  ('0110efdb-7b76-54b9-a9e1-ff7a07bd8b74'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0110efdb-7b76-54b9-a9e1-ff7a07bd8b74'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bb5a9043-600a-5dbb-8d52-400c3215c196'::uuid, NULL, E'The famous magazine tends to publish articles with alternative viewpoints.', NULL, NULL, NULL),
  ('0115c2a9-bd6c-560b-8ee7-5e46fac393a1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0115c2a9-bd6c-560b-8ee7-5e46fac393a1'::uuid, 1, NULL, TRUE, 0, NULL, E'Surgical Infections', E'Surgical site infections are caused by bacteria that get in through incisions made during surgery. They threaten the lives of millions of patients each year and contribute to the spread of antibiotic resistance. In low- and middle-income countries, 11% of patients who undergo surgery are infected in the process.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('01175022-99aa-5f10-a7df-cdf6c6db4104'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '01175022-99aa-5f10-a7df-cdf6c6db4104'::uuid, 1, NULL, TRUE, 0, NULL, E'Fossil Fuel', E'But look beyond fossil fuels for the most intriguing trends. One is that the energy intensity of the world economy -- the amount of energy it takes to produce one dollar''s {{1}} of income -- keeps falling, at a rate of about 2 percent. What this means is that even without any change in the {{2}} shares of fossil-based and fossil-free sources in the world''s energy mix, we could have 2 percent annual economic growth without increasing carbon emissions from energy use. Of course that is not enough to {{3}} climate change and we need more economic growth than that. It is {{4}} a stunning number, which refutes the claim by some environmentalists that permanent economic growth is fundamentally incompatible {{5}} finite physical resources.', NULL, NULL, NULL, E'1.worth, 2.relative, 3.address, 4.nonetheless, 5.with', NULL, NULL),
  ('01191116-da1b-5835-9dde-050e2dac53c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '01191116-da1b-5835-9dde-050e2dac53c6'::uuid, 1, NULL, TRUE, 0, NULL, E'Sexual Selection', E'Usually, the female of the species invests more in parenting. Females of many species choose their mates based on certain characteristics, such as large canine teeth in a male baboon or flashy tail feathers on a peacock, which in turn means those traits will be passed on to their male offspring. Biologists call this process sexual selection, which is related to natural selection.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('011b4f83-3afb-55a7-b8c7-26c1e2309735'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '011b4f83-3afb-55a7-b8c7-26c1e2309735'::uuid, 1, NULL, TRUE, 0, NULL, E'Excessive Noise', NULL, NULL, NULL, NULL, E'2, 1, 4, 3', NULL, NULL),
  ('0120251d-20ed-5a0c-821a-038362f73f6f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0120251d-20ed-5a0c-821a-038362f73f6f'::uuid, 1, NULL, TRUE, 0, NULL, E'Ancient Footprint', E'Fossilized human footprints found in New Mexico’s White Sands National Park were almost certainly made more than 20,000 years ago, during the height of the last ice age, according to new research. The study, published on Thursday in Science, overthrows decades of thinking about when humans arrived in North America.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('0124f4bb-e9f1-5d1b-adc5-62e5908e0d34'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '0124f4bb-e9f1-5d1b-adc5-62e5908e0d34'::uuid, 1, NULL, TRUE, 0, NULL, E'Keeping Fit', E'A healthy diet is more important for keeping fit than exercise. To what extent do you agree with this statement? Give an example or personal experiences.', NULL, NULL, NULL, NULL, 200, 300),
