  ('0162461e-a365-535f-850b-ab3bb5d915a3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0162461e-a365-535f-850b-ab3bb5d915a3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2229264e-b7c2-543c-a469-bdb08f717c94'::uuid, NULL, E'In marketing, short-term thinking can lead to many problems.', NULL, NULL, NULL),
