  ('016e171c-ed6d-5f05-a925-84953dcc5717'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '016e171c-ed6d-5f05-a925-84953dcc5717'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b1ba1b0b-e711-5300-9767-a2e459e214b2'::uuid, NULL, E'Words inherently reflect and describe the culture from which they originate.', NULL, NULL, NULL),
  ('0171db82-c40f-5b8f-b20c-17f712a27f85'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0171db82-c40f-5b8f-b20c-17f712a27f85'::uuid, 1, NULL, TRUE, 0, NULL, E'Open Border', NULL, '9401c7a2-ff3b-51d3-b5f8-7ea752fd632f'::uuid, NULL, E'I believe our borders should be open. But if that is not politically acceptable for now, Europe should at least open up a legal route for people from developing countries to come work here. Over time, hopefully, we can move to a position where borders are completely open. Persuading sceptics won''t be easy. That''s why I think the argument for free migration has to be made at several levels: a principled case: it increases freedom and reduces injustice; a humanitarian case: it helps people much poorer than ourselves; an economic case: it makes us richer; and a pragmatic case: it is inevitable, so it is in everyone''s interests to make the best of it. Freedom of movement is not just a matter of human rights and international solidarity; it is in our self-interest. Opening our borders may seem unrealistic. But so too, once, did abolishing slavery or giving women the vote. Campaigning for people''s right to move freely is a noble cause for our time.', NULL, NULL, NULL),
  ('01797cf3-2f60-55a5-85f7-b4f126869a58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '01797cf3-2f60-55a5-85f7-b4f126869a58'::uuid, 1, NULL, TRUE, 0, NULL, E'Subjective and Objective', E'To understand how sharing affects a person’s subjective and objective knowledge, the researchers gave a group of students the opportunity to read and share a range of news articles. The students then had to rate their subjective knowledge of each article before completing three multiple-choice questions that assessed their objective knowledge.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('0183463c-7014-5022-928a-e08ad1353ec5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0183463c-7014-5022-928a-e08ad1353ec5'::uuid, 1, NULL, TRUE, 0, NULL, E'Microbe Reproduction', E'A microbe can either reproduce by dividing or it can conserve its energy and maintain only its most basic functions. One possibility is that in the unfavorable conditions under the South Pacific floor, the microbes could have been dividing very slowly over centuries. In this case, the microbes in the study may be the descendants of an even more distant past.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('018bbed6-9c73-5b15-9c2c-af2725a83e27'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '018bbed6-9c73-5b15-9c2c-af2725a83e27'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ebcaa2b3-ef41-581b-85b7-7616f6f2f189'::uuid, NULL, NULL, E'Roads should be clear so that traffic can move smoothly.', NULL, NULL),
  ('018ca82b-a101-5738-96cd-c4edee82be1a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '018ca82b-a101-5738-96cd-c4edee82be1a'::uuid, 1, NULL, TRUE, 0, NULL, E'Classroom Technology', E'Classroom technology can enhance teaching and learning by providing interactive and engaging experiences for students. It includes tools like smart boards, tablets, and online resources that can help students stay engaged and motivated. However, it also requires careful planning and implementation to ensure that it aligns with learning goals and supports student success.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('018e2332-94fa-5698-8b77-df51fc9d90ef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '018e2332-94fa-5698-8b77-df51fc9d90ef'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '99b055e6-1464-5f7f-bc41-e6f2c0a2a87e'::uuid, NULL, NULL, E'A balanced diet and regular exercise are necessary for good health.', NULL, NULL),
  ('01967155-aac5-5e91-b0b2-cbbc665c1f56'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '01967155-aac5-5e91-b0b2-cbbc665c1f56'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '646b189f-fcbc-5c15-856c-2e9aeb777c90'::uuid, NULL, E'In English, the first letters of the months of the year are always capitalized.', NULL, NULL, NULL),
  ('019be1ee-1c14-5b80-ba88-a42e019dfee9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '019be1ee-1c14-5b80-ba88-a42e019dfee9'::uuid, 1, NULL, TRUE, 0, NULL, E'Financial Investment', E'Financial investment is a crucial aspect of personal finance that allows individuals to grow their wealth over time. While it may seem complex, understanding the essentials of investment is essential for making informed decisions and achieving financial goals. Diversification is a fundamental principle of investment. Spreading your investments across different asset classes, such as stocks, bonds, real estate, and commodities, helps reduce risk. A diversified portfolio can cushion losses in one area with gains in another, providing stability. Risk tolerance is another key consideration. Assessing your risk tolerance helps determine the right investment strategy for you. Generally, younger investors with a longer investment horizon can afford to take on more risk, while older investors may prioritize capital preservation. Time horizon plays a significant role in investment decisions. Short-term goals, like buying a car, may be best suited for low-risk, liquid investments, while long-term goals, such as retirement, can benefit from higher-risk, higher-reward options that have time to recover from market fluctuations. Research and education are critical for successful investing. Stay informed about financial markets, investment products, and economic trends. Consider seeking advice from financial advisors or using online resources to expand your knowledge. Costs matter in investing. Be aware of fees associated with investments, such as management fees, commissions, and taxes. Minimizing these costs can significantly impact your overall returns. Finally, it''s crucial to have a clear investment strategy and stick to it. Avoid emotional reactions to market volatility, as impulsive decisions can lead to losses. Patience and discipline are key to achieving long-term financial success. In conclusion, financial investment is a powerful tool for building wealth and achieving financial goals. By diversifying, understanding your risk tolerance, considering your time horizon, staying informed, managing costs, and adhering to a well-defined strategy, you can make the most of your investment journey.', NULL, NULL, E'Financial investment is a crucial element of personal finance, requiring diversification, risk assessment, consideration of time horizon, ongoing education, cost management, and disciplined adherence to a well-defined strategy to achieve long-term financial goals and build wealth effectively.', NULL, 5, 75),
  ('019d6f29-310d-52cb-82df-0456c4d07ada'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '019d6f29-310d-52cb-82df-0456c4d07ada'::uuid, 1, NULL, TRUE, 0, NULL, E'Natural Habitats', NULL, '7e4a693d-67b0-55c1-8a39-48267fa3b324'::uuid, NULL, E'Imagine a world where the lush green canopies of the Amazon no longer teem with life, where the coral reefs are silent, bereft of their colorful denizens. Our planet''s natural habitats are in peril, and their preservation is imperative, not just for the flora and fauna that call them home, but for humanity itself. Each ecosystem plays a critical role in the delicate balance of nature. Forests act as the earth''s lungs, purifying the air we breathe, while oceans regulate the climate. The loss of these habitats leads to the extinction of species, each a thread in the intricate web of life. Once gone, these threads cannot be rewoven. As inheritors of the earth, the onus is on us, the educated youth, to be the vanguards of conservation. Simple actions like supporting sustainable products and reducing waste contribute to a larger collective effort. In safeguarding nature''s sanctuaries, we secure the future for generations to come.', NULL, NULL, NULL),
  ('01af2d74-e02b-54aa-ba4c-723db4ffdc7e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '01af2d74-e02b-54aa-ba4c-723db4ffdc7e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '18ce840a-e1fa-5ffc-8633-e5eddece38bc'::uuid, NULL, E'The required amount of sleep remains constant as adults age.', NULL, NULL, NULL),
  ('01b0ee80-215d-504d-a7e9-cf1a0c8704c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '01b0ee80-215d-504d-a7e9-cf1a0c8704c0'::uuid, 1, NULL, TRUE, 0, NULL, E'Baby Hearing', E'Most babies start developing their hearing while still in the womb, prompting some hopeful parents to play classical music to their pregnant bellies. Some research even suggests that infants are listening to adult speech as early as 10 weeks before birth, gathering the basic building blocks of their family''s native tongue.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('01ba7926-40e9-5f6d-8d8c-b64251519691'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '01ba7926-40e9-5f6d-8d8c-b64251519691'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b88e56ba-a69a-5adb-a8f9-a4e318134934'::uuid, NULL, NULL, E'Americans have typically defined the processes of plant growth in quantitative terms.', NULL, NULL),
  ('01bc399d-009b-57a4-831e-d1cb178aa926'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '01bc399d-009b-57a4-831e-d1cb178aa926'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd92b133c-191a-52ad-b30f-5f701a4d5b18'::uuid, NULL, NULL, E'This standard is easily attainable by most of the students.', NULL, NULL),
  ('01beb888-88b8-5d93-8d38-9ef31423004f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '01beb888-88b8-5d93-8d38-9ef31423004f'::uuid, 1, NULL, TRUE, 0, NULL, E'Italy', E'From the 14th to the 16th centuries, Italy experienced an amazing burst of creativity known as the Renaissance. This period was a rebirth of the arts, {{1}} inspiration from ancient Greek and Roman culture. Artists {{2}} with new ways in painting, sculpture, and building design, achieving incredible beauty and detail. Famous artists like Michelangelo made the Sistine Chapel come alive with huge, dramatic paintings. Raphael was known for his stunning paintings of the Madonna and portraits that showed perfect balance and depth. Art was {{3}} all over Italy, from Leonardo da Vinci''s dreamy oil paintings in Florence to Titian''s brilliant use of color in Venice. This was a time of competition between Italian city-states, each trying to outdo the others in artistic brilliance. The Renaissance was a golden age for art, leaving a {{4}} impact on Western culture with its unforgettable masterpieces.', NULL, NULL, NULL, E'1.drawing, 2.experimented, 3.booming, 4.lasting', NULL, NULL),
  ('01bf4b9c-9658-51f1-9b89-7a378ee507d9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '01bf4b9c-9658-51f1-9b89-7a378ee507d9'::uuid, 1, NULL, TRUE, 0, NULL, E'Closure Activities', E'Closure activities allow participants to consolidate learning, say goodbye to group mates, and attend to any unfinished business prior to the ending of the group experience. Generally, these activities involve some reflection upon what has been learned or accomplished during the preceding time together and a sharing of those thoughts or insights with other participants.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('01c18989-253e-5148-ace5-97376b83dcd3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '01c18989-253e-5148-ace5-97376b83dcd3'::uuid, 1, NULL, TRUE, 0, NULL, E'Madagascar', E'Scientists have recommended actions the government of Madagascar''s recently elected president, Andry Rajoelina should take to turn around the precipitous decline of biodiversity and help put Madagascar on a trajectory towards sustainable growth. Madagascar''s protected areas, some of the most important for biodiversity in the world, have suffered terribly in recent years from illegal mining, logging, and collection of threatened species for the pet trade.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('01c41099-fef0-5b6d-961a-c46e9f73c172'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '01c41099-fef0-5b6d-961a-c46e9f73c172'::uuid, 1, NULL, TRUE, 0, NULL, E'Pilot', NULL, NULL, NULL, NULL, E'1, 3, 4, 2', NULL, NULL),
  ('01c60160-2ab1-54d5-a5bb-11031fa65af2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '01c60160-2ab1-54d5-a5bb-11031fa65af2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'bf89a3bb-f071-558b-99cd-736878dcc201'::uuid, NULL, NULL, E'The campaign is designed to increase public awareness of the issue.', NULL, NULL),
  ('01d40473-c12c-5357-aad7-d1fa137e881b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '01d40473-c12c-5357-aad7-d1fa137e881b'::uuid, 1, NULL, TRUE, 0, NULL, E'Royal Agricultural Society', E'The evolution of the RAS (Royal Agricultural Society) fits into the wider Western trend of promoting nationalism, progress and technology through exhibitory venues, which first became popular in the 1850s. Various types of fairs, from local agricultural shows to Worlds Fairs, were used as instruments of hegemony to support imperialism, to promote burgeoning capitalist endeavors, and to shape class identities, social spaces and public spaces. Visual culture and the art of display became essential in defining aspects of national distinction. Colonial nations in particular, such as Canada and Australia, were attempting to develop distinct national identities to differentiate themselves from British imperial power. Agricultural fairs in North America originated at the beginning of the nineteenth century and were devoted to educating practicing framers in ways of improving their cultivation of livestock and crops through the use of various technologies.\nIn 1822, the RAS was created on the premise that was a dire need in Australia for the development of improved farming skills to better support growing urban populations and export markets. Organizations based on agricultural improvement, which were popular in Britain, provided camaraderie as well as political and financial support for their members. Once transferred to the colonies, in this case Australia, they played an integral part in converting and organizing land for colonial purposes.', NULL, NULL, E'With the evolution of the RAS fitting into the wider Western trend of promoting nationalism, progress, and technology through exhibiting venues in the 1850s, various types of fairs were used to support imperialism, burgeoning capitalism and class identities in colonial nations, and then the RAS was created in 1822 in Australia to better support urbanization and export markets.', NULL, 5, 75),
  ('01d7d63a-9213-544e-befe-8e3eb04765d9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '01d7d63a-9213-544e-befe-8e3eb04765d9'::uuid, 1, NULL, TRUE, 0, NULL, E'Reptiles', E'Around 250 million years ago, 700 species of reptiles closely related to the modern-day crocodile roamed the earth, now new research reveals how a complex interplay between climate change, species competition and habitat can help explain why just 23 species of crocodile survive today.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('01e261b7-85be-5dd7-a2fe-a039cf296afa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '01e261b7-85be-5dd7-a2fe-a039cf296afa'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3499c2e3-bbc0-53aa-83da-9f15e6358376'::uuid, NULL, NULL, E'The professor improvised a poem in the class.', NULL, NULL),
  ('01eaf38e-c96f-512a-8f37-253c73ce0367'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '01eaf38e-c96f-512a-8f37-253c73ce0367'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1bf87257-1eda-5ce5-b9b3-d903056f6529'::uuid, NULL, NULL, E'Many graduates have already found a decent job by now.', NULL, NULL),
  ('01ef1020-2125-594f-baaf-2dde033d4aac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '01ef1020-2125-594f-baaf-2dde033d4aac'::uuid, 1, NULL, TRUE, 0, NULL, E'Milky Way System', E'Stars and the material between them are almost always found in gigantic {{1}} systems called galaxies. Our own galaxy, the Milky Way System, happens to be one of the two {{2}} systems in the Local Group of two dozen or so galaxies. The other is the Andromeda galaxy; it {{3}} more than one hundred thousand light-years from one end to the other, and it is {{4}} about two million light-years distant from us.', NULL, NULL, NULL, E'1.stellar, 2.largest, 3.stretches, 4.located', NULL, NULL),
  ('01f1f693-21ca-5c84-92ae-7d3482ae5f71'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '01f1f693-21ca-5c84-92ae-7d3482ae5f71'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd4fb7060-087e-54ba-b79a-41cb1bf45e17'::uuid, NULL, E'Doctor Green''s office has been moved to the second floor of the building.', NULL, NULL, NULL),
  ('01f39eb2-d3ce-522e-a27e-5dfaff649764'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', '01f39eb2-d3ce-522e-a27e-5dfaff649764'::uuid, 1, NULL, TRUE, 0, NULL, E'Drums', E'Drums can be divided according to shape. Some of the types are tubular vessel and frame drums. One of the most common tubular drums is the long drum. A lot of long drums are cylindrical. They have the same diameter from top to bottom, like this polynesian drum. This drum was carved from a length of tree trunks and has a single skinhead for vessel drums. We have the kettle drum. Kettle drums have a single membrane stretched over a pot or vessel body vessel. Drums come in a variety of sizes, from the very large drums of africa to the very compact and portable drums, like this one from hawaii. The third type I want you to see is the frame drum. A frame drum consists of one or two membranes stretched over a simple frame, which is usually made of thin.\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '8f512457-08f8-50d2-ae90-bf2f1a90897d'::uuid, NULL, NULL, E'wood', NULL, NULL),
  ('01f84277-e4ab-5100-922b-74834346f4cb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '01f84277-e4ab-5100-922b-74834346f4cb'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '04b8b7e2-9558-5cbf-bd05-3405471bd08b'::uuid, NULL, E'The tension between the two countries is likely to remain.', NULL, NULL, NULL),
  ('020104cf-5bb3-532d-8f82-49e83fa228e7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '020104cf-5bb3-532d-8f82-49e83fa228e7'::uuid, 1, NULL, TRUE, 0, NULL, E'Animal Laughing', E'If you have a dog, you may have noticed that sometimes it seems to be smiling. But, of course, we know that dogs don''t really smile. That''s just how dog mouths appear sometimes, right? Perhaps, but according to neuroscientist Jaak Panksepp of Bowling Green State University, some animals do laugh.\nWhen chimps play, Panksepp notes, they make panting sounds that could be a form of laughter. Even rats have a way of laughing - by chirping when they''re playing with each other or being tickled by humans.\nBut, if animals do in fact laugh, what are they laughing at? Scientists have long known that for many animals, life isn''t all about hunting, foraging, fighting, and sleeping. Young animals also play a lot, which suggests that animal laughter is related to playful joy.\n\nWhen are the animals most likely to laugh according to the scientists?', '327593c4-b5be-5a50-904f-c690fed42f58'::uuid, NULL, NULL, E'Playing with their companions.', NULL, NULL),
  ('0202066f-58e8-5641-aad1-09ed9ab577cd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', '0202066f-58e8-5641-aad1-09ed9ab577cd'::uuid, 1, NULL, TRUE, 0, NULL, E'Persistent Back Pain', E'People with persistent back pain or persistent headaches are twice as likely to suffer from both disorders, a new study from the University of Warwick has revealed.\nThe results, published in the Journal of Headache and Pain, suggest an association between the two types of pain that could point to a shared treatment for both.\nThe researchers from Warwick Medical School who are funded by the National Institute for Health Research (NIHR) led a systematic review of fourteen studies with a total of 460,195 participants that attempt to quantify the association between persistent headaches and persistent low back pain. They found an association between having persistent low back pain and having persistent (chronic) headaches, with patients experiencing one typically being twice as likely to experience the other compared to people without either headaches or back pain. The association is also stronger for people affected by migraine.\nThe researchers focused on people with chronic headache disorders, those who will have had headaches on most days for at least three months, and people with persistent low back pain that experience that pain day after day. These are two very common disorders that are leading causes of disability worldwide.\nAround one in five people have persistent low back pain and one in 30 have chronic headaches. The researchers estimate that just over one in 100 people (or well over half a million people) in the UK have both.\n\nWhat are the main findings of the study?', NULL, NULL, NULL, E'In the UK, one in 100 people have both persistent back pain and persistent headaches.\nThere is a link between persistent back pain and persistent headache.', NULL, NULL),
  ('0203091a-54de-5b00-9677-87a243edb84b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0203091a-54de-5b00-9677-87a243edb84b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the habitat of camels?', '32975df3-e020-5d30-91a4-41b03ac37766'::uuid, NULL, NULL, E'Desert', NULL, NULL),
  ('02049234-a1e2-5459-b8c1-0c7ea5b11295'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '02049234-a1e2-5459-b8c1-0c7ea5b11295'::uuid, 1, NULL, TRUE, 0, NULL, E'Cell Template', E'One of the great promises of stem-cell biology is to use a patient''s own cells as a template to build a real, working organ or tissue in the lab. One prime example: a {{1}} for diabetes by turning stem cells into working pancreatic beta cells, which release insulin.\n"The existing beta cells that our lab and others had created were 90 percent of the way there. But 90 percent still means not functional." Ron Evans, a molecular {{2}} at the Salk Institute.\nEvans compares the stem-cell-derived beta cells they first made to a darkened room. "If you walk into that room, there may be everything in it that you need to be a complete room, with furniture and chairs and everything else. But it''s dark. And the key is: what do you need to turn on the light?"\nThat light switch, Evans discovered, is a gene—called estrogen-related receptor gamma. Flip it on, and it {{3}} a genetic circuit that ramps up mitochondria production, powers up the cell, and endows the almost-functional beta cells with the ability to sense glucose and release insulin in {{4}} .\nEvans''s team recently used that trick to transform stem cells into beta cells that worked just like they would in a healthy pancreas. When they transplanted those cells into mice with a mouse version of diabetes, blood glucose fell to normal levels in half the rodents. The results are in the journal Cell Metabolism.\nNext, Evans says he''ll replicate the test in diabetic primates. "Primates get diabetes in a fashion that''s very similar to people. So if it works in a primate, very high probability that it''s going to work in people." If it does, we might someday replace a shot of insulin with a shot of cells.', NULL, NULL, NULL, E'1.treatment, 2.biologist, 3.activates, 4.response', NULL, NULL),
  ('0204932b-f603-564b-ac3c-28a10579109e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0204932b-f603-564b-ac3c-28a10579109e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e25d96d7-974d-5d7b-8fb9-c1bae7de8645'::uuid, NULL, NULL, E'The election of president is held once every four years.', NULL, NULL),
  ('0216dfad-7d9f-53ae-9c7d-4fd949bd511e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0216dfad-7d9f-53ae-9c7d-4fd949bd511e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a6820c38-fda9-5685-b423-2678685fe602'::uuid, NULL, NULL, E'Philosophers use logic to deeply understand why people do things.', NULL, NULL),
  ('021bcd03-a430-5f37-b3b5-ea83914a8a23'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '021bcd03-a430-5f37-b3b5-ea83914a8a23'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c280f5b5-bad4-53d8-927a-a751545c53bd'::uuid, NULL, E'She was disappointed not to be accepted into the netball club.', NULL, NULL, NULL),
  ('0224ef40-709a-5d78-b608-1c30c8d6f871'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0224ef40-709a-5d78-b608-1c30c8d6f871'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which word beginning with C is a synonym of idea?', 'f33a4d73-b803-5b16-9274-415c83fa87c1'::uuid, NULL, NULL, E'Concept', NULL, NULL),
  ('0226c04e-a400-5456-803b-f8089b8198ba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '0226c04e-a400-5456-803b-f8089b8198ba'::uuid, 1, NULL, TRUE, 0, NULL, E'Romans', E'The Romans glorified the {{1}} shown in the arena, but {{2}} the events and degraded the participants. Mosaic pictures of executions and combats, {{3}} violent to our eyes, were displayed in the public rooms and even dining rooms in the homes of wealthy Romans. How can the viewer today possibly understand such images? Until fairly recently, modern authors writing about the arena minimized its significance and {{4}} the institutionalized violence as a sideline to Roman history. The {{5}} was also to view the events through our own eyes and to see them as pitiful or horrifying, although to most Romans empathy with victims of the arena was inconceivable. In the past few decades, however, scholars have started to analyze the complex motivations for deadly public entertainments and contradictory views of gladiators as despised, yet beloved hero-slaves.', NULL, NULL, NULL, E'1.bravery, 2.trivialized, 3.graphically, 4.represented, 5.tendency', NULL, NULL),
  ('022f392a-dba7-5426-96d4-6acd6c25983f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '022f392a-dba7-5426-96d4-6acd6c25983f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '696cfd7b-e56e-585e-9f17-15c38be2b6a9'::uuid, NULL, E'The artist has gained fame for creating abstract art throughout his career.', NULL, NULL, NULL),
  ('022f3d1d-5739-5b3a-8657-e43a97c2dea2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '022f3d1d-5739-5b3a-8657-e43a97c2dea2'::uuid, 1, NULL, TRUE, 0, NULL, E'Importance of Water', E'Water is at the core of sustainable development. Water resources, and the range of services they provide, underpin poverty reduction, economic growth and environmental sustainability. From food and energy security to human and environmental health, water contributes to improvements in social well-being and inclusive growth, affecting the livelihoods of billions.\nIn a sustainable world that is achievable in the near future, water and related resources are managed in support of human well-being and ecosystem integrity in a robust economy. Sufficient and safe water is made available to meet every person''s basic needs, with healthy lifestyles and behaviors easily upheld through reliable and affordable water supply and sanitation services, in turn supported by equitably extended and efficiently managed infrastructure. Water resources management, infrastructure and service delivery are sustainably financed.\nWater is duly valued in all its forms, with wastewater treated as a resource that avails energy, nutrients and freshwater for reuse. Human settlements develop in harmony with the natural water cycle and the ecosystems that support it, with measures in place that reduce vulnerability and improve resilience to water-related disasters. Integrated approaches to water resources development, management and use and to human rights are the norm. Water is governed in a participatory way that draws on the full potential of women and men as professionals and citizens, guided by a number of able and knowledgeable organizations, within a just and transparent institutional framework.', NULL, NULL, E'Water is at the core of sustainable development, as water resources, and the range of services they provide underpins poverty reduction, economic growth, and environmental sustainability, while water resources are managed in support of human well-being and ecosystem integrity, so sufficient and safe water is made available to meet every person’s basic needs, and water is duly valued in all its forms, with wastewater treated as a resource.', NULL, 5, 75),
  ('023ac686-5e28-58a0-99f4-822dd2a86f25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '023ac686-5e28-58a0-99f4-822dd2a86f25'::uuid, 1, NULL, TRUE, 0, NULL, E'Former Civilization', NULL, 'd1c49bdd-c78b-587b-9075-72b1455b2d00'::uuid, NULL, E'The first thing I want to argue is that the former civilization is running into a pretty profound crisis in its relationships with the rest of nature, which we have been depending on for survival and for flourishing. And this is the most widely and well-recognized fact in relation to climate change and greenhouse gas emissions. Because it''s interlocked with a number of other crises as the crisis endangers access to fresh water and to food. Biodiversity loss on a huge scale, and associated problems of human inequality are also possible to happen. All those together have to be looked at as an interconnected set of really deep, profound crises.', NULL, NULL, NULL),
  ('023cd3b6-ad17-571b-ab3a-7c02bf1ef7f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '023cd3b6-ad17-571b-ab3a-7c02bf1ef7f9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f830cfd0-f96b-5dd6-a44f-2b6eb7ce5001'::uuid, NULL, NULL, E'The facility is used to record the progress of each experiment.', NULL, NULL),
  ('023d5a08-4431-5ec0-a01f-b1d96feb3f3f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '023d5a08-4431-5ec0-a01f-b1d96feb3f3f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1b1d898f-8a0e-5d7a-8b98-6e9a9fc91156'::uuid, NULL, NULL, E'A lack of sleep can increase the chance of some illnesses.', NULL, NULL),
  ('0244cccd-0a10-5000-b614-39a0fe2e6b18'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0244cccd-0a10-5000-b614-39a0fe2e6b18'::uuid, 1, NULL, TRUE, 0, NULL, E'Introverts'' Thinking', E'As introverts are thinking, they reach back into long-term memory to locate information. An introvert will often compare old and new experiences when making a decision, which slows the processing down but leads to carefully thought-out decisions. This means that introverts have an active dialogue with themselves and usually walk around with many thoughts in their minds.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('0246915f-b814-5668-ae96-8ae78d431402'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0246915f-b814-5668-ae96-8ae78d431402'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd8ae1f90-705e-5d62-ad0b-7a2d1605456a'::uuid, NULL, NULL, E'Students are encouraged to take part in their study as well as games.', NULL, NULL),
  ('024f2370-ef69-5918-be02-4a315d58263e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '024f2370-ef69-5918-be02-4a315d58263e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7fe0a552-9cf7-5fcb-a9c5-6c2a9cfdaacc'::uuid, NULL, E'Acupuncture is part of Chinese medicine''s holistic approach to healing.', NULL, NULL, NULL),
  ('024fcfd5-e2b4-56cc-afc8-e2e4a762f847'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '024fcfd5-e2b4-56cc-afc8-e2e4a762f847'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '571969f8-b2d9-506d-8581-cad2fe5989ed'::uuid, NULL, E'The content of the course depends on what the students would like to study.', NULL, NULL, NULL),
  ('025c64a5-96bf-5cce-92b2-73486b100126'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '025c64a5-96bf-5cce-92b2-73486b100126'::uuid, 1, NULL, TRUE, 0, NULL, E'University Workshops', E'This time the University is running a series of workshops for final year students on how to do well in interviews. These sessions will help participants prepare effectively for and perform at their best during later job interviews. The workshop tutors have an excellent record of success in helping students acquire the positions they desire.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('025fa2e2-6d13-5c38-9b3c-4fc81e46009f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '025fa2e2-6d13-5c38-9b3c-4fc81e46009f'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-R', E'Influenced by the view of some twentieth-century feminists that women''s position within the family is one of the central factors determining women''s social position, some historians have underestimated the significance of the woman suffrage movement. These historians contend that nineteenth-century suffragist was less radical and, hence, less important than, for example, the moral reform movement or domestic feminism—two nineteenth-century movements in which women struggled for more power and autonomy within the family. True, by emphasizing these struggles, such historians have broadened the conventional view of nineteenth-century feminism, but they do a historical disservice to suffragism. Nineteenth-century feminists and anti-feminist alike perceived the suffragists'' demand for enfranchisement as the most radical element in women''s protest, in part because suffragists were demanding power that was not based on the institution of the family, women''s traditional sphere. When evaluating nineteenth-century feminism as a social force, contemporary historians should consider the perceptions of actual participants in the historical events.\n\nThe author asserts that the historians discussed in the passage have', NULL, NULL, NULL, E'expanded the conventional view of nineteenth-century feminism', NULL, NULL),
  ('0260bb1e-1e7f-58c3-94e4-1f72d115d29d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0260bb1e-1e7f-58c3-94e4-1f72d115d29d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for the state of being equal, especially in status, rights, and opportunities?', '486e7a4e-fa37-5100-8086-ed5567e8d2a6'::uuid, NULL, NULL, E'Equality', NULL, NULL),
  ('02667384-412f-5c56-ab01-5d5d250d907f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '02667384-412f-5c56-ab01-5d5d250d907f'::uuid, 1, NULL, TRUE, 0, NULL, E'Missing Pages', E'You borrowed a book from the university library. But while reading it, you notice that two pages have been torn out, but you didn''t do it. What do you say to the librarian when you return the book?', 'f2816e98-eeab-5672-a3e3-9655bce107c5'::uuid, NULL, E'Respected librarian, I hope you are doing well.\nI would like to discuss an issue we have encountered with this library book I borrowed.\nIt appears that two pages inside the book are torn out, and I did not tear them.\nI would appreciate your opinion on this matter. Thank you for your consideration.', NULL, NULL, NULL),
  ('0268aea2-ef0a-53d5-8b7a-4370a393a64b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0268aea2-ef0a-53d5-8b7a-4370a393a64b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '350b29b8-b04c-570f-8dd7-eacbf39284d9'::uuid, NULL, NULL, E'The field of journalism has been seeing job decline for decades.', NULL, NULL),
  ('026d5c66-ee13-5297-99df-d2c2558e433e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '026d5c66-ee13-5297-99df-d2c2558e433e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '55e895ec-b4f9-5645-bfb6-48528620ac1a'::uuid, NULL, NULL, E'Only few students do not prefer working with other peers.', NULL, NULL),
  ('026dcaa1-de77-574c-a787-0bc0ba31d555'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '026dcaa1-de77-574c-a787-0bc0ba31d555'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '093ade18-ecda-5866-a92f-58d9498a9c06'::uuid, NULL, E'In eighteen eighty, cycling became a major phenomenon in Europe.', NULL, NULL, NULL),
  ('0271d53e-79af-54e1-87b0-39230013df09'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '0271d53e-79af-54e1-87b0-39230013df09'::uuid, 1, NULL, TRUE, 0, NULL, E'Bees', E'Bees have been around for over 100 million years, and in that time they''ve found a niche in almost every part of the globe. There are over 20,000 species of bee, but thanks to our close relationship with honeybees, most well-known bee facts relate to this hive-dwelling species alone.\nIn fact, around half of the planet''s bee species are solitary, most don''t make or store honey, and they can look very different to the yellow-and-black bees we''re familiar with. It''s a sad fact that these wonderfully adaptive insects, who''ve survived a whole host of changes since they first appeared on our planet, are now under serious threat. With around one-third of bee species in decline, it''s a critical time for us to do everything we can to support them.\nIt''s easy to see why the loss of bees would be catastrophic – we couldn''t survive without pollinators – but their extinction would have an impact well beyond their role in providing the food we eat. Bees and other pollinators are part of our planet''s delicately balanced ecosystem. If a bee species dies out, the plants and trees that depend on it are affected too; in turn the creatures who feed or live on those plants are affected and so on up the food chain.', NULL, NULL, NULL, NULL, 5, 75),
  ('0273aa3c-a1ff-54f4-821b-5fb4fefaffce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0273aa3c-a1ff-54f4-821b-5fb4fefaffce'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd7fdf192-0d8f-5d94-9a39-fdae9a5b64b7'::uuid, NULL, E'You have to submit projects by the end of this week.', NULL, NULL, NULL),
  ('0275211e-bb59-58a8-bee3-8e0905b2d537'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0275211e-bb59-58a8-bee3-8e0905b2d537'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What does human and animal skeleton consist of?', 'a4b8b0cf-2428-52f8-bc64-114f2d9a3b9d'::uuid, NULL, NULL, E'Bone / bones', NULL, NULL),
  ('0275ff77-cd02-5809-9996-82a025f6376b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '0275ff77-cd02-5809-9996-82a025f6376b'::uuid, 1, NULL, TRUE, 0, NULL, E'Chemistry', E'Chemistry is an extremely important topic in physiology. Most physiological processes occur as the {{1}} of chemical changes that occur within the body. These changes include the influx/efflux of ions across a neuron''s membrane, causing a {{2}} to pass from one end to the other. Other examples include the {{3}} of oxygen in the blood by a protein as it passes through the lungs for {{4}} throughout the body.', NULL, NULL, NULL, E'1.result, 2.signal, 3.storage, 4.usage', NULL, NULL),
  ('0276e97d-ca79-50ad-83d8-ecefc2dc6d6b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '0276e97d-ca79-50ad-83d8-ecefc2dc6d6b'::uuid, 1, NULL, TRUE, 0, NULL, E'Anthropologists', E'It is commonly said by anthropologists that primitive man is {{1}} individual and more completely moulded by his {{3}} than civilized man. This contains an element of truth. Simpler societies are more {{4}} , in the sense that they call for, and provide opportunities for, a far {{5}} diversity of {{6}} skills and occupations than the more complex and {{7}} societies. Increasing individualization in this sense is a necessary product of modern advanced society, and runs through all its activities from top to bottom. But it would be a serious error to set up an antithesis between this process of individualization and the growing strength and cohesion of society.', NULL, NULL, NULL, E'1.less, 2.society, 3.uniform, 4.smaller, 5.individual, 6.advanced', NULL, NULL),
  ('027981e8-6011-5239-b20d-9d9e6bda8024'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '027981e8-6011-5239-b20d-9d9e6bda8024'::uuid, 1, NULL, TRUE, 0, NULL, E'Technological Change', E'With today''s incredible {{1}} of technological change a lot of age-old human skills may be getting left behind or {{2}} out. It''s not just that if you buy a laptop today it''s obsolete within {{3}} than a year and the rest of the world has moved on; it''s more that, as workers get more expensive and equipment gets cheaper, companies are spending more on machines rather than people. Fewer people, therefore, are being {{4}} in necessary skills.', NULL, NULL, NULL, E'1.rate, 2.dying, 3.less, 4.trained', NULL, NULL),
  ('027b556b-37f9-560b-b6d0-44e34a7576f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '027b556b-37f9-560b-b6d0-44e34a7576f9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'bf34acfe-73f4-5d35-ad4a-905d38f788f2'::uuid, NULL, NULL, E'The conference will be held on Thursday morning.', NULL, NULL),
  ('027b6f32-44c4-5cf7-86e2-e3b3f9c00c89'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '027b6f32-44c4-5cf7-86e2-e3b3f9c00c89'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '51771abf-9b92-58ff-b468-6b2c7424f099'::uuid, NULL, E'Suggested by her mother, she will take a diploma in management studies.', NULL, NULL, NULL),
  ('02911e1e-8d69-5be6-b79e-c1ba67ecc193'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '02911e1e-8d69-5be6-b79e-c1ba67ecc193'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8bb34cba-302e-5e0a-a87a-ff5d25a1ae98'::uuid, NULL, NULL, E'They have been struggling since last year to make their services paid.', NULL, NULL),
  ('02983bbd-8374-5e18-a761-50d11d1cbd2a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '02983bbd-8374-5e18-a761-50d11d1cbd2a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '665651a8-9464-55b3-9f43-a457ac02a412'::uuid, NULL, NULL, E'Let me know if anyone struggles in the lab.', NULL, NULL),
  ('029a58f8-da07-560c-94f0-d3174a14a936'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '029a58f8-da07-560c-94f0-d3174a14a936'::uuid, 1, NULL, TRUE, 0, NULL, E'Tornadoes', E'As the climate {{1}} , it''s putting more heat into the atmosphere and creating more energy that can {{2}} tornadoes. Large December tornadoes are rare because December tends to be cool — but the U.S. is experiencing unusual warmth this year, including over the Gulf of Mexico, where the heat that fuels tornado-forming thunderstorms {{3}} .', NULL, NULL, NULL, E'1.warms, 2.feed, 3.originates', NULL, NULL),
  ('02a25d6a-f272-5a78-9550-04889888454f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '02a25d6a-f272-5a78-9550-04889888454f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7d4f728c-290d-5f06-afe0-8b2d3df50365'::uuid, NULL, E'If the doctor calls while I''m out, please leave a message.', NULL, NULL, NULL),
  ('02a5486f-728b-5ff5-9024-8375ff0971c3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '02a5486f-728b-5ff5-9024-8375ff0971c3'::uuid, 1, NULL, TRUE, 0, NULL, E'Heat Pumps', E'When you think about cooling a hot building, you probably don''t think of heat pumps. In fact, you likely think of using an air conditioner instead. But as it turns out, a heat pump can both heat and cool, and in some applications, it''s preferred to separate heating and cooling systems.\nSimply put, a heat pump is a device that uses a small amount of energy to move heat from one location to another. Heat pumps are typically used to pull heat out of the air or ground to heat a home or office building, but they can be reversed to cool a building. In a way, if you know how an air conditioner works, then you already know a lot about how a heat pump works. This is because heat pumps and air conditioners operate in very similar ways.\nOne of the biggest advantages of a heat pump over a standard heating, ventilating and air conditioning (HVAC) unit is that there''s no need to install separate systems to heat and cool your home. Heat pumps also work extremely efficiently, because they simply transfer heat rather than burn fuel to create it. This makes them a little greener than a gas-burning furnace.\nThere are many kinds of heat pumps, but they all operate on the same basic principle: heat transfer. This means that rather than burning fuel to create heat, the device moves heat from one place to another. There''s a key to making this all happen. According to thermodynamics, heat naturally flows from high temperature areas to those with lower temperatures.', NULL, NULL, NULL, NULL, 5, 75),
  ('02a88fd7-cca5-5063-b382-30554c9e9e9a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '02a88fd7-cca5-5063-b382-30554c9e9e9a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b5e6238d-ecce-5098-9683-8e983cbd6a45'::uuid, NULL, E'Medical books and journals have been moved to the second floor.', NULL, NULL, NULL),
  ('02a9f26e-e541-583c-b07a-0eefac3f9bfd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '02a9f26e-e541-583c-b07a-0eefac3f9bfd'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c8fd7dff-f31b-52ab-958c-97598ba0b870'::uuid, NULL, E'We need to encourage children to take the responsibility for their choice.', NULL, NULL, NULL),
  ('02b006f5-63ed-5578-a899-7f75d349b748'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '02b006f5-63ed-5578-a899-7f75d349b748'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '85011ca2-f6e7-5da8-9a03-f3bacf25d6f0'::uuid, NULL, NULL, E'Sympathy is a feeling of sorrow for someone who is not happy.', NULL, NULL),
  ('02b04148-eec8-5165-91ab-c2c4471d00cb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '02b04148-eec8-5165-91ab-c2c4471d00cb'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '007eb8f2-cc9c-5b85-8afb-5db8219e9b5c'::uuid, NULL, NULL, E'Technology is no longer a simple tool that we can control.', NULL, NULL),
  ('02b0d8ef-eb3a-5b54-b013-c65e74468334'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '02b0d8ef-eb3a-5b54-b013-c65e74468334'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the adjective opposite to ''rural''?', '92d6c61b-84ea-5f63-bbd9-4833457c422a'::uuid, NULL, NULL, E'Urban', NULL, NULL),
  ('02b37cbc-377b-53e5-9326-b38ff97d1037'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '02b37cbc-377b-53e5-9326-b38ff97d1037'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '46eec6c7-1e90-5f13-b538-8e5a8f091a49'::uuid, NULL, NULL, E'The trip has been extended to include a few other events.', NULL, NULL),
  ('02b5b78e-e06a-5f71-904c-acb4d2973517'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '02b5b78e-e06a-5f71-904c-acb4d2973517'::uuid, 1, NULL, TRUE, 0, NULL, E'Information Technology', E'The emergence of information technology has created new products, processes and distribution systems. New products include the computer, the Internet and digital TV; new processes include Internet banking, automated inventory control and automated teller machines; and new distribution systems include cable and satellite TV.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('02b9cadf-95c9-5755-abd6-2f5ac7b3b5b6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '02b9cadf-95c9-5755-abd6-2f5ac7b3b5b6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ed25d285-964d-5ba1-878d-f926ee5d096b'::uuid, NULL, NULL, E'Doing things and just learning about them in school are different.', NULL, NULL),
  ('02bb5773-a7c9-5754-a6af-3309082746c9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '02bb5773-a7c9-5754-a6af-3309082746c9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'aef2e3c2-a169-5afb-8d8f-033f611dc01f'::uuid, NULL, E'The light can be seen as waves or particles.', NULL, NULL, NULL),
  ('02bb9c45-468a-56e9-9a25-2fb4b70d6ffd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '02bb9c45-468a-56e9-9a25-2fb4b70d6ffd'::uuid, 1, NULL, TRUE, 0, NULL, E'Immune Vigilance', E'The problem is that increased immune vigilance has a side effect: allergies. Our speculation is that this is some kind of trade-off. In the past you needed to resist some kind of pathogen, and the trade-off or sacrifice you have to make is increased responsiveness to nonpathogenic allergens. So next time some of you get the springtime sniffles, blame your distant ancestor — the one with the heavy brow ridge.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('02c3e60a-884c-504c-a3b0-e229d9cc4c25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '02c3e60a-884c-504c-a3b0-e229d9cc4c25'::uuid, 1, NULL, TRUE, 0, NULL, E'Thunder', E'Thunder is the sound caused by a lightning discharge. Lightning heats the air in its path and {{1}} a large over-pressure of the air within its channel. The channel expands supersonically into the surrounding air as a shock wave and creates an {{2}} signal that is heard as thunder. The thunder heard after a flash to the ground is actually produced by the return stroke that follows the path {{3}} by the initial stroke.', NULL, NULL, NULL, E'1.causes, 2.acoustic, 3.forged', NULL, NULL),
  ('02c5aa7e-9f99-5846-a382-60c9991a85db'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '02c5aa7e-9f99-5846-a382-60c9991a85db'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '34e9d36b-babc-5697-8237-878cf2eddb9f'::uuid, NULL, NULL, E'More graduate training is often needed after the university study is finished.', NULL, NULL),
  ('02cc8e64-8629-5bf2-b9a7-2d46b8a5805b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '02cc8e64-8629-5bf2-b9a7-2d46b8a5805b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a woman whose husband has died and who has not married again?', '3e04606a-c565-5905-be40-710515b6739a'::uuid, NULL, NULL, E'Widow', NULL, NULL),
  ('02cd469b-4b93-50af-a8eb-7264ef163baf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '02cd469b-4b93-50af-a8eb-7264ef163baf'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4bfaa04f-12a1-5a20-8361-c6adb0f7b41f'::uuid, NULL, E'Basketball was created in eighteen ninety one by a physician and physical education instructor.', NULL, NULL, NULL),
  ('02ced75f-fbb1-500c-b271-15f0931f485a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '02ced75f-fbb1-500c-b271-15f0931f485a'::uuid, 1, NULL, TRUE, 0, NULL, E'Children''s Dream', E'As a child, you might dream one day of becoming an astronaut and, the next day, of becoming a ballet dancer — the possibilities are endless. Eventually, this wealth of choice is whittled down by external circumstances and internal interests. Similarly, precursor cells in early embryos make a series of stepwise ''decisions'' governed by external forces and internal factors to generate the diverse array of cell types present in adult organisms.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('02cee900-ec8d-51a6-b06c-7153317e8af9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '02cee900-ec8d-51a6-b06c-7153317e8af9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bf6e2ffe-d198-5c0e-a204-60cb04f48d55'::uuid, NULL, E'The technology company exports both hardware and software.', NULL, NULL, NULL),
  ('02d1c281-752d-5e98-99d1-d3caec5752c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '02d1c281-752d-5e98-99d1-d3caec5752c6'::uuid, 1, NULL, TRUE, 0, NULL, E'WiFi', E'If you want to take advantage of public WiFi hot spots or your own home-based network, the first thing you''ll need to do is make sure your computer has the right gear. Most new laptops and many new desktop computers come with built-in wireless transmitters. If your computer isn''t already equipped, you can buy a wireless adapter that plugs into the PC card slot or USB port. Desktop computers can use USB adapters, or you can buy an adapter that plugs into the PCI slot inside the computer''s case. Once you''ve installed a wireless adapter and the drivers that allow it to operate, your computer should be able to automatically discover existing networks. If you have an older computer, you may need to use a software program to detect and connect to a wireless network.\n\nWhen your PC cannot connect to a wireless network, which of the following cannot help you to address the problem?', NULL, NULL, NULL, E'To uninstall the wireless adapter on your computer.', NULL, NULL),
  ('02d3798c-2a9c-5c33-8377-ec40cca15f91'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '02d3798c-2a9c-5c33-8377-ec40cca15f91'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '40f91b33-0197-59a2-87f3-3c044b0924f4'::uuid, NULL, E'Our priority is to educate people about the dangers of drugs.', NULL, NULL, NULL),
  ('02d4c2f2-c8b9-543a-894e-314b8169b3a2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '02d4c2f2-c8b9-543a-894e-314b8169b3a2'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What does under the weather mean?', '14404d27-cee1-5227-9707-cc0d56a8accc'::uuid, NULL, NULL, E'Feel sick / poor health / tired / exhausted', NULL, NULL),
  ('02d5df89-79cc-51c8-9266-453b9643bf61'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '02d5df89-79cc-51c8-9266-453b9643bf61'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '245c6333-4a85-58c3-9812-5de972b9e568'::uuid, NULL, NULL, E'Freshwater creatures didn''t appear in the paintings until the modern period.', NULL, NULL),
  ('02da3c5a-e3aa-581a-85ec-4bc4a467d422'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '02da3c5a-e3aa-581a-85ec-4bc4a467d422'::uuid, 1, NULL, TRUE, 0, NULL, E'Viper', E'The horned desert viper''s ability to hunt at night always has puzzled biologists. Though it lies with its {{1}} buried in the sand, it can strike with great precision as soon as prey appears. Now, Young and physicists Leo van Hemmen and Paul Friedel at the Technical University of Munich in Germany have developed a computer model of the snake''s auditory {{2}} to explain how the snake "hears" its prey without really having the ears for it. Although the vipers have internal ears that can hear frequencies between 200 and 1000 hertz, it is not the sound of the mouse scurrying about that they are detecting. " The snakes don''t have external {{3}} ," says van Hemmen. " So unless the mouse wears boots and starts stamping, the snake won''t hear it."', NULL, NULL, NULL, E'1.head, 2.system, 3.eardrums', NULL, NULL),
  ('02df5f7e-fd01-586f-a184-a20bf18e5ad2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '02df5f7e-fd01-586f-a184-a20bf18e5ad2'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd0093ba6-65de-580c-8e25-1af60e14117f'::uuid, NULL, E'The government outlined a new set of proposals on women''s rights.', NULL, NULL, NULL),
  ('02eafcde-aa29-5a0d-bc25-188b3710d2b6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '02eafcde-aa29-5a0d-bc25-188b3710d2b6'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the item of footwear intended to protect and comfort human foot?', 'acf4fdc9-c62e-5399-af4f-31c34124d62a'::uuid, NULL, NULL, E'Shoes / socks / boots', NULL, NULL),
  ('02f5bf1c-a8c1-5382-b151-3d9e38ab2c45'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '02f5bf1c-a8c1-5382-b151-3d9e38ab2c45'::uuid, 1, NULL, TRUE, 0, NULL, E'Political Scholars', E'Political scholars had historically recognized the social role of the mass media. The impact of the mass media on the election and governing process has greatly increased over the last forty years. Tomorrow, the mass media will become the "central nervous system" for your society and the major source of public information.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('02f74bdc-d5c0-5a3c-b935-2e9306bcfa77'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '02f74bdc-d5c0-5a3c-b935-2e9306bcfa77'::uuid, 1, NULL, TRUE, 0, NULL, E'Growing Star', E'A super-computer simulation by an international team of researchers has shown the formation of a rapidly growing star from supersonic gas streams in the early universe left over from the Big Bang. The star ends its life with catastrophic collapse to leave a black hole with a mass of 34,000 times that of the Sun.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('02f884f4-6d9e-552f-bb3e-4028fe004af6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '02f884f4-6d9e-552f-bb3e-4028fe004af6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'bb4f18f9-aa9d-5fe6-a511-c4592065a7c6'::uuid, NULL, NULL, E'Cinema and music hold equal importance with science and mathematics.', NULL, NULL),
  ('03005535-da2c-5232-88dc-2781df3c7acf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '03005535-da2c-5232-88dc-2781df3c7acf'::uuid, 1, NULL, TRUE, 0, NULL, E'Vampire Tree', E'You may think vampires are limited to the tales of undead humans drinking blood, but you might be surprised to learn about one peculiar so-called vampire tree found in the forests of New Zealand.\nScientists found vampire-like behavior in the stump of a living kauri tree. The tree had extended its roots into an interweaving community of surrounding trees, forming what the study authors called a ‘superorganism.’ The vampire tree grafts its roots onto dozens or even hundreds of other trees, sucking in the water and nutrients at night that the other trees spent all day collecting.\nWithout the water and nutrients drained from its neighbors, the kauri tree stump would most certainly be dead. It lacks green tissue of its own, according to study co-author Sebastian Leuzinger. As for why the host trees don’t cut off the leaching stump, Leuzinger and his colleges theorized the vampire tree’s superorganism acts as a network of water and nutrients, taking turns pumping resources to one another.\nLeuzinger and Bader went on to uncover the stump’s vampirish nature by measuring the flow of water in the stump and the surrounding trees of the same species. In effect, they found a strong negative correlation in the water flow between the trees. In other words, though genetically different, they were sharing resources thanks to grafted roots recognizing nearby root tissue.\nResearchers are looking for more types of kauri tree stumps to further study the formation of root systems between stumps and living trees. Should they discover more vampire trees and the scope of the research expands, a better understanding of such resource-sharing superorganisms may be significant to the longevity of forests.', NULL, NULL, NULL, NULL, 5, 75),
  ('03042ae1-5b80-5b0d-b1c5-7975c88b4461'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '03042ae1-5b80-5b0d-b1c5-7975c88b4461'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f5aa1dd6-488d-56ac-b72d-7643a117efa6'::uuid, NULL, E'Today, we will be discussing the role of government in preventing injustice.', NULL, NULL, NULL),
  ('030b1ac0-bf34-5657-b9c0-b9eb79085854'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '030b1ac0-bf34-5657-b9c0-b9eb79085854'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5ae48402-c0cd-54e2-a7e8-13c1a3a0d9fa'::uuid, NULL, NULL, E'The coffee machine upstairs isn''t working at the moment.', NULL, NULL),
  ('030c9431-0ed1-54cb-8fd3-ab4109cb4cb3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '030c9431-0ed1-54cb-8fd3-ab4109cb4cb3'::uuid, 1, NULL, TRUE, 0, NULL, E'Social Contract', NULL, NULL, NULL, NULL, E'4, 2, 5, 1, 3', NULL, NULL),
  ('031812c2-5fea-5158-8d2b-e7bddae2381b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '031812c2-5fea-5158-8d2b-e7bddae2381b'::uuid, 1, NULL, TRUE, 0, NULL, E'Green Tea', NULL, NULL, NULL, NULL, E'5, 3, 4, 1, 2', NULL, NULL),
  ('031e1d58-84f2-57a4-845b-e3bb0e19375d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '031e1d58-84f2-57a4-845b-e3bb0e19375d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call the process of borrowing a sum of money from a bank?', 'fc73cc33-130e-5a43-aac9-5d1e3db564a2'::uuid, NULL, NULL, E'Loan', NULL, NULL),
  ('032aa1b8-99e8-5937-b676-85d58cbcfcb0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '032aa1b8-99e8-5937-b676-85d58cbcfcb0'::uuid, 1, NULL, TRUE, 0, NULL, E'Latin America Reform', NULL, '8fc9b4c6-261c-5176-8c1b-5b19a69f938f'::uuid, NULL, E'Due to globalization effect, it is hard for people to hold a positive attitude towards Latin America''s economy.\nGlobalization had been widely believed to benefit people globally, including Latin American countries.\nBut people are disappointed about the actual economic growth in that continent.\nOver the 20 years before globalization, the economy in Latin America developed by eighty percent.\nPeople thought taking part in globalization would achieve a higher economic growth rate. But in fact, the growth rate has dropped to ten percent after economic reforms related with globalization happened in Latin America.\nAccordingly, the poverty rate has increased, and the criterion of ''poverty'' is ''earning no more than two dollars per day''.\nThus, Latin America''s economy has become unsustainable.\nPeople are asking why the economic development has been slower than that before reforms.\nSo, globalization is not a perfect economic structure, which possibly has a negative effect.', NULL, NULL, NULL),
  ('03330b64-9c73-54cc-9955-0c6e434456fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '03330b64-9c73-54cc-9955-0c6e434456fd'::uuid, 1, NULL, TRUE, 0, NULL, E'Ocean Floor', E'The ocean floor is home to many unique communities of plants and animals. Most of these marine ecosystems are near the water surface, such as the Great Barrier Reef, a 2,000-km long coral {{1}} off the northeastern coast of Australia. Coral reefs, like nearly all complex living communities, depend on solar energy for growth (photosynthesis). The sun''s energy, however, penetrates at most only about 300 m below the surface of the water. The relatively shallow penetration of solar energy and the sinking of cold, subpolar water combine to make most of the deep ocean floor a {{2}} environment with few life forms.\nIn 1977, scientists discovered hot springs at a depth of 2.5 km, on the Galapagos Rift (spreading ridge) off the coast of Ecuador. This exciting discovery was not really {{3}} .Since the early 1970s, scientists had predicted that hot springs (geothermal vents) should be found at the active spreading centers along the mid-oceanic ridges, where magma, at temperatures over 1,000° Presumably was being erupted to form new oceanic crust. More exciting, because it was totally {{4}} ,was the discovery of abundant and unusual sea life - giant tube worms, huge clams, and mussels - that {{5}} around the hot springs.', NULL, NULL, NULL, E'1.formation, 2.frigid, 3.a surprise, 4.unexpected, 5.thrived', NULL, NULL),
  ('0334d115-aa6c-5b8a-b7fc-2f8beca8fcca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0334d115-aa6c-5b8a-b7fc-2f8beca8fcca'::uuid, 1, NULL, TRUE, 0, NULL, E'Headaches', E'Individuals who suffer from concussions often experience moderate to severe headaches in the weeks following the injury. However, a recent study has discovered that a combination of two commonly used anti-nausea medications, administered intravenously in the emergency room, may provide more effective relief for these headaches compared to a placebo.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('03395378-f83f-5e9b-8138-b2134d178939'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '03395378-f83f-5e9b-8138-b2134d178939'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd3a1e6c8-6510-55e4-a4b6-14b8a1da2bfa'::uuid, NULL, NULL, E'Those seeking a formal extension should contact their faculty for information.', NULL, NULL),
  ('033b5114-30eb-5179-9b87-0c54c378f78c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '033b5114-30eb-5179-9b87-0c54c378f78c'::uuid, 1, NULL, TRUE, 0, NULL, E'Lens', E'The lens, along with the iris and pupil, works like a camera. The lens {{1}} its shape to bend and focus the light a second time, {{2}} that you have a clear image of what you are looking at. It allows you to see objects both from short distances and from {{3}} . The lens {{4}} of water and protein, which maintain its transparency and function.', NULL, NULL, NULL, E'1.adjusts, 2.to ensure, 3.far away, 4.consists', NULL, NULL),
  ('033b8b0a-ba86-5d35-8623-b296ded69039'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '033b8b0a-ba86-5d35-8623-b296ded69039'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4dc0e02b-b945-5d40-849d-f0c2f12c34db'::uuid, NULL, NULL, E'This forum has attracted many scholars and experts from different fields.', NULL, NULL),
  ('03414ccf-cb0e-5101-be2c-81357499117a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '03414ccf-cb0e-5101-be2c-81357499117a'::uuid, 1, NULL, TRUE, 0, NULL, E'Jupiter’s Moon Europa', E'Scientists preparing for NASA''s proposed Jupiter icy Moons Orbiter believe that Jupiter''s moons Europa may be a corrosive mixture of acid and peroxide. Thus, it may not be the {{1}} place for life to exist as was thought possibly to be the case. {{3}} , all the information we have about Europa comes from the spacecraft Galileo, which completed its mission to study. {{4}} the general perception of Europa is of a frozen crust of water ice harboring a salty subterranean ocean kilometer below, researchers studying the most {{2}} measurements say light reflected from the moons icy surface bears the spectral fingerprints of hydrogen peroxide and strong acids. {{5}} , they accept that it could just be a thin surface dusting and might not come from the ocean below.', NULL, NULL, NULL, E'1.ideal, 2.Virtually, 3.Although, 4.recent, 5.However', NULL, NULL),
