  ('037c43c2-c916-5322-bec9-06eae99acb95'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '037c43c2-c916-5322-bec9-06eae99acb95'::uuid, 1, NULL, TRUE, 0, NULL, E'Telescopes', E'Astronomers have conducted an impressive observation campaign using a total of 12 telescopes, both on land and in space, including three facilities belonging to the European Southern Observatory (ESO). The study has revealed the peculiar behavior of a pulsar, which is a dead star that spins at an incredibly fast rate.', NULL, NULL, NULL, NULL, NULL, NULL),
