  ('03876b16-20a9-5932-baa8-aea9752abf61'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '03876b16-20a9-5932-baa8-aea9752abf61'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4ed73975-6620-56bc-a3eb-c4f18083d8df'::uuid, NULL, E'There is a new pharmacy on the north side of the university campus.', NULL, NULL, NULL),
  ('03878e8b-872a-5418-a2a9-e3e6a5744dd3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '03878e8b-872a-5418-a2a9-e3e6a5744dd3'::uuid, 1, NULL, TRUE, 0, NULL, E'Died Stars', E'The Milky Way is a gargantuan graveyard. Stars are born, burn out and die, but they don''t just vanish — and the galaxy is haunted by their corpses. Stars in the Milky Way that died billions of years ago went supernova and morphed into two types of objects. With their outer layers blasted away by the force of the explosion, the cores that were left formed black holes.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('038a4cb5-d456-5321-ac4a-b3c76b14c7cc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '038a4cb5-d456-5321-ac4a-b3c76b14c7cc'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '31ee536c-b247-5897-bd37-d4c7a5136dc0'::uuid, NULL, NULL, E'Trains have made it easy for everyone to travel far.', NULL, NULL),
  ('038faa97-a5cc-5ba0-b612-7677a4a54108'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '038faa97-a5cc-5ba0-b612-7677a4a54108'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ea8cde94-3ce1-5e57-b936-e3f9d93ec54a'::uuid, NULL, E'Export trade finance companies or agencies also provide information and support for export working capital.', NULL, NULL, NULL),
  ('039d5606-2ce1-56ca-b87c-1eac0bc8342c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '039d5606-2ce1-56ca-b87c-1eac0bc8342c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6469f99d-ee4e-5510-aba5-c8a919124899'::uuid, NULL, NULL, E'Meeting with mentors can be scheduled for students who require additional support.', NULL, NULL),
  ('039ecb13-de21-592b-99d4-894b8856ad0e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '039ecb13-de21-592b-99d4-894b8856ad0e'::uuid, 1, NULL, TRUE, 0, NULL, E'Fermentation', E'The word "ferment" comes from the Latin word for boiling or rising, which you''ll understand if you''ve ever seen beer brewing or bread dough rising — both signs of fermentation in action. A biologist would probably say fermentation is the anaerobic production of energy, meaning that microorganisms that don''t need oxygen to accomplish metabolization to fuel their bodies transform nutrients into energy in the absence of oxygen. This is true for some fermented foods — for instance, sauerkraut and alcohol are both products of the hard work of anaerobic bacteria. However, other foods and beverages that we consider "ferments" are made by aerobic microorganisms that use oxygen to do their business: kombucha, vinegars and miso are a few.\n\nThe purpose of the text is to ____ .', NULL, NULL, NULL, E'introduce two kinds of microorganisms responsible for fermentation.', NULL, NULL),
  ('03a18735-4b4a-57e8-a0cd-dc928abad561'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '03a18735-4b4a-57e8-a0cd-dc928abad561'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'db1a0fb3-eb44-5e21-ab2a-40cd9331460e'::uuid, NULL, E'Contemporary critics dismissed his idea as eccentric.', NULL, NULL, NULL),
