  ('03ac1d04-2536-5f1c-8710-a2ab5787e903'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '03ac1d04-2536-5f1c-8710-a2ab5787e903'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'fcfc7497-a5a1-56e2-8081-0e2a6190c289'::uuid, NULL, NULL, E'Always say where you get your information when writing papers.', NULL, NULL),
  ('03ae1c80-5a44-584d-b7cc-b94adc62462b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '03ae1c80-5a44-584d-b7cc-b94adc62462b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'fe40ab94-0b93-53a8-ac6a-103617181734'::uuid, NULL, NULL, E'Strong lasers are used to measure distances and baselines.', NULL, NULL),
  ('03b249ef-1c1f-5972-a670-37c81ca66111'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '03b249ef-1c1f-5972-a670-37c81ca66111'::uuid, 1, NULL, TRUE, 0, NULL, E'Bookcase', E'None of the books in my father’s dusty old bookcase were {{1}} .Yet while I was growing up, I never saw anyone take one down. Most were {{2}} tomes – a comprehensive history of civilization, matching volumes of the great works of western literature, numerous others I can no longer {{3}} – that seemed almost fused to {{4}} that bowed slightly from decades of {{5}} support.', NULL, NULL, NULL, E'1.forbidden, 2.massive, 3.recall, 4.shelves, 5.steadfast', NULL, NULL),
  ('03b4b266-d1f5-5226-ba29-7883d2c2ad54'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '03b4b266-d1f5-5226-ba29-7883d2c2ad54'::uuid, 1, NULL, TRUE, 0, NULL, E'Chemosignals', E'Studying how mouse brains process chemosignals will help researchers understand general principles of how their brains form social memories, and could help scientists identify what happens when these functions go wrong. Eventually this may help scientists understand what happens in people whose ability to recognize others is impaired or those who have difficulties with social interactions caused by autism.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('03bbfc2a-4c47-5188-9d1c-8dc24d198a01'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '03bbfc2a-4c47-5188-9d1c-8dc24d198a01'::uuid, 1, NULL, TRUE, 0, NULL, E'Circular Economy', E'How can you get your business to reduce waste and help the environment, yet at the same time reduce costs and increase customer {{1}} ? It sounds like a dream, but it’s undoubtedly possible through joining the circular economy in both discrete and process manufacturing. The circular economy is a system that looks to {{2}} waste and the continual use of resources. As opposed to a traditional linear economy in which we make, consume, and throw away, moving circular is all about creating a circle where we design out waste and pollution by keeping products and materials in use for as long as possible and finding ways to create new resources from what we {{3}} . With the circular economy, we’re extracting the maximum value from products while in use, then recover and regenerate products and materials at the end of each service life. The circular economy puts a big focus on services, maintenance, and {{4}} of assets. However, as resources become more and more scarce, manufacturers and distributors in the circular economy are introducing additional value-added services.', NULL, NULL, NULL, E'1.satisfaction, 2.eliminate, 3.discard, 4.refurbishment', NULL, NULL),
  ('03d151ba-21ab-5b4b-b989-2984c6be7a70'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '03d151ba-21ab-5b4b-b989-2984c6be7a70'::uuid, 1, NULL, TRUE, 0, NULL, E'Conversation', E'Time is one of humanity’s greatest blind spots. We experience it as days, months, or years. But nature functions on much grander scales, measured in centuries, millennia and even longer intervals often lumped together as “deep time.” As paleontologists, we were trained to think in deep time. Yet, as conservationists, we’ve come to realize that time can be confounding.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('03d15e1e-5fae-59d9-9467-c0d938d046fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '03d15e1e-5fae-59d9-9467-c0d938d046fb'::uuid, 1, NULL, TRUE, 0, NULL, E'Technology and Education', E'Do you agree that technology has had a more positive than negative impact on the quality of education?', NULL, NULL, NULL, NULL, 200, 300),
  ('03d557db-c09f-5c3a-85f1-6f091cc81567'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '03d557db-c09f-5c3a-85f1-6f091cc81567'::uuid, 1, NULL, TRUE, 0, NULL, E'Only One Book', E'You need to read a book for your class. However, there is only one of these books in the library, and another student is already reading it. How would you ask the student to give you the book later?', 'fbaecb23-2be8-5010-bb38-2abefdf74556'::uuid, NULL, E'Hey mate, I want to talk to you about something.\nWe seem to have a little issue with the class book from the library.\nIt''s like there is only one copy available, and I need it for my class, so could you pass it to me once you finish reading?\nAnd I''d like to know what you think.', NULL, NULL, NULL),
  ('03d7b0e1-d2fe-5a1f-90fb-fb3651e44b44'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '03d7b0e1-d2fe-5a1f-90fb-fb3651e44b44'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9cd83c82-d1b6-59bf-92da-8e63b7d4f477'::uuid, NULL, E'Nowadays, persuasion is an important area of research within social psychology.', NULL, NULL, NULL),
  ('03e46bca-4bdf-58f5-a440-ac3bd7b1189e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '03e46bca-4bdf-58f5-a440-ac3bd7b1189e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '269b9f56-2fba-5431-b43f-ad95aa2524a1'::uuid, NULL, NULL, E'The features issued the same explanation of the problem.', NULL, NULL),
  ('03e73212-3bd7-5cb7-9231-024ba50bdf43'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '03e73212-3bd7-5cb7-9231-024ba50bdf43'::uuid, 1, NULL, TRUE, 0, NULL, E'Statistical Information (B)', E'The provision of accurate and authoritative statistical information strengthens our society. It provides a basis for decisions to be made on public policy, such as determining electoral boundaries and where to locate schools and hospitals. It also allows businesses to know their market, grow their business, and improve their marketing strategies by targeting their activities appropriately.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('03e9a87d-8c03-5e17-b1bc-3f06b569d62f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '03e9a87d-8c03-5e17-b1bc-3f06b569d62f'::uuid, 1, NULL, TRUE, 0, NULL, E'Dimensions', NULL, 'd2f95b80-ecf5-562c-8fbd-30201dda0195'::uuid, NULL, E'A dimension of space is basically an independent direction in which in principle you could move, you could walk, so we talk about left and right, you can freely move left right, back forth, you can move back forth, up down, you can freely move up down as well. If you consider a diagonal direction, that''s not a new direction because that''s just a combination of moving this way and that way. So when we talk about dimensions, we talk about the independent directions, which you can move. Another way to think about dimensions, they are the data that needs to be specified in order to delineate where something takes place. So if you''re having a dinner party, you give your friend a straight, a cross straight in the floor number, three pieces of information to nail down a location in three dimensions in the space. According to the string theory, in reality you need to give your friend more than just those three pieces of information if you really want him or her to know where to go. You need to tell them coordinates, data, that''s specifies real actual dimensions the dinner party''s taking place, too, but because the actual dimensions we think are so small, it does not matter to your friend whether they show up exactly at the right location and actual dimensions or not because things are not able to penetrate them in any meaningful way. But that''s what dimension would be, it''s a piece of data necessary to delineate where something takes place.', NULL, NULL, NULL),
  ('03f1a7dc-31d6-5290-a624-88109449ce85'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '03f1a7dc-31d6-5290-a624-88109449ce85'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which one means ''not limited'', infinite or finite?', 'e61a257f-3eca-5daa-ad15-9c650e5f6dc7'::uuid, NULL, NULL, E'Infinite', NULL, NULL),
  ('03f43d33-f8b7-572d-84fa-5f5f46284d95'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '03f43d33-f8b7-572d-84fa-5f5f46284d95'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f1406907-a31d-5862-b119-179144ce51e8'::uuid, NULL, E'Please take these up to Mr Mitchell in the chemistry lab.', NULL, NULL, NULL),
  ('03fd9359-ce2f-5776-8300-df7e29e7483a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '03fd9359-ce2f-5776-8300-df7e29e7483a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3368aedd-82fc-5adf-976a-3101fc0d8daf'::uuid, NULL, NULL, E'All industries consist of systems of inputs, processes, outputs and feedback.', NULL, NULL),
  ('03fe66a9-8efb-50f8-b34d-513cec2a6c19'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '03fe66a9-8efb-50f8-b34d-513cec2a6c19'::uuid, 1, NULL, TRUE, 0, NULL, E'Brain', E'For decades, scientists have used an imaging technique called functional magnetic resonance imaging, or fMRI, to {{2}} the brain in action. But a study in the January 22nd issue of Nature suggests that fMRI might show more than what the brain is doing—it might reveal what the brain''s about to do.\nFMRI studies assume that blood flow in the brain {{3}} with neuronal {{5}} . Active brain cells need {{6}} , which are brought to the cells by freshly oxygenated blood. But in the new study, scientists found that fMRI also detects {{7}} blood flow in brain regions that aren''t active—but that may be in the near future.\nThe researchers trained monkeys to perform a specific visual task. And they found that, even when the animals were sitting in the dark waiting for the test to begin, fMRI nevertheless revealed an increased blood flow to the monkeys'' visual cortex.\nThe study suggests that fMRI data may be a lot more interesting than we thought. Scientists may be looking at their imaging data in a way that''s too simplistic. And fMRI may not be measuring exactly what we thought it did. What will they think of next? Maybe fMRI can tell.', NULL, NULL, NULL, E'1.chronicle, 2.correlates, 3.activity, 4.nutrients, 5.increased', NULL, NULL),
  ('03fee81e-f004-53ff-bd19-cafd55876c52'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '03fee81e-f004-53ff-bd19-cafd55876c52'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0eda7f75-572f-50d2-95dc-e22ec6dac369'::uuid, NULL, NULL, E'We change due dates only for very big, important reasons.', NULL, NULL),
  ('03ff1ecc-68d4-5855-914f-cfe3baa106d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '03ff1ecc-68d4-5855-914f-cfe3baa106d3'::uuid, 1, NULL, TRUE, 0, NULL, E'Future Population', E'Researchers have investigated how changes in urban land and population will affect future populations'' exposures to weather extremes under climate conditions at the end of the 21st century. They used a data-driven model to predict how urban areas across the country will grow by 2100, and found that how a city is laid out or organized spatially has the potential to reduce population exposures to future weather extremes.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('040077dd-3bb3-5799-a14b-8098b7a356b4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '040077dd-3bb3-5799-a14b-8098b7a356b4'::uuid, 1, NULL, TRUE, 0, NULL, E'Ernest', E'Ernest Shackleton was a British explorer of the South Pole who is best remembered for leading his crew to safety after the failed expedition of the Endurance (1914–16). Shackleton had been a junior officer on Robert Falcon Scott''s discovery {{1}} (1902–03), and his travels with the Nimrod (1907-09) had taken him closer to the South Pole than anyone before. After Roald Amundsen reached the Pole in 1911, Shackleton and a crew of 28 men set out in his ship Endurance in 1914, in the {{2}} of being the first to cross the polar continent. The ship was frozen in ice, then crushed, and Shackleton and his men set out in lifeboats after nearly a year and a half on the ice. Shackleton, known as "The Boss," took five men and sailed 800 miles in an open boat from Elephant Island to the island of South Georgia, then went back and {{3}} the rest of his crew, all of whom survived. Almost two years after starting out, they reached safety in South America in September 1916. In spite of his heroics, Shackleton had a hard time back in England with finances and alcohol. He {{4}} managed to get financing for another voyage to Antarctica in 1921, but he had a fatal heart attack at South Georgia Island and {{5}} made it.', NULL, NULL, NULL, E'1.expedition, 2.hope, 3.saved, 4.eventually, 5.never', NULL, NULL),
  ('0400d02e-8c7b-5a42-99d4-81f735563ef7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0400d02e-8c7b-5a42-99d4-81f735563ef7'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '123667b8-659e-5bd4-9adb-abe5bc53d598'::uuid, NULL, E'They''re discussing the most efficient strategy to manage the risks facing the business.', NULL, NULL, NULL),
  ('04024d3f-d4b2-5881-998f-c46038db7123'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '04024d3f-d4b2-5881-998f-c46038db7123'::uuid, 1, NULL, TRUE, 0, NULL, E'The Adolescent Brain', E'The rapid physical and {{1}} development that marks adolescence creates a critical window of opportunity. The adolescent brain develops at a {{2}} unseen since early childhood, making girls and boys hypersensitive to influences in their environments. Adolescents’ {{3}} to try new things can spark {{4}} and achievement, but it can also leave them {{5}} .', NULL, NULL, NULL, E'1.cognitive, 2.rate, 3.inclination, 4.innovation, 5.vulnerable', NULL, NULL),
  ('04038a22-c882-5442-a3a4-839314af2d7b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '04038a22-c882-5442-a3a4-839314af2d7b'::uuid, 1, NULL, TRUE, 0, NULL, E'Money for Job', E'The most important aspect of a job is the money a person earns. To what extent do you agree with this statement?', NULL, NULL, E'Money is undoubtedly a key factor in our lives, and it is no surprise that many people believe it to be the most important aspect of a job. While there are certainly other factors that contribute to job satisfaction, I strongly agree that money is the most crucial aspect of a job.\nFirstly, money is essential for survival in the modern world. We need money to pay for food, shelter, healthcare, and other basic necessities of life. Without a sufficient income, it can be challenging to meet these basic needs, let alone enjoy the luxuries that life has to offer. Therefore, earning a good salary is a fundamental aspect of any job.\nSecondly, higher income can provide financial security and stability. With more money, individuals can save for emergencies, invest in their future, and enjoy a higher quality of life. This financial security can reduce stress and anxiety, allowing individuals to focus on other important aspects of their lives. Moreover, it can provide a safety net for unexpected events such as job loss or illness.\nIn conclusion, while there are certainly other factors that contribute to job satisfaction, I strongly believe that money is the most important aspect of a job. It is necessary for survival in the modern world and provides financial security and stability. Therefore, when considering career options or evaluating job offers, individuals should prioritize earning a good salary as it is a crucial factor in achieving a fulfilling life.', NULL, 200, 300),
  ('040578a4-b86d-585d-9a19-076f83053bb9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '040578a4-b86d-585d-9a19-076f83053bb9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0403cd83-ef08-51f7-ba2f-e4df96ba971e'::uuid, NULL, NULL, E'Please put the book back where it belongs in the library.', NULL, NULL),
  ('0405b619-09af-57ec-9c5c-3cf52edd42d6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '0405b619-09af-57ec-9c5c-3cf52edd42d6'::uuid, 1, NULL, TRUE, 0, NULL, E'Japan and China', E'At times, a broad stream of knowledge flowed from China to Japan. At other times, this transfer was {{1}} on one side or the other, and Japan {{2}} on its own. But whether in isolation or not, Japan was always itself. Everything that {{3}} from China was {{4}} to suit Japanese tastes and needs.', NULL, NULL, NULL, E'1.halted, 2.developed, 3.arrived, 4.adapted', NULL, NULL),
  ('040b75b4-2881-59c9-a7a8-069925ab2c76'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '040b75b4-2881-59c9-a7a8-069925ab2c76'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2ff69c20-b1c7-5ba9-9cb9-b6e13c23bd34'::uuid, NULL, NULL, E'The properties should be appropriately distributed.', NULL, NULL),
  ('0416d00f-bb4e-5eba-82c7-45a3e118161f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0416d00f-bb4e-5eba-82c7-45a3e118161f'::uuid, 1, NULL, TRUE, 0, NULL, E'Carbon Emission', E'CHARLES: OK, let''s start with some basics - why our homes matter in the big picture of climate change. Nobody cares more about this than Donnel Baird, the BlocPower CEO we met earlier.\nBAIRD: Buildings in the United States are responsible for 30% of greenhouse gas emissions across the country. If you want to do something about climate change, your home is among the most important places to look.\nCHARLES: Maybe it''s hard to imagine a house releasing greenhouse gases just sitting there, but think about your daily routine. You stumble out of bed in the morning, turn on the lights, turn up the thermostat, take a shower, make some coffee or toast. The heat and the hot water may come from a furnace or a water heater that burn gas. They release carbon dioxide straight into the air, other kinds of pollution too actually. The lights and the coffee maker and the computer run on electricity, and that comes from power plants, most of which are still burning coal and gas. You can actually look at your electric bill and calculate those emissions.\n\nWhy does the man mention the daily routines?', 'dc330cbd-b834-5206-a38a-bd3ee373f3ed'::uuid, NULL, NULL, E'To give examples of how a house can produce greenhouse gases.', NULL, NULL),
  ('041911e3-47f7-59d5-be85-7b6c88531579'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '041911e3-47f7-59d5-be85-7b6c88531579'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b539fd1e-bc03-5fba-ab68-f23da1c1c2b7'::uuid, NULL, NULL, E'The business class can be held with local students.', NULL, NULL),
  ('04199d79-3275-5dcb-adcb-73e2928cc5f4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '04199d79-3275-5dcb-adcb-73e2928cc5f4'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call an arch of different colors that you can sometimes see in the sky after raining?', '5f8958a2-dfca-5739-88b3-2d91860e4874'::uuid, NULL, NULL, E'Rainbow', NULL, NULL),
  ('041a826a-6267-5859-b50f-3c4500e088a2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '041a826a-6267-5859-b50f-3c4500e088a2'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the type of book that has a stiff hard cover?', '35353991-6e00-543c-87fd-1fc92ab013d6'::uuid, NULL, NULL, E'Hardcover / hardback', NULL, NULL),
