  ('048b1d2c-3ea9-55bc-814d-3c900ba39f81'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '048b1d2c-3ea9-55bc-814d-3c900ba39f81'::uuid, 1, NULL, TRUE, 0, NULL, E'Good Customer Service', E'Good customer service relates to the service you and your employees provide before, during and after a purchase. For example, it’s how you {{3}} with your customers. Improving your customer service skills can lead to great customer satisfaction and a more enjoyable experience for them.\nNo matter the size of your business, good customer service needs to be at the heart of your business model if you wish to be successful. it is important to provide good customer service; to all types of customers, including {{1}} , new and existing customers.\nAlthough it can take extra resources, time and money, good customer service leads to customer satisfaction which can generate positive {{2}} for your business, keep your customers happy and encourage them to purchase things from your business again. Good customer service can help your business grow and prosper.', NULL, NULL, NULL, E'1.interact, 2.potential, 3.word of mouth', NULL, NULL),
  ('048d875d-8399-5fc8-bf95-939eb629b065'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '048d875d-8399-5fc8-bf95-939eb629b065'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c8eb350e-5ff6-5d02-b9a3-47b2107ffdb9'::uuid, NULL, E'People regularly encounter ads online, on TV, and in magazines.', NULL, NULL, NULL),
