  ('049e397b-284b-58fb-b5a5-7386be88b134'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '049e397b-284b-58fb-b5a5-7386be88b134'::uuid, 1, NULL, TRUE, 0, NULL, E'Data Analysis', E'To be accepted as trustworthy, qualitative researchers must {{1}} that data analysis has been conducted in a precise manner through systematizing the methods of analysis with enough detail to enable the reader to {{2}} whether the process is credible. Although there are numerous examples of how to {{3}} qualitative research, few sophisticated tools are available to researchers for conducting a rigorous and relevant thematic {{4}} .', NULL, NULL, NULL, E'1.demonstrate, 2.determine, 3.conduct, 4.analysis', NULL, NULL),
