  ('04a4f62e-2cf6-5e52-8d68-46a87bfed6e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '04a4f62e-2cf6-5e52-8d68-46a87bfed6e1'::uuid, 1, NULL, TRUE, 0, NULL, E'Revolving Restaurants', E'The popular trend of revolving restaurants and bars began sometime in the early Sixties after the successful launch of such towering creations as the Space Needle. But as the novelty wore off, the mechanical upkeep and maintenance of such ventures proved to be too costly for some entrepreneurs over time and many once-famous icons like Encounter Restaurant have since closed.', NULL, NULL, NULL, NULL, NULL, NULL),
