  ('04add04a-6cbc-5829-a20a-5666db8c0837'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '04add04a-6cbc-5829-a20a-5666db8c0837'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '66561f85-5306-5175-83c3-4bc7a05c648a'::uuid, NULL, E'Please sort and order the presentation slides according to topic and speaking time.', NULL, NULL, NULL),
  ('04af4752-e2c9-5c16-acaa-5346ee337ac3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '04af4752-e2c9-5c16-acaa-5346ee337ac3'::uuid, 1, NULL, TRUE, 0, NULL, E'Fingerprints', E'Fingerprints, referred to as ''fingermarks'' in forensics, are formed when residue from the ridged skin of the fingers or palms is {{1}} onto a surface, leaving behind an impression. Fingermarks are often made of sweat and colorless {{2}} materials such as soap, moisturizer and grease. These fingermarks are described as ''latent'' as they are generally invisible to the naked eye, which means that {{3}} them at a crime scene can be challenging.', NULL, NULL, NULL, E'1.transferred, 2.contaminating, 3.locating', NULL, NULL),
  ('04b389a3-1d47-5838-a74e-dae40bfb6919'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '04b389a3-1d47-5838-a74e-dae40bfb6919'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '503f434b-4e10-569f-b3d9-dee56f22b39f'::uuid, NULL, NULL, E'Three of the students were confused by the key hypothesis.', NULL, NULL),
  ('04b6dc5e-a4d1-52d7-a805-c10e76a91f0c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '04b6dc5e-a4d1-52d7-a805-c10e76a91f0c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do you describe an event that is held every two years?', '82f13873-7a2b-5589-aeb7-060e1c41aeb5'::uuid, NULL, NULL, E'Biennial', NULL, NULL),
  ('04ba38a6-2d66-535c-9b9c-d0dcf9644e00'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '04ba38a6-2d66-535c-9b9c-d0dcf9644e00'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8816b4bc-f659-5087-a50c-5e8dcedd497f'::uuid, NULL, NULL, E'Predicting the reactions of all the different characters was difficult.', NULL, NULL),
  ('04bb4e75-e827-5f29-93a9-7372e602fdc3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '04bb4e75-e827-5f29-93a9-7372e602fdc3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '704a893c-2a9b-509c-a139-a58ea1c431b4'::uuid, NULL, E'The process is simple, just call them or ask for a representative to guide you.', NULL, NULL, NULL),
  ('04be555e-5733-55b4-bc69-3deca04b6adf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '04be555e-5733-55b4-bc69-3deca04b6adf'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person who leaves college before finishing the studies?', 'e4cc17bc-8540-5e1e-bbf0-1643a112498c'::uuid, NULL, NULL, E'Dropout', NULL, NULL),
  ('04beb966-5fef-516c-947f-fca35baeecca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '04beb966-5fef-516c-947f-fca35baeecca'::uuid, 1, NULL, TRUE, 0, NULL, E'Poet Laureate', E'Speaker 1: ... yes, it''s funny you should mention Merwin - until about a year ago I thought England was the only country that had a Poet Laureate. After all, it''s a pretty odd job, isn''t it? No salary to speak of and just a barrel of wine or something as payment. But he was or is the American Poet Laureate, isn''t he?\nSpeaker 2: That''s right, but quite a few other countries have one too.\nSpeaker 1: I know, I looked into it a bit. Other countries in the UK for a start: Wales, as you''d expect, with their eisteddfods and long poetic tradition , and Ireland and Scotland. I think some places that were colonies or are in the Commonwealth have them - Canada, for example. And who''s that wonderful Caribbean poet, urn, the one that wrote Omeros?\nSpeaker 2: Derek Walcott.\nSpeaker 1: That''s him. He was the Poet Laureate of Saint Lucia. But what about the rest of Europe? Don ''t the French have such a thing?\nSpeaker 2: No, I don''t think so. They''ve got the Academy, and you get elected to that if you''re considered the best in your field. But I think Germany might have - no, it wasn''t Germany. Somewhere else, but I don''t remember. By the way, you''re a bit behind the times in thinking what they get paid is a barrel of wine. All that changed long ago, but one of the more recent ones asked to have it back.\n\nAccording to the text, which of the following countries has a Poet Laureate?', 'c39d01cb-0d9f-58ce-bba1-bd4b7df0b592'::uuid, NULL, NULL, E'Ireland\nSaint Lucia\nthe USA', NULL, NULL),
  ('04c35067-7f7a-5677-975a-2004de61c662'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '04c35067-7f7a-5677-975a-2004de61c662'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '76bc328e-47c6-5af9-9484-bbcf281772fc'::uuid, NULL, NULL, E'Pupils in our schools are taught in a secure environment.', NULL, NULL),
  ('04c90fe9-9d02-5a2e-9f8c-8357a98c5a5b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '04c90fe9-9d02-5a2e-9f8c-8357a98c5a5b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5a768993-72ef-53fc-8bf1-42a841b82925'::uuid, NULL, NULL, E'The summer course was canceled due to insufficient re-enrollments.', NULL, NULL),
  ('04d53974-037a-5220-95a7-6516f6a90264'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '04d53974-037a-5220-95a7-6516f6a90264'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '983e3a98-852a-5dc3-93ca-7f220c1285d3'::uuid, NULL, NULL, E'The quality of your statistics relies on your initial data.', NULL, NULL),
  ('04dc4b19-136b-5df9-9309-120a1b2bad40'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '04dc4b19-136b-5df9-9309-120a1b2bad40'::uuid, 1, NULL, TRUE, 0, NULL, E'Homework', NULL, 'a42eebcf-c899-5681-ada5-331964ed4643'::uuid, NULL, E'Now as we all know, it has long been the habit in many Countries that teachers give homework to school children of all ages. Despite the fact that a minority of educators don''t agree with this practice, it has never seriously been questioned or challenged before. However, it may be that the tide is turning.\nThese days, more people are becoming convinced that homework is of virtually no benefit, particularly for children in the younger age group. So, why have teachers always given homework? Well, the answer seems to be because they are obliged to. Most teachers don''t really believe it has any real value. And the latest research supports the teachers'' feelings about this. Not only does homework have very little impact on children''s learning but it also puts unnecessary obligations and responsibilities onto the parents. These days not all families have the time or the necessary knowledge to help their offspring. So it would seem that now, senior educators want to start a new initiative. Rather than giving homework, they plan to encourage reading books of any kind, just reading. and they claim that this is a far more effective method of consolidating learning than wading through piles of written homework.', NULL, NULL, NULL),
  ('04e20a90-385c-5768-bdcf-978140dd5213'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '04e20a90-385c-5768-bdcf-978140dd5213'::uuid, 1, NULL, TRUE, 0, NULL, E'Asking Questions', E'It is important that scientists be seen as normal people asking and answering important questions. Good, sound science depends on {{1}} , experiments and reasoned methodologies. It requires a willingness to ask new questions and try new approaches. It requires one to take risks and experience failures. But good science also requires {{2}} understanding, clear explanation and concise presentation. Our country needs more scientists who are willing to step out in the public {{3}} and offer their opinions on important matters. We need more scientists who can explain what they are doing in language that is {{4}} and understandable to the public. Those of us who are not scientists should also be prepared to support public engagement by scientists, and to {{5}} scientific knowledge into our public communications.', NULL, NULL, NULL, E'1.hypotheses, 2.contextual, 3.arena, 4.compelling, 5.incorporate', NULL, NULL),
  ('04e51e03-e93e-5809-a0c7-b90f69379864'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '04e51e03-e93e-5809-a0c7-b90f69379864'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd2cbfdab-a182-5d68-ae77-bf6840cccfcd'::uuid, NULL, NULL, E'We support the research on problems related to tropical cyclone dynamics and forecasting.', NULL, NULL),
  ('04f9522a-891e-5424-8c5d-6a99af5ec85a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '04f9522a-891e-5424-8c5d-6a99af5ec85a'::uuid, 1, NULL, TRUE, 0, NULL, E'GPS Receivers', E'GPS receivers are {{1}} to receive information about where each satellite is at any given moment. A GPS receiver determines its own location by measuring the time it takes for a signal to arrive at its location from at least four satellites. Because radio waves travel at a {{2}} speed, the receiver can use the time measurements to {{3}} its distance from each satellite.', NULL, NULL, NULL, E'1.programmed, 2.constant, 3.calculate', NULL, NULL),
