  ('0536478d-1d92-5457-a401-b71ad7762719'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0536478d-1d92-5457-a401-b71ad7762719'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6909dd9f-5e31-5247-8623-3ae28773fd7f'::uuid, NULL, E'Agriculture was based on the family as a unit in the past.', NULL, NULL, NULL),
  ('053af725-c60e-596b-aad9-29b25991b473'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '053af725-c60e-596b-aad9-29b25991b473'::uuid, 1, NULL, TRUE, 0, NULL, E'Architecture', E'As an art, architecture is essentially abstract and nonrepresentational and involves the manipulation of the relationships of spaces, volumes, planes, masses, and voids. Time is also an important factor in architecture, since a building is usually comprehended in a succession of experiences rather than all at once. In most architecture there is no one vantage point from which the whole structure can be understood. The use of light and shadow, as well as surface decoration, can greatly enhance a structure.\nThe analysis of building types provides an insight into past cultures and eras. Behind each of the greater styles lies not a casual trend nor a vogue, but a period of serious and urgent experimentation directed toward answering the needs of a specific way of life. Climate, methods of labor, available materials, and economy of means all impose their dictates. Each of the greater styles has been aided by the discovery of new construction methods. Once developed, a method survives tenaciously, giving way only when social changes or new building techniques have reduced it. That evolutionary process is exemplified by the history of modern architecture, which developed from the first uses of structural iron and steel in the mid-19th cent.', NULL, NULL, E'As an art, architecture is essentially abstract and nonrepresentational and involves the manipulation of the relationships of factors, since a building is usually comprehended in a succession of experiences rather than all at one; the analysis of building types provides an insight into past cultures and eras, and each of the greater styles has been aided by the discovery of new construction methods, which means evolutionary process is exemplified by the history of modern architecture.', NULL, 5, 75),
  ('054b190d-b40f-5867-bf24-a1193426a790'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '054b190d-b40f-5867-bf24-a1193426a790'::uuid, 1, NULL, TRUE, 0, NULL, E'Environmental Conservation', E'To what extent do you agree with the statement that environmental conservation should be prioritized over economic growth?', NULL, NULL, NULL, NULL, 200, 300),
  ('054c209e-0248-5cfa-b833-1a4dd58021e5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '054c209e-0248-5cfa-b833-1a4dd58021e5'::uuid, 1, NULL, TRUE, 0, NULL, E'Content Marketing', E'A well-crafted content marketing strategy places your business in the position of a thought leader, building brand preference as you inform and educate buyers. Providing helpful and entertaining content can form a strong bond between your brand and customers that continues to grow and strengthen over time.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('055033b7-62d1-56ab-a28d-bafa26cf9352'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '055033b7-62d1-56ab-a28d-bafa26cf9352'::uuid, 1, NULL, TRUE, 0, NULL, E'Tear Research', E'Human tears are more than just a sign of emotion - they carry a substance that can quell aggression, as per recent research findings. This intriguing discovery has led scientists to theorize that these tear drops may {{1}} as a protective mechanism for crying infants. In an experimental setup, men were asked to sniff emotional tears {{2}} by women, following which they participated in computerized tests designed to incite aggression. The outcome was quite remarkable - aggression {{3}} dipped by over 40% among the tear-sniffers. Furthermore, brain scans revealed corresponding changes in the brain’s aggression networks. Despite the experiment being conducted with women’s tears, the researchers behind the study are of the opinion that all human tears would {{4}} similar results.', NULL, NULL, NULL, E'1.have evolved, 2.shed, 3.levels, 4.yield', NULL, NULL),
  ('05508deb-279b-563c-b217-e21d86d8fcd1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '05508deb-279b-563c-b217-e21d86d8fcd1'::uuid, 1, NULL, TRUE, 0, NULL, E'Class Participation', E'Because of the instructional methods, expected class participation and the nature of the courses vary, no fixed number of absences is applicable to all {{1}} . Each {{2}} is responsible for making clear to the class at the beginning of the {{3}} his or her policies and procedures in regard to class {{4}} and the reasons for them.', NULL, NULL, NULL, E'1.situations, 2.instructor, 3.semester, 4.attendance', NULL, NULL),
  ('0552c57a-cced-54cc-95c7-6a09c66f638e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0552c57a-cced-54cc-95c7-6a09c66f638e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e4f029d0-7b59-5305-980e-18b8a02393af'::uuid, NULL, NULL, E'Students are required to complete the research paper by Monday.', NULL, NULL),
  ('0559456f-8683-5d14-bf61-a1c4a3739795'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0559456f-8683-5d14-bf61-a1c4a3739795'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'acfa47fb-a899-5681-a092-f3925a74e26b'::uuid, NULL, NULL, E'This is what we would call a state of equilibrium.', NULL, NULL),
  ('055b757d-0b40-59a9-9abe-08e9da79af43'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '055b757d-0b40-59a9-9abe-08e9da79af43'::uuid, 1, NULL, TRUE, 0, NULL, E'50 cm - 1 m', NULL, NULL, NULL, NULL, E'1, 2, 4, 3', NULL, NULL),
  ('055c0706-44ee-5316-9f90-7215ec9f863d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '055c0706-44ee-5316-9f90-7215ec9f863d'::uuid, 1, NULL, TRUE, 0, NULL, E'Ecological Balance', NULL, 'e6241288-0367-521b-9f73-492438f5697e'::uuid, NULL, E'Most of the world’s ecosystems are the result of millennia of coevolution by organisms, adapting to their environment and each other until a stable balance is reached. Healthy ecosystems maintain this balance via limiting factors, environmental conditions that restrict the size or range of a species. These include things like natural geography and climate, food availability, and the presence or absence of predators. For example, plant growth depends on levels of sunlight and soil nutrients. The amount of edible plants affects the population of herbivores, which in turn impacts the carnivores that feed on them. And a healthy predator population keeps the herbivores from becoming too numerous and devouring all the plants. But even minor changes in one factor can upset this balance, and the sudden introduction of non-native organisms can be a pretty major change. A species that is evolved in a separate habitat will be susceptible to different limiting factors, different predators, different energy sources, and different climates. If the new habitat’s limiting factors fail to restrict the species growth, it will continue to multiply, out-competing native organisms for resources and disrupting the entire ecosystem. Species are sometimes introduced into new habitats through natural factors, like storms, ocean currents, or climate shifts. The majority of invasive species, though, are introduced by humans.', NULL, NULL, NULL),
  ('055de755-5301-59b3-b628-5e329e81b616'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '055de755-5301-59b3-b628-5e329e81b616'::uuid, 1, NULL, TRUE, 0, NULL, E'Bottled Water', E'Bottled water prevails because of its convenience. Yet, plastic bottles have also caused a lot of environmental problems, so some claim that bottled water should be banned. To what extent do you agree or disagree with that?', NULL, NULL, NULL, NULL, 200, 300),
  ('056119f8-cacd-59c3-972f-9259d5b67469'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '056119f8-cacd-59c3-972f-9259d5b67469'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0f612485-4e1d-5bcd-bb56-337200b8faff'::uuid, NULL, NULL, E'The cafeteria was sold out of coffee on Friday this week.', NULL, NULL),
  ('056a1234-524c-5c5f-9b97-e97a951847e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '056a1234-524c-5c5f-9b97-e97a951847e1'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8ed57cf3-89cd-574e-9f57-ac4e5bacc2f7'::uuid, NULL, NULL, E'A few slots are still available in the most demanded courses.', NULL, NULL),
  ('056d219d-a6bd-5186-a6e6-e31fcee0975e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '056d219d-a6bd-5186-a6e6-e31fcee0975e'::uuid, 1, NULL, TRUE, 0, NULL, E'Open Door Policy', E'The Open Door policy, initially {{1}} by the United States, extends equal commercial and industrial rights to all nations within a specific territory. It {{2}} to ensure that all nations had equal access to China''s markets and resources, and that no single power could {{3}} the country. It was a reflection of the United States'' growing economic power and its desire to {{4}} a more active role in world affairs.', NULL, NULL, NULL, E'1.proposed, 2.sought, 3.dominate, 4.play', NULL, NULL),
  ('056f6a3f-7c80-57fb-b891-a2c5e0f0d274'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '056f6a3f-7c80-57fb-b891-a2c5e0f0d274'::uuid, 1, NULL, TRUE, 0, NULL, E'Nature or Nurture', E'Scientists have been debating the impact of nature and nurture on people''s personality and behavior. Nature brings you inborn skills and nurture helps you obtain skills by practice. Which one do you think has a greater influence?', NULL, NULL, E'The debate over the influence of nature and nurture on people''s personality and behavior has been ongoing for decades. While some argue that nature plays a more significant role in shaping who we are, others believe that nurture has a greater influence. In my opinion, nature has a greater impact on people''s personality and behavior due to its inborn and unchangeable nature.\nFirstly, genetics play a crucial role in determining personality traits such as temperament, emotional stability, and intelligence. Research has shown that identical twins, who share the same genetic makeup, tend to have more similar personalities than fraternal twins or siblings who do not share the same genetic makeup. This suggests that genetics play a significant role in shaping personality traits.\nSecondly, physical appearance, such as height, eye color, and facial features, is largely determined by genetics. While environmental factors such as diet and exercise can influence physical health, they cannot change a person''s genetic makeup. This is further evidence of the powerful influence of nature on human development.\nIn conclusion, while nurture certainly plays an important role in shaping who we are, I believe that nature has a greater impact on people''s personality and behavior due to its inborn and unchangeable nature. By recognizing the significance of nature in shaping who we are, we can better understand ourselves and others, and work towards creating a more accepting and inclusive society.', NULL, 200, 300),
  ('057201c1-2fb9-5d2d-8452-4146c2776488'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '057201c1-2fb9-5d2d-8452-4146c2776488'::uuid, 1, NULL, TRUE, 0, NULL, E'Curriculum', E'The curriculum enhances the general management programme with health-related courses, Dr Schulman says. Required courses include healthcare in the 21st century and the economics and strategy of health-sector management. Students may also take electives such as medical device commercialisation, healthcare marketing and the economics and management of the pharmaceutical industry.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('0576eb42-f53f-5113-bd09-a1fde0385472'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '0576eb42-f53f-5113-bd09-a1fde0385472'::uuid, 1, NULL, TRUE, 0, NULL, E'Engine Knock', NULL, NULL, NULL, NULL, E'2, 1, 4, 3', NULL, NULL),
  ('0582e766-4f5b-52b4-b196-09468c9d036b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0582e766-4f5b-52b4-b196-09468c9d036b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a baby cat?', '0bd20692-62a2-580e-9c8e-e715c3683ad0'::uuid, NULL, NULL, E'Kitten / kitty', NULL, NULL),
  ('05843b87-1269-5075-a5d6-05f3cfda4e2d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '05843b87-1269-5075-a5d6-05f3cfda4e2d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'cec1cc9e-55c6-57ad-90f7-9f22f1ed90f3'::uuid, NULL, NULL, E'Students need to submit both their assignments on the same day.', NULL, NULL),
  ('0585beae-1f28-5dbd-8e6c-782d2bd1b45a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0585beae-1f28-5dbd-8e6c-782d2bd1b45a'::uuid, 1, NULL, TRUE, 0, NULL, E'Babies Expecting Fairness', E'If babies as young as a year and a half old see someone else being treated unfairly, they expect the leader—the parent or caregiver—in that situation to step in and do something about it. "Babies evaluate others constantly." Renée Baillargeon is a psychologist at the University of Illinois. She led the research on babies expecting fairness.\n"When these transgressions occur, babies evaluate parents and other leaders and say, ''Well, you saw this transgression. You know this is not fair. Are you going to do something about it?'' And if you don''t, then you are shirking your responsibilities, and it makes you less of a leader, less of a parent."\nThat''s right, babies are judging you. Baillargeon says it seems babies are born with these expectations of what a leader is and how they should behave. The work is in the Proceedings of the National Academy of Sciences.\n\nWhat can we know from this passage?', 'd51e88e5-21ce-540e-852c-35947334eeef'::uuid, NULL, NULL, E'When something unfair happens, babies judge their parents and other leaders.\nIf parents do nothing about unfairness, babies may think they are escaping from their responsibilities.', NULL, NULL),
  ('0585eede-d763-50a7-be53-e0b3314f4073'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0585eede-d763-50a7-be53-e0b3314f4073'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2582a570-ff02-5fe5-b6ad-522036b684b6'::uuid, NULL, E'Make sure to hand in all assignments by the end of the week.', NULL, NULL, NULL),
  ('0588cdf4-a163-55da-8503-f2fd2ecd6f9b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0588cdf4-a163-55da-8503-f2fd2ecd6f9b'::uuid, 1, NULL, TRUE, 0, NULL, E'Black Hole (B)', NULL, 'bc24401e-0477-5e65-a1c6-4b72efeac6e3'::uuid, NULL, E'We actually have seen more than one of these black hole emergers, and we''ve seen actually two about equally good, although the one that we talked about you can see with your eyes. The second one is the one with the lighter black holes in it. They''re not so heavy, where the ringing is a lot longer, and you can see it without all the fancy data analysis. Then there is a third source, which we''ve already published, but now that we have seen that two of the other one, we also believe that could very well be a black hole here. So we have three sources—let''s call it three sources in three months. Now if we make design sensitivity, we have improved the apparatus by another factor of three. Now how does that translate into rate? It turns out if you look with a sensitivity three times better than we have, you can look three times deeper into the universe. That says the volume of the universe that you are looking at is three to the cube, so that''s about 27 or call it 30 in around the numbers. So instead of seeing one a month of these black hole appears, we should see maybe one every two days, one every day. That''s gonna change the character of how we operate completely. At that moment launched into what I called the astronomy, that''s associated gravitational wave, astronomy. That''s gonna be a big day.', NULL, NULL, NULL),
  ('058e027d-27fa-5638-a7b0-eb4f58462981'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '058e027d-27fa-5638-a7b0-eb4f58462981'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0c27d481-cd1d-5659-b774-bafbdb76f3cc'::uuid, NULL, NULL, E'Photography can be very useful in geographical research.', NULL, NULL),
  ('058e8ba2-45a3-5f65-be05-6e43bbdea776'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '058e8ba2-45a3-5f65-be05-6e43bbdea776'::uuid, 1, NULL, TRUE, 0, NULL, E'Flavonols', E'The cognitive score of people in the study who ate the most flavonols declined 0.4 units per decade more slowly than those who ate the fewest flavonols. The results held even after {{1}} for other factors that can affect memory, such as age, sex and smoking, according to the study recently published in Neurology, the medical journal of the American Academy of Neurology. Flavonols are cytoprotective, meaning they protect cells, including neurons, so it’s {{2}} there could be a direct impact on cognition. Plants contain over 5,000 flavonoid compounds, which play roles in producing cell growth, fighting environmental stress and attracting insects for pollination. Flavonols, a type of flavonoid, have been shown in animal and some human studies to reduce inflammation, a major {{3}} for chronic disease, and are rich sources of antioxidants. They may also be a marker of better overall diet quality, or even greater health {{4}} . People who are more health conscious may do things to preserve their cognition, or maybe being more health conscious is a by-product of better cognition.', NULL, NULL, NULL, E'1.adjusting, 2.plausible, 3.trigger, 4.consciousness', NULL, NULL),
  ('0591bb75-2ea1-5694-a169-ba3eab11b0f2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '0591bb75-2ea1-5694-a169-ba3eab11b0f2'::uuid, 1, NULL, TRUE, 0, NULL, E'Game', NULL, NULL, NULL, NULL, E'3, 4, 5, 2, 1', NULL, NULL),
  ('059d9c9b-ebb6-5fdf-acb0-7a1df53b0fa9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '059d9c9b-ebb6-5fdf-acb0-7a1df53b0fa9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '71b1d95d-f1ee-54ed-b8b0-661d1be86103'::uuid, NULL, E'Their research result has been published on a science website.', NULL, NULL, NULL),
  ('05ad6e7d-f05f-50af-9073-6243852fe200'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '05ad6e7d-f05f-50af-9073-6243852fe200'::uuid, 1, NULL, TRUE, 0, NULL, E'Dissociation of Personalities', NULL, 'a6dcf0d4-b7e5-5f57-b7f2-31e78f17f3b8'::uuid, NULL, E'Morton Prince was an American physician and psychologist, his book ''Dissociation of a Personality'' was the best-seller at that time. It tells a story of Miss Christine Beauchamp, who was suffering from MPD (Multiple Personality Disorder) .\nMiss Christine Beauchamp has several types of personalities, namely B1, B2 and B3. There was hidden memory in these three personalities, with hallucination among them.\nMiss Beauchamp was B2. B2 knows about B1, B3 knows both B1 & B2, but B1 knows nothing about B2 or B3.\nThe strongest personality accounts for most of the time and it will take over the others and become the main personality at the end.\nThis case and theory gives great help to crime investigation.', NULL, NULL, NULL),
  ('05aeb05f-0db7-5d6f-829a-0b84c075a5d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '05aeb05f-0db7-5d6f-829a-0b84c075a5d8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the huge truck that contains oil?', '093a1fac-109f-5fea-8301-cb929af3f3bd'::uuid, NULL, NULL, E'Oil tanker', NULL, NULL),
