  ('05b95cdb-80f4-553f-ac1b-84a505f573c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '05b95cdb-80f4-553f-ac1b-84a505f573c0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bc983563-5d3d-5d25-be86-32970c2f8bf7'::uuid, NULL, E'I can fix the issue but was told to keep it from you.', NULL, NULL, NULL),
  ('05be890c-964a-5843-b9af-6b5f8154aeeb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '05be890c-964a-5843-b9af-6b5f8154aeeb'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Where do people go to watch films for entertainment?', 'ea183483-9c59-53bd-8c0f-4381f4489145'::uuid, NULL, NULL, E'Cinema', NULL, NULL),
  ('05bf03ca-496c-5f54-9713-9c21ff0c684f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '05bf03ca-496c-5f54-9713-9c21ff0c684f'::uuid, 1, NULL, TRUE, 0, NULL, E'Ancient Diamonds', E'Formed millions to billions of years ago, diamonds can shine light into the darkest and oldest parts of the Earth''s mantle. The analysis of ancient, superdeep diamonds dug up from mines in Brazil and Western Africa, has exposed new processes of how continents evolved and moved during the early evolution of complex life on Earth.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('05c60634-a013-56d0-95aa-3deccb6752cc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '05c60634-a013-56d0-95aa-3deccb6752cc'::uuid, 1, NULL, TRUE, 0, NULL, E'Sea Combine', E'Often used to wrap sushi and flavor soups, seaweed has much greater {{1}} – both as a food and for use in a wide range of products from cosmetics and textiles to biodegradable packaging and even biofuel. Usually, seaweed is grown on ropes or nets {{2}} in the ocean, but current techniques make large-scale cultivation near impossible. The price of seaweed restricts its potential uses and in the current market, it’s often only economically {{3}} to use seaweed for high-priced food applications. Founded in 2010, Sea Energy wants to mechanize ocean farming, just as tractors did for agriculture, with its “Sea Combine,” an automated catamaran that simultaneously harvests and replants seaweed in the ocean. Suryanarayan hopes the Sea Combine will cut costs and make seaweed cheaper, so it can be more widely used. The machine travels back and forth between lines of seaweed, {{4}} the fully-grown plants and replacing them with freshly-seeded lines. As the technology develops and the market widens, the company intends to {{5}} more Sea Combines, including in its home country, India.', NULL, NULL, NULL, E'1.potential, 2.suspended, 3.viable, 4.harvesting, 5.deploy', NULL, NULL),
  ('05c66284-a622-546e-956a-d75d0f15a2e7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '05c66284-a622-546e-956a-d75d0f15a2e7'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'dc4c5d66-48fb-51ba-bfba-60ee197e45cd'::uuid, NULL, E'Studies have indicated that there is a relationship between diet and cancer.', NULL, NULL, NULL),
  ('05cdc396-ed0f-5078-9a6f-febce2783e49'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '05cdc396-ed0f-5078-9a6f-febce2783e49'::uuid, 1, NULL, TRUE, 0, NULL, E'Dog''s Breed', E'Your dog’s behavior probably isn’t due to its breed, according to a large-scale genetic analysis. The findings suggest that stereotypes {{1}} with certain breeds have little basis. Kathleen Morrill at the University of Massachusetts and her colleagues studied the DNA of more than 2000 dogs using a genome-wide analysis. The team wanted to determine if any common genetic {{2}} could be linked to behaviors typically associated with particular dog types. In other words, could genetics explain why Rottweilers often seem so aggressive or why Border collies are thought of as sociable? The researchers combined this analysis with survey responses from the owners of more than 18,000 dogs, mostly from the US, who had been asked to {{3}} the behaviour of their pets. After collecting all this information, the team focused their analysis on the differences between pure-bred and cross-bred dogs.', NULL, NULL, NULL, E'1.associated, 2.variations, 3.detail', NULL, NULL),
  ('05d1f78c-e3ad-55c9-ae1e-dfa4a878a136'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '05d1f78c-e3ad-55c9-ae1e-dfa4a878a136'::uuid, 1, NULL, TRUE, 0, NULL, E'Denmark’s Green Hydrogen', E'These giants of renewable energy tower over the Danish countryside. Here in Brande, a pioneering project offers what might be a glimpse of the future. This enormous turbine is harnessing energy from the wind – and that power is being used to produce another type of clean fuel – hydrogen gas. The pilot plant isn’t connected to the grid. And the green hydrogen made here supplies local taxis. Poul Skjaerbaek, a Chief Innovation Officer from Siemens Gamesa said, “We can produce a maximum, like, eight kilos per hour with the equipment you see behind me here. So, it’s, of course, extremely small. Nevertheless, eight kilos is actually what a car could drive, like, eight hundred kilometres on.”\nThe need to slash our carbon emissions has brought hydrogen increasingly into focus. The good thing with hydrogen, when you burn it, you actually do not get the CO2 emissions, so what comes out of the exhaust is water, instead of all the nasty stuff we see today.\nToday, most hydrogen, about 95%, is made using fossil fuels. Green hydrogen, however, is produced from water and renewable electricity. This facility in Kolding makes electrolysers – the technology needed to produce it. Hydrogen has been touted as a climate solution before – but it hasn’t really taken off. Proponents say it’s a different picture today. Dozens of new green hydrogen plants are now on the horizon. But much needs to be done if the hopes for this new clean fuel can live up to the hype.', NULL, NULL, NULL, NULL, 5, 75),
  ('05d245ae-ef92-581b-87c9-305a329597a3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '05d245ae-ef92-581b-87c9-305a329597a3'::uuid, 1, NULL, TRUE, 0, NULL, E'Power Mix', E'Imagine a time in the not too distant future when your power comes from a seamless mix of renewable energy and traditional sources. It is delivered by a grid that manages thousands of windmills and hundreds of thousands of customers. Computer {{1}} , the grid is able to manage instant variations in supply and demand and provides a real time power balance.\nFar more complex than anything {{2}} existence today, it is called a smart grid. This technology is a new frontier in power supply and seen as a green solution to current outdated management systems. When introduced smart grids will result in energy savings and will allow consumers a choice in their electricity charges and to be able to select the cheapest time {{3}} . The difficulty for the energy industry is that smart grids {{4}} in reality and the power companies cannot experiment with existing supplies.\nWithout an actual grid to conduct research on Professor Wu has had to design a simulated laboratory including input from theoretical wind generators and solar panels to feed into a constantly operating system. For an authentic approach researchers built various types of equipment failures {{5}} the grid to test the system.\nAnd it works.', NULL, NULL, NULL, E'1.controlled, 2.in, 3.slots, 4.do not exist, 5.into', NULL, NULL),
  ('05d79726-dc2e-524e-a00d-f6f4af6662f4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '05d79726-dc2e-524e-a00d-f6f4af6662f4'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e3007cc3-e3cf-54ad-a3a1-bfe2134e90a1'::uuid, NULL, E'It is expected that all students have their own laptops.', NULL, NULL, NULL),
  ('05da4f54-c997-5156-a623-f4518d95be15'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '05da4f54-c997-5156-a623-f4518d95be15'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2aed6f2b-8a86-5fa7-9996-3f7402ec6a6d'::uuid, NULL, E'My mom made a milkshake with frozen bananas and chocolate sauce.', NULL, NULL, NULL),
  ('05eacf93-c71a-5931-b877-08a1b62da2b7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '05eacf93-c71a-5931-b877-08a1b62da2b7'::uuid, 1, NULL, TRUE, 0, NULL, E'Pension Schemes', E'Clearly, times are changing and while many people are saving for their retirement, many more still need to do so. Most countries have a range of pension schemes that are designed to provide individuals with an income once they stop working. People need to take advantage of these if they are to have sufficient money throughout their retirement years.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('05eda03c-1b87-5d71-8577-bc2fa617f664'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '05eda03c-1b87-5d71-8577-bc2fa617f664'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ac1c4443-cc15-5f83-baf2-20e0d783461b'::uuid, NULL, NULL, E'When bad drove out good, the local workers were more difficult than their competitors.', NULL, NULL),
  ('05f0f6da-4b94-5b46-92ec-edcba7f76751'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '05f0f6da-4b94-5b46-92ec-edcba7f76751'::uuid, 1, NULL, TRUE, 0, NULL, E'The Nobel Academy', NULL, '7f81532f-8ae1-52cf-993e-56ee3eeb6aaa'::uuid, NULL, E'For the last 82 years, Sweden''s Nobel Academy has decided who will receive the Nobel Prize in Literature, thereby determining who will be elevated from the great and the near great to the immortal. But today the Academy is coming under heavy criticism both from the without and from within. Critics contend that the selection of the winners often has less to do with true writing ability than with the peculiar internal politics of the Academy and of Sweden itself. According to Ingmar Bjorksten , the cultural editor for one of the country''s two major newspapers, the prize continues to represent "what people call a very Swedish exercise: reflecting Swedish tastes."\nThe Academy has defended itself against such charges of provincialism in its selection by asserting that its physical distance from the great literary capitals of the world actually serves to protect the Academy from outside influences. This may well be true, but critics respond that this very distance may also be responsible for the Academy''s inability to perceive accurately5 authentic trends in the literary world.\nRegardless of concerns over the selection process, however, it seems that the prize will continue to survive both as an indicator of the literature that we most highly praise, and as an elusive8 goal that writers seek. If for no other reason, the prize will continue to be desirable for the financial rewards that accompany it; not only is the cash prize itself considerable, but it also dramatically increases sales of an author''s books.', NULL, NULL, NULL),
  ('05f13c0a-6d9a-5dcf-9204-8349b8e51ec9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '05f13c0a-6d9a-5dcf-9204-8349b8e51ec9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5b614993-45ea-526c-95ea-22c3bbc450d7'::uuid, NULL, NULL, E'The company has adopted a firm policy on shoplifting.', NULL, NULL),
  ('05fff9ec-3062-513c-afaa-7b28ea34aec7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '05fff9ec-3062-513c-afaa-7b28ea34aec7'::uuid, 1, NULL, TRUE, 0, NULL, E'Happy Sounds', E'Research published in the journal of Neuroscience suggests that happy sounds, such as laughter, are infectious. When people hear these sounds, their brains activate the premotor cortical region, which prepares facial muscles to move. This may explain why laughter and other happy sounds can spread so easily from person to person.', NULL, NULL, NULL, NULL, NULL, NULL),
