  ('061a0d2f-9d7b-5571-8b0b-b611f471079b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '061a0d2f-9d7b-5571-8b0b-b611f471079b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Name a country located in North America?', '33b5fcba-2055-5725-b679-1157f16611d1'::uuid, NULL, NULL, E'The United States of America / Canada', NULL, NULL),
  ('061bebb2-00ba-55a6-b575-e505c7eb58d2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '061bebb2-00ba-55a6-b575-e505c7eb58d2'::uuid, 1, NULL, TRUE, 0, NULL, E'Worsened Inequality', E'The COVID-19 pandemic and related shutdowns are challenging the effectiveness of civil and institutional structures around the world, resulting in interrelated crises for foreign policy, development, and economics. Inequality has consequently worsened, both within and across borders, with fiscal and monetary policies exacerbating inequality by favoring the rich while leaving poorer people and countries behind.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('061d4d02-2e8b-553b-a0eb-74a44bbf778c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '061d4d02-2e8b-553b-a0eb-74a44bbf778c'::uuid, 1, NULL, TRUE, 0, NULL, E'Coffee Cup Lid', NULL, '424aff8b-1fd2-5d8d-9d22-4b018960801e'::uuid, NULL, E'Our society is just more and more mobile. Everything is on the move. I mean, the good part, it’s convenient. You can drink coffee anywhere. You don’t have the stay in the dinner. It can be in the subway. You can be walking. The bad part is it’s harder to savor a coffee when you’re taking it on the road. The first patent for a lid on a cup was in 1934, but it was for cold beverages, and in 1950 this guy names James Reifsnyder invented the first snap-on lid, but it didn’t have an opening for drinking. In the ’60s there was this huge cultural shift where people started drinking coffee on the move, and 7-Eleven was the first to sell coffee to go. And then came this revolution. In 1967, a man named Alan Frank invented a lid that you could peel a tab off, like in the shape of a guitar pick and drink it from there. In 1975, another big advance, you could peel back a tab and attach it to the lid itself. So more and more people started drinking coffee on the go. In 1984, a watershed moment in the history of coffee cup lids, the birth of the traveler lid, and it is iconic. You’ve seen it a million times, and it solved a whole host of problems. It’s designed so that you don’t splash your face, because it’s higher than any of the other ones. It’s got this protruding rim, so it slightly cools the coffee before it hits your lips. It’s got a small depression in the center for your nose, so you can really get in there and get maximum aroma. It’s got this tiny air hole that lets the steam out and stops it from creating a vacuum. This is one of those objects where you just don’t notice it until it dribbles on your lap, so I think the coffee cup lid will just continue to evolve, and you’re gonna see a move away from single-use plastic lids to lids that are a little more sustainable.', NULL, NULL, NULL),
  ('061fc944-6edb-5b31-83d7-5b4554d74c2e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '061fc944-6edb-5b31-83d7-5b4554d74c2e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person undergoing illness?', 'ea993bfe-a9d3-5979-958c-411f9ee2bed1'::uuid, NULL, NULL, E'Patient', NULL, NULL),
