  ('062325fe-ee53-5119-ab78-440991af2562'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '062325fe-ee53-5119-ab78-440991af2562'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '41304324-f747-5352-8f90-7f25ddca9733'::uuid, NULL, E'Due to the rising demand for courses, the university should also increase their academic staff.', NULL, NULL, NULL),
