  ('0727f35f-c009-5e62-bef5-fd7e8e161451'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0727f35f-c009-5e62-bef5-fd7e8e161451'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd71e9a10-1b2c-5f27-aa88-b73d8f65ff08'::uuid, NULL, NULL, E'Deforestation increases as the number of people in the world grows.', NULL, NULL),
