  ('072e0220-51f7-5311-aa1f-ce5399225f61'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '072e0220-51f7-5311-aa1f-ce5399225f61'::uuid, 1, NULL, TRUE, 0, NULL, E'COVID-19', E'The term “excess deaths” describes deaths {{1}} what would have been expected under “normal” conditions. It captures not only confirmed deaths, but also COVID-19 deaths that were not correctly diagnosed and reported as well as deaths {{2}} to the overall crisis conditions. This provides a more {{3}} and accurate measure when compared with confirmed COVID-19 deaths alone.', NULL, NULL, NULL, E'1.beyond, 2.attributable, 3.comprehensive', NULL, NULL),
