  ('073b74b3-3ab3-5cbd-9568-c6baacae2423'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '073b74b3-3ab3-5cbd-9568-c6baacae2423'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'bb0ea613-b0a7-55a8-bc17-ee4dde7371c2'::uuid, NULL, NULL, E'The program has been successful since its inception.', NULL, NULL),
  ('07408bfa-bc92-567f-8af8-d48658e29c87'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '07408bfa-bc92-567f-8af8-d48658e29c87'::uuid, 1, NULL, TRUE, 0, NULL, E'Shakespeare', E'Shakespeare is widely regarded as the greatest playwright of all time, but he did not create his stories by {{1}} . He borrowed and adapted the plots of his plays from various sources, such as old tales, Italian writers, prose fictions, historical accounts, and classical works. He was a {{2}} reader who had a moderate acquaintance with the literary achievements of other men and of other ages. He read books in different languages and genres, and was influenced by some of his contemporaries such as Marlowe, Spenser, and Sidney. However, Shakespeare was not a {{3}} imitator or plagiarist. He transformed his sources by excluding undramatic material, developing characters, rearranging the plot, introducing a wider philosophical {{4}} , and elevating the dialogue and the imaginative writing. He infused his plays with his own genius, creativity, and originality, making them unique and timeless. He also added his own touches of humor, irony, and tragedy, creating a rich and complex dramatic experience for his audiences. Shakespeare’s plays are not just {{5}} of his sources, but masterpieces of his own.', NULL, NULL, NULL, E'1.himself, 2.keen, 3.mere, 4.outlook, 5.copies', NULL, NULL),
  ('07469392-7a72-561e-ba33-960352b19c2f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '07469392-7a72-561e-ba33-960352b19c2f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e0135957-8f7d-5eaa-826d-c24a4d58d731'::uuid, NULL, E'The law library is closed on Sundays and public holidays.', NULL, NULL, NULL),
  ('074b0533-b0ad-56a5-b464-6117b8aca830'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '074b0533-b0ad-56a5-b464-6117b8aca830'::uuid, 1, NULL, TRUE, 0, NULL, E'Lifelong Learning', E'Lifelong learning is essential for personal growth, career development, and staying up-to-date with new technologies and trends. It helps individuals develop new skills, pursue new interests, and adapt to changing circumstances. Lifelong learning opportunities are available through formal education programs, online courses, workshops, and other learning resources.', NULL, NULL, NULL, NULL, NULL, NULL),
