  ('076384fe-9380-5f09-a02d-47fca8ac989b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '076384fe-9380-5f09-a02d-47fca8ac989b'::uuid, 1, NULL, TRUE, 0, NULL, E'AI Capabilities', E'Artificial Intelligence is rapidly {{1}} our world. Remarkable surges in AI capabilities have led to a wide range of {{2}} including autonomous vehicles and connected Internet of Things devices in our homes. AI is even {{3}} to the development of a brain-controlled robotic arm that can help a paralyzed person feel again.', NULL, NULL, NULL, E'1.transforming, 2.innovations, 3.contributing', NULL, NULL),
  ('0766a117-a790-54c6-9376-d45393de1f75'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '0766a117-a790-54c6-9376-d45393de1f75'::uuid, 1, NULL, TRUE, 0, NULL, E'Overpackage', E'Do you think consumers should avoid over-packaged products or is it the responsibility of manufacturers to avoid extra packaging? Give your views or any relevant examples based on your own experience.', NULL, NULL, NULL, NULL, 200, 300),
  ('0768bdce-9930-5cd5-a335-11bab1acc5b0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0768bdce-9930-5cd5-a335-11bab1acc5b0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '88fdd3e4-e054-5d62-ad99-ce8541766a13'::uuid, NULL, E'You can pay by cash or using a credit card.', NULL, NULL, NULL),
  ('07690546-4a3c-5670-9a94-bb7413261af9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '07690546-4a3c-5670-9a94-bb7413261af9'::uuid, 1, NULL, TRUE, 0, NULL, E'Oldest Tortoise', E'He was alive when the first photograph of a person was taken (1838); now he poses for selfies with adoring tourists. He was born before the creation of the postage stamp (1840), and now {{1}} on them. He is Jonathan, the world''s oldest tortoise. And he’s celebrating his 190th birthday. Jonathan marked the occasion with a three-day birthday party over the weekend at his home on the South Atlantic island and British overseas territory St. Helena, where he’s spent the majority of his long life (minus the first 50 years or so). Jonathan is believed to have been born in 1832, but could potentially be even older. His {{2}} age is based on the fact that he was fully mature when he was brought to St. Helena from the Seychelles in 1882 as a gift to its then-governor. And an old photograph of a fully grown Jonathan {{3}} on grass at the governors’ residence -- called Plantation House -- sometime between 1882 and 1886 further supports that theory, according to Guinness World Records.', NULL, NULL, NULL, E'1.appears, 2.estimated, 3.grazing', NULL, NULL),
  ('076a30a6-83dd-58fa-8171-bf33e49714d1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '076a30a6-83dd-58fa-8171-bf33e49714d1'::uuid, 1, NULL, TRUE, 0, NULL, E'Balanced Lifestyle', NULL, 'b9d7c7da-f45c-5ff9-89b7-0a82ca42e492'::uuid, NULL, E'As we embark on our educational journey, the importance of a balanced lifestyle becomes ever more apparent. It is the keystone that supports not just academic success, but holistic well-being. A balanced lifestyle incorporates proper nutrition, which fuels both body and mind, essential for optimal cognitive function and energy levels. The American College Health Association reports that students who consume a balanced diet perform better academically than those who do not. Equally crucial is physical activity. Regular exercise releases endorphins, known as the ''feel-good'' hormones, which reduce stress and anxiety. In a study by the Journal of Exercise Science & Fitness, students who engaged in regular physical activity had significantly lower stress levels. By intertwining good nutrition and regular exercise into our daily routines, we forge a foundation of health that sustains us through our studies and beyond. Let''s strive to cultivate these habits, ensuring we are as healthy in body as we are keen in mind.', NULL, NULL, NULL),
  ('0781c9c1-ec41-55f9-b49c-749076f4fcaa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0781c9c1-ec41-55f9-b49c-749076f4fcaa'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'bf3a926c-79f3-5cb8-9745-465229faea4c'::uuid, NULL, NULL, E'Parents often simplify their vocabulary when speaking with their kids.', NULL, NULL),
  ('0782d55e-4a67-5add-8de4-88658eb4bcad'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0782d55e-4a67-5add-8de4-88658eb4bcad'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '051b5f16-9785-5b61-a6c2-e6304381055d'::uuid, NULL, E'The university policy on plagiarism can be viewed on the website.', NULL, NULL, NULL),
  ('07904cae-d25e-5ab7-8564-f259afef1d6c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '07904cae-d25e-5ab7-8564-f259afef1d6c'::uuid, 1, NULL, TRUE, 0, NULL, E'The Javan Warty Pig', E'Scientists have captured the first footage in the wild of one of the world''s rarest - and ugliest - pigs. The Javan warty pig is under such threat from hunting and habitat loss that conservationists surveying its habitat believed it might already have been driven to extinction. Camera traps have now revealed that small populations survive in Java''s increasingly fragmented forests.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('07904d46-92de-58b2-ace6-0c0c3dc9d99d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '07904d46-92de-58b2-ace6-0c0c3dc9d99d'::uuid, 1, NULL, TRUE, 0, NULL, E'Folklore', E'Folklore, a modern term for the {{1}} of traditional customs, superstitions, stories, dances, and songs that have been adopted and maintained within a given {{2}} by processes of repetition is not reliant on the written word. Along with folk songs and folktales, this broad {{3}} of cultural forms embraces all kinds of legends, riddles, jokes, proverbs, games, charms, omens, spells, and rituals, especially those of pre-literate societies or social classes. Those forms of verbal expression that are handed on from one generation or locality to the next by {{4}} of mouth are said to constitute an oral {{5}} .', NULL, NULL, NULL, E'1.body, 2.community, 3.category, 4.word, 5.tradition', NULL, NULL),
