  ('07b17a25-2e62-52b2-832f-3fdf0140de08'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '07b17a25-2e62-52b2-832f-3fdf0140de08'::uuid, 1, NULL, TRUE, 0, NULL, E'Golden Gate Bridge', E'San Francisco''s Golden Gate Bridge, a stunning technological and artistic achievement, {{1}} to the public after five years of construction. {{2}} opening day – ''Pedestrian Day'' – some 200,000 bridge walkers {{3}} at the 4,200-foot-long suspension bridge, which spans the Golden Gate Strait at the entrance to San Francisco Bay and {{4}} San Francisco and Marin County. On May 28, the Golden Gate Bridge opened to {{5}} traffic. On May 27, 1937, the Golden Gate Bridge was opened to great acclaim, a {{6}} of progress in the Bay Area during a time of economic crisis. At 4,200 feet, it was the longest bridge in the world {{7}} the completion of New York City''s Verrazano-Narrows Bridge in 1964. Today, the Golden Gate Bridge remains one of the world''s most recognizable architectural structures.', NULL, NULL, NULL, E'1.opens, 2.On, 3.marveled, 4.connects, 5.vehicular, 6.symbol, 7.until', NULL, NULL),
  ('07b3c5e0-ec8d-57b9-bdcc-93bb77dd2883'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '07b3c5e0-ec8d-57b9-bdcc-93bb77dd2883'::uuid, 1, NULL, TRUE, 0, NULL, E'Ministerial Staff', E'The contemporary ministerial staffing system is large, active and partisan — far larger and further evolved than any Westminster equivalent. Ministers'' demands for help to cope with the pressures of an increasingly competitive and professionalised political environment have been key drivers of the staffing system''s development. But there has not been commensurate growth in {{1}} to support and control it. The {{2}} framework for ministerial staff is {{3}} and ad hoc.', NULL, NULL, NULL, E'1.arrangements, 2.operating, 3.fragmented', NULL, NULL),
  ('07b51fa2-b52f-5772-b4e9-6dcef8ef78dc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '07b51fa2-b52f-5772-b4e9-6dcef8ef78dc'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the study of the origin and development of the universe?', '3a78a8ef-ff77-599e-95ca-23974638cfa0'::uuid, NULL, NULL, E'Cosmology', NULL, NULL),
