  ('07f7ec26-af37-501d-b3c7-944c92aff7c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '07f7ec26-af37-501d-b3c7-944c92aff7c0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '248fe478-1f0c-5ead-a502-f9f1d7cbed24'::uuid, NULL, E'This office is for students who want to study abroad.', NULL, NULL, NULL),
  ('07fe2829-9eec-549b-bbb1-c6cba5f8be10'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '07fe2829-9eec-549b-bbb1-c6cba5f8be10'::uuid, 1, NULL, TRUE, 0, NULL, E'Alcohol', E'Alcohol is a toxic and psychoactive substance with dependence-producing properties. In many of today’s societies, alcoholic beverages are a routine part of the social {{1}} for many in the population. This is particularly true for those in social environments with high visibility and societal influence, nationally and internationally, where alcohol frequently {{2}} socializing. In this context, it is easy to {{3}} or discount the health and social damage caused or contributed to by drinking. Overall, harmful use of alcohol is responsible for 5.1% of the global burden of disease. Harmful use of alcohol is {{4}} for 7.1% and 2.2% of the global burden of disease for males and females respectively. Alcohol is the leading risk factor for premature mortality and disability among those aged 15 to 49 years, accounting for 10% of all deaths in this age group.', NULL, NULL, NULL, E'1.landscape, 2.accompanies, 3.overlook, 4.accountable', NULL, NULL),
  ('07fe43b5-31ee-5d7c-9eae-b056b3b92699'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '07fe43b5-31ee-5d7c-9eae-b056b3b92699'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8e0b4dff-5de7-5a31-bf75-53e172dec462'::uuid, NULL, NULL, E'He is determined to go abroad to pursue his further study.', NULL, NULL),
  ('07ff1019-0a03-5335-b23c-8c974faffe7d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '07ff1019-0a03-5335-b23c-8c974faffe7d'::uuid, 1, NULL, TRUE, 0, NULL, E'Field Trip', E'Listen to a conversation between two students on a field trip. Look, isn''t that a house finch? Know? I think it''s just a little brown sparrow. It seems reddish to me. And its song is like a recording. We heard of a house finch. Professor flynn said we''d probably see a lot of red finches today. Well, maybe you''re right. We''d better write it down anyway. But I still say it''s too brown to be a house finch. I''ll put a question mark by it. We''re sure seen enough starling. I didn''t even know they lived in the city. I can remember hearing my cousin complain about how the starling is always ate all the fruit in their orchard. They are kind of pretty though. Don''t you think? Look at all the black mixed with a little green making their feathers look iridescent.\n\nWhat can be inferred about starlings?', '259bfc2f-a404-58f7-bb94-770b4e06b630'::uuid, NULL, NULL, E'They live in rural and urban areas.\nThey are a problem for fruit growers.', NULL, NULL),
