  ('0811bde3-c995-51ee-908e-24101f18e72e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '0811bde3-c995-51ee-908e-24101f18e72e'::uuid, 1, NULL, TRUE, 0, NULL, E'Empirical Studies', E'Empirical studies have delineated a dual-edged nature of computer gaming, presenting both beneficial and {{1}} outcomes. On the positive front. These games often require players to engage in critical thinking, plan ahead, and adapt to rapidly changing situations, {{2}} stimulating cognitive development and executive function skills. Conversely, concerns have been raised about potential adverse effects, particularly {{3}} violent video games and their correlation with aggressive behavior and desensitization to violence. The theory of social learning posits that consistent exposure to aggressive models in video games can lead to the internalization of aggressive norms, manifesting in increased physical aggression and reduced empathy. Additionally, the immersive nature of many games can lead to {{4}} lifestyle habits, contributing to obesity and related health issues. The academic discourse surrounding the effects of computer games on children is ongoing, with the consensus acknowledging the need for a balanced approach. This involves recognizing the potential for cognitive and social skill development through selective game genres while instituting boundaries to {{5}} exposure to harmful content and prevent problematic gaming behaviors.', NULL, NULL, NULL, E'1.detrimental, 2.thereby, 3.regarding, 4.sedentary, 5.mitigate', NULL, NULL),
  ('081514e7-714c-57d2-89a5-49cef0cf66b4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '081514e7-714c-57d2-89a5-49cef0cf66b4'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call a flight that you buy for going and return?', 'fb849637-7202-5bb7-a2be-bf48c5116871'::uuid, NULL, NULL, E'Round trip', NULL, NULL),
  ('08174d87-0899-5493-9932-b414fbeb0d69'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '08174d87-0899-5493-9932-b414fbeb0d69'::uuid, 1, NULL, TRUE, 0, NULL, E'Parenting', E'The decision to become a parent should not be {{1}} lightly. There are positives and negatives {{2}} with parenting that should be considered. Many parents report that having children increases their well-being. Researchers have also found that parents, {{3}} to their non-parent peers, are more positive about their lives.', NULL, NULL, NULL, E'1.taken, 2.associated, 3.compared', NULL, NULL),
