  ('08849c54-a03e-5722-b0bf-4a24b264b9fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '08849c54-a03e-5722-b0bf-4a24b264b9fb'::uuid, 1, NULL, TRUE, 0, NULL, E'Genes and Evolution', NULL, '97ecd677-6171-585f-844a-46c88464b069'::uuid, NULL, E'So the pace, at which human minds have evolved over the last half million years and more recently the last 200,000 years, has been so frighteningly rapid that the evolution of cognitive function and perception can only occur in a small number of genes. If one needed to adapt dozens of genes changes in concert, in order to acquire the penetrating minds that we now have, which our ancestors 5,000 years ago didn''t have, the evolution could not have taken place, it could not have occurred so quickly. And for that reason alone, one begins to really suspect that the genetic differences between people who lived 5,000 years ago is evidence that the difference between their cognitive functions and ours is not actually as large. Therefore, a rather small number of genes may be responsible for the powerful minds that humans have which most of us now possess.', NULL, NULL, NULL),
  ('08851ac7-61f6-59a4-956e-aff475f00507'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '08851ac7-61f6-59a4-956e-aff475f00507'::uuid, 1, NULL, TRUE, 0, NULL, E'Drivers licenses(驾照)', NULL, NULL, NULL, NULL, E'4, 3, 5, 1, 2', NULL, NULL),
