  ('088d6c49-b87a-5b91-ac5e-7b71f1315356'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '088d6c49-b87a-5b91-ac5e-7b71f1315356'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the document in which a political party announces their plans before elections?', '9d63ddf0-56af-5a0c-8594-f3f57d81c508'::uuid, NULL, NULL, E'Manifesto', NULL, NULL),
  ('088fa6c7-407e-5287-840a-fc72bb5b8f47'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '088fa6c7-407e-5287-840a-fc72bb5b8f47'::uuid, 1, NULL, TRUE, 0, NULL, E'Claude Monet', E'Claude Monet, a celebrated figure in the Impressionist movement, significantly influenced French art in the late 1800s. He''s {{1}} for his beautiful water lilies and Japanese footbridge scenes, which brilliantly play with light and color. His use of quick, distinct brushstrokes creates a lively effect on the canvas. Notably, his series on the Rouen Cathedral {{2}} the building in various atmospheric conditions, capturing different moments of the day. Monet''s paintings are more than just visually stunning; they marked a major departure from traditional artistic methods. Gone were the smooth finishes and precise outlines of academic art. {{3}} , Impressionists like Monet employed newly available, portable paint tubes to work outdoors and capture fleeting effects directly on the scene. Many critics initially derided their unusual, unfinished style. Yet the Impressionists {{4}} , influencing subsequent generations with their novel painting techniques {{5}} on vivid light and an illusion of spontaneity.', NULL, NULL, NULL, E'1.renowned, 2.showcases, 3.Instead, 4.persevered, 5.focused', NULL, NULL),
  ('0892a2f4-77f9-5b16-b484-afb8678af47d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '0892a2f4-77f9-5b16-b484-afb8678af47d'::uuid, 1, NULL, TRUE, 0, NULL, E'Leadership', E'Leadership is all about being granted permission by others to lead their thinking. It is a bestowed moral authority that gives the right to organize and direct the efforts of others. But moral authority does not come from simply managing people effectively or communicating better or being able to motivate. It comes from many {{1}} , including being authentic and genuine, having integrity, and showing a real and deep understanding of the business in question. All these {{2}} build confidence. Leaders lose moral authority for three reasons: they behave {{3}} , they become plagued by self-doubt and lose their conviction, or they are blinded by power, lose self-awareness and thus lose {{4}} with those they lead as the context around them changes. Having said all this, it has to be assumed that if someone becomes a leader, at some point they understood the difference between right and wrong. It is up to them to {{5}} by a moral code and up to us to ensure that the moment we suspect they do not, we fire them or vote them out.', NULL, NULL, NULL, E'1.sources, 2.factors, 3.unethically, 4.connection, 5.abide', NULL, NULL),
  ('0893345f-192a-561e-acf9-0c20af2f1401'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0893345f-192a-561e-acf9-0c20af2f1401'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8023c0cb-606e-530e-a7cd-e72fa29813a7'::uuid, NULL, NULL, E'Most products are affected in terms of demand, pricing, and consumption.', NULL, NULL),
  ('08981516-aec6-5aa1-8e1d-b661d80e5906'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '08981516-aec6-5aa1-8e1d-b661d80e5906'::uuid, 1, NULL, TRUE, 0, NULL, E'Bipolar Disorder', NULL, '9da88774-a963-5ec5-be48-405c98a0a2e1'::uuid, NULL, E'What is bipolar disorder? The word bipolar means two extremes. For the many millions experiencing bipolar disorder around the world, life is split between two different realities – elation and depression. Although there are many variations of bipolar disorder, let’s consider a couple. Type 1 has extreme highs alongside the lows, while Type 2 involves briefer, less extreme periods of elation interspersed with long periods of depression. For someone seesawing between emotional states, it can feel impossible to find the balance necessary to lead a healthy life. Type 1''s extreme highs are known as manic episodes, and they can make a person range from feeling irritable to invincible. But these euphoric episodes exceed ordinary feelings of joy, causing troubling symptoms like racing thoughts, sleeplessness, rapid speech, impulsive actions, and risky behaviors. Without treatment, these episodes become more frequent, intense, and take longer to subside.', NULL, NULL, NULL),
  ('08a75075-411b-5755-97c0-1b7786af0bd4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '08a75075-411b-5755-97c0-1b7786af0bd4'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What kind of food that vegetarians do not eat?', '7c5c96bf-0ff4-5cd9-ae06-08c9dd7d9dd5'::uuid, NULL, NULL, E'Meat', NULL, NULL),
