  ('08d2cd2f-3f72-5347-9c8c-dd95008d0b4e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '08d2cd2f-3f72-5347-9c8c-dd95008d0b4e'::uuid, 1, NULL, TRUE, 0, NULL, E'Solar Arts', E'Artists have recently started depicting solar power''s potential through visual art. One exhibition features a series of paintings that represent solar panels {{1}} sunlight into energy. The artworks use {{2}} colors and geometric patterns to symbolize the transition from fossil fuels to sustainable solar energy. These pieces aim to make the concept of solar power more {{3}} and accessible to the public, {{4}} a deeper appreciation for renewable energy sources.', NULL, NULL, NULL, E'1.transforming, 2.vibrant, 3.tangible, 4.inspiring', NULL, NULL),
  ('08db5412-532f-56ca-9283-e42271394c62'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '08db5412-532f-56ca-9283-e42271394c62'::uuid, 1, NULL, TRUE, 0, NULL, E'Long Team-Focused Message', E'A report, blog, podcast or document- sharing repository could handle the amount of information, but each would have some {{1}} . Reports are good for large amounts of data but are not interactive in nature. Podcasts would also be good for the first viewing, but they are static, and the information is not searchable. A blog could be a good answer because it could become a “living” document for team members to {{2}} as more information about the competitor’s product become available. The drawbacks of using a blog in this {{3}} would be managing hundreds of such blogs being used for multiple topics as well as quickly finding the blog you want in the corporate wiki. The same drawbacks could be in play with standard document-sharing technology when you have hundreds or thousands of emails or documents to {{4}} .', NULL, NULL, NULL, E'1.drawbacks, 2.append, 3.scenario, 4.handle', NULL, NULL),
  ('08e3cfab-ae69-5317-bc40-5c67a65e2b5a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '08e3cfab-ae69-5317-bc40-5c67a65e2b5a'::uuid, 1, NULL, TRUE, 0, NULL, E'The 1960s and 1970s(60、70年代)', NULL, NULL, NULL, NULL, E'2, 5, 1, 3, 4', NULL, NULL),
