  ('09077c10-e6f6-549c-b41a-3baad4bd69b5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '09077c10-e6f6-549c-b41a-3baad4bd69b5'::uuid, 1, NULL, TRUE, 0, NULL, E'Low Morale', E'You''re the head of a small department in a company, and you''ve noticed that the team''s morale has been low due to the high workload and tight deadlines. You want to address the issue to motivate them and discuss potential solutions to manage the workload more effectively without overwhelming anyone. What would you say to your team?', '7e74f58d-2729-5672-ba45-308ff23a9738'::uuid, NULL, E'Hey team, I''ve noticed we''ve all been feeling the heat with our recent workload and deadlines. I get it and I appreciate every bit of effort you''ve put in. Let''s have a chat about this in our next meeting, alright? I''m thinking we can brainstorm some ways to manage our tasks better. Maybe we can prioritize our projects or even discuss flexible working hours. Your well-being is our top priority.', NULL, NULL, NULL),
  ('0907e783-3c23-587e-8eff-2ca43cde5e3b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0907e783-3c23-587e-8eff-2ca43cde5e3b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '1e97d1fc-2fa8-5e58-ad68-080124f9fed2'::uuid, NULL, E'Please make an appointment before attending the next meeting.', NULL, NULL, NULL),
  ('09091891-b809-5e6e-b5b9-877931b20ad7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '09091891-b809-5e6e-b5b9-877931b20ad7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5e46c779-f939-5e07-a812-92b40615fd78'::uuid, NULL, NULL, E'Their most valuable belongings were locked in a safe.', NULL, NULL),
  ('0909bb0b-d7a4-5df2-bc4c-2849fa0c7003'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '0909bb0b-d7a4-5df2-bc4c-2849fa0c7003'::uuid, 1, NULL, TRUE, 0, NULL, E'Video Games', E'Do you believe that video games have a positive impact on cognitive skills?', NULL, NULL, E'In today''s digital age, video games have become a prevalent form of entertainment for people of all ages. While some may argue that video games are merely a source of leisure, I firmly believe that they have a positive impact on cognitive skills. Through engaging gameplay and interactive challenges, video games offer unique opportunities for cognitive development.\nOne compelling reason to support the positive impact of video games on cognitive skills is their ability to enhance problem-solving abilities. Many video games present complex puzzles and obstacles that require strategic thinking and quick decision-making. By navigating through these challenges, players can sharpen their problem-solving skills and develop effective strategies to overcome obstacles.\nFurthermore, playing video games can significantly improve hand-eye coordination and reflexes. Fast-paced games that demand quick reactions and precise movements can help individuals enhance their coordination skills. The need to react swiftly to in-game stimuli can lead to improved reflex responses, which can be beneficial in various real-life situations.\nIn conclusion, the positive impact of video games on cognitive skills cannot be overlooked. From improving problem-solving skills to enhancing hand-eye coordination and reflexes, video games offer a diverse range of cognitive benefits. As technology continues to advance, embracing the educational potential of video games can lead to further advancements in cognitive development and skill enhancement.', NULL, 200, 300),
  ('091ac85d-3dae-5a2e-9b49-4fc251459af2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '091ac85d-3dae-5a2e-9b49-4fc251459af2'::uuid, 1, NULL, TRUE, 0, NULL, E'Mass-communications', E'Traditionally, mass-communications research has conceptualized the process of communication in terms of a circulation circuit or loop. This {{1}} has been criticized for its linearity -- sender/message/receiver -- for its concentration on the level of message exchange and for the absence of a structured conception of the different moments as a complex structure of relations. But it is possible (and is {{2}} ) to think of this process in terms of a structure produced and sustained through the articulation of linked {{3}} distinctive moments production, circulation, distribution/consumption, reproduction. This would be to think of the {{4}} as a '' complex structure in dominance'' , sustained through the articulation of connected practices, each of which, however, retains its distinctiveness and has its own {{5}} modality, its own forms and conditions of existence.', NULL, NULL, NULL, E'1.model, 2.useful, 3.but, 4.process, 5.specific', NULL, NULL),
  ('0924b1ec-fc68-5517-ac01-4cbe36b8657a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0924b1ec-fc68-5517-ac01-4cbe36b8657a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a84307b2-488d-52ce-bce1-1d56e2ea1939'::uuid, NULL, E'The picture shows six of the nine planets in the solar system.', NULL, NULL, NULL),
  ('092cbf75-a301-51b7-ac9e-1b25b2caf84f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '092cbf75-a301-51b7-ac9e-1b25b2caf84f'::uuid, 1, NULL, TRUE, 0, NULL, E'Candle', NULL, NULL, NULL, NULL, E'2, 4, 1, 3', NULL, NULL),
  ('092e15de-06c4-5a7c-994c-5299c5049fc1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '092e15de-06c4-5a7c-994c-5299c5049fc1'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Does mathematics or linguistics cover the study of the relations between numbers?', '9833b9a2-4258-58fc-92e1-0abae9c6264a'::uuid, NULL, NULL, E'Mathematics', NULL, NULL),
  ('09407dcb-d763-5c89-8c56-901546821be7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '09407dcb-d763-5c89-8c56-901546821be7'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'When you have the PRIMARY, the SECONDARY, what do you have next?', '64c1b1c8-4acf-52dc-9898-7ee1ab47776c'::uuid, NULL, NULL, E'Tertiary', NULL, NULL),
  ('094435d0-160f-5f86-b2a0-9f4adaeea2ef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '094435d0-160f-5f86-b2a0-9f4adaeea2ef'::uuid, 1, NULL, TRUE, 0, NULL, E'No Shave November', E'Not to be outdone, No Shave November is an initiative that exploded in 2009 after the Chicago-based Hill family lost their father to colon cancer and wanted to raise money for charity in his honor. Since then, No Shavers have helped raise more than $12 million for cancer research and prevention.\nNo Shave November is run by the Matthew Hill Foundation, and participants — men and women — literally grow out their hair instead of shaving or grooming it for 30 days. No Shavers then donate the money they don''t spend on things like razors, haircuts and waxing appointments to support cancer research and education. The idea is to embrace your hair because so many people undergoing cancer treatments lose theirs.\n"We recognize that this form of fundraising may not be for everyone and that is fine," says Brett Hartigan, communications coordinator for the Matthew Hill Foundation. "We don''t discriminate, but defeating cancer is going to take all of us, which is why we will always encourage everyone to participate and get hairy. What is more important than raising funds for cancer awareness, screenings and education?"\nNo Shave November encourages people to register and establish fundraising pages, and groups can grow out their hair as a team, as well. Even if you have no interest in growing a beard or mustache (or you have no hair!) you can still support a No Shaver or make a general donation.', NULL, NULL, NULL, NULL, 5, 75),
  ('0949d39b-3cee-52b9-a5cf-f33f0ea1232c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0949d39b-3cee-52b9-a5cf-f33f0ea1232c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '117f587b-6641-5796-bd8e-0d343adf0a47'::uuid, NULL, NULL, E'Thousands of students are leaving college because of mental health issues.', NULL, NULL),
  ('094c8176-71cc-5fa9-804e-909bf3c47588'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '094c8176-71cc-5fa9-804e-909bf3c47588'::uuid, 1, NULL, TRUE, 0, NULL, E'Neuroplasticity', E'Recent studies in neuroplasticity have uncovered that the adult brain is far more adaptable than {{1}} thought. Researchers have {{2}} that through specific training and therapy, individuals can rewire their brains to recover {{3}} functions or even enhance cognitive abilities, {{4}} hope for brain injury treatments.', NULL, NULL, NULL, E'1.previously, 2.demonstrated, 3.lost, 4.offering', NULL, NULL),
  ('094e65b4-5e31-508d-8c3e-1e16639208ab'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '094e65b4-5e31-508d-8c3e-1e16639208ab'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '45387127-07bd-5490-8beb-2b93d00b4a71'::uuid, NULL, E'Please turn in your essays on white paper with double-spacing throughout.', NULL, NULL, NULL),
  ('0951bebf-0038-526b-9e3d-234a99b47c4d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0951bebf-0038-526b-9e3d-234a99b47c4d'::uuid, 1, NULL, TRUE, 0, NULL, E'Soot', NULL, 'c588875d-c331-5cc1-a94a-77b55212aab4'::uuid, NULL, E'Soot, which comes from combustion of many different things, is black so it''s a strong absorber. In fact it''s second only to CO2 in terms of warming, so it''s actually ahead of methane, which you hear a lot about. The interesting thing about soot and aerosols'' impact on climate is that their lifetimes are so much shorter. So if we can reduce the soot we can make changes within months versus tens of years. It''s not to say we should ignore the CO2 and the greenhouse gases but it could buy us some time while we actually do the right strategies to reduce the greenhouse gases.', NULL, NULL, NULL),
  ('09543f54-dfbd-50fc-9830-be8f799c7599'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '09543f54-dfbd-50fc-9830-be8f799c7599'::uuid, 1, NULL, TRUE, 0, NULL, E'Noise Control', E'At the local and state level, demanding funding for repairs and improvement to outdated transit infrastructure will greatly reduce the noise caused by trains, cars, and trucks.\nUrban-planning approaches to {{1}} noise on a city-by-city basis can be as simple as taking a single lane away from cars and giving it to bicycles, people, or green space. Improving, expanding, and properly funding public transit removes cars from the road, both reducing the sound they {{2}} and replacing it with quieter options like trams and high-speed light-rail. In architecture, acoustics should play a greater {{3}} in all structures, from mundane apartment buildings to the grandest art museums. Noise control should be a consideration from the very first planning stage, {{4}} than tacked on as an afterthought.', NULL, NULL, NULL, E'1.eliminating, 2.produce, 3.role, 4.rather', NULL, NULL),
  ('095601bc-556f-5c67-9899-3e20e21ef53e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '095601bc-556f-5c67-9899-3e20e21ef53e'::uuid, 1, NULL, TRUE, 0, NULL, E'Heavy Lifts', E'You''re at the gym, finishing up your workout, when your workout buddy asks if you''re available to spot him for his heavy lifts tomorrow morning. However, you realize you have a doctor''s appointment scheduled at the same time. What would you say to him?', '9e55c7b8-7b05-5e2d-bcf3-d56cee8dc99e'::uuid, NULL, E'I would love to help you out, but unfortunately, I have a doctor''s appointment tomorrow morning, so I won''t be available to spot you at that time. How about we plan for later in the afternoon or another day this week? I''m definitely down to spot you, but l just need to work around this appointment. Let me know what works best for you, and let''s do it together.', NULL, NULL, NULL),
  ('095a3830-e17c-5884-a717-dd4cd9cdf891'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '095a3830-e17c-5884-a717-dd4cd9cdf891'::uuid, 1, NULL, TRUE, 0, NULL, E'Inevitable Change', E'Change is inevitable in any sphere of life. Although the results of change can bring great benefits, the process of change can be intensely traumatic, involve loss of choice, power and status, and when change happens in the workplace, it can even lead to loss of jobs. Many businesses and organizations use a model called the Change Curve to understand and manage how people react to change.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('095e75b8-10aa-5449-bb19-971487744077'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '095e75b8-10aa-5449-bb19-971487744077'::uuid, 1, NULL, TRUE, 0, NULL, E'Jane Goodall', E'The 20th century saw two groundbreaking figures in animal research: Konrad Lorenz and Jane Goodall. While Lorenz focused on instinctual behavior in birds, Goodall revolutionized our understanding of primates, {{1}} chimpanzees. Prior to her work, {{2}} was known about the complex social lives and cognitive abilities of these intelligent animals. Goodall''s pioneering research, conducted in Tanzania''s Gombe Stream National Park, revealed chimps to be {{3}} of tool use, complex communication, and even self-awareness. Born in London in 1934, Goodall''s passion for animals manifested early. Despite lacking formal scientific training, her determination and keen observation skills led to a groundbreaking career. Initially dismissed by the scientific community for her unconventional methods, including naming individual chimps and observing them in their natural {{4}} , Goodall''s meticulous research eventually earned widespread recognition. Her discoveries challenged the prevailing view of primates as simple creatures, paving the way for a new understanding of their intelligence and emotional depth. More importantly, Goodall''s work sparked a global movement for chimpanzee conservation and {{5}} the importance of ethical treatment towards all animals.', NULL, NULL, NULL, E'1.particularly, 2.little, 3.capable, 4.habitat, 5.highlighted', NULL, NULL),
  ('095f20a7-9e54-5b37-b4e3-b32b42e56e56'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '095f20a7-9e54-5b37-b4e3-b32b42e56e56'::uuid, 1, NULL, TRUE, 0, NULL, E'Active Learning Classrooms', E'Active learning classrooms (ALCs) are student-centered, technology-rich classrooms. They are easily identified with their large {{1}} tables and movable seating designed to improve student {{2}} in class. Typically, each table is accompanied by a whiteboard and flat-screen monitor to display student work and larger rooms frequently have miniature bulbs and microphones at each table. In this way, students are able to {{3}} if they have questions or want to speak to the {{4}} room.', NULL, NULL, NULL, E'1.circular, 2.engagement, 3.signal, 4.entire', NULL, NULL),
  ('095f4871-b110-5701-979e-ff6fa7b80665'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '095f4871-b110-5701-979e-ff6fa7b80665'::uuid, 1, NULL, TRUE, 0, NULL, E'Roman Empire', NULL, NULL, NULL, NULL, E'2, 1, 4, 3', NULL, NULL),
  ('095f8f0d-5b41-5f90-b803-22ba376b52e5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '095f8f0d-5b41-5f90-b803-22ba376b52e5'::uuid, 1, NULL, TRUE, 0, NULL, E'Conversation between Student and Teacher', E'Good afternoon. Miss Davis. I was told by James that you wanted to see me in your office. Oh, I did! Thank you for coming. Gene. Have a seat. How are you? Is everything going fine? Yes, pretty much. What about you? Miss Davis? I haven''t seen you for awhile. Yes, I was away for a while. Actually. I went to Arizona and met your mother there. Didn''t she tell you about it? No, she didn''t, but that''s great. How is she? She is fine to me. She is still as exuberant as she was twenty years ago. You will never know how great a teacher your mother was. Anyway, how is your semester? It was fun. The teachers were nice, especially Ms. Mckenna. I loved her class. Strange. I never liked math and struggled so much until I met Miss Mckenna. That''s great. How was she so wonderful? She spoke softly and explained thoroughly. She answered all of the questions earnestly. I wish all my teachers were like Miss Mckenna. Many of our students made that common in the past, too. Who could have guessed that? I could get an a in math? Why not? You are smart, you can get an a in any subject you want, as long as you try. I believe. So I should have tried harder instead of giving up and neglecting the hard subjects.\n\nWhat did the student realize at the end of the conversation?', '10e9dfc2-eee4-5c1d-9de4-97ec753b83fe'::uuid, NULL, NULL, E'The student realized that she can do things if she tries hard.', NULL, NULL),
  ('0960da23-2586-57f7-bedf-c4166f1246b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '0960da23-2586-57f7-bedf-c4166f1246b8'::uuid, 1, NULL, TRUE, 0, NULL, E'Internal Reflection', NULL, NULL, NULL, NULL, E'4, 2, 1, 3', NULL, NULL),
  ('096547fd-33ad-5ab5-932d-46b84e2d1e7d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '096547fd-33ad-5ab5-932d-46b84e2d1e7d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3eac88b3-907a-50ce-9d2d-a3e1fca66b65'::uuid, NULL, E'The free workshop will be conducted this Wednesday on the fourth floor of the department.', NULL, NULL, NULL),
  ('0969f682-ea1b-5fd8-ab73-3dbd8740711b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0969f682-ea1b-5fd8-ab73-3dbd8740711b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the meeting where an employer asks a potential employee questions about their work experience?', 'b135d275-1b44-5d16-8833-758dcd01a97e'::uuid, NULL, NULL, E'Interview', NULL, NULL),
  ('096afe1e-a2e7-55ec-a25f-9d7e7b6849ab'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '096afe1e-a2e7-55ec-a25f-9d7e7b6849ab'::uuid, 1, NULL, TRUE, 0, NULL, E'Opportunity Cost', E'Opportunity cost incorporates the notion of scarcity: No matter what we do, there is always a trade-off. We must trade off one thing for another because resources are limited and can be used in different ways. {{1}} , we use up resources that could have been used to acquire something else. The {{2}} of opportunity cost allows us to measure this tradeoff. Most decisions {{3}} several alternatives. For example, if you spend an hour studying for an economics exam, you have one fewer hour to pursue other activities. To determine the opportunity cost of an activity, we look at what you consider the best of these ''other'' activities. For example, suppose the alternatives to studying economics are studying for a history exam or working in a job that pays $10 per hour. If you consider studying for history a {{4}} use of your time than working, then the opportunity cost of studying economics is the four extra points you could have received on a history exam if you studied history instead of economics. Alternatively, if working is the best alternative, the opportunity cost of studying economics is the $10 you could have earned instead.', NULL, NULL, NULL, E'1.By acquiring something, 2.notion, 3.involve, 4.better', NULL, NULL),
  ('096c7687-b52a-551c-acaa-fbd56deaabd2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '096c7687-b52a-551c-acaa-fbd56deaabd2'::uuid, 1, NULL, TRUE, 0, NULL, E'Electric Vehicle', E'However, electric vehicle (EV) ownership in the US has thus far been {{1}} by households with higher incomes and education levels, leaving the most vulnerable populations behind. We identified these {{2}} that will require targeted policies to promote energy justice in lower-income communities, including the {{3}} of charging infrastructure, as well as strategies to reduce electricity costs and increase the {{4}} of low-carbon transportation modes such as public transit and bicycling.', NULL, NULL, NULL, E'1.dominated, 2.disparities, 3.subsidizing, 4.availability', NULL, NULL),
  ('096c86fc-8f7c-5871-a11b-163251b24861'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '096c86fc-8f7c-5871-a11b-163251b24861'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '51e77705-9c99-51f4-ba83-f8c72da7079d'::uuid, NULL, NULL, E'They cannot put in everything: choices have to be made.', NULL, NULL),
  ('0973549e-aa30-52e0-a24b-01b2207600a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0973549e-aa30-52e0-a24b-01b2207600a6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c4fa1829-ea68-524a-abb4-2e8b6c285133'::uuid, NULL, E'When the rain came down the crowd started to disperse.', NULL, NULL, NULL),
  ('0976f058-1b82-571e-a4e2-69353b4fd3fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0976f058-1b82-571e-a4e2-69353b4fd3fb'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a712191a-c5e5-5c4d-a286-2eca31ec8ccc'::uuid, NULL, E'The two countries have become close trading partners in the field of crude oil.', NULL, NULL, NULL),
  ('0977583c-18bf-5ff1-9e5d-83fa706cff03'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0977583c-18bf-5ff1-9e5d-83fa706cff03'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'acb43ac4-fa14-5a42-8437-2bdc6c36dd9d'::uuid, NULL, E'The staff should make sure the kids have an enjoyable and educational day.', NULL, NULL, NULL),
  ('097768f7-3f0c-52eb-82a4-649170e57836'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '097768f7-3f0c-52eb-82a4-649170e57836'::uuid, 1, NULL, TRUE, 0, NULL, E'Clean Water', E'Many people are under the impression that the water which comes out of a plant is clean. This is a common misconception: the function of a plant is to make the water cleaner, but it''s not clean enough to drink. It could be used in irrigation. What a plant is trying to do is simply speed up a process that would naturally occur given more time. This means that a plant can create water that is safe to enter back into the water system as it''s so heavily diluted. The river then continues the water purification, acting as a form of the fourth stage.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('097a2c31-d221-59e3-9edb-3ec11e449b05'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '097a2c31-d221-59e3-9edb-3ec11e449b05'::uuid, 1, NULL, TRUE, 0, NULL, E'Americans and Food', E'What is it about Americans and food? We love to eat, but we feel {{1}} about it afterward. We say we want only the best, but we strangely enjoy junk food. We''re {{2}} with health and weight loss but face an unprecedented epidemic of obesity. Perhaps the {{3}} to this ambivalence lies in our history. The first Europeans came to this continent searching for new spices but went in vain. The first cash crop wasn''t eaten but smoked. Then there was Prohibition, intended to prohibit drinking but actually encouraging more {{4}} ways of doing it.\nThe immigrant experience, too, has been one of in harmony. Do as Romans do means eating what "real Americans" eat, but our nation''s food has come to be {{5}} by imports — pizza, say, or hot dogs. And some of the country''s most treasured cooking comes from people who arrived here in shackles.', NULL, NULL, NULL, E'1.guilty, 2.obsessed, 3.answer, 4.creative, 5.defined', NULL, NULL),
  ('097d8733-8451-5826-8715-ae0974c10886'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '097d8733-8451-5826-8715-ae0974c10886'::uuid, 1, NULL, TRUE, 0, NULL, E'Electronic Discourse', E'Electronic discourse is one form of interactive electronic communication. In this study, we reserve the term for the two-directional texts in which one person using a keyboard writes language that appears on the sender’s monitor and is transmitted to the monitor of a recipient, who responds by keyboard.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('097e112f-f443-5004-819f-89686831822b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '097e112f-f443-5004-819f-89686831822b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ae318009-bcda-53f6-b806-e1f7d0733884'::uuid, NULL, E'The negative discourse continues to be predominant in discussions about gender.', NULL, NULL, NULL),
  ('09801621-f1a4-5198-8310-452f59bff7ef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '09801621-f1a4-5198-8310-452f59bff7ef'::uuid, 1, NULL, TRUE, 0, NULL, E'History Assignment', E'You''ve just completed a history assignment and you''re keen on improving it before submission. You decide to seek feedback from your classmate, Ali, who always seems to excel in history. How do you approach Ali for feedback, and what specific questions do you ask to gain insights on how to enhance your assignment?', 'da36dd26-5f63-5462-bc70-0e04f1435220'::uuid, NULL, E'Hey Ali, I want to talk to you about something.\nWe seem to have a little issue with my finished history assignment.\nIt''s like I have finished my history assignment and I want to improve it before handing it in, so I hope you can give me some advice to make it better.\nAnd I''d like to know what you think.', NULL, NULL, NULL),
  ('0980a85a-a9ea-5988-ad31-ce210fff309a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0980a85a-a9ea-5988-ad31-ce210fff309a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'afcdb91b-db1c-5669-aed9-304a0df5f3e8'::uuid, NULL, E'I need more quotations to back up my argument.', NULL, NULL, NULL),
