  ('0a14d0cd-c9be-5a79-9bdd-bd36f5028a07'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0a14d0cd-c9be-5a79-9bdd-bd36f5028a07'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b29bd762-4ab5-569f-acaa-f31824d187d6'::uuid, NULL, E'Leading scientists speculate that numerous planets could support life forms.', NULL, NULL, NULL),
