  ('0ac6b105-3d3c-50b5-a9e9-b1374fbee531'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0ac6b105-3d3c-50b5-a9e9-b1374fbee531'::uuid, 1, NULL, TRUE, 0, NULL, E'Good Health', E'Maintaining good health is essential for living a happy and fulfilling life. Eating a balanced diet rich in fruits, vegetables, whole grains, and lean proteins, staying physically active for at least 30 minutes a day, and getting enough sleep are all important factors in achieving optimal health and preventing chronic diseases such as obesity, diabetes, and heart disease.', NULL, NULL, NULL, NULL, NULL, NULL),
