  ('0acc1999-01ab-5f4e-a922-675ab1598782'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0acc1999-01ab-5f4e-a922-675ab1598782'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'fa3532a5-eb7d-5331-b48b-5c2104631f66'::uuid, NULL, E'The inherent tension between these two features remains to be addressed.', NULL, NULL, NULL),
