  ('0bc5a62a-67d8-5513-99b1-ba063eab0c59'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0bc5a62a-67d8-5513-99b1-ba063eab0c59'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8582607c-ae03-5fb0-9fbb-ca20115f7769'::uuid, NULL, E'New York City''s ethnic diversity is renowned and celebrated widely.', NULL, NULL, NULL),
  ('0bce1f97-2774-58fc-b127-7e798c82241d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', '0bce1f97-2774-58fc-b127-7e798c82241d'::uuid, 1, NULL, TRUE, 0, NULL, E'Flax', E'When the Maori people first came to New Zealand. they brought the mulberry plant from which they made bark cloth. However. the mulberry did not flourish in the new climate so they found a substitute in the native flax. They used this for baskets, mats, and fishing nets and to make intricate fibre ceremonial cloaks. Maori identified almost 60 types of flax, and propagated flax nurseries and plantations to supply the integral material. They chopped the leaves near the base of the flax plant using a sharp mussel shell or shaped rocks. The flesh of the leaf was stripped off right down to the fibre which went through several processes of washing, bleaching, softening, dyeing and drying. Flax ropes and cords had such great strength that they were used to bind together sections of hollowed-out logs to create huge ocean-going canoes, and to provide rigging, sails and lengthy anchor warps for them. It was also used for roofs for housing. The ends of the flax leaves were fanned out to make torches to provide light at night.\n\nFor which of the following purposes does the passage say the Maori used flax?', NULL, NULL, NULL, E'special clothing\nequipment for boats', NULL, NULL),
  ('0bd41e71-71ef-501d-ab72-c91c25499036'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0bd41e71-71ef-501d-ab72-c91c25499036'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the world''s longest river?', 'ea18c31b-d033-5a34-a43c-fb987fc7b004'::uuid, NULL, NULL, E'Nile', NULL, NULL),
