  ('0bdf2d48-948c-58f4-82ed-9470d716bfb4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '0bdf2d48-948c-58f4-82ed-9470d716bfb4'::uuid, 1, NULL, TRUE, 0, NULL, E'Women in Labour Force', E'With the increase in women''s {{1}} in the labour force, many mothers have less time {{2}} to undertake domestic activities. At the same time, there has been increasing {{3}} that the father''s role and {{4}} with a child is important. A father can have many roles in the family, ranging from income provider to teacher, carer, playmate and role model. Therefore, balancing paid work and family responsibilities can be an important issue for both fathers and mothers in families.', NULL, NULL, NULL, E'1.participation, 2.available, 3.recognition, 4.relationship', NULL, NULL),
  ('0be68e86-fc29-5757-a5af-364895d19711'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0be68e86-fc29-5757-a5af-364895d19711'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4c7d44ef-4730-5d4e-a0f0-b316dd4bc882'::uuid, NULL, E'If you have any questions in the exam, please raise your hands.', NULL, NULL, NULL),
  ('0be8bc57-37c4-5a23-b3d8-fa5bb264dd44'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0be8bc57-37c4-5a23-b3d8-fa5bb264dd44'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for a steep-sided, often circular, depression in the ground formed by volcanic activity?', '9967be7e-9132-5d20-969c-faf3259baaae'::uuid, NULL, NULL, E'Caldera / crater', NULL, NULL),
