  ('0bece56d-558e-5208-b72f-fe2a2db6fccd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0bece56d-558e-5208-b72f-fe2a2db6fccd'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b3e57f6f-23ea-5a1a-9d65-04c1850ad496'::uuid, NULL, E'The old building in the university is still being used.', NULL, NULL, NULL),
  ('0bf1ea08-5d61-5c8f-9d81-51e14c82a4e3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '0bf1ea08-5d61-5c8f-9d81-51e14c82a4e3'::uuid, 1, NULL, TRUE, 0, NULL, E'Work for Whom', E'Some people prefer to work for themselves or own a business. Others prefer to work for an employer. What do you think?', NULL, NULL, E'The decision to work for oneself or for an employer is a topic of much debate. While some argue that working for an employer provides stability and security, I believe that people should work for themselves or own a business. This essay will argue that working for oneself or owning a business provides independence, potential for higher income and financial success, and flexibility in terms of work schedule and lifestyle.\nWorking for oneself or owning a business provides independence. Individuals who work for themselves have control over their work and decisions, and can choose the projects they work on. They are not beholden to a boss or company culture, and can create their own work environment and culture.\nWorking for oneself or owning a business has the potential for higher income and financial success. Entrepreneurs have the ability to create their own income streams, and can scale their business to increase profits. Additionally, owning a business can provide tax benefits and other financial advantages.\nIn conclusion, I believe that people should work for themselves or own a business. Working for oneself or owning a business provides independence, potential for higher income and financial success, and flexibility in terms of work schedule and lifestyle. While there may be some downsides to working for oneself or owning a business, such as the risk of failure or the need for self-discipline, I believe that the benefits outweigh the drawbacks. By working for themselves or owning a business, individuals can create their own path to success and financial stability.', NULL, 200, 300),
  ('0bf2ee2a-b940-5a30-9672-b200cf24269b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0bf2ee2a-b940-5a30-9672-b200cf24269b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ba9581da-ea3b-529a-8705-68c213452760'::uuid, NULL, NULL, E'The curriculum should be adjusted to incorporate recent developments.', NULL, NULL),
  ('0bf50705-fc62-5947-9a87-0c72a4038e56'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0bf50705-fc62-5947-9a87-0c72a4038e56'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '85eaf0e2-4701-58e3-8f08-a61dfabf5437'::uuid, NULL, E'The waiter answered the customer''s question patiently and provided helpful information.', NULL, NULL, NULL),
