  ('0c2a1d97-1803-53f8-bd0b-70d07eee9c53'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0c2a1d97-1803-53f8-bd0b-70d07eee9c53'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '498d869a-61af-543a-bf33-6438d9cc776b'::uuid, NULL, E'You have to be able to describe things in a form that users can understand.', NULL, NULL, NULL),
