  ('0c6ff6de-ea04-5f75-ba14-0eaad6087dc6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '0c6ff6de-ea04-5f75-ba14-0eaad6087dc6'::uuid, 1, NULL, TRUE, 0, NULL, E'Visual Arts', E'It is the assertion of this article that students who use visual art as a prewriting stimulus are composing their ideas both in images and in words. The result of the art creation process allows students the distance to {{1}} , add details, and create more coherent text. The process of writing is more than putting words on a piece of paper. Effective authors are able to create {{2}} and to communicate ideas using well-chosen words, phrases, and text structures. Emergent writers struggle with the {{3}} of the writing process, i.e. fine motor control for printing legibly, recall of {{7}} patterns, and the use of syntax and grammar rules. As a result, texts written by young writers tend to be simplistic and formulaic. The artwork {{4}} the writing process, resulting in a text that is richer in sensory detail and more {{5}} than the more traditional writing-first crayon drawing-second {{6}} .', NULL, NULL, NULL, E'1.elaborate, 2.imagery, 3.mechanics, 4.spelling, 5.facilitates, 6.intricate, 7.approach', NULL, NULL),
  ('0c7131ef-92c8-5ffe-938e-2a9e1b706dd8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0c7131ef-92c8-5ffe-938e-2a9e1b706dd8'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c9d4aeda-778b-5732-a5c0-5e37194dba17'::uuid, NULL, NULL, E'We are on track for one billion tobacco-related deaths this century.', NULL, NULL),
  ('0c72d802-9736-5bba-9be3-2cefa4cb5277'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '0c72d802-9736-5bba-9be3-2cefa4cb5277'::uuid, 1, NULL, TRUE, 0, NULL, E'Lionfish', E'"Until now, few {{1}} of the alien lionfish Pterois miles have been reported in the Mediterranean and it was {{2}} whether the species could invade this region like it has in the western Atlantic." Demetris Kletou, co-author of the paper said in a statement. "But we''ve found that lionfish have {{3}} increased in abundance, and within a year have colonized almost the entire south eastern coast of Cyprus, assisted by sea surface warming."\nLionfish were originally found in the waters of the Pacific and lndian Oceans. They likely ended up in the Caribbean and Western Atlantic after {{4}} from home aquariums.\nThe invasion of the Mediterranean has different roots. The expansion of the Suez Canal has given lionfish even more {{5}} to the Mediterranean Sea and warming water temperatures have provided the {{6}} environment for the invasive species.', NULL, NULL, NULL, E'1.sightings, 2.questionable, 3.recently, 4.being released, 5.access, 6.perfect', NULL, NULL),
  ('0c797d1a-0b09-59bb-be28-74ce4403ff36'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0c797d1a-0b09-59bb-be28-74ce4403ff36'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ccdb856b-1a18-599e-9a42-2236a3c6b711'::uuid, NULL, E'There''s more research on regular crimes than on company crimes.', NULL, NULL, NULL),
