  ('0e58cfb6-2425-5dcd-bb3f-9823866d10ec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0e58cfb6-2425-5dcd-bb3f-9823866d10ec'::uuid, 1, NULL, TRUE, 0, NULL, E'''Rewire'' Themselves', E'Contrary to the commonly-held view, the brain does not have the ability to rewire itself to compensate for the loss of sight, an amputation or stroke, for example, say scientists. The researchers argue that the notion that the brain, in response to injury or deficit, can reorganize itself and repurpose particular regions for new functions, is fundamentally flawed -- despite being commonly cited in scientific textbooks.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('0e5abd29-b23e-5653-ad22-9d364afa3f8d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0e5abd29-b23e-5653-ad22-9d364afa3f8d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c1143a6d-08b9-56e2-9a64-ed54818e2ec5'::uuid, NULL, NULL, E'Professionals have developed methods for quantifying plant growth through numerical measurements.', NULL, NULL),
