  ('0e615375-9c3f-5490-a9d0-7969441a7515'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0e615375-9c3f-5490-a9d0-7969441a7515'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bb513043-7f5e-5611-a82f-312d1c8f2246'::uuid, NULL, E'These professionals will offer you the opportunity to discuss issues with them.', NULL, NULL, NULL),
  ('0e68f185-d223-506a-a625-92b3ced12e2e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0e68f185-d223-506a-a625-92b3ced12e2e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f81fbe3b-2eac-5899-a39e-9e6dcef60134'::uuid, NULL, E'You should return books to the library before ending your term.', NULL, NULL, NULL),
  ('0e6a50d2-b8cf-5cf2-88ee-4c43ec6440de'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0e6a50d2-b8cf-5cf2-88ee-4c43ec6440de'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6c858839-44ef-57a0-bcb4-059def16b64b'::uuid, NULL, NULL, E'Art is an expression of creative skills and imagination.', NULL, NULL),
  ('0e6b665b-117d-5a6f-b8e1-f2f78fd5e40d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0e6b665b-117d-5a6f-b8e1-f2f78fd5e40d'::uuid, 1, NULL, TRUE, 0, NULL, E'Left and Right', NULL, 'f0373a97-d71f-5bfe-882f-6ddd2077b22d'::uuid, NULL, E'Alexis de Tocqueville, as we have noted, appears to have had some appeal to both ends of the political spectrum — left and right. Or rather, both have found him to be useful for their purposes in certain circumstances. His rational acceptance of the new forces of democracy brought about by the American and French revolutions made him an icon of left-wing liberals. However, during the Cold War - that is, from the end of World War II until the collapse of communism - he was adopted by some leading thinkers on the right. So, there are two sides to his political philosophy, and the man himself that we need to look at.\nNow, I would suggest that de Tocqueville''s biography is important here. You must always bear in mind when reading him that he was an aristocrat, and one whose family had suffered in the French Revolution. He wasn''t your typical aristocrat because his politics differed from others of his family and social rank. He abandoned the Catholic church and married beneath his class. Yet he never quite threw off the prejudices of that class. However, and what is important, he did recognize and believe that the tendency of history, which in those days could be traced back to the Middle Ages, was towards the leveling of social ranks, and more equal and democratic conditions. The French Revolution had in the end brought Napoleon, whom he hated, but democracy would inevitably come to France. His trip to America was to see democracy in practice, make note of its shortcomings and errors, and then find safeguards against them.', NULL, NULL, NULL),
  ('0e75c02c-a9ad-5a57-9cb4-b4272fe9c666'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0e75c02c-a9ad-5a57-9cb4-b4272fe9c666'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0d5a2025-0608-5f2e-a2dc-71a0ff6d621c'::uuid, NULL, E'I made a phone call to reserve a table in my favourite restaurant.', NULL, NULL, NULL),
  ('0e78492c-ba0c-5f1b-bb45-09c6eeb3089f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0e78492c-ba0c-5f1b-bb45-09c6eeb3089f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '95d92545-0e17-56af-b7bb-8104f855113b'::uuid, NULL, E'As she was bright and ambitious, she became a manager in no time.', NULL, NULL, NULL),
  ('0e7a4bd0-bc77-55ef-bacb-a0cb0e8e3e3d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0e7a4bd0-bc77-55ef-bacb-a0cb0e8e3e3d'::uuid, 1, NULL, TRUE, 0, NULL, E'Centrality of Work', NULL, '34590538-c2e6-5ba2-bd6b-833f02754be8'::uuid, NULL, E'Work comes to be the center around which the world turns. Human beings start to see themselves chiefly as workers, and the entirety of life becomes more and more work, or work like. To see this we can begin to examine a number of what I might call tightening conditions. So the first condition would be the centrality of work. We’ve come to think that work is actually the center and everything else begins to turn around it. That we are preparing for work. That we are preparing to leave work. And this is happening all the way around the world. Meanwhile we’re adjusting our schedules, the rest of our lives so that they are turning about it. So that would be the first condition. The second condition is subordination. That everything else in life comes to seem as if it’s subordinate to, and to be put in the service of, work. We can think of sleeping: the idea is that we wish to sleep well today in order to be focused and prepared for work. And that when we’re at work we wish to be as productive as possible. So sleep becomes that which is an instrument in the service of productivity. And we can play that game with all sorts of different instances. The third condition is the resemblance claim. It seems as if everything else in life comes to resemble work, more and more. So you can think of, on a day off you are wanting to be as productive as possible, thinking about how much you got done. You can begin to think about all the ways in which you plan and schedule time with children. The terms that begin to mark out our lives even when we’re not actually working sound more and more work like. And the last condition I think is the most intense and that’s what I might call cultural forgetfulness. We’ve come to almost forget that there was a time in which work was not the center of the world, that there are other ways of life that proceed the modern world, in which work was a part of life but was not the focus of life. We forget that that’s still true today with other cultures, some other cultures. And we forget that there could actually be a time when work would not be that around which the rest of the world turns.', NULL, NULL, NULL),
  ('0e7e214b-7b97-5c08-b398-bd630aee2cef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0e7e214b-7b97-5c08-b398-bd630aee2cef'::uuid, 1, NULL, TRUE, 0, NULL, E'Education', E'Education is a crucial component of personal and societal growth, providing individuals with the knowledge and skills they need to succeed in life. It encompasses formal schooling as well as informal learning opportunities such as workshops, apprenticeships, and online courses, and promotes critical thinking, creativity, and lifelong learning.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('0e8493dd-3422-51ee-9566-477c4bfdff13'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '0e8493dd-3422-51ee-9566-477c4bfdff13'::uuid, 1, NULL, TRUE, 0, NULL, E'Songbird', E'Males do the singing and females do the listening. This has been the established, even cherished view of courtship in birds, but now some ornithologists are changing tune. László Garamszegi of the University of Antwerp, Belgium, and colleagues studied the literature on 233 European songbird species. Of the 109 for which information on females was available, they found evidence for singing in 101 species. In only eight species could the team conclude that females did not sing. Females that sing have been overlooked, the team say, because their songs are quiet. They are mistaken for males from their similar plumage or they live in less well-studied areas such as the tropics. Garamszegi blames Charles Darwin for the oversight. "He emphasized the importance of male sexual display, and this is what everyone has been looking at." The findings go beyond modern species. After carefully tracing back an evolutionary family tree for their songbirds, Garamszegi''s team discovered that, in at least two bird families, singing evolved in females first. They suggest these ancient females may have been using their songs to deter other females from their territories, to coordinate breeding activities with males, or possibly to attract mates. "It leaves us with a perplexing question."', NULL, NULL, E'Females that sing have been overlooked, because their songs are quiet, and they are mistaken for males from their similar plumage or they live in less well-studied areas such as the tropics, while in at least two bird families, singing evolved in females first, so these ancient females may have been using their songs to deter other females from their territories.', NULL, 5, 75),
  ('0e9109e3-08d4-5e94-9dd9-2ed18d0afef2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '0e9109e3-08d4-5e94-9dd9-2ed18d0afef2'::uuid, 1, NULL, TRUE, 0, NULL, E'Philosopher', E'This philosopher''s works are not restricted to a single aspect of knowledge but {{1}} across multiple fields. {{2}} , her writings emphasize the value of critical thinking. She developed a unique style {{3}} ideas from science, ethics, and art were blended together.', NULL, NULL, NULL, E'1.extend, 2.Moreover, 3.in which', NULL, NULL),
  ('0e9491f2-17a3-5539-a58d-a5e0e9df6a10'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0e9491f2-17a3-5539-a58d-a5e0e9df6a10'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e0e1e42b-078e-58ee-b587-edd3d2208f2f'::uuid, NULL, E'I am available this Thursday afternoon.', NULL, NULL, NULL),
  ('0e9ce04e-d072-5ce0-882c-da16df3841c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0e9ce04e-d072-5ce0-882c-da16df3841c8'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ed8b0d30-b5d8-5323-8d7c-4f70a3fa8db1'::uuid, NULL, E'The local people in the small town regard crabs as a great delicacy.', NULL, NULL, NULL),
  ('0e9d1e43-d368-5895-a372-82b93ed5f27e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0e9d1e43-d368-5895-a372-82b93ed5f27e'::uuid, 1, NULL, TRUE, 0, NULL, E'SMW', E'Yeah, inferential statistics is a formalized body of methods for solving another class of problems that present great difficulties for the unaided human mind. This general class of problems characteristically involves attempts to make predictions using a sample of observations, for example, a school superintendent wishes to determine the proportion of children in a large school system who come to school without breakfast, have been vaccinated for flu or whatever. Having little knowledge of statistics, the superintendent would know that it is unnecessary and inefficient. To question each child. The proportion for the entire district could be estimated fairly accurately from a sample of a few as a hundred children bus. This is inferential statistics is to predict or estimate characteristics of a population from a knowledge of the characteristics of only a sample.\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '23f9f08b-67d8-5184-8c9a-fcc4ada9c9ec'::uuid, NULL, NULL, E'of the population', NULL, NULL),
  ('0ea2cb20-b980-535c-8120-41ecbd0cf0ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '0ea2cb20-b980-535c-8120-41ecbd0cf0ca'::uuid, 1, NULL, TRUE, 0, NULL, E'Electrons', E'The electrons that orbit closest to the nucleus are {{1}} attracted. They are called bound electrons. The electrons that are farther away from the pull of nucleus can be forced out of their orbits. These are called free electrons. Free electrons can move from one atom to another. This movement is known as electron flow.\nElectricity is the movement or flow of electrons from one atom to another. A {{2}} of imbalance is necessary to have a movement of electrons. In a {{3}} atom, the positively charged nucleus balances the negatively charged electrons. This holds them in orbit. If an atom loses electrons, it becomes positive in charge. It attracts more electrons in order to get its balance.\nA conductor is any {{4}} that allows a good electron flow and conducts electricity. A good conductor must be made of atoms that give off free electrons easily. Also, the atoms must be close enough to each other so that the free electron orbits {{5}} . Ignition systems use copper and aluminium wires to conduct electricity. They allow good electron flow.', NULL, NULL, NULL, E'1.strongly, 2.condition, 3.normal, 4.material, 5.overlap', NULL, NULL),
  ('0ea45546-d471-5e17-a4ae-a1881733140b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '0ea45546-d471-5e17-a4ae-a1881733140b'::uuid, 1, NULL, TRUE, 0, NULL, E'Farming', E'When humans began farming some 12,000 years ago, they altered the future of our {{1}} forever. Our ancestors were ecological {{2}} , discovering and cultivating the most {{3}} crops, scaling them up to feed entire communities and transforming wild crops so fundamentally that they became dependent on humans for their survival. Farming, in the words of National Geographic''s Genographic Project, ''sowed the seeds for the modern {{4}} .''', NULL, NULL, NULL, E'1.species, 2.pioneers, 3.valuable, 4.age', NULL, NULL),
  ('0eae511a-ed62-53a3-bcc2-c4df518d6cf9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0eae511a-ed62-53a3-bcc2-c4df518d6cf9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '688d15d9-6833-5c34-8334-4ce1c74a1582'::uuid, NULL, NULL, E'The history of the movement has been documented by authors.', NULL, NULL),
  ('0eb7b1d6-a9f2-58e8-bb5a-22bb854ce22f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '0eb7b1d6-a9f2-58e8-bb5a-22bb854ce22f'::uuid, 1, NULL, TRUE, 0, NULL, E'Dance', E'Dance has played an important role in many musicals. In some {{1}} , dance numbers are included as an excuse to add to the color and spectacle of the show, but dance is more effective when it forms an integral part of the {{2}} . An early example is Richard Rodgers On Your Toes(1936) in which the story about classical ballet meeting the world of jazz enabled dance to be introduced in a way that enhances, rather than {{3}} the drama.', NULL, NULL, NULL, E'1.cases, 2.plot, 3.interrupts', NULL, NULL),
  ('0ebb22f8-5a43-5fca-aeaa-c28d2498df4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0ebb22f8-5a43-5fca-aeaa-c28d2498df4b'::uuid, 1, NULL, TRUE, 0, NULL, E'Mathematics', E'Competence in mathematics was another trouble spot. More than half said that the real task for school graduates is their deficiency in mathematics, while more than 10% of respondents said that college graduates are deficient in the subject, and 70% said they are adequate.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('0ebbe7c7-5e39-5c8a-a969-c5cbc5cf9cbe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0ebbe7c7-5e39-5c8a-a969-c5cbc5cf9cbe'::uuid, 1, NULL, TRUE, 0, NULL, E'Book Expense', E'I can''t believe how much my books cost this semester. I just spent over one hundred dollars in the university bookstore for only four bucks. And I still need the book for chemistry. That one costs fifty five dollars. It''s a little more than my budget can handle at the moment. Science books are always out of sight. But did you know there''s another book store in the pioneer district. They carry use copies of most of the textbooks for the university. I wonder if they have my chemistry book. I need the third edition. I found all of my books there. You can sell any kind of book, too, not just textbooks. That''s not a bad idea. Where did you say that was? Again, number?\n\nWhat is the man''s problem?', '6d6f084f-524e-5179-9040-82c4d11949f1'::uuid, NULL, NULL, E'The books that he needs are a strain on his finances.', NULL, NULL),
