  ('0f25a706-e4df-583f-b257-d5e48c0ccb5a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0f25a706-e4df-583f-b257-d5e48c0ccb5a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the sport that involves pushing, pulling, and lifting weights?', '910620e0-31c4-55da-a238-40bd83fd9603'::uuid, NULL, NULL, E'Weightlifting', NULL, NULL),
  ('0f2700c9-3d00-5f13-9639-8ece2bcf58fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '0f2700c9-3d00-5f13-9639-8ece2bcf58fb'::uuid, 1, NULL, TRUE, 0, NULL, E'Harder Life', E'It is harder for children to grow up in the 21st century than it was in the past. How far do you agree with this statement? Give your opinions.', NULL, NULL, E'In the 21st century, children face a different set of challenges than those in the past. However, it is important to note that not all of these challenges are negative. In fact, there are several reasons why it is easier for children living in the 21st century than in the past.\nFirstly, children today have access to a wealth of information at their fingertips. With the advent of the internet and other digital technologies, children can easily access information on a wide range of topics. This has made it easier for children to learn and explore different subjects, which can help them develop their skills and knowledge.\nSecondly, technology has made learning and connecting with others easier and more convenient for children. With the use of digital devices such as smartphones and tablets, children can easily access educational materials and communicate with their teachers and peers. This has made learning more interactive and engaging, which can help children to better retain information and develop their social skills.\nIn conclusion, while there are certainly challenges that come with living in the 21st century, it is important to recognize the many advantages that children have today. With access to information and technological advancements, children have more opportunities than ever before to learn, grow, and succeed.', NULL, 200, 300),
  ('0f282827-10d6-58cc-9c5a-3ec1a32ba7c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0f282827-10d6-58cc-9c5a-3ec1a32ba7c0'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c8523229-6dbe-5bd1-863c-dfac815be1cc'::uuid, NULL, NULL, E'Over the years more and more students are young.', NULL, NULL),
  ('0f2cadee-3f47-5b59-99b1-498aeef65c1e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0f2cadee-3f47-5b59-99b1-498aeef65c1e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8c723ea8-e07b-57f8-a13a-9ccea5eebf35'::uuid, NULL, NULL, E'The graph indicates only a slight increase in growth recently.', NULL, NULL),
  ('0f2e1c21-471d-54b4-810c-b41bbbdb734e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0f2e1c21-471d-54b4-810c-b41bbbdb734e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '58cfee60-fdf4-5506-9783-cc59dafe9446'::uuid, NULL, NULL, E'Geography is typically categorized into two branches: human and physical.', NULL, NULL),
  ('0f317280-6448-5e72-a3be-087ef192541d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0f317280-6448-5e72-a3be-087ef192541d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '55abae34-1926-5efd-9fd7-cf13fae9b474'::uuid, NULL, NULL, E'Zoo animals behave differently than their counterparts in the wild.', NULL, NULL),
  ('0f3dd418-8b47-5833-a2f2-d1eeda70d511'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0f3dd418-8b47-5833-a2f2-d1eeda70d511'::uuid, 1, NULL, TRUE, 0, NULL, E'Port of London', NULL, '17f62184-0422-5229-9d1e-c20c4b2fb5b5'::uuid, NULL, E'But what we are going to discuss today is how the port of London was discovered and what we discovered about it. Now if you look at the historical records of Roman London, there is only about 14 actual references to London in antiquity I contemporary references. And all those only one is in the first century, there are none at all at the second or third century. There is only one in the late third century and there is four in the fourth century. So if you are a historian trying to write the history of Rome in London, it''s really difficult. You don''t have much data, you''re going to depend on the archaeological evidence, the material evidence of the port and indeed the town to have any understanding of what happened then. And so, what we''re looking at here is how did we discover about the port of London, there is no historical documentations, no customs books, no terrorists, no idea of the taxes. We have to understand the port entirely from the archaeological evidence. So that''s what we are going to do today. So, if we move on to the next slide, I love lifestreaming. Thank you very much.', NULL, NULL, NULL),
  ('0f3f1b66-ac4c-5e87-a688-cb35fe53fea1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '0f3f1b66-ac4c-5e87-a688-cb35fe53fea1'::uuid, 1, NULL, TRUE, 0, NULL, E'Interior Design', NULL, NULL, NULL, NULL, E'3, 2, 4, 1', NULL, NULL),
  ('0f3f3f6f-ad51-5cf8-8cbd-0b9c3c2405ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0f3f3f6f-ad51-5cf8-8cbd-0b9c3c2405ca'::uuid, 1, NULL, TRUE, 0, NULL, E'Turing Test', NULL, 'f3b70563-1f89-591b-98c1-d2a88f8590bd'::uuid, NULL, E'What is consciousness? Can an artificial machine really think? Does the mind just consist of neurons in the brain, or is there some intangible spark at its core? For many, these have been vital considerations for the future of artificial intelligence. But British computer scientist Alan Turing decided to disregard all these questions in favor of a much simpler one: can a computer talk like a human? This question led to an idea for measuring artificial intelligence that would famously come to be known as the Turing test. In the 1950 paper, “Computing Machinery and Intelligence,” Turing proposed the following game. A human judge has a text conversation with unseen players and evaluates their responses. To pass the test, a computer must be able to replace one of the players without substantially changing the results. In other words, a computer would be considered intelligent if its conversation couldn’t be easily distinguished from a human’s. Turing predicted that by the year 2000, machines with 100 megabytes of memory would be able to easily pass his test. But he may have jumped the gun. Even though today’s computers have far more memory than that, few have succeeded, and those that have done well focused more on finding clever ways to fool judges than using overwhelming computing power.', NULL, NULL, NULL),
  ('0f48a95e-6ede-52c1-bff8-80f9ba1fe159'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0f48a95e-6ede-52c1-bff8-80f9ba1fe159'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4ca4b5d7-a02b-5126-acfe-30e6bf4b3fc9'::uuid, NULL, E'There is limited funding in this department to support qualified students.', NULL, NULL, NULL),
  ('0f49a9ff-7915-5ae5-ab7a-e93805e02a29'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0f49a9ff-7915-5ae5-ab7a-e93805e02a29'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the amount of profits that a company pays to people who own shares in the company?', '65b16e99-d759-57b4-9b85-cd8feab19b99'::uuid, NULL, NULL, E'Dividend / dividends', NULL, NULL),
