  ('0f755944-0438-59d4-87fa-b72e53c5d865'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '0f755944-0438-59d4-87fa-b72e53c5d865'::uuid, 1, NULL, TRUE, 0, NULL, E'Exam Schedule', E'Some schools schedule all the exams at the end of each year, while other schools schedule them throughout the whole year. What are the advantages and disadvantages of these two strategies? Which one do you think is better?', NULL, NULL, NULL, NULL, 200, 300),
