  ('0f8caae3-aeb2-5803-a302-9672a1d76032'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0f8caae3-aeb2-5803-a302-9672a1d76032'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '70483ffa-54c6-5c0a-9961-8565ca097e95'::uuid, NULL, E'She sold all her furniture, so she could afford to feed herself and her dog.', NULL, NULL, NULL),
  ('0f92a2c5-e7fc-5a00-8fd2-02749a30a428'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '0f92a2c5-e7fc-5a00-8fd2-02749a30a428'::uuid, 1, NULL, TRUE, 0, NULL, E'Unwritten Rules', E'When we talk about unwritten rules, we refer to the informal norms and expectations that guide social interactions. They are not explicitly stated but are understood by members of a particular group or community. Unwritten rules can relate to behavior, communication, dress, and other aspects of social interaction. They are often learned through observation and experience rather than formal instruction.', NULL, NULL, NULL, NULL, NULL, NULL),
