  ('10031a82-8f90-55a2-a1b4-049459eb636e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '10031a82-8f90-55a2-a1b4-049459eb636e'::uuid, 1, NULL, TRUE, 0, NULL, E'Absolute Location', E'Absolute location is a way of explaining {{1}} on Earth you are by using a scientific system of coordinates — typically, latitude and longitude. Latitude is essentially an angle that ranges from 0 degree at the Equator to 90 degree (North or South) at the {{2}} . Conversely, longitude {{3}} where you are east or west of the prime meridian in Greenwich, England — which, by convention, has a longitude of 0 degree.', NULL, NULL, NULL, E'1.where, 2.poles, 3.measures', NULL, NULL),
