  ('100be3d7-1f75-5ce0-a119-2df04e33c84e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '100be3d7-1f75-5ce0-a119-2df04e33c84e'::uuid, 1, NULL, TRUE, 0, NULL, E'Health Budget', E'The projected decline of government spending in many low income countries will restrict their ability to strengthen pandemic preparedness and limit their progress towards universal health coverage. This will lead to growing inequalities between countries, threatening global stability, and prosperity. Thus, governments need to give greater priority to health in budgets, and improve the efficiency of health spending.', NULL, NULL, NULL, NULL, NULL, NULL),
