  ('1015741b-fbdf-5912-95b1-b50506bd159f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1015741b-fbdf-5912-95b1-b50506bd159f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '29de10be-dcab-5134-90eb-2da818e95a90'::uuid, NULL, NULL, E'Journalism is undergoing a crisis due to the digital age.', NULL, NULL),
  ('1018a06c-6788-5aeb-a1b0-c284fa125b12'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1018a06c-6788-5aeb-a1b0-c284fa125b12'::uuid, 1, NULL, TRUE, 0, NULL, E'Language of Lying', NULL, '876f1e1d-8c29-59b9-98e2-40f21a31b304'::uuid, NULL, E'According to the literature on reality monitoring, stories based on imagined experiences are qualitatively different from those based on real experiences. This suggests that creating a false story about a personal topic takes work and results in a different pattern of language use. A technology known as linguistic text analysis has helped to identify four such common patterns in the subconscious language of deception. First, liars reference themselves less, when making deceptive statements. They write or talk more about others, often using the third person to distance and disassociate themselves from their lie, which sounds more false: “Absolutely no party took place at this house,” or “I didn’t host a party here.” Second, liars tend to be more negative, because on a subconscious level, they feel guilty about lying. For example, a liar might say something like, “Sorry, my stupid phone battery died. I hate that thing.” Third, liars typically explain events in simple terms since our brains struggle to build a complex lie. Judgment and evaluation are complex things for our brains to compute. As a U.S. President once famously insisted: “I did not have sexual relations with that woman.” And finally, even though liars keep descriptions simple, they tend to use longer and more convoluted sentence structure, inserting unnecessary words and irrelevant but factual sounding details in order to pad the lie.', NULL, NULL, NULL),
