  ('107fff5b-f68d-5ce6-8502-1dd08cbda7dc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '107fff5b-f68d-5ce6-8502-1dd08cbda7dc'::uuid, 1, NULL, TRUE, 0, NULL, E'Atmospheric Rivers', E'The formation of an atmospheric river starts near the equator. The sun heats the earth most directly at the equator, and these warm {{1}} cause water to evaporate and {{2}} into the atmosphere. Some of that water vapor is pulled away from the equator by atmospheric circulation, forming a narrow band that can {{3}} the water vapor to other regions like a conveyor belt.', NULL, NULL, NULL, E'1.temperatures, 2.rise, 3.transport', NULL, NULL),
