  ('1096252f-0814-511b-8675-63f6a87cb1f2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1096252f-0814-511b-8675-63f6a87cb1f2'::uuid, 1, NULL, TRUE, 0, NULL, E'Black Holes', E'Conventional theories about black holes, based on Einstein''s theory of General Relativity, typically explain how static or spinning black holes can exist on their own, isolated in space. Black holes in pairs would eventually be thwarted by gravity attracting and colliding them together. However, this is true if one assumes the Universe is standing still. But what about one which is constantly moving?', NULL, NULL, NULL, NULL, NULL, NULL),
  ('109cb3db-54df-55be-ad78-0233ae7486f2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '109cb3db-54df-55be-ad78-0233ae7486f2'::uuid, 1, NULL, TRUE, 0, NULL, E'Pre-Raphaelitism', E'Pre-Raphaelitism was Britain''s most significant and influential 19th-century art movement. Founded in 1848, it {{1}} on a group of three young artists: William Holman Hunt, Dante Gabriel Rossetti and John Everett Millais. These artists sought to revive English art by radically turning away from the old studio {{2}} and bringing painting into direct {{3}} with nature. With an eye for absolute {{4}} ,every detail was now to have intense realist as well as {{5}} meaning.', NULL, NULL, NULL, E'1.centered, 2.tradition, 3.contact, 4.accuracy, 5.symbolic', NULL, NULL),
  ('10a0a637-0384-5a24-bde7-de8ff8f6fb9b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '10a0a637-0384-5a24-bde7-de8ff8f6fb9b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'In which subject would you learn gravity, physics or chemistry?', '9b0d5e3b-d047-5cbf-91e7-43ea793ebf13'::uuid, NULL, NULL, E'Physics', NULL, NULL),
