  ('10b0b62a-4df7-56cc-b233-ae8e0fabf3e3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '10b0b62a-4df7-56cc-b233-ae8e0fabf3e3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '1f78d2e8-7b10-50f7-8e00-b16bd234303e'::uuid, NULL, E'Obese people tend to have higher blood pressure than lean people.', NULL, NULL, NULL),
  ('10b0c47a-72f9-5304-b9d3-f1d2955a1a2c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '10b0c47a-72f9-5304-b9d3-f1d2955a1a2c'::uuid, 1, NULL, TRUE, 0, NULL, E'Language Usage', E'Some languages are increasingly spoken in different countries, while the usage of others is rapidly declining. Is this a positive or a negative development?', NULL, NULL, NULL, NULL, 200, 300),
  ('10b57dc9-77c8-5fc4-b0f3-412ace50dacd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '10b57dc9-77c8-5fc4-b0f3-412ace50dacd'::uuid, 1, NULL, TRUE, 0, NULL, E'Memory Retention', NULL, NULL, NULL, NULL, E'3, 4, 1, 2', NULL, NULL),
  ('10b67dc6-3a96-5953-893d-e2750012fd55'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '10b67dc6-3a96-5953-893d-e2750012fd55'::uuid, 1, NULL, TRUE, 0, NULL, E'NGO V2', NULL, '6578cda1-688d-5c6d-97ce-bcc717dafb9e'::uuid, NULL, E'A non-governmental organization (NGO) is an organization that is neither a part of a government nor a conventional for–profit business.\nUsually set up by ordinary citizens, NGOs may be funded by governments, foundations, businesses, or private persons. Some avoid formal funding altogether and are run primarily by volunteers. NGOs are highly diverse groups of organizations engaged in a wide range of activities, and take different forms in different parts of the world. Some may have charitable status, while others may be registered for tax exemption based on recognition of social purposes. Others may be fronts for political, religious, or other interests.\nThe number of NGOs in the United States is estimated at 1.5 million. Russia has 277,000 NGOs. India is estimated to have had around 2 million NGOs in 2009, just over one NGO per 600 Indians, and many times the number of primary schools and primary health centres in India. NGOs are difficult to define, and the term ‘NGO’ is rarely used consistently. As a result, there are many different classifications in use. The most common focus is on “orientation” and “level of operation”. An NGO’s orientation refers to the type of activities it takes on. These activities might include human rights, environmental, improving health, or development work. An NGO’s level of operation indicates the scale at which an organization works, such as local, regional, national, or international.\nSample Answer: This lecture mainly talks about the non-governmental organization. NGOs may be funded by governments, foundations, businesses or private persons. The number of NGOs in the US is 1.5 million and India has around 2 million in 2009. It is difficult to define NGO as the activities are highly diverse, some may have charitable status while others maybe registered for tax exemption.', NULL, NULL, NULL),
  ('10c94745-0751-541d-b73b-038263cc9772'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '10c94745-0751-541d-b73b-038263cc9772'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the sport where players hit a small, hard ball with a bat and run around four bases?', '5adf10fb-2b8b-5ed6-8523-05768e57f3ca'::uuid, NULL, NULL, E'Baseball', NULL, NULL),
  ('10cb83ca-8542-5b06-a739-cf6c639a43af'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '10cb83ca-8542-5b06-a739-cf6c639a43af'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the fruit with a fuzzy brown skin and green flesh, known for its high vitamin C content?', 'fb43eb28-8720-5ac3-a33f-8f781424358c'::uuid, NULL, NULL, E'Kiwi', NULL, NULL),
  ('10cfee80-3abd-527e-b00d-aec9fc743a21'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'HIGHLIGHT_CORRECT_SUMMARY', E'HIGHLIGHT_CORRECT_SUMMARY', E'LISTENING', E'SHARED', NULL, E'APPROVED', '10cfee80-3abd-527e-b00d-aec9fc743a21'::uuid, 1, NULL, TRUE, 0, NULL, E'Procrastination', E'To understand the roots of procrastination helps us weaken it. We know where it comes from: “Ah, I can be aware of and see these dynamics happening in front of me.” But another kind of awareness is to gain awareness of what we’re feeling. What do approach motives feel like versus avoidance? We know when we’re cleaning the fridge in our dorm room the night before the final exam that that’s procrastination. But there are other times it’s not so clear. Is checking your email procrastination? Is studying or doing the task on the low-important item on your list–is that procrastination? A lot of times it is. So the more we know, the greater awareness we have of our tendencies and our motivations, we’re more likely to overcome them. So we want to cultivate a stance, an observer’s stance, and say, “What does this feel like? What am I experiencing? What am I thinking?” So that we can then actively choose what we want to feel and think and what we’re motivated by.\n\nClick on the paragraph that best relates to the recording.', '0343557a-5358-5b32-94d9-f5bdf9cae843'::uuid, NULL, NULL, E'To overcome procrastination, we should gain awareness of our approach motives or avoidance motives when doing things, which means that we need to cultivate an observer’s stance to examine ourselves.', NULL, NULL),
  ('10d0bdbe-2fe0-5d9b-9957-b9fc3eb7e398'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '10d0bdbe-2fe0-5d9b-9957-b9fc3eb7e398'::uuid, 1, NULL, TRUE, 0, NULL, E'Economists and Ecologists', E'There is a pointless argument between economists and ecologists over which {{1}} is more important — the ecosphere or the economy? The materialistic {{2}} is that their fates are interlinked. We know the natural world only by interacting with it and transforming it: nature {{3}} us that way. Even if, as some supporters of ''deep ecology'' {{4}} , the earth would be better off without us, it is to us that the task of saving it falls.', NULL, NULL, NULL, E'1.crisis, 2.answer, 3.produced, 4.argue', NULL, NULL),
  ('10d99987-340d-53c2-b896-99fc6ca1c61f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '10d99987-340d-53c2-b896-99fc6ca1c61f'::uuid, 1, NULL, TRUE, 0, NULL, E'An Important Measuring(一个重要的方法)', NULL, NULL, NULL, NULL, E'4, 2, 1, 3', NULL, NULL),
  ('10df920e-d1f6-5d56-997e-edc44915e7f6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '10df920e-d1f6-5d56-997e-edc44915e7f6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '21ce02cf-e002-5ad4-b6fc-2ea41d48291a'::uuid, NULL, NULL, E'Any laboratory activities must be under the guidance of teachers.', NULL, NULL),
  ('10ea0979-fcef-5cf1-919e-b3e2cf948fcc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '10ea0979-fcef-5cf1-919e-b3e2cf948fcc'::uuid, 1, NULL, TRUE, 0, NULL, E'Heat Shock Response', E'This "heat shock response" of cells is a classic model of biological adaptation, part of the fundamental processes of life -- conserved in creatures from single-celled yeast to humans -- that allow our cells to adjust to changing conditions in their environment. For years, scientists have focused on how different genes respond to heat stress to understand this survival technique.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('10f28cc4-0d35-56da-800d-a3f944397b56'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '10f28cc4-0d35-56da-800d-a3f944397b56'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '60b7d3a9-6f1c-58bd-a5a2-3b67f40cf517'::uuid, NULL, E'Rules about breaks and lunch time vary from one company to another.', NULL, NULL, NULL),
