  ('1161b981-5f1d-51fb-abf2-f05741f159a2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '1161b981-5f1d-51fb-abf2-f05741f159a2'::uuid, 1, NULL, TRUE, 0, NULL, E'Daydream', E'Everyone knows the pleasures of daydreaming. Whether {{1}} your next vacation or an ideal romantic partner, it is enjoyable to let your mind {{2}} into a stream of consciousness where {{3}} come alive. Better yet, research shows that, far from being a waste of time, daydreaming has all {{4}} of benefits and is particularly important for developing brains.', NULL, NULL, NULL, E'1.envisioning, 2.drift, 3.aspirations, 4.sorts', NULL, NULL),
