  ('11878cc9-a144-5643-a89d-74c65fda4ff9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '11878cc9-a144-5643-a89d-74c65fda4ff9'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the female head of a family?', '747ef674-8aa0-5ad6-899a-78020b92887e'::uuid, NULL, NULL, E'Mistress / hostess / matriarch', NULL, NULL),
  ('11889d9a-1ed0-5655-933e-c463a62216ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '11889d9a-1ed0-5655-933e-c463a62216ca'::uuid, 1, NULL, TRUE, 0, NULL, E'Clown Fish', E'Clown fish became famous thanks to the movie Finding Nemo. In real life, their social hierarchy is simple: larger fish dominate their smaller {{1}} . Now we know that to reinforce this social structure, the fish communicate with aggressive and submissive audio signals. The new info is in the journal PLoS ONE.\nResearchers {{3}} clown fish calls, {{4}} this noise as one chased a smaller fish. These popping sounds function as an aggression signal. When a clown fish has been chased and wishes to submit, it shakes its head in a submissive gesture and produces clicking noises like these. The researchers {{6}} the aggressive and submissive calls, and found that the sound pulses in a submissive signal were shorter and more high-pitched.\nUnlike many animals that use sound to draw in {{7}} mates, clown fish appear to use their calls only as labels of social status. When a little fish makes submissive sounds to a larger one, neither has to invest in a physical confrontation. Which is good news for small-fry like Nemo.', NULL, NULL, NULL, E'1.counterparts, 2.recorded, 3.capturing, 4.compared, 5.potential', NULL, NULL),
  ('118b9e0a-8a34-575f-b242-5f5a22cbcaca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '118b9e0a-8a34-575f-b242-5f5a22cbcaca'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '10418ca3-3a3c-5b2b-a4f9-2695e2c474f7'::uuid, NULL, E'It is important to validate all assumptions before arriving at a conclusion.', NULL, NULL, NULL),
  ('118bb69f-416b-5d84-8475-ef9d28e56d8a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '118bb69f-416b-5d84-8475-ef9d28e56d8a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3af40c6c-07c4-509f-b535-ade2725f7dce'::uuid, NULL, E'The real reason for global hunger is not the lack of food, but poverty.', NULL, NULL, NULL),
  ('118f0962-fa71-5b05-9768-7fd14d623259'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '118f0962-fa71-5b05-9768-7fd14d623259'::uuid, 1, NULL, TRUE, 0, NULL, E'Exceptional Health', NULL, NULL, NULL, NULL, E'5, 3, 2, 1, 4', NULL, NULL),
  ('118fe059-7d9d-593a-b158-95d80763530d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '118fe059-7d9d-593a-b158-95d80763530d'::uuid, 1, NULL, TRUE, 0, NULL, E'Survey', NULL, '5d4a0473-bcff-5236-b345-2927f379bf3c'::uuid, NULL, E'Let''s say if I''m asking which source do you often use to get information. Newspaper? Radio? And the survey shows 62% of the people chose internet. You might be thinking I am going to say, how important the internet is, or how quickly it has changed the world for a few years. But what if I tell you this survey is conducted on the website global and mail.com? Our answer will be different. Because the people who did this survey on a website must be frequent users of internet. This sample is a biased sample. So we have to pay attention to how a survey is conducted.', NULL, NULL, NULL),
  ('119454cb-985f-5355-ab3e-8094b9fe111e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '119454cb-985f-5355-ab3e-8094b9fe111e'::uuid, 1, NULL, TRUE, 0, NULL, E'Experiential Learning', E'Do you agree that learning through experience is more effective than formal education?', NULL, NULL, E'Learning through experience surpasses formal education in effectiveness, offering unique advantages that foster practical skills, personal growth, and real-world relevance. The immersive nature of experiential learning provides individuals with invaluable opportunities to develop skills and insights that go beyond traditional classroom settings.\nExperience allows for hands-on learning and practical application of knowledge, which is often more impactful than passive learning in formal educational settings. Through direct engagement with tasks and projects, individuals gain a deeper understanding of concepts and develop essential skills that are transferable to real-world scenarios. The hands-on approach fosters active participation and critical thinking, enhancing the learning experience and retention of knowledge.\nExperiencing challenges firsthand not only facilitates personal growth but also cultivates resilience and adaptability. Unlike formal education, which may follow a standardized curriculum, experiential learning offers personalized growth opportunities tailored to individual needs and interests. Learning from experience provides real-world relevance by equipping individuals with practical skills, problem-solving abilities, and adaptability to navigate diverse situations effectively. This real-world applicability enhances the value of experiential learning in preparing individuals for success in various contexts.\nIn conclusion, the effectiveness of learning through experience lies in its ability to promote hands-on learning, personalized growth, and real-world relevance. By engaging in experiential learning opportunities, individuals can acquire practical skills, foster personal growth, and develop a deep understanding of real-world applications. Embracing practical learning as a complement to formal education enhances the learning process, equipping individuals with the tools and experiences necessary for success in today''s dynamic and ever-evolving world.', NULL, 200, 300),
  ('119be582-4df3-5a37-80a1-748b540375de'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '119be582-4df3-5a37-80a1-748b540375de'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '55ef101b-7001-5dd9-834c-10c74660600c'::uuid, NULL, E'Sam is researching the relationship between social classes and education.', NULL, NULL, NULL),
