  ('11e08112-61fd-520c-94d4-3f05b6c78bee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '11e08112-61fd-520c-94d4-3f05b6c78bee'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a2ca455f-8ffa-5a7c-94e0-4104bcfef5a2'::uuid, NULL, E'Academic writing is characterized by its frequent use of formal vocabulary.', NULL, NULL, NULL),
  ('11e44b88-2a8d-5779-a3f5-576996ce1df1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '11e44b88-2a8d-5779-a3f5-576996ce1df1'::uuid, 1, NULL, TRUE, 0, NULL, E'Ants and Insulin', E'The scientists found that division of reproductive labor in ants arose when an ancient insulin signaling pathway, typically involved in maintaining nutrition and growth, became responsive to social cues. In doing so, they also uncovered deeper insights into a process underlying how the environment gets under the skin to affect behavior, physiology, and the health and well-being of other members of a society.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('11e6d6f2-071f-5d21-a5c2-4b719a8eeb0e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '11e6d6f2-071f-5d21-a5c2-4b719a8eeb0e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '69138303-339f-5ce6-9184-6b55c62fa2d3'::uuid, NULL, NULL, E'The paper must be reviewed thoroughly and appropriately.', NULL, NULL),
  ('11ed5cf7-1f56-5b83-ac48-32f59a2ef34a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '11ed5cf7-1f56-5b83-ac48-32f59a2ef34a'::uuid, 1, NULL, TRUE, 0, NULL, E'Emotional Well-being', E'The emotional well-being of children is a significant concern, and it is essential to provide them with the tools and support they need to {{1}} their feelings and navigate the complexities of their emotions. One crucial aspect of emotional intelligence is self-awareness. Encouraging children to {{2}} their own emotions and recognize them in others promotes empathy and effective communication. Additionally, teaching children healthy ways to cope with stress and adversity can {{3}} their resilience. Skills such as problem-solving, relaxation techniques, and seeking support when needed are valuable in managing life''s challenges. Moreover, creating a safe and nurturing environment where children feel heard and supported can significantly {{4}} their emotional well-being and overall happiness.', NULL, NULL, NULL, E'1.acknowledge, 2.explore, 3.nurture, 4.bolster', NULL, NULL),
  ('11ef5f0f-a6c6-5ab9-959b-0b78b689dcd5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '11ef5f0f-a6c6-5ab9-959b-0b78b689dcd5'::uuid, 1, NULL, TRUE, 0, NULL, E'Organic Farming', E'Organic farming is a sustainable practice that promotes biodiversity and protects the environment from harmful chemicals and pesticides. Organic farming prioritizes soil health and uses natural methods to control pests and diseases instead of relying on synthetic chemicals. By supporting organic farming practices, we can promote healthier ecosystems and protect the health of our planet.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('11f33b1a-98c6-59d3-9ec5-4af1f6f73131'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '11f33b1a-98c6-59d3-9ec5-4af1f6f73131'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c95cf877-98a8-54dd-b38b-04226f0995ab'::uuid, NULL, NULL, E'Requests for late applications will not be accepted under any circumstances.', NULL, NULL),
  ('11f699e7-77f0-5be3-9614-c2e3fadfdbec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '11f699e7-77f0-5be3-9614-c2e3fadfdbec'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3bb3a4e1-c091-57ab-b082-052211b13b0f'::uuid, NULL, E'A new report outlines ways in which cities should address transport issues.', NULL, NULL, NULL),
  ('1202332b-b7d3-5269-b91e-6525ccbced11'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1202332b-b7d3-5269-b91e-6525ccbced11'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f9ae898d-fa0b-5576-9429-843a1da707a3'::uuid, NULL, NULL, E'I went to the school at the bottom of our street.', NULL, NULL),
  ('12040eb9-964c-5a34-b37c-c232bf73efc4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '12040eb9-964c-5a34-b37c-c232bf73efc4'::uuid, 1, NULL, TRUE, 0, NULL, E'Modern Technology', E'Modern technology has brought about significant changes in our daily lives, transforming the way we {{1}} , work, and communicate. The advent of the internet and smart devices has made information {{2}} at our fingertips, empowering individuals with unprecedented access to knowledge. However, this rapid technological progress is not without its challenges. Privacy concerns and the potential for technology to {{3}} social interactions are issues that require careful consideration. Despite these concerns, innovations in technology continue to provide solutions to global {{4}} , such as climate change and healthcare. As a result, modern technology remains a {{5}} force shaping our future.', NULL, NULL, NULL, E'1.live, 2.accessible, 3.weaken, 4.challenges, 5.transformative', NULL, NULL),
  ('1204ad2b-fbb9-5f85-8a02-c69ebee0147c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1204ad2b-fbb9-5f85-8a02-c69ebee0147c'::uuid, 1, NULL, TRUE, 0, NULL, E'Salary Types', NULL, '4719919e-7b84-546b-807f-e7d786537671'::uuid, NULL, E'Straight salary sales compensation plans aren''t very common, but they do have a place in some organizations. With this type of structure, you''d pay your sales people a straight albeit competitive salary like all of your other employees, and nothing else. No bonuses, no commissions, and few, if any, sales incentives.\nThis type of compensation plan is most often used when the industry you operate within prohibits direct sales, when sales people work as part of small groups or teams and all contributions are equal, when your sales team is relatively small, or when your sales people are expected to spend much of their time on other responsibilities other than selling.\nHowever, these plans don''t tend to offer motivation to sales people, as there are no incentives for them to work harder.\nSalary plus commission sales compensation plans are possibly the most common plans used today. They''re structured in a way that sales people receive a lower base salary along with commission pay that makes up the majority of the total compensation.\nOrganizations use salary plus commission sales compensation plans when there are opportunities to support all sales people on this structure and when there are proper metrics in place for tracking sales to ensure that the splits are fair and accurate.\nThis type of plan is often the better choice as opposed to straight salary because it offers motivation to increase productivity and to achieve goals. It also offers more stability. Sales people will still get some types of pay even if they''re in training, when sales are low during certain months, or if market conditions get volatile. However, it can be more complex to administer.\nCommission only sales compensation plans are exactly what they sound like you pay your sales people for the sales they bring in and nothing else. There is no guarantee of income.\nThese types of plans are easier to administer than salary plus commission and provide better value for your money paid as they are based solely on sales achieved. They also tend to attract fewer candidates, but do attract the most top-performing and hardest working sales professionals who know they can make a good income because they know how to sell. On the other hand, though, they can create aggression within your sales team and low income security, which can lead to a high turnover rate, and sales rep burnout from stress.', NULL, NULL, NULL),
  ('1205066c-e93c-55df-9836-86b84cdd3cbe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1205066c-e93c-55df-9836-86b84cdd3cbe'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '79da1e80-5899-541e-8e9c-3e36f07aeb0f'::uuid, NULL, E'The original Olympic Games were celebrated as religious festivals.', NULL, NULL, NULL),
  ('120b44dc-9eb2-57c6-a6a3-a97a641cec48'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '120b44dc-9eb2-57c6-a6a3-a97a641cec48'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '87abcb41-1a09-5774-a874-a6c8a7afb493'::uuid, NULL, E'Many medical volunteers no longer have access to medical literature.', NULL, NULL, NULL),
  ('1210c1d8-2f02-51d7-a938-b37456cee135'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '1210c1d8-2f02-51d7-a938-b37456cee135'::uuid, 1, NULL, TRUE, 0, NULL, E'Psychological Theories', E'Attempts to apply psychological theories to education can falter on the translation of the {{1}} into educational practice. Often, this translation is not clear. Therefore, when a program does not succeed, it is not clear whether the {{2}} of success was due to the inadequacy of the theory or the inadequacy of the implementation of the theory. A {{3}} of basic principles for translating a theory into practice can help clarify just what an educational implementation should (and should not) look like. This article presents 12 principles for translating a triarchic theory of successful intelligence into educational practice.', NULL, NULL, NULL, E'1.theory, 2.lack, 3.set', NULL, NULL),
  ('121873ee-4456-5df0-b144-5f3cdc5caa94'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '121873ee-4456-5df0-b144-5f3cdc5caa94'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '83cfe5d0-0a35-5245-bcd9-3c70fe1021c9'::uuid, NULL, NULL, E'He has discovered many facts to back up this theory.', NULL, NULL),
  ('121d4b23-f8f4-52bf-85d1-4046507bd48b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '121d4b23-f8f4-52bf-85d1-4046507bd48b'::uuid, 1, NULL, TRUE, 0, NULL, E'Australian Indigenous Food', E'In its periodic quest for culinary identity, Australia automatically looks to its indigenous ingredients, the foods that are native to this country. ''''There can be little doubt that using an indigenous product must qualify a dish as Australian'''', notes Stephanie Alexander. Similarly, and without qualification, states that a uniquely Australian food culture can only be based upon foods indigenous to this country. However, as Craw remarks, proposing Australian native foods as national symbols relies more upon their association with nature and geographic origin than on common usage. Notwithstanding the lack of justification for the premise that national dishes are, of necessity, founded on ingredients native to the country—after all, Italy''s gastronomic identity is tied to the non-indigenous tomato, Thailand''s to the non-indigenous chili—the reality is that Australians do not eat indigenous foods in significant quantities. The exceptions are fish, crustaceans and shellfish from oceans, rivers and lakes, most of which are unarguably unique to this country. Despite valiant and well-intentioned efforts today at promoting and encouraging the consumption of native resources, bush foods are not harvested or produced in sufficient quantities for them to be a standard component of Australian diets, nor are they generally accessible. Indigenous foods are less relevant to Australian identity today than lamb and passionfruit, both initially imported and now naturalized.', NULL, NULL, E'Australia automatically looks to its indigenous ingredients, and a uniquely Australian food culture can only be based upon foods indigenous to this country, but bush foods are not harvested or produced in sufficient quantities for them to be a standard component of Australian diets, nor are they generally accessible, so indigenous foods are less relevant to Australian identity today than lamb and passionfruit, both initially imported and now naturalized.', NULL, 5, 75),
  ('121ffd50-c876-5e6b-b2ac-49fece64ad6e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '121ffd50-c876-5e6b-b2ac-49fece64ad6e'::uuid, 1, NULL, TRUE, 0, NULL, E'Plate Tectonics', NULL, NULL, NULL, NULL, E'2, 3, 1, 4', NULL, NULL),
  ('1221854e-aa3b-516d-9fd6-6220c94cdb4c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '1221854e-aa3b-516d-9fd6-6220c94cdb4c'::uuid, 1, NULL, TRUE, 0, NULL, E'Brainstorming', E'Brainstorming is a {{1}} process often used in decision making, particularly when working in a group. The idea is to generate as many {{2}} solutions as possible without immediate criticism, and then later refine and evaluate them. This method has been proven effective in academic, business, and organizational {{3}} .', NULL, NULL, NULL, E'1.creative, 2.potential, 3.settings', NULL, NULL),
  ('122dc4f1-3fa5-59ee-b8d3-c26a653e0b94'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '122dc4f1-3fa5-59ee-b8d3-c26a653e0b94'::uuid, 1, NULL, TRUE, 0, NULL, E'Right Balance', E'Nowadays, it is increasingly more difficult to maintain the right balance between work and the other aspects of one''s life, such as leisure pursuits with family members. How important do you think this balance is and what are the reasons why some people think that this is hard to achieve?', NULL, NULL, E'In the contemporary world, juggling work commitments alongside personal and familial pursuits has become a pressing concern. Despite the challenges posed by demanding workloads, this essay posits that striking a balance between work and other facets of life is attainable and pivotal for holistic satisfaction.\nOne compelling reason to endorse the positive standpoint is the impact on personal well-being. Striking a harmonious balance between work and other activities alleviates stress, reduces burnout, and fosters better mental health. Engaging in leisure pursuits and spending quality time with family members rejuvenates the mind and nurtures relationships, resulting in increased overall happiness and satisfaction.\nFurthermore, achieving equilibrium yields enhanced productivity and job satisfaction. A well-rested mind, nurtured by non-work-related activities, can approach professional tasks with renewed vigor. People who can partake in leisure activities and connect with family members tend to feel more fulfilled in both spheres of life. This sense of accomplishment and contentment transcends into higher work performance and efficiency.\nIn conclusion, while heavy workloads might pose challenges to maintaining a balanced life, the benefits of doing so are compelling. Enhanced well-being and increased productivity underscore the importance of successfully navigating the demands of work and personal pursuits. Balancing work commitments with leisure and familial engagements is not only feasible but essential for leading a fulfilling and satisfying life.', NULL, 200, 300),
  ('1231a44f-a3e1-5703-ba79-2a3388138261'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1231a44f-a3e1-5703-ba79-2a3388138261'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which part of the human body is related to the word ''visual''?', 'a1a3c535-4bb9-5bf7-a8d9-3532f68dbbed'::uuid, NULL, NULL, E'Eye', NULL, NULL),
