  ('12407df8-0a45-584b-8cdd-7c10104b39a0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '12407df8-0a45-584b-8cdd-7c10104b39a0'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the device used to heat food quickly using microwave radiation?', '5a0e8c5d-65a2-5dfa-a4aa-bf9ebaecc7b4'::uuid, NULL, NULL, E'Microwave Oven', NULL, NULL),
  ('12414467-76da-5fa9-a931-9dc1ca596d93'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '12414467-76da-5fa9-a931-9dc1ca596d93'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c863b862-2883-5687-8b32-8e7b42972f27'::uuid, NULL, NULL, E'Chosen people will work together on big research projects.', NULL, NULL),
  ('124a0c27-e0b3-5b29-abd8-462c88e0f850'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '124a0c27-e0b3-5b29-abd8-462c88e0f850'::uuid, 1, NULL, TRUE, 0, NULL, E'Vulnerable Group', E'The second group that is particularly vulnerable are night shift workers, and the third group that is particularly vulnerable are people with sleep disorders, particularly sleep apnea. One out of three men and one out of six women have sleep apnea. And yet, 85 percent are undiagnosed and untreated. And it more than doubles the risk of cancers.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('124a74e8-12c6-5e9b-9ff4-e2c76faf2f59'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '124a74e8-12c6-5e9b-9ff4-e2c76faf2f59'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b9bb6d26-2323-5249-80c5-f500be2984c1'::uuid, NULL, E'The new system is the focus of controversy among the public.', NULL, NULL, NULL),
  ('12506485-04b7-56ef-9dc5-da27c2fd3e12'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', '12506485-04b7-56ef-9dc5-da27c2fd3e12'::uuid, 1, NULL, TRUE, 0, NULL, E'SMW', E'Too many students search for material by going to what they think is the right shelf in the library, finding little or nothing and then reporting back to their tutor that there''s nothing on it in the library. If you have some authors and titles in mind, look them up in the catalogue - they may not be where you think- and look at adjacent entries in the catalogue and on the shelves. The catalogue may lead you to restricted loan collections, reserve stacks or departmental collections, which may not always be obvious. You should also check the subject catalogue, trying to think of related terms. Other places to look would be the references shelves and newspaper section, though a problem here is finding [BEEP)\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '7da284a4-c79a-5bee-a007-90fa7d54fe17'::uuid, NULL, NULL, E'the article you ''re looking for', NULL, NULL),
  ('1250b4e5-f0c9-521e-bd05-827b31ba8aea'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1250b4e5-f0c9-521e-bd05-827b31ba8aea'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which building material comes from tree trunks?', '2d2e4b7a-cdfd-55da-bf0f-f5485c356f0b'::uuid, NULL, NULL, E'Wood', NULL, NULL),
  ('1256485b-59f1-552c-9c18-1e76be0b2898'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1256485b-59f1-552c-9c18-1e76be0b2898'::uuid, 1, NULL, TRUE, 0, NULL, E'Smoking Ban', E'A smoking ban is a public policy that includes criminal laws and health regulations that prohibit smoking in certain public places and workspaces. There are varying definitions of smoking employed in this legislation. The strictest definitions define smoking as being the inhalation of any tobacco substance while the loosest define smoking as possessing any lit tobacco product.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('125e93b1-5c92-52f0-8385-c801297d2ad9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '125e93b1-5c92-52f0-8385-c801297d2ad9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '959c9c62-61fd-539f-a7d0-05b24bb8ea4d'::uuid, NULL, NULL, E'Working with these kinds of students is not enough.', NULL, NULL),
  ('125fa06b-50eb-540f-b523-3dd8f1a42162'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '125fa06b-50eb-540f-b523-3dd8f1a42162'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6d644386-eb8b-5f46-be90-e6fd334a7c45'::uuid, NULL, E'She was really upset about the way her father treated her.', NULL, NULL, NULL),
  ('1266ab30-5bde-52e0-aa9d-b124cf0d21be'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1266ab30-5bde-52e0-aa9d-b124cf0d21be'::uuid, 1, NULL, TRUE, 0, NULL, E'Bees', E'Bees are more than just buzzing insects; they play an essential role in our ecosystem. Bees pollinate flowers, fruits, and vegetables, resulting in the production of food. Without them, the world''s food supply would be severely affected. Sadly, bees have been in danger due to the use of pesticides, changes in land use, and global warming.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('1269e6be-e2ac-51f4-b16d-a34715d2fcf4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1269e6be-e2ac-51f4-b16d-a34715d2fcf4'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0ab5e271-78ea-581f-857d-53ce6879d63c'::uuid, NULL, E'Our profits from exports have more than doubled this year.', NULL, NULL, NULL),
  ('126e304b-7a61-58ee-a121-88a56059529c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '126e304b-7a61-58ee-a121-88a56059529c'::uuid, 1, NULL, TRUE, 0, NULL, E'Violence on Television', E'It''s not good for a child to be exposed constantly to television violence. Research has shown such exposure has at least four effects: children may become less sensitive to the pain and suffering of others; may become more fearful of the world around them; may be more likely to behave in an aggressive manner toward others; may get an unrealistic sense of the amount of true violence in the world.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('126ef9fc-5046-5831-a596-0846f38780ad'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '126ef9fc-5046-5831-a596-0846f38780ad'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7878ea1f-2d8a-5c44-b41f-e07ed8c74845'::uuid, NULL, NULL, E'A disease that was once dangerous is now no longer a threat.', NULL, NULL),
  ('127433c0-ead7-5872-993d-c970a2951d42'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '127433c0-ead7-5872-993d-c970a2951d42'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-L', E'How would you define "reasonable" as it is used in law? For example, you are allowed to use "reasonable force" when defending yourself. It seems to depend on how serious the situation was, whether it was possible to resolve it by peaceful means, whether you were ready to try those means and, finally, the relative strengths of those involved. Now, most men know, and they''ve probably grasped this from their earliest years in the school playground, that, when it comes to blows, fights don''t stop until one of you is in no shape to do any damage to the other. The criteria mentioned seem a bit fuzzy to me. How can you convince a jury you were ready to try and talk your way out of it when the other person would have none of it and, besides, he was quick to land the first punch? Also you can strike the first blow and still plead self-defence.\nOf course, you again have the problem of convincing people that the threat was so great that you had no alternative, apart from getting beaten up yourself. Reacting calmly and rationally to a perceived threat is not easy to do.\n\nWhich of the following is true according to the speaker?', '71d033c5-2b26-513e-922e-a8e2a977e1db'::uuid, NULL, NULL, E'Your use of force may be judged on how strong you are compared to the other person.', NULL, NULL),
  ('1274e8bc-9567-506a-877d-a934c6383d62'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1274e8bc-9567-506a-877d-a934c6383d62'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd95d4168-2aee-55b3-a942-1cb4aa7d8a32'::uuid, NULL, E'Rain, snow and hail are collectively known as precipitation.', NULL, NULL, NULL),
  ('12758ebb-dbb7-5ef4-989a-5bf0e4809ab1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '12758ebb-dbb7-5ef4-989a-5bf0e4809ab1'::uuid, 1, NULL, TRUE, 0, NULL, E'Pollination', NULL, NULL, NULL, NULL, E'4, 2, 1, 3', NULL, NULL),
  ('127cfab7-a4c4-5b47-9ffe-fcd823308f73'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '127cfab7-a4c4-5b47-9ffe-fcd823308f73'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c406d071-9d94-5b15-bc63-7779ff67e2f1'::uuid, NULL, NULL, E'These push buttons can activate the elevator.', NULL, NULL),
  ('127f712c-1cd0-5ddf-8e3f-e9f7edd94ad7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '127f712c-1cd0-5ddf-8e3f-e9f7edd94ad7'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which symbol is used to complete a sentence?', 'ea6bffcc-1ea4-541c-8472-65241f539759'::uuid, NULL, NULL, E'Full stop / period', NULL, NULL),
  ('128efa5e-a621-51f4-8b75-92c43e8b0e47'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '128efa5e-a621-51f4-8b75-92c43e8b0e47'::uuid, 1, NULL, TRUE, 0, NULL, E'Education Equality or Quality', NULL, '5e7d91fd-a454-5f7e-8512-4919b7018c5d'::uuid, NULL, E'When Australians engage in debate about educational quality or equity, they often seem to accept that a country cannot achieve both at the same time. Curriculum reforms intended to improve equity often fail to do so because they increase breadth or differentiation in offerings in a way that increases differences in quality. Further, these differences in quality often reflect differences in students'' social backgrounds because the ''new'' offerings are typically taken up by relatively disadvantaged students who are not served well them. Evidence from New South Wales will be used to illustrate this point.The need to Improve the quality of education is well accepted across OECD and other countries as they seek to strengthen their human capital to underpin their modern, knowledge economies. Improved equity is also important for this purpose, since the demand for high—level skills is widespread and the opportunities for the low — skilled are diminishing.Improved equity in education is also important for social cohesion. There are countries in which the education system seems primarily to reproduce existing social arrangements, conferring privilege where it already exists and denying it where it does not. Even in countries where the diagnosis might be less extreme, the capacity of schooling to build social cohesion is often diminished by the way in which schools separate individuals and groups.', NULL, NULL, NULL),
  ('1293db42-10ea-5ca8-97eb-0ffaf5e0b3b5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1293db42-10ea-5ca8-97eb-0ffaf5e0b3b5'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0cf41872-faf5-56ae-bc9e-252153f1ece4'::uuid, NULL, E'The Soviet Union sent the very first human into space.', NULL, NULL, NULL),
  ('12945045-7e0b-590b-8113-d2d72c6c8416'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '12945045-7e0b-590b-8113-d2d72c6c8416'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What will students receive at the end of the term?', '9bad1966-d929-52a8-a11c-6984a99c2729'::uuid, NULL, NULL, E'Transcript', NULL, NULL),
  ('12a71a75-4180-554d-bfa4-c46410e43046'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '12a71a75-4180-554d-bfa4-c46410e43046'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which word can mean both color and fruit –- red, orange or purple?', '267e6d74-a5d8-5bcb-9737-da63f23dd78c'::uuid, NULL, NULL, E'Orange', NULL, NULL),
  ('12a7b908-bb5a-55a4-bd66-30a637ce1976'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '12a7b908-bb5a-55a4-bd66-30a637ce1976'::uuid, 1, NULL, TRUE, 0, NULL, E'Katakana', E'An eccentric mix of English, German and French has entered Japanese usage with grand abandon. A "kariya" woman is a career woman, and a "manshon" is an apartment. This increasing use of katakana, or unique Japanese versions of Western words, and the younger generation''s more casual use of the Japanese language have {{1}} Prime Minister Junichiro Koizumi to worry that these new words may not be understood by a wider audience. {{2}} , a government panel is proposing to publish a manual on how to speak proper Japanese. Foreign words became katakana Japanese {{3}} no existing Japanese words could quite capture a specific meaning or feeling. When the word "cool" traveled east, all of its English connotations did not make the journey. A kuru person in Japan is someone who is calm and never gets upset. {{4}} , someone who is kakkoii is hip, or in translation, "cool." {{5}} , a hotto person is one who is easily excitable, perhaps passionate, but not necessarily a popular person or personality of the moment.', NULL, NULL, NULL, E'1.prompted, 2.As a result, 3.because, 4.On the other hand, 5.Similarly', NULL, NULL),
  ('12ae1435-088f-5953-af0f-22497b77d915'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '12ae1435-088f-5953-af0f-22497b77d915'::uuid, 1, NULL, TRUE, 0, NULL, E'Arbitration', E'Arbitration is a method of conflict resolution which, with more or less formalized mechanisms, occurs in many political and legal spheres. There are two main {{1}} to arbitration. The first is that it is a voluntary process under which two parties in conflict agree between themselves to be {{2}} by the judgment of a third party which has no other authority over them; the judgment, however, is not legally binding. The second is that there is usually no clear body of {{3}} or set of rules that must apply; the arbitrator is free, {{4}} to any prior agreement with the conflicting parties, to decide on whatever basis of justice is deemed {{5}} .', NULL, NULL, NULL, E'1.characteristics, 2.bound, 3.laws, 4.subject, 5.suitable', NULL, NULL),
  ('12b02a43-b40b-54a3-9492-7f1a9b7e6c2d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '12b02a43-b40b-54a3-9492-7f1a9b7e6c2d'::uuid, 1, NULL, TRUE, 0, NULL, E'Atlantis', E'For centuries, Atlantis has been one of the western world''s favorite legends, a tantalizing blend of fantasy and mystery. Stories tell of a rich and glorious empire that was lost to the sea -- where some hope its ruins still lie, waiting to be discovered.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('12ba4b74-2927-5b32-8e85-89074e72401e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '12ba4b74-2927-5b32-8e85-89074e72401e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a shape of six sides?', '2de75ebf-166a-5f2e-85c5-4fa0b54d01aa'::uuid, NULL, NULL, E'Hexagon', NULL, NULL),
  ('12bb08aa-54e8-54f2-b1d3-c4343112fc12'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '12bb08aa-54e8-54f2-b1d3-c4343112fc12'::uuid, 1, NULL, TRUE, 0, NULL, E'Ancient Skeleton', E'A few years ago scientists {{1}} a three-foot skeleton of an early human species on an Indonesian island. They nicknamed the {{4}} a "hobbit." But the find left scientists with two major questions: Do these short, 18,000-year-old bones represent an entirely new human species? Or is it just someone with a growth disorder? Now the wrist bones may provide an answer. Researchers from the Smithsonian Institution {{5}} an article in the latest issue of Science. They showed that the hobbit''s wrists are {{6}} different from both early humans and from Neanderthals. In fact, the wrists are closer to those of African apes. Wrist bones take {{7}} in early pregnancy and don''t change much. They''re also particularly distinctive between species. Scientists believe this shows that an early species in the human line migrated from Africa to Asia. They evolved into a new species on the Indonesian island. If modern humans and Neanderthals have a common ancestor, then modern humans and hobbits have a common, well, grand-ancestor. Making us and hobbits kind of second cousins.', NULL, NULL, NULL, E'1.discovered, 2.creature, 3.published, 4.significantly, 5.shape', NULL, NULL),
  ('12bc3b5e-8311-5bb0-827c-be41e63d265f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '12bc3b5e-8311-5bb0-827c-be41e63d265f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e1ff2c53-d138-5ade-9115-006581468f55'::uuid, NULL, E'Enrollment for engineering courses has been low since this January.', NULL, NULL, NULL),
