  ('1341c0ab-4696-596d-9fe3-a1008e69390b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1341c0ab-4696-596d-9fe3-a1008e69390b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9f5a3fde-9c70-5662-be8c-60d0098cab93'::uuid, NULL, E'Some species of birds can sleep while they are flying.', NULL, NULL, NULL),
  ('13437bd9-6df1-5af9-ab89-bcd3c837321e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '13437bd9-6df1-5af9-ab89-bcd3c837321e'::uuid, 1, NULL, TRUE, 0, NULL, E'Phantom Rivers', E'For two summers in Pioneer Mountains, the roar of rushing white water filled the air. But where the loud sounds prevailed, only gentle streams flowed by. These phantom rivers were part of an experiment led by ecologist Dylan. He and colleagues were testing a hypothesis that the sounds of nature influence where animals lived and how they forage.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('13482165-b4a1-57c8-86a3-696a0ba0cb0b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '13482165-b4a1-57c8-86a3-696a0ba0cb0b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b3bbb6ad-bcbb-5cde-9690-b07acf54551b'::uuid, NULL, NULL, E'The history department is very active in research.', NULL, NULL),
  ('134cd790-7c4c-525c-a3d5-33b1c0a79b96'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '134cd790-7c4c-525c-a3d5-33b1c0a79b96'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9fd70a6f-2b8b-57a4-a99f-a8cf61b31547'::uuid, NULL, E'We went to the store to look for cosmic books for our children.', NULL, NULL, NULL),
  ('134ffe85-4211-5403-b7b7-823cdbe6534c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '134ffe85-4211-5403-b7b7-823cdbe6534c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the structure in bird''s throats that helps them produce sounds?', 'b8ebe367-4d6c-52ce-9d0c-2e7742846584'::uuid, NULL, NULL, E'Syrinx', NULL, NULL),
  ('1351d3a9-889f-547a-a740-e1737d68dd73'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '1351d3a9-889f-547a-a740-e1737d68dd73'::uuid, 1, NULL, TRUE, 0, NULL, E'Icebergs'' Sound', E'Twenty years ago, not so long before B-15 broke off from Antarctica, ''we didn''t even know that icebergs made noise,'' says Haru Matsumoto, an ocean engineer at NOAA who has studied these sounds. But in the past {{1}} years, scientists have started to learn to distinguish the eerie, haunting sounds of iceberg life — ice cracking, icebergs grinding {{2}} each other, an iceberg grounding on the seafloor — and measure the extent to {{3}} those sounds contribute to the noise of the ocean. While they''re just now learning to listen, the sounds of ice could help them understand the behavior and breakup of icebergs and ice shelves as the poles warm {{4}} .', NULL, NULL, NULL, E'1.few, 2.against, 3.which, 4.up', NULL, NULL),
  ('13543d19-6ad0-5a5e-b74c-39b092402b6f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '13543d19-6ad0-5a5e-b74c-39b092402b6f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which of the 5 senses are you using, if you detect the odor of gas in a laboratory or in your kitchen?', '63931255-19b4-5c63-bb23-13a8be98c740'::uuid, NULL, NULL, E'Smell / olfaction / olfactory', NULL, NULL),
  ('1360ee3b-8876-58c0-b5b6-aaf53bd0746d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '1360ee3b-8876-58c0-b5b6-aaf53bd0746d'::uuid, 1, NULL, TRUE, 0, NULL, E'Television', E'Television serves many useful functions. It helps people to relax. We can learn from television, and it can also be seen as a companion for the lonely. To what extent do you agree with this? Explain why with your own experience.', NULL, NULL, E'Television serves many useful functions, and I agree that it helps people to relax and can be seen as a companion for lonely individuals. In today''s fast-paced world, television provides a much-needed escape and entertainment for people of all ages.\nFirstly, television helps people to relax after a long and tiring day. After fulfilling their responsibilities and facing the challenges of life, individuals often seek ways to recharge. Television offers a wide range of programs, such as comedies, dramas, and reality shows, which provide a source of relaxation and amusement. It allows people to immerse themselves in captivating storylines, laugh at humorous situations, or simply enjoy the beauty of nature through documentaries. By engaging with television content, individuals can temporarily forget their worries and find peace in the entertainment it provides.\nAdditionally, television can be seen as a companion for lonely people. In today''s modern society, many individuals experience feelings of isolation and loneliness due to various reasons, such as living alone or being physically distant from loved ones. Television acts as a virtual companion, offering company and a sense of connection. It creates a shared experience as individuals watch their favorite shows or follow ongoing series. Characters on television become familiar faces, providing a sense of comfort and companionship.\nIn conclusion, television serves as a valuable tool for relaxation and companionship. It provides an escape from the stresses of life and offers entertainment that helps individuals relax. Moreover, it acts as a companion for lonely people, providing a sense of connection and shared experiences.', NULL, 200, 300),
  ('136faa0f-7760-5a20-b4a9-2a4b1b71def3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '136faa0f-7760-5a20-b4a9-2a4b1b71def3'::uuid, 1, NULL, TRUE, 0, NULL, E'Protein Songs', E'In recent years, scientists have created music based on the structure of proteins as a creative way to better popularize science to the general public, but the resulting songs haven''t always been pleasant to the ear. In a new study, researchers use the style of existing music genres to guide the structure of protein song to make it more musical.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('13707d7b-1c42-55f1-8a79-a8c5f333768b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '13707d7b-1c42-55f1-8a79-a8c5f333768b'::uuid, 1, NULL, TRUE, 0, NULL, E'Energy Bills', E'Across Europe, electricity and gas prices are skyrocketing – this is a massive burden for large sections of the population. In Greece, too, energy bills have risen sharply in recent months. Since the financial and economic crisis, many people are living on the edge of poverty.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('137748ef-44a8-5ddf-a9eb-24e6546f8990'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '137748ef-44a8-5ddf-a9eb-24e6546f8990'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd3a58359-6d71-578b-b04c-a625ad36019a'::uuid, NULL, E'This number went up very slowly over several centuries.', NULL, NULL, NULL),
  ('13796ec5-ac49-5e33-b4bf-beeb0115ae5b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '13796ec5-ac49-5e33-b4bf-beeb0115ae5b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4c13475d-8f9e-51e0-80b8-acdaba98823e'::uuid, NULL, NULL, E'We want everyone in our department to succeed together.', NULL, NULL),
  ('137beaa3-8311-52b6-b2c2-0163d5235091'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '137beaa3-8311-52b6-b2c2-0163d5235091'::uuid, 1, NULL, TRUE, 0, NULL, E'CRM', E'The CRM system is especially effective at helping to surface a marketing problem, and it can provide the internal data needed for an analysis, which, in turn, is used to solve the problem. CRM systems are designed to {{1}} data across the customer life cycle, starting with the initial contact point and progressing through each conversation and interaction that moves a {{2}} customer toward a purchasing decision. CRM systems also capture sales and spending data, and they enable analysts to {{3}} future spending patterns and lifetime value based on broader patterns in the customer data. These systems may also incorporate data about customer satisfaction and support, with accompanying {{4}} into what is driving satisfaction ratings and customers’ perceptions of the company. In addition to bringing together disparate customer data, CRM systems can recommend an {{5}} approach and provide research tools to complete the analysis. Many CRM systems have mechanisms for reporting results, orchestrating plans for taking action on the results, and even evaluating the effectiveness of those actions.', NULL, NULL, NULL, E'1.capture, 2.prospective, 3.project, 4.insights, 5.analytical', NULL, NULL),
  ('13828c43-bbbe-5487-bb2d-1706dbc84604'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '13828c43-bbbe-5487-bb2d-1706dbc84604'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ce85f77d-2d11-5daf-8ce7-5d14557b1e71'::uuid, NULL, E'We would like people to write a case study, describing an organization they know.', NULL, NULL, NULL),
  ('13835d5d-7d40-5f84-8f21-9593731d0b9d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '13835d5d-7d40-5f84-8f21-9593731d0b9d'::uuid, 1, NULL, TRUE, 0, NULL, E'Australia and New Zealand', E'Australia and New Zealand have many common links. Both countries were recently settled by Europeans, are predominantly English speaking and in that sense, share a common cultural {{1}} . Although in close proximity to one another, both countries are geographically isolated and have small populations by world {{2}} . They have similar histories and enjoy close relations on many fronts.\nIn terms of population {{3}} , Australia and New Zealand have much in common. Both countries have minority indigenous populations, and during the latter half of the 20th century have seen a steady stream of migrants from a variety of regions throughout the world. Both countries have {{4}} similar declines in fertility since the high levels recorded during the baby boom, and alongside this have enjoyed the benefits of continually improving life expectancy. One consequence of these trends is that both countries are faced with an ageing population, and the {{5}} challenge of providing appropriate care and support for this growing group within the community.', NULL, NULL, NULL, E'1.heritage, 2.standards, 3.characteristics, 4.experienced, 5.associated', NULL, NULL),
  ('13888a33-3dd3-55f4-ba61-9144583b26b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '13888a33-3dd3-55f4-ba61-9144583b26b2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5dc171fe-47c2-59a3-b74b-3b89d874c6b5'::uuid, NULL, NULL, E'The author of the lecture is well known to the public.', NULL, NULL),
  ('13895d19-ea56-5af4-aa80-28e7b160d0b5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '13895d19-ea56-5af4-aa80-28e7b160d0b5'::uuid, 1, NULL, TRUE, 0, NULL, E'Moon', E'The asteroid that slammed into the moon 3.8 billion years ago creating the Imbrium Basin may have had a diameter of at least 150 miles, according to a new estimate. The work helps explain puzzling geological features on the moon''s near side, and has implications for understanding the evolution of the early solar system.', NULL, NULL, NULL, NULL, NULL, NULL),
