  ('139e311f-3ebb-5fcc-9e28-3b4c62c40d57'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '139e311f-3ebb-5fcc-9e28-3b4c62c40d57'::uuid, 1, NULL, TRUE, 0, NULL, E'T Cells', E'Scientists are now trying to find ways to help treat patients by jumpstarting those lackluster T cells. Much of the research in this field, known as cancer immunotherapy, has focused on finding ways to stimulate those T cells directly. MIT researchers have now uncovered a possible new way to indirectly activate those T cells, by recruiting a population of helper immune cells called dendritic cells.', NULL, NULL, NULL, NULL, NULL, NULL),
