  ('13d544ce-2337-5eec-b680-7c9a86b87a2b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '13d544ce-2337-5eec-b680-7c9a86b87a2b'::uuid, 1, NULL, TRUE, 0, NULL, E'Dyke and Earthquake', E'This study marks the first time scientists have linked dike formation to large, damaging earthquakes, and Wauthier is looking back through history for more examples. She says researchers will never be able to predict exactly when an earthquake might strike after a dike intrusion. But at least now, researchers and rift zone residents know they''re not just in for bangs they may also be in for shudders.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('13d7d044-a7a4-5ca0-b5ec-6e97a1fc8b55'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '13d7d044-a7a4-5ca0-b5ec-6e97a1fc8b55'::uuid, 1, NULL, TRUE, 0, NULL, E'Dynamics', E'How quickly this occurs depends on the dynamics of fertility, mortality and overseas migration. While a moderate pace of demographic change allows for gradual adjustment of the economy and policies to the changing population demographics, rapid changes are more difficult to manage. As a result, governments and society as a whole may need to take actions to address these issues.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('13e08795-069a-521a-be1c-206bdb0a9945'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '13e08795-069a-521a-be1c-206bdb0a9945'::uuid, 1, NULL, TRUE, 0, NULL, E'Television against Communication', E'Television has compressed the time for communication between friends and families. What is your opinion?', NULL, NULL, NULL, NULL, 200, 300),
  ('13ecd939-7442-5906-b2fb-9e2b7c08e539'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '13ecd939-7442-5906-b2fb-9e2b7c08e539'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'efc3534c-4669-507e-8dae-fa05faf82779'::uuid, NULL, E'This part of the story is the story of my father.', NULL, NULL, NULL),
  ('13fc5748-04e7-5304-8304-7d7057cf0f7b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '13fc5748-04e7-5304-8304-7d7057cf0f7b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5ab76502-07d7-5eff-8306-d60ff0b255a6'::uuid, NULL, NULL, E'Academic dishonesty is regarded as a serious offense in universities.', NULL, NULL),
  ('1400d81e-b3c7-5a4d-93f2-353c9b7a1a23'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1400d81e-b3c7-5a4d-93f2-353c9b7a1a23'::uuid, 1, NULL, TRUE, 0, NULL, E'Timekeeping', E'Over the past five years, through studies of the simplest conceivable clocks, the researchers have discovered the fundamental limits of timekeeping. They’ve mapped out new relationships between accuracy, information, complexity, energy and entropy — the quantity whose incessant rise in the universe is closely associated with the arrow of time.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('140561b9-25cd-50c4-8f13-a11c753e4a18'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '140561b9-25cd-50c4-8f13-a11c753e4a18'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we say if we call brothers and sisters in a same way?', '1e3304e4-a4ee-5181-9ad2-a302e007073f'::uuid, NULL, NULL, E'Siblings', NULL, NULL),
  ('14058944-dc62-54e3-b55b-07051e172fb1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '14058944-dc62-54e3-b55b-07051e172fb1'::uuid, 1, NULL, TRUE, 0, NULL, E'School Liaison Police NSW', E'Armed police have been brought into NSW schools to reduce crime rates and educate students. The 40 School Liaison Police (SLP) officers have been allocated to public and private high schools across the state. Organisers say the officers, who began work last week, will build positive relationships between police and students. But parent groups warned of potential dangers of armed police working at schools in communities where police relations were already under strain. Among their duties, the SLPs will conduct crime prevention workshops, talking to students about issues including shoplifting, offensive behaviour, graffiti and drugs and alcohol. They can also advise school principals. One SLP, Constable Ben Purvis, began work in the inner Sydney region last week, including at Alexandria Park Community School''s senior campus. Previously stationed as a crime prevention officer at The Rocks, he now has 27 schools under his jurisdiction in areas including The Rocks, Redfern and Kings Cross. Constable Purvis said the full time position would see him working on the broader issues of crime prevention. "I am not a security guard," he said. "I am not there to patrol the school. We want to improve relationships between police and schoolchildren, to have positive interaction. We are coming to the school and giving them knowledge to improve their own safety." Parents'' groups responded to the program positively, but said it may spark a range of community reactions. "It is a good thing and an innovative idea and there could be some positive benefits," Council of Catholic School Parents executive officer.', NULL, NULL, E'Armed police have been brought into NSW schools to reduce crime rates and educate students, but parent groups warned of potential dangers of armed police working at schools in communities where police relations were already under strain; one policeman said that he could work on the broader issues of crime prevention, improve relationships between police and schoolchildren and have positive interaction.', NULL, 5, 75),
  ('140eb47b-daf2-5c30-ab0f-6f5e719f1a40'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '140eb47b-daf2-5c30-ab0f-6f5e719f1a40'::uuid, 1, NULL, TRUE, 0, NULL, E'America and India IT', E'Consider the current situation: like their counterparts in the United States, engineers and technicians in India have the capacity to provide both computer programming and innovative new technologies. Indian programmers and high-tech engineers earn one-quarter of what their counterparts earn in the United States; Consequently, India is able to do both jobs at a lower dollar cost than the United States: India has absolute advantage in both. In other words, it can produce a unit of programming for fewer dollars than the United States, and it can also produce a unit of technology innovation for fewer dollars. Does that mean that the United States will lose not only programming jobs but innovative technology job, too? Does that mean that our standard of living will fall if the United States and India engage in the international trade? David Ricardo would have answered no to both questions - as we do today. While India may have an absolute advantage in both activities, that fact is irrelevant in determining what India or the United States will produce. India has a comparative advantage in doing programming in part because of such activity requires little physical capital. The flip side is that the United States has a comparative advantage in technology innovation partly because it is relatively easy to obtain capital in this country to undertake such long-run projects. The result is that Indian programmers will do more and more of what U.S. programmers have been doing in the past. In contrast, American firms will shift to more and more innovation.', NULL, NULL, E'While India might has absolute advantage in providing both computer programming and innovative new technologies because of the low cost, the United States has a comparative advantage in technology innovation because of easier capital obtaining, which suggests that Indian programmers will do more and more of what U.S. programmers have been doing in the past and American firms will shift to more and more innovation.', NULL, 5, 75),
  ('14105719-2275-57ca-8713-75312d7b60e5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '14105719-2275-57ca-8713-75312d7b60e5'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the form of substance between gas and solid?', '5f5360e0-5c01-52a0-907e-2c5ba4a159c9'::uuid, NULL, NULL, E'Liquid', NULL, NULL),
