  ('141307d6-2148-54d6-b009-75475a757255'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '141307d6-2148-54d6-b009-75475a757255'::uuid, 1, NULL, TRUE, 0, NULL, E'Camel Sculptures', E'A series of camel sculptures carved into rock faces in Saudi Arabia are likely to be the oldest large-scale animal reliefs in the world, a study says. When the carvings were first discovered in 2018, researchers estimated they were created about 2,000 years ago. This was based on their similarity to reliefs at Jordan''s famous ancient city of Petra.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('1414c3a5-6d47-51e0-a1bc-0bcd58704e5a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1414c3a5-6d47-51e0-a1bc-0bcd58704e5a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd2aef833-4eda-5212-be2c-6baa9f24082d'::uuid, NULL, NULL, E'These factors are also linked to numerous deaths of sea creatures.', NULL, NULL),
  ('141b1b50-91a0-544d-9cf6-b6672c7b615a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '141b1b50-91a0-544d-9cf6-b6672c7b615a'::uuid, 1, NULL, TRUE, 0, NULL, E'Well-being', E'Life in the UK 2012 provides a unique overview of well-being in the UK today. The report is the first snapshot of {{1}} in the UK to be delivered by the Measuring National Well-being program and will be {{2}} and published annually. Well-being is discussed in terms of the economy, people and the environment. Information such as the unemployment rate or {{3}} of crimes against the person is presented alongside {{4}} on people''s thoughts and feelings, for example, satisfaction with our jobs or {{5}} time and fear of crime. Together, a richer picture on ''how society is doing'' is provided.', NULL, NULL, NULL, E'1.life, 2.updated, 3.number, 4.data, 5.leisure', NULL, NULL),
  ('142ed3d6-351b-5611-a089-c08c5837591c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '142ed3d6-351b-5611-a089-c08c5837591c'::uuid, 1, NULL, TRUE, 0, NULL, E'Why Students Forget', E'Teachers have long known that rote memorization can lead to a {{1}} grasp of material that is quickly forgotten. But new research in the field of neuroscience is starting to {{2}} light on the ways that brains are wired to forget — highlighting the importance of strategies to retain knowledge and make learning stick. In a recent article published in the journal Neuron, neurobiologists Blake Richards and Paul Frankland challenge the {{3}} view of memory, which holds that forgetting is a process of loss — the gradual washing away of critical information {{4}} our best efforts to retain it. According to Richards and Frankland, the goal of memory is not just to store information accurately but to ‘optimize decision-making’ in chaotic, quickly changing environments. In this model of cognition, forgetting is an evolutionary strategy, a {{5}} process that runs in the background of memory, evaluating and discarding information that doesn’t promote the survival of the species.', NULL, NULL, NULL, E'1.superficial, 2.shed, 3.predominant, 4.despite, 5.purposeful', NULL, NULL),
  ('142fcbba-3030-5e04-8ec4-5026c134d586'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '142fcbba-3030-5e04-8ec4-5026c134d586'::uuid, 1, NULL, TRUE, 0, NULL, E'Habeas Corpus Act', NULL, NULL, NULL, NULL, E'3, 1, 4, 2', NULL, NULL),
