  ('1475d015-f6ba-56bf-b0e5-b5cb0328c105'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1475d015-f6ba-56bf-b0e5-b5cb0328c105'::uuid, 1, NULL, TRUE, 0, NULL, E'Modifications', E'Some people object that in order for the eye to modify and still remain a useful instrument to its owner, many changes would have had to take place simultaneously. However, it is not necessary to suppose this if the modifications were extremely slight and gradual.', NULL, NULL, NULL, NULL, NULL, NULL),
