  ('1482e22b-b7c2-5e2f-b8cd-2fedf75477eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1482e22b-b7c2-5e2f-b8cd-2fedf75477eb'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a mass of snow, ice and rock that falls down the side of a mountain?', '2f95732f-d7a3-55af-aa78-4bf037d65ca6'::uuid, NULL, NULL, E'Avalanche / snowslide', NULL, NULL),
  ('1485f814-fe1a-5bbf-94fd-d16dd1aa56b7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1485f814-fe1a-5bbf-94fd-d16dd1aa56b7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '91d9740b-6be4-5faa-bbf7-3f36a968422a'::uuid, NULL, NULL, E'The university''s campaign to hire more teachers has been a success.', NULL, NULL),
  ('1486fba3-1efc-507d-864a-7ec48074e4a1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1486fba3-1efc-507d-864a-7ec48074e4a1'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '58964d5c-14c7-525b-9d02-d883e1cdb8a6'::uuid, NULL, NULL, E'This paper provides a synthesis of key issues in sociology.', NULL, NULL),
  ('1491d857-25c2-57af-83e4-d2b9899659d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '1491d857-25c2-57af-83e4-d2b9899659d8'::uuid, 1, NULL, TRUE, 0, NULL, E'Honeybees', E'Honeybees, essential pollinators for over a third of our food crops, are vanishing at an alarming rate. Scientists are vigorously investigating the cause of this "colony collapse disorder," with {{1}} ranging from pesticides to habitat loss. While the comprehensive picture remains {{2}} , research has illuminated some contributing factors. One culprit appears to be a class of insecticides called neonicotinoids, {{3}} to harm bee nervous systems. Another factor is the Varroa mite, a parasite that weakens bees and {{4}} viruses. The urgency is undeniable, as a world without bees would have devastating consequences for our food security and ecosystem. Researchers, beekeepers, and policymakers are working in {{5}} to find solutions, hoping to save these vital creatures before it''s too late. Their collaborative efforts offer a glimmer of hope in the face of this pressing ecological challenge.', NULL, NULL, NULL, E'1.suspects, 2.elusive, 3.known, 4.transmits, 5.unison', NULL, NULL),
  ('14928ccd-b4f8-5300-848c-bb53194007d1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '14928ccd-b4f8-5300-848c-bb53194007d1'::uuid, 1, NULL, TRUE, 0, NULL, E'Tele-banking', E'The transition from the ''brick and mortar'' structure to ''click and order'' model started with the emergence of Information Technology and its use in the financial sector. The use of technology in banking has resulted in availability of multiple delivery channels like ATMs, tele-banking, internet banking, and mobile banking.', NULL, NULL, NULL, NULL, NULL, NULL),
