  ('149843d3-6bfb-5a98-bab3-5dfe61e80f35'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '149843d3-6bfb-5a98-bab3-5dfe61e80f35'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b7cfc2a2-4fa7-5d8b-b699-c79ffd0ae1d7'::uuid, NULL, E'Collaborative teamwork is essential for success on this important project.', NULL, NULL, NULL),
