  ('14a0580d-970f-544e-b168-4c8d423ceb21'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '14a0580d-970f-544e-b168-4c8d423ceb21'::uuid, 1, NULL, TRUE, 0, NULL, E'Dialectical Thought', E'Thinking in early adulthood may become more {{1}} and balanced. Adolescents tend to think in {{2}} or absolute terms: ideas are true or false, good or bad, right or wrong and there is no middle ground. However, with education and experience, the young adult comes to recognize that there is some right and some wrong in each {{3}} .', NULL, NULL, NULL, E'1.flexible, 2.dichotomies, 3.position', NULL, NULL),
  ('14b1d4f8-00cc-586b-b564-86c3f46c715e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '14b1d4f8-00cc-586b-b564-86c3f46c715e'::uuid, 1, NULL, TRUE, 0, NULL, E'Australian Workplaces', E'Australian workplaces are increasingly suffering from depression, anxiety and stress, according to a large study of mental health in corporate Australia. Mental illness appears to have increased by a third in the last decade. Depression is now the primary mental health disorder.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('14b64dd9-4118-5e52-b960-4db852d19fd4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '14b64dd9-4118-5e52-b960-4db852d19fd4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c9d4d71c-ee69-549c-862b-5e5a648464a6'::uuid, NULL, NULL, E'There is a great deal of debate on this topic.', NULL, NULL),
  ('14ba2676-0da2-5a66-969a-8c959f2f4966'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '14ba2676-0da2-5a66-969a-8c959f2f4966'::uuid, 1, NULL, TRUE, 0, NULL, E'Material and Non-material', E'For the purposes of argument, culture is divided into material and non-material, and the speaker''s aim is to show how they both affect each other. Material developments in tools and technology can affect non-material culture, our customs and beliefs, and the other way around. Genetics is used as an example as it has changed the way we think about life, but also our beliefs have affected its rate of development.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('14bd9064-18b1-535f-86bb-eec035fe2c74'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '14bd9064-18b1-535f-86bb-eec035fe2c74'::uuid, 1, NULL, TRUE, 0, NULL, E'Chimpanzee Posture', E'Chimpanzee posture, gestures, and facial expressions communicate many messages and {{1}} between various individuals. When {{2}} a dominant individual following an absence or in response to an aggressive gesture, nervous {{3}} may approach with submissive signals —— crouching, presenting the hindquarters, holding a hand out —— accompanied by pant —— grunts or squeaks. In response, the dominant individual may make gestures of {{4}} , such as touching, kissing, or embracing.', NULL, NULL, NULL, E'1.emotions, 2.greeting, 3.subordinates, 4.reassurance', NULL, NULL),
  ('14c63b86-8610-55c3-b3bd-dd90cac319fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '14c63b86-8610-55c3-b3bd-dd90cac319fb'::uuid, 1, NULL, TRUE, 0, NULL, E'Guiding Principles', NULL, '2093b71b-f14c-55c2-9683-eb619e884107'::uuid, NULL, E'From reading philosophy, I came up with three principles as the guiding principles for a just city, of the principles of equity, democracy and diversity. Of these were derived from the works of a number of philosophers, most preeminently I supposed on Ross. My choice of word equity rather than equality is in fact based on Ross''s argument that a policy ought to distribute benefits to people where the worst off become better off. So the worst off don''t have to become equal to everybody else but no policy should in fact make those who are most disadvantaged more disadvantaged. And it means that we have to talk about the policy at the time it''s being enacted. To say, while we have to make our city more competitive because sometime and by and by, the benefits will trickle down to those people who were worst off doesn''t justify making them worst off as that time. We have a lot of examples on the world of people whose homes were destroyed in the name of the greater good and say eventually they will benefit. But equity means that you do not in fact take advantage of those people who are weakest.', NULL, NULL, NULL),
  ('14c914d3-38eb-575b-bfcf-64e9f38607a7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '14c914d3-38eb-575b-bfcf-64e9f38607a7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7d828ecb-e6c3-5d56-8eda-56d087ed4d97'::uuid, NULL, NULL, E'The development of this industry will take several years.', NULL, NULL),
