  ('1564872d-fdd8-575d-9d79-01bc7bbcaf7c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '1564872d-fdd8-575d-9d79-01bc7bbcaf7c'::uuid, 1, NULL, TRUE, 0, NULL, E'Xenophobia', E'Xenophobia has accelerated rapidly in the western countries. According to you what solutions can be proposed by government and individuals?', NULL, NULL, NULL, NULL, 200, 300),
  ('15669e3b-a581-5be9-a4a5-fc0e2021fd58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '15669e3b-a581-5be9-a4a5-fc0e2021fd58'::uuid, 1, NULL, TRUE, 0, NULL, E'Luminescence Dating', E'At this great age, putting a date on finds is very challenging and we used luminescence dating to do this. These new dating methods have far reaching implications -- allowing us to date much further back in time, to piece together sites that give us a glimpse into human evolution.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('1569bf65-c880-503d-9264-4d671993edc5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1569bf65-c880-503d-9264-4d671993edc5'::uuid, 1, NULL, TRUE, 0, NULL, E'Charlie Parker', E'Charlie Parker noticed that the solos were only improvised through the melodies, but that he could also improvise them through the chords, thus creating new variations over the structure of the songs, and also playing more notes and faster.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('1569d585-3d63-551d-80ca-4d535774738e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1569d585-3d63-551d-80ca-4d535774738e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0e77b9db-4180-54f0-b55d-cc0a84da4be7'::uuid, NULL, E'The initial results are intriguing, but statistically speaking, they are insignificant.', NULL, NULL, NULL),
  ('156becb9-5cd2-53f8-85cf-37b5d6f228b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '156becb9-5cd2-53f8-85cf-37b5d6f228b2'::uuid, 1, NULL, TRUE, 0, NULL, E'Corn People', E'Descendants of the Maya living in Mexico still sometimes refer to themselves as the corn people. The phrase is not intended as {{1}} . Rather, it''s meant to {{2}} their abiding dependence on this miraculous grass, the {{3}} of their diet for almost nine thousand years. Forty percent of the calories a Mexican eats in a day comes directly from corn, most of it in the form of tortillas. So when a Mexican says I am maize or corn walking, it is simply a statement of fact: The very substance of the Mexicans body is to a considerable extent a {{4}} of this plant.', NULL, NULL, NULL, E'1.metaphor, 2.acknowledge, 3.staple, 4.manifestation', NULL, NULL),
  ('1571ae3d-ef7f-5e6f-9c2e-1e5997d14749'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1571ae3d-ef7f-5e6f-9c2e-1e5997d14749'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What term is issued for animals that give birth to its young?', '0f32d404-3d61-521d-ae7c-e3f92463a340'::uuid, NULL, NULL, E'Mammals / mammal', NULL, NULL),
  ('15753063-f9f8-5a74-bb50-61b1676c4686'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '15753063-f9f8-5a74-bb50-61b1676c4686'::uuid, 1, NULL, TRUE, 0, NULL, E'Significant Moment', NULL, NULL, NULL, NULL, E'2, 1, 3, 4', NULL, NULL),
  ('157b2c5c-6d79-5e1a-badb-7dc909d698d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '157b2c5c-6d79-5e1a-badb-7dc909d698d7'::uuid, 1, NULL, TRUE, 0, NULL, E'Octopuses', NULL, 'f01d23ee-04a4-5569-b4e4-82e1939a6769'::uuid, NULL, E'Octopuses are creatures renowned for their remarkable intelligence and adaptability. These mysterious inhabitants of the deep offer insights into the complexity and wonders of marine life. Octopuses are known for their extraordinary cognitive abilities. They can solve puzzles, navigate mazes, and even use tools, demonstrating a level of intelligence that challenges our understanding of animal behavior. For instance, their ability to escape from secure tanks in aquariums has baffled scientists and underscored their problem-solving skills. Furthermore, their unique biology is equally captivating. Octopuses can change color and texture to blend into their surroundings, an incredible adaptation for both hunting and evading predators. This camouflage ability, combined with their intelligence, makes them one of the most intriguing species in the ocean. The study of octopuses not only fascinates us but also deepens our appreciation for the diversity and complexity of life in our oceans. Their intelligence and adaptability continue to inspire and intrigue the scientific community and beyond.', NULL, NULL, NULL),
  ('157db941-ec1d-5e0c-8582-d3743680c26f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '157db941-ec1d-5e0c-8582-d3743680c26f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person who thinks only for himself or herself?', '27a953b1-4bd1-58a8-a203-dcb58ab354d3'::uuid, NULL, NULL, E'Egoistic / selfish', NULL, NULL),
  ('157f059e-0876-5edf-85a7-318c72bd7c81'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '157f059e-0876-5edf-85a7-318c72bd7c81'::uuid, 1, NULL, TRUE, 0, NULL, E'Reason of Work', E'People work because they need money for a living. What are some other reasons why people work? Discuss one or more of these reasons.', NULL, NULL, E'While the need for money is undoubtedly a significant motivation for people to work, it is not the sole driving force behind employment. There are numerous other motivations that compel individuals to engage in work and contribute to society. This essay will explore some of these motivations and discuss their importance in people''s work lives.\nOne key motivation that drives people to work is personal fulfillment and satisfaction. Many individuals find a sense of purpose and accomplishment in their work, deriving joy from a job well done. Whether it is creating a piece of art, solving complex problems, or helping others, the intrinsic rewards of personal fulfillment can be a powerful driving force in the workplace. When individuals are able to find meaning and satisfaction in their work, it enhances their overall well-being and contributes to a fulfilling life.\nAnother motivation for work is the desire for social interaction and a sense of community. The workplace often serves as a platform for individuals to connect with others, build relationships, and foster a sense of belonging. Collaborative projects, team efforts, and shared goals create opportunities for social interaction and camaraderie. The sense of community in the workplace not only provides emotional support but also enhances productivity and teamwork, making work more enjoyable and meaningful.\nIn conclusion, while the need for money is an important motivation for people to work, there are many other factors that drive individuals in their professional lives. By understanding the diverse motivations that drive people to work, we can create environments that support personal growth, foster positive relationships, and promote overall well-being in the workforce.', NULL, 200, 300),
  ('1586b438-040f-503b-9413-fa368be8d9d9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1586b438-040f-503b-9413-fa368be8d9d9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '33964cb2-6068-5bb2-9307-2a52b7f9d2cd'::uuid, NULL, NULL, E'As student union members, you can influence and change our university.', NULL, NULL),
  ('15961059-2f61-5826-b1f4-cf1473143edc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '15961059-2f61-5826-b1f4-cf1473143edc'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2a733ef8-c615-5180-b8d8-d1b045d1b44d'::uuid, NULL, E'When we are stressed, our skin releases a natural chemical, a hormone, that repels mosquitoes.', NULL, NULL, NULL),
  ('15976490-b82d-5e7c-98e8-71d9620c922d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '15976490-b82d-5e7c-98e8-71d9620c922d'::uuid, 1, NULL, TRUE, 0, NULL, E'Walls', NULL, '8cee8c7c-7567-56fa-9817-3e9921bfb86c'::uuid, NULL, E'Walls and fences are often built with the intention of security, security from another group of people,from crime, from illegal trades. But walls and fences only provide us with a feeling of security, which is different from real security. Even though they might make us feel safe, the structures themselves can’t protect us. Instead, they do something else: they separate. They create an us and a them. They establish an enemy. Walls make us build a second wall in our head, a mental wall. And those mental walls slowly make us lose sight of all the things we have in common with the people on the other side. The other way around, mental walls can grow so strong that they encourage us to build, keep or strengthen physical walls. Physical and mental walls are closely interlinked, and one almost always comes with the other. It’s a constant cycle: physical walls empower mental walls, and mental walls empower physical walls until at one point one part falls away, and the cycle is disrupted.', NULL, NULL, NULL),
  ('159cd1d5-9628-57df-bac5-e427a9e87b99'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '159cd1d5-9628-57df-bac5-e427a9e87b99'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the people we work together with?', '53c1e29e-7661-5248-af2e-78083086cadd'::uuid, NULL, NULL, E'Co-worker / colleague', NULL, NULL),
  ('15a198b7-97f8-55e4-98c4-ff55f651421e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '15a198b7-97f8-55e4-98c4-ff55f651421e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call comments in a movie given by a person unseen on the screen?', '6cbef246-e076-5305-b5b8-1230670b22e6'::uuid, NULL, NULL, E'Voice-over', NULL, NULL),
  ('15aa126f-844e-5d42-a75d-dceba40f2d95'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '15aa126f-844e-5d42-a75d-dceba40f2d95'::uuid, 1, NULL, TRUE, 0, NULL, E'Definition of Country', E'What is a country, and how is a country defined? When people ask how many countries there are in the world, they expect a simple answer. After all, we''ve explored the {{1}} planet, we have international travel, satellite navigation and plenty of global organizations like the United Nations, {{2}} we should really know how many countries there are! However, the answer to the question varies according to whom you ask. {{3}} people say there are 192 countries, but others point out that there could be more like 260 of them. So why isn''t there a straightforward answer? The problem arises because there isn''t a universally agreed definition of ''country'' and because, for political reasons, some countries find it convenient to recognize or not recognize {{4}} countries.', NULL, NULL, NULL, E'1.whole, 2.so, 3.Most, 4.other', NULL, NULL),
  ('15b2b147-4ec3-56fc-93b9-61ecef5d8973'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '15b2b147-4ec3-56fc-93b9-61ecef5d8973'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'dadd305c-87e0-5abe-8d12-6b00a63aee7a'::uuid, NULL, NULL, E'The most important process of farming is weeding.', NULL, NULL),
  ('15b40508-3974-53ea-9683-d4f014c6ddba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '15b40508-3974-53ea-9683-d4f014c6ddba'::uuid, 1, NULL, TRUE, 0, NULL, E'Sense of Taste', E'Pavlov proposed over a century ago that the sight, smell and taste of food are important for regulating digestion. More recent studies in the 1970s and 1980s have also suggested that the taste of food may restrain how fast we eat, but it''s been impossible to study the relevant brain activity during eating because the brain cells that control this process are located deep in the brainstem.', NULL, NULL, NULL, NULL, NULL, NULL),
