  ('16500a9d-011c-5df8-a43b-7d43d81c762a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '16500a9d-011c-5df8-a43b-7d43d81c762a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '89be8ae5-4598-5109-a336-469bd3eddad3'::uuid, NULL, NULL, E'A group meeting will be held tomorrow in the library conference room.', NULL, NULL),
  ('1651b16d-6c80-5ec9-841d-bd969726cf0e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1651b16d-6c80-5ec9-841d-bd969726cf0e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7c9c222f-d299-54a7-aded-f6babd5ccbc7'::uuid, NULL, NULL, E'The article illustrates a very large number of very interesting experiments.', NULL, NULL),
  ('1652ea67-29eb-554b-9b1b-4f11aa701224'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1652ea67-29eb-554b-9b1b-4f11aa701224'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '32fa4250-d2ff-5fe0-a369-c34bd31a1042'::uuid, NULL, E'I will be in my office every day from ten to twelve.', NULL, NULL, NULL),
  ('1653b275-4812-51da-aa12-e580e4ae2973'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1653b275-4812-51da-aa12-e580e4ae2973'::uuid, 1, NULL, TRUE, 0, NULL, E'Privacy', NULL, '0e9e4c19-0de7-5c1c-a0d0-213b2f4beea2'::uuid, NULL, E'So that creates tensions and that''s what I want to talk about. Because I think it’s important that we are, as a society, able to have an informed debate about how much privacy is enough but not too much, how much security is enough but not too much. Privacy, as a human right, that''s simply quoting the Universal Decoration. In the physical world, we''ve got all kinds of protections. There is evidence that we care about our privacy. We''ve got locks, we''ve got obscured glass, welve got lots, we wear clothes, we put up shutters. And technology continues to erode the privacy that exists in the real world, in the three spatial dimensions. Security cameras, automatic number, plate recognition take away anonymity. Long lenses, paparazzi, take away distance and the privacy that used to create. And body scanners are increasingly being used to see through for example. This process isn’t going to slow down and the new quantum technologies are actually being able to do gravitational sensing. And that''s advancing at a remarkable rate. And you can''t shield gravity. So some of the new quantum technologies are able already to see through walls. And there are technologies also for seeing round corners now using scattered light from lasers. Technology continues to erode privacy.', NULL, NULL, NULL),
  ('1654bf8d-8c20-59a2-8b9b-3a7e1a3ad6b3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1654bf8d-8c20-59a2-8b9b-3a7e1a3ad6b3'::uuid, 1, NULL, TRUE, 0, NULL, E'Fresh Water', E'In Abu Dhabi, where fresh water sources are very limited, sustainable water management is a high priority. The region receives on average just 120 millimeters of rainfall every year but the country is seeing demand for water increase by almost 40% annually. In this situation, it is clear that Abu Dhabi needs to boost the efficiency of water use by increasing water recycling.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('165b1a41-c87d-596f-9fd5-1066a412b26c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '165b1a41-c87d-596f-9fd5-1066a412b26c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9b8c36cd-e9df-5c29-8d03-4ef03be108e0'::uuid, NULL, NULL, E'Accountant students should have a good understanding of profit and loss statement.', NULL, NULL),
  ('165c8eb1-4de6-5fd2-9561-c2285dae8614'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '165c8eb1-4de6-5fd2-9561-c2285dae8614'::uuid, 1, NULL, TRUE, 0, NULL, E'Organic Culture', E'A charge often leveled against organic agriculture is that it is more philosophy than science. There''s some truth to this indictment, if that is what it is, though why organic farmers should feel {{1}} about it is itself a mystery, a relic, perhaps, of our fetishism of science as the only {{2}} tool with which to approach nature. The philosophy of {{3}} natural processes precedes the science of understanding them.', NULL, NULL, NULL, E'1.defensive, 2.credible, 3.mimicking', NULL, NULL),
  ('166519d6-8734-55fd-bb0e-0edcc98ed700'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '166519d6-8734-55fd-bb0e-0edcc98ed700'::uuid, 1, NULL, TRUE, 0, NULL, E'AI and Employment', E'What is your opinion on the role of artificial intelligence in shaping the future of employment? Do you see it as a threat or an opportunity for the workforce?', NULL, NULL, NULL, NULL, 200, 300),
  ('166db5fe-9106-5c8a-8bff-070f4e87c727'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '166db5fe-9106-5c8a-8bff-070f4e87c727'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '94c5bd3b-dcfb-56bf-9bf8-2cb14d18d412'::uuid, NULL, E'Friendship is a source of pleasure and a component of good health.', NULL, NULL, NULL),
  ('16741a61-d276-5117-8087-a7195b8cf498'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '16741a61-d276-5117-8087-a7195b8cf498'::uuid, 1, NULL, TRUE, 0, NULL, E'MBA Programs', E'Deciding to go to business school is perhaps the simplest part of what can be a complicated process. With nearly 600 accredited MBA programs on {{1}} around the world, the choice of where to study can be overwhelming. Here we explain how to {{2}} the right school and course for you and unravel the application and funding process. "Probably the {{3}} of people applying to business school are at a point in their careers where they know they {{4}} to shake things up, but they don''t know exactly what they would like to do with their professional lives," says Stacy Blackman, an MBA admissions consultant based in Los Angeles. "If that''s the case with you, look at other {{5}} : culture, teaching method, location, and then pick a place that’s a good fit for you with a strong general management program. Super-defined career goals don’t have to be a part of this process."', NULL, NULL, NULL, E'1.offer, 2.choose, 3.majority, 4.want, 5.criteria', NULL, NULL),
