  ('168e2763-18f6-5120-9f98-8bd119776bc2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '168e2763-18f6-5120-9f98-8bd119776bc2'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the hand-held electric device that blows hot air to your hair?', 'd5c1e730-3c29-5246-ac62-bc59465e9350'::uuid, NULL, NULL, E'Hairdryer / hair dryer', NULL, NULL),
  ('1691177e-d43f-58cb-ac44-3c1915427418'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1691177e-d43f-58cb-ac44-3c1915427418'::uuid, 1, NULL, TRUE, 0, NULL, E'Environmental Degradation', E'People are waking up to the problem of environmental degradation. Efforts are being made all over the world to reduce carbon footprint and promote sustainable development. Environmental conservation is no longer only about mandating factories to adopt greener practices or ensuring that vehicles on the road are checked regularly for their pollution levels. It is wider than that and encompasses all industries.', NULL, NULL, NULL, NULL, NULL, NULL),
