  ('16c6b2c9-74b0-5762-a006-0469ee235c6b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '16c6b2c9-74b0-5762-a006-0469ee235c6b'::uuid, 1, NULL, TRUE, 0, NULL, E'Mosquito Diseases', E'To prevent mosquito-transmitted diseases, approaches based on genetic control of insect populations are being developed. However, many of these strategies are based on highly invasive, self-propagating transgenes that can rapidly spread the trait into other populations of mosquitoes.', NULL, NULL, NULL, NULL, NULL, NULL),
