  ('16e8edf8-eb45-53af-b215-c9bfbbaf1555'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '16e8edf8-eb45-53af-b215-c9bfbbaf1555'::uuid, 1, NULL, TRUE, 0, NULL, E'Restaurant Order', E'You were eating in a restaurant and you ordered a hamburger, but you were served fish and chips. What would you say to the waiter?', '127082dd-d049-57b6-8bc3-97cc138d64b4'::uuid, NULL, NULL, NULL, NULL, NULL),
  ('16ef4d7d-3bcd-53aa-987e-e513fc246757'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '16ef4d7d-3bcd-53aa-987e-e513fc246757'::uuid, 1, NULL, TRUE, 0, NULL, E'Statistics', E'Statistics are indicators of change and allow meaningful comparisons to be made. While it may be the issues rather than the statistics as such that grab people''s attention, it should be recognized that it is the statistics that informed the issues. Statistical literacy, then, is the ability to accurately understand, interpret and evaluate the data that inform these issues.', NULL, NULL, NULL, NULL, NULL, NULL),
