  ('16f82f35-67a5-5d07-bffa-636b87706dfe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '16f82f35-67a5-5d07-bffa-636b87706dfe'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8eede742-e8d5-55cb-96e5-49f84c1b5fe4'::uuid, NULL, NULL, E'Changing your interest is a natural part of the learning process.', NULL, NULL),
  ('16f8d0e5-b07e-5a45-bd1d-e17a20f3240c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '16f8d0e5-b07e-5a45-bd1d-e17a20f3240c'::uuid, 1, NULL, TRUE, 0, NULL, E'Rotation', E'The Earth, our celestial home, is in perpetual motion, gracefully rotating through space. This continuous rotation gives us the cycle of day and night, shapes our seasons, and influences our climate. Over geological time spans, it''s gradually slowing down, which has led to speculation about what would happen if the Earth stopped rotating altogether.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('16fad7e7-4649-592c-a228-9430f4f755b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '16fad7e7-4649-592c-a228-9430f4f755b8'::uuid, 1, NULL, TRUE, 0, NULL, E'Father', E'Ever since I remembered, father woke up at five thirty every morning, made us all breakfast and read newspaper. After that, he would go to work. He worked as a writer. It was a long time before I realized he did this for a living.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('16fe47d6-b223-55dc-b43a-d6e15b85a143'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '16fe47d6-b223-55dc-b43a-d6e15b85a143'::uuid, 1, NULL, TRUE, 0, NULL, E'Advertising Aim', E'The main {{1}} of advertising is to sell {{2}} by getting them known and, here, brash, sensational ideas may often serve the {{3}} . But by no means is all advertising aimed at promoting a new product or even a product at all. One of the most famous posters of the 20th century {{4}} Lord Kitchener early in the 1914-18 war pointing a finger, perhaps accusingly, at the entire male military-age population of Britain.', NULL, NULL, NULL, E'1.aim, 2.products, 3.purpose, 4.shows', NULL, NULL),
  ('170021d9-46f9-50b6-9c54-994f71df8800'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '170021d9-46f9-50b6-9c54-994f71df8800'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b7d0a347-87dd-5efa-add0-680853105027'::uuid, NULL, E'Newspapers are supported primarily by the sale of advertising space.', NULL, NULL, NULL),
