  ('1706ecd3-43f4-5e4b-8b97-d8ce317279df'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '1706ecd3-43f4-5e4b-8b97-d8ce317279df'::uuid, 1, NULL, TRUE, 0, NULL, E'Techniques', E'In the process of studying these techniques, I learned something {{1}} : that there''s far more potential in our {{2}} than we often give them credit for. I''m not just talking about the fact that it''s possible to memorize lots of {{3}} using memory techniques. I''m talking about a lesson that is more {{4}} , and in a way much bigger: that it''s possible, with training and hard work, to teach oneself to do something that might seem really {{5}} .', NULL, NULL, NULL, E'1.remarkable, 2.minds, 3.information, 4.general, 5.difficult', NULL, NULL),
  ('17074820-aa50-5703-852f-0a85a985b4e4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '17074820-aa50-5703-852f-0a85a985b4e4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '845ae7f7-524f-5642-a670-246c8811b735'::uuid, NULL, NULL, E'The students are to submit their research on time.', NULL, NULL),
