  ('17705fb0-8ac5-507d-9620-870d6eedc2fa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '17705fb0-8ac5-507d-9620-870d6eedc2fa'::uuid, 1, NULL, TRUE, 0, NULL, E'Essential Carbon', E'The carbon is essential to life on earth, but scientists still struggle to grasp its complexities. Most research to date has focused on major sources of the greenhouse gas carbon dioxide, and the use of fossil fuels. A new study has come to the counter-intuitive conclusion that plants might accumulate more carbon in the presence of predators and herbivores.', NULL, NULL, NULL, NULL, NULL, NULL),
