  ('17c2d0ac-6b22-5333-a0d4-fe72795f9a66'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '17c2d0ac-6b22-5333-a0d4-fe72795f9a66'::uuid, 1, NULL, TRUE, 0, NULL, E'Stress', E'Stress is encountered in four different stages. In the first stage, stress usually {{1}} alarm. Next, in the second or appraisal stage, the child {{2}} to find meaning from the event. Stage three {{3}} of children seeking out coping strategies. Lastly, in stage four, children {{4}} one or more of the coping strategies.', NULL, NULL, NULL, E'1.causes, 2.attempts, 3.consists, 4.execute', NULL, NULL),
  ('17cd9b55-86f9-52e0-9270-376d92b53c9b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '17cd9b55-86f9-52e0-9270-376d92b53c9b'::uuid, 1, NULL, TRUE, 0, NULL, E'Temperature and Flu', E'"Cold air is associated with {{1}} viral infection because you''ve essentially lost half of your immunity just by that small drop in temperature," said rhinologist Dr. Benjamin Bleier. A respiratory virus or bacteria {{2}} the nose, the main point of entry into the body. Immediately, the front of the nose detects the germ, well before the back of the nose is aware of the intruder, the team discovered. At that point, cells lining the nose immediately begin creating billions of simple copies of themselves called extracellular vesicles, or EV''. "EV''s can''t divide like cells can, but they are like little mini versions of cells {{3}} designed to go and kill these viruses," Bleier said. "What we found is that when you’re exposed to cold air, the temperature in your nose can drop by as much as 9 degrees Fahrenheit. And that''s enough to essentially {{4}} all three of those immune advantages that the nose has," Bleier said.', NULL, NULL, NULL, E'1.increased, 2.invades, 3.specifically, 4.knock out', NULL, NULL),
  ('17ce303a-f879-509c-b045-cf63f0a3a9b4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '17ce303a-f879-509c-b045-cf63f0a3a9b4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ceb80e58-1bc5-5f4a-ac5b-c5b9f62fc188'::uuid, NULL, NULL, E'Novelists write about the best things that they know.', NULL, NULL),
  ('17cee673-810b-5bf7-84e5-b767239e6089'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '17cee673-810b-5bf7-84e5-b767239e6089'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bcb975d3-dd06-55e3-85e0-343e1d1f5779'::uuid, NULL, E'The company saw the visit as an important signal of financial support.', NULL, NULL, NULL),
