  ('188638ed-4705-51e6-8944-2d95f2924026'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '188638ed-4705-51e6-8944-2d95f2924026'::uuid, 1, NULL, TRUE, 0, NULL, E'Polar Bears', E'Polar bears are creatures of the sea ice and they spend as much of their time on it as possible, {{1}} vast distances in {{2}} of seals. But because the ice of Hudson Bay melts completely each summer, the region’s bears must spend the warm months ashore, {{3}} in cool, earthen dens.', NULL, NULL, NULL, E'1.covering, 2.search, 3.sheltering', NULL, NULL),
  ('188c476f-67c0-5e7f-8a19-28747787686b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '188c476f-67c0-5e7f-8a19-28747787686b'::uuid, 1, NULL, TRUE, 0, NULL, E'Lunar New Year', E'Celebrated around the world, Spring Festival usually {{1}} the planet’s largest annual migration of people. Though it is known to some in the West as Chinese New Year, it isn’t just celebrated in China. Lunar New Year falls this year on Sunday, January 22, 2023, {{2}} off the Year of the Rabbit. It is traditionally a time for family {{3}} , plenty of food, and some very loud celebrations.', NULL, NULL, NULL, E'1.prompts, 2.kicking, 3.reunions', NULL, NULL),
  ('188c5b06-11f6-5727-ba48-b1c66d90c032'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '188c5b06-11f6-5727-ba48-b1c66d90c032'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '85d4d41e-d576-5a08-aeed-f3bd695c1e84'::uuid, NULL, NULL, E'Now, researchers are dealing with problems and finding answers.', NULL, NULL),
  ('188cd7b0-cff6-5c9e-ac10-7826d36c072e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '188cd7b0-cff6-5c9e-ac10-7826d36c072e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Where do we make our cars?', '5deac58a-0691-516f-8427-87884008bb71'::uuid, NULL, NULL, E'Automobile Factory / auto plant / car factory', NULL, NULL),
  ('188e0b83-62e4-5504-be19-2ac4fabdba1a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '188e0b83-62e4-5504-be19-2ac4fabdba1a'::uuid, 1, NULL, TRUE, 0, NULL, E'Violence in Ancient Societies', E'A recent study, co-authored by a researcher from Tulane University, has found evidence suggesting that violence was a prevalent aspect of life within ancient hunter-gatherer communities. The study examined skeletal remains dating back 10,000 years from burial sites in northern Chile, specifically looking for signs of trauma. These findings provide insights into the historical prevalence of violence among early human societies.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('188fee61-e4dd-5e70-ab5b-15bb1cbc7ae6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '188fee61-e4dd-5e70-ab5b-15bb1cbc7ae6'::uuid, 1, NULL, TRUE, 0, NULL, E'Ultra-Processed Foods', E'Many people know that most ultra-processed foods are not healthy. But the goal of cutting down on them can be so challenging that the majority of these attempts fail. Why? In my Food and Addiction Science and Treatment Lab at the University of Michigan, my colleagues and I are investigating one largely overlooked factor: these ultra-processed foods may be addictive, sharing more in common with tobacco products than with whole foods like apples or beans. Tobacco and ultra-processed foods alter mood in a similar way by increasing pleasurable feelings and reducing negative ones. The high levels of refined carbohydrates and fat in ultra-processed foods powerfully activate reward systems in the brain. Ultra-processed foods are highly reinforcing — they can shape your behavior to keep you coming back for more. For example, teachers and parents use ultra-processed foods to reward good behavior in children to increase the likelihood that kids will continue to behave. In rats, researchers have repeatedly found that sweet tastes are more reinforcing than even highly addictive drugs, like cocaine. The addictive nature of these ultra-processed foods undermines consumers'' free will and health in the service of profits. Yet, there is an important difference between tobacco and ultra-processed foods. We all have to eat. No one can opt out. In the case of tobacco products, it will likely take industry regulation to chip away at the popularity of ultra-processed foods.', NULL, NULL, NULL, NULL, 5, 75),
  ('18900a47-e05c-5b80-8bea-e4c3cd3a967a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '18900a47-e05c-5b80-8bea-e4c3cd3a967a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What color do tree leaves usually turn in autumn?', '3962d6ca-f879-5d57-a01d-7cc32b6e976b'::uuid, NULL, NULL, E'Yellow', NULL, NULL),
  ('189254cb-b93b-5c80-b073-989bcc505bb2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '189254cb-b93b-5c80-b073-989bcc505bb2'::uuid, 1, NULL, TRUE, 0, NULL, E'Food Sociology', E'Food is not just a basic human need but a complex social indicator that reflects personal identity, cultural traditions, and socio-economic {{1}} . The sociology of food examines how what we eat defines our relationships within families, communities, and societies. It explores the rituals of eating together, which reinforce social bonds and cultural norms, and how these practices vary {{2}} across different cultures. Food can also be a symbol of social differentiation, where dietary choices and food availability reflect underlying economic inequalities and health disparities. The global food system, with its intricate supply chains, has made diverse cuisines {{3}} , contributing to the fusion of culinary traditions but also raising ethical concerns about sustainability, food security, and the environmental impact of food production. The rise of movements such as farm-to-table and organic eating highlights a growing awareness of the connection between food, health, and the environment. Analyzing food from a sociological {{4}} reveals the layers of meaning it carries beyond mere sustenance, encompassing issues of power, tradition, and resistance in a globalized world.', NULL, NULL, NULL, E'1.status, 2.widely, 3.accessible, 4.perspective', NULL, NULL),
  ('18953a55-516e-5250-9069-049d8aa2e075'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '18953a55-516e-5250-9069-049d8aa2e075'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c8e58283-06f6-5dfd-9232-5c3302d03c31'::uuid, NULL, E'Would you pass the book on the left-hand side?', NULL, NULL, NULL),
  ('18957035-3686-59f1-93db-0d1bf36437b7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '18957035-3686-59f1-93db-0d1bf36437b7'::uuid, 1, NULL, TRUE, 0, NULL, E'Bird Species', E'Climate change is not only {{1}} the extinction of many bird species, but it may also mean that the birds that survive will have less diverse physical features. In the last 50 years, the US and Canada have lost more than one-quarter of their birds – an estimated 3 billion animals – due to human activity. A study released last year found that there are now 600 million fewer birds in Europe than there were in 1980. Extinctions are {{2}} to continue according to the latest State of the World’s Birds report, which found that 48 percent of birds worldwide are known or suspected to be {{3}} population declines. “We know we’re going to lose species, but we don’t know much about other aspects of diversity that are also super important,” says Emma Hughes at the University of Sheffield in the UK. As extinctions of some of the rarest and most {{4}} birds continue, Hughes wanted to know if surviving species will become more alike over time – a process called “homogenization”.', NULL, NULL, NULL, E'1.driving, 2.expected, 3.undergoing, 4.distinctive', NULL, NULL),
  ('1895f535-0039-5e06-86e3-54c562b94f62'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1895f535-0039-5e06-86e3-54c562b94f62'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3025159a-c834-56dc-a647-26823911a703'::uuid, NULL, NULL, E'Please visit the website for more information about the opening times.', NULL, NULL),
