  ('18a4176d-ec70-524d-959a-8263d5310fb9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '18a4176d-ec70-524d-959a-8263d5310fb9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b03651d0-d810-57fb-9bf7-cc77fa7d3d33'::uuid, NULL, NULL, E'This manual outlines the operation of the laboratory service.', NULL, NULL),
  ('18a43ab9-846b-5322-a146-d74b5f7395da'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '18a43ab9-846b-5322-a146-d74b5f7395da'::uuid, 1, NULL, TRUE, 0, NULL, E'Brain', E'In most animals, the brain is located in the head, protected by the skull and close to the primary sensory apparatus of vision, hearing, taste and olfaction. In humans, it is an organ of thought. While all vertebrates have a brain, invertebrates have either a centralized brain or collections of individual ganglia.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('18aaa600-ad88-563a-8035-937fa57c1c6e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '18aaa600-ad88-563a-8035-937fa57c1c6e'::uuid, 1, NULL, TRUE, 0, NULL, E'Automobile', E'Some people think that the automobile has improved modern life. Others think that the automobile has caused serious problems. What is your opinion?', NULL, NULL, NULL, NULL, 200, 300),
  ('18ab00ab-3520-52df-92f3-d468e6147ac9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '18ab00ab-3520-52df-92f3-d468e6147ac9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '440a9f15-0bc4-55ec-86e3-eb05ce706f06'::uuid, NULL, NULL, E'You can buy a ticket for the lecture from the school secretary.', NULL, NULL),
  ('18ad89cc-e3c0-56dc-8c5e-9d43c7dc4218'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '18ad89cc-e3c0-56dc-8c5e-9d43c7dc4218'::uuid, 1, NULL, TRUE, 0, NULL, E'Jawless Fish', NULL, NULL, NULL, NULL, E'2, 1, 4, 5, 3', NULL, NULL),
  ('18b0ba2c-1716-5e41-a435-2c4248cf9445'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '18b0ba2c-1716-5e41-a435-2c4248cf9445'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '94e23b35-6cef-581a-9bf6-ad55901864b7'::uuid, NULL, NULL, E'The industry is suffering from the effects of recent price rises.', NULL, NULL),
  ('18b0ff62-d80e-505e-878e-37855ce2a986'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '18b0ff62-d80e-505e-878e-37855ce2a986'::uuid, 1, NULL, TRUE, 0, NULL, E'Alien Life', E'No planet will have a complex form of life that popped into existence all on its own. Whatever life is like on an alien planet, it must have begun simply. But if life is to achieve any kind of complexity, the only way that complexity can accumulate is if favorable changes and innovations are retained and unfavorable ones are lost.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('18b44aeb-953b-53c2-b3a5-7e936dc79c75'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '18b44aeb-953b-53c2-b3a5-7e936dc79c75'::uuid, 1, NULL, TRUE, 0, NULL, E'Language and Thought', E'Language both reflects and shapes human thought. While some consider language a {{1}} utilitarian tool for communication, the languages we speak profoundly influence cognitive processes. They provide a system of mental categories and frameworks that color perception itself. Linguistic diversity presents a kind of natural experiment revealing relationships between the languages we learn, the way we {{2}} ideas, and prevailing cultural beliefs. As languages vanish, {{3}} do cultural traditions and intellectual legacies. Advocating for multilingualism isn''t just about preserving heritage; it''s crucial for the diverse richness of human thought and our varied perspectives on reality. We must value and support linguistic diversity or humanity will lose wisdom, tradition and ways of thought. Language extinction is a {{4}} for human epistemology and the diversity of our cultural and intellectual heritage.', NULL, NULL, NULL, E'1.purely, 2.construct, 3.so, 4.loss', NULL, NULL),
  ('18b54e7d-4ba6-5111-bd29-a61a996f1c5a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '18b54e7d-4ba6-5111-bd29-a61a996f1c5a'::uuid, 1, NULL, TRUE, 0, NULL, E'Space Exploration', NULL, '03c5e3db-19b6-5dc0-957c-db9751a4e4b7'::uuid, NULL, E'Space exploration is a testament to human curiosity and technological advancement. From peering into the stars with early telescopes to landing rovers on Mars, this journey illustrates our relentless pursuit to understand the cosmos. The story of space exploration began with early astronomers like Galileo, who used telescopes to observe celestial bodies. This marked the beginning of a new era in understanding our universe. Fast forward to the 20th century, when the launch of Sputnik, the first artificial satellite, ignited the space race, leading to remarkable milestones including the historic Apollo moon landing in 1969. In recent years, space exploration has entered a new frontier with missions to Mars. Rovers like Curiosity and Perseverance have been exploring the Martian surface, searching for signs of past life and paving the way for future human missions. These rovers represent incredible feats of engineering and symbolize our ongoing quest to explore the unknown. Space exploration is more than just scientific endeavor; it inspires us to look beyond our planet and consider our place in the universe. Each discovery brings new knowledge and raises important questions about our future in space. In conclusion, the journey of space exploration is a continuous voyage of discovery, innovation, and inspiration, demonstrating the boundless potential of human ingenuity.', NULL, NULL, NULL),
  ('18b69d56-32eb-5a3d-8130-e251fe84b48c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '18b69d56-32eb-5a3d-8130-e251fe84b48c'::uuid, 1, NULL, TRUE, 0, NULL, E'Hurry in Life', E'Some people are always in a hurry to go to various places and get things done. Other people prefer to take their time and live a life at a slower pace. What is your opinion?', NULL, NULL, E'The question of whether to live life at a fast or slow pace is a personal one. While some argue that being in a hurry is necessary for achieving success, I believe that taking one''s time and living life at a slower pace can lead to a more fulfilling and meaningful life.\nSlowing down allows for better appreciation of the present moment and enhances mindfulness. When we rush through life, we often miss out on the small details and experiences that make life worth living. By slowing down, we can take the time to appreciate the present moment and be more mindful of our thoughts, feelings, and surroundings. This can lead to a greater sense of gratitude and contentment in life.\nTaking time to relax and recharge reduces stress and promotes overall well-being. In today''s fast-paced world, stress is a common problem that can lead to physical and mental health issues. By taking the time to relax and recharge, we can reduce stress levels and promote overall well-being. This can lead to better health, improved relationships, and greater happiness in life.\nIn conclusion, I believe that taking one''s time and living life at a slower pace can lead to a more fulfilling and meaningful life. While some may argue that being in a hurry is necessary for achieving success, it is important to recognize that success can come in many forms, and a slower pace of life can lead to greater happiness and fulfillment in the long run.', NULL, 200, 300),
  ('18c01153-5d43-5ec0-8ef7-3c5424139b41'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '18c01153-5d43-5ec0-8ef7-3c5424139b41'::uuid, 1, NULL, TRUE, 0, NULL, E'Useful Resource', E'This is an extremely useful resource, which ranks books and academic papers on the subject not only in terms of their reliability but also their readability. As a result, it is likely to save students time and effort that would otherwise have been spent working through a lot of dense texts before finding the one they really need.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('18c55fff-55c6-5ee7-b906-ee336cd47173'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '18c55fff-55c6-5ee7-b906-ee336cd47173'::uuid, 1, NULL, TRUE, 0, NULL, E'Nutritionally Bankrupt', E'Globalization has affected what we eat in ways we are only beginning to understand. Modern food production no longer relates to our biological needs but is in direct conflict with them. The relationship between diet and our fertility, our risk of cancer, heart disease and mental illness is becoming clearer. Yet much of our food is nutritionally bankrupt.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('18c57e04-39c6-58d7-bf92-2b6bec858727'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '18c57e04-39c6-58d7-bf92-2b6bec858727'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '498579c4-b9cb-5fdf-a5ec-74ec6a38b6c1'::uuid, NULL, E'It takes just over eight minutes for sunlight to reach our planet.', NULL, NULL, NULL),
  ('18c682fd-85ae-560f-b1ae-a4c3dfe17210'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '18c682fd-85ae-560f-b1ae-a4c3dfe17210'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '631cf4c7-58b9-5454-ab3e-53848c361f9d'::uuid, NULL, E'The first assignment is due on the fourteenth of September.', NULL, NULL, NULL),
  ('18cc0630-8941-5a43-b778-de399eebfda3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '18cc0630-8941-5a43-b778-de399eebfda3'::uuid, 1, NULL, TRUE, 0, NULL, E'Water and Land Temperature', E'During the day, the sun heats up both the ocean surface and the land. And, {{1}} is a good absorber of the energy from the sun. The land absorbs much of the sun''s energy as well. However, water heats up much more slowly than land and so the air above the land will be {{2}} compared to the air over the ocean. The warm air over the land will rise throughout the day, causing low pressure at the surface. Over the water, high surface pressure will form because of the colder air. To {{3}} , the air will sink over the ocean. The wind will blow from the higher pressure over the water to lower pressure over the land causing the sea breeze. The sea breeze strength will vary depending on the temperature {{4}} between the land and the ocean.', NULL, NULL, NULL, E'1.water, 2.warmer, 3.compensate, 4.difference', NULL, NULL),
  ('18ced824-02d4-53a1-894f-9b12537e3bf3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '18ced824-02d4-53a1-894f-9b12537e3bf3'::uuid, 1, NULL, TRUE, 0, NULL, E'Low Fertility', E'Low fertility is a concern for many OECD countries as they face the prospect of population aging. This article makes {{1}} between Australia and seven other OECD countries in fertility rates between 1970 and 2004. Changing age {{2}} of fertility are also compared and show that for most of the countries, women are {{3}} childbirth and having fewer babies. The {{4}} of women''s education levels and rates of employment with fertility are also {{5}} .', NULL, NULL, NULL, E'1.comparisons, 2.patterns, 3.postponing, 4.associations, 5.explored', NULL, NULL),
  ('18d6b07e-79bf-501a-8617-3dea207f89e5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '18d6b07e-79bf-501a-8617-3dea207f89e5'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '98fef666-fcf4-5176-9615-068fa59c4a0b'::uuid, NULL, E'He was suffering from exposure and shock but his condition was said to be stable.', NULL, NULL, NULL),
  ('18d6b66f-21b9-5dcb-8175-ef315662498a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '18d6b66f-21b9-5dcb-8175-ef315662498a'::uuid, 1, NULL, TRUE, 0, NULL, E'Zebrafish', E'A simple and inexpensive zebrafish model of concussion reveals the genetic pathways underlying the animal''s remarkable ability to regenerate injured brain tissue. Understanding the mechanisms of regeneration in the zebrafish brain could ultimately help identify new ways to promote recovery from head injury in humans.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('18d90ff9-5fbb-5a52-8d79-26a89314be1c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '18d90ff9-5fbb-5a52-8d79-26a89314be1c'::uuid, 1, NULL, TRUE, 0, NULL, E'Honeybee Foraging', E'Honeybees are specialized foragers, collecting nectar and pollen {{1}} from flowers. They have evolved unique behaviors and physical adaptations for this task, such as a proboscis for {{2}} nectar and pollen baskets on their legs. Their foraging activities are crucial for pollination, {{3}} the reproduction of many flowering plants.', NULL, NULL, NULL, E'1.exclusively, 2.extracting, 3.enabling', NULL, NULL),
  ('18dfd12f-be93-574f-9094-c4158d4945e4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '18dfd12f-be93-574f-9094-c4158d4945e4'::uuid, 1, NULL, TRUE, 0, NULL, E'Bans from Everest', E'At 29,029 feet (8,848 meters), Mount Everest is the world''s tallest peak and an irresistible and (and sometimes deadly) draw for mountain climbers from all over the planet. It''s also a place of political turmoil and intrigue, straddling the border of China and Nepal, which offer up different regulations for would-be adventurers. In late December 2017, Nepal''s newest set of rules came under fire from some quarters for banning blind, amputee, and solo climbers.\nThe Nepalese tourism ministry tweaked the regulations in what it says is an effort to curb fatalities on the legendary slopes, which are steep, shifty, and so high that most climbers need supplemental oxygen to reach the summit. The moves would also create jobs for locals to act as guides for solo climbers.\nSome suspect that the new rules may be a ham-handed way to limit the ever-burgeoning crowds that now flood the slopes during the climbing season, which lasts for just a short time each year (mostly April and May) due to severe weather. Human waste, litter, and bottlenecks on narrow slopes make Everest look more like a packed movie theater queue than a wilderness journey on some days.\nAdventurer and author Brian Dickinson summited Everest in 2011. "Over the past few decades Everest has had some bad press based on unqualified climbers," he says. "Nepal is struggling to find an answer on how to control who should and shouldn''t climb, but they are focusing on the wrong demographic. They probably feel that others seeing blind and disabled climbers attempting the mountain makes the climb appear doable for anyone."', NULL, NULL, NULL, NULL, 5, 75),
  ('18e69989-035f-5590-93d6-a9fa08738951'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '18e69989-035f-5590-93d6-a9fa08738951'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e49e788c-30fc-5cb7-96d0-a76e458a0895'::uuid, NULL, NULL, E'Rising global temperatures are significantly changing wildlife populations and behavior.', NULL, NULL),
  ('18efc5f6-ef1b-5b54-b9bf-943e1f0f3edf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '18efc5f6-ef1b-5b54-b9bf-943e1f0f3edf'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7fa2f6cf-f058-5dca-a780-5eecd93faa7d'::uuid, NULL, NULL, E'Remember to sign the register before you exit the classroom.', NULL, NULL),
  ('18f29a57-17a5-50ee-81c5-aa912b88772a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '18f29a57-17a5-50ee-81c5-aa912b88772a'::uuid, 1, NULL, TRUE, 0, NULL, E'Meteorite', E'A meteorite that fell on Earth more than a century ago may contain some of the first concrete evidence for a cosmic mash-up in the early solar system. Following the birth of our sun 4.5 billion years ago, it is thought that Jupiter’s formation caused two reservoirs of asteroids to gather in the solar system, one inside the giant planet’s orbit and one outside.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('18f612c9-1c2e-5e4f-9764-d58cf23797d6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '18f612c9-1c2e-5e4f-9764-d58cf23797d6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a97fd0a0-d392-5977-9306-fac102c2ac41'::uuid, NULL, E'There are a range of housing options near the university.', NULL, NULL, NULL),
  ('19069066-1403-5652-903c-986f00847d7c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '19069066-1403-5652-903c-986f00847d7c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What are the people who study ancient bones or plants in rocks?', '5e8a33af-d113-5cce-91eb-ac89b67ae597'::uuid, NULL, NULL, E'Paleontologists / paleontologist / archaeologists / archaeologist', NULL, NULL),
  ('190cc159-c19c-5b1f-b76d-e58a89a3a459'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '190cc159-c19c-5b1f-b76d-e58a89a3a459'::uuid, 1, NULL, TRUE, 0, NULL, E'Schooling Model', E'The conventional model of schooling emerged in Prussia in the 18th century. Alternatives have so far failed to teach as many children as efficiently. Classrooms, hierarchical year-groups, standardized curriculums and fixed timetables are still the norm for most of the world’s nearly 1.5 billion schoolchildren.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('191157f5-5d69-5f5e-a413-fc392d31de82'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '191157f5-5d69-5f5e-a413-fc392d31de82'::uuid, 1, NULL, TRUE, 0, NULL, E'Introvert and Extrovert', E'Introverts (or those of us with introverted tendencies) tend to recharge by spending time alone. They lose energy from being around people for long periods of time, particularly large crowds. Extroverts, on the other hand, gain energy from other people. Extroverts actually find their energy is sapped when they spend too much time alone. They recharge by being social.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('1913b0c8-8ee4-57c7-9211-6dc72ddb4408'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '1913b0c8-8ee4-57c7-9211-6dc72ddb4408'::uuid, 1, NULL, TRUE, 0, NULL, E'Colony Collapse Disorder', E'Colony Collapse Disorder (CCD) has emerged as a perplexing and urgent concern for entomologists and environmentalists alike. This phenomenon, characterized by the abrupt disappearance of worker bees from a hive, has been causing significant declines in bee populations globally. The alarming rate of these disappearances not only {{1}} the survival of bee colonies but also poses a serious risk to agricultural practices dependent on pollination. Various hypotheses have been proposed to explain CCD, {{2}} environmental stress factors like climate change and habitat loss, to biological threats such as Varroa mites and pathogens. Additionally, the widespread use of agricultural pesticides, particularly neonicotinoids, has been implicated in weakening bee health, making them more {{3}} to disease and disorientation. As scientists delve {{4}} into this issue, the urgency to understand and mitigate the impacts of CCD grows, recognizing its critical role in maintaining biodiversity and food security worldwide.', NULL, NULL, NULL, E'1.threatens, 2.ranging from, 3.susceptible, 4.deeper', NULL, NULL),
  ('1917fe2b-e99a-5668-914c-0bdf8d7a5a39'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '1917fe2b-e99a-5668-914c-0bdf8d7a5a39'::uuid, 1, NULL, TRUE, 0, NULL, E'Ice Storm', E'An ice storm is a type of {{1}} when {{2}} rainfall comes down into the cold air and the water turns into {{3}} . Once there were {{4}} than 16,000 households which had a blackout {{5}} an ice storm as the cables snapped with ice weighing on them.', NULL, NULL, NULL, E'1.weather, 2.cold, 3.ice, 4.more, 5.during', NULL, NULL),
  ('1919022a-1c6d-5c3f-bf02-c02db3ba59ea'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1919022a-1c6d-5c3f-bf02-c02db3ba59ea'::uuid, 1, NULL, TRUE, 0, NULL, E'Slang', E'Australians do speak English. However, for some tourists and travelers, it can be difficult to understand the slang. Also, the links between Australian and American English were seen to be very tenuous. At least some colloquialisms in Australian English do not exist in other types of English.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('19198cb3-0665-5eda-82c2-d7d391fa1889'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'HIGHLIGHT_CORRECT_SUMMARY', E'HIGHLIGHT_CORRECT_SUMMARY', E'LISTENING', E'SHARED', NULL, E'APPROVED', '19198cb3-0665-5eda-82c2-d7d391fa1889'::uuid, 1, NULL, TRUE, 0, NULL, E'Less Expectation of Love', E'To enjoy a harmonious union with someone, we should ensure that we have plenty of sources of excitement, reassurance and stimulation outside of them. When we hit problems, we should be able to lean on other supports. The demand that another person compensates us for all that’s alarming, wearing or deficient in our lives is a mechanism for systematically destroying any relationship. Our conflicts and disappointments will at once feel more manageable when we stop asking our partner to function always as our long lost other half. The more we can survive without a relationship the greater will be that relationship’s chances of survival and fulfillment. We will truly give love a chance when we stop believing it can single-handedly save us.\n\nClick on the paragraph that best relates to the recording.', '52caf64f-fb8a-50b3-84d9-93fa38658a74'::uuid, NULL, NULL, E'The chance of survival and fulfillment of a relationship will be great, if we can survive without it. When we stop believing that love alone can save us, we will truly give love a chance.', NULL, NULL),
  ('1924c1f2-02a8-52e8-ae1e-1e0fab2bcb2f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1924c1f2-02a8-52e8-ae1e-1e0fab2bcb2f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f5f9f6ed-ec53-56a1-ac6f-cedb6cacc7e6'::uuid, NULL, NULL, E'The visiting speaker used to be a lecturer in this department.', NULL, NULL),
  ('1934e346-42ad-5619-bbee-0301c308a5a5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1934e346-42ad-5619-bbee-0301c308a5a5'::uuid, 1, NULL, TRUE, 0, NULL, E'Brain', NULL, '25c0db96-c41b-51e4-ae06-60812f5375e3'::uuid, NULL, E'The brain is basically built from the bottom up first the brain builds basic circuits that are responsible for basic skills, and then more complex circuits are built on top of those basic circuits as we develop more complex skills. Biologically, the brain is prepared to be shaped by experience. It’s expecting the experiences that a young child has to literally influence the formation of its circuitry it’s built into our biology. The interaction between genetics and experience that shapes brain architecture is embedded in a reciprocal relationship, the relationships that children have with the adults in their lives. And by that we mean what we refer to as the serve-and-return nature of children’s interaction with their adults development. And the impact of experience on development is not a one-way street. It’s a back-and-forth interaction. The brain is a highly integrated organ which has multiple sections that specialize in different kind of processes, so we have parts of the brain that are involved more in cognitive function and other parts that are involved in processing of emotion and parts involved in seeing and hearing. So if a child is emotionally kind of...well...put together and socially competent, that will affect more positive and productive learning. And if a child is preoccupied with fears or anxiety or is dealing with considerable stress no matter how intellectually gifted that child might be, his or her learning is going to be impaired by that kind of emotional interference.', NULL, NULL, NULL),
  ('19357a39-86e7-5b9f-a7d7-4637188be856'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '19357a39-86e7-5b9f-a7d7-4637188be856'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '049aa62a-c284-5497-b11f-6ca836312df5'::uuid, NULL, NULL, E'The workshop will show you how to search the library catalogues.', NULL, NULL),
  ('1936fa05-4866-55d9-aa36-3c08cf6669e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1936fa05-4866-55d9-aa36-3c08cf6669e9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '73cf43c3-0702-5af8-b0b6-ddd558fc7a0c'::uuid, NULL, NULL, E'Certain scientific principles must be learned verbally or by a logical deduction.', NULL, NULL),
  ('193a9f98-14cc-530e-849f-0c08bf854cd4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '193a9f98-14cc-530e-849f-0c08bf854cd4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '10a01fe7-93f9-5c35-a7ed-8a2ea4aaff23'::uuid, NULL, NULL, E'I have met him several times in different public lectures.', NULL, NULL),
