  ('1957c521-56ca-5780-b760-cc6fbf28ea41'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1957c521-56ca-5780-b760-cc6fbf28ea41'::uuid, 1, NULL, TRUE, 0, NULL, E'Tests of drug', E'Tests of a drug known to stimulate brain activity have shown early success in reducing symptoms of sluggish cognitive tempo in 38 men and women with attention deficit hyperactivity disorder. It also significantly corrected deficits in executive brain function, with fewer episodes of procrastination, improvements in keeping things in mind, and strengthened prioritization skills.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('195e0450-a679-5c44-a538-e75c073d7606'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '195e0450-a679-5c44-a538-e75c073d7606'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e5050ae8-fca2-55fd-a373-bdf866cf743d'::uuid, NULL, NULL, E'The cart carries a single object.', NULL, NULL),
