  ('19c31fda-689e-5a5d-8869-0e3c2778dc31'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '19c31fda-689e-5a5d-8869-0e3c2778dc31'::uuid, 1, NULL, TRUE, 0, NULL, E'Kindness Campaign', E'Fortunately, educators have access to many online resources that are {{1}} useful when helping children along the path to peace. The Young Peacemakers Club, started in 1992, provides a Website with resources for teachers and {{2}} on starting a Kindness Campaign. The World Centers of Compassion for Children International call attention to children''s rights and how to help the {{3}} of war. Starting a Peacemakers'' Club is a praiseworthy venture for a class and one that could spread to other classrooms and ideally affect the culture of the {{4}} school.', NULL, NULL, NULL, E'1.especially, 2.information, 3.victims, 4.entire', NULL, NULL),
