  ('1a2d91ff-42be-50be-8d19-bc8f1be07c50'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '1a2d91ff-42be-50be-8d19-bc8f1be07c50'::uuid, 1, NULL, TRUE, 0, NULL, E'Photographic Memory', E'Photographic memory is the ability to recall a past scene in detail with great {{1}} – just like a photo. Although many people claim they have it, we still don’t have proof that photographic memory actually {{2}} . However, there is a condition called Highly Superior Autobiographical Memory that allows people to recall past events in detail, along with the exact dates when they {{3}} .', NULL, NULL, NULL, E'1.accuracy, 2.exists, 3.occurred', NULL, NULL),
  ('1a317bfd-c878-5c56-8e35-2b111ebf25f4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1a317bfd-c878-5c56-8e35-2b111ebf25f4'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Despite all the advances in equality between the sexes, would more men or women play professional football?', '5bdcde6f-0d24-5413-ab93-51f4756a313d'::uuid, NULL, NULL, E'Men', NULL, NULL),
