  ('1a4571c4-ad74-592e-9a92-9397057c5762'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '1a4571c4-ad74-592e-9a92-9397057c5762'::uuid, 1, NULL, TRUE, 0, NULL, E'Comfort Zone', E'People prefer to stay in their comfort zone rather than try something new. Do you have any suggestions for them?', NULL, NULL, NULL, NULL, 200, 300),
  ('1a464753-c9bb-506c-ad8a-10f77c680329'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1a464753-c9bb-506c-ad8a-10f77c680329'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ba0ca94a-0c38-5246-8025-66577e0d8b45'::uuid, NULL, E'Tuition fees will vary according to the field of study.', NULL, NULL, NULL),
  ('1a4e18ea-158c-5162-ae8a-247be0d44bc0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1a4e18ea-158c-5162-ae8a-247be0d44bc0'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4676f55f-1cb6-549a-87c2-88d3ec34f32e'::uuid, NULL, NULL, E'Most people who looked at the idea thought it was good.', NULL, NULL),
  ('1a53f55c-9b63-5f9f-bfb1-e30bd2c476c1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1a53f55c-9b63-5f9f-bfb1-e30bd2c476c1'::uuid, 1, NULL, TRUE, 0, NULL, E'Emotional Strength', E'How can you be prepared for what’s ahead in life, good or bad? Building emotional strength can help you learn how to be confident in handling its twists and turns. But emotional strength doesn’t mean pushing aside or suppressing negative feelings or emotions; instead, it means acknowledging them and finding healthy ways to process and respond to them.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('1a5adabf-6aec-5636-b3e0-eac956736b5c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '1a5adabf-6aec-5636-b3e0-eac956736b5c'::uuid, 1, NULL, TRUE, 0, NULL, E'APP', E'When a tech startup finishes making prototypes and creates a cool new app, the leaders think about the best ways to {{1}} money from it. They look at costs, how much they want to earn in the long run, what other similar services are doing to attract customers, and how much their target users {{2}} to pay for certain features. They might let people use it for free or at a lower cost at first to get more users and attention, and then decide on the right amount to {{3}} for subscriptions. The price for different subscription levels should match what makes their app special for different types of customers, considering their hobbies, how much money they have to spend, and what other apps can''t give them. Besides selling the app directly, they can also make profits by letting big companies use it or by sharing user data with advertisers. This helps keep the app free for regular users. Like any pricing plan, they need to {{4}} adjusting it based on how people are using the app, to find a good balance between {{5}} and viable profit margins.', NULL, NULL, NULL, E'1.make, 2.are willing, 3.charge, 4.keep, 5.affordability', NULL, NULL),
  ('1a5bce48-bfc0-55c8-a0f5-b3cec08f1974'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1a5bce48-bfc0-55c8-a0f5-b3cec08f1974'::uuid, 1, NULL, TRUE, 0, NULL, E'Language Skills', E'Musicians are said to have better language skills. And scientific studies have backed that up. But it''s not clear why that might be the case.\nNow a study of 74 Chinese kindergartners suggests six months of piano lessons can heighten the brain''s response to changes in pitch. And kids who got piano lessons were also better at telling apart two similar-sounding Mandarin words, which contained different consonants, than were students who got extra reading training, or who just went through regular kindergarten. The results are in the Proceedings of the National Academy of Sciences.\nMandarin is a tonal language: the famous example being the word ''ma'' which can mean mother or horse depending on its pitch. So might musical training translate better to Mandarin, than, say, English? "Yeah it''s possible that influenced the results." Robert Desimone, a neuroscientist at the McGovern Institute at MIT. But he says other studies do back up the fact that music lessons benefit language learners, even in countries without tonal languages. "And what our study added on top of that was also some idea of the neural basis."\n\nAccording to the audio, which of the following statements are false?', '310b7345-2bfd-502c-9c9a-473ebb4410a0'::uuid, NULL, NULL, E'Children who have attended kindergarten are more interested in music.\nMusic lessons only benefit language learners who learn tonal languages.', NULL, NULL),
  ('1a5eeb63-78cd-5e07-8551-332f74d1f4b4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1a5eeb63-78cd-5e07-8551-332f74d1f4b4'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the joint that connects the top and bottom parts of the leg?', 'f40a9359-1b91-5e95-b92d-34e0eaebe185'::uuid, NULL, NULL, E'Knee', NULL, NULL),
  ('1a604443-11b6-5ff5-a958-bbf129ede50b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '1a604443-11b6-5ff5-a958-bbf129ede50b'::uuid, 1, NULL, TRUE, 0, NULL, E'Swedish Forestland', E'The growing season in Sweden ranges from about 240 days in the south to 120 days in the north. Less than one-tenth of Sweden’s land area is under cultivation. Most arable land is found in southern Sweden, but there are arable parcels up to the Arctic Circle. Wheat, barley, sugar beets, oilseeds, potatoes, and staple vegetables dominate in the south, while in the north hay and potatoes are the main crops. In Sweden as a whole, animal agriculture is more significant than cereal farming. Dairy cows are important in all parts of the country, while pig and poultry raising are concentrated in the extreme south. The yields of Swedish farms are among the highest in the world. Environmental problems, however, have made it necessary to reduce the use of fertilizers.\nAbout half of Swedish forestland is privately owned, about one-fourth company-owned, and about one-fourth publicly owned. Forest work used to be complementary winter employment for small farmers using their horses; today forestry is carried on year-round by a small workforce and large, modern machinery. Nearly three-fourths of all Swedish farms have timberland. The average regrowth and harvest time for spruce and pine is about 50 years in the south and roughly 140 years in the north. Since the late 19th century, forestry in Sweden has been conducted on a sustained-yield basis, which establishes a ratio between cutting and new growth that is strictly enforced. Modern large-scale forestry methods have been subject to severe criticism, and major reforms were implemented in the 1990s. A thorough mapping and inventory of key woodland habitats was undertaken in the mid-1990s to identify areas with high biodiversity values.', NULL, NULL, NULL, NULL, 5, 75),
  ('1a634f59-e738-577c-be6f-9964341dc5bc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1a634f59-e738-577c-be6f-9964341dc5bc'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '271b4575-a0e4-5111-a002-9d87c82c5c39'::uuid, NULL, E'An effective business manager is always open to new ideas.', NULL, NULL, NULL),
