  ('1b752d08-5e4f-5d7c-ad1d-9bf49a55aff5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '1b752d08-5e4f-5d7c-ad1d-9bf49a55aff5'::uuid, 1, NULL, TRUE, 0, NULL, E'Mandarin Chinese', E'The growing global influence of China has led to a surge in interest in learning Mandarin Chinese, now one of the most {{1}} spoken languages in the world. To cater to this demand, the comprehensive language course "Mandarin Mastery" has been developed, providing an immersive learning experience for adult learners. This course starts with the basics of Mandarin phonetics and characters and gradually {{2}} to complex linguistic structures and cultural nuances. Utilizing a blend of traditional and modern teaching {{3}} , including interactive digital tools, the course offers an engaging and effective way to achieve fluency. It covers a wide range of topics, from everyday conversation to business communication, {{4}} learners are well-equipped to navigate various social and professional settings. "Mandarin Mastery" focuses on language proficiency and {{5}} to deepen learners'' understanding of Chinese culture and history, providing a holistic approach to language learning.', NULL, NULL, NULL, E'1.widely, 2.advances, 3.methods, 4.ensuring, 5.aims', NULL, NULL),
  ('1b7cbbcd-bba3-568c-a7c4-f84174965ebd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1b7cbbcd-bba3-568c-a7c4-f84174965ebd'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which word is used to describe a large city like New York and London?', 'f25bfb6c-697b-5106-8b8a-873f8a8d0315'::uuid, NULL, NULL, E'Metropolis / bigalopolis', NULL, NULL),
