  ('1cfa4886-eca6-51c2-a2c4-d73fa273dc9f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '1cfa4886-eca6-51c2-a2c4-d73fa273dc9f'::uuid, 1, NULL, TRUE, 0, NULL, E'Hearing Loss', E'The impacts of hearing loss are broad and can be {{1}} . They include a loss of the ability to communicate with others and {{2}} language development in children, which can lead to social isolation, loneliness and frustration, particularly among older people with hearing loss. Many areas lack {{3}} accommodations for hearing loss, which effect academic performance and options for employment.', NULL, NULL, NULL, E'1.profound, 2.delayed, 3.sufficient', NULL, NULL),
  ('1cfdc3ba-b338-5fdc-acde-4b87017b4b54'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1cfdc3ba-b338-5fdc-acde-4b87017b4b54'::uuid, 1, NULL, TRUE, 0, NULL, E'Data Accuracy', E'Stakeholder acceptance and use of analytics depends on their trust in the data. End users and executives don’t always think about the behind-the-scenes work and preparation that went into a dashboard. But they do have an intuitive grasp of and even an emotional connection to accurate data, making obviously inaccurate data a real challenge to overcome.', NULL, NULL, NULL, NULL, NULL, NULL),
