  ('1d5362e7-0f69-50be-9720-cd84e3e11ede'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1d5362e7-0f69-50be-9720-cd84e3e11ede'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the opposite of ''forward''?', '0dcbd08e-105e-54e5-a600-4f0bf7692260'::uuid, NULL, NULL, E'Backward', NULL, NULL),
