  ('1e133b0c-cb67-5089-917a-e0433095db8c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1e133b0c-cb67-5089-917a-e0433095db8c'::uuid, 1, NULL, TRUE, 0, NULL, E'Economies of Scale', E'If countries can specialize in certain goods they can benefit from economies of scale and lower average cost. This is especially true in the industry with high fixed costs or that require a high level of investment. The benefits of the economy of scale will ultimately lead to lower prices for consumers and greater efficiency for exporting firms.', NULL, NULL, NULL, NULL, NULL, NULL),
