  ('1e5d2aad-0903-574d-b52e-c722eb71cbf3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1e5d2aad-0903-574d-b52e-c722eb71cbf3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ac88c9bc-7464-599f-b23a-27606f4cf236'::uuid, NULL, NULL, E'The teaching staff are not only educators but industry professionals.', NULL, NULL),
  ('1e6480d8-938e-5fd3-9d9d-abf3a4092d12'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1e6480d8-938e-5fd3-9d9d-abf3a4092d12'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do we describe materials that are able to conduct electricity?', '8addfcb2-bc89-5886-a18a-020b99f040ca'::uuid, NULL, NULL, E'Conductive', NULL, NULL),
  ('1e67647d-acba-53bd-ab87-0cc85d88e278'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1e67647d-acba-53bd-ab87-0cc85d88e278'::uuid, 1, NULL, TRUE, 0, NULL, E'Ocean Acidification', NULL, '82fc872a-cc21-5e5b-bf96-02c000c38480'::uuid, NULL, E'Well today I’m going to tell you about a serious reality that is changing our oceans called ocean acidification, or the evil twin of climate change. Did you know that the oceans have absorbed 25 percent of all of the carbon dioxide that we have emitted to the atmosphere? Now this is just another great service provided by the oceans since carbon dioxide is one of the greenhouse gases that’s causing climate change. But as we keep pumping more and more and more carbon dioxide into the atmosphere, more is dissolving into the oceans. And this is what’s changing our ocean chemistry. When carbon dioxide dissolves in seawater, it undergoes a number of chemical reactions. Now lucky for you, I don’t have time to get into the details of the chemistry for today, but I’ll tell you as more carbon dioxide enters the ocean, the seawater pH goes down. And this basically means that there is an increase in ocean acidity. And this whole process is called ocean acidification. And it’s happening alongside climate change. Scientists have been monitoring ocean acidification for over two decades. This figure is an important time series in Hawaii, and the top line shows steadily increasing concentrations of carbon dioxide, or CO2 gas, in the atmosphere. And this is directly as a result of human activities. The line underneath shows the increasing concentrations of carbon dioxide that is dissolved in the surface of the ocean which you can see is increasing at the same rate as carbon dioxide in the atmosphere since measurements began. The line on the bottom then shows the change in chemistry. As more carbon dioxide has entered the ocean, the seawater pH has gone down, which basically means there has been an increase in ocean acidity.', NULL, NULL, NULL),
  ('1e6e4a9a-3cee-5d5e-95e7-c56c19611833'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1e6e4a9a-3cee-5d5e-95e7-c56c19611833'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0c6cf030-085c-549c-851c-c8942fa0b861'::uuid, NULL, E'The world''s population increased from millions to billions in just over a decade.', NULL, NULL, NULL),
