  ('1f70774c-a7bf-5ec9-b170-146f7ec77686'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1f70774c-a7bf-5ec9-b170-146f7ec77686'::uuid, 1, NULL, TRUE, 0, NULL, E'Soybean Products', E'There are many reasons why Japanese people live longer than the rest of us. One reason might be soybean products like tofu, natto and miso. Scientists from the National Institute of Health and Nutrition in Tokyo conducted a study into the health benefits of soybeans and their products. They found that people who regularly ate tofu, natto and miso were 10 per cent less likely to die from common killers than people who ate no soybean products. Researchers said eating soybean-based food lowered the risk of death from heart attacks, stroke and other cardiovascular problems. They said: "A higher intake of fermented soy products was associated with a lower risk of mortality."\n\nWhich one below is true according to this audio?', 'bd028570-781b-5da1-b1b9-6e40e9ef2193'::uuid, NULL, NULL, E'People who regularly ate tofu were 10 percent less likely to die from a common cause than those who avoided soy products.', NULL, NULL),
  ('1f70dcdf-18a8-5285-a1c0-6edeaa27af21'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1f70dcdf-18a8-5285-a1c0-6edeaa27af21'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '92bd4033-9389-5d06-a07f-686b418339ae'::uuid, NULL, NULL, E'Farms must modify practices to cope with challenging climate conditions.', NULL, NULL),
  ('1f72065e-fd21-545e-8ae6-6f11814420a0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1f72065e-fd21-545e-8ae6-6f11814420a0'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '99d48656-af61-5d47-a1da-ec47f210407c'::uuid, NULL, NULL, E'Travelling by boat on the river is not possible in winter.', NULL, NULL),
  ('1f8104f2-064f-5e0c-93b4-5c5d2181e0c9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1f8104f2-064f-5e0c-93b4-5c5d2181e0c9'::uuid, 1, NULL, TRUE, 0, NULL, E'Norms and Values', E'Norms and values are important concepts in sociology that shape human behavior and social interactions. Values are the fundamental beliefs that guide individuals'' actions, while norms are the expectations that society has for people''s behavior. In other words, values determine what is right or wrong, while norms determine what is acceptable or not.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('1f8b09c4-f9a3-50fe-ba1d-647527e6bef7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1f8b09c4-f9a3-50fe-ba1d-647527e6bef7'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0d029729-cac0-593f-a593-16de623bdcd0'::uuid, NULL, E'The relation between national health and social care services is very important.', NULL, NULL, NULL),
  ('1f92ce29-3359-514c-a0d6-7e5183348657'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1f92ce29-3359-514c-a0d6-7e5183348657'::uuid, 1, NULL, TRUE, 0, NULL, E'Maturity and Kindness', E'For noble and very understandable reasons, we’ve come to associate maturity and kindness with a capacity not to give up on people. But this broad and generous truth can be in danger of missing out on an important caveat that health and maturity may also require a subtle capacity to give up on one or two people.', NULL, NULL, NULL, NULL, NULL, NULL),
