  ('1f9c8264-d898-5888-9ff8-d4f78e48f38c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1f9c8264-d898-5888-9ff8-d4f78e48f38c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ba38c958-8f6d-5939-8ea6-ac0555b12805'::uuid, NULL, E'The aim of the cruise was to awaken an interest in foreign cultures.', NULL, NULL, NULL),
  ('1fa22178-a239-5b18-984d-ff11a26198eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '1fa22178-a239-5b18-984d-ff11a26198eb'::uuid, 1, NULL, TRUE, 0, NULL, E'Good School', E'A big rise in state schools rated among the best institutions in the country is revealed in the latest edition of the Good Schools Guide. Middle-class parents facing financial pressures in the {{1}} are increasingly looking beyond the private sector to educate their children. The 23 year-old Good Schools Guide -- a {{2}} reference book for fee-paying families set on the best private school -- has increased the number of state schools in this year''s edition to 251, pushing the figure to more than a quarter of its 1,000 entries for the first time. And, {{3}} why the guide has more than doubled the number of schools it features outside the private sector in only five years, Sue Fieldman, regional editor, told the Financial Times: "The parents we speak to want more information on the state sector and the best it has to offer. "', NULL, NULL, NULL, E'1.downturn, 2.popular, 3.explaining', NULL, NULL),
  ('1fa83612-ab2a-5432-8f09-637d02fec2fc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '1fa83612-ab2a-5432-8f09-637d02fec2fc'::uuid, 1, NULL, TRUE, 0, NULL, E'Biodegradation', E'In {{1}} ,biodegradation is simple — large or complex materials are biologically converted into smaller, simpler, ideally non-toxic {{2}} that can be recycled in the biosphere, ideally without human {{3}} .However, the {{4}} involved in biological degradation are technically complex and the conditions under which biodegradation {{5}} in large scale waste management environments generally do not match those found in purely natural environments, such as soil and seawater.', NULL, NULL, NULL, E'1.concept, 2.compounds, 3.intervention, 4.mechanisms, 5.occurs', NULL, NULL),
  ('1fb46b6e-f01f-50bd-b12f-a4ed832161a3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1fb46b6e-f01f-50bd-b12f-a4ed832161a3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '051d4852-22ad-5142-bb3a-868f34a52e50'::uuid, NULL, NULL, E'This book mainly introduces the history of physics and astronomy.', NULL, NULL),
  ('1fb60122-3bf8-5a8d-802f-eca95d6b0d91'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1fb60122-3bf8-5a8d-802f-eca95d6b0d91'::uuid, 1, NULL, TRUE, 0, NULL, E'Golden Age', E'We call the first two decades of the twentieth century, the golden age of American agriculture. What were the factors that made the period, the golden age of American agriculture? Who can offer some reasons? New strains of crops, improved farming methods. And what about greater use of pesticides and fertilizers? Absolutely. Technical advances continue to improve productivity. The u s department of agriculture set up demonstration farms to show how new techniques could improve crop yields. In nineteen fourteen, congress created the agricultural extension service to advise farmers and their families about everything from crop fertilizers to home sewing projects. The department of agriculture undertook new research, developing hogs that fattened faster on less grain, as well as fertilizers that increased grain production, new hybrid seeds that developed into healthier plants, treatments that prevented or cured plant and animal diseases. And various methods for controlling pests were all introduced around this time. Anything else? Wasn''t there also some kind of population boom around then? Good farm prices were high as demand for goods increased and land values rose. However, the good years of the early twentieth century ended following world war one.\n\nWhat are the main reasons that made the early 20th century the golden age of American agriculture?', '72f14cf8-44b5-579b-b6fc-08a4d2b5d203'::uuid, NULL, NULL, E'The improvement of farming methods due to advanced technology.\nThe introduction of newly-developed seeds.', NULL, NULL),
  ('1fca96c4-7bed-52eb-b211-8f4aea78b495'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1fca96c4-7bed-52eb-b211-8f4aea78b495'::uuid, 1, NULL, TRUE, 0, NULL, E'Fence', E'Fence, humanly erected barrier between two divisions of land, used to mark a legal or other boundary, to keep animals or people in or out, and sometimes as an ornament. In newly settled lands fences are usually made of materials at hand, e.g., stone, earth, or wood.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('1fcdc128-5d8f-5036-b3c7-c202a9b2a8d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1fcdc128-5d8f-5036-b3c7-c202a9b2a8d5'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e10344cc-23e9-5c4d-bf8c-4e0836b77700'::uuid, NULL, E'The potential to reach new customers through social media has never been greater.', NULL, NULL, NULL),
  ('1fd07f37-1363-5b94-84e4-44c925564a47'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1fd07f37-1363-5b94-84e4-44c925564a47'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0b03d7ac-8df2-5c01-9c38-864c7e9aa4df'::uuid, NULL, NULL, E'The courses cover several aspects of the subject.', NULL, NULL),
  ('1fd44314-fc78-590d-b374-f890adce6ab6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '1fd44314-fc78-590d-b374-f890adce6ab6'::uuid, 1, NULL, TRUE, 0, NULL, E'Shakespeare''s Plays', E'Long ago, many plays written by William Shakespeare were staged in open-air theaters. These plays were usually performed during the daytime since {{1}} light was not available at the time. The theaters were designed with three sides of the auditorium full of audience members, {{2}} a vibrant and crowded atmosphere. Shakespeare''s plays attracted large audiences, ranging from the wealthy nobles seated in balconies to the {{3}} people standing near the stage.', NULL, NULL, NULL, E'1.artificial, 2.creating, 3.common', NULL, NULL),
  ('1fd4ef18-362e-54c0-a793-941f10cd5245'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '1fd4ef18-362e-54c0-a793-941f10cd5245'::uuid, 1, NULL, TRUE, 0, NULL, E'Product Concept', E'Both historically and currently, many businesses do not follow the marketing concept. For many years, companies such as Texas Instruments and Otis Elevator have followed a product {{1}} , in which the primary organizational focus is technology and innovation. All parts of these organizations invest heavily in building and showcasing impressive features and product {{2}} , which are the areas in which these companies prefer to compete. This approach is also known as the product concept. Rather than focusing on a deep understanding of customer needs, these companies assume that a technically {{3}} or less expensive product will sell itself. While this approach can be very {{4}} ,there is a high risk of losing touch with what customers actually want. This leaves product-oriented companies vulnerable to more customer-oriented competitors.', NULL, NULL, NULL, E'1.orientation, 2.advances, 3.superior, 4.profitable', NULL, NULL),
  ('1fd7e1f4-bec5-521c-a1c0-91616a9fd077'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1fd7e1f4-bec5-521c-a1c0-91616a9fd077'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e9615926-1650-56c3-b121-7d1076fc59e3'::uuid, NULL, NULL, E'Art depicting freshwater life didn''t appear until the modern era.', NULL, NULL),
  ('1fe35ea0-e21b-5f9e-b15a-1e29dcff3d68'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1fe35ea0-e21b-5f9e-b15a-1e29dcff3d68'::uuid, 1, NULL, TRUE, 0, NULL, E'Decision Fatigue', E'So decision fatigue is when you find yourself literally exhausted by the amount of decisions that you have to make, because we''re constantly inundated by so many different things from so many different channels. All that information requires our attention, and a lot of that information actually requires us to act. And acting on information is essentially making a decision. So do you want to go watch this movie? Do you want to go on this trip? Do you want to respond to this email? Do you? Do you? Do you? Do you? You have to constantly keep asking yourself and you''re making decisions. And over time, the more you allow yourself to be inundated by without taking a step back, the more exhausted you get. It might not be physically. Right. You can make decisions all day long, and you can still run a marathon but our mind also has a limited amount of energy. Your ability to make decisions becomes worse, it can really quickly degrade when you''re...\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '08c80afd-eaf8-5631-9a8e-b60719ed9226'::uuid, NULL, NULL, E'constantly making decisions', NULL, NULL),
  ('1feacb38-4bd5-5eb6-b618-545e3dce6b35'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1feacb38-4bd5-5eb6-b618-545e3dce6b35'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '470a7aee-03a2-5ce7-9fed-47e1d20dd068'::uuid, NULL, E'The most important consideration is that the environment should not be harmed.', NULL, NULL, NULL),
  ('1fecabd5-5cf5-5801-9e0d-311374f5be72'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1fecabd5-5cf5-5801-9e0d-311374f5be72'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'If something that will die one day is mortal; what term will be used for something that never dies?', '9dd76bb5-a5ed-51d2-ba76-ec15aeabffce'::uuid, NULL, NULL, E'Immortal', NULL, NULL),
  ('1fef17bf-9705-57c1-a72b-7a2d31225da2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1fef17bf-9705-57c1-a72b-7a2d31225da2'::uuid, 1, NULL, TRUE, 0, NULL, E'Alphabet', E'The problem begins with the alphabet itself. Building a spelling system for English using letters that come from Latin — despite the two languages not sharing exactly the same set of sounds — is like building a playroom using an IKEA office set.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('1ff1b73d-a546-503f-9c0d-2386ab7334c7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1ff1b73d-a546-503f-9c0d-2386ab7334c7'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'If you want to buy a ring, who do you approach, a jeweler or a pharmacist?', '85ab15e1-6c85-5efc-b27e-dea11045253d'::uuid, NULL, NULL, E'a Jeweler', NULL, NULL),
  ('1ff491b4-8b50-50a6-af2e-0271ab2ace47'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '1ff491b4-8b50-50a6-af2e-0271ab2ace47'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '72162038-b66b-5124-8987-14a079653ebd'::uuid, NULL, E'She likes to drink milky coffee with a lot of sugar every day.', NULL, NULL, NULL),
  ('1ffb155a-9889-561f-86ec-cec3e4404a05'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1ffb155a-9889-561f-86ec-cec3e4404a05'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '00c84671-bef4-598a-a2c0-3ba2c7b2e9dc'::uuid, NULL, NULL, E'Staff at the university will review feedback on evaluation forms.', NULL, NULL),
  ('1ffb610d-737b-5383-9172-7c14ed04d710'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1ffb610d-737b-5383-9172-7c14ed04d710'::uuid, 1, NULL, TRUE, 0, NULL, E'Classic Music', E'Listen to part of a lecture in a music class and answer the questions. What is classical music? Boring music played on the violin? Well, violins are used, but for many people it is far from boring, but you are allowed to have your own opinion about it. The term classical shows where the influence comes from. What do you think classical refers to? Um the Egyptians you are on the right track, but no the greeks the music was influenced by ancient greek and roman ideals of balance proportion and controlled expression. The late baroque style, the one that preceded classical was complex ornamental and rich in its melodies. Composers of the classical era departed from the evolution of their predecessors and composed music that was considerably simpler in texture. During the classical era. Music was composed in such a way that the melody and accompaniment were clearly distinct. Musical experiments were made, and the results completed. The transformation from the baroque era to the classical. The sonata was the most important of these, as well as the most developed. Although baroque composers also wrote sonatas, the classical style of sonata is completely distinct. The classical sonata is based on conflict, maybe between two themes of contrasting character. During the performance of the sonata, the conflict increases or becomes more involved until it is finally resolved. The sonata allowed composers to give solely instrumental pieces a dramatic character or even a personality. All of the main instrumental forms of the classical era, the quartet symphony and concerto were based on the dramatic structure of the sonata. Now that you know more about classical music, you might appreciate it more and not think it is so boring.\n\nAccording to the lecture, which of the following are true?', 'ec588f63-f436-51ec-82f9-2ffe796b00ee'::uuid, NULL, NULL, E'Sonatas can be found both in the Baroque and the classical music.\nThe Classical sonata emphasizes conflict and its resolution.', NULL, NULL),
  ('1ffc5ed0-8e32-5f86-b4c0-0c6e40bdcd91'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '1ffc5ed0-8e32-5f86-b4c0-0c6e40bdcd91'::uuid, 1, NULL, TRUE, 0, NULL, E'Essential Skill(必要技能)', NULL, NULL, NULL, NULL, E'1, 3, 2, 4', NULL, NULL),
  ('1ffd2ed7-8e40-5f16-86b8-757c58f02efc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '1ffd2ed7-8e40-5f16-86b8-757c58f02efc'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '253c3da2-fd27-598d-92e5-8dff2c79d6e6'::uuid, NULL, NULL, E'The delay of the project''s progress has raised many questions.', NULL, NULL),
  ('2009e9d0-3b1a-58ad-91a2-126279bd75f4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '2009e9d0-3b1a-58ad-91a2-126279bd75f4'::uuid, 1, NULL, TRUE, 0, NULL, E'Carbon-neutrality', E'You used to think that being green was a luxury for your company, but climate change has made you realize that you can no longer ignore it. The buzz is about becoming carbon-neutral, but where do you start? Consider your drivers. Do you want to become carbon-neutral for marketing reasons, for financial reasons or to help save the planet? Simon Armitage of the Carbon Neutral Company believes: "Your drivers will help you tailor your carbon-reduction program and determine key performance indicators." This will help build a case for going carbon-neutral. First, measure your carbon footprint, or get a specialist to do it for you. That primarily means taking account of your energy usage and emissions caused through travel. Before you begin, think about whether you''re collecting the right data and whether it''s readily accessible. When implementing any energy reduction measures, ensure you engage with your staff. "It''s much better if your people decide for themselves when it''s sensible for them to travel," says Armitage. You''ll also need them to participate in switching off the lights and other energy-saving measures. Set targets and show it''s not a one-off exercise.', NULL, NULL, E'Drivers will help companies tailor their carbon-reduction program and determine key performance indicators to build a case for going carbon-neutral, for which companies not only need to measure their carbon footprint, but also ensure that they engage with their staff when implementing any energy reduction measures; companies will also need them to set targets and show it''s not a one-off exercise.', NULL, 5, 75),
  ('200b199c-e86a-5e64-839a-9e4217a53738'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '200b199c-e86a-5e64-839a-9e4217a53738'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'df76077c-fd47-5dfa-9c95-61d06ce985a4'::uuid, NULL, E'The website is designed to be highly interactive.', NULL, NULL, NULL),
  ('200c31d4-e6d4-5d43-93fb-cd39b111ef79'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '200c31d4-e6d4-5d43-93fb-cd39b111ef79'::uuid, 1, NULL, TRUE, 0, NULL, E'Barbecue Party', E'You''ve organized a barbecue with your friends at your place. However, upon their arrival, you notice some of your friends are using your kitchen utensils carelessly. You need to remind everyone to handle the utensils with care to maintain their quality and keep ourselves safe. What would you say to your friends?', '8dc6e216-7ebc-59ab-9764-685e92c3a7cf'::uuid, NULL, E'Hey guys, thanks for coming over for the barbecue! Just a quick heads up, let''s be careful with the kitchen utensils to avoid any accidents. I noticed some of them were getting a bit banged up. It''s important to handle them with care to keep them in good shape and prevent any injuries. Let''s enjoy the barbecue safely and make sure we clean up properly afterward. Thanks for understanding!', NULL, NULL, NULL),
  ('2010e743-e66c-5247-b698-98ddded86dff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2010e743-e66c-5247-b698-98ddded86dff'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a200995c-b403-5ba0-a42e-7d5808e096cb'::uuid, NULL, E'Physics explores the properties and interactions of matter and energy.', NULL, NULL, NULL),
  ('20161170-b557-524c-b984-7d79587f8c8a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '20161170-b557-524c-b984-7d79587f8c8a'::uuid, 1, NULL, TRUE, 0, NULL, E'Vaccines and Wildlife', E'The idea of ‘self-disseminating’ vaccines has floated through epidemiological circles for decades, conceived mainly as a tool for protecting the health of wildlife. But evolutionary biologists have refreshed the proposal with evidence from their own modeling and other experimental work, which suggests that self-disseminating vaccines could be a safe and practical way to head off zoonotic pandemics as well.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('2018d50e-175c-5a25-8144-39a6d1ce57b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2018d50e-175c-5a25-8144-39a6d1ce57b2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '69c2f117-6f00-5f98-8472-fc1f99ea93ba'::uuid, NULL, NULL, E'He is looking for an opportunity to present his recent research.', NULL, NULL),
  ('2019af43-47d1-5af3-bef2-24cc0c290990'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2019af43-47d1-5af3-bef2-24cc0c290990'::uuid, 1, NULL, TRUE, 0, NULL, E'Special Birthday', E'Here in Britain, we have been celebrating a birthday. Not the birthday of a person, however, but the birthday of a railway. One hundred and fifty years ago, in January 1863, the first underground railway in the world carried its first passengers. It ran for 6 kilometers from Paddington in London to a place close to the City, which is the name we call London’s main business district. The new railway was controversial and unpopular with many people. The men building the railway dug up the streets and knocked down houses and other buildings. They dug a deep trench and put the railway track at the bottom. Then they covered over the new railway and remade the surface of the street. Not surprisingly, the construction work caused chaos in London for many months.\n\nWhich option below is false according to the speaker?', '32f0cead-8cb0-5e05-8043-d0868d35a8af'::uuid, NULL, NULL, E'People supported the building of the railway.', NULL, NULL),
  ('201b42cb-982a-588f-b8d7-24a1705587eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '201b42cb-982a-588f-b8d7-24a1705587eb'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '36379e37-2c2d-57b6-8854-04c3522e91a0'::uuid, NULL, NULL, E'Before attending the lecture, you must register online or by post.', NULL, NULL),
  ('201cdd68-09af-507f-8adb-f9d58c98aec5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '201cdd68-09af-507f-8adb-f9d58c98aec5'::uuid, 1, NULL, TRUE, 0, NULL, E'Chemical Bonds', E'The hardness of materials is determined by the strength of the chemical bonds that are formed between the electrons of the neighboring atoms. For example, the bonds in diamond are very strong, so it is one of the hardest materials known. The bonding is rooted in the laws of quantum mechanics.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('201fbdb1-2f55-529e-bbe6-fc4efb0e92d4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '201fbdb1-2f55-529e-bbe6-fc4efb0e92d4'::uuid, 1, NULL, TRUE, 0, NULL, E'Chemistry Exam', E'You’re studying for the upcoming chemistry final exam. You understand most topics, but the “organic chemistry reaction mechanisms” still confuse you. Your study partner got an A in last year’s chemistry class. Ask them to explain the key concepts and share their study notes. What would you say?', '296bfd27-83f0-57c3-8116-875cce55c2aa'::uuid, NULL, E'Hey partner, I want to talk to you about something.\nWe seem to have a little issue with my chemistry exam preparation.\nIt''s like I’m reviewing for the coming chemistry final, most topics are clear to me, yet organic chemistry reaction mechanisms are really confusing. You earned an A in chemistry last year, so I hope you can explain its key concepts and share your study notes with me.\nAnd I''d like to know what you think.', NULL, NULL, NULL),
  ('202072cc-b706-57aa-af9c-6d259f0114fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '202072cc-b706-57aa-af9c-6d259f0114fe'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '16cd6b0e-dc4b-5a09-ae65-e4300383091c'::uuid, NULL, NULL, E'It seems really hard to fix this problem easily.', NULL, NULL),
  ('202e5ea7-dc15-5e14-b748-e5bf1fda9512'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '202e5ea7-dc15-5e14-b748-e5bf1fda9512'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '91ca6232-446c-5a4f-a05e-5f1e8ec55b68'::uuid, NULL, NULL, E'Experts say learning and listening to music can reduce the stress.', NULL, NULL),
