  ('2059602e-d87e-5df0-9ad7-9a0ef1d5f958'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '2059602e-d87e-5df0-9ad7-9a0ef1d5f958'::uuid, 1, NULL, TRUE, 0, NULL, E'RO', NULL, NULL, NULL, NULL, E'3, 1, 4, 2', NULL, NULL),
  ('20599e18-250c-5632-a076-f8f3fcb9369d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '20599e18-250c-5632-a076-f8f3fcb9369d'::uuid, 1, NULL, TRUE, 0, NULL, E'Reactome', E'The pharmaceutical industry is witnessing a significant leap in innovation with the development of an AI-powered platform known as the ''reactome''. Developed {{1}} by Cambridge and Pfizer, this technology is revolutionizing the process of drug design by accurately {{2}} chemical reactions. This advancement streamlines the pharmaceutical development process, making it more efficient and potentially speeding up the availability of new drugs. The integration of AI into drug design marks a major shift in how pharmaceuticals are developed, offering a more precise and faster {{3}} to discovering new treatments. This could lead to breakthroughs in medicine, especially for complex diseases that have been challenging to treat. As the pharmaceutical industry {{4}} this new technology, it holds the promise of enhancing healthcare and treatment options globally.', NULL, NULL, NULL, E'1.jointly, 2.predicting, 3.route, 4.embraces', NULL, NULL),
  ('205c3d68-88ab-54bd-b765-5da4076405f3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '205c3d68-88ab-54bd-b765-5da4076405f3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f11708ea-45aa-52fc-a120-eb0069fcd67f'::uuid, NULL, E'We were all disappointed to learn that the picnic had been cancelled.', NULL, NULL, NULL),
