  ('208f45fe-0969-5e11-9c33-98170cd7d652'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '208f45fe-0969-5e11-9c33-98170cd7d652'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'da1e8647-f431-55ec-963d-a025981f3d7b'::uuid, NULL, NULL, E'You may find it useful to view the photographs.', NULL, NULL),
  ('2097b7e5-eb6b-5e5b-a39b-3e7e425d8568'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '2097b7e5-eb6b-5e5b-a39b-3e7e425d8568'::uuid, 1, NULL, TRUE, 0, NULL, E'Questions', E'You have about 30 minutes to answer each question. You must take account of how many marks are {{1}} for each part when you answer it. Even if you think you can write more, don''t spend 15 minutes {{2}} a part worth only 5 marks. {{3}} a space at the end of your answer and come back to it if you have {{4}} to spare later.\nAnd if you can''t think of an answer to some part, leave a space and move on to the next part. Don''t write about something else if you don''t know the correct answer — this is just a waste of your {{5}} time (and the examiner''s).', NULL, NULL, NULL, E'1.available, 2.answering, 3.Leave, 4.time, 5.valuable', NULL, NULL),
