  ('20af4136-f3d6-5773-b476-fce4cfd242fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '20af4136-f3d6-5773-b476-fce4cfd242fb'::uuid, 1, NULL, TRUE, 0, NULL, E'Bikes', E'In 2015, the owners of a Dutch cycling company began shipping bicycles across the Atlantic to the United States, but time and time again these deliveries were damaged in {{1}} . VanMoof {{2}} various solutions — Tougher boxes? Better packaging? Different shipping partners? Nothing worked. Bikes obviously didn’t have the kind of priority flat-screen TVs have, for example and then it clicked. The company began printing images of big, expensive television sets on the sides of boxes as a visual {{3}} to handlers, a tacit message that the contents were fragile. They reported this “small tweak had an outsized {{4}} ,” with shipment damage dropping by 70 to 80% overnight. Since most of their sales are online, this strategy has helped them better protect tens of thousands of orders to date.', NULL, NULL, NULL, E'1.transit, 2.experimented, 3.cue, 4.impact', NULL, NULL),
  ('20b10a9a-d412-542c-8506-2a6bf5d34a3d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '20b10a9a-d412-542c-8506-2a6bf5d34a3d'::uuid, 1, NULL, TRUE, 0, NULL, E'IQ Tests', E'Studies show that children who learn music often achieve higher average IQ scores. {{1}} , while Mozart is often associated with claims of higher intelligence, there is a lack of scientific evidence from proper {{2}} to fully support this. The key {{3}} in such research involved six-year-old children who learned music lessons and displayed an IQ gain of 3.2 points, and some even {{4}} an increase of 7.1 points. Scientists also note that people who prefer heavy food often think it is more satisfying than {{5}} food, and people sometimes have the {{6}} that light drinks such as wine are healthier. This psychological {{7}} of perception influences lifestyle choices just as much as {{8}} IQ does.', NULL, NULL, NULL, E'1.However, 2.tests, 3.process, 4.exhibited, 5.lighter, 6.illusion, 7.feature, 8.measured', NULL, NULL),
  ('20b3d89a-f916-5c34-8aa4-c585240b2328'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '20b3d89a-f916-5c34-8aa4-c585240b2328'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'be37b347-a4a2-5341-97e9-774d1ab4f1af'::uuid, NULL, NULL, E'The career center offers career advising by experts from different fields.', NULL, NULL),
