  ('20f8cc1e-6594-5156-9867-8993ce3659f5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '20f8cc1e-6594-5156-9867-8993ce3659f5'::uuid, 1, NULL, TRUE, 0, NULL, E'Children and Books', E'Books introduce children to social life and provide them with the opportunity to {{1}} their imaginary worlds. Preschool children are influenced by books more than adults. Children can {{2}} themselves with the heroes in the books and choose to act like them. Therefore, the {{3}} of the heroes in the intended message of the story have significant importance in {{4}} of children’s development.', NULL, NULL, NULL, E'1.expand, 2.identify, 3.features, 4.terms', NULL, NULL),
  ('210183ab-3c0d-5930-82d0-1c87e8ba37d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '210183ab-3c0d-5930-82d0-1c87e8ba37d7'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call an experienced person who advises and helps less experienced people especially at work?', '5b974f06-5623-5010-99e4-7f353b7f9843'::uuid, NULL, NULL, E'Mentor', NULL, NULL),
  ('2101ed14-be38-5cf9-8961-6493797fa973'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '2101ed14-be38-5cf9-8961-6493797fa973'::uuid, 1, NULL, TRUE, 0, NULL, E'Brainpower', E'You may have heard that humans only use 10 percent of their brain power, and that if you could {{1}} the rest of your brainpower, you could do so much more. You could become a super genius, or acquire psychic powers like mind reading and telekinesis. However, there is a powerful body of evidence {{2}} the 10 percent myth. Scientists have consistently shown that humans use their entire brain throughout each day. Despite the evidence, the 10 percent myth has inspired many references in the cultural imagination. Films like "Limitless" and "Lucy" {{3}} protagonists who develop godlike powers thanks to drugs that unlock the previously {{4}} 90 percent of the brain. A 2013 study showed that about 65 percent of Americans believe the trope, and a 1998 study showed that a full third of psychology majors, who focus on the workings of the brain, fell for it.', NULL, NULL, NULL, E'1.unleash, 2.debunking, 3.depict, 4.inaccessible', NULL, NULL),
  ('2103931e-e1d7-5bf1-ad8f-7da8785a7120'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2103931e-e1d7-5bf1-ad8f-7da8785a7120'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e72967ee-0552-5eea-8d60-bd711e11ec7a'::uuid, NULL, E'A company exists for profit, not for societal benefit.', NULL, NULL, NULL),
  ('210730bd-68c4-51d7-92c8-4f9bc465ca02'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '210730bd-68c4-51d7-92c8-4f9bc465ca02'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'cbe6d106-e5c9-50d3-8e5c-b658f4af37da'::uuid, NULL, E'Our online digital modules are suited to a diverse audience.', NULL, NULL, NULL),
  ('21084d9f-c0a9-575a-9a10-8e3fd6031994'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '21084d9f-c0a9-575a-9a10-8e3fd6031994'::uuid, 1, NULL, TRUE, 0, NULL, E'Studying Theater', E'What are the problems and the benefits for high school students of studying plays and other works for theatre that were written centuries ago? Use your own experience to discuss it.', NULL, NULL, E'Studying plays and other works for theatre that were written centuries ago can be a challenging but rewarding experience for high school students. While there are both benefits and problems associated with this type of learning, it is important to consider both sides.\nOn the one hand, studying these works can provide a historical perspective on the evolution of theatre and culture. Students can gain insight into the cultural and social norms of different periods in history. For instance, reading Shakespeare''s plays can provide a glimpse into Elizabethan England and the cultural values of that era. This can help students develop a deeper understanding of history and culture.\nOn the other hand, the language used in these plays can be difficult for students to understand, making it harder for them to engage with the material. The themes and values expressed in these plays may not align with modern sensibilities, leading to potential discomfort or conflict for students. It may also be difficult for students to relate to characters and situations in these plays, given the vast differences in historical context and societal norms.\nIn conclusion, while there are both benefits and problems associated with studying plays and other works for theatre that were written centuries ago, it is important for high school curriculums to include these works in their syllabus. By gaining a historical perspective and developing critical thinking skills, students can broaden their horizons and become more well-rounded individuals. However, it is also important for teachers to be aware of the potential challenges associated with this type of learning and to provide appropriate support for their students.', NULL, 200, 300),
  ('21090200-d62a-57ba-bc38-9a4e8c8aa8a4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '21090200-d62a-57ba-bc38-9a4e8c8aa8a4'::uuid, 1, NULL, TRUE, 0, NULL, E'Student Exchange Program', E'A student exchange program complements formal education, while promoting tolerance, maturity and independence – all highly sought after qualities in today’s competitive job market. Living in the host country, not as a tourist or guest but as a member of the community, is what makes the experience both challenging and rewarding.', NULL, NULL, NULL, NULL, NULL, NULL),
