  ('21784196-c1e0-5184-b735-eacf3f0344af'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '21784196-c1e0-5184-b735-eacf3f0344af'::uuid, 1, NULL, TRUE, 0, NULL, E'Palaeontology', E'The outsize influence of rich countries on paleontology could lead to a warped view of life''s history, the researchers say. Researchers studying large-scale trends in paleontology using resources are keenly aware that the fossil record is biased in myriad ways, including the age and type of rock in which fossils survive. But little consideration is given to the biases of the collectors themselves.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('21803e78-280a-50ad-83a3-70cb0b00a67c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '21803e78-280a-50ad-83a3-70cb0b00a67c'::uuid, 1, NULL, TRUE, 0, NULL, E'Children Learning Crisis', NULL, NULL, NULL, NULL, E'3, 4, 1, 2', NULL, NULL),
  ('218093f4-96fc-506e-b497-2fb1e32a4876'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '218093f4-96fc-506e-b497-2fb1e32a4876'::uuid, 1, NULL, TRUE, 0, NULL, E'Blame', E'There are two main ways that have been proposed to {{1}} blame. The first method comes from political science and law. A recent paper with seven studies and agent-based modeling suggested that the best thing to do to reduce blame is to focus on {{2}} as many people as possible on success, and blame as narrowly as possible after failure. In the {{3}} of COVID-19, this would mean focusing as much as possible on the people who have done the right thing and the successes along the way, and blame should be used extremely rarely to meet judgment on very narrow targets (e.g., a failed health minister who {{4}} social norms for his own gain). This method, in Path Based Model of blame, would work by changing when blame is used.', NULL, NULL, NULL, E'1.reduce, 2.praising, 3.context, 4.violated', NULL, NULL),
  ('2183c0fd-8bac-5637-a40d-da14d80ef74e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2183c0fd-8bac-5637-a40d-da14d80ef74e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '45e356a1-3998-549f-a406-ed2f764371e4'::uuid, NULL, NULL, E'Open days for undergraduates occur all year round for campus visits.', NULL, NULL),
  ('21840c39-f650-5c96-89db-eb037504fa5b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '21840c39-f650-5c96-89db-eb037504fa5b'::uuid, 1, NULL, TRUE, 0, NULL, E'Cartoonists', NULL, '70c6abc0-71d8-5974-b62e-8226091c13cd'::uuid, NULL, E'Cartoonists are like sponges; they soak up people, places, mannerisms, clothing, and behavior. Sometimes they might jot them down in a little black book that they carry around with them. Other times, it is just soaked up into the cartoonist’s brain only to be squeezed out later when she is sitting at her drawing table. Not only does a cartoonist have to be aware of what she is seeing visually, but she has to listen to herself think. In other words, take the incoming information and select it, shape it, and then use it for a cartoon. Now that you have an idea, or something you think could be good for a cartoon, it’s time to shape it. A cartoon is like a staged play. A cartoonist is playwright, director, stage designer, choreographer, and costume designer. A cartoon has characters, a set, dialogue, even if one line, and a backstory. The characters must be dressed to fit the idea, speak in a way that is natural and forwards the idea or gives the punchline. Nothing should be in the cartoon that is not absolutely necessary for the advancement of the idea. The image and words have to dance together in a way that makes sense. It could be a graceful dance, or an awkward dance, if that is part of the humor or idea. And then the execution. Some cartoonists sketch the idea with pencil then ink it with pen using a light box. Others visualize the image in their head and draw directly on the paper in pen.', NULL, NULL, NULL),
  ('2185d48c-fdc2-57df-84b5-3869f9826533'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2185d48c-fdc2-57df-84b5-3869f9826533'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '95533315-ee68-597d-8a07-562c3fee426d'::uuid, NULL, NULL, E'Weather patterns have changed significantly over the past two hundred years.', NULL, NULL),
