  ('21a2bb09-f2a8-5142-b588-abab4f30c4ce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '21a2bb09-f2a8-5142-b588-abab4f30c4ce'::uuid, 1, NULL, TRUE, 0, NULL, E'Plants’ Nutrients', E'Plants have essential nutrients that help keep your cells healthy and your body in balance so that your immune system can {{1}} at its best. A healthy immune system is essential for reducing your risk for cancer because it can recognize and attack mutations in cells before they can {{2}} to disease. Plants’ essential nutrients also help {{3}} inflammation in your body.', NULL, NULL, NULL, E'1.function, 2.progress, 3.resolve', NULL, NULL),
  ('21a659bd-1905-57b9-afc9-e192f5ad310e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '21a659bd-1905-57b9-afc9-e192f5ad310e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0babe6ad-8885-5dc3-bc84-733d51bc8d8b'::uuid, NULL, NULL, E'All companies must have regular independent financial auditing.', NULL, NULL),
  ('21a8cf6f-196f-5038-9ab8-eb03f3b033ec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '21a8cf6f-196f-5038-9ab8-eb03f3b033ec'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '1feb5f9d-2c7b-5123-9c46-956761e355b7'::uuid, NULL, E'Union leaders will meet tomorrow in an attempt to reach a settlement.', NULL, NULL, NULL),
  ('21aac136-b72c-513e-9cb5-15905abcb193'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '21aac136-b72c-513e-9cb5-15905abcb193'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '48f28606-09a0-5ad5-a953-bedb24c630a9'::uuid, NULL, NULL, E'Sentencing decisions hinge on the adjudicated guilt of the accused.', NULL, NULL),
  ('21b2ccde-0af1-5bed-8dee-094af5e95b2b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '21b2ccde-0af1-5bed-8dee-094af5e95b2b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ba4bdd2d-9f56-5612-b1cb-61f88cc0e58b'::uuid, NULL, E'This is how we deliver health care to millions of people over the world.', NULL, NULL, NULL),
  ('21b66b2e-bb5f-54f5-88f2-39832982cca7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '21b66b2e-bb5f-54f5-88f2-39832982cca7'::uuid, 1, NULL, TRUE, 0, NULL, E'Cancer Cells', NULL, 'f1f9510b-a763-5051-adae-7d5e923d1b76'::uuid, NULL, E'Cell division is an intricate chemical dance that’s part individual, part community-driven. And in a neighborhood of 100 trillion cells, some times things go wrong. Maybe an individual cell’s set of instructions, or DNA, gets a typo, what we call a mutation. Most of the time, the cell senses mistakes and shuts itself down, or the system detects a troublemaker and eliminates it. But, enough mutations can bypass the fail-safes, driving the cell to divide recklessly. That one rogue cell becomes two, then four, then eight. At every stage, the incorrect instructions are passed along to the cells’ offspring. Weeks, months, or years after that one rogue cell transformed, you might see your doctor about a lump in your breast. Difficulty going to the bathroom could reveal a problem in your intestine, prostate, or bladder. Or, a routine blood test might count too many white cells or elevated liver enzymes. Your doctor delivers the bad news: it’s cancer.', NULL, NULL, NULL),
  ('21b6caa5-9d79-5469-88cb-c7d878986c26'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '21b6caa5-9d79-5469-88cb-c7d878986c26'::uuid, 1, NULL, TRUE, 0, NULL, E'Rachel Carson', NULL, 'bbb0ae81-b319-5585-911b-f8fd39e9ea10'::uuid, NULL, E'Today, I''m honored to discuss the enduring legacy of Rachel Carson, a pioneering environmentalist whose work sparked a global environmental movement. Her groundbreaking book, "Silent Spring", published in 1962, played a pivotal role in raising public awareness about environmental issues and the impact of human activities on the natural world. Rachel Carson''s meticulous research and eloquent writing in "Silent Spring" exposed the dangers of indiscriminate pesticide use, particularly DDT, and its devastating effects on wildlife and ecosystems. Her work challenged the practices of agricultural scientists and the government, prompting a nationwide debate on environmental policy and public health. Carson''s advocacy led to a shift in national pesticide policy and laid the foundation for the modern environmental movement. Her efforts contributed to the creation of the U.S. Environmental Protection Agency and the eventual ban of DDT in the United States. Her legacy extends beyond environmental policy; she inspired generations to appreciate the interconnectedness of all living things and the importance of conserving the natural world. Rachel Carson''s work reminds us of the power of informed, passionate advocacy in effecting change. In conclusion, Rachel Carson''s life and work continue to be a beacon of inspiration, emphasizing the importance of environmental stewardship and the responsibility we bear towards our planet.', NULL, NULL, NULL),
  ('21bc0fff-c93f-5f64-acd2-fc99cb71a89a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '21bc0fff-c93f-5f64-acd2-fc99cb71a89a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What planet is known for its rings?', 'a800b5a2-4720-54a2-aa7f-f9d014c830dc'::uuid, NULL, NULL, E'Saturn', NULL, NULL),
  ('21bce349-9767-5101-9370-23fbbee91e5b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '21bce349-9767-5101-9370-23fbbee91e5b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '947f3de1-4ec1-52ce-80a9-eadfc3661597'::uuid, NULL, E'Some methods for clinical applications have been presented as well.', NULL, NULL, NULL),
  ('21be0736-a106-5600-9b5b-09dae82b2418'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '21be0736-a106-5600-9b5b-09dae82b2418'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e3bd1ca3-592a-5853-8b30-e2f3d6814582'::uuid, NULL, NULL, E'A wide range of courses covered different aspects in this subject.', NULL, NULL),
  ('21bee9e0-4b69-55db-a806-3e14d03c8635'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '21bee9e0-4b69-55db-a806-3e14d03c8635'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5dec9647-cfd7-5df1-92c8-5e6583872b12'::uuid, NULL, E'There will be a guest lecturer visiting the psychology department next month.', NULL, NULL, NULL),
  ('21c74503-4393-5684-90fa-d667171ab58c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '21c74503-4393-5684-90fa-d667171ab58c'::uuid, 1, NULL, TRUE, 0, NULL, E'Human Evolution', NULL, 'f4090f9d-6ced-57a4-a277-42c53db14215'::uuid, NULL, E'Well, if there are no more questions, I would like to continue our discussion of human evolution by looking at Homo erectus, the earliest of our ancestors who stood upright. Homo erectus lived about one and a half million years ago and was given that name because, at the time the first fossil was discovered, it represented the first primate to stand upright. There is evidence now that Homo erectus had sharper mental skills than their predecessors. They constructed the first standardized tool for hunting and butchering. They created an extraordinary stone implement, a large teardrop-shaped hand ax whose design and symmetry reveal a keen sense of aesthetics. This detailing, along with the ax''s utilitarian value, strongly suggests that Homo erectus had the ability to conceive of and execute a design to specification. In addition, Homo erectus was the first hominid to use fire. This discovery enticed them to cook meat, which they could flavor and keep from spilling by flame, and which paleontologists now believe may have given them a new disease. Some fossil bones of Homo erectus are grossly deformed, and paleontologists have noted that this condition is similar to that found in people today who have been exposed to chronic overdoses of vitamin A. Apparently Homo erectus first got this disease by eating large amounts of animal liver.', NULL, NULL, NULL),
  ('21ca56f6-52fd-5171-8277-5dc7c42f5f25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '21ca56f6-52fd-5171-8277-5dc7c42f5f25'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '39eae8b8-ee05-53f3-96f9-7de582402ff3'::uuid, NULL, NULL, E'At that time, few people moved from the town to the village.', NULL, NULL),
  ('21ca8351-50f6-5043-8a89-5ef70a6bcba8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '21ca8351-50f6-5043-8a89-5ef70a6bcba8'::uuid, 1, NULL, TRUE, 0, NULL, E'Travel Apps', NULL, NULL, NULL, NULL, E'4, 1, 3, 2', NULL, NULL),
  ('21cdc998-fe69-5cbb-9485-9f427034194a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '21cdc998-fe69-5cbb-9485-9f427034194a'::uuid, 1, NULL, TRUE, 0, NULL, E'Novel Device', E'A novel invention for helping farmers to dry out hay more quickly has won a University of Glasgow graduate a prestigious design award.Gavin Armstrong, 23, from Kippen, Stirlingshire {{1}} the Glasgow 1999 Design Medal for his design for a swath inverter— a {{2}} for flipping over a hay crop to help dry out the damp underside. Dry hay is an essential farmyard food source for sheep and cows. Gavin came up with the design as part of his Product Design Engineering degree course, run in {{3}} with Glasgow School of Art. He built a working prototype of the device which is powered and towed by a tractor and uses a pair of parallel belts to invert the swath. The rollers are driven from one hydraulic motor and are geared so as to spin at the same speed and in opposite directions {{4}} that the touching inner two faces of the belt that perform the inversion move rearwards at the same speed.', NULL, NULL, NULL, E'1.scooped, 2.device, 3.conjunction, 4.ensuring', NULL, NULL),
  ('21cdecd6-eef8-5d38-a288-a97de03e46a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '21cdecd6-eef8-5d38-a288-a97de03e46a6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c658e582-dc92-51a3-9078-6a2526f1e6a5'::uuid, NULL, E'Not everyone wants to keep in touch with their old school friends when they leave school, but I would like to.', NULL, NULL, NULL),
  ('21d17fcb-ef3d-580b-8597-7149fb74f400'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '21d17fcb-ef3d-580b-8597-7149fb74f400'::uuid, 1, NULL, TRUE, 0, NULL, E'Phthalates', E'Three types of phthalates, {{1}} additives that render hard plastics flexible, will be banned from children''s toys and child-care products starting Feb 10, while three other types of phthalates will be temporarily {{2}} from child-care products and toys that can be placed in a child''s mouth. Consumer {{3}} complain that the law has ended up sanctioning a grace period that allows toy makers to sell off soon-to-be banned toys, rather than forcing them to {{4}} of them.', NULL, NULL, NULL, E'1.chemical, 2.prohibited, 3.advocates, 4.dispose', NULL, NULL),
  ('21d4ed52-0f0b-504e-bacf-5e11f1615e4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '21d4ed52-0f0b-504e-bacf-5e11f1615e4b'::uuid, 1, NULL, TRUE, 0, NULL, E'Ethical Dilemma', NULL, 'ae42dbc8-585f-5b33-b2c7-974a272c4f21'::uuid, NULL, E'Animals have been used in research aimed at improving human welfare for centuries, typically at the cost of their lives. This practice reflects the widespread belief that human lives are more valuable than non-human lives. People have different views about the ethics of animal testing and how it’s conducted. But whatever your opinion, this scenario raises an important philosophical question: how do we determine the value of a life, whether human or non-human? One tool philosophers have used to consider this question is moral status. Beings with moral status should have their needs and interests taken into consideration by those making decisions that impact them. Traditionally, moral status has been seen as binary, either a being’s interests matter for their own sake, or they don’t. And historically, many philosophers believed that humans had moral status and other animals didn’t. Some contemporary philosophers like Shelly Kagan have argued that moral status comes in degrees, but even in this model, he argues that people have the most moral status. However, determining what grants any degree of moral status can be difficult. Enlightenment philosopher Immanuel Kant thought humans have moral status because of their rational nature and ability to will their actions. A binary conception of moral status then suggests that beings with these capacities are “persons” bearing full moral status, while all other creatures are “things” without moral status. But thinkers like Christine Korsgaard have argued a Kantian view should include many non-human animals because of how they value their own good.', NULL, NULL, NULL),
  ('21db2314-41df-5f4b-a1a8-2c74e9085bcf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '21db2314-41df-5f4b-a1a8-2c74e9085bcf'::uuid, 1, NULL, TRUE, 0, NULL, E'Hip Pop', NULL, NULL, NULL, NULL, E'1, 3, 2, 4', NULL, NULL),
  ('21e0b157-fd9c-5a64-b56c-077f2cf5fd44'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '21e0b157-fd9c-5a64-b56c-077f2cf5fd44'::uuid, 1, NULL, TRUE, 0, NULL, E'Air Pollution', E'The only way to reduce air pollution is to increase the prices of fuels for vehicles. What is your opinion and explain with your own experiences and examples.', NULL, NULL, NULL, NULL, 200, 300),
  ('21e334bd-302f-5695-96e6-51f8b01df929'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '21e334bd-302f-5695-96e6-51f8b01df929'::uuid, 1, NULL, TRUE, 0, NULL, E'Train Route', E'Your friend is planning to work far from their home and is considering driving. However, you believe taking the train could be a more convenient option because driving to work may cause you to get stuck in traffic, while taking the train is not only cheaper but also gives you time to do other things. How would you recommend the train as the better choice?', '5cc9d25e-e874-5b1e-8b21-4b455fba5991'::uuid, NULL, E'Hey buddy, I want to talk to you about something.\nWe seem to have a little issue with your travel choice for the far trip.\nIt''s like you''re hesitating between driving and taking the train, and I think the train is much more convenient. You can avoid traffic jams and tiring long-distance driving, and you can relax or enjoy the scenery during the whole ride. Finally, taking the train is cheaper.\nAnd I''d like to know what you think.', NULL, NULL, NULL),
  ('21e551af-f972-5f35-844c-fea376beb1d0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '21e551af-f972-5f35-844c-fea376beb1d0'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which word is more related to peasants, industry or agriculture?', '9ce8d5c2-0807-54bf-9c79-ae0179976e7f'::uuid, NULL, NULL, E'Agriculture', NULL, NULL),
  ('21f89210-1d55-5cad-ac62-156c56100be1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '21f89210-1d55-5cad-ac62-156c56100be1'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'fb3b0029-85e2-5139-93b3-1ed13aa54123'::uuid, NULL, E'This article covers the who, where, and when of the conflict.', NULL, NULL, NULL),
  ('2209e7c3-8aef-515a-9468-ba5680d873cb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2209e7c3-8aef-515a-9468-ba5680d873cb'::uuid, 1, NULL, TRUE, 0, NULL, E'Car Brakes', E'A car''s brakes are one of its most important safety features and generally come in one of two types: disc or drum. Disc brakes use a spinning disc, which is pinched between brake pads mounted on calipers to slow the motion of the car. Drum brakes, on the other hand, use shoes that push outward to contact the inside of a spinning cylinder.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('220a11df-c780-5d5d-b1af-89b1c84fea80'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '220a11df-c780-5d5d-b1af-89b1c84fea80'::uuid, 1, NULL, TRUE, 0, NULL, E'Shuttle', E'The shuttle was designed to be a space truck; it''s a multi-purpose vehicle. We''ve done a tremendous number of different things with it. It''s the most versatile space vehicle that has ever been built. We''ve used it to launch satellites. We''ve used it to repair satellites in orbit and put them back into orbit. We''ve used it to capture satellites and bring them back to Earth for repair.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('220d9b1c-afb6-528b-a2c2-4491d4050330'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '220d9b1c-afb6-528b-a2c2-4491d4050330'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0989aff7-ccf6-5264-be68-d86a2a2a0fa3'::uuid, NULL, E'Students are held accountable for adhering to established community standards.', NULL, NULL, NULL),
  ('22167205-66f9-51c9-894b-adebe1b875b5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '22167205-66f9-51c9-894b-adebe1b875b5'::uuid, 1, NULL, TRUE, 0, NULL, E'Babies', E'How can you tell the difference between a French baby and a German baby? No, it''s not that one is wearing a saucy little beret while the other is tucked into tiny pair of lederhosen. Well, maybe that''s part of it. But a new study in the journal Current Biology shows that the babies actually sound different. Because the melody of an infant''s cry matches its mother tongue.\nWe all know that babies start {{1}} while they''re still in the womb. So when they come out, they know their mother''s voice. When they''re older, they start to imitate the sounds they hear. Eventually they babble, and then start to speak, and then you never hear the end of it. But long before that first burble or coo, babies are learning the {{2}} of language.\nA team of scientists recorded the cries of 60 {{3}} : 30 born into {{4}} families and 30 that heard German. And they found that French infants wail on a rising note while the Germans favor a falling melody . Those {{5}} match the rhythms of their native languages. So next time you hear a baby cry, listen closely. He could be telling you where he''s from.', NULL, NULL, NULL, E'1.eavesdropping, 2.elements, 3.newborns, 4.French-speaking, 5.patterns', NULL, NULL),
  ('2216830d-6d10-591b-b00c-3d3b14fffd36'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2216830d-6d10-591b-b00c-3d3b14fffd36'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '201c927e-151e-5f7e-82b5-91c4f8b7a249'::uuid, NULL, E'Students will need to be in the lecture this Thursday.', NULL, NULL, NULL),
  ('221abb93-60c8-58da-b0e5-e49559b4c89d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '221abb93-60c8-58da-b0e5-e49559b4c89d'::uuid, 1, NULL, TRUE, 0, NULL, E'Television', E'Television is bound to have tremendous impact on a child. When a parent is concerned about the effects of television, he should consider a number of things: what TV offers the child in terms of information and knowledge, how many hours a week a youngster his age should watch television, the impact of violence and sex, and the influence of commercials.', NULL, NULL, NULL, NULL, NULL, NULL),
