  ('22387de3-9ece-5cdb-825e-6ea6442670af'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '22387de3-9ece-5cdb-825e-6ea6442670af'::uuid, 1, NULL, TRUE, 0, NULL, E'Breton Language', E'It is difficult to tell precisely when the Breton language was born. As early as the VIth century the new country was {{1}} and known as ''Lesser Britain'', but for many centuries its language {{2}} close to the one of Great Britain''s- very close even to the dialect spoken in the South West. The VIIIth century is the milestone where Breton, Cornish and Welsh are {{3}} as different languages.', NULL, NULL, NULL, E'1.established, 2.remained, 3.considered', NULL, NULL),
