  ('229987cd-e0cf-513c-82c2-087e18d3314d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '229987cd-e0cf-513c-82c2-087e18d3314d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Where do we catch a flight?', '80552b86-57f5-5eac-a2b3-bd91ea47eed5'::uuid, NULL, NULL, E'Airport', NULL, NULL),
  ('229cbd1a-d22d-5998-8abb-fa1d499dcfae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '229cbd1a-d22d-5998-8abb-fa1d499dcfae'::uuid, 1, NULL, TRUE, 0, NULL, E'Astronomers', NULL, 'd150865e-cb06-5bf1-a845-8d6028c515bc'::uuid, NULL, E'Most people think of astronomers as people who spend their time in cold observatories peering through telescopes every night. In fact, a typical astronomer spends most of his or her time analyzing data and may only be at the telescope a few weeks of the year. Some astronomers work on purely theoretical problems and never use a telescope at all. You might not know how rarely images are viewed directly through telescopes. The most common way to observe the skies is to photograph them. The process is very simple. First, a photographic plate is coated with a light-sensitive material. The plate is positioned so that the image received by the telescope is recorded on it. Then the image can be developed, enlarged, and published so that many people can study it. Because most astronomical objects are very remote, the light we receive from them is rather feeble. But by using a telescope as a camera, long time exposures can be made. In this way, objects can be photographed that are a hundred times too faint to be seen by just looking through a telescope.', NULL, NULL, NULL),
  ('22a0c785-ea66-5823-b3c1-861e7a47f049'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '22a0c785-ea66-5823-b3c1-861e7a47f049'::uuid, 1, NULL, TRUE, 0, NULL, E'Internet of Things', NULL, NULL, NULL, NULL, E'1, 4, 2, 3', NULL, NULL),
  ('22a20c47-4da4-565e-999f-e2cd3ab8916b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '22a20c47-4da4-565e-999f-e2cd3ab8916b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd0768673-e6f7-5019-a3d5-bd7547b445cb'::uuid, NULL, E'More females than males graduated from universities last year.', NULL, NULL, NULL),
  ('22a55cfd-82b5-5fd2-9abe-1ef5ef778637'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '22a55cfd-82b5-5fd2-9abe-1ef5ef778637'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e4d06d9d-046d-5c5f-a808-d6bcf058ca58'::uuid, NULL, E'People form into teams to achieve goals which are beyond the reach of an individual.', NULL, NULL, NULL),
  ('22aca356-4788-51ab-b0e5-b61136050cfa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '22aca356-4788-51ab-b0e5-b61136050cfa'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '02c80fa9-f716-58b4-a094-f3ab7965d17e'::uuid, NULL, NULL, E'The graduate student has made a contract with a technology company.', NULL, NULL),
  ('22b00d22-833e-5265-9332-944f8bc5b37e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '22b00d22-833e-5265-9332-944f8bc5b37e'::uuid, 1, NULL, TRUE, 0, NULL, E'Birth Cauls', E'With less than one in every 80,000 babies born with a caul, it comes as no surprise that superstitions and stories surround this mysterious and rare phenomenon. Believed to be the mark of something special, a birth caul may appear startling and sometimes frightening for the mother, but the majority of the time, it''s just a minor and harmless part of the birth process.\nA birth caul is a piece of the amniotic sac still attached to a newly born baby''s head or face. In extremely rare cases, a baby emerges fully inside the amniotic sac, which looks like a thin and filmy membrane. Some call this condition "born with a veil." A caul happens when a piece of the sac breaks away during gestation or during the birthing process and attaches itself to the baby''s head. The doctor or midwife simply peels away the caul without issue, although in rare cases, if the caul is tightly adhered to the baby''s head, they must take great care not to tear the baby''s skin.\nMany cultures consider a baby born with a caul a sign of good luck. Chances are this belief comes from the rarity of the condition, but many fascinating stories about birth cauls abound throughout history. In Belgium, the child would be lucky only if the caul was buried in a field. Coal miners would carry cauls with them to ward off fires and explosions.', NULL, NULL, NULL, NULL, 5, 75),
  ('22b36c17-41a0-5a6b-952f-f5362a5800ec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '22b36c17-41a0-5a6b-952f-f5362a5800ec'::uuid, 1, NULL, TRUE, 0, NULL, E'Restoration Efforts', E'The Old Town Restoration has successfully preserved the architectural heritage of the city''s most {{1}} district. Through meticulous restoration work, conservationists have saved {{2}} buildings from decay. These efforts have not only revitalized the area but also attracted tourists {{3}} to experience its timeless charm.', NULL, NULL, NULL, E'1.historic, 2.numerous, 3.eager', NULL, NULL),
  ('22b48263-ee1d-5053-b828-c9c6422363d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '22b48263-ee1d-5053-b828-c9c6422363d5'::uuid, 1, NULL, TRUE, 0, NULL, E'Hundred Years'' War', NULL, NULL, NULL, NULL, E'4, 2, 1, 3', NULL, NULL),
  ('22c61cc2-4a93-55a8-8a20-97c435d5b30b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '22c61cc2-4a93-55a8-8a20-97c435d5b30b'::uuid, 1, NULL, TRUE, 0, NULL, E'Economic Inequality', E'For the past thirty years, the United States has been {{1}} what one observer (Samuelson 2001) has called a massive social experiment regarding the political and social consequences of increasing economic inequality. The share of national income going to families in the bottom 40 percent of the income distribution {{2}} by about one-fifth, from 17.4% in 1973 to 13.9% in 2001, while the share going to families in the top 5 percent increased by more than one-third, from 15.5% to 21.0% (Mishel, Bernstein, and Boushey 2003). And {{3}} ,the share of income going to the top one-tenth of one percent quadrupled between 1970 and 1998, leaving the 13,000 richest families in America with almost as much income as the 20 million poorest families (Krugman 2002). The economic causes of technological change, demography and global competition are a matter of some scholarly controversy. But the important political point is that, whereas most rich democracies have significantly mitigated increasing economic inequality through government action, the United States has mostly been content to let economic trends take their course, doing less than almost any other rich democracy to {{4}} economic inequality through employment and wage policies, taxes, and transfers.', NULL, NULL, NULL, E'1.conducting, 2.declined, 3.meanwhile, 4.limit', NULL, NULL),
  ('22c9f5aa-412c-54aa-aabf-b5149432c37c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '22c9f5aa-412c-54aa-aabf-b5149432c37c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f838bb7d-79a3-5a7d-bc0f-e839843a7b11'::uuid, NULL, E'I feel that not enough is being done to protect the local animal life.', NULL, NULL, NULL),
  ('22cc2c73-d975-5f2f-ab6c-9d3f99a59e31'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '22cc2c73-d975-5f2f-ab6c-9d3f99a59e31'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for the study of birds?', '853d989d-324c-5134-93ad-8d11e6731f18'::uuid, NULL, NULL, E'Ornithology', NULL, NULL),
  ('22cdf33f-7ec4-546e-a83f-2f4c17a49e56'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '22cdf33f-7ec4-546e-a83f-2f4c17a49e56'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Tomorrow’s lecture has been cancelled. If today is Tuesday, then on which day is the lecture cancelled?', '4a862d37-8c65-5bfd-838a-9a73a5b489e2'::uuid, NULL, NULL, E'Wednesday', NULL, NULL),
  ('22d46b3a-f319-5ce8-85fa-0b07f80807d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '22d46b3a-f319-5ce8-85fa-0b07f80807d3'::uuid, 1, NULL, TRUE, 0, NULL, E'Discrimination against Women', E'Discrimination against women has been alleged in hiring practices for many occupations, but it is extremely difficult to demonstrate sex-biased hiring. A change {{1}} the way symphony orchestras recruit musicians provides an unusual way to test for sex-biased hiring. To overcome possible biases in hiring, most orchestras revised their audition policies in the 1970s and 1980s. A major change involved the use of ''blind'' auditions with a ''screen'' {{2}} the identity of the candidate from the jury. Female musicians in the top five symphony orchestras in the United States were less than 5% of all players in 1970 but are 25% today. We ask whether women were more likely to be advanced and/or hired with the use of ''blind'' auditions. Using data from actual auditions in an individual fixed-effects framework, we find that the screen increases by 50% the probability a woman {{3}} out of certain preliminary rounds. The screen also enhances, by several fold, the likelihood a female contestant will be the winner in the final round. Using data on orchestra personnel, the switch to ''blind'' auditions can explain between 30% and 55% of the {{4}} in the proportion female among new hires and between 25% and 46% of the increase in the percentage female in the orchestras since 1970.', NULL, NULL, NULL, E'1.in, 2.to conceal, 3.will be advanced, 4.increase', NULL, NULL),
  ('22d472bd-f343-5880-aa1c-b2887241afaf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '22d472bd-f343-5880-aa1c-b2887241afaf'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What will happen to a balloon if you inflate it beyond its capacity?', '62854dab-1688-5e18-9f0e-74b1dd2c1d62'::uuid, NULL, NULL, E'Blast / burst', NULL, NULL),
