  ('22ddef77-fbf9-5ccd-8db2-0e203709b91e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '22ddef77-fbf9-5ccd-8db2-0e203709b91e'::uuid, 1, NULL, TRUE, 0, NULL, E'Committee Gratitude', E'The committee would also like to express its gratitude to the independent assessors who joined the committee for consideration of each case. Their expertise and advice play a vital role in our work. A list of independent assessors who attended meetings during this reporting year is included at Appendix D.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('22e26203-145c-56a9-9c8d-460247da0d88'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '22e26203-145c-56a9-9c8d-460247da0d88'::uuid, 1, NULL, TRUE, 0, NULL, E'Mars', E'As we {{1}} more and more of its mysteries, the lure of Mars as a second home doesn''t {{2}} our imaginations. From the imagery {{3}} from previous Mars rovers such as Curiosity, scientists have found tracks of what could only be {{4}} to be flowing water.', NULL, NULL, NULL, E'1.unfold, 2.escape, 3.captured, 4.deemed', NULL, NULL),
  ('22ef15e5-072a-5034-9b0d-1b328254368b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '22ef15e5-072a-5034-9b0d-1b328254368b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '72d5b17d-38d0-58be-92b2-457e4c827b30'::uuid, NULL, E'The housing sales have been turning down since the last summer.', NULL, NULL, NULL),
  ('22f36e6f-9720-5a50-b26d-11dc96499ec3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '22f36e6f-9720-5a50-b26d-11dc96499ec3'::uuid, 1, NULL, TRUE, 0, NULL, E'Fractional Reserve Banking', E'Fractional reserve banking is a banking system in which banks only hold a fraction of the money their customers'' deposit as reserves. This allows them to use the rest of it to make loans and thereby essentially create new money. This gives commercial banks the power to directly affect the money supply.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('22fa3e8f-8d34-521d-a0f9-8532ca9383d0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '22fa3e8f-8d34-521d-a0f9-8532ca9383d0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd61344ab-bcbc-50fb-af9b-060ec9bf9b61'::uuid, NULL, E'These industries are polluting our rivers with tons of chemical materials.', NULL, NULL, NULL),
