  ('235c78b8-f4c4-557e-8952-b6dbb11f6959'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '235c78b8-f4c4-557e-8952-b6dbb11f6959'::uuid, 1, NULL, TRUE, 0, NULL, E'Monkey', E'A monkey that received a kidney from a genetically engineered miniature pig lived for more than two years after the transplant. Scientists took a molecular red pen to donor pigs’ genomes, editing the animals’ organs to be more of a match for humans. Such an editing strategy could one day make it more likely for people’s bodies to accept organs from different species.', NULL, NULL, NULL, NULL, NULL, NULL),
