  ('23a6cefa-140b-5ce8-99f3-b9db3377e68f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '23a6cefa-140b-5ce8-99f3-b9db3377e68f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c7eaa9ca-6bc2-589b-be79-9d070886c2eb'::uuid, NULL, E'It isn’t easy when it comes to the definition of this word.', NULL, NULL, NULL),
  ('23a7c0f6-961d-5c7f-b848-d45912462b7b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '23a7c0f6-961d-5c7f-b848-d45912462b7b'::uuid, 1, NULL, TRUE, 0, NULL, E'Pomo Basket Maker', E'Pomo, the Native Americans of northern California, were highly skilled at basketry, using the reeds, grasses, barks, and roots they found around them. Although a wide variety of materials was available, they used only a few. The weft was always made of willow, and the most commonly used weft was sedge root, a woody fiber that could easily be separated into strands. And even the basketry materials used by the Pomo people were limited, the designs were amazingly varied. Every Pomo basket maker knew how to produce fifteen to twenty distinct patterns that could be combined in a number of different ways.\n\nWhich description about Pomo is false?', NULL, NULL, NULL, E'They seldom used sedge root in their work.', NULL, NULL),
  ('23a8a727-43e6-512d-a191-1ad4bfec6749'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '23a8a727-43e6-512d-a191-1ad4bfec6749'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8343a3ed-d2b5-5e01-9d5a-a41f730b9ee3'::uuid, NULL, E'The book is informative but it could be accused of political bias.', NULL, NULL, NULL),
  ('23ad0062-7b23-5392-8fd9-867a14ddf7d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '23ad0062-7b23-5392-8fd9-867a14ddf7d8'::uuid, 1, NULL, TRUE, 0, NULL, E'Nervous System', E'Your nervous system allows you to think, move and feel. But there’s a whole other part of the nervous system that is largely outside of your control, operating automatically and quite independently from your conscious mind — and it keeps you alive.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('23b44ff8-0630-56c7-906a-b795a2fd074e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '23b44ff8-0630-56c7-906a-b795a2fd074e'::uuid, 1, NULL, TRUE, 0, NULL, E'Vividity of TV and Newspaper', E'To understand the final reason why the news marketplace of ideas dominated by television is so different from the one that emerged in the world dominated by the printing press, it is important to distinguish the quality of vividness experienced by television viewers from the "vividness" experienced by readers. I believe that the vividness experienced in the reading of words is automatically modulated by the constant activation of the reasoning centers of the brain that are used in the process of concreating the representation of reality the author has intended. By contrast, the visceral vividness portrayed on television has the capacity to trigger instinctual responses similar to those triggered by reality itself—and without being modulated by logic, reason, and reflective thought. The simulation of reality accomplished in the television medium is so astonishingly vivid and compelling compared with the representations of reality conveyed by printed words that it signifies much more than an incremental change in the way people consume information. Books also convey compelling and vivid representations of reality, of course. But the reader actively participates in the conjuring of the reality the book''s author is attempting to depict. Moreover, the parts of the human brain that are central to the reasoning process are continually activated by the very act of reading printed words: Words are composed of abstract symbols—letters—that have no intrinsic meaning themselves until they are strung together into recognizable sequences.\nTelevision, by contrast, presents to its viewers a much more fully formed representation of reality—without requiring the creative collaboration that words have always demanded.', NULL, NULL, E'The news marketplace of ideas dominated by television is so different from the one that emerged in the world dominated by the printing press, because the quality of vividness experienced by television viewers is different from that by readers, and the simulation of reality accomplished in the television medium is much more compelling and vivid compared with the representation of reality conveyed by printed words.', NULL, 5, 75),
  ('23b6a3ab-7004-5104-ae8d-8a41c0dfed88'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '23b6a3ab-7004-5104-ae8d-8a41c0dfed88'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6726fd2e-ee51-5a77-886f-0d9010037dfa'::uuid, NULL, NULL, E'The supplies of food and medicine have been delivered by volunteers.', NULL, NULL),
  ('23b97ec1-12ff-506a-8da0-379ee5abd7d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '23b97ec1-12ff-506a-8da0-379ee5abd7d5'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3e004d46-56a5-5939-8c71-04ba94cb323d'::uuid, NULL, E'It''s really hard to tell how much company crimes cost us.', NULL, NULL, NULL),
  ('23bc04de-88c7-5864-bfbc-8be6b6b18583'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '23bc04de-88c7-5864-bfbc-8be6b6b18583'::uuid, 1, NULL, TRUE, 0, NULL, E'Deep Space Video', E'In a groundbreaking experiment, NASA has successfully sent a 15-second video of an orange tabby cat named Taters chasing a laser pointer dot in ultra-HD. The video traveled almost 19 million miles from a probe back to Earth. This was part of a NASA experiment to test the possibility of sending streaming video through deep space, {{1}} a laser-based communication system called Deep Space Optical Communications (DSOC). The video was added to the Psyche probe, which was {{2}} in October on a six-year mission to visit an asteroid. On December 11, it sent the video back to Earth in just 101 seconds. This marked a significant achievement in the field of space communication, demonstrating the {{3}} of laser technology in transmitting data across vast distances in space. The implications of this experiment are far-reaching. It has set a precedent for future space missions, opening up the possibility of transmitting broadband video across millions of miles. This could significantly enhance our capabilities in space exploration and scientific research, facilitating more {{4}} missions in the future.', NULL, NULL, NULL, E'1.using, 2.launched, 3.potential, 4.ambitious', NULL, NULL),
  ('23bedc35-8633-59d4-8ffe-e2018f6e188b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '23bedc35-8633-59d4-8ffe-e2018f6e188b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0e8d8f4d-7fd9-59ae-9645-e23a90f4e8d9'::uuid, NULL, NULL, E'To excel, you must practice a specific skill repeatedly and consistently.', NULL, NULL),
  ('23c35f6e-f492-5d24-b953-e868d03c6753'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '23c35f6e-f492-5d24-b953-e868d03c6753'::uuid, 1, NULL, TRUE, 0, NULL, E'Emperor Penguin', E'The emperor is the giant of the penguin world and the most iconic of the birds of Antarctica. Gold patches on their ears and on the top of their chest brighten {{1}} their black heads. Emperors and their closest relative, the king penguin, have unique breeding cycles, with very long chick-rearing periods. The emperor penguins breed the furthest south of any penguin species, forming large colonies on the sea-ice surrounding the Antarctic continent. They are true Antarctic birds, rarely {{2}} in the subantarctic waters. {{3}} the chicks can fledge in the late summer season, emperors breed during the cold, dark winter, with temperatures as low at - 50°C and winds {{4}} to 200 km per hour. They trek 50–120 km (30–75 mls) over the ice to breeding colonies which may include thousands of individuals. The female lays a single egg in May then passes it over to her mate to incubate {{5}} she goes to sea to feed. For nine weeks the male fasts, losing 45% of his body weight. The male balances the egg on his feet, which are {{6}} in a thick roll of skin and feathers. The egg can be 70°C warmer than the outside temperature.', NULL, NULL, NULL, E'1.up, 2.seen, 3.So that, 4.up, 5.whilst, 6.covered', NULL, NULL),
  ('23c3bab0-9cf8-56cf-9529-2b6097897c04'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '23c3bab0-9cf8-56cf-9529-2b6097897c04'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '74ea072f-9b89-513a-acee-4cae80c5b881'::uuid, NULL, E'Elderly people tend to become more socially isolated than others.', NULL, NULL, NULL),
  ('23c4226c-192f-568a-af60-9a34f1e282d1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '23c4226c-192f-568a-af60-9a34f1e282d1'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '75031e23-f944-55b8-a5f4-429057e067ec'::uuid, NULL, E'They cut away all the dead branches from the tall palm tree.', NULL, NULL, NULL),
  ('23c61aeb-c424-58dc-a59c-0373135a9dc5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '23c61aeb-c424-58dc-a59c-0373135a9dc5'::uuid, 1, NULL, TRUE, 0, NULL, E'Changing Your Name', E'Changing your name is a big deal. Your identity and history are tied to your name, so the switch can be a monumental decision. Unfortunately, governments know this, too — so the process of legally changing your name often involves red tape, loads of paperwork, and high fees.\nName change laws vary from one U.S. state to the next, so navigating that maze of rules, forms, and hearings can be overwhelming. While a legal name change can be a bureaucratic nightmare, it''s necessary for people who wish to make their new names official.\nSome people decide to change their names for unconventional reasons, too, like they want the same name as their favorite superhero. Generally, you''re allowed to choose an unusual name for an atypical reason. But some names are off limits in certain states, like names that are vulgar or offensive, ones that may cause harm or public confusion, and ones that have excessive or numerical characters.\nBecause individual states handle name changes, it is impossible to provide a one-size-fits-all guide to the process. Though you''d need to refer to the instructions supplied by your local court or consult with an attorney to learn the rules specific to your situation, there are guidelines that are common across the U.S.\nLegal name changes can be divided into two basic categories: those that require you to file a petition with a local court and those that don''t. We''ll start with the latter, since those can demand less up-front legwork. These kinds of name changes occur within other legal proceedings, such as marriage, divorce, and naturalization.', NULL, NULL, NULL, NULL, 5, 75),
  ('23ce7a5f-bb4c-5998-9308-510b0de5af87'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '23ce7a5f-bb4c-5998-9308-510b0de5af87'::uuid, 1, NULL, TRUE, 0, NULL, E'Boredom', E'First and foremost, being bored motivates you to search out something less boring to do. Feeling bored at work, for example, could inspire you to explore a change of career. Or if you decide there’s nothing worth watching on TV, you might choose to switch off and make your own entertainment by taking up a new hobby.\nThis, according to researchers at the University of Central Lancashire, can explain why the lockdown of the past two years saw a surge in creativity among people stuck at home. From banana-bread-making to picking up a paintbrush for the first time since childhood, many of us realized there are only so many times you can watch Tiger King on Netflix before you need to find other ways to amuse yourself.\nBut what about those times when you have no choice but to stick with the boring situation — carrying out a mundane task at work or waiting for a bus, for instance? The good news is that the boredom you’re feeling now could spark your creativity and help you come up with some of your best ideas, says a 2019 study published in the Academy of Management Discoveries journal. People who’d taken part in a boring bean-sorting task later performed better at coming up with creative ideas than another group who’d been given something more interesting to do first.', NULL, NULL, NULL, NULL, 5, 75),
  ('23d25e7f-d64c-5f72-b1f7-60ee9a0f481c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '23d25e7f-d64c-5f72-b1f7-60ee9a0f481c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '890609c6-6860-5a9b-a84c-91920e521dcb'::uuid, NULL, E'You can borrow up to two books at the same time in the library.', NULL, NULL, NULL),
  ('23d5c9ee-5f87-5a2f-bd48-a6b3b553a71a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '23d5c9ee-5f87-5a2f-bd48-a6b3b553a71a'::uuid, 1, NULL, TRUE, 0, NULL, E'Doughnuts', E'Doughnuts are particularly difficult to resist – and now we know why. A study of how our brains respond to food has found that {{1}} that are high in both carbs and fats trigger a super-charged amount of activity in our brain’s reward center. Dana Small at Yale University and colleagues scanned the brain activity of hungry volunteers as they were shown images of foods that were either high in carbohydrate, such as candy, high in fat, such as cheese, or high in both, such as doughnuts. After the scans, the volunteers were asked to {{2}} money in a competitive auction for the food they wanted to have for a snack. Compared to food containing just carbs or fat, the team found that foods high in both of these together {{3}} far more activity in the brain’s striatum – a region involved in reward that releases the feel-good chemical dopamine. The volunteers were also willing to pay more for the snacks that were high in both carbs and fat, despite all the food items having the same calorific value.', NULL, NULL, NULL, E'1.treats, 2.bid, 3.provoked', NULL, NULL),
  ('23d7bedb-0e4d-5aaa-b835-9718aad0cb73'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '23d7bedb-0e4d-5aaa-b835-9718aad0cb73'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '418eff06-aa88-5526-9be9-6eba5144b3eb'::uuid, NULL, E'The main issue is to decide how we want to launch the new product.', NULL, NULL, NULL),
  ('23d93023-6d8f-5656-b34e-0edc4ccee5c1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '23d93023-6d8f-5656-b34e-0edc4ccee5c1'::uuid, 1, NULL, TRUE, 0, NULL, E'Nature Conservation Amendment Act', E'The Nature Conservation Amendment Act of 1996 enables the Minister of Environment and Tourism to register a conservancy if it has a {{1}} committee, a legal constitution, which provides for the sustainable management and utilization of game in the conservancy, the ability to {{2}} the funds, an approved method for the {{3}} distribution of benefits to members of the community and defined boundaries .', NULL, NULL, NULL, E'1.representative, 2.manage, 3.equitable', NULL, NULL),
  ('23dbafe0-8ca3-5b43-83a2-4f9f53fa2867'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '23dbafe0-8ca3-5b43-83a2-4f9f53fa2867'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which word do we use to describe a desert, humid or dry?', 'e4a04458-cf7a-5e94-9747-83d752d38941'::uuid, NULL, NULL, E'Dry', NULL, NULL),
  ('23de3ac4-6b86-5d58-8f98-a5a688956943'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '23de3ac4-6b86-5d58-8f98-a5a688956943'::uuid, 1, NULL, TRUE, 0, NULL, E'Urban and Rural', NULL, NULL, NULL, NULL, E'2, 1, 4, 3', NULL, NULL),
  ('23df69da-28bf-5544-b26b-160f205952e5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '23df69da-28bf-5544-b26b-160f205952e5'::uuid, 1, NULL, TRUE, 0, NULL, E'Low-income Countries', E'Periods of extremely hot weather cost the global economy an estimated $16 trillion between 1992 and 2013, while {{1}} the poorest countries four times as hard as the richest ones. “Our work reveals that we have {{2}} both the costs of climate change so far and how sensitive our economy is at present to climate variations,” says Justin Mankin at Dartmouth University in New Hampshire. Previous studies have shown that climate change hits the poorest nations hardest, despite them {{3}} the least to climate change. This is partly because many low-income countries are in the tropics and have a hotter climate to begin with. New data on economic growth allowed Mankin and Christopher Callahan, also at Dartmouth College, to look at the impact of extreme heat at a regional level and use models to fill in the data in parts of Africa and Asia where figures were missing. Their analysis reveals that short {{4}} of extreme heat were significant enough to lower a region’s economic output for the entire year.', NULL, NULL, NULL, E'1.hitting, 2.underestimated, 3.contributing, 4.spells', NULL, NULL),
  ('23e00126-9ae4-5498-b0ae-8002a8c6967f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '23e00126-9ae4-5498-b0ae-8002a8c6967f'::uuid, 1, NULL, TRUE, 0, NULL, E'Giant Turtle', E'A giant turtle made from discarded plastic trash will greet visitors to the British Science Festival this week. The plastic containers, bottles and cups were collected locally in Hull, where the event is taking place at the city''s university. Standing 3.5m tall (11.5ft), the art installation {{1}} commissioned by the University of Hull with the aim of raising awareness of plastic waste. Professor Dan Parsons, director of the university''s Energy and Environment Institute, said: ''Marine pollution is a mounting global challenge, which is already having {{2}} consequences. We have a duty to protect these fragile environments and the marine life and ecosystems which we {{3}} home. The university has commissioned this installation as a physical {{4}} of what is ending up in the oceans, but also to ask visitors to campus to stop and think what they could do to try to reduce their own waste.''', NULL, NULL, NULL, E'1.was, 2.devastating, 3.call, 4.reminder', NULL, NULL),
  ('23e136dc-ecb0-5fdf-9d8e-0a75b9270c99'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '23e136dc-ecb0-5fdf-9d8e-0a75b9270c99'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4983f7a5-331f-5065-a3e0-f0dd6f43ceb4'::uuid, NULL, NULL, E'Career mobility is very important for new graduates.', NULL, NULL),
  ('23e875f8-955c-5588-8a3a-ebd3e8eb9ef9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '23e875f8-955c-5588-8a3a-ebd3e8eb9ef9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9ebb7f16-8be9-55f3-b1f3-e300fa59791e'::uuid, NULL, NULL, E'Online classes offer flexibility to learn despite a hectic personal schedule.', NULL, NULL),
