  ('23f5d0d3-9059-5ad6-b14c-e7d4d508d785'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '23f5d0d3-9059-5ad6-b14c-e7d4d508d785'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '64aa65c2-d81e-5230-9cda-ac0c4e51fa1e'::uuid, NULL, E'The cafe will close soon but you can use the snack machine which is running overnight.', NULL, NULL, NULL),
  ('23f74a3f-228c-5563-a834-3cc3d4402c2f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '23f74a3f-228c-5563-a834-3cc3d4402c2f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7be4a913-20a4-5992-a8cd-04db47e4193c'::uuid, NULL, NULL, E'You must submit your assignments by next Friday at the latest.', NULL, NULL),
  ('23f74ce6-5c3d-56cd-ad71-ba0d99fa6407'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '23f74ce6-5c3d-56cd-ad71-ba0d99fa6407'::uuid, 1, NULL, TRUE, 0, NULL, E'Voyage', E'A crew of scientists voyaged by ship from the southern tip of Chile into the frigid Antarctic to search for clues to one of the great unknowns of climate change. They planned to crisscross a remote patch of sea near the spot where, a year earlier, another crew had injected a tankful of an inert chemical one mile below the surface.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('23f77627-1e70-5d4e-b79e-55e2313987f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '23f77627-1e70-5d4e-b79e-55e2313987f8'::uuid, 1, NULL, TRUE, 0, NULL, E'Boys'' and Girls'' Performance', NULL, 'de23b373-0a0d-5743-94df-0fdadf9d2339'::uuid, NULL, E'For centuries, boys were top of the class. But these days, that’s no longer the case. A new study by the OECD, a club of mostly rich countries, examined how 15-year-old boys and girls performed at reading, mathematics, and science. Boys still score somewhat better at maths, and in science the genders are roughly equal. But when it comes to the students who really struggle, the difference is stark: boys are 50% more likely than girls to fall short of basic standards in all three areas. Researchers suggest that doing homework set by teachers is linked to better performance in maths, reading, and science. Boys, it appears, spend more of their free time in the virtual world; they are 17% more likely than girls to play collaborative online games than girls every day. They also use the internet more. Third, peer pressure plays a role. A lot of boys decide early on that they are just too cool for school which means they’re more likely to be rowdy in class. Teachers mark them down for this. In anonymous tests, boys perform better. In fact, the gender gap in reading drops by a third when teachers don’t know the gender of the pupil they are marking. So what can be done to close this gap? Getting boys to do more homework and cut down on screen-time would help.. But most of all, abandoning gender stereotypes would benefit all students. Boys in countries with the best schools read much better than girls. And girls in Shanghai excel in mathematics. They outperform boys from anywhere else in the world.', NULL, NULL, NULL),
  ('23f9bb82-8ef5-5087-b492-00c77e436e89'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '23f9bb82-8ef5-5087-b492-00c77e436e89'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a picture painted on a wall?', '91b50529-ccdf-5a55-a892-782b5e88c788'::uuid, NULL, NULL, E'Mural / fresco / wall painting', NULL, NULL),
  ('23fa5dbe-c242-5005-987c-1ef9b316fb34'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '23fa5dbe-c242-5005-987c-1ef9b316fb34'::uuid, 1, NULL, TRUE, 0, NULL, E'Middle Class', E'The reason why middle class people are more likely to play music, paint and act has been revealed in a major new study. Research involving 78,000 people found that it was not wealth or social status that were strongly linked to people taking part in arts activities as amateurs or professionals, but rather, the level of education that lay behind arts participation.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('240af9ff-5d15-54cf-8be1-4c30e9fcbdf0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '240af9ff-5d15-54cf-8be1-4c30e9fcbdf0'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call a leave which is taken for a general reason?', '9fb6b852-4b90-5c79-ace9-53ba35da823a'::uuid, NULL, NULL, E'Casual leave / personal leave', NULL, NULL),
  ('240bd023-91a5-527e-b9e2-d457030223b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '240bd023-91a5-527e-b9e2-d457030223b2'::uuid, 1, NULL, TRUE, 0, NULL, E'Termites', E'Termites, the tiny creatures – have learnt to create a comfortable home in some of the world''s toughest climates. Outside, in the African Savannah the temperatures vary from forty degrees in the day to one degree at night. Yet, inside the mound, the temperature stays constant.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('2412b9f7-fa9c-5059-86d0-35e72d818048'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2412b9f7-fa9c-5059-86d0-35e72d818048'::uuid, 1, NULL, TRUE, 0, NULL, E'Urban and Rural', E'So it seems that, well, despite the fact that more couples are childless and more people are working in the cities, the pull to the suburbs has continued. Over 50 percent of Americans ... that''s about 158 million - live in the suburbs now, while in 1990 that figure was around 48 percent. That''s actually a difference of 40 million. Rural areas, on the other hand, have not seen the same pattern at all. Populations have declined over the past 20 years and now only 16 percent of our nation lives there.\n\nWhat is the speaker''s main focus?', '0c417627-3aa8-54f5-b8cc-ba9e79334db8'::uuid, NULL, NULL, E'trends in where Americans live', NULL, NULL),
  ('24132ac2-d6bc-55a9-ac2b-cfb93b8fca3b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '24132ac2-d6bc-55a9-ac2b-cfb93b8fca3b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ef419e9c-fcb9-5664-aaec-62cc9789344a'::uuid, NULL, NULL, E'Throughout your degree you''ll have the chance to participate in research.', NULL, NULL),
  ('24152a6f-494c-5b99-b8c9-47edab05bf49'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '24152a6f-494c-5b99-b8c9-47edab05bf49'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What fruit is known as the main ingredient in traditional American pie?', '408e86e5-d526-5e24-aba9-512ffdf5ac5c'::uuid, NULL, NULL, E'Apple', NULL, NULL),
  ('2419e4a1-25cf-5c1f-8b82-88454b87e0d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '2419e4a1-25cf-5c1f-8b82-88454b87e0d7'::uuid, 1, NULL, TRUE, 0, NULL, E'Noticeable Trend', E'As individuals'' {{1}} increase, there is a noticeable trend towards saving more, not merely for unforeseen emergencies, but also for future aspirations and comforts. The {{2}} to save is influenced by a {{3}} of factors including economic conditions, cultural values, and personal financial goals. As people navigate through different life stages, their saving patterns reflect a balancing act between {{4}} needs and long-term plans.', NULL, NULL, NULL, E'1.earnings, 2.propensity, 3.myriad, 4.immediate', NULL, NULL),
  ('241a8587-a44d-58e0-a7a8-93b88486e11f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '241a8587-a44d-58e0-a7a8-93b88486e11f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'If a building is one thousand meters high, from where do we measure the height?', '49850445-030f-5d86-83aa-7e2d9d981096'::uuid, NULL, NULL, E'Sea level', NULL, NULL),
  ('2424d999-f2ea-59d3-b77d-7011cc281ab1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '2424d999-f2ea-59d3-b77d-7011cc281ab1'::uuid, 1, NULL, TRUE, 0, NULL, E'Summary', NULL, NULL, NULL, NULL, E'5, 2, 3, 1, 4', NULL, NULL),
  ('242863e0-681f-5871-ad37-2bbc0ca156e3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '242863e0-681f-5871-ad37-2bbc0ca156e3'::uuid, 1, NULL, TRUE, 0, NULL, E'Use of IT', E'DeLone and McLean’s model has been criticized by some authors. Indeed, this model is specific to contexts of voluntary use of information technology. The usage variable remains a success variable of information systems if the user himself decides to adopt or reject the technology. However, for mandatory uses, such as for ERP systems, the use of the technology is obvious. The success of information systems cannot, therefore, be measured by usage.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('2429505e-12e3-5c36-8834-2f7b08eb535f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2429505e-12e3-5c36-8834-2f7b08eb535f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '74ea4af2-0d83-5f94-8182-532d8b755750'::uuid, NULL, NULL, E'Students must submit a thesis on this subject within next week.', NULL, NULL),
  ('242a3556-4e55-502f-9c76-920a4570f298'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '242a3556-4e55-502f-9c76-920a4570f298'::uuid, 1, NULL, TRUE, 0, NULL, E'Essays', E'Essays are used as an assessment tool to {{1}} your ability to research a topic and construct an {{2}} , as well as your understanding of subject content. This does not mean that essays are a ''regurgitation'' of everything your lecturer has said {{3}} the course. Essays are your opportunity to explore in greater {{4}} .', NULL, NULL, NULL, E'1.evaluate, 2.argument, 3.throughout, 4.depth', NULL, NULL),
  ('242b8aef-fa50-5fa5-a187-34cf77f772c9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '242b8aef-fa50-5fa5-a187-34cf77f772c9'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What are the thick forests in tropical parts of the world that have a lot of rain?', '0cb17bd9-1b17-5ea3-a602-ff2c50991289'::uuid, NULL, NULL, E'Rainforest / rainforests', NULL, NULL),
  ('242e3999-cb8d-5c34-a892-00ef2fbe7fac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '242e3999-cb8d-5c34-a892-00ef2fbe7fac'::uuid, 1, NULL, TRUE, 0, NULL, E'Bizarre Universe', E'It seems we live in a bizarre universe. One of the greatest mysteries in the whole of science is the prospect that 75% of the Universe is made up from a mysterious {{1}} known as ''Dark Energy'', which causes an acceleration of the cosmic expansion. Since a further 21% of the Universe is made up from invisible '' Cold Dark Matter'' that can only be {{2}} through its gravitational effects, the ordinary atomic matter making up the rest is apparently only 4% of the total cosmic budget. These {{3}} require a shift in our perception as great as that made after Copernicus'' {{4}} that the Earth moves around the Sun. This lecture will start by reviewing the chequered history of Dark Energy, not only since Einstein''s proposal for a similar entity in 1917, but by tracing the concept back to Newton''s ideas. This lecture will {{5}} the current evidence for Dark Energy and future surveys in which UCL is heavily involved: the ''Dark Energy Survey'', the Hubble Space Telescope and the proposed Euclid space mission.', NULL, NULL, NULL, E'1.substance, 2.detected, 3.discoveries, 4.revelation, 5.summarize', NULL, NULL),
  ('243165ff-7a31-504b-a4e4-f47419699186'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '243165ff-7a31-504b-a4e4-f47419699186'::uuid, 1, NULL, TRUE, 0, NULL, E'Stretchable System', E'A stretchable system that can harvest energy from human breathing and motion for use in wearable health-monitoring devices may be possible, according to an international team of researchers.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('2434237b-8972-50bc-afd3-4132e036220c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2434237b-8972-50bc-afd3-4132e036220c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd2a76164-bb5f-51d4-b148-b77a1e42694b'::uuid, NULL, E'The new job will provide you with invaluable experience.', NULL, NULL, NULL),
  ('243e48ee-d49a-5101-b352-e8dfc74eb77a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', '243e48ee-d49a-5101-b352-e8dfc74eb77a'::uuid, 1, NULL, TRUE, 0, NULL, E'SMW', E'As I mentioned last week, we''re going to look today at fiction writing, writing stories, and in particular at authors who have a reputation for creating characters in their books who are known as ''unreliable narrators''. Now what does that mean exactly? Well Originally, in the nineteenth century, it tended to simply mean that - as a reader - you just couldn''t trust what the narrator of a story was telling you. This might have been because they were not giving you important information, or because they themselves as a character in their own story lacked some kind of personal insight. In later works of literature, this ''unreliability'' was used by authors more deliberately, um, with the direct intention of making a story more complicated for a reader to understand - perhaps a crime novel,or a thriller. Nowadays, there''s a lot more humour in unreliable narration and it''s often used to make first-person characters enjoyable to read about. So, what all that tells us as a general starting point is that this type of narration - - - .\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', 'c4ecb71e-495f-578f-a545-45cc30728ec3'::uuid, NULL, NULL, E'has changed over time', NULL, NULL),
  ('2448cbe1-856f-5fc3-be73-d017adf3d663'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', '2448cbe1-856f-5fc3-be73-d017adf3d663'::uuid, 1, NULL, TRUE, 0, NULL, E'MCM-R', E'Why do some countries drive on the left, while others - the majority- drive on the right? In fact, those that drive on the left make up about twenty-five per cent of the world''s countries and are, apart from the UK itself, mostly countries that were British colonies: India, South Africa, Singapore, Jamaica, and so on. Japan does too, although it wasn''t a colony, and as late as 2009, Samoa switched from driving on the right largely because they wanted to buy right-hand drive cars made in Japan and New Zealand.\nThe Romans introduced the custom of keeping to the left, a habit that was reinforced in medieval times when riders throughout Europe passed oncoming strangers sword arm to sword arm - this idea is based on the fact that the majority of people are right-handed. An increase in horse traffic towards the end of the 18th century meant that the convention gained strength, but it was not put into law until 1835. Legend has it that Napoleon is responsible for making the European countries which he conquered\nkeep to the right, for the simple reason either that he was left-handed himself, or that he wanted to be different from his enemy, England. This is most probably nonsense, but an Emperor''s whims can go a long way. So France, obviously, and Spain, the Netherlands and other countries Napoleon overran used this system, and over the years other countries adopted the practice to make crossing borders easier and safer. The latest European country to convert was Sweden, in 1967.\n\nAccording to the text, which of the countries listed below drive on the left?', NULL, NULL, NULL, E'Japan\nScotland\nSamoa\nSouth Africa', NULL, NULL),
  ('24551686-7e54-5112-8844-a6d58e4279cd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '24551686-7e54-5112-8844-a6d58e4279cd'::uuid, 1, NULL, TRUE, 0, NULL, E'Kimbell', E'The first section of the book covers new modes of assessment. In Chapter 1, Kimbell (Goldsmith College, London) responds to {{1}} of design programs as formalistic and conventional, stating that a focus on risk-taking rather than hard work in design innovation is equally problematic. His research contains three parts that include preliminary exploration of design innovation qualities, investigation of resulting classroom practices, and development of evidence-based assessment. The assessment he describes is presented in the form of a structured worksheet, which includes a collaborative {{2}} and digital photographs, in story format. Such a device encourages stimulating ideas, but does not recognize students as design {{3}} .The assessment sheet includes holistic impressions as well as details about “having, growing, and proving” ideas. {{4}} judgments are evident in terms such as “wow” and “yawn” and reward the quality and quantity of ideas with the term, “sparkiness”, which fittingly is a pun as the model project was to design light bulb packaging. In addition, the assessment focuses on the process of optimizing or complexity control as well as proving ideas with thoughtful criticism and not just generation of novel ideas. The definitions for qualities such as “technical” and “aesthetic” pertaining to users, are too narrow and ill-defined. The author provides {{5}} of the project, its features and structures, students’ notes and judgments, and their sketches and photographs of finished light bulb packages, in the Appendix.', NULL, NULL, NULL, E'1.criticisms, 2.element, 3.innovators, 4.Colloquial, 5.examples', NULL, NULL),
  ('24583ed9-eb3d-5f3a-a3a9-5b29a8019640'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '24583ed9-eb3d-5f3a-a3a9-5b29a8019640'::uuid, 1, NULL, TRUE, 0, NULL, E'Uptick in Crime', E'The recent uptick in violent crime, particularly during the COVID-19 pandemic, has presented a complex puzzle for policymakers and the public alike. In 2020, the United States witnessed a dramatic increase in violent crimes, especially murders, which {{1}} by nearly 30%, and assaults. This rise is intricately linked to a broader spike in gun violence, with firearms {{2}} in a significant majority of murders. The phenomenon was widespread, affecting cities, suburban areas, and rural locales without clear distinctions along political lines. This national trend challenges the notion that local policy changes in specific jurisdictions are to blame, suggesting broader underlying {{3}} . Despite the increase in certain types of violent crime, it''s important to {{4}} that not all crime rates rose; property crimes, for instance, reached a record low, highlighting the divergent trends between different categories of crime.', NULL, NULL, NULL, E'1.surged, 2.being used, 3.causes, 4.note', NULL, NULL),
  ('245dd811-4cbd-5175-8e5a-409f857397ce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '245dd811-4cbd-5175-8e5a-409f857397ce'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7249c9c2-c608-57a4-bc67-5e9f4b0253ee'::uuid, NULL, E'The company will arrange a taxi to meet you at the airport.', NULL, NULL, NULL),
  ('245fd0b0-3251-5f99-9c01-f771e6f5cde0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '245fd0b0-3251-5f99-9c01-f771e6f5cde0'::uuid, 1, NULL, TRUE, 0, NULL, E'Barred Owls', E'You don’t have to drive far into the forests to hear the {{1}} hooting of the barred owl. In fact, you can find them in the neighborhoods, where you might {{2}} one perched above on a walk, or you might be surprised when one swoops down to {{3}} you away from its territory. The barred owl is an {{4}} species that competes with the native northern spotted owl.', NULL, NULL, NULL, E'1.distinctive, 2.glimpse, 3.chase, 4.invasive', NULL, NULL),
  ('2461bdbd-a01d-5258-a273-8417dc9a60da'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2461bdbd-a01d-5258-a273-8417dc9a60da'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7f417edc-cc9a-5f19-808a-fc75ced8e4b9'::uuid, NULL, NULL, E'Human beings compete with other living things for resources and space.', NULL, NULL),
  ('2468034b-a956-542c-a683-f4c00e4182ac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2468034b-a956-542c-a683-f4c00e4182ac'::uuid, 1, NULL, TRUE, 0, NULL, E'Live in Space', E'Humans evolved for and adapted to conditions on Earth. Move us off our planet, and we start to fail—physically and psychologically. The cancer risk from cosmic rays and the problems that human bodies experience in microgravity could be deal-breakers on their own. Moreover, there may not be a viable economic case for sustaining a presence on another world.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('246d5c20-81d2-5e00-9d9c-f56b57826eeb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '246d5c20-81d2-5e00-9d9c-f56b57826eeb'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bcb6202a-bf4d-5dac-b0d7-e88ad0faa6a5'::uuid, NULL, E'The company is now well positioned to compete in foreign markets.', NULL, NULL, NULL),
  ('247750c8-91c5-5f70-bf66-48f3b119f11e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '247750c8-91c5-5f70-bf66-48f3b119f11e'::uuid, 1, NULL, TRUE, 0, NULL, E'Interdisciplinary Studies', E'Interdisciplinarity or interdisciplinary studies involves the combination of two or more academic disciplines into one activity. It draws knowledge from several other fields like sociology, anthropology, psychology, economics etc. It is about creating something by thinking across boundaries. It is related to an interdisciplinary field, which is an organizational unit that crosses traditional boundaries between academic disciplines or schools of thought.', NULL, NULL, NULL, NULL, NULL, NULL),
