  ('24862f5a-6dfb-5564-b873-cebee012eab2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '24862f5a-6dfb-5564-b873-cebee012eab2'::uuid, 1, NULL, TRUE, 0, NULL, E'Love', E'Love is a powerful force that transcends boundaries and defies logic. It can bring immense joy and profound pain, often simultaneously. Love is the gentle touch that heals wounds and the flame that ignites passion. It is the unspoken words that convey understanding and the shared laughter that creates memories.', NULL, NULL, NULL, NULL, NULL, NULL),
