  ('2495a2e4-ca1b-5128-8c85-f3be6bf86b68'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2495a2e4-ca1b-5128-8c85-f3be6bf86b68'::uuid, 1, NULL, TRUE, 0, NULL, E'Birthday Activity', E'You''re organizing a team outing to celebrate a colleague''s birthday-Dave, and everyone''s suggesting different activities. However, you realize that some options might not be suitable due to varying preferences and physical abilities. You need to gently guide the discussion towards inclusive activities that everyone can enjoy regardless of their interests or limitations. What would you say to your colleagues?', '4c172552-1271-5dde-9f9d-d2ad772c5fc6'::uuid, NULL, E'Hey team, I''m thrilled about planning our outing for Dave''s birthday! Let''s consider activities that everyone can participate in comfortably. How about we go for a picnic in the park or have a game night at someone''s place? These options cater to various interests and physical abilities, ensuring everyone has a great time. Let''s focus on creating inclusive and enjoyable memories together!', NULL, NULL, NULL),
  ('249c4290-84b3-52dd-95f0-feb6f31ec03f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '249c4290-84b3-52dd-95f0-feb6f31ec03f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c96d540d-d1f4-5324-8f24-e0d8ee4b6899'::uuid, NULL, E'Prepare the report for the manager.', NULL, NULL, NULL),
