  ('24cd22e1-dcc6-5d1a-aead-95d4ce9a12e6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '24cd22e1-dcc6-5d1a-aead-95d4ce9a12e6'::uuid, 1, NULL, TRUE, 0, NULL, E'Reserve Bank', E'Most people do not realize that some banks literally make money by giving loans without having money on deposit. The system is called fractional reserve banking and is used in most economies. It sounds as though it is safe because it says that banks have to keep a fraction of their deposits with the Reserve Bank.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('24cf9b3a-3101-5269-8ed8-38cbfc23082c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '24cf9b3a-3101-5269-8ed8-38cbfc23082c'::uuid, 1, NULL, TRUE, 0, NULL, E'Global Changes', E'Globalization refers to a set of changes rather than a single change. Many of these changes are social, cultural and political rather than purely economic, and one of the main drivers in addition to the global marketplace is the communication revolution.', NULL, NULL, NULL, NULL, NULL, NULL),
