  ('25425971-9c90-5869-9fd1-3193421e91f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '25425971-9c90-5869-9fd1-3193421e91f0'::uuid, 1, NULL, TRUE, 0, NULL, E'Lazy Roommate', E'You have a roommate, but he usually does not clean the common areas. You cannot stand dirty common areas. You''re going to talk to him. What are you going to say?', 'c55edae9-89ae-5339-a325-ebdfa789bfe1'::uuid, NULL, E'Hey roommate, I want to talk to you about something.\nWe seem to have a little issue with the shared living spaces.\nIt''s like you rarely clean the common areas, and I feel uncomfortable when those areas get dirty.\nAnd I''d like to know what you think.', NULL, NULL, NULL),
