  ('258cc1fe-ca57-568e-a5f5-4a1aa9600079'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '258cc1fe-ca57-568e-a5f5-4a1aa9600079'::uuid, 1, NULL, TRUE, 0, NULL, E'Executive Residence', E'The Executive Residence in the White House in the United States of America, where the president resides, is divided into several wings. It also includes the vice-president''s and president''s staff offices. This government building is a national heritage.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('258d2768-fb3d-5300-9fcb-9c9845d98509'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '258d2768-fb3d-5300-9fcb-9c9845d98509'::uuid, 1, NULL, TRUE, 0, NULL, E'Climate Misinformation', E'Scientists have found no evidence that natural forces have contributed to our planet’s current global warming problem, but a middle school student reading a crisp new book from the nation’s top science textbook publisher might think otherwise. “Due to both human and natural activities,” the child would read, “the amount of carbon dioxide in the air has increased.”', NULL, NULL, NULL, NULL, NULL, NULL),
  ('2593e428-6f68-52fa-a364-a14eff6ca0ea'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '2593e428-6f68-52fa-a364-a14eff6ca0ea'::uuid, 1, NULL, TRUE, 0, NULL, E'Track Down Research', E'Having tracked down research that is {{1}} to your area of interest, the next task is to actually {{2}} of that research. This section is intended to show you how to be critical of the research you {{3}} and how to check that the {{4}} is credible and represented appropriately. Unfortunately this means discussing the ways in which research findings may be misrepresented.', NULL, NULL, NULL, E'1.relevant, 2.make sense, 3.are reviewing, 4.evidence', NULL, NULL),
  ('259c13a6-6433-56ae-ba95-c8ce12e1453a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '259c13a6-6433-56ae-ba95-c8ce12e1453a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f548dedd-0883-5045-b1bd-8f824b6fa4d0'::uuid, NULL, E'He refused to comment before he had seen all the relevant information.', NULL, NULL, NULL),
