  ('25a38a64-c35c-5ef8-b3c9-f0bfb5adbd86'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '25a38a64-c35c-5ef8-b3c9-f0bfb5adbd86'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What does the word VIP stand for?', '51de816e-050e-5412-b7ee-8990a290fc5e'::uuid, NULL, NULL, E'Very important person', NULL, NULL),
  ('25a4368f-c4ad-52ce-a8d0-84e2c94999ad'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '25a4368f-c4ad-52ce-a8d0-84e2c94999ad'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '481aded4-c67b-5e53-9b7f-0a2178c4dde3'::uuid, NULL, E'Climate change is a pressing issue that requires global cooperation and action.', NULL, NULL, NULL),
  ('25aad9ad-ddf2-5fd5-85e2-19ab4fa7e347'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '25aad9ad-ddf2-5fd5-85e2-19ab4fa7e347'::uuid, 1, NULL, TRUE, 0, NULL, E'Brain Inflammation', E'Severe inflammation in early childhood is a clinically known risk factor for developing autism and schizophrenia. Now, for the first time, scientists from the University of Maryland School of Medicine (UMSOM) have discovered that inflammation alters the development of vulnerable brain cells, and this could have mechanistic links to neurodevelopmental disorders.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('25b31d07-5c1a-5a21-9d3f-384d1a3d0f6f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '25b31d07-5c1a-5a21-9d3f-384d1a3d0f6f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the words that appear on the screen in a movie?', 'f34b3b85-36f8-5727-8163-4b660240e2f1'::uuid, NULL, NULL, E'Subtitle', NULL, NULL),
  ('25b4fe5a-2ccd-546f-9c67-94c443f488cc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '25b4fe5a-2ccd-546f-9c67-94c443f488cc'::uuid, 1, NULL, TRUE, 0, NULL, E'Skipping Stones', E'When physicist Lydéric Bocquet’s 7-year-old son asked him why a good throw makes a stone skip on a lake instead of {{1}} , Bocquet took the question as a challenge. He has now produced a set of equations explaining the physics underlying the popular pastime. Two key forces act on a skipping stone: gravity, which pulls it down, and lift, the reactive force of the water, which pushes the stone up each time it hits the {{2}} . If the lift force is greater than the force of gravity then the stone bounces up; otherwise it sinks. Bocquet’s physical model {{3}} out the conventional wisdom that the best skipping stones are flat and should be hurled nearly parallel to the water, fast and spinning. The stone’s flatness maximizes the lift, as does its speed, which also provides energy to keep it bouncing along. These are the same factors that keep a water-skier from sinking, Bocquet says. Spin prevents the stone from tilting and hitting the water edge-first, just as fast rotations {{4}} a bicycle or a spinning top.', NULL, NULL, NULL, E'1.sinking, 2.surface, 3.bears, 4.stabilize', NULL, NULL),
  ('25c3e83a-fcef-5562-b9eb-0928235b6388'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '25c3e83a-fcef-5562-b9eb-0928235b6388'::uuid, 1, NULL, TRUE, 0, NULL, E'Paleolithic People', E'The ways of life of Upper Paleolithic people are known through the remains of meals scattered around their hearths, together with many tools and weapons and the debris left over from their making. The people were hunter-gatherers who lived exclusively from what they could find in nature without practicing either agriculture or herding. They hunted the bigger herbivores, while berries, leaves, roots, wild fruit and mushrooms probably played a major role in their diet. Their hunting was indiscriminate, perhaps because so many animals were about they did not need to spare pregnant females or the young. In the cave of Enlene, for example, many bones of reindeer and bison fetuses were found. Apparently, upper Paleolithic people hunted like other predators and killed the weakest prey first. They did, however, sometimes concentrate on salmon runs and migrating herds of reindeer. Contrary to popular beliefs about cave man, upper Paleolithic people did not live deep inside caves. They rather chose the foot of cliffs, especially when an overhang provided good shelter. On the plains and in the valleys, they used tents made from hides of the animals they killed. At time, on the great Russian plains, they built huts with huge bones and tusks collected from skeletons of mammals. Men hunted mostly with spears, as the bow and arrow were probably not invented until the Magdalenian period that came at the end of the Upper Paleolithic. Tools and weapons, made out of wood or reindeer antlers, often had flint cutting edges.', NULL, NULL, E'The ways of life of Upper Paleolithic people are known through the remains of meals, tools and weapons, who were hunter-gatherers and hunted the bigger herbivores, when their hunting was indiscriminate, so they rather chose the foot of cliffs, and men hunted mostly with spears.', NULL, 5, 75),
  ('25d433d0-8a0c-5ae6-b05b-faba4befdf21'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '25d433d0-8a0c-5ae6-b05b-faba4befdf21'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '44100d0e-0d0e-5f8f-aa2c-2059e5547500'::uuid, NULL, NULL, E'Many people think they are more talented than others.', NULL, NULL),
