  ('26db8b1c-7ea0-5999-94f6-83a048130960'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '26db8b1c-7ea0-5999-94f6-83a048130960'::uuid, 1, NULL, TRUE, 0, NULL, E'Neptune', E'Neptune, the most distant gas giant in our solar system, is home to some of the most powerful winds ever observed. Faster than the speed of sound, these winds are more powerful than those on any other planet in our solar system, including Jupiter and Saturn. Neptune’s atmosphere is primarily composed of hydrogen and helium.', NULL, NULL, NULL, NULL, NULL, NULL),
