  ('26ea51e8-db91-52ea-addd-f933e3586b55'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '26ea51e8-db91-52ea-addd-f933e3586b55'::uuid, 1, NULL, TRUE, 0, NULL, E'Migraines', E'Individuals who suffer from migraines often struggle to find a treatment that is both reliable and effective, with limited information available regarding how different medications compare to one another. However, a recent study has utilized data from almost 300,000 smartphone app users to aid in medication decisions for those with migraines.', NULL, NULL, NULL, NULL, NULL, NULL),
