  ('2716d1df-7f5b-5cfc-bc4c-19a27ff1d22a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '2716d1df-7f5b-5cfc-bc4c-19a27ff1d22a'::uuid, 1, NULL, TRUE, 0, NULL, E'Renewable Energy', E'Recently, due to concerns over pollution and the possibility that some sources of fuel might eventually run out or become {{1}} to obtain, there has been much greater support for renewable sources of power, such as wind or solar energy.\nRenewable energy sources {{2}} 25 percent of the electricity we use. unlike {{3}} fuels, they tend not to produce any waste or significantly add to global warming by producing gases.', NULL, NULL, NULL, E'1.uneconomic, 2.provide, 3.fossil', NULL, NULL),
  ('27237d29-ad44-5a46-9c81-7a2a1bc28be1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '27237d29-ad44-5a46-9c81-7a2a1bc28be1'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd55aaf08-360e-53fa-872d-7a80a2f81046'::uuid, NULL, NULL, E'The study of utilizing projects is funded by the university.', NULL, NULL),
