  ('2785ae41-e6a3-531f-8293-1f382c001a83'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2785ae41-e6a3-531f-8293-1f382c001a83'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9513a785-d6f1-5676-a96d-77e38471e2f3'::uuid, NULL, NULL, E'After years of work, scholars have acquired much useful information.', NULL, NULL),
  ('27887bb4-6df8-5740-943b-911c3da1b08a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '27887bb4-6df8-5740-943b-911c3da1b08a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you need to attach to an envelope before posting it?', '1c61810a-8866-5bf3-8171-6d28ab906733'::uuid, NULL, NULL, E'Stamps', NULL, NULL),
  ('2788e6dd-8edc-5645-8b1b-d7d8e4300835'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '2788e6dd-8edc-5645-8b1b-d7d8e4300835'::uuid, 1, NULL, TRUE, 0, NULL, E'Bad Title', E'A good story may be given a bad title by its author, and so started toward failure. Novices are peculiarly {{1}} to this fault, usually through {{2}} themselves to be too easily satisfied. They go to {{3}} pains to make the story itself fresh and individual, and then cap it with a {{4}} phrase that is worse than no title at all. A good title is apt, specific, attractive, new, and short. A title is apt if it is an outgrowth of the plot — a text, as I have said. It stands definitely for that particular story, and gives a suggestion of what is to come — but only a suggestion, lest it should anticipate the denouement and so {{5}} the curiosity of the reader too soon.', NULL, NULL, NULL, E'1.liable, 2.allowing, 3.infinite, 4.commonplace, 5.satisfy', NULL, NULL),
  ('27899f8a-e8fb-5b76-8577-e3ecb6e7616c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '27899f8a-e8fb-5b76-8577-e3ecb6e7616c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the point on the Earth''s surface directly above an earthquake?', 'a4c8f3b1-8104-5bab-9c30-31d620dfa403'::uuid, NULL, NULL, E'Epicenter', NULL, NULL),
