  ('279526ea-976d-5a70-ab63-a5b0a7e01071'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '279526ea-976d-5a70-ab63-a5b0a7e01071'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '404b01ef-4242-589d-acb4-5f6de731d347'::uuid, NULL, NULL, E'The festival is heavily dependent on sponsorship for its success.', NULL, NULL),
  ('2795fd53-3df0-5d74-867e-d6e1eb3c8c05'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2795fd53-3df0-5d74-867e-d6e1eb3c8c05'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5b5a2ad3-050f-51cc-8201-8b4537e84291'::uuid, NULL, E'All students are encouraged to vote in the forthcoming elections.', NULL, NULL, NULL),
  ('2799d715-5ea2-5db3-aec6-300cbeec7ac6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2799d715-5ea2-5db3-aec6-300cbeec7ac6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'da80b40c-8db6-5885-8d7a-6ebfdfa8d786'::uuid, NULL, NULL, E'Having enough sleep has many positive benefits.', NULL, NULL),
  ('279edb5c-b48d-5be4-bff2-dc289bc72c27'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '279edb5c-b48d-5be4-bff2-dc289bc72c27'::uuid, 1, NULL, TRUE, 0, NULL, E'Diabetes', E'Diabetes is a chronic, metabolic disease {{1}} by elevated levels of blood sugar, which leads over time to serious damage to the heart, blood vessels, and so on. The most common is type 2 diabetes which {{2}} when the body becomes resistant to insulin or doesn''t make enough insulin. For people living with diabetes, access to {{3}} treatment is critical to their survival.', NULL, NULL, NULL, E'1.characterized, 2.occurs, 3.affordable', NULL, NULL),
  ('27a1e0c3-a3a3-58e4-b51d-95ac28227696'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '27a1e0c3-a3a3-58e4-b51d-95ac28227696'::uuid, 1, NULL, TRUE, 0, NULL, E'Community Garden Project', E'You''ve organized a community garden project with your neighbors, and everyone''s excited to start planting. However, upon arrival, you notice some garden beds are neglected, with weeds growing rampant. You need to remind everyone of their responsibility to maintain their assigned plots to ensure the success of the garden. What would you say to your neighbors?', 'b31c118a-4bf8-5c3b-842e-f913d6073093'::uuid, NULL, E'Hey everyone, thanks for being part of our project. But I noticed some of the garden beds are a bit neglected, with weeds taking over. Let''s all remember our responsibility to maintain our assigned plots. Weeding regularly and keeping the beds tidy will help ensure the success of our garden. Together, we can create a beautiful and thriving green space for everyone to enjoy. Let''s work together to keep our garden healthy and flourishing!', NULL, NULL, NULL),
  ('27a7838c-79a8-5277-82f3-edc0d02791cd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '27a7838c-79a8-5277-82f3-edc0d02791cd'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b5b497df-3baa-5f14-8d90-aa8598e87dff'::uuid, NULL, NULL, E'Students cannot leave the campus during the break time.', NULL, NULL),
  ('27a9c148-e8d1-59e9-969d-b0a800c53f31'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '27a9c148-e8d1-59e9-969d-b0a800c53f31'::uuid, 1, NULL, TRUE, 0, NULL, E'Deaf School', NULL, NULL, NULL, NULL, E'3, 2, 1, 4', NULL, NULL),
  ('27aa9bed-c38f-5a49-b16d-dc45a3d31300'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '27aa9bed-c38f-5a49-b16d-dc45a3d31300'::uuid, 1, NULL, TRUE, 0, NULL, E'A Cleanup', E'You''ve organized a beach cleanup event with your friends to help protect marine life and preserve the coastline. However, upon arriving at the beach, you notice some participants tossing their trash on the sand instead of using the designated bins. What would you say to your friends?', '7e0feb69-dfdd-5d27-90f7-d74c91870df2'::uuid, NULL, E'Hey everyone, thanks for joining us for the beach cleanup! Let''s remember to keep our beautiful coastline clean by using the designated trash bins. Tossing trash on the sand can harm marine life and spoil the beach for others. By disposing of our trash responsibly, we can help protect the environment and ensure everyone has a safe and enjoyable time at the beach. Let''s work together to keep our beaches clean and beautiful!', NULL, NULL, NULL),
  ('27ab1d62-878f-5adb-9157-12f2f58bbfcc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '27ab1d62-878f-5adb-9157-12f2f58bbfcc'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What word do we use to describe an accident or a disease which causes death?', '3fc5274a-9a4b-557c-8c5d-a53f84c5f1a4'::uuid, NULL, NULL, E'Fatal / deadly / lethal', NULL, NULL),
  ('27b51cff-c2f7-566b-bbe5-e63c4abfc6dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '27b51cff-c2f7-566b-bbe5-e63c4abfc6dd'::uuid, 1, NULL, TRUE, 0, NULL, E'New Program', E'California government has signed budget legislation that includes $45 million in one-time support for a statewide Animal Shelter Assistance Program. It will be administered by the Koret Shelter, at the University of California, Davis, Center for Companion Animal Health.\nThe funding reflects the governor’s commitment to providing resources that can help communities realize the state’s long-held policy that “no adoptable or treatable animal should be euthanized.” The Shelter set up a grant process, create and distribute educational materials and perform in-person consultations to help achieve the goals of the policy. And the administer of it believed that the program has the potential to change the situation for vulnerable animals.\n\nAccording to the passage, Animal Shelter Assistance Program ___ .', NULL, NULL, NULL, E'supports that treatable animals should not be euthanized', NULL, NULL),
  ('27c3c552-e15d-59ac-b137-7a9a49bc36df'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '27c3c552-e15d-59ac-b137-7a9a49bc36df'::uuid, 1, NULL, TRUE, 0, NULL, E'Housing', E'Housing fulfills the basic needs that people have for security, privacy and shelter. While the adequacy of housing is an important component of individual well-being, housing also has great impact on the nation’s economy, with its influence on investment levels, interest rates, building activity and employment.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('27c3e9f6-a10f-5281-b084-b99c854f8692'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '27c3e9f6-a10f-5281-b084-b99c854f8692'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4ccc5256-f0a6-5e70-917d-196037e3f79e'::uuid, NULL, NULL, E'The introduction of railway greatly contributed to the revolution of train industry.', NULL, NULL),
  ('27c74bf6-e666-52c5-a5e1-5c634f60551e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '27c74bf6-e666-52c5-a5e1-5c634f60551e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7480f907-7917-5455-b347-fbb7951321cc'::uuid, NULL, E'Physics is the subject of matter and energy.', NULL, NULL, NULL),
  ('27c7d185-870b-592a-9251-60339f8566ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '27c7d185-870b-592a-9251-60339f8566ca'::uuid, 1, NULL, TRUE, 0, NULL, E'Women and Man', E'Women today tend to live longer than men almost everywhere worldwide -- in some countries by more than a decade. Now, three centuries of historical records show that women don''t just outlive men in normal times: They''re also more likely to survive even in the worst of circumstances, such as famines and epidemics.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('27c8065b-e392-5c1f-b285-7a520d2c8768'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '27c8065b-e392-5c1f-b285-7a520d2c8768'::uuid, 1, NULL, TRUE, 0, NULL, E'Extrovert Ideal', E'Forget the "extrovert ideal" - the introverted workforce is quietly killing it. Sure, they may not be the loudest in the room, but don''t {{1}} their power. Introverts are the deep thinkers, the meticulous analysts, the creative minds who thrive on quiet contemplation. They''re the ones {{2}} information like sponges, listening intently, and processing details others miss. Yet, many companies fail to recognize this hidden power. They create environments that favor "talkers," overlooking the quiet firepower of their introverted employees. But it''s time for a change. Let''s provide spaces for introverts to thrive, where they can contribute their thoughtful ideas and meticulous work without feeling like they have to compete for the {{3}} .By embracing the introvert advantage, organizations can unlock a world of possibilities and gain a competitive {{4}} in an increasingly complex world.', NULL, NULL, NULL, E'1.underestimate, 2.absorbing, 3.spotlight, 4.edge', NULL, NULL),
  ('27c82808-683a-57c7-8095-8cf6ff1b502f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '27c82808-683a-57c7-8095-8cf6ff1b502f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '94631e81-2013-50b4-bc69-c3fbbd60fb13'::uuid, NULL, E'The fire ruined many plants in that place, causing severe destruction.', NULL, NULL, NULL),
  ('27c92b7e-86bd-5945-b8ff-d19dff92c7a9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '27c92b7e-86bd-5945-b8ff-d19dff92c7a9'::uuid, 1, NULL, TRUE, 0, NULL, E'Tissuing Engineering', NULL, '36237b08-1372-5aa8-9ce5-51ba02206c51'::uuid, NULL, E'Tissuing engineering, what is it? It''s an emerging field, interdisciplinary field that combines engineering and life sciences to create functional biological structures that can restore and improve tissue function. Examples include bladders, trachea blood vessels and if you look at it, printing as a technology has also gone through the revolution and well it''s been around for hundreds of years. In the last couple of decades, it''s been a new dimension. We can now print layer by layer in materials ranging from plastic to metal, to concrete, to chocolate, from the smallest scales to the largest. If you take 3D printing and we combine it with biology, we have bio-printing where the building blocks our cell aggregates where we called bio-ling particles that are composed of thousands of cells that can fuse together into different shapes, these geometries can include multi-layered sheets, such as skin, branching tubes for vasculature and the sophistication of this manufacturing technology improves daily to include different cell types and different shapes. And now why is it important, the pharmaceutical industry at the moment is in a moment of crisis. It spends more money each year on R&D, but has fewer drugs to show for it. It takes more than a decade, more than a billion of dollars to develop a new drug and the cost of a failure can be measured in hundreds of millions of dollars.', NULL, NULL, NULL),
  ('27cd00b4-1210-5b29-8840-949cc325aa68'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '27cd00b4-1210-5b29-8840-949cc325aa68'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8b7eb3a4-8b21-5026-aea2-c0ebc2585704'::uuid, NULL, E'She taught me to be less critical of other people.', NULL, NULL, NULL),
  ('27d0c30b-2448-5e1f-9c44-f4eb603b15fc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '27d0c30b-2448-5e1f-9c44-f4eb603b15fc'::uuid, 1, NULL, TRUE, 0, NULL, E'Flu', E'As millions of people prepare to travel and {{1}} for the holidays, public health officials are concerned that the worst is still ahead. Hospitals this winter are {{2}} the simultaneous threat of Covid, flu and RSV for the first time. Circulation of flu and RSV was very low during the pandemic due to widespread masking and social distancing implemented in {{3}} to Covid. But as most people return to normal life, traveling and gathering largely unmasked, all three viruses are circulating widely. Public health officials have said many people are probably more {{4}} to flu and RSV this year because they weren’t infected the past two years, which means their immunity is lower.', NULL, NULL, NULL, E'1.gather, 2.facing, 3.response, 4.vulnerable', NULL, NULL),
  ('27d1d0ec-4465-5fbc-9f74-b35111b7c58e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '27d1d0ec-4465-5fbc-9f74-b35111b7c58e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0f956636-9c83-5e21-8524-6d43495d9668'::uuid, NULL, NULL, E'Balancing coursework and a part-time job requires effective time management.', NULL, NULL),
  ('27dec066-fdeb-5f38-9c5c-6338dec15067'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '27dec066-fdeb-5f38-9c5c-6338dec15067'::uuid, 1, NULL, TRUE, 0, NULL, E'Goal Pursuit', E'Whatever happens, we should keep trying and never stop pursuing our goals. To what extent do you agree or disagree? Discuss it with your own experience.', NULL, NULL, NULL, NULL, 200, 300),
