  ('280765bc-f5cd-5dea-a7e1-f3d2345c05ef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '280765bc-f5cd-5dea-a7e1-f3d2345c05ef'::uuid, 1, NULL, TRUE, 0, NULL, E'Brain', E'The brain is divided into its ''hemispheres'' by a prominent groove. At the base of this lies nerve fibers which enable these two halves of the brain to communicate with each other. But the left hemisphere usually controls movement and sensation in the right side of the body, while the right hemisphere similarly controls the left side of the body.', NULL, NULL, NULL, NULL, NULL, NULL),
