  ('28151c90-93c5-53be-863c-cd4b1475a4b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '28151c90-93c5-53be-863c-cd4b1475a4b2'::uuid, 1, NULL, TRUE, 0, NULL, E'Sugar and Fat', E'Much of our food is increasingly {{1}} to be irresistible to us. Experts say this trend has long-term health consequences. Indulgent dishes {{2}} us with fat and sugar can feel impossible to avoid, especially during the holidays. Experts confirm it’s more than a feeling: Half a century of food trends has created an environment where more than half the food {{3}} by American adults is ultra-processed.', NULL, NULL, NULL, E'1.manufactured, 2.enticing, 3.consumed', NULL, NULL),
  ('28191fdd-1615-5624-b224-458f953b6e37'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '28191fdd-1615-5624-b224-458f953b6e37'::uuid, 1, NULL, TRUE, 0, NULL, E'Line Engraving', E'Line engraving on metal, which, to a great extent, was a development of the goldsmith’s craft of ornamenting armor and precious metals, did not emerge as a print-making technique until well into the 15th century. Copper, the metal mainly used for engraving, was expensive, and engraving itself was laborious and took a long time.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('281b2c96-737b-5152-ac19-942a981e08e0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '281b2c96-737b-5152-ac19-942a981e08e0'::uuid, 1, NULL, TRUE, 0, NULL, E'Rainforest', E'In the rainforest, there {{1}} more than two hundred species well {{2}} to science that {{3}} benefits for people. This high {{4}} of biodiversity is one reason Malaysia is often studied for its ecological richness.', NULL, NULL, NULL, E'1.can be, 2.known, 3.contain, 4.complexity', NULL, NULL),
  ('281b59a7-1a58-5d02-b47c-78dc3f75c706'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '281b59a7-1a58-5d02-b47c-78dc3f75c706'::uuid, 1, NULL, TRUE, 0, NULL, E'Assignment Extension', E'You’ve been given a deadline for an assignment, but due to a personal emergency, you need more time to finish it. How would you approach your professor to request an extension and ensure the situation is handled appropriately? What would you say?', 'e7cc02ef-de32-559d-ae32-087ee2f3528a'::uuid, NULL, E'Respected professor, I hope you are doing well.\nI would like to discuss an issue we have encountered with my assignment deadline.\nIt appears that I met an unexpected personal emergency, so I need extra time to complete this assignment.\nI would appreciate your opinion on this matter. Thank you for your consideration.', NULL, NULL, NULL),
  ('281cebc1-49f9-50ab-9cb3-8cebabbc8ca2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '281cebc1-49f9-50ab-9cb3-8cebabbc8ca2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6fd7a4a0-4b25-54da-a81b-dc2ff0433d2a'::uuid, NULL, NULL, E'The student service center is located on the main campus behind the library.', NULL, NULL),
  ('282190b0-9134-5144-8c96-ad87931f241e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '282190b0-9134-5144-8c96-ad87931f241e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bd3aea76-7292-5623-b1ae-638d9753742b'::uuid, NULL, E'Please make sure you use the standard form of quotation.', NULL, NULL, NULL),
  ('282bb712-6874-531b-8e0e-59e5e1c3d313'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '282bb712-6874-531b-8e0e-59e5e1c3d313'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '202ddbba-4a24-5256-9bd5-00d3a3bd0892'::uuid, NULL, NULL, E'The university theater group will be performing in the concert hall.', NULL, NULL),
  ('282dad4d-9874-5adf-87aa-23e2818470af'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '282dad4d-9874-5adf-87aa-23e2818470af'::uuid, 1, NULL, TRUE, 0, NULL, E'Best Managers', NULL, '47af131b-7501-5805-b2f2-64720a384a97'::uuid, NULL, E'Managers usually work long hours, so they don''t have time to read about other firms or broaden their perspectives. This reality of their daily grind creates a crucial need for preparation before they step into the role. It''s important to study this while in university. Ideas cultivated in university and the ability to have broad perspectives should be regarded as generic skills for managers. University is where future managers are exposed to a wide range of theories, case studies, and innovative thinking from various industries, which is exactly what their busy schedules will later limit. This is where they systematically acquire the essential toolkit for leadership. They should acquire organizational skills and professional knowledge. That''s why the best managers are not necessarily the most experienced. While experience is valuable, it does not automatically equate to strategic vision or effective leadership. A person might be excellent at their specific job but lack the broader perspective to lead a diverse team. This is why people who work their way up the ladder should not be considered as managers by default.', NULL, NULL, NULL),
  ('282f2bd7-7f52-5062-a827-08c4f53bb789'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '282f2bd7-7f52-5062-a827-08c4f53bb789'::uuid, 1, NULL, TRUE, 0, NULL, E'AI and Job', E'To what extent do you think artificial intelligence poses a threat to human jobs?', NULL, NULL, E'I strongly believe that artificial intelligence poses a significant threat to human jobs in the current technological landscape. As AI continues to advance, concerns arise regarding the potential displacement of workers due to automation and the need for reskilling to adapt to evolving workforce demands.\nOne critical aspect of AI''s threat to human jobs is its capability to automate routine and repetitive tasks traditionally performed by humans. As AI technologies become more sophisticated, they can efficiently handle tasks that were once exclusive to human labor, leading to the displacement of workers in various industries. The automation of repetitive tasks poses a significant challenge to job security for individuals in roles susceptible to AI-driven automation.\nFurthermore, the advancements in AI could result in job displacement, particularly in industries where tasks can be efficiently automated. The rapid integration of AI technologies may lead to job redundancies as companies seek to streamline operations and increase efficiency through automation. This shift necessitates a focus on reskilling and adaptation for workers to remain competitive in the workforce and transition into roles that complement AI technologies.\nIn conclusion, the increasing integration of artificial intelligence poses a tangible threat to human jobs through automation, job displacement, and the demand for reskilling. As AI technologies continue to evolve, it is imperative for individuals and organizations to proactively address the challenges posed by AI-driven changes in the workforce. By acknowledging the potential impact of AI on human jobs and investing in reskilling initiatives, we can mitigate the adverse effects and navigate the evolving landscape of work in the age of artificial intelligence.', NULL, 200, 300),
  ('28395ed2-8768-5ac0-af02-de5dc40191bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '28395ed2-8768-5ac0-af02-de5dc40191bd'::uuid, 1, NULL, TRUE, 0, NULL, E'Arrow Bamboo', NULL, NULL, NULL, NULL, E'2, 1, 3, 4', NULL, NULL),
