  ('2839f885-93f6-57d8-91a6-790f118e2c23'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2839f885-93f6-57d8-91a6-790f118e2c23'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which continent is the southernmost part of Earth?', '5be8ddec-deee-5aa8-b0a7-0a88aeca68b1'::uuid, NULL, NULL, E'Antarctica', NULL, NULL),
  ('28484974-1afa-5f12-8e1c-97513d5d434a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '28484974-1afa-5f12-8e1c-97513d5d434a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd89bfec0-d187-5e4d-a321-4561c9a5be87'::uuid, NULL, E'You must include a statement that you are taking all courses through distance education.', NULL, NULL, NULL),
  ('28561e1b-15f8-5e24-9f50-bd351ca8e9b5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '28561e1b-15f8-5e24-9f50-bd351ca8e9b5'::uuid, 1, NULL, TRUE, 0, NULL, E'Acid Rain', E'Acid deposition can be caused by natural sources such as volcanoes, but it is mainly caused by the {{1}} of sulfur dioxide and nitrogen oxide during fossil fuel combustion. When these gases are discharged into the atmosphere, they react with the water, oxygen, and other gases already present there to form sulfuric acid, ammonium nitrate, and nitric acid. These acids then {{2}} over large areas because of wind patterns and fall back to the ground as acid rain or other forms of precipitation. The gases most responsible for acid deposition are a byproduct of electric power generation and the burning of coal. As {{3}} , man-made acid deposition began becoming a significant issue during the Industrial Revolution. Although it was discovered in the 1800s, acid deposition did not gain significant public attention until the 1960s, and the term "acid rain" was coined in 1972. Public attention {{4}} increased in the 1970s when the "New York Times" published reports about problems occurring in the Hubbard Brook Experimental Forest in New Hampshire.', NULL, NULL, NULL, E'1.release, 2.disperse, 3.such, 4.further', NULL, NULL),
  ('2857d864-3def-5106-9d3c-2abff2d14012'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '2857d864-3def-5106-9d3c-2abff2d14012'::uuid, 1, NULL, TRUE, 0, NULL, E'Drug Resistance', NULL, NULL, NULL, NULL, E'2, 4, 1, 3', NULL, NULL),
  ('28596ae5-7243-596f-bc4e-af90dea0a6f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '28596ae5-7243-596f-bc4e-af90dea0a6f0'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the story a person tells to make people laugh?', '85257a60-7821-56c0-9895-b2fbdd28ee28'::uuid, NULL, NULL, E'Joke', NULL, NULL),
  ('285a5cf1-3cef-5411-b3bd-c10045d345d1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '285a5cf1-3cef-5411-b3bd-c10045d345d1'::uuid, 1, NULL, TRUE, 0, NULL, E'Learning and Performance', NULL, 'd7d43328-a9b4-5ace-bf75-768c8defb395'::uuid, NULL, E'What I’ve learned is that the most effective people and teams in any domain do something we can all emulate. They go through life deliberately alternating between two zones: the learning zone and the performance zone. The learning zone is when our goal is to improve. Then we do activities designed for improvement, concentrating on what we haven’t mastered yet, which means we have to expect to make mistakes, knowing that we will learn from them. That is very different from what we do when we’re in our performance zone, which is when our goal is to do something as best as we can, to execute. Then we concentrate on what we have already mastered and we try to minimize mistakes. Both of these zones should be part of our lives, but being clear about when we want to be in each of them, with what goal, focus and expectations, helps us better perform and better improve. The performance zone maximizes our immediate performance, while the learning zone maximizes our growth and our future performance. The reason many of us don’t improve much despite our hard work is that we tend to spend almost all of our time in the performance zone. This hinders our growth, and ironically, over the long term, also our performance.', NULL, NULL, NULL),
  ('285b7f56-3406-5faf-9b32-81bcc325cfa3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '285b7f56-3406-5faf-9b32-81bcc325cfa3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '75f323b7-4bb8-54df-b9dc-7fcbc0a525ae'::uuid, NULL, NULL, E'Businesses must adapt to the general data protection regulations.', NULL, NULL),
