  ('2874e277-16bc-501d-8adb-5e5aa519179a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '2874e277-16bc-501d-8adb-5e5aa519179a'::uuid, 1, NULL, TRUE, 0, NULL, E'Unregulated Individuals', E'Unlike businesses, unregulated individuals do not have to follow certain regulations and this can lead to poorer and {{1}} quality of goods and services and a higher risk of {{2}} . Nevertheless, in the consumerist society we live in today, the increased opportunities to sell on our unwanted and {{3}} goods can lead to a lesser impact on our environment.', NULL, NULL, NULL, E'1.inconsistent, 2.fraud, 3.underused', NULL, NULL),
  ('2876432d-a8aa-5f3c-abd1-62eae51c66a9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2876432d-a8aa-5f3c-abd1-62eae51c66a9'::uuid, 1, NULL, TRUE, 0, NULL, E'Plato', E'Plato often explores the father-son relationship and whether a father''s interest in his sons has anything to do with how well his sons turn out. A boy''s social identity in ancient Athens was determined by his family identity, and Plato often refers to his characters in terms of their parental and fraternal relationships. Socrates was not a family man and considered himself as his mother''s son.', NULL, NULL, NULL, NULL, NULL, NULL),
