  ('28780fd6-391c-5072-8ae8-00d3816ab5d4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '28780fd6-391c-5072-8ae8-00d3816ab5d4'::uuid, 1, NULL, TRUE, 0, NULL, E'Bilingual Education', E'Bilingual education is a valuable tool for preparing students for a globalized world. It helps students develop language proficiency in two or more languages, enhances cognitive skills, and promotes cultural understanding. Bilingual education programs can provide students with a competitive advantage in the job market and help them become more effective communicators.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('28783627-6f1e-5071-99ee-0e8b8020ca77'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '28783627-6f1e-5071-99ee-0e8b8020ca77'::uuid, 1, NULL, TRUE, 0, NULL, E'Pop Mega-stars', E'A music student at the University of Salford who wrote a song in two weeks is celebrating {{1}} being featured on a compilation album produced by Metropolis Studios. Pop mega-stars including Adele, Michael Jackson and Sir Elton John have all recorded music at the world-famous Metropolis Studios. Last year, the recording studios set {{2}} compiling an album called ''Lost Songs'', which features songs from relatively unknown musicians. First-year student Zak Taylor Fray decided to submit his song demo to be included in Volume Two of the Lost Songs album which was released this year, after he saw {{3}} successful Volume One had been. Zak 24, said: ''I found this competition when simply {{4}} the internet for songwriting competitions one day, and was lucky that there was still {{5}} to enter. It amazes me that people who have worked with huge pop stars thought my song was good and worth something.''', NULL, NULL, NULL, E'1.after, 2.about, 3.how, 4.searching, 5.time', NULL, NULL),
  ('287b66d0-07c6-5944-b6e1-ed11bc7f2e64'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '287b66d0-07c6-5944-b6e1-ed11bc7f2e64'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a507bfff-3d5d-5b0e-8fcd-6f6898d9e8a2'::uuid, NULL, E'More than a hundred firemen are still trying to put out the fire.', NULL, NULL, NULL),
