  ('2a208132-4c6b-563c-af68-e65a29b30cca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '2a208132-4c6b-563c-af68-e65a29b30cca'::uuid, 1, NULL, TRUE, 0, NULL, E'Cancer', E'Cancer is a large group of diseases that can start in almost any organ or tissue of the body when abnormal cells grow {{1}} , go beyond their usual boundaries to {{2}} adjoining parts of the body and spread to other organs. The latter process is called metastasizing and is a major {{3}} of death from cancer.', NULL, NULL, NULL, E'1.uncontrollably, 2.invade, 3.cause', NULL, NULL),
