  ('2b57f08d-47c4-5d86-9667-74046afcc7c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2b57f08d-47c4-5d86-9667-74046afcc7c6'::uuid, 1, NULL, TRUE, 0, NULL, E'Internet', E'The internet has grown in importance by many folds, over the process of decade. Its importance in the education world can now never be undermined. Despite the chances of fraud and drawbacks, the use of the internet is like a blessing for students. Today, the internet is something that is present in almost everything we use.', NULL, NULL, NULL, NULL, NULL, NULL),
