  ('2bc53afa-feee-541d-aab0-afef6a27474e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2bc53afa-feee-541d-aab0-afef6a27474e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '636cfc53-722c-5516-a19f-e1f27bf3e00a'::uuid, NULL, E'To acquire a copy of the presentation, please go to my website.', NULL, NULL, NULL),
  ('2bc61be6-c538-5730-aa3c-f0693b1ce15e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2bc61be6-c538-5730-aa3c-f0693b1ce15e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1b78d809-c0f1-542a-8d97-21e4506ee00d'::uuid, NULL, NULL, E'Students of the first year usually live on campus.', NULL, NULL),
  ('2bd14fd7-392f-50e2-af25-79d50e7144fc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '2bd14fd7-392f-50e2-af25-79d50e7144fc'::uuid, 1, NULL, TRUE, 0, NULL, E'Social Influence', E'If you want to guess how many jelly beans are in a jar, you should ask your friends. Then average their answers. Because a group guess is often more accurate than that of any one individual. Just don''t let them peek at each other''s responses. Because a new study shows that social influence can sway people''s {{1}} and render the crowd {{2}} . The work appears in the Proceedings of the National Academy of Sciences .\nCrowd wisdom is actually a statistical phenomenon. Gather enough estimates and the wild guesses cancel each other out, bringing you closer to the answer. But psychology and statistics don''t {{3}} . And knowing what your peers think doesn''t make you any smarter.\nEuropean scientists asked volunteers to estimate statistics like the population density of Switzerland. Each person got five guesses. Some were shown their peers'' answers and others weren''t. Turns out that seeing others'' estimates led to a lot of second guessing, which {{4}} the range of the group''s responses and pointed them in the wrong {{5}} . Even {{6}} , knowing that others said the same thing made everyone more confident they were right. So there is wisdom in numbers—as long as those numbers keep quiet `til they''re counted.', NULL, NULL, NULL, E'1.estimate, 2.incorrect, 3.mix, 4.narrowed, 5.direction, 6.worse', NULL, NULL),
  ('2bd665a0-7cac-5003-85e6-7d2b033020fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2bd665a0-7cac-5003-85e6-7d2b033020fe'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0891aade-c8ec-59ff-80de-347b4ca3ecb9'::uuid, NULL, NULL, E'Universities should help students to prepare for their future career.', NULL, NULL),
  ('2bd7d1cc-4193-560d-b30b-45afd2e102f6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2bd7d1cc-4193-560d-b30b-45afd2e102f6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c7284d79-8c74-5c88-89af-4bb5c171d508'::uuid, NULL, NULL, E'You should draw your graph on a separate page.', NULL, NULL),
  ('2bde67ed-75d3-5dcd-bcda-131ae9b1a40a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2bde67ed-75d3-5dcd-bcda-131ae9b1a40a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '52309ce8-d0fa-595e-b63b-8e52381e9a90'::uuid, NULL, NULL, E'Psychologists say that what we expect to happen influences our behaviors.', NULL, NULL),
  ('2bdf6dd0-f21e-514b-8ab9-49a790333423'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2bdf6dd0-f21e-514b-8ab9-49a790333423'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the animals kept in a farm?', 'cc1caead-2aba-54ab-921c-5183f4060ff9'::uuid, NULL, NULL, E'Livestock', NULL, NULL),
  ('2be5bcb6-822a-5373-b643-9bd3662d369a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '2be5bcb6-822a-5373-b643-9bd3662d369a'::uuid, 1, NULL, TRUE, 0, NULL, E'Art and Science', E'Advertising is both an art and a science, combining creativity and strategy to convey messages and influence consumer behavior. In a world inundated with advertisements, the challenge lies in creating impactful and memorable campaigns that resonate with the target audience.\nCreativity is at the heart of successful advertising. Eye-catching visuals, compelling storytelling, and memorable slogans can make an advertisement stand out from the crowd. Creative advertisements not only capture attention but also leave a lasting impression, making consumers more likely to remember the brand or product.\nHowever, creativity alone is not enough. Effective advertising also relies on a deep understanding of consumer behavior and market dynamics. Market research, data analysis, and consumer insights are crucial components of the advertising process. By identifying the needs, preferences, and motivations of their target audience, advertisers can tailor their messages to elicit desired responses.\nIn the digital age, advertising has evolved with the advent of online platforms and social media. Digital advertising allows for precise targeting, ensuring that messages reach the right people at the right time. It also enables interactivity, engagement, and real-time feedback, enhancing the overall effectiveness of campaigns.\nEthical considerations are another essential aspect of advertising. Advertisers must strike a balance between promoting their products or services and respecting consumer privacy and rights. Misleading or manipulative advertising practices can damage brand reputation and erode consumer trust.\nIn conclusion, effective advertising requires a harmonious blend of creativity and strategy. Creative elements capture attention and leave a lasting impression, while data-driven insights ensure that messages are tailored to resonate with the target audience. As the advertising landscape continues to evolve, ethical considerations and digital innovations will shape the future of the industry.', NULL, NULL, E'Effective advertising combines creativity and strategy, utilizing compelling visuals and storytelling to capture attention and leave a lasting impression while relying on data-driven insights and ethical considerations to ensure messages resonate with the target audience and respect consumer rights in the ever-evolving digital advertising landscape.', NULL, 5, 75),
  ('2be710c2-6907-54e1-b0ec-048fcfc82b3e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2be710c2-6907-54e1-b0ec-048fcfc82b3e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '55e63322-1410-5799-ad79-c720ce53924f'::uuid, NULL, NULL, E'Don''t forget your highlighter and book for class on Thursday.', NULL, NULL),
  ('2bee6cea-1edb-59f7-bd4b-13a357ca4c12'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2bee6cea-1edb-59f7-bd4b-13a357ca4c12'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Who is the Swiss greatest scientist in physics?', '40a750e9-9571-5ae9-8a17-b2408be7ed2c'::uuid, NULL, NULL, E'Einstein', NULL, NULL),
  ('2bf52343-8c4c-5c8a-b3c8-70ac321e1196'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2bf52343-8c4c-5c8a-b3c8-70ac321e1196'::uuid, 1, NULL, TRUE, 0, NULL, E'Molecular Crystals', E'A team of researchers has discovered molecular crystals capable of capturing iodine — one of the most common radioactive fission products — and other pollutants. The versatile crystals could be used for nuclear waste management and other energy-related applications and move the world closer to a net-zero future.', NULL, NULL, NULL, NULL, NULL, NULL),
