  ('2c00e7b2-8bfb-5a72-932a-38d027555672'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '2c00e7b2-8bfb-5a72-932a-38d027555672'::uuid, 1, NULL, TRUE, 0, NULL, E'Per Capita Income', E'To understand how many inhabitants of a country are poor, it is not enough to know a country''s per capita {{1}} .The number of poor people in a country and the {{2}} quality of life depend on how equally or unequally income is {{3}} across the population. In Brazil and Hungary, for {{4}} ,per capita income levels are quite comparable, but the {{5}} of poverty in Brazil is much higher.', NULL, NULL, NULL, E'1.income, 2.average, 3.distributed, 4.example, 5.incidence', NULL, NULL),
  ('2c181824-e1f0-56fa-b882-ebb43ad6648a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2c181824-e1f0-56fa-b882-ebb43ad6648a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9a33484e-44a2-5fb3-99b6-b439c23e118f'::uuid, NULL, NULL, E'Researchers say many students feel stressed and it affects academic results.', NULL, NULL),
  ('2c1be8b6-b9c7-585c-b7f1-c87e6cb3c02f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2c1be8b6-b9c7-585c-b7f1-c87e6cb3c02f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4a16a51b-9a09-570e-8aa7-cda5447ba812'::uuid, NULL, NULL, E'Answering some questions is needed to change your password.', NULL, NULL),
  ('2c2063c7-b47d-51e7-b14a-6b6a611ac29b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2c2063c7-b47d-51e7-b14a-6b6a611ac29b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f9c6331b-0ea3-582a-bb79-9cd223323492'::uuid, NULL, E'Tests should be administered by a medical expert.', NULL, NULL, NULL),
  ('2c232d2a-89d4-5c25-a8e9-ce32e994f8fa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '2c232d2a-89d4-5c25-a8e9-ce32e994f8fa'::uuid, 1, NULL, TRUE, 0, NULL, E'Successful Qualities', E'The qualities that a person needs to become truly successful cannot be learned at university or in a similar educational institution. To what extent do you agree or disagree?', NULL, NULL, E'The pursuit of true success is a multi-faceted journey that transcends the confines of traditional educational institutions. I firmly believe that the qualities essential for genuine success cannot be fully acquired within the confines of a university or similar educational setting. Real-world experiences, challenges, and practical learning opportunities play a pivotal role in shaping individuals into truly successful beings.\nSuccess often requires real-world experiences that offer invaluable lessons and insights not attainable in educational settings. Practical encounters outside the classroom provide individuals with a deeper understanding of their chosen fields, equipping them with essential skills for navigating the complexities of professional life. These real-world experiences empower individuals to make informed decisions based on the realities they encounter, fostering a practical and insightful approach to success.\nMoreover, facing challenges and setbacks beyond formal education fosters resilience and determination, critical attributes for achieving genuine success. Adversities encountered outside academic environments test individuals'' perseverance, adaptability, and problem-solving capabilities. These challenges serve as catalysts for personal growth, nurturing a resilient mindset and unwavering determination to overcome obstacles on the journey toward success.\nIn conclusion, the qualities necessary for genuine success extend beyond the realms of formal education. Real-world experiences, resilience forged through challenges, and innovative problem-solving skills acquired outside academic settings are indispensable for attaining true success. Embracing these opportunities for growth and learning outside traditional educational institutions is paramount for individuals striving to achieve excellence in their personal and professional endeavors.', NULL, 200, 300),
  ('2c314842-e076-5c96-9eb9-cebfc8a4522d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2c314842-e076-5c96-9eb9-cebfc8a4522d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the ancient Indian language in which many Hindu scriptures are written?', '6dc0aae6-bb79-53ad-88c0-3ed23fae7169'::uuid, NULL, NULL, E'Sanskrit', NULL, NULL),
