  ('2c729a9e-6eb3-562f-b517-e5cde4ebc6a1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2c729a9e-6eb3-562f-b517-e5cde4ebc6a1'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7a9b1c17-5d3e-5065-ad8d-6deccc3a5d8c'::uuid, NULL, NULL, E'Digital scans of archived materials are provided with a small fee.', NULL, NULL),
  ('2c7a1784-c5cf-57f3-80d3-f662b43f3bac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '2c7a1784-c5cf-57f3-80d3-f662b43f3bac'::uuid, 1, NULL, TRUE, 0, NULL, E'Bacteria Sinus Infections', E'This is the season when {{1}} sinus infections run rampant. But some people are better able to ward off that malady. And they can be identified by their taste buds. Because those of us who can better detect bitter flavors may also be better equipped to fight off upper {{2}} tract infections. The finding is in the Journal of Clinical Investigation.\nIt turns out that those bitter taste {{3}} aren''t just in our mouths. They''re also in our noses. Being better able to sense bitterness may be a first line of defense against bacteria. That''s because those bacteria {{4}} taste bitter to us. So when taste receptors in our airways sense a bitter flavor they roll out the {{5}} . Cilia lining our sinuses beat faster, to sweep away germs. And bacteria-killing nitric oxide gets released into our nasal {{6}} . Better bitter sensing means a bigger response.\nIt''s one reason researchers at the Monell Chemical Senses Center are trying to come up with a universal taste test—a standardized measurement of how well we sense flavors. Because one key to living healthier could be on the tip of your tongue.', NULL, NULL, NULL, E'1.bacterial, 2.respiratory, 3.receptors, 4.actually, 5.defenses, 6.cavities', NULL, NULL),
  ('2c809849-4dcc-55d8-8ac7-3fd13731857f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2c809849-4dcc-55d8-8ac7-3fd13731857f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '725d9ade-ec9d-5d38-b942-90a89a2511be'::uuid, NULL, E'But they haven''t come to widespread use yet.', NULL, NULL, NULL),
  ('2c82554e-8940-568c-86e5-0b807b1c40ba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2c82554e-8940-568c-86e5-0b807b1c40ba'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the color of the sky on a clear day?', '6ca97457-5a8b-5b61-8627-122ae4b2a78d'::uuid, NULL, NULL, E'Blue', NULL, NULL),
