  ('2c85fa5f-b78b-5177-9d7f-2310cc206cdb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2c85fa5f-b78b-5177-9d7f-2310cc206cdb'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the largest land animal living in Africa or India?', '9ad908a3-b617-5a55-9d15-3600b9115dbf'::uuid, NULL, NULL, E'Elephant', NULL, NULL),
  ('2c921d0e-e711-5bf5-8164-883011dda8cf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2c921d0e-e711-5bf5-8164-883011dda8cf'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '17aadfdb-744e-5660-acd3-990cb1daa4a3'::uuid, NULL, NULL, E'Getting enough money for research is very important for universities.', NULL, NULL),
  ('2c9a10d4-9207-532c-bee5-28962e8f0ceb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '2c9a10d4-9207-532c-bee5-28962e8f0ceb'::uuid, 1, NULL, TRUE, 0, NULL, E'Birth Rate', E'In many countries, the birth rates are lowering, and the problems of an ageing population are serious. What are the causes and the effects of this phenomenon? what should we do to address these issues?', NULL, NULL, E'Low birth rates and an ageing population are becoming increasingly problematic issues in many countries around the world. This phenomenon has been caused by a combination of factors including economic pressures, changing social attitudes, and increased access to birth control. In this essay, we will explore the causes and effects of this phenomenon and discuss potential solutions to address these issues.\nOne of the main causes of low birth rates is the high cost of living and education. Many young couples are choosing to delay having children or have fewer children due to financial concerns. For example, in countries like Japan and South Korea, the cost of living is very high, and many young people are struggling to afford basic necessities such as housing and food. This financial pressure is causing many young couples to postpone starting a family or choose not to have children at all.\nAnother cause of low birth rates is changing social attitudes towards family and career. Many young people are prioritizing their careers over starting a family, which is leading to a decline in birth rates. This shift in priorities is due to a variety of factors, including increased access to education and career opportunities for women, as well as changing cultural norms around marriage and family. In some countries, such as Italy and Spain, there is a stigma attached to having children outside of marriage, which is contributing to lower birth rates.\nTo address the issues of low birth rates and ageing populations, governments and societies must take action. One potential solution is to increase incentives for having children, such as tax breaks or subsidies for childcare. Additionally, policies that support work-life balance, such as flexible work arrangements and parental leave, can help encourage young people to start families. Finally, encouraging immigration can help increase the population and diversity of the workforce. By taking these steps, we can help address the challenges posed by low birth rates and ageing populations and ensure a brighter future for generations to come.', NULL, 200, 300),
  ('2c9c777b-5732-5d15-b041-34aee31b0f0c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '2c9c777b-5732-5d15-b041-34aee31b0f0c'::uuid, 1, NULL, TRUE, 0, NULL, E'Wholeness of Thought', E'The writer, or, for that matter, the speaker conceives his thought whole, as a unity, but must express it in a line of words; the reader, or listener, must take this line of symbols and from it {{1}} the original wholeness of thought. There is {{2}} difficulty in conversation, because the listener receives innumerable cues from the physical expressions of the speaker; there is a dialogue, and the listener can {{3}} in at any time. The advantage of group discussion is that people can overcome linear sequence of words by {{4}} on ideas from different directions; which makes for wholeness of thought. But the reader is confronted by line upon line of printed symbols, without benefits of physical {{5}} and emphasis or the possibility of dialogue or discussion.', NULL, NULL, NULL, E'1.reconstruct, 2.little, 3.cut, 4.converging, 5.tone', NULL, NULL),
  ('2c9d36aa-ca6b-5888-80ce-334560d04daf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2c9d36aa-ca6b-5888-80ce-334560d04daf'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '82441e87-8f09-53cd-b3e4-5907de62017a'::uuid, NULL, NULL, E'Organic foods are cultivated without any synthetic chemicals, pesticides, or fertilizers.', NULL, NULL),
  ('2ca98121-b323-5edd-b2e7-3da2904e3e6d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2ca98121-b323-5edd-b2e7-3da2904e3e6d'::uuid, 1, NULL, TRUE, 0, NULL, E'Roman Army', E'There were two types of soldier in the Roman Army: the roman legionary and the auxiliaries. The legionaries were the very best soldiers and the auxiliaries were actually non-Roman citizens. Legionaries wore an undershirt made of linen and a woollen tunic. The linen helped the soldiers to stay cool while the wool helped to trap heat, keeping the soldiers warm.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('2cad7cde-d08b-5394-b2e9-a730eb17baa5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'HIGHLIGHT_CORRECT_SUMMARY', E'HIGHLIGHT_CORRECT_SUMMARY', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2cad7cde-d08b-5394-b2e9-a730eb17baa5'::uuid, 1, NULL, TRUE, 0, NULL, E'Sharks', E'A new investigation into shark populations in the waters off Australia has discoyered that there are two distinct species of Great White shark, one to the east and one to the west of Bass Strait. This was discovered by tagging large numbers of sharks in the coastal waters all round Australia. Rather to the investigators'' surprise, they found that while sharks from the east side certainly travelled to the west side of the continent and vice versa, they always returned to their home areas to breed. The two types of shark were found to have a distinct genetic make up, indicating that interbreeding has not taken place. The implication of these research findings is that sharks may be more susceptible to changes in local marine environments than had previously been thought.\n\nClick on the paragraph that best relates to the recording.', 'a476dffa-4299-5ad5-91d6-8ab9ff9f908e'::uuid, NULL, NULL, E'A recent research study has shown that Australian Great White shark populations have remained surprisingly distinct as, despite traveling long distances. these sharks do not breed away from their original areas. This means that local shark habitats may have a greater effect on sharks than has been believed up to now.', NULL, NULL),
  ('2caff7f2-079c-521a-9c11-1da44a2e21d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2caff7f2-079c-521a-9c11-1da44a2e21d8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the part powering a car, ship or an aircraft?', 'f1a26231-383c-56a5-ac0d-6b7f0576d547'::uuid, NULL, NULL, E'Engine', NULL, NULL),
  ('2cb0315f-46fd-59f0-b97e-2c3ebef1c7f2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '2cb0315f-46fd-59f0-b97e-2c3ebef1c7f2'::uuid, 1, NULL, TRUE, 0, NULL, E'Norwegian Oil Industry', E'The Norwegian Government is doing its best to keep the oil industry under control. A new law limits exploration to an area south of the southern end of the long coastline; production limits have been laid down (though these have already been raised); and oil companies have not been allowed to employ more than a limited number of foreign workers. But the oil industry has a way of getting over such problems, and few people believe that the Government will be able to hold things back for long. As one Norwegian politician said last week: “We will soon be changed beyond all recognition.”\n\nThe Norwegian Government would prefer the oil industry to __ .', NULL, NULL, NULL, E'slow down the rate of its development.', NULL, NULL),
  ('2cb0d23f-fcee-5726-9de0-54ca4d3b1639'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2cb0d23f-fcee-5726-9de0-54ca4d3b1639'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the yellow fruit that''s known for being a good source of potassium?', '6e7778ba-78c2-54c5-a14b-b4754f306e1d'::uuid, NULL, NULL, E'Banana', NULL, NULL),
