  ('2cb57788-2fb1-5b31-b368-f1a88a0a6d35'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2cb57788-2fb1-5b31-b368-f1a88a0a6d35'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call the clothing actors wear on the stage?', '06889c82-8638-53c9-945f-993abffd27ee'::uuid, NULL, NULL, E'Costume', NULL, NULL),
  ('2cbdeb59-8c4a-50bd-8e2b-822f57727d17'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2cbdeb59-8c4a-50bd-8e2b-822f57727d17'::uuid, 1, NULL, TRUE, 0, NULL, E'Turbine Blades', E'To withstand the forces of nature and the huge forces the rotation itself generates, blades are manufactured with a multilayer ‘coat of armour’. Typically, the outer layer erodes during operation and the inner layers can become detached. Although the lifespan of a turbine is theoretically 25 years, current medium-sized systems typically require extensive maintenance at about 10 years due to blade deterioration.', NULL, NULL, NULL, NULL, NULL, NULL),
