  ('2cdf4090-d297-502a-8fc5-567f9d1e5edd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2cdf4090-d297-502a-8fc5-567f9d1e5edd'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd39084d7-bd8e-5f63-8990-d86ef21820dd'::uuid, NULL, E'Email is quick and convenient.', NULL, NULL, NULL),
  ('2cdf6afd-b4f0-5cb9-9220-bcc50d1c4461'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2cdf6afd-b4f0-5cb9-9220-bcc50d1c4461'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a book containing writings on a particular theme?', 'abe0c539-df1e-569f-a5f5-d30d1e735d14'::uuid, NULL, NULL, E'Compilation / anthology', NULL, NULL),
  ('2ce610c9-f1f6-5eeb-871b-66cfb475f384'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '2ce610c9-f1f6-5eeb-871b-66cfb475f384'::uuid, 1, NULL, TRUE, 0, NULL, E'Age of Tree', NULL, NULL, NULL, NULL, E'1, 2, 4, 3', NULL, NULL),
  ('2ce63730-2557-506d-ad9d-0ad8785c1746'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '2ce63730-2557-506d-ad9d-0ad8785c1746'::uuid, 1, NULL, TRUE, 0, NULL, E'Cost of Victories', E'Across various fields, from education to business and politics, we''ve embraced a "win at all {{1}} "mentality, often leaving individuals emotionally, mentally, and physically damaged. This focus on the {{2}} result neglects the human cost of achieving these victories. It''s time we redefine success, focusing on developing champions in life, regardless of wins or {{3}} . This approach is about asking the right questions, focusing on the experience and process rather than just the outcome. Listening {{4}} , without the need to respond or be right, can unlock profound insights and healing, as seen with gymnast Kyla Ross, who shared her experience of abuse and found strength in {{5}} . We must redefine success beyond wins, fostering an environment where individuals feel valued, heard, and empowered.', NULL, NULL, NULL, E'1.costs, 2.end, 3.losses, 4.genuinely, 5.being heard', NULL, NULL),
  ('2ce89342-ba19-55bd-a64f-83230548dc13'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2ce89342-ba19-55bd-a64f-83230548dc13'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7691f168-f194-527b-b040-002744ae036b'::uuid, NULL, E'Levels of pollution present in the atmosphere are increasing, which is rather concerning.', NULL, NULL, NULL),
  ('2ce8c5ea-d616-5d35-a276-2cc31ace3837'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2ce8c5ea-d616-5d35-a276-2cc31ace3837'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which word can be used to describe an inexperienced person, fledgling or veteran?', '0e765ee2-ab9e-5c26-b00e-5563c2309c45'::uuid, NULL, NULL, E'Fledgling', NULL, NULL),
  ('2ce937e8-c5f3-5c5e-9e1f-2e0112c3c947'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2ce937e8-c5f3-5c5e-9e1f-2e0112c3c947'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e6d65b7f-f058-5554-9f01-c2949fbf86de'::uuid, NULL, E'Much of his research is driven by his natural curiosity and instincts.', NULL, NULL, NULL),
  ('2cea3615-8541-5210-8fa8-0f67124b988d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2cea3615-8541-5210-8fa8-0f67124b988d'::uuid, 1, NULL, TRUE, 0, NULL, E'Spider Silk', E'Spider silk is prized for its unrivaled strength and toughness. But figuring out a way to mass-produce it is no easy feat. Spiders cannot be put to work to pump out the fibers the way silkworms can: They’re extremely territorial and inclined to eat their neighbors, and they refuse to keep at the task for long.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('2cfa7fb3-dc80-55d3-bce8-7d5c992fadb2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2cfa7fb3-dc80-55d3-bce8-7d5c992fadb2'::uuid, 1, NULL, TRUE, 0, NULL, E'Reading Books', NULL, '4a47e0ec-b1ed-5d76-812c-ca72a4433bb4'::uuid, NULL, E'We’ve been taught that once we start something we have to finish it. And I think that so often we view books as this linear thing. Whereas I think a different view of books is, what information do I need out of book right now? Is that an entertainment read? Do I need to read from start to finish? Is it a read where I’m comparing different views on a similar problem? Especially across non-fiction. Am I comparing and contrasting two or three different authors’ argumentation or authors’ views on a particular angle to a subject? In which case, I might not need to read the whole book. I just need to read a chapter. But then I’ve gotten everything out of that book. The books are there to serve you, right? You own the book. The book is your property. It’s your mental property. It’s your physical property. And you can do with it what you want. You don’t have to feel bad about putting down a book. It’s the author’s job to pull you into the book. It’s your job to extract what you need out of the book. And I think that extracting what you need, you can just read the table of contents, read the introduction, maybe read the conclusion, and skim a little bit.', NULL, NULL, NULL),
  ('2cfad28a-123e-5301-903e-03e8ead9fd6a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2cfad28a-123e-5301-903e-03e8ead9fd6a'::uuid, 1, NULL, TRUE, 0, NULL, E'Low Participation', E'You''re the leader of a book club that has been meeting virtually for the past few months. Recently, you''ve noticed that participation has dropped, and fewer people are joining the discussions. You want to revive interest and encourage more members to actively participate in the book club''s meetings and discussions. What would you say to your club?', '05d2f6ab-473b-513c-974c-b593a6c10af9'::uuid, NULL, E'Lately, I''ve noticed our virtual meet-ups aren''t as bustling as before, and I miss seeing all your faces and hearing your insights. Let''s shake things up! How about next time we each bring a friend, or perhaps we could vote on a genre we''ve never explored together? I''m also thinking of introducing a monthly ''book of the month'' award based on our discussions. I believe we can make our book club even more engaging and fun.', NULL, NULL, NULL),
  ('2cfbf667-f4c2-58bb-9e87-bc49d32428bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2cfbf667-f4c2-58bb-9e87-bc49d32428bd'::uuid, 1, NULL, TRUE, 0, NULL, E'Altimeter', E'A simple barometric altimeter includes a sealed metal chamber, a spring, and a pointer that shows altitude in meters or feet. The chamber expands as air pressure decreases and contracts as it increases, bending the spring and moving the pointer. An altimeter can be mounted on an aircraft’s instrument panel or worn on a person’s wrist.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('2cfd2209-7fb3-595c-9248-63161e795f30'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2cfd2209-7fb3-595c-9248-63161e795f30'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do workers wear on their heads for safety when building a house?', '41069187-c1d2-5971-90b9-0d8ef942c0b5'::uuid, NULL, NULL, E'Helmet / casque / hard hat', NULL, NULL),
  ('2d090ad1-037b-59a0-a075-b443fc18da59'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2d090ad1-037b-59a0-a075-b443fc18da59'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '729d3f7d-b4d9-569b-9111-559f97ee4d15'::uuid, NULL, E'Online learning has become increasingly popular in recent years.', NULL, NULL, NULL),
  ('2d0933bd-f3fd-50d4-a1b5-1cb3d7aaab24'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2d0933bd-f3fd-50d4-a1b5-1cb3d7aaab24'::uuid, 1, NULL, TRUE, 0, NULL, E'Historian', E'As a historian, if you really want to understand the sensibilities of those who lived in the past, you must be like a novelist and get into the skins of your characters and think and feel as they do. You are asked to imagine what it''s like to be a peasant in medieval times, asking the sort of questions a peasant might ask. What the writer is saying is that a historian needs imaginative sympathy with ordinary people in the past.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('2d0bd71f-ed88-5d48-b324-809e491ef5d4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2d0bd71f-ed88-5d48-b324-809e491ef5d4'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd1c07757-4282-5f4a-bf69-74f06431326f'::uuid, NULL, E'Try to get through it as soon as possible.', NULL, NULL, NULL),
  ('2d0df21c-d1b1-5375-a533-fe3d2a789423'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '2d0df21c-d1b1-5375-a533-fe3d2a789423'::uuid, 1, NULL, TRUE, 0, NULL, E'Industrial Revolution', E'Do you believe that the industrial revolution was the main factor for problems in developed nations?', NULL, NULL, NULL, NULL, 200, 300),
  ('2d1408c9-d9b5-594b-b47e-438275e782f3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2d1408c9-d9b5-594b-b47e-438275e782f3'::uuid, 1, NULL, TRUE, 0, NULL, E'Girls v.s. Boys', E'Teenage girls are continuing to outperform boys in English while the gender gap in achievements in math and science has almost disappeared. The figures show that last year 80% of 14-year-old girls reached at least the expected level 5 in English, compared with 65% of boys. But in math, the girls are just 1% ahead of boys, while in science the difference is 2%.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('2d18c5cb-0257-533d-8a1c-220eba956118'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2d18c5cb-0257-533d-8a1c-220eba956118'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'de829895-0af8-5583-93de-4039d8555033'::uuid, NULL, E'We have booked a famous band for our wedding reception.', NULL, NULL, NULL),
  ('2d2507da-dac8-5bd9-92c2-b06d2252e320'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2d2507da-dac8-5bd9-92c2-b06d2252e320'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a group of people watching movies in the cinema?', '5a73232d-8330-5a2f-879f-40d00fb715c4'::uuid, NULL, NULL, E'Audience', NULL, NULL),
  ('2d2542f0-4b0e-59fd-a224-6de80106475b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2d2542f0-4b0e-59fd-a224-6de80106475b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '34617bac-bff3-585f-8eeb-60929bf78c0d'::uuid, NULL, NULL, E'Students build confidence in their critical thinking skills over time.', NULL, NULL),
  ('2d26fce5-58c3-5689-9f55-a937390d3e22'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '2d26fce5-58c3-5689-9f55-a937390d3e22'::uuid, 1, NULL, TRUE, 0, NULL, E'Settlements', E'Over the last ten thousand years there seem to have been two separate and conflicting building sentiments throughout the history of towns and cities. Specifically, {{1}} is the desire to start again, for a variety of reasons: an earthquake or a tidal wave may have demolished the settlement, or fire destroyed it, or the new city {{2}} a new political beginning. The other can be likened to the effect of a magnet: established settlements attract people, who {{3}} to come whether or not there is any planning for their arrival. The clash between these two sentiments is evident in every established city {{4}} its development has been almost completely accidental or is lost in history. Incidentally, many settlements have been planned from the beginning but, for a variety of reasons, no settlement followed the plan. A good example is Currowan, on the Clyde River in New South Wales, which was surveyed in the second half of the 19 th century, in expectation that people would come to establish agriculture and a small port. But no one came.', NULL, NULL, NULL, E'1.one, 2.marks, 3.tend, 4.unless', NULL, NULL),
  ('2d2ac0fe-46f3-5758-97b2-e7fee1a3bfc4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '2d2ac0fe-46f3-5758-97b2-e7fee1a3bfc4'::uuid, 1, NULL, TRUE, 0, NULL, E'Culture and Environment', E'It is important to preserve both the culture and environment of the places you visit, but some people think it is impossible to be a responsible tourist. To what extent do you agree or disagree?', NULL, NULL, NULL, NULL, 200, 300),
  ('2d2c1c0b-b05f-53d2-aa0f-a461c2616a56'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2d2c1c0b-b05f-53d2-aa0f-a461c2616a56'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a car that needs to be charged?', 'efc1c89f-206f-5894-a086-952fc4b7b3b4'::uuid, NULL, NULL, E'Electric car / electric vehicle', NULL, NULL),
  ('2d3590a2-bd51-58a1-8103-e3ba749d6389'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2d3590a2-bd51-58a1-8103-e3ba749d6389'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Language is usually expressed in two forms, spoken and?', '56b4194c-f00d-532a-aef5-83f55a743090'::uuid, NULL, NULL, E'Written', NULL, NULL),
  ('2d3b4d83-a52a-5858-bf39-d9f13588615e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '2d3b4d83-a52a-5858-bf39-d9f13588615e'::uuid, 1, NULL, TRUE, 0, NULL, E'Mona Lisa', E'The Mona Lisa attracts millions of visitors {{1}} year, who come to admire it in the Louvre. Leonardo da Vinci, {{2}} being a painter, was considered one of {{3}} of his era. The Mona Lisa is often {{4}} as the most famous painting in the world.', NULL, NULL, NULL, E'1.every, 2.as well as, 3.the best artists, 4.described', NULL, NULL),
  ('2d3d8a77-21fa-5631-b305-f86f442c6ede'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2d3d8a77-21fa-5631-b305-f86f442c6ede'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8e425265-f071-55b5-b251-ea128a728e3b'::uuid, NULL, E'In the future, the goal is to eliminate all vehicles with combustion engines.', NULL, NULL, NULL),
  ('2d3e835c-f457-5be6-8c25-f40311359fc3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '2d3e835c-f457-5be6-8c25-f40311359fc3'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-R', E'Jean Wagner''s most enduring contribution to the study of Afro-American poetry is his insistence that it be analyzed in a religious, as well as secular, frame of reference. The appropriateness of such an approach may seem self-evident for a tradition commencing with spirituals and owing its early forms, rhythms, vocabulary, and evangelical fervor to Wesleyan hymnals. But before Wagner a secular outlook that analyzed Black poetry solely within the context of political and social protest was dominant in the field.It is Wagner who first demonstrated the essential fusion of racial and religious feeling in Afro-American poetry. The two, he argued, form a symbiotic union in which religious feelings are often applied to racial issues and racial problems are often projected onto a metaphysical plane. Wagner found this most eloquently illustrated in the Black spiritual, where the desire for freedom in this world and the hope for salvation in the next are inextricably intertwined.\n\nIt can be inferred from the passage that, before Wagner, most students of Afro-American poetry did which of the following?', NULL, NULL, NULL, E'Ignored at least some of the historical roots of Afro-American poetry.', NULL, NULL),
  ('2d40e7ac-74ef-59b4-b4fe-218e7ba2356e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '2d40e7ac-74ef-59b4-b4fe-218e7ba2356e'::uuid, 1, NULL, TRUE, 0, NULL, E'Vitamin D', E'Vitamin D refers to a group of fat--soluble secosteroids responsible for enhancing intestinal absorption of calcium, iron, magnesium, phosphate and zinc. In humans, the most important compounds in this group are vitamin D3 and vitamin D2. Cholecalciferol and ergocalciferol can be ingested from the diet and from supplements. Very few foods contain vitamin D; synthesis of vitamin D (specifically cholecalciferol) in the skin is the major natural source of the vitamin. Dermal synthesis of vitamin D from cholesterol is dependent on sun exposure Vitamin D from the diet or dermal synthesis from sunlight is biologically inactive; activation requires enzymatic conversion (hydroxylation) in the liver and kidney.Evidence indicates the synthesis of vitamin D from sun exposure is regulated by a negative feedback loop that prevents toxicity, but because of uncertainty about the cancer risk from sunlight, no recommendations are issued by the Institute of Medicine (US), for the amount of sun exposure required to meet vitamin D requirements. Accordingly, the Dietary Reference Intake for vitamin D assumes no synthesis occurs and all of a person''s vitamin D is from food intake, although that will rarely occur in practice. As vitamin D is synthesized in adequate amounts by most mammals exposed to sunlight[citation needed], it is not strictly a vitamin, and may be considered a hormone as its synthesis and activity occur in different locations. Vitamin D has a significant role in calcium homeostasis and metabolism. Its discovery was due to effort to find the dietary substance lacking in rickets.', NULL, NULL, E'Synthesis of vitamin D, a group of fat, in which the most important compounds are vitamin D3 and vitamin D2, in the skin is the major natural source of the vitamin, with activation requiring enzymatic conversion, but it is not strictly a vitamin and may be considered a hormone as its synthesis and activity occur in different locations.', NULL, 5, 75),
  ('2d43f525-e40e-5f80-9431-81a76e8e8d80'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2d43f525-e40e-5f80-9431-81a76e8e8d80'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5de18a6d-32da-5f34-88a5-4ed9d07773ab'::uuid, NULL, NULL, E'The company''s profits have soared dramatically in recent months.', NULL, NULL),
  ('2d4e28d1-c48e-5b56-a3f1-e714d5273a5d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2d4e28d1-c48e-5b56-a3f1-e714d5273a5d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bc677dd8-9df2-55fa-994b-3c8443f7add4'::uuid, NULL, E'A letter was sent out to inform clients about the change in service prices.', NULL, NULL, NULL),
  ('2d4e6c42-a9a2-5e78-91e7-bb7647547d48'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2d4e6c42-a9a2-5e78-91e7-bb7647547d48'::uuid, 1, NULL, TRUE, 0, NULL, E'Microbial World', NULL, 'df7013f9-8f8a-537b-a619-ece00076d6bd'::uuid, NULL, E'As we embark on this intellectual voyage, let us turn our gaze to the microscopic universe that thrives within and all around us: the microbial world. These microorganisms are the unsung heroes of our planet, essential to the Earth''s life cycles. They are not merely passengers in the journey of life; they are its engineers, facilitating processes from digestion in our bodies to nutrient cycling in the oceans. Furthermore, the study of microbes opens a window to biotechnology''s potential, offering solutions to pressing problems like waste management and sustainable energy. The power of microorganisms is harnessed in bioreactors to clean our water and in the soil to enhance agricultural productivity. As we stand at the threshold of our careers, let''s acknowledge the profound impact of these tiny, yet mighty organisms. By exploring and understanding the microbial world, we can unlock secrets to both sustaining and enhancing life on our planet. Let''s dive into this miniature cosmos, for even the smallest life forms hold keys to the grandest of questions.', NULL, NULL, NULL),
  ('2d51baf6-5be5-5f89-bae3-e58dc92415ac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2d51baf6-5be5-5f89-bae3-e58dc92415ac'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2d00f48d-dc36-53f3-8938-3e2cfa2b3ab2'::uuid, NULL, NULL, E'A rising population means more trees are cut down.', NULL, NULL),
  ('2d52a0ec-a9fd-5233-959f-3dc8d6f395c1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2d52a0ec-a9fd-5233-959f-3dc8d6f395c1'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8e86cf2b-a954-5c84-8be4-0efee349528f'::uuid, NULL, NULL, E'Older studies were more about ideas than doing real experiments.', NULL, NULL),
  ('2d58598d-c8ae-5d87-bedf-b52bec498563'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '2d58598d-c8ae-5d87-bedf-b52bec498563'::uuid, 1, NULL, TRUE, 0, NULL, E'Poisonous Animals', E'Poisonous animals include most amphibians (that is, frogs, toads, salamanders, etc.), which carry around some amount of {{1}} on their skin and within their other {{2}} , such as the highly toxic poison {{3}} by various poison dart frogs. These chemicals are strong enough that they can be {{4}} to humans, so you would be wise to keep these creatures off your menu.', NULL, NULL, NULL, E'1.toxins, 2.tissues, 3.secreted, 4.deadly', NULL, NULL),
  ('2d59b178-5612-53c8-8086-cfaad62dab92'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '2d59b178-5612-53c8-8086-cfaad62dab92'::uuid, 1, NULL, TRUE, 0, NULL, E'Body Language', E'Diving into the world of body language, it''s a mix of universal signals and cultural puzzles. Sure, a smile might be your passport to friendliness worldwide, but venture into hand gestures or posture, and suddenly you''re in uncharted territory. {{1}} the peace sign for example; a simple twist of the wrist can flip its meaning entirely. It''s like navigating a social minefield where a wrong step, say, a misplaced thumbs-up or a casual gesture, could land you in a world of {{2}} .Body language is this fascinating secret code – sometimes it''s your best friend, making connections without a word, and other times, it''s like trying to crack a joke in a language you {{3}} know. It''s all about the context, making the dance between what we mean and what''s understood an adventure in itself, {{4}} with potential mishaps and moments of genuine connection.', NULL, NULL, NULL, E'1.Take, 2.misunderstanding, 3.barely, 4.filled', NULL, NULL),
  ('2d5cf4a7-40f0-55f4-ae30-d4c6649a1bc9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2d5cf4a7-40f0-55f4-ae30-d4c6649a1bc9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'eb24f286-4c80-55fb-80bb-c43f541bc890'::uuid, NULL, E'He needs to talk to you about your industrial architecture class.', NULL, NULL, NULL),
  ('2d645898-ac58-502b-b5de-4e64a095da22'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2d645898-ac58-502b-b5de-4e64a095da22'::uuid, 1, NULL, TRUE, 0, NULL, E'Sea Levels', E'Paul Goddard, an assistant research scientist in the Department of Earth and Atmospheric Sciences at the College of Arts and Sciences at Indiana University, has stated that even if the world manages to achieve the ambitious goal of limiting global warming to 1.5 degrees Celsius above pre-industrial levels, which we are currently not on track to do so, there will still be a significant rise in sea levels.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('2d724c67-5491-5f87-9d12-e6c855268b63'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2d724c67-5491-5f87-9d12-e6c855268b63'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the clever or humorous use of a word that has more than one meaning?', '39a0d07e-8cbe-57ed-ba0d-33d7dd828212'::uuid, NULL, NULL, E'Pun / wordplay', NULL, NULL),
