  ('2dc710db-158e-5ca1-8fc3-7d8245a0f369'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '2dc710db-158e-5ca1-8fc3-7d8245a0f369'::uuid, 1, NULL, TRUE, 0, NULL, E'Urban Farming', E'In the heart of the city''s {{1}} and bustle, a green revolution grows. By planting urban gardens, people are turning the rooftops and abandoned {{2}} of the city into green havens that produce fresh fruits and vegetables. These green spaces not only provide fresh food to city {{3}} but also serve as community hubs where people learn and {{4}} with nature.', NULL, NULL, NULL, E'1.hustle, 2.lots, 3.dwellers, 4.connect', NULL, NULL),
  ('2dc797df-394b-5f96-b20b-0577ce69800d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2dc797df-394b-5f96-b20b-0577ce69800d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd9e8c4f7-0068-5b98-8b34-96d301d8b52d'::uuid, NULL, E'It is obligatory for companies to provide details of their industrial processes.', NULL, NULL, NULL),
  ('2dca5f07-5815-5b4e-a220-8e63fd323248'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '2dca5f07-5815-5b4e-a220-8e63fd323248'::uuid, 1, NULL, TRUE, 0, NULL, E'History of Sociology', E'Although sociology has its roots in the works of philosophers like Plato, Aristotle, and Confucius, it is a relatively new academic discipline. It {{1}} in the early 19th century in response to the challenges of modernity. Increasing mobility and technological advances resulted in the increasing {{2}} of people to cultures and societies different from their own. The impact of this exposure was varied, but for some people, it included the breakdown of traditional norms and customs and {{3}} a revised understanding of how the world works. Sociologists responded to these changes by trying to understand what holds social groups together and also to explore possible solutions to the breakdown of social solidarity. Thinkers of the Enlightenment period in the 18th century also helped set the {{4}} for the sociologists who would follow. This period was the first time in history that thinkers tried to provide general explanations of the social world. They were able to detach themselves, at least in principle, from expounding some existing ideology and to attempt to lay down general principles that explained social life.', NULL, NULL, NULL, E'1.emerged, 2.exposure, 3.warranted, 4.stage', NULL, NULL),
  ('2dcd06da-5da3-58e6-8bf3-ba6eb5acb062'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '2dcd06da-5da3-58e6-8bf3-ba6eb5acb062'::uuid, 1, NULL, TRUE, 0, NULL, E'Spices', E'Spices are so simple and ubiquitous that we often {{1}} them for granted. A sprinkle of turmeric, a pinch of cumin, a dash of chili flakes – these {{2}} insignificant additions have the power to transform a bland dish into a symphony of flavor. But spices are more than just culinary enhancements; they are potent allies in our quest for health and well-being. {{3}} millennia, spices have been treasured not only for their taste, but also for their medicinal properties. Ginger, with its warming and anti-inflammatory effects, has been used for centuries to soothe nausea and {{4}} digestion. Turmeric, a vibrant yellow spice, contains curcumin, a powerful antioxidant with proven anti-inflammatory and disease-fighting properties. Cinnamon, the sweet and aromatic bark of a tropical tree, helps regulate blood sugar and boasts antimicrobial benefits.', NULL, NULL, NULL, E'1.take, 2.seemingly, 3.For, 4.ease', NULL, NULL),
  ('2dcf496e-d392-5fd2-9e31-172486692186'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2dcf496e-d392-5fd2-9e31-172486692186'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2ba059da-fd46-5a07-9dca-a9931fc8f439'::uuid, NULL, NULL, E'Write down where you got your information from very carefully.', NULL, NULL),
