  ('2df5129b-2c61-5235-a2c1-5f811a8266d9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2df5129b-2c61-5235-a2c1-5f811a8266d9'::uuid, 1, NULL, TRUE, 0, NULL, E'Eiffel Tower', E'Since the beginning, the Eiffel Tower drew attention and served as the theatre for numerous events in the life of Paris and France. The Tower can be seen from many and various points around Paris and its suburbs. It is photographed, filmed and replicated in all kinds of circumstances. It naturally slipped into the role of symbolizing France in the collective imagination and in literature and poetry.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('2df7f9fb-26b6-55b3-b9c8-77e9978b2efb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2df7f9fb-26b6-55b3-b9c8-77e9978b2efb'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9caa5417-e00a-5bc5-b2f6-027a00db07e0'::uuid, NULL, E'There is no point in designing efficient cars if we use them more and more.', NULL, NULL, NULL),
  ('2dfadf9e-0577-54fc-9208-f72a4bddb11b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2dfadf9e-0577-54fc-9208-f72a4bddb11b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '28f51153-5b29-5384-aa81-e5888717931b'::uuid, NULL, E'Students can borrow this book for a maximum of one day.', NULL, NULL, NULL),
