  ('2e005ce1-dde8-5d6e-8a8f-f2d557d70141'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2e005ce1-dde8-5d6e-8a8f-f2d557d70141'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'If a person is doing an experiment, what would he wear to protect his eyes?', 'f6fda8c4-75a9-5df9-a41e-e944417dfb9f'::uuid, NULL, NULL, E'Goggles / Eye protector', NULL, NULL),
  ('2e00ea36-a48a-57dd-9468-56d083a24c0a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2e00ea36-a48a-57dd-9468-56d083a24c0a'::uuid, 1, NULL, TRUE, 0, NULL, E'Memorizing while Sleeping', NULL, '5cb8b851-c6a4-587c-9264-baa4b77e3be2'::uuid, NULL, E'In a 2007 study, for example, a group of neuroscientists had people learn the locations of a bunch of different objects while it smelled like roses, then made it smell like roses again while they were asleep. When they woke up, the subjects were better at remembering where the objects were, compared to when they did the same task without any smells. The researchers proposed that when the subjects smelled roses while they slept, that boosted the memory consolidation process because their brains associated the smell with the memories of the object locations. Basically, the smell acted as a cue to their brains to reactivate those memories, strengthening the connections between the neurons that stored them. And stronger connections meant they had an easier time recalling the memories when they woke up. That 2007 study was small, but later studies that tested the idea found similar results.', NULL, NULL, NULL),
  ('2e03ead7-fdce-50c4-8cd0-438c934d8bbf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2e03ead7-fdce-50c4-8cd0-438c934d8bbf'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ab64d4aa-0274-539b-9db4-192696669bb9'::uuid, NULL, NULL, E'The engineering construction group is to perform a difficult task.', NULL, NULL),
  ('2e0a5085-f686-535c-8ed5-fe8397476b08'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '2e0a5085-f686-535c-8ed5-fe8397476b08'::uuid, 1, NULL, TRUE, 0, NULL, E'Repetitive Routine', E'Some effective people live in a repetitive routine, such as eating the same food. Do you enjoy this lifestyle?', NULL, NULL, NULL, NULL, 200, 300),
