  ('2e704933-64a8-5258-927e-3c6edf3d3e74'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '2e704933-64a8-5258-927e-3c6edf3d3e74'::uuid, 1, NULL, TRUE, 0, NULL, E'David Lynch', E'David Lynch is professor and head of education at Charles Darwin University. And prior to this he was sub dean in the Faculty of Education and Creative Arts at Central Queensland University and foundation head of the University’s Noosa {{1}} . David''s career in education {{2}} as a primary school teacher in Queensland in the early 1980''s, {{3}} to four principal positions before {{4}} higher education. David''s research interests predominate in teacher education with particular interest in building teacher capability to meet a changed world.', NULL, NULL, NULL, E'1.campus, 2.began, 3.progressing, 4.entering', NULL, NULL),
  ('2e768189-fc14-5c4c-a5e7-7ed7ab72c52c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2e768189-fc14-5c4c-a5e7-7ed7ab72c52c'::uuid, 1, NULL, TRUE, 0, NULL, E'Mice and Temperatures', E'Cool room temperature inhibited cancer growth in mice: mice acclimatized to temperatures of 4°C had significantly slower tumor growth and lived nearly twice as long compared with mice in rooms of 30°C because they were burning more brown fat.', NULL, NULL, NULL, NULL, NULL, NULL),
