  ('2e89fdf0-8c18-5820-86ec-a2b404cf85ae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2e89fdf0-8c18-5820-86ec-a2b404cf85ae'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e7af124a-2c2a-59e0-ad1b-672bd4404f42'::uuid, NULL, NULL, E'Each semester, the dance department presents complex, artistic performances.', NULL, NULL),
  ('2e8eb1a1-2841-55d5-94e7-885adac44296'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2e8eb1a1-2841-55d5-94e7-885adac44296'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '024a210e-a873-59aa-ba21-44e341d0f2b7'::uuid, NULL, E'Scientific developments often cause lots of problems so sometimes they''re not worth it.', NULL, NULL, NULL),
  ('2e9463d0-a22b-5b8a-8aec-5484bccbd6f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2e9463d0-a22b-5b8a-8aec-5484bccbd6f8'::uuid, 1, NULL, TRUE, 0, NULL, E'Hummingbird', E'Hummingbirds are highly maneuverable fliers, flitting forward and backward as they home in on flowers. But in the dense foliage many inhabit, they often encounter gaps that are too narrow for their wingspan. Since they can''t bend their wings in flight, how do they get through? Researchers used high-speed cameras to capture their movements, discovering two unique strategies.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('2e99d806-302d-5fd2-a1ca-705cfa7d94e4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', '2e99d806-302d-5fd2-a1ca-705cfa7d94e4'::uuid, 1, NULL, TRUE, 0, NULL, E'Creativity', E'Teaching children in a way that encourages them to empathize with others measurably improves their creativity, and could potentially lead to several other beneficial learning outcomes, new research suggests.\nThe findings are from a year-long University of Cambridge study with Design and Technology (D&T) year 9 pupils at two inner London schools. Pupils at one school spent the year following curriculum-prescribed lessons, while the other group''s D&T lessons used a set of engineering design thinking tools which aim to foster students'' ability to think creatively and to engender empathy, while solving real-world problems.\nBoth sets of pupils were assessed for creativity at both the start and end of the school year using the Torrance Test of Creative Thinking: a well-established psychometric test.\nThe results showed a statistically significant increase in creativity among pupils at the intervention school, where the thinking tools were used. At the start of the year, the creativity scores of pupils in the control school, which followed the standard curriculum, were 11% higher than those at the intervention school. By the end, however, the situation had completely changed: creativity scores among the intervention group were 78% higher than the control group.\nThe researchers also examined specific categories within the Torrance Test that are indicative of emotional or cognitive empathy: such as ''emotional expressiveness'' and ''open-mindedness''. Pupils from the intervention school again scored much higher in these categories, indicating that a marked improvement in empathy was driving the overall creativity scores.\n\nWhich of the following statements are false?', NULL, NULL, NULL, E'The study lasted two years.\nTorrance Test of Creative Thinking can solve real-world problems.', NULL, NULL),
  ('2e9a5ae7-b3e6-5a2b-97d2-dcebc3f5bdf1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2e9a5ae7-b3e6-5a2b-97d2-dcebc3f5bdf1'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '28f9bcdc-b6e1-5607-97ee-d7e83b627af4'::uuid, NULL, E'They say Professor James''s lectures are always interesting and fun.', NULL, NULL, NULL),
