  ('2e9fee12-2df3-5b44-93d9-64d5644bb7a1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2e9fee12-2df3-5b44-93d9-64d5644bb7a1'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '861eca50-ebaa-5dcb-bb83-4ebbdf2d5e2d'::uuid, NULL, E'Put the eggs in the center of the dish, with the vegetables and herbs around the edge.', NULL, NULL, NULL),
