  ('2ee2d0f2-6fc7-590e-b98f-577217c620b1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '2ee2d0f2-6fc7-590e-b98f-577217c620b1'::uuid, 1, NULL, TRUE, 0, NULL, E'Introducing Solid Foods', E'Though infants usually start eating solid foods between 4 and 6 months of age, more and more solid foods are {{1}} by a growing toddler. Pediatricians recommended introducing foods one at a time and for a few days, in order to identify any {{2}} food allergies. Toddlers may be {{3}} at times, but it remains important to introduce a variety of foods and offer food with {{4}} vitamins and nutrients.', NULL, NULL, NULL, E'1.consumed, 2.potential, 3.picky, 4.essential', NULL, NULL),
