  ('2ee69b41-b697-5c60-997f-8bd932b568be'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '2ee69b41-b697-5c60-997f-8bd932b568be'::uuid, 1, NULL, TRUE, 0, NULL, E'Competitive Advantage', E'Companies are struggling to compete in the market due to the availability of different types of competitors with those competitors providing similar products or {{1}} products. In addition, consumers nowadays are becoming more critical in term of their needs and wants. {{2}} , the competition is getting harder day after day. Moreover, with so much variety of products and services, companies have to give more attention on getting the required competitive advantage. Competitive advantage is about how the company is trying to compete in the market. Therefore, it is the {{3}} of the benefits that the company is going to be able to deliver for its consumers while others are not. However, some studies have identified some factors that may take effect on the competitive advantage of companies such as the provided quality, cost reduction, delivering time, {{4}} , and flexibility to do changes on products or services whenever it is needed. Accordingly, selling the product or service with lower price than the competitors or selling products or services with higher quality than others'' products and services will create a good competitive advantage for the company.', NULL, NULL, NULL, E'1.substitution, 2.Therefore, 3.determination, 4.innovation', NULL, NULL),
  ('2eed0661-fc5c-5cbe-ba1a-82977af366a9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2eed0661-fc5c-5cbe-ba1a-82977af366a9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd62889dc-53ce-5184-816e-de020a060856'::uuid, NULL, E'It is important that you work as a team on this project.', NULL, NULL, NULL),
