  ('2f0ebd17-2ad8-5e67-af78-539395b826a2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '2f0ebd17-2ad8-5e67-af78-539395b826a2'::uuid, 1, NULL, TRUE, 0, NULL, E'Urban Canopy', E'Exploring the greenery of a city can reveal a surprising diversity, akin to the layers of a forest canopy. Urban trees, from the towering elms {{1}} the streets to the potted plants on balconies, create a layered tapestry of vegetation. This urban canopy does more than just beautify; it cleans the air, provides shade, and even reduces noise {{2}} .It''s fascinating how, within the {{3}} of concrete and steel, these plants thrive, adapting to their surroundings in inventive ways. Some trees have roots that navigate the urban soil landscape, {{4}} others seem to reach out from the smallest cracks in the pavement. This urban greenery, much like a natural forest, supports a range of wildlife, creating a micro-ecosystem in the heart of the city. Next time you walk through your city, look up and around; you''re likely {{5}} through an urban forest.', NULL, NULL, NULL, E'1.lining, 2.pollution, 3.confines, 4.while, 5.wandering', NULL, NULL),
  ('2f0ffbf1-f919-5c10-89ab-0925826ea13d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2f0ffbf1-f919-5c10-89ab-0925826ea13d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ce6da8cd-f2ae-5f34-9cea-fab766b49d2b'::uuid, NULL, E'The project modules are specified as modules of the control system.', NULL, NULL, NULL),
  ('2f105cf3-6646-56f2-9479-e875aab5d6da'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2f105cf3-6646-56f2-9479-e875aab5d6da'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7f0231b4-f8be-5ee1-a834-e398f3930451'::uuid, NULL, NULL, E'The supposed benefits of space exploration are frequently questioned.', NULL, NULL),
