  ('2f4b180c-12bc-594c-9dfe-d385de21d07c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2f4b180c-12bc-594c-9dfe-d385de21d07c'::uuid, 1, NULL, TRUE, 0, NULL, E'Personality', E'Recent studies do suggest that some of your personality is related to your genetics, but there are plenty of other factors, too. Many of these studies break down personality using the five-factor model, or the Big Five. It puts personality traits into five general categories: extraversion, agreeableness, conscientiousness, openness to experience, and neuroticism. That last one is also sometimes called emotional stability. The degree to which each of these traits shows up in your personality is pretty stable, for the most part. But it does change throughout your life. For example, as people age, studies suggest that they tend to become more conscientious. And life events like getting married have been shown to increase emotional stability. So, sure, your personality can...\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '5742d20b-ded7-53ae-8869-82df67d3bcc1'::uuid, NULL, NULL, E'change', NULL, NULL),
  ('2f558a88-e3e4-5b02-a36c-e4dd8df13fa1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '2f558a88-e3e4-5b02-a36c-e4dd8df13fa1'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c7884256-2d33-599c-b78f-2e54561546f0'::uuid, NULL, NULL, E'Reserve your books at the library''s help desk for easy pickup.', NULL, NULL),
  ('2f5ab27a-72fc-50e6-9bc8-f93d3f205e98'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2f5ab27a-72fc-50e6-9bc8-f93d3f205e98'::uuid, 1, NULL, TRUE, 0, NULL, E'Number 1', E'Number 1 represents strong leadership qualities, innovation, and unexplored potential. Individuals associated with this number possess a unique set of skills and abilities that set them apart. They have a natural inclination towards taking charge and initiating new projects. While they may have a tendency towards self-centeredness, they are generally righteous and kind-hearted leaders.', NULL, NULL, NULL, NULL, NULL, NULL),
