  ('2f62ac31-8830-58d7-9b86-eb8be4ae719f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2f62ac31-8830-58d7-9b86-eb8be4ae719f'::uuid, 1, NULL, TRUE, 0, NULL, E'Culinary Arts', E'Culinary arts is the art of preparing and cooking food. It encompasses a wide range of skills and techniques, from knife skills and flavor balancing to plating and presentation. The culinary industry includes many different types of establishments, such as restaurants, cafes, bakeries, and catering companies, and offers a variety of career paths for aspiring chefs and food professionals.', NULL, NULL, NULL, NULL, NULL, NULL),
