  ('2fe386d3-ef10-5d49-915f-f94a2452bae9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '2fe386d3-ef10-5d49-915f-f94a2452bae9'::uuid, 1, NULL, TRUE, 0, NULL, E'Migratory Species', E'A recent UN report warns that migratory species are in serious decline, and one in five are {{1}} with extinction. The report, titled the State of the World’s Migratory Species, reveals that the main drivers of the decline are human activities that affect the habitats, resources, and survival of migratory animals. The report calls for urgent and coordinated {{2}} to protect migratory species and their habitats, as they cross national and international boundaries and require global cooperation. Some of the proposed measures include implementing and enforcing laws and policies that {{3}} the use and trade of migratory species, reducing the sources and impacts of pollution and climate change, and raising awareness and engaging the public and stakeholders in the conservation of migratory species. Migratory species are a remarkable and valuable part of the natural world, but they are also {{4}} and endangered.', NULL, NULL, NULL, E'1.threatened, 2.action, 3.regulate, 4.vulnerable', NULL, NULL),
  ('2fe9ae45-f4cd-5f4d-bfe2-57da7a41b9bb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '2fe9ae45-f4cd-5f4d-bfe2-57da7a41b9bb'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'If ears are for hearing, what are for seeing?', 'b62b5513-63a6-5c46-a498-042d48b63322'::uuid, NULL, NULL, E'Eyes', NULL, NULL),
