  ('302d0910-6e80-53d3-a221-7ef698d4be4d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '302d0910-6e80-53d3-a221-7ef698d4be4d'::uuid, 1, NULL, TRUE, 0, NULL, E'Dark Matter', E'Dark matter remains one of the greatest mysteries in astronomy. Scientists know it exists because of its gravitational effects on visible matter, but they have yet to detect it directly. Solving the mystery of dark matter could revolutionize our understanding of the universe.', NULL, NULL, NULL, NULL, NULL, NULL),
