  ('303d5291-cc03-5f4b-bb2d-f7a5b8ef25e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '303d5291-cc03-5f4b-bb2d-f7a5b8ef25e1'::uuid, 1, NULL, TRUE, 0, NULL, E'Educational Demand', E'Public demand for education has remained strong, reflecting the importance of education as a means of social progress. Aware of the social value of education to the world of the work, the government continues to innovate and update the education system in order to produce a qualified and competent work force.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('3041f2c3-72a0-5f65-bb97-8e0f3139f2c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '3041f2c3-72a0-5f65-bb97-8e0f3139f2c4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'fb932f63-4e90-5591-aca0-d170c7e39d03'::uuid, NULL, NULL, E'Collaborate with your peers to foster teamwork and a cooperative spirit.', NULL, NULL),
  ('304206e0-7b57-5238-8f7b-f9617f524bee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '304206e0-7b57-5238-8f7b-f9617f524bee'::uuid, 1, NULL, TRUE, 0, NULL, E'Olympics', E'The Olympics {{1}} the noble ideal of sports overcoming the {{2}} of politics with champion athletes of all nations gathering in the spirit of sportsmanship. However, the stakes go beyond who wins the gold medal. Shortly after each competition, nations begin to vie afresh for the bid to host the next game. Winning the vote to host is not merely an honor, it is a political conquest in global recognition. It also spins revenue from the {{3}} of tourists, participants and Olympic related paraphernalia. However, all that {{4}} is not gold. For some residents of Beijing, the site of Olympic 2008, the impact of winning the bid cuts deep and far into their personal lives. The capital is expecting to pour billions of dollars into sports facilities and related upgrades {{5}} roads, public transport, landscaping and sanitation. For the bustling city of bicycles and traffic jams tucked among imperial relics, the Olympics is an opportunity for urban renewal.', NULL, NULL, NULL, E'1.represents, 2.barriers, 3.influx, 4.glitters, 5.such as', NULL, NULL),
  ('3054e77a-ac4c-50bb-b3a1-119862afccd5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '3054e77a-ac4c-50bb-b3a1-119862afccd5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f3b76286-debf-5f3b-a40c-6a63d1452870'::uuid, NULL, NULL, E'Team sports help to develop a child''s social skills.', NULL, NULL),
  ('305705ec-bd57-5a50-ae2c-d5b8875d461f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '305705ec-bd57-5a50-ae2c-d5b8875d461f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '84630918-4baf-5ff6-a30c-20507f79f972'::uuid, NULL, NULL, E'Tact is the knack of making a point without making an enemy.', NULL, NULL),
  ('305f4873-861e-51b0-8f5d-af7f3e1c660e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '305f4873-861e-51b0-8f5d-af7f3e1c660e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is one half of 100% ?', '4949c100-10c8-587c-ae83-1aeb91286890'::uuid, NULL, NULL, E'50%', NULL, NULL),
  ('3060642d-359e-5d78-a98f-cfcf725297c2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '3060642d-359e-5d78-a98f-cfcf725297c2'::uuid, 1, NULL, TRUE, 0, NULL, E'Coffee Consumption', E'Coffee consumption has witnessed a remarkable surge over the last decade, with individuals now drinking twice {{1}} coffee compared to a decade ago. The most significant uptick is {{2}} among the younger demographic, where weekly coffee consumption has nearly tripled, increasing from 8 hours and 12 minutes in 2013 to a staggering 23 hours and 45 minutes in 2020. On {{3}} , an adult spends over 15 hours a week enjoying their favorite brew, factoring in both home and workplace coffee rituals. The phenomenon of ''on-the-go'' coffee culture has seen a five-fold increase since 2013, with people {{4}} an average of 2 hours and 30 minutes per week sipping coffee away from their usual haunts. According to the latest Coffee Trends Report, the percentage of adults using coffee as a daily beverage has {{5}} from seven in ten in 2013 to an impressive nine in ten in 2022 This shift in coffee habits emphasizes the pervasive role of coffee in contemporary lifestyles and reflects the evolving dynamics of beverage consumption.', NULL, NULL, NULL, E'1.as much, 2.noticeable, 3.average, 4.spending, 5.risen', NULL, NULL),
  ('3065b210-16e9-50ad-bdb4-46984583b9d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3065b210-16e9-50ad-bdb4-46984583b9d8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for the art of making objects from clay?', '8e011daf-c4d7-5b57-bebe-97be5d5b0b33'::uuid, NULL, NULL, E'Ceramics / pottery', NULL, NULL),
  ('30711cf9-d9bf-59c9-9e62-aea83753c0de'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '30711cf9-d9bf-59c9-9e62-aea83753c0de'::uuid, 1, NULL, TRUE, 0, NULL, E'Facial Expressions', E'Being able to understand and interpret facial expressions is a big part of non-verbal communication skills. There are often times in conversations when just listening to the words that someone is saying will only tell you half of the story. Words don''t always match how we feel, and our facial expressions often have a habit of giving us away.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('307d8a36-e45a-5e34-8a79-42c628b4b15a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '307d8a36-e45a-5e34-8a79-42c628b4b15a'::uuid, 1, NULL, TRUE, 0, NULL, E'RL', NULL, '8257151d-207d-519f-ba39-c795e818932e'::uuid, NULL, E'Hello everyone. Today''s lecture is about setting up a website. I''m going to be focusing on things that you need to consider to ensure your website really adds value to the people using it.\nSo - there are three main areas you need to think about. The first and most important thing is who is your target audience? When you''re creating a new website you really need to think about who the users are and what\ninformation they''ll be looking for. What we do when we set up websites is to group users based on their needs. So, for a website in the academic community, for example, we may have groups such as researchers and administrators, and this helps us design the site and add information that is relevant to each group.\nThe second point is accessibility. The main thing here is to ensure your website can be found. And you can do this by making sure it can be reached from areas on the web where your target audience are also active. So this may mean providing links on other websites or maybe using social media.\nAnd thirdly - retention-making sure your target audience return to your website regularly. You do this by ensuring it gives them a reason to come back. So it''s important to keep the site up-to-date and make sure it provides the latest news and interesting information and so on.', NULL, NULL, NULL),
  ('30885e38-697f-5e55-9830-029f4301942f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '30885e38-697f-5e55-9830-029f4301942f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the company that provides flight services?', '18068753-b23b-5574-a0ed-8b95a652614e'::uuid, NULL, NULL, E'Airline', NULL, NULL),
