  ('30a3bfe2-33f1-5599-b93f-ef01661a7850'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '30a3bfe2-33f1-5599-b93f-ef01661a7850'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do we describe things that are not allowed by laws?', '0749ad38-9cc2-5301-835f-765b307155cd'::uuid, NULL, NULL, E'Illegal', NULL, NULL),
