  ('30a9a361-210e-5bc2-a4ef-ac7376e3c1cb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '30a9a361-210e-5bc2-a4ef-ac7376e3c1cb'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'If ''fact'' is a real happening, what is an unreal event or unreal story?', '50509a30-5c42-5146-b56d-afd344d8f32f'::uuid, NULL, NULL, E'Fiction', NULL, NULL),
  ('30b2bf90-f7fd-590d-a104-29ac87af9660'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '30b2bf90-f7fd-590d-a104-29ac87af9660'::uuid, 1, NULL, TRUE, 0, NULL, E'The Gray Wolf', E'After an absence of more than 50 years, the gray wolf (Canis lupus) once again runs beneath the night skies of Yellowstone National Park. At 3: 45 pm on March 21st 1995, the first of three groups of gray wolves (also known as the timber wolf) were released from {{1}} acclimation pens at Crystal Creek within Yellowstone National Park. The wolf release plan, {{2}} in an environmental impact statement (EIS) in 1992-1994, is to restore wolves to Yellowstone and central Idaho by establishing experimental populations of gray wolves in both areas. The goal for Yellowstone is to establish 10 packs wolves reproducing in the area for three {{3}} years by the year 2002. Restoring wolves to Yellowstone is in keeping with national park goals to perpetuate all native species and their natural interactions with their environment. As with other park wildlife programs, management emphasizes {{4}} human impact on natural animal population dynamics. Yellowstone National Park is a wilderness and wildlife refuge in the United States.', NULL, NULL, NULL, E'1.fenced, 2.involved, 3.consecutive, 4.minimizing', NULL, NULL),
  ('30bb082e-10a1-5c76-ba8e-f7c35b656bad'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '30bb082e-10a1-5c76-ba8e-f7c35b656bad'::uuid, 1, NULL, TRUE, 0, NULL, E'Enhancing Customer Service Process', E'Your team is discussing how to enhance the company''s customer service process, and someone suggests increasing the use of automated systems to handle customer inquiries. However, you realize this might weaken the interpersonal connection with customers. What would you say to your team?', 'c1e1914c-008c-5fc3-8f94-1fb7392d4600'::uuid, NULL, E'Hey team, I appreciate the suggestion to increase automation in our customer service process. However, we also need to consider the importance of maintaining a personal touch with our customers. Perhaps we can explore ways to use automation for routine inquiries while reserving human interaction for more complex issues or situations where empathy and understanding are crucial. This way, we can strike a balance between efficiency and building strong customer relationships.', NULL, NULL, NULL),
  ('30bca1c5-84b6-54a1-b003-bb492e13f27c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '30bca1c5-84b6-54a1-b003-bb492e13f27c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the mark used to show that one or more letters have been left out?', '3bd45e9e-1c7c-5075-9f62-69c8c98663b8'::uuid, NULL, NULL, E'Apostrophe', NULL, NULL),
