  ('316f3c4f-80cf-5b00-97f5-5481fa74050e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '316f3c4f-80cf-5b00-97f5-5481fa74050e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bd9539bc-dae0-58d5-8fd0-16358472513c'::uuid, NULL, E'Our university has set a minimum English Language proficiency level.', NULL, NULL, NULL),
  ('317f47bb-50a8-50ad-9733-462034ffbe41'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '317f47bb-50a8-50ad-9733-462034ffbe41'::uuid, 1, NULL, TRUE, 0, NULL, E'Reindeer Rebellion', E'Locals in central Finland are campaigning to have reindeer corralled all year round in a dispute with traditional herders. In what''s been described as a "reindeer rebellion", people living in North Ostrobothnia and Kainuu regions want tighter restrictions on herding, because they say that the free-range animals are damaging their crops and forests and harming their livelihoods.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('318b7fe1-0c21-5961-be47-525dce86aed5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '318b7fe1-0c21-5961-be47-525dce86aed5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '003248f4-6247-5540-b328-bede77f4547d'::uuid, NULL, NULL, E'Upgrading manufacturing systems can increase efficiency.', NULL, NULL),
  ('318d280e-7055-5908-be85-eda6b9f94505'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '318d280e-7055-5908-be85-eda6b9f94505'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What country has the highest population in the world?', '68dff1f1-52d9-51b2-bef5-6c38dd1755a1'::uuid, NULL, NULL, E'China', NULL, NULL),
  ('318e3530-c6d8-5e7a-bf6d-979a88c7dd34'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '318e3530-c6d8-5e7a-bf6d-979a88c7dd34'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5423a012-9dbe-5593-b9ac-5921bdd140a6'::uuid, NULL, E'Your car can park in the building behind the medical center.', NULL, NULL, NULL),
  ('3193953f-7431-5f37-97bb-d693ab476360'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '3193953f-7431-5f37-97bb-d693ab476360'::uuid, 1, NULL, TRUE, 0, NULL, E'Saunas', E'Saunas are part of a toasty tradition that is as entwined with Finland as the snow that falls there. Saunas originated as sterile ways to "wash up" before running hot water existed. The word sauna is actually a Finnish word that translates into English as "bath." The first Finnish saunas were dug into ridges in the ground, and later were built above ground from wooden logs. Rocks were heated until in a stone stove using a wood fire. But these first sauna rooms didn''t have chimneys and bathers would have to wait until the rooms cleared of smoke. Finally saunas evolved to what we know today: They''re traditionally heated by metal stoves and can reach temperatures as hot as 200 degrees Fahrenheit. Winters in Finland can last up to seven months in the northernmost regions; hence the need for extremely hot saunas. But what about that cold plunge? Well it provides an equally extreme way to cool off. As the Finland tourism board describes it: "When you come out of the sauna, jump into a lake, or roll in the snow. If you do roll in the snow, make sure it is fresh and powdery: old, icy snow can have an effect on your skin like sandpaper." Rolling in the snow sans clothes may sound like the worst spa experience ever.', NULL, NULL, NULL, NULL, 5, 75),
