  ('31a83758-d059-592e-89d6-b853606e154c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '31a83758-d059-592e-89d6-b853606e154c'::uuid, 1, NULL, TRUE, 0, NULL, E'Making Notes', E'The whole purpose of making notes is to aid your learning. It is important to go back over them within a day of making them to make sure they make sense and make them legible for future revisions. Also, going back over them should highlight the key questions of areas in which you want to do further reading.', NULL, NULL, NULL, NULL, NULL, NULL),
