  ('31ca35da-9195-5c7b-91c1-9564aaefe4ba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '31ca35da-9195-5c7b-91c1-9564aaefe4ba'::uuid, 1, NULL, TRUE, 0, NULL, E'Color Preference', E'Many tests have shown that, in a very broad way, peoples in most parts of the world have similar color preferences. Blue is the most preferred and popular hue, followed in order by red, green, purple, yellow and orange. Overlying this basic order of color preference, {{1}} , are the responses of individuals, which of course vary {{2}} and may also be very powerful. Children are likely to have strong preferences for some colors and aversions to others, but sometimes will not admit to them, since outside {{3}} may be influential in determining both color preferences and the way that they are expressed or suppressed. Current fashions in clothes and accessories, gender-stereotyping and peer-group pressure may all play a significant part. Boys in particular may be reluctant to admit to any strong preferences for colors {{4}} those of favorite football teams, because color awareness may be regarded by their peer-group as feminine.', NULL, NULL, NULL, E'1.however, 2.widely, 3.factors, 4.other than', NULL, NULL),
  ('31ca9aca-c50d-52b0-ab67-041e12621c4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '31ca9aca-c50d-52b0-ab67-041e12621c4b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the time after noon called?', 'ca7a4294-ab3f-57cb-84c7-caa74daca537'::uuid, NULL, NULL, E'Afternoon / Post Meridian / P.M.', NULL, NULL),
