  ('320269fa-58bf-521d-bf41-1dcfb7bc2778'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '320269fa-58bf-521d-bf41-1dcfb7bc2778'::uuid, 1, NULL, TRUE, 0, NULL, E'FSA', E'The Food Standards Authority has {{1}} a public warning about the risks of a compound called acrylamide that {{2}} in some foods cooked at high temperatures. This means that people should avoid {{3}} their roast potatoes, reject thin-crust pizzas and only easily toast their bread. But where is the evidence to support such {{4}} advice? While studies have shown that acrylamide can cause neurological damage in mice, there is no {{5}} evidence that it causes cancer in humans.', NULL, NULL, NULL, E'1.issued, 2.forms, 3.crisping, 4.alarmist, 5.conclusive', NULL, NULL),
  ('32063208-7fd6-5d4c-bdc2-48d1ab82161e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '32063208-7fd6-5d4c-bdc2-48d1ab82161e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4aa95ad0-adec-5e30-b795-7f249fdb5b32'::uuid, NULL, E'You can apply for multiple scholarships in one simple application.', NULL, NULL, NULL),
  ('320633dc-c3f8-5b52-84e1-22b54334bc19'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '320633dc-c3f8-5b52-84e1-22b54334bc19'::uuid, 1, NULL, TRUE, 0, NULL, E'Traffic Noise', E'Students who were {{1}} to the highest level of outdoor noise pollution while at school showed slower improvements in memory and {{2}} . Road traffic noise outside schools may {{3}} the development of a child’s attention span and short-term memory.­ Meanwhile, local aircraft noise has been shown to reduce academic {{4}} and reading comprehension in children.', NULL, NULL, NULL, E'1.exposed, 2.attentiveness, 3.impair, 4.performance', NULL, NULL),
  ('320657e6-6017-5526-b38e-e452085b458d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '320657e6-6017-5526-b38e-e452085b458d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the rate of death in a particular situation or period of time?', '70f913f8-ebe3-5e2d-b6a7-4a0af19ab725'::uuid, NULL, NULL, E'Mortality', NULL, NULL),
  ('320d5dad-feeb-56a5-b89d-fd5fb8874a98'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '320d5dad-feeb-56a5-b89d-fd5fb8874a98'::uuid, 1, NULL, TRUE, 0, NULL, E'A Better Government Plan', E'A better government plan is based on the assumption that government has a positive role to play in improving people’s lives but could perform this function far more effectively than it does now. What distinguishes the better government plan from the other two is that instead of changing the size of government, it reallocates spending in ways designed to improve government performance.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('32150447-2d40-5b95-80ad-e850bc80c535'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '32150447-2d40-5b95-80ad-e850bc80c535'::uuid, 1, NULL, TRUE, 0, NULL, E'Nurse Sharks', E'Nurse sharks are thought to take advantage of dormant fish which would otherwise be too fast for the sharks to catch, although their small mouths limit the size of prey items, the sharks have large throat cavities which are used as a sort of bellows valve. In this way, nurse sharks are able to suck in their prey. Nurse sharks are also known to graze algae and coral.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('3217c7f9-4aec-56b0-839f-a414e9ad4dc3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3217c7f9-4aec-56b0-839f-a414e9ad4dc3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6c840936-69fa-58ed-9110-f5803baa65f5'::uuid, NULL, E'Surprisingly, some people actually enjoy watching advertisements on television.', NULL, NULL, NULL),
  ('32202adc-747a-5d44-8b0a-0095f59c91f3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '32202adc-747a-5d44-8b0a-0095f59c91f3'::uuid, 1, NULL, TRUE, 0, NULL, E'Patent', E'Most inventors {{1}} to make money from an invention by licensing it to a larger company that will manufacture and sell the invention. However, they {{2}} the risk that potential licensees with whom they discuss the invention may learn enough about it to steal it or prevent them from patenting it. This means that the inventor would not receive any royalties from the invention.\nSometimes an inventor will {{3}} a provisional patent application to prevent this problem. They would need to make sure that their invention meets the requirements for patent protection. If it does, a provisional patent application can give their invention patent pending status for a minimal fee. This will {{4}} an inventor''s intent to move forward with obtaining patent rights for the invention. Another {{5}} for inventors to consider is requiring potential customers to sign a non-disclosure agreement, also known as a confidentiality agreement. This may be appropriate if the invention may not meet the patent requirements at this stage of its development, which means that they could not file a provisional patent application.', NULL, NULL, NULL, E'1.aim, 2.face, 3.file, 4.signal, 5.option', NULL, NULL),
  ('3220dcbb-25ac-5a69-9e82-da8cbd8bc3df'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '3220dcbb-25ac-5a69-9e82-da8cbd8bc3df'::uuid, 1, NULL, TRUE, 0, NULL, E'Self-defeating Habits', E'Don''t allow yourself to slip into self-defeating habits, such as procrastinating. Try to keep a {{1}} going in your study. Scatter blocks of study with short breaks to limit fatigue. If you study solidly for a couple of hours, make sure you give yourself fifteen minutes or so before you start up again. Think positively about yourself and your situation. Challenge the negative thoughts that {{2}} into your mind and cause you unnecessary stress at times, such as ''I''m going to fail'', ''I''ll end up blowing my future, my chance of getting a career''. You don''t have any need to think catastrophically, it''s not achieving anything. In fact, it''s doing you a lot more harm than good, because it''s distracting you away from what you need to do. Learn to become more relaxed in your daily life. There are simple techniques, such as breathing exercises and {{3}} muscular relaxation exercises, as well as guided imagery, which can help you to feel calmer, and more focused. The Macquarie University Counsellors can help you with these techniques. Some do relaxation tapes for students.', NULL, NULL, NULL, E'1.momentum, 2.creep, 3.progressive', NULL, NULL),
  ('3222772f-695f-578e-9873-67e63c500589'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '3222772f-695f-578e-9873-67e63c500589'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '94d8d0db-bffc-5e5c-b69a-74bbe06a565c'::uuid, NULL, NULL, E'Conferences ought to be always scheduled two weeks in advance.', NULL, NULL),
