  ('32b38cbd-4368-5c2a-b8e7-f39353a1963d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '32b38cbd-4368-5c2a-b8e7-f39353a1963d'::uuid, 1, NULL, TRUE, 0, NULL, E'Melatonin', NULL, 'd0e99432-f872-56b0-b020-dc288f801c85'::uuid, NULL, E'I''m just going to take on where stuff left off. The hormone I want to now talk about it''s called melatonin. The synthesis is in the Pineal Gland, which is very small. It is the size of a pea in your brain. Descartes called it the ''seat of soul'', and it is where melatonin is made. And it has a rhythm as well. And in the sense, it is the opposite of the cortisol. It peaks at night. We call it as the darkness hormone. In every species that we studied, melatonin occurs at night. And it''s hormone that prepares you for the things, that your species, does at night. So, of course, in humans we sleep, but animals, like rodents, they are awake. So, it''s a hormone that is related to darkness behavior.', NULL, NULL, NULL),
  ('32bd432c-1238-5d27-880e-343ade41ffe4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '32bd432c-1238-5d27-880e-343ade41ffe4'::uuid, 1, NULL, TRUE, 0, NULL, E'National Portrait Gallery', E'The majority of early pictures in the National Portrait Gallery''s {{1}} are by unknown artists, with fundamental questions, such as when, where and why they were painted still remaining to be answered. Through the application of scientific methods, a new project has the {{2}} to unlock evidence that will allow researchers to determine answers to these questions. They will use a {{3}} of cutting-edge scientific techniques, such as X-ray and infra-red reflectography, in order to reveal new {{4}} about individual paintings.', NULL, NULL, NULL, E'1.care, 2.potential, 3.combination, 4.information', NULL, NULL),
  ('32c75e12-638c-5439-8554-da47beb8aa46'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '32c75e12-638c-5439-8554-da47beb8aa46'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a photo of a person''s face taken from the side?', 'c658d485-0928-5c47-846f-83ec3112da79'::uuid, NULL, NULL, E'Profile', NULL, NULL),
