  ('3317cfb1-5895-5e9a-8a2a-69a4b7835b39'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '3317cfb1-5895-5e9a-8a2a-69a4b7835b39'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '00b513bf-7dc2-5751-a5ef-e233e7fb8d10'::uuid, NULL, NULL, E'We have a lecture in the morning on Thursday.', NULL, NULL),
  ('331ad1d7-ecd0-5d11-9361-0f45f63a8db6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '331ad1d7-ecd0-5d11-9361-0f45f63a8db6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a939a8e1-5ab3-5462-8896-356e40e86486'::uuid, NULL, E'New York City is famous for its ethnic diversity.', NULL, NULL, NULL),
  ('331f56ee-233b-5b5e-8881-5658c4c021f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '331f56ee-233b-5b5e-8881-5658c4c021f0'::uuid, 1, NULL, TRUE, 0, NULL, E'Hegra', E'They rise out of the desert sands, monumental monoliths shaped over millennia by the winds of time. Man has left his mark here too, carving out more than 110 rock tombs, many with ornate details: steps symbolising the way to heaven above the entrance, shelf cornicing and perhaps the head of Medusa to warn against tomb raiders. The result is seriously stunning, the huge red rocks standing stark against the brilliant blue of the desert sky. This is Hegra, the site of an ancient Saudi Arabian city built by the Nabataeans. And I believe you’ll be amazed and surprised by what you see when you come. Welcome!\n\nWhere does this passage most likely to appear?', NULL, NULL, NULL, E'A travel book.', NULL, NULL),
  ('33275919-d73d-5a29-ac04-1baaf2e20721'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '33275919-d73d-5a29-ac04-1baaf2e20721'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What kind of educational institution does a ten-year old child study in?', 'a89b0525-9941-5670-854f-4945d2a3fda4'::uuid, NULL, NULL, E'Primary school / elementary school', NULL, NULL),
