  ('33caca6d-c55c-5273-a121-44a414cc859c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '33caca6d-c55c-5273-a121-44a414cc859c'::uuid, 1, NULL, TRUE, 0, NULL, E'Humanities', E'We believe in the inherent value of research in the humanities and social sciences. And our research data agenda is given by the pursuit of new knowledge that will be of benefit of Australia and the world. We offer one of the most comprehensive programs in the humanities and social sciences in Australia and the Asian Pacific region.', NULL, NULL, NULL, NULL, NULL, NULL),
