  ('33ceadee-3f80-5c0f-a65b-089f1228b01c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '33ceadee-3f80-5c0f-a65b-089f1228b01c'::uuid, 1, NULL, TRUE, 0, NULL, E'Wine Quality', E'Researchers show that weather plays an important role in determining wine quality. By analyzing 50 years’ worth of wine critic scores from the Bordeaux wine region in relation to that year’s weather, the researchers showed that higher quality wine is made in years with warmer temperatures, higher winter rainfall, and earlier, shorter growing seasons.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('33d4e748-2571-56d6-b982-df00b9e1effc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '33d4e748-2571-56d6-b982-df00b9e1effc'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '75553007-085b-5e4d-a87e-2c4a95a5620b'::uuid, NULL, E'The new machine reduced labour costs to almost zero.', NULL, NULL, NULL),
  ('33d9286e-3d2f-59ce-941c-9f4e233877a0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '33d9286e-3d2f-59ce-941c-9f4e233877a0'::uuid, 1, NULL, TRUE, 0, NULL, E'Climate Change', E'Every day millions of lights and computers are left on in deserted offices, apartments, and houses. Environmental activists say that simply switching them off could cut Sydney''s greenhouse gas emissions by five percent over the next year. Per capita, Australia is one of the world''s largest producers of carbon dioxide and other gases that many scientists believe are helping to warm the Earth''s atmosphere, causing climate upset. A long-standing drought and serious water shortages in Australia have focused much attention on climate change. Some experts warn higher temperatures could leave this nation of 20 million people at the mercy of more severe droughts and devastating tropical cyclones.\n\nWhat does this passage suggest climate change will bring to Australia?', NULL, NULL, NULL, E'drought', NULL, NULL),
  ('33ddd7e5-4ea6-5be4-a19a-7d3df86df720'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '33ddd7e5-4ea6-5be4-a19a-7d3df86df720'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '18ba5a97-3a45-5c49-8776-2709f296ac96'::uuid, NULL, E'The gas station is closed while essential repairs are being carried out.', NULL, NULL, NULL),
  ('33e109d2-ab6d-5e44-a246-ea06e9c125f1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '33e109d2-ab6d-5e44-a246-ea06e9c125f1'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'fd75d251-3cec-56d6-a75c-4bb5adf78233'::uuid, NULL, E'Even with the permit, finding a parking spot on campus is still impossible.', NULL, NULL, NULL),
  ('33e73fec-0866-57b3-8039-2569425c0f25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '33e73fec-0866-57b3-8039-2569425c0f25'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the procedure of obtaining a small piece of tissue for examination under a microscope?', 'f553899f-3a89-5753-99f1-311713a69df3'::uuid, NULL, NULL, E'Biopsy', NULL, NULL),
  ('33f2c5ae-cc33-51d0-9108-f4483b70d234'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '33f2c5ae-cc33-51d0-9108-f4483b70d234'::uuid, 1, NULL, TRUE, 0, NULL, E'Beta Testing', E'There are over a million apps in the world. Most of these apps have to go through mobile beta testing for them to be relevant in the market. Beta testing allows testing your app’s real-world performance. This allows quality assurance teams to identify and focus on any bugs that will appear. By doing so, it’s assumed that customers can expect the product to work without any problems.\nUnderstanding the problems found ahead of time makes the development team efficient. They improved the quality of the product before release. This means they can improve on it during the development process to ensure better quality products at launch. Running a beta test on your product decreases the time for it to market. Understanding customer expectations improve other aspects of the product and improve other processes.\nBeta testing is also the product management opportunity to get real feedback from users in a real environment. It offers unique insights from the customer’s experience. Doing this also answers questions from a competitive analysis standpoint.\nBeta testers can record their interaction with the product and uncover any issues that they weren’t aware of. This also allows you to review their interaction with the product. Know what are the challenges they encounter or what they ignore when using your product.\nEvery product has an expected output and flow of action. Through beta testing, you can determine how many of the expected outcomes did the user does. Also, it expands the initial usability studies conducted and see how it performs in the wild.', NULL, NULL, NULL, NULL, 5, 75),
  ('33f83eba-33bb-527e-8b92-932dc66ae112'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '33f83eba-33bb-527e-8b92-932dc66ae112'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for a society marked by the influence of several distinct cultural groups?', 'db6a6f69-3f12-531d-89bf-bcfde6d8a957'::uuid, NULL, NULL, E'Multiculturalism', NULL, NULL),
  ('33fcf687-c1ce-5c6f-bad2-a6cbc331a550'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '33fcf687-c1ce-5c6f-bad2-a6cbc331a550'::uuid, 1, NULL, TRUE, 0, NULL, E'Social Support', E'There’s a lot of research out there that suggests social media are a useful tool to stay connected to others. In fact, those who use social media more also report feeling more social support. However, all of this comes with a huge caveat: we simply don’t know about cause and effect.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('34073c93-5b8b-5c4a-b3ec-b089e8ec2b6f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '34073c93-5b8b-5c4a-b3ec-b089e8ec2b6f'::uuid, 1, NULL, TRUE, 0, NULL, E'Cultural Shifts', E'People now curate their identities online, where digital footprints contribute to a new form of social currency. This phenomenon has led to the rise of virtual communities that transcend physical borders, allowing individuals to connect based on interests rather than {{1}} . However, this digital interconnectedness also raises questions about privacy, authenticity, and the long-term impact on interpersonal relationships. The {{2}} of life seems to have accelerated, with the expectation of instant communication and the constant {{3}} of information shaping a new cultural norm of immediacy. This rapid exchange has transformed how knowledge is {{4}} and shared, challenging traditional institutions of learning and news dissemination. The digital age''s cultural shifts reflect a complex interplay between technological advancement and human behavior, highlighting the adaptability of society in the face of continuous change and the enduring need for connection in an {{5}} virtual world.', NULL, NULL, NULL, E'1.proximity, 2.pace, 3.flow, 4.acquired, 5.increasingly', NULL, NULL),
  ('340b2b28-4ea3-5c07-8174-35a27209daf9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '340b2b28-4ea3-5c07-8174-35a27209daf9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '87113ace-76c5-5dd2-9f9d-17590214f890'::uuid, NULL, NULL, E'Digital architecture is changing a lot because of new technology today.', NULL, NULL);
