  ('3473f5a8-212b-5c52-9898-ab8115d3c583'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3473f5a8-212b-5c52-9898-ab8115d3c583'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '12b5eecb-4ffa-568d-8352-864dadc1a27b'::uuid, NULL, E'But there''s no context for the words we read.', NULL, NULL, NULL),
  ('34751616-4634-57b3-8360-3fd918d0a66e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '34751616-4634-57b3-8360-3fd918d0a66e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which one in the four seasons has the lowest temperature?', 'cb14ce39-55bf-58b2-8076-6dcb449f718f'::uuid, NULL, NULL, E'Winter', NULL, NULL),
  ('34802213-4975-5345-a950-7edbb39f327d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '34802213-4975-5345-a950-7edbb39f327d'::uuid, 1, NULL, TRUE, 0, NULL, E'Hemisphere', E'The brain is divided into two hemispheres, called the left and right hemispheres. Each hemisphere provides a different set of functions, behaviors, and controls. The right hemisphere is often called the creative side of the brain, while the left hemisphere is the logical or analytic side of the brain.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('34816663-2564-56e1-b3ae-02f3673d173a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '34816663-2564-56e1-b3ae-02f3673d173a'::uuid, 1, NULL, TRUE, 0, NULL, E'Spy', E'In my opinion, Pocahontas was a spy for the colonists. Yes, she served as a mediator between the british colonists and the native Americans, but she was more of a spy. As you know, she even provided vital food supplies to the colonists. However, she didn''t think of herself as a spy, and the colonists didn''t trust her much. Despite her help. In a way, we could say she was a sad spy. Unfortunately, a war broke out between the pole, ha tons and the colonists. The colonist captured her and brought her to jamestown. While she was in jamestown. As a hostage, she freely converted to christianity and married john rolfe. As we all know, this marriage brought the war to its end. What do you think? Was she a mediator or a spy? I believe she was a spy, a spy who played a role as a mediator. One. What role did Pocahontas play between the british colony and the native Americans?\n\nWhat did the marriage between Pocahontas and John Rolfe do to the war between the British colony and the Native Americans?', '99c5a60f-dd0a-57bb-857f-91fc3f69322f'::uuid, NULL, NULL, E'The marriage ended the war.', NULL, NULL),
  ('3489583d-d904-5545-bc43-14c4e0e05c2e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3489583d-d904-5545-bc43-14c4e0e05c2e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the hair that grows on the chin and cheeks of a man''s face?', '3c661442-78ff-5d13-aa58-a84376c462a6'::uuid, NULL, NULL, E'Beard / mustache / whiskers', NULL, NULL),
  ('348a5cb3-3b75-5793-832d-cceea0abbf28'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '348a5cb3-3b75-5793-832d-cceea0abbf28'::uuid, 1, NULL, TRUE, 0, NULL, E'Cash Transactions', NULL, NULL, NULL, NULL, E'1, 2, 3, 5, 4', NULL, NULL),
  ('348c682f-1fae-5b8f-a7fa-7550ba7436fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '348c682f-1fae-5b8f-a7fa-7550ba7436fd'::uuid, 1, NULL, TRUE, 0, NULL, E'Movie Delay', E'You went to watch a movie with a friend, but the car broke down on the way and made your friend wait for a long time. What should you say to your friend?', '1642e5de-1b6b-50d5-8d44-b607628e46c3'::uuid, NULL, E'Hey friend, I want to talk to you about something.\nWe seem to have a little issue with our movie trip.\nIt''s like my car broke down on the road, which kept you waiting for a really long time.\nAnd I''d like to know what you think.', NULL, NULL, NULL),
  ('34940f33-df1a-5789-9bbe-ff49d6221f16'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '34940f33-df1a-5789-9bbe-ff49d6221f16'::uuid, 1, NULL, TRUE, 0, NULL, E'Biopedturbation', E'Biopedturbation, the disturbance of soils by animals, is an important and often essential functional component of many ecosystems worldwide. It determines the spatiotemporal characteristics of soil patches and thereby contributes to the ecosystems'' diversity and heterogeneity.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('34969566-aa2e-562d-ba6a-d67cea7c4a69'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '34969566-aa2e-562d-ba6a-d67cea7c4a69'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f42110a0-7357-5925-9800-7e102f9a3f0a'::uuid, NULL, NULL, E'You need to hand in your work by Friday.', NULL, NULL),
  ('34979caa-1297-5039-ad58-1eb100853396'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '34979caa-1297-5039-ad58-1eb100853396'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which city is the American capital?', 'e244bee4-e4c5-5e89-ab0f-e4f7a801577b'::uuid, NULL, NULL, E'Washington D.C', NULL, NULL),
  ('34a0e674-2740-5a5a-80d3-59061cc87dd8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '34a0e674-2740-5a5a-80d3-59061cc87dd8'::uuid, 1, NULL, TRUE, 0, NULL, E'Avocados', E'Avocados are toxic to almost all animals (including cats and dogs). Humans are a rare exception. It is the only fruit to contain persin, a fatty acid, which, when eaten by animals causes vomiting, diarrhea, and other nasty symptoms. Consumption of large quantities can cause death within twelve hours. Avocados are berries (fleshy fruits coming from a single ovary). Interestingly, this broad definition of a berry means that bananas, pumpkin, tomatoes, watermelon, and coffee are also berries (you can tell that to the next person who tries to argue that tomatoes are vegetables). Curiously this also excludes strawberries as berries. Eighty percent of modern avocados originate from one ‘mother’ tree which was patented by mailman Rudolph Hass from California in 1935. The tree survived until 2002 when it died of root rot. Unfortunately Hass only made $5,000 in his lifetime from his patent on the tree because his partner sold cultivars to anyone who wanted to buy them. Subsequently Hass spent the remainder of his life working for the California Mail Service. Avocado also has an interesting characteristic: it is the only berry with no living animal large enough to spread it through consumption and release as dung. This has led scientists to believe that it co-evolved with prehistoric megafauna that were large enough to eat the fruit whole. The megafauna went extinct but the avocado remained as an unusual monument to an unknown dinosaur.', NULL, NULL, NULL, NULL, 5, 75),
  ('34a1e292-cd87-50d8-b37c-d7aabaa3da21'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '34a1e292-cd87-50d8-b37c-d7aabaa3da21'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'df2c9bec-cd42-5e90-8152-559e53d0edbc'::uuid, NULL, E'The result of the study will be published next month.', NULL, NULL, NULL),
