  ('34af23b6-c115-584c-947c-c71521ee4242'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '34af23b6-c115-584c-947c-c71521ee4242'::uuid, 1, NULL, TRUE, 0, NULL, E'Animal or Human', E'Some people think that human needs for farmland, housing and industry are more important than saving land for endangered animals. To what extent do you agree with this statement?', NULL, NULL, NULL, NULL, 200, 300),
