  ('34fc50cf-eb07-5ac1-ae86-9dd890b382c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '34fc50cf-eb07-5ac1-ae86-9dd890b382c5'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How many sides does a square have?', 'c2d840f4-e24c-5a66-a6dc-7d0b7a3709da'::uuid, NULL, NULL, E'Four', NULL, NULL),
  ('35036b81-19d9-5d31-8ecb-8f1b02069cc6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '35036b81-19d9-5d31-8ecb-8f1b02069cc6'::uuid, 1, NULL, TRUE, 0, NULL, E'Customs and Taboos', E'All cultures have their own unique sets of customs and taboos. It is important for marketers to learn about these customs and taboos so that they will know what is acceptable and unacceptable for their marketing programs. For example, in Japan, the number four is considered unlucky, and products packages containing four items are {{1}} by many consumers. In Middle Eastern countries where Islamic law is strictly observed, images {{2}} the uncovered arms or legs of the female body are considered offensive. Meanwhile in Egypt, where many women wear the headscarf or hijab in public, an increasing number of younger women are in work and educational settings where gender segregation does not exist. Marketers struggle with whether to {{3}} women with or without the hijab, knowing that they risk offending some of their target audience with either choice. Marketers should seek guidance from native experts familiar with local culture and customers. Marketing research can also help marketers understand and {{4}} these complex issues.', NULL, NULL, NULL, E'1.avoided, 2.displaying, 3.portray, 4.navigate', NULL, NULL),
  ('350eece1-54f7-5faf-848f-87d2a566c688'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '350eece1-54f7-5faf-848f-87d2a566c688'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which button do we use to remove something from computer?', 'b969d406-f0b1-57d2-b762-e5a597c27711'::uuid, NULL, NULL, E'Delete / backspace', NULL, NULL),
  ('3513ce7a-2923-5633-9b47-483733dc7970'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3513ce7a-2923-5633-9b47-483733dc7970'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'cbeb0f66-6803-5623-bf00-c803e21025f6'::uuid, NULL, E'The new tools are being tested by senior specialists.', NULL, NULL, NULL),
  ('35166f76-5bc9-51f5-8e09-a564119cb59d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '35166f76-5bc9-51f5-8e09-a564119cb59d'::uuid, 1, NULL, TRUE, 0, NULL, E'Discrimination', E'As a Society for Human Resource Management (SHRM) article emphasizes: "Discrimination costs employers millions of dollars every year, not to mention the countless hours of lost work time, employee stress and the {{1}} public image that goes along with a discrimination lawsuit." Equal employment opportunity isn''t just the right thing to do, it''s the law. Specifically, it''s a series of federal laws and Executive Orders designed to {{2}} employment discrimination. Illegal discrimination is the {{3}} of making employment decisions such as hiring, compensation, scheduling, performance evaluation, promotion, and firing {{4}} on factors unrelated to performance. There are currently seven categories protected under federal law: age, disability, genetic information, national origin, pregnancy, race and color, religion and sex.', NULL, NULL, NULL, E'1.negative, 2.eliminate, 3.practice, 4.based', NULL, NULL),
  ('35189f14-3826-51ff-9192-eb385fcd1145'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '35189f14-3826-51ff-9192-eb385fcd1145'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What type of body covering helps to insulate burns?', '63cd511c-06ee-5740-8b46-b07ca7e75d24'::uuid, NULL, NULL, E'Dressing / bandage', NULL, NULL),
