  ('35226f34-9935-5b9c-b7c4-3d4a32f29b9d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '35226f34-9935-5b9c-b7c4-3d4a32f29b9d'::uuid, 1, NULL, TRUE, 0, NULL, E'Augustus', E'Augustus was given the powers of an absolute monarch, but he presented himself as the preserver of republican traditions. He treated the Senate, or state council, with great respect, and was made Consul year after year. He successfully reduced the political power of the army by retiring many soldiers, but giving them land or money to keep their loyalty.', NULL, NULL, NULL, NULL, NULL, NULL),
