  ('3535e2d6-9ce3-57d1-863e-cfbdd65fd610'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3535e2d6-9ce3-57d1-863e-cfbdd65fd610'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call an amount of money that is taken off the usual cost of something?', 'e9484cae-028a-50b3-be42-06e38725f26b'::uuid, NULL, NULL, E'Discount / reduction', NULL, NULL),
  ('353cc540-4505-5a12-b9ae-ddf93cf62246'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '353cc540-4505-5a12-b9ae-ddf93cf62246'::uuid, 1, NULL, TRUE, 0, NULL, E'Green', E'Green is a refreshing and rejuvenating color that is often associated with nature and growth. It has a calming effect and can promote feelings of balance and harmony. Green is also believed to have healing properties, making it a popular choice for healthcare settings. Its soothing effects make it an ideal color for relaxation spaces like living rooms and bedrooms.', NULL, NULL, NULL, NULL, NULL, NULL),
