  ('354cd3c5-5fc7-5c51-90e5-cc0049f0ffbd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '354cd3c5-5fc7-5c51-90e5-cc0049f0ffbd'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a4c60e30-949d-5cb3-bb06-0d45cb987267'::uuid, NULL, E'The teacher asked the students to check their answers before handing in their homework.', NULL, NULL, NULL),
