  ('354f85f2-cec7-502c-affc-6c1e9a38a66f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '354f85f2-cec7-502c-affc-6c1e9a38a66f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6b3ad048-b0b2-566d-a5e8-934ba05ee852'::uuid, NULL, NULL, E'Musicians see music as a way to entertain people.', NULL, NULL),
  ('3555041d-5293-553a-8c45-e184bcdd52ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '3555041d-5293-553a-8c45-e184bcdd52ca'::uuid, 1, NULL, TRUE, 0, NULL, E'Accessible Education', E'Do you agree that technology has made education more accessible to people around the world?', NULL, NULL, E'I wholeheartedly agree that technology has significantly enhanced the accessibility of education worldwide. The transformative impact of technology has revolutionized the way people learn, making educational resources more reachable and learning opportunities more flexible, affordable, and inclusive.\nOne of the most compelling aspects of technology in education is its ability to enable access to educational resources and courses from anywhere in the world. Through online platforms and digital tools, individuals can now engage with a wealth of educational content regardless of their geographic location. This global reach of technology has democratized education, breaking down barriers to learning and providing opportunities for individuals in remote areas to access high-quality educational materials.\nAdditionally, online platforms offer flexibility in learning schedules, catering to diverse learner needs, while e-learning significantly reduces costs associated with traditional education, making learning more affordable and accessible to a broader range of individuals. This combination of flexibility and affordability in e-learning not only adapts to the varying schedules and preferences of learners but also breaks down financial barriers, ensuring that education is within reach for a more inclusive and diverse population.\nIn conclusion, technology has played a pivotal role in making education more accessible by enabling global access to resources, offering flexible learning options, and reducing financial barriers through e-learning. Embracing technology in education is essential for creating a more inclusive and equitable learning environment that empowers individuals worldwide to pursue their educational goals.', NULL, 200, 300),
  ('355df174-ca09-5805-9bde-1433b29f5c61'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '355df174-ca09-5805-9bde-1433b29f5c61'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '980c11d4-9e4d-5375-a4ca-2df4a3a93c10'::uuid, NULL, NULL, E'Group projects often lead to good results and teach teamwork.', NULL, NULL),
  ('356286b3-3009-536c-8cdc-75f15763d26b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '356286b3-3009-536c-8cdc-75f15763d26b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f377a95c-9b21-567c-b8dd-da51413dff0a'::uuid, NULL, E'People used to come and visit him after he had a stroke.', NULL, NULL, NULL),
  ('356925af-ef86-50c0-9578-78b46717f3f6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '356925af-ef86-50c0-9578-78b46717f3f6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e6e1f7f5-78ec-583e-9994-788930ef440e'::uuid, NULL, E'The book provides some valuable information on recent economic trends.', NULL, NULL, NULL),
  ('356995eb-400f-52bf-8b1d-8f7cec0dbf1b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '356995eb-400f-52bf-8b1d-8f7cec0dbf1b'::uuid, 1, NULL, TRUE, 0, NULL, E'Masses Particles', NULL, '8edb6e51-2de7-50a4-982e-d531a0cb83d8'::uuid, NULL, E'As physicists try to explain the masses particles, they found that if they just tried to inject the maths into the mathematics equations in a most straight-forward way, just put a parameter for the massive particles right into the math, the math didn''t work. It gave rise to quantum mechanically inconsistent features, so it''s recognized you need to have a more subtle way of introducing mass into the equations. That would not spoil the fundamental symmetries, but yet would allow the particles to have different masses, you see, fundamentally, the idea is that all particles begin life has been massless. There''s a high degree of symmetry associated with it, all the particles have the same math is zero. How do you inject math without spoiling that symmetry which is vital for the equations to make sense. The Higgs field does that by immersing everything in this bath, this molasses-like bath, it turns out that the equations allow you to have you cake and eat it. The fundamental symmetries are deeply preserved and yet the way in which the particles move experiencing different resistance like drag force allows them to have different masses.', NULL, NULL, NULL),
  ('356aa41a-31e9-58dd-9ff9-6edcc950befa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '356aa41a-31e9-58dd-9ff9-6edcc950befa'::uuid, 1, NULL, TRUE, 0, NULL, E'Neurons of Singing', E'Humans may have neurons whose main job is to process singing. Scientists have previously found neurons that are selective for speech and music, suggesting that our brains have specific cells that handle different types of sounds we hear. Sam Norman-Haignere and his colleagues recorded brain electrical activity from 15 people while they listened to 165 different sounds. These included music, speech, animal calls and the sound of a flushing toilet. The participants already had electrodes implanted into their heads, as they were in hospital for epilepsy treatment, which enabled the researchers to get more precise data compared with functional magnetic resonance imaging (fMRI) scans. With these recordings, the researchers discovered a population of neurons that seemed to respond nearly exclusively to singing, although they also had a very small response to speech and instrumental music. ‘This work suggests there’s a distinction in the brain between instrumental music and vocal music,’ says Norman-Haignere. They overlaid these results with fMRI data from 30 other people who listened to the same sounds so that they could map the neurons to a specific region of the brain. The ‘singing’ neurons were located roughly between the music and speech-selective areas of the auditory cortex. Many people think that singing has some important role in the evolution of music. But it’s also totally possible that it’s all driven by exposure.', NULL, NULL, NULL, NULL, 5, 75),
  ('3570a9da-99f1-5768-8fc3-003421bdc3e7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '3570a9da-99f1-5768-8fc3-003421bdc3e7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8a3e5d4b-1143-5a6d-933c-6697f56499d8'::uuid, NULL, NULL, E'The meeting for first-year economics students is on Tuesday.', NULL, NULL),
  ('35717e4c-956a-58b9-9356-e89046b24c87'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '35717e4c-956a-58b9-9356-e89046b24c87'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the action of expressing disapproval of somebody or opinions about someone''s faults and bad qualities?', 'dc27f6ce-c7c8-5b41-b785-80b48d0117be'::uuid, NULL, NULL, E'Criticism / critique', NULL, NULL),
  ('358a438e-3ab8-58f9-b310-f6c1e777e636'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '358a438e-3ab8-58f9-b310-f6c1e777e636'::uuid, 1, NULL, TRUE, 0, NULL, E'Cumulative Advantage', NULL, 'ec3b5f61-9561-55b4-a122-5bbaa0b37677'::uuid, NULL, E'The modern fantasy about wow, business is changing so quickly, you’ve got to keep morphing and changing, updating your brand, getting a new visual identity. All of those things, they’re just bad, bad, bad, bad, bad. Don’t do them. Why? It’s because you interrupt habit. So rather than a consumer thinking about, oh, wow, I am loyal to, let’s say, Tide. I’m loyal to Tide detergent. I really should buy it. It’s actually that person’s subconscious saying, you know, the most comfortable thing to do, the thing we... in your subconscious are most confident of is that thing that worked for us before. So please, please, please don’t think about buying something else. Tide’s been around for 76 years, and it has what we call cumulative advantage. Cumulative advantage is what you increasingly build as the customer becomes more and more comfortable with using your product or service. Each time they use it and get the benefits they wish, you get more cumulative advantage that causes the subconscious to say I’m totally comfortable with this and I would be uncomfortable if we did something else. That’s the win of cumulative advantage.', NULL, NULL, NULL),
  ('358acba3-d06b-5152-b4b8-9ac9f319b2d9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '358acba3-d06b-5152-b4b8-9ac9f319b2d9'::uuid, 1, NULL, TRUE, 0, NULL, E'Thermal Equilibrium', E'The distinction between heat and temperature is {{1}} but very important. Heat refers to the transfer of energy between systems (or bodies), whereas temperature is determined by the energy {{2}} within a singular system (or body). In other words, heat is energy, while temperature is a measure of energy. Adding heat will increase a body''s temperature while removing heat will lower the temperature, thus changes in temperature are the result of the presence of heat, or {{3}} , the lack of heat. Particles have more energy at higher temperatures, and as this energy is transferred from one system to another, the fast-moving particles will collide with slower moving particles. As they collide, the faster particle will transfer some of its energy to the slower particle, and the process will continue until all the particles are {{4}} at the same rate. This is called thermal equilibrium.', NULL, NULL, NULL, E'1.subtle, 2.contained, 3.conversely, 4.operating', NULL, NULL),
  ('3590e108-de40-5328-966f-5149e81d5385'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '3590e108-de40-5328-966f-5149e81d5385'::uuid, 1, NULL, TRUE, 0, NULL, E'Developing a Family', E'As children grow, their needs change from primarily {{1}} (feeding, changing diapers, and sleep) to more cognitive and emotional ones. Parents become the primary source of instilling cultural and spiritual values, as well as {{2}} a child’s individual personality. This period takes a tremendous amount of time and {{3}} from parents as the children remain the focus of daily interactions. Think of the family that runs around taking children to soccer, baseball, piano lessons, church, and {{4}} their educational development. In this stage, the personal development of children is of high importance to the family.', NULL, NULL, NULL, E'1.physical, 2.fostering, 3.commitment, 4.guiding', NULL, NULL),
  ('3591dd3a-7011-55f2-aed2-adb9298ff5e6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3591dd3a-7011-55f2-aed2-adb9298ff5e6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '68cfd050-e298-57ee-990e-3b5df401786b'::uuid, NULL, E'The team must finish the task before the deadline by all means.', NULL, NULL, NULL),
  ('359ab157-7505-59ef-8df8-77cea11ee824'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '359ab157-7505-59ef-8df8-77cea11ee824'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e78be0e8-8956-508f-ad73-7ec625bcf980'::uuid, NULL, NULL, E'An academic essay should use evidence from both primary and secondary sources.', NULL, NULL),
  ('359c1cfe-38c8-5f2b-9e0c-7004855240ef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '359c1cfe-38c8-5f2b-9e0c-7004855240ef'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '709f24b4-1e98-5bbb-9561-5d388cb2720a'::uuid, NULL, NULL, E'I had a sandwich and milk with orange juice for my breakfast.', NULL, NULL),
  ('359cb38f-e20c-5606-9bcc-6018e615345e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '359cb38f-e20c-5606-9bcc-6018e615345e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f5e18700-521a-5284-aa36-fd38adfd8252'::uuid, NULL, NULL, E'His lectures tend to range over a number of topics.', NULL, NULL),
  ('35abec0c-6ab9-57e4-a2fc-be5b7a58d0d6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '35abec0c-6ab9-57e4-a2fc-be5b7a58d0d6'::uuid, 1, NULL, TRUE, 0, NULL, E'Gravity', E'Every object pulls on every other object with an {{1}} force called gravity. This concept was not fully understood until Isaac Newton published the {{2}} of his three laws of motion. Over 300 years ago, Newton clearly {{3}} this invisible force of gravity. The strength of the force is determined by distance and mass. For example, the Earth and the Moon {{4}} each other through gravitational pull, but the Earth exerts a stronger force on the Moon than distant planets like the Jupiter does.', NULL, NULL, NULL, E'1.invisible, 2.theory, 3.explained, 4.affect', NULL, NULL),
  ('35b0af0b-70a2-5c48-a684-74234dd0d671'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '35b0af0b-70a2-5c48-a684-74234dd0d671'::uuid, 1, NULL, TRUE, 0, NULL, E'American Metropolis', E'To a discussion in a history class. Did anyone happen to catch the american metropolis last night? It was about the growth of cities. I didn''t see that, but I did see part of a documentary last week that told about a guy. I think he was a visitor from another country who wrote a book about the growth of industry and so on, the things we''ve just studied. I remember he said there was a huge population explosion that turned america into a nation of cities all within a decade. He was talking mostly about baltimore, baltimore, and then or now in the nineteenth century, right after the civil war. The program you saw was part of the same series as the one I want to tell you about. Last night, the topic was new york city. As early as eighteen eighty, the federal government wrote a report on how the five separate municipalities of new york actually constituted one vast metropolitan area. It was a progressive way of thinking at the time. And within twenty years, those five municipalities were official, united as a single city by a vote of the people. To this day, however, each barrel maintains traces of its original independence. I agree with that. I''m from brooklyn, and it''s definitely different from the rest of new york.\n\nWhat can be inferred about New York City?', 'a20cb53c-152c-5894-a3a1-12b16078b18b'::uuid, NULL, NULL, E'It was originally composed of five separate municipalities.\nIt has a borough called Brooklyn.', NULL, NULL),
  ('35b0b230-6eed-5595-8e92-828b49f53c71'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '35b0b230-6eed-5595-8e92-828b49f53c71'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person who operates a farm, raising animals or crops?', '7c4713a8-a819-593c-95a6-0a632f5fbb14'::uuid, NULL, NULL, E'Farmer', NULL, NULL),
