  ('3656f151-591b-55c4-9cac-d6321a915d75'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '3656f151-591b-55c4-9cac-d6321a915d75'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '42fcae55-0eb1-5d75-b618-87ed4904155d'::uuid, NULL, NULL, E'Banks charge interest on the money they lend to customers.', NULL, NULL),
  ('36572edb-6fed-5df8-9432-bfb72fca30f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '36572edb-6fed-5df8-9432-bfb72fca30f8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for a healthcare professional who provides care and treatment to ill or injured patients?', '49d1a8ad-f25b-55e7-85a8-b48b25ef24f9'::uuid, NULL, NULL, E'Nurse', NULL, NULL),
  ('365bd23e-3780-554c-9e29-71b8f3f83754'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '365bd23e-3780-554c-9e29-71b8f3f83754'::uuid, 1, NULL, TRUE, 0, NULL, E'Metallic Glass', NULL, '3900f602-7452-5e05-9f3a-69ba26a4b723'::uuid, NULL, E'Steel and plastic. These two materials are essential to so much of our infrastructure and technology, and they have a complementary set of strengths and weaknesses. Steel is strong and hard, but difficult to shape intricately. While plastic can take on just about any form, it’s weak and soft. So wouldn’t it be nice if there were one material as strong as the strongest steel and as shapeable as plastic? Well, a lot of scientists and technologists are getting excited about a relatively recent invention called metallic glass with both of those properties, and more. Metallic glasses look shiny and opaque, like metals, and also like metals, they conduct heat and electricity. But they’re way stronger than most metals, which means they can withstand a lot of force without getting bent or dented, making ultrasharp scalpels, and ultrastrong electronics cases, hinges, screws; the list goes on. Metallic glasses also have an incredible ability to store and release elastic energy, which makes them perfect for sports equipment, like tennis racquets, golf clubs, and skis. They’re resistant to corrosion, and can be cast into complex shapes with mirror-like surfaces in a single molding step. Despite their strength at room temperature, if you go up a few hundred degrees Celsius, they soften significantly, and can be deformed into any shape you like. Cool them back down, and they regain the strength.', NULL, NULL, NULL),
  ('3665e7e9-743e-5feb-8032-14a7bc70c284'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3665e7e9-743e-5feb-8032-14a7bc70c284'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the medical examination of a dead body to determine the cause of death?', '5b52794e-d8f3-51f5-966c-b8b8a5473749'::uuid, NULL, NULL, E'Autopsy', NULL, NULL),
