  ('36b514a2-b63e-5787-9c0a-5a7db3f2c600'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '36b514a2-b63e-5787-9c0a-5a7db3f2c600'::uuid, 1, NULL, TRUE, 0, NULL, E'Ecology', E'The study of ecology helps us understand how living organisms interact with each other and their environment, providing insights into how we can protect and preserve natural ecosystems for future generations. It encompasses topics such as biodiversity, conservation biology, and ecosystem services.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('36b56ee6-9b27-5d5e-aa8b-a9fb7ff69648'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '36b56ee6-9b27-5d5e-aa8b-a9fb7ff69648'::uuid, 1, NULL, TRUE, 0, NULL, E'Voting', E'Today, most American citizens over the age of 18 are entitled to vote in federal and state elections, but voting was not always a right for all Americans. Because the Constitution did not specifically say who could vote, this question was largely left to the states in the 1800s. While no longer explicitly excluded, voter suppression is a problem in many parts of the country.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('36bbed1c-8731-5261-83ec-2c7e18b66394'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '36bbed1c-8731-5261-83ec-2c7e18b66394'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'efc0b0ac-2367-5f5a-a69e-46ee01947d24'::uuid, NULL, NULL, E'Essential textbooks can be purchased from the campus bookshop.', NULL, NULL),
  ('36bf5b94-0d73-5952-81f9-4e5277f647e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '36bf5b94-0d73-5952-81f9-4e5277f647e9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c9829cc6-881a-5b05-b9c1-c12dfa8e0ac5'::uuid, NULL, NULL, E'The core subjects for students are English, mathematics and science.', NULL, NULL),
  ('36d0f5d2-7b10-54c1-b3e6-f4305d13b6c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '36d0f5d2-7b10-54c1-b3e6-f4305d13b6c8'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '649db84e-9ce5-51d9-aaea-bc59c32792b6'::uuid, NULL, E'The professional training trip will start soon, so pack your items before we leave.', NULL, NULL, NULL),
  ('36d2e3ab-ccf9-503d-b198-3bd85dd3449a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '36d2e3ab-ccf9-503d-b198-3bd85dd3449a'::uuid, 1, NULL, TRUE, 0, NULL, E'Sea Snail', E'Submarine operators have been alerted to the dangers of sea snails in a recent study. An international research team says the hardy deep-sea animals latch on to the submarines used by scientists, potentially spreading disease in pristine ecosystems.\nThe limpet is a sea snail that lives 2000 metres underwater but can also survive in air when a submarine emerges from the water. If it goes unnoticed, the limpet can find itself in another habitat the next time the submarine is used. As 90 per cent of limpets are infected by parasites, this poses a threat to the ecosystem; but thoroughly cleaning the submarines will solve the problem.\n\nWhat problem does the article mention in relation to sea snails?', NULL, NULL, NULL, E'Sea snails are being carried by submarines to places where they harm other species.', NULL, NULL),
  ('36d93f90-3613-549b-a589-417a286c25bb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '36d93f90-3613-549b-a589-417a286c25bb'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f9be8e08-2047-5741-aa60-dda4a606a9ba'::uuid, NULL, E'Does the professor keep regular office hours?', NULL, NULL, NULL),
  ('36db3a19-82eb-59df-9d9f-4de88abb8779'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '36db3a19-82eb-59df-9d9f-4de88abb8779'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6cd3153f-5c20-55ea-ac5d-6bf36734bb8f'::uuid, NULL, NULL, E'Exam results will be published on the noticeboard.', NULL, NULL),
  ('36dbc727-766b-5f98-a743-3f143f6ec739'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '36dbc727-766b-5f98-a743-3f143f6ec739'::uuid, 1, NULL, TRUE, 0, NULL, E'Peers', E'As children become adolescents, they usually begin spending more time with their peers and less time with their families, and these peer {{1}} are increasingly unsupervised by adults. Children''s notions of friendship often focus on shared activities, {{2}} adolescents'' notions of friendship increasingly focus on intimate {{3}} of thoughts and feelings.', NULL, NULL, NULL, E'1.interactions, 2.whereas, 3.exchanges', NULL, NULL),
  ('36df2bab-3451-504f-be75-6c64b5e4da5d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '36df2bab-3451-504f-be75-6c64b5e4da5d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f7add204-f704-595a-a951-ea3c25a66d55'::uuid, NULL, NULL, E'The restrooms are down the entrance and to the right.', NULL, NULL),
  ('36df339a-7533-5cf8-b2e0-da518f467d6f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '36df339a-7533-5cf8-b2e0-da518f467d6f'::uuid, 1, NULL, TRUE, 0, NULL, E'Trees and Winter', E'The shorter days are a sign to trees to begin to prepare for winter. During winter there is not enough light for photosynthesis to occur, so as the days shorten throughout autumn, the trees begin to close down their food production systems and reduce the amount of chlorophyll in their leaves.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('36e264ab-1873-5979-ac32-931791b4f4cc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '36e264ab-1873-5979-ac32-931791b4f4cc'::uuid, 1, NULL, TRUE, 0, NULL, E'Solanine', E'When potatoes are stored in a warm bright place, the tubers detect that they might be in a suitable growing location and prepare to sprout. Chlorophyll production increases, which slowly tints the peel, and eventually some of the flesh, green. While chlorophyll is a harmless chemical, its {{1}} in potatoes indicates that the tubers have also increased their production of a glycoalkaloid known as solanine. Solanine protects potatoes and other plants in the family Solanaceae from herbivory and serves to {{2}} the sprouting spud from hungry animal mouths. Solanine is considered a neurotoxin, and {{3}} by humans can cause nausea and headaches and can lead to serious neurological problems and even death if enough is consumed. A recent study suggested that a 16-oz (450-gram) fully green potato is enough to make a small adult ill. Cooking does not destroy the solanine toxin, so the green parts of potatoes should be {{4}} entirely. Green potatoes should especially not be served to children, whose smaller bodies make them more susceptible to poisoning.', NULL, NULL, NULL, E'1.presence, 2.preserve, 3.ingestion, 4.removed', NULL, NULL),
  ('36eb39d2-686a-5340-b140-5a3aca327ea1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '36eb39d2-686a-5340-b140-5a3aca327ea1'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a45a0146-d8d2-5ccb-8b37-9296c4ce7991'::uuid, NULL, E'A hypothesis is the first step before an idea becomes a theory.', NULL, NULL, NULL),
  ('36ecc40a-fdf2-57c1-8696-76ce76e3fee1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '36ecc40a-fdf2-57c1-8696-76ce76e3fee1'::uuid, 1, NULL, TRUE, 0, NULL, E'90 European Countries(90个欧洲国家)', NULL, NULL, NULL, NULL, E'4, 1, 3, 2', NULL, NULL),
  ('36f0b634-e439-56fb-a85a-f59ab1f562f7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '36f0b634-e439-56fb-a85a-f59ab1f562f7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd573da4f-e329-5d6b-aa9b-a03b6e50c631'::uuid, NULL, NULL, E'The dance department stages elaborated performances each semester.', NULL, NULL),
  ('36f1ecf7-4804-559e-b491-5d708233762c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '36f1ecf7-4804-559e-b491-5d708233762c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '726e4ce3-89ec-5dad-9b8d-145b873b242d'::uuid, NULL, NULL, E'The assessment procedure has been altered slightly since last year.', NULL, NULL),
  ('36fa0341-12f0-557c-90f1-cf6e344318d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '36fa0341-12f0-557c-90f1-cf6e344318d8'::uuid, 1, NULL, TRUE, 0, NULL, E'Ocean Floors', NULL, NULL, NULL, NULL, E'2, 1, 3, 4, 5', NULL, NULL),
  ('3705e105-3334-5080-8d68-7c3899e93140'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3705e105-3334-5080-8d68-7c3899e93140'::uuid, 1, NULL, TRUE, 0, NULL, E'Why We Dream', NULL, '356929b2-6ac9-5e62-8925-ecd98b7f4aca'::uuid, NULL, E'We dream to fulfill our wishes. In the early 1900s, Sigmund Freud proposed that while all of our dreams, including our nightmares, are a collection of images from our daily conscious lives, they also have symbolic meanings, which relate to the fulfillment of our subconscious wishes. Freud theorized that everything we remember when we wake up from a dream is a symbolic representation of our unconscious primitive thoughts, urges, and desires. Freud believed that by analyzing those remembered elements, the unconscious content would be revealed to our conscious mind, and psychological issues stemming from its repression could be addressed and resolved. We dream to remember. To increase performance on certain mental tasks, sleep is good, but dreaming while sleeping is better. In 2010, researchers found that subjects were much better at getting through a complex 3-D maze if they had napped and dreamed of the maze prior to their second attempt. In fact, they were up to ten times better at it than those who only thought of the maze while awake between attempts, and those who napped but did not dream about the maze. Researchers theorize that certain memory processes can happen only when we are asleep, and our dreams are a signal that these processes are taking place.', NULL, NULL, NULL),
  ('370a27a5-2fe4-5316-bd90-3b764ed82d81'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '370a27a5-2fe4-5316-bd90-3b764ed82d81'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '50bffb53-846b-5849-b856-13318d217bfd'::uuid, NULL, NULL, E'The hypothesis needs to be tested in a more rigorous way.', NULL, NULL),
  ('3710b393-6cc6-517b-b4bd-63a303128a35'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3710b393-6cc6-517b-b4bd-63a303128a35'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for an outdoor area for dining or relaxing that is adjacent to a building?', '02893fc0-9f31-5f87-a6ce-9f98751d3846'::uuid, NULL, NULL, E'Patio', NULL, NULL),
  ('37116747-1d68-5630-bef0-7d45cf3c8f29'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '37116747-1d68-5630-bef0-7d45cf3c8f29'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of a small, mild-flavored bird, often used in fine dining?', '029d90d3-0fa1-585e-a7c2-5d2272f65f01'::uuid, NULL, NULL, E'Quail', NULL, NULL),
  ('37191326-b48a-5fbf-8a04-84fb8844e225'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '37191326-b48a-5fbf-8a04-84fb8844e225'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b981d57f-32fd-5a20-84e5-b6b286fb562d'::uuid, NULL, NULL, E'The final essay is due at the end of this semester.', NULL, NULL),
  ('3720fc42-928e-5542-890a-87a6242ea2ea'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3720fc42-928e-5542-890a-87a6242ea2ea'::uuid, 1, NULL, TRUE, 0, NULL, E'Gorillas', E'While killing gorillas is already illegal in the country, declaring the subspecies as critically endangered would probably bring more funding and support for saving it. Protecting the entirety of the gorilla''s 7,700 square mile territory would no doubt prove impossible, but Dr. Plumptre and his colleagues are talking with the government and community leaders about establishing two new protected areas that would encompass 60 percent of the remaining gorillas'' habitat.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('37222822-aa18-5216-b3ec-6b30aa3a9df2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '37222822-aa18-5216-b3ec-6b30aa3a9df2'::uuid, 1, NULL, TRUE, 0, NULL, E'Rice', E'Certainly in Europe and the West we tend to think of bread as the staple food in our diet, as many proverbs and sayings, such as "bread is the staff of life" attest.\nYet for the majority of Lhe world''s population the most important staple food is not wheat but rice, which is the seed of a different type of grass. The earliest evidence we have of rice being cultivated dates back to eight thousand years ago, when rice grains of that period were discovered in a village in China. By around six thousand years ago, the cultivation of both long-grain and short-grain rice had become well-established in China, and had just got going in India.\nThe word "rice" itself, however, is derived from the Aramaic ourouzza and came to us by way of Greek and Arabic. In fact, it was the Arabs who introduced rice to their Spanish territories in the 7th century, but it didn''t spread to the rest of Europe until much later when, in the 15th century, Spaniards began to cultivate their own short-grain variety at Pisa in Italy.\n\nAccording to the text, who were originally responsible for popularizing rice in Europe?', 'dfa851aa-73fa-53c9-b9e0-8b89dc464231'::uuid, NULL, NULL, E'the Spanish\nthe Arabs', NULL, NULL),
  ('3723130e-9677-57df-84c7-94026683bacd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3723130e-9677-57df-84c7-94026683bacd'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'db5fbf0d-ad3f-57d8-a409-e7f2cee799c2'::uuid, NULL, E'The art museum is located across the street and near the theater.', NULL, NULL, NULL),
  ('37275445-2597-5d7e-8c2f-c84801f241e8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '37275445-2597-5d7e-8c2f-c84801f241e8'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '77ba3118-82db-551d-b4db-5afb3e626767'::uuid, NULL, E'There is a limited amount of departmental funding which is available for qualified students.', NULL, NULL, NULL),
  ('37279a75-1f2a-57bb-9c6c-d441b9d2c461'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '37279a75-1f2a-57bb-9c6c-d441b9d2c461'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '123d09be-35c2-5642-8fa3-cdd27fd462ff'::uuid, NULL, NULL, E'They watched how things happened in the classroom for their study.', NULL, NULL),
  ('372a1b1c-4bc9-58a2-82e0-fd527056cf97'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '372a1b1c-4bc9-58a2-82e0-fd527056cf97'::uuid, 1, NULL, TRUE, 0, NULL, E'Subway', E'Your colleague drives to work, but the traffic is heavy every day. How should you suggest she take the subway for several reasons?', 'fe05e9d6-4b41-5392-920b-ee2f96b4e3a1'::uuid, NULL, NULL, NULL, NULL, NULL),
  ('372bf7c5-3292-5459-9f2c-8320d7f59b29'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', '372bf7c5-3292-5459-9f2c-8320d7f59b29'::uuid, 1, NULL, TRUE, 0, NULL, E'Forgiving', E'Nature’s instruments for survival can be a Godsent until they begin to affect us in destructive ways. Someone’s negative characteristics can cloud their favorable traits to such an extent that we cannot see the positive anymore. In our biased minds, this person has become purely evil. It’s pretty difficult not to feel repulsed by someone who doesn’t have any positive traits – let alone forgive them. So, we might want to look beyond the vast specter of negativity and see that the people we resent are also carrying good within them and that it’s human to possess both evil and...\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '165dea1e-2705-5bae-91ac-82fcff0aa79e'::uuid, NULL, NULL, E'good', NULL, NULL),
  ('372e73a9-9ff2-5a47-a274-78d90638907a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '372e73a9-9ff2-5a47-a274-78d90638907a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ac7855c4-f93c-5f95-826b-c4d4eb944f0e'::uuid, NULL, E'That brief outline takes us to the beginning of the twentieth century.', NULL, NULL, NULL),
  ('37329afe-6d10-5182-ae57-18dd2c375c4d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '37329afe-6d10-5182-ae57-18dd2c375c4d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '097da162-ec58-5987-b359-4b8c5ad7701d'::uuid, NULL, NULL, E'The poster of this play is hung in the large lecture theater.', NULL, NULL),
  ('37345fec-d795-5dd9-8961-d58b34322eba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '37345fec-d795-5dd9-8961-d58b34322eba'::uuid, 1, NULL, TRUE, 0, NULL, E'Noise', NULL, '8f2b2818-aec4-54e1-bb20-0b0247780ee4'::uuid, NULL, E'What else can we do about noise? Well, very much like a carbon footprint, we all have a noise footprint, and there are things we can do to make that noise footprint smaller. For example, don''t start mowing your lawn at 7:00 a.m. on a Saturday morning. Your neighbors will thank you. Or use a rake instead of a leaf blower. In general, noise reduction at the source makes the most sense. So whenever you''re looking to buy a new car,\nair conditioning unit, blender, you name it, make low noise a priority. Many manufacturers will list the noise levels the devices generate, and some even advertise with them. Use that information. Many people think that stronger noise regulation and enforcement are good ideas, even obvious solutions perhaps. But it''s not as easy as you may think, because many of the activities that generate noise also generate revenue. Think about an airport and all the business that is associated with it. Our research tells politicians at what noise level they can expect a certain health effect and that helps inform better noise policy. Robert Koch supposedly once said, "One day, mankind will fight noise as relentlessly as Cholera and the Pest." I think we are there, and I hope that we will win this fight, and when we do, we can all have a nice, quiet celebration.', NULL, NULL, NULL),
  ('373f360a-d072-5dff-b55f-2177ccead7c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '373f360a-d072-5dff-b55f-2177ccead7c5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'caa99c50-34a6-56ba-8682-33514cd16770'::uuid, NULL, NULL, E'Learning to think critically is a big part of good education.', NULL, NULL),
  ('3740ef19-ab2e-53cc-a6e8-059ba2f28231'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '3740ef19-ab2e-53cc-a6e8-059ba2f28231'::uuid, 1, NULL, TRUE, 0, NULL, E'RO', NULL, NULL, NULL, NULL, E'2, 1, 3, 4', NULL, NULL),
  ('374e8b39-2f3d-53b1-848a-dc0911f866b0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '374e8b39-2f3d-53b1-848a-dc0911f866b0'::uuid, 1, NULL, TRUE, 0, NULL, E'Putting People First', NULL, 'f388369c-6d40-5775-be36-2433aea4224b'::uuid, NULL, E'This kind of approach is kind of the way some students approach preparing for standardized tests. In order to get test scores to go up, teachers will end up teaching to the test. Now, that approach can work; test results often do go up. But it fails the fundamental goal of education: to prepare students to succeed over the long term. So given these obstacles, what can we do to transform the way we transform organizations? So rather than being exhausting, it’s actually empowering and energizing? To do that, we need to focus on five strategic imperatives, all of which have one thing in common: putting people first. The first imperative for putting people first is to inspire through purpose. Most transformations have financial and operational goals. These are important and they can be energizing to leaders, but they tend not to be very motivating to most people in the organization. To motivate more broadly, the transformation needs to connect with a deeper sense of purpose. Take LEGO. The LEGO Group has become an extraordinary global company. Under their very capable leadership, they’ve actually undergone a series of transformations. While each of these has had a very specific focus, the North Star, linking and guiding all of them, has been Lego’s powerful purpose: inspire and develop the builders of tomorrow. Expanding globally? It’s not about increasing sales, but about giving millions of additional children access to LEGO building bricks.', NULL, NULL, NULL),
  ('3751c852-b347-5c63-8ca1-6ac7b10712c9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '3751c852-b347-5c63-8ca1-6ac7b10712c9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '11636909-b11b-5f10-828f-a2ed3c1e2c4f'::uuid, NULL, NULL, E'The summer school program allows some students to accelerate their studies.', NULL, NULL),
