  ('37679908-69aa-5186-85c2-cca1043faefb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '37679908-69aa-5186-85c2-cca1043faefb'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the writer or painter whose work represents things as they are in real life?', 'f6c476e4-d4e7-5e0b-a386-065f837a7a85'::uuid, NULL, NULL, E'Realist / realists', NULL, NULL),
