  ('37779f5f-8f66-52aa-b8c2-879a5f9d4a01'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '37779f5f-8f66-52aa-b8c2-879a5f9d4a01'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f6a19f04-5a3c-5269-8261-e7edefa6d96a'::uuid, NULL, E'In the eighteen thirties, periodicals appeared in large numbers in America.', NULL, NULL, NULL),
  ('37780145-ed56-5e63-a478-087ab57cf044'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '37780145-ed56-5e63-a478-087ab57cf044'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '250822e6-8dc3-5402-ad95-164f3a1d9de5'::uuid, NULL, E'There are lots of people competing for places in computer courses.', NULL, NULL, NULL),
  ('377e8851-e540-5528-b025-9288739cba8d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '377e8851-e540-5528-b025-9288739cba8d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '14525e90-fac4-5de1-9562-2b40fe9dfedd'::uuid, NULL, NULL, E'Neuroscience is about how different parts of the brain work.', NULL, NULL),
  ('37807d02-bb0e-5202-90bc-9c4952ebea66'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '37807d02-bb0e-5202-90bc-9c4952ebea66'::uuid, 1, NULL, TRUE, 0, NULL, E'DNA', E'The recipe for making any creature is written in its DNA. So last November when geneticists published the near-complete DNA sequence of the long-extinct woolly mammoth, there was much {{1}} about whether we could bring this behemoth back to life. Creating a living, breathing creature from a genome sequence that exists only in a computer''s memory is not possible right now. But someone someday is sure to try it, {{2}} Stephan Schuster, a molecular biologist at Pennsylvania State University, University Park, and a {{3}} force behind the mammoth genome project.', NULL, NULL, NULL, E'1.speculation, 2.predicts, 3.driving', NULL, NULL),
  ('3784b23d-008e-5948-ace2-9e2f1ac635a0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3784b23d-008e-5948-ace2-9e2f1ac635a0'::uuid, 1, NULL, TRUE, 0, NULL, E'Student Loan', E'Since 2003, borrowing for education advanced faster, in percentage terms, than all other types of consumer debt that includes mortgages, auto loans and credit cards, data from the Federal Reserve Bank of New York show. As of the fourth quarter, student loans represented 10.5 percent of a record $ 13.1 trillion in household debt, up from 3.3 percent at the start of 2003.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('3789303f-d110-5d82-a09b-1fcbc1b20eb9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '3789303f-d110-5d82-a09b-1fcbc1b20eb9'::uuid, 1, NULL, TRUE, 0, NULL, E'Short Weeks', E'In many countries unemployment among young people is a serious problem. One suggested solution is to shorten the working week. What do you think are the advantages and disadvantages? Do you think this policy should apply to just young workers or all age groups?', NULL, NULL, E'Nowadays, whether shortening the working week can solve the problem of unemployment among young people has fueled heated discussions. Proponents claim that shortening the working week fosters expanded recruitment needs, whereas opponents contend that it leads to tight production deadlines. From my perspective, I am convinced that shortening the working week has both advantages and disadvantages and this policy should apply to the whole workforce.\nTo begin with, shorter working hours can create more job opportunities by reducing overtime, increasing hiring, and distributing work. For example, fewer extra hours mean companies need more staff to finish the same tasks and projects. In addition to this, companies may need to recruit new team members to maintain productivity and efficiency and meet deadlines. Other than that, part-time jobs and flexible shifts increase, giving students and young workers more chances. It is thus shown that the advantage of shortening the work week is to bring more job opportunities.\nBesides, I also believe that it is not realistic for some industries due to production needs, customer demands, and strict schedules. On top of that, factory workers need to keep workshop lines running and meet daily targets without delays. Moreover, retail shops need extended opening hours to serve customers during peak shopping times. Recently, I have examined an article arguing that transport drivers have to follow precise schedules and deliver goods on time. This clearly proves that the problem of cutting the workweek length is to cause product delays.\nTo conclude, there is no doubt that more flexible work arrangements and emergency response protocols are essential in today''s world. While some might disagree, the evidence strongly supports that reducing the workweek comes with both benefits and drawbacks and this measure should apply to the entire workforce.', NULL, 200, 300),
  ('378a0ecb-018c-5733-bbd7-3047dcb9c45c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '378a0ecb-018c-5733-bbd7-3047dcb9c45c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call someone who is trained to assist women in childbirth?', '0a030a73-386c-53ea-b4d9-33676ec6138a'::uuid, NULL, NULL, E'Midwife', NULL, NULL),
