  ('3797dde0-2a48-5569-9406-28793d0e00d9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '3797dde0-2a48-5569-9406-28793d0e00d9'::uuid, 1, NULL, TRUE, 0, NULL, E'Estee Lauder', E'She transformed beauty into big business by cultivating classy sales methods and giving away samples. Leonard Lauder, chief executive of the company his mother founded, says she always thought she ''was growing a nice little business.'' And that it is. A little business that {{1}} 45% of the cosmetics market in U.S. department stores. A little business that sells in 118 countries and last year grew to be $3.6 billion big in sales. The Lauder family''s shares are worth more than $6 billion. But early on, there wasn''t a burgeoning business; there weren''t houses in New York, Palm Beach, or the south of France. It is said that at one point there was one person to answer the telephones who {{2}} her voice to become the shipping or billing department as needed. You more or less know the Estee Lauder story because it'' s a chapter from the book of American business folklore. In short, Josephine Esther Mentzer, daughter of immigrants, lived above her father''s hardware store in Corona, a section of Queens in New York City. She started her {{3}} by selling skin creams concocted by her uncle, a chemist, in beauty shops, beach clubs and resorts. No doubt the potions were good - Estee Lauder was a quality fanatic - but the sales lady was better. Much better. And she simply outworked everyone else in the cosmetics industry. She {{4}} the bosses of New York City department stores until she got some counter space at Saks Fifth Avenue in 1948. And once in that space, she utilized a personal selling approach that proved as {{5}} as the promise of her skin regimens and perfumes .', NULL, NULL, NULL, E'1.controls, 2.changed, 3.enterprise, 4.stalked, 5.potent', NULL, NULL),
  ('379bbee0-4d42-570b-992f-c272880105df'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '379bbee0-4d42-570b-992f-c272880105df'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ae6cf50b-8ba9-55ec-b16c-8c1a0ad641d7'::uuid, NULL, E'Many of the urban poor lived in an extremely cramped condition.', NULL, NULL, NULL),
  ('37a0432c-bbdf-59b9-8533-b12e89c8a012'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '37a0432c-bbdf-59b9-8533-b12e89c8a012'::uuid, 1, NULL, TRUE, 0, NULL, E'Mandarin', E'Because Mandarin is the most commonly spoken dialect, many people use the word Chinese to refer to it. While roughly 70 percent of the country speaks Mandarin, many other dialects are spoken as well. The languages are mutually intelligible to a varying degree, depending on how close the languages are to one another.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('37a370e9-ca20-533a-b5b6-86b28bf969ac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '37a370e9-ca20-533a-b5b6-86b28bf969ac'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '66124e4f-73d4-515f-a050-afd37ce81b82'::uuid, NULL, NULL, E'They trust in the information received from the girl.', NULL, NULL),
  ('37ad5647-d60d-5f0e-a294-3b079909ae52'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '37ad5647-d60d-5f0e-a294-3b079909ae52'::uuid, 1, NULL, TRUE, 0, NULL, E'First Impression', E'First impressions based on facial appearance predict many important social outcomes. We investigated {{1}} such impressions also influence the communication of scientific findings to lay audiences, a process that {{2}} public beliefs, opinion, and policy. First, we investigated the traits that {{3}} interest in a scientist''s work, and those that create the impression of a "good scientist" who does high-quality research. Apparent competence and morality were positively related to both interest and quality judgments, {{4}} attractiveness boosted interest but decreased perceived quality. Next, we had members of the public choose real science news stories to read or watch and found that people were more likely to choose items that were paired with "interesting-looking" scientists, especially when selecting video-based communications. Finally, we had people read real science news items and found that the research was judged to be of higher quality when paired with researchers who look like "good scientists." Our findings offer insights into the social psychology of science, and indicate a source of bias in the dissemination of scientific findings to broader society.', NULL, NULL, NULL, E'1.whether, 2.shapes, 3.engender, 4.whereas', NULL, NULL),
  ('37ae4c74-bad1-5433-8bf3-0d4349f19ad5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '37ae4c74-bad1-5433-8bf3-0d4349f19ad5'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '85a42cda-9000-58f1-a674-1d022a4935dd'::uuid, NULL, E'Some avian species are capable of sleeping while in flight.', NULL, NULL, NULL),
  ('37ae6ef9-f39f-5bbb-91ac-783de245a75c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '37ae6ef9-f39f-5bbb-91ac-783de245a75c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '761a51c4-7078-5e68-b422-9974391bf0de'::uuid, NULL, E'A high wall separated our back yard from the playing field.', NULL, NULL, NULL),
