  ('380cdec6-3c87-507c-a968-8465aa375c4c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '380cdec6-3c87-507c-a968-8465aa375c4c'::uuid, 1, NULL, TRUE, 0, NULL, E'Circadian Dysrhythmia', E'If you hop a plane across several time zones, you may {{1}} up with circadian dysrhythmia. It’s a temporary sleep disorder where your body’s internal clock isn’t in {{2}} with the time cues in your destination — daylight, dark of night, mealtimes. If you plan for it, you can do most of your {{3}} to your destination a few days in advance.', NULL, NULL, NULL, E'1.end, 2.sync, 3.acclimatizing', NULL, NULL),
  ('3810da2c-4ac1-54c6-a52a-d42a886f050f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3810da2c-4ac1-54c6-a52a-d42a886f050f'::uuid, 1, NULL, TRUE, 0, NULL, E'Summerhill School', E'Founded in 1921 by A.S. Neill, the Summerhill School is known for its unique approach to education. At Summerhill, students have the freedom to choose their own activities and are encouraged to participate in the decision-making process. This student-centered approach promotes self-expression, creativity, and personal development.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('3812653e-2fef-5b22-aa27-ac1317efacda'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3812653e-2fef-5b22-aa27-ac1317efacda'::uuid, 1, NULL, TRUE, 0, NULL, E'Social Media', E'Social media has become ubiquitous in modern society, but its impact on mental health is still being studied. Research suggests that social media use can lead to feelings of loneliness, anxiety, and depression, highlighting the need for responsible use and regulation. It is important for individuals to be mindful of their social media use and to seek support if they are experiencing negative effects on their mental health.', NULL, NULL, NULL, NULL, NULL, NULL),
