  ('3823ac0c-bc95-5bdf-8e7b-6b8258728809'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '3823ac0c-bc95-5bdf-8e7b-6b8258728809'::uuid, 1, NULL, TRUE, 0, NULL, E'Boeing Discipline', E'Boeing encourages employees to promptly {{1}} concerns about safety, quality, potential violations of the law, or Boeing policy. Boeing also works to {{2}} an environment in which employees feel safe {{3}} guidance, raising concerns, and identifying areas for improvement. Any retaliation against employees who raise a concern is not {{4}} and is grounds for discipline, up to and including termination.', NULL, NULL, NULL, E'1.raise, 2.foster, 3.seeking, 4.tolerated', NULL, NULL),
