  ('38308a66-87cc-5b8b-ad5b-42e80f64c863'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '38308a66-87cc-5b8b-ad5b-42e80f64c863'::uuid, 1, NULL, TRUE, 0, NULL, E'Mars Eruptions', E'NASA Confirms Thousands of Massive, Ancient Volcanic Eruptions on Mars: Scientists found evidence that a region of northern Mars called Arabia Terra experienced thousands of "super eruptions," the biggest volcanic eruptions known, over a 500-million-year period.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('3832e646-41b9-5618-ba32-2a8317fd2a0b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '3832e646-41b9-5618-ba32-2a8317fd2a0b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f0219402-b090-5ea1-9a1b-3c60fca9cb55'::uuid, NULL, NULL, E'Some students were absent due to the train delay.', NULL, NULL),
  ('383b5ea8-8b33-5a8b-bac3-1ba3bebd6c4d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '383b5ea8-8b33-5a8b-bac3-1ba3bebd6c4d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4e7901bf-c7af-5ae9-a825-a6e69b7e8145'::uuid, NULL, NULL, E'Our sociology department has a global reputation for its outstanding quality.', NULL, NULL),
  ('38462f5b-1736-5018-a6df-f708e8d04aaa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '38462f5b-1736-5018-a6df-f708e8d04aaa'::uuid, 1, NULL, TRUE, 0, NULL, E'Hitting a Deer', E'The risk of hitting a deer varies by time of day, day of the week, the monthly lunar cycle and seasons of the year. These accident cycles are partly a function of driver behavior – they are highest when traffic is heavy, drivers are least alert and driving conditions are poorest for spotting animals. They are also affected by deer behavior.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('3848913f-063a-5241-97e4-39a8346cec9f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '3848913f-063a-5241-97e4-39a8346cec9f'::uuid, 1, NULL, TRUE, 0, NULL, E'Seasonal Affective Disorder', E'Seasonal affective disorder (SAD) is a type of depression that sets in or starts in the winter months. Unlike other types of depression, it is often a cyclical, recurring disorder — you''ll feel depression every winter and begin to feel better each spring.\nSAD depression is caused by lowered levels of serotonin, the mood-affecting brain chemical that is triggered by seasonal changes in daylight. Shorter days may also disrupt the body’s biological clock — circadian rhythm — which upsets the balance of melatonin, the hormone which regulates mood and sleep patterns.\nSAD is far more common in northern climates, where days can be very short in winter. Replacing light bulbs in your home with full spectrum light bulbs can help because they emit light similar to sunlight.\nStudies have shown that upping your exercise routine can counteract SAD. Exercise raises levels of serotonin and also increases levels of endorphins, which are responsible for runner’s high and have been shown to fight depression. Moderate exercise such as walking, riding a stationary bike, or swimming is a great way to get started.\nVitamin D is necessary for the synthesis of serotonin and dopamine (chemicals associated with depression), so researchers concluded that a link between low vitamin D levels and depression was logical. The Vitamin D Council recommends 2,000 IU daily, but suggests taking more if you get little exposure to the sun.\nAnother way to prevent SAD is to eat more fish. Fatty fish, such as salmon and sardines, contain omega-3 fatty acids. Studies have found that people who have low levels of two chemicals found in fish, eicosapentaenoic acid (EPA) and docosahexaenoic acid (DHA), are at increased risk for depression.', NULL, NULL, NULL, NULL, 5, 75),
  ('384adfec-8296-5907-aeb9-35fe4d029d99'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '384adfec-8296-5907-aeb9-35fe4d029d99'::uuid, 1, NULL, TRUE, 0, NULL, E'Plants and Animals', E'No matter where we go on the planet, there are stunning plants, flowers, and animals that catch our attention. They are two very important aspects of any ecosystem. Of all the living organisms on the planet, the most commonly seen by us are the plant life and the animal life.', NULL, NULL, NULL, NULL, NULL, NULL),
