  ('38623cbc-5095-5fcd-ad90-2358d3b5e11d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '38623cbc-5095-5fcd-ad90-2358d3b5e11d'::uuid, 1, NULL, TRUE, 0, NULL, E'Fast Food', E'Hundreds of millions of American people eat fast food every day without giving it too much thought, unaware of the subtle and not so subtle ramifications of their purchases. They just grab their tray off the counter, find a table, take a seat, unwrap the paper, and dig in. The whole experience is transitory and soon forgotten.', NULL, NULL, NULL, NULL, NULL, NULL),
