  ('38910eff-9134-5643-84de-fc3fdfe2b5fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '38910eff-9134-5643-84de-fc3fdfe2b5fb'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the leader of a municipal government?', 'd74b2df0-0203-5d57-9eeb-c4347d5d8813'::uuid, NULL, NULL, E'Mayor', NULL, NULL),
  ('38937344-3e1b-58fd-bc7f-13cfa85fd717'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '38937344-3e1b-58fd-bc7f-13cfa85fd717'::uuid, 1, NULL, TRUE, 0, NULL, E'Isolation', E'Psychiatrists say the covid pandemic and the focus on social distancing has made us all a bit more lonely and a bit more awkward around other people. I would like to emphasize the consequences of isolation and loneliness the most, because it is no doubt an extremely important factor that affects both physical and mental health. People who spend a long time in isolation, like prisons or hospitals or Antarctica if you will, definitely lose certain social skills. And the longer they stay, the more they lose. Marchian Prohasko spent almost two months in Antarctica. He went there in early 2019 to write a book about the experience of being at a polar station. Later during quarantine, Marchionne often drew parallels with his time at the South Pole.\n\nWhat is the similarity between staying at Antarctica and being in quarantine according to the passage?', '2a419737-f93c-5fe6-9b71-6c7d73c987c5'::uuid, NULL, NULL, E'People tend to become less sociable.', NULL, NULL),
  ('3898332e-ce23-50a1-b036-d0da1e1cd8e4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3898332e-ce23-50a1-b036-d0da1e1cd8e4'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the opposite word of ‘export’?', '583c61ed-84a2-5dc3-afe0-4c0f8c41b628'::uuid, NULL, NULL, E'Import', NULL, NULL),
  ('3899dc81-25de-5571-a2cb-5f1fc917ff5a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3899dc81-25de-5571-a2cb-5f1fc917ff5a'::uuid, 1, NULL, TRUE, 0, NULL, E'Garden Care', E'You''re about to go on vacation and are worried that no one will take care of your garden plants. You want to ask your neighbor if they could help. One morning, you see her standing at the door and want to ask if she could water the plants twice a week. What should you say to your neighbor?', '032cf631-b4fe-54f3-9177-2f9c75a722bb'::uuid, NULL, E'Hi neighbour, I want to talk to you about something.\nWe seem to have a little issue with my garden plants during my vacation.\nIt''s like I’m going away on holiday soon and I’m worried there’s nobody to look after my plants. I saw you standing at your door just now, could you please help water them twice a week while I’m gone?\nAnd I''d like to know what you think.', NULL, NULL, NULL),
