  ('38cb2b90-1c45-5b95-9c4d-6c1df08de53f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '38cb2b90-1c45-5b95-9c4d-6c1df08de53f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'cf71c939-9807-5125-977b-e691b858bdc9'::uuid, NULL, NULL, E'We should never underestimate the power of creative design.', NULL, NULL),
  ('38cb885e-4435-5c33-8b22-96d88c4b0037'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '38cb885e-4435-5c33-8b22-96d88c4b0037'::uuid, 1, NULL, TRUE, 0, NULL, E'Disease Model', E'The disease model remains dominant in the U.S. because of its stakeholders. First, the rehab industry, worth an estimated 35 billion dollars per year, uses the disease nomenclature in a vast majority of its ads and slogans. Despite consistently low success rates, that''s not likely to stop because it pulls in the cash. Second, as long as addiction is labeled a disease, medical insurance providers can be required to pay for it.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('38cf15c2-ff1b-5000-b73d-7442b1cf200d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '38cf15c2-ff1b-5000-b73d-7442b1cf200d'::uuid, 1, NULL, TRUE, 0, NULL, E'Facial Expression', E'Researchers trained a program to detect when a smile is genuine. Visual computing researchers at the University of Bradford in the U.K. started with software for analyzing a changing facial expression. This program can examine a video clip of a human head and identify specific details around the eyes, cheeks and mouth. Then the program tracks the details moving relative to each other as the face smiles.\nNext, the scientists had their program evaluate two sets of video clips. In one, subjects performed posed smiles. In the other, they watched a film that inspired genuine displays of emotion. The program calculated the differences among the subjects'' faces during the two clips. And it turns out that your mouth, cheeks and eyes move differently when you''re faking that smirk.\nIn particular, the muscles around the eyes shift 10 percent more for a real smile than they do for a fake one. These results are in the journal Advanced Engineering Informatics.\n\nWhich of the following statements are true about this passage?', '5432ac71-df3b-557d-9b97-4a652d4f4e15'::uuid, NULL, NULL, E'Software can recognize people''s facial expressions to determine whether people pretend to smile.\nThe program can track and identify specific details around the eyes, cheeks and mouth.', NULL, NULL),
  ('38d55f2b-dbe8-5808-836f-938aae43a4af'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '38d55f2b-dbe8-5808-836f-938aae43a4af'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the top surface inside the room?', 'aa41f3c1-44b6-565b-a83a-d9beb6e9d55b'::uuid, NULL, NULL, E'Ceiling', NULL, NULL),
