  ('38dfd110-2479-5a1d-83df-9fb5e62f089c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '38dfd110-2479-5a1d-83df-9fb5e62f089c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'To which of our sense do all of the following words relate, opaque, vivid, brilliant, shiny?', '18562fa8-39be-5de2-91d2-437a09c799a1'::uuid, NULL, NULL, E'Vision', NULL, NULL),
  ('38e59754-5ae1-591f-84cb-869c7075d4ae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '38e59754-5ae1-591f-84cb-869c7075d4ae'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3e6f9584-26f8-5e64-b25e-c2fce7381dc9'::uuid, NULL, NULL, E'Sociology policies from the government try to fix social issues.', NULL, NULL),
  ('38e74213-d089-5fcd-bb23-0b5c307f21bc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '38e74213-d089-5fcd-bb23-0b5c307f21bc'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '28d3d38a-13a3-54cb-9fb9-59398b111881'::uuid, NULL, NULL, E'Students are advised that all the lectures today have been canceled.', NULL, NULL),
  ('38f73890-e875-536b-b9d9-08e821cbd5fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '38f73890-e875-536b-b9d9-08e821cbd5fd'::uuid, 1, NULL, TRUE, 0, NULL, E'Exposition', E'Exposition is a literary term that refers to the part of a story that sets the stage for the drama to follow: it introduces the theme, setting, characters, and circumstances at the story’s beginnings. To understand what exposition is, look at how the writer sets the scene for the story and the characters within it.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('38fa0400-1e7c-528f-bf35-ca15522e0982'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '38fa0400-1e7c-528f-bf35-ca15522e0982'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '326af186-f831-541e-865c-199a07b308f2'::uuid, NULL, NULL, E'An introduction to various information technologies has been given to students.', NULL, NULL),
  ('3900d805-82d0-5ad5-af38-800520c560fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3900d805-82d0-5ad5-af38-800520c560fd'::uuid, 1, NULL, TRUE, 0, NULL, E'Shrimp Farm', E'Shrimp farmers used to hold animals in nursery ponds for 30 to 60 days; now they try to move them into grow-out ponds in less than 30 days. This reduces stress on the animals and dramatically increases survivals in the grow-out ponds. Many farms that abandoned nursery ponds have gone back to them, and the results have been surprisingly positive. They''re using the old, uncovered, earthen, nursery ponds.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('390782ba-2d51-5c1a-a026-d3966420d94a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '390782ba-2d51-5c1a-a026-d3966420d94a'::uuid, 1, NULL, TRUE, 0, NULL, E'Brain Bus', E'Why does the smell of cut grass remind you of summer? How can you measure your nerve endings with a paper fastener? And how can you create the sound of church bells with just a serving spoon and a piece of string ...? These {{1}} questions and more will be revealed by University of Manchester scientists when they take to the road on their ''Brain Bus''. The bus is taking hands-on {{2}} to test the senses to the suburbs, to show young and old alike how the brain works and how science can answer some of life''s most captivating questions.\nOrganizer Dr Stuart Allan, lecturer at the Faculty of Life Sciences, explains: "Three-year-olds and upwards can understand the senses and it''s an area that is {{3}} to all ages." It takes effort to get out of bed on a Saturday morning and go to the Museum. We are bringing science to your doorstep and going further afield this year in the hope of finding new and different {{4}} . "We want people to see that science is interesting as well as important in our lives, and to {{5}} people who may not consider it possible to go to University."', NULL, NULL, NULL, E'1.fascinating, 2.activities, 3.intriguing, 4.audiences, 5.encourage', NULL, NULL),
  ('3907f2f0-a8a4-53a5-b8c6-e5f10dcea20e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3907f2f0-a8a4-53a5-b8c6-e5f10dcea20e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '403bd3b7-2fa7-504b-9766-71c68812d652'::uuid, NULL, E'I didn’t understand the author’s point of view on immigration.', NULL, NULL, NULL),
