  ('396df68e-c8de-570f-9b64-e0aa2f552e1a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '396df68e-c8de-570f-9b64-e0aa2f552e1a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '462ba841-1784-553a-9fc5-a26a99ebf054'::uuid, NULL, NULL, E'Art and design is a competitive field to work in.', NULL, NULL),
  ('39779ced-5378-5545-99a8-07bfdb9e3bc5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '39779ced-5378-5545-99a8-07bfdb9e3bc5'::uuid, 1, NULL, TRUE, 0, NULL, E'Child-Centric Mother', E'The conducted study serves three objectives. The first objective is to reveal the {{1}} loaded to the child by the child-centric mother''s attitude and the effect of 5-6-year-old nursery school children on the purchasing decision of families who belong to a high socio-economic class. The second objective is to {{2}} a child centricity scale and the third object is to examine the attitude and behaviour {{3}} between low child-centric and high child-centric mothers. {{4}} the data gathered from 257 mother respondents, the researchers have found that the lowest influence of the child upon the purchasing decisions of the family are those which carry high purchasing risk and are used by the whole family, whereas the highest influence of the child upon the purchasing decision of the family are the products with low risk used by the whole family. Findings also reveal that there are statistically significant differences between the high child-centric and low child-centric mothers regarding purchasing products that are highly risky and used by the whole family.', NULL, NULL, NULL, E'1.values, 2.develop, 3.differences, 4.Analysing', NULL, NULL),
  ('397a39c8-aa4f-5489-895a-cf84e6b2248c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '397a39c8-aa4f-5489-895a-cf84e6b2248c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a formal agreement or treaty between two or more states?', 'a328ea30-0775-5f06-98cf-a14f099bb9cc'::uuid, NULL, NULL, E'Alliance', NULL, NULL),
  ('397e42bf-24a9-5c75-a5bb-579ad4b492df'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '397e42bf-24a9-5c75-a5bb-579ad4b492df'::uuid, 1, NULL, TRUE, 0, NULL, E'Australian Women Novelist', E'In the literary world, it was an accepted assumption that the 1970s was a time of unprecedented growth in homegrown Australian fiction. And everybody was reading and talking about books by young Australian women.\nBut it was {{1}} that a researcher was able to measure just how many novels were published in that decade, and she found that there had been a decline in novels by Australian writers overall, but confirmed an increase in women''s novels.\nIt is this sort of research - testing ideas about literary history - that {{2}} with the spread of ''Digital Humanities.''\nThe intersection of Humanities and digital technologies is opening up opportunities in the fields of literature, linguistics, history and language that {{3}} computational methods and digitised resources to {{4}} information together in an accessible way.\nTranscription software is being developed for turning scans of books and documents into text, as the field of digital humanities really {{5}} .', NULL, NULL, NULL, E'1.not until recently, 2.is becoming possible, 3.were not possible without, 4.bring, 5.takes off', NULL, NULL),
  ('398bb9ad-c441-5ce5-b0f0-7cb5c9134d13'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '398bb9ad-c441-5ce5-b0f0-7cb5c9134d13'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '88c98789-b905-5453-a6e1-324cc1a405e1'::uuid, NULL, E'We have already succeeded in working out ground rules with the department.', NULL, NULL, NULL),
  ('398fb7c3-13b4-5086-840a-1fb24d81b2ef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '398fb7c3-13b4-5086-840a-1fb24d81b2ef'::uuid, 1, NULL, TRUE, 0, NULL, E'Fake Memory', NULL, '1b1bb232-c3f4-569b-861d-deb7a1c6b1c0'::uuid, NULL, E'Our memories are sometimes unreliable. And though we still don’t know precisely what causes this fallibility on a neurological level, research has highlighted some of the most common ways our memories diverge from what actually happened. The mall study highlights how we can incorporate information from outside sources, like other people or the news, into our personal recollections without realizing it. This kind of suggestibility is just one influence on our memories. Take another study, in which researchers briefly showed a random collection of photographs to a group of participants, including images of a university campus none of them had ever visited. When shown the images three weeks later, a majority of participants said that they had probably or definitely visited the campus in the past. The participants misattributed information from one context— an image they’d seen— onto another— a memory of something they believed they actually experienced. In another experiment, people were shown an image of a magnifying glass, and then told to imagine a lollipop. They frequently recalled that they saw the magnifying glass and the lollipop. They struggled to link the objects to the correct context— whether they actually saw them, or simply imagined them.', NULL, NULL, NULL),
  ('399b5282-5712-5664-9a64-9704903f1e8c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '399b5282-5712-5664-9a64-9704903f1e8c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b1260d0d-2042-5362-af74-e1a316802bfc'::uuid, NULL, NULL, E'Philosophy uses logic and reason to analyze human experience.', NULL, NULL),
  ('399d723a-2ba6-5879-b7c7-40d14f2977b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', '399d723a-2ba6-5879-b7c7-40d14f2977b9'::uuid, 1, NULL, TRUE, 0, NULL, E'Chronic Loneliness', E'Chronic loneliness can also change your body on a cellular level. Research has found that lonely people have 209 different gene expressions in some of their white blood cells, including increased activity of pro-inflammatory transcription factor. Now, inflammation is an important response to injury, but chronic inflammation wreaks havoc on your body. As a result, we see that poor social relationships show a 29% increase in coronary heart disease and 32% increase of a stroke. Overall, people with strong social relationships have a 50% increased likelihood of survival overall – that means they are much less likely to die over the same period of time, making loneliness as deadly of a risk factor as smoking 15 cigarettes a day, lack of exercise, or obesity! So yes, loneliness can increase...\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '4ae7a445-bed7-537f-bb77-186b007a38e9'::uuid, NULL, NULL, E'your chance of death', NULL, NULL),
  ('39a08c85-a471-5003-beee-d31511cb5d97'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '39a08c85-a471-5003-beee-d31511cb5d97'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2af47d4f-6513-53b4-bc33-8d11ae32d04e'::uuid, NULL, E'Agriculture is still largely based on traditional methods in some countries.', NULL, NULL, NULL),
  ('39a0e880-75ed-500f-a1f6-9ddffdf68979'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '39a0e880-75ed-500f-a1f6-9ddffdf68979'::uuid, 1, NULL, TRUE, 0, NULL, E'Work-life Balance', E'In today''s fast-paced society, the concept of work-life balance has taken on {{1}} importance. As people navigate demanding careers and hectic schedules, finding time for personal well-being and leisure activities has become increasingly challenging. Striking the right {{2}} between professional and personal commitments is essential for maintaining physical and mental health. The rise of remote work and flexible schedules has provided individuals with greater {{3}} to manage their time and create a work environment that suits their needs. However, this newfound flexibility can also blur the boundaries between work and personal life, leading to burnout and {{4}} stress. To combat these challenges, it''s crucial for individuals to establish clear boundaries and practice effective time management. Additionally, organizations can play a role by promoting a culture of {{5}} and supporting employees in achieving a healthy work-life balance.', NULL, NULL, NULL, E'1.paramount, 2.equilibrium, 3.flexibility, 4.heightened, 5.cooperation', NULL, NULL),
  ('39a29dfc-876e-58bd-b52c-f931797a0fa4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '39a29dfc-876e-58bd-b52c-f931797a0fa4'::uuid, 1, NULL, TRUE, 0, NULL, E'Composite Materials', E'Airplane {{1}} have been changing over from aluminum to advanced composite {{2}} . These lighter, stronger composites are made of fibers of carbon or glass embedded in a second material, often plastic.\nOne advantage is that composite-based planes use significantly less fuel. But there''s an important disadvantage. When aluminum is hit, you can see a dent. {{3}} , though, spring back to the original shape, which could hide internal damage.\nOne technique to test composite material takes advantage of heat transfer. Inspectors place large heaters next to a section of the plane. Any cracks will alter the flow of heat, and these changes can be picked up with a heat-sensitive camera. But this {{4}} bulky and expensive {{5}} .\nNow M.I.T. researchers have designed a new system. All you need is carbon {{6}} included in the composite, because nanotubes will heat up in response to a small electric current. This can be produced with a handheld device. Any internal deformations will still change the heat flow, which can be picked up by the thermal camera. The research was published in the journal Nanotechnology.\nThis technique offers the ability to detect very small cracks—which could help keep passengers safer in the skies.', NULL, NULL, NULL, E'1.manufacturers, 2.materials, 3.Composites, 4.involves, 5.equipment, 6.nanotubes', NULL, NULL),
  ('39a2adfd-85bc-531b-96cf-d7fab532e7fc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '39a2adfd-85bc-531b-96cf-d7fab532e7fc'::uuid, 1, NULL, TRUE, 0, NULL, E'DNA', E'DNA is a molecule that does two things. First, it acts as the {{1}} material, which is passed down from generation to generation. Second, it directs, to a considerable extent, the construction of our bodies, telling our cells what kinds of molecules to make and {{2}} our development from a single-celled zygote to a fully formed adult. These two things are of course {{3}} . The DNA sequences that construct the best bodies are more likely to get passed down to the next generation because well-constructed bodies are more likely to survive and {{4}} to reproduce. This is Darwin''s theory of natural selection stated in the language of DNA.', NULL, NULL, NULL, E'1.hereditary, 2.guiding, 3.connected, 4.thus', NULL, NULL),
  ('39a4e67a-2c63-516f-8497-c717a30f0fe8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '39a4e67a-2c63-516f-8497-c717a30f0fe8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call a statue or a building that is dedicated in memory of someone?', '953385bd-a1da-5608-90c1-9319258fe58d'::uuid, NULL, NULL, E'Monument / memorial', NULL, NULL),
