  ('39c5656a-a4d4-5cd3-bd1d-a7c6df3cbd19'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '39c5656a-a4d4-5cd3-bd1d-a7c6df3cbd19'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the shape of the earth''s orbit?', '6f45410d-685f-5b9e-8ef7-c571d092233c'::uuid, NULL, NULL, E'Oval / ellipse', NULL, NULL),
