  ('39c7ee12-0a0e-57d6-b824-7a15abbc39d2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '39c7ee12-0a0e-57d6-b824-7a15abbc39d2'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '236587a0-f5fa-54fb-acdd-7903baf315f3'::uuid, NULL, E'The campaign aims to motivate young people to improve their educational achievements.', NULL, NULL, NULL),
  ('39d03778-eaf2-5fc0-aa8f-25e1514fdefa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '39d03778-eaf2-5fc0-aa8f-25e1514fdefa'::uuid, 1, NULL, TRUE, 0, NULL, E'Ballet-pantomime', E'Most important of all is the fact that for each new ballet-pantomime created at the Paris Opera during the July Monarchy, a new score was produced. The reason for this is simple: these ballet-pantomimes told stories — elaborate ones — and music was considered an indispensable tool in getting them across to the audience. Music, {{1}} , had to be newly created to fit each story. Music tailor-made for each new ballet-pantomime, however, was only one weapon in the Opera''s explanatory arsenal. And {{2}} was the ballet-pantomime libretto, a printed booklet of fifteen to forty pages in length, which was sold in the Operas lobby(like the opera libretto), and which laid out the plot in painstaking detail, scene by scene. Critics also took it upon themselves to recount the plots (of both ballet-pantomimes and operas) in their {{3}} of premieres. So did the publishers of souvenir albums, which also featured pictures of famous {{4}} and of scenes from favorite ballet-pantomimes and operas.', NULL, NULL, NULL, E'1.therefore, 2.another, 3.reviews, 4.performers', NULL, NULL),
  ('39d06cbe-64e6-53ae-9db5-c21d02abb02b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '39d06cbe-64e6-53ae-9db5-c21d02abb02b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '85d4212b-82cd-50ad-891b-3708898786a5'::uuid, NULL, NULL, E'The paper has the potential to transform life science.', NULL, NULL),
  ('39d6609a-a911-554d-a7e8-254379a137aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '39d6609a-a911-554d-a7e8-254379a137aa'::uuid, 1, NULL, TRUE, 0, NULL, E'Positive Parenting', E'Positive parenting practices have been linked to improved child outcomes in a range of areas, including academic achievement, mental health, and social skills. Positive parenting involves establishing clear rules and boundaries, providing emotional support and encouragement, and fostering open communication with children.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('39def9e7-bbc1-5d1b-83a4-12e221e0d4b5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '39def9e7-bbc1-5d1b-83a4-12e221e0d4b5'::uuid, 1, NULL, TRUE, 0, NULL, E'Ford Motor', E'Ford Motor has added a third production shift to its Michigan plant that produces the electric F-150 Lightning as it looks to boost output. The addition of the third shift comes as the automaker is {{1}} the newly built facility to hit a top capacity of 150,000 units by next fall. Ford is on {{2}} to hit that previously announced production milestone, Corey Williams, plant manager of the Dearborn Truck Plant and Rouge electric vehicle center, said during a tour of the facility Tuesday. The third shift was added in November, {{3}} up the electric truck plant''s employment from 500 to roughly 750 people. The plant is now running three rotating crews of workers on 10-hour shifts seven days a week, Williams said, maintaining a high level of production even as construction workers scramble to {{4}} an expansion of the facility. “That''s how we''re doing this fast. We''re building product while building” out the factory, Williams said.', NULL, NULL, NULL, E'1.expanding, 2.track, 3.bumping, 4.complete', NULL, NULL),
  ('39e58abb-b346-5318-ab7e-3fe69f314b83'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '39e58abb-b346-5318-ab7e-3fe69f314b83'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c4175c14-3453-5dfd-9249-df3699512192'::uuid, NULL, NULL, E'The project is concerned with the solutions for financial problems.', NULL, NULL),
