  ('3a4a0ddf-25cf-5bf6-8d69-b68d93079265'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3a4a0ddf-25cf-5bf6-8d69-b68d93079265'::uuid, 1, NULL, TRUE, 0, NULL, E'Human Predilection', E'Networking is easy and fun because it taps into this human predilection to talk about ourselves when asked. Consider successful networking as little more than the process of guiding a person to tell you about his life, what he''s doing, the company that employs him, and his current industry.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('3a551693-fd81-5004-b7a7-8a77d35d2a1a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '3a551693-fd81-5004-b7a7-8a77d35d2a1a'::uuid, 1, NULL, TRUE, 0, NULL, E'Circulation', E'Circulation is the {{1}} movement of blood throughout the body, driven by the {{2}} action of the heart. The circulation of the blood links the sites of oxygen {{3}} and uptake in the body; thus, it is {{4}} to ensuring that oxygen-rich blood reaches tissues and back to the lungs. The rapidity of circulation is {{5}} by the output of the heart, which in turn is responsive to overall body requirements.', NULL, NULL, NULL, E'1.continuous, 2.pumping, 3.utilization, 4.critical, 5.determined', NULL, NULL),
  ('3a59dae0-a2ac-5863-b0a1-c8cd90aa13fa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3a59dae0-a2ac-5863-b0a1-c8cd90aa13fa'::uuid, 1, NULL, TRUE, 0, NULL, E'Power of Artistic Expression', E'Artistic expression has been a powerful form of communication throughout history. From the Romantic movement to the present day, artists have sought to convey emotions and connect with their audience. Whether through visual art, music, or performance, artists aim to evoke a range of responses, from joy and inspiration to introspection and contemplation.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('3a6b88e0-3ef0-5cab-8f55-39cbfbc907f4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '3a6b88e0-3ef0-5cab-8f55-39cbfbc907f4'::uuid, 1, NULL, TRUE, 0, NULL, E'Innovation in Science', E'Innovation in science, as commonly perceived, is often associated {{1}} groundbreaking discoveries made by young minds, brimming with fresh ideas and boundless energy. History is {{2}} with examples of young scientists who made significant contributions at an early age. Isaac Newton was just twenty-six when he formulated the theory of gravity. Albert Einstein developed the theory of special relativity at twenty-six. Marie Curie was in her {{3}} twenties when she conducted pioneering research on radioactivity. In some fields of science, like theoretical physics, this trend towards youthful {{4}} is especially pronounced. How old was Werner Heisenberg when he formulated the uncertainty principle? Merely twenty-five. "Scientists peak young," is a {{5}} supported by many researchers in the field of scientific creativity. This pattern of early peak performance is corroborated by studies showing that the most groundbreaking scientific work often happens in the early stages of a scientist''s career.', NULL, NULL, NULL, E'1.with, 2.replete, 3.late, 4.brilliance, 5.notion', NULL, NULL),
  ('3a6c1d0d-66e3-5049-b743-cd6214934b71'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3a6c1d0d-66e3-5049-b743-cd6214934b71'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '70aa2e4f-5fee-5b86-86b8-014876313791'::uuid, NULL, E'The final two sessions will take place on Sunday morning.', NULL, NULL, NULL),
