  ('3bfff24c-796f-574c-a0bf-979843661cb2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3bfff24c-796f-574c-a0bf-979843661cb2'::uuid, 1, NULL, TRUE, 0, NULL, E'Subgenre', E'Variations kept the genre alive. From the mid 19th century onwards, when mass literacy grew, adventure became a popular subgenre of fiction. Although not exploited to its fullest, adventure has seen many changes over the years - from being constrained to stories of knights in armor to stories of high-tech espionage.', NULL, NULL, NULL, NULL, NULL, NULL),
