  ('3c8f1298-cee0-5aea-b160-d061045430f6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '3c8f1298-cee0-5aea-b160-d061045430f6'::uuid, 1, NULL, TRUE, 0, NULL, E'Traditional Cultures', E'Some people think traditional cultures should be strictly followed, while others think modern people should adopt a new way of life. What is your opinion?', NULL, NULL, NULL, NULL, 200, 300),
  ('3c8fce55-c6cf-596d-b77a-b6a8c3c37d22'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '3c8fce55-c6cf-596d-b77a-b6a8c3c37d22'::uuid, 1, NULL, TRUE, 0, NULL, E'Wildfire', E'Together, forests, shrubland, and grassland cover more than half of the land area in the United States. These ecosystems are important resources, both environmentally and {{1}} .Although wildfires occur naturally and play a long-term role in the health of these ecosystems, changing wildfire patterns threaten to {{2}} the status quo. Multiple studies have found that climate change has already led to an increase in wildfire season length, wildfire frequency, and burned area. The wildfire season has {{3}} in many areas due to factors including warmer springs, longer summer dry seasons, and drier soils and vegetation. Similarly, climate change threatens to increase the frequency, extent, and severity of fires through increased temperatures and drought. Earlier spring melting and reduced snowpack result in decreased water {{4}} during hot summer conditions, which in turn contributes to an increased wildfire risk, allowing fires to start more easily and burn hotter. These trends of longer wildfire seasons and larger wildfire size are predicted to continue as more frequent and longer droughts occur.', NULL, NULL, NULL, E'1.economically, 2.upset, 3.lengthened, 4.availability', NULL, NULL),
  ('3c9185de-685d-50b0-9431-04a5c8436b0f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '3c9185de-685d-50b0-9431-04a5c8436b0f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '35306490-9744-58da-b127-d89c40521e9f'::uuid, NULL, NULL, E'We have developed a new technique to detect errors in the manufacturing process.', NULL, NULL),
  ('3c935b43-14a9-5fd8-a7f8-72a5e1607146'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3c935b43-14a9-5fd8-a7f8-72a5e1607146'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'baf7dcc0-f97f-5361-ba77-bd59d56eb74b'::uuid, NULL, E'Time management is essential for balancing academics and extracurricular activities.', NULL, NULL, NULL),
  ('3c95488d-f766-5607-8dd2-3af5c0193fae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '3c95488d-f766-5607-8dd2-3af5c0193fae'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2b002955-ecb9-51d3-b81b-27a65a14d74c'::uuid, NULL, NULL, E'Formal conclusions could be established through rigorous experiments.', NULL, NULL),
  ('3c99bb00-d234-5d80-9cd9-05f0424fc8b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '3c99bb00-d234-5d80-9cd9-05f0424fc8b9'::uuid, 1, NULL, TRUE, 0, NULL, E'Delegation', E'The process of delegation comprises the decision to {{1}} , the briefing, and the follow-up. At each of these points, {{2}} the potential problems. When you delegate, you are not delegating the right to perform {{3}} ,you are delegating the right to make decisions. It is important to be {{4}} ,as the person to whom you delegate may have a better and faster way of completing a job than you. {{5}} responsibility for a delegated task remains with you. It is helpful to others if you can provide {{6}} feedback on their performance.', NULL, NULL, NULL, E'1.delegate, 2.anticipate, 3.an action, 4.flexible, 5.Overall, 6.constructive', NULL, NULL),
  ('3caa14a4-b44e-5072-b3c7-9d7a1b6c118d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'HIGHLIGHT_CORRECT_SUMMARY', E'HIGHLIGHT_CORRECT_SUMMARY', E'LISTENING', E'SHARED', NULL, E'APPROVED', '3caa14a4-b44e-5072-b3c7-9d7a1b6c118d'::uuid, 1, NULL, TRUE, 0, NULL, E'Laws', E'Eve all probably heard about zoning laws, but many people are confused about what they are someone like to cover them. Now, local governments, such as cities and counties, typically pass zoning laws. They regulate how people use the land in certain parts of the city or country. Think about our cITy for a moment. IT''s divided into various districts. Some are commercial while others are residential. This isn''t accidental. IT''s intentional. This city developed this way because of zoning laws. You see in the commercial district, there are businesses. And in the residential district, there are houses and departments. You can''t open a factory in the residential district, and you can''t direct an apartment building in the commercial district. You can''t do these things because of zoning laws. There were actually quite a number of zones, as I just stated. There are residential and commercial zones. There are also industrial, agricultural, and recreational zones. Industrial zones are for factories and other manufacturers. Agricultural zones are for farms, and recreational zones are for parks, lakes, and sporting facilities. So why do we need the zones? Well, think of it like this. Would you like a factory located right next to your house? How about a huge farm next to the shopping mall downtown? Or what about a big warehouse with lots of trucks next to the park? Yeah, that''s what I thought. And that''s why we have zoning laws. They keep various buildings or businesses out of places where they don''t belong.\n\nClick on the paragraph that best relates to the recording.', '1ba804a1-88b2-5e3e-8685-3df7c9ee30f4'::uuid, NULL, NULL, E'Zoning laws keep buildings in places where they should be. There are quite a number of zones, and all serve distinct purpose.', NULL, NULL),
  ('3cb106bb-0420-5c6d-b94f-1581bca24435'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '3cb106bb-0420-5c6d-b94f-1581bca24435'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c34d217e-5a0f-528d-b8bd-86c2eb9b40f1'::uuid, NULL, NULL, E'Studying abroad enhances students'' prospects in the global job market.', NULL, NULL),
