  ('3cb5774d-219b-5f31-a6a3-e96c1142498b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3cb5774d-219b-5f31-a6a3-e96c1142498b'::uuid, 1, NULL, TRUE, 0, NULL, E'Semiconductor Industry', E'The semiconductor industry has been able to improve the performance of electronic systems for more than four decades by making ever-smaller devices. However, this approach will soon encounter both scientific and technical limits, which is why the industry is exploring a number of alternative device technologies.', NULL, NULL, NULL, NULL, NULL, NULL),
