  ('3cb9a2fb-9757-576a-b021-c4087cb06ab7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '3cb9a2fb-9757-576a-b021-c4087cb06ab7'::uuid, 1, NULL, TRUE, 0, NULL, E'Reality', E'Surely, reality is what we think it is; reality is revealed to us by our experiences. To one extent or another, this view of reality is one many of us hold, if only {{1}} . I certainly find myself {{2}} this way in day-to-day life; it''s easy to be {{3}} by the face nature reveals directly to our senses. Yet, in the decades since first {{4}} Camus'' text, I''ve learned that modern science {{5}} a very different story.', NULL, NULL, NULL, E'1.implicitly, 2.thinking, 3.seduced, 4.encountering, 5.tells', NULL, NULL),
