  ('3cc4878a-7490-526b-b523-064edecae3f3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3cc4878a-7490-526b-b523-064edecae3f3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd6901cc5-632d-593f-b39a-555b4a5acf76'::uuid, NULL, E'Globalization has been a major force driving both urbanization and the growth of cities.', NULL, NULL, NULL),
  ('3cc9ec20-446c-5ca7-9ea8-46f2740310fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3cc9ec20-446c-5ca7-9ea8-46f2740310fb'::uuid, 1, NULL, TRUE, 0, NULL, E'Diverse Population', E'The world is aging and becoming increasingly urban. For the first time, there are more older persons than children under five, and more people are driven to cities for livelihoods, to have access to essential services and simply to enjoy their golden years. How can we ensure cities welcome and nurture a diverse population in ways that are equitable for all?', NULL, NULL, NULL, NULL, NULL, NULL),
