  ('3d158102-e6d2-50fc-911b-5f4ed80f1a76'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3d158102-e6d2-50fc-911b-5f4ed80f1a76'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is ''BA'' for, such as history and literature?', '3d8fcf41-8922-5a0c-8dd5-6684e7202106'::uuid, NULL, NULL, E'Bachelor of arts', NULL, NULL),
