  ('3daa68e9-33c6-5f76-b594-8f58b085583f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '3daa68e9-33c6-5f76-b594-8f58b085583f'::uuid, 1, NULL, TRUE, 0, NULL, E'Just-in-time', E'''Just-in-time'' is a management philosophy and not a technique. It originally referred to the production of goods to meet customer {{1}} exactly, in time, quality and quantity, {{2}} the ''customer'' is the final purchaser of the product or another process {{3}} along the production line. It has now come to mean producing with {{4}} waste. ''Waste'' is taken in its most general sense and includes time and resources as well as materials.', NULL, NULL, NULL, E'1.demand, 2.whether, 3.further, 4.minimum', NULL, NULL),
  ('3dabf38c-5a14-5557-92a8-e79dcecf471c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3dabf38c-5a14-5557-92a8-e79dcecf471c'::uuid, 1, NULL, TRUE, 0, NULL, E'Postponing a Deadline', E'You''re in the library working on your thesis when suddenly you receive a message from your advisor asking if you can submit a progress report by Friday. You hope to request more time since the reference materials you reserved won''t be available from the library until Thursday. What would you say to your advisor?', '48b72d44-43c4-57c2-915e-19cf45d2e9b0'::uuid, NULL, E'Dear professor, I''ve just received your email about the progress report due this Friday. I''m eager to share my work, but I''ve hit a snag - the key reference materials I need from the library won''t be available until Thursday. Could we possibly extend the deadline to next Monday? This would give me enough time to include all the necessary information and ensure the report is as detailed and accurate as possible. Thanks for considering my request.', NULL, NULL, NULL),
