  ('3db4c02f-33cf-5f87-8f95-8a895dfd9de5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3db4c02f-33cf-5f87-8f95-8a895dfd9de5'::uuid, 1, NULL, TRUE, 0, NULL, E'Word Radical', E'The word radical from the Latin word for roots means anyone who advocates fundamental change in the political system. Literally, a radical is one who proposes to attack some political or social problems by going deep into the social or economic fabric to get at the root cause and alter this basic weakness.', NULL, NULL, NULL, NULL, NULL, NULL),
