  ('3e1b9f55-891e-5bec-a44a-5e0106b069b7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '3e1b9f55-891e-5bec-a44a-5e0106b069b7'::uuid, 1, NULL, TRUE, 0, NULL, E'Early Empathy', E'A group of psychologists in Melbourne focused on the development of empathy in early childhood as a crucial aspect of socialization. They {{1}} a study, involving 120 pairs of parents and their children, and observed varied forms of empathetic responses in children, closely {{2}} to parental interaction styles. A particular form of response, termed ''engaged empathy,'' was {{3}} when children showed genuine concern and understanding of others'' emotions, often {{4}} their parents'' empathetic behavior.', NULL, NULL, NULL, E'1.conducted, 2.linked, 3.noted, 4.mirroring', NULL, NULL),
  ('3e1c74b5-66d4-5ab7-afa3-821adc0dc0b7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3e1c74b5-66d4-5ab7-afa3-821adc0dc0b7'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'cac2b1fa-cf98-5c00-8062-0736234f84bd'::uuid, NULL, E'The library is located on the north side of the campus.', NULL, NULL, NULL),
