  ('3e243e9d-5b90-5868-aac7-5acaac7a9a19'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '3e243e9d-5b90-5868-aac7-5acaac7a9a19'::uuid, 1, NULL, TRUE, 0, NULL, E'Apartment Renting', E'My name is Tonia. My roommate and I are looking for a nice apartment near my college’s campus. We are very quiet and study a lot. I study history, and my roommate studies French. We are very interested {{1}} renting your apartment. We can {{2}} the rent on time because we do a part-time work, too. Some of our friends live in the same building and have recommended your place to us. They mentioned that you are a kind and responsible landlord, and we hope to {{3}} the same positive experience.\nI would {{4}} an appointment to view the apartment in person. {{5}} application form is ready, and we are prepared to proceed with the process quickly.\nWe look forward to hearing from you soon.\nBest regards, Tonia', NULL, NULL, NULL, E'1.in, 2.pay, 3.have, 4.like to make, 5.Our', NULL, NULL),
  ('3e2bd105-9830-5245-a09c-8089a54302c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3e2bd105-9830-5245-a09c-8089a54302c6'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Where do ships load and unload goods or find shelter from storms?', '73466f49-1e91-563e-af27-6357b366cef9'::uuid, NULL, NULL, E'Port / harbor', NULL, NULL),
