  ('3e627164-54b8-5ae0-850b-3f876ab71065'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3e627164-54b8-5ae0-850b-3f876ab71065'::uuid, 1, NULL, TRUE, 0, NULL, E'STEM Education', E'STEM education is essential for preparing students for the technological and scientific challenges of the future. It provides students with the skills and knowledge needed to pursue careers in science, technology, engineering, and mathematics. STEM education also promotes critical thinking and problem-solving skills.', NULL, NULL, NULL, NULL, NULL, NULL),
