  ('3edbbd89-40b7-5457-8617-2f68c85e60ab'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3edbbd89-40b7-5457-8617-2f68c85e60ab'::uuid, 1, NULL, TRUE, 0, NULL, E'Largest Moon', E'Previous research has offered circumstantial evidence that Ganymede, the largest moon in the solar system, contains more water than all of Earth''s oceans put together. However, temperatures there are so cold that the water on the surface is frozen solid. Also, Ganymede’s ocean is thought to be 100 miles below the moon’s crust. This means that the water vapor discovered by Hubble is not likely to represent the evaporation of this ocean.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('3ee4dbc5-1b31-5534-8abe-477b69bfa56e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '3ee4dbc5-1b31-5534-8abe-477b69bfa56e'::uuid, 1, NULL, TRUE, 0, NULL, E'Glacier National Park', E'Snow pack, sea ice, and glaciers are melting around the world. One of the most {{1}} effects of climate change is the {{2}} disappearance of glaciers. Scientists from Glacier National Park in Montana, U.S., have documented the steady {{3}} of the park’s iconic glaciers with photographs. Glaciers around the world are melting faster than snow and ice can {{4}} them.', NULL, NULL, NULL, E'1.visible, 2.rapid, 3.decline, 4.replenish', NULL, NULL),
