  ('3f0d21da-eced-5385-b56f-88929468278c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '3f0d21da-eced-5385-b56f-88929468278c'::uuid, 1, NULL, TRUE, 0, NULL, E'Available Food', E'The {{1}} of readily available food has diminished the art of cooking. In the past, cooking was a communal and creative process, {{2}} families together and ensuring nutritious meals. Today''s fast-paced lifestyle has led to a {{3}} on quick, often less nutritious food options, {{4}} family bonding time and the enjoyment of cooking.', NULL, NULL, NULL, E'1.convenience, 2.bringing, 3.reliance, 4.reducing', NULL, NULL),
  ('3f14ded8-8cc7-553e-9116-f4523f9b2514'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '3f14ded8-8cc7-553e-9116-f4523f9b2514'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8d85450a-9ddf-5a72-90aa-f0933a9a2fa2'::uuid, NULL, NULL, E'The young teacher was obviously nervous when giving his first lesson.', NULL, NULL),
  ('3f19cd99-2927-5917-a0ff-0b7092771cda'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3f19cd99-2927-5917-a0ff-0b7092771cda'::uuid, 1, NULL, TRUE, 0, NULL, E'Walking Tour', E'The information session is a 45-minute presentation conducted by an admission representative. Immediately following the session is a 90-minute walking tour of the campus led by a student ambassador. Walking tours of the campus generally include classroom buildings, a residence hall room, a dining hall, the library, athletic facilities, performing art facilities, and the student union.', NULL, NULL, NULL, NULL, NULL, NULL),
