  ('3f1c2328-b104-50d5-8b8e-fa1d7e1ad39a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3f1c2328-b104-50d5-8b8e-fa1d7e1ad39a'::uuid, 1, NULL, TRUE, 0, NULL, E'Tortoise', E'The tortoise size and shell shape varies depending on where they live. The shell is made of bone and is a dull brown color. Their ribs, backbone and breastbone have become part of the shell, which is why you can never separate the tortoise from its shell.', NULL, NULL, NULL, NULL, NULL, NULL),
