  ('3f24ad1f-5c0e-564c-840c-5394ec5a663d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '3f24ad1f-5c0e-564c-840c-5394ec5a663d'::uuid, 1, NULL, TRUE, 0, NULL, E'Egg-eating Snakes', E'Egg-eating snakes are a small group of snakes whose {{1}} consists only of eggs. Some eat only small eggs, which they have to swallow {{2}} , as the snake has no teeth. Instead, some other snakes eat bigger eggs, but it requires special {{3}} . These snakes have spines that stick {{4}} from the backbone. The spines crack the egg {{5}} as it passes through the throat.', NULL, NULL, NULL, E'1.diet, 2.whole, 3.treatment, 4.out, 5.open', NULL, NULL),
