  ('3f3a9387-5e46-5cc3-83c3-44e647be7833'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '3f3a9387-5e46-5cc3-83c3-44e647be7833'::uuid, 1, NULL, TRUE, 0, NULL, E'Poetry', E'Throughout history poetry has often been created to celebrate a wedding. This article will examine the ways in {{1}} this has happened at different periods of time and in many widely differing societies. It will look at some examples of wedding poems from a {{2}} of eras and cultures, and will set them in their specific context, drawing out the particular features that {{3}} that context. Other writers on this topic have tended to focus on more personal wedding poems, {{4}} dedicated to the bride or the groom. Here, however, the intention is to consider poems that were written with more of a social purpose in mind.', NULL, NULL, NULL, E'1.which, 2.range, 3.reflect, 4.those', NULL, NULL),
  ('3f3bed25-6da9-589c-a803-cc8c5564a4bf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3f3bed25-6da9-589c-a803-cc8c5564a4bf'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '40952437-1d6f-508e-993f-ea3ca5d42098'::uuid, NULL, E'When we look at the effects of corporate crime we may find it''s very difficult to assess the costs.', NULL, NULL, NULL),
