  ('3f4b01cf-4b4f-5607-801c-5df5f14fb7d2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3f4b01cf-4b4f-5607-801c-5df5f14fb7d2'::uuid, 1, NULL, TRUE, 0, NULL, E'Lunar Eclipse', E'For a lunar eclipse to occur, the Sun, Earth, and Moon must be roughly aligned in a line. Otherwise, the Earth cannot cast a shadow on the Moon''s surface and an eclipse cannot take place. When the three bodies are aligned in a way that the Moon is partly covered by the Earth''s umbra, a partial lunar eclipse is the result.', NULL, NULL, NULL, NULL, NULL, NULL),
