  ('3fd5a65b-052a-5c27-8656-aefb944fcee8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '3fd5a65b-052a-5c27-8656-aefb944fcee8'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '165dbaba-f87c-511a-b7c7-220610200bc2'::uuid, NULL, NULL, E'All new medical school students must attend the talk about optional courses.', NULL, NULL),
  ('3fe12d9a-2676-5d15-8961-8dd3535d5675'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '3fe12d9a-2676-5d15-8961-8dd3535d5675'::uuid, 1, NULL, TRUE, 0, NULL, E'Akimbo', E'Akimbo, this must be one of the odder-looking words in the language and puzzles us in part because it doesn''t seem to have any relatives. What''s more, it is now virtually a fossil word, until recently almost invariably found in arms akimbo, a posture in which a person stands with hands on hips and elbows sharply bent outward, one signaling impatience, hostility, or contempt.', NULL, NULL, NULL, NULL, NULL, NULL),
