  ('400f7f65-6862-5edf-9ee6-4a35d194cd73'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '400f7f65-6862-5edf-9ee6-4a35d194cd73'::uuid, 1, NULL, TRUE, 0, NULL, E'Nature of Reality', E'In attempts to understand the very nature of our reality, physicists sure have some mind-bending theories. Like what if information is a tangible and fundamental aspect of physical reality itself – alongside matter and energy? Or, alternatively, what if information is the fifth state of matter?', NULL, NULL, NULL, NULL, NULL, NULL),
