  ('411146cf-0c74-53cc-b5ec-0d0bd0d58a76'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '411146cf-0c74-53cc-b5ec-0d0bd0d58a76'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2fa4b980-aaea-5b68-bebf-e534ed583645'::uuid, NULL, E'Please click the logo above to enter the site.', NULL, NULL, NULL),
  ('411164a3-be73-58fc-8591-97d7a8ff6ef9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '411164a3-be73-58fc-8591-97d7a8ff6ef9'::uuid, 1, NULL, TRUE, 0, NULL, E'Visual Description', NULL, 'caf486f4-8fb8-569d-9f0a-f0166746f88d'::uuid, NULL, E'The comics I show you with lots of people chatting around in a room is a form of description. We use different kinds of methods to describe a situation.\nSometimes we have to use visual description, particularly when we do not witness the scenario. I was born during the Second World War and my hometown is X, for example when I asked my mother about the war, I always ask her you have mentioned this or that when you talked to me when asked her about the shelter, I asked her what the shelter looks like and when did you go to the shelter. From her response I could get more visual evidence as I can to write my book.', NULL, NULL, NULL),
  ('4111ae5f-28aa-5d0a-9175-7b5b64cfddab'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4111ae5f-28aa-5d0a-9175-7b5b64cfddab'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b5435209-806d-5f94-a571-82efeff51b00'::uuid, NULL, NULL, E'Several fields are now under water after the heavy rain.', NULL, NULL),
