  ('4161b301-cb0a-5686-a0b6-38e8fa836051'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '4161b301-cb0a-5686-a0b6-38e8fa836051'::uuid, 1, NULL, TRUE, 0, NULL, E'Cheating', E'Although not written about extensively, a few individuals have considered the concept and act of cheating in {{1}} as well as contemporary culture. J. Barton Bowyer writes that cheating ''is the advantageous distortion of perceived reality. The advantage falls to the cheater because the cheated person {{2}} what is assumed to be the real world''. The cheater is taking advantage of a person, a situation, or {{3}} . Cheating also involves ''distortion of perceived reality'' or what others call ''deception''. Deception can involve hiding the ''true'' reality or ''showing'' reality in a way intended to deceive others.', NULL, NULL, NULL, E'1.history, 2.misperceives, 3.both', NULL, NULL),
  ('4164de73-1e26-528b-ad88-1bf239979664'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4164de73-1e26-528b-ad88-1bf239979664'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f0ff0252-7968-5b3f-b0f6-7762a5ec7a18'::uuid, NULL, NULL, E'Bad policy decisions led to the financial crisis.', NULL, NULL),
  ('41697151-7af8-5e5e-a82d-3b321685f6d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '41697151-7af8-5e5e-a82d-3b321685f6d3'::uuid, 1, NULL, TRUE, 0, NULL, E'Siblings', E'No two siblings are the same, not even {{1}} twins. Parents often {{2}} about why their children are so different from one another. They'' ll say, I {{3}} them up all the same. They forget that what {{4}} our behaviour isn''t what happens to us but how we {{5}} what happens to us, and no two people ever see anything in exactly the same way.', NULL, NULL, NULL, E'1.identical, 2.puzzle, 3.brought, 4.determines, 5.interpret', NULL, NULL),
