  ('4173beae-5197-5c53-bd07-760e3a8e9a6f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '4173beae-5197-5c53-bd07-760e3a8e9a6f'::uuid, 1, NULL, TRUE, 0, NULL, E'DNA Myth', E'DNA is more important to a child’s personality, exam results and future income than the way they are brought up. Environment is undoubtedly a key {{1}} on almost every {{2}} of our lives, but it’s been argued that genetics plays a more important and measurable role, even to the extent that our parenting and {{3}} don’t matter that much.', NULL, NULL, NULL, E'1.influence, 2.aspect, 3.schooling', NULL, NULL),
