  ('423cef3d-ca37-51f5-9df4-412f7bf9b955'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '423cef3d-ca37-51f5-9df4-412f7bf9b955'::uuid, 1, NULL, TRUE, 0, NULL, E'Unlucky Numbers', E'While in the West, Friday the 13th might give some people pause, other cultures have their own numerological apprehensions. Take the number 4 in East Asia, often {{1}} with death due to its pronunciation {{2}} similar to the word for "die" in several languages. Buildings frequently skip the fourth floor, much like the 13th in the West. Then there''s Italy, where 17 is the unlucky number, based on its Roman numeral representation, XVII, which can be rearranged to spell ''VIXI'', translated as "I have lived," an implication of death. These superstitions, while {{3}} arbitrary, hold a fascinating glimpse into cultural psychologies and histories. They influence architecture, business, and daily life in subtle but pervasive ways. It''s a curious aspect of human {{4}} how numbers can carry such weight in our collective imaginations.', NULL, NULL, NULL, E'1.associated, 2.sounding, 3.seemingly, 4.nature', NULL, NULL),
  ('42418a4c-7a75-5418-9f11-0a32532c07a7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '42418a4c-7a75-5418-9f11-0a32532c07a7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9f47c464-963e-5466-b930-03d6a2ad86bb'::uuid, NULL, NULL, E'We support to do research in the field of archaeology such as forecasting and estimation.', NULL, NULL),
