  ('425f74d2-1097-5e16-8d4c-de37adb97788'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '425f74d2-1097-5e16-8d4c-de37adb97788'::uuid, 1, NULL, TRUE, 0, NULL, E'Digital Data', E'A team of researchers has developed a custom-built ''data-to-music'' algorithm that can transform digital data into sound, making it easier to comprehend and analyze. The use of sound to represent data has the potential to revolutionize the way we interpret and understand complex information, particularly in fields such as science, medicine, and engineering.', NULL, NULL, NULL, NULL, NULL, NULL),
