  ('42a469e4-240d-59ea-820b-fabfee57b234'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '42a469e4-240d-59ea-820b-fabfee57b234'::uuid, 1, NULL, TRUE, 0, NULL, E'Migration', E'Migration could be described as the well-defined journey animals make to a familiar {{1}} at specific seasons or times of the year. All species that migrate do so for a common {{2}} , in order to survive. Migration allows them to spend their life in more than one area and thus {{3}} problems that can occur in one habitat, such as lack of food, shelter or exposure to harsh weather.', NULL, NULL, NULL, E'1.destination, 2.purpose, 3.avoid', NULL, NULL),
  ('42a745a4-8922-5648-9ee4-c27b8f2b6465'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '42a745a4-8922-5648-9ee4-c27b8f2b6465'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '90998a5f-eee4-58c5-bb23-489f20f916c4'::uuid, NULL, NULL, E'Different factors affect the freezing time of water.', NULL, NULL),
  ('42a7f7a9-adc0-50fe-ad43-e259a58b5ade'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '42a7f7a9-adc0-50fe-ad43-e259a58b5ade'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'dd873026-3a82-5cb1-b326-0b1f2bf2e7d9'::uuid, NULL, NULL, E'Democracy is constantly offering a stable form of government.', NULL, NULL),
  ('42ac140f-c255-5121-bb36-d583edb0f962'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '42ac140f-c255-5121-bb36-d583edb0f962'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a2a975c7-f633-5f43-a884-e06591c5da5f'::uuid, NULL, E'A thorough bibliography is needed at the end of every assignment.', NULL, NULL, NULL),
  ('42af73de-68e1-528a-9612-91021cab2a53'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '42af73de-68e1-528a-9612-91021cab2a53'::uuid, 1, NULL, TRUE, 0, NULL, E'Tiger Sharks', E'The tiger shark is named for the dark, vertical stripes on either side of its body, which are reminiscent of a tiger''s {{1}} . These stripes actually {{2}} as the tiger shark ages, so they can''t be used as an identifying {{3}} of every individual. Young tiger sharks have dark blotches or spots, which eventually {{4}} into stripes. For this reason, the species is sometimes known as the leopard shark or the spotted shark.', NULL, NULL, NULL, E'1.markings, 2.fade, 3.feature, 4.merge', NULL, NULL),
  ('42b6ff7a-11c3-55a0-994f-32537673429c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '42b6ff7a-11c3-55a0-994f-32537673429c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b3b519e0-1e06-5ec4-8873-d6fce2993c7f'::uuid, NULL, E'All lecture handouts are downloadable on the university website.', NULL, NULL, NULL),
  ('42b92351-b52a-51f3-808c-b44324f987c1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '42b92351-b52a-51f3-808c-b44324f987c1'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8fd1e96e-eb38-5911-8ffa-a78009100c22'::uuid, NULL, E'Newspapers across the world are reporting stories of presidents.', NULL, NULL, NULL),
  ('42c01a76-1b87-5094-af1f-e53ef118ada3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '42c01a76-1b87-5094-af1f-e53ef118ada3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '676750c9-479c-5970-8a99-0b5a3f7ad961'::uuid, NULL, E'Readers have been invited to write in with their comments.', NULL, NULL, NULL),
  ('42c3db8e-36d4-5aff-98f1-17009a1275cb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '42c3db8e-36d4-5aff-98f1-17009a1275cb'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8ca75d57-d700-5639-81e4-dfbb748471d2'::uuid, NULL, E'We can meet in my office after the lecture.', NULL, NULL, NULL),
  ('42c8bdc5-9846-5f5d-9268-0ed327e96535'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '42c8bdc5-9846-5f5d-9268-0ed327e96535'::uuid, 1, NULL, TRUE, 0, NULL, E'Light Energy', E'Light is usually described as a form of energy and it is indeed a kind of electromagnetic energy, not much different from radio waves, television signals, heat, and X-rays. All of these are made up of waves that {{1}} , bend, interfere with one another, and react with obstacles in their path, rather like waves in water. A physicist might tell you that light, along with all its electromagnetic relatives, is really a form of matter, little different from more {{2}} matter such as houses and, like them, it is made up of individual particles. Light particles, called photons, travel in streams, similar to the way in which water pours through a hose. To most people, this might sound paradoxical or illogical, as many things to do with physics seem to these days. How can light be both energy and matter, wave and particle? The reason it can be is, in fact, not at all {{3}} : all energy is a form of matter. Almost everybody recognizes — even if they do not understand — Einstein’s famous equation, E =mc2, which spells it out: E refers to energy and m to the mass of matter. Furthermore, all matter has some of the characteristics of waves and some of the particles, but the waves of such solid-seeming things as houses are not {{4}} and can generally be ignored because ordinary matter acts as if it were made up of particles.', NULL, NULL, NULL, E'1.spread, 2.substantial, 3.complicated, 4.discernible', NULL, NULL),
  ('42ca23e2-fe28-5b7a-8836-381519496bdc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '42ca23e2-fe28-5b7a-8836-381519496bdc'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9e0143f8-4b8f-5ce7-ab72-b2d094dab1d6'::uuid, NULL, NULL, E'Banks make money by charging interest when they lend it out.', NULL, NULL),
