  ('42cd233d-e196-5f9a-873b-236ef7c1d10b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '42cd233d-e196-5f9a-873b-236ef7c1d10b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9c061553-b06c-5167-92f3-8f4c67dc2ca2'::uuid, NULL, E'Those reference books are too old, while the others are OK.', NULL, NULL, NULL),
  ('42cdc17d-5631-5d0d-84a0-d20c8acf7493'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '42cdc17d-5631-5d0d-84a0-d20c8acf7493'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the selling and transporting of goods to another country?', 'f231e36b-358c-5687-9207-eaa07b219952'::uuid, NULL, NULL, E'Export / exportation', NULL, NULL),
  ('42d0105f-3fc7-5f06-afda-d158f4566534'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '42d0105f-3fc7-5f06-afda-d158f4566534'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '225d5b82-8070-52b6-bc61-d4c80c658e15'::uuid, NULL, NULL, E'There are many different things you can study in cultural classes.', NULL, NULL),
  ('42d04688-ffe3-51fc-8b68-1c935e315c9e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '42d04688-ffe3-51fc-8b68-1c935e315c9e'::uuid, 1, NULL, TRUE, 0, NULL, E'Hybrid Rice', E'A new breed of rice that is a hybrid of an annual Asian rice and a perennial African rice could be a more sustainable option. The hybrid rice was able to produce grain for 8 consecutive harvests over four years at a yield comparable to the standard annual Asian rice, with much lower costs and labor.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('42d0eab3-a16f-5cbd-bf43-c3fc03437405'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '42d0eab3-a16f-5cbd-bf43-c3fc03437405'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6b801f42-6c1e-5313-ab75-cf7152f477e8'::uuid, NULL, E'The professor plans to discuss issues in the news that reflect concepts taught in class.', NULL, NULL, NULL),
  ('42d10b47-0460-57cc-b2cc-a981fd36c699'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '42d10b47-0460-57cc-b2cc-a981fd36c699'::uuid, 1, NULL, TRUE, 0, NULL, E'Interdisciplinarity', E'Interdisciplinarity refers to a method that merges traditional educational concepts in order to arrive at new approaches. It is an increasingly important concept within both academic research and the private sector. More than just pasting together different subjects, interdisciplinary work is the process of developing an integration of methods that are traditionally thought of as separate fields.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('42d40ffa-908b-5b27-b78b-ffb4a96b9ce5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '42d40ffa-908b-5b27-b78b-ffb4a96b9ce5'::uuid, 1, NULL, TRUE, 0, NULL, E'Ginger', E'The pungent and flavorful taste of ginger makes it a popular ingredient in many cuisines. It is also known for its medicinal properties, such as aiding digestion and reducing inflammation. However, the cultivation of ginger is a labor-intensive process that requires careful attention to soil quality, temperature, and humidity. Despite these challenges, ginger remains a highly sought-after spice around the world.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('42e2c8b3-f681-5562-9beb-6ad6b71e7660'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '42e2c8b3-f681-5562-9beb-6ad6b71e7660'::uuid, 1, NULL, TRUE, 0, NULL, E'Ewaste Recycling', NULL, '81c1f9f3-5f07-5d1b-aa90-5a66e1c5cf1b'::uuid, NULL, E'If you have an old phone, you might want to consider your options before throwing it away. To minimize waste, you could donate it to a charity for reuse, take it to an e-waste recycling facility, or look for a company that refurbishes old models. However, even recycling companies need our scrutiny. Just as the production of smartphones comes with social and environmental problems, dismantling them does too. E-waste is sometimes intentionally exported to countries where labor is cheap but working conditions are poor. Vast workforces, often made up of women and children, may be underpaid, lack the training to safely disassemble phones, and be exposed to elements like lead and mercury, which can permanently damage their nervous systems. Phone waste can also end up in huge dump sites, leaching toxic chemicals into the soil and water, mirroring the problems of the mines where the elements originated. A phone is much more than it appears to be on the surface. It’s an assemblage of elements from multiple countries, linked to impacts that are unfolding on a global scale. So, until someone invents a completely sustainable smartphone, we’ll need to come to terms with how this technology affects widespread places and people.', NULL, NULL, NULL),
  ('42e55b5f-817d-5072-850b-15e70c3e4c7c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '42e55b5f-817d-5072-850b-15e70c3e4c7c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4393fea2-1974-5d3a-b521-76b628f9831e'::uuid, NULL, E'I really didn''t like the movie even though the acting was good.', NULL, NULL, NULL),
  ('42e66afe-0125-5d9c-b86e-3a10cd05264f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '42e66afe-0125-5d9c-b86e-3a10cd05264f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0df3ed97-9135-5743-86e9-4aafc8ff4f41'::uuid, NULL, E'We have specially assigned staff to help you find appropriate work placements.', NULL, NULL, NULL),
  ('42e6e831-a605-5e72-9ef9-346b420ec6ff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '42e6e831-a605-5e72-9ef9-346b420ec6ff'::uuid, 1, NULL, TRUE, 0, NULL, E'3D Printing Method', E'Scientists have used 3D printing technology to create a specialized brain tissue that mimics the cerebral cortex. By utilizing human stem cells, they were able to implant these engineered structures into mouse brain slices, where they seamlessly integrated with the existing tissue. This groundbreaking technique shows promise for future applications in treating brain injuries.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('42ea63b9-9c07-5e4f-b3bc-0421a168ed3e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '42ea63b9-9c07-5e4f-b3bc-0421a168ed3e'::uuid, 1, NULL, TRUE, 0, NULL, E'Hummingbird', E'Most birds can bend their wings at the wrist, pulling arched wings close to their bodies to navigate their way through dense vegetation like branches. But hummingbird wings aren’t as flexible. Because the wings stick straight out from a hummingbird’s body, getting through tight spaces requires some tricky maneuvering.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('42ec7852-dd7a-5aff-a71d-5b9cd1d25dd0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '42ec7852-dd7a-5aff-a71d-5b9cd1d25dd0'::uuid, 1, NULL, TRUE, 0, NULL, E'Paleontological Momentum', E'By this time, however, paleontological momentum had moved to England. In 1812, at Lyme Regis on the Dorset coast, an extraordinary child named Mary Anning — aged 11, 12 or 13, depending on whose account you read — found a strange fossilized sea monster, 17 feet long and now known as the ichthyosaurus, embedded in the steep and dangerous cliffs along the English Channel.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('42eca311-869b-507b-bc55-ca2736213662'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '42eca311-869b-507b-bc55-ca2736213662'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b0b1dc90-a1e7-55ec-8578-531ac0f96433'::uuid, NULL, E'He had to spend about six months in a class with younger students.', NULL, NULL, NULL),
  ('42fae94f-7fbc-58ee-81d9-ec888d59441e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', '42fae94f-7fbc-58ee-81d9-ec888d59441e'::uuid, 1, NULL, TRUE, 0, NULL, E'MCM-R', E'The Cognitive Approach. Cognitive psychologists assert that our behavior is influenced by our values, by the ways in which we interpret our situations and by choice. For example, people who believe that aggression is necessary and justified-as during wartime-are likely to act aggressively, whereas people who believe that a particular war or act of aggression is unjust, or who think that aggression is never justified, are less likely to behave aggressively. One cognitive theory suggests that aggravating and painful events trigger unpleasant feelings. These feelings, in turn, can lead to aggressive action, but not automatically. Cognitive factors intervene. People decide whether they will act aggressively or not on the basis of factors such as their experiences with aggression and their interpretation of other people''s motives. Supporting evidence comes from research showing that aggressive people often distort other people''s motives. For example, they assume that other people mean them harm when they do not.\n\nAccording to the cognitive approach described in the paragraphs, which of the following options may influence the decision whether to act aggressively?', NULL, NULL, NULL, E'previous experiences with aggression\nbeliefs about other people''s intentions', NULL, NULL),
  ('42fd5600-9202-51ef-9ac9-5502d07a41c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '42fd5600-9202-51ef-9ac9-5502d07a41c5'::uuid, 1, NULL, TRUE, 0, NULL, E'Bill', E'The bill calls for the establishment of the National Landslide Hazards Reduction Program within one year of becoming law. The program serves numerous functions, including to identify and understand landslide hazards and risks, reduce losses from landslides, protect communities at risk of landslides hazards, and improve communication and emergency preparedness.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('42ffabc8-6928-5baa-9083-43455b759061'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '42ffabc8-6928-5baa-9083-43455b759061'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '31cc66ae-7291-5c97-a6c5-d865d9a4fe3f'::uuid, NULL, NULL, E'Physiology is the study of how living things work.', NULL, NULL),
  ('43024000-4c8c-566d-a9aa-439015a28348'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '43024000-4c8c-566d-a9aa-439015a28348'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '25e4c2db-6a9f-5b53-9aaf-1d6cf31e7b3a'::uuid, NULL, NULL, E'Major sports on campus include rugby, soccer and tennis.', NULL, NULL),
  ('43056cdd-ec70-5a51-b1f0-9a1f3bcfa0e2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '43056cdd-ec70-5a51-b1f0-9a1f3bcfa0e2'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the study of human society, culture, and behavior?', 'f75a6479-71c3-5d63-97b6-6d9906677aa9'::uuid, NULL, NULL, E'Sociology', NULL, NULL),
  ('430bbf1c-ab6c-5c4d-a13e-d919786ea4c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '430bbf1c-ab6c-5c4d-a13e-d919786ea4c8'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ecb16e2e-e1ec-54c3-b9cb-02e2392e41c5'::uuid, NULL, NULL, E'I recommend that you should get some professional advice.', NULL, NULL),
  ('430c60b9-fdc2-510f-9d20-4f477e7e5d54'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '430c60b9-fdc2-510f-9d20-4f477e7e5d54'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f2275d93-3b89-54e3-bc0e-c67db2d1900b'::uuid, NULL, NULL, E'We''re still waiting for our exam results to come through.', NULL, NULL),
  ('4312ae2e-3111-5acb-bbb3-238f1fb9800b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '4312ae2e-3111-5acb-bbb3-238f1fb9800b'::uuid, 1, NULL, TRUE, 0, NULL, E'Country Definition', E'What is a country, and how is a country defined? When people ask how many countries there are in the world, they expect a simple answer. After {{1}} , we''ve explored the whole planet, we have international travel, satellite navigation and plenty of global organizations like the United Nations, so we {{2}} really know how many countries there are! However, the answer to the question varies according to whom you ask. Most people say there are 192 countries, but others point out that there could be more like 260 of them. So why isn''t there a straightforward answer? The problem {{3}} because there isn''t a universally agreed definition of ''country'' and because, for political reasons, some countries {{4}} it convenient to recognize or not recognize {{5}} countries.', NULL, NULL, NULL, E'1.all, 2.should, 3.arises, 4.find, 5.other', NULL, NULL),
  ('43183721-d9af-5004-aa64-8470ee8ab345'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '43183721-d9af-5004-aa64-8470ee8ab345'::uuid, 1, NULL, TRUE, 0, NULL, E'Circular Time', E'Each of us is born into and raised in a particular "time world" — an environment with its own rhythm to which we entrain ourselves. Certain cultures have related to time as a cyclical {{1}} , in which there is no pressure or future anxiety. The whole of existence goes around: the cycle of the {{2}} , of planting and harvesting, the daily return of the sun, of birth and death. In circular time there is no pressing {{3}} to achieve and create newness, or to insatiably produce more than is needed to simply survive. Additionally, there is no fear of death. Such societies have successfully integrated the past and future into a peaceful sense of the {{4}} . They also honored the wisdom of elders who held the knowledge of the past — upon which the future was clearly linked.', NULL, NULL, NULL, E'1.phenomenon, 2.seasons, 3.need, 4.present', NULL, NULL),
  ('43196f5f-e2d9-5c1f-b07d-9fdd17156e9b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '43196f5f-e2d9-5c1f-b07d-9fdd17156e9b'::uuid, 1, NULL, TRUE, 0, NULL, E'Gravitational Waves', E'The recent discovery of gravitational waves was a monumental {{1}} , born from the hypothesis that massive cosmic events would create ripples in space-time. Teams of astrophysicists, armed with advanced {{2}} like the LIGO observatory, {{3}} out to capture these elusive waves. After years of fine-tuning their instruments and combing through data, they finally {{4}} the jackpot, confirming a key prediction of Einstein''s theory of relativity and opening up new avenues for understanding the universe.', NULL, NULL, NULL, E'1.achievement, 2.equipment, 3.set, 4.hit', NULL, NULL),
  ('431feaa7-e900-50f4-a05d-7ca069272263'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '431feaa7-e900-50f4-a05d-7ca069272263'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '17a2bc9d-aaa9-5063-9a2f-f6d3927318ae'::uuid, NULL, E'You will get the money report for the last few months later today.', NULL, NULL, NULL),
  ('432439ab-8886-5e55-b02b-f0dd0995a4e4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '432439ab-8886-5e55-b02b-f0dd0995a4e4'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6e239d2e-2e31-5f28-8028-ba5f9379706c'::uuid, NULL, E'Our future prosperity depends on economic growth to some extent.', NULL, NULL, NULL),
  ('432a8d47-c48c-5d35-bff1-22803bdc3006'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '432a8d47-c48c-5d35-bff1-22803bdc3006'::uuid, 1, NULL, TRUE, 0, NULL, E'Wrinkle Cure', E'Barrie Finning''s, a professor at Monash University''s college of pharmacy in Melbourne, and PhD student Anita Schneider, recently tested a new wrinkle cure. Twice daily, 20 male and female volunteers applied a liquid containing Myoxinol, a patented {{1}} of okra (Hibiscusesculentus) seed, to one side of their faces. On the other side they applied a similar liquid without Myoxinol. Every week for a month their wrinkles were tested by self-assessment, photography and the size of depressions made in silicon moulds. The results were impressive. After a month the {{2}} and number of wrinkles on the Myoxinol-treated side were reduced by approximately 27 per cent. But Finnin''s research, commissioned by a cosmetics company, is unlikely to be published in a scientific {{3}} . It''s hard to even find studies that show the active ingredients in cosmetics penetrate the skin, let alone more {{4}} research on their effects. Even when {{5}} studies are commissioned, companies usually control whether the work is published in the traditional scientific literature.', NULL, NULL, NULL, E'1.extract, 2.depth, 3.publication, 4.comprehensive, 5.rigorous', NULL, NULL),
  ('43341dcd-3245-5ab6-9410-6becb5789023'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '43341dcd-3245-5ab6-9410-6becb5789023'::uuid, 1, NULL, TRUE, 0, NULL, E'Frogs', E'Frogs have excellent night vision and are very sensitive to movement. The bulging eyes of most frogs allow them to see in front, to the sides, and partially behind them. When a frog swallows food, it pulls its eyes down into the roof of its mouth, to help push the food down its throat.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('43406372-a322-56ee-be25-b6f7e9f8f2ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '43406372-a322-56ee-be25-b6f7e9f8f2ee'::uuid, 1, NULL, TRUE, 0, NULL, E'Habitat Preservation', E'What is your opinion on the importance of preserving natural habitats?', NULL, NULL, E'Preserving natural habitats is a critical necessity for the health of our planet and the prosperity of future generations. It is imperative to understand the importance of protecting these habitats to maintain biodiversity, safeguard endangered species, and ensure a healthy environment for all.\nProtecting natural habitats is essential for maintaining biodiversity and ecosystem balance. These habitats serve as homes to a diverse range of plant and animal species, forming intricate ecosystems where each organism plays a vital role in the functioning of the environment. By preserving these habitats, we safeguard the delicate balance of nature and ensure the survival of various species for generations to come.\nFurthermore, the preservation of habitats is crucial for safeguarding endangered species and their habitats. Many species face threats due to habitat destruction, fragmentation, and climate change. By conserving natural habitats, we provide a safe haven for endangered species to thrive and prevent their extinction, contributing to the overall health and resilience of ecosystems.\nIn conclusion, the conservation of natural habitats is not only about protecting wildlife; it is about ensuring clean air, water, and a healthy environment for all living beings. By prioritizing the preservation of natural habitats, we uphold biodiversity, protect endangered species, and maintain a sustainable environment that benefits both present and future generations.', NULL, 200, 300),
  ('4341c4a8-88c7-5a80-bf7e-3634c7f3d395'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4341c4a8-88c7-5a80-bf7e-3634c7f3d395'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9ec7d61a-0ef1-5ce1-a751-89ef2ebced04'::uuid, NULL, E'I really don''t think so. Scientists should be free to do what they like.', NULL, NULL, NULL),
  ('4342ca45-012d-52ea-96e2-2e799c76ec9d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '4342ca45-012d-52ea-96e2-2e799c76ec9d'::uuid, 1, NULL, TRUE, 0, NULL, E'Wool Market', E'The wool market was extremely important to the English medieval economy and wool {{1}} the English export trade from the late-thirteenth century to its {{2}} in the late-fifteenth century. Wool was at the forefront of the establishment of England as a European {{3}} and economic power and this volume was the first study of the medieval wool market in over 20 years. It investigates in detail the scale and scope of advance {{4}} for the sale of wool; the majority of these agreements were formed between English monasteries and Italian merchants, and the book focuses on the data contained within them.', NULL, NULL, NULL, E'1.dominated, 2.decline, 3.political, 4.contracts', NULL, NULL),
  ('4342f096-ef6f-59aa-9664-ece17a2b5a22'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4342f096-ef6f-59aa-9664-ece17a2b5a22'::uuid, 1, NULL, TRUE, 0, NULL, E'True Sociability', NULL, 'b5bdc48e-ad7a-5979-aa4f-066ce94127da'::uuid, NULL, E'Parties have become synonymous with sociability because of certain underlying ideas about what true social connection might require and entail. We assume that sociability naturally springs up when lots of people are put together in a room, that it means speaking a lot and notably cheerfully about things that have been happening in our lives, that it depends on a jokey manner and ideally on the possession of a few entertaining anecdotes, often involving striking coincidences. But such assumptions sidestep two sizeable objections. Firstly, true sociability that is a real connection between two people is almost never built up via anything cheerful. It is the result of making ourselves vulnerable before another person, by revealing some of what is broken, lost, confused, lonely and in pain within us. We build genuine connections when we dare to exchange thoughts that might leave us open to humiliation and judgement; we make real friends through sharing in an uncensored and frank way a little of the agony and confusion of being alive. Secondly, true sociability requires a context. We are generally under such pressure to appear normal, self-possessed and solid, we are understandably uninclined spontaneously to disclose our true selves. Our default mode is without anything sinister being meant by this to lie about who we are and what is really going on in our lives. This suggests that a genuinely social occasion might be rather different from what we typically envisage.', NULL, NULL, NULL),
  ('43482a94-87ca-58a0-94cc-52c51fdc8d78'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '43482a94-87ca-58a0-94cc-52c51fdc8d78'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a78d8795-194b-51f8-ac2e-ae544ab00ab5'::uuid, NULL, E'He gave the child a lecture on the importance of punctuality.', NULL, NULL, NULL),
  ('4349ef5d-0b0f-555a-8a21-4ba5227c8422'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4349ef5d-0b0f-555a-8a21-4ba5227c8422'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '35d3725b-6d6d-50b3-90c4-162f6ff8fdee'::uuid, NULL, E'Some people propose a tax on unhealthy food to discourage consumption.', NULL, NULL, NULL),
  ('4350797d-23f6-5c04-bda3-52278476b6eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '4350797d-23f6-5c04-bda3-52278476b6eb'::uuid, 1, NULL, TRUE, 0, NULL, E'Retirement for Celebrities', NULL, NULL, NULL, NULL, E'2, 4, 3, 1', NULL, NULL),
  ('435715a8-e213-5e9a-818e-7cb4846ecdba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '435715a8-e213-5e9a-818e-7cb4846ecdba'::uuid, 1, NULL, TRUE, 0, NULL, E'Child Health', E'Protecting and improving the health of children is of {{1}} importance. Over the past several decades, we have seen dramatic {{2}} in improving the health and reducing the mortality rate of young children. However, a great deal of work {{3}} to further improve the health outcomes for children. Many child deaths are due to conditions that could be easily {{4}} or treated given access to health care and improvements to their quality of life.', NULL, NULL, NULL, E'1.fundamental, 2.progress, 3.remains, 4.prevented', NULL, NULL),
  ('4359fd2e-acc6-57c9-9e55-76229b051ad4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4359fd2e-acc6-57c9-9e55-76229b051ad4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '31d0d072-7f15-59e1-9088-8c398a5b6417'::uuid, NULL, NULL, E'Swimming utilizes more muscles than most other forms of exercise.', NULL, NULL),
  ('435b27ab-1889-5772-b80c-8e0ef3ee0829'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '435b27ab-1889-5772-b80c-8e0ef3ee0829'::uuid, 1, NULL, TRUE, 0, NULL, E'Electric Vehicles', NULL, '68941ef7-6535-5700-a65c-f6e7ccc39e5e'::uuid, NULL, E'This week I''d like to start by talking a bit about electric vehicles. Although we tend to think of electric cars as being something completely modern, they were in fact some of the earliest types of motorized vehicle. At the beginning of the twentieth century electric cars were actually more popular than cars with an internal combustion engine as they were more comfortable to ride in. However, as cars fuelled by petrol increased in importance, electric cars declined. The situation became Such that electric vehicles were only used for certain specific purposes - as fork-lift trucks, ambulances and urban delivery vehicles, for example.\nAlthough electricity declined in use in road vehicles, it steadily grew in importance as a means of powering trains. Switzerland, for example, was quick to develop an electrified train system, encouraged in this no doubt by the fact that it had no coal or oil resources of its own.\nNowadays there is renewed interest in electricity as a means of powering road vehicles. Why is this the case? Well, undoubtedly economic reasons are of considerable importance. The cost of oil has risen so sharply that there is a strong financial imperative to look for an alternative. However, there are also environmental motivations. Emissions from cars are blamed in large part for - among other things - the destruction of the ozone layer and the resultant rise in temperatures in the polar regions. A desire not to let things get any worse is also encouraging research into designing effective electric transport.', NULL, NULL, NULL),
  ('435eca89-63e4-5508-9a68-6f5e408b1021'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '435eca89-63e4-5508-9a68-6f5e408b1021'::uuid, 1, NULL, TRUE, 0, NULL, E'Borrowed Book', E'You borrowed a book from your friend Anita, but she now wants it back. How would you politely arrange to return the book to her, and possibly discuss a convenient time for her to pick it up?', 'cfc08c2f-ce0c-5b8d-9aed-fe43cead1c0b'::uuid, NULL, E'Hey Anita, I want to talk to you about something.\nWe seem to have a little issue with the book I borrowed from you.\nIt''s like you want your book back, and I’d like to figure out a suitable time for you to come and get it.\nAnd I''d like to know what you think.', NULL, NULL, NULL),
  ('435ee0e7-2259-5d2e-b862-bbaa2002b365'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '435ee0e7-2259-5d2e-b862-bbaa2002b365'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c49570a9-d172-52f8-a93d-5336ffa0f725'::uuid, NULL, NULL, E'I looked into my closet for something to wear but couldn''t find anything that was appropriate.', NULL, NULL),
