  ('4387f40b-2a58-5fcd-986b-5181c4eb4568'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4387f40b-2a58-5fcd-986b-5181c4eb4568'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a large cage in which birds are kept?', 'ef75c50e-d676-54ad-8473-7c5ecf6849e2'::uuid, NULL, NULL, E'Aviary', NULL, NULL),
  ('4388f382-61f4-5d9d-aca3-ccaeb7021d08'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4388f382-61f4-5d9d-aca3-ccaeb7021d08'::uuid, 1, NULL, TRUE, 0, NULL, E'Community Gardens', E'Around the world, city residents build gardens on balconies, rooftops and small strips of land. A March 2023 study published in the journal Ecology Letters confirms that beyond offering food and an outlet for cultivating outdoor space, urban gardens provide benefits for the humans, insects, and animals who inhabit these leafy respites from city life.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('438bca83-c5ad-5415-8e46-7518fb2ea16d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '438bca83-c5ad-5415-8e46-7518fb2ea16d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0cf787d6-5aa5-5ea4-afb2-84bcb8e40c68'::uuid, NULL, E'Simply answering this complex question with yes or no won''t work.', NULL, NULL, NULL),
  ('438ecf4e-e0cb-5dc4-9b13-9fb9ba00ac47'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '438ecf4e-e0cb-5dc4-9b13-9fb9ba00ac47'::uuid, 1, NULL, TRUE, 0, NULL, E'Zero-gravity', E'Researchers already know that spending long periods of time in a zero-gravity {{1}} —such as that inside the International Space Station (ISS) — results in loss of bone density and {{2}} to the body’s {{3}} . That’s partly why stays aboard the ISS are {{4}} at six months. And now, a number of NASA astronauts are reporting that their 20/20 {{5}} {{6}} after spending time in space, with many needing glasses once they returned to Earth.', NULL, NULL, NULL, E'1.environment, 2.damage, 3.muscles, 4.restricted, 5.vision, 6.faded', NULL, NULL),
  ('43966159-0c32-5aeb-905a-b173da1bb238'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '43966159-0c32-5aeb-905a-b173da1bb238'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '668b549c-799b-5b6a-88ac-8221968e4d28'::uuid, NULL, E'We need to work harder to remain competitive with other companies.', NULL, NULL, NULL),
  ('439683fb-ad3b-56dd-a015-6d8ebcdef00a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '439683fb-ad3b-56dd-a015-6d8ebcdef00a'::uuid, 1, NULL, TRUE, 0, NULL, E'Compulsory Voting', E'In some countries around the world, voting is compulsory. Do you agree with the notion of compulsory voting?', NULL, NULL, NULL, NULL, 200, 300),
  ('43a07c84-36c8-527e-89c2-f5ba9d8210d6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '43a07c84-36c8-527e-89c2-f5ba9d8210d6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f39389a2-d9fd-5c23-992f-1e3a9f98daa9'::uuid, NULL, E'Regrettably, Professor Jones possessed limited tolerance for foolish behavior in class.', NULL, NULL, NULL),
  ('43a4af76-f831-58de-8ed2-19e93a23c383'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '43a4af76-f831-58de-8ed2-19e93a23c383'::uuid, 1, NULL, TRUE, 0, NULL, E'Yellow', E'Cheerful sunny yellow is an attention getter. While it is considered an optimistic color, people lose their tempers more often in yellow rooms, and babies will cry more. It is the most difficult color for the eye to take in, so it can be overpowering if overused. Yellow enhances concentration, hence its use for legal pads. It also speeds metabolism.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('43a70a74-ec92-568f-959a-9b5f85319981'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '43a70a74-ec92-568f-959a-9b5f85319981'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the atmospheric layer closest to Earth''s surface, where most weather occurs?', 'b0705957-628f-59b5-936c-536fb9914576'::uuid, NULL, NULL, E'Troposphere', NULL, NULL),
  ('43a9b4ad-8aa8-530b-9e7f-dc4ede7a1188'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '43a9b4ad-8aa8-530b-9e7f-dc4ede7a1188'::uuid, 1, NULL, TRUE, 0, NULL, E'Erasing Memories', E'Throughout our lives, we make many memories, some good and others not so pretty. For the ones that we wish we could forget, there may be a way to achieve this. Erasing memories is possible, but you must be willing to go seriously out of your way to achieve your goal.\nScientists recently discovered that our memories are not as permanent as we thought. Research on both animals and humans has shown that using drugs like propranolol, a high blood pressure medication, can rewire our brains to the point where we lessen the effects of emotional memories. This research is backed by the discovery that every memory is locked in different connections in your brain. When you form a memory, proteins stimulate specific brain cells to help create new connections.\nFor instance, if bikes scare you, it is because you, or someone close to you, had a bad experience with one. As you take your prescription, you will only be scared of bikes without defaulting to the bad experience. Research may also suggest that a placebo (usually a sugar pill that the user believes is the real drug) can alter behaviors that may dissipate the psychosomatic effects of a bad memory.\nWhether you should erase your memories is not a straightforward answer. That problem seems like it belongs to the ethics department.', NULL, NULL, NULL, NULL, 5, 75),
  ('43af5151-de78-553c-a412-dc07543d0e8a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '43af5151-de78-553c-a412-dc07543d0e8a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1e867477-532d-5578-9936-a8309f5c16a6'::uuid, NULL, NULL, E'Physics students will take an additional module if their grades are low.', NULL, NULL),
  ('43b48d27-5ba7-5b76-9b3e-1d038f075714'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '43b48d27-5ba7-5b76-9b3e-1d038f075714'::uuid, 1, NULL, TRUE, 0, NULL, E'Opium War', NULL, 'b7273f55-3aaf-55ad-90b3-30fe47badfd2'::uuid, NULL, E'And as Great Britain grew, interest in tea spread around the world. By 1700, tea in Europe sold for ten times the price of coffee and the plant was still only grown in China. The tea trade was so lucrative that the world’s fastest sailboat, the clipper ship, was born out of intense competition between Western trading companies. All were racing to bring their tea back to Europe first to maximize their profits. At first, Britain paid for all this Chinese tea with silver. When that proved too expensive, they suggested trading tea for another substance, opium. This triggered a public health problem within China as people became addicted to the drug. Then in 1839, a Chinese official ordered his men to destroy massive British shipments of opium as a statement against Britain’s influence over China. This act triggered the First Opium War between the two nations. Fighting raged up and down the Chinese coast until 1842 when the defeated Qing Dynasty ceded the port of Hong Kong to the British and resumed trading on unfavorable terms. The war weakened China’s global standing for over a century.', NULL, NULL, NULL),
  ('43b506d8-2461-5bab-b19f-d11b501209bf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '43b506d8-2461-5bab-b19f-d11b501209bf'::uuid, 1, NULL, TRUE, 0, NULL, E'A_Female_Writer', NULL, '54153883-ff7f-57f7-82cc-dda420f7a6f4'::uuid, NULL, E'I''ve been written non-fictions for years actually and but secretly I wanted to be a novelist. When I first started writing at the age of thirty was with the intension of writing a fiction. But I took a long detour and for ten or twelve years and wrote non- fiction which I absolutely had no regret about it at all. I think it exactly the right thing for me to do. But that was that dream took away and side of me to do this. Now I remember reading something that Eudora Welty wrote, who is, you know, the great novelist who has a big influence on me actually, and she said ''No art ever came out of not risking your neck.'' And I think she is absolutely right about that. It doubts that way to me at that time and it actually feels that way to me every time I sit down to write something. Finally, in the early 90s, I took my deep breath and started writing fiction. It felt risky to me at the time to do that. And one of the very first things that I wrote was what I thought was going to be, the first chapter of the novel called ''The Secret Life of Bees''. I wrote it in 1992 and it is actually an essentially the first chapter of the novel, as it is now.', NULL, NULL, NULL),
  ('43b683d6-5fbc-56ec-a481-3e8ce163785f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '43b683d6-5fbc-56ec-a481-3e8ce163785f'::uuid, 1, NULL, TRUE, 0, NULL, E'Sustainable Tourism', NULL, '8bb6e91f-185f-5620-9c98-233a6e99bffd'::uuid, NULL, E'Sustainable tourism is a concept vital to preserving the world''s cultural and natural heritage. This responsible travel philosophy is about making a positive impact on the environments we visit and the communities we encounter. Firstly, sustainable tourism is about respecting and contributing to local cultures. It involves engaging with tradition, supporting artisan markets, and preserving historical sites. By doing so, we become not just tourists, but advocates for cultural preservation. Secondly, it emphasizes environmental conservation. By choosing eco-friendly accommodations and activities, we minimize our carbon footprint. Practices like leaving no trace and reducing plastic use help protect natural landscapes and wildlife. As we venture out to explore the world, let''s commit to sustainable tourism practices. Our conscious choices ensure that the beauty and diversity of our global destinations remain for future travelers to appreciate.', NULL, NULL, NULL),
  ('43bfcead-19fa-5cd4-8283-1af2b2546522'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '43bfcead-19fa-5cd4-8283-1af2b2546522'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c74dd338-73a1-55f5-a84a-75811b0f8796'::uuid, NULL, E'Don''t waste the precious years of youth.', NULL, NULL, NULL),
  ('43c849c4-bf97-5838-85ef-4a749a881aa0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '43c849c4-bf97-5838-85ef-4a749a881aa0'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-R', E'The outpouring of contemporary American Indian literature in the last two decades, often called the Native American Renaissance, represents for many the first opportunity to experience Native American poetry. The appreciation of traditional oral American Indian literature has been limited, hampered by poor translations and by the difficulty, even in the rare culturally sensitive and aesthetically satisfying translation, of completely conveying the original''s verse structure, tone, and syntax. By writing in English and experimenting with European literary forms, contemporary American Indian writers have broadened their potential audience, while clearly retaining many essential characteristics of their ancestral oral traditions. For example, Pulitzer-prizewinning author N. Scott Momaday''s poetry often treats art and mortality in a manner that recalls British romantic poetry, while his poetic response to the power of natural forces recalls Cherokee oral literature. In the same way, his novels, an art form European in origin, display an eloquence that echoes the oratorical grandeur of the great nineteenth-century American Indian chiefs.\n\nWhich of the following is most likely one of the reasons that the author mentions the work of N. Scott Momaday?', NULL, NULL, NULL, E'To illustrate how the author believes that members of the Native American Renaissance have broadened their potential audience', NULL, NULL),
  ('43c9c328-e114-5167-949b-5eaca8838cec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '43c9c328-e114-5167-949b-5eaca8838cec'::uuid, 1, NULL, TRUE, 0, NULL, E'Domestication of Dog', E'The domestication of the dog from its wild ancestors is a story that spans thousands of years. Originally, dogs were {{1}} for their abilities in hunting and protection. Over time, selective breeding led to a wide variety of breeds, each {{2}} to different tasks and environments. As a result, dogs have become the most widespread and popular domestic animals in the world, with a population {{3}} to be over 900 million.', NULL, NULL, NULL, E'1.tamed, 2.suited, 3.estimated', NULL, NULL),
  ('43d01771-3a5f-586f-950a-cceb5df8c6b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '43d01771-3a5f-586f-950a-cceb5df8c6b9'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the equipment with apparatus for controlling the humidity and temperature in a room?', '7503a8b0-a9a3-574b-bff5-fcdabe6b3917'::uuid, NULL, NULL, E'Air conditioner', NULL, NULL),
