  ('43d75b73-7fbb-5512-a148-20bd4fb1344e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '43d75b73-7fbb-5512-a148-20bd4fb1344e'::uuid, 1, NULL, TRUE, 0, NULL, E'Performance Appraisals', E'Performance appraisals have traditionally been considered the best way to {{1}} an employee''s performance, but increasingly organizations are finding them of little {{2}} . Employees find them stressful and unhelpful. Importantly, they also take up a lot of time. When Deloitte analyzed their own {{3}} , they found managers and employees spent around 2 million hours a year on performance reviews. A growing number of companies have decided to {{4}} performance reviews altogether, instead introducing more regular catch-ups.', NULL, NULL, NULL, E'1.evaluate, 2.value, 3.process, 4.abolish', NULL, NULL),
  ('43d80de8-4e7b-5d52-abab-168dca4a79f2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '43d80de8-4e7b-5d52-abab-168dca4a79f2'::uuid, 1, NULL, TRUE, 0, NULL, E'Unicorn', E'Unicorns roam free in fantasy novels and children’s stories, not so much in the real world, much less the cold, analytical ones of math and philosophy. But it turns out that these logical disciplines are only one misstep away from proving the existence of the long-adored mythic creatures—or proving any absurdity.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('43d8cd24-b209-558a-b442-b0bde5ab20f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '43d8cd24-b209-558a-b442-b0bde5ab20f9'::uuid, 1, NULL, TRUE, 0, NULL, E'Chemical Incidents', E'A chemical incident is the uncontrolled release of a toxic substance, potentially {{1}} in harm to public health and the environment. Chemical incidents can {{2}} as a result of natural events, or as a result of accidental or intentional events. These incidents can be sudden and acute or have a slow {{3}} when there is a ‘silent’ release of a chemical. They can also range from small releases to full-scale major {{4}} .', NULL, NULL, NULL, E'1.resulting, 2.occur, 3.onset, 4.emergencies', NULL, NULL),
  ('43d941cc-ed9b-56b5-80fc-d41c7712a544'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '43d941cc-ed9b-56b5-80fc-d41c7712a544'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Lettuce and carrots come under which category?', 'd4c0c41b-eb1e-5a27-aad1-15065eb6e307'::uuid, NULL, NULL, E'Vegetable', NULL, NULL),
  ('43dd0767-193e-5227-8b22-0d33890821a4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '43dd0767-193e-5227-8b22-0d33890821a4'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the time period before noon called?', '7f719365-cee5-55dc-a2a4-a53f976d6626'::uuid, NULL, NULL, E'Ante meridian / A.M / ante meridiem / morning', NULL, NULL),
