  ('43e47410-48cb-5d77-87e3-05d96e8c4809'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '43e47410-48cb-5d77-87e3-05d96e8c4809'::uuid, 1, NULL, TRUE, 0, NULL, E'Vitamin and Death', E'Vitamin D deficiency linked to premature death. Over a 14-year follow-up period, researchers found that the risk for death significantly decreased with increased vitamin D concentrations, with the strongest effects seen among those with severe deficiencies.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('43ebe2c6-01d2-529c-ac39-d482a03bda1f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '43ebe2c6-01d2-529c-ac39-d482a03bda1f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5b711faf-2a8d-5707-ae77-4ea39ad3a948'::uuid, NULL, E'Kids are not allowed in chemical labs due to safety concerns.', NULL, NULL, NULL),
