  ('43f1e505-f615-559b-bbe5-54c766c70f22'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '43f1e505-f615-559b-bbe5-54c766c70f22'::uuid, 1, NULL, TRUE, 0, NULL, E'Harvest Moon', E'The harvest moon is the full moon closest to the autumnal equinox, typically in late September or early October. Typically, the moon rises about 50 minutes later each day, but the same doesn''t go for harvest moons. The rising harvest moon appears in the night sky about 25 minutes later than the previous night''s moon — a much shorter time between moonrises.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('43f89443-2ff0-5669-bab8-febe51410abe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '43f89443-2ff0-5669-bab8-febe51410abe'::uuid, 1, NULL, TRUE, 0, NULL, E'Calligraphy', NULL, NULL, NULL, NULL, E'2, 4, 3, 1', NULL, NULL),
  ('43fd8c69-0c55-50d1-afa7-38731a32fd49'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '43fd8c69-0c55-50d1-afa7-38731a32fd49'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the period between sunrise and sunset?', 'f2152b4c-37d3-59cb-97ed-8bfba8425afa'::uuid, NULL, NULL, E'Daytime', NULL, NULL),
  ('4401fe99-e0dd-5046-a7a0-eef2fa8a6f62'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4401fe99-e0dd-5046-a7a0-eef2fa8a6f62'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f9922c04-b765-5a91-a0e5-0e80b819d5de'::uuid, NULL, NULL, E'The business partner or corporate sponsor can be an organization.', NULL, NULL),
  ('4403955c-09cb-5bb6-9285-6f28c6ee8359'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '4403955c-09cb-5bb6-9285-6f28c6ee8359'::uuid, 1, NULL, TRUE, 0, NULL, E'Roman Concrete', E'Roman concrete, in many cases, has proven to be longer-lasting than its modern {{1}} ,which can deteriorate within decades. Now, scientists behind a new study say they have uncovered the mystery ingredient that allowed the Romans to make their construction material so durable and build {{2}} structures in challenging places such as docks, sewers and earthquake zones. They found that white chunks in the concrete, referred to as lime clasts, gave the concrete the ability to heal cracks that formed over time. The white chunks previously had been {{3}} as evidence of sloppy mixing or poor-quality raw material. With further study, the researchers concluded that lime clasts arose because of the use of quicklime (calcium oxide) – the most reactive, and dangerous, dry form of limestone – when mixing the concrete, rather than or in addition to slaked lime. Additional analysis of the concrete showed that the lime clasts formed {{4}} extreme temperatures expected from the use of quicklime, and “hot mixing” was key to the concrete’s durable nature.', NULL, NULL, NULL, E'1.equivalent, 2.elaborate, 3.overlooked, 4.at', NULL, NULL),
  ('44042ebc-af06-5ba6-8e5f-e9947231bad1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '44042ebc-af06-5ba6-8e5f-e9947231bad1'::uuid, 1, NULL, TRUE, 0, NULL, E'Bilingualism', E'There are many benefits to bilingualism and exposure to multiple languages. Children who learn multiple languages learn to be sensitive to their conversation partners; they make word and language choices based on their knowledge of others. These are sophisticated social decisions that show advanced social skills.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('4404838e-08f9-5ce5-be23-1fe78eb41363'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4404838e-08f9-5ce5-be23-1fe78eb41363'::uuid, 1, NULL, TRUE, 0, NULL, E'Baidu', E'China’s biggest online-search company, Baidu, said it would make its self-driving car technologies available to others. In a bid to advance autonomous vehicles—and perhaps to become an industry standard in the same way that Google’s Android operating system is for smartphones—Baidu’s Apollo project will distribute technologies to developers and carmakers, initially for use in restricted environments, as soon as July.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('44064e4d-3992-578e-a0c7-af7935413d5f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '44064e4d-3992-578e-a0c7-af7935413d5f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the date on which someone is born?', '65c3d506-7b0b-57d4-b719-0483abc5a92a'::uuid, NULL, NULL, E'Birthday', NULL, NULL),
  ('4409125d-2574-54fc-b1a4-01e475fde238'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4409125d-2574-54fc-b1a4-01e475fde238'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9b9680fd-b762-5b7f-9ae6-c7f83353be4d'::uuid, NULL, E'I will be in my office every Tuesday and Thursday.', NULL, NULL, NULL),
  ('44141ecc-d7b4-54d3-a5e0-7e13ee988c35'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '44141ecc-d7b4-54d3-a5e0-7e13ee988c35'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What type of food is an apple?', 'e8e01cc1-29c3-5943-8635-704d4565d576'::uuid, NULL, NULL, E'Fruit', NULL, NULL),
  ('441aa8c6-a28b-5903-af94-bb6f884090e0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '441aa8c6-a28b-5903-af94-bb6f884090e0'::uuid, 1, NULL, TRUE, 0, NULL, E'Owls', E'Owls are nearly {{1}} hunters, swooping down on prey without any warning whoosh. How do they do it?\nWe''ve known that the leading edge of an owl''s wing has a comb of stiff {{2}} . And the trailing edge has a flexible fringe, unlike the rigid trailing edge of a {{4}} bird wing. These two features contribute to a structure that {{5}} almost no noise as it rushes through the air.\nNow it appears that these {{6}} have a third trick up their sleeves — or rather, wings — that allow them to be so silent but deadly.\nResearchers modeled the effect of the layer of down on the wing''s top surface. And it looks like that fluffy stuff absorbs sound too. The work was presented at a meeting of the American Physical Society''s Division of Fluid Dynamics.\nMimicking owl wing down may lead to new sound-proofing materials. Down and the other silencing features could inspire wind turbines and plane engines that produce less noise and fewer vibrations. So that all we hear is silence.', NULL, NULL, NULL, E'1.noiseless, 2.feathers, 3.conventional, 4.produces, 5.predators', NULL, NULL),
  ('441c5cc2-6d14-52ab-9992-48d2fa17761f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '441c5cc2-6d14-52ab-9992-48d2fa17761f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '98356d3f-26e1-50b0-9da7-250c75010fa8'::uuid, NULL, E'Her father prevented me from talking to her.', NULL, NULL, NULL),
  ('4420fae2-b36e-5751-a234-235d7cc69a03'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4420fae2-b36e-5751-a234-235d7cc69a03'::uuid, 1, NULL, TRUE, 0, NULL, E'Caffeine', NULL, 'c8004b54-e390-5675-8a37-21a2886a5ac5'::uuid, NULL, E'There’s evidence that caffeine’s effects on adenosine and dopamine receptors can have long-term benefits, too, reducing the risk of diseases like Parkinson’s, Alzheimer’s, and some types of cancer. Caffeine can also ramp up the body’s ability to burn fat. In fact, some sports organizations think that caffeine gives athletes an unfair advantage and have placed limits on its consumption. From 1972 until 2004, Olympic athletes had to stay below a certain blood-caffeine concentration to compete. Of course, not all of caffeine’s effects are so helpful. It might make you feel better and more alert, but it can also raise your heart rate and blood pressure, cause increased urination or diarrhea, and contribute to insomnia and anxiety. Plus, the foods and beverages caffeine is found in have their own impacts on your body that have to be taken into account. Your brain can adapt to regular consumption of caffeine. If your adenosine receptors are perpetually clogged, your body will manufacture extra ones. That way, even with caffeine around, adenosine can still do its job of signaling the brain to power down. That’s why you may find you need to consume more and more caffeine to feel as alert. There are more and more adenosine receptors to block.', NULL, NULL, NULL),
  ('442477a3-ef6f-58bd-81c6-02366678d7c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '442477a3-ef6f-58bd-81c6-02366678d7c0'::uuid, 1, NULL, TRUE, 0, NULL, E'Symbiosis', E'Symbiosis is a general term for {{1}} interactions in which two species live together in a long-term, {{2}} association. In everyday life, we sometimes use the term symbiosis to mean a relationship that {{3}} both parties. However, in ecologist-speak, symbiosis is a broader concept and can include {{4}} , lasting relationships with a variety of positive or negative effects on the participants.', NULL, NULL, NULL, E'1.interspecific, 2.intimate, 3.benefits, 4.close', NULL, NULL);
