  ('44589e00-7be7-58b7-b5d0-4eb0cb12934f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '44589e00-7be7-58b7-b5d0-4eb0cb12934f'::uuid, 1, NULL, TRUE, 0, NULL, E'Essay Extension', E'You have an essay due tomorrow, but you have been feeling sick for the past two weeks. You went to the clinic and got a doctor''s note. You feel bad about now but have to ask your professor for an extension until the weekend. You go to the professor''s office. What do you say to him?', 'ab4a2bf3-061b-53eb-8376-d4e5df4a2377'::uuid, NULL, NULL, NULL, NULL, NULL),
