  ('44d3a622-5eac-531c-8086-8f91c904c806'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '44d3a622-5eac-531c-8086-8f91c904c806'::uuid, 1, NULL, TRUE, 0, NULL, E'Happiness and Success', E'Happiness affects personal economic success. Do you agree with this? Give your own example.', NULL, NULL, NULL, NULL, 200, 300),
  ('44daf110-d3b0-5a37-842b-cdd0b6e38b4e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '44daf110-d3b0-5a37-842b-cdd0b6e38b4e'::uuid, 1, NULL, TRUE, 0, NULL, E'Pursuing Academics', E'Pursuing academics is a challenging and rewarding endeavor that requires dedication, hard work, and effective study strategies. Achieving academic goals and succeeding in chosen fields can be accomplished by setting objectives, managing time efficiently, seeking assistance when necessary, and developing a growth mindset that embraces challenges and values learning.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('44dbf312-19e7-55ca-9e8b-9c882e69a561'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '44dbf312-19e7-55ca-9e8b-9c882e69a561'::uuid, 1, NULL, TRUE, 0, NULL, E'Lo-Fab', NULL, '78d288b9-b332-510c-98d0-e834c0e9cc5f'::uuid, NULL, E'Evidence shows that a simple view of nature can radically improve health outcomes, So why couldn’t we design a hospital where every patient had a window with a view? Simple, site-specific designs can make a hospital that heals. Designing it is one thing; getting it built, we learned, is quite another. We worked with Bruce Nizeye, a brilliant engineer, and he thought about construction differently than I had been taught in school. When we had to excavate this enormous hilltop and a bulldozer was expensive and hard to get to site, Bruce suggested doing it by hand, using a method in Rwanda called “Ubudehe,” which means “community works for the community.” Hundreds of people came with shovels and hoes, and we excavated that hill in half the time and half the cost of that bulldozer. Instead of importing furniture, Bruce started a guild, and he brought in master carpenters to train others in how to make furniture by hand. And on this job site, 15 years after the Rwandan genocide, Bruce insisted that we bring on labor from all backgrounds, and that half of them be women. Bruce was using the process of building to heal, not just for those who were sick, but for the entire community as a whole. We call this the locally fabricated way of building, or “lo-fab”, and it has four pillars: hire locally, source regionally, train where you can and most importantly, think about every design decision as an opportunity to invest in the dignity of the places where you serve. Think of it like the local food movement, but for architecture. And we’re convinced that this way of building can be replicated across the world, and change the way we talk about and evaluate architecture.', NULL, NULL, NULL),
  ('44dc97a7-c862-5a5e-9d55-355957da1461'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '44dc97a7-c862-5a5e-9d55-355957da1461'::uuid, 1, NULL, TRUE, 0, NULL, E'Marketing Manager', E'I feel about the opportunity to take on new challenges and {{1}} to the team. While I was working at my previous job, I gained valuable experience that I believe will be beneficial in this role. I am eager to take a {{2}} at your esteemed company and I am {{3}} that my skills and experience make me a strong candidate. Please let me {{4}} if there are any additional steps I need to take or information I need to provide. I am looking {{5}} to your response.', NULL, NULL, NULL, E'1.contribute, 2.position, 3.confident, 4.know, 5.forward', NULL, NULL),
  ('44e407e5-8afa-5e88-9bbc-adf6b7a2785f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '44e407e5-8afa-5e88-9bbc-adf6b7a2785f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ed5059aa-c7b4-5d69-92bf-d8f141591b46'::uuid, NULL, E'Academics need to go outside the university gates and communicate with ordinary people.', NULL, NULL, NULL),
  ('44e5d5e4-acbb-5df8-99e1-5206ea2d6f4c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '44e5d5e4-acbb-5df8-99e1-5206ea2d6f4c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '47bb10dc-b2dc-5b94-b6ca-1c678fee4492'::uuid, NULL, E'International tourism has provided many new employment opportunities for travelers.', NULL, NULL, NULL),
  ('44f0af59-73fd-576a-a9b5-f29175abfc11'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '44f0af59-73fd-576a-a9b5-f29175abfc11'::uuid, 1, NULL, TRUE, 0, NULL, E'Natural Environment', E'Climate change, deforestation, pollution, and overexploitation of natural resources are some of the major threats facing the natural environment. Addressing these challenges requires a comprehensive understanding of the complex interactions between humans and the natural environment, as well as a commitment to sustainable development and responsible environmental stewardship.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('44f0c7e2-73d2-5d84-9a1b-40e02e794ae7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '44f0c7e2-73d2-5d84-9a1b-40e02e794ae7'::uuid, 1, NULL, TRUE, 0, NULL, E'Himalayan Glaciers', E'A team of international researchers has uncovered a fascinating phenomenon: in response to rising global temperatures, Himalayan glaciers are actively working to preserve themselves by cooling the air in contact with their ice surface. However, it remains unclear how long these glaciers can continue to fight back against the effects of climate change.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('44f2a364-7cc0-5eb2-9df4-0bb865da2593'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '44f2a364-7cc0-5eb2-9df4-0bb865da2593'::uuid, 1, NULL, TRUE, 0, NULL, E'Depression', E'Teenagers in the United States are in crisis. That news got hammered home earlier this year following the release of a nationally representative survey showing that over half of high school girls reported persistent feelings of “sadness or hopelessness” — common words used to screen for depression. Almost a third of teenage boys reported those same feelings.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('44f5d997-cee5-5967-b1fd-690342d73f84'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '44f5d997-cee5-5967-b1fd-690342d73f84'::uuid, 1, NULL, TRUE, 0, NULL, E'Free Trade', E'Over the years, to increase trade, many countries have created free trade agreements with other countries. Under the framework of General Agreement on Tariffs and Trade and World Trade Organization, countries opened up their borders and agreed to {{1}} trade barriers, which saw the emergence of International Trade and expanded economic globalization. For example, in 1994, the United States, Mexico, and Canada signed the North American Free Trade Agreement (NAFTA), which ultimately {{2}} all tariffs on trade goods between the three nations. This {{3}} globalization of goods and services, as well as people and ideas, between these three countries.', NULL, NULL, NULL, E'1.remove, 2.removed, 3.allowed', NULL, NULL),
  ('44f64e16-f721-5df0-a53e-87895dc29cce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '44f64e16-f721-5df0-a53e-87895dc29cce'::uuid, 1, NULL, TRUE, 0, NULL, E'Children Skip School', E'Children who skip school are increasingly on family holidays, government figures revealed today. And, {{1}} children {{2}} truant this spring term compared with the spring term last year. Children missed 3m unauthorised days of school last term, compared with 3.7m days of school in the same period last year.\nBut a {{3}} group of truants - 6% of the school population - who account for more than three-quarters of all those on unauthorised absence, are more likely to be on a family holiday than they were in the same {{4}} last year.\nSome 1.2% of all absence was for family holidays not {{5}} by their school last term, compared with 0.9% for the same term last year. More than 60% of all absences were for illness, the same figure as last year.', NULL, NULL, NULL, E'1.fewer, 2.played, 3.hardcore, 4.period, 5.agreed', NULL, NULL),
  ('44f946af-4518-5701-b600-72a3a6378b2d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '44f946af-4518-5701-b600-72a3a6378b2d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '71431e16-596d-5845-ba42-3733aa38ee95'::uuid, NULL, E'This institution was built to help people with psychological illnesses.', NULL, NULL, NULL),
  ('45004803-83be-589e-ab57-9a77e11f1b2c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '45004803-83be-589e-ab57-9a77e11f1b2c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the force that things fall to the ground when they are dropped in the earth?', '3555d57f-d775-518f-b670-67093e6fa7dd'::uuid, NULL, NULL, E'Gravity', NULL, NULL),
  ('45077db4-1fd6-5d47-9a06-a24e157548a5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '45077db4-1fd6-5d47-9a06-a24e157548a5'::uuid, 1, NULL, TRUE, 0, NULL, E'Globalization', E'The benefits and disadvantages of globalization are the subject of ongoing debate. The downside to globalization can be seen in the increased risk for the transmission of diseases. Globalization has of course led to great good, too. Richer nations now can come to the aid of poorer nations in crisis. Increasing diversity in many countries has meant more opportunity to learn about and celebrate other cultures.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('45103d57-f461-5898-bcf2-7051c03b8c58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '45103d57-f461-5898-bcf2-7051c03b8c58'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '234ed9c2-26d3-545c-9b5a-cc556d9e0277'::uuid, NULL, NULL, E'The new articles for the study and the subject are collected.', NULL, NULL),
  ('45151189-7510-5829-89ce-bc50479d1698'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '45151189-7510-5829-89ce-bc50479d1698'::uuid, 1, NULL, TRUE, 0, NULL, E'Living in nursing homes', E'At present, some old people prefer to live in nursing homes instead of living with their adult children. What do you think are the reasons?', NULL, NULL, NULL, NULL, 200, 300),
  ('45178fed-c5fc-54af-88da-8c6c067c0d52'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '45178fed-c5fc-54af-88da-8c6c067c0d52'::uuid, 1, NULL, TRUE, 0, NULL, E'Cup Class Boats', E'At the end of this year, we will launch the cup class boats. So these will be about twice the power. The sailors are down in cockpits, unlike today. A lot of power is being generated by these four grinders that are providing hydraulic power, and that energy is being used to control the flying surface, the hydrofoil and is also being used to control the wing and the flaps.', NULL, NULL, NULL, NULL, NULL, NULL),
