  ('46018a87-1fc4-50c3-a4a4-376f2d7db438'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '46018a87-1fc4-50c3-a4a4-376f2d7db438'::uuid, 1, NULL, TRUE, 0, NULL, E'Thesis (B)', E'A thesis is a claim that you can argue for or against. It should be something that you can present persuasively and clearly in the scope of your paper, so keep in mind the page count. If possible, your thesis should be somewhat original.', NULL, NULL, NULL, NULL, NULL, NULL),
