  ('461ad21b-9fff-58f7-90c3-37f6d0a6fd11'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '461ad21b-9fff-58f7-90c3-37f6d0a6fd11'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'be24f9e6-ee33-5b34-9092-dada5311dde1'::uuid, NULL, E'Almost every representative of a new idea has to struggle and suffer similar difficulties.', NULL, NULL, NULL),
  ('46266531-8405-512a-968f-a1b6a0a6f77d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '46266531-8405-512a-968f-a1b6a0a6f77d'::uuid, 1, NULL, TRUE, 0, NULL, E'Dictionary', E'Samuel Johnson''s Dictionary of the English Language is one of the most famous dictionaries in {{1}} . First published in 1755, the dictionary took just over eight years to compile, {{2}} six helpers and listed 40,000 words. Each word was defined in {{3}} , the definitions illustrated with quotations {{4}} every branch of learning. It was a huge scholarly {{5}} , a more extensive and complex dictionary than any of its predecessors – the comparable French Dictionnaire had taken 55 years to compile and required the dedication of 40 scholars.', NULL, NULL, NULL, E'1.history, 2.required, 3.detail, 4.covering, 5.achievement', NULL, NULL),
  ('462a5d2c-af3c-5861-8435-34057c1cb994'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '462a5d2c-af3c-5861-8435-34057c1cb994'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Is a short sleep in afternoon a siesta or a nap?', '7deb85e2-129e-5a41-a889-aae0627a647b'::uuid, NULL, NULL, E'Siesta', NULL, NULL),
  ('4635beb8-b88d-5206-b319-c269a4c61cf3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4635beb8-b88d-5206-b319-c269a4c61cf3'::uuid, 1, NULL, TRUE, 0, NULL, E'Question Doddging', E'Clementson wanted to see if claims of question dodging actually held up, historically — not necessarily in the unique case of Trump. So Clementson analysed the transcripts of 14 presidential debates, from 1996 to 2012 . Overall, he found 51 accusations of question dodging — 26 by Dems, 25 by Republicans.', NULL, NULL, NULL, NULL, NULL, NULL),
