  ('465f12df-639c-5665-ae35-20b595191022'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '465f12df-639c-5665-ae35-20b595191022'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the sour yellow fruit used to make lemonade?', '50e7ff91-90cd-589c-af40-721ee68bbf7d'::uuid, NULL, NULL, E'Lemon', NULL, NULL),
  ('466070be-08e2-51fa-b0f0-1a8e690a40c7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '466070be-08e2-51fa-b0f0-1a8e690a40c7'::uuid, 1, NULL, TRUE, 0, NULL, E'Ancient Athens', E'In ancient Athens, a boy was socially located by his family identity, and Plato often refers to his characters in terms of their paternal and fraternal relationships. Socrates was not a family man and saw himself as the son of his mother, who was apparently a midwife.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('4663d3d8-a3d1-5243-a230-9ab90a22fec0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4663d3d8-a3d1-5243-a230-9ab90a22fec0'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9524ff86-d0dc-5d0e-80d5-8ab4bb66cfed'::uuid, NULL, NULL, E'Canada has a long history of immigration from many different parts of the world.', NULL, NULL),
  ('466b13e0-4202-5947-8cc0-b829dbc452c9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '466b13e0-4202-5947-8cc0-b829dbc452c9'::uuid, 1, NULL, TRUE, 0, NULL, E'Polynesians', E'The Polynesians explored and {{1}} islands of the South Pacific by traveling in 18-meter-long, double-hull canoes and living on the {{2}} ocean for days or weeks as they moved between islands. They used observations of the stars to help them navigate across the ocean and developed a {{3}} sense of the ocean currents and how winds and islands {{4}} them.', NULL, NULL, NULL, E'1.settled, 2.open, 3.keen, 4.influenced', NULL, NULL),
  ('466cf291-cae7-5047-b0e6-f36de3fcbe6b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '466cf291-cae7-5047-b0e6-f36de3fcbe6b'::uuid, 1, NULL, TRUE, 0, NULL, E'Burnout', E'Burnout is a common condition associated with the pressures of the modern world. It’s not just a physical condition; it has psychological effects that can impact heavily on your work and life in general. Suffering from burnout can stifle our creativity and productivity. Taking steps to avoid burning out can benefit not just us, but our bosses and families. Psychologist Albert Bandura’s idea of self-efficacy — which is the theory that you should believe in your ability to complete a task at hand — may assist you. A feeling that the task is achievable and that you are capable of succeeding means that a difficult task might be less gruelling. Finding ways to express your creative side may help. Not everyone has creative aspects to their jobs, and, therefore, they need to find other outlets. They could paint, write or take part in local theatre. All of this may help to detach them from the overwhelming stress that may exist in their working life. Looking after yourself and your surroundings can also be beneficial. The consequence is that you are surrounded by a cleaner and more positive environment. This, in turn, leads to another tip, which is to have healthy and positive thoughts. Being negative can be incredibly draining. Having a positive mental attitude towards everything you do means that you may feel more capable as well.', NULL, NULL, NULL, NULL, 5, 75),
  ('466f28d2-d22c-537d-9443-0ea99842c013'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '466f28d2-d22c-537d-9443-0ea99842c013'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2aaa3204-fb3a-5916-9f05-23d1a2c0d4d1'::uuid, NULL, NULL, E'Make sure to read chapter one before our management class.', NULL, NULL),
  ('4670cb77-2825-5ad9-9aa7-c57cad1dff92'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4670cb77-2825-5ad9-9aa7-c57cad1dff92'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '603d0cb7-7286-5439-8b68-d8b05dd92a82'::uuid, NULL, NULL, E'Scientists have found all parts of society today.', NULL, NULL),
