  ('469555c7-f8ad-5f09-bb92-fa79caa045ec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '469555c7-f8ad-5f09-bb92-fa79caa045ec'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '49c8720c-0b47-5a4b-baf6-cb5b8722da8e'::uuid, NULL, NULL, E'You can find what each part of the course involves online.', NULL, NULL),
  ('4696060d-abe6-5b68-9e08-2283b8d85456'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4696060d-abe6-5b68-9e08-2283b8d85456'::uuid, 1, NULL, TRUE, 0, NULL, E'Tiny Bot', E'Humanity took a step forward into that future recently, when Israeli scientists revealed that they''ve developed a new type of brain-machine interface, which for the first time has allowed a human operator to control a nanobot implanted inside the body of a living creature (in this case a cockroach), simply by using his thoughts.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('469bf38d-96d6-5e57-8371-a4693c2905bb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '469bf38d-96d6-5e57-8371-a4693c2905bb'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '91965e7c-60e9-51eb-b232-d6d36af27ba4'::uuid, NULL, E'You need to use a Bunsen burner and a test tube.', NULL, NULL, NULL),
  ('469ca953-867a-5f29-840f-93552434f5fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '469ca953-867a-5f29-840f-93552434f5fd'::uuid, 1, NULL, TRUE, 0, NULL, E'Shrimp Farms', E'Over the past two decades around a third of the world’s mangrove swamps have been {{1}} for human use, with many turned into valuable shrimp farms. In 2007 an economic study of such shrimp farms in Thailand showed that the commercial profits per hectare were $9,632. If that were the only factor, conversion would seem an excellent idea.\nHowever, proper {{2}} shows that for each hectare government subsidies formed $8,412 of this figure and there were costs, too: $1,000 for pollution and $12,392 for losses to ecosystem services. These {{3}} damage to the supply of foods and medicines that people had taken from the forest, the loss of habitats for fish, and less buffering against storms. And because a given shrimp farm only stays {{4}} for three or four years, there was the additional cost of restoring them afterwards.', NULL, NULL, NULL, E'1.converted, 2.accounting, 3.comprised, 4.productive', NULL, NULL),
  ('469d6886-647f-5a52-b019-b24f2fae1aff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '469d6886-647f-5a52-b019-b24f2fae1aff'::uuid, 1, NULL, TRUE, 0, NULL, E'Australian Immigration', E'Australia has a proud modern immigration history. Government discrimination has been banished, replaced by a skills-based\nsystem generating unparalleled economic gain for Australia. Creating an environment where innovation can thrive depends on immigration. With a population where one in four people are born overseas, Australia is already well positioned to kick start a new period of growth.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('469ea82e-bf14-564c-90e3-f440eed630d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '469ea82e-bf14-564c-90e3-f440eed630d7'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for a naturally occurring solid aggregate of minerals or mineraloids?', 'd19365f6-ad11-5cac-b45d-783e0dea3868'::uuid, NULL, NULL, E'Rock', NULL, NULL),
