  ('46a555dd-18c5-5f9a-9ce7-81c34c24a080'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '46a555dd-18c5-5f9a-9ce7-81c34c24a080'::uuid, 1, NULL, TRUE, 0, NULL, E'Effective Healers', E'Effective healers accompany sufferers on a journey toward wellness. Healing tools include the deft use of suggestion, confession, memory, ritual and medicines. Healers find ways to provide consolation and hope, enabling their wounded charges to engage with meaningful work and find purpose in life.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('46aaf5fb-af18-5438-8c0b-0da20400a140'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '46aaf5fb-af18-5438-8c0b-0da20400a140'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '382fbe24-c910-5074-9651-07292df072a4'::uuid, NULL, NULL, E'People look at organizational failure in different ways in studies.', NULL, NULL),
  ('46af758c-5f54-59c5-9536-0bd0f2e14dd2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '46af758c-5f54-59c5-9536-0bd0f2e14dd2'::uuid, 1, NULL, TRUE, 0, NULL, E'World Maps', NULL, NULL, NULL, NULL, E'3, 4, 2, 1', NULL, NULL),
  ('46afc8e0-a5fe-5d20-b69b-c1c393b1205c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '46afc8e0-a5fe-5d20-b69b-c1c393b1205c'::uuid, 1, NULL, TRUE, 0, NULL, E'Coral Reefs', E'Coral reefs {{1}} more marine life than any other ocean ecosystem and are, not {{2}} , a favorite pursuit for many divers. But as well as being physically and biologically spectacular, coral reefs also sustain the livelihoods of over half a billion people. What is more, this number is expected to {{3}} in coming decades while the area of high-quality reef is expected to halve. In combination with the very real threat of climate change, which could lead to increased seawater temperatures and ocean acidification , we start to arrive at some quite frightening scenarios.', NULL, NULL, NULL, E'1.support, 2.surprisingly, 3.double', NULL, NULL),
  ('46b30775-b4b6-5486-bb91-9e636c509aa8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '46b30775-b4b6-5486-bb91-9e636c509aa8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What kind of gas is necessary for the survival of most living animals?', '2539db7d-8e5c-5da1-a332-7eaf0e907c79'::uuid, NULL, NULL, E'Oxygen', NULL, NULL),
  ('46b6e900-b35b-5968-8b1f-ad5017616d1e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '46b6e900-b35b-5968-8b1f-ad5017616d1e'::uuid, 1, NULL, TRUE, 0, NULL, E'Eagles', E'Eagles are found throughout the world, inhabiting diverse ecosystems such as forests, mountains, and coastal regions. They play a crucial role in maintaining the balance of their ecosystems by regulating prey populations. Many species of eagles are threatened by habitat loss, hunting, and pollution, highlighting the need for conservation efforts to protect these magnificent birds and their ecological contributions.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('46b83d98-abae-5171-bbfa-1328e445e4e2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '46b83d98-abae-5171-bbfa-1328e445e4e2'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd16d8a05-fd34-5f99-afd6-a54c044c22ec'::uuid, NULL, E'The students will have enough time to ask questions after the talk.', NULL, NULL, NULL),
  ('46b93124-fa49-50ab-bbc0-f7fc7fb85aa7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '46b93124-fa49-50ab-bbc0-f7fc7fb85aa7'::uuid, 1, NULL, TRUE, 0, NULL, E'Uncaffeinated Adults', E'Researchers gathered 160 uncaffeinated adults, people who consumed less than 500 milligrams of caffeine a week. These decaf subjects looked at pictures of various objects, then took either a placebo or a pill containing 200 milligrams of caffeine. That’s roughly the amount you''d get from two cups of coffee.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('46bd8f1e-faf9-5339-ab3b-b062221ab83c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '46bd8f1e-faf9-5339-ab3b-b062221ab83c'::uuid, 1, NULL, TRUE, 0, NULL, E'Wolf Image', E'The image of a wolf silhouetted against the night sky has led many to believe that wolves howl at the moon. However, scientific investigation into the behavior of these canines reveals that the moon''s presence has {{1}} to do with their iconic vocalizations. Wolves use howling as a form of communication, not as a homage to the celestial body above. Howling serves several critical {{2}} within wolf packs: it helps members keep in {{3}} , allowing them to locate one another when separated by large distances. It also serves as a territorial claim, warning other packs away from their domain. The {{4}} that wolves howl at the moon likely stems from the coincidental timing of their howls with the moon''s visibility in the night sky. Wolves are more active during the night, which is also when the moon is most visible, leading to the association between the two. Additionally, the posture a wolf adopts when howling — nose pointed upwards — further {{5}} the myth. In reality, wolves point their muzzles toward the sky to project their calls as far as possible, not because they are directing their howls at the moon.', NULL, NULL, NULL, E'1.little, 2.functions, 3.touch, 4.misconception, 5.perpetuates', NULL, NULL),
  ('46bfec67-4464-52d5-86ae-64fb6353c2be'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '46bfec67-4464-52d5-86ae-64fb6353c2be'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '18ce89bd-79f4-539d-a324-ffb849bb09ae'::uuid, NULL, NULL, E'A maximum of four individuals can be in the lab simultaneously.', NULL, NULL),
  ('46c229a0-d4e6-5b5f-a6ba-5391ce5e0a61'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '46c229a0-d4e6-5b5f-a6ba-5391ce5e0a61'::uuid, 1, NULL, TRUE, 0, NULL, E'Early Stage Earth', NULL, NULL, NULL, NULL, E'5, 3, 2, 4, 1', NULL, NULL),
  ('46c3eed2-f0ce-5899-9915-a9ff448dfedd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '46c3eed2-f0ce-5899-9915-a9ff448dfedd'::uuid, 1, NULL, TRUE, 0, NULL, E'Body Odor', E'A chemical that is sometimes {{1}} from human skin, breath and faeces has no {{2}} smell, but it appears to influence people''s behavior, with men becoming calmer and women becoming more {{3}} . Although scientists have yet to {{4}} when or under what conditions people and other mammals release hexadecanal, it seems clear that humans are ‘communicating’ with each other {{5}} through their body odor.', NULL, NULL, NULL, E'1.emitted, 2.detectable, 3.aggressive, 4.determine, 5.subconsciously', NULL, NULL),
  ('46ccb28d-33e2-52b4-bd58-5e114c41b126'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '46ccb28d-33e2-52b4-bd58-5e114c41b126'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What should we call a permanent mark on a person’s skin since his or her birth?', '5eb76da8-860b-534c-9b11-f3ceafc7189d'::uuid, NULL, NULL, E'Birthmark', NULL, NULL),
  ('46cf8e34-dcac-5a15-8c1b-b019fe00c4fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '46cf8e34-dcac-5a15-8c1b-b019fe00c4fe'::uuid, 1, NULL, TRUE, 0, NULL, E'World Cup', E'Those of you {{1}} the World Cup know that at this stage there can be no more draws. Ties are broken during {{2}} play, or in a penalty kick shootout in which a {{3}} ''s ability to anticipate the ball''s flight can mean the difference between victory and elimination. Now, {{4}} at Rensselaer {{5}} Institute have discovered how a kicker''s body can betray whether he''s aiming left or right.\nIn a penalty shot, it''s kicker versus goalkeeper. And with the shooter standing just 12 yards from the goal, that ball can touch net in about half a second. That''s faster than a keeper can launch himself from the goal''s center to either post. Which means that a goalkeeper has to start moving before the kicker''s foot meets the ball. And he has to guess correctly which way to dive.\nTo figure out how good goalies might up their odds, scientists {{6}} motion detectors to college-level penalty kickers. And they found a handful of {{7}} that reliably predict kick direction, such as the angle of the kicker''s hips and how he plants his supporting foot.\nGood goalies may be able to read those subtle cues. Meaning that they use their hands, and their heads.', NULL, NULL, NULL, E'1.following, 2.overtime, 3.goalkeeper, 4.scientists, 5.Polytechnic, 6.attached, 7.indicators', NULL, NULL),
  ('46d2ede6-3fdd-5ff0-823c-83fbce51f264'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '46d2ede6-3fdd-5ff0-823c-83fbce51f264'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6ecc62e9-7acb-52aa-b9e1-049608e07334'::uuid, NULL, NULL, E'The evaluation form will be reviewed by university personnel.', NULL, NULL),
  ('46d87391-5723-54d2-9ff6-d24faffc5cac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '46d87391-5723-54d2-9ff6-d24faffc5cac'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5740c375-e78b-5cf5-8d38-2701a1d837f2'::uuid, NULL, E'The interviewer asked her to speak into the microphone.', NULL, NULL, NULL),
  ('46e0ec6f-e0cb-555b-b0e7-356a9ba49235'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '46e0ec6f-e0cb-555b-b0e7-356a9ba49235'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call someone who writes for newspapers, magazines, or news websites?', '8e27c673-7909-5f36-aeb4-a220a0c21136'::uuid, NULL, NULL, E'Journalist', NULL, NULL),
  ('46e151aa-dcaf-5cb3-9a7e-c9a4295e0f0d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '46e151aa-dcaf-5cb3-9a7e-c9a4295e0f0d'::uuid, 1, NULL, TRUE, 0, NULL, E'Online User', E'Online user reviews have become an essential tool for consumers who increasingly rely on them to evaluate products and services before purchase. The business models of online review platforms like Yelp and TripAdvisor, and e-commerce sites like Amazon and Expedia critically depend on them. Should such sites pay users to encourage them to write reviews? According to a new study, that is a bad idea.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('46e49277-dc0d-5377-bf33-0733d536bf07'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '46e49277-dc0d-5377-bf33-0733d536bf07'::uuid, 1, NULL, TRUE, 0, NULL, E'Neuromorphic Computing', E'As advancements continue to be made in neuromorphic computing, the integration of targeted magnetic waves and other innovative techniques holds promise for creating more efficient and powerful AI systems. These developments could revolutionize various fields, including robotics, image recognition, and natural language processing. The future of neuromorphic computing is bright and full of exciting possibilities.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('46e4ef36-fdfb-513b-a5b0-1cec862e168c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '46e4ef36-fdfb-513b-a5b0-1cec862e168c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'be4494b7-c29d-5c40-b3ef-834facf886db'::uuid, NULL, NULL, E'Throughout his life, he composed a vast array of music.', NULL, NULL),
  ('46ea4015-5c70-5221-b26e-099d2caceb88'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '46ea4015-5c70-5221-b26e-099d2caceb88'::uuid, 1, NULL, TRUE, 0, NULL, E'Light Pollution', E'The widespread use of artificial light in modern societies means that light pollution is an increasingly common feature of the environments humans inhabit. This type of pollution is {{1}} high in coastal regions of tropic and temperate zones, as these are areas of high rates of human population growth and settlement. Light pollution is a threat for many species that inhabit these locations, particularly those whose ecology or behavior depends, {{2}} , on natural cycles of light and dark. Artificial light is known to have detrimental effects on the ecology of sea turtles, particularly at the hatchling stage when they emerge from nests on natal beaches and head towards the sea. Under natural conditions, turtles hatch predominantly at night (although some early morning and late afternoon emergence occurs) and show an innate and well-directed orientation to the water, {{3}} mostly on light cues that attract them toward the brighter horizon above the sea surface. Artificial lighting on beaches is strongly attractive to hatchlings and can cause {{4}} away from the sea and interfere with their ability to orient in a constant direction. Ultimately, this disorientation due to light pollution can lead to death of hatchlings from exhaustion, dehydration and predation.', NULL, NULL, NULL, E'1.exceptionally, 2.in some way, 3.relying, 4.them to move', NULL, NULL),
  ('46eac6ed-26e4-53c6-8b6c-084be68aade9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '46eac6ed-26e4-53c6-8b6c-084be68aade9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '376d5a0a-b65a-5f05-bd44-c165d3903f3e'::uuid, NULL, NULL, E'Mathematical physics is difficult for the new students.', NULL, NULL),
  ('46ed257f-6119-59e5-b238-93c5762c3830'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '46ed257f-6119-59e5-b238-93c5762c3830'::uuid, 1, NULL, TRUE, 0, NULL, E'Computer Storage', NULL, NULL, NULL, NULL, E'3, 1, 4, 2', NULL, NULL),
  ('46ed2855-2326-5e9c-8d70-7ce1c8fa3b85'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '46ed2855-2326-5e9c-8d70-7ce1c8fa3b85'::uuid, 1, NULL, TRUE, 0, NULL, E'Astronomy', E'Astronomy is a science {{1}} that studies virtually everything beyond the earth. It emphasizes the when and where a celestial {{2}} can be observed. Astronomy requires the skill of careful {{3}} in order to understand and discover depth of the universe. It was through observations that preliminary understanding of {{4}} of days, nights, and monthly patterns was achieved.', NULL, NULL, NULL, E'1.discipline, 2.object, 3.observation, 4.timing', NULL, NULL),
  ('46efd34d-cc5d-594e-94a4-7c23d2981c2d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '46efd34d-cc5d-594e-94a4-7c23d2981c2d'::uuid, 1, NULL, TRUE, 0, NULL, E'Repetitive Syllables', E'Assessments of language learning in 18-month-olds suggest that children are better at grasping the names of objects with repeated syllables, over words with non-identical syllables. Researchers say the study may help {{1}} why some words or phrases, such as ''train'' and ''good night'', have given rise to versions with repeated syllables, such as choo-choo and night-night. The researchers say such words are easier for infants to learn, and may provide them {{2}} a starter point for vocabulary learning. A team from the University of Edinburgh assessed the infants'' language learning behavior in a series of {{3}} and attention tests using pictures on a computer screen of two unfamiliar objects. The two objects were named with {{4}} words which were {{5}} to the infants by a recorded voice — one with two identical syllables, for example neenee, and the other without repeated syllables, such as bolay. The infants were then tested for their recognition of {{6}} word. Recordings of their eye movements showed they looked more reliably at the object labeled with repeated syllables, than the other object. Researchers validated their results with a control test, in which the infants responded to pictures of familiar objects — such as a dog or an apple.', NULL, NULL, NULL, E'1.explain, 2.with, 3.visual, 4.made-up, 5.communicated, 6.each', NULL, NULL),
  ('46f1876a-463b-5317-ad93-f5bc7add9299'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '46f1876a-463b-5317-ad93-f5bc7add9299'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the opposite of ‘thick’?', '4c4e3321-15c8-546f-b534-3e3752500523'::uuid, NULL, NULL, E'Thin', NULL, NULL),
  ('46f62463-31c3-5133-8628-5cff143f3384'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '46f62463-31c3-5133-8628-5cff143f3384'::uuid, 1, NULL, TRUE, 0, NULL, E'Communication', E'Communication has changed significantly in the last 10 years. Discuss the positive and negative impacts of this change.', NULL, NULL, NULL, NULL, 200, 300),
