  ('47029b3a-2118-5989-94e4-81f6d13e5de5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '47029b3a-2118-5989-94e4-81f6d13e5de5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '42d69989-817d-541b-9f93-278b159f0099'::uuid, NULL, NULL, E'All students can learn, even though they have different speeds.', NULL, NULL),
  ('470592be-bb5b-58ab-9c67-7b8edb02dc29'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '470592be-bb5b-58ab-9c67-7b8edb02dc29'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9f86ea37-1dba-5f91-803f-e008b49f0629'::uuid, NULL, E'He left England with the intention of traveling in Africa.', NULL, NULL, NULL),
  ('4708e049-7edc-507d-ab0d-dddf9dd2cc22'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4708e049-7edc-507d-ab0d-dddf9dd2cc22'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f12ed822-449b-51f5-bc53-ec14d5b9cb6d'::uuid, NULL, E'This will be the first art exhibition to be held by the university.', NULL, NULL, NULL),
  ('470ac112-7e20-59f3-8b17-165eca108262'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '470ac112-7e20-59f3-8b17-165eca108262'::uuid, 1, NULL, TRUE, 0, NULL, E'Universal Philosophy', NULL, '39ec6ee5-26e6-53e4-9d67-7c91945ddfca'::uuid, NULL, E'Okay. So this is the ... this is the big benefit of a universal philosophy. It says it applies to everybody. Well, looks that doesn''t, you know, 205 or 206 countries in the world. And you''ve got something that applies to everybody. That''s a bit strange, isn''t it? No, says liberal theory. There are same value structures that apply to all of us. You couldn''t have the United Nations without it.\nIt couldn''t tell you that the Universal Declaration of Human Rights without this idea of values that apply to all of us just because we are humans. Now, the idea is to test that as well. Why is sport universal? Why does everybody play football? It''s because the values are specified at a very thin level at the top. There are these rules and we all have to abide by just these rules. But there are lots of things about football that aren''t rules specified. So Brazilian football is different from Italian football, from British football, from German football, from Spanish football. It''s culturally specific, but acknowledges that there are these universal general rules to apply to everybody.', NULL, NULL, NULL),
  ('470ac2b0-2cbb-5bb2-aac5-3fb50dfdfc15'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '470ac2b0-2cbb-5bb2-aac5-3fb50dfdfc15'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the largest desert in the world?', '2cbb8ba3-e4a4-590e-88ce-9746654bcc5e'::uuid, NULL, NULL, E'Sahara Desert', NULL, NULL),
  ('4710f5b1-ec1c-5aaf-a521-9f4ddadf0965'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'HIGHLIGHT_CORRECT_SUMMARY', E'HIGHLIGHT_CORRECT_SUMMARY', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4710f5b1-ec1c-5aaf-a521-9f4ddadf0965'::uuid, 1, NULL, TRUE, 0, NULL, E'HCS', E'There''s no doubt that we have more consumer choices today than ever before. We all think we''re good at making choices - some of us even enjoy making them. And you would think, that with all these consumer choices that people would be spending more money, because they can get exactly what they want. Well, actually, that''s not always the case. Let me tell you about one study that has produced results about this that are really quite counterintuitive.\nAn experiment was done in an upmarket specialty grocery store in the US where a tasting booth was set up, first offering consumers 24 different varieties of jam to try and then at another time, they offered six varieties. Now when there were more varieties, more customers stopped to try than when there were only six. But only about three percent of them actually went ahead and selected a product to buy. This is where it''s interesting - when there were just six varieties, fewer people stopped to try but what the researchers noticed, and what they didn''t expect, was that thirty percent of them bought a jar of jam.\nWhat does this show? Well, it shows that we have choice overload, that up to a point choice is good but beyond that. it overwhelms consumers.\n\nClick on the paragraph that best relates to the recording.', 'd4063ecf-78ef-52de-b4bb-2dd078cd2b21'::uuid, NULL, NULL, E'With a wide range of choices, one would expect consumers to buy more products. However, a consumer experiment found that when customers had many choices, they were likely to sample the products but became overwhelmed and did not buy much, whereas they were more likely to buy something when they had far fewer options to choose from.', NULL, NULL),
  ('47145992-93be-5997-bb7c-c9b304f8d848'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '47145992-93be-5997-bb7c-c9b304f8d848'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '09585a4e-c81d-550f-a4d4-b427aeeff88b'::uuid, NULL, NULL, E'The lecturer spared a few minutes for students to ask questions.', NULL, NULL),
  ('471780b8-698c-5d27-bf92-6cf8ce597f0e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '471780b8-698c-5d27-bf92-6cf8ce597f0e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a3a7b164-c225-5b12-8c9a-467ada8f9dfd'::uuid, NULL, NULL, E'Specific scientific principles must either be verbally learned or deduced logically.', NULL, NULL),
  ('47192024-5c88-5895-8bde-a5ecc2a59f05'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '47192024-5c88-5895-8bde-a5ecc2a59f05'::uuid, 1, NULL, TRUE, 0, NULL, E'Black Box', E'The relationship between the customer (also called the buyer) and the provider (the seller) forms through a phenomenon called a market exchange. During the exchange process, each party assesses the relative trade-offs they must make to {{1}} their respective needs and wants. On the part of the seller, the trade-offs are guided by company polices and objectives. For example, company policy may {{2}} that it can proceed with an exchange only when the profit {{3}} is 10 percent or greater. The buyer — the other party in the exchange — also has policies and objectives that guide his or her decisions in an exchange. For individual buyers, these are usually unwritten personal policies and objectives that people make at each stage of a purchasing decision based on the information and options available to them. Even more likely, individuals often are not fully conscious of what {{4}} them to behave in a particular manner.', NULL, NULL, NULL, E'1.satisfy, 2.dictate, 3.margin, 4.prompts', NULL, NULL),
  ('471cddb7-9a55-5590-8e1a-58bcb71ef686'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '471cddb7-9a55-5590-8e1a-58bcb71ef686'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f605e7fd-7f71-527b-85c0-ed76cd00ea7e'::uuid, NULL, E'The students were instructed to submit their assignments before Friday.', NULL, NULL, NULL),
  ('47204752-a97c-5603-ac4e-031bf59338e4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '47204752-a97c-5603-ac4e-031bf59338e4'::uuid, 1, NULL, TRUE, 0, NULL, E'Organic Food', E'Organic milk and dairy products may contain higher levels of omega-3 fatty acids and slightly higher amounts of iron, vitamin E, and some carotenoids. {{1}} , organic milk may contain less selenium and iodine than non-organic milk. These are two minerals that are essential for health. A review of 67 studies found that organic meat contained higher levels of omega-3 fatty acids and slightly lower levels of saturated fats than conventional meat. A higher intake of omega-3 fatty acids has been {{2}} with many health benefits, including a reduced risk of heart disease. However, several other studies found no differences. While several studies find that organic foods can have significant positive outcomes, others have found insufficient evidence to recommend organic over conventional. An observational study comparing the nutrient intakes of nearly 4,000 adults consuming either organic or conventional vegetables found {{3}} results. Although a slightly higher intake of certain nutrients was seen in the organic group, this was most likely {{4}} higher overall vegetable consumption.', NULL, NULL, NULL, E'1.However, 2.associated, 3.conflicting, 4.due to', NULL, NULL),
  ('4722ad0b-2034-5860-88ca-38ecee49a22a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4722ad0b-2034-5860-88ca-38ecee49a22a'::uuid, 1, NULL, TRUE, 0, NULL, E'Market Research', E'There are two main types of market research. Quantitative research involves collecting a lot of information by using techniques such as questionnaires and other forms of survey. Qualitative research involves working with smaller samples of consumers, often asking them to discuss products and services while researchers take notes about what they have to say.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('472a760f-86f4-5789-a13b-8902e82b996a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '472a760f-86f4-5789-a13b-8902e82b996a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the device used for aerial photography and videography, operated remotely?', '40c9aad0-ffc8-5bfc-b767-47dbee6417c8'::uuid, NULL, NULL, E'Drone', NULL, NULL),
  ('472b32e9-e508-58b2-a815-ce25f453f379'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '472b32e9-e508-58b2-a815-ce25f453f379'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a140420c-c583-500e-ab6e-c96b48fa8bed'::uuid, NULL, NULL, E'Regular exercise promotes physical fitness and reduces stress levels in students.', NULL, NULL),
  ('472ba70d-2a7a-5e78-9494-ef3b22c3585d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '472ba70d-2a7a-5e78-9494-ef3b22c3585d'::uuid, 1, NULL, TRUE, 0, NULL, E'. Modern Democracy', E'Modern democracies, characterized by free elections and protection of civil {{1}} , stand as the prevailing systems of governance in many countries, {{2}} participation and accountability. In these democracies, the {{3}} of the rule of law and separation of powers ensure that government actions are subject to checks and balances, preventing any one branch from {{4}} too much power.', NULL, NULL, NULL, E'1.rights, 2.promoting, 3.principles, 4.amassing', NULL, NULL),
  ('472f2a7d-3655-55d1-9434-cb513d527480'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '472f2a7d-3655-55d1-9434-cb513d527480'::uuid, 1, NULL, TRUE, 0, NULL, E'Self-expression', E'A surprising number of writers, even those who have thought of their writing as "self-expression," have sought a {{1}} from the tyranny of subjectivity, echoing Goethe''s claim that "Every healthy effort is directed from the {{2}} to the outward world." From time to time others have risen to defend commitment, engagement, and involvement. But, at least until {{3}} , the predominant demand in this {{4}} has been for some sort of objectivity.', NULL, NULL, NULL, E'1.freedom, 2.inward, 3.recently, 4.century', NULL, NULL),
  ('4731ed4f-0b78-5de3-a8e6-e6631d496933'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4731ed4f-0b78-5de3-a8e6-e6631d496933'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the hardest substance in the human body?', '37a61e0b-b07b-5856-ae0f-14ae3c564c65'::uuid, NULL, NULL, E'Tooth Enamel', NULL, NULL),
  ('4735b0b8-5af0-5606-8481-d29663f82c6e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4735b0b8-5af0-5606-8481-d29663f82c6e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '1d9ef6c4-447d-5ebc-baff-e9e072bdc34a'::uuid, NULL, E'The car he was riding crashed into a train.', NULL, NULL, NULL),
  ('473a311b-cd16-5627-b4a3-6a860a4fab7f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '473a311b-cd16-5627-b4a3-6a860a4fab7f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What clothes are used to hike mountains and are used to keep dry?', '368f3b95-9fae-5e70-8c32-858fe16bb6f8'::uuid, NULL, NULL, E'Outdoor jacket', NULL, NULL),
  ('473a6360-5db8-5592-9354-7a983d8159d2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '473a6360-5db8-5592-9354-7a983d8159d2'::uuid, 1, NULL, TRUE, 0, NULL, E'Asking for Leave', E'You have an appointment and need to leave work early to accompany a relative. How do you request permission from your employer for early departure? What key points should you address to ensure your request is understood and approved?', '1107d1bf-bdc4-5a32-bb1a-05a5df0099b0'::uuid, NULL, NULL, NULL, NULL, NULL),
  ('473c3889-5f1d-5264-89bd-94ebe5c5cdef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '473c3889-5f1d-5264-89bd-94ebe5c5cdef'::uuid, 1, NULL, TRUE, 0, NULL, E'Domestication', E'Domestication is an evolutionary, rather than a political development. They were more likely to survive and prosper in an alliance with humans than on their own. Humans provided the animals with food and protection, in exchange for which the animals provided the humans their milk and eggs and yes — their flesh.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('473e413d-6341-5509-8df4-b57e4616de90'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '473e413d-6341-5509-8df4-b57e4616de90'::uuid, 1, NULL, TRUE, 0, NULL, E'Experiential Learning', E'Some people point that experiential learning (i.e. learning by doing) can work well in formal education. However, others think a traditional form of teaching is the best. Do you think experiential learning can work well in high schools or colleges?', NULL, NULL, E'Experiential learning, characterized by its "learning by doing" approach, has sparked a debate on its applicability in formal education. While proponents believe in its efficacy, others contend that traditional teaching methods are superior. In my view, experiential learning can indeed thrive in high schools and colleges due to its practicality and engagement-driven benefits.\nFirstly, the practicality of experiential learning is a compelling reason for its effectiveness in formal education. Although both positive and negative impacts of various teaching approaches must be considered, experiential learning has enriched educational experiences in numerous ways. Albert Einstein''s famous quote, "Learning is experience. Everything else is just information," underscores the value of active engagement. Through hands-on activities, students grasp complex concepts and develop critical thinking skills that are essential for real-world problem-solving.\nMoreover, experiential learning offers unmatched engagement, a factor crucial for modern education. Traditional methods might struggle to maintain student interest and motivation. Conversely, experiential learning, involving interactive projects, fieldwork, and simulations, captivates learners by connecting theoretical knowledge to practical application. A recent study reported by the Journal of Applied Psychology revealed that students who engaged in experiential learning demonstrated higher levels of motivation and learning retention.\nIn conclusion, experiential learning can undoubtedly flourish in high schools and colleges, driven by its practicality and engagement-driven benefits. To address this issue, educational institutions should adopt a balanced approach that incorporates experiential learning alongside traditional teaching methods. By doing so, we can harness the advantages of both approaches and create a more holistic and effective learning environment that prepares students for the complexities of the modern world.', NULL, 200, 300),
  ('4740b78e-ef21-50b8-b6fe-85470951a0c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4740b78e-ef21-50b8-b6fe-85470951a0c8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call the vehicle used in combat with heavy armor and typically armed with a large cannon?', 'ec3d87fb-5fc8-5237-8c29-b86314809134'::uuid, NULL, NULL, E'Tank', NULL, NULL),
  ('47448461-01a6-5064-ab85-12d130a4a5a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '47448461-01a6-5064-ab85-12d130a4a5a6'::uuid, 1, NULL, TRUE, 0, NULL, E'Science and Technology', E'Science and technology are constantly advancing, pushing the boundaries of what we thought was possible and opening up new possibilities for innovation and discovery. From gene editing to quantum computing to space exploration, these fields require collaboration between researchers from different disciplines and sectors.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('474789b1-b88c-50ff-be44-d4789207f5a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '474789b1-b88c-50ff-be44-d4789207f5a6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b7ebe348-db24-5174-ad79-fb48d38918f6'::uuid, NULL, E'You can add a salad to your meal.', NULL, NULL, NULL),
  ('47487002-cda6-5216-b2de-b3b21c95c811'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '47487002-cda6-5216-b2de-b3b21c95c811'::uuid, 1, NULL, TRUE, 0, NULL, E'Unwilling to Do', E'People sometimes should do things they aren’t willing to do. Discuss whether you agree with this statement or not.', NULL, NULL, NULL, NULL, 200, 300),
  ('474d4ac7-2371-5d7d-b8ec-d838f472c0f3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '474d4ac7-2371-5d7d-b8ec-d838f472c0f3'::uuid, 1, NULL, TRUE, 0, NULL, E'Leo in Relationships', E'In relationships, Leo individuals are passionate and generous partners. They bring excitement and vitality to their romantic connections, making every moment feel like an adventure. Leo individuals value loyalty and admiration from their partners and seek relationships that allow them to shine and be appreciated. However, their need for constant attention and validation can sometimes create challenges in relationships, as they may require their partner''s undivided adoration.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('474db1d8-4bbf-5813-aff8-fdc05ec85f60'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '474db1d8-4bbf-5813-aff8-fdc05ec85f60'::uuid, 1, NULL, TRUE, 0, NULL, E'Online Learning', NULL, NULL, NULL, NULL, E'1, 3, 4, 2', NULL, NULL),
  ('474f282d-99d6-5294-aa36-67132b213389'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '474f282d-99d6-5294-aa36-67132b213389'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bc0e5d41-7c5b-523c-b1ac-7bbca8d65a4b'::uuid, NULL, E'He started his tutorial presentation right on time.', NULL, NULL, NULL),
  ('4750ec89-e38b-5880-9535-6f1c82b6f539'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4750ec89-e38b-5880-9535-6f1c82b6f539'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What can Christmas, Easter and Thanksgiving be called by a joint name?', 'c57fdb4f-3111-5597-ac09-c91e225977f6'::uuid, NULL, NULL, E'Festival', NULL, NULL),
  ('47513c45-7dea-58a8-b660-ffc352d3a920'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '47513c45-7dea-58a8-b660-ffc352d3a920'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '011cfdcc-37b0-5b88-88bc-cbfa38b36f24'::uuid, NULL, NULL, E'There are many different styles of business management.', NULL, NULL),
  ('47545967-b6be-52ba-976c-520185a18d1c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '47545967-b6be-52ba-976c-520185a18d1c'::uuid, 1, NULL, TRUE, 0, NULL, E'Episodic Memory', E'Humans don’t use the same type of memory to recall the capitals of the world as they do to {{1}} back to a visit to a friend’s house the {{2}} week. The {{3}} , which allows people to revisit past personal experiences in their minds, is known as “episodic memory,” and was once thought to be {{4}} to humans.', NULL, NULL, NULL, E'1.flash, 2.prior, 3.latter, 4.exclusive', NULL, NULL),
  ('47605a88-e276-5996-a125-90c686feac3d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '47605a88-e276-5996-a125-90c686feac3d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the set of ethical principles that govern a person''s behavior or the conduct of an activity?', '9d275914-19c5-5bda-bd6b-de33460f675d'::uuid, NULL, NULL, E'Morality', NULL, NULL),
  ('47651c7e-75b6-514c-a706-b1c4e30b44c7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '47651c7e-75b6-514c-a706-b1c4e30b44c7'::uuid, 1, NULL, TRUE, 0, NULL, E'Quantum Computing', NULL, NULL, NULL, NULL, E'4, 2, 1, 3', NULL, NULL),
  ('4767f750-2bfa-5ba3-88d2-3a832b267634'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '4767f750-2bfa-5ba3-88d2-3a832b267634'::uuid, 1, NULL, TRUE, 0, NULL, E'The Internet', E'By 1984, the internet had grown to include 1,000 host computers. The National Science Foundation was one of the first outside institutions hoping to connect to this body of information. Other government, non-profit, and educational institutions followed. Initial attempts to catalogue this rapidly expanding system of networks were simple. Among the first was Archie, a list of FTP information created by Peter Deutsch at McGill University in Montreal. However, the greatest innovation in the Internet was still to come, brewing in an MIT laboratory in Cambridge, Mass. The World Wide Web, or the Web, is often confused with the Internet. In fact, it is just one part of the Internet, along with email, video conferencing, and streaming audio channels. In 1989, Tim Berners-Lee, now a scientist at the Massachusetts Institute of Technology, introduced a new system of communication on the Internet which used hyperlinks and a user-friendly graphical interface. His slice of the Internet pie camera to be known as the World Wide Web. Berners- Lee says, “The Web is an abstract (imaginary) space of information. On the Net, you find computers –on the Web, you find documents, sounds, videos, ...information. On the Net, the connections are cables between computers; on the web, connections are hypertext links. The Web exists because of programs which communicate between computers on the Net. The Web could not be without the Net. The Web made the Net useful because people are really interested in information (not to mention knowledge and wisdom!) and don’t really want to know about computers and cables.”', NULL, NULL, E'The National Science Foundation with other government, non-profit, and educational institutions hope to connect to the Internet, with initial attempts to catalogue including Archie, a list of FTP information created by Peter Deutsch at McGill University in Montreal, The World Wide Web, or the Web, which is an abstract space of information.', NULL, 5, 75),
  ('476959cf-b6be-5c9f-a4d5-ffbfb4f77cc3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '476959cf-b6be-5c9f-a4d5-ffbfb4f77cc3'::uuid, 1, NULL, TRUE, 0, NULL, E'Book Structure', E'Any writer must decide upon an order and a structure for a book in keeping with the reflexive nature of the work. There are strong currents of reiteration in the book, with each iteration developing understandings of research, theory, and practice as the story continues to unfold.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('4769c374-451f-5908-960f-a8d2bcc3af54'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4769c374-451f-5908-960f-a8d2bcc3af54'::uuid, 1, NULL, TRUE, 0, NULL, E'Rites of Passage', E'Rites of passage are one deep avenue to experience this love in our bones. Once realized, the care for the earth, the connection and experience of nature, and our part and place in the whole, will inform our future, our care for all of life. Without this care, and a true understanding of interdependence, our actions and lives may well be fragmented, divisive, and destructive.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('476c3528-2192-5b19-9de1-3a3732a66093'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '476c3528-2192-5b19-9de1-3a3732a66093'::uuid, 1, NULL, TRUE, 0, NULL, E'Physical Activity', E'Participating regularly in physical activity has been shown to benefit an individual''s health and {{1}} . Regular physical activity is important in reducing the risk of {{2}} diseases, such as heart disease and stroke, obesity, diabetes and some forms of cancer. The National Physical Activity Guidelines for Adults {{3}} at least 30 minutes of moderate-intensity physical activity, {{4}} every day of the week, to {{5}} health benefits.', NULL, NULL, NULL, E'1.wellbeing, 2.chronic, 3.recommends, 4.preferably, 5.obtain', NULL, NULL),
  ('477593bf-9f48-5c0f-9a51-c35581bc5f36'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '477593bf-9f48-5c0f-9a51-c35581bc5f36'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9488d9a7-05af-5719-9154-dcb24f5507b2'::uuid, NULL, NULL, E'Financial help for undergraduate study is available on application.', NULL, NULL),
  ('477b280e-6ef7-5e43-aba1-dde8729cf70d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '477b280e-6ef7-5e43-aba1-dde8729cf70d'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-R', E'Although scientists observe that an organism''s behavior falls into rhythmic patterns, they disagree about how these patterns are affected when the organism is transported to a new environment. One experimenter, Brown, brought oysters from Connecticut waters to Illinois waters. She noted that the oysters initially opened their shells widest when it was high tide in Connecticut, but that after fourteen days their rhythms had adapted to the tide schedule in Illinois. Although she could not posit an unequivocal causal relationship between behavior and environmental change, Brown concluded that a change in tide schedule is one of several possible exogenous influences (those outside the organism) on the oysters'' rhythms. Another experimenter, Hamner, however, discovered that hamsters from California maintain their original rhythms even at the South Pole. He concluded that endogenous influences (those inside the organism) seem to affect an organism''s rhythmic behavior.\n\nAll of the following could be considered examples of exogenous influences on an organism EXCEPT the influence of the __ .', NULL, NULL, NULL, E'level of a hormone on a field mouse’s readiness for mating', NULL, NULL),
  ('477b4fd6-250a-586b-a464-3b504d47a61f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '477b4fd6-250a-586b-a464-3b504d47a61f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b190129f-9848-5d86-bf14-9028d2e8cee2'::uuid, NULL, E'She was in England for the publication of her new book.', NULL, NULL, NULL),
  ('477b5d73-3e3f-53fb-8451-c0c84a784644'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '477b5d73-3e3f-53fb-8451-c0c84a784644'::uuid, 1, NULL, TRUE, 0, NULL, E'Continuing Resolution', E'The so-called continuing resolution keeps the government funded until 8 February in the hope that Congress can reach a longer-term budget agreement in the meantime. Thousands of federal employees who had been placed on temporary, unpaid leave since Saturday breathed a sigh of relief.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('477d9d6d-33bc-5942-8487-39daf9d8dace'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '477d9d6d-33bc-5942-8487-39daf9d8dace'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do people wear if they can''t see very well?', '01b7c99b-b670-5f16-b2b7-26a387f7bd81'::uuid, NULL, NULL, E'Glasses / contact lenses / spectacles', NULL, NULL),
  ('478be7c7-320e-5f38-9de6-9ce91ac2f31a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '478be7c7-320e-5f38-9de6-9ce91ac2f31a'::uuid, 1, NULL, TRUE, 0, NULL, E'Addressing Pet Care', E'You''ve entrusted a friend to take care of your pet while you''re away, but when you return, you find your pet''s food bowl empty, the water dish dirty, and your pet visibly stressed. You need to address this with your friend. What would you say to your friend?', '9e0a4949-f992-57cf-80b9-8b360e336b25'::uuid, NULL, E'Hey, I noticed my pet seemed stressed and the food and water dishes weren''t as I expected upon my return. I appreciate your help, but I''m concerned about their well-being. Maybe next time, we could set reminders for feeding and cleaning? Or if it''s too much, I understand and can arrange alternative care. Let''s find a solution that works for both of us and ensures my pet''s happiness and health.', NULL, NULL, NULL),
  ('478ebac8-8139-53ac-81fd-9ca3459c65ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '478ebac8-8139-53ac-81fd-9ca3459c65ca'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a9c0ad5d-f9e2-516b-bf64-b31a7f2b5522'::uuid, NULL, E'It is very important to wear masks during this pandemic.', NULL, NULL, NULL),
  ('47943d25-c2a6-543a-9a5f-180b7e1a78a9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '47943d25-c2a6-543a-9a5f-180b7e1a78a9'::uuid, 1, NULL, TRUE, 0, NULL, E'Genome Structural Variation', NULL, '1eac75ce-cc5e-53a4-8552-a7b537ef1e07'::uuid, NULL, E'But I''m going to focus on today, is really different larger forms of genetic variation involving essentially gains losses and inversions of sequence. so showing here is a 30 in the simple diagram. we have an example of some structural variation operationally defined as events greater than a KB in size. so we have pieces of DNA that sometimes become deleted. we have pieces of DNA that sometimes become duplicated on chromosomes and regions which can be in fact inverted or turned around with respect to another orientation. so this very busy map here represents probably about three years of work in my lab, just to kind of characterize the general pattern of structural variation in eight human genomes. so shown here are different human chromosomes for from African, and for from non-African the distinctions really aren''t that important, but what I''m showing you here, is the presence of insertions deletions and inversions as red as blue red and green and so each line here represents a different human genome that has been analyzed looking for structural variation of events greater than 5,000 base pairs in size, so a couple things you can maybe get from. this is you can see that there''s a lot of genetic variation out there , that is above the level of single base pair change and most of the events that you''re seeing here are essentially inherited , but we now know based on studying roughly about 2,000 human genomes, but there''s a significant fraction of very large events often hundreds of KB in size that are either individually specific or specific to specific families , so this is kind of changing our view of the dynamic nature of the human genome.', NULL, NULL, NULL),
  ('47960b54-87d3-5608-bf08-b3a670930fa2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '47960b54-87d3-5608-bf08-b3a670930fa2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '89dbcf44-9f4c-5851-b81c-016c89525a42'::uuid, NULL, NULL, E'There are places on campus where you can get milk.', NULL, NULL),
  ('4797b55e-5015-5cf5-976c-2bb137b404c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4797b55e-5015-5cf5-976c-2bb137b404c4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c2eb3d70-786b-54f3-ba68-4b247116a3c4'::uuid, NULL, NULL, E'Some people regarded this as eyewash whereas some people asked for the status of their complaints and actions taken.', NULL, NULL),
  ('4799df19-141c-5cbc-a87b-224e5e8f43ad'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4799df19-141c-5cbc-a87b-224e5e8f43ad'::uuid, 1, NULL, TRUE, 0, NULL, E'Social Media', E'Our widespread participation in social media in recent years has led to the emergence of what is termed social media influencers''. These online entrepreneurs are people who have created a positive reputation amongst their followers for providing knowledge or expertise on a particular subject. The brands have seen them as a means of promoting their product or service to thousands and sometimes millions of people.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('479b2da8-cddb-54cf-a65e-e4ef873c25ec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '479b2da8-cddb-54cf-a65e-e4ef873c25ec'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we usually call a person who is receiving medical treatment in a hospital?', 'b6e09d51-37a5-5c0e-bd05-7016c306824b'::uuid, NULL, NULL, E'Patient / patients', NULL, NULL),
