  ('479c4c63-69dc-55fb-b787-1ddc26bdaf1e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '479c4c63-69dc-55fb-b787-1ddc26bdaf1e'::uuid, 1, NULL, TRUE, 0, NULL, E'Teachers', E'Teachers should be paid according to how much their students learn. Do you agree or not? Support your ideas with details.', NULL, NULL, NULL, NULL, 200, 300),
  ('479ec59a-7266-5ca9-840a-8257945aab52'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '479ec59a-7266-5ca9-840a-8257945aab52'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '20983b65-12ac-59ac-86b0-26ae5cf243a9'::uuid, NULL, E'It takes a lot of practice to master a foreign language.', NULL, NULL, NULL),
  ('47a2264d-1a1e-533f-8ee5-7271a05c041e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '47a2264d-1a1e-533f-8ee5-7271a05c041e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '028aca89-884f-5176-8354-053cc0accb19'::uuid, NULL, E'Essays should be typed with double spacing on white paper.', NULL, NULL, NULL),
  ('47b32749-89f8-5ce0-a806-eb60b7a5e67e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '47b32749-89f8-5ce0-a806-eb60b7a5e67e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9880ca54-8bec-5537-b7a9-85b2a778d020'::uuid, NULL, NULL, E'The chemistry building is actually being built.', NULL, NULL),
  ('47b59d7f-2ebc-5c87-8076-bdc04909f027'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '47b59d7f-2ebc-5c87-8076-bdc04909f027'::uuid, 1, NULL, TRUE, 0, NULL, E'Robots-manned Space Station', E'Robots manning a space station might read like science fiction, but this could be a reality sooner than later. NASA has already been testing robots called ‘Astrobee’, which work on the International Space Station (ISS). These three cube-shaped free-flying robots began working independently alongside astronauts on the space station.\nOne reason why robots will be critical to future space station missions is that these stations will be located at quite a distance from Earth. For context, ISS orbits the Earth at an altitude of approximately 400 kilometres above the surface of Earth where distance in communication is not an issue. But in contrast, NASA’s proposed Gateway space station will orbit the Moon, which is an average of 384,400 kilometres away from our planet. In such scenarios, robots could solve many of the problems.\nBut getting the robots to work in space is not so easy – even though they might work perfectly fine in the labs as NASA’s experience with Astrobee showed. “The environment on ISS is pretty dynamic. Things change day to day with bags moving, and lighting conditions changing. This made it difficult for the robot to navigate the environment. We had to redesign a lot of the software and algorithms that go into this vision-based navigation and ultimately, we got it right,” said Jose Benavides, project manager for the Astrobee project at NASA.', NULL, NULL, NULL, NULL, 5, 75),
  ('47ba5a15-a9c3-5635-a739-f1efb7f3b42c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '47ba5a15-a9c3-5635-a739-f1efb7f3b42c'::uuid, 1, NULL, TRUE, 0, NULL, E'Amara Jones', E'Amara Jones'' story is one of resilience and fortitude. Born into a family of sharecroppers in the Mississippi Delta, she faced the {{1}} realities of poverty and social inequality from a young age. Despite these challenges, Amara became a beacon of {{2}} for her community. Her memoir, "Roots of Resistance," is a poignant {{3}} of struggle and triumph, detailing how she overcame {{4}} to become an influential voice for justice and equity.', NULL, NULL, NULL, E'1.harsh, 2.hope, 3.account, 4.barriers', NULL, NULL),
  ('47c694a8-7e7b-5bb9-9217-8f71a628f3fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '47c694a8-7e7b-5bb9-9217-8f71a628f3fe'::uuid, 1, NULL, TRUE, 0, NULL, E'Social Isolation', E'Sound depressing, even apocalyptic? Well, it could be the future. If government {{1}} are right, about 20 years from now, two out of five households will be single {{2}} . And there is evidence the situation is already {{3}} . According to a report, Social Isolation in America, published in the American Sociological Review in 2006, the average American today has only two close friends. Twenty-five per cent of those surveyed said they do not have anyone to talk with about important things—And yet, while some are {{4}} a crisis in our ability to make friends, others are saying exactly the opposite. For example, MSN''s Anatomy of Friendship Report, published last November, suggests that the average Briton has 54 friends—a {{5}} rise of 64 per cent since 2003.', NULL, NULL, NULL, E'1.forecasts, 2.occupancy, 3.deteriorating, 4.declaring, 5.spectacular', NULL, NULL),
  ('47cbb5ec-339a-5551-80f5-28bcd98d2c1a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '47cbb5ec-339a-5551-80f5-28bcd98d2c1a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd5736539-af32-5d14-9151-a4571c290a2c'::uuid, NULL, NULL, E'The mountain is the boundary between the two countries.', NULL, NULL),
  ('47d5081f-b0d0-5de7-9318-c80fc28f8ba3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '47d5081f-b0d0-5de7-9318-c80fc28f8ba3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2ffc26d1-1c31-543f-9b1b-c4fd0b4739ab'::uuid, NULL, E'We carefully compared the first report with the second looking for any difference.', NULL, NULL, NULL),
  ('47da5c4f-a632-59b8-8043-178e4765aefa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '47da5c4f-a632-59b8-8043-178e4765aefa'::uuid, 1, NULL, TRUE, 0, NULL, E'Inevitable Rhythms', E'The natural world is a testament to the profound and intricate patterns of growth and change that govern all living things. Whether it''s the growth of a towering oak tree or the transformation of a caterpillar into a butterfly, the rhythms of growth and change are embedded in the very fabric of life. One of the most remarkable aspects of growth is its consistency. In the world of plants, seeds germinate, roots take hold, and shoots emerge, all guided by the innate wisdom of nature. Animals, too, undergo predictable stages of development as they progress from infancy to adulthood. These processes are governed by genetic instructions that ensure the survival and reproduction of species. Change is another fundamental aspect of growth. As living organisms grow, they undergo numerous transformations. For example, the seasons bring about dramatic changes in the natural world. Trees shed their leaves in the fall, only to bud new ones in the spring. Animals molt, migrate, and hibernate in response to changing environmental conditions. The concept of metamorphosis, as seen in the transformation of a caterpillar into a butterfly, illustrates the marvels of growth and change. This process involves a series of distinct stages, each with a specific purpose. The caterpillar, a voracious eater, prepares for its final transformation by storing energy and building a chrysalis. Inside the chrysalis, the caterpillar undergoes a remarkable metamorphosis, emerging as a completely different creature with wings that enable it to fly. Ultimately, these patterns of growth and change remind us of the resilience and adaptability of life in the natural world. They highlight the interconnectedness of all living things and the importance of preserving and protecting our environment to ensure the continued growth and evolution of the diverse species that call our planet home.', NULL, NULL, E'The natural world exemplifies profound patterns of growth and change, from the consistent development of plants and animals to transformative processes like seasonal shifts and metamorphosis, illustrating life''s resilience and adaptability, and underscoring the interconnectedness and importance of preserving our environment for the ongoing evolution of diverse species.', NULL, 5, 75),
  ('47daeab9-64cc-5b54-a736-b7d6d2d485da'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '47daeab9-64cc-5b54-a736-b7d6d2d485da'::uuid, 1, NULL, TRUE, 0, NULL, E'Choice of Transportation', E'Choose one transportation vehicle and explain why you think it has changed people’s lives.', NULL, NULL, NULL, NULL, 200, 300),
  ('47dbe840-55be-5525-a5f1-b94d00ed3cfc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '47dbe840-55be-5525-a5f1-b94d00ed3cfc'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call a person who is one hundred years old or more?', 'c5e4f6da-e956-56bb-9246-3d45fc300252'::uuid, NULL, NULL, E'Centenarian', NULL, NULL),
  ('47e55d43-6f59-5d38-933d-f8de4616c692'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '47e55d43-6f59-5d38-933d-f8de4616c692'::uuid, 1, NULL, TRUE, 0, NULL, E'Print Sources', E'Simply put, print sources are sources that have been published in printed format, such as many daily newspapers, magazines, academic or trade journals, books, government reports, etc. Just because an assignment requires the use of print sources doesn’t {{1}} mean that you must have access to the printed copy. Many print sources can be accessed online. The {{2}} feature of print sources is that they may be accessed in printed form, not that you have accessed them in printed form. Regardless of how you access a print source, it is important to pay close attention to their credibility and {{3}} . Just because an article appears in a print publication does not {{4}} its credibility. Let’s now take a closer look at how analyzing the C.R.A.A.P. (currency, relevance, authority, accuracy, purpose) in a print source can help you determine its credibility and suitability.', NULL, NULL, NULL, E'1.necessarily, 2.distinguishing, 3.reliability, 4.ensure', NULL, NULL),
  ('47e6ffa6-e329-5e66-a4df-a68c81d92b20'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '47e6ffa6-e329-5e66-a4df-a68c81d92b20'::uuid, 1, NULL, TRUE, 0, NULL, E'Renting', E'My name is Tonia. My roommate and I are looking for a nice apartment near my college’s campus. We are very quiet and study a lot. I study history, and my roommate studies French. We are very interested {{1}} renting your apartment. We can {{2}} the rent on time because we do a part-time work, too. Some of our friends live in the same building and have recommended your place to us. They mentioned that you are a kind and responsible landlord, and we hope to {{3}} the same positive experience. I would like to {{4}} an appointment to view the apartment in person. Our application form is ready, and we are prepared to proceed with the process quickly. We look {{5}} to hearing from you soon.', NULL, NULL, NULL, E'1.in, 2.pay, 3.have, 4.make, 5.forward', NULL, NULL),
  ('47ebcdc5-5375-5466-bc56-2f85d863708f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '47ebcdc5-5375-5466-bc56-2f85d863708f'::uuid, 1, NULL, TRUE, 0, NULL, E'Feasible Options', E'You''re planning a weekend getaway with friends, and they''re discussing the activities they want to do. However, you realize some of the suggestions might not be feasible due to time constraints or budget limitations. You need to gently guide the conversation towards more realistic options without dampening the excitement. What would you say to your friends?', 'efb15efc-69d5-5003-a803-ccf7fd6ebad7'::uuid, NULL, E'Hey everyone, I''m loving all the ideas for our weekend getaway! Just a heads up, I think some of the activities might be a bit tricky to fit into our schedule or budget. How about we brainstorm some alternative options that are more practical but still super fun? We want to make the most of our time together without stressing about logistics. Let''s keep the excitement going and find the perfect balance of adventure and affordability!', NULL, NULL, NULL),
  ('47f8484e-0610-5143-82f6-32f6aff53f47'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '47f8484e-0610-5143-82f6-32f6aff53f47'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8ab0e568-3ca8-5775-a468-c077bc28c8d7'::uuid, NULL, NULL, E'Information technology has changed the way people study today.', NULL, NULL),
