  ('48263b33-bbdc-5611-af5a-964722e8f272'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '48263b33-bbdc-5611-af5a-964722e8f272'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What literary term is defined as the use of words to imitate sounds?', '6a72d760-c7bc-556d-bab1-55d5ee3a7165'::uuid, NULL, NULL, E'Onomatopoeia', NULL, NULL),
  ('482a3d37-fe21-5b5b-8be4-6769b4f58602'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '482a3d37-fe21-5b5b-8be4-6769b4f58602'::uuid, 1, NULL, TRUE, 0, NULL, E'Historic Preservation', E'Preserving historic buildings and landmarks is not only important for maintaining a community''s identity but also for enhancing economic stability. Historic preservation attracts tourists who are interested in the unique character and history of a place. Visitors are more likely to spend time and money in areas with well-preserved historic buildings, contributing to the local economy.', NULL, NULL, NULL, NULL, NULL, NULL),
