  ('482dbba8-8309-59af-99f1-c08ae340bb00'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '482dbba8-8309-59af-99f1-c08ae340bb00'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1c9ac4bf-d2ae-5fdb-afba-f18f6a921d40'::uuid, NULL, NULL, E'This course is integrated because it has several parts.', NULL, NULL),
  ('4834f603-53a0-5bb0-81cd-919e1d529f26'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '4834f603-53a0-5bb0-81cd-919e1d529f26'::uuid, 1, NULL, TRUE, 0, NULL, E'Feature Films', E'The universality of story Feature films are narratives – they tell stories. Even films based on {{1}} events will fictionalize them in order to produce drama, to telescope time, to avoid being filled up with too many {{2}} characters, or simply to be more entertaining. Even in the current welter of special-effect movies, feature films are usually summarized by their plots - in their first treatment(or outline of the script idea), in the advance publicity, in the TV guide, in reviews, and in conversations. Films may differ from other {{3}} of narrative- literary fiction or television drama, for instance in the medium used and the representational conventions. They do, however, {{4}} with literary fiction and television drama the basic structure and functions of narrative. Much work has been done by researchers in the field known as ''narratology'' on exactly what constitutes the structures and functions of the narrative. Their conclusions are of great use to students of the feature film.', NULL, NULL, NULL, E'1.true, 2.minor, 3.kinds, 4.share', NULL, NULL),
  ('4837d6e5-dcfa-5274-92b1-8a43c41a6adf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4837d6e5-dcfa-5274-92b1-8a43c41a6adf'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '27f19508-32e0-5665-850d-3da7099dd160'::uuid, NULL, E'The medical center is located near the supermarket on North Street.', NULL, NULL, NULL),
  ('483a88b8-6e9e-5a3d-a1d4-4e6c3bed51a7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '483a88b8-6e9e-5a3d-a1d4-4e6c3bed51a7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '90f9234e-aaef-55b5-b07c-1a8d83df20cf'::uuid, NULL, NULL, E'Basketball was created in 1891 by a physician and physical education instructor.', NULL, NULL),
  ('483caf42-4c75-5112-a039-60af08fa5142'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '483caf42-4c75-5112-a039-60af08fa5142'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ac2153d7-b2b0-537b-8f99-147e0b9b33e8'::uuid, NULL, NULL, E'The government should help colleges and universities to grow bigger.', NULL, NULL),
  ('483d63d8-4300-5442-8a2d-4d956dde88e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '483d63d8-4300-5442-8a2d-4d956dde88e1'::uuid, 1, NULL, TRUE, 0, NULL, E'Foam-filled Furniture', E'Foam-filled furniture is very dangerous if it catches fire, and foam quickly produces a high temperature, thick smoke and poisonous gases - including carbon monoxide. Therefore, set levels of fire resistance have been established for new and second-hand upholstered furniture and other similar products.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('48407a8f-4b18-5179-84e2-15ee59f536cb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '48407a8f-4b18-5179-84e2-15ee59f536cb'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5448dad4-5244-5406-9b3f-2e8a7e34f93e'::uuid, NULL, NULL, E'Organization plays an important role in academic literature.', NULL, NULL),
  ('48419c68-272a-5073-97b5-91d334e6ae47'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '48419c68-272a-5073-97b5-91d334e6ae47'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '013064df-863d-5cec-9b32-d8e29f46e193'::uuid, NULL, E'Most people dislike advertisements but appear to be influenced by them anyway.', NULL, NULL, NULL),
  ('4843e4cf-ca26-530a-adf1-815c8cf22f8f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4843e4cf-ca26-530a-adf1-815c8cf22f8f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '95c228ab-5335-5f4f-bab9-4fe74d5d81d0'::uuid, NULL, E'She was faced with an arduous journey into a remote country.', NULL, NULL, NULL),
  ('48441751-f597-544d-8806-28ea29f92a09'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '48441751-f597-544d-8806-28ea29f92a09'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f007da9d-a1cb-598e-b74f-c0f8234eca21'::uuid, NULL, E'If you want your seminar to be postponed, make sure to get permission first.', NULL, NULL, NULL),
  ('48442143-03be-587e-b64a-b56545923a32'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '48442143-03be-587e-b64a-b56545923a32'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3607037c-ccda-567d-8e2a-6bf575a451e1'::uuid, NULL, NULL, E'Science is really important in how we live today.', NULL, NULL),
  ('4844cb86-4584-5689-9dca-294e0aa43126'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '4844cb86-4584-5689-9dca-294e0aa43126'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-R', E'These days you can fit hundreds of books into one e-book reader or smartphone, and this has ledpublishers, writers and readers alike to ask whether this means the death of the printed book and adrastic change in how we read. Or, as some hope and believe, will the electronic book format simplycomplement traditional book publishing?The fact that a book can be downloaded from almost anywhere in the world has blurred the linesbetween author, reader, format and distribution, and this has caused some head-scratching at some of theworld''s biggest publishing companies. Such companies must adapt, and quickly, to the new market; butmany are nervous of the risks and often shareholders are not willing to break new ground.For many writers, however, e-publishing provides new freedoms and opportunities. Many e-books arepublished by writers who do not have a readership through mainstream publishers, and this allowsthem to deal with material that mainstream publishers would consider too controversial or otherwiseunmarketable.The market is very much driven by the consumer, and publishing companies are going to have to dealwith this new situation sooner or later. It is quite a complicated situation, but it doesn''t have to beeither/or. The book as we know it has been around for about 500 years and, once things settle down,there is no reason why the e-book and the traditional printed book should not exist happily side by side.\n\nWhich of the following statements is true according to the text?', NULL, NULL, NULL, E'E-publishing has created new possibilities for writers.', NULL, NULL),
  ('48493a0d-4de9-5445-9b43-0ac019518f5a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '48493a0d-4de9-5445-9b43-0ac019518f5a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '82ac36ba-0969-50e1-ba52-834b0d409b47'::uuid, NULL, E'She ate a sandwich and drank juice.', NULL, NULL, NULL),
  ('484b51ca-fcea-57f7-a2bc-a5e19735c126'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '484b51ca-fcea-57f7-a2bc-a5e19735c126'::uuid, 1, NULL, TRUE, 0, NULL, E'Father''s Role', E'The father''s role in society has changed during the last 20 years, with a trend towards acceptance of a nurturant father who is more involved in child care responsibilities. With the birth of a child, father-child issues may {{1}} from the family in which the father was born and raised. The healthy, {{2}} father is able to put these issues in perspective and resolve them. Thus, bitterness, hostility, or {{3}} from the family of origin does not spill into the immediate family. While fathers contribute to their own psychosocial development, they also have an important impact on their children from infancy {{4}} adulthood. One researcher concludes that fathers who are more involved in infant care giving have infants with greater cognitive development at one year of age than fathers who are less involved in infant care giving. Infants can {{5}} fathers from other adults early.', NULL, NULL, NULL, E'1.resurface, 2.adjusted, 3.resentment, 4.through, 5.distinguish', NULL, NULL),
  ('485063fa-809d-50e1-ad72-ad6a1c0f871f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '485063fa-809d-50e1-ad72-ad6a1c0f871f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e0104e8f-4738-5ad6-a609-ffe54dbf4a68'::uuid, NULL, NULL, E'The award is presented to organizations that are dedicated to biology.', NULL, NULL),
  ('48531adc-4ee8-5c44-a31f-770c104c8f07'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '48531adc-4ee8-5c44-a31f-770c104c8f07'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3c57a50a-88a0-5691-b0e7-95d71793f4f4'::uuid, NULL, NULL, E'Using charts makes it easier to understand numbers and data.', NULL, NULL),
  ('48556c85-7b23-5d08-aeba-bafa61997d67'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '48556c85-7b23-5d08-aeba-bafa61997d67'::uuid, 1, NULL, TRUE, 0, NULL, E'Warming Oceans', E'The impacts of global warming on oceans are significant. One reason sea levels are uneven is that prevailing {{1}} drive ocean currents, distributing water in complex patterns. Water, like land, absorbs heat unevenly, which means {{2}} temperature also becomes uneven across regions. Sea levels of hotter waters rise more clearly because larger {{3}} is needed when water expands with heat. In addition, melting ice from icebergs helps to {{4}} sea levels even further, worsening the effects of climate change.', NULL, NULL, NULL, E'1.winds, 2.ocean, 3.space, 4.raise', NULL, NULL),
  ('48574cae-6bc5-5e5b-b12d-ae1f2f159557'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '48574cae-6bc5-5e5b-b12d-ae1f2f159557'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ecadcb4d-c4f6-5478-875f-0bea51149c21'::uuid, NULL, NULL, E'Many faculty members showed their support for this decision openly.', NULL, NULL),
  ('485895a9-d68a-57bb-94ae-8b7abf1fde08'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '485895a9-d68a-57bb-94ae-8b7abf1fde08'::uuid, 1, NULL, TRUE, 0, NULL, E'Sound Speed', E'The speed of sound (otherwise known as Mach 1) varies with temperature. At sea level on a ''standard day'', the temperature is 59°F, and Mach 1 is approximately 761 mph. As the altitude increases, the temperature and speed of sound {{1}} decrease until about 36,000 feet, after which the temperature {{2}} steady until about 60,000 feet. Within that 36,000 – 60,000 foot range, Mach 1 is about 661 mph. Because of the {{3}} , it is possible for an airplane flying supersonic at high altitude to be slower than a subsonic flight at sea level. The transonic band (the ''sound barrier'') extends {{4}} around Mach 0.8 — when the first supersonic shock waves form {{5}} the wing — to Mach 1.2, when the entire wing has gone supersonic.', NULL, NULL, NULL, E'1.both, 2.remains, 3.variation, 4.from, 5.on', NULL, NULL),
  ('4865faf5-0d1a-5c13-b3ea-b64cabaca183'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4865faf5-0d1a-5c13-b3ea-b64cabaca183'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the main ingredient in bread?', 'fc2ecdea-f151-529d-ab85-61518c4756d3'::uuid, NULL, NULL, E'Flour', NULL, NULL),
  ('48672595-cbad-5993-8799-ebaf2c32ebae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '48672595-cbad-5993-8799-ebaf2c32ebae'::uuid, 1, NULL, TRUE, 0, NULL, E'Desert Ants', NULL, 'daa00334-fa30-56a0-a524-363b5832acdc'::uuid, NULL, E'There comes a time in a desert ant''s life when a piece of food is too large to ignore, but too heavy to lift, and the only way to get it home is to adopt a new style of walking.\nThe long-legged and speedy Cataglyphis fortis normally covers ground with a three-legged stride that moves two legs forwards on one side, and one on the other. For the next step, the insect mirrors the move with its other three legs.\nBut recordings of ants in the Tunisian desert reveal that when faced with oversized lumps of food 10 times their own weight, the forward ''tripod'' walking style is abandoned. Unable to lift the morsels in their mandibles, the ants drag the food backwards instead, moving all six legs independently. "This is the first time we have seen this in any ants," said lead author Sarah Pfeffer at the University of Ulm in Germany.\nThe ants'' long legs already help keep their bodies away from the scorching desert floor and enable them to speed around at up to 60cm per second.\n"Think of Usain Bolt, who has very long legs compared to body size. The desert floor is also very hot, so the further away their bodies are from the surface, the better," said co-author Matthias Wittlinger. The ants have also evolved to function at body temperatures of 50C in a desert where temperatures can soar to 70C. "They’re basically just trying to get out of the heat," he added.', NULL, NULL, NULL),
  ('4870f640-6c6d-5584-8812-58eb76a7bf47'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4870f640-6c6d-5584-8812-58eb76a7bf47'::uuid, 1, NULL, TRUE, 0, NULL, E'Television Viewing', E'Parents need to take control of the television viewing of pre-schoolers and children of early school age. A workable technique is to make a simple but firm weekly plan as to what programs will be permitted and how much time overall may be spent in viewing. Any child''s weekly schedule normally involves a certain amount of time for school, naps, outdoor play and indoor play.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('48783b1d-ff66-57c4-9b04-0fcd019c825a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '48783b1d-ff66-57c4-9b04-0fcd019c825a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the payment of a student''s education by an organization called?', '94938c2d-797a-52f1-833f-35c309f42444'::uuid, NULL, NULL, E'Scholarship / fellowship', NULL, NULL),
  ('4878b721-dbe7-532a-b6d0-b1115eb37d0f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '4878b721-dbe7-532a-b6d0-b1115eb37d0f'::uuid, 1, NULL, TRUE, 0, NULL, E'Footprints', E'The discovery of a set of what look like ancient hominin footprints on the island of Crete could throw our understanding of human evolution into disarray. Received wisdom is that after {{1}} from the chimp lineage, our hominin ancestors were confined to Africa until around 1.5 million years ago. The prints found in Crete, however, {{2}} to a creature that appears to have lived 5.7 million years ago — suggesting a more complex story. More research is needed to confirm what kind of animal made them. However, the prints seem to have been {{3}} by a creature that walked upright, on the soles of clawless feet (rather than on its toes), with a big toe positioned like our own, rather than sticking out sideways like an ape''s. It may yet turn out to have been a {{4}} unknown non-hominin that had evolved with a human-like foot; but the explanatory paper, in the Proceedings of the Geologists'' Association, is not the first to suggest that hominins could have originated in Europe. A few months ago, a team put forward evidence, gleaned from fossils found in Greece and Bulgaria that a 7.2 million-year old ape known as Graecopithecus was in fact a hominin.', NULL, NULL, NULL, E'1.splitting, 2.belonged, 3.made, 4.previously', NULL, NULL),
  ('487a6378-8cc7-590f-b0a7-498d3ef53478'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '487a6378-8cc7-590f-b0a7-498d3ef53478'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '611cf3b9-fee3-5f92-90af-44f6bcddbcf8'::uuid, NULL, NULL, E'Renovation work is currently being undertaken throughout the whole building.', NULL, NULL),
  ('487e95d8-b2de-54a7-93a4-8efeee23e8bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '487e95d8-b2de-54a7-93a4-8efeee23e8bd'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '778f89e1-6a42-526a-b5c3-fc8fe086abf1'::uuid, NULL, E'Your son has a bad cold and is in the nurse''s room.', NULL, NULL, NULL),
  ('487f0ecb-3fee-5743-845e-7d9914b15c2d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '487f0ecb-3fee-5743-845e-7d9914b15c2d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do we measure the force or pressure of the atmosphere?', '87596b13-788d-5aa6-80a1-4bb3f4dff993'::uuid, NULL, NULL, E'Barometer', NULL, NULL),
  ('4884d87a-dccb-584d-8b8a-faa97f126b1c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4884d87a-dccb-584d-8b8a-faa97f126b1c'::uuid, 1, NULL, TRUE, 0, NULL, E'Shared Study Space', E'You manage a small local library and have arranged a space within it for community members to study and work. Upon a routine check, you find that the area is cluttered with personal items left behind. You need to address this issue with the community members. What would you say to the community members?', 'b3d96b24-24fe-5346-b5bf-c78a849333e2'::uuid, NULL, E'I wanted to talk about the condition of our shared study space in the library. This area is a valuable resource for our community. To maintain its usefulness and ensure it remains welcoming for everyone, I kindly ask that you please clean up after yourselves, respect the furniture, and keep the space tidy. Your cooperation is greatly appreciated in keeping our library a conducive place for learning and collaboration. Thank you for your understanding and help.', NULL, NULL, NULL),
  ('488b0e5c-1b06-560e-a555-fb7c0b754133'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '488b0e5c-1b06-560e-a555-fb7c0b754133'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'cd904b09-c046-5233-8302-3ee59a07cccf'::uuid, NULL, NULL, E'The thief visited homes of several people every day.', NULL, NULL),
  ('489b1041-fc98-579b-b380-bd58abbbce3b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '489b1041-fc98-579b-b380-bd58abbbce3b'::uuid, 1, NULL, TRUE, 0, NULL, E'Takeaway Meals', NULL, NULL, NULL, NULL, E'1, 2, 3, 5, 4', NULL, NULL),
  ('489ffd81-6090-5d7c-8fa6-2dca6923ad6d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '489ffd81-6090-5d7c-8fa6-2dca6923ad6d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name for the shaking of the earth''s surface caused by movement of the earth''s crust?', '39d03fa0-6aeb-5edc-ae53-9949c5198d90'::uuid, NULL, NULL, E'Earthquake', NULL, NULL),
  ('48a19615-67e5-5169-a571-e468cba1a8cb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '48a19615-67e5-5169-a571-e468cba1a8cb'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e6d7aa41-eb24-5c05-a2b6-7e710a22767b'::uuid, NULL, NULL, E'The secretary of state is presently considering the proposal.', NULL, NULL),
  ('48a21cd6-3885-5c7c-9f7e-b79236383cc4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '48a21cd6-3885-5c7c-9f7e-b79236383cc4'::uuid, 1, NULL, TRUE, 0, NULL, E'Power', NULL, '2f6d1896-ca64-5960-a38f-b44150c78bf2'::uuid, NULL, E'Sometimes ignorance is preferable to the detailed truth. Maybe, we only care about truth in so far as it empowers us: knowing and thinking about all of the details of every orange tree would just be a psychological burden for the most of us. I’ll take illusion over the reality. But I can’t help but ask, “Is it possible that the mind is actually accessing a deeper kind of truth?” Maybe, the mind is separating the signal from the noise. But, what constitutes signal versus noise? Our values. A farmer that values knowing all the details of an orange tree will view it differently than a regular person. Well, where do our values come from? Here’s Nietzsche’s view from Beyond Good and Evil: “Behind all logic and its seeming sovereignty of movement, there too stand valuations or, more clearly, physiological demands for the preservation of a certain type of life.” For Nietzsche, our values come from our physiological demands, and what does our physiology demand? Power. It wants to survive and thrive. What does it mean to thrive? To imagine the world a certain way and to be able to make that illusion a reality. Someone could try to contest this idea, by saying that they don’t seek power or want to thrive, they won’t eat or drink anything to prove this point. But, they would “still” be seeking a kind of power, they imagine a world in which they prove the idea wrong and they seek to bring “that” world into fruition, even at their own expense.', NULL, NULL, NULL),
  ('48a735b5-808b-52e3-9710-cec4b50c6268'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '48a735b5-808b-52e3-9710-cec4b50c6268'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ba5d8770-e26c-5d92-a466-47d87770e546'::uuid, NULL, NULL, E'Your role was principally involved in development of new chemical processes.', NULL, NULL),
  ('48a86e53-f32a-505b-b2e6-67be4fd224b4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '48a86e53-f32a-505b-b2e6-67be4fd224b4'::uuid, 1, NULL, TRUE, 0, NULL, E'Lionfish', E'A lionfish can expand its stomach more than 30 times in volume when eating a large meal. It''s also capable of long-term fasting, and can go without food for more than 12 weeks without dying. It doesn''t help matters that lionfish start reproducing when they are less than 1 year old and can lay up to 30,000 eggs every four days, and have very few natural predators.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('48a90407-e862-5226-90d2-f371fc255d3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '48a90407-e862-5226-90d2-f371fc255d3c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for a set of moral principles or values held by a person or society?', '8018a94a-6e8b-543e-9545-e969b8134717'::uuid, NULL, NULL, E'Ethics', NULL, NULL),
  ('48acc713-efc0-507d-9f1b-fb1c606fc8ec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '48acc713-efc0-507d-9f1b-fb1c606fc8ec'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9ccac1ea-fbc7-51d7-a2c3-ca54e9070865'::uuid, NULL, E'This teaching method provides the opportunity for students to learn by completing tasks.', NULL, NULL, NULL),
  ('48ad93b6-12ad-5c5a-b743-b0a91b419118'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '48ad93b6-12ad-5c5a-b743-b0a91b419118'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5145be71-1b66-51bd-90f8-90a973d59956'::uuid, NULL, E'Language games are usually intended to encourage students'' interaction.', NULL, NULL, NULL),
  ('48c94cff-db2e-54d9-9d23-2ba20be8c90b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '48c94cff-db2e-54d9-9d23-2ba20be8c90b'::uuid, 1, NULL, TRUE, 0, NULL, E'Digital Forensics', E'Digital forensics has become crucial in solving modern crimes. Just as fingerprints can place a suspect at a crime {{1}} , digital footprints can prove equally telling. Whether it''s through online activity, GPS data, or even smart home devices, digital {{2}} are almost always left behind. Forensic experts in this field are increasingly vital in piecing together these digital puzzles to solve complex {{3}} .', NULL, NULL, NULL, E'1.scene, 2.traces, 3.cases', NULL, NULL),
  ('48cfc6f9-7c67-523f-91d8-5bc3cdfcdfbc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '48cfc6f9-7c67-523f-91d8-5bc3cdfcdfbc'::uuid, 1, NULL, TRUE, 0, NULL, E'Biological Forgetting', NULL, '18ff69ea-ff22-56ba-b72b-e8286ed54e90'::uuid, NULL, E'People forget things every day including experiences, feelings and thoughts.\nWe call this process biological forgetting.\nRemembering is hard for people, and people try to overcome biological forgetting.\nHuman'' memory is not fixed, but it can be reconstructed and shaped by the past.\nSince ancestors, we have always been trying to improve our memory.', NULL, NULL, NULL),
  ('48d2bb6b-2f06-5dc5-9476-342d463e247e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '48d2bb6b-2f06-5dc5-9476-342d463e247e'::uuid, 1, NULL, TRUE, 0, NULL, E'Hookham', E'The booksellers of Hookham and Carpenter (hereafter referred to only as Hookham) were located on New Bond Street in London, and their records span the most politically turbulent decade of the eighteenth-century—the 1790''s. Clients who frequented Hookham were primarily from the aristocratic or gentry classes. In fact, of Hookham''s total buyers, 22% were aristocracy, and 35% of the aristocracy purchased novels. We can also confidently assume that untitled female customers were of gentry income because their addresses were primarily in London''s fashionable ''West End''.\nHookham''s ledgers not only reveal a dramatic increase in the proportion of female purchasers of novels by comparison to earlier studies of provincial women, but they also reveal a remarkable increase in the proportion of female purchases of novels authored by females. Such a marked increase illustrates that Hookham''s leisured female customers were able to buy more novels.\nFurthermore, the fact that these female aristocrats and gentry have accounts under their own name, not their husbands, demonstrates the greater degree of agency and independence that these urban, moneyed women had relative to provincial women. However, because our study does not include an examination of male customers, we are very limited in what claims we can make about whether or not these women behaved according to the cliche that women were the predominant consumers of novels in the eighteenth-century.\nMoreover, while more disposable income and leisure time certainly account for the significant increase in female purchases of novels authored by women in the 1790s, this increase also strongly suggests a desire on the part of women readers to engage in this politically charged decade. Thus, novel-reading provided women readers with the means through which they were able to participate in the male-dominated world of politics. The latter part of our paper will more fully explore this hypothesis in the context of certain recent literary scholars claim that both Gothic and sentimental novels are actively engaged in political debate and discussion.', NULL, NULL, E'The records of booksellers of Hookham and Carpenter span the 1790''s, and clients who frequented Hookham were primarily from the aristocratic or gentry classes, illustrating Hookham''s female customers were able to buy more novels, so the fact demonstrates the greater degree of agency and independence, while more disposable income and leisure time suggest a desire on the part of women readers to engage in this politically charged decade.', NULL, 5, 75),
  ('48da96aa-4a9e-5c32-a24d-39504793cd05'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '48da96aa-4a9e-5c32-a24d-39504793cd05'::uuid, 1, NULL, TRUE, 0, NULL, E'Paper Writing', E'Many papers you write in college will require you to include quotes from one or more sources. Even if you don''t have to do it, integrating a few quotes into your writing can add life and persuasiveness to your arguments. The key is to use quotes to support a point you''re trying to make rather than just include them to fill space.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('48dca1c4-939d-5872-9712-e7bf8da102eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '48dca1c4-939d-5872-9712-e7bf8da102eb'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b9e497bf-c573-5364-b73a-099f07a8a332'::uuid, NULL, E'A study skill seminar is on for the students who require assistance.', NULL, NULL, NULL),
  ('48e3966e-00f4-59ee-b4d9-3e001611047b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '48e3966e-00f4-59ee-b4d9-3e001611047b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9a95f773-daef-5c0d-b422-4da8e81b54dd'::uuid, NULL, E'Wearing a mask is one of the best ways to curb the pandemic.', NULL, NULL, NULL),
  ('48e67b00-de1c-5ec3-8c86-c6f2ff122ffd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '48e67b00-de1c-5ec3-8c86-c6f2ff122ffd'::uuid, 1, NULL, TRUE, 0, NULL, E'Concentration', E'Some people argue that young people should concentrate on study or work, but some people think it is better to put energy in activities designed to broaden their experience, such as international travel and volunteering. Discuss with examples or cases.', NULL, NULL, E'In today''s fast-paced world, there is an ongoing debate about whether young people should solely focus on study or work, or if they should also engage in activities aimed at broadening their experience, such as international travel and volunteering. While some argue that academic and professional pursuits should take precedence, I firmly believe that investing energy in diverse experiences can greatly benefit young individuals.\nOne compelling reason to support the positive standpoint is that engaging in activities like international travel and volunteering can help young people develop invaluable interpersonal skills and cultural awareness. By immersing themselves in different cultures and interacting with people from diverse backgrounds, individuals can enhance their ability to communicate effectively, build relationships, and navigate unfamiliar situations. These skills are not only beneficial for personal growth but also highly valued in today''s globalized world, where cross-cultural collaboration is increasingly prevalent.\nFurthermore, international travel and volunteering provide unique opportunities for personal growth and self-discovery. Stepping outside one''s comfort zone and experiencing different environments can foster resilience, adaptability, and a broader perspective on life. Through travel, young people can gain a deeper understanding of themselves, their values, and their aspirations. Volunteering, on the other hand, allows individuals to contribute to meaningful causes and make a positive impact on communities in need. These experiences can instill a sense of purpose and fulfillment, shaping young people into compassionate and socially responsible individuals.\nIn conclusion, while some argue that young people should solely concentrate on study or work, I firmly believe that engaging in activities designed to broaden their experience, such as international travel and volunteering, can be immensely beneficial. These experiences not only foster interpersonal skills and cultural awareness but also provide opportunities for personal growth and self-discovery.', NULL, 200, 300),
  ('48e8ed5b-0688-55a7-8f36-17fd815c4ce0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '48e8ed5b-0688-55a7-8f36-17fd815c4ce0'::uuid, 1, NULL, TRUE, 0, NULL, E'Cannibalism', E'Many animals eat their parents, siblings, and {{1}} for different reasons. Cannibalism has a bad rap, but the more scientists learn about it, the more they {{2}} it''s a vital part of nature. The {{3}} of eating one''s own kind is wildly common across the animal kingdom. It''s most often observed in invertebrates and fish, but cannibalism {{4}} in every major animal group.', NULL, NULL, NULL, E'1.offspring, 2.discover, 3.practice, 4.occurs', NULL, NULL),
