  ('49345a53-2452-528a-b44b-eb5ae9cf1b87'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '49345a53-2452-528a-b44b-eb5ae9cf1b87'::uuid, 1, NULL, TRUE, 0, NULL, E'Serpentinite', E'Case studies on the deformation of serpentinite tunnels are not hit in the Web of Science database, {{1}} severe deformation has been {{2}} at soft rock tunnels worldwide, and many papers have been published. The lack of publication may indicate that tunnel excavation in serpentinite is difficult, and thus excavation without professional guidance should be {{3}} .', NULL, NULL, NULL, E'1.although, 2.experienced, 3.avoided', NULL, NULL),
