  ('494e2fbd-a983-5a85-a7e3-fec0320cfff4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '494e2fbd-a983-5a85-a7e3-fec0320cfff4'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which month is the Christmas in?', '17b211d2-6ba8-5790-bae7-382a9836f6d8'::uuid, NULL, NULL, E'December', NULL, NULL),
  ('494fefd9-b3d5-50c3-8e33-3fe24c911c10'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '494fefd9-b3d5-50c3-8e33-3fe24c911c10'::uuid, 1, NULL, TRUE, 0, NULL, E'Teenage Daughter', E'Your teenage daughter gets top marks in school, captains the debate team, and volunteers at a shelter for homeless people. But while driving the family car, her text-messages her best friend and rear-ends another vehicle. How can teens be so clever, accomplished, and responsible and reckless at the same time? Easily, according to two physicians at Children''s Hospital Boston and Harvard Medical School( HMS) who have been exploring the unique structure and chemistry of the adolescent brain. The teenage brain is not just an adult brain with fewer miles on it, says Frances E. Jensen, a professor of neurology. It''s a paradoxical time of development. These are people with very sharp brains, but they''re not quite sure what to do with them. In animals, the movement is coordinated by a cluster of neurons in the spinal cord called the central pattern generator( CPG). This produces signals that drive muscles to contract rhythmically in a way that produces running or walking, depending on the pattern of pulses. A simple signal from the brain instructs the CPG to switch between different modes, such as going from a standstill to walking.\n\nAccording to the text, what is the reason teens can be so clever, accomplished and responsible and reckless at the same time in terms of brain activities?', NULL, NULL, NULL, E'They do not know what to do with their very sharp brains.', NULL, NULL),
  ('49523830-36ff-5fd3-95b1-250f33fae668'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '49523830-36ff-5fd3-95b1-250f33fae668'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bfc632a4-63b5-582d-adac-ea7683b4da19'::uuid, NULL, E'The school is widely admired for its excellent teaching quality.', NULL, NULL, NULL),
  ('49549be6-1efa-5c50-a94d-e6635816dcf8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '49549be6-1efa-5c50-a94d-e6635816dcf8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the study of the distribution and abundance of organisms and their interactions with the environment?', '22b2f36c-6946-5082-ae69-5449abfc0687'::uuid, NULL, NULL, E'Ecology', NULL, NULL),
  ('495a3650-c820-5794-ab6a-61bb0098e6e4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '495a3650-c820-5794-ab6a-61bb0098e6e4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '577c7a63-e1e2-5385-b96a-706688e4fd65'::uuid, NULL, NULL, E'Students are required to give their feedback when the term ends.', NULL, NULL),
  ('496312d9-0473-521a-ba87-d8bac4f8eb0b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '496312d9-0473-521a-ba87-d8bac4f8eb0b'::uuid, 1, NULL, TRUE, 0, NULL, E'Saturn Rings', NULL, '1be1a30e-96be-5f2f-b3d2-7e5ff546f81a'::uuid, NULL, E'In the solar system, many planets have rings.\nSaturn''s rings are the most spectacular planetary ring. Consisting of countless particles whose diameters range from microns to meters, these rings orbit the Saturn. in 1610, Galileo was the first man who spotted Saturn''s rings. With his 20-power telescope, Galileo might have mistaken Saturn''s gaseous ring to surmise that the Saturn system was formed of one planet with two moons as satellites. In 1675, Giovanni Cassini determined that Saturn''s "ring" was actually composed of sub-rings with gaps among them. So the number of Saturn''s rings are more than 10. Other planets like Venus, Jupiter, Neptune and Uranus also have rings but not as many as Saturn have. Finally, Scientists have dedicated themselves to study the formation of Saturn rings and claim that these rings are formed by gravitational fields.', NULL, NULL, NULL),
  ('49675cb7-7742-5350-8733-ba74063f126a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '49675cb7-7742-5350-8733-ba74063f126a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b0a239bc-507d-59b8-b22f-919f8667bcdf'::uuid, NULL, NULL, E'While conceiving ideas is desirable, basic issues must first be addressed.', NULL, NULL),
