  ('498de4f3-cebb-5550-a95b-2e32b8d2b670'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '498de4f3-cebb-5550-a95b-2e32b8d2b670'::uuid, 1, NULL, TRUE, 0, NULL, E'Vanilla', E'The uniquely scented flavor of vanilla is second only to chocolate in popularity on the world’s palate. It’s also the second most expensive spice after saffron. But highly labor intensive cultivation methods and the plant’s temperamental life cycle and propagation mean production on a global scale is struggling to keep up with the increasing demand for the product.', NULL, NULL, NULL, NULL, NULL, NULL),
