  ('49943945-ca9c-5565-8976-c5519ab86d38'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '49943945-ca9c-5565-8976-c5519ab86d38'::uuid, 1, NULL, TRUE, 0, NULL, E'American Birth Rates', E'Since its founding, America has enjoyed population growth famously fueled by high immigration rates, but Americans have historically had large families compared to other countries as well. Birth rates today have fallen to their lowest point in history. While birth rates have historically been connected to economic cycles, the present decline is happening during good economic times.', NULL, NULL, NULL, NULL, NULL, NULL),
