  ('49ae2823-2727-5a36-81aa-24297c2ecf83'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '49ae2823-2727-5a36-81aa-24297c2ecf83'::uuid, 1, NULL, TRUE, 0, NULL, E'Case Approach', E'It was found that while many companies express interest in Jacobson''s use case approach, actual scenario usage often falls outside what is described in textbooks and standard methodologies. Users therefore face significant scenario management problems not yet addressed adequately in theory or practice, and are demanding solutions to these problems.', NULL, NULL, NULL, NULL, NULL, NULL),
