  ('49c0c8cb-a7c2-5cb0-a7b8-a6c249ccda5f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '49c0c8cb-a7c2-5cb0-a7b8-a6c249ccda5f'::uuid, 1, NULL, TRUE, 0, NULL, E'Pets', E'Many people have a close relationship with their pets. These people treat their birds, cats, or other animals as members of their family. In your opinion, are such relationships good? Give examples to support your idea.', NULL, NULL, NULL, NULL, 200, 300),
