  ('49eead7b-11cd-5a60-b36f-bea40645e7a0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '49eead7b-11cd-5a60-b36f-bea40645e7a0'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for the healthcare professional who examines and treats disorders of the feet?', '771f128e-ec66-5626-bc37-6f79e76e1490'::uuid, NULL, NULL, E'Podiatrist', NULL, NULL),
