  ('49f05b7d-63c3-5a8d-8e6c-15535c5b5313'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '49f05b7d-63c3-5a8d-8e6c-15535c5b5313'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3af80106-c7aa-5d00-87d5-959e42fc81f1'::uuid, NULL, NULL, E'A consensus on climate change exists among many esteemed scientists.', NULL, NULL),
  ('49f208b0-4c4a-5449-a9c2-1f57892f38d1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '49f208b0-4c4a-5449-a9c2-1f57892f38d1'::uuid, 1, NULL, TRUE, 0, NULL, E'Cell Maps', E'An international team of scientists has charted the genetic, cellular, and structural composition of both the human brain and the brains of non-human primates. This comprehension of brain structure facilitates a more profound understanding of the cellular underpinnings of brain functions and malfunctions, which can help to create more precise therapeutic treatments for individuals with mental illnesses and other brain disorders.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('49f2ca32-147a-5716-80ff-4b7f12c39b9b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '49f2ca32-147a-5716-80ff-4b7f12c39b9b'::uuid, 1, NULL, TRUE, 0, NULL, E'Kenya', E'It is believed that Cushitic-speaking people were the first ethnic group to migrate to today’s Kenya. It is believed that they moved in from northern Africa somewhere around 2000 BCE. Then came the Arab Traders who started frequenting the Kenyan coast way back in the first century CE (Common Era). The Kenyan coast served host to communities of iron workers, subsistence farmers, hunters and fishermen who supported the economy with agriculture, fishing, metal production and trade with foreign countries.\n\nWhich of the following statements is not true with reference to Kenya?', NULL, NULL, NULL, E'Cushitic speaking people moved into today’s Kenyan territory around 2000 years ago.', NULL, NULL),
  ('49f33696-416e-5c13-9579-40e610face09'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '49f33696-416e-5c13-9579-40e610face09'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'dd6ed522-ca26-5c28-9571-83d7d105823e'::uuid, NULL, E'For further details about trips, please check the student newspaper''s latest issue.', NULL, NULL, NULL),
  ('49f814be-faee-571c-9d9f-c1501e166e02'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '49f814be-faee-571c-9d9f-c1501e166e02'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '63694bd6-1c14-52c3-883f-bf28240f2a04'::uuid, NULL, E'The brain requires a constant supply of oxygen to keep it alive.', NULL, NULL, NULL),
  ('49f8b48b-9772-5582-b3a9-48292246a8f4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '49f8b48b-9772-5582-b3a9-48292246a8f4'::uuid, 1, NULL, TRUE, 0, NULL, E'Mental Illness', E'A mental illness is a health problem that significantly affects how a person feels, thinks, behaves, and interacts with other people. People who experience mental illnesses and their family and friends suffer a great deal due to these illnesses. According to the World Health Organization, depression will be one of the biggest health problems worldwide by the year 2020.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('4a0140f7-7613-54b6-a576-3e4aaf9f0c2e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4a0140f7-7613-54b6-a576-3e4aaf9f0c2e'::uuid, 1, NULL, TRUE, 0, NULL, E'Culture Comparison', E'In comparing material with non-material culture - the first being the objects and technologies we create, and the second our customs, beliefs and attitudes - the speaker gives greater emphasis to the material culture. He gives the example of the development of genetic science and the benefits it has brought to mankind , despite a fair amount of opposition.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('4a01a6f4-8f54-58bb-9f18-d04f8caaad5a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4a01a6f4-8f54-58bb-9f18-d04f8caaad5a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8a4f5c68-b8d4-541b-af83-973be5a5a8b1'::uuid, NULL, E'The potential consequences of climate change include an increased risk of flooding.', NULL, NULL, NULL),
  ('4a055df0-41bc-5549-93da-408a7869ee63'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4a055df0-41bc-5549-93da-408a7869ee63'::uuid, 1, NULL, TRUE, 0, NULL, E'Seismology', E'Seismology is the scientific study of earthquakes and the propagation of elastic waves through the Earth or through other planet-like bodies. The field also includes studies of earthquake environmental effects such as tsunamis as well as diverse seismic sources such as volcanic, tectonic, glacial, fluvial, oceanic, atmospheric, and artificial processes such as explosions. A related field that uses geology to infer information regarding past earthquakes is paleoseismology.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('4a0ffdcb-5c3c-5d8f-9956-fa06b91d4c56'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '4a0ffdcb-5c3c-5d8f-9956-fa06b91d4c56'::uuid, 1, NULL, TRUE, 0, NULL, E'Personal Life', E'Nowadays, people who devote too much time to their job leave very little time for their personal and private life. How widespread is the problem? What problem will this shortage of time cause?', NULL, NULL, E'In today''s fast-paced world, people tend to devote an excessive amount of time to their work, leaving them with very little time for their personal life. This has become a significant problem in many countries, and it can have several negative impacts on individuals and society as a whole.\nThe problem of overworking is widespread in many countries. People are working longer hours than ever before, and this has become a norm in many industries. Many employees work overtime to meet deadlines, and some even bring work home, which can lead to stress and burnout. Moreover, the pressure to perform well and meet targets can cause people to neglect their personal life, leading to a lack of work-life balance.\nThe shortage of personal time can cause several problems for individuals and society. From a personal perspective, overworking can lead to physical and mental health problems such as heart disease, stroke, anxiety, and depression. Additionally, it can lead to strained relationships with family and friends and a lack of social life. From a societal perspective, overworking can lead to a decrease in productivity, as people may become less efficient due to fatigue and stress.\nIn conclusion, while the problem of overworking is widespread, it is essential to recognize that working hard can have positive outcomes. However, it is crucial to maintain a healthy work-life balance to avoid the negative impacts of overworking. Employers should also take steps to ensure that their employees are not overworked and provide them with adequate support to maintain their physical and mental well-being.', NULL, 200, 300),
  ('4a102c87-9a19-5890-a6e3-97cf2749f31f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4a102c87-9a19-5890-a6e3-97cf2749f31f'::uuid, 1, NULL, TRUE, 0, NULL, E'Team-building Activity', E'You''ve organized a team-building activity for your colleagues at a local park. However, upon arrival, you notice some team members are not participating actively and seem disengaged. You need to remind everyone of the importance of teamwork and encourage active participation to maximize the benefits of the activity. What would you say to your colleagues?', '287998be-e54c-594f-8f92-217833d03cf8'::uuid, NULL, E'Hey everyone, thanks for joining us for today’s activity! Let''s make sure we''re all actively participating to get the most out of it. Remember, teamwork is key to our success, and by working together, we can achieve great things. Let''s engage in the activities, share ideas, and support each other throughout. Together, we can strengthen our bond as a team and accomplish our goals more effectively. Let''s dive in and make the most of this opportunity!', NULL, NULL, NULL),
  ('4a1c3908-ff26-5822-a016-9e1f85648fba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '4a1c3908-ff26-5822-a016-9e1f85648fba'::uuid, 1, NULL, TRUE, 0, NULL, E'Well-being', E'Life in the UK 2012 provides a unique overview of well-being in the UK today. The report is the first snapshot of life in the UK to be {{1}} by the Measuring National Well-being program and will be {{2}} and published annually. Well-being is discussed in terms of the economy, people and the environment. Information such as the unemployment rate or {{3}} of crimes against the person are presented alongside data on people’s thoughts and feelings, for example, satisfaction with our jobs or {{4}} time and fear of crime. Together, a richer picture on ''how society is doing'' is provided.', NULL, NULL, NULL, E'1.delivered, 2.updated, 3.number, 4.leisure', NULL, NULL),
  ('4a267056-a7dd-53db-a1bc-0ec310bb9552'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4a267056-a7dd-53db-a1bc-0ec310bb9552'::uuid, 1, NULL, TRUE, 0, NULL, E'Chocoholics', NULL, 'a395c0b1-ede6-53b2-9f8e-9ee86a78f9d2'::uuid, NULL, E'Are you a chocolate-lover? Even true chocoholics might not know what their favorite treat has in common with yogurt, cheese, and wine: its flavors come from fermentation. Fermentation is the process of improving a food through the controlled activity of microbes. The food you know as chocolate starts its life as the seeds of football-shaped fruit. Farmers scoop out the seeds and pulp into piles or boxes. The seeds are now called "cacao beans". They ferment for about a week before they''re dried, roasted, and crushed with sugar until smooth and ready to eat. Let''s go back to that fermentation step. Cacao fermentation is a multi-stage process. The first stage involves yeast. Just like the yeast in your beer, yeast in a cacao fermentation produces alcohol by digesting the sugary pulp around the beans. As the pulp breaks down, oxygen seeps in. And oxygen-loving bacteria take over. The bacteria generate acetic acid from the alcohol that the yeast produced. Acetic acid causes biochemical changes as it soaks into the beans, and that has a major impact on flavor. Finally, as the acid slowly evaporates and the sugars are all used up, spore-forming organisms begin to grow. Cacao is a wild fermentation. Farmers rely on natural microbes in their environment to create unique, local flavors.', NULL, NULL, NULL),
  ('4a289280-7d51-574a-ac0a-ccbe2067a357'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '4a289280-7d51-574a-ac0a-ccbe2067a357'::uuid, 1, NULL, TRUE, 0, NULL, E'Ultraprocessed Foods', E'If more than 20% of your daily calorie intake is ultraprocessed foods, however, you may be {{1}} your risk for cognitive decline, a new study found. Ultraprocessed foods are usually high in sugar, salt and fat, all of which {{2}} inflammation throughout the body. But if a person also ate a lot of unprocessed, whole fruits and veggies, whole grains and healthy sources of protein, the association between ultraprocessed foods and cognitive decline {{3}} .', NULL, NULL, NULL, E'1.raising, 2.promote, 3.disappeared', NULL, NULL),
  ('4a344656-db34-5a23-96fa-c9b0c80ac058'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4a344656-db34-5a23-96fa-c9b0c80ac058'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How often are the Olympic Games held?', '203061f4-f5ba-5866-8d55-fc5880389673'::uuid, NULL, NULL, E'Every four years', NULL, NULL),
  ('4a363eb9-2396-53c3-b7de-3ebc8e48328c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '4a363eb9-2396-53c3-b7de-3ebc8e48328c'::uuid, 1, NULL, TRUE, 0, NULL, E'Product Life Cycle', E'A company has to be good at both developing new products and managing them in the {{1}} of changing tastes, technologies, and competition. Products generally go through a life cycle with predictable sales and profits. Marketers use the product life cycle to follow this {{2}} and identify strategies to influence it. The product life cycle starts with the product’s development and introduction, then moves toward {{3}} or eventual demise.', NULL, NULL, NULL, E'1.face, 2.progression, 3.withdrawal', NULL, NULL),
  ('4a36fde5-c3a4-5bdd-b623-b9f8a83fb6bb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4a36fde5-c3a4-5bdd-b623-b9f8a83fb6bb'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '460b8e3c-920a-5d3d-b851-56afdafc158b'::uuid, NULL, NULL, E'There will be a chemistry test in the class next week.', NULL, NULL),
  ('4a3e0afc-bd8d-577c-a18b-4b4a83920096'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4a3e0afc-bd8d-577c-a18b-4b4a83920096'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'bd512f35-d68a-5f14-b9e3-0cb74e9f6020'::uuid, NULL, NULL, E'A further study suggests the opposite of the former theory.', NULL, NULL),
