  ('4a96540c-786f-5c87-9994-6e5b08c62981'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '4a96540c-786f-5c87-9994-6e5b08c62981'::uuid, 1, NULL, TRUE, 0, NULL, E'Sufficient Sleep', E'In our fast-paced modern lives, getting sufficient sleep is often overlooked, yet it {{1}} vital. And also, it is really important that you get enough sleep to stay {{2}} . Adequate sleep allows our body to repair and rejuvenate, keeping our mind sharp. If you {{3}} enough sleep regularly, you may feel drowsy, which {{4}} concentration, saps energy, and even dulls reflexes, making daily tasks a struggle.', NULL, NULL, NULL, E'1.is, 2.rested, 3.lack, 4.impacts', NULL, NULL),
  ('4a990f15-41c1-5c93-82c2-7d6670514480'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4a990f15-41c1-5c93-82c2-7d6670514480'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a tower-like structure providing ventilation?', 'bf65d6d8-1f33-5fc9-824b-788dd03b41ea'::uuid, NULL, NULL, E'Chimney', NULL, NULL),
