  ('4aa63ec4-8540-5b6d-8066-71e968b5acf1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4aa63ec4-8540-5b6d-8066-71e968b5acf1'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bd7b7261-2246-5dd0-b367-3e9e9ebd07de'::uuid, NULL, E'Quality of life is an important measure on which the cities are ranked.', NULL, NULL, NULL),
  ('4aa7b750-856a-54f4-a2ad-46ed04b1ca02'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4aa7b750-856a-54f4-a2ad-46ed04b1ca02'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3ccdb1b3-febc-548c-a2e9-8adbbd2dbb9c'::uuid, NULL, NULL, E'Urban planners plant trees in cities for a better environment.', NULL, NULL),
  ('4aa9bac2-a369-59e0-96df-bac48de9c8f2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4aa9bac2-a369-59e0-96df-bac48de9c8f2'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '57f469cb-9010-5b6c-929e-d0f291bbc580'::uuid, NULL, E'The seminar will now take place once a week on Tuesday.', NULL, NULL, NULL),
  ('4ab611ce-d5f0-5b3a-ae3d-04e12d2478ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4ab611ce-d5f0-5b3a-ae3d-04e12d2478ca'::uuid, 1, NULL, TRUE, 0, NULL, E'Exponential Goals', NULL, 'fd086993-916a-5661-a35c-e96fc22c7cea'::uuid, NULL, E'We know from history that every major industrial disruption has followed the same shape and exponential curve, with new technologies being adopted very slowly at first, but then a doubling rate kicking in consistently until the overall transformation happens very quickly in the end. It’s a movie we’ve seen many times before, whether from horses to cars, from valves to transistors, or landlines to mobile phones. And we understand how it works. Initially, the cost of technology is high but as we learn through volume adoption, the cost goes down and adoption goes up. Best example right now would be electric batteries, consistently coming down in cost by 20% a year for the last 10 years. And as the volume of adoption grows, especially with electric vehicle sales growing, we can be confident that the costs of that technology will continue to go down, driving that exponential growth. We set these exponential goals because we believe in the power of human innovation. Engineers love these goals. They stretch targets. It’s what they live for.', NULL, NULL, NULL),
  ('4ac0481d-a3c9-59e0-b933-6a98b814c98f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4ac0481d-a3c9-59e0-b933-6a98b814c98f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0505175b-c2e0-58ad-8664-b1e1321fbe48'::uuid, NULL, E'Make sure you correctly cite all your sources.', NULL, NULL, NULL),
