  ('4b042932-a6bc-5b05-8561-d329d7c6d2c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4b042932-a6bc-5b05-8561-d329d7c6d2c6'::uuid, 1, NULL, TRUE, 0, NULL, E'Adult Coral', E'Recent research suggests that adult fragments of a coral species exhibit improved tolerance to bleaching and a faster recovery when exposed to symbionts that have evolved to withstand higher temperatures. Interestingly, the study also found that the treatment with these heat-evolved symbionts did not negatively impact the coral''s growth.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('4b048dff-cd90-5683-a6f8-800cea04192d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4b048dff-cd90-5683-a6f8-800cea04192d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '55d4d1fb-27e6-5e87-ab44-95dd9a3d7c30'::uuid, NULL, NULL, E'This study guide helps you achieve your goals on the exam.', NULL, NULL),
  ('4b053616-0d77-50c7-bb56-b171f049f7bf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4b053616-0d77-50c7-bb56-b171f049f7bf'::uuid, 1, NULL, TRUE, 0, NULL, E'Degraded Lands', E'The effects of soil erosion go beyond the loss of fertile land. It has led to increased pollution and sedimentation in streams and rivers, clogging these waterways and causing declines in fish and other species. Degraded lands are also often less able to hold onto water, which can worsen flooding. Sustainable land use can help to reduce the impacts of agriculture and livestock.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('4b0a2bb9-4487-59df-a72c-c075d5fd7fd7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4b0a2bb9-4487-59df-a72c-c075d5fd7fd7'::uuid, 1, NULL, TRUE, 0, NULL, E'Hotter Tropics', E'The tropics are becoming hotter due to a combination of warming associated with deforestation and climate change, and that can reduce the ability of outdoor workers to perform their jobs safely. Researchers are estimating how many safe working hours people living in the tropics have lost due to local temperature change associated with loss of trees.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('4b0b7dd3-4091-59b3-b81e-ba212ff68e2f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4b0b7dd3-4091-59b3-b81e-ba212ff68e2f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '93abff0c-4a09-562b-983c-4d8455fdf3cc'::uuid, NULL, NULL, E'The summer class was not held due to low student numbers.', NULL, NULL),
