  ('4b16c296-7554-578f-936c-b9b4a90f8bd7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '4b16c296-7554-578f-936c-b9b4a90f8bd7'::uuid, 1, NULL, TRUE, 0, NULL, E'Charles Darwin', E'In his theory of natural selection, Charles Darwin suggested that ‘survival of the fittest’ was the {{1}} for organic evolution (the change of living things with time). Evolution itself is a biological phenomenon common to all living things, even though it has led to their {{2}} . Evidence to support the theory of evolution has come {{3}} from the fossil record, and from comparative studies of structure and function.', NULL, NULL, NULL, E'1.basis, 2.differences, 3.primarily', NULL, NULL),
