  ('4b462fc9-d654-5843-a5c6-1decbea33065'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4b462fc9-d654-5843-a5c6-1decbea33065'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5c65d693-8cf2-5680-bef3-d3cbf80bb90f'::uuid, NULL, NULL, E'The professor is giving some detailed information about the following exam.', NULL, NULL),
  ('4b5b82e6-23c6-57d0-8590-acbcd3ffea2c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4b5b82e6-23c6-57d0-8590-acbcd3ffea2c'::uuid, 1, NULL, TRUE, 0, NULL, E'Sleep Schedule', E'Maintaining a consistent sleep schedule is crucial for a good night''s sleep in autumn when daylight hours are shorter and the body''s internal clock can be disrupted. Going to bed and waking up at the same time each day helps regulate your circadian rhythm, allowing your body to anticipate when it''s time to sleep and when it''s time to wake, promoting deeper and more restful sleep.', NULL, NULL, NULL, NULL, NULL, NULL),
