  ('4b7dcfc7-ef79-5949-a2f2-ebd0b15b4945'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '4b7dcfc7-ef79-5949-a2f2-ebd0b15b4945'::uuid, 1, NULL, TRUE, 0, NULL, E'Air Quality', E'While recent data indicates an overall improvement in air quality across the United States, the benefits are not uniformly {{1}} across all communities, highlighting significant environmental injustices. Studies show that marginalized groups, including low-income communities and communities of color, continue to face higher exposure to air pollutants. This {{2}} distribution of air quality improvements can be attributed to various factors, including proximity to industrial areas, traffic density, and limited resources for environmental safeguards in these communities. The situation calls for a reassessment of environmental policies, emphasizing the need to address these disparities and ensure {{3}} access to clean air. The challenge lies in {{4}} targeted measures that address the specific needs of affected communities, while also maintaining the broader goal of nationwide air quality improvement. This issue has drawn attention from policymakers, environmentalists, and public health experts, all advocating for a more inclusive approach to environmental protection and air quality management. As the U.S. continues to make strides in reducing overall pollution levels, the focus is now {{5}} towards ensuring that these advancements benefit all sections of the society equally.', NULL, NULL, NULL, E'1.experienced, 2.uneven, 3.equitable, 4.implementing, 5.shifting', NULL, NULL),
  ('4b7f8581-fbf6-5aec-aaca-a4d1a086eaae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4b7f8581-fbf6-5aec-aaca-a4d1a086eaae'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c6895f68-e12a-579c-a588-a61097aaa421'::uuid, NULL, E'The key to success in the exam is to study hard and do well.', NULL, NULL, NULL),
