  ('4b99b0f4-7db9-53ff-b3e3-fa1569160305'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '4b99b0f4-7db9-53ff-b3e3-fa1569160305'::uuid, 1, NULL, TRUE, 0, NULL, E'Seinfeld Study', E'A team of researchers from the University of Western Ontario in Canada has used the popular sitcom Seinfeld to investigate how the brain responds to different types of jokes. They {{1}} the brain activity of 22 volunteers while they watched clips from the show, and found that different regions of the cortex, the brain’s {{2}} layer, were involved in processing humor. The study revealed that the brain’s left hemisphere was more active when the participants understood the jokes, {{3}} the right hemisphere was more active when they found them funny. The researchers also identified a network of brain regions that were involved in both humor comprehension and appreciation, suggesting that these processes are closely linked. The findings could help improve the {{4}} and treatment of conditions that affect humor perception, such as depression, autism, and dementia.', NULL, NULL, NULL, E'1.monitored, 2.outermost, 3.while, 4.diagnosis', NULL, NULL),
  ('4b9c7111-e1b3-59a7-b238-794be7096a7c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4b9c7111-e1b3-59a7-b238-794be7096a7c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Something that can be eaten is edible. What is something that can be heard?', 'b25517f6-624f-502e-830b-0d9c495ab3c4'::uuid, NULL, NULL, E'audible', NULL, NULL),
  ('4b9dae52-4f9e-5551-8500-8d1a61496a33'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4b9dae52-4f9e-5551-8500-8d1a61496a33'::uuid, 1, NULL, TRUE, 0, NULL, E'Vikings', E'Invaders, pirates, warriors - the history books taught us that Vikings were brutal predators who travelled by sea from Scandinavia to pillage and raid their way across Europe and beyond. Now cutting-edge DNA sequencing of more than 400 Viking skeletons from archaeological sites scattered across Europe and Greenland will rewrite the history book.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('4ba08479-e193-50d7-af5b-ae809342b83b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '4ba08479-e193-50d7-af5b-ae809342b83b'::uuid, 1, NULL, TRUE, 0, NULL, E'AI Narrated Books', E'Apple has launched Apple Books digital narration, which lets publishers automatically create high-quality audio {{1}} by artificial intelligence from written text. On its website, Apple describes the new digital narration feature as a bid to make the creation of audio books more {{2}} to all by slashing the cost and {{3}} of producing them for authors and publishers.', NULL, NULL, NULL, E'1.generated, 2.accessible, 3.complexity', NULL, NULL),
