  ('4bae6361-3dff-523e-ba40-a05ba8727ed7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4bae6361-3dff-523e-ba40-a05ba8727ed7'::uuid, 1, NULL, TRUE, 0, NULL, E'Water on Mars', E'A meteorite that originated from Mars billions of years ago provides insights into past impact events on the red planet. The presence of oxidized minerals from the Martian crust within the meteorite suggests the involvement of water during the impact that formed it. This discovery contributes to a better understanding of the role of water in the formation of planets, bridging some gaps in our knowledge.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('4bb7f514-e5e0-50b8-88bb-f2571515e041'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4bb7f514-e5e0-50b8-88bb-f2571515e041'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8a271d24-202e-5bc2-a721-c7b0408477e8'::uuid, NULL, E'The university''s student support office provides help to students with settling into their early years.', NULL, NULL, NULL),
