  ('4bbcf583-0ea6-5f17-abc3-a6450c5547a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4bbcf583-0ea6-5f17-abc3-a6450c5547a6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '686ef867-47c2-5713-9efb-efd4b7205bcc'::uuid, NULL, NULL, E'Half of television output is given away for educational programs.', NULL, NULL),
  ('4bbd51c9-e7f7-58e0-b116-c43816c8a4a3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '4bbd51c9-e7f7-58e0-b116-c43816c8a4a3'::uuid, 1, NULL, TRUE, 0, NULL, E'Gender Relations in Africa', E'Since the dawn of man, gender relations were not a problem among Africans. People collectively lived with their specified divisions of labour and specializations within the households, where men were in charge of all family matters. Under traditional African families, both men and women had different roles to play in their households. Lives were tied and agreed by the traditional African socio-cultural norms for centuries. Division of labour and specializations maintained and strengthened social relations across gender lens which in turn brought strong families, clans and communities with high mutual respect, honesty, humility and understandings. As such, diversified roles in social, economic and political condition in African traditional setting has never been the cause of problems and hence should not be interpreted as discrimination, persecutions and marginalization of across gender.\nCampaigns from the western world for gender equality have brought serious problems in African traditional setting. What is interpreted as unequal gender relation in Africa was the product of western interpretations caused by the transformations brought to Africa by the colonial relations and western liberal democracies. As a result of misinterpretations of the real African lives from its historical perspectives, modernity and new perceptions implanted to African societies through western educations, democracies, and activism, liberty and freedom concepts have seriously contributed to African dissolution, conflicts and chaos at all levels. This situation has therefore put African generations at the crossroads particularly in upholding their long cherished traditions as they have strongly been opposed and absorbed by modernity and western gender equality conceptions.', NULL, NULL, NULL, NULL, 5, 75),
  ('4bc9c0f4-cec1-58d7-b787-5e83e401116c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4bc9c0f4-cec1-58d7-b787-5e83e401116c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1fd3fe42-fca9-5e15-875a-a8dac3798314'::uuid, NULL, NULL, E'The body fat keeps internal organs warm.', NULL, NULL),
  ('4bca3528-0f6c-5f8c-8f29-0763b7394f4d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4bca3528-0f6c-5f8c-8f29-0763b7394f4d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '83d89b15-2d59-538e-8dec-0e84ae79da88'::uuid, NULL, E'Those suffering from infectious diseases are separated from other patients.', NULL, NULL, NULL),
  ('4bce1020-4c42-5553-87a8-d12c534943ba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '4bce1020-4c42-5553-87a8-d12c534943ba'::uuid, 1, NULL, TRUE, 0, NULL, E'Economic Globalization', E'Economic globalization has been a predominant phenomenon now. What problems may it cause? Please list some of them.', NULL, NULL, NULL, NULL, 200, 300),
  ('4bd00d6a-6e34-5d6a-bfab-867fb66b3f47'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '4bd00d6a-6e34-5d6a-bfab-867fb66b3f47'::uuid, 1, NULL, TRUE, 0, NULL, E'Poison Pills', E'Poison pills were developed in the early 1980s as a defense tactic against corporate raiders to effectively poison their takeover efforts, sort of reminiscent of the suicide pills that spies supposedly swallow if captured. There are many variants of poison pills, but they generally increase the number of shares, which then dilutes the bidder''s stake and causes them a significant financial loss. Let''s say a company has 1,000 shares outstanding valued at $10 each, which means the company has a market value of $10,000. An activist investor purchases 100 shares at the cost of $1,000 and accumulates a significant 10 percent stake in the company. But if the company has a poison pill that is triggered once any hostile bidder owns 10 percent of its stock, all other shareholders would suddenly have the opportunity to buy additional shares at a discounted price, say, half the market price. This has the effect of quickly diluting the activist investor''s original stake and also making it worth a lot less than it was before. Twitter adopted a similar measure. If any shareholder accumulates a 15 percent stake in the company in a purchase not approved by the board of directors, other shareholders would get the right to buy additional shares at a discount, diluting the 9.2 percent stake Musk recently purchased. Poison pills are useful in part because they can be adopted quickly, but they usually have expiration dates. The poison pill adopted by Twitter, for example, expires in one year.', NULL, NULL, NULL, NULL, 5, 75),
  ('4bda0bc1-07b6-54c9-9bec-1de6da05e833'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4bda0bc1-07b6-54c9-9bec-1de6da05e833'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c42ac9df-270b-5b09-b673-ecf51d6bc247'::uuid, NULL, NULL, E'Farming has changed a lot and gotten better over the years.', NULL, NULL),
  ('4be15bab-3781-54d7-a564-cecef6a4df55'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4be15bab-3781-54d7-a564-cecef6a4df55'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'In most university courses there are two ways of being assessed,one is orally,the other is through..?', 'a99d9335-90e2-5d08-82e2-154712f730e6'::uuid, NULL, NULL, E'Written assignment', NULL, NULL),
  ('4be35aca-1633-5cc8-83ae-08eebfd36b7d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4be35aca-1633-5cc8-83ae-08eebfd36b7d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'be11d5a1-6917-5ad0-9853-f1fa8175f601'::uuid, NULL, E'The Japanese recycle more than half of their waste paper each year.', NULL, NULL, NULL),
  ('4be69fdd-0876-583c-8c63-d7c2861dcc49'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4be69fdd-0876-583c-8c63-d7c2861dcc49'::uuid, 1, NULL, TRUE, 0, NULL, E'Race Car Drivers', E'Where the drivers blinked was surprisingly predictable, the team found. The drivers had a shared pattern of blinking that had a strong connection with acceleration, such that drivers tended not to blink while changing speed or direction — like while on a curve in the track — but did blink while on relatively safer straightaways.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('4be7da77-ca7d-5c88-bf7f-588fe9da66cf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4be7da77-ca7d-5c88-bf7f-588fe9da66cf'::uuid, 1, NULL, TRUE, 0, NULL, E'Living on Moon', NULL, 'b1e3eb37-6f8b-5f26-8163-1d7d18589ba0'::uuid, NULL, E'Of course, living on the moon won''t be easy. The camp envisioned is not so much a village as an inhabited research base. Similar to those in places like Antarctica, but there are far greater obstacles to living on the moon than just cold weather. The biggest is cosmic radiation. Unlike the Earth, the moon has no atmosphere and no magnetic field. A person on its surface can receive over 400 times the maximum safe dosage of heavy ion radiation, enough to be fatal within ten hours, even in a spacesuit. The first step would likely involve robots and 3D printers constructing covered habitats from lunar soil, or building shelters inside caves formed by lava tubes from the moon''s volcanic past. But what would the inhabitants live on? Supplies would need to be transported from Earth at first. Growing plants requires greenhouse soil and air rich in carbon dioxide, a gas that''s rare on the moon, but could be synthesized from recycled materials. A water treatment plant could be supplied by ice mined from the polar regions using a specialized drill that can bore two meters beneath the lunar surface. Friendly bacteria and viruses necessary to the human microbiome and immune system would also have to be imported or synthesized on site. And lunar inhabitants would have to exercise for hours a day to maintain bone and muscle mass. That''s because the moon''s gravity is just one-sixth that of the Earth. and the everyday strain of working against gravity is part of what keeps our bodies healthy.', NULL, NULL, NULL),
  ('4bed4c5b-802f-5326-97f5-81fa1c99ec89'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4bed4c5b-802f-5326-97f5-81fa1c99ec89'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the title of a newspaper called?', 'd5a4a73e-d342-5673-b30e-ff32ba978363'::uuid, NULL, NULL, E'Headline', NULL, NULL),
  ('4bef53aa-3591-5466-aea5-ab994a73cbef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4bef53aa-3591-5466-aea5-ab994a73cbef'::uuid, 1, NULL, TRUE, 0, NULL, E'Acknowledgement', E'We acknowledge all the information and memory notes provided by students. We also acknowledge open source from various books and journal articles. All questions and answers are prepared and annotated by the Australian Institute of Language. All rights reserved, not for any commercial purposes, but for personal study only.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('4beff9c8-fea9-5a74-a557-dfd57a715b65'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4beff9c8-fea9-5a74-a557-dfd57a715b65'::uuid, 1, NULL, TRUE, 0, NULL, E'TV Shows', E'One of the benefits of watching the television shows is that you will get to learn and appreciate the different cultures. As a movie enthusiast, you will watch different movies of different actors who originate in different countries. This will give you a wider perspective of the various cultures, and you are likely to appreciate the contribution being made by individuals in different parts of the world.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('4bf06a9c-3664-5a8a-8000-54e57de38b7a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '4bf06a9c-3664-5a8a-8000-54e57de38b7a'::uuid, 1, NULL, TRUE, 0, NULL, E'Biological and Toxin', E'Biological and toxin weapons are either microorganisms produced by living organisms that are produced and {{1}} deliberately to cause disease and death in humans, animals or plants. Biological weapons form a subset of a larger class of weapons sometimes referred to as unconventional weapons or weapons of mass {{2}} . The use of biological agents is a serious {{3}} , and the risk of using these agents in a terrorist attack is thought to be increasing.', NULL, NULL, NULL, E'1.released, 2.destruction, 3.concern', NULL, NULL),
  ('4bf08561-754d-5ac5-b311-0e675f6bda9f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '4bf08561-754d-5ac5-b311-0e675f6bda9f'::uuid, 1, NULL, TRUE, 0, NULL, E'Population Change', E'Populations can change through three processes: fertility, mortality and migration. Fertility {{1}} the number of children that women have and differs from fecundity (a woman''s childbearing potential). Mortality is the study of the causes, consequences and measurement of processes affecting death in a population. Demographers most commonly study mortality using the Life Table, a statistical {{2}} which provides information about the mortality conditions (most notably the life expectancy) in the population. Migration refers to the movement of persons from an origin place to a destination place across some pre-defined political boundary. Migration researchers do not designate movements as migrations, {{3}} they are somewhat permanent. Thus demographers do not consider tourists and travelers to be migrating. While demographers who study migration typically do so through census data on place of {{4}} , indirect sources of data including tax forms and labor force surveys are also important.\nDemography is today widely taught in many universities across the world, {{5}} students with initial training in social sciences, statistics or health studies.', NULL, NULL, NULL, E'1.involves, 2.device, 3.unless, 4.residence, 5.attracting', NULL, NULL),
  ('4bf49aee-2d9c-5fc9-bbe0-47d376e6aecf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '4bf49aee-2d9c-5fc9-bbe0-47d376e6aecf'::uuid, 1, NULL, TRUE, 0, NULL, E'Nature Benefits', E'A new study from the University of Vienna shows that regular {{1}} with nature can have positive effects on mental health, especially for people with lower incomes. The study involved a sample of 2,300 Austrian residents and assessed their well-being and {{2}} with natural environments. The researchers found that spending time in nature can help reduce stress, improve immune system function, enhance cognition, improve sleep quality, and increase life satisfaction. However, these benefits are not {{3}} distributed among different income groups. The study revealed that people with lower incomes {{4}} to have poorer mental health than their wealthier counterparts, but they also benefit the most from contact with nature. According to the study’s lead author, Leonie Fian, the well-being benefits derived from weekly visits to nature throughout the year are comparable to the benefits associated with an annual income increase of 1,000 euros. However, {{5}} living near green areas or water bodies is not enough. Active engagement with these places is necessary.', NULL, NULL, NULL, E'1.encounters, 2.interactions, 3.equally, 4.tend, 5.simply', NULL, NULL),
  ('4bf7fd6c-cda2-5ba8-a2f4-4fe75ad55781'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4bf7fd6c-cda2-5ba8-a2f4-4fe75ad55781'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '00bde07e-49f1-5f9e-93bb-84aeaa0bb286'::uuid, NULL, NULL, E'Aquatic science is the study of ecosystems to increase scientific understanding.', NULL, NULL),
