  ('4ca20f73-2f2c-587c-bbf0-e3a71e8d8b80'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '4ca20f73-2f2c-587c-bbf0-e3a71e8d8b80'::uuid, 1, NULL, TRUE, 0, NULL, E'Canadian Arctic', E'This summer, 41 UBC alumni and friends participated in expeditions to the Canadian Arctic and the legendary Northwest Passage. Presentations, conversations and learning accompanied their exploration of the great {{1}} aboard the Russian-flagged Akademik Ioffe, designed and built in Finland as a scientific research vessel in 1989. Her bridge was open to passengers virtually 24 hours a day. Experts on {{2}} presented on topics including climate change, wildlife, Inuit culture and history, and early European explorers. UBC professor Michael Byers presented on the issue of Arctic sovereignty, a {{3}} cause of debate as ice melts, new shipping routes open, and natural resources {{4}} accessible. Recommended pre-trip reading was late UBC alumnus Pierre Berton''s book, The Arctic Grail.', NULL, NULL, NULL, E'1.outdoors, 2.board, 3.growing, 4.become', NULL, NULL),
  ('4ca6e7f1-0606-5b68-8e09-371c9e27a03f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4ca6e7f1-0606-5b68-8e09-371c9e27a03f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'In which style of swimming do you swim lying on your back?', 'ee42a994-7fa7-5c25-95af-11cef5988ebf'::uuid, NULL, NULL, E'Backstroke', NULL, NULL),
  ('4ca98f87-8290-5ad5-99a0-6a781ede7682'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4ca98f87-8290-5ad5-99a0-6a781ede7682'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '01ada80f-965d-599a-87b6-1d1333a65914'::uuid, NULL, E'Economic recovery can''t be sustained unless more jobs are created.', NULL, NULL, NULL),
  ('4cac5a82-3fe0-5202-8a49-490a778216e5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4cac5a82-3fe0-5202-8a49-490a778216e5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e831e835-65a5-5845-a366-538e2788bef7'::uuid, NULL, NULL, E'Books from this collection are loanable for a one-week period.', NULL, NULL),
  ('4cb99f45-1b45-59ae-aaa2-9c5452b6a042'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4cb99f45-1b45-59ae-aaa2-9c5452b6a042'::uuid, 1, NULL, TRUE, 0, NULL, E'Alzheimer’s Disease', NULL, 'e9da8d2a-7ac1-52fc-80a5-2b824acd1145'::uuid, NULL, E'In 2015 I traveled to Columbia to prepare for the first ever prevention study in Alzheimer’s disease. A simple blood test could detect the mutation. If the study is successful patients could be identified and treated before the onset of symptoms. But what about the rest of the world with Alzheimer’s disease do the different genetic and environmental risks, what about patients like my friend David? Today’s technologies, smart phones wearables, online patient communities and online assessment tools can be used to gather data in an unprecedented global scale. With enough data, we can begin to understand the emerging genetics and this disease much the way Dr. Lopera did in Columbia. When that happens, we can begin to understand your risk for Alzheimer’s disease. The biological pathways that are the most important in you and most importantly, when to begin treatment. Now it’s the time that patients, family members, physicians, scientists and drug developers all have a role to play in defeating Alzheimer’s disease.', NULL, NULL, NULL),
  ('4ccb0c20-52ac-5335-86bf-610de205a218'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '4ccb0c20-52ac-5335-86bf-610de205a218'::uuid, 1, NULL, TRUE, 0, NULL, E'Cultural Studies', E'Cultural studies is a new way of engaging in the study of culture. In the past, many academic subjects including anthropology, history, literary studies, human geography and sociology have brought their own disciplinary concerns to the study of culture. {{1}} , in recent decades there has been a {{2}} interest in the study of culture that has crossed disciplinary {{3}} . The {{4}} activities and cultural studies have emerged as an intriguing and exciting area of intellectual inquiry which has already shed important new light on the character of human cultures and which {{5}} to continue to do so. While there is little doubt that cultural studies are coming to {{6}} as an important and distinctive field of study, it does seem to encompass a potentially enormous area. This is because the term ''culture'' has a complex history and range of usages, which have provided a legitimate {{7}} of inquiry for several academic disciplines.', NULL, NULL, NULL, E'1.However, 2.renewed, 3.boundaries, 4.resulting, 5.promises, 6.be widely recognized, 7.focus', NULL, NULL),
  ('4cccc6a5-82e1-5792-bfff-c24b17c91907'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '4cccc6a5-82e1-5792-bfff-c24b17c91907'::uuid, 1, NULL, TRUE, 0, NULL, E'Paid Leave', E'Working employees have paid leave. Is it good or bad?', NULL, NULL, NULL, NULL, 200, 300),
