  ('4d72dc8c-9b5d-5501-a43a-b85307829c9a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4d72dc8c-9b5d-5501-a43a-b85307829c9a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '16ae978a-b391-5a30-85db-a3b6cc499f9f'::uuid, NULL, E'Social justice is an important topic in today''s society.', NULL, NULL, NULL),
  ('4d747ee5-028e-5c05-8e38-a42eeb453290'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '4d747ee5-028e-5c05-8e38-a42eeb453290'::uuid, 1, NULL, TRUE, 0, NULL, E'Statistics', E'Governments, business and many types of institutions collect, organise and record statistics. Statistics capture vital information about such things as the economy, population and the environment and therefore allow meaningful comparisons to be made. This can then inform decisions and plans made about such issues which in turn become public policies. While it may be the issues behind the statistics, rather than the statistics as such that command the public''s attention, it must be recognised that it is the figures that inform these issues.\n\nThe author considers statistics to be important because', NULL, NULL, NULL, E'they assist in driving public issues.', NULL, NULL),
