  ('4f3815f3-dfd0-589f-b0de-20719749d489'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4f3815f3-dfd0-589f-b0de-20719749d489'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'de449a62-f4e0-5053-9025-ee0384e98130'::uuid, NULL, E'The university''s football team has won several national championships.', NULL, NULL, NULL),
