  ('4f3cb169-3a2b-5630-94c0-bc4c0bef5a97'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4f3cb169-3a2b-5630-94c0-bc4c0bef5a97'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'de24a669-f934-5964-b08e-48ede47cb367'::uuid, NULL, E'Please read the first five chapters to prepare for next week''s tutorial.', NULL, NULL, NULL),
  ('4f401f27-410b-5584-99aa-2e8973f52b59'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4f401f27-410b-5584-99aa-2e8973f52b59'::uuid, 1, NULL, TRUE, 0, NULL, E'Children Obesity', NULL, 'e26f85e3-8cea-50e9-ac6c-8c2d1d5210b7'::uuid, NULL, E'The growing issue of childhood obesity is a serious health crisis that we can no longer ignore. There are twenty percent of children in the USA today have the obesity problem.\nAs a result, heart diseases have become more and more common among children, the youngest of which is five years old. This is a stark departure from the past. The diseases that used to occur to people above fifty or sixty are now happening to people as early as they are five or six years old. This situation makes children suffer the heart attack and other health problems earlier and earlier, such as kidney impairment and stroke.\nThose diseases that used to be uncommon have begun to be common. This normalization is dangerous because it can make us less urgent in our response. When serious health issues become frequent, we risk accepting them as an inevitable part of modern life, rather than as a preventable crisis.\nTherefore, the need for action is clear and immediate. We have to address the overweight problem.', NULL, NULL, NULL),
  ('4f46fa4b-42dc-54f7-a40a-87d813c817a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4f46fa4b-42dc-54f7-a40a-87d813c817a8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which part at the end of book can be used for further reading?', 'e17381de-7366-5705-a3b3-e1de3c5601a6'::uuid, NULL, NULL, E'Bibliography / index / reference', NULL, NULL),
  ('4f4a40ef-0c9b-5191-b6b2-7e3c93a664cc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4f4a40ef-0c9b-5191-b6b2-7e3c93a664cc'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8e5db531-05d4-582b-b2bc-35ddf474db20'::uuid, NULL, NULL, E'To take this course students should have basic subject knowledge.', NULL, NULL),
  ('4f4c7aec-b457-51d4-b7f6-d1e8bf9dd830'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4f4c7aec-b457-51d4-b7f6-d1e8bf9dd830'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which day of the week starts with ''th''?', 'a009cc50-aa9e-5143-a9b4-f1709f897b24'::uuid, NULL, NULL, E'Thursday', NULL, NULL),
  ('4f527b57-9b42-5648-bd62-db9f7a7a9dba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '4f527b57-9b42-5648-bd62-db9f7a7a9dba'::uuid, 1, NULL, TRUE, 0, NULL, E'Role of Innovation', E'Innovation is a driving force behind economic growth and prosperity. It fuels productivity, enhances competitiveness, and creates new opportunities in the global marketplace. The relationship between innovation and economic success is a symbiotic one, with each reinforcing the other. Innovation leads to increased productivity by finding more efficient ways to produce goods and deliver services. It results in the development of cutting-edge technologies, processes, and products that boost efficiency, reduce costs, and increase output. This, in turn, contributes to economic growth by expanding the capacity of industries and markets.\nCompetitiveness in the global economy is another area where innovation plays a pivotal role. Nations and companies that prioritize innovation are better equipped to compete effectively. They can offer superior products and services that meet evolving consumer demands, both domestically and internationally. Innovation helps create sustainable competitive advantages, driving economic growth and market expansion. Moreover, innovation fosters entrepreneurship and job creation. New businesses often emerge as a result of innovative ideas, and these startups can have a significant impact on job markets. As innovation-driven companies thrive, they create employment opportunities and contribute to economic stability and prosperity.\nInnovation is not limited to technological advancements; it also encompasses improvements in business models, organizational structures, and social practices. These innovations can lead to more inclusive and sustainable economic growth, benefiting a broader range of individuals and communities.', NULL, NULL, E'Innovation is a driving force behind economic growth and prosperity, which fuels productivity, enhances competitiveness, and creates new opportunities in the global marketplace, and it contributes to economic growth by expanding the capacity of industries and markets; innovations can lead to more inclusive and sustainable economic growth, benefiting a broader range of individuals and communities.', NULL, 5, 75),
  ('4f53699e-61da-5853-a986-1d23f1f82fe3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4f53699e-61da-5853-a986-1d23f1f82fe3'::uuid, 1, NULL, TRUE, 0, NULL, E'Emotional Blackmail', NULL, '8eff7a1f-c828-513d-b0d1-7f87f5f07ab1'::uuid, NULL, E'M: Fundamentally, the blackmailer is entitled. They believe that others are responsible for their feelings. They believe others must act in a way that makes them feel good, rather than taking responsibility for their own feelings.\nS: Oh, that actually makes a lot of sense. What about the person who let’s themselves be blackmailed? Why do they allow that?\nM: The blackmailer refuses to take responsibility for their own feelings, but the blackmailee is the exact opposite: they take responsibility for feelings that aren’t their own. While the blackmailer wants everyone around them to act a certain way, the blackmailee wants everyone to feel a certain way. While the blackmailer feels entitled, the blackmailee feels like they owe a debt. While the blackmailer passes judgements, the blackmailee is always looking to be positively judged. They take the judgments of other people very seriously. If someone says to them, “you’re a very selfish person,” they believe it immediately. They think, am I selfish? I must be selfish! Why would someone say that if I wasn’t? Oh god I’m such a bad person. I need to fix this right now. While the blackmailer wants everyone to serve them, the blackmailee wants to serve everyone. They wanna be liked and approved by everyone, and they’ll do just about anything to get it. While the blackmailer believes what they say is the truth, the blackmailee believes that what others say about them is the truth. And while the blackmailer’s mind is dominated by taking, the blackmailee’s mind is dominated by giving.', NULL, NULL, NULL),
  ('4f5675fe-8e99-566b-a429-1e3e057f8de4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4f5675fe-8e99-566b-a429-1e3e057f8de4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f7f3b2a6-f993-5355-8469-dece0ef05ef3'::uuid, NULL, NULL, E'Education is the best way for people to invest in the future.', NULL, NULL),
  ('4f569827-6e9d-5412-93b7-50d4837141ed'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4f569827-6e9d-5412-93b7-50d4837141ed'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '21938271-170c-5832-bb6d-bfa110ada90b'::uuid, NULL, NULL, E'Online courses enable people to improve their skills while employed.', NULL, NULL),
  ('4f6532a6-34ee-5472-aae2-0fe92053f3e6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4f6532a6-34ee-5472-aae2-0fe92053f3e6'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call the money you pay to use a road or a bridge?', 'b6ac3f2d-f179-54f8-be6d-e08cc7f77e9b'::uuid, NULL, NULL, E'Toll', NULL, NULL),
  ('4f6cde97-aa32-5049-bc58-b79d33cc8bab'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', '4f6cde97-aa32-5049-bc58-b79d33cc8bab'::uuid, 1, NULL, TRUE, 0, NULL, E'Old Man of Lake', E'Small, localized enterprises are becoming ever-more imaginative in identifying opportunities to boost tourism for their areas. A more unusual attraction is the Old Man of the Lake, which is the name given to a 9-meter-tall tree stump that has been bobbing vertically in Oregon''s Crater Lake since at least 1896. For over one hundred years, it has been largely ignored but recently it has become a must-see item on the list of lake attractions. Since January 2012, tour boats regularly include the Old Man on their sightseeing trips around the lake.\nAt the waterline, the stump is about 60 centimeters in diameter, and the exposed part stands approximately 120 centimeters above the surface of the water. Over the years, the stump has been bleached white by the elements. The exposed end of the floating tree is splintered and worn but wide and buoyant enough to support a person''s weight.\nObservations indicated that the Old Man of Crater Lake travels quite extensively, and sometimes with surprising rapidity. Since it can be seen virtually anywhere on the lake, boat pilots commonly communicate its position to each other as a general matter of safety.\n\nWhich of the following are true of the Old Man of the Lake according to the text?', NULL, NULL, NULL, E'It is a drifting piece of wood.\nIt can quickly move about the lake.\nIt can be a danger to boat users.', NULL, NULL),
  ('4f771ab9-c5d6-5152-a016-63d765d96774'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4f771ab9-c5d6-5152-a016-63d765d96774'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4688016a-63f4-52be-b485-1ee76e1f2c88'::uuid, NULL, E'There will be ample opportunities to ask questions about the presentation.', NULL, NULL, NULL),
  ('4f7f4442-a0b6-56ff-bd65-1d0faa66e024'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4f7f4442-a0b6-56ff-bd65-1d0faa66e024'::uuid, 1, NULL, TRUE, 0, NULL, E'Subjective Beliefs', E'The concept that a placebo or sham treatment can mimic genuine treatment effects is well-established in science. While researchers have closely monitored this phenomenon, it has been typically catalogued separately from the in-depth analyses of the actual treatment outcomes. What sets our study apart is that we have brought together these two datasets -- subjective beliefs and objective treatment measures.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('4f801878-97de-5296-8cf6-53907a98d59d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4f801878-97de-5296-8cf6-53907a98d59d'::uuid, 1, NULL, TRUE, 0, NULL, E'Drug Overdose Deaths', E'The slight decline in drug overdose deaths in 2018 coincides with Chinese regulations on the powerful opioid carfentanil, rather than the result of domestic U.S. efforts to curb the epidemic, a new analysis reveals. What many — including President Donald Trump — perceived as a decline in overdose deaths in 2018, appears to be a return to the historic exponential curve.', NULL, NULL, NULL, NULL, NULL, NULL),
