  ('4f914055-6115-5605-bef8-a6e0cbf8b613'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '4f914055-6115-5605-bef8-a6e0cbf8b613'::uuid, 1, NULL, TRUE, 0, NULL, E'Caffeine', E'Whether it’s in your morning espresso or an energy drink at the gym, caffeine might be such an integral part of your {{1}} that you don’t stop to think that it’s actually a psychostimulant – a drug that {{2}} on the brain. Specifically, caffeine acts to block the brain chemical adenosine, which usually serves to {{3}} us down physiologically, such as by lowering our blood pressure and {{4}} our breathing.', NULL, NULL, NULL, E'1.routine, 2.acts, 3.calm, 4.slowing', NULL, NULL),
  ('4fa798c0-a139-5cd5-9700-3b83fd4ecf69'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4fa798c0-a139-5cd5-9700-3b83fd4ecf69'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call a country where there is no king but a president?', 'edf9a1fa-aa72-5cc9-a732-156237f006d6'::uuid, NULL, NULL, E'Republic', NULL, NULL),
