  ('4fc346e9-3f57-582f-975f-cf713cb1e266'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '4fc346e9-3f57-582f-975f-cf713cb1e266'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f247f594-85a1-5f35-a50f-8d79e974fe6a'::uuid, NULL, NULL, E'The discussion of a new university policy has been discouraged.', NULL, NULL),
  ('4fc5936e-fbb8-5c37-b443-f924f1a116d4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '4fc5936e-fbb8-5c37-b443-f924f1a116d4'::uuid, 1, NULL, TRUE, 0, NULL, E'Working Remotely', E'You will be on vacation and you want to discuss with your boss how to work efficiently, such as working remotely or something like that. What should you say to your boss?', '192bc531-92c1-58d8-a699-ec0ec8263f93'::uuid, NULL, E'Respected boss, I hope you are doing well.\nI would like to discuss an issue we have encountered with work arrangements during my upcoming vacation.\nIt appears that I’m going to take a vacation soon, and I’d like to talk about efficient work solutions like remote working.\nI would appreciate your opinion on this matter. Thank you for your consideration.', NULL, NULL, NULL),
