  ('506021e8-fa0b-5e19-af67-09549fdd1955'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '506021e8-fa0b-5e19-af67-09549fdd1955'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'efab2093-169f-5445-9eae-bc0c7bdc3a5c'::uuid, NULL, NULL, E'The key witnesses of the event are factors of your conviction.', NULL, NULL),
