  ('50fb90e6-4b3b-5eb1-bb40-362d48bee5c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '50fb90e6-4b3b-5eb1-bb40-362d48bee5c4'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bb0bc5ce-1c6f-55e7-b102-d93cd66eb34d'::uuid, NULL, E'I will be discussing the situation with my colleagues tomorrow.', NULL, NULL, NULL),
