  ('513e3c11-12eb-58bd-91cb-189af4e1cd25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '513e3c11-12eb-58bd-91cb-189af4e1cd25'::uuid, 1, NULL, TRUE, 0, NULL, E'Nuclear Weapons', E'About 46,000 nuclear weapons were produced during the Cold War era, leading to tremendous volumes of acidic radioactive liquid waste seeping into the environment. A new study suggests yeast as a potentially safer and more cost effective way to help clean up these radioactive waste sites.', NULL, NULL, NULL, NULL, NULL, NULL),
