  ('515dd92c-e2d1-5dc0-8bab-cc732dc3ea01'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '515dd92c-e2d1-5dc0-8bab-cc732dc3ea01'::uuid, 1, NULL, TRUE, 0, NULL, E'Psychology', E'Psychology is the study of cognitions, emotions, and behavior. Psychologists are involved in a variety of tasks. Many spend their careers designing and performing research to understand how people behave in specific situations, how and why we think the way we do, and how emotions develop and what impact they have on our interactions with others.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('516f00fa-5f92-533b-8f65-f51eeba1328a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '516f00fa-5f92-533b-8f65-f51eeba1328a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '89105b70-348a-56db-9282-103c94c72f88'::uuid, NULL, NULL, E'We pick people who know the basics to start with.', NULL, NULL),
