  ('51e56f74-43f7-5f67-9f78-c88d1e086406'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '51e56f74-43f7-5f67-9f78-c88d1e086406'::uuid, 1, NULL, TRUE, 0, NULL, E'Housework', E'Your flatmate doesn''t follow the schedule to complete housework. What would you say to him or her?', '56bebadb-1ae8-558b-b1c5-2ee35112d2e0'::uuid, NULL, E'Hey flatmate, I want to talk to you about something.\nWe seem to have a little issue with our housework schedule.\nIt''s like you haven''t finished your housework following our agreed schedule.\nAnd I''d like to know what you think.', NULL, NULL, NULL),
