  ('5271d2db-6441-5170-8352-043c723ee48d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '5271d2db-6441-5170-8352-043c723ee48d'::uuid, 1, NULL, TRUE, 0, NULL, E'Jury', E'Serving on a jury is normally compulsory for individuals who are {{1}} for jury service. A jury is {{2}} to be an impartial panel capable of reaching a verdict. There are often {{3}} and requirements, including a fluent understanding of the language and the opportunity to test juror''s neutrality or otherwise exclude jurors who are perceived as likely to be less than {{4}} or partial to one side.', NULL, NULL, NULL, E'1.qualified, 2.intended, 3.procedures, 4.neutral', NULL, NULL),
  ('5272ca1c-a603-55a0-9841-cd8f4f3ed8b0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5272ca1c-a603-55a0-9841-cd8f4f3ed8b0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7d0c1583-a895-54be-ba6a-01db42b31636'::uuid, NULL, E'We need to approach communication in an open way.', NULL, NULL, NULL),
  ('5272f8e6-6be4-5099-a3e7-6c46ef8e4b7d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '5272f8e6-6be4-5099-a3e7-6c46ef8e4b7d'::uuid, 1, NULL, TRUE, 0, NULL, E'Artificial Intelligence', E'How can artificial intelligence (AI) help us solve some of the most complex and {{1}} problems in the world? Can AI systems learn from data and {{2}} with humans in natural ways? What are the ethical and social implications of developing and {{3}} AI systems in various domains? These are some of the questions that motivate and challenge AI researchers and practitioners who aim to create and apply AI systems that can {{4}} human capabilities.', NULL, NULL, NULL, E'1.pressing, 2.interact, 3.deploying, 4.enhance', NULL, NULL),
