  ('527d932a-a219-513a-a667-1cde8f55df84'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '527d932a-a219-513a-a667-1cde8f55df84'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b4014e3d-b0a6-5c05-9470-a5220a25ac75'::uuid, NULL, NULL, E'Our school has lots of different things for students to use.', NULL, NULL),
  ('527fbe3d-154b-5148-8860-45497e3b0eaa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '527fbe3d-154b-5148-8860-45497e3b0eaa'::uuid, 1, NULL, TRUE, 0, NULL, E'Conclusion', E'A satisfying conclusion allows a reader to finish your paper with a clear understanding of the points you made and hopefully even a new {{1}} on the topic. Any one paper might have a number of conclusions, but as the writer, you must consider who the readers are and the conclusions you want them to reach. For example, is your reader relatively new to your topic? If so, you may want to restate your main points for {{2}} as a way of starting the conclusion. Don’t literally use the same sentence(s) as in your introduction, but come up with a comparable way of restating your thesis. You’ll want to {{3}} conclude by showing that the judgment you have reached is, in fact, reasonable.', NULL, NULL, NULL, E'1.perspective, 2.emphasis, 3.smoothly', NULL, NULL),
