  ('53419a1d-7131-572c-99d4-36fbf9d7974f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '53419a1d-7131-572c-99d4-36fbf9d7974f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7385af68-637b-5a41-b304-70482187393b'::uuid, NULL, NULL, E'The college has built a library open to the public.', NULL, NULL),
  ('5344adb0-62c3-5dad-8aa8-2977962145d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5344adb0-62c3-5dad-8aa8-2977962145d8'::uuid, 1, NULL, TRUE, 0, NULL, E'Education at Home', E'There are two main reasons why parents decide to educate their children at home: either they dislike schools on principle, however odd those principles might be, or they don''t believe their local schools provide an adequate education or the right sort of education for their children. If someone decides to teach their child at home - either by themselves or by employing a teacher - they have to convince their local education authority (LEA) that the teaching provided is satisfactory. Schedules, lesson plans and book lists must be shown, and it must also be demonstrated that the child is in fact learning and that they have adequate opportunities for physical education and meeting other children. Furthermore, while there is no formal assessment, officers from the LEA will come and inspect what is being done and look at the child''s exercise books. If they are not satisfied, they may make out a school attendance order.\n\nWhich of the following conditions need to be met by parents who want to have their children educated at home?', '3a86c1ab-47a4-5d21-a7a6-0626ea678b0a'::uuid, NULL, NULL, E'They must ensure their child has access to physical education.\nThey must provide book lists.', NULL, NULL),
  ('5346368f-1dfd-50ef-a86d-02462cf42a5e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5346368f-1dfd-50ef-a86d-02462cf42a5e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5465a57e-2b0f-5ecf-9bb6-0292b0a27112'::uuid, NULL, NULL, E'Policies failed because the union leaders disagreed over the issue.', NULL, NULL),
  ('53471cbf-1e82-59a6-adb8-ce4867e293e2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '53471cbf-1e82-59a6-adb8-ce4867e293e2'::uuid, 1, NULL, TRUE, 0, NULL, E'Pigeons', E'There’s no scientific difference between pigeons and the much more beloved doves. While the term ‘pigeon’ tends to be {{1}} to larger species and ‘dove’ to smaller ones, the scientist notes in her illustrated field guide that there is actually no scientific or evolutionary {{2}} to either group. What’s more, the ubiquitous pigeon found in cities worldwide {{3}} from a bird known as the rock dove, which people long ago domesticated.', NULL, NULL, NULL, E'1.applied, 2.distinction, 3.descends', NULL, NULL),
  ('534c31a5-20c0-5d8a-b596-e4e017ab4647'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '534c31a5-20c0-5d8a-b596-e4e017ab4647'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '34698afe-550d-5c72-828a-c167f34f1588'::uuid, NULL, E'He''s showing his work at the London Gallery of Art.', NULL, NULL, NULL),
  ('534ca244-25bc-514b-8b5d-364917df1305'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '534ca244-25bc-514b-8b5d-364917df1305'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'afb8ccd1-fb16-57cc-8368-8377968162af'::uuid, NULL, NULL, E'This occupation requires a good demand of Spanish and French.', NULL, NULL),
  ('5354f0e2-3bd1-5856-be2d-6282e997b97a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5354f0e2-3bd1-5856-be2d-6282e997b97a'::uuid, 1, NULL, TRUE, 0, NULL, E'Tutorial', NULL, '358a9ab1-ca0b-5ffe-b4c3-70b5c64dbe21'::uuid, NULL, E'My name is Evie Carroll, I’m a second year studying International Business. My degree subject is made up of tutorials, lectures, and independent learning. And today I’m going to speak about tutorials. Before each tutorial we’re asked to prepare in advance. We’re usually given a reading lists which we have to complete before each tutorial. We are given websites to look at, e-journals to look at. And we have to prepare by writing our notes down. In every tutorial there’s about five to fifteen students, and these are led by the tutors, which are usually Masters or PhD students. And then when we come into the tutorial we are put into small groups and we are asked to discuss our ideas, generate new ideas, and then feed back to the class. During our tutorials there’s lots of support given. Our tutors are there so that we can ask questions at any time. We also have our peers there which we can also ask questions to. If we need help before the tutorial we can email in any of the tutors and they’ll provide you with help. The difference between lectures and tutorials is that in lectures you usually have about two hundred to three hundred students, whereas in tutorials it’s about five to fifteen students, which allows you to discuss matters, put your hand up, and talk to your tutors about any difficulties you may have with the subject.', NULL, NULL, NULL),
  ('535adedf-b4c0-5739-aa3c-a2abd39e66f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '535adedf-b4c0-5739-aa3c-a2abd39e66f8'::uuid, 1, NULL, TRUE, 0, NULL, E'Soybeans', NULL, NULL, NULL, NULL, E'1, 3, 2, 4', NULL, NULL),
  ('535bdcf6-e8b1-5549-816d-7e45246236cf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '535bdcf6-e8b1-5549-816d-7e45246236cf'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '76db9da5-4b5d-53f8-9af6-3574b25a72d8'::uuid, NULL, NULL, E'All mobile devices must be switched off during the examination.', NULL, NULL),
  ('5363b2ec-248b-58d2-aba7-e61abd0f3c54'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '5363b2ec-248b-58d2-aba7-e61abd0f3c54'::uuid, 1, NULL, TRUE, 0, NULL, E'Clinical Trials', NULL, NULL, NULL, NULL, E'1, 3, 5, 4, 2', NULL, NULL),
  ('536fbd61-4d0a-518b-9e08-0192087f2a75'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '536fbd61-4d0a-518b-9e08-0192087f2a75'::uuid, 1, NULL, TRUE, 0, NULL, E'Online Learning', E'What potential challenges do students face in online learning environments?', NULL, NULL, NULL, NULL, 200, 300),
  ('536ffa9f-f0b8-558d-88bd-10a1e8fd0b15'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '536ffa9f-f0b8-558d-88bd-10a1e8fd0b15'::uuid, 1, NULL, TRUE, 0, NULL, E'Astro-botany', E'In an intriguing development in astro-botany, researchers are exploring the potential of watermeal, the world''s smallest flowering plant, in hypergravity conditions. This research {{1}} to assess its suitability as a sustainable food {{2}} and oxygen producer for astronauts. Conducted in environments mimicking space conditions, the study explores how watermeal grows and thrives under increased gravity. The plant''s small size and rapid growth rate make it an {{3}} candidate for space cultivation. If {{4}} , watermeal could become a vital component of life-support systems in long-duration space missions, providing astronauts with a renewable source of food and oxygen. This research not only contributes to the advancement of space exploration but also opens up new possibilities in understanding plant biology {{5}} extreme conditions. It can also offer insights into how plants might adapt to changing environments on Earth, particularly in response to climate change.', NULL, NULL, NULL, E'1.aims, 2.source, 3.ideal, 4.successful, 5.under', NULL, NULL),
  ('5372092c-d130-53f6-9081-092684fb064b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '5372092c-d130-53f6-9081-092684fb064b'::uuid, 1, NULL, TRUE, 0, NULL, E'Hummingbirds', NULL, NULL, NULL, NULL, E'3, 4, 1, 2', NULL, NULL),
  ('53738972-dcf9-50c5-b29c-f3e91eaa7276'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '53738972-dcf9-50c5-b29c-f3e91eaa7276'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b57da53e-617b-5cff-9602-f53e95a8c59b'::uuid, NULL, E'The report stresses that students need to improve their computing skills.', NULL, NULL, NULL),
  ('537b1a22-cfb5-5ec0-92d9-0f65a3e31b49'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '537b1a22-cfb5-5ec0-92d9-0f65a3e31b49'::uuid, 1, NULL, TRUE, 0, NULL, E'Nostalgia', NULL, '549df80b-2234-5a98-9ff0-132621135c00'::uuid, NULL, E'In the late 17th century, a medical student named Johannes Hofer noticed a strange illness affecting Swiss mercenaries serving abroad. Its symptoms, including fatigue, insomnia, irregular heartbeat, indigestion, and fever were so strong, the soldiers often had to be discharged. As Hofer discovered, the cause was not some physical disturbance, but an intense yearning for their mountain homeland. He dubbed the condition nostalgia, from the Greek “nostos” for homecoming and “algos” for pain or longing. At first, nostalgia was considered a particularly Swiss affliction. Some doctors proposed that the constant sound of cowbells in the Alps caused trauma to the ear drums and brain. Commanders even forbade their soldiers from singing traditional Swiss songs for fear that they’d lead to desertion or suicide. But as migration increased worldwide, nostalgia was observed in various groups. It turned out that anyone separated from their native place for a long time was vulnerable to nostalgia. And by the early 20th century, professionals no longer viewed it as a neurological disease, but as a mental condition similar to depression.', NULL, NULL, NULL),
  ('537ed0b0-e71f-5aad-a779-0120e396bf06'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '537ed0b0-e71f-5aad-a779-0120e396bf06'::uuid, 1, NULL, TRUE, 0, NULL, E'Struggling With Computers', E'An endlessly rotating beach ball, a program that crashes without saving data or systems that require illogical procedures or simply do not work. Unfortunately, struggling with computers is still a familiar situation for most of us. Tearing your hair out over computers that do not work remains very common among users, according to new Danish research.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('5380322e-2e8d-5bb8-ae10-45d733cdf4c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5380322e-2e8d-5bb8-ae10-45d733cdf4c8'::uuid, 1, NULL, TRUE, 0, NULL, E'AI anxiety', E'It’s logical for humans to feel anxious about artificial intelligence. After all, the news is constantly reeling off job after job at which the technology seems to outperform us. But humans aren’t yet headed for all-out replacement. And if you do suffer from so-called AI anxiety, there are ways to alleviate your fears and even reframe them into a motivating force for good.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('538468b1-21fc-58a0-a14d-7530367bdff8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '538468b1-21fc-58a0-a14d-7530367bdff8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for a narrow body of water connecting two larger bodies of water?', 'd4f26248-6b7b-5ca1-9e00-25c6357dd5cb'::uuid, NULL, NULL, E'Strait', NULL, NULL),
