  ('538a12e0-2bde-5014-9ee9-9ca6c57ecaf2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '538a12e0-2bde-5014-9ee9-9ca6c57ecaf2'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What shows dishes before you order?', 'd6d5132c-a317-5b7a-99b9-7c930bcd7bcf'::uuid, NULL, NULL, E'Menu', NULL, NULL),
  ('538ebd2b-3c41-501e-945f-88b80916f811'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '538ebd2b-3c41-501e-945f-88b80916f811'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e108c802-745c-5e2b-98cf-a75c504722cc'::uuid, NULL, E'Many experts think that the world climate is changing.', NULL, NULL, NULL),
  ('5391db93-7385-5ab0-8859-d528feb5de42'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '5391db93-7385-5ab0-8859-d528feb5de42'::uuid, 1, NULL, TRUE, 0, NULL, E'Conventional Vehicles', E'Despite the surge in new energy vehicle sales, gasoline models are still more popular in China, the world''s largest vehicle market, according to a ByteDance report released on Monday.\nDcar, the company''s automotive information and service platform, said the absolute majority of its users searched online for information about internal combustion engine vehicles in 2021. “It did not offer specific statistics, but users'' interest as reflected in their searches is basically in line with the status quo in the market,” said Dcar.\nNEV sales are expected to reach 3.4 million this year in China, roughly 13 percent of total vehicle sales in the country, according to the China Association of Automobile Manufacturers. But their cumulative deliveries accounted for 2.28 percent of 297 million vehicles in China by the end of September 2021, said the Ministry of Public Security.\nDcar said the top 10 automotive brands that its users showed most interest in 2021 were all conventional brands, with German carmaker Volkswagen ranking first. The German brand was followed by Japan''s Honda and Toyota. In terms of premium brands, Mercedes-Benz was the most popular.\nLocal Chinese brands saw their popularity grow in 2021. Changan, BYD and Geely were among the top 10 brands Dcar users searched for. Startups, despite their high valuations in the stock market, garnered less attention compared with established brands, said Dcar. Of the new players, Xpeng ranked No 1, followed by Li Auto, Great Wall Motors'' new marque Ora and Geely''s electric arm Zeekr.', NULL, NULL, NULL, NULL, 5, 75),
  ('53967e90-47c2-5f92-b6c0-fefade54020c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '53967e90-47c2-5f92-b6c0-fefade54020c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '92f1f028-ab78-5329-a5cb-332f7c49596d'::uuid, NULL, E'Extension is only available under special circumstances.', NULL, NULL, NULL),
  ('53985b5f-4ab3-59c8-988b-36cfc7b1718d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '53985b5f-4ab3-59c8-988b-36cfc7b1718d'::uuid, 1, NULL, TRUE, 0, NULL, E'Freelancing', NULL, 'c87c22b9-963c-5aec-a35f-605240d6329b'::uuid, NULL, E'At some point in your life— maybe even now— you might wonder whether freelancing is right for you. You’ll need a few things to be successful. First, you’ll need a skill that’s in demand. This can be as universal as driving a car to as specialized as neurosurgery, and it can be in pretty much any field. The more people who want your skill, and the fewer people who have it, the more you can charge for your services. Next, you’ll need to transform yourself into an entrepreneur. Before freelancers can do any work, they have to find it. That takes marketing your services, negotiating contracts, building a network of satisfied clients, and a whole set of administrative skills like project management, time management, and accounting. And thirdly, if you can afford it, it’s probably a good idea to budget for some benefits for yourself and maybe your family. Freelancers don’t automatically get perks that some salaried jobs offer, like paid vacation or sick leave, life insurance, college tuition, or retirement plans.', NULL, NULL, NULL),
  ('539c1509-7971-54b8-bf67-6160a2fefae1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '539c1509-7971-54b8-bf67-6160a2fefae1'::uuid, 1, NULL, TRUE, 0, NULL, E'Overall Happiness', E'In today''s fast-paced world, finding balance in our lives has become a challenging art. We juggle work, family, social commitments, and personal interests, often leaving us feeling overwhelmed and stressed. However, achieving balance is essential for our well-being and overall happiness. One key aspect of balance is time management. Prioritizing tasks, setting realistic goals, and creating a schedule that allocates time for work, relaxation, and personal pursuits can help restore equilibrium. Learning to say no when necessary and avoiding overcommitment is also crucial. Maintaining a healthy work-life balance is equally vital. Allowing time for rest, relaxation, and quality time with loved ones can prevent burnout and nurture our relationships. Unplugging from digital devices periodically and setting boundaries for work-related communication outside of office hours can further promote balance. Physical well-being is another integral component. Regular exercise, a balanced diet, and sufficient sleep are foundational to maintaining physical health. These habits not only boost energy levels but also reduce stress and enhance overall life satisfaction. Mental and emotional balance involves mindfulness practices such as meditation and self-reflection. These techniques help us stay centered, manage stress, and develop emotional resilience. Furthermore, nurturing our passions and hobbies is essential. Engaging in activities that bring joy and fulfillment can counterbalance the demands of daily life. In conclusion, finding balance in modern life is an art that requires conscious effort and self-awareness. By prioritizing time management, work-life balance, physical health, mental well-being, and personal passions, we can create a harmonious and fulfilling life. Balancing our responsibilities with self-care ultimately leads to a happier, healthier, and more satisfying existence.', NULL, NULL, E'Achieving balance is essential for our well-being and overall happiness, where one key aspect of balance is time management and physical well-being is another integral component, and nurturing our passions and hobbies is also essential; balancing our responsibilities with self-care ultimately leads to a happier, healthier, and more satisfying existence.', NULL, 5, 75),
  ('539e7131-7839-5990-a8e7-16ababc9dee9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '539e7131-7839-5990-a8e7-16ababc9dee9'::uuid, 1, NULL, TRUE, 0, NULL, E'Stroke Risk', E'People in their 20s and 30s who drink moderate to heavy amounts of alcohol may be more likely to have a stroke as young adults than people who drink low amounts or no alcohol, according to a study. The risk of stroke increased the more years people reported moderate or heavy drinking.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('539f7c3e-cc66-5d8b-b0c7-200125d91454'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '539f7c3e-cc66-5d8b-b0c7-200125d91454'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '54c18d4a-6095-5c28-9ce0-9ff1a2d77a65'::uuid, NULL, NULL, E'It is hard to find a job without advanced skills.', NULL, NULL),
  ('539fc45f-30c0-5e48-9937-85f94c949c24'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '539fc45f-30c0-5e48-9937-85f94c949c24'::uuid, 1, NULL, TRUE, 0, NULL, E'Geosphere', E'The geosphere includes all the stuff that makes up the crust and the core of the earth, and everything natural and lifeless that makes up the surface of the earth. Examples are all the rocks and sand particles from dry land to those found at the bottom of the oceans. The geosphere undergoes infinite processes constantly, which in turn modifies other spheres.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('53a97b95-e973-5e78-bcce-4e73b511a3c2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '53a97b95-e973-5e78-bcce-4e73b511a3c2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '90d67270-905e-5ba0-8236-8c391a9b6eb8'::uuid, NULL, NULL, E'Globally, governments are structured and operate in various distinct forms.', NULL, NULL),
