  ('53ac9f80-407e-537a-a6e2-bc6ab6aa95ed'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '53ac9f80-407e-537a-a6e2-bc6ab6aa95ed'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ddc42b89-8e69-5b16-8954-03f583a1bd76'::uuid, NULL, E'Answers to these crucial scientific questions are approaching closer for researchers.', NULL, NULL, NULL),
  ('53aefedf-93c0-5a39-89d0-be02e059ba9b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '53aefedf-93c0-5a39-89d0-be02e059ba9b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e7a43dde-36b2-50bf-bdc2-b3b3cb21e42f'::uuid, NULL, NULL, E'This is a brief survey of public support in selected nations.', NULL, NULL),
  ('53b10106-79a2-55d8-96a8-902fd801d77f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '53b10106-79a2-55d8-96a8-902fd801d77f'::uuid, 1, NULL, TRUE, 0, NULL, E'Seminars', E'Seminars are not designed to be mini-lectures. Their educational {{4}} is to provide an opportunity for you to discuss interesting and/or difficult aspects of the course. This is founded on the {{5}} that it is only by actively trying to use the knowledge that you have acquired from lectures and texts that you can achieve an adequate understanding of the subject. If you do not understand a point it is highly {{1}} that you will be the only person in the group in that position; you will invariably be undertaking a {{3}} for the entire group if you come to the seminar equipped with questions on matters which you feel you did not fully understand. The seminar is to {{2}} discussion.', NULL, NULL, NULL, E'1.role, 2.assumption, 3.unlikely, 4.duty, 5.provoke', NULL, NULL),
  ('53b99d33-70b9-5ac8-9850-3f2fdc78a919'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '53b99d33-70b9-5ac8-9850-3f2fdc78a919'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '360d4e24-1133-5a70-81e7-667296a333ea'::uuid, NULL, NULL, E'The new research has produced some other unexpected results.', NULL, NULL),
  ('53c54884-0f13-572e-9c99-7f307a41bb8d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '53c54884-0f13-572e-9c99-7f307a41bb8d'::uuid, 1, NULL, TRUE, 0, NULL, E'Mechanical Engineering', E'Mechanical engineering was at the heart of Taylor''s theorizing, providing the context for its development, the world view by which it was sustained and, finally, the justification for its widespread application. Scientific management aimed to analyse and control the activities of people {{1}} engineers analysed and controlled machines. Central {{2}} Taylor''s system was the desire {{3}} and standardize production techniques in the interests of economy, efficiency and mutual prosperity. His primary point of interest was the individual worker {{4}} individual goals and motivated by incentive payments. {{5}} Taylor''s view of human motivation was somewhat simplistic and his apprehension of the significance of groups was limited and generally negative.', NULL, NULL, NULL, E'1.in the same way that, 2.to, 3.to rationalize, 4.pursuing, 5.Undoubtedly', NULL, NULL),
  ('53cf9338-8b09-5fac-9e98-7ce60424b1df'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '53cf9338-8b09-5fac-9e98-7ce60424b1df'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6e9eaa74-57e4-58b7-bacd-ce10941b3f87'::uuid, NULL, NULL, E'Discipline and motivation are essential for achieving your goals.', NULL, NULL),
  ('53d08b71-e24c-588b-b5f2-9aa2a98b7bcb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '53d08b71-e24c-588b-b5f2-9aa2a98b7bcb'::uuid, 1, NULL, TRUE, 0, NULL, E'Time Management', E'Time management is not that difficult, but it does require advanced thinking and staying on top of tasks that are coming up. Whether the upcoming task is imminent or in the future, it should be recorded. Whether it is recorded on a tech device or a paper notepad, the need is the same.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('53d5702a-5eb8-5aa1-b0ce-8ea01e4886f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '53d5702a-5eb8-5aa1-b0ce-8ea01e4886f9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '12b49cfe-4023-5275-9577-25956e55e3c7'::uuid, NULL, NULL, E'Students must know the technological aspects of the society.', NULL, NULL),
  ('53d6a280-9bb0-5100-9039-d92c73592f17'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '53d6a280-9bb0-5100-9039-d92c73592f17'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a set of wires covered in plastic or rubber that carries electricity?', '5917dc37-a8a5-550c-a1e6-78b7f000812e'::uuid, NULL, NULL, E'Cable', NULL, NULL),
  ('53d9ebfc-f4d6-59f8-858e-cb8f235b4a46'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '53d9ebfc-f4d6-59f8-858e-cb8f235b4a46'::uuid, 1, NULL, TRUE, 0, NULL, E'World of Journalism', E'Never before has the world of journalism been so explosive, so global, and so competitive. Forget hourly news flashes; we live in a world of 24-hour breaking news, with radio and TV stations and Internet news sites updating stories by the minute.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('53dcaa2b-9c67-5425-8093-b036962d3e20'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '53dcaa2b-9c67-5425-8093-b036962d3e20'::uuid, 1, NULL, TRUE, 0, NULL, E'Civil War', E'A Civil War reenactment is in part a memorial service. It is partly, too, a leisure activity.\nFurthermore most reenactors assert an educational import to the performance, and to develop their roles many pursue archival research with a rare dedication. On the other hand Civil War reenactments are increasingly commercial {{1}} , with as many as fifty thousand Americans routinely gathering at (or near) historical Civil War battlefields in order to stage performances that purport to recreate the conflict, while hundreds of thousands more spectate (Hadden 1996:5).\nI will show how theoretical issues of {{2}} arise as practical problems in the Civil War reenactment community by presenting my own observations from the 2006 Gettysburg reenactment and by {{3}} on a number of texts produced by participant-observers. In particular I will refer to Robert Lee Hodge, who was made famous by Tony Horwitz''s 1996 book, Confederates in the Attic, and who served as a kind of Virgil to the author on his journey through a Confederate Valhalla. From these sources I will {{4}} that ''Living History'' performances require an interpretive apparatus that takes genuine history as its authority, while remaining external to both participants and tourists, who may well be unaware of how closely their own involvement approximates genuine historical events.', NULL, NULL, NULL, E'1.spectacles, 2.authenticity, 3.relying, 4.argue', NULL, NULL),
  ('53ea8545-9820-51ad-92b9-62610157d373'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '53ea8545-9820-51ad-92b9-62610157d373'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5aeca602-ff84-5222-a2fc-341e6f5fd909'::uuid, NULL, E'He studied for many years with an expert painter.', NULL, NULL, NULL),
  ('53ed3d3a-c946-50f7-aa5a-8b6db5c286ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '53ed3d3a-c946-50f7-aa5a-8b6db5c286ca'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd8fd40ee-cf21-5be1-a50a-dfb25a7c019d'::uuid, NULL, E'The manager will have a meeting in this room today.', NULL, NULL, NULL),
  ('53f4235e-3c50-5ca1-8cd1-69c7e91794ad'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '53f4235e-3c50-5ca1-8cd1-69c7e91794ad'::uuid, 1, NULL, TRUE, 0, NULL, E'Scientific Curiosity', E'Scientific curiosity is a {{1}} force behind breakthroughs in medicine, technology, and understanding our universe. Curiosity can enhance your well-being and happiness, as it stimulates your brain and makes you more {{2}} with your surroundings. Cultivate your curiosity by asking questions, and don''t be {{3}} to challenge yourself and step out of your {{4}} zone.', NULL, NULL, NULL, E'1.driving, 2.engaged, 3.afraid, 4.comfort', NULL, NULL),
  ('53f5fe43-3103-515b-86de-2594860ca5c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '53f5fe43-3103-515b-86de-2594860ca5c6'::uuid, 1, NULL, TRUE, 0, NULL, E'Chopsticks', NULL, '249a60fe-25bd-5d08-b0ba-c8ae8df06423'::uuid, NULL, E'Chopsticks are used in a huge portion of the world across much of Asia. About 1.5 billion people are covered in the chopsticks sphere. Different cultures have slightly different variations of chopsticks. Chinese chopsticks will tend to be long and round, Korean chopsticks, which are flatter, and often made of metal, and Japanese chopsticks tend to be round, and very, very pointy. While chopsticks are actually really commonplace in American society today, there was definitely a time in the late 1800s where this idea that Asian men, because they ate rice with sticks, were of a different quality than American men who ate proper meat with knife and fork. But, when China and the United States began their diplomatic engagement in the 1970s, Richard Nixon, Henry Kissinger had to practice eating with chopsticks. What’s been really interesting to see is that as Asian cuisine has moved from the east into the west, chopsticks have become part of the experience. There’s evidence of chopsticks as long ago as the Shang dynasty, which was about 3,000 years ago. And they loved tripods during the Shang dynasty, so, when you cook with these big tripods, chopsticks were actually really useful because it was a way for you to stir and to reach without getting burned as the water was boiling in these really big pots. Chinese culture has knives and has forks, that uses them in many cases for cooking, but in terms of what moved into the dining room, it was the chopsticks.', NULL, NULL, NULL),
  ('53fc31d3-cfa1-542a-8c62-517ddc495fa0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '53fc31d3-cfa1-542a-8c62-517ddc495fa0'::uuid, 1, NULL, TRUE, 0, NULL, E'Soccer', E'The term "soccer" comes from a time when the sport needed to be distinguished {{1}} its cousin, rugby football. Back in England, where both games originated, "soccer" is actually a nickname derived from "association football," the official name for the game we know and love that involves kicking a ball into a goal. The "assoc" in association got snipped and slapped with an "er," giving {{2}} to "soccer." It stuck around, especially in places like the United States and Australia, where they already had their own {{3}} of football. So, while most of the world passionately calls it "football," Americans and a few others {{4}} on to "soccer" to avoid confusion with their own gridiron and Aussie rules games. It''s all about keeping things clear while still kicking around the same beloved ball.', NULL, NULL, NULL, E'1.from, 2.birth, 3.versions, 4.hold', NULL, NULL),
  ('53ff0001-671d-5a69-a9f5-2765be28440b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '53ff0001-671d-5a69-a9f5-2765be28440b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the replacement of a typewriter?', '3373c9fe-aae9-5344-8065-caef382edd33'::uuid, NULL, NULL, E'Keyboard', NULL, NULL),
  ('5400b1c0-6f8d-594b-b08f-dc884cfab723'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5400b1c0-6f8d-594b-b08f-dc884cfab723'::uuid, 1, NULL, TRUE, 0, NULL, E'Body Composition', E'Your body''s composed of trillions of cells — lots of different types of cells that make up different organs and other parts of your body. Your body is also where 10 times that number of bacteria call ''home sweet home.'' But don''t be afraid — these bacteria do more good than harm to you.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('54033893-ec0f-5369-81b3-a3304321680e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '54033893-ec0f-5369-81b3-a3304321680e'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-R', E'Civilization is not inimical to health and long life. In fact, the contrary is true, for as the people advance they learn to master the forces of nature and with these forces under control they are able to lead better, healthier lives; but if they become too soft and luxurious, there is decay of moral and physical fiber. Civilization is favorable to long life so long as the people are moderate and live simply, but when it degenerates to sensuous softness, individual and racial deterioration ensue. Too generous a supply of food, too little physical activity and packed food are some of the luxuries which are generally introduced with civilization.\n\nWhich of the following most accurately summarizes the opinion of the author in the text?', NULL, NULL, NULL, E'Life of immoderation is neither natural nor desirable.', NULL, NULL),
  ('54097290-1426-54dd-9afa-a09bfd7155b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '54097290-1426-54dd-9afa-a09bfd7155b8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the scientific study of animals and their behaviors?', '69996be8-3b02-56ea-bbcf-263fb6278841'::uuid, NULL, NULL, E'Zoology', NULL, NULL),
  ('5409dd1c-fc16-5da1-bf8b-a6ef4ddcab25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5409dd1c-fc16-5da1-bf8b-a6ef4ddcab25'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f03d685e-e5ef-5fe0-9d8e-34ab1ffaeaea'::uuid, NULL, E'Successful applicants will work with a large team of researchers.', NULL, NULL, NULL),
  ('54106c79-d2a0-55b1-abd0-6f394ca749cb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '54106c79-d2a0-55b1-abd0-6f394ca749cb'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call an underground pipe that is used to carry sewage away from houses?', '28f21f4f-72ca-5989-949c-2dcb4c847bde'::uuid, NULL, NULL, E'Sewer', NULL, NULL),
  ('54172b92-aa6f-590d-9228-9dbbdb656b40'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '54172b92-aa6f-590d-9228-9dbbdb656b40'::uuid, 1, NULL, TRUE, 0, NULL, E'International Travel', E'International travel is cheaper and more convenient than ever. Do the advantages of this outweigh the disadvantages?', NULL, NULL, E'The current era has witnessed a significant shift towards cheaper and more convenient international travel, offering a myriad of advantages that outweigh the potential disadvantages. Increased accessibility, a boost to the tourism industry, and enhanced cultural exchange are among the key benefits of this trend, fostering greater connectivity and mutual understanding on a global scale.\nCheaper travel options have democratized international exploration, making distant destinations more accessible to a wider range of people. This increased accessibility not only broadens horizons for travelers but also promotes cultural diversity and cross-cultural interactions, enriching the travel experience for individuals from all walks of life.\nThe affordability of international travel catalyzes the tourism industry, driving economic growth and benefiting local economies. More tourists mean increased revenue for businesses, job opportunities for locals, and investments in infrastructure development. Additionally, convenient travel fosters cultural exchange and understanding among diverse populations, promoting mutual respect, tolerance, and appreciation for different traditions and customs.\nIn conclusion, the advantages of cheaper and more convenient international travel far outweigh any potential disadvantages, as it enhances accessibility, stimulates economic growth in the tourism sector and fosters cultural exchange on a global scale. Embracing this trend not only promotes mutual understanding and connectivity among nations but also contributes to the enrichment of individual experiences and the strengthening of global relationships.', NULL, 200, 300),
  ('54217e22-fb7e-5e31-afa2-78f7272d420f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '54217e22-fb7e-5e31-afa2-78f7272d420f'::uuid, 1, NULL, TRUE, 0, NULL, E'Soil Erosion', E'Soil is the earth''s fragile skin that anchors all life on Earth. It is comprised of countless species that create a {{1}} and complex ecosystem and is among the most precious resources to humans. Increased demand for agriculture commodities generates incentives to convert forests and grasslands to farm fields and pastures. The {{2}} to agriculture from natural vegetation often cannot hold onto the soil and many of these plants, such as coffee, cotton, palm oil, soybean and wheat, can actually increase soil erosion beyond the soil’s ability to maintain itself. The effects of soil erosion go beyond the loss of {{3}} land. It has led to increased pollution and sedimentation in streams and rivers, clogging these waterways and causing declines in fish and other {{4}} . And degraded lands are also often less able to hold onto water, which can worsen flooding. Sustainable land use can help to reduce the impacts of agriculture and livestock, preventing soil degradation and erosion and the loss of valuable land to desertification.', NULL, NULL, NULL, E'1.dynamic, 2.transition, 3.fertile, 4.species', NULL, NULL),
  ('542593b2-cc05-5332-9654-d0e85094010e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '542593b2-cc05-5332-9654-d0e85094010e'::uuid, 1, NULL, TRUE, 0, NULL, E'Invention and Innovation', E'For our purposes the words ''invention'' and ''innovation'' can be used interchangeably. More {{1}} , however, the term ''invention'' refers to the discovery of new products or processes, while ''innovation'' refers to the commercialization (bringing to the market) of new products or processes. {{2}} , we can distinguish between product innovations and process innovations. Product innovations result {{3}} the production of a new product, such as the change from a three-wheel car to a four-wheel car, or the change from LP records to CDs. Process innovations increase the {{4}} of the methods of production of existing products, for example the invention of the assembly-line technique.\nThe inventions and innovations that form industrial revolutions are those that open new doors and create new ways of doing things, not simply those that fill gaps in existing ways of doing things (Mokyr, 1997). The core of the First Industrial Revolution in the eighteenth century was a succession of technological changes that brought about material advances in three basic areas: (1) the substitution of mechanical devices (such as machines) for human labour; (2) the substitution of inanimate sources of power (such as steam) for animate sources of power (such as horse power); and (3) the substitution of mineral raw materials for vegetable or animal substances, and in general the use of new and more {{5}} raw materials.', NULL, NULL, NULL, E'1.specifically, 2.Furthermore, 3.in, 4.efficiency, 5.abundant', NULL, NULL),
  ('54303ed9-aaa2-5071-bff3-64abe3c56935'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '54303ed9-aaa2-5071-bff3-64abe3c56935'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the part that is inside a nut’s or a seed’s shell ?', 'f65722db-e427-597f-acec-be2c005f11fa'::uuid, NULL, NULL, E'Kernel', NULL, NULL),
  ('54333e3b-31b3-5745-8237-f745257f7fe6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '54333e3b-31b3-5745-8237-f745257f7fe6'::uuid, 1, NULL, TRUE, 0, NULL, E'Positive Mindset', E'Research shows that when people work with a positive mind-set, performance on nearly every level – productivity, creativity, engagement - improves. Yet happiness is perhaps the most misunderstood driver of performance. For one, most people believe that success precedes happiness. "Once I get a promotion, I''ll be happy," they think. Or, "Once I hit my sales target, I''ll feel great." But because success is a moving target – as soon as you hit your target, you raise it again, the happiness that results from success is fleeting. In fact, it works the other way around: people who cultivate a positive mind-set perform better in the face of challenge. I call this the "happiness advantage" – every business outcome shows improvement when the brain is positive. I''ve observed this effect in my role as a researcher and lecturer in 48 countries on the connection between employee happiness and success. And I''m not alone: in a meta-analysis of 225 academic studies, researchers Sonja Lyubomirsky, Laura King, and Ed Diener found strong evidence of directional causality between life satisfaction and successful business outcomes. Another common misconception is that our genetics, our environment, or a combination of the two determines how happy we are. To be sure, both factors have an impact. But one''s general sense of well-being is surprisingly malleable. The habits you cultivate, the way you interact with coworkers, how you think about stress – all these can be managed to increase your happiness and your chances of success.', NULL, NULL, E'When people work with a positive mind-set, performance on nearly every level improves, because happiness is perhaps the most misunderstood driver of performance, where most people believe that success precedes happiness, and people who cultivate a positive mind-set perform better in the face of challenge, while another common misconception is that our genetics, our environment, or a combination of the two determines how happy we are, so one''s general sense of well-being is surprisingly malleable.', NULL, 5, 75),
  ('5438cbc2-6007-535c-b43f-27ac71fea34d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', '5438cbc2-6007-535c-b43f-27ac71fea34d'::uuid, 1, NULL, TRUE, 0, NULL, E'Traffic Lights', E'Game-changing technology to design traffic lights that absorb kinetic energy, stopping them from crumpling when hit by a vehicle, will prevent thousands of fatalities and injuries each year and make our roads much safer.\nThat''s the prediction from University of South Australia (UniSA) senior lecturer and research lead Dr Mohammad Uddin, who is partnering with manufacturing company Impact Absorbing Systems (IAS) on a new project to minimise collision-related injuries as well as damage to traffic lights and vehicles.\nThe $640,000 project, partially funded by the Innovative Manufacturing CRC (IMCRC), will leverage IAS''s expertise in road safety and UniSA''s engineering design and advanced manufacturing skills to ensure traffic lights absorb a high-impact crash, remain undamaged and operational, and save pedestrian and motorists'' lives.\nThe technology involves replicating existing IAS-fabricated energy absorbing bollards and tuning the design to better suit the shape, length and size of common traffic lights, while satisfying regulatory standards.\n"Recent statistics show that in Australia, traffic light collisions cost $18.5 million a year in fatalities, $53.7 million for injuries and up to $16 million annually to repair, install and maintain traffic lights," Dr Uddin says. Worldwide, the figure is much higher.\n\nWhat are the functions of traffic lights that absorb kinetic energy?', NULL, NULL, NULL, E'Save the lives of pedestrians and drivers.\nThe normal operation.\nMake our roads safer.', NULL, NULL),
  ('5445d32c-8578-5a82-94f8-6f27e4d83df0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5445d32c-8578-5a82-94f8-6f27e4d83df0'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the property that is given by a person when he dies?', 'b71c9fd8-53e6-5845-895e-7c599c95dcab'::uuid, NULL, NULL, E'Legacy / inheritance', NULL, NULL),
  ('544aa087-114a-5d0c-a796-ade6561ef3ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '544aa087-114a-5d0c-a796-ade6561ef3ee'::uuid, 1, NULL, TRUE, 0, NULL, E'Income Inequality', E'Income inequality is a significant social issue that affects communities worldwide. The gap between the rich and the poor continues to widen, leading to social unrest and economic instability. To address this issue, governments can implement policies that promote equitable distribution of resources and opportunities.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('545137c5-d786-55b1-b434-4a23518a00df'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '545137c5-d786-55b1-b434-4a23518a00df'::uuid, 1, NULL, TRUE, 0, NULL, E'Positive Pressure', E'It is quite normal to feel under pressure, and pressure can sometimes be a positive force: it can make us feel energized and take action to get results. But if the pressure becomes too much and we tip over into the feeling of being stressed, then it can have negative impact on us and our health. However, stress is a very subjective phenomenon and it lacks a precise medical definition.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('54520565-4f25-5b88-8747-7216dc686f94'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '54520565-4f25-5b88-8747-7216dc686f94'::uuid, 1, NULL, TRUE, 0, NULL, E'Darkness', E'The increasing darkness in the Northern Hemisphere this time of year indicates to the plant that {{1}} is coming on. So it starts recouping materials from the {{2}} before they drop off. Evergreens protect their needle-like foliage from freezing with {{3}} coatings and natural "antifreeze." But broadleaf plants, like sugar maples, birches, and sumacs, have no such protections. As a result, they {{4}} their leaves. But before they do, the plants first try to {{5}} important nutrients such as nitrogen and phosphorus.', NULL, NULL, NULL, E'1.autumn, 2.leaves, 3.waxy, 4.shed, 5.salvage', NULL, NULL),
