  ('54759769-66f3-511e-8e97-f4406ace3606'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '54759769-66f3-511e-8e97-f4406ace3606'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9c83223e-5e2f-52f4-9ce4-60fe0e5519b2'::uuid, NULL, NULL, E'The new art gallery can only be visited on Fridays.', NULL, NULL),
  ('54780120-2315-5e46-a72b-3376cb7a52c9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '54780120-2315-5e46-a72b-3376cb7a52c9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '583cda5c-1a71-5a1f-ac0d-7be70b2e2813'::uuid, NULL, E'In the end the government drew back from their extreme standpoint.', NULL, NULL, NULL),
  ('547f6df9-e2a9-5155-bcbe-eeab5e21a434'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '547f6df9-e2a9-5155-bcbe-eeab5e21a434'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd4847dab-48eb-5410-83fc-a74142bd6e67'::uuid, NULL, NULL, E'Native language speakers don''t need to take language proficiency tests.', NULL, NULL),
  ('5484b5e6-c317-5c99-bed0-7373aeed8782'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '5484b5e6-c317-5c99-bed0-7373aeed8782'::uuid, 1, NULL, TRUE, 0, NULL, E'Seasonal Affective Disorder', E'Seasonal Affective Disorder (SAD), a type of depression related to changes in seasons, is a compelling example of the complex relationship between our biological rhythms and mental health. Predominantly occurring in the winter months, SAD is characterized by symptoms such as low mood, lethargy, and a loss of interest in everyday activities. Biologically, SAD is linked to the reduced exposure to sunlight during shorter winter days. This decrease in sunlight can disrupt our body''s internal clock, or circadian rhythm, which regulates sleep, hormone production, and mood. The lack of light can also lead to lower serotonin levels, a neurotransmitter associated with mood regulation, and an increase in melatonin production, which can induce sleepiness and affect mood. Interestingly, not everyone is affected by SAD in the same way, suggesting that genetic factors may also play a role. Some individuals may have a predisposition to the disorder, making them more susceptible to changes in light and seasonal shifts. Treatment for SAD often includes light therapy, which involves exposure to artificial light that mimics natural outdoor light, helping to regulate the circadian rhythm. Other approaches include psychotherapy, medications, and lifestyle changes such as increasing physical activity and spending more time outdoors. Recognizing the symptoms of SAD is crucial for timely intervention. It is important to distinguish between a simple ''winter blues'' and the more severe symptoms of SAD that impact daily functioning. Awareness and understanding of this disorder can lead to better management and improved mental health during the challenging winter months. In conclusion, Seasonal Affective Disorder exemplifies the intricate connection between environmental factors, our biological systems, and mental health. By acknowledging and addressing the unique challenges of SAD, we can better support those affected and enhance our overall approach to mental well-being.', NULL, NULL, E'Seasonal Affective Disorder highlights the complex interplay between environmental factors, like reduced winter sunlight, and mental health, affecting mood and energy through disruptions in circadian rhythms and neurotransmitter levels, with treatments including light therapy, medication, and lifestyle changes.', NULL, 5, 75),
  ('5485290e-818e-529e-8cd5-5879944be6b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5485290e-818e-529e-8cd5-5879944be6b8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Before the public performance of a play, what do actors in the play do to practice?', '4b2bddf1-1e0b-577f-8888-8aa875642d45'::uuid, NULL, NULL, E'Rehearsal / rehearse', NULL, NULL),
