  ('5494efeb-746a-5e10-a9b1-b933bb42169b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5494efeb-746a-5e10-a9b1-b933bb42169b'::uuid, 1, NULL, TRUE, 0, NULL, E'Absence for Tutorial', E'You have a tutorial at 3 P.M. on Monday afternoon, but unfortunately there is a competition that you need to attend at the same time. What would you say to your teacher?', '8b7138a1-bede-5540-9465-790bf6120fe1'::uuid, NULL, E'Respected teacher, I hope you are doing well.\nI would like to discuss an issue we have encountered with my Monday tutorial arrangement.\nIt appears that I have a tutorial at 3 p.m. on Monday, yet I have to take part in a competition at the exact same time.\nI would appreciate your opinion on this matter. Thank you for your consideration.', NULL, NULL, NULL),
  ('54962faa-9c42-56cc-a0e8-5cb41be6f16c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '54962faa-9c42-56cc-a0e8-5cb41be6f16c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '20d2d2ae-2bff-5d5e-8b45-bf4b100d425c'::uuid, NULL, NULL, E'The study of anthropology can help us to learn about society today.', NULL, NULL),
  ('549ca8e9-af6f-5168-ab3a-a793f073c574'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '549ca8e9-af6f-5168-ab3a-a793f073c574'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ae94a919-619f-5d5c-9025-5a5e64a8a7fd'::uuid, NULL, E'If their aspirations are not achieved, they become gloomy.', NULL, NULL, NULL),
  ('54c8dbb0-0f26-5084-b499-e46629cd55a0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '54c8dbb0-0f26-5084-b499-e46629cd55a0'::uuid, 1, NULL, TRUE, 0, NULL, E'Nonprofit Institutions', E'Nonprofit institutions exist to benefit a stated mission or purpose, {{1}} of whether profits are achieved. Owing to their socially beneficial purpose, nonprofit organizations are {{2}} to an entirely different set of laws — notably tax laws. While they are allowed to generate profits, they must use these funds in specific, philanthropic ways in order to maintain their nonprofit status. Marketing efforts focus on activities that {{3}} the organization’s mission. A school, college, or university might use marketing to attract students, improve academic reputation, and {{4}} donations from alumni. A museum or nonprofit theater company uses marketing to attract visitors, ticket sales, event sponsors, and philanthropic donations. Marketing for nonprofit hospitals usually {{5}} on attracting patients and strengthening reputation as a high quality health care provider.', NULL, NULL, NULL, E'1.regardless, 2.subject, 3.promote, 4.solicit, 5.focuses', NULL, NULL),
  ('54c98470-a357-5191-b580-8fcaf5703cfb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '54c98470-a357-5191-b580-8fcaf5703cfb'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e30e66c8-8bca-5620-bbf1-aa6edd960928'::uuid, NULL, NULL, E'University graduates lose their time finding jobs.', NULL, NULL),
  ('54cb7736-1aad-5652-8bd6-13bc33281d94'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', '54cb7736-1aad-5652-8bd6-13bc33281d94'::uuid, 1, NULL, TRUE, 0, NULL, E'Wound Healing', E'A protein named Agrin has been discovered to promote wound healing and repair, when it is triggered after skin tissue is injured. These findings could pave the way for the development of Agrin protein therapy to accelerate skin tissue healing for chronic wounds from diabetes or burns. The research, led by A*STAR''s Institute of Molecular and Cell Biology (IMCB), was published in the journal Nature Communications on 3 November 2021.\nOne in 20 Singaporeans is afflicted with chronic wound conditions. Complications in the healing of chronic wounds are prevalent in patients suffering from diabetes or burn injuries, and are a leading cause of amputation and decreased emotional well-being for patients. During injury, a major chunk of extracellular matrix, which helps to rebuild tissue, is lost, therefore delaying wound healing. As such, the timely replenishment of key ECM proteins may accelerate wound healing.\nIn this study, researchers have shown that timely induction or exogenous supplementation of Agrin, an ECM protein, may promote accelerated healing of injured skin tissues. Using both human and pre-clinical models, they found that physical injury to the skin tissue enhanced the expression of Agrin, which preserves the mechanical architecture of injured skin layers by repairing the skin tissue.\n\nWhich of the following statements are incorrect?', NULL, NULL, NULL, E'Agrin can heal the wound instantly.\nOne in 20 Singaporeans suffers from diabetes or burns.', NULL, NULL),
  ('54cdc8e9-cd51-5ed3-bab5-f16362bb2733'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '54cdc8e9-cd51-5ed3-bab5-f16362bb2733'::uuid, 1, NULL, TRUE, 0, NULL, E'Diversity in Workplace', E'A diverse workplace isn’t always easy to achieve, as some locations, industries, and positions tend to attract people of certain backgrounds. To {{1}} the workplace, some companies make a significant effort to reach out to diverse communities. For example, they might reach out to the veterans community, which includes thousands of individuals of all backgrounds, many of {{2}} have solid training and experience. The explosive growth in global trade means that large corporations began sending more Americans abroad, {{3}} work to other countries, and hiring non-American workers to come to the United States. Meanwhile, the Americans with Disabilities Act made it necessary for businesses to {{4}} individuals with disabilities through the addition of elevators, ramps, Braille signage, flexible work settings and hours, and more.', NULL, NULL, NULL, E'1.diversify, 2.whom, 3.outsourcing, 4.accommodate', NULL, NULL),
  ('54cfb63d-07a5-55c8-be07-a8b87ce99458'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '54cfb63d-07a5-55c8-be07-a8b87ce99458'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '86293404-4d1b-5b85-a437-5449b4613c4c'::uuid, NULL, NULL, E'There is an overlap between chemistry and other subjects.', NULL, NULL),
