  ('54d2de56-cda1-57e5-85aa-ac9c29cf190e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '54d2de56-cda1-57e5-85aa-ac9c29cf190e'::uuid, 1, NULL, TRUE, 0, NULL, E'Cat''s Age', E'Despite the youthful outward appearance, inside the cat will be getting older. It is much easier to understand how to manage our cats’ lives, health and behaviour if we can associate their age with an equivalent of our own human years. It has often been suggested that we simply need to multiply a cat’s age by seven to get a comparative human age.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('54d4c29c-9e43-52ea-ba42-c155d77fccbf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '54d4c29c-9e43-52ea-ba42-c155d77fccbf'::uuid, 1, NULL, TRUE, 0, NULL, E'Facebook', E'Facebook has defended itself against claims that using the site can damage mental health. It said while there was evidence it could negatively affect mood, the way it affected people was determined by how they used it. Facebook''s downsides could be combated by making more use of the site and interacting positively. A social media expert said the way Facebook was built made it hard to use it in those better ways.', NULL, NULL, NULL, NULL, NULL, NULL),
