  ('54e97093-1a0b-5f8d-863a-9b3d42186cee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '54e97093-1a0b-5f8d-863a-9b3d42186cee'::uuid, 1, NULL, TRUE, 0, NULL, E'Sole Aim', E'Some people believe that the sole aim of higher education is to make people ready for employment. To what extent do you agree or disagree? Discuss.', NULL, NULL, NULL, NULL, 200, 300),
  ('54eb0996-4cd7-51ee-871a-723303c0f312'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '54eb0996-4cd7-51ee-871a-723303c0f312'::uuid, 1, NULL, TRUE, 0, NULL, E'Essential CBD Gummies', E'Essential CBD Gummies contains pure concentrated doses of hemp extract known as CBD or Cannabidiol, which can help relieve even the most agonizing joint discomfort along with general muscle aches, soreness, sleep disorders, anxiety and many other {{1}} . And since it contains NO THC, it heals without the “high”. It also calms, {{2}} , and eases tension all over the body. When taken orally, Essential CBD Gummies activates those receptors in the brain and body, and soothing comfort begins to take {{3}} . The key to Essential CBD Gummies’s health benefits is the Endocannabinoid system, a network of receptors in the cells. The system is there to maintain homeostasis (balance). In response to toxins in our body, it releases cannabinoids to set things back to their {{4}} state. And our bodies are practically designed to work with the compounds in CBD, which is why we need a solution like Essential CBD Gummies that unleashes its full potential.', NULL, NULL, NULL, E'1.ailments, 2.relaxes, 3.form, 4.natural', NULL, NULL),
  ('54f00fdd-8406-5824-b80a-301e33b15645'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '54f00fdd-8406-5824-b80a-301e33b15645'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do ton, kilogram and stone measure?', 'c86168a1-9b50-529f-81c0-616d80e2aadd'::uuid, NULL, NULL, E'Weight / mass', NULL, NULL),
  ('54f245ac-d0bb-5716-997e-47f594fa9e16'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '54f245ac-d0bb-5716-997e-47f594fa9e16'::uuid, 1, NULL, TRUE, 0, NULL, E'Reasons of Attending College', E'People attend college or university for many different reasons (for example, new experiences, career preparation, or knowledge). Why do you think people attend college or university? Use specific reasons and examples to support your answer.', NULL, NULL, NULL, NULL, 200, 300),
