  ('54fdb7ad-5713-5a63-918b-3d4d7f25642e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '54fdb7ad-5713-5a63-918b-3d4d7f25642e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'We call numbers like one, three, five odd numbers, then what do we call numbers like two, four, six?', '5416f3ff-2bad-5590-89a6-f58ede714bc4'::uuid, NULL, NULL, E'Even numbers', NULL, NULL),
  ('54fefbc7-30d9-5c30-be4a-712503735336'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '54fefbc7-30d9-5c30-be4a-712503735336'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a place where people live permanently?', '690f8c6b-fc51-597e-bf53-94cb014dfb28'::uuid, NULL, NULL, E'Permanent address / home / domicile', NULL, NULL),
  ('54ff0dc5-6e04-5303-9b02-de5c9eba9e7a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '54ff0dc5-6e04-5303-9b02-de5c9eba9e7a'::uuid, 1, NULL, TRUE, 0, NULL, E'Hummingbird Tracking', E'Hummingbirds are tiny birds with long, slender beaks designed for feeding on the nectar of tubular flowers. They are only found in the Western Hemisphere, with only a few dozen species spending the winter in Central America or Mexico. After that, they fly from the southern United States towards their breeding grounds in the north from late January or February. Later in the spring, they migrate farther north and may be seen in Canada’s breeding grounds. Hummingbird tracking can be done through a website or an app that displays the migratory patterns of hummingbirds across the United States and Canada. To help track their migration, sites like Hummingbird Central host a publicly accessible Hummingbird Migration Map. Each year the site updates the interactive map with viewer-submitted sightings throughout the spring, as hummingbirds fly on, often between late January and mid-May. Every year during the winter, hummingbirds fly across states to warmer parts of the United States and Canada. A hummingbird tracker works with the help of viewers’ sightings of these birds in specific areas.\nOnce viewers spot their first sighting of hummingbirds from non-breeding sites, they fill out a form that includes details of the sighting date, the viewers’city, state, ZIP code and the species type out of the 15 most common hummingbirds in North America. However, submissions are not instantly viewable on the map, as they are updated periodically throughout the day.\nThe hummingbirds’ eventual destination changes yearly, depending on weather and environmental factors. As a result, scientists and hummingbird enthusiasts always look forward to tracking the migratory patterns each year.', NULL, NULL, NULL, NULL, 5, 75),
  ('5502920e-66a7-5710-be1c-e62d4738936d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5502920e-66a7-5710-be1c-e62d4738936d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '580b4327-ed65-589e-b4d7-ece7d68dba06'::uuid, NULL, E'This semester will be from October to January.', NULL, NULL, NULL),
