  ('550de310-cee7-5bfe-8db6-f6d4057cc7d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '550de310-cee7-5bfe-8db6-f6d4057cc7d3'::uuid, 1, NULL, TRUE, 0, NULL, E'Organic Agriculture', E'The world of organic agriculture has often been critiqued as being {{1}} more in philosophy than in science. While this criticism might hold a grain of {{2}} , it is important to note that the field of organic agriculture has made significant {{3}} in recent years in developing and testing scientific methods that support its {{4}} .', NULL, NULL, NULL, E'1.rooted, 2.truth, 3.strides, 4.practices', NULL, NULL),
  ('5510f9f5-abe7-53b5-b9d9-3342dbf967db'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5510f9f5-abe7-53b5-b9d9-3342dbf967db'::uuid, 1, NULL, TRUE, 0, NULL, E'Group Presentation', E'You''re preparing for a group presentation, and your team members suggest incorporating complex charts and graphs into the slides. However, you realize that these visuals might confuse the audience and distract from the main points. You need to gently steer the discussion towards simpler and clearer visuals that enhance understanding. What would you say to your team members?', '92de7b84-213c-558d-991b-37d36f455292'::uuid, NULL, E'Hey guys, I appreciate the suggestion for the presentation slides. However, let''s aim for simpler visuals to ensure our audience grasps the main points easily. How about we use straightforward charts and diagrams that highlight key information without overwhelming them? This way, we can enhance understanding and keep everyone engaged throughout the presentation. Let''s prioritize clarity and effectiveness in our visuals.', NULL, NULL, NULL),
  ('55124799-b70f-5e17-9903-9120e57591bf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '55124799-b70f-5e17-9903-9120e57591bf'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4d113ee4-566a-5d1c-89f2-de1c12979223'::uuid, NULL, E'He refused to comment before he had reviewed all the relevant information.', NULL, NULL, NULL),
