  ('55897aa0-02b9-517b-8b13-f47d93e831e2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '55897aa0-02b9-517b-8b13-f47d93e831e2'::uuid, 1, NULL, TRUE, 0, NULL, E'History', E'Centuries ago, in a time long forgotten, great civilizations rose and fell, leaving behind a legacy etched in the annals of history. From the majestic pyramids of Egypt to the grandeur of ancient Rome, each era had its triumphs and tribulations. The tales of conquerors and visionaries, heroes and villains, continue to captivate our imagination.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('5596c8ef-311e-5d20-87ca-b7d8a8aa24a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5596c8ef-311e-5d20-87ca-b7d8a8aa24a8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which human organ does food go into and begin to be digested first?', '0ac96b69-e1ca-5a36-8b0b-748792976bcb'::uuid, NULL, NULL, E'Stomach', NULL, NULL),
  ('559abd67-d744-57a0-aedf-289a509459df'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '559abd67-d744-57a0-aedf-289a509459df'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4175af11-c25c-5502-b174-1d419fac2ba9'::uuid, NULL, NULL, E'Gadgets and apps are really making our normal days different.', NULL, NULL),
  ('559b9156-568f-5b4b-a0c6-e36ef4c40f92'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '559b9156-568f-5b4b-a0c6-e36ef4c40f92'::uuid, 1, NULL, TRUE, 0, NULL, E'David Thorne', E'David Thorne doesn''t encounter angst-ridden teenagers in his daily grind. Instead, his clients are hardened CEOs and corporate executives {{1}} with the intricacies of employee engagement and organizational change. "Executives need someone who speaks their language," he explains. Originally a motivational speaker, Thorne now acts as a corporate consultant, working one-on-one with leadership teams to navigate complex workplace dynamics. His clients, often {{2}} to the cutthroat world of business, {{3}} themselves ill-equipped for the nuanced emotions and delicate interactions that fuel a thriving organization. "Leaders today are {{4}} to quick fixes and bottom lines," he says. "Suddenly, they''re faced with a workforce that craves purpose and belonging, and the old playbook doesn''t work anymore." Nicknamed the "Empathy Architect" for his ability to bridge the gap between executive vision and employee needs, Thorne is launching a series of online workshops designed to equip leaders with the tools they need to build a more engaged and {{5}} workforce. The role of the corporate consultant, he argues, has evolved alongside the changing landscape of work, becoming indispensable for leaders who want to thrive in an increasingly human-centric business environment.', NULL, NULL, NULL, E'1.grappling, 2.accustomed, 3.find, 4.used, 5.productive', NULL, NULL),
  ('559be10c-4999-5b8b-8eae-35508916f4b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '559be10c-4999-5b8b-8eae-35508916f4b9'::uuid, 1, NULL, TRUE, 0, NULL, E'Live Performance', E'Attending a live performance, such as a play, is more enjoyable than watching the same event through the internet. Do you agree or disagree?', NULL, NULL, NULL, NULL, 200, 300),
  ('55a04e88-2283-5502-af61-e9561de8d05c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '55a04e88-2283-5502-af61-e9561de8d05c'::uuid, 1, NULL, TRUE, 0, NULL, E'Planetary Rings', E'Planetary rings are some of the most spectacular features in our solar system, consisting of countless particles orbiting around a planet. They are formed by a variety of processes, including collisions between moons and gravitational interactions with nearby planets. Studying planetary rings can provide insights into the formation and evolution of planetary systems.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('55a075a6-dc6f-5deb-a1d8-9a107e7fc9e7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '55a075a6-dc6f-5deb-a1d8-9a107e7fc9e7'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the tropical fruit with a rough, brown skin and sweet, water-filled interior?', '083d07a0-0a76-5770-b7f7-165c391fdd11'::uuid, NULL, NULL, E'Coconut', NULL, NULL),
