  ('55d1dce5-037b-5817-9e4a-99cef9bdb0c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '55d1dce5-037b-5817-9e4a-99cef9bdb0c8'::uuid, 1, NULL, TRUE, 0, NULL, E'Health Concept', E'The concept of health holds different meanings for different people and groups. These meanings of health have also {{1}} over time. This difference is no more {{2}} than in Western society today, when {{3}} of health and health promotion are being challenged and {{4}} in new ways.', NULL, NULL, NULL, E'1.changed, 2.evident, 3.notions, 4.expanded', NULL, NULL),
