  ('5658b121-6998-591c-abb6-9ba47823c4c2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5658b121-6998-591c-abb6-9ba47823c4c2'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Where would you go to see an exhibition of sculptures?', '611a699b-ed48-59ac-aeb6-29a332bca6ec'::uuid, NULL, NULL, E'Art gallery / Museum', NULL, NULL),
  ('565b0132-e2e8-5929-9b3c-fe9047e71892'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '565b0132-e2e8-5929-9b3c-fe9047e71892'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a flying machine?', '9e45530b-494b-5e84-9c76-91c465b02c7d'::uuid, NULL, NULL, E'Aircraft', NULL, NULL),
  ('5661885f-4f77-59ba-8004-2d3192ef4db1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5661885f-4f77-59ba-8004-2d3192ef4db1'::uuid, 1, NULL, TRUE, 0, NULL, E'Sleep Cycle', NULL, '3d26c04a-b4f1-5f3e-89ce-4056156e17b8'::uuid, NULL, E'Did you ever wonder why it is that most people are "programmed" to sleep at night instead of during the day? If there''s something about the cycle of light and dark that''s telling us when to sleep, then shouldn''t the sleep cycle of a blind person be different? As it turns out, many blind people—people with no visual perception of light at all—do have the same sleep cycle as sighted people. So now you''re wondering, "How can this happen?" The answer is: hormones, one hormone in particular. It''s called melatonin. In sighted people, the level of melatonin goes up at night, or when it''s dark, and goes down in the day, or when it''s light. It''s believed that it''s the presence of this hormone in the blood that gives us the urge to sleep. If an increase in melatonin level "programs" sighted people to sleep at night, then what about blind people? A researcher, named Dr. Charles Czeisler, tells about an interesting experiment. He tried shining a bright light into the eyes of some blind people. When he did this, he noticed that the level of the melatonin in the blood of these subjects went down just as it would do for sighted people. Somehow, the eyes of these subjects, even though they were damaged and had no visual perception of light, could tell their brain when there was more or less light. Now, this doesn''t work for all blind people; in fact, most of Czeisler''s subjects had no hormonal response to light at all. Further research may be able to explain this sensitivity to light in terms of the type of blindness of the subject.', NULL, NULL, NULL),
  ('56627ac1-ddea-555b-a79e-952781f7cd4f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '56627ac1-ddea-555b-a79e-952781f7cd4f'::uuid, 1, NULL, TRUE, 0, NULL, E'Retirement Community', E'Nowadays, some seniors choose to live in retirement communities with other old people rather than live with their adult children. What are the advantage or disadvantages of this phenomenon?', NULL, NULL, NULL, NULL, 200, 300),
