  ('57260079-dcb6-5667-a31e-29a765892499'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '57260079-dcb6-5667-a31e-29a765892499'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f1d53b56-1c83-5e2a-9499-74ac45462bfa'::uuid, NULL, NULL, E'Working in the lab presents us with numerous challenges daily.', NULL, NULL),
  ('572b42b3-af3b-5110-9ba2-d96a8daec2c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '572b42b3-af3b-5110-9ba2-d96a8daec2c4'::uuid, 1, NULL, TRUE, 0, NULL, E'Legal Deposit', E'Legal deposit has existed in English law since 1662. It helps to ensure that the nation’s published output (and thereby its {{1}} record and future published heritage) is collected systematically, to {{2}} the material for the use of future generations and to make it available for {{3}} within the designated legal deposit libraries. The legal deposit system also has {{4}} for authors and publishers:\nDeposited publications are made available to users of the deposit libraries on their premises, are preserved for the benefit of future generations, and become part of the nation’s heritage. Publications are {{5}} in the online catalogues, and become an essential {{6}} tool for future generations.', NULL, NULL, NULL, E'1.intellectual, 2.preserve, 3.readers, 4.benefits, 5.recorded, 6.research', NULL, NULL),
  ('572e743e-0e3c-5660-8040-fe04ef76006e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '572e743e-0e3c-5660-8040-fe04ef76006e'::uuid, 1, NULL, TRUE, 0, NULL, E'Japan', E'Japan is the world''s calculator superpower. Japanese manufacturers have led sales of calculators for over 30 years in many countries. Even in the age of personal computers, calculators are still essential in accounting jobs. In addition, calculators with graphing capabilities have begun to be used in education.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('573450f8-25df-5816-ba53-d8230993dc7b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '573450f8-25df-5816-ba53-d8230993dc7b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8bc09be3-e381-53bd-b114-394a8f140441'::uuid, NULL, NULL, E'Higher numbers of patients were infected during previous outbreaks of illness.', NULL, NULL),
  ('57437879-8c8f-5c9c-b0c7-3ea2b1e53a56'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '57437879-8c8f-5c9c-b0c7-3ea2b1e53a56'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '61c81636-cd3c-5f1d-9f99-fb9f7f96a561'::uuid, NULL, E'In the upcoming lecture, the professor will review the summary.', NULL, NULL, NULL),
  ('57455206-9ca5-5873-b99c-cdd9e68a49b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'HIGHLIGHT_CORRECT_SUMMARY', E'HIGHLIGHT_CORRECT_SUMMARY', E'LISTENING', E'SHARED', NULL, E'APPROVED', '57455206-9ca5-5873-b99c-cdd9e68a49b2'::uuid, 1, NULL, TRUE, 0, NULL, E'Workplace Models', E'Now, one of the workplace models I want to look at today is telecommuting. Done properly, telecommuting makes good business sense and companies can make huge savings on their overheads.\nIt can also be a very effective lure to recruit quality employees, but companies need to plan ahead and create the right culture for it to work. It''s not as simple as just giving everybody a laptop and sending them off to work from home. Management needs to look at training, security and communication issues before any kind of telecommuting agreement is entered into.\nNow, a key part of making it work is ensuring that every employee - and that''s whether they''re at home or in the office - has equal access to resources and, of course, promotions. The last thing you want is to create a kind of ''us versus them'' scenario. The arrangement breaks down quickly if people start feeling isolated, or limited in their chances of moving up the ladder if they aren''t physically in the office.\nThere has to be foresight, right from the start, in the hiring process. It''s vital to screen employees carefully to determine who will be able to prosper working away from the office. Some companies give personality tests to prospective workers - and they do them online or over the phone to see if they''re comfortable with that type of set up.\n\nClick on the paragraph that best relates to the recording.', 'c2ddafd0-e80c-56be-91f1-c29e398b31b0'::uuid, NULL, NULL, E'Telecommuting has a lot of advantages but to make it work, company leaders need to plan in advance to ensure that they anticipate issues for example training, security and communication. They also need to ensure that they hire workers who are suited to working remotely and ensure equal access to resources and advancement.', NULL, NULL),
  ('57491b5e-0d08-5af3-8531-93138bcfeec1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '57491b5e-0d08-5af3-8531-93138bcfeec1'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Correlation is the relationship between cause and what?', '4a632f3e-c5ce-52d4-81f2-072e96a1635c'::uuid, NULL, NULL, E'Effect', NULL, NULL),
