  ('5776fdf5-7b8f-5411-b862-97a7f4e16bbf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5776fdf5-7b8f-5411-b862-97a7f4e16bbf'::uuid, 1, NULL, TRUE, 0, NULL, E'Lullaby', E'A lullaby or cradle song, is a soothing song or piece of music that is usually played for children. The purposes of lullabies vary. In some societies they are used to pass down cultural knowledge or tradition. Lullabies can be found in many countries, and have existed since ancient times.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('5778a624-7acb-50cd-aaa7-7b4eac111564'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '5778a624-7acb-50cd-aaa7-7b4eac111564'::uuid, 1, NULL, TRUE, 0, NULL, E'World Shakespeare Congress', E'Over 800 Shakespeare scholars from almost fifty countries will gather at King’s College\nLondon next week as the university co-hosts the 10th World Shakespeare Congress to explore and honor the Bard’s life and work.\nOrganised by the International Shakespeare Association (ISA) the World Congress {{1}} held every five years and 2016 is the first time it will be co-hosted {{2}} two locations that were integral to both the personal and working life of William Shakespeare. Delegates will arrive in London on Thursday following the start of the Congress on Sunday in Stratford-upon-Avon. {{3}} a main theme of ‘Creating and Recreating Shakespeare’, the Congress will look {{4}} the continuing global relevance of Shakespeare’s work through a varied program of plenaries, panels, seminars and workshops.', NULL, NULL, NULL, E'1.is, 2.in, 3.With, 4.at', NULL, NULL),
  ('577df7cf-d563-5108-9090-4af3ab5496a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '577df7cf-d563-5108-9090-4af3ab5496a8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Where are many valuable and historical objects displayed to the public?', '71afaeb8-f764-56d0-a729-a8c251613ac5'::uuid, NULL, NULL, E'Museum', NULL, NULL),
  ('577e2608-3887-50ca-82c2-256232487a0f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '577e2608-3887-50ca-82c2-256232487a0f'::uuid, 1, NULL, TRUE, 0, NULL, E'Youth and Technology', E'Teachers are in a unique {{1}} when it comes to assessing how children and young people use technology such as mobile phones and the {{2}} it has on them. They see how children and young people use technology to learn and {{3}} , and how it affects their relationships with their {{4}} .', NULL, NULL, NULL, E'1.position, 2.effect, 3.socialize, 4.peers', NULL, NULL),
  ('578156d5-f8e3-5e0b-a748-350296a93415'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '578156d5-f8e3-5e0b-a748-350296a93415'::uuid, 1, NULL, TRUE, 0, NULL, E'Scientific Evidence', E'The latest scientific evidence on the nature and strength of the links between diet and chronic diseases is examined and discussed in detail in the following sections of this report. This section gives an overall view of the current situation and trends in chronic diseases at the global level.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('5784e5e9-7c20-5ec7-b45e-62a8ad8f0d21'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '5784e5e9-7c20-5ec7-b45e-62a8ad8f0d21'::uuid, 1, NULL, TRUE, 0, NULL, E'Sandra Lousada', E'London''s National Portrait Gallery is currently celebrating the fifty-year {{1}} of photographer Sandra Lousada. The twenty-one portraits on display depict key {{2}} in literature, film and fashion from the early 1960s. Subsequent to the acquisition of forty portraits by Lousada, the {{3}} at The National Portrait Gallery highlights shots taken between 1960 and 1964, many of which feature in Lousada''s book Public Faces Private Places (2008). Formal commissioned portraits are shown alongside behind-the-scenes photographs taken on film {{4}} and unguarded portraits of sitters captured at home.', NULL, NULL, NULL, E'1.career, 2.figures, 3.display, 4.sets', NULL, NULL),
  ('57911ecb-f3d2-55df-80d0-79e4940bfa2a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '57911ecb-f3d2-55df-80d0-79e4940bfa2a'::uuid, 1, NULL, TRUE, 0, NULL, E'Marine Creature', NULL, NULL, NULL, NULL, E'4, 2, 3, 1', NULL, NULL),
