  ('57ddd8e9-37c8-5cb1-ba3f-2689a65b85ba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '57ddd8e9-37c8-5cb1-ba3f-2689a65b85ba'::uuid, 1, NULL, TRUE, 0, NULL, E'Leaves’ Color', E'Leaves {{1}} from trees in autumn because as temperatures drop, the tree’s internal temperature is also dropping. The amount of light that plants can work with to produce photosynthesis also {{2}} . Leaves are losing {{3}} and they can’t photosynthesize as well due to lower light levels so they lose their greenness.', NULL, NULL, NULL, E'1.fall, 2.decreases, 3.nutrients', NULL, NULL),
  ('57debfc9-ea25-5f88-847e-69a718076529'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '57debfc9-ea25-5f88-847e-69a718076529'::uuid, 1, NULL, TRUE, 0, NULL, E'Indian businessmen(印度商人)', NULL, NULL, NULL, NULL, E'2, 3, 5, 1, 4', NULL, NULL),
  ('57f21698-f575-543d-a39a-64ef3e2601a9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '57f21698-f575-543d-a39a-64ef3e2601a9'::uuid, 1, NULL, TRUE, 0, NULL, E'Emigration', E'Many people choose to emigrate to other countries. What are the advantages and disadvantages of living in a foreign country? Discuss with your own experience.', NULL, NULL, E'Emigrating to another country is a major decision that many people make in their lives. While it can be a life-changing experience, it also comes with its own set of advantages and disadvantages. This essay will explore both perspectives, providing examples to support each viewpoint.\nLiving in a foreign country can provide many advantages. It can provide opportunities for personal and professional growth. When individuals move to a new country, they are exposed to new experiences and challenges that can help them develop new skills and perspectives. This can lead to personal growth and increased career opportunities.\nHowever, there are also potential disadvantages to living in a foreign country. It can be challenging due to language barriers and cultural differences. When individuals move to a new country, they may struggle to communicate effectively and navigate cultural norms. This can lead to misunderstandings and difficulties in adjusting to the new environment.\nIn conclusion, living in a foreign country has both advantages and disadvantages. While it can provide opportunities for personal and professional growth, as well as cultural enrichment and new experiences, it can also be challenging due to language barriers, cultural differences, and emotional strain. To mitigate potential negative consequences, individuals should research the new environment thoroughly and seek out support networks. By doing so, they can harness the benefits of living in a foreign country while minimizing potential drawbacks.', NULL, 200, 300),
  ('57f26bc8-8ec3-5b39-9037-6c95d6103dd3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '57f26bc8-8ec3-5b39-9037-6c95d6103dd3'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a set of shared beliefs and practices associated with supernatural powers?', 'd4596bf0-a9c6-5636-bdcd-1ef915ff7f8a'::uuid, NULL, NULL, E'Religion', NULL, NULL),
  ('57fa320d-ef97-5157-8f66-6f05b0a348af'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '57fa320d-ef97-5157-8f66-6f05b0a348af'::uuid, 1, NULL, TRUE, 0, NULL, E'Carbon Prices', E'Carbon prices in the European Union also reached their highest level in a decade this summer following a series of {{1}} meant to limit the oversupply of {{2}} and expand many industries subjected to the cap. The biggest development of all may be in China, the world''s largest greenhouse gas emitter, which has taken steps toward its own {{3}} trading program. China''s move has the {{4}} to narrow the gap between global carbon prices and climate costs to 63 percent in the early 2020s, OECD found.', NULL, NULL, NULL, E'1.reforms, 2.credits, 3.emissions, 4.potential', NULL, NULL),
  ('57fba1a5-1c0e-5e7c-8557-4469cd8aa4c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '57fba1a5-1c0e-5e7c-8557-4469cd8aa4c0'::uuid, 1, NULL, TRUE, 0, NULL, E'Yellow', E'Yellow is considered as the most optimistic color. Yet surprisingly, people lose their tempers more often in yellow rooms and babies cry more in them. The reason may be that yellow is the hardest color for eyes to take in. So it can be overpowering if overused.', NULL, NULL, NULL, NULL, NULL, NULL),
