  ('584193e8-aecb-5a3f-8d2b-2960739eeb14'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '584193e8-aecb-5a3f-8d2b-2960739eeb14'::uuid, 1, NULL, TRUE, 0, NULL, E'Nightmares', E'Visions from nightmares can also creep like dark shadows into the light of the next day, {{1}} a person’s ability to focus and think. Mood {{2}} , and anxiety rises, which can lead to a diagnosis of nightmare disorder, a sleep condition that {{3}} about 4% of adults.', NULL, NULL, NULL, E'1.disrupting, 2.plummets, 3.affects', NULL, NULL),
  ('584494f2-b5f8-5519-b61b-384edbe89193'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '584494f2-b5f8-5519-b61b-384edbe89193'::uuid, 1, NULL, TRUE, 0, NULL, E'Management', E'Management is everywhere. Any time people work to achieve a goal, they are {{1}} in management. At least as {{2}} back as the building of pyramids in ancient Egypt or Mesoamerica, people have used principles of management to achieve goals. Today, organizations of all types use management techniques to plan and {{3}} their activities.', NULL, NULL, NULL, E'1.engaging, 2.far, 3.organize', NULL, NULL),
  ('584593d1-3a8e-5bdd-aafc-c88bc117d693'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '584593d1-3a8e-5bdd-aafc-c88bc117d693'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4dcc0ef4-4cef-542d-bb3d-69a8f10815d0'::uuid, NULL, NULL, E'The textile sector plays a major role in economic enhancement.', NULL, NULL),
