  ('58c8892e-28b7-5744-9338-637a52744900'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '58c8892e-28b7-5744-9338-637a52744900'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '1142a09d-cddf-5ee4-afd3-7fcecfeeaa49'::uuid, NULL, E'He used different brushes to make his art more interesting.', NULL, NULL, NULL),
  ('58d07024-b513-54d7-b8e3-3e416e1b168e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '58d07024-b513-54d7-b8e3-3e416e1b168e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the world''s largest reef system?', 'c7b024ac-1451-5550-8d2d-7d3ac0f24bd8'::uuid, NULL, NULL, E'Great Barrier Reef', NULL, NULL),
  ('58d6807d-5445-5e56-bcfb-10969ed5e173'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '58d6807d-5445-5e56-bcfb-10969ed5e173'::uuid, 1, NULL, TRUE, 0, NULL, E'Rehabilitation', E'Globally, 1 in 3 people today are estimated to be living with a health condition that would benefit {{1}} rehabilitation. People are living longer but with more {{2}} disease and disability. Currently, many people are living with mid- and long-term {{3}} of COVID-19 and may be in need of rehabilitation to support their recovery from the disease.', NULL, NULL, NULL, E'1.from, 2.chronic, 3.consequences', NULL, NULL),
  ('58da587c-72e5-5ee7-bede-684056d4e109'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '58da587c-72e5-5ee7-bede-684056d4e109'::uuid, 1, NULL, TRUE, 0, NULL, E'Aleutian Islands', E'Alaska''s Aleutian Islands have long been accustomed to shipwrecks. They have been part of local consciousness since a Japanese whaling ship ran {{1}} near the western end of the 1,100-mile (1,800-km) volcanic {{2}} in 1780, inadvertently naming what is now Rat Island when the ship''s infestation {{3}} ashore and made itself at home. Since then, there have been at least 190 shipwrecks in the islands.', NULL, NULL, NULL, E'1.aground, 2.archipelago, 3.scurried', NULL, NULL),
  ('58da848e-4056-5203-b400-823587b906e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '58da848e-4056-5203-b400-823587b906e1'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call drawings or writing on a wall, especially in a public place?', '10a0e47b-66ce-5d01-81e0-aefee54f138d'::uuid, NULL, NULL, E'Graffiti', NULL, NULL),
  ('58dafd18-e468-5291-a2ba-e5117c0a4e21'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '58dafd18-e468-5291-a2ba-e5117c0a4e21'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-R', E'The transition from forest to treeless tundra on a mountain slope is often a dramatic one. Within a vertical distance of just a few tens of meters, trees disappear as a life-form and are replaced by low shrubs, herbs, and grasses. This rapid zone of transition is called the upper timberline or tree line. In many semiarid areas there is also a lower timberline where the forest passes into steppe or desert at its lower edge, usually because of a lack of moisture.The upper timberline, like the snow line, is highest in the tropics and lowest in the Polar Regions. It ranges from sea level in the Polar Regions to 4,500 meters in the dry subtropics and 3,500-4,500 meters in the moist tropics. Timberline trees are normally evergreens, suggesting that these have some advantage over deciduous trees (those that lose their leaves) in the extreme environments of the upper timberline. There are some areas, however, where broadleaf deciduous trees form the timberline. Species of birch, for example, may occur at the timberline in parts of the Himalayas.At the upper timberline the trees begin to become twisted and deformed. This is particularly true for trees in the middle and upper latitudes, which tend to attain greater heights on ridges, whereas in the tropics the trees reach their greater heights in the valleys. This is because middle- and upper- latitude timberlines are strongly influenced by the duration and depth of the snow cover. As the snow is deeper and lasts longer in the valleys, trees tend to attain greater heights on the ridges, even though they are more exposed to high-velocity winds and poor, thin soils there. In the tropics, the valleys appear to be more favorable because they are less prone to dry out, they have less frost, and they have deeper soils.\n\nWhich of the following can be inferred from this passage about both the upper and lower timberlines?', NULL, NULL, NULL, E'Both mark forest boundaries.', NULL, NULL),
  ('58dc4bb8-a389-5b26-9c3c-ce2039fc4037'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '58dc4bb8-a389-5b26-9c3c-ce2039fc4037'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '727dad2e-0fbb-5d0d-ace7-96c6819de004'::uuid, NULL, E'The newspaper job had me doing the same thing day after day.', NULL, NULL, NULL),
