  ('58eb0f34-9bb7-5a30-9dcf-076311bb9266'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '58eb0f34-9bb7-5a30-9dcf-076311bb9266'::uuid, 1, NULL, TRUE, 0, NULL, E'Reproduction among Sharks', NULL, NULL, NULL, NULL, E'4, 1, 2, 3', NULL, NULL),
  ('58eb4c27-a481-5fbf-94bb-58e69e2726ab'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '58eb4c27-a481-5fbf-94bb-58e69e2726ab'::uuid, 1, NULL, TRUE, 0, NULL, E'Generosity', E'Americans approached a record level of generosity last year. Of the $260.28bn given to charity in 2005, 76.5 percent of it came from individual {{1}} . These people gave across the range of nonprofit bodies, from museums to hospitals to religious organizations, with a heavy {{2}} on disaster relief after the Asian tsunami and US hurricanes. In total, Americans gave away 2.2 per cent of their household income in 2005, slightly above the 40-year {{3}} of 2.1 per cent.', NULL, NULL, NULL, E'1.donors, 2.emphasis, 3.average', NULL, NULL),
  ('58ef239d-ba9b-5ae8-b9bc-bc7e8183912c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '58ef239d-ba9b-5ae8-b9bc-bc7e8183912c'::uuid, 1, NULL, TRUE, 0, NULL, E'Earthquake and Fault', NULL, '36bb1e54-65d8-5c8e-9efb-45c26ce00a7a'::uuid, NULL, E'Today, we will discuss the relationship between the fault lines in the Earth''s crust and an earthquake. This dislocation of the rock occurs from the Earth''s surface, seven kilometers to several hundred kilometers vertically down to the crust. The earthquake''s focus is called epicenter which is vertically beneath the interior of the Earth''s crust and the energy releases and transfers through epicenter. The faults are the fracture on the Earth''s crust. The position of the epicenters can be identified by the faults'' maps, looking down from the center of the Earth. It will result in seismic wave which is decreased as it moved away from the epicenter.', NULL, NULL, NULL),
  ('58f8e786-ad93-5717-b6f8-97c83436c6e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '58f8e786-ad93-5717-b6f8-97c83436c6e1'::uuid, 1, NULL, TRUE, 0, NULL, E'Tokyo', NULL, NULL, NULL, NULL, E'3, 5, 4, 2, 1', NULL, NULL),
