  ('5904afde-5462-52cd-bb5d-163756daea45'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '5904afde-5462-52cd-bb5d-163756daea45'::uuid, 1, NULL, TRUE, 0, NULL, E'Native Species', E'Of the more than 1,000 bat species worldwide, 22 are {{1}} to North America. And while there are no pollinator bats in our area, gardeners should {{2}} those that do live here, because they''re insectivorous. These bats {{3}} moths, beetles and mosquitoes, and can eat up to 500 mosquito-sized insects per hour. They also protect gardens and crops from such {{4}} as cucumber beetles, cutworms and leafhoppers.', NULL, NULL, NULL, E'1.native, 2.champion, 3.consume, 4.pests', NULL, NULL),
  ('5906baf0-3c2c-5dbb-987b-0b6cdf2be737'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5906baf0-3c2c-5dbb-987b-0b6cdf2be737'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7a96735d-946d-54c7-acb2-43edcc5c1902'::uuid, NULL, E'Transport has always been the key to developing international trade in this century.', NULL, NULL, NULL),
