  ('59295a02-ca91-5e6d-884e-9a2a6448334b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '59295a02-ca91-5e6d-884e-9a2a6448334b'::uuid, 1, NULL, TRUE, 0, NULL, E'Regular Exercise', E'Regular exercise releases brain chemicals key for memory, concentration, and mental sharpness at the same time as lifting your mood, and lowering stress and anxiety all of which contribute to brain health. Studies show that regular exercise helps you manage complex tasks, organize and razor-sharpen your focus which is great for those long revision sessions or particularly complex exam questions.', NULL, NULL, NULL, NULL, NULL, NULL),
