  ('5936e428-0a27-5164-b716-245028841139'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5936e428-0a27-5164-b716-245028841139'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What kind of food do almonds, pistachios and walnuts fall into?', '132678e4-83d5-5ca0-bd60-ef2c0ed6d17a'::uuid, NULL, NULL, E'Nut', NULL, NULL),
  ('59372438-7f0a-54df-a7de-0068cb0486bc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '59372438-7f0a-54df-a7de-0068cb0486bc'::uuid, 1, NULL, TRUE, 0, NULL, E'Concrete Jungle', E'Spending too much time in the concrete jungle is bad for city {{1}} '' health and could have potentially catastrophic {{2}} for the environment, conservation biologist Richard Fuller will argue during a seminar at the University of Canberra today. Dr Fuller, a {{3}} in biodiversity and conservation at the University of Queens'' and CSIRO, will explore the fact that although there''s evidence that the well-being of humans increases with {{4}} to our surrounding biodiversity, the {{5}} for people to experience nature are declining rapidly in the modern world.', NULL, NULL, NULL, E'1.dwellers, 2.consequences, 3.lecturer, 4.exposure, 5.opportunities', NULL, NULL),
  ('593c76cb-4d51-558a-b49f-c0a65d652afc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '593c76cb-4d51-558a-b49f-c0a65d652afc'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '32227887-fc29-5c08-a32f-7d6bba0c02cb'::uuid, NULL, NULL, E'The whole point of the project was to look at the norm not the exception.', NULL, NULL),
