  ('5953d339-36a8-5abd-987e-4ae9c43a2f94'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5953d339-36a8-5abd-987e-4ae9c43a2f94'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '711c220e-459b-5772-be5d-3491f394a021'::uuid, NULL, NULL, E'The discussion aims to make admission to school more transparent.', NULL, NULL),
  ('595a8214-b4bf-5ec1-913a-37a1dae0af94'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '595a8214-b4bf-5ec1-913a-37a1dae0af94'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3d0a2e09-fa52-55f5-8e78-4deccdc7d512'::uuid, NULL, NULL, E'These students learned a lot from teachers who knew a lot.', NULL, NULL),
  ('596077ae-f08b-5a6f-a618-1656b4170765'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '596077ae-f08b-5a6f-a618-1656b4170765'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What word do we use to describe people who are subject to death?', '8eb06b51-0eb6-5929-9e56-bd4ca1c625a4'::uuid, NULL, NULL, E'Mortal', NULL, NULL),
  ('59620fa0-ffdc-5552-aab4-7e3d2ed80731'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '59620fa0-ffdc-5552-aab4-7e3d2ed80731'::uuid, 1, NULL, TRUE, 0, NULL, E'Flower Color', E'A flower''s colour, however, isn''t a full-proof guide to a good lunch. That''s because the colour can change depending on the angle at which sunlight hits its petals. A yellow flower, for example, may look somewhat blue from one angle and red from another. Scientists call this kind of colour change iridescence. ''It''s the same {{1}} that makes a rainbow appear in a soap bubble or on a CD,'' says Beverley Glover. She studies plants at the University of Cambridge in England.\nIn 2009, Glover and her colleagues showed that even when petals look {{2}} , bees can still tell which flowers likely hold food. But she and others noticed something odd about iridescence. It''s not quite as flashy in plants as in other life forms, Glover says. The backs of jewel, beetles, or the wings of certain butterflies, for instance, shine and shimmer a lot more.\nThe researchers tested their hypothesis in the lab. They trained a group of bees to associate fake purple flowers with getting more nectar. Then the team tested the bees. They added non-shimmery {{3}} flowers with purple-blue and purple-red hues to the bees'' flight path. The bees passed the test, ignoring flowers that weren''t perfectly purple.\nSecond group of bees was trained to drink from fully flashy, ''perfectly iridescent'' purple flowers. But when the team added perfectly iridescent flowers in different hues, the insects checked them for nectar, too.\nA third group of bees, however, had no problem finding the right flowers when the petals had only a little bit of bling. These bees were trained to drink from '' {{4}} iridescent'' purple flowers. When the team added imperfectly iridescent flowers in different hues, the bees weren''t confused at all. ''They could still clearly identify the purple flowers as the good ones,'' Glover says. That means imperfect iridescence is best for bees.', NULL, NULL, NULL, E'1.phenomenon, 2.shimmery, 3.fake, 4.imperfectly', NULL, NULL),
  ('596aa95e-0a8a-5ae6-83d8-18a5a156c996'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '596aa95e-0a8a-5ae6-83d8-18a5a156c996'::uuid, 1, NULL, TRUE, 0, NULL, E'Biology', NULL, NULL, NULL, NULL, E'4, 3, 2, 5, 1', NULL, NULL),
