  ('59902219-9467-5d32-b354-1e70aacd86e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '59902219-9467-5d32-b354-1e70aacd86e1'::uuid, 1, NULL, TRUE, 0, NULL, E'Information Office', E'Our information office on campus provided resource and support to help you make the right choices about childcare — whether you''re a student, staff, or member of the local community. The office provides information about the five centers closest to our campuses, relevant government agency, and other daycare centers in the surrounding areas.', NULL, NULL, NULL, NULL, NULL, NULL),
