  ('5992889f-dd22-5f80-a0c2-2fa8c12a4a57'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5992889f-dd22-5f80-a0c2-2fa8c12a4a57'::uuid, 1, NULL, TRUE, 0, NULL, E'City Space', NULL, 'ecd7723a-7c4e-5d8b-81d3-86aac045bfc3'::uuid, NULL, E'I want to explore certain issues with you. There is no conclusion to my top, there is no closure. I think over time throughout history, cities have changed in whether they were strategic spaces or routinized spaces. This, our global modernity is the time when cities are strategic. That doesn''t mean all cities but that means that certain city throughout the world becomes spaces where our most acute problems our major government challenges hit the ground, become concrete, become urgent. The city, urban space has a capacity to pull down a lot of stuff that otherwise stated up there. Take the environmental question national states can talk and talk and talk for years. Kyoto took years but in the meantime, cities had to deal with the environment list.', NULL, NULL, NULL),
  ('5994b4c6-d7b8-58e4-8c30-97766f4fd862'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5994b4c6-d7b8-58e4-8c30-97766f4fd862'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call someone who drives a vehicle, especially as a profession?', 'c55615b8-8161-5031-811d-5f0496dc518a'::uuid, NULL, NULL, E'Driver', NULL, NULL),
