  ('59dc6bf4-53f8-5d4b-bdff-dbc89ae4c8fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '59dc6bf4-53f8-5d4b-bdff-dbc89ae4c8fd'::uuid, 1, NULL, TRUE, 0, NULL, E'College Application Process', E'The college application process can be daunting, but with careful planning, research, and preparation, students can maximize their chances of getting accepted to their top-choice schools. This process typically involves researching colleges and universities that match one''s interests and qualifications, preparing for standardized tests like the SAT or ACT, and crafting a compelling personal statement or essay that highlights one''s strengths and achievements.', NULL, NULL, NULL, NULL, NULL, NULL),
