  ('5a5dba87-a550-5626-965e-72bddcebe7c3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5a5dba87-a550-5626-965e-72bddcebe7c3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '370425ad-779e-514f-9c50-aacf345e52d2'::uuid, NULL, NULL, E'Joining a society can help to meet new people.', NULL, NULL),
  ('5a608a8e-a1a1-5c2a-8c5f-3ae1e21c0f06'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5a608a8e-a1a1-5c2a-8c5f-3ae1e21c0f06'::uuid, 1, NULL, TRUE, 0, NULL, E'Night Sky', E'Nature offers no greater splendor than the starry sky on a clear, dark night. Silent, timeless, jeweled with the constellations of ancient myth and legend, the night sky has inspired wonder throughout the ages — a wonder that leads our imaginations far from the confines of Earth and the pace of the present day, out into boundless space and cosmic time itself.', NULL, NULL, NULL, NULL, NULL, NULL),
