  ('5a7e379b-b34d-56d2-a2e4-2112be579a6d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5a7e379b-b34d-56d2-a2e4-2112be579a6d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call a piece of equipment we use to look at stars?', '58ea5ae6-4242-5da5-8d18-4b6cb894799c'::uuid, NULL, NULL, E'Telescope / astronomical telescope', NULL, NULL),
  ('5a8252fd-a608-50d5-bb36-5a204b5ba0a2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5a8252fd-a608-50d5-bb36-5a204b5ba0a2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd775e97b-7d51-5eb5-a956-10157256d704'::uuid, NULL, NULL, E'Currently the growth of the economy is unpredictable.', NULL, NULL),
  ('5a912389-c6b1-5da8-b620-4d008009092a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5a912389-c6b1-5da8-b620-4d008009092a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '76fa6cdf-ec78-5da8-a0fe-e6238121d70e'::uuid, NULL, NULL, E'Please close the door behind you when you leave the room.', NULL, NULL),
  ('5a97e1ed-94ac-526c-a381-6e3f994f9eda'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5a97e1ed-94ac-526c-a381-6e3f994f9eda'::uuid, 1, NULL, TRUE, 0, NULL, E'Birth Kit', NULL, 'd44d6fa6-b2fe-5f40-b94d-0109772c0ca2'::uuid, NULL, E'After many iterations working with experts, medical health professionals and the women themselves, I should say it was not an easy process at all, but we had a simple and beautiful design. For a dollar more than what the existing product was offered for, at three dollars, we were able to deliver “Janma,” a clean birth kit in a purse. Janma, meaning “birth,” contained a blood-absorbing sheet for the woman to give birth on, a surgical scalpel, a cord clamp, a bar of soap, a pair of gloves and the first cloth to wipe the baby clean. All this came packaged in a beautiful purse that was given to the mother as a gift after all her hard work, that she carried home with pride as a symbol of prosperity. One woman reacted to this gift. She said, “Is this really mine? Can I keep it?” The other one said,”Will you give me a different color when I have my next baby?” Better yet, a woman expressed that this was the first purse that she had ever owned in her life. The kit, aside from its symbolism and its simplicity, is designed to follow globally recommended medical protocol and serves as a behavior-change tool to follow steps one after the other. It can not only be used in homes, but also in institutional settings. To date, our kit has impacted over 600,000 mothers and babies around the world. It’s a humbling experience to watch these numbers grow, and I cannot wait until we reach a hundred million.', NULL, NULL, NULL),
  ('5aa0cd16-6f67-53e8-b6e6-7def3f2dd380'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '5aa0cd16-6f67-53e8-b6e6-7def3f2dd380'::uuid, 1, NULL, TRUE, 0, NULL, E'Formulaic Writing', E'A good starting place is to {{1}} writing as thinking. Experienced writers don’t figure out what they want to say and then write it. They write in order to figure out what they want to say. Experienced writers develop theses in dialog with the body of the essay. An initial characterization of the problem leads to a tentative thesis. Then, drafting the body of the paper reveals thorny contradictions or critical areas of ambiguity, {{2}} the writer to revisit or expand the body of evidence and then refine the thesis based on that fresh look. The revised thesis may require that body paragraphs be reordered and {{3}} to fit the emerging thesis. Throughout the process, the thesis serves as an {{4}} point while the author wades through the morass of facts and ideas. The writer continues to read to learn more about his or her issue and refines his or her ideas in response to what is learned. The dialogue between thesis and body continues until the author is satisfied or the due date arrives, whatever comes first.', NULL, NULL, NULL, E'1.recharacterize, 2.prompting, 3.reshaped, 4.anchor', NULL, NULL),
  ('5aa955bd-dcc1-5635-b7da-4920f0a12976'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '5aa955bd-dcc1-5635-b7da-4920f0a12976'::uuid, 1, NULL, TRUE, 0, NULL, E'Facebook Research', E'A large-scale study was {{1}} by Facebook to analyze how people interact with {{2}} online. The research showed {{3}} of communication and the influence of social networks on relationships and community-building.', NULL, NULL, NULL, E'1.made, 2.each other, 3.patterns', NULL, NULL),
