  ('5b52d26b-5fdf-5f32-9d5a-72d3b8170567'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5b52d26b-5fdf-5f32-9d5a-72d3b8170567'::uuid, 1, NULL, TRUE, 0, NULL, E'Thesis', E'Once you''ve picked a general topic for your paper, you need to come up with a thesis. Your thesis is the main and focal point of your paper and it''s the position you''ll take on your particular topic. Formulating a strong thesis is one of the most important things you need to do to ace your paper.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('5b538c6d-0256-5630-9f31-b95c42c2c2c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5b538c6d-0256-5630-9f31-b95c42c2c2c5'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'eef8f46a-9652-5a4e-9314-f17ad92f8b56'::uuid, NULL, E'Thirty nine point five percentage of California residents speak a language other than English at home.', NULL, NULL, NULL),
  ('5b557799-07b8-5500-b69c-e356fc92ae08'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5b557799-07b8-5500-b69c-e356fc92ae08'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '440be1bf-a516-5d97-b280-6af51ad0330f'::uuid, NULL, NULL, E'Some of the children have specific learning difficulties.', NULL, NULL),
  ('5b5ad437-60cc-5415-8c35-100d441662a2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5b5ad437-60cc-5415-8c35-100d441662a2'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4d521ade-9f0a-5c6f-980f-25a6d55e2a79'::uuid, NULL, E'You may use your student identification card to borrow books at the library.', NULL, NULL, NULL),
  ('5b5ecd4c-5d6c-5007-81fb-f2fcfaa59509'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5b5ecd4c-5d6c-5007-81fb-f2fcfaa59509'::uuid, 1, NULL, TRUE, 0, NULL, E'Chest X-Ray', NULL, 'e5a05e8c-9f7a-5a28-ab6a-fcedf246775d'::uuid, NULL, E'This is one picture that you probably you all know what it is when you see it. It''s a familiar-looking image. It''s something that probably we all have some personal experience with, right?\nThis is a chest X-ray that would be taken in your doctor''s office, for example, or a radiologist''s office.\nAnd it is a good example of Biomedical Engineering and that it takes a physical principle, that is how do X-rays interact with the tissues of your body, and it uses that physics, that physical principle to develop a picture of what''s inside your body, so to look inside and see things that you couldn''t see without this device. And you''ll recognize some parts of the image, you can see the ribcage here, the bones you can see the heart is the large bright object down here.\nIf you, have good eyesight from the distance, you can see the vessels leading out of the heart and into the lungs, and the lungs are darker spaces within the ribcage.', NULL, NULL, NULL),
  ('5b5f694e-c5b4-5768-8270-ece73fa584e5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5b5f694e-c5b4-5768-8270-ece73fa584e5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0a7f66ff-32bb-5125-ba3f-71ea0d88fc6d'::uuid, NULL, NULL, E'He failed to pass the exam because of his carelessness.', NULL, NULL),
  ('5b621250-1727-55bb-804a-6261c5ee84f4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5b621250-1727-55bb-804a-6261c5ee84f4'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the opposite of ''appreciate''?', 'b3365ff4-73d6-52ae-a9c6-41c58f849a2e'::uuid, NULL, NULL, E'Depreciate', NULL, NULL),
  ('5b6618ef-5cce-5f76-abfd-9113867a90bb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5b6618ef-5cce-5f76-abfd-9113867a90bb'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '73d56a63-3c1d-572a-8784-cbbb5722c62b'::uuid, NULL, E'You need to write a proposal for your research.', NULL, NULL, NULL),
  ('5b66cb91-6294-5938-8644-ccef7d859c60'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5b66cb91-6294-5938-8644-ccef7d859c60'::uuid, 1, NULL, TRUE, 0, NULL, E'Looking Younger', E'The other day I saw an advert on the internet asking for volunteers to test a new skin cream. It was an anti aging product. How is it possible for a cream or lotion to stop us looking old? I don''t think any skin care goods can make us look younger. I certainly don''t believe cosmetics companies that say their expensive creams can remove wrinkles. They just want to make lots of money. Why do people believe them? How do they know their creams work? They did not test their products on thousands of people over fifty years. I think if a person uses an anti aging cream for fifty years, they would not even look a year younger when they are sixty. This means it''s a huge waste of money. Only healthy living can keep us.\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '7332ba30-7c96-52cc-9a23-3d8440a022ff'::uuid, NULL, NULL, E'looking younger', NULL, NULL),
  ('5b6c51f2-f331-50d2-9ded-e33385bcfa24'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5b6c51f2-f331-50d2-9ded-e33385bcfa24'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'cbf082a6-62ac-5f5e-90dc-d8d78c9b0116'::uuid, NULL, NULL, E'We aim to provide an opportunity for graduates from diverse academic backgrounds.', NULL, NULL),
  ('5b71d53c-ab3f-5618-af9f-54e0420445b5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '5b71d53c-ab3f-5618-af9f-54e0420445b5'::uuid, 1, NULL, TRUE, 0, NULL, E'Dentistry', E'Dentistry is a profession {{1}} with the prevention and treatment of oral disease. Dentistry also encompasses the treatment and correction of malformation of the jaws, misalignment of the teeth, and birth anomalies of the oral cavity such as cleft palate. Dentistry, in some form, has been {{2}} since ancient times. For example, Egyptian skulls dating from 2900 to 2750 BCE contain evidence of small holes in the jaw in the vicinity of a tooth’s roots. Such holes are believed to have been {{3}} to drain abscesses. In addition, accounts of dental treatment appear in Egyptian scrolls dating from 1500 BCE. It is thought that the Egyptians practiced oral surgery perhaps as early as 2500 BCE, although evidence for this is minimal. An early attempt at tooth {{4}} dates to Phoenicia (modern Lebanon) around 600 BCE, where missing teeth were replaced with animal teeth and were bound into place with cord.', NULL, NULL, NULL, E'1.concerned, 2.practiced, 3.drilled, 4.replacement', NULL, NULL),
  ('5b73ddab-a641-5b35-ab3d-aeef0b2d886d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '5b73ddab-a641-5b35-ab3d-aeef0b2d886d'::uuid, 1, NULL, TRUE, 0, NULL, E'Pressing Concern', E'In today''s fast-paced world, our {{1}} to the environment is a pressing concern. The relentless exploitation of natural resources, escalating pollution levels, and the looming threat of climate change have brought us to a critical juncture. The need for {{3}} action to protect our planet has never been more urgent. One of the key contributors to environmental degradation is the excessive use of single-use plastics. These items, such as plastic bags and bottles, end up in our oceans and harm marine life. Using plastic {{4}} and recycling efforts are steps in the right direction, but a more comprehensive approach is required. Individuals, communities, governments, and industries all play a role in shaping the future of our planet. We must {{5}} reduce our dependence on fossil fuels, promote renewable energy sources, and adopt sustainable practices in agriculture and manufacturing.', NULL, NULL, NULL, E'1.indifference, 2.proactive, 3.alternatives, 4.collectively', NULL, NULL),
  ('5b743d11-3b95-5663-b99b-12c248b83f52'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5b743d11-3b95-5663-b99b-12c248b83f52'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What mark is used in writing to show that a sentence is over?', 'dadfcede-b2a1-5e37-9d57-173841cdc925'::uuid, NULL, NULL, E'Period / full stop', NULL, NULL),
  ('5b750395-ea5c-5009-8d96-d5c0e01ac6f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5b750395-ea5c-5009-8d96-d5c0e01ac6f9'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the capital city of South Korea?', '98ecf59e-dbdc-5524-b9c4-96be8f57dca0'::uuid, NULL, NULL, E'Seoul', NULL, NULL),
  ('5b76e7e5-9135-56ac-91cc-3e8ec109fcb8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5b76e7e5-9135-56ac-91cc-3e8ec109fcb8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person who flies an aircraft?', '367c9225-bdcf-5638-a963-f1df876df820'::uuid, NULL, NULL, E'Pilot', NULL, NULL),
  ('5b78dac2-3890-50ed-a329-54b53ec35959'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5b78dac2-3890-50ed-a329-54b53ec35959'::uuid, 1, NULL, TRUE, 0, NULL, E'Fingerprint', E'One of life''s great marvels is that, much like snowflakes, no two fingerprints are alike. This goes even for identical twins, who split from the very same egg. In fact, fingerprints are so unique that we actually have different prints on each and every digit. Although it''s not entirely impossible for two fingerprints to match up, the odds are way against it, at 1 in 64 billion.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('5b7972c8-387b-55f1-be54-51ee98807049'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5b7972c8-387b-55f1-be54-51ee98807049'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What does a barometer measure?', 'a79be083-ab43-5639-abe9-8e14708f374e'::uuid, NULL, NULL, E'Air pressure', NULL, NULL),
  ('5b7ca7a8-b6ec-5a50-a532-53978d6a89d4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '5b7ca7a8-b6ec-5a50-a532-53978d6a89d4'::uuid, 1, NULL, TRUE, 0, NULL, E'Legal Humanism', E'So far, we have been looking at the work of humanist historians in the Renaissance and the new way in which they approached their subject. Not only did they use close reading of ancient texts, as you would expect, but they also did a lot of research in the archives. That is, they didn''t just read the historians that came before them, they looked for real documents. For example, they studied the records of cases that went to court, official letters that had survived, and so on to get a fuller picture of how people really lived and went about their business.\nThese same techniques of historical research were used in what we can call "legal humanism". The idea here was to get as accurate a picture as possible of the law and its practice in ancient, especially Roman, times. Legal historians did this with a view to refining the laws and applying them to the present historical situation. Legal scholarship''s original desire to recover and purify the heritage of the ancient world later came to be distorted by political views, but even here, in the 16th century, such intense study could lead to unexpected conclusions. For example, in France, inquiries meant to uncover and apply the legal wisdom of the Romans ended by uncovering a Roman law so pure that it was totally alien. This law, in fact, belonged to the past and to a different society, and was therefore unusable.\n\nWhat was the ultimate aim of legal scholarship?', NULL, NULL, NULL, E'To apply Roman law to their own society.', NULL, NULL),
  ('5b9066b7-65be-5469-94f9-0897ce9caf21'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5b9066b7-65be-5469-94f9-0897ce9caf21'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which one is the odd one out among dog, cat, horse and shoes?', 'e4a3a67f-bfbc-52b9-8743-c53a60c2a0fb'::uuid, NULL, NULL, E'Shoes', NULL, NULL),
  ('5b995437-f934-50aa-8571-972c5f02e2db'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5b995437-f934-50aa-8571-972c5f02e2db'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '682c6753-465f-54ad-8bd9-5fe98a56bddb'::uuid, NULL, NULL, E'Newspapers across the country have been reporting stories of the president.', NULL, NULL),
  ('5b9a3868-3e6d-511d-a801-c6d085956401'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '5b9a3868-3e6d-511d-a801-c6d085956401'::uuid, 1, NULL, TRUE, 0, NULL, E'Balanced Diet', NULL, NULL, NULL, NULL, E'2, 3, 1, 4', NULL, NULL),
  ('5b9a8095-cfa3-5478-9552-a4302b90a32a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '5b9a8095-cfa3-5478-9552-a4302b90a32a'::uuid, 1, NULL, TRUE, 0, NULL, E'Food Minding', E'At supper Johnson talked of good eating with uncommon {{1}} . "Some people," said he, "have a foolish way of not minding, or pretending not to mind, what they eat. For my part, I mind my belly very {{2}} , and very carefully; for I look upon it, that he who does not mind his belly will hardly mind anything else," He was, for the moment, not only serious but {{3}} . Yet I have heard him, upon other occasions, talk with great contempt of people who were anxious to gratify their palates; and the 206th number of his Rambler is a masterly essay against {{4}} . His practice, indeed, I must acknowledge, may be considered as casting the balance of his different opinions upon this subject; for I never knew any man who {{5}} good eating more than he did.', NULL, NULL, NULL, E'1.satisfaction, 2.studiously, 3.vehement, 4.gulosity, 5.relished', NULL, NULL),
  ('5b9c963c-2494-5bcd-bc0e-316c6091d367'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5b9c963c-2494-5bcd-bc0e-316c6091d367'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7509130d-480f-5108-9741-8bfa203fba16'::uuid, NULL, NULL, E'Politicians need to be more practical when they are addressing the issues.', NULL, NULL),
  ('5b9d17f4-6012-5d9b-9ff8-0a178aca7659'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5b9d17f4-6012-5d9b-9ff8-0a178aca7659'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the study of stars and planet called?', 'd435d256-598f-5ebc-b2e1-741526cbcb8d'::uuid, NULL, NULL, E'Astronomy / uranological / uranology / cosmology', NULL, NULL),
  ('5ba42b94-3dc9-5d35-a2a3-5ad094ff1063'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '5ba42b94-3dc9-5d35-a2a3-5ad094ff1063'::uuid, 1, NULL, TRUE, 0, NULL, E'Agrarian Parties', E'Agrarian parties are political parties chiefly representing the interests of peasants or, more broadly, the rural sector of society. The extent to which they are important, or {{1}} they even exist, depends mainly on two factors. One, obviously, is the size of an identifiable peasantry, or the size of the rural relative {{2}} the urban population. The other is a matter of social integration: {{3}} agrarian parties to be important, the representation of countryside or peasantry must not be integrated with the other major sections of society. {{4}} , a country might possess a sizable rural population, but have an economic system in which the interests of the voters were predominantly related to their incomes, {{5}} than their occupations or location; and in such a country the political system would be unlikely to include an important agrarian party.', NULL, NULL, NULL, E'1.whether, 2.to, 3.for, 4.Thus, 5.rather', NULL, NULL),
  ('5ba51c37-28c3-56b7-8b52-d85b5bbb4fbc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5ba51c37-28c3-56b7-8b52-d85b5bbb4fbc'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ed0af872-796a-5632-831f-a3de8c9145ad'::uuid, NULL, E'Please ensure you come well-prepared for the upcoming seminar session.', NULL, NULL, NULL),
  ('5ba6fa3b-acae-5931-b75e-8f96cd06a08a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5ba6fa3b-acae-5931-b75e-8f96cd06a08a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '871f7a52-1631-59e5-8f20-00fff5b3842b'::uuid, NULL, NULL, E'Scientists can develop new elements in the laboratory.', NULL, NULL),
  ('5bac3822-e945-5573-b44a-b9639c635dfc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5bac3822-e945-5573-b44a-b9639c635dfc'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '271ebe9f-9d1d-5423-be96-1f1084b1e7b4'::uuid, NULL, E'This can be used as a starting point of my discussion today.', NULL, NULL, NULL),
  ('5bb9447f-2f07-57dc-98d1-7d14efe0c423'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5bb9447f-2f07-57dc-98d1-7d14efe0c423'::uuid, 1, NULL, TRUE, 0, NULL, E'Trees', NULL, 'cd39472d-b0dd-5b8c-a819-b618a2793d7b'::uuid, NULL, E'Around 30% of our planet is covered in trees. Trees are majestic help biodiversity and can reduce climate change. But we’re cutting them down at an alarming rate. Since the start of human civilisation, it’s estimated that we’ve cut down almost half the trees on Earth. So, what would happen if all of us and that’s all 7.7 billion of us, planted a tree? Well, there might be 7.7 billion of us, but it’s estimated there are currently over 3 trillion trees on the planet. 7.7 billion more trees would be a valuable step forward. But we’d need to go further to make a really substantial difference to the environment. But we could. In fact, according to one estimate, if we planted 1.2 trillion trees, we’d cancel out a decade’s worth of CO2 emissions by the time the forests mature. So that’s more like 160 trees per person. Trees take carbon dioxide out of the air and release oxygen – making them a natural source of carbon capture. Planting 1.2 trillion more trees could capture up to 100 gigatonnes of CO2, on top of the 400 gigatonnes captured by all our existing trees. Trees planted near the equator can be especially beneficial, as they grow much faster in the warm, wet and humid environment. Let’s imagine that happened. In as little as 20 or 30 years, entire woodlands and forests would be established. And in 100 years, these trees would grow and mature, safeguarding habitats that otherwise get cut down. We’d also see a rise in biodiversity as trees get older and start to decompose, because they, along with dead trees, offer a habitat to all kinds of fungi and insects. On top of this, we could see a positive impact to our mental health, as studies have shown trees can lower stress and make people happier.', NULL, NULL, NULL),
  ('5bb9a60c-a944-547d-9cc6-8d1b4f149565'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5bb9a60c-a944-547d-9cc6-8d1b4f149565'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '402e660f-ecdf-5777-abed-9712f4f5fdd4'::uuid, NULL, NULL, E'My brother graduated with a first-class degree in history.', NULL, NULL),
  ('5bbb02d8-bbf6-5cc3-b19b-5a95fad266f4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '5bbb02d8-bbf6-5cc3-b19b-5a95fad266f4'::uuid, 1, NULL, TRUE, 0, NULL, E'Web Security', E'In the past, security teams have {{1}} a collection of on-premises solutions to manage email and web security. But increasingly organizations are turning to comprehensive email and web security solutions via {{2}} technologies that {{3}} the task and reduce the cost of reducing risk. And because attackers often leverage email and web channels together, a {{4}} and scalable strategy for protecting both is essential.', NULL, NULL, NULL, E'1.deployed, 2.integrated, 3.simplify, 4.seamless', NULL, NULL),
  ('5bc096ec-83c3-5544-9e3a-a10fc299276c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '5bc096ec-83c3-5544-9e3a-a10fc299276c'::uuid, 1, NULL, TRUE, 0, NULL, E'AI and Drug Resistance', E'Scientists in the United Kingdom and China have announced plans to use artificial intelligence on chicken farms in order to combat the problem of antibiotic resistance in both farm animals and humans. The new initiative will use machine learning to find ways to track and prevent disease on poultry farms, reducing the need for antibiotic treatment in chickens and therefore lowering the risk of antibiotic-resistant bacteria transferring to people.\nNow, antibiotic resistance is a worldwide problem and it''s getting worse and worse. Some of these superbugs are resistant to everything. On farms, superbugs are not confined to animals. They spread to humans and to the environment, which is an exponential spread.\nAnd antibiotics work by disrupting function in certain parts of a bacterial cell. Bacteria become resistant to antibiotics through genetic mutations that alter those areas of the cell, meaning the medication can no longer target them. The more a strain of bacteria is exposed to an antibiotic, the more likely it is to become resistant. Large numbers of people and animals are given antibiotics when they don''t need them, so reducing unnecessary consumption is crucial in the fight against so-called superbugs.\nWith a large-scale data set, the human mind can''t cope with it, and it''s too complex. So we need the machine that is able to understand the relationship across a big amount of information.', NULL, NULL, NULL, NULL, 5, 75),
  ('5bc3ef92-9ec3-5b1a-b924-37090b9baa27'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5bc3ef92-9ec3-5b1a-b924-37090b9baa27'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '63f1c909-0d82-5437-9d31-c6eac8fe77c8'::uuid, NULL, E'It has been shown that the number of male nurses has increased substantially.', NULL, NULL, NULL),
