  ('5cb73f24-9a3d-590c-8c66-1c842a508764'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5cb73f24-9a3d-590c-8c66-1c842a508764'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the quickest way to get from the first floor to the 25th floor in a building?', '76ef8d7c-1460-5af6-8b52-673f0d63e1ec'::uuid, NULL, NULL, E'Lift / Elevator', NULL, NULL),
  ('5cb80389-98b3-5adf-b212-f731b0b53375'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5cb80389-98b3-5adf-b212-f731b0b53375'::uuid, 1, NULL, TRUE, 0, NULL, E'DBS', E'Deep brain stimulation (DBS) to the superolateral branch of the medial forebrain bundle (MFB), which is linked to reward and motivation, revealed metabolic brain changes over 12 months post-DBS implantation, making it a strong potential therapy for treatment-resistant depression.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('5cbde857-a0e5-5728-9bb0-fb3b99582732'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5cbde857-a0e5-5728-9bb0-fb3b99582732'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5fb61242-55e5-5def-a8a8-8e48e31a4659'::uuid, NULL, NULL, E'The influence of friends is often pivotal to young people''s behavior.', NULL, NULL),
