  ('5da17bc6-6abd-5c64-b099-4944ef2b0a89'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5da17bc6-6abd-5c64-b099-4944ef2b0a89'::uuid, 1, NULL, TRUE, 0, NULL, E'Distance Learning', E'We understand that not everyone can put their job and other responsibilities on hold to study. That''s why our healthcare ethics and law master''s courses are available to study by distance learning, so you can fit gaining an academic qualification around your work and family.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('5da189cd-0d65-5563-b210-16f2fbb59d78'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5da189cd-0d65-5563-b210-16f2fbb59d78'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3a50e250-68e2-5701-8ec7-d9e00f43fb42'::uuid, NULL, E'You can find faculty and staff by department or unit through the university''s directories.', NULL, NULL, NULL),
