  ('5e97624d-9729-5f0b-a1f7-b064def93176'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5e97624d-9729-5f0b-a1f7-b064def93176'::uuid, 1, NULL, TRUE, 0, NULL, E'Dutch Consortium', E'A Dutch consortium has developed an electrical bicycle that prevents elderly people from falling. The smart Assistive Bicycle, called SOFIE, increases stability by, amongst others, a drive off assistance and by automatically lowering the saddle at low speeds.', NULL, NULL, NULL, NULL, NULL, NULL),
