  ('5e9d014f-ee46-50f6-a490-453733f8d121'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '5e9d014f-ee46-50f6-a490-453733f8d121'::uuid, 1, NULL, TRUE, 0, NULL, E'Addressing Basic Needs', E'Managers have a {{1}} role to find out what each employee cares about. A mother may need flexible hours. Another person’s motivation may be mostly {{2}} , and he needs space (autonomy) to work his way. Someone else may need rules and {{3}} . The work environment may not allow much flexibility, but just recognizing an individual’s {{4}} is a strong first step.', NULL, NULL, NULL, E'1.critical, 2.intrinsic, 3.structure, 4.preferences', NULL, NULL),
  ('5ea2bad7-9666-52be-aa58-58bf81a5aa53'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5ea2bad7-9666-52be-aa58-58bf81a5aa53'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the tropical fruit known for its spiky skin and sweet, juicy interior?', 'c03a1e61-8891-5ef4-ab02-c2a15961951b'::uuid, NULL, NULL, E'Pineapple', NULL, NULL),
  ('5ea94ff1-2226-54ba-8735-af935dcf248b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5ea94ff1-2226-54ba-8735-af935dcf248b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the highest position in the embassy?', '6c8fd128-c308-59d8-a803-0a50933f3e0f'::uuid, NULL, NULL, E'Ambassador', NULL, NULL),
  ('5eaa32f6-dcb7-582d-bb08-94dfb1bfbfab'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5eaa32f6-dcb7-582d-bb08-94dfb1bfbfab'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5bd8a5ba-31b5-5b2d-98b4-b1f344d38243'::uuid, NULL, E'Data processing is the series of operations that are carried out on data.', NULL, NULL, NULL),
  ('5ead119e-c07c-55ec-b347-b49ca46a4ed5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5ead119e-c07c-55ec-b347-b49ca46a4ed5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ea0530e7-e0c5-5ae8-acf2-f172c6e99c08'::uuid, NULL, NULL, E'The young man has received his doctoral degree in law.', NULL, NULL),
  ('5eb7da72-b823-58f5-a648-b94bd64d7532'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '5eb7da72-b823-58f5-a648-b94bd64d7532'::uuid, 1, NULL, TRUE, 0, NULL, E'New Radio Tuner', E'It''s happened to all of us. You''re on your cell phone, your boss is saying something important, and then the connection starts to drop out.\nNow a team of physicists in Denmark, led by Albert and Eugene Polzik, has demonstrated a new kind of radio tuner that is far more sensitive to faint signals. The technique could eventually mean fewer dropped calls, better GPS coverage, faster Wifi, and much more detailed images from MRI scanners.\nThe tuner includes a novel component: a tiny reflective membrane just half a {{1}} on a side and only a hundred nanometers thick. It functions in the circuit as a capacitor, and when radio waves pass through the antenna, the {{2}} voltage shifts make the membrane bounce like a trampoline.\nLaser light, {{3}} off the membrane and then interfering with itself, turns those nanometer-high wiggles into a strong, clear signal. The report is {{4}} on the site arXiv.org.\nThe scientists are excited about how the technology might sharpen the pictures produced by radio {{5}} . But wouldn''t it also be nice to {{6}} get decent phone reception inside a parking garage?', NULL, NULL, NULL, E'1.millimeter, 2.minuscule, 3.reflecting, 4.published, 5.telescopes, 6.actually', NULL, NULL),
  ('5eb99c48-4b40-5d7b-b192-f5f7541d6beb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5eb99c48-4b40-5d7b-b192-f5f7541d6beb'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the long speech that is spoken by only one actor in a film or play?', '70d6e99f-2a4f-56ca-b6db-4c8cf0ecbbf1'::uuid, NULL, NULL, E'Monologue / soliloquy', NULL, NULL),
  ('5eb9c0a7-57ff-5b62-bcd6-bdd93c554c27'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '5eb9c0a7-57ff-5b62-bcd6-bdd93c554c27'::uuid, 1, NULL, TRUE, 0, NULL, E'Psychoanalytic and Behaviorist', E'Elements of both the psychoanalytic and behaviorist theories are {{1}} in modern approaches to personality. Advances in neuroscience have begun to {{2}} the gap between biochemistry and behavior, but there is still a great deal that needs to be explained. Without a consistent understanding of personality, how can we begin to {{3}} risk takers? If we cannot, we will be unable to {{4}} their genes with those of others.', NULL, NULL, NULL, E'1.arranged, 2.bridge, 3.categorize, 4.compare', NULL, NULL),
  ('5ebb52b6-945b-5eca-ae25-85ec050c5ada'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5ebb52b6-945b-5eca-ae25-85ec050c5ada'::uuid, 1, NULL, TRUE, 0, NULL, E'Dogs', NULL, '5dac8589-752c-5ee1-a2ab-64131277464d'::uuid, NULL, E'When this dog approaches some food, another dog''s playful snarls are played back the dog seems curious, but the sound doesn''t stop it from taking the bone. Here a dog hears the growls of a dog being approached by a stranger, but these don''t deter it from grabbing the bone either. In another scenario the sound of a dog protecting its food is played back. This time the dog backs off. These experiments suggest the dogs can distinguish between different types of growls.', NULL, NULL, NULL),
  ('5ebd6fc8-9f3d-5ae2-9a57-95eabf24ebbc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5ebd6fc8-9f3d-5ae2-9a57-95eabf24ebbc'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f8d70b9d-1770-599c-a379-3e6db06147dd'::uuid, NULL, E'The teacher forbade the student from taking the exam since he was late.', NULL, NULL, NULL),
  ('5ebe4972-01c1-53d1-a778-ddad97bbbdc0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5ebe4972-01c1-53d1-a778-ddad97bbbdc0'::uuid, 1, NULL, TRUE, 0, NULL, E'Noise Restrictions', E'The noise restrictions are based on measurements on animals in captivity exposed to noise levels that induce a temporary threshold shift (TTS) in hearing. The TTS onset threshold is the lowest noise exposure capable of inducing a small temporary reduction of hearing sensitivity, also known as auditory fatigue, with full recovery shortly after exposure.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('5ebef8a0-3826-5ca4-aec2-555f4f40926a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5ebef8a0-3826-5ca4-aec2-555f4f40926a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '88973892-602c-5a70-99eb-a23d95c6a515'::uuid, NULL, NULL, E'He is one of the leading authors in educational psychology.', NULL, NULL),
  ('5ec5751f-23e3-5f26-8260-69a676cf0983'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5ec5751f-23e3-5f26-8260-69a676cf0983'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b597b7bc-c491-557a-85af-dc79d954c837'::uuid, NULL, E'The professor regards this research as fundamental to our environment.', NULL, NULL, NULL);
