  ('5ec902c9-bb2f-5508-ba91-a264b1b15772'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5ec902c9-bb2f-5508-ba91-a264b1b15772'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a piece of iron that attracts objects made of iron towards it?', 'f2d5378d-52be-5f25-babe-2156d8f0eaf8'::uuid, NULL, NULL, E'Magnet / magnetic-iron', NULL, NULL),
  ('5ecbb1fa-7d72-50d5-8500-90f922168e3b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5ecbb1fa-7d72-50d5-8500-90f922168e3b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8bdad3a8-1d83-5112-b980-9a75480d9390'::uuid, NULL, E'The cell is the unit of which all living organisms are composed.', NULL, NULL, NULL),
  ('5ecc30fd-cbfb-5aff-8fa8-7d996352fab1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '5ecc30fd-cbfb-5aff-8fa8-7d996352fab1'::uuid, 1, NULL, TRUE, 0, NULL, E'Healthy Eating', NULL, NULL, NULL, NULL, E'2, 4, 3, 1', NULL, NULL),
  ('5ed2fe17-ade5-5b65-8138-2c7f7ae924ed'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5ed2fe17-ade5-5b65-8138-2c7f7ae924ed'::uuid, 1, NULL, TRUE, 0, NULL, E'New Mineral', E'A diamond that formed deep in the earth’s mantle contains a mineral never seen before in nature. The discovery is a rare glimpse into the deep mantle and may help reveal new information about the structure of the planet at depths of more than 660 kilometers. This can help geologists better understand how the mantle controls the earth’s plate tectonics.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('5ed51dfc-334b-5002-b45d-50176e00e592'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5ed51dfc-334b-5002-b45d-50176e00e592'::uuid, 1, NULL, TRUE, 0, NULL, E'Unions', E'Unions take the power out of the employer''s hands on many issues. There are examples of cases where workers were engaging in sexual or racial harassment, but were protected by their unions and allowed to keep their jobs. Poor workers and excellent workers often receive the same pay and raises, giving no reason for a person to work harder than necessary at their jobs.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('5ed5aab6-0711-50ab-aa1c-bfb2aa41f46f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '5ed5aab6-0711-50ab-aa1c-bfb2aa41f46f'::uuid, 1, NULL, TRUE, 0, NULL, E'Carbon Detox', E'In his {{1}} book Carbon Detox, George Marshall argues that people are not persuaded by information. Our views are formed by the views of the people with whom we mix. Of the {{2}} that might penetrate these circles, we are more likely to listen to those that offer us some reward. A story that tells us that the world is cooking and that we''ll have to make sacrifices for the sake of future generations is less likely to be accepted than the more rewarding idea that climate change is a conspiracy hatched by scheming governments and venal scientists, and that strong, independent-minded people should unite to defend their freedoms.\nHe proposes that instead of arguing for sacrifice, {{3}} should show where the rewards might lie: that understanding what the science is saying and planning accordingly is the smart thing to do, which will protect your interests more effectively than flinging abuse at scientists. We should {{4}} the old-fashioned virtues of uniting in the face of a crisis, of resourcefulness and community action. Projects like the transition town’s network and proposals for a green new deal tell a story which people are more willing to hear.', NULL, NULL, NULL, E'1.fascinating, 2.narratives, 3.environmentalists, 4.emphasize', NULL, NULL),
  ('5ed9555e-18bd-5b19-9597-a6e2bd750969'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '5ed9555e-18bd-5b19-9597-a6e2bd750969'::uuid, 1, NULL, TRUE, 0, NULL, E'Sahara Desert', NULL, NULL, NULL, NULL, E'3, 2, 4, 1', NULL, NULL),
  ('5ee14ae0-3889-5dfe-b498-2e0599adfab7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5ee14ae0-3889-5dfe-b498-2e0599adfab7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a8b9a100-5b88-5e94-abcc-28c57048f916'::uuid, NULL, NULL, E'A person''s education level is closely linked to their economic background.', NULL, NULL),
  ('5ee30a1e-ad6c-51fd-b51b-5667aebdb704'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5ee30a1e-ad6c-51fd-b51b-5667aebdb704'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c9038d32-54aa-5a0e-8fca-647592500b6f'::uuid, NULL, NULL, E'International exchange formed the important part of our study programs.', NULL, NULL),
  ('5ee7ba5a-1df8-5030-bc18-954da2b1d24e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '5ee7ba5a-1df8-5030-bc18-954da2b1d24e'::uuid, 1, NULL, TRUE, 0, NULL, E'Birds', E'Some birds of prey have learned to control fire, a {{1}} previously thought to be unique to humans. The birds appear to deliberately spread wildfires in order to {{2}} out prey. The finding suggests that birds may have {{3}} us to the use of fire.', NULL, NULL, NULL, E'1.skill, 2.flush, 3.beaten', NULL, NULL),
  ('5ee8fe6f-bbe6-5fc7-80bf-6a9c97a9e4f6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5ee8fe6f-bbe6-5fc7-80bf-6a9c97a9e4f6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '46153640-5b20-5bfb-a6b0-568f3d6f53e7'::uuid, NULL, NULL, E'Please work with each other to build monolithic statues.', NULL, NULL),
  ('5eead00e-5c95-58a4-be6c-cb80742af3b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '5eead00e-5c95-58a4-be6c-cb80742af3b2'::uuid, 1, NULL, TRUE, 0, NULL, E'Chilies', E'Humans have been cultivating chilies as food for 6,000 years, but we are still learning new things about the science behind their heat and how it reacts with our body. In the late 1900''s, scientists identified the pain nerves that detect capsaicin: the chemical in chillies responsible for most of the burning sensation in our mouth. But it''s only during the last few years that scientists have also learnt why chilies evolved to be spicy in the first place, and they have managed to cultivate new varieties that are up to 300 times hotter than the common Jalapeno.\nThe hottest part of a chilli is not the seeds, as many people think, but the white flesh that houses the seeds, known as the placenta. But why did chillies evolve to be hot in the first place? Most scientists believe capsaicin acts mainly as a deterrent against would-be mammal predators such as rodents. But recent research suggests this may not be the whole story. US scientists working in Bolivia have studied how hot and mild chillies differ in their susceptibility to a certain harmful fungus. It turns out that the hotter the chilli, the better its defences against the fungus, leading the researchers to propose that heat may have evolved to help chillies deal with harmful microbes, as well as hungry mammals.', NULL, NULL, E'Scientists are beginning to understand why chilies evolved to be so hot when eaten, and although many scientists still believe the hotness is to deter mammals from eating the plant, recent research suggests it also developed as a defense against harmful microbes .', NULL, 5, 75),
  ('5ef1ca54-dcb7-58ec-b2e4-b0e118e7511a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '5ef1ca54-dcb7-58ec-b2e4-b0e118e7511a'::uuid, 1, NULL, TRUE, 0, NULL, E'New Parents', E'Many new parents experience some worries and fears after bringing their newborn home, but for some, these feelings can become overwhelming and {{1}} . This is the case for those who suffer from postnatal anxiety, a condition that is often overlooked and misunderstood. Postnatal anxiety is different from postnatal depression, {{2}} they can co-occur. It is characterized by excessive and persistent worry, panic attacks, obsessive thoughts, and physical {{3}} such as insomnia, nausea, and palpitations. Postnatal anxiety can affect both mothers and fathers, and it can have negative consequences for their well-being, their relationships, and their parenting. The {{4}} of postnatal anxiety are not fully understood, but researchers believe that biological, psychological, and social factors may play a role. Some of these factors include hormonal changes, genetic predisposition, previous trauma, lack of social support, and unrealistic expectations. The Covid-19 pandemic has also added to the stress and isolation of many new parents. Fortunately, postnatal anxiety is treatable, and there are several options available for those who {{5}} help. These include cognitive-behavioral therapy, mindfulness, medication, and peer support groups.', NULL, NULL, NULL, E'1.debilitating, 2.although, 3.symptoms, 4.causes, 5.seek', NULL, NULL),
  ('5f127c8e-8ae0-587d-bf07-0c9d5c7d567d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5f127c8e-8ae0-587d-bf07-0c9d5c7d567d'::uuid, 1, NULL, TRUE, 0, NULL, E'Bermuda Triangle', E'The Bermuda Triangle is a mythical section of the Atlantic Ocean roughly bounded by Miami, Bermuda and Puerto Rico where dozens of ships and airplanes have disappeared. Unexplained circumstances surround some of these accidents, including one in which the pilots of a squadron of U.S. Navy bombers became disoriented while flying over the area; the planes were never found.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('5f151bb4-0263-5dcf-851d-3d6c4161dccb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5f151bb4-0263-5dcf-851d-3d6c4161dccb'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a room or building where dead bodies are kept before they are buried?', 'e8d39395-7140-5e0e-8758-a36aadd6646e'::uuid, NULL, NULL, E'Mortuary / morgue', NULL, NULL),
  ('5f19c3c4-c45e-54b5-8fbf-b5915f06a1fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '5f19c3c4-c45e-54b5-8fbf-b5915f06a1fd'::uuid, 1, NULL, TRUE, 0, NULL, E'Running for Office', E'One of the things that we are seeing is that we''re seeing more young people run for office, and the more people start running for office, they realize that local {{1}} is what makes the most impact, at least here in America. So if you want, for example, some racial {{2}} in your judicial system, vote for your district attorney, vote for your city {{3}} . If you think that there''s disparities in our education system, run for your school board. So that''s one. But the other thing to send very clearly to politicians is that when young Americans voted their heart out. Young Latinos, youth in general, outvoted the people before them, but they''re voting on making a bet that their life will change, because the last four years could not have been {{4}} .', NULL, NULL, NULL, E'1.government, 2.reform, 3.councilman, 4.rockier', NULL, NULL),
  ('5f1f33e5-2171-5eaa-8832-fb2b5b76c224'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '5f1f33e5-2171-5eaa-8832-fb2b5b76c224'::uuid, 1, NULL, TRUE, 0, NULL, E'Poker Face', E'A good "poker face" can hide the quality of your cards. But your arms might still be giving away your hands. That''s the finding of a study to come out in the journal Psychological Science.\nVolunteers watched videos of the World Series of Poker. The videos were edited so the subjects saw one of three different views of the players: the poker players'' entire bodies from the table up, or just the players'' faces or just the players'' arms pushing chips into the pot. "When {{1}} were {{2}} chips being pushed into the center of the table by the players, it was only then could they {{3}} perceive how good a hand was better than chance. They couldn''t do it for the whole body and if {{4}} they were worse from just watching the face." Michael Slepian, a psychology doctoral student at Stanford {{5}} , and a co-author of the study.\nNo pros were among the video watchers. But there''s some {{6}} that, as might be expected, they''d be even better at {{7}} arm cues. "In one of our studies, the more participants were familiar with poker—even though they were all novices—the better they did."', NULL, NULL, NULL, E'1.participants, 2.watching, 3.accurately, 4.anything, 5.University, 6.evidence, 7.catching', NULL, NULL),
  ('5f1f8bba-b2fa-5f66-ba28-54ae5d659be9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5f1f8bba-b2fa-5f66-ba28-54ae5d659be9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1a9204d9-0a3a-5742-bb3f-4f444284c08d'::uuid, NULL, NULL, E'Students can gain valuable experience by working at the campus radio.', NULL, NULL),
  ('5f2b95b7-7089-5b81-a7e7-2beb0ea5fbca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5f2b95b7-7089-5b81-a7e7-2beb0ea5fbca'::uuid, 1, NULL, TRUE, 0, NULL, E'Topic', E'When you have selected a topic, you will first have to familiarize yourself with the topic in order to clarify it. In this way you will get a clearer idea of all aspects concerning the topic, definitions, facts and theories. You will get to know related terms and concepts, the context and the various possible ways of approaching the topic.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('5f2da85f-c23a-5741-a6b0-874f7077286b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5f2da85f-c23a-5741-a6b0-874f7077286b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '80aa9c69-8484-59df-a69e-d86a9ce4a476'::uuid, NULL, NULL, E'One of the election pledges is to reduce income tax.', NULL, NULL),
  ('5f2ed3db-e6b1-5a48-8594-364776e1d235'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5f2ed3db-e6b1-5a48-8594-364776e1d235'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Whose job is to make or repair shoes?', 'd8704ebb-7ebc-567a-b4c3-35d631e34baf'::uuid, NULL, NULL, E'Cobbler / shoemaker', NULL, NULL),
  ('5f2f0b97-82d1-5a47-87cf-e75cb2dcff33'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '5f2f0b97-82d1-5a47-87cf-e75cb2dcff33'::uuid, 1, NULL, TRUE, 0, NULL, E'Sustainable Development', E'The Brundtland Report, Our Common Future (1987), defines sustainable development as "development which meets the needs of the present without compromising the ability of future generations to meet their own needs". Implicit in this definition is the idea that the old pattern of development could not be sustained. Is this true? Development in the past was driven by growth and innovation. It led to new technologies and huge improvements in living standards. To assume that we know what the circumstances or needs of future generations will be is mistaken and inevitably leads to the debilitating sense that we are living on borrowed time.\nOnly if we assume that society will remain static can we understand the needs of the future. The way we live today could not have been predicted twenty years ago. The sustainability paradigm fails to recognize this. It is a static view and thus places limits on human ingenuity. Similarly, a whole host of false assumptions dominate environmental thought; the scale of problems is exaggerated, the amount of resources is underestimated and spurious links are made between areas such as green policies and profit, poverty and environmental degradation. Those of us who want a better future need to question these assumptions.', NULL, NULL, E'Sustainable development is defined as "development which meets the needs of the present without compromising the ability of future generations to meet their own needs", and implicit in this definition is the idea that the old pattern of development could not be sustained, yet only if we assume that society will remain static can we understand the needs of the future, so those of us who want a better future need to question these assumptions.', NULL, 5, 75),
  ('5f3377c4-5e3b-5f65-851a-2fe0e63956f4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5f3377c4-5e3b-5f65-851a-2fe0e63956f4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ac009536-9200-5529-87f9-7bb8633521df'::uuid, NULL, NULL, E'What people think about biotech is important for science to agree.', NULL, NULL),
