  ('5f6abb44-083e-56a6-ba72-567829b8a736'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5f6abb44-083e-56a6-ba72-567829b8a736'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '91191050-4456-59a2-9083-fd7c0d46eb2a'::uuid, NULL, NULL, E'The research showed that many doctors were improperly trained.', NULL, NULL),
  ('5f6cbcca-dfc2-5677-8e65-b90970a3c1ae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5f6cbcca-dfc2-5677-8e65-b90970a3c1ae'::uuid, 1, NULL, TRUE, 0, NULL, E'Pancreatic Cancer', E'Pancreatic cancer is tricky to manage because it spreads easily and early, and the tumors have a unique biological makeup. But, researchers made a breakthrough by learning about the genetic changes that occur during tumor migration -- and also found a drug that can obstruct the process.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('5f6cbfbb-324d-54de-a5d3-dcf2ea8072ac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5f6cbfbb-324d-54de-a5d3-dcf2ea8072ac'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'In normal circumstances would four hours of sleep per night be too much, too little or just right for most people?', 'c351ebb1-ea5f-5423-af4a-5d10192ab6ea'::uuid, NULL, NULL, E'Too little', NULL, NULL),
  ('5f6cdf24-bdf4-5799-8fea-f64c95079a04'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5f6cdf24-bdf4-5799-8fea-f64c95079a04'::uuid, 1, NULL, TRUE, 0, NULL, E'Spring Water', E'Spring water comes from a protected, underground water source from which the water flows to the surface on its own. It may be collected either at the surface spring or through a sanitary, protected hole drilled directly into the source feeding the spring. If the water is collected through a hole drilled into the source, it has to have exactly the same composition as the water in the surface spring.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('5f730c5d-dfe4-553b-9fce-a3dbd9e4db62'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5f730c5d-dfe4-553b-9fce-a3dbd9e4db62'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a young cow?', 'c63050f5-81fc-5c74-8aaf-3c5af633d87d'::uuid, NULL, NULL, E'Calf / calves', NULL, NULL),
  ('5f781b12-94a5-5034-9a60-0c43f60e5bab'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5f781b12-94a5-5034-9a60-0c43f60e5bab'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6f9dbd7b-59bd-56e3-b2ba-4c901fa861e5'::uuid, NULL, NULL, E'Biology involves the study of life at all levels.', NULL, NULL),
  ('5f7a871a-d5c2-59d4-8dc9-e2ecfca6e2ed'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5f7a871a-d5c2-59d4-8dc9-e2ecfca6e2ed'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we usually call dogs and cats who live with us?', '739820d8-528e-5b11-84ba-44dad2e58b2e'::uuid, NULL, NULL, E'pets / pet', NULL, NULL),
  ('5f8ad26a-9491-510b-970a-a85ca4ab4e9e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5f8ad26a-9491-510b-970a-a85ca4ab4e9e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ecb1c391-d2c7-55c2-9300-43a1fdba7355'::uuid, NULL, E'The U.S. ranks twenty second in foreign aid, given the percentage of GDP.', NULL, NULL, NULL),
  ('5f8dce76-d725-57c6-8a21-7ac514ec4093'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5f8dce76-d725-57c6-8a21-7ac514ec4093'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '405f3569-15d2-52b1-bfc7-4bbd191256aa'::uuid, NULL, NULL, E'In this sector you will meet experts in accounting and financing.', NULL, NULL),
  ('5f8eaadf-7491-5dbd-8852-4b244e662e96'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5f8eaadf-7491-5dbd-8852-4b244e662e96'::uuid, 1, NULL, TRUE, 0, NULL, E'Night Sky Darkness', NULL, '2cec1d4b-9c70-540a-8c68-21c641cdc664'::uuid, NULL, E'Our friends at the Highlands Museum and Discovery Center in Ashland, Kentucky, asked a very good question. Why is it dark in space?That question is not as simple as it may sound. You might think that space appears dark at night because that is when our side of Earth faces away from the Sun as our planet rotates on its axis every 24 hours. But what about all those other far away suns that appear as stars in the night sky? Our own Milky Way galaxy contains over 200 billion stars, and the entire universe probably contains over 100 billion galaxies. You might suppose that that many stars would light up the night like daytime!Until the 20th century, astronomers didn''t think it was even possible to count all the stars in the universe. They thought the universe went on forever. In other words, they thought the universe was infinite.Besides being very hard to imagine, the trouble with an infinite universe is that no matter where you look in the night sky, you should see a star. Stars should overlap each other in the sky like tree trunks in the middle of a very thick forest. But, if this were the case, the sky would be blazing with light. This problem greatly troubled these astronomers and became known as "Olbers'' Paradox." A paradox is a statement that seems to disagree with itself.To try to explain the paradox, some 19th century scientists thought that dust clouds between the stars must be absorbing a lot of the starlight so it wouldn''t shine through to us. But later scientists realized that the dust itself would absorb so much energy from the starlight that eventually it would glow as hot and bright as the stars themselves.Astronomers now realize that the universe is not infinite. A finite universe—that is, a universe of limited size—even one with trillions and trillions of stars, just wouldn''t have enough stars to light up all of space.Although the idea of a finite universe explains why Earth''s sky is dark at night, other causes work to make it even darker.', NULL, NULL, NULL),
  ('5f95af4d-ae49-5d25-8e82-89394b4a6015'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5f95af4d-ae49-5d25-8e82-89394b4a6015'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'dfb5faff-002b-5d12-a390-40800e2e935d'::uuid, NULL, NULL, E'People need basic education if they want to become employable.', NULL, NULL),
  ('5fa2c954-211a-5f6f-a8ac-ff9d59e9b22b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '5fa2c954-211a-5f6f-a8ac-ff9d59e9b22b'::uuid, 1, NULL, TRUE, 0, NULL, E'Management', E'Event management is particularly challenging from an operational viewpoint. In many cases, events are staged on sites where everything has been set up over a 24-hour period, with all elements carefully {{1}} . In contrast, many events are years in the planning: large convention bids are often won five years before the event is held. For the very {{2}} bidding process, budgets need to be developed and prices quoted, requiring a good understanding of market, economic and political trends, as well as consumer choices. This long-term view is the basis of strategic management, which is covered in Part 1, and focuses on the event concept, feasibility of the event, legal compliance and financial management. Marketing is a critical {{3}} factor and another important topic of this first section, many events (sporting, cultural and arts) involving long-term sponsorship {{4}} with key industry players. Relationship building is particularly {{5}} since there are so many stakeholders involved in events, including government agencies at many levels. Part 1 will look at all these aspects, including strategic risk, before moving on to the second part where operational planning and implementation will be covered in detail.', NULL, NULL, NULL, E'1.synchronised, 2.competitive, 3.success, 4.arrangements, 5.challenging', NULL, NULL),
  ('5fa2d86e-e1a0-55e0-abb1-e1cd004f64f6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '5fa2d86e-e1a0-55e0-abb1-e1cd004f64f6'::uuid, 1, NULL, TRUE, 0, NULL, E'Paris', E'Paris is very old — there has been a settlement there for at least 6,000 years and its shape has been determined in {{2}} by the River Seine, and in part by the edicts of France'' s rulers. But the great boulevards we admire today are relatively new, and were constructed to prevent any more barricades being {{4}} by the rebellious population; that work was carried out in the middle 19th century. The earlier Paris had been in part a maze of narrow streets and alleyways. But you can imagine that the work was not only highly expensive, but caused great distress among the half a million or so whose houses were {{5}} razed, and whose neighborhoods disappeared. What is done cannot usually be undone, especially when buildings are torn {{6}} .', NULL, NULL, NULL, E'1.part, 2.created, 3.simply, 4.down', NULL, NULL),
  ('5fa838c1-3007-546e-8d16-166ac3fc036e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5fa838c1-3007-546e-8d16-166ac3fc036e'::uuid, 1, NULL, TRUE, 0, NULL, E'Monster Waves', E'Long considered myth, freakishly large rogue waves are very real and can split apart ships and even damage oil rigs. Using 700 years'' worth of wave data from more than a billion waves, scientists at the University of Copenhagen and University of Victoria have used artificial intelligence to find a formula for how to predict the occurrence of these maritime monsters.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('5fb19420-b426-5f75-9906-1ff63b9a1f3e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5fb19420-b426-5f75-9906-1ff63b9a1f3e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ef01be32-d723-505d-bc78-4606ff542659'::uuid, NULL, E'Most supermarkets in this country sell a range of organic products.', NULL, NULL, NULL),
  ('5fb69676-af52-54fa-8067-d3ff5e036e4e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '5fb69676-af52-54fa-8067-d3ff5e036e4e'::uuid, 1, NULL, TRUE, 0, NULL, E'William Shakespeare', E'For all his fame and celebration, William Shakespeare remains a(n) {{1}} figure with regards to personal history. There are just two primary {{2}} for information on the Bard: his works, and various legal and {{3}} documents that have survived from Elizabethan times. Naturally, there are many {{4}} in this body of information, which tells us little about Shakespeare the man.', NULL, NULL, NULL, E'1.mysterious, 2.sources, 3.church, 4.gaps', NULL, NULL),
  ('5fbf5899-5134-59d5-ac19-70f935fa9954'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '5fbf5899-5134-59d5-ac19-70f935fa9954'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a5c09b2d-4906-5050-aa2b-3eafd847a7a3'::uuid, NULL, E'Australia''s economy relies a lot on money from visitors and education institutions.', NULL, NULL, NULL),
  ('5fbfdf95-7b3f-57b5-b3e0-7cc4395eda5c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5fbfdf95-7b3f-57b5-b3e0-7cc4395eda5c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '49b7ac86-a40b-59dc-9237-48abdd5b1631'::uuid, NULL, NULL, E'An increase in university tuition fees is anticipated for next year.', NULL, NULL),
  ('5fc4b47a-8bd0-560f-846e-8de7e2fa2c7b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5fc4b47a-8bd0-560f-846e-8de7e2fa2c7b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f0f59459-0840-55fb-9efb-125257866324'::uuid, NULL, NULL, E'Since the start of the year, the marketing budget has grown.', NULL, NULL),
  ('5fcb4862-7237-5ba4-8a55-61a21d39badd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '5fcb4862-7237-5ba4-8a55-61a21d39badd'::uuid, 1, NULL, TRUE, 0, NULL, E'Australian Education', E'When Australians engage in debate about educational quality or equity, they often seem to accept that a country cannot achieve both at the same time. Curriculum reforms intended to improve equity often fail to do so because they increase breadth or differentiation in offerings in a way that increases differences in quality. Further, these differences in quality often reflect differences in students’ social backgrounds because the ‘new’ offerings are typically taken up by relatively disadvantaged students who are not served well them. Evidence from New South Wales will be used to illustrate this point. The need to improve the quality of education is well accepted across OECD and other countries as they seek to strengthen their human capital to underpin their modern, knowledge economies. Improved equity is also important for this purpose, since the demand for high level skills is widespread and the opportunities for the low skilled are diminishing. Improved equity in education is also important for social cohesion. There are countries in which the education system seems primarily to reproduce existing social arrangements, conferring privilege where it already exists and denying it where it does not. Even in countries where the diagnosis might be less extreme, the capacity of schooling to build social cohesion is often diminished by the way in which schools separate individuals and groups.', NULL, NULL, E'Australians seem to believe that they cannot achieve educational quality and equity at the same time, as curriculum reforms intended to improve equity often fail to do so, while these differences in quality often reflect differences in students’ social backgrounds, but improved equity is also important since the demand for high level skills is widespread and the opportunities for the low skilled are diminishing, and improved equity in education is also important for social cohesion.', NULL, 5, 75),
  ('5fcd81ec-8109-59b4-8a61-96f58a5ea51e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '5fcd81ec-8109-59b4-8a61-96f58a5ea51e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '11fab60f-8c3c-5255-b4b6-d5a1479834bd'::uuid, NULL, NULL, E'All medical students must clean their hands before entering the room.', NULL, NULL),
