  ('601a6fa4-6efd-56e1-8f26-2a6a8dffa9e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '601a6fa4-6efd-56e1-8f26-2a6a8dffa9e1'::uuid, 1, NULL, TRUE, 0, NULL, E'Artificial Neural Networks', E'Artificial Neural Networks have recently become the state-of-the-art technique for crucial signal processing applications such as specific frequencies classification, structural health monitoring, diseases detection in power electronics circuitry and motor-fault detection. This is an expected outcome as there are numerous advantages of using an adaptive and compact deep counterparts. Particularly, it can be efficiently trained with a limited dataset of signals, besides requiring data transformation.', NULL, NULL, NULL, NULL, NULL, NULL),
