  ('609cc2f0-fa92-5477-8081-41b6668ea150'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '609cc2f0-fa92-5477-8081-41b6668ea150'::uuid, 1, NULL, TRUE, 0, NULL, E'Maya', E'The Classic era of Mayan {{1}} came to an end around 900 AD. Why this happened is unclear; the cities were probably over-farming the land, so that a {{2}} of drought led to famine. Recent geological {{3}} supports this, as there appears to have been a 200-year drought around this time.', NULL, NULL, NULL, E'1.civilization, 2.period, 3.research', NULL, NULL),
