  ('60c02474-7633-5e83-a193-ffa4431b46f6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '60c02474-7633-5e83-a193-ffa4431b46f6'::uuid, 1, NULL, TRUE, 0, NULL, E'Environment Effect', E'Some people say that people are defined by the place where they grew up, but some argue that the environment only has little effect. To what extent do you agree or disagree? Use a celebrity you know to support your opinion.', NULL, NULL, NULL, NULL, 200, 300),
  ('60c120c2-912a-5b95-afdd-ee412bf3c727'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '60c120c2-912a-5b95-afdd-ee412bf3c727'::uuid, 1, NULL, TRUE, 0, NULL, E'Trade-off', E'"It appears that in the process of {{1}} specialized face-recognition abilities to quickly and accurately {{2}} important information, there has been a trade-off where face-like images in {{3}} orientations become especially difficult to process," he says. "The {{4}} for this trade-off is unclear, but it probably {{5}} to the fact that you rarely see inverted faces", says Sheehan.', NULL, NULL, NULL, E'1.evolving, 2.extract, 3.unexpected, 4.reason, 5.relates', NULL, NULL),
