  ('61264c6a-cd39-5097-b8ec-b3815dcecb81'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '61264c6a-cd39-5097-b8ec-b3815dcecb81'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '26a44b89-c93d-5c9d-aa93-adfed41bc29c'::uuid, NULL, E'They will announce the result of the vote at the dining hall tonight.', NULL, NULL, NULL),
  ('613087cd-3970-5975-8c71-ce249e22f6fa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '613087cd-3970-5975-8c71-ce249e22f6fa'::uuid, 1, NULL, TRUE, 0, NULL, E'Great Feedback', NULL, '968c5467-9a00-5184-94e9-a1d4ecd0fc93'::uuid, NULL, E'Great feedback givers begin their feedback by asking a question that is short but important. It lets the brain know that feedback is actually coming. It would be something, for example, like, “Do you have five minutes to talk about how that last conversation went” or “I have some ideas for how we can improve things. Can I share them with you?” This micro-yes question does two things for you. First of all, it’s going to be a pacing tool. It lets the other person know that feedback is about to be given. And the second thing it does is it creates a moment of buy-in. I can say yes or no to that yes or no question. And with that, I get a feeling of autonomy. The second part of the feedback formula is going to be giving your data point. Here, you should name specifically what you saw or heard, and cut out any words that aren’t objective. There’s a concept we call blur words. A blur word is something that can mean different things to different people. Blur words are things that are not specific. So for example, if I say “You shouldn’t be so defensive” or “You could be more proactive.” What we see great feedback givers doing differently is they’ll convert their blur words into actual data points. So for example, instead of saying, “You know you aren’t reliable,” we would say, “You said you’d get that email to me by 11, and I still don’t have it yet.” Specificity is also important when it comes to positive feedback, and the reason for that is that we want to be able to specify exactly what we want the other person to increase or diminish. And if we stick with blur words, they actually won’t have any clue particularly what to do going forward to keep repeating that behavior.', NULL, NULL, NULL),
  ('613f00ed-faeb-579a-a547-ec99f3c49c26'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '613f00ed-faeb-579a-a547-ec99f3c49c26'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c991c67b-fd87-5512-b8d8-4686dcbdd05d'::uuid, NULL, E'The big house was surrounded by a tall wooden fence.', NULL, NULL, NULL),
