  ('6140c299-cdf8-502d-9273-2be19420e69d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6140c299-cdf8-502d-9273-2be19420e69d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3c12480d-64dd-53ca-8ccb-e7b0d793998d'::uuid, NULL, E'In Canada, children prefer to go to public schools instead of private ones.', NULL, NULL, NULL),
  ('61446f67-f722-5011-9fe5-a4983f36828c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '61446f67-f722-5011-9fe5-a4983f36828c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '03bdd7f6-7729-5721-ad0f-b677e895d014'::uuid, NULL, E'The government has to find some way to balance these two needs.', NULL, NULL, NULL),
  ('614510e6-04d6-5438-8e41-b007ce624aac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '614510e6-04d6-5438-8e41-b007ce624aac'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '629b364e-82e8-55ac-8c6e-be9db6df6abc'::uuid, NULL, E'Even during leisure time you can hear attempts to persuade or influence.', NULL, NULL, NULL),
  ('6149ac59-5118-53cf-b334-56ee8ebb0930'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '6149ac59-5118-53cf-b334-56ee8ebb0930'::uuid, 1, NULL, TRUE, 0, NULL, E'Continent Drifting', E'According to the theory of continental drift, the world was made up of a single continent through most of geologic time. That continent eventually separated and drifted apart, forming into the seven continents we have today. The first comprehensive theory of continental drift was suggested by the German meteorologist Alfred Wegener in 1912. The hypothesis asserts that the continents consist of lighter rocks that rest on heavier crustal material—similar to the manner in which icebergs float on water. Wegener contended that the relative positions of the continents are not rigidly fixed but are slowly moving—at a rate of about one yard per century.\nAccording to the generally accepted plate-tectonics theory, scientists believe that Earth''s surface is broken into a number of shifting slabs or plates, which average about 50 miles in thickness. These plates move relative to one another above a hotter, deeper, more mobile zone at average rates as great as a few inches per year. Most of the world''s active volcanoes are located along or near the boundaries between shifting plates and are called plate-boundary volcanoes. The peripheral areas of the Pacific Ocean Basin, containing the boundaries of several plates, are dotted with many active volcanoes that form the so-called Ring of Fire. The Ring provides excellent examples of plate-boundary volcanoes, including Mount St. Helens. However, some active volcanoes are not associated with plate boundaries, and many of these so-called intra-plate volcanoes form roughly linear chains in the interior of some oceanic plates. The Hawaiian Islands provide perhaps the best example of an intra-plate volcanic chain, developed by the northwest-moving Pacific plate passing over an inferred "hot spot" that initiates the magma-generation and volcano-formation process.', NULL, NULL, E'According to the theory of continental drift, the world was made up of a single continent, which eventually drifted apart, forming into the seven continents we have today, and scientists believe that Earth’s surface is broken into a number of shifting slabs or plates, which move relative to one another above a hotter, deeper, more mobile zone, and along whose boundaries most active volcanoes are located, despite some in the interior.', NULL, 5, 75),
  ('6149b551-2174-59c7-aff9-6a450c406777'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '6149b551-2174-59c7-aff9-6a450c406777'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '70e65c92-794a-58b1-b377-58cd4f0a76c3'::uuid, NULL, NULL, E'I went down into the cellar for more wine.', NULL, NULL),
  ('614c3b99-5ae4-5304-a6b7-23798f0924c9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '614c3b99-5ae4-5304-a6b7-23798f0924c9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '12a76cca-79e6-5625-af97-bb555a9668a8'::uuid, NULL, E'You are not permitted to take reference books out of the library.', NULL, NULL, NULL),
  ('615159a5-4103-53ec-8ebb-bc2c7f998ea9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '615159a5-4103-53ec-8ebb-bc2c7f998ea9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd6b64326-c0b3-5aa8-bfe5-ddf036991e87'::uuid, NULL, E'The contemporary literature works have been broadened and extended through interpretation.', NULL, NULL, NULL),
  ('6155d6ec-36c6-5409-aa3d-65efd9ef0a45'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '6155d6ec-36c6-5409-aa3d-65efd9ef0a45'::uuid, 1, NULL, TRUE, 0, NULL, E'Twin Studies', E'Twin studies have been very useful in giving us information about whether our genes or our environment makes us who we are. A surprising result is the way that genes influence our work. At a basic level, our genes affect how we look and so they influence whether we can become a basketball player or a supermodel, for example. However, there is evidence that genes influence our job choice in much greater ways.\nResearch shows that identical twins choose more similar jobs than non-identical twins. In fact, identical twins who have grown up apart choose more similar jobs than non-identical twins who have grown up together. Studies also show that identical twins suggests that our genes affect both the satisfaction that comes from doing a job and satisfaction that comes from working conditions such as a person''s pay or their manager.\nSo what does this mean? It means that from birth, you are more likely to prefer one occupation to another and find certain jobs more satisfying than others. However, genes are not the only factor. Other things in your life, such as family background and education, will also be influential in your career choices.', NULL, NULL, E'Twin studies reveal a surprising result that genes have a greater influence on our job choices than we expected, which means people with similar genes are more likely to choose similar jobs and get satisfaction at the same level.', NULL, 5, 75),
  ('6161b690-719a-56a6-a8f0-d4831d17afcd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6161b690-719a-56a6-a8f0-d4831d17afcd'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What term refers to a system of government in which priests rule in the name of God or a god?', '53201ebe-04c6-54ef-b949-f58816d1c727'::uuid, NULL, NULL, E'Theocracy', NULL, NULL),
  ('616fe636-a773-51eb-b616-f865c2c02dff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '616fe636-a773-51eb-b616-f865c2c02dff'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do you call the tower containing a beacon light to warn or guide ships at sea?', 'ed10f55e-8cde-57a9-8622-ad30a0a54ce7'::uuid, NULL, NULL, E'Light house / beacon', NULL, NULL),
