  ('61a4ec43-d81b-521f-87f5-ec7a81cde765'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '61a4ec43-d81b-521f-87f5-ec7a81cde765'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2d0ca0fe-4713-51d6-aaf5-9c4d7eba5ca8'::uuid, NULL, NULL, E'Students are encouraged to participate in one of the summer programs.', NULL, NULL),
  ('61a70e3a-4d97-59b0-80b8-d3abe29e54df'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '61a70e3a-4d97-59b0-80b8-d3abe29e54df'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person who is waiting for doing something?', 'cfd57c84-59ab-5713-87ef-06f70aee4632'::uuid, NULL, NULL, E'Standby', NULL, NULL),
  ('61a7a19b-c628-5e54-8c63-08df017dc6a2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '61a7a19b-c628-5e54-8c63-08df017dc6a2'::uuid, 1, NULL, TRUE, 0, NULL, E'Technology and Life', E'Technology has made the world a better place to live. To what extent do you agree with this statement?', NULL, NULL, E'I strongly agree that technology has made the world a better place to live. Its profound impact on our daily lives and global society is overwhelmingly positive, primarily because it enhances our well-being and bridges human connections across distances, fundamentally improving how we live and interact.\nFirstly, technology acts as a powerful tool for improving health and safety, directly creating a safer world. Advanced medical technology, such as MRI scanners and modern vaccines, allows for the early detection and effective treatment of diseases, saving countless lives. In our homes, smart devices like automatic lights and security systems help prevent accidents and deter crime. This integration of technology into healthcare and daily security provides peace of mind and a more protected environment for everyone.\nSecondly, technology has revolutionized communication, making the world a more connected and accessible community. Where once distance was a barrier, communication technology now allows for instant, free video calls with loved ones anywhere on the globe, keeping families close. Furthermore, the internet provides unprecedented access to information, from online educational courses that offer free skill-building to platforms that allow us to share experiences and cultures. This connectivity fosters understanding and makes lifelong learning a possibility for all, enriching our collective experience.\nIn conclusion, while technology presents challenges, its benefits in safeguarding our lives and uniting humanity are undeniable. By making us healthier, safer, and more interconnected, technology has undeniably transformed the world into a significantly better place for all.', NULL, 200, 300),
  ('61ab14eb-593b-503c-97cf-a7818c0fac80'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '61ab14eb-593b-503c-97cf-a7818c0fac80'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4b0bd9b8-992f-513d-a25f-3d8b8f3d4693'::uuid, NULL, E'A detailed list of our publications is available on request.', NULL, NULL, NULL),
  ('61ab90d2-f014-51e6-ae85-2bc1b57a9be3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '61ab90d2-f014-51e6-ae85-2bc1b57a9be3'::uuid, 1, NULL, TRUE, 0, NULL, E'Absenteeism', E'Absence from work is a costly and {{1}} problem for any organization. The cost of absenteeism in Australia has been put at 1.8 million hours per day or $1400 million annually. The study reported here was {{2}} in the Prince William Hospital in Brisbane, Australia, where, prior to this time, few active steps {{3}} been taken to measure, understand or manage the {{4}} of absenteeism.', NULL, NULL, NULL, E'1.disruptive, 2.conducted, 3.had, 4.occurrence', NULL, NULL),
  ('61acd287-6a46-56cd-b75c-77fc335a73c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '61acd287-6a46-56cd-b75c-77fc335a73c8'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ab9d3898-510c-5c02-bb68-4af2f6224d38'::uuid, NULL, E'Each student has been given their own email address by the school.', NULL, NULL, NULL),
  ('61ae7397-898f-5220-895a-2582d71b2ed8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '61ae7397-898f-5220-895a-2582d71b2ed8'::uuid, 1, NULL, TRUE, 0, NULL, E'Vaccines', E'Vaccines work by training and preparing the body’s natural defences – the immune system – to recognize and fight off viruses and bacteria. If the body is exposed to those disease-causing pathogens later, it will be ready to destroy them quickly – which prevents illness. When a person gets vaccinated against a disease, their risk of infection is also reduced.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('61af7357-8427-5b99-88b9-231e80528dcb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '61af7357-8427-5b99-88b9-231e80528dcb'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is it that you wear on your wrist and that tells you time?', '388c4cf0-713a-5758-af4d-bf267688bf81'::uuid, NULL, NULL, E'Wrist watch / watch', NULL, NULL),
  ('61b02933-4f9a-5d2d-9f65-ca87ba2eb114'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '61b02933-4f9a-5d2d-9f65-ca87ba2eb114'::uuid, 1, NULL, TRUE, 0, NULL, E'Living in Cities', NULL, NULL, NULL, NULL, E'1, 3, 4, 2', NULL, NULL),
  ('61b29594-4415-53d5-aea7-285667b439e2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '61b29594-4415-53d5-aea7-285667b439e2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3e854956-4817-58c3-ab0c-53b5cf303ba0'::uuid, NULL, NULL, E'Students who are successful have a good strategy for learning.', NULL, NULL),
  ('61b4edff-1956-5b6f-82a2-ae306472d661'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '61b4edff-1956-5b6f-82a2-ae306472d661'::uuid, 1, NULL, TRUE, 0, NULL, E'Pinker', E'Steven Pinker, a cognitive psychologist best known for his book "The Language Instinct", {{1}} music "auditory cheesecake, an exquisite confection crafted to tickle the sensitive spots of at least six of our mental faculties." If it vanished from our species, he said, "the rest of our lifestyle would be {{2}} unchanged." Others have argued that, on the {{3}} , music, along with art and literature, is part of what makes people human; its absence would have a brutalizing effect. Philip Ball, a British science writer and an {{4}} music enthusiast, comes down somewhere in the middle. He says that music is {{5}} in our auditory, cognitive and motor functions. We have a music instinct as much as a language instinct, and could not rid ourselves of it if we tried.', NULL, NULL, NULL, E'1.has called, 2.virtually, 3.contrary, 4.avid, 5.ingrained', NULL, NULL),
  ('61b61af3-1d36-5855-a7d5-67d08e1bf027'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '61b61af3-1d36-5855-a7d5-67d08e1bf027'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which kind of energy makes light bulbs work?', '2fe1a215-cb62-5542-a814-6e3494652fd6'::uuid, NULL, NULL, E'Electricity', NULL, NULL),
  ('61b8dd59-3b9c-5779-86fc-bd8a8d56d067'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '61b8dd59-3b9c-5779-86fc-bd8a8d56d067'::uuid, 1, NULL, TRUE, 0, NULL, E'Fluid Intelligence', E'Fluid intelligence is the type of intelligence that has to do with short-term memory and the ability to think quickly, logically, and abstractly in {{1}} to solve new problems. It {{2}} in young adulthood, levels out for a period of time, and then generally starts to slowly {{3}} as we age. But {{4}} aging is inevitable, scientists are finding out that certain changes in brain function may not be.', NULL, NULL, NULL, E'1.order, 2.peaks, 3.decline, 4.while', NULL, NULL),
  ('61be0d6d-880d-52dd-98b4-66c87fa2a052'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '61be0d6d-880d-52dd-98b4-66c87fa2a052'::uuid, 1, NULL, TRUE, 0, NULL, E'Evolution of Human Beings', E'Dr. Philip Lieberman of Brown University explained on NPR''s "The Human Edge" that after humans {{1}} from an early-ape ancestor more than 100,000 years ago, the shape of the mouth and vocal tract changed, with the tongue and larynx, or voice box, moving further down the tract. The tongue became more {{2}} and independent and was able to be controlled more precisely. The tongue is attached to the hyoid bone, which is not attached to any other bones in the body. Meanwhile, the human neck grew longer to accommodate the tongue and larynx, and the human mouth grew smaller. The larynx is lower in the throats of humans than it is in chimpanzees, which, along with the increased flexibility of the mouth, tongue, and lips, is what enables humans to speak as well as to change {{3}} and sing. The ability to speak and develop language was an enormous advantage for humans. The disadvantage of this {{4}} development is that this flexibility comes with an increased risk of food going down the wrong tract and causing choking.', NULL, NULL, NULL, E'1.diverged, 2.flexible, 3.pitch, 4.evolutionary', NULL, NULL),
  ('61beee9b-e9a9-59e4-aa96-0fb869b83666'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '61beee9b-e9a9-59e4-aa96-0fb869b83666'::uuid, 1, NULL, TRUE, 0, NULL, E'Specific Compounds', E'Specific compounds are transformed by and strongly associated with specific bacteria in native biological soil crust (biocrust) using a suite of tools called ''exometabolomics.'' Understanding how microbial communities in biocrusts adapt to harsh environments could shed light on the roles of soil microbes in the global carbon cycle.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('61c331f2-7464-57d3-b2ca-692483d9c0b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '61c331f2-7464-57d3-b2ca-692483d9c0b9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '871417c5-5ae8-5934-80c7-50a854c0b3c0'::uuid, NULL, NULL, E'Farmers used to hire themselves out to whoever needed them.', NULL, NULL),
  ('61c33343-2b44-570d-9e9f-1789f128c4e5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '61c33343-2b44-570d-9e9f-1789f128c4e5'::uuid, 1, NULL, TRUE, 0, NULL, E'Bioprinting', E'3D bioprinting is the process of 3D printing a biological structure using bioinks consisting of cells and other biological materials. This innovation can be used in the medical field for different {{1}} , especially for organ transplants. As of now, transplant patients {{2}} the risk of organ rejection, an instance where the body recognizes a donor organ as foreign body and enlists the immune system to treat it as such. {{3}} the donor organ is necessary to the patient, other measures need to be taken to try to stop the immune system from fighting against it. The use of bioinks and specialization of 3D bioprinters can {{4}} in less rigorous medical therapies for these patients. 3D bioprinted organs were hypothesized to induce a better response from the immune system than current donor organs do. The conclusion that 3D bioprinting can lead to better lifestyles for organ transplant patients and less rejection by the human immune system was reached after research {{5}} the use of autologous cells and specialized cells in 3D bioprinting.', NULL, NULL, NULL, E'1.procedures, 2.run, 3.Since, 4.result, 5.showed', NULL, NULL),
  ('61c6f201-0e6a-5047-a37e-f9d2309ebf58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '61c6f201-0e6a-5047-a37e-f9d2309ebf58'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f0b2c7ed-b23a-52c2-b344-2685002afe8b'::uuid, NULL, NULL, E'Experts of the financial department will give the guests a lecture.', NULL, NULL),
