  ('61d1d838-3fb4-5f51-9089-6e9574e6478e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '61d1d838-3fb4-5f51-9089-6e9574e6478e'::uuid, 1, NULL, TRUE, 0, NULL, E'Science of Smiling', E'Smiling is a universal sign of happiness and positivity, but did you know that it also has a physiological effect on the body? When you smile, your brain releases endorphins, which are natural painkillers and mood boosters. This may be why smiling is so contagious and can have a positive impact on those around you.', NULL, NULL, NULL, NULL, NULL, NULL),
