  ('634344a4-dfb6-5e56-8b45-56e5224fe99f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '634344a4-dfb6-5e56-8b45-56e5224fe99f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the opposite of majority?', '4a283cea-c3e2-5bf2-8d40-b4ccbc18dc01'::uuid, NULL, NULL, E'Minority', NULL, NULL),
  ('634637d6-79b2-5962-9057-341a198d0485'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '634637d6-79b2-5962-9057-341a198d0485'::uuid, 1, NULL, TRUE, 0, NULL, E'Telepsychiatry', E'The COVID-19 pandemic created an enormous level of stress on a global scale, leading to elevated levels of anxiety, depression, and other mental illnesses. Along with this was a disruption and challenges in the delivery of mental health services that were traditionally provided in the office. This disruption, increasing need, and the already limited access to mental health services could create a very challenging situation. To prevent that, we had to make a robust transition in our ways of delivering services to videoconferencing and allowing coverage by the payors.\nLike other transitions, adopting the use of technology was challenging for many, especially in the absence of high-speed internet infrastructure for some patients. For those with limited logistics or knowledge of video-conferencing, often the sessions take place over the phone, which reduces access to a patient’s nonverbal behavior. Sound quality might not be great, leading to extended time for enabling sufficient communication. Although in psychiatry physical examination is used less often than in most other medical specialties, when it is needed, telepsychiatry is a barrier.\nDespite these challenges, telepsychiatry has provided enormous opportunities, especially for less economically privileged patients. For an office visit, one must take time off work, find child support, and have access to reliable transportation to make it to the visit. For those with limited resources, or in areas far from psychiatric services, this would lead to frequent interruptions in care and economic cost. Telepsychiatry has overcome those barriers. Patients can connect to providers regardless of their geographical location, and connect while at home near their children, during their lunch break, or even from their car in the parking lot.', NULL, NULL, NULL, NULL, 5, 75),
  ('634f626a-57af-5bfb-a883-3205af2b7f4e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '634f626a-57af-5bfb-a883-3205af2b7f4e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person who writes books, stories, or articles?', '08520790-6870-5035-8114-cfe97aa29dfa'::uuid, NULL, NULL, E'Author', NULL, NULL),
