  ('6350ac7c-d063-57cd-8e8e-12264bf187dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '6350ac7c-d063-57cd-8e8e-12264bf187dd'::uuid, 1, NULL, TRUE, 0, NULL, E'Technology', E'Technology allows us to have a more helpful and interesting life than in the past. Do you agree or disagree?', NULL, NULL, NULL, NULL, 200, 300),
  ('63561eb1-12db-58eb-af4e-bd039ffae2b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '63561eb1-12db-58eb-af4e-bd039ffae2b8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do you describe the period of time when it rains a lot?', '5c44bc70-af6a-54b6-9e0c-453ff78f8921'::uuid, NULL, NULL, E'Rainy', NULL, NULL),
  ('635c65a9-01e5-5e3c-a6c2-9d9472eb4e45'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '635c65a9-01e5-5e3c-a6c2-9d9472eb4e45'::uuid, 1, NULL, TRUE, 0, NULL, E'Organic Farming', E'To what extent do you think that organic farming can feed the world population?', NULL, NULL, E'The question of whether organic farming can sufficiently feed the global population is a complex and pressing issue in today''s agricultural landscape. Organic farming practices offer a range of benefits that contribute to sustainable food production and environmental stewardship.\nOrganic farming plays a crucial role in enhancing soil health and fertility, which are essential for sustainable crop production. By avoiding synthetic chemicals and embracing natural methods, organic farmers enrich the soil with nutrients and beneficial microorganisms, fostering long-term productivity and resilience in agricultural systems.\nFurthermore, the practice of crop rotation in organic farming serves as a natural pest control method, reducing the reliance on chemical pesticides. By alternating crops, organic farmers disrupt pest life cycles and prevent the buildup of pest populations, promoting a balanced ecosystem that supports biodiversity and minimizes the risk of crop damage.\nIn conclusion, organic farming holds significant promise in addressing the challenge of feeding the world population sustainably. Through its focus on soil health, pest management, and biodiversity conservation, organic agriculture offers a holistic approach to food production that not only nourishes people but also protects the environment for future generations. Embracing and scaling up organic farming practices can play a pivotal role in ensuring food security while preserving the health of our planet.', NULL, 200, 300),
  ('636664d7-987d-5024-9274-0b5225e67ea8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '636664d7-987d-5024-9274-0b5225e67ea8'::uuid, 1, NULL, TRUE, 0, NULL, E'Modern Dance', NULL, 'a11fe9c9-75c2-5cad-9cf5-9162cde05f6a'::uuid, NULL, E'So, why did what is now called "modern dance" begin in the United States? To begin to answer this question, I''ll need to backtrack a little bit and talk about classical ballet. By the late 1800''s, ballet had lost a lot of its popularity. Most of the ballet dancers who performed in the United States were brought over from Europe. They performed using the rigid techniques that had been passed down through the centuries. Audiences and dancers in the United States were eager for their own, "contemporary" dance form. And, so, around 1900, dancers created one. So, how was this "modern" dance so different from classical ballet? Well, most notably, it wasn''t carefully choreographed. Instead, the dance depended on the improvisation and free, personal expression of the dancers. Music and scenery were of little importance to the "modern" dance, and lightness of movement wasn''t important either. In fact, modern dancers made no attempt at all to conceal the effort involved in a dance step. But even if improvisation appealed to audiences, many dance critics were less than enthusiastic about the performances. They questioned the artistic integrity of dancers who were not professionally trained and the artistic value of works that had no formal structure. Loie Fuller, after performing Fire Dance, was described as doing little more than turning "round and round like an eggbeater." Yet, the free, personal expression of the pioneer dancers is the basis of the "controlled freedom" of modern dance today.', NULL, NULL, NULL),
  ('636912b6-77a2-55dc-ad3e-89803718db58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '636912b6-77a2-55dc-ad3e-89803718db58'::uuid, 1, NULL, TRUE, 0, NULL, E'Genetic Modification', NULL, NULL, NULL, NULL, E'2, 3, 1, 4', NULL, NULL),
  ('63691cca-5001-5175-8ac2-b287a4cab046'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '63691cca-5001-5175-8ac2-b287a4cab046'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a student who is in his first year at a college?', 'e7291e8f-7b8e-54ab-986b-2b62904da914'::uuid, NULL, NULL, E'Freshman', NULL, NULL),
