  ('6430e3fd-fd61-5ceb-8cf0-dbb6f1f6c8f4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6430e3fd-fd61-5ceb-8cf0-dbb6f1f6c8f4'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5ed68d2a-6882-5a21-8892-04554fc60a99'::uuid, NULL, E'We didn''t notice any significant variance among the two or three tasks.', NULL, NULL, NULL),
