  ('6446026e-c6f7-5e61-83af-ca90b18d3b53'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6446026e-c6f7-5e61-83af-ca90b18d3b53'::uuid, 1, NULL, TRUE, 0, NULL, E'Bear Genes', E'The internal clocks of grizzly bears appear to keep ticking through hibernation, according to a genetic study. This persistence highlights the strong role of circadian rhythms in the metabolism of many organisms including humans. The genetic study confirmed observational evidence that bears'' energy production still waxes and wanes in a daily pattern even as they slumber for several months without eating.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('6452b337-ff29-53d9-9a83-c8f2394b4147'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6452b337-ff29-53d9-9a83-c8f2394b4147'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the meat of a pig that is used for food?', '68557b40-4a5f-52b4-8590-ce1cf1ffe4e9'::uuid, NULL, NULL, E'Pork', NULL, NULL),
  ('645a3b8e-8281-584d-adc8-7ac9b954aadf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '645a3b8e-8281-584d-adc8-7ac9b954aadf'::uuid, 1, NULL, TRUE, 0, NULL, E'Graduation Gifts', E'The practice of giving graduation gifts seems to be alive and well, despite {{1}} economic times. A recent study in the US has shown that while families may not have as much to spend, they are being more {{2}} in the gifts they bestow. Lavish celebrations and large lump {{3}} seem to have gone by the wayside in favour of smaller, more thoughtful gifts.', NULL, NULL, NULL, E'1.hard, 2.creative, 3.sums', NULL, NULL),
  ('645b911f-2585-5020-8c4a-39fb26e4fe98'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '645b911f-2585-5020-8c4a-39fb26e4fe98'::uuid, 1, NULL, TRUE, 0, NULL, E'Mass Strandings', E'Mass strandings of whales are a recurring issue in Australia and New Zealand. In recent years, multiple events have highlighted the severity of this problem. For instance, in April 2024, around 160 pilot whales stranded on a Western Australian beach, prompting a significant rescue operation by marine biologists and wildlife officers.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('645bf73f-c923-549b-90ae-2442cef667fc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '645bf73f-c923-549b-90ae-2442cef667fc'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Would you go to a pharmacist or a surgeon with a prescription after visiting a doctor?', '48e146ec-df1e-515f-be01-bf762ec2fbee'::uuid, NULL, NULL, E'Pharmacist', NULL, NULL),
