  ('654395bd-5be0-51f0-add8-d2a5f5226151'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '654395bd-5be0-51f0-add8-d2a5f5226151'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2c0d49a1-94f2-5627-b1c5-7d9f7c0a9620'::uuid, NULL, E'During certain sleep stages, rapid eye movement occurs behind closed eyelids.', NULL, NULL, NULL),
  ('65478842-b94e-5aef-a9aa-20f6c408f32b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '65478842-b94e-5aef-a9aa-20f6c408f32b'::uuid, 1, NULL, TRUE, 0, NULL, E'James Webb Telescope', E'The James Webb Space Telescope, Named after the NASA administrator, who oversaw the Apollo moon landings, this space behemoth is the largest, most powerful and most complex space telescope ever built. It has been hailed as the successor of Hubble, which itself was instrumental in expanding our understanding of the universe over the last few decades. It has undergone major redesigns, cost $9.7billion to build, and has taken 25 years to fully develop, construct and test. There were moments in its decades-long construction where it was very nearly cancelled completely. And yet with the aid of scientists from several nations around the world, it has overcome hurdle after hurdle.\n\nWhich one of the statements about James Webb telescope is right?', '5be82113-8d36-5ee2-8efb-138f5c91e1b7'::uuid, NULL, NULL, E'It took nearly 30 years to complete the telescope, during which it was nearly cancelled.', NULL, NULL),
  ('65483bcd-1062-5c8a-bc1f-f103358b0ce9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '65483bcd-1062-5c8a-bc1f-f103358b0ce9'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do we describe a person who is not guilty of a crime?', 'b6475dfa-7832-52db-af50-640d2001f00c'::uuid, NULL, NULL, E'Innocent', NULL, NULL),
  ('654a1bcd-f34e-5bc5-aecc-dd136a560bc4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '654a1bcd-f34e-5bc5-aecc-dd136a560bc4'::uuid, 1, NULL, TRUE, 0, NULL, E'Thermometer', E'Researchers have discovered a brain molecule that functions as a ''thermometer'' for the presence of others in an animal''s environment. Zebrafish ''feel'' the presence of others via mechanosensation and water movements —which turns the brain hormone on.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('654b8753-f3bb-5029-a5d8-03d34e7d1cb1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '654b8753-f3bb-5029-a5d8-03d34e7d1cb1'::uuid, 1, NULL, TRUE, 0, NULL, E'Tutors', E'Tutors play a crucial role in education by providing personalized instruction tailored to the needs of each student. They can help students with homework, test preparation, and clarifying difficult concepts. Tutors often employ various teaching strategies and techniques to engage students and enhance their learning experience.', NULL, NULL, NULL, NULL, NULL, NULL),
