  ('65a9e5f9-081a-5cb2-b56c-e0f375233a6b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '65a9e5f9-081a-5cb2-b56c-e0f375233a6b'::uuid, 1, NULL, TRUE, 0, NULL, E'Tesla', E'Tesla''s theoretical work formed the basis of modern alternating current electric power systems. Thomas Edison promised him almost one million dollars in today''s money to undertake motor and generator improvement. However, when Tesla asked about the money, Edison reportedly replied "Tesla, you don''t understand our American humor." The pair became arch-rivals.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('65aa1141-a7b5-5367-a0b4-315cb9c2e1b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '65aa1141-a7b5-5367-a0b4-315cb9c2e1b9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '03ed519f-8728-5e3e-adbb-025e68cd9fb9'::uuid, NULL, E'Please don''t forget to check your email for the updates of the week.', NULL, NULL, NULL),
  ('65ab995e-eeb5-5648-b801-58799fc065d0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '65ab995e-eeb5-5648-b801-58799fc065d0'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4464b288-f959-5a8d-b361-cf45001eba1b'::uuid, NULL, NULL, E'It was hard to anticipate how all the different characters would react.', NULL, NULL),
  ('65acf0aa-5bfa-5f56-a77c-f1bbd4dc7ccd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '65acf0aa-5bfa-5f56-a77c-f1bbd4dc7ccd'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1aadc61a-ef87-5c10-b738-891fff58219d'::uuid, NULL, NULL, E'The application process may take longer than expected.', NULL, NULL),
  ('65b044a6-44f2-50bf-b867-11dfb97315bc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '65b044a6-44f2-50bf-b867-11dfb97315bc'::uuid, 1, NULL, TRUE, 0, NULL, E'Fewer Work Hours', E'"In the future, people will work fewer hours at their jobs than they do now." How far do you agree with the statement? Please support your opinion with your own experience.', NULL, NULL, E'Nowadays, whether people will spend less time on working has fueled heated discussions. Proponents claim that people will put in fewer hours at work with the help of robot assistance, whereas opponents contend that productivity-driven workflows make people log fewer hours at their jobs. From my perspective, I am convinced that in the future, people will work fewer hours than they do now.\nTo begin with, advancements in technology and shifting social values enable people to accomplish more tasks in fewer hours. For example, artificial intelligence will handle repetitive tasks, allowing employees to focus on personal time for leisure. In addition to this, remote work tools and flexible schedules will become standard, boosting work efficiency. Other than that, society will value quality of life more than overworking, as communities emphasize efficient output rather than extended working hours. It is thus shown that individuals will put in fewer hours at work than they do now.\nBesides, I also believe that with the advent of remote collaboration tools and autonomous work models, future work trends will shorten work hours. On top of that, more people will choose flexible project work with independently set timetables that align with personal commitments. Moreover, globalized work models will make companies focus on output rather than attendance, enabling employees to choose their most productive hours. Recently, I have examined an article arguing that the knowledge economy will value mental labor over mechanical work, with hourly-paid creative jobs replacing traditional time-clock systems. This clearly proves that people will need less time for their jobs in the future.\nTo conclude, there is no doubt that smart working and task-oriented schedules are essential in today''s world. While some might disagree, the evidence strongly supports that in the future, people will spend fewer hours working than they do now.', NULL, 200, 300),
  ('65b7a8aa-da35-5bde-8407-dd5bad9c58c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '65b7a8aa-da35-5bde-8407-dd5bad9c58c4'::uuid, 1, NULL, TRUE, 0, NULL, E'Forests', E'Forests cover 31 percent of the world’s land surface, and are home to the {{1}} of the world’s terrestrial biodiversity. Forests are a source of fiber, fuel and food, and they provide {{2}} for millions of people. Some 2.4 billion people use wood-based energy for cooking. Forests help {{3}} climate change and improve soil, air and water quality.', NULL, NULL, NULL, E'1.majority, 2.livelihoods, 3.mitigate', NULL, NULL),
