  ('65cc419b-cb57-5f2e-9fe9-38d5df699b29'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '65cc419b-cb57-5f2e-9fe9-38d5df699b29'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for a group of similar organisms that can reproduce to produce fertile offspring?', '02c8e77f-8df6-5276-b175-1b8c5345866e'::uuid, NULL, NULL, E'Species', NULL, NULL),
  ('65d25fcd-cee2-560d-9d81-3a883ac1710d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '65d25fcd-cee2-560d-9d81-3a883ac1710d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'bbffd634-6e21-5e20-94c5-73d1025b56d1'::uuid, NULL, NULL, E'Nutrition plays a key role in athletic performance.', NULL, NULL),
  ('65d9adf9-1eca-5541-83b1-1ab7cf7f6bd4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '65d9adf9-1eca-5541-83b1-1ab7cf7f6bd4'::uuid, 1, NULL, TRUE, 0, NULL, E'Grand Canyon', E'The Grand Canyon is 277 miles long, up to 18 miles wide and attains a depth of over a mile. While the specific geologic processes and timing that formed the Grand Canyon are the subject of debate by geologists, recent evidence suggests the Colorado River established its course through the canyon at least 17 million years ago.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('65de1184-1284-5a06-ae9c-8f2455e5f3b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '65de1184-1284-5a06-ae9c-8f2455e5f3b9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8e207b70-d417-5fa1-a87f-43247ddfb54f'::uuid, NULL, NULL, E'Females are better than males in academic results until 44 years of age.', NULL, NULL),
  ('65e5718f-4d86-5e18-8bda-c370c32a95b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '65e5718f-4d86-5e18-8bda-c370c32a95b2'::uuid, 1, NULL, TRUE, 0, NULL, E'Coral Reefs', NULL, '271a6159-1029-5889-bccb-211e273f8ab2'::uuid, NULL, E'Coral reefs are some of the most spectacular ecosystems on the planet. They’re also some of the most vulnerable. But how can we protect the reefs and the animals and plants who rely on them? And how can we make sure our protected areas aren’t hurting those people who use reefs to survive? These are some of the big questions facing marine conservation biologists today. Let’s take Fiji, for example. Fiji is series of islands in the South Pacific Ocean. To help balance the need for conservation and making a living, scientists had suggested that instead of one big park which provides a lot of coverage for one reef system while leaving the rest unprotected, a better way is to create a system of protected areas nested together like pearls on a string. This idea is called connectivity. In this way, scientists can protect lots of different habitats while not excluding people from their traditional fishing grounds. Now, the only way this string-of-pearls kind of reserve network is going to work is if each park is connected to other parks.', NULL, NULL, NULL),
  ('65edfd10-4ab6-5171-9b0f-410224f522cf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '65edfd10-4ab6-5171-9b0f-410224f522cf'::uuid, 1, NULL, TRUE, 0, NULL, E'Platypus', E'The platypus looks like no other creature on Earth. Physically, it appears to be a hybrid blend of a bird, beaver, reptile and otter, with additional characteristics not contained in any of these four. On cursory examination, the platypus has a bill that most {{1}} that of a waterfowl, not the mouth of any known mammal. Yet it is not an ordinary bill. It is actually a well-designed sensory organ. Not a nose, but a highly sensitive electro-location sensor, detecting minuscule electrical impulses generated by its food source of small crustaceans and worms. No other mammal has a sensor so highly {{2}} — in fact; only one other mammal has this ability at all. Then {{3}} are the webbed feet, similar to those found on otters. Unlike an otter, however, the webbing is far more pronounced on the front feet of the platypus, which it uses like paddles for swimming. {{4}} in the water, the back feet are tucked into its body and hardly used at all.', NULL, NULL, NULL, E'1.resembles, 2.developed, 3.there, 4.While', NULL, NULL),
  ('65f4f023-0149-55d6-9b67-0f0a70a0c6d6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '65f4f023-0149-55d6-9b67-0f0a70a0c6d6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '1a8bfd88-6f05-5da4-a24b-0c99ce86f376'::uuid, NULL, E'In no sense can the issue be said to be resolved.', NULL, NULL, NULL),
  ('65f5bb18-88b2-5e8a-9813-bfd05992f111'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '65f5bb18-88b2-5e8a-9813-bfd05992f111'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '95f0eba0-f32a-5c0e-b1a9-d837e4d6db16'::uuid, NULL, NULL, E'Schools really care about stopping students from copying work.', NULL, NULL),
  ('65f8fd7f-85ff-5d37-b0ae-b2b922c72f89'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '65f8fd7f-85ff-5d37-b0ae-b2b922c72f89'::uuid, 1, NULL, TRUE, 0, NULL, E'Lauder', E'Leonard Lauder, chief executive of the company his mother founded, says she always thought she "was growing a nice little business." And that it is. A little business that {{1}} 45% of the cosmetics market in U.S. department stores. A little business that sells in 118 countries and last year grew to be $3.6 billion big in sales. The Lauder family''s shares are worth more than $6 billion. But early on, there wasn''t a burgeoning business, there weren''t houses in New York, Palm Beach, Fla., or the south of France. It is said that at one point there was one person to answer the telephones who {{2}} her voice to become the shipping or billing department as needed. You more or less know the Estée Lauder story because it''s a chapter from the book of American business folklore. In short, Josephine Esther Mentzer, daughter of immigrants, lived above her father''s hardware store in Corona, a section of Queens in New York City. She started her {{3}} by selling skin creams concocted by her uncle, a chemist, in beauty shops, beach clubs and resorts. No doubt the portions were good — Estée Lauder was a quality fanatic — but the saleslady was better. Much better. And she simply outworked everyone else in the cosmetics industry. She {{4}} the bosses of New York City department stores until she got some counter space at Saks Fifth Avenue in 1948. And once in that space, she utilized a personal selling approach that proved as {{5}} as the promise of her skin {{6}} and perfumes.', NULL, NULL, NULL, E'1.controls, 2.changed, 3.enterprise, 4.stalked, 5.potent, 6.regimens', NULL, NULL),
  ('65ff7340-d8f8-5e46-b3c3-03aff58abf9f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '65ff7340-d8f8-5e46-b3c3-03aff58abf9f'::uuid, 1, NULL, TRUE, 0, NULL, E'Environment of Growth', E'It is better for children to grow up in big cities than in the countryside. To what extent do you agree with this statement?', NULL, NULL, NULL, NULL, 200, 300),
  ('66026e2d-ff3a-566e-8dbf-16f9fcca8594'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '66026e2d-ff3a-566e-8dbf-16f9fcca8594'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '465f844d-d8f8-5724-80ca-72ddcc1dd371'::uuid, NULL, E'All the assignments should be submitted by the end of this week.', NULL, NULL, NULL),
