  ('66072552-4d50-5866-a1b8-4aba9ca2ce7d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '66072552-4d50-5866-a1b8-4aba9ca2ce7d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '1e48aaa3-75d0-52dd-922d-7690431d662a'::uuid, NULL, E'We will see if we can get through this without too many interruptions.', NULL, NULL, NULL),
  ('66079805-0af8-59cb-b00a-84bc064022ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '66079805-0af8-59cb-b00a-84bc064022ca'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'de4b010c-5154-5a1e-a725-14582d217ed7'::uuid, NULL, NULL, E'They will test your knowledge with difficult questions in class.', NULL, NULL),
  ('660b657c-d0f7-5927-ab57-f150020e8365'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '660b657c-d0f7-5927-ab57-f150020e8365'::uuid, 1, NULL, TRUE, 0, NULL, E'Animals in Science', E'Many scholars attribute the 17th-century belief that animals were mere machines devoid of fear, pain or pleasure to the French mathematician, philosopher and scientist. Animals’ feelings, even if present, were morally irrelevant to Descartes, who attempted to prove his point by subjecting dogs and rabbits to exquisite torture.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('6615e49f-4704-5cee-a759-24487e01018f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6615e49f-4704-5cee-a759-24487e01018f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a small solar system body made mostly of rock and metal?', '9e9db0f0-9ea3-5cda-888b-9a9684695423'::uuid, NULL, NULL, E'Asteroid', NULL, NULL),
  ('661f37f1-ff0f-5de9-8a1d-72be4cd82b19'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '661f37f1-ff0f-5de9-8a1d-72be4cd82b19'::uuid, 1, NULL, TRUE, 0, NULL, E'Health of Ocean', NULL, '7ce03cd6-99d0-50da-bc00-bd199bf85857'::uuid, NULL, E'Interviewer: In an article that you wrote that I just read, you said you wished you could take everyone back to decades ago to look at the Florida Keys.\nInterviewee: Fifty years ago. Think about how much change has taken place in that short period of time. We have managed to consume on the order of 90% of the big fish in the ocean: the tunas, the swordfish, the sharks. They''re mostly gone. Until recently people have had the belief that there isn''t much we puny human beings can do to change the nature of the ocean. But in fact, we have, not just because of what we''ve been taking out, and the destructive means often applied to take fish and other creatures from the sea, but also what we''re putting into the sea, either directly or what we put into the atmosphere that falls back into the sea.\nInterviewer: So if you were going to give a grade on the health of the oceans today, what would it be? Interviewee: Well, it depends on which aspect. Across the board. Huh. The oceans are in trouble. It''s hard for me to assign a specific grade. Maybe C-?', NULL, NULL, NULL),
  ('66216e12-faf6-5334-ac70-03a60a76fa72'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '66216e12-faf6-5334-ac70-03a60a76fa72'::uuid, 1, NULL, TRUE, 0, NULL, E'Breast-feeding', E'While many mothers-to-be are advised about the {{1}} of breastfeeding, what they may not be told is that the effects go well beyond physical health. A new study finds babies breastfed for long periods have better performance on intelligence tests, greater school achievement, and higher monthly incomes as 30-year-olds.\nWhile past research has found higher intelligence {{2}} among breastfed babies, what is so significant about this study is that the researchers were able to collect more complete information on breastfeeding duration and also followed for a longer period. And, by using a population-based birth {{3}} , the breast feeding practices had no association {{4}} income level. Most of the evidence of higher intelligence test scores among breastfed babies comes from high-income countries, where middle-class and higher-class mothers are more likely to breastfeed their babies than lower income mothers- certainly in the United States, breastfeeding rates {{5}} this trend.\nWith evidence coming from first-world countries ''Where breastfeeding is positively associated with higher socioeconomic status''. Horta explained, ''There is always a question of whether the effect that has been observed in other studies is a consequence of breastfeeding by itself or has the result been {{6}} by socioeconomic status.'' Specifically, higher income babies are most likely eating better quality food and this could be impacting IQ test scores.', NULL, NULL, NULL, E'1.benefits, 2.scores, 3.cohort, 4.with, 5.reflect, 6.confounded', NULL, NULL),
  ('6625d315-a6c4-5188-8cb9-9757ebc97f68'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6625d315-a6c4-5188-8cb9-9757ebc97f68'::uuid, 1, NULL, TRUE, 0, NULL, E'Artificial Intelligence', E'Researchers have designed an artificial intelligence model that is better able to predict how much students are learning in educational games. The improved model makes use of an AI training concept called multi-task learning, and could be used to improve both instruction and learning outcomes.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('662880a5-c6e3-5962-a217-f0b2d6d0a6c9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '662880a5-c6e3-5962-a217-f0b2d6d0a6c9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '932e017d-e709-5952-b4d3-7e6d25ff5f54'::uuid, NULL, E'More and more people regard films as entertainment instead of art.', NULL, NULL, NULL),
  ('662bb15a-4b0d-5313-8c38-4c08e45be5f3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '662bb15a-4b0d-5313-8c38-4c08e45be5f3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '151ac1c1-e3d8-55c3-9ec2-c8e39a93954b'::uuid, NULL, E'A computer virus has destroyed all my files.', NULL, NULL, NULL),
  ('662c38fe-fa44-5fe7-8da6-678c214fa0fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '662c38fe-fa44-5fe7-8da6-678c214fa0fd'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the yellow stuff that can be found on beaches or deserts?', 'f16fde57-d96b-5ce1-8b65-a78226e4648c'::uuid, NULL, NULL, E'Sand', NULL, NULL),
  ('6632958a-0e9b-5c82-9339-fd84e86be056'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6632958a-0e9b-5c82-9339-fd84e86be056'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the state of believing in oneself?', '3ad5fa40-ec9f-5845-9484-70fea536f8a2'::uuid, NULL, NULL, E'Confidence / confident / self-confidence / self-confident', NULL, NULL),
  ('6635c402-6d9d-5723-8784-b237e8bf0b8a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6635c402-6d9d-5723-8784-b237e8bf0b8a'::uuid, 1, NULL, TRUE, 0, NULL, E'Addressing Shared Kitchen Hygiene', E'You''re the manager of a shared kitchen in your office, and you''ve noticed that some employees are leaving dirty dishes in the sink and not cleaning up spills on the counters. This is causing unpleasant odors and attracting pests. You need to remind them of the importance of cleaning up for everyone''s convenience and health. What would you say?', '3e374526-7806-57ad-a948-34bd9064b7ec'::uuid, NULL, E'I''ve noticed some issues in the kitchen lately that we need to address. It''s important for all of us to keep the shared space clean and tidy. Leaving dirty dishes in the sink and spills on the counters not only creates unpleasant odors but also attracts pests, which can be a health concern for everyone. Let''s all pitch in and make sure we clean up after ourselves to maintain a clean and hygienic kitchen environment. Thanks for your cooperation!', NULL, NULL, NULL),
  ('664262b3-5036-5f3f-87f3-caf0a1d33941'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '664262b3-5036-5f3f-87f3-caf0a1d33941'::uuid, 1, NULL, TRUE, 0, NULL, E'Invented Things', E'What are the advantages and disadvantages of living in an era in which new things are constantly being invented?', NULL, NULL, NULL, NULL, 200, 300),
  ('664dbb1a-6918-5c40-a088-026d0b5c2220'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '664dbb1a-6918-5c40-a088-026d0b5c2220'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'acd8439d-5637-5300-ac09-d85c869857bd'::uuid, NULL, NULL, E'The doctors are discussing how to cure this patient.', NULL, NULL),
  ('664ffb21-9197-5abd-a2a5-945ce87edb3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '664ffb21-9197-5abd-a2a5-945ce87edb3c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Who invented the light bulb?', '0c914bfc-8fd8-524e-aed5-493686666917'::uuid, NULL, NULL, E'Edison', NULL, NULL),
  ('6651ba2a-8cb4-52ed-9d59-e7224bb9c78c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6651ba2a-8cb4-52ed-9d59-e7224bb9c78c'::uuid, 1, NULL, TRUE, 0, NULL, E'A Delayed Project', E'You''ve organized a group project with your classmates, and everyone agreed on their roles and deadlines. However, one member consistently fails to deliver their part on time, causing delays for the entire group. What would you say to your classmate?', 'cacf4e75-5b56-5e79-91b4-dddd990d6a25'::uuid, NULL, E'I wanted to talk about our group project. I''ve noticed that we''re facing delays because some parts aren''t coming in on time. I totally get that plans can go wrong sometimes, but meeting deadlines is crucial for the success of our project. Is there anything I can do to help or any challenges you''re facing? Let''s figure out a plan together to make sure we will get our project back on track.', NULL, NULL, NULL),
  ('6653c9ff-bc32-5b49-90ab-a7fcb73ce95f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6653c9ff-bc32-5b49-90ab-a7fcb73ce95f'::uuid, 1, NULL, TRUE, 0, NULL, E'Faster Communications', E'As we progress into the 21st century, communications are becoming faster and faster. Think of the millions of different media images you are bombarded with every day. It is as important now to be able to read and make sense of those images, as it has been to be able to read ordinary text.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('6654e53a-d3ca-5b44-b07c-ce265608ec8b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6654e53a-d3ca-5b44-b07c-ce265608ec8b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the animal that gives birth to babies, not eggs, and feed the babies on milk?', 'a90ee6a5-3482-5ada-9ff6-e71c9e2bf6e8'::uuid, NULL, NULL, E'Mammal', NULL, NULL),
  ('66555c55-52c5-5e67-a5ef-8943a5783b5f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '66555c55-52c5-5e67-a5ef-8943a5783b5f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3c31106c-005e-54c1-a201-e07f7fadf845'::uuid, NULL, E'The article details the who, where, and when of the war.', NULL, NULL, NULL),
  ('6657f463-3c0a-5923-8012-d3dc614d518c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '6657f463-3c0a-5923-8012-d3dc614d518c'::uuid, 1, NULL, TRUE, 0, NULL, E'Parental Income', E'In England it is well known that access to university, on average, varies substantially by the levels of parental income and that students from poorer families access different types of universities than those from wealthier backgrounds. However, the question of whether graduates’ earnings vary {{1}} their socioeconomic backgrounds amongst graduates attending similar universities and taking the same subject has remained poorly understood, {{2}} limited by data availability. Our unique administrative database offers substantial advantages {{3}} this crucial question. The findings are also relevant for myriad other issues that benefit from better information on {{4}} in graduates’ earnings, including: students’ choices of subjects and institutions; better information for schools {{5}} advise and guide students whilst at school; and the operation and cost of the higher education finance system.', NULL, NULL, NULL, E'1.according to, 2.thus far, 3.in addressing, 4.variation, 5.to help', NULL, NULL),
  ('665ab040-8dcc-5f0f-84b2-7e1638d95206'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '665ab040-8dcc-5f0f-84b2-7e1638d95206'::uuid, 1, NULL, TRUE, 0, NULL, E'Electronic Devices', NULL, NULL, NULL, NULL, E'3, 1, 4, 2', NULL, NULL),
