  ('665d52aa-a6a8-5812-be5e-2a9cd4eb6b97'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '665d52aa-a6a8-5812-be5e-2a9cd4eb6b97'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for a large painting or decoration, created either directly on a wall or ceiling or on a canvas attached to the wall?', '58a6c816-2919-596d-aa0e-f26cdb575d81'::uuid, NULL, NULL, E'Mural', NULL, NULL),
  ('666302c0-3946-591e-bf95-1fd8bd0980b5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '666302c0-3946-591e-bf95-1fd8bd0980b5'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0cac2118-0ea5-54e2-b5b9-14f60d6d43d1'::uuid, NULL, E'My own happy childhood sometimes makes me forget others'' varied experiences.', NULL, NULL, NULL),
  ('66664302-1889-5bcb-bceb-8d7e4ccf039a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '66664302-1889-5bcb-bceb-8d7e4ccf039a'::uuid, 1, NULL, TRUE, 0, NULL, E'Wildlife Conservation', E'Protecting biodiversity and preserving ecosystems are vital for maintaining ecological balance. Efforts to conserve endangered species, combat wildlife trafficking, and establish protected areas are ongoing. Education and awareness play a crucial role in promoting sustainable practices and fostering a sense of responsibility towards the natural world.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('6676a563-ee52-588e-8695-64953a52316b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6676a563-ee52-588e-8695-64953a52316b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What''s the verb used to describe two people sharing the same opinion?', 'e9587441-7678-5eb9-9e44-160f73c3ab5a'::uuid, NULL, NULL, E'Agree / consent', NULL, NULL),
  ('6677590c-00d2-598f-b091-9d2ec09bd534'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6677590c-00d2-598f-b091-9d2ec09bd534'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9a49d6c8-ee88-561b-9238-c60ebe92dcd2'::uuid, NULL, E'Higher education means higher pay and more opportunities you will get.', NULL, NULL, NULL),
  ('6682123c-e2eb-5594-95fe-6282c852c32f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6682123c-e2eb-5594-95fe-6282c852c32f'::uuid, 1, NULL, TRUE, 0, NULL, E'Sleep Deprivation', NULL, 'd8a55fc8-01f0-5963-85cb-f805fcb22081'::uuid, NULL, E'Scientists use a technique known as psychomotor vigilance tasks or PVTs to understand the impact of sleep deprivation on human in studies. Simply put, it’s a reaction test: a red button randomly turns green and people have to push it as fast as possible. Not so surprisingly, those who get 8 hours of sleep over a 2-week period show very few lapses in attention and no cognitive declines. But those groups that receive either 6 or 4 hours of sleep see declining PVT results on almost a daily basis for the entire 2-week period. Of course the 4-hour group performs the worst. But these results don’t just show a loss of concentration, they show full lapses and awareness called “microsleeps”. In other words, their brains aren’t just slower but shutting off for moments at a time. When looking at the results deeper, scientists concluded that getting 6 hours of sleep for 10 days in a row was the same as not sleeping for 24 hours straight. That’s the same cognitive decline as being legally drunk. And if you get 4 hours of sleep for 11 days, it’s like you haven’t slept for 48 hours straight.', NULL, NULL, NULL),
  ('6687d0a5-43af-585d-bf1d-b331ecc33360'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '6687d0a5-43af-585d-bf1d-b331ecc33360'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3ff5d73c-cdd8-5b86-b794-739931b8256f'::uuid, NULL, NULL, E'Current societal issues are the focus of our intense research.', NULL, NULL),
  ('668ad866-cfc7-57be-90a5-7f8214febda3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '668ad866-cfc7-57be-90a5-7f8214febda3'::uuid, 1, NULL, TRUE, 0, NULL, E'Smart Glasses', E'The headset, {{1}} by Epson in partnership with the Royal National Theatre, is heavier than normal reading glasses but much lighter than bulky virtual reality headsets like the Oculus Rift. The lenses look like a typical pair of glasses, but they fit inside a large gray casing that sits on the sides of your head. When you look through the glasses, closed captions {{2}} across the bottom of the augmented reality lenses. A handheld keypad is attached to the glasses via cable to allow each user to {{3}} the color, size and position of the closed captions. Here’s how it works: The script from an opening-night production is fed into speech software, which follows the performance and adjusts the captions accordingly. This process is {{4}} using sound, video and lighting cues. Some hard of hearing users wear it so they can read lips at the same time as reading the captions. The technology has been successfully used in US movie theaters, but the Royal National Theatre’s challenges are greater because their performances are live.', NULL, NULL, NULL, E'1.manufactured, 2.scroll, 3.customize, 4.refined', NULL, NULL),
  ('668d4d66-8f8b-5448-a82b-33a04e74be6a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '668d4d66-8f8b-5448-a82b-33a04e74be6a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the smaller part of a group?', '1ffc26c6-8ba7-5df2-9ea8-b1943e227fe9'::uuid, NULL, NULL, E'Minority', NULL, NULL),
