  ('66de79a3-fab5-5433-b7fa-407b55551d33'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '66de79a3-fab5-5433-b7fa-407b55551d33'::uuid, 1, NULL, TRUE, 0, NULL, E'Pets', E'As countries develop, more and more people regard pets as family members. What’s your opinion? Support it with examples.', NULL, NULL, NULL, NULL, 200, 300),
  ('66e909f4-9ed9-5831-864e-244fc5b3ddcb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '66e909f4-9ed9-5831-864e-244fc5b3ddcb'::uuid, 1, NULL, TRUE, 0, NULL, E'Favorable Traits', E'New favorable traits evolve when genetic mutations arise that offer a survival edge. As the survivors of each generation pass on those beneficial mutations, the mutations and {{1}} adaptive traits become more common in the general population.\nThough it may take millions of years for complex traits {{2}} , say allowing humans to walk on two legs, evolution itself happens with each generation as adaptive mutations become more frequent in the population.\nThe genomic revolution has allowed biologists to see the natural selection process {{3}} by making the genetic blueprint of hundreds of thousands of people available for comparison. By tracking the relative rise and fall of specific mutations {{4}} generations of people, researchers can infer which traits are spreading or dwindling.', NULL, NULL, NULL, E'1.their, 2.to evolve, 3.in action, 4.across', NULL, NULL),
  ('66f136fb-45bf-5b94-b758-c77e6a50249d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '66f136fb-45bf-5b94-b758-c77e6a50249d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3c716f9d-45f8-59a9-a7d7-bbdf3ce6a991'::uuid, NULL, NULL, E'The rationale of my research is to present the value of the urban ecosystem.', NULL, NULL),
  ('66fadfdb-bffd-5d48-ada5-a3e223a95778'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '66fadfdb-bffd-5d48-ada5-a3e223a95778'::uuid, 1, NULL, TRUE, 0, NULL, E'Choosing a Place', E'You''re planning a birthday celebration for a friend, and the group is discussing potential venues. One suggestion is to go to a loud and crowded nightclub, but you know that some friends prefer quieter and more intimate settings. What would you say to the group?', 'dd0261bd-bb90-5978-9a26-c46f59f7ea88'::uuid, NULL, E'Hi! I would like to discuss an issue we have encountered with choosing the right venue for our friend''s birthday celebration.\nThe background is that while some of us enjoy loud and crowded nightclubs, others prefer quieter and more intimate settings.\nIn the situation, what I can think of is to pick a compromise location.\nBesides, another thing that comes to my mind is to take a quick vote.', NULL, NULL, NULL),
