  ('67225d8b-6cbd-5789-9b86-d33171b406f7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '67225d8b-6cbd-5789-9b86-d33171b406f7'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '16015a60-e33d-594a-89fb-66c7c9355f56'::uuid, NULL, E'You are not sure that you can skip the sessions for Wednesday.', NULL, NULL, NULL),
