  ('67a69010-d508-55f3-be94-f89600f3b495'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '67a69010-d508-55f3-be94-f89600f3b495'::uuid, 1, NULL, TRUE, 0, NULL, E'Coral Reefs', NULL, NULL, NULL, NULL, E'3, 1, 2, 4', NULL, NULL),
  ('67a6f855-1fe2-514c-962d-a4d72f20ab9f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '67a6f855-1fe2-514c-962d-a4d72f20ab9f'::uuid, 1, NULL, TRUE, 0, NULL, E'Bioplastics', E'Do you agree that the use of bioplastics is a crucial step towards reducing plastic pollution?', NULL, NULL, E'I firmly believe that the use of bioplastics represents a crucial step towards reducing plastic pollution. In the face of escalating environmental challenges posed by traditional plastics, bioplastics offer a sustainable alternative that aligns with the principles of conservation and eco-friendliness. With their inherent biodegradability, reliance on renewable resources, and lower carbon footprint, bioplastics stand as a beacon of hope in combating plastic pollution and fostering a greener future.\nOne of the key advantages of bioplastics is their enhanced biodegradability compared to traditional plastics. Bioplastics are engineered to break down more easily through natural processes, reducing their environmental impact and preventing long-lasting pollution in ecosystems. This characteristic ensures that bioplastics do not persist in the environment for extended periods, unlike conventional plastics that contribute significantly to plastic waste accumulation.\nFurthermore, bioplastics are predominantly derived from renewable resources such as corn starch or sugarcane. By utilizing these sustainable sources, the production of bioplastics reduces reliance on finite fossil fuels, thereby decreasing the environmental strain associated with extracting and processing traditional plastics. Moreover, the manufacturing process of bioplastics generally results in lower greenhouse gas emissions, contributing to climate change mitigation efforts and promoting a more sustainable industrial sector.\nIn conclusion, the adoption of bioplastics as an alternative to traditional plastics is undeniably a crucial step in the fight against plastic pollution. With their biodegradability, reliance on renewable resources, and reduced carbon footprint, bioplastics offer a sustainable solution that addresses the pressing environmental challenges posed by plastic waste. Embracing bioplastics not only mitigates plastic pollution but also paves the way for a more environmentally conscious and sustainable future for generations to come.', NULL, 200, 300),
  ('67ab4b05-9614-58e8-8c92-baf405e679c2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '67ab4b05-9614-58e8-8c92-baf405e679c2'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we use to rest our heads on in bed?', 'c61ccbf8-8ce2-51d3-81ed-6d163a08a2d3'::uuid, NULL, NULL, E'Pillow', NULL, NULL),
