  ('67b5ac05-cf7d-5d85-9ee7-64b3bd29e395'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '67b5ac05-cf7d-5d85-9ee7-64b3bd29e395'::uuid, 1, NULL, TRUE, 0, NULL, E'Bonus of Dendrochronology', E'A bonus of dendrochronology is that the width and substructure of each ring {{1}} the amount of rain and the {{2}} at which the rain fell during that particular year. Thus, tree ring studies also allow one to reconstruct {{3}} climate; e.g., a series of wide rings means a wet period, and a {{4}} of narrow rings means a {{5}} .', NULL, NULL, NULL, E'1.reflect, 2.season, 3.past, 4.series, 5.drought', NULL, NULL),
  ('67baaa82-a8f6-5892-865d-9110dc425864'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '67baaa82-a8f6-5892-865d-9110dc425864'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ccf66b2a-b3d1-5f9c-a2bf-20b392b54ebd'::uuid, NULL, E'Is the professor available at the office on a regular schedule?', NULL, NULL, NULL),
