  ('67fcbe0d-2ac1-5e19-9e1d-63c853deeef6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '67fcbe0d-2ac1-5e19-9e1d-63c853deeef6'::uuid, 1, NULL, TRUE, 0, NULL, E'Root Network', E'The networks of roots that plants use to absorb water and nutrients can encompass a space larger than the part of the plant visible above ground. The nature of these roots systems can help plants adapt to challenging environments such as deserts.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('67fcc8bb-2210-50c1-9c28-df7bdde94c70'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '67fcc8bb-2210-50c1-9c28-df7bdde94c70'::uuid, 1, NULL, TRUE, 0, NULL, E'Technological Innovation', NULL, NULL, NULL, NULL, E'1, 2, 4, 3', NULL, NULL),
  ('680282cc-2e2f-58d7-bd5e-9ca96f32bec8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '680282cc-2e2f-58d7-bd5e-9ca96f32bec8'::uuid, 1, NULL, TRUE, 0, NULL, E'Proper Gear', E'You''ve organized a weekend hiking trip with your friends, and everyone''s excited to hit the trails. However, upon arrival, you notice some of them are not wearing proper hiking shoes, which could lead to discomfort and injuries during the hike. You need to remind everyone to wear appropriate footwear. What would you say to your friends?', 'b3310711-aee7-5af9-a4cd-34deb08a4b05'::uuid, NULL, E'Hey everyone, before we start our hiking adventure, let''s make sure we''re all wearing suitable footwear. Proper hiking shoes will provide the support and protection we need for the trails ahead, reducing the risk of discomfort and injuries. If anyone doesn''t have the right shoes, let''s see if we can borrow or rent some nearby. It''s essential for everyone''s safety and enjoyment. So be sure to put on the proper gear.', NULL, NULL, NULL),
  ('6806d8e7-51fe-5525-88ca-c39c3893281e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '6806d8e7-51fe-5525-88ca-c39c3893281e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '36b5c250-2f78-50d5-ac73-7d364f3ac318'::uuid, NULL, NULL, E'The bar chart provides a useful means of data comparison.', NULL, NULL),
  ('680712a3-734c-502c-8bf4-72843ac43298'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '680712a3-734c-502c-8bf4-72843ac43298'::uuid, 1, NULL, TRUE, 0, NULL, E'Natural-born Runners', E'You''ve probably had the feeling. Your running shoes are pounding the pavement — then suddenly your pain fades away, and you''re feeling euphoric. The runner''s high. But that biological perk may be limited to mammals that evolved for endurance {{1}} — like us. So says a study in the Journal of Experimental Biology.\nResearchers had humans and dogs — both natural-born runners — jog a half hour on a treadmill. Then they sampled their blood for endocannabinoids, some of the {{2}} thought to trigger the runner''s high. As expected, humans and dogs had much higher levels after the run. But when ferrets — a {{3}} species — took the same 30-minute trot, they had no spike in those {{4}} molecules.\nThe authors say that''s because long-distance running could have helped our hunter-gatherer ancestors find more food — thus increasing their reproductive success. And they speculate that natural selection may have linked up a feel-good reward to that beneficial {{5}} . These days of course, this ancient trait won''t help us find extra calories — but it may encourage us to run ''em off.', NULL, NULL, NULL, E'1.exercise, 2.compounds, 3.sedentary, 4.feel-good, 5.behavior', NULL, NULL),
  ('680ac3a3-944a-5b4e-8d59-15e26c5074e0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '680ac3a3-944a-5b4e-8d59-15e26c5074e0'::uuid, 1, NULL, TRUE, 0, NULL, E'Butterflies', E'Butterflies, unlike moths, are not usually attracted to artificial light. Why is there a difference in behavior between two closely related {{1}} ? The answer may lie in their evolutionary paths and ecological niches. Butterflies, being diurnal creatures, have evolved to navigate using the sun. Artificial lights do not provide the same cues, {{2}} their lack of attraction. This {{3}} in behavior underscores the diverse {{4}} strategies evolved by these creatures over millennia.', NULL, NULL, NULL, E'1.species, 2.hence, 3.distinction, 4.survival', NULL, NULL),
  ('680cdb66-8430-5aca-82c3-5e3aa2dfe6c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '680cdb66-8430-5aca-82c3-5e3aa2dfe6c4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4b239d5f-aa8b-552b-a957-1c86261a2b96'::uuid, NULL, NULL, E'Next week, it looks like it''s going to rain a lot.', NULL, NULL),
  ('68118be9-ad26-57f1-9b85-67a829e4f8a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '68118be9-ad26-57f1-9b85-67a829e4f8a6'::uuid, 1, NULL, TRUE, 0, NULL, E'Losing Weight', E'Losing weight is no walk in the park. ( Although a walk in the park wouldn''t hurt). Seems no matter what diet you try, those {{1}} love handles just won''t go away. Part of the problem is that the bulk of your bulk is stored inside fat cells. And the number of fat cells you have is set before you reach adulthood. So if you chunked up as a child, that battalion of fat cells is with you for life. It''s enough to make you want to bury your face in a tray of {{2}} , I know. But hold off. Because researchers from Stockholm think they''ve found a loophole.\nThe Swedish scientists confirmed that even after massive weight loss, the number of fat cells an adult has remains the same. But they {{3}} that individual fat cells don''t last a {{4}} . Each year, about 10 percent of them die off. Of course new fat cells take their place, findings that appear in the online issue of the journal Nature. While that might not seem like a major victory, if scientists can figure out how to stop the {{5}} fat cells from being born, that would tip the scales in your favor. So you might just be able to have your cake and eat it too, and still fit into your pants.', NULL, NULL, NULL, E'1.stubborn, 2.brownies, 3.discovered, 4.lifetime, 5.replacement', NULL, NULL),
  ('681ade0e-82b0-5453-920c-878b7ab4b9ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '681ade0e-82b0-5453-920c-878b7ab4b9ca'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '74f9e29d-fd5b-5ac4-9ede-5db519ed676d'::uuid, NULL, NULL, E'Sociological studies emphasize the importance of the family.', NULL, NULL),
  ('681c1794-3237-52e3-8e4b-562d214aeccd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '681c1794-3237-52e3-8e4b-562d214aeccd'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '357de42d-0834-58d0-a022-231f60fa1ebf'::uuid, NULL, NULL, E'Journalism students don''t have a standard test to pass.', NULL, NULL),
  ('681c88ef-3fad-5a87-9c1d-701d841d15c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '681c88ef-3fad-5a87-9c1d-701d841d15c4'::uuid, 1, NULL, TRUE, 0, NULL, E'Death Experiences', E'These days it seems near death experiences are a common phenomenon. The research team, which studied hundreds of cases to narrow down the medical definition, discovered that around fifteen per cent of people who have been resuscitated from a coma after cardiac arrest have had these experiences.', NULL, NULL, NULL, NULL, NULL, NULL),
