  ('684bc139-3730-5e4c-8f3f-8b8c82ec301a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '684bc139-3730-5e4c-8f3f-8b8c82ec301a'::uuid, 1, NULL, TRUE, 0, NULL, E'Geography', E'Many famous geographers and non-geographers have attempted to define the discipline in a few short words. The concept has also changed throughout the ages, making it difficult to create a {{1}} , universal geography definition for such a dynamic and all-encompassing subject. After all, Earth is a big place with many {{2}} to study. It affects and is affected by the people who live there and use its {{3}} . But basically, geography is the study of the {{4}} of Earth and the people who live there, and all that encompasses.', NULL, NULL, NULL, E'1.concise, 2.facets, 3.resources, 4.surface', NULL, NULL),
  ('6851375e-8b05-5657-9545-95d46fd51bbf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '6851375e-8b05-5657-9545-95d46fd51bbf'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0d884a35-57c6-58d3-a2ca-7cb3bfe2a500'::uuid, NULL, NULL, E'Each of us must take responsibility for our own actions.', NULL, NULL),
  ('68515747-751a-57ba-baaf-8458c9e3ec56'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '68515747-751a-57ba-baaf-8458c9e3ec56'::uuid, 1, NULL, TRUE, 0, NULL, E'Sustainable Seafood', E'Sustainability essentially refers to the most efficient use of products. In the case of seafood, sustainability relates to fish and shellfish caught for human consumption by fishers operating under sustainable fishery-management systems. According to Fish Watch, these systems conserve fish stock and the ecosystems that support these species.\nFish Watch offers a simpler definition, explaining that sustainable seafood refers to any seafood products that are healthy for the planet, people and economy. Sustainable seafood aims to offer healthy products without harming the oceanic environment and other species in a way that matters in the long run.\nThe quest to find sustainable seafood is an endurance race, not a quick sprint. It involves coordinating fisheries with government regulators and consumers. Consumers are empowered to make sustainable food choices when they have information and education on selecting the best products with the people, planet and economy in mind.\nSustainable seafood choices impact not just one spot on the bottom of the ocean but the entire oceanic environment. They can potentially have a lasting impact on fish populations and communities which heavily rely on fish farming and fishers for a sufficient protein source and millions of jobs. In 2015, the seafood industry alone accounted for 1.6 million jobs in the U.S.\nIn addition, the health of our oceans affects the quality of the food we receive. Factors like what chemicals companies are fishing with or what bacteria might they introduce into water sources can significantly impact human well-being on a global scale. If you like seafood and want to help support the supply of your favorite dockside dishes, choosing sustainable seafood can make a big impact over time.', NULL, NULL, NULL, NULL, 5, 75),
  ('6852f4dc-88b0-5ee8-8f23-41200ffb455b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6852f4dc-88b0-5ee8-8f23-41200ffb455b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bbaaa112-5460-5b32-be88-1093d2699a87'::uuid, NULL, E'The tutorial rooms are located along the left-hand side.', NULL, NULL, NULL),
  ('685af71e-7419-50a3-a573-e75cad23570a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '685af71e-7419-50a3-a573-e75cad23570a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which language do we call the most widely spoken language in the world?', 'c86c935b-68c3-5bdc-8a18-9f1f4ec48430'::uuid, NULL, NULL, E'Mandarin Chinese', NULL, NULL),
  ('686013e5-4c36-55d3-acf7-194bc3c98bbb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '686013e5-4c36-55d3-acf7-194bc3c98bbb'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for the process of adapting or adjusting to the culture of a group or nation, or the state of being so adapted?', 'd94ac2c1-7109-5895-aae0-9763ef2d8864'::uuid, NULL, NULL, E'Acculturation.', NULL, NULL),
  ('6866e6d1-68bc-5d12-87be-f381114120ea'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '6866e6d1-68bc-5d12-87be-f381114120ea'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e962842f-9b31-5316-ba24-4be46491fbfc'::uuid, NULL, NULL, E'The global conversation now often includes the politics of food.', NULL, NULL),
  ('686d91e3-36c5-5058-aa67-bf6d58a8076e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '686d91e3-36c5-5058-aa67-bf6d58a8076e'::uuid, 1, NULL, TRUE, 0, NULL, E'Intelligent Elephant', NULL, 'f3e12f15-1c05-576f-953a-0ae135111b47'::uuid, NULL, E'The elephant boasts the largest brain of any land mammal, as well as an impressive encephalization quotient. This is the size of the brain relative to what we’d expect for an animal’s body size, and the elephant’s EQ is nearly as high as a chimpanzee’s. And despite the distant relation, convergent evolution has made it remarkably similar to the human brain, with as many neurons and synapses and a highly developed hippocampus and cerebral cortex. It is the hippocampus, strongly associated with emotion, that aids recollection by encoding important experiences into long-term memories. The ability to distinguish this importance makes elephant memory a complex and adaptable faculty beyond rote memorization. It’s what allows elephants who survived a drought in their youth to recognize its warning signs in adulthood, which is why clans with older matriarchs have higher survival rates. Unfortunately, it’s also what makes elephants one of the few non-human animals to suffer from post-traumatic stress disorder. The cerebral cortex, on the other hand, enables problem solving, which elephants display in many creative ways. They also tackle problems cooperatively, sometimes even outwitting the researchers and manipulating their partners. And they’ve grasped basic arithmetic, keeping track of the relative amounts of fruit in two baskets after multiple changes.', NULL, NULL, NULL),
  ('6870d7d5-df56-587c-827f-7118a4b0b9e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6870d7d5-df56-587c-827f-7118a4b0b9e1'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What natural resource is used by a carpenter?', 'fc632ada-c78e-54ab-91c0-28533569ef95'::uuid, NULL, NULL, E'Wood / timber', NULL, NULL),
  ('6873d3cb-246f-53f0-9cba-56f88ade6f77'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6873d3cb-246f-53f0-9cba-56f88ade6f77'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person who pays rent to the landlord?', '969ac659-ce39-5385-a051-29ba718f6db3'::uuid, NULL, NULL, E'Lessee / tenant', NULL, NULL),
  ('6873f076-8bdd-5e54-bb64-7c05fb1ecdce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '6873f076-8bdd-5e54-bb64-7c05fb1ecdce'::uuid, 1, NULL, TRUE, 0, NULL, E'Most Respected Companies', E'Look at the recent "Most Respected Companies" survey by the Financial Times. Who are the most respected companies and business leaders at the {{1}} time? Rather predictably, they are Jack Welch and General Electric, and Bill Gates and Microsoft. {{2}} has achieved their world class status through playing nice. Welch is still remembered for the brutal downsizing he led his business {{3}} and for the environmental pollution incidents and prosecutions. Microsoft has had one of the {{4}} profile cases of bullying market dominance of recent times- and Gates has been able to {{5}} the financial status where he can choose to give lots of money away by being ruthless in business.', NULL, NULL, NULL, E'1.current, 2.Neither, 3.through, 4.highest, 5.achieve', NULL, NULL),
  ('687964a9-daa9-578a-bfd6-b48fd21f1070'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '687964a9-daa9-578a-bfd6-b48fd21f1070'::uuid, 1, NULL, TRUE, 0, NULL, E'Radioactivity', E'Radioactivity was discovered in 1896 by the French physicist, Antoine Henri Becquerel. He left an unexposed photographic plate in the dark near a sample of a uranium salt. When the plate was {{1}} it was found to be {{2}} , just as if it had been exposed to light, which was caused by a form of radiation from the uranium.\nThe term radioactivity was {{3}} by Marie Curie and her husband Pierre Curie. They worked together and showed that radioactivity was an atomic property not a chemical change. The {{4}} of radioactivity won the Curies and Ekcquerel the Nobel Prize for Physics in 1903.', NULL, NULL, NULL, E'1.developed, 2.fogged, 3.coined, 4.discovery', NULL, NULL),
  ('688000bc-1cd0-52ed-9cf6-c5e5cca0a53e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '688000bc-1cd0-52ed-9cf6-c5e5cca0a53e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e9000cf8-25d8-5535-8b35-191254827224'::uuid, NULL, NULL, E'Imported default packages are likely to be used for most computers.', NULL, NULL),
