  ('69386d2a-d66f-5731-b8d8-1fa70fb17758'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '69386d2a-d66f-5731-b8d8-1fa70fb17758'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the process by which organisms produce offspring?', 'dcf88c67-9c28-5334-9f30-9cd1aa5789c1'::uuid, NULL, NULL, E'Reproduction', NULL, NULL),
  ('693be943-1dea-55b8-a929-b6e645ac31c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '693be943-1dea-55b8-a929-b6e645ac31c6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '056f36e0-b1a3-5c42-a361-2298ac40a0f6'::uuid, NULL, E'The course registration is open in early March for new students.', NULL, NULL, NULL),
  ('69466b55-20bb-5dda-82f2-39bdf744944f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '69466b55-20bb-5dda-82f2-39bdf744944f'::uuid, 1, NULL, TRUE, 0, NULL, E'Architectural Studies', E'Architectural studies demand a rigorous work ethic, countering the misconception that {{1}} talent alone leads to success. Drawing {{2}} to the mastery of an instrument, the discipline requires {{3}} practice and dedication. The comprehensive understanding of architecture encompasses not only the creation of structures but also the influence of societal trends, technological advancements, and cultural {{4}} .', NULL, NULL, NULL, E'1.innate, 2.parallels, 3.consistent, 4.dynamics', NULL, NULL),
  ('694b5728-0e04-57d7-9d57-b6757ac52018'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '694b5728-0e04-57d7-9d57-b6757ac52018'::uuid, 1, NULL, TRUE, 0, NULL, E'Textile Industry', E'The environmental impact of the global textile industry is hard to overstate. One-third of the water used worldwide is spent fashioning fabrics. For every ton of cloth {{1}} , 200 tons of water is polluted with chemicals and heavy metals. An estimated 1 trillion kilowatt-hours of electricity powers the factories that card and comb, spin and weave, and cut and stitch materials into everything from T-shirts to towels, {{2}} behind mountains of solid waste and a massive carbon footprint. "Where the industry is today is not really sustainable for the long term," says Shreyaskar Chaudhary, chief executive of Pratibha Syntex, a textile manufacturer based outside Indore, India. With something of an "if you build it, they will come" attitude, Mr. Chaudhary has steered Pratibha {{3}} the leading edge of eco-friendly textile production. Under his direction, Pratibha began making clothes with organic cotton in 1999. Initially, the company couldn''t find enough organic farms growing cotton in central India to {{4}} its factories. To meet production demands, Chaudhary''s team had to convince conventional cotton farmers to change their growing methods. Pratibha provided seeds, cultivation instruction, and a guarantee of fairtrade prices for their crops. Today, Pratibha has a network of 28,000 organic cotton growers across the central states of Madhya Pradesh, Maharashtra, and Orissa.', NULL, NULL, NULL, E'1.produced, 2.leaving, 3.toward, 4.supply', NULL, NULL),
  ('694c1548-22b0-54ef-a33a-7cb446080510'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '694c1548-22b0-54ef-a33a-7cb446080510'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How many years are there in a decade?', '926f47f9-6c5a-5fb5-9e63-7b3b0cd24e3a'::uuid, NULL, NULL, E'10 years', NULL, NULL),
  ('694c72ed-8383-5509-be7b-d28a982957c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '694c72ed-8383-5509-be7b-d28a982957c5'::uuid, 1, NULL, TRUE, 0, NULL, E'Social Situations', E'In social situations, some people believe that it is better to be a good listener than a good talker. Do you agree or disagree?', NULL, NULL, NULL, NULL, 200, 300),
  ('694e5988-b7b4-5efc-ad02-143b90bb8d84'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '694e5988-b7b4-5efc-ad02-143b90bb8d84'::uuid, 1, NULL, TRUE, 0, NULL, E'Social Factors', E'Society and culture have great {{1}} on the business environment. These factors include demographics like population growth, age distribution, and attitudes toward safety and health {{2}} . For example, {{3}} rates of obesity have forced management to look closely at marketing campaigns in giant food corporations such as Nestle and Kraft Foods.', NULL, NULL, NULL, E'1.impacts, 2.consciousness, 3.rising', NULL, NULL),
  ('6952a706-49b5-5ecd-898f-b8e43a5e1147'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6952a706-49b5-5ecd-898f-b8e43a5e1147'::uuid, 1, NULL, TRUE, 0, NULL, E'Medicine and Values', E'How would you feel about a new therapy for your chronic pain, which — although far more effective than any available alternative — might also change your religious beliefs? Or a treatment for lymphoma that brings one in three patients into remission, but also made them more likely to vote for your least preferred political party?', NULL, NULL, NULL, NULL, NULL, NULL),
  ('695367bc-356e-5446-9d73-7ce7a3f35edd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '695367bc-356e-5446-9d73-7ce7a3f35edd'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0ad2dcbd-9cb8-5663-b8a5-f2d4849b1e63'::uuid, NULL, NULL, E'The class teaches you about numbers and how to use them well.', NULL, NULL),
  ('695500df-a400-50b0-b794-a0c3b53cba58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', '695500df-a400-50b0-b794-a0c3b53cba58'::uuid, 1, NULL, TRUE, 0, NULL, E'MCM-R', E'Europe in the eleventh century underwent enormous social, technological, and economic changes, but this did not create a new Europe—it created two new ones. The north was developed as a rigidly hierarchical society in which status was determined, or was at least indicated, by the extent to which one owned, controlled, or labored on land; whereas the Mediterranean south developed a more fluid, and therefore more chaotic, world in which industry and commerce predominated and social status both reflected and resulted from the role that one played in the public life of the community. ln other words, individual identity and social community in the north were established on a personal basis, whereas in the south they were established on a civic basis. By the start of the twelfth century, northern and southern Europe were very different places indeed, and the Europeans themselves noticed it and commented on it.\n\nWhich of the following was a deciding factor in person''s place in society in northern and southern Europe respectively at the end of the eleventh century?', NULL, NULL, NULL, E'Role in public life in the community.\nRelationship to land through ownership or labor.', NULL, NULL),
  ('69569197-9c86-5f2f-a900-c84b972ca0df'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '69569197-9c86-5f2f-a900-c84b972ca0df'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4f33b83b-2130-55db-a8ff-90c80698cd15'::uuid, NULL, NULL, E'We have been working together with other major comprehensive universities.', NULL, NULL),
