  ('69a6311d-0632-5971-abab-960168ca90c1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '69a6311d-0632-5971-abab-960168ca90c1'::uuid, 1, NULL, TRUE, 0, NULL, E'Presentation', E'So next Wednesday you''re all going to be doing your presentations. We''ll have to be very strict about timing. Fifteen minutes each — not a minute more. It might make sense to do a practice run-through at home but that''s up to you. I''m going to ask you to put an abstract of your presentation on our course website but I''d like you to do that after you''ve given your talk. Come with your slides on a memory stick — that''s the most straightforward way of dealing with things, I think. Oh, and don''t forget to bring handouts for everyone. There won''t be time to do photocopying that morning. So, any questions!\n\nWhat must the students do before next Wednesday!', '55b2f7a6-99c9-59c0-86ba-f561eb827607'::uuid, NULL, NULL, E'make enough copies of their handouts', NULL, NULL),
