  ('69ef014d-af0c-5817-974a-570b45db2188'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '69ef014d-af0c-5817-974a-570b45db2188'::uuid, 1, NULL, TRUE, 0, NULL, E'Political Declaration', E'The Assembly also decided that, at that special session, it would adopt a concise and action-oriented political declaration, agreed upon in advance by consensus through intergovernmental negotiations under the auspices of the Conference.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('69f33852-9c5a-50f4-8106-ea9c24639f74'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '69f33852-9c5a-50f4-8106-ea9c24639f74'::uuid, 1, NULL, TRUE, 0, NULL, E'Sleep Patterns', E'Children have sound sleep patterns. They can {{1}} sleep for 8-9 hours and get up at a fixed time. But teenagers don''t. Their sleep patterns are {{2}} by their {{3}} schedules, in which they sometimes have more classes but sometimes have fewer. {{4}} these factors, they actually need longer sleep and {{5}} sleep may be responsible for their learning problems.', NULL, NULL, NULL, E'1.soundly, 2.influenced, 3.erratic, 4.Despite, 5.insufficient', NULL, NULL),
