  ('6a07cb60-23c4-5e08-a36f-0da45057cf2d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6a07cb60-23c4-5e08-a36f-0da45057cf2d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '73366fb7-e1b3-56e9-8289-56efbf1eec46'::uuid, NULL, E'The business school offers internships and networking opportunities.', NULL, NULL, NULL),
  ('6a089546-fc2b-5b26-9e17-64b4f06365e7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6a089546-fc2b-5b26-9e17-64b4f06365e7'::uuid, 1, NULL, TRUE, 0, NULL, E'Running', E'People run for many different reasons, namely: for fun, for exercise, to raise money for charities, and so on. Over the past decades, running has become an essential part of many health routines because of the publicity about its beneficial effects. It is claimed that it is good for our heart, it reduces stress and it helps to prevent diseases like diabetes.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('6a089e31-44b9-5c3f-954c-20f7c4257665'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6a089e31-44b9-5c3f-954c-20f7c4257665'::uuid, 1, NULL, TRUE, 0, NULL, E'Apple', NULL, 'af528059-87ff-500a-963a-d723b0f17f9f'::uuid, NULL, E'One other keys to Apple is Apple''s incredibly collaborative company, and so you know how many committees we have in Apple? Zero. No committee. We are organized like a start-up. One person''s in charge of iPhone OS software, one person is in charge of Mac hardware. One person is in charge of iPhone hardware engineering, another person is in charge of worldwide marketing, another person''s in charge of operations. We''re organized like a startup. We''re the biggest startup on the planet and we all meet for three hours once a week and we talk about everything we''re doing the whole business and there''s tremendous teamwork at the top of the company which filters down to tremendous teamwork throughout the company. And teamwork is dependent on trusting the other folks to come through with their part without watching them all the time but trusting that they''re gonna come through with their parts and that''s what we do really well and we''re great at figuring out how to divide things up in these great teams that we have and all work on the same thing, touch basis frequently and bring it all together into a product. We do that really well and so what I do all day is meet with teams of people and work on ideas and solve problems to make new products to make new marketing programs whatever it is.', NULL, NULL, NULL),
  ('6a0a6384-0318-517c-9033-6b919f7f41be'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '6a0a6384-0318-517c-9033-6b919f7f41be'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b511bdf3-360f-5da4-aa90-c81d07f89682'::uuid, NULL, NULL, E'Animal and plant cells have a number of structures in common.', NULL, NULL),
