  ('6a952ced-c8ea-55d5-8b63-fd038941860c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '6a952ced-c8ea-55d5-8b63-fd038941860c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c1aca67b-bbde-524b-9fe5-2d5174c8734c'::uuid, NULL, NULL, E'The methods of communication among people are evolving over time steadily.', NULL, NULL),
  ('6a985f14-2211-533d-9689-29e414c085fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6a985f14-2211-533d-9689-29e414c085fb'::uuid, 1, NULL, TRUE, 0, NULL, E'Strong Research Question', NULL, '5af7f1c1-d7a6-531b-b6aa-bec2b1819b68'::uuid, NULL, E'Here are 5 steps to develop a strong research question. Step 1, choose a broad topic. Go with a topic that sparks your interest, since you’ll be spending quite some time with it. For me, I’m thinking maybe something about social media. Step 2, do some preliminary reading about the topic. Ok, so I’ve read a lot of newspaper writing about how social media negatively impacts high school students’ academic performances. And they also happen to be one of the most active age groups on social media. Step 3, narrow down to a specific niche. This way, you can make sure the research is within a feasible scope instead of something too broad to achieve in a given timeframe. Since academic performance is too broad, let me narrow it down to attention span. Step 4, identify a research problem. So we have already established that adolescences are one of the most active age groups on social media platforms. But only a scarce amount of research has been done on the effect of social media has on the younger generation’s attention span. So this will be my research problem. Step 5, write your research question! Turning your research problem into a question, and it sounds something like: What effect does daily use of Twitter have on the attention span of people in the age group of 16 to 20? Since this is the descriptive research, the research question is also descriptive. But there are also other kinds of research questions, it all depends on the type of research you’ll do. For example comparative research, descriptive research, or correlational research.', NULL, NULL, NULL),
  ('6a9a2026-bdac-5e1a-b2ba-237f1e5825b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6a9a2026-bdac-5e1a-b2ba-237f1e5825b2'::uuid, 1, NULL, TRUE, 0, NULL, E'Brain Development', E'Scientific studies show that by age three there is a gap in brain development between kids who read aloud and those who do not, and children from low-income families are disproportionately impacted by this gap. Making sure all parents know the importance of reading aloud to their children is critical to closing the achievement gap.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('6a9c28f6-f3f1-5b3b-926e-c713627bc081'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '6a9c28f6-f3f1-5b3b-926e-c713627bc081'::uuid, 1, NULL, TRUE, 0, NULL, E'Advertising', E'Advertisements make people purchase things they don’t need or cannot afford, but they also convey information to increase people''s life quality. What is your opinion?', NULL, NULL, NULL, NULL, 200, 300),
