  ('6aa4e39c-bb79-5b33-b328-c143273f5ac3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '6aa4e39c-bb79-5b33-b328-c143273f5ac3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c79779a2-cd18-5c4d-ac4c-e158fa006aec'::uuid, NULL, NULL, E'Keeping organized class notes makes study time more efficient.', NULL, NULL),
  ('6aa8eeca-ae67-5ec3-8028-651f62f1785b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '6aa8eeca-ae67-5ec3-8028-651f62f1785b'::uuid, 1, NULL, TRUE, 0, NULL, E'Personal Development', E'It makes sense for businesses to {{1}} time and resources into building and developing employee skills and strengths. On a professional level, increasing employee skills and understanding strengthens the business. Many companies will help fund employees’ education who want to {{2}} advanced degrees or certifications in their field. Training seminars and programs can also be useful tools for professional development. Though it might not seem to be as directly related to business goals, investing in the personal development of employees also {{3}} the organization. This type of development could still be related to professional functions, such as programs that help develop leadership skills or seminars that train employees in how to manage interpersonal communication skills. These would have obvious practical value in most organizational settings. Even if personal development programs do not have direct application to the workplace, helping employees become {{4}} individuals and reach stability and fulfillment in their personal lives will always provide a carryover benefit to the organization.', NULL, NULL, NULL, E'1.invest, 2.pursue, 3.benefits, 4.well-rounded', NULL, NULL),
  ('6aa93860-552e-5d97-a788-673b7c0b7cca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '6aa93860-552e-5d97-a788-673b7c0b7cca'::uuid, 1, NULL, TRUE, 0, NULL, E'Consumer Shifts', E'Social media and online reviews influence decisions, and e-commerce has become the norm. Companies adapt by {{1}} data analytics to understand and predict consumer behavior. The shift {{2}} convenience and personalization is reshaping the retail landscape, pushing brands to innovate and {{3}} their approaches to meet {{4}} customer expectations.', NULL, NULL, NULL, E'1.utilizing, 2.towards, 3.tailor, 4.evolving', NULL, NULL),
  ('6ac37007-9257-55e5-9d69-18c4b5a0c702'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '6ac37007-9257-55e5-9d69-18c4b5a0c702'::uuid, 1, NULL, TRUE, 0, NULL, E'Audiovisuals’ Impact', E'The power of audiovisuals has been manifested and exploited politically, socially, and economically throughout history. Leaders such as Adolf Hitler, for example, successfully used films as propaganda tools during World War II. Unfortunate facts like these show the raw power of film has even caused revolutions.\nAs technology keeps growing, political and economic leaders have utilized cinema in changing and shaping people’s outlooks either for their own benefit or for the benefit of the people. Quality translations are also readily available and extremely affordable for everyone these days, which makes it easy for filmmakers to reach their target audiences from all corners of the world in their mother tongue.\nA good movie can entertain, educate, and inspire the viewer in many ways. Think of the impact that songs have on people, for example. They can make us think. They can make us compassionate. They can inspire us to help others and to do good to and for humanity. Romantic movies, on the other hand, can remind us why love is important and why it is worth fighting for. They make us cry and laugh at our own romantic flaws. Crime and action TV shows also warn us about the dangers of criminal activities, terrorism, and war.\nEvery movie is set and developed in a particular culture. Movies are an integral part of us; they mirror what we believe and how we coexist as people. It is easier to see our concerns, attitudes, flaws and strengths in films than it is to decipher them from our daily interactions. When our prevalent beliefs and ideologies are challenged in films, we are sometimes able to interrogate ourselves and embrace change.', NULL, NULL, NULL, NULL, 5, 75),
  ('6ac8ca0f-685b-5b20-91e9-40824cf05a40'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6ac8ca0f-685b-5b20-91e9-40824cf05a40'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the number that is obtained by multiplying a number by itself?', '36f0ab67-f114-5d09-a53f-64cdbf260648'::uuid, NULL, NULL, E'Square', NULL, NULL),
  ('6ac9a168-8f60-511c-99af-b09f86120ed3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '6ac9a168-8f60-511c-99af-b09f86120ed3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '27fffb55-6fad-5058-84da-f504afdd43c1'::uuid, NULL, NULL, E'Experts have made some assumptions based on students'' study habits.', NULL, NULL),
  ('6acdb564-1e0d-56ce-8268-1d4fc7c5cc14'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6acdb564-1e0d-56ce-8268-1d4fc7c5cc14'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2c4a376a-f2b1-5360-b042-05e1f76ab4ef'::uuid, NULL, E'There is no compelling reason for me to believe him.', NULL, NULL, NULL),
  ('6ace1267-b541-58fd-b5af-e53d204ec19b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '6ace1267-b541-58fd-b5af-e53d204ec19b'::uuid, 1, NULL, TRUE, 0, NULL, E'Happy', E'Want to know what will make you happy? Then ask a total stranger — or so says a new study from Harvard University, which shows that another person’s experience is often more {{1}} than your own best guess.\nThe study, which appears in the current issue of Science, was led by Daniel Gilbert, professor of psychology at Harvard and author of the 2007 bestseller “Stumbling on Happiness,” along with Matthew Killingsworth and Rebecca Eyre, also of Harvard, and Timothy Wilson of the University of Virginia.\n“If you want to know how much you will enjoy an experience, you are better off knowing how much someone else enjoyed it than knowing anything about the experience itself,” says Gilbert. “Rather than closing our eyes and {{2}} the future, we should examine the experience of those who have been there. Previous research in psychology, neuroscience, and behavioral economics {{3}} that people have difficulty predicting what they will like and how much they will like it, which {{4}} them to make a wide variety of poor decisions. Interventions aimed at {{5}} the accuracy with which people imagine future events have been generally unsuccessful.', NULL, NULL, NULL, E'1.informative, 2.imagining, 3.has shown, 4.leads, 5.improving', NULL, NULL),
  ('6acec2ed-759e-5d32-81db-717c2a6415fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '6acec2ed-759e-5d32-81db-717c2a6415fe'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c3570ab2-da36-536a-a45e-bc5dd1b5b48a'::uuid, NULL, NULL, E'The library has a number of collections of historical and social statistical publications.', NULL, NULL),
