  ('6ae13102-c13b-5b3c-bd5a-41f3c3531646'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6ae13102-c13b-5b3c-bd5a-41f3c3531646'::uuid, 1, NULL, TRUE, 0, NULL, E'Electronic Blood Vessels', E'Researchers have developed electronic blood vessels that can be actively tuned to address subtle changes in the body after implantation. The blood vessels -- made of a metal-polymer conductor membrane that''s flexible and biodegradable -- mimic natural blood vessels, were conductive in vitro experiments, and were able to effectively replace key arteries in rabbits.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('6aeead08-d988-5f6a-b1fe-9814b8784f28'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '6aeead08-d988-5f6a-b1fe-9814b8784f28'::uuid, 1, NULL, TRUE, 0, NULL, E'Earth-like Planets', E'Earth-like planets have the {{1}} to form around many—and perhaps most—of the nearest stars that are like our sun. Michael Meyer of the University of Arizona announced that {{2}} Sunday at the annual meeting of the American Association for the Advancement of Science. Meyer says that between 20 and 60 percent of the stars are {{3}} for the development of rocky planets.\nThe researchers used the NASA Spitzer Space Telescope. Meyer explains: "With Spitzer, we detect the heat radiation of dust grains, not unlike the smoke you will see rising from chimneys (around here in the Boston area) on a cold day." Models say that the observed warm dust is consistent with small rocky bodies smashing into each other. "From those observations of dust, we infer the {{4}} of colliding larger rocky bodies, not unlike asteroids and other things in our solar system that we know bang together and generate dust. By tracing that dust, we trace these dynamical processes that we think led to the {{5}} of the terrestrial planets in our solar system."', NULL, NULL, NULL, E'1.potential, 2.discovery, 3.candidates, 4.presence, 5.formation', NULL, NULL),
  ('6aeeb262-cabd-5dad-861b-bd3a338923c1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6aeeb262-cabd-5dad-861b-bd3a338923c1'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a2c705d9-bdcd-5d09-af46-fb3e1e70a62d'::uuid, NULL, E'Doctor Smith''s lecture will be held at the art center.', NULL, NULL, NULL),
