  ('6beafc19-9a0b-5c1c-a483-418126909392'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6beafc19-9a0b-5c1c-a483-418126909392'::uuid, 1, NULL, TRUE, 0, NULL, E'Stressful Occupations', E'Just how stressed are teachers? A recent Gallup poll found teachers are tied with nurses for the most stressful occupation in America today. Unfortunately, that stress can have a trickle-down effect on their students, leading to disruptive behavior that results in student suspensions.', NULL, NULL, NULL, NULL, NULL, NULL),
