  ('6c9def4e-94a7-5385-86be-834619aa46a9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6c9def4e-94a7-5385-86be-834619aa46a9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd82badde-c9fa-5e60-8d65-322548984a7e'::uuid, NULL, E'Students'' papers should be about a current social issue.', NULL, NULL, NULL),
  ('6c9fcb25-fc5d-5f5e-8ade-d4131b95166a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '6c9fcb25-fc5d-5f5e-8ade-d4131b95166a'::uuid, 1, NULL, TRUE, 0, NULL, E'Modern Humans', E'Modern humans are masters of multitasking. We eat while driving, watch TV while {{1}} , and of course talk on our cell phones while doing, well, {{2}} . How do we do it? A study in the July 16th issue of Neuron suggests that though we can train our brains to work faster as we juggle, we never {{3}} manage to do more than one thing at a time.\nOur brains aren''t really built to handle the sort of {{4}} processing we think we''re capable of. The good news is: studies have shown that extensive training can make us better at doing two things at once. But how?\nOne theory is that with lots of {{5}} some routines become "automatic." And if we don''t need to run every little thing past the part of the brain that spends time {{6}} about stuff, we can multitask just fine.\nBut this new study finds that that''s not the way it works. Turns out that multitaskers still consult the prefrontal cortex, but training gets the "Thinking Brain" to think a little faster. So we''re switching tasks quickly enough to appear to be doing them simultaneously. Which is still nothing to shake a stick and sneeze at.', NULL, NULL, NULL, E'1.studying, 2.everything, 3.actually, 4.parallel, 5.practice, 6.thinking', NULL, NULL),
  ('6ca08785-479b-5c8d-be1f-731f3b5148a0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6ca08785-479b-5c8d-be1f-731f3b5148a0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8f496517-1e91-5092-ab22-f8f2ce7205ef'::uuid, NULL, E'Customers can pick up the camera at the circulation desk of the store.', NULL, NULL, NULL),
