  ('6cc2e768-f7c2-55ad-b438-ad9a08601773'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6cc2e768-f7c2-55ad-b438-ad9a08601773'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c1c5c410-b9e1-5e05-9a91-e09b4bf2a20a'::uuid, NULL, E'There is a fitness center next to the student union.', NULL, NULL, NULL),
  ('6cc7317e-cdca-5717-bacd-dc2329b8c9b6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6cc7317e-cdca-5717-bacd-dc2329b8c9b6'::uuid, 1, NULL, TRUE, 0, NULL, E'Nikola Tesla', E'As the inventor of alternating-current technology, Nikola Tesla played a paramount role in the electricity used to power the entire world. Tesla also worked diligently on a dream of supplying electrical power without wires. Thomas Edison was also instrumental in shaping society today with his inventions. Edison''s design of the inside of the light bulb was the crucial key to making a light that would stay lit for hours instead of going out almost immediately.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('6cdc6b75-5caf-5cd3-90a8-77c4c800d7fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '6cdc6b75-5caf-5cd3-90a8-77c4c800d7fb'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7a815495-f53f-5336-93ff-c86b547d4ae7'::uuid, NULL, NULL, E'Atmosphere is composed of several layers.', NULL, NULL),
  ('6cdd3214-781a-52aa-b14f-da1204befced'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6cdd3214-781a-52aa-b14f-da1204befced'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '885490d3-9352-5d64-897b-b555a5935130'::uuid, NULL, E'There are many people in the USA who are critical of the voting system.', NULL, NULL, NULL),
  ('6ce43aa8-56f0-508d-9799-8f7aa3f3614d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6ce43aa8-56f0-508d-9799-8f7aa3f3614d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'cbaa633b-4052-5a97-a36d-a0c6478f9224'::uuid, NULL, E'Farmers do not always receive fair prices for agricultural goods.', NULL, NULL, NULL),
  ('6ce56511-f6e5-5649-b8a2-0b226876153b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '6ce56511-f6e5-5649-b8a2-0b226876153b'::uuid, 1, NULL, TRUE, 0, NULL, E'Digital Marketing', E'At a high level, digital marketing refers to advertising delivered through digital channels such as search engines, websites, social media, email, and mobile apps. Using these online media channels, digital marketing is the method by which companies endorse goods, services, and brands. Consumers heavily rely on digital means to research products. For example, ‘Think With Google’ marketing insights found that 48% of consumers start their inquiries on search engines, while 33% look to brand websites and 26% search within mobile applications.\nWhile modern day digital marketing is an enormous system of channels to which marketers simply must onboard their brands, advertising online is much more complex than the channels alone. In order to achieve the true potential of digital marketing, marketers have to dig deep into today’s vast and intricate cross-channel world to discover strategies that make an impact through engagement marketing. Engagement marketing is the method of forming meaningful interactions with potential and returning customers based on the data you collect over time. By engaging customers in a digital landscape, you build brand awareness, set yourself as an industry thought leader, and place your business at the forefront when the customer is ready to buy.\nBy implementing an omnichannel digital marketing strategy, marketers can collect valuable insights into target audience behaviors while opening the door to new methods of customer engagement. Additionally, companies can expect to see an increase in retention. According to a report by Invesp, companies with strong omnichannel customer engagement strategies retain an average of 89% of their customers compared to companies with weak omnichannel programs that have a retention rate of just 33%.\nAs for the future of digital marketing, we can expect to see a continued increase in the variety of wearable devices available to consumers. Forbes also forecasts that social media will become increasingly conversational in the B2B space, video content will be refined for search engine optimization (SEO) purposes, and email marketing will become even more personalized.', NULL, NULL, NULL, NULL, 5, 75),
  ('6ce7a18d-6f99-54ee-a5a6-725e15250b29'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6ce7a18d-6f99-54ee-a5a6-725e15250b29'::uuid, 1, NULL, TRUE, 0, NULL, E'Team Project', E'After a team project meeting, you notice that tasks are frequently being misunderstood or forgotten, leading to delays and frustration. You need to address the team to encourage clear communication, timely updates, and shared responsibility for the project''s success. What would you say to the team?', '068d9384-2b2d-53e3-b57e-a5077112fa0a'::uuid, NULL, E'Well, I''ve noticed we''re facing challenges with task clarity and follow-through, which is affecting our project''s timeline and morale. To enhance our efficiency, let''s implement a shared digital task board for real-time updates and responsibility tracking. This will help everyone stay informed and accountable. Additionally, I propose weekly check-ins where we can address any confusion and adjust plans as needed. Let''s work together to make this a success.', NULL, NULL, NULL),
  ('6ceb0d9e-f24b-5caa-baeb-6dc84cae07f6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '6ceb0d9e-f24b-5caa-baeb-6dc84cae07f6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e8ca9ff9-5ee1-5bb6-a45b-f098eb3b4ea5'::uuid, NULL, NULL, E'Traffic noise is intensified by high buildings.', NULL, NULL),
