  ('6e23616b-4410-547e-bf8f-2c320111ed1e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6e23616b-4410-547e-bf8f-2c320111ed1e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '597f54c6-9e7a-5a96-b6a0-8edf131c56dd'::uuid, NULL, E'Most of these criticisms can be shown to be false.', NULL, NULL, NULL),
  ('6e24ac3c-44e9-5820-bf70-867bad8257a3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6e24ac3c-44e9-5820-bf70-867bad8257a3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3dd35774-a1e2-54e8-895a-baed1a6d301a'::uuid, NULL, E'Chapter one provides the historical background to the topic.', NULL, NULL, NULL),
  ('6e24d182-1012-5cd6-94b4-8d4ae8dd6136'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '6e24d182-1012-5cd6-94b4-8d4ae8dd6136'::uuid, 1, NULL, TRUE, 0, NULL, E'Lightning', E'In 2018, a momentous lightning bolt {{1}} above a network of radio telescopes in the Netherlands. The telescopes’ {{2}} recordings, which were processed only recently, {{3}} something no one has seen before: lightning actually starting up inside a thundercloud. Researchers used the observations to settle a long-standing debate about what {{4}} lightning — the first step in the mysterious process by which bolts arise, grow and propagate to the ground.', NULL, NULL, NULL, E'1.flashed, 2.detailed, 3.reveal, 4.triggers', NULL, NULL),
  ('6e28434d-f395-5099-9cbc-c89bee0c53de'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '6e28434d-f395-5099-9cbc-c89bee0c53de'::uuid, 1, NULL, TRUE, 0, NULL, E'Different Bosses', E'Think about all the different bosses you''ve had or heard about. Some are strict and by-the-book, while others are more laid back. Over time, experts in management have come up with several ways to describe these styles. Early on, people thought leaders were just born with certain {{1}} that made them great. Later, the focus shifted to what good leaders do, {{2}} what they are born with. For example, some leaders are really good at giving clear instructions, while others are great at {{3}} their teams to be creative. Then there''s situational leadership, which is all about adapting your style to fit the team''s needs or the task at {{4}} . This approach is like a coach who knows when to push the team hard and when to give a pep talk. Understanding these different styles can help anyone become a better leader, whether you''re running a business, coaching a sports team, or even {{5}} a community event.', NULL, NULL, NULL, E'1.traits, 2.rather than, 3.inspiring, 4.hand, 5.organizing', NULL, NULL),
  ('6e2855b0-f595-5d1e-9777-0e9a1462b73a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6e2855b0-f595-5d1e-9777-0e9a1462b73a'::uuid, 1, NULL, TRUE, 0, NULL, E'Party', E'You are going to have a party with your classmates at home. You will prepare barbecue and salad to treat them, but you do not know their dietary restrictions. You made a phone call to ask them about this, but they did not answer the call. Please leave a message to them.', '58c46fd3-7639-568d-acad-ff7b54a27769'::uuid, NULL, NULL, NULL, NULL, NULL),
  ('6e3c0f31-54d4-5773-9b85-56a1eaf8006a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '6e3c0f31-54d4-5773-9b85-56a1eaf8006a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f2d7ed7e-483c-5164-b1c2-aa66a62af082'::uuid, NULL, NULL, E'The former lecturer often returns as a visitor to the campus.', NULL, NULL),
  ('6e3db4ed-56a9-546b-b8b7-8eb260b3e03f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '6e3db4ed-56a9-546b-b8b7-8eb260b3e03f'::uuid, 1, NULL, TRUE, 0, NULL, E'Choice of Subject', E'Rather than choose a subject that is suitable for future employment possibilities, you should choose a subject that you interested in or could get good grades. Agree or disagree?', NULL, NULL, NULL, NULL, 200, 300),
  ('6e40910b-17ba-5a95-854d-e2bf7938712a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6e40910b-17ba-5a95-854d-e2bf7938712a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'aa39d388-db01-5bbb-b998-f4fc5e82897c'::uuid, NULL, E'The lecture was meant to start at ten.', NULL, NULL, NULL),
  ('6e41c914-05cf-54e6-9919-87e4c48f6473'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '6e41c914-05cf-54e6-9919-87e4c48f6473'::uuid, 1, NULL, TRUE, 0, NULL, E'Namibia Gained Independence', E'When Namibia gained independence in 1990, teenager Pascolena Florry was herding goats in the country dry, desolate northern savannah. Her job, unpaid and dangerous, was to protect her parents'' livestock from preying jackals and leopards. She saw wildlife as the enemy, and many of the other indigenous inhabitants of Namibia''s rural communal lands shared her view. Wildlife poaching was commonplace. Fifteen years later, 31-year-old Pascolena''s life and outlook are very different. She has built a previously undreamed of career in tourism and is the first black Namibian to be appointed manager of a guest lodge. Her village, and hundreds of others, have directly benefited from government efforts to devolve management and tourism development of communal lands to conservancies run by indigenous peoples. "Now we see the wildlife as our way of creating jobs and opportunities as the tourism industry grows," she says. "The future is better with wildlife around, not only for jobs, but also for the environment."', NULL, NULL, E'Although Pascolena Florry and her villagers saw wildlife as enemy when Namibia gained independence because their job at that time was to protect their parents'' livestock, they started to treat wildlife as the ways of creating job opportunities and protection of the environment fifteen years later because they had benefited from the establishment of a tourism career and the government efforts to devolve.', NULL, 5, 75),
  ('6e43737a-ffe5-5f4f-a235-aba47fc435cc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6e43737a-ffe5-5f4f-a235-aba47fc435cc'::uuid, 1, NULL, TRUE, 0, NULL, E'Neuroscience', E'Neuroscience has traditionally been classed as a subdivision of biology. Many researchers say that neuroscience means the same as neurobiology. However, neurobiology looks at the biology of the nervous system, while neuroscience refers to anything to do with the nervous system. Neuroscientists are involved in a much wider scope of fields, who study the evolutionary and medical aspects of the nervous system.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('6e4692a1-0cb6-5632-b295-8b4421ac5f37'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '6e4692a1-0cb6-5632-b295-8b4421ac5f37'::uuid, 1, NULL, TRUE, 0, NULL, E'Urbanization', NULL, NULL, NULL, NULL, E'5, 3, 1, 2, 4', NULL, NULL),
  ('6e487f6d-d6ae-5c8f-9970-e1e4090691f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6e487f6d-d6ae-5c8f-9970-e1e4090691f9'::uuid, 1, NULL, TRUE, 0, NULL, E'Dairy Product', E'You and your family are going to a friend''s house for dinner. You''re worried that your friend may not know that your wife, Lilly, can''t have dairy products, so you decide to call your friend in advance to let them know. What would you say?', '1d2f4d42-97fe-5acc-acb3-e1cbb43ec047'::uuid, NULL, E'Hey Jack, I want to talk to you about something.\nWe seem to have a little issue with the dinner at your house tonight.\nIt''s like my wife Lilly can’t eat any dairy products at all. I’m calling you early just to let you know this dietary restriction before you start cooking.\nAnd I''d like to know what you think.', NULL, NULL, NULL),
  ('6e4fd47e-fe43-5492-b6af-65d36499ae81'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '6e4fd47e-fe43-5492-b6af-65d36499ae81'::uuid, 1, NULL, TRUE, 0, NULL, E'Retirement', E'For a start, we need to change our {{1}} of ''retirement'', and we need to change mindsets arising from earlier government policy which, in the face of high unemployment levels, encouraged mature workers to take early retirement. Today, government encourages them to {{2}} their retirement.\nWe now need to think of retirement as a phased process, where mature age workers {{3}} reduce their hours, and where they have considerable flexibility in how they combine their work and non work time.\nWe also need to recognise the broader change that is occurring in how people work, learn, and live. Increasingly we are moving away from a linear relationship between education, training, work, and retirement, as people move in and out of jobs, careers, caregiving, study, and leisure. Employers of choice remove the {{4}} between the different segments of people''s lives, by creating flexible conditions of work and a range of leave entitlements. They take an individualised approach to workforce planning and development so that the needs of employers and employees can be met {{5}} . This approach supports the different transitions that occur across the life course - for example, school to work, becoming a parent, becoming responsible for the care of older relatives, and moving from work to retirement.', NULL, NULL, NULL, E'1.concept, 2.delay, 3.gradually, 4.barriers, 5.simultaneously', NULL, NULL),
  ('6e5184fd-77b9-5fbf-8b76-8fe344ba1a00'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '6e5184fd-77b9-5fbf-8b76-8fe344ba1a00'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7773f317-6d1c-54b6-81ea-3b4c0f21f04b'::uuid, NULL, NULL, E'We''re not planning to raise our prices at this time.', NULL, NULL),
  ('6e51baaa-94fd-5eee-8398-208975bd086b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6e51baaa-94fd-5eee-8398-208975bd086b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the verb that describes traveling on boat?', 'eb4b5ec5-02d4-56d0-9fd4-ac312c52dce6'::uuid, NULL, NULL, E'Cruise / voyage / sail', NULL, NULL),
