  ('6e54b133-3abc-50d6-ba36-8ff0a4214306'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6e54b133-3abc-50d6-ba36-8ff0a4214306'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3d1f697e-b4c4-50e8-92c1-a0b4b172ea10'::uuid, NULL, E'Diagnosis is not a discrete or limited process.', NULL, NULL, NULL),
  ('6e5547d7-b39c-5592-80b9-827c36ccb902'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6e5547d7-b39c-5592-80b9-827c36ccb902'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd7a6a33a-cd31-518d-9b57-6092acaebe03'::uuid, NULL, E'Increased investment in public transportation can greatly improve urban mobility.', NULL, NULL, NULL),
  ('6e5e24ef-fd2f-5ab1-85ea-543107536c5b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '6e5e24ef-fd2f-5ab1-85ea-543107536c5b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '951fa395-c013-528c-bae4-91ce154da5ed'::uuid, NULL, NULL, E'Urban planning emphasizes the efficiency and expansion of the community.', NULL, NULL),
  ('6e6155ee-c5f3-55fa-9a5b-1b9ad97a6f4c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', '6e6155ee-c5f3-55fa-9a5b-1b9ad97a6f4c'::uuid, 1, NULL, TRUE, 0, NULL, E'MCM-R', E'It should be obvious that cetaceans—whales, porpoises, and dolphins—are mammals. They breathe through lungs, not through gills, and give birth to live young. Their streamlined bodies, the absence of hind legs, and the presence of a fluke1 and blowhole2 cannot disguise their affinities with land dwelling mammals. However, unlike the cases of sea otters and pinnipeds (seals, sea lions, and walruses, whose limbs are functional both on land and at sea), it is not easy to envision what the first whales looked like. Extinct but already fully marine cetaceans are known from the fossil record. How was the gap between a walking mammal and a swimming whale bridged? Missing until recently were fossils clearly intermediate, or transitional, between land mammals and cetaceans.\n\nWhich of the following can be inferred from the paragraph about early sea otters?', NULL, NULL, NULL, E'It is not difficult to imagine what they looked like.\nThey lived in the sea and land.', NULL, NULL),
  ('6e6e8585-75db-5b3a-87d3-d8816a2baba1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '6e6e8585-75db-5b3a-87d3-d8816a2baba1'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9a541a2b-56df-576f-b65b-34999ebc4c4e'::uuid, NULL, NULL, E'Today''s lecture material will be included in the next assessment.', NULL, NULL),
