  ('6e88400d-ebe4-592d-bacd-cacbc7af514b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '6e88400d-ebe4-592d-bacd-cacbc7af514b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9c559b46-ecd8-5f22-93cd-df0bda3de35a'::uuid, NULL, NULL, E'All the student union members can register their names to get that service.', NULL, NULL),
  ('6e8bc10c-9406-5df5-a79f-9e9ebb02b509'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6e8bc10c-9406-5df5-a79f-9e9ebb02b509'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '916ddeb8-16ab-5d12-a5ae-8995b71718ae'::uuid, NULL, E'All course materials will be posted online.', NULL, NULL, NULL),
  ('6e8e2743-6676-5169-8338-8a68404480ed'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '6e8e2743-6676-5169-8338-8a68404480ed'::uuid, 1, NULL, TRUE, 0, NULL, E'Categories of Living Things', E'It was once assumed that all living things could be divided into two fundamental and exhaustive categories. Multicellular plants and animals, as well as many unicellular organisms, are eukaryotic—their large, complex cells have a well-formed nucleus and many organelles. On the other hand, the true bacteria are prokaryotic cells, which are simple and lack a nucleus. The distinction between eukaryotes and bacteria, initially defined in terms of subcellular structures visible with a microscope, was ultimately carried to the molecular level. Here prokaryotic and eukaryotic cells have many features in common. For instance, they translate genetic information into proteins according to the same type of genetic coding. But even where the molecular processes are the same, the details in the two forms are different and characteristic of the respective forms. For example, the amino acid sequences of various enzymes tend to be typically prokaryotic or eukaryotic.\nThe differences between the groups and the similarities within each group made it seem certain to most biologists that the tree of life had only two stems. Moreover, arguments pointing out the extent of both structural and functional differences between eukaryotes and true bacteria convinced many biologists that the precursors of the eukaryotes must have diverged from the common ancestor before the bacteria arose.\nAlthough much of this picture has been sustained by more recent research, it seems fundamentally wrong in one respect. Among the bacteria, there are organisms that are significantly different both from the cells of eukaryotes and from the true bacteria, and it now appears that there are three stems in the tree of life. New techniques for determining the molecular sequence of the RNA of organisms have produced evolutionary information about the degree to which organisms are related, the time since they diverged from a common ancestor, and the reconstruction of ancestral versions of genes. These techniques have strongly suggested that although the true bacteria indeed form a large coherent group, certain other bacteria, the archaebacteria, which are also prokaryotes and which resemble true bacteria, represent a distinct evolutionary branch that far antedates the common ancestor of all true bacteria.', NULL, NULL, E'All living things could be divided into two fundamental and exhaustive categories: eukaryotes and bacteria, whose distinction was ultimately carried to the molecular level, and it was believed that the tree of life had only two stems, but it now appears that there are three stems in the tree of life, when certain other bacteria, the archaebacteria, represent a distinct evolutionary branch that far antedates the common ancestor of all true bacteria.', NULL, 5, 75),
  ('6e965a3c-1c8c-5480-a76e-2a0d3c64fb5b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '6e965a3c-1c8c-5480-a76e-2a0d3c64fb5b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ec0a8c12-a7db-53d3-914e-632e8d876d96'::uuid, NULL, NULL, E'In my opinion, this car should be repaired soon.', NULL, NULL),
