  ('6ee5100c-8e10-55d3-8079-0ec5775495af'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6ee5100c-8e10-55d3-8079-0ec5775495af'::uuid, 1, NULL, TRUE, 0, NULL, E'Racial Politics', E'The racial and identity politics were subtle and complex, but real, and in full operation every day. The target of racial jokes changed erratically, and the cruelty would vary depending on the target''s position in the ''coolness'' hierarchy at school.', NULL, NULL, NULL, NULL, NULL, NULL),
