  ('6f399d61-1a57-5248-92ac-ccff17537722'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '6f399d61-1a57-5248-92ac-ccff17537722'::uuid, 1, NULL, TRUE, 0, NULL, E'Disease', E'If you have a {{1}} disease such as heart disease, diabetes, asthma, or back or joint pain, exercise can have important health {{2}} . However, it''s important to talk to your doctor before starting an exercise {{3}} . He or she might have {{4}} on what exercises are safe and any precautions you might need to take while exercising.', NULL, NULL, NULL, E'1.chronic, 2.benefits, 3.routine, 4.advice', NULL, NULL),
