  ('6f4667d2-92a7-5904-a2df-ba89722910fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6f4667d2-92a7-5904-a2df-ba89722910fd'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'A business doesn''t want to make a loss - what does it want to make?', '12ff78c0-eb99-5dfd-a6ae-808fcc38bdc8'::uuid, NULL, NULL, E'Profit / profits', NULL, NULL),
  ('6f494f19-9a24-591f-b55a-ef29964bcff6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6f494f19-9a24-591f-b55a-ef29964bcff6'::uuid, 1, NULL, TRUE, 0, NULL, E'Underground Microbes', E'Precambrian cratons -- some of Earth''s oldest rocks -- were uninhabitable for microbes for much of their existence, with the longest period of habitability not much beyond a billion years, and many only for the past 50 million to 300 million years, according to a paper correlating Earth''s deep biosphere with geologic history.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('6f5d68bd-410f-5141-b106-604763154460'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '6f5d68bd-410f-5141-b106-604763154460'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8cf1b852-072d-5015-8d15-aace6e0a1ee4'::uuid, NULL, NULL, E'The university has put funds into new technology for educational purposes.', NULL, NULL),
  ('6f611adb-7cc4-5d9d-9c09-be3cea5caf9d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '6f611adb-7cc4-5d9d-9c09-be3cea5caf9d'::uuid, 1, NULL, TRUE, 0, NULL, E'Efficiency', E'How do we measure efficiency? To economists - or to a certain type of economist - it is simply a question of profitability, even when it concerns what most people consider a social provision such as public transport. What is lost when railway lines and bus routes to small, out-of-the-way communities are cut in the name of efficiency? After all, if a line or a route is only used occasionally by a few people,it would be much cheaper to rip up the lines and let everyone use their cars.\nFor many governments, the way to turn inefficient national services into profitable businesses has been to sell off these services - and their responsibilities - to private enterprises. Cost, in terms of profit and loss, is of course an important factor, but other factors need to be considered when dealing with the livelihoods of whole communities, however small. Among these are the social, environmental, human and cultural costs incurred by cutting off more remote communities from greater opportunities, including economic activities that benefit society as a whole.\nTaking away such links - the usual result of privatization - may well lead to economic benefits in the short term, but, as the last twenty to thirty years have shown, also leads to long-term social and cultural damage. Of course, no business with its eye on profits is going to "waste" money supporting underused services. Only large collective bodies such as national and local governments can do that. These services are, after all, a social provision, not businesses.', NULL, NULL, E'The closure or privatization of inefficient national services may have short-term economic benefits, with efficiency measured by profitability, but can cause long-term damage both socially and culturally because some services are social provisions, not businesses.', NULL, 5, 75),
  ('6f64dfb6-d084-59c2-86b5-6cdc4624845d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '6f64dfb6-d084-59c2-86b5-6cdc4624845d'::uuid, 1, NULL, TRUE, 0, NULL, E'Fire Crews', E'Fire crews have worked through the night trying to control a number of bush fires burning in Western Australia''s southwest. The department upgraded the alert level from "watch and act" to "emergency" and advised residents to take necessary steps to ensure their safety. Conditions there have eased overnight and the spread of the blaze has slowed. The firefighting effort will be reassessed at first light.', NULL, NULL, NULL, NULL, NULL, NULL),
