  ('706b92b4-bdb5-5da0-9688-c3cb08e2b5e4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '706b92b4-bdb5-5da0-9688-c3cb08e2b5e4'::uuid, 1, NULL, TRUE, 0, NULL, E'A Charity Event', E'You''re coordinating a charity event for your company, and your team proposes hosting a silent auction to raise funds. However, you realize that organizing the auction might require more resources and time than anticipated. You need to gently guide the discussion towards simpler fundraising ideas. What would you say to your team?', '89fce3ba-0a9f-5080-97e6-f9b7bd835ad8'::uuid, NULL, E'Hey team, I love the idea of a silent auction for our charity event, but let''s consider simpler alternatives that are equally effective. How about organizing a bake sale or a raffle instead? These options require less time and resources to set up but still have the potential to raise significant funds for our cause. Let''s brainstorm some creative ideas that align with our goals and resources.', NULL, NULL, NULL),
  ('706c452c-0b12-5add-9bbe-6eb4dfb5a0c1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '706c452c-0b12-5add-9bbe-6eb4dfb5a0c1'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '28c1eb2d-03c5-51c5-8ff1-d9a7e76e830e'::uuid, NULL, E'Students seeking extensions should approach their respective tutors for permission.', NULL, NULL, NULL),
  ('706d27f8-3b06-5c08-90bc-58dc5fefe0d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '706d27f8-3b06-5c08-90bc-58dc5fefe0d3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c61a172f-5967-5100-90bb-291d8eea9652'::uuid, NULL, NULL, E'The elective course introduces engineering students to construction practices and concepts.', NULL, NULL),
  ('7079726d-b1ad-5ae3-ba39-8065d61abb6d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '7079726d-b1ad-5ae3-ba39-8065d61abb6d'::uuid, 1, NULL, TRUE, 0, NULL, E'Pop Art', E'Pop art was a cultural {{1}} that began in the mid-20th century, {{2}} to everyday life as a source of inspiration. American artists often used {{3}} subjects from their surroundings, such as beer bottles, clothing, comic strips, and advertisements, to create bold and striking artworks. In the United Kingdom, however, pop art drew heavily from {{4}} found in magazines, {{5}} archives and mass media culture. Together, these approaches made pop art one of the most accessible and influential movements in modern art.', NULL, NULL, NULL, E'1.movement, 2.turning, 3.familiar, 4.imagery, 5.as well as', NULL, NULL),
  ('707d88fa-baee-51d9-9b11-eb0a0a67fee6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '707d88fa-baee-51d9-9b11-eb0a0a67fee6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a0b74ec3-0b27-5b33-904c-cdf993db0025'::uuid, NULL, NULL, E'The school has made a promotional video to attract new students.', NULL, NULL),
  ('707f63ce-140f-5e55-9bac-8f668fde50d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '707f63ce-140f-5e55-9bac-8f668fde50d5'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call animals that eat both plants and meat?', 'c879e19b-ab2c-5ede-9368-5a677179bf98'::uuid, NULL, NULL, E'Omnivores', NULL, NULL),
  ('7081f45c-7392-57b0-906e-ca4c55d72226'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7081f45c-7392-57b0-906e-ca4c55d72226'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8e27aa9d-e7ec-53b2-8c2c-a3526d02bea6'::uuid, NULL, NULL, E'There''s some doubt about his suitability for the job.', NULL, NULL),
  ('70838587-4545-5cfe-8e04-4c6214ca70a0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '70838587-4545-5cfe-8e04-4c6214ca70a0'::uuid, 1, NULL, TRUE, 0, NULL, E'Human Remains', E'Human remains are a fundamental part of the archaeological record, offering unique insights into the lives of individuals and populations in the past. Like many archaeological materials, human remains require distinctive and specialized methods of recovery, analysis, and interpretation, while technological innovations and the accumulation of expertise have enabled archaeologists to extract ever greater amounts of information from assemblages of skeletal material. Alongside analyses of new finds, these advances have consistently thrown new light on existing collections of human remains in museums, universities and other institutions. Given the powerful emotional, social and religious meanings attached to the dead body, it is perhaps unsurprising that human remains pose a distinctive set of ethical questions for archaeologists.\nWith the rise of indigenous rights movements and the emergence of post-colonial nations, the acquisition and ownership of human remains became a divisive and politically loaded issue. It became increasingly clear that many human remains in museum collections around the world represented the traces of colonial exploitation and discredited pseudo-scientific theories of race. In the light of these debates and changing attitudes, some human remains were returned or repatriated to their communities of origin, a process which continues to this day. Recently a new set of challenges to the study of human remains has emerged from a rather unexpected direction: the British government revised its interpretation of nineteenth-century burial legislation in a way that would drastically curtail the ability of archaeologists to study human remains of any age excavated in England and Wales. This paper examines these extraordinary events and the legal, political and ethical questions that they raise.', NULL, NULL, E'Human remains are a fundamental part of the archaeological record, offering unique insights into the lives of individuals and populations in the past, which require distinctive and specialized methods of recovery, and pose a distinctive set of ethical questions for archaeologists, but the acquisition and ownership of human remains became a divisive and politically loaded issue, since many human remains in museum collections around the world represented the traces of colonial exploitation.', NULL, 5, 75),
  ('7083b2df-814b-52b8-8524-e7c6020cb374'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7083b2df-814b-52b8-8524-e7c6020cb374'::uuid, 1, NULL, TRUE, 0, NULL, E'MBA Students', E'Along with customary classes on subjects such as finance, accounting, and marketing, today''s MBA students are enrolling on courses for environmental policy and stewardship. Indeed, more than half of business schools require a course in environmental sustainability or corporate social responsibility, according to a survey of 91 US business schools, published in October 2005.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('7084f834-15bb-5a70-b002-917e469bbf67'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '7084f834-15bb-5a70-b002-917e469bbf67'::uuid, 1, NULL, TRUE, 0, NULL, E'Productivity', E'Technology and flexible work {{1}} have had a significant impact on today''s busy companies. In terms of productivity, it seems the {{2}} has shifted from managing employees in the workplace to monitoring their total {{3}} no matter where they choose to work. Whether this trend will continue depends to some {{4}} on how well it works for everyone concerned.', NULL, NULL, NULL, E'1.practices, 2.focus, 3.output, 4.extent', NULL, NULL),
