  ('709683f1-8b94-58ef-8a23-7ebdd3361597'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '709683f1-8b94-58ef-8a23-7ebdd3361597'::uuid, 1, NULL, TRUE, 0, NULL, E'London Zoo', E'It was a busy old time at London Zoo this week, reports the Daily Mail, where over 19,000 animals were having their annual weight and height {{1}} . Some creatures, such as rhinos, tigers, and okapis, had to be {{2}} on to specially constructed larger scales. The statistics are shared with other zoos across the world to allow keepers to compare information about {{3}} species. The zoological manager named Mark Habben said: "We have to know the vital {{4}} of each animal at the zoo, however big or small."', NULL, NULL, NULL, E'1.checked, 2.coaxed, 3.endangered, 4.statistics', NULL, NULL),
  ('7096b751-8f75-5d09-9ff4-efdd425054c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7096b751-8f75-5d09-9ff4-efdd425054c6'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call the female partner in a marriage?', '639064de-3c75-54e9-a756-eb0dab273a47'::uuid, NULL, NULL, E'Wife', NULL, NULL),
  ('70978e00-7494-5491-826f-f01e2cbcabc8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '70978e00-7494-5491-826f-f01e2cbcabc8'::uuid, 1, NULL, TRUE, 0, NULL, E'Fine Arts', E'The Department of Fine Arts is a vibrant department comprising active art professionals housed in a modern, well-equipped facility. The faculty enjoys {{1}} relationships with local museums, numerous galleries and a variety of other art organizations. Fine Arts students benefit from studying with artistically {{2}} mentors who exhibit and research regionally, nationally and internationally. The department provides students with many opportunities for artistic and personal {{3}} through daily contact with full-time faculty members who are noted artists and researchers. Classes are small to allow for personalised feedback and guidance. Well-appointed studios on campus {{4}} the daily practice of art in combination with the study of liberal arts. During their studies, students gain exposure to world-class visiting artists and exhibitions, and also have local and international travel opportunities.', NULL, NULL, NULL, E'1.collaborative, 2.active, 3.growth, 4.facilitate', NULL, NULL),
  ('70afd3be-fc24-5de4-9b9a-a690f152c2da'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '70afd3be-fc24-5de4-9b9a-a690f152c2da'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '57fdcdbe-03fe-51ed-aa2a-804a999ce221'::uuid, NULL, E'Could you pass the material to students that are in your row?', NULL, NULL, NULL),
  ('70b06393-662c-514a-985c-3a9f07a92b42'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '70b06393-662c-514a-985c-3a9f07a92b42'::uuid, 1, NULL, TRUE, 0, NULL, E'Crustaceans'' Pain', E'The last time you {{1}} on a live lobster for dinner, you might not have given any thought to how much the little guy was going to suffer as he boiled to death. Until recently many researchers {{2}} the crustacean nervous system too primitive to process pain. But scientists at Queen''s University in Belfast now think that crustaceans may be more sensitive to pain than {{3}} thought.\nThe researchers used crabs as their test animals. And they found that crabs that {{4}} an electric shock when they hid under a safe, dark rock would {{5}} learn to avoid the hiding place. And that avoidance is key: the animals'' ability to remember the unpleasant shock and avoid it is consistent with the ability to feel and remember pain. If the behavior was merely a reflex, the critters would continue to visit the shelter.\nThe study is in the Journal of Experimental Biology. [Also see Nicola Stead, Painful Feelings in Crabs]\nThe situation is likely the same with lobsters. So before you break out the bibs and melted butter, it might be nice to put your future dinner on a little anesthetic ice.', NULL, NULL, NULL, E'1.splurged, 2.believed, 3.previously, 4.experienced, 5.eventually', NULL, NULL),
  ('70b5f885-b998-5f17-a14e-d7bc14d0d612'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '70b5f885-b998-5f17-a14e-d7bc14d0d612'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '19f215c7-a053-51a8-ad23-24648cfc086f'::uuid, NULL, NULL, E'They walked along the road in the moonlight.', NULL, NULL),
  ('70ba342d-a1fd-5a49-80dc-c249e9081983'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '70ba342d-a1fd-5a49-80dc-c249e9081983'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f457f76e-113c-5077-a351-69fb91541706'::uuid, NULL, NULL, E'Sydney is renowned as Australia''s bustling cultural hub and port.', NULL, NULL),
  ('70c369f7-3574-5914-ae7c-228bbdc6fbb4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '70c369f7-3574-5914-ae7c-228bbdc6fbb4'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term used for a person who cannot read or write?', '5061e3d9-d2ec-5af5-b686-538d614e4d21'::uuid, NULL, NULL, E'illiterate / illiteracy', NULL, NULL),
  ('70ce41e6-056e-59fb-9240-0c740b1f12e5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '70ce41e6-056e-59fb-9240-0c740b1f12e5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ae22fe74-f894-5e22-97b9-d1a9a11aca04'::uuid, NULL, NULL, E'She tried to lighten up her speech with a few jokes.', NULL, NULL),
  ('70d358a5-e189-5db0-b63e-8a6c435a944b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', '70d358a5-e189-5db0-b63e-8a6c435a944b'::uuid, 1, NULL, TRUE, 0, NULL, E'Skin Cancer', E'Research by the Oregon State University College of Pharmacy suggests that a vaccine stimulating production of a protein critical to the skin''s antioxidant network could help people bolster their defenses against skin cancer.\nUltraviolet radiation from the sun leads to oxidative stress, which increases the risk of skin cancers such as melanoma, explains Arup Indra, professor of pharmaceutical sciences at OSU and the study''s leader.\nA messenger RNA vaccine, like the Moderna and Pfizer vaccines for COVID-19, that promoted production of the protein, TR1, in skin cells could mitigate the risk of UV-induced cancers and other skin problems, he said.\nFindings of the research, in which Arup and collaborators used a mouse model to probe TR1''s role in skin cells'' health and stability, were published in the Journal of Investigative Dermatology.\nSkin cancer is the most common cancer in the United States, according to the Centers for Disease Control and Prevention. Melanoma, the most lethal type of skin cancer, is a form in which malignant cells form in skin cells known as melanocytes; melanocytes produce the pigment melanin, which determines skin color.\nMost cases of skin cancer, the CDC says, are linked to UV radiation exposure. People become tan from exposure to the sun or tanning beds because producing melanin is the body''s way of trying to protect the skin from burning.\n\nWhich of the following statements are incorrect?', NULL, NULL, NULL, E'Skin cancer is the most common cancer in the United States, and Melanoma is the least deadly form of skin cancer.\nUltraviolet radiation from the sun certainly causes skin cancer.', NULL, NULL),
  ('70dbe02d-93bc-53b7-a800-e59382301073'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '70dbe02d-93bc-53b7-a800-e59382301073'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which kind of book can we find Africa maps?', 'b25eda53-50ec-569e-8db7-22cf1b17079c'::uuid, NULL, NULL, E'Atlas', NULL, NULL),
  ('70e07d34-2f36-5d04-a5d4-4ef36457e2ec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '70e07d34-2f36-5d04-a5d4-4ef36457e2ec'::uuid, 1, NULL, TRUE, 0, NULL, E'Telescope', E'On a starry night in Padua 400 years ago, Galileo first turned a telescope toward the sky. It might seem the most natural of actions—after all, what else does one do with a telescope? But in 1609, the instrument, which had been invented only the year before by Dutch opticians, was known as a "spyglass", in anticipation of its military uses. The device was also sold as a toy. When Galileo read of it, he quickly set about making a much more powerful version. The Dutch telescopes magnified images by 3 times; Galileo''s telescopes magnified them by 8 to 30 times.\nAt the time, astronomy, like much of science, remained under the spell of Aristotle. Almost 2,000 years after his death, the giant of Greek philosophy was held in such high regard that even his most suspect pronouncements were considered unimpeachable. Aristotle had maintained that all celestial objects were perfect and immutable spheres, and that the stars made a dizzying daily journey around the center of the universe, our stationary Earth. Why scrutinize the sky? The system had already been neatly laid out in books. Astronomers "wish never to raise their eyes from those pages", Galileo wrote in frustration, "as if this great book of the universe had been written to be read by nobody but Aristotle, and his eyes had been destined to see for all posterity."\nIn Galileo''s day, the study of astronomy was used to maintain and reform the calendar. Sufficiently advanced students of astronomy made horoscopes; the alignment of the stars was believed to influence everything from politics to health.', NULL, NULL, E'On a starry night in Padua 400 years ago, Galileo first turned a telescope toward the sky, and when Galileo read of it, he quickly set about making a much more powerful version, but astronomy, like much of science, remained under the spell of Aristotle, so astronomers wish never to raise their eyes from those pages, for the alignment of the stars was believed to influence everything from politics to health.', NULL, 5, 75),
  ('70e2c58e-f87e-5799-8281-6be9f5900381'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '70e2c58e-f87e-5799-8281-6be9f5900381'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd7558798-5fc1-58c1-96d4-dfc418d09b67'::uuid, NULL, NULL, E'The instructor of the class used to be an experienced teacher.', NULL, NULL),
  ('70e57bdc-31b3-5ce2-a65a-5ccb16f3c9fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '70e57bdc-31b3-5ce2-a65a-5ccb16f3c9fb'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1ca0b586-2c0b-56e8-afc7-f4a42873c088'::uuid, NULL, NULL, E'The aerial photographs were promptly registered for thorough evaluation.', NULL, NULL),
  ('70e631f9-5f98-5b4c-a3af-eff6ba1f7448'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'HIGHLIGHT_CORRECT_SUMMARY', E'HIGHLIGHT_CORRECT_SUMMARY', E'LISTENING', E'SHARED', NULL, E'APPROVED', '70e631f9-5f98-5b4c-a3af-eff6ba1f7448'::uuid, 1, NULL, TRUE, 0, NULL, E'Ugly Building', E'It seems to me that architecture is pretty much something that causes us both pleasure and trouble. I live in the part of western London where I think many of the streets are really really ugly, and this distresses me every time when I walk to a supermarket or walk to the tube. I do not understand why they built those buildings without architecture. A bad building has a serious impact on the people around it, which could be hundreds of years. It lasted so long, and if you write a bad book or a bad play, I will be shocked when it was shown. Suppose the book arose a little bit from the frustration, and then I realize if you talk about architecture, you will say why building are not more beautiful. Then you will say I can use such work as "beauty", which is a really arrogant word. And no one knows what beautiful is. It''s all in the eye of the beholder. I couldn''t help but think about that actually. Well, you know that we all attempt to agree that Rome is nice than Milkykings, and San Francisco has the edge of Frankfurt, so we can make that sort of generalization. Surely they are something we can say about why a building works or why it doesn''t. So the books really attempt to suggest why architecture works when it does and what might go wrong when it doesn''t work.\n\nClick on the paragraph that best relates to the recording.', 'cc8ba725-500a-51b0-8d9c-752962a42c21'::uuid, NULL, NULL, E'Ugly buildings can impact people who live around them, even for hundreds of year. Beautiful is a very hard thing to define, as no one really knows what beautiful is.', NULL, NULL),
  ('70faa24a-5e37-53a3-aa50-9e1f4435921c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '70faa24a-5e37-53a3-aa50-9e1f4435921c'::uuid, 1, NULL, TRUE, 0, NULL, E'Ecofuels', E'Fast growth in both world energy demand and carbon dioxide emissions due to fossil fuels has resulted in search for alternative sources which are not only renewable but also environment friendly. One of these alternative source is ecofuels which are solid, liquid, or gaseous fuels primarily produced from biomass. The solid ecofuels include wood, animal dung, municipal waste, and energy crops.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('70ffc816-895c-5034-8c75-cdf5f35e12b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '70ffc816-895c-5034-8c75-cdf5f35e12b2'::uuid, 1, NULL, TRUE, 0, NULL, E'Loud Music', E'Your neighbor has been playing loud music late at night, making it difficult for you to sleep. You want to address the situation diplomatically to maintain a good relationship with your neighbor while ensuring the noise is reduced during late hours. What would you say to your neighbor?', 'a480b6fa-8a4d-5c2e-b382-6065506c1d51'::uuid, NULL, E'Hello, I hope you''re doing well. But I wanted to chat about something that''s been a bit tricky for me. I''ve noticed the music can get pretty loud at night. I totally get the need to unwind and enjoy your tunes, but it''s been tough for me to get some rest. Would you mind turning it down a bit after 10 PM? I''d really appreciate it, and it would help me out a lot.', NULL, NULL, NULL),
  ('71018514-60d0-5b06-85a4-2f867e9a205b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '71018514-60d0-5b06-85a4-2f867e9a205b'::uuid, 1, NULL, TRUE, 0, NULL, E'Water Cycle', NULL, NULL, NULL, NULL, E'4, 2, 1, 3', NULL, NULL),
