  ('7106edce-31f8-5765-a0ef-c29d3b52e5b1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7106edce-31f8-5765-a0ef-c29d3b52e5b1'::uuid, 1, NULL, TRUE, 0, NULL, E'Blue Whale', E'Blue whales are the largest living mammals. Though reports of maximum length and weight vary from one account to another, Antarctic blue whales are known to have reached lengths to 100 feet and weights of over 150 tons before stocks were severely depleted by whaling operations. North Atlantic blue whales may be expected to reach lengths of 80-85 feet.', NULL, NULL, NULL, NULL, NULL, NULL),
