  ('71945160-156a-5740-97e7-564c3552f0b5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '71945160-156a-5740-97e7-564c3552f0b5'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f58b2d83-0e28-5cfe-bbc1-7478450c6818'::uuid, NULL, E'We offer a broad range of undergraduate and postgraduate courses.', NULL, NULL, NULL),
  ('719738de-533e-590e-81bd-8d2ebee276cf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '719738de-533e-590e-81bd-8d2ebee276cf'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd7e2ff07-9bf3-5db3-99bc-d9a3fdfd1d29'::uuid, NULL, NULL, E'Universities should invest in new technologies designed for learning.', NULL, NULL),
  ('719a480a-9f18-5964-9838-6f12178ea4bf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '719a480a-9f18-5964-9838-6f12178ea4bf'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2d9c5655-4dc3-5538-8d70-67732586608a'::uuid, NULL, NULL, E'The new media have transcended traditional national boundaries.', NULL, NULL),
  ('719b0504-f895-58b2-93e9-5e5548f0315c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '719b0504-f895-58b2-93e9-5e5548f0315c'::uuid, 1, NULL, TRUE, 0, NULL, E'The History of the Khoikhoi', E'In around 2300 BP (Before Present), hunter gatherers called the San acquired domestic stock in what is now modern day Botswana. Their population grew, and spread throughout the Western half of South Africa. They were the first pastoralists in southern Africa, and called themselves Khoikhoi (or Khoe), which means ''men of men'' or ''the real people''. This name was chosen to show pride in their past and culture. The Khoikhoi brought a new way of life to South Africa and to the San, who were hunter gatherers as opposed to herders. This led to misunderstandings and subsequent conflict between the two groups.\nThe Khoikhoi were the first native people to come into contact with the Dutch settlers in the mid-17th century. As the Dutch took over land for farms, the Khoikhoi were dispossessed, exterminated, or enslaved and therefore their numbers dwindled. The Khoikhoi were called the ''Hottentots'' by European settlers because the sound of their language was so different from any European language, and they could not pronounce many of the words and sounds.', NULL, NULL, E'In around 2300 BP, hunter gatherers called the San acquired domestic stock in what is now modern day Botswana, who were the first pastoralists in southern Africa and brought a new way of life to South Africa and to the San, which led to misunderstandings and subsequent conflict between the two groups, so as the Dutch took over land for farms, the Khoikhoi were dispossessed, exterminated, or enslaved and therefore their numbers dwindled.', NULL, 5, 75),
  ('719c214f-44b1-5b8b-858e-bfc23c985bd7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '719c214f-44b1-5b8b-858e-bfc23c985bd7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6c3bde94-9d5c-595a-8e02-645e989bc9b3'::uuid, NULL, NULL, E'Securing enough money is often the toughest part of graduate research.', NULL, NULL),
  ('719e7494-43d6-522c-a434-dd8bd7f3f9fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '719e7494-43d6-522c-a434-dd8bd7f3f9fb'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c21bcd34-d8d0-519d-a8d0-54a8b6138f31'::uuid, NULL, NULL, E'Business people sometimes split costs with each other for things.', NULL, NULL),
  ('719f8034-8874-512b-bedd-73156a769598'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '719f8034-8874-512b-bedd-73156a769598'::uuid, 1, NULL, TRUE, 0, NULL, E'Video Games', E'A study of nearly 2,000 children found that those who reported playing video games for three hours per day or more performed better on cognitive skills tests involving impulse control and working memory compared to children who had never played video games.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('719fee47-6eb4-5672-bfe0-ab72c67007ff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '719fee47-6eb4-5672-bfe0-ab72c67007ff'::uuid, 1, NULL, TRUE, 0, NULL, E'Solar System', E'The Sun is the hub of a huge rotating system consisting of nine planets, their satellites, and numerous small bodies, including asteroids, comets, and meteoroids. An estimated 99.85 percent of the mass of our solar system is contained within the Sun, while the planets collectively make up most of the remaining 0.15 percent. The planets, in order of their distance from the Sun, are Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune, and Pluto. Under the control of the Sun''s gravitational force, each planet maintains an elliptical orbit and all of them travel in the same direction. The planets in our solar system fall into two groups: the terrestrial (Earth-like) planets (Mercury, Venus, Earth, and Mars) and the Jovian (Jupiter-like) planets (Jupiter, Saturn, Uranus, and Neptune). Pluto is not included in either category, because its great distance from Earth and its small size make this planet''s true nature a mystery. The most obvious difference between the terrestrial and the Jovian planets is their size. The largest terrestrial planet, Earth has a diameter only one quarter as great as the diameter of the smallest Jovian planet, Neptune, and its mass is only one seventeenth as great. Hence, the Jovian planets are often called giants. Also, because of their relative locations, the four Jovian planets are known as the outer planets, while the terrestrial planets are known as the inner planets. There appears to be a correlation between the positions of these planets and their sizes.\n\nAccording to the passage, each of the following statements comparing terrestrial planets with Jovian planets is true EXCEPT:', NULL, NULL, NULL, E'Terrestrial planets travel in a different direction than Jovian planets do.', NULL, NULL),
  ('71a37def-7d03-5a09-a1c4-522517559393'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '71a37def-7d03-5a09-a1c4-522517559393'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c3ff79e9-73ce-5d49-bed5-11671e9c4a8a'::uuid, NULL, NULL, E'At this stage, the financial situation is rather promising.', NULL, NULL),
  ('71b12792-f362-55c1-9844-a697bb1f1173'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '71b12792-f362-55c1-9844-a697bb1f1173'::uuid, 1, NULL, TRUE, 0, NULL, E'A Book', E'So, as much as this is a book about the experience of traveling – the contemplation of cities that are vast in scale and villages that are as remote and strange as anything Westerners are ever likely to encounter – it is also a book that tries to describe another kind of journey.', NULL, NULL, NULL, NULL, NULL, NULL),
