  ('71b5a4cd-642c-5d0d-aeea-78f160f6c912'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '71b5a4cd-642c-5d0d-aeea-78f160f6c912'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e41a4d5e-c166-5795-9ac3-0beac4a9ec2a'::uuid, NULL, NULL, E'A child''s age on admission to school may vary in different areas.', NULL, NULL),
  ('71b5c82d-f324-5610-bbd4-603cb9b2d5d2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '71b5c82d-f324-5610-bbd4-603cb9b2d5d2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1223ba53-97d1-5bae-aff6-e135b98ca7fe'::uuid, NULL, NULL, E'Updates to the course reflect recent changes in the field.', NULL, NULL),
  ('71b643a1-c8a6-5238-be04-d6f3b4780c2a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '71b643a1-c8a6-5238-be04-d6f3b4780c2a'::uuid, 1, NULL, TRUE, 0, NULL, E'Amphibians', E'Whether salamander, frog or toad, amphibians are some of the most diverse and far-flung animals on the planet. However, they''re disappearing, and experts are worried since frogs are considered bellwethers for the environment. Their double life makes them unique. It''s through their skin that they breathe and drink water because their skin is so permeable.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('71bd74b0-4c64-597c-85fb-0c194f53f85f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '71bd74b0-4c64-597c-85fb-0c194f53f85f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '494aea8d-797c-5a08-b204-88e82486130a'::uuid, NULL, NULL, E'Writing a history book entails a lot of work.', NULL, NULL),
  ('71be4fdc-614d-5b06-bbf9-c4c1fabd8313'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '71be4fdc-614d-5b06-bbf9-c4c1fabd8313'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How many months are there in a year?', '70d939ce-8f36-5a01-ba0a-829f80bc7e91'::uuid, NULL, NULL, E'Twelve', NULL, NULL),
  ('71be61eb-0748-56ab-977e-ff1e73898cae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '71be61eb-0748-56ab-977e-ff1e73898cae'::uuid, 1, NULL, TRUE, 0, NULL, E'Olympic Torch', E'The Olympic torch relay represents an iconic beginning to the games. Former Olympians and members of the public carry the Olympic flame from Athens all the way to the opening ceremony, signifying the official commencement of the games.\nCreating a unique, functional torch is a massive undertaking. Identical torches must be manufactured for each runner in the relay before the initial lighting of the Olympic flame in Greece. The entire process of designing, modeling, prototyping, testing, and manufacturing actually begins years before the games themselves begin.\nThe fundamental elements of an Olympic torch are simple. It must contain a fuel canister and discharge system to support the burning of the flame; the Olympic flame must be clearly visible while burning and resistant to being extinguished under extreme conditions; and it must be a manageable weight and shaped in a way that is easy to hold. Beyond that, the unique design for a particular host city is left up to the organizing committee.\nEach torch is designed with the host country in mind. In the case of the Tokyo 2020 torch, designer Tokujin Yoshioka was inspired by the traditional flower of Japan, which is the cherry blossom. Yoshioka also shaped the torch out of aluminum recycled from the temporary housing constructed in the wake of the Great East Japan earthquake and tsunami in 2011, according to the Tokyo organizing committee. Approximately 30 percent of each individual torch contains this recycled aluminum.', NULL, NULL, NULL, NULL, 5, 75),
  ('71bf1e7d-6cd7-5f23-8cea-9de6b0a3d3ba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '71bf1e7d-6cd7-5f23-8cea-9de6b0a3d3ba'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'df0268da-652c-5df0-88d3-aad756eeacdb'::uuid, NULL, E'This course will examine some of the profound ethical dilemmas.', NULL, NULL, NULL),
  ('71bf27a5-9a90-5dc4-a0a1-4f5c24d9fee6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '71bf27a5-9a90-5dc4-a0a1-4f5c24d9fee6'::uuid, 1, NULL, TRUE, 0, NULL, E'Race and Education', NULL, NULL, NULL, NULL, E'3, 2, 1, 4', NULL, NULL),
  ('71bfa5b1-55fe-5806-b599-b9f586b836fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '71bfa5b1-55fe-5806-b599-b9f586b836fe'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the two-wheeled vehicle that is powered by a motor?', 'fa885291-dc44-5752-a5c9-adb177337125'::uuid, NULL, NULL, E'Motorcycle / motorbike', NULL, NULL),
  ('71c0c887-1d21-5233-a8bb-f7906e53a036'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '71c0c887-1d21-5233-a8bb-f7906e53a036'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-R', E'Recently some scientists have concluded that meteorites found on Earth and long believed to have a Martian origin might actually have been blasted free of Mars''s gravity by the impact on Mars of other meteorites. This conclusion has led to another question: whether meteorite impacts on Earth have similarly driven rocks from this planet to Mars.According to astronomer S. A. Phinney, kicking a rock hard enough to free it from Earth''s gravity would require a meteorite capable of making a crater more than 60 miles across. Moreover, even if Earth rocks were freed by meteorite impact, Mars''s orbit is much larger than Earth''s, so Phinney estimates that the probability of these rocks hitting Mars is about one-tenth as great as that of Mars''s rocks hitting Earth. To demonstrate this estimate, Phinney used a computer to calculate where 1,000 hypothetical particles would go if ejected from Earth in random directions. He found that 17 of the 1,000 particles would hit Mars.\n\nThe passage is primarily concerned with', NULL, NULL, NULL, E'suggesting an answer to a theoretical question', NULL, NULL),
  ('71c0ccb9-2860-56b7-81ab-9d934bf806c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '71c0ccb9-2860-56b7-81ab-9d934bf806c4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a45a4c21-2a00-568d-8001-a7cc3c618239'::uuid, NULL, NULL, E'She doesn''t even care about anything but what is honest and true.', NULL, NULL),
  ('71c4d2f1-9b82-56df-9c19-4d5e658951cf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '71c4d2f1-9b82-56df-9c19-4d5e658951cf'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f080de17-ca10-5c60-905b-437513c6886d'::uuid, NULL, NULL, E'Our scientists diligently study various weather types for research purposes.', NULL, NULL),
  ('71c561b2-3d3d-528b-9733-0cd763cc7911'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '71c561b2-3d3d-528b-9733-0cd763cc7911'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7a8d3625-27c9-5bef-89a4-05cd08f383b5'::uuid, NULL, NULL, E'This course aims to develop your knowledge of statistics.', NULL, NULL),
  ('71cba78e-75ef-57df-83e8-b7018e3c87a5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '71cba78e-75ef-57df-83e8-b7018e3c87a5'::uuid, 1, NULL, TRUE, 0, NULL, E'Polar Bears', E'Polar bears are a powerful symbol of the strength and {{1}} of the Arctic. Their Latin name, Ursus maritimus, means "sea bear." It''s an {{2}} name for this majestic species, which spends much of its life in, around, or on the ocean. They have a thick layer of body fat and a water-repellent coat that {{3}} them from the cold air and water.', NULL, NULL, NULL, E'1.endurance, 2.apt, 3.insulates', NULL, NULL),
  ('71d459e6-79b5-53e3-ad46-77130978906d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '71d459e6-79b5-53e3-ad46-77130978906d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '47f031ea-75bc-538c-afca-6a0a48de6f4b'::uuid, NULL, NULL, E'Before architecture was invented, humans lived in underground houses.', NULL, NULL),
  ('71d51657-6749-50f5-8b10-23ea907d6cd9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '71d51657-6749-50f5-8b10-23ea907d6cd9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '293e2539-d6e1-5d7d-b1f4-3a49723379f3'::uuid, NULL, E'Social media has changed the way we communicate and connect with others.', NULL, NULL, NULL),
  ('71d5d2ac-5c13-5e43-904b-17cd668c07d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '71d5d2ac-5c13-5e43-904b-17cd668c07d3'::uuid, 1, NULL, TRUE, 0, NULL, E'Carotenemia', E'If your skin begins turning orange, you may feel like the star of a sci-fi flick, but there''s most likely a more down-to-earth explanation. Carrots, cantaloupe and other soil-grown foods are chock-full of beta-carotene, and when eaten in abundance they can sometimes cause people to develop an orange skin tone. The orange and red pigments in apricots, mangoes, oranges, pumpkin, squash, sweet potatoes and similar products create an excessive amount of beta-carotene in the bloodstream, which in turn builds up in the areas of the body with thicker skin — hands, knees, elbows, feet and the folds around the nose — and exhibits a titian hue. This is so-called carotenemia. The condition is more visible on those who have light skin, but people of any skin color can be affected.\nCarotenemia isn''t terribly common, even for people who are fruit and vegetable enthusiasts. It''s usually the result of a restricted diet that includes large quantities of a specific fruit or vegetable that is high in red, orange and yellow pigment; this pigment also is known as beta-carotene. While orange, yellow and red fruits and veggies are the primary source of carotenosis, it also can be caused by other colors of foods such as cabbage, spinach, kiwi, asparagus and apples. So, if you''re looking for a healthy glow, keep eating those fruits and veggies — as long as there is a variety of them.', NULL, NULL, NULL, NULL, 5, 75),
  ('71e0c193-8557-5883-bbb2-91bbf34c6b99'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '71e0c193-8557-5883-bbb2-91bbf34c6b99'::uuid, 1, NULL, TRUE, 0, NULL, E'Animal Behavior', NULL, '1e9793b4-3ceb-573f-9f90-d11cf28168ed'::uuid, NULL, E'We can ask 2 fundamental questions about animal behavior they referred to as proximate and ultimate. Proximate questions are those concerned with the mechanisms that bring about behavior. Ultimate questions are those concerned with the evolution of behavior. We can divide the proximate and ultimate into 2 sub-questions. For proximate, how does behavior develop and secondly what causes the behavior. For ultimate, you can ask how did the behavior evolve and secondly what is the adaptive of significance of the behavior. What’s its purpose? Together these comprise what are called Tinbergen’s 4 questions about animal behavior. Niko Tinbergen was one of the founding fathers of the study of the animal behaviors. These questions represent different ways of studying animal behavior and understanding the difference between those 4 questions are fundamental to understanding behavior and indeed the whole of biology. How do we study animal behavior? Well that depends on the type of question we’re hoping to answer.', NULL, NULL, NULL),
  ('71e1b29a-b96c-55bd-bce1-1873687980a5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '71e1b29a-b96c-55bd-bce1-1873687980a5'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person who attacks and robs ships at sea?', 'c5cfd370-d143-5822-83ad-ace21a60117b'::uuid, NULL, NULL, E'Pirate', NULL, NULL),
  ('71e3015a-3eda-5b15-b5e0-393d10d35667'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '71e3015a-3eda-5b15-b5e0-393d10d35667'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the study of designing buildings?', '8767ee13-5971-56ad-ab9f-a064e090b06f'::uuid, NULL, NULL, E'Architecture', NULL, NULL),
  ('71e529f5-b431-5145-86fa-63cf26499e8b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '71e529f5-b431-5145-86fa-63cf26499e8b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f00f02ce-96e8-5526-8ed5-ca1cb773722d'::uuid, NULL, E'A public relations exercise improves the relationship between the public and an organization.', NULL, NULL, NULL),
  ('71e8ace5-8d9e-5dc5-a313-952b5305fe31'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '71e8ace5-8d9e-5dc5-a313-952b5305fe31'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7502145f-c59d-573f-8606-63c32d7f0cd5'::uuid, NULL, E'Diagnosis is not a single event, but an evolving process.', NULL, NULL, NULL),
  ('71e93389-65b3-5119-a010-5b26e5ad1eba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '71e93389-65b3-5119-a010-5b26e5ad1eba'::uuid, 1, NULL, TRUE, 0, NULL, E'Voting', E'When it comes to {{1}} , sometimes we vote with our heads and sometimes with our hearts. But scientists at {{2}} say we might also be voting with our pompoms. Because they''ve found that our behavior at the polls is influenced by the results of local {{3}} events, work published in the Proceedings of the National Academy of Sciences.\nHumans are emotional {{4}} . And our strong feelings about one thing can spread to another. So the Stanford scientists wondered whether events that are unrelated to government performance might sway the way people feel about their elected officials. And what could be less {{5}} to the workings in Washington or your state capital than college football?\nThe researchers looked at the election results from 20 years'' worth of {{6}} , senatorial and gubernatorial races. And they found that a {{7}} win before the election gave the incumbent a boost of almost two percentage points. The more beloved the team, the bigger the bounce.\nAnd it''s not just football. In a separate survey, the scientists found that NCAA college basketball results affected presidential approval ratings. So next election day, you might think about practicing a little separation of stadium and state.', NULL, NULL, NULL, E'1.elections, 2.Stanford, 3.sporting, 4.creatures, 5.relevant, 6.presidential, 7.home-team', NULL, NULL),
  ('71efceee-ab14-593d-9cda-81361583d8c1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '71efceee-ab14-593d-9cda-81361583d8c1'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c861d551-7c72-5404-8e36-876b4f151c74'::uuid, NULL, NULL, E'Optional tutorials are offered in the final week of a term.', NULL, NULL),
  ('71f28f86-311f-5193-88ed-f09496579106'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '71f28f86-311f-5193-88ed-f09496579106'::uuid, 1, NULL, TRUE, 0, NULL, E'Papal Reform', E'Since the last papal reform, several {{1}} have been offered to make the Western calendar more useful or {{2}} . Very few reforms, such as the rather different decimal French Republican and Soviet calendars, had gained official {{3}} but each was put out of use shortly after its introduction.', NULL, NULL, NULL, E'1.proposals, 2.regular, 3.acceptance', NULL, NULL),
  ('71f3045c-32dd-5280-b032-9ddc820aba59'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '71f3045c-32dd-5280-b032-9ddc820aba59'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which one is past tense: has gone, went or going?', '498d326d-d109-5d4f-a2f5-fa28cceff011'::uuid, NULL, NULL, E'went', NULL, NULL),
  ('71f55af6-b3e3-5452-b36f-578d92a4d05f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '71f55af6-b3e3-5452-b36f-578d92a4d05f'::uuid, 1, NULL, TRUE, 0, NULL, E'Nature', E'The sun dipped below the horizon, casting a warm golden glow over the tranquil meadow. The gentle breeze whispered through the tall grass, creating a soothing melody. The scent of wildflowers filled the air, as butterflies danced from petal to petal. Birds chirped their evening lullabies, while a stream trickled nearby.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('71f72a13-ac2c-50d7-8cd3-e8d2e7273cce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '71f72a13-ac2c-50d7-8cd3-e8d2e7273cce'::uuid, 1, NULL, TRUE, 0, NULL, E'Daniel Harris', E'Daniel Harris, a scholar of consumption and style, has observed that until photography finally {{1}} illustration as the "primary means of advertising clothing" in the 1950s, glamour inhered {{2}} in the face of the drawing, which was by necessity schematic and generalized, than in the sketch''s attitude, posture, and gestures, especially in the strangely dainty positions of the hands. Glamour once resided so emphatically in the stance of the {{3}} that the faces in the {{4}} cannot really be said to have {{5}} at all, but angles or tilts. The chin raised upwards in a haughty look; the eyes lowered in an attitude of introspection; the head cocked at an inquisitive or coquettish angle; or the profile presented in sharp outline, emanating power of the severity like an emperor''s bust {{6}} on a Roman {{7}} .', NULL, NULL, NULL, E'1.supplanted, 2.less, 3.model, 4.illustrations, 5.expressions, 6.embossed, 7.coin', NULL, NULL),
  ('71f77af3-8d35-5964-af3d-91c264dc9aa1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '71f77af3-8d35-5964-af3d-91c264dc9aa1'::uuid, 1, NULL, TRUE, 0, NULL, E'Habituation', NULL, '09f4f535-9b45-5e88-99d9-4d3de8d71477'::uuid, NULL, E'Why do we get used to everyday things? Well as human beings, we have limited brain power. And so our brains encode the everyday things we do into habits, so we can free up space to learn new things. It’s a process called habituation and it’s one of the most basic ways, as humans, we learn. Now, habituation isn’t always bad. Remember learning to drive? I sure do. Your hands clenched at 10 and 2 on the wheel, looking at every single object out there — the cars, the lights, the pedestrians. It’s a nerve-wracking experience. So much so, that I couldn’t even talk to anyone else in the car and I couldn’t even listen to music. But then something interesting happened. As the weeks went by, driving became easier and easier. You habituated it. It started to become fun and second nature. And then, you could talk to your friends again and listen to music. So there’s a good reason why our brains habituate things. If we didn’t, we’d notice every little detail, all the time. It would be exhausting, and we’d have no time to learn about new things. But sometimes, habituation isn’t good. If it stops us from noticing the problems that are around us, well, that’s bad. And if it stops us from noticing and fixing those problems, well, then that’s really bad.', NULL, NULL, NULL),
  ('71f85426-229f-58bf-882a-ccfccd2742a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '71f85426-229f-58bf-882a-ccfccd2742a8'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e632b9e9-ccc2-5343-9348-0d6b4ea03edf'::uuid, NULL, E'Number the beakers and put them away until tomorrow.', NULL, NULL, NULL),
