  ('72160b68-09a5-5e87-b0e0-88f894db031f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '72160b68-09a5-5e87-b0e0-88f894db031f'::uuid, 1, NULL, TRUE, 0, NULL, E'Seismic Mars', E'Until now, Mars has been generally considered a geologically dead planet. An international team of researchers led by ETH Zurich now reports that seismic signals indicate volcanism still plays an active role in shaping the Martian surface.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('721aff5f-d1bb-59f1-b373-f85dc41117e3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '721aff5f-d1bb-59f1-b373-f85dc41117e3'::uuid, 1, NULL, TRUE, 0, NULL, E'Mindfulness', E'Mindfulness is introduced and then two experiments are conducted. In the first experiment, a group of people were tested before and after mindfulness training, and new connections between areas in the brain {{1}} . In the second experiment, a group of people undergo the practice of mindfulness and are compared with people who {{2}} the practice of mindfulness. The results show that mindfulness is deeply involved {{3}} brain functions and is {{4}} with positive changes in mental health.', NULL, NULL, NULL, E'1.have been observed, 2.have not done, 3.in, 4.associated', NULL, NULL),
  ('721cb8d0-cebf-5b4a-9b6b-28b924aece1a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '721cb8d0-cebf-5b4a-9b6b-28b924aece1a'::uuid, 1, NULL, TRUE, 0, NULL, E'Shakespeare Congress', E'Over 800 Shakespeare scholars from almost fifty countries will gather at King’s College London next week as the university co-hosts the 10th World Shakespeare Congress to explore and honor the Bard’s life and work.\nOrganized by the International Shakespeare Association, the World Congress {{1}} held every five years and 2016 is the first time it will be co-hosted in two locations that were integral to both the personal and working life of William Shakespeare. Delegates will arrive {{2}} London on Thursday following the start of the Congress on Sunday in Stratford-upon-Avon. {{3}} a main theme of ‘Creating and Recreating Shakespeare’, the Congress will look {{4}} the continuing global relevance of Shakespeare’s work through a varied program of plenaries, panels, seminars and workshops .', NULL, NULL, NULL, E'1.is, 2.in, 3.With, 4.at', NULL, NULL),
  ('721d6e13-ab5c-5762-aa89-3be07e882096'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '721d6e13-ab5c-5762-aa89-3be07e882096'::uuid, 1, NULL, TRUE, 0, NULL, E'Star Watching', E'Break out the binoculars and telescopes on Saturday, May 19th. Because it''s the first International Sidewalk Astronomy Night. "Sidewalk Astronomers" was founded in San Francisco in 1968, when a lot of people were seeing stars, and not just at night. The group''s goal is to {{1}} more people to the beauty and wonder of celestial objects with good viewing equipment and to provide {{2}} about what the eyewitnesses are actually looking at.\nThe most {{3}} viewed objects are the moon; Jupiter, whose major moons are visible with good binocs; and Saturn. I once trained a cheap telescope on Saturn and some friends were so amazed at the site of the rings they seriously looked at the other end of the scope to see if I had {{4}} it. Sidewalk Astronomy Night is indeed an international event, with dozens of public viewing sites from Beijing to the corner of 81st Street and Central Park West in Manhattan. For more info and to find a site near you, just go to the official website. And if there''s no {{5}} site near you, feel free to go outside and look at the stars anyway.', NULL, NULL, NULL, E'1.expose, 2.information, 3.frequently, 4.doctored, 5.organized', NULL, NULL),
  ('7221face-ea33-5ebf-9d15-1c60eed5f4d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '7221face-ea33-5ebf-9d15-1c60eed5f4d5'::uuid, 1, NULL, TRUE, 0, NULL, E'Mathematical Reasoning(数学逻辑)', NULL, NULL, NULL, NULL, E'4, 5, 2, 3, 1', NULL, NULL),
  ('72289ff0-abad-5b91-84b8-c3977514b247'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '72289ff0-abad-5b91-84b8-c3977514b247'::uuid, 1, NULL, TRUE, 0, NULL, E'Meditation', E'Research has shown that regular meditation can reduce stress, anxiety, and depression, as well as improve sleep quality, cognitive function, and immune system response. Meditation is also associated with increased feelings of compassion, empathy, and self-awareness. By cultivating a regular meditation practice, individuals can enhance their overall health and well-being.', NULL, NULL, NULL, NULL, NULL, NULL),
