  ('722ee8df-3b81-5f18-8d6a-7494930c5d73'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '722ee8df-3b81-5f18-8d6a-7494930c5d73'::uuid, 1, NULL, TRUE, 0, NULL, E'Eco-friendly Smoothies', E'Students at the University of Leicester have recently whizzed up a storm of eco-friendly smoothies. This comes as part of a week of events aimed at promoting environmental initiatives {{1}} campus. A range of events and activities were organized by the University Environment Team and the Students Union to encourage students to waste less, recycle {{2}} , travel sustainably and save energy to contribute to the University''s target of cutting its carbon footprint {{3}} 60% by the year 2020.\nThe highlight of the week was a cycle-powered smoothie maker. Students rescued fruit from Leicester market which would {{4}} have been thrown away and salvaged it to create delicious smoothies. {{5}} electricity was used as the fruit was whizzed up in a blender attached to the back of a bike pedaled by enthusiastic student volunteers.', NULL, NULL, NULL, E'1.on, 2.more, 3.by, 4.otherwise, 5.No', NULL, NULL),
  ('72330820-486a-5d9e-b282-518b04647ff6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '72330820-486a-5d9e-b282-518b04647ff6'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a reward paid to an employee at the end of the year?', '5fd1d205-4c3f-558d-a709-ec035d251285'::uuid, NULL, NULL, E'Year-end bonus', NULL, NULL),
  ('72343566-20e8-5c2a-91e8-b8b8e08bfde5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '72343566-20e8-5c2a-91e8-b8b8e08bfde5'::uuid, 1, NULL, TRUE, 0, NULL, E'Most Plants', E'Most plants capture {{1}} . And the results are usually green. Because in photosynthesis, plant chlorophyll uses {{2}} of blue and our sun''s abundant red, and {{3}} green. But what if—as many sci-fi scenarios suggest—there''s an Earth-like planet with multiple suns? Researchers at England''s University of Saint Andrews say that photosynthetic life on such a planet might end up as a drab black or gray. Or even with a high SPF.\nA quarter of all stars like our sun actually exist in multi-star systems. Plants on a planet with two sunlike stars could need protection against too much radiation—they might {{4}} their own UV-blocking sunscreens.\nOr a planet with two stars may have one sunlike star, along with a red dwarf star that''s also {{5}} in multi-star systems. Any photosynthetic life would be adapted to take {{6}} of the available light waves.\nPlants that relied at times mostly on the dim red dwarf might need light from all across the visible {{7}} .', NULL, NULL, NULL, E'1.sunlight, 2.wavelengths, 3.reflects, 4.evolve, 5.common, 6.advantage, 7.spectrum', NULL, NULL),
  ('7238ba94-54e8-5ec9-a19e-4a7618d3d374'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7238ba94-54e8-5ec9-a19e-4a7618d3d374'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '915c6afd-2af6-5153-8abc-1b0d122a58ad'::uuid, NULL, E'Note that the deadline of the submission of proposals has been extended for a week.', NULL, NULL, NULL),
