  ('723f5ec4-879e-5bac-a379-c0ee79add48c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '723f5ec4-879e-5bac-a379-c0ee79add48c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person''s move to a more important job or rank in a company?', '7830dbf5-2ca2-5c51-a9ea-e6358c537d0e'::uuid, NULL, NULL, E'Promotion', NULL, NULL),
  ('72440904-4015-54c2-a143-2458ad5c9ee8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '72440904-4015-54c2-a143-2458ad5c9ee8'::uuid, 1, NULL, TRUE, 0, NULL, E'Minerals', E'Minerals are important for your body to stay healthy. Your body uses minerals for many different jobs, including keeping your muscles, heart and brain working properly. Minerals are also important for making enzymes and hormones. Most people get the amount of minerals they need by eating a wide variety of foods. If the intake is not enough, doctors may recommend a mineral supplement.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('72482541-474c-52ff-836f-ac2f53e26e72'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '72482541-474c-52ff-836f-ac2f53e26e72'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1a9fa64c-3a51-5dcc-b715-95128a61a2e0'::uuid, NULL, NULL, E'We can see the stars that were formed thirteen billion years ago.', NULL, NULL),
  ('724a4374-d221-5d18-ae9f-c4109d268663'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '724a4374-d221-5d18-ae9f-c4109d268663'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c9fdc5db-557c-5c32-8591-f9fb8d34b697'::uuid, NULL, E'Enrollment in classes is supposed to be completed via the university records system.', NULL, NULL, NULL),
  ('724ce62a-44d3-52b7-b9b6-e89d23182ae9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '724ce62a-44d3-52b7-b9b6-e89d23182ae9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '928da13f-0ec5-5f40-b3a9-a81b10d184af'::uuid, NULL, NULL, E'All academic institutions must conform to those new regulations.', NULL, NULL),
  ('7250c008-acf0-52e5-a296-2ac2b1c047db'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '7250c008-acf0-52e5-a296-2ac2b1c047db'::uuid, 1, NULL, TRUE, 0, NULL, E'Keith Haring', E'Keith Haring began as an underground artist, literally. His first famous projects were pieces of {{1}} graffiti drawn in New York subway stations. Haring traveled from station to station, drawing with chalk and chatting with commuters about his work. These doodles helped him develop his classic style and he {{2}} so prolific, doing up to 40 drawings a day, that it was not long before fame and a measure of fortune followed. Soon, galleries and collectors from the art establishment wanted to buy full-sized pieces by Haring. The paintings {{3}} in price but this did not sit well with Haring''s philosophy. He believed that art, or at least his art, was for everyone. Soon, Haring opened a store which he called the Pop Shop, which he hoped would attract a broad range of people. While somewhat controversial among street artists, some of whom {{4}} Haring of ''selling out'', the Pop Shop changed the way people thought about the relationship between art and business.', NULL, NULL, NULL, E'1.stylized, 2.grew, 3.skyrocketed, 4.accused', NULL, NULL),
  ('7253f78e-6a65-5a93-bb47-91ea1fbfb192'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7253f78e-6a65-5a93-bb47-91ea1fbfb192'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we write on blackboards with?', 'edd5d101-7d17-5762-b482-f121028cdb55'::uuid, NULL, NULL, E'Chalk', NULL, NULL),
  ('72552a63-5b01-5150-acbe-bb360d4358af'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '72552a63-5b01-5150-acbe-bb360d4358af'::uuid, 1, NULL, TRUE, 0, NULL, E'Information Overload', E'We have all been in situations when we felt that too much information was coming at us. When this happens, we feel {{1}} and fear that we will not be able to retain any information at all. Sometimes it is not just the quantity of communication but the level that causes overload. If the message contains information that is new to the receiver, {{2}} processes or concepts that are not familiar, then the chances of overload increase greatly. The sender should break up the message into more {{3}} or digestible bits and reduce the amount of information that has to be absorbed at any one time. One technique is to make a high-level announcement and then follow it up later with more details. The sender has the {{4}} responsibility to check that the receiver has understood the message. This means that a manager may have to {{5}} a message to reflect the various experiences of the employees. A new employee may need repeated explanations before beginning an operation, whereas an experienced employee may start rolling his eyes at the same old instructions.', NULL, NULL, NULL, E'1.overwhelmed, 2.including, 3.palatable, 4.primary, 5.adjust', NULL, NULL),
  ('725d1671-8331-5682-aaa3-23690c1ce931'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '725d1671-8331-5682-aaa3-23690c1ce931'::uuid, 1, NULL, TRUE, 0, NULL, E'Great Barrier Reef', E'Amidst the vibrant coral reefs of the Great Barrier Reef, Dr. Maya Sharma isn''t just admiring the underwater wonderland. She''s on a {{1}} against the clock, collecting samples of these marine jewels. Around the globe, dedicated scientists like Sharma are diving into the ocean''s depths, not for buried treasure or hidden shipwrecks, but for coral fragments. Unlike the thrill of archaeological discovery or the adrenaline rush of exploring uncharted waters, coral collection is a meticulous and critical {{2}} . While some pursue these fragments for profit, supplying the booming aquarium industry, others, like Sharma, are driven by a more noble purpose: preservation. Their mission is to rescue and cultivate these vital ecosystems before they {{3}} into a wave of extinction. The race {{4}} time is on, as coral reefs disappear at an alarming rate. But fueled by unwavering dedication and scientific ingenuity, coral crusaders like Sharma are leading the charge to preserve these underwater wonders. They are the guardians of the sea, {{5}} that future generations can witness the breathtaking beauty and vital importance of these marine ecosystems.', NULL, NULL, NULL, E'1.mission, 2.endeavor, 3.vanish, 4.against, 5.ensuring', NULL, NULL),
  ('72636501-c89e-500c-a901-9e7dc25ad8a2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '72636501-c89e-500c-a901-9e7dc25ad8a2'::uuid, 1, NULL, TRUE, 0, NULL, E'Age for Activity', E'Some people say the elderly are unsuitable to take part in some activities. Please give an example of the activities, and give the maximum age for it.', NULL, NULL, E'As the population ages, there has been an ongoing debate about the suitability of elderly individuals participating in certain activities. One such activity that is often debated is bungee jumping. While some argue that bungee jumping is suitable for people of all ages, I take a negative standpoint and argue that bungee jumping is not an activity that elderly individuals should participate in.\nFirstly, as people age, their bodies become more fragile and susceptible to injury. Bungee jumping can put a lot of stress on the body, which may increase the risk of injury or health complications in older individuals. This is especially true for those who have pre-existing medical conditions such as heart disease or osteoporosis.\nSecondly, older individuals may have weaker bones and muscles, which may make them more susceptible to injury during the jump. Even with proper safety precautions, the force of the jump can cause damage to the body, particularly in older individuals whose bodies may not be able to handle the stress.\nIn conclusion, while some may argue that bungee jumping is suitable for people of all ages, I believe that elderly individuals should avoid this activity. As people age, their bodies become more fragile and susceptible to injury, and the risk of injury during a bungee jump is simply too high for older individuals. Instead, elderly individuals should focus on activities that are less physically demanding and pose less risk to their health and well-being.', NULL, 200, 300),
  ('72689aed-7516-5af3-b98e-a769c45a81e3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '72689aed-7516-5af3-b98e-a769c45a81e3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '874a7561-7239-53eb-be5f-67262a215b0b'::uuid, NULL, E'The capacity of programming computers is expanding enormously every year.', NULL, NULL, NULL),
  ('7269837c-c974-5441-a37d-bde97ae6e443'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '7269837c-c974-5441-a37d-bde97ae6e443'::uuid, 1, NULL, TRUE, 0, NULL, E'Sidewalk Labs', E'In Silicon Valley, to make a device “smart” means to add internet {{1}} , allowing it to collect, send, and receive data, often while learning and {{2}} to user preferences. The technology industry has invested wholesale in the idea that “smart” means better, so we have smartphones. Soon enough, we’ll have a smart city: Sidewalk Labs. It is not the first smart city — municipalities around the world have {{3}} smart infrastructure like artificial-intelligence-enabled traffic lights — but it might be the most {{4}} . The project’s 200-page wish list of features is astounding. The “vision document” imagines not only the revitalization of a 12-acre plot that has sat largely vacant since its heyday as an industrial port, but its transformation into a micro-city {{5}} with smart technologies that will use data to disrupt everything from traffic congestion to health care, housing, zoning regulations, and greenhouse-gas emissions.', NULL, NULL, NULL, E'1.connectivity, 2.adapting, 3.adopted, 4.ambitious, 5.outfitted', NULL, NULL),
  ('727354b6-5fbc-5afd-86f2-2719dd42b74f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '727354b6-5fbc-5afd-86f2-2719dd42b74f'::uuid, 1, NULL, TRUE, 0, NULL, E'Presidential Election', E'According to the United States Constitution, a presidential election is to be held once every fourth year. The process of electing a President and Vice-President begins long before Election Day. Candidates from both major and minor political parties and independent candidates begin to raise money and campaign at least one year in advance of the general presidential election. In order to officially represent a political party, a candidate must be nominated by that party.\nThis primary nomination process is a contest that often produces factions within political parties. These divisions impact the policy stances and agendas of the candidates running for nomination as they attempt to garner the support of party leaders and activists. The nominating process officially begins with the first state primaries and caucuses, which usually occur in the month of February of the election year. It is at these local events that voters are given their first chance to participate in electing the nation’s next President.\nThere are many factors that influence who will ultimately become the candidate for a party. The public’s perception of the candidates is influenced by such things as media reports, public opinion polls, candidate preference surveys, and advertising. These factors will help determine the perceived strengths and weaknesses of the candidates in the months leading up to the caucuses and primaries.', NULL, NULL, E'Although a presidential election is to be held once every fourth year, candidates of President and Vice-President begin to raise money and campaign long before Election Day in order to be nominated by their parties, and this primary nomination process is a contest that often produces factions within political parties, but there are many factors such as media reports and public surveys that influence who will ultimately become the candidate for a party.', NULL, 5, 75),
  ('727822fb-7a13-5770-bcba-174c7a50950b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '727822fb-7a13-5770-bcba-174c7a50950b'::uuid, 1, NULL, TRUE, 0, NULL, E'Biology', NULL, 'bf044fa8-16d0-5247-b9e0-7010e784d776'::uuid, NULL, E'Welcome to your very first tutorial in biology. Now, in this video series what I want to do is I want to talk to you guys about many different topics concerning biology. For example, I want to talk to you guys about DNA and genetics in cells, in bacteria, in life and a whole bunch of interesting stuff. But since this is the very first video, I think what we should do in this video is just stick with the very basics. And the first thing I want to do is talk to you guys about what is biology. So, let''s go ahead and answer that question. And the definition of biology is this: the study of life in living organisms. All right, that makes sense up to a certain point up until organisms because you may have heard of organisms before. And you may have your own definition but the scientific definition of an organism is a living thing. Well, that''s easy. We know what living things are. I''m a living thing, plants, grass is a living thing. My puppy named old Dan, cutest puppy ever, by the way, is a living thing but whenever we talk about living things. Believe it or not, things get rid of complicated because then you have to ask yourself ''what is life''. Well, of course, if you ask your grandma or your best friend or even if you ask a philosopher ''what is life'', everyone is going to give you kind of a different definition of their outlook on life. However, whenever scientist and biologists were first deciding, you know what, what is life? That''s the problem that they had everyone had their own separate definition of life itself. So, what they need to do before biology was even invented, which is, of course, the study of life is scientists needed to agree on the definition of life.', NULL, NULL, NULL),
  ('727981d0-1372-511d-9fa2-07ed208f2333'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '727981d0-1372-511d-9fa2-07ed208f2333'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '28fd3c5b-9512-573e-aa03-2b8fd03ae9a3'::uuid, NULL, NULL, E'Colleges must maintain a high academic standard all the time.', NULL, NULL),
  ('727d49da-f8d2-54ba-89db-9269649d1805'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '727d49da-f8d2-54ba-89db-9269649d1805'::uuid, 1, NULL, TRUE, 0, NULL, E'Animal Rights', E'Animal rights are important. Give your opinions.', NULL, NULL, NULL, NULL, 200, 300),
  ('72882a6f-f7a7-5d07-9d96-2083f4478c55'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '72882a6f-f7a7-5d07-9d96-2083f4478c55'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a writer''s first version of the book without publishing?', '61f8f56b-07a4-54b7-b3e0-81b54b1e937c'::uuid, NULL, NULL, E'Manuscript', NULL, NULL),
  ('7289f8d2-f9d2-5852-9b6d-2ae2081a1d5a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '7289f8d2-f9d2-5852-9b6d-2ae2081a1d5a'::uuid, 1, NULL, TRUE, 0, NULL, E'Computer Viruses', E'Computer viruses have been a {{1}} of life at least since the 1980s, if not before. They can cause companies to lose hours of working time and they can also spread panic among computer users everywhere. There are, however, several {{2}} types of computer infection – all loosely referred to as viruses – and they each work in a slightly different way. A particularly nasty one is the worm, which is a program designed to sneak its way into an entire computer network, and reproduce itself over and over again. Then there is the Trojan, which strictly {{3}} isn’t a virus, but a piece of software that appears to do one thing, but actually does something malicious instead. When the ''unsuspecting'' operator introduces it into the computer, the alien program will take over the machine. With Trojans you have to be particularly careful because they can often be introduced by way of a message advertising an anti-virus product. So what motivates someone to {{4}} a virus into the computer systems of innocent victims? Perhaps it’s simply the desire to prove that it can be done. Or because it gives the kind of pleasure you get from solving a difficult problem – nowadays people protect their computers with all sorts of security software, so it takes considerable {{5}} to break through all the defences and introduce a virus.', NULL, NULL, NULL, E'1.fact, 2.distinct, 3.speaking, 4.introduce, 5.skill', NULL, NULL),
  ('728ddc44-68bd-5537-9a0d-058fa27d9771'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '728ddc44-68bd-5537-9a0d-058fa27d9771'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f580af35-0121-5d49-b86c-81206073d1a6'::uuid, NULL, E'The new building will be located in the center of the town.', NULL, NULL, NULL),
