  ('72af01e4-71b2-56b5-a270-77c2492d1fa2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '72af01e4-71b2-56b5-a270-77c2492d1fa2'::uuid, 1, NULL, TRUE, 0, NULL, E'Hippocrates', E'Hippocrates allowed observation, rationality and his own genuine respect for his patients to {{1}} his practice. Using the scientific method, he carefully recorded his patient''s symptoms and {{3}} to treatments and used the data {{4}} to evaluate and prescribe the most successful regimens. His prestige as a great {{2}} practitioner, educator, and author helped spread these ideals of {{6}} medicine throughout the ancient world.', NULL, NULL, NULL, E'1.guide, 2.responses, 3.gathered, 4.medical, 5.rational', NULL, NULL),
  ('72af3704-aa4d-5432-9de3-6dd5fb050350'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '72af3704-aa4d-5432-9de3-6dd5fb050350'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c0bbed53-cb86-5185-a850-ffa0ea1474ea'::uuid, NULL, NULL, E'Student assistants will support new students with their study and accommodation.', NULL, NULL),
  ('72b0be9c-bd14-591f-9195-6c0524133245'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '72b0be9c-bd14-591f-9195-6c0524133245'::uuid, 1, NULL, TRUE, 0, NULL, E'Differential Education', E'Discuss the advantages and disadvantages of differential education, i.e., splitting students into different classes according to their academic performance.', NULL, NULL, NULL, NULL, 200, 300),
  ('72b107f2-cbc9-50e5-9b36-a1dff5a11c60'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '72b107f2-cbc9-50e5-9b36-a1dff5a11c60'::uuid, 1, NULL, TRUE, 0, NULL, E'Work or Luck', E'People argue whether it is hard work or luck that contributes to success. What is your opinion?', NULL, NULL, E'Success is a topic that has been debated for centuries, with many people wondering whether it is hard work or luck that contributes to it. In my opinion, hard work is the primary factor that leads to success, and there are several reasons why I believe this.\nFirstly, hard work leads to mastery of skills and knowledge, which are essential for success. Success is rarely achieved overnight, and it often requires years of practice and dedication to hone one''s skills and knowledge. For example, a musician who wants to become successful must spend countless hours practicing their instrument and learning music theory to become proficient. Without this hard work, they would not have the necessary skills to succeed in the industry.\nSecondly, hard work helps build discipline and resilience, which are important traits for success. Discipline is necessary to stay focused on one''s goals and work towards them consistently, while resilience is necessary to bounce back from setbacks and failures. These traits are developed through hard work and perseverance, as individuals learn to push through difficult times and stay committed to their goals.\nIn conclusion, while luck may play a role in success, I believe that hard work is the primary factor that contributes to it. Through hard work, individuals can develop the necessary skills, knowledge, discipline, and resilience to achieve their goals and succeed in their chosen fields. Therefore, it is important for individuals to focus on working hard and committing themselves fully to their pursuits if they want to achieve success.', NULL, 200, 300),
  ('72bcc764-2183-5a5a-a28e-f8d760250271'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '72bcc764-2183-5a5a-a28e-f8d760250271'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the main building of a large company or an organization?', '07f917df-ce98-5e2a-888e-c04e521a0e32'::uuid, NULL, NULL, E'Headquarters', NULL, NULL),
