  ('72bfd9d6-5566-5c54-b432-0af0a991c048'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '72bfd9d6-5566-5c54-b432-0af0a991c048'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd09bd409-34af-5d71-98d7-834f49a4dba2'::uuid, NULL, E'We offer a range of short online courses that are open to everyone.', NULL, NULL, NULL),
  ('72c2ff25-3372-55c0-954d-8ff67c4e6649'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '72c2ff25-3372-55c0-954d-8ff67c4e6649'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1fc5cbc1-057e-51d1-ae0d-43515a3409d7'::uuid, NULL, NULL, E'Several universities work together to carry out their educational mission.', NULL, NULL),
  ('72c31992-a96e-5ee9-822c-c82fe1716df2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '72c31992-a96e-5ee9-822c-c82fe1716df2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '36ebc891-8336-5840-a44a-9973ec3ef61c'::uuid, NULL, NULL, E'There are more postgrad students here than is usually seen.', NULL, NULL),
  ('72c38429-2bdb-50e6-a971-df8377616cb1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '72c38429-2bdb-50e6-a971-df8377616cb1'::uuid, 1, NULL, TRUE, 0, NULL, E'Pattern Books', NULL, 'cd34ea78-4946-584f-b173-d9070efd5d94'::uuid, NULL, E'In today''s class we''ll be examining some nineteenth-century pattern books that were used for building houses. I think it''s fair to say that these pattern books were the most important influence on the design of North American houses during the nineteenth century. This was because most people who wanted to build a house couldn''t afford to hire an architect. Instead, they bought a pattern book, picked out a plan, and took it to the builder. The difference in cost was substantial. In 1870, for example, hiring an architect would''ve cost about a hundred dollars. At the same time, a pattern book written by an architect cost only five dollars. At that price, it''s easy to see why pattern books were so popular. Some are back in print again today, and of course they cost a lot more than they did a hundred years ago. But they''re an invaluable resource for historians, and also for people who restore old houses. I have a modern reprint here that I’ll be passing around the room in a moment so that everyone can have a look.', NULL, NULL, NULL),
  ('72c68f40-9de0-5071-947d-c494763988e8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '72c68f40-9de0-5071-947d-c494763988e8'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c472af5a-c4d3-5619-93e9-7446b0aeac77'::uuid, NULL, NULL, E'We have not yet achieved equality in our society.', NULL, NULL),
  ('72cc0fb2-1f62-5f6b-8d9c-fa4c91a63d51'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '72cc0fb2-1f62-5f6b-8d9c-fa4c91a63d51'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '73652838-384b-5684-887e-c3e4c91943c7'::uuid, NULL, E'They decided to spread the building process over three years.', NULL, NULL, NULL),
  ('72cf4195-4634-575d-b837-ce74e36494f5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '72cf4195-4634-575d-b837-ce74e36494f5'::uuid, 1, NULL, TRUE, 0, NULL, E'Neurotransmitter', E'A ubiquitous neurotransmitter that carries signals between brain cells, dopamine, among its many functions, is involved in multiple aspects of cognitive processing. The chemical messenger has been extensively studied from the perspective of external cues, or "deterministic" signals.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('72d58f45-ee09-5036-9e02-5060b22114d4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '72d58f45-ee09-5036-9e02-5060b22114d4'::uuid, 1, NULL, TRUE, 0, NULL, E'PTSD', E'Trauma affects even the most resilient among us and can include anything from isolated incidents, such as surviving an active shooter in a public location or narcissistic abuse in an intimate relationship, to severe and prolonged abuse or neglect occurring in childhood. Statistics suggest a lifetime estimate of approximately 6.8% for PTSD diagnosis, which is a small portion relative to those who experience trauma. Thus, on average, approximately 7 out of 100 people will go on to develop symptoms associated with PTSD after experiencing a significant traumatic event, with an average estimate of 7.5 million to 8 million people per year developing the disorder.\nThe effects of post-traumatic stress can be lifelong, chronic, and highly variable. Children who are abused or neglected may develop symptoms of PTSD, compromising their ability to function as independent adults; others may not develop any symptoms or milder symptoms. Issues with self-worth, self-love, feelings of uselessness, and suicidal ideation are commonly reported in those with PTSD. Those who experience abuse in childhood are more susceptible to being re-traumatized later in life with unhealthy adult relationships. PTSD often includes both short-term effects immediately following a traumatic event and more chronic, long-term effects.\nWhether someone will go on to develop PTSD following trauma is influenced by many factors, which may include: individual resiliency, personality, prior history of trauma, intensity of the trauma (i.e. a one-time isolated event versus chronic or long-term abuse), duration of the traumatic event(s), availability of an emotional support system, and other factors such as environmental contingencies (drugs/alcohol, unstable or unsafe living conditions).', NULL, NULL, NULL, NULL, 5, 75),
  ('72d8f50b-e88d-54ca-923a-bcf352f7dedb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '72d8f50b-e88d-54ca-923a-bcf352f7dedb'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7ccbee53-c2be-5bc7-b6bb-042345ece4e7'::uuid, NULL, E'You should include your name and identification number on the registration form.', NULL, NULL, NULL),
