  ('72efab43-6988-5c72-b713-1c8691e32baa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '72efab43-6988-5c72-b713-1c8691e32baa'::uuid, 1, NULL, TRUE, 0, NULL, E'Retirement', E'For a start, we need to change our {{1}} of ''retirement'', and we need to change mind-sets arising from earlier government policy which, in the face of high unemployment levels, encouraged mature workers to take early retirement. Today, government encourages them to {{2}} their retirement.\nWe now need to think of retirement as a phased process, where mature age workers {{3}} reduce their hours, and where they have considerable flexibility in how they combine their work and non work time.\nWe also need to recognise the broader change that is occurring in how people work, learn, and live. Increasingly we are moving away from a linear relationship between education, training, work, and retirement, as people move in and out of jobs, careers, caregiving, study, and leisure. Employers of choice remove the {{4}} between the different segments of people''s lives, by creating flexible conditions of work and a range of leave entitlements. They take an individualized approach to workforce planning and development so that the needs of employers and employees can be met {{5}} .', NULL, NULL, NULL, E'1.concept, 2.delay, 3.gradually, 4.barriers, 5.simultaneously', NULL, NULL),
  ('72f0932e-7f9b-51ed-85c4-9e5bc0466808'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '72f0932e-7f9b-51ed-85c4-9e5bc0466808'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '582d65b7-0870-54fa-ba8c-cb6bdc309f92'::uuid, NULL, E'I''ve had a very happy childhood so I sometimes forget that others haven''t.', NULL, NULL, NULL),
  ('72f82796-f409-5a61-b345-a4f0574102a3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '72f82796-f409-5a61-b345-a4f0574102a3'::uuid, 1, NULL, TRUE, 0, NULL, E'Optogenetics', E'Optogenetics is a research tool in neuroscience that uses light to alter the activity of genetically engineered light-sensitive nerve cells to better understand the function and behavior of clusters of neurons in animals. Now, a team led by researchers from the Korea Advanced Institute of Science and Technology has developed an implantable optogenetic light-emitting device that can be wirelessly recharged.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('72f869b6-c932-50cb-8880-e556e1d5f82a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '72f869b6-c932-50cb-8880-e556e1d5f82a'::uuid, 1, NULL, TRUE, 0, NULL, E'Hong Kong', E'The subtropical sea {{1}} Hong Kong is a noisy place: A flow of massive freight ships {{2}} through constantly; high-speed ferries {{3}} time-pressed business people to meetings in towers; and the coastal development is never-ending. It is one of the most densely-urbanized areas on the planet.', NULL, NULL, NULL, E'1.surrounding, 2.chug, 3.jet', NULL, NULL),
