  ('733bd550-8aaa-59f9-9737-2abe2d694046'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '733bd550-8aaa-59f9-9737-2abe2d694046'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'cc708f3d-3549-5fcc-8581-0b5c0779fe8c'::uuid, NULL, NULL, E'The essay will argue that the technology does more harm than good.', NULL, NULL),
  ('733c1fc7-d01a-5980-880d-25cb0317debd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '733c1fc7-d01a-5980-880d-25cb0317debd'::uuid, 1, NULL, TRUE, 0, NULL, E'Problem with Over-achievement', NULL, 'e6632336-cc80-5a2c-8bf4-f01c9191637e'::uuid, NULL, E'In other words, over-achievers are trying to solve a range of psychological problems through material or worldly means. And this is why their efforts must, in a deep sense, always be doomed to failure – even when it appears to most of the world as if over-achievers are succeeding beyond measure. Because success is the moment when over-achievers are likely to notice the doomed nature of their ambitions, it is a particularly troubling and dangerous eventuality. Depression may set in just after the company is sold; the star will fall into a crisis just after they finally gain worldwide recognition. At exactly the point when their work is acclaimed or finds its audience, over-achievers are at risk of severe breakdown. So long as they are merely running, they can forget to notice that their goal is misaligned with their true inner ambition. They must wait for success to reveal the fateful nature of their life’s quest.', NULL, NULL, NULL),
  ('734d818c-1f7b-5f70-b062-5234e5004897'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '734d818c-1f7b-5f70-b062-5234e5004897'::uuid, 1, NULL, TRUE, 0, NULL, E'Medical Fund', E'Nowadays, researches on new medicines and treatments are essential for improving health and dealing with diseases. Who do you think should fund these researches: private companies or governments?', NULL, NULL, NULL, NULL, 200, 300),
