  ('735aa69d-6b25-526d-aa8d-d28f3da2c142'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '735aa69d-6b25-526d-aa8d-d28f3da2c142'::uuid, 1, NULL, TRUE, 0, NULL, E'Middle Ages', E'To understand the past you have to think as the people in the period you are studying thought. The example of what it must have been like to be a peasant in the Middle Ages is used. However, sensibilities change over time and we can''t completely throw off the mentality of the present. Therefore, every age will have a slightly different perspective on the same period of the past.', NULL, NULL, NULL, NULL, NULL, NULL),
