  ('73621730-9810-5227-abce-b482eb90dda0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '73621730-9810-5227-abce-b482eb90dda0'::uuid, 1, NULL, TRUE, 0, NULL, E'Childhood Education', E'Early childhood education plays a crucial role in a child''s development. It provides a strong foundation for future learning and helps children develop social, emotional, and cognitive skills. High-quality early childhood education programs can make a positive impact on children''s lives and their future success.', NULL, NULL, NULL, NULL, NULL, NULL),
