  ('737642a7-40c9-575a-b38a-f4f1e31252dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '737642a7-40c9-575a-b38a-f4f1e31252dd'::uuid, 1, NULL, TRUE, 0, NULL, E'Influenza Virus', E'The influenza virus is constantly mutating, essentially putting on ever-changing disguises, to {{1}} our immune systems. When a new virus {{2}} that can easily infect people and be spread between people, it can turn into a pandemic, but we do not know when it will happen, what virus strain it will be and how {{3}} the disease will be.', NULL, NULL, NULL, E'1.evade, 2.emerges, 3.severe', NULL, NULL),
  ('73773c35-079d-541a-83d8-4b5b08c4eb78'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '73773c35-079d-541a-83d8-4b5b08c4eb78'::uuid, 1, NULL, TRUE, 0, NULL, E'Ancient grapes', E'Extreme heat and extreme drought in Baja California are pushing some winemakers to {{1}} a very old and very climate-adaptable wine varietal. The results are delicious: they are not just surviving but {{2}} . Grapes left on the vine after the recent harvest are still {{3}} and sweet.', NULL, NULL, NULL, E'1.explore, 2.thriving, 3.plump', NULL, NULL),
