  ('7412fd1b-dbcc-55d1-af16-1fb5ec0a1531'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7412fd1b-dbcc-55d1-af16-1fb5ec0a1531'::uuid, 1, NULL, TRUE, 0, NULL, E'Dyes and Pigments', E'The dyes and pigments available in any particular period in which a specific color photographic process was invented, manufactured and used have profound effects on the quality of color that defines most of the style and particular historical period.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('7414b6df-bab0-54a6-bdf3-b85ae1c48400'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7414b6df-bab0-54a6-bdf3-b85ae1c48400'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Who takes care of people who are sick and stay in hospital?', '5e19773c-d9bb-579f-b36b-10ea00988efa'::uuid, NULL, NULL, E'Nurse', NULL, NULL),
  ('74176f47-086c-5131-8c9e-7c34e3e74594'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '74176f47-086c-5131-8c9e-7c34e3e74594'::uuid, 1, NULL, TRUE, 0, NULL, E'Museum Restaurant', E'This museum restaurant is a {{1}} place to {{2}} a party. You can have a party of 20-25 people. More people are {{3}} and prices {{4}} at $45.', NULL, NULL, NULL, E'1.perfect, 2.have, 3.possible, 4.start', NULL, NULL),
  ('741a855b-0d1f-54a4-858c-9a67f071cbf8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '741a855b-0d1f-54a4-858c-9a67f071cbf8'::uuid, 1, NULL, TRUE, 0, NULL, E'University Terms', E'University terms are typically divided into semesters or quarters, with each term lasting several months. The academic calendar may also include summer sessions or intersessions, which offer additional opportunities for students to take courses and accelerate their degree progress. University terms are structured to provide students with a clear timeline for completing their coursework and earning their degrees.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('741c765d-ee60-5465-87b7-0e8c9471ee80'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '741c765d-ee60-5465-87b7-0e8c9471ee80'::uuid, 1, NULL, TRUE, 0, NULL, E'Dolphins', E'Dolphins, whales and porpoises are all social animals, but some species are more sociable than others. This depends on the environment because a species adopts the lifestyle most suitable for this. Among dolphins, forming groups makes it easier for them to find food, reproduce and gain knowledge. They are safer too, because dolphins can communicate danger when there are threats around.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('7421af7a-38cd-51e2-9900-e5e3afddcbc9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '7421af7a-38cd-51e2-9900-e5e3afddcbc9'::uuid, 1, NULL, TRUE, 0, NULL, E'Stem Cell', E'Stem cell research, a vital and continuously evolving field in biology and medicine, promises transformative advances in regenerative medicine. Stem cells are unique for their ability to develop into different cell types in the body, offering potential remedies for various diseases, including degenerative conditions and severe injuries. At the forefront of this research is the study of both embryonic and adult stem cells. Embryonic stem cells, derived from early-stage embryos, have the remarkable capacity to differentiate into any cell type, making them invaluable for developing new therapies. Adult stem cells, found in tissues like bone marrow and skin, have a more limited capacity for transformation but are crucial for tissue repair and regeneration. One of the most significant breakthroughs has been in the area of induced pluripotent stem cells (iPSCs). Scientists have learned to reprogram adult cells to an embryonic-like state, allowing them to generate any cell type. This innovation not only circumvents ethical concerns associated with embryonic stem cells but also opens up personalized treatment possibilities. Stem cell research has already led to notable advances, such as the use of stem cells in bone marrow transplants for leukemia patients. Ongoing research aims to harness stem cells for repairing damaged tissues and organs, potentially offering cures for conditions like Parkinson''s disease, spinal cord injuries, and diabetes. Despite the promise, stem cell research faces scientific and ethical challenges, including the risk of cell rejection and ethical considerations in the use of embryonic cells. Nevertheless, the potential of stem cells to revolutionize medicine remains an exciting and hopeful prospect. In conclusion, stem cell research stands at the cutting edge of regenerative medicine, offering unprecedented opportunities to treat and potentially cure a wide range of diseases. As research progresses, it holds the key to unlocking new frontiers in medical treatment and human health.', NULL, NULL, E'Stem cell research, exploring embryonic and adult stem cells, including breakthroughs in induced pluripotent stem cells, promises revolutionary treatments in regenerative medicine, potentially curing diseases like leukemia, Parkinson''s, and diabetes, despite facing scientific and ethical challenges.', NULL, 5, 75),
  ('742e2f77-0fa2-5f2d-99a4-5f9458dc44f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '742e2f77-0fa2-5f2d-99a4-5f9458dc44f0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8483e4a1-b144-5858-806d-7a519701bd11'::uuid, NULL, E'English is expanding as a lingua franca but not as a mother tongue.', NULL, NULL, NULL),
  ('74374dfc-3b08-5920-b678-82fc1ae95ca4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '74374dfc-3b08-5920-b678-82fc1ae95ca4'::uuid, 1, NULL, TRUE, 0, NULL, E'Natural Language', E'When people start thinking about language, the first question which often occurs to them is this: is language natural to humans? - in the same way that grunting is natural to pigs, and barking comes naturally to dogs. Or is it just something we happen to have learned? - in the same way that dogs may learn to beg, or elephants may learn to waltz, or humans may learn to play the guitar.\nClearly, in one sense, children ''learn'' whatever language they are exposed to, be it Chinese, Nootka or English. So no one would deny that ''learning'' is very important. But the crucial question is whether children are born with ''blank sheets'' in their head as far as language is concerned - or whether humans are ''programmed'' with an outline knowledge of the structure of languages in general.\nThis question of whether language is partly due to nature or wholly due to learning or nurture is often referred to as the nature-nurture controversy, and has been discussed for centuries. For example, it was the topic of one of Plato''s dialogues, the Cratylus. Controversies which have been going on for literally ages tend to behave in a characteristic fashion. They lie dormant for a while, then break out fiercely. This particular issue resurfaced in linguistics in 1959 when the linguist Noam Chomsky wrote a devastating and witty review of Verbal Behavior, a book by the Harvard psychologist B.F. Skinner (Skinner 1957; Chomsky 1959). This book claimed to ''explain'' language as a set of habits gradually built up over the years. According to Skinner, no complicated innate or mental mechanisms are needed. All that is necessary is the systematic observation of the events in the external world which prompt the speaker to utter sounds.', NULL, NULL, E'When people start thinking about language, the first question which often occurs to them is whether language is natural to humans, and clearly, in one sense, children learn whatever language they are exposed to, but the crucial question is whether children are born with blank sheets in their head or whether humans are programmed with an outline knowledge, so this question is often referred to as the nature-nurture controversy.', NULL, 5, 75),
  ('743c6be4-471e-51bf-9f01-fdf7f3ed458d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '743c6be4-471e-51bf-9f01-fdf7f3ed458d'::uuid, 1, NULL, TRUE, 0, NULL, E'Coaching a Basketball Team', E'You''re coaching a youth basketball team, and you''ve noticed that the team''s performance has been inconsistent. The players show potential during practice but struggle to maintain focus and teamwork during games. You want to find a way to improve their game-time performance and help them play more cohesively as a team. What would you say to your team?', 'eecaf545-de68-5840-9d5a-6da014e54a4f'::uuid, NULL, E'Hey team, I''ve seen how hard you all work in practice, and you''ve got so much talent. But during games, it feels like we''re not quite clicking together as we should. How about we start some new drills that focus specifically on teamwork and communication? Also, let''s have a quick huddle before each game to set our focus and hype each other up. Together, I know we can bring our A-game every time.', NULL, NULL, NULL),
  ('74415120-201f-531d-b64e-96706e7112aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '74415120-201f-531d-b64e-96706e7112aa'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd3815544-cc0f-52f5-9c8c-9be417c1868c'::uuid, NULL, NULL, E'Attracting skilled workers to an expensive housing city is challenging.', NULL, NULL),
