  ('74d5c12b-cafb-5b66-881b-6439ba1edcc4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '74d5c12b-cafb-5b66-881b-6439ba1edcc4'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '60b80669-9a53-5032-bf5c-929d87779e0e'::uuid, NULL, E'During some stages of sleep, your eyes move rapidly behind your closed eyelids.', NULL, NULL, NULL),
  ('74d6f557-356d-5249-8f4f-0fb059662eb9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', '74d6f557-356d-5249-8f4f-0fb059662eb9'::uuid, 1, NULL, TRUE, 0, NULL, E'Taste Sensitivity', E'What you eat influences your taste for what you might want to eat next. So claims a University of California, Riverside, study performed on fruit flies. The study offers a better understanding of neurophysiological plasticity of the taste system in flies. To maintain ideal health, animals require a balanced diet with optimum amounts of different nutrients. Macronutrients like carbohydrates and proteins are essential; indeed, an unbalanced intake of these nutrients can be detrimental to health. Flies require macronutrients such as sugars and amino acids for survival. They use the gustatory system, the sensory system responsible for the perception of taste, to sense these nutrients and begin feeding.\nIn their experiments in the lab, the researchers Anindya Ganguly and Manali Dey, led by Anupama Dahanukar, fed adult flies different diets: a balanced diet, a sugar-reduced and protein-enriched diet, and a sugar-enriched and protein-depleted diet. They ensured that all three diets were similar in total calorie content and tested the flies daily for a week to examine modifications in their food choice and taste sensitivity. The researchers report that diet affects dopamine and insulin signaling in the brain, which, in turn, affects the flies'' peripheral sensory response, which is comprised of neurons directly involved in detecting external stimuli. This response then influences what the flies eat next.\n\nWhich of the following statements about the study are true?', NULL, NULL, NULL, E'The fly senses macronutrients through its taste system.\nDopamine in the brain is closely related to diet.', NULL, NULL),
  ('74d7282c-e939-553d-9ee4-296db08f0285'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '74d7282c-e939-553d-9ee4-296db08f0285'::uuid, 1, NULL, TRUE, 0, NULL, E'Roofing', E'Roofing your house rarely rates high on the list of fun and exciting home remodeling projects. But when your home develops a leak, your attitude might take a sharp turn. Suddenly, the prospect of a dry, tightly sealed house begins to look very attractive. A beautiful new roof can also improve the curb appeal of your house.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('74de9c61-4b74-5463-9e1d-63bf2e7e47ba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '74de9c61-4b74-5463-9e1d-63bf2e7e47ba'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '63286cc8-4368-51a1-b499-acfd60b0cd6c'::uuid, NULL, NULL, E'This course provides the opportunity to get valuable industry experience.', NULL, NULL),
  ('74df548a-61a5-5d97-b22a-b9866172d832'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '74df548a-61a5-5d97-b22a-b9866172d832'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do you make food or drink go down your throat into your stomach?', '62c70b41-1e12-5466-aa4b-e26fcdcb435a'::uuid, NULL, NULL, E'Swallow', NULL, NULL),
  ('74e686f8-ddd0-5cf1-998d-dc4f758997ab'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '74e686f8-ddd0-5cf1-998d-dc4f758997ab'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What does post- mean in the word postwar?', 'b8719e80-5456-53f3-84a8-90998f56bde3'::uuid, NULL, NULL, E'After', NULL, NULL),
  ('74f1df53-149c-54ce-a81c-09f33988ef6d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '74f1df53-149c-54ce-a81c-09f33988ef6d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the regular beating of blood through your body, and you can feel it especially when you touch your wrist?', '35ce4179-a698-5b3b-b2d7-5c4cff3ac018'::uuid, NULL, NULL, E'Pulse / Sphygmus', NULL, NULL),
  ('74f98e05-600f-5ae3-89d4-945fe9ba0522'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '74f98e05-600f-5ae3-89d4-945fe9ba0522'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7f24bb54-c4c9-5711-a8a4-1d341a4910e8'::uuid, NULL, E'We don''t have enough evidence to be absolutely sure of anything.', NULL, NULL, NULL),
  ('74ff3e0f-bb87-5785-9604-cc52e093f3b3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '74ff3e0f-bb87-5785-9604-cc52e093f3b3'::uuid, 1, NULL, TRUE, 0, NULL, E'The Camera Never Lies', E'The saying "The camera never lies." has been with us almost since the beginning of photography — yet we all now know that it can, and does lie, and very convincingly. Yet most of us still seem to trust the truth of a photographic image — especially in our newspapers or on TV news reports — even though we may question its message. We think of photographs as an accurate reflection of unaltered reality. We''re convinced of this when we take unposed snaps on our family holidays or of colleagues the worse for wear at the office party. It is this property of photography that makes it hard to question the evidence before our eyes.\nOur holiday snaps, though, like photographs showing life ten, fifty, a hundred years ago, tend only to bring about at most a feeling of nostalgia — not always a negative emotion. Many people keep albums to relive the better moments of their lives — and their impact is reduced by the fact that what they show is over, part of history. News photos, on the other hand, in presenting moments of an event that is probably still going on somewhere, must provoke a more vivid, emotional response.', NULL, NULL, E'We all now know that cameras can, and does lie, and very convincingly, despite the fact that most of us, thinking photographs as an accurate reflection of unaltered reality, still seem to trust the truth of a photographic image, and our holiday snaps tend only to bring about at most a feeling of nostalgia, with many people keeping albums to relive the better moments and news photos provoking a more vivid, emotional response.', NULL, 5, 75),
  ('750ccc51-a6ef-52f0-8f7d-8ff032d1ca6a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '750ccc51-a6ef-52f0-8f7d-8ff032d1ca6a'::uuid, 1, NULL, TRUE, 0, NULL, E'Expression', E'Expression became important during the romantic movement with artwork expressing a definite feeling, as in the sublime or dramatic. Audience response was important, for the artwork was intended to evoke an emotional response. This definition holds true today as artists look to connect with and evoke responses from their viewers.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('75138880-dbc5-537f-b415-be4296bdfabb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '75138880-dbc5-537f-b415-be4296bdfabb'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the boat that carries people from one side of a river to the other?', '2e4f081b-3ebd-5658-820b-555f95c4abd1'::uuid, NULL, NULL, E'Ferry', NULL, NULL),
  ('7514a470-fc22-55f9-9256-2045b81b9e82'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7514a470-fc22-55f9-9256-2045b81b9e82'::uuid, 1, NULL, TRUE, 0, NULL, E'Obesity', E'Some people are at higher risk of developing obesity because they possess genetic variants that affect how the brain processes sensory information and regulates feeding and behavior. The findings support a growing body of evidence that obesity is a disease whose roots are in the brain.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('751a1d1f-c94d-5888-88c5-46fbd94cabea'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '751a1d1f-c94d-5888-88c5-46fbd94cabea'::uuid, 1, NULL, TRUE, 0, NULL, E'Smaller World', E'A new book titled "A Smaller World" features vivid illustrations by {{1}} artists, interpreting conversations with leading nanotechnology researchers. The book presents futuristic scenarios where nanotechnology revolutionizes medicine, alongside detailed explanations of the science {{2}} . Its striking visuals help readers {{3}} a future where tiny machines treat diseases at the cellular level.', NULL, NULL, NULL, E'1.renowned, 2.involved, 3.envision', NULL, NULL),
  ('751f49c8-513e-5c65-bb17-4214ce7c56ba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '751f49c8-513e-5c65-bb17-4214ce7c56ba'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5cd8c674-a415-5c88-a805-ce6cc076e712'::uuid, NULL, E'The percentage of respondents who knew that the earth circles the sun once each year remained essentially unchanged.', NULL, NULL, NULL),
  ('7524ddd0-3099-542e-8bc8-f89ba362f6be'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7524ddd0-3099-542e-8bc8-f89ba362f6be'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7d956e70-9acd-55aa-9241-632ad65a6a1f'::uuid, NULL, NULL, E'You need to be able to concentrate when working or studying.', NULL, NULL),
  ('7524f968-3021-5240-8666-922bc832ef74'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '7524f968-3021-5240-8666-922bc832ef74'::uuid, 1, NULL, TRUE, 0, NULL, E'Personal Values', E'The journey of achieving success in college begins with a single step: {{1}} your personal values. Your personal values are your core beliefs and guiding {{2}} . They color your interests and passions, and {{3}} your thoughts and words. In {{4}} , your values are a compass that help you make decisions and choices.', NULL, NULL, NULL, E'1.identifying, 2.principles, 3.frame, 4.essence', NULL, NULL),
  ('75259855-0748-515a-b096-4d79afe76057'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '75259855-0748-515a-b096-4d79afe76057'::uuid, 1, NULL, TRUE, 0, NULL, E'Thermostats', E'A few years ago scientists determined that our thermostats are sexist—namely, that office climates had been optimized for a hypothetical roomful of 40-year-old, 150-pound men, using standards developed more than 50 years ago. And that ends up leaving a lot of women in the cold.\n"It''s called the battle of the thermostat, right?" Tom Chang, a behavioral economist at the USC Marshall School of Business. He says it goes beyond comfort for women: "It seems that it''s not just a matter of comfort, but it also affects their productivity."\nChang and his colleague tested that link between temperature and performance by quizzing 543 German students on basic addition skills and word scrambles in rooms that varied from 60 to 90 degrees Fahrenheit.\n"And if you went from the low 60s to the mid-70s, you saw an increase in female performance of almost 15 percent, one five not five zero, which I found remarkably large—that''s much larger than I had expected." The effects tapered off after the mid-70s. But men, on the other hand, had a small decrease in performance—about 3 percent—as temperatures rose to the mid-70s.\n\nWhat can be inferred from this passage?', '09cf62a6-da1f-5494-afb3-14c70bc96382'::uuid, NULL, NULL, E'Office thermostats were set according to standards established more than 50 years ago.\nFor women, the standardized thermostat in the office can be uncomfortable.', NULL, NULL),
  ('7528aca6-a8ca-564e-858f-f2ab49ba308a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '7528aca6-a8ca-564e-858f-f2ab49ba308a'::uuid, 1, NULL, TRUE, 0, NULL, E'Shakespeare', E'There has been a great variety of critical approach to Shakespeare''s work since his death. During the 17th {{1}} 18th centuries, Shakespeare was both admired and condemned. Since then, much of the adverse criticism {{2}} considered relevant, although certain issues have continued to interest critics throughout the years. For instance, charges against his moral propriety were made by Samuel Johnson in the 18th century and by George Bernard Shaw in the 20th.\nEarly criticism was directed primarily at questions of form. Shakespeare was {{3}} for mixing comedy and tragedy and failing to observe the unities of time and place {{4}} by the rules of classical drama. Dryden and Johnson were among the critics claiming that he had {{5}} the language with false wit, puns, and ambiguity. {{6}} some of his early plays might justly be charged with a frivolous use of such devices, 20th-century criticism has tended to praise their use in later plays as adding depth and resonance of meaning.', NULL, NULL, NULL, E'1.and, 2.has not been, 3.criticized, 4.prescribed, 5.corrupted, 6.While', NULL, NULL),
  ('752b7006-a06e-5724-9519-c7dbcfab5266'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '752b7006-a06e-5724-9519-c7dbcfab5266'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a798e772-6468-5fd0-9b1a-60804b0df982'::uuid, NULL, NULL, E'This class really helps you to think through problems better.', NULL, NULL),
  ('753932ad-e023-5ab3-90ec-6828ae44656b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '753932ad-e023-5ab3-90ec-6828ae44656b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b11ef51a-db71-5c2f-825a-1d11cc2fc023'::uuid, NULL, E'This is a practical and comprehensive guide to planning and developing a curriculum.', NULL, NULL, NULL),
  ('753e6559-774e-5753-b004-9c1eef3a51c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '753e6559-774e-5753-b004-9c1eef3a51c5'::uuid, 1, NULL, TRUE, 0, NULL, E'MCM-L', E'Woodblocks used for pictorial illustration became fairly common in 15th century Europe, but had been used long before that for printing designs on textiJes. Most of these were simple in design and quite crudely cut, but some were skillfully drawn and cut, while others even contained pictorial imagery.\nRecords show that woodblock printing on fabrics was practised by the Egyptians as early as 2000 years BC. The oldest existing printed fabric, which is Egyptian, dates from the 4th century. At the same time, the craft seems to have been widely established, even commonplace, elsewhere: for example, in India, Mexico and Peru, where the same techniques continue to be practised today. And the technique was almost certainly used by both the Japanese and the Chinese too.\n\nWhich of these countries still use woodblock printing on fabrics?', 'fb29e885-d525-586e-bd57-87c1703a3add'::uuid, NULL, NULL, E'Peru\nIndia\nMexico', NULL, NULL),
  ('7541e7a8-146a-5a89-a167-05c426b714f6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7541e7a8-146a-5a89-a167-05c426b714f6'::uuid, 1, NULL, TRUE, 0, NULL, E'Mice and Plants', E'Japanese researchers at Nagoya University have uncovered new aspects of the interaction between mast seeding plants like bamboo and field mice. Their study reveals that mice behavior, influenced by species, environment, and season, plays a crucial role in seed dispersal and forest ecosystem health, challenging existing theories about seed storage and consumption.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('75484b7a-d636-593d-bd8e-7b8a3ce2ab2e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '75484b7a-d636-593d-bd8e-7b8a3ce2ab2e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '009c280b-bc73-5be9-8aa4-910067b405fa'::uuid, NULL, NULL, E'Undergraduate students can select what interests them most in the science program.', NULL, NULL),
  ('754bfec1-8dca-5580-98d9-9bf62dce4554'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '754bfec1-8dca-5580-98d9-9bf62dce4554'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4fd370cf-2309-5d8f-8e90-941ce08e39b7'::uuid, NULL, E'His looks conveyed subtle signs of a deeper, underlying interest.', NULL, NULL, NULL),
  ('75517af1-b7ae-5c96-95b7-0626a916cc1e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '75517af1-b7ae-5c96-95b7-0626a916cc1e'::uuid, 1, NULL, TRUE, 0, NULL, E'Mutation', E'Our genes serve as an operating manual for cells of the body. Genes tell cells what to do and when. But copying errors in those operating manuals, known as mutations, can lead to misspelled instructions that can change how cells operate. Scientists now know that some of those mutations can lead to disease.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('7553fe6e-b535-5637-a524-9d326caea28c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7553fe6e-b535-5637-a524-9d326caea28c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6256003e-590c-58b6-a0ac-eee0b4e4fbcf'::uuid, NULL, NULL, E'The staff at the front desk can help you find a house.', NULL, NULL),
  ('75551a90-7785-58db-9ae0-d2fddbe9a3c3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '75551a90-7785-58db-9ae0-d2fddbe9a3c3'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for a mammal''s winter sleep?', '97e90f54-35a7-5122-8b53-6adf1dba1125'::uuid, NULL, NULL, E'Hibernation', NULL, NULL),
  ('755c0b1f-f0c0-57f9-8753-1e43e0c8b910'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '755c0b1f-f0c0-57f9-8753-1e43e0c8b910'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0f489f54-ba77-51a7-8ae1-ded20e33f7da'::uuid, NULL, NULL, E'Several candidates will be qualified as the greatest scientists of all time.', NULL, NULL),
  ('75652b79-f3ad-5f61-a397-85f9c9ca4909'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '75652b79-f3ad-5f61-a397-85f9c9ca4909'::uuid, 1, NULL, TRUE, 0, NULL, E'Community Service', NULL, '7c7d7fdf-ffc6-5838-9537-de9f6967429a'::uuid, NULL, E'Community service is an important component of education here at our university. We encourage all students to volunteer for at least one community activity before they graduate. A new community program called "One On One" helps elementary students who''ve fallen behind. Your education majors might be especially interested in it because it offers the opportunity to do some teaching, that is, tutoring in math and English. You''d have to volunteer two hours a week for one semester. You can choose to help a child with math, English, or both. Half-hour lessons are fine, so you could do a half hour of each subject two days a week. Professor Dodge will act as a mentor to the tutors. He''ll be available to help you with lesson plans or to offer suggestions for activities. He has office hours every Tuesday and Thursday afternoon. You can sign up for the program with him and begin the tutoring next week. I''m sure you''ll enjoy this community service and you''ll gain valuable experience at the same time. It looks good on your resume, too, showing that you''ve had experience with children and that you care about your community. If you''d like to sign up, or if you have any questions, stop by Professor Dodge''s office this week.', NULL, NULL, NULL),
  ('756de279-aa57-59f2-bc1d-bfac9a787ad9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '756de279-aa57-59f2-bc1d-bfac9a787ad9'::uuid, 1, NULL, TRUE, 0, NULL, E'Mindfulness', E'Feeling overwhelmed by deadlines, bills, and the endless to-do list? Stress, a constant companion in our fast-paced world, takes a {{1}} on our well-being. But mindfulness meditation offers a powerful antidote. Studies show it can lower stress hormones, leaving you feeling calmer and clearer. The benefits go beyond stress-busting. Regular practice can sharpen your focus, helping you tackle tasks with more {{2}} . It can also boost your emotional resilience, {{3}} you to handle issues with more serenity. Mindfulness isn''t a magic bullet, but a simple tool anyone can use. Unlike medication or expensive treatments, it requires no special equipment or resources. Just a few minutes each day in a quiet space can be enough to cultivate peace and {{4}} the numerous benefits.', NULL, NULL, NULL, E'1.toll, 2.ease, 3.equipping, 4.reap', NULL, NULL),
  ('7571bf9b-2c42-52c8-ab57-07a171ae9ca8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '7571bf9b-2c42-52c8-ab57-07a171ae9ca8'::uuid, 1, NULL, TRUE, 0, NULL, E'Drama', E'I do not think I am twisting the usual meaning of drama if I define it as a presentation before spectators by performers who take on roles and who interact with each other to further a story or a text intended for such presentations. This is intended as a {{1}} definition simple enough to be recalled easily. Indeed, it is so simple that I should point out that it makes one or two {{2}} that are perhaps not immediately obvious. First, to say that performers "take on roles" leaves {{3}} the possibility that they are not within the roles to other performances as such alternative phrases as "performers in character" or "characters represented by actors" do not. To say that the performers "interact with each other" might seem {{4}} , but is in fact important, for in traditional societies there are many performances in which different characters appear successively and simultaneously but, {{5}} , do not interact. And I say "to further a story" because a progression of the story may not provide the structure of the performance.', NULL, NULL, NULL, E'1.working, 2.distinctions, 3.open, 4.unnecessary, 5.nevertheless', NULL, NULL),
  ('75780941-928b-52b8-bf05-f248371d8e99'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '75780941-928b-52b8-bf05-f248371d8e99'::uuid, 1, NULL, TRUE, 0, NULL, E'Orchestra', E'Away from the rumble of Shanghai''s highways and the cacophony of the shopping districts, stroll down side streets filled with rows of tall brick {{1}} . In the early evening or on a weekend morning, you''ll hear the {{2}} of classical music {{3}} from a piano, played by a 10-year old or a grandmother in her seventies. And, {{4}} down another alley toward concrete {{5}} and you''ll hear Beethoven or Mozart flowing from a violin, or perhaps a cello, accordion or flute. In China, classical music is {{6}} as mightily as the 1812 Overture. Commanding ¥I00-200 per hour, private music {{7}} in Shanghai can readily earn more than five times the average per capita monthly income.', NULL, NULL, NULL, E'1.houses, 2.sound, 3.drifting, 4.wander, 5.skyscrapers, 6.booming, 7.teachers', NULL, NULL),
  ('757b1ae4-bb24-5eff-bfb9-22d6c8abb384'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '757b1ae4-bb24-5eff-bfb9-22d6c8abb384'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '06e51f05-87e4-5efa-bb0c-1ce085ba7754'::uuid, NULL, NULL, E'You will be tested online.', NULL, NULL),
  ('7583fb48-3c85-5b24-b74d-62b2d34450c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7583fb48-3c85-5b24-b74d-62b2d34450c0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2a751cbb-38f0-533c-884e-234461e49b20'::uuid, NULL, E'Students are required to complete their assignments in the coming month.', NULL, NULL, NULL),
  ('758686e4-b2c4-53cb-bec5-d287b6463f72'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '758686e4-b2c4-53cb-bec5-d287b6463f72'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What will you use for moving a small boat, especially a canoe?', '3090a5eb-31d4-5c11-abf2-fce69af1ed67'::uuid, NULL, NULL, E'Paddle', NULL, NULL),
  ('7591d7bd-c1e6-560f-85c6-620d3e55a847'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7591d7bd-c1e6-560f-85c6-620d3e55a847'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the fruit with a green skin and soft, buttery texture inside, often used in guacamole?', '98a3c510-de02-551d-b0e5-90b4eb8784ee'::uuid, NULL, NULL, E'Avocado', NULL, NULL),
  ('7592ccc4-b9f8-5656-8e59-635f9d089e0b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7592ccc4-b9f8-5656-8e59-635f9d089e0b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7e3bb993-e35c-5d6a-95af-c882e5a27050'::uuid, NULL, NULL, E'Schools teach you the important skills you need for jobs.', NULL, NULL),
  ('75a07884-a66e-5518-bfde-461424d7e3ce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '75a07884-a66e-5518-bfde-461424d7e3ce'::uuid, 1, NULL, TRUE, 0, NULL, E'Eastern Europe', E'The term “Eastern Europe” suggests a self-contained world of kindred regions. This is a fiction, and to some extent we can reconstruct precisely how it originated. It may be founded on older images of Russia, but it goes back primarily to the French Enlightenment. For centuries before that, the only cultural and political axis of significance had been the north-south divide. Following the Renaissance, the “barbaric” regions north of the Alps sought to appropriate the political and cultural legacy of the Roman Empire. This led to the development – in parallel with colonialism – of competing notions of what constituted the center of the “civilized” world.\nThe impetus for a shift to a west-east cultural axis came from Paris around the middle of the 18th century, when French Enlightenment thinkers pronounced the orient – which combines the geographical “east” with proximity to the “orient” – to be that region that remained closed to the French or European Enlightenment.\nThe east-west axis marked out a descent from the center of enlightened civilization into less and less civilized zones. For travelers, the road to the East, from its supposed beginnings in Poland, Hungary, or Galicia, became a voyage into increasingly Asiatic zones. In the process, perceptions were adapted, sometimes in highly fanciful ways, to fit in with the preconceived expectation of encountering a lower level of civilization. Barbarism was now located in the East.\nIt was only with the emergence of this idea that outsiders started to view Eastern Europe as a single entity. The “West” asserted the right to define the prevailing level of civilization in different regions, and increasingly Europe defined itself against the areas to its east. In this context, it was easy to ignore that even the more westerly regions did not consist solely of urban centers of modernization, characterized by refined behavior.', NULL, NULL, NULL, NULL, 5, 75),
  ('75a82767-a913-5824-a569-63edde19d38a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '75a82767-a913-5824-a569-63edde19d38a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '156de9dc-e197-5d8d-8375-6e3c3e86cd6f'::uuid, NULL, E'The seven industrial countries will have their yearly meeting in London.', NULL, NULL, NULL),
  ('75b3a4c6-fd0d-58e1-a5e9-53e83338afd1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '75b3a4c6-fd0d-58e1-a5e9-53e83338afd1'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '1eb31b0b-a72d-5510-8ec6-db8c83b61c5b'::uuid, NULL, E'This small Indian state is a land of forests, valleys and snowy islands.', NULL, NULL, NULL),
  ('75b85988-371b-5ce0-99ad-cbd23e942b36'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '75b85988-371b-5ce0-99ad-cbd23e942b36'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e419855f-70fd-5bcc-af88-fdfd3841849e'::uuid, NULL, NULL, E'A number of assignments will be submitted to the conference.', NULL, NULL),
  ('75b8b7bf-ef5a-5dd7-9fda-881e19abf056'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '75b8b7bf-ef5a-5dd7-9fda-881e19abf056'::uuid, 1, NULL, TRUE, 0, NULL, E'Ageing Population', E'There’s one thing for certain — we’re all getting older. However, as the world population ages, will there be enough people to replace our younger selves? A situation where there are more old people than young certainly has an effect on the world. A report by the Pew Research Center says that globally the number of people over 65 years old will triple by 2050, drastically altering some countries’ demographic make-up.\nThis growing and dependent population means that there is an increased demand for health and social care. Governments will struggle to provide satisfactory pensions, which are ultimately funded by taxes paid by the working population. And in a long-term, a smaller population of economically-active people may be a problem for companies trying to recruit staff.\nAttitudes to an ageing population vary around the world. Some countries thought the elderly should take care of themselves, while others thought it was the responsibility of the family. Many thought the government should be responsible.\nBut old age shouldn’t just be seen negatively. Elderly people have knowledge and experience they can pass on. Some have wealth which they can spend, helping the economy. And some help society by doing voluntary or charity work. Of course, solutions are needed to tackle the issue, and these include increasing the retirement age, encouraging people to save for the future, persuading skilled and educated migrants to fill labour shortages, or even convincing people to have more children.', NULL, NULL, NULL, NULL, 5, 75),
  ('75bb0945-df7c-54f9-8d53-3f646f726e05'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '75bb0945-df7c-54f9-8d53-3f646f726e05'::uuid, 1, NULL, TRUE, 0, NULL, E'Activity Preference', E'You''re organizing a team-building event for your colleagues, and one suggestion is to participate in an escape room activity. However, you realize that some team members may feel uncomfortable or anxious in enclosed spaces. What would you say to your colleagues?', '59c8cdfb-7422-5a6a-899e-9a0b62f0e06a'::uuid, NULL, E'While the escape room idea sounds fun, let''s consider everyone''s comfort. How about we explore outdoor activities like a team picnic in the park, a friendly sports match, or even a creative workshop where everyone can express themselves freely? By offering a variety of options, we ensure that everyone can participate comfortably and enjoyably, fostering stronger team bonds without leaving anyone out. Let''s brainstorm more ideas together to find the perfect fit for our team!', NULL, NULL, NULL),
  ('75bb497f-e99a-52c5-9ac4-eb8335b8ced3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '75bb497f-e99a-52c5-9ac4-eb8335b8ced3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7bbc3d4d-557a-5545-a240-7dfd5fda9918'::uuid, NULL, E'Every living thing begins as a single cell.', NULL, NULL, NULL),
  ('75bfc9e1-025d-5789-ab67-43808c74faab'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '75bfc9e1-025d-5789-ab67-43808c74faab'::uuid, 1, NULL, TRUE, 0, NULL, E'Bhutan', E'Bhutan is the last standing Buddhist Kingdom in the World and, until recently, has preserved much {{1}} their culture since the 17th century by avoiding globalization and staying isolated from the world. Internet, television, and western dress were {{2}} from the country up until ten years ago. But over the past ten years globalization has begun to change in Bhutan, but things remain perfectly balanced.\nBhutan is the only country in the world that has a ''GNH.'' You may think GNH is just another {{3}} based term with no real-life application, but it refers to "Gross National Happiness." The process of measuring GNH began when Bhutan opened to globalization. It measures people''s quality of life, and makes sure that "material and spiritual development happen together." Bhutan has done an amazing Job of finding this balance. Bhutan has continually been ranked as the happiest country in all of Asia, and the eighth Happiest Country in the world according to Business Week. In 2007 Bhutan had the second fastest growing GDP in the world, at the same time as {{4}} their environment and cultural identity.', NULL, NULL, NULL, E'1.of, 2.banned, 3.statistically, 4.maintaining', NULL, NULL),
  ('75c2f941-075e-562d-8ff8-57a808199976'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '75c2f941-075e-562d-8ff8-57a808199976'::uuid, 1, NULL, TRUE, 0, NULL, E'Control of Genes', E'Scientists have discovered a way that bacteria in the gut can control genes in our cells. Their work shows that chemical messages from bacteria can alter chemical markers throughout the human genome. The signal chemicals are made when bacteria digest fruits and vegetables. By communicating in this way, the bacteria may help to fight infections and to prevent cancer.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('75cea082-51b6-58d3-9f81-e7bd664b75cf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '75cea082-51b6-58d3-9f81-e7bd664b75cf'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the force that opposes the relative motion of two surfaces in contact?', 'd074a056-df6f-5563-a21e-cbe871432137'::uuid, NULL, NULL, E'Friction', NULL, NULL),
  ('75d19e0b-be25-528d-ba5a-81cd6337b173'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '75d19e0b-be25-528d-ba5a-81cd6337b173'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7cfb0182-0a10-5134-b1a1-09077c79b433'::uuid, NULL, E'Experts have made some assumptions based on students'' study habits.', NULL, NULL, NULL),
  ('75d1c6cd-616e-53e9-8c47-304cb91af334'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '75d1c6cd-616e-53e9-8c47-304cb91af334'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'fc3ac5b8-689c-5ed1-af43-efad69260ede'::uuid, NULL, E'Unlike applied arts, fine arts do not serve a practical function.', NULL, NULL, NULL),
  ('75d3921f-ecf1-5c9d-a23f-9627c4fd7443'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '75d3921f-ecf1-5c9d-a23f-9627c4fd7443'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8831a4b0-aac6-554d-986e-2756dbd85862'::uuid, NULL, E'Write a case study detailing an organization you''re familiar with, please.', NULL, NULL, NULL),
  ('75d468d4-69a8-5456-8114-417e0e99dbad'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '75d468d4-69a8-5456-8114-417e0e99dbad'::uuid, 1, NULL, TRUE, 0, NULL, E'Medicare', E'It is understandable that the government would look outside of Medicare to get the efficiency-related revolutions it {{1}} . If Medicare was capable of delivering those {{2}} , it would have already done so. Finding another organization that can deliver these services at a {{3}} cost with increased functionality, especially to the consumer of these services, makes absolute sense. The objections to making such a move will be about the potential loss of {{4}} from Medicare. Given how labour-intensive the current system is, this will be a {{5}} concern, but one that is facing all industries dealing with modernization through improved technology.', NULL, NULL, NULL, E'1.wants, 2.changes, 3.reduced, 4.jobs, 5.genuine', NULL, NULL),
  ('75dc079f-a35b-5fc4-b877-c27d5196ef2f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '75dc079f-a35b-5fc4-b877-c27d5196ef2f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0714b381-0b18-5e8c-8608-a7902a0e4230'::uuid, NULL, NULL, E'Readers are required to observe the rules of the library.', NULL, NULL),
