  ('75df6054-e7ba-54a8-a037-9684a79585c3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '75df6054-e7ba-54a8-a037-9684a79585c3'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person who takes care of children when their parents are at work?', '1ba2f5db-b103-54b0-8e8f-b4ab9ce076f2'::uuid, NULL, NULL, E'Babysitter / nanny / childminder', NULL, NULL),
