  ('75ea2098-5708-5aba-833b-79991f8fb0b1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '75ea2098-5708-5aba-833b-79991f8fb0b1'::uuid, 1, NULL, TRUE, 0, NULL, E'Recycling Plastics', E'The proliferation of plastic waste is a global concern, with millions of tons of non-biodegradable materials {{1}} up in landfills and oceans annually. Recycling efforts are crucial in {{2}} this issue, yet they face challenges {{3}} the variety of plastics and the complexity of processing them. Innovations in bioplastics and recycling technologies hold promise for reducing the environmental footprint of plastic production and waste, {{4}} the need for a shift towards a more sustainable circular economy.', NULL, NULL, NULL, E'1.ending, 2.mitigating, 3.due to, 4.emphasizing', NULL, NULL),
  ('75ef257c-e027-5335-aa64-352bde12f132'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '75ef257c-e027-5335-aa64-352bde12f132'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'fee49a94-a017-53c7-a164-956c8a8a9a59'::uuid, NULL, NULL, E'Storms can be dangerous in some regions.', NULL, NULL),
