  ('75fa20de-1343-50da-bc63-715a0e4d5bc2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '75fa20de-1343-50da-bc63-715a0e4d5bc2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '748f3093-c0a6-57a3-ac25-4e78b80caef5'::uuid, NULL, NULL, E'Brain disorders have gradually become an increasing public health concern.', NULL, NULL),
  ('76015e9c-3bc2-5d72-9354-ca406d814cb6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '76015e9c-3bc2-5d72-9354-ca406d814cb6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9b5851be-c5f7-5bb8-8de7-d3a6c31b1163'::uuid, NULL, E'Social work is not the only subject in sociology.', NULL, NULL, NULL),
  ('7609d078-b6f9-5aab-9b7d-6709395a4671'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '7609d078-b6f9-5aab-9b7d-6709395a4671'::uuid, 1, NULL, TRUE, 0, NULL, E'Rosalid Franklin', E'Rosalind Franklin''s contributions to the discovery of DNA''s structure remain one of the most compelling narratives in the annals of scientific research. Born in 1920 in London, Franklin was a gifted scientist whose work in X-ray crystallography was instrumental in understanding the molecular structure of DNA.\nFranklin''s journey in science began at Cambridge University, where her passion for chemistry and physics blossomed. Her most significant work unfolded at King''s College London, where she used X-ray diffraction methods to study DNA. Franklin''s photographs, particularly Photo 51, revealed critical clues about DNA''s structure. Her images showed DNA to be a double helix, a discovery that was pivotal to the work of James Watson and Francis Crick, who later won the Nobel Prize for this groundbreaking finding.\nDespite her crucial role, Franklin''s contributions were overshadowed in a male-dominated field, and her work was only fully recognized posthumously. She faced gender-based discrimination, yet remained undeterred in her pursuit of scientific excellence. Franklin''s dedication to her research was unwavering, even as she battled ovarian cancer, which tragically cut her life short at the age of 37.\nToday, Rosalind Franklin is celebrated as a pioneering figure in molecular biology. Her legacy lives on, not only in the realm of DNA research but also as an inspiration for women in science. She broke barriers and paved the way for future generations of female scientists, showing the world the invaluable contributions women can make in the field of science and research.\nIn conclusion, Rosalind Franklin''s story is a poignant reminder of the unrecognized heroes in scientific discovery. Her determination, expertise, and significant findings in DNA structure have left an indelible mark on the world of science and medicine.', NULL, NULL, E'Rosalind Franklin, a pioneering figure in molecular biology, played a crucial yet underrecognized role in discovering DNA''s structure through her expertise in X-ray crystallography, overcoming gender-based barriers and leaving a lasting impact on science and an inspirational legacy for women in scientific research.', NULL, 5, 75),
  ('7611d4eb-6bee-5cb6-b35d-88d4eb206041'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7611d4eb-6bee-5cb6-b35d-88d4eb206041'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the starchy, tuberous crop often fried or mashed?', '56d8a24d-5cac-5b9b-9169-b1b5d9769d88'::uuid, NULL, NULL, E'Potato', NULL, NULL),
  ('76192467-ae38-5567-8363-53b653915f73'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '76192467-ae38-5567-8363-53b653915f73'::uuid, 1, NULL, TRUE, 0, NULL, E'Marshmallow Test', E'Mischel is the creator of the marshmallow test, one of the most famous experiments in the history of psychology, which is often cited as evidence of the importance of self-control. In the original test, which was administered at the Bing Nursery School, at Stanford, in the nineteen-sixties, Mischel''s team would present a child with a treat (marshmallows were just one option) and tell her that she could either eat the one treat {{1}} or wait alone in the room for several minutes until the researcher returned, at which point she could have two treats. The promised treats were always visible and the child knew that all she had to do to stop the agonizing wait was ring a bell to call the experimenter back – although in that {{2}} , she wouldn''t get the second treat. The longer a child delayed gratification, Mischel found – that is, the longer she was able to wait – the better she would fare later in life at numerous measures of what we now call executive function. She would {{3}} better academically, earn more money, and be healthier and happier. She would also be more likely to avoid a number of negative outcomes, including jail time, obesity, and drug use .', NULL, NULL, NULL, E'1.immediately, 2.case, 3.perform', NULL, NULL),
  ('76192e28-43f2-505b-8420-e932e400c4c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '76192e28-43f2-505b-8420-e932e400c4c6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e721e7c4-d0e2-575e-a76a-d9a44b8bafb2'::uuid, NULL, E'A moderate earthquake struck the United States early on Saturday.', NULL, NULL, NULL),
  ('76205e76-3ff3-5066-af55-64824130a7e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '76205e76-3ff3-5066-af55-64824130a7e1'::uuid, 1, NULL, TRUE, 0, NULL, E'Injury or Disease', E'Injury or disease that afflicts a relatively small number of brain cells causes a chain reaction that stops activity across a vast network of neural circuits, according to new research. The study may help to explain why people can suffer from temporary but severe loss of cognitive function in cases of traumatic brain injury or disease.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('762088b0-fd13-585f-bf81-a87e7ee03510'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '762088b0-fd13-585f-bf81-a87e7ee03510'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bb9c2d84-d704-50c1-b9ce-266966a9045f'::uuid, NULL, E'This parking space is for the employee of the month.', NULL, NULL, NULL),
  ('7621ab8c-07f6-57a2-b840-dda801068ca9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7621ab8c-07f6-57a2-b840-dda801068ca9'::uuid, 1, NULL, TRUE, 0, NULL, E'Toy Play', E'There is ample evidence that toy play is a very important aspect of child development. Children of all ages enjoy playing with toys and the different roles they play in their fantasy and make-believe games, but toys are more than simple playthings. Many toys offer hands-on learning opportunities that can instill basic skills that will benefit them for the rest of their lives.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('7624b5c4-2207-53aa-89f5-acf5d339111a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '7624b5c4-2207-53aa-89f5-acf5d339111a'::uuid, 1, NULL, TRUE, 0, NULL, E'Talent Recruitment', E'The demand for workers in the US is {{1}} the supply, and finding the best talent is going to be increasingly difficult as the world navigates a period of heightened economic uncertainty. Despite the need for {{2}} our existing talent strategies to keep pace, employers have been slow to move on what we see as the most sustainable way to hire and grow more effective, engaged workforces: hiring for skills, instead of just relying on pedigree. In this age of uncertainty, when companies {{3}} skills (not degrees or “who you know”), they can build a more agile workforce that has gained experiences via many different routes, which can help to avoid “group-think” and lead to more dynamic teams. Recognizing the diverse ways skills are acquired and {{4}} a skills-first approach to talent will bring greater transparency, efficiency and equity to the labor market, making it easier for anyone from anywhere to achieve anything.', NULL, NULL, NULL, E'1.outpacing, 2.revamping, 3.prioritize, 4.adopting', NULL, NULL),
  ('7628e19f-e599-5a1d-afc9-629d824d8af4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7628e19f-e599-5a1d-afc9-629d824d8af4'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e35aebf1-bfd3-593e-8399-ae2476123071'::uuid, NULL, E'Regular consumption of junk food can have adverse effects on one''s health.', NULL, NULL, NULL),
  ('76357d6d-43e4-5491-8672-47d0d6aef8f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '76357d6d-43e4-5491-8672-47d0d6aef8f9'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What general part of the day is known as dawn?', 'ab7f54b5-3b4f-5d81-9559-8cb56edac884'::uuid, NULL, NULL, E'Sunrise / sunrises / daybreak', NULL, NULL),
  ('76381a4d-7762-5c76-a16c-41bcb15dbc0e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '76381a4d-7762-5c76-a16c-41bcb15dbc0e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '919553b8-f72e-5014-b15c-35dc447463e2'::uuid, NULL, E'Whether other animals can dream or not is still unclear.', NULL, NULL, NULL),
  ('763bed8e-a7de-52ea-94f3-2c218e83ebab'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '763bed8e-a7de-52ea-94f3-2c218e83ebab'::uuid, 1, NULL, TRUE, 0, NULL, E'Help Other People', E'There are many different ways to help other people. Perhaps the most common of these involves giving others {{1}} help. In our society, there are many individuals who spontaneously help others in this way. Additionally, there are others who belong to organizations which have been set up to provide help to specific groups, such as the elderly, the disabled, and those with serious physical or {{2}} health problems. Most importantly, there are many {{3}} , such as nursing, occupational therapy and social work, which involve professionals who are trained to provide or organize practical help for others. {{4}} helping other people in a practical way, many volunteer and professional helpers also make use of some counselling skills. These skills can be very useful in enabling people to feel better as described in this book and our book, Counselling Skills in Everyday Life. However, it needs to be {{5}} that just being able to make use of some counselling skills does not qualify a person as a counsellor.', NULL, NULL, NULL, E'1.practical, 2.mental, 3.occupations, 4.While, 5.recognized', NULL, NULL),
  ('763f6cbf-1e27-556f-a7c8-1af5a4393e3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '763f6cbf-1e27-556f-a7c8-1af5a4393e3c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What device is used to measure a 200-meter sprint?', '085bb5a6-a2fd-5f1c-8c75-1055dbfcd80b'::uuid, NULL, NULL, E'Stopwatch', NULL, NULL),
  ('7648702f-c378-5b08-8c7d-c5496f86f058'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7648702f-c378-5b08-8c7d-c5496f86f058'::uuid, 1, NULL, TRUE, 0, NULL, E'Farewell Gift', E'Your manager Joe is about to retire and he is going to travel in another country. You want to give him a farewell gift. How should you discuss with your colleagues what gift to prepare for the manager?', '29ad8f0d-b22c-5c08-a114-d3e2082a4304'::uuid, NULL, E'Hey guys, I want to talk to you about something.\nWe seem to have a little issue with the farewell gift for our manager Joe.\nIt''s like Joe will retire and travel abroad, and I want to figure out a proper gift for him together with all of you.\nAnd I''d like to know what you think.', NULL, NULL, NULL),
  ('7648ed32-1059-5b14-b995-ea86708e19e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '7648ed32-1059-5b14-b995-ea86708e19e1'::uuid, 1, NULL, TRUE, 0, NULL, E'Gamification', E'Gamification refers to the integration of game-like elements into non-game environments, particularly in the workplace, to drive engagement and {{1}} . It involves using mechanics such as points, badges, leaderboards, and challenges to make tasks more engaging, rewarding, and fun. The primary goal of gamification is to inspire employees to perform better, work more collaboratively, and meet their objectives while feeling {{2}} for their efforts. To be effective, gamification needs to be thoughtfully {{3}} . It should align with company goals and be tailored to the needs of employees. Overuse or poorly designed gamification systems can backfire, leading to stress or disengagement. Successful gamification strategies tap into intrinsic motivation, offering employees meaningful rewards, fostering a sense of achievement, and encouraging healthy {{4}} . The key is to ensure the game elements enhance the workplace experience rather than distract from it. Kevin Werbach, a professor at the Wharton School of the University of Pennsylvania, is a leading expert on gamification. Through his research and teaching, Werbach has explored how businesses can apply these game mechanics to increase employee motivation and {{5}} .', NULL, NULL, NULL, E'1.motivation, 2.acknowledged, 3.implemented, 4.competition, 5.performance', NULL, NULL),
  ('764b0c39-f34f-5df4-8df3-01eef238ff85'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '764b0c39-f34f-5df4-8df3-01eef238ff85'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd6bb1205-a901-5b7b-997d-faec5644618d'::uuid, NULL, E'He was a mediocre scholar who loved poetry, science and travel books.', NULL, NULL, NULL),
  ('764cfb74-8856-564f-b991-7861fb94546c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '764cfb74-8856-564f-b991-7861fb94546c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ae39d615-7a2b-53ba-8941-1841b4f682a3'::uuid, NULL, NULL, E'Football is played all year at the university.', NULL, NULL),
  ('764e3df6-670f-5e6c-83af-483439bf689f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '764e3df6-670f-5e6c-83af-483439bf689f'::uuid, 1, NULL, TRUE, 0, NULL, E'Edison', E'Thomas Alva Edison was both a scientist and an inventor. Born in 1847, Edison would see {{1}} changes take place in his lifetime. He was also to be responsible for making many of those changes occur. When Edison was born, society still thought of electricity as a {{2}} , a fad.\nBy the time he died, entire cities were lit by electricity. Much of the credit for that progress goes to Edison. In his lifetime, Edison patented 1,093 inventions, earning him the nickname “The Wizard of Menlo Park.” The most famous of his inventions was the incandescent light bulb. Besides the light bulb, Edison {{3}} the phonograph and the “kinetoscope,” a small box for viewing moving films.\nThomas Edison is also the first person in the US to make his own filmstrips. He also {{4}} upon the original design of the stock ticker, the telegraph, and Alexander Graham Bell’s telephone. He believed in hard work, sometimes working twenty hours a day. Edison was quoted as saying, “Genius is one percent inspiration and 99 percent perspiration.” In {{5}} to this important American, electric lights in the United States were dimmed for one minute on October 21, 1931, a few days after his death.', NULL, NULL, NULL, E'1.tremendous, 2.novelty, 3.developed, 4.improved, 5.tribute', NULL, NULL),
  ('765a4722-ce4d-5b98-b939-b516aaf7b875'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', '765a4722-ce4d-5b98-b939-b516aaf7b875'::uuid, 1, NULL, TRUE, 0, NULL, E'Spending on Experiences', E'Buying time is often seen as one of the best ways to spend your money in that it allows you to focus on the most joyous aspects, while offloading the more laborious aspects to someone else who will happily do them. The gig economy has made this more accessible than ever before – allowing people to spend more of their time for the things that truly matter, even if it means having a little less in the bank account. This might mean paying someone to do the dishes so you can read a book to your child in bed, or it could mean purchasing a more expensive ticket to be able to spend some time with family. Material possessions also draw a lot of attention when it comes to the relation between wealth and happiness. The research is clear on this too – spend on experiences, not things. The reason is that experiences are exclusive, nobody can feel what you felt on that trip with your best friend. Nobody can buy that ...\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '5d0c920d-f8e7-5ffe-8e39-052353d2b902'::uuid, NULL, NULL, E'exclusivity', NULL, NULL),
  ('76651ceb-36ca-50f2-9267-ccd4e13faa84'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '76651ceb-36ca-50f2-9267-ccd4e13faa84'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '69754479-9e5d-5094-a7f1-2d65d181cbcd'::uuid, NULL, NULL, E'Students should keep track of their own grades and work.', NULL, NULL),
