  ('768f057a-747a-5a6c-9256-e0839ac52760'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '768f057a-747a-5a6c-9256-e0839ac52760'::uuid, 1, NULL, TRUE, 0, NULL, E'Pocket Money', E'Giving pocket money to children as young as four or five years helps them start learning about the value of money and money management. When children get pocket money, they have to make choices about spending or saving. Pocket money can also help children learn about consequences, including the consequences of losing money or spending it unwisely. Letting your children make a few mistakes is part of the learning process.', NULL, NULL, NULL, NULL, NULL, NULL),
