  ('769cd94f-6f1e-5c58-b5be-f8a6ad667dda'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '769cd94f-6f1e-5c58-b5be-f8a6ad667dda'::uuid, 1, NULL, TRUE, 0, NULL, E'Caspian Sea', E'The salinity of the Caspian Sea is one of its most intriguing aspects, with levels significantly lower than that of the world''s oceans, averaging about one-third the salinity of seawater. This reduced salinity is due to the large {{1}} of fresh water it receives from rivers, particularly the Volga, which {{2}} contributes about 80% of the incoming water. However, the Caspian Sea''s salinity is not {{3}} throughout; it varies from north to south, being lower in the northern parts due to the greater influx of river water and higher in the southern parts due to higher evaporation rates. These differences in salinity {{4}} the distribution of marine life and the ecological balance of the Caspian basin, making it a unique environment for researchers studying the impacts of salinity on aquatic ecosystems.', NULL, NULL, NULL, E'1.volume, 2.alone, 3.uniform, 4.affect', NULL, NULL),
  ('769f67cf-eda7-54ac-a41f-2ad18de6ba17'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '769f67cf-eda7-54ac-a41f-2ad18de6ba17'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4b38879d-7c41-5a1e-af15-6afa7be549aa'::uuid, NULL, NULL, E'There has been no response to his remarks from the government.', NULL, NULL),
