  ('76bb37b9-4293-5d22-b167-2a4f47b9c917'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '76bb37b9-4293-5d22-b167-2a4f47b9c917'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f8397368-9806-50e4-95cc-15d57e39fdb7'::uuid, NULL, NULL, E'Doing exercises regularly is really good for your health.', NULL, NULL),
  ('76c098ab-a66e-5e4d-b74a-fac58ee3b5a3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '76c098ab-a66e-5e4d-b74a-fac58ee3b5a3'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for an instrument used to measure atmospheric pressure?', '9a8953cd-b524-5353-bcfb-2d7f163430ec'::uuid, NULL, NULL, E'Barometer', NULL, NULL),
  ('76c766b0-6327-5679-97a7-3fc98df8bd94'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '76c766b0-6327-5679-97a7-3fc98df8bd94'::uuid, 1, NULL, TRUE, 0, NULL, E'Most Important Things', E'Food is one of the most important things you''ll ever buy. And yet most people never bother to think about their food and where it comes from. People spend a lot more time worrying about what kind of blue jeans to wear, what kind of video games to play, what kind of computers to buy.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('76d061a1-3ffe-5a33-a305-34b831f964e7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '76d061a1-3ffe-5a33-a305-34b831f964e7'::uuid, 1, NULL, TRUE, 0, NULL, E'Fin Whale Songs', E'Fin whale songs contain signals that are reflected and refracted within the crust, including the sediment and the solid rock layers beneath. These signals, recorded on seismometers on the ocean bottom, can be used to determine the thickness of the layers as well as other information relevant to seismic research.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('76d410ce-7b26-5eb6-b529-8732e0e78009'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '76d410ce-7b26-5eb6-b529-8732e0e78009'::uuid, 1, NULL, TRUE, 0, NULL, E'Matter Transport', E'"Beam me up, Scotty!" It''s one of the most famous lines in the "Star Trek" franchise and refers to the {{1}} matter transportation device or "transporter" on every ship in the galaxy. The transporter dematerializes entire humans (and other objects) and sends their constituent particles to another destination where they are perfectly {{2}} .The best thing to come to personal point-to-point transportation since the elevator, this technology seemed to have been {{3}} by every civilization in the show. Will it ever be possible to develop such technology? Recent technology has made it possible to transport, or "beam" if you will, small pools of particles or photons from one location to another. This quantum mechanics phenomenon is known as "quantum transport." The process does have future {{4}} in many electronics such as advanced communication technologies. Applying the same technique to something as large and complex as a living human being is a very different matter.', NULL, NULL, NULL, E'1.futuristic, 2.reassembled, 3.adopted, 4.applications', NULL, NULL),
  ('76d4e5a2-b98e-5f40-acee-637486f128f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '76d4e5a2-b98e-5f40-acee-637486f128f8'::uuid, 1, NULL, TRUE, 0, NULL, E'Power of Travel', NULL, '0d4c05cd-f02b-5959-a75e-1b77043bd6fc'::uuid, NULL, E'The transformative power of travel in personal growth is significant. Travel is more than a leisure activity; it''s a journey of education and self-discovery. Travel broadens our horizons. Stepping out of our comfort zones exposes us to different cultures and lifestyles. For example, visiting diverse countries introduces us to new languages, customs, and values, offering lessons beyond any textbook. Additionally, travel enhances adaptability and independence. It often presents unexpected challenges, like navigating language barriers or unfamiliar streets. Overcoming these hurdles teaches us to make decisions and adapt quickly. Travel is a potent tool for personal development. It not only offers entertainment but also teaches survival and growth in unfamiliar environments. So, I encourage you all, when the opportunity arises, to travel and explore our beautiful and vast world.', NULL, NULL, NULL),
  ('76d6fa79-13ae-5334-944c-b00685ea0e56'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '76d6fa79-13ae-5334-944c-b00685ea0e56'::uuid, 1, NULL, TRUE, 0, NULL, E'Sharing the Cost', E'You live in the same building as your colleague Mike, and if you and Mike each drive to work, you both have to pay the company for parking. You want to commute to work with him every day and share the cost. What would you say to him?', 'f1348ec7-449e-5108-a0a6-4cb3c3fc05f8'::uuid, NULL, E'Hi Mike, since we live in the same building and both drive to work, I was wondering if we could commute together every day.\nWe could share the parking cost, which would save both of us some money.\nIt would also be more convenient and give us a chance to chat on the way.\nWhat do you think?', NULL, NULL, NULL),
  ('76d9d728-2c28-5dc9-82fd-75b733b4556c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '76d9d728-2c28-5dc9-82fd-75b733b4556c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7494a18b-a9e7-5fe3-bed6-eac99e2e8c77'::uuid, NULL, NULL, E'The exam will not be posted until further notice.', NULL, NULL),
