  ('7704fa05-6b2b-5c65-81f8-d6d30f96b923'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7704fa05-6b2b-5c65-81f8-d6d30f96b923'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6e9c5769-fe14-59d5-b23b-bd51dfb3d050'::uuid, NULL, NULL, E'Our class will be divided into two groups: you will come with me, and the others will stay here.', NULL, NULL),
  ('770d7641-3049-5146-b8ea-bfc76f63a3d0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '770d7641-3049-5146-b8ea-bfc76f63a3d0'::uuid, 1, NULL, TRUE, 0, NULL, E'Friends', E'The people we know resemble us in the most basic social characteristics, such as gender and educational background. Although our friends tend to be similar, many people are unaware of this because they did not pick their friends for their similarity. Our social connections depend first and foremost on whom we get to meet. This depends on the social contexts we enter and the activities we engage in.', NULL, NULL, NULL, NULL, NULL, NULL),
