  ('77f0b69d-ef95-5172-8744-eb6bc471a81d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '77f0b69d-ef95-5172-8744-eb6bc471a81d'::uuid, 1, NULL, TRUE, 0, NULL, E'Bookkeeper Fraud', E'A national study into fraud by bookkeepers employed at small and medium-sized businesses has uncovered 65 instances of theft in more than five years, with more than thirty one million dollars stolen. Of the cases identified by the research, 56 involved women and nine instances involved men. However, male bookkeepers who defrauded their employer stole three times, on average, the amount that women stole.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('77fbe194-87c6-54ae-9a2e-3e881ce39fab'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '77fbe194-87c6-54ae-9a2e-3e881ce39fab'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2b318939-92c4-5661-8eab-09a33b4fbb3b'::uuid, NULL, E'My favorite sports are soccer, tennis and basketball.', NULL, NULL, NULL),
  ('77fec839-ef35-5cde-94fc-50d922feb8c1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '77fec839-ef35-5cde-94fc-50d922feb8c1'::uuid, 1, NULL, TRUE, 0, NULL, E'Success', E'"Most people think success comes from surrounding yourself with others that are like you," says Johansson. "But true success and breakthrough {{1}} involves discomfort. Discomfort pushes you to {{2}} . This is {{3}} difference of experience, opinion, and perspective come in. Diversity is a well-documented pathway to unlocking new {{4}} , overcoming new challenges, and {{5}} new insights."', NULL, NULL, NULL, E'1.innovation, 2.grow, 3.where, 4.opportunities, 5.gaining', NULL, NULL),
  ('780682fd-eb7c-57be-98f8-07c090998c2a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '780682fd-eb7c-57be-98f8-07c090998c2a'::uuid, 1, NULL, TRUE, 0, NULL, E'Carbon Dioxide', E'The greenhouse gas is the primary pollutant {{1}} for climate change. Not only are scientists, leaders, and activists trying to {{2}} its production, but they also want to {{3}} it directly from the air and lock it underground where it will do less harm.', NULL, NULL, NULL, E'1.responsible, 2.halt, 3.capture', NULL, NULL),
  ('78073923-a177-576d-b2b7-b66a88b56408'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '78073923-a177-576d-b2b7-b66a88b56408'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8e8e23a9-b2f4-50c9-bde4-c37abe0778b5'::uuid, NULL, E'The assignment should be submitted prior to the spring break.', NULL, NULL, NULL),
