  ('7808e573-29a8-546b-a95a-90e11ca521f4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '7808e573-29a8-546b-a95a-90e11ca521f4'::uuid, 1, NULL, TRUE, 0, NULL, E'Mobile Devices', E'There are more negative impacts than benefits of people using mobile devices. Do you agree?', NULL, NULL, NULL, NULL, 200, 300),
  ('780d9e61-ed60-59f5-b190-a2874eb24156'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '780d9e61-ed60-59f5-b190-a2874eb24156'::uuid, 1, NULL, TRUE, 0, NULL, E'Global Textile Industry', E'The environmental impact of the global textile industry is hard to overstate. One-third of the water used worldwide is spent fashioning fabrics. For every ton of cloth {{1}} , 200 tons of water is polluted with chemicals and heavy metals. An estimated 1 trillion kilowatt-hours of electricity powers the factories that card and comb, spin and weave, and cut and stitch materials into everything from T-shirts to towels, {{2}} behind mountains of solid waste and a massive carbon footprint.\n''Where the industry is today is not really sustainable for the long term,'' says Shreyaskar Chaudhary, chief executive of Pratibha Syntex, a textile manufacturer based outside Indore, India.\nWith something of an ''if you build it, they will come'' attitude, Mr.Chaudhary has steered Pratibha {{3}} the leading edge of eco-friendly textile production. Under his direction, Pratibha began making clothes with organic cotton in 1999. Initially, the company couldn''t find enough organic farms growing cotton in central India {{4}} its factories. To meet production demands, Chaudhary''s team had to convince conventional cotton farmers to change their growing methods. Pratibha provided seeds, cultivation instruction, and a guarantee of fair-trade prices for {{5}} crops. Today, Pratibha has a network of 28,000 organic cotton growers across the central states of Madhya Pradesh, Maharashtra, and Orissa.', NULL, NULL, NULL, E'1.produced, 2.leaving, 3.toward, 4.to supply, 5.their', NULL, NULL),
  ('78129a8c-26fa-5863-b5fe-4d959c2c8536'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '78129a8c-26fa-5863-b5fe-4d959c2c8536'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f336aa2a-0a3e-5029-8037-a90936de2cb9'::uuid, NULL, NULL, E'This chapter presents the diversity of the social sciences in the region.', NULL, NULL),
  ('781bf858-8712-57ff-8e03-06008ca6312f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '781bf858-8712-57ff-8e03-06008ca6312f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the frozen type of water called?', 'a097b4a8-3f3b-5bd0-bb06-d5c26886a561'::uuid, NULL, NULL, E'Ice', NULL, NULL),
  ('7822f070-24f6-5573-b4ba-fe0d78b9cda5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '7822f070-24f6-5573-b4ba-fe0d78b9cda5'::uuid, 1, NULL, TRUE, 0, NULL, E'Bees'' Die-off', E'It sounds like something out of a science fiction movie - or nightmare millions of honeybees {{1}} dying off, their bodies never found. Scientists have {{2}} the phenomenon ''Colony Collapse Disorder'', but they aren''t {{3}} on the reason. Theories abound as to the {{4}} of the mass die-off, ranging from the unlikely (cellphones affecting bees navigational abilities) to the more {{5}} though still debated (widespread pesticide use).', NULL, NULL, NULL, E'1.suddenly, 2.named, 3.united, 4.cause, 5.plausible', NULL, NULL),
  ('7825d3c8-e9ab-5915-8e74-605f190917f3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7825d3c8-e9ab-5915-8e74-605f190917f3'::uuid, 1, NULL, TRUE, 0, NULL, E'Wikipedia', E'If Wikipedia had been around a couple hundred years ago we probably would have had an article that says that the sun revolves around the Earth because that was what we understood to be true. We no longer understand that to be true thanks to advances in science and physics, but if tomorrow we were to wake up and learn that in fact time being relative really does upend the way that we think about the world Wikipedia would have to evolve in order to describe that. So we''re not really in the business of truth or facts, we''re in the business of what is known, and what has been determined through consensus—scientific consensus or otherwise. And I think that that actually provides some clarity on how to understand what information you''re looking at. One thing that I think is really unique about Wikipedia is there''s only one version for the whole public. There’s no feed that’s curated for you or for me. We all are looking at...\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '88fb8bcb-c0e9-5a2e-bb59-ef1173b124c2'::uuid, NULL, NULL, E'the same version of the article', NULL, NULL),
  ('7826d7ce-e7bb-5e85-94b2-ace1e970d7d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '7826d7ce-e7bb-5e85-94b2-ace1e970d7d8'::uuid, 1, NULL, TRUE, 0, NULL, E'Angkor', E'Angkor was the site of several capitals of the Khmer Empire, north of Tonlé Sap lake, in northwest Cambodia. For about five and a half centuries (9th to 15th), it was the heart of the empire. Extending over an area of 120 sq mi (32.3 sq km), the ruins contain some of the most imposing monuments in the world, including about a thousand temples, mainly Hindu and some Buddhist; the ancient city, however, had an extent perhaps nearly 10 times that size (according to satellite photographs published in 2007), and was home to perhaps 750,000 people.\n\nThe ancient city of Angkor ( )', NULL, NULL, NULL, E'was significantly larger than the site today.', NULL, NULL),
  ('78274b39-5ca2-5ef8-8b67-3494e3768ad7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '78274b39-5ca2-5ef8-8b67-3494e3768ad7'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a6bf1b37-a121-5536-af5f-c05e1f83e4f8'::uuid, NULL, E'The book deals with the interface between accountancy and law.', NULL, NULL, NULL),
