  ('78c79e13-2738-536a-9dd2-430b134282d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '78c79e13-2738-536a-9dd2-430b134282d7'::uuid, 1, NULL, TRUE, 0, NULL, E'Royal College', E'The 36-year-old is usually based in East London, where he spends up to 10 hours a day, seven days a week, working on his {{1}} art. But before leaving his home country to study at the UK’s Royal College of Art seven years ago, he {{2}} a traditional and highly technical education in Seoul National University. The course required him to {{3}} reproduce Asian masterpieces and brushwork techniques from centuries past.', NULL, NULL, NULL, E'1.intricate, 2.underwent, 3.painstakingly', NULL, NULL),
