  ('78debf59-1ca9-57d4-874f-74cf6504648b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '78debf59-1ca9-57d4-874f-74cf6504648b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ea3a7c53-81ce-5696-8f54-5e332359b48d'::uuid, NULL, NULL, E'Animal behavior appears to contain both similar and distinct aspects to that of humans.', NULL, NULL),
  ('78e3ff15-b586-5625-af0a-49d989650bee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', '78e3ff15-b586-5625-af0a-49d989650bee'::uuid, 1, NULL, TRUE, 0, NULL, E'Himalayas', E'Hills and mountains are often regarded as the epitome of permanence, successfully resisting the destructive forces of nature, but in fact they tend to be relatively short-lived in geological terms. As a general rule, the higher a mountain is, the more recently it was formed; for example, the high mountains of the Himalayas are only about 50 million years old. Lower mountains tend to be older, and are often the eroded relics of much higher mountain chains. About 400 million years ago, when the present-day continents of North America and Europe were joined, the Caledonian mountain chain was the same size as the modern Himalayas. Today, however, the relics of the Caledonian orogeny (mountain-building period) exist as the comparatively low mountains of Greenland, the northern Appalachians in the United States, the Scottish Highlands, and the Norwegian coastal plateau.\n\nWhich of the following can be inferred from the paragraph about the mountains of the Himalayas?', NULL, NULL, NULL, E'At present, they are much higher than the mountains of the Caledonian range.\nThey did not exist 400 million years ago.', NULL, NULL),
