  ('7951ef18-7bc6-5ca3-82e9-c05ad1f0df15'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '7951ef18-7bc6-5ca3-82e9-c05ad1f0df15'::uuid, 1, NULL, TRUE, 0, NULL, E'Cognitive Empathy', E'Empathy is important because it {{1}} the way in which people interact socially, and it impacts the way their personal relationships develop. Cognitive empathy is when a person is {{2}} able to understand what someone else might be feeling, and they are even able to use that knowledge to {{3}} how the person will act or feel, which could also help scientists develop better support for people who may {{4}} to read facial expressions.', NULL, NULL, NULL, E'1.governs, 2.intellectually, 3.predict, 4.struggle', NULL, NULL),
  ('7954da49-5102-542c-827b-9e86eadcaa46'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7954da49-5102-542c-827b-9e86eadcaa46'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '18743e28-c734-5ce7-adcd-0fb39973b753'::uuid, NULL, E'Biodiversity is essential for the processes that support all life on Earth, including humans.', NULL, NULL, NULL),
  ('79555ae8-afd2-56ba-8bcc-57bd681eddea'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '79555ae8-afd2-56ba-8bcc-57bd681eddea'::uuid, 1, NULL, TRUE, 0, NULL, E'Social Distancing', E'Social distancing, also called physical distancing, refers to staying a specific distance away from other people to help prevent illnesses from spreading. The specific distance is determined by health experts and national governments, and social distancing is a recommended medical practice to help “flatten the curve,” or lower the number of COVID-19 cases throughout the world. With all the misinformation online, take a few minutes to review how to understand social distance and learn why it’s so important to help stop COVID-19. If you need help explaining social distancing to children, you can use the information below to help make social distancing easier for kids to understand.\n\nThe passage is an excerpt from a longer essay. According to the last sentence, what may the remaining part of the essay be about?', NULL, NULL, NULL, E'A more simplified and interesting description about social distancing.', NULL, NULL),
  ('7958e1eb-854c-55e4-96e8-707b2df216e0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7958e1eb-854c-55e4-96e8-707b2df216e0'::uuid, 1, NULL, TRUE, 0, NULL, E'External Reality', NULL, 'a8da427c-482a-57d5-a141-ad1d4a9721f7'::uuid, NULL, E'Is there an external reality? Of course there’s an external reality. The world exists. It’s just that we don’t see it. At least, we don’t see it as it is. In fact, we can never it as it is! In fact it’s even useful to not see it as it is. And the reason is because it goes back to really Berkeley, who tells us we have no direct access to that physical world other than through our senses. And because our senses conflate multiple aspects of that world we can never know whether our perceptions are in any way accurate. And so this has always been a very deep question. It’s not so much “Do we see the world in the way it really is?” but “Do we actually even see it accurately?”. And the answer is no, we don’t. So if we remember that the information that’s coming on to your eye or onto your skin or into your ears is inherently meaningless (because it could mean anything) then it means that we need another kind of data in order to be able to generate behaviors that are useful. And that data is necessarily historical, which means that the functional structure of your brain is really a physical manifestation of your past interactions with the world, and it’s a physical, active interaction. It’s not passive, receiving data like a Facebook broadcast; it’s an active engagement with that world.', NULL, NULL, NULL),
