  ('797fb5ad-04f7-54a3-b156-1b783d1b9d4c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '797fb5ad-04f7-54a3-b156-1b783d1b9d4c'::uuid, 1, NULL, TRUE, 0, NULL, E'Content Marketers', E'There''s an entire industry dedicated to marketing products and services through web articles, videos and social media posts. Digital marketers write blog posts, produce videos and maintain social media channels for both large corporations and mom-and-pop shops. But that type of targeted content is exactly what generative AI is designed to create.', NULL, NULL, NULL, NULL, NULL, NULL),
