  ('798909ab-2c86-5b2e-865d-11ea24ea21eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '798909ab-2c86-5b2e-865d-11ea24ea21eb'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the study of celestial objects, such as stars, planets, and galaxies?', '10392667-8bf1-5bf0-859a-ff40d76336bb'::uuid, NULL, NULL, E'Astronomy', NULL, NULL),
  ('798e5b36-eceb-5912-aab8-56119d6ed122'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '798e5b36-eceb-5912-aab8-56119d6ed122'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Who serves food in a restaurant?', 'bd3f81a6-1037-580c-b141-ca2830053b51'::uuid, NULL, NULL, E'Waiter / Waitress', NULL, NULL),
  ('798e9a60-291f-5525-826e-65ff13c4bcaa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '798e9a60-291f-5525-826e-65ff13c4bcaa'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2350e5fd-0af3-5f8e-9fc2-3f7c02402dee'::uuid, NULL, E'Companies must be able to survive in the competitive marketplace.', NULL, NULL, NULL),
  ('79996f2d-1ac8-5cc9-bddf-f86d8923c220'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '79996f2d-1ac8-5cc9-bddf-f86d8923c220'::uuid, 1, NULL, TRUE, 0, NULL, E'Skylines', E'If you live in a city, you may take your skyline for granted, but let me remind you how cool it is. Skyscrapers are amazing feats of engineering and a testament to humankind''s progress. What''s more, skylines offer an array of architectural styles, as cities certainly weren''t built in a day.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('79998045-4a86-532b-a9de-6151c4fedf02'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '79998045-4a86-532b-a9de-6151c4fedf02'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6ae7ee4c-92c4-5b3d-b9ab-9d22954c0ffd'::uuid, NULL, NULL, E'Agenda items must be submitted by the end of the day.', NULL, NULL),
  ('79a08f4f-1882-55e4-9715-c9c972f2ec4a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '79a08f4f-1882-55e4-9715-c9c972f2ec4a'::uuid, 1, NULL, TRUE, 0, NULL, E'Trade Unions', E'Trade unions originated in Europe during the industrial revolution. Because of the machinery that had become commonplace, skilled labor became less in demand so employers had nearly all of the bargaining power. Employers mistreated the workers and paid them too little for the work they did. Trade unions were organized that would help in the improvement of working condition.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('79a12fa1-e7f0-5b68-937e-ef4e79a2396a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '79a12fa1-e7f0-5b68-937e-ef4e79a2396a'::uuid, 1, NULL, TRUE, 0, NULL, E'Group Work', E'It is more important to be able to work with a group of people on a team than to work independently. Do you agree with that?', NULL, NULL, E'The debate over whether it is more important to work independently or in a team has been ongoing for years. While some people believe that working independently is the key to success, I believe that it is more important to be able to work with a group of people on a team. This essay will argue that working in a team provides benefits such as collaboration, creativity, and motivation.\nWorking in a team allows for collaboration and the pooling of diverse skills and expertise. When individuals work together, they can combine their strengths and knowledge to achieve a common goal. Collaboration can also lead to new ideas and perspectives that may not have been considered otherwise. In addition, working in a team can create a sense of accountability, as individuals are responsible not only for their own tasks but also for the success of the team as a whole.\nIn addition to collaboration, teamwork promotes creativity and innovation through the exchange of ideas and perspectives. When individuals work together, they can bounce ideas off one another and provide feedback. This process can lead to new approaches and solutions that may not have been possible when working alone. Furthermore, working in a team fosters a sense of camaraderie and mutual support, leading to increased motivation and productivity.\nIn conclusion, working in a team is more important than working independently due to the benefits it provides. While individual work may have its merits, teamwork provides a richer and more diverse experience that can lead to greater success. By working together, individuals can achieve more than they could alone, making teamwork an essential component of success in today''s world.', NULL, 200, 300),
  ('79a33f91-02ef-5347-90b3-9e61c8252143'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '79a33f91-02ef-5347-90b3-9e61c8252143'::uuid, 1, NULL, TRUE, 0, NULL, E'Origin of Music', E'Music is an important part of our lives. We connect and interact with it daily and use it as a way of projecting our self-identities to the people around us. The music we enjoy — whether it''s country or classical, rock n'' roll or rap — {{1}} who we are.\nBut where did music, at its core, first come from? It''s a puzzling question that may not have a definitive answer. One {{2}} researcher, however, has proposed that the key to understanding the origin of music is nestled snugly in the loving bond between mother and child.\nIn a lecture at the University of Melbourne, Richard Parncutt, an Australian-born professor of systematic musicology, endorsed the idea that music originally spawned from ''motherese'' — the playful voices mothers {{3}} when speaking to infants and toddlers.\nAs the theory goes, increased human brain sizes caused by evolutionary changes occurring between one and 2,000,000 years ago resulted in earlier births, more fragile infants and a critical need for stronger relationships between mothers and their newborn babies.\nAccording to Parncutt, who is based at the University of Graz in Austria, ''motherese'' arose as a way to strengthen this maternal bond and to help {{4}} an infant''s survival.', NULL, NULL, NULL, E'1.reflects, 2.leading, 3.adopt, 4.ensure', NULL, NULL),
  ('79a79dc9-db52-526a-a53d-e5d181b773c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '79a79dc9-db52-526a-a53d-e5d181b773c6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '749886bd-9b6b-5c6c-8ec7-e146cb1afb64'::uuid, NULL, NULL, E'The essay assignments are given in the midterm and final exams.', NULL, NULL),
