  ('7a76201d-26b2-586a-be55-48a53187912e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7a76201d-26b2-586a-be55-48a53187912e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ccf3ca43-65de-5009-ac0a-a38536ce04b6'::uuid, NULL, E'Deciding research boundaries is challenging; defining limits requires careful consideration.', NULL, NULL, NULL),
  ('7a8c68b3-691a-5935-9714-2184752defeb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '7a8c68b3-691a-5935-9714-2184752defeb'::uuid, 1, NULL, TRUE, 0, NULL, E'Rainbows', E'“Climate change is {{1}} rainbows — now we know that’s true,” says Carlson, the lead author on a paper, which used computer models to {{2}} future rainbow-ready conditions. As major weather patterns {{3}} because of climate change, many parts of the world — particularly places nearer to the poles, like Alaska or Siberia, will get more rain — {{4}} adding dozens more rainbow-rich days by the end of the century.', NULL, NULL, NULL, E'1.affecting, 2.simulate, 3.morph, 4.potentially', NULL, NULL),
  ('7a8cd4f8-a7f0-58b4-9f47-816c646dc6bf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '7a8cd4f8-a7f0-58b4-9f47-816c646dc6bf'::uuid, 1, NULL, TRUE, 0, NULL, E'English Language', E'With about one and a half billion non-native speakers, English has become the world''s own language. Such {{1}} has its downside, of course. There are now about 6,800 languages left in the world, compared with perhaps {{2}} that number back at the dawn of agriculture. Thanks in {{3}} to the rise of über-languages, most importantly English, the remaining languages are now dying at the {{4}} of about one a fortnight. Want to learn Busuu, anyone? Then you''d better head to Cameroon fast, before one of the language''s last eight speakers kicks the bucket (as the Busuu-nese presumably doesn''t say).', NULL, NULL, NULL, E'1.dominance, 2.twice, 3.part, 4.rate', NULL, NULL),
  ('7a9c1a13-fca0-533e-a4c5-239e05580b9f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7a9c1a13-fca0-533e-a4c5-239e05580b9f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for the temperature at which a liquid boils and turns to vapor?', '1c38b2c1-310e-5de5-86a9-b195ae39bb58'::uuid, NULL, NULL, E'Boiling point', NULL, NULL),
  ('7a9e48d6-2926-53d4-b30a-9b31283817c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '7a9e48d6-2926-53d4-b30a-9b31283817c0'::uuid, 1, NULL, TRUE, 0, NULL, E'Mass Extinction', E'Scientists have discovered the cause of a mass extinction of sea-floor marine organisms 800,000 years ago — which also provides insight into how climate change can impact {{1}} deep ocean biota.\nIn a new study {{2}} in the journal Nature Communications, scientists from the universities of Nottingham and Durham and the British Geological Survey (BGS), have discovered the cause of a mass extinction within marine organisms called foraminifera. Foraminifera are an important group in relation to biomass in the deep ocean and the cause of their extinction was {{3}} unknown. Scientists tested various possible {{4}} for the mass extinction and were able to discount others such as ocean cooling. {{5}} , they discovered that the extinction was caused by a global change in plankton at the surface of the ocean.', NULL, NULL, NULL, E'1.on, 2.published, 3.previously, 4.causes, 5.Instead', NULL, NULL),
  ('7aa361d2-ebc5-5545-bc01-03825709d7e3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7aa361d2-ebc5-5545-bc01-03825709d7e3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1848033b-ca78-5b20-a9d1-13c3bfc771ef'::uuid, NULL, NULL, E'Expect to run into a lot of challenges during this project.', NULL, NULL),
