  ('7aacb7a7-580e-56e6-9619-69014af83d8b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7aacb7a7-580e-56e6-9619-69014af83d8b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8cfd7426-1891-5358-9ef8-80091d898753'::uuid, NULL, E'A liberal arts curriculum can be very broad and diverse.', NULL, NULL, NULL),
  ('7ab08d7a-7fc5-57c3-8e31-27702c795af6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7ab08d7a-7fc5-57c3-8e31-27702c795af6'::uuid, 1, NULL, TRUE, 0, NULL, E'Precipitation', E'In meteorology, precipitation is any product of the condensation of atmospheric water vapor that falls under gravity. The main forms of precipitation include drizzle, rain, sleet, snow, graupel, and hail.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('7ab1b61b-fd42-5b90-91d4-987c70eb386c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7ab1b61b-fd42-5b90-91d4-987c70eb386c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8bc10ccf-4785-53ef-a53f-ce90fbd26c2b'::uuid, NULL, E'Volcanoes have played a key role in forming and modifying the earth.', NULL, NULL, NULL),
  ('7ab3967a-baa2-5e19-ac63-736aafb4c56d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7ab3967a-baa2-5e19-ac63-736aafb4c56d'::uuid, 1, NULL, TRUE, 0, NULL, E'Malaria', E'A:Actually, the word ''malaria'' means ''bad air'' in Italian and centuries ago that''s what people thought caused this very infectious disease.\nB:And who can blame them really? Who can blame them for making that, hmm, false connection? Who''d have thought that a tiny insect, like a mosquito, could cause so much sickness?\nA:Mmm, Yes. More surprising perhaps is the fact that it''s taken scientists so much time since then to come up with a cure.\nB:Ahah. Well that''s what we''re going to talk about now. Because it does seem that this is now becoming a real possibility.\n\nWhat do the speakers feel about early views on malaria?', '274550df-780f-5e4d-b1fc-c32183b948dc'::uuid, NULL, NULL, E'They were understandable at the time.', NULL, NULL),
  ('7ab7ae24-66db-5306-a332-c36570451322'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7ab7ae24-66db-5306-a332-c36570451322'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f0fa4dae-1073-5fb3-94d4-25d9c79b2da0'::uuid, NULL, NULL, E'Criminal charges will be brought against all of the men.', NULL, NULL),
  ('7abbfbdc-c359-54db-9c05-b20f3044abca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7abbfbdc-c359-54db-9c05-b20f3044abca'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What word can we use to replace the word ‘answer’?', '15dc583b-5391-5f40-b4c8-48060457d6ee'::uuid, NULL, NULL, E'Reply / response', NULL, NULL),
  ('7abc0f61-6053-515b-8a17-afbe76c3941d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7abc0f61-6053-515b-8a17-afbe76c3941d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6d98ac9d-c4d6-5b41-bf3e-2220d5a21c31'::uuid, NULL, E'He dedicated many years to studying with a renowned painter.', NULL, NULL, NULL),
  ('7ac20eed-9d6b-5fc9-9583-19bafa7260e6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '7ac20eed-9d6b-5fc9-9583-19bafa7260e6'::uuid, 1, NULL, TRUE, 0, NULL, E'One Health', NULL, NULL, NULL, NULL, E'3, 1, 4, 5, 2', NULL, NULL),
  ('7acb2a69-6a21-5940-9af8-6cbb0e57e3fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '7acb2a69-6a21-5940-9af8-6cbb0e57e3fb'::uuid, 1, NULL, TRUE, 0, NULL, E'Flexible Working', E'In the US in 2016, 43 per cent of employees said they had spent at least some time working remotely. We like these freedoms – but are they good for business? Andrew Barnes thinks so. In late 2017, he read that workers were properly {{1}} for only a few hours a day, so he decided to experiment with a four-day working week at the trust management company he founded in New Zealand. The idea was that employees would focus more to get their work done quicker, and get a paid day off in {{2}} . And they did indeed get the same amount of work done. Economist Helen Delaney at the University of Auckland, who surveyed the staff, says they felt “rested and {{3}} upon returning to work, which enabled them to sustain the higher performance during the trial period”. She says the exercise has {{4}} significant interest from trade unions and government.', NULL, NULL, NULL, E'1.productive, 2.return, 3.rejuvenated, 4.generated', NULL, NULL),
  ('7ad2be0e-47ba-5143-bbef-32aa9743bae9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7ad2be0e-47ba-5143-bbef-32aa9743bae9'::uuid, 1, NULL, TRUE, 0, NULL, E'Kids in the Museum', NULL, 'f820c94a-8c42-509d-a679-c7f1d6787cd4'::uuid, NULL, E'So, we were founded just over ten years ago, when I was in the Royal Academy, a museum in the centre of London, with my three children, at the Aztec exhibition. I don''t know if any of you saw it.\nI had an older child and two younger children, twins, strapped in a pushchair, and one of my children, three years old, shouted and I''ve never denied he shouted he shouted, ''Monster, monster! '' at this statue which looked just like a monster, had snakes for hair, a big beak for a nose. And, I thought, this is fantastic. I''ve got a three-year-old that''s appreciating art. How good can it get? So, I bent down and I said, ''Yes, it looks just like a monster'' And, at that moment, a room warden came over, a gallery assistant came over and said we were being too noisy, and threw us out to the wrong family. I was, at that time, a journalist with The Guardian newspaper, and two days later wrote a big piece in The Guardian about being thrown out of the Royal Academy. What was really interesting was, by the end of that day, we had had, at the paper, over 500 emails from other families saying, museums aren''t working for us. Let''s try and make it work. So, that''s what we did.\nIn the Guardian, we set up a campaign. We called it the Kids in Museums campaign, but it didn''t really exist. It was just a few pages. We ran loads of stories on it; I began touring the country talking about how to make your museum family-friendly.', NULL, NULL, NULL),
  ('7add578a-40f9-5333-a6b9-7b36fa082f8b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7add578a-40f9-5333-a6b9-7b36fa082f8b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '40a82906-71e1-5d28-a24b-f37a7c0e4af7'::uuid, NULL, NULL, E'Lack of motivation resulted in his failure of the project.', NULL, NULL),
  ('7ae1d5cb-10a9-5924-915e-c9ce36f0f691'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '7ae1d5cb-10a9-5924-915e-c9ce36f0f691'::uuid, 1, NULL, TRUE, 0, NULL, E'Energy Use and Weather', E'Hot weather can be uncomfortable, and in extreme cases dangerous. One way people respond to hot weather is by using air conditioning. Air conditioning is the primary way to cool a home and has become more widely used over time; as of 2015, it {{1}} for 17 percent of the electricity that the average American household uses every year. As climate change contributes to an increase in average temperatures and unusually hot days, Americans are {{2}} to use more energy - mostly electricity for air conditioning. As a result, people will likely have to spend more money on electricity for cooling. Increased use of air conditioning could also {{3}} to more greenhouse gas emissions and further climate change, because more electricity must be {{4}} to meet this increased demand. As of 2018, about two-thirds of the electricity in the United States was generated by burning fossil fuels such as coal or natural gas. Burning fossil fuels for electricity is one of the largest sources of heat-trapping greenhouse gas emissions in the United States.', NULL, NULL, NULL, E'1.accounted, 2.expected, 3.lead, 4.generated', NULL, NULL),
  ('7ae23191-570c-5c2b-b480-9d174a9aff61'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7ae23191-570c-5c2b-b480-9d174a9aff61'::uuid, 1, NULL, TRUE, 0, NULL, E'Brain_development', NULL, '69a3406a-3e0a-56ec-b7b7-d6931204271b'::uuid, NULL, E'The key to forming strong brain architecture is what''s known as " serve and return" interaction with adults. In this developmental game, new neural connections form in the brain as young children instinctively serve through babbling, facial expressions, and gestures, and adults return the serve, responding in a very directed, meaningful way. It starts very early in life when a baby coos and the adults interacts and directs the baby''s attention to a face or hand. This interaction forms the foundation of brain architecture upon which all future development will be built. It helps create neural connections between all the different areas of the brain, building the emotional and cognitive skills children need in life. For example, here''s how it works for literacy and language skills. When the baby sees an object, the adult says its name. This makes connections in the baby''s brain between particular sounds and their corresponding objects. Later, adults show young children that those objects and sounds can also be represented by marks on a page. With continued support from adults, children then learn how to decipher writing and, eventually, to write themselves. Each stage builds on what came before. Ensuring that children have adult caregivers who consistently engage in serve and return interaction, beginning in infancy, builds the foundation in the brain for all the learning, behavior, and health that follow.', NULL, NULL, NULL),
  ('7ae42ff3-8ddf-5a0d-9e4b-53696441ac30'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '7ae42ff3-8ddf-5a0d-9e4b-53696441ac30'::uuid, 1, NULL, TRUE, 0, NULL, E'APS', E'The APS supports the development of an Australian curriculum for psychological science. The APS Division of Psychological Research, Education and Training, in {{1}} with teacher and curriculum representatives from every State and Territory in Australia, {{2}} a proposed framework for senior secondary school studies in psychological science. This framework {{3}} on the current senior science curricula that were developed and published by the Australian Curriculum, Assessment and Reporting Authority. The APS hopes that this framework will {{4}} a dialogue between educators and their local curriculum authority, with the aim of working towards a more {{5}} approach to the teaching of psychological science at secondary school level and optimizing the preparation for students going on to undergraduate psychology studies at university, as well as the effective use of psychological principles in everyday life.', NULL, NULL, NULL, E'1.consultation, 2.develops, 3.is modeled, 4.facilitate, 5.consistent', NULL, NULL),
