  ('7beef8ea-732a-5852-ad9b-ab2c30034028'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7beef8ea-732a-5852-ad9b-ab2c30034028'::uuid, 1, NULL, TRUE, 0, NULL, E'Wet Floor', E'You are walking up the stairs in front of your apartment and almost slip on the wet floor. You tell one of your neighbors about it. What would you say?', '2e5ce7b9-01a6-5d21-a6f6-7e719b573d51'::uuid, NULL, NULL, NULL, NULL, NULL),
