  ('7c1b27f0-0bec-5978-a02c-ad1fec15de46'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7c1b27f0-0bec-5978-a02c-ad1fec15de46'::uuid, 1, NULL, TRUE, 0, NULL, E'Reliable Evidence', E'A scientist''s evidence is thought to be reliable because it will have been tested and verified at every stage. This is not, of course, infallible as scientists are subject to human error as much as the rest of us.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('7c1c3f57-bbf7-522e-8423-ac72fc0ab6b5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7c1c3f57-bbf7-522e-8423-ac72fc0ab6b5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0613b44a-29f6-5632-bc48-375ff403dc0f'::uuid, NULL, NULL, E'When it gets cold, birds fly to places where it''s warm.', NULL, NULL),
  ('7c1c9fac-f1fe-5bed-abbf-d330a62d47a2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7c1c9fac-f1fe-5bed-abbf-d330a62d47a2'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd5b7d822-7dbc-5a72-b805-e8c5a93d85e1'::uuid, NULL, E'There are many good methods that can be used.', NULL, NULL, NULL),
  ('7c1f2251-15eb-50da-a62f-7d3d4f045344'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '7c1f2251-15eb-50da-a62f-7d3d4f045344'::uuid, 1, NULL, TRUE, 0, NULL, E'Fever', E'Maybe it''s happened to you. You think you have a fever. So you pop a thermometer in your mouth and try to breathe through your nose to get an accurate reading. But you''re totally stuffed up, so you {{1}} this moment of {{2}} panic because you can''t get enough air. Well, a new study in the journal Cell says you can thank your amygdala for that. Because this key member of the brain''s fear circuitry can directly sense {{3}} , and trigger feelings of terror.\nThe amygdala plays a role in {{4}} to threats, and it can kick off a fight-or-flight {{5}} when it senses danger. Now, this brain region is packed with a type of protein that''s activated by acid, and seems to be {{6}} in an animal''s response to fear. Well, suffocation is pretty scary and signals to the brain that something isn''t right. And it does so by activating this acid-sensing protein.\nWhen an animal can''t breathe, carbon dioxide builds up, and boosts the amount of acid in the body. The acid, in turn, turns on this protein, which then hits the panic button and tells the animal to do something. Even if, during the Thanksgiving meal, it''s just to remind the animal to stop swallowing and take a deep breath.', NULL, NULL, NULL, E'1.experience, 2.complete, 3.suffocation, 4.responding, 5.reaction, 6.involved', NULL, NULL),
  ('7c2080b8-f39e-5a40-8009-914c85bdc1c7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7c2080b8-f39e-5a40-8009-914c85bdc1c7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a4f652d5-1c06-5ea9-b043-8205a429d654'::uuid, NULL, NULL, E'Poverty exists everywhere, but the situation has improved.', NULL, NULL),
  ('7c2f4663-b628-5575-8c87-7b526f327fd3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7c2f4663-b628-5575-8c87-7b526f327fd3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'aa5d2f63-6725-5e8a-a88e-8f746af8b44a'::uuid, NULL, NULL, E'The history of economics is a tricky subject to study.', NULL, NULL),
