  ('7c6a8a2b-4cdb-5e6c-9571-d7074e7602d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '7c6a8a2b-4cdb-5e6c-9571-d7074e7602d5'::uuid, 1, NULL, TRUE, 0, NULL, E'Genetic Test for PD', E'While Florey researchers have also created a genetic test for PD (10% of PD cases are caused by genetic factors), this new test has a broader {{1}} by screening for many different types of PD and monitoring treatment, as well as measuring the {{2}} of drugs being developed to treat the disease.\nDr Qiao-Xin Li and colleagues from The University of Melbourne and The Mental Health Research Institute of Victoria, along with Prof Malcolm Horne from the Howard Florey Institute, found people with PD had low levels of the brain-secreted protein ‘alpha-synuclein'' in their blood, {{3}} people without PD had high levels of the protein.\nProf Horne said the test they developed measured alpha-synuclein levels in blood. “Currently there is no specific PD diagnostic test so doctors rely on their observations to make a diagnosis, which means some patients may not be prescribed the most suitable medication and around 15% of those {{6}} may actually be suffering from something else,” Prof Horne said.\nFurther studies are required to establish whether this test can {{4}} between people who are responsive to treatment and those who are not,” he said. The researchers are now conducting a large-scale study to determine the effectiveness of the test, to discover whether it is applicable for all types of PD, and to find out if it can measure the rate of {{5}} and severity of the disease.', NULL, NULL, NULL, E'1.application, 2.effectiveness, 3.while, 4.diagnosed, 5.distinguish, 6.progression', NULL, NULL),
  ('7c6a9f7f-f215-5016-8126-d248fef62136'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7c6a9f7f-f215-5016-8126-d248fef62136'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do we describe a person who is weak and can easily get hurt physically or emotionally?', '23ab2f50-43d5-5a04-a85d-73e830c5c163'::uuid, NULL, NULL, E'Vulnerable', NULL, NULL),
  ('7c6aef3e-2042-5236-8fc3-ad378846f9a3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7c6aef3e-2042-5236-8fc3-ad378846f9a3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '43e808b6-3a28-58b2-ba0a-e3198de2e4b7'::uuid, NULL, NULL, E'We have found further scientific evidence for this geology theory.', NULL, NULL),
