  ('7c771ebb-7c97-5670-a0d8-c05476304ae9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7c771ebb-7c97-5670-a0d8-c05476304ae9'::uuid, 1, NULL, TRUE, 0, NULL, E'Wildfire Prevention', E'Although forest thinning and controlled burning remove carbon in the short term, living trees are more likely to survive a subsequent wildfire. In the long term, that’s a good outcome for carbon and climate. Living trees continue to absorb and store carbon from the atmosphere, as well as provide critical seeds and shade for seedlings to regenerate, grow and recover the carbon lost to fires.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('7c7e0d55-69b8-5f8c-885c-11ef1afb8874'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7c7e0d55-69b8-5f8c-885c-11ef1afb8874'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1bc80abf-52c1-57e1-9a1b-49dd8cb9af92'::uuid, NULL, NULL, E'He is well-qualified to guide groups on mountain expeditions safely.', NULL, NULL),
