  ('7c7fc7c0-08be-5d29-899c-2013b3057667'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7c7fc7c0-08be-5d29-899c-2013b3057667'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2a6e1950-1b05-5ec7-8820-86aa71ace517'::uuid, NULL, NULL, E'The primary school is located at the center of the town.', NULL, NULL),
  ('7c800f86-79f3-5fc5-b78d-58d483b81707'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7c800f86-79f3-5fc5-b78d-58d483b81707'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b92e2786-0273-52be-a988-1693d1c9d54f'::uuid, NULL, E'This dissertation is an extended piece of research on a topic of your interest.', NULL, NULL, NULL),
  ('7c830a73-7aac-5703-93b6-1b057eaaacc2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7c830a73-7aac-5703-93b6-1b057eaaacc2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5438fcfc-12af-505d-9158-e102869e7951'::uuid, NULL, NULL, E'These few resources fall short for completing the current assignment.', NULL, NULL),
  ('7c8387e3-906e-5a89-9582-b03afafac60b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7c8387e3-906e-5a89-9582-b03afafac60b'::uuid, 1, NULL, TRUE, 0, NULL, E'Hydrogen Fuel', E'The power of the sun, wind and sea may soon combine to produce clean-burning hydrogen fuel, according to researchers. A team integrated water purification technology into a new proof-of-concept design for a seawater electrolyzer, which uses an electric current to split apart the hydrogen and oxygen in water molecules.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('7c83bef2-3c4e-55a5-9290-346aaf7d3b01'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '7c83bef2-3c4e-55a5-9290-346aaf7d3b01'::uuid, 1, NULL, TRUE, 0, NULL, E'Seat Belts', E'Today''s school buses have been designed for better crash and rollover protection. They protect kids through "compartmentalization," which means spacing seats close together, as well as using seats with high, energy-absorbing backs to prevent children from being tossed around in a collision.\nSchool buses are also highly visible and have safety features like red flashing red lights, cross-view mirrors and stop-sign arms. Drivers stay on carefully planned routes and maintain slow speeds, so seat belts aren''t needed. That''s the thought, anyway.\nUnfortunately, though, deadly school bus crashes happen. Such was the case in November 2016 when a crash in Chattanooga, Tennessee killed six elementary school students. After another deadly school bus crash in May 2018 in Morris County, New Jersey, killed two, including a child, and injured 43 others, the National Transportation Safety Board (NTSB) opened a full investigation into school bus safety.\nHowever, today seat belts are only federally mandated on small school buses, or those weighing 10,000 pounds or less. States are allowed to decide whether to mandate them by law on the rest of school buses. Currently only eight states have laws requiring seat belts on large school buses, though many others are considering similar legislation.\nSince most school buses are on the road for at least 10 and often up to 20 years, it''s unlikely school districts would choose to retrofit older buses at that cost, which means it would potentially take decades for new legislation requiring seat belts to take effect across a fleet as new buses slowly replace older ones.', NULL, NULL, NULL, NULL, 5, 75),
  ('7c856910-deea-5f41-8b41-92950f31d488'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7c856910-deea-5f41-8b41-92950f31d488'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3f60f720-5d39-5e40-a953-d4cc39b2dab2'::uuid, NULL, NULL, E'Fill out this form to get cheaper prices at school.', NULL, NULL),
  ('7c87dbbd-9c0c-591e-ad0f-1eec2dabf2d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7c87dbbd-9c0c-591e-ad0f-1eec2dabf2d7'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do pedestrians move by?', '1a81e326-565e-5a3d-a9a0-97f284742223'::uuid, NULL, NULL, E'Foot / feet', NULL, NULL),
  ('7c888758-a7f0-5ce0-8ca8-97092df1e6c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '7c888758-a7f0-5ce0-8ca8-97092df1e6c4'::uuid, 1, NULL, TRUE, 0, NULL, E'Nome', E'Each year after the Christmas holidays, citizens of coastal Nome, Alaska cart out their Christmas trees and set them up on ice amidst a field of other custom figures, creating a temporary winter wonderland that lasts {{1}} the ice holds (before the trees are carried out to sea). Like other informal guerrilla forests, it is a small, local and {{2}} affair. The Nome Nugget, "Alaska''s Oldest Newspaper," has reported on the "Nome National Forest" from time to time over the past 25-plus years of the tradition''s {{3}} . "The story begins at Fat Freddies, an iconic restaurant that closed and was replaced by Bering Sea Restaurant," they explain. The owners decided to play a kind of practical joke on tourists — something light and fun to {{4}} visitors.', NULL, NULL, NULL, E'1.as long as, 2.cozy, 3.existence, 4.confound', NULL, NULL),
  ('7c89423a-b701-5565-8545-9076039ded1d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '7c89423a-b701-5565-8545-9076039ded1d'::uuid, 1, NULL, TRUE, 0, NULL, E'Solar Eclipse', E'A total solar eclipse is a rare and spectacular phenomenon that occurs when the moon {{1}} the sun’s light completely, creating a brief period of darkness in the middle of the day. On 8 April 2024, people in North America will have a chance to {{2}} this amazing event, as the path of totality - the area {{3}} the eclipse is visible - will stretch from Mexico to Canada, crossing 13 US states. To enjoy the full experience of the eclipse, viewers need to know where and when to look, as well as how to protect their eyes from the sun’s harmful rays. The eclipse will {{4}} for about 3 hours, but the totality will only be for about 4 minutes, depending on the location. During this time, the temperature will drop, the sky will darken, and stars and planets will appear. There will also be other phenomena to observe, such as strange shadows, diamond rings, and the sun’s corona. A total solar eclipse is a once-in-a-lifetime opportunity that should not be {{5}} by anyone who loves astronomy and nature.', NULL, NULL, NULL, E'1.blocks, 2.witness, 3.where, 4.last, 5.missed', NULL, NULL),
  ('7c898a41-cc87-5251-8403-8a17fe305853'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7c898a41-cc87-5251-8403-8a17fe305853'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for a journey, especially a long one, involving travel by sea or in space?', '73dc39bc-199c-5edc-a5d8-8d3e727ee914'::uuid, NULL, NULL, E'Voyage', NULL, NULL),
  ('7c94dcea-9bf3-5254-8210-f5183b54ac06'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7c94dcea-9bf3-5254-8210-f5183b54ac06'::uuid, 1, NULL, TRUE, 0, NULL, E'Cat', E'You are planning to be away from home for three days and need someone to take care of your cat. You decide to ask your friend Monica for help. How would you explain the situation and request her assistance in feeding your cat while you are away?', 'fd1cb4e3-8cf1-5083-b4a7-dfae906a8502'::uuid, NULL, E'Hey Monica, I want to talk to you about something.\nWe seem to have a little issue with my cat care these three days.\nIt''s like I will leave home for three days and I hope you can help feed my cat during my absence.\nAnd I''d like to know what you think.', NULL, NULL, NULL),
  ('7c9566a3-8227-5582-b1a4-bcfe138455ff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7c9566a3-8227-5582-b1a4-bcfe138455ff'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call your cousin''s father?', '2727e4b4-d1d1-52d5-afd0-8ba63756ae9e'::uuid, NULL, NULL, E'Uncle', NULL, NULL),
  ('7c969869-22cf-53ff-ac68-37938c8f5192'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '7c969869-22cf-53ff-ac68-37938c8f5192'::uuid, 1, NULL, TRUE, 0, NULL, E'Ageing Australia', E'In 2005 Japan had the highest median age of all countries in the world, while Australia''s population was only moderately aged. Some 50 years ago the demographic situation was quite different, with the median age of Australia''s population being seven years older than Japan''s.\nThe ageing of the population is a major issue for Australian policy makers, particularly in regard to the long-term implications for reduced economic growth and the increasing demand for Age Pensions, and health and aged care services. As the population ages, growth in the number of people of working age will slow, while the proportion of people of retirement age will increase.\nSustained population ageing also leads to slowing or negative population growth. While declining population growth in developed countries is welcomed by some environmentalists and social scientists, economists tend to agree that population decline brings gloomy economic prospects. In addition to the decrease in the labor supply, the demand side of the economy may be affected through shrinking markets for goods and services.\nHow quickly this occurs depends on the dynamics of fertility, mortality and overseas migration. While a moderate pace of demographic change allows for gradual adjustment of the economy and policies to the changing population demographics, rapid changes are more difficult to manage. As a result, governments and society as a whole may need to take actions to address these issues. But how severe is the ageing of Australia''s population, relative to other countries?\nOne way of applying a degree of perspective to the ageing debate is to compare ageing in Australia with that of other countries. This article examines the population structures in Australia and Japan and the demographic forces that shape the respective populations, both historically and projections for the future.', NULL, NULL, E'The ageing of the population is a major issue for Australian policy makers, as sustained population ageing leads to slowing or negative population growth, and population decline brings gloomy economic prospects, so governments and society as a whole may need to take actions to address these issues.', NULL, 5, 75),
  ('7c9aa818-d53a-5ae5-b617-feb0626edc90'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '7c9aa818-d53a-5ae5-b617-feb0626edc90'::uuid, 1, NULL, TRUE, 0, NULL, E'Foreign Language Learning', E'What can make learning a new foreign language unimportant? Give your example and explanation.', NULL, NULL, E'Learning a new foreign language can be a valuable and rewarding experience, but there are situations where it may not be as important. In this essay, I will discuss reasons why learning a new foreign language may be considered unimportant.\nFirstly, limited travel or interaction with speakers of that language reduces the need for language proficiency. For example, if someone lives in a country where the language is not commonly spoken and has no plans to travel to a country where the language is spoken, then learning that language may not be a priority. In this case, the individual may not have many opportunities to use the language in their daily life, making it less important to learn.\nSecondly, the availability of translation tools and language apps simplifies communication without the need for extensive language learning. With the advancement of technology, there are many translation tools and language apps that make communication easier without extensive language learning. These tools can translate text, speech, and even images in real-time, making it possible to communicate with speakers of other languages without having to learn the language itself.\nIn conclusion, while learning a new foreign language can be a valuable and rewarding experience, there are situations where it may not be as important. Limited travel or interaction with speakers of the language, the availability of translation tools and language apps, and the dominance of a widely spoken global language are all factors that can make learning a new foreign language unimportant.', NULL, 200, 300),
  ('7c9b966b-b30a-5ebd-b499-0d4210c24010'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7c9b966b-b30a-5ebd-b499-0d4210c24010'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '40248344-841d-5e10-bee9-8868fcbb8405'::uuid, NULL, E'The ship successfully underwent sea trials in coastal waters.', NULL, NULL, NULL),
