  ('7cabb01c-4d62-5595-9507-1ad6ac6451b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7cabb01c-4d62-5595-9507-1ad6ac6451b8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do we call the young horse?', 'e6495768-701f-5e5b-af27-75b1e11609d7'::uuid, NULL, NULL, E'Pony / foal', NULL, NULL),
  ('7cac9e7c-719e-53ef-9af4-948324c2c073'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7cac9e7c-719e-53ef-9af4-948324c2c073'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'If you are happy with the agreement, what would you like to put at the bottom of the contract with the date?', '7d57f3b4-7c92-5aa8-9d1e-35d5285f1651'::uuid, NULL, NULL, E'Signature / signatures', NULL, NULL),
  ('7cadc46f-d322-5abc-a5c0-048cc63a3cae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7cadc46f-d322-5abc-a5c0-048cc63a3cae'::uuid, 1, NULL, TRUE, 0, NULL, E'Standardized Tests', NULL, '5ce6f2cd-252f-5e61-92fb-0a1c670d78d8'::uuid, NULL, E'Reliability and validity are two critical ideas for understanding standardized tests. To understand the difference between them, we can use the metaphor of two broken thermometers. An unreliable thermometer gives you a different reading each time you take your temperature, and the reliable but invalid thermometer is consistently ten degrees too hot. Validity also depends on accurate interpretations of results. If people say results of a test mean something they don’t, that test may have a validity problem. Just as we wouldn’t expect a ruler to tell us how much an elephant weighs, or what it had for breakfast, we can’t expect standardized tests alone to reliably tell us how smart someone is, how diplomats will handle a tough situation, or how brave a firefighter might turn out to be. So standardized tests may help us learn a little about a lot of people in a short time, but they usually can’t tell us a lot about a single person. Many social scientists worry about test scores resulting in sweeping and often negative changes for test takers, sometimes with long-term life consequences. We can’t blame the tests, though. It’s up to us to use the right tests for the right jobs, and to interpret results appropriately.', NULL, NULL, NULL),
