  ('7ce3cde3-20c9-57c5-bf2d-c059102f5ba8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7ce3cde3-20c9-57c5-bf2d-c059102f5ba8'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '216decab-1a39-532d-a217-ba9df505945a'::uuid, NULL, NULL, E'The goal of the government policy is to increase the foreign investment.', NULL, NULL),
  ('7ce7dafa-36ee-5d70-b9af-b8d772041e95'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7ce7dafa-36ee-5d70-b9af-b8d772041e95'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9efffa28-41e7-5fca-b53c-eed85004e7e8'::uuid, NULL, NULL, E'Almost half of the state''s residents were born elsewhere.', NULL, NULL),
  ('7cfce0f1-3c6f-5251-b02c-6c65588f39b4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '7cfce0f1-3c6f-5251-b02c-6c65588f39b4'::uuid, 1, NULL, TRUE, 0, NULL, E'Legendary Scientists', E'Einstein, Newton and many other legendary scientists did groundbreaking work in their 20s. But if your hair has gone gray and no Nobel seems likely, don''t fret just yet. Because the age at which {{1}} work gets done has been going up. So says a study in the Proceedings of the National Academy of Sciences .\nResearchers {{2}} 525 science Nobel Prize-winners from 1901 to 2008. In the small sample before 1905, about {{3}} of Nobel winners did their major work before age 40. But by 2000 most laureates did their cited work after age 40.\nThe entire field of quantum mechanics was predominantly a young man''s game — which meant that as late as 1934, more than three-quarters of physics prizes were for work done by people under 40. But the more mature researchers have steadily {{4}} their catch since then.\nThe study authors note that a shift from theoretical to experimental work can account for some of the age change. It also takes longer to educate and train new contributors to now-mature fields. So keep plugging. Unlike the youthful Archimedes, your "eureka" moment may come in a bathtub with safety bars.', NULL, NULL, NULL, E'1.Nobel-winning, 2.analyzed, 3.two-thirds, 4.increased', NULL, NULL),
  ('7d061910-a3d9-52fc-a92e-625f355469d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7d061910-a3d9-52fc-a92e-625f355469d7'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'In medical terms, are antibodies harmful or beneficial for patients?', '85dd6c9c-c4a7-57bc-a838-f3d5d8381461'::uuid, NULL, NULL, E'Beneficial', NULL, NULL),
  ('7d10ff5f-0fef-5906-b568-194633cdc343'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7d10ff5f-0fef-5906-b568-194633cdc343'::uuid, 1, NULL, TRUE, 0, NULL, E'Falsifiable Science', E'Contemporary scholars who study scientific methodology are often frustrated by the implication that science is logically falsifiable. The problem is that scientists can always make excuses to avoid falsifying a claim. The discovery of Neptune is a famous case. Astronomers had noticed irregularities in the orbit of Uranus. One possibility was that these irregularities violated the theory currently used to explain planetary motion, and that this theory should be rejected.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('7d11edeb-34c6-5bde-9e7a-3f1c1403fdbf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7d11edeb-34c6-5bde-9e7a-3f1c1403fdbf'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b744a27d-2cd7-5541-bc48-320aadb746df'::uuid, NULL, E'Among various heating and cooling systems, central heating proves to be superior.', NULL, NULL, NULL),
  ('7d14793f-d1b4-5f36-b6e7-daee35da36e0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7d14793f-d1b4-5f36-b6e7-daee35da36e0'::uuid, 1, NULL, TRUE, 0, NULL, E'Past, Present and Future', E'Modern science says: ‘The Sun is the past, the Earth is the present, the moon is the future.‘ From an incandescent mass we have originated, and into a frozen mass, we shall turn. Merciless is the law of nature, and rapidly and irresistibly we are drawn to our doom.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('7d149403-494b-5b20-8bc6-cd5866113961'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '7d149403-494b-5b20-8bc6-cd5866113961'::uuid, 1, NULL, TRUE, 0, NULL, E'Giant Panda', E'The worldwide population of wild giant pandas increased by 268 over the last decade according to a new survey conducted by the government of China. The increase in population brings the total number of wild giant pandas to 1864. The population increase represents 16.8% rise compared to the last panda survey in 2003. Wild giant pandas, a global symbol of wildlife conservation, are found only in China’s Sichuan, Shanxi and Gansu provinces.\nAccording to the report, formally known as the Fourth National Giant Panda Survey, the geographic range of pandas throughout China also increased. The total area inhabited by wild giant pandas in China now equals 2,577,000 hectares, an expansion of 11.8% since 2003.\n"These results are a testament to the conservation achievements of the Chinese government," said Xiaohai Liu, executive director of programs, WWF- China. "A lot of good work is being done around wild giant panda conservation, and the government has done well to integrate these efforts and partner with conversation organizations including WWF.\nThe report, the fourth in a series of decadal (10- year) surveys conducted by the State Forestry Administration of China, began in 2011 with financial and technical support from WWF. Much of the success in increasing the panda population comes as a result of conservation policies implemented by the Chinese government, including the Natural Forest Protection Project and Grain for Green.\nThe report found that 1,246 wild giant pandas live within nature reserves, accounting for 66.8% of the total wild population, and the habitat within nature reserves accounts for 53.8% of the total habitat area. There are currently 67 panda nature reserves in China, an increase of 27 since the last report.', NULL, NULL, E'The worldwide population of wild giant pandas increased by 268 over the last decade, which brings the total number of wild giant pandas to 1864, where the total area inhabited by wild giant pandas in China now equals 2,577,000 hectares, while much of the success in increasing the panda population comes as a result of conservation policies implemented by the Chinese government, and 1,246 wild giant pandas live within nature reserves.', NULL, 5, 75),
  ('7d1b1bbb-1211-548c-9f72-a5609bef2837'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7d1b1bbb-1211-548c-9f72-a5609bef2837'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call the gradual increase in the overall temperature of the Earth''s atmosphere generally attributed to the greenhouse effect?', '6118ff79-fd8f-5cb2-b7b0-bbed9e3892f8'::uuid, NULL, NULL, E'Global Warming', NULL, NULL),
