  ('7ea70b27-e534-52ef-8eba-f4b2122960bc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7ea70b27-e534-52ef-8eba-f4b2122960bc'::uuid, 1, NULL, TRUE, 0, NULL, E'Forest', E'The forest was a symphony of sound and color, the rustling of leaves and the chirping of birds creating a harmonious melody. The trees towered above, their branches reaching towards the sky. The air was fresh and invigorating, filled with the scent of pine and earth. In this natural oasis, the hustle and bustle of the city felt worlds away.', NULL, NULL, NULL, NULL, NULL, NULL),
