  ('7ec87689-cd40-51dd-9267-e328ded4cb25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7ec87689-cd40-51dd-9267-e328ded4cb25'::uuid, 1, NULL, TRUE, 0, NULL, E'Mice', E'A new study in mice finds that a high-fat diet allows cancer cells to outcompete immune cells for fuel, impairing immune function and accelerating tumor growth. Cancer cells do so by rewiring their metabolisms to increase fat consumption. Blocking this rewiring enhances anti-tumor immunity. The findings suggest new strategies to target cancer metabolism and improve immunotherapies.', NULL, NULL, NULL, NULL, NULL, NULL),
