  ('7f07e5fd-c09c-5044-becb-c852715045c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7f07e5fd-c09c-5044-becb-c852715045c6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd0c4b946-df49-50a0-8e7b-013b9108cbd3'::uuid, NULL, E'The medicine always made him feel sleepy and unable to concentrate.', NULL, NULL, NULL),
