  ('7f7a2529-8fbb-5529-834d-47ef227f74b0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '7f7a2529-8fbb-5529-834d-47ef227f74b0'::uuid, 1, NULL, TRUE, 0, NULL, E'Parent Invitation', E'We invite parents to participate in a program {{1}} three times a year. The details of the program will be {{2}} on our website. We {{3}} parents to {{4}} so that their children can {{5}} .', NULL, NULL, NULL, E'1.held, 2.posted, 3.expect, 4.attend, 5.succeed', NULL, NULL),
  ('7f83189f-b981-5619-8c4a-19e34646c4c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7f83189f-b981-5619-8c4a-19e34646c4c5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4425a8e1-de93-58c9-8be4-3f525dfc20ce'::uuid, NULL, NULL, E'The teacher asked the group to commence the task.', NULL, NULL),
  ('7f85be0a-a36a-5a67-980a-11b3206f9870'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '7f85be0a-a36a-5a67-980a-11b3206f9870'::uuid, 1, NULL, TRUE, 0, NULL, E'Keep Quiet(保持安静)', NULL, NULL, NULL, NULL, E'5, 3, 2, 1, 4', NULL, NULL),
  ('7f8d7e83-2fc7-513a-9e29-6d85d33bb5e4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7f8d7e83-2fc7-513a-9e29-6d85d33bb5e4'::uuid, 1, NULL, TRUE, 0, NULL, E'Amerlia Earhart', NULL, 'd7f34022-05f6-58f8-8e17-62b90433e99c'::uuid, NULL, E'Today, I am excited to share the inspiring story of Amelia Earhart, a trailblazing aviator whose courage and determination broke barriers in the sky and paved the way for future generations. Her story goes beyond her achievements in aviation; it''s a testament to the power of ambition and resilience. Amelia Earhart was not only the first female aviator to fly solo across the Atlantic Ocean, but she also set numerous flying records and championed the advancement of women in aviation. Her 1932 solo transatlantic flight was a remarkable feat that challenged the prevailing norms of her time and showcased her exceptional skills and bravery. Despite facing numerous obstacles, including societal expectations and technical challenges, Earhart remained undeterred. Her pioneering spirit was evident in her tireless efforts to promote aviation and women''s rights, making her a role model and an icon of empowerment. Tragically, Earhart''s quest to circumnavigate the globe in 1937 ended in mystery, but her legacy endures. She remains an enduring symbol of adventurous spirit and perseverance, inspiring countless individuals to chase their dreams, no matter how insurmountable they may seem. Amelia Earhart''s life story is more than an aviation tale; it''s a narrative about breaking barriers and redefining possibilities, encouraging us all to soar to new heights.', NULL, NULL, NULL),
  ('7f8fdbf4-839a-5c5f-b0e8-dc2230c7935e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '7f8fdbf4-839a-5c5f-b0e8-dc2230c7935e'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-R', E'Many of today''s most trusted sales techniques were invented over a century ago by a young merchant named Eaton in Toronto. When he was young, Eaton worked briefly with his brothers in small-town stores. In 1869, he set up his own shop in downtown Toronto. He had many competitors, but he was also ambitious and had a plan for success. He offered a unique style of trade, but as was expected, all the other shopkeepers laughed at him, believing he would eventually fail. However, Eaton was not a man to be easily defeated; he came up with a brand new notion of business - ''Goods satisfactory, or money refunded.'' He sold all his goods at fixed prices and only for cash.\n\nThe best description of Eaton is that', NULL, NULL, NULL, E'he introduced new sales practices', NULL, NULL),
  ('7f944f44-9bf8-503e-9c6d-3d6db2ca2ffc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7f944f44-9bf8-503e-9c6d-3d6db2ca2ffc'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '984638fa-39b4-5923-a29c-adefbdf2e69d'::uuid, NULL, E'On our campus, prospective students have access to thirteen college libraries.', NULL, NULL, NULL),
  ('7f97bbc7-938f-5c16-91a6-be89f4c79a8e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7f97bbc7-938f-5c16-91a6-be89f4c79a8e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ea7556c2-44db-595f-9491-bab57c3d29ad'::uuid, NULL, NULL, E'Rising inflation leads to increasing goods prices and decreasing demand for products.', NULL, NULL),
  ('7fa1ead5-11c5-5a40-b498-c4eef01374a5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7fa1ead5-11c5-5a40-b498-c4eef01374a5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7b3a47e0-cd26-5004-a91c-bbc0a222f16f'::uuid, NULL, NULL, E'A demonstrated ability to write clear, correct and concise English is obligatory.', NULL, NULL),
  ('7fa44dd9-a60d-547a-b309-967326cf665d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '7fa44dd9-a60d-547a-b309-967326cf665d'::uuid, 1, NULL, TRUE, 0, NULL, E'New Republic', E'The essential problem, as Rosenfeld sees it, is that {{1}} government is predicated on an aspiration to collective truth. {{5}} older systems of aristocratic and monarchical rule, which excluded the people from power and stressed the need for administrative secrecy, the new republics of the late 18th century, and the more egalitarian mass democracies that {{2}} them, depended on openness and trust between citizens and rulers. Through the free discussion and united wisdom of the educated and the masses, errors would be dispelled, ''public knowledge'' established and societies advanced. And yet, she points out, the reality has never {{3}} this powerful ideal. From the outset, democratic societies contained vast inequalities of power and education, and their media have always been driven by commercial and partisan imperatives. {{4}} , instead of a free civil marketplace of ideas, politics has always been a vicious fight over the truth and the power of determining it.', NULL, NULL, NULL, E'1.democratic, 2.Unlike, 3.succeeded, 4.lived up to, 5.In practice', NULL, NULL),
  ('7fa5a62e-dc28-504d-b0a4-37fc7b974b58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '7fa5a62e-dc28-504d-b0a4-37fc7b974b58'::uuid, 1, NULL, TRUE, 0, NULL, E'Cognitive Health', E'Neuropsychological testing is one way to {{1}} cognitive health. However, this option can be costly and labor intensive. In many cases, basic screening will suffice for an understanding of a given individual''s cognitive health status. There are a number of excellent tools available to {{2}} for basic screening and tracking of cognitive health. Many of these tools are designed for use with older people, but some are meant for use with younger people as well. The Alzheimer''s Association website offers a cognitive assessment toolkit that includes the Medicare Annual Wellness Visit algorithm for the assessment of cognition. This assessment uses patient history, observations by clinicians, and concerns {{3}} by the patient, family, or caregivers. The toolkit further includes three measures {{4}} for use by professionals to assess and track a patient''s cognitive health. These measures include the General Practitioner Assessment of Cognition, Memory Impairment Screen, and the Mini-Cog brief psychometric test.', NULL, NULL, NULL, E'1.assess, 2.practitioners, 3.raised, 4.validated', NULL, NULL),
  ('7fa77420-5b3e-583e-ae34-64db4b13754a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7fa77420-5b3e-583e-ae34-64db4b13754a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How would you describe an animal that no longer exists on the earth?', 'eabad217-c7c9-55d6-9382-fafa14a3e13c'::uuid, NULL, NULL, E'Extinct', NULL, NULL),
  ('7fad30cb-11d1-5ab0-bd23-140537b2cd96'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '7fad30cb-11d1-5ab0-bd23-140537b2cd96'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4bcde667-cb36-57be-9d3c-461dc64babf6'::uuid, NULL, NULL, E'Psychology and philosophy aren''t really related most of the time.', NULL, NULL),
  ('7fb1fc05-44d6-5ecd-8b49-a3905e1ad199'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '7fb1fc05-44d6-5ecd-8b49-a3905e1ad199'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-R', E'In seeking to describe the origins of theater, one must rely primarily on speculation, since there is little concrete evidence on which to draw. The most widely accepted theory, championed by anthropologists in the late nineteenth and early twentieth centuries, envisions theater as emerging out of myth and ritual. The process perceived by these anthropologists may be summarized briefly. During the early stages of its development, a society becomes aware of forces that appear to influence or control its food supply and well-being. Having little understanding of natural causes, it attributes both desirable and undesirable occurrences to supernatural or magical forces, and it searches for means to win the favor of these forces. Perceiving an apparent connection between certain actions performed by the group and the result it desires, the group repeats, refines and formalizes those actions into fixed ceremonies, or rituals.Stories (myths) may then grow up around a ritual. Frequently the myths include representatives of those supernatural forces that the rites celebrate or hope to influence. Performers may wear costumes and masks to represent the mythical characters or supernatural forces in the rituals or in accompanying celebrations. As a person becomes more sophisticated, its conceptions of supernatural forces and causal relationships may change. As a result, it may abandon or modify some rites. But the myths that have grown up around the rites may continue as part of the group''s oral tradition and may even come to be acted out under conditions divorced from these rites. When this occurs, the first step has been taken toward theater as an autonomous activity, and thereafter entertainment and aesthetic values may gradually replace the former mystical and socially efficacious concerns.\n\nAccording tothis passage, why did some societies develop and repeat ceremonial actions?', NULL, NULL, NULL, E'To increase the society’s prosperity', NULL, NULL),
  ('7fba58ca-e16b-54f7-bf84-3e830f9ad26b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7fba58ca-e16b-54f7-bf84-3e830f9ad26b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b7e4e9c7-e3e6-559c-adc0-603919dc6367'::uuid, NULL, E'Globalization problems require global solutions.', NULL, NULL, NULL),
  ('7fbc38d8-8893-508a-b30e-be53652835c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '7fbc38d8-8893-508a-b30e-be53652835c8'::uuid, 1, NULL, TRUE, 0, NULL, E'Christmas Tree Plantations', E'Christmas tree plantations can provide a {{1}} to biodiversity, especially in areas where it has been {{2}} as agriculture becomes more intensified. This is because the plantations tend to have open habitat structures rich in bare ground, which can allow higher {{3}} to food resources, and their fences can also keep out the {{4}} from humans and dogs.', NULL, NULL, NULL, E'1.boost, 2.declining, 3.accessibility, 4.disruption', NULL, NULL),
  ('7fbfeb75-941d-5e11-a79c-3ba71a486a4d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7fbfeb75-941d-5e11-a79c-3ba71a486a4d'::uuid, 1, NULL, TRUE, 0, NULL, E'Small Pebble', E'Analyses on a small pebble found in south-west Egypt cast significant questions on a widely-held view about the primitive pre-solar dust cloud which our Sun, Earth and other planets were formed from. Researchers found exotic micro-mineral compounds in the ''Hypatia'' stone that are not known to occur on Earth, elsewhere in our solar system, or in known meteorites or comets.', NULL, NULL, NULL, NULL, NULL, NULL),
