  ('7fcaad1e-fc05-509e-a25b-6f14e3712d82'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7fcaad1e-fc05-509e-a25b-6f14e3712d82'::uuid, 1, NULL, TRUE, 0, NULL, E'Visual Images', E'Visual images always have a strong appeal compared to words. Using projectors and visuals to aid in learning is another form of great technological use. Top institutions around the world, now rely on the use of amazing PowerPoint presentations and projections in order to keep the learning interactive and interesting.', NULL, NULL, NULL, NULL, NULL, NULL),
