  ('7fd9ac6e-8b62-5f6f-b83c-ae7b47800afd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '7fd9ac6e-8b62-5f6f-b83c-ae7b47800afd'::uuid, 1, NULL, TRUE, 0, NULL, E'Competence in Chemistry', E'A level of competence in chemistry is essential to the professional practice of material conservation. An understanding of scientific concepts and a basic scientific vocabulary enables the conservator to understand conservation problems, treatments, material techniques in a systematic and quantifiable way, which can be communicated not only to colleagues in the profession but also those from other disciplines.', NULL, NULL, NULL, NULL, NULL, NULL),
