  ('7fde7e0e-ae76-5190-8d55-9a53121c49a5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '7fde7e0e-ae76-5190-8d55-9a53121c49a5'::uuid, 1, NULL, TRUE, 0, NULL, E'University Nearby', E'Some students choose university near where they live and continue to stay at home with families, other students choose university away from family, what is the advantages and disadvantages for both sides.', NULL, NULL, NULL, NULL, 200, 300),
