  ('80d35c42-cfe4-5505-9a54-1ddefa27fc54'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '80d35c42-cfe4-5505-9a54-1ddefa27fc54'::uuid, 1, NULL, TRUE, 0, NULL, E'Honorary Fellowship', E'The Royal Geological Society recently {{1}} an honorary fellowship to a pioneering environmental scientist at a prestigious ceremony. Dr. Eliza Montgomery has been recognized for her groundbreaking work in climate change research, {{2}} her studies on the impact of deforestation on global weather patterns. Dr. Montgomery''s work has significantly advanced our understanding of how terrestrial ecosystems influence climate dynamics. Her research, which employs both satellite imagery and field data, {{3}} light on the critical role of forests in carbon sequestration and their effect on atmospheric conditions. Beyond her research, Dr. Montgomery has been instrumental in shaping environmental policy through her advisory roles on several international environmental panels. Her {{4}} to environmental education has also led her to mentor the next generation of scientists, emphasizing the importance of sustainable practices. As she accepted her fellowship, Dr. Montgomery stressed the {{5}} of addressing climate change and the responsibility of the scientific community to lead the way in finding viable solutions.', NULL, NULL, NULL, E'1.awarded, 2.particularly, 3.has shed, 4.commitment, 5.urgency', NULL, NULL),
  ('80e20c45-f98a-5e0b-8733-eace8b11908a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '80e20c45-f98a-5e0b-8733-eace8b11908a'::uuid, 1, NULL, TRUE, 0, NULL, E'Wildlife Overpass', E'A newly constructed wildlife overpass has {{1}} successful in reducing animal-vehicle collisions on a busy highway. The overpass is part of a larger initiative to create safe migration {{2}} for wildlife, which also promotes genetic diversity by connecting animal populations that were previously {{3}} by roads.', NULL, NULL, NULL, E'1.proven, 2.routes, 3.segmented', NULL, NULL),
