  ('812b05f6-2ae0-5cda-81c2-05dbc3c7aa3a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '812b05f6-2ae0-5cda-81c2-05dbc3c7aa3a'::uuid, 1, NULL, TRUE, 0, NULL, E'Monarch Butterfly', E'The Monarch butterfly, {{1}} from various regions in North America, travel thousands of miles to reach their wintering grounds in the mountains of central Mexico. Remarkably, this {{2}} is not made by a single butterfly but is a multi-generational trek. Each year, {{3}} generations of monarchs complete different legs of the journey, {{4}} on a combination of environmental cues and inherited instincts to find their way to a {{5}} they have never seen before.', NULL, NULL, NULL, E'1.originating, 2.journey, 3.successive, 4.relying, 5.destination', NULL, NULL),
  ('8137a69b-5161-5c51-a625-1cbf8708f66a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8137a69b-5161-5c51-a625-1cbf8708f66a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'dec8aee0-4e89-5955-b408-986ac22bce61'::uuid, NULL, E'Read the instructions carefully before you start writing your essay.', NULL, NULL, NULL),
  ('81381920-41e9-568d-be30-fc893364d55f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '81381920-41e9-568d-be30-fc893364d55f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '715b7416-08e4-54b0-acfc-2c998c80f3b9'::uuid, NULL, NULL, E'The seminar offers opportunities to exchange and discuss ideas with peers.', NULL, NULL),
  ('814480f4-f722-5491-bb74-48de5b820e36'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '814480f4-f722-5491-bb74-48de5b820e36'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you throw underwater to keep ships staying on rivers or oceans without drifting away?', '3fb76d87-cf01-5be4-8047-75c0f88c92c2'::uuid, NULL, NULL, E'Anchor', NULL, NULL),
  ('8144f16c-6dad-5e2f-b0cc-d377ba039af4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '8144f16c-6dad-5e2f-b0cc-d377ba039af4'::uuid, 1, NULL, TRUE, 0, NULL, E'Humanities', E'Some say that in today’s world the value of humanities has been eclipsed by the necessity of preparing for specific wealth-producing careers, such as medicine. What is your opinion about a role in today’s changing world for study of the humanities?', NULL, NULL, NULL, NULL, 200, 300),
  ('81484f97-78e6-5748-b0a1-406841af15c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '81484f97-78e6-5748-b0a1-406841af15c4'::uuid, 1, NULL, TRUE, 0, NULL, E'Calories Consumption', E'Whether people on a diet eat most of their calories at breakfast or at dinner has no effect on weight loss, but it does {{1}} how hungry they are. Previous research on the importance of calorie distribution across meals for weight loss has been mixed. Some studies have suggested that {{2}} up at breakfast improves weight loss, while others have concluded that it doesn’t make a difference, even if you skip breakfast altogether. Settling questions like this is difficult because most nutrition research is {{3}} and often relies on people’s own reports of what they consumed and when, which can be unreliable. To get a clearer picture, Alexandra Johnstone at the University of Aberdeen in the UK and her colleagues recruited 30 adults who were overweight or obese and had no other underlying health conditions. By the end of the study, the researchers found that there was little difference in how much weight participants lost when they ate more in the morning or the evening. That suggests calories are metabolized the same {{4}} of when they are consumed, says Johnstone.', NULL, NULL, NULL, E'1.affect, 2.filling, 3.observational, 4.regardless', NULL, NULL),
  ('814a928f-65f1-55e3-8f2d-6f080fad6c09'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '814a928f-65f1-55e3-8f2d-6f080fad6c09'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'bbf97020-1096-5cfc-805b-5fcada37d24e'::uuid, NULL, NULL, E'Parents usually talk to their kids in simple ways.', NULL, NULL),
  ('814c688b-4bab-5c5a-b281-cc7857debfca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '814c688b-4bab-5c5a-b281-cc7857debfca'::uuid, 1, NULL, TRUE, 0, NULL, E'Coding Languages', E'Coding languages, {{1}} to modern technology, emerged from the convergence of mathematical logic and electronic engineering. Initially {{2}} for specific tasks, they evolved to create complex systems and applications. Python, known for its simplicity and readability, has become widely used in {{3}} fields from web development to data science. Moreover, it is constantly evolving and improving, as new features and enhancements are {{4}} into the language and its library every year.', NULL, NULL, NULL, E'1.integral, 2.developed, 3.diverse, 4.incorporated', NULL, NULL),
  ('814ff506-5ea1-51b3-9340-e14385db0d31'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '814ff506-5ea1-51b3-9340-e14385db0d31'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '14148a20-d051-55fd-91af-554e882a8fc4'::uuid, NULL, NULL, E'Social support has played a role in reducing work stress.', NULL, NULL),
  ('8150c14e-fe2e-55bf-86c0-d49127a91649'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '8150c14e-fe2e-55bf-86c0-d49127a91649'::uuid, 1, NULL, TRUE, 0, NULL, E'Life Success', E'Some people believe that success in life comes from taking risks or chances. Others believe that success results from careful planning. What is your opinion about success?', NULL, NULL, E'In today''s fast-paced and competitive world, the concept of success has become an integral part of our lives. While some people believe that success is a result of taking risks, others believe that it is the outcome of careful planning. In my opinion, success can come from both taking risks and careful planning.\nFirstly, taking risks can lead to unexpected opportunities. When we step out of our comfort zones and take risks, we open ourselves up to new experiences and opportunities that we may not have encountered otherwise. For example, starting a new business venture or pursuing a new career path may involve taking risks, but it can also lead to great rewards and personal growth.\nSecondly, careful planning can increase efficiency and productivity. When we plan ahead and set clear goals, we can work towards achieving them in a more organized and efficient manner. This can help us to stay focused and motivated, and ultimately achieve success. For instance, planning a project or a task can help us to identify potential obstacles and come up with strategies to overcome them.\nIn conclusion, success is not just a result of taking risks or careful planning, but rather a combination of both. By taking calculated risks and planning ahead, we can achieve our goals and reach new heights in our personal and professional lives. It is important to strike a balance between the two approaches in order to achieve success in a sustainable and fulfilling way.', NULL, 200, 300),
  ('8161a4c0-a224-59a1-8359-15a553b82427'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8161a4c0-a224-59a1-8359-15a553b82427'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a sudden shake of the Earth’s surface?', '80cccf37-aaa2-5321-b3a7-b1ae51e7e971'::uuid, NULL, NULL, E'Earthquake', NULL, NULL),
  ('8161a908-153f-51c5-8002-1ac8e98fd693'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '8161a908-153f-51c5-8002-1ac8e98fd693'::uuid, 1, NULL, TRUE, 0, NULL, E'Tourism''s Pros and Cons', E'For a less developed country, the disadvantages of tourism are as great as the advantages. Please discuss this statement, and explain your opinion.', NULL, NULL, E'Tourism is an industry that has grown rapidly in recent years, providing significant benefits to many countries around the world. While some argue that tourism has negative impacts on less developed countries, such as overdevelopment and cultural erosion, I believe that the advantages of tourism outweigh the disadvantages. In this essay, I will explore the positive aspects of tourism.\nOne of the most significant benefits of tourism is its ability to create job opportunities and boost the economy. Tourism can provide employment opportunities in a variety of industries, including hospitality, transportation, and retail. Additionally, it can stimulate economic growth by increasing demand for goods and services. For example, the World Tourism Organization estimates that tourism accounts for 10% of global GDP and provides jobs for one in ten people worldwide.\nAnother benefit of tourism is its ability to promote cultural exchange and understanding between countries. Tourism allows individuals to experience different cultures and customs, which can lead to greater understanding and appreciation of diversity. Additionally, it can promote cultural preservation by providing funding for the maintenance and restoration of historical and cultural sites. For example, the revenue generated from tourism has allowed countries such as Cambodia to restore ancient temples and protect cultural heritage sites.\nIn conclusion, while some may argue that tourism has negative impacts on less developed countries, I believe that the advantages of tourism outweigh the disadvantages.', NULL, 200, 300),
  ('816cd5cb-3086-5a79-bc61-0a3ccb5f126a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '816cd5cb-3086-5a79-bc61-0a3ccb5f126a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '691af0ec-3674-5570-a635-f3df429dc03c'::uuid, NULL, E'Advertisements need to appeal to people of different ages, socioeconomic backgrounds, and genders.', NULL, NULL, NULL),
  ('817098e4-fdcf-5a72-b6c8-46ee3d4c3e73'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '817098e4-fdcf-5a72-b6c8-46ee3d4c3e73'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '018141bc-099a-5d3f-a2a0-a4a90b9ddd09'::uuid, NULL, E'Talented people do specialized marketing.', NULL, NULL, NULL),
  ('817275e2-ceb7-5070-9c2e-ab0306d5eda0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '817275e2-ceb7-5070-9c2e-ab0306d5eda0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'dfaa6d8b-a956-5e0c-8484-471d905988e9'::uuid, NULL, E'Our future well-being depends on the actions we take now.', NULL, NULL, NULL),
  ('8174f2b0-e681-5c0e-8a0e-81490f3be433'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8174f2b0-e681-5c0e-8a0e-81490f3be433'::uuid, 1, NULL, TRUE, 0, NULL, E'Unity In Chimpanzees', NULL, 'b570d815-341c-52e1-b0e3-5a471cdfea79'::uuid, NULL, E'Now let me first show you how the unity is shown in chimpanzees. What you see here is two males on the left who are standing together. You also see the big canine teeth that they have. And they’re standing together and they demonstrate to the rest of the group, “We are together. We are a unit.” The males on the right are walking together in synchrony. That’s another way of demonstrating that you are together. And so demonstrating unity is extremely important in a coalition system, and as I said, in the primaries always I’m waiting for that moment because then you have two members of the same party who have been fighting with each other, and they need to come together at some moment. And it leads to very awkward situations. People who don’t like each other need to embrace each other and stand together, and that’s absolutely essential for the unity of the party, and if you don’t do that, the party may fall apart. And so if it doesn’t go well, like in this particular case — then the party is in deep doo-doo because they have not demonstrated unity.', NULL, NULL, NULL),
  ('8175947d-3828-51cc-9756-55fba8bddc43'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8175947d-3828-51cc-9756-55fba8bddc43'::uuid, 1, NULL, TRUE, 0, NULL, E'Choice of Book', E'This book is no ordinary book, and should not be read through from beginning to end. It contains many different adventures, and the path you take will depend on the choices you make along the way. The success or failure of your mission will depend on the decisions you make, so think carefully before choosing.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('81760e21-db80-58bc-b070-c2b0afec0579'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '81760e21-db80-58bc-b070-c2b0afec0579'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the policy aimed at equalizing the distribution of wealth and opportunity?', '78301955-b00e-5d49-81f1-62ef27859cb2'::uuid, NULL, NULL, E'Socialism', NULL, NULL),
  ('817821a9-fb46-579b-b27f-1b6262e47501'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '817821a9-fb46-579b-b27f-1b6262e47501'::uuid, 1, NULL, TRUE, 0, NULL, E'Columbus', E'On October 12, 1492 (the first day he encountered the native people of the Americas) , Columbus wrote in his journal: They should be good servants . I, our Lord being pleased, will take hence, at the time of my departure, six natives for your Highnesses. These captives were later paraded through the streets of Barcelona and Seville when Columbus returned to Spain.From his very first contact with native people, Columbus had their domination in mind. For example, on October 14, 1492, Columbus wrote in his journal,with fifty men they can all be subjugated and made to do what is required of them. These were not mere words: after his second voyage, Columbus sent back a consignment of natives to be sold as slaves.Yet in an April, 1493, letter to Luis de Santangel (a patron who helped fund the first voyage), Columbus made clear that the people he encountered had done nothing to deserve ill treatment.', NULL, NULL, E'On October 12, 1492, when he encountered the native people of the Americas , Columbus wrote in his journal: they should be good servants, and from his very first contact with native people, Columbus had their domination in mind, but in an April, 1493, letter to Luis de Santangel, a patron who helped fund the first voyage, Columbus made clear that the people he encountered had done nothing to deserve ill treatment.', NULL, 5, 75),
  ('8179642c-a336-5c96-97b1-d6977c497c53'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8179642c-a336-5c96-97b1-d6977c497c53'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'cef98db4-46bf-5c0b-8cd7-666bcd6eb787'::uuid, NULL, NULL, E'Behind the barn, there is a flat cart drawn by mules.', NULL, NULL),
  ('817ed67f-8ea0-56b2-81af-817759517eb8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '817ed67f-8ea0-56b2-81af-817759517eb8'::uuid, 1, NULL, TRUE, 0, NULL, E'Traffic Jams', E'For the first time Japanese researchers have {{1}} a real-life experiment that shows how some traffic jams appear for no apparent reason. They placed 22 vehicles on a single track and asked the drivers to {{2}} around at a constant speed of 30 kilometers an hour. At first, traffic moved {{3}} but soon the distance between cars started to vary and vehicles clumped together at one point on the track. But the jams {{4}} backwards around the track like a shock wave at a rate of about 20 kilometers an hour. Real-life jams move backwards at about the same speed.', NULL, NULL, NULL, E'1.conducted, 2.cruise, 3.smoothly, 4.spread', NULL, NULL),
  ('818934e4-a0e7-5639-85e2-8d6b94dc8625'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '818934e4-a0e7-5639-85e2-8d6b94dc8625'::uuid, 1, NULL, TRUE, 0, NULL, E'Male Chicks', E'Male chicks have been dealt a bad hand. They don’t lay eggs and typically have less meat on their bones than hens, meaning they’re not only useless but a {{1}} to farmers. As such, these undesirable byproducts of egg production may be killed through gassing. The mass culling of male chicks is not only tragic but also resource-intensive for farmers, who must manually {{2}} males from females shortly after they hatch. But a groundbreaking development could have major implications for animal welfare in the poultry industry, perhaps finally putting an end to the {{3}} of an estimated seven billion male chicks each year shortly after they hatch due to their lack of commercial value. Israeli researchers have created gene-edited hens that lay eggs from which only female chicks hatch. The team, led by Dr. Enbal Ben-Tal Cohen, used gene-editing tools to {{4}} hens that produce eggs with unviable male embryos when exposed to blue light for several hours. Female chick embryos are unaffected by the light and continue to develop normally.', NULL, NULL, NULL, E'1.liability, 2.sort, 3.culling, 4.breed', NULL, NULL),
  ('818c96d7-2e2e-5cb6-948e-a7496cb8413c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '818c96d7-2e2e-5cb6-948e-a7496cb8413c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '95dad5c0-9514-5786-9e0f-34da8815a48d'::uuid, NULL, NULL, E'Most teaching staff make their lecture notes available online.', NULL, NULL),
  ('818ecd68-36b2-54d9-a744-c0ed27ae8c10'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '818ecd68-36b2-54d9-a744-c0ed27ae8c10'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-R', E'The success of fluoride in combating dental decay is well established and, without a doubt, socially beneficial. However, fluoride''s toxic properties have been known for a century. In humans excessive intake (for adults, over 4 milligrams per day) over many years can lead to skeletal fluorosis, a well-defined skeletal disorder, and in some plant species, fluoride is more toxic than ozone, sulfur dioxide, or pesticides.Some important questions remain. For example, the precise lower limit at which the fluoride content of bone becomes toxic is still undetermined. And while fluoride intake from water and air can be evaluated relatively easily, it is much harder to estimate how much a given population ingests from foodstuffs because of the wide variations in individual eating habits and in fluoride concentrations in foodstuffs. These difficulties suggest that we should be wary of indiscriminately using fluoride, even in the form of fluoride-containing dental products.\n\nIn the passage, the author is primarily concerned with', NULL, NULL, NULL, E'describing and cautioning', NULL, NULL),
  ('81908d01-49ac-5125-87e1-9d4f307e83ad'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '81908d01-49ac-5125-87e1-9d4f307e83ad'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '04cc77c8-bf41-5583-8864-351f15519a05'::uuid, NULL, E'They had been forced to find cheap tickets in the gallery.', NULL, NULL, NULL),
  ('8192d69e-fc59-505b-b9ad-6fb800ab444d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '8192d69e-fc59-505b-b9ad-6fb800ab444d'::uuid, 1, NULL, TRUE, 0, NULL, E'Graphene', E'Fascination with this material stems from its remarkable physical properties and the potential applications these properties offer for the future. {{1}} scientists knew one atom thick, two-dimensional crystal graphene existed, no-one {{2}} out how to extract it from graphite.\nThat was until it was isolated in 2004 by two researchers at The University of Manchester, Professor Andre Geim and Professor Kostya Novoselov. This is the story of how that stunning scientific feat came about and why Andre and Kostya won the Nobel Prize in Physics for their pioneering work.\nAndre and Kostya frequently held ''Friday night experiments'' - sessions where they would try out experimental science that wasn’t {{3}} linked to their day jobs.', NULL, NULL, NULL, E'1.Although, 2.had worked, 3.necessarily', NULL, NULL);
INSERT INTO _pte_local_seed_questions (question_public_id, created_at, updated_at, deleted, pte_task_type, task_type_key, task_type_section, visibility, tenant_id, status, revision_group_public_id, revision_number, supersedes_public_id, is_current, version, rejection_reason, title, prompt_text, audio_prompt_ref, image_prompt_ref, reference_answer_text, correct_answer_text, min_word_count, max_word_count) VALUES
  ('8197b270-f7b3-5327-bb4a-6d469c5d8ad8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8197b270-f7b3-5327-bb4a-6d469c5d8ad8'::uuid, 1, NULL, TRUE, 0, NULL, E'Astronomic Discovery', E'Astronomers discovered seven planets, roughly Earth-sized, orbiting a dwarf star some 380 trillion kilometers from our own. That is 40 light years away—fairly close and within range of planned big telescopes. Scientists therefore think it offers the best chance yet to discover evidence of life, or why it hasn’t evolved, beyond the solar system.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('819bae93-2f15-56e2-a93c-1e50f3975c79'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '819bae93-2f15-56e2-a93c-1e50f3975c79'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which kind of books are more expensive, hardcover or softcover?', '85b06c6f-3f5b-5b6d-9824-3a2a37f8b9b5'::uuid, NULL, NULL, E'Hardcover', NULL, NULL),
  ('81a62905-420b-5624-934c-9681796bd6ce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '81a62905-420b-5624-934c-9681796bd6ce'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '208a3c92-3bfb-5edf-a38c-99618217a17c'::uuid, NULL, NULL, E'The teacher training includes observing the classes.', NULL, NULL),
  ('81a650da-1569-5d22-a8a1-1904cb934522'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '81a650da-1569-5d22-a8a1-1904cb934522'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'When you want to include a picture or other file into an email, what will you do?', '11067d0c-e1a0-5138-b128-50139c70b882'::uuid, NULL, NULL, E'Attach', NULL, NULL),
  ('81a67df3-071a-5fda-8cd8-b9d7b162b934'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '81a67df3-071a-5fda-8cd8-b9d7b162b934'::uuid, 1, NULL, TRUE, 0, NULL, E'Hearing Ability', E'In the animal kingdom, ear size doesn''t necessarily determine hearing ability. Compare bats and chinchillas. They both have large, prominent ears but vastly different frequency ranges. Bats can hear from 2,000 to 110,000 hertz (Hz), while chinchillas can detect only 90 to 22,800 Hz. And in most large-eared animals, ear size has more to do with keeping the animal cool than it does with helping it detect sound. Consider how much larger the ears of African elephants are than those of Asian elephants. Those giant ears help redirect heat from the body — a useful attribute in a hot climate.\nLet''s get back to people. The external portion of our ears (also known as the pinna) has two main purposes: to protect the ear canal and to channel sound into it. Neither of these functions are improved in larger ears — the shape of our ears is much more important here. But keep in mind that the broad variety of human earlobe shapes doesn''t impact hearing differences. Unless there''s a congenital defect, the basic structure of the ear is relatively the same in all people. While the pinna does play an important role, the mechanisms most critical to hearing are found deeper within. These sound receptors help transmit auditory signals to the brain, so they''re tucked safely away in the inner ear. Therefore, hearing ability is not connected to ear size.', NULL, NULL, NULL, NULL, 5, 75),
  ('81a75a68-ba70-5918-9be9-8c5c4a5be032'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '81a75a68-ba70-5918-9be9-8c5c4a5be032'::uuid, 1, NULL, TRUE, 0, NULL, E'Climate Feedback Loops', E'The climate feedback loops propose essential {{1}} into the course of global warming, and thus it is {{2}} to take it into account to create a more accurate depiction of the current state of the climate. In order to achieve carbon neutrality and a state of environmental {{3}} , it is important to {{4}} the threats proposed by the climate feedback loops.', NULL, NULL, NULL, E'1.insight, 2.imperative, 3.equilibrium, 4.address', NULL, NULL),
  ('81ac6056-c85d-538f-a7b8-a76aa2a95868'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '81ac6056-c85d-538f-a7b8-a76aa2a95868'::uuid, 1, NULL, TRUE, 0, NULL, E'Racial and Ethnic Disparities', NULL, NULL, NULL, NULL, E'2, 3, 1, 4', NULL, NULL),
  ('81ae7577-dd25-515b-b786-785b592549f3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', '81ae7577-dd25-515b-b786-785b592549f3'::uuid, 1, NULL, TRUE, 0, NULL, E'Whig Party', E'During Jackson''s second term, his opponents had gradually come together to form the Whig party. Whigs and Democrats held different attitudes toward the changes brought about by the market, banks, and commerce. The Democrats tended to view society as a continuing conflict between "the people"—farmers, planters, and workers—and a set of greedy aristocrats. This "paper money aristocracy" of bankers and investors manipulated the banking system for their own profit, Democrats claimed, and sapped the nation''s virtue by encouraging speculation and the desire for sudden, unearned wealth. The Democrats wanted the rewards of the market without sacrificing the features of a simple agrarian republic. They wanted the wealth that the market offered without the competitive, changing society; the complex dealing; the dominance of urban centers; and the loss of independence that came with it.\n\nThe author mentions bankers and investors in the passage as an example of which of the following?', NULL, NULL, NULL, E'The people that Democrats claimed were unfairly becoming rich\nOne of the groups might be not in favor of Whig party and Democrats', NULL, NULL),
  ('81bc84d7-7efd-54e0-96ac-df412bc6839e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '81bc84d7-7efd-54e0-96ac-df412bc6839e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7bba6230-5d69-5990-9fef-4f34fcd6f24c'::uuid, NULL, NULL, E'Art must strike a balance between originality and public appeal.', NULL, NULL),
  ('81c10b1b-42dc-525d-9b90-77423c85be52'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '81c10b1b-42dc-525d-9b90-77423c85be52'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '30ec45ae-2c8f-58fe-b42d-4ebc53005c5e'::uuid, NULL, E'The academic magazine was full of tips for both teachers and students.', NULL, NULL, NULL),
  ('81c35616-2d66-5401-ad71-3e461f098d99'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '81c35616-2d66-5401-ad71-3e461f098d99'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0c8472fc-7cc4-50fc-aa9c-7c10e970dea2'::uuid, NULL, E'The circulation desk is located on the ground floor.', NULL, NULL, NULL),
  ('81cfc3f7-9105-5a32-87d5-f1e9f6407c46'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '81cfc3f7-9105-5a32-87d5-f1e9f6407c46'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a meeting which all staff and employees must attend?', '74e27e7e-b437-546f-8db9-4e27f3151b17'::uuid, NULL, NULL, E'Plenary meeting', NULL, NULL),
  ('81d2a3d2-407a-5a61-9e0b-008423411600'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '81d2a3d2-407a-5a61-9e0b-008423411600'::uuid, 1, NULL, TRUE, 0, NULL, E'Bacteria', E'If you want to see evolution at work, visit a hospital. Inside a sick patient, antibiotics wipe out {{1}} bacteria by the millions. But germs are always {{3}} . A few adapt to resist the drug, so they survive—and spread. Such antibiotic-resistant bacteria infect two million Americans every year; they kill 23,000. In this arms race between medicine and evolution, evolution is winning.\nBut could we turn evolution against bacteria?\nIt turns out that when bacteria mutate to become resistant to one antibiotic, they often become more vulnerable to a {{4}} drug. So maybe after a jab with the left, a roundhouse to the right will deliver a {{6}} blow.\nTo test this idea, researchers in Denmark dosed batches of E. coli with 23 different antibiotics, and waited for resistance to evolve. In three quarters of the cases, the mutant germs became more {{7}} to a second drug.\nThe work appears in the journal Science Translational Medicine.\nOne particular combination of widely used antibiotics—gentamicin, then cefuroxime, then gentamicin again, and so on—looks like it could hold the bugs at bay indefinitely.', NULL, NULL, NULL, E'1.infectious, 2.mutating, 3.different, 4.knockout, 5.susceptible', NULL, NULL),
  ('81d5d763-43eb-5d0f-9bfb-1e7db7d28a76'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', '81d5d763-43eb-5d0f-9bfb-1e7db7d28a76'::uuid, 1, NULL, TRUE, 0, NULL, E'Xhosa Bride', E'A Xhosa bride in southern Africa, in contrast to her western counterpart, is expected to show both reluctance and sadness during her wedding - any signs of joy are considered inappropriate. She may even cry, and not without reason, because she is leaving her own family and relatives to live among a group of strangers where she will have to be careful of what she says and does.\nFor example, a new bride is not allowed to walk across the central meeting place in the middle of the kraal, or village, nor the cattle pen. And when she wishes to go from house to house, she must take the back way. To show respect for her husband''s senior relatives, she has to avoid using the names of senior male relatives or even words similar to them, which can lead to some complex paraphrases. Furthermore, she is not allowed to use the personal names of her mother-in-law, nor those of her husband''s aunts and elder sisters. Her first priority is the care of her husband, which means doing most of the heavy domestic work. Further constraints are having to wear a handkerchief low over her forehead, never showing her bare head to her husband''s relatives, not being allowed to drink milk from the homestead herd, and not touching the drinking utensils.\nHowever, these rules become less strict as time passes. The handkerchief is eventually removed, gifts are exchanged, and family relationships become a bit more relaxed. Finally, there is a ritual killing of a cow and the bride is allowed to drink the milk of the homestead. However, once she has done this, she can no longer drink the milk of her father''s house, symbolizing her final separation from her family.\n\nAccording to the text, which of the following behaviors are expected of a new Xhosa bride?', NULL, NULL, NULL, E'At her wedding she is meant to appear unwilling.\nShe must wear a head scarf when meeting her husband''s relatives.\nShe must avoid using the names of some of her husband''s female relatives.', NULL, NULL),
  ('81d6034a-0e89-54e0-93f4-7f195bacf6eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '81d6034a-0e89-54e0-93f4-7f195bacf6eb'::uuid, 1, NULL, TRUE, 0, NULL, E'Russia', E'Long isolated from Western Europe, Russia grew up without participating in the development like the Reformation that many Russians taking pride in their unique culture find dubious value. Russia is, as a result, the most unusual member of the European family, if indeed it is European at all. The question is still open to debate, particularly among Russians themselves.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('81d6fc85-74f7-5ee5-acc8-7e6fcc834efb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '81d6fc85-74f7-5ee5-acc8-7e6fcc834efb'::uuid, 1, NULL, TRUE, 0, NULL, E'Electric Vehicles', NULL, NULL, NULL, NULL, E'2, 3, 4, 1', NULL, NULL),
  ('81dc12da-4f09-5786-adc8-2285c0db7b3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '81dc12da-4f09-5786-adc8-2285c0db7b3c'::uuid, 1, NULL, TRUE, 0, NULL, E'Energy Challenge', NULL, '3c9e8130-2c3d-5832-8031-12f6c877a68a'::uuid, NULL, E'Most Americans take energy for granted. But, for many families, maintaining access to reliable and affordable energy is a persistent challenge and a significant material hardship. This is a problem referred to as energy insecurity, and it affects millions of American households each year. We have found that energy insecurity is a growing and vexing problem among low-income households, and the COVID-Nineteen pandemic has made this problem worse. Our analysis finds that there are disparities in rates of energy insecurity across various socio-demographic groups. Black and Hispanic households, for example, are significantly more likely to experience energy insecurity and face utility disconnection than white households. So too are households with young children, individuals that require electronic medical devices, and those in dwellings with inefficient or poor conditions. Households that cannot pay for energy are unable to power electronic learning or medical devices, keep perishable, healthy food in the refrigerator, or maintain safe body temperatures. Under conditions of extreme heat or cold, people can suffer from mental and physical health consequences, including the possibility of death. Strategies for coping with uncomfortable temperatures, such as burning trash or sitting in one''s car with the heat running, can lead to tragic outcomes as well. Our research underscores the importance of public policy that targets energy insecurity and its underlying causes. Weatherization assistance, incentives for residential solar power, energy bill assistance, and utility disconnection protections are all viable strategies for helping the millions of households across the country that are currently unable to pay their energy bills.', NULL, NULL, NULL),
  ('81dd25b4-6ab7-5a8e-b515-719d2aad22f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '81dd25b4-6ab7-5a8e-b515-719d2aad22f0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3913e2b8-15ca-5152-9463-789f453deec8'::uuid, NULL, E'He studies in particular the fishes of the Indian Ocean.', NULL, NULL, NULL),
  ('81dfc2a4-60f6-585b-93d3-6f7efc68f5c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '81dfc2a4-60f6-585b-93d3-6f7efc68f5c0'::uuid, 1, NULL, TRUE, 0, NULL, E'Stone Tools', E'Stone tools have been essential tools for human survival throughout history. These primitive implements, crafted from rocks and shaped by skilled hands, enabled early humans to hunt, gather, and build shelters. Stone tools served as a testament to our ancestors'' resourcefulness and adaptability in the face of challenges.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('81e366b3-9f77-597a-bdbe-c0283d18859d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '81e366b3-9f77-597a-bdbe-c0283d18859d'::uuid, 1, NULL, TRUE, 0, NULL, E'John Milton', E'John Milton wrote in a wide range of genres, in {{1}} languages, and on an extraordinary range of subjects. His was a more general {{2}} than is offered at Cambridge these days, and it continued after his seven years here, equipping him with the tools to write some of the most {{3}} literature ever seen, and to engage as a polemicist on many different social, political, and theological {{4}} .', NULL, NULL, NULL, E'1.several, 2.education, 3.groundbreaking, 4.questions', NULL, NULL),
