  ('82458b93-d016-5c65-8c32-365591501e70'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '82458b93-d016-5c65-8c32-365591501e70'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the time of day when light first appears?', 'd7051263-3ff2-5bcc-9986-a8dec9328e0f'::uuid, NULL, NULL, E'Dawn', NULL, NULL),
  ('8248110d-4249-5457-bc0d-74d938558a96'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8248110d-4249-5457-bc0d-74d938558a96'::uuid, 1, NULL, TRUE, 0, NULL, E'Course Introduction', NULL, 'adc827bd-ec42-5256-9d3c-1a960eb4fe78'::uuid, NULL, E'This course provides students with an in-depth understanding of the exciting disciplines of politics and international relations. Students will learn about the workings of political institutions in countries around the world and explore the complex field of relations between nations. Topics in governance, public policy,\npublic administration, national security and border control ensure that students receive a broad and current education in the range of issues which are covered under the label of politics and international relations. Students will undertake four compulsory units and two majors, one in politics and international relations and the other in governance and policy. They will also choose an elective major from a wide choice of options including political communication, international studies, international business and national security studies. In addition to acquiring specialist knowledge and competencies in Politics and International Relations and Commerce, students will graduate with a range of generic skills such as critical thinking, enhanced communication abilities, problem-solving and strong capacities to work with others. They will also develop ethically based and socially responsible attitudes and behaviors.', NULL, NULL, NULL),
  ('824c3158-e56b-51c3-abab-2689e8adc4ab'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '824c3158-e56b-51c3-abab-2689e8adc4ab'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '83a4622f-3a6d-5359-8243-668d0225a895'::uuid, NULL, E'The university''s career center provides resources for job searching and career development.', NULL, NULL, NULL),
