  ('8282aeeb-ba6f-5668-9b40-283604a4fd3a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '8282aeeb-ba6f-5668-9b40-283604a4fd3a'::uuid, 1, NULL, TRUE, 0, NULL, E'Electrons', E'The electrons that orbit closest to the nucleus are strongly {{1}} . They are called bound electrons. The electrons that are farther away from the pull of nucleus can be {{2}} out of their {{3}} . These are called free electrons. Free electrons can move from one atom to another. This {{4}} is known as electron flow. Electricity is the movement or flow of electrons from one atom to another.', NULL, NULL, NULL, E'1.attracted, 2.forced, 3.orbits, 4.phenomenon', NULL, NULL),
  ('8286cbb0-9465-5841-9f90-614e649f2d65'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8286cbb0-9465-5841-9f90-614e649f2d65'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the process of a caterpillar turning into a butterfly called?', 'ec1a4f99-6d86-57de-af8d-d3d290fe2431'::uuid, NULL, NULL, E'Metamorphosis', NULL, NULL),
