  ('828aab88-1aba-5f38-b364-cf95a9211ba8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '828aab88-1aba-5f38-b364-cf95a9211ba8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the act of a group of people wishing someone happiness or success by drinking wine?', '54916443-5c01-5ac5-88ab-887b3611217c'::uuid, NULL, NULL, E'Toast', NULL, NULL),
  ('8290b6cb-7d33-5695-855f-021981005f3e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8290b6cb-7d33-5695-855f-021981005f3e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bc1cdf46-d58b-5141-bca8-ff0aab863efa'::uuid, NULL, E'Electric cars are the future of transportation as they promise a cleaner environment.', NULL, NULL, NULL),
  ('82940da3-9f35-593b-a44f-7385413495ba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '82940da3-9f35-593b-a44f-7385413495ba'::uuid, 1, NULL, TRUE, 0, NULL, E'Nepalese Gharial', E'Which would you rather see: a rare Nepalese gharial or a common vole? Even without knowing what these animals are, you might be more intrigued by the gharial, simply because it is rare. This is the conclusion of research {{2}} in the journal Public Library of Science ONE.\nThe researchers say that labeling endangered animals as "rare," may harm the species, raising its value and so putting it at greater risk of being exploited within the illegal {{3}} , for either medicines or exotic zoos.\nScientists created a Web site where users could view images of either "rare" or "common" animals. When users clicked on one of the two options, up popped a progress bar showing the images in the process of downloading. But, {{5}} , the download took a {{6}} six minutes (although users did have the option to cancel). When the download finally completed, the images were designed not to show up!\nWell, significantly more users chose the rare {{7}} , waited for it to download and often tried again after it didn''t work. So, maybe to save the endangered gharial, we ought to just call it just a tired, ugly crocodile.', NULL, NULL, NULL, E'1.published, 2.pet-trade, 3.irritatingly, 4.whopping, 5.slideshow', NULL, NULL),
  ('8294c933-9e73-5b56-b80a-73238eba8ce8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '8294c933-9e73-5b56-b80a-73238eba8ce8'::uuid, 1, NULL, TRUE, 0, NULL, E'Zaha Hadid', E'Zaha Hadid was a revolutionary architect whose designs {{1}} out for their futuristic curves and brave forms. Before her untimely death in 2016, she {{2}} a permanent mark on the world of architecture, becoming the first woman to {{3}} the Pritzker Architecture Prize. Her works, from the London Aquatics Centre to the Guangzhou Opera House, are {{4}} for their innovation and dynamic sense of movement, challenging conventional architectural norms.', NULL, NULL, NULL, E'1.stand, 2.left, 3.win, 4.celebrated', NULL, NULL),
  ('82965b85-12ed-5460-964f-a006f6d4b2d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '82965b85-12ed-5460-964f-a006f6d4b2d5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a48e9c7c-1a1f-5398-ab0e-9cff002062b2'::uuid, NULL, NULL, E'The meeting was attended by all members of this study team.', NULL, NULL),
  ('82976a04-8319-5039-939f-34b67f16a75a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '82976a04-8319-5039-939f-34b67f16a75a'::uuid, 1, NULL, TRUE, 0, NULL, E'Pig Kidney Transplantation', E'Surgeons in New York City successfully attached a pig kidney to a human patient and watched the pinkish organ function normally for 54 hours. Such procedures have been done in nonhuman primates. However, this is the first time that a pig kidney has been transplanted to a human body and not been immediately rejected.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('82a00ef8-fbda-58d2-a780-19ad8c182bd0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '82a00ef8-fbda-58d2-a780-19ad8c182bd0'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '10e717af-15f3-5d89-b6bb-839a74f13f61'::uuid, NULL, NULL, E'Time is needed to complete the lecture.', NULL, NULL),
  ('82a35fc9-41a7-5f41-aa51-601d5230837b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '82a35fc9-41a7-5f41-aa51-601d5230837b'::uuid, 1, NULL, TRUE, 0, NULL, E'Selective Books(认真挑选的书籍)', NULL, NULL, NULL, NULL, E'4, 3, 2, 1', NULL, NULL),
  ('82acc10f-2bfb-54ee-aeb6-e61c82c24df0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '82acc10f-2bfb-54ee-aeb6-e61c82c24df0'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What emergency service is called at sea?', '3152c9c7-4b1d-544d-92ec-89225fc8eeba'::uuid, NULL, NULL, E'Coastguard', NULL, NULL),
  ('82ad1569-c681-5788-9f45-4936641eaff0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', '82ad1569-c681-5788-9f45-4936641eaff0'::uuid, 1, NULL, TRUE, 0, NULL, E'Amazon Protection', E'Using laws governing human rights may be the best way of harnessing international legislation and tribunals to protect the Amazon, a new study shows.\nSafeguarding the rainforest is a critical priority because of the ecosystem''s planetary importance. Recent increases in deforestation and fires in the region have made this even more urgent.\nThe new research, published in the Review of European, Comparative and International Environmental Law (RECIEL), says using human rights law to protect the Amazon is more likely to have stronger prospects, as campaigners wouldn''t need to submit information about more than one nation for it to be upheld. Courts would only need to judge that environmental damage violated the rights of either certain individuals or tribal and indigenous peoples.\nThe experts behind the study hope it will be used as a comprehensive guide for those working to protect the Amazon. It assesses the potential for litigation in international courts and tribunals, examining the possible claims, the risks associated with each of these and which are more likely to be successful.\nThe protection of the Amazon poses particular challenges for international law because global ways of protecting the environment exist alongside the territorial jurisdiction of the Amazon nations, which have permanent sovereignty over natural resources.\nThe hurdles in jurisdiction and evidence often prevent a clear-cut judgment and Amazon states from being compelled to take the urgent and direct measures needed to bring the ecosystem back from the brink.\n\nAccording to the passage, which of the following statements about the Amazon protection is true?', NULL, NULL, NULL, E'The best way to protect the Amazon is to use laws governing human rights and probably international legislation.\nUsing human rights law to protect the Amazon is more likely to prove promising.\nThe increase in regional deforestation and fires has made the protection more urgent.', NULL, NULL),
  ('82b51d7f-46e4-5965-9085-6ae27d068a0b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '82b51d7f-46e4-5965-9085-6ae27d068a0b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call water in its solid state?', '6f62a4a9-ca0c-57db-9f0f-fbeedcee4af0'::uuid, NULL, NULL, E'Ice', NULL, NULL),
