  ('82ce9e65-30d8-5786-ae89-3a3dce75b11e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '82ce9e65-30d8-5786-ae89-3a3dce75b11e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the fruit that''s similar to a peach but with smooth skin?', '46163383-4852-5392-91cd-42f5d32cdb70'::uuid, NULL, NULL, E'Nectarine', NULL, NULL),
  ('82d2d198-c8a3-59c0-9512-41cebf20c997'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '82d2d198-c8a3-59c0-9512-41cebf20c997'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call a place where tennis is played?', '760a2db2-254c-5247-ad0a-dc320a2719d4'::uuid, NULL, NULL, E'Tennis court', NULL, NULL),
  ('82d9b1e6-d40a-5ac0-9edf-6d2c1e6d6456'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '82d9b1e6-d40a-5ac0-9edf-6d2c1e6d6456'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person who repairs cars?', '5d9a4b92-ea9f-5e20-9b4b-59aef8d917df'::uuid, NULL, NULL, E'Auto technician / mechanic', NULL, NULL),
  ('82e23f53-94d9-55f9-9e74-7b8fbadcc1e2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '82e23f53-94d9-55f9-9e74-7b8fbadcc1e2'::uuid, 1, NULL, TRUE, 0, NULL, E'Pain', NULL, 'bca30ef9-6721-5b7e-9391-2a335e839d8b'::uuid, NULL, E'Say you’re at the beach, and you get sand in your eyes. How do you know the sand is there? You obviously can’t see it, but if you are a normal, healthy human, you can feel it, that sensation of extreme discomfort, also known as pain. Now, pain makes you do something, in this case, rinse your eyes until the sand is gone. And how do you know the sand is gone? Exactly because there’s no more pain. There are people who don’t feel pain. Now, that might sound cool, but it’s not. If you can’t feel pain, you could get hurt, or even hurt yourself and never know it. Pain is your body’s early warning system. It protects you from the world around you, and from yourself. As we grow, we install pain detectors in most areas of our body. These detectors are specialized nerve cells called nociceptors that stretch from your spinal cord to your skin, your muscles, your joints, your teeth and some of your internal organs. Just like all nerve cells, they conduct electrical signals, sending information from wherever they’re located back to your brain. But, unlike other nerve cells, nociceptors only fire if something happens that could cause or is causing damage. So, gently touch the tip of a needle. You’ll feel the metal, and those are your regular nerve cells. But you won’t feel any pain. Now, the harder you push against the needle, the closer you get to the nociceptor threshold. Push hard enough, and you’ll cross that threshold and the nociceptors fire, telling your body to stop doing whatever you’re doing.', NULL, NULL, NULL),
  ('82e92b8c-0fb4-58e2-8c22-c680d2786169'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '82e92b8c-0fb4-58e2-8c22-c680d2786169'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ca420448-9ce1-5bf2-afa3-c6ce4aef90d5'::uuid, NULL, E'Fatigue is a factor in a significant proportion of road accidents.', NULL, NULL, NULL),
  ('82eff5ed-382c-5ffd-87c7-edf4753b9703'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '82eff5ed-382c-5ffd-87c7-edf4753b9703'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '74f9d25c-3616-58ab-9d4c-9f97215e2ede'::uuid, NULL, NULL, E'Social media is responsible for helping the government to solve social problems.', NULL, NULL),
  ('82f7d06c-c4b9-56db-b9d0-557597476718'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '82f7d06c-c4b9-56db-b9d0-557597476718'::uuid, 1, NULL, TRUE, 0, NULL, E'Actors'' Performance', NULL, NULL, NULL, NULL, E'3, 4, 1, 2', NULL, NULL),
  ('82fbb08f-5f4e-533e-a3f7-bffb97a56568'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '82fbb08f-5f4e-533e-a3f7-bffb97a56568'::uuid, 1, NULL, TRUE, 0, NULL, E'UK Universities', E'The research, commissioned by HEDQF, asked 1,000 students from UK universities for their views on the quality of their university campus and sheds new light on how students make decisions as they go through the application process. When asked what the most important factors were when deciding where to study, 76% of students {{1}} campus facilities as either ''quite'' or ''very'' important, with only 8% saying it was ''not very'' or ''not at all'' important in their choice. This was the fourth most important factor after course, location and reputation. Estate quality increases in importance once a student has chosen a university, with 86% of students saying that it is ''quite'' or ''very'' important in their first year of studies. However, the importance students {{2}} to estates decreases to 79% for third years students. The research also highlighted how factors such as demographics, region and type of university {{3}} have an impact on how students view the university buildings. Students in Russell Group universities are much more likely to describe their buildings as ''inspiring'', closely followed by students in newer universities such as Lincoln, Gloucestershire and Ravensbourne College. This pattern was repeated when students were asked to rate the overall quality and design of estate, with Russell Group students, and students from newer universities, more likely to rate the estates as excellent. {{4}} data shows capital expenditure on estates has been the highest amongst the Russell Group universities during 2001-2011. When asked where they would invest money in their universities, the top three areas in order of {{5}} were: smaller class sizes, bursaries for poorer students and new buildings and facilities. When their expenditure options were restricted to estates-only items, the repair and {{6}} of existing buildings came out top with 77%, which suggests that new buildings should not be at the {{7}} of the rest of the estate, and may even highlight the deficiencies of tired and outmoded facilities.', NULL, NULL, NULL, E'1.ranked, 2.attach, 3.attended, 4.Existing, 5.preference, 6.maintenance, 7.expense', NULL, NULL),
  ('82fe9ef7-076e-5b5a-abed-a87ed3ae5e41'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '82fe9ef7-076e-5b5a-abed-a87ed3ae5e41'::uuid, 1, NULL, TRUE, 0, NULL, E'Kennedy', E'John F. Kennedy had a high academic degree and was handsome, with a Hollywood-style appearance. He was the most popular politician partly because of his heroism in the war. He was awarded a medal in the war to {{1}} his personal {{2}} , and these qualities—along with his charisma—made him admired by the public. Because of these three characteristics, he became {{3}} in people’s eyes. He was also blessed {{4}} handsome looks, a {{5}} political style, and a beautiful wife. All of this helped him prepare in advance for his reelection campaign.', NULL, NULL, NULL, E'1.prove, 2.passion, 3.iconic, 4.with, 5.mending', NULL, NULL),
  ('830126c8-63c7-5ff9-a149-dac724a461ce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', '830126c8-63c7-5ff9-a149-dac724a461ce'::uuid, 1, NULL, TRUE, 0, NULL, E'Great Conversation', E'What are the essential elements that make a conversation truly a great conversation? And humility would be one basic design principle that we should all start from. The kind of humility I’m talking about is the kind that you can’t set aside. Because the world is an incredibly complicated place. None of us can ever have the full lock on truth. We can only see the world from a particular vantage point. And that means that our knowledge is going to be going to have special insight because of our vantage point but it’s also going to be limited because of our vantage point. And so that sort of like limited knowledge that we can have about the world means that we must enter into any conversation with a deep sense of...\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '1559b58b-32bb-599e-a4b7-0759fead79ab'::uuid, NULL, NULL, E'humility', NULL, NULL),
  ('8304e104-594c-59eb-9cf3-29dddd9cb6da'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '8304e104-594c-59eb-9cf3-29dddd9cb6da'::uuid, 1, NULL, TRUE, 0, NULL, E'Security Footage', E'The introduction of security footage in courtrooms as evidence is increasingly common. With the number of closed-circuit television (CCTV) cameras rising, the likelihood of images deemed relevant for criminal proceedings being recorded also increases.\nHowever, while CCTV footage may arguably have assisted in achieving {{1}} in some high-profile cases, can it assist in the overall reduction of violence against women?\nA well-known example in Australia of CCTV helping solve a crime is the footage pulled from a shop on Sydney Road the night Jill Meagher was raped and murdered by Adrian Bayley. This footage was mentioned in his sentencing in 2013.\nIn the same year, Simon Gittany was found {{2}} of the murder of his partner Lisa Harnum. CCTV footage – taken from his own security cameras – was again {{3}} as key evidence.\nBeyond the courtroom, news media reports of crime are saturated with the use of CCTV footage. In both contexts, it is often seen to be {{4}} – an authoritative and objective witness that can tell us “what really happened”.\nWhile used in a range of offenses, its inclusion in instances of extreme (and public) violence against women can mean certain images receive significant and sustained media {{5}} , and may remain online indefinitely.\nThe strength of CCTV in our public consciousness is such that questions of privacy are often dismissed as inconsequential. CCTV installed in the homes of family violence victims has even been considered.', NULL, NULL, NULL, E'1.convictions, 2.guilty, 3.interpreted, 4.decisive, 5.attention', NULL, NULL),
  ('830a7fad-eb50-5136-93fc-7ab2dd46399c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '830a7fad-eb50-5136-93fc-7ab2dd46399c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '113f30bb-21c2-5142-afed-c00254c79d12'::uuid, NULL, E'We heard the argument against it from several perspectives.', NULL, NULL, NULL),
