  ('83356378-0cba-5207-b32e-e27923dc476f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '83356378-0cba-5207-b32e-e27923dc476f'::uuid, 1, NULL, TRUE, 0, NULL, E'Pandemic', E'The COVID-19 pandemic accelerated the shift to remote work, transforming work culture. While it offers flexibility and the chance to {{1}} down on commuting-related emissions, concerns about burnout and maintaining work-life balance {{2}} . Companies are now exploring hybrid models to combine the best of both {{3}} .', NULL, NULL, NULL, E'1.cut, 2.persist, 3.worlds', NULL, NULL),
