  ('83e06e2d-b186-5800-8a2d-ff5199886a0b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '83e06e2d-b186-5800-8a2d-ff5199886a0b'::uuid, 1, NULL, TRUE, 0, NULL, E'Deaths of Despair', E'People who attended religious services at least once a week were significantly less likely to die from ''deaths of despair'', including deaths related to suicide, drug overdose, and alcohol poisoning, according to new research.', NULL, NULL, NULL, NULL, NULL, NULL),
