  ('83eae48e-497c-55da-b570-9507e568c2b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '83eae48e-497c-55da-b570-9507e568c2b9'::uuid, 1, NULL, TRUE, 0, NULL, E'Language Acquisition', E'Modern linguistics {{1}} light on the paradoxical nature of language acquisition. Renowned researchers contend that the critical period for language learning is not {{2}} to early childhood, as traditionally believed. Instead, evidence suggests that language skills can be significantly honed well into adulthood, {{3}} that the methods of instruction align with the nuanced cognitive frameworks of mature learners. This insight has profound implications for second-language education and {{4}} for a more flexible and age-inclusive approach.', NULL, NULL, NULL, E'1.sheds, 2.confined, 3.provided, 4.advocates', NULL, NULL),
  ('83ec5e66-d466-5197-80f3-0f6dfa7b6113'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '83ec5e66-d466-5197-80f3-0f6dfa7b6113'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which word is connected with a type of class at a university, session or seminar?', '2e1854f1-5b8f-5897-b2b1-cf457e544484'::uuid, NULL, NULL, E'Seminar', NULL, NULL),
  ('83f78ed4-01d0-5b37-b04f-0c2ffa99ff50'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '83f78ed4-01d0-5b37-b04f-0c2ffa99ff50'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What object has three legs and can support a camera?', '34e454a5-cc5f-55ea-b5ae-53cfa73cd306'::uuid, NULL, NULL, E'Tripod', NULL, NULL),
  ('83f8e1d1-ac45-5672-858b-585486bc0b49'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '83f8e1d1-ac45-5672-858b-585486bc0b49'::uuid, 1, NULL, TRUE, 0, NULL, E'Locomotion', E'Locomotion underpins a limitless array of animal behaviors and can be a rich source of inspiration for the design of modern machines. Movement requires mechanical interaction with the physical environment to monitor and control musculoskeletal systems that may be complex with many degrees of freedom. Recent advances in robotics have proven to be powerful in broadening our understanding of how animals run in a controlled manner.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('83fd5b7f-6aaa-590c-bb33-2eb7594e7239'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '83fd5b7f-6aaa-590c-bb33-2eb7594e7239'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '65273e09-05da-5e1f-89d8-81312af59925'::uuid, NULL, E'It was decided by a unanimous vote that this school should be closed.', NULL, NULL, NULL),
  ('84071f0b-0ed9-5a99-9b8a-ae41cb4a3ec0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '84071f0b-0ed9-5a99-9b8a-ae41cb4a3ec0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'cdc43937-56f9-5a94-8dec-0e2c4e2ec3e2'::uuid, NULL, E'The lecture theater one is located on the ground floor of the Pack Building.', NULL, NULL, NULL),
  ('84093e9b-8cdd-5bf4-a4b1-b54559458672'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', '84093e9b-8cdd-5bf4-a4b1-b54559458672'::uuid, 1, NULL, TRUE, 0, NULL, E'MCM-R', E'There is increasing evidence that the impacts of meteorites have had important effects on Earth, particularly in the field of biological evolution. Such impacts continue to pose a natural hazard to life on Earth. Twice in the twentieth century, large meteorite objects are known to have collided with Earth. If an impact is large enough, it can disturb the environment of the entire Earth and cause an ecological catastrophe. The best-documented such impact took place 65 million years ago at the end of the Cretaceous period of geological history. This break in Earth''s history is marked by a mass extinction, when as many as half the species on the planet became extinct. While there are a dozen or more mass extinctions in the geological record, the Cretaceous mass extinction has always intrigued paleontologists because it marks the end of the age of the dinosaurs. For tens of millions of years, those great creatures had flourished. Then, suddenly, they disappeared.\n\nIn the paragraph, why does the author include the information that dinosaurs had flourished for tens of millions of years and then suddenly disappeared?', NULL, NULL, NULL, E'To explain why paleontologists have always been intrigued by the mass extinction at the end of the Cretaceous\nTo provide evidence that an impact can be large enough to disturb the environment of the entire planet and cause an ecological disaster', NULL, NULL),
  ('840fd1ee-e141-5c0e-93ec-82d526bc64bf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '840fd1ee-e141-5c0e-93ec-82d526bc64bf'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call a seat with legs but with nothing to support your arms or back?', 'abef0ec5-93ae-5c06-b2fa-f1d048cfe305'::uuid, NULL, NULL, E'Stool', NULL, NULL),
  ('841fb134-f265-551e-875d-fb32859c26ae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '841fb134-f265-551e-875d-fb32859c26ae'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7a5fafdc-c065-5ce7-8bf6-bbc96e5b398c'::uuid, NULL, E'The company has been performing poorly over the past six years.', NULL, NULL, NULL),
  ('84306379-6e03-5ab2-b75b-e730b5f0dd4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '84306379-6e03-5ab2-b75b-e730b5f0dd4b'::uuid, 1, NULL, TRUE, 0, NULL, E'Bad Habits', E'It is very easy to acquire bad habits, such as eating too many sweets or too much food, or drinking too much fluid of any kind, or smoking, etc.. The more we do a thing, the more we tend to like doing it. In later stage, if we do not continue to do it, we feel unhappy. This is called the ''force of habit'' and the force of habit should be fought against.', NULL, NULL, NULL, NULL, NULL, NULL),
