  ('843ddd23-1a33-5d16-88e5-32b7d4a29db4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', '843ddd23-1a33-5d16-88e5-32b7d4a29db4'::uuid, 1, NULL, TRUE, 0, NULL, E'Surfing', E'Surfing has been a central part of Hawaiian culture for hundreds of years. But surfing wasn''t just a pastime for the Hawaiians in ancient times. It served as a kind of training exercise meant to keep chiefs in top physical condition. Chiefs demonstrated their mastery by their skill in the surf, and commoners gained popularity by the way they handled themselves in the ocean. As well as this, surfing served as a system for conflict resolution. Young males would test their surfing skills in fierce competitions, during which wealth, pride, and even romance ...\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '49b8e159-f9c7-528f-a996-e105ad879675'::uuid, NULL, NULL, E'were at stake', NULL, NULL),
