  ('84642390-97a5-586d-bf42-e0724082c28e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '84642390-97a5-586d-bf42-e0724082c28e'::uuid, 1, NULL, TRUE, 0, NULL, E'ARENA', E'The Australian Renewable Energy Agency (ARENA) has awarded $2.49 million to cover a {{1}} of the cost of a collaborative project led by the Australian Maritime College at the University of Tasmania, in {{2}} with The University of Queensland and CSIRO. The $5.85 million ''Tidal Energy in Australia _ Assessing Resource and Feasibility to Australia''s Future Energy Mix'' project will map the country''s tidal energy in {{3}} detail before assessing its ability to contribute to Australia''s energy needs.', NULL, NULL, NULL, E'1.portion, 2.partnership, 3.unprecedented', NULL, NULL),
  ('846885d7-7fc6-5a99-a400-088c00f1df2e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '846885d7-7fc6-5a99-a400-088c00f1df2e'::uuid, 1, NULL, TRUE, 0, NULL, E'Migraine', E'A throbbing, pounding headache. Bright zigzagging lines across your field of vision. Sensitivity to light, lingering fatigue, disrupted sleep. A migraine can include any of these symptoms. While an incapacitating headache is one of the most common experiences of migraine, the word “headache” doesn’t really capture the wide array of experiences a migraine can entail. No two are alike, and some don’t even involve a headache.\n\nWhat does the speaker say about the symptoms of migraine?', 'd681ee2d-024e-5d38-8aa8-9b58313b5f47'::uuid, NULL, NULL, E'Migraine may include a variety of symptoms.', NULL, NULL),
  ('846a44cb-ad38-571c-bfbd-40cb01aea0f7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '846a44cb-ad38-571c-bfbd-40cb01aea0f7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1f6ed9c9-5e1f-5bce-896a-58dd809d0c77'::uuid, NULL, NULL, E'The university auditorium is around the corner.', NULL, NULL),
  ('846de411-ed9c-5bc0-9217-ea3d82032f38'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '846de411-ed9c-5bc0-9217-ea3d82032f38'::uuid, 1, NULL, TRUE, 0, NULL, E'Ethical Considerations', E'To what extent do you think that ethical considerations should guide scientific research?', NULL, NULL, E'Ethical considerations should serve as the cornerstone of scientific research, guiding researchers in upholding principles of safety, integrity, and social responsibility. Ethical standards must be prioritized to ensure the credibility and impact of scientific endeavors.\nEthical guidelines play a vital role in safeguarding the well-being of research participants and maintaining transparency in research practices. By adhering to ethical standards, researchers prioritize the protection of participants from harm or exploitation, ensuring that studies are conducted ethically and with due regard for the rights and dignity of individuals involved. Transparency in research processes, guided by ethical principles, promotes accountability and trust in the scientific community, enhancing the credibility and reliability of research outcomes.\nFurthermore, ethical considerations promote integrity in scientific research by emphasizing honesty, accuracy, and accountability in all stages of the research process. Upholding ethical standards fosters a culture of integrity within the scientific community, where researchers are committed to conducting studies with honesty and rigor.\nIn conclusion, ethical considerations are essential in guiding scientific research towards responsible and impactful outcomes. By prioritizing the protection of participants, promoting transparency and integrity, and emphasizing the social impact of research, ethical standards uphold the values of safety, credibility, and social responsibility in scientific endeavors. Embracing ethical guidelines not only enhances the quality and reliability of research but also reinforces the public''s trust in science, paving the way for advancements that benefit society as a whole.', NULL, 200, 300),
  ('84726425-eea2-5225-b4de-40bc6d8d5908'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '84726425-eea2-5225-b4de-40bc6d8d5908'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '32f7aed0-bfa7-5a2e-848c-9fcb9a08ec49'::uuid, NULL, NULL, E'It is clear that the human population impacts the environment.', NULL, NULL),
  ('84727405-cb9f-5644-b340-079125e66e08'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '84727405-cb9f-5644-b340-079125e66e08'::uuid, 1, NULL, TRUE, 0, NULL, E'Disordered Eating', E'The most significant difference between an eating disorder and disordered eating is whether or not a person''s symptoms and experiences align with the criteria defined by the American Psychiatric Association. The term "disordered eating" is a descriptive phrase, not a diagnosis.', NULL, NULL, NULL, NULL, NULL, NULL),
