  ('8534f4a8-e1ef-561e-b32b-fb0332a9db5b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '8534f4a8-e1ef-561e-b32b-fb0332a9db5b'::uuid, 1, NULL, TRUE, 0, NULL, E'Toys', E'Three types of phthalates, {{1}} additives that render hard plastics flexible, will be banned from children''s toys and child-care products starting Feb 10, while three other types of phthalates will be temporarily {{2}} from child-care products and toys that can be placed in a child''s mouth. Consumer {{3}} complain that the law has ended up sanctioning a grace period that allows toy makers to sell off soon-to-be banned toys, rather than forcing them to {{4}} of them.', NULL, NULL, NULL, E'1.chemical, 2.prohibited, 3.advocates, 4.dispose', NULL, NULL),
  ('854416ea-f5ee-55e3-956d-19f7eb582166'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '854416ea-f5ee-55e3-956d-19f7eb582166'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd5898ccb-a9f9-5b13-a491-95c361c5fce9'::uuid, NULL, E'He had worked in the theater for many years, starting at the bottom.', NULL, NULL, NULL),
  ('8546f975-7967-573b-b383-77c16e1cf1c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8546f975-7967-573b-b383-77c16e1cf1c8'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0bd0e7c1-8ad2-5ab3-a0f9-d52512717456'::uuid, NULL, E'It''s difficult for us to control our feelings of disgust.', NULL, NULL, NULL),
  ('854e889d-cd92-5707-bab6-3b532dfbe88c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '854e889d-cd92-5707-bab6-3b532dfbe88c'::uuid, 1, NULL, TRUE, 0, NULL, E'Movies', E'Movies are an integral part of us; they mirror what we believe and how we coexist as people. It is easier to see our concerns, attitudes, flaws and strengths in films than it is to decipher them from our daily interactions. When our prevalent beliefs and ideologies are challenged in films, we are sometimes able to interrogate ourselves and embrace change.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('854f0251-2e05-5a46-a19d-37bc9752d709'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '854f0251-2e05-5a46-a19d-37bc9752d709'::uuid, 1, NULL, TRUE, 0, NULL, E'Artists', E'In the US, artists in the mid-1950s began to create a {{1}} to Pop. Strongly influenced by Dada and its {{2}} on appropriation and everyday objects, artists increasingly worked with {{3}} , consumer products, and a healthy dose of irony. Jasper Johns {{4}} iconic imagery like the American flag; Robert Rauschenberg employed silk-screen printings and found objects; and Larry Rivers used images of mass-produced goods. All three are considered American {{5}} of Pop.', NULL, NULL, NULL, E'1.bridge, 2.emphasis, 3.collage, 4.reimagined, 5.forerunners', NULL, NULL),
  ('85516457-50e2-5b21-a63f-4e299f45b7fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '85516457-50e2-5b21-a63f-4e299f45b7fd'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the fear of heights?', 'a1f5e355-62b3-5109-a0fe-8de537839272'::uuid, NULL, NULL, E'Acrophobia', NULL, NULL),
  ('855465df-b4c5-5692-b74b-f07294364be8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '855465df-b4c5-5692-b74b-f07294364be8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the Spanish tradition of a midday rest or nap, especially common in hot climates?', '68565cd5-5532-56e5-9ac8-2fce02e69069'::uuid, NULL, NULL, E'Siesta', NULL, NULL),
  ('8554fa46-93ae-5f88-9cab-52fe5b0e9849'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8554fa46-93ae-5f88-9cab-52fe5b0e9849'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8b48ae8e-ef94-566b-8207-ffd1f3e06271'::uuid, NULL, E'I still don''t understand the last sentence.', NULL, NULL, NULL),
  ('85570db4-87e9-540e-8d42-c7b986b99103'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '85570db4-87e9-540e-8d42-c7b986b99103'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a655f8a7-6351-5eca-9b31-f849ced83332'::uuid, NULL, NULL, E'The two sides have disagreed on how to solve the problem.', NULL, NULL),
  ('8559ee13-b243-515d-bb7e-ab430999af0d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8559ee13-b243-515d-bb7e-ab430999af0d'::uuid, 1, NULL, TRUE, 0, NULL, E'Umbrella', E'You''ve just arrived at the office and realized that it''s pouring outside. You didn''t bring an umbrella and know that one of your colleagues, who sits near you, often has a spare umbrella. How do you approach your colleague to ask for an umbrella, and what specific points do you include to ensure a positive response?', '2f9fb1ad-8460-5e40-b53d-bbe3e1a7c401'::uuid, NULL, E'Hey colleague, I want to talk to you about something.\nWe seem to have a little issue with going out after work.\nIt''s like it’s pouring rain outside right now, and I didn’t bring an umbrella. I know you usually keep a spare umbrella, so could I borrow yours temporarily? I will return it to you as soon as possible.\nAnd I''d like to know what you think.', NULL, NULL, NULL),
  ('855efeb6-2efa-5599-a373-50e370056894'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '855efeb6-2efa-5599-a373-50e370056894'::uuid, 1, NULL, TRUE, 0, NULL, E'Digital Medicine', NULL, '91504ffe-1051-5912-8290-5f394aec8ec4'::uuid, NULL, E'The doctor-patient relationship is a founding principle of healthcare and medicine. The first step is to eliminate keyboards and computer screens and clinical encounters. Some doctors in the West can spend up to twice as many hours on medical paperwork than with their patients. In the years ahead, we should be able to eliminate the data clerk functions of clinician. These are mutually hated as much by patients as by doctors and clinician. AI tools such as speech recognition technology that are now commonplace in homes could be used in clinical settings for capturing data and notes, allowing doctors to concentrate on people. We have a problem with accuracy and efficiency. Trained on a huge resource of medical data, the power of AI learning can read some images more accurately than humans. Whether it’s a pattern like a scan or a slide, or a prediction, AI can really rev up the accuracy. And that is important for a better diagnosis, better treatments, better outcomes, lower cost. Powerful machines can interpret scans 150 times faster than radiologists, and can work 24 hours a day. AI can even suggest a diagnosis. Many conditions could be AI-diagnosed. And so the time that a doctor comes into play is very specific to important diagnoses.', NULL, NULL, NULL),
  ('85663824-46c8-5f37-bc0d-1b1810fb95dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '85663824-46c8-5f37-bc0d-1b1810fb95dd'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'eb9983df-f44f-5bbf-8d2b-eb0419e68819'::uuid, NULL, E'Marketing involves various activities, such as research, product development, and promotion strategies.', NULL, NULL, NULL),
  ('8567dc68-da89-56e2-84a4-6bb11de280aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8567dc68-da89-56e2-84a4-6bb11de280aa'::uuid, 1, NULL, TRUE, 0, NULL, E'Academics and Extracurriculars', E'While extracurricular activities can be enriching, it is important to balance them with academic responsibilities. Students should prioritize their coursework and ensure that they have enough time to study and complete assignments. Effective time management skills are crucial for balancing academics and extracurriculars successfully.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('856b1a21-ce3f-59b7-8369-d6668ffa268f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '856b1a21-ce3f-59b7-8369-d6668ffa268f'::uuid, 1, NULL, TRUE, 0, NULL, E'Radiation', NULL, '8c128637-d5e1-541d-8bf7-1d559d497cde'::uuid, NULL, E'Radiation is a word that makes people very nervous. But, to radiate just means, “giving off”. Like when the radiator in your house gives off heat in the form of infrared radiation. Different parts of the electromagnetic spectrum correspond to different types of radiation. And, many of them are perfectly harmless. Some of them can be dangerous though. Radiation with very short wavelengths like UV Light, X-Rays, and Gamma Rays are strong enough to rip electrons out of their atoms, which can cause burns and genetic damage. This is what many people have in mind when they hear the term “radiation”. The rest of the spectrum covers a large range of longer waves from Visible Light, Infrared, Microwaves to Radio Waves. This is the kind of radiation that’s emitted by all sorts of human technology: mobile phones, Wi-Fi routers, electric power lines, and household appliances. This radiation doesn’t disrupt molecules in our body. However, some kinds of radiation can stimulate muscles and nerves and can also make the hair on your body vibrate, which can sometimes cause a tingly feeling above certain threshold values. Other kinds are useful for making dinner. Microwaves push the water molecules in your food around which warms it up. This happens to us all the time. For example, the pleasant warmth you feel at the beach is your skin heating up from exposure to electromagnetic infrared radiation from the sun. We are surrounded by natural, and generally harmless sources of electromagnetic radiation all the time and always have been.', NULL, NULL, NULL),
  ('856b5997-4be4-5ef0-9104-7379f1b5f79c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '856b5997-4be4-5ef0-9104-7379f1b5f79c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a statement presented in court by a defendant or a lawyer?', '43edde17-25cc-5685-abf2-774021793b4d'::uuid, NULL, NULL, E'Plea', NULL, NULL),
