  ('85f39837-29e6-5d2c-a5f8-8783176e18d2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '85f39837-29e6-5d2c-a5f8-8783176e18d2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '86a96341-75d9-5670-9c17-c89e5fe71de6'::uuid, NULL, NULL, E'The teaching group will perform in the concert hall.', NULL, NULL),
  ('85f61bd4-a277-5d67-b766-92da68658d58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '85f61bd4-a277-5d67-b766-92da68658d58'::uuid, 1, NULL, TRUE, 0, NULL, E'Social Networks', E'Ten years ago, Barsky and Purdon (2006) discovered that social networks which are expanding communication through social media are becoming popular and the costs involved are getting further reduced. Yet, library executives did not see how such a phenomenon could become a part of library and information services. They felt that the users should be left to their social media while the library carried on with its traditional roles (De Rosa et al., 2007). This was also the case when Charnigo and Barnett-Ellis (2007) conducted a survey of 126 academic librarians and concluded that 54% of the librarians surveyed did not believe that there was an academic purpose for Facebook. The rationale behind these librarians’ belief was that the social media was a space where students interact with each other. Hence, the librarian was not welcome as their coming in might be viewed as an invasion of space. But time has proved that as the technology of the social media became more popular, users and librarians acquired digitally literacy, and libraries, seeing an explosion of social media around it, were forced to reconsider their stance. In a survey involving 497 international librarians, Taylor & Francis (2014) discovered that over 70% of librarians now feel that the use of social media is important. Though the wave began with public libraries (Mon, 2015), today, libraries of every type either have a social media presence or they are seriously considering it. Hence, the use of social media by libraries has become mainstream.', NULL, NULL, E'Social networks are becoming popular and the costs involved are getting further reduced, but library executives didn''t see how such a phenomenon could become a part of library and information services, although however, over 70% of librarians now feel that the use of social media is important, and libraries of every type either have a social media presence or they are seriously considering it, so the use of social media by libraries has become mainstream.', NULL, 5, 75),
  ('85f81581-c5e4-57b7-8f2b-cfed9c056254'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '85f81581-c5e4-57b7-8f2b-cfed9c056254'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What does the earth revolve around?', 'bf1fc64e-1230-5309-aff4-c4d91360235d'::uuid, NULL, NULL, E'Sun', NULL, NULL),
