  ('8637520f-fc59-573c-bf4f-a5b74070f7f1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8637520f-fc59-573c-bf4f-a5b74070f7f1'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5682a3ab-66ac-5498-a09c-ef7f49de4d84'::uuid, NULL, NULL, E'The use of dictionaries is not allowed during the examination.', NULL, NULL),
  ('8638a59c-be92-502e-9622-7adc740c7cf3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8638a59c-be92-502e-9622-7adc740c7cf3'::uuid, 1, NULL, TRUE, 0, NULL, E'Cancer', E'Cancer is most treatable when caught early. But despite the vast resources aimed at finding ways to detect the disease in its initial stages, many people who qualify for existing screenings still do not receive them. Some are unfamiliar with the constantly evolving guidelines on when and where to get tested. Others have never been informed that they need exams in the first place.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('8639c6f2-a654-5119-a4fe-ffb17205d01b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '8639c6f2-a654-5119-a4fe-ffb17205d01b'::uuid, 1, NULL, TRUE, 0, NULL, E'Heart Attack', E'A team of researchers has created an AI that assesses the risk of you having a heart attack in the next 10 years, just by looking once at your chest X-ray. Heart disorders that {{1}} from reduced or blocked blood flow in arteries due to the accumulation of cholesterol and fat in them are called atherosclerotic cardiovascular diseases (ASCVSD). It is one of the major causes of stroke in heart patients. The team’s deep learning model offers a potential solution for population-based opportunistic screening of cardiovascular disease risk using existing chest X-ray images. Generally, if a doctor wants to predict the risk of heart attack for a patient, they {{2}} a statistical model that calculates the ASCVD risk score, which involves evaluating cardiac health on the basis of factors like systolic blood pressure, age, hypertension and so on. However, since it may not always be possible to have {{3}} to all these records, the researchers consider X-rays to be an ideal singular parameter for calculating heart attack risk.', NULL, NULL, NULL, E'1.originate, 2.employ, 3.access', NULL, NULL),
  ('863e4ba4-901a-5cd6-a440-661eb02f6828'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '863e4ba4-901a-5cd6-a440-661eb02f6828'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for a large, naturally occurring community of flora and fauna occupying a major habitat?', 'c460063f-8ea0-5de3-8b89-7bfa07d120cb'::uuid, NULL, NULL, E'Ecosystem', NULL, NULL),
