  ('864b4a4b-fc1f-532d-8c36-03311e25884d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '864b4a4b-fc1f-532d-8c36-03311e25884d'::uuid, 1, NULL, TRUE, 0, NULL, E'Energy Intakes', E'Recommended energy intakes are difficult to {{1}} even among individuals of the same age, sex, weight, height and general pattern of {{2}} . Therefore the energy requirement for healthy people is often {{3}} as the amount of energy needed to {{4}} the status quo.', NULL, NULL, NULL, E'1.calculate, 2.activity, 3.expressed, 4.maintain', NULL, NULL),
  ('86579571-9d74-54cd-a4f7-2ba3419d3afd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '86579571-9d74-54cd-a4f7-2ba3419d3afd'::uuid, 1, NULL, TRUE, 0, NULL, E'Book Reviews', NULL, NULL, NULL, NULL, E'3, 2, 4, 1', NULL, NULL),
  ('8657d7be-9d48-556c-ba95-3af06a2939c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8657d7be-9d48-556c-ba95-3af06a2939c8'::uuid, 1, NULL, TRUE, 0, NULL, E'Grass and Cow', E'In exchange for these services the grasses offer ruminants a plentiful and exclusive supply of lunch. For cows have evolved the special ability to convert grass - which single-stomached creatures like us can''t digest - into high-quality protein. They can do this because they possess what is surely the most highly evolved digestive organ in nature: the rumen.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('865abb59-d58b-5a7e-ab1f-78503408d7cc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '865abb59-d58b-5a7e-ab1f-78503408d7cc'::uuid, 1, NULL, TRUE, 0, NULL, E'Domesticated Rabbits', E'Domesticated rabbits come in all sizes and colors, including tiny Netherland Dwarfs, floppy-eared French lops, Flemish Giants, and fluffy Angoras. These breeds belong to Europe''s only rabbit species, originally limited to the Iberian Peninsula and Southern France and used for meat and fur since the last Ice Age, culminating in domestication about 1,500 years ago.', NULL, NULL, NULL, NULL, NULL, NULL),
