  ('86b9aaee-6a38-5128-893c-c3b97a46cffd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '86b9aaee-6a38-5128-893c-c3b97a46cffd'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c32aff67-1ea9-5bc6-b509-34662c879e29'::uuid, NULL, E'He was an abstract expressionist painter.', NULL, NULL, NULL),
  ('86c04ea7-ed2c-5053-bd98-d86d0e5eaf34'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '86c04ea7-ed2c-5053-bd98-d86d0e5eaf34'::uuid, 1, NULL, TRUE, 0, NULL, E'Human Brain', E'We now know through the work of neuroscientists that the human brain is wired to mimic other people, and this mimicry involves actual involuntary physiological {{1}} in the observer. Human beings tend to {{2}} actions that they see. Physiologically, our brains include mirror neurons, which {{3}} to actions that are seen as if we are doing the action ourselves. It is largely an unconscious and automatic experience. When we hear people speak, observe their vocal {{4}} , watch their posture, gestures, and facial expressions, etc, neural networks in our brains are stimulated by the ''shared representations'' generating feelings within us that {{5}} the experience of those we are observing.', NULL, NULL, NULL, E'1.experience, 2.imitate, 3.react, 4.nuances, 5.reflect', NULL, NULL),
  ('86c1d58b-0f44-50e4-96c7-35cfc577281c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '86c1d58b-0f44-50e4-96c7-35cfc577281c'::uuid, 1, NULL, TRUE, 0, NULL, E'Genius', E'Genius, in the popular conception, is inextricably tied up with precocity - doing something truly creative, we''re inclined to think, requires the freshness and exuberance and energy of youth. Orson Welles made his masterpiece, "Citizen Kane," at twenty-five. Herman Melville wrote a book a year {{1}} his late twenties, culminating, at age thirty-two, with "Moby-Dick." Mozart wrote his breakthrough Piano Concerto No. 9 in E-Flat-Major at the {{2}} of twenty-one. In some creative forms, like lyric poetry, the {{3}} of precocity has hardened into an iron law. How old was T. S. Eliot when he wrote "The Love Song of J. Alfred Prufrock" ("I grow old ... I grow old")? Twenty-three. "Poets peak young," the {{4}} researcher James Kaufman maintains. Mihály Csíkszentmihályi, the author of "Flow", agrees: "The most creative lyric verse is believed to be that written by the young." According to the Harvard psychologist Howard Gardner, a leading {{5}} on creativity, "Lyric poetry is a {{6}} where {{7}} is discovered early, burns brightly, and then peters out at an early age."', NULL, NULL, NULL, E'1.through, 2.age, 3.importance, 4.creativity, 5.authority, 6.domain, 7.talent', NULL, NULL),
  ('86cbf632-f6ad-5749-9009-91028a50c641'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '86cbf632-f6ad-5749-9009-91028a50c641'::uuid, 1, NULL, TRUE, 0, NULL, E'Paper Label', E'Make sure your shipping envelopes are clean and dry, and remember to remove any paper shipping labels before going to drop-off {{1}} . Paper labels are detrimental to the Store Drop-off recycling {{2}} . If the labels don''t peel off easily, you can cut them off with {{3}} .', NULL, NULL, NULL, E'1.locations, 2.process, 3.scissors', NULL, NULL),
