  ('86eaf06b-91ee-516e-9508-23e572d0c308'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '86eaf06b-91ee-516e-9508-23e572d0c308'::uuid, 1, NULL, TRUE, 0, NULL, E'Drive', E'Leaders tend to be highly {{1}} individuals. This inner drive is reflected in a number of common ways. They reflect a greater effort level in general, they {{2}} for achievement, they have greater {{3}} , they work with greater energy, they are often tenacious, and they are more likely to take the {{4}} rather than wait for someone else to do so.', NULL, NULL, NULL, E'1.motivated, 2.strive, 3.ambition, 4.initiative', NULL, NULL),
  ('86eb835a-7e28-5dff-8acf-ee98f00bdf84'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '86eb835a-7e28-5dff-8acf-ee98f00bdf84'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call meat that comes from a pig?', '39f87c5c-b0e4-5924-ade8-e3e6dc5d02cd'::uuid, NULL, NULL, E'Pork', NULL, NULL),
  ('86eef37a-536b-524d-a430-fb59bb52ddfa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '86eef37a-536b-524d-a430-fb59bb52ddfa'::uuid, 1, NULL, TRUE, 0, NULL, E'Oversleeping', NULL, '36fdf29d-d890-521e-a5e7-5cd772ea3bd5'::uuid, NULL, E'According to a study on the sleep habits of 400,000 Taiwanese adults, the risk of coronary heart disease is about the same in people who sleep less than 4 hours a night as it is in those who sleep more than eight hours a night. Subjects who underslept had a 35% higher risk of heart disease, and people who overslept had a 34% increase. Another study, published in 2009, followed 276 subjects for six years and found that people who slept either less than 7 hours or more than 8 hours were at least twice as likely to develop type 2 diabetes or trouble tolerating glucose. And there’s more: A 2013 study of about 54,000 adults over the age of 44 found links between too much sleep and increased rates of heart disease, diabetes, obesity, stroke, and mental health issues. In fact, the rates of coronary heart disease, diabetes, and stroke were even higher in people who overslept than in those who slept too little. So, the links are there. Sleep correlates with all kinds of health problems. But it’s hard to say whether too much sleep actually causes these issues. It’s totally possible that oversleeping is actually a symptom of things like depression or heart disease, or that there’s some other connection. Either way, consistently sleeping too much might be a bad sign.', NULL, NULL, NULL),
  ('86f4b98f-3fe9-58b7-b7c0-96f8c47289dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '86f4b98f-3fe9-58b7-b7c0-96f8c47289dd'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f40c4178-dbb4-5d78-bcde-af3fe8c1280f'::uuid, NULL, NULL, E'The bank is hoping to tap into a fast-growing market.', NULL, NULL),
  ('86f96b51-012b-5e2d-8506-f9fa20024a32'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '86f96b51-012b-5e2d-8506-f9fa20024a32'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b6e2fe45-3119-5a2c-a0e1-10de009c1bd9'::uuid, NULL, NULL, E'Experts are now able to forecast weather over much longer periods.', NULL, NULL),
  ('86fa81c7-ee16-5c50-897b-f958eaca1d38'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '86fa81c7-ee16-5c50-897b-f958eaca1d38'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9ded95c4-b2f0-50f5-ad66-2dd4d83e60c1'::uuid, NULL, E'Even scientists do not comprehend these phenomena.', NULL, NULL, NULL),
  ('86fd7c14-07ba-5d3a-82db-1ead00f5c7e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '86fd7c14-07ba-5d3a-82db-1ead00f5c7e1'::uuid, 1, NULL, TRUE, 0, NULL, E'Technology', E'Technology has transformed the way we learn and interact with information, from online learning platforms to virtual reality simulations that offer new ways of engaging with course material. These tools can enhance the learning experience by providing more flexibility, interactivity, and customization than traditional classroom methods. For example, online learning platforms like Coursera or edX offer students access to courses from top universities around the world.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('86ff1a95-cb37-5de6-9c65-7bb51c973cd3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '86ff1a95-cb37-5de6-9c65-7bb51c973cd3'::uuid, 1, NULL, TRUE, 0, NULL, E'Space Exploration', E'Space exploration has entered a new era with the {{1}} of private spaceflight companies. The collaborative efforts between agencies like NASA and private entities are paving the {{2}} for ambitious missions to Mars and beyond. Technological advancements are critical to the future of human space travel and the quest to {{3}} extraterrestrial life. As a result of these partnerships, space exploration has become more accessible and cost-effective than ever before.', NULL, NULL, NULL, E'1.advent, 2.way, 3.discover', NULL, NULL),
  ('86ff22ff-49d1-5df8-89fc-10e472766d3a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '86ff22ff-49d1-5df8-89fc-10e472766d3a'::uuid, 1, NULL, TRUE, 0, NULL, E'Buffets', E'The three main costs of running a restaurant are rent, food and labor. One of the big reasons why weekday lunch and Sunday brunch buffets are so popular with restaurant owners is that they are major labor-saving devices, and therefore cost-saving devices.\nAaron Allen is a restaurant consultant and industry analyst. He explains that a buffet cuts back on staff throughout the restaurant.\n"If the guest is walking through the buffet and plating their own food and basically serving themselves, you don''t need as many front-of-house workers," says Allen, referring to waiters and bussers. "And for the back-of-house kitchen staff, you don''t need to have an a la carte culinary team making items to order. Just a few cooks can make items in batches and replenish, so you can work with a smaller crew and produce more volume."\nMatthew Britt, a chef and instructor at Johnson & Wales University in Providence, Rhode Island, says that lower staffing needs and the predictability of buffet cooking are a great way for an a la carte restaurant to balance risk. Britt says that with the rise of nouvelle cuisine in the 1970s and 1980s profit margins at restaurants became much thinner. "There''s a lot of uncertainty in a nouvelle cuisine dinner service. You don''t know who''s coming in or what they''re going to order. You need an army of highly trained cooks to facilitate all the guests'' needs," says Britt. "The lunch or brunch buffet was the answer to that."', NULL, NULL, NULL, NULL, 5, 75),
  ('8705200e-1bad-58e3-9b24-88f287b64165'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8705200e-1bad-58e3-9b24-88f287b64165'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7a5d5a9e-e7ab-52aa-9046-aaea708a460d'::uuid, NULL, NULL, E'There are a lot of competitions for places on the history classes.', NULL, NULL),
  ('8706cc87-1e0f-578d-a7ed-99ba8eeb4c8d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8706cc87-1e0f-578d-a7ed-99ba8eeb4c8d'::uuid, 1, NULL, TRUE, 0, NULL, E'Computerized Workplace', E'The computerized workplace can be hazardous to your health. If you don''t take preventative measures today, we''ll go over what some of these hazards are, and more importantly, what can be done about them. One major complaint may be the biggest complaint of people who spend time at the computer is eyestrain. To help ease the strain on the eyes, the computer screen should be about two feet from your eyes. The entire screen should be in focus. The brightness and contrast should be adjusted for best readability. A good way to relieve eyestrain is to look away from the screen, frequently focus your eyes on objects that are far away, like something outside the building across the street, or the tree in the...\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '8df99cff-dc30-5bff-b6b2-59d8b2a58dfa'::uuid, NULL, NULL, E'parking lot', NULL, NULL),
