  ('870b6dd3-ae8a-5743-bfe9-efc841d69b73'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '870b6dd3-ae8a-5743-bfe9-efc841d69b73'::uuid, 1, NULL, TRUE, 0, NULL, E'Pluto', E'Pluto lost its official status as a planet yesterday, when the International Astronomical Union downsized the solar system from nine to eight planets. Although there had been a passionate debate at the IAU General Assembly Meeting in Prague about the definition of a planet, and whether Pluto met the specifications, the audience greeted the decision to exclude it with applause.', NULL, NULL, NULL, NULL, NULL, NULL),
