  ('870ffc18-8dc7-51d4-9489-53df33ab46f3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '870ffc18-8dc7-51d4-9489-53df33ab46f3'::uuid, 1, NULL, TRUE, 0, NULL, E'Nitrogen Dioxide', E'As far as nitrogen dioxide is concerned, vehicle emissions are the biggest source. Besides, power plants and factories also generate these pollutants. Volcanic activities, lightning, and the decaying process of organic matter may also generate a large amount of nitrogen dioxide.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('8711f4f1-645f-5577-9cb8-e218fdc82b9e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8711f4f1-645f-5577-9cb8-e218fdc82b9e'::uuid, 1, NULL, TRUE, 0, NULL, E'Stratification', E'In Western countries, social stratification primarily occurs as a result of socioeconomic status in which a hierarchy determines the groups most likely to gain access to financial resources and forms of privilege. Typically, the upper classes have the most access to these resources while the lower classes may get few or none of them, putting them at a distinct disadvantage.', NULL, NULL, NULL, NULL, NULL, NULL),
