  ('87215fa8-1634-590d-97ea-b5e8408072e3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '87215fa8-1634-590d-97ea-b5e8408072e3'::uuid, 1, NULL, TRUE, 0, NULL, E'Academia', E'Academia’s mission is to make all research available for free to everyone in the world. Upgrading to premium is a way to support this mission and help make all scholarship and science easily and freely accessible to everyone, not just those affiliated with well-endowed institutions. Academia Premium also includes features such as Advanced Search and Extra Analytic.', NULL, NULL, NULL, NULL, NULL, NULL),
