  ('873f3821-347f-5fd4-9c20-d148274605d6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '873f3821-347f-5fd4-9c20-d148274605d6'::uuid, 1, NULL, TRUE, 0, NULL, E'Theory of Evolution', E'According to the theory of evolution, individuals with traits that enable them to {{1}} to their environments will help them survive and have more offspring, which will {{2}} those traits. Over time, the traits that enable species to survive and {{3}} will become more frequent in the population and the population will evolve.', NULL, NULL, NULL, E'1.adapt, 2.inherit, 3.reproduce', NULL, NULL),
  ('873f762c-0f51-5a5a-8913-4a849fd38d04'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '873f762c-0f51-5a5a-8913-4a849fd38d04'::uuid, 1, NULL, TRUE, 0, NULL, E'Organic Food', E'Organic food production is a self- {{1}} industry with government {{2}} in some countries, distinct from private gardening. Currently, the European Union, the United States, Canada, Japan, and many other countries require producers to obtain special {{3}} based on government-defined standards in order to market food as organic within their borders. In the {{4}} of these regulations, foods marketed as organic are produced in a way that complies with organic {{5}} set by national governments and international organic industry trade organizations.', NULL, NULL, NULL, E'1.regulated, 2.oversight, 3.certification, 4.context, 5.standards', NULL, NULL),
