  ('8749d2de-2d10-54bc-9eb3-e6e9074bb8cb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8749d2de-2d10-54bc-9eb3-e6e9074bb8cb'::uuid, 1, NULL, TRUE, 0, NULL, E'Rates of Depression', E'Rates of depression have been a growing concern in recent years, particularly among adolescents and adults. In the United States, it is estimated that 4.1 million adolescents aged 12 to 17 have experienced at least one major depressive episode. This indicates a rising trend in depression rates among adolescents.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('874cd439-cf52-5142-a326-12a5bc62f389'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '874cd439-cf52-5142-a326-12a5bc62f389'::uuid, 1, NULL, TRUE, 0, NULL, E'Petrified Forest', E'The Petrified Forest is home to some of the most impressive fossils ever found and more are being discovered each year as erosion {{1}} new evidence. Fossils found here show the Forest was once a tropical region, {{2}} towering trees and extraordinary creatures we can only imagine. {{3}} more than 150 different species of fossilized plants have been discovered by paleontologists, species of reptiles, such as Desmatosuchus, similar to the armadillo, have also been discovered.\nArchaeologists have found {{4}} evidence to indicate that ancient native people inhabited this region about 10,000 years ago. Petroglyph drawings on rock surfaces, gives a glimpse of the past and you can see the marks of a solar calendar at Puerco Pueblo near the time of the summer solstice.', NULL, NULL, NULL, E'1.exposes, 2.filled with, 3.While, 4.much', NULL, NULL),
  ('874f70da-24eb-5534-9925-5af74e78b257'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '874f70da-24eb-5534-9925-5af74e78b257'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a large game bird, often hunted for its meat?', 'e6b9d9ec-c782-5dc0-87b6-4251b157c9da'::uuid, NULL, NULL, E'Grouse', NULL, NULL),
