  ('8824b15f-6c83-550e-94e4-7a6dcb16740b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8824b15f-6c83-550e-94e4-7a6dcb16740b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '37bfa44c-e48b-5669-87c5-dddbf68db0dd'::uuid, NULL, NULL, E'The night sky has always involved mystery and wonder.', NULL, NULL),
  ('882ab7d0-b2f5-581d-94ae-6b7a0f9c625d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '882ab7d0-b2f5-581d-94ae-6b7a0f9c625d'::uuid, 1, NULL, TRUE, 0, NULL, E'Aphasia', E'Aphasia is a communication disorder that affects someone''s ability to speak or understand speech. It also impacts how they understand written words and their ability to read and to write.\nIt is important to note that aphasia can take different forms. Some people with aphasia only have difficulty understanding language, a result of damage to the temporal lobe, which governs how sound and language are processed in the brain. Others have only difficulty with speaking, indicating damage to the frontal lobe. A loss of both speaking and comprehension of language would suggest damage to both the large temporal lobe and frontal lobe.\nIn most cases, aphasia results from a stroke or hemorrhage in the brain. It can also be caused by damage to the brain from impact injury such as a car accident. Brain tumors can also result in aphasia.\nThere is also a separate form of the condition called primary progressive aphasia. This starts off with mild symptoms but gets worse over time. The medical community doesn''t know what causes primary progressive aphasia. We know that it affects the same brain regions as in cases where aphasia results from a stroke or hemorrhage, but the onset of symptoms follow a different trajectory.\nAphasia is unfortunately quite common. Approximately one-third of all stroke survivors have it. In the U.S., around 2 million people have aphasia and around 225,000 Americans are diagnosed every year. Right now, we don''t know what proportion of people with aphasia have the primary progressive form of the condition.', NULL, NULL, NULL, NULL, 5, 75),
  ('8837548f-45b9-506f-80d7-89b0a775136f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8837548f-45b9-506f-80d7-89b0a775136f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What job is concerned with instructing actors while producing a film or movie?', '98851656-1175-52fe-b157-5a4febea179e'::uuid, NULL, NULL, E'Director', NULL, NULL),
  ('883bc248-a88b-584d-a155-828416d17034'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '883bc248-a88b-584d-a155-828416d17034'::uuid, 1, NULL, TRUE, 0, NULL, E'Research Ship', E'The modern research ship takes its origins from the early exploration voyages such as HMS Endeavour and HMS Challenger, both of which were converted vessels, fitted with a range of research facilities to sample and measure across a range of disciplines in extreme environments. Early research vessels were fairly basic and simplistic compared to the state-of-the-art ships we see being developed today. Gradually, the trend of converting other vessels into research ships {{1}} by the challenging demands of investigating increasingly complex areas of oceanographic research, such as physical, biological and chemical oceanography; marine geology and geophysics; ocean engineering and atmospheric science in one expedition. In order to carry {{2}} multi-disciplinary research in extreme environments, specially designed research vessels became a requirement. Research ships are the primary source of oceanographic observations and {{3}} so for the foreseeable future. As time {{4}} , science is likely to be conducted in increasingly remote and environmentally challenging areas, including the polar seas, so the ability to operate with minimal interruptions from the natural elements remains unchanged from the days of the Challenger Expedition.', NULL, NULL, NULL, E'1.was challenged, 2.out, 3.will remain, 4.goes on', NULL, NULL),
  ('8844320d-b6e4-5cff-97e1-84f55d29f3d0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8844320d-b6e4-5cff-97e1-84f55d29f3d0'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '05010779-0006-5d88-ab52-7d5afaace757'::uuid, NULL, NULL, E'I thought we would meet in the small meeting room.', NULL, NULL),
  ('884557dd-18e2-566f-8952-500e222236c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '884557dd-18e2-566f-8952-500e222236c6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6fe9164b-447b-541e-9391-e37dedad63e6'::uuid, NULL, E'Students had to choose one elective from the choices of art, music and computers.', NULL, NULL, NULL),
