  ('88c15841-79dc-5f15-9c3e-7d2c62049e24'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '88c15841-79dc-5f15-9c3e-7d2c62049e24'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'cfc1d556-cdfd-59e5-8a68-bcb76adf5270'::uuid, NULL, NULL, E'All students do their homework at home.', NULL, NULL),
  ('88c20583-5051-540c-b3e9-c288699e1164'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '88c20583-5051-540c-b3e9-c288699e1164'::uuid, 1, NULL, TRUE, 0, NULL, E'Enhancing Collaboration', E'You''re tasked with leading a team to develop a new software feature within a tight deadline. The team is talented but new to working together, and progress has been slower than expected. To meet the deadline, you need to find ways to enhance collaboration and efficiency among team members without causing burnout. What would you say to your team?', '9f6a0d07-629f-5917-a825-43febad4eb7c'::uuid, NULL, E'Hey team, I''ve noticed we''re a bit behind on our project timeline. You''re all doing great, but since we''re a new team, it takes time to find our groove. Let''s try a couple of things to boost our workflow: first, daily quick stand-up meetings to share updates and hurdles. Also, how about pairing up on trickier tasks? Two heads are often better than one, and it''s a great way to speed things up without overworking anyone.', NULL, NULL, NULL),
  ('88c8d326-c7cc-52da-b2b6-a8916b1ff1aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '88c8d326-c7cc-52da-b2b6-a8916b1ff1aa'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call the upper interior surface of a room?', '7ef887c7-7f8e-5b79-b167-68ebf3bbf2d2'::uuid, NULL, NULL, E'Ceiling', NULL, NULL),
  ('88c8f18a-38b9-52a6-9cba-200f123d2039'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '88c8f18a-38b9-52a6-9cba-200f123d2039'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7b18e7a8-5761-55fb-93a7-4895a9d0778f'::uuid, NULL, NULL, E'The instructor started with his lecture notes to show his ideas.', NULL, NULL),
  ('88ccca42-5eae-5033-8b1b-898372640ee0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '88ccca42-5eae-5033-8b1b-898372640ee0'::uuid, 1, NULL, TRUE, 0, NULL, E'Coveted Internship', E'Your son, barely out of his teens, has just landed a coveted internship at a Michelin-starred restaurant. He spends his weekends experimenting with exotic ingredients, his kitchen a symphony of clanging pots and bubbling sauces. Yet, this culinary prodigy can''t seem to manage the simplest task at home. How can someone possess such talent and passion yet {{1}} basic life skills? The answer {{2}} the intricate dance between passion and practicality, says Dr. Evelyn Davis, a renowned neuropsychologist. "The young mind is a canvas brimming with unbridled enthusiasm, {{3}} to explore and master new domains," she explains. "But this very passion can sometimes overshadow the development of foundational skills that seem mundane in comparison." Research suggests that the areas of the brain {{4}} for creativity and exploration are particularly active in youth. This explains the seemingly boundless energy and enthusiasm young people bring to their pursuits. However, the regions responsible for planning, organization, and execution often lag {{5}} , necessitating external guidance and structure.', NULL, NULL, NULL, E'1.lack, 2.lies in, 3.eager, 4.responsible, 5.behind', NULL, NULL),
  ('88ce8c40-e399-5a4b-afdc-c0617ad63a91'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '88ce8c40-e399-5a4b-afdc-c0617ad63a91'::uuid, 1, NULL, TRUE, 0, NULL, E'Magnetar', E'The best comparison is likely a magnetar, a young neutron star with a powerful magnetic field, the researchers said. Magnetars also produce bright X-ray flares. While magnetars are thought to be young stars, the two flaring objects in this study reside near elliptical galaxies, which contain older stars. So the objects are likely too old to be magnetars, the researchers said.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('88d188b0-0980-5c6e-970e-0e13bd571fb3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '88d188b0-0980-5c6e-970e-0e13bd571fb3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9fe1a49e-c215-532d-8456-cf2c059bf734'::uuid, NULL, E'Crops respond no more readily to anything than to careful husbandry and skillful cultivation.', NULL, NULL, NULL),
  ('88d8a61f-bed5-5186-a619-8d4843f5cdc4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '88d8a61f-bed5-5186-a619-8d4843f5cdc4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b1210489-1d15-5c2a-a9aa-0efd8fa0f1bb'::uuid, NULL, NULL, E'This graph shows there is a minimum growth.', NULL, NULL),
  ('88d8bf5c-33b0-5c0a-a817-180ba6a879c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '88d8bf5c-33b0-5c0a-a817-180ba6a879c6'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How many times does an isolated incident occur?', 'fec8b040-ca06-5fa8-8173-f4766f60c848'::uuid, NULL, NULL, E'One / Once', NULL, NULL),
  ('88dc17b5-cc3f-516a-865d-eb55052e7f7d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '88dc17b5-cc3f-516a-865d-eb55052e7f7d'::uuid, 1, NULL, TRUE, 0, NULL, E'Universal Expressions', NULL, 'ad18f22c-4cd5-5adb-934c-639b0d1d71e9'::uuid, NULL, E'What makes certain expressions universal? And why are they expressed in these particular ways? Scientists have a lot of theories rooted in our evolutionary history. One is that certain expressions are important for survival. Fear and surprise could signal to others an immediate danger. Studies of humans and some other primates have found that we pay more attention to faces that signal threats over neutral faces, particularly when we''re already on high alert. Expressions also could help improve group fitness by communicating our internal states to those around us. Sadness, for example, signals to the group that something’s wrong. There’ s some evidence that expressions might be even more directly linked to our physiology. The fear expression, for instance, could directly improve survival in potentially dangerous situations by letting our eyes absorb more light and our lungs take in more air, preparing us to fight or flee. There’s still much research to be done in understanding emotional expression, particularly as we learn more about the inner workings of the brain. But if you ever find yourself among strangers in a strange land, a friendly smile could go a long way.', NULL, NULL, NULL),
  ('88e19b84-fe65-5e88-816e-2ab7ede677f3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '88e19b84-fe65-5e88-816e-2ab7ede677f3'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What’s the color of the medal that a champion gets?', '5b3f33ce-e89b-5490-8ab8-a7123a962bca'::uuid, NULL, NULL, E'Golden / gold', NULL, NULL),
  ('88e2fab9-4a07-5b4c-b31f-d88660fe13c7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '88e2fab9-4a07-5b4c-b31f-d88660fe13c7'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e88aa7dd-8e4a-52b2-a0b2-3451e76fd2aa'::uuid, NULL, E'You must ensure you do not include too much irrelevant information.', NULL, NULL, NULL),
  ('88e88170-e469-5d43-9415-a9b6058d86d6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '88e88170-e469-5d43-9415-a9b6058d86d6'::uuid, 1, NULL, TRUE, 0, NULL, E'Experiential Purchases', E'Experiential purchases are also more associated with identity, connection, and social behavior. Looking back on purchases made, experiences make people happier than do possessions. It''s kind of counter to the logic that if you pay for an experience, like a vacation, it will be over and gone.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('88ec978a-b7d2-58f7-be50-9400d760f1b0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '88ec978a-b7d2-58f7-be50-9400d760f1b0'::uuid, 1, NULL, TRUE, 0, NULL, E'Squirrels Lifespan', E'Wild squirrels can live up to 18 years, depending on their species, environment and a handful other factors. In North America, we most often see Eastern gray squirrels, tree squirrels and red squirrels, which all have white bellies and bushy tails but slightly different average life spans. They fall into three basic types: tree squirrels, ground squirrels and flying squirrels.\nAll squirrels are part of the rodent family, and as is the case for many mammals, the larger the species of squirrel, the longer its average life span.\nBut what about pet squirrels? Do squirrels in captivity tend to live longer than wild squirrels live? Sometimes they do. Red squirrels can live up to eight years in captivity compared to about five years in the wild. The average life span of a gray squirrel in captivity keeps increasing. They can live as long as 20 years as a pet compared to six years in the wild.\nFox squirrels also live longer as pets. In captivity they can live up to 18 years; that''s almost double their average life span in the wild. Of course, not everybody loves squirrels; they really are everywhere, and they really do eat everything. Next time you see a squirrel getting into your garden or trying to eat your birdseed, remember the furry little guy is just doing normal squirrel things.', NULL, NULL, NULL, NULL, 5, 75),
  ('88ef86d4-8ac1-50b1-bf25-7c7f6cb315fa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '88ef86d4-8ac1-50b1-bf25-7c7f6cb315fa'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd70e77c6-d6ed-5153-acff-0fae178f7236'::uuid, NULL, E'Companies are offering us all kinds of internet-connected devices.', NULL, NULL, NULL),
