  ('8985e679-265d-58e9-b7db-9eafe08c6de6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8985e679-265d-58e9-b7db-9eafe08c6de6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '234a032b-769a-5d0f-8119-5b0b21ee506f'::uuid, NULL, NULL, E'Researchers found that trees can relieve stress and anxiety.', NULL, NULL),
  ('8988bcd0-0e0f-511b-bac8-b9a868b9637a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8988bcd0-0e0f-511b-bac8-b9a868b9637a'::uuid, 1, NULL, TRUE, 0, NULL, E'Animals and Noise', E'Animals as well as humans are affected by noise. There is evidence to show that some whales. for example, died when they beached themselves after being exposed to excessive sonar - the noise produced by submarines as they navigate underwater. It''s been shown that whales produced louder sounds when communicating with each other when sonar equipment was on in their vicinity. This was doubtless because they needed to make themselves heard by their fellows, perhaps to warn each other of danger, or tell one another about a food source. Another example of how noise can affect animal behavior is given by the European robin. In urban areas this small bird sings at night rather than during the day.\n\nWhat point does the lecturer make about whales and sound pollution?', 'e8a88778-245a-5bd3-aaae-68f623ad6bbf'::uuid, NULL, NULL, E'Whales may not survive in some situations where there is sound pollution.', NULL, NULL),
  ('898babe8-eac1-59d2-b311-ba1d2151ccc5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '898babe8-eac1-59d2-b311-ba1d2151ccc5'::uuid, 1, NULL, TRUE, 0, NULL, E'Human Brain', E'Researchers have created the largest atlas of human brain cells so far, revealing more than 3,000 cell types — many of which are new to science. The work, published in a package of 21 papers today in Science, Science Advances and Science Translational Medicine, will aid the study of diseases, cognition and what makes us human, among other things, say the authors.', NULL, NULL, NULL, NULL, NULL, NULL),
