  ('89a10f10-d48a-5a97-83ca-fb723c45090d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '89a10f10-d48a-5a97-83ca-fb723c45090d'::uuid, 1, NULL, TRUE, 0, NULL, E'Film', E'The silver screen lights up with the flicker of images, transporting us to different worlds, different times, and different lives. Film is an art form that allows us to explore the beauty and complexity of the human experience in all its glory. From the sweeping epic to the intimate character study, it is a medium that captures the imagination and stirs the soul.', NULL, NULL, NULL, NULL, NULL, NULL),
