  ('89ad1099-a4ec-5f6b-a7cb-1d26eb8b80bc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '89ad1099-a4ec-5f6b-a7cb-1d26eb8b80bc'::uuid, 1, NULL, TRUE, 0, NULL, E'Medical Jargon', E'British doctors have been {{1}} to use simple language when communicating with their patients, says the BBC. The Academy of Medical Royal Colleges says very often correspondence contains complex medical jargon rather than plain and simple English. Using of phrase "twice daily" to explain the {{2}} of a medicine is better than Latin abbreviation "bd". The Please Write to Me initiative is aimed basically at doctors working in {{3}} clinics, although it is the best practice for all clinicians who need to write clinical letters and they are being asked to write directly to patients, rather than sending them a copy of a letter {{4}} to their GP. The Academy suggests any medical words should be {{5}} in plain English.', NULL, NULL, NULL, E'1.urged, 2.dosing, 3.outpatient, 4.penned, 5.translated', NULL, NULL),
  ('89af9da6-d81a-513c-9e4c-bddb99472b1f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '89af9da6-d81a-513c-9e4c-bddb99472b1f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9f4119a3-b756-5f07-8e9a-8645c7392345'::uuid, NULL, E'You need to be careful when quoting Internet sources.', NULL, NULL, NULL),
  ('89b052fa-c6ec-546e-8c77-0b72bb69e0e4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '89b052fa-c6ec-546e-8c77-0b72bb69e0e4'::uuid, 1, NULL, TRUE, 0, NULL, E'Language Deficit', E'This is a challenging time for UK students, and we should be making their transition from university to the globalized world easier, not harder. The British Academy has voiced its {{1}} over the growing language deficit for some years, and the gloomy statistics speak for themselves. We need {{2}} action if we are remedying this worsening situation. The {{3}} of the problem lie within schools, but Vice-Chancellors have the power to drive change and help their students recognize the importance of learning languages, and about the countries where they are spoken and the cultures they sustain. We {{4}} them to act and protect this country''s long term economic, social and cultural standing.', NULL, NULL, NULL, E'1.concern, 2.decisive, 3.roots, 4.urge', NULL, NULL),
  ('89b4c0fb-11fe-5547-9bbd-c01900037f8a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '89b4c0fb-11fe-5547-9bbd-c01900037f8a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the architectural term for a room or building used for scientific experiments, research, or teaching, or for the manufacture of drugs or chemicals?', 'e647a3fd-a6d4-5e59-9da6-7bf234262deb'::uuid, NULL, NULL, E'Laboratory / Lab', NULL, NULL),
  ('89b9d208-ebbd-5f89-8bf1-5d85213c0788'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '89b9d208-ebbd-5f89-8bf1-5d85213c0788'::uuid, 1, NULL, TRUE, 0, NULL, E'Carbon Dioxide', E'Every metric ton of carbon dioxide humans emit comes at a cost — not only in terms of the financial toll of the damage wrought by floods, heat waves and droughts but also the price in human lives. Substantially curtailing emissions today could prevent tens of millions of premature deaths over the course of this century.', NULL, NULL, NULL, NULL, NULL, NULL),
