  ('89c56a48-b6d6-53b6-8725-d97f53d87891'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '89c56a48-b6d6-53b6-8725-d97f53d87891'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b5cb4d83-647d-54d6-8894-53ddef280630'::uuid, NULL, E'These seafront amusements have been attracting visitors from big cities.', NULL, NULL, NULL),
  ('89c5adc7-2bde-50e5-98a2-a865ca972a0b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '89c5adc7-2bde-50e5-98a2-a865ca972a0b'::uuid, 1, NULL, TRUE, 0, NULL, E'Mafia', E'In organized crime there is a hierarchy, with higher-ranking members making decisions that trickle down to the other members of the family. The Mafia is not a single group or gang — it is made up of many families that have, at times, fought each other in bitter, bloody gang wars. At other times, they have cooperated in the interest of greater profits, sometimes even serving on a "Commission" that made major decisions affecting all the families . Most of the time, though, they simply agree to stay out of each other''s way.\n\nFrom the author’s description of Mafia, which of the following statement is true?', NULL, NULL, NULL, E'Families may fight with each other or work together depending on the circumstances.', NULL, NULL),
  ('89c5ca14-14c2-5996-ab72-8cec026571ec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '89c5ca14-14c2-5996-ab72-8cec026571ec'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c0597e0a-d524-5455-94cd-01e6e86f1435'::uuid, NULL, E'Your duties mainly include typing letters and answering the telephone.', NULL, NULL, NULL),
  ('89ce6290-0c56-54c5-a543-7dd7eaee6781'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '89ce6290-0c56-54c5-a543-7dd7eaee6781'::uuid, 1, NULL, TRUE, 0, NULL, E'Spiral of Silence', E'The spiral of silence is a mass communication theory introduced by Elizabeth to describe the process of public opinion formation. He defines the “spiral of silence” as the process an individual experiences when he may find that the views he holds are losing ground; the more this appears to be so, the less he will be inclined to express his opinion.', NULL, NULL, NULL, NULL, NULL, NULL),
