  ('89d5ec41-5144-5f11-b9ac-16c55eed6a13'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '89d5ec41-5144-5f11-b9ac-16c55eed6a13'::uuid, 1, NULL, TRUE, 0, NULL, E'Geology', E'I suppose the reason I got into geology was, well, as a kid I was fascinated by fossils - the fact that they went back countless years, long before there were any people on the planet. That was exciting and, urn, they were beautiful too. And one thing led to another. What fascinates me ... let me give you an example: suppose we dredge up from the sea floor some silt washed down by a river and, um, suppose that for political or other reasons we can''t enter the country through which that river runs. Well, by careful study of the particles of that silt, we can form a pretty accurate picture of the nature of that country. Not just the rocks, 1mean, but the vegetation and animal life of the area. I sometimes think what we do is a bit like, urn, Sherlock Holmes. You know, he takes a look at a man''s shoes and can tell you which field in which county in England he''s been in, and when. That sort of detective aspect of the work is always interesting and exciting. OK. we do spend time in the lab and at the computer, but we do get out and about, and go to interesting places for fieldwork.\n\nWhat made the speaker take up geology as a profession?', '25057ea1-8ab8-5c6c-b4ed-7401b66bfba2'::uuid, NULL, NULL, E'His childhood interest in fossils.', NULL, NULL),
  ('89dbd5b9-8e75-52bd-a891-930ec7505d4e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '89dbd5b9-8e75-52bd-a891-930ec7505d4e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3d522265-d498-567f-9ce8-ecd380334094'::uuid, NULL, NULL, E'Designers need to keep up with social trends.', NULL, NULL),
  ('89dcbe57-c8e8-53d7-81c5-a61abc9883c1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '89dcbe57-c8e8-53d7-81c5-a61abc9883c1'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '587462fd-3c04-50b7-8917-ce6406684033'::uuid, NULL, E'He has been studying classical architecture and design in Rome for decades.', NULL, NULL, NULL);
