  ('89e122cf-f326-5e95-83cd-0dbda4618960'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '89e122cf-f326-5e95-83cd-0dbda4618960'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '32cd4cfd-4510-5833-ac76-a71cd9e6a6ad'::uuid, NULL, E'What distinguishes him from others is his dramatic use of black and white photography.', NULL, NULL, NULL),
