  ('89ea652a-2cad-5b2e-a8fd-efd5bb792dec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '89ea652a-2cad-5b2e-a8fd-efd5bb792dec'::uuid, 1, NULL, TRUE, 0, NULL, E'Wise Buying', E'Wise buying is a positive way in which you can make your money go further. The way you go about purchasing an article or a service can actually {{1}} you money or can add to the cost. Take the {{2}} example of a hairdryer. If you are buying a hairdryer, you might think that you are making the {{3}} buy if you choose one whose look you like and which is also the cheapest {{4}} price. But when you get it home you may find that it takes twice as long as a more expensive {{5}} to dry your hair. The cost of the electricity plus the cost of your time could well make your hairdryer the most expensive one of all.', NULL, NULL, NULL, E'1.save, 2.simple, 3.best, 4.in, 5.model', NULL, NULL),
  ('89f2b974-d036-5611-a2ab-0791c031c5a3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '89f2b974-d036-5611-a2ab-0791c031c5a3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5bc89ce3-3870-5e15-9f0a-624d6eb97a6c'::uuid, NULL, NULL, E'Many different conferences offer opportunities for volunteer work.', NULL, NULL),
  ('89f3296a-91d5-5a1e-acc7-e8a49f45b363'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '89f3296a-91d5-5a1e-acc7-e8a49f45b363'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do police call the person when they think he or she is guilty of a crime but there isn''t any convincing evidence?', 'd68328ac-6ac8-5537-8613-0d9b6b5c7b3b'::uuid, NULL, NULL, E'Suspect', NULL, NULL),
  ('89f3ec27-da30-57c4-84d3-2865ae4e291c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '89f3ec27-da30-57c4-84d3-2865ae4e291c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2a9a80d8-a4ef-5bc9-8a4a-3ec21bfcccd9'::uuid, NULL, E'These new laboratories enhance the ability of researchers to make new discoveries.', NULL, NULL, NULL),
  ('8a015133-5540-5bc1-a957-3c82786c6b8a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8a015133-5540-5bc1-a957-3c82786c6b8a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'bc596421-dd58-57d2-b352-0329d285143b'::uuid, NULL, NULL, E'The career service provides suggestions on how to pass the job interview.', NULL, NULL),
  ('8a02166c-27f6-55a8-b7cf-cd20996c3da6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8a02166c-27f6-55a8-b7cf-cd20996c3da6'::uuid, 1, NULL, TRUE, 0, NULL, E'Left-handers', NULL, '6c0f138f-39f5-5043-9853-c6183e7efe4f'::uuid, NULL, E'The benefits of being left-handed are clearest in activities involving an opponent, like combat or competitive sports. For example, about 50 % of top hitters in baseball have been left-handed. Why? Think of it as a surprise advantage. Because lefties are a minority to begin with, both right-handed and left-handed competitors will spend most of their time encountering and practicing against righties. So when the two face each other, the left-hander will be better prepared against this right-handed opponent, while the righty will be thrown off. This fighting hypothesis, where an imbalance in the population results in an advantage for left-handed fighters or athletes, is an example of negative frequency-dependent selection. But according to the principles of evolution, groups that have a relative advantage tend to grow until that advantage disappears. If people were only fighting and competing throughout human evolution, natural selection would lead to more lefties being the ones that made it until there were so many of them, that it was no longer a rare asset. So in a purely competitive world, 50% of the population would be left-handed.', NULL, NULL, NULL),
  ('8a0670af-9578-58f8-be28-4622098b1d97'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8a0670af-9578-58f8-be28-4622098b1d97'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call the part of the theatre where actors perform?', '44783479-4bac-5d2a-a0a2-8adc8ae54003'::uuid, NULL, NULL, E'Stage', NULL, NULL),
  ('8a0b953d-4b42-5aa5-a4f1-9c9cd238ebb6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8a0b953d-4b42-5aa5-a4f1-9c9cd238ebb6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8dad16cc-ed82-5f6a-a80b-186952b9486c'::uuid, NULL, E'Being a student representative on the union really cuts into my study time.', NULL, NULL, NULL),
