  ('8a1072b9-8069-5d6f-a9de-85f225d9af72'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8a1072b9-8069-5d6f-a9de-85f225d9af72'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the largest bird in the world that cannot fly?', '764de6c5-e35c-56f9-b4ea-8013b4984efb'::uuid, NULL, NULL, E'Ostrich', NULL, NULL),
  ('8a29c0cb-38bb-59cb-a055-8ca76142e920'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8a29c0cb-38bb-59cb-a055-8ca76142e920'::uuid, 1, NULL, TRUE, 0, NULL, E'Dogs', E'All domestic dogs belong to a single species that descended from wolves—despite vast differences in size, appearance, behavior and temperament among breeds.\nWhile dogs first became domesticated tens of thousands of years ago, the breeds we know today are largely the result of selection for certain traits by humans over the past several hundred years. “We have an enormous amount of diversity within the same species, and we can rarely observe such diversity in nature. So it’s a wonderful system to understand how evolution works within a short period of time.”\nEvolutionary biologist László Garamszegi of the Institute of Ecology and Botany in Hungary. He says that our playing with dogs is a key component of the human-canine bond.\n\nWhat are the characteristics of dogs in this passage?', '215e40a1-300b-515b-ba5a-90ef11957c92'::uuid, NULL, NULL, E'All dogs evolved from wolves.\nPlay can help dogs bond with humans.', NULL, NULL),
  ('8a2afacf-2a11-55bc-a6c7-eaca4c592161'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8a2afacf-2a11-55bc-a6c7-eaca4c592161'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '78e4d7cd-685c-56ef-8de4-4f2fa2f9b623'::uuid, NULL, NULL, E'Options for student housing range from dorms to apartments off-site.', NULL, NULL),
  ('8a2f740d-efc6-5ba1-84dc-05f1917d05bf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8a2f740d-efc6-5ba1-84dc-05f1917d05bf'::uuid, 1, NULL, TRUE, 0, NULL, E'Bacteria', E'A novel approach has been developed that enables researchers to track gene expression during the development of bacterial communities over time and space. Using this cutting-edge technique, scientists have demonstrated for the first time that bacteria collaborate and exchange nutrients across generations when they form communities.', NULL, NULL, NULL, NULL, NULL, NULL),
