  ('8a3a0573-73c5-5828-a06d-465cbe5e83e7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8a3a0573-73c5-5828-a06d-465cbe5e83e7'::uuid, 1, NULL, TRUE, 0, NULL, E'End of Genes', E'Researchers conducting experiments with a novel technique for sequencing individual cells have made a surprising discovery that challenges our existing knowledge of genetic rules. By examining the genome of a protist, they have identified a distinctive deviation in the DNA code that marks the end of a gene.', NULL, NULL, NULL, NULL, NULL, NULL),
