  ('8a56290b-4811-5d9d-9b5c-6225f6f5ab4e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '8a56290b-4811-5d9d-9b5c-6225f6f5ab4e'::uuid, 1, NULL, TRUE, 0, NULL, E'Conflict', E'Most of us are {{1}} of open conflict and avoid it if we can. And there is a {{2}} of expressing and working through conflict. If the working through involves harsh words and name-calling, people feel deeply hurt and relationships can be {{3}} . Sometimes permanently. Some group members may be afraid that if they really {{4}} their anger, they may go out of control and become violent, or they may do this. These fears can be very {{5}} and based on experience.', NULL, NULL, NULL, E'1.scared, 2.risk, 3.damaged, 4.express, 5.real', NULL, NULL),
  ('8a59a2f8-a159-5c7b-ab09-0b27627de590'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '8a59a2f8-a159-5c7b-ab09-0b27627de590'::uuid, 1, NULL, TRUE, 0, NULL, E'Chemistry', E'Chemistry is an extremely important topic in physiology. Most physiological processes occur as the {{1}} of chemical changes that occur within the body. These changes include the influx/efflux of ions across a neuron''s membrane, causing a {{2}} to pass from one end to the other. Other examples include the {{3}} of oxygen in the blood by a protein as it passes through the lungs for {{5}} throughout the body.', NULL, NULL, NULL, E'1.result, 2.signal, 3.storage, 4.usage', NULL, NULL),
