  ('8a6b0614-dda4-51a2-ac6f-d7ce4f3c3e41'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8a6b0614-dda4-51a2-ac6f-d7ce4f3c3e41'::uuid, 1, NULL, TRUE, 0, NULL, E'Industrial Revolution', E'The Industrial Revolution was a transformative period that unfolded from the late 18th century to the 19th century. Characterized by a shift from manual labor to mechanized production, this era marked a significant shift from agrarian and manual labor-based economies to mechanized production and industrialization.', NULL, NULL, NULL, NULL, NULL, NULL),
