  ('8c864bb3-a9b4-5f59-bf19-63517e4b5c65'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8c864bb3-a9b4-5f59-bf19-63517e4b5c65'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5d167e62-32e6-59e4-84ba-4a94ac1b0447'::uuid, NULL, NULL, E'Rivers provide habitats and migration pathways for numerous aquatic species.', NULL, NULL),
  ('8c87f12d-3f1f-5cb4-ab07-895c81de1d6a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8c87f12d-3f1f-5cb4-ab07-895c81de1d6a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '36055962-f865-5155-9ae7-8df52fa8911e'::uuid, NULL, E'Everyone should get access to art galleries no matter where they live.', NULL, NULL, NULL),
  ('8c89d86c-8952-596c-bd70-ae8b3eb20cc0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8c89d86c-8952-596c-bd70-ae8b3eb20cc0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4523857c-a6bc-55c3-96c0-2469a824ea09'::uuid, NULL, E'You will learn to apply business strategies to solve problems in production of agricultural goods.', NULL, NULL, NULL),
  ('8c8ca725-1a92-5b1a-b06c-af230fb2065e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8c8ca725-1a92-5b1a-b06c-af230fb2065e'::uuid, 1, NULL, TRUE, 0, NULL, E'Earthquake', E'Investigations like this one have been plodding along for 40 years, and some studies — like one following the deadly Kobe quake in 1995 — have found similar correlations. But study author Alasdair Skelton, a professor of geochemistry at Stockholm University, says the unpredictable study subject makes it tough to get funding because you can in no way guarantee a result. So l‘ll get three years of money, but if there’s no earthquake, there''s no result.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('8c8f531f-e6c8-5399-bd1f-b226cf55521f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '8c8f531f-e6c8-5399-bd1f-b226cf55521f'::uuid, 1, NULL, TRUE, 0, NULL, E'Great Manager', E'What do great managers actually do? In my research, beginning with a survey of 80,000 managers conducted by the Gallup Organization and continuing during the past two years with in-depth studies of a few top performers, I''ve found that while there are as many styles of management as there are managers, there is one quality that sets truly great managers apart from the rest: they discover what is unique about each person and then capitalize on it. Average managers play checkers, while great managers play chess. The difference? In checkers, all the pieces are uniform and move in the same way; they are interchangeable. You need to plan and coordinate their movements, certainly, but they all move at the same pace, on parallel paths. In chess, each type of piece moves in a different way, and you can''t play if you don’t know how each piece moves. More important, you won''t win if you don’t think carefully about how you move the pieces. Great managers know and value the unique abilities and even the eccentricities of their employees, and they learn how best to integrate them into a coordinated plan of attack.\nThis is the exact opposite of what great leaders do. Great leaders discover what is universal and capitalize on it. Their job is to rally people toward a better future. Leaders can succeed in this only when they can cut through differences of race, sex, age, nationality, and personality and, using stories and celebrating heroes, tap into those very few needs we all share. The job of a manager, meanwhile, is to turn one person''s particular talent into performance. Managers will succeed only when they can identify and deploy the differences among people, challenging each employee to excel in his or her own way. This doesn''t mean a leader can''t be a manager or vice versa. But to excel at one or both, you must be aware of the very different skills each role requires.', NULL, NULL, E'Truly great managers discover what is unique about each person and then capitalize on it, who know and value the unique abilities and even the eccentricities of their employees, and they learn how best to integrate them into a coordinated plan of attack, and great leaders discover what is universal and capitalize on it, while the job of a manager is to turn one person’s particular talent into performance.', NULL, 5, 75),
  ('8c97dd2a-eb92-51bf-a06c-2ab717532d20'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8c97dd2a-eb92-51bf-a06c-2ab717532d20'::uuid, 1, NULL, TRUE, 0, NULL, E'Orientalists', E'Orientalists, like many other nineteenth-century thinkers, conceive of humanity either in large collective terms or in abstract generalities. Orientalists are neither interested in nor capable of discussing individuals; instead, artificial entities predominate. Similarly, the age-old distinction between "Europe" and "Asia" or "Occident" and "Orient" herds beneath very wide labels of every possible variety of human plurality, reducing it in the process to one or two terminal collective realities.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('8c9ca249-af4f-5f86-a263-1bb63b2c3f87'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8c9ca249-af4f-5f86-a263-1bb63b2c3f87'::uuid, 1, NULL, TRUE, 0, NULL, E'Faint Sound', E'Listening to the soft rustle of the leaves, it''s a sound that you simply cannot hear without silence. What you can sense in the noisy environment becomes suddenly vivid in the quiet. How clear and pure the sound is! It''s fascinating, but it''s also soothing. Suddenly, it''s as if another realm has touched your auditory sense and you think, hey I hadn''t realized that something so faint, so subtle could be so ...\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '410e72b8-34fa-580c-b469-cd28d483a5c9'::uuid, NULL, NULL, E'calming', NULL, NULL),
  ('8c9f7704-151f-5f98-93e6-89b92bf593bf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '8c9f7704-151f-5f98-93e6-89b92bf593bf'::uuid, 1, NULL, TRUE, 0, NULL, E'Insect Concealment', E'The world of species is tricky, in which it is often {{1}} for insects to be exposed, and they have to {{2}} themselves in order to survive. For predators, nothing is less {{3}} than what appears to be a dead prey. This camouflage mechanism only {{4}} effectively when the insect stays completely still, often remaining hidden {{5}} the danger has passed.', NULL, NULL, NULL, E'1.fatal, 2.conceal, 3.appetizing, 4.works, 5.until', NULL, NULL),
  ('8ca270c0-462f-5bfb-b65a-429075872e0c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', '8ca270c0-462f-5bfb-b65a-429075872e0c'::uuid, 1, NULL, TRUE, 0, NULL, E'Engineering of Fish', E'There are adaptations that increase the amount of forward thrust as well as those that reduce drag. Again, these fishes are the envy of engineers. Their high, narrow tails with swept-back tips are almost perfectly adapted to provide propulsion with the least possible effort. Perhaps most important of all to these and other fast swimmers is their ability to sense and make use of swirls and eddies (circular currents) in the water. They can glide past eddies that would slow them down and then gain extra thrust by "pushing off" the eddies. Scientists and engineers are beginning to study this ability of fishes in the hope of designing more efficient propulsion systems for ships.\n\nAccording to the passage, one of the adaptations of fast-swimming fishes that might be used to improve the performance of ships is these fishes'' ability to', NULL, NULL, NULL, E'make efficient use of water currents\ngain speed by pushing off the swirls', NULL, NULL),
  ('8ca54d1e-c3b0-5a0f-93ff-4c4b96e54a4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8ca54d1e-c3b0-5a0f-93ff-4c4b96e54a4b'::uuid, 1, NULL, TRUE, 0, NULL, E'Carbon-capture Tree', E'Due to the growing urgency of the climate crisis, there has been a significant increase in the establishment of commercial tree plantations as a means to counterbalance excessive carbon emissions. However, experts argue that these carbon-offset plantations may have negative impacts on biodiversity and other vital functions of ecosystems.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('8ca8549d-725a-58e4-a2f6-05906c6a56b3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8ca8549d-725a-58e4-a2f6-05906c6a56b3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b265fa8e-1196-5236-bd30-cbda1f854e66'::uuid, NULL, NULL, E'School exams are easy compared with those in universities.', NULL, NULL),
  ('8cafcdce-64ea-5486-a20a-8a0e3e50c417'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8cafcdce-64ea-5486-a20a-8a0e3e50c417'::uuid, 1, NULL, TRUE, 0, NULL, E'Joseph Lister', NULL, '0ab9d094-bce9-51cb-aa48-7f9352558e08'::uuid, NULL, E'Joseph Lister was a great surgeon in Britain who completely transformed the way surgeries are performed. In the 19th century, many patients died after operations due to infections, but Lister changed this tragic reality. He became well known for his groundbreaking work in antiseptic surgery. Inspired by the germ theory, Lister successfully introduced carbolic acid as a powerful disinfectant. He used this chemical to sterilize surgical instruments and to clean wounds before and after operations. This innovative method led to a reduction in infections and significantly made surgery safer for patients all over the world. Because of his great medical achievement, Joseph Lister is often honored as the father of modern surgery. His dedication and scientific approach represent a major achievement in medicine, saving countless lives and laying the foundation for the sterile medical practices we rely on today.', NULL, NULL, NULL),
  ('8cba2418-041f-5619-b73c-433cd6ea7041'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8cba2418-041f-5619-b73c-433cd6ea7041'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd9e8f34b-2878-5ca3-9030-1f1e183fbad6'::uuid, NULL, E'Would you please put the materials on the table?', NULL, NULL, NULL),
