  ('8d59564f-74f8-56a6-a220-3d7f4d5c7a29'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '8d59564f-74f8-56a6-a220-3d7f4d5c7a29'::uuid, 1, NULL, TRUE, 0, NULL, E'Antinuclear Demonstration', E'Police fired tear gas and arrested more than 5,000 passively resisting protesters Friday in an {{1}} to break up the largest antinuclear demonstration ever {{2}} in the United States. More than 135,000 demonstrators confronted police on the construction site of a 1,000-megawatt nuclear power plant {{3}} to provide power to most of southern New Hampshire. Organizers of the huge demonstration said, the protest was {{4}} despite the police actions. More demonstrators were arriving to keep up the pressure on state authorities to cancel the project.', NULL, NULL, NULL, E'1.attempt, 2.staged, 3.scheduled, 4.continuing', NULL, NULL),
  ('8d6044c6-fd33-52bb-a381-24ed8cb08228'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '8d6044c6-fd33-52bb-a381-24ed8cb08228'::uuid, 1, NULL, TRUE, 0, NULL, E'Volunteering', E'One of the best ways to make new friends and strengthen existing relationships is to {{1}} to a shared activity together. Volunteering is a great way to meet new people, especially if you are new to an area. Volunteering can also strengthen your ties to the community and {{2}} your support network, {{3}} you to people with common interests, neighborhood resources, and fun and {{4}} activities.', NULL, NULL, NULL, E'1.commit, 2.broaden, 3.exposing, 4.fulfilling', NULL, NULL),
