  ('8d6ddf60-2db6-5f72-a2fd-103aba384ff6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8d6ddf60-2db6-5f72-a2fd-103aba384ff6'::uuid, 1, NULL, TRUE, 0, NULL, E'Tissues and Organs', E'Tissues are grouped together in the body to form organs. These include the brain, heart, lungs, kidneys, and liver. Each body organ has a specific shape and is made up of different types of tissue that work together. For example, the heart consists mainly of a specialized type of muscle tissue, which contracts rhythmically to provide the heart''s pumping action.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('8d700acc-aeed-5550-bfa7-fb71359ddb0b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8d700acc-aeed-5550-bfa7-fb71359ddb0b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a64391ed-d35b-5072-a458-80bab9c8dae8'::uuid, NULL, E'Advertisements are all around us wherever we go, whatever we do.', NULL, NULL, NULL),
  ('8d70abf3-afc1-59ff-acbb-1b500a5c37d0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '8d70abf3-afc1-59ff-acbb-1b500a5c37d0'::uuid, 1, NULL, TRUE, 0, NULL, E'Avid Readers', E'Victorians were avid readers. Just as we bury our faces in our mobile devices on the morning commute, {{1}} did Victorians with the latest penny fiction. Perhaps the best known serialized novels were the "Penny Dreadfuls". {{2}} just one old penny, they focused on the exploits of detectives, criminals, or supernatural entities. The price of new books — often only available as a set of three — was out of reach for most working-class people, so they borrowed from circulating libraries {{3}} Mudie''s (founded 1842), which dispatched books all over Britain for a modest subscription fee. For the wealthier classes who {{4}} first editions, reading from their own collection would be an everyday occurrence.', NULL, NULL, NULL, E'1.so too, 2.Costing, 3.such as, 4.could afford', NULL, NULL),
  ('8d7c87ec-316f-5bcb-8f9d-d4f25dbefa3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8d7c87ec-316f-5bcb-8f9d-d4f25dbefa3c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What part of the body propels a flying bird in the air?', '5404bf95-8acd-57aa-ac96-eb1fd0d5bc53'::uuid, NULL, NULL, E'Wing', NULL, NULL),
  ('8d7d51b1-2faa-52ec-a2d8-ed505adddead'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8d7d51b1-2faa-52ec-a2d8-ed505adddead'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0282edbe-42fe-5e4c-b742-46dbfdd39952'::uuid, NULL, NULL, E'Weeding is recognized as a fundamental step in the farming process.', NULL, NULL),
  ('8d7e7a78-c12c-5ab1-bdd3-6886e4e04c07'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8d7e7a78-c12c-5ab1-bdd3-6886e4e04c07'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8543a864-3980-59d0-9abc-f364b119def5'::uuid, NULL, NULL, E'Essays and assignments spread out across the academic year.', NULL, NULL),
  ('8d806611-c9b4-5802-8565-8cd3ddafb672'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8d806611-c9b4-5802-8565-8cd3ddafb672'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '670bc87a-76eb-5d54-ab6c-0be12aef43ff'::uuid, NULL, NULL, E'Many of these exchanges followed a predictable pattern.', NULL, NULL),
  ('8d81c606-d41f-5a51-a137-97f5b6e38d4e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8d81c606-d41f-5a51-a137-97f5b6e38d4e'::uuid, 1, NULL, TRUE, 0, NULL, E'The Language of Music', NULL, '3591f716-84e2-5831-9c43-912ee308ab91'::uuid, NULL, E'A painter hangs his or her finished pictures on a wall, and everyone can see it. A composer writes a work, but no one can hear it until it is performed. Professional singers and players have great responsibilities, for the composer is utterly dependent on them. A student of music needs as long and as arduous a training to become a performer as a medical student needs to become a doctor. Most training is concerned with technique, for musicians have to have the muscular proficiency of an athlete or a ballet dancer. Singers practice breathing every day, as their vocal chords would be inadequate without controlled muscular support. String players practice moving the fingers of the left hand up and down, while drawing the bow to and fro with the right arm-two entirely different movements.\nSingers and instruments have to be able to get every note perfectly7 in tune. Pianists are spared this particular anxiety, for the notes are already there, waiting for them, and it is the piano tuner''s responsibility to tune the instrument for them. But they have their own difficulties; the hammers that hit the string have to be coaxed not to sound like percussion, and each overlapping tone has to sound clear.\nThis problem of getting clear texture is one that confronts student conductors: they have to learn to know every note of the music and how it should sound, and they have to aim at controlling these sound with fanatical but selfless authority.\nTechnique is of no use unless it is combined with musical knowledge and understanding. Great artists are those who are so thoroughly at home in the language of music that they can enjoy performing works written in any century.', NULL, NULL, NULL),
  ('8d833468-14e4-55bb-aaaf-561ec46d1814'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8d833468-14e4-55bb-aaaf-561ec46d1814'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e3a56aaa-4cf0-54f8-9155-55c7f8cd0815'::uuid, NULL, E'She will talk on the issues she cares passionately about, including education and nursery care.', NULL, NULL, NULL),
  ('8d88ab75-8cec-51e5-8497-b1038647c25f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '8d88ab75-8cec-51e5-8497-b1038647c25f'::uuid, 1, NULL, TRUE, 0, NULL, E'Health Maintenance', E'What is your opinion on the role of diet in maintaining good health?', NULL, NULL, E'In today''s fast-paced world, the significance of a balanced diet in maintaining good health cannot be overstated. As an advocate for healthy living, I firmly believe that a balanced diet is paramount for overall well-being. It serves as the foundation for a healthy lifestyle, providing the body with essential nutrients to function optimally.\nA balanced diet is critical as it ensures the provision of essential nutrients required for the body''s optimal performance. These nutrients, such as vitamins, minerals, proteins, and carbohydrates, are indispensable for supporting a wide range of bodily functions, from energy generation to immune system upkeep. Inadequate intake of these essential nutrients can impede the body''s ability to function effectively, potentially leading to various health issues and deficiencies.\nFurthermore, the significance of maintaining a balanced diet extends to weight management and the prevention of obesity-related health complications. By incorporating a diverse range of nutrient-dense foods in appropriate portions, individuals can effectively regulate their calorie consumption, facilitating weight control. This not only aids in attaining and maintaining a healthy weight but also diminishes the risk of developing serious conditions like cardiovascular diseases and diabetes.\nIn conclusion, the role of diet in maintaining good health is undeniable. By making informed food choices and prioritizing a diverse and nutritious diet, individuals can pave the way for a healthier and more fulfilling life.', NULL, 200, 300),
  ('8d8a95e6-26b1-5e73-8cfd-e7b4263e10ac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8d8a95e6-26b1-5e73-8cfd-e7b4263e10ac'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a9566c32-23b3-51e5-947d-314eb8fa4f4e'::uuid, NULL, NULL, E'This course section teaches you a new method of creating.', NULL, NULL),
  ('8d8d4538-58b9-56d6-b378-faf0f61e8b04'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8d8d4538-58b9-56d6-b378-faf0f61e8b04'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6351935c-3439-52ab-87ff-03d8dbd21f10'::uuid, NULL, NULL, E'The reception can assist with queries about lending and printing.', NULL, NULL),
  ('8d933e26-d76c-5b75-a881-305c711f5200'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8d933e26-d76c-5b75-a881-305c711f5200'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ce197532-fbbe-5ff2-bfbc-f745065ad563'::uuid, NULL, NULL, E'Measuring personal experience of happiness is easier than you would think.', NULL, NULL),
  ('8d93e565-b469-5be2-a04e-99ce230dc0bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8d93e565-b469-5be2-a04e-99ce230dc0bd'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the opposite of ‘retail’?', 'e795924d-1000-598c-848a-78f511232aeb'::uuid, NULL, NULL, E'Wholesale', NULL, NULL),
  ('8d973332-6b47-5be6-a7d3-9c2ecd3a5a2e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8d973332-6b47-5be6-a7d3-9c2ecd3a5a2e'::uuid, 1, NULL, TRUE, 0, NULL, E'Mobile Phone', E'These days nearly everyone with a mobile phone is able to take photographs or even make a video, but originally cameras were so large and heavy that photography''s appeal as a pastime was limited to a few enthusiasts. Also, the time needed for the exposure meant that your subjects, if you were photographing people, had to remain still for what must have seemed like a very long time. Movement would come out as a blur in the picture or, if someone walked across the view of the lens, would not register at all, which is why early photographs of city streets appear deserted. In other words, all pictures had to be posed. However, as early as the 1880s, manufacturers in both Europe and America began producing miniature models, some of them small enough to be hidden in people''s clothing. Cameras came in all shapes and sizes. Handbags, walking stick handles and tie-pins were among the oddest and were collectively known as "detective cameras". This was not because they were used in police work, but because the user could move about without attracting attention [BEEP)\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '02b81409-5579-5453-934c-91f3ed5e9c5c'::uuid, NULL, NULL, E'as they took pictures', NULL, NULL),
  ('8d99a3bb-6a10-510f-9f27-1a7cac03ed37'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '8d99a3bb-6a10-510f-9f27-1a7cac03ed37'::uuid, 1, NULL, TRUE, 0, NULL, E'Bears', E'Among the biggest threats to all species of bears is habitat loss, especially from logging, agriculture, and growing human populations. Habitat loss {{1}} the amount of area bears have to hunt and means they''re increasingly coming into contact with humans, which can lead to human-wildlife conflict. Bears are killed out of concern for human safety or in {{2}} for hunting livestock or crop-raiding. Some species of bears, including Asiatic black bears and sun bears, are also {{3}} by the illegal wildlife trade. Bear bile, which is produced in the gall bladder, is an important ingredient in traditional Chinese medicine. Asiatic black bears and sun bears may be {{4}} for their gall bladders, paws, skins, and other parts. Sometimes American black bears are also {{5}} for the same reasons. Climate change is also a significant threat, especially to polar bears. They depend on finding seals on sea ice for their meals, and they’ll often pass the summer months without eating while they wait for ice to solidify.', NULL, NULL, NULL, E'1.reduces, 2.retaliation, 3.threatened, 4.poached, 5.targeted', NULL, NULL),
  ('8da4a441-9bb1-5c86-a407-0e6f717a0593'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8da4a441-9bb1-5c86-a407-0e6f717a0593'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ff7df4ca-bb6b-5955-8d33-ef5d0904c225'::uuid, NULL, NULL, E'In addition to psychology, he also teaches chemistry and physics.', NULL, NULL),
  ('8dac353c-ad7d-5dda-a214-645444d22f17'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8dac353c-ad7d-5dda-a214-645444d22f17'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How many planets are in our solar system?', '7cd0a64e-8b2b-5510-8b09-fb897abb561d'::uuid, NULL, NULL, E'Eight', NULL, NULL),
  ('8db0105c-c4d3-5d5c-aca6-66af60095a59'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8db0105c-c4d3-5d5c-aca6-66af60095a59'::uuid, 1, NULL, TRUE, 0, NULL, E'Modern Buildings', E'Modern buildings have to achieve certain performance requirements, at least to satisfy those of building codes, to provide a safe, healthy, and comfortable environment. However, these conditioned environments demand resources in energy and materials, which are both limited in supply, to build and operate.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('8db2daef-cd4a-59c6-9117-f863449432ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '8db2daef-cd4a-59c6-9117-f863449432ca'::uuid, 1, NULL, TRUE, 0, NULL, E'Domesticated Cats', E'One of the biggest milestones in the history of the cat-human relationship has always been their treatment as elevated pets in ancient Egypt. As long as 4,000 years ago, they were not only living alongside humans, but they were cherished by them. For a long time, that’s where we thought it all started, until an excavation in the Chinese village of Quanhuccun revealed a slightly different, much older story.\nAn examination of bones from several cats found in the ancient village revealed something startling, especially considering it wasn’t thought that cats were domesticated in China until about 2,000 years ago. The bones are approximately 5,300 years old, and they tell a story that’s much more complicated than just the life of a wild cat.\nTesting the cats’ bones revealed much more than just the time that they lived, it revealed something about their diet, too. By measuring the isotopes present in the bones, researchers got a feel for what the cats were eating, and part of the finding substantiated what’s largely been thought about how cats and humans first got together. Once humans settled into farming and agricultural communities, they started to store grain and other crops. This, in turn, attracted mice, rats, and other pests. When humans realized that the cats were invaluable at keeping these pests down to a manageable number, a partnership was born and they started wanting to keep the cats around. Suddenly, the cats were no longer pests themselves.', NULL, NULL, NULL, NULL, 5, 75),
  ('8db42613-9da2-58c1-82c1-cc1ae8aeab2c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '8db42613-9da2-58c1-82c1-cc1ae8aeab2c'::uuid, 1, NULL, TRUE, 0, NULL, E'Asking Questions', E'All non-human animals are constrained by the tools that nature has bequeathed them through natural selection. They are not capable of striving towards truth; they simply absorb information, and behave in ways useful for their survival. The kinds of knowledge they require of the world have been largely pre-selected by evolution. No animal is capable of asking questions or generating problems that are irrelevant to its immediate circumstances or its evolutionarily designed needs. When a beaver builds a dam, it doesn''t ask itself why it does so or whether there is a better way of doing it. When a swallow flies south, it doesn''t wonder why it is hotter in Africa or what would happen if it flew still further south. Humans do ask themselves these and many other kinds of questions, questions that have no relevance, indeed make little sense, in the context of evolved needs and goals. What marks out humans is our capacity to go beyond our naturally defined goals such as the need to find food, shelter or a mate and to establish human created goals.', NULL, NULL, E'While all non-human animals are constrained by the tools that nature has bequeathed them through natural selection and never ask questions and generate problems, humans do ask themselves these and many other kinds of questions, questions that have no relevance, indeed make little sense, in the context of evolved needs and goals, which makes humans go beyond naturally defined goals and to establish human-created goals.', NULL, 5, 75),
  ('8db53486-b159-596f-9831-6fa78b35505e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '8db53486-b159-596f-9831-6fa78b35505e'::uuid, 1, NULL, TRUE, 0, NULL, E'Science', NULL, NULL, NULL, NULL, E'2, 1, 4, 3', NULL, NULL),
