  ('8de083f3-47e8-5877-9540-bf919af22db6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8de083f3-47e8-5877-9540-bf919af22db6'::uuid, 1, NULL, TRUE, 0, NULL, E'News Sharing', E'Social media is a powerful tool for making people feel more knowledgeable and may have benefits for people’s mental health. ‘Feeling smart can improve self-esteem,’ commented Dr. Ward. Indeed, studies have shown that news sharing can lead to social learning and political engagement encouraging people to take more active roles in their communities.', NULL, NULL, NULL, NULL, NULL, NULL),
