  ('8de1b525-2a32-5974-baf0-fa34d94b9b06'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8de1b525-2a32-5974-baf0-fa34d94b9b06'::uuid, 1, NULL, TRUE, 0, NULL, E'Marriage Satisfaction', E'Researchers found that couples with higher satisfaction in relationship had greater neural synchronization while watching marriage-related clips, but they don''t know whether there is selection-based behaviors arising from similar brain activity, or whether couples evolve over time to develop it.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('8de57a9b-ff75-5953-848a-dcf84fa709df'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8de57a9b-ff75-5953-848a-dcf84fa709df'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '608402e9-1cca-51d4-b916-50f371af7820'::uuid, NULL, NULL, E'The amount of time spent on configuration varies considerably.', NULL, NULL),
