  ('8e16b172-72c9-512d-bf9d-dd722797af19'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '8e16b172-72c9-512d-bf9d-dd722797af19'::uuid, 1, NULL, TRUE, 0, NULL, E'Values', E'The role of values in society is to {{1}} what is acceptable or unacceptable. Values are part of the societal fabric of a culture, and they can also be expressed individually, {{2}} from the influence of family, education, moral, and religious beliefs. Values are also learned through experiences. Not surprisingly, values can influence consumer perceptions and purchasing behavior. For example, consumers in some countries, such as the United States, tend to be {{3}} and make many purchasing decisions based on their own personal preferences. In other countries, such as Japan, the well-being of the group is more highly valued, and buying decisions are more influenced by the well-being of the group, such as the family. Based on these differences in values, it is not surprising that ads {{4}} individuals tend to do better in countries where individualism is an important value, and ads featuring groups do better in countries where the group’s well-being is a higher value.', NULL, NULL, NULL, E'1.dictate, 2.arising, 3.individualistic, 4.featuring', NULL, NULL),
  ('8e1d17fc-e1e4-5672-950b-79c7c0ac66ce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8e1d17fc-e1e4-5672-950b-79c7c0ac66ce'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '773cd013-6dc7-589c-b198-bfcc9140ed39'::uuid, NULL, NULL, E'The library''s searching system hasn''t been updated since last year.', NULL, NULL),
