  ('8e67974c-bcf9-5e99-8fb4-b71397b4fa03'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8e67974c-bcf9-5e99-8fb4-b71397b4fa03'::uuid, 1, NULL, TRUE, 0, NULL, E'Changing Temperatures', E'Changing temperatures shift the energy balance of ecosystems – from plants that produce energy from sunlight to the animals that consume plants and other animals – subsequently altering the sensory worlds that animals experience. It is likely that climate change will challenge all of their senses, from sight and taste to smell and touch.', NULL, NULL, NULL, NULL, NULL, NULL),
