  ('8e7019e3-713c-5054-af68-18b38ebe1478'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8e7019e3-713c-5054-af68-18b38ebe1478'::uuid, 1, NULL, TRUE, 0, NULL, E'Bad Luck', E'Mathematics and symbolism often play a significant role in superstitions, and the number three is no exception. In many cultures, three is seen as a symbol of balance and completeness. The triangle, with its three sides, represents stability and harmony. The Pythagoreans, an ancient Greek philosophical school, regarded three as the first true number.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('8e710588-5c30-54b0-a7b6-986ba6cb3b05'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8e710588-5c30-54b0-a7b6-986ba6cb3b05'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1e9c25dc-a4a6-5654-9f79-045e352421dc'::uuid, NULL, NULL, E'With the weather changing, farmers are changing how they farm.', NULL, NULL),
  ('8e743b9d-9150-5352-875a-b71b1956dc09'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '8e743b9d-9150-5352-875a-b71b1956dc09'::uuid, 1, NULL, TRUE, 0, NULL, E'Lifelong Employment', E'Businesses should hire employees for their entire lives. Discuss the advantages or disadvantages of this.', NULL, NULL, NULL, NULL, 200, 300),
  ('8e74f1f0-559a-5ba5-b900-9ded0700c023'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '8e74f1f0-559a-5ba5-b900-9ded0700c023'::uuid, 1, NULL, TRUE, 0, NULL, E'Wagonways in Germany', E'Roads of rails called Wagonways were being used in Germany as {{1}} as 1550. These {{2}} railed roads consisted of wooden rails over which horse-drawn wagons or carts moved with greater ease than over dirt roads. Wagonways were the beginnings of modern railroads.\n{{3}} 1776, iron had replaced the wood in the rails and wheels on the carts. Wagonways evolved into Tramways and spread throughout Europe. Horses still provided all the pulling power. In 1789, Englishman, William Jessup designed the first wagons with flanged wheels. The {{4}} was a groove that allowed the wheels to better grip the rail, this was an important design that carried over to later locomotives.', NULL, NULL, NULL, E'1.early, 2.primitive, 3.By, 4.flange', NULL, NULL),
  ('8e7aeb44-cb04-538a-b234-179101427f16'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '8e7aeb44-cb04-538a-b234-179101427f16'::uuid, 1, NULL, TRUE, 0, NULL, E'Pressing Climate Change', E'Climate change is one of the most pressing global {{1}} of our time. The rise in global temperatures, melting ice caps, and extreme weather events are all clear {{2}} of the impact of human activities on the environment. The burning of fossil fuels, deforestation, and industrial emissions have contributed significantly to the increase in greenhouse gases in the atmosphere. Addressing climate change requires {{3}} action at both the individual and governmental levels. Individuals can reduce their carbon footprint by using public transportation, conserving energy, and adopting sustainable practices. Governments, on the other hand, must implement policies to promote renewable energy sources, limit carbon emissions, and invest in climate-resilient infrastructure. One of the most significant challenges in combatting climate change is international {{4}} . Countries around the world must come together to set ambitious targets for reducing emissions and work collaboratively to achieve them. The Paris Agreement, signed by numerous nations, represents a critical step in this direction. In conclusion, climate change poses a severe threat to our planet, but with collective effort and global cooperation, we can mitigate its {{5}} and build a more sustainable future.', NULL, NULL, NULL, E'1.issues, 2.effects, 3.concerted, 4.cooperation, 5.impact', NULL, NULL),
  ('8e7b7503-702b-59bf-bf7d-b021f47d3933'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8e7b7503-702b-59bf-bf7d-b021f47d3933'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '46a22a82-2dbc-5334-8930-c7cdf6164079'::uuid, NULL, NULL, E'The internet has transformed the nature of publishing.', NULL, NULL),
  ('8e7b8681-7d54-5be0-b5dc-30747a3200a1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8e7b8681-7d54-5be0-b5dc-30747a3200a1'::uuid, 1, NULL, TRUE, 0, NULL, E'Economical Cycle', NULL, '39e85d5e-93f1-53f1-86d3-65d0f3d73cc2'::uuid, NULL, E'Today''s economy: materials are extracted, products manufactured, used and thrown away at as low a cost as possible. This cycle is not only polluting, it is unsustainable in a planet with limited resources. But, it can be improved. Have you heard about the circular economy? Products stay in the economy for longer, and at the end of their life they are reused, repaired, remanufactured, upgraded or recycled. Truly creating a circular economy could give a 1.8 trillion Euro boost to the European economy. That''s the same amount as Italy''s entire economy. It would also be good for the environment: reducing the damaging extraction of raw materials, improving air quality by reducing incineration and preventing toxic residues leaking into the soil through landfill waste sites. But what about people? It is estimated that for every 10,000 tonnes of waste: 1 job can be created if that waste is incinerated, 6 jobs if it is landfilled, 36 if it is recycled and 296 if it is reused. Examples from all around Europe show that when people and social enterprises are able to get involved in the circular economy, the social, environmental and financial benefits are enjoyed by all. On 2 December, the European Commission published the circular economy package, which places people at a secondary level. The Greens are calling for a better integration of people''s interests in the circular economy, such as stronger support for citizen''s initiatives and social enterprises and a stronger focus on green job creation. This is why the greens are calling for 5 things to change in the package.', NULL, NULL, NULL),
  ('8e8501f8-0ad9-5355-8a64-7da573d3f906'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8e8501f8-0ad9-5355-8a64-7da573d3f906'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '96da3b17-edbc-5876-aa62-13216b3b6b47'::uuid, NULL, E'The diploma should be the same whether distance learning or on-campus study is employed.', NULL, NULL, NULL),
