  ('8e8f709f-22d5-5027-b758-db81d078914c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '8e8f709f-22d5-5027-b758-db81d078914c'::uuid, 1, NULL, TRUE, 0, NULL, E'Housing Agency', E'Housing agencies pay the utility {{1}} , generally because {{2}} in developments don''t have individual meters. Some buildings have individual meters, and each family {{3}} its own to the utility {{4}} , so agencies will deduct the {{5}} from your {{6}} .', NULL, NULL, NULL, E'1.costs, 2.units, 3.pays, 4.company, 5.amount, 6.rent', NULL, NULL),
  ('8e9abb04-eb63-59a5-9bf3-45287519253a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8e9abb04-eb63-59a5-9bf3-45287519253a'::uuid, 1, NULL, TRUE, 0, NULL, E'War and Commodity', E'In the past, wars have led to inflation and higher commodity prices. Fighting disrupts trade and prevents raw materials from being shipped from one country to another. In second-world-war Britain, a banana was the highest of luxury.', NULL, NULL, NULL, NULL, NULL, NULL),
