  ('8ecd2ef4-fa13-5bfc-896c-66cfc9344c66'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8ecd2ef4-fa13-5bfc-896c-66cfc9344c66'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a990bb0e-6366-549b-ba7f-e18e42998ea8'::uuid, NULL, E'You have to submit the project by the end of the week.', NULL, NULL, NULL),
  ('8ed44fce-42ee-5d60-afef-e58c493e1750'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8ed44fce-42ee-5d60-afef-e58c493e1750'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3030fdad-dd47-55bb-a8c5-d40ab1a63e29'::uuid, NULL, E'Students'' past education and experience are vital.', NULL, NULL, NULL),
  ('8ed824cb-527a-5be4-a3dc-15697ced3d2a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '8ed824cb-527a-5be4-a3dc-15697ced3d2a'::uuid, 1, NULL, TRUE, 0, NULL, E'Hancock Building', E'Hancock Building certainly {{1}} up to its name. The {{2}} is derived from the Latin word "lucere", meaning "to shine", and the artwork''s 3,115 lights {{3}} a scale map of the stars that shine in the night sky. The 13-foot artwork {{4}} thousands of glass bulbs, all fed light through blue illuminating fibre-optic lines. The sculpture, created by English artist Wolfgang Buttress with the help of astrophysicist Dr. Daniel Bayliss, represents a 3D map of all the stars in the Northern Hemisphere that are able to be visible with the naked eye.', NULL, NULL, NULL, E'1.lives, 2.title, 3.depict, 4.comprises', NULL, NULL),
