  ('8ee0f5e6-f39f-5dc8-8acc-d416243f6eaf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8ee0f5e6-f39f-5dc8-8acc-d416243f6eaf'::uuid, 1, NULL, TRUE, 0, NULL, E'Time Zone', E'It''s strange to think that time zones were invented as a way of reducing confusion rather than causing it. Since solar time varies as you move even a short distance from one spot to another across the planet, for most of human history, the time of day varied everywhere.', NULL, NULL, NULL, NULL, NULL, NULL),
