  ('8eef0246-6e58-517f-a1dc-edd77fb32686'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8eef0246-6e58-517f-a1dc-edd77fb32686'::uuid, 1, NULL, TRUE, 0, NULL, E'Solid Waste Management', E'The solid waste management issue is the biggest challenge to the authorities of both small and large cities’ in developing countries. This is mainly due to the increasing generation of such solid waste and the burden posed on the municipal budget. In addition to the high costs, the solid waste management is associated with lack of understanding over different factors that affect the entire handling system.', NULL, NULL, NULL, NULL, NULL, NULL),
