  ('8f32aa66-2bf9-5419-8584-1339d4c05398'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8f32aa66-2bf9-5419-8584-1339d4c05398'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a group of lions?', '598ee3ef-c3e8-5c35-95bc-698baa1a9388'::uuid, NULL, NULL, E'A pride', NULL, NULL),
  ('8f3585dd-2718-506c-b083-500801d60a94'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8f3585dd-2718-506c-b083-500801d60a94'::uuid, 1, NULL, TRUE, 0, NULL, E'Cryptocurrency Mining', E'Amid the global water crisis, the process of cryptocurrency mining has been found to consume a substantial amount of water, with predictions of an even greater demand in the future. A recent study has provided the first extensive calculation of the amount of water used by Bitcoin. The researcher has expressed concern over the potential impact on drinking water if this practice continues without proper regulation.', NULL, NULL, NULL, NULL, NULL, NULL),
