  ('8f4b5406-60d5-5e4c-9d41-4c63198ddd59'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8f4b5406-60d5-5e4c-9d41-4c63198ddd59'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the vehicle that runs on rails and is commonly used for urban public transport?', 'd39df14b-0af6-5bcd-8640-cc4d57ae4750'::uuid, NULL, NULL, E'Tram', NULL, NULL),
  ('8f50ec24-d444-5744-9733-75862cfe4afb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8f50ec24-d444-5744-9733-75862cfe4afb'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'db6f2631-6302-5cd2-88d0-3cd3e2c3fa62'::uuid, NULL, NULL, E'It is a debate about the knowledge of values.', NULL, NULL),
  ('8f5413db-a4d5-5a92-a079-c97a109efdfa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '8f5413db-a4d5-5a92-a079-c97a109efdfa'::uuid, 1, NULL, TRUE, 0, NULL, E'Global Supply Chains', E'Today’s globally {{1}} economy makes it necessary for businesses to look as far as possible for both the cheapest and the best resources. The benefit of global supply chains is that businesses can take {{2}} of low-cost goods and services in foreign locations to bring down operating costs. However, when a business depends on outsourcing, it increases the number of risk factors outside of its control. Tsunamis in Japan shut down an auto assembly plant in Ohio when essential parts couldn’t be shipped; severe flooding in Thailand {{3}} the manufacture of computers for the US market when hard drives failed to appear. Ethical considerations can also be a factor. Even when a firm tries to ensure that the factory owners it contracts with provide fair wages and safe working conditions, {{4}} still occur, and responsibility is hard to assess. A series of factory fires and disasters killed hundreds of workers in Bangladesh in 2013 and led to the Disney Company canceling the production of its licensed products in that country.', NULL, NULL, NULL, E'1.integrated, 2.advantage, 3.delayed, 4.abuses', NULL, NULL),
  ('8f5f72ca-8e0a-5f01-b276-f456c117355e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8f5f72ca-8e0a-5f01-b276-f456c117355e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8c39c3bf-22a6-5843-b929-8943e17d1068'::uuid, NULL, NULL, E'This book can be borrowed for a maximum of one week.', NULL, NULL),
  ('8f728f75-c04e-5d0e-95c2-666d5c0cd6d1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8f728f75-c04e-5d0e-95c2-666d5c0cd6d1'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '59f7c82a-c73a-589b-b121-7a5593e7e449'::uuid, NULL, E'A demonstrated ability to write clear, correct and concise English is obligatory.', NULL, NULL, NULL),
  ('8f77b30f-37ea-5da7-8316-94c9819a2e15'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '8f77b30f-37ea-5da7-8316-94c9819a2e15'::uuid, 1, NULL, TRUE, 0, NULL, E'Air Travel', E'Some people think air travel has more negative impacts than positive impacts on modern life. What do you think?', NULL, NULL, NULL, NULL, 200, 300),
  ('8f7aed80-4569-594b-bc8c-0add6010340b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8f7aed80-4569-594b-bc8c-0add6010340b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4c78a874-2232-55bb-82f6-c0fae021e356'::uuid, NULL, E'Hypothetically, insufficient mastery in the areas slows future progress.', NULL, NULL, NULL),
  ('8f800950-93d2-570c-a0e4-4ea71066f068'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8f800950-93d2-570c-a0e4-4ea71066f068'::uuid, 1, NULL, TRUE, 0, NULL, E'Sensory Information', E'When you’re scared, your body will typically try to take in more sensory information. So your face will open up as you breathe more deeply and scan the environment with your eyes. On the other hand, when you’re disgusted, you’ll generally reject sensory information.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('8f801fb3-4b80-5f55-8741-5b1360beb260'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8f801fb3-4b80-5f55-8741-5b1360beb260'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What would be the opposite of compulsory service?', 'fffa2066-3b74-5849-9c0d-c862e47b8871'::uuid, NULL, NULL, E'Voluntary service', NULL, NULL),
  ('8f828a6d-1df6-538b-aaa5-f9617ace1ae6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '8f828a6d-1df6-538b-aaa5-f9617ace1ae6'::uuid, 1, NULL, TRUE, 0, NULL, E'AI', E'We''re entering a new era of healthcare. AI can sift through vast amounts of data and knowledge in a way that''s not possible for a human brain. Already, IBM''s supercomputer Watson can draw on troves of data and patient records to provide personalized recommendations on treatment in seconds.\nA robot-scientist developed by Ross King, professor of machine intelligence at the University of Manchester, can screen over 10,000 compounds a day in the search for new drugs to beat tropical diseases. Professor King predicts, "Biological systems are so complex that humans cannot understand them without help from computers. I believe that most diseases will be treatable, if not cured, in the next 50–100 years."\nSmart technology will also give us more personalized, democratic health systems. "AI will make healthcare unrecognizable in the next ten years," declares British-based engineer and entrepreneur Dr Ali Parsa. For £7.99 a month, his smartphone app Babylon enables subscribers to text simple queries and have virtual consultations. Users can add fitness monitors and if they show stress and high blood pressure, for instance, a doctor can proactively make contact.\n"I don’t believe AI will replace doctors," says Dr Parsa, "but it can play a crucial role in assisting with simpler queries, giving doctors more time to focus on complex conditions and patients that need a greater level of care."', NULL, NULL, NULL, NULL, 5, 75),
  ('8f83f086-db91-5ab1-a3de-de498d9725b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8f83f086-db91-5ab1-a3de-de498d9725b2'::uuid, 1, NULL, TRUE, 0, NULL, E'Unconscious and Intuition', E'When buying a house, for example, it''s best to let our unconscious mull over the many variables. But when we''re picking stocks and shares, intuition often leads us astray. The trick is to determine when to lean on which part of the brain. And to do this, we need to think harder and smarter about how we think.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('8f856039-79db-5ff8-b1be-5b3ae79463c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8f856039-79db-5ff8-b1be-5b3ae79463c8'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'eddf516c-37cc-5e5b-b3e8-16c4de5093fa'::uuid, NULL, NULL, E'Summer school programs provide a fast track for student learning.', NULL, NULL),
  ('8f87a918-d1c6-5247-9c69-d316b3a399ef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '8f87a918-d1c6-5247-9c69-d316b3a399ef'::uuid, 1, NULL, TRUE, 0, NULL, E'Transportation Networks', E'With cities expanding, governments should look forward to creating better networks of public transport available for everyone rather than building more roads for vehicle owning population. To what extent do you agree or disagree?', NULL, NULL, E'In the modern era, the debate over whether governments should prioritize building more roads for the vehicle-owning population has garnered significant attention. While some advocate for alternate modes of transportation, I firmly believe that expanding road infrastructure remains a crucial endeavor for the betterment of society.\nThe primary reason to support this stance is the enhancement of personal mobility and convenience. As cities expand and populations grow, efficient transportation becomes paramount. Expanding road networks offers vehicle owners improved accessibility and reduced commute times, contributing to an overall improvement in their quality of life. The renowned American scientist Einstein once stated, "Life is like riding a bicycle. To keep your balance, you must keep moving." This sentiment underscores the importance of efficient transportation systems in maintaining the equilibrium of daily life.\nAdditionally, the economic implications of road expansion cannot be overlooked. Developed road networks facilitate the movement of goods and services, bolstering local and national economies. This economic growth leads to job creation and increased business opportunities, further benefiting both vehicle owners and the general populace. Such benefits align with the broader societal objective of fostering economic prosperity and stability.\nIn conclusion, the perspective that governments should prioritize building more roads for the vehicle-owning population is well-founded. Improved road infrastructure directly enhances personal mobility, convenience, and economic growth. By committing to this approach, governments can provide citizens with essential services, improve the flow of goods and services, and contribute to the overall advancement of society.', NULL, 200, 300),
  ('8f91f47e-af1d-5079-a98d-ec9e56580d76'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8f91f47e-af1d-5079-a98d-ec9e56580d76'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the system responsible for circulating blood and lymph throughout the body?', '6b91bd16-2406-501b-8020-74364242520d'::uuid, NULL, NULL, E'Cardiovascular system', NULL, NULL),
  ('8f922bc0-7691-5e0b-afb2-40b810ca6274'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '8f922bc0-7691-5e0b-afb2-40b810ca6274'::uuid, 1, NULL, TRUE, 0, NULL, E'Jean Piaget', E'Jean Piaget, the pioneering Swiss philosopher and psychologist, spent much of his professional life listening to children, watching children and poring {{1}} reports of researchers around the world who were doing the same. He found, to put it most succinctly ,that children don''t think like grownups. After thousands of interactions with young people often barely old enough to talk, Piaget began to {{2}} that behind their cute and seemingly illogical {{3}} were thought processes that had their own kind of order and their own special logic. Einstein called it a {{4}} "so simple that only a genius could have thought of it." Piaget''s insight opened a new window into the inner workings of the mind. By the end of a wide-ranging and remarkably {{5}} research career that spanned nearly 75 years, from his first scientific publication at age 10 to work still in progress when he died at 84, Piaget had developed several new fields of science: developmental psychology, cognitive theory and what came to be called genetic epistemology. Although not an educational reformer, he {{6}} a way of thinking about children that provided the foundation for today’s education-reform {{7}} . It was a shift comparable to the displacement of stories of "noble savages" and "cannibals" by modern anthropology. One might say that Piaget was the first to take children''s thinking seriously.', NULL, NULL, NULL, E'1.over, 2.suspect, 3.utterances, 4.discovery, 5.prolific, 6.fashioned, 7.movements', NULL, NULL),
  ('8f95d84c-2bf0-53c6-b896-9d7b1d42a899'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8f95d84c-2bf0-53c6-b896-9d7b1d42a899'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4e964a75-e941-5f37-92d3-cea4beec9088'::uuid, NULL, NULL, E'It''s good for students to check their own attendance.', NULL, NULL),
  ('8fa48822-4c91-54a9-aa2d-50da254b609c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '8fa48822-4c91-54a9-aa2d-50da254b609c'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-R', E'Even as the number of females processed through juvenile courts climbs steadily, an implicit consensus remains among scholars in criminal justice that male adolescents define the delinquency problem in the United States. We suggest two reasons why this view persists. First, female adolescents are accused primarily of victimless crimes, such as truancy, that do not involve clear-cut damage to persons or property. If committed by adults, these actions are not even considered prosecutable; if committed by juvenile males, they have traditionally been looked on leniently by the courts. Thus, ironically, the plight of female delinquents receives little scrutiny because they are accused of committing relatively minor offenses. Second, the courts have long justified so-called preventive intervention into the lives of young females viewed as antisocial with the rationale that women are especially vulnerable. Traditional stereotypes of women as the weaker and more dependent sex have led to earlier intervention and longer periods of misdirected supervision for female delinquents than for males.\n\nThe passage suggests that scholars in criminal justice could be criticized for which of the following?', NULL, NULL, NULL, E'Focusing on those whose crimes have involved damage to persons or property', NULL, NULL),
  ('8fadf0d5-ec2c-55e0-a41c-4ddfaae5e82c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8fadf0d5-ec2c-55e0-a41c-4ddfaae5e82c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6c8591f1-1866-57b1-91a7-643c09169d87'::uuid, NULL, NULL, E'A thin cable can carry the signal to a computer.', NULL, NULL),
