  ('8fc136ea-e79b-5397-86e8-01a46a1f9890'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8fc136ea-e79b-5397-86e8-01a46a1f9890'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a084f38f-137c-5cb3-9ae2-cb263ecbfec8'::uuid, NULL, E'Critics want the government to take this one stage further and ban the film altogether.', NULL, NULL, NULL),
  ('8fc1c96f-b4f9-584e-8bca-f8457f6ae231'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8fc1c96f-b4f9-584e-8bca-f8457f6ae231'::uuid, 1, NULL, TRUE, 0, NULL, E'The Spanish Language', E'The Spanish language has a rich and complicated history. It has navigated the rise and fall of great empires, has been a symbol of cultural identity, and has both been used as a tool of unity and caused considerable divisiveness. Today, it is the world’s second-most spoken native language and is used by people in all corners of the globe.', NULL, NULL, NULL, NULL, NULL, NULL),
