  ('8fd050d1-55c6-5c3a-80cc-4f788e28310a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8fd050d1-55c6-5c3a-80cc-4f788e28310a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9f18e433-2e83-5254-b333-a79b232df588'::uuid, NULL, NULL, E'You can make an appointment to meet the librarian.', NULL, NULL),
  ('8fd08ec1-1759-5bc2-b4a4-fd768a084b6d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8fd08ec1-1759-5bc2-b4a4-fd768a084b6d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f64ab7d5-02d3-58d5-8b99-ef9ca8561255'::uuid, NULL, NULL, E'There may be financial concerns in the research, for example, funding considerations.', NULL, NULL),
  ('8fd10200-21d6-544c-8d07-039e38fde399'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '8fd10200-21d6-544c-8d07-039e38fde399'::uuid, 1, NULL, TRUE, 0, NULL, E'Sportswomen', E'Sportswomen''s records are important and need to be preserved. And if the paper records don''t {{1}} , we need to get out and start interviewing people, not to put too fine a {{2}} on it, while we still have a {{3}} . After all, if the records aren''t kept in some form or another, then the stories are {{4}} too.', NULL, NULL, NULL, E'1.exist, 2.point, 3.chance, 4.lost', NULL, NULL),
  ('8fd63d71-108a-5d92-ae4d-8f0521bc09b3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '8fd63d71-108a-5d92-ae4d-8f0521bc09b3'::uuid, 1, NULL, TRUE, 0, NULL, E'Helping Others', E'There are many different ways to help other people. Perhaps the most common of these involves giving others {{1}} help. In our society, there are many individuals who spontaneously help others in this way. Additionally, there are others who belong to organisations which have been set up to provide help to specific groups, such as the elderly, the disabled, and those with serious physical or {{2}} health problems. Most importantly, there are many {{3}} ,such as nursing, occupational therapy and social work, which involve professionals who are trained to provide or organise practical help for others. And, {{4}} helping other people in a practical way, many volunteer and professional helpers also make use of some counselling skills. These skills can be very useful in enabling people to feel better as described in this book and our book, Counselling Skills in Everyday Life. However, it needs to be {{5}} that just being able to make use of some counselling skills does not qualify a person as a counsellor.', NULL, NULL, NULL, E'1.practical, 2.mental, 3.occupations, 4.while, 5.recognized', NULL, NULL),
  ('8fd95dce-af16-5ed9-8cec-ab4658ffb078'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8fd95dce-af16-5ed9-8cec-ab4658ffb078'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6a7979ae-9cbf-5333-8839-f103beab7539'::uuid, NULL, E'You must be willing to accept any of the choices you selected.', NULL, NULL, NULL),
  ('8fda9959-4ac9-58d8-a000-aaf8293b0f3a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '8fda9959-4ac9-58d8-a000-aaf8293b0f3a'::uuid, 1, NULL, TRUE, 0, NULL, E'Chess experts and Novices', E'In a study conducted in Tubingen, Germany, chess experts and novices were shown geometric objects and chess positions and were later asked to identify each one of them. Their reaction times and brain activity closely monitored with the use of functional MRI scans. On the first part, which was recognizing the geometric objects, results reveal that the subjects’ performance didn’t show any dissimilarities, which implied that the experts’ visualization skills are no better than the amateurs’. However, during the identification of the chess position, the experts were seen to have performance significantly faster and better.\nAs the researchers geared toward an element of a study previously conducted on pattern and object recognition by the chess experts, they had anticipated to notice areas of the left hemisphere of the experts’ brains (involved in object recognition) to be more reactive when they performed the tasks. However, the reaction times of the subjects were virtually identical. The very thing that sets the experts apart from the amateurs is that the former’s right brain hemispheres (involved in pattern recognition) were to seen to have also lit up during the activity. Therefore, both sides of the experts’ brains were active, processing information in two places simultaneously. The researchers added that when they showed the chess diagrams to the subjects, they observed that the amateur relied on looking at the pieces intently to be able to recognize them, whereas the experts merely relied on their peripheral vision and looked across the boards.', NULL, NULL, E'According to a study, chess experts'' visualization skills are no better than the amateurs but their performance on the identification of the chess position is much faster and better because both sides of the experts'' brains are active during the activity, processing information in two places simultaneously.', NULL, 5, 75),
  ('8fe2b961-ee27-539f-ac2b-324b090fb924'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '8fe2b961-ee27-539f-ac2b-324b090fb924'::uuid, 1, NULL, TRUE, 0, NULL, E'Mistake in Report', E'There was a mistake in the report you gave your manager last night. You hope he hasn''t seen it yet, so you call him today to explain what happened.\nWhat would you say?', '8849b589-8d50-50d9-98e6-6afca1292c7f'::uuid, NULL, NULL, NULL, NULL, NULL),
  ('8fe3eddd-deb3-5b23-b912-05ec13f2e037'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8fe3eddd-deb3-5b23-b912-05ec13f2e037'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '04d3eea0-e05b-5d19-a82f-53be1ec59f40'::uuid, NULL, NULL, E'Knowing the library''s use can significantly reduce your research time.', NULL, NULL),
  ('8fe78983-d7d3-5273-acda-d0589322ea33'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '8fe78983-d7d3-5273-acda-d0589322ea33'::uuid, 1, NULL, TRUE, 0, NULL, E'Art Career', E'Before you undertake a career in the arts. There are a number of factors to consider whether your goal is to be an actor or an animator, a saxophone, a store, a sculptor. Talent is an essential consideration, but talent alone won''t guarantee a successful career in the arts. You also need training experience and self discipline. Most importantly, however, you should realize that a career in the arts requires a personal sense of commitment, a calling, because art does have a history of insecure employment. A lot of artists find it difficult, even impossible to live on the money they make from their art. Most have to supplement their income by teaching or by working behind the scenes or by doing other work not related to the arts. In your opinion, what''s the best way for us to know if we really have a calling to art? Well, those of you who are interested in art as a career should talk with arts professionals or work in the arts yourselves. Professionals can give good first hand advice, but experience is the best way to get a feel for the field.\n\nAccording to the professor, what factors are important in choosing a career in the arts?', '30aa59a7-26af-5d05-9ea5-0c0fbe1a3723'::uuid, NULL, NULL, E'Talent\nExperience', NULL, NULL),
