  ('905d32c6-9b9c-5e8a-ab64-861ea1787176'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '905d32c6-9b9c-5e8a-ab64-861ea1787176'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a 12-month accounting period used by governments, companies, and organizations for financial reporting and budgeting purposes?', '33d2ee4f-14a5-5043-89dc-fc0cede84284'::uuid, NULL, NULL, E'Fiscal year', NULL, NULL),
  ('9064289f-f54e-595f-97c6-ef75a9fc355f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9064289f-f54e-595f-97c6-ef75a9fc355f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for the main circuit board in a computer?', '8d80bbe7-ddca-5ae2-acc2-60f1d166e9eb'::uuid, NULL, NULL, E'Motherboard', NULL, NULL),
  ('9066df12-7132-5559-a185-4276ddc1170c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '9066df12-7132-5559-a185-4276ddc1170c'::uuid, 1, NULL, TRUE, 0, NULL, E'Banksy', E'Banksy, the enigmatic street artist, combined sharp political commentary with dark humor, quickly gaining public {{1}} . Despite his growing fame, he maintained anonymity, challenging the commercial art scene with his guerrilla tactics. His art, which frequently mocked societal {{2}} ,rose in popularity, but he still questioned art''s commodification by performing satirical stunts, such as {{3}} up a painting at auction, thus {{4}} public discourse on the intersection of art, fame, and value.', NULL, NULL, NULL, E'1.attention, 2.norms, 3.tearing, 4.reshaping', NULL, NULL),
  ('9067b97e-3067-51c0-9d5c-7907ebf185a1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '9067b97e-3067-51c0-9d5c-7907ebf185a1'::uuid, 1, NULL, TRUE, 0, NULL, E'Banking', E'The first banks were probably the religious temples of the ancient world, and were probably established sometime during the third millennium B.C. Banks probably {{1}} the invention of money. Deposits initially consisted of grain and later other goods including cattle, agricultural implements, and eventually precious {{2}} such as gold, in the form of easy-to-carry compressed plates. Temples and palaces were the safest places to store gold as they were constantly attended and well {{3}} . As sacred places, temples presented an extra {{4}} to {{5}} thieves.', NULL, NULL, NULL, E'1.predated, 2.metals, 3.built, 4.deterrent, 5.would-be', NULL, NULL),
  ('906c43a3-566c-59d6-82ea-95e2c36b2e56'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '906c43a3-566c-59d6-82ea-95e2c36b2e56'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'At what ceremony do students receive their degree or diploma at the end of their period of study?', '9ddf69f8-85ad-599b-909f-04a8ff4b6f56'::uuid, NULL, NULL, E'Graduation / commencement', NULL, NULL),
  ('9078c78d-5c19-5b69-a393-68161145e3d0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9078c78d-5c19-5b69-a393-68161145e3d0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '50bbfc66-90e1-5f23-ac8a-6c4cc8f64373'::uuid, NULL, E'Researchers hold differing opinions on the reasons for our dreams.', NULL, NULL, NULL),
  ('907cec32-aac8-5799-b3b5-3e1a36541ec3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '907cec32-aac8-5799-b3b5-3e1a36541ec3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6ca376ee-7696-5063-be05-c5557b7bf5de'::uuid, NULL, NULL, E'Classical mechanics is sometimes considered as a branch of applied mathematics.', NULL, NULL),
  ('9085bd0a-88f2-5a4a-9165-fd800356af92'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '9085bd0a-88f2-5a4a-9165-fd800356af92'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-R', E'Until the 1600s, English was, for the most part, spoken only in England. However, during the course of the next two centuries, English began to spread around the globe as a result of exploration, trade, colonization, and missionary work. English gradually became the primary language of international business, banking, and diplomacy. Currently, more than 80 percent of the information stored on computer systems worldwide is in English. Two thirds of the world’s science writing is in English, and English is the main language of technology, advertising, media, international airports, and air traffic controllers. Today there are more than 700 million English users in the world, and over half of these are non-native speakers, constituting the largest number of non-native users of any language in the world.\n\nWhich of the following most accurately summarizes the opinion of the author in the text?', NULL, NULL, NULL, E'English has become the dominant language of international communication.', NULL, NULL),
  ('9088abb2-6f36-5af7-8917-1f9ebaf9f9ef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9088abb2-6f36-5af7-8917-1f9ebaf9f9ef'::uuid, 1, NULL, TRUE, 0, NULL, E'Circadian Rhythm', E'An internal “body clock” regulates your sleep cycle, controlling when you feel tired and ready for bed or refreshed and alert. This clock operates on a 24-hour cycle known as the circadian rhythm. After waking up from sleep, you’ll become increasingly tired throughout the day. These feelings will peak in the evening leading up to bedtime.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('908a3930-20ef-589a-bdd8-aaf40998160e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '908a3930-20ef-589a-bdd8-aaf40998160e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2c84c914-214b-5923-bee9-fbd35d450e2b'::uuid, NULL, NULL, E'They are now making plans to form their own separate group.', NULL, NULL),
  ('908b1af4-4194-58e0-8c20-e70d5fe927d0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '908b1af4-4194-58e0-8c20-e70d5fe927d0'::uuid, 1, NULL, TRUE, 0, NULL, E'Pendulum Clock', E'One of Guinness World Records'' more unusual awards was presented at the National Maritime Museum yesterday. After a 100-day trial, the timepiece known as Clock B — which had been sealed in a clear plastic box to prevent tampering — was officially declared, by Guinness, to be the world''s "most accurate mechanical clock with a pendulum swinging in free air". It was an intriguing enough award. But what is really astonishing is that the clock was designed more than 250 years ago by a man who was derided at the time for "an incoherence and absurdity that was little short of the symptoms of insanity", and whose plans for the clock lay ignored for two centuries. The derision was poured on John Harrison, the British clockmaker whose marine chronometers had revolutionized seafaring in the 18th century (and who was the subject of Longitude by Dava Sobel). His subsequent claim — that he would go on to make a pendulum timepiece that was accurate to within a second over a 100-day period — triggered widespread ridicule. The task was simply impossible, it was declared. But now the last laugh lies with Harrison. At a conference, Harrison Decoded: Towards a Perfect Pendulum Clock, held at Greenwich yesterday, observatory scientists revealed that a clock that had been built to the clockmaker''s exact specifications had run for 100 days during official tests and had lost only five-eighths of a second in that period.', NULL, NULL, E'John Harrison, the British clockmaker claimed that he would go on to make a pendulum timepiece that was accurate to within a second over a 100-day period, which triggered widespread ridicule, but now the last laugh lies with Harrison as Clock B, which was designed more than 250 years ago, and was officially declared, by Guinness, to be the world''s "most accurate mechanical clock with a pendulum swinging in free air".', NULL, 5, 75),
  ('908c6b29-99a2-53d2-8d6c-b12227336a4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '908c6b29-99a2-53d2-8d6c-b12227336a4b'::uuid, 1, NULL, TRUE, 0, NULL, E'Snakes(蛇)', NULL, NULL, NULL, NULL, E'3, 4, 1, 2', NULL, NULL),
  ('908ddf61-833b-5da5-b559-a7f61935b69a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '908ddf61-833b-5da5-b559-a7f61935b69a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e89d25db-b0cd-5d07-8b93-936f13eb67ab'::uuid, NULL, NULL, E'Many governments are struggling with their countries'' high populations.', NULL, NULL),
  ('909523d1-fd67-5bcc-8a26-c0e74bee0387'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '909523d1-fd67-5bcc-8a26-c0e74bee0387'::uuid, 1, NULL, TRUE, 0, NULL, E'Away from Home', E'For many first-year students, the University may be their first {{1}} living away from home for an extended period of time. It is a {{2}} break from home. The individual''s usual {{3}} of support are no longer present to {{4}} adjustment to the unfamiliar environment.', NULL, NULL, NULL, E'1.experience, 2.definite, 3.sources, 4.facilitate', NULL, NULL),
  ('909e0f93-7504-585d-be3f-b7eb21579055'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '909e0f93-7504-585d-be3f-b7eb21579055'::uuid, 1, NULL, TRUE, 0, NULL, E'Slow Travel', NULL, NULL, NULL, NULL, E'2, 3, 1, 4', NULL, NULL),
  ('90a06486-d408-5d50-b1af-556e9715afa6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '90a06486-d408-5d50-b1af-556e9715afa6'::uuid, 1, NULL, TRUE, 0, NULL, E'Global and Local', E'What is your opinion on the impact of globalization on local cultures?', NULL, NULL, E'Globalization, in its essence, serves as a bridge that connects the world''s diverse cultures, fostering mutual understanding and collaboration. In my view, globalization has a profoundly positive impact on local cultures, enriching them through cultural exchange, economic growth, and technological advancement.\nGlobalization acts as a powerful force that transcends geographical boundaries, allowing for the seamless flow of ideas, beliefs, and practices between different cultures. This exchange of cultural elements not only enriches societies with a vibrant tapestry of traditions and perspectives but also fosters a sense of unity and interconnectedness among people from diverse backgrounds. Through this cultural fusion, individuals gain a deeper appreciation for the diversity that exists in the world, promoting mutual respect and understanding.\nMoreover, the global exchange of technological advancements and best practices transcends borders, igniting innovation and progress in various industries. By sharing knowledge and expertise internationally, globalization paves the way for transformative developments, increased efficiency, and enhanced competitiveness in local economies. This collaborative approach fosters a dynamic environment where industries can thrive and communities can benefit from the advancements of the global marketplace.\nIn conclusion, the positive impact of globalization on local cultures cannot be understated. By promoting cultural exchange, driving economic growth, and facilitating technological innovation, globalization contributes to the vibrancy and resilience of local communities. Embracing the opportunities presented by globalization while preserving the unique identities of local cultures is essential in harnessing the full potential of this global phenomenon.', NULL, 200, 300),
  ('90a0e36e-e6ec-55fb-96c9-8de6ee76343a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '90a0e36e-e6ec-55fb-96c9-8de6ee76343a'::uuid, 1, NULL, TRUE, 0, NULL, E'Is Math Real', E'Math has a reputation for supplying concise, black-or-white answers to questions. Getting straightforward math questions right or wrong is often presented as the litmus test of whether someone has mathematical ability. But that view of math is simplistic. Rather than a tool for obtaining objective right answers, math is a method for asking questions and exploring the possibilities those questions raise.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('90a9e009-fb8d-5b54-b768-8983ed14d9b6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '90a9e009-fb8d-5b54-b768-8983ed14d9b6'::uuid, 1, NULL, TRUE, 0, NULL, E'Beauty Contests', E'Beauty contests, whether it''s Miss Universe or Miss Teen International, are demeaning to women and out of sync with the times. Opponents say that they are nothing more than symbols of decline. Since Australians Jennifer Hawkins and Lauryn Eagle were crowned Miss Universe and Miss Teen International respectively, there has been a dramatic increase in interest in beauty pageants in this country.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('90a9e737-840c-5c72-9362-08fe1b233da3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '90a9e737-840c-5c72-9362-08fe1b233da3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'bd3b9605-c7de-5231-9818-73a5ef7885de'::uuid, NULL, NULL, E'Applications should be in the form of a signed document.', NULL, NULL),
  ('90ae56d2-5b49-5e3b-9555-ec5e3def8a80'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '90ae56d2-5b49-5e3b-9555-ec5e3def8a80'::uuid, 1, NULL, TRUE, 0, NULL, E'Scientists', E'Scientists make observations, have assumptions, and do experiments. After these have been done, they get their results. Then there is a lot of data from scientists. The scientists around the world have a picture of the world.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('90ba4d8d-1456-5bf3-bde2-46950a7bd2a1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '90ba4d8d-1456-5bf3-bde2-46950a7bd2a1'::uuid, 1, NULL, TRUE, 0, NULL, E'Coconut Crabs', E'Coconut crabs spend most of their lives on land, but they start out in the ocean. On the new moon, a female coconut crab {{1}} larvae (which she''s been carrying around in her abdomen since they were just fertilized eggs) into the ocean, and the babies {{2}} around in the currents for a month or so before dropping to the seafloor and finding nice, cozy snail shells to move into. Just like your childhood hermit crab friend, young coconut crabs move in and out of shells as they {{3}} up and get used to living on land. Sometimes a juvenile coconut crab will use a coconut husk or empty sea shell as {{4}} until its own shell gets harder. After about a year, the teens of the species eventually find there are no shells left on the beach large enough to {{5}} their bulk, so they move out altogether. From here on out, they live the rest of their lives out of the water — coconut crabs will drown if totally submerged.', NULL, NULL, NULL, E'1.deposits, 2.float, 3.bulk, 4.armor, 5.accommodate', NULL, NULL),
  ('90ba577f-4131-5f87-abd9-0be7f8db25d9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '90ba577f-4131-5f87-abd9-0be7f8db25d9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b4434a44-79f2-5c2a-ab2e-e0224848c0cb'::uuid, NULL, E'It''s a great place for swimming, but beware dangerous currents.', NULL, NULL, NULL),
