  ('921a2d8e-d83a-5cf6-9a8e-952929ab85d4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '921a2d8e-d83a-5cf6-9a8e-952929ab85d4'::uuid, 1, NULL, TRUE, 0, NULL, E'Summerhill School', E'Summerhill School was regarded with considerable suspicion by the educational establishment. Lessons were optional for pupils at the school, and the government of the school was carried out by a School Council, of which all the pupils and staff were members, with everyone having equal voting rights.', NULL, NULL, NULL, NULL, NULL, NULL),
