  ('92f75cf1-2b5f-5bb8-a83c-c5d65ff2f1de'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '92f75cf1-2b5f-5bb8-a83c-c5d65ff2f1de'::uuid, 1, NULL, TRUE, 0, NULL, E'Leadership Communication', E'Leadership communication styles can be divided into two types: tell-and-sell and ask-and-listen. The former involves communicating a clear vision and persuading subordinates to follow it, while the {{1}} involves seeking input and {{2}} from subordinates to create a shared goal. Both styles can be effective, but they require different skills and situations. According to a recent paper by German psychologists Niels van Quaquebeke and Fabiola Gerpott, effective leaders need to be flexible in their communication styles, using each according to the desired {{3}} . The tell-and-sell approach works well when leaders have a charismatic personality and a strong sense of direction, {{4}} the ask-and-listen approach works well when leaders need creative solutions and have subordinates with sufficient expertise. By adapting their communication style to the situation, leaders can engage their subordinates and achieve their goals more effectively.', NULL, NULL, NULL, E'1.latter, 2.feedback, 3.outcome, 4.while', NULL, NULL),
  ('92fa4eb8-495b-5086-9266-ef31f0071ed3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '92fa4eb8-495b-5086-9266-ef31f0071ed3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '76d20253-8f6e-501b-a57e-91dd5dae7dc7'::uuid, NULL, E'We all hope that this film will be a commercial success.', NULL, NULL, NULL),
