  ('9308a411-0467-57f3-a2c6-f51b4e150b78'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9308a411-0467-57f3-a2c6-f51b4e150b78'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '263046e5-d146-5b70-8cda-04db2ea597dc'::uuid, NULL, NULL, E'Please remember to bring a highlighter and your textbook to class next Thursday.', NULL, NULL),
  ('930cbece-4af3-5bc6-80ca-08ecb8f60d74'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '930cbece-4af3-5bc6-80ca-08ecb8f60d74'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the medical instrument used to examine the ear?', 'df53474f-1488-5c70-b61d-f436cd8d2173'::uuid, NULL, NULL, E'Otoscope', NULL, NULL),
  ('930cfe44-7bad-5256-8066-db2729ddf8aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '930cfe44-7bad-5256-8066-db2729ddf8aa'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1a2db910-e620-521d-be2b-1ec97c307037'::uuid, NULL, NULL, E'In ancient times the sheltered harbor attracted travelers at this location.', NULL, NULL),
  ('93113228-05d0-5e85-bfcf-e100caf42d41'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '93113228-05d0-5e85-bfcf-e100caf42d41'::uuid, 1, NULL, TRUE, 0, NULL, E'YOD', E'Young-onset dementia (YOD) is a form of dementia that affects people under the age of 65. It is a devastating condition that has a significant impact on the quality of life of the {{1}} individuals and their families. However, the risk factors and prevention strategies for YOD are not well understood. A recent analysis of data from the UK Biobank, a large biomedical database, identified 15 key {{2}} that could increase the risk of developing YOD. These factors include genetic, environmental, lifestyle, and health-related factors, such as lower education, lower socioeconomic status, alcohol use disorder, depression, diabetes, heart disease, and stroke. Some of these factors are modifiable and/or preventable, meaning that they can be changed or avoided by {{3}} healthy habits. For example, physical exercise, a Mediterranean-based diet, cognitive stimulation, mood regulation, and social interaction can all help lower the risk of YOD. By addressing these early on, it may be possible to prevent or delay the onset of YOD and improve the {{4}} for the affected individuals and their families.', NULL, NULL, NULL, E'1.affected, 2.factors, 3.adopting, 4.outcomes', NULL, NULL),
  ('93119ec6-efa5-5e2a-a19b-1733d857b732'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '93119ec6-efa5-5e2a-a19b-1733d857b732'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-R', E'The periodic table is a chart that reflects the periodic recurrence of chemical and physical properties of the elements when the elements are arranged in order of increasing atomic number (the number of protons in the nucleus). It is a monumental scientific achievement, and its development illustrates the essential interplay between observation, prediction, and testing required for scientific progress. In the 1800''s scientists were searching for new elements. By the late 1860''s more than 60 chemical elements had been identified, and much was known about their descriptive chemistry. Various proposals were put forth to arrange the elements into groups based on similarities in chemical and physical properties. The next step was to recognize a connection between group properties (physical or chemical similarities) and atomic mass (the measured mass of an individual atom of an element). When the elements known at the time were ordered by increasing atomic mass, it was found that successive elements belonged to different chemical groups and that the order of the groups in this sequence was fixed and repeated itself at regular intervals. Thus when the series of elements was written so as to begin a new horizontal row with each alkali metal, elements of the same groups were automatically assembled in vertical columns in a periodic table of the elements. This table was the forerunner of the modern table.\n\nAccording to this passage, what pattern did scientists notice when the known elements were written in order of increasing atomic mass?', NULL, NULL, NULL, E'Elements with similar chemical properties appeared in the listing at regular intervals.', NULL, NULL),
  ('9314b1eb-eb89-5fab-a9af-85e8af987a74'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9314b1eb-eb89-5fab-a9af-85e8af987a74'::uuid, 1, NULL, TRUE, 0, NULL, E'Movie Night', E'You''ve organized a monthly movie night with your friends, and everyone''s excited to watch a classic film together. However, upon arrival, you notice some guests bringing loud snacks that could disturb others during the movie. You need to remind everyone to bring quiet snacks to ensure an enjoyable viewing experience for everyone. What would you say to your friends?', '61ab480e-307d-5616-8f4d-330fcbb3d0cb'::uuid, NULL, E'Hey everyone, thanks for coming to movie night! Just a quick reminder, let''s try to bring snacks that won''t be too noisy during the movie. Loud wrappers and crunchy snacks can be distracting for others. Let''s opt for quieter options like popcorn, chocolate, or fruit. That way, we can all enjoy the movie without any interruptions. Thanks for understanding, and let''s have a great time together!', NULL, NULL, NULL),
  ('9316533f-f073-56e2-b03e-acf665a1abad'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9316533f-f073-56e2-b03e-acf665a1abad'::uuid, 1, NULL, TRUE, 0, NULL, E'Another Virtue', E'Another virtue that both propagate is that the present is meant to be enjoyed to the fullest. It is no use fretting about the past for it cannot be undone or overturned and no use pondering too much about the future for it remains unseen. The day being thought about may never dawn on you. The ultimate service, however, remains the one done for your fellow men.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('93190b5b-4f64-5f5b-8534-4c5a2e386565'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '93190b5b-4f64-5f5b-8534-4c5a2e386565'::uuid, 1, NULL, TRUE, 0, NULL, E'Bennett', E'In the last years of the wheat boom, Bennett had become increasingly {{1}} at how the government seemed to be encouraging an {{2}} farming binge. He went directly after the Department of Agriculture for {{3}} people. Farmers on the Great Plains were working {{4}} nature, he {{5}} in speeches.', NULL, NULL, NULL, E'1.frustrated, 2.exploitative, 3.misleading, 4.against, 5.thundered', NULL, NULL),
  ('931a19e1-42b7-5d5e-aa64-57841775115a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '931a19e1-42b7-5d5e-aa64-57841775115a'::uuid, 1, NULL, TRUE, 0, NULL, E'Smarter Organisms', E'Some of the most basic organisms are smarter than we thought. Rather than moving about randomly, amoebas and plankton employ sophisticated {{1}} to look for food and might travel in a way that {{2}} their foraging. Immediately upon an amoeba turning right, it was twice as likely to turn left as right again, and vice versa, they addressed a meeting of the American Physical Society in Denver, Colorado, last week. This suggests that the cells have a rudimentary {{3}} , being able to remember the last direction they had just turned in.', NULL, NULL, NULL, E'1.strategies, 2.optimizes, 3.memory', NULL, NULL),
  ('931aa65f-6034-58bb-9a3b-3cc0a9bef5b4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '931aa65f-6034-58bb-9a3b-3cc0a9bef5b4'::uuid, 1, NULL, TRUE, 0, NULL, E'Global Leadership', E'Education for Global Leadership: The Importance of International Studies and Foreign Language Education for U.S. Economic and National Security. To {{3}} the twenty-first century challenges to our economy and national security, our education system must {{1}} to increase the foreign language skills and cultural awareness of our students. America''s continued global leadership will depend on our students'' abilities to {{2}} with the world community both inside and outside our borders.', NULL, NULL, NULL, E'1.confront, 2.be strengthened, 3.interact', NULL, NULL),
  ('931b343b-edb0-53ba-845b-cee8e68fb2dc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '931b343b-edb0-53ba-845b-cee8e68fb2dc'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the process by which rural areas are transformed into urban areas?', '4f6acb5c-a358-54e5-89ce-d6a2ef96f42f'::uuid, NULL, NULL, E'Urbanization', NULL, NULL),
  ('931d0313-5b15-528f-93a1-22d7ab20edfb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '931d0313-5b15-528f-93a1-22d7ab20edfb'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c9dd3c2f-88d7-5fb0-aed9-bb7c84cc81d1'::uuid, NULL, NULL, E'Ads for kids are something people have strong opinions about.', NULL, NULL),
  ('93257e06-ced1-574a-9804-448decc95add'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '93257e06-ced1-574a-9804-448decc95add'::uuid, 1, NULL, TRUE, 0, NULL, E'Phantom Rivers', NULL, NULL, NULL, NULL, E'4, 5, 1, 2, 3', NULL, NULL),
  ('93303207-dc1f-5e90-9c43-b595e34cf792'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '93303207-dc1f-5e90-9c43-b595e34cf792'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a09e2eea-5617-592d-a3e4-2153e35ada69'::uuid, NULL, NULL, E'A new series of scholarly articles has recently been released.', NULL, NULL),
  ('933c2ce1-601a-593f-9fbb-01bec06d428a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '933c2ce1-601a-593f-9fbb-01bec06d428a'::uuid, 1, NULL, TRUE, 0, NULL, E'Types of Speech', NULL, 'd2d39e5d-3854-59ec-9ecc-e95e63f42072'::uuid, NULL, E'Standard usage includes those words and expressions understood, used, and accepted by a majority of the speakers of a language in any situation regardless of the level of formality. As such, these words and expressions are well defined and listed in standard dictionaries.\nColloquialisms, on the other hand, are familiar words and idioms that are understood by almost all speakers of a language and used in informal speech or writing, but not considered appropriate for more formal situations. Almost all idiomatic expressions are colloquial language. Slang, however, refers to words and expressions understood by a large number of speakers but not accepted as good, formal usage by the majority. Colloquial expressions and even slang may be found in standard dictionaries but will be so identified. Both colloquial usage and slang are more common in speech than in writing.\nColloquial speech often passes into standard speech. Some slang also passes into standard speech, but other slang expressions enjoy momentary popularity followed by obscurity. In some cases, the majority never accepts certain slang phrases but nevertheless retains them in their collective memories. Every generation seems to require its own set of words to describe familiar objects and events. It has been pointed out by a number of linguists that three cultural conditions are necessary for the creation of a large body of slang expressions. First, the introduction and acceptance of new objects and situations in the society; second, a diverse population with a large number of subgroups; third, association among the subgroups and the majority population.\nFinally, it is worth noting that the terms "standard" "colloquial" and "slang" exist only as abstract labels for scholars who study language. Only a tiny number of the speakers of any language will be aware that they are using colloquial or slang expressions. Most speakers of English will, during appropriate situations, select and use all three types of expressions.', NULL, NULL, NULL),
  ('933d5944-f7f8-5efe-b888-05e7514a45ff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '933d5944-f7f8-5efe-b888-05e7514a45ff'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the state of distress experienced by an individual who is suddenly exposed to a new, or foreign cultural environment?', 'c7cffe91-c387-5678-8b60-b6724bb1bacb'::uuid, NULL, NULL, E'Culture shock', NULL, NULL),
  ('934387c2-f1c9-5a01-b7ff-fa5684b2059e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '934387c2-f1c9-5a01-b7ff-fa5684b2059e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3c947ca7-8712-56c4-9a58-4637481831d1'::uuid, NULL, E'Would you like to come to the gallery with me?', NULL, NULL, NULL),
  ('93448b69-5f34-5b17-9f0e-e068bc5f62bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '93448b69-5f34-5b17-9f0e-e068bc5f62bd'::uuid, 1, NULL, TRUE, 0, NULL, E'Stress', E'This study tracked about 1,000 adults in the United States, and they ranged in age from 34 to 93, and they started the study by asking, ''How much stress have you experienced in the last year?'' They also asked, ''How much time have you spent helping out friends, neighbors, people in your community?'' And then they used public records for the next five years to find out who died.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('934f433e-c525-58d5-8cb9-8aec32be257b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '934f433e-c525-58d5-8cb9-8aec32be257b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6704a158-5914-5402-b0af-78f366417f2b'::uuid, NULL, NULL, E'She is an expert in the eighteenth-century French literature.', NULL, NULL),
  ('935447c3-46d2-5bf2-a3b6-7d844560e754'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '935447c3-46d2-5bf2-a3b6-7d844560e754'::uuid, 1, NULL, TRUE, 0, NULL, E'Succulents', E'Although succulents can vary greatly in appearance, they share a number of basic fundamental characteristics. The most important of these is the succulent''s ability to store water, from which its name is derived. Plants all have a certain degree of succulence. But succulents took this talent to new heights: some can store years'' worth of water in either their stems, roots or leaves for times of severe drought. Think of the wide stem of a saguaro cactus or the thick fleshy leaves of an aloe plant, and you''re basically looking at an expandable botanical rain barrel.\nHow are they going to collect any water in all those wild environments they inhabit? Many succulents have fantastic root systems completely specialized for their environments. In mountain regions, roots often dig down deep to harvest any subterranean water sources. But up on the plains, their roots are often broadly spread but incredibly shallow in order to catch any moisture that might lick the surface of the land, such as morning dew.\nPlants wage a constant battle to get all the nutrients they need in order to function. Besides water, they also need sunlight and carbon dioxide for photosynthesis. The CO2 comes in through diffusion so most plants have a huge number of pores, called stomata, to coax it in. But at the same time the sun is providing them with the energy they need to perform photosynthesis, it''s also evaporating water (a process that in plants is called transpiration) through the exposed stomata. It''s a difficult tightrope to walk, so succulents have managed to get themselves a safety harness.', NULL, NULL, NULL, NULL, 5, 75),
  ('93614a89-9463-50c6-9862-faf885750b26'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '93614a89-9463-50c6-9862-faf885750b26'::uuid, 1, NULL, TRUE, 0, NULL, E'Chemical''s Label', NULL, 'f4fc043f-d606-5c3f-afb8-b08d26d77ac3'::uuid, NULL, E'Product labels play an important role in protecting consumers, especially when the label is attached to a hazard chemical product. However, some products are designed in a way that may confuse people instead of warning them about potential risks. For example, the front of a container may show the lovely picture, giving the impression that the product is safe. Meanwhile, the warning information is only displayed at the back, which is very concerning because many people may never notice it before using the product. Another problem is that the warning text is often printed in small front, making it difficult to read. Studies have shown that about 60% of Americans cannot recognize words printed in fonts smaller than size 10. In addition, around 40% are illiterate, so they may not be able to understand written warnings even if they see them. As a result, many consumers won’t be aware of the hazardless associated with these products. For this reason, warning labels should be placed where they are easy to notice and written in a clear, readable format so that everyone can understand the potential dangers.', NULL, NULL, NULL),
  ('9364135b-2473-5376-a0ea-bbb30b35409c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9364135b-2473-5376-a0ea-bbb30b35409c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the sport that involves riding waves on a board?', 'f6a7ad64-7dd5-56fd-b193-3a82ec6156c0'::uuid, NULL, NULL, E'Surfing', NULL, NULL),
