  ('9375b981-0752-526e-b14e-0becad4213b7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9375b981-0752-526e-b14e-0becad4213b7'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3a6a81d3-523c-5e68-ba52-047615375019'::uuid, NULL, E'If I go out, he will call and leave notes for me.', NULL, NULL, NULL),
  ('937cbcd2-b7fa-57c0-9925-d4e254106846'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '937cbcd2-b7fa-57c0-9925-d4e254106846'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a355d919-a1f1-5471-bfa7-4ab9faf432bd'::uuid, NULL, NULL, E'The government has accused the media of bias.', NULL, NULL),
  ('937f1aa0-bcd4-5c43-b08d-d5311be279aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '937f1aa0-bcd4-5c43-b08d-d5311be279aa'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5e4d4ff0-e33a-5fc1-9013-32c6fb0f5321'::uuid, NULL, NULL, E'Her property was assigned to her grandchildren.', NULL, NULL),
  ('938124cf-7947-5bc8-8ae1-702129d3c823'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', '938124cf-7947-5bc8-8ae1-702129d3c823'::uuid, 1, NULL, TRUE, 0, NULL, E'Food Preference', E'Parents and other adults with whom children have close contact have a powerful influence on children''s food preferences. Children are very sensitive to the reactions of those around them. And if they see others enjoying a particular food, they will be inclined more favourably towards that food. Thus, if parents want to persuade their children to eat more vegetables than rather than simply telling them what to eat, it''s more effective to demonstrate that they themselves ...(beep)\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '8a1bf13c-6c4a-582d-ab54-a8043e83257f'::uuid, NULL, NULL, E'eat plenty of vegetables every day', NULL, NULL),
  ('93819349-955d-5975-9d10-30ac2e4779ea'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '93819349-955d-5975-9d10-30ac2e4779ea'::uuid, 1, NULL, TRUE, 0, NULL, E'Data Leak', E'In 2016, the world''s largest ever data leak dubbed "The Panama Papers" exposed a scandal, uncovering a vast global network of people — including celebrities and world leaders, who used offshore tax havens, anonymous transactions through intermediaries and shell corporations to hide their wealth, grow their fortunes and avoid taxes.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9386c732-e693-5aa7-9a94-5ce267c13bca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9386c732-e693-5aa7-9a94-5ce267c13bca'::uuid, 1, NULL, TRUE, 0, NULL, E'Stopped Internet', NULL, '900220ec-ac0d-5dcf-a086-5b9f62d8bbcc'::uuid, NULL, E'You could argue this kind of digital detox would be beneficial. We’d take our eyes off our screens then strike up real-life conversations with each other. We’ve discovered that our smartphones can actually make phone calls. We bring back fax machines and start making notes by hand. Well, maybe not fax machines and hey, we’d still have TV to entertain us the world would not fall apart. In fact, with almost 4 billion people having no access to the Internet worldwide, half of humanity wouldn’t notice a difference in the short term. But not you, mighty internet user. You would notice right away. If the internet suddenly flatlined, social media users would start calling each other on the phone overloading the working telecommunication systems, unless cell phone towers and telephone lines were also shut down. Then you’d go back to writing letters and sending them via post. Forget about Wireless file transfers with no Wi-Fi. You’d have to use a physical cable to connect to computers or a CD. Remember this? Now think about the economy with financial data generally stored on a server banking services largely depend on the Internet. Each transfers would be impossible. Your credit card and debit card would become a useless piece of plastic.', NULL, NULL, NULL),
