  ('93df230f-2b14-5779-a11d-806159bbeec3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '93df230f-2b14-5779-a11d-806159bbeec3'::uuid, 1, NULL, TRUE, 0, NULL, E'Diet Trends', E'Looking into the history of human diet, it''s clear that what we eat has changed dramatically from early hunter-gatherer societies to the present day. The introduction of agriculture was a turning point, leading to the development of settlements and the {{1}} of civilizations. Nowadays, there''s a significant {{2}} in diets like paleo, which suggest eating similarly to our ancestors for better health, highlighting a debate on the impact of processed foods. Nutrition science often presents conflicting advice, with studies sometimes {{3}} previous dietary guidelines. This makes choosing the "right" diet a complex issue, influenced by individual health needs and the latest research findings, rather than a one-size-fits-all solution. The push towards organic and {{4}} sourced foods reflects a general concern about the environmental and health impacts of our food choices.', NULL, NULL, NULL, E'1.rise, 2.interest, 3.overturning, 4.locally', NULL, NULL),
  ('93e06413-81d9-5390-88fb-7aca44b88037'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '93e06413-81d9-5390-88fb-7aca44b88037'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ff6f924a-500c-5537-983f-92b4ffc54656'::uuid, NULL, E'Many of my friends say they want to leave home to study overseas but I wouldn''t.', NULL, NULL, NULL),
