  ('948441c4-5f47-5f66-a967-9e3ab6a848dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '948441c4-5f47-5f66-a967-9e3ab6a848dd'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How many lines are there in a sonnet?', '67b50f5b-c230-5a49-9554-583fb92b3646'::uuid, NULL, NULL, E'Fourteen', NULL, NULL),
  ('948e8913-27f7-5e2a-9169-be49bfaaca40'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '948e8913-27f7-5e2a-9169-be49bfaaca40'::uuid, 1, NULL, TRUE, 0, NULL, E'Improving living standards', E'In order to improve living standards, it is inevitable to destroy the environment. Do you agree with this statement or not?', NULL, NULL, NULL, NULL, 200, 300),
  ('948f8a65-a4a0-55a0-8fb2-8fc38e9b46f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '948f8a65-a4a0-55a0-8fb2-8fc38e9b46f0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7e7ea419-dd42-5067-b5b3-095d796442fe'::uuid, NULL, E'You can get the books for this course in the library.', NULL, NULL, NULL),
  ('948f8cb3-dd43-58c7-9524-9ce610c946f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '948f8cb3-dd43-58c7-9524-9ce610c946f9'::uuid, 1, NULL, TRUE, 0, NULL, E'Angel Investors', E'Angel investors are individual funders to budding enterprises. They provide funds at very early stages of their growth, usually between one to three years of their existence. Angel investors are known with many names such as seed investors, angel funders, or private investors.\nThe investment from private investors come in exchange for a certain percentage of equity shares, giving an ownership stake in the startup. They are high-risk bearers since they park their funds in an early-stage firm that has to make a long journey to earn a market. Many private investors are high-net-worth individuals who invest their own funds. Additionally, those with limited funds rely on fellow investors and fund through a common pool.\nIt enables entrepreneurs to avail extensive capital without being burdened by debts. Moreover, many angel investors hold business expertise and are from specialized fields. By extending their knowledge, they assist in the startup’s management. It lays a strong foundation for the startup to walk towards its goals. In fact, the investment decision can only emerge if the investor sees genuine growth potential in the startup.\nInvestors make profits when shares appreciate in value either through public listing or acquisition. As per the Angel Capital Association’s report, surveying 1,659 accredited angel funders in the US, the median investment size is $25,000. However, investors with entrepreneurial experience sign bigger checks, with an average being $39,000 instead of the non-business background, whose average is $28,000. Moreover, amongst their portfolio, an average of 11 % gave positive returns. Every year, angel funders put in $25 billion in over 70,000 companies.', NULL, NULL, NULL, NULL, 5, 75),
  ('949e99ff-e9bb-5798-8022-23e5ab2c53af'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '949e99ff-e9bb-5798-8022-23e5ab2c53af'::uuid, 1, NULL, TRUE, 0, NULL, E'Sleep Disorder', NULL, '29d9019a-eb57-5f35-91da-cec98cb10b94'::uuid, NULL, E'You might think that most of the patients at sleep clinics are being treated for sleeplessness, commonly referred to as insomnia, but that is not the case. The majority of sleep-clinic patients suffer from disorders of excessive sleep, or "hypersomnia." While most insomniacs somehow manage to drag themselves through the day and function at acceptable, although not optimal levels, this is not so for people who suffer from hypersomnia. They are incapacitated by irresistible urges to sleep during the day, often in inappropriate situations--at business meetings, in supermarkets, or at parties. Even more dangerous is their failure to remain awake when driving or operating machinery. Falling asleep in such situations could obviously be life-threatening. Many hypersomniacs suffer from narcolepsy, for which the primary symptom is excessive daytime sleepiness. Though not apparent in childhood, this symptom most often appears for the first time during the teen years and continues throughout a person''s life. The sleep attacks may occur as many as fifteen to twenty times during the course of the day and last for periods from fifteen minutes up to two hours. What can be done to help those suffering from narcolepsy? There are certain drugs that can help, and specialists suggest voluntary napping to decrease the frequency of such sleep attacks.', NULL, NULL, NULL),
  ('94a31644-021d-5ff2-8074-e8a01c38de0f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '94a31644-021d-5ff2-8074-e8a01c38de0f'::uuid, 1, NULL, TRUE, 0, NULL, E'Eating Ways', E'People often get bored with one way of eating, which means that we have a lot of flexibility in {{1}} of creating our own healthy dietary patterns that can be {{2}} to individual food preferences, health conditions and cultures. For example, if you are eating healthy Mediterranean, and after a few months you want to try something different, you can {{3}} to a semi-vegetarian diet.', NULL, NULL, NULL, E'1.terms, 2.tailored, 3.switch', NULL, NULL),
  ('94a77576-d7bf-5918-8129-a5f6e93499eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '94a77576-d7bf-5918-8129-a5f6e93499eb'::uuid, 1, NULL, TRUE, 0, NULL, E'Future of Telecommunication', E'As technology continues to evolve, so too will telecommunication. The development of 5G networks, the Internet of Things (IoT), and other emerging technologies promise to transform the way we communicate and interact with each other. The future of telecommunication is full of exciting possibilities and endless potential.', NULL, NULL, NULL, NULL, NULL, NULL),
