  ('94e59127-9f73-541d-b789-a8f438f21220'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '94e59127-9f73-541d-b789-a8f438f21220'::uuid, 1, NULL, TRUE, 0, NULL, E'White Noise', E'We sometimes use the term "white noise" as a catch-all for ambient noises that drown out different sounds. But it turns out there''s something special about this particular combination of frequencies — experts have even found that the soothing sound of white noise helps people stay asleep. Buckle up for a primer on different types of ambient noise and how they affect your daily life.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('94f67f54-a953-56f0-9317-6c96f44b4dfd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '94f67f54-a953-56f0-9317-6c96f44b4dfd'::uuid, 1, NULL, TRUE, 0, NULL, E'Sunlight', E'Sunlight travels through space at nearly 300,000 kilometers per second. When sunlight {{1}} the Earth, it is mostly reflected or absorbed. Reflected light {{2}} back into space while absorbed light is the source of energy that {{3}} processes in the atmosphere, hydrosphere, and biosphere.', NULL, NULL, NULL, E'1.strikes, 2.bounces, 3.drives', NULL, NULL),
  ('94f9176e-59da-5b06-884c-d5cfb0d3120c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '94f9176e-59da-5b06-884c-d5cfb0d3120c'::uuid, 1, NULL, TRUE, 0, NULL, E'Tiny Creatures', E'Think of the {{1}} creatures you''ve ever seen in a sci-fi film. Now think of this: there are far stranger, albeit smaller, critters living in your own home. And Rob Dunn at North Carolina State University wants you to go on safari to find them.\nResearch has been done on the {{2}} of bacteria, fungi and other organisms that live on our skin, in our guts, even in our belly buttons.\nBut there are other entire ecosystems that surround us. And scientists want to understand how they differ based on how and where we live. What''s the tiny life like on a door frame in Brooklyn compared with that in Des Moines? Or how do fridge {{3}} of an urban singleton stack up with those of a suburban family?\nThe research team seeks ten volunteers from each state, five urban and five rural. Each volunteer will get a kit of vials and swabs, along with instructions about where and how to swipe—such as door frames, couch cushions, refrigerators, {{4}} yourself. The samples will be {{5}} , to uncover the secrets of our {{6}} companions. To find out more, go to robdunnlab.com.', NULL, NULL, NULL, E'1.weirdest, 2.diversity, 3.microbes, 4.even, 5.analyzed, 6.microscopic', NULL, NULL),
  ('94fabd3d-2e20-57c7-80b1-595a0f477246'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '94fabd3d-2e20-57c7-80b1-595a0f477246'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person who believes that laws and governments are not necessary?', '92dbb234-d831-5590-b73a-65d88374c165'::uuid, NULL, NULL, E'Anarchist', NULL, NULL),
