  ('95427a2c-ec77-5569-89ae-eb78177c6428'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '95427a2c-ec77-5569-89ae-eb78177c6428'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '14561e95-50b9-5571-b1cc-c6647f5555ce'::uuid, NULL, E'The books are filled with drawings of machines invented when he was a student.', NULL, NULL, NULL),
  ('954c050b-97f6-529c-bd5a-fa5791a4394b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '954c050b-97f6-529c-bd5a-fa5791a4394b'::uuid, 1, NULL, TRUE, 0, NULL, E'Water and Health', E'Getting enough water every day is important for your health. Drinking water can prevent dehydration, a condition that can cause unclear thinking, result in mood change, cause your body to overheat, and lead to constipation and kidney stones. Water has no calories, so it can also help with managing body weight and reducing calorie intake when substituted for drinks with calories, such as sweet tea or regular soda.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('95510b5e-3b03-5271-9fca-e4096dd54cc5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '95510b5e-3b03-5271-9fca-e4096dd54cc5'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is opposite to herbivore?', 'e2320902-ae0b-5167-918e-d682be779c3f'::uuid, NULL, NULL, E'Carnivore', NULL, NULL),
  ('9560aef3-7710-58c2-9a87-1c2144f9b02d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9560aef3-7710-58c2-9a87-1c2144f9b02d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f44aef9f-c5aa-5df7-b720-241b5bf0b6a1'::uuid, NULL, E'Fine arts typically lack practical functionality compared to applied arts.', NULL, NULL, NULL),
  ('956b5c32-5924-519b-91d1-18472a3a0de7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '956b5c32-5924-519b-91d1-18472a3a0de7'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2749d893-4da1-5e96-9c6f-cdc11e064daa'::uuid, NULL, E'You still have heaps of time to complete this task before its deadline.', NULL, NULL, NULL),
  ('956f77e2-7cbe-52ba-996d-10d8841bd12a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '956f77e2-7cbe-52ba-996d-10d8841bd12a'::uuid, 1, NULL, TRUE, 0, NULL, E'Fire', E'Some scientists say the use of fire helped make us modern humans—it dramatically changed what and how we eat and may have even altered our anatomy. But University of Utah anthropologist Polly Wielder thinks that fire was also important in shaping human social interactions and cultural {{1}} . Her conclusions are in the Proceedings of the National Academy of Sciences.\nWiessner evaluated day and night activities and {{2}} of Bushmen from Botswana and Namibia. These communities still live by hunting and gathering, as most humans did over {{3}} history.\nDuring the day, nearly a third of the conversations dealt with economic issues such as hunting strategies and foraging plans. Another third covered complaints, criticisms and gossip.\nBut at night around the fire, more than 80 percent of group conversations were storytelling, often about people living far away or in the spirit world.\nWeissner says that humans are unique in that we create ties to others outside of our immediate group. Gathering at the fire {{4}} listeners'' imaginations and allowed for the development of cognitive processes that made it possible to form those links to distant communities. Which makes fire the precursor to Facebook.', NULL, NULL, NULL, E'1.traditions, 2.conversations, 3.evolutionary, 4.expanded', NULL, NULL),
  ('95819570-d62a-55b4-920f-e97b5cfe4ee9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '95819570-d62a-55b4-920f-e97b5cfe4ee9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '319e28eb-2587-56b0-a951-46ffcf70948f'::uuid, NULL, E'The train is leaving in a few minutes.', NULL, NULL, NULL),
  ('95874d4d-f45f-5f68-a49d-808068dad0c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '95874d4d-f45f-5f68-a49d-808068dad0c0'::uuid, 1, NULL, TRUE, 0, NULL, E'Video Game', E'IBM arranged a video game match between a supercomputer and human gamers. The fact that the computer has {{1}} against humans made people worry whether scientific technologies could threaten us. {{2}} , the computer can only perform programs that are set by us. Even machine-learning has not {{3}} developed enough to think independently like humans.', NULL, NULL, NULL, E'1.competed, 2.However, 3.yet', NULL, NULL),
  ('958846e5-c2cf-54d8-817f-1cb7b7ea0a6c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '958846e5-c2cf-54d8-817f-1cb7b7ea0a6c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '77cece5b-6d46-51d6-aaa1-a8f9c1e70c8a'::uuid, NULL, NULL, E'He was in an argument with his landlord downstairs.', NULL, NULL),
  ('958a907a-dc43-5257-990a-5479e2a8706c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '958a907a-dc43-5257-990a-5479e2a8706c'::uuid, 1, NULL, TRUE, 0, NULL, E'Conflict', NULL, 'c300d19d-2448-5f09-826a-6338cd037bbd'::uuid, NULL, E'Some years ago a group of academics from different disciplines recognized the necessity of studying conflict as a phenomenon. They were interested in the distinct properties of conflict as it occurred in international relations, national politics, industrial relations, communities or even in the domestic setting. These academics believed that approaches from different disciplines could be applied to the study of conflict with a view to better understanding its causes, effects and solutions.\nAs a result, research groups developed, and universities and academic journals began to publish papers on ''conflict theory'', as it came to be called. Unfortunately many other academics didn''t welcome this new discipline; they couldn''t reconcile it with traditional scholarly practices because it had both a practical nature and an analytical approach.\nNevertheless, the new discipline continued to develop and the field grew and spread and conflict theory now has the same prestige as other academic areas of research and study, despite the early criticism it attracted.', NULL, NULL, NULL),
  ('958cef78-dd27-55c7-afdf-83c398cfbef2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '958cef78-dd27-55c7-afdf-83c398cfbef2'::uuid, 1, NULL, TRUE, 0, NULL, E'Mindfulness Practice and Migraine', E'Many common medication treatments for migraine may cause side effects that are difficult to tolerate, and can lead people to not take their medications as recommended, or to stop taking them altogether. A recent study suggests that up to 20% of patients with migraine have used opioids to treat their pain in the past year. Therefore, there is a great need for better and more tolerable treatments for people who have migraines.\nResearch has shown that combining behavioral treatments with preventive medication treatments works better for preventing headaches than medications alone. Mindfulness practice has also been associated with improvements in individuals with chronic pain, including migraine. Mindfulness is the mind-body treatment that involves purposely focusing one’s attention on the present momentary awareness and accepting it without judgment.\nStress is a well-known trigger for migraine. Moreover, stressful events have been associated with people experiencing more frequent or chronic migraines versus having them occasionally. Mindfulness can result in stress reduction, reduced emotional response to stress, and improved general happiness. In patients with migraine, pain severity and unpleasant symptoms can be reduced with this treatment.\nMindfulness can potentially strengthen emotional and cognitive control of pain by helping to train someone with migraine to reassess their pain in a nonjudgmental way and modify their evaluation of the pain. In addition, mindfulness practices can help to control depression, anxiety, and pain catastrophizing (an exaggerated negative feeling toward pain experiences), which can play a role in chronic migraine.', NULL, NULL, NULL, NULL, 5, 75),
  ('958e1c59-3792-58a6-9e69-69dfb9d9b332'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '958e1c59-3792-58a6-9e69-69dfb9d9b332'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '34655946-8eb8-5892-9e12-19dc05c4803f'::uuid, NULL, E'Making workplace changes can often bring significant challenges to the forefront.', NULL, NULL, NULL),
  ('95973022-9bb2-5307-a83d-f10fc382942b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '95973022-9bb2-5307-a83d-f10fc382942b'::uuid, 1, NULL, TRUE, 0, NULL, E'Supply and Demand', E'The supply of a thing, in the phrase ''supply and demand'', is the amount that will be offered for sale at each of a series of prices; the demand is the amount that will be bought at each of a series of prices. The principle that value depends on supply and demand means that in the case of nearly every commodity, more will be bought if the price is lowered, less will be bought if the price is {{1}} . Therefore sellers, if they wish to induce buyers to take more of a commodity than they are already doing, must reduce its price; if they raise its price, they will sell less. If there is a general falling off in demand - due, say, to trade depression - sellers will either have to {{2}} prices or put less on the {{3}} ; they will not be able to sell the same {{4}} at the same price. Similarly with supply. At a certain price a certain amount will be offered for sale, at a higher price more will be offered, at a lower price less. If consumers want more, they must offer a higher price; if they want less, they will probably be able to force prices down. That is the first result of a change in demand or supply.', NULL, NULL, NULL, E'1.raised, 2.reduce, 3.market, 4.amount', NULL, NULL),
  ('9597e495-9788-5df5-b1d6-087fe63d804f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9597e495-9788-5df5-b1d6-087fe63d804f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '484deed6-60b2-56ce-b849-fb224954858f'::uuid, NULL, E'You will probably need to find the nearest post office to access that service.', NULL, NULL, NULL),
  ('959bfa33-b977-571d-b88a-9702e94059c7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '959bfa33-b977-571d-b88a-9702e94059c7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '78a1c3d1-117a-536e-a840-0f5adcf60c0b'::uuid, NULL, NULL, E'Fashion trends help people to make life interesting.', NULL, NULL),
  ('959c691c-0af9-5818-8e55-81328f0cafbf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '959c691c-0af9-5818-8e55-81328f0cafbf'::uuid, 1, NULL, TRUE, 0, NULL, E'Thought Processes', NULL, NULL, NULL, NULL, E'1, 2, 3, 5, 4', NULL, NULL),
  ('959c80cb-ee07-5fb0-be05-49b1e6bc14b0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '959c80cb-ee07-5fb0-be05-49b1e6bc14b0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3a06ca00-1c5c-5141-a5d0-f14a9931f49e'::uuid, NULL, E'The study demonstrates a need for further research in this field.', NULL, NULL, NULL),
  ('959e9d98-6308-5d4e-95a9-e7bc5c6653ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '959e9d98-6308-5d4e-95a9-e7bc5c6653ee'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '189f7c26-b435-5882-aed5-2b6c6452a7ed'::uuid, NULL, E'Make sure the financial director knows the full details of the pay agreement.', NULL, NULL, NULL),
  ('959f6fd5-44bf-56bb-ad92-232ce7efd0f3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '959f6fd5-44bf-56bb-ad92-232ce7efd0f3'::uuid, 1, NULL, TRUE, 0, NULL, E'Political Analysts', E'For those political analysts whose main interest remains class divisions in society the biggest split these days is that between those who control and work with informational technology (IT) and those we might still call blue-collar workers. The old divisions of class have become a lot more difficult to apply, if not completely outdated. There''s no escaping the enormous impact of information technology in the late 20th and, even more, the early 21st centuries, both economically and socially.\nDuring the scientific revolution of the 17th and 18th centuries, the spirit of experiment was in the air, and those involved were practical people working to practical ends — often on their own or with a small group of trusted friends. Secrecy was important as there was money to be made in new inventions.\nWhat interested them were results, not theories. Most modern technological advances, however, were developed as theories first, and then made reality by large teams of scientists and experts in the field. What we have now is that more and more of this type of expertise is being used to analyse and find solutions to all kinds of business and social problems, thus creating — in the eyes of the political analysts mentioned above — a whole large new economic and social class.', NULL, NULL, E'The biggest split of social class these days is that between those who control and work with informational technology and blue-collar workers, with most modern technological advances developed as theories first and then made reality by scientists and experts in the field and more and more of this type of expertise being used to analyse and find solutions to all kinds of business and social problems, thus creating a new economic and social class.', NULL, 5, 75),
  ('95b08811-2611-5fa7-abe1-422e17788ce3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '95b08811-2611-5fa7-abe1-422e17788ce3'::uuid, 1, NULL, TRUE, 0, NULL, E'Music and Wellbeing', NULL, '53d5b90e-85ab-5f7e-a6e5-1f9056cc3ce5'::uuid, NULL, E'So what do we mean by well-being? Health, happiness, a sense of achievement and contentment, a state of mind and body where people can thrive. Well-being is not something that is purely limited to people who are facing extraordinary challenges in their lifestyle, health or personal circumstances, everybody here has a level of well-being. Music so often forms an intuitive part of our well-being management, music to pick us up, music to calm us down, music to heal our sorrows. Our aim through research is to move from this level of intuitive application of music through to informed use in our communities to take the next step in the understanding of the power of music in human life. Music already works for us on so many levels whether it''s soothing and teaching our infants bringing people and communities together adding spirit to our work and personal endeavors, but there is no reason to stop here.', NULL, NULL, NULL),
  ('95b47b02-422a-5a3a-9ad8-e51bdc883dcb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '95b47b02-422a-5a3a-9ad8-e51bdc883dcb'::uuid, 1, NULL, TRUE, 0, NULL, E'Color Awareness', E'Have you ever wondered if you see the same colors as other people? Most people know what blue is when they see it. It’s the color of sea, sky and sapphires. They see the color and call it blue because they were taught the word and associated it with what they saw. But how do you know what you see as blue isn’t someone else’s red, and vice versa?\nThe ability to perceive different colors is down to receptors in our eyes known as cones. Light waves hit these receptors and they react depending on which color the light is, sending signals to the brain. The brain then decodes these signals to determine which color light the eyes are receiving. Some people’s receptors are more developed than others. And those with more enhanced receptors can see more shades of one colour, which is the first way in which people may see colors differently from each other. The inability of the receptor to interpret the light waves correctly means that some people cannot distinguish between different shades of a color. So we sometimes hear people having an argument about whether something is dark blue or black. It might be because one person has stronger receptors to interpret the light than another.\nSo, the next time you talk about your favorite color, just remember if yours is blue and your friend says red, you might actually be thinking about the same colour. What if everyone in the world has the same favorite color, but just calls it different names?', NULL, NULL, NULL, NULL, 5, 75),
  ('95b89948-0097-5a37-9bf9-292ac3b3333b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '95b89948-0097-5a37-9bf9-292ac3b3333b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f0a5b955-8597-52c1-9169-ad40c8c0d561'::uuid, NULL, NULL, E'Scientific progress relies heavily on the process of peer review.', NULL, NULL),
  ('95bbd55a-8468-5d7e-909f-51140fe2a820'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '95bbd55a-8468-5d7e-909f-51140fe2a820'::uuid, 1, NULL, TRUE, 0, NULL, E'Online Shopping', E'With the development of online shopping, more people prefer to buy things online rather than in the store. Do you think it is a positive or negative development?', NULL, NULL, NULL, NULL, 200, 300),
  ('95bc126d-263b-5488-a550-0c6a05198fb3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '95bc126d-263b-5488-a550-0c6a05198fb3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b0aff32c-040d-58f0-897a-7c012ec23a4b'::uuid, NULL, NULL, E'The key difference between courses is the kind of assessment.', NULL, NULL),
  ('95bcd5ed-7d20-551f-893a-33767b0ae515'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '95bcd5ed-7d20-551f-893a-33767b0ae515'::uuid, 1, NULL, TRUE, 0, NULL, E'Human Nature', E'Modern developments in areas such as neuroscience, artificial intelligence and evolutionary psychology have resulted in new {{1}} of thinking about human nature. Can we explain the mind and consciousness in {{2}} of brain function? Can we understand modern human behavior as our evolutionary heritage? Is science even the right {{3}} to start if we want to understand human nature? Come along to the Great Debate, hear the arguments and have your {{4}} .', NULL, NULL, NULL, E'1.ways, 2.terms, 3.place, 4.say', NULL, NULL),
  ('95bd1db9-68d0-57a8-8bff-73243118a126'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '95bd1db9-68d0-57a8-8bff-73243118a126'::uuid, 1, NULL, TRUE, 0, NULL, E'Cycads', E'Like their lumbering grazers, most cycads have gone extinct. Their disappearance from their prior habitats began during the late Mesozoic and continued into the early Cenozoic Era, punctuated by the cataclysmic asteroid impact and volcanic activity that mark the K-Pg boundary 66 million years ago. However, unlike the dinosaurs, somehow a few groups of cycads survived to the present.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('95bd55d7-58b7-5f6d-8aee-6bde5015ab67'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '95bd55d7-58b7-5f6d-8aee-6bde5015ab67'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person who sells goods or services, often in a store?', 'a04c5afa-0f59-5e5a-9665-0c2ae0e0bed7'::uuid, NULL, NULL, E'Salesperson / Salesman / Saleswoman', NULL, NULL),
