  ('96cdb4d7-3d89-5dc5-bde6-8bab45309401'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '96cdb4d7-3d89-5dc5-bde6-8bab45309401'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0dcc62f1-4580-5abe-aae8-7c3b2fad31c2'::uuid, NULL, E'There is a special exam designed for students with disabilities.', NULL, NULL, NULL),
  ('96d7848e-1c61-5479-9abf-bf06993703b6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '96d7848e-1c61-5479-9abf-bf06993703b6'::uuid, 1, NULL, TRUE, 0, NULL, E'Traditional Books', E'Do you agree that traditional books are better for learning than electronic books?', NULL, NULL, E'I firmly believe that traditional books offer a superior learning experience compared to electronic books. The tangible and sensory aspects of traditional books provide unique benefits that contribute to a more effective and engaging learning process.\nTraditional books provide a physical and tactile reading experience that enhances learning in a way that electronic books cannot match. The act of turning pages, feeling the texture of paper, and physically engaging with the content creates a deeper connection with the material, leading to enhanced comprehension and retention of information.\nMoreover, reading traditional books can help reduce eye strain and limit screen time, addressing common concerns associated with electronic devices. The absence of digital screens in traditional books eliminates the potential negative effects of prolonged screen exposure, allowing for extended reading sessions without the strain and fatigue often experienced with electronic reading. Additionally, traditional books do not require batteries or technical devices to access, ensuring uninterrupted learning experiences without reliance on external power sources.\nIn conclusion, the physicality, eye-friendly nature, and independence from batteries or technical devices make traditional books the preferred choice for learning over electronic books. The immersive and practical advantages offered by traditional books create a conducive environment for effective learning, fostering comprehension, focus, and engagement without the distractions and limitations associated with electronic devices.', NULL, 200, 300),
  ('96d8f0e1-e927-5efc-88d9-ea6677eedc83'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '96d8f0e1-e927-5efc-88d9-ea6677eedc83'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f0383c39-c22e-5796-b84b-205da8d6f355'::uuid, NULL, E'You need to pass the written exam before you can apply for the driver''s license.', NULL, NULL, NULL),
  ('96dee020-eb52-5e4e-a944-0ec2a9651b61'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '96dee020-eb52-5e4e-a944-0ec2a9651b61'::uuid, 1, NULL, TRUE, 0, NULL, E'Psychology', E'Psychology is the scientific study of the mind and behavior, according to the American Psychological Association. Psychology is a multifaceted discipline and includes many sub-fields of study such areas as human development, sports, health, clinical, social behavior and cognitive processes.\nPsychology is really a very new science, with most advances happening over the past 150 years or so. However, its origins can be traced back to ancient Greece, 400 – 500 years BC. Philosophers used to discuss many topics now studied by modern psychology, such as memory, free will vs determinism, nature vs. nurture, attraction etc.\nIn the early days of psychology there were two dominant theoretical perspectives regarding how the brain worked, structuralism and functionalism. Structuralism was the name given to the approach pioneered by Wilhelm Wundt (1832-1920), which focused on breaking down mental processes into the most basic components. The term originated from Edward Titchener, an American psychologist who had been trained by Wundt. Wundt was important because he separated psychology from philosophy by analyzing the workings of the mind in a more structured way, with the emphasis being on objective measurement and control. Structuralism relied on trained introspection, a research method whereby subjects related what was going on in their minds while performing a certain task.\nAn American psychologist named William James (1842-1910) developed an approach which came to be known as functionalism, that disagreed with the focus of Structuralism. James argued that the mind is constantly changing and it is pointless to look for the structure of conscious experience. Rather, he proposed the focus should be on how and why an organism does something, i.e. the functions or purpose of the brain. James suggested that psychologists should look for the underlying cause of behavior and the mental processes involved. This emphasis on the causes and consequences of behavior has influenced contemporary psychology.', NULL, NULL, NULL, NULL, 5, 75),
  ('96df3538-9697-50f2-93c8-0c609651b6fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '96df3538-9697-50f2-93c8-0c609651b6fb'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '87e85c24-bd65-5468-844d-8cb0707457a8'::uuid, NULL, E'Technically you can use many methods to solve these math problems.', NULL, NULL, NULL),
  ('96e737f9-96b6-5c69-8207-be5bb72343cc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '96e737f9-96b6-5c69-8207-be5bb72343cc'::uuid, 1, NULL, TRUE, 0, NULL, E'Vision Impairment', E'Globally, at least 1 billion people have a near or distance vision impairment that could have been prevented or has yet to be {{1}} . In the {{2}} of timely detection, reduced or absent eyesight can have long-term personal and economic effects. It often affects quality of life through lower {{3}} ,decreased workforce participation and high rates of depression.', NULL, NULL, NULL, E'1.addressed, 2.absence, 3.productivity', NULL, NULL),
  ('96f38a94-8538-5fa0-9ba5-e74cb4e89e86'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '96f38a94-8538-5fa0-9ba5-e74cb4e89e86'::uuid, 1, NULL, TRUE, 0, NULL, E'Echidna', E'A long-beaked echidna named after Sir David Attenborough and last seen by scientists in 1961 has been photographed for the first time in an Indonesian tropical forest. An international team of researchers worked with local communities to deploy over 80 camera traps to film the elusive animal. Besides rediscovering the echidna, the team uncovered a wealth of species completely new to science.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('96f39fda-f718-5d44-ae06-94c870171cf9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '96f39fda-f718-5d44-ae06-94c870171cf9'::uuid, 1, NULL, TRUE, 0, NULL, E'CSIRO', E'The Australian Maritime College at the University of Tasmania, in {{1}} with CSIRO and University of Queensland, have been awarded $2.49 million in {{2}} for their new project that is set to attract and underpin investment in tidal energy in Australia. The project hopes to overcome barriers to investment in commercial-scale tidal farms in Australia by mapping the country’s tidal energy in more {{3}} than ever before.', NULL, NULL, NULL, E'1.partnership, 2.support, 3.detail', NULL, NULL),
  ('96fb9e34-181b-517d-ae28-7720d1f1c782'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '96fb9e34-181b-517d-ae28-7720d1f1c782'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'If one’s response is simultaneous, quick or slow?', '7f2c0241-5b7e-59ec-ae59-03313d111f72'::uuid, NULL, NULL, E'quick', NULL, NULL),
