  ('9717f621-e4fd-5236-85f4-c2748573de8d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9717f621-e4fd-5236-85f4-c2748573de8d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c37b3461-6055-5631-850d-7a1201a6aaa3'::uuid, NULL, NULL, E'The temporary library will be closed in the winter break.', NULL, NULL),
  ('971beed5-cdcd-5304-a78a-746f66aa5a5d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '971beed5-cdcd-5304-a78a-746f66aa5a5d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ee42e8ef-b4f5-57ab-b761-2b9218b6d1a3'::uuid, NULL, E'You will find the circulation desk on the library''s ground level.', NULL, NULL, NULL),
  ('972916d3-5985-5e58-88bb-f73f7fc6db68'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '972916d3-5985-5e58-88bb-f73f7fc6db68'::uuid, 1, NULL, TRUE, 0, NULL, E'AI and Science', E'The concept of artificial intelligence (AI) has been a {{1}} in science fiction for decades, but in recent years, it has evolved from fiction to {{2}} reality. AI is now integrated into many aspects of our daily lives, from voice assistants like Siri and Alexa to recommendation algorithms on streaming platforms. One of the most exciting {{3}} of AI is its potential to revolutionize healthcare. AI-powered diagnostic tools can analyze medical images and patient data with incredible accuracy, helping doctors make more informed decisions. This has the potential to improve patient outcomes and reduce healthcare costs. However, the widespread adoption of AI also raises {{4}} challenges. Concerns about data privacy and the ethical use of AI are growing. There is a need for clear regulations to ensure that AI systems are developed and used responsibly. Additionally, the potential for job displacement due to automation requires a proactive approach to workforce training and reskilling. In conclusion, while AI offers tremendous benefits in various {{5}} , it also comes with ethical and societal considerations that need to be carefully addressed to harness its full potential.', NULL, NULL, NULL, E'1.dream, 2.actual, 3.benefits, 4.significant, 5.fields', NULL, NULL),
  ('9731b75e-f209-5360-bde9-3c8dbbcf8b6e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '9731b75e-f209-5360-bde9-3c8dbbcf8b6e'::uuid, 1, NULL, TRUE, 0, NULL, E'Celtic Bards', E'Ancient Celtic bards were famous for the sheer {{1}} of information they could memorize. This included thousands of songs, stories, chants and {{2}} that could take hours to recite in full. Today we are pretty spoiled. Practically the whole of human {{3}} is conveniently available at our fingertips.', NULL, NULL, NULL, E'1.quantity, 2.poems, 3.knowledge', NULL, NULL),
  ('97381768-ef06-5797-b27f-9384fd4b6892'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '97381768-ef06-5797-b27f-9384fd4b6892'::uuid, 1, NULL, TRUE, 0, NULL, E'Advertisement', E'Almost all public spaces nowadays have advertisements in sight, and all forms of media, from newspapers to the cinema to the Internet, are {{1}} with adverts. This all-pervasive presence reflects the value of advertising to us. Without it, businesses of all types and sizes would {{2}} to inform potential customers about the products or services they provide, and consumers would be unable to make informed assessments when looking for products to buy and services to use. Without advertising, the promotion of products and {{3}} that contribute to our physical and psychological well-being-medicines to treat minor ailments, insurance schemes to protect us, clothes and cosmetics to make us look and feel better- would be {{4}} more problematic than it is. And without advertisements and the {{5}} represented in them, the world would be a far {{6}} place.', NULL, NULL, NULL, E'1.filled, 2.struggle, 3.practices, 4.infinitely, 5.aspirations, 6.duller', NULL, NULL),
  ('97394849-c102-5cd5-8456-62bf93ebb53c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '97394849-c102-5cd5-8456-62bf93ebb53c'::uuid, 1, NULL, TRUE, 0, NULL, E'Internet Interruptions', E'Internet interruptions caused by extreme weather events sap billions of dollars annually from the global economy and can interfere with the delivery of essential data and services by governments, utilities, and first responders. A Boston-based startup is trying to address that problem by applying climate resilience and adaption principles to the internet, which experts say is vulnerable to climate change.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('97394f0c-491c-5eb3-b850-217c179ad853'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '97394f0c-491c-5eb3-b850-217c179ad853'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c8d30294-be8e-5ca1-9a32-6833051339c4'::uuid, NULL, E'Please make sure that your assignments are successfully submitted via the online portal.', NULL, NULL, NULL),
