  ('9740f833-d0a5-5ef4-8e2e-644794870407'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9740f833-d0a5-5ef4-8e2e-644794870407'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which organ of your body is responsible for pumping blood through your body?', '5727ed6a-09a1-553c-a1e3-873b45343ef8'::uuid, NULL, NULL, E'Heart', NULL, NULL),
  ('974314e3-fdfd-5280-8373-060d1414cfee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '974314e3-fdfd-5280-8373-060d1414cfee'::uuid, 1, NULL, TRUE, 0, NULL, E'Lecture Beginning', E'Don''t miss the beginning of the lecture since it is very often most valuable part, for instance, because it reviews previous lectures or outlines objects and lecture structure. If you easily get distracted by other students, sit near the front.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9747317f-ac04-581d-bc57-b3b075f4d5b3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9747317f-ac04-581d-bc57-b3b075f4d5b3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '13bbcdf6-7070-5df6-850d-b2523586d4dd'::uuid, NULL, NULL, E'A well-designed architectural structure should be functional, long-lasting, and aesthetically pleasing.', NULL, NULL),
  ('97484faa-bb7d-5835-a472-3e539829e36f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '97484faa-bb7d-5835-a472-3e539829e36f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4eb74d9a-3111-5fb3-ba2e-fed39d052e7a'::uuid, NULL, NULL, E'The chairman of the committee is expected to be back tomorrow.', NULL, NULL),
  ('9751986d-0b3d-58da-800e-94d23adda38f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9751986d-0b3d-58da-800e-94d23adda38f'::uuid, 1, NULL, TRUE, 0, NULL, E'Herbivore', E'“What we found is that the plant is actually damaged by herbivores like most plants are in nature. And in response to that it secretes sugar from the wound edges where the herbivores have damaged the plant.” Tobias Lortzing is a graduate student at Freie University Berlin and one of the study authors.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9754ad8b-631f-5b49-a19f-c18689bde411'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9754ad8b-631f-5b49-a19f-c18689bde411'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'bed0e87a-d1e7-5a19-a50d-c62597fac2fc'::uuid, NULL, NULL, E'The professor said biology is not the only one on the exam.', NULL, NULL),
  ('9758e931-1dc5-5b9c-9a4f-1f71a3012f82'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '9758e931-1dc5-5b9c-9a4f-1f71a3012f82'::uuid, 1, NULL, TRUE, 0, NULL, E'Technology', E'Some would say that improving technology has made our lives easier. Imagine what your day would be like without the Internet, the automobile, or electricity. In The World Is Flat, Thomas Friedman (2005) argues that technology is a {{1}} force behind globalization, while the other forces of social change (social institutions, population, environment) play comparatively minor roles. He suggests that we can view globalization as occurring in three distinct {{2}} . First, globalization was driven by military expansion, powered by horsepower and wind power. The countries best able to take {{3}} of these power sources expanded the most, and {{4}} control over the politics of the globe from the late fifteenth century to around the year 1800. The second shorter period from approximately 1800 C.E. to 2000 C.E. consisted of a globalizing economy. Steam and rail power were the guiding forces of social change and globalization in this period. Finally, Friedman brings us to the post-millennial era. In this period of globalization, change is driven by technology, particularly the Internet.', NULL, NULL, NULL, E'1.driving, 2.periods, 3.advantage, 4.exert', NULL, NULL),
  ('97596828-8ae2-5c80-9be7-8250cf744a4d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '97596828-8ae2-5c80-9be7-8250cf744a4d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a machine which carries people from one floor to another in a high building?', 'afc964eb-208e-5c80-a7dc-2067100e1c2d'::uuid, NULL, NULL, E'Lift / Elevator', NULL, NULL),
  ('97610a18-1e6e-5cd7-a0cb-aaaf56503672'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '97610a18-1e6e-5cd7-a0cb-aaaf56503672'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What can we call the science or practice of drawing maps?', '71dab00e-efb3-5e2d-94f3-ce389b9bd702'::uuid, NULL, NULL, E'Cartography', NULL, NULL),
  ('9761d6be-c688-5f82-ba53-c63561f4f44b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '9761d6be-c688-5f82-ba53-c63561f4f44b'::uuid, 1, NULL, TRUE, 0, NULL, E'Puzzle', NULL, NULL, NULL, NULL, E'2, 3, 4, 5, 1', NULL, NULL),
  ('97664a3d-b121-52db-a10e-601f146d3aa4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '97664a3d-b121-52db-a10e-601f146d3aa4'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e8676dd7-3960-527c-acda-1df82a074c0b'::uuid, NULL, E'I am pleased to report that many topics have been involved in this lecture.', NULL, NULL, NULL),
  ('976a2432-4cde-5ae8-b9c9-f4509e5837b3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '976a2432-4cde-5ae8-b9c9-f4509e5837b3'::uuid, 1, NULL, TRUE, 0, NULL, E'Leg Coordination', E'Finally, the experimenters examined real insects. To see if leg adhesion might also play a role in the walking coordination of real flies, they put polymer drops on the flies'' legs to cover their claws and adhesive pads — as if the flies were wearing boots — and watched what happened. The flies quickly began to use bipod-like leg coordination similar to the one discovered in the simulation.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('976eb856-9085-5c2f-bf3a-8081fbd06c2f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '976eb856-9085-5c2f-bf3a-8081fbd06c2f'::uuid, 1, NULL, TRUE, 0, NULL, E'Financial Crisis', E'Since the beginning of the financial crisis, there have been two principal {{1}} for why so many banks made such disastrous decisions. The first is structural. Regulators did not regulate. Institutions failed to {{2}} as they should. Rules and guidelines were either inadequate or {{3}} . The second explanation is that Wall Street was {{4}} , that the traders and investors didn''t know enough, that they made extravagant bets without understanding the consequences.', NULL, NULL, NULL, E'1.explanations, 2.function, 3.ignored, 4.incompetent', NULL, NULL),
