  ('97ba009a-3001-5b18-a913-3c5d928d830c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '97ba009a-3001-5b18-a913-3c5d928d830c'::uuid, 1, NULL, TRUE, 0, NULL, E'Spanish and French', E'Spanish is known for its phonetic pronunciation, with consistent spelling and pronunciation rules. It has a relatively simple verb conjugation system compared to French. On the other hand, French is renowned for its complex verb conjugations and intricate pronunciation, with many silent letters and liaisons. French also has a rich literary tradition and is widely spoken in various parts of the world, particularly in Europe and Africa.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('97ba6811-3d6b-5511-87f7-1b13216d72b5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '97ba6811-3d6b-5511-87f7-1b13216d72b5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4764fc25-f640-5c16-abf9-4e906d0148ed'::uuid, NULL, NULL, E'Students should take the training course to use the gym.', NULL, NULL),
  ('97c418c4-43de-5ac5-b9b3-264864fafb71'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '97c418c4-43de-5ac5-b9b3-264864fafb71'::uuid, 1, NULL, TRUE, 0, NULL, E'Walk in Countryside', E'Your friend Susan suggests having a walk in the countryside tomorrow. You would love to, but you have seen the weather forecast and it might rain tomorrow. You want to wait and see the weather tomorrow morning, and decide then. What would you say to Susan right now?', '8815c799-9c4f-5c18-be6f-35057411b458'::uuid, NULL, E'Hey Susan, I want to talk to you about something.\nWe seem to have a little issue with our countryside walk tomorrow.\nIt''s like I checked the weather forecast and it may rain tomorrow. I think we can check the weather tomorrow morning and make a decision later.\nAnd I''d like to know what you think.', NULL, NULL, NULL),
  ('97c76dda-c571-5af3-8975-6fd648fb4411'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '97c76dda-c571-5af3-8975-6fd648fb4411'::uuid, 1, NULL, TRUE, 0, NULL, E'Maasai Olympics', E'The Maasai people of East Africa have long been celebrated for their distinctive culture and traditions. One of the most unique and transformative events in recent Maasai history has been the introduction of the Maasai Olympics, an initiative that combines sportsmanship with the preservation of cultural heritage.\nTraditionally, Maasai warriors gained honor and prestige through acts of bravery, such as lion hunting. However, as wildlife conservation efforts intensified and lion populations declined, there was a growing need to find alternative ways to demonstrate valor and leadership within the community.\nIn response to these challenges, the Maasai Olympics was born. This biennial event showcases athletic skills in sports like running, spear throwing, and high jump, all inspired by traditional warrior training. The twist is that instead of hunting lions, participants now compete to protect them, as the Maasai people have recognized the importance of wildlife conservation.\nThe Maasai Olympics not only provides a platform for young warriors to display their physical prowess but also promotes environmental conservation and raises awareness about the importance of preserving Africa''s wildlife. It sends a powerful message that cultural heritage and wildlife conservation can go hand in hand.\nThis unique event has not only gained attention within Maasai communities but has also garnered international recognition. It exemplifies how innovative approaches can honor tradition while adapting to the changing times. The Maasai Olympics serves as an inspiring example of how culture, sports, and environmental stewardship can intersect to create a positive impact in the modern world.\nIn conclusion, the Maasai Olympics represents a significant shift in Maasai culture, where the preservation of tradition and wildlife conservation coalesce in a powerful and meaningful way. This event showcases how indigenous communities can adapt and thrive while maintaining their cultural roots and contributing to global conservation efforts.', NULL, NULL, E'The Maasai Olympics, a transformative event in East Africa, creatively merges traditional Maasai warrior skills with wildlife conservation, replacing lion hunting with sports like running, spear throwing, and high jump; this biennial event not only allows young Maasai warriors to exhibit their prowess but also emphasizes the importance of preserving wildlife, demonstrating how cultural heritage and environmental stewardship can coexist harmoniously in the modern world, thereby gaining both local and international acclaim.', NULL, 5, 75),
  ('97cc43a5-aac1-5e53-b9e6-ee90b0fd0c05'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '97cc43a5-aac1-5e53-b9e6-ee90b0fd0c05'::uuid, 1, NULL, TRUE, 0, NULL, E'House or Business', E'You have enough money to purchase either a house or a business. Which would you choose to buy? Give examples to support your idea.', NULL, NULL, NULL, NULL, 200, 300),
  ('97ce8af0-8f55-5858-b3e2-ea4f0f382e70'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '97ce8af0-8f55-5858-b3e2-ea4f0f382e70'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4d18e866-f687-59c3-bbcc-629b1b298d39'::uuid, NULL, NULL, E'Currently the company employs people all over Europe.', NULL, NULL),
  ('97da5df5-602a-5804-abd3-70c7f251f959'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '97da5df5-602a-5804-abd3-70c7f251f959'::uuid, 1, NULL, TRUE, 0, NULL, E'Biodiversity', NULL, NULL, NULL, NULL, E'1, 2, 4, 3', NULL, NULL),
  ('97da96f7-bab9-5449-8328-fd3ea37fb2f7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '97da96f7-bab9-5449-8328-fd3ea37fb2f7'::uuid, 1, NULL, TRUE, 0, NULL, E'Spanish', E'While Spanish is not a commonly heard language in most parts of Africa, Asia, and the majority of Europe, that hasn''t stopped it from becoming the second most commonly spoken language. The spread of the Spanish language is rooted in colonization. Between the 15th and 18th centuries, Spain colonized much of South and Central of North America as well.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('97e23cf7-772f-599f-bb53-1dd82bfb2837'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '97e23cf7-772f-599f-bb53-1dd82bfb2837'::uuid, 1, NULL, TRUE, 0, NULL, E'Double Blind', E'The feature of being “double blind”, where neither patients nor physicians are aware of who receives the experimental treatment, is almost universally trumpeted as being a virtue of clinical trials. Hence, trials that fail to remain successfully double blind are regarded as providing inferior evidential support. The rationale for this view is unobjectionable: double blinding rules out the potential confounding influences of patient and physician beliefs.\nNonetheless, viewing double blind trial as necessarily superior is problematic. For one, it leads to the paradox that very effective experimental treatments will not be supportable by best evidence. If a new drug were to make even the most severe symptoms of the common cold disappear within seconds, most participants and investigators would correctly identify it as the latest wonder drug and not the control (i.e. placebo) treatment. Any trial testing the effectiveness of this wonder drug will therefore fail to remain double blind. Similar problems arise for treatments, such as exercise and most surgical techniques, whose nature makes them resistant to being tested in double blind conditions. It seems strange that an account of evidence should make priori judgments that certain claims can never be supported by ‘best evidence’. It would be different if the claims at issue were pseudoscientific – untestable. But so far as treatments with large effects go, the claim that they are effective is highly testable and intuitively they should receive greater support from the evidence than do claims about treatments with moderate effects.', NULL, NULL, E'The feature of being “double blind” is almost universally trumpeted as being a virtue of clinical trials, so trials that fail to remain successfully double blind are regarded as providing inferior evidential support, but viewing double blind trial as necessarily superior is problematic, as it leads to the paradox that very effective experimental treatments will not be supportable by best evidence, and similar problems arise for treatments.', NULL, 5, 75),
  ('97e748dd-0c9f-5c79-81ea-81b611fc260d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '97e748dd-0c9f-5c79-81ea-81b611fc260d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2d6ff4af-6b04-5e6f-985f-8b127c4a3cca'::uuid, NULL, NULL, E'All students have their own styles of learning.', NULL, NULL),
  ('97eb4487-56c4-53aa-b86c-cf3f6f0c47fa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '97eb4487-56c4-53aa-b86c-cf3f6f0c47fa'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bccca587-c12a-587f-90ae-433a7492ac6d'::uuid, NULL, E'Note-taking methods work greatly both on paper and digitally.', NULL, NULL, NULL),
  ('97f7f043-a7cf-5275-a99d-f546194fd290'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '97f7f043-a7cf-5275-a99d-f546194fd290'::uuid, 1, NULL, TRUE, 0, NULL, E'Crop Rotation', E'Without access to chemical fertilizers, medieval farmers developed and relied heavily on the system of crop rotation to {{1}} the health of their arable land. This agrarian practice was essential for sustaining the ever-growing populations of medieval Europe. Crop rotation involved the cyclic {{2}} of different types of crops on the same plot of land over several seasons or years. This method prevented the {{3}} of specific soil nutrients, as different crops had varying nutrient requirements and effects on the soil composition. Typically, a farmer would plant grain crops, such as wheat or barley, which were nitrogen-consuming, in one year. The following year, the field {{4}} sown with legumes like peas or beans, which had the ability to fix nitrogen back into the soil. In some rotations, the third year would involve leaving the field fallow – unplanted – to allow the land to recover naturally. In other {{5}} , the fallow land would be used for grazing livestock, which helped in manure deposition, further enriching the soil.', NULL, NULL, NULL, E'1.preserve, 2.cultivation, 3.depletion, 4.would be, 5.cases', NULL, NULL),
  ('98064a72-5397-555e-ae3e-369b5dd471f4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '98064a72-5397-555e-ae3e-369b5dd471f4'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call a person who is guilty in terms of law?', '3269f1d7-0afa-569d-a165-e835c94fef55'::uuid, NULL, NULL, E'Convict / criminal / offender', NULL, NULL),
  ('980fa6fb-1ebc-5cd7-98f0-e8909303e4b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '980fa6fb-1ebc-5cd7-98f0-e8909303e4b8'::uuid, 1, NULL, TRUE, 0, NULL, E'Young People', E'Young people are increasingly aware of the challenges and risks {{1}} by the climate crisis and of the opportunity to {{2}} sustainable development. Young people are not only victims of climate change, but they are also {{3}} contributors to climate action. Whether through education, science or technology, young people are {{4}} up their efforts and using their skills to accelerate climate action.', NULL, NULL, NULL, E'1.presented, 2.achieve, 3.valuable, 4.scaling', NULL, NULL),
  ('98127830-00ec-5d43-aa91-97a3357abf52'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '98127830-00ec-5d43-aa91-97a3357abf52'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a celestial event where two astronomical bodies align?', '9e3b3bad-abe9-5972-bad7-43a0066f88ca'::uuid, NULL, NULL, E'Conjunction', NULL, NULL),
  ('98138ff7-b310-5e72-b7a6-7a55fa1b04d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '98138ff7-b310-5e72-b7a6-7a55fa1b04d3'::uuid, 1, NULL, TRUE, 0, NULL, E'Plants and Animals', E'From the earliest civilisations, plants and animals have been portrayed as a means of understanding and recording the potential uses, such as their economic and healing properties. From the first illustrated {{1}} of medicinal plants, De Materia Medica by Dioscorides, in the first century through to the late fourteenth century the illustration of plants and animals changed very little. Woodcuts in instructional manuals and herbals were often repeatedly copied over the centuries, resulting in a loss of definition and accuracy so that they became little more than stylized decoration. With the growing {{2}} of copperplate engravings, the traditional use of woodcuts declined and the representation of plants and animals became more {{3}} . Then, with the emergence of artists such as Albrecht Durer and Leonardo Da Vinci, naturalists such as Otto Brunfels, Leonhard Fuchs in botany and Conrad Gesner and Ulisse Aldrovandi in zoology, nature began to be depicted in a more realistic style. Individual living plants or animals were observed directly and their likeness was {{4}} onto paper or vellum.', NULL, NULL, NULL, E'1.catalogue, 2.popularity, 3.accurate, 4.rendered', NULL, NULL),
  ('9813e413-29f9-5211-af2f-e2eee2175c05'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '9813e413-29f9-5211-af2f-e2eee2175c05'::uuid, 1, NULL, TRUE, 0, NULL, E'City Cleaner', E'Rather than {{1}} at the next beetle or wasp in your way, you might want to thank them-- for helping to keep city streets clean. Researchers from North Carolina State University working in New York City found that hungry urban arthropods play a significant role in the disposal of trash. For example, in a small section of Manhattan called the Broadway/West Street corridor, insects consume the equivalent of 60,000 hot dogs a year that would otherwise be lying in the street. And that''s {{2}} the bugs stop chowing down in winter. To assess how much {{3}} food bugs got rid of, the researchers placed {{4}} amounts of hot dogs, potato chips and cookies at 21 park sites and 24 street medians. Contrary to their prediction, location played an even bigger role in garbage {{5}} than biodiversity did--insects gobbled up two to three times more food in the street medians than they did in the parks. The study appears in the journal Global Change Biology. If all that garbage disposal still does not make you an arthropod admirer, then consider this: by competing with larger pests for resources, insects help keep rat populations down. There''s some food for {{6}} .', NULL, NULL, NULL, E'1.cringing, 2.assuming, 3.discarded, 4.measured, 5.consumption, 6.thought', NULL, NULL),
  ('981a6542-9c88-5739-8723-303e2a4bb28d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '981a6542-9c88-5739-8723-303e2a4bb28d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2e70042d-8670-599b-88c0-37ca177c11f5'::uuid, NULL, NULL, E'She had raised a very important question at the meeting.', NULL, NULL),
  ('98252b7c-2738-5aaf-b2c4-d665163ac344'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '98252b7c-2738-5aaf-b2c4-d665163ac344'::uuid, 1, NULL, TRUE, 0, NULL, E'Coffee', NULL, '1ba2b488-7ad9-524b-a61f-05a18a3a3e98'::uuid, NULL, E'Coffee is a beverage that has not only energized individuals but also transformed societies. Coffee is not just a drink; it''s a global phenomenon that has shaped economic, social, and cultural landscapes. Coffee''s journey from ancient Ethiopian fields to European coffee houses highlights its profound impact. In the 17th and 18th centuries, coffee houses in London and Paris became hubs for intellectual and social gatherings, influencing political and philosophical discourse. They were places where ideas flourished, fostering an environment of innovation and exchange. Moreover, the coffee trade has played a significant role in the global economy. It has been a major commodity in international trade, influencing economies of numerous countries, particularly in Latin America, Africa, and Asia. The industry has also evolved with ethical considerations like fair trade and sustainable farming gaining prominence. In conclusion, coffee''s role extends beyond being a morning staple. It has been a catalyst for social interaction, economic development, and cultural exchange, demonstrating how a simple beverage can have far-reaching global influence.', NULL, NULL, NULL),
  ('9828ac4b-d148-52c9-b083-e788ef6f8300'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9828ac4b-d148-52c9-b083-e788ef6f8300'::uuid, 1, NULL, TRUE, 0, NULL, E'Australia’s Export', NULL, '592dec5c-9815-5272-be76-7a8dbfe60114'::uuid, NULL, E'Thanks for this opportunity to speak about Australia''s engagement with Asia from the perspective of trade and in particular to say a few words about what trade is doing in this, in this space. And I''m particularly pleased to be addressing trade and investment not just of course because these two things are inextricably linked but also of course because Australia reports to Australia''s first ever Minister for trade and investment. Asia''s importance to Australia''s economy is growing by the day. It is one of the most important factors to consider. When assessing the International conditions for national prosperity Asian demand for our exports has helped Australia manage the global financial crisis better than most other developed economies. In fact, probably better than all other developed economies. An investment from Asia has added to the productive capacity of the economy and to overall productivity in 2013. Seven of our top ten export markets were in Asia and represented 65 percent of our total exports. Asian markets and Australia''s geographic proximity are critical not just for our trade ties and our capacity to access important global supply chains, but also to the level of foreign investment in Australia. FDI has grown markedly in Australia over the past decade. In fact it has more than doubled from about two hundred ninety two billion dollars to 630 billion dollars in 2013.', NULL, NULL, NULL),
  ('9831ad87-0fe3-50dd-87a7-82615563110b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9831ad87-0fe3-50dd-87a7-82615563110b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '735c1a3d-08e5-5f62-82a7-2f8cc86f5c03'::uuid, NULL, NULL, E'The library holds a substantial collection of materials on economic history.', NULL, NULL),
  ('9836d43a-61b5-53a9-92e5-4e03bb7a497d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '9836d43a-61b5-53a9-92e5-4e03bb7a497d'::uuid, 1, NULL, TRUE, 0, NULL, E'Teaching and Learning', NULL, NULL, NULL, NULL, E'1, 2, 3, 4', NULL, NULL),
  ('984503f2-6cca-5471-b722-4743a406ba75'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '984503f2-6cca-5471-b722-4743a406ba75'::uuid, 1, NULL, TRUE, 0, NULL, E'Civilization', E'I use the word civilization now for the first time, because before the Bronze Age there is nothing that we would define as civilization. Civilization involves the establishment of permanent dwelling areas that we call {{1}} as opposed to villages. Agricultural villages will have existed all over the place in the late Stone Age, in the Neolithic Period, as it is known. But there is a difference and the critical difference is that a city contains a number of people who do not provide for their own support. That is to say, they don''t {{2}} food. They need to acquire it from somebody else. Instead, they do various things like governing and are priests, and are bureaucrats, and are {{3}} in other nonproductive activities that depend upon others to feed them. That''s the narrowest definition of cities.', NULL, NULL, NULL, E'1.cities, 2.produce, 3.engaged', NULL, NULL),
  ('98456c85-93a8-5a58-b5f7-188666c228f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '98456c85-93a8-5a58-b5f7-188666c228f8'::uuid, 1, NULL, TRUE, 0, NULL, E'Generative Model', E'Today''s technological market is dominated by two contrasting business models: the generative and the non-generative. The generative models - the PCs, Windows, and Macs of this world - allow third parties to build upon and share through them. The non-generative model is more restricted; appliances might work well, but the only entity that can change the way they operate is the vendor.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('98474cd2-22a7-5f9a-bd58-eefd907d4c09'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '98474cd2-22a7-5f9a-bd58-eefd907d4c09'::uuid, 1, NULL, TRUE, 0, NULL, E'Sensitive Skin', E'People with generally sensitive skin have local reactions to chemicals, dyes, and fragrances present in products that come into contact with their skin. They may also get rashes or irritation from clothing or friction. Some people are allergic to certain substances and may react on their skin.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('985020d0-ccd8-511b-8a27-388f0edbd384'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '985020d0-ccd8-511b-8a27-388f0edbd384'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '827f7f8f-52d5-512a-80f2-2c086d1a11c0'::uuid, NULL, NULL, E'Astronauts measure vast space distances in units called light years.', NULL, NULL),
  ('9851f047-c9ab-5589-ae4d-80a3beb34b2a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9851f047-c9ab-5589-ae4d-80a3beb34b2a'::uuid, 1, NULL, TRUE, 0, NULL, E'Tree Frog', E'A miner in the state of Chiapas found a tiny tree frog that has been preserved in amber for 25 million years, a researcher said. If authenticated, the preserved frog would be the first of its kind found in Mexico, according to David Grimaldi, a biologist and curator at the American Museum of Natural History, who was not involved in the find.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9851fd64-0e10-5a1a-abdf-a1c7234bdd83'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9851fd64-0e10-5a1a-abdf-a1c7234bdd83'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7cd4f2c8-21f0-55f4-b57e-97be737882a4'::uuid, NULL, NULL, E'Students will need these reasoning skills in all academic areas.', NULL, NULL),
