  ('98a188e2-21f7-50bc-9198-77ce0034be89'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '98a188e2-21f7-50bc-9198-77ce0034be89'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f85a6ea9-d2e7-54f5-b488-c0f3087b30a2'::uuid, NULL, E'It is important to take gender into account when discussing the figures.', NULL, NULL, NULL),
  ('98a304f1-b8ac-50f3-893c-3ba6aa3b9f89'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '98a304f1-b8ac-50f3-893c-3ba6aa3b9f89'::uuid, 1, NULL, TRUE, 0, NULL, E'McLuhan', E'McLuhan''s preeminent theory was his idea that human history could be {{1}} into four eras: the acoustic age, the literary age, the print age and the electronic age. He {{2}} the concept in a 1962 book called The Gutenberg Galaxy, which was {{3}} just as the television was starting to become popular. He {{4}} the world was entering the fourth, electronic age, which would be {{5}} by a community of people brought together by technology. He called it the "global village", and said it would be an age when everyone had access to the same information through technology. The "global village" could be understood to be the internet.', NULL, NULL, NULL, E'1.divided, 2.outlined, 3.released, 4.predicted, 5.characterized', NULL, NULL),
  ('98a6afb2-2a14-5902-a579-604594709b7b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '98a6afb2-2a14-5902-a579-604594709b7b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '46ed2b57-458e-5f36-afe3-46bcee6e3322'::uuid, NULL, NULL, E'Many cities are actively working on ways to reduce air pollution.', NULL, NULL),
  ('98a7034a-9cb8-59f3-9d1f-762fe6fac2bc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '98a7034a-9cb8-59f3-9d1f-762fe6fac2bc'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What powers electric devices or appliances?', '9e2bebfa-0411-5bcc-8438-ae68dc975fef'::uuid, NULL, NULL, E'Electricity', NULL, NULL),
  ('98a7abc9-f744-5b23-83e4-d6e91cd7dc18'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '98a7abc9-f744-5b23-83e4-d6e91cd7dc18'::uuid, 1, NULL, TRUE, 0, NULL, E'Child Language Acquisition', NULL, '7380708b-5fff-5764-97af-bf8291b48b12'::uuid, NULL, E'Child language acquisition, three little words. So let''s take them on at a time. Child, when to start being a child? For many people, language acquisition starts around about twelve months when kids say that first word, but don''t forget the first year. At the first year, our first year of life is very important as well and indeed before you are born, remember there are couple of months before you are born, when you actually able to perceive in the womb, something of the language that''s around you. So language acquisition starts earlier than most people think. And it also ends later than most people think. When does child language acquisition stop? Well, in a sense, you know, we are all children, we stay being children all in our lives. There is no obvious endpoint for learning sounds, of course, there is for learning grammar, there is for vocabulary, huh. I mean that goes on for the rest of our lives in million or more words in English. Most of us only have a vocabulary of 50, 60, 70 thousand words, whatever it is until there is always something to learn. So remember that two ends of child language acquisition are wider apart than some people think. That means there is more scope for studying in it than most people think.', NULL, NULL, NULL),
  ('98a7ba8c-7a68-5744-9672-56529f6e6322'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '98a7ba8c-7a68-5744-9672-56529f6e6322'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '04353ffa-b688-564f-9b99-e1d7673cd04f'::uuid, NULL, NULL, E'Near the entrance, you will find the building dedicated to chemistry.', NULL, NULL),
