  ('98d876c5-da17-57f1-9fe7-542195c087e8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '98d876c5-da17-57f1-9fe7-542195c087e8'::uuid, 1, NULL, TRUE, 0, NULL, E'Gender Inequality', E'Gender inequality is one of the oldest and most pervasive forms of inequality in the world. It denies women their voices and devalues their work. Despite some important progress to change this in recent years, in no country have women achieved economic equality with men, and women are still more likely to live in poverty.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('98dbffa6-6f36-5ccf-bf5c-a11a98d0f2c3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '98dbffa6-6f36-5ccf-bf5c-a11a98d0f2c3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7e81d499-620f-56f1-8237-6209f6df860b'::uuid, NULL, E'The city''s most shocking statistic is the high infant mortality rate.', NULL, NULL, NULL),
  ('98dc363b-55b3-5dca-b8ee-b96efbcfd65d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '98dc363b-55b3-5dca-b8ee-b96efbcfd65d'::uuid, 1, NULL, TRUE, 0, NULL, E'Nostradamus', E'One of the most interesting and often cited wrong predictions attributed to Nostradamus {{1}} the year 1999. In one of his quatrains, Nostradamus predicted that in "the year 1999, in the seventh month, from the sky will come a great King of Terror" to bring back to life the "great King of the Mongols." Many interpreted this as a prophecy predicting a catastrophic event or the end of the world in July 1999, possibly a nuclear apocalypse or a {{2}} asteroid impact. However, July 1999 came and went without any such cataclysmic events. Critics and scholars argue that this prediction, like many of Nostradamus''s quatrains, is vague and {{3}} to wide interpretation, which has led to numerous speculative and incorrect claims about his foresight into future events. This particular prophecy showcases the complexities and challenges in interpreting Nostradamus''s work, {{4}} the human penchant for finding meaning in ambiguous predictions.', NULL, NULL, NULL, E'1.involves, 2.devastating, 3.subject, 4.as well as', NULL, NULL),
  ('98e3e7f7-21a6-595c-95da-4765872829f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '98e3e7f7-21a6-595c-95da-4765872829f9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1df1d88a-d982-5847-9bba-87d69f15eb66'::uuid, NULL, NULL, E'There is a pharmacy on campus near the bookstore.', NULL, NULL),
