  ('98fd74a4-9edb-5748-a8b3-fe92b1c0796a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '98fd74a4-9edb-5748-a8b3-fe92b1c0796a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '30bc30b6-7f99-58a5-bfa0-f7d017e7189a'::uuid, NULL, NULL, E'The timetable will be posted on the website in the morning.', NULL, NULL),
  ('9900a1e8-69b1-5cd7-aeb0-db3871d87d98'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9900a1e8-69b1-5cd7-aeb0-db3871d87d98'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the act of reusing waste materials?', 'c9c9f034-87aa-50f5-80a4-dc9f110564c8'::uuid, NULL, NULL, E'Recycling', NULL, NULL),
  ('99037dc6-b6f8-5633-a3c8-a17e5e963259'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '99037dc6-b6f8-5633-a3c8-a17e5e963259'::uuid, 1, NULL, TRUE, 0, NULL, E'Large Igneous Province', NULL, '8e9f3c21-9f4d-5b72-8d60-b6b04194dd30'::uuid, NULL, E'Most of us know about an asteroid hitting the Earth and wiping out the dinosaurs, but most people don’t know that the Earth nearly got devastated by a large igneous province that formed in Siberia 250 million years ago. Now, imagine that we had to deal with a colossal LIP like that today. How much damage would it cause? Urban areas would be decimated by the rift, causing extensive destruction. And those quakes? They’re just the preview. Next, the lava makes its grand entrance. Once here, it’s on the warpath. Farmland needed for raising crops would be incinerated. Bodies of water like lakes, streams and rivers would be vaporized if there was enough lava. And depending on how fast the lava flows, endangered species would be wiped out if they couldn’t relocate in time. It would also devastate the economy. Schools, businesses and hospitals would be ravaged, along with infrastructure like highways, power generating facilities, gas lines and water mains. And that beautiful new house you bought? It’s covered in lava. Your new car? It’s under lava. And what about you? Well, according to Oregon State University, lava moves on a flat slope, like Hawaii’s Mount Kilauea, at a maximum of 10 km/h (6.2 mph). The average speed people walk at is 5 km/h (3.1 mph) and average running speed is about 13 km/h (8 mph). So if you were good at track and field, now’s your time to shine.', NULL, NULL, NULL),
  ('9908cfda-33e1-534f-83ce-a63cf763483d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9908cfda-33e1-534f-83ce-a63cf763483d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e9d15c26-7b02-5467-94a1-59561e760efe'::uuid, NULL, NULL, E'Annual reports can give important information on company finances.', NULL, NULL),
  ('9908dd05-32b6-5ece-a451-bb391976cff8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9908dd05-32b6-5ece-a451-bb391976cff8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the activity of inhaling tobacco substances?', 'e16cd581-45f7-547a-9d85-ced7f5b06a29'::uuid, NULL, NULL, E'Smoking', NULL, NULL),
  ('990a6f73-32bb-5207-aa96-937b96dce67c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '990a6f73-32bb-5207-aa96-937b96dce67c'::uuid, 1, NULL, TRUE, 0, NULL, E'Global Warming', E'The world is set to {{1}} enough carbon to exceed the 1.5°C global warming target within the next 10 years, according to a new analysis from the United Nations. National climate plans submitted to the UN outlining emissions cuts between now and 2030 are {{2}} near ambitious enough to limit warming to 1.5°C, the UN’s climate change secretariat warned. On the current {{3}} , the planet’s average temperature will reach 2.5°C above pre-industrial levels by the end of the century, {{4}} through even the upper threshold of 2°C of warming set by the Paris Agreement. Scientists warn that this level of warming could {{5}} tipping points that would spark runaway climate change. The latest synthesis report from the UN assesses the impact of climate plans submitted under the UN process. Since last year’s analysis, some progress has been made, with global emissions now set to peak by the end of the decade.', NULL, NULL, NULL, E'1.emit, 2.nowhere, 3.trajectory, 4.blasting, 5.trigger', NULL, NULL),
  ('990e17ce-2c4f-538f-ac64-d95d374be899'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '990e17ce-2c4f-538f-ac64-d95d374be899'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '811fe4ed-1a00-52bf-b43b-22c8abb76443'::uuid, NULL, E'The designer will be unveiling her latest fashions for autumn and winter.', NULL, NULL, NULL),
