  ('9910d7bb-b220-5fd7-8c33-7c8c252a5f45'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '9910d7bb-b220-5fd7-8c33-7c8c252a5f45'::uuid, 1, NULL, TRUE, 0, NULL, E'Napoleon', NULL, NULL, NULL, NULL, E'2, 3, 1, 4', NULL, NULL),
  ('99136541-398e-5dfd-abcf-2ee1c70261a0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '99136541-398e-5dfd-abcf-2ee1c70261a0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '15443a80-ac02-5945-9935-e187eec1ee4e'::uuid, NULL, E'The airport is being privately funded by a construction group.', NULL, NULL, NULL),
  ('991cac43-afe3-56a6-9bfe-47e41020bc6e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '991cac43-afe3-56a6-9bfe-47e41020bc6e'::uuid, 1, NULL, TRUE, 0, NULL, E'Career Planning', NULL, NULL, NULL, NULL, E'1, 4, 3, 2', NULL, NULL),
  ('991cb846-eed0-5d72-913d-7b25e55b5bf9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '991cb846-eed0-5d72-913d-7b25e55b5bf9'::uuid, 1, NULL, TRUE, 0, NULL, E'Oxford Course', E'When I enrolled in my master''s course at Oxford last year, I had come straight from medical school with the decision to leave clinical science for good. Thinking back, I realize that I didn''t put very much {{1}} on this decision at the time. But today, I more clearly understand the {{2}} of leaving my original profession. When I meet old friends who are now physicians and surgeons, I sense how our views on medical problems have {{3}} .They scrutinize the effects of disease and try to eliminate or alleviate them; I try to understand how they come about in the first place. I feel happier working on this side of the problem, although I do occasionally miss clinical work and seeing patients. However, when I think about the rate at which my medical skills and knowledge have {{4}} , the years spent reading weighty medical textbooks, the hours spent at the bedside, I sometimes wonder if these years were partly a {{5}} of time now that I am pursuing a research career. Nonetheless, I know the value of my medical education. It is easy to forget the importance of the biosciences when working with model organisms in basic research that seem to have nothing to do with a sick child or a suffering elderly person. Yet, I still have vivid memories of the cruel kaleidoscope of severe diseases and of how they can {{6}} a human being. I hope to retain these memories as a guide in my current occupation.', NULL, NULL, NULL, E'1.weight, 2.consequences, 3.diverged, 4.dissipated, 5.waste, 6.strike', NULL, NULL),
  ('992559a6-d9ab-5066-acf3-99727a9daebf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '992559a6-d9ab-5066-acf3-99727a9daebf'::uuid, 1, NULL, TRUE, 0, NULL, E'The World', E'A good way to make sure that people police themselves is to get them to {{1}} essentially the same stories about what the world is and why the way it is good, {{2}} and beautiful. The world needs to be {{3}} , and needs to be justified by arguments about nature, philosophical principle, history or the gods. People will find their {{4}} in such a world. They will learn {{5}} hopes they might reasonably hold for themselves.', NULL, NULL, NULL, E'1.believe, 2.true, 3.described, 4.place, 5.what', NULL, NULL),
  ('99324319-c3e3-5e8b-935c-8c6b7f06a303'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '99324319-c3e3-5e8b-935c-8c6b7f06a303'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6da769bd-0a41-5fb8-bdd6-8b86f8bb8096'::uuid, NULL, NULL, E'Living in apartments near campus can be very convenient for students.', NULL, NULL),
  ('993792be-ba68-598e-b772-910b1c230360'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '993792be-ba68-598e-b772-910b1c230360'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'feb59a57-61b4-5830-868e-9712cd3e1847'::uuid, NULL, NULL, E'Some of the farmland has been devastated by floods and droughts.', NULL, NULL),
  ('993e9fbb-f5a3-5a5c-a5a4-31a37cb126b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '993e9fbb-f5a3-5a5c-a5a4-31a37cb126b2'::uuid, 1, NULL, TRUE, 0, NULL, E'Connective Tissue Cells', E'Connective tissue cells provide structural strength to the body and also defend against foreign invaders like bacteria. Two types of cells are native to connective tissue. Other cells migrate into connective tissue from the bloodstream to fight diseases. Special types of connective tissue are designed to be stronger and more rigid than most connective tissues.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('993fffa2-1e39-5ca9-982a-cfc126813d5c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '993fffa2-1e39-5ca9-982a-cfc126813d5c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5b02ea9c-4e11-5099-aa37-4a3591198bd9'::uuid, NULL, NULL, E'The student magazine is looking for a new editor.', NULL, NULL),
  ('99446765-2155-5c6f-95d7-30e571fe12b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '99446765-2155-5c6f-95d7-30e571fe12b8'::uuid, 1, NULL, TRUE, 0, NULL, E'Renewable Energy', E'To what extent do you think renewable energy research should be funded by governments?', NULL, NULL, E'The funding of renewable energy research by governments is essential for addressing environmental challenges and transitioning towards sustainable energy sources. It plays a crucial role in promoting a cleaner environment and reducing carbon emissions, contributing to a healthier planet and a more sustainable future.\nInvesting in renewable energy research is not just about reducing carbon emissions; it is a fundamental step towards safeguarding our environment for future generations. By directing resources toward the development of renewable energy sources like solar and wind power, governments can significantly diminish our dependence on fossil fuels, thereby curbing greenhouse gas emissions and preserving the planet''s ecological balance.\nMoreover, the funding of renewable energy research serves as a catalyst for innovation and progress in the renewable energy sector. Government support incentivizes researchers and industry professionals to explore cutting-edge technologies and enhance existing solutions. This commitment drives advancements in renewable energy production efficiency and cost-effectiveness, paving the way for a more sustainable and environmentally conscious energy landscape.\nIn conclusion, government backing for renewable energy research not only contributes to environmental preservation through reduced carbon emissions but also fuels innovation and economic growth. By investing in renewable energy initiatives, governments have the opportunity to create employment opportunities, stimulate economic development, and lay the foundation for a sustainable and greener future that benefits both current and future generations.', NULL, 200, 300),
  ('994a02be-317f-5691-ae1b-2a5f6c81482b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '994a02be-317f-5691-ae1b-2a5f6c81482b'::uuid, 1, NULL, TRUE, 0, NULL, E'Seasonal Changes', NULL, NULL, NULL, NULL, E'5, 3, 1, 4, 2', NULL, NULL),
  ('994d66cf-7c26-55de-b415-0b3d8da53b4a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '994d66cf-7c26-55de-b415-0b3d8da53b4a'::uuid, 1, NULL, TRUE, 0, NULL, E'Ancient Farming', E'When humans began farming some 12,000 years ago, they altered the future of our {{1}} forever. Our ancestors were ecological {{2}} , discovering and cultivating the most valuable crops, scaling them up to feed entire communities, and transforming wild crops so fundamentally that they became dependent on humans for their survival. Farming, in the words of National Geographic’s Genographic Project, “sowed the seeds for the modern {{3}} ".', NULL, NULL, NULL, E'1.species, 2.pioneers, 3.age', NULL, NULL),
  ('994eb75a-ee0d-5749-bac6-b1e32fe1549c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '994eb75a-ee0d-5749-bac6-b1e32fe1549c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0d677c1c-b952-55d8-bd48-821100e724e5'::uuid, NULL, E'First of all, a lot of students don''t even know how to type very fast.', NULL, NULL, NULL),
  ('99559cbe-e687-5c89-b46f-83944d90f120'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '99559cbe-e687-5c89-b46f-83944d90f120'::uuid, 1, NULL, TRUE, 0, NULL, E'Solid Waste Management', NULL, NULL, NULL, NULL, E'1, 4, 3, 2', NULL, NULL),
  ('9955de06-b63d-514e-8e5f-a7b7b83b9edb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9955de06-b63d-514e-8e5f-a7b7b83b9edb'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '62225cfe-83fd-5d7e-8cf1-480888d22802'::uuid, NULL, E'An extra lecture is about to be scheduled at the end of this week to assist you with revision.', NULL, NULL, NULL),
  ('9958315e-313d-5ce5-9a5c-089a88406918'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '9958315e-313d-5ce5-9a5c-089a88406918'::uuid, 1, NULL, TRUE, 0, NULL, E'Typing', E'Some schools believe that children should learn typing rather than handwriting. To what extent do you agree with that? Give reasons with your experience.', NULL, NULL, NULL, NULL, 200, 300),
  ('9972c880-2972-54ef-9428-85aacf3b2f52'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9972c880-2972-54ef-9428-85aacf3b2f52'::uuid, 1, NULL, TRUE, 0, NULL, E'Tipping Etiquette', E'Travel planning is all about the details. But while you may be a master at uncovering the cleanest hotels and practicing proper airplane etiquette, there’s an element of being a guest that stumps even the savviest of travelers. Tipping etiquette — who to tip and how much of a tip to give — can be confusing.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9975f16c-1f73-5721-afb3-9779d55afe82'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9975f16c-1f73-5721-afb3-9779d55afe82'::uuid, 1, NULL, TRUE, 0, NULL, E'Food Insecure Americans', NULL, 'b4c4ef21-4622-5330-89a7-b2004957b5d5'::uuid, NULL, E'You could put a Trader Joe’s or Walmart on every corner, and food insecurity could still not afford to eat, or to buy what they should be eating. Why? Because America’s food system is designed from the farm bill on up to make calories cheap and nutrition expensive. That’s why the face of hunger in America today is an obese person. Food insecure Americans are forced to fill up on food that’s loaded with sugar, fat, sodium, little nutrition. Hence the answer isn’t a full stomach, it’s a healthy meal. So my next learning was about money. Nonprofits tend to spend 75 percent of management’s time in fund raising. They do great work. It’s the air they breathe. But... funder fatigue sets in, funding dries up. So I wondered instead of seeking donors to continually fund our mission. Year after year, would it be possible to have a mission that could fund itself? Well, we did something interesting, we actually went into a food insecure neighborhood, and ask the people what they wanted. And they said, we don’t want handouts, we want to buy tasty nutritious food we can afford. We’re not looking for charity, we’re buying food now, we want to keep buying food. Don’t make your store needs-based, everybody should be able to shop there. We don’t want to feel stigmatized by shopping in a store that’s just for poor people. Another light bulb, turns out people are even hungrier to keep their dignity than for nutrition, which means we can use the dignity problem to help solve the funding problem.', NULL, NULL, NULL),
  ('99798b8e-e640-5072-8cbe-974a7223e8b6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '99798b8e-e640-5072-8cbe-974a7223e8b6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2b329caf-a50d-52aa-83c7-d657202c47df'::uuid, NULL, E'Understanding the historical context will help you appreciate the art in this era.', NULL, NULL, NULL),
  ('997e24ec-f37f-5adb-9d07-b881ed8ffa08'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '997e24ec-f37f-5adb-9d07-b881ed8ffa08'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the dirty water from homes and factories, which flows away through sewers?', 'a159c6bc-5f5d-5c7a-9941-21ce94506534'::uuid, NULL, NULL, E'Sewage / effluent / slop', NULL, NULL),
  ('998b4e05-2f7b-57ad-bee5-ad1fe3b362b7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '998b4e05-2f7b-57ad-bee5-ad1fe3b362b7'::uuid, 1, NULL, TRUE, 0, NULL, E'Native Australians', E'Native Australians, {{1}} referred to as Aboriginal Australians, have a rich and diverse culture that dates back over 65,000 years, making them one of the oldest continuous cultures on Earth. They comprise various groups, each with its own languages, traditions, and territories, ranging from the Torres Strait Islanders of the islands between Australia and New Guinea to the many Aboriginal groups throughout the Australian mainland. {{2}} European settlement in the late 18th century, Aboriginal Australians lived as hunter-gatherers with a complex social {{3}} and spiritual beliefs deeply connected to the land, which they consider sacred. Their knowledge of the environment, reflected in practices such as fire-stick farming and the creation of complex fish traps, demonstrates an intricate understanding of ecology and sustainable living. Despite the profound impact of colonization, including dispossession, disease, and cultural disruption, Aboriginal Australians have {{4}} a vast array of cultural practices, languages, and ceremonies, actively contributing to Australian society and tirelessly advocating for recognition, rights, and reconciliation.', NULL, NULL, NULL, E'1.commonly, 2.Before, 3.structure, 4.preserved', NULL, NULL),
  ('998bb977-a069-554a-b425-012191cb4c03'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '998bb977-a069-554a-b425-012191cb4c03'::uuid, 1, NULL, TRUE, 0, NULL, E'Glamorous Person', E'Who do you think is the most glamorous person? A biotechnologist who led his company in international research, an ordinary welder who gained international fame through his work, or a photographer complimented widely for a series of photos?', NULL, NULL, NULL, NULL, NULL, NULL),
  ('999166b2-ca81-51c6-a656-529c9894af3d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '999166b2-ca81-51c6-a656-529c9894af3d'::uuid, 1, NULL, TRUE, 0, NULL, E'Not-for-profit University', E'A university is not a business. More precisely, a not-for-profit college or university is significantly different than a for-profit business. A university has no owners and it is a public trust. A business has a single over-riding goal: the maximization of return for the owners. A university has a multiplicity of goals: to foster learning, to create knowledge, and to serve its community.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9993909a-6e8b-599e-9808-7b989ad58d5e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '9993909a-6e8b-599e-9808-7b989ad58d5e'::uuid, 1, NULL, TRUE, 0, NULL, E'Snakes’ Bite', E'Some people who are bitten by snakes (or suspect or imagine that they have been bitten) may develop quite striking symptoms and signs, even when no venom has been {{1}} . This results from an understandable fear of the consequences of a real venomous bite. Anxious people may hyperventilate so that they develop pins-and-needles {{2}} in the extremities, spasm of their hands and feet, and dizziness. Some may develop vasovagal shock after the bite or suspected bite, with faintness and collapse with profound slowing of the heart. Others may become highly agitated and {{3}} and may manifest a wide range of misleading symptoms. The clinical {{4}} of a snakebite victim varies with the age and size of the patient, the species of snake, the number and location of the bites, and the quantity and toxicity of the venom.', NULL, NULL, NULL, E'1.injected, 2.sensation, 3.irrational, 4.presentation', NULL, NULL),
  ('999b11b8-f7f1-5796-a91f-43dbf2b52092'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '999b11b8-f7f1-5796-a91f-43dbf2b52092'::uuid, 1, NULL, TRUE, 0, NULL, E'Learning Method', E'There is no single method of learning that guarantees success. How we learn that depends on many different factors. And what works best for you will not necessarily be the same as the approach used for the other students even if they study the same course. We are all unique as learners, although some patterns emerge from any groups of students.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('99a1c8a2-f426-5173-b58d-2d6950e028c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '99a1c8a2-f426-5173-b58d-2d6950e028c5'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the crime of deliberately setting fire to buildings?', '79d0d4b0-3c39-5e06-82e8-5191259887d0'::uuid, NULL, NULL, E'Arson', NULL, NULL),
  ('99a4c0d7-040b-516b-b35b-5ba947138351'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '99a4c0d7-040b-516b-b35b-5ba947138351'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call a notice of death in a newspaper?', '614d9d5f-06cb-5550-9a11-4b9dd9086ed2'::uuid, NULL, NULL, E'Obituary', NULL, NULL),
  ('99a558d2-d869-5c31-926a-109e81947854'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '99a558d2-d869-5c31-926a-109e81947854'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What term describes a society''s way of passing down knowledge, values, and traditions over time?', '58666dcb-3d12-5789-b2d4-29b85414540b'::uuid, NULL, NULL, E'Cultural Heritage', NULL, NULL),
  ('99a61589-2038-50c0-8f70-87b32eb84852'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '99a61589-2038-50c0-8f70-87b32eb84852'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ea6801b2-293c-5713-ab6f-4cad23b1c66d'::uuid, NULL, NULL, E'Attracting skilled workers to the city with expensive housing is hard.', NULL, NULL),
  ('99a65423-a5cf-56e3-a242-b1e6b49af307'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '99a65423-a5cf-56e3-a242-b1e6b49af307'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '86b49562-4be7-51d1-b5fa-1004914fd90c'::uuid, NULL, NULL, E'There is a list of dedicated librarians available during teaching time each term.', NULL, NULL),
  ('99a77c62-a67f-5936-833a-69fab28a966d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '99a77c62-a67f-5936-833a-69fab28a966d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8e167fed-d7ea-5433-af78-70b1e4dcb661'::uuid, NULL, NULL, E'Artificial intelligence has made significant progress in the last few years.', NULL, NULL),
  ('99a7a54d-6225-53fb-83e5-1730d83f7e33'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '99a7a54d-6225-53fb-83e5-1730d83f7e33'::uuid, 1, NULL, TRUE, 0, NULL, E'Coral Bay', E'The once-thriving coastal town of Coral Bay was a jewel of biodiversity, its coral reefs a {{1}} for marine life and a magnet for eco-tourists. Each year, from spring through fall, the clear, warm waters played host to an array of sea creatures, from gentle sea turtles to colorful schools of fish, drawing divers and nature enthusiasts from across the globe. The local economy flourished on this {{2}} , with dive operators, eco-lodges, and seafood restaurants thriving on the steady stream of visitors. However, the turn of the century marked the onset of a grave environmental {{3}} . Successive coral bleaching events, driven by rising ocean temperatures and unchecked pollution, decimated the reefs. The vibrant underwater communities dwindled, leading to a dramatic fall in tourist arrivals and a subsequent economic downturn for the town. The stark decline served as a grim {{4}} of the fragile interdependence between human activities and natural ecosystems. Efforts {{5}} the reefs and restore Coral Bay''s former glory are underway, involving conservationists and the local community in a challenging battle against climate change and environmental degradation.', NULL, NULL, NULL, E'1.haven, 2.influx, 3.crisis, 4.reminder, 5.to revive', NULL, NULL),
  ('99a829c0-d87b-519e-9249-dc6068d16505'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '99a829c0-d87b-519e-9249-dc6068d16505'::uuid, 1, NULL, TRUE, 0, NULL, E'Conservation Scientists', E'Conservation scientists have long tried to map how much of the planet remains undegraded by human activity. Previous estimates using satellite imagery or raw demographic data found anywhere from 20 to 40 percent of the globe was free from obvious human incursions, such as roads, light pollution or the gaping scars of deforestation. But an intact forest canopy can hide an emptied-out ecosystem below.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('99a8d13b-7094-5d9b-a7be-391cc31b8ed8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '99a8d13b-7094-5d9b-a7be-391cc31b8ed8'::uuid, 1, NULL, TRUE, 0, NULL, E'Financial Adviser Anxiety', E'Financial adviser anxiety can stem from a fear of being {{1}} about your lack of financial knowledge or the current {{2}} of your finances. It can encompass feelings of shame or {{3}} , and also a discomfort at the prospect of sharing personal information. The industry itself arguably hasn’t always helped itself – all too often presenting an image of sombre advisers {{4}} in suits and talking in jargon.', NULL, NULL, NULL, E'1.judged, 2.state, 3.guilt, 4.dressed', NULL, NULL),
  ('99b239f8-d224-54f9-b0fb-74ea3551ea78'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '99b239f8-d224-54f9-b0fb-74ea3551ea78'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '41b30398-5480-56ac-9761-e449f6b7f99b'::uuid, NULL, NULL, E'Big companies changed their rules after reports about them came out.', NULL, NULL),
  ('99cc2c46-1865-550b-a1bb-6c96d40d2e40'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '99cc2c46-1865-550b-a1bb-6c96d40d2e40'::uuid, 1, NULL, TRUE, 0, NULL, E'Plant Hormones', E'Listen to a lecture in a botany class. The professor is talking about plant hormones. The word ‘hormone’ is derived from a greek verb, that means to excite. Hormones are found in all multicellular organisms and function to coordinate the parts of the organism. A hormone is a chemical signal. It''s produced by one part of the body, and is then transported to other parts of the body, where it triggers responses in cells and tissues. The concept of chemical messengers in plants first emerged from a series of classic experiments on how plant stems respond to light. Think about this. A house plant on a window sill grows toward light. If you rotate the plant, it will soon reorient its growth until its leaves again face the window. The growth of a plant toward light is called phototropism. In a forest or other natural ecosystem where plants may be crowded, phototropism directs growing seedlings toward the sunlight that powers photosynthesis. Some of the earliest experiments on phototropism were conducted in the late nineteenth century by Charles Darwin and his son, Francis. The Darwins observed that a grass seedling could bend toward light only if the tip of the shoot was present. If the tip was removed, the shoot would not curve toward light. The seedling would also fail to grow toward light if the tip was covered with an opaque cap. The Darwins proposed the hypothesis that some signal was transmitted downward from the tip into the part of the stem that controlled growth. Later experiments by other scientists studying phototropism led to the discovery of chemical messengers that stimulated growth in the stem. These chemical messengers were hormones.\n\nWhat do plant hormones do?', 'c24ddb00-e697-5d3b-af86-6a806bcd6b1b'::uuid, NULL, NULL, E'Stimulate responses in cells and tissues', NULL, NULL),
  ('99cc4661-eb56-58fa-81ed-9640fedd4bbc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '99cc4661-eb56-58fa-81ed-9640fedd4bbc'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the longest mountain range in the world?', '534d5c01-395d-5068-8fe5-483b50c1da50'::uuid, NULL, NULL, E'Andes', NULL, NULL),
  ('99cc656e-bc97-51ea-aaeb-05aa647948ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '99cc656e-bc97-51ea-aaeb-05aa647948ee'::uuid, 1, NULL, TRUE, 0, NULL, E'Movie or Television', E'Movies and television have a bad influence on people’s behaviors. To what extent do you agree with this statement?', NULL, NULL, E'Movies and television have long been criticized for their supposed negative influence on people''s behaviors. However, I disagree with this statement and believe that movies and television do not have a bad influence on people''s behaviors, for several reasons.\nFirstly, movies and television are a form of entertainment that allows individuals to explore different perspectives and experiences without actually engaging in harmful behaviors. For example, watching a movie about drug addiction can raise awareness and understanding about the issue, without actually encouraging drug use.\nSecondly, movies and television can provide positive role models and messages that inspire individuals to make positive changes in their lives. For instance, watching a movie about overcoming adversity can motivate individuals to persevere through their own challenges.\nMoreover, movies and television can serve as a way for individuals to process and cope with difficult emotions and experiences. Watching a movie or TV show that deals with similar issues can provide a sense of catharsis and help individuals feel less alone in their struggles.\nIn conclusion, while some people may argue that movies and television have a bad influence on people''s behaviors, I believe that they do not. Movies and television can provide a safe way for individuals to explore different perspectives, inspire positive change, and cope with difficult emotions and experiences. Therefore, it is important to approach movies and television as a form of entertainment and education, rather than as a negative influence on behavior.', NULL, 200, 300),
  ('99ccf348-ded4-587a-822c-6fecf567782b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '99ccf348-ded4-587a-822c-6fecf567782b'::uuid, 1, NULL, TRUE, 0, NULL, E'Loggerhead Turtle', E'It’s time for this young loggerhead turtle to go to work. We can tether turtles in these little cloth harnesses, put them into this tank and dull swimming place. University of North Carolina biologist Ken Loman studies sea turtles that are programed from birth for an extraordinary journey. Mother turtles buried the eggs on the beach and then returned to the sea and the eggs hatch about 50 to 60 days later.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('99d7131b-6b10-597c-b6b3-4c14210b639c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '99d7131b-6b10-597c-b6b3-4c14210b639c'::uuid, 1, NULL, TRUE, 0, NULL, E'Dolphins', E'Dolphins are marine mammals found all over the world. There are many {{1}} species. They are well-known as intelligent creatures and seem to {{2}} with one another in sophisticated ways. Dolphins are {{3}} animals in that they live in groups. These can {{4}} in size from five to several hundred. They often hunt in groups and work together to {{5}} the fish or squid they like to eat.', NULL, NULL, NULL, E'1.different, 2.communicate, 3.sociable, 4.range, 5.capture', NULL, NULL),
  ('99d8a2f3-24f0-53f2-8985-3212d3422300'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '99d8a2f3-24f0-53f2-8985-3212d3422300'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '601c889b-fcc3-53c5-b5e0-666da1685d45'::uuid, NULL, NULL, E'Your summary should be as clear and concise as possible.', NULL, NULL),
