  ('99e953e5-a508-5b44-a2cb-8ede6a0e9621'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '99e953e5-a508-5b44-a2cb-8ede6a0e9621'::uuid, 1, NULL, TRUE, 0, NULL, E'Bad Day', E'You all have those days when nothing seems to go right. You oversleep, miss your train, spill coffee on your shirt, and face one obstacle after {{1}} . You feel like the universe is conspiring against you and you wonder why you are so unlucky. But don’t despair. There are ways to bounce back from a bad day and {{2}} your luck around. The first step is to acknowledge and embrace the reality of your situation, without resisting or {{3}} it. Accepting your feelings and emotions can reduce your stress and suffering, and help you {{4}} on. The next step is to examine what went wrong and focus on what you can change and control, and take proactive steps to prevent or mitigate future problems. The final step is to {{5}} yourself with kindness and compassion. Do something that makes you happy and relaxed, such as reading a book, taking a bath, or listening to music. Self-care can help you recharge and reset, and prepare you for a better tomorrow.', NULL, NULL, NULL, E'1.another, 2.turn, 3.denying, 4.move, 5.treat', NULL, NULL),
  ('99ea9017-a3ba-5691-9a77-ee8197d943b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '99ea9017-a3ba-5691-9a77-ee8197d943b8'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'baa4224f-a0fc-5c68-aa5d-026e6a771157'::uuid, NULL, E'Information systems can simplify or complicate a problem.', NULL, NULL, NULL),
