  ('99fb5921-9a12-551d-af89-774b0f6d4b99'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '99fb5921-9a12-551d-af89-774b0f6d4b99'::uuid, 1, NULL, TRUE, 0, NULL, E'Air Pollution', E'The government is proposing a new initiative to address the issue of air pollution in urban areas. The initiative aims to identify and mitigate the sources of pollution, reduce the impact of air pollution on public health, and improve air quality in cities. This program will require collaboration between different stakeholders, including government agencies, businesses, and citizens.', NULL, NULL, NULL, NULL, NULL, NULL),
