  ('9b1d738a-942f-5a57-a52b-5e5eaa15c68c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9b1d738a-942f-5a57-a52b-5e5eaa15c68c'::uuid, 1, NULL, TRUE, 0, NULL, E'Hydrogen Production', E'A solar fuels generation research program is focused on hydrogen production by means of reactive metal water splitting in a cyclic iron-based redox process. Iron-based oxides are explored as an intermediary reactive material to dissociate water molecules at significantly reduced thermal energies.', NULL, NULL, NULL, NULL, NULL, NULL),
