  ('9ba15764-4de1-5ce4-b969-ce35d7c70d57'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9ba15764-4de1-5ce4-b969-ce35d7c70d57'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call the people who visit sightseeing locations?', '48bde544-255f-5dc8-bed6-eabfaf9ff9c6'::uuid, NULL, NULL, E'Tourists', NULL, NULL),
  ('9ba423c0-8c61-5202-86c3-c872a87e1414'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9ba423c0-8c61-5202-86c3-c872a87e1414'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a83d0447-1b00-5943-800f-700afebc0c71'::uuid, NULL, E'He studies and observes the behavior of babies and has written many articles about it.', NULL, NULL, NULL),
  ('9ba46c9f-fbeb-58a8-ad13-36250039db99'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9ba46c9f-fbeb-58a8-ad13-36250039db99'::uuid, 1, NULL, TRUE, 0, NULL, E'Experience Economy', NULL, '36683cad-6a7f-5ea1-a1c6-3e5c1aa5ae82'::uuid, NULL, E'Joe has written a book called ''The Experience Economy''. Well what''s happened is we''ve gone from an agrarian economy based off commodities through an industrial economy based off goods, through a service economy. And today we''re in an experience economy. What experiences really do is that they engage everyone inside of them. Living in the digital age that we are now, there''s more need than ever for people to connect. And the digital age also means we can document these experiences. And of course show them off online. We take selfies not because we think we''re going to get the perfect picture, but because we were there and it proves that we were there. These are similar to that souvenir that you picked up on your seaside holiday that means absolutely nothing to anybody else but is so important to you.', NULL, NULL, NULL),
  ('9ba472ec-ea15-5718-a315-1149534c6fa3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '9ba472ec-ea15-5718-a315-1149534c6fa3'::uuid, 1, NULL, TRUE, 0, NULL, E'Hotel Reservation', E'In modern luxury hotels, remote check-in {{1}} allow guests to skip the front desk and access their rooms directly using their smartphones without a key, removing the need for a physical {{2}} . This convenient feature enhances the overall {{3}} for guests, allowing them to enjoy a more relaxing and seamless stay.', NULL, NULL, NULL, E'1.functions, 2.queue, 3.experience', NULL, NULL),
  ('9ba87458-5184-521d-b3bd-81c0b01bdd4e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9ba87458-5184-521d-b3bd-81c0b01bdd4e'::uuid, 1, NULL, TRUE, 0, NULL, E'Mosquitoes', E'How mosquitoes seek out and feed on their hosts are important factors in how a virus circulates in nature. Mosquitoes spread diseases by acting as carriers of viruses and other pathogens: A mosquito that bites a person infected with a virus can acquire the virus and pass it on to the next person it bites.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9bae1619-c754-5617-afef-8461a6446f77'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '9bae1619-c754-5617-afef-8461a6446f77'::uuid, 1, NULL, TRUE, 0, NULL, E'Trinity Sport and Fitness', E'Whether you want to exercise and stay {{1}} , train professionally with like-minded people, or indulge your competitive streak, Trinity Sport and Fitness {{2}} .\nWe''ve got a dedicated support development team on campus to support every student {{3}} part in sports.\nYou might want to participate in sports competitions volunteer with a local sports class or simply play for {{4}} with our social sport program.\nTrinity fitness members of our public-facing sports facility will also {{5}} you to discounts when you are booking a sports facility and fitness class. You will also get an opportunity to {{6}} from tailored personal training, free activities events, and lots more.', NULL, NULL, NULL, E'1.healthy, 2.has it covered, 3.taking, 4.fun, 5.entitle, 6.benefit', NULL, NULL),
  ('9bae3813-6d0b-5c1e-bc56-a1cf24f2e226'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '9bae3813-6d0b-5c1e-bc56-a1cf24f2e226'::uuid, 1, NULL, TRUE, 0, NULL, E'Impact on Agriculture', E'What is your opinion on the impact of climate change on global agriculture?', NULL, NULL, E'I firmly believe that climate change exerts a profound impact on global agriculture, manifesting in altered temperature and precipitation patterns, increased pest pressures, and the heightened frequency of extreme weather events. These challenges reshape agricultural landscapes, posing threats to crop growth, pest management, and food security worldwide.\nClimate change alters temperature and precipitation patterns, disrupting traditional agricultural practices and impacting crop growth and productivity. Fluctuating temperatures and irregular rainfall patterns lead to water stress, affecting crop yields and quality. Concurrently, shifts in climate conditions create favorable environments for the spread of pests and diseases, threatening agricultural crops. Warmer temperatures and altered rainfall patterns contribute to the proliferation of pests, jeopardizing crop health and yield.\nThe escalating frequency of extreme weather events such as droughts and floods exacerbates food insecurity by causing crop losses and disruptions in agricultural systems. Droughts lead to water scarcity and diminished crop yields, while floods result in soil erosion and crop damage. These weather extremes amplify food insecurity, highlighting the vulnerability of global agriculture to the impacts of climate change.\nIn conclusion, the multifaceted impacts of climate change on global agriculture underscore the urgency of implementing adaptive strategies and sustainable practices to mitigate risks and enhance resilience in food production systems. Addressing the challenges posed by climate change demands collaborative efforts, innovative solutions, and a steadfast commitment to sustainable agriculture practices to safeguard food security and ensure a resilient future for agriculture amidst a changing climate.', NULL, 200, 300),
