  ('9c46bf62-1928-5c73-b509-a55eee8a0201'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9c46bf62-1928-5c73-b509-a55eee8a0201'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd16d4956-079a-5c70-b98f-9538b97dc3dc'::uuid, NULL, NULL, E'You need to hand in the essay next semester.', NULL, NULL),
  ('9c476382-bab8-520f-bf14-f9a8e7680d5e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9c476382-bab8-520f-bf14-f9a8e7680d5e'::uuid, 1, NULL, TRUE, 0, NULL, E'Late for Appointment', E'You are thirty minutes late for your doctor''s appointment at 10 am. You need to explain to the receptionist and ask if the doctor could see you later today. What would you say to the receptionist?', '4fdcb539-af5a-59b2-af02-461f38c42563'::uuid, NULL, E'Respected receptionist, I hope you are doing well.\nI would like to discuss an issue we have encountered with my medical appointment.\nIt appears that I am thirty minutes late for my 10 am doctor''s appointment, and I wonder if the doctor can see me later today.\nI would appreciate your opinion on this matter. Thank you for your consideration.', NULL, NULL, NULL),
  ('9c4ac556-982e-5d90-a0b5-6056310423cb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9c4ac556-982e-5d90-a0b5-6056310423cb'::uuid, 1, NULL, TRUE, 0, NULL, E'Fake News', E'Fake news can distort people''s beliefs even after being debunked. For example, repeated over and over, a story such as the one about the Pope endorsing Trump can create a glow around a political candidate that persists long after the story is exposed as fake. A 2017 study published in the journal Intelligence suggests that some people may have an especially difficult time rejecting misinformation.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9c4fd28b-b1c0-5d6d-b505-e5b425fe43df'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9c4fd28b-b1c0-5d6d-b505-e5b425fe43df'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which type of meal is usually eaten outdoors, picnic or buffet?', 'eb4bab5e-54b4-5884-85dc-ceb5cd974819'::uuid, NULL, NULL, E'Picnic', NULL, NULL),
  ('9c5b8cee-7452-51c5-ae16-75a05ae07519'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9c5b8cee-7452-51c5-ae16-75a05ae07519'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '324c3b2f-efac-5e57-a96d-4d69c553498e'::uuid, NULL, E'The competition is open to both amateur and professional photographers.', NULL, NULL, NULL),
  ('9c5d5aa9-02e6-5973-81d9-26b051cca67f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9c5d5aa9-02e6-5973-81d9-26b051cca67f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '1887c56f-51c9-59e3-9df8-67f1ebb1c004'::uuid, NULL, E'Visual aids can make presentations clearer and more interesting.', NULL, NULL, NULL),
  ('9c6b3475-57cc-5431-af29-a20299ab5cce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9c6b3475-57cc-5431-af29-a20299ab5cce'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'fe7e817f-0306-5f7d-bb86-3dd0596ce1ca'::uuid, NULL, NULL, E'The lectures today were carried out in the field of global warming.', NULL, NULL),
  ('9c6f1ae3-5618-5ba5-aa17-a0332f918e0c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '9c6f1ae3-5618-5ba5-aa17-a0332f918e0c'::uuid, 1, NULL, TRUE, 0, NULL, E'Online Content', E'Do you believe that social media platforms should regulate online content more strictly?', NULL, NULL, E'In today''s digital age, the role of social media platforms in shaping public discourse is undeniable. As such, it is imperative that these platforms take a proactive approach to regulate online content more strictly to safeguard users and uphold the integrity of the online space.\nOne compelling reason to advocate for stricter regulation is to protect users from harmful and misleading information. With the proliferation of false narratives and deceptive content online, users are vulnerable to manipulation and exploitation. By imposing stricter regulations, social media platforms can create a safer online environment where users can engage with content free from potential harm.\nAnother crucial aspect is the need to prevent the spread of fake news and misinformation. Misleading information can have far-reaching consequences, eroding trust in media sources and distorting public perceptions. By enforcing stringent content guidelines, social media platforms can play a pivotal role in curbing the dissemination of false information and promoting factual accuracy.\nIn conclusion, advocating for stricter regulation of online content on social media platforms is essential to foster a safer and more trustworthy online environment. By prioritizing user protection, combating misinformation, and promoting transparency, these platforms can uphold their responsibility as custodians of digital discourse. It is imperative that we collectively support efforts to enhance content regulation for the betterment of online communities worldwide.', NULL, 200, 300),
  ('9c7b2490-b087-5689-b958-b6ed9977cf92'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9c7b2490-b087-5689-b958-b6ed9977cf92'::uuid, 1, NULL, TRUE, 0, NULL, E'MCM-L', E'Today we are going to talk some more about architecture and what makes for a good design. There are of course a whole range of qualities that most architects would like their buildings to possess. One of these is the durability of the building. Architects must consider how well the building will stand up to the ravages of climate and time. Will it remain robust and in good condition? Clearly, requirements will vary according to the surroundings of the building in question. A design that is suitable for Dubai will have different needs from one for Moscow. Then of course it''s essential to consider the appearance of the building.\nRegardless of what its purpose may be, will people find pleasure in looking at it! An original and still respected writer on architecture, the Roman Vitrtlvius, wrote in the first century that a building should delight people and should raise their spirits. Again. tastes may vary from one society to the next, but the prinCiple remains the same.\n\nWhich of these qualities of a building does the speaker mention as being', '943b97fa-b5b2-5a83-9ffc-e09f1f71f849'::uuid, NULL, NULL, E'how attractive the building is to look at\nhow long the building is likely to last', NULL, NULL),
  ('9c7e786f-d70f-59e9-8631-a5baa4867882'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9c7e786f-d70f-59e9-8631-a5baa4867882'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7208c9af-cea9-5ba4-9d34-6b1031668d11'::uuid, NULL, NULL, E'In the concert venue, the teaching ensemble will showcase their talent.', NULL, NULL),
