  ('9cc1929d-defd-55d0-b6a3-20a528a6e619'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '9cc1929d-defd-55d0-b6a3-20a528a6e619'::uuid, 1, NULL, TRUE, 0, NULL, E'Taking Part in Sports', E'Taking part in sports is important for an adult''s health and happiness. To what extent do you agree with it?', NULL, NULL, NULL, NULL, 200, 300),
  ('9cc56966-3b10-555e-a6a2-257e8378ed52'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9cc56966-3b10-555e-a6a2-257e8378ed52'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '51145c7d-d12a-5425-87cb-742aaa88d8c1'::uuid, NULL, NULL, E'Global connections increased in academic communities, thanks to social media.', NULL, NULL),
  ('9cc92208-dced-573a-8844-1b942f5faa3d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '9cc92208-dced-573a-8844-1b942f5faa3d'::uuid, 1, NULL, TRUE, 0, NULL, E'Academic Freedom', E'Researchers say they have been {{1}} of their finances and academic freedoms and do not feel valued by the new government. Many continue to fear being {{2}} for their international connections, {{3}} or gender — or because they have been critical of the government — and some say they have been threatened with death or {{4}} by the Taliban.', NULL, NULL, NULL, E'1.stripped, 2.persecuted, 3.ethnicity, 4.retribution', NULL, NULL),
  ('9cc9bf18-7964-5091-b018-53eb8260186b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9cc9bf18-7964-5091-b018-53eb8260186b'::uuid, 1, NULL, TRUE, 0, NULL, E'Recycling', E'When we recycle, used materials are converted into new products, reducing the need to consume natural resources. If used materials are not recycled, new products are made by extracting fresh, raw material from the Earth, through mining and forestry. Recycling helps conserve important raw materials and protects natural habitats for the future.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9ccc6dff-048c-5897-9847-80479c5b6bc5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9ccc6dff-048c-5897-9847-80479c5b6bc5'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a fear of large and open space?', '9fb07b1c-1e6f-5de7-b8de-11eb9bfeaafa'::uuid, NULL, NULL, E'Agoraphobia', NULL, NULL),
  ('9cd3bb49-0364-5b51-a75a-f67c35d92c01'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9cd3bb49-0364-5b51-a75a-f67c35d92c01'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9d7b9142-972a-5008-9fbf-b715314dcc80'::uuid, NULL, E'The generic biology technology lab is located at the North Wing of the library.', NULL, NULL, NULL),
  ('9cd6ecc9-e26c-50d7-a116-923db429cc58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9cd6ecc9-e26c-50d7-a116-923db429cc58'::uuid, 1, NULL, TRUE, 0, NULL, E'Penicillin Allergy', NULL, '745f15bb-8221-5f63-88b8-81ae72c5db21'::uuid, NULL, E'Many patients acquire the allergy label as children, when a rash appears after they’re treated for an infection with penicillin or closely related drugs. The rash is often blamed on penicillin, while the more likely culprit is the original infection, or a reaction between the infection and the antibiotic. However, genuine penicillin allergies, where our immune systems mistake penicillin for an attacker, do occur rarely and can be very dangerous. So if you think you’re allergic but don’t know for sure, your best bet is to visit an allergist. They’ll complete an evaluation that’ll confirm whether or not you have the allergy. Even if you do have a penicillin allergy, your immune cells that react to the drug may lose their ability to recognize it. In fact, about 80% of people who are allergic to penicillin outgrow their allergy within ten years. This is great news for people who currently identify as allergic to penicillin; the drug may one day save their lives, as it has done for so many others.', NULL, NULL, NULL),
  ('9cd7bc25-bd3e-58ab-94a4-2c138487d0c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9cd7bc25-bd3e-58ab-94a4-2c138487d0c6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'eaf42b4b-08ec-5917-b442-e75a18e1b6c8'::uuid, NULL, E'She sold furniture to afford food for herself and her dog.', NULL, NULL, NULL),
  ('9cddc686-a612-5122-a99b-02e18f797894'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9cddc686-a612-5122-a99b-02e18f797894'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3ab5a889-3563-523b-b8a5-41be50e36440'::uuid, NULL, NULL, E'This new paper challenged many previously accepted theories.', NULL, NULL),
  ('9cde8ceb-6c5b-5e5b-99db-3ec7ad760c2e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '9cde8ceb-6c5b-5e5b-99db-3ec7ad760c2e'::uuid, 1, NULL, TRUE, 0, NULL, E'Snails', E'Snails are not traditionally known for quick thinking, but new research shows they can make complex decisions using just two brain cells in {{1}} that could help engineers design more efficient robots. Scientists at the University of Sussex attached electrodes to the heads of freshwater snails {{2}} they searched for lettuce. They found that just one cell was used by the mollusc to tell {{3}} it was hungry or not, while another let it know when food was present. Foodsearching is an example of goal-directed behavior, {{4}} which an animal must integrate information about both its external environment and internal state while using as little energy as possible. Lead researcher Professor George Kemenes, say "This will eventually help us design the ''brain'' of robots based on the principle of using the {{5}} possible components necessary to perform complex tasks." What goes on in our brains when we {{6}} complex behavioral decisions and carry them out is poorly understood." Our study reveals for the first time how just two neurons {{7}} create a mechanism in an animal''s brain which drives and optimizes complex decision-making tasks.', NULL, NULL, NULL, E'1.findings, 2.as, 3.if, 4.during, 5.fewest, 6.make, 7.can', NULL, NULL),
  ('9cdfb14a-673e-5e47-b4b0-45d97e142be9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '9cdfb14a-673e-5e47-b4b0-45d97e142be9'::uuid, 1, NULL, TRUE, 0, NULL, E'Global Exchange', NULL, NULL, NULL, NULL, E'4, 2, 3, 1', NULL, NULL),
  ('9cea40e3-5b60-5213-9900-c8f7826229f5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', '9cea40e3-5b60-5213-9900-c8f7826229f5'::uuid, 1, NULL, TRUE, 0, NULL, E'Snow', E'Snow is formed when temperatures are low and there is moisture - in the form of tiny ice crystals - in the atmosphere. When these tiny ice crystals collide they stick together in clouds to become snowflakes. If enough ice crystals stick together, they''ll become heavy enough to fall to the ground.\nPrecipitation falls as snow when the air temperature is below 2°C. It is a myth that it needs to be below zero to snow. In fact the heaviest snowfalls tend to occur when the air temperature is between zero and 2°C.\nThe falling snow does begin to melt as soon as the temperature rises above freezing, but as the melting process begins, the air around the snowflake is cooled.\nIf the temperature is warmer than 2°C then the snowflake will melt and fall as sleet rather than snow, and if it''s warmer still, it will be rain.\nThe size and make-up of a snowflake depends on how many ice crystals group together, and this will be determined by air temperatures. Snowflakes that fall through dry, cool air will be small, powdery snowflakes that don''t stick together. This ''dry'' snow is ideal for snow sports but is more likely to drift in windy weather.\nWhen the temperature is slightly warmer than 0°C, the snowflakes will melt around the edges and stick together to become big, heavy flakes. This creates ''wet'' snow, which sticks together easily and is good for making snowmen.\n\nWhich of the following statements about snow match the information in the passage?', NULL, NULL, NULL, E'Snow is formed from ice.\nDry snow falls in colder temperatures than wet snow.', NULL, NULL),
  ('9ceb564f-5e54-5bb3-b033-2aa169b32881'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '9ceb564f-5e54-5bb3-b033-2aa169b32881'::uuid, 1, NULL, TRUE, 0, NULL, E'Academic Writing (B)', E'Academic writing is {{1}} of logic that is the product of thinking. This {{2}} that the writing that you produce is a {{3}} of your intellectual abilities. It {{4}} into words your knowledge and your conceptual understanding and shows {{5}} of your ability to think critically.', NULL, NULL, NULL, E'1.expression, 2.means, 3.reflection, 4.puts, 5.evidence', NULL, NULL),
  ('9ced1ee2-282a-5f14-89c6-4a655b6ae2c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9ced1ee2-282a-5f14-89c6-4a655b6ae2c0'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0b7c1a05-8e86-52a1-9d40-fa18dcd532b4'::uuid, NULL, NULL, E'The next lecture will discuss what is causing global warming.', NULL, NULL),
  ('9ced3ff6-4433-5c92-8024-664da6c2b504'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9ced3ff6-4433-5c92-8024-664da6c2b504'::uuid, 1, NULL, TRUE, 0, NULL, E'Civil Society', NULL, 'c3c09cac-a6f8-50e6-9095-7c8332c31cf5'::uuid, NULL, E'But in the face of the sense of disempowerment, there surprisingly is no decline in involvement in organizations which seek to share wealth and\nopportunities, protect one another''s right and work towards the common good. according to the United Nations, Civil Society groups have Grown 40-fold since the turn of last century. Internationally the nonprofit sector is worth 1 trillion dollars, and there are 700,000 such organizations in Australia alone. the UN recognizes 37000 specifically Civil Society organizations across the global, and gave 3500 accreditation to the 2002 World\nSummit on sustainable development. This profound movement towards harnessing voices and resources from outside realm of governments and\nofficialdom reflects a profound growth in NGOs, "the third sector" as some call it. Putnam discovered in the field of local government in ltaly, the best predictor of governmental success was the strength and density of a region''s civic associations.', NULL, NULL, NULL),
  ('9cee8dac-02b9-5312-be1a-18430d5fabef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9cee8dac-02b9-5312-be1a-18430d5fabef'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '97fe3493-886a-5006-ab6d-f42d3bc52f12'::uuid, NULL, NULL, E'We are now able to accommodate more postgraduate students than before.', NULL, NULL),
  ('9cf297ac-d753-5e9b-9443-b773c86f44ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '9cf297ac-d753-5e9b-9443-b773c86f44ee'::uuid, 1, NULL, TRUE, 0, NULL, E'Yayoi Kusama', E'Advanced age and the pandemic have done little to deter Japan''s Yayoi Kusama. At 93, the world''s best-selling living female artist is still painting daily at the psychiatric hospital she voluntarily checked into and has lived in since the 1970s. Best known for her {{1}} pumpkin sculptures and polka-dot paintings, which can command millions of dollars at auction, Kusama’s success has {{2}} in the past decade. Some of her latest creations feature alongside early drawings in a new exhibition at Hong Kong''s M+ museum. Bringing together more than 200 works, "Yayoi Kusama: 1945 to now" {{3}} seven decades as the largest retrospective of her art in Asia outside her home country. "Kusama is so much more than pumpkin sculptures and polka-dot patterns," the museum''s deputy director Doryun Chong explained. "She is a thinker of deep philosophy – a ground-breaking figure who has really revealed so much about herself, her vulnerability and her struggles as the source of {{4}} for her art."', NULL, NULL, NULL, E'1.signature, 2.skyrocketed, 3.spans, 4.inspiration', NULL, NULL),
  ('9cf34f3b-bdc6-5428-8777-b725616ac5aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9cf34f3b-bdc6-5428-8777-b725616ac5aa'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f40d3c0e-0cc1-5fa1-8300-d41e95bbe832'::uuid, NULL, E'Advertisements can occur in unusual places, even in the sea or in the sky.', NULL, NULL, NULL),
  ('9cf4a3b8-5433-5829-9078-6700b3c72f28'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9cf4a3b8-5433-5829-9078-6700b3c72f28'::uuid, 1, NULL, TRUE, 0, NULL, E'Call and Dinner', E'You are preparing dinner, and your friend is calling you to discuss a problem with one of her children. You really want to help your friend to solve her problem, but you are busy now, so you hope your friend could call you later. What do you say to your friend?', '91657952-5c0a-5127-a98a-b4648ac01716'::uuid, NULL, E'Hey friend, I want to talk to you about something.\nWe seem to have a little issue with our talk right now.\nIt''s like I am preparing dinner at the moment, though I am willing to help you deal with a problem involving one of your children, I hope you can call me later.\nAnd I''d like to know what you think.', NULL, NULL, NULL),
  ('9cf712eb-f5c2-53a5-85f3-3fb5917acc8c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9cf712eb-f5c2-53a5-85f3-3fb5917acc8c'::uuid, 1, NULL, TRUE, 0, NULL, E'Lifelong Learning', NULL, '1a10356e-dc99-5566-b5ef-cdaedcc37638'::uuid, NULL, E'In this talk, I want to emphasize the importance of lifelong learning, a journey that extends beyond the confines of traditional education. In a world that is constantly evolving, the pursuit of knowledge is a never-ending process. Lifelong learning keeps us relevant and adaptive. As technology and societal norms change, continuous learning enables us to stay updated and skilled. For instance, learning new languages or technological skills opens up opportunities in a globalized job market. Furthermore, lifelong learning enhances personal growth. It''s not just about career advancement; it''s about broadening our horizons, understanding diverse perspectives, and cultivating a more fulfilling life. The pursuit of knowledge shouldn''t end at graduation. Lifelong learning is a key to not only professional success but also personal enrichment. Let''s embrace this journey with enthusiasm and curiosity.', NULL, NULL, NULL),
  ('9cf952b1-c7a4-5a99-9ac0-e4e07bb8dad1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9cf952b1-c7a4-5a99-9ac0-e4e07bb8dad1'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '248ccf56-0151-5295-9415-583c7a88a189'::uuid, NULL, E'You should go to the reception to get your student card.', NULL, NULL, NULL),
  ('9cf9a174-203c-5d34-847a-c47265b2acf0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '9cf9a174-203c-5d34-847a-c47265b2acf0'::uuid, 1, NULL, TRUE, 0, NULL, E'Two Norths', E'Mapping software works with your phone''s GPS for the location and then the in-built {{1}} finds north, adjusting to the direction you''re facing and {{2}} the way. But that''s not easy because there are two ''norths''. There''s {{3}} north - which is the direction of the North Pole and which reliably stays put - and there''s {{4}} north which, thanks to the flowing layer of molten iron in the Earth''s outer {{5}} , has a habit of moving around.', NULL, NULL, NULL, E'1.compass, 2.pointing, 3.true, 4.magnetic, 5.core', NULL, NULL),
  ('9cf9d019-2b43-562f-8116-944f16d6f9d4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9cf9d019-2b43-562f-8116-944f16d6f9d4'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'When the writer of a book is unknown, what word is used for the author?', 'ded15047-fa5b-557f-86e5-71062159d756'::uuid, NULL, NULL, E'Anonymous / anonymity', NULL, NULL),
  ('9cf9e58f-6453-5c81-aab2-68187bac3545'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '9cf9e58f-6453-5c81-aab2-68187bac3545'::uuid, 1, NULL, TRUE, 0, NULL, E'First Publication', NULL, NULL, NULL, NULL, E'4, 1, 2, 3', NULL, NULL),
  ('9cfa9fab-7231-531b-ae2c-e7c97fd9d3f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9cfa9fab-7231-531b-ae2c-e7c97fd9d3f0'::uuid, 1, NULL, TRUE, 0, NULL, E'Atoms', E'Physicists thought they had a solid grasp on what made up matter. They knew that atoms contained electrons surrounding a positively charged nucleus. They also knew that each nucleus contained a number of protons and positively charged particles. Combinations of those two particles made up all of the matter in the universe.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9cfc8e7b-f9f2-5e18-b660-d9924e02e33c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9cfc8e7b-f9f2-5e18-b660-d9924e02e33c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a3ff5aa6-2b8a-5b15-9fcd-62253aaabe87'::uuid, NULL, E'Our professor is hosting the business development conference next week.', NULL, NULL, NULL),
  ('9cfe0632-98ed-55e7-88c2-5fec9d8d7dfc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '9cfe0632-98ed-55e7-88c2-5fec9d8d7dfc'::uuid, 1, NULL, TRUE, 0, NULL, E'Sustainable Living', E'Do you believe that sustainable living can be achieved by everyone?', NULL, NULL, E'Nowadays, the question of whether sustainable living can be achieved by everyone is a pertinent one, and I firmly believe that it is indeed attainable for all.\nOne pivotal reason why sustainable living can be achieved by everyone lies in its profound environmental impact. By embracing sustainable practices such as reducing waste, conserving energy, and utilizing renewable resources, individuals can significantly lower their carbon footprint and contribute to the preservation of the planet. These actions not only protect ecosystems and biodiversity but also play a crucial role in combating climate change and ensuring a sustainable future for generations to come.\nMoreover, sustainable living offers a dual advantage of promoting health and economic well-being. Embracing organic food choices, engaging in physical activity, and reducing exposure to harmful chemicals through eco-friendly products can enhance overall health and well-being. Additionally, sustainable practices such as energy efficiency, water conservation, and waste reduction can lead to substantial cost savings over time. By investing in sustainable technologies and practices, individuals can not only improve their quality of life but also reduce financial burdens associated with resource consumption and waste generation.\nIn conclusion, the prospect of achieving sustainable living for everyone is not only feasible but imperative in the face of escalating environmental challenges. By recognizing the interconnectedness of individual actions with global sustainability goals, each person has the power to make a meaningful impact through conscious choices and everyday practices. Sustainable living is not a distant ideal but a practical and achievable lifestyle that can benefit both individuals and the planet. Through collective efforts and a commitment to sustainable principles, we can create a more resilient and harmonious world for present and future generations.', NULL, 200, 300),
  ('9d013c72-d30b-5183-beb4-dc266b411871'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9d013c72-d30b-5183-beb4-dc266b411871'::uuid, 1, NULL, TRUE, 0, NULL, E'Plastics', E'If you walk into your kitchen, almost everything has encountered plastic in one way or another: the plastic bags you stuff into a drawer, your favorite cup, and even the packaging keeping those blueberries fresh. Despite plastic’s ubiquity, we often forget where it comes from. Indeed, when it comes to plastic, our efforts seem much more focused on what happens after rather than before we use it.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9d055a9e-f64b-5101-8b78-77f658d46474'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9d055a9e-f64b-5101-8b78-77f658d46474'::uuid, 1, NULL, TRUE, 0, NULL, E'Animal Calls', E'A recent study by Western researchers found that when animals produce sounds while sitting on the ground, like the chirping of crickets, their volume and range can increase by up to ten times. This discovery challenges the conventional belief in the field of animal communication that the ground impedes sound transmission.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9d23e473-073d-5392-a507-39883f2b1086'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9d23e473-073d-5392-a507-39883f2b1086'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the verb describing the process that water becomes ice?', '1b403ef0-2365-5bb1-8d6a-56733440fe6a'::uuid, NULL, NULL, E'Freeze', NULL, NULL),
  ('9d28bd4d-3cbb-5afe-880d-db5d2e0e21d0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '9d28bd4d-3cbb-5afe-880d-db5d2e0e21d0'::uuid, 1, NULL, TRUE, 0, NULL, E'Sports and Games', E'Sports and games create disturbance in students’ life because students cannot fully concentrate on their studies. To what extent do you agree or disagree?', NULL, NULL, NULL, NULL, 200, 300),
  ('9d2c4bd4-4844-5178-a34a-d990e6ee4b31'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '9d2c4bd4-4844-5178-a34a-d990e6ee4b31'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-R', E'Notable as important nineteenth-century novels by women, Mary Shelley''s Frankenstein and Emily Bronte''s Wuthering Heights treat women very differently. Shelley produced a masculine text in which the fates of subordinate female characters seem entirely dependent on the actions of male heroes or anti-heroes. Bronte produced a more realistic narrative, portraying a world where men battle for the favors of apparently high-spirited, independent women. Nevertheless, these two novels are alike in several crucial ways. Many readers are convinced that the compelling mysteries of each plot conceal elaborate structures of allusion and fierce, though shadowy, moral ambitions that seem to indicate metaphysical intentions, though efforts by critics to articulate these intentions have generated much controversy. Both novelists use a storytelling method that emphasizes ironic disjunctions between different perspectives on the same events as well as ironic tensions that inhere in the relationship between surface drama and concealed authorial intention, a method I call an evidentiary narrative technique.\n\nThe primary purpose of the passage is to __', NULL, NULL, NULL, E'compare and contrast two novels', NULL, NULL),
  ('9d2d8b42-8c4c-53be-895c-fa0499348b47'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9d2d8b42-8c4c-53be-895c-fa0499348b47'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the opposite of ''false''?', '09e628ea-0d4d-5a66-a65a-d08a15bbec14'::uuid, NULL, NULL, E'True / correct', NULL, NULL),
  ('9d328bec-dc99-52fa-99d0-6e21c5b55f32'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '9d328bec-dc99-52fa-99d0-6e21c5b55f32'::uuid, 1, NULL, TRUE, 0, NULL, E'History', E'History is selective. What history books tell us about the past is not everything that happened, but what historians have {{1}} .They cannot put in everything: choices have to be made. Choices must similarly be made about which aspects of the past should be formally taught to the next generation in the shape of school history lessons. So, for example, when a national school curriculum for England and Wales was first discussed at the end of the 1980s, the history curriculum was the subject of considerable public and media {{2}} . Politicians argued about it; people wrote letters to the press about it; the Prime Minister of the time, Margaret Thatcher, {{3}} in the debate.', NULL, NULL, NULL, E'1.selected, 2.interest, 3.intervened', NULL, NULL),
  ('9d33e096-f1c3-5b2d-8bb9-084c73fadec6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9d33e096-f1c3-5b2d-8bb9-084c73fadec6'::uuid, 1, NULL, TRUE, 0, NULL, E'Measurable Benefit', E'Perhaps the most measurable benefit of the program has been the opportunity to meet in small groups, something that is difficult to arrange such a desperate organization. Many officers would have to work together for thirty years but would not know other''s strengths and weaknesses.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9d3819d8-efbb-5582-9e60-7f7cfa763489'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', '9d3819d8-efbb-5582-9e60-7f7cfa763489'::uuid, 1, NULL, TRUE, 0, NULL, E'Global Warming', E'This warming trend around the globe is due to human activities that have increased emissions of carbon dioxide and other greenhouse gases into the atmosphere. The planet is already seeing the effects of global warming: Arctic sea ice is declining, sea levels are rising, wildfires are becoming more severe and animal migration patterns are shifting. Understanding how the planet is changing — and how rapidly that change occurs — is crucial for humanity to prepare for and adapt to a warmer world. “Science leaves no room for doubt: Climate change is the existential threat of our time,” said NASA Administrator Bill Nelson.\n\nWhat is the author’s main purpose to write this passage?', NULL, NULL, NULL, E'To call for the action to combat global warming.', NULL, NULL),
  ('9d391d1f-6c13-597f-a9e9-1acd9fe26da0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '9d391d1f-6c13-597f-a9e9-1acd9fe26da0'::uuid, 1, NULL, TRUE, 0, NULL, E'International Organizations', E'Global problems are related to governments and international organizations. What are the problems and what is your solution?', NULL, NULL, E'There are many global problems. In my opinion, climate change is one of the most pressing global problems that we face today. The effects of climate change are already being felt around the world, from more frequent and severe weather events to rising sea levels and melting glaciers. However, there are solutions that we can implement to mitigate the impacts of this most pressing problem.\nFirstly, governments should invest in renewable energy sources such as wind and solar power to solve this pressing problem. This can help reduce our dependence on fossil fuels and decrease greenhouse gas emissions. In addition, governments should provide incentives for individuals and businesses to adopt more sustainable practices, such as using energy-efficient appliances and reducing waste.\nSecondly, international organizations can play a role in reducing their carbon footprint in order to solve this pressing problem. This can include driving less, eating less meat, and using public transportation or biking instead of driving. Moreover, international organizations can support environmental organizations and advocate for policies that address climate change.\nIn conclusion, addressing climate change requires a concerted effort from international organizations and governments. By investing in renewable energy sources, adopting sustainable practices, and advocating for policies that address climate change, we can mitigate the impacts of climate change and protect our planet for future generations. It is imperative that we take action now to address this pressing global problem.', NULL, 200, 300),
  ('9d395ce1-9773-5644-b5ed-a7b12fb65bed'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '9d395ce1-9773-5644-b5ed-a7b12fb65bed'::uuid, 1, NULL, TRUE, 0, NULL, E'Robots', E'Robots may soon be able to sense and avoid potentially harmful {{1}} , thanks to a system that mimics the human pain response. The system consists of artificial skin that can detect forces and a neural network that can interpret which ones are likely to cause damage. The artificial skin is made of flexible rubber with embedded sensors that measure pressure, temperature and strain. The neural network {{2}} to classify the sensor data into three levels of pain: no pain, mild pain and {{3}} pain. The system can also learn from its own experiences and adjust its pain threshold over time. The system could help robots protect themselves from injuries and extend their lifespan. It could also enable more natural and safe {{4}} between robots and humans.', NULL, NULL, NULL, E'1.stimuli, 2.is trained, 3.severe, 4.interactions', NULL, NULL),
  ('9d39ef71-6a51-5a25-b494-78504cb4d3ba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '9d39ef71-6a51-5a25-b494-78504cb4d3ba'::uuid, 1, NULL, TRUE, 0, NULL, E'Speech Pattern', NULL, NULL, NULL, NULL, E'4, 3, 1, 2', NULL, NULL),
