  ('9d49ef15-5c7a-55fa-a471-3d58f2794b2b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '9d49ef15-5c7a-55fa-a471-3d58f2794b2b'::uuid, 1, NULL, TRUE, 0, NULL, E'Behanzin', E'Behanzin ruled the West African {{1}} of Dahomey at the end of the nineteenth century, a time when Europeans were doing their utmost to colonise Africa. Behanzin put up extremely {{2}} resistance. He did this with the {{3}} of an army, including five thousand female warriors. He is often called King Shark, a name suggesting {{4}} and wisdom. Famed for being a {{5}} as well as a warrior, he wrote some of the most beautiful songs ever produced in Dahomey.', NULL, NULL, NULL, E'1.kingdom, 2.powerful, 3.aid, 4.strength, 5.poet', NULL, NULL),
  ('9d4bdde1-c32a-545d-ac7b-3f70e2dd8a9d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '9d4bdde1-c32a-545d-ac7b-3f70e2dd8a9d'::uuid, 1, NULL, TRUE, 0, NULL, E'Coober Pedy', NULL, NULL, NULL, NULL, E'2, 3, 5, 4, 1', NULL, NULL),
  ('9d4e5f37-53c3-564d-b9a3-9fb172c28bad'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9d4e5f37-53c3-564d-b9a3-9fb172c28bad'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '619c195f-bac1-56eb-a4c7-4c8a320a7f97'::uuid, NULL, NULL, E'Field trips and internship opportunities are included in this major.', NULL, NULL),
  ('9d50587b-6678-554d-9b41-051a58c8a80d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '9d50587b-6678-554d-9b41-051a58c8a80d'::uuid, 1, NULL, TRUE, 0, NULL, E'Gondwana', E'Millions of years ago, the continents were arranged in a way that one landmass dominated the others: Gondwana, which {{1}} present-day South America, Africa, Arabia, Madagascar, India, Australia, and Antarctica. More continents collided with this early Gondwana {{2}} time to form Pangaea, the “whole Earth.” It was immense by any {{3}} of the imagination: all of the planet’s landmass was surrounded by the biggest ocean in history.', NULL, NULL, NULL, E'1.incorporated, 2.over, 3.stretch', NULL, NULL),
  ('9d55487e-20c8-56a9-824e-b7a619d0e9ce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9d55487e-20c8-56a9-824e-b7a619d0e9ce'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '72fa1daa-60c0-5aa3-871d-5458ff793fe3'::uuid, NULL, NULL, E'Graduating from community college, she decided to pursue a bachelor''s degree.', NULL, NULL),
  ('9d55c2f1-57db-5253-b478-ad44de9e412a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '9d55c2f1-57db-5253-b478-ad44de9e412a'::uuid, 1, NULL, TRUE, 0, NULL, E'Health and Disease', NULL, NULL, NULL, NULL, E'2, 4, 3, 5, 1', NULL, NULL),
  ('9d58e1da-440f-5d7c-84e9-120f6a375dbc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '9d58e1da-440f-5d7c-84e9-120f6a375dbc'::uuid, 1, NULL, TRUE, 0, NULL, E'Home Appliances', E'In the developed world, home appliances have greatly reduced the need for physical labour. {{1}} people need to be involved in tasks that once left them little time to do much else. For example, the word processor and email have, to a great {{2}} , replaced the dedicated secretarial staff that briefly flourished with the rise of the typewriter. At {{3}} time all copies were made with manual scribes, carefully duplicating what they read. Then we had carbon paper. Then photocopiers. Then printers. Then the requirement for physical copy reduced. An entire stream of labour appeared and disappeared as technology advanced. We freed ourselves of one kind of work; we just replaced it {{4}} another.', NULL, NULL, NULL, E'1.Fewer, 2.extent, 3.one, 4.with', NULL, NULL),
  ('9d5c57f2-3911-5d8d-87f6-62dfadea1f2f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '9d5c57f2-3911-5d8d-87f6-62dfadea1f2f'::uuid, 1, NULL, TRUE, 0, NULL, E'Tardigrades', E'Tardigrades, also known as water bears, are microscopic animals that can live in almost any environment, from the deep sea to the frozen poles. They have a remarkable ability to enter a {{1}} of deep hibernation when faced with harsh conditions such as high temperatures, radiation, or dehydration. But how do they do it? Researchers have discovered that tardigrades use tiny molecular sensors in their cells to {{2}} the level of harmful molecules which are produced by stress. These sensors {{3}} an amino acid called cysteine, which changes its structure and function when oxidized by harmful stress molecules. This {{4}} the tardigrades to enter or exit hibernation, depending on the situation. The researchers say that this mechanism may help us understand the ageing process and the possibility of long-term space travel.', NULL, NULL, NULL, E'1.state, 2.detect, 3.are made of, 4.signals', NULL, NULL),
  ('9d5f5321-a585-52cc-a85b-1cfd3ee1d545'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9d5f5321-a585-52cc-a85b-1cfd3ee1d545'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e7c9b53e-303e-5b16-be46-151590cf3966'::uuid, NULL, E'Their new technology began local production of metal and leather goods.', NULL, NULL, NULL),
  ('9d764ccc-0bbd-582e-985a-8dc4cb54af13'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '9d764ccc-0bbd-582e-985a-8dc4cb54af13'::uuid, 1, NULL, TRUE, 0, NULL, E'Oliver Smithies', E'Oliver Smithies won the Nobel Prize in {{2}} or Medicine in 2007. On June 27th, he spoke to students about what he learned from his thesis {{3}} , which {{4}} developing a new method to measure the osmotic pressures of mixes of proteins:\n"Here''s my osmotic pressure {{5}} . And I was rather proud of this method. And I {{6}} it with great delight. This paper has a record, you know: nobody ever quoted it. And nobody ever used the method again. And I didn''t use the method again. So I have to ask you, what was the point of it all? Well, the answer is really a very serious answer. The answer is I learned to do good science. But it didn''t matter what I did when I was learning to do good science. So it doesn''t matter what you do when you''re doing a thesis, you see. But it''s very important that you enjoy it. Because if you don''t enjoy it, you won''t do a good job and you won''t learn science. So all of this comes around to the fact that if you don''t enjoy what you''re doing, ask your advisors to let you do something else. And if your advisor won''t do that, there''s another {{7}} : change your advisor."', NULL, NULL, NULL, E'1.Physiology, 2.research, 3.involved, 4.measurement, 5.published, 6.solution', NULL, NULL),
  ('9d782319-4013-5ccb-91f2-89bf4df4b6d6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '9d782319-4013-5ccb-91f2-89bf4df4b6d6'::uuid, 1, NULL, TRUE, 0, NULL, E'Cardona Salt Mountain', E'Formed two million years ago when low-density salt was pushed up through the much harder materials surrounding it, the Cardona Salt Mountain is one of the largest domes of its kind in the world, and unique in Europe. While small amounts of other minerals pervade the savory hill, the salt pile {{1}} a near translucent quality if not for the thin layer of reddish clay coating the exterior. The {{2}} of the mountain was recognized as early as the middle ages when Romans began exploiting the mountain for its salt, which began to bolster the young Cardonian {{3}} . With the invention of industrial mining techniques, a mine was built into the side of the mountain and a thriving facility formed at its base as excavators dragged enormous amounts of potash (water-soluble) salt from the innards of the hill. In {{4}} to the mineral export, the locals of Cardona began making salt sculptures to sell and invented a number of hard, salty pastries unique to the area.', NULL, NULL, NULL, E'1.would have, 2.significance, 3.economy, 4.addition', NULL, NULL),
  ('9d7b5baf-6ab2-5d66-b4dd-265634824f89'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9d7b5baf-6ab2-5d66-b4dd-265634824f89'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a0bcc779-d09d-5593-b803-def9d176aa26'::uuid, NULL, E'All of our accommodations are within walking distance of the academic buildings.', NULL, NULL, NULL),
  ('9d7f056c-2b83-51cb-b019-7e94a6d0fde2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9d7f056c-2b83-51cb-b019-7e94a6d0fde2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9115338a-7db0-5d07-adaf-e37a0aa066a8'::uuid, NULL, NULL, E'It is compulsory to attend the laboratory instruction.', NULL, NULL),
  ('9d8edfae-d4d0-5261-ae8d-d8d12e462ad1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9d8edfae-d4d0-5261-ae8d-d8d12e462ad1'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '50d01b53-2ea0-5c1e-8615-bcdae8c47f2a'::uuid, NULL, NULL, E'During that time people had large families as an insurance against some children loss.', NULL, NULL),
  ('9d974306-bb46-5f8e-961d-eae15a84e7ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '9d974306-bb46-5f8e-961d-eae15a84e7ee'::uuid, 1, NULL, TRUE, 0, NULL, E'Plants', E'Plants serve as the conduit of energy into the biosphere, provide food and materials used by humans, and they {{1}} our environment. According to Ehrhardt and Frommer, the three major challenges facing humanity in our time are food, energy, and environmental {{2}} . All three are plant related. All of our food is produced by plants, either directly or indirectly via animals that eat them. Plants are a {{3}} of energy production. And they are intimately involved in climate change and a major factor in a variety of environmental concerns, including agricultural expansion and its impact on habitat destruction and waterway pollution. What''s more, none of these issues is independent of each other. Climate change places additional stresses on the food supply and on various habitats. So, plant research is instrumental in addressing all of these problems and moving into the future. For plant research to move significantly forward, Ehrhardt and Former say technological development is critical, both to test existing hypotheses and to gain new information and generate fresh hypotheses. If we are to make headway in understanding how these essential organisms function and build the foundation for a sustainable future, then we need to apply the most advanced technologies available to the study of plant life, they say.', NULL, NULL, NULL, E'1.shape, 2.degradation, 3.source', NULL, NULL),
  ('9daa6124-f8cc-5fb1-8b4e-55ad95f129d9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9daa6124-f8cc-5fb1-8b4e-55ad95f129d9'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the slowest mammal in the world?', '0d363d8c-14d6-513f-a089-5769954ddce7'::uuid, NULL, NULL, E'Sloth', NULL, NULL),
  ('9daa7657-cfe8-5a55-8dba-94d5caa24352'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '9daa7657-cfe8-5a55-8dba-94d5caa24352'::uuid, 1, NULL, TRUE, 0, NULL, E'Wage Slave', E'Americans in the mid-nineteenth century could point to plenty of examples, real as well as mythical, of self-made men who by dint of "industry, prudence, perseverance, and good economy" had risen "to competence, and then to affluence".With the election of Abraham Lincoln they could point to one who had risen from a log cabin to the White House. "I am not ashamed to confess that twenty five years ago I was a hired laborer, mauling rails, at work on a flat-boat—just what might happen to any poor man''s son!" Lincoln told an audience at New Haven in 1860. However, in the free states, a man knows that he can better his condition. There is no such thing as a freeman being fatally fixed for life, in the condition of a hired laborer. Wage slave was a contradiction in terms, said Lincoln. The man who labored for another last year, this year labors for himself, and next year he will hire others to labor for him. If a man continues through life in the condition of a hired laborer, it is not the fault of the system, but because of either a dependent nature which prefers it, or improvidence, folly, or singular misfortune. "The free labor system," concluded Lincoln, "opens the way for all—gives hope to all, and energy, and progress, and improvement of condition to all."', NULL, NULL, E'With the election of Abraham Lincoln, they could point to one who had risen from a log cabin to the White House, but in the free states, a man knows that he can better his condition, and wage slave was a contradiction in terms, where the free labor system opens the way for all.', NULL, 5, 75),
  ('9daaaabe-dd4a-54ed-8274-2bb70dbd1946'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9daaaabe-dd4a-54ed-8274-2bb70dbd1946'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'dfe71e56-e09c-5f9c-a872-6ed70db3da4c'::uuid, NULL, NULL, E'There are a number of people familiar with this process.', NULL, NULL),
  ('9dadbdc0-8b7e-51e3-aa9a-b4fa33cf4155'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9dadbdc0-8b7e-51e3-aa9a-b4fa33cf4155'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8649ef3c-78ba-5215-8f07-68859d0b7705'::uuid, NULL, E'We should attempt to lower the amount of traffic on the roads.', NULL, NULL, NULL),
  ('9daeebde-baa9-5a13-aa59-bcf777178894'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9daeebde-baa9-5a13-aa59-bcf777178894'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '090ca8b6-83cb-5d9e-b96f-28a208dbc25b'::uuid, NULL, NULL, E'British students must study mathematics at secondary schools.', NULL, NULL),
  ('9dafb543-3f57-53d1-a322-e07046bebb1b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '9dafb543-3f57-53d1-a322-e07046bebb1b'::uuid, 1, NULL, TRUE, 0, NULL, E'Coca-Cola Logo', E'Why is the Coca-Cola logo red? Some claim that the red color came from one of the company’s first advertisements, which featured Santa Claus wearing his famous red-and-white suit and holding a Coke bottle. But according to the Coca-Cola Company, its famous logo dates back to the very beginning of the brand itself. Over 130 years ago, Coca-Cola was sold in barrels at American drug stores and pharmacies. Alcohol was distributed in the same way. But while alcohol was taxed at the time, soft drinks were not. So, the Coca-Cola Company began painting its barrels red in order to help customs and tax officials distinguish them from barrels of booze. There’s also a scientific reason why so many logos are red. The Coco-Cola logo is a trademark of its time, yet has remained fashionable through generations. The hallmark for the branding of the drink is its placement inside a red circle. This design made for easy decoration and advertisements in restaurants and stores. You see a red disc icon on a storefront, and you know that you’ll be able to get delicious, ice-cold Coca-Cola there. It became a promise in a way. Moreover, you won’t find this beverage’s famous hue in any Pantone color registries, because it is actually a combination of three different shades of red.', NULL, NULL, NULL, NULL, 5, 75),
  ('9db0b509-0deb-5f69-982c-d20291f7a4ff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9db0b509-0deb-5f69-982c-d20291f7a4ff'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f527316e-5e8a-544c-808c-39238fdcd2b0'::uuid, NULL, NULL, E'The gathered data was effectively transformed into an understandable argument.', NULL, NULL),
  ('9db6dcb6-2220-5527-bc34-c37ed61fee52'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9db6dcb6-2220-5527-bc34-c37ed61fee52'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Who is more likely to have sleep problems caused by their work schedule an accountant, a university lecturer or an international pilot?', '9a49d033-68be-50c0-915c-a21a4df21d77'::uuid, NULL, NULL, E'International pilot', NULL, NULL),
  ('9db7d1c7-f936-5ae2-b8ab-9ea94e436976'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '9db7d1c7-f936-5ae2-b8ab-9ea94e436976'::uuid, 1, NULL, TRUE, 0, NULL, E'Past and Present', E'Experts think that for those of us who live in the present, knowing about the past is of little value. To what extent do you agree with this statement?Explain it with your own experience.', NULL, NULL, NULL, NULL, 200, 300),
