  ('9dc65274-5c05-5197-8a1b-480c42b169eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9dc65274-5c05-5197-8a1b-480c42b169eb'::uuid, 1, NULL, TRUE, 0, NULL, E'Triumph of Capitalism', E'Most peasants remained self-sufficient and sceptical about money - and with good reason: the triumph of capitalism probably made them worse off. They now had to deal with a centralized imperial state that was collecting tax more efficiently, giving more power to landlords, and slowly reducing customary peasant rights to land and produce.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9dc712ac-e7e5-54e6-800c-9fe82ba56783'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '9dc712ac-e7e5-54e6-800c-9fe82ba56783'::uuid, 1, NULL, TRUE, 0, NULL, E'Women''s Care', E'A study shows that women may need more care than men. To what extent do you agree with it?', NULL, NULL, NULL, NULL, 200, 300),
