  ('9dd0a275-2a23-5e9d-bbb4-ef79dd3d0cfc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '9dd0a275-2a23-5e9d-bbb4-ef79dd3d0cfc'::uuid, 1, NULL, TRUE, 0, NULL, E'Public Good', E'Providing for children in their early years must be {{1}} as a public good, not a private test of a family’s {{2}} strength. Parents around the world should no longer be reduced to hoping for the best, crossing their fingers that the {{3}} care they are often forced to use isn’t a risk to their child’s safety or their future {{4}} in life.', NULL, NULL, NULL, E'1.treated, 2.financial, 3.inadequate, 4.prospects', NULL, NULL),
  ('9dd488ba-8c0f-5a80-aa92-7a219d8e6696'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9dd488ba-8c0f-5a80-aa92-7a219d8e6696'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6960e67a-ba6d-5ee1-b762-7b0cf5be06c1'::uuid, NULL, E'They voted to table the proposal until the following meeting.', NULL, NULL, NULL),
  ('9dd5da40-378f-5139-a7d3-a51f191802c7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '9dd5da40-378f-5139-a7d3-a51f191802c7'::uuid, 1, NULL, TRUE, 0, NULL, E'African Refugees', E'Conflict driven large-scale displacement (both internal and external) is among the main challenges {{1}} sub-Saharan Africa today. According to the United Nations High Commissioner for Refugees, more than 2.3 million South Sudanese {{2}} from their homes have {{3}} to neighboring countries, with 82% of them being women or children. These refugees face {{4}} social, health, and livelihood challenges.', NULL, NULL, NULL, E'1.facing, 2.uprooted, 3.fled, 4.tremendous', NULL, NULL),
