  ('9de6a285-ab0b-5111-8543-edf008146808'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '9de6a285-ab0b-5111-8543-edf008146808'::uuid, 1, NULL, TRUE, 0, NULL, E'Silk Road', E'The Silk Road has often been {{1}} for the spread of infectious diseases in the past between East Asia, the Middle East and Europe. While such a hypothesis seems plausible, there is actually very little {{2}} evidence to prove that diseases were {{3}} by early travelers moving along its {{4}} branches.', NULL, NULL, NULL, E'1.blamed, 2.concrete, 3.transmitted, 4.various', NULL, NULL),
