  ('9e3914d2-dedd-5183-ab00-794b8b1030f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9e3914d2-dedd-5183-ab00-794b8b1030f8'::uuid, 1, NULL, TRUE, 0, NULL, E'Environment Problems', E'Environment problems caused by hard rock mining involve water pollution by metals themselves, chemicals used in processing, acid drainage, and sediment. Metals and metal-like elements in the ore are toxic and prone to cause trouble by ending up in nearby streams and water tables as a result of mining operations.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9e3d4581-a251-527d-b164-ee890d145e80'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9e3d4581-a251-527d-b164-ee890d145e80'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '74efb854-7928-5e20-b74e-149f68a885ca'::uuid, NULL, NULL, E'The research results will be shared with the internal and external stakeholders.', NULL, NULL),
  ('9e403e62-8cfc-5b55-ac8d-f944348123d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9e403e62-8cfc-5b55-ac8d-f944348123d5'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'cd59eb21-6095-590b-b9c5-85001bd8e26a'::uuid, NULL, E'The new class timetables will be posted for students'' convenience on the noticeboard.', NULL, NULL, NULL),
  ('9e43d65d-a999-5cc7-b69d-984e3f2387a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9e43d65d-a999-5cc7-b69d-984e3f2387a8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the device that cuts grass to an even length?', 'bf1bfaa3-4313-5f55-81b0-b6c5777babe0'::uuid, NULL, NULL, E'Lawnmower / lawn mower', NULL, NULL),
  ('9e48b2f1-d375-5b1b-93a9-caa333230650'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9e48b2f1-d375-5b1b-93a9-caa333230650'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a0c17587-720c-578d-91c7-9bb3f816c63e'::uuid, NULL, NULL, E'My loan has been approved by the bank.', NULL, NULL),
  ('9e4a4ef1-fdd6-5aa6-8ec3-c3dd82999194'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '9e4a4ef1-fdd6-5aa6-8ec3-c3dd82999194'::uuid, 1, NULL, TRUE, 0, NULL, E'Sharks', E'Sharks come in a wide {{1}} of shapes and sizes. Today, more than 500 species of shark swim throughout the world’s salt and fresh waters, each with its own unique {{2}} and adaptations, but many species are {{3}} as endangered by the International Union for the Conservation of Nature. Their numbers and habitat have {{4}} dramatically over the last decades, primarily due to human activity like offshore drilling and fishing.', NULL, NULL, NULL, E'1.range, 2.characteristics, 3.classified, 4.decreased', NULL, NULL),
  ('9e53182a-3439-5cc3-a7f6-2a18366bb772'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9e53182a-3439-5cc3-a7f6-2a18366bb772'::uuid, 1, NULL, TRUE, 0, NULL, E'Moods', E'Moods may also have an effect on how information is processed, by influencing the extent to which judges rely on pre-existing, internal information, or focus on new, external information. Positive moods promote more holistic and top-down processing style, while negative moods recruit more stimulus-driven and bottom-up processing.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9e53fdaa-88ef-5d59-bc89-af86cee130f2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '9e53fdaa-88ef-5d59-bc89-af86cee130f2'::uuid, 1, NULL, TRUE, 0, NULL, E'Superintelligence', E'A superintelligence is any intellect that vastly outperforms the best human brains in practically every field, including scientific creativity, general wisdom, and social skills. This definition leaves open how the superintelligence {{1}} : it could be in a digital computer, an ensemble of networked computers, cultured cortical tissue, or something else. On this definition, Deep Blue is not a superintelligence, since it is only smart within one narrow domain (chess), and even there it is not vastly superior {{2}} the best humans. Entities such as corporations or the scientific community are not superintelligences either. Although they can perform a number of intellectual feats of which no individual human is capable, they are not {{3}} integrated to count as intellects, and there are many fields in which they perform much worse than single humans. For example, you cannot have a real-time conversation with the scientific community.', NULL, NULL, NULL, E'1.is implemented, 2.to, 3.sufficiently', NULL, NULL),
  ('9e63c560-0784-5748-8d53-a3ace1c8910c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9e63c560-0784-5748-8d53-a3ace1c8910c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do Internet websites sometimes require you to enter to get a discount on shopping?', '8343ccbf-1640-54d0-8458-1329d31b4a8c'::uuid, NULL, NULL, E'Voucher / coupon', NULL, NULL),
  ('9e63d52d-75d7-5167-ba51-a1f5aec4097d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9e63d52d-75d7-5167-ba51-a1f5aec4097d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0c5a6618-f3b3-5bf0-9c4c-840eac8dbed0'::uuid, NULL, E'If you need help, I can give you a hand in finding a flat.', NULL, NULL, NULL),
  ('9e690b76-cc51-5579-9654-96ea91b6a97b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9e690b76-cc51-5579-9654-96ea91b6a97b'::uuid, 1, NULL, TRUE, 0, NULL, E'Human Brain', NULL, 'd36aab08-8ac7-5618-b34e-7afe40513090'::uuid, NULL, E'The human brain is a subject at the forefront of neuroscience. This remarkable organ, though small in size, is vastly complex and the source of our thoughts, emotions, and memories. The brain''s intricate structure, composed of billions of neurons, enables us to perform a range of functions, from basic survival instincts to advanced cognitive processes. Recent advancements in brain imaging technologies, like MRI and PET scans, have allowed scientists to observe the brain in action and understand how different regions are involved in various tasks. The study of the brain has significant implications for treating neurological and psychological disorders. By understanding how the brain operates, we can develop better treatments for conditions like Alzheimer''s, depression, and epilepsy. Understanding the human brain is not just a scientific pursuit; it''s a journey into the essence of what makes us human. As we continue to explore this complex organ, we unlock mysteries of the mind that have intrigued humanity for centuries.', NULL, NULL, NULL),
  ('9e6a60ff-4b8b-5312-9ed1-3c5b46969b49'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '9e6a60ff-4b8b-5312-9ed1-3c5b46969b49'::uuid, 1, NULL, TRUE, 0, NULL, E'Wildlife Conservation', E'In recent years, the integration of green technology into wildlife conservation efforts has yielded promising results. This marriage of innovation and environmental protection has the potential to reshape the future of conservation.\nOne notable research result has been the development of advanced monitoring systems that employ artificial intelligence and remote sensing. These technologies enable researchers to track wildlife populations, behavior, and habitat changes with unprecedented precision. This data-driven approach not only enhances our understanding of animal ecosystems but also aids in conservation decision-making.\nEmerging green products, such as biodegradable materials and sustainable building practices, play a vital role in reducing human impact on natural habitats. From eco-friendly building designs that minimize disruption to ecosystems to the use of biodegradable fishing gear, these innovations help mitigate the negative effects of human activities on wildlife and their environments.\nIn addition to technological advancements, conservation events and competitions have gained prominence. These events foster awareness and collaboration among researchers, conservationists, and the general public. They provide a platform for showcasing innovative conservation strategies and inspiring collective action.\nFurthermore, green technology contributes to the protection of endangered species. Conservationists are using drones and remote-controlled vehicles for anti-poaching patrols, ensuring the safety of vulnerable animals while deterring illegal hunting.\nAs climate change and habitat destruction continue to threaten wildlife, the intersection of green technology, conservation research, and public engagement offers hope for the preservation of our planet''s biodiversity. By harnessing the power of innovation and environmental consciousness, we can strive for a more harmonious coexistence with the animal kingdom and protect our fragile ecosystems for generations to come.', NULL, NULL, E'The recent fusion of green technology with wildlife conservation, through advanced AI-enabled monitoring systems, biodegradable products, and public engagement events, is reshaping conservation efforts, enhancing our understanding and protection of biodiversity, and offering a hopeful approach to mitigating the impacts of climate change and habitat destruction.', NULL, 5, 75),
  ('9e707b86-6a27-557f-919d-5a4a21f197f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9e707b86-6a27-557f-919d-5a4a21f197f0'::uuid, 1, NULL, TRUE, 0, NULL, E'Steel', E'Steel is an alloy of two elements: iron and carbon. Steel alloys vary in their ratio of iron to steel as well as any additional metals present. For example, to create stainless steel, you would combine steel with chromium. Carbon steel contains a higher percentage of carbon, making it stronger than other steel alloys.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9e762427-debd-5a57-9f0b-c2bdff385ecb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9e762427-debd-5a57-9f0b-c2bdff385ecb'::uuid, 1, NULL, TRUE, 0, NULL, E'Brain Scans', E'Scientists studying brain scans of people who were asked to come up with inventive uses for everyday objects found a specific pattern of connectivity that correlated with the most creative responses. Researchers were then able to use that pattern to predict how creative other people''s responses would be based on their connections in this network.', NULL, NULL, NULL, NULL, NULL, NULL),
