  ('9e9da53d-fc2e-57b4-974c-686c9af5e4d6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9e9da53d-fc2e-57b4-974c-686c9af5e4d6'::uuid, 1, NULL, TRUE, 0, NULL, E'Thymus', E'Researchers have rebuilt a human thymus, an essential organ in the immune system, using human stem cells and a bioengineered scaffold. Their work is an important step towards being able to build artificial thymi which could be used as transplants.', NULL, NULL, NULL, NULL, NULL, NULL),
