  ('9ec7891a-1e6b-5273-b2f9-57b9c9e62633'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9ec7891a-1e6b-5273-b2f9-57b9c9e62633'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0fe8d6d5-bedb-5fba-a9df-76d6ad465b89'::uuid, NULL, E'If you wish to be a good student, you should attend every class.', NULL, NULL, NULL),
