  ('9ec7f461-3427-5b9b-b913-2d1d6d9061dc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9ec7f461-3427-5b9b-b913-2d1d6d9061dc'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5f102dc2-6703-533c-8b9f-3bfab71b3e55'::uuid, NULL, E'The United Kingdom is a constitutional monarchy and parliamentary democracy.', NULL, NULL, NULL),
  ('9ed58510-9be3-5eee-84f8-c0cc126f7a97'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '9ed58510-9be3-5eee-84f8-c0cc126f7a97'::uuid, 1, NULL, TRUE, 0, NULL, E'Language', E'Language is used in our everyday lives. If psychology is a science of behavior, scientific investigation of language use must be one of the most central topics — this is because language use is {{1}} . Every human group has a language; human infants (except those who have disabilities) learn at least one language without being taught {{2}} . Even when children, who don’t have many languages to begin with, are brought together, they can begin to develop and use their own language. There is at least one known instance where children, who had had little language, were brought together and developed their own language spontaneously with minimum {{3}} from adults. In Nicaragua in the 1980s, deaf children who were separately raised in various locations were brought together to schools for the first time. Teachers tried to teach them Spanish with little success. However, they began to notice that the children were using their hands and {{4}} , apparently to communicate with each other. Linguists were brought in to find out what was happening — it turned out the children had developed their own sign language by themselves.', NULL, NULL, NULL, E'1.ubiquitous, 2.explicitly, 3.input, 4.gestures', NULL, NULL),
  ('9ee1eb54-bfc3-5bf5-b4dd-ae8c86661919'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9ee1eb54-bfc3-5bf5-b4dd-ae8c86661919'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6b022902-1186-5a87-880b-9f8b4b970f6e'::uuid, NULL, E'The gadget can be attached to any vertical or near vertical surface.', NULL, NULL, NULL),
