  ('9f0d17bf-4806-5bdf-bcd5-6165b7d12de9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', '9f0d17bf-4806-5bdf-bcd5-6165b7d12de9'::uuid, 1, NULL, TRUE, 0, NULL, E'Competitive Environment', E'Is a competitive environment in school or university good or bad? Discuss and give your own experiences as examples.', NULL, NULL, NULL, NULL, 200, 300),
  ('9f1725dc-66cd-5132-89c9-c2fed14eba9a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9f1725dc-66cd-5132-89c9-c2fed14eba9a'::uuid, 1, NULL, TRUE, 0, NULL, E'Eye Issues', E'During the winter season, various eye issues can arise due to harsh weather conditions. Excess tearing and watery eyes, often caused by cold air and icy winds can lead to eye redness and inflammation. This can often be due to dry eyes from the combination of entering and exiting the cold weather and rooms that have been heated with central heating.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9f23fa97-6c50-5c29-a30f-9691ff2dfa71'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9f23fa97-6c50-5c29-a30f-9691ff2dfa71'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'fe5a4955-d752-50db-bc57-6e3b126d7c2f'::uuid, NULL, NULL, E'Continuing students will be sent necessary application forms.', NULL, NULL),
  ('9f28058a-b812-5a4c-811f-489aef084445'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9f28058a-b812-5a4c-811f-489aef084445'::uuid, 1, NULL, TRUE, 0, NULL, E'Iambic Pentameter', NULL, '7481686e-9cc2-500f-a7bf-2f2a8a5b292c'::uuid, NULL, E'To someone first encountering the works of William Shakespeare, the language may seem strange, but there is a secret to appreciating it.\nAlthough he was famous for his plays, Shakespeare was first and foremost a poet.\nOne of the most important things in Shakespeare''s language is his use of stress.\nNot that kind of stress, but the way we emphasize certain syllables in words more than others.\nWe''re so used to doing this that we may not notice it at first.\nBut if you say the word slowly, you can easily identify them.\nPoets are very aware of these stresses, having long experimented with the number and order of stressed and unstressed syllables and combined them in different ways to create rhythm in their poems.\nLike songwriters, poets often express their ideas through a recognizable repetition of these rhythms or poetic meter.\nShakespeare''s favorite meter in particular was iambic pentameter, where each line of force is made up of five two syllable items for a total of ten syllables.\nAnd it''s used for many of Shakespeare''s most famous sonnets.\nWhy did Shakespeare choose iambic pentameter for these moments?\nIt''s been said that iambic pentameter was easy for his actors to memorize and for the audience to understand because it''s naturally suited to the English language.\nBut there might be another reason.\nShakespeare''s most poetic lines don''t just talk about matters of the heart.\nThey follow its rhythm.', NULL, NULL, NULL),
  ('9f2fd826-d021-5604-bf2c-e3930573098f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9f2fd826-d021-5604-bf2c-e3930573098f'::uuid, 1, NULL, TRUE, 0, NULL, E'Administration Option', E'Another administration option is to bake marijuana at a relatively low temperature to kill any dangerous microorganisms and then allow that patient to eat it or drink it. Both of these methods of administration make smoking the drug unnecessary. However, criticism of medical marijuana has also been raised because as a natural plant, it cannot be patented and marketed by pharmaceutical companies and is unlikely to win widespread medical acceptance.', NULL, NULL, NULL, NULL, NULL, NULL),
