  ('9f33026c-5c17-5303-899e-4b1dce2545d2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9f33026c-5c17-5303-899e-4b1dce2545d2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1d45f58a-5650-5764-9197-c1d5c6db4c1d'::uuid, NULL, NULL, E'The company has not achieved success despite good reputation.', NULL, NULL),
  ('9f349ab2-33a4-57c0-ad9e-ecf9fa35c05e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9f349ab2-33a4-57c0-ad9e-ecf9fa35c05e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the place selling gold and silver?', 'd84f9f57-03a1-5e91-8235-2228de2a0cb8'::uuid, NULL, NULL, E'Jewelry store / bullion market', NULL, NULL),
  ('9f3b14b0-6547-50cb-90e4-7de8035a13fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '9f3b14b0-6547-50cb-90e4-7de8035a13fb'::uuid, 1, NULL, TRUE, 0, NULL, E'Eccentric Language', E'An eccentric mix of English, German and French has entered Japanese usage with grand {{1}} . A "kariya" woman is a career woman, and a "manshon" is an apartment. This increasing use of katakana, or unique Japanese versions of Western words, and the younger generation''s more casual use of the Japanese language have {{2}} Prime Minister Junichiro Koizumi to worry that these new words may not be understood by a wider audience. As a result, a government panel is proposing to publish a manual on how to speak proper Japanese. Foreign words became katakana Japanese {{3}} no existing Japanese words could quite capture a specific meaning or feeling. When the word "cool" traveled east, all of its English connotations did not make the journey. A kuru person in Japan is someone who is calm and never gets upset. On the other hand, someone who is kakkoii is hip, or in translation, "cool." {{4}} , a hot person is one who is easily excitable, perhaps passionate, but not necessarily a popular person or personality of the moment.', NULL, NULL, NULL, E'1.abandon, 2.prompted, 3.because, 4.Similarly', NULL, NULL),
  ('9f3c9faa-b873-5429-aa02-3707702fded6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9f3c9faa-b873-5429-aa02-3707702fded6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e7566bc4-d606-51a0-a5a9-1c1aee3fffca'::uuid, NULL, E'Conforming to the wrong group can lead to dangerous and harmful outcomes.', NULL, NULL, NULL),
  ('9f47d6ab-3385-59ff-bb8f-39892d254a79'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', '9f47d6ab-3385-59ff-bb8f-39892d254a79'::uuid, 1, NULL, TRUE, 0, NULL, E'Echolocation', NULL, NULL, NULL, NULL, E'4, 5, 1, 2, 3', NULL, NULL),
  ('9f4c381a-df8b-5cbb-b482-7a30d0b2ea0c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9f4c381a-df8b-5cbb-b482-7a30d0b2ea0c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '28d03183-f50a-5219-9908-de6b712e8dd1'::uuid, NULL, NULL, E'The curriculum has been updated to encourage more scholarly development.', NULL, NULL),
  ('9f4c7c73-4541-5087-abc0-7c0873523422'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9f4c7c73-4541-5087-abc0-7c0873523422'::uuid, 1, NULL, TRUE, 0, NULL, E'Antarctic', E'The world''s fifth largest continent: Antarctica is almost entirely covered by ice 2000 meters thick. The area sustains varied wildlife including seals, whales, and penguins. The Antarctic treaty signed in 1959 and enforced since 1961 provides for international governance of Antarctica.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9f525650-9119-5939-bf63-e112f6d6948f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9f525650-9119-5939-bf63-e112f6d6948f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the language by using hand movements rather than spoken words?', 'f276dd63-e380-525e-9704-6dcd37b11f74'::uuid, NULL, NULL, E'Body language / sign language', NULL, NULL),
  ('9f542523-4073-5c2c-a141-51baffdce8b6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '9f542523-4073-5c2c-a141-51baffdce8b6'::uuid, 1, NULL, TRUE, 0, NULL, E'Electronic Tattoo', E'For most people, monitoring blood pressure still means winding a cuff around the arm — whether in a health care setting or at home — and waiting for the squeeze as it inflates and then deflates to reveal a blood pressure reading. And even then, the reading is merely a moment in time and not a continual monitoring of blood pressure, which can and typically does frequently change throughout the day.\nNow there is good news on the horizon regarding the ability to continuously monitor blood pressure. Researchers at The University of Texas at Austin and Texas A&M University have developed a noninvasive solution for continuous blood pressure monitoring at home — in the form of a temporary tattoo.\nThe newly designed electronic tattoo is made with graphene, which is considered one of the strongest — and thinnest — materials in the world. The composition of graphene is similar to the graphite used in pencils, but when graphene is used as a temporary tattoo, it provides a waterproof way to measure the skin''s electrical currents and the body''s response to changes in blood volume. Prototypes of the electronic tattoo can be worn for up to a week to provide continuous blood pressure readings.\nThe use of graphene has proven instrumental in the temporary tattoo''s ability to accurately gather blood pressure data. Unlike, for example, the UV-monitoring temporary tattoos already on the market, graphene is so thin that it can eliminate the movement-caused data deterioration that can come with thicker tattoos that don''t adhere as easily to the skin.', NULL, NULL, NULL, NULL, 5, 75),
  ('9f5e0c07-200c-549c-91eb-7064fb0c6482'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', '9f5e0c07-200c-549c-91eb-7064fb0c6482'::uuid, 1, NULL, TRUE, 0, NULL, E'Diasporas', E'Diasporas – communities which live outside, but maintain links with their homelands – are getting larger, thicker and stronger. They are the human face of globalisation. Diaspora consciousness is on the rise: diasporas are becoming more interested in their origins, and organising themselves more effectively; homelands are revising their opinions of their diasporas as the stigma attached to emigration declines, and stepping up their engagement efforts; meanwhile, host countries are witnessing more assertive diasporic groups within their own national communities, worrying about fifth columns and foreign lobbies, and suffering outbreaks of ‘diaspora phobia’. This trend is the result of five factors, all of them connected with globalisation: the growth in international migration; the revolution in transport and communications technology, which is quickening the pace of diasporas’ interactions with their homelands; a reaction against global homogenised culture, which is leading people to rethink their identities; the end of the Cold War, which increased the salience of ethnicity and nationalism and created new space in which diasporas can operate; and policy changes by national governments on issues such as dual citizenship and multiculturalism, which are enabling people to lead transnational lives. Diasporas such as those attaching to China, India, Russia and Mexico are already big, but they will continue to grow; the migration flows which feed them are likely to widen and quicken in the future.', NULL, NULL, E'With the diasporas are getting larger, thicker, and stronger, resulting of five globalization factors, including the growth in international migration, the revolution in transport and communications technology, a reaction against global homogenized culture, the end of the Cold War, and policy changes by national governments, homelands are revising their opinions to their engagement efforts while host countries are starting to worry about foreign lobbies and Diaspora phobia.', NULL, 5, 75),
  ('9f609d7a-00cf-57dc-bb33-bb9148121991'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9f609d7a-00cf-57dc-bb33-bb9148121991'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call someone who travels and works in a spacecraft?', 'c95c0a56-a8c5-588e-a2ee-9cb4c6915b6c'::uuid, NULL, NULL, E'Astronaut / spaceman', NULL, NULL),
  ('9f643ecd-5ea7-5f9e-b64a-59f09d8fad5a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9f643ecd-5ea7-5f9e-b64a-59f09d8fad5a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9f8f8cad-a0d7-59c6-bfde-58e6507fe1ae'::uuid, NULL, E'Pick three or four courses you like before you sign up.', NULL, NULL, NULL),
  ('9f696ae6-cc84-5390-ae89-f200eef18eae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9f696ae6-cc84-5390-ae89-f200eef18eae'::uuid, 1, NULL, TRUE, 0, NULL, E'Ageing Population', NULL, '9dad252b-d111-5801-8f97-befdb6abfa59'::uuid, NULL, E'As the world population grows, the problem of an ageing population has become more serious globally. This is not just a future concern—it is happening right now. About nine percent of people are more than sixty-five years old in the world.\nLet''s take a closer look at specific examples: Ageing population percentage in the US is now 13% and is expected to be 23% by 2030. About 4% of the UK population is over the age of 75. The situation is more severe in Japan and Italy. And Germany follows, whose percentage of people over sixty-five years old is expected to be twenty-five percent by 2030. These figures reveal a clear trend: industrialized nations are experiencing the most rapid growth in older populations.\nThe ageing problem is related to industrialization. Industrialized societies tend to have better healthcare, nutrition, and living standards, which allow people to live longer. At the same time, as countries develop economically, birth rates often decline. This combination of people living longer and fewer babies being born naturally leads to an older average age for the population.', NULL, NULL, NULL),
  ('9f6d3a3a-731b-5553-8995-a7d6d2aa758a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9f6d3a3a-731b-5553-8995-a7d6d2aa758a'::uuid, 1, NULL, TRUE, 0, NULL, E'Virtual Reality', E'Virtual reality (VR) is not only a technology for games and entertainment, but also has potential in science and medicine. Researchers at Ruhr University Bochum, Germany, have now gained new insights into human perception with the help of VR. They used virtual reality scenarios in which subjects touched their own bodies with a virtual object.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9f73c8fe-8184-51b5-ac8b-89d0753cfcd8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '9f73c8fe-8184-51b5-ac8b-89d0753cfcd8'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '815eb9f7-6eee-55df-97f7-773f9848c7d3'::uuid, NULL, NULL, E'A new study has shown some really new and interesting things.', NULL, NULL),
