  ('9f8ad6e3-4901-579e-9a7b-1ea42f4440e2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9f8ad6e3-4901-579e-9a7b-1ea42f4440e2'::uuid, 1, NULL, TRUE, 0, NULL, E'Public Art', E'Public art has the power to transform communities and enhance economic stability. Art installations, murals, and sculptures can attract tourists and visitors, creating a vibrant and culturally rich atmosphere. Additionally, public art can increase foot traffic in commercial areas, leading to increased sales for local businesses.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('9f8da781-140b-5d04-850a-ae9ba6e4e014'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9f8da781-140b-5d04-850a-ae9ba6e4e014'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6c3dcd85-4082-54b6-ba30-703678885152'::uuid, NULL, E'Visual aids can make presentations clear and more interesting.', NULL, NULL, NULL),
  ('9f907bd7-3aec-56b9-814d-417df69949d0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '9f907bd7-3aec-56b9-814d-417df69949d0'::uuid, 1, NULL, TRUE, 0, NULL, E'Racial Prejudice', E'In some countries where racial prejudice is acute, violence has so come to be taken for granted as a means of solving differences, that it is not even questioned. There are countries where the white man {{1}} his rule by brute force; there are countries where the black man protests by setting fire to cities and by looting and pillaging. Important people on both sides, who would in other respects appear to be reasonable men, get up and calmly argue in favor of violence as if it were a {{2}} solution, like any other. What is really frightening, what really fills you with despair, is the realization that when it comes to the crunch, we have made no actual progress at all. We may wear collars and ties instead of war-paint, but our {{3}} remain basically {{4}} . The whole of the recorded history of the human race, that {{5}} documentation of violence has taught us absolutely nothing.', NULL, NULL, NULL, E'1.imposes, 2.legitimate, 3.instincts, 4.unchanged, 5.tedious', NULL, NULL),
