  ('9fbbe601-3597-562b-8f5d-5ce3f0786df9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9fbbe601-3597-562b-8f5d-5ce3f0786df9'::uuid, 1, NULL, TRUE, 0, NULL, E'Biomass', E'People have used biomass energy — energy from living things — since the earliest “cave men” first made wood fires for cooking or keeping warm. Biomass is organic, meaning it is made of material that comes from living organisms, such as plants and animals. The most common biomass materials used for energy are plants, wood, and waste.', NULL, NULL, NULL, NULL, NULL, NULL),
