  ('9fc65af7-26cd-5ffc-8448-761844f62c83'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '9fc65af7-26cd-5ffc-8448-761844f62c83'::uuid, 1, NULL, TRUE, 0, NULL, E'Space', E'Researchers already know that spending long periods of time in a zero-gravity {{1}} — such as that inside the International Space Station (ISS) — results in loss of bone density and {{2}} to the body''s {{3}} . That''s partly why stays aboard the ISS are {{4}} at six months. And now, a number of NASA astronauts are reporting that their 20/20 vision {{5}} after spending time in space, with many needing glasses once they returned to Earth.', NULL, NULL, NULL, E'1.environment, 2.damage, 3.muscles, 4.restricted, 5.deteriorated', NULL, NULL),
