  ('9fe35165-3d10-554c-ae62-74d650274702'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '9fe35165-3d10-554c-ae62-74d650274702'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a fast train that makes only a few scheduled stops?', 'ff2049ec-70bd-5e35-98b3-92dde76748af'::uuid, NULL, NULL, E'Express / express train / limited express', NULL, NULL),
