  ('a0db8412-92eb-5727-a9f5-08fae7496153'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'a0db8412-92eb-5727-a9f5-08fae7496153'::uuid, 1, NULL, TRUE, 0, NULL, E'Late Babies', E'In some countries, couples are having babies late in life. What are the reasons?', NULL, NULL, NULL, NULL, 200, 300),
  ('a0e32a0a-8b00-55aa-84f2-743944dc62ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'a0e32a0a-8b00-55aa-84f2-743944dc62ee'::uuid, 1, NULL, TRUE, 0, NULL, E'African Tribal Masks', NULL, NULL, NULL, NULL, E'4, 1, 2, 3', NULL, NULL),
  ('a0e53f6e-b9df-58fd-9d6d-1f817db2c7a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a0e53f6e-b9df-58fd-9d6d-1f817db2c7a6'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which part of our body does a gastroscope look into?', '285c8c97-476c-524b-b6e5-32a76481f624'::uuid, NULL, NULL, E'Stomach', NULL, NULL),
  ('a0ec9504-4e14-596b-9f4e-271a6d506c8b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a0ec9504-4e14-596b-9f4e-271a6d506c8b'::uuid, 1, NULL, TRUE, 0, NULL, E'Advertisement', E'Signs advertising business premises have been around for thousands of years and were used in ancient Egypt, Greece and Rome to attract customers; and they often used symbols to illustrate what kind of business it was - for example, bushes or branches of ivy meant the place was a tavern. Both of these, the tavern and its sign, were introduced into Britain by the Romans in the first half of the 1st century AD. In Europe in the Middle Ages signs became more common. Then, in the 14th century, English merchants were obliged to have them outside their shops. However, the fashion was to have large swinging signs hung from a strut sticking out of the wall - and many public houses still have such signs - but so many accidents occurred, mostly involving people on horseback, that in the 17th century a law was brought in requiring shopkeepers to mount their signs flat against the wall of the premises, where they could do no harm.\n\nAccording to the text, when did signs advertising businesses become compulsory?', 'a30b6e16-b5c6-5ef4-9f7f-27d10f766626'::uuid, NULL, NULL, E'In the 14th century', NULL, NULL),
  ('a0fbeb5c-8aa3-56b3-b8f9-8be79cc6d07b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a0fbeb5c-8aa3-56b3-b8f9-8be79cc6d07b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b5f2a810-ef38-5476-95b3-84cd2a55fa46'::uuid, NULL, E'We did not receive any news during his long absence.', NULL, NULL, NULL),
  ('a0fbff6f-ccfe-5a5e-a135-de12a008ccd6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a0fbff6f-ccfe-5a5e-a135-de12a008ccd6'::uuid, 1, NULL, TRUE, 0, NULL, E'Excessive Job Hours', E'Research has shown that excessive job hours, such as working long hours or overtime, can lead to negative outcomes, including increased stress levels, fatigue, and decreased job satisfaction. Additionally, long work hours have been associated with adverse health effects, such as increased risk of cardiovascular disease and mental health issues.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a0fe837d-a3a9-56c0-a5fe-e80f1669c5ed'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a0fe837d-a3a9-56c0-a5fe-e80f1669c5ed'::uuid, 1, NULL, TRUE, 0, NULL, E'Divorce', NULL, '451b20c0-029b-5f5d-915b-64babbb6bcb9'::uuid, NULL, E'Too often in marriage, we make sacrifices, and we demand them, without reckoning their cost. But there is wisdom in looking at the price tags attached to our marital decisions in just the way that divorce law teaches us to do. What I want is for people to think about their marital bargains through the lens of divorce. And to ask, “How is marriage a sacrifice, but an exchange of sacrifice? How do we think about our exchange?” Second: “How do we think about childcare and deal with the fact that there is no such thing as free childcare?” “How do we deal with the fact that some things can be separate and if we don’t think about it, then it will all be part of the joint enterprise.” So basically, what I want to leave you with is that in marriage or divorce, people should think about the way that “till death do us part” marriage is forever.', NULL, NULL, NULL),
  ('a101fe04-1752-56ea-ac85-f35b3584fe0a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a101fe04-1752-56ea-ac85-f35b3584fe0a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which one would a vegetarian most likely to eat, sandwiches or fruit salad?', '62da417d-f312-5f3c-aa9f-0fa8c770483d'::uuid, NULL, NULL, E'Fruit salad', NULL, NULL),
