  ('a10f217d-5416-575a-987a-7a92d4214f50'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a10f217d-5416-575a-987a-7a92d4214f50'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the opposite of introvert?', 'e9461561-11d4-5a27-94f1-d7fd23e9f8b4'::uuid, NULL, NULL, E'Extrovert', NULL, NULL),
