  ('a11725ed-28e2-5ada-8ed9-1b32b28e9be5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a11725ed-28e2-5ada-8ed9-1b32b28e9be5'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3bdc2175-e931-503b-8016-fcf687021107'::uuid, NULL, E'Even in big companies, some bad decisions have been attributed to group conformity.', NULL, NULL, NULL),
  ('a1182fef-0f4c-5f3e-bb08-a5d2e7703c1d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'a1182fef-0f4c-5f3e-bb08-a5d2e7703c1d'::uuid, 1, NULL, TRUE, 0, NULL, E'Conduit of Energy', E'Plants serve as the conduit of energy into the biosphere, provide food and materials used by humans, and they {{1}} our environment. According to Ehrhardt and Frommer, the three major challenges facing humanity in our time are food, energy, and environmental {{2}} . All three are plant related. All of our food is produced by plants, either directly or indirectly via animals that eat them. Plants are a {{3}} of energy production. And they are intimately involved in climate change and a major factor in a variety of environmental concerns, including agricultural expansion and its impact on habitat destruction and waterway pollution.', NULL, NULL, NULL, E'1.shape, 2.degradation, 3.source', NULL, NULL),
  ('a11af7cb-d933-52ee-9b72-2e7b60469ee3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a11af7cb-d933-52ee-9b72-2e7b60469ee3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '97e8806e-47dc-5e77-a5c4-968da2b6a75a'::uuid, NULL, NULL, E'We can''t consider an increase in our price at this stage.', NULL, NULL),
