  ('a12571ca-d981-57b0-8c21-c5128789bb96'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a12571ca-d981-57b0-8c21-c5128789bb96'::uuid, 1, NULL, TRUE, 0, NULL, E'Late for Meeting', E'You are ten minutes late for a meeting because of a traffic jam. How should you explain to your colleagues?', '817c629a-e9e7-502b-9052-cb2b1af128ff'::uuid, NULL, E'Hey everyone, I want to talk to you about something.\nWe seem to have a little issue with my arrival for the meeting.\nIt''s like I was stuck in a traffic jam, which made me ten minutes late for this meeting.\nAnd I''d like to know what you think.', NULL, NULL, NULL),
  ('a12a9849-717a-50dd-9e23-b671b293ee00'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a12a9849-717a-50dd-9e23-b671b293ee00'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '83a3f8dc-399d-5350-8373-180ef136c946'::uuid, NULL, NULL, E'Good journalism stays important and influential for a long time.', NULL, NULL),
  ('a12c0e30-6385-5e75-b953-1eb71f578112'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a12c0e30-6385-5e75-b953-1eb71f578112'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which one of the following is not a mythological animal, unicorn, giraffe, dragon or mermaid?', '33ebcfe6-6e71-530b-b8dd-c648780f4476'::uuid, NULL, NULL, E'Giraffe', NULL, NULL),
  ('a12ed94c-0443-555e-b3c6-372411d7f61b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'a12ed94c-0443-555e-b3c6-372411d7f61b'::uuid, 1, NULL, TRUE, 0, NULL, E'Multilingualism', E'English is the world''s lingua franca, the language of science, technology, business, diplomacy and popular culture. That probably explains why it is the world''s most widely spoken language. It probably also explains why native English speakers are so reluctant to learn a second language. It''s not worth the effort.\nIn 2008, the European Commission carried out a survey of the European Union''s 25 member states. The two with the lowest rates of bilingualism — defined as being able to hold a conversation in more than one language — were the UK and Ireland. About two-thirds of people in these countries speak only English. If a similar story wherever English is spoken as the mother tongue. Only about 25 per cent of US citizens can converse in another language. In Australia, the rates are even lower.\nCompare that with continental Europe, where multilingualism is the rule rather than the exception. More than half of EU citizens are bilingual, and not just because they live in countries like Luxembourg with multiple official languages. Even in France, which has only one official language and is immensely proud of its linguistic heritage, most people speak a second language.\nAgain, that is largely down to the dominance of English. Across Europe, English is by far the most commonly learned language. High levels of bilingualism are not driven by a general desire to learn languages but a specific need to learn English.', NULL, NULL, E'The two countries with the lowest rates of bilingualism are the UK and Ireland, with English being the world''s lingua franca, the language of science, technology, business, diplomacy and popular culture, while more than half of EU citizens are bilingual, because across Europe, English is by far the most commonly learned language.', NULL, 5, 75),
  ('a133a8ba-42c0-5874-af72-ad425a2e769a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a133a8ba-42c0-5874-af72-ad425a2e769a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8286586e-6cb1-581e-ad23-cf6c428df754'::uuid, NULL, NULL, E'Music students will have great opportunities to work with musical professionals.', NULL, NULL),
