  ('a2d7b57c-d364-5f4b-a724-91df58844c10'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a2d7b57c-d364-5f4b-a724-91df58844c10'::uuid, 1, NULL, TRUE, 0, NULL, E'Old English', E'The earliest speakers of English spoke Old English. It developed in a turbulent period of British history. This was just after the Romans had left Britain, around 1,600 years ago. The Romans had colonized Britain but they abandoned the country in the fifth century because the Roman empire was collapsing all around them.', NULL, NULL, NULL, NULL, NULL, NULL),
