  ('a3e7cd4c-7714-514e-a450-37f5ec8a2ebf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', 'a3e7cd4c-7714-514e-a450-37f5ec8a2ebf'::uuid, 1, NULL, TRUE, 0, NULL, E'Fuller''s Dance', E'Fuller devised a type of dance that focused on the shifting play of lights and colors on the voluminous skirts or draperies she wore, which she kept in constant motion principally through movements of her arms, sometimes extended with wands concealed under her costumes. She rejected the technical virtuosity of movement in ballet, the most prestigious form of theatrical dance at that time, perhaps because her formal dance training was minimal. Although her early theatrical career had included stints as an actress, she was not primarily interested in storytelling or expressing emotions through dance; the drama of her dancing emanated from her visual effects.\n\nAccording to the paragraph, all of the following are characteristic of Fuller''s type of dance EXCEPT', NULL, NULL, NULL, E'formal and tough dance training\ntechnical virtuosity of movement', NULL, NULL),
  ('a3ebdb9c-ad45-535f-b734-109d661a3b1c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a3ebdb9c-ad45-535f-b734-109d661a3b1c'::uuid, 1, NULL, TRUE, 0, NULL, E'Protein Tau', E'Researchers have found a novel form of the Alzheimer''s protein tau in the fluid surrounding the brain and spinal cord. This form of tau -- known as MTBR tau -- indicates what stage of Alzheimer''s a person is in and tracks with tangles of tau protein in the brain.', NULL, NULL, NULL, NULL, NULL, NULL),
