  ('a40f319a-1887-5582-b64d-00df399c1c30'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'a40f319a-1887-5582-b64d-00df399c1c30'::uuid, 1, NULL, TRUE, 0, NULL, E'Internet Use', E'People are spending twice as much time online compared to 10 years ago, fueled by increasing use of tablets and smartphones. The biggest increase has been {{1}} young adults, with time spent online almost tripling from 10 hours and 24 minutes each week in 2005 to 27 hours and 36 minutes in 2014.\nIn total, the average adult spends more than 20 hours online a week, which includes time spent on the internet at work. {{2}} the average person spends 2.5 hours every week ''online while on the move'' - away from their home, work or place of study. This is a five-fold {{3}} from 2005, when the figure was just 30 minutes.\nOverall, the proportion of adults using the internet has risen by half - from six in ten in 2005 to almost nine in ten today, {{4}} to Ofcom''s Media Use and Attitudes 2015 report, which questioned 1,890 adults aged 16 and over about their internet consumption habits.', NULL, NULL, NULL, E'1.among, 2.Meanwhile, 3.increase, 4.according', NULL, NULL),
  ('a40f6bf7-ec3c-5014-8ccc-78fbdfb7b4a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'a40f6bf7-ec3c-5014-8ccc-78fbdfb7b4a8'::uuid, 1, NULL, TRUE, 0, NULL, E'Youth Crime', E'Involvement of youth in crime is increasing at an alarming rate. What is your suggestion?', NULL, NULL, NULL, NULL, 200, 300),
  ('a40fba8d-efb9-5d33-9298-0b2a7df00bcd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'a40fba8d-efb9-5d33-9298-0b2a7df00bcd'::uuid, 1, NULL, TRUE, 0, NULL, E'Heat-related illnesses', E'Heat-related illnesses can occur when a person is {{1}} to high temperatures, such that their body cannot cool itself sufficiently through sweating. Symptoms range from mild swelling, rashes, or cramps to {{2}} deadly heat exhaustion and heat stroke. Any person can suffer from heat stress, regardless of age, sex, or health status. Older adults and children, however, have a higher-than-average risk of becoming ill due to exposure to extreme heat. People working outdoors, the socially {{3}} and economically disadvantaged, those with chronic illnesses, and some communities of color are also especially vulnerable to heat. Unusually hot summer temperatures have become more common across the world in recent decades, and extreme heat events (heat waves) are expected to become more frequent and more {{4}} in the future. As a result, the risk of heat-related illness is expected to increase.', NULL, NULL, NULL, E'1.exposed, 2.potentially, 3.isolated, 4.intense', NULL, NULL),
