  ('a4372573-d6c0-5997-a181-fbd972f51550'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'a4372573-d6c0-5997-a181-fbd972f51550'::uuid, 1, NULL, TRUE, 0, NULL, E'Attending courses', E'Some people think students should attend all classes they enrolled in, but other people believe that students can choose to attend the classes or not. Give your own opinion.', NULL, NULL, NULL, NULL, 200, 300),
  ('a43807e8-d5ba-55dd-9145-e1e7438654f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a43807e8-d5ba-55dd-9145-e1e7438654f0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '239d4596-6a4b-576b-8fe1-24f9cc640621'::uuid, NULL, E'Psychology relies on scientific methods to investigate questions and arrive at conclusions.', NULL, NULL, NULL),
  ('a4424f5f-afe8-54ff-acc5-ee27ee0a72b1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a4424f5f-afe8-54ff-acc5-ee27ee0a72b1'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which is the season of the year when plants start growing again?', '6e3ed647-843a-529d-a550-260434507050'::uuid, NULL, NULL, E'Spring', NULL, NULL),
  ('a4455d58-407a-5225-9a55-36067182b27c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'a4455d58-407a-5225-9a55-36067182b27c'::uuid, 1, NULL, TRUE, 0, NULL, E'Sharing', E'Sharing is one of the {{1}} of human {{2}} : give me a cookie and I''m more likely to give you one later. But our bonobo cousins have an odd variation on the practice. They share with {{3}} before friends. The finding is in the journal PLoS ONE.\nResearchers tested bonobo sharing in {{4}} involving {{5}} of the apes. All were born in the wild. In the primary experiment, bonobos were placed in a cage with food, and they could choose to admit either a known member of their group, a stranger, or both. In 51 trials, most bonobos shared the feast, but they let the stranger in first.\nWhy choose an outsider over a friend? In another experiment, the {{6}} found bonobos only shared when doing so led to a social interaction. Giving up some food to strangers lets these apes expand their social network. This behavior may have evolved to promote social tolerance, in contrast with chimps'' {{7}} deadly aggression against strangers. Which means that even when food is offered, there''s still no such thing as a free lunch.', NULL, NULL, NULL, E'1.hallmarks, 2.behaviors, 3.strangers, 4.experiment, 5.fourteen, 6.scientists, 7.sometimes', NULL, NULL),
  ('a447740d-0204-5e15-bc72-2abf2b12a368'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a447740d-0204-5e15-bc72-2abf2b12a368'::uuid, 1, NULL, TRUE, 0, NULL, E'Arabian Desert', E'The Arabian Desert, not to be confused with the Syrian Desert or North Arabian Desert, is the fourth-largest desert in the world. It is second in total land mass for subtropical deserts, with an expansive surface area of 1 million square miles scattered across the Arabian Peninsula. The Arabian Desert is also home to 102 endemic species of mammals and 310 various species of birds.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a448f73d-2669-55bd-901e-84b4f257fe01'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a448f73d-2669-55bd-901e-84b4f257fe01'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the process of rocks breaking down into smaller pieces due to weathering and erosion called?', 'e0d127d9-9176-5303-b1ed-a0dd4102178f'::uuid, NULL, NULL, E'Weathering', NULL, NULL),
  ('a44a098f-60a2-5d7e-9677-b8c767c2a715'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'a44a098f-60a2-5d7e-9677-b8c767c2a715'::uuid, 1, NULL, TRUE, 0, NULL, E'Idea of Beauty', E'When we are very concerned about certain of our physical {{1}} — a nose that is stubbornly a bit too large, eyes that are slightly too far apart, hair that is not as lustrous as it should be — we miss an overall point about our relationship to our appearance: how beautiful we feel has nothing to do with the {{2}} structure of our face or body. It isn’t what we look like that counts: it''s how we feel inside. Our self-assessments are in the end solely {{3}} our relative degrees of self-love and self-contempt. There are people of ideal {{4}} and exceptional beauty who cannot bear what they see in the mirror and others who can contemplate a less than svelte stomach or a no longer so supple kind of skin with indifference and defiant good humor. And at a tragic {{5}} , there are heart-breakingly fine-looking people who starve themselves to ill-health.', NULL, NULL, NULL, E'1.features, 2.objective, 3.based on, 4.proportions, 5.extreme', NULL, NULL),
  ('a44cdd52-c9f3-5f4a-b9c5-30843c00f7a2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'a44cdd52-c9f3-5f4a-b9c5-30843c00f7a2'::uuid, 1, NULL, TRUE, 0, NULL, E'Leaving Homes', E'Young people are leaving their homes from rural areas to study or work in the cities. What are the reasons? Do advantages of this development outweigh its disadvantages?', NULL, NULL, NULL, NULL, 200, 300),
