  ('a497f749-f6a4-5464-ad88-a7929d632584'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a497f749-f6a4-5464-ad88-a7929d632584'::uuid, 1, NULL, TRUE, 0, NULL, E'Protein', E'A single protein is a master regulator of mouse muscle function during aging, a new study finds. Blocking this protein increased muscle strength and endurance in old animals. It may play a role in age-related muscle weakening in humans.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a49b7bc2-8d8e-5328-b4c2-20af5efce43c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a49b7bc2-8d8e-5328-b4c2-20af5efce43c'::uuid, 1, NULL, TRUE, 0, NULL, E'Undesirable Programs', E'Parents can communicate their personal feelings about undesirable programs both by discouraging their children from watching them and by writing to their local television station or to the programs sponsors. The public does have a voice. Clearly, not all programs need please everybody. We do have a choice of programs and we also have a choice, for ourselves and at least for our younger children, of watching or not watching.', NULL, NULL, NULL, NULL, NULL, NULL),
