  ('a49f9902-00d8-5d3b-91ac-aedb89047367'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a49f9902-00d8-5d3b-91ac-aedb89047367'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4013a8c2-00ab-5ceb-ac9a-0737569441f2'::uuid, NULL, E'Emerging technology plays a pivotal role in driving innovation across industries.', NULL, NULL, NULL),
  ('a4a3b3bb-8642-5158-a177-ce0e142aeeb7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a4a3b3bb-8642-5158-a177-ce0e142aeeb7'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the full name for UFO?', '0e1335f2-35cb-54d4-94b8-b7f7bf45c2e2'::uuid, NULL, NULL, E'Unidentified Flying Object', NULL, NULL),
  ('a4a4bdcf-3602-5384-8d5c-ba55e2892ce4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a4a4bdcf-3602-5384-8d5c-ba55e2892ce4'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '66035292-d8b7-5335-a9d4-f735bb1931b6'::uuid, NULL, E'Parents should set a good example to their children.', NULL, NULL, NULL),
  ('a4a8aed8-2851-57b1-869f-2498501d0771'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a4a8aed8-2851-57b1-869f-2498501d0771'::uuid, 1, NULL, TRUE, 0, NULL, E'Grand Canyon 2', E'Few things in the world produce such amazement as one''s first glimpse of the Grand Canyon; it took around more than 2 billion years to create this vast wonder - in some places. 17 miles wide, largely through the relentless force of Colorado River, which runs 277 miles along its length, a mile beneath its towering rims.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a4aa2135-48e5-599b-8dcd-59186ce29522'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'a4aa2135-48e5-599b-8dcd-59186ce29522'::uuid, 1, NULL, TRUE, 0, NULL, E'Existentialism', E'Existentialism is a philosophical movement that became prominent in the 20th century, particularly in the years {{1}} World War II. At its core, existentialism emphasizes the individual human being’s freedom and responsibility to give meaning to their own life. Key existentialist philosophers like Jean-Paul Sartre and Kierkegaard argued for the primacy of existence over essence. This means they believed that human beings define themselves through the choices they {{2}} and the actions they take, rather than having some {{3}} essence or nature that defines who they are. As Sartre famously stated, “existence precedes essence.” This focus on subjective experience and individual freedom leads to the existentialist view that each person must create meaning for themselves in an objectively meaningless and absurd universe. Existentialists do not believe there is any {{4}} meaning or purpose given by a divine being or human nature - there is only the meaning we each generate. This places the {{5}} and responsibility of making choices and directing one’s life solely on the individual.', NULL, NULL, NULL, E'1.following, 2.make, 3.predetermined, 4.overarching, 5.burden', NULL, NULL),
  ('a4c52a1d-9955-5ff7-8e7c-c511f96ea884'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a4c52a1d-9955-5ff7-8e7c-c511f96ea884'::uuid, 1, NULL, TRUE, 0, NULL, E'Animal Fighting', E'When someone commits a criminal act, we always hope the punishment will match the offense. But when it comes to one of the cruelest crimes, animal fighting, things rarely work out that way. Dog-fighting victims are tortured and killed for profit and "sport", yet their criminal abusers often receive a minimal sentence for causing a lifetime of pain.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a4d49043-1a80-5723-873b-07cbe1fd91c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a4d49043-1a80-5723-873b-07cbe1fd91c8'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8250bf1c-f727-5b40-9baa-adc75848f055'::uuid, NULL, NULL, E'The reality of climate change is now recognized by experts.', NULL, NULL),
  ('a4d5b78a-0073-5ed7-9ecb-f922bb025c2a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a4d5b78a-0073-5ed7-9ecb-f922bb025c2a'::uuid, 1, NULL, TRUE, 0, NULL, E'Mass Extinctions', E'Mass extinctions of land-dwelling animals — including amphibians, reptiles, mammals, and birds — follow a cycle of about 27 million years, coinciding with previously reported mass extinctions of ocean life, according to a new analysis.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a4d61427-f837-5337-8b3d-95c8139153c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'a4d61427-f837-5337-8b3d-95c8139153c6'::uuid, 1, NULL, TRUE, 0, NULL, E'Thea Proctor', E'Thea Proctor was just sixteen when her entry at the Bowral Art Competition caught the eye of the judge, Arthur Streeton. It was the first of many associations with art world {{1}} . The next year saw her at the Julian Ashton Art School in the illustrious company of Elioth Gruner, Sydney Long and George Lambert, for whom she often posed and who {{2}} her great friend until his death in 1930. Lambert''s paintings and sketches of Proctor emphasize the elegance of her dress. A keen interest in fashion was just one {{3}} of her fascination with design, and she saw herself as an early style guru on a quest to rid Australian art of "its lack of imagination and inventive design". Skilled in watercolor and drawing, Proctor did not {{4}} herself to paper, canvases or to her popular magazine illustrations; she designed theater sets and a restaurant interior and wrote on a range of subjects from flower arranging to the colors of cars. It made for a busy and {{5}} life but, as she said, she was not the sort of person "who could sit at home and knit socks."', NULL, NULL, NULL, E'1.recruits, 2.remained, 3.aspect, 4.limit, 5.varied', NULL, NULL),
  ('a4e0c396-ab9c-5ba5-b14a-0026a216a201'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a4e0c396-ab9c-5ba5-b14a-0026a216a201'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for a word that expresses strong emotion or surprise, such as "Wow!" or "Ouch!"?', 'fffc882d-8de7-50e1-a81a-e6d2ee43e143'::uuid, NULL, NULL, E'Interjection / exclamation', NULL, NULL),
