  ('a508ad39-3cb6-5861-b656-8c7df8327989'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a508ad39-3cb6-5861-b656-8c7df8327989'::uuid, 1, NULL, TRUE, 0, NULL, E'Life Expectancy', E'Life expectancy has increased dramatically in the last century. Most people these days will live for over 70 years. This is more than double the lifespan of the average human in the seventeenth century. We can attribute our longevity to advances in medicine and lifestyle. While everyone agrees that living longer is wonderful, overpopulation is becoming a serious environmental concern.', NULL, NULL, NULL, NULL, NULL, NULL),
