  ('a585a03f-1f31-5ae3-b6d3-1d9a0a5f7280'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a585a03f-1f31-5ae3-b6d3-1d9a0a5f7280'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3d35dd8b-dd36-51d2-8725-ba5271f9216f'::uuid, NULL, E'Some health staff believe elderly people can''t grasp new things.', NULL, NULL, NULL),
  ('a5879803-c7bf-51e6-a33c-7567321078bc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a5879803-c7bf-51e6-a33c-7567321078bc'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e751c58d-8a99-53c5-8a6f-5a673ee955c9'::uuid, NULL, NULL, E'Academic staff are key to achieving the university education goals.', NULL, NULL),
  ('a58bb94f-d453-5399-abfa-1dd81935fcdb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'a58bb94f-d453-5399-abfa-1dd81935fcdb'::uuid, 1, NULL, TRUE, 0, NULL, E'Electric Eels', E'On a field trip to the Amazon in 1807, 19th-century explorer Alexander von Humboldt witnessed a group of horses lead through a muddy pool filled with electric eels, which he described as dramatically leaping up to attack the intruders. But scientists have doubted the story.\nBelow is an illustration of Alexander von Humboldt''s story of the battle between the horses and electric eels.\n“The first time I read von Humboldt''s tale, I thought it was completely bizarre,” Catania says. “Why would the eels attack the horses instead of swimming away?” But then he observed the same behaviour by accident as he transferred the eels in his lab from one tank to another using a metal-rimmed net. Instead of swimming away, larger eels attacked the net by leaping out of the water.\nCatania tracked the strength of the eels’ electric shock by attaching a voltmeter to an aluminium plate, or conductive metal strips to “predator” objects such as a crocodile head replica.\nThe zap a submerged eel distributes through the water is relatively weak when it reaches the target.\nBut when an eel touches it with its electricity-generating chin, the current travels directly to the target and has to travel through its body before it gets back to the water, Catania reported in Proceedings of the National Academy of Sciences.\n“This allows the eels to deliver shocks with a maximum amount of power to partially submerged land animals that invade their territory,” Catania explains. “It also allows them to electrify a much larger portion of the invader''s body.”\nCatania found the eels leapt to attack, rather than receding, more often when the water in the aquarium was lower. He argues the attack lets electric eels better defend themselves during the Amazonian dry season, when they’re cornered in small pools and make easy prey.', NULL, NULL, E'Alexander witnessed a group of horses lead through a muddy pool filled with electric eels, but scientists have doubted the story, when Catania tracked the strength of the eels’ electric shock, and he found that the eels leapt to attack more often when the water in the aquarium was lower, so the attack lets electric eels better defend themselves during the Amazonian dry season, when they’re cornered in small pools and make easy prey.', NULL, 5, 75),
  ('a58cfba6-6713-55e2-b5c0-e23a25da9da8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a58cfba6-6713-55e2-b5c0-e23a25da9da8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Who is in charge of a museum or art gallery?', 'd2065789-e78d-514e-b3df-9df233719d8b'::uuid, NULL, NULL, E'Curator', NULL, NULL),
