  ('a5a40273-599c-5680-99de-0fa7bf2fbed3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a5a40273-599c-5680-99de-0fa7bf2fbed3'::uuid, 1, NULL, TRUE, 0, NULL, E'Train Noise', E'There are other components, aside from the wheels and rails, that add to the noise a train makes when it passes. Older trains had their air conditioning units underneath the carriage, but modern trains have been lowered to allow people with less mobility to enter the carriage more easily. As a result, air conditioning units are now on top of the carriage, where they add to the train noise.', NULL, NULL, NULL, NULL, NULL, NULL),
