  ('a5cde0e3-262e-51f0-ae3e-c4d561e3143d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'a5cde0e3-262e-51f0-ae3e-c4d561e3143d'::uuid, 1, NULL, TRUE, 0, NULL, E'Planes', E'By 2025, government experts say, America''s skies will swarm with three {{1}} as {{2}} planes, and not just the kind of traffic flying today. There will be {{3}} of tiny jets, seating six or fewer, at airliner {{4}} , competing for space with remotely operated drones that need help avoiding mid-air {{5}} , and with commercially operated rockets carrying {{6}} and tourists into space.', NULL, NULL, NULL, E'1.times, 2.many, 3.thousands, 4.altitudes, 5.collisions, 6.satellites', NULL, NULL),
  ('a5cf6085-e306-5ee3-bb2d-1ba5d669221e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a5cf6085-e306-5ee3-bb2d-1ba5d669221e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'cb21000a-49e3-5a03-b661-2af793fa708b'::uuid, NULL, NULL, E'Many food crops require a large amount of water and fertilizer.', NULL, NULL),
