  ('a5d279b5-6564-53b8-925c-f87fde2983ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a5d279b5-6564-53b8-925c-f87fde2983ee'::uuid, 1, NULL, TRUE, 0, NULL, E'Survivors', E'Our survivors have told me many times that hate starts small and it grows when your neighbours, workmates and friends ignore it and do nothing. Hate triumphs when intolerance and prejudice become ingrained across an entire society, from the pages of newspapers to the halls of government, from schoolrooms to boardrooms.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a5d3a2fa-f6c7-5c9e-b8e2-ef31f6571071'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'a5d3a2fa-f6c7-5c9e-b8e2-ef31f6571071'::uuid, 1, NULL, TRUE, 0, NULL, E'Human Remains', E'In 1959, the partial skeletal remains of an ancient woman estimated to be 10,000 years old were unearthed in Arlington Springs on Santa Rosa Island, one of the eight Channel Islands off the southern California coast. They were discovered by Phil C. Orr, curator of anthropology and natural history at the Santa Barbara Museum of Natural History. The remains of the so-called Arlington Springs woman were recently reanalyzed by the {{1}} radiocarbon dating techniques and were found to be approximately 13,000 years old. The new date makes her remains older than any other known human skeleton found {{2}} in North America. The discovery {{3}} the popular belief that the first colonists to North America arrived at the end of the last ice age about 11,500 years ago {{4}} a Bering land bridge that connected Siberia to Alaska and northwestern Canada. The earlier date and the location of the woman''s remains on the island adds weight to an alternative theory that some early settlers may have constructed boats and migrated from Asia by sailing down the Pacific coast.', NULL, NULL, NULL, E'1.latest, 2.so far, 3.challenges, 4.by crossing', NULL, NULL),
  ('a5e44f07-ec87-5815-899e-d0ba756df43f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a5e44f07-ec87-5815-899e-d0ba756df43f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Who proposed the theory of relativity?', '96064a9e-12f4-5a85-85d4-e923cccce470'::uuid, NULL, NULL, E'Einstein', NULL, NULL),
