  ('a5f52f6e-38c0-5129-95ad-dc7c8385dba6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'a5f52f6e-38c0-5129-95ad-dc7c8385dba6'::uuid, 1, NULL, TRUE, 0, NULL, E'Cryptocurrency Scams', E'Cryptocurrency scams have become increasingly prevalent as digital currencies gain popularity. Fraudulent schemes often {{1}} high profits through complex trading strategies or mining investments but instead use funds from new investors to pay {{2}} to earlier investors, similar to a Ponzi scheme. Investors are urged to {{3}} caution and perform due {{4}} before engaging with cryptocurrency ventures.', NULL, NULL, NULL, E'1.promise, 2.returns, 3.exercise, 4.diligence', NULL, NULL),
  ('a5f579fd-7512-5291-849a-7aac481f878e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a5f579fd-7512-5291-849a-7aac481f878e'::uuid, 1, NULL, TRUE, 0, NULL, E'Magnetic Field', E'The magnetic field is a vector field - at each point it has a magnitude and direction. The direction is defined as the direction of the force that a magnetic north pole would feel at that point. Since like poles repel and opposite poles attract, this means that the magnetic field goes away from the north pole of a magnet and towards the south pole.', NULL, NULL, NULL, NULL, NULL, NULL),
