  ('a6199995-1b73-582c-b83e-916d77b194f6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a6199995-1b73-582c-b83e-916d77b194f6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '89c94c99-cca8-5136-bfeb-7f7b4679b933'::uuid, NULL, E'European car manufacturers are struggling due to their reliance on diesel.', NULL, NULL, NULL),
  ('a621ecc3-9983-5a8e-944b-cb9acbb0d6b4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a621ecc3-9983-5a8e-944b-cb9acbb0d6b4'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the sum of the lengths of the sides of a polygon?', '9e05cffc-8c53-5ace-b102-5b9b1b6b1e71'::uuid, NULL, NULL, E'Perimeter', NULL, NULL),
  ('a6257451-7263-5a28-90a5-764721f18e62'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a6257451-7263-5a28-90a5-764721f18e62'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f8d23e7d-afbc-5a6a-a976-86faf37fc864'::uuid, NULL, NULL, E'Generally young children around the world enjoy listening to stories.', NULL, NULL),
  ('a62b9949-da5c-55e7-979f-9c1958d5030e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'a62b9949-da5c-55e7-979f-9c1958d5030e'::uuid, 1, NULL, TRUE, 0, NULL, E'Corn People', E'Descendants of the Maya living in Mexico still sometimes refer to themselves as “the corn people.” The phrase is not intended as metaphor. Rather, it’s meant to {{1}} their abiding dependence on this miraculous grass, the {{2}} of their diet for almost 9,000 years. Forty percent of the calories a Mexican eats in a day comes directly from corn, most of it in the form of tortillas. So when a Mexican says I am maize or corn walking, it is simply a statement of fact: The very substance of the Mexicans body is to a considerable extent a {{3}} of this plant.', NULL, NULL, NULL, E'1.acknowledge, 2.staple, 3.manifestation', NULL, NULL),
  ('a62cda92-6f5a-50a4-bbe0-ac12b7250dd8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a62cda92-6f5a-50a4-bbe0-ac12b7250dd8'::uuid, 1, NULL, TRUE, 0, NULL, E'Consultation', E'The Mexican government began a 90-day consultation on the North American Free Trade Agreement with the country’s lawmakers and business community. The discussion is required before holding talks with America to review NAFTA’s terms. Donald Trump wants to renegotiate the trade pact—of which Canada is also a member—to get better terms for America.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a62eb982-5bb8-5e2c-a727-af9b4bddc8c9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a62eb982-5bb8-5e2c-a727-af9b4bddc8c9'::uuid, 1, NULL, TRUE, 0, NULL, E'Bomb Calorimeter', NULL, 'f75893e7-e8e6-5520-9110-2d5a3d071ac0'::uuid, NULL, E'This is a bomb calorimeter; this is the actual piece of equipment that researchers used to calculate the energy content of either biodiesel or maybe even the potato chips that you had for lunch today. When they calculate the amount of energy. They’re going to calculate it in heat unites which would either be joules or calories. I want you to look inside the bomb calorimeter inside here, you can see that there’s a silver bucket water goes all in here and this is actually the bomb is the smaller silver cylinder what you do is put your fuel sample in there then these two electrodes are connected to the bomb. These provide the spark that will ignite your sample when your sample burns or combust that gives off energy. So how is the energy collected or how did a scientist figure out how much energy is being given off. Well, it’s a closed system, there’s a lid here that goes on top of this calorimeter and what’s in here in the lid is a stirrer. The stir is going to stir the water. That’s in this big pool here so that the heat given off from the sample is going to warm the water in a uniform way. This is the temperature probe, this goes down in the water also and measures the change in temperature because as the sample is burned, it will give off heat and the temperature the water will increase. So the lid goes on the sample is prepared. The last thing that you need to make a combustion reaction happen is oxygen and at some point during the process, some oxygen is added by a tank. That’s connected to the calorimeter here. So we are going to burn a sample of the biodiesel that you’ve prepared and get some feedback on the energy content of it. You’ll be able to use this to compare it to petroleum-based fuels like octane.', NULL, NULL, NULL),
  ('a63287d3-5c19-5410-aa5c-30f7a8584594'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'a63287d3-5c19-5410-aa5c-30f7a8584594'::uuid, 1, NULL, TRUE, 0, NULL, E'Pandemic Impact', E'Anna was a 15-year-old girl who loved to {{1}} out with her friends, play soccer, and listen to music. She was looking forward {{2}} high school and exploring new subjects and activities. But then the covid-19 pandemic {{3}} , and everything changed. She had to stay at home, attend online classes, and avoid social gatherings. She felt lonely, bored, and anxious. She was not alone. Many adolescents around the world experienced similar challenges during the pandemic. A new study found that the pandemic had a particularly large effect on the ageing rate of adolescent girls’ brains. The researchers speculated that the pandemic might have {{4}} the normal development of the adolescent brain, which is sensitive to environmental influences. They suggested that factors such as stress, isolation, lack of stimulation, and reduced physical activity might have contributed to the brain changes. They also warned that these changes might have long-term {{5}} for cognitive and mental health. They called for more research and interventions to support adolescents during and after the pandemic.', NULL, NULL, NULL, E'1.hang, 2.to starting, 3.hit, 4.disrupted, 5.consequences', NULL, NULL),
  ('a634004e-9d03-506e-9e49-24040632b8b3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a634004e-9d03-506e-9e49-24040632b8b3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '70ea0012-9ab3-57ba-98ef-f38ec51699a7'::uuid, NULL, E'Population growth often leads to increased demands on limited natural resources.', NULL, NULL, NULL),
  ('a6344d06-cb03-5e4e-9a8b-dfcf528db1ab'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a6344d06-cb03-5e4e-9a8b-dfcf528db1ab'::uuid, 1, NULL, TRUE, 0, NULL, E'Credit Unions', E'Credit unions are nonprofit organizations that were imported to the United States from Germany in the early 1900s. They were regulated in 1934 by the Federal Credit Union Act, which limits membership to "groups having a common bond of occupation or association". Groups from particular geographical areas also were eligible to join credit unions.', NULL, NULL, NULL, NULL, NULL, NULL),
