  ('a63994a2-9baa-5627-b979-5ce1ff5a0fc9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a63994a2-9baa-5627-b979-5ce1ff5a0fc9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '89a57f88-27a8-5646-b970-ccff7c826e02'::uuid, NULL, E'Long thin wires have more resistance than short thick wires do.', NULL, NULL, NULL),
  ('a63d00cf-c667-522c-8539-89bf8a60e175'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a63d00cf-c667-522c-8539-89bf8a60e175'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7f1924a1-6118-58c4-8019-c5fe474c0ea3'::uuid, NULL, NULL, E'The first assignment is due on the fourteenth of September.', NULL, NULL),
  ('a641045b-76c4-5d52-800d-4c28b229db70'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'a641045b-76c4-5d52-800d-4c28b229db70'::uuid, 1, NULL, TRUE, 0, NULL, E'Gender Studies', E'Gender studies is a dynamic field of academic inquiry that has evolved significantly over the years. It encompasses the study of gender roles, identities, and the impact of societal norms and expectations on individuals.\nIn recent decades, gender studies has expanded its focus beyond a binary understanding of gender to recognize the complexity and diversity of human identities. It acknowledges that gender is not limited to just male and female but exists on a spectrum. This shift has been essential in acknowledging and respecting the experiences of transgender and non-binary individuals.\nAnother significant development in gender studies is the intersectionality perspective. It recognizes that gender cannot be studied in isolation but is deeply intertwined with other aspects of identity, such as race, ethnicity, class, and sexuality. This approach has led to a more comprehensive understanding of the experiences of marginalized groups and has informed social justice movements.\nFurthermore, gender studies has played a crucial role in raising awareness about issues such as gender-based violence, workplace discrimination, and unequal access to resources. It has been instrumental in advocating for policy changes and promoting social change to address these issues.\nAdditionally, gender studies has found its way into various disciplines, influencing fields like psychology, sociology, and public health. It has enriched the academic landscape by encouraging scholars to consider the role of gender in their research.\nIn conclusion, gender studies has undergone significant transformation, embracing a more inclusive and intersectional perspective. It continues to be a driving force in promoting gender equality, challenging stereotypes, and fostering a deeper understanding of the complex interplay between gender and society.', NULL, NULL, E'Gender studies has evolved from a binary understanding of gender to embrace diversity and intersectionality, playing a pivotal role in advocating for gender equality, challenging stereotypes, and fostering a comprehensive understanding of how gender interacts with various aspects of society.', NULL, 5, 75),
  ('a64438ff-def0-55de-ac6f-7e9dfedab368'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a64438ff-def0-55de-ac6f-7e9dfedab368'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'aa18dcaf-dab0-51ba-955e-0de0dc402f28'::uuid, NULL, NULL, E'You can now watch many school classes online from your home.', NULL, NULL),
