  ('a66a0f50-b626-5ade-98b0-dc528c537001'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a66a0f50-b626-5ade-98b0-dc528c537001'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd440802b-f2e3-52e6-b450-fcba64ac8edb'::uuid, NULL, E'A good education helps you recognize yourself and your strengths.', NULL, NULL, NULL),
  ('a66a9ab9-9bec-561c-8149-ca4a22a5a60f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a66a9ab9-9bec-561c-8149-ca4a22a5a60f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ba5d56a5-92be-5bd3-8a99-b507d2240c40'::uuid, NULL, NULL, E'He''s the president of a large international organization.', NULL, NULL),
  ('a672cbe0-1a2d-54cd-934b-b835e9cbeb50'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a672cbe0-1a2d-54cd-934b-b835e9cbeb50'::uuid, 1, NULL, TRUE, 0, NULL, E'Job Hours', E'Most of us spend on average 18 hundred hours per year in our jobs, and will work for about 40 years before retirement. When you consider the amount of time spent in the office, you soon realize how important it is to feel a sense of achievement at the end of the day, rather than just meeting financial objectives.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a67793f8-06fe-59a6-8047-a267dc1158e8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'a67793f8-06fe-59a6-8047-a267dc1158e8'::uuid, 1, NULL, TRUE, 0, NULL, E'Plantation', E'The term plantation arose as settlements in the southern United States, originally linked with colonial expansion, came to revolve around the production of agriculture. The word plantation first appeared in English in the 15th century. Originally, the word meant to plant. However, what came to be known as plantations became the center of large-scale enslaved labor operations in the Western Hemisphere. Historians Peter H. Wood and Edward Baptist advocate to stop using the word plantation when referencing agricultural operations involving forced labor. Instead they suggest calling these places ‘labor camps’ or ‘slave labor camps’. The plantation system developed in the American South as British colonists arrived in what became known as Virginia and divided the land into large areas suitable for farming. The land on which these plantations were established was stolen through canceled, disregarded, and deceitful treaties, or outright violence from indigenous nations. The plantation system came to dominate the culture of the South, and it was rife with inequity from the time it was established. In 1606, King James I formed the Virginia Company of London to establish colonies in North America, but when the British arrived, they faced a harsh and foreboding wilderness, and their lives became little more than a struggle for survival. So, to make settling the land more attractive, the Virginia Company offered any adult man with the means to travel to America 50 acres of land. At the encouragement of the company, many of the settlers banded together and created large settlements, called hundreds, as they were intended to support 100 individuals, usually men who led a household.', NULL, NULL, NULL, NULL, 5, 75),
  ('a67a40c1-68aa-5e68-aaf3-3ccb1f0a8310'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a67a40c1-68aa-5e68-aaf3-3ccb1f0a8310'::uuid, 1, NULL, TRUE, 0, NULL, E'Primitive Societies', E'Early in the field''s history, anthropologists were almost all Europeans or Americans who conducted research in what they considered to be "primitive" societies that they believed were "untouched" by western influence. Because of this mindset, the field has long been critiqued for its colonialist, condescending attitude toward non-western people and its inaccurate representations of their cultures.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a68263c8-b9c4-5a71-9ab2-21291d850636'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a68263c8-b9c4-5a71-9ab2-21291d850636'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do butterflies fly?', 'ab1c19a2-de8e-53e9-9e57-718f763c9fdd'::uuid, NULL, NULL, E'Flutter', NULL, NULL),
  ('a684025a-a99d-5eb8-88df-76e60fd4f25d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'a684025a-a99d-5eb8-88df-76e60fd4f25d'::uuid, 1, NULL, TRUE, 0, NULL, E'Brand Awareness', E'Branding is more important than some marketers think, with 81 percent of consumers stating they only buy from brands they trust. This feeling cuts across all global markets, ages, and income groups.\nConsumers need to be aware of your brand before they can decide whether to trust you or not. When it comes to creating brand awareness, there’s hardly a more effective way than using social media. Roughly 97 percent of Fortune 500 enterprises use social media to enhance their initiatives and boost communication with their stakeholders.\nIn an increasingly digitized world, the world has migrated to social media. As of 2021, there are about 3.78 billion social media users worldwide, and the number keeps growing. Small businesses that harness the unprecedented power of social media stand to succeed.\nThe crucial step in brand awareness with social media is to make sure you’re targeting the right audience. Take the time to define your audience so you can come up with content that resonates best with them. Ideally, you want to target people who need your product or service the most. Once you determine who these people are, it becomes easier to connect and interact with them.\nAnother important step is to take the time to do your research: know what social media platforms they’re most likely to use frequently. One way to determine the right social media platform to use is to take a closer look at what product or service you offer.', NULL, NULL, NULL, NULL, 5, 75),
  ('a685a80e-e9ea-52e8-8962-e40358b67f17'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'a685a80e-e9ea-52e8-8962-e40358b67f17'::uuid, 1, NULL, TRUE, 0, NULL, E'Dark Matter', E'A new interdisciplinary centre for the study of the frontiers of the universe, from the tiniest subatomic particle to the largest chain of galaxies, has been formed at the University of Texas at Austin. The Texas Cosmology Center will be a way for the university''s departments of Astronomy and Physics to {{1}} on research that concerns them both. "This centre will bring the two departments together in an area where they {{2}} —— in the physics of the very early universe," said Dr. Neal Evans, Astronomy Department chair. Astronomical observations have revealed the presence of dark matter and dark energy, {{3}} that challenge our knowledge of fundamental physics. And today''s leading theories in physics {{4}} energies so high that no earthbound particle accelerator can test them. They need the universe as their {{5}} . Dr. Steven Weinberg, Nobel laureate and professor of physics at the university, called the advent of the centre "a very exciting development" for that department.', NULL, NULL, NULL, E'1.collaborate, 2.overlap, 3.discoveries, 4.involve, 5.laboratory', NULL, NULL),
  ('a687c321-9ae0-5ab4-9ee0-9946c83e3e2c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a687c321-9ae0-5ab4-9ee0-9946c83e3e2c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '585cde54-90ee-5991-bf6f-b6fdf84a8802'::uuid, NULL, NULL, E'Relevant materials are reserved in the library.', NULL, NULL),
