  ('a695bd19-f036-5fa1-aeef-7fe3438a9820'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a695bd19-f036-5fa1-aeef-7fe3438a9820'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'af452f45-1b9b-5eea-856c-7eb92b8a49fa'::uuid, NULL, E'Most students in last year''s course did well in this module.', NULL, NULL, NULL),
