  ('a6975a26-9868-58bd-a534-84c5e72c0fca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a6975a26-9868-58bd-a534-84c5e72c0fca'::uuid, 1, NULL, TRUE, 0, NULL, E'Psychologist', E'Psychologist Saho Takagi, a graduate student at Kyoto University in Japan, strolls into one of Japan''s many cat cafes. These establishments allow customers to pay an hourly fee for the chance to cuddle some cats. They''re popular in Japan because so many apartment buildings forbid pet ownership. But Takagi isn''t a typical customer. She’s not there for feline affection, but to probe their minds.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a69a4cc4-a85a-50a4-9fec-3f12051902e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'a69a4cc4-a85a-50a4-9fec-3f12051902e1'::uuid, 1, NULL, TRUE, 0, NULL, E'Atmospheric Circulation', E'From the gentlest of breezes to the raging winds of a category-five hurricane, the atmosphere is constantly in {{1}} . The energy for all that movement comes from sunlight that is {{2}} and re-radiated by the surface of the Earth and the rotation of the Earth. Atmospheric circulation, along with ocean circulation, {{3}} heat across the entire surface of the Earth, bringing us our daily weather and {{4}} regional climates.', NULL, NULL, NULL, E'1.motion, 2.absorbed, 3.distributes, 4.shaping', NULL, NULL),
  ('a69ebb8d-10bc-5de0-896a-50998b0b2ee6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a69ebb8d-10bc-5de0-896a-50998b0b2ee6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '28e2ec9d-c4e8-5f3e-8d1c-741eece807ee'::uuid, NULL, E'The feeling of disgust is related to the stomach.', NULL, NULL, NULL),
  ('a6a21df2-a051-537a-b9e9-b77962701c9b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'a6a21df2-a051-537a-b9e9-b77962701c9b'::uuid, 1, NULL, TRUE, 0, NULL, E'Hibernation', E'Hibernation allows the animal to {{1}} energy during periods of food scarcity or cold weather when there’s not much to do, when animals eat lots of extra food to {{2}} fat stores for hibernation. This fat will {{3}} the animal the whole winter so there has to be enough. Hibernation is most commonly observed in some mammals, but some reptiles and amphibians also {{4}} hibernation-like behavior.', NULL, NULL, NULL, E'1.conserve, 2.build, 3.feed, 4.exhibit', NULL, NULL),
  ('a6ab8b8d-7a2e-5500-9f22-52a9b3a3839f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a6ab8b8d-7a2e-5500-9f22-52a9b3a3839f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'eb6bfcfb-0f7c-5daa-b420-e4cd9b3e3637'::uuid, NULL, E'When the demand for the course rose, university authorities took on additional academic staff.', NULL, NULL, NULL),
  ('a6b2dec8-7621-5fc3-8d2a-db90b4c21c6d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a6b2dec8-7621-5fc3-8d2a-db90b4c21c6d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6cd47a6e-d633-5475-9a38-33c220f88815'::uuid, NULL, E'Try to explain how your ideas are linked so that there is a logical flow.', NULL, NULL, NULL),
  ('a6b7bce0-12d6-56d0-be02-8d8da94920e7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a6b7bce0-12d6-56d0-be02-8d8da94920e7'::uuid, 1, NULL, TRUE, 0, NULL, E'School Shooting', E'Current policy responses do not address the fundamental question of why so many mass shootings take place in schools. To answer this question, we need to get to the heart of how students experience school and the meaning that schools have in American life. While some of these measures seem sensible, overall there is little empirical evidence that such security measures decrease the likelihood of school shootings.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a6b82a23-0461-5161-a333-253202a75bb7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a6b82a23-0461-5161-a333-253202a75bb7'::uuid, 1, NULL, TRUE, 0, NULL, E'Four Dimensions', NULL, 'e0ece353-934e-5eaf-b8ae-0221527d4f08'::uuid, NULL, E'In physics, people often describe the universe as existing in a four-dimension space. Unlike traditional three-dimensional space, which only includes location, the fourth dimension adds another important factor: time. The three basic spatial dimensions are longitude, latitude, and altitude. Longitude and latitude help us locate a position on the Earth, while altitude shows the height of an object. When time is added, these four elements allow scientists to describe anything in space. With these four dimensions, we can identify the location of an object or event at any time. For example, if we want to describe an event, we need to provide information about its position and moment of occurrence, including longitude, latitude, altitude, and date. The concept of the fourth dimension helps researchers better understand movement, changes, and events in the universe. It provides a more complete way to describe not only where something happens but also when it happens.', NULL, NULL, NULL),
  ('a6b955ad-a153-5d83-94ef-070fc5809d4e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a6b955ad-a153-5d83-94ef-070fc5809d4e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b3cb847d-af54-59f8-80e1-820be98c44be'::uuid, NULL, NULL, E'Nature is defined as specific chemical compounds.', NULL, NULL),
  ('a6bba91e-cc47-5025-98dd-38df8b927ede'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a6bba91e-cc47-5025-98dd-38df8b927ede'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which one is more shining, gold or silver?', '333cd656-fafe-506e-b945-4870d191832b'::uuid, NULL, NULL, E'Gold', NULL, NULL),
  ('a6bf5759-8fda-5e34-bccb-922df656178d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a6bf5759-8fda-5e34-bccb-922df656178d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the process of artificially introducing immunity against a specific infectious disease?', '8dba7f51-6f99-538b-9e99-cd85d0dca326'::uuid, NULL, NULL, E'Vaccination', NULL, NULL),
  ('a6c0248e-9ca7-5461-b9ca-90ef1d002fd9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a6c0248e-9ca7-5461-b9ca-90ef1d002fd9'::uuid, 1, NULL, TRUE, 0, NULL, E'What You Want', E'The listening is critical to the transformation. Parker Palmer said that, "Before I can tell my life what I want to do with it, I have to listen to my life telling me who I am." How many of us do that? So if we want to desire differently, mine your life for those stories when you were engaged in deeply meaningful and fulfilling action, and see if there''s a pattern. I promise you, if you go through your life and you identify three, four, five of these fulfillment stories, you will probably begin to see a pattern emerge. And that''s your life telling you something about where you find fulfillment in your desires. We usually wanna get to the transformation and the change right away, but before we can go there, we have to simply take the time to...\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '70c8ce9e-af76-53c8-b2fe-901c357a2cbc'::uuid, NULL, NULL, E'listen', NULL, NULL),
  ('a6c7609e-1d8c-5c96-ab21-7f878fedc53c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a6c7609e-1d8c-5c96-ab21-7f878fedc53c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4768a10e-9dc8-5b77-a269-4851a9f8347c'::uuid, NULL, E'Please bring back all library books by the end of the week.', NULL, NULL, NULL),
