  ('a6d27694-a2b4-5b6d-8276-6dca93acac6d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a6d27694-a2b4-5b6d-8276-6dca93acac6d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '592c148a-b8b5-5200-8d3e-398143094732'::uuid, NULL, E'Our fundamental realities, especially national needs, have seen the ability to flourish.', NULL, NULL, NULL),
  ('a6dcb444-dff5-513b-b0e3-6652d357ab03'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a6dcb444-dff5-513b-b0e3-6652d357ab03'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9b85b5ee-6dac-5c29-b9f9-ac81f5ffd04d'::uuid, NULL, NULL, E'Colleges are now putting money into new ways to teach with tech.', NULL, NULL),
  ('a6e76564-0984-5919-b2aa-295ed7e40a2f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a6e76564-0984-5919-b2aa-295ed7e40a2f'::uuid, 1, NULL, TRUE, 0, NULL, E'Alexander the Great', E'Before the time of Alexander the Great, the only eastern people who could be compared with the Greeks in the fields of science and philosophy were from the Indian sub-continent. However, because so little is known about Indian chronology, it is difficult to tell how much of their science was original and how much was the result of Greek influence.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a6e85940-781d-5e8f-aaee-33ee4a3988c9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a6e85940-781d-5e8f-aaee-33ee4a3988c9'::uuid, 1, NULL, TRUE, 0, NULL, E'Tool-user', E'The human animal''s status as the only clever tool-user who can talk about our feelings is crumbling. Prairie dogs can make up words for new animals. Crows are born with the ability to make tools. As biologists delve into these subjects, they''re demonstrating that we''re not nearly as unique as we once thought. It''s the perfect time, scientifically speaking, to reassess our place in the animal kingdom.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a6ea7f30-0cf5-5294-b335-9cfb1b207141'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a6ea7f30-0cf5-5294-b335-9cfb1b207141'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '06e693ca-4420-5da5-af88-c072f7ee9e08'::uuid, NULL, NULL, E'Agricultural development plays a vital role in poor and rural areas.', NULL, NULL),
  ('a6ead2ab-5928-5e6a-8a44-b1d66d79ea60'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a6ead2ab-5928-5e6a-8a44-b1d66d79ea60'::uuid, 1, NULL, TRUE, 0, NULL, E'Moon Transportation', E'Although it is difficult to take people back to the Moon, it is not impossible! We can transport people but the logistical challenge of keeping them there, is a very different thing. However, we have two of the components necessary to make this work: power from the Sun, and the minerals on the Moon itself. Scientists and researchers are already busy working on this in laboratories.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a6ec8783-e7ef-563f-9fc1-57e6118967c7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a6ec8783-e7ef-563f-9fc1-57e6118967c7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '638fe587-c2da-5143-a390-e2b596a6d0c6'::uuid, NULL, NULL, E'Application forms should be submitted in one week.', NULL, NULL),
  ('a6f46fe2-1d8c-5022-907a-cf9a64f33f2e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a6f46fe2-1d8c-5022-907a-cf9a64f33f2e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '381cde29-1072-5fe7-af73-145da32a0216'::uuid, NULL, NULL, E'The concept has inherent imperfections and necessitates thorough and deliberate evaluation.', NULL, NULL),
  ('a6f60e3b-2e45-55c5-8025-8c5a0dee0424'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a6f60e3b-2e45-55c5-8025-8c5a0dee0424'::uuid, 1, NULL, TRUE, 0, NULL, E'Paper Money', E'The Chinese were, as far as we know, the inventors of paper money and because it was so easy to move compared with coins, it was named "flying money". They were also the first to experience an economic problem which has become all too familiar: by the 12th century, there was money in circulation to cause serious inflation. In Europe, it wasn''t until about 1400 that bankers in Spain and Italy began to honor "bills of exchange", which were a kind of private paper money not in general use. They were documents used by those involved in a business transaction in which payment was made through a third party to avoid the cost of foreign exchange. However, it is the Swedes who are generally credited with producing the first proper European bank [BEEP]\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '91eeb484-48d3-5e4e-ae7d-505cc1434c43'::uuid, NULL, NULL, E'notes', NULL, NULL),
  ('a6f66906-bd7b-527a-8ed5-94874591b867'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a6f66906-bd7b-527a-8ed5-94874591b867'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What instrument do you use when long-distance learning?', 'b2321252-3020-59bb-b740-6cc1a0337171'::uuid, NULL, NULL, E'Computer', NULL, NULL),
  ('a6fb5a1b-2f96-55bf-b4f9-baf2f7c0e490'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'a6fb5a1b-2f96-55bf-b4f9-baf2f7c0e490'::uuid, 1, NULL, TRUE, 0, NULL, E'Online Teaching & Learning', E'What makes teaching online unique is that it uses the internet, especially the World Wide Web, as the primary means of communication. Thus, when you teach online, you don''t have to be someplace to teach. You don''t have to lug your briefcase full of paper or your laptop to a classroom, stand at a lectern, scribble on a chalkboard (or even use your high-tech, interactive classroom "smart" whiteboard), or grade papers in a stuffy room while your students take a test. You don''t even have to sit in your office waiting for students to show up for conferences. You can hold "office hours" on weekends or at night after dinner. You can do all this while living in a small town in Wyoming or a big city like Bangkok, even if you are working for a college whose administrative office is located in Florida or Dubai. You can attend an important conference in Hawaii on the same day you teach your class in New Jersey, logging on from your laptop via the local café''s wireless hotspot or your hotel room''s high-speed network. Or you may simply pull out your smartphone to quickly check on the latest postings, email, or text messages from students.\nOnline learning offers more freedom for students as well. They can search for courses using the Web, scouring their institution or even the world for programs, classes, and instructors that fit their needs. Having found an appropriate course, they can enroll and register, shop for their books, read articles, listen to lectures, submit their homework assignments, confer with their instructors, and receive their final grades — all online. They can assemble virtual classrooms, joining other students from diverse geographical locales, forging bonds and friendships not possible in conventional classrooms, which are usually limited to students from a specific geographical area.', NULL, NULL, E'What makes teaching online unique is that it uses the internet, because when you teach online, you don''t have to be someplace to teach, and you can hold "office hours" on weekends or at night after dinner, while online learning offers more freedom for students as well, so they can search for courses, enroll and register, shop for their books and read articles online.', NULL, 5, 75),
  ('a6ff0c06-af09-5bd6-b5f5-aaa00f026824'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a6ff0c06-af09-5bd6-b5f5-aaa00f026824'::uuid, 1, NULL, TRUE, 0, NULL, E'Noble Gases', NULL, '073c6da5-bf29-588b-9a7d-1e41adeef70f'::uuid, NULL, E'Uniquely stable, they seemed to participate in no chemical reactions. But by understanding the stability of the noble gases, physicists discovered the key to chemical bonding itself. Dmitri Mendeleev added the noble gases to his periodic table in 1902, where he arranged the elements in rows and columns\naccording to their atomic weight.\nMendeleev was able to see repeating (or periodic) patterns in their properties. The noble gases appeared regularly in the periodic table, occurring in every eighth position, at least amongst the lighter elements.', NULL, NULL, NULL),
  ('a7054155-94f4-59e8-9b28-6061b1697189'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a7054155-94f4-59e8-9b28-6061b1697189'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b6cee699-003b-5023-ae91-bb0b4aed1392'::uuid, NULL, NULL, E'He refused to admit his departure from the government.', NULL, NULL),
  ('a7054a4f-df76-59f4-a3c1-6c5b751d65d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'a7054a4f-df76-59f4-a3c1-6c5b751d65d5'::uuid, 1, NULL, TRUE, 0, NULL, E'Critical Thinking', E'Critical thinking involves looking at something you may have seen many times and examining it from many different {{1}} and perspectives. It involves going beyond the {{2}} or beyond ''easy'' to seek new understanding and rare {{3}} . It involves looking at common issues with uncommon eyes, known problems with new skepticism, everyday conflicts with probing {{4}} and daily challenges with greater attention to detail.', NULL, NULL, NULL, E'1.angles, 2.obvious, 3.solutions, 4.curiosity', NULL, NULL),
  ('a709df1c-ae2e-514a-be82-12ac0a0180a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a709df1c-ae2e-514a-be82-12ac0a0180a8'::uuid, 1, NULL, TRUE, 0, NULL, E'Prescriptive and Descriptive', NULL, '4144a182-27d4-5354-b708-afe9c8fc943c'::uuid, NULL, E'Most of us learn to speak at such an early age that we don’t even remember it. We form our spoken repertoire through unconscious habits, not memorized rules. And because speech also uses mood and intonation for meaning, its structure is often more flexible, adapting to the needs of speakers and listeners. This could mean avoiding complex clauses that are hard to parse in real time, making changes to avoid awkward pronunciation, or removing sounds to make speech faster. The linguistic approach that tries to understand and map such differences without dictating correct ones is known as descriptivism. Rather than deciding how language should be used, it describes how people actually use it, and tracks the innovations they come up with in the process. But while the debate between prescriptivism and descriptivism continues, the two are not mutually exclusive. At its best, prescriptivism is useful for informing people about the most common established patterns at a given point in time. This is important, not only for formal contexts, but it also makes communication easier between non-native speakers from different backgrounds. Descriptivism, on the other hand, gives us insight into how our minds work and the instinctive ways in which we structure our view of the world. Ultimately, grammar is best thought of as a set of linguistic habits that are constantly being negotiated and reinvented by the entire group of language users.', NULL, NULL, NULL),
  ('a7123e6d-3c8d-5797-a32d-4df5c97ac1aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'a7123e6d-3c8d-5797-a32d-4df5c97ac1aa'::uuid, 1, NULL, TRUE, 0, NULL, E'Cataract Surgery', E'Scientists believe they may have found a way to prevent complications that can arise following cataract surgery, the world’s leading cause of blindness. Detailing why complications can occur after surgery, researchers from the University of East Anglia (UEA) explained that while cataract surgery works well to restore vision, a few natural lens cells always remain after the procedure. Over time, the eye’s wound-healing response leads these cells to spread across the underside of the artificial lens, which interferes with vision, causing what’s known as ‘posterior capsule opacification’ or secondary cataract. UEA’s School of Biological Sciences academic, Dr. Michael Wormstone, who led the study, said: “Secondary visual loss responds well to treatment with laser surgery. But as life expectancy increases, the problems of cataract and posterior capsule opacification will become even greater in terms of both patient well being and economic burden. It’s essential that we find better ways to manage the condition in future.” As a result, researchers are designing new artificial lenses that can be placed into a capsular bag that stays open, instead of shrink-wrapping closed, which currently occurs. It is believed that, through the new approach, fluid in the eye can flow around the artificial lens, therefore diluting and washing away the cell-signaling molecules that encourage cell re-growth.', NULL, NULL, E'Complications following cataract surgery are the world’s leading cause of blindness because it will cause secondary cataract which will become even greater in terms of patients’ wellbeing and economic burden as life expectancy increases, but researchers are designing new artificial lenses that are proved to be able to prevent complications following cataract surgery.', NULL, 5, 75),
  ('a71a8083-cae6-51ef-9644-b315ec9e1ee8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'a71a8083-cae6-51ef-9644-b315ec9e1ee8'::uuid, 1, NULL, TRUE, 0, NULL, E'Science Writing', E'At the World Conference of Science Journalists last week in London, outgoing Scientific American Editor in Chief John Rennie talked to writers about the future of what they do, remarks that also pertain to this podcast:\nThe question then is, how could science writing for the public possibly be better? I think there are a couple of different ideas. One of them is, maybe there should just be less of it. And because I would like to leave this room unlynched, let me amend that to say that at least there should be less of some of it. If our job is, ultimately as we see it, to try to inform the public better about science and technology, I for one think that we could all do with a lot fewer of the "what causes/cures cancer this week" story.\nI think that in fact is directly related, that kind of story is really related to a different problem, which is that we have a model of {{1}} what defines science news as that 95 percent of the time it is " {{2}} paper that appears in prestigious journal this week." That constitutes science news. Except that we''re all smart enough to know that that has absolutely nothing to do with how science works. That has to do with how publishing works. That''s what did they put into press this week.\nScience actually doesn''t change when one, new important paper comes out. We all know that. The reality of science is it takes time for science to play itself out. When interesting new results come in, they''re tested and they''re confirmed and people rework them. One paper can be the landmark that starts to affect some of that, but the reality is the actual change in the science follows that often by a considerable amount of time. Sometimes long after we''ve actually written the big headlines about the exciting, dramatic, {{3}} change of whatever has come about because of {{4}} .\nAnd I think that''s something that I don''t have a {{5}} prescription on all of this. But I really think this comes down to why it is that we have a {{6}} as editors to try to rethink what counts as science news.', NULL, NULL, NULL, E'1.following, 2.interesting, 3.revolutionary, 4.something, 5.particular, 6.responsibility', NULL, NULL),
  ('a71caf88-9ad8-5722-b6da-77e5c072b0ed'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a71caf88-9ad8-5722-b6da-77e5c072b0ed'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a773e72d-4b95-5d35-b062-9224f69fa429'::uuid, NULL, E'Data visualization techniques are used to gain better insights into customer experience.', NULL, NULL, NULL),
