  ('a7210ee7-8fae-5522-9529-2a063e3a615c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a7210ee7-8fae-5522-9529-2a063e3a615c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4f046ef0-cc60-51a7-8b0b-e5274e5fe18a'::uuid, NULL, NULL, E'Please turn off the light to save energy.', NULL, NULL),
  ('a72137b7-14e6-518d-9cf8-2c98500d14aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a72137b7-14e6-518d-9cf8-2c98500d14aa'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '501a5b7e-18c7-54b3-8cb1-0b8875fdcf71'::uuid, NULL, E'Safety glasses should be worn while doing experiments in the lab.', NULL, NULL, NULL),
  ('a727a01b-0b6b-50c8-a63f-5863008a8ec8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'HIGHLIGHT_CORRECT_SUMMARY', E'HIGHLIGHT_CORRECT_SUMMARY', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a727a01b-0b6b-50c8-a63f-5863008a8ec8'::uuid, 1, NULL, TRUE, 0, NULL, E'Washington', E'We all know that the capital of the united states is washington, DC. However, when america first became a country, washington didn''t even exist. Back then, philadelphia was the logical choice as the new country''s capital. Why philadelphia? Why not boston, new york, or even a charleston for several reasons? First, philadelphia had a roughly central location in the u s at that time, also, it had been a focal point of the american revolution. The continental congress had met there before the war, and several major events took place there. So, uh, why is washington the capital and not philadelphia, mostly because of a riot in philadelphia in seventeen eighty three, congress was meeting there when some soldiers disrupted them. The soldiers demanded payment for their service. During the war. The congress had no money. It asked the government of pennsylvania to protect it, but the government refused. Congress promptly left philadelphia so that um, ruled out. Philadelphia congress realized it couldn''t rely on the states to defend it. Thus the members of congress decided to create an entirely new area called the district of columbia. Several states competed for the right to host the district, but ultimately, congress decided on a stretch of land between virginia and maryland. Like philadelphia, it was near the geographical center of the country. The necessary land was given to the federal government. Construction on the new capital then began, and that''s how washington dc became our capital. Let''s look at its design now.\n\nClick on the paragraph that best relates to the recording.', 'd4405b6d-3e14-5857-a5d7-6f4ce46047a0'::uuid, NULL, NULL, E'How Washington D.C. became the capital of United States is an intriguing story. Since in 1783 some soldiers interrupted a meeting of Congress in Philadelphia,it decided to create a completely new and independent area as the capital city.', NULL, NULL),
  ('a729ea9d-b842-50b7-b00f-43033e39a205'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a729ea9d-b842-50b7-b00f-43033e39a205'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b2e8db96-c8f7-5a8c-95aa-49b10ec4f13f'::uuid, NULL, NULL, E'Modern art now does better than stocks as an investment.', NULL, NULL),
