  ('a7c24070-ce84-5360-9872-f961fefa624a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a7c24070-ce84-5360-9872-f961fefa624a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a22b2a4c-556e-5e28-b61f-0b45aa4bc0a4'::uuid, NULL, E'Major sports on campus include rugby, soccer and tennis.', NULL, NULL, NULL),
  ('a7c49c2e-f630-55f0-a0e1-2ac8f2bc179a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a7c49c2e-f630-55f0-a0e1-2ac8f2bc179a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'fb1af1ff-2a4b-585e-a96f-1baf723c9e70'::uuid, NULL, NULL, E'An internal organ''s role includes maintaining the body''s core temperature.', NULL, NULL),
  ('a7d2a5ce-f1b9-593b-a9bc-c8beecce90ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'a7d2a5ce-f1b9-593b-a9bc-c8beecce90ee'::uuid, 1, NULL, TRUE, 0, NULL, E'Brain', E'Researchers in Europe and the US wanted to find out exactly what happens to our brain when we find ourselves stunned with fright in the hope of better understanding how fear {{1}} with human anxiety disorders. For the first time, they traced and linked three parts of the brain responsible for freezing behaviors: the amygdala, ventrolateral periaqueductal grey region and magnocellular nucleus. Mice are excellent lab animals where it comes to anxiety and fear experiments. When a mouse is scared, its defensive behaviors range from freezing, attacking, risk {{2}} or fleeing the scene. How a mouse acts depends on variables such as access to escape routes or the level of threat faced. So Andreas Luthi at the Friedrich Miescher Institute for Biomedical Research in Switzerland and colleagues from Europe and the US observed brain activity in mice placed in frightening situations to {{3}} the brain circuits {{4}} for freezing behaviors. In particular, the researchers wanted to learn more about a part of the brain called the ventrolateral periaqueductal grey region, which was believed to {{5}} some part in a mouse'' s instinct to freeze or flee.', NULL, NULL, NULL, E'1.interplays, 2.assessment, 3.trace, 4.responsible, 5.play', NULL, NULL),
  ('a7d45cd5-13cc-5568-bc89-8fdf04bcb40b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a7d45cd5-13cc-5568-bc89-8fdf04bcb40b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you use to dry your body after a shower?', 'e8e45228-4ad6-5e99-8e9b-4fd034a67245'::uuid, NULL, NULL, E'Towel', NULL, NULL),
  ('a7da3bb3-902e-5a07-b655-6acfd00458b4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'a7da3bb3-902e-5a07-b655-6acfd00458b4'::uuid, 1, NULL, TRUE, 0, NULL, E'ASD', E'ASD is a lifelong condition with a median age of {{1}} greater than 4 years although most current intervention strategies {{2}} children less than 6 years to promote early behavioral change. Individuals with ASD and their families {{3}} significant challenges during developmental transitions. School-age children in particular, often remain unengaged in social {{4}} , reducing opportunities for socio-communicative development.', NULL, NULL, NULL, E'1.diagnosis, 2.target, 3.face, 4.settings', NULL, NULL),
  ('a7dcfe52-a34f-5ed3-8122-611dfd4c14a2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'a7dcfe52-a34f-5ed3-8122-611dfd4c14a2'::uuid, 1, NULL, TRUE, 0, NULL, E'Population Growth', E'Global population growth is shaped by births and deaths, though migration can also impact regional populations. Another factor is also at play: population momentum. This concept explains why the age structure of a population can cause it to grow even as fertility declines below replacement level. In essence, even if the fertility rate is declining, there is still a large absolute number of people of reproductive age in the population, resulting in more births than deaths. For example, in Nigeria the U.N. projects that if the fertility rate dropped to replacement level today, the population would continue to grow for the rest of the century, with 124,000 more people than today in 2100 (an increase of 57 percent). In contrast, fertility rates in Japan have been below replacement level since 1959, leading to a much older population, but population size only started to decline in 2005. If all fertility rates were at replacement level, then the world population would still hit 9 billion in 2039: only two years later than current projections. Short of an unprecedented disaster, the population will continue to grow. Even COVID-19 mortality had a very small effect on the size of the global population. The World Health Organization estimates that 14.9 million excess deaths were associated with COVID in 2020 and 2021. This is a very large absolute number, but it is dwarfed by the 269 million births that happened in the same period.', NULL, NULL, NULL, NULL, 5, 75),
  ('a7e0d464-2328-56fd-a8ce-190f658825a0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a7e0d464-2328-56fd-a8ce-190f658825a0'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Where are art works usually exhibited?', 'a735d1c8-6784-52a6-a101-e79533f4a0eb'::uuid, NULL, NULL, E'Art gallery', NULL, NULL),
  ('a7fbb7d9-8fcc-5932-8ef7-7488c429b114'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a7fbb7d9-8fcc-5932-8ef7-7488c429b114'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the large road vehicle used for long-distance passenger travel?', 'fac20cd2-a710-5131-8427-4c80e3a18221'::uuid, NULL, NULL, E'Coach', NULL, NULL),
  ('a8076b3b-b831-51a4-a8aa-c1c6a7c191bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a8076b3b-b831-51a4-a8aa-c1c6a7c191bd'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do we call the car that uses two types of fuels?', '1a868565-d4b9-56ee-8d20-f8d621090585'::uuid, NULL, NULL, E'Hybrid', NULL, NULL),
  ('a8103ed5-ae66-5962-93d3-28ce863901c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a8103ed5-ae66-5962-93d3-28ce863901c6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3f5a591b-df3e-5387-960b-b7333501c0fe'::uuid, NULL, NULL, E'The team discussed their tactics during the break.', NULL, NULL),
  ('a8129f28-0fa8-5590-8268-7e7ebc456bb9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a8129f28-0fa8-5590-8268-7e7ebc456bb9'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How would people travel to work each day in big cities like Hong Kong, Tokyo and New York?', '44bbdd20-9dde-5bfd-8af7-00d86df6524b'::uuid, NULL, NULL, E'By public transportation /by cars / by train / by bus / by tram', NULL, NULL),
  ('a813139d-1e0e-55a8-8cf7-b95f4cca6913'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', 'a813139d-1e0e-55a8-8cf7-b95f4cca6913'::uuid, 1, NULL, TRUE, 0, NULL, E'Hydropower', E'Hydropower is the dominant source of energy in the Amazon region, the world''s largest river basin and a hotspot for future hydropower development. However, a new Global Environmental Change study warns that in the coming decades, climate change-driven reductions in precipitation and river discharge will diminish the Amazon''s hydropower capacity.\nThe study''s authors examined 351 proposed hydropower projects in the Amazon basin. Their findings suggest that hydrologic shifts by midcentury will reduce hydropower generation at many locations. As river discharge becomes increasingly variable and hydropower output declines, alternative energy sources like solar and wind are expected to become ever more important.\nHydropower needs to be designed to operate in concert with alternative energy sources like solar and wind so periods of low river flows do not disrupt electrical grids that supply vital power to cities and industries. New hydropower facilities should be carefully sited in locations of more reliable flows, and designed to operate over a broader range of flows than historical experience would indicate.\nAlmeida concludes, "Energy planners need to focus on climate resilience. Brazil, for example, has over 200 million people and hydropower is the dominant energy source. This year, Brazilian hydropower reservoirs are at record lows due to extreme drought; as a result, Brazil might need to start rationing power. Ensuring energy security into the future will require diversifying energy sources to include solar and wind, and adapting hydropower plans to suit future -- not historic -- river flows."\n\nWhich of the following statements are correct?', NULL, NULL, NULL, E'Hydrologic changes will reduce hydropower generation in many places by the middle of the century.\nHydroelectric reservoirs in Brazil are at record lows due to extreme drought.\nAlternative energy sources such as solar and wind will become increasingly important.', NULL, NULL),
  ('a814bf51-e62f-5efa-8ab9-06d72cc2e992'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'a814bf51-e62f-5efa-8ab9-06d72cc2e992'::uuid, 1, NULL, TRUE, 0, NULL, E'Domestication of Animals', NULL, NULL, NULL, NULL, E'1, 4, 3, 2', NULL, NULL),
  ('a8170efc-926c-5b29-8ba2-340eaa07cdf1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'a8170efc-926c-5b29-8ba2-340eaa07cdf1'::uuid, 1, NULL, TRUE, 0, NULL, E'German Luftwaffe', E'The German Luftwaffe dropped thousands of bombs on London from 1939 to 1945, killing almost 30,000 people. More than 70,000 buildings were completely demolished, and another 1.7 million were damaged. The extent of the damage to each and every one of these buildings was logged and mapped in near real-time by surveyors, architects, engineers, and construction workers. The result is an incredible collection of maps, color-coded by hand, that reveal the amount of the destruction in painstaking detail. Today, the maps remain an invaluable resource for academics, family historians, and even builders trying to avoid touching off unexploded bombs. Now, these bomb census maps are available in a beautiful oversized book released earlier this year to commemorate the 75th anniversary of the end of the Blitz, a nine-month period during which London and other British cities were relentlessly attacked by the German air force. Visually, the maps are quite striking. The apparent randomness of the colors stands in contrast to the more orderly pattern of streets and buildings. The damage from World War II transformed London into the architecturally diverse city it is today. The maps showing how widespread the destruction was, really bring home the scale of the devastation.\n\nWhich of the following most accurately summarizes the opinion of the author in the text?', NULL, NULL, NULL, E'The author believes that the maps are works of art that give information about London’s destruction in World War II.', NULL, NULL),
  ('a817faed-2736-52f5-a875-eabb5e2a076a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a817faed-2736-52f5-a875-eabb5e2a076a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1d073f40-6d97-5fd4-a117-b2668fd64046'::uuid, NULL, NULL, E'This book invites readers to discuss future directions in social development.', NULL, NULL),
  ('a81be12d-b69c-528a-b235-842d70d8a82b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a81be12d-b69c-528a-b235-842d70d8a82b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f8140cc7-a55d-5352-9bc6-3bd2614d3942'::uuid, NULL, E'The fire left the area almost completely devoid of vegetation.', NULL, NULL, NULL),
  ('a81ee445-2035-57e7-a40c-92edf7a464b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a81ee445-2035-57e7-a40c-92edf7a464b2'::uuid, 1, NULL, TRUE, 0, NULL, E'CD Quality Sound', E'Reiss took a stab at settling the argument with a meta-analysis — a study of studies — on whether people can really perceive better-than-CD quality sound. He analyzed data from 18 studies, including more than 400 participants and nearly 13,000 listening tests. Overall, listeners picked out the better-than-CD-quality track 52.3 percent of the time. Statistically significant, if not all that impressive.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a821c425-0dcd-56c2-b780-ec065ff89e46'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a821c425-0dcd-56c2-b780-ec065ff89e46'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which is the biggest one, the elephant, the tiger, or the cheetah?', '4f184d74-99c7-5f7a-92ea-c76f7b45cb27'::uuid, NULL, NULL, E'Elephant', NULL, NULL),
  ('a8288c9e-f37b-5579-98aa-7daf3008b295'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a8288c9e-f37b-5579-98aa-7daf3008b295'::uuid, 1, NULL, TRUE, 0, NULL, E'Deforestation', E'Deforestation of the Amazon rainforest contributes significantly to climate change, affecting the local ecosystem and the entire planet. Trees absorb carbon dioxide from the atmosphere, regulating the Earth''s climate. When forests are destroyed, this carbon is released into the atmosphere, contributing to global warming and climate change.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a82d2a5e-1f5b-5e7a-b919-ab598d62a6c7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'a82d2a5e-1f5b-5e7a-b919-ab598d62a6c7'::uuid, 1, NULL, TRUE, 0, NULL, E'Stress-busting Break', E'You have been sitting at your desk for longer than you care to remember. Your head is fuzzy, your body is aching. You know it’s not good for you, but you also need to get that work done. Yet skipping breaks is the best way not only to {{1}} energy reserves and increase stress, but also to depress productivity. When the Draugiem Group, an IT company based in Latvia, tracked the behaviour of its employees, the top 10 per cent most productive people worked the same hours as everyone else, {{2}} took more breaks – on average a 17-minute break after 52 minutes of work. Organizational psychologist John Trougakos at the University of Toronto, Canada, says we should ideally stand up and move around for 30 to 60 seconds every 20 to 30 minutes, and focus on something more than 6 meters away to {{3}} our eyes. We should take an extended break of 10 or 15 minutes every hour or so, because we have only a limited {{4}} to concentrate for longer.', NULL, NULL, NULL, E'1.deplete, 2.but, 3.rest, 4.capacity', NULL, NULL),
  ('a82ff45c-779b-5624-82b1-88ec55476235'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a82ff45c-779b-5624-82b1-88ec55476235'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd4d14cf4-4941-5b84-a111-022dfd1d47d3'::uuid, NULL, NULL, E'This money is intended for the development of the tourism industry.', NULL, NULL),
  ('a8367cfb-68f3-5ea6-91fe-d4f55f4457f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'a8367cfb-68f3-5ea6-91fe-d4f55f4457f9'::uuid, 1, NULL, TRUE, 0, NULL, E'The Origins of Music', E'Music is an important part of our lives. We connect and interact with it daily and use it as a way of projecting our self-identities to the people around us. The music we enjoy - whether it''s country or classical, rock n'' roll or rap - {{1}} who we are.\nBut where did music, at its core, first come from? It''s a puzzling question that may not have a definitive answer. One {{2}} researcher, however, has proposed that the key to understanding the origin of music is nestled snugly in the loving bond between mother and child.\nIn a lecture at the University of Melbourne, Richard Parncutt, an Australian-born professor of systematic musicology, endorsed the idea that music originally spawned from ''motherese'' - the playful voices mothers {{3}} when speaking to {{4}} and toddlers.\nAs the theory goes, increased human brain sizes caused by evolutionary changes occurring between one and 2,000,000 years ago resulted in earlier births, more fragile infants and a {{5}} need for stronger relationships between mothers and their newborn babies.\nAccording to Parncutt, who is based at the University of Graz in Austria, ''motherese'' arose as a way to strengthen this maternal bond and to help {{6}} an infant''s survival.', NULL, NULL, NULL, E'1.reflects, 2.leading, 3.adopt, 4.infants, 5.critical, 6.ensure', NULL, NULL),
  ('a83894ab-f3c2-5bbf-b5d9-e3965b3050d9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a83894ab-f3c2-5bbf-b5d9-e3965b3050d9'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call people who engrave or polish on stones and gems?', '66fdcb6d-58d5-5865-8162-21209239214d'::uuid, NULL, NULL, E'Stonemason / stonemasons / lapidarist / lapidary', NULL, NULL),
  ('a838d127-f993-5139-bf17-24dd7d958736'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a838d127-f993-5139-bf17-24dd7d958736'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd8684797-610f-57e6-8bf2-8be5a2962914'::uuid, NULL, E'Their early success was succeeded by a period of miserable failure.', NULL, NULL, NULL),
  ('a83c9f8b-2b6f-5734-bc62-cd85fc933c48'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'a83c9f8b-2b6f-5734-bc62-cd85fc933c48'::uuid, 1, NULL, TRUE, 0, NULL, E'Siblings', E'No two siblings are the same, not even {{1}} twins. Parents often {{2}} about why their children are so different from one another. They''ll say, I {{3}} them up all the same. They forget that what {{4}} our behaviour isn''t what happens to us but how we {{5}} what happens to us, and no two people ever see anything in exactly the same way.', NULL, NULL, NULL, E'1.identical, 2.puzzle, 3.brought, 4.determines, 5.interpret', NULL, NULL),
  ('a83ea195-8423-5a9e-b33e-c0cbcac0db59'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'a83ea195-8423-5a9e-b33e-c0cbcac0db59'::uuid, 1, NULL, TRUE, 0, NULL, E'Blood Flow', E'All approaches aim to increase {{1}} flow to areas of tension and to release painful knots of muscle known as '' trigger points.'' ''Trigger points are tense areas of muscle that are almost constantly contracting,'' says Kippen. '' The contraction causes pain, which in turn causes contraction, so you have a vicious circle. This is what deep tissue massage aims to break.'' The way to do this, as I found out under Ogedengbe'' s elbow, is to apply pressure to the point, stopping the blood flow, and then to release, which causes the brain to flood the affected {{2}} {{3}} blood, encouraging the muscle to relax. At the same time, says Kippen, you can fool the tensed muscle into relaxing by applying pressure to a complementary one nearby. '' If you cause any muscle to contract, its opposite will expand. So you try to trick the body into relaxing the muscle that is in spasm.''', NULL, NULL, NULL, E'1.blood, 2.area, 3.with', NULL, NULL),
  ('a8411e7c-2411-55e9-b577-89e5b6947d95'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a8411e7c-2411-55e9-b577-89e5b6947d95'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '07f10430-9d3f-53f1-857f-e953db81a2f8'::uuid, NULL, NULL, E'No link was established between the medication used and healing rates.', NULL, NULL),
