  ('a8493700-33de-5221-b8ab-28d20c02ea6b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'a8493700-33de-5221-b8ab-28d20c02ea6b'::uuid, 1, NULL, TRUE, 0, NULL, E'Skill of Presentation', E'Being able to give a good and clear presentation to a public audience is a skill that you and your future employer will value {{1}} . Prospective employers invariably ask for your experience in using these key skills during interviews. You need to be able to articulate what makes a good and poor presentation and offer evidence for your knowledge. So, when you are asked to give a talk or produce a poster as part of your studies, recognize the importance of developing the skills of delivery {{2}} conveying the content.\nPosters and oral presentations are forms of presentation that enable you to develop your confidence in different ways. Posters check your ability to present information succinctly, and present it in an attractive and message-focused way, {{3}} oral presentations allow for more information and a more in-depth delivery. In both modes you will probably find yourself taking questions and {{4}} your ideas.', NULL, NULL, NULL, E'1.greatly, 2.as well as, 3.while, 4.explaining', NULL, NULL),
  ('a84b7c10-1e34-51c2-90a4-6631c9782d30'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a84b7c10-1e34-51c2-90a4-6631c9782d30'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '13536cc1-9822-5b86-98dd-c9c71ebe12b5'::uuid, NULL, NULL, E'The composition showcases a reserved style in its musical theme.', NULL, NULL),
