  ('a8887792-d2d8-5e99-9bf9-0aa852a8fe5d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'a8887792-d2d8-5e99-9bf9-0aa852a8fe5d'::uuid, 1, NULL, TRUE, 0, NULL, E'Very Old Paris', E'Paris is very old—there has been a settlement there for at least 6000 years and its shape has been determined in part by the River Seine, and in part by the edicts of France’s rulers. But the great boulevards we admire today are relatively new, and were constructed to prevent any more barricades {{4}} by the rebellious population; that work was carried out in the middle 19th century. The earlier Paris had been {{2}} a maze of narrow streets and alleyways. But you can imagine that the work was not only highly expensive, but caused great distress among the half a million or so residents whose houses were {{3}} razed, and whose neighbourhoods disappeared. What is done cannot usually be undone, especially when buildings are torn {{1}} .', NULL, NULL, NULL, E'1.being created, 2.in part, 3.simply, 4.down', NULL, NULL),
  ('a88c1e5e-adb8-5a1e-8115-4ed2f82e4cd3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a88c1e5e-adb8-5a1e-8115-4ed2f82e4cd3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8acb9328-3af1-5872-b6ca-640ed8b31543'::uuid, NULL, E'Medicine should not be kept where it is accessible to children.', NULL, NULL, NULL),
  ('a88fa37f-f668-59e8-8bd0-11970a478d05'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a88fa37f-f668-59e8-8bd0-11970a478d05'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ec8d407e-b811-5db3-b084-c82460797c86'::uuid, NULL, E'He had managed to cover a lot of topics in a short talk.', NULL, NULL, NULL),
  ('a8961ecb-d28f-5d9e-a0ef-b265c92c5b6c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a8961ecb-d28f-5d9e-a0ef-b265c92c5b6c'::uuid, 1, NULL, TRUE, 0, NULL, E'Personality Tests', E'Today, personality testing is a multi-billion dollar industry used by individuals, schools, and companies. But none of these tests, including the MBTI, the Big Five, the DiSC assessment, the Process Communication Model, and the Enneagram, actually reveal truths about personality. In fact, it’s up for debate whether personality is a stable, measurable feature of an individual at all. Part of the problem is the way the tests are constructed. Each is based on a different set of metrics to define personality: the Myers-Briggs, for instance, focuses on features like introversion and extroversion to classify people into personality “types,” while the Big Five scores participants on five different traits. Most are self-reported, meaning the results are based on questions participants answer about...\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', 'e2dc1cf5-ce0b-59d9-a931-b1b0d9d1ee1b'::uuid, NULL, NULL, E'themselves', NULL, NULL),
  ('a8a2e656-ca41-54b6-90ab-368183c9609a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'a8a2e656-ca41-54b6-90ab-368183c9609a'::uuid, 1, NULL, TRUE, 0, NULL, E'Trees'' Role', NULL, NULL, NULL, NULL, E'3, 1, 4, 2', NULL, NULL),
  ('a8a5cda0-d116-578c-8337-e767e94a8099'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a8a5cda0-d116-578c-8337-e767e94a8099'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Where do we conduct experiments?', 'b8cfa91e-e1cf-509c-853d-7d9ec3847e14'::uuid, NULL, NULL, E'Laboratory', NULL, NULL),
  ('a8ab9536-d43f-58c0-b571-9f71e7e7c6ef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a8ab9536-d43f-58c0-b571-9f71e7e7c6ef'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What does the prefix bi- such as in words like bilateral and bilingual mean?', '02e2cb76-f961-59f6-be48-b593b5aec4c1'::uuid, NULL, NULL, E'Two / twice / double', NULL, NULL),
  ('a8b2093a-6446-5d3d-98fc-6d4e5b5be203'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a8b2093a-6446-5d3d-98fc-6d4e5b5be203'::uuid, 1, NULL, TRUE, 0, NULL, E'Super-symmetry', NULL, 'da243eb9-5733-541a-ba7a-4f36e44a1927'::uuid, NULL, E'Super-symmetry is a mathematical idea that people have developed an effort to understand the sharpest organising principle for the fundamental constituents of matter. You see, we have learned that particles that seem to be different, can actually secretly be united by certain symmetry principles. So we use the fact that there are symmetric objects in the world like a sphere or basketball. You turn a sphere, and even though you''ve transformed it, it looks the same fundamentally. We found that certain particles when you transform one particle into another, even though looks like the identity of the particle has changed, overall the equations describing it they don''t change at all at an underlying level of symmetry, but we''ve not been able to do is find a symmetry that would relate certain kinds of particles, namely matter particles and force particles. Matter particles are particles like electrons, muons and quarks, force particles are like photons and gluons and WZ bosons. Super-symmetry is a symmetry that actually relates to these two kinds, these two classes of particles. And people have proven that super-symmetry is the last possible symmetry of the fundamental particles that are mathematics, reality has not yet been shown to make use of it. So people are now trying to see whether that symmetry might actually be working in the world can be found evidence for it in our understanding of fundamental particles.', NULL, NULL, NULL),
  ('a8b36989-f7a2-5041-bca1-953afa06fc0a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a8b36989-f7a2-5041-bca1-953afa06fc0a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2f16930f-5476-586a-b1af-3a665432c987'::uuid, NULL, NULL, E'The bus to London will leave ten minutes later than planned.', NULL, NULL),
  ('a8c018ff-fce5-5459-a3c5-53bcc5e080d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'a8c018ff-fce5-5459-a3c5-53bcc5e080d5'::uuid, 1, NULL, TRUE, 0, NULL, E'French Revolution', NULL, NULL, NULL, NULL, E'4, 2, 3, 1', NULL, NULL),
  ('a8c5734c-751c-55e4-b123-2400056dc134'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'a8c5734c-751c-55e4-b123-2400056dc134'::uuid, 1, NULL, TRUE, 0, NULL, E'Deforestation', E'Deforestation can disrupt the lives of local communities, sometimes with {{1}} consequences. Forests provide a vast array of {{2}} to all of us, including food, wood, medicine, fresh water, and the air we breathe. Without the trees, species can disappear, the natural water balance can become disrupted and the ecosystem that supports the human population can fall {{3}} .', NULL, NULL, NULL, E'1.devastating, 2.resources, 3.apart', NULL, NULL),
  ('a8c753ac-5e56-5056-8e19-f99e8cf73211'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a8c753ac-5e56-5056-8e19-f99e8cf73211'::uuid, 1, NULL, TRUE, 0, NULL, E'Tea Ceremony', E'The Japanese tea ceremony is a ritual tour influenced by Buddhism in which green tea is prepared and served to a small group of guests in a peaceful setting. The ceremony can take as long as four hours and there are many traditional gestures that both the server and the guest must perform.', NULL, NULL, NULL, NULL, NULL, NULL),
