  ('a8db0fc0-fdae-5923-aea1-0134a8a792a4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a8db0fc0-fdae-5923-aea1-0134a8a792a4'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How many wheels does a bicycle have?', '0287be31-428a-5532-b076-4402e55986cf'::uuid, NULL, NULL, E'Two', NULL, NULL),
  ('a8dcbac8-18fe-5ca1-a4a0-f327c7e80b80'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a8dcbac8-18fe-5ca1-a4a0-f327c7e80b80'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b4a92cb1-c9de-54cd-b8f0-c5f0ffd42eb0'::uuid, NULL, E'Children are not allowed to be in the laboratory at any time.', NULL, NULL, NULL),
  ('a8dd7ad3-55bc-591a-bc97-c79c3490932e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'a8dd7ad3-55bc-591a-bc97-c79c3490932e'::uuid, 1, NULL, TRUE, 0, NULL, E'Children''s Verbal Skills', NULL, NULL, NULL, NULL, E'3, 1, 2, 4, 5', NULL, NULL),
  ('a8e3dff4-488f-5ab1-b5de-5ac8820241f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'a8e3dff4-488f-5ab1-b5de-5ac8820241f0'::uuid, 1, NULL, TRUE, 0, NULL, E'Sci-fi Movie', E'It''s like the publishing version of one of those scenes from a sci-fi movie where an alien invasion impels traditional adversaries to join together to face their larger, common threat. Today 56 newspapers, in Pakistan and India, in Israel and Lebanon, in China, in Greece and Turkey, in Africa and in North, South and Central America are publishing an unprecedented joint editorial calling for meaningful action to face the threat posed by climate change. The editorial, {{2}} in 45 {{3}} in 20 different languages, appears on this first day of the Copenhagen climate conference. The British paper the Guardian led the effort, which involved weeks of negotiations to reach a final version.\nThe editorial notes that "the science is complex but the facts are clear. The world needs to take steps to limit temperature rises to 2 degrees C. A bigger rise of 3 to 4 degrees C would parch continents, turning farmland into desert. Half of all species could become extinct, untold millions of people would be displaced, whole nations drowned by the sea. The controversy over emails by British researchers that suggest they tried to suppress inconvenient data has muddied the waters but failed to dent the mass of evidence on which these predictions are based."\nThe editorial {{5}} that "the shift to a low-carbon society holds out the prospect of more opportunity than sacrifice. Already some countries have recognized that embracing the transformation can bring growth, jobs and better quality lives. The flow of capital tells its own story: last year for the first time more was invested in renewable forms of energy than producing {{6}} from fossil fuels."\nSo while gleeful anarchists like Oklahoma Senator James Inhofe go to Copenhagen to try to sabotage the proceedings, the worldwide array of newspapers attempts to remind the conference participants and the people they represent to keep their eye on the ball—the ball in this case being an oblate spheroid with almost seven billion human inhabitants and a fever that {{7}} needs to be treated. As the Guardian''s editor in chief, Alan Rusbridger, said, "Newspapers have never done anything like this before but they have never had to cover a story like this before."', NULL, NULL, NULL, E'1.published, 2.countries, 3.recognized, 4.electricity, 5.desperately', NULL, NULL),
  ('a8e4a23c-7354-5a14-8df8-f1942b9c8508'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'a8e4a23c-7354-5a14-8df8-f1942b9c8508'::uuid, 1, NULL, TRUE, 0, NULL, E'Powerful Tool', E'The Internet has become humanity''s most powerful tool for information {{1}} and communication. However, this {{2}} has its drawbacks. Traditional forms of media and interpersonal communication have been significantly {{3}} , with some languages and dialects becoming less prevalent in the digital space. This digital revolution, spearheaded by the rise of social media and online platforms, has resulted in a constant {{4}} of information.', NULL, NULL, NULL, E'1.exchange, 2.dominance, 3.altered, 4.influx', NULL, NULL),
  ('a8e728c6-16a3-5b90-8c2d-a0b76866c7bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a8e728c6-16a3-5b90-8c2d-a0b76866c7bd'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2a2e5978-bd8e-5926-bc0d-156f41d7a433'::uuid, NULL, NULL, E'Science degrees are now offering different levels of specialization.', NULL, NULL),
  ('a8e80311-3c74-5d5f-930d-7eb96c90e0bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a8e80311-3c74-5d5f-930d-7eb96c90e0bd'::uuid, 1, NULL, TRUE, 0, NULL, E'Leadership and Management', NULL, 'a374750f-5f36-52f8-8c54-6a6c12ec92b1'::uuid, NULL, E'In organizations, there are profound differences between management and leadership. Although both of them are important for achieving goals, they focus on different ways of thinking and working. Leaders usually do not accept the current situation easily. They may dislike the status quo and try to make some challenges to existing systems. They often question traditional methods, take risks, and attempt to change directions in order to create new opportunities and improvements. On the other hand, managers usually focus on maintaining stability and efficiency. They often stay in the status quo, follow established rules, and ensure that everything goes with the procedures. Their main responsibility is to organize resources, control processes, and make sure that daily operations run smoothly. Therefore, leadership and management have different purposes. Management emphasizes order, consistency, and following existing systems, while leadership focuses on innovation, change, and challenging old ideas. In this sense, leadership disrupts management because leaders often need to break traditional patterns in order to create progress and transformation.', NULL, NULL, NULL),
  ('a8ef7cc2-7b74-5f7d-850c-8e7825506920'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a8ef7cc2-7b74-5f7d-850c-8e7825506920'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do birds use to fly with?', 'b5c8fe99-75e5-5a6b-86b1-7b0213c983b6'::uuid, NULL, NULL, E'Wings', NULL, NULL),
  ('a8f2dde5-c9e1-5724-abbe-cbaed485a742'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a8f2dde5-c9e1-5724-abbe-cbaed485a742'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0af23c72-724e-5093-9239-04aea86451a7'::uuid, NULL, E'Our company''s software saw significant changes over the past year.', NULL, NULL, NULL),
  ('a8f438d9-1c12-5d3d-aed7-3f6b534e7f45'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'a8f438d9-1c12-5d3d-aed7-3f6b534e7f45'::uuid, 1, NULL, TRUE, 0, NULL, E'Mass Extinction', E'Some 66 million years ago, a meteor crashed into the coast of Mexico’s Yucatan Peninsula, marking the end of the age of dinosaurs. It was a mass extinction event and it was {{1}} . A mass extinction is a short period of geological time in which a high percentage of biodiversity, or distinct species dies out. Unlike previous extinction events that were caused by {{2}} phenomena, the sixth mass extinction is driven by human activity. The biggest driver of destruction is how we use the land and the sea. This includes the {{3}} of land cover such as forests and other natural habitats for agricultural and urban use. And agricultural expansion is the main driver behind deforestation, with animal farming being a particular driver of forest degradation and forest biodiversity loss. The natural world is also affected by the climate crisis. Species and ecosystems around the world, especially the most {{4}} ones, are affected by the rise of greenhouse gas emissions. Mankind’s emissions of greenhouse gases are warming up the atmosphere and {{5}} , everything on Earth.', NULL, NULL, NULL, E'1.devastating, 2.natural, 3.conversion, 4.vulnerable, 5.subsequently', NULL, NULL),
  ('a8f60738-fe84-560f-b951-b9a558545f4d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a8f60738-fe84-560f-b951-b9a558545f4d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '17bc2709-4796-58b5-9c31-c70e9dd0caef'::uuid, NULL, E'I hope I can take early retirement before I''m sixty.', NULL, NULL, NULL),
  ('a9001a6c-93ce-58e7-9611-af00f0bf9526'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a9001a6c-93ce-58e7-9611-af00f0bf9526'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ed401803-5b8f-58a8-8e89-873fa8479617'::uuid, NULL, NULL, E'Various groups are dedicated to reducing suffering in animal populations.', NULL, NULL),
  ('a90960b3-a4c4-5d34-9299-6adfdc5c7f50'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a90960b3-a4c4-5d34-9299-6adfdc5c7f50'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '66ec7f3a-5f7c-5799-870c-c42651d993ac'::uuid, NULL, NULL, E'A good abstract quickly tells you what the study is about.', NULL, NULL),
  ('a90cc818-7f45-57d2-b132-e7d83eac9acd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'a90cc818-7f45-57d2-b132-e7d83eac9acd'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-R', E'Although the hormone adrenaline is known to regulate memory storage, it does not pass from the blood into brain cells. We are faced with an apparent paradox: how can a hormone that does not act directly on the brain have such a large effect on brain function? Recently, we tested the possibility that one of the hormone''s actions outside the brain might be responsible. Since one consequence of adrenaline release in an animal is an increase in blood glucose levels, we examined the effects of glucose on memory in rats. We found that glucose injected immediately after training enhances memory tested the next day. Additional evidence was provided by negative findings: drugs called adrenergic antagonists, which block peripheral adrenaline receptors, disrupted adrenaline''s ability to regulate memory but did not affect memory enhancements produced by glucose that was not stimulated by adrenaline. These results are as they should be if adrenaline affects memory modulation by increasing blood glucose levels.\n\nThe primary purpose of the passage is to', NULL, NULL, NULL, E'present evidence that may help to resolve an apparent contradiction', NULL, NULL),
  ('a9101ae4-ef97-5257-b067-b4ec3fe31df4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a9101ae4-ef97-5257-b067-b4ec3fe31df4'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4e62ff3b-3ae1-591d-9ae1-4ddb464c6975'::uuid, NULL, E'Information is being given to readers in a format that looks familiar.', NULL, NULL, NULL),
  ('a9110f37-ad61-5a8f-ab8c-b35b3cc6c1ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a9110f37-ad61-5a8f-ab8c-b35b3cc6c1ca'::uuid, 1, NULL, TRUE, 0, NULL, E'Human Behavior', NULL, '79de65bc-b3f8-5fe8-ba07-57ad336fe76f'::uuid, NULL, E'Determinant, human behavior is affected by internal and external factors. At the end of lecture, the speaker mentioned that psychologists are interested in explaining human behavior. Determinant is influenced by two factors, the personal factors which are internal and the environmental factors which are external. The personal factors include people''s belief on certain things and their individual thinking about it, while the environmental factors include temperature, air pressure and the others'' thinking about them. In conclusion, one''s determinants are affected by both himself and the environment.', NULL, NULL, NULL),
  ('a9156dac-20d4-5e72-8ec2-7f5e613623ec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a9156dac-20d4-5e72-8ec2-7f5e613623ec'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'eb956d63-6f2d-5e8d-9ae6-c2f981153eb2'::uuid, NULL, NULL, E'College may have an impact on the mental growth of students.', NULL, NULL),
  ('a9231e30-2ba6-5c8c-8885-39b94ef935c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a9231e30-2ba6-5c8c-8885-39b94ef935c0'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4d527a36-50a0-58be-9ad3-ad2a43cdc0b6'::uuid, NULL, NULL, E'Statistically speaking, the likelihood of this result is extremely low.', NULL, NULL),
  ('a9267036-5cc7-57e4-b5f0-77e8b55c92af'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a9267036-5cc7-57e4-b5f0-77e8b55c92af'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f1c59f6d-5ed1-5ee7-8a55-d4e32b943b4b'::uuid, NULL, E'In many ways, our social statistics exaggerate the degree of hardship.', NULL, NULL, NULL),
  ('a9286527-0aa4-56f5-b90a-1983dbed837d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a9286527-0aa4-56f5-b90a-1983dbed837d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4cabe1df-8a4d-5d83-82f7-547a56fc09b5'::uuid, NULL, E'Let''s meet at a later time instead of the earlier one, as previously agreed.', NULL, NULL, NULL),
  ('a92e4c39-44f7-5e68-9c62-085c6a5555e7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a92e4c39-44f7-5e68-9c62-085c6a5555e7'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '612c3e88-c1fe-5349-89f6-f18f96cf2d19'::uuid, NULL, E'I can''t make the lecture due to my scheduled doctor''s appointment.', NULL, NULL, NULL),
  ('a92ecf94-bebd-56f1-bf46-9b4f64020a70'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a92ecf94-bebd-56f1-bf46-9b4f64020a70'::uuid, 1, NULL, TRUE, 0, NULL, E'Values of Literature', E'Certainly one of the important values of literature is that it nourishes our emotional lives. An effective literary work may seem to speak directly to us especially if we are ripe for it. The inner life that good writers reveal in their characters often gives us glimpses of some portion of ourselves. We can be moved to laugh, cry, tremble, dream, ponder, shriek, or rage with a character by simply turning the page instead of turning our lives upside down.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a9336b09-edee-51fd-9673-2bae964dd30c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'a9336b09-edee-51fd-9673-2bae964dd30c'::uuid, 1, NULL, TRUE, 0, NULL, E'Reality (Camus'' text)', E'Surely, reality is what we think it is; reality is revealed to us by our experiences. To one extent or another, this view of reality is one many of us hold, if only {{1}} . I certainly find myself {{2}} this way in day-to-day life; it''s easy to be {{3}} by the face nature reveals directly to our senses. Yet, in the decades since first {{4}} Camus'' text, I''ve learned that modern science {{5}} a very different story.', NULL, NULL, NULL, E'1.implicitly, 2.thinking, 3.seduced, 4.encountering, 5.tells', NULL, NULL),
  ('a93378fc-7ca0-5443-873f-22ea6a27ea9f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a93378fc-7ca0-5443-873f-22ea6a27ea9f'::uuid, 1, NULL, TRUE, 0, NULL, E'Tutor', E'Your tutor helps you make the most of your time at university by giving you guidance and support along the way. All new students are allocated a personal tutor who will encourage you to get the most out of your course, direct you to other sources of support and help you achieve your goals.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a9373429-2a38-5d13-97ad-92c34046e2ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a9373429-2a38-5d13-97ad-92c34046e2ee'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2df075f3-e562-5625-bdc3-e4af3f765060'::uuid, NULL, NULL, E'University clubs offer students opportunities to pursue their diverse interests.', NULL, NULL),
  ('a939d473-a127-5666-a246-207aee127874'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a939d473-a127-5666-a246-207aee127874'::uuid, 1, NULL, TRUE, 0, NULL, E'Molly Pitcher', NULL, '234aff67-a9ce-5184-9435-77f8cbf813bc'::uuid, NULL, E'Last week we talked about Anne Bradstreet and the role of women in the Puritan colonies. Today I want to talk about some other women who''ve contributed to American history—some famous and some not-so-famous. The first woman I''d like to talk about is Molly Pitcher. Those of you who are familiar with the name may know her as a hero of the American Revolution. But, in fact, there never was a woman named Molly Pitcher. Her real name was actually Mary Ludwig Hays. She got the nickname Molly Pitcher for her acts of bravery during the Revolutionary War. As the story goes, when Mary''s—or Molly''s—husband, John Hays, enlisted in the artillery, Mary followed, like many other wives did. She helped out doing washing and cooking for the soldiers. She was known to be a pretty unusual woman. She smoked a pipe and chewed tobacco. Anyway, in the summer of 1778, at the Battle of Monmouth, it was a blistering hot day, maybe over a hundred degrees, and fifty soldiers died of thirst during the battle. Molly wasn''t content to stay back at camp. Instead, she ran through gunshots and cannon fire carrying water in pitchers from a small stream out to the thirsty American soldiers. The relief that she brought with her pitchers of water gave her the legendary nickname Molly Pitcher. The story also says that she continued to load and fire her husband''s cannon after he was wounded. They say she was so well liked by the other soldiers that they call her "Sergeant Molly." In fact, legend has it that George Washington himself gave her the special military title.', NULL, NULL, NULL),
  ('a93aa675-069e-5223-8d8c-ccdf8734f32d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'a93aa675-069e-5223-8d8c-ccdf8734f32d'::uuid, 1, NULL, TRUE, 0, NULL, E'Love of Reading', E'Many parents want their children to grow up with a love of reading. However, recent research {{1}} that children nowadays spend far more of their time using their phones or computers than reading books. Of course, technology brings children many advantages, but books are {{2}} important as computers. For instance, when children read storybooks, they imagine the characters and practise their language skills, too.\nMany British schools run an event called World Book Day. This event {{3}} to promote reading to pupils using various fun activities. Some pupils come to school in costumes inspired by their favourite book. Other schools organise World Book Day activities where pupils create music, art or plays about books.\nBut it''s also important for children to read at home, too. At the moment, {{4}} parents spend time reading with their children regularly. Unfortunately, this means that these children are missing an opportunity to develop the reading habit at an early age.', NULL, NULL, NULL, E'1.has shown, 2.as, 3.aims, 4.very few', NULL, NULL),
  ('a942612c-ec15-51b1-9adf-9c33f54f6486'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'a942612c-ec15-51b1-9adf-9c33f54f6486'::uuid, 1, NULL, TRUE, 0, NULL, E'Local Museum', E'Quite a few people would first visit the local museums when they travel to new places. Discuss the reasons why people like to visit museums.', NULL, NULL, NULL, NULL, 200, 300),
  ('a943ca51-c89d-5076-8b5c-4a99e0c73073'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'a943ca51-c89d-5076-8b5c-4a99e0c73073'::uuid, 1, NULL, TRUE, 0, NULL, E'Live Music', NULL, NULL, NULL, NULL, E'2, 4, 1, 3', NULL, NULL),
  ('a94dcf54-9a11-5c08-a4e3-48e6bb0ad441'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a94dcf54-9a11-5c08-a4e3-48e6bb0ad441'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a society which is ruled or controlled by men?', '9de31de2-e7e0-5779-93cf-313e65ff6cb1'::uuid, NULL, NULL, E'Patriarchy', NULL, NULL),
  ('a96a4bc1-5fe3-5b48-a0e5-26ee30634945'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'a96a4bc1-5fe3-5b48-a0e5-26ee30634945'::uuid, 1, NULL, TRUE, 0, NULL, E'Prison', E'Some people see prisons as the place where criminals should be punished, while some people think their primary function should be to teach them how to lead better lives. What is your opinion about the main function of time spent in prison, punishment or rehabilitation?', NULL, NULL, NULL, NULL, 200, 300),
  ('a9760d9a-b53f-574c-8356-8c109d2ec18b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a9760d9a-b53f-574c-8356-8c109d2ec18b'::uuid, 1, NULL, TRUE, 0, NULL, E'Hydrogen Technology', E'Hydrogen will play several roles in our future. For transport, we now see several manufacturers launching cars powered by electricity produced in a hydrogen fuel cell, and this will happen even more in the near future. Fuel cell buses are also an attractive solution for public transport. Also engineers are now even starting to consider using fuel cells and hydrogen to power trains.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a979f01d-d5c9-5986-b52b-3044460b1d8a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a979f01d-d5c9-5986-b52b-3044460b1d8a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3d49a0b0-c39f-5c97-8342-b248be91239b'::uuid, NULL, E'Conformity involves acting or thinking like other group members.', NULL, NULL, NULL),
  ('a97dd04e-1bc6-502f-89aa-f5a86c8b9904'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a97dd04e-1bc6-502f-89aa-f5a86c8b9904'::uuid, 1, NULL, TRUE, 0, NULL, E'SMW', E'Land animals move easily through air, because air does not slow them down. Sea creatures, on the other hand, have to move through water, which is hundreds of times thicker than air. A sea animal has to push itself through water in order to move. Sea animals use many different ways to swim, creep or glide through water. Fish are able to swim by bending their bodies into waves. They have flattened fins and tails that push against the water, like, or blades converting their body waves into forward movement. The size of officious tail contributes to the swimming speed. Small tail fins are found in slow swimmers, like the eel. The medium sized tail of the base is linked with a medium to fast swimming speed. Long pointed tail lobes, like those on the marlin, are found only on fast.\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', 'd339e80d-9fed-5f80-9b08-608b0afa2f7e'::uuid, NULL, NULL, E'swimmers', NULL, NULL),
  ('a985848b-6ae8-5c2b-a154-c3f1feabc292'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'a985848b-6ae8-5c2b-a154-c3f1feabc292'::uuid, 1, NULL, TRUE, 0, NULL, E'Plastic Waste', E'Plastic waste accumulating in the global ocean is an increasingly threatening environmental issue. Although research on the topic has attracted {{1}} attention in recent years, major knowledge {{2}} remain. A {{3}} scientific challenge at present is to determine the mass of plastic present on coastlines, the ocean surface and the deep ocean, as well as to quantify the plastic {{4}} between these compartments.', NULL, NULL, NULL, E'1.considerable, 2.gaps, 3.crucial, 4.fluxes', NULL, NULL),
  ('a98671ec-3adf-5110-979d-b925e9fa8612'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a98671ec-3adf-5110-979d-b925e9fa8612'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the machine used to dry clothes after they have been washed?', 'f90e1b17-fa9c-5b95-bbd2-94d92348d178'::uuid, NULL, NULL, E'Dryer', NULL, NULL),
  ('a986ef94-d07d-5cf9-9f9c-83768209c62e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a986ef94-d07d-5cf9-9f9c-83768209c62e'::uuid, 1, NULL, TRUE, 0, NULL, E'Nuclear Fallout', NULL, '9e7f17d4-0ad3-5a8a-abc8-e10c9a5c0c43'::uuid, NULL, E'And though it may sound surprising, the best way to stay protected before, during, and after a nuclear detonation, is getting inside. Similar to protecting yourself from tornadoes or hurricanes, getting and staying inside a sturdy building would offer protection from the explosion’s shock wave, heat, and radiation. The shock wave of energy would travel several kilometers beyond the fireball’s radius in the first few seconds. Sturdy buildings within that range should be able to withstand the shock wave, and staying in the centers and basements of these buildings also helps provide protection from heat and flying objects. Finding shelter is especially important if the fireball occurs close to the earth, as it will pull thousands of tons of dirt and debris several kilometers into the atmosphere. As the fireball cools, unstable atoms created by the nuclear fission mix with the debris to produce the most dangerous long-term effect of a nuclear detonation: radioactive particles called fallout. These sand-sized particles emit-ionizing radiation, capable of separating electrons from molecules and atoms. Exposure to massive amounts of this radiation can result in cell damage, radiation burns, radiation sickness, cancer, and even death. Thankfully, the same buildings that offer protection from the blast are even better at guarding against fallout. Radiation is reduced as it travels through space and mass. So while a broken window and sealed window both have the same minimal effect on radiation, thick layers of steel, concrete, and packed earth can offer serious protection.', NULL, NULL, NULL),
  ('a98a2236-3d1e-57b2-b5fa-6916bb6b166b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a98a2236-3d1e-57b2-b5fa-6916bb6b166b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'what we call it if trees are cut down in a large area?', 'ccfa7487-fd7d-5e3a-8c54-4a0f4cbc53df'::uuid, NULL, NULL, E'Deforestation', NULL, NULL),
  ('a98d1904-7b09-5294-8221-375ba874645b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a98d1904-7b09-5294-8221-375ba874645b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e5cc716f-b1b9-5d5b-a102-889c0ba4c184'::uuid, NULL, NULL, E'A good way to improve vocabulary is repetition.', NULL, NULL),
  ('a9950c3e-6ef8-5626-8eef-0a00bf04f4c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a9950c3e-6ef8-5626-8eef-0a00bf04f4c4'::uuid, 1, NULL, TRUE, 0, NULL, E'Immigration Control', NULL, '266e1903-0259-58ed-9a5d-f3487b3c4ade'::uuid, NULL, E'Now the economists’ calculated, it’s a-back-of-the-envelope calculation, that removing all immigration controls would double the size of the world economy, and even a small relaxation of immigration controls would lead to disproportionally big gains. Now for an ethical point of view, it’s hard to argue against a policy that will do so much to help people that are much poorer than ourselves. The famous Rand Study reckons that a typical immigrant who arrives in US ends up with $20,000 a year, that’s rough. It’s not just the migrants themselves who gain, it’s the countries they come from. Already, the migrants working for poor countries working in rich countries send home around 200 billion dollars a year, through formal channels, and about twice as that through informal channels. And that compares to the neat a hundred million dollars that Western governments give in aid. These remittances are not wasted on weapons or siphoned off into Swiss bank accounts; they go straight into the pockets of local people. They pay for food, clean water, and medicines, they help kids in school, they help start up new business. Sample answer: Removing immigration control would double the world economy. This policy will do so much to help poor people. Immigrants ends up with 20000 a year from gain and countries they come from. They send home around 200 billion dollars a year through formal channels which are twice as that through informal channels. These remittances can help local people for living straightly.', NULL, NULL, NULL),
  ('a9960865-b9e9-50c0-b843-76c73e6b6d71'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'a9960865-b9e9-50c0-b843-76c73e6b6d71'::uuid, 1, NULL, TRUE, 0, NULL, E'New Zealand', E'Twelve hundred miles east of Australia {{1}} the islands of New Zealand. Long before they were {{2}} by Europeans, a Polynesian race of warriors, the Maoris, had sailed across the Pacific from the northeast and established a civilization {{3}} for the brilliance of its art and the strength of its military {{4}} . When Captain Cook visited these islands towards the end of the 18th century, he {{5}} that the population numbered about a hundred thousand.', NULL, NULL, NULL, E'1.lie, 2.discovered, 3.notable, 4.system, 5.estimated', NULL, NULL),
  ('a99b0737-9689-52f4-8682-fa893c0ece36'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a99b0737-9689-52f4-8682-fa893c0ece36'::uuid, 1, NULL, TRUE, 0, NULL, E'Historical Contingency', E'The teleology and historical contingency of biology make it unique among the sciences. Both of these features stem from perhaps biology’s only general guiding principle: evolution. It depends on chance and randomness, but natural selection gives it the appearance of intention and purpose. Animals are drawn to water not by some magnetic attraction, but because of their instinct to survive.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a99facd7-10b4-579d-82fa-bf007d4803d9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'a99facd7-10b4-579d-82fa-bf007d4803d9'::uuid, 1, NULL, TRUE, 0, NULL, E'Remaining Professional', E'Behaving in a professional manner is a key to success in the workplace. Maintaining that {{1}} , even in stressful times, can be a challenge. What does it mean to be “professional” at work? The definition varies, but usually includes {{2}} knowledge and expertise, being in a positive mood, meeting your {{3}} accurately and on time, respecting all with whom you interact, using proper language, operating ethically, having social and emotional intelligence and maintaining an appropriate appearance. Other terms describing professional {{4}} in the workplace are soft skills, protocol, business etiquette and polish.', NULL, NULL, NULL, E'1.demeanor, 2.possessing, 3.obligations, 4.conduct', NULL, NULL),
  ('a9b265ff-30e2-5f56-95ad-349fc5dee6b1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a9b265ff-30e2-5f56-95ad-349fc5dee6b1'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd8666113-b019-5794-a80b-a456c1b485a5'::uuid, NULL, NULL, E'This study gives new ideas about what people think of tech.', NULL, NULL),
  ('a9b9ddfa-b428-5695-a197-eccb38dbbd6e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'a9b9ddfa-b428-5695-a197-eccb38dbbd6e'::uuid, 1, NULL, TRUE, 0, NULL, E'Spending or Saving', E'When you earn money, is it better to enjoy it or save it for the future? Please prove your opinion with specific reasons.', NULL, NULL, NULL, NULL, 200, 300),
  ('a9bb45dd-3c59-5123-82dd-e74b308e475d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a9bb45dd-3c59-5123-82dd-e74b308e475d'::uuid, 1, NULL, TRUE, 0, NULL, E'Diet', NULL, '37f2fbc3-8f21-5994-a387-7cca50f8321d'::uuid, NULL, E'Everyone is interested in improving their diet. Adding grains is one of the easiest ways. Many people in the United States have a growing concern about nutrition, so grains are often served in restaurants. And many grains are now available in grocery stores, too, though for some you still have to go to health food stores. You can stock up when you go, though, because uncooked grains keep a long time. You''ll find that grains are easy to prepare. Many grains are as simple to cook as spaghetti. Barley, for instance, is just cooked in salted water. Remember, though, whole-grain barley, the most nutritious kind, never will get as tender as spaghetti no matter how long it''s cooked. Grain-based salads are easy, too. Just use grains left over from a hot meal. You call even put together a grain salad hours before you need it, since grains don''t wilt like lettuce does. But to get back to health factors, all grains are nutritious and many have special benefits. Barley has very little fat. Some experts believe that it may even reduce cholesterol levels. Jasmine rice is also low in fat. And it has a bonus in its wonderful aroma, a very special fragrance.', NULL, NULL, NULL),
  ('a9bd307f-1acc-56e8-bf79-a2af59ada9ec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'a9bd307f-1acc-56e8-bf79-a2af59ada9ec'::uuid, 1, NULL, TRUE, 0, NULL, E'Major Conclusion', E'Our major conclusion is that the current measure needs to be revised. It no longer provides an accurate picture of the differences in the extent of economic poverty among population groups or geographic areas of the country, nor an accurate picture of trends over time.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('a9c03d9c-f78a-5cc0-8b35-d54794492922'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'a9c03d9c-f78a-5cc0-8b35-d54794492922'::uuid, 1, NULL, TRUE, 0, NULL, E'External Appearance', E'One should never judge a person by external appearances. To what extent do you agree with this statement?', NULL, NULL, E'In a world where appearances are often given undue importance, the statement "One should never judge a person by external appearances" holds significant truth. I firmly agree with this statement as it emphasizes the importance of looking beyond superficial attributes to truly understand and appreciate an individual.\nFirstly, external appearances cannot accurately reflect a person''s true character and qualities. Superficial judgments based solely on appearances can lead to misunderstandings and stereotypes. By not judging solely based on external appearances, we open ourselves up to discovering the depth and complexity of individuals, allowing for a more genuine and meaningful connection.\nSecondly, judging based on external appearances undermines the principles of fairness and inclusivity. Every individual deserves to be treated with respect and given a fair chance to be understood. By disregarding external appearances, we create an environment that promotes empathy, understanding, and acceptance, fostering a more harmonious and inclusive society.\nIn conclusion, it is crucial to recognize that external appearances do not define a person''s true worth or character. By embracing the belief that one should never judge a person by external appearances, we encourage a more compassionate and open-minded approach to understanding others. This mindset allows us to appreciate the richness and diversity of humanity, fostering deeper connections and promoting a more inclusive society for all.', NULL, 200, 300),
  ('a9cd4f44-e6b4-58ce-a52b-bc4d1a4c05f1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a9cd4f44-e6b4-58ce-a52b-bc4d1a4c05f1'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '12efff71-5464-5004-af5c-7ffe3244a061'::uuid, NULL, NULL, E'The later chapters discuss the effects on the environment.', NULL, NULL),
  ('a9d6ce8d-4893-55fd-87a3-687a5d8a7d84'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'a9d6ce8d-4893-55fd-87a3-687a5d8a7d84'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd3cf62b2-d1f7-55af-9dad-5e6d76d7365e'::uuid, NULL, NULL, E'His contribution has been key to the development of modern mathematics.', NULL, NULL),
