  ('a9f31708-74c4-5e14-b922-e0d651028535'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'a9f31708-74c4-5e14-b922-e0d651028535'::uuid, 1, NULL, TRUE, 0, NULL, E'Evolution of Cinema', E'The evolution of cinema, from its humble {{1}} to its current status as a global cultural phenomenon, is a testament to the {{2}} of storytelling through moving images. The Lumière brothers, pioneers of early film, first projected motion pictures to a mesmerized audience in 1895, {{3}} the birth of cinema as we know it. Since {{4}} , the art of filmmaking has grown and diversified, {{5}} boundaries of language and culture.', NULL, NULL, NULL, E'1.beginnings, 2.power, 3.marking, 4.then, 5.transcending', NULL, NULL),
