  ('aa09a3fa-1f1a-557b-b9d7-0115f02174e4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'aa09a3fa-1f1a-557b-b9d7-0115f02174e4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd2a86a88-58ff-55d0-86c4-a0d2d1a6385d'::uuid, NULL, NULL, E'Writers usually write about things they know or have lived.', NULL, NULL),
  ('aa0efa65-610f-53ed-a60a-94459a6eb155'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'aa0efa65-610f-53ed-a60a-94459a6eb155'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0fd7d76c-d664-5a72-98e2-ea0701bfbfbf'::uuid, NULL, NULL, E'He wasn''t the only advocate pushing for legal reforms back then.', NULL, NULL),
  ('aa101b34-27c3-55b4-b9ab-3be44ae12c24'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'aa101b34-27c3-55b4-b9ab-3be44ae12c24'::uuid, 1, NULL, TRUE, 0, NULL, E'SMW', E'The complex process inside a leaf takes energy from the sun and uses it to convert water and carbon dioxide into sugars. During this process, photosynthesis plants convert light energy into chemical energy. All leaves carry out photosynthesis in basically the same way. First, the pores on the leaves, outer skin open up and taking molecules of carbon dioxide. Water absorbed by the roots is transported upward through the plant, and it enters the leaf through its stem, carbon dioxide, and water. These are the raw materials for photosynthesis. Once carbon dioxide and water are present, photosynthesis can.\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '8effaf99-937a-5e69-a2e3-b51326ec8c5a'::uuid, NULL, NULL, E'begin', NULL, NULL),
  ('aa1316f9-25da-53bf-bab9-9e4fef6f9956'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aa1316f9-25da-53bf-bab9-9e4fef6f9956'::uuid, 1, NULL, TRUE, 0, NULL, E'ATP', E'Adenosine triphosphate, or ATP, is the molecule that provides energy for most biological processes in living cells. It is often referred to as the "molecular unit of currency" within the cell. ATP is formed through a process called cellular respiration, which occurs in the mitochondria of cells.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('aa1459ac-5562-58d2-8c9f-854803acebac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aa1459ac-5562-58d2-8c9f-854803acebac'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the spicy root vegetable often grated and used in sushi?', '41d259b0-d33d-5e24-bd17-cea9207afffb'::uuid, NULL, NULL, E'Wasabi', NULL, NULL),
  ('aa18127f-e349-5970-8e56-80627156783d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'aa18127f-e349-5970-8e56-80627156783d'::uuid, 1, NULL, TRUE, 0, NULL, E'Friends'' Opinions', E'Some people think that the family has the most important influence on young adults. Other people think that friends have the most important influence on young adults. What is your opinion?', NULL, NULL, E'The debate over whether family or friends have the most significant influence on young adults has been ongoing for years. While some argue that family plays a vital role in shaping young adults'' lives, others believe that friends have a more critical impact. This essay will argue that family has the most important influence on young adults.\nFamily is the first social group that young adults are exposed to and spend most of their early lives with. As a result, family members have a deep understanding of their children''s character, strengths, and weaknesses. Parents can provide guidance and support to their children, which can help them make better decisions. For example, when young adults encounter difficulties, they often turn to their parents for advice and support. Parents can also instill values and beliefs that shape young adults'' attitudes towards life.\nWhile friends play an essential role in young adults'' lives, their influence is often temporary. Friendships can be fleeting, and young adults may not remain close to the same people throughout their lives. Friends may also encourage young adults to engage in risky behaviors or make poor decisions that could have long-term consequences. On the other hand, family members are more likely to provide consistent support and guidance throughout their children''s lives.\nIn conclusion, while friends can be a valuable source of support and guidance, family has the most important influence on young adults. Parents and other family members have a deep understanding of their children''s characters and can provide consistent support throughout their lives. Therefore, it is crucial for young adults to maintain strong relationships with their families to ensure that they receive the guidance and support they need to make informed decisions and lead fulfilling lives.', NULL, 200, 300),
  ('aa227255-1ed9-578b-a0f1-a1169d8bdb78'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aa227255-1ed9-578b-a0f1-a1169d8bdb78'::uuid, 1, NULL, TRUE, 0, NULL, E'Heat and Humidity', E'Scientists have identified the maximum mix of heat and humidity a human body can survive. Even a healthy young person will die after enduring six hours of 35-degree Celsius warmth when coupled with 100 percent humidity, but new research shows that threshold could be significantly lower.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('aa26bc3c-cdc9-5aaf-a682-38ced3f90d53'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aa26bc3c-cdc9-5aaf-a682-38ced3f90d53'::uuid, 1, NULL, TRUE, 0, NULL, E'College Football', E'With revenue from college football at an unprecedented 3.4 billion dollars annually, universities across the country invest millions each year in recruitment efforts for high school football players. But with talented players typically receiving multiple scholarship offers, team rosters are in limbo until student athletes commit to a university.', NULL, NULL, NULL, NULL, NULL, NULL),
