  ('aa2894ca-5a89-5ae4-9b12-90f03f4ea5d1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aa2894ca-5a89-5ae4-9b12-90f03f4ea5d1'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e4f4e3ed-c52d-559f-bf13-4547a67aa13a'::uuid, NULL, E'The number of people in the world tripled during the last century.', NULL, NULL, NULL),
  ('aa2ed367-1231-5990-abf6-3a5e266f4f13'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aa2ed367-1231-5990-abf6-3a5e266f4f13'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the largest internal organ in the human body?', '944abb13-1b74-516b-9dcd-b441eb0bcce8'::uuid, NULL, NULL, E'Liver', NULL, NULL),
  ('aa2ee39c-1e25-5a94-944f-2aab17a67250'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aa2ee39c-1e25-5a94-944f-2aab17a67250'::uuid, 1, NULL, TRUE, 0, NULL, E'Macroeconomics', E'This report includes a huge swath of macroeconomics, such as the effects of tax reform, a new industrial policy, and understanding how to deal with the uncertainty inherent in global financial market. But it also covers key areas of microeconomic policies, such as boosting laggardly rates of productivity.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('aa370569-795b-58c8-b7d9-725536e98748'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aa370569-795b-58c8-b7d9-725536e98748'::uuid, 1, NULL, TRUE, 0, NULL, E'Lenient Parents', E'Two sisters were at a dinner party when the conversation turned to upbringing. The elder sister started to say that her parents had been very strict and that she had been rather frightened of them. Her sister, younger by two years, interrupted in amazement. "What are you talking about?" she said. "Our parents were very lenient."', NULL, NULL, NULL, NULL, NULL, NULL),
  ('aa413dde-9144-5565-87eb-2805d3837b57'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'aa413dde-9144-5565-87eb-2805d3837b57'::uuid, 1, NULL, TRUE, 0, NULL, E'Communication Study', E'World War II played a major role in {{1}} the direction of communication study during the 1940s. Two instrumental players in communication research during this era, Kurt Lewin and Carl Hovland et al. studied group dynamics and mass communication. {{2}} World War II, scholars such as Lazarsfeld, Lasswell, Hovland, and Schramm wanted to bring more credibility and attention to their research. One approach they used to {{3}} this was to call for Communication study to be its own field of research at universities. They began using the terms “mass communication” and “communication research” more frequently in their writings, which helped begin the process of {{4}} Communication research and departments from other fields such as political science, psychology, and sociology. This {{5}} as the big push to create departments of Communication that you are familiar with today.', NULL, NULL, NULL, E'1.shaping, 2.Following, 3.accomplish, 4.distinguishing, 5.served', NULL, NULL),
  ('aa44925f-74ac-5187-8b3f-42106f13030b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'aa44925f-74ac-5187-8b3f-42106f13030b'::uuid, 1, NULL, TRUE, 0, NULL, E'Greenland Sharks', E'An international team of scientists, including a physiologist from The University of Manchester, will head to the largest island in the world later this month to investigate the Greenland shark – believed to be the longest-lived vertebrate animal. Dr Holly Shiels, who is also a trustee of the Physiological Society, will be the only UK-based scientist on the expedition aboard the research vessel Sanna commissioned by the Greenland government. The purpose of the mission is to understand more about the Greenland shark, a top predator in the Arctic, which lives for more than 272 years - possibly more than 400. This extreme age was only revealed by scientists from Copenhagen last year and published in the journal Science. Little else is known about how the shark survives in the deep seas around the Arctic Circle. It is both a hunter and a scavenger and has been seen to feed on seals and been found with the remains of polar bears and whales in its stomach. It is also one of the largest species of shark – growing to about five-and-a-half metres, just a bit smaller than the great white. However, more information is required to ensure the species is adequately protected, as Dr Shiels explained: "Greenland sharks are classified as data deficient," she said. "This means that we don''t know enough to put measures in place to protect them from over-fishing, pollution or climate change. This expedition has a broad range of expertise which means that we''ll be able to take full advantage of any sharks that we discover."', NULL, NULL, E'The Greenland shark is believed to be the longest-lived vertebrate animal, but little else is known about how the shark survives in the deep seas around the Arctic Circle, and it is both a hunter and a scavenger, which is also one of the largest species of shark, so more information is required to ensure the species is adequately protected, as Greenland sharks are classified as data deficient.', NULL, 5, 75),
  ('aa460c57-6770-5de5-9e26-695da34e751d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'aa460c57-6770-5de5-9e26-695da34e751d'::uuid, 1, NULL, TRUE, 0, NULL, E'Sun Clock', E'OK, so the date of the invention of the first clock is disputed among historians but it''s agreed that the first method for telling the time was the movement of the sun across the sky. When the sun was directly ahead, it was midday and when it was on the horizon, it was early morning or early evening, according to whether it was in the east or the west. However, this method was problematic in terms of accuracy: but nevertheless, it''s been used for countless years, from early humanity to - - - .\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', 'b52d4efd-6381-5bba-b26d-f0b639c4e2d6'::uuid, NULL, NULL, E'current days', NULL, NULL),
  ('aa4b4b21-299b-5102-b51b-27fec9cc8990'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'aa4b4b21-299b-5102-b51b-27fec9cc8990'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '65b8f197-919c-50db-8bf7-9b5d6c76b563'::uuid, NULL, NULL, E'Doing activities outside class helps students learn more skills.', NULL, NULL),
