  ('aa4f6de2-1821-5f2f-a31b-fb560d11a72d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'aa4f6de2-1821-5f2f-a31b-fb560d11a72d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '40ba011b-8d03-5526-8936-ca50b1ef0a91'::uuid, NULL, NULL, E'The college includes two branches, physical and social sciences.', NULL, NULL),
