  ('ab08413b-f25b-5569-9c6b-b99de326412b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ab08413b-f25b-5569-9c6b-b99de326412b'::uuid, 1, NULL, TRUE, 0, NULL, E'Business Climate', E'The climate for doing business improved in Egypt more than in any other country last year, according to a global study that revealed a wave of company-oriented reforms across the Middle East. The World Bank rankings, which look at business regulations, also showed that the pace of business reforms in Eastern Europe was overtaking East Asia .', NULL, NULL, NULL, NULL, NULL, NULL),
