  ('ab228225-a791-5a0c-a91b-31e8f007c667'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ab228225-a791-5a0c-a91b-31e8f007c667'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '34d37d62-c1b2-5f85-b9e6-5f189786baac'::uuid, NULL, E'The café house is closed down and the snack machine is still running (throughout the night)', NULL, NULL, NULL),
  ('ab231043-5eec-59e7-a404-8258e4266551'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ab231043-5eec-59e7-a404-8258e4266551'::uuid, 1, NULL, TRUE, 0, NULL, E'Sportsmanship', E'Sportsmanship comes in many forms and helps make competitive games fun and enjoyable. It fosters good habits and positive life skills both in and out of sports games, and is an important life skill for people of all ages. It is also key to becoming a mature, respectful, and successful adult.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ab2438f5-0cd9-5ceb-b6d0-3730c5270c46'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ab2438f5-0cd9-5ceb-b6d0-3730c5270c46'::uuid, 1, NULL, TRUE, 0, NULL, E'Cryptocurrencies', E'Cryptocurrencies emerge from the digital {{1}} between various encryption techniques. As many cryptocurrencies were developed during the digital {{2}} , one of the components is often a traditional currency, like the US dollar, {{3}} the other component is a cryptographic protocol. Typically, one provides the main transactional functionality, and the other ensures security. When cryptocurrencies become mainstream as a {{4}} of transaction, they might evolve into a new form of digital asset.', NULL, NULL, NULL, E'1.interaction, 2.age, 3.while, 4.mode', NULL, NULL),
  ('ab25856e-e2f6-589b-b8c9-ab69cc6d15b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ab25856e-e2f6-589b-b8c9-ab69cc6d15b8'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2dd38459-ed70-5a99-bff1-1543cfa15e95'::uuid, NULL, NULL, E'Nurses can specialize in clinical work or management.', NULL, NULL),
  ('ab28e17c-9084-5de6-9e5a-5b90ce58256b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ab28e17c-9084-5de6-9e5a-5b90ce58256b'::uuid, 1, NULL, TRUE, 0, NULL, E'Newer Sites', E'Newer sites usually are more accessible than older ones. Many facility owners and operators may not have the experience or knowledge to determine the level of accessibility on their sites. If they have never received any complaints, they may mistakenly assume that no problems exist. Inspect all areas of the site carefully to make an accurate assessment of its level of accessibility.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ab2fa2f8-ddcb-5aae-9121-235b48abe5bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ab2fa2f8-ddcb-5aae-9121-235b48abe5bd'::uuid, 1, NULL, TRUE, 0, NULL, E'Mathematical Languages', E'The mathematical language for talking about connections, which usually depends on networks — vertices and edges — has been an invaluable way to model real-world phenomena. But a few decades ago, the emergence of giant data sets forced researchers to expand their toolboxes and, at the same time, gave them sprawling sandboxes to apply new mathematical insights.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ab36020b-67d0-59c1-8c89-e6ed7ce71cc0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'ab36020b-67d0-59c1-8c89-e6ed7ce71cc0'::uuid, 1, NULL, TRUE, 0, NULL, E'Packet', E'Internet data, whether in the form of a Web page, a downloaded file or an e-mail message, travels over a system known as a packet-switching network. In this system, the data in a message or file is broken up into packages about 1,500 bytes long. Each of these packages gets a wrapper that includes information on the sender''s address, the receiver''s address, the package''s place in the entire message, and how the receiving computer can be sure that the package arrived intact. Each data package, called a packet, is then sent off to its destination via the best available route -- a route that might be taken by all the other packets in the message or by none of the other packets in the message.\n\nAccording to the text, which description below of the transmission process is NOT true?', NULL, NULL, NULL, E'The receiving computer can determine whether or not the package is intact all by itself.', NULL, NULL),
  ('ab3a0034-89d3-574c-849c-cad2e9823bec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ab3a0034-89d3-574c-849c-cad2e9823bec'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the state of sharing the same opinion?', 'af19ce82-25a1-53c4-8e48-3a046468fc7b'::uuid, NULL, NULL, E'Agreement / consensus', NULL, NULL),
  ('ab3cfa56-903c-5654-a539-5f4f8a1798d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ab3cfa56-903c-5654-a539-5f4f8a1798d7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1ceaeb28-a245-584c-83b9-b56ba4ba01fa'::uuid, NULL, NULL, E'The task tomorrow will require a higher level of skill.', NULL, NULL),
  ('ab41a411-c2ac-5437-b2ef-6efd982cf146'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'ab41a411-c2ac-5437-b2ef-6efd982cf146'::uuid, 1, NULL, TRUE, 0, NULL, E'Beauty Contest', E'Since Australians Jennifer Hawkins and Lauryn Eagle were crowned Miss Universe and Miss Teen International respectively, there has been a dramatic increase in interest in beauty pageants in this country. These wins have also sparked a debate as to whether beauty pageants are just harmless reminders of old-fashioned values or a throwback to the days when women were respected for how good they looked.\nOpponents argue that beauty pageants, whether Miss Universe or Miss Teen International, are demeaning to women and out of sync with the times. They say they are nothing more than symbols of decline.\nIn the past few decades Australia has taken a real step toward treating women with dignity and respect. Young women are being brought up knowing that they can do anything, as shown by inspiring role models in medicine such as 2003 Australian of the Year Professor Fiona Stanley.\nAlmost all of the pageant victors are wafer thin, reinforcing the message that thin equals beautiful. This ignores the fact that men and women come in all sizes and shapes. In a country where up to 60 percent of young women are on a diet at any one time and 70 percent of school girls say they want to lose weight, despite the fact that most have a normal BMI, such messages are profoundly hazardous to the mental health of young Australians.', NULL, NULL, E'While Australian has taken a real step toward treating women with dignity and respect, young Australian women still concern more about their body shapes because not only all the beauty pageants are judged by their looks, and they are reinforcing the idea that thin equals beautiful, but also they ignore the fact that men and women do come in all sizes and shapes, which are hazardous to the mental health of young Australians.', NULL, 5, 75),
  ('ab425249-88e6-5b39-8c30-52c3520ed410'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ab425249-88e6-5b39-8c30-52c3520ed410'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f96634ea-c5c7-5922-861a-4e0ae6856954'::uuid, NULL, NULL, E'Access the lecture slides and notes online after the class ends.', NULL, NULL),
  ('ab4ca981-a494-5972-a284-86af3921f3c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ab4ca981-a494-5972-a284-86af3921f3c5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '66a8ad85-3612-526e-bf82-71b4460a81f3'::uuid, NULL, NULL, E'You may be charged for additional art supplies.', NULL, NULL),
  ('ab4d49a8-0d7a-5f1b-90b6-efcd7750726e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ab4d49a8-0d7a-5f1b-90b6-efcd7750726e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the collection and study of stamps?', '45c404d4-98ab-5b6a-b129-c625d554ef5e'::uuid, NULL, NULL, E'Philately', NULL, NULL),
  ('ab536dc4-cf3e-5c0f-b82f-f470efaa1c7d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ab536dc4-cf3e-5c0f-b82f-f470efaa1c7d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a light that usually has a glass covering and can be carried by a handle?', '908c34ad-52cd-5061-be15-242548abc45b'::uuid, NULL, NULL, E'Lantern / lanterns', NULL, NULL),
  ('ab5fe66d-74e6-5c32-863f-f0b6f743135d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ab5fe66d-74e6-5c32-863f-f0b6f743135d'::uuid, 1, NULL, TRUE, 0, NULL, E'Longevity Diet', E'I have seen my future and it is full of beans, both literally and {{1}} . As well as upping my bean count, there will be a lot of vegetables, no meat, long periods of hunger and hardly any alcohol. But in return for this dietary discipline, my future will also be significantly longer and {{2}} . I am 52 and, on my current diet, can expect to live another 29 years. But if I change now, I could gain an extra decade and live in good health into my 90s. This “longevity diet” isn’t just the latest fad, it is the product of more than a human lifespan of scientific research. And it isn’t merely designed to prevent illness, but to actually slow down the ageing process – that’s the claim, anyway. Of course, it is a no-brainer to say that our diets can alter our lifespans. Worldwide, millions of people still die {{3}} every year from lack of calories and nutrients. Meanwhile, an estimated 11 million die each year from too many calories and the wrong sort of nutrients.', NULL, NULL, NULL, E'1.metaphorically, 2.sprightlier, 3.prematurely', NULL, NULL),
  ('ab64efd3-ace5-537d-9f7f-92b5658d4e92'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ab64efd3-ace5-537d-9f7f-92b5658d4e92'::uuid, 1, NULL, TRUE, 0, NULL, E'Fiction and Life', E'The precise relationship between fiction and life has been debated extensively. Most modern critics agree that, whatever its apparent factual content or verisimilitude, fiction is finally to be regarded as a structured imitation of life and should not be confused with a literal {{2}} of life itself. While fiction is a work of the imagination rather than {{3}} , it can also be based closely on real events, sometimes experienced by the author. In a work of fiction, the author is not the same {{4}} the narrator, the voice that tells the story. Authors maintain a distance from their characters. Sometimes that distance is obvious for instance, if a male writer tells a story from the point of view of a female character. Other times it is not so obvious, especially if we know something of the author''s life and there are clear connections between the story and the author''s life. The writer of fiction is free to choose his or her subject matter and is free to invent, select, and {{5}} fictional elements to {{6}} his or her purpose. The elements of fiction are the different components that make up a work of fiction. All literature explores a theme or significant truth expressed in various elements such as character, plot, setting, point of view, style, and tone that are essential and specific to each work of fiction. All of these elements bind a literary work into a consistent whole and give it unity. Understanding these elements can help.', NULL, NULL, NULL, E'1.transcription, 2.reality, 3.as, 4.arrange, 5.achieve', NULL, NULL),
  ('ab68ac26-72bf-5159-9fdc-d78418540637'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ab68ac26-72bf-5159-9fdc-d78418540637'::uuid, 1, NULL, TRUE, 0, NULL, E'Water Security', E'Equally critical is the challenge of water security. The UN Environment Programme (UNEP) has pointed out that about one-third of the world''s population lives in countries with moderate to high water stress, with a {{1}} impact on the poor. With current projected global population growth, the task of providing water for human {{2}} will become increasingly difficult. And increasing competition over this scarce but vital resource may fuel instability and conflict within states as well as between states. The UN is doing a great deal in both areas to proactively foster {{3}} among Member States. UNEP has long been actively addressing the water issue together with partner UN {{4}} and other organizations. Looking ahead, the UN can do more to build synergies of technology, policy and capacity in this field. In this {{5}} , events like the annual World Water Week in Stockholm come to the forefront of the public mind when talking about championing water issues.', NULL, NULL, NULL, E'1.disproportionate, 2.sustenance, 3.collaboration, 4.agencies, 5.regard', NULL, NULL),
  ('ab7220e8-4646-5b50-bf4d-db5e8aff74af'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ab7220e8-4646-5b50-bf4d-db5e8aff74af'::uuid, 1, NULL, TRUE, 0, NULL, E'Shakespeare''s Writing Style', E'Shakespeare''s writing style is characterized by the use of stylized language and rhetorical devices. He often employed extended metaphors and conceits in his poetry, creating rich and vivid imagery. Some of his notable themes include love, power, ambition, fate, and the human condition. His works explore the depths of human emotions and the complexities of human relationships.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ab77d84b-c9ef-52ad-8dc3-7aa4d58a3535'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ab77d84b-c9ef-52ad-8dc3-7aa4d58a3535'::uuid, 1, NULL, TRUE, 0, NULL, E'Noise Control', E'You''ve organized a group study session with your classmates at your apartment. However, when they arrive, you notice some of them are not following the agreed-upon noise level and are causing disturbances to your neighbors. You need to remind them to be considerate of others. What would you say to your classmates?', 'fe5bd635-a6ca-507d-a0ac-9113265c8037'::uuid, NULL, E'Hey guys, thanks for coming over for our study session! Just a quick reminder, let''s keep the noise level down so we don''t disturb our neighbors. They''ve been really cool about letting us use the apartment, so let''s be respectful in return. Maybe we can use headphones or lower our voices to ensure everyone can focus. Thanks for understanding and helping create a conducive environment for studying!', NULL, NULL, NULL),
  ('ab7826b9-1ad4-5730-976d-c938436bf503'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ab7826b9-1ad4-5730-976d-c938436bf503'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9f137a79-f8ab-5f3d-b70c-0614c328cdcb'::uuid, NULL, E'Britain''s balance of payments deficit has improved slightly.', NULL, NULL, NULL),
  ('ab7c6592-7c30-5391-85fa-95d3677dd5e2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ab7c6592-7c30-5391-85fa-95d3677dd5e2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '298f822a-068a-524f-bd4a-89e0af1d0d8f'::uuid, NULL, NULL, E'The reception staff can give advice on renting private accommodation.', NULL, NULL),
  ('ab7efebe-24f7-574b-a015-c0dd6e989d9c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ab7efebe-24f7-574b-a015-c0dd6e989d9c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '684cdecc-5603-506f-b478-6dca7e05da84'::uuid, NULL, NULL, E'Every semester, students have the opportunity to take math and stats tests.', NULL, NULL),
  ('ab82f8e0-a697-52cc-8694-c0b1e2bbdf41'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ab82f8e0-a697-52cc-8694-c0b1e2bbdf41'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ec5c3a48-b24d-5dfe-bd80-c34733df5895'::uuid, NULL, NULL, E'Leaving valuable possessions unattended in public places is risky.', NULL, NULL),
  ('ab949385-1a23-50af-99c0-19fe24d98cc1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ab949385-1a23-50af-99c0-19fe24d98cc1'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Where do airplanes take off or land?', 'f13a7a7e-693d-53d3-a10d-a44763780881'::uuid, NULL, NULL, E'Airport', NULL, NULL),
  ('ab964c7a-0497-50c7-9e9c-8962599a215a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ab964c7a-0497-50c7-9e9c-8962599a215a'::uuid, 1, NULL, TRUE, 0, NULL, E'Hans Christian Andersen', E'Fans of biographical criticism have a luxurious source in the works of Hans Christian Andersen. Like Lewis Carroll (and, to a lesser extent, Kenneth Grahame), Andersen was near- pathologically uncomfortable in the company of adults. Of course, all three had to work and {{1}} with adults, but all three really {{2}} well to children and their simpler worlds. Andersen, for a time, ran a puppet theater and was incredibly popular with children, and, of course, he wrote an impressive body of fairy tales which have been produced in thousands of editions since the 19th century.\nMost everyone has read or at least knows the titles of many of Andersen’s works: “The Ugly Duckling,” “The Emperor’s New Clothes,” “The Nightingale,” “The Little Mermaid,” “The Match Girl,” and many others. Though, as with most folk and fairy tales, they {{3}} adult rereaders much differently than they do young first-time readers.\nCharming tales of ducks who feel {{4}} because they don’t fit in, only to exult in the discovery that they are majestic swans, gives child readers clearly-identifiable messages: don’t tease people because they’re different; don’t fret about your being different because some day you’ll discover what special {{5}} you have.\nA closer, deeper look at many of Andersen’s tales (including “The Ugly Duckling,” which is not on our reading list), reveals a darker, harder, more {{6}} thread. People are often cruel and unfeeling, love is torturous–in general, the things of the material world cause suffering. There is often a happy ending, but it’s not conventionally happy. Characters are rewarded, but only after they manage (often through death) to transcend the rigors of the mortal world.', NULL, NULL, NULL, E'1.interact, 2.related, 3.strike, 4.awkward, 5.gifts, 6.painful', NULL, NULL),
  ('aba4975d-fd16-5bbd-b472-63b95bfb0b12'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aba4975d-fd16-5bbd-b472-63b95bfb0b12'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'de6b69f9-9f9e-5561-a4e5-0ae41a7314ac'::uuid, NULL, E'Students should take advantage of the online resources before attending the lecture.', NULL, NULL, NULL),
