  ('acc92275-2337-5546-8a53-f21d8d0bd7bf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'acc92275-2337-5546-8a53-f21d8d0bd7bf'::uuid, 1, NULL, TRUE, 0, NULL, E'Robotic Surgery', E'Robotic surgery allows the entire procedure to be recorded, helping to {{1}} detailed surgical information. This creates a valuable tool for {{2}} , giving students and professionals the chance to learn from real operations. It also enables doctors to {{3}} remotely, a technique known as telesurgery.', NULL, NULL, NULL, E'1.preserve, 2.training, 3.operate', NULL, NULL),
