  ('accde19c-8ed5-5f2d-a4d0-e7a6b0a88aac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'accde19c-8ed5-5f2d-a4d0-e7a6b0a88aac'::uuid, 1, NULL, TRUE, 0, NULL, E'Climate Change', E'This is what needs to happen on climate change: the world needs to put a price on carbon emissions and let the market respond. If politicians pretend this can be done without pain, it will probably result in another five to ten years of pretending to take action.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('acd37e04-8118-561b-853a-bdb0068f4bee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'acd37e04-8118-561b-853a-bdb0068f4bee'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'fd80b9d0-e5fb-5374-b1a3-765e24b39140'::uuid, NULL, E'The beggar was laughed at by the children.', NULL, NULL, NULL),
