  ('acd5c079-cfca-5d35-80a3-1b465e26e533'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'acd5c079-cfca-5d35-80a3-1b465e26e533'::uuid, 1, NULL, TRUE, 0, NULL, E'Dead Language', E'A dead language may still be studied through recordings or writings, but it is still dead or extinct unless there are fluent speakers. Although languages have always become extinct throughout human history, they are currently dying at an accelerated rate because of globalization. Many projects are under way aimed at preventing or slowing language loss.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('acd8bbb1-9f73-5a7c-b73a-777a2215968e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'acd8bbb1-9f73-5a7c-b73a-777a2215968e'::uuid, 1, NULL, TRUE, 0, NULL, E'Hazard Assessment', E'A Hazard Assessment should be performed for work involving distillations of organic liquids and should thoroughly address issues relating to residual water and possible decomposition of the solvent in question, as well as the physical placement of the distillation apparatus and heating equipment to be employed.', NULL, NULL, NULL, NULL, NULL, NULL),
