  ('ace51ba5-5465-5b7a-98d3-6eb64cdf1efe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ace51ba5-5465-5b7a-98d3-6eb64cdf1efe'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the study of how individuals, businesses, and governments allocate resources to satisfy their wants and needs called?', '820d44f4-4ef5-5dd1-ad3f-152323e3657c'::uuid, NULL, NULL, E'Economics', NULL, NULL),
  ('aceb9eba-c637-5dfc-bb81-c58610babda4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aceb9eba-c637-5dfc-bb81-c58610babda4'::uuid, 1, NULL, TRUE, 0, NULL, E'Poor Posture', NULL, 'db2704cf-c72e-5600-b816-3896f20fb4bb'::uuid, NULL, E'Your posture, the way you hold your body when you’re sitting or standing, is the foundation for every movement your body makes, and can determine how well your body adapts to the stresses on it. These stresses can be things like carrying weight, or sitting in an awkward position. And the big one we all experience all day every day: gravity. If your posture isn’t optimal, your muscles have to work harder to keep you upright and balanced. Some muscles will become tight and inflexible. Others will be inhibited. Over time, these dysfunctional adaptations impair your body’s ability to deal with the forces on it. Poor posture inflicts extra wear and tear on your joints and ligaments, increases the likelihood of accidents, and makes some organs, like your lungs, less efficient. Researchers have linked poor posture to scoliosis, tension headaches, and back pain, though it isn’t the exclusive cause of any of them. Posture can even influence your emotional state and your sensitivity to pain. So there are a lot of reasons to aim for good posture.', NULL, NULL, NULL),
  ('acf3f59a-9ef4-5642-9b20-d4d18fade414'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'acf3f59a-9ef4-5642-9b20-d4d18fade414'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4b74f5a3-be4a-5ec1-9655-71c83c705aa7'::uuid, NULL, E'He''s passionate about the need to protect the environment.', NULL, NULL, NULL),
  ('acfae8e8-85a8-51c1-8add-fc64e0f7c930'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'acfae8e8-85a8-51c1-8add-fc64e0f7c930'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5a548801-86ab-52fc-9cfe-54c279ca3c81'::uuid, NULL, NULL, E'Students often gather in the quad for outdoor events and activities.', NULL, NULL),
