  ('ad015df9-905e-581f-b458-aa0dd1f471fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ad015df9-905e-581f-b458-aa0dd1f471fd'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5af41e0a-eaa8-53ef-b569-0dae00b5df29'::uuid, NULL, E'The campus is located in a bustling urban area.', NULL, NULL, NULL),
