  ('ad1134b8-3e7c-5552-b867-7f57609fd062'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ad1134b8-3e7c-5552-b867-7f57609fd062'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e8e2628f-554f-55be-9b3e-cb0fb098c0c3'::uuid, NULL, NULL, E'Payments can be made with either cash or credit card.', NULL, NULL),
  ('ad33642b-019a-5a12-b9bb-aeb1d5f0c3d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ad33642b-019a-5a12-b9bb-aeb1d5f0c3d3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '21e0998e-56c2-59ab-a09d-271d170ee13c'::uuid, NULL, NULL, E'Experience would be an advantage for this managerial role.', NULL, NULL),
  ('ad35537e-5bea-5751-8d55-5bdc11313a08'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ad35537e-5bea-5751-8d55-5bdc11313a08'::uuid, 1, NULL, TRUE, 0, NULL, E'Why Comedy Matters', NULL, '0a4c05d5-4b7b-5e49-a870-b9bf1d0cc25b'::uuid, NULL, E'The comic move is to guide us to a benevolent conception of people, and hence, parts of ourselves. Comedy also does a great job at reducing power imbalances. It’s hugely reassuring to see the powerful laughing at themselves. Finding oneself comical is a token of maturity; it means being able to see one’s faults without being too defensive about it. Humor often provides a mechanism where by the powerless, or at least, the less powerful, can give constructive but pointed feedback to the powerful. Monty Python was particularly focused on this task. “The Philosophers’ Football Match” mocks the great figures of intellectual history. It’s funny because we’ve been intimidated so deeply in the past by intellectual bullies, we made us feel small with our reading of Wittgenstein or Schopenhauer. And now they’re shown as being completely rubbish at football, and yet seriously involved in the game. Comedy isn’t just a bit of fun. The comic perspective is a central need of a society. It enables us to cope much better with our own follies and disappointments, our troubles around work and love, and our difficulties in enduring ourselves. Comedy is waiting to be re-framed as a central tool in a better society.', NULL, NULL, NULL),
  ('ad37665b-726a-575c-983b-90ac5eda5d91'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ad37665b-726a-575c-983b-90ac5eda5d91'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call a male sheep?', '5c9611a9-9b39-508a-a190-ef6c6c2ae557'::uuid, NULL, NULL, E'Ram', NULL, NULL),
