  ('ad704fbf-1af3-57ad-b1df-dfc6ceca5471'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'ad704fbf-1af3-57ad-b1df-dfc6ceca5471'::uuid, 1, NULL, TRUE, 0, NULL, E'New Way against Cancer', E'Leonard Seymour is preparing to launch trials of a radical new way to fight cancer, which kills tumors by infecting them with viruses like the common cold. Prof Seymour’s innovative solution is to mask the virus from the body’s immune system, effectively allowing the viruses to do what chemotherapy drugs do — spread through the blood and reach tumors. The big hurdle is to find a way to deliver viruses to tumors via the bloodstream without the body''s immune system destroying them on the way. Though several more years of trials will be needed, Prof Seymour hopes that one day it might be applied to all cancers.\n\nAccording to the text, which statement below is true?', NULL, NULL, NULL, E'The virus will be delivered by blood.', NULL, NULL),
  ('ad71d409-0b2e-5165-b0ff-06f98210970b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ad71d409-0b2e-5165-b0ff-06f98210970b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b9a92281-b2fa-5112-973a-0185347baf00'::uuid, NULL, NULL, E'Gold is very special and expensive because it''s rare and pure.', NULL, NULL),
