  ('ad736ce7-db2b-5eb7-96fd-4436ee429c53'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ad736ce7-db2b-5eb7-96fd-4436ee429c53'::uuid, 1, NULL, TRUE, 0, NULL, E'Bering Land Bridge', E'The Bering Land Bridge, a {{1}} of land that once connected Asia with North America, came into {{2}} much later than experts previously thought, but humans likely crossed not long after it formed, according to a new study. Researchers reconstructed the sea level history of the Bering Land Bridge from 46,000 years ago and found that it didn''t {{3}} until around 35,700 years ago.', NULL, NULL, NULL, E'1.stretch, 2.existence, 3.emerge', NULL, NULL),
  ('ad74e164-1b53-5cdb-a689-a4a1c0fbda97'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ad74e164-1b53-5cdb-a689-a4a1c0fbda97'::uuid, 1, NULL, TRUE, 0, NULL, E'Earthquake', E'After the violent earthquake that shook Los Angeles in 1994, earthquake scientists had good news to report: The damage and death toll could have been much worse. More than 60 people died in this earthquake. By comparison, an earthquake of similar {{1}} that shook America in 1998 claimed 25,000 victims.\nInjuries and deaths were {{2}} less in Los Angeles because the quake occurred at 4:31 a.m. on a holiday, when traffic was light on the city''s highway. In addition, {{3}} made to the construction codes in Los Angeles during the last 20 years have strengthened the city''s buildings and highways, making them more {{4}} to quakes.', NULL, NULL, NULL, E'1.intensity, 2.relatively, 3.changes, 4.resistant', NULL, NULL),
  ('ad79dbd5-cf8d-5ea0-8640-fb0e1bcf74b1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'ad79dbd5-cf8d-5ea0-8640-fb0e1bcf74b1'::uuid, 1, NULL, TRUE, 0, NULL, E'LinkedIn', NULL, NULL, NULL, NULL, E'2, 4, 1, 3', NULL, NULL),
