  ('ad83c435-7f9c-5af2-8c25-2a17fe0f8648'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ad83c435-7f9c-5af2-8c25-2a17fe0f8648'::uuid, 1, NULL, TRUE, 0, NULL, E'Fish in Distress', E'Our field teams have come across fish in distress or even eels stranded and it is simply that the water''s got too hot. Often dissolved oxygen concentrations go down as water temperature increases and animals may seek refuge outside the water, or in fact they may be stranded if the water''s evaporating very quickly.', NULL, NULL, NULL, NULL, NULL, NULL),
