  ('adaceefd-9838-584b-bb4d-ffe60aad10bf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'adaceefd-9838-584b-bb4d-ffe60aad10bf'::uuid, 1, NULL, TRUE, 0, NULL, E'Flood Control', E'We''ve spent a lot of money over the last seventy years on flood control, and it''s protected millions of people and has saved us billions of dollars. We''ve built dams to hold back the waters. We''ve built levees to keep the water off the people, and we''ve raised the ones that were originally started in seventeen eighteen.', NULL, NULL, NULL, NULL, NULL, NULL),
