  ('adc7f89a-8ff6-5062-995a-8d6f6cae342d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'adc7f89a-8ff6-5062-995a-8d6f6cae342d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '1c3416b1-f43d-5ae1-94d0-ea6e28d454a3'::uuid, NULL, E'We need to strengthen our skills to think creatively.', NULL, NULL, NULL),
  ('add88e97-a1aa-5666-bdfd-830d60c8aadc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'add88e97-a1aa-5666-bdfd-830d60c8aadc'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bc4bcfb7-c291-58f7-8f28-ffb33e3a2404'::uuid, NULL, E'I will make this machine work even if I have to stay up all night.', NULL, NULL, NULL),
  ('ade3350f-33ee-52d7-a395-5a4b5417913b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ade3350f-33ee-52d7-a395-5a4b5417913b'::uuid, 1, NULL, TRUE, 0, NULL, E'Smartwatches', E'More than half of all Americans carry smartphones. Smartwatches and smartglasses may not be far behind. What''s not all that smart are the rigid {{1}} that power our gadgets. But some may soon be replaced by ultra-thin, flexible batteries, sewn right into your clothes.\nResearchers built a prototype out of conductive, nickel-coated {{2}} fabric. They applied lithium compounds to create the anode and cathode, and separated them with a spandex-like material. The {{3}} battery was just half a millimeter thick, with a capacity of 510 milliampere-hours per cubic inch—about a quarter that of the battery in an iPhone 5. And the tighter the knit, the higher the capacity.\nOf course, fabric {{4}} . But this battery can too. Even after being folded 5,500 times, the battery kept trucking. Thin foil batteries, on the other hand, took just 70 folds to become really foiled. The findings appear in the journal Nano Letters.\nYou don''t even have to disrobe to charge this {{5}} battery. Researchers tacked flexible solar cells to it, so it can charge on the go. Might be just the thing to make polyester current again.', NULL, NULL, NULL, E'1.batteries, 2.polyester, 3.finished, 4.wrinkles, 5.wearable', NULL, NULL),
  ('ade56545-f8ba-5b52-9bc5-32bcdd83c7d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ade56545-f8ba-5b52-9bc5-32bcdd83c7d7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6648098f-8931-5837-b4ce-53f39788b311'::uuid, NULL, NULL, E'Major restoration work on this site will begin in May.', NULL, NULL),
  ('ade74a18-4cf5-5b60-a75b-d87f7d51957d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ade74a18-4cf5-5b60-a75b-d87f7d51957d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '179893fe-a037-5141-b35b-fb73f86f1ac0'::uuid, NULL, E'We have a range of on-campus accommodation available to students.', NULL, NULL, NULL),
