  ('adf4ade1-389d-518d-bf10-bc5047acb647'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'adf4ade1-389d-518d-bf10-bc5047acb647'::uuid, 1, NULL, TRUE, 0, NULL, E'Menopause Data', E'“Despite the fact that every woman goes through menopause, there’s not enough research,” Anna says. “Our scientific understanding of menopause is vastly limited due to the lack of data. Menopausal changes are correlated with women’s cardiovascular, cognitive, and overall health, so a database will allow us to better understand these connections.”', NULL, NULL, NULL, NULL, NULL, NULL),
  ('adfc551d-b142-540a-a5dc-c598d5273d2e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'adfc551d-b142-540a-a5dc-c598d5273d2e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4f063dca-2f8a-5b3a-a4a1-941f703e2393'::uuid, NULL, NULL, E'Your advisor must approve your application before submitting your dissertation.', NULL, NULL),
  ('adfe375f-485f-50ac-8e7d-00f1d2b076fa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'adfe375f-485f-50ac-8e7d-00f1d2b076fa'::uuid, 1, NULL, TRUE, 0, NULL, E'Financial Literacy', NULL, '291b6b58-2baf-5ee9-94cb-efabaa7c5fd2'::uuid, NULL, E'Financial literacy is a vital skill that empowers us to make wise decisions with our money, crucial for our time in college and beyond. It is the compass that guides us through a sea of financial decisions, from student loans to budgeting for daily expenses. Firstly, understanding the basics of budgeting can prevent the common pitfall of overspending. It teaches us to differentiate between wants and needs, ensuring that our financial resources support our academic goals and well-being. A study by the National Financial Educators Council highlighted that college students who adhere to a budget experience less financial stress. Secondly, knowledge of saving and investing places us on the path to long-term security. By grasping the power of compound interest and the importance of saving early, we can plan for future goals, such as further education or starting a business. In conclusion, financial literacy is not just about numbers; it''s about making informed choices that pave the way for a secure and prosperous future.', NULL, NULL, NULL),
  ('ae09df91-a7db-5b62-bb02-d9f948d1aac3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ae09df91-a7db-5b62-bb02-d9f948d1aac3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c6d7d1a0-d6e8-5b2f-b450-1df5c9f72d6a'::uuid, NULL, E'Children need books in their own language with settings that reflect their lives.', NULL, NULL, NULL),
  ('ae0b06c7-afc6-54f4-9795-21f5942b4fa7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ae0b06c7-afc6-54f4-9795-21f5942b4fa7'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8634dc2d-28a3-5c16-abdc-e56cda74845d'::uuid, NULL, E'All undergraduate students should participate in the seminar.', NULL, NULL, NULL),
  ('ae124e4c-3ee0-517a-88a4-6d43abafedf9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ae124e4c-3ee0-517a-88a4-6d43abafedf9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '403aa7f1-4f08-5189-aefb-9f2913f57080'::uuid, NULL, NULL, E'Taking a campus tour offers a comprehensive preview of learning environments.', NULL, NULL),
  ('ae1d58b9-6995-51b9-b036-c92273ba68c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ae1d58b9-6995-51b9-b036-c92273ba68c4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'bd36ab36-f08d-5179-b8ff-5b4702758cfe'::uuid, NULL, NULL, E'The assignment requires us to critically analyse and evaluate relevant technology.', NULL, NULL),
  ('ae1d8920-ee57-59e7-951c-2dc5bb4f6729'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ae1d8920-ee57-59e7-951c-2dc5bb4f6729'::uuid, 1, NULL, TRUE, 0, NULL, E'Political Landscape', E'The political landscape of ancient Egypt, {{1}} by the central role of the Pharaoh, was a unique combination of theocratic and bureaucratic {{2}} . The Pharaoh was both a political leader and a divine {{3}} , centralizing power and religious authority. This system fostered a stable and organized society that could undertake monumental architectural projects, like the {{4}} of the pyramids, reflecting the strength and organization of the Egyptian state.', NULL, NULL, NULL, E'1.characterized, 2.elements, 3.figure, 4.construction', NULL, NULL),
  ('ae1da52a-c71b-5947-a491-ff7b52d9c392'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ae1da52a-c71b-5947-a491-ff7b52d9c392'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call the daughter of your sister or brother?', 'b4d0d2b1-4d5b-50e9-8d10-a62f6cafd470'::uuid, NULL, NULL, E'Niece', NULL, NULL),
  ('ae1ef998-2e66-529b-8866-e6195e5524db'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ae1ef998-2e66-529b-8866-e6195e5524db'::uuid, 1, NULL, TRUE, 0, NULL, E'Prosecutors', NULL, 'cec0c8cd-7e9c-59b2-bf5f-e6dc81e04372'::uuid, NULL, E'As an individual caught selling a large quantity of drugs in my late teens, I knew firsthand the power of opportunity as opposed to the wrath of the criminal justice system. Along the way, with the help and guidance of my district attorney, my supervisor and judges, I learned the power of the prosecutor to change lives instead of ruining them. And that’s how we do it in Boston. We helped a woman who was arrested for stealing groceries to feed her kids get a job. Instead of putting an abused teenager in adult jail for punching another teenager, we secured mental health treatment and community supervision. A runaway girl who was arrested for prostituting, to survive on the streets, needed a safe place to live and grow — something we could help her with. I even helped a young man who was so afraid of the older gang kids showing up after school, that one morning instead of a lunchbox into his backpack, he put a loaded 9-millimeter. We would spend our time that we’d normally take prepping our cases for months and months for trial down the road by coming up with real solutions to the problems as they presented. Which is the better way to spend our time? How would you prefer your prosecutors to spend theirs? Why are we spending 80 billion dollars on a prison industry that we know is failing, when we could take that money and reallocate it into education, into mental health treatment, into substance abuse treatment and to community investment so we can develop our neighborhoods?', NULL, NULL, NULL),
  ('ae20ff02-ff2a-56c8-98a0-09581fc0efee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ae20ff02-ff2a-56c8-98a0-09581fc0efee'::uuid, 1, NULL, TRUE, 0, NULL, E'Orchestras', E'The advantage of the great European and American orchestras is that they were able to establish their iconic status in an age when their identity could become entrenched, there was less competition and it was easier to create a brand. Not only did they have the best halls, they attracted the best musicians, who tended to stay put.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ae230e6b-3742-51f9-a8eb-bd1e1555649d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ae230e6b-3742-51f9-a8eb-bd1e1555649d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd9334953-6679-5620-a6d5-78f74810de1e'::uuid, NULL, NULL, E'This software company designs and creates new products.', NULL, NULL),
  ('ae2a27e1-70ab-5e1f-9e57-600fb95d83d0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ae2a27e1-70ab-5e1f-9e57-600fb95d83d0'::uuid, 1, NULL, TRUE, 0, NULL, E'Historical Monuments', E'Historical monuments such as the Great Wall of China, the Pyramids of Giza, and the Colosseum in Rome are symbols of human achievement and cultural heritage. They serve as reminders of our shared history and cultural identity. By preserving these monuments, we can ensure that future generations can appreciate and learn from their historical significance.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ae2ab10e-1310-59f2-ae4b-13b7f6a3243f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ae2ab10e-1310-59f2-ae4b-13b7f6a3243f'::uuid, 1, NULL, TRUE, 0, NULL, E'Take A Break', E'''Take A Break'' is a program that encourages teens who have signed up for it to log off after they have been on the platform for a certain amount of time. Starting Tuesday, the feature is available to any users between the ages of thirteen and eighteen based on how they self-reported when they signed up for Instagram.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ae2b1deb-bb6b-5011-870d-cc4e400a43c7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ae2b1deb-bb6b-5011-870d-cc4e400a43c7'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the people whose job is to make clothes for individual customers?', '35a953ed-2d13-57fd-ae85-07fcac113a33'::uuid, NULL, NULL, E'Dressmaker / tailor', NULL, NULL),
  ('ae3045dd-0d1a-5b11-bc4f-8216ae37843d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ae3045dd-0d1a-5b11-bc4f-8216ae37843d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '09ba39e0-cdf0-571a-9974-6f07197413d8'::uuid, NULL, NULL, E'The coffee house has a special student discount throughout the week.', NULL, NULL),
  ('ae331243-bf22-550d-a75d-e8b650eae39c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'ae331243-bf22-550d-a75d-e8b650eae39c'::uuid, 1, NULL, TRUE, 0, NULL, E'Classmate or Parent', E'Classmates have a more important influence than parents on a child’s success in school. To what extent do you agree with this statement?', NULL, NULL, E'The influence of classmates and parents on a child''s success in school is a topic of much debate. While some argue that classmates have a greater impact on a child''s academic performance, I believe that parents play a more important role in their child''s education. This essay will argue that parents provide emotional and financial support, have a deeper understanding of their child''s strengths and weaknesses, and have a longer-term perspective on their child''s education and future.\nParents provide emotional and financial support, which is crucial for a child''s success in school. Emotional support can come in the form of encouragement, motivation, and guidance. Financial support can include paying for tuition, books, and other educational resources. Without this support, children may struggle to stay motivated and engaged in their studies.\nParents have a deeper understanding of their child''s strengths, weaknesses, and learning style. This allows them to provide more personalized support, such as tutoring or extra help with homework. Additionally, parents can work with teachers to create an individualized learning plan for their child, which can help them to succeed academically.\nIn conclusion, I believe that parents have a more important influence than classmates on a child''s success in school. Parents provide emotional and financial support, have a deeper understanding of their child''s strengths and weaknesses, and have a longer-term perspective on their child''s education and future. While classmates can provide academic and social support, parents play a crucial role in their child''s education and overall well-being.', NULL, 200, 300),
  ('ae3342e2-facb-5f8a-a310-7ea2ded87319'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ae3342e2-facb-5f8a-a310-7ea2ded87319'::uuid, 1, NULL, TRUE, 0, NULL, E'Continuous Development', E'Continuous development views development as a {{1}} process, gradually improving on existing skills. With this type of development, there is a gradual change. In {{2}} ,theorists who view development as discontinuous believe that development takes place in unique stages and that it occurs at {{3}} times or ages. With this type of development, the change is more sudden, such as an infant’s ability to {{4}} awareness of object permanence.', NULL, NULL, NULL, E'1.cumulative, 2.contrast, 3.specific, 4.demonstrate', NULL, NULL),
  ('ae38aea0-1854-53f3-b5da-3557db78b1aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ae38aea0-1854-53f3-b5da-3557db78b1aa'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What device do you use when the batteries of your mobile phones are running down?', 'cb7a7455-0efb-575a-b160-ebde5f7205e1'::uuid, NULL, NULL, E'Charger', NULL, NULL),
  ('ae443684-69bc-5e08-846c-f29f0fe23cb7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ae443684-69bc-5e08-846c-f29f0fe23cb7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '97266dd1-8252-56c9-bcc1-76e4c3c2fa4b'::uuid, NULL, NULL, E'By collaborating, we can create statues that are both imposing and magnificent.', NULL, NULL),
  ('ae4582a2-8ab9-512b-98af-165f8179f060'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ae4582a2-8ab9-512b-98af-165f8179f060'::uuid, 1, NULL, TRUE, 0, NULL, E'SMW', E'Psychology is a relatively new science. Like other sciences, psychology must be able to state laws. A law is a way of organizing knowledge about something so that we can make predictions. When enough knowledge is gained about a subject, a scientist can state precisely what will happen under certain conditions. We experimental psychologists are interested in developing laws about human behavior, so we''ll be able to understand and predict what people do and why they do it. Of course, to develop laws about human behavior, we must assume there''s some regularity to it. We can''t be psychologists without making the assumption the behaviour follows.\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '3994ef65-35e2-5f15-a06f-fe78ff326828'::uuid, NULL, NULL, E'certain patterns', NULL, NULL),
  ('ae48a3dd-e2b8-5cbd-8b4d-3c6e90d1b6c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ae48a3dd-e2b8-5cbd-8b4d-3c6e90d1b6c8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What unit do we use to measure temperature?', '8fd4b451-a09f-50dd-bb77-d484f9d26fdd'::uuid, NULL, NULL, E'Degree Celsius / degree Fahrenheit / centigrade', NULL, NULL),
