  ('ae56c553-a239-50c9-b9ad-d31752c72abc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ae56c553-a239-50c9-b9ad-d31752c72abc'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2b3648ec-233b-5445-b880-9e09b1233769'::uuid, NULL, E'Few people now are skeptical about alternative power sources such as wind power.', NULL, NULL, NULL),
  ('ae58ded2-57eb-5f48-b90e-787e0b4dcf17'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ae58ded2-57eb-5f48-b90e-787e0b4dcf17'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How many sides does an octagon have?', '767b0d5a-37c8-5fd8-b0b3-c23e41d7da30'::uuid, NULL, NULL, E'Eight', NULL, NULL),
  ('ae5b669e-2e8d-521d-aa2a-a0c7a2270681'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ae5b669e-2e8d-521d-aa2a-a0c7a2270681'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2a00f695-3502-5433-92ed-42fd10f86342'::uuid, NULL, NULL, E'Guided by a current student, you can explore our campus facilities.', NULL, NULL),
  ('ae64cb13-62d5-57d7-be0d-04346c4af90a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'ae64cb13-62d5-57d7-be0d-04346c4af90a'::uuid, 1, NULL, TRUE, 0, NULL, E'Space Lab', E'An experiment conducted aboard Space Lab in 1983 was the first attempt to grow protein crystals in the low-gravity environment of space. That experiment is still cited as evidence that growing crystals in microgravity can increase crystal size: the authors reported that they grew lysozyme protein crystals 1,000 times larger than crystals grown in the same device on Earth. Unfortunately, the authors did not point out that their crystals were no larger than the average crystal grown using other, more standard techniques in an Earth laboratory. No research has yet produced results that could justify the enormous costs of producing crystals on a large scale in space. To get an unbiased view of the usefulness of microgravity crystal growth, crystals grown in space must be compared with the best crystals that have been grown with standard techniques on Earth. Given the great expense of conducting such experiments with proper controls, and the limited promise of experiments performed thus far, it is questionable whether further experiments in this area should even be conducted.\n\nAccording to the passage, which of the following is true about the Space Lab experiment conducted in 1983?', NULL, NULL, NULL, E'Its results are still considered by some to be evidence for the advantages of microgravity protein crystal growth.', NULL, NULL),
  ('ae6ad1ce-dfc4-594f-87d1-21a2e55f9db7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ae6ad1ce-dfc4-594f-87d1-21a2e55f9db7'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '16c87bb1-7591-5ba9-b280-7fdd7cd536be'::uuid, NULL, E'Students must observe lab safety regulations at all times.', NULL, NULL, NULL),
