  ('ae8f6a7c-6525-52c8-a205-47ce2c82e0ff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ae8f6a7c-6525-52c8-a205-47ce2c82e0ff'::uuid, 1, NULL, TRUE, 0, NULL, E'Fresh Water', E'Everybody needs fresh water. {{1}} water people, animals and plants cannot live. Although a few plants and animals can make do with saltwater, all humans need a constant supply of fresh water to stay {{2}} and healthy. Of the total supply of water on the Earth, only about 3% of it is fresh, most of that is stored as ice snow at the poles, or is so {{3}} under the surface of the Earth that we cannot get to it. Despite so much of the water being out of reach, we still have a million cubic miles of it that we {{4}} use. That''s about 4, 300,000 cubic kilometers of freshwater to share out between most of the plants, animals & people on the planet.', NULL, NULL, NULL, E'1.Without, 2.fit, 3.deep, 4.can', NULL, NULL),
  ('ae934d2d-6f03-5246-a23f-4256b429adc8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ae934d2d-6f03-5246-a23f-4256b429adc8'::uuid, 1, NULL, TRUE, 0, NULL, E'CPG', E'In animals, movement is coordinated by a cluster of neurons in the spinal cord called the Central Pattern Generator (CPG). This produces signals that drive muscles to {{1}} rhythmically in a way that produces running or walking, depending on the {{2}} of pulses. A simple signal from the brain instructs the CPG to switch between different {{3}} , such as going from a standstill to walking.', NULL, NULL, NULL, E'1.contract, 2.pattern, 3.modes', NULL, NULL),
