  ('aeb8553f-1f26-5175-a68d-7401d04e112e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aeb8553f-1f26-5175-a68d-7401d04e112e'::uuid, 1, NULL, TRUE, 0, NULL, E'Marketing Management', E'For any marketing course that requires the development of a marketing plan, such as Marketing Management, Marketing Strategy and Segmentation Support Marketing, this is the only planning handbook that guides students through the step-by-step creation of a customized marketing plan while offering commercial software to aid in the process.', NULL, NULL, NULL, NULL, NULL, NULL),
