  ('aec732fc-6f8d-5cb7-8e03-7316f3e97c0d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aec732fc-6f8d-5cb7-8e03-7316f3e97c0d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e5f3d97e-a40a-5916-9678-c9e0ad264897'::uuid, NULL, E'During a successful business career, she accumulated a great amount of wealth.', NULL, NULL, NULL),
  ('aecac1e6-2ce2-5fc0-8317-9e831e7a13a1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aecac1e6-2ce2-5fc0-8317-9e831e7a13a1'::uuid, 1, NULL, TRUE, 0, NULL, E'Cognitive Revolution', NULL, '9de249c3-ffef-58d1-a755-5bc3e29dc6f9'::uuid, NULL, E'I''m Steve Pinker and I''m Harvard college professor and Johnstone family professor, Harvard department of Psychology. The Cognitive Revolution which took place at Harvard was the start after modern scientific study of the mind. Who study something like the mind you like to think that you''re a scientist, you face the immediate problem of what we do with these things called mental contents, thoughts, emotions, images, plans, rules, you can''t see them, you can''t taste them, then you can''t feel them. If you''re a scientist you are supposed to be studying things that you can see measure and manipulate, how do you even begin with a science of mind. Well, the answer is the dominated psychology in the middle part of the 20th century where it just to give up all talks of mental contents. This is the school of behaviorism and came to take over American psychology until the early 1950s when a number of scholars with ties to Harvard started to rethink that whole idea when we talk about how computers work you can''t get around computing internal states to them. Computers have memories, they have goal states, they execute plans and if you could do that, about a hunk of metal and you are not being unscientific why should be on the scientific to say those things about a human being. The result was called Cognitive Science included both experimental psychology, people who study other humans in the lab with linguistics, including the famous theories of linguist Noam Chomsky who was here at Harvard as a society fellow, a computer science and artificial intelligence and later neuroscience.', NULL, NULL, NULL),
  ('aecb0f40-e093-5676-ae8e-ed8674da9c17'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'aecb0f40-e093-5676-ae8e-ed8674da9c17'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'dff7fd21-7dee-5fe9-abfe-153c4801611e'::uuid, NULL, NULL, E'Frequently observed attributes tend to interpret the problem in comparable manners.', NULL, NULL),
  ('aecfca90-0de9-5f1b-9155-acc58ddaf1e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aecfca90-0de9-5f1b-9155-acc58ddaf1e9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9e208003-e06d-5b3e-b1b5-92b892d91123'::uuid, NULL, E'His understanding of the language is very rudimentary.', NULL, NULL, NULL),
  ('aee03a67-903b-5159-8795-c1d0ce178a14'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aee03a67-903b-5159-8795-c1d0ce178a14'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which tool with narrow pointed teeth do we use to make our hair neat?', 'ee07e6cd-5f67-58ff-921a-730c66dbd8f8'::uuid, NULL, NULL, E'Comb', NULL, NULL),
  ('aee07d6f-1571-5180-aae9-99a673e749cd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'aee07d6f-1571-5180-aae9-99a673e749cd'::uuid, 1, NULL, TRUE, 0, NULL, E'Maya Patel', E'Dr. Maya Patel stumbled upon a curious statistic while researching water scarcity: a disproportionate number of the world''s poorest nations shared one defining {{1}} - aridity. This sparked a burning question within her: could the limited availability of water be a missing {{2}} in the complex puzzle of global economic disparity? Delving into the research, Dr. Patel and Dr. David Singh began to unravel this intricate relationship. Their study revealed a striking correlation: countries receiving less than 500 millimeters of annual rainfall consistently struggled with poverty, while those {{3}} this threshold displayed greater economic prosperity. The team identified two key mechanisms {{4}} aridity hampered economic growth. Firstly, limited water availability severely constrained agricultural productivity, hindering the development of a robust food system and jeopardizing food security. Secondly, aridity amplified the impact of disease, as stagnant water bodies became breeding {{5}} for pathogens, leading to higher rates of illness and decreased workforce participation. This vicious cycle of limited resources and poor health created a significant barrier to economic development.', NULL, NULL, NULL, E'1.characteristic, 2.piece, 3.exceeding, 4.through which, 5.grounds', NULL, NULL),
  ('aee31c2e-b0cb-588b-abf6-959c19e58497'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aee31c2e-b0cb-588b-abf6-959c19e58497'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a1758a2b-0ec5-5db1-9a6f-5c0ffd5804e7'::uuid, NULL, E'Charles used to take the bus, but now his friend drives him.', NULL, NULL, NULL),
  ('aee3639a-d07c-520b-9e80-4b38aa529cdf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'aee3639a-d07c-520b-9e80-4b38aa529cdf'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'cfb0b60e-9e45-5cce-8245-b56d7a7217e5'::uuid, NULL, NULL, E'More financial support is available for students who need it.', NULL, NULL),
  ('aee5e1bb-1ba0-516c-b92a-f1b56f602fbd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'aee5e1bb-1ba0-516c-b92a-f1b56f602fbd'::uuid, 1, NULL, TRUE, 0, NULL, E'Croatia’s New Currency', E'All that changed on January 1 when Croatia joined the Eurozone, {{1}} its historic kuna with the euro. Euro banknotes and coins are now {{2}} in the country, with around 70% of ATMs in the country already distributing euros rather than kuna. Also, Croatia joined the Schengen area – the {{3}} of 26 countries that has done away with border checks within Europe, making it the largest border-free area in the world.', NULL, NULL, NULL, E'1.replacing, 2.circulating, 3.bloc', NULL, NULL),
  ('aee951e1-9d65-521e-aaab-e107b005322b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'aee951e1-9d65-521e-aaab-e107b005322b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f917f2e3-2a06-536a-ae18-efa4526060f4'::uuid, NULL, NULL, E'Doctorate papers are set up a lot like other research articles.', NULL, NULL),
  ('aeee3e85-352b-566b-ada8-99525a9b2ad7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'aeee3e85-352b-566b-ada8-99525a9b2ad7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'eeb90b7a-a587-5dcd-a14a-e079f0a6d22d'::uuid, NULL, NULL, E'Most theories shared similarities, but a minority of critics disagreed.', NULL, NULL),
  ('aeee48ad-0d18-5c5f-bcd2-628e0da87699'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aeee48ad-0d18-5c5f-bcd2-628e0da87699'::uuid, 1, NULL, TRUE, 0, NULL, E'Placebo', E'If a doctor expects a treatment to be successful, a patient may experience less pain and have better outcomes, according to a new study. The findings reveal how social interactions between hypothetical healthcare providers and patients have the power to influence how patients perceive the effectiveness of a treatment, even when it is a placebo.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('aeef8ae8-215d-5416-a78e-5c844cf8b37e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aeef8ae8-215d-5416-a78e-5c844cf8b37e'::uuid, 1, NULL, TRUE, 0, NULL, E'Tidal Energy', E'Tidal energy, also known as tidal power, is a renewable source of energy and a form of hydropower used to generate electricity from the energy of the tides. Though not currently widely utilized, due to high costs and limited availability, it can be called the energy resource of the future given the current rate of depletion of energy resources.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('aef0602f-0928-55cc-bdcd-0e406853e0ba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aef0602f-0928-55cc-bdcd-0e406853e0ba'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the conservation of non-renewable energy?', 'cd0ede1e-b572-5206-8def-28600ee6b368'::uuid, NULL, NULL, E'Reuse / recycling', NULL, NULL),
  ('aef52af1-69fb-5e00-bcbe-f253fc2cf0ac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aef52af1-69fb-5e00-bcbe-f253fc2cf0ac'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which city is known as the city of seven hills?', 'd6b7696c-c80c-5ac5-97a5-895dfae7a759'::uuid, NULL, NULL, E'Rome', NULL, NULL),
  ('aef559d2-5488-5c5d-b855-1a2bcf56c18a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aef559d2-5488-5c5d-b855-1a2bcf56c18a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the word for a period of one hundred years?', 'd1b6e0a2-a2b8-57a0-8c32-04e6d97ff7d0'::uuid, NULL, NULL, E'Century', NULL, NULL),
  ('aef7cc8d-73ce-574d-896d-4a02f906230f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'aef7cc8d-73ce-574d-896d-4a02f906230f'::uuid, 1, NULL, TRUE, 0, NULL, E'Arts or Technology Research', E'Governments should not put too much attention on arts, such as theaters. Instead, they should allocate more funds to areas of concern, such as the technology research. Do you agree with this opinion or not? Use your own experience to support your idea.', NULL, NULL, E'Governments around the world are faced with the challenge of allocating limited resources to different areas of concern. Some argue that the arts, such as theaters, do not warrant significant attention from governments and that resources should instead be directed towards technology research. However, I believe that the arts are a vital component of society and should not be ignored by governments.\nThe arts, such as theaters, play an important role in preserving culture and promoting social cohesion. Throughout history, the arts have been used to express ideas and emotions that are difficult to convey through other means. Theaters, in particular, provide a platform for actors, directors, and writers to showcase their talents and bring stories to life. These stories often reflect the values and beliefs of a particular culture or society and can help to foster a sense of identity and belonging among individuals. By investing in the arts, governments can help to preserve cultural heritage and promote social cohesion.\nThe arts also provide a means of expression for individuals and can help to foster creativity and critical thinking. Artistic endeavors require individuals to think outside the box and challenge conventional ways of thinking. This type of thinking is essential for innovation and progress in all areas of society, including technology research. In fact, many technological advancements have been inspired by artistic endeavors. By investing in the arts, governments can help to foster creativity and critical thinking, which can lead to new ideas and innovations.\nIn conclusion, I believe that governments should not overlook the arts, such as theaters, when allocating resources. The arts play an important role in preserving culture, promoting social cohesion, and fostering creativity and critical thinking.', NULL, 200, 300),
  ('aef822cc-004e-56e3-898a-56cf95f6094f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aef822cc-004e-56e3-898a-56cf95f6094f'::uuid, 1, NULL, TRUE, 0, NULL, E'Upconversion', E'Significant progress has been made towards achieving photochemical upconversion in a solid state, bringing us one step closer to realizing a breakthrough in various fields such as renewable energy, water purification, and advanced healthcare. This groundbreaking technique holds the potential to unlock vital innovations that can revolutionize the way we harness and utilize energy.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('aefa4f9f-5e57-530c-91a4-571719e2e399'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'aefa4f9f-5e57-530c-91a4-571719e2e399'::uuid, 1, NULL, TRUE, 0, NULL, E'Struck in Quicksand', NULL, '72a11f59-6234-5a69-8e83-33b1eef97e13'::uuid, NULL, E'But if not trying to escape, and trying too hard, are both bad choices, then what are you supposed to do if you get stuck in quicksand? The trick is to stay calm. First, get rid of any heavy items that you’re wearing or carrying, as they’ll only drag you deeper. Then, try to lean as far back as you can to create more space for yourself. Water will come in and fill the gaps you create, which will make it easier for you to move and pull your body towards the surface. If you can, grab a stick and wedge it underneath your back; this will help to increase your leverage. Hopefully, you’ll get help from emergency services. But if not, you can use these tips to get out on your own. It will be a long and exhausting process since, just to free your foot from a puddle of quicksand, moving at a rate of one centimeter per second, it would require the same amount of force as it does to lift a small car. And once you’re free, you’ll probably be in a lot of pain. With all that pressure from the densely packed sand, you might emerge in the quicksand with permament nerve damage, or without a leg. If you do manage to come out in one piece, well, maybe tread a little more carefully in the future. But don’t let this one sucky experience keep you from another adventure. Put your best foot forward, and take a walk on the wild side.', NULL, NULL, NULL),
  ('af05366b-ff7c-5608-a7d4-d588426e9d10'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'af05366b-ff7c-5608-a7d4-d588426e9d10'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the mammal known for carrying its babies in a pouch?', '20a74797-5be7-59f0-8f33-83c00c7500d7'::uuid, NULL, NULL, E'Marsupial', NULL, NULL),
