  ('af1f55f2-af0c-5fc4-9b4d-b18e25bcd246'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'af1f55f2-af0c-5fc4-9b4d-b18e25bcd246'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e5833f62-b23b-50b5-9816-526a0cf4ef4c'::uuid, NULL, E'What do I need to do to start a bank account?', NULL, NULL, NULL),
  ('af236238-d32b-5f37-99e3-fe81a3f016c7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'af236238-d32b-5f37-99e3-fe81a3f016c7'::uuid, 1, NULL, TRUE, 0, NULL, E'Brittle Stars', E'Relatives of starfish, brittle stars spend most of their time hiding under rocks and crevices in the ocean or burrowing in the sand. These shy marine creatures have no brain to speak of -- just nerve cords running down each of their five wiggly arms, which join to form a nerve ring near their mouth.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('af243b72-13f9-5851-85bd-e02b5ad864a3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'af243b72-13f9-5851-85bd-e02b5ad864a3'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which country is both in Europe and Asia?', '2afeb28e-aa94-5e00-bcf5-2abea56de1a4'::uuid, NULL, NULL, E'Turkey', NULL, NULL),
  ('af26105e-52dc-57fd-b4c5-c69490e16366'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'af26105e-52dc-57fd-b4c5-c69490e16366'::uuid, 1, NULL, TRUE, 0, NULL, E'Cooking', E'Cooking, at its {{1}} , is an edible science, where chefs become akin to chemists, experimenting with ingredients and techniques. Each recipe is a hypothesis, each method a trial, and the dish {{2}} is the result of careful measurement and timing. But what makes cooking a science {{3}} pursuing is the joy and satisfaction it brings to both the cook and the eater. Cooking is a science that feeds not only the body, but also the mind and the {{4}} .', NULL, NULL, NULL, E'1.core, 2.served, 3.worth, 4.soul', NULL, NULL),
  ('af2a2302-224a-537e-8a74-7205122d264b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'af2a2302-224a-537e-8a74-7205122d264b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f65b4972-92ce-5260-a02d-e8ce3fbe1cd8'::uuid, NULL, E'You may let us know what projects interest you the most.', NULL, NULL, NULL),
  ('af2bfcab-2a2c-533a-a29b-b1cd721af476'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'af2bfcab-2a2c-533a-a29b-b1cd721af476'::uuid, 1, NULL, TRUE, 0, NULL, E'Anti-HIV Program', NULL, '8eb093e7-a8b3-5653-9470-f0a9d85d7369'::uuid, NULL, E'In India, a lot of people are working as community service workers.\nQuarterly meetings are held in order to provide training and consultation to them, and thus they can understand how to prevent diseases from spreading throughout the communities, such as HIV, which is difficult to be controlled.\nSuch precaution knowledge is taught by professionals from large hospitals and organizations.\nBut in some cities, large consultation is not suitable because it is hard for target groups to meet, who live in remote areas.\nTo deliver training to them, professional teams have to go across rivers.', NULL, NULL, NULL),
  ('af2f2a85-f746-54ce-8f0d-942e28182761'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'af2f2a85-f746-54ce-8f0d-942e28182761'::uuid, 1, NULL, TRUE, 0, NULL, E'Sexual Infections', E'Roughly one million sexually transmitted infections are exchanged each day. If untreated, they can lead to cervical cancer, pelvic inflammatory disease and infertility. However, people are often reluctant to ask their doctors to test for such infections, so Eve Medical in Toronto developed a kit for women to screen themselves.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('af31edb3-0f4a-5c21-b6b4-7941a6703dc4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'af31edb3-0f4a-5c21-b6b4-7941a6703dc4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9195822a-658b-52cc-a401-cc190f4573f5'::uuid, NULL, NULL, E'When writing an essay, consider different views of the subject.', NULL, NULL),
  ('af34b4e6-0085-5725-ab5b-8ff1e466d2ce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'af34b4e6-0085-5725-ab5b-8ff1e466d2ce'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9598b9f7-949a-5b5e-b9b0-2e5c162efe44'::uuid, NULL, NULL, E'Your agent will collect commission for each house they sell.', NULL, NULL),
  ('af36e56e-bc9f-5a08-a33d-64de8d0ccd95'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'af36e56e-bc9f-5a08-a33d-64de8d0ccd95'::uuid, 1, NULL, TRUE, 0, NULL, E'Environmental Awareness', E'As consumers become more environmentally aware, studies have shown a rising preference for sustainable products. This {{1}} is especially strong among millennials, who are increasingly interested in how products are made. They''re looking for brands that are open about their manufacturing processes, care for the environment, and {{2}} social responsibility seriously. Several fashion companies are responding to this trend by adopting ethical practices. These brands are setting themselves apart {{3}} fast fashion companies by promoting their eco-friendly credentials, which is attracting a growing number of customers, particularly in urban areas. Predictions suggest that by 2025, products made in this ethical way could make up to 40% of the market in clothing and footwear. This is a {{4}} change from the current dominance of mass-produced items.', NULL, NULL, NULL, E'1.trend, 2.take, 3.from, 4.significant', NULL, NULL),
  ('af3a9c47-a108-5c46-a75b-8dca298eaddb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'af3a9c47-a108-5c46-a75b-8dca298eaddb'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f79022b1-f8b4-54d1-8113-a4060bb5c424'::uuid, NULL, E'Campus safety is a top priority for universities across the country.', NULL, NULL, NULL),
  ('af3e12de-bc76-5d7f-882f-d0ffd8d1e611'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'af3e12de-bc76-5d7f-882f-d0ffd8d1e611'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '882d3899-1aaa-5f85-859b-2168fb77dca5'::uuid, NULL, E'We don''t have enough evidence to draw conclusions.', NULL, NULL, NULL),
  ('af41b727-f0d5-5db3-94d9-c9ef67d91686'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'HIGHLIGHT_CORRECT_SUMMARY', E'HIGHLIGHT_CORRECT_SUMMARY', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'af41b727-f0d5-5db3-94d9-c9ef67d91686'::uuid, 1, NULL, TRUE, 0, NULL, E'20 Hours', E'How long does it take from starting something and being grossly incompetent and knowing it to being reasonably good? In hopefully, as short a period of time as possible. So, how long does that take? Here’s what my research says: 20 hours. That’s it. You can go from knowing nothing about any skill that you can think of. Want to learn a language? Want to learn how to draw? Want to learn how to juggle flaming chainsaws? If you put 20 hours of focused deliberate practice into that thing, you will be astounded. Astounded at how good you are. 20 hours is doable, that’s about 45 minutes a day for about a month. Even skipping a couple days, here and there. 20 hours isn’t that hard to accumulate. Now, there’s a method to doing this. Because it’s not like you can just start fiddling around for about 20 hours and expect these massive improvements. There’s a way to practice intelligently. There’s a way to practice efficiently, that will make sure that you invest those 20 hours in the most effective way that you possibly can.\n\nClick on the paragraph that best relates to the recording.', '5383debb-e00e-598a-bbb8-c0315264b01e'::uuid, NULL, NULL, E'Research has shown that it takes you just 20 hours to be reasonably good in a thing, provided that you have invested these 20 hours in an intelligent and effective way.', NULL, NULL),
  ('af4a6e81-e32f-52be-8c62-f3c42e904c16'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'af4a6e81-e32f-52be-8c62-f3c42e904c16'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9273a83a-6fd5-51eb-9555-fe2388af87a7'::uuid, NULL, E'Conferences are always scheduled on the third Wednesday of the month.', NULL, NULL, NULL),
  ('af4cefb4-89ce-58f7-bafd-39fd20f42821'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'af4cefb4-89ce-58f7-bafd-39fd20f42821'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'be5d17d4-2bd3-585a-8c24-f563eb3af813'::uuid, NULL, E'Alternatively, you have the option to receive your academic grades through email.', NULL, NULL, NULL),
  ('af4ded34-3e90-53b4-bdc0-f006f199bde8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'af4ded34-3e90-53b4-bdc0-f006f199bde8'::uuid, 1, NULL, TRUE, 0, NULL, E'Journalism', E'Journalism serves as a pillar of democracy, tasked with the critical role of informing the public and holding those in {{1}} accountable. In an age where information is rapidly {{2}} , journalists must navigate the challenges of accuracy and bias. The field demands a {{3}} to truth and ethics, with journalists acting as watchdogs for society.', NULL, NULL, NULL, E'1.power, 2.disseminated, 3.commitment', NULL, NULL),
  ('af4e5522-8696-56f5-b960-46f7731f5e61'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'af4e5522-8696-56f5-b960-46f7731f5e61'::uuid, 1, NULL, TRUE, 0, NULL, E'William Shakespeare', E'Three hundred and eighty years after his death, William Shakespeare remains the central author of the English-speaking world; he is the most quoted poet and the most regularly produced playwright — and now among the most popular screenwriters as well. Why is that, and who "is" he?', NULL, NULL, NULL, NULL, NULL, NULL),
