  ('af9b9ef8-de50-56eb-8d15-c4f8dcb9d04c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'af9b9ef8-de50-56eb-8d15-c4f8dcb9d04c'::uuid, 1, NULL, TRUE, 0, NULL, E'Edible Insects', E'More than 1000 species of insects are {{2}} around the world. For example, “kungu cakes” – made from midges – are a {{3}} in parts of Africa. Mexico is an insect-eating – or entomophagous – hotspot, where more than 200 insect species are consumed. {{4}} is so high that 40 species are now under {{5}} , including white agave worms. These caterpillars of the tequila giant-skipper butterfly {{6}} around $250 a kilogram.', NULL, NULL, NULL, E'1.served up, 2.delicacy, 3.Demand, 4.threat, 5.fetch', NULL, NULL),
  ('af9c0212-555d-53fd-aeae-6a396f950ac8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'af9c0212-555d-53fd-aeae-6a396f950ac8'::uuid, 1, NULL, TRUE, 0, NULL, E'Environmental Degradation', E'What are the primary reasons behind environmental degradation?', NULL, NULL, NULL, NULL, 200, 300),
  ('afa019a4-2085-535b-8386-fc9e9b1ba2c7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'afa019a4-2085-535b-8386-fc9e9b1ba2c7'::uuid, 1, NULL, TRUE, 0, NULL, E'Goal-setting', E'Goal-setting is fascinating because it''s sort of a broken process in many respects. This is the way a goal works: You say to yourself, "When I achieve, whatever the thing is, that''s how I''ll know... I''ll have succeeded, and I''m gonna do everything I can to get to that point as quickly as possible." What that means is you exist in a failure state for a long time until you reach that goal, if it’s a long-range goal. And so, as you evaluate your process, all you get is the negative feedback of not having achieved that goal. Perhaps as you move close to it, there''s some positive feedback, but if the goal is really the end state that you''re seeking out, there''s a lot of failure ...\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', 'ff652e00-ae26-5cdf-90ba-517ab82d44a1'::uuid, NULL, NULL, E'before you get there', NULL, NULL),
  ('afa02c74-5fbf-53b6-ab05-9bd4908c9466'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'afa02c74-5fbf-53b6-ab05-9bd4908c9466'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What movement can babies do before they can sit and walk?', '792d931e-d887-5fc8-8eb4-0b1183557aa2'::uuid, NULL, NULL, E'Crawl / crawling', NULL, NULL),
  ('afaa7241-3b07-5823-95d1-291342bcd6c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'afaa7241-3b07-5823-95d1-291342bcd6c4'::uuid, 1, NULL, TRUE, 0, NULL, E'Learning More', E'Some people claim that instead of having to prepare for huge numbers of exams in school, children should learn more. To what extent do you agree with this statement?', NULL, NULL, NULL, NULL, 200, 300),
  ('afaebda6-8f05-5ee9-a6a2-a56e74251e36'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'afaebda6-8f05-5ee9-a6a2-a56e74251e36'::uuid, 1, NULL, TRUE, 0, NULL, E'Dark Energy (B)', E'The rest of the universe appears to be made of a mysterious, invisible {{1}} called dark matter 25 percent and a force that repels gravity known as dark energy 70 percent. Scientists have not yet {{2}} dark matter directly. It doesn''t interact with baryonic matter; it''s completely invisible to light and other forms of electromagnetic radiation, making dark matter {{3}} to detect with current instruments. But scientists are confident it {{4}} because of the gravitational effects, it appears to have on galaxies and galaxy clusters.', NULL, NULL, NULL, E'1.substance, 2.observed, 3.impossible, 4.exists', NULL, NULL),
