  ('affc481a-4d66-5d61-8f35-66b34f1e2d10'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'affc481a-4d66-5d61-8f35-66b34f1e2d10'::uuid, 1, NULL, TRUE, 0, NULL, E'Flu in Children', E'Although it is unclear how often neuropsychiatric events occur in children in the United States as a result of influenza, the use of a commonly prescribed antiviral medication for treating flu in children has become a subject of controversy that has raised concerns among parents and medical professionals alike.', NULL, NULL, NULL, NULL, NULL, NULL),
