  ('b05ffe81-3d03-557f-99d0-279f966de1e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b05ffe81-3d03-557f-99d0-279f966de1e1'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4f7802db-ae19-5d51-ad76-06749b6b4571'::uuid, NULL, E'Most of our employees get posted abroad at some certain stages.', NULL, NULL, NULL),
  ('b063a41e-2d08-5849-b200-5045442396a2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b063a41e-2d08-5849-b200-5045442396a2'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9056bded-9541-533e-8858-264e3714e331'::uuid, NULL, E'The chemistry building is still open during vacation.', NULL, NULL, NULL),
  ('b06571f9-f015-55c1-9a87-51c0498d151e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b06571f9-f015-55c1-9a87-51c0498d151e'::uuid, 1, NULL, TRUE, 0, NULL, E'Drug Ads', NULL, '9e73db0f-6f2a-5589-a7be-a17468e634a6'::uuid, NULL, E'The amount of money drug companies spend on TV ads has doubled in recent years. Studies show they work: Consumers go to their doctor with a suggestion for a certain prescription drug they saw advertised on TV. Now a study in the Annals of Family Medicine raises questions about the message the ads promote. You’re most likely to see drug ads during prime time, especially around the news. Researchers analyzed ads aimed at people with conditions like hypertension, herpes, high cholesterol , depression, arthritis and allergies.\nThe drug industry says the ads arm consumers with information. Researchers found that the information was technically accurate, but the tone was misleading.\n"Typically, what we would see with these ads is that before taking a particular prescription drug, the character''s life is out of control and the loss of control extended beyond the impact of their health condition."\nFor example, herpes patients were portrayed as being incapacitated for days. Insomniacs were utterly out of23 synch on the job. Depressed patients were friendless and boring at parties.\n"When the character is then shown taking the drug, he then magically regains complete control of his life."\nNone of the ads mentioned lifestyle changes that could also help treat the condition. That''s not surprising, given that the ads are just another form of mass marketing. But prescription medicines are not soap.', NULL, NULL, NULL),
  ('b0660797-ded0-54de-a3cc-33a40db8bd4e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b0660797-ded0-54de-a3cc-33a40db8bd4e'::uuid, 1, NULL, TRUE, 0, NULL, E'Egg-shape', E'Egg-shape has long attracted the attention of mathematicians and biologists from an analytical point of view. The shape has been highly regarded for its evolution as large enough to incubate an embryo, small enough to exit the body in the most efficient way, not roll away once laid, is structurally sound enough to bear weight and be the beginning of life for so many species.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b067d67b-ac78-5082-a52e-0a871b76fd8d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b067d67b-ac78-5082-a52e-0a871b76fd8d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the opposite of ''guilty''?', '0cd5b07c-1190-51cd-a3d9-f5ea22ca26b0'::uuid, NULL, NULL, E'Innocent', NULL, NULL),
  ('b069d1cc-c67c-5ff3-b570-5094cf8724af'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b069d1cc-c67c-5ff3-b570-5094cf8724af'::uuid, 1, NULL, TRUE, 0, NULL, E'Dog Trainer', E'Unlike traditional dog trainers, Alice Thompson doesn''t believe in dominance or punishment. Instead, she uses "empathetic communication" to understand and address the {{1}} of a dog''s behavioral issues. Affectionately known as the "Dog Whisperer Down Under," she traverses Australia, aiding families grappling with anxious pups, destructive chewers, and even aggressive canines. "Dogs aren''t {{2}} bad," she points out, "they simply lack the ability to effectively {{3}} their needs." Through her calm, assertive demeanor and keen observation skills, Alice {{4}} trust with the dogs, teaching them alternative behaviors through positive reinforcement. Her success stories have garnered a devoted following, solidifying the notion that understanding, not force, is the {{5}} to unlocking a dog''s true potential, fostering harmonious relationships between humans and their canine companions.', NULL, NULL, NULL, E'1.root, 2.inherently, 3.communicate, 4.builds, 5.key', NULL, NULL),
  ('b06e04f8-7e6f-59f2-9de0-7a68b194c641'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b06e04f8-7e6f-59f2-9de0-7a68b194c641'::uuid, 1, NULL, TRUE, 0, NULL, E'Lazy Journalism', E'The lazy journalism has become commonplace in today''s digitalized world. How do you define ''lazy journalism''? What is the cause?', NULL, NULL, NULL, NULL, 200, 300),
