  ('b0983427-df02-5587-931c-961b35c13f91'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b0983427-df02-5587-931c-961b35c13f91'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e1bc32c3-beab-59c9-97fd-38176769597a'::uuid, NULL, NULL, E'The university has evolved into a modern institution of higher education.', NULL, NULL),
  ('b09c0c08-f251-5324-9ff4-8adad35aa3e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b09c0c08-f251-5324-9ff4-8adad35aa3e9'::uuid, 1, NULL, TRUE, 0, NULL, E'Technological Isolation', E'Do you agree that advancements in technology are making people more isolated? Explain with examples.', NULL, NULL, NULL, NULL, 200, 300),
  ('b09eb9eb-bbbb-5297-a473-ef85203aae25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b09eb9eb-bbbb-5297-a473-ef85203aae25'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'eda9b6af-61e6-52b1-97d0-9036037ed428'::uuid, NULL, E'The first three characters in the book are vividly presented in pictures.', NULL, NULL, NULL),
  ('b0ab26f3-d344-5ee7-b44b-08469e59d586'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b0ab26f3-d344-5ee7-b44b-08469e59d586'::uuid, 1, NULL, TRUE, 0, NULL, E'Legume', E'Legumes, which are called pulses when they’re dried, have two key superpowers. They contain a high proportion of protein (more on this later), and they perform what’s called nitrogen fixation. Plants need nitrogen to make photosynthesis happen. It’s also a building block of their cells and DNA. Most plants take the nitrogen they need from the soil and legumes extract the nitrogen they need from the air. What they don’t use ends up in the soil, ready to be used by other plants.\nSo a crop of cereal grains will take nitrogen out of the soil, but a crop of legumes will put it back in. Rotating crops this way was, historically, how farmers recharged their soil with both nitrogen and organic matter. But after the Second World War, factory-produced, petroleum-derived nitrogen fertilisers took legumes out of the planting cycle.\nThere is no question that synthetic nitrogen fertiliser has allowed huge improvements in food outputs – but the downsides are considerable. It is increasingly expensive to use, because over-farmed soil becomes less fertile, requiring more of this energy-intensive finite resource. Runoff takes it into streams and ground water, where it spoils water quality and promotes algal blooms.\nAs it breaks down, it gives off nitrous oxide, a greenhouse gas that is 300 times more potent than carbon dioxide and affects the ozone layer. Plus, synthetic fertilisers don’t add any organic matter, part of the reason we now have serious soil degradation threatening global food security.', NULL, NULL, NULL, NULL, 5, 75),
  ('b0ac927c-a3d7-5fe7-8e27-022febba9b16'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b0ac927c-a3d7-5fe7-8e27-022febba9b16'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '404c8a38-ca6e-50d9-8708-228ee0aab407'::uuid, NULL, NULL, E'She has published many books including novels and literary criticism.', NULL, NULL),
  ('b0b03065-c2e8-5ba8-9d1a-deea986b88fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'b0b03065-c2e8-5ba8-9d1a-deea986b88fb'::uuid, 1, NULL, TRUE, 0, NULL, E'Note-taking', NULL, NULL, NULL, NULL, E'4, 3, 1, 2', NULL, NULL),
  ('b0bdf730-57d2-5016-9d21-abaeb09c8373'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b0bdf730-57d2-5016-9d21-abaeb09c8373'::uuid, 1, NULL, TRUE, 0, NULL, E'Rates of Depression', E'At a time when stress levels are soaring, rates of depression are increasing and the gap between rich and poor is ever widening. We believe that giving can play a positive role in helping people to feel connected to those around them and generate a sense of purpose and hope. When we give, we feel valued, useful and happy.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b0c2ca48-ecd4-5caa-8eeb-63e1056401df'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b0c2ca48-ecd4-5caa-8eeb-63e1056401df'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '530eb8ed-e4cc-50a6-8f3d-92a908562f55'::uuid, NULL, NULL, E'Cinema and music are as important as science and mathematics.', NULL, NULL),
  ('b0c4bf10-44d3-5bb6-98c7-71c9bf306c38'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b0c4bf10-44d3-5bb6-98c7-71c9bf306c38'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5451c42a-afe0-54da-a4cf-afedc8e9e41a'::uuid, NULL, E'It is necessary to examine how the new policy can be carried out.', NULL, NULL, NULL),
  ('b0cb85ed-2b59-5242-b074-a8bd505dbbd3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b0cb85ed-2b59-5242-b074-a8bd505dbbd3'::uuid, 1, NULL, TRUE, 0, NULL, E'Dark Mode', NULL, '0258356b-c044-5a88-9f94-dec298051cfe'::uuid, NULL, E'I think light mode is far better with respect to being able to comfortably read and use digital device for a long period of time and I think there are enough studies to back that up. There are indeed a bunch of studies to back this up. The consensus is that our eyes are roughly 26 percent worse at reading when it comes to dark mode. The biggest scientific factors for this, are focus, light scatter, and contrast. Let’s use a camera lens to explain the first one. Focusing is largely affected by how much light is coming into our eyes and how we focus that light. If a lot of light is coming in like when using light modes, eye pupils contract allowing less light in, creating a wide depth of field, meaning everything is in focus. If this is inverted, less light coming in, that causes our pupils to dilate and that creates a shallower plain of focus, meaning our eyes have to put more efforts into focusing on individual objects. When it comes to reading, you want everything to be in focus. You need that light background for the pupil to work appropriately to minimize amount of light coming in. It also increases your depth of the focus, the eye just works better more comfortably.', NULL, NULL, NULL),
  ('b0ce93de-1bc3-5854-82c1-68ea7a735882'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b0ce93de-1bc3-5854-82c1-68ea7a735882'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1b9859f4-fb04-5069-96cc-56a798cb1412'::uuid, NULL, NULL, E'Too many people and not enough cleanliness impacted most people''s lives.', NULL, NULL),
  ('b0cf9c3f-9f93-510c-9e9f-134671a7729a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b0cf9c3f-9f93-510c-9e9f-134671a7729a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '064fd383-100e-5b0d-972b-b7fe02001268'::uuid, NULL, NULL, E'Most governments face the significant challenge of managing population growth.', NULL, NULL),
  ('b0d1753d-67be-5fe5-b48d-337b796cf27d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b0d1753d-67be-5fe5-b48d-337b796cf27d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '91157ef6-61f5-56b7-9397-72fa4e2c4a3d'::uuid, NULL, NULL, E'Exercise is important for mental and physical health.', NULL, NULL),
  ('b0d93311-8ff9-58b6-8e5c-03c67da3050a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b0d93311-8ff9-58b6-8e5c-03c67da3050a'::uuid, 1, NULL, TRUE, 0, NULL, E'Robot and Human', NULL, 'a1fbaa7a-1808-5945-93a6-025ac8d092e8'::uuid, NULL, E'Why is it difficult to make a robot like a human being? Why cannot robots finish the work easily like human beings?\nFor some tasks, it is easy and simple for humans to complete, but it is very difficult to ask a robot to do what we want because humans and robots have different recognition functions.\nFor example, considering the insights, it is hard for robots to recognize colors because they do not have sensory mechanisms.\nArtificial intelligence scientists have to devise a sensor that is implanted to robots to enable them to recognize different colors.\nThe sensor has a camera on it to capture pixels, and then will translate the pixels into an image, which is not as easy as expected. This process is very complex.\nThe translation of every pixel to accurate things could be difficult, especially color differentiation which needs complicated sensors to fulfil. So the improvement of the sensor is necessary.\nIn conclusion, there is no comparison between humans and robots.', NULL, NULL, NULL),
  ('b0d9fab4-525b-5245-b9d8-09dfc7ee501d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b0d9fab4-525b-5245-b9d8-09dfc7ee501d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Computer, telephone and typewriter, which one is first invented?', '5cad3c86-afbf-524c-97b3-0a8bb0a89375'::uuid, NULL, NULL, E'Typewriter', NULL, NULL),
  ('b101cf03-d5a6-5da7-8f95-fe894ac68db1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b101cf03-d5a6-5da7-8f95-fe894ac68db1'::uuid, 1, NULL, TRUE, 0, NULL, E'Digital Tip Jars', E'A new checkout trend is sweeping across America, making for an increasingly awkward experience: digital tip jars. You order a coffee, an ice cream, a salad or a slice of pizza and pay with your credit card or phone. Then, an employee standing behind the counter spins around a touch screen and slides it in front of you. The screen has a few {{1}} tip amounts -- usually 10%, 15% or 20%. It’s being driven in large part by changes in technology that have enabled business owners to more easily {{2}} the costs of compensating workers directly to customers. Customers were encouraged to tip generously during the pandemic to help keep restaurants and stores {{3}} ,raising expectations. The shift to digital payments also accelerated during the pandemic, leading stores to {{4}} old-fashioned cash tip jars with tablet touch screens. But these screens and the procedures for digital tipping have proven more intrusive than a low-pressure cash tip jar with a few bucks in it.', NULL, NULL, NULL, E'1.suggested, 2.shift, 3.afloat, 4.replace', NULL, NULL),
  ('b114f374-ad0b-5752-95da-4fe4ec9f76d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b114f374-ad0b-5752-95da-4fe4ec9f76d5'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c2cda518-5419-50d1-93d4-12d9ecd77f7f'::uuid, NULL, E'If your parents come to visit you this semester, where will they stay?', NULL, NULL, NULL),
  ('b1203d91-6f4c-523d-8396-f856f342dc18'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b1203d91-6f4c-523d-8396-f856f342dc18'::uuid, 1, NULL, TRUE, 0, NULL, E'Sovereignty', E'Defining sovereignty in the digital era presents a complex challenge, {{1}} to the difficulty of defining a country. In an age where digital borders are increasingly blurred by global internet access, satellite communications, and transnational data flows, the traditional notion of sovereignty — {{2}} in territorial and physical boundaries — is being reevaluated. The question of how to assert control over digital spaces and data crosses has led to debates among policymakers, technologists, and legal experts. While some advocate for a cyberspace without borders, others call {{3}} national jurisdictions to extend into the digital domain. This tension underscores the evolving nature of sovereignty, where digital infrastructure and information sovereignty become critical aspects of national security and identity. The absence of a universal {{4}} for digital governance only adds to the complexity, mirroring the geopolitical debates over the recognition of nation-states.', NULL, NULL, NULL, E'1.akin, 2.rooted, 3.for, 4.framework', NULL, NULL),
  ('b127dae0-ec31-53c6-97a9-afde4cb3603a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b127dae0-ec31-53c6-97a9-afde4cb3603a'::uuid, 1, NULL, TRUE, 0, NULL, E'Take-all Disease', E'The soil dwelling fungus ''take-all'' inflicts devastating stress to the roots of cereals crops worldwide and is a major disease problem in UK wheat crops. However, recent field trial data from Rothamsted Research, an institute of the BBSRC, has demonstrated that farmers could control this devastating disease by selecting wheat cultivars that reduce take-all build up in the soil when grown as a first wheat. Wheat is an important staple crop worth 1.6 Billion a year to the UK economy alone. This work funded by the Biotechnology and Biological Sciences Research Council (BBSRC), the Department for the Environment, Food and Rural Affairs (Defra) and the HGCA will help farmers to increase yields, combating global food security and contributing to UK economic growth. Take-all disease, caused by the fungus, Gaeumannomyces graminis var. tritici, reduces grain yield and quality and results in an increased amount of residual applied nitrogen fertiliser left in the soil post-harvest. Despite the use of chemical, biological and cultural control methods the take-all fungus is still one of the most difficult pathogens of wheat to control. The risk of take-all infection in second and third wheat crops is directly linked to the amount of fungus remaining in the soil after the first wheat is harvested.\nThe Rothamsted Research study, published in Plant Pathology, has demonstrated that wheat cultivars differ in their ability to build-up the take-all fungus.\nGrowing a low building cultivar, such as Cadenza, as a first wheat crop can be used to manipulate take-all inoculum levels in the soil resulting in better yields from the second and third wheat crops. Yield increases of up to 2 tonnes per hectare in 2nd wheats have been observed.', NULL, NULL, E'Although ''take-all'' inflicts devastating stress to the roots of cereals crops and is a major disease problem in UK wheat crops which are important staple crops because it reduces grain yield and quality and results in an increased amount of residual applied nitrogen fertiliser left in the soil post-harvest, it can be controlled because growing a low building cultivar as a first wheat crop can be used to manipulate take-all inoculum levels in the soil.', NULL, 5, 75),
  ('b128ae11-667a-5f62-bdb1-ad24ddb1df3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b128ae11-667a-5f62-bdb1-ad24ddb1df3c'::uuid, 1, NULL, TRUE, 0, NULL, E'Koalas', E'Koalas are often called ‘koala bears’, probably because they look so cute and cuddly and resemble teddy bears. These animals weigh anywhere from 9 to 29 pounds, and they’re about 2 feet tall. While they do have a close resemblance to small bear cubs, koalas aren’t bears at all. Koalas are actually marsupials and are more closely related to Australia’s kangaroos and wombats. Marsupials have pouches to carry their offspring during early development stages. A baby koala, also known as a joey, is born blind and earless. It grows in the mother’s pouch for about six months. After that, the joey rides around on its mother’s back for another six months, using its mothers pouch to continue to feed during this time. Joeys are completely blind at birth, and their eyesight doesn’t improve too much as they mature. Overall, koalas have poor vision. They aren’t entirely blind, but their long-range sight is low. Because of this, these marsupials rely more on other senses to navigate their daily lives. To compensate for their eyesight, koalas have incredible hearing, which helps them stay ahead of predators and other koalas. They also have a great sense of smell they use to find food and detect koalas nearby. Interestingly, male koalas have scent glands on their chests that they use to mark trees and attract mates. They rub their chests up and down trees, which releases a strong, musky oil to mark their territory.', NULL, NULL, NULL, NULL, 5, 75),
  ('b128dce8-1f90-50e6-99b4-ad11a07b8648'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b128dce8-1f90-50e6-99b4-ad11a07b8648'::uuid, 1, NULL, TRUE, 0, NULL, E'Private Schools', E'Private schools in the UK are redoubling their marketing efforts to foreigners. Almost a third of the 68,000 boarding pupils at such schools {{1}} come from overseas. But now, with many UK residents {{2}} or unable to afford the fee - top boarding schools {{3}} towards £30,000 ($49,759) a year - and a cultural {{4}} away from boarding, many schools are looking abroad to survive. Overseas students now {{5}} for about £500m of fee income a year for boarding schools in the UK.', NULL, NULL, NULL, E'1.already, 2.unwilling, 3.edging, 4.shift, 5.account', NULL, NULL),
  ('b140664f-d571-5780-ab02-11f0e5733d49'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b140664f-d571-5780-ab02-11f0e5733d49'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '350e09d0-9a30-52f7-84dc-33937c319e88'::uuid, NULL, E'A lot of agricultural workers came to the East End to look for alternative work.', NULL, NULL, NULL),
  ('b144eee8-6c2a-5682-b90c-82197c132b4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b144eee8-6c2a-5682-b90c-82197c132b4b'::uuid, 1, NULL, TRUE, 0, NULL, E'Help', E'Before we start today''s episode, we need your help with an upcoming show. Are you a business that is trying to hire but cannot? We would love for you to tell us what you have tried. Have you changed the hours? Have you added perks? Are you turning to less-skilled workers? And we''d also love to hear what this has meant for your business that you cannot find workers. And then on the other hand, are you a worker who has turned down a job or quit? Tell us why. Was the pay too low? Is it safety, child care? Is it something we haven''t thought of yet? And then thirdly here, are you looking for work and cannot find it? Do you want to call b.s. on the whole labor shortage? Have you applied for jobs that are maybe even at companies complaining about the shortage? If your answer is yes to any of these, we would love to hear from you.\n\nBased on the information given in the passage, what could the upcoming show mainly be about?', '31ace47a-af7e-5936-9a9a-17711d708f17'::uuid, NULL, NULL, E'Discussion about the problems confronting the labor market.', NULL, NULL),
  ('b1485b94-84cf-581a-8a75-41365cf2d276'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b1485b94-84cf-581a-8a75-41365cf2d276'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2f2c6e19-9c20-5bf0-8503-0a8a289e9066'::uuid, NULL, E'Effective presenters make eye contact with the audience.', NULL, NULL, NULL),
  ('b14b4440-3901-52ba-84e3-ef6ab58fdf41'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b14b4440-3901-52ba-84e3-ef6ab58fdf41'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '49314dba-238c-5c35-a4ba-50caadc1005b'::uuid, NULL, E'A team is now studying the behavior of tropical animals.', NULL, NULL, NULL),
  ('b14bdf18-c73f-56d8-9838-47022e231eb8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b14bdf18-c73f-56d8-9838-47022e231eb8'::uuid, 1, NULL, TRUE, 0, NULL, E'Dumping Fertilizer', NULL, 'd937afb9-0683-51da-b786-5d9a4c56e3f5'::uuid, NULL, E'A massive forest provides a whole lotta fuel, so unless we want our National Parks to become heaps of ash, there are some blazes that we need to shut down as quickly as they start. Dumping crazy amounts of water on a forest fire is one pretty effective approach. Water does a couple big things. First, water interferes with that combustion reaction because as it vaporizes it creates a layer of water vapor that separates the fire’s fuel from the atmospheric oxygen that it needs to keep going. Second, the water cools the fuel, which slows and ultimately extinguishes the reaction. During a forest fire, firefighters work quickly to put out anything ablaze, including embers, which can fly around and spread the fire. They spray water from the ground and sky, refilling tanks at nearby water sources like lakes, rivers, or even your family’s pool. At the same time crews are creating a fire break, which is exactly what it sounds like — a break between the fire and its fuel. But dumping water and cutting down forest often isn’t enough. So, here’s where that bright red stuff comes in. It’s a long-term fire retardant, which means it can be sprayed on an area and, unless it gets washed away by a rainstorm, it will stick around for months. It’s made of 85 % water, 10 % fertilizer, and 5 % other stuff like clay and gum thickeners that help keep it together so that it makes to the ground from the plane.', NULL, NULL, NULL),
  ('b14f4019-0e3f-56ad-86f2-5516929755b5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b14f4019-0e3f-56ad-86f2-5516929755b5'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '341b56d1-10a3-57a8-80b5-e84caf4f810d'::uuid, NULL, E'The evidence was discovered through the study and observation of rocks.', NULL, NULL, NULL),
  ('b14f9231-311a-5cd9-8c65-1ed3bb7a1e42'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'HIGHLIGHT_CORRECT_SUMMARY', E'HIGHLIGHT_CORRECT_SUMMARY', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b14f9231-311a-5cd9-8c65-1ed3bb7a1e42'::uuid, 1, NULL, TRUE, 0, NULL, E'Welfare Programs', E'Most societies throughout history employed some strategies to help people in poverty meet basic needs. Before the 20th century, religious groups and private charities often led such initiatives. Today, these are called welfare programs, and they usually take the form of government-provided subsidies for housing, food, energy, and healthcare. Typically, these programs are means-tested, meaning that only people who fall below a certain income level are eligible for benefits. This policy is designed to ensure aid goes to those who need it most. But it also means people lose access as soon as they earn more than the qualification threshold, regardless of whether or not they’re financially stable enough to stay there. This vicious cycle is harmful to both those in poverty and those outside of it. Mainstream economic models assume people are rational actors who weigh the cost and benefits of their options and choose the most advantageous path forward. If those in poverty know they’ll gain no net benefit from working, they’re incentivized to remain in government assistance. Of course, people work for many reasons, including societal norms and personal values. But income is a major incentive to pursuing employment. And when less people take on new jobs, the economy slows down, keeping people in poverty and potentially pushing people on the cusp of poverty over the edge.\n\nClick on the paragraph that best relates to the recording.', 'c63776af-4019-5a04-a731-a4d6201ab04c'::uuid, NULL, NULL, E'Welfare programs are devised to ensure assistance goes to people who need it the most. Once they earn more than the qualification threshold, they will no longer be provided with such welfare. If people gain no net benefit from working, they’re more likely to remain in government help, which will lead to a low employment rate and a sluggish economy.', NULL, NULL),
  ('b152cd6d-b589-57f2-8c98-dc891ede5a34'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b152cd6d-b589-57f2-8c98-dc891ede5a34'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '1cecd1a2-05bf-5f8e-ad8a-d8c30ee9e14d'::uuid, NULL, E'In this class, the teaching staff are planning to collect students'' essays.', NULL, NULL, NULL),
