  ('b153afe5-0334-5b59-a333-6361b7991c87'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b153afe5-0334-5b59-a333-6361b7991c87'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5bb01f12-f234-527c-8ceb-5e4be22ffe7c'::uuid, NULL, E'Academics must actively interact with the general public outside the university setting.', NULL, NULL, NULL),
  ('b15ce2ef-29bc-5e2a-9920-5a08c3ad392d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b15ce2ef-29bc-5e2a-9920-5a08c3ad392d'::uuid, 1, NULL, TRUE, 0, NULL, E'Big Five', E'One Harvard medical school professor believes that there are five simple things to do everyday in order to live a longer life. In his new book, The Big Five, Sanjiv Chopra outlines five habits that have decades of research to back them up. Dr. Chopra says the first thing is to drink coffee. He claims that it really is a miracle drug. Then there are the more obvious beneficial habits, such as exercising daily and making sure you have enough Vitamin D in your diet. He also believes that a handful of nuts a day can prevent many diseases. And lastly, meditation for stress reduction is essential.\n\nWhich one is not mentioned for a longer life according to the professor?', 'df279cc5-67f4-5c2e-8937-81fc5cc2cf76'::uuid, NULL, NULL, E'Eating supplementary drugs.', NULL, NULL),
  ('b16056d2-ca63-5887-b29f-7e2ea84701f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b16056d2-ca63-5887-b29f-7e2ea84701f0'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '41c9b21c-6b51-5337-b240-baec543ac391'::uuid, NULL, NULL, E'Check the website if you are looking for discounted textbooks.', NULL, NULL),
