  ('b1fefea9-a820-5e71-b895-fefda44855c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b1fefea9-a820-5e71-b895-fefda44855c8'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bcc9db5e-694f-5733-baef-c420003aa42f'::uuid, NULL, E'Did you know that to become more fluent, you need lots of practice?', NULL, NULL, NULL),
  ('b2000a8d-6fe5-5728-98d1-ca5a01acb691'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b2000a8d-6fe5-5728-98d1-ca5a01acb691'::uuid, 1, NULL, TRUE, 0, NULL, E'Shock Absorption', E'Spacecraft and launch pad equipment undergo extreme stress due to vibration during rocket launches. To make sure that they remain functional in space, shock absorption technology was designed to protect the spacecraft. During earthquakes, buildings and bridges undergo similar stress. That is why the same shock absorption technology used for spacecraft is now used to strengthen buildings and bridges in earthquake-prone regions.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b200c6a8-41bb-5797-8711-4d1ce8370354'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b200c6a8-41bb-5797-8711-4d1ce8370354'::uuid, 1, NULL, TRUE, 0, NULL, E'Natural Networks', E'Neural networks are some of the most important tools in AI. So far, they run on traditional processors in the form of adaptive software, but experts are working on an alternative concept, the ''neuromorphic computer''. In this case, neurons are not simulated by software but reconstructed in hardware components. Researchers has now demonstrated a new approach to such hardware-targeted magnetic waves.', NULL, NULL, NULL, NULL, NULL, NULL),
