  ('b20129d8-b81f-5202-b35b-9526ec75a89e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b20129d8-b81f-5202-b35b-9526ec75a89e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b21cb6f2-15a4-5246-a2bd-45ce0548833a'::uuid, NULL, E'The householder has a duty to take good care for the visitor''s safety.', NULL, NULL, NULL),
  ('b2024d89-c4bd-51b6-b3c9-8dafc77a0f10'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b2024d89-c4bd-51b6-b3c9-8dafc77a0f10'::uuid, 1, NULL, TRUE, 0, NULL, E'Human Activities', E'Human activities are exposing US rivers and streams to a cocktail of salts, with consequences for infrastructure and drinking water supplies. So reports a new study that is the first to assess the combined, long-term changes in freshwater salinity and alkalization across the country.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b202e372-1df3-50d5-a97f-d6ffffd53322'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b202e372-1df3-50d5-a97f-d6ffffd53322'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e1a6f5a3-b35d-590a-92b2-d8a526f2bba2'::uuid, NULL, NULL, E'We''re still not sure what really happened in those old stories.', NULL, NULL),
  ('b20a61aa-47cc-55ba-9742-0c6483ad5e78'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b20a61aa-47cc-55ba-9742-0c6483ad5e78'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1508059b-25f7-5e15-9e38-3e8645f30f2d'::uuid, NULL, NULL, E'Students should look at online resources before their classes start.', NULL, NULL),
  ('b2112dd3-98bf-5310-ae5c-ba1c4645915e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b2112dd3-98bf-5310-ae5c-ba1c4645915e'::uuid, 1, NULL, TRUE, 0, NULL, E'Food Truth', E'It is that time of year again. As the cold and flu season hits the northern hemisphere on top of the ongoing {{1}} of covid-19, many of us reach for something to give our body’s defence a helping hand. There is no shortage of foods and drinks that claim to be able to help. Supermarket shelves are heaving with “immunity support” juices, yogurts and spice-infused teas. Comforting, yes, but can these foods really help {{2}} off contagion? The impact of diet on our natural defence is a topic {{3}} with claims that don’t stand up to scrutiny, but we are finally developing a clearer {{4}} of the powerful influence that food can have on our immunity. The surprising truth is that focusing on particular products or ingredients could be leading you down the wrong path. In fact, an immune “boost” might be the last thing you need.', NULL, NULL, NULL, E'1.ravages, 2.stave, 3.rife, 4.picture', NULL, NULL),
  ('b211f0f7-1e0d-559e-8302-18b6d595feb4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b211f0f7-1e0d-559e-8302-18b6d595feb4'::uuid, 1, NULL, TRUE, 0, NULL, E'Marketing in Companies', E'Should marketing in companies which produce consumer goods, like food and clothing, place emphasis on the reputation of the company or short-term strategies like discounts and special offers? Why?', NULL, NULL, E'Marketing is an essential aspect of any business, particularly in the consumer goods industry. Companies must decide whether to focus on building their reputation or implementing short-term strategies like discounts and special offers. In my opinion, companies should prioritize building their reputation over short-term strategies. In this essay, I will explore the positive aspects of reputation-building, including its ability to build customer loyalty, attract new customers, and promote ethical business practices.\nOne of the most significant benefits of reputation-building is its ability to build customer loyalty over time. By investing in their reputation, companies can establish a sense of trust with their customers. This trust can lead to repeat business and positive word-of-mouth advertising. Additionally, a strong reputation can help companies weather negative events or crises, as customers are more likely to forgive a company they trust.\nAnother benefit of reputation-building is its ability to attract new customers. Consumers are increasingly interested in purchasing products from companies with a strong ethical track record and commitment to sustainability. By emphasizing their reputation for ethical and sustainable practices, companies can attract new customers who share these values.\nIn conclusion, while short-term strategies like discounts and special offers may be effective in increasing sales quickly, I believe that companies should prioritize building their reputation over these strategies. Building a strong reputation can lead to customer loyalty, attract new customers, and promote ethical business practices. By doing so, companies can create a sustainable business model that benefits both the company and its customers.', NULL, 200, 300),
  ('b2151e5c-4d35-5d8d-a4eb-f4a232384b0a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b2151e5c-4d35-5d8d-a4eb-f4a232384b0a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call a specialist who repairs leaking water pipes?', 'f72e3f77-0a28-579f-96f3-c6d45255b991'::uuid, NULL, NULL, E'Plumber', NULL, NULL),
  ('b21a9de3-0d4e-579f-b8dd-20e39861465d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b21a9de3-0d4e-579f-b8dd-20e39861465d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What are the five things in front of your foot?', 'b56c482b-8318-5811-80df-dee0d65faa8e'::uuid, NULL, NULL, E'Toes', NULL, NULL),
  ('b21e7b6c-1db7-58a3-8931-034e0545cc16'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b21e7b6c-1db7-58a3-8931-034e0545cc16'::uuid, 1, NULL, TRUE, 0, NULL, E'Malicious Apps', E'A recent incident at Meta’s Facebook left users worried as the social media giant announced earlier this week that over a million users may have had their credentials compromised. The reason behind the security lapse – malicious apps that tricked users into giving the app their login credentials under false guises. A report by Bloomberg suggests that a number of malicious apps that were available on the Play Store and App Store were disguised as photo editors, mobile games and health trackers, among others. This makes it hard for most people to identify what could potentially be problematic apps since such apps are built around offering a false use-case. Malicious apps will offer to provide extra bonus features by getting users to log in with their Facebook account (or another social media account). This seemingly harmless act tricks users into opening in-app windows where they will sign in with their usernames and passwords. Similar to how keyloggers work, once a user enters their credentials, the malicious apps may keep a record of the same and send it to remote attackers when the phone is next connected to mobile data or WiFi. Facebook has said that not all of the roughly 1 million devices may have had their credentials compromised, but the company plans to share tips with potential victims on how they can avoid being “re-compromised” by learning to spot potentially malicious apps.', NULL, NULL, NULL, NULL, 5, 75),
  ('b224338e-8729-5a9a-82d2-988c1732ede1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b224338e-8729-5a9a-82d2-988c1732ede1'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2222aa84-1434-5354-a8e0-942a0d15e210'::uuid, NULL, NULL, E'The same features in the device explain the issue every time.', NULL, NULL),
