  ('b229ae44-57f3-5fe1-a78c-10ec0412f65d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b229ae44-57f3-5fe1-a78c-10ec0412f65d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '63227ecd-ff4d-5f58-ad4d-08e641a67b6d'::uuid, NULL, NULL, E'A growing number of people are beginning to follow a vegetarian diet.', NULL, NULL),
  ('b231626b-236b-5287-a7ae-80cbed7b2bfe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'b231626b-236b-5287-a7ae-80cbed7b2bfe'::uuid, 1, NULL, TRUE, 0, NULL, E'Nazca Lines', NULL, NULL, NULL, NULL, E'3, 4, 1, 2', NULL, NULL),
  ('b2326e9f-05d0-5885-a83b-ba3e2e9c0c4c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b2326e9f-05d0-5885-a83b-ba3e2e9c0c4c'::uuid, 1, NULL, TRUE, 0, NULL, E'Clouds', E'Howard believed that all clouds belonged to three distinct groups: cumulus, stratus and cirrus. He added a fourth category, nimbus, to describe a cloud in the act of condensation into rain, hail or snow. It is by observing how clouds change color and shape that weather can be predicted, and as long as the first three of cloud keep their normal shape there won''t be any rain.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b23bbbfe-0425-5841-9551-9810bf1241ef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b23bbbfe-0425-5841-9551-9810bf1241ef'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4c8e1eb6-5a8f-5df6-9154-487293028a1d'::uuid, NULL, NULL, E'Scholarships help meet financial needs of students globally and locally.', NULL, NULL),
  ('b23dbc94-d59b-563b-9b3b-5fbdd8847388'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b23dbc94-d59b-563b-9b3b-5fbdd8847388'::uuid, 1, NULL, TRUE, 0, NULL, E'Children''s Numerical Skills', NULL, '8adb9f4d-d017-5c61-b2d1-cc444fcd53e1'::uuid, NULL, E'people appear to born to compute. The numerical skills of children develop so early and so inexorably that it is easy to imagine an internal clock of mathematical maturity guiding their growth. Not long after learning to walk and talk, they can set the table with impress accuracy---one knife, one spoon, one fork, for each of the five chairs. Soon they are capable of nothing that they have placed five knives, spoons and forks on the table and, a bit later, that this amounts to fifteen pieces of silverware. Having thus mastered addition, they move on to subtraction. It seems almost reasonable to expect that if a child were secluded on a desert island at birth and retrieved seven years later, he or she could enter a second enter a second-grade mathematics class without any serious problems of intellectual adjustment.\nOf course, the truth is not so simple. This century, the work of cognitive psychologists has illuminated the subtle forms of daily learning on which intellectual progress depends. Children were observed as they slowly grasped-----or, as the case might be, bumped into----- concepts that adults take for quantity is unchanged as water pours from a short glass into a tall thin one. Psychologists have since demonstrated that young children, asked to count the pencils in a pile, readily report the number of blue or red pencils, but must be coaxed into finding the total. Such studies have suggested that the rudiments9 of mathematics are mastered gradually, and with effort. They have also suggested that the very concept of abstract numbers------the idea of a oneness, a twoness, a threeness that applies to any class of objects and is a prerequisite for doing anything more mathematically demanding than setting a table-----is itself far from innate', NULL, NULL, NULL),
  ('b253e5bd-3904-5060-934b-75e0f5e54972'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b253e5bd-3904-5060-934b-75e0f5e54972'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'fe4e327a-9832-5a5c-9d9f-e603e9425418'::uuid, NULL, E'They were struggling to pay their fees last year.', NULL, NULL, NULL),
