  ('b25e25a6-b3dd-5f6c-a4dd-842c07c569b7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b25e25a6-b3dd-5f6c-a4dd-842c07c569b7'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ed5f97db-6e8b-5139-b58a-ced60496505e'::uuid, NULL, E'The Australian economy depends heavily on revenue from tourism and education.', NULL, NULL, NULL),
  ('b25f5451-be34-5bb9-b8e8-1eefe3db7e0d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b25f5451-be34-5bb9-b8e8-1eefe3db7e0d'::uuid, 1, NULL, TRUE, 0, NULL, E'Interferon', E'So why not switch on those interferons 24/7 in humans? Well in us, they also tend to cause lots of inflammation and cell damage. Like the symptoms you feel from the flu — a lot of that is your immune system''s fault. But the key might be to do as the bats do.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b262f6c9-4270-59c8-b149-fc697f2744e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b262f6c9-4270-59c8-b149-fc697f2744e1'::uuid, 1, NULL, TRUE, 0, NULL, E'Psychology', E'Psychology is a suitable course of study for those {{1}} in all aspects of human thought and behavior. It can be {{2}} as the scientific study of how humans function on a biological, social and mental level. There are a range of influential approaches to the subject, which are {{3}} to such areas as child development, health, education and sports.', NULL, NULL, NULL, E'1.interested, 2.defined, 3.applied', NULL, NULL),
  ('b264d1c4-1923-50c2-8d24-d7ee9d30dc17'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b264d1c4-1923-50c2-8d24-d7ee9d30dc17'::uuid, 1, NULL, TRUE, 0, NULL, E'Exams Looming', E'It''s that time again! Exams looming, essays or reports outstanding and you wonder where the year''s gone already. You start {{1}} how you''re going to cope with it all. A limited amount of {{2}} can help you to be more motivated and more {{3}} . It can help you to plan your work and to think more clearly and {{4}} about it. In other words, it can help you stay on top of things. Sit down at your desk and make a start on writing down all the things you have to do to {{5}} for the exams.', NULL, NULL, NULL, E'1.wondering, 2.anxiety, 3.purposeful, 4.logically, 5.prepare', NULL, NULL),
  ('b26977f5-543e-5574-b616-69826930983a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b26977f5-543e-5574-b616-69826930983a'::uuid, 1, NULL, TRUE, 0, NULL, E'Realm of Education', E'In the realm of education, the integration of technology has brought about {{1}} changes in the way students learn and teachers instruct. With the advent of e-learning platforms, students now have access to a {{2}} array of educational resources and can learn at their own pace. One of the key advantages of technology in education is its ability to cater to diverse {{3}} styles. Interactive multimedia, virtual classrooms, and gamified learning experiences offer a variety of approaches to engage students and enhance their understanding of complex subjects. However, the widespread use of technology in education also raises {{4}} concerns. The digital divide remains a significant issue, as not all students have equal access to technology and the internet. Additionally, there are concerns about screen time and the potential negative effects of excessive device usage on students'' physical and mental well-being. In conclusion, the integration of technology in education offers immense {{5}} for enhancing learning experiences, but it also requires addressing issues of access and well-being to ensure equitable benefits for all students.', NULL, NULL, NULL, E'1.revolutionary, 2.vast, 3.learning, 4.ethical, 5.opportunities', NULL, NULL),
  ('b26bf03f-b292-5b5e-9e08-edfcdc27c337'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b26bf03f-b292-5b5e-9e08-edfcdc27c337'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which kind of dance is related to swans?', '61ab1c71-32f7-5d91-8810-053ad966b0ad'::uuid, NULL, NULL, E'Ballet', NULL, NULL),
