  ('b26d1558-9413-5f14-bec8-1c432529bce2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b26d1558-9413-5f14-bec8-1c432529bce2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '79bae258-9dc8-52fb-99e5-f08844263cb0'::uuid, NULL, NULL, E'Mobile devices are not allowed during the examination.', NULL, NULL),
  ('b26f6b82-ea42-54d5-bbce-6b6604481ff0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b26f6b82-ea42-54d5-bbce-6b6604481ff0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'fbfaafdd-8ab4-5643-8777-60eff2ca928d'::uuid, NULL, E'Our existence is dependent on the energy we utilize daily.', NULL, NULL, NULL),
  ('b26fe1d4-00a3-51c3-bf56-57a126a9e47b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b26fe1d4-00a3-51c3-bf56-57a126a9e47b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '425297fa-128c-5a95-8548-bdac1bd3ab59'::uuid, NULL, NULL, E'Books in the reserved collection contribute significantly to students'' achievements.', NULL, NULL),
  ('b27886b7-ccbe-5263-9f41-3f62747c0256'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b27886b7-ccbe-5263-9f41-3f62747c0256'::uuid, 1, NULL, TRUE, 0, NULL, E'Ageing Process', E'In Boston labs, old, blind mice have {{1}} their eyesight, developed smarter, younger brains and built healthier muscle and kidney tissue. On the flip side, young mice have prematurely aged, with {{2}} results to nearly every tissue in their bodies. This experiment shows aging is a {{3}} process, capable of being driven forwards and backwards at will.', NULL, NULL, NULL, E'1.regained, 2.devastating, 3.reversible', NULL, NULL),
  ('b27b1a44-75f2-54af-86f9-488081371179'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b27b1a44-75f2-54af-86f9-488081371179'::uuid, 1, NULL, TRUE, 0, NULL, E'AudioLM', E'A new AI system can create natural-sounding speech and music after being prompted with a few seconds of audio. AudioLM, developed by Google researchers, generates audio that fits the style of the prompt, including complex sounds like piano music, or people speaking, in a way that is almost indistinguishable from the original recording. The technique shows promise for speeding up the process of training AI to generate audio, and it could eventually be used to auto-generate music to accompany videos.\nAI-generated audio is commonplace: voices on home assistants like Alexa use natural language processing. AI music systems like Open AI’s Jukebox have already generated impressive results, but most existing techniques need people to prepare transcriptions and label text-based training data, which takes a lot of time and human labor. Jukebox, for example, uses text-based data to generate song lyrics.\nAudioLM, described in a non-peer-reviewed paper last month, is different: it doesn’t require transcription or labeling. Instead, sound databases are fed into the program, and machine learning is used to compress the audio files into sound snippets, called “tokens,” without losing too much information. To generate the audio, a few seconds of sound are fed into AudioLM, which then predicts what comes next.\nRoger Dannenberg, who researches computer-generated music at Carnegie Mellon University, says AudioLM already has much better sound quality than previous music generation programs. In particular, he says, AudioLM is surprisingly good at re-creating some of the repeating patterns inherent in human-made music. To generate realistic piano music, AudioLM has to capture a lot of the subtle vibrations contained in each note when piano keys are struck. The music also has to sustain its rhythms and harmonies over a period of time.', NULL, NULL, NULL, NULL, 5, 75),
  ('b27c42d2-ab08-549e-8078-ac0ad5a7a7c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b27c42d2-ab08-549e-8078-ac0ad5a7a7c0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f8267063-f58f-5c9a-8562-847d62c2fb02'::uuid, NULL, E'Half of the marks in mathematics are allocated for correct working.', NULL, NULL, NULL),
