  ('b28f0e50-6f56-5e3e-9593-d8bc88db1b77'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b28f0e50-6f56-5e3e-9593-d8bc88db1b77'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '42be8e67-b339-5404-816c-baeab0699796'::uuid, NULL, E'The college welcomes students from all over the world.', NULL, NULL, NULL),
