  ('b293a8b7-d1f2-5b61-8409-beb3bef0d450'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b293a8b7-d1f2-5b61-8409-beb3bef0d450'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '75af3dd2-d7f9-5368-9029-bc3158d77ef9'::uuid, NULL, NULL, E'It is quite clear that our facial expressions are similar across different cultures.', NULL, NULL),
  ('b294c0f0-b59e-55fd-a442-be238609c96b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b294c0f0-b59e-55fd-a442-be238609c96b'::uuid, 1, NULL, TRUE, 0, NULL, E'Paraphrasing', E'We define paraphrasing as putting a passage from an author into your own words. However, what are your own words? How different must your paraphrase be from the original? The answer is it should be considerably different. The whole point of paraphrasing is to show you have read and understood another person''s ideas and can summarize them in your own writing style rather than borrowing their phrases.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b294c645-f108-51bb-a6a6-7be652471bd9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b294c645-f108-51bb-a6a6-7be652471bd9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9468ee8e-be09-5876-9fa9-2118c37570c6'::uuid, NULL, E'Remember to sign the attendance sheet before leaving the lecture hall.', NULL, NULL, NULL),
  ('b298fe1f-5b59-5a25-9010-599b6d73dd6e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b298fe1f-5b59-5a25-9010-599b6d73dd6e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e8dff57c-42b7-5c97-8de4-bffd0f3e9deb'::uuid, NULL, NULL, E'The professor took the students to the new chemistry lab.', NULL, NULL),
  ('b29e99bd-da0a-532f-9233-0ee139403275'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b29e99bd-da0a-532f-9233-0ee139403275'::uuid, 1, NULL, TRUE, 0, NULL, E'Rosalind Franklin', NULL, '87767f1d-2552-55fa-ac50-dfea9cb58c8b'::uuid, NULL, E'Rosalind Franklin is a remarkable scientist whose contributions were crucial to understanding the structure of DNA. Her story is a powerful reminder of the impact of perseverance and dedication in scientific discovery. Rosalind Franklin''s expertise in X-ray crystallography led to the famous Photo 51, a critical piece of evidence in determining the double helix structure of DNA. Her meticulous and precise approach provided key insights that were essential for this groundbreaking discovery. Yet, her contributions were initially overshadowed and only gained recognition posthumously. Franklin''s work extends beyond DNA. She made significant contributions to understanding the molecular structures of viruses and coal, showcasing her versatility and expertise in multiple fields of study. In conclusion, Rosalind Franklin''s legacy is not just in her scientific achievements but also in her resilience in a male-dominated field. Her story inspires future generations of scientists, especially women, to pursue their passions in the face of challenges.', NULL, NULL, NULL),
  ('b2a93f92-9a5d-5920-8fc8-b17f5b91336b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b2a93f92-9a5d-5920-8fc8-b17f5b91336b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What color symbolizes purity and cleanliness?', 'd5cd0200-34f7-57ea-8d5e-ff56d9d9b40f'::uuid, NULL, NULL, E'White', NULL, NULL),
  ('b2a9a3d8-a3b4-5a14-a4e3-3c9b877261dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b2a9a3d8-a3b4-5a14-a4e3-3c9b877261dd'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e4d30313-c743-5e2d-9cd8-345f5975b740'::uuid, NULL, E'Diversity of architectural styles is one of the greatest features of the Main Campus.', NULL, NULL, NULL),
  ('b2acfacd-c8bc-5afb-b12f-d2b12e238aa1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b2acfacd-c8bc-5afb-b12f-d2b12e238aa1'::uuid, 1, NULL, TRUE, 0, NULL, E'Existentialism', E'Existentialism is a philosophical movement that explores the nature of human existence and the individual''s struggle to find meaning in a chaotic and absurd world. It emphasizes personal freedom, responsibility, and the importance of subjective experience. Existentialist thinkers delve into concepts such as authenticity, anxiety, and the inevitability of death.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b2b0ad1b-482b-5736-b1a0-be0407f4dc65'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'b2b0ad1b-482b-5736-b1a0-be0407f4dc65'::uuid, 1, NULL, TRUE, 0, NULL, E'Dual-Mode Vehicle', E'Japan recently unveiled the world’s first Dual-Mode Vehicle (DMV), a contraption that runs both on roads, like a bus, and on rails, like a train. The mini-bus-like contraption didn’t win anyone over with its looks, but it definitely made an impression in terms of practicality. It runs with normal rubber tires on the road, but when it needs to switch to train mode, a pair of metal wheels drop down from the vehicle’s underbelly. The front tires are lifted off of the track, while the rear wheels stay down to propel the vehicle. Switching between road and train modes takes only about 15 seconds.\n\nAccording to this passage, we can know that __', NULL, NULL, NULL, E'People think DMV is pragmatic.', NULL, NULL),
  ('b2c173d1-627a-54af-94a7-b63fcce917c9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b2c173d1-627a-54af-94a7-b63fcce917c9'::uuid, 1, NULL, TRUE, 0, NULL, E'Deflationary Spiral', E'As economic troubles stop flaring up around the globe, the earning estimates of American firms who do business abroad begin to flatten. Without these international consumers to buy their products, there are fewer sales, which means that inventories pile up. When there is more supply than demand, prices go down. Lower prices would normally cause demand to pick up, but in an uncertain economy, people tend to postpone purchases. We see this tendency in the American economy with computer products where consumers believe that the prices will go down if they wait another six months, so they decide to hold off. This tendency causes further gluts in the market, which eventually leads manufacturers to slow production. They lay off workers, causing domestic consumption to fall further since there is less money to buy goods. These effects ripple throughout the economy and create a deflationary spiral that can lead to a recession or even a depression.', NULL, NULL, E'As economic troubles stop flaring up around the globe, the earning estimates of American firms who do business abroad begin to flatten, so without these international consumers to buy their products, there are fewer sales, which makes the prices go down, but in an uncertain economy, people tend to postpone purchases, as this tendency causes further gluts in the market, and these effects ripple throughout the economy and create a deflationary spiral.', NULL, 5, 75),
  ('b2c9db41-5164-5046-ad9d-e14a2f6ddef7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b2c9db41-5164-5046-ad9d-e14a2f6ddef7'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ba4fbe43-fc39-58e9-9c36-2d400057ff7a'::uuid, NULL, E'You have to do well academically to get into medical school.', NULL, NULL, NULL),
  ('b2ce6836-c68a-5dc1-a26a-e4c0bf6a3c30'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b2ce6836-c68a-5dc1-a26a-e4c0bf6a3c30'::uuid, 1, NULL, TRUE, 0, NULL, E'Space Exploration', E'Space exploration has expanded our horizons and deepened our understanding of the universe, from the first moon landing to the discovery of exoplanets orbiting distant stars. Through space missions and telescopic observations, scientists have unraveled cosmic mysteries, studied celestial bodies in detail, and gained insights into the origins and evolution of our universe.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b2d2d453-0d31-56e8-b73f-43931b72e997'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b2d2d453-0d31-56e8-b73f-43931b72e997'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1a8ba22f-4b17-5b2a-a028-1013ba372bd9'::uuid, NULL, NULL, E'Including a thorough bibliography is necessary to secure full marks.', NULL, NULL),
