  ('b2f5f85e-5789-552e-8380-d70ae83841e3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b2f5f85e-5789-552e-8380-d70ae83841e3'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the opposite of even numbers?', '4725a21b-54d1-5d90-9b0e-6cbf209be22b'::uuid, NULL, NULL, E'Odd numbers', NULL, NULL),
  ('b2f6bef5-8882-55ca-a10b-984c763f538c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b2f6bef5-8882-55ca-a10b-984c763f538c'::uuid, 1, NULL, TRUE, 0, NULL, E'Home Design', E'The recent trend towards smart homes {{1}} gadgets that automate tasks, aiming to increase convenience and efficiency. For example, smart thermostats can adjust the temperature based on the weather and occupancy, smart lights can turn on and off with voice {{2}} or motion sensors, and smart security systems can alert the homeowners of any {{3}} activity. At the same time, there''s a growing appreciation for vintage and handmade items, suggesting a desire {{4}} uniqueness and craftsmanship. Many people choose to decorate their homes with antiques, collectibles, or artisanal products, such as quilts, pottery, or paintings. Others mix and {{5}} different styles and eras, creating a fusion of old and new. This juxtaposition raises questions about how these seemingly opposite elements can coexist and enhance each other''s value.', NULL, NULL, NULL, E'1.incorporates, 2.commands, 3.suspicious, 4.for, 5.match', NULL, NULL),
  ('b2f6c447-7a24-5845-a82f-7c3b18b810f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b2f6c447-7a24-5845-a82f-7c3b18b810f0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3313f7d4-c956-570b-bdeb-590dc83fc60e'::uuid, NULL, E'Researchers have observed that family plays a crucial role in the success of individuals.', NULL, NULL, NULL),
