  ('b32e377e-787e-5c0b-ba8a-5d7d11087a30'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b32e377e-787e-5c0b-ba8a-5d7d11087a30'::uuid, 1, NULL, TRUE, 0, NULL, E'Tail Feathers', E'Most tail feathers {{1}} an interlocking microstructure similar to wing feathers. Arranged in a fan shape, these feathers support precision {{2}} in flight. Typically, birds have six pairs of feathers on the tail, which display increasing levels of asymmetry toward the outer pairs. In some birds, tail feathers have evolved into showy {{3}} that are useless in flight.', NULL, NULL, NULL, E'1.feature, 2.steering, 3.ornaments', NULL, NULL),
  ('b3310546-871c-5590-8b2c-9f2575beacff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b3310546-871c-5590-8b2c-9f2575beacff'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b4334e01-487b-5ab3-9742-7a7caff8d70c'::uuid, NULL, NULL, E'The designers will complete the plan later today.', NULL, NULL),
  ('b338be69-baff-5f1f-9d1e-0f230fdf0917'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b338be69-baff-5f1f-9d1e-0f230fdf0917'::uuid, 1, NULL, TRUE, 0, NULL, E'Eating Habbits', E'What are the main reasons people struggle to maintain healthy eating habits in today''s society?', NULL, NULL, E'In today''s fast-paced society, maintaining healthy eating habits has become increasingly difficult for many individuals. Despite the growing awareness of the importance of nutrition, several factors hinder people from making healthier food choices.\nOne significant reason for the struggle to maintain healthy eating habits is the prevalence of busy lifestyles, leading individuals to rely heavily on fast food and processed meals due to time constraints. The convenience and accessibility of these options, despite lacking essential nutrients, make them appealing choices that contribute to poor dietary habits.\nFurthermore, the constant exposure to unhealthy food advertisements significantly influences individuals'' food choices by promoting sugary snacks, high-fat foods, and sugary beverages. These marketing strategies create an environment that encourages the consumption of unhealthy products, leading individuals to make less nutritious choices and struggle to maintain a balanced diet. Limited knowledge about nutrition and healthy eating practices exacerbates this challenge, as individuals without a solid understanding of food''s nutritional value may struggle to make informed choices, resulting in poor dietary decisions that impact overall health negatively.\nIn conclusion, the obstacles to maintaining healthy eating habits in today''s society are multifaceted. Addressing issues such as busy lifestyles, exposure to unhealthy food marketing, and limited nutritional knowledge is crucial in promoting healthier dietary behaviors and improving overall health outcomes.', NULL, 200, 300),
  ('b33a9ba3-548f-563c-a3dd-f884cb66bcd1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b33a9ba3-548f-563c-a3dd-f884cb66bcd1'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '159b1cf5-0ecf-5647-a47d-6b1b2ed66526'::uuid, NULL, E'The university is willing to join the joint research efforts of the local council.', NULL, NULL, NULL),
  ('b33f1b01-dea8-5da8-a131-1b96bf171d39'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b33f1b01-dea8-5da8-a131-1b96bf171d39'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e82dba04-f998-5814-8148-739b58f15629'::uuid, NULL, E'Your lowest quiz grade has been omitted from the calculations.', NULL, NULL, NULL),
