  ('b3414b0f-726a-5595-8256-45a9fb66b870'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b3414b0f-726a-5595-8256-45a9fb66b870'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What term is used to describe a person who rides waves on a special board in the ocean?', '6bb410bd-e94c-5019-a094-1540a5d3ed79'::uuid, NULL, NULL, E'Surfer', NULL, NULL),
  ('b343f075-c1d3-57ba-b4df-749d613886bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b343f075-c1d3-57ba-b4df-749d613886bd'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2e311b12-1b48-53bf-b168-e7a1670a8002'::uuid, NULL, NULL, E'It''s confidence and it''s optimism that I now have.', NULL, NULL),
  ('b3441abc-3ecd-5b82-8caf-915e0fd24c6f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b3441abc-3ecd-5b82-8caf-915e0fd24c6f'::uuid, 1, NULL, TRUE, 0, NULL, E'Here Be Dragons', E'Medieval mapmakers supposedly inscribed the phrase “Here Be Dragons” on maps showing unknown regions of the world. Unfortunately, apart from an inscription on a globe, this claim is unfounded. Although there were no dragons, and the inscription “Here Be Dragons” was virtually never used, some of the purported earliest mapmakers did have to deal with real and formidable megafauna.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b348b24a-36e8-504f-ae40-155c28efbee8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b348b24a-36e8-504f-ae40-155c28efbee8'::uuid, 1, NULL, TRUE, 0, NULL, E'Naked Biome', E'Hopefully, this will treat and prevent acne and other skin diseases and reduce antibiotic use. Naked Biome is entering clinical trials to see if its approach is safe and effective.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b34d7003-2630-535e-8226-353daf7acc68'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b34d7003-2630-535e-8226-353daf7acc68'::uuid, 1, NULL, TRUE, 0, NULL, E'Hunter-gatherer', E'The life of a hunter-gatherer is indeed, as Thomas Hobbes said of the state of nature, ''solitary, poor, nasty, brutish, and short''. In some respects, to be sure, wandering through the jungle bagging monkeys may be preferable to the hard slog of subsistence agriculture.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b350af27-08bf-5303-9ca2-3c3147d63ecf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b350af27-08bf-5303-9ca2-3c3147d63ecf'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a flat piece of hard clay or other materials used to cover the floors or walls?', 'f50ac88e-bf6b-5aa5-95c2-3ca81c87ac9c'::uuid, NULL, NULL, E'Tile', NULL, NULL),
  ('b3563962-7622-5881-8f2d-81b87845f177'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', 'b3563962-7622-5881-8f2d-81b87845f177'::uuid, 1, NULL, TRUE, 0, NULL, E'X-ray', E'X-ray crystallography is the study of crystal structures through X-ray diffraction techniques. When an X-ray beam bombards a crystalline lattice in a given orientation, the beam is scattered in a definite manner characterized by the atomic structure of the lattice. This phenomenon, known as X-ray diffraction, occurs when the wavelength of X-rays and the interatomic distances in the lattice have the same order of magnitude. In 1912, the German scientist Max van Laue predicted that crystals exhibit diffraction qualities. Concurrently, W. Friedrich and P. Knipping created the first photographic diffraction patterns. A year later, Lawrence Bragg successfully analyzed the crystalline structures of potassium chloride and sodium chloride using X-ray crystallography, and developed a rudimentary treatment for X-ray/crystal interaction (Bragg''s Law). Bragg''s research provided a method to determine a number of simple crystal structures for the next 50 years. In the 1960s, the capabilities of X-ray crystallography were greatly improved by the incorporation of computer technology. Modern X-ray crystallography provides the most powerful and accurate method far determining single-crystal structures. Structures containing 100-200 atoms now can be analyzed on the order of 1-2 days, whereas before the 1960s a 20-atom structure required 1-2 years far analysis. Through X-ray crystallography the chemical structure of thousands of organic, inorganic, organometallic, and biological compounds are determined every year.\n\nWhich of the fallowing factors are consistent with the theory of X-ray crystallography?', NULL, NULL, NULL, E'X-rays are scattered according to the atomic structure of the crystal lattice.\nThe process can be used to determine the chemical structure of biological compounds.', NULL, NULL),
  ('b35687b9-3b89-5d5d-b12a-9995e4093ace'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b35687b9-3b89-5d5d-b12a-9995e4093ace'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the whole system of rules that everyone in a country or society must obey?', 'd10922b4-8633-5947-a7a1-4f8bbd8ca3c5'::uuid, NULL, NULL, E'Law', NULL, NULL),
  ('b358c0aa-2fde-5d4a-99bb-45335c3dbd48'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b358c0aa-2fde-5d4a-99bb-45335c3dbd48'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for someone who teaches students, especially in a school?', 'bd50b7a1-e84d-513b-b65c-c3429914357a'::uuid, NULL, NULL, E'Teacher', NULL, NULL),
  ('b35a460c-56ca-5f5a-bdce-f05eeed09c63'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b35a460c-56ca-5f5a-bdce-f05eeed09c63'::uuid, 1, NULL, TRUE, 0, NULL, E'Economics Today', NULL, '7b2a00d8-4b38-5472-a4e1-023b01d3b038'::uuid, NULL, E'Today, I have come to share the secrets of our success, because rich capitalists like me have never been richer. So the question is, how do we do it? How do we manage to grab an ever-increasing share of the economic pie every year? Is it that rich people are smarter than we were 30 years ago? Is it that we’re working harder than we once did? Are we taller, better looking? Sadly, no. It all comes down to just one thing: economics. Because, here’s the dirty secret. There was a time in which the economics profession worked in the public interest for everyone, but in the neoliberal era, today, they work only for big corporations and billionaires, and that is creating a little bit of a problem. We could choose to enact economic policies that raise taxes on the rich, regulate powerful corporations or raise wages for workers. We have done it before. But neoliberal economists would warn that all of these policies would be a terrible mistake, because raising taxes always kills economic growth, and any form of government regulation is inefficient, and raising wages always kills jobs.', NULL, NULL, NULL),
  ('b35db61f-1d5b-5365-8d5f-541735174b4d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b35db61f-1d5b-5365-8d5f-541735174b4d'::uuid, 1, NULL, TRUE, 0, NULL, E'Black Hole', E'Researchers used the Frontera supercomputer to model for the first time a black hole merger of two black holes with very different sizes (128:1). The research required seven months of constant computation. The results predict the gravitational waves such a merger would produce, as well as characteristics of the resulting merged black hole.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b35eac4e-b914-52ff-9442-1759669d3d1e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b35eac4e-b914-52ff-9442-1759669d3d1e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7c270678-8638-50d3-8693-1ed5a51b1ce9'::uuid, NULL, NULL, E'When houses don''t sell, it can make the whole economy bad.', NULL, NULL),
