  ('b37418ba-c373-535b-95a6-085f1083e2e5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b37418ba-c373-535b-95a6-085f1083e2e5'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9cc6ea03-2b3f-5b03-a755-a5a6a3373ccc'::uuid, NULL, E'This office is highly associated with your academic life on campus.', NULL, NULL, NULL),
