  ('b411da0e-073f-554a-ae59-037ab9384eb1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b411da0e-073f-554a-ae59-037ab9384eb1'::uuid, 1, NULL, TRUE, 0, NULL, E'Baby Carer', E'You have a new baby and find it challenging to manage cooking and taking care of the baby simultaneously. You want to ask a friend for advice on how they manage to balance cooking with baby care. How do you approach this conversation and what specific questions do you ask to get helpful tips?', '5ba7ea36-28ae-55af-b4f9-45450781d0dd'::uuid, NULL, NULL, NULL, NULL, NULL),
  ('b414877a-c905-5926-88bf-d02e622d01ac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b414877a-c905-5926-88bf-d02e622d01ac'::uuid, 1, NULL, TRUE, 0, NULL, E'Wildfires', E'Extratropical forests are globally significant because they store vast quantities of carbon in vegetation and permafrost soils. Approximately 91 per cent of these forests in the northern hemisphere are underlain by permafrost. When fires occur in these regions, they emit large amounts of carbon dioxide (CO2) and other greenhouse gases compared to other regions.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b41b3af3-c46c-5e15-84f1-c6fe652185af'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b41b3af3-c46c-5e15-84f1-c6fe652185af'::uuid, 1, NULL, TRUE, 0, NULL, E'Attractiveness', E'A new study found that while a ''beauty premium'' exists across professions, it''s partially because attractive people develop distinct traits as a result of how the world responds to their attractiveness. They build a greater sense of power and have more opportunities to improve nonverbal communication skills throughout their lives.', NULL, NULL, NULL, NULL, NULL, NULL),
