  ('b429165e-b56c-538a-bc4c-490809b8e486'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b429165e-b56c-538a-bc4c-490809b8e486'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '75f71b98-9479-5161-bc7a-75e8b7848a8d'::uuid, NULL, NULL, E'Today, scientists found out a lot from many different studies.', NULL, NULL),
  ('b4320dfa-4a70-508a-8c3d-f2f51d75eeed'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b4320dfa-4a70-508a-8c3d-f2f51d75eeed'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6e743155-70ce-5d70-807a-b1a21647c632'::uuid, NULL, NULL, E'Scientists use new technologies in labs.', NULL, NULL),
  ('b4347bfb-74f3-58dc-ae67-25e2a3369480'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b4347bfb-74f3-58dc-ae67-25e2a3369480'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the plant that grows in the desert and has sharp points?', '77e9f90b-a788-5298-bb02-38f028321c89'::uuid, NULL, NULL, E'Cactus / cacti', NULL, NULL),
  ('b434c9be-5fae-5f3c-9dc3-60b650afe041'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b434c9be-5fae-5f3c-9dc3-60b650afe041'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f37fe8c7-57fb-5c13-82ab-4a650736e8c7'::uuid, NULL, NULL, E'The meeting has been brought forward from May to April.', NULL, NULL),
  ('b4350848-7d2b-5029-b17f-be04b0681a92'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b4350848-7d2b-5029-b17f-be04b0681a92'::uuid, 1, NULL, TRUE, 0, NULL, E'Problems in Research Paper', NULL, 'a52ea955-6682-5843-81de-ef61c5535285'::uuid, NULL, E'I''m sure you realize that your research papers are due in six weeks. I''ve looked at your proposed topics and made comments about them. The most frequent problem was proposing too broad a topic. Remember, this is only a fifteen-page paper. As I return your topic papers, I''d like to look over the schedule which sketches out what we''ll do during the next two weeks. Today is Monday; by Friday, I want your preliminary outline. Please be sure to incorporate the suggestions I''ve made on your topics in your outlines. Next week I''ll have a conference with each of you. I''ve posted a schedule on my office door. Sign your name to indicate the time you''re available for an appointment. In the conference, we''ll discuss your preliminary outline. Then you can make the necessary revisions and hand in your final outline, which is due two weeks from today. Use the outline style in your textbook and remember it should be no more than two pages long. Be sure to begin with a thesis statement, that is, with a precise statement of the point you intend to prove and include a conclusion. Have you got all that? Your two-page preliminary outlines are due at the end of this week and the final outlines are due after your conferences. Follow the textbook style and include a thesis statement and a conclusion.', NULL, NULL, NULL),
  ('b439ed8a-d0e2-529a-8683-8e5f98e438ec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b439ed8a-d0e2-529a-8683-8e5f98e438ec'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What device can be used to take photos?', '84a1f494-a4ee-506d-b3a2-6c8f167590b2'::uuid, NULL, NULL, E'Camera', NULL, NULL),
  ('b43c5f5b-7103-571f-81cb-43c44c8e88cf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b43c5f5b-7103-571f-81cb-43c44c8e88cf'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b0a90088-075d-5172-925c-83482d023f33'::uuid, NULL, E'I met him on a flight from London to Paris.', NULL, NULL, NULL),
  ('b449a886-aa08-5447-999e-fc315ea67763'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b449a886-aa08-5447-999e-fc315ea67763'::uuid, 1, NULL, TRUE, 0, NULL, E'Behavioral Science', E'Behavioral and social sciences research helps predict, prevent, and manage illness — in individuals and in whole populations. This research also helps people change their behaviors, understand treatments, and learn how to stick with them. Society''s role is significant, too: access to health care affects decision-making and behavior.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b44c8215-bef9-549e-829d-40b1c7b433e4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b44c8215-bef9-549e-829d-40b1c7b433e4'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '82015b73-cefa-5ae1-acd9-3b4f78800f91'::uuid, NULL, E'Please write your name on the essay cover sheet.', NULL, NULL, NULL),
  ('b44e5e5a-1d8e-5ff7-8edc-7d65d66cb127'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b44e5e5a-1d8e-5ff7-8edc-7d65d66cb127'::uuid, 1, NULL, TRUE, 0, NULL, E'Music', E'Even when we may not be aware of it, hearing music can affect our bodies as well as our minds. But are the physiological effects of music unique to one culture or are they more general?\nTo find out, researchers enlisted 40 Canadians from downtown Montreal and 40 Pygmies from the Congo rainforest. All the volunteers listened to musical clips from the movies Psycho, Star Wars and Schindler''s List, and to music from Pygmy culture. As the participants listened, the researchers observed their emotional reactions, as well as psychophysiological responses like changes in heart rate, breathing rate and palm-sweat production. The two groups disagreed about whether a particular musical selection was happy or sad. But they all had similar levels of arousal, as measured by their psychophysiological responses. These findings suggest that some aspects of how we react to music are universal, rather than strictly cultural. The study is in the journal Frontiers in Psychology.\n\nWhich of the following statements are true in this passage?', '98f503ae-9e19-5ac9-880a-c90b81979fbd'::uuid, NULL, NULL, E'Music can cross cultural boundaries.\nThe two groups of volunteers had different emotions about specific music.', NULL, NULL),
  ('b44ef520-c5de-5f91-bd77-af3536ad72b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b44ef520-c5de-5f91-bd77-af3536ad72b2'::uuid, 1, NULL, TRUE, 0, NULL, E'Space War', E'Space war. Listen to part of a lecture in an international politics class and answer the questions space became another arena for competition. After the soviet union launched sputnik, an artificial satellite, in nineteen fifty seven, Americans felt humiliated. The soviets launched a rocket that could have easily carried a nuclear bomb. The united states did not even launch its first satellite, explorer one until nineteen fifty eight. The already gloomy public mood took a turn for the worse when the soviets placed the first man in orbit in nineteen sixty one. President Kennedy''s answer to this was to commit the united states to land a man on the moon and bring him back before this decade is out. In august nineteen sixty two. John H Glenn Junior was the first American to orbit the earth in the mid nineteen sixties. US scientists used the gemini program to look at the effects of extended space flight on man gemini latin for twins carried two astronauts, one more than the earlier mercury series and one less than the Apollo spacecraft. Gemini achieved several first eight-day mission in August 1965, the longest spaceflight at that time, and in November nineteen sixty six, the first automatically controlled reentry into the earth''s atmosphere. Gemini also accomplished the first manned linkup of two spacecraft in flight, as well as the first u s walks in space. The Apollo project achieve Kennedy''s goal in july nineteen sixty nine, with hundreds of millions of television viewers watching around the world. Neil Armstrong became the first human to walk on the surface of the moon.\n\nWhich of the following were achieved by Gemini?', '80d8f8f6-6988-58de-a75f-dae1b329b440'::uuid, NULL, NULL, E'The first manned linkup of two spacecraft.\nThe first eight-day mission in space.', NULL, NULL),
  ('b45a0245-ba6e-560c-a946-a7db7db3eb13'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b45a0245-ba6e-560c-a946-a7db7db3eb13'::uuid, 1, NULL, TRUE, 0, NULL, E'Rice Cultivation', E'A potentially more sustainable choice in rice cultivation could be the development of a new rice breed that combines the traits of an annual Asian rice variety and a perennial African rice variety. This hybrid rice has demonstrated impressive performance, producing grain continuously for eight consecutive harvests over a span of four years.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b467f997-3ac3-53db-a6fe-23838fce5afc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b467f997-3ac3-53db-a6fe-23838fce5afc'::uuid, 1, NULL, TRUE, 0, NULL, E'Galapagos Islands', E'The Galapagos Islands offer a unique glimpse into an untouched paradise. {{1}} many other islands, these haven''t succumbed to the homogenizing forces of globalization. Instead, strict conservation efforts have painstakingly preserved the islands'' remarkable biodiversity, making them a living museum of natural history. From the lumbering giant tortoises that inspired Charles Darwin''s theories of evolution to the playful sea lions basking on volcanic rocks, the Galapagos {{2}} with life found nowhere else on Earth. With tourism carefully managed and {{3}} to specific areas, the islands maintain a delicate balance {{4}} showcasing their wonders and safeguarding their ecological treasures. Unlike many countries obsessed with material growth, the Galapagos prioritize well-being. Their focus isn''t solely on GDP but on a more holistic measure: the "Gross Island Happiness" (GIH). This unique approach considers not just economic prosperity but also environmental sustainability, cultural preservation, and the overall well-being of both islanders and the diverse species they {{5}} their home with.', NULL, NULL, NULL, E'1.Unlike, 2.teem, 3.restricted, 4.between, 5.share', NULL, NULL),
  ('b473b304-1989-5268-9908-e3a137f5d100'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b473b304-1989-5268-9908-e3a137f5d100'::uuid, 1, NULL, TRUE, 0, NULL, E'Spanish', E'Spanish is spoken by more than 300 million people in over 20 countries and is rapidly becoming one of the most popular {{1}} for language learners around the world. A popular course for beginners, Suenos World Spanish is designed to {{2}} the varied needs of adult learners, {{3}} learning at home or in a class. From the very beginning it encourages you to develop your listening and speaking skills with confidence and {{4}} many opportunities to practice reading in Spanish. Using the extensive {{5}} of media available, from the course book to the audio CDs or cassettes, to the popular accompanying television series and free online {{6}} , Suenos World Spanish can help you reach the equivalent level of a first qualification, such as GCSE.', NULL, NULL, NULL, E'1.choices, 2.meet, 3.whether, 4.provides, 5.range, 6.activities', NULL, NULL),
  ('b477e3ff-8935-56a7-9c58-f0e4c6f00cbc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b477e3ff-8935-56a7-9c58-f0e4c6f00cbc'::uuid, 1, NULL, TRUE, 0, NULL, E'Systemic Errors', NULL, '25896b6e-8ffc-5b3f-b5d8-0d553fc4db27'::uuid, NULL, E'And systemic errors don’t just appear in matters of human judgement. From 1993-2008, the same female DNA was found in multiple crime scenes around Europe, incriminating an elusive killer dubbed the Phantom of Heilbronn. But the DNA evidence was so consistent precisely because it was wrong. It turned out that the cotton swabs used to collect the DNA samples had all been accidentally contaminated by a woman working in the swab factory. In other cases, systematic errors arise through deliberate fraud, like the presidential referendum held by Saddam Hussein in 2002, which claimed a turnout of 100% of voters with all 100% supposedly voting in favor of another seven-year term. When you look at it this way, the paradox of unanimity isn’t actually all that paradoxical. Unanimous agreement is still theoretically ideal, especially in cases when you’d expect very low odds of variability and uncertainty, but in practice, achieving it in situations where perfect agreement is highly unlikely should tell us that there’s probably some hidden factor affecting the system. Although we may strive for harmony and consensus, in many situations, error and disagreement should be naturally expected. And if a perfect result seems too good to be true, it probably is.', NULL, NULL, NULL),
  ('b47aa68d-ce2c-5dce-a99e-ba9236a71248'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b47aa68d-ce2c-5dce-a99e-ba9236a71248'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the dark areas visible on the Sun''s surface?', '1c4a8d9a-7271-5691-be16-47cf00758518'::uuid, NULL, NULL, E'Sunspots / Spots / Sun spots', NULL, NULL),
