  ('b4ab65e2-e2da-5b06-900b-2cd370ff183b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b4ab65e2-e2da-5b06-900b-2cd370ff183b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '96ddfeeb-edab-5d18-93d4-680da5be5f61'::uuid, NULL, NULL, E'Some of our graduates are deficient in mathematics skills.', NULL, NULL),
  ('b4acb9ba-3036-5957-88a3-dd82e79539e7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b4acb9ba-3036-5957-88a3-dd82e79539e7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ab67a6a4-4a4b-583f-ab27-488c5584ce44'::uuid, NULL, NULL, E'Sleep is believed to play a critical role in storing memories.', NULL, NULL),
  ('b4ad2314-cc53-5726-be1a-1dbe50253303'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b4ad2314-cc53-5726-be1a-1dbe50253303'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '25a8c318-9110-59e6-a706-9437b6f2dd40'::uuid, NULL, E'We are required to submit the assignment before Friday.', NULL, NULL, NULL),
  ('b4b11b93-2a5e-53a7-a613-a00481d1b81f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b4b11b93-2a5e-53a7-a613-a00481d1b81f'::uuid, 1, NULL, TRUE, 0, NULL, E'Virtual Assistants', E'Virtual assistants have become increasingly sophisticated -- and more human-like -- since the days when Clippy asked if you needed help with your document. These assistants are intended to make programs and apps easier to use, but research suggests that human-like virtual assistants may actually deter some people from seeking help on tasks that are supposed to measure achievement.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b4c362e2-6309-5829-aca7-45c3ef21a060'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b4c362e2-6309-5829-aca7-45c3ef21a060'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which is the last month of the year?', '1c9d0b95-25f7-5b6d-b3df-dfb7f5a6d9a6'::uuid, NULL, NULL, E'December', NULL, NULL),
  ('b4c65629-2703-540d-abc2-20409b7f15ff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b4c65629-2703-540d-abc2-20409b7f15ff'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a large system of stars, gas, and dust held together by gravity?', '586f5110-2623-5d42-9555-e2765baa05a0'::uuid, NULL, NULL, E'Galaxy', NULL, NULL),
  ('b4c90d6a-0cf4-5034-9317-44126b326a09'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b4c90d6a-0cf4-5034-9317-44126b326a09'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '468077cb-7f4f-5778-b5e9-11fd3379aef6'::uuid, NULL, E'He was regarded as the foremost economist at that time.', NULL, NULL, NULL),
  ('b4d4448d-0e30-5fa1-bb9e-b00a0b875a17'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b4d4448d-0e30-5fa1-bb9e-b00a0b875a17'::uuid, 1, NULL, TRUE, 0, NULL, E'Travel & Tourism Industry', E'Jobs generated by Travel & Tourism are spread across the economy in retail, construction, manufacturing and telecommunications, as well as directly in Travel & Tourism companies. These jobs employ a large proportion of women, minorities and young people; are predominantly in small and medium sized companies; and offer good training and transferability. Tourism can also be one of the most effective drivers for the development of regional economies. These patterns apply to both developed and emerging economies. There are numerous good examples of where Travel & Tourism is acting as a catalyst for conservation and improvement of the environment and maintenance of local diversity and culture. Travel & Tourism creates jobs and wealth and has tremendous potential to contribute to economically, environmentally and socially sustainable development in both developed countries and emerging nations. It has a comparative advantage in that its start up and running costs can be low compared to many other forms of industry development. It is also often one of the few realistic options for development in many areas. Therefore, there is a strong likelihood that the Travel & Tourism industry will continue to grow globally over the short to medium term.', NULL, NULL, E'Jobs generated by Travel & Tourism are spread across the economy, which can also be one of the most effective drivers for the development of regional economies, and the Travel & Tourism industry will continue to grow globally over the short to medium term.', NULL, 5, 75),
  ('b4dbce44-5820-5ea4-a5dd-e30e6f1be9eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b4dbce44-5820-5ea4-a5dd-e30e6f1be9eb'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '22a69c89-31dd-56ab-bd30-a50c67b68c0a'::uuid, NULL, E'Most of the student advisors are extremely helpful.', NULL, NULL, NULL),
  ('b4ddb2a0-a218-5b37-819c-76a5b6017744'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b4ddb2a0-a218-5b37-819c-76a5b6017744'::uuid, 1, NULL, TRUE, 0, NULL, E'Importance of Soil', E'It''s very easy to forget about what''s in the ground beneath our feet and why it''s so important to protect it. One tablespoon of soil contains more organisms than there are people on Earth; billions of bacteria, fungi and other microorganisms combine with minerals, water, air and organic matter to create a living system that supports plants and, in turn, all life. Healthy soil can store as much as 3,750 tons of water per hectare, reducing the risk of flooding, and the International Panel on Climate Change (IPCC) has said that 89% of all agricultural emissions could be mitigated if we improved the health of our soil.\nGood soil management also increases disease resistance in livestock and ultimately drives profits for farmers - yet soil and its impact on the health of our animals has, over recent decades, been one of the most neglected links in UK agriculture. Over the last 50 years, agriculture has become increasingly dependent on chemical fertilizers, with applications today around 10 times higher than in the 1950s. Farmers often think the chemical fertilizer NPK (nitrogen, phosphorous and potassium) provides all the nutrition a plant requires, but it also has a detrimental effect on the long-term health of the land: research suggests there are fewer than 100 harvests left in many of the world''s soils.', NULL, NULL, E'Soil contains many organisms, which create a living system that supports plants and all life, and good soil management also increases disease resistance in livestock and ultimately drives profits for farmers, yet soil and its impact on the health of our animals has been one of the most neglected links in UK agriculture.', NULL, 5, 75),
