  ('b54e98c7-175e-5e02-b3a6-3ba37906e3dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b54e98c7-175e-5e02-b3a6-3ba37906e3dd'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the psychological term for a persistent and irrational fear of a specific object, activity, or situation?', 'c10fdc8d-15c6-535a-85aa-838c6b37becb'::uuid, NULL, NULL, E'Phobia', NULL, NULL),
  ('b55152ca-9b51-5cc9-88b5-1925d7c1e709'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b55152ca-9b51-5cc9-88b5-1925d7c1e709'::uuid, 1, NULL, TRUE, 0, NULL, E'DNA', NULL, '3fb19ef9-a1ad-52c5-9df6-369a4aedf922'::uuid, NULL, E'In biology, genes play an important role because they decide the protein produced inside the cells. In simple terms, genes contain the information needed for cells to produce proteins, which are essential for the structure and function of living organisms. However, the process from genes to protein is not simple. It is a complex process involving several stages, where genetic information is copied and transformed into proteins that perform different tasks in the body. Proteins are considered the fundamental building blocks of all organisms. They help form body structures and support many biological activities. Without proteins, living things would not be able to grow, repair themselves, or maintain normal functions. The genetic information is stored in DNA, which is shown in the picture. DNA looks like a chain, with many connected parts carrying important instructions. These instructions are passed from genes to proteins, creating the foundation of life and biological development.', NULL, NULL, NULL),
  ('b551c0b3-711d-55cf-88e7-003bd7885412'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b551c0b3-711d-55cf-88e7-003bd7885412'::uuid, 1, NULL, TRUE, 0, NULL, E'Death Stars', E'In a bone-chilling event two weeks ago, astronomers caught a star {{1}} a nearby black hole, or perhaps a neutron star, and then getting eaten by its {{2}} meal. The {{3}} spectacular explosion left behind a black hole. Astronomers had {{4}} that such a star-eat-star supernova was possible, but had never observed one.', NULL, NULL, NULL, E'1.swallowing, 2.own, 3.resulting, 4.theorized', NULL, NULL),
  ('b559d62a-520b-5532-93cd-01aed329635a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b559d62a-520b-5532-93cd-01aed329635a'::uuid, 1, NULL, TRUE, 0, NULL, E'Classic', E'One of the most important things to remember is that "classic" does not necessarily translate to "favorite" or "bestselling". Literature is instead considered classic when it has stood the test of time and it stands the test of time when the artistic {{1}} it expresses - be it an expression of life, truth, beauty, or anything about the universal human condition - continues to be relevant and continues to inspire emotional responses, no matter the period in which the work was {{2}} . Indeed, classic literature is considered as such {{3}} book sales or public popularity. That said, classic literature {{4}} merits lasting recognition - from critics and other people in a position to influence such decisions - and has a universal appeal. And, while effective use of language - as well as technical excellence - is a must, not everything that is well-written or is {{5}} by technical achievement or critical acclaim will automatically be considered a classic. Conversely, works that have not been {{6}} or received positively by the writer''s contemporaries or critics can still be considered as classics.', NULL, NULL, NULL, E'1.quality, 2.written, 3.regardless of, 4.usually, 5.characterized, 6.acknowledged', NULL, NULL),
  ('b55a6fb3-550f-5c77-830a-a0c6f4b2c1c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b55a6fb3-550f-5c77-830a-a0c6f4b2c1c8'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9bb72b43-e6e8-54e8-96c6-3036f7add17a'::uuid, NULL, E'A renowned economist is selected to have a speech tonight at eight.', NULL, NULL, NULL),
  ('b560b9b3-8806-534d-9f23-cf88d3111ae8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b560b9b3-8806-534d-9f23-cf88d3111ae8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'There are several customers and a waiter pointing at the menu, what are they doing?', 'f714770d-1032-55eb-bcf5-6292fd4d7eb4'::uuid, NULL, NULL, E'Order / ordering', NULL, NULL),
