  ('b58a20f6-c4c5-5cde-b209-fc76e751a9c9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b58a20f6-c4c5-5cde-b209-fc76e751a9c9'::uuid, 1, NULL, TRUE, 0, NULL, E'Rental Assistance', E'Rental assistance programs often cover a portion of a tenant''s rent, with the amount of {{1}} varying based on the individual''s income and the {{2}} rent in the area. In certain cases, these programs offer direct payment to landlords, reducing the financial {{3}} on low-income tenants. However, like housing agencies covering utility costs, these programs have their challenges, such as limited funding and long waiting {{4}} , making it difficult for all eligible families to receive assistance.', NULL, NULL, NULL, E'1.aid, 2.average, 3.burden, 4.lists', NULL, NULL),
  ('b598613b-9948-5e3d-b213-78e9cde36e94'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b598613b-9948-5e3d-b213-78e9cde36e94'::uuid, 1, NULL, TRUE, 0, NULL, E'T-shirt', E'How does a T-shirt originally sold in a U.S. shopping mall to {{1}} an American sports team end up being worn by an African teen? Globalization, consumerism, and recycling all {{2}} to connect these scenes. Globalization has made it possible to produce clothing at increasingly lower prices, prices so low that many consumers consider this clothing to be {{3}} . Some call it ''fast fashion'', the clothing {{4}} of fast food.', NULL, NULL, NULL, E'1.promote, 2.converge, 3.disposable, 4.equivalent', NULL, NULL),
  ('b5a5b437-854f-57ba-a268-bc788b6aa3fa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b5a5b437-854f-57ba-a268-bc788b6aa3fa'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a4c53618-bf17-5b85-afd6-23735ea2508c'::uuid, NULL, E'The bus right out front will take you to London.', NULL, NULL, NULL),
  ('b5a71705-272b-52d5-a2c1-fe6bc43653c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b5a71705-272b-52d5-a2c1-fe6bc43653c0'::uuid, 1, NULL, TRUE, 0, NULL, E'Missing Books', E'You''re leading a community book club, and during this month''s meeting, you discover several books are missing from the club''s library. You want to address the issue respectfully, reminding members to return books on time for everyone''s benefit. What would you say to your members?', 'd790e2c1-d3b4-5775-856b-0f760a1edcac'::uuid, NULL, E'Hey guys, hope you’re all enjoying our picks! I’ve noticed a few of our shared books haven’t made their way back to our library. Totally understand things can slip our minds, but let’s try to keep track and return them when done. This way, everyone gets a chance to enjoy. If you’ve got a book or two, no worries, just bring them to our next meet-up. Maybe we can set up a quick check-in system for our books?', NULL, NULL, NULL),
  ('b5a7e6f4-8251-5308-a0c5-d2b6f54d57a3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b5a7e6f4-8251-5308-a0c5-d2b6f54d57a3'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How many languages can a monolingual person speak?', '67bee0ef-f3a9-55ca-af5d-33e7a1021833'::uuid, NULL, NULL, E'One', NULL, NULL),
