  ('b5b400e0-caa0-5f0b-9965-fe75577ffaa1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b5b400e0-caa0-5f0b-9965-fe75577ffaa1'::uuid, 1, NULL, TRUE, 0, NULL, E'Becoming Carbon-neutral', E'You used to think that being green was a luxury for your company, but climate change has made you realize that you can no longer ignore it. The buzz is about becoming carbon-neutral, but where do you start? Consider your drivers. Do you want to become carbon-neutral for marketing reasons, for financial reasons or to help save the planet?', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b5b8df8a-7ce2-523d-a7c6-7c5ae6ce177b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b5b8df8a-7ce2-523d-a7c6-7c5ae6ce177b'::uuid, 1, NULL, TRUE, 0, NULL, E'Noble Gas', E'The six gases: helium, neon, argon, krypton, xenon and radon have a myriad of modern uses. When they were first discovered, their strangely stand-offish properties were a mystery.\nUniquely stable, they {{1}} to participate in no chemical reactions. But by understanding the stability of the noble gases, physicists discovered the key to chemical bonding {{2}} . Dmitri Mendeleev added the noble gases to his periodic table in 1902, where he arranged the elements in rows and columns {{3}} to their atomic weight.\nMendeleev was able to see repeating (or periodic) patterns in their properties. The noble gases appeared {{4}} in the periodic table, occurring in every eighth position, at least amongst the lighter elements.', NULL, NULL, NULL, E'1.seemed, 2.itself, 3.according, 4.regularly', NULL, NULL),
  ('b5b93718-d2d9-5ee6-8b4f-2e4c9a73c709'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b5b93718-d2d9-5ee6-8b4f-2e4c9a73c709'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a baby bear?', '44136d51-9c6f-5597-b8a2-74aa002a9b4e'::uuid, NULL, NULL, E'Cub', NULL, NULL),
  ('b5bda8c0-9c26-552f-bc86-6237ddf7db01'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b5bda8c0-9c26-552f-bc86-6237ddf7db01'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '88925c14-ec1e-52af-9918-0d800bbb9920'::uuid, NULL, E'We''ve decided to ask you to write four short pieces of coursework this year.', NULL, NULL, NULL),
