  ('b5c72204-df73-51ad-85f4-d58136d50222'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b5c72204-df73-51ad-85f4-d58136d50222'::uuid, 1, NULL, TRUE, 0, NULL, E'Animals’ Role', E'Animals have played a major role in human’s lives throughout history. Today, scientific research is trying to {{1}} the positive aspects of living with companion animals. Animals have been used as an {{2}} form of treatment for many years. More recently it has been discovered that owning a pet can help lower people’s blood pressure, {{3}} the chances of living after a heart attack, keep people more active and provide more satisfaction with life. It is {{4}} that this happens because pets help people become more social, provide a means to give and receive {{5}} , and help connect us with the natural world.', NULL, NULL, NULL, E'1.discover, 2.alternative, 3.enhance, 4.theorized, 5.affection', NULL, NULL),
  ('b5cd6928-b1fc-5ad6-8e01-a0ab37e3b1e6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b5cd6928-b1fc-5ad6-8e01-a0ab37e3b1e6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3ee49208-1b94-5b3d-9b0a-ccda2bf7cdbe'::uuid, NULL, NULL, E'Students may only park their cars in authorized university parking spaces.', NULL, NULL),
  ('b5d7b61e-6d26-5eb4-b526-b80ae20f824d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b5d7b61e-6d26-5eb4-b526-b80ae20f824d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the area of art concerned with arranging and composing dance movements and patterns?', 'd069ee34-a972-59b2-937a-169f6c008e92'::uuid, NULL, NULL, E'Choreography', NULL, NULL),
  ('b5d8fef0-582d-5792-8117-02dfc038a307'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b5d8fef0-582d-5792-8117-02dfc038a307'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1d1e330f-4be3-50bc-ba61-4fd4b65cf38c'::uuid, NULL, NULL, E'There are still some tickets available for the concert next Wednesday.', NULL, NULL),
  ('b5dea7c0-628b-52be-97a3-a90f3356c69f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b5dea7c0-628b-52be-97a3-a90f3356c69f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '828c87d1-b843-5d47-82f2-7c784987309f'::uuid, NULL, NULL, E'Sound cannot travel in a vacuum where no air exists.', NULL, NULL),
  ('b5e36963-abcf-5902-aab9-42fb649c2ad8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'b5e36963-abcf-5902-aab9-42fb649c2ad8'::uuid, 1, NULL, TRUE, 0, NULL, E'Bermuda', E'No scientific derivations prove any aura of mystery enveloping the Bermuda Triangle. Many theories pertaining to extraterrestrials, evil humans, anti gravity, magnetic field, oceanic flatulence and other technical sounding and weird hypothesis have been put forth. But a few investigators contrive ill luck, pirates, incompetence of navigators to be the cause of these missing ships and planes. A few die hard rationalists believe that there is no mystery element that needs to be explained as the figures pertaining to wrecks is common when there is such exceeding traffic on sea.\n\nWhat main point is the author trying to make?', NULL, NULL, NULL, E'The missing ships and planes around the Bermuda Triangle have aroused public curiosity.', NULL, NULL),
  ('b5e9858b-c33e-58b4-82ed-dc22dbaf6b73'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b5e9858b-c33e-58b4-82ed-dc22dbaf6b73'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1f157080-aada-559f-86ac-ded305bd49e3'::uuid, NULL, NULL, E'Affordable housing is a pressing concern for all members of society.', NULL, NULL),
  ('b5efb265-8dd6-527f-9600-b1672942eea5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'b5efb265-8dd6-527f-9600-b1672942eea5'::uuid, 1, NULL, TRUE, 0, NULL, E'Bats', NULL, NULL, NULL, NULL, E'2, 4, 1, 3', NULL, NULL),
  ('b5fa929b-3147-57e6-9350-4f517891baa3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b5fa929b-3147-57e6-9350-4f517891baa3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a0bce5a5-80c5-51eb-9986-e5a0812ffea4'::uuid, NULL, NULL, E'Some of these features were part of the previous system.', NULL, NULL),
  ('b6005c1f-5203-595d-ae48-dd2ec134f059'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b6005c1f-5203-595d-ae48-dd2ec134f059'::uuid, 1, NULL, TRUE, 0, NULL, E'Placebos', NULL, '7c9d2fdb-6498-560a-9ab2-8f78aae7985d'::uuid, NULL, E'So, you see, physical illness can have psychological causes. Now, we just have time to introduce another interesting example of the interaction between the mind and the body, placebos. Placebos—maybe you''ve heard them called sugar pills—are harmless substances, not always sugar, that are used routinely on groups of sick people in experiments. These experiments test the effectiveness of new drugs. One group is given the new drug, the other group is given a placebo, and the results are measured. As you might guess, some of the people who receive the new drug get better. Surprisingly, however, some of the placebo group also get better. Why? Well, it''s an interesting question, one which doctors can''t quite answer. Some of the group may have gotten better on their own, without any treatment at all, but research has shown that the very act of taking a medication that you think will make you better, often does make you feel better. Have you ever taken an aspirin and felt better in five minutes? Aspirin doesn''t work that fast, does it? Basically, if you believe you will get better, sometimes you do. The history of how doctors and healers have used the mind-body connection to cure people is long and interesting, but I see that it''s time to chose, so I''ll have to cover this in the next class. You''ll have to hold your questions on this topic till then. Before you go, I have some handouts for you concerning the midterm exams next week.', NULL, NULL, NULL),
  ('b6027b6b-a73f-5306-9384-7aaa8ac36a97'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b6027b6b-a73f-5306-9384-7aaa8ac36a97'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'cba17623-2f28-5411-ad33-d67e8c22d06a'::uuid, NULL, E'The teacher wants the children to feel confident about asking questions.', NULL, NULL, NULL),
  ('b6038746-f7b4-5f68-88ba-ab1b37108f20'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b6038746-f7b4-5f68-88ba-ab1b37108f20'::uuid, 1, NULL, TRUE, 0, NULL, E'Volcano Prediction', E'In general, no single event can be used to predict a volcanic eruption, and thus many events are usually monitored so that taken in total, an eruption can often be predicted. Still, each volcano behaves somewhat differently, and until patterns are recognized for an individual volcano, predictions vary in their reliability. Furthermore, sometimes a volcano can erupt with no precursor events at all.\nAfter the catastrophic eruption of Mount St. Helens on May 18, 1980, a volcanic dome began to grow in the crater. Growth of this dome occurred sporadically, and sometimes small eruptions occurred from the dome. After several years of dedicated monitoring, scientists are now able to predict with increasing accuracy eruptions from this dome. An example is shown in the graphs to the right. In the weeks prior to an eruption on March 19, 1982, the amount of seismic energy released increased, the amount of dome expansion increased, tilt increased, and SO2 emissions increased prior to the event.\nNote that eruption predictions are only possible if constant monitoring of a volcano takes place. Monitoring is an expensive endeavor, and not all active or potentially active volcanoes are monitored. Still, if people living around volcanoes are aware of some of the precursor phenomena they may be able to communicate their findings to scientists and help prevent a pending disaster.', NULL, NULL, NULL, NULL, 5, 75),
  ('b60c0fe7-77b2-5623-a817-859d8f68fd1c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b60c0fe7-77b2-5623-a817-859d8f68fd1c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '61f80950-2397-54f5-949e-8614722df9f5'::uuid, NULL, NULL, E'A summer conference on academic web research is scheduled here next.', NULL, NULL),
  ('b61b5cc0-e506-5d94-87b2-56c3e1d83453'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b61b5cc0-e506-5d94-87b2-56c3e1d83453'::uuid, 1, NULL, TRUE, 0, NULL, E'Napping', E'A large new study has found that people who regularly took a siesta were significantly less likely to die of heart disease. "Taking a nap could turn out to be an important weapon in the fight against coronary mortality," said DimitriosTrichopoulos of the Harvard School of Public Health in Boston, who led the study published yesterday in the Archives of Internal Medicine. The study of more than 23,000 Greek adults -- the biggest and best examination of the subject to date found that those who regularly took a midday siesta were more than 30 percent less likely to die of heart disease. Other experts said the results are intriguing. Heart disease kills more than 650,000 Americans each year, making it the nation''s No. 1 cause of death. "It''s interesting. A little siesta, a little snooze may be beneficial," said Gerald Fletcher, a cardiologist at the Mayo Clinic in Jacksonville, Fla., speaking on behalf of the American Heart Association. "It''s simple, but it has a lot of promise."\nWhile more research is needed to confirm and explore the findings, there are several ways napping could reduce the risk of heart attacks, experts said. "Napping may help deal with the stress of daily living," said Michael Twery, who directs the National Heart Lung and Blood Institute''s National Center on Sleep Disorders Research. "Another possibility is that it is part of the normal biological rhythm of daily living. The biological clock that drives sleep and wakefulness has two cycles each day, and one of them dips usually in the early afternoon. It''s possible that not engaging in napping for some people might disrupt these processes."\nResearchers have long known that countries such as Greece, Italy and Spain, where people commonly take siestas, have lower rates of heart disease than would be expected. But previous studies that attempted to study the relationship between naps and heart disease have produced mixed results. The new study is first to try to fully account for factors that might confuse the findings, such as physical activity, diet and other illnesses. "This study has a number of advantages," Trichopoulos said. He and colleagues at the University of Athens examined 23,681 Greek men and women ages 20 to 86 who had no history of heart disease or any other serious health problem when they enrolled in the study between 1994 and 1999. The researchers asked the participants whether they took midday naps and, if so, how often and for how long. They also asked detailed questions about their health and lifestyles, such as whether they had any illnesses that might make them sleep more, how much exercise they got and what they ate. After an average of more than six years of follow-up, 792 of the study subjects died, including 133 who died of heart disease. Of that group, 94 were nappers. After the researchers accounted for factors that could confuse the issue, they found that those who took naps frequently were 34 percent less likely to die of heart disease than those who did not. The biggest nappers-79 people who took a siesta for 30 minutes or more at least three times a week-had a 37 percent lower risk. Naps appeared to offer the most protection to working men: Those who took midday siestas either occasionally or systematically had a 64 percent lower risk of death from heart disease. Non-working men had a 36 percent reduction in risk. A similar analysis could not be done in women because too few died of heart disease.', NULL, NULL, E'People who regularly took a siesta were significantly less likely to die of heart disease, as napping may help deal with the stress of daily living, which is part of the normal biological rhythm of daily living, so not engaging in napping for some people might disrupt these processes, and naps appeared to offer the most protection to working men.', NULL, 5, 75),
  ('b625c0f9-f9ed-5fd5-bccc-e87780ea2c2d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b625c0f9-f9ed-5fd5-bccc-e87780ea2c2d'::uuid, 1, NULL, TRUE, 0, NULL, E'Scientific Method', E'The logic of the scientific method was set out by John Stuart Mill in 1843 and was {{1}} the method of difference. A simple example of what he {{2}} by this is to take two glasses of water which are identical in every {{3}} . Introduce a few drops of ink into one of these glasses. The water changes color! {{4}} to Mill’s method of difference it is safe to {{5}} that the change in the color of the water is due to the {{6}} of a new factor — the independent variable — in this case, the ink.', NULL, NULL, NULL, E'1.named, 2.meant, 3.respect, 4.According, 5.assume, 6.introduction', NULL, NULL),
  ('b629a5e9-9c08-5977-9571-90f15a0eb34c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b629a5e9-9c08-5977-9571-90f15a0eb34c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the collective name for pencil, eraser and ruler?', '88c18996-c724-578d-8ad0-3cd80e3b256e'::uuid, NULL, NULL, E'Stationery', NULL, NULL),
  ('b629ec56-f8c3-58fd-a3ef-9a4f6679cd7b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b629ec56-f8c3-58fd-a3ef-9a4f6679cd7b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'In a compass, there are four directions, north, south, east, and?', '759a4251-5155-5f41-9b3d-84fff989c77d'::uuid, NULL, NULL, E'West', NULL, NULL),
  ('b62a4a51-22c6-5ee8-b41d-bb8ab8421979'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b62a4a51-22c6-5ee8-b41d-bb8ab8421979'::uuid, 1, NULL, TRUE, 0, NULL, E'British Policy', NULL, 'ae682df3-22ba-5c2f-99f0-8ba1bacecdc4'::uuid, NULL, E'The development of a free and vibrant press is a key aspect of modern society, and its roots are often tied to foundational government policies. A prime example of this can be seen in the British experience. The British press is sophisticated and highly developed. To understand how this came to be, we need to look back to its origins. It came into being in the 18th century. This period was crucial because freedom of speech has been encouraged by the British policy since then.\nIt actively fostered a new culture of public debate and information sharing. The new policy empowered ordinary citizens. People could talk about anything in public places, such as in coffee houses or on streets. There they read newspapers and talked about politics, government policies and military matters. This was revolutionary. The fact that everyday people could openly critique the government and debate national issues in a public forum is a great sign of public freedom.', NULL, NULL, NULL),
  ('b63c0bba-2c58-5ace-a908-13cc8b1c9b14'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b63c0bba-2c58-5ace-a908-13cc8b1c9b14'::uuid, 1, NULL, TRUE, 0, NULL, E'Frogs', NULL, '173fb282-8cd7-5ce7-9ee8-fccc78ffa0fa'::uuid, NULL, E'Frogs are a diverse and largely carnivorous group of short-bodied, tailless amphibians composing the order Anura. The oldest fossil proto frog appeared in the early Triassic of Madagascar, but molecular clock dating suggests their origins may extend further back to the Permian, 265 million years ago. Frogs are widely distributed, ranging from the tropics to subarctic regions, but the greatest concentration of species diversity is found in tropical rain forests. There are approximately 4,800 recorded species, accounting for over 85% of extant amphibian species. They are also one of the five most diverse vertebrate orders. Besides living in fresh water and on dry land, the adults of some species are adapted for living underground or in trees. Adult frogs generally have a carnivorous diet consisting of small invertebrates, but omnivorous species exist and a few feed on fruit. Frogs are extremely efficient at converting what they eat into body mass. They are an important food source for predators and part of the food web dynamics of many of the world''s ecosystems. The skin is semipermeable, making them susceptible to dehydration, so they either live in moist places or have special adaptations to deal with dry habitats. Frogs produce a wide range of vocalizations, particularly in they are breeding season, and exhibit many different kinds of complex behaviors to attract mates, to fend off predators and to generally survive. Frog populations have declined significantly since the 1950s. More than one-third of species are considered to be threatened with extinction and over one hundred and twenty are believed to have become extinct since the 1980s. The number of malformations among frogs is on the rise and an emerging fungal disease, chytridiomycosis, has spread around the world. Conservation biologists are working to understand the causes of these problems and to resolve them. Frogs are valued as food by humans and also have many cultural roles in literature, symbolism and religion.', NULL, NULL, NULL),
  ('b642d7e5-33ef-5824-b803-c6c0cfd75881'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b642d7e5-33ef-5824-b803-c6c0cfd75881'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '621fb7d2-bb09-5d54-84f1-775480baf879'::uuid, NULL, NULL, E'A good academic paper should be clear.', NULL, NULL),
  ('b64cf710-e773-50aa-9fc0-141c594bcfd3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b64cf710-e773-50aa-9fc0-141c594bcfd3'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the direction of the longitude lines on the earth''s surface?', '3dac4658-ecab-529a-8e27-d22165baa306'::uuid, NULL, NULL, E'Vertical', NULL, NULL),
  ('b64d8429-3e76-5de0-abe0-7d8ee672f24b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b64d8429-3e76-5de0-abe0-7d8ee672f24b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '01eb0e56-c390-5b1b-9ca2-896ff0136e71'::uuid, NULL, E'Legal aid is a fundamental part of our system of justice.', NULL, NULL, NULL),
  ('b64eb935-3303-5a33-bb77-18c9f439f8df'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b64eb935-3303-5a33-bb77-18c9f439f8df'::uuid, 1, NULL, TRUE, 0, NULL, E'International Trade', E'The world is shrinking rapidly with the advent of faster communication, transportation, and financial flows. Products developed in one country — Gucci purses, Sony electronics, McDonald’s hamburgers, Japanese sushi, German BMWs — have found enthusiastic acceptance in other countries. It would not be surprising to hear about a German businessman wearing an Italian suit meeting an English friend at a Japanese restaurant who later returns home to drink Russian vodka and watch Dancing with the Stars on TV.\nInternational trade has boomed over the past three decades. Since 1990, the number of multinational corporations in the world has grown from 30,000 to more than 63,000. Some of these multinationals are true giants. In fact, of the largest 150 “economies” in the world, only 81 are countries. The remaining 69 are multinational corporations. Walmart, the world’s largest company, has annual revenues greater than the GDP of all but the world’s 21 largest countries.\nBetween 2000 and 2008, total world trade grew more than 7 percent per year, easily out-stripping GDP output, which was about 3 percent. Despite a dip in world trade caused by the recent worldwide recession, the world trade of products and services last year was valued at more than $12 trillion, about 17 percent of GDP worldwide.\nMany U.S. companies have long been successful at international marketing: McDonald’s, Coca-Cola, Starbucks, GE, IBM, Colgate, Caterpillar, Boeing, and dozens of other American firms have made the world their market. In the United States, names such as Sony, Toyota, Nestlé, IKEA, Canon, and Nokia have become household words. Other products and services that appear to be American are, in fact, produced or owned by foreign companies.', NULL, NULL, E'The world is shrinking rapidly with the advent of faster communication, transportation, and financial flows, so products developed in one country have found enthusiastic acceptance in other countries, and international trade has boomed over the past three decades, while many U.S. companies have long been successful at international marketing.', NULL, 5, 75),
  ('b651af97-21ab-5c8a-8552-3cc6e16b78e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b651af97-21ab-5c8a-8552-3cc6e16b78e1'::uuid, 1, NULL, TRUE, 0, NULL, E'Smoking Happiness', E'On March 18th, we told you that smoking doesn''t make people happy. Well, we hear you ask, what will make me happy? What? What?! Ok, first, relax. Then, take out your wallet. Because {{1}} to a study published in the March 21st issue of Science, giving money to other people is what brings us joy.\nScientists from Boston and British Columbia got to wondering whether money really can buy happiness. They were {{2}} by the fact that over the past 20 or 30 years, people in the US and other developed countries have been making much more money—yet our happiness has pretty much {{3}} . What they found is that money can buy happiness. But only when you spend it on someone else. In one experiment, the scientists asked volunteers to {{4}} their happiness. Then they gave each subject some cash, either 5 or 20 dollars. Half the {{5}} were told to spend the money on themselves. The others were asked to give it away. At the end of the day, the folks who got the biggest boost were the ones who spread the wealth, even if it was only five bucks. So if you want to be happy, here''s a big tip: always leave a big tip.', NULL, NULL, NULL, E'1.according, 2.bothered, 3.flatlined, 4.rate, 5.participants', NULL, NULL),
