  ('b664cc14-909d-53af-94ec-a9cbf47cc6d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b664cc14-909d-53af-94ec-a9cbf47cc6d8'::uuid, 1, NULL, TRUE, 0, NULL, E'Glucose', E'The body uses glucose as its main source of energy. Glucose comes from foods that contain carbohydrates, which is released and absorbed into the bloodstream after food is digested. The glucose in the bloodstream needs to move into body tissues so that cells can use it for energy. Excess glucose is also stored in the liver, or converted to fat.', NULL, NULL, NULL, NULL, NULL, NULL),
