  ('b66647c8-052a-5211-aaef-b2065bd21a3b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b66647c8-052a-5211-aaef-b2065bd21a3b'::uuid, 1, NULL, TRUE, 0, NULL, E'Daydreaming', E'So-called maladaptive daydreamers will compulsively {{1}} in vivid fantasies and daydreaming plots so excessively that it interferes with their ability to {{2}} in daily life. Many discover this ability early on in childhood, realizing fantasy and daydreams can be used to {{3}} distress. By creating an inner world of comfort, they’re able to {{4}} from reality.', NULL, NULL, NULL, E'1.engage, 2.function, 3.regulate, 4.escape', NULL, NULL),
  ('b678d88d-545e-54cb-97f3-362e07f7c5ff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'b678d88d-545e-54cb-97f3-362e07f7c5ff'::uuid, 1, NULL, TRUE, 0, NULL, E'Restaurant', NULL, NULL, NULL, NULL, E'1, 3, 2, 4', NULL, NULL),
  ('b67b73b8-f6b8-5cd4-9863-415d969c308f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b67b73b8-f6b8-5cd4-9863-415d969c308f'::uuid, 1, NULL, TRUE, 0, NULL, E'New Catalyst', E'Now, Northwestern University chemists have developed a new catalyst that quickly, cleanly and completely breaks down Nylon-6 in a matter of minutes -- without generating harmful byproducts. Even better: The process does not require toxic solvents, expensive materials or extreme conditions, making it practical for everyday applications.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b67f298c-0fb1-5f91-afc5-ac53fbead595'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b67f298c-0fb1-5f91-afc5-ac53fbead595'::uuid, 1, NULL, TRUE, 0, NULL, E'SMW', E'Are you going to be more effective and happy as a specialist or as a generalist? Do you find real satisfaction in the precision order and system of a clearly laid out job? Or are you one of those people who tend to grow impatient with anything that looks like a routine job? There are great many careers in which the emphasis is on specialization. You find these careers in engineering and in accounting, in production, in statistical work and in teaching. But there is an increasing demand for people who are able to take in a great area at a glance. There is, in other words, a demand for people who are capable of seeing the forest rather than the trees of making overall.\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '400fc623-d9d0-5f0f-b7b4-3c98f2c71915'::uuid, NULL, NULL, E'judgements', NULL, NULL),
  ('b67f5ef5-9b35-5bcb-9ae9-c085d7a25630'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b67f5ef5-9b35-5bcb-9ae9-c085d7a25630'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2156aeb9-a23e-55a1-b3c2-9de65d326df5'::uuid, NULL, NULL, E'The focus of marketing will be on price and distribution.', NULL, NULL),
