  ('b68ce29e-21c6-5388-ba75-a4399965176d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b68ce29e-21c6-5388-ba75-a4399965176d'::uuid, 1, NULL, TRUE, 0, NULL, E'Astronomy', E'Astronomy is a fascinating field that allows us to explore the mysteries of the universe, from the origins of stars and galaxies to the search for extraterrestrial life. It requires advanced technology such as telescopes and spacecraft, as well as interdisciplinary collaboration between scientists from different fields.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b68d81d1-3bd7-5775-bf9f-02fbe3b12a42'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b68d81d1-3bd7-5775-bf9f-02fbe3b12a42'::uuid, 1, NULL, TRUE, 0, NULL, E'Organizational Culture', E'When everyone in a corporation shares the same values and goals, it’s possible to create a culture of {{1}} respect, collaboration, and support. Companies that have a strong, supportive culture are more likely to attract highly {{2}} , loyal employees who understand and work toward the company’s best {{3}} .', NULL, NULL, NULL, E'1.mutual, 2.qualified, 3.interests', NULL, NULL),
