  ('b69026ef-9188-5e99-8c97-476f444f8a8c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b69026ef-9188-5e99-8c97-476f444f8a8c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do you describe the money that citizens must contribute to the government for public use?', '318638ca-5c94-57b5-b910-3d3d541e5281'::uuid, NULL, NULL, E'Tax / taxes', NULL, NULL),
  ('b69d75b4-3311-53da-901e-f1e61783f82d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b69d75b4-3311-53da-901e-f1e61783f82d'::uuid, 1, NULL, TRUE, 0, NULL, E'Bookkeepers', E'Bookkeepers are strategic partners in financial management. They possess a deep understanding of financial systems, risk management, and regulatory compliance. Bookkeepers provide valuable insights into financial performance, contribute to strategic planning, and assist in the formulation of financial policies. They collaborate with stakeholders across the organization to ensure transparency and accountability in financial reporting.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b69ed366-ce8f-587f-9732-256624d9c3a9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b69ed366-ce8f-587f-9732-256624d9c3a9'::uuid, 1, NULL, TRUE, 0, NULL, E'Flux Theory', E'The three-body problem is one of the oldest and most challenging puzzles in physics, {{1}} to the 17th century. It involves determining the motion of three bodies that interact with each other through gravity or other forces, such as the Earth, the Moon, and the Sun. The problem is {{2}} difficult to solve, as even small changes in the initial conditions can lead to unpredictable and chaotic behavior. To test the Flux theory, the researchers conducted {{3}} computer simulations, tracking millions of scattering events in three-body systems. They were able to measure the chaotic emissivity function and compare it with the flux-based prediction for the chaotic outcome distribution. The results showed a remarkable agreement, with an accuracy of 6% across the entire two-dimensional space of variables {{4}} . The flux-based theory represents a significant advancement in chaos theory, as it offers a more efficient and precise method for calculating chaotic outcome distributions in three-body systems. The theory can also pave the way for further research and discovery in the {{5}} of physics.', NULL, NULL, NULL, E'1.dating back, 2.notoriously, 3.extensive, 4.examined, 5.realm', NULL, NULL),
  ('b6a2b3da-3f0f-502e-9860-e6815a44cd9a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b6a2b3da-3f0f-502e-9860-e6815a44cd9a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '93071908-77c6-5e99-9d6e-1fcbecea995a'::uuid, NULL, NULL, E'The history class has been relocated to the main theater.', NULL, NULL),
