  ('b6be94f1-0829-574d-b0e7-f86ae66fce0d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b6be94f1-0829-574d-b0e7-f86ae66fce0d'::uuid, 1, NULL, TRUE, 0, NULL, E'Population Growth', E'City population has been growing rapidly. To cope with this problem, should we rely on city planners or new policies?', NULL, NULL, NULL, NULL, 200, 300),
  ('b6c70400-9800-593d-8576-1e6c3f456824'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b6c70400-9800-593d-8576-1e6c3f456824'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the force that happens between the relative motion when objects are rubbed against each other?', '338d3564-43f5-5d92-984b-6c749f3ede0f'::uuid, NULL, NULL, E'Friction', NULL, NULL),
  ('b6cb2286-525b-5803-89be-7a92ff6321c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b6cb2286-525b-5803-89be-7a92ff6321c8'::uuid, 1, NULL, TRUE, 0, NULL, E'Advent of Internet', E'Does the advent of Internet change the role of teacher? To what extent do you agree?', NULL, NULL, NULL, NULL, 200, 300),
  ('b6cb53ed-d388-5cb0-94ab-09585702e2ae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', 'b6cb53ed-d388-5cb0-94ab-09585702e2ae'::uuid, 1, NULL, TRUE, 0, NULL, E'Luke Howard', E'Before Luke Howard invented his system for classifying clouds, they had simply been described by their shape and color as each person saw them: they were too changeable and moved too quickly for anyone to think they could be classified in any useful way. Howard had been interested in clouds - and meteorology in general - ever since he was a small boy, and for thirty years kept a record of his meteorological observations. In 1802-1803, he produced a paper in which he named the clouds, or, to be more precise, classified them, claiming that it was possible to identify several simple categories within the various and complex cloud forms. As was standard practice for the classification of plant and animal species, they were given Latin names, which meant that the system could be understood throughout Europe.\nHoward believed that all clouds belonged to three distinct groups; cumulus, stratus and cirrus. He added a fourth category, nimbus, to describe a cloud "in the act of condensation into rain, hail or snow". lt is by observing how clouds change color and shape that weather can be predicted, and as long as the first three types of cloud keep their normal shape there won''t be any rain.\nThis system came to be used across the European continent, and in the 20th century his cloud classification system was adopted, with some additions, as the international standard, but that was not his only contribution to meteorology. He wrote papers on barometers and theories of rain, and what is probably the first textbook on weather. He can also be considered to be the father of what is now called "urban climatology". Howard had realized that cities could significantly alter meteorological elements. One of these he called "city fog". Nowadays we call it "smog", a combination of smoke and fog.\n\nWhich of the following achievements can be attributed to Luke Howard?', NULL, NULL, NULL, E'He was the first to identify and classify different cloud forms.\nHis classification system became used all over the world.\nHe realized that cities could have an effect on the weather.', NULL, NULL),
  ('b6d24bc0-4b8b-5f5c-84d3-631e538d4847'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b6d24bc0-4b8b-5f5c-84d3-631e538d4847'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4871a868-7a59-5d5c-a56c-118e87c03884'::uuid, NULL, NULL, E'A lack of formal education will limit your job opportunities.', NULL, NULL),
  ('b6df2e5e-64d9-502c-91e5-c0a0937c0c08'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b6df2e5e-64d9-502c-91e5-c0a0937c0c08'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the art of producing beautiful handwriting using a brush or a special pen?', 'f3752dee-a269-5033-acdb-c96ff9480eca'::uuid, NULL, NULL, E'Chirography / penmanship / calligraphy', NULL, NULL),
  ('b6df2e90-1a41-59b4-916a-9f1d1da91a10'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b6df2e90-1a41-59b4-916a-9f1d1da91a10'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the chemical name of Gold, Mg, Au or O2?', '7208689b-e8a7-5984-b2dc-33e74dfb9bcb'::uuid, NULL, NULL, E'Au', NULL, NULL),
  ('b6e8aa39-b0ec-55c6-9115-2eeeef87d16e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b6e8aa39-b0ec-55c6-9115-2eeeef87d16e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5b1ca076-db62-5ed0-91e8-ae14325c58eb'::uuid, NULL, E'High-earning parents are more likely to live in a good neighborhood for raising children.', NULL, NULL, NULL),
  ('b6ee0da2-2ff2-5c9c-8e59-1e3ba95fe4bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b6ee0da2-2ff2-5c9c-8e59-1e3ba95fe4bd'::uuid, 1, NULL, TRUE, 0, NULL, E'Biology', E'Biology is the natural science that studies life and living organisms, including their physical structure, chemical processes, physiological mechanisms and evolution. Certain unifying concepts consolidate it into a single and coherent field that recognizes genes as the basic unit of heredity, and evolution as the engine that propels the creation and extinction.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b6ef6d70-d056-549e-9462-7270586ad6e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b6ef6d70-d056-549e-9462-7270586ad6e9'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call the complete control of trade in particular goods or the supply of a particular service?', 'd72ad9ad-85a8-5349-9612-13f61506dbcc'::uuid, NULL, NULL, E'Monopoly', NULL, NULL),
  ('b6f1e669-76de-5f89-9bb3-a2b824441e03'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b6f1e669-76de-5f89-9bb3-a2b824441e03'::uuid, 1, NULL, TRUE, 0, NULL, E'Road to Success', E'It is well that young men should begin at the beginning and occupy the most subordinate positions. Many of the leading businessmen of Pittsburgh had a serious responsibility thrust upon them at the very {{1}} of their career. They were introduced to the broom, and spent the first hours of their business lives sweeping out the office. I notice we have janitors now in offices, and our young men unfortunately miss that {{2}} branch of business education. But if by chance the professional sweeper is {{3}} any morning, the boy who has the {{4}} of the future partner in him will not hesitate to try his hand at the broom. It does not hurt the newest comer to sweep out the office if necessary. I was one of those sweepers myself.', NULL, NULL, NULL, E'1.threshold, 2.salutary, 3.absent, 4.genius', NULL, NULL),
  ('b6f2a809-b1e0-5b7b-9ca2-5c0bb258bdf0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b6f2a809-b1e0-5b7b-9ca2-5c0bb258bdf0'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Who was the first President of the United States?', 'c6053faf-3fc6-5604-a552-eb105089f194'::uuid, NULL, NULL, E'George Washington', NULL, NULL),
  ('b7030282-94f0-5a7c-a49f-99e6c6c0623a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b7030282-94f0-5a7c-a49f-99e6c6c0623a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b909fa9e-8d16-5fde-9cda-74b585404266'::uuid, NULL, NULL, E'The museum shuts down every Thursday morning for the month.', NULL, NULL),
  ('b707436d-acf3-5064-a03c-0e40c4735056'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b707436d-acf3-5064-a03c-0e40c4735056'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '431e3ac6-c580-50cd-ad3e-6a5218a4ab33'::uuid, NULL, E'Speaking one or more foreign languages will be useful in your career.', NULL, NULL, NULL),
  ('b70f6c28-f2b7-51df-8883-3853edf6e318'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b70f6c28-f2b7-51df-8883-3853edf6e318'::uuid, 1, NULL, TRUE, 0, NULL, E'Childhood Mortality', E'In a new study of childhood mortality rates between 1961 and 2010 in the United States and 19 economically similar countries, researchers report that while there''s been overall improvement among all the countries, the U.S. has been slowest to improve. Infants in the U.S. were 76 percent more likely to die.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b71171f5-2842-5d96-bc4b-ddcc26342a31'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b71171f5-2842-5d96-bc4b-ddcc26342a31'::uuid, 1, NULL, TRUE, 0, NULL, E'The Antarctic and the Arctic', E'At the height of summer the Antarctic, tourist ships move gently around the coast. Even 30 years ago such sights would have been unthinkable, but today people are willing to pay large sums of money to see the last real wilderness in the world. In the Arctic, careless human exploitation {{4}} has damaged the fragile ecosystem. Today concerned governments are trying to find ways to develop the region {{2}} caring for the very special natural environment. {{3}} the Antarctic is less accessible than the Arctic, it is still largely undamaged by humans, although holes in the ozone layer above the Antarctic {{1}} discovered. Many people believe that one way to preserve the area is to make the whole region into a world park, with every form of exploitation internationally {{5}} .', NULL, NULL, NULL, E'1.in the past, 2.while, 3.Because, 4.have already been, 5.banned', NULL, NULL),
  ('b7129c22-cf67-59fa-9ff4-bc8c42295745'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b7129c22-cf67-59fa-9ff4-bc8c42295745'::uuid, 1, NULL, TRUE, 0, NULL, E'Multiple Mutations', E'In a point mutation, a single letter of the genetic code changes to another letter. When a protein gets made from that new code, it''ll be {{1}} different from usual. But new research finds that it may be fairly common for {{2}} mutations to happen in DNA simultaneously. Which could make big {{3}} jumps {{4}} {{5}} , without waiting for the changes to accrue over generations. The work is in the journal Current Biology.\nThe researchers did close {{6}} of the genomes of organisms ranging from yeast to fruit flies to the plant Arabidopsis to humans. And they concluded that about three percent of all new mutations must be multiples. A likely explanation is that some polymerase enzyme is {{7}} prone to errors when it''s weaving a strand of DNA.\nHere''s why having multiples could be a big deal. The single mutation-at-a-time view would be like hoping you hit the Pick 4 lottery by getting one number a day for four days. Sadly, what you really get is four losing tickets. But multiple mutations could let you hit the Pick 4 all at once. And win the evolutionary lottery.', NULL, NULL, NULL, E'1.slightly, 2.multiple, 3.evolutionary, 4.possible, 5.immediately, 6.examinations, 7.particularly', NULL, NULL),
  ('b716b970-c264-5c88-885c-72e9db49169f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b716b970-c264-5c88-885c-72e9db49169f'::uuid, 1, NULL, TRUE, 0, NULL, E'Congressional Aides', NULL, '26d44613-7b93-5987-9414-8d94380acb2a'::uuid, NULL, E'We''re going to start today talking about congressional aides, that is, the people who work for our congressional representatives, both in Washington and in the representatives'' local districts. It used to be that members of Congress had a relatively small staff of people working for them, and the role of these people wasn''t of primary importance. But now there are thousands of congressional aides, and they''ve profoundly affected the way the whole government works. Congressional aides work in two different locations: one, in the congressional representatives'' local offices, the districts from which they were elected, and two, in Washington. Staff in the local offices help members of Congress stay in touch with citizens in their districts. These citizens can bring problems in in person, or by mail or phone. This personal connection between the aides and the local people can be helpful when the next election comes around. People remember the help they get from the office of their local congressional representative. But as you know, members of Congress have to spend most of their time in Washington taking care of their legislative duties. Over six thousand new laws are introduced in Congress each session. Without help, representatives would have trouble keeping up with the proposed laws that directly affect their districts. So that''s why the congressional aides play a major role in Washington. They keep their bosses informed about pending legislation, organize hearings, and just keep their local congressional representatives up-to-date and informed on what''s going on in other parts of Congress. Now another thing congressional aides do is to help develop ideas for laws that their bosses can eventually propose to Congress. This can be called the staff''s entrepreneurial function, a bit like a business executive trying to find out what products are most popular. Congressional aides promote or encourage laws they think will be popular with the public. You''ve also got other employees that work for the whole Congress, not just for individual members. We''ll talk about these people next.', NULL, NULL, NULL),
  ('b718b30a-71c4-5586-a014-0a0ef4ecb4ea'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b718b30a-71c4-5586-a014-0a0ef4ecb4ea'::uuid, 1, NULL, TRUE, 0, NULL, E'Eukaryotes & Prokaryotes', NULL, '6baa860f-1700-507b-9638-18de2a247ccb'::uuid, NULL, E'In this lesson, we discuss the similarities and differences between the eukaryotic cells of your body and prokaryotic cells such as bacteria. Eukaryotes organize different functions within specialized membrane-bound compartments called organelles These structures do not exist in prokaryotes.Your body''s composed of trillions of cells - lots of different types of cells that make up different organs and other parts of your body. Your body is also where 10 times that number of bacteria call ''home sweet home.'' But don''t be afraid - these bacteria do more good than harm to you. And besides, just in case you wanted to strike up a conversation with your tenants, you and your bacteria do have a few things in common.All cells share some common characteristics that make them living things. All organisms are composed of cells, the basic fundamental unit of life. They contain DNA as a heritable genetic material, and they can reproduce. They transcribe DNA into RNA and translate RNA into proteins on ribosomes. They can also regulate transport across a cell membrane and require chemical energy for some cellular processes. Organelles are the biggest difference between bacteria and cells that make up the human body Organelles.', NULL, NULL, NULL),
  ('b720c214-d85a-57d3-b4b6-9deeed0284da'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b720c214-d85a-57d3-b4b6-9deeed0284da'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5a3d51b6-4da0-5647-a34c-d0baa5dce478'::uuid, NULL, NULL, E'New media has an impact on human communications.', NULL, NULL),
  ('b7255944-e433-5db7-a2ef-b95c736c56a0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b7255944-e433-5db7-a2ef-b95c736c56a0'::uuid, 1, NULL, TRUE, 0, NULL, E'Marriage', E'Marriage does more than change people’s living situations and daily {{1}} ; becoming a spouse appears to change one’s {{2}} as well, especially in the early years of marriage. Men, for example, tend to become more {{3}} and introverted than they were when single, and women more emotionally {{4}} .', NULL, NULL, NULL, E'1.routines, 2.personality, 3.conscientious, 4.stable', NULL, NULL),
  ('b73aa2d6-6718-5069-afce-c5a603006847'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b73aa2d6-6718-5069-afce-c5a603006847'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1093908b-6cf1-51ca-9db7-5b26929b3a22'::uuid, NULL, NULL, E'The tutorial timetable can be found on the course website.', NULL, NULL),
  ('b740f1aa-7c57-578f-9e6a-517868beea78'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b740f1aa-7c57-578f-9e6a-517868beea78'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the meat from a duck?', 'b64bdb2e-d58a-590e-92dd-0299cda2193a'::uuid, NULL, NULL, E'Duck', NULL, NULL),
  ('b7422d98-cb79-5b09-b279-ba568f6735b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b7422d98-cb79-5b09-b279-ba568f6735b2'::uuid, 1, NULL, TRUE, 0, NULL, E'Heavily Hunted Species', E'It''s not that human activities didn''t impact wildlife at all of course. Heavily hunted species, like white-tailed deer, grey squirrels, and raccoons, were photographed somewhat less often in hunted areas. Coyotes showed up more often in hunted areas. While most species didn''t avoid hiking trails, the predators actually preferred them.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b74e7ef0-296b-5be6-933c-593b7b775f38'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'b74e7ef0-296b-5be6-933c-593b7b775f38'::uuid, 1, NULL, TRUE, 0, NULL, E'Copernicus', NULL, NULL, NULL, NULL, E'1, 2, 4, 3', NULL, NULL),
  ('b75209ae-f2d9-59f0-b587-5e1a63bb05b3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'b75209ae-f2d9-59f0-b587-5e1a63bb05b3'::uuid, 1, NULL, TRUE, 0, NULL, E'Sleep', NULL, NULL, NULL, NULL, E'1, 2, 4, 3, 5', NULL, NULL),
  ('b752f889-92c3-52b6-847d-e99416c25a2f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b752f889-92c3-52b6-847d-e99416c25a2f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b3c7ca20-d8ef-5a0b-a5ee-f6e67e7b07fb'::uuid, NULL, NULL, E'Media can influence humans'' opinions.', NULL, NULL),
  ('b75d336e-e9e2-590a-9d85-b01aecec52d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b75d336e-e9e2-590a-9d85-b01aecec52d8'::uuid, 1, NULL, TRUE, 0, NULL, E'Revision', E'Timing is important for revision. Have you noticed that during the school day you get times when you just don''t care any longer? I don''t mean the lessons you don''t like, but the ones you find usually OK, but on some occasions you just can''t be bothered with it. You {{1}} have other things on your mind, be tired, restless, or looking forward to what comes next. Whatever the reason, that particular lesson doesn''t get 100 percent {{2}} from you. The same is true of revision. Your mental and physical {{3}} are important. If you try to revise when you are tired or totally occupied with something else, your revision will be inefficient and just about worthless. If you approach it feeling fresh, alert and happy, it will be so much easier and you will learn more, faster. However, if you make no plans and just slip in a little bit of revision when you feel like it, you probably won''t do much revision! You need a revision timetable so you don''t keep {{4}} .', NULL, NULL, NULL, E'1.may, 2.effort, 3.attitudes, 4.putting it off', NULL, NULL),
  ('b76357e3-50a5-557e-822f-4a2c61fb0e30'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b76357e3-50a5-557e-822f-4a2c61fb0e30'::uuid, 1, NULL, TRUE, 0, NULL, E'3D Printing', E'3D printing is advancing rapidly, and the range of materials that can be used has expanded considerably. While the technology was previously limited to fast-curing plastics, it has now been made suitable for slow-curing plastics as well. These have decisive advantages as they have enhanced elastic properties and are more durable and robust.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b763f7dd-7d71-5b1c-a3c8-3f1243eb171e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b763f7dd-7d71-5b1c-a3c8-3f1243eb171e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a4bf9572-e61d-5df3-8edc-29e0ca139a6f'::uuid, NULL, E'There are no places left in the morning tutorial.', NULL, NULL, NULL),
  ('b764b38a-388c-59f3-8058-4440adb6ed84'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b764b38a-388c-59f3-8058-4440adb6ed84'::uuid, 1, NULL, TRUE, 0, NULL, E'Nectar', E'The scientists say this is the first documented instance of nectar that attracts a particular animal assistant being produced outside of a nectary. In fact, the observed nectar bleeding might actually be an early system that evolved to include the nectaries found in other plants today.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b7675333-6c9c-5e06-a93b-c02c75bd5967'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b7675333-6c9c-5e06-a93b-c02c75bd5967'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8fd5ae77-68a1-53b9-a521-9927863752a0'::uuid, NULL, NULL, E'The professor will have a lecture in the class.', NULL, NULL),
