  ('b781e51d-65a6-51d5-a10d-88f8749e89d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b781e51d-65a6-51d5-a10d-88f8749e89d3'::uuid, 1, NULL, TRUE, 0, NULL, E'School-skipping', E'Children who skip school are increasingly on family holidays, government figures revealed today. {{1}} children played truant this spring term compared with the spring term last year. Children missed 300 unauthorized days of school last term, compared with 370 days of school in the same period last year.\nBut a {{2}} group of truants - 6% of the school population - who account for more than three-quarters of all those on unauthorized absence, are more likely to be on a family holiday than they were in the same {{3}} last year.\nSome 1.2% of all absence was for family holidays not {{4}} by their school last term, compared with 0.9% for the same term last year. More than 60% of all absences were for illness, the same figure as last year.', NULL, NULL, NULL, E'1.Fewer, 2.hardcore, 3.period, 4.agreed', NULL, NULL),
  ('b781eb29-7ef9-5d1b-b203-d032179e7f6a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b781eb29-7ef9-5d1b-b203-d032179e7f6a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '459234b2-14c7-5d83-ac1d-2b8fb36c6f56'::uuid, NULL, NULL, E'The role of collaboration among students is incredibly crucial to success.', NULL, NULL),
