  ('b78b9690-d55a-5eb0-8132-d20330aee9d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b78b9690-d55a-5eb0-8132-d20330aee9d5'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd8c04461-2513-58c0-b85f-16cb1a8425f1'::uuid, NULL, E'The seminar will include speakers willing to share their experiences of marketing.', NULL, NULL, NULL),
  ('b7926806-687a-5097-84ac-1fb9c8b29771'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'b7926806-687a-5097-84ac-1fb9c8b29771'::uuid, 1, NULL, TRUE, 0, NULL, E'Roses', NULL, NULL, NULL, NULL, E'4, 2, 3, 1', NULL, NULL),
  ('b797f6e0-48e5-594f-85c1-79f10414ab17'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b797f6e0-48e5-594f-85c1-79f10414ab17'::uuid, 1, NULL, TRUE, 0, NULL, E'Wetlands Resources', E'Wetlands are one of the world’s most important environmental assets which provide homes for large, diverse biota as well as significant economic, social and cultural benefits related to timber, fisheries, hunting, recreational and tourist activities. They support the livelihoods of surrounding communities, including water, papyrus and fisheries among others, and provides vital ecosystem services such as purification and storage of water. It also acts as a carbon sink, thus regulating global and local climatic conditions and is internationally recognized as a key biodiversity area that hosts globally and nationally threatened bird, fish and mammal species. The wetland has attracted both local farmers and external agricultural interests. Wetlands constitute an important resource for riparian communities, and therefore it is important that they participate in the management of wetlands. Community participation in natural resource management has evolved from the realization that people living with natural resources should be responsible for their management and benefit from using the resources. Citizens must not only have access to information but must also be entitled to participate in decision making and have access to justice in environmental matters. However, participation of local communities in seeking solutions to wetlands resources use remains a grave challenge as managers of participation processes engage in low level consultations that do not empower them to co-manage these resources. Besides, the dynamics of communities’ participation and their activities on the wetland are not clearly understood despite wetland’s continued degradation in size and value.', NULL, NULL, NULL, NULL, 5, 75),
  ('b79ae045-aef5-5a9e-aca9-b2522d6060cb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b79ae045-aef5-5a9e-aca9-b2522d6060cb'::uuid, 1, NULL, TRUE, 0, NULL, E'Interpersonal Communication', E'To what extent do you think technology has influenced the quality of interpersonal communication? Is it positive or negative?', NULL, NULL, NULL, NULL, 200, 300),
  ('b7a0c20c-6670-5a91-afb9-200a04aa98ef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b7a0c20c-6670-5a91-afb9-200a04aa98ef'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e2a810f1-75ab-51c1-a4e2-6595e2831ae3'::uuid, NULL, NULL, E'Bar charts serve as effective tools for comparing different data.', NULL, NULL),
  ('b7a1cb3a-a9e0-5519-9a45-52c9749bd8d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b7a1cb3a-a9e0-5519-9a45-52c9749bd8d8'::uuid, 1, NULL, TRUE, 0, NULL, E'Welfare Morality', E'The morality of the welfare state depends on contribution and responsibility. Since some people don''t contribute and many are irresponsible, the choices of those who do contribute and are responsible are either to {{1}} the free riders, refuse to pay for the {{2}} of their irresponsibility or trust the state to {{3}} them. Hence the government campaigns against smoking, alcoholism, obesity and gas guzzling ‐ the first two solidly in place, the other two ramping up. But the British state now goes further: it acts in favor of sexual and racial minorities. In the case of gay men and women this means progressively removing the legal disadvantages under which they have lived, and ensuring that society as a whole observes the new order.', NULL, NULL, NULL, E'1.tolerate, 2.effects, 3.educate', NULL, NULL),
  ('b7aa0671-5a55-5f06-bbc8-5b15177e0a4d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b7aa0671-5a55-5f06-bbc8-5b15177e0a4d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What subject involves the study of gravity, electricity and so on?', 'b1cc8778-6eb5-53b1-9e5d-326030e3a689'::uuid, NULL, NULL, E'Physics', NULL, NULL),
  ('b7ac065a-1d5c-55c0-86e9-6f6b6e015a2b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b7ac065a-1d5c-55c0-86e9-6f6b6e015a2b'::uuid, 1, NULL, TRUE, 0, NULL, E'Native Species in North America', E'Of the more than 1,000 bat species worldwide, 22 are {{4}} to North America. And while there are no pollinator bats in our area, gardeners should {{1}} those that do live here, because they’re insectivorous. These bats {{3}} moths, beetles and mosquitoes, and can eat up to 500 mosquito-sized insects per hour. They also protect gardens and crops from such {{2}} as cucumber beetles, cutworms and leafhoppers.', NULL, NULL, NULL, E'1.native, 2.champion, 3.consume, 4.pests', NULL, NULL),
  ('b7ae4cb5-1182-512d-9d23-7a2f7e7b2443'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b7ae4cb5-1182-512d-9d23-7a2f7e7b2443'::uuid, 1, NULL, TRUE, 0, NULL, E'Medalists', E'In an often-cited study about counterfactuals, Medvec, Madey, and Gilovich (1995) found that bronze medalists appeared happier than silver medalists in television coverage of the 1992 Summer Olympics. Medvec et al {{1}} that bronze medalists compared themselves to 4th place finishers, {{2}} silver medalists compared themselves to gold medalists. These counterfactuals were the most {{3}} because they were either qualitatively different (gold vs silver) or categorically different (medal vs no medal) from what {{4}} occurred. Drawing on archival data and experimental studies, we show that Olympic athletes (among others) are more likely to make counterfactual comparisons based on their {{5}} expectations, consistent with decision affect theory. Silver medalists are more likely to be disappointed because their personal expectations are higher than {{6}} of bronze medalists.', NULL, NULL, NULL, E'1.argued, 2.whereas, 3.salient, 4.actually, 5.prior, 6.those', NULL, NULL),
  ('b7aeff53-51e6-5543-96fc-693a073ecd97'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b7aeff53-51e6-5543-96fc-693a073ecd97'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ef85dbe9-4f63-5f3e-99f2-40333a162f40'::uuid, NULL, NULL, E'Rail transport is becoming more and more popular.', NULL, NULL),
  ('b7b2e3cf-8125-59ce-8082-ef946db52fc8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b7b2e3cf-8125-59ce-8082-ef946db52fc8'::uuid, 1, NULL, TRUE, 0, NULL, E'Advertising', NULL, 'c9fddef6-7ada-5784-9577-629854bd96c2'::uuid, NULL, E'Advertisers spent over 100 billion dollars worldwide in 2000, and consumer product advertisements accounted for a little under half of that. What did they get for it? Does advertising actually work? Does it that is persuade customers to pay a premium price for the extra intangible value which a brand confers on a product. Some businessmen say that one cannot quantify the effect of advertising because it meant to have an unquantifiable effect. Such as improving product awareness reinforcing brand loyalties or increasing total consumption of a product category. However, that hasn''t stopped advertising executives from tying for many years to prove the clans that advertisements have a very quantifiable effect indeed on sales. Advertising is, of course, only a part of the total marketing mix thinking up the product or service, naming it, deciding its price, getting it to retailers, arranging the shelf display are all important too. Advertising was very successful in American Britain during the 1950s and early 1960s. It slowed down in the early 1970s and totally collapsed in the recession of 1974, 1975 with the economic recovery from 1976 through 1979 came some improvement. But higher media prices pushed up total expenditures. By 1990, that expenditure in most places had regained its real pre-1970 for level. The 1990s were not good though. Although spending on advertising grew slowly in France, Britain and Japan. Only in Germany and America did it increase significantly in real terms and that was mianly because of the 1996 Olympics. The American elections and export drives in Japan and Germany.', NULL, NULL, NULL),
  ('b7bf4e6c-6841-532a-8803-bbd6b75b0207'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b7bf4e6c-6841-532a-8803-bbd6b75b0207'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '41aa5362-a07f-52f2-acf5-994f310af5f6'::uuid, NULL, NULL, E'Student ID cards are expected to be ready by today.', NULL, NULL),
  ('b7c0961e-14b8-51c5-a7dd-14ff5fe058a4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b7c0961e-14b8-51c5-a7dd-14ff5fe058a4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '025a54aa-311f-5065-910f-7362559eae47'::uuid, NULL, NULL, E'The quality of your statistical information depends on your raw data.', NULL, NULL),
  ('b7c36549-e25b-5aa3-80ae-7752e0a820ab'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b7c36549-e25b-5aa3-80ae-7752e0a820ab'::uuid, 1, NULL, TRUE, 0, NULL, E'Culture', E'Listen to part of a talk in anthropology class. The professor is discussing culture. What would human life be without culture? It''s impossible for us to imagine what we''d be like without language, without art or religion or technology. Over hundreds of thousands of years of evolution, these aspects of our cultures have become as much a part of us as our anatomy and physiology. We have a lot in common with the people around us. In fact, the number of ideas we have in common with nearby people is very large. A complete list of shared ideas, for example, ideas we share with our own, the people around us. This list would include our ideas about what''s right and wrong, what''s beautiful and ugly and so on. Also our ideas about food, work, love, marriage, every aspect of our lives, even our rules about how to behave towards strangers, friends, animals on the earth. Think of a particular group of people. Any groups say, for example, college students, if you could take all the ideas and behaviors, all the tools and technology, all the things that college students share as a result of being in contact with each other, you''d have what anthropologists call student culture. So what you''re saying is culture is sort of like a club. College students are a club. It''s because our experiences like we go to class, we do homework, we have our computers and cell phones, we hang out with other students. Sometimes we forget what the outside world is like. This is why this what we have in common with other students. It''s why our culture makes us feel like part of a club. Right? Um. Well, in a way, a culture is like a club. Neighboring cultures might share the same ideas and rules like neighboring clubs do, but the comparison doesn''t completely cut it. Think about it. A club has borders that we can define, but we run into trouble if we try to draw borders around a culture. Culture isn''t a thing, it''s an idea. Still, even though the idea of culture is problematic, some of us believe that by continuing to study cultures, we will eventually be able to explain the similarities and differences among us.\n\nWhy does the professor mention student culture?', '54dda91b-978d-512b-8f2c-90ced8b74a5e'::uuid, NULL, NULL, E'To illustrate how culture involves shared ideas and behaviors', NULL, NULL),
  ('b7cd164f-43b6-56c1-bf2e-3917dbf6cdd7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b7cd164f-43b6-56c1-bf2e-3917dbf6cdd7'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '96a1b37b-3e8d-5695-bf7c-6b5882d90020'::uuid, NULL, E'The marketing department has always played a subsidiary role to the sales department.', NULL, NULL, NULL),
  ('b7d7b422-db7f-5751-b8fb-2332db29e9d2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b7d7b422-db7f-5751-b8fb-2332db29e9d2'::uuid, 1, NULL, TRUE, 0, NULL, E'Hunter''s Full Moon', E'The Hunter''s full moon is the first full moon after the autumnal equinox, which marks the arrival of the colder months in the Northern Hemisphere. At higher latitudes in the Northern Hemisphere, the moon therefore appeared larger than the full moons of the summer months, as it lingered relatively low above the horizon.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b7da2e9a-b91f-52ca-a0bd-af319d625a51'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b7da2e9a-b91f-52ca-a0bd-af319d625a51'::uuid, 1, NULL, TRUE, 0, NULL, E'Inflation and Deflation', NULL, '547e0f68-1295-553e-9983-1129703d8932'::uuid, NULL, E'So why doesn’t the Fed just decide to print infinite hundred dollar bills to make everyone happy and rich? Well, because then the bills wouldn’t be worth anything. Think about the purpose of currency, which is to be exchanged for goods and services. If the total amount of currency in circulation increases faster than the total value of goods and services in the economy, then each individual piece will be able to buy a smaller portion of those things than before. This is called inflation. On the other hand, if the money supply remains the same, while more goods and services are produced, each dollar’s value would increase in a process known as deflation. So which is worse? Too much inflation means that the money in your wallet today will be worth less tomorrow, making you want to spend it right away. So while this would stimulate business, it would also encourage overconsumption, or hoarding commodities, like food and fuel, raising their prices and leading to consumer shortages and even more inflation. But deflation would make people want to hold onto their money, and a decrease in consumer spending would reduce business profits, leading to more unemployment and a further decrease in spending, causing the economy to keep shrinking. So most economists believe that while too much of either is dangerous, a small, consistent amount of inflation is necessary to encourage economic growth.', NULL, NULL, NULL),
  ('b7e9e39e-e332-51d2-9515-5b5f8c16367e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b7e9e39e-e332-51d2-9515-5b5f8c16367e'::uuid, 1, NULL, TRUE, 0, NULL, E'Amazon Forest', E'A very unexpected discovery has surprised the world. The Amazon Forest, thought to be a reservoir of wildlife and primitive indigenous settlements, was also the seat of advanced civilizations. By advanced, we mean that they were large urban societies with civic and ritualistic activities, in contrast with nomadic small tribes.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b7eb91ed-17bc-52fd-96b1-d0efbd0ec23c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b7eb91ed-17bc-52fd-96b1-d0efbd0ec23c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ddadec8e-861e-59a6-a2aa-1564724df7f2'::uuid, NULL, E'Modern knowledge companies have fewer repetitive, mechanical tasks in their operations.', NULL, NULL, NULL),
  ('b7f11428-c89d-56e0-ac00-60f93d57e7bf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b7f11428-c89d-56e0-ac00-60f93d57e7bf'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3e49a713-c57d-51c9-b0b8-605a7065b4c7'::uuid, NULL, E'Many of her novels regarding female mental health have been adapted for television.', NULL, NULL, NULL),
  ('b7f6b06a-e405-50c6-b79a-7a5343e13bbf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b7f6b06a-e405-50c6-b79a-7a5343e13bbf'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the antonym of ''innocent''?', '7fa3564f-39c7-5dda-9422-550260857512'::uuid, NULL, NULL, E'Guilty', NULL, NULL),
  ('b7f91367-f545-5a1b-af7a-617d5363cc2a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b7f91367-f545-5a1b-af7a-617d5363cc2a'::uuid, 1, NULL, TRUE, 0, NULL, E'Screenwriter', E'Becoming a screenwriter starts with developing your talent as a writer, and the best way to develop your talent as a writer is to write. Your first project doesn''t need to be a screenplay or TV script. You just need to start somewhere; essays, short stories, plays, etc. The idea is to become comfortable with the writing process, a surprisingly slow and frustrating experience, and find what they call your "voice." Over time, you''ll discover if your talents lie primarily with comedy, drama or some combination of the two.\nSome people find it helpful to develop their writing skills in a structured educational setting, whether it''s a college course, a film school program, or an online writing workshop. The advantage of taking a class is that there are deadlines and grades motivating you to sit down and get to work. At film school, in particular, you also have access to a community of artists, writers and filmmakers from which to draw inspiration and fresh ideas. And if you''re lucky, friends and connections you make in film school could lead to your first industry job.\nBut formal classes and degrees are certainly not required to become a screenwriter. You can create your own personal film school, renting and studying the greatest films and TV shows. There are several free and pay Web sites for reading film and TV scripts online. And there''s no shortage of books written for aspiring screenwriters. The most famous is Syd Field''s "Screenplay: The Foundations of Screenwriting." Since digital video technology is so affordable, you can always get together with a group of friends and write and produce your own films to gain experience.', NULL, NULL, NULL, NULL, 5, 75),
  ('b7fe2fc1-db5b-5eca-a771-30d0e8fecf4d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b7fe2fc1-db5b-5eca-a771-30d0e8fecf4d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e03386c2-ced8-5898-b800-cdeb34ce0ace'::uuid, NULL, NULL, E'If you are not sure, phone student services for help.', NULL, NULL),
