  ('b80e79ba-98e6-5338-84a6-8be744a2575e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b80e79ba-98e6-5338-84a6-8be744a2575e'::uuid, 1, NULL, TRUE, 0, NULL, E'Venus', NULL, '67458be1-b048-580b-9605-337eecc8f002'::uuid, NULL, E'There is a picture, sort of artist''s impression, before the space age of what Venus might be like on its surface and so this was looking at the planet Venus, it was science fiction and science fact all the way up to 56 before the start of the space age but it wasn''t completely disproved, this idea of a really sort of lush environment on Venus until 1967, which is when the first measurements in detail were done at Venus.\nSo Mariner four and Mariner five confirmed the feeling from an earlier space mission that in fact the surface of Venus was not like this at all, but extremely hot and, and also that the clouds were made of sulfuric acid so there wasn''t a nice water cycle like is going on in this picture and so,\nthat it had to wait for these in situ measurements by space craft to actually do that and so Venus turned out not to be quite as Earth like as we thought and I''ll sort of tell you about some of the latest results from Venus Express, which, which they actually there are some Earth like features, but to a large extent, it''s not like the Earth.', NULL, NULL, NULL),
  ('b80f4240-f9c7-5e31-a480-8461b39b7095'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b80f4240-f9c7-5e31-a480-8461b39b7095'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bc9847d4-e3db-5b31-a536-d912e70e5fd8'::uuid, NULL, E'Friends help with feelings, but how much depends on each person.', NULL, NULL, NULL),
