  ('b864d8d8-1d8e-56cc-8264-8b29b958f97d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b864d8d8-1d8e-56cc-8264-8b29b958f97d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '571de5c5-df82-5bb4-927c-a8746a82dc5f'::uuid, NULL, E'There is absolutely no archaeological evidence to prove that Alexander the Great existed.', NULL, NULL, NULL),
  ('b865d5fa-19a3-520d-bb4a-cea1b6514b38'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b865d5fa-19a3-520d-bb4a-cea1b6514b38'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a6b20990-6dc9-5047-93f9-6ef401a18126'::uuid, NULL, E'The test includes subjects from each chapter in this semester''s material.', NULL, NULL, NULL),
  ('b8688eb6-987f-5d44-adf8-b1e7820977c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b8688eb6-987f-5d44-adf8-b1e7820977c8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person who writes poems?', '3186289b-0be1-5b75-b1ee-0dc99008552c'::uuid, NULL, NULL, E'Poet', NULL, NULL),
  ('b8692d73-917d-574b-b916-6fc83217b4a1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b8692d73-917d-574b-b916-6fc83217b4a1'::uuid, 1, NULL, TRUE, 0, NULL, E'FIB', E'Sometimes it seems there''s only so much we can learn about {{1}} . We can''t know what their coloration looked like, we can''t watch them interact with each other. We can only extrapolate from their remains. But now scientists say we can discern a hint of dinosaur movement - from ostriches.\nThe giant, flightless birds still have feathered forelimbs that scientists assumed were now solely used for display and temperature regulation. But {{2}} from Germany and Belgium carefully {{3}} {{4}} ostriches, and modeled their movement in the surrounding air streams. They found that far from being useless in movement, the leftover wings help ostriches break quickly, turn, and zig-zag. The scientists presented their {{5}} at the Society for {{6}} Biology''s annual conference in Prague.\nOstriches are descendants of dinosaurs, and the researchers liken ostrich movements to those of bipedal dinosaurs. Paleontologists had previously thought that some dinos'' small forelimbs had served to catch insects or rip flesh. But this new research shows dinosaurs may have used their forelimbs to help with quickness, {{7}} and agility. Further study in this field could lead to more accurate ideas of what it once looked like when dinosaurs went dashing through their prehistoric landscape.', NULL, NULL, NULL, E'1.dinosaurs, 2.researchers, 3.observed, 4.hand-raised, 5.findings, 6.Experimental, 7.stability', NULL, NULL),
  ('b873e0f3-5df7-5a08-b917-873c1e55bac5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b873e0f3-5df7-5a08-b917-873c1e55bac5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2bceae15-3263-58c2-9067-1ac2b51d62fc'::uuid, NULL, NULL, E'During the war children suffered from a deficiency of food.', NULL, NULL),
