  ('b87ad4f6-e2f3-53e1-bf16-d546c1e12df6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b87ad4f6-e2f3-53e1-bf16-d546c1e12df6'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What was the dominant language of the Roman Empire?', '07ef1220-6645-59e4-8f30-f81baed69cfe'::uuid, NULL, NULL, E'Latin', NULL, NULL),
  ('b87bd199-ad1f-5e55-b015-5ae3d2ecc162'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b87bd199-ad1f-5e55-b015-5ae3d2ecc162'::uuid, 1, NULL, TRUE, 0, NULL, E'Desert', E'Wind-blown {{1}} of sand from dunes may carry far inland, covering fields and diverting streams. More seriously, drifting sands can bury whole buildings and transform {{2}} land into desert. However, dunes can be made more stable by the artificial {{3}} of marram grass, a plant so robust that it can find {{4}} even in sand. The grass spreads over the {{5}} of the dune, protecting it against wind, while its roots bind the sand together.', NULL, NULL, NULL, E'1.grains, 2.fertile, 3.planting, 4.nourishment, 5.surface', NULL, NULL),
  ('b87d8a6d-de12-505e-8bf7-500ba006fd37'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b87d8a6d-de12-505e-8bf7-500ba006fd37'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Where does a camel normally live?', '4487e631-05bc-5f07-b3e2-153f1c517f33'::uuid, NULL, NULL, E'Desert', NULL, NULL),
  ('b8806d44-522e-5290-b2f4-138248f7683c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'b8806d44-522e-5290-b2f4-138248f7683c'::uuid, 1, NULL, TRUE, 0, NULL, E'African Elephants', NULL, NULL, NULL, NULL, E'3, 5, 4, 2, 1', NULL, NULL),
  ('b884e90a-932c-5d46-9d18-a2af28820120'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b884e90a-932c-5d46-9d18-a2af28820120'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a large building with a square base and triangular sides?', '7be11b83-c60a-55ef-aacf-469d208b5a3c'::uuid, NULL, NULL, E'Pyramid', NULL, NULL),
  ('b889f3a1-7529-5942-873e-24cc8546389e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b889f3a1-7529-5942-873e-24cc8546389e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd76c72ba-e3bd-5044-9817-736bb84d48f1'::uuid, NULL, NULL, E'The governor has denied making improper use of the state money.', NULL, NULL),
  ('b89288b0-2725-5733-8f9c-0ab4e2c2ce28'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'HIGHLIGHT_CORRECT_SUMMARY', E'HIGHLIGHT_CORRECT_SUMMARY', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b89288b0-2725-5733-8f9c-0ab4e2c2ce28'::uuid, 1, NULL, TRUE, 0, NULL, E'Communication between Couples', E'Always try to best understand your partner’s specific communication styles. A lot of times we''ll take it personally if we notice someone''s avoiding us or they''re communicating with us less frequently than we''d like, and this doesn''t mean that they don''t care about you or they don''t respect you. This is likely how they were modeled communication as a child. Your partner''s communication style typically comes from how their caregivers communicated with each other. You should feel comfortable asking your partner “How do you best handle conflict?” Also, some people struggle with verbal communication, so if that''s the case, you may want to ask your partner to write down what they''re feeling. And this way they won''t feel so overwhelmed. Finally, know that communication requires compromise. So if you have a completely different communication style from your partner, know that it''s going to be a work in progress until you figure out how you''re both best going to communicate.\n\nClick on the paragraph that best relates to the recording.', 'bef81fc7-c257-59c7-b9e7-98488aa8c234'::uuid, NULL, NULL, E'Different people have different communication styles, so you need to understand your partner’s style. You can even write down your feelings if you have difficulties when communicating verbally. Communication also needs compromise, so make sure you are patient when seeking for the best way to communicate with her or him.', NULL, NULL),
  ('b89476bd-fd91-58e5-bc6e-65a15ad2c423'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b89476bd-fd91-58e5-bc6e-65a15ad2c423'::uuid, 1, NULL, TRUE, 0, NULL, E'Written Examinations', E'Written examinations are a fact of life for most high school and university students. However, recent studies have shown that this traditional form of assessment may not be an accurate indicator of academic performance. Tests have shown that many students experience anxiety during exam weeks, which leads to poorer results. As a result, some learning institutions are replacing exams with alternative assessments such as group work and oral presentations.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b89b82d1-677c-5b7b-9672-73ff43394aaa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b89b82d1-677c-5b7b-9672-73ff43394aaa'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5054a95c-0954-59ea-96e3-fc45905c4239'::uuid, NULL, E'The student got an extension to finish writing his thesis since he was ill.', NULL, NULL, NULL),
  ('b89b8354-96d2-5b21-b5ec-d81fe778bcd4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b89b8354-96d2-5b21-b5ec-d81fe778bcd4'::uuid, 1, NULL, TRUE, 0, NULL, E'Eye Protection', E'Continuous use of mobile phones before bedtime in the dark can initially cause dry eyes, and strain your eyes. Direct glare of over 30 minutes can even cause irreversible eye macular degeneration, resulting in rapid deterioration of vision.\nThe fact is that the mobile devices expose us to high energy visible (HEV) light or blue light, which in certain experiments in laboratory with high dose of exposure has shown to cause changes in certain cells of the eyes. The HEV light or blue light is also part of the light from LEDs and sunlight. K. Bhujang Shetty, chairman and managing director of Narayana Nethralaya, says that eyes could be affected after continuous and prolonged use of mobile phones in the dark. And this habit may not cause enough damage that can lead to permanent vision loss if a person uses it occasionally. But it would definitely strain the eyes. He also suggests some precautions, including maintaining a comfortable working distance from the device — be it a mobile phone or computer and ensure that the screen is bright enough and the fonts big enough to read comfortably.\nIt is also advisable for a person to follow the rule of 20s — every 20 minutes, stare at an object 20 feet away for 20 seconds. This will bring back your blink rate to normal and also relax the muscles in your eye.', NULL, NULL, NULL, NULL, 5, 75),
  ('b89bec57-0bf7-579c-86ab-69721844f7c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b89bec57-0bf7-579c-86ab-69721844f7c5'::uuid, 1, NULL, TRUE, 0, NULL, E'Categorization', E'Categorization is the brain''s tool to organize nearly everything we encounter in our daily lives. Grouping information into categories simplifies our complex world and helps us to react quickly and effectively to new experiences. Researchers identified neurons encoding learned categories and thereby demonstrated how abstract information is represented at the neuronal level.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b8a1b571-341a-5ebe-aa4b-d3992a4f7245'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b8a1b571-341a-5ebe-aa4b-d3992a4f7245'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e95534b6-200f-523f-b990-205c27e2d5ba'::uuid, NULL, E'The report mentions that this company has overspent on marketing.', NULL, NULL, NULL),
  ('b8a6649a-897b-5384-8689-b8efd0d72023'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b8a6649a-897b-5384-8689-b8efd0d72023'::uuid, 1, NULL, TRUE, 0, NULL, E'Unwritten Rules', E'Every culture is riddled with unwritten rules, such as ones on punctuality. They are the invisible scaffold that frames the behavior of individuals so that the collective can function in a frictionless and productive way. But the rigor of these rules and the exactitude with which they are enforced varies dramatically. Some nations tolerate singing in an elevator, swearing during an interview or entering a bank barefoot, while others frown upon such behaviors.', NULL, NULL, NULL, NULL, NULL, NULL),
