  ('b8e93ea2-25f5-5bec-8663-338f17007d9f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b8e93ea2-25f5-5bec-8663-338f17007d9f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which word is related to physical disability, handicap or obstacle?', '8a2b66d0-32b9-5c55-8252-11afa59cbaa2'::uuid, NULL, NULL, E'Handicap', NULL, NULL),
