  ('b9709e1c-cc3d-56bd-b17e-962f5d58d903'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b9709e1c-cc3d-56bd-b17e-962f5d58d903'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '46e0f7ac-c3f0-5492-9c80-e26bc141fe93'::uuid, NULL, E'Anonymous behaviors can be identified without intervention.', NULL, NULL, NULL),
  ('b977a47e-3865-59aa-90d5-ef9528a58c6f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b977a47e-3865-59aa-90d5-ef9528a58c6f'::uuid, 1, NULL, TRUE, 0, NULL, E'Cashless Experiment', E'KELLY: For a glimpse of what the U.S. economy might look like in the future, we head to Scandinavia. No country is dropping cash as fast as Sweden. Just 13 percent of people there reported using cash to buy something last year. But as Maddy Savage reports from Stockholm, some Swedes are concerned that things have changed too quickly.\nMADDY SAVAGE, BYLINE: Next to the cinnamon buns and open sandwiches at this restaurant, there’s a large blue sign with the English word cash crossed out. Notes and coins stopped being accepted here a year ago after staff noticed most people were hardly using them.\nCHRISTOPHER LOOB: It was super rare, I’d say 5 percent — something like that — in the restaurant was using cash.\nSAVAGE: That’s general manager Christopher Loob, who’s been keeping an eye on how customers have responded.\nLOOB: There’s hardly been any reaction. Almost everybody has the alternative payment method — a credit card — and it’s good for both the guests and for us.\nSAVAGE: He says scrapping cash saves time at the till and helps protect against theft.\n\nFrom the report, we know that ___', '88a14352-784b-5c48-ae9d-4a72e6589dbd'::uuid, NULL, NULL, E'cash is not welcomed in the restaurant.\ncustomers in the restaurant don’t feel offended by the cashless requirement.', NULL, NULL),
  ('b979706c-e4bf-54d0-9c84-532bdf8d3876'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b979706c-e4bf-54d0-9c84-532bdf8d3876'::uuid, 1, NULL, TRUE, 0, NULL, E'Salt Fish', E'Salt fish has been a part of Caribbean cuisine {{1}} back to the days of European colonial rule. Salt fish was first {{2}} to the Caribbean in the 16th century. Today, most of the salt fish {{3}} in the Caribbean is still {{4}} , though countries like Guyana now make their own salt fish.', NULL, NULL, NULL, E'1.dating, 2.introduced, 3.consumed, 4.imported', NULL, NULL),
