  ('b97b5a36-ff11-50d2-98bf-45cc019894db'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b97b5a36-ff11-50d2-98bf-45cc019894db'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f4bd24fc-831a-5218-a18e-0cc20945837b'::uuid, NULL, E'The bus by the building goes directly to the central bus station.', NULL, NULL, NULL),
  ('b98357f0-04be-53c2-bfa5-1094e1f24600'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b98357f0-04be-53c2-bfa5-1094e1f24600'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '181a8867-8f53-5ba1-812d-c14aaee9d897'::uuid, NULL, NULL, E'Please check the information on the website for the opening time.', NULL, NULL),
  ('b9886fe9-1084-5262-ab9f-2eedf8dbe53d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'b9886fe9-1084-5262-ab9f-2eedf8dbe53d'::uuid, 1, NULL, TRUE, 0, NULL, E'Unseasonable Spring', NULL, NULL, NULL, NULL, E'5, 2, 4, 3, 1', NULL, NULL),
  ('b990c66c-4e0d-5e34-a406-929adcddbb31'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b990c66c-4e0d-5e34-a406-929adcddbb31'::uuid, 1, NULL, TRUE, 0, NULL, E'Compulsory Reburial', E'Human remains are a fundamental part of the archaeological record, offering unique insights into the lives of individuals and populations in the past. Recently a new set of challenges to the study of human remains has emerged from a rather unexpected direction: the British government revised its interpretation of nineteenth-century burial legislation in a way that would drastically curtail the ability of archaeologists to study human remains of any age excavated in England and Wales. This paper examines these extraordinary events and the legal, political and ethical questions that they raise.\nIn April 2008 the British government announced that, henceforth, all human remains archaeologically excavated in England and Wales should be reburied after a two-year period of scientific analysis. Not only would internationally important prehistoric remains have to be returned to the ground, removing them from public view, but also there would no longer be any possibility of long-term scientific investigation as new techniques and methods emerged and developed in the future. Thus, while faunal remains, potsherds, artifacts and environmental samples could be analyzed and re-analyzed in future years, human remains were to be effectively removed from the curation process. Archaeologists and other scientists were also concerned that this might be the first step towards a policy of reburying all human remains held in museum collections in England and Wales including prehistoric, Roman, Saxon, Viking and Medieval as well as more recent remains.', NULL, NULL, E'Human remains are a fundamental part of the archaeological record, but recently a new set of challenges to the study of human remains has emerged from a rather unexpected direction, and there would no longer be any possibility of long-term scientific investigation as new techniques and methods emerged and developed in the future, so this might be the first step towards a policy of reburying all human remains held in museum collections.', NULL, 5, 75),
  ('b9a018c6-6d9f-54c2-bf3e-9ade6508af54'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b9a018c6-6d9f-54c2-bf3e-9ade6508af54'::uuid, 1, NULL, TRUE, 0, NULL, E'Bertrand Russell', E'Russell was arguably the greatest philosopher of the 20th century and the greatest logician since Aristotle. Analytic philosophy, the dominant philosophy of the twentieth century, owes its existence more to Russell than to any other philosopher. And the system of logic developed by Russell and A.N. Whitehead, based on earlier work by Dedekind, Cantor, Frege, and Peano, broke logic out of its Aristotelian straitjacket. He was also one of the century''s leading public intellectuals and won the Nobel Prize for Literature in 1950 "in recognition of his varied and significant writings in which he champions humanitarian ideals and freedom of thought."\nRussell was involved, often passionately, in numerous social and political controversies of his time. For example, he supported suffragists, free thought in religion and morals, and world government; he opposed World War I and the Vietnam War, nationalism, and political persecution. He was jailed in 1918 for anti-war views and in 1961 for his anti-nuclear weapons stance.\nHe was married 4 times and had 3 children. With Dora Russell, he founded the experimental Beacon Hill School. He knew or worked with many of the most prominent figures in late 19th and 20th century philosophy, mathematics, science, literature, and politics. Active as a political and social critic until his end, Russell died in 1970 at the age of 97.', NULL, NULL, E'Bertrand Russell, arguably the greatest philosopher of the 20th century, the greatest logician since Aristotle, also one of the century''s leading public intellectuals who won the Nobel Prize for Literature in 1950, involved in numerous social and political controversies of his time, knowing or working with many prominent figures, was active as a political and social critic until he died at the age of 97.', NULL, 5, 75),
  ('b9a0e90a-9328-58f3-9925-4d6e2fe3fbd1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b9a0e90a-9328-58f3-9925-4d6e2fe3fbd1'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c2133a0b-5057-59c8-b367-9add609be30f'::uuid, NULL, NULL, E'The earth''s atmosphere is primarily composed of oxygen and nitrogen gases.', NULL, NULL),
  ('b9a1f78a-9dd7-522e-b6db-92b258cec590'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b9a1f78a-9dd7-522e-b6db-92b258cec590'::uuid, 1, NULL, TRUE, 0, NULL, E'Gender Bias in Africa', E'In African society, the gender {{1}} and patriarchal construct remain the bane across virtually all spheres of life in the society. There is a greater level of gender sensitivity to the extent that boys are {{2}} up to see themselves as {{3}} sex to girls, while the females are trained to see themselves as weaker sex or even as appendages to the menfolk.', NULL, NULL, NULL, E'1.peculiarities, 2.brought, 3.superior', NULL, NULL),
  ('b9a2064d-e6c5-5578-85fa-b94b3b3491ea'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b9a2064d-e6c5-5578-85fa-b94b3b3491ea'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5d6f1838-5d39-54e7-b365-bf37d6c26702'::uuid, NULL, NULL, E'Our food supply now contains too much sugar that our metabolic system cannot handle it.', NULL, NULL),
  ('b9a2d651-efa8-5b8d-ad85-592ea1746f28'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b9a2d651-efa8-5b8d-ad85-592ea1746f28'::uuid, 1, NULL, TRUE, 0, NULL, E'Sports', E'Sports were firstly part of survival skills, {{1}} linked to human existence, but now they are mainly for {{2}} purposes and enjoyment. For example, swimming, hunting, and fishing were {{3}} necessary for food, but today they have evolved into popular competitive sports. Some of them are actually seen as global competitions {{4}} millions of spectators.', NULL, NULL, NULL, E'1.tightly, 2.recreational, 3.originally, 4.attracting', NULL, NULL),
  ('b9a4e621-8ab2-575c-a576-f7902d07d7ec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b9a4e621-8ab2-575c-a576-f7902d07d7ec'::uuid, 1, NULL, TRUE, 0, NULL, E'Ancient Egypt', E'Contrary to common belief, most sites in ancient Egypt haven''t been discovered. In fact, less than one percent have been {{1}} .Using satellite technology, scientists are able to discover Egyptian sites that have not {{2}} been unearthed. Sites that may have taken years to find can be located and even {{3}} in a mere couple of weeks.', NULL, NULL, NULL, E'1.excavated, 2.yet, 3.mapped', NULL, NULL),
  ('b9a54fe2-0504-5665-b0d1-b07619c6ac8e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b9a54fe2-0504-5665-b0d1-b07619c6ac8e'::uuid, 1, NULL, TRUE, 0, NULL, E'Music', E'What is music? In one sense, this is an easy {{1}} . Even the least musical among us can recognize pieces of music when we hear them and name a few canonical {{2}} . We know there are different kinds of music and, even if our {{3}} of music is restricted, we know which kinds we like and which kinds we do not.', NULL, NULL, NULL, E'1.question, 2.examples, 3.knowledge', NULL, NULL),
  ('b9a81809-eb1f-575e-a6b3-248d23b4b63e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b9a81809-eb1f-575e-a6b3-248d23b4b63e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '875608e7-6948-5b32-a64e-7e56ea58edbc'::uuid, NULL, E'Next year I''m planning to take a sabbatical so that I can travel to South America.', NULL, NULL, NULL),
  ('b9a8bdc8-61f7-516f-9f4b-2f93ce6c9542'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b9a8bdc8-61f7-516f-9f4b-2f93ce6c9542'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e9ec4114-ea11-5974-bdfd-7e5ef41711ff'::uuid, NULL, E'In English, the month of the year is always capitalized.', NULL, NULL, NULL),
  ('b9a8c3e9-7585-5093-87a3-a66e447e06fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b9a8c3e9-7585-5093-87a3-a66e447e06fd'::uuid, 1, NULL, TRUE, 0, NULL, E'Decisions', E'These decisions are highly nuanced. Of course we use a lot of data to inform our decisions, but we also rely very heavily on iteration, research, testing, intuition and human empathy. Now, sometimes the designers who work on these products are called "data-driven," which is a term that totally drives us bonkers. The fact is, it would be irresponsible of us not to rigorously test our designs when so many people are counting on us to get it right.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('b9acddb6-257f-52b6-b27b-85ab90d2ee3a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b9acddb6-257f-52b6-b27b-85ab90d2ee3a'::uuid, 1, NULL, TRUE, 0, NULL, E'Resources', E'The professor is talking about economics in colonial new england. We know that in colonial new england, the native americans, compared to the european colonists, had a far greater knowledge of what resources in the environment could be eaten or made useful. Native americans used a wide range of resources for economic subsistence, and these resources were simply used by the family that acquired them. Only a few resources were accumulated for the purpose of showing a person''s social status, for example, shells, furs, and ornaments of the hunt, excuse me, doctor, singer. But did they, um, did the native americans have a concept of wealth? The native americans believed a person''s status came more from kinship and personal alliances than from stores of wealth. Their definition of need was what they needed to survive. So if they had food, clothing, and shelter, they considered themselves wealthy for the european colonists. On the other hand, resources in the environment were seen more as commodities, as goods that could be exchanged in markets. European economies, measured commodities in terms of money values. Abstract equivalence is that could be accumulated and could function as indicators of wealth and social status. So for the colonists need was defined by the markets that bought new england goods. So the europeans perceived few resources in new england ecosystems, but they saw many commodities for fish timber, which could be sold in the market place for profit number.\n\nWhat does the professor say about the Native Americans'' use of resources?', 'd5139148-a93b-53bc-81d6-32b95bea33e4'::uuid, NULL, NULL, E'They used resources mainly for economic subsistence.', NULL, NULL),
  ('b9b2177c-8621-5360-99a2-69af1eda7c9f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b9b2177c-8621-5360-99a2-69af1eda7c9f'::uuid, 1, NULL, TRUE, 0, NULL, E'Plastic', E'Plastic has {{1}} the way we manufacture, package, transport, and use different products {{2}} from groceries to cosmetics and vaccines. It is a tool — and like any tool, it can offer great {{3}} , but it can also pose problems when being used {{4}} .', NULL, NULL, NULL, E'1.transformed, 2.ranging, 3.advantages, 4.improperly', NULL, NULL),
  ('b9b25aa5-f049-56c6-bef0-d0c09e9fd597'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b9b25aa5-f049-56c6-bef0-d0c09e9fd597'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7317d7fe-7ca4-56c2-bd28-4293198a195a'::uuid, NULL, NULL, E'This magazine is running a special feature on science.', NULL, NULL),
  ('b9b26e44-1f90-5236-9760-15c9f7e5c3c3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b9b26e44-1f90-5236-9760-15c9f7e5c3c3'::uuid, 1, NULL, TRUE, 0, NULL, E'Space Exploration', E'The exploration of space continues to captivate human curiosity. Robotic missions and manned expeditions contribute to our understanding of the universe and the potential for extraterrestrial life. Space agencies and private companies are collaborating to advance space travel technologies and pave the way for future interplanetary exploration.', NULL, NULL, NULL, NULL, NULL, NULL),
