  ('b9c0ed16-fe64-5d31-9fe6-4d9f6c3e8b3d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b9c0ed16-fe64-5d31-9fe6-4d9f6c3e8b3d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ef7dace8-71b1-5089-a6cb-ddb149da0ee9'::uuid, NULL, NULL, E'Artists and politicians alike start by learning the basics of politics.', NULL, NULL),
  ('b9c2b468-52c2-51ef-b0a4-14df2af5f7a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b9c2b468-52c2-51ef-b0a4-14df2af5f7a8'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '334dfc01-0ddf-52fb-803b-a6f5005e4832'::uuid, NULL, NULL, E'The majority of academic publications are in English.', NULL, NULL),
  ('b9c6b6cd-d33b-5ecb-8ae7-81d1145df185'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'b9c6b6cd-d33b-5ecb-8ae7-81d1145df185'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7d05b8b1-783e-5242-9910-5141e7a15608'::uuid, NULL, NULL, E'You need to take clear notes while learning new languages.', NULL, NULL),
  ('b9cec247-bcd5-5db1-b150-ba7b86cee84f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'b9cec247-bcd5-5db1-b150-ba7b86cee84f'::uuid, 1, NULL, TRUE, 0, NULL, E'Middle East Trade', E'Trade was the mainstay of the urban economy in the Middle East, as caravans negotiated the surrounding desert, restricted only by access to water and by mountain ranges. This has been so since ancient times, partly due to the geology of the area, which is mostly limestone and sandstone, with few deposits of metallic ore and other useful materials. Ancient demands for obsidian (a black volcanic rock useful for making mirrors and tools) led to trade with Armenia to the north, while jade for cutting tools was brought from Turkistan, and the precious stone lapis lazuli was imported from Afghanistan. One can trace such expeditions back to ancient Sumeria, the earliest known Middle Eastern civilization. Records show merchant caravans and trading posts set up by the Sumerians in the surrounding mountains and deserts of Persia and Arabia, where they traded grain for raw materials, such as timber and stones, as well as for metals and gems. Reliance on trade had several important consequences. Production was generally in the hands of skilled individual artisans doing piecework under the tutelage of a master who was also the shop owner. In these shops differences of rank were blurred as artisans and masters labored side by side in the same modest establishment, were usually members of the same guild and religious sect, lived in the same neighborhoods, and often had assumed (or real) kinship relationships. The worker was bound to the master by a mutual contract that either one could repudiate, and the relationship was conceptualized as one of partnership.\n\nAccording to the paragraph, why has trade been so important throughout the history of the Middle East', NULL, NULL, NULL, E'Many useful and decorative raw materials cannot be found naturally in the Middle East but are available from neighboring regions.', NULL, NULL),
  ('b9d1e43f-be6e-5983-ab0d-2623a295c833'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'b9d1e43f-be6e-5983-ab0d-2623a295c833'::uuid, 1, NULL, TRUE, 0, NULL, E'Professional Astronomers', E'Professional astronomers, {{1}} their amateur counterparts, have no particular interest in the aesthetic quality of their photographs. What {{2}} to them is the contribution their images can {{3}} to research, and to the {{4}} of data scientists in their field {{5}} for research purposes.', NULL, NULL, NULL, E'1.unlike, 2.matters, 3.make, 4.collection, 5.use', NULL, NULL),
  ('b9e3af3d-03cf-5548-b12e-194282c9989c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b9e3af3d-03cf-5548-b12e-194282c9989c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the occupation of someone who plays a character in a movie?', '7f012b6b-5aad-565f-b42c-eda2b8b42651'::uuid, NULL, NULL, E'Actor / actress', NULL, NULL),
  ('b9e51898-6443-5e1e-83e7-842c149bde44'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b9e51898-6443-5e1e-83e7-842c149bde44'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the national flower of India?', 'b0d20429-0ebb-5c9b-8280-1b38004461c1'::uuid, NULL, NULL, E'Lotus', NULL, NULL),
  ('b9e58045-a211-552b-82ac-0ed3ebfece00'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b9e58045-a211-552b-82ac-0ed3ebfece00'::uuid, 1, NULL, TRUE, 0, NULL, E'Walking', NULL, '9f18219f-55d1-51f8-b10e-7d5539a46036'::uuid, NULL, E'Walking is the most fundamental basic form of human physical activity. The average sort of hunter-gatherer will take 10, 15,000 steps a day. The average American before the pandemic was taking something like 4,700 and something steps a day. Only about 20% of Americans get the very minimum levels of exercise that every health organization in the world thinks is the minimum for an adult- which is 150 minutes a week. So 80% of us really struggle and fail to get very basic amounts of exercise, but almost everyone says that they want to get enough exercise. We live in a world where we no longer have to be physically active. We now, in a very strange way, have to choose to be physically active, and that’s not so easy ’cause there were no ellipticals and other kinds of machines back in the Stone Age. If you wanna get your heart rate up you probably were running. And one of the biggest myths about running is that it’ll destroy your knees. There’s tons and tons of studies, more than a dozen randomized, controlled-perspective, gold standard studies, which show that people who run more are not more likely to get arthritis. In fact, lots of research shows that physical activities like running actually cause your joints to repair themselves and to stay healthy. The other kinds of running injuries- I think that a lot of them are caused because we don’t learn how to run properly anymore. I think running is a skill like swimming or throwing or, you know, all kinds of other things that we do.', NULL, NULL, NULL),
  ('b9e5f884-68fc-55f8-9666-68e3f284f3ab'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b9e5f884-68fc-55f8-9666-68e3f284f3ab'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for a system of government in which power is held by the people?', '883f443d-1efb-5b4d-95fd-e808fa5263a2'::uuid, NULL, NULL, E'Democracy', NULL, NULL),
  ('b9e85733-c450-58ff-bc27-7f6ac929307a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b9e85733-c450-58ff-bc27-7f6ac929307a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0263b5ff-f96c-5901-918c-f370e15f4bdf'::uuid, NULL, E'Her new job as a technician does not start until May.', NULL, NULL, NULL),
  ('b9ed9458-a6a3-586e-93f4-3ac34b753140'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'b9ed9458-a6a3-586e-93f4-3ac34b753140'::uuid, 1, NULL, TRUE, 0, NULL, E'Experience or Book', E'Knowledge gained from experience is more important than knowledge gained from books. To what extent do you agree with this statement?', NULL, NULL, E'The debate over the importance of knowledge gained from experience versus knowledge gained from books has long been a topic of discussion. While some argue that books provide a comprehensive and structured source of knowledge, others believe that experience is more important. In this essay, I will argue that knowledge gained from experience is more important than knowledge gained from books.\nFirstly, experience allows individuals to gain practical skills and insights that cannot be obtained solely from books. For example, someone who has never worked in a customer service role may have theoretical knowledge about how to handle difficult customers, but it is only through experience that they can truly develop the skills needed to excel in that role. Real-life experience provides individuals with a deeper understanding of how concepts and theories can be applied in practice.\nSecondly, experience fosters personal growth and development. Through experiencing different situations and challenges, individuals learn valuable lessons about themselves and the world around them. These lessons cannot be learned solely through reading books and require real-life experience to fully understand.\nIn conclusion, while books can provide a comprehensive source of knowledge, experience is more important in terms of gaining practical skills, insights, and personal growth. It is through experiencing different situations and challenges that individuals can truly understand how concepts and theories can be applied in practice. Therefore, it is important for individuals to seek out opportunities to gain real-life experience in addition to reading books in order to fully develop their knowledge and skills.', NULL, 200, 300),
  ('b9edd376-5f77-5845-b2c2-37fa08b70162'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b9edd376-5f77-5845-b2c2-37fa08b70162'::uuid, 1, NULL, TRUE, 0, NULL, E'Emotional Impacts', NULL, 'd1f6c894-717b-5c24-a08c-b6094e7322db'::uuid, NULL, E'I suppose that it has always been the case for the majority of us that the first test of a work of art or literature or music is how much pleasure it gives us, and we don''t want to bother with analysing why or how it has had such an emotional impact on us. It''s always good to know what your pleasures are in the positive sense - and not as easy as some people think - as opposed to only really knowing what you don''t like and complaining about it, though presumably there''s some kind of pleasure to be had from that too. But now that you''ve chosen to take a course on the novel, I''m afraid that evaluating literature on the basis of how you feel about a book won''t count as an intelligent critical response to the work being studied.\nIt is, however, useful to remind yourselves from time to time that we all fall for trash every now and again. For instance, you might actually enjoy listening to a catchy pop song, but you''d find it hard to explain in critical terms that it is good, or better than something else, just because it is enjoyable. So, you''re here to sharpen up your critical knives, as it were, among other things of course.', NULL, NULL, NULL),
  ('b9ef7958-4ba2-5a95-b2d4-ef207cf7ce9b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'b9ef7958-4ba2-5a95-b2d4-ef207cf7ce9b'::uuid, 1, NULL, TRUE, 0, NULL, E'Bothersome Symptoms', E'Have you ever felt fine at the doctor’s office, even though you had been experiencing bothersome symptoms before? This can be frustrating and confusing, especially if you have a chronic illness or a mental health issue. You may wonder if your doctor will take you seriously, or if you are making a big deal {{1}} nothing. However, experts say that this phenomenon is normal and common, and there are ways to deal with it. Symptoms can {{2}} due to various factors, such as stress, distraction, or coincidence. Your mental health can also affect your physical health, and {{3}} . Illness anxiety disorder, or hypochondria, is a serious mental condition that can affect one’s physical health and well-being. People with this disorder have a {{4}} fear of having an undiagnosed illness, despite having no or minimal symptoms. A recent Swedish study found that people with this disorder may die earlier than others, due to both natural and unnatural causes. However, there is hope for people with illness anxiety disorder, as effective treatments are available. Cognitive behavioral therapy, which helps patients identify and challenge their irrational thoughts and behaviors, is one of the most successful {{5}} .', NULL, NULL, NULL, E'1.out of, 2.fluctuate, 3.vice versa, 4.persistent, 5.interventions', NULL, NULL),
  ('b9f6672a-6c9e-507a-af42-cda5ce79fcd7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'b9f6672a-6c9e-507a-af42-cda5ce79fcd7'::uuid, 1, NULL, TRUE, 0, NULL, E'Misinformation', E'Misinformation is everywhere. It can be spread inadvertently if people make a genuine mistake. In today’s environment, people get much of their news from social media, which lacks gate-keepers and therefore allows misinformation to spread fast and wide. People are being bombarded with information and it has become difficult for them to separate fact from fiction.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ba09db9c-f93c-5e66-8555-f3f25ce9f661'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ba09db9c-f93c-5e66-8555-f3f25ce9f661'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'dc522b5f-a39e-5cd2-91d7-0114f2103cd3'::uuid, NULL, E'The student must attend the safety courses and wear protective goggles before entering the laboratory.', NULL, NULL, NULL),
  ('ba162382-04cc-5e21-aebb-9342b950dc03'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ba162382-04cc-5e21-aebb-9342b950dc03'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a6a8b5d9-9f82-548a-aec5-e0e585dd0ac5'::uuid, NULL, NULL, E'Art students often exhibit their works on the university buildings.', NULL, NULL),
  ('ba1875dd-1843-5831-9b5d-e4c4c4ca1d4d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ba1875dd-1843-5831-9b5d-e4c4c4ca1d4d'::uuid, 1, NULL, TRUE, 0, NULL, E'Musical', E'One of the most popular forms of theater is the musical. Combining drama, dance and music, the musical has been around for over a century, and in that time has kept pace with changing {{1}} and social {{2}} , as well as {{3}} in theater technology. Many modern musicals are known for their spectacular {{4}} , lighting and other effects.', NULL, NULL, NULL, E'1.tastes, 2.conditions, 3.advances, 4.sets', NULL, NULL),
  ('ba1ef93a-14d5-5fb7-bae7-03f5d3e885d9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ba1ef93a-14d5-5fb7-bae7-03f5d3e885d9'::uuid, 1, NULL, TRUE, 0, NULL, E'Critical Role of University', E'Universities are, of course, the primary centers of intellectual life in modern society. Therefore, they are a {{1}} center of criticism: criticism of society and of the dominant {{2}} in it, especially its politics, by sections of both the {{3}} and the student bodies. This critical {{4}} of the university, as the place where ideas are born and where support for criticism is {{5}} among students, who form the mass base for many protest movements, has been true for a long time and in many countries.', NULL, NULL, NULL, E'1.key, 2.trends, 3.staff, 4.role, 5.found', NULL, NULL),
  ('ba213dd7-4e60-529b-89e0-18823963ea85'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ba213dd7-4e60-529b-89e0-18823963ea85'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '36ae1129-8e0e-573b-b623-672df79c7554'::uuid, NULL, E'All students must participate in the exercise.', NULL, NULL, NULL),
  ('ba22bc3d-f9e0-5966-ac83-b27514f7ad02'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ba22bc3d-f9e0-5966-ac83-b27514f7ad02'::uuid, 1, NULL, TRUE, 0, NULL, E'Corporal Punishment', E'In the past, corporal punishment was a common disciplinary method in schools, reflecting a broader societal {{1}} of physical discipline as a means to enforce obedience and correct misbehavior. This form of punishment could involve the use of implements such as paddles, rulers, or canes to administer pain to students as a direct consequence of rule {{2}} , ranging from minor infractions like tardiness to more serious acts of disobedience or disrespect. Advocates believed that such measures instilled discipline, respect for authority, and moral values, arguing that the immediate and tangible nature of the punishment would {{3}} future misbehavior. However, over time, views on corporal punishment shifted dramatically. Research highlighting the potential psychological harm, including increased aggression, fear, and resentment towards authority {{4}} , coupled with evolving societal norms emphasizing children''s rights and non-violent forms of discipline, led to a significant decline in its use.', NULL, NULL, NULL, E'1.acceptance, 2.violations, 3.deter, 4.figures', NULL, NULL),
  ('ba25a644-1928-5382-8643-bd1806bab4d6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ba25a644-1928-5382-8643-bd1806bab4d6'::uuid, 1, NULL, TRUE, 0, NULL, E'Austria', E'Since Austria sits at a high elevation and spends a quarter of the year under {{1}} , it should come as no surprise that heating is a matter of considerable importance in the {{2}} . What may be surprising, however, is that Vienna — a grand imperial city of music, art, and history — actually boasts a museum {{3}} specifically to heating systems.', NULL, NULL, NULL, E'1.snow, 2.country, 3.dedicated', NULL, NULL),
  ('ba284347-879b-544b-8462-d3e2705e1f12'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ba284347-879b-544b-8462-d3e2705e1f12'::uuid, 1, NULL, TRUE, 0, NULL, E'Infants', E'Newborns typically sleep for about 16 to 18 hours a day, but the total amount of time spent sleeping gradually decreases to about 9 to 12 hours a day by age two years. At birth infants display a set of inherited {{1}} involving such acts as sucking, blinking, grasping, and limb withdrawal. Infants’ vision improves from 20/800 (in Snellen notation) among two-week-olds to 20/70 vision in five-month-olds to 20/20 at five years. Even newborns are {{2}} to certain visual patterns, chiefly movement and light-dark contrasts and show a noticeable preference for gazing at the human face; by the first or second month they can {{3}} between different faces, and by the third they can identify their mother by sight. Young infants also show a {{4}} for the tones of their mother’s voice, and they manifest a surprising sensitivity to the tones, rhythmic flow, and sounds that together make up human speech.', NULL, NULL, NULL, E'1.reflexes, 2.sensitive, 3.discriminate, 4.predilection', NULL, NULL),
  ('ba28f024-71b3-5bb5-8a71-2dc1229efead'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ba28f024-71b3-5bb5-8a71-2dc1229efead'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5b9d69f3-895b-51d2-9ecb-7b0ad936cc34'::uuid, NULL, NULL, E'We should eat plenty of fresh fruit and vegetables every day.', NULL, NULL),
  ('ba2908b0-38cf-5d0e-ac46-cbc1b346fcd4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ba2908b0-38cf-5d0e-ac46-cbc1b346fcd4'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'A compilation of songs or photos is also called what?', '95d5d1fa-83a5-5b6e-9ec7-e4542c6a5348'::uuid, NULL, NULL, E'Album', NULL, NULL),
  ('ba2bb550-a8c3-5b5f-9e79-cd8cf63402cb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ba2bb550-a8c3-5b5f-9e79-cd8cf63402cb'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3d86519a-38d8-53ba-9168-42fd8d5fee31'::uuid, NULL, NULL, E'The students have spent two days in a computer lab.', NULL, NULL),
  ('ba2bfb0a-bd65-54a9-9d78-db7952cab34c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'ba2bfb0a-bd65-54a9-9d78-db7952cab34c'::uuid, 1, NULL, TRUE, 0, NULL, E'Immune System', E'The immune system is a complex network of different organs, cells, and proteins that work together. There are 2 main parts of the immune system: the innate immune system - you are born with this, and the adaptive immune system - you develop this when your body is exposed to microbes or chemicals released by microbes. These two immune systems work together.\nThe innate immune system is your child''s rapid response system. It is the first to respond when it finds an invader. It is made up of the skin, the eye''s cornea, and the mucous membrane that lines the respiratory, gastrointestinal, and genitourinary tracts. These all create physical barriers to help protect your child''s body. They protect against harmful germs, parasites (such as worms), or cells (such as cancer). The innate immune system is inherited. It is active from the moment your child is born. When this system recognizes an invader, it goes into action right away. The cells of this immune system surround and cover the invader. The invader is killed inside the immune system cells (called phagocytes).\nThe acquired immune system, with help from the innate system, makes special proteins (called antibodies) to protect your body from a specific invader. These antibodies are developed by cells called B lymphocytes after the body has been exposed to the invader. The antibodies stay in your child''s body. It can take several days for antibodies to form. But after the first exposure, the immune system will recognize the invader and defend against it. The acquired immune system changes during your child''s life.Immunizations train your child''s immune system to make antibodies to protect them from harmful diseases.', NULL, NULL, E'The immune system is a complex network of different organs, cells, and proteins that work together, which mainly contains the innate immune system and the adaptive immune system; the innate immune system is the first to respond when it finds an invader, which is killed inside the immune system cells, and the acquired immune system makes special proteins to protect your body from a specific invader, as immunizations train the immune system to make antibodies.', NULL, 5, 75),
  ('ba2f152d-fec8-592f-8806-9ded7e7502e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ba2f152d-fec8-592f-8806-9ded7e7502e9'::uuid, 1, NULL, TRUE, 0, NULL, E'Colloquialism', E'Australians speak English of course. But for many tourists and even some locals, Australian English has only tenuous links with mother tone. Our speech is prepared with words and phrases whose arcane meanings are understood only by the initiate. It is these colorful colloquialisms that Australian slang set to truly explain.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ba30e307-1492-588f-880b-e71ed31aadc3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ba30e307-1492-588f-880b-e71ed31aadc3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'aaa607e4-03c2-5ee5-936b-1f2cb50b5a0c'::uuid, NULL, NULL, E'The university''s website has many additional useful resources available.', NULL, NULL),
  ('ba3b699b-4e1c-5d2e-8aaa-aad01bd6f2d0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ba3b699b-4e1c-5d2e-8aaa-aad01bd6f2d0'::uuid, 1, NULL, TRUE, 0, NULL, E'Psychology and Psychiatry', E'Psychology and psychiatry are often confused, yet they are distinct fields. Psychology focuses on the study of behavior and the mind, utilizing various therapeutic techniques for mental health {{1}} . Psychiatrists, on the other {{2}} , are medical doctors specializing in mental health, able to {{3}} medications alongside therapy. Both fields play crucial roles in mental health treatment, but they {{4}} it from different angles.', NULL, NULL, NULL, E'1.issues, 2.hand, 3.prescribe, 4.approach', NULL, NULL),
  ('ba3d256c-8f80-5ce3-9d6d-66a3c15f4eba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ba3d256c-8f80-5ce3-9d6d-66a3c15f4eba'::uuid, 1, NULL, TRUE, 0, NULL, E'SMW', E'So, just a few weeks ago excavators of a remote archeological site in southeastem Asia reported an exciting find under the ground, They found evidence of a writing system which dates back thousands of years. Three blocks of flat rock with odd symbols which look like ancient forms of writing were discovered. Well,this find could reveal much about an advanced, independent urban culture which historians believe may have lived in that area. However,many scholars are sceptical about the authenticity of the blocks,which they suspect - - - .\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '4cb1c834-cc71-56e7-8273-fbf6e070741f'::uuid, NULL, NULL, E'could very possibly be fake', NULL, NULL),
  ('ba3fecda-8374-5e60-9b0f-cc9209214c41'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ba3fecda-8374-5e60-9b0f-cc9209214c41'::uuid, 1, NULL, TRUE, 0, NULL, E'Winning at Work', E'From insistent emails to querying colleagues, many things can {{1}} our focus at work. So how can we {{2}} in our wandering minds? Switching off email and messaging services helps, and you should also put your smartphone and other {{3}} screens away – they attract our attention even if they are off.', NULL, NULL, NULL, E'1.disrupt, 2.rein, 3.extraneous', NULL, NULL),
  ('ba446565-baad-5beb-b354-9bd10e4430b6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ba446565-baad-5beb-b354-9bd10e4430b6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a3e3a33f-3f9d-5731-91e3-5a269897c5c7'::uuid, NULL, NULL, E'Mechanical evolution became a predominant phenomenon during the Industrial Revolution.', NULL, NULL),
  ('ba4b51ac-7ac3-5c4d-be7c-fd00edbc4cee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ba4b51ac-7ac3-5c4d-be7c-fd00edbc4cee'::uuid, 1, NULL, TRUE, 0, NULL, E'Mini Helicopter', E'A mini helicopter modelled on flying tree seeds could soon be flying overhead. Evan Ulrich and colleagues at the University of Maryland in College Park {{1}} the biological world for inspiration to build a scaled-down helicopter that could mimic the properties of full-size aircraft.\nThe complex {{2}} of full-size helicopters gets less efficient when shrunk, meaning that standard mini helicopters expend most of their power simply fighting to stay stable in the air. The researchers realized that a simpler aircraft designed to stay stable passively would use much less power and reduce manufacturing costs to boot.\nIt turns out that nature {{3}} them to it. The seeds of trees such as the maple have a single-blade structure that {{4}} them to fly far away and drift safely to the ground. These seeds, known as samaras, need no engine to {{5}} through the air, thanks to a process called autorotation. By analyzing the behavior of the samara with high-speed cameras, Ulrich and his team were able to copy its design.', NULL, NULL, NULL, E'1.turned to, 2.design, 3.had beaten, 4.allows, 5.spin', NULL, NULL),
  ('ba4e590a-30f6-5deb-b96f-273180304a1f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'ba4e590a-30f6-5deb-b96f-273180304a1f'::uuid, 1, NULL, TRUE, 0, NULL, E'Chinese Architecture', E'The most significant difference between traditional Chinese architecture and traditional western Western architecture is the construction material. Most ancient Western buildings were built up with stones, solemn and magnificent. Most importantly, they survive today. Ancient Chinese people were very good at using wood, and created the complex mortise and tenon joint structure to bring in the unique aesthetics for ancient Chinese wooden architecture. Most of the palaces, temples and pagodas of ancient China were built with wood. They were energy-efficient, environmentally-friendly and durable, but were easily destroyed by fire in history. Fortunately, there are still many ancient Chinese wooden architecture gems left and preserved today.\nChinese architecture is almost as old as Chinese civilization. The wooden architecture of stilt style founded in the Hemudu Site of Neolithic Age is the earliest to date, with a history of over 6000 years. The wood and mud walls of Banpo Neolithic Village have a history of around 5000 years. In addition, archaeologists have found massive wooden palaces and imperial tombs in Yin Ruins, Anyang City, Henan Province, dating back to 1400BC - 1100BC during the Shang Dynasty. Over the next 3,000 years, Chinese wooden architecture, through the replacements of dozens of dynasties, retains its prominent features. Of China’s 50 UNESCO heritage sites, most are cultural heritages related to architecture.\nThe wooden buildings of ancient China, whether they are royal palaces or folk houses, whether they are located in the densely populated capitals or thinly populated mountainous areas, follow the same architectural system, which has three basic elements, a huge foundation platform, a timber frame and body, wooden ceiling with decorated roof.', NULL, NULL, NULL, NULL, 5, 75),
  ('ba4ed9f7-a44b-5c2c-9fdf-b79846ce7e2e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ba4ed9f7-a44b-5c2c-9fdf-b79846ce7e2e'::uuid, 1, NULL, TRUE, 0, NULL, E'Matthew Brady', E'In 1861, Matthew Brady, a well-known portrait photographer, approached President Lincoln requesting permission to move freely around the country photographing the Civil War. Lincoln granted him permission to travel anywhere with the Union armies, and his record of this conflict brought home to millions the horrors of war.', NULL, NULL, NULL, NULL, NULL, NULL),
