  ('ba814268-075f-5d3c-96e9-d6a145038781'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ba814268-075f-5d3c-96e9-d6a145038781'::uuid, 1, NULL, TRUE, 0, NULL, E'Role Modeling', E'If the need for organizational change is communicated from the top down, it must be modeled from the top down as well. When a corporate leader is truly {{1}} to change, he or she becomes a guiding light for the entire organization. A leader can model change through public actions such as press conferences or presentations. More significant, however, are actions that show that the leader is truly taking his or her own ideas to {{2}} . Not only is it inspiring to see a leader taking his or her own advice to heart, but it’s also helpful to see what the change really looks like. Robert Iger, who became CEO of Disney, was concerned that innovation was fading. To show his commitment to cultural change, he {{3}} in to provide hands-on help with game creation.', NULL, NULL, NULL, E'1.committed, 2.heart, 3.jumped', NULL, NULL),
  ('ba856c94-d7d1-5c61-bcf2-e320fb21a4e6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ba856c94-d7d1-5c61-bcf2-e320fb21a4e6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '27a087b3-af3f-5ad3-8453-a8318b4e0269'::uuid, NULL, NULL, E'Ensure your essays are submitted by Friday noon without fail.', NULL, NULL),
  ('ba87fbaf-c6f3-5b28-8bdf-d2e8b1c81ba5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'ba87fbaf-c6f3-5b28-8bdf-d2e8b1c81ba5'::uuid, 1, NULL, TRUE, 0, NULL, E'Geothermal Power', E'Huge reserves of energy have been found in rocks far below the surface of the ground in Britain. It is estimated that the north and southwest regions could hold enough energy in the form of heat to provide power for millions of homes. In fact, up to a fifth of Britain''s energy could be provided by this geothermal source. Extracting the heat and converting it into electricity is difficult and expensive. Thousands of bore holes would be needed; but once they were in place, the heat would keep regenerating indefinitely.\n\nWhat is the writer''s main purpose in this paragraph?', NULL, NULL, NULL, E'to highlight the potential benefits of geothermal power for Britain', NULL, NULL),
