  ('ba982443-0aae-5e77-b5ab-75e17c789803'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ba982443-0aae-5e77-b5ab-75e17c789803'::uuid, 1, NULL, TRUE, 0, NULL, E'Great Depression', E'The Great Depression, which began in 1929 and lasted until the late 1930s, was the most {{1}} and prolonged economic downturn in the history of the Western industrialized world. Its causes are complex and multifaceted, reflecting a combination of {{2}} and international conditions that conspired to {{3}} economic stability and confidence. One of the primary causes was the over-speculation in the stock market, which had become disconnected from the real economy. Throughout the 1920s, the U.S. stock market {{4}} rapid expansion, reaching its peak in August 1929, after a decade of roaring growth. This speculative bubble was partly fueled by the widespread use of margin buying, {{5}} investors borrowed money to buy stocks, betting on continued increases in stock prices. However, when the market began to decline in late 1929, panic set in, leading to a catastrophic crash in October.', NULL, NULL, NULL, E'1.severe, 2.domestic, 3.undermine, 4.underwent, 5.where', NULL, NULL),
  ('ba991aae-afa8-5751-aac9-8f461d66774c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ba991aae-afa8-5751-aac9-8f461d66774c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ae2ee256-47ba-5ea7-a20f-7ce6759505a7'::uuid, NULL, NULL, E'There are many ways to manage a business well.', NULL, NULL),
  ('baa88dcd-6ca8-51d1-80fe-1095dcb85770'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'baa88dcd-6ca8-51d1-80fe-1095dcb85770'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9c51b6db-844e-50f8-afee-a6af342e338b'::uuid, NULL, NULL, E'Reaching the university on foot can be a lengthy endeavor.', NULL, NULL),
  ('baaaedba-1de0-518c-8c71-a73852e55f61'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'baaaedba-1de0-518c-8c71-a73852e55f61'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9a31e9f8-3a36-5df1-a42a-87d15140e546'::uuid, NULL, NULL, E'It is expected that the report will suggest some major reforms.', NULL, NULL),
  ('bab6add4-8359-55fd-b406-244c6f516c81'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'HIGHLIGHT_CORRECT_SUMMARY', E'HIGHLIGHT_CORRECT_SUMMARY', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'bab6add4-8359-55fd-b406-244c6f516c81'::uuid, 1, NULL, TRUE, 0, NULL, E'Ernest Hemingway', E'Ernest Hemingway was famously masculine. We can see this in the topics he wrote about: all those fights and bullfights, all those wars, all that hunting and fishing. All this, it is thought, was overdoing it and must point to some deep insecurity in the man. Perhaps he felt that the conventional image of a writer as a person who doesn''t do a lot more than sitting at a desk, not visibly contributing much socially or economically to society as a whole was unmanly and carried a certain amount of guilt and shame with it?\nDuring the First World War, he was badly wounded, hospitalized, and fell in love with a nurse. He wrote a novel about a man who was badly wounded in the First World War, was hospitalised and who fell in love with a nurse. The Spanish Civil War and the Second World War followed as did books about his experiences in them. Now, how much can we draw on a writer''s biography to explain h is work? It should, l believe, be irrelevant to the judgement you bring to the merits of the individual work.\nBiographies of writers can be fascinating, especially if they lived as hard and fast as Hemingway, but, unfortunately, these days many people prefer the biography to the actual work. It is odd that the very reason a person would want to read a biography of a writer - that the subject has achieved fame and distinction in his field - should be the excuse for not reading his works.\n\nClick on the paragraph that best relates to the recording.', 'a4c0f7da-44eb-5ea2-984e-b26bb8a4b881'::uuid, NULL, NULL, E'The main point is to question whether the biographical facts of a writer''s life are of any importance in evaluating his work. Hemingway is the example used here, and there does seem to be a direct connection between the events of his life and those in his books, but knowing this should not get in the way of a true critical judgement of the works.', NULL, NULL),
  ('babb9c10-f6dc-5295-b368-17f6da8f5bde'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'babb9c10-f6dc-5295-b368-17f6da8f5bde'::uuid, 1, NULL, TRUE, 0, NULL, E'Effective Practice', NULL, 'b5e17745-a34a-5380-ab3a-a7f72a626dfb'::uuid, NULL, E'There are many theories that attempt to quantify the number of hours, days, and even years of practice that it takes to master a skill. While we don’t yet have a magic number, we do know that mastery isn’t simply about the amount of hours of practice. It’s also the quality and effectiveness of that practice. Effective practice is consistent, intensely focused, and targets content or weaknesses that lie at the edge of one’s current abilities. So if effective practice is the key, how can we get the most out of our practice time? Try these tips: Focus on the task at hand. Minimize potential distractions by turning off the computer or TV and putting your cell phone on airplane mode. In one study, researchers observed 260 students studying. On average, those students were able to stay on task for only six minutes at a time. Laptops, smartphones, and particularly Facebook were the root of most distractions. Start out slowly or in slow-motion. Coordination is built with repetitions, whether correct or incorrect. If you gradually increase the speed of the quality repetitions, you have a better chance of doing them correctly. Next, frequent repetitions with allotted breaks are common practice habits of elite performers. Studies have shown that many top athletes, musicians, and dancers spend 50-60 hours per week on activities related to their craft. Many divide their time used for effective practice into multiple daily practice sessions of limited duration. And finally, practice in your brain in vivid detail.', NULL, NULL, NULL),
  ('bac24585-f485-5656-b0b9-cc3997094218'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'bac24585-f485-5656-b0b9-cc3997094218'::uuid, 1, NULL, TRUE, 0, NULL, E'Concentration', E'Some students say that they need complete quiet to read and study. Others study best in a crowded, noisy room because the noise actually {{1}} them concentrate. Some students like quiet music playing; {{2}} do not. The point is, you should know the level of noise that is optimal for your own studying. However, one general rule for all students is that the television seems to be more of a distraction than music or other background noise, so {{3}} the TV off when you are reading or studying. {{4}} , don''t let yourself become distracted by computer games, email, or Internet surfing.', NULL, NULL, NULL, E'1.helps, 2.others, 3.leave, 4.Also', NULL, NULL),
  ('bac57aae-ffbf-5c0c-8369-6238e1206198'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'bac57aae-ffbf-5c0c-8369-6238e1206198'::uuid, 1, NULL, TRUE, 0, NULL, E'Rosalind Franklin', E'Rosalind Franklin was an English scientist born in 1920. She was brilliant at using X-ray crystallography, a method to see the tiny details of molecular structures. Franklin''s most famous work was on the DNA molecule, which {{1}} our genetic information. In the early 1950s, she took a picture known as Photo 51. This image was key to understanding the DNA structure, but Franklin''s contribution was not {{2}} recognized at the time. Two other scientists, Watson and Crick, used Franklin''s findings to build a model of DNA''s double helix structure. They won a Nobel Prize for this, but Franklin did not share in the honor because Nobel Prizes are not awarded posthumously, and she had passed away by {{3}} . Today, we remember Franklin for her critical role in discovering the DNA structure and her {{4}} work in science.', NULL, NULL, NULL, E'1.carries, 2.fully, 3.then, 4.pioneering', NULL, NULL),
  ('bac8cac6-529c-5516-9bb0-6182b510cdcc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'bac8cac6-529c-5516-9bb0-6182b510cdcc'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '64ac4359-61aa-52bd-89de-4a744f18dfa4'::uuid, NULL, NULL, E'Services are rapidly growing in parts of the global economy.', NULL, NULL),
  ('bac90e6e-ca6d-5b17-a719-8f30c7265e1d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'bac90e6e-ca6d-5b17-a719-8f30c7265e1d'::uuid, 1, NULL, TRUE, 0, NULL, E'Academic Writing', E'Academic writing experts suggest {{1}} your skills by engaging regularly with scholarly texts. They advise starting with a clear thesis and {{2}} it up with well-researched evidence. Effective academic writing hinges on developing a coherent argument and presenting it in a structured manner. Their clear structure, when done right, can turn complex ideas into {{3}} articles.', NULL, NULL, NULL, E'1.honing, 2.backing, 3.comprehensible', NULL, NULL),
  ('bac9bbdc-971b-5d36-a14d-32d674ece200'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'bac9bbdc-971b-5d36-a14d-32d674ece200'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '82b97309-15b2-51b6-a6e0-7600f0be0f39'::uuid, NULL, NULL, E'The exact number of people carrying the virus is unknown.', NULL, NULL),
