  ('bb66f95d-6f8b-5789-b81e-307d6a7790e7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bb66f95d-6f8b-5789-b81e-307d6a7790e7'::uuid, 1, NULL, TRUE, 0, NULL, E'GDP', E'Using GDP alone as a measure of a nation’s wealth only tells you half of the story. Bigger and more populous countries have a distinct advantage, since they have more workers to produce more goods and services. The only way to make an apples-to-apples comparison is to calculate each country’s GDP per capita.', NULL, NULL, NULL, NULL, NULL, NULL),
