  ('bb7112bf-961b-576b-bb5e-c314168e48f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bb7112bf-961b-576b-bb5e-c314168e48f0'::uuid, 1, NULL, TRUE, 0, NULL, E'Battery', E'Scientists have improved a promising battery technology, creating a single-crystal, nickel-rich cathode that is hardier and more efficient than before. It''s one step toward improved lithium-ion batteries that are common in electric vehicles today. Increasing nickel content in the cathode is on the drawing board of lithium-ion battery makers largely because of its relatively low cost, wide availability and low toxicity compared to other key battery materials, such as cobalt.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('bb7464b1-ab6b-53d2-a178-7b60f9bc0428'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bb7464b1-ab6b-53d2-a178-7b60f9bc0428'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do you call the device that produces electricity?', '511851b5-445c-5d35-af4c-811858b4f0bc'::uuid, NULL, NULL, E'Generator', NULL, NULL),
  ('bb7abd21-8a26-5d3e-87c9-bb16e19914a3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'bb7abd21-8a26-5d3e-87c9-bb16e19914a3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd2a239c1-77b0-5b8e-af34-b93fbca791d0'::uuid, NULL, NULL, E'Speed is defined as how quickly an object or a person moves.', NULL, NULL),
