  ('bb7d251c-3877-55d8-a555-8310b0fa38a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bb7d251c-3877-55d8-a555-8310b0fa38a6'::uuid, 1, NULL, TRUE, 0, NULL, E'License Plates', E'Initially, license plates were issued to last the life of the vehicle, but by the 1920s, registration renewal became a thing. During this time, states began experimenting with different methods of creating license plates. Typically, the front of the registration card would have the registration number in large, centered numbers while the back would have the abbreviated name of the state and a two- or four-digit year of validity.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('bb7ed46c-2882-50b4-a2cc-0d79bcb9dd72'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'bb7ed46c-2882-50b4-a2cc-0d79bcb9dd72'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '91e5a65e-ef42-561b-9cc2-ca0d3923bc8f'::uuid, NULL, NULL, E'Lots of laboratory tests have been carried out this week.', NULL, NULL),
