  ('bb8a4d9f-c96b-508f-83b3-0b347f66e95d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bb8a4d9f-c96b-508f-83b3-0b347f66e95d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call the substances used to speedup a chemical reaction?', 'febb9ba7-f266-5340-bab7-89038b4d29f7'::uuid, NULL, NULL, E'Catalyst', NULL, NULL),
  ('bb8b31b7-014f-5e5c-9467-54ed0199fa2c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bb8b31b7-014f-5e5c-9467-54ed0199fa2c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the northernmost and southernmost parts of the earth?', 'a78fa8fc-e33e-5a9d-97bc-b101258b9d4e'::uuid, NULL, NULL, E'Pole / poles', NULL, NULL),
  ('bb8ebdea-35ee-5e62-8c8d-3d1da045be55'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bb8ebdea-35ee-5e62-8c8d-3d1da045be55'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c15711d1-0461-5e9f-8e6a-0a4bbaef301f'::uuid, NULL, E'We are not going to accept the assignment after the due date on Friday.', NULL, NULL, NULL),
  ('bba2ff4c-767a-5aff-ad8d-7d03ad2a2e8a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bba2ff4c-767a-5aff-ad8d-7d03ad2a2e8a'::uuid, 1, NULL, TRUE, 0, NULL, E'Fibre', NULL, '3805a51c-dede-5177-9877-68661f7fa86d'::uuid, NULL, E'Fiber is amazing. It affects the digestive tract from top to bottom. It is very simply a carbohydrate the body can’t absorb. While other carbs are broken down into sugars, fiber passes by sort of moseying along, doing all kinds of cool things. High-fiber foods physically take longer to eat, so they help us pace our meals. The bulk also slows down digestion, especially in the stomach, and makes you feel full longer. Fiber also draws water into the stool, keeping it soft. Scratchy, hard stool is, to put it mildly, unpleasant. It also increases bacterial mass. The water and bacteria together increase the bulk of the stool, which helps it move along. Fiber also slows absorption of sugars into the bloodstream and reduces absorption of fats and cholesterols. And as fiber collects in your colon, it feeds all your good gut bacteria, helping you maintain a healthy microbiome. Fiber is associated with the reduced risk of diabetes, heart disease, several gastrointestinal conditions and even certain cancers.', NULL, NULL, NULL),
  ('bba43aec-db0d-5252-98c5-d8270959d1d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'bba43aec-db0d-5252-98c5-d8270959d1d5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '938eb65f-3b7c-5c39-b0ac-d8d0b6c16e89'::uuid, NULL, NULL, E'Building trust is not something that can be achieved overnight.', NULL, NULL),
