  ('bc04be03-ce25-5b9c-b0f0-ab88f4c06220'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'bc04be03-ce25-5b9c-b0f0-ab88f4c06220'::uuid, 1, NULL, TRUE, 0, NULL, E'Koalas', E'In previous project work, the number of koalas was not known but distribution had been recorded {{1}} an area of 2000 square kilometres in {{2}} featuring manna gum and the nationally endangered Eyre Peninsula blue gum woodland communities. To {{3}} , there is no evidence to suggest that koalas can self-regulate their numbers as kangaroos do. There were {{4}} koalas might eventually consume all the available food in an area, resulting in their own {{5}} .', NULL, NULL, NULL, E'1.across, 2.habitats, 3.date, 4.concerns, 5.starvation', NULL, NULL),
  ('bc0db53d-e89c-527a-8f0d-7d329400ee53'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'bc0db53d-e89c-527a-8f0d-7d329400ee53'::uuid, 1, NULL, TRUE, 0, NULL, E'Latino Vote', E'Much has been said of the Latino vote in this election, which is something I know a little bit about, having been working {{1}} over it for the last 16 years. Latinos are the fastest-growing {{2}} , with the largest voter registration cap in America. A Latino youth turns 18 every 30 seconds. While the mode for whites in America is 58, the mode for Latinx is 11 years old. You heard that right. And it''s these new voters and the youth who are translating America for their immigrant {{3}} who are leading the charge for {{4}} change.', NULL, NULL, NULL, E'1.obsessively, 2.demographic, 3.families, 4.audacious', NULL, NULL),
  ('bc15ea48-12d2-51cc-845f-cd33c07a5f4a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'bc15ea48-12d2-51cc-845f-cd33c07a5f4a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '07980521-66e5-57a6-bc60-47f7f2f5d8b1'::uuid, NULL, NULL, E'The author is currently a professor at Cambridge University.', NULL, NULL),
