  ('bc80e057-49cf-5348-aa6d-d13a9ebf3279'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bc80e057-49cf-5348-aa6d-d13a9ebf3279'::uuid, 1, NULL, TRUE, 0, NULL, E'Volunteering', E'For graduates looking to give something back, volunteering, either in the UK or overseas, is a popular option. Voluntary projects can cost anything from nothing up to a few thousand pounds, and with that in mind it is essential to look into the project carefully before signing on the dotted line.', NULL, NULL, NULL, NULL, NULL, NULL),
