  ('bce6ce09-fa3f-58ca-8c30-3ddbe6d0c57e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'bce6ce09-fa3f-58ca-8c30-3ddbe6d0c57e'::uuid, 1, NULL, TRUE, 0, NULL, E'Exploration of Space', E'The exploration of space extends beyond the quest to visit distant planets; it''s about understanding our place in the {{1}} universe. Astronomers and astrophysicists use cutting-edge technology to observe {{2}} phenomena, from black holes to the cosmic microwave background. These explorations {{3}} the boundaries of human knowledge and {{4}} our collective imagination about what lies beyond our planet.', NULL, NULL, NULL, E'1.vast, 2.celestial, 3.push, 4.spark', NULL, NULL),
  ('bce77bb6-03ec-53a8-822a-6a5329cf9f6a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'bce77bb6-03ec-53a8-822a-6a5329cf9f6a'::uuid, 1, NULL, TRUE, 0, NULL, E'Kashmiri', E'Two decades ago, Kashmiri houseboat-owners rubbed their hands every spring at the prospect of the annual influx of {{1}} . From May to October, the hyacinth-choked {{2}} of Dal Lake saw flotillas of vividly painted Shikaras carrying Indian families, boho westerners, young travellers and wide-eyed Japanese. Carpet-sellers {{3}} their skills, as did purveyors of anything remotely embroidered while the house boats initiated by the British Raj provided unusual accommodation. Then, in 1989, separatist and Islamist militancy {{4}} and everything changed. Hindus and countless Kashmiri business people bolted, at least 35,000 people were killed in a decade, the lake stagnated, and the houseboats rotted. Any foreigners venturing there risked their {{5}} , proved in 1995 when five young Europeans were kidnapped and murdered.', NULL, NULL, NULL, E'1.tourists, 2.waters, 3.honed, 4.attacked, 5.lives', NULL, NULL),
