  ('bd55af8c-2993-5d6b-8dbc-9e8b4dd3486c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'bd55af8c-2993-5d6b-8dbc-9e8b4dd3486c'::uuid, 1, NULL, TRUE, 0, NULL, E'Welfare Morality', E'The morality of the welfare state depends on contribution and responsibility. Since some people don''t contribute and many are irresponsible, the choices of those who do contribute and are responsible are either to {{1}} the free riders, refuse to pay for the {{2}} of their irresponsibility or trust the state to {{3}} them.', NULL, NULL, NULL, E'1.tolerate, 2.effects, 3.educate', NULL, NULL),
  ('bd5c98f3-b24e-5f23-a0f0-9293cabaae05'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bd5c98f3-b24e-5f23-a0f0-9293cabaae05'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How many months does a season have?', '352548b9-aa5f-5265-877d-aceccf8143af'::uuid, NULL, NULL, E'Three', NULL, NULL),
  ('bd6d2ee7-da86-544d-ad7f-9ff288a57dfe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'bd6d2ee7-da86-544d-ad7f-9ff288a57dfe'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '47c23100-2247-584a-8d1d-53ea36b62619'::uuid, NULL, NULL, E'I will be back in several minutes.', NULL, NULL),
  ('bd6dba50-8389-5641-9a62-2da0a799c466'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'bd6dba50-8389-5641-9a62-2da0a799c466'::uuid, 1, NULL, TRUE, 0, NULL, E'Starvation', E'Over weeks and months, malnutrition can result in specific diseases, like anemia when people don''t get enough iron or beriberi if they don''t get adequate thiamine. A {{1}} lack of food for a prolonged period — not enough calories of any sort to keep up with the body''s energy needs — is starvation. The body''s reserve resources are {{2}} . The result is substantial weight loss, wasting away of the body''s tissues and eventually death. When faced with starvation, the body fights back. The first day without food is a lot like the overnight fast between dinner one night and breakfast the next morning. Energy levels are low but {{3}} up with a morning meal. Within days, faced with nothing to eat, the body begins feeding on itself. Metabolism slows; the body cannot regulate its temperature; kidney function is impaired and the immune system {{4}} . When the body uses its reserves to provide basic energy needs, it can no longer supply necessary nutrients to vital organs and tissues. The heart, lungs, ovaries and testes shrink. Muscles shrink and people feel weak. Body temperature drops and people can feel chilled. People can become {{5}} , and they become difficult to concentrate.', NULL, NULL, NULL, E'1.severe, 2.depleted, 3.pick, 4.weakens, 5.irritable', NULL, NULL),
  ('bd7858f9-5108-52d1-bea2-8c94b28b61be'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bd7858f9-5108-52d1-bea2-8c94b28b61be'::uuid, 1, NULL, TRUE, 0, NULL, E'Climate Change', NULL, '3d06d565-6b48-5385-9739-5366e777c0f5'::uuid, NULL, E'Climate change, some adverse effects of climate changes to agricultural productions. Some lands are unsuitable for growing crops. There will be millions of people facing hunger in Africa in the future. Climate change will result in less production and less food. It is difficult for developing countries to deal with climate change due to their financial status and other issues. There are many people living in hunger especially in Africa. The climate change has devastating effects on world economy. The tropical areas on earth are dry and hot, and are originally not suitable for food production. The change of the climate leads to extreme weather conditions such as flood and hurricane, which exacerbates the food production. As a result, it leads to a continuous decline in food supply annually around 10-17%. And this trend is perceived to be continue in the future by 2070. The regions suffering the most will be some African countries.', NULL, NULL, NULL),
  ('bd7dbc1c-91cd-538a-94d4-e3ddd07740d9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bd7dbc1c-91cd-538a-94d4-e3ddd07740d9'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'If a person is not telling the truth, then what is he or she telling?', '853a66c0-f0af-5edc-abcb-fe000b7f1eac'::uuid, NULL, NULL, E'Lie / lies', NULL, NULL),
  ('bd870098-957c-56ac-9a20-3c017620facb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'bd870098-957c-56ac-9a20-3c017620facb'::uuid, 1, NULL, TRUE, 0, NULL, E'Vegetative Propagation', E'Because vegetative propagation is a form of asexual reproduction, plants produced through this system are genetic clones of a parent plant. One advantage of vegetative propagation is that plants with {{1}} traits are repeatedly reproduced. Commercial crop growers can employ {{2}} vegetative propagation techniques to ensure advantageous {{3}} in their crops. A major disadvantage, however, of vegetative propagation is that it does not allow for any degree of genetic {{4}} .', NULL, NULL, NULL, E'1.favorable, 2.artificial, 3.qualities, 4.variation', NULL, NULL),
