  ('bda372f4-83cc-52cb-acaa-53a70f0e955e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'bda372f4-83cc-52cb-acaa-53a70f0e955e'::uuid, 1, NULL, TRUE, 0, NULL, E'Workplace Flexibility', E'As the modern workplace evolves, there is growing {{1}} of the importance of work-life balance for all employees. Both men and women are increasingly {{2}} responsibilities for household duties and child {{3}} . Consequently, many companies are {{4}} flexible work policies that support diverse roles to help employees balance professional and personal commitments.', NULL, NULL, NULL, E'1.recognition, 2.sharing, 3.care, 4.enforcing', NULL, NULL),
