  ('bdb98e9e-58a2-568e-bb12-869a9db514a3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'bdb98e9e-58a2-568e-bb12-869a9db514a3'::uuid, 1, NULL, TRUE, 0, NULL, E'Poverty', E'Measuring poverty on a global scale {{1}} establishing a uniform poverty level across extremely divergent economies, which can result in only rough comparisons. The World Bank has defined the international poverty line as U.S. $1 and $2 per day in 1993 Purchasing Power Parity (PPP), which adjusts for differences in the {{2}} of goods and services between countries. The $1 per day level is generally used for the {{3}} developed countries, primarily African; the $2-per-day level is used for middle- {{4}} economies such as those of East Asia and Latin America.', NULL, NULL, NULL, E'1.requires, 2.prices, 3.least, 4.income', NULL, NULL),
