  ('be79b85f-149d-52ee-ac45-90289ef6263a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'be79b85f-149d-52ee-ac45-90289ef6263a'::uuid, 1, NULL, TRUE, 0, NULL, E'Sedentary Lifestyle', E'A sedentary lifestyle eventually takes a {{1}} on health but snapping out of prolonged inactivity can be daunting. Now, however, there may be a simple way to {{2}} into more activity. A recent study suggests that short bursts of vigorous activity every day — climbing stairs, carrying a heavy load of groceries, or {{3}} up the pace of housework — can provide {{4}} health benefits.', NULL, NULL, NULL, E'1.toll, 2.ease, 3.stepping, 4.substantial', NULL, NULL),
