  ('beea789d-ea8f-55e0-8c03-19ac35daf6ea'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'beea789d-ea8f-55e0-8c03-19ac35daf6ea'::uuid, 1, NULL, TRUE, 0, NULL, E'Global Order', E'The defining question about global order for this generation is whether China and the United States can escape Thucydides’s Trap. The Greek historian’s metaphor reminds us of the attendant dangers when a rising power rivals a ruling power—as Athens challenged Sparta in ancient Greece, or as Germany did Britain a century ago.', NULL, NULL, NULL, NULL, NULL, NULL),
