  ('bef92da3-f1f3-513a-bc44-c2976672c554'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bef92da3-f1f3-513a-bc44-c2976672c554'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '38c83417-c74f-5e62-a1d8-82b7dd34e851'::uuid, NULL, E'It seems that language appears from nowhere.', NULL, NULL, NULL),
  ('befca457-0b9c-56f4-a762-74680fa7da15'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'befca457-0b9c-56f4-a762-74680fa7da15'::uuid, 1, NULL, TRUE, 0, NULL, E'Chicxulub Crater', E'Hidden below the waters of the Gulf of Mexico, the Chicxulub crater marks the impact site of an asteroid that {{1}} Earth 66 million years ago. The most {{2}} outcome of this cataclysmic event was the fifth mass extinction, which {{3}} out about 80% of all animal species, including the non-avian dinosaurs.', NULL, NULL, NULL, E'1.struck, 2.consequential, 3.wiped', NULL, NULL),
  ('befd1fb0-f7be-5037-9088-af6a8265705e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'befd1fb0-f7be-5037-9088-af6a8265705e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a private teacher who gives you lessons outside school hours?', '8d6db399-0bc4-584d-8b62-61aa9c00c14b'::uuid, NULL, NULL, E'Tutor', NULL, NULL),
  ('bf0e1009-9a15-574a-8a3b-afc827a3d7de'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bf0e1009-9a15-574a-8a3b-afc827a3d7de'::uuid, 1, NULL, TRUE, 0, NULL, E'Summer Learning Loss', NULL, '4dd0fee3-7184-5ed1-89fb-24275ff1738e'::uuid, NULL, E'The summer learning loss is a term that they use to describe the regressions that kids in low-income neighborhoods face relative to their affluent peers. So they say in lower income neighborhoods kids forget anywhere from two-and-a-half to three-and-a-half months of what they learned during the school year over the summer, while their middle-class peers break even or even make gains. When I first learned about the achievement gap I was a freshman in college and I certainly wanted to understand what the causes of it were. And as I started to do my research I realized that there were a thousand different reasons why the achievement gap existed: everything from a lack of positive role models to poor health conditions in so many of these inner-city and low-income neighborhoods. And then I found this startling statistic that said that two-thirds of the achievement gap could be directly attributed to unequal summer learning opportunities, or the summer learning loss. In low-income neighborhoods, kids forget anywhere from two-and-a-half to three-and-a-half months of what they learn over the summer from the school year, and so when they return to school they’re now two-and-a-half to three-and-a-half months behind their affluent or their middle class peers. Just to put that in perspective for you all: the school year from September to June is only ten months long. If a kid forgets two-and-a-half to three-and-a-half months of what they learned, that’s almost 25 to 35 percent of their learning. Teachers have then reported that they spend anywhere from a month-and-a-half to two months reteaching old material. So if you add that additional 20 percent you’re talking about 50 percent of a kid’s learning. So we sit here and we ask ourselves, “Why does an eighth grader only have a fourth grade reading level?” and the truth of the matter is that theoretically speaking they’ve only been in school for half the time.', NULL, NULL, NULL),
  ('bf1a7f39-7214-5305-8071-4c38a6445656'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'bf1a7f39-7214-5305-8071-4c38a6445656'::uuid, 1, NULL, TRUE, 0, NULL, E'Water Temperature', E'Changes in water temperature can affect the environments where fish, shellfish, and other marine species live. Certain fish species naturally {{1}} in response to seasonal temperature changes, moving northward or to deeper, cooler waters in the summer and migrating back during the winter. As climate change causes the oceans to become warmer year-round, however, populations of some species may {{2}} by shifting away from areas that have become too warm and toward areas that were previously cooler. Marine species represent a particularly good {{3}} of warming oceans because they are sensitive to climate and because they have been studied and tracked for many years. Fish are especially {{4}} ,and they may shift their location more easily than species on land because they face fewer physical barriers. Populations of many marine species have been measured {{5}} for several decades across various types of ocean habitats. Tracking data from many species is useful because if a change in behavior or distribution occurs across a large range of species, it is more likely the result of a more systematic or common cause.', NULL, NULL, NULL, E'1.migrate, 2.adapt, 3.indicator, 4.mobile, 5.consistently', NULL, NULL),
  ('bf1dff6b-2e42-51f9-8532-0ee5ece2158e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'bf1dff6b-2e42-51f9-8532-0ee5ece2158e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b0bcae55-97f4-5432-912a-ee2218119cdc'::uuid, NULL, NULL, E'The program examines the scientific technology influencing the food industry.', NULL, NULL),
  ('bf22ac31-fa2b-5343-bc06-c83e0f36170a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'bf22ac31-fa2b-5343-bc06-c83e0f36170a'::uuid, 1, NULL, TRUE, 0, NULL, E'Green Spaces', E'Green spaces contribute significantly to a {{1}} in soil and aerial temperatures during spells of hot weather, so contributing to human wellbeing. In the garden {{2}} , there is, however, little information as to what extent various types of plants {{3}} in their cooling potential and how certain planting combinations may maximize cooling under a scenario of {{4}} rainfall and minimal water inputs.', NULL, NULL, NULL, E'1.reduction, 2.context, 3.differ, 4.low', NULL, NULL),
  ('bf269ecc-2fbd-50b3-bbd1-09ee920d3944'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'bf269ecc-2fbd-50b3-bbd1-09ee920d3944'::uuid, 1, NULL, TRUE, 0, NULL, E'Animal Domestication', E'Not all wild animals can become domestic animals. In fact, only fourteen species are fully domestic. According to one scientist, he says that six things must be true before it can happen. Without these six things, it''s impossible for an animal to become domestic. Firstly, the animal must eat inexpensive food that''s readily available, so humans can feed it easily. Secondly, the animal must grow fast, because slow growing animals are unhelpful to humans. It also needs to breed easily. If the animal doesn''t have babies, the species will soon disappear. The animals shouldn''t be frightened when placed in a small space, because this is dangerous to humans. Finally, it helps if the animal lives in a group in its natural environment. If the group has a social structure, the human can become its leader. If one animal in the group accepts the human as leader, the others will probably.\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', 'bf95aec0-4a97-5134-895c-b02d30760dcb'::uuid, NULL, NULL, E'follow', NULL, NULL),
  ('bf270720-c3c7-5a92-bbb8-f3299b3f155f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'bf270720-c3c7-5a92-bbb8-f3299b3f155f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '60f56a78-ab51-5cfa-96f8-6a69d7d21d81'::uuid, NULL, NULL, E'Our students have attended the summer camp hosted by the university.', NULL, NULL),
