  ('bf445913-2af7-5aad-b1f9-ee193ca99235'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bf445913-2af7-5aad-b1f9-ee193ca99235'::uuid, 1, NULL, TRUE, 0, NULL, E'Child Birth Rate', NULL, '65f79b87-ebed-54de-bae1-158ef287f8cc'::uuid, NULL, E'The western countries women are becoming more and more reluctant to give birth to babies.\nHowever, the male''s status in society remains as strong as it ever has in recent years. The birth rates increased during 20''s century but it starts to decrease over these last two decades. In the year 2000, as an example, the birth rate remained at around 1%. There are even some negative birth rates in other countries. Birth rates dropped to the lowest points that has never been seen in the society. It also has impacts on males in the society especially young males, and it might have some connection with unemployment rates as well.', NULL, NULL, NULL),
  ('bf474739-111a-5038-946d-d321723e84f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bf474739-111a-5038-946d-d321723e84f0'::uuid, 1, NULL, TRUE, 0, NULL, E'Online Shopping', E'A unique characteristic of online shopping environments is that they allow vendors to create retail interfaces with highly interactive features. One desirable form of interactivity from a consumer perspective is the implementation of sophisticated tools to assist shoppers in their purchase decisions by customizing the electronic shopping environment to their individual preferences.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('bf490681-9d36-5e7b-a806-39137a8b4175'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bf490681-9d36-5e7b-a806-39137a8b4175'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a small open area of grass in a forest?', '6a598ee5-2a21-53f3-b40b-7ab4066435b3'::uuid, NULL, NULL, E'Glade', NULL, NULL),
