  ('bf50718b-4198-504d-ba19-44e62aaa046e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'bf50718b-4198-504d-ba19-44e62aaa046e'::uuid, 1, NULL, TRUE, 0, NULL, E'Employment', E'The employment {{1}} for people in their 50s and 60s has increased significantly over the last two {{2}} . Due to advances in technology, some of their jobs offer greater {{3}} , such as working {{4}} from home or for themselves. However, it can still be difficult to get a job for those who do not have the relevant modern‐day skills.', NULL, NULL, NULL, E'1.rate, 2.decades, 3.flexibility, 4.remotely', NULL, NULL),
  ('bf605317-2d18-52a7-a660-042eab2bd9c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'bf605317-2d18-52a7-a660-042eab2bd9c0'::uuid, 1, NULL, TRUE, 0, NULL, E'Compass', E'Before Google Maps and even GPS, people used magnetic compasses for over 900 years in order to reliably {{1}} around the world. A compass works by using the earth’s magnetic field to {{2}} a magnetized needle. This allows us to {{3}} the four cardinal directions: north, south, east, and west.', NULL, NULL, NULL, E'1.navigate, 2.align, 3.determine', NULL, NULL),
