  ('bf85310c-f414-5786-a1d6-67330cf24564'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'bf85310c-f414-5786-a1d6-67330cf24564'::uuid, 1, NULL, TRUE, 0, NULL, E'New Light Bulb', E'Although it symbolizes a bright idea, the traditional incandescent light bulb is a dud. It wastes huge {{1}} of electricity, radiating 95% of the energy it {{2}} as heat rather than light. Its life is also relatively short, culminating in a dull pop as its filament fractures. Now a team of researchers has {{3}} a light bulb that is not only much more energy-efficient — it is also expected to {{4}} longer than the devices into which it is inserted. Moreover, the lamp could be used for rear-projection televisions as well as general illumination. The trick to a longer life, for light bulbs at least, is to {{5}} that the lamp has no electrodes. Although electrodes are undeniably convenient or plugging bulbs directly into the lighting system, they are also the main reason why lamps fail.', NULL, NULL, NULL, E'1.amounts, 2.consumes, 3.devised, 4.last, 5.ensure', NULL, NULL),
  ('bf9e0d90-2c7d-599a-b691-d86cd3307df4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'bf9e0d90-2c7d-599a-b691-d86cd3307df4'::uuid, 1, NULL, TRUE, 0, NULL, E'Cultural Heritage', E'What is your opinion on the importance of preserving cultural heritage in the age of globalization? Do you think it''s necessary or not?', NULL, NULL, NULL, NULL, 200, 300),
  ('bfa839cc-7a42-570a-8220-a2b31c936532'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bfa839cc-7a42-570a-8220-a2b31c936532'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7b6d7004-2d3d-59fd-8042-86781dc117be'::uuid, NULL, E'We recently explored various facets of London''s rich social history.', NULL, NULL, NULL),
  ('bfad46ad-e830-5655-9d16-8170bf5b59d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'bfad46ad-e830-5655-9d16-8170bf5b59d8'::uuid, 1, NULL, TRUE, 0, NULL, E'Closed-system Economy', E'In a closed-system economy, gross national product is {{1}} as a ‘cost of the system’. The Leontiev model relating the components of society''s {{2}} to resource use has been extended to make possible {{3}} estimates of ‘social entropy’. This kind of work suggests a {{4}} for minimizing social entropy and real cost in a more advanced economy and technology.', NULL, NULL, NULL, E'1.regarded, 2.demand, 3.quantitative, 4.rationale', NULL, NULL),
  ('bfad5790-b712-572b-8660-a0ff54a09a0a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'bfad5790-b712-572b-8660-a0ff54a09a0a'::uuid, 1, NULL, TRUE, 0, NULL, E'Egg Whites', E'Microplastics in recent years have taken front and center as a massive environmental problem {{1}} havoc on ecosystems in even the most remote areas of the planet. In fact, since plastic is not decomposable, environmental scientists have been scrambling to come up with ways to {{2}} the planet of microplastics and keep our waterways clean. And they have successfully used egg whites to create a lightweight and porous aerogel material that can be used in several ways, including water filtration, energy storage, and sound, as well as insulation. The structure has the ability to remove both salt and microplastics from seawater in remarkable ways, doing so with 98% and 99% efficiency, {{3}} . And the experiments were done with regular store-bought eggs, which means that future work can be done in a cost-effective way. The only issue with this is that there would be such a large demand for eggs that it could possibly outcompete the food industry. Once this is tackled, using these structures will work {{4}} as an effective, energy-efficient, and cost-effective method.', NULL, NULL, NULL, E'1.wreaking, 2.rid, 3.respectively, 4.smoothly', NULL, NULL),
  ('bfaf6c66-861b-5a14-a307-019627c013a5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bfaf6c66-861b-5a14-a307-019627c013a5'::uuid, 1, NULL, TRUE, 0, NULL, E'Earworms', E'Like the science of yawns, the reason for earworms is fascinating. They are a form of auditory imagery where we perceive tone in the brain in the absence of actually hearing it. “The auditory cortex is located in the temporal lobe of the brain,” says Samata Sharma, MD, director of addiction consult psychiatry at Brigham and Women’s Hospital in Boston, who has published research on this topic.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('bfb06303-0cd3-588c-a666-440a7b8f2beb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'bfb06303-0cd3-588c-a666-440a7b8f2beb'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3f2ff880-b592-5ce3-966c-986801a7be05'::uuid, NULL, NULL, E'Popular culture is now a serious subject of academic inquiry.', NULL, NULL),
  ('bfb931fa-da7a-52d0-846e-9ba5ed4efbe0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bfb931fa-da7a-52d0-846e-9ba5ed4efbe0'::uuid, 1, NULL, TRUE, 0, NULL, E'Motorcycle Crash', E'If you do experience a motorcycle crash, be aware the other driver will most likely blame you for the accident. This includes the road, road conditions, any skid marks, road signs, construction, and anything else that may have contributed to the accident. Not every accident requires an attorney but a knowledgeable local attorney can help you make sense of the process, as well as ensure that the other driver''s insurance doesn''t unfairly blame you for the accident.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('bfba921e-76ed-53e7-ac95-8172963c4e98'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'bfba921e-76ed-53e7-ac95-8172963c4e98'::uuid, 1, NULL, TRUE, 0, NULL, E'Part-time Jobs', E'What are the advantages and disadvantages for students doing part-time jobs?', NULL, NULL, NULL, NULL, 200, 300),
