  ('bfc7eb2e-f3bb-5dec-a8d6-a8469f8fc610'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bfc7eb2e-f3bb-5dec-a8d6-a8469f8fc610'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '29a11e8b-974a-5181-9c7c-44eac9615cc5'::uuid, NULL, E'Market research surveys can be conducted via phone, internet, or in person.', NULL, NULL, NULL),
  ('bfc861f9-5e54-5eda-91bf-062209af1f98'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'bfc861f9-5e54-5eda-91bf-062209af1f98'::uuid, 1, NULL, TRUE, 0, NULL, E'Australian Dwellings', E'The stock of Australia''s dwellings is {{1}} with current homes having more bedrooms on average than homes ten years ago. At the same time, households are getting smaller on average with decreasing {{2}} of couple families with children and {{3}} couple-only and lone-person households. This {{4}} examines the changes in household size and number of bedrooms from 1994_95 to 2003_04. It also looks at the types of households with spare bedrooms and the size of recently purchased new homes compared with existing stock.', NULL, NULL, NULL, E'1.evolving, 2.proportions, 3.increasing, 4.article', NULL, NULL),
  ('bfc8c1e8-36b4-5f31-ae33-9d8385dce8d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bfc8c1e8-36b4-5f31-ae33-9d8385dce8d8'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f3883d98-92d0-512e-afd2-4a907548c2e0'::uuid, NULL, E'Of all the heating and cooling options, central heating is the best.', NULL, NULL, NULL),
  ('bfca83d7-7fda-59fd-9102-2f87270f0a5e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'bfca83d7-7fda-59fd-9102-2f87270f0a5e'::uuid, 1, NULL, TRUE, 0, NULL, E'Aeroplanes or Cars', E'Which one has the greater impact on human’s life, aeroplanes or cars?', NULL, NULL, NULL, NULL, 200, 300),
  ('bfcce963-1bc8-5149-9aab-3798f0a2df15'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bfcce963-1bc8-5149-9aab-3798f0a2df15'::uuid, 1, NULL, TRUE, 0, NULL, E'Kidney Transplant', E'People seeking a kidney transplant often have to wait years for a donor organ to become available—and many die before ever receiving one. Xenotransplantation, in which organs from one species are transplanted into another, could alleviate the organ shortage. But bridging millions of years of evolutionary divergence between two species is a tall order, so for decades organ xenotransplantation was largely impractical.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('bfce4a95-625e-5cf0-b926-6620e2f16fb0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'bfce4a95-625e-5cf0-b926-6620e2f16fb0'::uuid, 1, NULL, TRUE, 0, NULL, E'Copyright', E'The presentation will cover copyright''s position as one of the intellectual property rights and how it {{1}} from other intellectual property rights. It will give an {{2}} of what copyright protects as well as what may be done with copyright protected works without permission under permitted acts. It is by manipulating the restricted acts through licensing arrangements that rights owners establish and {{3}} commercial markets. In contrast to commercial markets, the growth of open source and open content licensing models has challenged established business models. The presentation gives a brief commentary on two of the more {{4}} open licensing frameworks: the GNU Creative Commons licences.', NULL, NULL, NULL, E'1.differs, 2.overview, 3.exploit, 4.prominent', NULL, NULL),
  ('bfcf81d8-100f-5e38-87f3-57d2c85c7f71'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'bfcf81d8-100f-5e38-87f3-57d2c85c7f71'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for a shape with three sides and three angles?', '974e1a84-46d9-52fc-b7f1-df62b27e2438'::uuid, NULL, NULL, E'Triangle', NULL, NULL),
