  ('bff8ee4f-9993-5ad4-be5b-814838397def'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'bff8ee4f-9993-5ad4-be5b-814838397def'::uuid, 1, NULL, TRUE, 0, NULL, E'Healthy Eating', E'Many people realize that healthy eating habits can help support a healthy weight, manage or improve chronic diseases and maintain overall good health. But a diet that contains more processed, less nutritious foods can lead to weight gain and poor health. If you want to develop healthy eating habits, make small changes over a longer period. You''ll need to focus on eating consistent, well-balanced meals and eating a variety of foods. This will help ensure you''re consuming enough nutrients to support your body and daily activities. Developing healthy eating habits is a great way to improve your health and can be just a few small changes away.\n\nAccording to the passage, which statement below is NOT true?', NULL, NULL, NULL, E'To make sure that you get enough nutrients, you should focus on eating a few specific kinds of foods.', NULL, NULL),
  ('c006e624-91ca-58a6-94b3-3a7e74407dd7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c006e624-91ca-58a6-94b3-3a7e74407dd7'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '1c87b701-db6a-5550-b0fe-9bf368e758c8'::uuid, NULL, E'Many people disagree about this theory due to the lack of evidence.', NULL, NULL, NULL),
