  ('c0176287-3143-55c6-be70-72f20fadbd22'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c0176287-3143-55c6-be70-72f20fadbd22'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '301199d4-589d-573c-a6b7-27d144eaeb11'::uuid, NULL, E'Being a vegan means not consuming any animal products.', NULL, NULL, NULL),
  ('c01b6317-8954-5a3b-b15a-dad0d1985151'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c01b6317-8954-5a3b-b15a-dad0d1985151'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3bdc02a7-37c4-5eec-838d-bea8b4cb5ff1'::uuid, NULL, E'Many new university students often experience feelings of nervousness upon arrival.', NULL, NULL, NULL),
  ('c01d2414-fa21-5a7a-b3da-2658f031f5db'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c01d2414-fa21-5a7a-b3da-2658f031f5db'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c31c4725-b86f-5dc5-a0c9-66b16d35cb80'::uuid, NULL, NULL, E'Teachers must keep a record of students'' attendances.', NULL, NULL),
  ('c02555cf-16e7-5279-a186-39491f275f66'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c02555cf-16e7-5279-a186-39491f275f66'::uuid, 1, NULL, TRUE, 0, NULL, E'Meditation', E'Host: So where does meditation fit into mindfulness?\nInterviewee: So mindfulness is often spoken of as the heart of Buddhist meditation. So it''s a form of meditation that really is the cultivation of intimacy with awareness. We have to learn to enter the domain of awareness because so much of the time, we''re living in distraction. And that was true for thousands of years. So we didn''t have to wait for the iPhone to be distracted. But now we''re distracted to an infinitely higher degree than ever before. And just on average, people check their phones about 260 times a day - just to check, not to answer the phone but to just check the phone to see whether there''s anything interesting happening. So in all those 260 moments...\n\nWhy did the man mention phones in the end?', 'b76faaa3-b0ec-59c2-a693-a65ecef9455c'::uuid, NULL, NULL, E'To prove that people nowadays are distracted to an unprecedented higher degree.', NULL, NULL),
  ('c0262d2b-4f10-54be-80bf-04288d865ef9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c0262d2b-4f10-54be-80bf-04288d865ef9'::uuid, 1, NULL, TRUE, 0, NULL, E'Fall Colors', E'Relish the fall colors while you can. Scientists think that the rich reds, oranges and yellows of fall may be one of the many casualties of global warming. Leaves change color in part because of cues taken from dropping temperatures. As temperatures remain warmer through fall and winter nights, they could delay the beloved fall color shift.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('c0284ccb-8e16-57ef-b96d-31cb5b086d5e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c0284ccb-8e16-57ef-b96d-31cb5b086d5e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8cdd4ba8-d7b9-5b06-a7c9-9610cf6d18b8'::uuid, NULL, NULL, E'Their background gives them little chance of achieving at school.', NULL, NULL),
  ('c02d92d0-1a6e-594b-8e03-ab3b91e01e44'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c02d92d0-1a6e-594b-8e03-ab3b91e01e44'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'If a species is described as venomous, what substance does it have?', 'a050084e-4331-5f98-9012-3b725a18eac3'::uuid, NULL, NULL, E'Venom / poison', NULL, NULL),
  ('c0301e09-03d9-5d24-80c7-4a15960d823a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c0301e09-03d9-5d24-80c7-4a15960d823a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which one of the five senses is attributed to the nose?', '25a1198e-40f5-5206-a3a0-ba1eaed396ab'::uuid, NULL, NULL, E'Smell / olfactory sense', NULL, NULL),
  ('c030f979-ca8d-5305-901f-436e60262a8d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c030f979-ca8d-5305-901f-436e60262a8d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4b4291db-e0d2-5726-ad28-e6970cda39d0'::uuid, NULL, NULL, E'A good architectural structure should be useful, durable, and beautiful.', NULL, NULL),
  ('c0348626-6cf9-5c1c-b3d4-df6d0f365a52'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c0348626-6cf9-5c1c-b3d4-df6d0f365a52'::uuid, 1, NULL, TRUE, 0, NULL, E'Black Hole', NULL, '4adbb357-35b3-52b0-8144-8134944e9496'::uuid, NULL, E'This simulation shows what you might see. If you are orbiting a black hole. The light and position of background stars around the hole are distorted by its gravity and they seem to spin around. On the right the constellation Orion appears to approach the event horizon the boundary from which nothing can escape. Orion stars look like they become separated and get spun around. Once the hole has passed by Orion reappears on the left and looks normal again. Users can also experiment with different scenarios. This is what you might see if you were traveling towards a black hole with rocket engines slowing your descent. Another simulation mimics free fall into a hole. In the middle the light of the entire universe appears to be concentrated in a bright ring.', NULL, NULL, NULL),
  ('c037290f-8937-5475-8a21-e39a570e99c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c037290f-8937-5475-8a21-e39a570e99c5'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the longest river in the USA?', '0bd8dc3b-b900-50a9-9f4f-6cd1471be92e'::uuid, NULL, NULL, E'Mississippi', NULL, NULL),
  ('c03a7565-1c1f-5e17-856b-406b6ec1226f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'c03a7565-1c1f-5e17-856b-406b6ec1226f'::uuid, 1, NULL, TRUE, 0, NULL, E'A National Crisis', E'In 1868, botanist Jules-émile Planchon {{1}} the culprit behind a national crisis. For five years, a {{2}} had been stealing across France’s vineyards. Its cause was invisible, its spread {{3}} . Always it followed the same pattern. First a single vine would {{4}} ,then a circle of plants. Entire vineyards were wiped out within years.', NULL, NULL, NULL, E'1.unmasked, 2.blight, 3.inexorable, 4.wither', NULL, NULL),
  ('c04d172b-6ac2-53ae-aca8-0fb9ce2949f5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c04d172b-6ac2-53ae-aca8-0fb9ce2949f5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '19b3a36f-f5f0-5637-9950-b4f5e97d685d'::uuid, NULL, NULL, E'We meet once a month to discuss community problems.', NULL, NULL),
  ('c04d8a71-3912-58b5-a4e0-e23c5eefa369'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'c04d8a71-3912-58b5-a4e0-e23c5eefa369'::uuid, 1, NULL, TRUE, 0, NULL, E'Easy Food', E'Food has become easier to prepare in the modern society. This change also improves the way people live. Do you agree with that?', NULL, NULL, E'Food preparation has evolved significantly in modern society, with numerous technological advancements making it easier and more convenient to prepare meals. In my opinion, this change has greatly improved the way people live, as it has led to greater efficiency and accessibility in the kitchen.\nFirstly, the convenience factor is a major reason why I believe that food preparation has improved in modern society. With the advent of kitchen appliances such as microwaves, ovens, and blenders, preparing meals has become quicker and more efficient. This has made it easier for individuals to cook healthy meals at home, rather than relying on fast food or takeout options. Additionally, the availability of pre-packaged and pre-cooked foods has made meal preparation even more convenient, allowing individuals to save time and energy in the kitchen.\nMoreover, another factor that should be considered is the health benefits of modern food preparation. With greater access to fresh produce and ingredients, individuals are able to prepare healthier meals that meet their dietary needs. Additionally, the use of cooking techniques such as grilling, roasting, and baking can help retain the nutritional value of foods, while reducing the need for added fats or oils. As a result, individuals are able to maintain a healthier lifestyle, with greater control over their diets.\nIn conclusion, I believe that food preparation has greatly improved in modern society, leading to greater efficiency and accessibility in the kitchen. The convenience factor and health benefits of modern food preparation have made it easier for individuals to cook healthy meals at home, while also saving time and energy. To continue this trend, it is important for individuals to continue exploring new cooking techniques and ingredients, while also prioritizing healthy eating habits.', NULL, 200, 300),
  ('c052e060-75f9-57c4-a08f-9b0ac1ad3af5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c052e060-75f9-57c4-a08f-9b0ac1ad3af5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '543ee570-dfc1-596b-bf58-bd6459c9d677'::uuid, NULL, NULL, E'It''s really hard for countries to deal with too many people.', NULL, NULL),
  ('c055c9a2-d4f8-5814-a1f4-ebfa43a38c1d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'c055c9a2-d4f8-5814-a1f4-ebfa43a38c1d'::uuid, 1, NULL, TRUE, 0, NULL, E'FIB', E'When it comes to sheer celestial bling, stars might not corner the market on twinkle. Because beneath their rocky {{1}} , some terrestrial planets may be half diamond. So said {{2}} at the fall meeting of the American Geophysical Union.\nThe {{5}} were fixing to study how diamonds form here on Earth, under the conditions found in the planet''s lower mantle. So they took a tiny sample of iron, carbon, and oxygen, {{6}} abundant in Earth''s {{7}} , and cooked it up at about 3,800 degrees Fahrenheit and 9.5 million pounds of pressure per square inch. What they saw was that iron hooks up with oxygen to produce rust, and leaves behind pockets of carbon, which become diamond.\nNow, what happens if they look not at Earth but at a planet in a solar system where there''s even more carbon? According to the model, the carbon merges with iron to form a core made of steel, leaving a carbon mantle rich with diamond.\nWhether the Milky Way harbors such gems is still an open question. One thing is for sure: they probably wouldn''t harbor life. Because diamonds readily transfer heat. So a planet made of diamond would be one cold stone.', NULL, NULL, NULL, E'1.exteriors, 2.scientists, 3.researchers, 4.elements, 5.interior', NULL, NULL),
  ('c0575cb8-2363-51d6-8622-12cc6ee53453'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c0575cb8-2363-51d6-8622-12cc6ee53453'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2719d5a7-e199-5305-b0ca-ec7ee2c08ee8'::uuid, NULL, NULL, E'Plants can keep growing for as long as they live.', NULL, NULL),
  ('c05b5ed5-d3b6-5b5e-bf11-1474abdd6f75'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c05b5ed5-d3b6-5b5e-bf11-1474abdd6f75'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'bee7b846-4c82-5407-9210-bb3f8aaad0ba'::uuid, NULL, NULL, E'For staff training purposes, the library will be closed tomorrow.', NULL, NULL),
  ('c05c9b41-5698-5346-bebb-951ab0a776f1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c05c9b41-5698-5346-bebb-951ab0a776f1'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the piece of land that is a protected area for animals, plants and so on?', 'e4ff4ac1-1cea-53e3-bee1-3fa52d1626ba'::uuid, NULL, NULL, E'Conservation area / reserve / sanctuary', NULL, NULL),
  ('c05da110-e316-5e8d-bc79-447a40dcd952'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c05da110-e316-5e8d-bc79-447a40dcd952'::uuid, 1, NULL, TRUE, 0, NULL, E'The Voice', NULL, '8dd92e0c-77c8-56cb-aa32-10b4e6d7890e'::uuid, NULL, E'Today we''re going to practice evaluating the main tool used when addressing groups—the voice. There are three main elements that combine to create either a positive or negative experience for listeners. They can result in a voice that is pleasing to listen to and can be used effectively. Or they can create a voice that doesn''t hold attention, or even worse, causes an adverse reaction. The three elements are volume, pitch, and pace. When evaluating volume, keep in mind that a good speaker will adjust to the size of both the room and the audience. Of course, with an amplifying device like a microphone, the speaker can use a natural tone. But speakers should not be dependent on microphones; a good speaker can speak loudly without shouting. The second element, pitch, is related to the highness or lowness of the sounds. High pitches are, for most people, more difficult to listen to, so in general speakers should use the lower registers of their voice. During a presentation, it''s important to vary pitch to some extent in order to maintain interest. The third element, pace, that is how fast or slow words and sounds are articulated, should also be varied. A slower pace can be used to emphasize important points. Note that the time spent not speaking can be meaningful, too. Pauses ought to be used to signal transitions or create anticipation. Because a pause gives the listeners time to think about what was just said or even to predict what might come next, it can be very effective when moving from one topic to another. What I''d like you to do now is watch and listen to a videotape and use the forms I gave you to rate the speaking voices you hear. Then tonight I want you to go home and read a passage into a tape recorder and evaluate your own voice.', NULL, NULL, NULL),
  ('c06121fd-d3f5-5282-88ed-069c4b38d33d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c06121fd-d3f5-5282-88ed-069c4b38d33d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '00b91454-f973-544a-b2a6-5c48a7ad7ea0'::uuid, NULL, NULL, E'The new classrooms will be put into use next month.', NULL, NULL),
