  ('c078b8bd-a8b4-5cbd-a16b-244b55f7d52c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c078b8bd-a8b4-5cbd-a16b-244b55f7d52c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9f52bdce-5804-5c99-a5c3-c93efd2a9c77'::uuid, NULL, E'The campus library is a valuable resource for research and studying.', NULL, NULL, NULL),
  ('c07b6817-5615-51a9-ae4e-bf60cf49ef54'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'c07b6817-5615-51a9-ae4e-bf60cf49ef54'::uuid, 1, NULL, TRUE, 0, NULL, E'Omniscience', E'Omniscience may be a foible of men, but it is not so of books. Knowledge, as Johnson said, is of two {{1}} , you may know a thing yourself, and you may know where to find it. Now the amount which you may actually know yourself must, at its best, be limited, but what you may know of the {{2}} of information may, with proper training, become almost boundless. And here come the {{3}} and use of reference books-the working of one book in connection with another-and applying your own {{4}} to both. By this means we get as near to that omniscient volume which tells everything as ever we shall get, and although the single volume or work which tells everything does not exist, there is a vast number of reference books in existence, a knowledge and proper use of which is essential to every intelligent person. Necessary as I believe reference books to be, they can easily be made to be {{5}} to idleness, and too mechanical a use should not be made of them.', NULL, NULL, NULL, E'1.kinds, 2.sources, 3.value, 4.intelligence, 5.contributory', NULL, NULL),
  ('c07d413e-847c-5bc1-ac42-6543f8db26a7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c07d413e-847c-5bc1-ac42-6543f8db26a7'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the most important document you would have to show if you would to hire a car?', '5ebe5d0b-d651-5004-9a42-2d3b847dbaae'::uuid, NULL, NULL, E'Driver''s license / driving license', NULL, NULL),
  ('c083613a-b5dd-59c6-8fbd-db7f6c9922d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'c083613a-b5dd-59c6-8fbd-db7f6c9922d8'::uuid, 1, NULL, TRUE, 0, NULL, E'False Memories', E'Your brain activity changes depending on whether you''re {{1}} a true or a false memory, new research suggests. A "false" memory {{2}} to when you remember something that didn''t happen or that actually occurred at a different time or place. According to the new study, a specific {{3}} of electrical activity erupts in the hippocampus immediately before someone remembers a false memory — and it {{4}} from the electrical activity that occurs when people remember an event correctly.', NULL, NULL, NULL, E'1.recalling, 2.refers, 3.pattern, 4.differs', NULL, NULL),
  ('c083c14d-4ea6-5e6c-bffe-d2740e88eb58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c083c14d-4ea6-5e6c-bffe-d2740e88eb58'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the tropical fruit with yellow skin and sweet, tangy flesh, often eaten with a spoon?', '8388b732-9414-57fb-af06-5d55ba3c968d'::uuid, NULL, NULL, E'Papaya', NULL, NULL),
  ('c08456e5-dbee-5cc4-90fc-88791f8d9961'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'c08456e5-dbee-5cc4-90fc-88791f8d9961'::uuid, 1, NULL, TRUE, 0, NULL, E'Constitutional Interpretation', E'One of the Supreme Court''s most important {{1}} is to decide cases that raise questions of constitutional interpretation. The Court decides if a law or government {{2}} violates the Constitution. This is known as judicial review and enables the Court to invalidate both federal and state laws when they {{3}} with the Constitution. Since the Supreme Court stands as the ultimate authority in constitutional interpretation, its decisions can be {{4}} only by another Supreme Court decision or by a constitutional amendment.', NULL, NULL, NULL, E'1.responsibilities, 2.action, 3.conflict, 4.changed', NULL, NULL),
  ('c0876bb0-fab6-5ca5-9af1-bd91f952cc50'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c0876bb0-fab6-5ca5-9af1-bd91f952cc50'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f70e2e03-2089-5cbe-83cc-4c45415359d2'::uuid, NULL, NULL, E'A recent article shows a number of interesting experiments.', NULL, NULL),
