  ('c08fe907-6b12-5bb6-bc97-f453b7313cf0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c08fe907-6b12-5bb6-bc97-f453b7313cf0'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1163c356-f9ee-5e7c-b3e5-4a6202fd9405'::uuid, NULL, NULL, E'Students are permitted to park in campus parking spaces.', NULL, NULL),
  ('c090011d-40c9-5329-bd2c-b001db0f120e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c090011d-40c9-5329-bd2c-b001db0f120e'::uuid, 1, NULL, TRUE, 0, NULL, E'Email', E'Over the years, various internet services have been created to communicate remotely. Social networks have been a revolution, as have instant messaging apps. Since the beginning, there is also a timeless communication standard, representing one of the best tools for individuals and companies to communicate quickly: email.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('c093bf36-5e7a-5f89-ab8b-b1991535ec46'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c093bf36-5e7a-5f89-ab8b-b1991535ec46'::uuid, 1, NULL, TRUE, 0, NULL, E'Susceptibility', E'A susceptibility to gain weight may be written into molecular processes of human cells, a new study indicates. The proof-of-concept study with a set of 22 twins found an epigenetic signature in buccal or cheek cells appearing only for the twins who were obese compared to their thinner siblings.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('c0997f4f-19ec-50a6-a4da-424b2bab7d42'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c0997f4f-19ec-50a6-a4da-424b2bab7d42'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1154c5b2-d3df-5ce8-a8ed-2ada00f634c1'::uuid, NULL, NULL, E'Internet addiction is often blamed on frequent social media use.', NULL, NULL),
  ('c0a05909-619d-52b9-b009-4f2926f3cc41'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'c0a05909-619d-52b9-b009-4f2926f3cc41'::uuid, 1, NULL, TRUE, 0, NULL, E'School Shooting', E'The majority of school shootings are committed by white middle-class males living in suburban or rural areas. In attempting to explain this phenomenon, some researchers argued that African American parents recognized the need to prepare their children to face not only bullying but also humiliating racist comments and acts from the dominant culture. They frequently emphasized to their children that racist behaviours are wrong and that their children need not feel alone in their struggle. Research on the predominantly or exclusively white communities where the white male middle-class school shooters resided painted a very different picture. Parents and school staff in these areas indicated that they offered little or no opportunity either to stop the intense bullying or to help the victims process the emotions and identify strategies for responding. Because the boys were sometimes ashamed to report these violations of their masculinity, parents and school staff were often ignorant of, or ignored, the daily demoralizing, humiliating, and taunting environments embedded in the school and community cultures where the white school shooters lived. Thus, some future school shooters were left to determine on their own how to negotiate their feelings of intense rejection and discrimination relating to their social standing in their schools and among their peers: they were on their own in defending their sense of self in the context of their often extreme physical and verbal bullying and severe personal humiliation.', NULL, NULL, NULL, NULL, 5, 75),
  ('c0a30ccb-023b-57ef-8518-a569d3f5f2b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c0a30ccb-023b-57ef-8518-a569d3f5f2b2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3b0a099d-6f93-505b-9384-a0263a90e534'::uuid, NULL, NULL, E'Public perception about biotechnology is crucial for developing scientific consensus.', NULL, NULL),
  ('c0b4aab9-791b-5b74-9285-7bfa65dd45b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c0b4aab9-791b-5b74-9285-7bfa65dd45b8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the most important part of the human respiratory system?', 'e726306f-de9a-5eaf-9184-43019d3a6c3d'::uuid, NULL, NULL, E'Lung', NULL, NULL),
  ('c0b69473-2d2a-5858-ba9a-d77d87393e60'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c0b69473-2d2a-5858-ba9a-d77d87393e60'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'In which city was the first atomic bomb dropped in 1945?', '72e9506e-9648-59a8-8119-ea3f0ad04c73'::uuid, NULL, NULL, E'Hiroshima', NULL, NULL),
