  ('c14f9184-b148-528c-883b-d0551ac76de7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c14f9184-b148-528c-883b-d0551ac76de7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5b615a67-c212-5640-9e90-045406d2559c'::uuid, NULL, NULL, E'The policy is related to the conditions of admission to college.', NULL, NULL),
