  ('c153b294-7a25-55d6-9f91-b9e048f316e5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c153b294-7a25-55d6-9f91-b9e048f316e5'::uuid, 1, NULL, TRUE, 0, NULL, E'Black Swan (B)', E'Before the discovery of Australia, people in the old world were convinced that all swans were white, an unassailable belief as it seemed completely confirmed by empirical evidence. The sighting of the first black swan might have been an interesting surprise for a few scientists, but that is not where the significance of the story lies.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('c160bfe4-ecda-58c5-ac16-829c94b913b0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'c160bfe4-ecda-58c5-ac16-829c94b913b0'::uuid, 1, NULL, TRUE, 0, NULL, E'Pest Control', NULL, NULL, NULL, NULL, E'3, 1, 2, 4', NULL, NULL),
  ('c1652189-55e8-5b4d-b5a0-9bd8993828ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c1652189-55e8-5b4d-b5a0-9bd8993828ca'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9586e674-bea9-50f9-ba49-9631016cd5ae'::uuid, NULL, NULL, E'This course is based on experimentation and practice.', NULL, NULL),
  ('c16c2e0c-f688-5cc8-b9e6-e8189fb36369'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'c16c2e0c-f688-5cc8-b9e6-e8189fb36369'::uuid, 1, NULL, TRUE, 0, NULL, E'Modified Insects', E'People have been buzzing this week about a study from Johns Hopkins {{1}} on mosquitoes, {{2}} engineered to be resistant to malaria. The idea is to introduce the modified insects into an area affected by the disease and have them completely replace the native population. If the mosquitoes can''t get infected, the logic goes, then the people they bite won''t either.\nBut to make that scheme work, {{3}} mosquitoes need to {{4}} the locals. So {{5}} at Johns Hopkins tested their ability to do this, by allowing equal numbers of resistant and non-resistant mosquitoes to feed on the blood of malaria-infected mice. After nine generations, the transgenic mosquitoes made up 70 percent of the population, meaning they survived better and laid more eggs than the ordinary ones. Winning a {{6}} contest in the lab, though, doesn''t mean the same thing will happen out in the field. There are a lot of mosquitoes out there, and elbowing them out won''t be easy. The researchers say the strategy would have to be {{7}} with insecticides, drugs and perhaps a malaria vaccine to effectively wipe out this deadly disease.', NULL, NULL, NULL, E'1.University, 2.genetically, 3.transgenic, 4.outcompete, 5.scientists, 6.head-to-head, 7.combined', NULL, NULL),
  ('c16d8622-e2dd-5ec3-ac65-ec87b86b4965'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c16d8622-e2dd-5ec3-ac65-ec87b86b4965'::uuid, 1, NULL, TRUE, 0, NULL, E'Hainan', E'If the dream is to turn this palm-fringed corner of Hainan into a tourist trap comparable to Florida''s balmy space coast, there is still a lot to do. Several idle building sites suggest that some investors have gambled rashly. Signs have been taken down from a patch of scrub that was once earmarked for an amusement centre.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('c16da885-4d90-52e6-8414-6f6f9644fa02'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c16da885-4d90-52e6-8414-6f6f9644fa02'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '52b24407-e64f-5a29-b68f-3a55c0a54633'::uuid, NULL, NULL, E'The course allows students to progress at their own speed.', NULL, NULL),
  ('c1701b72-a067-5979-a6be-430e24dd6ff9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'c1701b72-a067-5979-a6be-430e24dd6ff9'::uuid, 1, NULL, TRUE, 0, NULL, E'Air Pollution', E'Air pollution is all around us. Microscopic pollutants in the air can {{1}} past our body’s defences, {{2}} deep into our respiratory and circulatory system, damaging our lungs, heart and brain. Air pollution is closely linked to climate change - the main driver of climate change is fossil fuel combustion which is also a major {{3}} to air pollution.', NULL, NULL, NULL, E'1.slip, 2.penetrating, 3.contributor', NULL, NULL),
  ('c17c0a20-ae90-51f7-b893-d3f3edc98562'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c17c0a20-ae90-51f7-b893-d3f3edc98562'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0e0fbe65-07f6-5b81-8a99-62f9b79cc370'::uuid, NULL, NULL, E'A formal ceremony has been scheduled to take place in May.', NULL, NULL),
  ('c17c8422-3b16-5de7-bc8c-0cefcf1051bf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c17c8422-3b16-5de7-bc8c-0cefcf1051bf'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '442d3fd5-ecc4-59b6-9fa2-920b5adad8a2'::uuid, NULL, NULL, E'There has been an increasing diversity in career opportunities.', NULL, NULL),
  ('c1850aa8-f642-59ac-ae84-05f09c4fa3b0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c1850aa8-f642-59ac-ae84-05f09c4fa3b0'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What utensils do we commonly use to eat food with?', 'c620d804-5b8f-55ce-909f-fd289ff233a0'::uuid, NULL, NULL, E'Fork / spoon / knife', NULL, NULL),
  ('c1860e6a-acf0-51b0-9618-53adb3cd8732'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c1860e6a-acf0-51b0-9618-53adb3cd8732'::uuid, 1, NULL, TRUE, 0, NULL, E'Thermodynamics', NULL, '2b8d7ce2-c683-5ac2-ac70-633e78f16c43'::uuid, NULL, E'Thermodynamics is simply defined as the branch of physics that deals with the conversion of different forms of energy, and the relations between heat and various energy forms such as mechanical, electrical or chemical energy. Kinetics deals with the actions of forces that cause various motions (also known as dynamics) and it is concerned with the rate of reactions. Temperature is the average kinetic energy within a given object. Thermal energy is defined as the total of all kinetic energies within a given system. It is important to remember that heat is caused by flow of thermal energy due to differences in temperature (heat flows from object at higher temperature to object at lower temperature), transferred through conduction/convection/radiation. Additionally thermal energy always flows from warmer areas to cooler areas. Energy occurs in many forms, including chemical energy, thermal energy, electromagnetic radiation, gravitational energy, electric energy, elastic energy, nuclear energy, and rest energy. These can be categorized in two main classes: potential energy and kinetic energy. Kinetic energy is the movement energy of an object. Kinetic energy can be transferred between objects and transformed into other kinds of energy. Kinetic energy may be best understood by examples that demonstrate how it is transformed to and from other forms of energy. For example, a cyclist uses chemical energy provided by food to accelerate a bicycle to a chosen speed. On a level surface, this speed can be maintained without further work, except to overcome air resistance and friction. The chemical energy has been converted into kinetic energy, the energy of motion, but the process is not completely efficient and produces heat within the cyclist.', NULL, NULL, NULL),
  ('c18ad758-5408-5d0d-924f-a85683fbc8ba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'c18ad758-5408-5d0d-924f-a85683fbc8ba'::uuid, 1, NULL, TRUE, 0, NULL, E'Fiber', E'Currently, Americans only eat about 16 grams of fiber — the parts of plants that can''t be digested — per day. That''s way less than the 25 to 30 grams that''s recommended. There are so many reasons why, from fast-food marketing to agriculture subsidies, but one contributing factor is the slow death of cooking, and the rise of the restaurant meal. Americans now spend more on food at restaurants than they do at grocery stores, but restaurant food tends to have even less fiber than the food we would otherwise eat at home. One problem seems to be that restaurant meals aren''t typically loaded with two of the best sources of fiber, unprocessed fruits and vegetables. A revealing study from 2007, in which researchers interviewed 41 restaurant executives, showed that restaurants think fruits and vegetables are too expensive to feature prominently on the menu, and 61 percent said profits drive menu selections. They also opposed labeling certain menu items as healthier choices, saying that would be "the kiss of death." So people like to eat out, and when they do, they prefer mushy, fiber-free comfort foods, but that''s a pretty dangerous road to go down.', NULL, NULL, E'Currently, Americans only eat about 16 grams of fiber per day, one contributing factor being the slow death of cooking and the rise of the restaurant meal, but restaurant food tends to have even less fiber than the food we would otherwise eat at home, as they think fruits and vegetables are too expensive to feature prominently on the menu and oppose labeling certain menu items as healthier choices.', NULL, 5, 75),
  ('c18cb8fe-63ad-59c2-938b-5c38409594fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'c18cb8fe-63ad-59c2-938b-5c38409594fe'::uuid, 1, NULL, TRUE, 0, NULL, E'Sweat Glands', NULL, NULL, NULL, NULL, E'2, 1, 3, 5, 4', NULL, NULL),
  ('c195cec8-7d90-5514-9c0b-20a51e671dd3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'c195cec8-7d90-5514-9c0b-20a51e671dd3'::uuid, 1, NULL, TRUE, 0, NULL, E'Chanan Tigay', E'Don''t expect a straightforward answer from Chanan Tigay about the {{1}} or even the existence of what was promoted as the earliest version of the fifth and final book of the Jewish Torah, known to Christians as the Book of Deuteronomy in the Old Testament.\nAs an author who spent years trying to {{2}} a juicy mystery and get it down on paper, Tigay wants you to read his book, "The Lost Book of Moses: The Hunt for the World''s Oldest Bible," to find the answer.\nBut at a talk on Wednesday, the writer, journalist, and fellow offered listeners an enticing peek, describing how he landed on the story of the mysterious manuscript and about his years trying to track {{3}} the document.\nFrom the author''s description, it was a wild, Indiana Jones-type ride that included a competition to find the relic, false starts, dead ends, trips to faraway places, and an ultimate breakthrough close to home.', NULL, NULL, NULL, E'1.authenticity, 2.unravel, 3.down', NULL, NULL),
