  ('c1aafe44-161e-538a-9862-66ef3507c81f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'c1aafe44-161e-538a-9862-66ef3507c81f'::uuid, 1, NULL, TRUE, 0, NULL, E'Data Observation', E'The main advantage of data observation is that it enables researchers to see what people are doing and do not have to {{1}} on what they say they are doing. Compared with second-hand and self-reported data, data observation can be more {{2}} to describe events and behaviors. Approaches to observation has diversity, and can be used by those whose {{3}} skill is weak. It is {{4}} for people to provide descriptive background information of related objects and phenomena environment.', NULL, NULL, NULL, E'1.rely, 2.objective, 3.verbal, 4.invaluable', NULL, NULL),
