  ('c26c0797-c2ba-5cb8-81e3-7abc295b9d65'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c26c0797-c2ba-5cb8-81e3-7abc295b9d65'::uuid, 1, NULL, TRUE, 0, NULL, E'Importance of Research', E'At our institution, we recognize the importance of research in the humanities and social sciences. We are committed to advancing knowledge in these fields through rigorous research and analysis. Our research agenda is driven by the pursuit of new insights that can benefit society both locally and globally. We offer a wide range of programs in the humanities and social sciences.', NULL, NULL, NULL, NULL, NULL, NULL),
