  ('c3e5bff7-e74d-5cad-978f-61b4fde6ea7c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'c3e5bff7-e74d-5cad-978f-61b4fde6ea7c'::uuid, 1, NULL, TRUE, 0, NULL, E'Mphil', E'This MPhil {{1}} students from a wide variety of academic, business and political {{2}} to the traditions, methods, and state-of-the-art research that shape an advanced analysis of human society. The MPhil is an eleven-month course designed for those who wish to go on to do doctoral research or {{3}} for those who {{4}} want to improve their understanding of methodology and analysis and attain an independent postgraduate degree in its own right.', NULL, NULL, NULL, E'1.introduces, 2.backgrounds, 3.equally, 4.simply', NULL, NULL),
  ('c3e92827-8a4d-5648-a67f-863998b39d2a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c3e92827-8a4d-5648-a67f-863998b39d2a'::uuid, 1, NULL, TRUE, 0, NULL, E'Tropical Cyclone', E'A tropical cyclone is a generic term used by meteorologists to describe a rotating, organized system of clouds and thunderstorms. The weakest tropical cyclones are called tropical depressions. If a depression intensifies such that its maximum sustained winds reach thirty-nine miles per hour, the tropical cyclone becomes a tropical storm.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('c3ef3422-4882-5da8-9f2f-af55cc59838b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'c3ef3422-4882-5da8-9f2f-af55cc59838b'::uuid, 1, NULL, TRUE, 0, NULL, E'Symbiosis', E'Symbiosis is a biological {{1}} in which two species live in {{2}} proximity to each other and interact regularly in such a way as to benefit one or both of the organisms. When {{3}} partners benefit, this {{4}} of symbiosis is known as mutualism.', NULL, NULL, NULL, E'1.relationship, 2.close, 3.both, 4.variety', NULL, NULL),
  ('c3f7a84a-9ba5-552b-b7c7-76bafdd674f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'c3f7a84a-9ba5-552b-b7c7-76bafdd674f9'::uuid, 1, NULL, TRUE, 0, NULL, E'Newspaper', E'Many UK newspapers have a strong online {{1}} but falling print circulations and changes to advertising trends have caused the press sector to experience {{3}} revenues. Latest {{4}} show that around two thirds of local authority areas don''t have a daily newspaper.', NULL, NULL, NULL, E'1.presence, 2.declining, 3.figures', NULL, NULL),
  ('c406f050-1ac6-56b9-8eba-1ac04372e281'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'c406f050-1ac6-56b9-8eba-1ac04372e281'::uuid, 1, NULL, TRUE, 0, NULL, E'Progressive Enhancement', E'Progressive enhancement is a design practice based on the idea that instead of {{1}} the least capable browser, or mangling our code to make a site look the same in every browser, we should provide a core set of functionality and information to all users, and then {{2}} the appearance and behavior of the site for users of more capable browsers. It''s very productive development practice. {{3}} hours working out how to add drop shadows to the borders of an element in every browser, we simply use the standards-based approach for browsers that support it and don''t even attempt to implement it in browsers that don''t. After all, the users of older and less capable browsers won''t know what they are missing. The {{4}} to progressive enhancement is the belief among developers and clients that websites should look the same in every browser. As a developer, you can simplify your life and dedicate your time to more interesting challenges if you let go of this outdated notion and embrace progressive enhancement.', NULL, NULL, NULL, E'1.designing for, 2.progressively enhance, 3.Instead of spending, 4.biggest challenge', NULL, NULL),
  ('c40eabd8-a5d3-5f94-a095-a462cd32b0e0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c40eabd8-a5d3-5f94-a095-a462cd32b0e0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6590014f-02e9-5164-ae3b-7aae06f8e56d'::uuid, NULL, E'The first person in space was from the Soviet Union.', NULL, NULL, NULL),
  ('c414f7f0-69ab-5a14-9ba3-3837ce29b66f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'c414f7f0-69ab-5a14-9ba3-3837ce29b66f'::uuid, 1, NULL, TRUE, 0, NULL, E'Dog', E'A DOG may be man''s best friend. But man is not always a dog''s. Over the centuries {{1}} breeding has pulled at the canine body shape to produce what is often a grotesque distortion of the underlying wolf. Indeed, some of these distortions are, when found in people, regarded as {{2}} . Dog breeding does, though, offer a chance to those who would like to understand how body shape is controlled. The ancestry of pedigree pooches is well recorded, their generation time is short and their {{3}} size reasonably large, so there is plenty of material to work with. {{4}} ,breeds are, by definition, inbred, and this simplifies genetic analysis. Those such as Elaine Ostrander, of America''s National Human Genome Research Institute, who wish to identify the genetic basis of the features of particular pedigrees thus have an {{5}} experimental animal.', NULL, NULL, NULL, E'1.selective, 2.pathologies, 3.litter, 4.Moreover, 5.ideal', NULL, NULL),
  ('c418b1af-a804-5164-bbba-c145a1c59178'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c418b1af-a804-5164-bbba-c145a1c59178'::uuid, 1, NULL, TRUE, 0, NULL, E'Thomas Edison', E'Thomas Edison used his access to the railroad to conduct chemical experiments in a small laboratory he set up in a train. During one of his experiments, a chemical fire started and the train caught fire. The conductor rushed in and struck Edison on the side of the head, probably furthering some of his hearing loss.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('c41b6212-69a1-597c-b35d-3bc7e827f37c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c41b6212-69a1-597c-b35d-3bc7e827f37c'::uuid, 1, NULL, TRUE, 0, NULL, E'Water Conservation', E'Water is a precious resource that we must conserve to ensure its availability for future generations. We can do this by fixing leaks, using low-flow toilets and showerheads, and avoiding wasteful practices like leaving the tap running while brushing our teeth. Conserving water also helps to protect aquatic habitats and wildlife that depend on healthy water sources.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('c42880ed-9343-5acf-bc5c-8e91bb64152f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c42880ed-9343-5acf-bc5c-8e91bb64152f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'daa468d0-f93d-56a2-9cfc-d3c6dafb8ece'::uuid, NULL, NULL, E'Good research delivers practical benefit to real people.', NULL, NULL),
