  ('c491bc48-d882-54f0-86b3-aacfa1496615'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c491bc48-d882-54f0-86b3-aacfa1496615'::uuid, 1, NULL, TRUE, 0, NULL, E'Rehabilitation', E'The primary application we''re targeting at first is to give people a decision aid during rehabilitation, following an acute knee injury, to help them understand when they can perform particular activities, and when they can move to different intensities of particular activities. A useful thing to take crack at.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('c4950cf0-018e-5dd9-9d87-b772989c612b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'c4950cf0-018e-5dd9-9d87-b772989c612b'::uuid, 1, NULL, TRUE, 0, NULL, E'Pop Mega-star', E'Pop mega-stars including Adele, Michael Jackson and Sir Elton John have all {{1}} music at the world-famous Metropolis Studios. Last year, the recording studios set about compiling an album called ''Lost Songs'', which {{2}} songs from relatively unknown musicians. First-year student Zak Taylor Fray decided to submit his song demo to be {{3}} in Volume Two of the Lost Songs album which was released this year, after he {{4}} how successful Volume One had been. Zak 24, said: ''I {{5}} this competition when simply searching the internet for songwriting competitions one day, and was lucky that there was still time to enter. It amazes me that people who have worked with huge pop stars thought my song was good and worth something.''', NULL, NULL, NULL, E'1.recorded, 2.features, 3.included, 4.saw, 5.found', NULL, NULL),
  ('c49c1292-6100-5a67-a346-f6a2de069cf1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c49c1292-6100-5a67-a346-f6a2de069cf1'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '37f0075f-c452-5b19-a084-912e86de39c4'::uuid, NULL, NULL, E'The company has refused her demand for a pay raise.', NULL, NULL),
  ('c49c4cba-f91a-58f8-8444-169b58ca6169'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c49c4cba-f91a-58f8-8444-169b58ca6169'::uuid, 1, NULL, TRUE, 0, NULL, E'Child Psychology', E'Within this free course, you will be introduced briefly to the discipline of child psychology and to theories and approaches that have been developed to help us understand and support children''s lives by focusing on the individual children. Psychologists can assess changes in their child''s abilities over time, including their physical, cognitive, social, and emotional development.', NULL, NULL, NULL, NULL, NULL, NULL),
