  ('c4c5f87a-48aa-5ba4-95ed-e29e4531b3fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c4c5f87a-48aa-5ba4-95ed-e29e4531b3fe'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1febd621-3c7f-5a68-a9fc-3a3b1e62acc4'::uuid, NULL, NULL, E'One of the election promises is to decrease the income tax.', NULL, NULL),
  ('c4c60d2d-2b9c-5bae-a414-d889218fa935'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c4c60d2d-2b9c-5bae-a414-d889218fa935'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'de46e155-1adc-5319-b976-162b80706f23'::uuid, NULL, E'Sydney is Australia''s largest city, chief port and cultural center.', NULL, NULL, NULL),
  ('c4cc5c13-a0a4-58a7-84ef-6c2ca9851b21'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c4cc5c13-a0a4-58a7-84ef-6c2ca9851b21'::uuid, 1, NULL, TRUE, 0, NULL, E'Why We Buy Diamonds', NULL, '826040c5-65b3-5564-8e8e-13a9c2868a04'::uuid, NULL, E'In 1947, Ayer copywriter Frances Gerety came up with the slogan ''A Diamond is Forever'' and the association with eternal love was solidified. It''s appeared in every De Beers advert since 1948. It''s been heralded as the ‘advertising slogan of the century''. It was so successful Gerety worked on every De Beers campaign until 1970. Shorty after it was immortalized in the Bond film of the same name. What the slogan did was create the concept that a diamond ring would be kept by the betrothed for eternity, creating a special sentiment but also meaning fewer would be re-sold, therefore increasing the chance for De Beers to sell more, freshly mined stones. Ayer''s copywriters were also skilled in directing consumer spending habits suggesting a month’s salary was a good amount to spend on a ring, then upping it to two by the 1980s. Before the second world war, 10% of engagement rings contained diamonds. By the 1980s the number was up to 80%. Over the same period diamond sales in the United States grew from $23 million to $2.1 billion. De Beers and N.W. Ayer & Son''s marketing masterpiece played on our emotions so powerfully that not only were they able to sell us a product we didn''t need but they influenced the culture of marriage.', NULL, NULL, NULL),
  ('c4d64fc5-5789-55c0-8c7d-e00d441b5894'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c4d64fc5-5789-55c0-8c7d-e00d441b5894'::uuid, 1, NULL, TRUE, 0, NULL, E'Nightmare', E'As terrible as whatever visions that are running through their head might be, waking someone from a nightmare is more likely to ensure that they’ll remember the bad dream. And if someone appears physically distressed in their sleep like this, it’s more likely that they’re having a night terror than a nightmare; night terrors are different neurological experiences.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('c4d7f584-6441-5efe-a079-e857e5810ab4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c4d7f584-6441-5efe-a079-e857e5810ab4'::uuid, 1, NULL, TRUE, 0, NULL, E'Personal Library', E'Building a personal library requires careful consideration and a discerning eye for selecting literary works that resonate with one''s intellectual curiosity. Beyond being a physical manifestation of one''s intellectual journey, personal libraries serve as a sanctuary for intellectual stimulation and contemplation. They offer a haven for deep reading, critical thinking, and the exploration of new ideas.', NULL, NULL, NULL, NULL, NULL, NULL),
