  ('c4db293e-1234-5c07-8d04-92fd7d75c856'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'c4db293e-1234-5c07-8d04-92fd7d75c856'::uuid, 1, NULL, TRUE, 0, NULL, E'Cuisine', E'Cuisine has been evolving {{1}} the dawn of time and continues to do so in the modern era. Ironically, while we {{2}} the history of traditional recipes and the cultural nuances in culinary practices, we often {{3}} up our noses at contemporary twists on classic dishes. This reflects a ''stuck in the mud'' attitude. Some food critics even argue that traditional cuisine is fading away, or, if not fading, being slowly {{4}} by a relentless tide of fusion and innovation.', NULL, NULL, NULL, E'1.since, 2.relish, 3.turn, 4.diluted', NULL, NULL),
  ('c4db574d-83ae-5bab-998c-0709a88ecd7b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c4db574d-83ae-5bab-998c-0709a88ecd7b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1e5d46d3-d057-5b44-9cd7-b0e0a54a448b'::uuid, NULL, NULL, E'The key witnesses to the event have conflicting recollections.', NULL, NULL),
  ('c4dfae9e-c842-5d72-a02a-f05d3efb6822'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c4dfae9e-c842-5d72-a02a-f05d3efb6822'::uuid, 1, NULL, TRUE, 0, NULL, E'Package', E'You are expecting an important package to be delivered while you are not at home for about an hour. Since the package requires a signature upon delivery, you decide to ask your neighbor for help. How would you politely request your neighbor to sign for the package and let them know that you will pick it up once you return?', '8507755c-ff54-5fe0-9960-13231d7b815b'::uuid, NULL, E'Hey neighbour, I want to talk to you about something.\nWe seem to have a little issue with my delivery package.\nIt''s like I will be out for an hour, my important package needs a signature, could you sign for it and I will come to get it after I return home.\nAnd I''d like to know what you think.', NULL, NULL, NULL),
