  ('c529070c-a742-5363-80e2-e2a0cccdf9ce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'c529070c-a742-5363-80e2-e2a0cccdf9ce'::uuid, 1, NULL, TRUE, 0, NULL, E'Zigzag Lightning', E'Why does lightning zigzag across the sky, instead of {{1}} in a straight line between a thundercloud and the ground? Many of the {{2}} of lightning remain a mystery, although researchers are starting to {{3}} the reason behind lightning''s crookedness. A study suggests that the {{4}} zigzag pattern of lightning is caused by a highly conducting form of oxygen that builds up irregularly as the bolt travels toward the ground.', NULL, NULL, NULL, E'1.discharging, 2.mechanisms, 3.untangle, 4.characteristic', NULL, NULL),
  ('c529c864-612e-584d-beb0-4f99bd7e2837'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c529c864-612e-584d-beb0-4f99bd7e2837'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b1362844-8c68-5da2-9a49-042a2dad50ca'::uuid, NULL, NULL, E'We currently offer free monthly lectures on different health topics.', NULL, NULL),
  ('c536fb27-f691-5a25-a4fa-efa0c47644cd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c536fb27-f691-5a25-a4fa-efa0c47644cd'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '67ed4381-59d7-5047-b294-de7be838cca1'::uuid, NULL, E'This short line in the artwork symbolizes the essence and vitality of life.', NULL, NULL, NULL),
  ('c53bea5b-927f-5212-9734-fba30ed08a34'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'c53bea5b-927f-5212-9734-fba30ed08a34'::uuid, 1, NULL, TRUE, 0, NULL, E'Stress', NULL, NULL, NULL, NULL, E'5, 1, 4, 2, 3', NULL, NULL),
  ('c53cb49d-d21d-5c67-97af-2ca9c81b4349'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c53cb49d-d21d-5c67-97af-2ca9c81b4349'::uuid, 1, NULL, TRUE, 0, NULL, E'How to Succeed', NULL, '9c310d39-1301-5f52-a71b-76e01907cd36'::uuid, NULL, E'People say you have to have a lot of passion for what you are doing and it''s totally true. The reason is because it''s so hard that if you don''t any rational person would give it up. It''s really hard and you have to do it over a sustained period of time, so if you don''t love it, if you don''t have fun doing it, you don''t really love it, you are going to give up. And that''s what happened to most people actually. If you really look at the ones that ended up "unsuccessful" in the eyes of the society and the eyes of others. Often times, it is the ones that are successful love what they did so they persevere when it got very tough. And ones that didn''t love it, quit, cause they are sane. Who''d want to put up with stuff if you don''t love it. So it''s a lot of hard work and it''s a lot of worrying, constantly. And if you don''t love it, you are going to fail. So you''ve got to love it, you''ve got to have passion. The second thing is you''ve got to be talent scout. It doesn''t matter how talent you are; you need a team of great people. You''ve got to figure out how to size people up fairly quickly, make decisions without knowing people too well and hire them and see how they do and refine your intuition. And be able to help build an organization that can eventually build itself. Because you need great people around you.', NULL, NULL, NULL),
  ('c54231fc-7be5-5917-8632-2e05a85fd29c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c54231fc-7be5-5917-8632-2e05a85fd29c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'cb1dd728-5587-5aae-9505-58bcc319bb3b'::uuid, NULL, NULL, E'Parents are financially responsible for their children right up until they reach adulthood.', NULL, NULL),
  ('c5482210-34dc-5795-9b4e-14f769dbfedc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c5482210-34dc-5795-9b4e-14f769dbfedc'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd912bfe8-cc20-5abc-b4b9-aa401d59d2e3'::uuid, NULL, NULL, E'You are required to submit your assignment by Friday.', NULL, NULL),
  ('c54c6631-3856-5309-ae62-15614f08d393'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c54c6631-3856-5309-ae62-15614f08d393'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5681c4ad-1bd5-55e9-81d7-efce2c79f209'::uuid, NULL, NULL, E'The essay is easy to complete once the research is finished.', NULL, NULL),
  ('c5579691-aabf-5d40-89e6-99cecb22b5e5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'c5579691-aabf-5d40-89e6-99cecb22b5e5'::uuid, 1, NULL, TRUE, 0, NULL, E'Effective Study', E'Effective study requires time, comfort and peace. It is impossible to combine a student''s learning with employment because one may distract the other. To what extent do you think the statements are realistic? Give your opinion with examples.', NULL, NULL, E'Effective studying is crucial for academic success, and it requires dedicated time, comfort, and peace. Some argue that combining learning with employment is impossible because one may distract the other. In this essay, I will present a positive standpoint, asserting that it is realistic to believe that studying and employment can be successfully combined.\nThe first reason why studying and employment can be effectively combined is the opportunity for practical application of knowledge. By working while studying, individuals have the chance to apply the theories and concepts they learn in real-life situations. This practical experience enhances their understanding and retention of the subject matter, making their learning more meaningful and applicable to future endeavors.\nAnother reason why combining learning with employment is realistic is the development of valuable skills. Balancing work and study requires effective time management, organization, and multitasking abilities. These skills are highly sought after in the professional world and can greatly enhance one''s employability. By successfully juggling both responsibilities, individuals can demonstrate their ability to handle multiple tasks and meet deadlines, making them valuable assets in the workforce.\nIn conclusion, the idea that studying and employment cannot be combined effectively is not realistic. By integrating work and study, individuals have the opportunity to apply their knowledge in practical settings and develop valuable skills. While it may require careful planning and dedication, the benefits of combining learning with employment are substantial. Therefore, it is possible to strike a balance between the two and achieve success in both academic pursuits and professional endeavors.', NULL, 200, 300),
  ('c55c691b-832f-5c2e-85da-2cfd3d078c8f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c55c691b-832f-5c2e-85da-2cfd3d078c8f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f708b30b-79c2-5856-ba5b-5949f8421848'::uuid, NULL, E'The research paper should begin with a thorough review of the literature.', NULL, NULL, NULL),
  ('c5613370-985f-56d1-a883-1c5898dbd129'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c5613370-985f-56d1-a883-1c5898dbd129'::uuid, 1, NULL, TRUE, 0, NULL, E'New Form of Carbon', E'A newly created form of carbon in a mesh just one atom thick is tantalizing scientists with hints that it could sharply improve rechargeable batteries and allow wires so small that they can operate at a scale where metals fail. The material is highly conductive and may prove able to store more electrical energy than even graphene, the astonishing atomic-thickness carbon honeycomb material identified nearly 20 years ago.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('c563b5a8-7547-5729-af49-69ae16e358e2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c563b5a8-7547-5729-af49-69ae16e358e2'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9f3b4de4-6684-5b88-871d-c286f17f9d8c'::uuid, NULL, E'To avoid evening traffic, we should leave before it gets busy.', NULL, NULL, NULL),
  ('c5645aee-6deb-55e2-84c7-9e26a07b4815'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'c5645aee-6deb-55e2-84c7-9e26a07b4815'::uuid, 1, NULL, TRUE, 0, NULL, E'Food Demand', E'The demand for food is increasing worldwide. What are the causes? What measures could the international community take to improve the situation?', NULL, NULL, NULL, NULL, 200, 300),
  ('c56f0c00-1ed6-5667-ba68-c0edbc64d388'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c56f0c00-1ed6-5667-ba68-c0edbc64d388'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0bc80e6e-142d-5fd3-80b5-9c4ec7e4ca95'::uuid, NULL, E'Organic food is grown without applying chemicals and the process is without artificial additives.', NULL, NULL, NULL),
  ('c5735982-0671-5731-b2c9-486021b8ef4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'c5735982-0671-5731-b2c9-486021b8ef4b'::uuid, 1, NULL, TRUE, 0, NULL, E'Dag Hammarskjold Library', E'The Dag Hammarskjold Library at United Nations Headquarters in New York is a library designated to facilitate the work of the United Nations and {{1}} mainly on the needs of the UN Secretariat and diplomatic missions. Anyone with a valid United Nations Headquarters grounds {{2}} , including specialized agencies, accredited media and NGO staff, is able to visit the library. Due to {{3}} constraints in place at the United Nations Headquarters complex, the library is not open to the general {{4}} .', NULL, NULL, NULL, E'1.focuses, 2.pass, 3.security, 4.public', NULL, NULL),
  ('c575622b-a650-5f23-ba10-a0a2d8820701'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c575622b-a650-5f23-ba10-a0a2d8820701'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5ae0969d-80d4-54c3-bb53-1be196328cc4'::uuid, NULL, E'The teacher asked the students to check their work for any errors.', NULL, NULL, NULL),
  ('c57c54da-82f0-51ed-a5a0-9646dfecbad0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c57c54da-82f0-51ed-a5a0-9646dfecbad0'::uuid, 1, NULL, TRUE, 0, NULL, E'Blinking', E'Every few seconds, our eyelids automatically shutter and our eyeballs roll back in their sockets. So why doesn''t blinking plunge us into intermittent darkness and light? New research shows that the brain works extra hard to stabilize our vision despite our fluttering eyes. When our eyeballs roll back in their sockets during a blink, they don''t always return to the same spot when we reopen our eyes.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('c57e447d-496b-5568-aa66-79d201e432f1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c57e447d-496b-5568-aa66-79d201e432f1'::uuid, 1, NULL, TRUE, 0, NULL, E'Leadership', NULL, '8ba7b616-809d-53ed-8bc9-5f3a1904ca51'::uuid, NULL, E'A leader can define or clarify goals by issuing a memo or an executive order, an edict or a fatwa or a tweet, by passing a law, barking a command, or presenting an interesting idea in a meeting of colleagues. Leaders can mobilize people''s energies in ways that range from subtle, quiet persuasion to the coercive threat or the use of deadly force. Sometimes a charismatic leader such as Martin Luther King Jr. can define goals and mobilize energies through rhetoric and the power of example. We can think of leadership as a spectrum, in terms of both visibility and the power the leader wields. On one end of the spectrum, we have the most visible: authoritative leaders like the president of the United States or the prime minister of the United Kingdom, or a dictator such as Hitler or Qaddafi. At the opposite end of the spectrum is casual, low-key leadership found in countless situations every day around the world, leadership that can make a significant difference to the individuals whose lives are touched by it. Over the centuries, the first kind, the out-in-front, authoritative leadership, has generally been exhibited by men. Some men in positions of great authority, including Nelson Mandela, have chosen a strategy of ''leading from behind''; more often, however, top leaders have been quite visible in their exercise of power. Women (as well as some men) have provided casual, low-key leadership behind the scenes. But this pattern has been changing, as more women have taken up opportunities for visible, authoritative leadership.', NULL, NULL, NULL),
  ('c58a6228-6e90-59f9-92ef-ee9c46ca73a7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'c58a6228-6e90-59f9-92ef-ee9c46ca73a7'::uuid, 1, NULL, TRUE, 0, NULL, E'Career Choice', E'Career counselors often suggest introspection as the starting {{1}} in finding the right career —understanding one''s passions and skills can illuminate the way {{2}} . Many seeking a career change feel a {{3}} of restlessness with their current path, but may not have a clear vision of their future. In such {{4}} , it''s essential to evaluate personal values and strengths, which can guide the selection of a fulfilling new career.', NULL, NULL, NULL, E'1.point, 2.forward, 3.sense, 4.cases', NULL, NULL),
  ('c58fc88a-1ae6-5bf8-9053-18cd3224161d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c58fc88a-1ae6-5bf8-9053-18cd3224161d'::uuid, 1, NULL, TRUE, 0, NULL, E'Large Hadron Collider (LHC)', NULL, '935f72b9-5235-5fac-a1f2-3fcceebab103'::uuid, NULL, E'Protons are finally transferred to the LHC (both in a clockwise and an anticlockwise direction) where they are accelerated for 20 minutes to 6.5 TeV. Beams circulate for many hours inside the LHC beam pipes under normal operating conditions.\nFor each collision, the physicist''s goal is to count, track and characterize all the different particles.\nThe charge of the particle, for instance, is obvious since particles with positive electric charge bend one way and those with negative charge bend the opposite way. Also the momentum of the particle can be determined.\nLarge Hadron Collider (LHC) is the world''s largest particle accelerator lies in a tunnel. The LHC is a ring roughly 28km around that accelerates protons almost to the speed of light before colliding them head-on. Protons are particles found in the atomic nucleus, roughly one thousand-million-millionth of a meter in size. The LHC starts with a bottle of hydrogen gas, which is sent through an electric field to strip away the electrons, leaving just the protons Electric and magnetic fields are the key to a particle accelerator.', NULL, NULL, NULL),
  ('c59026aa-5c02-5050-82da-100bc6ee6415'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'c59026aa-5c02-5050-82da-100bc6ee6415'::uuid, 1, NULL, TRUE, 0, NULL, E'Counseling', E'Counseling is an {{1}} service that colleges and universities invariably provide. Services can range from life-saving care to {{2}} with minor concerns. Life {{3}} , such as deaths and divorces in the family, issues with friends, substance abuse, and suicide are just a few of the many issues that college students may experience or {{4}} others struggling with.', NULL, NULL, NULL, E'1.essential, 2.assistance, 3.stressors, 4.witness', NULL, NULL),
  ('c594af7c-b3ac-5c7f-8a71-a910f44f3251'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'c594af7c-b3ac-5c7f-8a71-a910f44f3251'::uuid, 1, NULL, TRUE, 0, NULL, E'Monitoring Animals', E'Monitoring animals is hard work. Field biologists have to follow {{1}} made by the animals and {{2}} out for fruit that they might like in order to find the animals, whether it be walking through rivers, up and down slippery hillsides with {{3}} vegetation or through thick mud and swamps.', NULL, NULL, NULL, E'1.tracks, 2.look, 3.dense', NULL, NULL),
  ('c595fb21-56a8-5b7a-a1c7-0f49d69b5f56'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c595fb21-56a8-5b7a-a1c7-0f49d69b5f56'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9c9d95e8-bbd2-5b86-ba29-0036f5d64112'::uuid, NULL, NULL, E'Clinical placements in nursing prepare students for professional practice.', NULL, NULL),
  ('c598eb7e-7d1e-53fa-b13a-ee05055f6408'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c598eb7e-7d1e-53fa-b13a-ee05055f6408'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9d1b6ffd-bedf-556f-bbb4-370ed42d85f7'::uuid, NULL, E'At night, sailors in the Mediterranean can see the glow from the fiery molten material that is thrown into the air.', NULL, NULL, NULL),
  ('c598f0c3-4a45-5b76-b7ef-2d2e9e3e1dde'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c598f0c3-4a45-5b76-b7ef-2d2e9e3e1dde'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the job title of someone who designs buildings?', 'b90f8f90-781d-53a2-9c4f-fe77f2863bfb'::uuid, NULL, NULL, E'Architect', NULL, NULL),
  ('c5a00841-d0cb-5f90-9c51-52fa60728e76'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c5a00841-d0cb-5f90-9c51-52fa60728e76'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a character in movies who holds superior power to humans?', '4d4ac89b-2665-5037-bfe7-f55463133f84'::uuid, NULL, NULL, E'Superman', NULL, NULL),
  ('c5a0d08e-7a57-53dc-a357-8a0a5aa2694b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c5a0d08e-7a57-53dc-a357-8a0a5aa2694b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '57e810fe-65f8-5972-8783-a9148f4a9f72'::uuid, NULL, NULL, E'Please write down the name of the author and the year of publication.', NULL, NULL),
  ('c5a111f5-4b11-5cbb-a9b5-ce2d196e98a9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c5a111f5-4b11-5cbb-a9b5-ce2d196e98a9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1cdc50aa-bc07-5cd7-b113-8410c695b500'::uuid, NULL, NULL, E'The teaching staff are actively engaged in the original research.', NULL, NULL),
  ('c5a1caa8-f39d-54bd-be10-2cfaec0409b6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c5a1caa8-f39d-54bd-be10-2cfaec0409b6'::uuid, 1, NULL, TRUE, 0, NULL, E'Fiction', E'If reading fiction is an exercise in empathy, as it lets you climb inside someone else''s head and see the world through their eyes, then reading science fiction and fantasy ups the ante. You still see through someone else''s eyes, but the world you''re seeing can be almost anything - a distant planet, an alternate timeline, a land of magic and mystery, even maybe our own familiar world just tweaked a bit. Whether you''re a longtime science fiction and fantasy reader or just getting your feet wet, or maybe you''ve stepped away from these genres for a while, only to become intrigued by how much they seem to be changing in recent years, we''ve got you covered with some basic background, some things to look for and some solid recommendations from experts.\n\nThe passage is an introduction of a radio show. Then, what could the show be about?', 'ceaa854d-d711-5703-a478-4be5ece66a46'::uuid, NULL, NULL, E'different types of information on science fiction.', NULL, NULL),
  ('c5a4ac34-1af3-5ce6-9d72-d6491c7f6020'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c5a4ac34-1af3-5ce6-9d72-d6491c7f6020'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the clothes that need washing?', 'b08e4348-f2c6-5215-962a-c7cd0fb2b0fa'::uuid, NULL, NULL, E'Laundry', NULL, NULL),
  ('c5acf39b-175e-5085-818b-994fbfe62b76'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c5acf39b-175e-5085-818b-994fbfe62b76'::uuid, 1, NULL, TRUE, 0, NULL, E'Yellowstone National Park', NULL, 'cace5cea-d791-57e8-897e-e3b475ea3957'::uuid, NULL, E'Welcome to Yellowstone National Park. Before we begin our nature walk today, I''d like to give you a short history of our National Park Service. The National Park Service began in the late 1800''s. A small group of explorers had just completed a month-long exploration of the region that is now Yellowstone. They gathered around a campfire, and after hours of discussion, they decided that they should not claim this land for themselves. They felt it should be accessible to everyone. So they began a campaign to preserve this land for everyone''s enjoyment. Two years later, in the late nineteenth century, an act of Congress signed by President Ulysses S. Grant proclaimed the Yellowstone region a public park. It was the first national park in the world. After Yellowstone became a public park, many other areas of great scenic importance were set aside, and in 1916 the National Park Service was established to manage these parks. As a park ranger, I am an employee of the National Park Service. In a national park, park rangers are on duty at all times to answer questions and help visitors in any difficulty. Nature walks, guided tours, and campfire talks are offered by specially training staff members. The park service also protects the animals and plants within the parks.', NULL, NULL, NULL),
  ('c5bac779-5a38-5edc-9068-b632150dc12a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c5bac779-5a38-5edc-9068-b632150dc12a'::uuid, 1, NULL, TRUE, 0, NULL, E'Difficult Conversations', E'Surprisingly, despite what appear to be infinite variations, all difficult conversations share a common structure. When you’re caught up in the details and anxiety of a particularly difficult conversation, this structure is hard to see. But understanding that structure is essential to improve how you handle your most challenging conversations.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('c5bae464-73c4-55e0-ac3f-673deecc9fa4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c5bae464-73c4-55e0-ac3f-673deecc9fa4'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'When we are talking about spring, summer, autumn and winter, what are they the examples of?', 'afa3ffef-f9b5-520d-b45d-2e7e57d96c9a'::uuid, NULL, NULL, E'Seasons', NULL, NULL),
  ('c5c612ec-f40f-5561-89c5-94d7b17e9089'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c5c612ec-f40f-5561-89c5-94d7b17e9089'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '115cb2f1-1b3a-5407-9dac-dc82d20a3fee'::uuid, NULL, NULL, E'The main concepts of these events were not yet fully understood.', NULL, NULL),
  ('c5c993b1-e6c5-5585-bf26-5abe0ce2e8aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'c5c993b1-e6c5-5585-bf26-5abe0ce2e8aa'::uuid, 1, NULL, TRUE, 0, NULL, E'Observatory', E'Astronomers have used data from two NASA telescopes, the Chandra X-ray Observatory and the James Webb Space Telescope, to {{1}} new details about a bizarre structure in the debris field of an exploded star. The structure, {{2}} the “Green Monster” because of its resemblance to the wall in the left field of Fenway Park, was first identified in Webb’s infrared data from April 2022. The origin of this feature was not clear, until the researchers combined the Webb data with X-rays from Chandra. The team {{3}} that the Green Monster is part of the blast wave from the supernova explosion, and is plowing into the gas that was ejected by the star before it exploded. The material in the Green Monster is moving {{4}} us, and has a much higher density than the average density of the surrounding gas. This result can help reconstruct the complicated history of mass loss by the star before it exploded.', NULL, NULL, NULL, E'1.uncover, 2.dubbed, 3.concluded, 4.towards', NULL, NULL),
  ('c5ca3cd0-8b80-50e9-a68c-a871059a86a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c5ca3cd0-8b80-50e9-a68c-a871059a86a8'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3cdf61c1-5e04-5d64-ad37-5150a831b479'::uuid, NULL, NULL, E'These young students are grouped by the teachers according to their ages.', NULL, NULL),
  ('c5caf31f-7ede-527b-800c-a8c2a5d6d77f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c5caf31f-7ede-527b-800c-a8c2a5d6d77f'::uuid, 1, NULL, TRUE, 0, NULL, E'Population Growth', E'How quickly is the world''s population growing? In the United States and other developed countries, the current growth rate is very low. In most developing countries, the human population is growing at a rate of nearly 3 people per second. Because of this bustling growth rate, the human population is well on its way to reaching 9 billion within lifetime.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('c5ce33d8-eabf-5882-9052-a2c23268f18f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c5ce33d8-eabf-5882-9052-a2c23268f18f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6fbf11e4-e878-54f5-91e7-9780ab7e0696'::uuid, NULL, NULL, E'Maintaining good health is essential for a productive college experience.', NULL, NULL),
  ('c5ce8374-a62a-5feb-b3c5-5e579f24c592'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c5ce8374-a62a-5feb-b3c5-5e579f24c592'::uuid, 1, NULL, TRUE, 0, NULL, E'Climate Change', E'Climate change is not a distant threat but a present reality that is already affecting communities around the world through rising temperatures and extreme weather events. Climate change is caused by human activities such as burning fossil fuels, deforestation, and agriculture. Its impacts include more frequent heatwaves, droughts, floods, and storms that can damage infrastructure, harm ecosystems, and cause loss of life.', NULL, NULL, NULL, NULL, NULL, NULL),
