  ('c61cecdb-3197-5b21-8f0b-a5393f06ca8c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c61cecdb-3197-5b21-8f0b-a5393f06ca8c'::uuid, 1, NULL, TRUE, 0, NULL, E'The Office of the Future', E'To bridge gaps between teams, one tactic is to set aside more of the office to showcase the work of each department, so that people who never encounter each other on Zoom can see examples of what their colleagues do. Another option is to ply everyone with drink. Expect more space to be set aside for socialising and events.', NULL, NULL, NULL, NULL, NULL, NULL),
