  ('c63a067d-fd8d-58d1-91cd-640050a47ab5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c63a067d-fd8d-58d1-91cd-640050a47ab5'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Would a family, a corporation or a sports team probably include the most people?', 'ea0bb05f-1170-5309-8fe1-61484eb8c667'::uuid, NULL, NULL, E'Corporation', NULL, NULL),
  ('c63e172d-2656-5b47-86c0-3acf5aae763d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'c63e172d-2656-5b47-86c0-3acf5aae763d'::uuid, 1, NULL, TRUE, 0, NULL, E'Science v.s. Arts', E'With the development of technology and science, some people believe that there is no great value of artists such as musicians and painters. What are the things artists can do but the scientist cannot? Why should we encourage studying in art area?', NULL, NULL, NULL, NULL, 200, 300),
  ('c641d2ee-d3fe-5ac4-925b-f4081879d13c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c641d2ee-d3fe-5ac4-925b-f4081879d13c'::uuid, 1, NULL, TRUE, 0, NULL, E'Paraphrasing', E'Paraphrasing involves restating information or ideas in one''s own words while maintaining the original meaning. Paraphrasing helps to avoid plagiarism and demonstrates a deeper understanding of the source material. To paraphrase effectively, one must carefully analyze the original text, identify the main ideas, and rephrase them using different words and sentence structures.', NULL, NULL, NULL, NULL, NULL, NULL),
