  ('c6741154-386d-5a05-9a28-de39639b7587'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c6741154-386d-5a05-9a28-de39639b7587'::uuid, 1, NULL, TRUE, 0, NULL, E'Statistical Chance', E'The survey found that the statistical chances of someone from a poor background being accepted at one of the country''s most respected universities are far lower than those of a student from a wealthy family. This means that the inequalities in society are likely to be passed down from one generation to the next.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('c67ea34b-b7f2-5746-b380-c92402f88e9a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'c67ea34b-b7f2-5746-b380-c92402f88e9a'::uuid, 1, NULL, TRUE, 0, NULL, E'Farming', E'Farming is {{1}} the planet, but there could be a much more environmentally friendly way to feed ourselves: using renewable energy to {{2}} carbon dioxide into food. This is becoming a {{3}} : a company is building the first commercial-scale factory, near Helsinki in Finland, that will be able to make food directly from CO2. It will {{4}} 100 tonnes per year, enough for 4 or 5 million meals.', NULL, NULL, NULL, E'1.devastating, 2.turn, 3.reality, 4.produce', NULL, NULL),
