  ('c6bdf038-6c4e-5e95-9b77-15dde48dcc26'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c6bdf038-6c4e-5e95-9b77-15dde48dcc26'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '62d44aab-1b9b-5f6f-8da2-b0a263ee2eec'::uuid, NULL, NULL, E'The research yielded some results that were not anticipated initially.', NULL, NULL),
  ('c6c06426-4b03-5e3c-8880-0c004221b11c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'c6c06426-4b03-5e3c-8880-0c004221b11c'::uuid, 1, NULL, TRUE, 0, NULL, E'Telecommunication Evolution', E'Telecommunication has evolved dramatically since the {{1}} of the telegraph. What began as a {{2}} of sending Morse code signals across wires has burgeoned into a complex network of satellites, fiber-optic cables, and wireless technologies. This evolution has turned the world into a global village, with information {{3}} possible in mere seconds.', NULL, NULL, NULL, E'1.invention, 2.means, 3.exchange', NULL, NULL),
  ('c6c51fc1-ced1-54b5-bd37-935124f02fff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c6c51fc1-ced1-54b5-bd37-935124f02fff'::uuid, 1, NULL, TRUE, 0, NULL, E'Sampling', E'In statistics, a predetermined number of observations can be extracted from a larger population. This is called sampling. There are many sampling techniques adopted by researchers and statisticians and the type of sampling depends upon the analysis to be performed. When it seems time consuming to obtain data from every member of the population, then sampling techniques are employed.', NULL, NULL, NULL, NULL, NULL, NULL),
