  ('c6dded05-c56e-5117-af32-ee28bc93a13d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c6dded05-c56e-5117-af32-ee28bc93a13d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7d3a9796-117e-5379-bd89-e983802eb0ee'::uuid, NULL, NULL, E'Organizational failure is considered from various perspectives in academic literature.', NULL, NULL),
  ('c6de8596-718f-5a1b-98b1-6d94b090958d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c6de8596-718f-5a1b-98b1-6d94b090958d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9966b0a5-4b4a-5f3c-9f35-9f0abe8f704d'::uuid, NULL, NULL, E'Children conquer their first language without any efforts.', NULL, NULL),
  ('c6e2eb77-0aee-5ad9-adbd-a684491b390b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c6e2eb77-0aee-5ad9-adbd-a684491b390b'::uuid, 1, NULL, TRUE, 0, NULL, E'Einstein''s Insight', NULL, 'cefd4f75-c672-5f6a-ab31-3f4cf89600a7'::uuid, NULL, E'One of the most surprising insights from Einstein is that time is not what we intuitively think it is, right? Most of us have this sense that time for you is the same as time for me. And sometimes there is a cosmic clock that out there taking second after second after second, dragging it''s all in exactly the same way into the future. Einstein found that if you and I are moving relative to each other, however, our clocks don''t take off the time at the same rate. Our watches if they were once in sync if we''re moving relatively to each other, they fall out synchronization. And what is that mean? All that means that what I consider to be happening right now at a given moment, from your perspective, that might be the past or might be the future? What you consider to be happening right now to me that may be the past or the future. Now since your view of reality is every bit as valid as my view of reality. That means you cannot really say the past is gone because that might be your now, your reality. You cannot really say that the future is yet to be, maybe the future to me might be your now, your reality at that given moment, so in a sense past, present and future are all equally really, all exist, all out there.', NULL, NULL, NULL),
  ('c6e38286-7861-58b1-8741-da23b553ff98'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'c6e38286-7861-58b1-8741-da23b553ff98'::uuid, 1, NULL, TRUE, 0, NULL, E'Personal Life', E'Many people find that work leaves little time for people''s personal life. How widespread do you think it is? How can we solve the problems caused by the shortage of time?', NULL, NULL, E'The perception that work severely encroaches on personal time is widespread, a reality validated by global stress surveys and cultural shifts towards "hustle" culture. However, this prevalent problem is not insurmountable. By implementing clear workplace policies and re-evaluating personal priorities, society can reclaim time for life beyond the office.\nFirstly, the issue is extensive, affecting diverse professions and economies. The constant connectivity enabled by smartphones means many employees are mentally tethered to work long after leaving, blurring the line between professional and private hours. This "always-on" expectation creates a widespread sense of time poverty, where leisure and family time feel like rare luxuries rather than guaranteed necessities.\nThe solution lies in decisive structural and personal changes. Employers must lead by establishing enforceable policies that respect off-hours, such as banning non-urgent communication after work. On a personal level, individuals can combat time scarcity by actively scheduling and protecting their leisure time with the same importance as a business meeting. This deliberate prioritization is crucial for wellbeing.\nIn conclusion, while the dominance of work over personal life is a common challenge, it can be effectively addressed. A combined approach of institutional change and individual empowerment offers a clear path forward. By valuing personal time as essential, not optional, we can build a healthier and more sustainable balance for everyone.', NULL, 200, 300),
  ('c6e63122-777c-509f-b0f1-5d51d4c5baa4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c6e63122-777c-509f-b0f1-5d51d4c5baa4'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8ba72e40-99e1-59d2-9887-5cc52a55a60f'::uuid, NULL, E'You can find the student service desk located on the ground floor of the whole building.', NULL, NULL, NULL),
  ('c6e8ac00-fdef-57dd-a743-b11e4ef14a6a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c6e8ac00-fdef-57dd-a743-b11e4ef14a6a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the word for the place where a river starts?', 'c32419bc-c67b-543e-a439-9569249fb3d0'::uuid, NULL, NULL, E'Source / birthplace / origin', NULL, NULL),
  ('c6f20f07-699d-5dcd-ba57-ec2aa169b296'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'c6f20f07-699d-5dcd-ba57-ec2aa169b296'::uuid, 1, NULL, TRUE, 0, NULL, E'Progressive Enhancement', E'Progressive enhancement is a design practice based on the idea that instead of {{1}} for the least capable browser, or mangling our code to make a site look the same in every browser, we should provide a core set of functionality and information to all users, and then {{2}} enhance the appearance and behavior of the site for users of more capable browsers. It''s very productive development practice. Instead of {{3}} hours working out how to add drop shadows to the borders of an element in every browser, we simply use the standards-based approach for browsers that support it and don''t even attempt to implement it in browsers that don''t. After all, the users of older and less capable browsers won''t know what they are missing. The biggest {{4}} to progressive enhancement is the belief among developers and clients that websites should look the same in every browser. As a developer, you can simplify your life and dedicate your time to more interesting challenges if you let go of this outdated notion and embrace progressive enhancement.', NULL, NULL, NULL, E'1.designing, 2.progressively, 3.spending, 4.challenge', NULL, NULL),
  ('c6f73c27-1170-5c83-81fa-2f94067e1abe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c6f73c27-1170-5c83-81fa-2f94067e1abe'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c6395c61-8370-5115-a4c6-ccf405565c86'::uuid, NULL, E'We look forward to seeing you on your next visit to the library.', NULL, NULL, NULL),
