  ('c70e673d-f079-56d0-9543-2462f3c8a9ea'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c70e673d-f079-56d0-9543-2462f3c8a9ea'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '15459df0-ecb3-548d-a1dc-c9c552f6cdcf'::uuid, NULL, E'They did blood tests on him for signs of vitamin deficiency.', NULL, NULL, NULL),
  ('c714a3db-37d9-5d01-a8af-ea25eb2af07b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'HIGHLIGHT_CORRECT_SUMMARY', E'HIGHLIGHT_CORRECT_SUMMARY', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c714a3db-37d9-5d01-a8af-ea25eb2af07b'::uuid, 1, NULL, TRUE, 0, NULL, E'Alzheimer’s Disease', E'As populations have aged, dementia has soared to become the fifth leading cause of death worldwide. Alzheimer’s disease, a form of dementia, accounts for most of these cases. Tens of billions of dollars have been spent on Alzheimer’s research over the past several decades, but still there is no cure. All attempts to halt the progression of the disease have failed. Now many major drug companies have pulled out of research altogether. So why is Alzheimer’s disease still such a medical mystery? One of the signs of Alzheimer’s in the brain is damage of connections and the loss of large numbers of neurons over time. It affects the hippocampus and its connected structures, making it harder to form new memories or learn new information. As damage spreads through the brain, the cortex becomes thinner and more memories are lost, although emotional responses can often remain. As the brain shrinks further, it slowly alters personality and behavior and eventually the ability to live and function independently.\n\nClick on the paragraph that best relates to the recording.', '1cc2ce6c-61a2-5053-8e84-b356aa96dea4'::uuid, NULL, NULL, E'There is still no cure for Alzheimer’s disease, a form of dementia accounting for many deaths worldwide. It damages the neurons in the brain, and slowly changes people’s personality and behavior, and finally the ability to live on their own.', NULL, NULL),
  ('c7225e18-02c9-5cc5-8ea4-30a9d290bc1b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c7225e18-02c9-5cc5-8ea4-30a9d290bc1b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '27d1d846-b6ef-5560-863b-fa1cfcfb336a'::uuid, NULL, E'Can you help me complete this new questionnaire that the university has requested?', NULL, NULL, NULL),
  ('c72bc66a-92f1-5325-aa85-d351e084bc9a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c72bc66a-92f1-5325-aa85-d351e084bc9a'::uuid, 1, NULL, TRUE, 0, NULL, E'Mature Tree', E'The wonderful framework of mature trees creates a secluded, enclosed atmosphere that unites a great variety of plantings to inspire visitors in all seasons. Spring in the garden is marked by leafing up and flowering of trees and the eruption of the flowers in the bulb meadows, and woodland understory.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('c72d8875-9dd4-5fb7-991b-064197fdb101'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c72d8875-9dd4-5fb7-991b-064197fdb101'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which is more expensive, gold or silver?', '639038ee-3c53-5344-9ec3-22afeecc7912'::uuid, NULL, NULL, E'Gold', NULL, NULL),
