  ('c7c770c3-5cde-555c-a51f-bd2362a2d9b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'c7c770c3-5cde-555c-a51f-bd2362a2d9b9'::uuid, 1, NULL, TRUE, 0, NULL, E'Allure of Book', E'The allure of the book has always been negative and {{1}} , for the texts and pictures between the covers have helped many young readers to {{2}} and grasp the world around them in a pleasurable and meaningful way. But the allure has also enabled authors and publishers to {{3}} upon young readers'' dispositions and desires and to {{4}} them a menu that turns out to be junk food.', NULL, NULL, NULL, E'1.positive, 2.discover, 3.prey, 4.sell', NULL, NULL),
