  ('c878416e-4d14-5acb-825a-de667082a308'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'c878416e-4d14-5acb-825a-de667082a308'::uuid, 1, NULL, TRUE, 0, NULL, E'Genetically Modified Foods', E'Genetically modified foods provide no {{1}} benefit to consumers; the food is not {{2}} better or cheaper. The greater benefit, {{3}} argue, is that genetic engineering will play a crucial role in {{4}} the world''s {{5}} population. Opponents disagree, {{6}} that the world already grows more food per person than ever before – more, even, than we can {{7}} .', NULL, NULL, NULL, E'1.direct, 2.noticeably, 3.proponents, 4.feeding, 5.burgeoning, 6.asserting, 7.consume', NULL, NULL),
