  ('c8a2755a-ecab-5230-b5c5-1a628d4d45db'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c8a2755a-ecab-5230-b5c5-1a628d4d45db'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '43082336-9490-5516-b611-bed9add2f3b7'::uuid, NULL, NULL, E'Students will get their marks by the combination of both assessments and examinations.', NULL, NULL),
  ('c8a97ae2-eca8-543a-9cd9-a86df9553492'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c8a97ae2-eca8-543a-9cd9-a86df9553492'::uuid, 1, NULL, TRUE, 0, NULL, E'Tests and Grades', E'Lecture and answer the questions. Ok. Now let''s talk about tests and grades. There will be two written tests and one oral test this semester. Each written test will have forty multiple choice questions. The oral test will have five questions. Uh, some of you may think the tests are too difficult with too many questions, but that is not. So as a matter of fact, there will be a summary hand out every class this semester. And if you study them, well, then the tests will be very easy. And speaking about grades, the written and oral tests will be just a small portion of your final grade. Active class participation is the most important thing to get a good grade. So please listen to my lectures carefully. Ask many questions and discuss the topics with your classmates and me during the class. It will be very good for you to prepare for each unit before class two.\n\nWhat do students have to do to get good grades?', 'a89494c8-9935-5d2e-95ae-9975a327cefe'::uuid, NULL, NULL, E'They must study the handouts and actively participate in the class.', NULL, NULL),
  ('c8b2671e-e3d2-5ce6-9ab1-6276af1a7ea4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c8b2671e-e3d2-5ce6-9ab1-6276af1a7ea4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '679fa36a-4f56-5e5d-8f7f-7407bb495883'::uuid, NULL, NULL, E'The staff is cleaning the room for tomorrow morning''s meeting.', NULL, NULL),
  ('c8b7ba92-6f1b-5b94-87a4-8018bbd65d3a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'c8b7ba92-6f1b-5b94-87a4-8018bbd65d3a'::uuid, 1, NULL, TRUE, 0, NULL, E'Children and Snack', E'Jennifer Harris, a researcher at the University of Connecticut''s Rudd Centre for Food Policy & Obesity, has studied the impact of food advertising on children''s eating {{1}} . In one key experiment, children aged 7 to 11 watched a cartoon interspersed with either food or non-food advertisements. Afterward, they were given a bowl of cheddar cheese crackers to snack {{2}} . The results showed that children exposed to food ads consumed 45% more snacks than those who saw non-food ads. This study suggests that food advertising can significantly increase snack {{3}} among children, potentially contributing to unhealthy eating habits and obesity. Food ads, often designed with colourful packaging and appealing characters, trigger cravings in children, making them more likely to choose unhealthy, calorie-dense snacks. These advertisements create emotional associations between eating the product and feelings of enjoyment or fun, further encouraging children to {{4}} . The findings highlight the need for stricter regulations on food advertising targeting children. By reducing exposure to these ads, it may be possible to mitigate their influence and promote healthier eating {{5}} . Harris''s research underscores the importance of protecting children from marketing practices that could lead to long- term health issues, such as obesity.', NULL, NULL, NULL, E'1.behaviors, 2.on, 3.consumption, 4.indulge, 5.habits', NULL, NULL),
  ('c8c8b4b8-8dbc-55b6-bac6-e74bcb6abe83'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c8c8b4b8-8dbc-55b6-bac6-e74bcb6abe83'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5f63a8fd-196d-5685-b8ce-d25b98edc15f'::uuid, NULL, NULL, E'The challenges our health care sector faces are bigger than ever.', NULL, NULL),
  ('c8c8c8bb-c3d3-5cb2-95ad-a4f99277d84e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'c8c8c8bb-c3d3-5cb2-95ad-a4f99277d84e'::uuid, 1, NULL, TRUE, 0, NULL, E'Complementary Therapies', E'Complementary therapies - such as those {{1}} by naturopaths, chiropractors, and acupuncturists - have become increasingly popular in Australia over the last few {{2}} . Interest initially coincided with {{3}} for alternative lifestyles, while immigration and increased contact and trade with China have also had an {{4}} . The status of complementary therapies is being re-visited in a number of areas: legal regulation; the stances of doctors'' associations; their inclusion in medical education; and scientific research into their {{5}} .', NULL, NULL, NULL, E'1.practiced, 2.decades, 3.enthusiasm, 4.influence, 5.efficacy', NULL, NULL),
  ('c8ca3f46-84a7-5dc4-b41e-e9aaa063bd57'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'c8ca3f46-84a7-5dc4-b41e-e9aaa063bd57'::uuid, 1, NULL, TRUE, 0, NULL, E'Plant Pollen', E'Increasing concentrations of atmospheric carbon dioxide and changes in climate, such as increasing temperatures and altered precipitation patterns, are expected to {{1}} to increases in levels and distribution of plant pollen. Pollen from trees and grasses is a common allergen that can {{2}} health effects such as allergic rhinitis (hay fever) and asthma. In the United States in 2017, 8 percent of adults reported {{3}} from hay fever. Eight percent of adults also reported suffering from asthma, and this population of asthmatics accounts for 1.7 million emergency department visits yearly. These health effects lead to {{4}} costs. For asthma, medical expenses and indirect costs, such as missed work days, added up to $56 billion in 2007. Medical spending to treat hay fever was estimated at $11 billion in 2005.', NULL, NULL, NULL, E'1.contribute, 2.trigger, 3.suffering, 4.economic', NULL, NULL),
  ('c8cad46a-1aec-5c77-86bf-bc509f501833'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c8cad46a-1aec-5c77-86bf-bc509f501833'::uuid, 1, NULL, TRUE, 0, NULL, E'Creativity', NULL, '91eb87c1-d186-59d5-a936-3ce2c7685f73'::uuid, NULL, E'In our collective academic voyage, creativity stands as a lighthouse, guiding us through the sea of challenges. It''s not merely an artist''s tool but a universal skill that enhances our problem-solving abilities. Creativity is often the birthplace of innovation. When faced with a complex problem, a creative approach can illuminate unorthodox solutions, breaking away from the traditional ''one-right-answer'' paradigm. For instance, interdisciplinary studies show that creative thinkers are better at developing solutions that transcend conventional boundaries, fostering advancements in science, business, and the arts. Moreover, creativity in problem-solving encourages risk-taking and resilience. It allows us to view setbacks not as failures but as part of the creative process. This mindset is essential in our fast-paced world, where adaptability and flexibility are key to overcoming personal and professional hurdles.', NULL, NULL, NULL),
  ('c8ccc9dd-bebf-5a5a-89bc-3515ab1d9f0b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c8ccc9dd-bebf-5a5a-89bc-3515ab1d9f0b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '919dd88e-1120-5cde-b0f9-05f3936a36f1'::uuid, NULL, E'Most Britons prefer urban areas as their place of residence.', NULL, NULL, NULL),
  ('c8cceac6-2c83-5fd0-8365-879752737ca9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c8cceac6-2c83-5fd0-8365-879752737ca9'::uuid, 1, NULL, TRUE, 0, NULL, E'Extreme Diets', NULL, '6fd98284-7dc2-50c8-a68a-51b723f57b33'::uuid, NULL, E'Plans called “detoxification diets” either promote or restrict certain foods to provide specific nutrients in high quantities. These can be useful for addressing some nutritional problems, but they’re far too specific to be used as general cure-alls. For example, for a person with low vitamin A, a juice diet might be helpful. But for someone high in vitamin A, juicing could be disastrous. And regardless of personal nutrition, maintaining a juice diet over multiple weeks is likely to compromise the immune system due to a lack of essential fats and proteins. Therein lies the problem with all these fast-moving diets — whether you’re cutting calories or food groups, extreme diets are a shock to your system. There are well-established rates of healthy weight loss motivated by both diet and exercise that account for genetic and medical differences. And staying on those timelines requires a dietary lifestyle that’s sustainable. In fact, some of the worst side effects of extreme diets are rarely discussed since so few people stick with them, it also bears mentioning that many societies have unhealthy relationships with weight. and people are often pressured to diet for reasons other than health or happiness. So rather than trying to lose weight fast, we should all be taking our time to figure out what the healthiest lifestyle is for ourselves.', NULL, NULL, NULL),
  ('c8d04279-c832-5a33-a0e5-4a4195fce3d1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c8d04279-c832-5a33-a0e5-4a4195fce3d1'::uuid, 1, NULL, TRUE, 0, NULL, E'Conscientiousness', E'Conscientiousness is a fundamental personality trait. A conscientious person is good at self-regulation and impulse control. This trait influences whether you will set and keep long-range goals, deliberate over choices, behave cautiously or impulsively, and take obligations to others seriously.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('c8d85928-66cc-5f4e-bbca-f8a6376d93a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c8d85928-66cc-5f4e-bbca-f8a6376d93a6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '62f77b9a-cdc8-53c3-a5b6-5f75447949c9'::uuid, NULL, NULL, E'Before the invention of the refrigerator, people stored food in underground ice houses.', NULL, NULL),
  ('c8e10bb6-b839-5ec0-aabf-280dafa0aea9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'c8e10bb6-b839-5ec0-aabf-280dafa0aea9'::uuid, 1, NULL, TRUE, 0, NULL, E'Wind Farms', E'People are naturally concerned about the polluting {{1}} of energy sources such as oil or coal. Wind farms are the {{2}} . With their enormous rotating blades, these huge {{3}} are becoming more commonplace in certain {{4}} of the world. Yet for some people, they are an unwelcome {{5}} of the landscape.', NULL, NULL, NULL, E'1.effects, 2.answer, 3.machines, 4.regions, 5.feature', NULL, NULL),
