  ('c94e583a-9566-515e-86c4-ff005a1d114f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'c94e583a-9566-515e-86c4-ff005a1d114f'::uuid, 1, NULL, TRUE, 0, NULL, E'African Culture', E'African culture varies not only between national boundaries, but within them. One of the key {{1}} of this culture is the large number of {{2}} groups throughout the 54 countries on the continent. For example, Nigeria alone has more than 300 tribes, according to Culture Trip. Africa has been importing and exporting its culture for centuries; East African trading ports were a crucial link between East and West as early as the seventh century, according to The Field Museum. This led to complex urban centers along the Eastern coast, often connected by the movement of raw materials and goods from {{3}} parts of the continent. It would be impossible to {{4}} all of African culture with one description. Northwest Africa has strong ties to the Middle East, while Sub-Saharan Africa shares historical, physical and social characteristics that are very different from North Africa, according to Britannica.', NULL, NULL, NULL, E'1.features, 2.ethnic, 3.landlocked, 4.characterize', NULL, NULL),
  ('c9508ddf-77e7-5e5c-9121-43220b76a62b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c9508ddf-77e7-5e5c-9121-43220b76a62b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '692d19f7-e762-5963-b0d4-20ed3a7f731b'::uuid, NULL, NULL, E'There is no criterion passed for qualified journalists.', NULL, NULL),
