  ('c98faba9-1af0-594a-810c-ff67cfa1b85c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c98faba9-1af0-594a-810c-ff67cfa1b85c'::uuid, 1, NULL, TRUE, 0, NULL, E'Matthew Brady', E'Matthew Brady was an American photographer who is widely recognized as one of the pioneers of photography in American history. He was born around 1822-1824 and passed away on January 15, 1896. Brady is best known for his iconic photographs depicting scenes from the American Civil War. He studied under Samuel Morse, the inventor of the daguerreotype technique in America.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('c9934653-c218-51b9-9736-1f658d0fa84b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c9934653-c218-51b9-9736-1f658d0fa84b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which one has more interactions between teachers and students, a lecture or a tutorial?', 'cf73a0f6-64e6-5a7f-8412-65d871087738'::uuid, NULL, NULL, E'Tutorial', NULL, NULL),
