  ('c9af20d5-b7a2-5157-a120-8d258ee31309'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c9af20d5-b7a2-5157-a120-8d258ee31309'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '1b0facad-e599-5854-8bfb-f693945a7395'::uuid, NULL, E'The program operates solely on financial contributions from private benefactors.', NULL, NULL, NULL),
  ('c9b6032d-fc6a-5415-bcf5-c3fcdfbeee5c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c9b6032d-fc6a-5415-bcf5-c3fcdfbeee5c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ca6b5ead-5a96-57e2-822d-5f18160db02c'::uuid, NULL, NULL, E'Next term we will research into how plants grow.', NULL, NULL),
  ('c9d327da-e3df-5ea1-8362-51c19ed95fe7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c9d327da-e3df-5ea1-8362-51c19ed95fe7'::uuid, 1, NULL, TRUE, 0, NULL, E'Autocracy', NULL, '2b4deac7-108e-51ec-a442-5248a332daaa'::uuid, NULL, E'Over the last decade the share of the world''s population living under autocracy increased from 48 to 68 percent. It is more important than ever to understand how autocracies work. Autocrats have a keen interest in promoting the idea that they are all powerful. Whereas leaders in democracies can be removed via elections, leaders in autocracies can lose office in two ways: via a coup or popular revolt. To make matters worse, autocrats can rarely address both threats at the same time. They often have to choose whether to reward their elite cronies to prevent a coup or the masses to prevent a revolt. This generates many difficult tradeoffs. Cheat too little on elections and risk losing office, but cheat too much and signal weakness to your opponents. Use corruption to reward your elite friends, but not so much that it slows economic growth and sparks a revolt. Manipulate the media, but not so much that people turn off the television. Repress your political opponents, but not so much that it causes a backlash. Empower the security services, but not so much that they can overthrow you. Rulers who fail to resolve these tradeoffs often suffer the consequences.', NULL, NULL, NULL),
  ('c9d51f59-48df-5507-8be3-9e717095798f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c9d51f59-48df-5507-8be3-9e717095798f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '891eb594-6cb6-5fb5-bbbd-9ebf6bda88bb'::uuid, NULL, E'Organizational failure is considered from various perspectives in academic literature.', NULL, NULL, NULL),
