  ('c9ef4f76-8b34-56e6-bbe0-6668a6528d3a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'c9ef4f76-8b34-56e6-bbe0-6668a6528d3a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the hot liquid rock that comes out of a volcano?', 'bbb2376b-b449-5032-b6c7-9d61585405e1'::uuid, NULL, NULL, E'Lava', NULL, NULL),
  ('c9efd865-9a88-5cd5-88e5-f1f5d107ecbc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c9efd865-9a88-5cd5-88e5-f1f5d107ecbc'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6b5daa83-5611-5984-ba3e-01c65361c9d4'::uuid, NULL, NULL, E'We are moving at a very fast pace.', NULL, NULL),
  ('c9f5b886-d263-5f87-b7ee-1fb52779193f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'c9f5b886-d263-5f87-b7ee-1fb52779193f'::uuid, 1, NULL, TRUE, 0, NULL, E'Looking Trustworthy', E'It would be reassuring to think that the electorate choose who to vote for based on the candidates'' track records and future policy promises. {{1}} , many of us are swayed simply by the way that politicians look. Consider a 2009 study that asked Swiss students to look at multiple pairs of unfamiliar French political candidates and in each case to select the one who looked most competent. Most of the time, the candidate selected by students {{2}} looking the most competent was also the one who''d had real life electoral success, the implication {{3}} that voters too had been swayed by the candidates'' appearance (there''s little evidence that appearance and competence actually {{4}} ). Unsurprisingly, being attractive also helps win votes, especially in war time (in peace time, looking trustworthy is more of an advantage). Other research has shown that we''re more likely to vote for male and female candidates with deeper voices.', NULL, NULL, NULL, E'1.In truth, 2.as, 3.being, 4.correlate', NULL, NULL),
  ('c9fb701a-090e-5ffa-8793-bdc243036b6b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'c9fb701a-090e-5ffa-8793-bdc243036b6b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '68f7ec53-5df8-516e-826c-dee208d968eb'::uuid, NULL, NULL, E'Current research has been carried out in universities and other institutions.', NULL, NULL),
  ('ca017c59-8605-59ff-885b-e5d8f2d561d1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'ca017c59-8605-59ff-885b-e5d8f2d561d1'::uuid, 1, NULL, TRUE, 0, NULL, E'London Underground', NULL, NULL, NULL, NULL, E'1, 3, 2, 4', NULL, NULL),
  ('ca02783d-01be-5cd7-8101-d04cd026c2f5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ca02783d-01be-5cd7-8101-d04cd026c2f5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '77077c0a-7d67-5e48-8315-1f12a9fee313'::uuid, NULL, NULL, E'More research is required in the field of food science.', NULL, NULL),
  ('ca07357e-4b71-516f-8699-28962d31b10b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ca07357e-4b71-516f-8699-28962d31b10b'::uuid, 1, NULL, TRUE, 0, NULL, E'Aboriginal People', E'Aboriginal people are believed to have arrived as early as 60,000 years ago, and evidence of Aboriginal art in Australia dates back at least 30,000 years. Several states and territories had their origins as penal colonies, with the first British convicts arriving at Sydney Cove in seventeen eighty eight.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ca0f2090-b9ac-53c3-964a-b0a45947cd94'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ca0f2090-b9ac-53c3-964a-b0a45947cd94'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '53e77940-0c7c-5edb-bb34-0ac20cbe7648'::uuid, NULL, NULL, E'Plants are the living things that can grow on land or in water.', NULL, NULL),
  ('ca11a860-49bb-5902-b44e-9a97d9d8b005'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ca11a860-49bb-5902-b44e-9a97d9d8b005'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c1afd882-2e8c-5847-9c3a-675ccb9d5d0d'::uuid, NULL, E'Biology is the backbone of many specialized courses in the university.', NULL, NULL, NULL),
  ('ca13962f-35a4-5588-9c6f-44dd9a63798e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'ca13962f-35a4-5588-9c6f-44dd9a63798e'::uuid, 1, NULL, TRUE, 0, NULL, E'Microbial Gene Catalog', E'A team from Fudan University in Shanghai has launched the world''s most comprehensive global microbial gene catalog - a database containing 303 million unigenes that will help researchers better understand the relationship between microorganisms and human health. A unigene is a representative DNA sequence of gene sequences that stem from the same microbial species. A paper about the catalog, "Towards the Biogeography of Prokaryotic Genes", was published in the science journal Nature. Bacterial communities live in habitats and each community comprises a group of unique species called a microbiome, which contains genes with specific functions. To collect all the genes in the global microbiome to create the catalog, a team from Fudan''s Institute of Science and Technology for Brain-Inspired Intelligence - Luis Pedro Coelho, Zhao Xingming and Peer Bork - identified unigenes from 14 environments, including human and animal bodies, soil and water. They created the database based on 13,000 pieces of publicly available data. The researchers said microbiome research is normally carried out according to different habitats such as human microorganisms and marine microorganisms, but the catalog can analyze microbial metagenomes in different habitats on a global scale. While collecting the unigenes, they discovered that relatively few - 5.8 percent - could be identified across habitats. Such unigenes were usually related to antibiotic resistance, with some able to move from one genome to another. Understanding how bacteria and genes cross from one environment to another is critical for human health research, understanding antibiotic resistance and the development of antibacterial drugs, they said. Zhao said the team expects to use the catalog to study the influence of microbes on human health, cognition and behavior.', NULL, NULL, NULL, NULL, 5, 75),
  ('ca178559-367f-5d50-838e-df6697daad54'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ca178559-367f-5d50-838e-df6697daad54'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '742004b1-8d88-518d-a2fd-45deba447fb7'::uuid, NULL, NULL, E'Students often gather in the courtyard to socialize and relax together.', NULL, NULL),
