  ('ca30582c-d0df-50ad-83a9-960468214ea8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ca30582c-d0df-50ad-83a9-960468214ea8'::uuid, 1, NULL, TRUE, 0, NULL, E'Environmentalists', E'Although environmentalists have been {{1}} about this situation for decades, many other people are finally beginning to realise that if we don''t act soon it will be too late. The good news is that more and more businesses and governments are beginning to {{2}} that without a healthy environment the global economy and everything that depends on it will be seriously endangered. And they are beginning to take {{3}} action.', NULL, NULL, NULL, E'1.warning, 2.understand, 3.positive', NULL, NULL),
  ('ca34e5fc-f4ef-5caa-adfa-da201369d66e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ca34e5fc-f4ef-5caa-adfa-da201369d66e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '88be32a5-33c6-58e1-a66c-68b6751b5d0d'::uuid, NULL, E'To get the presentation, visit my website for a download link.', NULL, NULL, NULL),
