  ('ca99c61d-1253-51f6-a62d-d2c70f2718ea'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'ca99c61d-1253-51f6-a62d-d2c70f2718ea'::uuid, 1, NULL, TRUE, 0, NULL, E'Online Games', E'Computer and online games should be banned to students in schools as they have no educational value. What''s your opinion?', NULL, NULL, NULL, NULL, 200, 300),
  ('ca9bb7d9-d061-5df1-8c8d-b329ca86234c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ca9bb7d9-d061-5df1-8c8d-b329ca86234c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Where do people go to watch plays?', '79ffbe38-f85c-59f6-a6fa-2162134e593f'::uuid, NULL, NULL, E'Theatre / theater', NULL, NULL),
  ('caa668f7-bef7-5fc1-99d4-21c0132af279'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'caa668f7-bef7-5fc1-99d4-21c0132af279'::uuid, 1, NULL, TRUE, 0, NULL, E'Sustainable Business', NULL, 'c0280f1a-845d-5b32-960e-93a8b9a14d54'::uuid, NULL, E'In this lecture, I''d like to focus on the vital role of sustainable business practices in shaping our future. In an era of environmental challenges, the way businesses operate can have far-reaching impacts on our planet and society. Sustainable business isn''t just about reducing environmental harm; it''s about creating a positive impact. Companies adopting green practices are seeing benefits not only in their environmental footprint but also in financial performance and public perception. This shift is driven by increased consumer awareness and a global call for corporate responsibility. Moreover, sustainable business practices often lead to innovation. By rethinking materials, energy use, and supply chains, companies are uncovering new, more efficient ways of operating. This innovation is not just beneficial for the environment; it''s a catalyst for economic growth and job creation. In conclusion, the move towards sustainable business practices represents a significant opportunity for both environmental preservation and economic prosperity. As future leaders and consumers, your choices and actions will be instrumental in driving this positive change.', NULL, NULL, NULL),
  ('caaaba9b-824a-5a39-8506-40046cea1831'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'caaaba9b-824a-5a39-8506-40046cea1831'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6bbd565a-2b60-5228-b921-be9aad5f785c'::uuid, NULL, NULL, E'The amount of advertising aimed at children sparks widespread debate.', NULL, NULL),
  ('caaf8d43-9885-5e59-9330-872d6b8969d4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'caaf8d43-9885-5e59-9330-872d6b8969d4'::uuid, 1, NULL, TRUE, 0, NULL, E'Only Family', E'Imagine living all your life as the only family on your street. Then, one morning, you open the front door and discover houses all around you. You see neighbors tending their gardens and children walking to school. Where did all the people come from? What if the answer turned out to be that they had always been there — you just hadn''t seen them?', NULL, NULL, NULL, NULL, NULL, NULL),
  ('caafe4e7-d5b7-5ea5-930d-9f2271d1c45e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'caafe4e7-d5b7-5ea5-930d-9f2271d1c45e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '71b5f8cb-d3f2-51af-89f5-e4f0395fa9e8'::uuid, NULL, NULL, E'Accountancy students probably have a good understanding of economics, statistics and psychology.', NULL, NULL),
