  ('cab3140a-fd8e-5eb2-a776-84616e684eaa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cab3140a-fd8e-5eb2-a776-84616e684eaa'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do we describe a person unable to pay his or her debts?', '40453145-15c1-51e0-8351-8244d5871217'::uuid, NULL, NULL, E'Insolvent / bankrupt', NULL, NULL),
