  ('cab985e6-2bd0-5694-9e69-735107d0cf40'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cab985e6-2bd0-5694-9e69-735107d0cf40'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '00525568-4cb9-5300-a797-a4c5c3ae1023'::uuid, NULL, E'Consuming fruits and vegetables can help students avoid viruses.', NULL, NULL, NULL),
  ('cabba2a9-f819-59e6-af73-fe8d11d6c421'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'cabba2a9-f819-59e6-af73-fe8d11d6c421'::uuid, 1, NULL, TRUE, 0, NULL, E'Dictatorship', E'Dictatorship is not a modern concept. Two thousand years ago, during the period of the Roman Republic, exceptional powers were sometimes given by the Senate to {{1}} dictators such as Sulla and Julius Caesar. The {{2}} was that the dictatorship would be temporary and that it would make it {{3}} to take swift and effective action to deal with an emergency. There is some {{4}} as how the term should be applied today. Should it be used in its original form to describe the temporary exercise of emergency powers? Or can it now be {{5}} in a much broader sense as common usage suggests?', NULL, NULL, NULL, E'1.individual, 2.intention, 3.possible, 4.disagreement, 5.applied', NULL, NULL),
  ('cabc5b18-c3cb-53a1-9d89-f0256d33d3a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cabc5b18-c3cb-53a1-9d89-f0256d33d3a8'::uuid, 1, NULL, TRUE, 0, NULL, E'Pollution Reduction', E'Air pollution reduced when U.S. embassies around the world installed monitors and tweeted the Readings. The resulting reductions in air pollution levels had large health benefits for residents in these cities, speaking to the potential efficacy of other monitoring and information interventions.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('cac295a3-b0a2-5f88-b4f1-08e3d8bbbfcc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cac295a3-b0a2-5f88-b4f1-08e3d8bbbfcc'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is a mass of ice floating in the sea?', 'afbeb8b3-7797-5dd6-926a-21b7288ee9dc'::uuid, NULL, NULL, E'Iceberg', NULL, NULL),
  ('caca6cb9-854f-57c6-a759-8194ea972f62'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'caca6cb9-854f-57c6-a759-8194ea972f62'::uuid, 1, NULL, TRUE, 0, NULL, E'Happiness and Social Relations', NULL, '3d78ca8e-d90d-5327-bafc-ec4043b66978'::uuid, NULL, E'Happiness comes from frequency and quality of social relation.\nThe higher the frequency is, the more happiness relations with friends and family and others produce.\nIt is not sure why social relation is correlated with happiness.\nBut there''s evidence that when people feel more satisfied with their social relations, they will feel happier, in turn, when people feel happier, they will get more satisfied with social relations.\nHappy people tend to be social more with friends and have more interaction between family.\nSome people wonder if their social activities make them happier or their happy personalities drive them to be social more with their friends and families.', NULL, NULL, NULL),
  ('cacc0566-8187-5d74-bf46-6f65eaac0a05'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cacc0566-8187-5d74-bf46-6f65eaac0a05'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '39713a3c-4f6f-5fd2-aea4-f247fe9e4213'::uuid, NULL, E'It is important to cite examples to support your argument.', NULL, NULL, NULL),
