  ('cbeebe3d-c04f-5483-aa06-a8f83978a840'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cbeebe3d-c04f-5483-aa06-a8f83978a840'::uuid, 1, NULL, TRUE, 0, NULL, E'Possible Understanding', E'The question is asked: "How is understanding possible?" The technique for thinking of this approach is that, while Scripture is "something past a standard substance," Scripture is in the principle examination "content" which individuals endeavor to appreciate; in this sense, the benchmarks of seeing any substance applied to the Bible additionally paying little regard to whatever other additional, especially philosophical gauges are considered.', NULL, NULL, NULL, NULL, NULL, NULL),
