  ('cbf714e3-ade0-5ff0-878e-ebc4447dc90f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cbf714e3-ade0-5ff0-878e-ebc4447dc90f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person who watches candidates in an exam and ensure that they do not cheat?', '92fbfcdb-ce98-54c7-8410-3df1a7a3e5ec'::uuid, NULL, NULL, E'Invigilator / proctor', NULL, NULL),
  ('cbfa11aa-1581-51eb-96f7-992bd5bb38ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'cbfa11aa-1581-51eb-96f7-992bd5bb38ca'::uuid, 1, NULL, TRUE, 0, NULL, E'Io''s Crater', E'Jupiter''s moon Io is the most volcanically active world in the solar system, {{1}} hundreds of eruptions occurring every year. These eruptions constantly reshape the surface of Io, erasing any signs of impact craters that may have formed from collisions with asteroids and comets. However, a keen-eyed amateur astronomer from Sweden has {{2}} what may be the first crater ever seen on Io. Jesper Sandberg was browsing through old images from the Galileo spacecraft, which explored the Jupiter system from 1995 to 2003, when he {{3}} a small, circular feature on Io''s surface. The feature, which is about 100 meters across, appears to be a fresh impact crater surrounded by a bright ejecta blanket. Sandberg reported his finding to the Planetary Society, which confirmed that the feature had not been previously {{4}} or catalogued. The discovery of this crater could provide valuable {{5}} into the geology and history of Io, as well as the frequency and size of impactors in the outer solar system.', NULL, NULL, NULL, E'1.with, 2.discovered, 3.noticed, 4.identified, 5.insights', NULL, NULL),
  ('cc027c5f-860c-582f-8cad-a2cab553e99e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cc027c5f-860c-582f-8cad-a2cab553e99e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '1a09e022-91a9-5146-afd7-c4d09b3ab6e1'::uuid, NULL, E'Last year, they faced challenges with paying their school fees.', NULL, NULL, NULL),
  ('cc081e51-8406-5ea8-8acd-1edc63a22e99'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'cc081e51-8406-5ea8-8acd-1edc63a22e99'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd3331810-652f-5e0a-a71a-c97e5006c741'::uuid, NULL, NULL, E'Understanding ancient poetry is efficient for the project.', NULL, NULL),
  ('cc09c52a-0121-50be-b5ef-82afa72942e0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cc09c52a-0121-50be-b5ef-82afa72942e0'::uuid, 1, NULL, TRUE, 0, NULL, E'Medical School', NULL, '05072d57-19c7-5df1-a0df-363b061ab095'::uuid, NULL, E'It seems like only yesterday that I was sitting where you are, just finishing my first year of medical school and wondering if I''d ever get a chance to use all my new knowledge on a real live patient! Well, I have good news for you! You don''t have to wait until your third or fourth year of medical school to get some hands-on experience! The dean has invited me here to tell you about the university''s rural opportunity program. If you enroll in this program, you can have the opportunity this summer, after your first year of medical school, to spend from four to six weeks observing and assisting a real physician like me in a small rural community. You won''t have to compete with other students for time and attention, and you can see what life as a country doctor is really like. The program was designed to encourage medical students like yourselves to consider careers in rural communities that are still understaffed. It seems that medical students are afraid to go into rural family practice for two reasons. First, they don''t know much about it. And second, specialists in the cities usually make more money. But, on the up-side, in rural practice, doctors can really get to know their patients and be respected members of the community. I participated in the program when it first started and spent six weeks in a small rural town. Let me tell you, it was really great! I got to work with real patients. I watched the birth of a child, assisted an accident victim, and had lots of really practical hands-on experience—all in one summer. And to my surprise, I found that country life has a lot to offer that city life doesn''t—no pollution or traffic jams, for instance! My experience made me want to work where I''m needed and appreciated. I don''t miss the city at all!', NULL, NULL, NULL),
  ('cc0b9686-6fa4-5629-bf24-0cc3701e3f62'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'cc0b9686-6fa4-5629-bf24-0cc3701e3f62'::uuid, 1, NULL, TRUE, 0, NULL, E'Nightjar', E'When you spend your days nesting on the ground and weigh less than 100 grams, self-preservation depends on mastering the art of disguise. The nightjar''s soft plumage and variegated coloring help it {{1}} in with its surrounds, but it is the bird''s own judgement in choosing the most sympathetic background that {{2}} it a camouflage champion. Each bird chooses where to nest {{3}} on its specific patterns and colors, says camouflage researcher Martin Stevens, of the Centre for Ecology and Conservation at the University of Exeter in Cornwall. "Each individual bird looks a little bit different," he says. "This is not a species-level choice. Individual birds consistently sit in places that enhance their own unique markings, {{4}} within a habitat and at a fine scale with regards to specific background sites."', NULL, NULL, NULL, E'1.blend, 2.makes, 3.based, 4.both', NULL, NULL),
  ('cc0f9bc3-8569-58e6-8100-a6408e8e24c9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cc0f9bc3-8569-58e6-8100-a6408e8e24c9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '381b690d-0bf2-5255-93fd-c841b6d68d12'::uuid, NULL, E'Some claim that chocolate can reduce your chance of a heart attack.', NULL, NULL, NULL),
