  ('cc777e35-1d71-55d4-b694-abdefd0058bc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cc777e35-1d71-55d4-b694-abdefd0058bc'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '1edafc45-ca43-5413-83ae-4d76b18548b0'::uuid, NULL, E'For timetable inquiries this term, consult the tutor without delay.', NULL, NULL, NULL),
  ('cc7aa7ad-4c43-5c12-8d3c-acfca01c3305'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'cc7aa7ad-4c43-5c12-8d3c-acfca01c3305'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '478ca391-d53a-5091-8206-de5c6a0e5293'::uuid, NULL, NULL, E'Students have freedom to choose the subjects they are interested in.', NULL, NULL),
