  ('ceb7b097-600e-5a7f-bbf1-68851bd7205b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ceb7b097-600e-5a7f-bbf1-68851bd7205b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do you call the movements that the babies move by using hands and legs?', '03624bc6-cbaf-5801-a294-6f085bca95da'::uuid, NULL, NULL, E'Crawling / crawl', NULL, NULL),
  ('ceb94bca-6be6-5f49-b034-5d5c894889b1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ceb94bca-6be6-5f49-b034-5d5c894889b1'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd0dd212f-36bf-5e73-824e-4fae36e5a82b'::uuid, NULL, NULL, E'Medical books and journals have been moved to the second floor.', NULL, NULL),
  ('cebafa2c-fd13-5c50-94b8-3a28897c97cb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cebafa2c-fd13-5c50-94b8-3a28897c97cb'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0572b8f3-818b-5e41-88b4-9b560f66387f'::uuid, NULL, E'Active people often live longer and don''t get seriously ill.', NULL, NULL, NULL),
  ('cebebe44-d082-5720-95ac-af110023ed7f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'cebebe44-d082-5720-95ac-af110023ed7f'::uuid, 1, NULL, TRUE, 0, NULL, E'Best Teachers', E'Parents are the best teachers. To what extent do you agree with this statement?', NULL, NULL, E'Parents play a crucial role in the development and education of their children. Some argue that parents are the best teachers, while others may hold a different view. In my opinion, I strongly agree that parents are indeed the best teachers due to their deep emotional connection, lifelong dedication, and unique understanding of their children.\nFirstly, parents possess a deep emotional connection with their children, which makes them the best teachers. From the moment a child is born, parents are there to nurture, guide, and support them. This emotional bond allows parents to understand their children''s needs, learning styles, and interests better than anyone else. It enables them to tailor their teaching methods and provide personalized attention that fosters a positive learning environment.\nSecondly, parents demonstrate a lifelong dedication to their children''s education. Unlike other teachers who come and go, parents are committed to their children''s growth from infancy to adulthood. They continuously invest time and effort in their children''s education, ensuring a consistent and stable learning environment. This dedication allows parents to instill important values, work ethics, and life skills that go beyond academic knowledge.\nIn conclusion, I firmly believe that parents are the best teachers for their children. The deep emotional connection they share, their lifelong dedication, and their unique understanding of their children''s needs make them unparalleled in their teaching role. While other teachers certainly have a valuable place in a child''s education, parents are the foundation upon which a child''s learning journey begins. It is essential to recognize and appreciate the significant impact parents have on shaping their children''s lives and academic success.', NULL, 200, 300),
  ('cebfa4f0-8b78-5f56-bc7c-af35edcd6cc2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cebfa4f0-8b78-5f56-bc7c-af35edcd6cc2'::uuid, 1, NULL, TRUE, 0, NULL, E'Mental Illness', E'In the not-so-distant past, society shunned people with mental health conditions. Some people believed that evil spirits or divine retribution were responsible for mental illness. Although this way of thinking has been extricated from society in much of the world, it still casts a long shadow.', NULL, NULL, NULL, NULL, NULL, NULL),
