  ('ceefa045-6c5d-5c8e-8068-1fa026fdf960'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ceefa045-6c5d-5c8e-8068-1fa026fdf960'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '392eccbe-1a55-5ce8-be5d-3e43a4883955'::uuid, NULL, E'The lecture will deal with the influence of technology on music.', NULL, NULL, NULL),
  ('cef2f6b7-bdfb-5032-b048-e6e192856f49'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'cef2f6b7-bdfb-5032-b048-e6e192856f49'::uuid, 1, NULL, TRUE, 0, NULL, E'Chemicals', E'Chemicals used to control weeds in crops such as corn and soybeans may sometimes run off farmland and enter surface water bodies such as lakes and streams. If a surface water body that is used as a {{1}} water supply receives excess amounts of these herbicides, then the municipal water treatment plant must {{2}} them out in order for the water to be safe to drink. This added filtration process can be expensive. Farmers can help control excess herbicides in runoff by choosing chemicals that bind with {{3}} more readily, are less toxic, or degrade more quickly. Additionally, selecting the best tillage practice can help minimize herbicide {{4}} .', NULL, NULL, NULL, E'1.drinking, 2.filter, 3.soil, 4.pollution', NULL, NULL),
  ('cef46620-74f3-5be0-936e-7ab59bcfa67e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cef46620-74f3-5be0-936e-7ab59bcfa67e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f794ea2a-aa05-5f5c-ad77-17f32c14cbaa'::uuid, NULL, E'Once we make the adjustments for inflation, the fall in interest rates is quite small.', NULL, NULL, NULL),
