  ('cf8a0f3b-c425-565e-a9a0-3c953a894480'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cf8a0f3b-c425-565e-a9a0-3c953a894480'::uuid, 1, NULL, TRUE, 0, NULL, E'Avi Loeb', E'“The situation is similar to a pregnant woman that has twin babies in her belly,” says Avi Loeb of the Harvard-Smithsonian Center for Astrophysics. He''s proposing the idea in a paper that''s been accepted for publication in the Astrophysical Journal Letters.', NULL, NULL, NULL, NULL, NULL, NULL),
