  ('cf90a777-a70f-52cc-b8c5-56041fc2ed58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'cf90a777-a70f-52cc-b8c5-56041fc2ed58'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'cb17ae48-7b4c-510a-b9d0-f8d55af8eeba'::uuid, NULL, NULL, E'There is an important difference between mass production and batch production.', NULL, NULL),
  ('cf927dca-9209-5bdf-aaae-438e6cbc9078'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cf927dca-9209-5bdf-aaae-438e6cbc9078'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e6f8c8f9-0e0e-5c2e-95c4-ba87d1a5e908'::uuid, NULL, E'The most serious cases were treated at the scene of the accident.', NULL, NULL, NULL),
  ('cf993444-2146-5872-ab08-1867a4cb2ea4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cf993444-2146-5872-ab08-1867a4cb2ea4'::uuid, 1, NULL, TRUE, 0, NULL, E'Mental Health Challenge', E'The COVID-19 pandemic created an enormous level of stress on a global scale, leading to elevated levels of anxiety, depression, and other mental illnesses. Along with this was a disruption and challenges in the delivery of mental health services that were traditionally provided in the office.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('cf9cb36c-5f63-597f-b006-78b31a7ade3a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'cf9cb36c-5f63-597f-b006-78b31a7ade3a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '85181337-95f2-5b4c-aa72-ccb29c633a60'::uuid, NULL, NULL, E'Remember, your homework is due next Tuesday without fail.', NULL, NULL),
  ('cfa3f150-85eb-560c-be88-d85a07b50101'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cfa3f150-85eb-560c-be88-d85a07b50101'::uuid, 1, NULL, TRUE, 0, NULL, E'Flattened World', E'The beginning of the twenty-first century will be remembered, not for military conflicts or political events, but for a whole new age of globalization - a ''flattening'' of the world. The explosion of advanced technologies now means that suddenly knowledge pools and resources have connected all over the planet, leveling the playing field as never before.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('cfa52d89-1135-5258-937f-4bd1ceb4f0fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'cfa52d89-1135-5258-937f-4bd1ceb4f0fd'::uuid, 1, NULL, TRUE, 0, NULL, E'Classical Music', NULL, NULL, NULL, NULL, E'4, 2, 1, 3', NULL, NULL),
  ('cfa74a90-67a2-532f-99fa-c7c6cdda5488'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cfa74a90-67a2-532f-99fa-c7c6cdda5488'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the transport system using trains in a city, often underground?', '85580880-4ab6-56b0-b9a0-2985c9379ca8'::uuid, NULL, NULL, E'Subway', NULL, NULL),
  ('cfac2223-9cee-58df-b012-90aea6c47973'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'cfac2223-9cee-58df-b012-90aea6c47973'::uuid, 1, NULL, TRUE, 0, NULL, E'Human Empathy', E'Do you believe that human empathy is declining in the digital age?', NULL, NULL, E'In today''s digital era, the question arises: is human empathy dwindling? The answer is unequivocally yes. The pervasive influence of technology has contributed to a decline in human empathy, evident in various aspects of our daily lives.\nExcessive screen time, primarily driven by the proliferation of smartphones and social media platforms, has emerged as a significant contributor to the decline of empathy. This increased digital engagement has led to a notable decrease in face-to-face interactions, which are essential for fostering empathy. Instead of meaningful conversations and interpersonal connections, individuals are often absorbed in virtual interactions, hindering the development of empathetic skills that are nurtured through real-life experiences.\nFurthermore, social media platforms, originally designed to facilitate connections, often foster comparison and competition rather than genuine empathy. Users frequently present idealized versions of their lives, fueling feelings of inadequacy and promoting self-promotion over empathy. In this atmosphere of constant comparison, empathy takes a backseat, exacerbating the trend of declining empathy in the digital age.\nIn conclusion, the digital age has ushered in a decline in human empathy, fueled by excessive screen time, the competitive nature of social media, and the anonymity of online interactions. To counteract this trend, it is essential to prioritize genuine human connection and cultivate empathy both online and offline.', NULL, 200, 300),
  ('cfc13a58-105a-548c-8c01-4c310089c28a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'cfc13a58-105a-548c-8c01-4c310089c28a'::uuid, 1, NULL, TRUE, 0, NULL, E'Plug-in Vehicle', E'Here''s a term you''re going to hear much more often: plug-in vehicle, and the acronym PEV. It''s what you and many other people will drive to work in ten years and more from now. At that time, before you drive off in the morning you will first unplug your car - your plugin vehicle. Its big on board batteries will have been fully charged overnight, with enough power for you to drive 50-100 kilometers through city traffic.\nWhen you arrive at work you''ll plug in your car once again, this time into a socket that allows power to flow from your car''s batteries to the electricity grid. One of the things you did when you bought your car was to sign a contract with your favorite electricity supplier, allowing them to draw a limited amount of power from your car''s batteries should they need to, perhaps because of a blackout, or very high wholesale spot power prices. The price you get for the power the distributor buys from your car would not only be the most attractive to you, but also be a good deal for them too, their alternative being very expensive power from peaking stations. If, driving home or for some other reason your batteries looked like running flat, a relatively small, but quiet and efficient engine running on petrol, diesel or compressed natural gas, even bio-fuel, would automatically cut in, driving a generator that supplied the batteries so you could complete your journey.\nConcerns over ''peak oil'', increasing greenhouse gas emissions, and the likelihood that by the middle of this century there could be five times as many motor vehicles registered worldwide as there are now, mean that the world''s almost total dependence on petroleum-based fuels for transport is, in every sense of the word, unsustainable.', NULL, NULL, E'Plug-in vehicles are what many people will drive to work in ten years and more from now, and one of the things you did when you bought your car was to sign a contract with your favorite electricity supplier, which would be a good deal for them too, but the world''s almost total dependence on petroleum-based fuels for transport is unsustainable.', NULL, 5, 75),
  ('cfc4ef84-4697-560a-be96-b70ca052eab3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'cfc4ef84-4697-560a-be96-b70ca052eab3'::uuid, 1, NULL, TRUE, 0, NULL, E'Visual Perception', E'A team in the University of London found that people who went with their initial response on a test of visual perception (questions included picking out an anomaly in a pattern of symbols) did better than those who were given more time to ponder. {{1}} the subconscious brain recognized a rotated version of the same symbol as different, the conscious brain reasoned that ''an apple is still an apple whether rotated or not'', the researchers on the project {{2}} . When the subjects had time to engage their higher-level functions {{3}} of relying on their intuitive responses, they were more {{4}} to be wrong.', NULL, NULL, NULL, E'1.Whereas, 2.concluded, 3.instead, 4.likely', NULL, NULL),
  ('cfc68c94-2baa-5fd0-be49-80ee89949e87'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cfc68c94-2baa-5fd0-be49-80ee89949e87'::uuid, 1, NULL, TRUE, 0, NULL, E'Student''s Reading', E'The student''s reading in his own subject slows down, and his comprehension becomes less secure. He expresses himself slowly and often fails to convey his ideas exactly. He is disappointed to find that under pressure he makes a lot of unnecessary mistakes in areas where he knows the correct language forms.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('cfceacdd-7eaf-5037-87a8-3c22e544e4ff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cfceacdd-7eaf-5037-87a8-3c22e544e4ff'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f5d07a2a-f243-5dbd-8579-879c3da7a1b1'::uuid, NULL, E'An office assistant is to help the attorney organize all of his case files.', NULL, NULL, NULL),
  ('cfd33e47-0ad7-5f68-b0b5-f57472e48449'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'cfd33e47-0ad7-5f68-b0b5-f57472e48449'::uuid, 1, NULL, TRUE, 0, NULL, E'Medicare', E'Medicare was created in 1965 as a safety net health insurance program for older Americans. All Americans over 65 years old qualify for Medicare health coverage regardless of preexisting conditions, and Medicare covers a significant portion of the costs of doctor''s office visits, treatments and surgeries, and prescription medications, although Medicare recipients also pay annual premiums and out-of-pocket costs.', NULL, NULL, NULL, NULL, NULL, NULL),
