  ('d02e5a66-c1fb-5899-95a5-a896b76ddee2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd02e5a66-c1fb-5899-95a5-a896b76ddee2'::uuid, 1, NULL, TRUE, 0, NULL, E'Behaviorists', E'Another way of looking at personality is the behaviorist approach. According to the behaviorists, the inner {{1}} of the consciousness are not important. Instead they believed that our behaviors, and therefore our {{2}} are learned primarily through our experiences. The theories of behaviorism arose through {{3}} largely on animals in which behaviors were learned through carefully controlled {{4}} .', NULL, NULL, NULL, E'1.facts, 2.personalities, 3.experiments, 4.stimuli', NULL, NULL),
