  ('d03dbbb6-a977-5fda-bd84-bcbcb4d75cbb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd03dbbb6-a977-5fda-bd84-bcbcb4d75cbb'::uuid, 1, NULL, TRUE, 0, NULL, E'Physical Activities', E'Participating regularly in physical activity has been shown to benefit an individual''s health and wellbeing. Regular physical activity is important in reducing the risk of chronic diseases, such as heart disease and stroke, obesity, diabetes and some forms of cancer. The National Physical Activity Guidelines for Adults recommends at least 30 minutes of moderate-intensity physical activity, preferably every day of the week, to obtain health benefits.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d04a1756-523a-50d7-bdfb-913c38fe0a5c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd04a1756-523a-50d7-bdfb-913c38fe0a5c'::uuid, 1, NULL, TRUE, 0, NULL, E'Charity Group', E'Landing a position with the acclaimed charity group, often referred to as the {{1}} providers, was a dream come true for Sarah. Although the organization could only offer a {{2}} stipend, she eagerly {{3}} the terms. She believed that working alongside such selfless individuals was far more {{4}} than chasing a high corporate salary. Over the years, this dedicated group has continued to provide essential healthcare to impoverished communities worldwide, relying heavily on passionate workers who value purpose over financial gain.', NULL, NULL, NULL, E'1.angel, 2.meager, 3.accepted, 4.rewarding', NULL, NULL),
  ('d060e6a7-215f-5469-b02b-1eb2948ae118'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd060e6a7-215f-5469-b02b-1eb2948ae118'::uuid, 1, NULL, TRUE, 0, NULL, E'Faster communications', E'Faster communications have irrevocably altered the way we communicate and interact with others, ushering in a new era of interconnectedness that has transformed the world into an interconnected global village. The emergence of cutting-edge technologies such as the internet and mobile devices has enabled us to transmit information at unprecedented speeds.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d061b184-aa12-5ec6-aa5a-833da30730d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd061b184-aa12-5ec6-aa5a-833da30730d7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '71c91632-39c2-5850-8cc1-f40e343d56b5'::uuid, NULL, NULL, E'Children in this village enjoy free education and medical care.', NULL, NULL),
