  ('d078351b-cd5f-51ba-8621-43a49edb52b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd078351b-cd5f-51ba-8621-43a49edb52b8'::uuid, 1, NULL, TRUE, 0, NULL, E'Paracas Glyphs', E'Unlike the iconic Nasca lines — most of which are only visible from overhead — the older Paracas glyphs were laid down on hillsides, making them visible to villages below. The two cultures also pursued different artistic subjects: Nasca lines most often consist of lines or polygons, but many of the newfound Paracas figures depict humans.', NULL, NULL, NULL, NULL, NULL, NULL),
