  ('d0a55cf3-ad7f-5254-8c92-a7652afb4327'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd0a55cf3-ad7f-5254-8c92-a7652afb4327'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '80aed774-b2b0-504a-bdc9-9b4b67d342e8'::uuid, NULL, E'Anatomy examines both internal and external structures of the human body.', NULL, NULL, NULL),
  ('d0af9482-6c4c-5648-ade4-7e53b4be441e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'd0af9482-6c4c-5648-ade4-7e53b4be441e'::uuid, 1, NULL, TRUE, 0, NULL, E'Mandarin', NULL, NULL, NULL, NULL, E'5, 2, 1, 4, 3', NULL, NULL),
  ('d0afd0cf-da9a-53ca-9d04-3197a05963a9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'd0afd0cf-da9a-53ca-9d04-3197a05963a9'::uuid, 1, NULL, TRUE, 0, NULL, E'Nurse Shark', E'Nurse sharks are nocturnal animals, spending the day in large inactive groups of up to 40 individuals. Hidden under submerged ledges or in crevices within the reef, the nurse sharks seem to prefer specific resting sites and will return to them each day after the nights hunting. By night, the sharks are largely solitary. Nurse sharks spend most of their time foraging through the bottom sediments in search of food.\nTheir diet consists primarily of crustaceans, molluscs, tunicates and other fish such as spiny lobsters, crabs, shrimps, sea urchins, octopuses, squid, marine snails and bivalves and in particularly, stingrays.\nNurse sharks are thought to take advantage of dormant fish which would otherwise be too fast for the sharks to catch, although their small mouths limit the size of prey items, the sharks have large throat cavities which are used as a sort of bellows valve. In this way, nurse sharks are able to suck in their prey. Nurse sharks are also known to graze algae and coral.\nGenerally slow and sluggish, nurse sharks spend much of their time resting on the bottom of the ocean. Nurse sharks have been observed resting on the bottom with their bodies supported on their fins, possibly providing a false shelter for crustaceans which they then ambush and eat. If it must move, the nurse shark may even use its large front (or pectoral) fins to ‘walk’ along the ocean floor.', NULL, NULL, E'Since nurse sharks are nocturnal animals, they spend the day in groups and are solitary at night, and they are thought to take advantage of dormant fish by providing a false shelter before nurse sharks can suck in their prey.', NULL, 5, 75),
