  ('d1891007-c5d1-5b3d-9237-4921da91875e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd1891007-c5d1-5b3d-9237-4921da91875e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bc625623-e8a2-5171-a17d-2c6046ba3760'::uuid, NULL, E'Students are competing for every place in the computer courses.', NULL, NULL, NULL),
  ('d18ad3c9-87cf-55fc-afff-ed1cb78fc61e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd18ad3c9-87cf-55fc-afff-ed1cb78fc61e'::uuid, 1, NULL, TRUE, 0, NULL, E'Roman Arena', E'The Romans glorified the {{1}} shown in the arena, but {{2}} the events and degraded the participants. Mosaic pictures of executions and combats, {{3}} violent to our eyes, were displayed in the public rooms and even dining rooms in the homes of wealthy Romans. How can the viewer today possibly understand such images? Until fairly recently, modern authors writing about the arena minimized its significance and {{4}} the institutionalized violence as a sideline to Roman history. The {{5}} was also to view the events through our own eyes and to see them as pitiful or horrifying, although to most Romans empathy with victims of the arena was inconceivable. In the past few decades, however, scholars have started to analyze the complex motivations for deadly public entertainments and for contradictory views of gladiators as despised, yet beloved hero-slaves.', NULL, NULL, NULL, E'1.bravery, 2.trivialized, 3.graphically, 4.represented, 5.tendency', NULL, NULL),
  ('d18bb08e-87ae-5846-afc9-2d0ba908fc48'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd18bb08e-87ae-5846-afc9-2d0ba908fc48'::uuid, 1, NULL, TRUE, 0, NULL, E'Peppermint', E'Peppermint grows best in partial shade, where it has some protection from the midday sun of hot summer days. The plant needs frequent watering, but overall, it doesn''t need much encouragement to grow. In fact, because it grows like a weed, it''s not a great idea to plant peppermint too close to other herbs or vegetables because it can easily crowd them out.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d18e6ff4-46b5-5fea-9a3b-633b7a544cfb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd18e6ff4-46b5-5fea-9a3b-633b7a544cfb'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call an aircraft with blades on top which turn around quickly to make it fly?', '5dc07c89-8753-5c45-b02a-2d71ea52fefb'::uuid, NULL, NULL, E'Helicopter', NULL, NULL),
  ('d192f30c-0cf9-5bd1-9936-1e6ba2eb80ec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd192f30c-0cf9-5bd1-9936-1e6ba2eb80ec'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '451770c4-a19a-5e36-ab96-b974f15b7b05'::uuid, NULL, NULL, E'Technological developments have changed the way we live.', NULL, NULL),
  ('d192fe12-b4ff-524b-a764-0640d5791072'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'd192fe12-b4ff-524b-a764-0640d5791072'::uuid, 1, NULL, TRUE, 0, NULL, E'Cooperation and Competition', E'Some people believe that cooperation is more important than competition. Discuss whether you think cooperation outweighs competition.', NULL, NULL, NULL, NULL, 200, 300),
  ('d19ace67-c602-5a3c-8fa9-009c8ee5f62c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd19ace67-c602-5a3c-8fa9-009c8ee5f62c'::uuid, 1, NULL, TRUE, 0, NULL, E'Extreme Heat', E'Extreme heat is a major public health threat, especially when it is unseasonable and where people are less acclimated to higher temperatures. Among the most vulnerable populations are the very young, the elderly, those with existing health conditions such as heart disease and those without access to air-conditioning. People who work outdoors are also particularly susceptible to heat illness and heat stroke.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d1a33bd6-0f8e-5596-a238-97b0d00629ea'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd1a33bd6-0f8e-5596-a238-97b0d00629ea'::uuid, 1, NULL, TRUE, 0, NULL, E'Modern Communication', NULL, '0536dcf5-7a42-57d6-aac4-1f9a618ea8d5'::uuid, NULL, E'Technology has revolutionized the way we communicate. The digital era has transformed our interaction dynamics, both positively and negatively. Technology has enabled instant connectivity. With social media and messaging apps, we can now stay in touch with friends and family across the globe in real-time. This immediate communication breaks down geographical barriers, fostering global connections. However, technology also brings challenges to interpersonal communication. The prevalence of digital communication often leads to misunderstandings due to the lack of non-verbal cues like tone and body language. Moreover, excessive reliance on digital communication can impact our ability to engage in face-to-face interactions effectively. In conclusion, while technology has greatly facilitated communication, it''s crucial to balance our digital interactions with meaningful, in-person conversations. As we navigate this digital age, let''s strive to maintain the essence of human connection.', NULL, NULL, NULL),
  ('d1a4697c-23e8-5446-ab05-9b62058ec8dc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'd1a4697c-23e8-5446-ab05-9b62058ec8dc'::uuid, 1, NULL, TRUE, 0, NULL, E'Movie Theater', E'A new movie theater is said to be built in your neighborhood. What are the advantages or disadvantages of this plan?', NULL, NULL, NULL, NULL, 200, 300),
  ('d1a511c9-8909-5cee-838d-26a44abd3d9d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'd1a511c9-8909-5cee-838d-26a44abd3d9d'::uuid, 1, NULL, TRUE, 0, NULL, E'Photogrammetry', NULL, NULL, NULL, NULL, E'1, 4, 2, 5, 3', NULL, NULL),
