  ('d1aa3613-045a-58e6-825b-bd3e8bdb7d12'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd1aa3613-045a-58e6-825b-bd3e8bdb7d12'::uuid, 1, NULL, TRUE, 0, NULL, E'Blood Sugar', E'Australian scientists say they have developed pain-free blood sugar testing for diabetics, a non-invasive strip that checks glucose levels via saliva for diabetics. Managing their blood sugar levels typically means pricking their fingers multiple times a day with a lancet and then placing a drop of blood on a testing strip.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d1adb8fa-b4ec-5616-be9b-7708c00b0536'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd1adb8fa-b4ec-5616-be9b-7708c00b0536'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '930c218e-5a7d-599b-a114-d695b5ec85db'::uuid, NULL, NULL, E'Specialized vocabulary with unique meanings within fields is termed jargon.', NULL, NULL),
  ('d1ae7e37-2d08-55f7-85b8-ba806ee51b3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd1ae7e37-2d08-55f7-85b8-ba806ee51b3c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '679b0f5d-79cc-5f10-a36d-a960721a5bf5'::uuid, NULL, NULL, E'Artists affiliated with conservative politics also play the role of critics.', NULL, NULL),
  ('d1b4f978-921e-5545-bbe0-8a218063b585'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd1b4f978-921e-5545-bbe0-8a218063b585'::uuid, 1, NULL, TRUE, 0, NULL, E'Rudman', E'Rudman looks at how a poor understanding of Maths has led historians to false conclusions about the Mathematical sophistication of early societies. Rudman''s final observation-that ancient Greece {{1}} unrivaled progress in the subject while {{2}} to teach it at school-leads to a {{3}} punchline:Mathematics could be better learnt after we {{4}} school.', NULL, NULL, NULL, E'1.enjoyed, 2.failing, 3.radical, 4.leave', NULL, NULL),
  ('d1b56260-67a1-58b3-9e68-57cffa4daae7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd1b56260-67a1-58b3-9e68-57cffa4daae7'::uuid, 1, NULL, TRUE, 0, NULL, E'Repeated Syllables', E'Assessments of language learning in 18-month-olds suggest that children are better at grasping the names of objects with repeated syllables, over words with non-identical syllables. Researchers say the study may help explain {{1}} some words or phrases, such as ''train'' and ''good night'', have given rise to versions with repeated syllables, such as choo-choo and night-night. The researchers say such words are easier for infants to learn, and may provide them {{2}} a starter point for vocabulary learning. A team from the University of Edinburgh assessed the infants'' language learning behavior in a series of visual and attention tests {{3}} pictures on a computer screen of two unfamiliar objects. The two objects were named with made-up words which were {{4}} to the infants by a recorded voice - one with two identical syllables, for example neenee, and the other without repeated syllables, such as bolay. The infants were then tested for their recognition of {{5}} made-up word. Recordings of their eye movements showed they looked more reliably at the object labeled with repeated syllables, than the other object. Researchers validated their results with a control test, in which the infants responded to pictures of familiar objects - such as a dog or an apple.', NULL, NULL, NULL, E'1.why, 2.with, 3.using, 4.communicated, 5.each', NULL, NULL),
  ('d1b5ebca-723e-574b-8fde-6f181cf62422'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd1b5ebca-723e-574b-8fde-6f181cf62422'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '68dbb640-9168-58ea-b5a6-ad577ba43964'::uuid, NULL, E'This system has imposed additional financial burdens on many people.', NULL, NULL, NULL),
  ('d1b968ee-d0c1-53a9-b0e5-31290fbbfdcd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd1b968ee-d0c1-53a9-b0e5-31290fbbfdcd'::uuid, 1, NULL, TRUE, 0, NULL, E'Online Learning', E'Online learning has become increasingly popular in recent years, offering students the flexibility to pursue their education from anywhere with an internet connection. However, online learning also requires self-discipline and strong time management skills to stay on track and complete coursework on time. Additionally, online learning may not be the best fit for all students, as some may prefer the structure and social interaction of traditional classroom settings.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d1bba5e5-38e0-51af-91fd-2af5162a2a83'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd1bba5e5-38e0-51af-91fd-2af5162a2a83'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call people who write songs?', 'eb38a598-feb3-5a8d-8d7a-2271cfe5e7c8'::uuid, NULL, NULL, E'Songwriter / composer', NULL, NULL),
  ('d1bbbfda-dca5-5755-ba0e-9fb4e7227803'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'd1bbbfda-dca5-5755-ba0e-9fb4e7227803'::uuid, 1, NULL, TRUE, 0, NULL, E'Human Height', E'Genetics partially influences height, but other factors, such as nutrition, also affect how tall you become as an adult. The average height of a population can indicate the health of its people since things such as childhood illness and poor nutrition during pregnancy and childhood can stunt a person''s growth.\nAverage human height in countries such as the U.S., U.K., and Japan has leveled off at around 5 feet and 10 inches (1.8 meters) over the last few decades. However, height is still increasing in places such as Latin America. These increases are likely the result of better maternal health and nutrition and greater access to health care. The findings suggest that human height may have reached a limit or a convergence point called a biological asymptote under favorable conditions.\nStudies have examined the relationship between height and body mass index with socioeconomic status. An analysis of data from the UK Biobank published in 2016 found that lower socioeconomic status correlated with shorter stature and higher BMI, though such associations differed between the sexes.\nShorter height and lower socioeconomic status appeared to be more strongly linked for men, whereas the link between higher BMI and lower socioeconomic status was paramount for women. These findings imply that taller people, especially men, are associated with higher attainment in education, employment, and income levels. However, lower income levels are associated more closely with overweight people.', NULL, NULL, NULL, NULL, 5, 75),
  ('d1bc8169-a430-5ef7-9a7d-74c32d58567f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd1bc8169-a430-5ef7-9a7d-74c32d58567f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'fc59abdd-b116-58ee-bf0c-0ded532e5bb0'::uuid, NULL, E'Our support services include health and wellbeing and career guidance.', NULL, NULL, NULL),
