  ('d20ae6c9-237e-5955-8583-e8566972a306'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd20ae6c9-237e-5955-8583-e8566972a306'::uuid, 1, NULL, TRUE, 0, NULL, E'Men and Calories', E'Winter may be seen as the time to fill up with comfort food, but in fact, the sunny summer months are when men eat more calories – unlike women. The effect may {{1}} because sunlight makes the skin release an appetite-stimulating hormone called Ghrelin, says Carmit Levy at Tel Aviv University in Israel. Levy and her team noticed the unexpected effect in experiments in mice that investigated mechanisms behind skin cancer, in which male animals {{2}} to UV light ate more food. To see if humans do the same, the researchers used existing data on about 3000 people who had filled in detailed {{3}} questionnaires as part of the Israeli government’s regular national health and nutrition survey. Between March and September, men consumed about 17 per cent more calories per day than they did during the rest of the year, while women’s food {{4}} stayed about the same.', NULL, NULL, NULL, E'1.occur, 2.exposed, 3.dietary, 4.intake', NULL, NULL),
  ('d20fa4a4-3e82-5340-9124-9989ca28cde1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd20fa4a4-3e82-5340-9124-9989ca28cde1'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '11001b38-cb58-59b6-b372-30ab08df8595'::uuid, NULL, E'Before choosing your university course, you should consider your career.', NULL, NULL, NULL),
