  ('d2423ebb-1121-5989-b28d-25321ea15c66'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd2423ebb-1121-5989-b28d-25321ea15c66'::uuid, 1, NULL, TRUE, 0, NULL, E'Brain Cells', E'In a large, multi-institutional effort {{1}} by University of California San Diego, researchers have analyzed more than a million human brain cells to produce {{2}} maps of gene switches in brain cell types, and {{3}} the links between specific types of cells and various common neuropsychiatric disorders. The team also developed artificial intelligence tools to {{4}} the influence of individual high-risk gene variants among these cells and how they may {{5}} to disease.', NULL, NULL, NULL, E'1.led, 2.detailed, 3.revealed, 4.predict, 5.contribute', NULL, NULL),
  ('d2490c79-d06a-5733-9b0a-3f6c9bb094e8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd2490c79-d06a-5733-9b0a-3f6c9bb094e8'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '1f0fe75d-24cc-587c-bb30-2a08157728d8'::uuid, NULL, E'The atmosphere is composed of oxygen and nitrogen gases.', NULL, NULL, NULL),
  ('d24f3494-13e0-550c-a6e6-6aa7c1dd69b0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'd24f3494-13e0-550c-a6e6-6aa7c1dd69b0'::uuid, 1, NULL, TRUE, 0, NULL, E'Sports or Libray', E'Universities should give the same amount of money to their students’ sports activities as they give to their university libraries. Do you agree or disagree with the statement?', NULL, NULL, E'In recent years, there has been a growing debate on whether universities should allocate equal funding to sports activities and libraries. While libraries are essential for academic success, I believe that sports activities are equally important and should receive the same amount of funding. In this essay, I will outline the reasons why universities should invest in sports activities and the benefits they offer to students.\nFirstly, sports activities promote physical health and mental well-being, which are essential for students to excel academically. Engaging in sports activities can help students manage stress, improve sleep patterns, and enhance their overall health. Regular exercise has also been linked to improved cognitive function, memory retention, and academic performance. By investing in sports activities, universities can create a healthier and more productive learning environment for their students.\nSecondly, sports activities provide opportunities for students to develop leadership, teamwork, and communication skills. These skills are valuable in their future careers and can help them become well-rounded individuals. Participating in sports activities can also foster a sense of community and school spirit, creating a positive campus culture. By investing in sports activities, universities can help students develop important life skills and create a more vibrant campus community.\nIn conclusion, universities should allocate equal funding to sports activities and libraries. While libraries are essential for academic success, sports activities offer physical and mental health benefits, as well as opportunities for personal growth and skill development. By investing in sports activities, universities can create a more holistic learning environment that fosters academic success and personal growth.', NULL, 200, 300),
  ('d256ad44-5679-5410-9d57-912b5f22b25d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd256ad44-5679-5410-9d57-912b5f22b25d'::uuid, 1, NULL, TRUE, 0, NULL, E'Task-Centered Leadership', E'Task-centered styles of leadership focus on giving {{1}} and directions to group members to reach achievement and {{2}} goals more efficiently and effectively. The focus is on the {{3}} analysis of what needs done and the specific course of actions that should be taken to meet those needs. Employees are seen as resources to be used to accomplish the goals.', NULL, NULL, NULL, E'1.instructions, 2.accomplishment, 3.objective', NULL, NULL),
  ('d25939cf-afeb-583a-8632-b900f047b073'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'd25939cf-afeb-583a-8632-b900f047b073'::uuid, 1, NULL, TRUE, 0, NULL, E'Research Report', NULL, NULL, NULL, NULL, E'4, 2, 1, 5, 3', NULL, NULL),
  ('d25b0681-bfc6-56c1-9196-1d38537b8d54'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'd25b0681-bfc6-56c1-9196-1d38537b8d54'::uuid, 1, NULL, TRUE, 0, NULL, E'Sports', E'People should take part in sports either in individual or in teams, because people can learn many useful skills. How far do you agree? Explain and use examples or your own experience.', NULL, NULL, NULL, NULL, 200, 300),
  ('d260a571-9a8f-5641-993f-969ad4e5e4a2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd260a571-9a8f-5641-993f-969ad4e5e4a2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b91be35c-55ca-5746-b736-aadb2d9cecd2'::uuid, NULL, NULL, E'The large, wide table is not for sale.', NULL, NULL),
  ('d262747f-6f5e-5dde-8fcb-52ae266972ac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd262747f-6f5e-5dde-8fcb-52ae266972ac'::uuid, 1, NULL, TRUE, 0, NULL, E'Sam''s Cafe', E'You have a dinner date with a friend, and she wants to go to Sam''s Cafe which only serves sandwiches, coffee, tea, etc. You want to eat in another restaurant with a lot of food. What do you say to your friend?', '57965bea-3a71-5310-b322-92325cd78d8b'::uuid, NULL, E'Hey, I want to talk to you about something.\nWe seem to have a little issue with our dinner place.\nIt''s like you want to go to Sam''s Cafe that only sells sandwiches, coffee and tea, but I hope we can pick another restaurant with more kinds of food.\nAnd I''d like to know what you think.', NULL, NULL, NULL),
  ('d271176a-2906-5ef1-9c27-e8766ba8ad4e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd271176a-2906-5ef1-9c27-e8766ba8ad4e'::uuid, 1, NULL, TRUE, 0, NULL, E'Anticipation', E'The brain''s knack for anticipation is a marvel, similar to a chess player thinking several moves ahead. This ability isn''t just about reflexes or instincts but involves complex planning and prediction. For instance, before you even decide to {{1}} a ball, your brain has already mapped out the trajectory, your hand position, and the force needed. This foresight {{2}} beyond physical actions to emotional and cognitive realms, preparing you for conversations, problem-solving, and even bracing for potential stressors. It''s {{3}} the brain is perpetually drafting blueprints for multiple futures, selecting the most relevant one as the situation {{4}} . This foresight closely reflects the brain''s complexity, not just reacting to the present but continuously shaping the future.', NULL, NULL, NULL, E'1.catch, 2.extends, 3.as if, 4.unfolds', NULL, NULL),
  ('d27334a4-579e-5fcb-ac20-3af67136c60c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd27334a4-579e-5fcb-ac20-3af67136c60c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which part of a tree grows under the ground and absorbs nutrients and water from the soil?', '2b27b58c-4a95-5a24-a6ca-e7f5e55fe3b2'::uuid, NULL, NULL, E'Root', NULL, NULL),
  ('d2746336-27ec-599d-8a42-19a502963b0d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'd2746336-27ec-599d-8a42-19a502963b0d'::uuid, 1, NULL, TRUE, 0, NULL, E'Crusades', NULL, NULL, NULL, NULL, E'3, 1, 2, 4', NULL, NULL),
  ('d2748e05-ad78-5d85-81f4-ef09ee0c96a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', 'd2748e05-ad78-5d85-81f4-ef09ee0c96a6'::uuid, 1, NULL, TRUE, 0, NULL, E'MCM-R', E'Water for public supply can be obtained from underground sources by wells sunk into aquifers, or from surface sources, such as purpose-built reservoirs or lakes (collecting rainwater run-off or water from streams) and rivers. The safety of the water is of utmost concern - several million people die each year after consuming contaminated water. The primary aim in water treatment is the elimination of any pathogenic micro-organisms present. All the above-mentioned sources can be subject to pollution.\nIn the case of underground water, polluted surface water can enter the saturation zone of an aquifer and so lead to its contamination. Pollution can come from waste containing heavy metals and organic compounds. farm run-off containing pesticides. and industrial wastes which may have been deliberately dumped down old coal mine shafts. River water can be affected by farm drainage, sewage works and industrial effluents. and also the run-off water from roads. Thus there is a need to maintain the quality of the aquatic environment to ensure that the water is suitable for treatment for public supply. and that the cost of treatment is kept as low as possible.\nRaw water is usually abstracted from a river and pumped to a reservoir for storage and settlement. In the reservoir. the number of bacteria is reduced through natural processes, such as ultraviolet radiation from sunlight. Also. a large portion of the suspended solids settles out. The water is then conveyed from the reservoir to a treatment works.\n\nWhich of the following statements are true according to the information in the passage?', NULL, NULL, NULL, E'Industrial pollution can affect both underground and river water.\nThere are numerous means by which water can become impure.', NULL, NULL),
  ('d2775e5e-cfb5-5d28-a2a9-39d407ee804e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'd2775e5e-cfb5-5d28-a2a9-39d407ee804e'::uuid, 1, NULL, TRUE, 0, NULL, E'Livestock Farming', NULL, NULL, NULL, NULL, E'1, 4, 3, 2', NULL, NULL),
  ('d27e02c0-ae0f-529d-a76f-d923da41c68e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd27e02c0-ae0f-529d-a76f-d923da41c68e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '611c25a5-50d2-5bba-b07d-2b457a89777b'::uuid, NULL, E'Parents try to influence their children by using toys and other incentives.', NULL, NULL, NULL),
  ('d27f057b-e052-5ff6-aab5-de8e9bcbf045'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd27f057b-e052-5ff6-aab5-de8e9bcbf045'::uuid, 1, NULL, TRUE, 0, NULL, E'Washing Machine', E'Programs, such as delicate wash or color wash, are one of the features of washing machines, particularly fully-automatic washing machines, which gives you the choice when it comes to how you want to wash your clothes. If you’re washing with a certain fabric, then programs help you find the optimal washing conditions for your laundry needs from selecting the right wash temperature to setting up your washing timing.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d27f52a2-72ae-5281-8b6a-8e55015a69aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd27f52a2-72ae-5281-8b6a-8e55015a69aa'::uuid, 1, NULL, TRUE, 0, NULL, E'Interconnected World', E'In our fast-paced, interconnected world, the importance of cultural understanding and empathy cannot be overstated. As societies become increasingly diverse, the ability to appreciate and respect different cultures is an essential skill. It {{1}} harmonious coexistence, reduces prejudice, and promotes global cooperation. One way to foster cultural understanding is through education. Schools and universities have a pivotal role in promoting multiculturalism and teaching students to value diversity. Exposure to different cultures, languages, and traditions can broaden young minds and instill a sense of {{2}} . Furthermore, cultural exchange programs and international collaborations can create opportunities for individuals to engage with people from diverse backgrounds. These experiences can challenge stereotypes and deepen one''s {{3}} of the world. In today''s interconnected world, cultural understanding is not only a personal virtue but also a key factor in addressing global challenges such as conflict resolution, diplomacy, and social cohesion. It is a bridge that connects people across borders, fostering a more inclusive and {{4}} world.', NULL, NULL, NULL, E'1.fosters, 2.curiosity, 3.appreciation, 4.interconnected', NULL, NULL),
  ('d2815240-4d33-5198-becb-b40bcbce8500'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd2815240-4d33-5198-becb-b40bcbce8500'::uuid, 1, NULL, TRUE, 0, NULL, E'Our Brains', E'When we engage in social interactions, like shaking hands or having a conversation, our observation of other people''s actions is crucial. But what exactly happens in our brain during this process: how do the different brain regions talk to each other? Researchers provide an intriguing answer: our perception of what others do depends more on what we expect to happen than previously believed.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d28237bf-e21b-5c1f-a6b5-820fd138259c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd28237bf-e21b-5c1f-a6b5-820fd138259c'::uuid, 1, NULL, TRUE, 0, NULL, E'Public Opinion', E'Public opinion stabilizes and integrates society because conflicts will be resolved through spirals of silence in favor of one opinion. Wherever people live together in societies, public opinion will function as a mechanism of social control. However, what specifically public opinion approves or rejects will change with time and differ from place to place.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d2842f21-2c1d-53a3-b19e-e35c864c139e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd2842f21-2c1d-53a3-b19e-e35c864c139e'::uuid, 1, NULL, TRUE, 0, NULL, E'Language Learning', E'When it {{1}} to the magical world of language learning in toddlers, you''d be surprised at the tricks up their tiny {{2}} . It {{3}} out, 18-month-olds have a knack for latching onto words with a bit of repetition. Researchers have been peering into the minds of these linguistic geniuses and found that names with repeated {{4}} , like "choo-choo" or "ma-ma", are easier for these pint-sized scholars to {{5}} up.', NULL, NULL, NULL, E'1.comes, 2.sleeves, 3.turns, 4.syllables, 5.pick', NULL, NULL),
  ('d287f28d-0c50-5561-8b32-fe10daa0248e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd287f28d-0c50-5561-8b32-fe10daa0248e'::uuid, 1, NULL, TRUE, 0, NULL, E'Fine Arts Department', E'At the Fine Arts Department, we place dual emphasis on studio art and art history, and are dedicated to the exploration of contemporary art while promoting traditional Chinese art and culture. Our department has been a strategic base for training up artists and art historians, and has made significant contribution to the field of art nationally and internationally.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d2881689-4e39-5cb4-8ee8-cf51adb5170b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd2881689-4e39-5cb4-8ee8-cf51adb5170b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person who gives lectures in a school?', 'd6b4852a-9019-5940-a611-d8d3696a9c02'::uuid, NULL, NULL, E'Teacher / teachers / professor / professors / lecturer / lecturers', NULL, NULL),
