  ('d302ff70-9654-5fdd-b759-e72bf3ae5056'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd302ff70-9654-5fdd-b759-e72bf3ae5056'::uuid, 1, NULL, TRUE, 0, NULL, E'MAROON-X Instrument', E'Using the MAROON-X instrument on the Gemini-North Telescope, the team was able to identify and measure the abundance of 11 chemical elements in the atmosphere of the planet. Those include rock-forming elements whose abundances are not even known for giant planets in the Solar System such as Jupiter or Saturn.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d30bd497-60ae-590d-afaf-20c694b2940b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd30bd497-60ae-590d-afaf-20c694b2940b'::uuid, 1, NULL, TRUE, 0, NULL, E'Restaurant Location', E'The physical location of a restaurant in the competitive landscape of the city has long been known as a major factor in its likely success or failure. Once restaurants are established in such environments they can do little about their location. All they can do is work to improve customer access to their premises.', NULL, NULL, NULL, NULL, NULL, NULL),
