  ('d35685d7-96e1-594f-8231-f07c2d1f3c04'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd35685d7-96e1-594f-8231-f07c2d1f3c04'::uuid, 1, NULL, TRUE, 0, NULL, E'Greenhouse Gas Emissions', E'As the world strives to cut greenhouse gas emissions and find sustainable transportation solutions, University of Houston energy researchers suggest that hydrogen fuel can potentially be a cost-competitive and environmentally friendly alternative to traditional liquid fuels, and that supplying hydrogen for transportation in the greater Houston area can be profitable today.', NULL, NULL, NULL, NULL, NULL, NULL),
