  ('d3c1082d-b34b-5c94-815a-923e3e6e266c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd3c1082d-b34b-5c94-815a-923e3e6e266c'::uuid, 1, NULL, TRUE, 0, NULL, E'Trackway', E'A fossilized trackway on public lands in Lake County, Oregon, may reveal {{1}} about the ancient family dynamics of Columbian mammoths. Recently excavated by a {{2}} from the University of Oregon Museum of Natural and Cultural History, the Bureau of Land Management and the University of Louisiana, the trackway includes 117 footprints thought to represent a number of {{3}} as well as juvenile and infant mammoths.', NULL, NULL, NULL, E'1.clues, 2.team, 3.adults', NULL, NULL),
