  ('d3cb9ac0-e102-5584-a0fd-edef10fd888b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd3cb9ac0-e102-5584-a0fd-edef10fd888b'::uuid, 1, NULL, TRUE, 0, NULL, E'Opening of Parliament', E'The ritual of the state opening of parliament still illustrates the basis of the British constitution. The sovereignty of the Royal Family has passed to the sovereignty of parliament, leaving the monarchy with the trappings of power, while prime ministers are still denied the kind of status that is given to American and French presidents.', NULL, NULL, NULL, NULL, NULL, NULL),
