  ('d456620b-f09f-5a9d-93f2-e491a64b4728'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd456620b-f09f-5a9d-93f2-e491a64b4728'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '024af99f-5048-5c67-a196-c8cddb6208ee'::uuid, NULL, E'Mary has nobody to talk with, but she doesn’t feel lonely.', NULL, NULL, NULL),
  ('d45a910d-fa47-56fb-a4b0-c482e03b0440'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd45a910d-fa47-56fb-a4b0-c482e03b0440'::uuid, 1, NULL, TRUE, 0, NULL, E'Globalization', E'Protestors see globalization in a different light than the Treasury Secretary of the United States. The differences in {{1}} are so great that one wonders, are the protestors and the policy makers talking about the same {{2}} ? Are the visions of those in {{3}} clouded by special and particular {{4}} ? What is this topic of globalization that has been subject, at the same time, to such vilification and such praise? Fundamentally, it is the closer integration of the countries and the peoples of the world which has been {{5}} about by the enormous reduction in the costs of transportation and communication, and the breaking down of the {{6}} barriers to the flow of goods, services, capital, knowledge, and, to a lesser extent, people across borders.', NULL, NULL, NULL, E'1.views, 2.phenomenon, 3.power, 4.interests, 5.brought, 6.artificial', NULL, NULL),
  ('d46a4a54-57f8-5b70-bb58-dd57237a0dd6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd46a4a54-57f8-5b70-bb58-dd57237a0dd6'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a professional who provides expert advice in a particular field?', 'b574eb12-cc99-52d7-846d-07d305b82d4d'::uuid, NULL, NULL, E'Consultant', NULL, NULL),
