  ('d4d52139-100d-5ec2-8415-5dddae2d03b6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd4d52139-100d-5ec2-8415-5dddae2d03b6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '647ccfc6-5553-5277-ab8c-d178a4ab0515'::uuid, NULL, E'You are late for the appointment, please reschedule.', NULL, NULL, NULL),
