  ('d4dce22e-4347-551e-96c3-5f38780a48c3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd4dce22e-4347-551e-96c3-5f38780a48c3'::uuid, 1, NULL, TRUE, 0, NULL, E'Major Layoffs', E'As of Friday, Musk and Twitter had given no public notice of the coming layoffs, according to a spokesperson for California’s Employment Development Department. That’s even though the Worker Adjustment and Retraining Notification statute requires employers with at least 100 workers to disclose layoffs involving 500 or more employees, regardless of whether a company is publicly traded or privately held.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d4df0837-586d-5317-a3c2-215cffc64b65'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd4df0837-586d-5317-a3c2-215cffc64b65'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b7908627-d1e5-5086-9a04-a87de65a9406'::uuid, NULL, NULL, E'Proper nutrition is vital for overall health and maintaining energy.', NULL, NULL),
  ('d4dfc34d-36e1-55c6-b167-fbd0320a58be'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd4dfc34d-36e1-55c6-b167-fbd0320a58be'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '665c2f02-d0e5-59cc-b83e-ec8edd073e46'::uuid, NULL, E'There were more than half students who didn''t come to the lecture.', NULL, NULL, NULL),
  ('d4e2aea6-2771-572f-a84f-5cfa35a34b3a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd4e2aea6-2771-572f-a84f-5cfa35a34b3a'::uuid, 1, NULL, TRUE, 0, NULL, E'Volcano Behaviors', E'There were various explanations for volcano behavior before the structure of the earth mantle as a semisolid material was developed. For decades, awareness that compression and radioactive materials may be heat sources was discounted and volcanic action was often attributed to chemical reactions and a thin layer of molten rock near the surface.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d4e3cd12-bf4b-5c46-853f-442b64127f27'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd4e3cd12-bf4b-5c46-853f-442b64127f27'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '166fae29-450d-55c5-b284-9dd502fbafc2'::uuid, NULL, E'The lecture on child psychology has been rescheduled to this Friday.', NULL, NULL, NULL),
  ('d4f31323-0268-54f6-ae34-c7bd5f7d6801'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd4f31323-0268-54f6-ae34-c7bd5f7d6801'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the process by which sweat glands in the skin secrete a saline solution?', '3746ba8a-87d8-551d-95b4-7583be1db21e'::uuid, NULL, NULL, E'Perspiration / sweating', NULL, NULL),
  ('d4fb75c5-71ab-542b-a305-87cabb650853'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd4fb75c5-71ab-542b-a305-87cabb650853'::uuid, 1, NULL, TRUE, 0, NULL, E'Planet Nine', E'Astronomers think planets can exist in orbits far from their star, and propose a two-step process: interactions with the star or inner planets kick it out of the inner system, and then a passing star stabilizes the orbit to keep it bound. This scenario could explain the hypothesized ''Planet Nine'' in our solar system. Astronomers have confirmed that one binary star system has a planet in a bound, highly eccentric orbit.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d4fc907e-40cf-578e-a9e1-e26236f48c04'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd4fc907e-40cf-578e-a9e1-e26236f48c04'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4011f81e-fa08-5030-b8c6-136d53b3d424'::uuid, NULL, E'Knowledge becomes a vital role in young generations.', NULL, NULL, NULL),
  ('d4fef24c-7a72-5122-85bc-c15fb3f3e928'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd4fef24c-7a72-5122-85bc-c15fb3f3e928'::uuid, 1, NULL, TRUE, 0, NULL, E'Greek Mythology', NULL, 'b7bfe147-1fb0-514c-b737-8ebbf21e8c99'::uuid, NULL, E'I''m going to explore the enduring influence of Greek mythology in modern culture. These ancient myths, more than just old tales, continue to shape our art, literature, and even our understanding of the world. Greek mythology, a rich tapestry of gods, heroes, and monsters, has been a source of inspiration for centuries. Its themes of heroism, adventure, and the human condition resonate deeply, influencing countless works of literature and art. For example, the epic tales of Hercules and Odysseus have been retold in numerous forms, from classical paintings to modern movies. Moreover, Greek mythology extends its influence beyond the arts. It has shaped modern language, with many English words and expressions originating from these ancient stories. Additionally, these myths have provided a framework for understanding human psychology, notably through the work of Freud and Jung, who often used mythological figures to explain complex psychological concepts. In conclusion, the impact of Greek mythology is not confined to the past; it is a living, breathing part of modern culture. Its timeless stories and characters continue to inspire, entertain, and enlighten us, proving that these ancient tales are as relevant today as they were millennia ago.', NULL, NULL, NULL),
  ('d4ffade7-a55d-5847-8a88-56fe8664a97d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd4ffade7-a55d-5847-8a88-56fe8664a97d'::uuid, 1, NULL, TRUE, 0, NULL, E'Teen Writing', E'Teens write for a variety of reasons—as part of a school assignment, to {{1}} a good grade, to stay in touch with friends, to share their artistic creations with others or simply to put their thoughts to paper (whether virtual or otherwise). In our focus groups, teens said they are motivated to write when they can {{2}} topics that are relevant to their lives and interests, and report greater enjoyment of school writing when they have the opportunity to write creatively. Having teachers or other adults who challenge them, {{3}} them with interesting curricula and give them detailed feedback also serves as a motivator for teens. Teens also {{4}} writing for an audience motivates them to write and write well.', NULL, NULL, NULL, E'1.get, 2.select, 3.present, 4.report', NULL, NULL),
  ('d4ffc654-e10b-5ca9-9864-7e8ef22b5cec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd4ffc654-e10b-5ca9-9864-7e8ef22b5cec'::uuid, 1, NULL, TRUE, 0, NULL, E'Arrest of President', E'A South Korean court ordered the arrest of Park Geun-hye, the former president, on charges of bribery and abuse of power. Ms Park, who was removed from office three weeks ago, will be jailed while prosecutors seek an indictment for her alleged role in a corruption scandal. The court said that if Ms Park was not taken into custody she might “destroy evidence”.', NULL, NULL, NULL, NULL, NULL, NULL),
