  ('d5111a9c-c927-58c3-af70-5957c4134e06'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd5111a9c-c927-58c3-af70-5957c4134e06'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which one deals with rules of language, grammar or literature?', 'baecea0a-68c2-53c0-9002-3c5c430fb609'::uuid, NULL, NULL, E'Grammar', NULL, NULL),
  ('d51c3e80-0775-5e86-a78b-3a1720238f64'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd51c3e80-0775-5e86-a78b-3a1720238f64'::uuid, 1, NULL, TRUE, 0, NULL, E'Roman Soldiers', E'Known for their discipline, organization, and superior training, the Roman soldiers were highly skilled and well-equipped. The army consisted of various specialized units, including infantry, cavalry, and auxiliary troops recruited from conquered territories. They employed innovative tactics such as the famous "testudo" formation and utilized advanced weaponry and siege engines.', NULL, NULL, NULL, NULL, NULL, NULL),
