  ('d52a0bc3-2705-5ff1-8161-0b6536a20279'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd52a0bc3-2705-5ff1-8161-0b6536a20279'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person who lives permanently?', '3b030f34-c8e4-54f2-8313-0e70b35f2a5e'::uuid, NULL, NULL, E'Immortal', NULL, NULL),
  ('d5337a7e-d06b-5c4a-8ab9-fc83cfbc940c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd5337a7e-d06b-5c4a-8ab9-fc83cfbc940c'::uuid, 1, NULL, TRUE, 0, NULL, E'High Levels of Anxiety', E'High levels of anxiety can {{1}} a person’s ability to control their attention, and this effect has been shown to increase with age, according to an analysis of dozens of studies. Ran Shi, then at the University of Sydney in Australia, and her colleagues combined the results of 58 studies that measured the attention and anxiety level of 8292 children and adults in total, who either self-reported their anxiety or {{2}} it through behavioral tests. These studies examined various components of attention control. These included inhibition, which involves preventing attention from being pulled towards irrelevant stimuli; switching, which involves keeping attention focused on a relevant task; and updating, which involves evaluating how relevant new information is and {{3}} old information. Across all studies, the researchers found that overall attention control was significantly worse in people who are more anxious. Highly anxious groups, whether or not they had been clinically diagnosed, had similar {{4}} in attention control.', NULL, NULL, NULL, E'1.strain, 2.demonstrated, 3.overwriting, 4.deficits', NULL, NULL),
  ('d53ea012-93cd-5743-a1e2-b430264635d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd53ea012-93cd-5743-a1e2-b430264635d7'::uuid, 1, NULL, TRUE, 0, NULL, E'Hyalinobatrachium', E'The Hyalinobatrachium yaku, known for its translucent skin {{1}} which its heart and internal organs can be seen, presents a stunning example of the wonders of natural adaptation. Researchers have been studying these glass frogs to understand their {{2}} camouflage techniques which protect them from {{3}} . These studies unveil the secrets of amphibian survival strategies in {{4}} rainforests and the intricate relationships between species and their {{5}} .', NULL, NULL, NULL, E'1.through, 2.unique, 3.predators, 4.dense, 5.habitats', NULL, NULL),
  ('d5421778-b109-5a8e-bf3f-8ab0f662d43a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd5421778-b109-5a8e-bf3f-8ab0f662d43a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c5e6f093-5ed6-5c69-ba16-bd1bcebf7c9d'::uuid, NULL, E'The French have acted swiftly and decisively to protect their industries.', NULL, NULL, NULL),
