  ('d58a04a0-5cdd-5bd1-8932-96e487af92e7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd58a04a0-5cdd-5bd1-8932-96e487af92e7'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do eyes produce while crying?', 'e1be6a69-aa75-5a22-96ee-96b1f74a8e21'::uuid, NULL, NULL, E'Tear / tears', NULL, NULL),
