  ('d596a0dd-d69c-5082-993a-33cef754427e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd596a0dd-d69c-5082-993a-33cef754427e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '860cbc11-dcdf-5914-8cca-ae8775b59723'::uuid, NULL, E'Prepare your PowerPoint presentation for the crucial team meeting tomorrow.', NULL, NULL, NULL),
  ('d5970b77-abff-5c74-ba5a-9b5780c84331'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd5970b77-abff-5c74-ba5a-9b5780c84331'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '47c92b9e-f5cc-5048-bc7d-eb98fb90834e'::uuid, NULL, NULL, E'You can use your laptops in the lecture.', NULL, NULL),
  ('d5971dbd-7e9e-5287-85ac-26e0b5f1f4f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd5971dbd-7e9e-5287-85ac-26e0b5f1f4f9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c2ec9d84-6d08-50a6-924b-0aa7c9e6ff9f'::uuid, NULL, E'Biographical information should be removed prior to the publication of the results.', NULL, NULL, NULL),
  ('d598e2c3-39ff-536b-aa9b-c423dce47be9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd598e2c3-39ff-536b-aa9b-c423dce47be9'::uuid, 1, NULL, TRUE, 0, NULL, E'Domesticated Creatures', E'The idea that a dog could seek help from a human does have a solid basis in science.\nIn what''s known as the "unsolvable task" experiment, a dog first learns how to open a puzzle box with a tasty treat inside. The puzzle is then secretly switched for another that''s impossible to solve. After becoming frustrated, dogs shift their attention away from the puzzle and onto a nearby human and then back to the puzzle. The dog attempts to shift the human''s attention to the puzzle as a request for help. Human infants do the same thing. Such efforts are called "referential communication."\nSo if dogs behave this way, you might expect the same from their close relatives: wolves. But when researchers tested wolves raised by humans, the animals just kept trying to solve the puzzle, never seeking help. Since the dogs and wolves were all raised the same way and by the same people, domestication must be responsible for the behavior.\n\nWhat can be inferred from this article?', '60993ec6-15d9-5fe1-88f5-4165c76931e9'::uuid, NULL, NULL, E'There is a scientific basis for dogs to turn to humans for help.\nBabies seek help when they are in trouble.', NULL, NULL),
  ('d599bf4d-4558-53a9-8a38-31f58ec7fdc8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd599bf4d-4558-53a9-8a38-31f58ec7fdc8'::uuid, 1, NULL, TRUE, 0, NULL, E'Carbon Prices', E'Carbon prices in the European Union have risen to their highest {{1}} in a decade this summer. This is {{2}} the EU has made some changes to its emissions trading system, which limits how much carbon dioxide different industries can emit. The EU has set a {{3}} of becoming carbon-neutral by 2050 and encourages more businesses to switch to cleaner energy {{4}} and reduce their greenhouse gas emissions.', NULL, NULL, NULL, E'1.level, 2.because, 3.target, 4.sources', NULL, NULL),
  ('d59ea72b-eceb-5b95-9351-a819f8344b30'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'd59ea72b-eceb-5b95-9351-a819f8344b30'::uuid, 1, NULL, TRUE, 0, NULL, E'Polar Bears', NULL, NULL, NULL, NULL, E'1, 3, 4, 2', NULL, NULL),
  ('d59ef2ae-2f2d-59cd-bc81-123d4bfa6039'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd59ef2ae-2f2d-59cd-bc81-123d4bfa6039'::uuid, 1, NULL, TRUE, 0, NULL, E'Nissan', E'Nissan will overhaul the inspection process for its Japan-destined vehicles for the first time in decades as the carmaker seeks to address a widening {{1}} scandal that has forced it to suspend production for the domestic market. The company said on Thursday that unauthorized workers had been {{2}} vehicles set for sale in the Japanese market, even after the company announced the recall of nearly 1.2m cars earlier this month over the same issue. With investors increasingly concerned about Japan Inc’s adherence to standards — concerns that were most recently {{3}} by the Kobe Steel data falsification scandal — the news pushed Nissan shares down 1.6 per cent on Friday, and also weighed on the prices of its suppliers. HirotoSaikawa, Nissan’s chief executive, pledged “drastic measures” to deal with the problem, namely the {{4}} of vehicle production for the home market at all six factories in Japan run by the company and its affiliate, Nissan Shatai.', NULL, NULL, NULL, E'1.inspection, 2.certifying, 3.inflamed, 4.suspension', NULL, NULL),
  ('d59f8c73-8912-56c8-a3ca-056c56ea026f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd59f8c73-8912-56c8-a3ca-056c56ea026f'::uuid, 1, NULL, TRUE, 0, NULL, E'Flight Canceled', E'You previously called the taxi driver and informed him that you were going to the airport, but now you have to change your destination to go home due to the flight cancel. You want to tell the driver where your home address is and how to get there. What should you say to the driver?', 'ac5e20d1-5608-5c24-8171-ba63a855aeb4'::uuid, NULL, E'Hey driver, I want to talk to you about something.\nWe seem to have a little issue with the destination.\nIt''s like I originally told you to head to the airport, but my flight got cancelled, so I need to change the destination to my home. I’ll tell you my home address and guide you on the way there.\nAnd I''d like to know what you think.', NULL, NULL, NULL),
  ('d5a3b1ac-d57c-54ff-8030-34fbc1a9daff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'd5a3b1ac-d57c-54ff-8030-34fbc1a9daff'::uuid, 1, NULL, TRUE, 0, NULL, E'Technology and Language', NULL, NULL, NULL, NULL, E'2, 4, 1, 3', NULL, NULL),
  ('d5a3b34f-1e76-54d8-9251-e907505a674d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd5a3b34f-1e76-54d8-9251-e907505a674d'::uuid, 1, NULL, TRUE, 0, NULL, E'Southern Cone', E'In the southern cone especially, from Venezuela to Argentina, the region is rising to overthrow the legacy of external domination of the past centuries and the cruel and destructive social forms that they have helped to establish. The {{1}} of imperial control — violence and economic warfare, hardly a distant memory in Latin America — are losing their effectiveness, a sign of the shift toward independence. Washington is now compelled to tolerate governments that in the past would have drawn intervention or reprisal. Throughout the region a vibrant {{2}} of popular movements provides the basis for a meaningful democracy. The indigenous populations, as if in a rediscovery of their pre-Columbian legacy, are much more active and influential, particularly in Bolivia and Ecuador. These developments are in part the result of a phenomenon that has been observed for some years in Latin America: As the elected governments become more formally democratic, citizens {{3}} an increasing disillusionment with democratic institutions. They have sought to construct democratic systems based on popular participation rather than elite and foreign {{4}} .', NULL, NULL, NULL, E'1.mechanisms, 2.array, 3.express, 4.domination', NULL, NULL),
  ('d5a3c621-c99e-5cd4-9a73-cb878e78c901'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd5a3c621-c99e-5cd4-9a73-cb878e78c901'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '16fd8ad1-f021-5ab5-a034-15da7e5634e2'::uuid, NULL, E'The quality of our accommodation is high, but it is still affordable for students.', NULL, NULL, NULL),
