  ('d5aa6418-a0a9-54ae-98df-053dcea8fd37'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd5aa6418-a0a9-54ae-98df-053dcea8fd37'::uuid, 1, NULL, TRUE, 0, NULL, E'Online Shopping Environments', E'Online shopping environments offer unique advantages that traditional brick-and-mortar stores cannot match. One of the most significant benefits is the ability to create highly interactive retail interfaces that can be customized to individual preferences. This level of personalization can enhance the shopping experience and improve customer satisfaction.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d5b341d1-ff6e-5a5f-bdae-b11ec0ca73ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd5b341d1-ff6e-5a5f-bdae-b11ec0ca73ee'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Who invented Arabic numerals?', '10b45fd6-9bbf-55c7-8fbc-24f17f5ec4a3'::uuid, NULL, NULL, E'Indians / Hindoos / Hindus', NULL, NULL),
  ('d5b52d2f-f4a8-5925-a103-4003f1755895'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd5b52d2f-f4a8-5925-a103-4003f1755895'::uuid, 1, NULL, TRUE, 0, NULL, E'Learner Experience', E'We seek to improve learner''s experience of education at college and help them to aspire, achieve and progress. We must embed equality and diversity in everything we do, both as a provider and an employer. We hope to prepare our students for work, higher education and citizenship by equipping our staff with the skills to meet this agenda.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d5b62441-ce62-55b4-aaf8-bae272c766fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd5b62441-ce62-55b4-aaf8-bae272c766fd'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for the study of fungi?', '2137755e-7568-5203-9065-48c9ebcadb14'::uuid, NULL, NULL, E'Mycology', NULL, NULL),
  ('d5baff63-a743-55b4-ae5e-d4ff03358a2d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd5baff63-a743-55b4-ae5e-d4ff03358a2d'::uuid, 1, NULL, TRUE, 0, NULL, E'Biodiversity Decline', E'Climate change and biodiversity decline are major challenges of our time. Both are predominantly caused by human activities, with profound consequences for people and the ecosystems on which we depend. Some actions we can undertake are beneficial in both areas, helping to mitigate and adapt to climate change as well as conserve and restore biodiversity.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d5bc0858-da30-5273-9603-2e8251f17fbe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd5bc0858-da30-5273-9603-2e8251f17fbe'::uuid, 1, NULL, TRUE, 0, NULL, E'Estee Lauder', E'She transformed beauty into big business by cultivating classy sales methods and giving away samples. Leonard Lauder, chief executive of the company his mother founded, says she always thought she ''was growing a nice little business.'' And that it is. A little business that {{1}} 45% of the cosmetics market in U.S. department stores. A little business that sells in 118 countries and last year grew to be $3.6 billion big in sales. The Lauder family''s shares are worth more than $6 billion. But early on, there wasn''t a burgeoning business; there weren''t houses in New York, Palm Beach, or the south of France. It is said that at one point there was one person to answer the telephones who {{2}} her voice to become the shipping or billing department as needed. You more or less know the Estee Lauder story because it'' s a chapter from the book of American business folklore. In short, Josephine Esther Mentzer, daughter of immigrants, lived above her father''s hardware store in Corona, a section of Queens in New York City. She started her {{3}} by selling skin creams concocted by her uncle, a chemist, in beauty shops, beach clubs and resorts. No doubt the potions were good - Estee Lauder was a quality fanatic - but the sales lady was better. Much better. And she simply outworked everyone else in the cosmetics industry. She {{4}} the bosses of New York City department stores until she got some counter space at Saks Fifth Avenue in 1948. And once in that space, she utilized a personal selling approach that proved as {{5}} as the promise of her skin regimens and perfumes.', NULL, NULL, NULL, E'1.controls, 2.changed, 3.enterprise, 4.stalked, 5.potent', NULL, NULL),
  ('d5c1c41e-0cac-5d77-b541-68575f43d448'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd5c1c41e-0cac-5d77-b541-68575f43d448'::uuid, 1, NULL, TRUE, 0, NULL, E'Sociological Thought', E'Written by ten eminent professors, it had been updated to reflect the shifts of sociological thought in the last five years, making it the most comprehensive, authoritative, and contemporary dictionary available. It was essential reading for all students and teachers of sociologies and other related courses, and also for the general reader.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d5c3c8e4-82ad-5cee-84d6-08f1c00dabfe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd5c3c8e4-82ad-5cee-84d6-08f1c00dabfe'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '44f3b64c-f43b-517e-a6f4-5a443d04e37d'::uuid, NULL, NULL, E'I thought it was through the small meeting room.', NULL, NULL),
  ('d5cca37e-9f46-5aec-90c8-6407e6650351'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd5cca37e-9f46-5aec-90c8-6407e6650351'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '95057ace-0e55-572d-9e94-1f681c8f23a5'::uuid, NULL, NULL, E'Active research engagement is a hallmark of the history department.', NULL, NULL),
  ('d5ce890a-3acb-5875-9517-66445fe73c48'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd5ce890a-3acb-5875-9517-66445fe73c48'::uuid, 1, NULL, TRUE, 0, NULL, E'Campus Resources', E'Campus resources like writing centers, tutoring services, and academic advisors can provide valuable support for students seeking to improve their academic performance and achieve their goals. These resources can help students develop the skills and strategies needed to succeed in college, such as effective writing techniques, time management strategies, and study skills.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d5df942b-e48e-5fc5-834a-b242ec739417'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd5df942b-e48e-5fc5-834a-b242ec739417'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bc9157e1-44e1-5331-a881-9f211fcf5a15'::uuid, NULL, E'She has a small business about toys.', NULL, NULL, NULL),
  ('d5e46e21-96d1-5287-a456-728b3b2f60c9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd5e46e21-96d1-5287-a456-728b3b2f60c9'::uuid, 1, NULL, TRUE, 0, NULL, E'Language Diversity', E'Despite a number of events in recent years devoted to language diversity, language endangerment, and multilingualism, such as the International Year of Languages, public awareness of the issues is still remarkably limited. Only one in four of the population know that half the languages of the world are so seriously endangered that they are unlikely to survive the present century.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d5e93637-c17c-5146-8013-7940ce50df6d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'd5e93637-c17c-5146-8013-7940ce50df6d'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-R', E'The transplantation of organs from one individual to another normally involves two major problems: (1) organ rejection is likely unless the transplantation antigens of both individuals are nearly identical, and (2) the introduction of any unmatched transplantation antigens induces the development by the recipient of donor-specific lymphocytes that will produce violent rejection of further transplantations from that donor. However, we have found that among many strains of rats these "normal" rules of transplantation are not obeyed by liver transplants. Not only are liver transplants never rejected, but they even induce a state of donor-specific unresponsiveness in which subsequent transplants of other organs, such as skin, from that donor are accepted permanently. Our hypothesis is that (1) many strains of rats simply cannot mount a sufficiently vigorous destructive immune-response (using lymphocytes) to outstrip the liver''s relatively great capacity to protect itself from immune-response damage and that (2) the systemic unresponsiveness observed is due to concentration of the recipient''s donor-specific lymphocytes at the site of the liver transplant.\n\nThe primary purpose of the passage is to treat the accepted generalizations about organ transplantation in which of the following ways?', NULL, NULL, NULL, E'Present findings that qualify them', NULL, NULL),
  ('d5eb2f03-b578-5c81-b801-a39cd1e03373'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd5eb2f03-b578-5c81-b801-a39cd1e03373'::uuid, 1, NULL, TRUE, 0, NULL, E'Intercultural Difficulties', E'"There are, of course, intercultural difficulties as well as language difficulties," he said. "There are, of course, also many Australian students who don''t speak such fantastically good English either.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d5ee7bd9-e013-5634-99f1-28a4b3f6e9be'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd5ee7bd9-e013-5634-99f1-28a4b3f6e9be'::uuid, 1, NULL, TRUE, 0, NULL, E'Ocean Conservation', NULL, '38dec6c2-8a14-5222-ba3c-1f26e8364aeb'::uuid, NULL, E'In today''s lecture, I would like to explore the interconnection between ecology and economics through the lens of ocean conservation. The health of our oceans is not just an ecological concern; it is intrinsically linked to the economic stability of communities worldwide. Sustainable fishing practices ensure the longevity of marine life, which in turn supports the livelihoods of millions who rely on the sea''s bounty. Moreover, marine ecosystems play a crucial role in regulating our climate. By protecting our oceans, we are investing in natural capital that offers returns in the form of climate resilience, which is essential for economic planning and development. As we venture into our various fields of study, let us remember that the principles of conservation and economics are not adversaries but allies. It is in this synergy that solutions for a prosperous and sustainable future lie.', NULL, NULL, NULL),
  ('d5f349ac-6632-584a-b858-9fc62170f6cc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd5f349ac-6632-584a-b858-9fc62170f6cc'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9dfffe02-9b02-5fd1-976c-f04a0f9cd23a'::uuid, NULL, NULL, E'We interviewed each individual member of this special community.', NULL, NULL),
  ('d5fe0f48-1f06-5020-94bf-b22a2981a531'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd5fe0f48-1f06-5020-94bf-b22a2981a531'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '1eecdaa0-9de6-57f2-b715-aa599ba69b69'::uuid, NULL, E'Rather unfortunately, ads sometimes give misleading information rather than informing.', NULL, NULL, NULL),
  ('d60a4734-b64f-533e-9ec9-93860152d6ff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd60a4734-b64f-533e-9ec9-93860152d6ff'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the job of someone that looks after your teeth and gums?', 'f74d4a86-6715-5098-8f24-d6dd29a6e571'::uuid, NULL, NULL, E'Dentist / surgeon dentist', NULL, NULL),
  ('d60cea56-9a81-59c3-892a-746aa4ad7bfb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd60cea56-9a81-59c3-892a-746aa4ad7bfb'::uuid, 1, NULL, TRUE, 0, NULL, E'Recycling', E'Recycling is a powerful tool for reducing waste and conserving resources. By recycling paper, plastic, glass, and metal, we can reduce the amount of waste sent to landfills and conserve natural resources. Recycling also saves energy and reduces greenhouse gas emissions. To maximize the benefits of recycling, we should strive to reduce our consumption of single-use products and prioritize the use of recycled materials.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d612da06-d1f1-50d3-81d0-c8f50cec61bf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'd612da06-d1f1-50d3-81d0-c8f50cec61bf'::uuid, 1, NULL, TRUE, 0, NULL, E'Lunar Eclipse', E'There are always headlines when a blood moon is coming, but they don''t always explain what a blood moon is — and how it differs from a lunar eclipse. A blood moon is the same thing as a total lunar eclipse (one of three types of lunar eclipses that can be seen from Earth). Whenever you read a news story about an upcoming blood moon — or see beautiful pictures of one that has just happened — the scientifically accurate term for what you''re seeing is a total lunar eclipse.\nTo help make more sense of the blood moon phenomena, it helps to understand how eclipses work. An eclipse occurs any time one celestial body (such as Earth or the moon) passes in between the sun and another celestial body and casts a shadow on that other object. In the case of a lunar eclipse, Earth passes between the sun and the moon and our shadow is cast onto the moon.\nHowever, it''s even more complex: There are two different parts to a shadow. There''s the penumbra, the partially shaded outer region of the shadow, and the umbra, the fully shaded inner region of a shadow. The penumbra is the lighter area that causes your shadow to appear fuzzy on the ground on a sunny day; the umbra is the darker area of your shadow.\nGiven all that, we can now make sense of the kind of lunar eclipse that creates a blood moon or a total lunar eclipse. When the moon passes completely into the Earth''s umbra, it is in our shadow and appears with a reddish tint.', NULL, NULL, NULL, NULL, 5, 75),
  ('d617106a-7f52-5d1e-98f8-100dd7e0c2cc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd617106a-7f52-5d1e-98f8-100dd7e0c2cc'::uuid, 1, NULL, TRUE, 0, NULL, E'Addressing Equipment Care', E'You are the captain of a community sports team and have provided team equipment for everyone''s use. After a few weeks, you notice that the equipment is often left outside, not stored properly, and some items are starting to show wear and tear much faster than expected. What would you say to your team?', '1b578b9e-883b-5233-bfe8-1df7f327dce0'::uuid, NULL, E'Hey team, I''ve noticed our equipment isn''t being put away properly and it''s wearing out faster than it should. It''s crucial we all pitch in to take care of what we share. Let''s make sure to store everything correctly after use and check for any damage. Maybe we can set up a quick equipment check at the end of practice? This way, we ensure everything lasts longer and is ready for us whenever we need it. Thanks for understanding and helping out.', NULL, NULL, NULL),
  ('d61b7161-589f-56d8-8192-5e3cc91bc15b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd61b7161-589f-56d8-8192-5e3cc91bc15b'::uuid, 1, NULL, TRUE, 0, NULL, E'Rescheduling Meeting', E'You need to change the meeting time with your colleague. How would you approach them to request a new time, and what key points should you cover, including suggesting alternative times, considering their availability, and ensuring the rescheduling is convenient for both parties?', '02f46e6e-61b2-5934-87ca-565606401632'::uuid, NULL, NULL, NULL, NULL, NULL),
  ('d6208907-ea64-5444-acb5-80e26da3072a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd6208907-ea64-5444-acb5-80e26da3072a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '20d12e72-e144-5243-b3c0-3c248e0fea89'::uuid, NULL, E'And they might only breathe twice an hour.', NULL, NULL, NULL),
  ('d6277c81-aa4c-5bbe-b417-e3a9e46b01a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd6277c81-aa4c-5bbe-b417-e3a9e46b01a6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e13229ae-b435-516e-833f-c3fe301725a7'::uuid, NULL, NULL, E'Successful applicants will work with a large team of researchers.', NULL, NULL),
  ('d62d7910-7869-5257-9f39-9128a0731cb9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd62d7910-7869-5257-9f39-9128a0731cb9'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What''s the name of the company that produce books and magazines?', '77fbe128-18d6-5cde-b9bd-366b8fe68075'::uuid, NULL, NULL, E'Publisher / publishing house / press', NULL, NULL),
  ('d633bb26-cf1f-51c7-892b-8a69a5ed233b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd633bb26-cf1f-51c7-892b-8a69a5ed233b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '33ea3907-2cd2-5643-9a0d-c215f32f1d9e'::uuid, NULL, E'Doctors are unanimous about the dangers of this drug.', NULL, NULL, NULL),
  ('d63612f3-dbb5-5ce8-9ff6-16a353fbcad0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'HIGHLIGHT_CORRECT_SUMMARY', E'HIGHLIGHT_CORRECT_SUMMARY', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd63612f3-dbb5-5ce8-9ff6-16a353fbcad0'::uuid, 1, NULL, TRUE, 0, NULL, E'Green Light', E'Did any of you notice those strange greenish colored lights in the sky last night? Anybody? Mark? I did, sir. They were beautiful. But what were they? We call them the northern lights. But they''re also called auroras there are two types of or as those in the northern hemisphere and those in the southern hemisphere, in the north, we call them the aurora borealis in the south. There the aurora Australia is or as appear as colorful streams of light in the sky in high, northern and southern latitudes. They frequently occur during the months before or after the equinox. The equinox happens in March and September. That''s when the planet is tilted, so that it''s neither pointed away from nor toward the sun. So, uh, why do auroras occur they are the result of reaction in the upper atmosphere. Solar winds hit the earth''s magnetic field. This may excite the oxygen and nitrogen atoms in the atmosphere. After some time, the atoms become relaxed. As they relax. The electrons in these atoms give off energy. This energy appears in the form of light. The color of the light depends on whether it comes from oxygen or nitrogen. In addition, the height in the atmosphere helps determine the colors that the light forms also. Um, just so, you know, oxygen usually emits a green or brownish red light. Nitrogen typically gives off a red or blue light. Most are or as are green in color.\n\nClick on the paragraph that best relates to the recording.', 'cd1cac25-06d4-5e52-9ccf-e4fff1305efa'::uuid, NULL, NULL, E'Auroras appear as colorful streams of light in the sky in high northern and southern latitudes. They are caused by three things: nitrogen atoms getting excited, solar winds in the Earth''s magnetic field, and electrons in oxygen atoms giving off energy.', NULL, NULL),
  ('d63830ce-2958-519d-a31d-cb11f8ad3b89'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd63830ce-2958-519d-a31d-cb11f8ad3b89'::uuid, 1, NULL, TRUE, 0, NULL, E'Landscape of Technology', E'In the ever-evolving landscape of technology, data has become the lifeblood of the digital age. With the proliferation of smartphones and the Internet of Things (IoT), we are generating {{1}} amounts of data every day. This data has the potential to revolutionize industries, inform decision-making, and improve our quality of life. However, it also raises concerns about privacy and {{2}} . The concept of data privacy is more important than ever. In the quest to collect and analyze data, companies and governments must strike a {{3}} between innovation and safeguarding individuals'' personal information. Data breaches and the misuse of data have become all too common, eroding public trust and highlighting the need for robust {{4}} measures. As we navigate this data-driven world, it is essential for individuals to understand their rights and take steps to protect their digital footprint. Meanwhile, policymakers and technology companies must work together to establish clear guidelines and regulations that ensure the responsible and ethical use of data.', NULL, NULL, NULL, E'1.massive, 2.security, 3.balance, 4.safeguarding', NULL, NULL),
  ('d63a650c-705c-5c38-9eaf-72d205617379'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'd63a650c-705c-5c38-9eaf-72d205617379'::uuid, 1, NULL, TRUE, 0, NULL, E'Famine', E'Famine is a widespread condition in which a large percentage of people in a country or region have little or no access to adequate food supplies. Many people believe that famines are food shortages caused solely by underproduction. However, in many cases, famine has multiple causes. A natural disaster, such as a long period of drought, flooding, extreme cold, typhoons, insect infestations, or plant disease, combined with government decisions on how to respond to the disaster, can result in a famine. The famine might be initiated by a natural disaster, and a government''s inability or unwillingness to deal with the consequences of that event may magnify the effects. This happened in North Korea in the 1990s when government mismanagement of food supplies and an inequitable rationing policy led to a famine that killed over two million people by some estimates. Human events also lead to famine. A major human cause of famine is warfare. During war, crops are destroyed, either intentionally or as a result of combat. In addition, supply lines and routes are cut off, and food cannot be distributed or is prevented from being distributed by combatants. Forced starvation for political reasons is another cause of famine. In the Soviet Union of the 1930s, for example, millions of peasants died as a result of leader Joseph Stalin’s agricultural policies, which required that a quota of grain be supplied to the government before any of the grain could be consumed by those who grew it. Anyone caught violating the policy could be executed.', NULL, NULL, NULL, NULL, 5, 75),
  ('d63c2cf3-4017-5f74-b879-617d7bd58ca5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd63c2cf3-4017-5f74-b879-617d7bd58ca5'::uuid, 1, NULL, TRUE, 0, NULL, E'Home Buying', E'In this guide, we discuss how to {{1}} the right neighborhood and home for you, and we demystify the purchasing and mortgage application process. Many prospective homeowners are at a {{2}} where they desire a change in lifestyle, but they''re uncertain about where they want to {{3}} . If you find yourself in this position, consider other factors: community culture, property style, location, and then choose a home that fits well with your life objectives. Having a detailed {{4}} isn''t necessary to begin the process.', NULL, NULL, NULL, E'1.pinpoint, 2.point, 3.settle, 4.plan', NULL, NULL),
  ('d64450cb-706f-572e-9d39-30799ad781ac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd64450cb-706f-572e-9d39-30799ad781ac'::uuid, 1, NULL, TRUE, 0, NULL, E'Negative Immigration', E'There is a tendency, especially in the popular press to concentrate on the negative effects of immigration. In that context, this lecture listing the benefits it brings to more developed nations is much more welcome. Also, it is delivered in a lively and amusing style.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d6451122-d833-5447-9144-f444ab82ce3e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd6451122-d833-5447-9144-f444ab82ce3e'::uuid, 1, NULL, TRUE, 0, NULL, E'Birding', E'In a time of stagnation and collective uncertainty, birding has given me the opportunity to get out of my head and commune with nature. While it has admittedly brought me some moments of frustration and disappointment, it''s also allowed me to experience just pure, unadulterated stoke. It''s provided moments of rapture and awe, surprise and delight - just looking at birds doing their thing in their natural habitats. It''s fun as hell. But what comes to mind when you picture a birder? For a lot of people, the prompt conjures up an image of a person in a khaki vest, maybe, with a pair of binoculars hanging around their neck. Whatever preconceived notions are coming up, I want you to set them aside because there are all kinds of birders. And there''s no right way to bird. All the tips in this episode or just that, tips. Take them or leave them depending on what you want your version of birding to be like.\n\nWhat is the speaker’s attitude expressed towards birding?', 'fcc9a55b-5e17-5a81-8020-62f72d5c041b'::uuid, NULL, NULL, E'There is no fixed way of birding.', NULL, NULL),
  ('d64c51b4-bcf1-573a-84f9-d0f037310d3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd64c51b4-bcf1-573a-84f9-d0f037310d3c'::uuid, 1, NULL, TRUE, 0, NULL, E'PIE', E'No matter whether you speak English or Urdu, Waloon or Waziri, Portuguese or Persian, the roots of your language are the same. Proto-Indo-European (PIE) is the mother tongue — shared by several hundred contemporary languages, as well as many now extinct, and spoken by people {{1}} lived from about 6,000 to 3,500 BC on the steppes to the north of the Caspian Sea. They left no written texts and {{2}} historical linguists have, since the 19th century, painstakingly reconstructed the language from daughter languages, the question of how it actually sounded was assumed to be permanently out of reach. Now, researchers at the Universities of Cambridge and Oxford have developed a sound-based method to move back through the family tree of languages that stem from PIE. They can simulate how certain words {{3}} when they were spoken 8,000 years ago. Remarkably, at the {{4}} of the technology is the statistics of shape. ''Sounds have shape,'' explains Professor John Aston, from Cambridge''s Statistical Laboratory. ''As a word is uttered it vibrates air, and the shape of this soundwave can be measured and turned into a series of numbers. Once we have these stats, and the stats of another spoken word, we can start asking how similar they are and what it would take to shift from one to another.''', NULL, NULL, NULL, E'1.who, 2.although, 3.would have sounded, 4.heart', NULL, NULL),
  ('d655da19-c0ab-5db5-a81c-992171a2dac8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd655da19-c0ab-5db5-a81c-992171a2dac8'::uuid, 1, NULL, TRUE, 0, NULL, E'Cotton', E'Just about everyone on the planet wears at least one article of clothing made from cotton at some point during the day, inevitably. By-products of the plant show up as well in something that person is doing. The source of cotton''s power is its nearly terrifying versatility and the durable creature comforts it provides.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d6571ed4-23ed-593b-8631-c000854a40f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd6571ed4-23ed-593b-8631-c000854a40f0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9d7baa02-81e5-56f7-ad64-e826218d6c48'::uuid, NULL, E'The patients were observed over a period of several months.', NULL, NULL, NULL),
  ('d6598039-f014-58e4-b800-d92660c0b826'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'd6598039-f014-58e4-b800-d92660c0b826'::uuid, 1, NULL, TRUE, 0, NULL, E'Animal Testing', E'Do you believe that animal testing is necessary for scientific advancement?', NULL, NULL, E'Animal testing is deemed essential for scientific progress as it has been instrumental in the development of life-saving medications and medical treatments. It serves as a crucial step in testing the efficacy and safety of new drugs and treatments before human trials, leading to significant advancements in healthcare and the treatment of various illnesses.\nAnimal testing has played a crucial role in the development of life-saving medications and medical treatments. Through animal research, scientists have been able to test the efficacy and safety of new drugs and treatments before human trials. This process has led to the discovery of vital treatments for various diseases, ultimately saving countless lives and improving healthcare outcomes.\nFurthermore, animal testing is essential for ensuring the safety of products like cosmetics and pharmaceuticals before human use. By subjecting these products to rigorous testing on animals, researchers can assess potential risks and side effects, ensuring that products are safe for human consumption or application. This process helps protect consumers from harmful substances and ensures product safety standards are met.\nIn conclusion, animal research provides valuable insights into biological processes and diseases that are crucial for scientific advancement. While ethical concerns exist, the contributions of animal testing to medical progress cannot be overlooked. The development of life-saving medications, the assurance of product safety, and the understanding of complex biological mechanisms are all made possible through animal testing, highlighting its necessity for scientific advancement.', NULL, 200, 300),
  ('d65a4b7b-fba5-5ccb-9820-a6c7928d7953'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd65a4b7b-fba5-5ccb-9820-a6c7928d7953'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'eb7346de-85d9-5e76-9f05-a9e527d8297c'::uuid, NULL, NULL, E'Campus life offers diverse activities for students to explore and enjoy.', NULL, NULL),
  ('d65b5691-321f-5349-9e69-0b7fa0b5a5ff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd65b5691-321f-5349-9e69-0b7fa0b5a5ff'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd00edf77-2f37-528f-84a6-caf2403dea6d'::uuid, NULL, NULL, E'Career advisors give tips on how to do well in job talks.', NULL, NULL),
  ('d65c99bc-c931-5fd6-b5a2-6b68c31e92af'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd65c99bc-c931-5fd6-b5a2-6b68c31e92af'::uuid, 1, NULL, TRUE, 0, NULL, E'Bamboo', E'Bamboo is a favoured plant among architects and designers because of its incredible strength and durability. One Colombian architect {{1}} to it as nature''s steel, but in many respects it is even better than steel: it is lighter and more flexible, and these {{2}} make it the ideal building material in areas that suffer earthquakes and severe weather patterns. Construction workers in places such as Hong Kong rely on bamboo scaffolding whatever the {{3}} of the tower block they may be working on: over a billion people around the world live in a home that is made of bamboo; and China {{4}} the plant for thousands of years. The only drawback to this remarkable product is the cost of transporting it. So for those {{5}} live in cooler regions of the world, the enormous advantages of this natural building material are less accessible.', NULL, NULL, NULL, E'1.refers, 2.qualities, 3.height, 4.has cultivated, 5.who', NULL, NULL),
  ('d6614034-f6a6-5752-9d17-93477280d44c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd6614034-f6a6-5752-9d17-93477280d44c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '85c69ee3-3878-50a4-a12f-14b5c778b11b'::uuid, NULL, E'You will get a broad foundation in the technology of machine systems.', NULL, NULL, NULL),
  ('d665bc2d-e021-57d7-914b-c2731a76b293'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd665bc2d-e021-57d7-914b-c2731a76b293'::uuid, 1, NULL, TRUE, 0, NULL, E'Managing Performance', E'Managing performance is about getting people into action so that they achieve planned and agreed results. It focuses on what {{1}} to be done, how it should be done and what is to be achieved. But it is equally concerned with {{2}} people - helping them to learn - and providing them with the support they need to do well, now and in the future. The framework for performance management is provided by the performance agreement, {{3}} is the outcome of performance planning. The agreement provides the basis for managing performance throughout the year and for {{4}} improvement and development activities. It is used as a reference point {{5}} reviewing performance and the achievement of improvement and development plans.', NULL, NULL, NULL, E'1.is, 2.developing, 3.which, 4.guiding, 5.when', NULL, NULL),
  ('d6694378-64b6-542d-b08a-8afddf2d4f8f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd6694378-64b6-542d-b08a-8afddf2d4f8f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the opposite word of subtraction in mathematics?', 'ba848203-9b15-56e3-a64a-3f148baf796b'::uuid, NULL, NULL, E'Addition', NULL, NULL),
  ('d66e6fae-1836-5c8e-88ca-c97e9366acbb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd66e6fae-1836-5c8e-88ca-c97e9366acbb'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the event in which people move through a public place to celebrate an important day or event?', '4278a8bd-1814-5be3-b62b-481399f48821'::uuid, NULL, NULL, E'Parade', NULL, NULL),
