  ('d677b762-fd5d-54cf-9da0-6a1d571685f2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd677b762-fd5d-54cf-9da0-6a1d571685f2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '52bf3893-071e-5074-9091-ede2c3f5cf3e'::uuid, NULL, NULL, E'There is no proof that the document is authentic.', NULL, NULL),
  ('d67cb800-36a9-5457-b19a-c4e947e0214c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd67cb800-36a9-5457-b19a-c4e947e0214c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the fruit with hairy shells and milky juice inside?', '86b6c06a-88fa-53c9-8609-cdb9b7fd790b'::uuid, NULL, NULL, E'Coconut', NULL, NULL),
  ('d67ebd90-ffe3-5c94-8fee-eb4d66343224'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'd67ebd90-ffe3-5c94-8fee-eb4d66343224'::uuid, 1, NULL, TRUE, 0, NULL, E'Explicatory Essay', E'“Explication” means to explain the work of an item of literature. An explication, or “explicatory” essay is used to explain and interpret a piece of literature such as a poem, a play, a novel, or a short story. It often examines sentences, verses, or passages extracted from longer literary works. Like all other types of essays, however, it also needs a clear thesis around which body parts focus, ending on a conclusion. The text is cited at different places to support the main claim and move the argument forward.\n\nAccording to the text, which statement below is true about explicatory essay?', NULL, NULL, NULL, E'A definite thesis is necessary for explicatory essay.', NULL, NULL),
  ('d68836bf-496d-5451-90a0-3b34877242d4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'd68836bf-496d-5451-90a0-3b34877242d4'::uuid, 1, NULL, TRUE, 0, NULL, E'Correct Information', E'Many believe that many kinds of media simultaneously communicating to people help people get correct information. Do you agree with it?', NULL, NULL, NULL, NULL, 200, 300),
  ('d68ed305-6e77-5f8c-8a1a-13988e34fa9d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'd68ed305-6e77-5f8c-8a1a-13988e34fa9d'::uuid, 1, NULL, TRUE, 0, NULL, E'Cup Handle', NULL, NULL, NULL, NULL, E'1, 2, 3, 4', NULL, NULL),
  ('d6911dba-d9d7-506e-8a6c-6e7780188ca3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd6911dba-d9d7-506e-8a6c-6e7780188ca3'::uuid, 1, NULL, TRUE, 0, NULL, E'Cultural Ideas', E'People modify cultural ideas in their minds, and sometimes they pass on the modified versions. Inevitably, there are unintentional modifications as well, partly because of {{1}} error, and partly because inexplicit ideas are hard to {{2}} accurately: there is no way to download them directly from one brain to another like computer programs. And, {{3}} native speakers of a language will not give {{4}} definitions of every word. So it can be only rarely, if {{5}} , that two people hold precisely the same cultural idea in their minds. That is why, when the founder of a political or philosophical movement or a religion dies, or even before, schisms typically happen. The movement''s most devoted followers are often shocked to {{6}} that they disagree about what its doctrines really are.', NULL, NULL, NULL, E'1.straightforward, 2.convey, 3.even, 4.identical, 5.ever, 6.discover', NULL, NULL),
  ('d693963b-2e4c-5524-9375-159c51dab29d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd693963b-2e4c-5524-9375-159c51dab29d'::uuid, 1, NULL, TRUE, 0, NULL, E'Magic Bullet Theory', E'The magic bullet theory (also called the hypodermic needle theory) suggests that mass communication is like a gun firing bullets of information at a passive audience. “Communication was seen as a magic bullet that {{1}} ideas or feelings or knowledge or motivations almost automatically from one mind to another”. This theory has been largely discredited by academics because of its suggestion that all members of an audience interpret messages in the same way, and are largely {{2}} receptors of messages. This theory does not take into account intervening cultural and demographic {{3}} such as age, ethnicity, gender, personality, or education that cause us to react differently to the media messages we encounter. However, many people hold the assumption that media, like television news outlets, simply {{4}} information that doesn’t encourage audience engagement and critical thinking. Rather than give a story with an unbiased message, media news outlets present stories to audiences that are attractive to them. Those who believe reality television shows actually portray reality hold some assumptions of the magic bullet theory.', NULL, NULL, NULL, E'1.transferred, 2.passive, 3.variables, 4.release', NULL, NULL),
  ('d69ad39e-ab65-526b-ad98-9889ae667c0b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd69ad39e-ab65-526b-ad98-9889ae667c0b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for a doctor specializing in the treatment of skin disorders?', '1981ea45-b12c-5d27-aa99-c06869af07c3'::uuid, NULL, NULL, E'Dermatologist', NULL, NULL),
  ('d69b42d2-75e9-5185-a899-3938e2af2310'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'd69b42d2-75e9-5185-a899-3938e2af2310'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-R', E'Hydrogeology is a science dealing with the properties, distribution, and circulation of water on the surface of the land, in the soil and underlying rocks, and in the atmosphere. The hydrologic cycle, a major topic in this science, is the complete cycle of phenomena through which water passes, beginning as atmospheric water vapor, passing into liquid and solid form as precipitation, thence along and into the ground surface, and finally again returning to the form of atmospheric water vapor by means of evaporation and transpiration.The term ''geohydrology'' is sometimes erroneously used as a synonym for ''hydrogeology.'' Geohydrology is concerned with underground water. There are many formations that contain water but are not part of the hydrologic cycle because of geologic changes that have isolated them underground. These systems are properly termed geohydrologic but not hydrogeologic. Only when a system possesses natural or artificial boundaries that associate the water within it with the hydrologic cycle may the entire system properly be termed hydrogeologic.\n\nIt can be inferred that which of the following is most likely to be the subject of study by a geohydrologist?', NULL, NULL, NULL, E'The trapping of water in a sealed underground rock cavern through the action of an earthquake', NULL, NULL),
  ('d6aad0c6-08c0-5128-84f0-becb162bdf0b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd6aad0c6-08c0-5128-84f0-becb162bdf0b'::uuid, 1, NULL, TRUE, 0, NULL, E'Multi-languages', E'It is claimed, by neuroscientists among others, that speaking two or more languages increases cognitive abilities and in some way re-wires the brain, as it were, in a way that positively affects how the brain works. And it''s true that we tend to think of people who can speak two or more languages as being bright. Learning a language is, anyway, good mental exercise, not to mention its benefits in introducing you to other peoples and cultures. This is why all school curricula should include at least one compulsory language. Anyone who knows two languages will find thai, in certain circumstances, they compete for position, the vocabulary of one getting in the way of the other. Often bi- or multilingual people find one language more suitable for expressing certain kinds of thoughts or feelings.\nThere is another view on being bilingual, not from a neuroscientist, but from someone whose business involves words and language. Brought up in a bilingual home, speaking Greek and French, and also fluent in English, she is old enough to remember when her native language, Greek, was also in effect two languages. There was the formal, correct form, kathareuousa, which was taught and spoken in schools, written in newspapers and books, and so on, and the everyday demotic language you used with your friends. As for her view on bilingualism, she says that you end up with a split personality.\n\nAccording to the speaker, which of the following is true of people who speak two or more languages?', 'cc83c1f7-f3d1-5a8f-8c08-e749832ef621'::uuid, NULL, NULL, E'They are generally regarded as being clever.', NULL, NULL),
  ('d6afa51e-7309-57b8-8ec1-80c2818547df'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd6afa51e-7309-57b8-8ec1-80c2818547df'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2e1c640d-6f7e-54f8-9499-64708ae3ed47'::uuid, NULL, E'Have you talked to your parents about the problems you''re having?', NULL, NULL, NULL),
  ('d6b590ad-df14-516f-85c0-03d2ff300847'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd6b590ad-df14-516f-85c0-03d2ff300847'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which planet is known as the Red Planet?', '5def23a9-e779-548f-92ef-2e2bb9d43e50'::uuid, NULL, NULL, E'Mars', NULL, NULL),
  ('d6b84728-5f8b-5fe8-9027-5faa541e0766'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd6b84728-5f8b-5fe8-9027-5faa541e0766'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8fe86f38-5346-5eff-9dc7-3293e6b2f461'::uuid, NULL, NULL, E'I will now demonstrate how the reaction can be arrested by adding a dilute acid.', NULL, NULL),
  ('d6bce935-1403-5949-9a8f-c5cb93fa2157'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd6bce935-1403-5949-9a8f-c5cb93fa2157'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'eeb7ce23-8754-5acb-8613-8583434e54ca'::uuid, NULL, NULL, E'Students are advised to use multiple methods for this project.', NULL, NULL),
  ('d6beb062-4b1c-579e-9d32-874f990cdd1a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd6beb062-4b1c-579e-9d32-874f990cdd1a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ee285115-79c3-5215-98cb-c773704a5c5e'::uuid, NULL, E'Professionals in responsible roles require adequate sleep to maintain performance standards.', NULL, NULL, NULL),
  ('d6c0ea96-e7bc-5a48-9a75-993ff66cad2b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'd6c0ea96-e7bc-5a48-9a75-993ff66cad2b'::uuid, 1, NULL, TRUE, 0, NULL, E'Be healthy', E'Many people think that being healthy is a difficult task that involves lots of dieting and time at the gym, but that''s not actually true! By supporting your body and mind, making some simple tweaks to your routine, and setting small goals for yourself, you can be on the path toward living a healthier, happier life. Start a daily habit of making healthier choices when it comes to eating, relaxing, being active, and sleeping. Soon, you''ll start to see your healthy life taking shape!\n\nThe main purpose of the author is to ___', NULL, NULL, NULL, E'encourage people to live a healthy lifestyle.', NULL, NULL),
  ('d6c1c4f9-433a-5432-8be1-5d674891677b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'd6c1c4f9-433a-5432-8be1-5d674891677b'::uuid, 1, NULL, TRUE, 0, NULL, E'Solar System', NULL, NULL, NULL, NULL, E'3, 2, 4, 1', NULL, NULL),
  ('d6c48a03-db18-5812-8ce7-385cc6430811'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd6c48a03-db18-5812-8ce7-385cc6430811'::uuid, 1, NULL, TRUE, 0, NULL, E'Biology', E'Biology is subdivided into separate branches for convenience of study, though all the subdivisions are {{1}} by basic principles. Thus, while it is {{2}} to separate the study of plants (botany) from that of animals (zoology), and the study of the structure of organisms (morphology) from that of function (physiology), all living things share in common certain biological {{3}} : for example, various means of reproduction, cell division, and the transmission of genetic material.', NULL, NULL, NULL, E'1.interrelated, 2.custom, 3.phenomena', NULL, NULL),
  ('d6c6a528-7ac3-5212-8452-008f3e52f622'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd6c6a528-7ac3-5212-8452-008f3e52f622'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'fd1d73b0-41b7-5123-b5fe-0f3686ef008b'::uuid, NULL, NULL, E'You will learn how to rationally assess your own arguments.', NULL, NULL),
  ('d6cc55e5-d358-5a9b-aaec-648053255571'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd6cc55e5-d358-5a9b-aaec-648053255571'::uuid, 1, NULL, TRUE, 0, NULL, E'Microscopic Invaders', E'We all know about bacteria, viruses and microscopic protozoa. We can watch the way that these tiny agents move into our bodies and damage our organs. We have a growing understanding of how our body mounts defensive strategies that fight off these invaders, and have built some clever chemical that can help mount an assault on these bio-villains.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d6cea268-4af4-52e2-90ed-266bd9910b2b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd6cea268-4af4-52e2-90ed-266bd9910b2b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '92e0b42e-bad6-5032-a531-fa299821b389'::uuid, NULL, NULL, E'Challenges for local workers are often greater than for others.', NULL, NULL),
  ('d6d714e9-f86b-5800-b067-32c512d31cde'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd6d714e9-f86b-5800-b067-32c512d31cde'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c7a56db7-e300-578a-9ada-532f2e168600'::uuid, NULL, NULL, E'The library''s desk has a vast collection of historical books.', NULL, NULL),
  ('d6dabac4-587d-5312-bf7e-da355dd2363e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd6dabac4-587d-5312-bf7e-da355dd2363e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How to describe people who are the original, earliest known inhabitants of a region?', '5e86f833-f671-5403-815b-5480418693f6'::uuid, NULL, NULL, E'Indigenous', NULL, NULL),
  ('d6dfe4a3-a817-5635-9782-51762603b87f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd6dfe4a3-a817-5635-9782-51762603b87f'::uuid, 1, NULL, TRUE, 0, NULL, E'Drugs', E'When that happens, staff will help the person — {{1}} out and now a little stressed — fish their drugs out of the rubbish. On their way out, they might have a blood test, their first {{2}} check-up in years, or just a hot cup of Milo. "We enable people to inject in the centre because that''s what they do," the medical director, Nico Clark, tells Guardian Australia during a recent visit to the North Richmond Community Health Centre. "The majority are dependent on their {{3}} . The purpose is not to be a place that facilitates injection per se. The {{4}} is to keep people alive." The center is a response to a coroner’s report that noted the heroin-relate deaths in the area in 2016.', NULL, NULL, NULL, E'1.strung, 2.dental, 3.substances, 4.purpose', NULL, NULL),
  ('d6e4cb53-061b-5008-b76b-25979540ea60'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd6e4cb53-061b-5008-b76b-25979540ea60'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8376aa83-b86e-5d54-b6b9-4a3e8504e5d3'::uuid, NULL, E'Logbooks account for a small portion of the total grading points available.', NULL, NULL, NULL),
  ('d6e7e002-a5d6-5a8c-b47d-def5ffbd5d42'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd6e7e002-a5d6-5a8c-b47d-def5ffbd5d42'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3101c7b7-bfda-55a7-b92b-3c7160c90a28'::uuid, NULL, NULL, E'Your boss wants you to finish this report by Monday.', NULL, NULL),
  ('d6e85d15-f6f2-5a60-8843-63f055f2e14c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd6e85d15-f6f2-5a60-8843-63f055f2e14c'::uuid, 1, NULL, TRUE, 0, NULL, E'Weight Gain', E'Both men and women gained weight but when it came to race, black women had the most rapid weight gain, followed by white women and then black and white men.\nThe weight gain was just a few pounds—but even a slightly higher BMI is associated with weight-related health issues. Several reasons exist for the weight discrepancy between the single and married people. For example, married men and women may be less concerned about their body weight because they''re no longer actively seeking a mate. Plus, married people have a regular dining partner, possibly leading to more meals. On the single side, those who are widowed or have gone through a divorce may lose weight due to stress. So while this news may not be good for the smug marrieds, it may be welcomed by Bridget Jones. The single, and very weight-conscious, Jones may actually have had the easier path to staying thin than her married friends.\n\nWhy are married people more likely to gain weight?', 'e3c36fbd-4a76-5e95-807c-4a890dc6b617'::uuid, NULL, NULL, E'Because they have regular dining partners and probably have more meals.\nBecause they don''t need to find a mate anymore and care less about their weight.', NULL, NULL),
  ('d6ef85e9-2f60-5605-9796-3d6cf227f080'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd6ef85e9-2f60-5605-9796-3d6cf227f080'::uuid, 1, NULL, TRUE, 0, NULL, E'Chip Discount', E'You bought some chips at a supermarket with a discount of 2 for 3 dollars, but when you checked out, you found a mistake because you were charged 3 dollars each. What would you say to the assistant?', '4f2d7c41-fa12-59e5-8d51-79fb6539db81'::uuid, NULL, E'Respected assistant, I hope you are doing well.\nI would like to discuss an issue we have encountered with my purchase.\nIt appears that the chips are on sale 2 for 3 dollars, yet I was charged 3 dollars for each at checkout.\nI would appreciate your opinion on this matter. Thank you for your consideration.', NULL, NULL, NULL),
  ('d6f28528-238d-5bcb-8749-e56704715767'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd6f28528-238d-5bcb-8749-e56704715767'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4d6bfce9-a368-575a-ab15-90fd5a629070'::uuid, NULL, NULL, E'Maintaining an adequate supply of affordable housing is very difficult.', NULL, NULL),
  ('d6f555ee-823e-566d-9d72-bcef18642b88'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd6f555ee-823e-566d-9d72-bcef18642b88'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1caa4479-6904-5a7f-a697-238efb8b427a'::uuid, NULL, NULL, E'It is absolutely vital that you acknowledge all your sources.', NULL, NULL),
  ('d6f7229c-c8d9-5919-8712-e4a593a1d2d6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd6f7229c-c8d9-5919-8712-e4a593a1d2d6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'aa13387a-54c7-5e66-a9a1-9e59b702d434'::uuid, NULL, NULL, E'Many schools offer programs to study abroad for a term or two.', NULL, NULL),
  ('d6f8b6a2-4447-561b-9f16-289bad8a00e4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd6f8b6a2-4447-561b-9f16-289bad8a00e4'::uuid, 1, NULL, TRUE, 0, NULL, E'Design', E'Of course, for as long as there have been objects they have been designed. Yet design only {{1}} as a dedicated discipline in the 19th century and its literature and theory are still very much in its infancy. It is curious that {{2}} the increasingly prominent role that self-consciously designed commodities play in our everyday lives and in the way we define ourselves, the literature around the subject is hugely disappointing. In fact, beyond bland coffee-table books, it is barely there at all.\nNikolaus Pevsner''s Pioneers of Modern Design, a classic Hegelian text treating modernism as the inevitable {{3}} of a historical process, is, despite being first published in 1936 and hopelessly dated, still the key text. There have been {{4}} books, from quirky Bruno Munari (Design as Art) to deadpan Norman Potter (What is a Designer: Things, Places, Messages), and Deyan Sudjic''s 2008 The Language of Things, {{5}} attempted a broader examination. Nevertheless there is surprisingly little critique, an almost complete absence of theory and little genuinely popular, compelling writing on the subject.', NULL, NULL, NULL, E'1.emerged, 2.despite, 3.outcome, 4.other, 5.which', NULL, NULL),
  ('d6fd41fc-8e66-55e8-aae7-fe4432e92842'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd6fd41fc-8e66-55e8-aae7-fe4432e92842'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9c6de48e-49a0-5904-9134-46c4785ded14'::uuid, NULL, E'The chocolate chip cookies smelled so good that I ate one without asking.', NULL, NULL, NULL),
  ('d70bf1b7-7e75-5a78-a0ab-bc85208d8904'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd70bf1b7-7e75-5a78-a0ab-bc85208d8904'::uuid, 1, NULL, TRUE, 0, NULL, E'Impressionist', E'Impressionism was a nineteenth century art movement that began as a loose association of Paris-based artists who started publicly exhibiting their art in the 1860s. Characteristics of Impressionist painting include visible brush strokes, light colors, open composition, {{1}} on light in its changing qualities (often accentuating the effects of the passage of time), ordinary subject matter, and unusual visual angles. The name of the movement {{2}} from Claude Monet''s Impression, Sunrise (Impression, soleil levant). Critic Louis Leroy inadvertently coined the term in a satiric review published in Le Charivari.\nRadicals in their time, early Impressionists broke the rules of academic painting. They began by giving colors, freely brushed, primacy over line, drawing {{3}} from the work of painters such as Eugene Delacroix. They also took the {{4}} of painting out of the studio and into the world. Previously, not only still-lives and portraits, but also landscapes had been painted indoors, but the Impressionists found that they could {{5}} the momentary and transient effects of sunlight by painting air (in plain air).', NULL, NULL, NULL, E'1.emphasis, 2.is derived, 3.inspiration, 4.act, 5.capture', NULL, NULL),
  ('d70cf8f3-b242-52e1-846c-9e72ab41d064'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd70cf8f3-b242-52e1-846c-9e72ab41d064'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the hair that covers the body of sheep?', 'fef53b25-a1e6-5633-a9fb-e783ce9a460d'::uuid, NULL, NULL, E'Wool/ fleece / lana', NULL, NULL),
  ('d70f8f4f-2c04-5272-90c8-61478803f118'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'd70f8f4f-2c04-5272-90c8-61478803f118'::uuid, 1, NULL, TRUE, 0, NULL, E'Death of Salesman', E'Death of a Salesman is the masterpiece of Arthur Miller written in 1948 and produced in 1949. The popularity and success of the play demonstrate the strength of its story. The play was adapted for various tableaus, films, and course books across the globe, securing a Pulitzer Prize for Miller. The story of the play revolves around an unfortunate middle-class man who ruins his life, chasing the idea of the American Dream. This unattainable hunt costs him dearly; he seems stuck between fantasy and reality with a resultant loss of his own life. In one of his interviews, Miller mentions that the inspiration for the play is seeing his father struggle during the Depression.\n\nAccording to the passage, which of the following can be inferred?', NULL, NULL, NULL, E'People around the world who were interested in this play were able to enjoy it after it became successful.', NULL, NULL),
  ('d714f122-420b-5c1d-ac90-d6929e7d689f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', 'd714f122-420b-5c1d-ac90-d6929e7d689f'::uuid, 1, NULL, TRUE, 0, NULL, E'MCM-R', E'The Psychodynamic Approach. Theorists adopting the psychodynamic approach hold that inner conflicts are crucial for understanding human behavior, including aggression. Sigmund Freud, for example, believed that aggressive impulses are inevitable reactions to the frustrations of daily life. Children normally desire to vent aggressive impulses on other people, including their parents, because even the most attentive parents cannot gratify all of their demands immediately. Yet children, also fearing their parents'' punishment and the loss of parental love, come to repress most aggressive impulses. The Freudian perspective, in a sense: sees us as "steam engines." By holding in rather than venting "steam," we set the stage for future explosions. Pent-up aggressive impulses demand outlets. They may be expressed toward parents in indirect ways such as destroying furniture, or they may be expressed toward strangers later in life.\n\nAccording to the paragraph, Freud believed that children experience conflict between a desire to vent aggression on their parents and', NULL, NULL, NULL, E'a fear that their parents will punish them\na fear for loss of their parents'' love', NULL, NULL),
  ('d718125b-30e2-5baf-a1bc-59b25a62c40f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd718125b-30e2-5baf-a1bc-59b25a62c40f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the study of population numbers, composition, and trends?', '04b40c6b-9e17-551c-9285-3bd7e6abb357'::uuid, NULL, NULL, E'Demography', NULL, NULL),
  ('d71fd282-55d0-5281-b761-fdd3230b3be6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd71fd282-55d0-5281-b761-fdd3230b3be6'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call a place with lodging, food, and other services for travelers?', 'e7f5a3bc-a584-5a4f-9a63-f9a4dc98ffaf'::uuid, NULL, NULL, E'Hotel', NULL, NULL),
  ('d7266fa6-edef-52e4-87ff-170636ddf822'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd7266fa6-edef-52e4-87ff-170636ddf822'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e1d15303-31d8-5cb6-9646-cf6c6e6f021e'::uuid, NULL, E'She went into the kitchen in search of a soft drink.', NULL, NULL, NULL),
  ('d726ccb6-fac3-5a53-8110-2c2d472e31ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd726ccb6-fac3-5a53-8110-2c2d472e31ca'::uuid, 1, NULL, TRUE, 0, NULL, E'Long-lasting Symptoms', E'A new study published in the journal Science has revealed a possible {{1}} for why some COVID-19 patients develop long-lasting symptoms after recovering from the infection. The researchers found that these patients had a group of proteins in their blood that indicated a persistent activation of the complement system, a part of the immune system that helps {{2}} infections. The complement system normally helps clear pathogens from the body, but when it remains active without a target, it can damage healthy cells and tissues. This could lead to reduced oxygen and nutrient {{3}} to various organs, causing symptoms such as fatigue, brain fog, chest pain, and stomach issues. These symptoms, {{4}} known as long COVID, affect around 14% of adults who had COVID-19, according to a U.S. survey. The study, which involved 113 COVID-19 patients and 39 healthy controls, found that 40 patients had developed long COVID after six months. The study’s authors also suggest that {{5}} the complement system could be a potential strategy to prevent long COVID in the first place. They recommend further research to explore the role of the complement system in COVID-19 and its long-term consequences.', NULL, NULL, NULL, E'1.explanation, 2.fight, 3.delivery, 4.collectively, 5.modulating', NULL, NULL),
  ('d734c2a0-2931-51a3-9bc0-b8b4715de975'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'd734c2a0-2931-51a3-9bc0-b8b4715de975'::uuid, 1, NULL, TRUE, 0, NULL, E'Moai Statues', NULL, NULL, NULL, NULL, E'1, 2, 3, 4', NULL, NULL),
  ('d7353130-4a25-5bf9-8e45-6f246ed8edf4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd7353130-4a25-5bf9-8e45-6f246ed8edf4'::uuid, 1, NULL, TRUE, 0, NULL, E'Haze', E'One of the most basic forms of air pollution, haze, {{1}} visibility in many American cities and scenic areas. Haze is caused when sunlight {{2}} tiny pollution particles in the air, which reduce the clarity and color of what we see. Since 1988 the federal government has been {{3}} visibility in national parks and wilderness areas. In 1999, the government {{4}} a major effort to improve air quality in national parks and wilderness areas.', NULL, NULL, NULL, E'1.degrades, 2.encounters, 3.monitoring, 4.announced', NULL, NULL),
  ('d7355def-07a8-5eec-ba0f-e0303cb3f6d6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd7355def-07a8-5eec-ba0f-e0303cb3f6d6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8e23e333-f436-56fd-acb8-58ea1a9ee265'::uuid, NULL, NULL, E'The present system of funding for higher education is unsatisfactory.', NULL, NULL),
  ('d73a88d6-b3c0-5586-b9b3-923ff16e1289'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd73a88d6-b3c0-5586-b9b3-923ff16e1289'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'afb0c53e-873b-5686-9605-882f6f17a505'::uuid, NULL, E'Some advertisements primarily focus on promoting a brand rather than specific products.', NULL, NULL, NULL),
  ('d743b5de-fb6e-520a-8882-05450f4eb82e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd743b5de-fb6e-520a-8882-05450f4eb82e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '26a369e7-bf0f-56d4-92f1-6e6a93529643'::uuid, NULL, E'These days, more people are choosing to study from afar.', NULL, NULL, NULL),
  ('d74767aa-5ec3-5f67-bcae-7722341f6237'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd74767aa-5ec3-5f67-bcae-7722341f6237'::uuid, 1, NULL, TRUE, 0, NULL, E'Technology and Writer', NULL, '62b96d5c-368f-5b58-b178-7be49d6851f7'::uuid, NULL, E'What I want to look at today is the question of how much technology - If, um, a pen can indeed be called technology ... perhaps I should say the instrument of writing - affects a writer''s style and level of production. I also want to consider other factors that may have an effect on prose style, such as personality, educational background, and so on. Now, production levels aren''t so hard to measure in relation to the writing instrument used. The quill pen, for instance, would need continual re-filling and resharpening, which led to a leisurely, balanced style of prose full of simple sentences. Writing took a lot longer than now and the great novelists of the 18" century - Fielding, Smollett, Richardson - had a relatively small output, though some of their books ran to enormous length.\nBy the middle of the 19''h century, the fountain pen had been invented. It didn''t need such constant refilling, which can account for the more flowing, discursive style of, say, Dickens and Thackeray, as well as their tremendous output. Then came the typewriter, whose purpose, once you got the hang of it, was to speed up the writing process and was therefore much favored by journalists. This, it seems to me, gave rise to a short winded style characterized by short sentences. A short prose style, if you like. Dictating machines and tape recorders led, as one novelist complained, to writers becoming too conversational, rambling and long winded. Henry James, although he didn''t use these machines, dicta ted his later novels and, well, some might agree with this accusation. Well, it looks as though we''re going to have to leave word processors, computers and, of course, the way film and its narrative techniques have affected writing style for another day.', NULL, NULL, NULL),
  ('d7521deb-115e-5865-8657-b7edb198fc86'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd7521deb-115e-5865-8657-b7edb198fc86'::uuid, 1, NULL, TRUE, 0, NULL, E'Aphasia', NULL, '0ef3753b-7dec-554d-a1d0-7f142a69a683'::uuid, NULL, E'Language is an essential part of our lives that we often take for granted. With it, we can communicate our thoughts and feelings, lose ourselves in novels, send text messages, and greet friends. It’s hard to imagine being unable to turn thoughts into words. But if the delicate web of language networks in your brain became disrupted by stroke, illness, or trauma, you could find yourself truly at a loss for words. This disorder, called aphasia, can impair all aspects of communication. People who have aphasia remain as intelligent as ever. They know what they want to say, but can''t always get their words to come out correctly. They may unintentionally use substitutions called paraphasias, switching related words, like saying ''dog'' for ''cat'', or words that sound similar, such as ''house'' for ''horse''. Sometimes, their words may even be unrecognizable.', NULL, NULL, NULL),
  ('d752e185-b8f3-5651-95c1-de382d3adc16'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd752e185-b8f3-5651-95c1-de382d3adc16'::uuid, 1, NULL, TRUE, 0, NULL, E'Lunar Lander', E'More than 50 years after the last human landing on the moon, a new robotic explorer is on its way to attempt a historic {{1}} : touching down near the lunar South Pole. The Odysseus lunar lander, nicknamed Odie, was launched early Thursday morning by NASA and Intuitive Machines, a Houston-based company. The spacecraft is {{2}} the size of a telephone booth and carries a camera system, an original sculpture, and several science and technology experiments. The mission aims to land at a site that has never been explored before, where the sun barely rises above the {{3}} and the temperatures are extremely cold. The landing site is also of interest because it may contain water ice, a valuable resource for future lunar missions. Odie is named {{4}} the Greek hero Odysseus, who faced many challenges and adventures on his journey home after the Trojan War. The lander’s team hopes that Odie will also overcome the {{5}} and dangers of space exploration and make a successful landing on the moon.', NULL, NULL, NULL, E'1.feat, 2.roughly, 3.horizon, 4.after, 5.obstacles', NULL, NULL),
  ('d7565c5b-1b79-5d4b-ab25-c9ef45239a51'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd7565c5b-1b79-5d4b-ab25-c9ef45239a51'::uuid, 1, NULL, TRUE, 0, NULL, E'Tea and Sugar', E'Like coffee, plain tea contains just a couple of calories per cup and no sugar. But what’s added in it can change that situation. A medium sweet tea and a large iced latte from fast food restaurants both pack about seven teaspoons of sugar. However, the American Heart Association recommends no more than six teaspoons for the whole day.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d75a4cef-c02e-5b52-a12e-0dde6f042e4c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd75a4cef-c02e-5b52-a12e-0dde6f042e4c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'dd02b0b4-b1bd-5584-94bd-e092732b6b7a'::uuid, NULL, NULL, E'The application of this new technology was supported by the board.', NULL, NULL),
  ('d75b5dd9-561a-5a1a-922b-9024e71ea011'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', 'd75b5dd9-561a-5a1a-922b-9024e71ea011'::uuid, 1, NULL, TRUE, 0, NULL, E'Pakicetus', E'The fossil consists of a complete skull of an archaeocyte, an extinct group of ancestors of modern cetaceans. Although limited to a skull, the Pakicetus fossil provides precious details on the origins of cetaceans. The skull is cetacean-like but its jawbones lack the enlarged space that is filled with fat or oil and used for receiving underwater sound in modern whales. Pakicetus probably detected sound through the ear opening as in land mammals. The skull also lacks a blowhole, another cetacean adaptation for diving. Other features, however, show experts that Pakicetus is a transitional form between a group of extinct flesh-eating mammals, the mesonychids, and cetaceans. It has been suggested that Pakicetus fed on fish in shallow water and was not yet adapted for life in the open ocean. It probably bred and gave birth on land.\n\nPakicetus and modern cetaceans have similar ____ .', NULL, NULL, NULL, E'skull shapes\nfeeding locations', NULL, NULL),
  ('d76037d1-3a97-5a3e-8288-9698158d5766'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'd76037d1-3a97-5a3e-8288-9698158d5766'::uuid, 1, NULL, TRUE, 0, NULL, E'Age-Ready Cities', NULL, NULL, NULL, NULL, E'4, 1, 2, 3', NULL, NULL),
  ('d769d170-16f7-5036-ad89-ed1f738e5ed2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd769d170-16f7-5036-ad89-ed1f738e5ed2'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the practice of growing aquatic animals or plants for food?', 'd453f8c0-de1a-5475-adcc-0e7b0e7f4182'::uuid, NULL, NULL, E'Aquaculture', NULL, NULL),
  ('d76c7259-e611-58bb-a9f1-660ef125a880'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd76c7259-e611-58bb-a9f1-660ef125a880'::uuid, 1, NULL, TRUE, 0, NULL, E'Fluids', E'Fluids can be roughly divided into two {{1}} :regular ones and weird ones. Regular ones, like water and alcohol, act more or less as expected when {{2}} through pipes or stirred with a spoon. Lurking among the weird ones — which include {{3}} such as paint, honey and blood — are a vast variety of behavioral enigmas that have {{4}} researchers over the centuries.', NULL, NULL, NULL, E'1.categories, 2.pumped, 3.substances, 4.baffled', NULL, NULL),
  ('d76c9cac-e7f9-50f5-a669-256adfee64c1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd76c9cac-e7f9-50f5-a669-256adfee64c1'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ab763ecf-9455-5303-821a-0c5d430c6abb'::uuid, NULL, NULL, E'It was sad when the study didn''t give them clear answers.', NULL, NULL),
  ('d77ac6f0-ae7f-5e4d-a736-2340f0a3e5c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd77ac6f0-ae7f-5e4d-a736-2340f0a3e5c5'::uuid, 1, NULL, TRUE, 0, NULL, E'Amazing Plants', E'Some plants have amazing abilities that show their intelligence, such as catching and eating insects. {{1}} than growing randomly, plants like the Venus flytrap demonstrate strategic behaviors in {{2}} prey. For instance, the flytrap will often {{3}} shut only after the second brush of its hairs, {{4}} a basic form of memory and decision-making process.', NULL, NULL, NULL, E'1.Rather, 2.capturing, 3.snap, 4.indicating', NULL, NULL),
  ('d77d60da-028d-59e5-a32e-a9582c8cfd40'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd77d60da-028d-59e5-a32e-a9582c8cfd40'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'cb739249-4912-56a9-b542-1a489cd5a086'::uuid, NULL, E'The teacher asked the group to commence the task.', NULL, NULL, NULL);
