  ('d77ef44f-d0a7-5190-a4c7-1b7468b33cbd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd77ef44f-d0a7-5190-a4c7-1b7468b33cbd'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '36473914-d468-5bf5-85bc-6e681c452d85'::uuid, NULL, NULL, E'Safety is most important in the biology lab.', NULL, NULL),
  ('d78a6c4c-4f2a-532e-8068-f71823e9b5fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd78a6c4c-4f2a-532e-8068-f71823e9b5fd'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5965921e-bea0-54f9-ad5c-7fec5fd59e72'::uuid, NULL, NULL, E'This is a compulsory course, so make sure you attend.', NULL, NULL),
  ('d78bd6a3-3f78-59e8-b901-a8f08cc0223c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd78bd6a3-3f78-59e8-b901-a8f08cc0223c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'cbba8bb3-bbc9-5b84-b400-3667c8969eba'::uuid, NULL, NULL, E'A university degree is a requirement to enter many professions.', NULL, NULL),
  ('d790c867-1844-591e-8be1-83bfcf9c8684'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'd790c867-1844-591e-8be1-83bfcf9c8684'::uuid, 1, NULL, TRUE, 0, NULL, E'Infants'' Imitation', E'Contrary to popular belief, babies under a few months don''t grin at you because they''re copying your own smile, according to new research.\nMany studies have indicated that from birth, infants imitate the behaviors and facial expressions of the adults around them.\nHowever, a team of Australian, South African and British researchers have released a study this week that refutes this widespread belief. "Numerous studies from the 1980s and 90s indicated no imitation by newborns, while others claimed it was there, "says Virginia Slaughter, a biologist at the University of Queensland and co-author of the study.\n"We wanted to clear up the confusion because the ''fact'' that newborns imitate is widely cited, not just in the fields of psychology, neuroscience and paediatrics, but also in popular sources for parents.''\nThe international research team, led by Janine Oostenbroek, a psychologist at the University of York in the UK, exposed more than 100 infants to a broad range of gestures and recorded their responses at one, two, six and nine weeks of age.\nThe gestures included social cues like adults poking their tongues out, frowning or grinning, as well as non-social cues such as pointing or opening a box.\nThe findings showed no link between behaviors exhibited by babies in their first few months and the gestures they were exposed to. The babies were just as likely to exhibit gestures they had never seen before as repeat ones they had.\nFor instance, babies stuck their tongues out just as frequently if they were being exposed to pointing or opening a box, rather than anything to do with mouths or tongues.', NULL, NULL, E'With a study released to indicating no imitation by newborns and no link between behaviors exhibited by babies in their first few months and the gestures they were exposed to, babies under a few months do not grin at you because they are copying your own smile, despite many studies having indicated that from birth, infants imitate the behaviors and facial expressions of the adults around them.', NULL, 5, 75),
  ('d791ee21-b558-575d-83cd-e5ba8cbfacf9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd791ee21-b558-575d-83cd-e5ba8cbfacf9'::uuid, 1, NULL, TRUE, 0, NULL, E'Performance of Genders', NULL, '723a9fff-80a4-5ccc-a7a4-e13bbe5406eb'::uuid, NULL, E'You can see that the two charts, each give quite a different picture of the performance of boys and girls in the two key subjects of Math and English. It shows that in English, girls consistently outperform boys over a period of 6 years, achieving scores about 10% above their male peers. There is quite a different picture when we look at the Math results with no real difference between genders in the results. What is the explanation for these key differences? To answer this question, researchers look at biological and cognitive factors, and a range of social factors. The interaction between these different components in early childhood development are seen as maintained and reinforced in the school context. And this leads to distinct gender patterns of behavior and skills with direct consequences for school performance and achievement. The ultimate uses of this evidence (are) to show that biological factors, such as patterns of cognitive developments are closely linked to social factor, such as learned gender categories. This cognitive skills are learned both pre-school and subsequently at school, supported by the responses of teachers, creating a reinforcement of patterns.', NULL, NULL, NULL),
  ('d7939294-7495-568d-9b6c-7c2dbb4986bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd7939294-7495-568d-9b6c-7c2dbb4986bd'::uuid, 1, NULL, TRUE, 0, NULL, E'Arts And Sicence Students', E'An investigation into the study habits of undergraduates was carried out by a {{1}} of researchers at a number of different universities. In all the universities {{2}} in the study, it was found that there were the {{3}} significant differences between the habits of arts and science students. Not surprisingly perhaps, arts students read more {{4}} , while science students tended to concentrate on a few {{5}} texts.', NULL, NULL, NULL, E'1.team, 2.participating, 3.same, 4.widely, 5.core', NULL, NULL),
  ('d7979d4f-23e3-5068-a3c6-0ac695f1e708'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd7979d4f-23e3-5068-a3c6-0ac695f1e708'::uuid, 1, NULL, TRUE, 0, NULL, E'Online Education', E'Online education has opened up new opportunities for students who may not have access to traditional campus-based programs, allowing them to pursue their academic goals from anywhere in the world. Online courses offer greater flexibility and convenience than traditional classroom-based courses, allowing students to study at their own pace and on their own schedule.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d79a061c-fe6a-5da9-8527-2eda4bdb4b19'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd79a061c-fe6a-5da9-8527-2eda4bdb4b19'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6d1d0fdb-d606-51ce-aa97-d680c637cee9'::uuid, NULL, E'Most scientists believe that climate change threatens life on Earth.', NULL, NULL, NULL),
  ('d79dee6d-bf6b-5d66-a53a-f77914765dee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd79dee6d-bf6b-5d66-a53a-f77914765dee'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '180f7cae-cad5-528f-b806-2067feb5dde7'::uuid, NULL, NULL, E'Students must submit assignments online through the university''s learning platform.', NULL, NULL),
  ('d79df5e5-529c-5546-bfb0-7bc9f0712093'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd79df5e5-529c-5546-bfb0-7bc9f0712093'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f68367e1-c251-5cc8-806d-6a47d813fe44'::uuid, NULL, E'The university''s main campus could be closed for today''s activities.', NULL, NULL, NULL),
  ('d7aa2e55-1fd9-5657-ab89-ef486249496e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'd7aa2e55-1fd9-5657-ab89-ef486249496e'::uuid, 1, NULL, TRUE, 0, NULL, E'Climate Change''s Impact', E'As warmer winter temperatures become more common, one way for some animals to adjust is to shift their ranges northward. But a new study of 59 North American bird species indicates that doing so is not easy or quick — it took about 35 years for many birds to move far enough north for winter temperatures to match where they historically lived.\nThe researchers used 35 years of data from the North American Christmas Bird Count to match winter temperatures to where birds were seen. They tested 59 bird species individually and found that they responded differently to climate change. When summarized across bird species, there was evidence for a strong delay lasting about 35 years.\nFor example, black vultures have spread northward in the last 35 years and now winter as far north as Massachusetts, where the minimum winter temperature is similar to what it was in Maryland in 1975. On the other hand, the endangered red-cockaded woodpecker did not alter its range at all despite the warming trend, possibly because its very specific habitat requirements precluded a range shift.\nBoth of these scenarios could represent problems for birds, La Sorte said. Species that do not track changes in climate may wind up at the limits of their physiological tolerance, or they may lose important habitat qualities, such as favored food types, as those species pass them by. But they also can''t move their ranges too fast if the habitat conditions they depend on also tend to lag behind climate.\nIf warming trends weaken, as they did over the past few years, birds may be able to catch up. But accelerated warming, which is likely as global carbon emissions continue to increase, may put additional strain on birds. The study highlights these challenges and the high potential climate change has for disrupting natural systems. It also underscores the challenges ecologists face in predicting the long-term consequences of climate change for many species simultaneously.', NULL, NULL, E'It took about 35 years for many birds to move far enough north for winter temperatures to match where they historically lived, while bird species responded differently to climate change, so species that do not track changes in climate may lose important habitat qualities, but they also can''t move their ranges too fast if the habitat conditions they depend on also tend to lag behind climate, and accelerated warming may put additional strain on birds.', NULL, 5, 75),
  ('d7aacbf3-1523-5039-9716-b25cc03a3832'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd7aacbf3-1523-5039-9716-b25cc03a3832'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7549440e-26e1-5d4d-8d3d-d1dde24a0698'::uuid, NULL, E'The buildings looked lovely in the bright sunshine.', NULL, NULL, NULL),
  ('d7b5343c-2e2b-50fe-8220-2742c9ad100a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd7b5343c-2e2b-50fe-8220-2742c9ad100a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'debef907-d2a2-552d-9960-5f484e52b0af'::uuid, NULL, E'The largest literacy program in this country reaches one hundred people yearly.', NULL, NULL, NULL),
  ('d7b69eb9-c76e-5e7d-9e8c-810c64aca5fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd7b69eb9-c76e-5e7d-9e8c-810c64aca5fb'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b5dac5e6-a1b6-5f20-8f6f-ec8868b42fe5'::uuid, NULL, NULL, E'There are many teachers to help students on campus.', NULL, NULL),
  ('d7ba9870-ed65-5864-a378-c98f3809966f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd7ba9870-ed65-5864-a378-c98f3809966f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c9d165a8-9aaf-5475-99cf-30ef133c7c65'::uuid, NULL, E'Long before children are able to speak or understand a language, they communicate through facial expressions and by making noises.', NULL, NULL, NULL),
  ('d7c0488c-760d-5434-8fdc-f022d6126b54'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd7c0488c-760d-5434-8fdc-f022d6126b54'::uuid, 1, NULL, TRUE, 0, NULL, E'Alternate Plans', E'You''ve arranged a weekend hiking trip with friends, but as the date approaches, you notice the weather forecast predicts heavy rain. You need to discuss with your friends whether to proceed with the hike, postpone it, or plan an alternative indoor activity for the weekend. What would you say to your friends?', 'a12fe7f2-e4f6-5bcf-b114-da25a161baf0'::uuid, NULL, E'So, I''ve been checking the weather for our hiking weekend, and it looks like we''re in for some heavy rain. I''m thinking it might not be the best idea to hike in that. How do you all feel about postponing the hike to another weekend? Alternatively, we could switch gears and plan something indoors instead, like a game night or a movie marathon at my place. Let me know what you think.', NULL, NULL, NULL),
  ('d7c139af-87f2-5194-a737-117784b6ad0a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd7c139af-87f2-5194-a737-117784b6ad0a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the component of a camera that should be developed in darkness?', '12ee002c-a43d-5186-9f9b-323813be7c39'::uuid, NULL, NULL, E'Negative / film', NULL, NULL),
  ('d7c3ec73-39ca-5d12-899f-9896b9dc13ce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd7c3ec73-39ca-5d12-899f-9896b9dc13ce'::uuid, 1, NULL, TRUE, 0, NULL, E'Insects and Streetlights', E'There''s growing alarm over plunging insect populations with climate change, habitat destruction and pesticides all thought to play a role. But now, scientists say there''s another culprit: artificial streetlights. Researchers from the charity Butterfly Conservation counted caterpillars at the sides of brightly lit roads. Compared with similar stretches of unlit roads, caterpillar numbers were reduced by half, suggesting streetlights can affect the abundance of insects – at least on a local scale. The scientists say with insects in trouble, we should be doing all we can to reduce negative influences. But there are practical solutions such as dimming streetlights in the early hours, installing motion sensors, or using color filters to modify the light.\n\nAccording to the speaker, what is the result of the research into insect population near streetlights?', '2f2d4ee9-c95a-5e3d-a26b-4fbfe261bcd2'::uuid, NULL, NULL, E'Insect population drops 50% near streetlights.', NULL, NULL),
  ('d7c415e2-6c50-55d2-a298-6a11d89b5e0d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd7c415e2-6c50-55d2-a298-6a11d89b5e0d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0e3a8a11-9f13-5980-b0a7-56f1c998f11d'::uuid, NULL, E'The professor is going to discuss the conflict.', NULL, NULL, NULL),
  ('d7c6a6ac-9e43-576b-99ee-d312fd6ec2ab'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd7c6a6ac-9e43-576b-99ee-d312fd6ec2ab'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8cadef33-03b5-5e62-a0d0-a34f89969941'::uuid, NULL, E'All necessary information is in the assignment.', NULL, NULL, NULL),
  ('d7c71bd2-ee77-544b-8be5-a4a128ca5eb9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd7c71bd2-ee77-544b-8be5-a4a128ca5eb9'::uuid, 1, NULL, TRUE, 0, NULL, E'Plato', E'Plato {{1}} one of the greatest philosophers of all time, whose ideas continue to influence education, politics, and morality. {{2}} , his theories were often challenged by critics, who questioned {{3}} the ideal society in his mind could ever exist in reality.', NULL, NULL, NULL, E'1.remains, 2.However, 3.whether', NULL, NULL),
  ('d7ca334f-e5dc-5c38-b140-1f9159adc34a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd7ca334f-e5dc-5c38-b140-1f9159adc34a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which part of the hand do we use to pick up objects?', 'd7b56926-0dbd-5e33-8735-f751d1e38705'::uuid, NULL, NULL, E'Finger / fingers', NULL, NULL),
  ('d7d65bdb-17d4-5bef-b30c-84e7d5b0ff75'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd7d65bdb-17d4-5bef-b30c-84e7d5b0ff75'::uuid, 1, NULL, TRUE, 0, NULL, E'FIB', E'People have been leaving {{1}} on bathroom walls for thousands of years. Just google "ancient Roman bathroom graffiti." But we''re not the only ones to use latrines for information exchange—as two German researchers have {{2}} after hundreds of hours watching lemurs pee and poop. For science.\n{{3}} Iris Dröscher and Peter Kappeler concentrated on seven sets of pair-bonded members of a species called {{4}} sportive lemurs, at a nature reserve in southern Madagascar. Their report is in the journal Behavioral Ecology and Sociobiology.\nMany animals use the same spots {{5}} to do their business, primates in {{6}} . For these lemurs, a specific tree becomes the urine and feces focal point. And because chemical compounds in their waste transmit information, the so-called latrine tree becomes like a bulletin board to post messages for the rest of the community.\nBased on their 1,097 hours of observations, the researchers conclude that urine and glandular secretions left on the tree trunk are the primary message {{7}} . Feces mostly just collects on the ground.\nSome urine telegrams are probably signals from a particular lemur to the neighbors that he or she is around. But male lemurs upped their latrine visits when potential competitors for females came into their home area. So the frequent chemical messages left on the tree probably say in that case, "Buzz off, buddy, she''s with me." In lemur.', NULL, NULL, NULL, E'1.messages, 2.confirmed, 3.Primatologists, 4.white-footed, 5.repeatedly, 6.particular, 7.vehicles', NULL, NULL),
  ('d7e1b914-6d79-5979-a246-a166e0a9d17a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'd7e1b914-6d79-5979-a246-a166e0a9d17a'::uuid, 1, NULL, TRUE, 0, NULL, E'Formal Vocabulary', NULL, NULL, NULL, NULL, E'2, 5, 1, 3, 4', NULL, NULL),
  ('d7e4ddee-5b14-5759-9f96-b440a1a61915'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd7e4ddee-5b14-5759-9f96-b440a1a61915'::uuid, 1, NULL, TRUE, 0, NULL, E'Emotional Intelligence', NULL, '2908dfbb-1600-5d9d-ba54-434087f5eb4b'::uuid, NULL, E'In the panorama of skills vital for success, emotional intelligence shines prominently. It''s the ability to be aware of, control, and express our emotions judiciously and empathetically that marks our path, not just through academia, but through life. Emotional intelligence is crucial in developing robust relationships, both personal and professional. It equips us with the sensitivity to navigate social complexities, leading to more fruitful collaborations and deeper connections. Studies in organizational behavior find that teams with high emotional intelligence have increased effectiveness, higher job satisfaction, and better outcomes. Beyond interaction, emotional intelligence is integral to self-awareness. It allows us to reflect, understand our strengths and weaknesses, and pursue personal growth. This introspective aspect is not only a cornerstone for mental well-being but also a catalyst for academic and career success. As we march towards our future, let''s invest in our emotional intelligence. It is this investment that will yield dividends in all facets of our lives, forging paths to leadership and fulfillment.', NULL, NULL, NULL),
  ('d7e7325a-e2c2-58ed-a146-e92cd5a87975'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd7e7325a-e2c2-58ed-a146-e92cd5a87975'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f829eaab-138a-5669-826d-bd4bdfbd57e6'::uuid, NULL, NULL, E'All living things, no matter how different, share some same parts.', NULL, NULL),
  ('d7e99cc3-0118-5a3b-9505-70c1142a211e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd7e99cc3-0118-5a3b-9505-70c1142a211e'::uuid, 1, NULL, TRUE, 0, NULL, E'Enough Fluid', E'Your body is nearly two-thirds water. And so it is really important that you consume enough fluid to stay hydrated and healthy. If you don''t get enough fluid you may feel tired, get headaches, and not perform at your best.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d7ee21cf-596a-5b2d-892a-01ea9d6862c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd7ee21cf-596a-5b2d-892a-01ea9d6862c0'::uuid, 1, NULL, TRUE, 0, NULL, E'Romans', E'Over many centuries and across many territories the Romans were able to win an astonishing number of military victories and their success was due to several important factors. Italy was a peninsula not easily attacked. {{1}} a huge pool of fighting men to draw upon, a disciplined and innovative army, a centralized command and line of supply, expert engineers, effective diplomacy {{2}} a network of allies, and an inclusive approach to conquered people, {{3}} allowed for strengthening and broadening of the Roman power and logistical bases. {{4}} , her allies not only supplied, equipped and paid for additional men but they also supplied vital materials such as grain and ships. {{5}} this, Rome was more or less in a continuous state of war or readiness for it and believed absolutely in the necessity of defending and imposing on others what she firmly believed was her cultural superiority.', NULL, NULL, NULL, E'1.There was, 2.through, 3.which, 4.Further, 5.On top of all', NULL, NULL),
  ('d7f30245-9a75-5a54-bed0-8c7ef89db3e6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd7f30245-9a75-5a54-bed0-8c7ef89db3e6'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do we describe a person who is unable to speak?', 'f874546c-1c22-55d8-b649-245c5e44d569'::uuid, NULL, NULL, E'Dumb / mute / tongueless', NULL, NULL),
  ('d7f56d86-eafa-52ab-806c-7668d377f92e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd7f56d86-eafa-52ab-806c-7668d377f92e'::uuid, 1, NULL, TRUE, 0, NULL, E'A Letter', E'A letter from a mother to school officials. Because her son was {{1}} at home she explained his illness to them saying she did not want her son to {{2}} the disease to other children. She {{3}} that the authorities would be able to {{4}} on lessons to her son during this {{5}} .', NULL, NULL, NULL, E'1.sick, 2.spread, 3.hoped, 4.pass, 5.period', NULL, NULL),
  ('d7f98e24-96bd-56fe-b431-b92c2a5a6b47'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd7f98e24-96bd-56fe-b431-b92c2a5a6b47'::uuid, 1, NULL, TRUE, 0, NULL, E'Colorado River', E'The Colorado river is the lifeblood of the US Southwest, but today it is drastically {{1}} due to overuse, megadrought and climate change. That is partly down to the {{2}} that people are taking too much water out of the river basin and partly down to a megadrought, {{3}} by climate change, which means the region the Colorado flows through is the driest it has been in 1200 years.', NULL, NULL, NULL, E'1.depleted, 2.fact, 3.exacerbated', NULL, NULL),
  ('d7fdaf6e-dea0-5289-bd66-7227eda6f410'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd7fdaf6e-dea0-5289-bd66-7227eda6f410'::uuid, 1, NULL, TRUE, 0, NULL, E'Fence', E'Fences are not just designed to keep people and animals out, but they also keep things in, like children. From a safety perspective, knowing your children are in a yard that is fenced offers solid peace of mind when it comes to their well-being. Fences are also great for keeping pets in a confined, controlled area.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d8006ced-3fbb-52d4-aef7-57d81667bf55'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd8006ced-3fbb-52d4-aef7-57d81667bf55'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '72950854-131a-5cc2-bc19-ca0fc1aaadd6'::uuid, NULL, NULL, E'The university has created summer schools for international students.', NULL, NULL),
  ('d800b00b-5f81-5591-89b4-104b33b448c3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd800b00b-5f81-5591-89b4-104b33b448c3'::uuid, 1, NULL, TRUE, 0, NULL, E'Reading and Writing', E'The simplest {{1}} for practising writing is that it contributes to children''s fluent reading. In reading and writing, a vivid {{2}} is often {{3}} to the author''s prospects and success, deepening the reader''s {{4}} .', NULL, NULL, NULL, E'1.reason, 2.image, 3.tied, 4.understanding', NULL, NULL),
  ('d804ebf6-5ff7-552e-83bb-64b87cc25507'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd804ebf6-5ff7-552e-83bb-64b87cc25507'::uuid, 1, NULL, TRUE, 0, NULL, E'Basic Organisms', E'Some of the most basic organisms are smarter than we thought. Rather than moving about randomly, amoebas and plankton employ sophisticated {{1}} to look for food and might travel in a way that optimizes their foraging. Biophysicists have {{2}} tried to explain how creatures of all sizes search for food. However, single-celled organisms such as bacteria seem to move in no particular direction in their search. To investigate, Liang Li and Edward Cox at Princeton University studied the movements of amoebas (Dictyostelium) in a Petri dish, recording the paths travelled by 12 amoebas, including every turn and movement straight ahead, for 8 to 10 hours per amoeba. Immediately after an amoeba turned right, it was twice as {{3}} to turn left as right again, and vice versa, they told a meeting of the American Physical Society meeting in Denver, Colorado, last week. This suggests that the cells have a {{4}} memory being able to remember the last direction they had just turned in, says Robert Austin, a biophysicist at Princeton who was not involved in the study.', NULL, NULL, NULL, E'1.strategies, 2.long, 3.likely, 4.rudimentary', NULL, NULL),
  ('d80ef189-6620-5361-b9c4-006b12d68a8e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'd80ef189-6620-5361-b9c4-006b12d68a8e'::uuid, 1, NULL, TRUE, 0, NULL, E'English Grammar', NULL, NULL, NULL, NULL, E'5, 1, 2, 4, 3', NULL, NULL),
  ('d81a97c8-142a-5f34-bae1-3ad370374f82'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd81a97c8-142a-5f34-bae1-3ad370374f82'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '70b64822-9f7f-53d8-8e43-b457b1ee8c57'::uuid, NULL, NULL, E'The delegates have entered the assembly hall through the lobby.', NULL, NULL),
  ('d824c96c-9295-5acb-af6b-75ff72c805fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd824c96c-9295-5acb-af6b-75ff72c805fd'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e3971d6a-85c0-5491-a009-1a5e099855c6'::uuid, NULL, NULL, E'An expedition has been planned down to the last detail.', NULL, NULL),
  ('d827f6d6-b2a9-5d60-8553-842a8facb669'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'd827f6d6-b2a9-5d60-8553-842a8facb669'::uuid, 1, NULL, TRUE, 0, NULL, E'Plastic Particles', E'Fish are being killed, and prevented from reaching maturity, by the litter of plastic particles finding their way into the world''s oceans, new research has proved. Some young fish have been found to prefer tiny particles of plastic to their natural food sources, effectively starving them before they can reproduce. The growing problem of microplastics - tiny particles of polymer-type materials from modern industry - has been thought for several years to be a peril for fish, but the study published on Thursday is the first to prove the damage in trials. Microplastics are near-indestructible in natural environments. They enter the oceans through litter, when waste such as plastic bags, packaging and other convenience materials are discarded. Vast amounts of these end up in the sea, through inadequate waste disposal systems and sewage outfall. Another growing source is microbeads, tiny particles of hard plastics that are used in cosmetics, for instance as an abrasive in modern skin cleaners. These easily enter waterways as they are washed off as they are used, flushed down drains and forgotten, but can last for decades in our oceans.\nThe impact of these materials has been hard to measure, despite being a growing source of concern. Small particles of plastics have been found in seabirds, fish and whales, which swallow the materials but cannot digest them, leading to a build-up in their digestive tracts. For the first time, scientists have demonstrated that fish exposed to such materials during their development show stunted growth and increased mortality rates, as well as changed behavior that could endanger their survival.', NULL, NULL, E'Fish are being killed and prevented from reaching maturity, by the litter of plastic particles finding their way into the world''s oceans, as some young fish have been found to prefer tiny particles of plastic to their natural food, effectively starving them before they can reproduce, which has been thought for several years to be a peril for fish, with the impact of these materials hard to measure, despite being a growing source of concern.', NULL, 5, 75),
  ('d8325dde-3b43-58c9-ba70-ab56ef15dbd5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd8325dde-3b43-58c9-ba70-ab56ef15dbd5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f9bc9f4f-cf43-5978-8c1c-47059fc241c7'::uuid, NULL, NULL, E'Safety protocols dictate always wearing protective gear in the lab.', NULL, NULL),
  ('d8352d3a-6fae-5032-b4ff-615ed3d2031a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd8352d3a-6fae-5032-b4ff-615ed3d2031a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the formal discussion of a particular issue at a public meeting with two groups expressing opposing views?', '8ab5f33b-0f63-5dfa-acba-9dc4977b06c8'::uuid, NULL, NULL, E'Debate', NULL, NULL),
  ('d83a8e9c-611f-5849-a6dc-9af80a06c917'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd83a8e9c-611f-5849-a6dc-9af80a06c917'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What gas will be generated from the boiling water?', '2f2c4efb-c9d9-50c4-94e7-41985bca7593'::uuid, NULL, NULL, E'Water vapor / steam', NULL, NULL),
  ('d84887e2-ea99-5117-96f3-e955b7a795b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'd84887e2-ea99-5117-96f3-e955b7a795b8'::uuid, 1, NULL, TRUE, 0, NULL, E'Overseas Departures', E'Over the past ten years, Australian overseas departures have grown from 1.7 million to 3.2 million. This represents strong average, annual growth of 6.5 per cent. This paper {{1}} outbound travel demand to each destination country using the travel demand models of short- term resident departures. The models are specified in terms of a double logarithmic linear functional form, with overseas departures as the dependent variable and real household disposable income prices of travel and accommodation in Australia and overseas and the exchange rate as independent {{2}} .\nThe models were estimated using historical time series data from 1973 to 1998. The data were obtained from several {{3}} such as the World Tourism Organization, Australian Bureau of Statistics, World Bank and International Monetary Fund. The results suggest that the estimated elasticity parameters are consistent with standard economic theory. The number of short-term resident departures is positively influenced by per capita real household disposable income, and the price of domestic travel and accommodation, and {{4}} influenced by the price of travel and accommodation overseas.\nThe estimated demand models were used to develop the Tourism Forecasting Council’s long run forecasts. The forecasts suggest that the number of short-term resident departures will increase strongly over the next ten years, largely due to the strength of the Australian economy, competitive travel prices, and Australians'' interest in {{5}} different cultures and lifestyles.', NULL, NULL, NULL, E'1.analyses, 2.variables, 3.sources, 4.negatively, 5.experiencing', NULL, NULL),
  ('d8495d1c-d7ed-500b-9962-e549a2fca97b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd8495d1c-d7ed-500b-9962-e549a2fca97b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a device that is used to measure temperature?', 'f3570a24-d370-5285-9ea7-12a48fb4e320'::uuid, NULL, NULL, E'Thermometer', NULL, NULL),
