  ('d85614e1-cfb1-5329-9ac5-999c0fc29679'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd85614e1-cfb1-5329-9ac5-999c0fc29679'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Where do teachers sit at the university?', '82612ea2-4ce3-5ba0-8284-235780bf8a15'::uuid, NULL, NULL, E'Office', NULL, NULL),
  ('d85d8730-b379-504d-88f9-7b9be8b1eaa8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd85d8730-b379-504d-88f9-7b9be8b1eaa8'::uuid, 1, NULL, TRUE, 0, NULL, E'Parties', E'Since 1852, every US president has been a member of one of the country''s two major political parties, the Republican party or the Democratic party. Democrats generally support higher taxes, so they can fund more government programs. Republicans generally prefer lower taxes and smaller government. These two parties tend to reflect relatively moderate political views.\nBut there are several other smaller parties on the fringes, including the Libertarian, Constitution, Socialist or Green Parties. Or you can just be an independent not affiliated with any party. Third parties are not that big. But they can have a major influence on presidential elections, by taking away votes from the two major party candidates, which in some years can be a deciding factor in the race to become president.\n\nWhich statement about the US parties is NOT true?', '21f02d9f-2188-519b-80a2-58e53768cd0c'::uuid, NULL, NULL, E'Third parties always play a marginal role in the presidential elections in America.', NULL, NULL),
  ('d8658654-af50-58bb-9481-4025ab396881'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd8658654-af50-58bb-9481-4025ab396881'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'A coworker in the same institution is a colleague or a peer?', '0b6ba6ba-39e6-59c9-8037-bb376f833e0f'::uuid, NULL, NULL, E'Colleague', NULL, NULL),
