  ('d9002e41-3f3a-5034-a4a8-31100abf48aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd9002e41-3f3a-5034-a4a8-31100abf48aa'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f7cc3667-8831-5324-8f67-e98de16b9ac3'::uuid, NULL, NULL, E'Working as part of a team is a skill we possess.', NULL, NULL),
  ('d9019cfd-9137-51d7-82bd-526f9eeb03db'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd9019cfd-9137-51d7-82bd-526f9eeb03db'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0e0713bb-7cc5-5e04-a8a7-6fd91f894d16'::uuid, NULL, E'You don''t have to tell lies to get people to like you.', NULL, NULL, NULL),
  ('d9036dc4-d417-55ab-8a3e-597d8dde8033'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd9036dc4-d417-55ab-8a3e-597d8dde8033'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8ae14741-3a4c-5ee3-9518-c31c09d81ae1'::uuid, NULL, E'Cellular engineering strategies are highly desirable.', NULL, NULL, NULL),
  ('d9065fc2-d76e-5a4c-aea6-59709b5dc9d6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd9065fc2-d76e-5a4c-aea6-59709b5dc9d6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '52bdf1c5-666d-5eb4-b5b7-2e805b27d824'::uuid, NULL, E'The prospect of living in a city does not appeal to me.', NULL, NULL, NULL),
  ('d9098d0c-ec08-5f90-9aa9-ab8d176b810f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd9098d0c-ec08-5f90-9aa9-ab8d176b810f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bb6e73a4-055d-5365-b28a-213a16ff4aba'::uuid, NULL, E'Many of the most popular courses are available online.', NULL, NULL, NULL),
  ('d90b5c8d-a319-5622-a001-cb1e01c76434'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd90b5c8d-a319-5622-a001-cb1e01c76434'::uuid, 1, NULL, TRUE, 0, NULL, E'Awe', NULL, 'a217597e-50fc-5a7c-a155-3527c5b8a956'::uuid, NULL, E'The idea is that you experience awe in situations where it’s important to be acquiring information that you can use later. It makes sense: if something is awe-inspiring because it doesn’t fit with your understanding ofthe world, that’s probably something that you should know more about if you wan na survive. The feeling of awe directs your attention away from yourself and toward your environment, so you can acquire more information about this new, possibly life-changing thing—whether it’s positive or negative. So awe might have given us a social advantage or an intellectual advantage, or maybe some combination of both. But no matter why the emotion evolved, we know that it’s incredibly powerful—to the point that it can, like, totally hack your brain and body. For one thing, it can improve your physical health. It’s been linked to lower levels of inflammation, which plays a role in all sorts of illnesses. Awe can also change your perception of what ’ s causing events to unfold. Studies have found that it makes people more likely to interpret a series of events as the consequence of something intentional, as opposed to random chance. It’s all part of the search for an explanation for something your brain is struggling to comprehend, which could help us explain why religion is a thing.', NULL, NULL, NULL),
  ('d910f273-6c32-515e-9540-7b7babb37f66'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'd910f273-6c32-515e-9540-7b7babb37f66'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1a37d591-0be3-594b-a307-af1fd1367cbd'::uuid, NULL, NULL, E'Social support may enhance a person''s ability to cope with illness.', NULL, NULL),
  ('d915cb74-66cc-5a43-a19d-399b318c4267'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'd915cb74-66cc-5a43-a19d-399b318c4267'::uuid, 1, NULL, TRUE, 0, NULL, E'Foreign Languages', E'While artificial intelligence becomes so advanced, people can use computers to translate foreign languages. That makes learning a foreign language unnecessary. To what extent do you agree with it?', NULL, NULL, E'As artificial intelligence technology advances, computer translation has become increasingly accurate and accessible. Some argue that this makes learning a foreign language unnecessary. However, I strongly disagree with this viewpoint. In this essay, I will explain why learning a foreign language is still essential for personal and professional growth.\nLearning a foreign language provides numerous cognitive benefits that cannot be replicated by computer translation. For example, studies have shown that learning a foreign language can improve memory, problem-solving skills, and overall cognitive function. Furthermore, learning a foreign language can enhance cultural understanding and empathy towards others. When we learn a foreign language, we gain insight into the nuances of another culture, which can help us to become more open-minded and tolerant.\nLearning a foreign language is also important for professional growth. In today''s globalized economy, companies are increasingly seeking employees who are multilingual. Being able to speak another language can give you a competitive edge in the job market and increase your earning potential. By being able to communicate effectively with people from different cultures, you can build relationships and expand your professional network.\nIn conclusion, while computer translation has made communication easier, it cannot replace the benefits of learning a foreign language. Learning a foreign language provides cognitive and cultural benefits that are essential for personal growth, as well as professional benefits that can enhance career opportunities. Therefore, I believe that learning a foreign language is still necessary, even in the age of advanced artificial intelligence technology.', NULL, 200, 300),
  ('d9209a02-85e6-5144-920c-7f7c041c4c4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd9209a02-85e6-5144-920c-7f7c041c4c4b'::uuid, 1, NULL, TRUE, 0, NULL, E'Sun and Moon', E'In these distant times the sun was seen to make its daily {{1}} across the sky. At night the moon appeared. Every new night the moon waxed or waned a little and on a few nights it did not appear at all. At night the great dome of the heavens was dotted with tiny specks of light. They {{2}} known as the stars. It was thought that every star in the heavens had its own purpose and that the {{3}} of the universe could be discovered by making a study of them. It was well known that there were wandering stars, they appeared in different nightly positions against their neighbors and they became known as planets. It took centuries, in fact it took millennia, for man to {{4}} the true nature of these wandering stars and to evolve a model of the world to accommodate them and to {{5}} their positions in the sky.', NULL, NULL, NULL, E'1.journey, 2.became, 3.secrets, 4.determine, 5.predict', NULL, NULL),
  ('d9224c36-de9f-5b99-a6f4-d0cb8b3e9278'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd9224c36-de9f-5b99-a6f4-d0cb8b3e9278'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd6b64097-2fdf-52db-91f9-387f55581fd2'::uuid, NULL, E'To begin, let me quickly outline the rich history of our museum for you.', NULL, NULL, NULL),
  ('d92a10f7-f7bd-522f-aaa5-86865df978cd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd92a10f7-f7bd-522f-aaa5-86865df978cd'::uuid, 1, NULL, TRUE, 0, NULL, E'Taxonomy', NULL, '39f958f1-32ac-5948-b051-05d2395959f2'::uuid, NULL, E'Welcome to today''s lesson. We''re continuing with our study of taxonomy. Taxonomy is how scientists classify organisms into different groups based on the characteristics that they share. So, for instance, a good way to think about taxonomy is the US Postal Service. If we want to send a letter to someone, we first start off by addressing it to the nation they are in. By default, we usually assume that''s America but it doesn''t have to be in England or Costa Rica or Spain. You put their nation or their kingdom. Then within that kingdom, you address it to a slightly more specific level their states. So, for instance, South Carolina would be the same as a phylum. And within that state, you would address it to their city and then to their street number, the street they live on. Then you would address it to say their apartment complex and within that complex, you''d address it by their last name to their family and then finally their first name to the specific person you want to get it to and in that way we''re able to weed out all the 400 million people we don''t want to send our letter to in America and pinpoint the exact person we want the letter to reach. And in the same way, scientists use a taxonomy chart to pinpoint a living creature and organism and how it relates to everything else in the world.', NULL, NULL, NULL),
  ('d931aa6f-b823-5e56-9384-07d3789398fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'd931aa6f-b823-5e56-9384-07d3789398fd'::uuid, 1, NULL, TRUE, 0, NULL, E'Biomimicry', E'Biomimicry (from bios, meaning life, and mimesis, meaning to imitate) is a new science that studies nature''s best ideas and then imitates these designs and processes to solve human problems. Studying a leaf to invent a better solar cell is an example. I think of it as ''innovation inspired by nature.'' The core idea is that nature, imaginative by necessity, has already solved many of the problems we are grappling with. Animals, plants, and microbes are the consummate engineers. They have found what works, what is appropriate, and most important, what lasts here on Earth. This is the real news of biomimicry: After 3.8 billion years of research and development, failures are fossils, and what surrounds us is the secret to survival. Like the viceroy butterfly imitating the monarch, we humans are imitating the best and brightest organisms in our habitat. We are learning, for instance, how to harness energy like a leaf, grow food like a prairie, build ceramics like an abalone, self-medicate like a chimp, compute like a cell, and run a business like a hickory forest. The conscious emulation of life''s genius is a survival strategy for the human race, a path to a sustainable future. The more our world looks and functions like the natural world, the more likely we are to endure on this home that is ours, but not ours alone.', NULL, NULL, E'Biomimicry is a new science that studies nature''s best ideas and then imitates these designs and processes to solve human problems, whose core idea is that nature has already solved many of the problems we are grappling with, with animals, plants, and microbes being the consummate engineers, and the more our world looks and functions like the natural world, the more likely we are to endure on this home.', NULL, 5, 75),
  ('d935ffb3-8b25-5b94-b829-d3eb0ae47fbf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd935ffb3-8b25-5b94-b829-d3eb0ae47fbf'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f44742af-3bcd-548d-a65d-8ab86a9d6ad3'::uuid, NULL, E'The company has every intention of keeping the share price high.', NULL, NULL, NULL),
  ('d93fcaff-a924-54ff-b83c-e3a0f734b221'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd93fcaff-a924-54ff-b83c-e3a0f734b221'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '87230e5b-1810-54a5-83ad-d3a23d62cc5e'::uuid, NULL, E'I have made an appointment to see the doctor this morning.', NULL, NULL, NULL),
  ('d941d8ca-02fe-5f45-9054-ae8615642b70'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd941d8ca-02fe-5f45-9054-ae8615642b70'::uuid, 1, NULL, TRUE, 0, NULL, E'Lemurs', E'A research team has systematically investigated the cognitive abilities of lemurs, which have relatively small brains compared to other primates. Conducting systematic tests with identical methods revealed that cognitive abilities of lemurs hardly differ from those of monkeys and great apes. Instead, this study revealed that the relationship between brain size and cognitive abilities cannot be generalized and it provides new insights into the evolution of primates.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('d945e41a-b2c5-5938-941a-8390ade2617f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd945e41a-b2c5-5938-941a-8390ade2617f'::uuid, 1, NULL, TRUE, 0, NULL, E'Bilingual Education', E'Roberto''s story is just one of {{1}} success stories. Research has shown that bilingual education is the most {{2}} way both to teach children English and ensure that they succeed academically. In Arizona and Texas, bilingual students {{3}} outperform their peers in monolingual programs. Calexico, California implemented bilingual education, and now has dropout rates that are less than half the state average and college {{4}} rates of more than 90%. In El Paso, bilingual education programs have helped raise student scores from the lowest in Texas to among the highest in the nation.', NULL, NULL, NULL, E'1.countless, 2.effective, 3.consistently, 4.acceptance', NULL, NULL),
  ('d94a1ebe-d282-5005-bb37-7b62e13d4ebf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'd94a1ebe-d282-5005-bb37-7b62e13d4ebf'::uuid, 1, NULL, TRUE, 0, NULL, E'Project Extension', E'You are taking business night classes and your project is going to be due soon, but your computer is broken and there are some visitors to see you. You want to ask your professor for an extension over the weekend. You go to the professor''s office. What do you say to him?', '87b0e77b-407a-5812-bbe4-dd4c74095c8a'::uuid, NULL, E'Respected professor, I hope you are doing well.\nI would like to discuss an issue we have encountered with my upcoming project submission.\nIt appears that my computer is broken and I have visitors coming over, so I hope to ask for an extension for the project over the weekend.\nI would appreciate your opinion on this matter. Thank you for your consideration.', NULL, NULL, NULL),
  ('d94d5966-4151-5639-9097-9b573507fd00'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'd94d5966-4151-5639-9097-9b573507fd00'::uuid, 1, NULL, TRUE, 0, NULL, E'Trees', E'Trees, as ever, are or should be at the heart of all {{1}} on climate change. The changes in carbon dioxide, in temperature, and in patterns of rainfall will each affect them in many ways, and each parameter {{2}} with all the others, so between them, these three main {{3}} present a bewildering range of possibilities.', NULL, NULL, NULL, E'1.discussions, 2.interacts, 3.variables', NULL, NULL),
