  ('d962a424-05c0-516b-99bd-d91655141d8f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'd962a424-05c0-516b-99bd-d91655141d8f'::uuid, 1, NULL, TRUE, 0, NULL, E'Travel with Friends', E'Some people like to travel with friends, while others prefer to travel alone. Which one would you prefer?', NULL, NULL, NULL, NULL, 200, 300),
