  ('da4625ed-667d-5271-b03f-b395ea2a3d0d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'da4625ed-667d-5271-b03f-b395ea2a3d0d'::uuid, 1, NULL, TRUE, 0, NULL, E'Art Never Die', E'I do not think that the arts are dependent on philanthropic efforts, which might sound to be at odds with what I do for a living but I think that what is remarkable about the arts is that you cannot kill them. They will not die. I think of this particularly with the art form that I come out of, poetry. It actually is beautifully partnered by various social media because it can travel and be sent out in a way that fiction is a little bit trickier because fiction is...\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', 'e48b4455-b0ea-5862-8fb0-456dd951a233'::uuid, NULL, NULL, E'a longer form', NULL, NULL),
