  ('db424d9e-d422-5346-94d5-a82b4a24be3f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'db424d9e-d422-5346-94d5-a82b4a24be3f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9284b2de-01fa-58c5-a248-034a7939da09'::uuid, NULL, NULL, E'Submission of your group assignment must be made punctually by one of your group members.', NULL, NULL),
  ('db4bb8d0-f612-597b-b7d3-720bfe89c1de'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'db4bb8d0-f612-597b-b7d3-720bfe89c1de'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '475f6457-0bf9-5e3a-874f-beff6512d682'::uuid, NULL, E'All students should participate in the upcoming elections for encouragement.', NULL, NULL, NULL),
  ('db4d91a8-f7a0-5373-bc05-e8b53fbe1e85'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'db4d91a8-f7a0-5373-bc05-e8b53fbe1e85'::uuid, 1, NULL, TRUE, 0, NULL, E'Federal Reserve', E'The Federal Reserve is not funded by Congress. Instead, it''s funded by the interest earned on securities it buys, plus fees it receives for services it provides to banking institutions, including check clearing and fund transferring. All net earnings of the Federal Reserve Banks are transferred to the U.S. Treasury.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('db4f85a9-16d8-504e-aa91-2e555cc4428b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'db4f85a9-16d8-504e-aa91-2e555cc4428b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'dba34de2-939f-5945-8675-d46cc63c9ff0'::uuid, NULL, E'The capacity to listen to colleagues is often considered a great skill.', NULL, NULL, NULL),
  ('db55f8ef-dd68-57f4-a0af-34d5942e1845'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'db55f8ef-dd68-57f4-a0af-34d5942e1845'::uuid, 1, NULL, TRUE, 0, NULL, E'Piano', NULL, NULL, NULL, NULL, E'3, 4, 1, 2', NULL, NULL),
  ('db5941f6-babf-5894-82c4-ad885263dbb0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'db5941f6-babf-5894-82c4-ad885263dbb0'::uuid, 1, NULL, TRUE, 0, NULL, E'Balance of Nature', E'An understanding of man''s effect on the balance of nature is crucial to being able to find the appropriate remedial action. It is a very common belief that the problems of the population explosion are caused mainly by poor people living in poor countries who do not know enough to limit their reproduction. This is not true. The actual number of people in an area is not as important as the effect they have on nature. Developing countries do have an effect on their environment, but it is the populations of richer countries that have a far greater impact on the earth as a whole. For example, tropical forests are known to be essential to the balance of nature, yet we are destroying them at a great rate. They are being cleared not to benefit the natives of that country, but to satisfy the needs of rich countries. Central American forests are being destroyed for grassland to make pet food in the United States cheaper; in Papua New Guinea, forests are destroyed to supply cheaper cardboard packaging for Japanese electronic products; in Burma and Thailand, forests have been destroyed to produce more attractive furniture in Singapore and Hong Kong. Therefore, a rich person living thousands of miles away may cause more tropical forest destruction than a poor person living in the forest itself.\n\nIn the author''s opinion,', NULL, NULL, NULL, E'rich countries exercise worse influence on environment than poor countries.', NULL, NULL),
  ('db6253bd-8ad5-5a9b-b679-d7e4f1919385'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'db6253bd-8ad5-5a9b-b679-d7e4f1919385'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '42d5793b-d228-5809-a6b2-42f96a99ca0b'::uuid, NULL, NULL, E'The research paper examined the economies of three countries.', NULL, NULL),
  ('db638ff2-48aa-5507-a9f9-3d8d000e641e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'db638ff2-48aa-5507-a9f9-3d8d000e641e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'fb75762b-80f0-582c-ad96-47d6f7c8c01f'::uuid, NULL, NULL, E'Sugar consists of carbon, hydrogen, and oxygen in small amounts.', NULL, NULL),
  ('db6f0f68-5872-5a59-9220-d7d80b63871a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'db6f0f68-5872-5a59-9220-d7d80b63871a'::uuid, 1, NULL, TRUE, 0, NULL, E'Online Campus', E'Remember when universities were bursting at the seams with students sitting in the aisles, balancing books on their knees? No more, it seems. E-learning is as likely to stand for empty lecture theatres as for the internet {{1}} , which has greatly increased the {{2}} and range of course materials available online in the past five years. " The {{3}} now is to simply think, ''Everything will be online so I don''t need to go to class''," said Dr Kerri-Lee Krause, of the Centre for the Study of Higher Education at the University of Melbourne. The nation''s universities are in the process of opening the doors for the new academic year and, while classes are generally well {{4}} for the early weeks, it often does not last. " There is concern at the university level about student attendance dropping and why students are not coming to lectures,"Dr Krause said. But lecturers'' pride - and {{5}} competition among universities for students - mean few are willing to acknowledge publicly how poorly attended many classes are.', NULL, NULL, NULL, E'1.revolution, 2.volume, 3.temptation, 4.attended, 5.fierce', NULL, NULL),
  ('db762517-0300-51a7-94ea-73e3b9e2a4ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'db762517-0300-51a7-94ea-73e3b9e2a4ee'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'If any experiment is duplicated, how many times it is performed?', '357029a6-b72c-5eee-8a52-85da5f0b6b70'::uuid, NULL, NULL, E'Two / twice', NULL, NULL),
  ('db7b3861-c9e8-55e3-aa37-6b8f793d25d2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'db7b3861-c9e8-55e3-aa37-6b8f793d25d2'::uuid, 1, NULL, TRUE, 0, NULL, E'Active Brain', E'Keeping the brain active and engaged appears to combat the cognitive decline associated with getting older. Now a study has found a new, but related, factor in maintaining a sharp mind—the space in which we live.\nResearchers recruited almost 1,300 senior citizens, none of whom showed any signs of clinical dementia at the start of the study. The participants had their cognitive function tested annually for up to eight years. And they also described their living space. For example, maybe they mostly hung around their bedroom. Perhaps they spent time in the yard. Or frequently traveled.\nBy the end of the study, 180 people had Alzheimers. And those whose {{1}} narrowed in on their immediate home were almost twice as likely to develop the {{2}} as those who ventured out. The homebound folks also had an {{3}} risk of other cognitive impairments and a faster rate of cognitive decline. The research was published in the American Journal of Geriatric Psychiatry.\nThe study''s lead investigator, Bryan James of the Rush University Medical Center in Chicago, {{4}} that, "Perhaps life space is an indicator of how much we are {{5}} engaging and challenging our cognitive {{6}} ."', NULL, NULL, NULL, E'1.life-space, 2.condition, 3.increased, 4.suggests, 5.actively, 6.abilities', NULL, NULL),
  ('db7cc692-d1fa-5859-bdf9-181b24f9dddb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'db7cc692-d1fa-5859-bdf9-181b24f9dddb'::uuid, 1, NULL, TRUE, 0, NULL, E'Pig Kidney Transplantation', NULL, NULL, NULL, NULL, E'1, 3, 4, 2', NULL, NULL),
