  ('db92e9a1-cf43-55ca-bd94-596711f0777e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'db92e9a1-cf43-55ca-bd94-596711f0777e'::uuid, 1, NULL, TRUE, 0, NULL, E'Black Hole', E'A black hole is an astronomical object with a gravitational pull {{1}} powerful that nothing can escape from it, including light. Black holes form when massive stars collapse at the end of their lifecycle. This collapse causes a singularity, a point where density and gravity become infinite. Surrounding the singularity is the event horizon - the boundary past which no matter or information can escape from the intense gravitational effects. Supermassive black holes likely {{2}} at the center of most large galaxies. Evidence {{3}} the giant elliptical galaxy Messier 87 contains a supermassive black hole over 6 billion times the mass of our sun. NASA recently captured the first image of this black hole’s event horizon and shadow, providing {{4}} into its formation and behavior. Understanding more about black holes will shed light on galaxies’ formations, the fundamental laws of physics, and intricate processes occurring at the edge of a black hole’s event horizon still shrouded in mystery.', NULL, NULL, NULL, E'1.so, 2.exist, 3.indicates, 4.clues', NULL, NULL),
  ('db949084-b4da-5df1-9023-cb0d111de845'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'db949084-b4da-5df1-9023-cb0d111de845'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8e75b0b2-ebd8-5450-b1ac-5adfe84bf75d'::uuid, NULL, NULL, E'The English degree involves certain work placements in the third year.', NULL, NULL),
