  ('dbac59b9-4150-5807-b4e7-3b1a90210ddc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'dbac59b9-4150-5807-b4e7-3b1a90210ddc'::uuid, 1, NULL, TRUE, 0, NULL, E'Vaping', E'Amid growing concern over the rapid rise of vaping particularly among the young, and the controversy over its effect on health, Malaysia is set to {{1}} a game-changing law to ban smoking and vaping for an entire generation, those born from 2007. Currently, the vape industry operates in a legal grey area in the country. While vaping is not regulated, the sale of e-liquids containing nicotine – while commonplace – is technically illegal. And several states including Johor have {{2}} the sale of vaping products. E-liquids are a component of e-vaporisers, also known as vapes or e-cigarettes. The liquids often contain nicotine and, when heated, turn into vapor that is {{3}} by users. Vapes are {{4}} by advocates as a smoking cessation tool. Oh for instance, said: “We are not claiming vapes as a 100-per-cent healthy product. We are selling vape as harm reduction compared to smoking.”', NULL, NULL, NULL, E'1.introduce, 2.prohibited, 3.inhaled, 4.touted', NULL, NULL),
  ('dbc696af-a4ec-50bb-a238-4f55f996ea92'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dbc696af-a4ec-50bb-a238-4f55f996ea92'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What piece of equipment would you use to go diving in a sea 一 an aquaplane or an aqualung?', 'ef762894-8cb8-5818-9338-7940366cd3e6'::uuid, NULL, NULL, E'Aqualung', NULL, NULL),
