  ('dbd0d21e-7cc7-50ef-9156-6a00e3eaa860'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dbd0d21e-7cc7-50ef-9156-6a00e3eaa860'::uuid, 1, NULL, TRUE, 0, NULL, E'Gator Hunter', E'Nell and his colleagues took to the Everglades at night, hunting for gators near and far from nests.'' You have to use a spotlight and you see the little demon eyes shining out of the marsh.'' They lassoed the gators, pulled them into the airboat, and took blood samples and body measurements.', NULL, NULL, NULL, NULL, NULL, NULL),
