  ('dbdb9729-d9f7-5c57-a406-5ff91d33d7d9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'dbdb9729-d9f7-5c57-a406-5ff91d33d7d9'::uuid, 1, NULL, TRUE, 0, NULL, E'Ancient Paintings', E'Ancient paintings offer a fascinating glimpse into the lives, beliefs, and artistic skills of early civilizations. Many of these paintings were created on cave walls or pottery and have survived for thousands of years due to their {{1}} . The subjects of ancient paintings often include animals, humans, and scenes from daily life. These artworks were not only meant for decoration but also had {{2}} significance. For instance, some cave paintings are believed to have been created for ritualistic purposes or to convey stories and {{3}} . The use of natural pigments and {{4}} techniques highlights the resourcefulness and creativity of ancient artists. Despite the passage of time, the beauty and intricacy of ancient paintings continue to captivate and inspire modern audiences.', NULL, NULL, NULL, E'1.preservation, 2.religious, 3.folklore, 4.traditional', NULL, NULL),
  ('dbddafa6-f871-5a61-9a91-ae5522f5eb6f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dbddafa6-f871-5a61-9a91-ae5522f5eb6f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '57ac1251-735f-5e37-b3a3-61200dcc4afe'::uuid, NULL, E'We spend the time presenting the information in a variety of chart forms.', NULL, NULL, NULL),
