  ('dc94c6a2-d26b-521c-aff5-73132e0ab6ae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dc94c6a2-d26b-521c-aff5-73132e0ab6ae'::uuid, 1, NULL, TRUE, 0, NULL, E'Blood Pressure', E'The correlation between elevated blood pressure levels and a multitude of health complications is widely acknowledged. However, recent studies have shed light on an equally concerning aspect. Researchers have discovered that these fluctuations in blood pressure can not only be detrimental to overall health but also act as a potential precursor to the development of dementia and vascular disease.', NULL, NULL, NULL, NULL, NULL, NULL),
