  ('dc9b6f07-0ace-53ef-ac0a-c907bb252bcb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'dc9b6f07-0ace-53ef-ac0a-c907bb252bcb'::uuid, 1, NULL, TRUE, 0, NULL, E'Pollination', E'According to a research conducted by Cambridge University, flowers can find their own ways to attract insects to help them pollinate. Flowers will release an {{1}} smell. A scientist and her {{2}} did an experiment in which they use fake flowers to attract bees and insects. In their experiments, they freed many bumblebees from their {{3}} repeatedly and got the same results.', NULL, NULL, NULL, E'1.irresistible, 2.colleagues, 3.origins', NULL, NULL),
