  ('dca38319-af8d-5a24-aa4d-5b6d779b217e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'dca38319-af8d-5a24-aa4d-5b6d779b217e'::uuid, 1, NULL, TRUE, 0, NULL, E'Mural Projects', E'Mural projects are an increasingly popular form of public art that {{1}} outdoor spaces into public art galleries. Our research explored this intersection of public space, public art and public memory through The Big Wash Up. Using a {{2}} called reverse graffiti, the project {{3}} dozens of outdoor murals. Their focus on local themes and characters celebrated community {{4}} , heritage and memory. The process simultaneously honored community memories while creating new shared memories.', NULL, NULL, NULL, E'1.transforms, 2.technique, 3.created, 4.identity', NULL, NULL),
