  ('dcae9ea6-9da8-53a8-adfd-4ab9a541bcb7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'dcae9ea6-9da8-53a8-adfd-4ab9a541bcb7'::uuid, 1, NULL, TRUE, 0, NULL, E'Rosetta Stone', NULL, NULL, NULL, NULL, E'2, 4, 3, 1', NULL, NULL),
  ('dcb30b55-d6b8-58b4-a018-bdcd4c7daab1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dcb30b55-d6b8-58b4-a018-bdcd4c7daab1'::uuid, 1, NULL, TRUE, 0, NULL, E'Biggish City', NULL, '9b383ec5-45c9-5a44-812b-23e5938849b6'::uuid, NULL, E'We have briefly looked at some of the problems involved in running a biggish city like, say, Melbourne, keeping the road and rail systems running, policing, providing food and housing, and so on. In another lecture, I''m going to deal with what we must no megalopolis - cities with populations of ten million or more. However, first I want to go back in history to when the population of cities could be numbered in the thousands rather than millions. One of the earliest theorists of the city was, of course, Plato, who created an ideal city in his text, The Republic. The population of this city would be around twenty-five to thirty thousand at most. Oddly enough, the same figures were chosen by Leonardo da Vinci for his ideal cities.\nNow, of these twenty five to thirty inhabitants only about five thousand would be citizens. A reason for this might be that it is the largest number that could be addressed publicly at one time and by one person, and makes a voting system much easier to manage. Also, perhaps the numbers are kept deliberately low because a large population would be harder to control, or because, in practical terms, fewer inhabitants are easier to feed from local supplies without having to depend on outside sources.', NULL, NULL, NULL),
  ('dcc8ce47-cb6d-5c5c-a191-7a14612c0c83'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dcc8ce47-cb6d-5c5c-a191-7a14612c0c83'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Where do buses stop?', 'd6983259-70b8-5b15-9e7e-caf39af0cd29'::uuid, NULL, NULL, E'Bus stop / bus terminal / bus station', NULL, NULL),
  ('dccca948-b8e7-5814-9384-9e5b3672e4d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dccca948-b8e7-5814-9384-9e5b3672e4d5'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is another way to say the arrangement of musical notes in a tune?', 'f4dcb5ed-c5b3-5104-8922-982a58b4cd53'::uuid, NULL, NULL, E'Melody', NULL, NULL),
  ('dcd228a2-b410-5fdc-9ccb-42ff47da759a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'dcd228a2-b410-5fdc-9ccb-42ff47da759a'::uuid, 1, NULL, TRUE, 0, NULL, E'Dementia', E'Dementia is the loss of cognitive functioning — thinking, remembering, and reasoning — to such an extent that it interferes with a person''s daily life and activities. Some people with dementia cannot control their emotions, and their personalities may change. Dementia ranges in severity from the mildest stage, when it is just beginning to affect a person''s functioning, to the most severe stage, when the person must depend completely on others for basic activities of living.\nAbout one-third of all people age 85 or older may have some form of dementia, but it is not a normal part of aging. Many people live into their 90s and beyond without any signs of dementia. Signs and symptoms of dementia result when once-healthy neurons or nerve cells in the brain stop working, lose connections with other brain cells, and die. While everyone loses some neurons as they age, people with dementia experience far greater loss.\nPeople with intellectual and developmental disabilities can also develop dementia as they age, and recognizing their symptoms can be particularly difficult. It’s important to consider a person’s current abilities and to monitor for changes over time that could signal dementia.\nThe causes of Alzheimer’s and related dementia can vary, depending on the types of brain changes that may be taking place. While research has found that some changes in the brain are linked to certain forms of dementia, in most cases, the underlying causes are unknown. Rare genetic mutations may cause dementia in a relatively small number of people.\nAlthough there is no proven prevention, in general, leading a healthy lifestyle may help reduce risk factors that have been associated with these diseases.', NULL, NULL, NULL, NULL, 5, 75),
  ('dcd7b5b4-8763-53a6-b44f-bb6e6c6cac41'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'dcd7b5b4-8763-53a6-b44f-bb6e6c6cac41'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '80742a3a-3eb7-5e99-9a18-dc19c6b2b33a'::uuid, NULL, NULL, E'The best managers are always open to trying new things.', NULL, NULL),
