  ('dce79364-4d35-5542-8148-b6b0f32284df'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dce79364-4d35-5542-8148-b6b0f32284df'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6690640c-88d5-50d9-bc0f-1ae0499e140e'::uuid, NULL, E'The office said Dr. Smith will arrive later today.', NULL, NULL, NULL),
  ('dcea7811-1227-5b53-aaa7-504a5f8dcaa7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'dcea7811-1227-5b53-aaa7-504a5f8dcaa7'::uuid, 1, NULL, TRUE, 0, NULL, E'French Lord', E'France was still essentially a feudal nation with lords, due to a range of ancient and modern rights from their peasants who comprised about 80 percent of the population and the majority lived in rural contexts. France was a predominantly agricultural nation, even though this agriculture was low in productivity, wasteful, and using out of date methods. An attempt to introduce modern techniques from Britain had not succeeded. Inheritance laws, {{1}} estates were divided up among all the heirs, had {{2}} France divided into many tiny farms; {{3}} the large estates were small when compared to other European nations. The only major region {{4}} large-scale farming was around Paris, where the always hungry capital city provided a convenient market. Harvests were critical but fluctuating, causing famine, high prices, and riots.', NULL, NULL, NULL, E'1.whereby, 2.left, 3.even, 4.of', NULL, NULL),
  ('dcef0f03-056a-5c39-90e2-37cd2124b72e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dcef0f03-056a-5c39-90e2-37cd2124b72e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd6706fbd-f449-5f83-8fab-f083f239326d'::uuid, NULL, E'There is plenty of cheap accommodation off campus.', NULL, NULL, NULL),
