  ('dcf22abb-a013-540a-b7f5-3c2dc6dc7b10'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'dcf22abb-a013-540a-b7f5-3c2dc6dc7b10'::uuid, 1, NULL, TRUE, 0, NULL, E'Economic Dimension', E'The difference in {{1}} is so great that one wonders. "Are the protesters and the policy makers talking about the same {{2}} ? Are they looking at the same data? Are the visions of those in {{3}} so clouded by special and particular {{4}} ?"', NULL, NULL, NULL, E'1.views, 2.phenomenon, 3.power, 4.interests', NULL, NULL),
  ('dcf60b37-051c-5bae-b743-b56f8b7abbd8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'dcf60b37-051c-5bae-b743-b56f8b7abbd8'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '333b922b-7a4d-57be-a131-2f7d67f86699'::uuid, NULL, NULL, E'The scientists found most of the studies today.', NULL, NULL),
  ('dcf75989-c998-5e2f-b499-f921ff2886c2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dcf75989-c998-5e2f-b499-f921ff2886c2'::uuid, 1, NULL, TRUE, 0, NULL, E'Breaking Habits', E'Breaking habits is very difficult. The easiest way is to control your environment so that you do not encounter the cue which triggers your habit. It is difficult to break any habit even when you are motivated to do so. If you are ambivalent about breaking it, then you will be less likely to succeed.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('dcf8dfd9-2e5f-5b24-8efa-b3f1a2cf1ed4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'dcf8dfd9-2e5f-5b24-8efa-b3f1a2cf1ed4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '32739d0a-1c4d-569d-b267-81fea3431c04'::uuid, NULL, NULL, E'The field study on Wednesday has been canceled.', NULL, NULL),
  ('dcfd2cd8-1709-56f4-8451-406afb25d243'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'dcfd2cd8-1709-56f4-8451-406afb25d243'::uuid, 1, NULL, TRUE, 0, NULL, E'Keith Haring', E'Keith Haring began as an underground artist, literally. His first famous projects were pieces of stylized graffiti {{1}} in New York subway stations. Haring travelled from station to station, drawing with chalk and chatting with commuters about his work. These doodles helped him develop his classic style and he grew so {{2}} , doing up to 40 drawings a day, that it was not long before fame and a measure of fortune followed.\nSoon, galleries and collectors from the art establishment wanted to buy full-sized pieces by Haring. The paintings skyrocketed in price but this did not sit well with Haring''s philosophy. He believed that art, or {{3}} his art, was for everyone. Soon, Haring opened a store which he called the Pop Shop, which he hoped would attract a broad range of people. While somewhat controversial among street artists, some of {{4}} accused Haring of ''selling out'', the Pop Shop changed the way people thought about the relationship between art and business.', NULL, NULL, NULL, E'1.drawn, 2.prolific, 3.at least, 4.whom', NULL, NULL),
  ('dcfe4214-f61d-5015-b365-7acf80694a0e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'dcfe4214-f61d-5015-b365-7acf80694a0e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5f356a3d-7e31-560f-b24a-b2f994330c48'::uuid, NULL, NULL, E'Every student develops a unique approach to their learning process.', NULL, NULL),
  ('dcff5555-067e-5d1f-b6ec-b73433130fcb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dcff5555-067e-5d1f-b6ec-b73433130fcb'::uuid, 1, NULL, TRUE, 0, NULL, E'Stars', E'Stars are the most widely recognized astronomical objects, and represent the most fundamental building blocks of galaxies. The age and composition of the stars in a galaxy trace the dynamics and evolution of that galaxy. Consequently, the study of the birth, life, and death of stars is central to the field of astronomy.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('dd02bafb-c6bf-5fa1-9e9c-efcc7bc6981a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'dd02bafb-c6bf-5fa1-9e9c-efcc7bc6981a'::uuid, 1, NULL, TRUE, 0, NULL, E'Small Lakes', E'Small lakes with a surface area of less than 100 square meters represent the majority of global freshwater ecosystems. Many of these lakes {{1}} in remote, often mountainous areas with no inflow and outflow. Yet in most of these lakes, there are fish. So {{2}} do fish reach lakes and ponds that are not connected to other bodies of water?\nThis question {{3}} addressed by some of the leading natural scientists of the 19th century such as Charles Darwin, Alfred Russel Wallace and Charles Lyell, who all came to the same conclusion—water birds must be {{4}} fish dispersal.\nAnd they had a plausible explanation for this: fish eggs of some species are sticky and can survive for some time out of water. The theory is thus that the fish eggs {{5}} to water birds'' feathers or feet; the birds then fly from one body of water to the next, where the fish hatch from their eggs.', NULL, NULL, NULL, E'1.are found, 2.how, 3.was already, 4.responsible for, 5.stick', NULL, NULL),
  ('dd170466-9ba3-58f7-a74e-4c515de8761c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'dd170466-9ba3-58f7-a74e-4c515de8761c'::uuid, 1, NULL, TRUE, 0, NULL, E'Blogging Personalities', E'Analysts surveyed content from thousands of personal blogs, and {{1}} that most blog posts focus on lifestyle and personal experiences, with bloggers often using their platforms to showcase their expertise or hobbies. Relationship and community-themed blogs were also {{2}} ,with a substantial number {{3}} to cultural heritage and travel. The data suggested that bloggers {{4}} write individually rather than in groups, with millennials being the most active demographic.', NULL, NULL, NULL, E'1.discovered, 2.prevalent, 3.dedicated, 4.predominantly', NULL, NULL),
  ('dd1cff44-a312-57b4-a71f-ef6b37525552'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dd1cff44-a312-57b4-a71f-ef6b37525552'::uuid, 1, NULL, TRUE, 0, NULL, E'Non-Governmental Organization', NULL, '940e15cc-da6b-5d7f-ab11-dfc1add07c0e'::uuid, NULL, E'I marveled at how often powerful Phil powerless but in the face of this sense of disempowerment, there''s no decline in involvement in organizations which seek to share wealth and opportunities. We seek to protect one another''s rights and work towards the common good. According to the UN, civil society groups have grown 40-fold since the turn of last century, sorry, since the turn of, yes, last century. Internationally, the non-profit sector is worth one trillion dollars, and there are 700,000 non-profitable organizations in Australia alone, 700,000. UN recognizes 37,000 specifically civil society organizations across the globe, working international relief, and gives accreditation to many of them.\nThis profound movement towards harnessing voices and resources from outside the realm of governments and officialdom reflects a growth in trust, "the third sector", NGOs. Putnam discovered in the field of local government in Italy, the best predictor of governmental success was the strength and density of a region''s civic associations.', NULL, NULL, NULL),
  ('dd2d85b7-e90a-5f72-b47c-1c7066dbfe4a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dd2d85b7-e90a-5f72-b47c-1c7066dbfe4a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f371323b-7fd0-5fe1-829d-eec182046242'::uuid, NULL, E'Students can download the lecture handouts from the course website.', NULL, NULL, NULL),
  ('dd2d8c54-1732-5f8e-8aa6-81933b034f5b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'dd2d8c54-1732-5f8e-8aa6-81933b034f5b'::uuid, 1, NULL, TRUE, 0, NULL, E'Poincaré', NULL, NULL, NULL, NULL, E'2, 4, 1, 3', NULL, NULL),
  ('dd2f8add-b219-5c61-927b-35adf6f2a9f2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'dd2f8add-b219-5c61-927b-35adf6f2a9f2'::uuid, 1, NULL, TRUE, 0, NULL, E'Cat Myths', NULL, NULL, NULL, NULL, E'1, 4, 3, 2', NULL, NULL),
  ('dd32bbf9-5f23-5a9c-87b7-e9cc92c19fef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'dd32bbf9-5f23-5a9c-87b7-e9cc92c19fef'::uuid, 1, NULL, TRUE, 0, NULL, E'Experimental Work', E'Scientists use research articles to {{1}} their research findings and scientific claims. These articles are not just factual {{2}} of experimental work; the authors also try to convince the reader that their {{3}} is correct. It is now easier than {{4}} to read the original research behind science stories in the media, as more and more articles are being made freely available through open-access {{5}} .', NULL, NULL, NULL, E'1.communicate, 2.reports, 3.argument, 4.ever, 5.publishing', NULL, NULL),
  ('dd39024a-6504-536f-9b18-63a5e73bc05d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'dd39024a-6504-536f-9b18-63a5e73bc05d'::uuid, 1, NULL, TRUE, 0, NULL, E'Learning Process', E'Learning is a process by which behavior or knowledge changes as a result of experience. Learning from experience plays a major role {{1}} enabling us to do many things that we clearly were not born to do, from the simplest tasks, such as flipping a light switch, to the more {{2}} , such as playing a musical instrument. To many people, the term '' learning'' signifies the {{4}} that students do reading, listening, and taking tests in order to acquire new information. This process, which is known as cognitive learning, is just {{5}} type of learning, however. Another way that we learn is by associative learning, which is the focus of this module. You probably associate {{6}} holidays with specific sights, sounds, and smells, or foods with specific flavors and textures. We are not the only {{7}} with this skill even the simplest animals such as the earthworm can learn by association.', NULL, NULL, NULL, E'1.in, 2.complex, 3.activities, 4.one, 5.certain, 6.species', NULL, NULL),
  ('dd46ddaa-df95-5179-a08c-530b4d4512e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dd46ddaa-df95-5179-a08c-530b4d4512e9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b5957702-516e-57b1-bd5e-8123510b4e56'::uuid, NULL, E'Children enjoy a healthy lifestyle when they live in a healthy family.', NULL, NULL, NULL),
  ('dd51e772-960c-585a-905f-43c23c0890e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dd51e772-960c-585a-905f-43c23c0890e9'::uuid, 1, NULL, TRUE, 0, NULL, E'Castle Dove', E'Ministers have rehearsed for the Queen''s death for the first time with a secret exercise to prepare for 10 days of national mourning, it has emerged. The run-through, apparently known as Castle Dove, saw Cabinet ministers and Whitehall officials discuss ''D+1'', the day after the monarch''s death.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('dd5489e1-3fdb-5142-9377-3c5ed06befef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'dd5489e1-3fdb-5142-9377-3c5ed06befef'::uuid, 1, NULL, TRUE, 0, NULL, E'Highway Hypnosis', E'Have you ever driven home and arrived at your destination without remembering how you got there? No, you weren’t abducted by aliens or taken over by your alternate persona. You simply experienced highway hypnosis. Highway hypnosis or white line fever is a trance-like state under which a person drives a motor vehicle in a normal, safe manner yet has no recollection of having done so. Drivers experiencing highway hypnosis may zone out for short distances or hundreds of miles. Highway hypnosis is an example of the phenomenon of automaticity, which is the ability to perform actions without consciously thinking about them. People perform daily activities automatically all the time, such as walking, riding a bike, or performing a learned and practiced skill, such as knitting. Once a skill is mastered, it’s possible to perform it while focusing on other tasks. For example, a person skilled at driving a car can plan a grocery list while driving. Because the stream of consciousness is directed at the other task, partial or complete amnesia of the time spent driving can occur. While driving on automatic may seem hazardous, automaticity may actually be superior to conscious driving for professional or skilled drivers. When a person experiencing true highway hypnosis automatically scans the environment for threats and alerts the brain of danger, it is the typical distinction from dangerous fatigued driving.', NULL, NULL, NULL, NULL, 5, 75),
  ('dd5496d5-fe08-5859-83a0-fe7d36744145'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dd5496d5-fe08-5859-83a0-fe7d36744145'::uuid, 1, NULL, TRUE, 0, NULL, E'When to Meet', E'You are meeting a friend this weekend, but you haven''t decided on a specific time yet. You need to discuss when to meet. What would you say to the friend?', 'a0d63b66-717a-5b9b-bf3a-318fedd9a9d5'::uuid, NULL, NULL, NULL, NULL, NULL),
