  ('dd691261-5800-596c-9b8d-05c7e6e54c50'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dd691261-5800-596c-9b8d-05c7e6e54c50'::uuid, 1, NULL, TRUE, 0, NULL, E'Universities of Europe', E'During the Early Modern period, the universities of Europe would see a tremendous amount of growth, productivity, and innovative research. At the end of the Middle Ages, about 400 years after the first European university was founded, there were twenty-nine universities spread throughout Europe.', NULL, NULL, NULL, NULL, NULL, NULL),
