  ('dd8d1559-6979-57c1-96b2-2633e2473d9e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'dd8d1559-6979-57c1-96b2-2633e2473d9e'::uuid, 1, NULL, TRUE, 0, NULL, E'Financial Crisis', E'Since the beginning of the financial crisis, there have been two principal {{1}} for why so many banks made such disastrous decisions. The first is structural. Regulators did not regulate. Institutions failed to {{2}} as they should. Rules and guidelines were either inadequate or ignored. The second explanation is that Wall Street was {{3}} , that the traders and investors didn''t know enough, that they made extravagant bets without {{4}} the consequences.', NULL, NULL, NULL, E'1.explanations, 2.function, 3.incompetent, 4.understanding', NULL, NULL),
  ('dd932de9-ac7a-5cda-a864-46bd2b882971'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'dd932de9-ac7a-5cda-a864-46bd2b882971'::uuid, 1, NULL, TRUE, 0, NULL, E'American Arts', E'The United States in the 1800''s was full of {{1}} , hardworking people who did not consider the arts -- from theater to painting -- useful {{2}} . In addition, the public’s attitude that European art was better than American art both {{3}} and infuriated American artists. In the early 1900’s there was a strong feeling among artists that the United States was long {{4}} in developing art that did not reproduce European traditions.', NULL, NULL, NULL, E'1.practical, 2.occupations, 3.discouraged, 4.overdue', NULL, NULL),
  ('dd97d58b-eba9-552e-a8b7-8f02a1a138cf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'dd97d58b-eba9-552e-a8b7-8f02a1a138cf'::uuid, 1, NULL, TRUE, 0, NULL, E'Teams', E'You hear a lot about teams every day — sports teams, disaster and rescue teams, and medical support teams. Teams {{1}} because they are effective in achieving goals, especially when the goal is well-defined. In the business environment, {{2}} on teams has been growing in the last few decades as organizations become more {{3}} (operating over distance) and more structurally complex. Businesses rely on teams to {{4}} tasks not well suited to more traditional organizational structures. The most common types of teams are discussed in this section.', NULL, NULL, NULL, E'1.exist, 2.reliance, 3.virtual, 4.perform', NULL, NULL),
  ('dd98c51a-b422-5bfb-9bd1-ddec7a22247e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'dd98c51a-b422-5bfb-9bd1-ddec7a22247e'::uuid, 1, NULL, TRUE, 0, NULL, E'Certain Jobs', E'There are more men or women in certain jobs and there’s nothing we can change about it. Do you agree with that?', NULL, NULL, NULL, NULL, 200, 300),
  ('dd9eb577-513c-5693-8936-816813b39f6a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'dd9eb577-513c-5693-8936-816813b39f6a'::uuid, 1, NULL, TRUE, 0, NULL, E'Management Accounting', E'Management accounting is concerned with providing information and {{1}} to managers to help them plan, evaluate and control activities, in order to achieve an organization’s {{2}} . Whereas financial accounting is concerned with reporting on the past financial performance of an organization, management accounting is essentially concerned with improving its future performance. In order to understand the {{3}} and principles of management accounting it is necessary first to have some {{4}} of what managers do! This, in turn, requires an understanding of the organizations in which managers work – and of the external environment in which these organizations exist and operate.', NULL, NULL, NULL, E'1.analysis, 2.objectives, 3.concepts, 4.appreciation', NULL, NULL),
  ('dd9ed636-9d75-5c4d-833a-f9f50dd66ecd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'dd9ed636-9d75-5c4d-833a-f9f50dd66ecd'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1a145dfe-8781-5e9d-97d0-4cc6611a97ac'::uuid, NULL, NULL, E'Learning how to teach can involve watching other teachers teach.', NULL, NULL),
  ('dda152ba-287a-57c8-a6f3-2b4cf0a6af99'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'dda152ba-287a-57c8-a6f3-2b4cf0a6af99'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4265858f-61f9-53b2-a02c-efd88ccceb91'::uuid, NULL, NULL, E'The world is now getting warmer at a fast rate.', NULL, NULL),
  ('dda439eb-d022-5724-95aa-b7df1c6831eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'dda439eb-d022-5724-95aa-b7df1c6831eb'::uuid, 1, NULL, TRUE, 0, NULL, E'Cannabis', E'Cannabis is a widely used substance that can have various effects on the brain and behavior. One of the aspects that cannabis may influence is {{1}} people perceive and respond to emotions, both their own and others’. A new study by researchers at Colorado State University sheds some light on the way cannabis affects the recognition and processing of human emotions like happiness, sadness and anger. The study used an electroencephalogram to measure the brain activity of about 70 volunteers, who {{2}} themselves as chronic, moderate or non-users of cannabis. The participants were shown faces with different {{3}} and asked to either identify the emotion or the sex of the face. The researchers found that cannabis users showed more brain activity when they saw negative emotions, {{4}} anger, than non-users. However, cannabis users also showed less brain activity when they saw positive emotions, such as happiness, than non-users. The researchers concluded that cannabis affects the brain’s ability to process emotion, but that the brain may be able to successfully {{5}} the effects, depending on whether the emotions are explicitly or implicitly detected.', NULL, NULL, NULL, E'1.how, 2.identified, 3.expressions, 4.especially, 5.counter', NULL, NULL),
  ('dda47e4e-78b8-5aa8-b952-5a052c1876ea'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'dda47e4e-78b8-5aa8-b952-5a052c1876ea'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '49060877-5046-5c07-9157-47a2ed91fef0'::uuid, NULL, NULL, E'The American astronomers made a plan for landing a spaceship on Mars.', NULL, NULL),
