  ('ddac365d-bd57-5c28-a0fd-1048df507b49'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ddac365d-bd57-5c28-a0fd-1048df507b49'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'cdd7d088-230b-5b86-b579-eeda094f1549'::uuid, NULL, NULL, E'Many universities'' lectures can now be reviewed on the Internet.', NULL, NULL),
  ('ddac833b-b68f-50c9-ba2a-5be159d1d9a0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ddac833b-b68f-50c9-ba2a-5be159d1d9a0'::uuid, 1, NULL, TRUE, 0, NULL, E'Martin Luther King', E'In nineteen sixty three, Martin Luther King Junior led a massive demonstration in birmingham, alabama. The protest was against racism. In the united states, people, including children and teenagers, took to the streets to fight for their rights. However, tragically, police officers and fire fighters try to stop them with dogs and high pressure water hoses. They were brutally attacked by dogs and torrents of water from fire hoses. These scenes were shown in newspapers and on televisions around the world. Of course, these scenes touched people''s hearts. So the demonstrators gain support against segregation.\n\nWhat was the purpose of the demonstration led by Martin Luther King, Jr.?', 'af42e6f4-146b-5c1a-8a23-fb1b12f33000'::uuid, NULL, NULL, E'The purpose was to fight against racism and segregation.', NULL, NULL),
  ('ddaf5d47-6590-5c09-92a2-fa257071b918'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ddaf5d47-6590-5c09-92a2-fa257071b918'::uuid, 1, NULL, TRUE, 0, NULL, E'Memory Illusion', E'When considering what makes us who we are, it is easy to think our memories are the answer. Aside from the physical traces of the passing of time on your body, your {{1}} are perhaps the only thing that links the you sitting here today to the many yous from every previous day of your existence. Without them, your relationships would mean nothing, not to {{2}} your knowledge, tastes, and your many adventures. It might be no {{3}} to say your memories are the essence of you. With this in mind, it is not surprising that much of the burgeoning field of neuroscience has turned its efforts to understanding what makes a memory and how to keep hold of it. Perhaps the most {{4}} idea to come from recent discoveries is a re-imagining of the dark side of memory – forgetting.', NULL, NULL, NULL, E'1.recollections, 2.mention, 3.exaggeration, 4.intriguing', NULL, NULL),
  ('ddb20118-df1b-5c10-9103-4d6193e28b21'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ddb20118-df1b-5c10-9103-4d6193e28b21'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '58ac62d3-adcc-5679-9f5c-424ba3f0e019'::uuid, NULL, E'I would like an egg and tomatoes on white sandwich bread with orange juice.', NULL, NULL, NULL),
