  ('de00c8a3-4a4b-5897-ae4d-df6d93d63d32'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'de00c8a3-4a4b-5897-ae4d-df6d93d63d32'::uuid, 1, NULL, TRUE, 0, NULL, E'MBA', E'Deciding to go to business school is perhaps the simplest part of what can be a complicated process. With nearly 600 accredited MBA programs on {{1}} around the world, the choice of where to study can be overwhelming. Here we explain how to {{2}} the right school and course for you and unravel the application and funding process. "Probably the {{3}} of people applying to business school are at a point in their careers where they know they {{4}} to shake things up, but they don''t know exactly what they want to do with their professional lives," says Stacy Blackman, an MBA admissions consultant based in Los Angeles. "If that''s the case with you, look at other {{5}} : culture, teaching method, location, and then pick a place that’s a good fit for you with a strong general management program. Super-defined career goals don’t have to be a part of this process."', NULL, NULL, NULL, E'1.offer, 2.choose, 3.majority, 4.want, 5.criteria', NULL, NULL),
  ('de06119f-b8d8-5b8e-bb56-55b1da94456f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'de06119f-b8d8-5b8e-bb56-55b1da94456f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '824ec8e4-572a-5077-a551-c577a016a8b7'::uuid, NULL, E'It''s possible that in the course of time a cure for cancer will be found.', NULL, NULL, NULL),
