  ('de3d072e-7480-54e6-b6ee-98c468cea756'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'de3d072e-7480-54e6-b6ee-98c468cea756'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd27185b1-112e-5253-a916-6f61a90d2812'::uuid, NULL, NULL, E'There was a lot of traffic this morning.', NULL, NULL),
  ('de3d6827-2a3a-5fff-968f-39c5974a010c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'de3d6827-2a3a-5fff-968f-39c5974a010c'::uuid, 1, NULL, TRUE, 0, NULL, E'Dictionary', E'The famous dictionary of Samuel Johnson, published in London in 1755; its principles dominated English {{1}} for more than a century. This two-volume work surpassed earlier dictionaries not in {{2}} but in the precision of definition. Its strength lay in two features: the original carefully divided and ordered, elegantly formulated definitions of the main word stock of the language; and the copious citation of quotations from the entire range of English literature, which served in support and illustration and which {{3}} the different shades of meaning of a particular word. A Dictionary of the English Language included a history of the language, a grammar, and an extensive list of words representing basic general vocabulary, based on the best conversation of {{4}} London and the normal usage of respected writers. The original was followed in 1756 by an abbreviated one-volume version that was widely used far into the 20th century. Johnson''s accomplishment was to provide for the English language a dictionary that incorporated with skill and intellectual power the {{5}} ideals and resources and the best available techniques of European lexicography. It was the standard English dictionary until Noah Webster''s.', NULL, NULL, NULL, E'1.lexicography, 2.bulk, 3.exemplified, 4.contemporary, 5.prevailing', NULL, NULL),
  ('de3e31ab-c001-5758-8da3-c6e8ac251b3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'de3e31ab-c001-5758-8da3-c6e8ac251b3c'::uuid, 1, NULL, TRUE, 0, NULL, E'Vitamin D', E'Dark pigments help protect the skin from sunlight’s {{1}} ultraviolet rays, but people make vitamin D when {{2}} to sunlight. For people living in areas that don’t get much sunlight, it helps if their skin has less pigment. And over many generations, people living in Europe {{3}} light-colored skin, which helped them get enough vitamin D.', NULL, NULL, NULL, E'1.harmful, 2.exposed, 3.developed', NULL, NULL),
  ('de45fdea-9c75-5839-b391-176890387b84'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'de45fdea-9c75-5839-b391-176890387b84'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '20eb09c9-f20a-54f3-ad54-f2de0665d662'::uuid, NULL, NULL, E'We aim to develop the partnership with the government and financial institutions.', NULL, NULL),
  ('de473d7b-fd8c-5804-974e-fad0e1e2fdae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'de473d7b-fd8c-5804-974e-fad0e1e2fdae'::uuid, 1, NULL, TRUE, 0, NULL, E'Avalanche', E'Avalanche, as are a constant threat on mountain highways. The rogers pass stretch of the trans Canada is at risk of being buried in snow from November to April every year. This is why the highway now has a sophisticated defense system. The best way. It''s important to control an avalanche when it''s small. So a slide is set off while it''s still small before it builds up into a serious danger. A team of snow technicians monitors the snow pack. They sort of read the snow and try to predict when it''s likely to slide. They studied data from the weather stations in the mountains. As the danger increases, they drop explosives on to test slopes to see if the snow can be made a ...\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', 'a2e18420-0f63-57ed-9c1b-d616c5824929'::uuid, NULL, NULL, E'slide', NULL, NULL),
  ('de479bff-1a6e-5e26-8b13-9b38542e35c9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'de479bff-1a6e-5e26-8b13-9b38542e35c9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5455d8e6-767f-5c35-8eec-60c194cad713'::uuid, NULL, NULL, E'There is no record that he obtained a high school diploma.', NULL, NULL),
