  ('de49a48f-742b-5915-9e4e-47d7e4e5129a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'de49a48f-742b-5915-9e4e-47d7e4e5129a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the synonym of ''destiny''?', '2f175d0c-ae19-5d23-b043-a41463625d66'::uuid, NULL, NULL, E'Fate / fortune', NULL, NULL),
  ('de4eaad6-41cc-505d-87e5-d699d40e6646'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'HIGHLIGHT_CORRECT_SUMMARY', E'HIGHLIGHT_CORRECT_SUMMARY', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'de4eaad6-41cc-505d-87e5-d699d40e6646'::uuid, 1, NULL, TRUE, 0, NULL, E'Noise Exposure', E'Long term exposure to noise can lead to loss of hearing. The relative loudness of sounds is measured in decibels. Just to give you an idea of what this means. The sound of a whisper is thirty decibels, while a normal conversation is sixty decibels. The noise of vacuum cleaner makes is around eighty five decibels. The danger zone, the risk of injury begins it around ninety. Continual exposure to sounds above ninety decibels can damage your hearing loud noises, especially when they come at you every day. All this noise can damage the delicate hair cells in your inner ear. Lots of everyday noises are bad for us in the long run. For example, a car horn sounds at around one hundred decibels. A rock band at close range is one hundred and twenty five decibels. A jet engine at close range is one of the worst culprits at an ear busting one hundred and forty decibels. The first thing to go is your high frequency hearing, where you detect the consonant sounds in words. That''s why a person with hearing loss can hear voices, but has trouble understanding what''s being said.\n\nClick on the paragraph that best relates to the recording.', '52aa6473-2ffb-55ce-aa7f-eda9d53aa761'::uuid, NULL, NULL, E'Loss of hearing are caused by exposure to noise over a long window of time. At 90 decibels level,  people have risk of hearing loss begin. Lots of everyday life can damage your hearing, for examples, long term exposure to rock bands and jet engines.', NULL, NULL),
  ('de55391e-4b8d-596e-bb34-bcc0e58188ec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'de55391e-4b8d-596e-bb34-bcc0e58188ec'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '75138d6f-dd5a-5a36-8405-9116c607ba67'::uuid, NULL, NULL, E'Our professor is now on leave after a busy semester.', NULL, NULL),
  ('de57e2eb-dd7d-5b07-a449-03faa0d2c7a1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'de57e2eb-dd7d-5b07-a449-03faa0d2c7a1'::uuid, 1, NULL, TRUE, 0, NULL, E'Social Value of Offsets', E'The Social Value of Offsets (SVO) is an economic framework that will help policymakers calculate how much carbon should be stored in temporary offsets to make it equivalent to a permanent CO2 emission. Using the SVO metric the researchers estimate that an offset sequestering one ton of carbon for 50 years is equivalent to between 0.3 to 0.5 tons permanently locked away.', NULL, NULL, NULL, NULL, NULL, NULL),
