  ('deaaf730-2368-59aa-a315-376154ddd8b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'deaaf730-2368-59aa-a315-376154ddd8b9'::uuid, 1, NULL, TRUE, 0, NULL, E'Earthquake Strikes', E'When an earthquake strikes, smaller quakes known as aftershocks can continue to shake the area for days to years after the original earthquake occurred. These smaller quakes decrease over time and are part of the fault''s readjustment process following the original quake. While aftershocks are smaller in magnitude than the main shock, they can still damage infrastructure and impede recovery from the original earthquake.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('deac5fe7-0b18-5a9a-bb16-6f179934b6ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'deac5fe7-0b18-5a9a-bb16-6f179934b6ca'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4778e032-e94e-5f33-bdb9-0982f5aec13b'::uuid, NULL, NULL, E'The literature review should include recent articles.', NULL, NULL),
  ('dead362a-9720-5308-9060-512ed8bc3f7e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dead362a-9720-5308-9060-512ed8bc3f7e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a5d104c5-fe88-5cde-9b24-e02696ff5c09'::uuid, NULL, E'He used to take a walk in a small garden after dinner.', NULL, NULL, NULL),
  ('deaec6c8-9367-56d5-bf6a-6eb85021d323'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'deaec6c8-9367-56d5-bf6a-6eb85021d323'::uuid, 1, NULL, TRUE, 0, NULL, E'Women''s Suffrage Movement', NULL, NULL, NULL, NULL, E'4, 1, 3, 2', NULL, NULL),
  ('deb5f9b3-c296-55fa-9a8a-6000bafedfe1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'deb5f9b3-c296-55fa-9a8a-6000bafedfe1'::uuid, 1, NULL, TRUE, 0, NULL, E'Galapagos Islands', E'The Galapagos Islands are like a biological ark in the eastern Pacific Ocean. There are giant tortoises and swimming iguanas and numerous creatures found nowhere else. It’s one of the world’s most protected places. But scientists have discovered that dozens of exotic species have invaded the Galapagos — underwater. NPR''s Christopher Joyce reports on this unexpected finding.\nCHRISTOPHER JOYCE, BYLINE: Marine biologist James Carlton remembers when he first got to thinking that the Galapagos Islands may not be as pristine as people thought.\nJAMES CARLTON: On my first visit to the Galapagos, I collected some samples from a boat bottom.\nJOYCE: Barnacles, sponges and other hitchhikers. That was 1987. Carlton didn''t know if those creatures he found were native or not, so four years ago, he and a team of scientists decided to return and take a closer look.\nCARLTON: We didn''t know quite what to expect.\nJOYCE: What they did know was that on land there were lots of invasive species, species that are not native to the islands. But in the surrounding ocean, scientists only knew of five invaders; everything else presumably was native. When Carlton''s team looked underwater, however, they found a horde of invaders.\n\nAccording to the audio, the Galapagos Islands ____', '75232846-70f2-5b07-852d-49f507b9af72'::uuid, NULL, NULL, E'are a place where many invasive species underwater were found.\nsurprised scientists because of its underwater invaders.', NULL, NULL),
  ('deb75fee-a268-509f-9c9e-bd8dea61dcab'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'deb75fee-a268-509f-9c9e-bd8dea61dcab'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0b8a4f9d-b233-57c3-9e61-593bb3d10b75'::uuid, NULL, E'Employees go around the park at lunchtime.', NULL, NULL, NULL),
  ('dec5db62-6d84-511c-8afb-374607cdc6e8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dec5db62-6d84-511c-8afb-374607cdc6e8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the fundamental principles or established precedents according to which a state is governed?', '15bd5322-f942-5670-9551-3ce2d4d5998f'::uuid, NULL, NULL, E'Constitution', NULL, NULL),
  ('dec977a7-eb2d-5b7c-9e6f-32114df3eb94'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dec977a7-eb2d-5b7c-9e6f-32114df3eb94'::uuid, 1, NULL, TRUE, 0, NULL, E'Hihi', E'Conservationists in New Zealand have come up with a novel way of raising money for one of the country''s lesser-known endangered bird species - by holding a race to see which male stitchbird, or hihi, has the fastest sperm. The Great Hihi Sperm Race will pit samples from birds collected from four different hihi colonies, and donors can place a ten NZ dollar bet on which of the 128 samples swims the fastest.', NULL, NULL, NULL, NULL, NULL, NULL),
