  ('ded172bb-64b5-5368-b3c4-284a2b54e2f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ded172bb-64b5-5368-b3c4-284a2b54e2f0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '18d5aa0f-6f01-537d-b3a3-ae8b37d09f23'::uuid, NULL, E'This library card provides free access to books and other learning materials.', NULL, NULL, NULL),
  ('ded296ca-37aa-56d2-87be-f75c6054980b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ded296ca-37aa-56d2-87be-f75c6054980b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'df843cb1-1569-547e-a99f-e801ba1ef804'::uuid, NULL, E'She was asked to describe what her campus life was like as a freshman.', NULL, NULL, NULL),
  ('dedc2a80-fbb3-5d45-9e2e-52490463e1f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'dedc2a80-fbb3-5d45-9e2e-52490463e1f9'::uuid, 1, NULL, TRUE, 0, NULL, E'Emigrants', E'In the late 16th and 17th centuries, many English, French and Dutch emigrants went to North America in search of gold and silver. But they did not find it. Instead, settlers were forced to support themselves by cultivating crops that they could sell in Europe, like tobacco, indigo and rice.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('dede467b-094f-51c9-b08b-061f9e176fe3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'dede467b-094f-51c9-b08b-061f9e176fe3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b42a398a-5fd5-5662-9064-df7a21330fa6'::uuid, NULL, NULL, E'If you have any questions about the exam, please raise your hand.', NULL, NULL),
  ('dee274c7-42df-5c7b-8c44-102658c88df7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'dee274c7-42df-5c7b-8c44-102658c88df7'::uuid, 1, NULL, TRUE, 0, NULL, E'Clutches', E'Clutches are useful in devices that have two rotating shafts, including cars. One of the shafts is typically driven by a motor or pulley, and the other shaft drives another device. The clutch connects the two shafts so that they can either be locked together and spin at the same speed, or be decoupled and spin at different speeds.\nIn a car, you need a clutch because the engine spins all the time, but the car''s wheels do not. In order for a car to stop without killing the engine, the wheels need to be disconnected from the engine somehow. The clutch allows us to smoothly engage a spinning engine to a transmission that is not spinning by controlling the slippage between them.\nTo understand how a clutch works, it helps to know a little bit about friction, which is a measure of how hard it is to slide one object over another. Friction is caused by the peaks and valleys that are part of every surface, even very smooth surfaces still have microscopic peaks and valleys. The larger these peaks and valleys are, the harder it is to slide the object.\nA clutch works because of friction between a clutch plate and a flywheel. When your foot is off the clutch pedal in a manual car, springs push the pressure plate against the clutch disc, which in turn presses against the flywheel. This locks the engine to the transmission input shaft, causing them to spin at the same speed.', NULL, NULL, NULL, NULL, 5, 75),
  ('dee2be98-7a31-5596-9632-47ddc6431c99'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'dee2be98-7a31-5596-9632-47ddc6431c99'::uuid, 1, NULL, TRUE, 0, NULL, E'Quality of Online Education', NULL, NULL, NULL, NULL, E'2, 3, 4, 1, 5', NULL, NULL),
