  ('e0d3cd73-8507-531b-aada-5112c20ec10f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e0d3cd73-8507-531b-aada-5112c20ec10f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0ef6384e-b47d-5394-952f-ea09e7810fbc'::uuid, NULL, E'Scientific advances can bring problems and may not be worthwhile.', NULL, NULL, NULL),
  ('e0e4cc14-6a3e-5440-a797-c75cd0953828'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e0e4cc14-6a3e-5440-a797-c75cd0953828'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e6458e1a-8989-5bcf-bdee-6fff851b4499'::uuid, NULL, NULL, E'The degree is typically taught by using a mixture of lectures and seminars.', NULL, NULL),
  ('e0e71aee-b774-5ae5-bd23-4b7168ec8a4d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e0e71aee-b774-5ae5-bd23-4b7168ec8a4d'::uuid, 1, NULL, TRUE, 0, NULL, E'Genius', E'Genius, in the popular conception, is inextricably tied up with precocity - doing something truly creative, we''re inclined to think, requires the freshness and exuberance and energy of youth. Orson Welles made his masterpiece, "Citizen Kane", at twenty-five. Herman Melville wrote a book a year {{1}} his late twenties, culminating, at the {{2}} of thirty-two, with "Moby-Dick". Mozart wrote his breakthrough Piano Concerto No. 9 in E-Flat-Major at the age of twenty-one. In some creative forms, like lyric poetry, the {{3}} of precocity has hardened into an iron law. How old was T. S. Eliot when he wrote "The Love Song of J. Alfred Prufrock" ("I grow old ... I grow old")? Twenty-three. "Poets peak young," the creativity researcher James Kaufman maintains. Mihály Csíkszentmihályi, the author of "Flow", agrees: "The most creative lyric verse is believed to be that written by the young." According to the Harvard psychologist Howard Gardner, a leading {{4}} on creativity, "Lyric poetry is a domain where {{5}} is discovered early, burns brightly, and then peters out at an early age."', NULL, NULL, NULL, E'1.through, 2.age, 3.importance, 4.authority, 5.talent', NULL, NULL),
  ('e0e7dc04-5bbe-539d-9f9a-8ada9925ecdb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e0e7dc04-5bbe-539d-9f9a-8ada9925ecdb'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b90b93ea-80cc-5b10-930e-e6a44d35467f'::uuid, NULL, E'He would raise his voice if anyone interrupted him while painting.', NULL, NULL, NULL),
  ('e0eb4588-6763-5512-81d4-feb66904b7b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e0eb4588-6763-5512-81d4-feb66904b7b9'::uuid, 1, NULL, TRUE, 0, NULL, E'Natural Gas', E'Demand for natural gas has grown internationally in recent years, in part because it has a smaller carbon footprint than coal and other fossil fuels. In Singapore, where the government has promoted increased use of natural gas, consumption has grown about ninefold in recent decades. In some places, natural gas consumption has expanded as public opinion has turned against nuclear power.', NULL, NULL, NULL, NULL, NULL, NULL),
