  ('e0f2cf1a-5f42-56ca-9544-c772350eada1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e0f2cf1a-5f42-56ca-9544-c772350eada1'::uuid, 1, NULL, TRUE, 0, NULL, E'Economic Growth', E'Governments promise continuous economic growth, but it''s actually an illusion. Some people think that governments should abandon this. Please talk about the validity and the implications.', NULL, NULL, NULL, NULL, 200, 300),
  ('e0f69b1a-1714-53c9-b82a-311d71583975'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e0f69b1a-1714-53c9-b82a-311d71583975'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e724ae42-6d17-5555-9b8b-b9fb1fc283e4'::uuid, NULL, E'After considering all the options she decided to take risks.', NULL, NULL, NULL),
  ('e109c3d4-e454-5c3b-8ee3-3a2ae7e1af6d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e109c3d4-e454-5c3b-8ee3-3a2ae7e1af6d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '956b8c3f-7fc5-5978-a560-d17dd6501bfa'::uuid, NULL, NULL, E'That period is often hailed as a golden era in English literature.', NULL, NULL),
  ('e110a89d-fa0d-58b0-81e7-a8fa074e2ad7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e110a89d-fa0d-58b0-81e7-a8fa074e2ad7'::uuid, 1, NULL, TRUE, 0, NULL, E'Debtor', E'There isn''t a financial director around who wouldn''t like to {{1}} cash flow by {{2}} debtor days- in other words, get customers to {{3}} faster. In Europe''s top 1,000 quoted companies, nearly one quarter of all invoices are unpaid {{4}} in time, according to recent research carried out by the ASF organization. This means they are sitting on a total of 274 billion overdue debt. Most of this is caused by poor collection practices. According to Jan Porter, ASF''s Managing Director, ''You can set up all the systems you want, you can insist on watertight contracts and payment terms, the government can even introduce late payment legislation, but there are always some debtors who fail to pay on time. Once a payment is overdue, your first step is to talk to your debtor. You should let them know the payment is late and try to find out if there is a dispute about the work, or if your debtor has financial problems. {{5}} , but Tim Vainio, a chartered accountant, believes that too many companies are afraid of losing a relationship, and that, before {{6}} , the focus should be on recovering as much money as possible, rather than on preserving a relationship.''', NULL, NULL, NULL, E'1.accelerate, 2.reducing, 3.pay up, 4.at any point, 5.This is OK, 6.undertaking any action', NULL, NULL),
  ('e117c8f8-0835-5513-ba60-8a0f1708ddd4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e117c8f8-0835-5513-ba60-8a0f1708ddd4'::uuid, 1, NULL, TRUE, 0, NULL, E'Biodiversity Summit', E'On 7 December, representatives from nearly every country in the world will gather in Montreal for the United Nations’ COP15 summit to {{1}} the world’s biodiversity crisis. Delays to the meeting have {{2}} expectations for the outcome of the summit, but participants are holding out hope that the meeting could be as consequential for stemming biodiversity loss as the landmark 2015 Paris Agreement was for action on climate change. COP15 is the 15th Conference of the Parties to the UN Convention on Biological Diversity, a treaty {{3}} in 1992 to protect the world’s biodiversity. Parties to the treaty include the European Union and every country in the world except the US and Vatican City, though both will participate in the summit. Representatives from countries meeting in Montreal will {{4}} an agreement to shape the next decade of action on biodiversity.', NULL, NULL, NULL, E'1.tackle, 2.tempered, 3.drafted, 4.negotiate', NULL, NULL),
  ('e11ab8fa-7422-544a-abd6-50638d3a88ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'e11ab8fa-7422-544a-abd6-50638d3a88ee'::uuid, 1, NULL, TRUE, 0, NULL, E'Understanding Differences(了解差异)', NULL, NULL, NULL, NULL, E'3, 4, 1, 2', NULL, NULL),
  ('e11f2b7a-92c9-5913-ac3c-55495eeaa1fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e11f2b7a-92c9-5913-ac3c-55495eeaa1fd'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which country is famous for its fjords?', '6720c3f7-aed0-501b-8187-c9e6135247cf'::uuid, NULL, NULL, E'Norway', NULL, NULL),
  ('e11f4ee9-e250-588e-b868-e5eafec4a755'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e11f4ee9-e250-588e-b868-e5eafec4a755'::uuid, 1, NULL, TRUE, 0, NULL, E'Skipping Breakfast', E'Skipping breakfast seems a simple way of losing weight or saving time while getting the children ready for school or rushing off to work. But it can also be a sign of an unhealthy lifestyle with potentially dangerous consequences, including a higher risk of premature death. According to a study, adults and teenagers who miss the first meal of the day are less likely to look after their health. They tend to smoke more, drink more alcohol and take less exercise than those who do eat. Those who skip food in the morning are also more likely to be fatter and less well-educated, meaning they find it harder to get a job. Researcher Dr. Anna Keski-Rahkonen said: Smoking, infrequent exercise, a low level of education, frequent alcohol use and a high body mass index were all associated with skipping breakfast in adults and adolescents. Our findings suggest this association exists throughout adulthood. Individuals who skip breakfast may care less about their health than those who eat breakfast. Previously, experts assumed that missing breakfast often called the most important meal of the day was simply the marker of a hectic life or a way to try to lose weight. But Dr. Keski-Rahkonen, who led the study at Helsinki University, said the results revealed starting the day without food suggests an unhealthy lifestyle.', NULL, NULL, E'Skipping breakfast, seemingly a simple way of losing weight or saving time, can be a sign of an unhealthy lifestyle with potentially dangerous consequences for adults and teenagers who miss the first meal of the day, and smoking, infrequent exercise, a low level of education, frequent alcohol use and a high body mass index are all associated with skipping breakfast.', NULL, 5, 75),
  ('e12547dd-8965-56e5-93b2-574543034142'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e12547dd-8965-56e5-93b2-574543034142'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e61d3c76-76f5-549c-b23d-3bce0c328cb1'::uuid, NULL, NULL, E'Most of the lectures begin promptly, so do not be late.', NULL, NULL),
  ('e127717c-34b8-59dd-9d50-162a070f29bb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e127717c-34b8-59dd-9d50-162a070f29bb'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a9e0dadc-802e-5fd6-a682-159bb30f35a1'::uuid, NULL, NULL, E'All our results are published in scientific journals.', NULL, NULL),
  ('e127789a-c062-50e5-9674-a68454ad886c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e127789a-c062-50e5-9674-a68454ad886c'::uuid, 1, NULL, TRUE, 0, NULL, E'Customer Service Promotion', E'Promoting good customer service must start at the top. If management doesn''t realize how important this {{1}} of their business is, they will be at an instant {{2}} in their industry. Good customer response equates to loyal customers, which are the cornerstone of any successful business. No matter how much money you invest in your {{3}} , if you don''t much have the fundamental elements of your business right, it''s {{4}} money.', NULL, NULL, NULL, E'1.aspect, 2.disadvantage, 3.marketing, 4.wasted', NULL, NULL),
  ('e12a537c-b206-5c87-9262-3ede790dc788'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e12a537c-b206-5c87-9262-3ede790dc788'::uuid, 1, NULL, TRUE, 0, NULL, E'Small Wars', E'In such an environment, warfare is no longer purely directed against the military potential of adversarial states. It is rather directed at infiltrating all areas of their societies and threatening their existences. The comparatively easy access to weapons of mass destruction, in particular low-cost biological agents, is of key concern. Both governmental and non-governmental actors prefer to use force in a way that can be characterized as "unconventional" or also as "small wars". War waged according to conventions is an interstate phenomenon. The "small war" is the archetype of war, in which the protagonists acknowledge no rules and permanently try to violate what conventions do exist. The protagonists of the "small war" observe neither international standards nor arms control agreements. They make use of territories where they do not have to fear any sanctions because there is no functioning state to assume charge of such sanctions or because the state in question is too weak to impose such sanctions. This type of war does not provide for any warning time. It challenges not only the external security of the nation states and international community, but also their internal safety.', NULL, NULL, E'Warfare is rather directed at infiltrating all areas of their societies and threatening their existences, where the comparatively easy access to weapons of mass destruction is of key concern, and the protagonists acknowledge no rules, who observe neither international standards nor arms control agreements, so it challenges not only the external security of the nation states and international community, but also their internal safety.', NULL, 5, 75),
  ('e12fbd80-a153-5a18-a017-8064127634aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e12fbd80-a153-5a18-a017-8064127634aa'::uuid, 1, NULL, TRUE, 0, NULL, E'Stars', E'Since the dawn of recorded civilization, stars played a key role in religion and proved vital to navigation, according to the International Astronomical Union. Astronomy, the study of the heavens, may be the most ancient of the sciences. The invention of the telescope and the discovery of the laws of motion and gravity in the 17th century prompted the realization that stars were just like the sun, all obeying the same laws of physics. In the 19th century, photography and spectroscopy — the study of the wavelengths of light that objects emit — made it possible to investigate the compositions and motions of stars from afar, leading to the development of astrophysics.\nA star develops from a giant, slowly rotating cloud that is made up entirely or almost entirely of hydrogen and helium. Due to its own gravitational pull, the cloud behind to collapse inward, and as it shrinks, it spins more and more quickly, with the outer parts becoming a disk while the innermost parts become a roughly spherical clump.\nAccording to NASA, this collapsing material grows hotter and denser, forming a ball-shaped protostar. When the heat and pressure in the protostar reaches about 1.8 million degrees Fahrenheit, atomic nuclei that normally repel each other start fusing together, and the star ignites. Nuclear fusion converts a small amount of the mass of these atoms into extraordinary amounts of energy — for instance, 1 gram of mass converted entirely to energy would be equal to an explosion of roughly 22,000 tons of TNT.\nThe life cycles of stars follow patterns based mostly on their initial mass. These include intermediate-mass stars such as the sun, with half to eight times the mass of the sun, high-mass stars that are more than eight solar masses, and low-mass stars a tenth to half a solar mass in size. The greater a star''s mass, the shorter its lifespan generally is, according to NASA. Objects smaller than a tenth of a solar mass do not have enough gravitational pull to ignite nuclear fusion — some might become failed stars known as brown dwarfs.', NULL, NULL, NULL, NULL, 5, 75),
  ('e1305524-8e1d-5252-9246-1caa9337aef5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e1305524-8e1d-5252-9246-1caa9337aef5'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd5d3390d-dd30-51a5-ac28-979b31da51a6'::uuid, NULL, E'Before publishing, delete personal information from the results to ensure privacy.', NULL, NULL, NULL),
  ('e130d7dd-5d35-51cd-8b3f-51ec9e4ce15a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e130d7dd-5d35-51cd-8b3f-51ec9e4ce15a'::uuid, 1, NULL, TRUE, 0, NULL, E'Transportation by Water', E'Not a lot is known about how the transportation of goods by water first began. Large cargo boats were being used in some parts of the world up to five thousand years ago. However, sea trade became more widespread when large sailing boats travelled between ports, carrying spices, perfumes and objects made by hand.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e1375be0-8682-5401-909c-97d70acf9c38'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e1375be0-8682-5401-909c-97d70acf9c38'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you describe something that can be carried easily, portable or cumbersome?', 'f81ff1ce-d21c-5e75-9137-2489ec7800b8'::uuid, NULL, NULL, E'Portable', NULL, NULL),
  ('e1376e49-9bce-5cd7-9173-80ceed446cd8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e1376e49-9bce-5cd7-9173-80ceed446cd8'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd3383da6-4691-5b22-b708-12e1abab7ff0'::uuid, NULL, NULL, E'You have to send me your essay in two core and three optional modules.', NULL, NULL),
  ('e139b21d-d33b-51d9-b1a7-3ac85f8301bc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e139b21d-d33b-51d9-b1a7-3ac85f8301bc'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '64a1b83e-6b62-5762-bb14-1988aa8ccd1a'::uuid, NULL, E'There has been an acute shortage of water since the river was polluted.', NULL, NULL, NULL),
  ('e13c082a-836b-5732-98b2-2d12461c4e76'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e13c082a-836b-5732-98b2-2d12461c4e76'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '45cf68f6-2968-5802-a6c1-1a76efe7cd07'::uuid, NULL, NULL, E'Our planet''s atmosphere consists mostly of nitrogen and oxygen gases.', NULL, NULL),
  ('e14954e3-15a4-527d-a90c-b0cf605f3b82'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e14954e3-15a4-527d-a90c-b0cf605f3b82'::uuid, 1, NULL, TRUE, 0, NULL, E'Cloud Seeding', E'Cloud seeding, a form of weather modification, is a way of attempting to change the amount of precipitation that comes from clouds. Cloud seeding is carried out by dispersing substances into the air, but it also occurs due to ice nuclei in nature, most of which are bacterial in origin.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e15597a9-bb9e-50b1-a13e-d4952c5f23b6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e15597a9-bb9e-50b1-a13e-d4952c5f23b6'::uuid, 1, NULL, TRUE, 0, NULL, E'Stress', E'Stress — that tense feeling often connected to having too much to do, too many bills to pay and {{7}} time or money — is a common emotion that knows few {{1}} .\nAbout three-fourths of people in the United States, Australia, Canada, France, Germany, Italy, South Korea and Britain reported experiencing stress on a daily basis, according to AP-Ipsos {{2}} . Anxious feelings were more {{5}} during the holidays.\nGermans feel stress more intensely than those in other countries polled. People in the United States cite financial pressures as the top worry. About half the people polled in Britain said they frequently or {{6}} felt that life was beyond their control, the highest level in the 10 countries surveyed.', NULL, NULL, NULL, E'1.not enough, 2.borders, 3.polling, 4.intense, 5.sometimes', NULL, NULL),
  ('e155aec0-c9a4-50db-9b2f-749f48236389'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'e155aec0-c9a4-50db-9b2f-749f48236389'::uuid, 1, NULL, TRUE, 0, NULL, E'Non-material and Material Culture', NULL, NULL, NULL, NULL, E'5, 4, 1, 2, 3', NULL, NULL),
  ('e15872ae-7886-5f8a-a65b-15331cc8451a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e15872ae-7886-5f8a-a65b-15331cc8451a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'fe7d1788-faf8-5cae-ba82-0918f8d38fcb'::uuid, NULL, NULL, E'University fees are expected to increase next year.', NULL, NULL),
  ('e159963b-9aa7-51aa-a9ec-cdd9416725b6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e159963b-9aa7-51aa-a9ec-cdd9416725b6'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for the study of plants?', 'ce3eaa8d-91e2-5f5a-8652-7e5e67b0f624'::uuid, NULL, NULL, E'Botany', NULL, NULL),
  ('e15998c3-d52e-5df6-9031-3361ee5735a1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e15998c3-d52e-5df6-9031-3361ee5735a1'::uuid, 1, NULL, TRUE, 0, NULL, E'Museum', E'The best way to experience the museum is from the top floor down. One emerges from the elevators into a spacious hallway. At some hours, museum staff members are giving small hands-on {{1}} of techniques such as quillwork. These activities take place near wall cases filled with objects. These small surveys of the museum''s vast holdings are called "Windows on the Collection." Appearing on every floor in the halls that {{2}} the rotunda, these display cases serve as a kind of visible storage, presenting a panoply of objects and materials. Their arrangements are artistic, and their contents perhaps {{3}} designed to jar the visitor. For example, the largest case on the fourth floor displays animal imagery of all sorts. Older {{4}} of birds, mammals and sea creatures {{5}} alongside witty contemporary works such as Larry Beck'' s version of a Yup'' ik mask made of rubber tire treads and metal tools, and Jim Schoppert'' s "Walrus Loves Baby Clams" mask. Recently-made ivory carvings challenge the common distinction between so-called "authentic fine art" and commodity( a distinction which may be passé in the academic world, but which still {{6}} strong among much of the general public).', NULL, NULL, NULL, E'1.demonstrations, 2.overlook, 3.intentionally, 4.sculptures, 5.appear, 6.holds', NULL, NULL),
  ('e15c4ef4-fee8-5871-b562-175214873774'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e15c4ef4-fee8-5871-b562-175214873774'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Where would you keep the meat you wish to keep frozen at home?', 'fa753ee4-5b2f-502b-99df-21745c29eb1a'::uuid, NULL, NULL, E'Freezer', NULL, NULL),
  ('e164d8a5-9316-5403-9b2e-dc08a290fced'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e164d8a5-9316-5403-9b2e-dc08a290fced'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call programs that run on a computer?', 'e52da898-7399-5865-8269-0362287c4e7b'::uuid, NULL, NULL, E'Software', NULL, NULL),
  ('e1658db2-b32a-5473-96b3-7fcb021267d1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e1658db2-b32a-5473-96b3-7fcb021267d1'::uuid, 1, NULL, TRUE, 0, NULL, E'Tambora', E'On 1815, on the island of Sumbawa in Indonesia, a handsome and long quiescent mountain named Tambora exploded spectacularly, killing a hundred thousand people with its blast and associated tsunamis. No one living now has ever seen such fury. Tambora was far bigger than anything any living human has experienced. It was the biggest volcanic explosion in ten thousand years, 150 times the size of Mount St. Helens, equivalent to sixty thousand Hiroshima- sized atom bombs.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e167dee3-f8a4-5b3e-900c-ec1130466964'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e167dee3-f8a4-5b3e-900c-ec1130466964'::uuid, 1, NULL, TRUE, 0, NULL, E'Infrastructure', E'The grid-based infrastructure enables large-scale scientific applications to be run on distributed resources. However, in practice, grid resources are not very easy to use for the end-users who have to learn how to generate security credentials. There is an imminent need to provide transparent access to these resources so that the end-users are shielded from the complicated details.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e17a291e-ec49-5ab5-a10b-de866530b8dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e17a291e-ec49-5ab5-a10b-de866530b8dd'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the economic sector that deals with farming?', '300a2ba0-ad72-5d2d-8239-ebc27338e981'::uuid, NULL, NULL, E'Agriculture', NULL, NULL),
  ('e184fa84-9afb-592e-b86b-a3018b6de6fa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e184fa84-9afb-592e-b86b-a3018b6de6fa'::uuid, 1, NULL, TRUE, 0, NULL, E'Dead Stars', E'The Milky Way is a gargantuan graveyard. Stars are born, burn out and die, but they don''t just {{1}} — and the galaxy is haunted by their corpses. Stars in the Milky Way that died billions of years ago went supernova and {{2}} into two types of objects. With their outer layers {{3}} away by the force of the explosion, the cores that were {{4}} formed black holes.', NULL, NULL, NULL, E'1.vanish, 2.morphed, 3.blasted, 4.left', NULL, NULL),
  ('e18ad5de-4ac6-5eee-b28d-75a3a7f1f8cc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e18ad5de-4ac6-5eee-b28d-75a3a7f1f8cc'::uuid, 1, NULL, TRUE, 0, NULL, E'Toasted Food', E'When we put toast in the toaster or add marshmallows to the top of our sweet potatoes for a baked holiday dish we expect them to turn brown and to develop a sweet, caramelized flavor. Although we expect it to happen, do you know why certain foods take on these new colors and flavors as they are toasted?', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e1943e72-f81c-5774-9134-27ffe74070ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e1943e72-f81c-5774-9134-27ffe74070ca'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7556683a-64de-5690-a71f-bf170c60ef9d'::uuid, NULL, E'This section has discussed the relationship between sociology and values.', NULL, NULL, NULL),
  ('e1a024be-b66a-5d97-970a-8afc14d7cbdc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e1a024be-b66a-5d97-970a-8afc14d7cbdc'::uuid, 1, NULL, TRUE, 0, NULL, E'Radioactivity', E'So why is it a concern? It is {{1}} radioactivity is invisible and unsensed, and for that reason is perceived as scary. {{2}} , we understand quite well the radiation levels to which people can be {{3}} without harm, and those levels are orders of {{4}} above the typical background levels.', NULL, NULL, NULL, E'1.because, 2.Nevertheless, 3.exposed, 4.magnitude', NULL, NULL),
  ('e1a61a7d-0e46-5088-aab5-4b2855865e30'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e1a61a7d-0e46-5088-aab5-4b2855865e30'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the container that is used for heating or boiling water?', '7a6a1a36-dd2b-55ef-825f-67a3ed0f4994'::uuid, NULL, NULL, E'Kettle / kettles', NULL, NULL),
  ('e1a6954d-9311-5774-83f8-35bd8eb47046'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e1a6954d-9311-5774-83f8-35bd8eb47046'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5f5a1f89-1561-5430-a717-11ddff9ad8c8'::uuid, NULL, E'Over time, you will get a far better understanding of the job.', NULL, NULL, NULL),
  ('e1acb5b1-8785-512f-a470-70d411f314f5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e1acb5b1-8785-512f-a470-70d411f314f5'::uuid, 1, NULL, TRUE, 0, NULL, E'Parents and Education', E'What is your opinion on the role of parents in a child''s education?', NULL, NULL, E'The pivotal role of parents in a child''s education cannot be overstated, as they serve as the primary influencers in shaping their child''s academic success and overall development.\nParents play a vital role in supporting their child''s education both at home and within the school community. By assisting with homework, creating a conducive learning environment, and actively engaging in educational activities, parents reinforce classroom teachings and help cultivate essential study habits. Simultaneously, active involvement in school activities, such as participating in parent-teacher conferences, collaborating with educators, and attending school events, demonstrates a strong commitment to their child''s education and underscores the value placed on learning within the family dynamic.\nAdditionally, parents are instrumental in instilling values and motivation that drive academic success. By fostering a love for learning, nurturing curiosity, and promoting perseverance in the face of challenges, parents inspire their children to excel academically. Instilling values such as discipline, resilience, and a growth mindset equips children with the necessary tools to navigate obstacles and achieve their educational aspirations, fostering a sense of intrinsic motivation and a lifelong passion for learning.\nIn conclusion, the role of parents in a child''s education is multifaceted and essential for fostering academic growth and personal development. By actively supporting learning at home, engaging in school activities, and instilling values and motivation, parents create a strong foundation for their child''s educational journey. Collaborative efforts between parents, educators, and students contribute to a holistic approach to education that empowers children to reach their full potential and thrive academically.', NULL, 200, 300),
  ('e1b88c85-5c47-56e6-8175-6c3ede2b00fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e1b88c85-5c47-56e6-8175-6c3ede2b00fe'::uuid, 1, NULL, TRUE, 0, NULL, E'Microbes', E'Investigators also compared those microbes with those living in 52 other soil samples taken from all around the planet. The park had organisms that also exist in deserts, frozen tundra, forests, rainforests, and prairies. Antarctica was the only area that had microbes that did not overlap with those found in Central Park. Only a small percentage of the park’s microbes were found to be already listed in databases.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e1b9223b-fdd7-5349-a711-8a99b704d917'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e1b9223b-fdd7-5349-a711-8a99b704d917'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c91d0ec8-0f39-5c4e-8374-919f1cf77502'::uuid, NULL, NULL, E'Polar regions'' islands are ideal for meteorologists and astrophysicists.', NULL, NULL),
  ('e1b99344-6123-5eb7-b4bf-3163a9a57402'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e1b99344-6123-5eb7-b4bf-3163a9a57402'::uuid, 1, NULL, TRUE, 0, NULL, E'Society', E'Societies face numerous challenges, including inequality, discrimination, and social injustice. It''s important to recognize these issues and work towards building a more equitable and compassionate society. By raising awareness, supporting marginalized communities, and advocating for social justice, we can work towards creating a better future for all.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e1b9b874-dead-5d2d-8bcc-337259508af5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e1b9b874-dead-5d2d-8bcc-337259508af5'::uuid, 1, NULL, TRUE, 0, NULL, E'Competitive Market', E'While {{1}} businesses struggle to adapt in today''s competitive market, only a {{2}} have managed to truly {{3}} . Those that succeed often work alongside innovative partners who help {{4}} growth through collaboration and shared resources. Thriving in such environments requires not only resilience but also the ability to adapt and work effectively {{5}} others.', NULL, NULL, NULL, E'1.many, 2.few, 3.thrive, 4.facilitate, 5.alongside', NULL, NULL),
  ('e1ba8f27-2047-5899-9a89-e5aa23d9a1d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e1ba8f27-2047-5899-9a89-e5aa23d9a1d7'::uuid, 1, NULL, TRUE, 0, NULL, E'Presentation', E'This year we''re planning to use a different type of assessment on this module. In the past students were required to complete two long written assignments and also to do a presentation on a subject of their own choice. We have decided to ask you to write four shorter pieces of written coursework this year. We are also going to be more prescriptive about what you focus on in your presentation. This is because previously many students lost marks unnecessarily simply because ...\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '436d644f-1c4d-5d26-aed9-816a7a1b1a9c'::uuid, NULL, NULL, E'they made an inappropriate choice of topic', NULL, NULL),
