  ('e1ce6f45-e187-5f02-8a90-c282973bf5a5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e1ce6f45-e187-5f02-8a90-c282973bf5a5'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '78bd740f-73cf-5c72-89a8-7c72a8accb72'::uuid, NULL, E'The university offers a wide range of programs to suit different interests.', NULL, NULL, NULL),
  ('e1d01830-0c72-53a3-a182-5c3e1ff25b73'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e1d01830-0c72-53a3-a182-5c3e1ff25b73'::uuid, 1, NULL, TRUE, 0, NULL, E'Soil', E'Soil is the top layer of the Earth''s surface, mostly created from weathered rock. It is made up of varying amounts of minerals, humus, or decayed organic matter, and useful living creatures like worms. The finest rock particles within soil - forms sticky clay, the medium particles become silt, and the coarsest constitute sand. While there is sufficient moisture, soil supports vegetation, providing a habitat for a variety of animals.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e1d038f0-3ba8-574c-b00b-74ae1e8e9389'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e1d038f0-3ba8-574c-b00b-74ae1e8e9389'::uuid, 1, NULL, TRUE, 0, NULL, E'Birmingham Courses', E'We offer a wide range of courses designed to {{1}} students to think critically and independently. Our faculty members provide an educational {{2}} that is second to none. By joining us, you will be learning from some of the {{3}} minds in their respective fields.', NULL, NULL, NULL, E'1.encourage, 2.experience, 3.finest', NULL, NULL),
  ('e1d20b78-677a-5dd5-a860-00e7bfe97bbc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e1d20b78-677a-5dd5-a860-00e7bfe97bbc'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '943dc5db-d8aa-5cc7-9f39-121ce0314e64'::uuid, NULL, NULL, E'The university is a major center for scientific research.', NULL, NULL),
  ('e1d8e60d-9621-544f-9d51-5fc133a50ec9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e1d8e60d-9621-544f-9d51-5fc133a50ec9'::uuid, 1, NULL, TRUE, 0, NULL, E'Renewable Energy', E'Renewable energy is energy {{1}} from natural sources that are {{2}} at a higher rate than they are consumed. Renewable energy sources are {{3}} and all around us. Fossil fuels, coal, oil and gas, on the other hand, are non-renewable resources that take hundreds of millions of years to {{4}} .', NULL, NULL, NULL, E'1.derived, 2.replenished, 3.plentiful, 4.form', NULL, NULL),
  ('e1e27fb7-5326-5e37-8156-b9de1f07db23'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e1e27fb7-5326-5e37-8156-b9de1f07db23'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Cash usually includes banknotes and ?', 'ad3b8175-0733-5df6-94d8-658772357ace'::uuid, NULL, NULL, E'coins', NULL, NULL),
  ('e1eade4a-25e3-5cd7-96e4-614509f176c9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e1eade4a-25e3-5cd7-96e4-614509f176c9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '97334dd3-809a-5d1e-951a-f4e1b64c7783'::uuid, NULL, E'I just want to let you know that I think you’re the most beautiful woman that I''ve ever seen.', NULL, NULL, NULL),
  ('e1ecd3e4-a0fb-5ac3-8f4a-f9379b3daad2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e1ecd3e4-a0fb-5ac3-8f4a-f9379b3daad2'::uuid, 1, NULL, TRUE, 0, NULL, E'Weather', E'Some people prefer to live in places that have the same weather or climate all year long. Others like to live in areas where the weather changes several times a year. What is your opinion?', NULL, NULL, E'The debate over whether consistent or changing weather is preferable when choosing a place to live has been ongoing for years. While some people prefer to live in areas with the same climate all year long, others, like myself, enjoy living in areas where the weather changes several times a year. This essay will argue that living in areas with changing weather is preferable due to the variety of experiences and opportunities it provides.\nLiving in an area with changing weather provides a range of outdoor activities throughout the year. In the summer, people can enjoy swimming, hiking, and outdoor festivals, while in the winter, they can go skiing, ice skating, and enjoy holiday festivities. The changing weather also provides opportunities for unique experiences such as apple picking in the fall or spring flower festivals.\nIn addition to providing a range of outdoor activities, changing weather can bring a sense of excitement and novelty to daily life. The anticipation of the first snowfall or the arrival of spring can create a sense of excitement and joy. Changing weather can also provide an opportunity to explore different types of cuisine and seasonal foods, such as pumpkin spice in the fall or fresh berries in the summer.\nIn conclusion, living in areas where the weather changes several times a year is preferable due to the variety of experiences and opportunities it provides. From outdoor activities to seasonal foods, changing weather can bring excitement and novelty to daily life. While some may prefer consistent weather for its convenience, living in areas with changing weather can provide a richer and more diverse life experience.', NULL, 200, 300),
  ('e1ecf3f2-9130-5f42-aa12-5728f344f172'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e1ecf3f2-9130-5f42-aa12-5728f344f172'::uuid, 1, NULL, TRUE, 0, NULL, E'Astrology', E'Before we dive into the specifics of sun signs, it''s essential to understand the basics of astrology. Astrology is a complex study that explores the relationship between celestial bodies and human behavior. It is based on the belief that the positions and movements of these celestial bodies can influence our lives and personalities.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e1efc6d2-9140-5d14-9a15-50815ba2fa18'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e1efc6d2-9140-5d14-9a15-50815ba2fa18'::uuid, 1, NULL, TRUE, 0, NULL, E'Origins of Sexism', E'For most of our history, we have been hunter-gatherers, and patrilocal residence is not the norm among modern hunter-gatherer societies. Instead, either partner may move to live with the “in-laws”, or a couple may {{1}} away from both their families. According to the scientist, a degree of egalitarianism is built into these systems. If they reflect what prehistoric hunter-gatherers did, women in those early societies would have had the choice of support from the group they grew up with, or the option to move away from {{2}} . According to one school of thought, things changed around 12,000 years ago. With the {{3}} of agriculture and homesteading, people began settling down. They acquired resources to defend, and power {{4}} to the physically stronger males. Fathers, sons, uncles and grandfathers began living near each other, property was passed down the male line, and female autonomy was eroded. As a result, the argument goes, patriarchy emerged.', NULL, NULL, NULL, E'1.relocate, 2.oppression, 3.advent, 4.shifted', NULL, NULL),
  ('e1f01efd-08e5-59e9-92d6-044f84e37d18'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e1f01efd-08e5-59e9-92d6-044f84e37d18'::uuid, 1, NULL, TRUE, 0, NULL, E'Lost Wallet', E'You’re at a salon and you want to get a haircut, but you realize that you left your wallet in your taxi. You don’t have the taxi number and you don’t have any other payment methods with you. What will you tell the stylist in order to resolve this situation?', 'dc602b0e-1a10-5a1b-8a23-2c5b91783d6f'::uuid, NULL, NULL, NULL, NULL, NULL),
