  ('e1fb97eb-9817-5a58-9c5f-e05ed802874a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e1fb97eb-9817-5a58-9c5f-e05ed802874a'::uuid, 1, NULL, TRUE, 0, NULL, E'Trump', E'Trump has threatened to declare China a currency manipulator, but experts say he has little legal or economic basis to take such a step. He has also threatened to impose a tariff of up to 45 percent on Chinese imports if Beijing doesn''t behave a move that could lead to a trade war and damage the economies of both nations.', NULL, NULL, NULL, NULL, NULL, NULL),
