  ('e20711f3-1752-53fc-840d-d9f86b8937a7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e20711f3-1752-53fc-840d-d9f86b8937a7'::uuid, 1, NULL, TRUE, 0, NULL, E'New Languages', E'Learning a new language at an early age is helpful for children. It is more positive for their future prospects, though it can also have some adverse effects. Do you agree or disagree?', NULL, NULL, NULL, NULL, 200, 300),
  ('e207780c-4038-5fd6-a8fe-0ab587b7cebb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e207780c-4038-5fd6-a8fe-0ab587b7cebb'::uuid, 1, NULL, TRUE, 0, NULL, E'Elevated Front Door', E'Years ago on a trip to Newfoundland, retired traveler Jackie Jansen began documenting a strangely persistent phenomenon: front doors {{1}} high above the ground. Odder still: these elevated entries had no stairs to speak of, leaving her to wonder why. It turns out there are competing theories about these unusual portals. Locals told Jansen and her husband (presumably tongue in cheek) that such “mother-in-law doors” were for ushering out {{2}} in-laws, but that’s not the only tall tale going around about these quirky designs. Some have speculated that these seemingly useless secondary doors are a product of building regulations — when Newfoundland joined Canada in the late 1940s, they suddenly had to {{3}} new fire regulations that required two modes of egress for houses. Following the letter of the law, the theory goes, a door was added, but no stairs, since technically that was not included in the legal {{4}} .', NULL, NULL, NULL, E'1.raised, 2.unwanted, 3.match, 4.requirement', NULL, NULL),
  ('e20bcf34-f463-5ffa-9df8-f310ab2bb2ae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e20bcf34-f463-5ffa-9df8-f310ab2bb2ae'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '092ca13e-7008-57b3-88a8-03b122635db0'::uuid, NULL, E'Meeting with tutors could be arranged for students who need additional help.', NULL, NULL, NULL),
  ('e211affe-ff5f-5e54-9aaf-0f2a9f02aa70'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e211affe-ff5f-5e54-9aaf-0f2a9f02aa70'::uuid, 1, NULL, TRUE, 0, NULL, E'Sea Breeze', E'The sea breeze is one of the most frequently occurring small-scale weather systems. It results from the unequal sensible heat flux of the lower atmosphere over adjacent solar-heated land and water masses. Owing to the large thermal inertia of a water body, during daytime the air temperature changes little over the water while over land the air mass warms.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e2178ce0-cabe-5a63-b413-f938feb9dda8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e2178ce0-cabe-5a63-b413-f938feb9dda8'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'db104527-9ee5-5f6a-9f50-cd968b0f603a'::uuid, NULL, NULL, E'Students engaged in research often face the greatest challenge in securing funding.', NULL, NULL),
  ('e2192eaf-1168-50c3-a1a2-ef4775562e1d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e2192eaf-1168-50c3-a1a2-ef4775562e1d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ee09c55f-9634-5ac5-92c6-abfad1d380cb'::uuid, NULL, E'In this course we will look at some Indian literature in its social context.', NULL, NULL, NULL),
  ('e21be87b-37b9-5317-97a8-a16e8910ac26'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e21be87b-37b9-5317-97a8-a16e8910ac26'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0e2d0116-8fe1-55e9-ba99-88ee7ce5dd73'::uuid, NULL, E'The number of students registering for postgraduate research has risen.', NULL, NULL, NULL),
  ('e21e3aa1-158c-579b-8417-e84ae6d40094'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e21e3aa1-158c-579b-8417-e84ae6d40094'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '863b10eb-c305-5d3e-8286-d5548353b441'::uuid, NULL, NULL, E'Statistical findings need to be presented differently in various situations.', NULL, NULL),
  ('e21fe49d-689d-5b4f-b6c4-d289f10cdcea'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e21fe49d-689d-5b4f-b6c4-d289f10cdcea'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd5bcc780-dc51-5ab4-8950-717038f32acd'::uuid, NULL, NULL, E'Theory and training are required to become a medical specialist.', NULL, NULL),
  ('e2206a81-a41f-526f-af37-514498e874e7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e2206a81-a41f-526f-af37-514498e874e7'::uuid, 1, NULL, TRUE, 0, NULL, E'SMW', E'In some ways, mental development is related to social development. In school age, children between the ages of six and twelve children move from being able to think only on a concrete level. That is about real objects they can touch to being capable of abstract thought in their social development. Children gradually acquire interpersonal reasoning skills. They learn to understand the feelings of other people, and also learned that a person''s actions or words don''t always reflect their.\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '24ec604d-61db-5019-b09f-814b1cc3e589'::uuid, NULL, NULL, E'inner feelings', NULL, NULL),
  ('e224feec-75f1-5da5-ab66-af7a58008e13'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e224feec-75f1-5da5-ab66-af7a58008e13'::uuid, 1, NULL, TRUE, 0, NULL, E'A Rare Fossil Record', NULL, '1035fb78-93b7-5862-9337-96f758ab4da9'::uuid, NULL, E'The preservation of embryos and juveniles is a rate occurrence in the fossil record. The tiny, delicate skeletons are usually scattered by scavengers or destroyed by weathering before they can be fossilized. Ichthyosaurs had a higher chance of being preserved than did terrestrial creatures because, as marine animals, they tended to live in environments less subject to erosion. Still, their fossilization required a suite of factors: a slow rate of decay of soft tissues, little scavenging by other animals, a lack of swift currents and waves to jumble and carry away small bones, and fairly rapid burial. Given these factors, some areas have become a treasury of well-preserved ichthyosaur fossils.\nThe deposits at Holzmaden, Germany, present an interesting case for analysis. The ichthyosaur remains are found in black, bituminous marine shales deposited about 190 million years ago. Over the years, thousands of specimens of marine reptiles, fish and invertebrates have been recovered from these rocks. The quality of preservation is outstanding, but what is even more impressive is the number of ichthyosaur fossils containing preserved embryos. Ichthyosaurs with embryos have been reported from 6 different levels of the shale in a small area around Holzmaden, suggesting that a specific site was used by large numbers of ichthyosaurs repeatedly over time. The embryos are quite advanced in their physical development; their paddles, for example, are already well formed. One specimen is even preserved in the birth canal. In addition, the shale contains the remains of many newborns that are between 20 and 30 inches long.\nWhy are there so many pregnant females and young at Holzmaden when they are so rare elsewhere? The quality of preservation is almost unmatched and quarry operations have been carried out carefully with an awareness of the value of the fossils. But these factors do not account for the interesting question of how there came to be such a concentration of pregnant ichthyosaurs in a particular place very close to their time of giving birth.', NULL, NULL, NULL),
  ('e22db127-906e-5515-8205-44da9f636cb2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e22db127-906e-5515-8205-44da9f636cb2'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the political system in which a country is ruled by a king or a queen?', 'acb44c37-fde3-57a9-9f4a-bee90e8595d8'::uuid, NULL, NULL, E'Monarchy', NULL, NULL),
  ('e22ddb5b-9949-5253-b20e-2b946776dc17'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e22ddb5b-9949-5253-b20e-2b946776dc17'::uuid, 1, NULL, TRUE, 0, NULL, E'Politeness in Communication', E'In human communication, the communicators involved in the interaction have an {{1}} to show politeness to each other for a successful {{2}} .Non-observance of politeness in a communicative act has the {{3}} to infringe upon the public self-image of the addressees. When people become aware of the importance of the {{4}} of their interlocutors, they tend to avoid embarrassments and incendiary language.', NULL, NULL, NULL, E'1.obligation, 2.conversation, 3.potential, 4.needs', NULL, NULL),
  ('e22ffda6-1013-51ff-aede-3d22817fb7c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e22ffda6-1013-51ff-aede-3d22817fb7c5'::uuid, 1, NULL, TRUE, 0, NULL, E'John Locke', NULL, 'da715ea9-1f8e-5c63-ba6d-068fcc28b6a0'::uuid, NULL, E'During the time when the church controlled what people could believe, and the kings ruled over what people ought to own, John Locke, an English doctor, popularized three ideas that changed society and parenting forever. First, people keep fighting over their beliefs, because nobody can actually know which one is true. To solve this problem, everyone should have freedom of thought and the right to choose their own religion. Second, kings can’t just do as they please, because people have natural rights to liberty, property and life, and hence need to be asked for permission. Third, parents should avoid punishing their children, since the use of emotions to make them behave well can make them sensationalist. Instead, they should allow their children to be guided by thoughts. Locke’s idea on religion and democracy became the foundation of most liberal societies. His thoughts on education, however, may have been even more influential. Locke understood that most people doubt new ideas, without any other apparent reason than them being uncommon. However, teaching children how to think rationally and all for themselves works. Education is therefore the key to freeing society from political and psychological tyranny. And his book, Some Thoughts Concerning Education, became a parenting guide to that world.', NULL, NULL, NULL),
  ('e236133e-933e-51ea-852c-c563c309bbc0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e236133e-933e-51ea-852c-c563c309bbc0'::uuid, 1, NULL, TRUE, 0, NULL, E'Natural World', E'The natural world is full of wonder and beauty, from the towering mountains to the vast oceans and everything in between. It provides us with essential resources such as clean air and water, as well as recreational opportunities that promote physical and mental health.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e238584c-bdbc-5e72-8eac-4ae7d0195960'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e238584c-bdbc-5e72-8eac-4ae7d0195960'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6e965880-f209-5f07-b5b0-5e6e72fd4a56'::uuid, NULL, E'The parties agree they will respect all members of this academic community.', NULL, NULL, NULL),
  ('e23e6695-6d5d-573a-aa08-b9ab982b8900'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e23e6695-6d5d-573a-aa08-b9ab982b8900'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '670dd9cc-a1e5-5e09-8f6d-14e953b6cd8e'::uuid, NULL, NULL, E'Soon, forms will be handed out to students coming back to school.', NULL, NULL),
  ('e256d682-5ee2-59ef-8e77-541b32434fd3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e256d682-5ee2-59ef-8e77-541b32434fd3'::uuid, 1, NULL, TRUE, 0, NULL, E'Skipping Breakfast(B)', E'Skipping breakfast has drawbacks. It''s no mystery why so many people routinely skip breakfast: bad timing. It comes at a time when folks can be more occupied with matters of grooming, attire and otherwise making themselves presentable for a new day. However, studies conducted both in the United States and internationally have shown that skipping breakfast can affect learning, memory and physical well-being. Students who skip breakfast are not as efficient at selecting critical information for problem-solving as their peers who have had breakfast. For school children, skipping breakfast diminishes the ability to recall and use newly acquired information, verbal fluency, and control of attention, according to Ernesto Pollitt, a UC Davis professor of pediatrics whose research focuses on the influence of breakfast on mental and physical performance. Skipping breakfast can impair thinking in adults, also. For both children and adults, a simple bowl of cereal with milk goes a long way toward providing a sufficiently nutritious start to the day. Green-Burgeson recommends choosing a cereal that''s low in sugar — less than five grams per serving — and using nonfat or one percent milk. Frederick Hirshburg, a pediatrician at UC Davis Medical Group, Carmichael, says that babies and other preschoolers rarely skip breakfast because they''re usually the hungriest at the beginning of the day. Breakfast then becomes more of a "learned experience" than a response to a biological need, Hirshburg says.', NULL, NULL, E'Skipping breakfast affects learning, memory and physical well-being, as well as diminishing school children''s ability to recall and use newly acquired information, and can also impair thinking in adults, while a simple bowl of cereal with milk goes a long way toward providing a sufficiently nutritious start to the day, so breakfast has become more of a "learned experience" than a response to a biological need.', NULL, 5, 75),
  ('e25ab30f-1f97-510d-9c1c-3b8a4d55c842'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e25ab30f-1f97-510d-9c1c-3b8a4d55c842'::uuid, 1, NULL, TRUE, 0, NULL, E'Food Waste', E'One of the complex agricultural problems is the issue of food waste. Food waste refers to the discarding of edible food at various stages of the food supply chain, from production to consumption. This not only represents a significant loss of resources but also has environmental implications, such as greenhouse gas emissions from decomposing food waste in landfills.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e262d15b-730f-5012-9147-5ec7e0d955f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e262d15b-730f-5012-9147-5ec7e0d955f0'::uuid, 1, NULL, TRUE, 0, NULL, E'Heart Disease', E'Heart disease is the leading cause of death for both men and women in the United States. While often thought of as one illness, heart disease is actually an umbrella term that covers a range of heart conditions. It includes diseases of the blood vessels, including coronary artery disease (CAD) and peripheral artery disease (PAD) and so on. Symptoms of heart disease can vary depending on which type you have and whether you are a man or a woman. For example, with a heart attack, men are more likely to experience chest pain, while women are more likely to have symptoms other than chest discomfort, like nausea, shortness of breath, and fatigue.\nThe causes of heart disease also vary depending on the type of disease. CAD and PAD are caused by atherosclerosis, or the buildup of cholesterol and other material called plaque in the arteries. This buildup of plaque can result in the narrowing of arteries, which makes it harder for blood to flow and can result in a heart attack or stroke.\nBefore a heart disease diagnosis is made, your healthcare provider will gather a full medical history and perform a physical exam. If your doctor suspects heart disease, blood tests will be ordered to check your cholesterol and triglyceride levels, as well as look for proteins that could signal heart failure or plaque in your arteries. A chest X-ray will also help your doctor look for signs of heart failure or heart valve problems.', NULL, NULL, NULL, NULL, 5, 75),
  ('e26b5fc7-80a2-5950-a516-194164b2a777'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e26b5fc7-80a2-5950-a516-194164b2a777'::uuid, 1, NULL, TRUE, 0, NULL, E'Water that Dissolves', NULL, 'cc309fc5-311e-59eb-9c91-2ecbdc89b36e'::uuid, NULL, E'We make our countertops with quartz, our clothes with cotton, our windows with glass, and our streets with asphalt because water can’t dissolve these materials. They’re made mostly of molecules with no charged parts. It would be silly to build, say, windows with something that can dissolve in water, like sugar... unless you’re going to eat them. And lots of the substances that water DOES dissolve, like washable markers, are things we engineered so that they can be washed away. We’ve also engineered versions that aren’t dissolvable in water for when we don’t want them to be washed away. By making sure water dissolves what we want it to and only what we want it to. We’ve been able to adapt a life to a world in which water dissolves so much stuff. We humans also literally adapted to a world in which water dissolves so much stuff. The outer layer of our skin is built in a way that makes it uncharged and therefore undissolvable. And the membrane surrounding each of the cells inside us has a similar undissolvable layer. The only reason we humans exist at all on this watery planet or that trees, fish, bacteria, or anything else exists is that we evolved barriers that could keep water from dissolving us into goo. Any life forms that didn’t were simply dead in the water.', NULL, NULL, NULL),
  ('e278a2f7-ec6c-51f4-a139-d2f1dd072382'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e278a2f7-ec6c-51f4-a139-d2f1dd072382'::uuid, 1, NULL, TRUE, 0, NULL, E'Practical Nature', E'Considerations of a practical nature give us the most {{1}} possible grounds for a belief that human desires, feelings, etc., are homogeneous and communicable. The fact is that we all have back of us many millions of years of evolutionary history in the same general environment. In the past, with relatively minor {{2}} , the same influences have played upon our ancestors from the beginnings of life on our planet. And then, we are born into the same society, and it has given us, not, to be sure, the power of {{3}} , but certainly all of our most essential stimuli. Further, we do get along in society. We laugh together, and we play together, we share each other''s sorrows, we love and hate each other, in a way that would be wholly impossible if we did not in practice {{4}} the correctness of our ''inferences'' about one another''s motives and desires. And the fact that these ''inferences'' are in the main correct is the one thing that makes social life possible. We can, and do, understand one another''s motives, desires, wants, emotions. We can, and do, {{5}} communicate our feelings to one another.', NULL, NULL, NULL, E'1.reliable, 2.variations, 3.reaction, 4.assume, 5.consistently', NULL, NULL),
  ('e27abf94-493a-5081-b3d7-cf3230367a6f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e27abf94-493a-5081-b3d7-cf3230367a6f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the electronic device used to maintain a comfortable temperature indoors?', 'b4ee7111-aa9d-5b99-86bf-8e97409a26db'::uuid, NULL, NULL, E'Air Conditioner', NULL, NULL),
  ('e28396de-8071-58ef-9033-e527ad00c180'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e28396de-8071-58ef-9033-e527ad00c180'::uuid, 1, NULL, TRUE, 0, NULL, E'Neanderthals'' Diet', E'When it comes to Neanderthal diets, the {{1}} has been: they ate meat. Lots of meat. But now it looks like Neanderthals chomped on a fair amount of veggies, too.\nResearchers have had a tough time discerning the Neanderthals'' diet. They evaluated carbon and nitrogen isotopes in bones, but those only {{2}} to some general kinds of proteins. Even plant remains in Neanderthal teeth could have gotten there because a tasty animal carcass itself contained traces of a last {{3}} meal.\nSo the researchers relied on {{4}} evidence—they studied Neanderthal fecal remains from a site in southern Spain called El Salt. Neanderthals made it their home about 50,000 years ago.\nThe researchers analyzed the samples for chemical compounds that can only result from metabolizing cholesterol from meat or from metabolizing plants. All five samples showed evidence of meat {{5}} . But two revealed the digestion of plants. Meaning that Neanderthals did try vegetation, likely tubers and nuts. The study is in the journal PLoS ONE. Ainara Sistiaga et al,\nThe scientists intend to use the same technique to examine soil samples at a 1.8 million-year-old site in Tanzania. In the hopes that any remaining poop may deliver an {{6}} scoop.', NULL, NULL, NULL, E'1.consensus, 2.correspond, 3.vegetarian, 4.foolproof, 5.consumption, 6.ancestral-diet', NULL, NULL),
  ('e28400e2-6687-5a0e-893b-52de84cff594'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e28400e2-6687-5a0e-893b-52de84cff594'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How to stimulate an individual''s immune system to develop adaptive immunity to a kind of viral?', 'f6b33ea4-eeb8-5990-b2b5-dc9489d13bcd'::uuid, NULL, NULL, E'Vaccinate', NULL, NULL),
  ('e2876c8d-895f-5801-9717-7491f95a3635'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e2876c8d-895f-5801-9717-7491f95a3635'::uuid, 1, NULL, TRUE, 0, NULL, E'Lifetime Employment', E'Businesses should employ people for life. What are the advantages and disadvantages of lifetime employment system?', NULL, NULL, NULL, NULL, 200, 300),
  ('e290a660-2d2f-54f2-8d13-3c12a36b0bdb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e290a660-2d2f-54f2-8d13-3c12a36b0bdb'::uuid, 1, NULL, TRUE, 0, NULL, E'Pullman', E'Built in 1880 on 4,000 acres of {{1}} outside of the Chicago city limits, Pullman, Illinois, was the first industrial planned {{2}} in the United States. George Pullman, of the Pullman railroad Car Company, built the south residential portion of the company town first, which contained 531 {{3}} , some of which stand today more or less as they did originally.', NULL, NULL, NULL, E'1.land, 2.community, 3.houses', NULL, NULL),
  ('e2930ac2-3ab4-59c4-b582-08b9c5387ea4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e2930ac2-3ab4-59c4-b582-08b9c5387ea4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd39601de-6fab-5ab8-a462-e7e929372388'::uuid, NULL, NULL, E'Even simple techniques need to be practiced to become perfect.', NULL, NULL),
  ('e293fa8f-96aa-52cb-b8d6-b63e33feac58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e293fa8f-96aa-52cb-b8d6-b63e33feac58'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the largest type of deer?', 'fed7ae6a-92e1-583c-89b1-e27ff8d4a03b'::uuid, NULL, NULL, E'Moose', NULL, NULL),
  ('e297b055-0098-596a-9541-e5a7b0640534'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'e297b055-0098-596a-9541-e5a7b0640534'::uuid, 1, NULL, TRUE, 0, NULL, E'Learning Categories', NULL, NULL, NULL, NULL, E'2, 3, 5, 4, 1', NULL, NULL),
  ('e29efcab-da3f-501a-98e0-e25919be18d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e29efcab-da3f-501a-98e0-e25919be18d5'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do we describe the products that can be used for a long time without breaking or getting weaker?', '5159b78f-e8a3-51e5-857a-fc12f6c73973'::uuid, NULL, NULL, E'Durable', NULL, NULL),
  ('e2a06bd2-2918-5358-8a5e-19e16438455e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'e2a06bd2-2918-5358-8a5e-19e16438455e'::uuid, 1, NULL, TRUE, 0, NULL, E'Ethiopian Runners', NULL, NULL, NULL, NULL, E'3, 1, 5, 2, 4', NULL, NULL),
  ('e2a27b49-893a-5366-8e85-9bd5e7b3e602'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e2a27b49-893a-5366-8e85-9bd5e7b3e602'::uuid, 1, NULL, TRUE, 0, NULL, E'Subjective Age', E'"Age is an issue of mind over matter. If you don''t mind, it doesn''t matter." This {{1}} of wisdom, often attributed to Mark Twain, has been turned into many an {{2}} internet meme over the years. As a 51-year-old who is starting to feel the gathering momentum of the inevitable slide, it strikes me as little more than a platitude that makes people feel better about getting old. But according to a growing body of research, there is more to it than that. Subjective age – how old we feel – has a very real impact on health and {{3}} . People who feel younger than their years often actually are, in terms of how long they have left to live. The question of what controls our subjective age, and whether we can change it, has always been tricky to {{4}} scientifically.', NULL, NULL, NULL, E'1.nugget, 2.inspirational, 3.longevity, 4.address', NULL, NULL),
  ('e2a4a473-2f7c-5d20-a026-7a30930cfbb1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e2a4a473-2f7c-5d20-a026-7a30930cfbb1'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c0930b45-f10e-5f3c-8205-813b0d82ca59'::uuid, NULL, E'Overeating can lead to numerous health problems and should be avoided.', NULL, NULL, NULL),
  ('e2aaec5b-0885-5ebb-8077-96586b2e7fba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e2aaec5b-0885-5ebb-8077-96586b2e7fba'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we measure in Celsius?', '5f6b48e5-53df-56db-a242-54d35159c8e3'::uuid, NULL, NULL, E'Temperature', NULL, NULL),
  ('e2ae5433-8c48-55c9-af8d-e01c75961268'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e2ae5433-8c48-55c9-af8d-e01c75961268'::uuid, 1, NULL, TRUE, 0, NULL, E'Moon', E'Both the rotation of the moon and its revolution around earth takes twenty seven days, seven hours and forty three minutes, to be exact. Because of this motion, the moon appears to move about thirteen degrees against for stars each day, or about half of a degree per hour. If you watch the moon over the course of several hours one night, you will notice that its position among the stars will change by a few degrees. The changing position of the moon with respect to the sun leads to lunar phases.\n\nHow long does the moon take to rotate around Earth?', 'f6849c03-708f-50a1-aeb1-ac87a3a6d60b'::uuid, NULL, NULL, E'27 days, 7 hours, and 43 minutes', NULL, NULL),
  ('e2afbd9a-266b-5600-8bd3-0838c7616c19'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e2afbd9a-266b-5600-8bd3-0838c7616c19'::uuid, 1, NULL, TRUE, 0, NULL, E'Thermodynamics (B)', NULL, '4118f5c5-1dd6-51d6-8904-710d23592421'::uuid, NULL, E'Thermodynamics is the science of the flow of heat. So, thermo is heat, and dynamic is the motion of heat. Thermodynamics was developed largely beginning in the 1800''s, at the time of the Industrial Revolution. So, taming of steel. The beginning of generating power by burning fossil fuels. The beginning with the problems with CO2 and global warming. In fact, it''s interesting to note that the first calculation on the impact of the CO2 on climate was done in the late 1800''s by Arrhenius. Beginning of a generation of power moving heat from fossil fuels to generating energy, locomotives, etcetera. So, he calculated what would happen to this burning of fossil fuels, and he decided in his calculation, he basically got the calculation right, by the way, but he came out that in 2,000 years from the time that he did the calculations, human would be in trouble.', NULL, NULL, NULL),
  ('e2b0e0ac-64ba-564a-ae6c-58ca2db9c648'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'e2b0e0ac-64ba-564a-ae6c-58ca2db9c648'::uuid, 1, NULL, TRUE, 0, NULL, E'Paleontologists(古生物学家)', NULL, NULL, NULL, NULL, E'4, 3, 1, 2', NULL, NULL),
  ('e2c0a40f-8795-572e-9233-bf3289e258b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e2c0a40f-8795-572e-9233-bf3289e258b2'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Where do scientists conduct experiments?', '5d22f95e-74ec-5b47-83d0-23ecbc2b767b'::uuid, NULL, NULL, E'Laboratory / lab', NULL, NULL),
