  ('e2d3a818-616b-5d99-b337-b2ebaab26153'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e2d3a818-616b-5d99-b337-b2ebaab26153'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ee9a4cc6-b9ab-5a22-af0c-13bdcd9e468c'::uuid, NULL, E'People get product information from advertisements, friends, family and product reviews.', NULL, NULL, NULL),
  ('e2d3b4a5-4576-593f-9e71-40a5fcab88b5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e2d3b4a5-4576-593f-9e71-40a5fcab88b5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'dbe1b0d9-d2a9-5994-b06f-638d8bf95313'::uuid, NULL, NULL, E'Diving into hobbies can lead to a lot of personal happiness.', NULL, NULL),
  ('e2d8adef-3ccf-5207-ae01-b2f63197392e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e2d8adef-3ccf-5207-ae01-b2f63197392e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What kind of equipment is used to protect motorbike riders'' brains from injury?', '55c1641d-e021-58f2-be89-6d98f8788d3c'::uuid, NULL, NULL, E'Helmet', NULL, NULL),
  ('e2dd3094-129b-52fa-9e45-78b454189738'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e2dd3094-129b-52fa-9e45-78b454189738'::uuid, 1, NULL, TRUE, 0, NULL, E'Dolphins', E'Alzheimer’s is the most common cause of dementia. It affects memory, thinking, and behavior and it’s serious enough to {{1}} with daily life. The main risk factor is increasing age, and most people with Alzheimer’s are 65 or older. Until now, this was thought to be a human-only disease, but this may not be the case. The brains of three species of dolphins {{2}} along the coast of Scotland have shown the classic markers of human Alzheimer’s disease – {{3}} that dolphins too may be plagued by the disease. The researchers still don’t know why this brain {{4}} could be happening in odontocetes, but it could explain why some groups of whales, dolphins, and porpoises run aground in shallow water.', NULL, NULL, NULL, E'1.interfere, 2.stranded, 3.hinting, 4.degeneration', NULL, NULL),
  ('e2ddbfdc-748d-51fe-9b06-b010c045c2b1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e2ddbfdc-748d-51fe-9b06-b010c045c2b1'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '972a0a55-d81f-5117-ba0d-7149d2f8c7ba'::uuid, NULL, NULL, E'The main ideas of these events remain largely not understood.', NULL, NULL),
  ('e2e39aed-958b-5e6a-980b-96f378191a4f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e2e39aed-958b-5e6a-980b-96f378191a4f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'baf2fb9d-bcc3-5827-a76c-fd4daad318c7'::uuid, NULL, NULL, E'Eating is prohibited within the main sections of the library.', NULL, NULL),
  ('e2e4172a-cecf-5e82-8ec5-0e2a1d7bc63b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e2e4172a-cecf-5e82-8ec5-0e2a1d7bc63b'::uuid, 1, NULL, TRUE, 0, NULL, E'Genie', NULL, '69466212-60c0-5a13-b71e-53f3dd389ecd'::uuid, NULL, E'Genie spent the first 13 years of her life locked away in a small bedroom in her parents’ home. In 1970, her parents were charged with child abuse and Genie began rehabilitation with a team of psychologists and linguists. And scientists were using her experiences to answer the following question: if a person is deprived of language throughout their childhood, can they ever learn enough to be able to communicate well? At first, the answer appeared to be yes. Genie quickly began to learn new words for the objects around her and even say phrases with two or three words similar to how toddlers speak. However, from there, her ability to communicate verbally plateaued. This is because she could not learn grammar, which linguist Noam Chomsky believes separates human language from the communication of animals. It appeared that Genie had passed the critical period of learning human language, which is thought to end around puberty. Scientists have hypothesized that, after a restricted developmental period where the nervous system is particularly sensitive to the effects of a certain experience, in this case, language, it is nearly impossible to learn it. And the same effects have also been shown when learning sign language after the critical period. Now you’re probably wondering why there is a critical period in the first place. According to Eric Lenneberg, the linguist who popularized the critical period hypothesis, the function of language tends to settle in the left hemisphere of the brain after the critical period. And it’s thought that the brain loses some of its plasticity after this lateralization. So, if you haven’t learned language until after this point, it may be harder for your brain to learn the new material. And sadly for Genie, she was already past that point. However, while Genie would never be able to effectively use language, she was able to quickly learn other things, such as how to use the toilet and dress herself.', NULL, NULL, NULL),
  ('e2e84f4e-b877-506c-977b-136816ea023f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e2e84f4e-b877-506c-977b-136816ea023f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6e63949c-184a-5b55-9f8f-28e149bd08d8'::uuid, NULL, NULL, E'In some countries, people live in homes made from shipping containers.', NULL, NULL),
  ('e2f05cb5-0a9c-5209-9710-85fbdb6b74aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e2f05cb5-0a9c-5209-9710-85fbdb6b74aa'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a9b3ebe1-7a80-5125-95be-ad2a0a2576ff'::uuid, NULL, E'We want to improve the quality of life and the standard of living.', NULL, NULL, NULL),
  ('e2f123ec-7115-5501-9fa6-b5c401bd8db8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e2f123ec-7115-5501-9fa6-b5c401bd8db8'::uuid, 1, NULL, TRUE, 0, NULL, E'Carski Award', E'In 2001 he received the SIUC Outstanding Scholar Award. In 2003 he received the Carski Award for Distinguished Undergraduate Teaching from the American Society for Microbiology. Mike''s research is {{1}} on bacteria that inhabit {{2}} environments, and for the past 12 years he has studied the microbiology of permanently ice-covered lakes in the McMurdo Dry Valleys, Antarctica. In addition to his research papers, he has edited a major {{3}} on phototrophic bacteria and served for over a decade as chief editor of the {{4}} Archives of Microbiology. He currently serves on the editorial board of Environmental Microbiology. Mike''s non-scientific {{5}} include forestry, reading, and caring for his dogs and horses. He lives beside a peaceful and quiet lake with his wife, Nancy, five shelter dogs (Gaino, Snuffy, Pepto, Peanut, and Merry), and four horses (Springer, Feivel, Gwen, and Festus).', NULL, NULL, NULL, E'1.focused, 2.extreme, 3.treatise, 4.journal, 5.interests', NULL, NULL),
  ('e2f25559-4ed8-589f-a1fb-8687de534c88'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e2f25559-4ed8-589f-a1fb-8687de534c88'::uuid, 1, NULL, TRUE, 0, NULL, E'Shrimp Farm', E'Over the past two decades around a third of the world''s mangrove swamps have been {{1}} for human use, with many turned into valuable shrimp farms. In 2007 an economic study of such shrimp farms in Thailand showed that the commercial profits per hectare were $9,632. If that were the only {{2}} , conversion would seem an excellent idea.\nHowever, proper {{3}} shows that for each hectare government subsidies formed $8,412 of this figure and there were costs, too: $1,000 for pollution and $12,392 for losses to ecosystem services. These {{4}} damage to the supply of foods and medicines that people had taken from the forest, the loss of habitats for fish, and less buffering against storms. And because a given shrimp farm only stays {{5}} for three or four years, there was the additional cost of restoring them afterwards: if you do so with mangroves themselves, add another $9,318 per hectare. The overall lesson is that what looks {{6}} only does so because the profits are retained by the private sector, while the problems are spread out across society at large, appearing on no specific balance sheet.', NULL, NULL, NULL, E'1.converted, 2.factor, 3.accounting, 4.comprised, 5.productive, 6.beneficial', NULL, NULL),
  ('e2f37398-566e-50b8-9196-d6448182d8a1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e2f37398-566e-50b8-9196-d6448182d8a1'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '89ed2b81-3774-571c-a276-b23ea6c2cb44'::uuid, NULL, NULL, E'Teaching assistants will receive a monthly stipend for housing.', NULL, NULL),
  ('e2f6d02d-ce4e-5601-8fff-b63a7a4ea36b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e2f6d02d-ce4e-5601-8fff-b63a7a4ea36b'::uuid, 1, NULL, TRUE, 0, NULL, E'Forest', E'Mr has been invited to speak to a group of students, listen to part of the talk. No matter whether we live in the country, the suburbs or the city. We come in contact with forests every day, a combination of trees, other plants, insects, wildlife, soil, water, air, and people is a forest. I''m a professional forester. That means i''ve been trained in the management of forests. Managing a forest is both a science and an art, which is why my education included courses in the biological, physical, and social sciences as well as the humanities. Doesn''t being a forester mean you always work in the woods? Foresters, of course, do work in the woods more and more. However, they also work in laboratories, classrooms, planning agencies, corporate offices, and so forth. In fact, our professional organization, the society of american foresters, lists over seven hundred job categories. I''ve always been confused about the difference between a national park and the national forest. In a lot of ways. They''re similar. For example, we can camp and hike in both. There is a difference between them. National parks such as yellowstone are set aside and preserved in a near natural state, mainly for the recreational enjoyment of the public. Our parks are administered by the department of the interior. National forests, on the other hand, are administered by the department of agriculture. Our forests are managed for their many benefits, including recreation, wood products, wildlife, and water. That means there''s a difference between a forester and a park ranger. Right? Yes, there are differences. A forester manages an area of forest for forest products, water quality, wildlife recreation, and so on. A park ranger, on the other hand, manages an area in a national or state park mainly for recreation. Another difference is who owns the land? A forester can work on federal, state, or private land, while a park ranger is almost always a government employee. My major is biology, but i''d like to work in the woods in the area of wildlife preservation. Would that make me a forester or a biologist? Some foresters are primarily biologists, but most foresters majored in forestry management. Foresters and wildlife biologists often work together as a team. Both foresters and biologists want to see that various types of habitat flourish, dear, for example, require a different habitat than wolves, yet the forest can accommodate them both.\n\nWhat is the talk mainly about?', '88984e9c-1d54-500f-84a6-831d4d580c4b'::uuid, NULL, NULL, E'Forestry as a profession\nWhere foresters work', NULL, NULL),
  ('e2fa3214-8562-5bfd-bc98-7a470077d78a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e2fa3214-8562-5bfd-bc98-7a470077d78a'::uuid, 1, NULL, TRUE, 0, NULL, E'Diabetes and Obesity', E'Diabetes and obesity rates can be reduced by {{1}} towns and cities into places where it is safe and {{2}} to walk, cycle or take public transport rather than drive. Scientists scoured more than 170 previous studies and discovered {{3}} evidence that people who live in areas where walking and cycling are practical options are more active and less likely to have diabetes or obesity.', NULL, NULL, NULL, E'1.transforming, 2.convenient, 3.consistent', NULL, NULL),
  ('e3034d5f-9b1d-5977-b2f7-382c1ae72217'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e3034d5f-9b1d-5977-b2f7-382c1ae72217'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e8e44b0b-12b4-5fc4-8b9c-a27913aef197'::uuid, NULL, E'The teacher tried to gain her student''s attention by clapping her hands loudly.', NULL, NULL, NULL),
  ('e3052929-bb1c-5dfe-a11f-006c4e0436f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e3052929-bb1c-5dfe-a11f-006c4e0436f9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0a7ff215-99d8-51a4-9cca-f93e94de50a5'::uuid, NULL, E'My particular interest is in the eighteenth century French society.', NULL, NULL, NULL),
  ('e307ad03-a31d-580d-a825-fe1dd5b8d9cb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e307ad03-a31d-580d-a825-fe1dd5b8d9cb'::uuid, 1, NULL, TRUE, 0, NULL, E'Meal Invitation', E'A friend, Mike, invites you to a meal and asks if you have any dietary restrictions. You don''t have any, but your partner is allergic to milk.\nWhat would you say to him?', '1473a0b8-23ae-5db7-8060-c8c19c8b76af'::uuid, NULL, E'Hey Mike, I want to talk to you about something.\nWe seem to have a little issue with dietary requirements for your dinner.\nIt''s like I don''t have any dietary restrictions, but my partner is allergic to milk.\nAnd I''d like to know what you think.', NULL, NULL, NULL),
  ('e30fef4a-9f56-5df7-9d74-724a3a90c09a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e30fef4a-9f56-5df7-9d74-724a3a90c09a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0e7cab59-4bcd-53f4-a5ce-768ac4ac4bcd'::uuid, NULL, NULL, E'Sugar is a compound including carbon, hydrogen and oxygen atoms.', NULL, NULL),
  ('e312e502-e125-51ee-a31a-733f37cd3c2f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e312e502-e125-51ee-a31a-733f37cd3c2f'::uuid, 1, NULL, TRUE, 0, NULL, E'Global Business', E'Political risk and nationalism have had major impacts on the development and retardation of global business. Two World Wars, the protectionism of the 1930s, and subsequent waves of economic nationalism damaged the global economy severely and threw it into reverse, though temporarily and partially, and changed the trajectory of globalization during the twentieth century. Wartime blockades, interwar trade barriers, and policies of sovereign nations protecting or serving national interests dealt a blow to the global integration of the market. The two World Wars also brought about technological innovation, and partly contributed to the rise of regions that had been traditionally on the periphery, and laid the basis for today’s multi-polar global economy. Under these pressures, global business looked to transform itself from being based on a unitary structure to a multi-centred one: today’s multinational corporations were created to operate beyond the constraints imposed by the sovereign states. In addition, the economic entities involved in global business created international public goods on their own, such as special safe havens, rather than remaining passive to the actions of sovereign states. Ironically, however, this seems to be creating a new kind of political risk and widespread anti-globalism. The effects of political risks, due to their nature, showed significant geographical differences. They varied widely between European and US companies. In Europe, where serious risks such as war and occupation became a reality, the capability to address political risks had a great impact on the rise, fall, and survival of firms, while in US, such risks have little impact on companies.', NULL, NULL, NULL, NULL, 5, 75),
  ('e31329ca-2430-52ed-abae-76ddff52bc07'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e31329ca-2430-52ed-abae-76ddff52bc07'::uuid, 1, NULL, TRUE, 0, NULL, E'Moth', E'Why are moths fatally attracted to the light? {{1}} is the old glib theory that the moths are trying to use the flame to navigate. {{2}} does not tell us, {{3}} , why it is that in many species only males are thus attracted, and in a few, only females. {{4}} , if moths need to navigate, they must be from a migrating species. {{5}} most of the time such moths are not migrating. Indeed most species do not migrate at all and thus have no need of navigation.', NULL, NULL, NULL, E'1.One solution, 2.This explanation, 3.however, 4.What''s more, 5.Yet', NULL, NULL),
  ('e31341a7-2523-59e7-bb7d-b10fb30e582f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e31341a7-2523-59e7-bb7d-b10fb30e582f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1ede74d8-c1fb-504c-a245-95d800fa9f2b'::uuid, NULL, NULL, E'Plants are able to continue growing throughout their lives.', NULL, NULL),
  ('e3155a9a-3b1a-5c22-8629-58b8f85f7997'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e3155a9a-3b1a-5c22-8629-58b8f85f7997'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the fairy tale character who slept for 100 years?', '5c786cd3-a134-5145-8e1d-2a563e32e598'::uuid, NULL, NULL, E'Sleeping Beauty', NULL, NULL),
  ('e317dd21-ffbe-5312-a85d-24e42c56c585'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e317dd21-ffbe-5312-a85d-24e42c56c585'::uuid, 1, NULL, TRUE, 0, NULL, E'Route Planning of Airlines', NULL, '19e39f30-90df-5931-8a6a-3becdb4b4a40'::uuid, NULL, E'Airlines can make a lot of money by flying to the right places. British Airways, for example, long-ago cemented themselves as the leader on the London Heathrow to New York JKF route, and flying between these two airports now earns them over $1 billion per year. That’s more than any airline makes on any other route in the world. Conversely, though, airlines can lose a lot of money by flying to the wrong places. American Airlines, for example, recently cancelled their Chicago to Beijing flight as it was loosing them tens of millions of dollars per year. Now, the fact that this route failed might be puzzling considering it flew between the world’s fiftieth and the world seventh largest city. Even more, they were flying the 787-8 Dreamliner, the smallest plane they could on this route. Nonetheless, it was truly a financial disaster. The airline said that, in terms of annual revenue, the route was $ 80 million away from their target. The truth is that deciding where to fly is a lot more complicated than pairing up the largest cities. It’s an art that people spend their whole lives mastering and the difference between an airline that’s good at route planning and one that’s bad. This can be the difference between a profitable airline and a defunct one.', NULL, NULL, NULL),
  ('e321dbdb-3d1f-582e-8d72-aec4ad6764a9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e321dbdb-3d1f-582e-8d72-aec4ad6764a9'::uuid, 1, NULL, TRUE, 0, NULL, E'Informative Speech', E'The purpose of the informative speech is to provide interesting, useful, and unique information to your audience. By dedicating yourself to the goals of providing information and appealing to your audience, you can take a positive step toward succeeding in your efforts as an informative speaker.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e32bfb5c-efbb-50a0-b86a-de4b1a974d2f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e32bfb5c-efbb-50a0-b86a-de4b1a974d2f'::uuid, 1, NULL, TRUE, 0, NULL, E'Films', E'For children, using films to study is as important as studying literature. To what extent do you agree?', NULL, NULL, NULL, NULL, 200, 300),
  ('e32d1477-b04f-5690-bbb7-5a5c37390e5e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e32d1477-b04f-5690-bbb7-5a5c37390e5e'::uuid, 1, NULL, TRUE, 0, NULL, E'Hypertension', E'High blood pressure, also known as hypertension, is one of the most common risk {{1}} for heart disease, which is the leading cause of death in the U.S. and worldwide. However, many people who have high blood pressure may not be aware of it, as it often causes no symptoms {{2}} . According to Dr. Haider Warraich, a Harvard cardiologist and author of the book State of the Heart, high blood pressure is a “silent killer” that can damage the arteries, heart, brain, kidneys and other organs without any warning signs. “While many might believe that they can ‘feel’ their blood pressure, fact is that for the vast {{3}} , high blood pressure causes no symptoms, and would be totally missed {{4}} one gets it checked,” he told Newsweek. The only way to know if you have high blood pressure is to measure it regularly, either at home or at a health care provider’s office.', NULL, NULL, NULL, E'1.factors, 2.at all, 3.majority, 4.unless', NULL, NULL),
  ('e33077f2-9dc0-5473-8b8b-52474c745df0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e33077f2-9dc0-5473-8b8b-52474c745df0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8d3eb3e6-2509-5345-bb05-9dfa150cc19e'::uuid, NULL, E'They were very curious about the people who lived upstairs.', NULL, NULL, NULL),
  ('e33a34f2-701a-50d2-a7ed-c3d069d9e8a0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e33a34f2-701a-50d2-a7ed-c3d069d9e8a0'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1553a9ef-0fa5-5811-b1db-1ea952ebb776'::uuid, NULL, NULL, E'Chemical reactions occur when substances combine or change form.', NULL, NULL),
  ('e345a852-1d94-5f76-b48d-73a3b24c6c0e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e345a852-1d94-5f76-b48d-73a3b24c6c0e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '75e0d2fb-ff28-5e10-b977-438fa94a7171'::uuid, NULL, E'Student services provide help with housing and transport.', NULL, NULL, NULL),
  ('e346e1b9-cdaa-5993-a187-e26642b267cc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e346e1b9-cdaa-5993-a187-e26642b267cc'::uuid, 1, NULL, TRUE, 0, NULL, E'Bees', E'Bees need two different kinds of food. One is honey made from nectar, which actually is a fluid that is collected in the heart of the flowers to {{1}} pollination by insects and other animals. The other comes from pollen, a fine powdery substance in yellow, consisting of microscopic grains {{2}} from the male part of a flower or from a male cone. It contains a male gamete that can fertilize the female ovule, which is {{3}} by wind, insects or other animals.', NULL, NULL, NULL, E'1.encourage, 2.discharged, 3.transported', NULL, NULL),
  ('e348617b-159e-5d0a-94ae-ac0188ce8d9b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e348617b-159e-5d0a-94ae-ac0188ce8d9b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '92337270-56b2-5151-aa14-7a4548052325'::uuid, NULL, E'Could you please pass the handouts to students in your row?', NULL, NULL, NULL),
  ('e34bc03d-e860-5adc-ba4a-bdd34b5b56c1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e34bc03d-e860-5adc-ba4a-bdd34b5b56c1'::uuid, 1, NULL, TRUE, 0, NULL, E'Rainbow', E'A rainbow is most often viewed as a circular arc in the sky. An observer on the ground observes a half-circle of color with red being the color {{1}} on the outside or top of the bow. Those who are fortunate enough to have seen a rainbow from an airplane in the sky may know that a rainbow can {{2}} be a complete circle. Observers on the ground only view the top half of the circle since the bottom half of the circular arc is prevented by the presence of the ground. Yet observers in an airborne plane can often look both upward and downward to view the complete circular bow. The circle results because there are a {{3}} of suspended droplets in the atmosphere that are capable of concentrating the dispersed light at angles of {{4}} of 40-42 degrees relative to the original path of light from the sun. These droplets actually form a circular arc, with each droplet within the arc {{5}} light and reflecting it back towards the observer.', NULL, NULL, NULL, E'1.perceived, 2.actually, 3.collection, 4.deviation, 5.dispersing', NULL, NULL),
  ('e34d3d44-61ad-566a-a941-8ff41c373b89'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e34d3d44-61ad-566a-a941-8ff41c373b89'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How often does an annual event happen?', 'b65ed4a1-f022-5c16-b6ac-0107aaaf6ea4'::uuid, NULL, NULL, E'Once a year / yearly', NULL, NULL),
  ('e34f48d9-2d41-55f0-9290-f5498297f41f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e34f48d9-2d41-55f0-9290-f5498297f41f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'cc80d486-1ee4-58ae-a8af-48064d7e0dda'::uuid, NULL, E'A team of teachers is trying to come up with an innovative curriculum.', NULL, NULL, NULL),
  ('e35a54b5-df8e-5c4b-8d53-263600f13244'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e35a54b5-df8e-5c4b-8d53-263600f13244'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '492d9085-f8e3-5ac3-b8c6-8ea474e7b773'::uuid, NULL, E'The country suffered a series of invasions by tribes from present-day Germany and Denmark.', NULL, NULL, NULL),
  ('e362be37-4a6a-52c2-8092-d522d736f218'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e362be37-4a6a-52c2-8092-d522d736f218'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'cf41fc3f-2560-5a1f-8d32-c054f43eb608'::uuid, NULL, NULL, E'The investment will be dedicated to improving transport infrastructure.', NULL, NULL),
  ('e363d249-517a-5897-a764-697666c561d1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e363d249-517a-5897-a764-697666c561d1'::uuid, 1, NULL, TRUE, 0, NULL, E'Entrepreneur', NULL, '29e80796-62f1-54b9-8340-3ddfa4dac623'::uuid, NULL, E'To be a successful entrepreneur, you should have good ideas, but the definition of a good idea varies depending on whom you ask. A great idea should have several features. Firstly, the great idea should be various and novel. Secondly, the great idea should be unique, which means no one has thought about it. Thirdly, it is essential for great ideas to be transformative and productive. All ideas are essentially a combination of other smaller ideas, but this doesn’t mean they can’t be unique. Merely copying doesn’t make anything idiosyncratic, it’s the individuality that one puts in which makes a concept stand out. Constant innovation leaves no room for stagnation and thus, adds on to the basic idea, effectively making it unique. Unique ideas are inspired by basic things, they are simply extensions of pre-existing notions. And, an idea or a concept is unique only when it transcends its predecessor and serves its purpose in a better and more precise way.', NULL, NULL, NULL),
  ('e3668281-0aff-5a04-bffb-e8fb8d641684'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e3668281-0aff-5a04-bffb-e8fb8d641684'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9cccd18a-0b03-5312-a7af-d729fcc15e65'::uuid, NULL, E'Higher fees make students think more critically about what universities can offer.', NULL, NULL, NULL),
