  ('e36da231-c6c3-57d4-876f-4fad8f67f27f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e36da231-c6c3-57d4-876f-4fad8f67f27f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call the middle of something?', 'e262ec2b-4948-5446-b44b-e59c40d6883d'::uuid, NULL, NULL, E'Center', NULL, NULL),
  ('e370bbbc-c753-5000-bdfb-3f9aa9759b58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e370bbbc-c753-5000-bdfb-3f9aa9759b58'::uuid, 1, NULL, TRUE, 0, NULL, E'Public Space', E'Some people believe that all cities and towns should have at least one large public open space. To what extent do you agree or disagree?', NULL, NULL, NULL, NULL, 200, 300),
  ('e3717353-ef57-50bf-8ab5-1c5480d422de'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e3717353-ef57-50bf-8ab5-1c5480d422de'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the ancient Greek city-state known for its powerful army and strict discipline?', '621c680b-f26f-5b4e-90a6-049880553b59'::uuid, NULL, NULL, E'Sparta', NULL, NULL),
  ('e3764bd4-0937-5dc6-b36f-5aea3f64f28a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e3764bd4-0937-5dc6-b36f-5aea3f64f28a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the natural light display in the Earth''s sky, typically seen in polar regions?', '72b0e79c-ae6f-5302-8a0a-6a7fd16c743b'::uuid, NULL, NULL, E'Aurora', NULL, NULL),
  ('e37895a1-bb3a-5303-8850-f8bad99f79b6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e37895a1-bb3a-5303-8850-f8bad99f79b6'::uuid, 1, NULL, TRUE, 0, NULL, E'DNA Barcoding', E'DNA barcoding was invented by Paul Hebert of the University of Guelph, in Ontario, Canada, in 2003. His idea was to {{1}} a unique identification tag for each species based on a short {{2}} of DNA. Separating species would then be a simple task of sequencing this tiny bit of DNA. Dr Hebert proposed part of a gene called cytochrome c oxidase I (COI) as suitable to the task. All animals have it. It seems to vary enough, but not too much, to act as a reliable marker. And it is easily {{3}} ,because it is one of a handful of genes found outside the cell nucleus, in structures called mitochondria. Barcoding has taken off rapidly since Dr Hebert invented it. When the idea was proposed, it was expected to be a {{4}} to taxonomists trying to name the world''s millions of species. It has, however, proved to have a far wider range of uses than the merely academic-- most promisingly in the {{5}} of public health. One health-related project is the Mosquito Barcoding Initiative being run by Yvonne-Marie Linton of the Natural History Museum in London. This aims to barcode 80% of the world''s mosquitoes within the next two years, to help control mosquito-borne diseases. Mosquitoes are {{6}} for half a billion malarial infections and 1m deaths every year. They also {{7}} devastating diseases such as yellow fever, West Nile fever and dengue. However, efforts to control them are consistently {{8}} by the difficulty and expense of identifying mosquitoes-- of which there are at least 3,500 species, many of them hard to tell apart.', NULL, NULL, NULL, E'1.generate, 2.stretch, 3.extracted, 4.boon, 5.realm, 6.responsible, 7.transmit, 8.undermined', NULL, NULL),
  ('e378ead0-188a-52d0-894c-4f786d3e2d3e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'e378ead0-188a-52d0-894c-4f786d3e2d3e'::uuid, 1, NULL, TRUE, 0, NULL, E'Mechanical Engineering(机械工程)', NULL, NULL, NULL, NULL, E'1, 4, 3, 2', NULL, NULL),
  ('e37c9817-23d4-5070-b8b5-690c706d3857'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e37c9817-23d4-5070-b8b5-690c706d3857'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7ef256c4-5ca1-56e9-a4e5-eec100f91bb6'::uuid, NULL, NULL, E'A well-done school paper is always easy to understand and organize.', NULL, NULL),
  ('e37e5e2f-1f25-56ca-be85-71db9aa22e4a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e37e5e2f-1f25-56ca-be85-71db9aa22e4a'::uuid, 1, NULL, TRUE, 0, NULL, E'Invasive Species', E'Invasive species can {{1}} biodiversity and drive resident species to the brink of extinction. But how do these interlopers fare so well in unfamiliar territory? One idea is that they''ve escaped their enemies, for example, the {{2}} that keep them in check on their home turf. But a study in the journal Biology Letters suggests that notion doesn''t always stand up. Because at least one kind of invasive shrimp is an even bigger pest when it has a parasite on board.\nThe scientists were studying a {{3}} shrimp commonly found in England. Fishermen brought the shrimp to Northern Ireland in the 1950s as a tasty treat for local trout. Well, the shrimp liked the new digs. So much that they''ve all but eliminated the native shrimp species. The strange thing is, they may have parasites to thank.\nIn some streams, 70 percent of the invaders are {{4}} with an intestinal worm that doesn''t go for the native shrimp. But this gut worm doesn''t slow them down. In fact, infected shrimp eat 30 percent more prey than those that are parasite-free.\nWhich perhaps is not surprising. If you had a worm that {{5}} a quarter of your body weight, you''d eat more too.', NULL, NULL, NULL, E'1.decrease, 2.parasites, 3.freshwater, 4.infected, 5.constituted', NULL, NULL),
  ('e380b62a-3ca4-5272-8a71-56e93c8c77db'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e380b62a-3ca4-5272-8a71-56e93c8c77db'::uuid, 1, NULL, TRUE, 0, NULL, E'Class Participation', E'Because the instructional methods, expected class participation and the nature of the courses vary, no fixed number of absences is {{1}} to all situations. Each instructor is {{2}} for making clear to the class at the beginning of the semester his or her {{3}} and procedures in {{4}} to class attendance and the reasons for them.', NULL, NULL, NULL, E'1.applicable, 2.responsible, 3.policies, 4.regard', NULL, NULL),
  ('e38420b1-3c41-50ff-b4c0-ae1fdf5a7f74'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e38420b1-3c41-50ff-b4c0-ae1fdf5a7f74'::uuid, 1, NULL, TRUE, 0, NULL, E'Object Recognition', E'In a study in the current issue of the journal PLOS One, a team of scientists in Germany showed experts and novices simple geometric objects and simple chess positions and asked the subjects to identify them. Reaction times were measured and brain activity was monitored using functional M.R.I. scans. On the identification of the geometric objects, the subjects performed the same, showing that the chess experts had no special visualization skills. When the subjects were shown the chess positions, the experts identified them faster.\nFocusing on an element of an earlier study on pattern and object recognition by chess experts, the researchers had expected to see parts of the left hemispheres of the experts'' brains — which are involved in object recognition — react more quickly than those of the novices when they performed the chess tasks. But the reaction times were the same.\nWhat set the experts apart was that parts of their right brain hemispheres — which are more involved in pattern recognition — also lit up with activity. The experts were processing the information in two places at once. The researchers also found that when the subjects were shown the chess diagrams, the novices looked directly at the pieces to recognize them, while the experts looked on the middle of the boards and took everything in with their peripheral vision.', NULL, NULL, E'The chess experts had no special visualization skills on the identification of the geometric objects, while the subjects were shown the chess positions, the experts identified them faster, and parts of the left hemispheres of the experts'' brains react the same as those of the novices when they performed the chess tasks, with their right brain hemispheres also lighting up with activity, suggesting the experts were processing the information in two places at once.', NULL, 5, 75),
  ('e386db75-2363-542d-8296-ea6a7168b2f3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e386db75-2363-542d-8296-ea6a7168b2f3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c516a846-a9e6-5e23-9222-e61ef3f4f078'::uuid, NULL, E'Please submit your term papers to the general office.', NULL, NULL, NULL),
  ('e38720f4-1275-5b45-80a1-271ba56a1328'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e38720f4-1275-5b45-80a1-271ba56a1328'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2fd71411-9710-53dd-8e07-b3fd09257c63'::uuid, NULL, E'Folk tales are passed orally from generation to generation.', NULL, NULL, NULL),
  ('e38f02ef-98f1-54d4-8b0d-6647e0bfbfef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e38f02ef-98f1-54d4-8b0d-6647e0bfbfef'::uuid, 1, NULL, TRUE, 0, NULL, E'Good Things', NULL, '08e4dbc2-2d4a-500b-991f-ceb073fe9dd2'::uuid, NULL, E'Glaucon breaks all good things into three classes. The first kinds, we desire for their own sake, like the experience of harmless pleasure. The second, we want only for the value they bring, though they may be onerous, like exercise or medicine. The third class comprises things we desire for their own sake and the value they offer, like knowledge and health. Glaucon argues that justice belongs to the second class of good: it’s a burden that nevertheless brings rewards. The only reason anyone conducts themselves virtuously, he reasons, is due to external influences. So it’s appearing—not actually being—virtuous that matters. Socrates, as written by Plato, disagrees, countering that justice belongs to the third class of good, offering both extrinsic and intrinsic benefits. Socrates argues that the human soul has three parts: reason, spirit, and appetite. Reason guides an individual to truth and knowledge, and is influenced by either spirit or appetite. Spirit is righteous, ambitious, and the source of bold action, while appetite consists of baser, bodily desires. To Socrates, the philosopher is led by reason, and their spirit keeps their appetite in check, making them the most just and the happiest. Even without consequences for self-serving wrongdoings, they wouldn’t commit them. Meanwhile, the tyrant succumbs to appetite and acts unjustly.', NULL, NULL, NULL),
  ('e39509c1-61c9-51a5-9b0f-0220a62dd2e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'e39509c1-61c9-51a5-9b0f-0220a62dd2e9'::uuid, 1, NULL, TRUE, 0, NULL, E'Bank Account', NULL, NULL, NULL, NULL, E'2, 5, 3, 1, 4', NULL, NULL),
  ('e39f9d9b-bdcf-5763-a4d9-8e5c3b3fa45a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e39f9d9b-bdcf-5763-a4d9-8e5c3b3fa45a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd2d4a075-6660-5854-8f4c-ae59b43c6e0a'::uuid, NULL, NULL, E'Health experts recommend consuming fish for its nutritional benefits.', NULL, NULL),
  ('e3a2cd9c-c1f4-56e5-b012-0f2375ca64e2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e3a2cd9c-c1f4-56e5-b012-0f2375ca64e2'::uuid, 1, NULL, TRUE, 0, NULL, E'Moon''s Oxygen', E'Oxygen can be found in many of the minerals in the ground around us, and the Moon is mostly made of the same rocks you''ll find on Earth (although with a slightly greater amount of material that came from meteors). Minerals such as silica, aluminium, and iron and magnesium oxides dominate the Moon’s landscape. All of these minerals contain oxygen, but not in a form our lungs can access.\nThe Moon''s regolith is made up of approximately 45% oxygen. But that oxygen is tightly bound into the minerals mentioned above. In order to break apart those strong bonds, we need to put in energy. You might be familiar with this if you know about electrolysis. On Earth this process is commonly used in manufacturing, such as to produce aluminium. An electrical current is passed through a liquid form of aluminium oxide (commonly called alumina) via electrodes, to separate the aluminium from the oxygen. In this case, the oxygen is produced as a byproduct. On the Moon, the oxygen would be the main product and the aluminium (or other metal) extracted would be a potentially useful byproduct. It’s a pretty straightforward process, but there is a catch: it''s very energy hungry. To be sustainable, it would need to be supported by solar energy or other energy sources available on the Moon.\nExtracting oxygen from regolith would also require substantial industrial equipment. We''d need to first convert solid metal oxide into liquid form, either by applying heat, or heat combined with solvents or electrolytes. We have the technology to do this on Earth, but moving this apparatus to the Moon — and generating enough energy to run it — will be a mighty challenge.', NULL, NULL, NULL, NULL, 5, 75),
  ('e3ac3bc7-5cef-5df8-a4af-bb809229bf43'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'e3ac3bc7-5cef-5df8-a4af-bb809229bf43'::uuid, 1, NULL, TRUE, 0, NULL, E'Sun''s Radiation', NULL, NULL, NULL, NULL, E'2, 4, 5, 1, 3', NULL, NULL),
  ('e3accb2b-72ae-546d-abaf-4f3a5ec894df'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e3accb2b-72ae-546d-abaf-4f3a5ec894df'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '642a4e96-4f9a-5f38-ab8a-e457deb0cd8d'::uuid, NULL, E'Answering such a complex question with a simple yes or no is absolutely impossible.', NULL, NULL, NULL),
  ('e3afe396-0a1f-5207-be77-eba94a5cf9cc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e3afe396-0a1f-5207-be77-eba94a5cf9cc'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '953e5ec0-472d-5869-ae55-baedd014b8f4'::uuid, NULL, E'The team is developing original projects with new ideas and inspirations.', NULL, NULL, NULL),
  ('e3be4586-f37f-5d0a-a567-7719e7359f81'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e3be4586-f37f-5d0a-a567-7719e7359f81'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the headache or other sick feelings caused by drinking too much alcohol?', 'b19a2d20-1b80-534c-841b-e588962d7e3d'::uuid, NULL, NULL, E'Hangover', NULL, NULL),
  ('e3bfd5f6-0088-5e37-abd6-da54f3a20546'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e3bfd5f6-0088-5e37-abd6-da54f3a20546'::uuid, 1, NULL, TRUE, 0, NULL, E'High-involvement Decisions', E'High-involvement decisions are those that are important to the buyer. These decisions are closely {{1}} to the consumer’s ego and self-image. They also involve some risk to the consumer. This may include financial risk (highly priced items), social risk (products that are important to the peer group), or {{2}} risk (the wrong decision may cause the consumer some concern and anxiety). In making these decisions, consumers generally feel it is worth the time and energy needed to do research and consider solution {{3}} carefully. The full, six-stage, complex process of consumer decision making is more likely to happen with high-involvement product purchases. In these cases, a buyer gathers {{4}} information from multiple sources, evaluates many alternatives, and invests substantial effort in making the best decision.', NULL, NULL, NULL, E'1.tied, 2.psychological, 3.alternatives, 4.extensive', NULL, NULL),
  ('e3c0a682-8044-5320-ab1a-86ec71bb5ae0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e3c0a682-8044-5320-ab1a-86ec71bb5ae0'::uuid, 1, NULL, TRUE, 0, NULL, E'Photosynthesis', E'Through three. Listen to part of a lecture in a botany class. The professor is discussing photosynthesis. The complex process inside a leaf takes energy from the sun and uses it to convert water and carbon dioxide into sugars. During this process, photosynthesis plants convert light energy into chemical energy. All leaves carry out photosynthesis. And basically the same way, first the pores on the leaves, outer skin open up and taking molecules of carbon dioxide. Water absorbed by the roots is transported upward through the plant, and it enters the leaf through its stem, carbon dioxide, and water. These are the raw materials for photosynthesis. Once carbon dioxide and water are present, photosynthesis can begin. The chemical reactions of photosynthesis take place in two stages, the light dependent reactions and the light independent reactions. When sunlight shines on a leaf during the light dependent stage, its energy is absorbed by molecules of chlorophyll, which you all know is the pigment giving a leaf its green color. The light energy absorbed by the chlorophyll is used to split the hydrogen and oxygen in the water. Then during the light independent reactions, hydrogen from the water combines with carbon dioxide and forms carbohydrates, including the sugar glucose, but also other molecules that are rich in food energy for the plant. In the process, access oxygen is released to the outside air through the leaves pores. Finally, the plant transports the products of photosynthesis. Microscopic veins in the leaf carry the food out through the stem and into the cells of the plant. This process continues all throughout the growing season. That is as long as the leaves remain green.\n\nWhat must be present for photosynthesis to begin?', 'dc857e04-157a-52a6-8c9c-19b949104cdf'::uuid, NULL, NULL, E'Carbon dioxide\nWater', NULL, NULL),
  ('e3c1973c-3474-50e4-9e00-d7b7801b9ceb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e3c1973c-3474-50e4-9e00-d7b7801b9ceb'::uuid, 1, NULL, TRUE, 0, NULL, E'Edmund Wilson', NULL, '51e2c066-815c-5c8c-814b-4a1bfc53e35c'::uuid, NULL, E'Wilson came then from a different world and he became the focal point of a broad mainstream American culture that thought that modern literature and wanted modern literature to be able to be read and appreciated by ordinary people. They were not modernists in an abstract sense and certainly some of them like TS Eliot and Faulkner were too difficult for some of their writings to be read by ordinary people, but this was a world before the division between the brows or between elite or whatever had established itself as part of our consciousness. Wilson was a major player in the successful effort of his generation to establish at the heart of American life and innovative literature that would equal the great cultures of Europe. And he knew that the great cultures of Europe were there he was not a product of a narrow American Studies kind of training at all. He joined a high artistic standard with an openness to all experience and a belief that literature was as much a part of life for everyone as conversation. He thought that Proust and Joyce and Yeats and Eliot could and should be read by ordinary Americans and helped that to happen. Wilson was a very various man over a period of almost 50 years. He was a dedicated a literary journalist, an investigative reporter, a brilliant memoirist and a dedicated journal keeper.', NULL, NULL, NULL),
  ('e3c1be90-ae1b-524b-b985-d5970ef7dc1d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e3c1be90-ae1b-524b-b985-d5970ef7dc1d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call the word type like ''UK'', or ''USA''?', 'e920c77e-38cf-5e62-9c8e-30ba2fefa242'::uuid, NULL, NULL, E'Acronym', NULL, NULL),
