  ('e3ce66c0-b840-5436-b187-8eea294adff5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e3ce66c0-b840-5436-b187-8eea294adff5'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the psychology fear after an accident called?', '07121b50-5bb0-5978-94d7-e66126faef35'::uuid, NULL, NULL, E'PTSD / trauma', NULL, NULL),
  ('e3d477ca-b17d-5621-a030-1f2355f384ed'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e3d477ca-b17d-5621-a030-1f2355f384ed'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '260d8f99-2b40-5b3f-9fe1-1d4060b1acbd'::uuid, NULL, E'People see ads on the internet, on TV and in magazines.', NULL, NULL, NULL),
  ('e3d5020c-46a0-54df-869d-bbfb3c044ce6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e3d5020c-46a0-54df-869d-bbfb3c044ce6'::uuid, 1, NULL, TRUE, 0, NULL, E'Physical Constraints', E'Cambridge scientists have shown that placing physical constraints on an artificially-intelligent system -- in much the same way that the human brain has to develop and operate within physical and biological constraints -- allows it to develop features of the brains of complex organisms in order to solve tasks.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e3e545d7-7682-51e1-bf5c-b2dd0e2072dc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e3e545d7-7682-51e1-bf5c-b2dd0e2072dc'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '222aac69-72a1-5b1c-9620-886fad0a8cc9'::uuid, NULL, NULL, E'Formal course study is a valuable means of professional development.', NULL, NULL),
  ('e3e96e95-711f-5c5a-9f35-319753e0c310'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e3e96e95-711f-5c5a-9f35-319753e0c310'::uuid, 1, NULL, TRUE, 0, NULL, E'Mother''s Day', E'The origins of Mother''s Day as a modern celebration can be traced back to the early 20th century in the United States, {{1}} the efforts of Anna Jarvis. Following the death of her mother, Ann Reeves Jarvis, in 1905, Anna sought to honor her mother''s legacy and the sacrifices mothers {{2}} for their children. Ann Reeves Jarvis had previously established Mother''s Day Work Clubs to address public health issues and reconcile Union and Confederate neighbors during the Civil War. Inspired by her mother''s work, Anna Jarvis {{3}} for the establishment of a national Mother''s Day to honor all mothers. Her efforts bore fruit when President Woodrow Wilson officially {{4}} the second Sunday in May as Mother''s Day in 1914. Initially a day of personal celebration and religious observance, Mother''s Day quickly became commercialized, a development that Anna Jarvis later {{5}} opposed, spending much of her later life fighting the commercialization of the holiday she helped create.', NULL, NULL, NULL, E'1.thanks to, 2.made, 3.campaigned, 4.declared, 5.vehemently', NULL, NULL),
  ('e3e98d45-cd68-5ece-81a0-bc8b89c789fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e3e98d45-cd68-5ece-81a0-bc8b89c789fd'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'aebd9bd5-a24c-5bd1-bde3-73f87f0c8247'::uuid, NULL, E'This leaflet is produced for the information of our customers.', NULL, NULL, NULL),
