  ('e47ffde4-7b8a-570f-b41d-f78e5a785c94'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e47ffde4-7b8a-570f-b41d-f78e5a785c94'::uuid, 1, NULL, TRUE, 0, NULL, E'Yield of Plants', E'The maximum yield of plants, determined by their genetic potential, is seldom achieved because factors such as insufficient water or nutrients, adverse climate conditions, plant diseases, and insect damage will limit growth at some stage. Plants subjected to these biotic and abiotic constraints are said to be stressed.', NULL, NULL, NULL, NULL, NULL, NULL),
