  ('e4aa7056-b7b1-52f9-b533-f87e39ce4f4f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e4aa7056-b7b1-52f9-b533-f87e39ce4f4f'::uuid, 1, NULL, TRUE, 0, NULL, E'Wrong Delivery', E'You received a letter that was mistakenly delivered to your address, and it belongs to your neighbor. How would you approach your neighbor and politely return the letter to them?', '3c3e26ba-3b77-5318-8ccf-64d06a654e61'::uuid, NULL, E'Hey neighbour, I want to talk to you about something.\nWe seem to have a little issue with a misdelivered letter.\nIt''s like a letter was wrongly sent to my house and it actually belongs to you, so I come to give it back to you.\nAnd I''d like to know what you think.', NULL, NULL, NULL),
  ('e4adff29-cc1d-5154-a4e1-a6167c606fe2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e4adff29-cc1d-5154-a4e1-a6167c606fe2'::uuid, 1, NULL, TRUE, 0, NULL, E'Food Prices', E'For two decades, leading up to the millennium, global demand for food {{1}} steadily, along with growth in the world''s population, record harvests, {{2}} in incomes, and the diversification of diets. As a result, food prices continued to {{3}} through 2000. But beginning in 2004, prices for most grains began to rise. Rising production could not keep pace with the even {{4}} growth in demand.', NULL, NULL, NULL, E'1.increased, 2.improvements, 3.decline, 4.stronger', NULL, NULL),
  ('e4b41b0e-d671-507a-8bc7-63d6ff646c05'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e4b41b0e-d671-507a-8bc7-63d6ff646c05'::uuid, 1, NULL, TRUE, 0, NULL, E'Stay in School', E'''Students should be required to stay in school until the age of eighteen.'' To what extent do you agree or disagree with this statement? Support your point of view with reasons and /or examples from your own experience.', NULL, NULL, NULL, NULL, 200, 300),
