  ('e566f438-0998-5b96-b198-c3071b06ebd9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e566f438-0998-5b96-b198-c3071b06ebd9'::uuid, 1, NULL, TRUE, 0, NULL, E'Zoo and Animal', E'Animal rights have been a subject of debate since the 1970s. Are zoos helping or hurting animals?', NULL, NULL, NULL, NULL, 200, 300),
