  ('e572f861-f65c-5dd3-99e5-3a600bb266b3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e572f861-f65c-5dd3-99e5-3a600bb266b3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8f06c1e7-f020-57f2-b4bb-ef2c4acdb0a4'::uuid, NULL, E'The job encompasses a wide range of responsibilities, so it is very challenging.', NULL, NULL, NULL),
  ('e573d305-72ab-5e9b-83c1-19ded62bfa38'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e573d305-72ab-5e9b-83c1-19ded62bfa38'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7f9401d5-64f2-5c96-b63f-52da4f81f216'::uuid, NULL, E'Unfortunately, their immune systems were not strong enough to fight off common earthly bacteria.', NULL, NULL, NULL),
  ('e5780c24-6d4d-5160-81bc-0fe587897e92'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e5780c24-6d4d-5160-81bc-0fe587897e92'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd84bedc8-d310-5087-a64e-707dac3e9335'::uuid, NULL, NULL, E'You need student identification to borrow books from the library.', NULL, NULL),
  ('e578da69-28c5-526b-9415-2e64c6dea119'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e578da69-28c5-526b-9415-2e64c6dea119'::uuid, 1, NULL, TRUE, 0, NULL, E'Pandemic', E'The pandemic created an {{1}} situation, prompting unprecedented {{2}} to bolster the health {{3}} , reform the pharmaceutical {{4}} , and distribute relief {{5}} the country.', NULL, NULL, NULL, E'1.urgent, 2.contribution, 3.system, 4.sector, 5.throughout', NULL, NULL),
  ('e57be88d-21ed-524d-a80c-ea5a241c0077'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e57be88d-21ed-524d-a80c-ea5a241c0077'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Who would you consult to treat a fear of crowded places, a philosopher or a psychologist?', 'ed07395f-0901-530a-bb5b-0827513a6564'::uuid, NULL, NULL, E'Psychologist', NULL, NULL),
  ('e57e39e9-a189-58fd-8dd7-e568ce8cb4da'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e57e39e9-a189-58fd-8dd7-e568ce8cb4da'::uuid, 1, NULL, TRUE, 0, NULL, E'Baby''s Senses', E'The development of a baby''s senses begins in the womb, with hearing being one of the earliest to emerge. Parents have been known to play music to their unborn babies, hoping to stimulate their cognitive development. Recent research shows that babies can even start hearing adult speech as early as 10 weeks before birth, providing them with an early exposure to the sounds and rhythms of their family''s language.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e580aa36-9f01-5f13-b4c5-0e2028952741'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e580aa36-9f01-5f13-b4c5-0e2028952741'::uuid, 1, NULL, TRUE, 0, NULL, E'Spinosaurus', E'The largest predatory dinosaur to ever walk on Earth sported a massive sail that rose from its back. Its bony, muscular tail wouldn’t have had the same {{1}} of a whale or fish, and the heavy sail might have been more of an obstacle than a useful tool. If Spinosaurus was plunked down in deep water, the results wouldn’t have been very pleasant. This anatomical clue suggested Spinosaurus was “semiaquatic” and {{2}} into the shallow waters along river banks for its prey. Similar to some lizards today that have spine-supported sails, Spinosaurus likely used its sail during competition and courtship. Intriguingly, the dinosaur likely lived along marine and freshwater {{3}} like other semiaquatic reptiles, but it’s not something that any other extinct or {{4}} large aquatic vertebrates like ichthyosaurs or sea turtles did. So Spinosaurus would have prowled along coastal and inland waterways, ambushing prey as it waded into shallow waters.', NULL, NULL, NULL, E'1.flexibility, 2.waded, 3.habitats, 4.extant', NULL, NULL),
  ('e58a0247-85ef-5392-9c26-8426310244f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e58a0247-85ef-5392-9c26-8426310244f8'::uuid, 1, NULL, TRUE, 0, NULL, E'Natural Movement', E'Basically, when we are standing still, our bodies are constantly making adjustments in order to keep us stable. For example, if someone bumps into us when we are standing in line, our legs make a wide range of movements that we are not even necessarily aware of in order to keep us upright.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e5910912-6c5e-5c5c-8e12-2fb40ffe4af0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e5910912-6c5e-5c5c-8e12-2fb40ffe4af0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '17a8b4a0-8cbc-590a-9e9b-038df6048011'::uuid, NULL, E'Human activities are the principal cause of global warming.', NULL, NULL, NULL),
  ('e594db67-0bc0-5bbf-90ab-923eb7ede612'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e594db67-0bc0-5bbf-90ab-923eb7ede612'::uuid, 1, NULL, TRUE, 0, NULL, E'Cognitive Enhancers', E'Neurotech Industries recently unveiled a line of cognitive enhancers {{1}} at improving memory and focus. These supplements, {{2}} through extensive neuro-pharmacological research, are said to bolster mental performance without the side {{3}} typically associated with nootropics. The cognitive enhancers have shown positive results in clinical {{4}} involving thousands of volunteers.', NULL, NULL, NULL, E'1.aimed, 2.developed, 3.effects, 4.trials', NULL, NULL),
  ('e597e98e-94f8-5a95-9b5e-cedeef626555'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e597e98e-94f8-5a95-9b5e-cedeef626555'::uuid, 1, NULL, TRUE, 0, NULL, E'Vanilla', E'Dairy products such as ice cream and yogurt have relied on natural vanilla for many years, McBride points out. In the U.S., Food & Drug Administration rules state that vanilla ice cream must get its flavor from natural vanilla. If the flavor comes partially or fully from another source, the company must stamp “vanilla flavored” or “artificial vanilla” on the front of the package, a likely turnoff to consumers.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e599d9a2-b1fb-506a-a3af-cc7cc86d2a04'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e599d9a2-b1fb-506a-a3af-cc7cc86d2a04'::uuid, 1, NULL, TRUE, 0, NULL, E'Deaf Children', E'Deaf children learning a sign language could certainly pursue the development of listening and spoken language skills if desired, and doing so would carry much less risk knowing the child would have mastery in at least one language. If a child does not succeed in mastering either a spoken language or a sign language, we must then ask how much benefit the child derived from interventions in each language relative to the amount of time and resources dedicated to those interventions.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e59afdef-2ad6-5a7b-bc85-64e45b1dd972'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'e59afdef-2ad6-5a7b-bc85-64e45b1dd972'::uuid, 1, NULL, TRUE, 0, NULL, E'Environmental Conservation', NULL, NULL, NULL, NULL, E'1, 4, 2, 3', NULL, NULL),
  ('e59e5bbc-57b4-51a6-9d22-56cda7bf5064'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e59e5bbc-57b4-51a6-9d22-56cda7bf5064'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f2af49e4-f3c9-55fb-bc67-3ab1a0051b73'::uuid, NULL, NULL, E'Globalization in the modern world leads to economic growth.', NULL, NULL),
  ('e5a05ce8-d469-5a3a-99e6-91a8ae1cd4aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e5a05ce8-d469-5a3a-99e6-91a8ae1cd4aa'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5112467b-052b-576d-8bab-c1ca6bbaa813'::uuid, NULL, NULL, E'You can keep your bags in the back room.', NULL, NULL),
  ('e5a16cb8-321c-5b9a-99bb-27b1067380e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e5a16cb8-321c-5b9a-99bb-27b1067380e1'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which section of a newspaper gives the editor an opinion?', '5b9c9eb3-9d96-5b51-8288-3bc42d35472b'::uuid, NULL, NULL, E'Editorial', NULL, NULL),
  ('e5a25713-711b-5980-b874-f5b264f02835'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e5a25713-711b-5980-b874-f5b264f02835'::uuid, 1, NULL, TRUE, 0, NULL, E'Mars and Earth', E'Today the Martian surface is hostile to life as we know it, but as this scientific story goes, Mars may have once {{1}} a rich abundance of microbes. Residing in the planet''s briny underworld and {{2}} from the lethal radiation that bathes the surface, these organisms could have grown in nooks and fissures, {{3}} until their collective heft rivaled Earth''s cache of life.', NULL, NULL, NULL, E'1.hosted, 2.shielded, 3.multiplying', NULL, NULL),
  ('e5ae5989-9f03-54b5-ad06-3d6a67cec019'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e5ae5989-9f03-54b5-ad06-3d6a67cec019'::uuid, 1, NULL, TRUE, 0, NULL, E'Aging Society', E'The wealthy world is ageing, fast. In 1950 around one in every 12 people in high-income countries was over 65. By 2050, it’s expected to be more like one in four and it’s storing up a big problem. It is a feat that we can live longer and that we can enjoy being alive for longer. But it’s expensive. When people retire they start to cost society more money and the costs will soon be unsustainable.\n\nWhich of the following statements is best related with the opinion expressed by the woman?', '99e5292d-e10b-5bb6-ae4c-b56218e0c2fa'::uuid, NULL, NULL, E'More money will be needed to support the aging population.', NULL, NULL),
  ('e5ae59d2-e028-5d20-b6e0-f1dd70e0b8b4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e5ae59d2-e028-5d20-b6e0-f1dd70e0b8b4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '914ece7f-e786-5e3c-a9a8-fac0af285bd8'::uuid, NULL, NULL, E'It is important to balance your study and personal life effectively.', NULL, NULL),
  ('e5aec2cd-92f5-53d7-87e1-5b0b35f2f518'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e5aec2cd-92f5-53d7-87e1-5b0b35f2f518'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '26a8d1d0-9123-58b3-bf45-750c9128086d'::uuid, NULL, E'All laboratory equipment will be provided in class.', NULL, NULL, NULL),
  ('e5b09cd2-5525-5177-bd59-7dd91d61829c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'e5b09cd2-5525-5177-bd59-7dd91d61829c'::uuid, 1, NULL, TRUE, 0, NULL, E'Ecological Footprint', NULL, NULL, NULL, NULL, E'4, 3, 2, 5, 1', NULL, NULL),
  ('e5b1bf37-2119-5af1-b132-051034b8970b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e5b1bf37-2119-5af1-b132-051034b8970b'::uuid, 1, NULL, TRUE, 0, NULL, E'Alaska’s Fading Coastline', E'The top of our world is changing - warming twice as fast as the rest of the planet. And it is destroying communities. The island of Shishmaref (a town in Alaskan) is on the frontline of climate change. As temperatures rise, less sea ice forms, exposing the coast.\nAs the climate changes, the animals and fish that people here used to live on are getting harder to find. Parts of the main road have been washed away, and now the air strip that is the community’s lifeline to the outside world is threatened. The plan is to move the entire town onto the mainland. It will cost an estimated a hundred and eighty million dollars, but, says Dennis, they''ve got no choice. The climate is changing so fast. And the storms are getting more violent, and the ice isn''t forming, and the water''s warming. Within the next five, ten years, this will all be covered easily. Just that one or two degrees makes a big difference.\nIt isn''t easy to let go of the place where you''ve spent your entire life. But if greenhouse gas emissions aren''t cut rapidly, it is something many millions more people are likely to have to face.', NULL, NULL, NULL, NULL, 5, 75),
  ('e5b2b9eb-7f2a-5066-a116-768b8552044e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e5b2b9eb-7f2a-5066-a116-768b8552044e'::uuid, 1, NULL, TRUE, 0, NULL, E'Lucy', E'Lucy was a single hominid skeleton found in Ethiopia. First, she was a bunch of broken fragments lying in Ethiopia. She was found by Donald Johanson and Tom Gray, who headed out to the area looking for rocks, and then drove back. {{1}} that return journey, Johanson spotted a forearm bone, identified it -- and then kept looking, where the two found a huge set of bones that would eventually {{2}} 40 per cent of the entire skeleton.\nThe discovery was so important because it entirely {{3}} our understanding of the process of evolution.\nShe showed that people had been wrong to think that we became intelligent before we stood up-- Lucy and her contemporaries were better suited for walking {{4}} than we were, but appeared to have been much less {{5}} advanced. That was important because it changed our understanding of the story of evolution, implying that walking was one of the most important things in moving us towards our current state, and that brainpower might not have been the most important thing.', NULL, NULL, NULL, E'1.During, 2.represent, 3.upset, 4.upright, 5.intellectually', NULL, NULL),
  ('e5b6bc59-3bd7-54d9-a28c-db7fdd211df1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'e5b6bc59-3bd7-54d9-a28c-db7fdd211df1'::uuid, 1, NULL, TRUE, 0, NULL, E'Global Species', E'There are innumerable different species on the planet. Nobody really knows how many species there are,although many scientists have tried to estimate it. However, the complexity of trying to do this makes it impossible to establish a definitive number with any confidence. This is probably due to the fact that new species are continually appearing, while at the same time existing species evolve and some become extinct. In the past, the number of new species appearing exceeded the number of those dying out. Nowadays, however,due to human activity, this trend has reversed and as a result we are in danger of seriously disturbing our ecosystem.\n\nWhy is it difficult to establish the number of species globally?', NULL, NULL, NULL, E'The number of species is constantly changing.', NULL, NULL),
  ('e5b720a7-57ef-5a84-aadf-6c189c5efd3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e5b720a7-57ef-5a84-aadf-6c189c5efd3c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4a033b70-c552-5da3-8f9c-f082dadcf541'::uuid, NULL, NULL, E'You may not arrange your time when reading the text.', NULL, NULL),
  ('e5b8043e-2c39-5301-974e-c83508f2227e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e5b8043e-2c39-5301-974e-c83508f2227e'::uuid, 1, NULL, TRUE, 0, NULL, E'Recurring Dream', E'Having the same dream again and again is a well-known phenomenon — nearly two-thirds of the population report having recurring dreams. Being chased, finding yourself naked in a public place or in the middle of a natural disaster, losing your teeth or forgetting to go to class for an entire semester are typical recurring scenarios in these dreams.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e5ba757c-725e-5f05-9095-b7c3b9fc4892'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e5ba757c-725e-5f05-9095-b7c3b9fc4892'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which one is using manpower: plane, car, or cycling?', '3e3565c3-489f-5e0b-8403-c1cae37b4d72'::uuid, NULL, NULL, E'Cycling', NULL, NULL),
  ('e5bce3f7-c6d5-5fbc-9c62-bf9f73f3684b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e5bce3f7-c6d5-5fbc-9c62-bf9f73f3684b'::uuid, 1, NULL, TRUE, 0, NULL, E'Solar System', E'The formation of the solar system is a complex and fascinating process that began over 4.6 billion years ago. It involved the collapse of a giant molecular cloud, the formation of a protostar, and the accretion of dust and gas into planets, moons, and asteroids. Understanding this process can provide insights into the origins of life and the formation of other planetary systems.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e5bee941-ff7a-5615-8860-114b2174b2eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e5bee941-ff7a-5615-8860-114b2174b2eb'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd68fe810-ff13-5d4c-bc61-8ca3d6c703dd'::uuid, NULL, E'The art course has been cancelled due to the new policy.', NULL, NULL, NULL),
  ('e5c2e8ae-3b2f-5ea7-9530-c19d72b67d59'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e5c2e8ae-3b2f-5ea7-9530-c19d72b67d59'::uuid, 1, NULL, TRUE, 0, NULL, E'Heart Disease', E'You may go for your routine cervical smears and mammograms but do you think about your heart health too? Coronary heart disease kills twice as many women in the UK as breast cancer, and it’s the single biggest killer of women worldwide. Yet it’s often considered to be a man’s problem.\nAccording to a British Heart Foundation (BHF) report in October 2019, an average of 65 women die from coronary heart disease each day in the UK, most commonly due to a heart attack. Women don’t always realize they have a higher risk of heart disease, don’t always recognize the signs of a heart attack and often delay getting help. This is costing women’s lives.\nYou can’t change some of your risk factors, such as your family history or ethnic background. But it’s good to be aware of them. If you have African or African Caribbean heritage, for example, you may be more prone to having high blood pressure, which can lead to a heart attack or stroke. And there’s some evidence that the risk of having heart disease is up to 50 percent higher in South Asians (who are more likely to store excess fat around their waistline) compared to white Europeans.\n“If you have heart disease in your family, consult your GP, who can advise on ways to reduce your risk of developing the condition through a healthy, balanced lifestyle,” says Dr Brian Clapp, consultant cardiologist for The Cardiac Clinic at London Bridge Hospital (part of HCA UK). “It is better to be aware of any inherited conditions as early as possible to better prevent problems occurring later in life.”', NULL, NULL, NULL, NULL, 5, 75),
  ('e5c3eb44-0be7-57a4-865d-7844e6240292'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e5c3eb44-0be7-57a4-865d-7844e6240292'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How many years are there in a half of century?', '3eaf92cd-524b-5fb7-ba49-435769dc19dd'::uuid, NULL, NULL, E'Fifty', NULL, NULL),
  ('e5c8beef-7ca7-59e9-bafd-1dea2e615caf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e5c8beef-7ca7-59e9-bafd-1dea2e615caf'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f041cb2a-48b3-5b68-b44a-329251b07fe8'::uuid, NULL, NULL, E'Watching people helps us figure out why they do things.', NULL, NULL),
  ('e5cdde5d-9502-52e1-8cf6-d136b98e72b3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e5cdde5d-9502-52e1-8cf6-d136b98e72b3'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the fourth basic mathematical operation, addition, subtraction, multiplication and?', '146f9b12-7a15-5db8-bfeb-2f54d532a2a5'::uuid, NULL, NULL, E'Division', NULL, NULL),
  ('e5d652f5-00df-5a4d-90d0-410a5e59fa91'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e5d652f5-00df-5a4d-90d0-410a5e59fa91'::uuid, 1, NULL, TRUE, 0, NULL, E'Evolutionary Cousins', E'Compared to chimpanzees, our closest evolutionary cousins, humans are particularly prone to developing advanced carcinomas -- the type of tumors that include prostate, breast, lung and colorectal cancers -- even in the absence of known risk factors, such as genetic predisposition or tobacco use. A recent study helps explain why.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e5d86ba0-7b2d-5764-a7bf-9fc8472d8118'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e5d86ba0-7b2d-5764-a7bf-9fc8472d8118'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f6178219-4ac3-53ec-bcab-c4ed8e120cfa'::uuid, NULL, E'The librarian has been fired because of a serious mistake.', NULL, NULL, NULL),
  ('e5d9550b-2ea9-5e62-843d-7179fab9ea62'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e5d9550b-2ea9-5e62-843d-7179fab9ea62'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3bd172e8-c39f-5032-aad7-f08dbcbc64ce'::uuid, NULL, NULL, E'Relative humidity is the amount of moisture that the air can hold.', NULL, NULL),
  ('e5dbc9b2-1b9c-5709-bb8e-9f5fa53fe2e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e5dbc9b2-1b9c-5709-bb8e-9f5fa53fe2e9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '71c0f863-545e-5e9c-8ad3-206538b1bd56'::uuid, NULL, E'Children tend to have a very short attention span at school.', NULL, NULL, NULL),
  ('e5dfac65-40e2-51dd-a729-ee42f8162695'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e5dfac65-40e2-51dd-a729-ee42f8162695'::uuid, 1, NULL, TRUE, 0, NULL, E'Health Care Business', E'According to a study by the McKinsey Global Institute, $13.4 trillion could be added to the global economy by 2040 if the unmet needs of patients who suffer from musculoskeletal, mental-health and neurological disorders are {{1}} . Frederik Ducrozet, head of a macroeconomic research, says from an investor''s standpoint, the health theme runs the range of opportunities from health preservation and disease {{2}} to care service delivery and treatment. “Indeed, an entire industry has materialized over the last decade around prevention, with wrist trackers and other smart personal health monitoring devices now omnipresent and insurance companies offering subscribers financial incentives to {{3}} healthy lifestyles,” Ducrozet says. As a result, the field of preventative health care has yielded a {{4}} of key investment opportunities. When investing in prevention however, it is important to consider the health theme holistically, going beyond the health care sector.', NULL, NULL, NULL, E'1.addressed, 2.prevention, 3.adopt, 4.number', NULL, NULL),
  ('e5ea3967-c77c-555c-a586-f8d48f44df6c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e5ea3967-c77c-555c-a586-f8d48f44df6c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '909e2e48-1aa5-598f-80f3-fb7e46f770a4'::uuid, NULL, NULL, E'Evidence suggests that the human brain changes shape in response to the way it is used.', NULL, NULL),
  ('e5ec11aa-8beb-533f-9267-9b3faa9eba00'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e5ec11aa-8beb-533f-9267-9b3faa9eba00'::uuid, 1, NULL, TRUE, 0, NULL, E'Bird Nests', E'Nell says that, in order to seek protection from their furry foes, birds actually prefer to build their nests in plots of swamp with a resident alligator. In fact, in one study a graduate student planted fake alligators. The birds seemed to prefer to build nests close to them. “Where there’s a water source, there are alligators, so it’s sort of this moat of protection around these colonies.”', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e5ef9c25-800d-530a-b87b-fd66f8017d65'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e5ef9c25-800d-530a-b87b-fd66f8017d65'::uuid, 1, NULL, TRUE, 0, NULL, E'Map-making', E'Map-making has a long and fascinating h istory - both before Ptolemy produced the first great map of the world and after, up to the beautiful simplicity of the London Underground map and the precisely-detailed Ordnance Survey maps, which cover almost every inch of the United Kingdom.\nAncient map-makers used to draw in hills, valleys and rivers to give an idea of the topography, the shape of the land. It wasn''t until the late 16th century that contour lines were used - that is, lines that linked points of the land at the same height - but this was to show the relative depths and shallows of a river. The first time land contours were used was on a map of France, which took about forty years to complete, and was finished in 1783. The Ordnance Survey was set up in 1791 and their maps, as the name suggests, were originally made for military purposes, and the first one to be produced was of the county of Kent at a ratio of one inch to one mile.\n\nWhich of the following statements is true about the use of contour lines in map-making?', 'c7bce243-d500-5d58-a14b-8195f34a8fa5'::uuid, NULL, NULL, E'Land contour lines were first used on a map of France.', NULL, NULL),
  ('e5f1a1fa-1e7f-5bdb-8ede-055c8e789175'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e5f1a1fa-1e7f-5bdb-8ede-055c8e789175'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a61f805a-41b1-5de7-87f5-64e7a3311477'::uuid, NULL, NULL, E'Every year, more and more academic courses are made available online.', NULL, NULL),
  ('e5fa402c-a3f5-557e-a28d-201527738847'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e5fa402c-a3f5-557e-a28d-201527738847'::uuid, 1, NULL, TRUE, 0, NULL, E'City Life', E'Urbanization has been a defining trend of the modern era, with more than half of the world''s population now living in cities. Cities offer numerous advantages, including access to better job opportunities, healthcare, education, and cultural amenities. The concentration of people and resources in urban areas drives economic growth and innovation, making cities engines of development. Additionally, cities often serve as melting pots of diverse cultures, fostering social integration and the exchange of ideas. However, living in cities also presents several challenges. Urban areas are frequently plagued by issues such as traffic congestion, pollution, and high living costs. The dense population can strain infrastructure and public services, leading to problems like inadequate housing and healthcare facilities. Furthermore, cities are often characterized by stark inequalities, with significant disparities in wealth and access to resources between different neighborhoods. The rapid pace of urbanization can exacerbate these issues, as cities struggle to accommodate the growing population. Sustainability is another critical concern for urban living. High energy consumption and waste generation contribute to environmental degradation and climate change. To address these challenges, urban planners and policymakers are increasingly focusing on creating sustainable, livable cities. This involves promoting public transportation, green spaces, renewable energy sources, and efficient waste management systems. By adopting such measures, cities can enhance the quality of life for their residents while minimizing their environmental impact. Ultimately, while cities offer numerous benefits, they also require careful planning and management to ensure that they remain vibrant, inclusive, and sustainable places to live.', NULL, NULL, E'Cities offer numerous advantages, as the concentration of people and resources in urban areas drives economic growth and innovation, but living in cities also presents several challenges, such as traffic congestion, pollution, and high living costs, and cities are often characterized by stark inequalities, while sustainability is another critical concern for urban living, so urban planners and policymakers are increasingly focusing on creating sustainable, livable cities.', NULL, 5, 75),
  ('e5fa9aa9-8719-5aa4-91fb-11761ba7ab25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e5fa9aa9-8719-5aa4-91fb-11761ba7ab25'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'eb9493c6-4019-5907-909e-a07b42678ddc'::uuid, NULL, NULL, E'Students need to develop strategies for comprehending the academic lectures.', NULL, NULL),
  ('e6011d57-75d4-52d0-9aad-299683081a1c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e6011d57-75d4-52d0-9aad-299683081a1c'::uuid, 1, NULL, TRUE, 0, NULL, E'Self-motivation', E'Research on motivation has suggested that a strong sense of autonomy is the key to developing the healthy self-motivation that allows children and teens to pursue their goals with passion and to enjoy their achievements. But what we see in many of the kids we test or tutor is motivational patterns that are at the extremes of one, an obsessive drive to succeed and two, seeing little point in working hard.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e602ee0e-d504-5cf4-9b11-1b7698bafd94'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'e602ee0e-d504-5cf4-9b11-1b7698bafd94'::uuid, 1, NULL, TRUE, 0, NULL, E'Essay Plan', NULL, NULL, NULL, NULL, E'2, 1, 3, 4', NULL, NULL),
