  ('e671957f-e0e0-5056-8271-f900d30d7f6c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e671957f-e0e0-5056-8271-f900d30d7f6c'::uuid, 1, NULL, TRUE, 0, NULL, E'Robotics', E'The integration of robotics with artificial intelligence and machine learning enables robots to adapt and learn from their surroundings, improving their capabilities and flexibility. However, the widespread adoption of robotics in manufacturing raises concerns about job displacement and the need for reskilling workers. It is crucial to strike a balance between automation and human labor to ensure sustainable employment and equitable economic development.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e676bd18-9e8a-5a81-9109-e282cf9b6803'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e676bd18-9e8a-5a81-9109-e282cf9b6803'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'af6d9f97-781e-58c3-913a-49f2a8446e1e'::uuid, NULL, E'Companies'' projects must comply with the General Data Protection Regulation.', NULL, NULL, NULL),
  ('e6880118-d4d7-5aa2-818b-ee2572b678e3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e6880118-d4d7-5aa2-818b-ee2572b678e3'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the wet place does crocodile prefer to live in?', '486a475c-3126-5d05-b74f-be10def697d2'::uuid, NULL, NULL, E'Swamp / marsh', NULL, NULL),
  ('e68aa52c-fa4b-56ae-8e0f-e4e1cc3a314b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e68aa52c-fa4b-56ae-8e0f-e4e1cc3a314b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8d98c47c-5df2-52d4-b71e-1a8115e5558a'::uuid, NULL, NULL, E'A surprisingly large number of students applied for that course.', NULL, NULL),
  ('e68aff93-f89e-50af-9ee5-630cb0181389'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e68aff93-f89e-50af-9ee5-630cb0181389'::uuid, 1, NULL, TRUE, 0, NULL, E'Polar Bears', E'Laidre and her colleagues analyzed genetic samples from polar bears that they tracked from 2015 to 2019, which they combined with data from previous studies. In their first discovery, they found a few hundred polar bears in south-east Greenland are the most genetically {{1}} of their species. While tracking these animals, the team further discovered this genetically-isolated group hunts via floating blocks of freshwater ice, broken off from glaciers, for about 250 days of the year, when sea ice has {{2}} . This probably enables the bears to live in the area, which has no sea ice for considerably longer than other polar bear habitats. While this suggests all polar bears are more {{3}} than we previously thought, glacial ice is largely limited to the animals around Greenland and Svalbard. “Glacier ice may help small numbers of polar bears survive for longer periods under climate warming, and may be important to prevent extinction, but it is not available for the vast {{4}} of polar bears,” says Laidre. “Climate action is the single most important thing for the future of polar bears. Most polar bears in the Arctic depend on sea ice.”', NULL, NULL, NULL, E'1.isolated, 2.melted, 3.resilient, 4.majority', NULL, NULL),
  ('e68c02da-26d0-53fb-bdae-aa7d1e6e594b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e68c02da-26d0-53fb-bdae-aa7d1e6e594b'::uuid, 1, NULL, TRUE, 0, NULL, E'Gift-giving', E'Over the centuries, the holiday evolved, and by the 18th century, gift-giving and exchanging handmade cards on Valentine''s Day had become common in England. Handmade Valentine''s cards made of lace, ribbons, and featuring cupids and hearts eventually spread to the American colonies. The tradition of Valentine''s cards did not become widespread in the United States, however, until the 1850s.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e6901303-be82-50f5-82f3-d071a564a3b6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e6901303-be82-50f5-82f3-d071a564a3b6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e3a4459e-8abb-5404-b7d5-7494d825b826'::uuid, NULL, E'The information you need for this meeting is on the website.', NULL, NULL, NULL),
  ('e690ff79-656b-53a1-bb37-d79be0e789fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e690ff79-656b-53a1-bb37-d79be0e789fe'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '59bbc1fb-cbd6-59b6-8644-ebaa54cdf757'::uuid, NULL, NULL, E'A campus tour is beneficial at the beginning of each term.', NULL, NULL),
  ('e693db85-0a17-5074-9dd9-2ac2418abf3f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e693db85-0a17-5074-9dd9-2ac2418abf3f'::uuid, 1, NULL, TRUE, 0, NULL, E'Cognitive Empathy', E'Cognitive empathy is the intellectual ability to ‘read’ others’ emotions. It can be {{1}} as ‘empathic accuracy’. People with higher levels of cognitive empathy tend to be better at communication and have better people skills as they are able to take {{2}} guesses at how another person is feeling or how they may {{3}} emotionally to something.', NULL, NULL, NULL, E'1.described, 2.educated, 3.react', NULL, NULL),
  ('e69ef012-57e8-5a9f-a64c-700e421d59e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e69ef012-57e8-5a9f-a64c-700e421d59e9'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for someone who researches and studies the behavior, anatomy, and habitats of animals?', '68b9c1d2-51f6-5d60-a8e1-7a06f42e103c'::uuid, NULL, NULL, E'Zoologist', NULL, NULL),
  ('e6a63c3e-17ce-509b-9169-d6923fedf6fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'HIGHLIGHT_CORRECT_SUMMARY', E'HIGHLIGHT_CORRECT_SUMMARY', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e6a63c3e-17ce-509b-9169-d6923fedf6fb'::uuid, 1, NULL, TRUE, 0, NULL, E'What Democracy Breeds', E'In a chapter of Democracy in America entitled why the Americans are often so restless in the midst of their prosperity? De Tocqueville sketched an enduring analysis of the relationship between high expectations and dissatisfaction between political equality and envy. He wrote, when all the prerogatives of birth and fortune have been abolished, when every profession is open to everyone, an ambitious man may think it is easy to launch himself on a great career, and feel that he has been called to no common destiny. But this is a delusion which experience quickly corrects. When inequality is the general rule in society the greatest inequalities attract no attention. But when everything is more or less level, the slightest variation is noticed. That is the reason for the strange melancholy often haunting inhabitants of democracies in the midst of abundance, and of that disgust with life sometimes gripping them even in calm and easy circumstances.\n\nClick on the paragraph that best relates to the recording.', '7dbb965c-4533-561a-8232-6054cb4854a8'::uuid, NULL, NULL, E'By analyzing political equality and envy and expectations and dissatisfaction, De Tocqueville mentioned that when everyone is living in a basically equal environment, even the slightest inequality will be noticed. This is the reason that the Americans are often restless even in a cozy circumstance.', NULL, NULL),
  ('e6a77ad5-7cf0-57b4-a4af-f6ecfd8633ce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e6a77ad5-7cf0-57b4-a4af-f6ecfd8633ce'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which word do we use to describe “three times” ?', 'daa046a9-b3fe-5b8e-837c-49482c24f0af'::uuid, NULL, NULL, E'Triple / treble / threefold / thrice', NULL, NULL),
  ('e6abf6bf-6616-5a91-bd4c-d7cb21141c4f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e6abf6bf-6616-5a91-bd4c-d7cb21141c4f'::uuid, 1, NULL, TRUE, 0, NULL, E'Omicron', E'The holiday season is well underway - and with it, a fresh batch of worries over the latest COVID-19 variant, omicron. (Sighing) Was that a giant collective sigh I just heard? I know. After almost two years of pandemic life and last year''s socially distant New Year''s parties, we''re all tired of holding our breath and itching to share some hot chocolate by the fire. The good news is we''ve come a long way in the last year, and though there''s still a lot unknown about the newest variant, there''s still plenty we can do to protect ourselves and our loved ones.\n\nWhat is the speaker’s attitude expressed towards holidays against the outbreak of omicron?', '3480a1ad-1cf5-5e2b-b95d-8ec782ac15e3'::uuid, NULL, NULL, E'Much can be done to protect people, so it is relatively safe to take a holiday.', NULL, NULL),
