  ('e77ae025-911b-5594-95c7-38f0e607d7cf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e77ae025-911b-5594-95c7-38f0e607d7cf'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the lizard that can change its color according to the surroundings?', '145b5381-d840-58be-adc3-b2a2e3ceecea'::uuid, NULL, NULL, E'Chameleon / anole', NULL, NULL),
