  ('e77f020c-5864-542f-b3e8-22b15f8398dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e77f020c-5864-542f-b3e8-22b15f8398dd'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '92bf46a0-694b-527a-9e79-3e10eaafac96'::uuid, NULL, E'This framework could allow us to pose further research questions more systematically.', NULL, NULL, NULL),
  ('e780fef3-c05f-5ade-b5d3-c9a8704ac5a5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e780fef3-c05f-5ade-b5d3-c9a8704ac5a5'::uuid, 1, NULL, TRUE, 0, NULL, E'Dark Chocolate', NULL, 'b49d15b5-e767-51d2-87cf-aee9bf0d8a6e'::uuid, NULL, E'In this presentation, I am excited to share with you the surprising benefits of dark chocolate on health. Often considered a guilty pleasure, dark chocolate, in reality, offers a variety of health advantages when consumed in moderation. Dark chocolate, rich in cocoa, is packed with antioxidants, specifically flavonoids. These compounds are known for their role in reducing heart disease risk by improving blood flow and lowering blood pressure. A study published in the Journal of Nutrition found that regular consumption of small amounts of dark chocolate can benefit cardiovascular health. Moreover, dark chocolate also positively affects brain health. Research suggests that the flavonoids in dark chocolate may improve cognitive function, enhance mood, and even provide neuroprotective effects. This makes it not just a treat for the palate, but also for the mind. Dark chocolate is more than just a dessert. Its health benefits, from improving heart health to boosting brain function, make it a delightful addition to a balanced diet. So next time you savor a piece of dark chocolate, know that it''s not just indulging your taste buds but also contributing to your well-being.', NULL, NULL, NULL),
  ('e7877151-a09f-5bcb-b38c-8cb9fe4e5934'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e7877151-a09f-5bcb-b38c-8cb9fe4e5934'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How many years are there in two centuries?', '839ad03d-27e1-5d53-9ee2-7c5ed25d93cc'::uuid, NULL, NULL, E'Two hundred', NULL, NULL),
