  ('e7d83c04-cd4a-5bad-bdd6-55e97f866efe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e7d83c04-cd4a-5bad-bdd6-55e97f866efe'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '631223c6-ba3f-58e8-b96c-05a8fa849eee'::uuid, NULL, NULL, E'The coffee shop offers a menu including salads, soups, and meats.', NULL, NULL),
  ('e7dbdd85-3d67-504a-8bb2-c775d239840f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e7dbdd85-3d67-504a-8bb2-c775d239840f'::uuid, 1, NULL, TRUE, 0, NULL, E'Sand Battery', E'Finnish researchers have installed the world''s first fully working "sand battery", which can store green power for months at a time.\nThe developers say this could solve the problem of year-round supply, a major issue for green energy.\nUsing low-grade sand, the device {{1}} heat made from cheap electricity from solar or wind.\nThe sand stores the heat at around 500C, {{2}} can then warm homes in winter when energy is more expensive. Because of climate change and now thanks to the rapidly rising price of fossil fuels, there''s a surge of investment in new renewable energy production.\nBut {{3}} new solar panels and wind turbines can be quickly added to national grids, these extra sources also present huge challenges. {{4}} , most batteries are made with lithium and are expensive with a large, physical footprint, and can only cope with a limited amount of excess power. One of the big challenges now is whether the technology can be scaled up to really make a difference — and will the developers be able to use it to get electricity out {{5}} heat?\nThe efficiency falls dramatically when the sand is used to just return power to the electricity grid.', NULL, NULL, NULL, E'1.is charged up with, 2.which, 3.while, 4.Right now, 5.as well as', NULL, NULL),
  ('e7dc2a2c-15f7-5488-afde-16dd7ba4b48f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e7dc2a2c-15f7-5488-afde-16dd7ba4b48f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5348a9f7-886a-56aa-ae09-ef789874cd07'::uuid, NULL, E'These grapes produce fruity wines with a high level of alcohol.', NULL, NULL, NULL),
