  ('e7e49825-e0c4-57f5-8eaa-c53fafaacb6b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e7e49825-e0c4-57f5-8eaa-c53fafaacb6b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What are the words or sentences with special meaning that are used by a particular profession or group of people?', 'c4c047ee-6c1d-595f-89f3-012ed46863f9'::uuid, NULL, NULL, E'Jargon / lingo', NULL, NULL),
  ('e7e5ae6c-9081-55c7-b1c1-a8766d154578'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e7e5ae6c-9081-55c7-b1c1-a8766d154578'::uuid, 1, NULL, TRUE, 0, NULL, E'Sustainable Job Growth', E'"Sustainable Job Growth" is a motto for many governments, especially in the aftermath of a recession. The problem of ''job quality'' is less often addressed and may be seen as {{1}} job growth. The sentiment ''any job is better than no job'' may resonate with governments as well as people, especially in the context of high unemployment. However, if the {{2}} between improving the quality of {{3}} jobs and creating new jobs becomes greatly imbalanced towards the latter, this could increase work stress among {{4}} and future workers, which in turn has health, economic and social costs. A recent British Academy Policy Centre Report on Stress at Work highlights these {{5}} , and describes the context, determinants and consequences of work-related stress in Britain.', NULL, NULL, NULL, E'1.hindering, 2.balance, 3.existing, 4.current, 5.concerns', NULL, NULL),
  ('e7eade41-b04b-582a-b07a-50a9103011b4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e7eade41-b04b-582a-b07a-50a9103011b4'::uuid, 1, NULL, TRUE, 0, NULL, E'Extreme Weather Events', E'Extreme weather events are happening more often around the world. Hurricanes are {{1}} up in intensity, particularly in the North Atlantic. The year 2017 was a busy one for Atlantic hurricanes. Hurricanes Harvey, and Maria {{2}} their destructive power on Texas and Florida. A group of scientists using high-resolution computer modeling {{3}} that the main reason the 2017 hurricane season was so {{4}} was due to warm sea-surface conditions in the North Atlantic.', NULL, NULL, NULL, E'1.ramping, 2.unleashed, 3.determined, 4.violent', NULL, NULL),
  ('e7eaf4dd-df10-52eb-a927-13ec15856dc8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e7eaf4dd-df10-52eb-a927-13ec15856dc8'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4af6934c-7d69-52d5-8da1-c52340d44d66'::uuid, NULL, NULL, E'Our university is working on the issue of the population decrease.', NULL, NULL),
  ('e7edf1e1-bb8e-52fc-975c-d9d7a59ee04f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e7edf1e1-bb8e-52fc-975c-d9d7a59ee04f'::uuid, 1, NULL, TRUE, 0, NULL, E'Meat and Dairy', E'Do you want to know roughly how much longer you might live if you permanently {{1}} a healthier diet? The “Food for healthy life” website can give you an idea – and if you’re under 60 and eat a typical Western diet, the answer could be around a decade or more on average. The website is based on data from hundreds of studies. “The estimated life {{2}} is mainly due to a reduction in the risk of heart disease, diabetes and cancer,” says Lars Fadnes at the University of Bergen in Norway. His team started with recent meta-analyses of the effect of eating various amounts of particular food types, such as fruits. These findings were combined with data on global mortality and what people currently eat to estimate the impact of a permanent change in diet. The highest estimates of lifespan extension are based on a diet designed to {{3}} the health benefits. This optimized diet involves eating no red or {{4}} meat, drinking no sugar-sweetened beverages, reducing dairy and egg consumption, and eating more legumes, whole grains and nuts.', NULL, NULL, NULL, E'1.adopted, 2.extension, 3.maximize, 4.processed', NULL, NULL),
  ('e7f282b4-b6cf-51f8-a9eb-ddd0baa7c204'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e7f282b4-b6cf-51f8-a9eb-ddd0baa7c204'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6e57d5b0-4f01-5b8a-bfb6-123c11e9f746'::uuid, NULL, NULL, E'There had been many female artists in early modern France.', NULL, NULL),
  ('e80a9249-0b23-5068-a165-2441422e036f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e80a9249-0b23-5068-a165-2441422e036f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the force that draws objects toward a planet''s center?', '75f35ec2-dcbb-5098-850f-68417971d2c2'::uuid, NULL, NULL, E'Gravity / gravitation', NULL, NULL),
  ('e81beff9-28e5-5445-8307-ad1497c38ffb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e81beff9-28e5-5445-8307-ad1497c38ffb'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the sport of swimming under water by using special devices to help you breathe?', '02d972d8-d2d8-578c-b75d-dd336af8f81d'::uuid, NULL, NULL, E'Diving', NULL, NULL),
  ('e81e1f64-3da2-5341-866e-9ee01cf2a120'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e81e1f64-3da2-5341-866e-9ee01cf2a120'::uuid, 1, NULL, TRUE, 0, NULL, E'Christopher Columbus', E'In 1492, Italian sailor Christopher Columbus, sent by Spain, arrived in the New World. This was a dramatic event for both the people who already lived in the Americas and for Europe. Native Americans fell {{1}} to an immense plague of European diseases which weakened them in the face of armies led by Spanish conquistadors. Within a few decades, Spain conquered the Caribbean, the Aztec Empire of modern-day Mexico, and the Inca Empire stretching across the Andes. Native Americans were {{2}} and forced to work on plantations and mines. As a result, Spain grew rich and powerful. The other countries of Europe looked upon the success of Spain with envy. They quickly hired explorers of their own and sent them west in search of societies to conquer, gold to snatch, and perhaps even a route to Asia for a {{3}} trade connection.', NULL, NULL, NULL, E'1.victim, 2.enslaved, 3.prosperous', NULL, NULL),
  ('e822e040-58e2-517b-a758-b971b2920f07'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e822e040-58e2-517b-a758-b971b2920f07'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '78f4862f-f287-5421-a996-5e989b11c32c'::uuid, NULL, E'For many years, the schools attempted to neutralize controversies over race.', NULL, NULL, NULL),
  ('e822e3ff-9681-5daf-9e40-7a0832edbdb4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e822e3ff-9681-5daf-9e40-7a0832edbdb4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '9e036d1d-b307-5002-bb13-1ed8dfe30f1a'::uuid, NULL, NULL, E'Giving good examples can help make what you''re saying stronger.', NULL, NULL),
  ('e8232cbb-b5b9-5f38-af42-16daca48cfdd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e8232cbb-b5b9-5f38-af42-16daca48cfdd'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8bcde026-80da-5069-971c-99966f48a4d5'::uuid, NULL, NULL, E'Using the same method again led to the same problem.', NULL, NULL),
  ('e83026c3-badf-5b57-baa4-2c1869796fae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e83026c3-badf-5b57-baa4-2c1869796fae'::uuid, 1, NULL, TRUE, 0, NULL, E'Dense UK Cities', E'People who live in dense urban areas, particularly those with closely packed apartments, are more likely to experience loneliness and {{1}} , a large-scale study of UK cities has found. Chris Webster at the University of Hong Kong and his colleagues analyzed health data from nearly 406,000 people in 22 UK cities held by the UK Biobank and compared it with detailed data of their environment, such as their {{2}} to busy roads and green spaces. The team found that people’s self-reported loneliness increased by 2.8 per cent for every additional 1000 housing units within 1 kilometer of their home, while their self-reported social isolation increased by 11.4 per cent. The researchers controlled for factors including age, health and socioeconomic status, finding that the effects were more {{3}} in men and retirees. Compared with their {{4}} living in the lowest residential densities, men in the highest densities were 23.5 per cent more likely to report loneliness, while retirees in areas with the densest housing were 17.4 per cent more likely to do so.', NULL, NULL, NULL, E'1.isolation, 2.proximity, 3.pronounced, 4.counterparts', NULL, NULL),
  ('e8313a73-1a59-5750-9cbe-3ae33677092e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e8313a73-1a59-5750-9cbe-3ae33677092e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0d625194-2629-5320-8fbb-14fb5459dd96'::uuid, NULL, E'We are aware of the potential problems and have taken every precaution.', NULL, NULL, NULL),
  ('e8367a93-d013-57d0-811c-1aaaf1255de8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e8367a93-d013-57d0-811c-1aaaf1255de8'::uuid, 1, NULL, TRUE, 0, NULL, E'Rock', E'Most rocks are made of minerals containing silicon and oxygen, the most abundant elements in the Earth’s crust. There are three kinds of rock: igneous, sedimentary and metamorphic. Igneous rocks form when molten rock cools and solidifies. Sedimentary rocks originate when particles settle out of water or air. Metamorphic rocks result when existing rocks are changed by heat or pressure.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e837d0c1-96b3-5989-8d02-dc4a511fadd5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e837d0c1-96b3-5989-8d02-dc4a511fadd5'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person who is in charge of a meeting?', '7310d1f1-7ec2-5bbe-b436-6c52de47c550'::uuid, NULL, NULL, E'Chairman / chairwoman / chairperson', NULL, NULL),
  ('e838f3bf-23e8-5033-86b8-7385130fff9c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e838f3bf-23e8-5033-86b8-7385130fff9c'::uuid, 1, NULL, TRUE, 0, NULL, E'King Arthur', E'Little is known about the figure that inspired the story of King Arthur. While Arthurian legends have been a part of Western literature for centuries, the historical reality of King Arthur remains shrouded in {{1}} . The earliest references to a figure resembling Arthur come from various sources, including Welsh, Latin, and later, mediaeval English texts. However, concrete evidence linking Arthur to a specific historical figure is {{2}} . One of the key figures associated with the Arthurian legend is the 6th century Welsh bard Aweinrin( also known as Awenydd). While Aweinrin himself is an elusive historical figure, his works, particularly his poetry, suggest that he may have played a role in shaping the mythic image of Arthur. Aweinrin''s poems are filled with references to heroic warriors and {{3}} , which may have been inspired by real historical events or figures from the tumultuous period of post-Roman Britain. In the context of Arthur, Aweinrin''s work might have contributed to the development of the legend of a warrior king who defends his people against invaders. Though Aweinrin''s connection to Arthur is {{4}} , some scholars believe that elements of his poetry could have been woven into later tales of the Arthurian cycle. Whether or not Aweinrin directly inspired the stories of King Arthur, his legacy as a poet and historian of his time remains {{5}} in understanding the origins of these enduring myths.', NULL, NULL, NULL, E'1.obscurity, 2.lacking, 3.battles, 4.speculative, 5.influential', NULL, NULL),
  ('e8399ff7-af5b-5161-9757-07508fb0ce52'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e8399ff7-af5b-5161-9757-07508fb0ce52'::uuid, 1, NULL, TRUE, 0, NULL, E'Reptiles', E'Reptiles, the most abundant and {{1}} animal group in the desert, are well {{2}} to extreme temperature variation because they are cold blooded, which means they do not need to invest energy in {{3}} a constant body temperature. In other words, reptiles can use this energy {{4}} , like hunting.', NULL, NULL, NULL, E'1.diverse, 2.adapted, 3.maintaining, 4.elsewhere', NULL, NULL),
  ('e839e6b0-de1e-5789-8cc5-25c043ae6877'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e839e6b0-de1e-5789-8cc5-25c043ae6877'::uuid, 1, NULL, TRUE, 0, NULL, E'Milk Carton', E'You are shopping in a supermarket and accidentally drop the carton of milk you are holding, causing the milk to spill onto the floor. What would you say to a store stuff member?', 'a1244270-8b12-5aa3-aa26-ed97a4c604c2'::uuid, NULL, E'Respected staff member, I hope you are doing well.\nI would like to discuss an issue we have encountered with the spilled milk on the floor.\nIt appears that I accidentally dropped the carton of milk I was holding and the milk spilled onto the floor.\nI would appreciate your opinion on this matter. Thank you for your consideration.', NULL, NULL, NULL),
  ('e83a8653-96eb-57eb-9d59-ad82b912cc4a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e83a8653-96eb-57eb-9d59-ad82b912cc4a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6fef539a-50ba-5be8-b897-22c976edeb79'::uuid, NULL, NULL, E'The stock market crash had repercussions throughout the world.', NULL, NULL),
  ('e83ab9e6-64e2-562f-8324-7c28fc39c3f2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e83ab9e6-64e2-562f-8324-7c28fc39c3f2'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do you call the two children born by a mother at the same time?', '4a50d0a3-06b1-5f72-a6c8-b5df477e5b75'::uuid, NULL, NULL, E'Twins', NULL, NULL),
  ('e83f7f7f-676f-5766-84b4-5f9fedea1b72'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e83f7f7f-676f-5766-84b4-5f9fedea1b72'::uuid, 1, NULL, TRUE, 0, NULL, E'Bangalore Palace', E'The majestic Bangalore Palace is iconic for many reasons. The palace rooms now occupy arts and artifacts from the bygone era and is a popular destination for music events. If you are visiting the palace, do opt for the audio guide for an immersive experience.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e844ef7e-664b-5449-a81a-06fb34f2f875'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e844ef7e-664b-5449-a81a-06fb34f2f875'::uuid, 1, NULL, TRUE, 0, NULL, E'Buying a House', E'Buying a {{1}} can seem like a daunting process. First you need to work out how much you can borrow. This is where our services will really help you. Make sure you have an accurate and detailed budget that takes into account all associated with purchasing a property, including stamp duty, council rates, and other fees. We can help you identify these extra costs. Ask us for our budget planner if you don''t already have one. Interest rates move constantly, so you will need to allow room in your budget for interest rate increases and for other {{2}} events. All purchase funds are paid at settlement. In the {{3}} of events, settlement takes place, the purchase price is paid in full and the deposit bond simply lapses into group certificates for the {{4}} two years.', NULL, NULL, NULL, E'1.house, 2.unforeseen, 3.ordinary course, 4.past', NULL, NULL),
  ('e84c1292-7a75-582e-b375-51ff14f72f53'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e84c1292-7a75-582e-b375-51ff14f72f53'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5682eb29-f8fb-5e7f-a3f1-655f9e7d9838'::uuid, NULL, NULL, E'Slides and handouts can be downloaded after the lecture.', NULL, NULL),
