  ('e86048fa-172e-505f-bc44-5d6e70b9c016'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e86048fa-172e-505f-bc44-5d6e70b9c016'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which medical instrument will a doctor use for putting drugs into a patient’s body?', '50d0a239-4d2b-548f-a20d-d5b1c5a164c2'::uuid, NULL, NULL, E'Syringe', NULL, NULL),
  ('e8616986-c8eb-56b3-9c7b-a8c882f45b4c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e8616986-c8eb-56b3-9c7b-a8c882f45b4c'::uuid, 1, NULL, TRUE, 0, NULL, E'Secret Farm', E'A secret farm in South Africa is {{1}} to 2,000 white rhinos, one of the largest herds in the world. The farm was recently bought by African Parks, a conservation charity that plans to rewild the rhinos and {{2}} them to their natural habitats across Africa. The farm was founded by John Hume, who wanted to {{3}} rhinos and sell their horns, but ran out of money. African Parks saw the opportunity to save the rhinos and use them to rebuild populations that have been decimated by poaching. Poaching is driven by the demand for rhino horn in some parts of Asia, where it is used in traditional medicine and as a status symbol. The charity hopes to transfer all the rhinos {{4}} the farm to secure and sustainable locations in the next 10 years. This would be one of the most ambitious animal rewilding projects ever {{5}} , and could secure the future of the white rhino in Africa.', NULL, NULL, NULL, E'1.home, 2.restore, 3.breed, 4.from, 5.undertaken', NULL, NULL),
  ('e8633a31-f7be-5d15-8d3d-f53b2d41aac0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e8633a31-f7be-5d15-8d3d-f53b2d41aac0'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '65344dc9-d351-5613-867f-52517acd74dc'::uuid, NULL, NULL, E'The integration of archeologists'' studies with community projects is widely encouraged.', NULL, NULL),
  ('e866afa7-c0ed-5bc9-9c0b-d02dd34bee86'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e866afa7-c0ed-5bc9-9c0b-d02dd34bee86'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '73906f15-656e-518f-8297-0c712aecfd42'::uuid, NULL, NULL, E'Studying history can help you better understand the present.', NULL, NULL);
INSERT INTO _pte_local_seed_questions (question_public_id, created_at, updated_at, deleted, pte_task_type, task_type_key, task_type_section, visibility, tenant_id, status, revision_group_public_id, revision_number, supersedes_public_id, is_current, version, rejection_reason, title, prompt_text, audio_prompt_ref, image_prompt_ref, reference_answer_text, correct_answer_text, min_word_count, max_word_count) VALUES
  ('e869ea35-850c-553c-b0ab-33a28c84dacc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e869ea35-850c-553c-b0ab-33a28c84dacc'::uuid, 1, NULL, TRUE, 0, NULL, E'Learning from History', E'The prospect of learning something from history is what makes sociologists tick. It is through {{1}} a systematic understanding of the forces which shape our lives that we {{2}} exercise control over them. The founding thinkers of sociology, who {{3}} to prominence during the development of what we are pleased to call modernity, thought so. It Is the intimate relationship between the development of sociology and the development of modernity that the course begins with.\nThis relationship is an intimate one, because it is {{4}} with the social change instituted in the development of the modern world that a discipline such as sociology and social science in general could either exist or have anything to study.', NULL, NULL, NULL, E'1.developing, 2.can, 3.came, 4.only', NULL, NULL),
  ('e86c2657-4895-5dd8-a722-bf7c96a015e6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e86c2657-4895-5dd8-a722-bf7c96a015e6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '58cbf999-de6a-5a24-90ea-ca58091c5a01'::uuid, NULL, E'I was driving along the road when a kid suddenly stepped out in front of me.', NULL, NULL, NULL),
  ('e86fb885-2e42-5f3a-9444-7e124edbdfe7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e86fb885-2e42-5f3a-9444-7e124edbdfe7'::uuid, 1, NULL, TRUE, 0, NULL, E'Overqualified Employees', E'If your recruiting efforts attract job applicants with too much experience—a near certainty in this weak labor market—you should consider a response that runs counter to most hiring managers’ MO: Don’t reject those applicants out of hand. Instead, take a closer look. New research shows that overqualified workers tend to perform better than other employees, and they don’t quit any sooner. Furthermore, a simple managerial tactic—empowerment—can mitigate any dissatisfaction they may feel.\nThe prejudice against too-good employees is pervasive. Companies tend to prefer an applicant who is a “perfect fit” over someone who brings more intelligence, education, or experience than needed. On the surface, this bias makes sense: Studies have consistently shown that employees who consider themselves overqualified exhibit higher levels of discontent. For example, over-qualification correlated well with job dissatisfaction in a 2008 study of 156 call-center reps by Israeli researchers Saul Fine and Baruch Nevo. And unlike discrimination based on age or gender, declining to hire overqualified workers is perfectly legal.\nBut even before the economic downturn, a surplus of overqualified candidates was a global problem, particularly in developing economies, where rising education levels are giving workers more skills than are needed to supply the growing service sectors. If managers can get beyond the conventional wisdom, the growing pool of too-good applicants is a great opportunity. Berrin Erdogan and Talya N. Bauer of Portland State University in Oregon found that overqualified workers’ feelings of dissatisfaction can be dissipated by giving them autonomy in decision making. At stores where employees didn’t feel empowered, “overeducated” workers expressed greater dissatisfaction than their colleagues did and were more likely to state an intention to quit. But that difference vanished where self-reported autonomy was high.', NULL, NULL, E'Prejudice against too-good employees is pervasive as employees who consider themselves overqualified exhibit higher levels of discontent and declining to hire overqualified workers is perfectly legal, but the growing pool of too-good applicants is a great opportunity for managers because overqualified workers tend to perform better than other employees, and empowerment can mitigate any dissatisfaction they may feel.', NULL, 5, 75),
  ('e8711da4-53d2-5c65-80a9-6b842df70fc9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e8711da4-53d2-5c65-80a9-6b842df70fc9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a983bc5b-c1d8-51ac-bc37-7251ec9faa07'::uuid, NULL, E'Earthquakes happen when two tectonic plates collide with each other.', NULL, NULL, NULL),
