  ('e87890ef-d477-51e3-b9ac-44597fcd55aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e87890ef-d477-51e3-b9ac-44597fcd55aa'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4416488e-4332-5f2c-87eb-6103027353ae'::uuid, NULL, NULL, E'He recently completed a national science foundation research for undergraduates.', NULL, NULL),
  ('e87d31e6-1f42-59da-8217-646f2414b6b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e87d31e6-1f42-59da-8217-646f2414b6b2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd60cf505-d3f2-5272-8759-81c9bb56e751'::uuid, NULL, NULL, E'Our mission is to disseminate and apply the new knowledge.', NULL, NULL),
  ('e88458d5-ac94-5171-9f02-6c2ad858f374'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e88458d5-ac94-5171-9f02-6c2ad858f374'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3712e7ee-d291-5156-976a-13563b58b575'::uuid, NULL, E'There are three separate assignments for this module.', NULL, NULL, NULL),
  ('e8888629-0f39-5231-8e12-762e4b9c1085'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e8888629-0f39-5231-8e12-762e4b9c1085'::uuid, 1, NULL, TRUE, 0, NULL, E'Bioluminescent Animals', E'Bioluminescence, the ability of certain animals to produce and emit light, has long intrigued scientists and captivated the public''s imagination. This incredible natural phenomenon is not only a marvel to behold but also serves various functions in the animal kingdom.\nOne of the most well-known bioluminescent creatures is the firefly. These tiny insects produce light through a chemical reaction in their abdomen to attract mates during their nocturnal courtship displays. Fireflies create a mesmerizing spectacle on warm summer evenings, as they flicker and glow in synchrony.\nDeep beneath the ocean''s surface, bioluminescence is even more prevalent. Many marine species, including certain types of jellyfish, anglerfish, and plankton, use bioluminescence for a range of purposes. Some deep-sea creatures employ it as a form of camouflage, matching their light emission to the faint glow of sunlight filtering through the water above.\nBioluminescence can also be a means of communication and defense. Some squids use flashes of light to communicate with each other or to deter predators. The ability to emit sudden bursts of bluish light can startle and confuse potential threats, allowing the squid to escape.\nScientists have been studying bioluminescent animals for years, not only to understand the biological mechanisms behind their light production but also to develop new technologies. The enzymes and molecules responsible for bioluminescence have been utilized in biotechnology, leading to advancements in fields like medicine and genetics.\nIn summary, the world of bioluminescent animals is a captivating realm filled with unique and awe-inspiring creatures. These organisms have evolved remarkable adaptations, from finding mates to surviving in the depths of the ocean. Beyond their natural beauty, they offer valuable insights and potential applications that continue to inspire scientific research and innovation.', NULL, NULL, E'Bioluminescence, a natural ability in certain animals like fireflies, jellyfish, and squids to emit light, plays varied roles from courtship to camouflage in the deep sea, captivating both the public and scientists who study its biological mechanisms and potential applications in fields like medicine and genetics.', NULL, 5, 75),
  ('e88d831d-f590-53d3-98cf-0b3540584941'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e88d831d-f590-53d3-98cf-0b3540584941'::uuid, 1, NULL, TRUE, 0, NULL, E'Disinformation', E'Melting of glaciers, rising sea levels, extreme heat waves: the consequences of climate change are more visible than ever, and the scientific community has confirmed that humans are responsible. Yet studies show that a third of the population still doubts or disputes these facts. The cause is disinformation spread by certain vested interests.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e88fc7c7-736f-5c77-9e06-2460c5c42091'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e88fc7c7-736f-5c77-9e06-2460c5c42091'::uuid, 1, NULL, TRUE, 0, NULL, E'Noninvasive Brain Stimulation', E'Noninvasive brain stimulation is having its heyday, as scientists and hobbyists alike look for ways to change the activity of neurons without cutting into the brain and implanting electrodes. Next, the researchers wanted to figure out how much current they needed to apply to the human scalp to produce those electrical fields inside the brain.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e8975c60-6036-5ffc-8aca-5c667ef82e5f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e8975c60-6036-5ffc-8aca-5c667ef82e5f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0b15599d-3365-5a90-93e5-28f3a84f52fb'::uuid, NULL, E'We offer databases and educational resources to students of all ages.', NULL, NULL, NULL),
  ('e898e4aa-47ca-5817-8df7-dbd01a59777c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e898e4aa-47ca-5817-8df7-dbd01a59777c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a8dd7b60-0cba-5e37-8c28-3cd4e63f5b27'::uuid, NULL, E'The company has to deal with huge losses resulting from its latest investment.', NULL, NULL, NULL),
  ('e89aa473-00de-5f88-9c64-2f2000a39e4c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e89aa473-00de-5f88-9c64-2f2000a39e4c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which word is relating to the moon, lunar or solar?', 'd3150a34-bffa-570f-b5b3-79d6b6f37da9'::uuid, NULL, NULL, E'Lunar', NULL, NULL),
  ('e89b63a9-46ec-5b9b-af04-3a931586954a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e89b63a9-46ec-5b9b-af04-3a931586954a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '57dbba73-87dc-545e-b7c6-84db68882c55'::uuid, NULL, E'The analytical and communication skills are essential to accounting and finance.', NULL, NULL, NULL),
  ('e89f09a6-01ce-55b6-be88-08a4e31d6aee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e89f09a6-01ce-55b6-be88-08a4e31d6aee'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-L', E'What troubles me when I''m asked the question, "Can creative writing be taught?" - usually asked in a skeptical tone of voice - is not lhat I can''t find an answer, but trying\nto figure out why I''m being asked. What do they want me to say? "No, of course it can''t. I just like taking people for a ride. I''m a con artist."\nObviously, you can''t teach someone to have a talent for storytelling,\nor a love of language, or how to write extremely well, but there\nare important lessons to be gotten across that will improve their writing and, at the very least, make it publishable.\nFor me, the best starting point is the habit of close reading, really close, and responding to the language. Forget about grand themes and ethical content, whatever, for the moment and ask if the author writes badly or well. So, writing can be taught through reading, through literature. Then I''d say, when it comes to your own writing, that you need to learn how to edit: to know when to say, "You don''t need that word or tllat sentence. And tllat whole paragraph can go:· It''s one of the most important lessons a writing class can teach. As for producing a Tolstoy or a Dickens ... well, people like that tend to get there by their own route.\n\nWhat is the speaker''s view of creative writing classes?', '78ed7cb4-c0b0-5dfc-928f-1efa7792b5ab'::uuid, NULL, NULL, E'There are certain important aspects of writing they can teach.', NULL, NULL),
  ('e8ae9f92-2d8f-5b7b-bce6-37567059f9ce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e8ae9f92-2d8f-5b7b-bce6-37567059f9ce'::uuid, 1, NULL, TRUE, 0, NULL, E'Mugginess', E'What Makes It Muggy?\nLike the heat index, muggy is a "feels-like" condition, except it has to do more with how "breathable" the air feels than how hot it feels. The muggier the weather, the less chance you''ll feel cool because of decreased evaporation rates, which is why the following weather conditions are notoriously linked to the muggiest of days and nights:\nWarm air temperatures, generally of 70°F or above (the warmer the air, the more moisture it''s able to hold);\nHigh moisture (the more moisture there is in the air, the "heavier" it feels); and low winds (the less wind there is, the fewer air molecules there are passing over your skin evaporating and cooling you off).\nSince mugginess expresses how moist the air feels, you might think that relative humidity would be a good indicator of how muggy it feels outside. However, dewpoint temperature is actually a better measure of mugginess. Why? Dewpoint not only gives you an indication of how moist air is, but how warm it is as well (since dew point temperature can go as high as, but never higher than the actual air temperature). So if the dew point is high, it means both air moisture and temperature probably are, too.', NULL, NULL, E'Muggy is a "feels-like" condition, except it has to do more with how "breathable" the air feels than how hot it feels, so the muggier the weather, the less chance you''ll feel cool, because of the warm air temperatures, high moisture and low winds, and dewpoint temperature is actually a better measure of mugginess, as dewpoint not only gives you an indication of how moist air is, but how warm it is as well.', NULL, 5, 75),
  ('e8af7d63-8e9c-574d-83e9-07a07bde44de'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e8af7d63-8e9c-574d-83e9-07a07bde44de'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '3ba94d39-1856-5a99-a329-df21feff4327'::uuid, NULL, E'The Italian cheese has been exported to many different countries.', NULL, NULL, NULL),
  ('e8b24f9e-7cd9-50f1-bf00-dceb84f2fe05'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e8b24f9e-7cd9-50f1-bf00-dceb84f2fe05'::uuid, 1, NULL, TRUE, 0, NULL, E'Neanderthals', E'Anthropologists'' early perception of Neanderthals was partly {{1}} in racist ideology that one''s intelligence or humanity could be {{2}} from skull shape, and that ancestral human species like Neanderthals were necessarily much more "primitive" than humans are today. Those assumptions have now been {{3}} : new discoveries over the past few decades have helped to rehabilitate Neanderthals'' reputation as people who were a lot like us.', NULL, NULL, NULL, E'1.rooted, 2.assessed, 3.discredited', NULL, NULL),
  ('e8b3c7ae-4c03-5159-9ff7-f48bd33f5419'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e8b3c7ae-4c03-5159-9ff7-f48bd33f5419'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9b244861-d064-5833-80a3-2b164b9a1ed1'::uuid, NULL, E'Globalization has been an overwhelming urban and urbanization phenomenon.', NULL, NULL, NULL),
  ('e8b40acc-a94d-5db8-9b1e-3a638a57b787'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e8b40acc-a94d-5db8-9b1e-3a638a57b787'::uuid, 1, NULL, TRUE, 0, NULL, E'UNV', E'If you are inspired to take concrete action for global peace and development, take a look at the United Nations Volunteers (UNV) Program. Every year, up to 8,000 qualified and experienced women and men of some 160 different nationalities volunteer at least six months of their lives to help others. These UN volunteers work in some 130 countries promoting peace, responding to disasters, empowering communities and helping to build sustainable livelihoods and lasting development. UN Volunteers come from dozens of professional backgrounds but all of them are catalysts of positive change. They are encouraged to be creative and entrepreneurial, and foster volunteerism for peace and development both within and beyond their assignments. They work at the heart of communities in partnership with governments, United Nations entities and civil society. Being a UN Volunteer is not a career (you are currently limited to four years of service), but it is rich with opportunities and experience and offers huge personal rewards. As a UN Volunteer you receive a Volunteer Living Allowance (VLA) which covers basic needs, housing and utilities. Additionally, UNV will provide a settling-in-grant, life, health, and permanent disability insurance, return airfares and a nominal resettlement allowance.', NULL, NULL, E'UN volunteers work in some 130 countries, who come from dozens of professional backgrounds, and they are encouraged to be creative and entrepreneurial, and foster volunteerism for peace and development both within and beyond their assignments while working at the heart of communities, so it is rich with opportunities and experience and offers huge personal rewards.', NULL, 5, 75),
  ('e8b76685-3b38-5624-9080-d9c2ba32a9ec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e8b76685-3b38-5624-9080-d9c2ba32a9ec'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the device used to amplify sound, especially for musical instruments?', 'baadebec-5040-52d2-98dd-49375a51fc4a'::uuid, NULL, NULL, E'Amplifier', NULL, NULL),
  ('e8bb5c51-ab38-58c1-ad4c-d093bbff27f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e8bb5c51-ab38-58c1-ad4c-d093bbff27f9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c35ed503-13a6-5786-9819-83d78e29f619'::uuid, NULL, NULL, E'You are required to attend lectures and write weekly reports.', NULL, NULL),
  ('e8bccfd9-ad1f-5568-93c5-67679c7f3e0a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e8bccfd9-ad1f-5568-93c5-67679c7f3e0a'::uuid, 1, NULL, TRUE, 0, NULL, E'Dangerous Superbugs', E'Antibiotics either directly kill bacteria or slow their growth, leaving the immune system to finish the job. The drugs work in several ways — by preventing bacteria from building sturdy walls or making copies of their DNA, for instance. Growth-slowing antibiotics usually disrupt ribosomes, the factories in which bacterial cells make proteins.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e8beac00-b8c0-5a03-9fb2-44d7bb74710b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e8beac00-b8c0-5a03-9fb2-44d7bb74710b'::uuid, 1, NULL, TRUE, 0, NULL, E'Brain Bus', E'These fascinating questions and more will be revealed by University of Manchester scientists when they take to the road on their ''Brain Bus''. The bus is taking hands on {{1}} to test the senses to the suburbs, to show young and old alike how the brain works and how science can answer some of life''s most captivating questions.\nOrganiser Dr Stuart Allan, lecturer at the Faculty of Life Sciences, explains: "Three-year-olds and upwards can understand the senses and it''s an area that is {{2}} to all ages. "It takes effort to get out of bed on a Saturday morning and go to the Museum. We are bringing science to your doorstep and going further afield this year in the hope of finding new and different {{3}} . "We want people to see that science is interesting as well as important in our lives, and to {{4}} people who may not consider it possible to go to University."', NULL, NULL, NULL, E'1.activities, 2.intriguing, 3.audiences, 4.encourage', NULL, NULL),
  ('e8c05b87-ccfc-5a86-9648-988a21bfbb37'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e8c05b87-ccfc-5a86-9648-988a21bfbb37'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8615a3c6-0987-5163-b326-292baa6ba0bf'::uuid, NULL, E'I don''t like cheese and tomato sandwiches on white bread and orange juice.', NULL, NULL, NULL),
  ('e8c10f94-ef9b-5edb-a369-f9275b5bd4d6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e8c10f94-ef9b-5edb-a369-f9275b5bd4d6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '12d65076-36e1-5d93-b5a0-1a77748aa756'::uuid, NULL, NULL, E'They have devised methods to represent plant growth through charts.', NULL, NULL),
  ('e8c40007-3c2f-545b-834f-5d06143ee8e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e8c40007-3c2f-545b-834f-5d06143ee8e9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7bbe6c31-1a41-574b-ae07-e974ca36b70b'::uuid, NULL, E'To write a good essay you must first organize your ideas logically.', NULL, NULL, NULL),
  ('e8c46767-b622-50a3-af31-b63f1c689a04'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e8c46767-b622-50a3-af31-b63f1c689a04'::uuid, 1, NULL, TRUE, 0, NULL, E'Traffic Congestion', E'City planners predict that as more people move into urban areas, traffic jams will get worse. That''s why sustainability experts propose a new way to analyze traffic congestion. Using more precise measures to describe the shape of cities and considering other socioeconomic factors, the model, which was applied to nearly 100 American cities, could lead to a better understanding of the link between congestion and land use.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e8c52d9b-18fe-5f5f-a300-06418c00f4a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e8c52d9b-18fe-5f5f-a300-06418c00f4a6'::uuid, 1, NULL, TRUE, 0, NULL, E'Globalization', NULL, '85446969-bb0f-5163-a7b4-d1ef44cef2c0'::uuid, NULL, E'I''ve been thinking a lot about the world recently and how it''s changed over the last 20, 30, 40 years. Twenty or thirty years ago, if a chicken caught a cold and sneezed and died in a remote village in East Asia, it would have been a tragedy for the chicken and its closest relatives, but I don''t think there was much possibility of us fearing a global pandemic and the deaths of millions. Twenty or thirty years ago, if a bank in North America lent too much money to some people who couldn''t afford to pay it back and the bank went bust, that was bad for the lender and bad for the borrower, but we didn''t imagine it would bring the global economic system to its knees for nearly a decade. This is globalization. This is the miracle that has enabled us to transship our bodies and our minds and our words and our pictures and our ideas and our teaching and our learning around the planet ever faster and ever cheaper. It''s brought a lot of bad stuff, like the stuff that I just described, but it''s also brought a lot of good stuff. A lot of us are not aware of the extraordinary successes of the Millennium Development Goals, several of which have achieved their targets long before the due date. That proves that this species of humanity is capable of achieving extraordinary progress if it really acts together and it really tries hard.', NULL, NULL, NULL),
  ('e8d33f4e-734f-534b-a584-cc3e3c97aded'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e8d33f4e-734f-534b-a584-cc3e3c97aded'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3813b057-0225-56e4-a16e-96531ebe8821'::uuid, NULL, NULL, E'Career opportunities in this field are quite limited.', NULL, NULL),
  ('e8d6ffe9-5be0-5d05-9a82-f02d93f3fb05'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e8d6ffe9-5be0-5d05-9a82-f02d93f3fb05'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9eace1ae-e80f-544c-8c25-1a8d98d7b8fd'::uuid, NULL, E'Scientists should have the freedom to explore their research interests freely.', NULL, NULL, NULL),
  ('e8dc4c61-6012-57d7-9240-3d8ac6fa1b47'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e8dc4c61-6012-57d7-9240-3d8ac6fa1b47'::uuid, 1, NULL, TRUE, 0, NULL, E'Icehouse Structures', E'The icehouse structures, of which four still remain intact, are located south of Sultan Kala. These large, conically-domed earthen structures would have had sheets of ice built up on the ground level over the course of the winter to provide year-round ice supplies.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e8dd5a78-6732-5d93-85cf-4bd92064fcaf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'e8dd5a78-6732-5d93-85cf-4bd92064fcaf'::uuid, 1, NULL, TRUE, 0, NULL, E'Stereotype', NULL, NULL, NULL, NULL, E'1, 3, 2, 4', NULL, NULL),
  ('e8e11079-17d1-5731-84c1-4173e8fcd056'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e8e11079-17d1-5731-84c1-4173e8fcd056'::uuid, 1, NULL, TRUE, 0, NULL, E'Study of Leadership', E'Based on collaborative research by Arizona''s top business schools, this study of leadership and company performance uncovers the effects of leadership driven by {{1}} , cost control, and maintaining market share, versus {{2}} driven more by balancing employee relations and development, customer or client {{3}} , and the welfare of the greater community. Together, Mary Sully de Luque, assistant professor of Management and Research Fellow at Thunderbird School of Global Management and David Waldman, director of the Center for Responsible Leadership at ASU''s School of Global Management and Leadership, have found that maintaining a specific focus on earnings in {{4}} making can have negative effects on how a leader is viewed.', NULL, NULL, NULL, E'1.profits, 2.leadership, 3.needs, 4.decision', NULL, NULL),
  ('e8e885c3-e2bd-5657-bef7-b10d0648b281'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e8e885c3-e2bd-5657-bef7-b10d0648b281'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1da89f09-739f-5d4d-b84d-aaaa5c7940bf'::uuid, NULL, NULL, E'The bookstore carries all required textbooks for your school courses.', NULL, NULL),
  ('e8ecbe53-171f-541d-8bcf-9edae7e8ea69'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e8ecbe53-171f-541d-8bcf-9edae7e8ea69'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4ca6e3d2-11b1-562a-a386-b28ccfce6c59'::uuid, NULL, NULL, E'The book was supported by many faculty members.', NULL, NULL),
  ('e8f27d49-50ce-5a30-8f57-68858b895fc0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e8f27d49-50ce-5a30-8f57-68858b895fc0'::uuid, 1, NULL, TRUE, 0, NULL, E'Saliva', E'Saliva contains many useful components. Lubricants. Enzymes for breaking down food. And now, compounds that can reveal a person''s age. That''s {{1}} to a study in the journal Public Library of Science ONE.\nDuring normal development, DNA in your body gets what''s called methylated. Small chemicals called methyl groups bind to the DNA, helping to determine which genes become active. But the patterns of {{2}} change as we grow older. Which was a clue that measuring methylation might give away age.\nThe {{3}} studied DNA in saliva contributed by 34 pairs of male identical twins, ages 21 to 55. They found 88 sites on the men''s DNA where the amount of methylation {{4}} with their ages. The {{5}} next verified that finding in 60 men and women, ages 18 to 70.\nThen they narrowed in on two genes that had the {{6}} age-related correlation. And using just that data, they found that they could estimate the ages of their saliva contributors to within five years.\nThis technique might help in crime scene {{7}} —recovered saliva could tell the age of a perpetrator. So if you''re worried about anyone knowing how old you are, be careful where you spit.', NULL, NULL, NULL, E'1.according, 2.methylation, 3.researchers, 4.correlated, 5.scientists, 6.strongest, 7.investigations', NULL, NULL),
  ('e8f28102-49bc-54b7-b4b4-89aee2c25bb3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e8f28102-49bc-54b7-b4b4-89aee2c25bb3'::uuid, 1, NULL, TRUE, 0, NULL, E'Dictaphones', E'During the early to mid-1900s, dictaphones continued to evolve, with advancements in recording technology. The introduction of magnetic tape in the 1950s brought a more affordable and reliable storage medium for sound data. This innovation led to the production of speech recording devices with improved recording capacity, including the popular cassette tapes.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e8f62eeb-251e-58ee-a491-c9edcf2aa479'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e8f62eeb-251e-58ee-a491-c9edcf2aa479'::uuid, 1, NULL, TRUE, 0, NULL, E'Destination Choice', E'You and your friends are planning a vacation. Someone suggests going to a faraway foreign country, but you realize one friend might have a fear of flying and some of them have a relatively tight budget. You need to carefully propose an alternative suggestion to ensure everyone can enjoy the trip. What would you say to your friends?', '2c99584a-36a5-583b-9293-200e2f3f3c66'::uuid, NULL, E'As we plan our vacation, let''s consider everyone''s preferences and needs. While a faraway foreign country sounds intriguing, we should also think about alternative destinations that accommodate different budget levels and travel preferences. How about exploring a nearby city or taking a road trip to a neighboring state? This way, we can still have an exciting adventure while ensuring everyone feels comfortable and included in the trip.', NULL, NULL, NULL),
  ('e8f7ab8d-b7c4-50d7-97ca-a43aeb834e83'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e8f7ab8d-b7c4-50d7-97ca-a43aeb834e83'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0a5d525b-cd90-5c04-9675-b601f97fb88b'::uuid, NULL, E'Even my friends often confuse me and my twin sister.', NULL, NULL, NULL),
  ('e8f895ee-d63b-5fe6-b4f0-8050a099b72f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e8f895ee-d63b-5fe6-b4f0-8050a099b72f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '54c5649d-707e-5343-b7ee-f831392886ba'::uuid, NULL, E'I can''t afford to take a gap year unless I can get a job and save up.', NULL, NULL, NULL),
  ('e8fd78cc-7855-5b11-aad4-f2583d0897d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e8fd78cc-7855-5b11-aad4-f2583d0897d8'::uuid, 1, NULL, TRUE, 0, NULL, E'Great Sphinx', E'Archaeological excavations in the early 19th century found pieces of its carved stone beard and a royal cobra emblem from its headdress. Residues of red pigment are still visible on the face, leading researchers to conclude that at some point, the Sphinx’s entire visage was painted red. Traces of blue and yellow paint elsewhere suggest to Lehner that the Sphinx was once decked out in gaudy comic book. For thousands of years, sand buried the colossus up to its shoulders, creating a vast disembodied head atop the eastern edge of the Sahara. Then, in 1817, a Genoese adventurer, Captain Giovanni Battista Caviglia, led 160 men in the first modern attempt to dig out the Sphinx. They could not hold back the sand, which poured into their excavation pits nearly as fast as they could dig it out. The Egyptian archaeologist Selim Hassan finally freed the statue from the sand in the late 1930s. “The Sphinx has thus emerged into the landscape out of shadows of what seemed to be an impenetrable oblivion,” the New York Times declared.', NULL, NULL, E'Archaeological excavations found pieces of its carved stone beard and a royal cobra emblem from its headdress, with residues of red pigment still visible on the face, concluding Sphinx was once decked out in gaudy, comic book, and in 1817, a Genoese adventurer, attempted to dig out the Sphinx with the statue freed from the sand finally.', NULL, 5, 75),
  ('e8fe53c3-aac0-534e-bf43-e9efba40250b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e8fe53c3-aac0-534e-bf43-e9efba40250b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6ab9ee0e-efba-51c6-9431-d00d8a2d755d'::uuid, NULL, NULL, E'One student representative will be selected from each class.', NULL, NULL),
