  ('e90838d1-db14-5e2c-92a4-f0e7da4853cf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e90838d1-db14-5e2c-92a4-f0e7da4853cf'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b520e2f6-5d13-5423-ac74-664d73323874'::uuid, NULL, E'The rate of registered marriage has been declining for years.', NULL, NULL, NULL),
  ('e9169e21-2c65-5ad6-8a84-a9c89790e05d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e9169e21-2c65-5ad6-8a84-a9c89790e05d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'If telescopes are used to locate distant objects, what instrument is employed to magnify minuscule objects?', 'fdb2ca9b-4af2-50b5-bc52-326bccc5a057'::uuid, NULL, NULL, E'Microscope / microscopes', NULL, NULL),
  ('e91e8904-65d8-519f-b568-2e18704911e6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e91e8904-65d8-519f-b568-2e18704911e6'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What would you do to show your appreciation for a video on YouTube and other social media?', '6a288608-13f0-5915-b5e4-8b7bb6ec65ed'::uuid, NULL, NULL, E'Like it / subscribe / share / comment / thumbs-up', NULL, NULL),
  ('e9277469-61fd-5c34-bffb-3f2e668a84bf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e9277469-61fd-5c34-bffb-3f2e668a84bf'::uuid, 1, NULL, TRUE, 0, NULL, E'Special Taxi', E'A taxi driver in Taiwan is offering free rides in exchange for singing a karaoke song. Mr Tu Ching Liang, 57, is a big fan of driving, karaoke and of listening to people sing. Mr Tu has become famous for the disco lights in his taxi and his offer of free rides. It is easy to spot his yellow taxi. It has a pink neon star on the dashboard and colourful flashing lights inside. People can select a “karaoke” option if they use a taxi-locating app in the capital city of Taiwan. Mr. Tu will appear on your smartphone screen. When Mr Tu’s taxi arrives, he will give you a microphone and an iPad on which you can go to YouTube and select the song you want to sing. He says people have more bravery to sing at night.\n\nWhich is not the characteristic of Mr. Tu''s taxi?', '16ee21a9-5dcf-530a-9c74-b78a9e6e9166'::uuid, NULL, NULL, E'He could drive very fast.', NULL, NULL),
  ('e9352149-1227-5565-9bee-26bd8a49b484'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e9352149-1227-5565-9bee-26bd8a49b484'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '95198a45-2cef-553b-982e-eea32d88a934'::uuid, NULL, NULL, E'Classical languages are rarely read, and information may soon vanish forever.', NULL, NULL),
  ('e93a15c5-c68b-5bef-932b-8f7f50c6db74'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e93a15c5-c68b-5bef-932b-8f7f50c6db74'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7cb02cc0-40d9-5505-91c4-c0575b82472e'::uuid, NULL, NULL, E'The contract will be signed by the owner of the company.', NULL, NULL),
  ('e93a7657-3fd5-5795-bd06-ef6f443a34af'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e93a7657-3fd5-5795-bd06-ef6f443a34af'::uuid, 1, NULL, TRUE, 0, NULL, E'Telecommunication', E'Today, telecommunication is widespread and devices that assist the progress are common in many parts of the world. There is also a vast array of networks that connect these devices, including computer, telephone and cable networks. Computer communication across the Internet, such as e-mail and instant messaging, is just one of many examples of telecommunication.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('e93c8478-e7a0-5a67-882c-74357e870ca8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e93c8478-e7a0-5a67-882c-74357e870ca8'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5dccd8e9-5a49-54b7-aa67-c32fda8bcefd'::uuid, NULL, E'Most of the assignments should be submitted on the same day.', NULL, NULL, NULL),
  ('e93e4fcd-c2c4-5cd2-80d6-8b853444d483'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e93e4fcd-c2c4-5cd2-80d6-8b853444d483'::uuid, 1, NULL, TRUE, 0, NULL, E'Diagnosis', E'In order to know how behavior patterns can be changed, the clinical psychologist has to know what causes the client to behave the way he or she does. Identifying the cause is called diagnosis. In diagnosis, a psychologist uses two basic tools, interviews and psychological tests. Through interviews and tests, the psychologist tries to classify the problem to see if it falls into any non categories. A psychologist may also attempt to describe the client''s personality in terms of how he or she deals with life, for example, some people like to lead, and some prefer to follow the lead of others. Some people are active and outgoing, while others are quiet and reflective. In a diagnostic interview, the psychologist takes the client''s case history. This means learning how the client got along with parents, teachers, and friends, as well as how the person handle difficult situations in the past. Psychological testing is the other way that a psychologist tries to diagnose the clients problems. Clinical psychologists have developed tests that can help them learn about a person''s intelligence and personality, as well as tests that show whether a person''s behavior or perception is influenced by emotions, disabilities, or other factors. Personality testing is useful in discovering how the client tries to adjust to life. Personality tests can reveal unconscious feelings. The person is unable to talk about. This information can be important and could help shorten the length of treatment required.\n\nWhy does the professor discuss taking a client''s case history?', '4b53e710-7f43-5fc6-89bb-0eaf13291990'::uuid, NULL, NULL, E'To show that a client''s past behavior assists in diagnosis', NULL, NULL),
  ('e9477204-d837-5d22-affb-4b09ffdcd1bb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e9477204-d837-5d22-affb-4b09ffdcd1bb'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e1d6605a-a144-50ae-b8d3-a988fb667538'::uuid, NULL, NULL, E'You do not need to be encouraged to be a hero.', NULL, NULL),
  ('e955d372-4188-591a-9300-9f1c39568cd5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e955d372-4188-591a-9300-9f1c39568cd5'::uuid, 1, NULL, TRUE, 0, NULL, E'Bee Language', NULL, '0d8e6bb1-52a8-528d-b4d8-7f4410c751e3'::uuid, NULL, E'Honey bees do a waggle dance to direct other bees to the source of nectar. The dancing bees like this one can be halted by a headbutt from another bee. Now research has found that this headbutt is actually a warning signal. A feeding station was set up in the lab to mimic the a source of nectar, then foraging bees were introduced to the dangers at the station, such as competition from rival colonies. When foragers returned to the hive they stopped bees dancing. Scientists think the behavior warns dancers of a dangerous source of nectar.', NULL, NULL, NULL),
  ('e956cb86-edda-5f84-89c5-da1c3c286d9a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e956cb86-edda-5f84-89c5-da1c3c286d9a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '799094f7-9341-52de-a4f2-93611fbb3a4a'::uuid, NULL, E'Does the government in your country help families that need help?', NULL, NULL, NULL),
  ('e9571cb0-9ac2-5868-bbd4-4088d754d9a1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e9571cb0-9ac2-5868-bbd4-4088d754d9a1'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e1d60feb-2ac5-5e2d-b9bd-b0db40e37ae7'::uuid, NULL, E'The corporation did not work well and gained no profits.', NULL, NULL, NULL),
  ('e9580d8d-cb61-5eb0-affd-0d828cf54c6c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e9580d8d-cb61-5eb0-affd-0d828cf54c6c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'acddc95f-571e-5588-a117-52a1b9346ef8'::uuid, NULL, NULL, E'These regions were both areas of economic development.', NULL, NULL),
  ('e95e956c-1963-5e4a-bb43-d290e7e29727'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'e95e956c-1963-5e4a-bb43-d290e7e29727'::uuid, 1, NULL, TRUE, 0, NULL, E'Current Developments in Management Practices', E'Although many of the principles described by twentieth century management researchers are still in use, they are being {{1}} in widely different ways. Building on the {{2}} in technology and social psychology, management theory has become more {{3}} to meet the continually {{4}} challenges organizations face by operating in a global economy.', NULL, NULL, NULL, E'1.applied, 2.advances, 3.specialized, 4.arising', NULL, NULL),
  ('e9632fc0-c986-5f79-9340-023594ee980c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e9632fc0-c986-5f79-9340-023594ee980c'::uuid, 1, NULL, TRUE, 0, NULL, E'Photography', NULL, '51ae5769-2026-5c91-a31b-f5aa5df11fc6'::uuid, NULL, E'It is almost impossible these days not to include photography in a course on the history of art. I disagree with people such as Walter Benjamin who suggest that technology and an don''t go well together. Photography, with its realism, its accurate representation of the thing in front of you, initially deprived many artists of their subject matter, forcing them to look in new ways - no bad thing. True, mass produced images of, say, the Mona Lisa, obviously can''t provide the same experience as seeing the real painting. On the other hand, there are photographs which, to my mind, are far more thought-provoking and have greater emotional impact than a painting of the same subject could.\nSome people say that the traditional idea of an artist with a trained hand and eye is old-fashioned. They no longer believe that an artist needs specialist knowledge, but rather that he or she can simply point a camera at a scene and recordit. However, on the one hand, that ignores the creative skill involved in producing photographs. On the other hand, it also ignores the fact that even in the past, painters used various technological aids. For example, the Dutch painter, Vermeer, used a camera obscura to help him create his images. We''ll go into that later, but for now, I want to look at the documentary and cultural value of photography.', NULL, NULL, NULL),
  ('e9667b5f-95dd-51d0-941d-c84e9e3a8d10'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'e9667b5f-95dd-51d0-941d-c84e9e3a8d10'::uuid, 1, NULL, TRUE, 0, NULL, E'Longevity', E'People are living longer and this longevity is good news for sales teams. It results in a much more {{1}} customer base for them to work from. Why we are living longer is not the issue for anyone {{2}} in drawing up plans to market a product. What they focus on is the fact that there are now more age groups to target, which means that a sales pitch can be re-worked a number of times to more exactly fit each one. For example, {{3}} referring simply to ''adults'', there are now ''starting adults'', ''young adults'' and ''established adults''. {{4}} , markets no longer talk about ''children'', but tend to refer to a fuller range of categories that includes ''kids'', ''tweens'', ''pre-teens'' and ''teenagers''. We now have a very diverse population in terms of age, and that can only be a {{5}} for business.', NULL, NULL, NULL, E'1.precise, 2.involved, 3.rather than, 4.Similarly, 5.bonus', NULL, NULL),
  ('e968c9ac-e344-5074-b3e0-3fcb4b84f663'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e968c9ac-e344-5074-b3e0-3fcb4b84f663'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'fae27199-7d89-5f56-8523-3f0fcac45c97'::uuid, NULL, NULL, E'The department has a higher-than-normal proportion of postgraduate students.', NULL, NULL),
  ('e96d2318-fd05-59f1-8800-c87222bef4f6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e96d2318-fd05-59f1-8800-c87222bef4f6'::uuid, 1, NULL, TRUE, 0, NULL, E'Two Roles of TV', E'Television has two roles: to inform and to entertain people. Explain which of these roles you see as more important. To what extent do you think that TV today performs each of these roles in an effective way? Support your point of view with details from your own experiences, observations or reading.', NULL, NULL, E'While television''s capacity to entertain is undeniable, its fundamental duty to inform the public is ultimately of greater social importance. An informed citizenry is essential for a functioning democracy and a cohesive society. Regrettably, modern television often falls short in fulfilling this critical role effectively.\n\nThe primacy of information lies in its role as a public good. Quality news reporting and documentary programming empower citizens with the knowledge needed to participate in civic life, make informed decisions, and hold power to account. For instance, during emergencies, trustworthy broadcast news remains a vital source of coordinated public guidance. This democratic function is foundational and cannot be replaced by entertainment.\n\nHowever, television''s current effectiveness as an informer is severely compromised. The pursuit of ratings and the 24-hour news cycle have elevated speed and sensationalism over depth and accuracy. Complex issues are reduced to simplified headlines, while the rise of overtly partisan channels frequently blurs the line between reporting and opinion, sowing confusion rather than clarity. Consequently, the medium''s immense power to educate is often squandered.\n\nIn conclusion, despite its shortcomings, television''s informing role remains paramount. While it continues to entertain brilliantly, its drift towards infotainment and biased commentary undermines its democratic potential. For television to truly serve society, a renewed commitment to rigorous, impartial journalism must be prioritized, ensuring it informs as effectively as it entertains.', NULL, 200, 300),
  ('e96fc6b7-5bd5-541a-9336-4c6657338376'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e96fc6b7-5bd5-541a-9336-4c6657338376'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a2104137-6311-5e92-9ea4-132eb2db9391'::uuid, NULL, NULL, E'It is impossible to predict what the eventual outcome will be.', NULL, NULL),
  ('e97af2d3-fe97-5b7b-967c-af90ed663611'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e97af2d3-fe97-5b7b-967c-af90ed663611'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a group of lines that form a unit in a poem?', '4f6bcee7-a1a1-5c33-a608-b83838a84a94'::uuid, NULL, NULL, E'Verse', NULL, NULL),
