  ('e9c479e0-98f9-55e8-9c1c-efbe4467f3dc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e9c479e0-98f9-55e8-9c1c-efbe4467f3dc'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5c28c664-5bd1-5d60-b644-4bbcd852d9e0'::uuid, NULL, E'Stretching exercises can help you avoid injury and improve your performance.', NULL, NULL, NULL),
  ('e9c95e04-0ed0-567b-a138-d44c9fa01266'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'e9c95e04-0ed0-567b-a138-d44c9fa01266'::uuid, 1, NULL, TRUE, 0, NULL, E'Autism Diagnoses', E'The first two years of a baby’s life are critical for brain development. In this study, parents were given video-based tips on how best to interact with their babies according to their particular needs. By the age of three, the baby still had some developmental difficulties, but their social skills had improved, and two thirds fewer met the criteria for a diagnosis of autism spectrum disorder, compared to babies who received standard care. The research charity Autistica said the study was promising and people should not have to wait for a diagnosis for support to be provided. But the National Autistic Society said autism was not a disease that should be cured or lessened. The research team says longer term studies on more babies using the technique are now needed.\n\nWhat is the attitude of the research charity Autistica with regard to their finding?', '0c7dfad5-475f-5cdf-8002-6df12b196f9f'::uuid, NULL, NULL, E'Expectant.', NULL, NULL),
  ('e9d65da2-eb25-57ad-8100-6eeea555e6c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'e9d65da2-eb25-57ad-8100-6eeea555e6c4'::uuid, 1, NULL, TRUE, 0, NULL, E'Bugs', NULL, NULL, NULL, NULL, E'2, 1, 3, 4', NULL, NULL),
