  ('e9e5d260-79b0-50ea-9c28-16b21e0ec7e3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'e9e5d260-79b0-50ea-9c28-16b21e0ec7e3'::uuid, 1, NULL, TRUE, 0, NULL, E'Urbanization and Unemployment', E'The only effective way to deal with unemployment is to introduce rapid urbanization. To what extent do you agree with it?', NULL, NULL, NULL, NULL, 200, 300),
  ('e9ecced9-bdd2-5407-ada2-84e4d8bfbdf0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e9ecced9-bdd2-5407-ada2-84e4d8bfbdf0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '79947cb4-f956-5201-a272-32170976db26'::uuid, NULL, E'There are numerous effective methods available for various purposes and needs.', NULL, NULL, NULL),
  ('e9fb8918-aaa8-58ea-939b-4e2555f4300f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'e9fb8918-aaa8-58ea-939b-4e2555f4300f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '36a22e25-9507-5da8-8644-4aa33610dd86'::uuid, NULL, E'It''s a difficult one. If you start prohibiting some research, where do you draw the line?', NULL, NULL, NULL),
  ('ea0030ac-6d17-5577-bdd6-7c7ec279a1d4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ea0030ac-6d17-5577-bdd6-7c7ec279a1d4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4da5b8b7-02ce-5af8-978f-b32ad58568c8'::uuid, NULL, NULL, E'Assignments should be submitted to the department office before the deadline.', NULL, NULL),
  ('ea02155f-125d-5dc9-888e-ac92be7883bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ea02155f-125d-5dc9-888e-ac92be7883bd'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the extra performance that actors give?', '67950668-a048-579d-8880-5f20cfe0b6b3'::uuid, NULL, NULL, E'Encore', NULL, NULL),
  ('ea030528-fd24-5ad6-83ad-25895c0fa92e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ea030528-fd24-5ad6-83ad-25895c0fa92e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for a society''s customs, arts, and social institutions?', 'f1333027-b9ed-5533-83b2-16c3397f1f52'::uuid, NULL, NULL, E'Culture', NULL, NULL),
  ('ea0440c7-25b4-594b-bd6d-f90b3eaf0b7d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ea0440c7-25b4-594b-bd6d-f90b3eaf0b7d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '996b3e43-fe9e-5b66-96a9-7789b6ffbf09'::uuid, NULL, E'Some experts argue that watching television can be very educational while others disagree.', NULL, NULL, NULL),
  ('ea083625-dece-5e59-b1be-9322dcee3c06'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ea083625-dece-5e59-b1be-9322dcee3c06'::uuid, 1, NULL, TRUE, 0, NULL, E'Theme Parks', E'Not all theme parks succeed when they are built. Some theme parks may start, but close in the first few days due to declining business, poor management or an inability to respond to market changes. Closure of theme park happens even at popular ones if visitors are disappointed with their inconsistent service quality or unchanged aging attractions.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ea09ecf4-e1ce-5f26-94aa-96374864914e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ea09ecf4-e1ce-5f26-94aa-96374864914e'::uuid, 1, NULL, TRUE, 0, NULL, E'The 1950''s', NULL, 'edb4e279-600a-581a-a430-141a72edc5ce'::uuid, NULL, E'Now let''s focus on comics in the 1950''s. Early in the decade sales were down, so publishers started looking for some new angle to get their readers interested again. They found what they were looking for with horror comics, stories about ghosts and demons that were often graphically violent. Before long, most of the major publishers were printing horror comics, but it all came to an end a few years later. You see, there was a psychologist named Frederic Wertham who claimed that comic books, the horror books in particular, were a bad influence on children and turned them into juvenile delinquents. Wertham even wrote a book called Seduction of the Innocent that showed specific scenes from comics that he thought were a particularly bad influence on kids. Wertham wasn''t the only one down on comics. The United States Senate Subcommittee on Juvenile Delinquency also released a report very critical of comics. The result of all this fuss was the creation of the Comics Code Authority in 1995. This is a self-censoring body created by the publishers. Essentially, for a comic book to be approved by the code, it had to be free of the blood and gore that was usually depicted in most horror comics, and evil could never triumph over good. Children had to be shown that crime did not pay. Well, if comic sales were bad in 1950, things got even worse in 1955. Many small publishers actually went out of business. But the industry rebounded by introducing a new lineup of superheroes, characters like Spider-Man and the Fantastic Four. Now, I''ve brought with me today some comic books from this era to pass around. They''re from my own personal collection, so please be extra careful when handling them.', NULL, NULL, NULL),
  ('ea11aff7-2dfc-5509-9c8a-881e5171fe28'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ea11aff7-2dfc-5509-9c8a-881e5171fe28'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'bdb647a6-6507-534f-8e02-44d5a169ca51'::uuid, NULL, NULL, E'More people are concerned about social inequality recently.', NULL, NULL),
  ('ea1201e9-8240-5edc-ba0f-17ca24e66244'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ea1201e9-8240-5edc-ba0f-17ca24e66244'::uuid, 1, NULL, TRUE, 0, NULL, E'Falling in Love', NULL, '43686164-3866-5ce6-b68e-e18e0d2131d9'::uuid, NULL, E'When we fall in love, we tend to fall in love with somebody who wouldn''t normally be considered compatible with us, because they''re personality traits are opposite to ours. This allows us to fit together like pieces of a puzzle. This person''s good traits compensate for our bad ones and vice versa. When we look back on it, we often wonder how we could have fallen in love with somebody who was so different from ourselves. But nature intended for us to fall in love, and it made sure we would by having our brains release what we call ''feel-good'' hormones including oxytocin, phenylethylamine, serotonin, and dopamine. These hormones give aid to a biochemical process that rids us of stressors and fills us with infatuation. This is why it''s so hard for us to recognize our partner''s flaws. These hormones hide our flaws and encourage us to do whatever we can to keep the romance alive. While we aren''t actually lying to our partners, we''re wearing a mask of adoration. Taking off this mask and revealing who we really are may influence our partner to leave, so we keep it on. Knowing this, in order to avoid any major confrontations and confusion With your partner. you can work on bringing up somewhat difficult topics with them. Such as whether or not you both want children or wish to be married.', NULL, NULL, NULL),
  ('ea14be9f-e9dc-577b-8b04-5f6057998d2d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ea14be9f-e9dc-577b-8b04-5f6057998d2d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ec83ba41-1641-5fc0-8b81-61ca6174ce0b'::uuid, NULL, E'When we talk, we use tones and expressions to understand each other.', NULL, NULL, NULL),
