  ('ea1d566f-3a48-5638-9bf8-2dd2904006e2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ea1d566f-3a48-5638-9bf8-2dd2904006e2'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '33ffb678-ac12-5aff-b4fb-2d399144769d'::uuid, NULL, E'The geography assignments must be submitted by midday on Friday.', NULL, NULL, NULL),
  ('ea1d79db-74fe-51c7-9ead-9713047b3d38'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ea1d79db-74fe-51c7-9ead-9713047b3d38'::uuid, 1, NULL, TRUE, 0, NULL, E'Paraphrasing', E'Paraphrasing is likely the most common way you will {{1}} your source information. Quoting should be minimal in most research papers. Paraphrasing can be tricky, however. You really have to make changes to the wording. Changing a few words here and there doesn’t {{2}} as a paraphrase, and including exact phrases from the source without putting them in quotation marks can get you into trouble with {{3}} .', NULL, NULL, NULL, E'1.integrate, 2.count, 3.plagiarism', NULL, NULL),
  ('ea1f9810-37ea-5c61-98f4-0bf095a8195d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ea1f9810-37ea-5c61-98f4-0bf095a8195d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a4d40d67-c303-540a-a87c-78c45a35a151'::uuid, NULL, E'To improve the essay, I decided to include more direct quotes.', NULL, NULL, NULL),
  ('ea3f86c6-b1ad-521d-9700-75422edd2b91'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ea3f86c6-b1ad-521d-9700-75422edd2b91'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b45be8d9-7c6e-53c7-8031-4c3e286f9888'::uuid, NULL, NULL, E'Heavy rain will fall across the city next week.', NULL, NULL),
  ('ea41f445-3195-5cf7-b73f-1d3fecf8089b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ea41f445-3195-5cf7-b73f-1d3fecf8089b'::uuid, 1, NULL, TRUE, 0, NULL, E'Capturing Authentic Narratives', NULL, '13cf856b-923f-5858-9e39-8ec1a9843fa6'::uuid, NULL, E'How, as a journalist, do you ask the questions that yield this type of narrative? You have to know what to ask of whom. First you need to understand that every piece of journalism requires a trifecta of sourcing. If you picture the reporting process as depicted by a triangle, one side will be official sources, another side will be overview sources, and a third side will be unofficial sources. All three components are necessary in every well-reported piece. The first side has official sources. Those are the people with titles and expertise, who own the company; are spokespeople for the movement. They tell you the numbers, and the answers to how much, how many, where, when, and who. A second side of the triangle includes overview sources: academics, consultants, authors, who are not directly connected as stakeholders, but have knowledge of the big picture. Yet it is the third side of the trifecta – unofficial sources – who hold the power of the individual’s insight. This is where you can find the why, giving consequence on the event, trend, phase, or idea and what it means on a soul level to someone affected by it. So how do you mine for the gems, identifying what is compelling from what is chatter? You ask surprising questions. To achieve the complicated, fragile human connection, you regard the stories of every subject as sacred. Realize that an anecdote is oxygen that breathes life into a grey story of exposition, facts and data.', NULL, NULL, NULL),
  ('ea42f312-e78b-555d-af0c-5cb69d3235ba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ea42f312-e78b-555d-af0c-5cb69d3235ba'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ae0194bc-00e2-54f1-881a-d8d1b16712e4'::uuid, NULL, E'He came across this story while he was searching local news articles.', NULL, NULL, NULL),
