  ('ea471b33-06d0-54b8-8d9d-842990e1582d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ea471b33-06d0-54b8-8d9d-842990e1582d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2a4a0a5b-cd68-5b30-83de-c32ec7aa96aa'::uuid, NULL, E'Author and subject indexes are available on a library database.', NULL, NULL, NULL),
  ('ea498c28-ea6b-5d17-85a0-90d05c7be69d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ea498c28-ea6b-5d17-85a0-90d05c7be69d'::uuid, 1, NULL, TRUE, 0, NULL, E'Cultural Geography', E'Cultural geography is a subfield of human geography that explores the patterns and interactions of human culture in {{1}} to the natural environment and the human organization of space. It {{2}} a wide range of topics, such as identity, ideology, power, meaning, values, colonialism, post-colonialism, postmodernism, gender, sexuality, race, ethnicity, media, language, and more. Cultural geography also {{3}} various theoretical traditions, such as Marxism, feminism, post-structuralism, psychoanalysis, and non-representational theory. Cultural geography is not a unified or fixed discipline, {{4}} a living tradition of disagreements, passions, commitments, and enthusiasms. It can be seen as a style of thought that seeks to expand and illuminate diverse geographies, both material and non-material, human and non-human, representational and more-than-representational. Some examples of cultural geography include the diffusion of religions and the diffusion of culture via colonialism and imperialism.', NULL, NULL, NULL, E'1.relation, 2.encompasses, 3.draws on, 4.but rather', NULL, NULL),
  ('ea4c7887-ed9d-505e-9173-72402f1f1f79'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ea4c7887-ed9d-505e-9173-72402f1f1f79'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c45c1242-e983-5549-b24c-76a135133ea0'::uuid, NULL, E'It''s important for people to connect to each other.', NULL, NULL, NULL),
