  ('ea6d7c38-6041-537a-a361-b2f750fca93a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ea6d7c38-6041-537a-a361-b2f750fca93a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0203e2b8-c4de-5e42-ad43-1ff447673940'::uuid, NULL, NULL, E'Weather experts can tell what the weather will do later on.', NULL, NULL),
  ('ea7152c8-fe15-577f-b626-ace07d0e2233'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ea7152c8-fe15-577f-b626-ace07d0e2233'::uuid, 1, NULL, TRUE, 0, NULL, E'Small Languages', NULL, '9cb6bd18-e2c6-52cb-acee-e341b79a1904'::uuid, NULL, E'Minor languages are disappearing at a rate that has never been seen before in history.\nThe main reasons for the minor language extinction is globalization and urbanization.\nPeople in rural areas trend to move to urban areas.\nThe stress of life in big cities makes people who have moved there from the countryside have to be bilingual : to learn to speak the language used by the majority there and only speak their own minor languages as an auxiliary one.\nSo big cities are not good places for minor languages to survive, and mainstream, or dominant languages such as English, have been taking place of many small languages there.\nThus, only people who stay in remote territories preserve their minor languages very well, for example, those who live in isolated islands.\nToday such a linguistic change may cause an ethnic concern, and surrounding culture and tradition more and more controversy has risen.', NULL, NULL, NULL),
