  ('ea8f721f-d739-50f9-a721-bb479760368b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ea8f721f-d739-50f9-a721-bb479760368b'::uuid, 1, NULL, TRUE, 0, NULL, E'Crying Baby', E'Scientists have uncovered the most effective technique to {{1}} a crying baby. An experiment involving 21 infants aged less than 7 months found they were more likely to stop crying and fall asleep when their mother walked with them, compared with when they were held by their mother in a chair or {{2}} in a cot. “This finding makes sense because when most people pick up a crying baby, they rarely just stand still with them, they {{3}} walk around,” says Harriet Hiscock at the Royal Children’s Hospital in Melbourne, Australia. Scientists became interested in how babies respond to motion after studying the “transport response” in other mammals, in which infants become passive and develop slower heart rates when their mothers carry them. To test the effect in people, the team monitored 21 crying babies in Japan and Italy while their mothers tried four methods to {{4}} them: holding their baby while walking, moving them back and forth in a pram or rocking cot, holding them while seated and laying them down in a cot.', NULL, NULL, NULL, E'1.soothe, 2.laid, 3.instinctively, 4.calm', NULL, NULL),
  ('ea8f77d3-e667-5f0a-abb5-3bf4c37c7175'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ea8f77d3-e667-5f0a-abb5-3bf4c37c7175'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6d4bde93-2156-558e-95aa-04f92e5385e7'::uuid, NULL, NULL, E'If anyone faces challenges in the lab, please inform me.', NULL, NULL),
  ('ea91ac43-2123-5833-8095-c2c63e637040'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ea91ac43-2123-5833-8095-c2c63e637040'::uuid, 1, NULL, TRUE, 0, NULL, E'Morris', E'Richard Morris, of the school of accounting at the University of NSW, which requires an entrance score in the top 5 percent of students, says attendance has been a problem since the late 1990s.\n“Sometimes in the lectures we’ve only got about one-third of students {{1}} attending,” he said. “It definitely is a problem. If you don’t turn up to class you’re missing out on the whole {{2}} of the {{3}} : you don’t think a whole lot, you don’t {{4}} in debates with other students - or with your teachers.”\nIt is not all gloom, said Professor John Dearn, a Province-Chancellor at the University of Canberra, who said the Internet was {{5}} the way students access and use information.\n“It is strange that despite all the evidence as to their ineffectiveness, {{6}} lectures seem to persist in our universities.”', NULL, NULL, NULL, E'1.enrolled, 2.richness, 3.experience, 4.engage, 5.transforming, 6.traditional', NULL, NULL),
