  ('ead187ce-04a4-5605-b599-2930a8742d31'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ead187ce-04a4-5605-b599-2930a8742d31'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'cf248fa9-fe6b-5ae3-9a33-88df8dee89a8'::uuid, NULL, E'Today, I''d like to talk a little bit about the other theories that can explain the variations in climate.', NULL, NULL, NULL),
  ('ead3ae7e-c547-5980-9c72-3817e35df78a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ead3ae7e-c547-5980-9c72-3817e35df78a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f2838ecb-3206-5580-b1ec-a18f25645f74'::uuid, NULL, NULL, E'You will work as part of a team for this project.', NULL, NULL),
  ('ead42c28-8981-5593-a8e9-6579241e711a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ead42c28-8981-5593-a8e9-6579241e711a'::uuid, 1, NULL, TRUE, 0, NULL, E'Communication Tip', E'I try only to say three important things when I talk to people. No more than three. If it''s one thing that''s maybe even better, but usually there''s a lot to say. When I make notes on what I want to talk about, if I see I''m going on past three to four and five I start eliminating them or seeing if I can fold them into the other things. Because three things are really all I can remember and I don''t work from notes when I talk to people and I advise other people not to. I never read it because reading just excommunicates you; it’s not communication it’s excommunication, in my view. So I can''t remember more than three things, and I don’t think they can remember more than three things, so what’s the point of telling them stuff they’re not going to remember? So I stick to...\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '7d63ec3a-486f-55ce-af2f-3bf9b5f0e023'::uuid, NULL, NULL, E'three', NULL, NULL),
  ('ead447a4-9f99-5972-b003-2cbbf4bdd242'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ead447a4-9f99-5972-b003-2cbbf4bdd242'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f9f7fdc7-1625-5e4b-bc98-3ca8bcf4763b'::uuid, NULL, E'The business world is constantly evolving, and staying up-to-date is essential.', NULL, NULL, NULL),
  ('eae25894-ba90-53b7-8b1a-68d040a3a862'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'eae25894-ba90-53b7-8b1a-68d040a3a862'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '48b62b25-dd86-57b3-8479-ba5d91191150'::uuid, NULL, NULL, E'Make sure you bring everything you need with you.', NULL, NULL),
  ('eaeeac72-cbc0-551b-937d-78da653f5a6a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'eaeeac72-cbc0-551b-937d-78da653f5a6a'::uuid, 1, NULL, TRUE, 0, NULL, E'Medical Cable Assemblies', E'Medical cable assemblies are, in short, the organization of these cables as well as the protection of these cables from the elements. There are a few different types of medical cable assemblies that tackle different functions.\nFirst up, we have equipment and sub-interfaces. These are medical cable assemblies that are typically installed by the original equipment manufacturer. These are not parts that ware and are expected to be replaced every so often. There are two situations when you would work on this kind of equipment. The first is when you’re upgrading the system to a more modern unit. The second is when you’re replacing the system entirely.\nCommunication interfaces are another type of medical cable assembly. These are the cables that deal with the transmission of medical data from one piece of equipment to the other. As you can imagine, it is of utmost importance that the data is transferred accurately and quickly. This will ensure that the patient receives speedy and accurate service.\nLast but not least, we have patient and staff interfaces. This refers to the medical cabling that powers all of the equipment that the patient and/or medical staff actually interfaces with. This could include custom medical cables for surgical equipment, laboratory instruments, and the like.\nMedical cable assemblies, while they may not be the most obvious thing to stick out in a hospital or clinic, are nonetheless hugely important to the overall mission of the medical establishment.', NULL, NULL, NULL, NULL, 5, 75),
  ('eaf03c8c-c707-5b78-b95b-01959c740a96'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'eaf03c8c-c707-5b78-b95b-01959c740a96'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2d4235d9-5c58-58fb-8975-db49aad84e3e'::uuid, NULL, NULL, E'If the government helps, solar energy could become more widely used.', NULL, NULL),
