  ('eb0d53f1-7fe3-590c-a07f-36d7dbb4d3a2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'eb0d53f1-7fe3-590c-a07f-36d7dbb4d3a2'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you get if you successfully complete a university course?', 'd1fe631f-0e64-5b0a-9abb-7f81fd47bd28'::uuid, NULL, NULL, E'Diploma', NULL, NULL),
