  ('eb2bc73b-84c7-5c38-8edd-ca12c6a33f0e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'eb2bc73b-84c7-5c38-8edd-ca12c6a33f0e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call the front face of a building, especially an imposing or decorative one?', 'a666d12e-9e1b-53fe-a9de-f47942cac9f0'::uuid, NULL, NULL, E'Facade', NULL, NULL),
