  ('eb2d7d1e-c6a7-5b16-9352-4ef52ead34cd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'eb2d7d1e-c6a7-5b16-9352-4ef52ead34cd'::uuid, 1, NULL, TRUE, 0, NULL, E'Domestic Cats', E'Domestic cats that are largely indoor hunt less than outdoor cats because they don’t have access to mice. In the wild, feral kittens are taught how to kill prey by their mothers. Domestic cats often fail to learn this skill, which is why you will see them "playing" with anything they catch, or they may bring the mouse to you to kill.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('eb345413-99d6-598a-a292-329521a48246'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'eb345413-99d6-598a-a292-329521a48246'::uuid, 1, NULL, TRUE, 0, NULL, E'Supernova', E'The term supernova was coined in the 1930s by a memorably odd astrophysicist named Fritz Zwicky. Born in Bulgaria and raised in Switzerland, Zwicky came to the California Institute of Technology in the 1920s and there as once distinguished himself by his abrasive personality and erratic talents. He didn’t seem to be outstandingly bright, and many of his colleagues considered him little more than “an irritating buffoon”.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('eb396c74-de08-5668-8689-e7943adf3294'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'eb396c74-de08-5668-8689-e7943adf3294'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the rough written version of a letter, book, or speech?', '5aca8c82-0a5b-54db-a206-0956dec5681a'::uuid, NULL, NULL, E'Draft / manuscript', NULL, NULL),
