  ('eb92e475-3ad2-5336-a4db-d9e15b85e82b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'eb92e475-3ad2-5336-a4db-d9e15b85e82b'::uuid, 1, NULL, TRUE, 0, NULL, E'Cell', E'Cells are now {{1}} as a unifying concept. A cell is the smallest {{2}} of structure and function. Thus, cells are the basic building blocks of all organisms. Cells vary in size. With few exceptions, individual cells are {{3}} small they cannot be seen unaided. In 1665, a British scientist named Robert Hooke observed cells for the {{4}} time using a microscope. A microscope is an instrument that magnifies an object. Most images of cells are taken with a microscope and are called micrographs.', NULL, NULL, NULL, E'1.acceptable, 2.unit, 3.so, 4.first', NULL, NULL),
  ('eb964282-5a79-5f31-827b-ddfb1f814c1b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'eb964282-5a79-5f31-827b-ddfb1f814c1b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '510b8760-43c0-5d19-844f-a4e2ad71dc59'::uuid, NULL, E'His lecture is always useful and stimulating.', NULL, NULL, NULL),
