  ('ebc4fa4a-55a7-50a7-83f1-bf84eafff8e4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ebc4fa4a-55a7-50a7-83f1-bf84eafff8e4'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Where would you expect to find equipment like microscopes, a Bunsen burner, beaker and petri dish?', '78fb6779-d51c-5e22-ab68-67e23b521b1b'::uuid, NULL, NULL, E'Laboratory / lab', NULL, NULL),
  ('ebc52cf0-b738-58e4-b075-afbd667ab12a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ebc52cf0-b738-58e4-b075-afbd667ab12a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0aac4fe7-512f-51e7-a74d-53a2a7eaaa07'::uuid, NULL, NULL, E'The biology department is respected in research activities.', NULL, NULL),
  ('ebd02e4a-f493-5c1e-accd-e5311ffe8aad'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ebd02e4a-f493-5c1e-accd-e5311ffe8aad'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f1458aca-758c-58c2-acc6-5140e2ea1066'::uuid, NULL, E'You need to get a new photo for your driver''s license.', NULL, NULL, NULL),
  ('ebd4392c-2536-54cb-bfc8-776225abbf43'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'ebd4392c-2536-54cb-bfc8-776225abbf43'::uuid, 1, NULL, TRUE, 0, NULL, E'Wine Industry', E'In 1920, the eighteenth Amendment to the United States Constitution created yet another setback for the American wine industry. The National Prohibition Act, also known as the Volstead Act, prohibited the manufacture, sale, transportation, importation, delivery, or possession of intoxicating liquors for beverage purposes. Prohibition, which continued for thirteen years, nearly destroyed what had become a thriving and national industry. One of the loopholes in the Volstead Act allowed for the manufacture and sale of sacramental wine, medicinal wines for sale by pharmacists with a doctor''s prescription, and medicinal wine tonics (fortified wines) sold without prescription. Perhaps more important, prohibition allowed anyone to produce up to two hundred gallons yearly of fruit juice or cider. The fruit juice, which was sometimes made into concentrate, was ideal for making wine. People would buy grape concentrate from California and have it shipped to the East Coast. The top of the container was stamped in big bold letters: caution: do not add sugar or yeast or else fermentation will take place! Some of this yield found its way to bootleggers throughout America who did just that. But not for long, because the government stepped in and banned the sale of grape juice, preventing illegal wine production. Vineyards stopped being planted, and the American wine industry came to a halt.', NULL, NULL, E'While the National Prohibition Act prohibited the manufacture, sale, transportation, importation, delivery, or possession of intoxicating liquors for beverage purposes, Americans still found a loophole that they could make wine from fruit juice or cider, but this was banned by the government eventually, with the American wine industry coming to a halt.', NULL, 5, 75),
  ('ebd79765-7d2e-52d7-b20f-3ad8001932a9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ebd79765-7d2e-52d7-b20f-3ad8001932a9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '92f267ca-bc2b-5f0e-9a97-092154fc2ecf'::uuid, NULL, E'The government must deal with this issue as a matter of urgency.', NULL, NULL, NULL),
  ('ebd91ae6-9a8f-538e-9306-6eb72dff94fa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ebd91ae6-9a8f-538e-9306-6eb72dff94fa'::uuid, 1, NULL, TRUE, 0, NULL, E'Higher Protein Diet', E'Our studies, suggested that those people on a higher protein diet lost the same amount of weight as those on a higher carbohydrate diet, since the two diets offered an {{1}} amount of kilojoules and the same amount of fat. However, body composition (that is, the ratio of fat to muscle) {{2}} greater improvement among those people on the higher protein diet. When the participants in our studies were allowed to eat until they were no longer hungry, those on the higher protein diet lost more weight than those on the higher carbohydrate diet, even after more than a year.\nThe reduction in hunger and the beneficial effect on muscle supplied by the higher protein diet is mostly related to its protein content. The diet is healthy because its protein comes from lean red meat, fish, chicken and low-fat dairy products, all of which {{3}} good nutrition. A high-protein diet in which the protein comes from protein powders and supplements is unlikely to be healthy, unless the supplements are fortified with vitamins and minerals.', NULL, NULL, NULL, E'1.equal, 2.showed, 3.provide', NULL, NULL),
  ('ebe618d2-746f-5f6a-8867-d7f76a150aad'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'ebe618d2-746f-5f6a-8867-d7f76a150aad'::uuid, 1, NULL, TRUE, 0, NULL, E'Humans and Animals', E'Humans are animals but essentially they are the only rational animals. When a human sees an object they can create the idea of what makes that object unique (a tree). This is called abstraction. Animals merely see the object as a single thing (the tree). Because we can separate the idea of a thing (its concept) from the thing itself, we can combine it in our mind with other things to make new things that don’t exist in the physical world (a tree that talks, combining ‘tree’ and ‘human’). This concept of abstraction is unique to man and is the reason that humans have been able to create such incredible structures and objects that we surround ourselves with in life. A bird can make a nest but unless it is in his nature to build homes with heating, he will never be able to conceive of the idea of combing his home with a heating source. The foundation of this idea is from the philosophical concept that certain things in their essence (their being or existence) is what determines their differentness. Using the same concept we can say that the difference between animals and inanimate objects is sentience (the ability to sense). Only animals have senses (a tree can’t feel the cold, a stone can’t smell the earth). Animals have senses, and humans have senses, therefore humans are animals. But only humans have rationality.', NULL, NULL, NULL, NULL, 5, 75),
  ('ebe6ae4e-bf39-5922-9996-7f79f0d6798b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ebe6ae4e-bf39-5922-9996-7f79f0d6798b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a5d88a2c-f076-53c8-a2b7-9d833b702acf'::uuid, NULL, NULL, E'You should complete the job application form in order to get called for the manager''s position.', NULL, NULL),
  ('ebe83120-ad35-5a19-a895-7cbb045d8874'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ebe83120-ad35-5a19-a895-7cbb045d8874'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c65ef20c-3553-5455-a09c-99082be8f4ae'::uuid, NULL, E'There won''t be any space for me in the car.', NULL, NULL, NULL),
  ('ebe8eae8-b506-5fba-a6b6-1d9fcc940cb0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ebe8eae8-b506-5fba-a6b6-1d9fcc940cb0'::uuid, 1, NULL, TRUE, 0, NULL, E'Microscope', E'When you first examine something under a microscope, say a leaf from a plant, you''re amazed at how much detail there is and it''s detail that you simply cannot see without magnification. And what you can see with the naked eye becomes suddenly huge under the lens.\nHow big everything looks is astonishing but it''s also amazingly intricate. Suddenly it''s as if another world has opened up in front of your eyes and you think, hey, I hadn''t realized that something so small, so tiny, could be so- --.\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '1ebdc3b2-8223-5fc5-b8e9-e822ed499fe3'::uuid, NULL, NULL, E'complex', NULL, NULL),
  ('ebf24388-4239-518b-9d03-c1aff74ad4a5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ebf24388-4239-518b-9d03-c1aff74ad4a5'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd158ab7e-9db3-5e0e-b3b3-0347750d1aba'::uuid, NULL, E'The red car came to a halt just in time to prevent an accident.', NULL, NULL, NULL),
  ('ebf39454-c941-5f77-9414-51f6ea9a3248'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ebf39454-c941-5f77-9414-51f6ea9a3248'::uuid, 1, NULL, TRUE, 0, NULL, E'Radio Burst', E'First discovered in 2007, ''fast radio burst'' continue to defy explanation. These cosmic chirps last for a thousandth of a second. The characteristics of the radio pulses suggested that they came from galaxies billions of light-years away. However, new works points to a much closer origin – flaring stars within our own galaxy.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ebf5995f-98c1-57b3-8649-0ee3dfcf2c0d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ebf5995f-98c1-57b3-8649-0ee3dfcf2c0d'::uuid, 1, NULL, TRUE, 0, NULL, E'Hubble Space Telescope', E'The successor to the Hubble Space Telescope has been delayed yet again and will not now launch until "approximately May 2020”. The James Webb Space Telescope is also in danger of busting the cost cap put on the project by the US Congress. Back in 2011, politicians on Capitol Hill said the observatory should not take more than 8 billion to build and 800 million to operate over five years in orbit.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ebf63f50-e7c0-564f-9c2a-c367a17f5f66'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ebf63f50-e7c0-564f-9c2a-c367a17f5f66'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1762b50c-68c9-5101-b1cf-8cf7a6ca7b89'::uuid, NULL, NULL, E'The new tax policy would help keep down education fees.', NULL, NULL),
  ('ebfc57cf-c707-5df0-9acd-ebbda835b978'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ebfc57cf-c707-5df0-9acd-ebbda835b978'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f659df71-b5c8-5b47-9b07-c567820a14e5'::uuid, NULL, E'Our young people need education and more organized activities.', NULL, NULL, NULL),
  ('ebff68f5-0e6b-5a65-beac-69a6fc61ef70'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ebff68f5-0e6b-5a65-beac-69a6fc61ef70'::uuid, 1, NULL, TRUE, 0, NULL, E'Ecotourism', E'Ecotourism is broadly defined as low impact travel to endangered and often undisturbed locations. It is different from traditional tourism because it allows the traveler to become educated about the areas — both in terms of the physical {{1}} and cultural characteristics, and often provides funds for conservation and benefits the economic development of places that are frequently impoverished. Ecotourism and other forms of {{2}} travel have their origins with the environmental movement of the 1970s. Ecotourism itself did not become {{3}} as a travel concept until the late 1980s. During that time, increasing environmental awareness and a desire to travel to natural locations as opposed to built up tourist locations made ecotourism desirable. Since then, several different organizations {{4}} in ecotourism have developed and many different people have become experts on it.', NULL, NULL, NULL, E'1.landscape, 2.sustainable, 3.prevalent, 4.specializing', NULL, NULL),
  ('ec01596c-6aa6-5038-a55d-93ec4e1fbccb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ec01596c-6aa6-5038-a55d-93ec4e1fbccb'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b99403e5-5d1a-5507-8d78-331d038e6559'::uuid, NULL, E'There will be an open book exam on Monday, the twenty eighth.', NULL, NULL, NULL),
  ('ec02ed86-9f57-57b8-9d7a-9739565b0b08'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ec02ed86-9f57-57b8-9d7a-9739565b0b08'::uuid, 1, NULL, TRUE, 0, NULL, E'Mars Rover', E'The Mars 2020 Perseverance Rover will search for signs of ancient microbial life, which will advance NASA''s quest to explore the past habitability of Mars. The rover has a drill to collect core samples of Martian rock and soil, then store them in sealed tubes for pickup by a future mission that would ferry them back to Earth for detailed analysis. Perseverance will also test technologies to help pave the way for future human exploration of Mars.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ec0537b6-5bf0-5fdb-9c7d-2187dc6c8ea1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'ec0537b6-5bf0-5fdb-9c7d-2187dc6c8ea1'::uuid, 1, NULL, TRUE, 0, NULL, E'Use animals for food', E'It is no longer necessary to use animals for food, clothing or medical research. To what extent do you agree or disagree?', NULL, NULL, E'I firmly agree that the use of animals for food, clothing, and medical research is no longer necessary, given the ethical concerns surrounding animal welfare, the availability of alternative technological advancements, and the environmental impact of animal agriculture and testing. Embracing ethical considerations and technological progress is essential in transitioning towards more sustainable and compassionate practices.\nThe ethical implications of using animals for food, clothing, and research are profound, raising significant concerns about animal welfare. The inherent suffering and exploitation of animals in these industries underscore the need for a shift towards more humane and ethical practices that prioritize the well-being of sentient beings.\nAdvancements in technology have paved the way for alternative methods such as plant-based foods, synthetic materials, and advanced testing techniques that offer viable alternatives to using animals. Furthermore, the environmental impact of animal agriculture and testing cannot be ignored, as these practices contribute to environmental degradation and climate change. Embracing sustainable alternatives not only mitigates environmental harm but also aligns with the ethical values of compassion and respect for all living beings.\nIn conclusion, the time has come to reevaluate our reliance on animals for food, clothing, and medical research in light of ethical considerations, technological advancements, and environmental concerns. By transitioning towards more humane, sustainable, and innovative practices, we can forge a path towards a more compassionate and environmentally conscious future where the well-being of animals, humans, and the planet are prioritized.', NULL, 200, 300),
  ('ec06aebd-d545-5a48-a14c-321a3816c86d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ec06aebd-d545-5a48-a14c-321a3816c86d'::uuid, 1, NULL, TRUE, 0, NULL, E'Fashion Industry', E'In recent years, the fashion industry has seen a {{1}} shift towards sustainability. This change is driven by growing {{2}} about the environmental and social impacts of fast fashion. Fast fashion, characterized by rapid production and disposal of inexpensive clothing, has led to issues like textile waste and exploitation of labor. One of the most promising {{3}} in sustainable fashion is the use of recycled materials. Brands are increasingly using recycled fabrics, such as PET bottles turned into polyester, to create stylish and eco-friendly clothing. Additionally, sustainable fashion emphasizes durable designs and encourages consumers to buy fewer, higher-quality pieces that last longer. However, the transition to sustainable fashion also poses {{4}} . The cost of sustainable materials and ethical production practices can make clothing more expensive, which may limit accessibility. Moreover, there is a need for greater transparency and accountability in the fashion supply chain to ensure that claims of sustainability are not just marketing tactics. In conclusion, the fashion industry''s shift towards sustainability is a {{5}} response to pressing global challenges, but it also requires addressing affordability and transparency issues to create a lasting impact.', NULL, NULL, NULL, E'1.dramatic, 2.awareness, 3.developments, 4.challenges, 5.meaningful', NULL, NULL),
  ('ec0dffa7-c394-5668-94e1-1301582dae03'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ec0dffa7-c394-5668-94e1-1301582dae03'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do police usually use to hold a prisoner’s wrists together?', '86a8e1e9-87c5-5982-a42a-47ea1510361b'::uuid, NULL, NULL, E'handcuffs', NULL, NULL),
  ('ec120b8b-cd54-5d65-a0ca-35509864d5fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ec120b8b-cd54-5d65-a0ca-35509864d5fe'::uuid, 1, NULL, TRUE, 0, NULL, E'Innovation', E'Innovation drives progress by creating new technologies and industries that improve our lives. It is important to support innovation through funding for research and development as well as education in STEM fields (science, technology, engineering, and math). Additionally, promoting innovation can help address global challenges like climate change or public health crises.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ec144eab-8171-5f3a-8062-4c86eb747f7e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ec144eab-8171-5f3a-8062-4c86eb747f7e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f256383d-2a77-5b1d-9004-bc6ba5c90789'::uuid, NULL, NULL, E'She has experienced the highs and lows of her acting career.', NULL, NULL),
