  ('ec1f2038-c33b-5a8e-9777-ad697b9caa0e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ec1f2038-c33b-5a8e-9777-ad697b9caa0e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '50c94752-3668-5cc6-9450-f99bc1555b64'::uuid, NULL, E'It''s important to keep this medicine in the fridge.', NULL, NULL, NULL),
