  ('ec36e6b6-2b0a-5413-aa2c-9bcf863e1935'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ec36e6b6-2b0a-5413-aa2c-9bcf863e1935'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8f4149d0-9c6f-5e47-90e1-60cb299d8a2d'::uuid, NULL, E'He has been awarded a research grant because of his excellent work.', NULL, NULL, NULL),
  ('ec370dcb-424d-5310-b080-dd3b9499802a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ec370dcb-424d-5310-b080-dd3b9499802a'::uuid, 1, NULL, TRUE, 0, NULL, E'Experiments', E'Experiments are designed to {{1}} hypotheses under controlled conditions, where it is relatively easy to measure variables while keeping other factors {{2}} . By ensuring that all other conditions remain stable, researchers can reliably {{3}} cause-and-effect relationships.', NULL, NULL, NULL, E'1.test, 2.constant, 3.identify', NULL, NULL),
  ('ec47e2ff-674f-5dc3-b125-4ac078b59294'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ec47e2ff-674f-5dc3-b125-4ac078b59294'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'c22db70d-32b3-56e5-90e6-891f8e8d40eb'::uuid, NULL, NULL, E'The lecture tomorrow will discuss the educational policy of the United States.', NULL, NULL),
  ('ec49136e-b382-58d0-bf3e-a3a73e73d460'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'ec49136e-b382-58d0-bf3e-a3a73e73d460'::uuid, 1, NULL, TRUE, 0, NULL, E'School Advertisements', E'Some people think placing advertisements in school is a great resource for public schools that need additional funding, but others think it exploits children by treating them as a captive audience for corporate sponsors. Choose which position you most agree with and discuss why you choose that position. Support your point of view with details from your own experiences, observations or reading.', NULL, NULL, NULL, NULL, 200, 300),
  ('ec4a29e7-c7c7-51d7-ae63-7adf61ca5af7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ec4a29e7-c7c7-51d7-ae63-7adf61ca5af7'::uuid, 1, NULL, TRUE, 0, NULL, E'Ocean Warming', E'Increasing concentrations of greenhouse gases in the atmosphere from human activity traps heat within the climate system, warming air, the land surface, the oceans, and melting polar ice. Oceans do by far the most work, absorbing more than 90 per cent of the excess human-generated heat accumulated in the Earth''s climate system, moderating atmospheric temperature rises.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ec4d18fa-c4d8-541e-b8f9-c73266e03cc6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ec4d18fa-c4d8-541e-b8f9-c73266e03cc6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'afa79bdd-8819-5860-a2ef-13c7e206c362'::uuid, NULL, E'When you have finished typing, remember to save your document.', NULL, NULL, NULL),
  ('ec51178d-fc7b-56a3-8106-3cea446006a9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ec51178d-fc7b-56a3-8106-3cea446006a9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'fc9b45d0-5c84-5248-88a0-0428debfc4be'::uuid, NULL, NULL, E'You must satisfy the qualifications to get a work permit.', NULL, NULL),
  ('ec545e15-cf23-5243-b872-7f852d664ba7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ec545e15-cf23-5243-b872-7f852d664ba7'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Would fresh milk last longer in a fridge or in a cool cupboard?', '35d439cd-f650-536b-925f-bc679ecc0c9c'::uuid, NULL, NULL, E'A fridge', NULL, NULL),
  ('ec59a2cd-a31d-5030-ba2c-bd8682606d44'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ec59a2cd-a31d-5030-ba2c-bd8682606d44'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b77a0c12-841c-5c3a-9601-e54670242400'::uuid, NULL, NULL, E'All students are expected to participate in all class activities.', NULL, NULL),
  ('ec61e3f8-1b16-57d0-ab9d-918f58c6be5c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ec61e3f8-1b16-57d0-ab9d-918f58c6be5c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '50545c23-a828-52ac-8588-fa0a5095f228'::uuid, NULL, NULL, E'A good assistant always makes sure to clarify all the details.', NULL, NULL),
  ('ec68b3de-02d0-5b5c-975b-80fe50cb8465'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'ec68b3de-02d0-5b5c-975b-80fe50cb8465'::uuid, 1, NULL, TRUE, 0, NULL, E'Modified Food', E'Do you agree that genetically modified foods are safe for consumption?', NULL, NULL, E'Through advancements in genetic engineering, genetically modified (GM) foods offer numerous benefits, including enhanced nutritional value, pest and disease resistance, and increased crop yields. These advancements have the potential to address global food security challenges and contribute to sustainable agriculture practices.\nGenetically modified foods can be tailored to have increased nutritional content, effectively addressing deficiencies in certain vitamins and minerals. By enhancing the nutritional profile of crops through genetic modifications, GM foods have the potential to provide essential nutrients that may be lacking in traditional varieties, thereby improving the overall health and well-being of consumers.\nGM crops can be engineered to resist pests and diseases, reducing the reliance on chemical pesticides and promoting sustainable agricultural practices. By incorporating genetic modifications that confer resistance to common pests and diseases, farmers can reduce the use of harmful chemicals, minimize environmental impact, and ensure a more resilient and productive crop yield.\nIn conclusion, the safety and benefits of genetically modified foods are evident through their enhanced nutritional value, pest and disease resistance, and increased crop yields. As technology continues to advance, genetically modified foods play a crucial role in addressing global food security challenges and promoting sustainable agriculture practices. Embracing the potential of genetically modified foods can lead to a more resilient and efficient food production system, ensuring a safe and sustainable food supply for current and future generations.', NULL, 200, 300),
  ('ec6ba039-ac16-52fc-b2ed-13bb386a6ce5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ec6ba039-ac16-52fc-b2ed-13bb386a6ce5'::uuid, 1, NULL, TRUE, 0, NULL, E'Water Consumption', E'The growing population makes the city''s water {{1}} rise rapidly. To address this, we must improve water resource {{2}} and management. In rich countries, water consumption has gradually slowed because of higher prices, modern technologies, and recycling systems. Governments and companies also conserve water through strategic {{3}} that encourage sustainable use.', NULL, NULL, NULL, E'1.consumption, 2.efficiency, 3.plans', NULL, NULL),
  ('ec6ed2f1-d330-5b89-b0ca-08bc342aa164'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ec6ed2f1-d330-5b89-b0ca-08bc342aa164'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1ca93c1f-d1dd-5410-890a-63caab6e498e'::uuid, NULL, NULL, E'The farmers need to adapt to the changes in the climate.', NULL, NULL),
  ('ec6f98d6-2f7c-5825-8b16-1390d2280784'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ec6f98d6-2f7c-5825-8b16-1390d2280784'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Where will you go when a crime happen to you?', '83621bf9-cf65-5c16-bb79-c5116666680e'::uuid, NULL, NULL, E'Police station', NULL, NULL),
  ('ec7bba52-4ed1-54ba-b4a5-7f784e29e487'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'ec7bba52-4ed1-54ba-b4a5-7f784e29e487'::uuid, 1, NULL, TRUE, 0, NULL, E'Krill', NULL, NULL, NULL, NULL, E'2, 4, 3, 1', NULL, NULL),
  ('ec7f5f22-6e78-5a9a-b0a4-c1e6ee2813e3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ec7f5f22-6e78-5a9a-b0a4-c1e6ee2813e3'::uuid, 1, NULL, TRUE, 0, NULL, E'Immune System', NULL, 'e43dd3f1-2d29-5a7d-99f5-7180bfb83e8e'::uuid, NULL, E'All organisms on earth are made from the same basic part, mostly proteins. Proteins are the building blocks of life and can have billions of different shapes – you can imagine them as 3D puzzle pieces. There are billions of different puzzle pieces your enemies can use to construct their bodies. Why is this important? Because proteins are in a way the “language” of the micro-world. Cells don’t have eyes or ears, so to tell friend from foe, they have to touch them and recognize if their protein is part of a friend or part of an enemy. Recognizing means that cells have countless tiny devices called receptors, that are able to connect with a specific protein puzzle piece. So your cells have tiny puzzle pieces on their outsides that are able to click together, or recognize other protein puzzle pieces. When a cell connects together with a protein and recognizes it as “enemy”, it knows that it has to attack. Only if your cells can make this distinction between friend or foe is your immune system able to fight an invader. But since there are billions of possible protein puzzle pieces, this means there are billions of possible enemy puzzle pieces. This is also one of the reasons we still have to deal with diseases like the flu each year, the influenza virus mutates very rapidly and so the proteins that make up its hull constantly change a tiny bit. The soldiers of your innate immune system have a large number of the puzzle pieces for common bacteria and viruses memorized, that’s why they are your all purpose weapons.', NULL, NULL, NULL),
  ('ec841055-f9f1-52ac-ad24-f63dfa864bf7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ec841055-f9f1-52ac-ad24-f63dfa864bf7'::uuid, 1, NULL, TRUE, 0, NULL, E'Public Spaces', E'Globally, about one-third of a city’s land area is covered by public spaces. Despite this significance, the potential of public-space assets to transform cities and improve urban life is often overlooked. The resulting degradation of public spaces into congested, vehicle-dominated, and polluted places often becomes a liability, exacerbating various city problems.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ec8627c7-e409-5df7-a505-4c84dc352e5e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ec8627c7-e409-5df7-a505-4c84dc352e5e'::uuid, 1, NULL, TRUE, 0, NULL, E'Cultural Empathy', NULL, 'e9c55c59-e592-5f1c-9e06-29c876da29ba'::uuid, NULL, E'In this global village, ''Cultural Empathy'' emerges as a beacon of unity amidst our diverse backgrounds. It is the heartfelt understanding that the world is a mosaic of cultures, each piece as significant as the other. Encountering a culture different from our own can be like stepping into a new world. It''s the subtle art of listening and the quiet humility of learning that bridges the gap. When we travel or interact with international students, we''re not just exchanging words; we''re sharing pieces of our heritage. Moreover, cultural empathy extends beyond mere tolerance. It''s about celebration and participation. It''s one thing to acknowledge festivals from around the world; it''s another to dance to the rhythm of foreign melodies and taste the spice of exotic cuisines. This is how we weave the threads of understanding and respect into the fabric of our everyday lives. Let us, as students and future leaders, champion the cause of cultural empathy, for it is the path to a more cohesive, compassionate, and peaceful world.', NULL, NULL, NULL),
  ('ec877a36-f749-5e69-b08b-f846665076e5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ec877a36-f749-5e69-b08b-f846665076e5'::uuid, 1, NULL, TRUE, 0, NULL, E'Locust', E'Fancy a locust for lunch? Probably not, if you live in the west, but elsewhere it is a different story. Edible insects, termites, stick insects, dragonflies, grasshoppers and giant water bugs, are on the menu for an estimated 80 percent of the world'' s population. More than 1000 species of insects are served up around the world. For example, Kungu cakes, made from midges, are a {{1}} in parts of Africa. Mexico is an insect-eating, or entomophagous - hotspot, where more than 200 insect species are consumed. {{2}} is so high that 40 species are now under threat, including white agave worms. These caterpillars of the tequila giant-skipper butterfly {{3}} around $250 a kilogram. Eating insects make nutritional sense. Some contain more protein than meat or fish. The female gypsy moth, for instance, is about 80 percent protein. Insects can be a good {{4}} of vitamins and minerals too: a type of caterpillar (Usta Terpsichore) eaten in Angola is rich in iron, zinc, and thiamine. What do they taste like? Ants have a lemon tang, apparently, whereas giant water bugs taste of mint and fire ant pupae of watermelon. You have probably, inadvertently, already tasted some of these things, as insects are often accidental tourists in other types of food. The US Food and Drug Administration even issues guidelines for the number of insect parts allowed in certain foods. For example, it is acceptable for 225 grams of macaroni to contain up to 225 insect fragments.', NULL, NULL, NULL, E'1.delicacy, 2.Demand, 3.fetch, 4.source', NULL, NULL),
  ('ec8806a9-c247-5537-a3f0-75af0ec88db3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ec8806a9-c247-5537-a3f0-75af0ec88db3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8053883f-6e81-5699-b103-4dbfe2d7c7f8'::uuid, NULL, NULL, E'The economy is now showing the first sign of recovery.', NULL, NULL),
