  ('ed273439-b1c2-502a-8558-6882e1998eb8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ed273439-b1c2-502a-8558-6882e1998eb8'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6e4ba2b4-d8aa-5ba4-8fdb-44eed7b9a567'::uuid, NULL, NULL, E'A large organization can be slow to adapt to change.', NULL, NULL),
