  ('ed2dc20a-db82-5ac4-bdb1-1783abc4ca60'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'ed2dc20a-db82-5ac4-bdb1-1783abc4ca60'::uuid, 1, NULL, TRUE, 0, NULL, E'Global Positioning System', NULL, NULL, NULL, NULL, E'4, 3, 1, 2', NULL, NULL),
  ('ed2dc4f6-fc54-51c9-8f83-9617d629527f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ed2dc4f6-fc54-51c9-8f83-9617d629527f'::uuid, 1, NULL, TRUE, 0, NULL, E'Hierarchy of Needs', E'Abraham Maslow’s hierarchy of needs is a seminal theory in psychology which describes a five-tier model of human needs. At the base are physiological needs like food, water, and sleep. These most basic needs must be {{1}} first before advancing upwards through the hierarchy. The next tier contains safety and security needs, including health, employment, property, and social stability. Higher up is the need for love and belonging, {{2}} friendships, family, and intimate relationships. Near the top lies the need for esteem, which involves prestige, confidence, achievement, and respect from others. At the apex is self-actualization, defined by Maslow as achieving one’s {{3}} potential, including creative activities and peak experiences. While intuitive, Maslow’s hierarchy remains controversial among psychologists. Contemporary research continues {{4}} and testing the hierarchical ordering and boundaries between need levels. Nonetheless, the theory endures as an influential framework for understanding human motivation and development. Specific {{5}} include designing workplace environments, understanding consumer behavior, and developing self-improvement strategies.', NULL, NULL, NULL, E'1.met, 2.encompassing, 3.full, 4.examining, 5.applications', NULL, NULL),
  ('ed36b51c-c264-536b-b4cc-29496a71f1bf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ed36b51c-c264-536b-b4cc-29496a71f1bf'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4b0cf79a-17ac-5deb-9c03-5339a7a22d96'::uuid, NULL, NULL, E'Students have regular meetings with their own tutors for help.', NULL, NULL),
  ('ed3ebd30-e5a7-5fdf-9a04-37d70c209173'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ed3ebd30-e5a7-5fdf-9a04-37d70c209173'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '250eb6db-51e7-5018-98b4-4cfc34574a45'::uuid, NULL, NULL, E'Please confirm your essay topic before the deadline.', NULL, NULL),
