  ('ed485992-0176-56b4-b1af-cecb1b303036'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ed485992-0176-56b4-b1af-cecb1b303036'::uuid, 1, NULL, TRUE, 0, NULL, E'Tourism', E'Tourism is a challenging sector which divides statistics since businesses serve tourists, also serve local people. Therefore, it is not straightforward to estimate how much business sectors'' revenues and how many jobs are due to tourist expenditures.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ed4dbced-910f-5b0c-b19b-dd6f03ff16b7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ed4dbced-910f-5b0c-b19b-dd6f03ff16b7'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6698a5f7-c16b-56fa-9d83-9e4390988018'::uuid, NULL, E'The global population experienced a threefold increase in the last century.', NULL, NULL, NULL),
  ('ed4fad87-0e55-59a4-b0e9-b75a10e377e5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ed4fad87-0e55-59a4-b0e9-b75a10e377e5'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Where do polar bears live?', '176cfbf8-b52b-592d-b0d6-17710853679c'::uuid, NULL, NULL, E'Arctic / north pole', NULL, NULL),
  ('ed51655c-c3c0-5184-a490-b69ed5e165c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ed51655c-c3c0-5184-a490-b69ed5e165c4'::uuid, 1, NULL, TRUE, 0, NULL, E'Vitamin', E'Vitamin, any of several organic substances that are necessary in small quantities for normal health and growth in higher forms of animal life. Vitamins are distinct in several ways from other biologically important {{1}} such as proteins, carbohydrates, and lipids. Although these latter substances also are {{2}} for proper bodily functions, almost all of them can be synthesized by animals in adequate quantities. Vitamins, on the other hand, generally cannot be synthesized in amounts {{3}} to meet bodily needs and therefore must be obtained from the diet or from some synthetic source. For this reason, vitamins are called essential nutrients. Vitamins also differ from the other biological compounds in that relatively small quantities are needed to complete their functions. In general these functions are of a catalytic or regulatory nature, facilitating or controlling vital chemical reactions in the body’s cells. If a vitamin is {{4}} from the diet or is not properly absorbed by the body, a specific deficiency disease may develop.', NULL, NULL, NULL, E'1.compounds, 2.indispensable, 3.sufficient, 4.absent', NULL, NULL),
  ('ed548d40-f5ec-5c35-8d86-518cf1fe6b5b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ed548d40-f5ec-5c35-8d86-518cf1fe6b5b'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8c017829-4026-5ded-871e-0853f5241b9e'::uuid, NULL, NULL, E'Find out how to get your resources before your research.', NULL, NULL),
  ('ed570e72-6f99-51b6-99eb-67f8e920ce7e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'HIGHLIGHT_CORRECT_SUMMARY', E'HIGHLIGHT_CORRECT_SUMMARY', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ed570e72-6f99-51b6-99eb-67f8e920ce7e'::uuid, 1, NULL, TRUE, 0, NULL, E'Anthropology', E'Urn ... how did I get into anthropology? Well, l''m not an anthropologist, not trained in it anyway - in fact I''m a marine biologist - and it''s more that I''m interested in the Strandlopers, the "beach walkers", if you like, than in anthropology generally. In fact, it was through my early interest in all things to do with the sea that I first heard of them. As a kid my favorite pastime was getting down to the beach and mucking about in rock pools and collecting anything the sea tossed up, and, um, the Strandlopers lived off the sea and seashore gathering food such as mussels, oysters, crabs, and so on, just as I did. So when I heard of them I thought, right, this is my kind of thing and I felt a kind of, well, affinity for them.\nAt first people thought they were a myth; I suppose because there didn''t seem to be much evidence for their existence, but now we do have archaeological evidence such as pottery, discarded shells, the bones of seals and large fish, and so on. And those shells, we believe, became their first tools, and in some cases were also used as money and jewellery. Of course, before they had the implements, the, um, tools to hunt and fish, everything had to be caught by hand, so they kept mostly to shallow water. Then they might have used a primitive form of fishing line, perhaps the tendril of a climbing plant or a strip of animal skin with a bone or small piece of wood that would stick in the fish''s throat. Anyway, the more we search the more we discover - most recently, caves on the coast have been discovered with ancient drawings.\nl find it endlessly fascinating.\n\nClick on the paragraph that best relates to the recording.', '34f09e79-4fd9-5df7-88f9-7541653d3fd6'::uuid, NULL, NULL, E'The speaker is a marine biologist who became interested in the Strandlopers, an ancient people who lived on the coastline, because of their and his connection to the sea. Their way of life intrigued him - as a child he had spent a lot of time by the sea, exploring and collecting things - so he began to study them, and discovered some interesting information about their way of life, how they hunted, what tools they used, and so on.', NULL, NULL),
  ('ed5772e6-d222-517f-b1cd-6592d0bda945'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ed5772e6-d222-517f-b1cd-6592d0bda945'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ffe72759-2c11-5d37-be7b-97f05ae96286'::uuid, NULL, E'To understand its entity, we need to go back to its origin.', NULL, NULL, NULL),
  ('ed57dc67-e1e8-55c0-9acd-dbc9bc85e63e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'ed57dc67-e1e8-55c0-9acd-dbc9bc85e63e'::uuid, 1, NULL, TRUE, 0, NULL, E'Christ Church', E'It is a curious tradition that the clock on the tower of Christ Church Cathedral in Oxford is always five minutes later than standard British time.\nThe explanation for this lies in the conservative nature of the Cathedral''s clergy. It was only when the railways arrived in the middle of the nineteenth century that it became important for clocks throughout the country to be synchronized, however difficult this might be. When the Cathedral was asked to come into line, the clergy discussed the request but decided that this was an idea that needed to prove its worth before being adopted.\n\nWhy does Christ Church Cathedral clock give a different time from other British churches?', NULL, NULL, NULL, E'Cathedral staff were reluctant to act too quickly.', NULL, NULL),
  ('ed59388f-cb6d-55f5-a379-26b3c0f75a09'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ed59388f-cb6d-55f5-a379-26b3c0f75a09'::uuid, 1, NULL, TRUE, 0, NULL, E'Engineering', E'Engineering requires many building blocks and tools. To produce real world results, one must practically apply mathematics and sciences to tangible problems and scenarios. Included in this category are the various technical topics which cut across engineering disciplines, encompassing many branches of mathematics and scientific disciplines.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ed6109ec-7d2e-5324-bcd7-7c3874fa1f17'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ed6109ec-7d2e-5324-bcd7-7c3874fa1f17'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4cbf3e55-2434-5b50-855d-b4bf950a33b6'::uuid, NULL, NULL, E'You can request library books by using the electronic catalogue.', NULL, NULL),
