  ('ed8980cf-b2b5-5fcc-90df-717e241bdd69'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ed8980cf-b2b5-5fcc-90df-717e241bdd69'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f3855e18-7e0e-54b0-9b95-0cfe903768ce'::uuid, NULL, E'Persist through life''s obstacles; don''t give up when challenges emerge.', NULL, NULL, NULL),
  ('ed89b30f-cc71-5078-8a01-a7546aa11a55'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ed89b30f-cc71-5078-8a01-a7546aa11a55'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What clothing do people wear, such as students or nurses, to show that they belong to the same organizations?', 'cf2eed43-da17-5c16-89d1-108863a0af1c'::uuid, NULL, NULL, E'Uniform', NULL, NULL),
  ('ed8b7472-3307-5792-8a3f-4571fbaa63f3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ed8b7472-3307-5792-8a3f-4571fbaa63f3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '58e78d37-ee58-5ee6-8298-2fe041b026af'::uuid, NULL, NULL, E'The party room was decorated in vibrant blues and greens.', NULL, NULL),
  ('ed915cfd-ee70-51db-b8ed-9dfb9dcd475c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ed915cfd-ee70-51db-b8ed-9dfb9dcd475c'::uuid, 1, NULL, TRUE, 0, NULL, E'Left-handed Population', E'In any given population, about ten percent of the people are left-handed and this figure remains {{1}} stable over time. So-called “handedness” runs in families, but what causes it and why the proportion of left-handed to right-handed people is a constant are still a mystery. One thing we do know is that hand {{2}} is related to brain asymmetry; and it seems to be generally agreed that the human brain is profoundly asymmetric, and that understanding how this works will tell us much about who we are and how our brains work. Brain (function) is {{3}} into the left and right hemispheres, and this is crucial for understanding language, thought, memory, and perhaps even creativity. For right-handed people, language activity is mainly on the left side. Many left-handers also have left-side language dominance, but a significant number may have language either more {{4}} distributed in both hemispheres or else predominantly on the right side of the brain. Because left-handedness is seen as a key to the complex anatomy of the brain, scientists are searching for links to other {{5}} , including immune disorders, learning disabilities, and reduced life expectancy.', NULL, NULL, NULL, E'1.relatively, 2.dominance, 3.distributed, 4.evenly, 5.conditions', NULL, NULL),
  ('ed9e22a9-0e83-56b9-8106-dfe12933a4f5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ed9e22a9-0e83-56b9-8106-dfe12933a4f5'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '7a8f94ea-e429-5fde-a362-4d97e7b22c7b'::uuid, NULL, E'Jonathan is often late when he goes to different places or events.', NULL, NULL, NULL),
  ('eda4d6f3-0d0d-569f-80b3-d14ff5d9b787'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'eda4d6f3-0d0d-569f-80b3-d14ff5d9b787'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1680344c-2c30-5344-984a-2e76ea6a72e4'::uuid, NULL, NULL, E'I have received an encouraging response to my last advertisement.', NULL, NULL),
  ('eda57728-0298-5d15-a5b7-8fabbb8fa0ef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'eda57728-0298-5d15-a5b7-8fabbb8fa0ef'::uuid, 1, NULL, TRUE, 0, NULL, E'Wrist Watch', E'The wrist watch works by {{1}} information such as a person''s pulse or movement. When it {{2}} a change in a person''s health, the watch sends information to a touchscreen hub {{3}} in the home. The hub then {{4}} pre-determined contacts and calls for help immediately.', NULL, NULL, NULL, E'1.tracking, 2.detects, 3.located, 4.alerts', NULL, NULL),
  ('edab3788-e7eb-50c0-b3cd-ef5a00e14ab5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'edab3788-e7eb-50c0-b3cd-ef5a00e14ab5'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e2b36c05-6972-52da-92f8-ed9507ef4140'::uuid, NULL, E'Consumers generally trust friends more than commercial advertisements for guidance.', NULL, NULL, NULL),
  ('edb12c31-e73e-5c4b-a999-6be50d357c89'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'edb12c31-e73e-5c4b-a999-6be50d357c89'::uuid, 1, NULL, TRUE, 0, NULL, E'Galaxy', E'One of the unidentifiable objects in this study lies just outside Centaurus A (NGC 5128), an elliptical galaxy located about 12 million light-years from Earth. The other is in a globular cluster of stars found just outside NGC 4636, another elliptical galaxy located 47 million light-years from Earth in the constellation Virgo.', NULL, NULL, NULL, NULL, NULL, NULL),
