  ('edb6a325-d19e-506c-8d43-bf58ad25d788'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'edb6a325-d19e-506c-8d43-bf58ad25d788'::uuid, 1, NULL, TRUE, 0, NULL, E'Overtime Hours', E'Japan''s Parliament tightened limits on overtime hours, responding to concerns about karoshi , or death by overwork, and seeking to improve productivity in a country where long hours are more a custom than business necessity.', NULL, NULL, NULL, NULL, NULL, NULL),
