  ('edfafc0c-1636-5124-9653-e0cff0b40e56'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'edfafc0c-1636-5124-9653-e0cff0b40e56'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '274e4d3e-a59a-5c43-b762-14cd5d62bfc9'::uuid, NULL, E'The new rules have made thousands more people eligible for legal aid.', NULL, NULL, NULL),
  ('edfd671b-eb6c-581c-ba2d-60aeac386cfa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'edfd671b-eb6c-581c-ba2d-60aeac386cfa'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for the middle number in a sorted list of numbers?', '4d58981b-d4ab-5c18-8b8a-83b29a762239'::uuid, NULL, NULL, E'Median', NULL, NULL),
  ('edffb8cb-f64f-5ebc-a542-5668f7f1a841'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', 'edffb8cb-f64f-5ebc-a542-5668f7f1a841'::uuid, 1, NULL, TRUE, 0, NULL, E'Regent Honeyeater', E'New research from The Australian National University (ANU) shows unless conservation actions are urgently stepped up, one of our most beautiful songbirds, the regent honeyeater, will be extinct within 20 years.\nThe new study reveals current, already intensive, conservation efforts are not sufficient, and a huge redoubling of effort is needed if we are to save these birds from extinction.\n"The regent honeyeater population has been decimated by the loss of over 90 per cent of their preferred woodland habitats," lead author Professor Rob Heinsohn from ANU said.\n"Less than 80 years ago, it was one of the most commonly encountered species, ranging from Adelaide to Rockhampton. Now it is on track to follow the Dodo into extinction."\nToday there are fewer than 300 regent honeyeaters left, making it one of our rarest bird species. Habitat loss has forced them to compete with larger species for remaining habitat.\nThe ANU team commenced a large-scale project in 2015 to better understand the regent honeyeater population decline, but found they are an exceptionally difficult bird to study in the wild. As nomads, they wander long distances in search of nectar. After 6 years of intensive fieldwork, the team discovered that the birds'' breeding success has declined due to predation at the nest by species such as pied currawongs, noisy miners and possums.\n\nWhich of the following statements about the regent honeyeater is correct?', NULL, NULL, NULL, E'It used to be one of the most common species.\nThe decrease of habitat is the main reason for the decrease of the regent honeyeater.', NULL, NULL),
  ('ee02a5e7-e536-58a3-9a55-9146c593d990'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'ee02a5e7-e536-58a3-9a55-9146c593d990'::uuid, 1, NULL, TRUE, 0, NULL, E'Going to University', E'In a perfect world, every young person should go to university. Do you agree with this statement? Why?', NULL, NULL, NULL, NULL, 200, 300),
