  ('ee44ca78-97bc-5ec6-bd2f-4d86b45cf738'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ee44ca78-97bc-5ec6-bd2f-4d86b45cf738'::uuid, 1, NULL, TRUE, 0, NULL, E'Gulf of Mutual Incomprehension', E'Six decades after the British novelist and chemist C. P. Snow famously decried the "gulf of mutual incomprehension" between the sciences and the humanities, the chasm often seems larger than ever. Science has grown more technically demanding over the years, even as the shared public experience of art and culture has fragmented.', NULL, NULL, NULL, NULL, NULL, NULL),
