  ('ee4fda0b-49dc-56d9-8bae-8d6a4bdccec1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ee4fda0b-49dc-56d9-8bae-8d6a4bdccec1'::uuid, 1, NULL, TRUE, 0, NULL, E'Enlightenment', E'The Enlightenment, spanning the 17th and 18th centuries, was an intellectual movement in Europe that sought to challenge traditional doctrines and elevate reason and the scientific method as the primary {{1}} of knowledge. Philosophers like Voltaire, Rousseau, and Kant inspired vigorous debates on liberty, equality, and the {{2}} of government, contributing to the progressive ideas that precipitated revolutionary changes in politics and society. This era championed skepticism toward monarchist and clerical authority, advocating for political and social structures informed by rational discourse and empirical evidence. Notable advances {{3}} from this milieu, including Diderot’s ‘Encyclopédie,’ which aimed to consolidate human knowledge and was instrumental in disseminating Enlightenment thought. The rippling effect of these ideals is seen in pivotal historical developments such as the American Revolution and the crafting of the United States Constitution, which drew {{4}} upon Enlightenment principles. Often referred to as the ‘Age of Reason,’ the Enlightenment left a profound {{5}} that shaped modern Western thought, embodying an enduring faith in the progress of human civilization through rational inquiry and the pursuit of knowledge.', NULL, NULL, NULL, E'1.sources, 2.nature, 3.stemmed, 4.heavily, 5.legacy', NULL, NULL),
  ('ee5b03d1-78ac-5fc5-9dca-0b205c8adea9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ee5b03d1-78ac-5fc5-9dca-0b205c8adea9'::uuid, 1, NULL, TRUE, 0, NULL, E'Cosmic Rays', E'Killer cosmic rays from nearby supernovae could be the culprit behind at least one mass extinction event, researchers said, and finding certain radioactive isotopes in Earth''s rock record could confirm this scenario.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ee5b94be-5fd7-5d96-9330-27980e395f75'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'ee5b94be-5fd7-5d96-9330-27980e395f75'::uuid, 1, NULL, TRUE, 0, NULL, E'Movies', E'Movies are popular all over the world. Explain why movies are so popular.', NULL, NULL, NULL, NULL, 200, 300),
  ('ee5dd419-3d96-5494-bfb0-2ddc2dc87c6e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ee5dd419-3d96-5494-bfb0-2ddc2dc87c6e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '50e34b2e-86f3-5527-940f-59edce66d2a2'::uuid, NULL, E'Eating too much will do harm to your health.', NULL, NULL, NULL),
  ('ee63d6d3-8a80-5b00-916c-763aef52e699'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ee63d6d3-8a80-5b00-916c-763aef52e699'::uuid, 1, NULL, TRUE, 0, NULL, E'Stone Tools', E'Modern humans arrived in westernmost Europe 41,000 to 38,000 years ago, about 5,000 years earlier than previously known, according to an international team of researchers that discovered stone tools used by modern humans dated to the earlier time period in a cave near the Atlantic coast of central Portugal. The tools document the presence of modern humans at a time when Neanderthals were thought to be present in the region.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ee6cefe1-ef6d-5d9a-99ed-bbd77c2e3e65'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ee6cefe1-ef6d-5d9a-99ed-bbd77c2e3e65'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2c93a42c-b45d-534d-b533-25dfabdfe122'::uuid, NULL, NULL, E'As the world gets more crowded more trees are being cut down.', NULL, NULL),
  ('ee81c01b-1866-5d61-8cd4-02a7e7adb9d2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ee81c01b-1866-5d61-8cd4-02a7e7adb9d2'::uuid, 1, NULL, TRUE, 0, NULL, E'Norms and Values', E'Members of a culture must conform to its norms for the culture to exist and function. Hence, members must want to conform and obey rules. They first must internalize the social norms and values that dictate what is normal for the culture. Then they must socialize or teach norms and values to their children.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ee887e39-9d9a-5d3c-88b9-d0035623b45d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RESPOND_TO_A_SITUATION', E'RESPOND_TO_A_SITUATION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ee887e39-9d9a-5d3c-88b9-d0035623b45d'::uuid, 1, NULL, TRUE, 0, NULL, E'A Hiking Trip', E'You''ve organized a group hiking trip with your friends, and everyone''s excited to hit the trails. However, upon arrival at the meeting point, you notice some of them have brought single-use plastic water bottles and snack wrappers, leaving behind litter. You need to remind them to respect the environment. What would you say to your friends?', '9552e455-ff5a-5bad-9043-ffb7f08a4558'::uuid, NULL, E'Hey everyone, before we hit the trails, let''s chat about keeping our environment clean. I noticed some single-use plastic and snack wrappers left behind. Let''s be mindful and pack out all our trash to leave no trace and preserve the beauty of nature for others to enjoy. Bringing reusable water bottles and snacks in reusable containers can help minimize waste. Thanks for helping keep our hiking experience enjoyable and eco-friendly!', NULL, NULL, NULL),
  ('ee89e650-6028-560c-9716-fc5dd3dce68c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ee89e650-6028-560c-9716-fc5dd3dce68c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which one is quicker? Running, jogging or walking?', '8d968c8d-b2a2-5e63-a6e4-f182f388cfdd'::uuid, NULL, NULL, E'Running', NULL, NULL),
