  ('ee9d6c21-e161-5b0b-aac7-07a553584d9e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ee9d6c21-e161-5b0b-aac7-07a553584d9e'::uuid, 1, NULL, TRUE, 0, NULL, E'Koala', E'A koala rode 16 kilometers near Adelaide, Australia, inside an {{1}} for a car wheel. The driver did not {{2}} until he stopped and heard the animal making noise. A woman with an animal rescue organization said that it was incredible, but the koala was in {{3}} . The organization took her straight to the vet. People named the koala Kelli, after one of her {{4}} , and put the koala back into the wild. She quickly climbed up a tree and went to sleep. Koalas are a {{5}} species as there are less than 100,000 of them in the wild.', NULL, NULL, NULL, E'1.arch, 2.observe, 3.shock, 4.rescuers, 5.vulnerable', NULL, NULL),
  ('eea44caf-195a-573c-88ab-028c355a6b11'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'eea44caf-195a-573c-88ab-028c355a6b11'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What order is a bibliography usually listed in?', 'c2d0564c-cb44-5251-b50b-423335c6cdd6'::uuid, NULL, NULL, E'Alphabet', NULL, NULL),
  ('eea5a54c-1fd6-5bdf-a4e2-c9f3314423cd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'eea5a54c-1fd6-5bdf-a4e2-c9f3314423cd'::uuid, 1, NULL, TRUE, 0, NULL, E'Work-Life Balance', E'One of the major issues that organizations and employees face is the difficulty in finding balance between work and personal life. It is not possible to {{1}} those two areas completely, as problems or stress in one area strongly affect the other. Further, the two areas often compete with one another for individuals’ time, energy, and attention. This leads to conflict and stress, which in turn causes lower {{2}} levels on the job. Organizations realize that this is not a beneficial situation, and there are many things they can do to support the right balance between work and life. One of the most obvious is to limit {{3}} to reasonable levels of work commitment each week. Overloading employees and demanding an unreasonable portion of their time and energy inevitably leads to difficulties. Along these same lines, providing {{4}} vacation time has also been identified as a wise policy that prevents employee burnout and increases productivity in the long run.', NULL, NULL, NULL, E'1.separate, 2.performance, 3.expectations, 4.ample', NULL, NULL),
  ('eebf3a1b-d81f-5059-a1c9-4b27061c00ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'eebf3a1b-d81f-5059-a1c9-4b27061c00ee'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '539eef31-ecf7-59b2-8163-09510a6ae885'::uuid, NULL, E'A lot of people who have up until now been spending money in having a good time now need to be more careful with their money.', NULL, NULL, NULL),
