  ('eecc76ae-0790-5c7d-8e4f-2b27f95911a0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'eecc76ae-0790-5c7d-8e4f-2b27f95911a0'::uuid, 1, NULL, TRUE, 0, NULL, E'Water Vapor', E'In cold weather or during startup, water vapor present in the exhaust system can create white smoke, while blue smoke might be an indication of a different issue. Exhaust emissions, a natural byproduct of the combustion process, are typically harmless, as they dissipate quickly once the engine warms up.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('eed00525-ff0a-5f20-9204-a34ccab81a46'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'eed00525-ff0a-5f20-9204-a34ccab81a46'::uuid, 1, NULL, TRUE, 0, NULL, E'Ford', E'Ford made a U-turn, scrapping plans for a 1.6 billion factory in Mexico to build compact cars, and diverting some of the investment to a plant near Detroit to produce electric vehicles. Ford stressed that this was a commercial decision. Donald Trump had criticized the proposed Mexican factory while campaigning on the theme of saving American jobs.', NULL, NULL, NULL, NULL, NULL, NULL),
