  ('eeddc7e4-4f68-51bc-adb2-5b40d8ac6778'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'eeddc7e4-4f68-51bc-adb2-5b40d8ac6778'::uuid, 1, NULL, TRUE, 0, NULL, E'Pupil Charity', E'My school in the city of London held a {{1}} appeal. In the community, I was voted as the chairman. We {{2}} 48,000 pounds and I won the first place in the end. During this period, I learnt a lot and realized the importance of {{3}} and how to {{4}} other pupils'' awareness.', NULL, NULL, NULL, E'1.charity, 2.raised, 3.tenacity, 4.rouse', NULL, NULL),
  ('eede4d17-41ff-5138-baac-76d2221980d6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'eede4d17-41ff-5138-baac-76d2221980d6'::uuid, 1, NULL, TRUE, 0, NULL, E'Decline or Empowerment', E'While opponents view beauty pageants as symbols of decline, others argue that they can be platforms for empowerment and self-expression. Supporters highlight the opportunities these contests provide for personal growth, public speaking, and community involvement. It is essential to foster a dialogue that explores the potential positive aspects of beauty pageants while addressing concerns about objectification.', NULL, NULL, NULL, NULL, NULL, NULL),
