  ('eeebe4cf-2102-5bcb-be39-83eb4bc0c05b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'eeebe4cf-2102-5bcb-be39-83eb4bc0c05b'::uuid, 1, NULL, TRUE, 0, NULL, E'Politics Disciplines', E'This course provides students with an in-depth understanding of the exciting disciplines of politics and international relations and commerce. Students will learn about the {{1}} of political institutions in countries around the world and explore the complex field of relations between nations. Topics in governance, public policy, public administration, national security, border control and commerce ensure that students receive a {{2}} and current education in the range of issues which are covered under the label of politics and international relations. Students will undertake four compulsory units and two majors, one in politics and international relations and the other in governance and policy. They will also choose an elective major from a wide choice of {{3}} including political communication, international studies, international business and national security studies. In {{4}} to acquiring specialist {{5}} and competencies in Politics and International Relations and Commerce, students will graduate with a range of generic skills such as critical thinking, enhanced communication abilities, problem solving and strong capacities to work with others. They will also develop ethically based and socially {{6}} attitudes and behaviors.', NULL, NULL, NULL, E'1.workings, 2.broad, 3.options, 4.addition, 5.knowledge, 6.responsible', NULL, NULL),
  ('eeee7b7a-fecb-56fa-98d6-1abcca4107da'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'eeee7b7a-fecb-56fa-98d6-1abcca4107da'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person who reads a book?', '04d1d76d-78dc-57ae-ab9f-8bd2db827be4'::uuid, NULL, NULL, E'Reader', NULL, NULL),
  ('eef1f6bd-f9dc-52db-8a10-3042c006ffe2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'eef1f6bd-f9dc-52db-8a10-3042c006ffe2'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ed8b7ed1-2c95-5dce-9bfa-077528f9cac5'::uuid, NULL, NULL, E'There was not enough evidence to support these recommendations.', NULL, NULL),
  ('eef6d7e3-b38b-5218-b3ce-b96d610e65b1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'eef6d7e3-b38b-5218-b3ce-b96d610e65b1'::uuid, 1, NULL, TRUE, 0, NULL, E'Cheese', NULL, '7d4bc399-a1eb-51ed-9e0e-d63e55160552'::uuid, NULL, E'As early as 8000 BCE, the earliest Neolithic farmers living in the Fertile Crescent began a legacy of cheese-making almost as old as civilization itself. The rise of agriculture led to domesticated sheep and goats, which ancient farmers harvested for milk. But when left in warm conditions for several hours, that fresh milk began to sour. Its lactic acids caused proteins to coagulate, binding into soft clumps. Upon discovering this strange transformation, the farmers drained the remaining liquid – later named whey – and found the yellowish globs could be eaten fresh as a soft, spreadable meal. These clumps, or curds, became the building blocks of cheese, which would eventually be aged, pressed, ripened, and whizzed into a diverse cornucopia of dairy delights. The discovery of cheese gave Neolithic people an enormous survival advantage. Milk was rich with essential proteins, fats, and minerals. But it also contained high quantities of lactose – a sugar which is difficult to process for many ancient and modern stomachs. Cheese however, could provide all of milk’s advantages with much less lactose. And since it could be preserved and stockpiled, these essential nutrients could be eaten throughout scarce famines and long winters.', NULL, NULL, NULL),
  ('eefe7cdb-e663-5f5c-84be-812b7e20a3ec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'eefe7cdb-e663-5f5c-84be-812b7e20a3ec'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What thing do postgraduate students have that undergraduate students don’t?', '3f7c3ab6-ba8f-53b3-81e9-35d42445dff6'::uuid, NULL, NULL, E'Bachelor degree', NULL, NULL),
