  ('ef3e0558-c34f-5582-8e39-26f849d0cf92'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ef3e0558-c34f-5582-8e39-26f849d0cf92'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0547d01c-46ac-59fb-a648-9f5b1526b56c'::uuid, NULL, NULL, E'Work through these math questions using what you''ve learned.', NULL, NULL),
