  ('ef628571-cbe1-5529-87f9-4eeee9d473a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ef628571-cbe1-5529-87f9-4eeee9d473a8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do meter and millimeter measure, weight or length?', 'afe50a3e-c0a5-5e43-a342-ac6164667ac6'::uuid, NULL, NULL, E'Length', NULL, NULL),
  ('ef637265-8fbd-5201-9f19-cb833307e195'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'ef637265-8fbd-5201-9f19-cb833307e195'::uuid, 1, NULL, TRUE, 0, NULL, E'Turkey(土耳其)', NULL, NULL, NULL, NULL, E'3, 2, 4, 1', NULL, NULL),
  ('ef68de5e-ab00-57fa-b297-b0c57e7d1ab1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ef68de5e-ab00-57fa-b297-b0c57e7d1ab1'::uuid, 1, NULL, TRUE, 0, NULL, E'Remember Being Babies', E'Most adults can''t recall life''s earliest moments unless the events are reinforced by others who often retell them, or the memories are triggered by photographs or other cues. It''s a phenomenon scientists call childhood amnesia. While you may have been able to recall and describe your second birthday party in great detail for months after it happened, a year later those memories may have faded and, eventually, are lost altogether.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ef6cfe7e-c355-5630-9181-0f73d5b24438'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ef6cfe7e-c355-5630-9181-0f73d5b24438'::uuid, 1, NULL, TRUE, 0, NULL, E'Urban Transformation', E'The focus of this study pivots to the heart of urban transformation, examining the impact of electric scooters in metropolitan areas. In two major cities, a pilot program was {{1}} to integrate e-scooters into the urban transportation grid. The study observed how this integration affected traffic flow, pollution levels, and the overall urban landscape. The participating cities saw a marked decrease in car usage, suggesting a shift towards more sustainable travel options. {{2}} , there was a notable reduction in noise and air pollution. The study, named the ‘Urban Mobility Project’, aimed to understand how such small-scale transport means could significantly alter the {{3}} of city life. The results indicated not only a positive environmental impact but also a change in the social fabric of urban communities, {{4}} a more connected and accessible city environment.', NULL, NULL, NULL, E'1.introduced, 2.Additionally, 3.dynamics, 4.fostering', NULL, NULL),
  ('ef73e973-05f2-5207-a2b4-85ab2c0732e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ef73e973-05f2-5207-a2b4-85ab2c0732e1'::uuid, 1, NULL, TRUE, 0, NULL, E'Forecasting Earthquakes', E'Forecasting earthquakes would {{1}} high-resolution measurements deep underground over the course of decades, if not longer, coupled with sophisticated simulations of the {{2}} interactions between the tectonic plates, faults, and rocks. And even then, it’s {{3}} to yield an hour’s worth of lead time, let alone a {{4}} date, location, and magnitude of an earthquake.', NULL, NULL, NULL, E'1.require, 2.complex, 3.unlikely, 4.precise', NULL, NULL),
  ('ef7c061f-6fff-5d73-a06b-bbdd9668d847'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ef7c061f-6fff-5d73-a06b-bbdd9668d847'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2d4404dd-05fb-5e48-84d2-d6b9c18e031a'::uuid, NULL, E'He needs to discuss your industrial architecture class in detail.', NULL, NULL, NULL),
  ('ef82546e-e740-55b2-9bd0-32ac4ffb1dc5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ef82546e-e740-55b2-9bd0-32ac4ffb1dc5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '44a41e3e-751e-5d44-82bf-91f5ee66bb14'::uuid, NULL, NULL, E'Officers from the education department visit the schools regularly.', NULL, NULL),
  ('ef880920-0d16-5917-9029-d3809ef9501a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ef880920-0d16-5917-9029-d3809ef9501a'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'aa4f6f9b-3393-57a6-b61f-b2a470a4fa01'::uuid, NULL, NULL, E'They came here in search of new markets for their products.', NULL, NULL),
  ('ef89d15a-f8c1-5088-a924-e2610448b971'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ef89d15a-f8c1-5088-a924-e2610448b971'::uuid, 1, NULL, TRUE, 0, NULL, E'Sydney', E'Sydney is becoming effective in making the best of its limited available unconstrained land. Sydney is suitable for integrating suitable business, office, residential, retail and other development in accessible locations so as to maximize public transport {{1}} and encourage walking and cycling. Also this city can reduce the {{2}} of land for housing and associated urban development on the urban fringe. For the proposed mixed business, mixed use and business park areas, there was no employment data available for {{3}} areas. It is also concluded that lack of housing supply will affect {{4}} in Sydney.', NULL, NULL, NULL, E'1.patronage, 2.consumption, 3.comparable, 4.affordability', NULL, NULL),
  ('ef8f25da-ff04-5f09-8d2a-29e4c8bc0fcd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ef8f25da-ff04-5f09-8d2a-29e4c8bc0fcd'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c2566ddf-a0c3-5b94-83f2-6ec1259d61b9'::uuid, NULL, E'All students on engineering courses spent one year working on the raw experience.', NULL, NULL, NULL),
  ('ef98abd0-bb99-5cfc-a1da-05afcad5740f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ef98abd0-bb99-5cfc-a1da-05afcad5740f'::uuid, 1, NULL, TRUE, 0, NULL, E'Time Famine', E'A team of researchers finds that shelling out for services that save time can bring greater feelings of life satisfaction than, say, simply buying more stuff. The results appear in the Proceedings of the National Academy of Sciences.\nIt''s safe to say that most of us regularly feel crunched for time. So much so that we are experiencing what Ashley Whillans of the Harvard Business School, the lead author of the study, describes as a "time famine." And like any famine, this chronic lack of time takes its toll on our health.\n"When we feel like our to-do lists are longer than the hours that we have time in the day to complete them, we can feel as if our life is spiraling out of control, thereby undermining our personal well-being."\nWell, if time is money, Whillans and her team wondered whether money that''s used to buy time could offer some relief. Like paying someone else to clean the house, mow the lawn, or deliver the groceries.\n\nAccording to the speaker, which services are the time-saving services?', '26837a12-3bd6-5d7d-a9dc-5453b0a16259'::uuid, NULL, NULL, E'Hiring someone to walk the dog.\nHiring a babysitter to take care of the baby.', NULL, NULL),
  ('ef9f2303-4884-54ab-b237-d6a50191e331'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ef9f2303-4884-54ab-b237-d6a50191e331'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd7334b27-61cb-56b4-a052-53cda4844708'::uuid, NULL, NULL, E'Affordable housing is an important issue for all members of society.', NULL, NULL),
  ('efab0704-32db-5cc7-8eb0-a0e91d4af1f1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'efab0704-32db-5cc7-8eb0-a0e91d4af1f1'::uuid, 1, NULL, TRUE, 0, NULL, E'Cosmic Civilization', NULL, '7b4de6fc-dd32-5491-9dc3-0395bf6abac8'::uuid, NULL, E'The possibility of the existence of other cosmic civilizations has always been an important topic in space research. Scientists are interested in finding out whether life exists on other planets beyond Earth and whether another civilization could develop somewhere in the universe. Every year, around 7 stars are created in some areas of the universe, and there are many planets formed around these stars. However, most planets around them cannot support life because their environments are usually either too hot or too cold. Researchers estimate that only about 20% of all planets may meet all necessary criteria and have a chance to have life. Even if a planet has suitable conditions, the possibility of life developing into a complex civilization is still very small. The change of appearance of life from simple organisms to advanced civilizations is extremely rare, which makes it hard to find another cosmic civilization. Therefore, although the universe contains countless planets, discovering another intelligent civilization remains a great challenge.', NULL, NULL, NULL),
  ('efb4467e-1e80-554f-ac28-af49e222877b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'efb4467e-1e80-554f-ac28-af49e222877b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which would be better to report the population of a major global city - hundreds, millions or billions?', '15c079ac-5eaa-5a9d-b078-3c26d29c1d9f'::uuid, NULL, NULL, E'Millions', NULL, NULL),
  ('efb62c96-a0b3-5f0d-a761-90e806dbd419'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'efb62c96-a0b3-5f0d-a761-90e806dbd419'::uuid, 1, NULL, TRUE, 0, NULL, E'Kashmiri', E'Two decades ago, Kashmiri houseboat-owners rubbed their hands every spring at the prospect of the annual influx of {{1}} . From May to October, the hyacinth-choked {{2}} of Dal Lake saw flotillas of vividly painted Shikaras carrying Indian families, boho westerners, young travelers and wide-eyed Japanese. Carpet-sellers honed their skills, as did purveyors of anything remotely embroidered while the house boats initiated by the British Raj provided unusual accommodation. Then, in 1989, separatist and Islamist militancy {{3}} and everything changed. Hindus and countless Kashmiri business people bolted, at least 35,000 people were killed in a decade, the lake stagnated, and the houseboats rotted. Any foreigners venturing there risked their {{4}} , proved in 1995 when five young Europeans were kidnapped and murdered.', NULL, NULL, NULL, E'1.tourists, 2.waters, 3.attacked, 4.lives', NULL, NULL),
  ('efb6415e-c349-5f5a-a041-c150334e9abe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'HIGHLIGHT_CORRECT_SUMMARY', E'HIGHLIGHT_CORRECT_SUMMARY', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'efb6415e-c349-5f5a-a041-c150334e9abe'::uuid, 1, NULL, TRUE, 0, NULL, E'DNA Model', E'In the effort to construct a comprehensive mathematical model for DNA, it is essential to represent not only the quasi-helical geometry of the molecule but also its non-linear and sequence-dependent energetic behavior. A valid model must remain consistent under symmetry-preserving transformations and account for global topological constraints. The Mobius weight energy function (MWEF) is introduced as a scalar descriptor for capturing the intertwined effects of structural topology and torsional energy distribution. The Mobius weight function, adapted from continuous mapping principles in differential topology, assigns a signed curvature weight to local torsional segments of the DNA. This weighting incorporates a parity-sensitive inversion property, enabling the detection of torsional phase discontinuities that conventional helical twist measures often overlook. In this framework, DNA is represented as a sequence of discrete base-pair states embedded in a ribbon-like manifold with non-trivial topological properties. The MWEF aggregates the Mobius weights across the DNA contour while incorporating local bending resistance and torsional flexibility parameters. This approach produces an energy landscape sensitive to both the base sequence variations and higher-order structural deformations such as supercoiling or localized kinking. One of the strengths of this model is its ability to combine mechanical deformation characteristics with electronic interaction potentials between base pairs, while preserving global topological invariants. Computational studies using this method show that energy minima emerge near specific Mobius phase transitions, which correlate with experimentally observed loop-closure points and structural kinks in constrained DNA samples.\n\nClick on the paragraph that best relates to the recording.', 'eba790ee-db2f-5cd8-8ff4-23e000607689'::uuid, NULL, NULL, E'The proposed model uses Mobius weight functions to unify topological and sequence-dependent torsional characteristics in DNA.', NULL, NULL),
  ('efc466ec-c5ab-5d9d-9125-00e3e184a43f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'efc466ec-c5ab-5d9d-9125-00e3e184a43f'::uuid, 1, NULL, TRUE, 0, NULL, E'Antibiotics', NULL, '7d96dc94-3827-57c0-bfd2-f988af1ac439'::uuid, NULL, E'In this presentation, I''m excited to delve into the revolutionary role of antibiotics in modern medicine. The discovery of antibiotics marked a turning point in medical history, drastically changing the way we treat infections. Before the advent of antibiotics, simple infections could be deadly, and surgeries were high-risk procedures. The introduction of penicillin in the 1940s, discovered by Alexander Fleming, changed everything. It became the first widely used antibiotic, turning once-fatal diseases into treatable conditions. Antibiotics have not only saved countless lives but also have played a critical role in advancing medical procedures. They made complex surgeries safer and organ transplants possible by preventing and treating bacterial infections. However, it''s crucial to address the growing concern of antibiotic resistance due to overuse and misuse. This highlights the importance of responsible antibiotic use and ongoing research for new treatments. In conclusion, antibiotics are a cornerstone of modern medicine, dramatically improving our ability to fight infections. Their discovery and development remind us of the incredible impact of medical research and innovation.', NULL, NULL, NULL),
  ('efc5655e-d774-59b9-bc08-e0be0bb53bc4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'efc5655e-d774-59b9-bc08-e0be0bb53bc4'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '55211365-d379-57e2-8fde-2602b11d0fcd'::uuid, NULL, E'We are delighted to have professor Robert to join our faculty.', NULL, NULL, NULL),
  ('efc7216d-3d78-5982-8d49-5e5df3dafef3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'efc7216d-3d78-5982-8d49-5e5df3dafef3'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term for a professional who takes photographs, either as a hobby or a career?', '4201e84f-d30e-5522-85b9-11096b6aa9ce'::uuid, NULL, NULL, E'Photographer', NULL, NULL),
  ('efcca88d-777d-5c10-9c9a-3d28b63691f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'efcca88d-777d-5c10-9c9a-3d28b63691f9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '036bd5e6-7c0e-575e-844e-2ea41f8941e6'::uuid, NULL, E'Our guest professor will give a geology lecture very soon.', NULL, NULL, NULL),
