  ('efd92019-1e58-5081-908a-845def509a9b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'efd92019-1e58-5081-908a-845def509a9b'::uuid, 1, NULL, TRUE, 0, NULL, E'Language Appearance', E'It seems that language appeared from nowhere since no other species has anything resembling human language. However, other animals do possess basic systems for perceiving and producing sounds that enable them to communicate. These systems may have been in place before the appearance of language.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('efde0465-1a51-5833-a85a-cc511447ca63'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'efde0465-1a51-5833-a85a-cc511447ca63'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name for the branch of biology that deals with the structure of organisms?', 'aca25e63-407c-561b-9e4f-a17462ee5438'::uuid, NULL, NULL, E'Anatomy', NULL, NULL),
  ('efe036a4-95e5-5103-b018-3c7053ebdde9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'efe036a4-95e5-5103-b018-3c7053ebdde9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '95731a94-f2fb-5fae-b0ec-ecb2d21c13a6'::uuid, NULL, E'Due to rising enrollment in courses, universities should also increase their staff.', NULL, NULL, NULL),
  ('efe73341-5ce7-530f-9005-14a0cfed8b8e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'efe73341-5ce7-530f-9005-14a0cfed8b8e'::uuid, 1, NULL, TRUE, 0, NULL, E'Joint Venture', E'A joint venture is a business arrangement in which two or more parties agree to pool their resources for the purpose of accomplishing a specific task. This task can be a new project or any other business activity. In a joint venture, each of the participants is responsible for profits, losses, and costs associated with it.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('efedea45-fe71-59a6-9ddd-26b584aa4073'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'efedea45-fe71-59a6-9ddd-26b584aa4073'::uuid, 1, NULL, TRUE, 0, NULL, E'Sporting Events', E'Hosting sporting events such as the Olympics and the World Cup can bring benefits to the host countries. How far do you agree with this statement? Use your own examples to support.', NULL, NULL, NULL, NULL, 200, 300),
  ('eff7dd21-6de8-5f96-9f42-c740da9d75ac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'eff7dd21-6de8-5f96-9f42-c740da9d75ac'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the mountain range in western North America?', '382a2ec5-09e7-57a0-93be-c6344a36797e'::uuid, NULL, NULL, E'Rocky Mountains', NULL, NULL),
  ('eff80010-2529-53df-8434-6b181e7c61a5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'eff80010-2529-53df-8434-6b181e7c61a5'::uuid, 1, NULL, TRUE, 0, NULL, E'Flipping Coin', NULL, '9dcca2c6-62ce-5559-a647-66f20424a269'::uuid, NULL, E'Flipping a coin may not be the fairest way to settle disputes. About a decade ago, statistician Persi Diaconis started to wonder if the outcome of a coin flip really is just a matter of chance. He had Harvard University engineers build him a mechanical coin flipper. Diaconis, now at Stanford University, found that if a coin is launched exactly the same way, it lands exactly the same way.\nThe randomness in a coin toss, it appears, is introduced by sloppy humans. Each human-generated flip has a different height and speed, and is caught at a different angle, giving different outcomes.\nBut using high speed cameras and equations, Diaconis and colleagues have now found that even though humans are largely unpredictable coin flippers, there''s still a bias built in, if a coin starts out heads, it ends up heads when caught more often than it does tails. NPR''s David Kestenbaum reports.', NULL, NULL, NULL),
  ('effc7be9-7af5-500f-934f-d249397c7e21'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'effc7be9-7af5-500f-934f-d249397c7e21'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '20aaab58-95fd-5618-88c8-eb989069e7fc'::uuid, NULL, E'Children often depend on their parents for food and clothing.', NULL, NULL, NULL),
  ('f009d027-95b9-5924-b13a-59bd6bb5a656'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f009d027-95b9-5924-b13a-59bd6bb5a656'::uuid, 1, NULL, TRUE, 0, NULL, E'Deep Ocean', E'As the depth of the ocean increases, the water pressure and the amount of sunlight both decrease until about two thousand meters, after which the water temperature {{1}} steady until about four thousand meters. In this pitch-dark and high-pressure zone, what {{2}} these odd creatures to survive is their special adaptations. Astonishingly, numerous odd creatures have evolved here, their unique forms {{3}} a marvel, fueling scientists'' eagerness to explore further.', NULL, NULL, NULL, E'1.remains, 2.enables, 3.presenting', NULL, NULL),
  ('f00c6b98-8e43-58b9-8bd7-c094e549632b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f00c6b98-8e43-58b9-8bd7-c094e549632b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '87703d43-b04e-5884-8afc-83df56f2f673'::uuid, NULL, E'The building will be closed and reopened next week.', NULL, NULL, NULL),
