  ('f04329cd-adfe-5d5c-bfa1-7deb029229cb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f04329cd-adfe-5d5c-bfa1-7deb029229cb'::uuid, 1, NULL, TRUE, 0, NULL, E'Inclined Plane', E'An inclined plane is a simple machine with no moving parts. It is simply an even sloping surface. It makes it easier for us to move objects to higher or lower surfaces than if we lifted the objects directly upwards. It is believed that ancient Egyptians used inclined planes to carry heavy stones to build pyramids.', NULL, NULL, NULL, NULL, NULL, NULL),
