  ('f0912e64-aa15-582d-b92c-f9b7d0c1225e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f0912e64-aa15-582d-b92c-f9b7d0c1225e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What sport involves two teams trying to score by throwing a ball into a hoop?', 'f14b9cc4-2431-5fc1-ad6e-7cc95847977f'::uuid, NULL, NULL, E'Basketball', NULL, NULL),
