  ('f09e5222-6973-5c38-8825-6eef22e87d9f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f09e5222-6973-5c38-8825-6eef22e87d9f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'bbbb92cf-2436-5624-a205-60fb8a77f190'::uuid, NULL, NULL, E'Honey serves both as a nutritious food and a medicinal product.', NULL, NULL),
  ('f0a15543-8e24-5938-b4ce-42e88350ba51'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f0a15543-8e24-5938-b4ce-42e88350ba51'::uuid, 1, NULL, TRUE, 0, NULL, E'Science Warn Global Warming', E'You may well ask why science did not warn us of global warming sooner; I think that there are several reasons. We were from the 1970s until the end of the century {{1}} the important global problem of stratospheric {{2}} depletion, which we knew was manageable. We threw all our efforts into it and succeeded but had little time to spend on climate change. Climate science was also neglected because twentieth-century science failed to {{3}} the true nature of Earth as a {{4}} self-regulating entity. Biologists were so carried away by Darwin''s great vision that they failed to see that living things were tightly coupled to their material environment and that evolution concerns the whole Earth system with living organisms an {{5}} part of it. Earth is not the Goldilocks planet of the solar system sitting at the right place for life. It was in this favourable state some two billion years ago but now our planet has to work hard, against ever increasing heat from the Sun, to keep itself {{6}} . We have chosen the worst of times to add to its difficulties.', NULL, NULL, NULL, E'1.distracted by, 2.ozone, 3.recognize, 4.responsive, 5.integral, 6.habitable', NULL, NULL),
