  ('f0f99066-f810-55eb-a3bb-792219d6be47'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f0f99066-f810-55eb-a3bb-792219d6be47'::uuid, 1, NULL, TRUE, 0, NULL, E'Governmental Blogging', NULL, '97867d7d-5449-55fa-9976-306a1efde03e'::uuid, NULL, E'We normally see blogging as a two-way interaction, in which the blogger/author creates the content and the readers interact with or challenge the author.\nBut the case will be much difficult when it comes to governments, such as the White House.\nBecause people will become coarser and ruder online towards their governments, especially in comment areas.\nThus, governments'' blogs may go wild and chaotic.\nAnd then governments will have to administrate the comments.\nOnce the government starts to impose harsh administration on comment areas, citizens may find the government manipulating what should be said and what should be shown, which contradicts the original intention.', NULL, NULL, NULL),
