  ('f11a8813-c5df-59f4-ad46-c81843419dc6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f11a8813-c5df-59f4-ad46-c81843419dc6'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '817374f1-a1a4-56a3-b1b7-382a90650d5f'::uuid, NULL, NULL, E'You must set a security question when resetting your password.', NULL, NULL),
  ('f11f2699-7ca0-53f1-ab70-21d6a9107015'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f11f2699-7ca0-53f1-ab70-21d6a9107015'::uuid, 1, NULL, TRUE, 0, NULL, E'Sociological Imagination', E'The sociological imagination, a concept established by C. Wright Mills (1916-1962) provides a framework for understanding our social world that far surpasses any common sense notion we might {{1}} from our limited social experiences. Mills was a contemporary sociologist who brought tremendous {{2}} into the daily lives of society’s members. Mills stated: “Neither the life of an individual nor the history of a society can be understood without understanding both”. The sociological imagination is making the connection between personal challenges and larger social issues. Mills identified “troubles” (personal challenges) and “issues” (larger social challenges), also known as biography and history {{3}} . Mills’ sociological imagination allows individuals to see the relationships between events in their personal lives (biography), and events in their society (history). In other words, this mindset provides the ability for individuals to {{4}} the relationship between their personal experiences and the larger society in which they live their lives.', NULL, NULL, NULL, E'1.derive, 2.insight, 3.respectively, 4.realize', NULL, NULL),
  ('f11fb5e4-9dfd-55d4-a119-c5a20f552420'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f11fb5e4-9dfd-55d4-a119-c5a20f552420'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which organ of our body can tell different tastes?', 'e45afbe4-4a9f-5f18-938f-7430f43aaffe'::uuid, NULL, NULL, E'Tongue', NULL, NULL);
