  ('f1579b47-d13c-59d5-83c6-874b0435dcf5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f1579b47-d13c-59d5-83c6-874b0435dcf5'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call one of the parts of a school year?', 'd7f3624e-304e-5a3b-8ccc-d5b4dd8d2f20'::uuid, NULL, NULL, E'Term / terms / semester', NULL, NULL),
