  ('f16b08e8-0cab-5b77-8186-d9d8399a45c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f16b08e8-0cab-5b77-8186-d9d8399a45c0'::uuid, 1, NULL, TRUE, 0, NULL, E'Quality Translation', E'As technology keeps growing, political and economic leaders have utilized cinema in changing and shaping people’s outlooks either for their own benefit or for the benefit of the people. Quality translations are also readily available and extremely affordable for everyone these days, which makes it easy for filmmakers to reach their target audiences from all corners of the world in their mother tongue.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f16dce6a-66ce-50ea-936f-65361c6eb558'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f16dce6a-66ce-50ea-936f-65361c6eb558'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '75fb159a-c719-53ac-aab4-e655c2855102'::uuid, NULL, NULL, E'The library has a wide range of collection of images and films.', NULL, NULL),
  ('f16e5b1f-5007-5bec-a15a-f7902f27f53e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f16e5b1f-5007-5bec-a15a-f7902f27f53e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e253515e-04ae-552d-8fb6-c67beca96829'::uuid, NULL, NULL, E'It is generally accepted that language is a part of culture.', NULL, NULL),
  ('f1723ebf-9f5e-5089-b7fe-c7b48d3ba8cc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f1723ebf-9f5e-5089-b7fe-c7b48d3ba8cc'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6f18930a-64fc-58ca-9b7c-a1b980983a6a'::uuid, NULL, E'The library offers group study rooms, so you can work with other students.', NULL, NULL, NULL),
  ('f173ecb8-e4f5-563b-9749-d9f0f8293ea1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f173ecb8-e4f5-563b-9749-d9f0f8293ea1'::uuid, 1, NULL, TRUE, 0, NULL, E'Artificial Sweeteners', E'You could be forgiven for being completely confused when it comes to consuming low-calorie or artificial sweeteners. Some days, the headlines are full of {{1}} for their beneficial effects on health, helping people to lose weight by replacing their favorite sugary drinks and treats with similar-tasting diet versions. At other times, we are told low-calorie sweeteners are linked with serious health conditions, from raising blood pressure to an increased risk of type 2 diabetes. Just last month, a large study of French adults claimed to have found an {{2}} between consuming sweeteners and an increased risk of heart disease. Allison Sylvetsky, an associate professor at George Washington University, is trying to unpick the science involved in this controversial topic. Her work is {{3}} light on whether artificial sweeteners can give us the sweet fix we seek while helping us to maintain our weight and prevent chronic disease, or whether they should be handled with care.', NULL, NULL, NULL, E'1.praise, 2.association, 3.shedding', NULL, NULL),
  ('f1758c98-565e-5d40-98fb-e0e1c58909a4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f1758c98-565e-5d40-98fb-e0e1c58909a4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'dc535102-9b41-5dac-a531-5a4bf2889b2f'::uuid, NULL, NULL, E'The professor will be teaching history and sociology next term.', NULL, NULL),
  ('f17946ad-498b-5bf0-98f6-e8a7a5608904'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'f17946ad-498b-5bf0-98f6-e8a7a5608904'::uuid, 1, NULL, TRUE, 0, NULL, E'Jupiter', E'Jupiter has 2-1/2 times more mass as compared to all other planets put together. Besides, its diameter is 11 times more than Earth''s diameter. Because of its size, the scientists were also forced into believing that it became a star. Gasses and dust contracted to build the planet and immense pressure was created by the gravitational forces along with tens of thousands of degrees of temperature. However, unlike the Sun, the unavailability of sufficient mass required to create the temperature which can initiate fusion reaction, Jupiter relatively got cooler over a period of time.\n\nWhat is mainly talked about in this passage?', NULL, NULL, NULL, E'Jupiter’s development as compared to the Sun', NULL, NULL),
  ('f179d8c4-ff2b-5a1c-8e82-bef5b22a942f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f179d8c4-ff2b-5a1c-8e82-bef5b22a942f'::uuid, 1, NULL, TRUE, 0, NULL, E'Economists'' Views', E'An economist sees the world basically through a typical micro-economic {{1}} . That involves things like thinking at the margin, rationality, opportunity cost, trade-offs. Economics, like any other {{2}} or dogma, has its own jargon and its own rules, and its own way of seeing the world. So basically economics, or economists in general tend to apply micro-economic {{3}} like that to explain the way humans behave and to make {{4}} about the future.', NULL, NULL, NULL, E'1.toolkit, 2.discipline, 3.concepts, 4.predictions', NULL, NULL),
  ('f179e4d9-a6b3-5181-b4a9-cb1969dcb2ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'f179e4d9-a6b3-5181-b4a9-cb1969dcb2ee'::uuid, 1, NULL, TRUE, 0, NULL, E'Replaced Textbooks', E'Do you think textbooks should be replaced by online resources and technological innovations?', NULL, NULL, E'As technology advances, many people are questioning whether traditional textbooks should be replaced by online resources and technological innovations. While some may argue that textbooks still have value, I firmly believe that online resources and technological innovations are the way forward for education.\nFirstly, one of the biggest advantages of using online resources and technological innovations is the convenience they offer. With just a few clicks, students can access a wealth of information from anywhere in the world. This means that students no longer have to carry heavy textbooks around with them, or worry about losing them. Additionally, online resources can be constantly updated, which means that students always have access to the most up-to-date information.\nSecondly, online resources and technological innovations can provide a more engaging and interactive learning experience than traditional textbooks. For example, interactive simulations and virtual reality can help students understand complex concepts in a more intuitive and immersive way. This can help to make learning more enjoyable and effective, which is particularly important for students who may struggle with traditional teaching methods.\nIn conclusion, I believe that online resources and technological innovations are the future of education. While traditional textbooks have their place, advancements in technology have provided new opportunities for learning that cannot be ignored. By embracing these new tools and resources, we can create a more efficient, engaging, and equitable education system that benefits all individuals.', NULL, 200, 300),
  ('f17a06e2-9843-5cca-b502-ef9a451f21c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f17a06e2-9843-5cca-b502-ef9a451f21c5'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the potential benefits of alternatives when a decision is made?', 'd93a5826-957f-577c-8d56-0a81491fe045'::uuid, NULL, NULL, E'Opportunity cost', NULL, NULL),
  ('f17a90d2-a55b-5965-99e0-5d3aaf73bec3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f17a90d2-a55b-5965-99e0-5d3aaf73bec3'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a7e504a9-3593-5137-9e1a-1e982f3c699f'::uuid, NULL, E'We offer many programs and resources to help you thrive at university.', NULL, NULL, NULL),
  ('f17acadd-26aa-5b2d-b222-48e60526cc04'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f17acadd-26aa-5b2d-b222-48e60526cc04'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3e8d53f1-7f92-5d7d-b5b1-dadd010ab5d0'::uuid, NULL, NULL, E'We have to work within severe constraints of time and money.', NULL, NULL),
  ('f17b1aa8-ad04-526f-8263-5d8cefe54e0e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f17b1aa8-ad04-526f-8263-5d8cefe54e0e'::uuid, 1, NULL, TRUE, 0, NULL, E'AI', E'In today''s rapidly evolving technological landscape, the integration of artificial intelligence (AI) into various industries has become {{1}} . AI has the potential to revolutionize healthcare, transportation, and finance, among many other fields. Its ability to analyze vast amounts of data and make predictions based on patterns has the potential to improve patient outcomes, reduce traffic accidents, and optimize investment strategies. However, the widespread adoption of AI also raises important ethical {{2}} and concerns. One of the key challenges is ensuring that AI systems are developed and deployed {{3}} and responsibly. There is a need for robust regulations and guidelines to prevent bias and discrimination in AI algorithms. Additionally, the potential for job displacement due to automation requires a proactive approach to retraining the workforce. Moreover, the environmental {{4}} of AI should not be overlooked. The energy-intensive nature of AI training processes can have a significant carbon footprint, and efforts must be made to develop more energy-efficient AI models. In conclusion, while AI holds great promise, it is essential to address the ethical, regulatory, and environmental {{5}} that come with its widespread use.', NULL, NULL, NULL, E'1.transformative, 2.implications, 3.ethically, 4.footprint, 5.challenges', NULL, NULL),
  ('f17d03f9-8354-5386-8826-3a21df2b2da1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f17d03f9-8354-5386-8826-3a21df2b2da1'::uuid, 1, NULL, TRUE, 0, NULL, E'Enthusiasm', E'Enthusiasm seeks to contribute to a culturally and historically nuanced understanding of how emotions secure and ratify the truth of convictions. More than just pure affective intensity, enthusiasm is about something: a certainty, clarity or truth. Enthusiasm takes its starting point in religion, the social arena in which the concept was first debated and to which the term still gestures.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f17d3fed-472e-5deb-b0c2-70c19e9defe5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f17d3fed-472e-5deb-b0c2-70c19e9defe5'::uuid, 1, NULL, TRUE, 0, NULL, E'Nostradamus’s Prophecies', E'Some people believe that Nostradamus’s prophecies have predicted actual events. Others {{1}} that because his prophecies tend to be about general types of events that occur frequently {{2}} history — and are written in a cryptic and vague manner — it’s possible to find one that seems to {{3}} almost any event that has occurred.', NULL, NULL, NULL, E'1.maintain, 2.throughout, 3.match', NULL, NULL),
