  ('f1882645-2a7d-5c3e-b917-f5ed693d4814'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f1882645-2a7d-5c3e-b917-f5ed693d4814'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '22990fd4-4923-567c-adb7-419021b4b180'::uuid, NULL, NULL, E'I will come back to this in a moment.', NULL, NULL),
  ('f188b297-f7f1-5b16-9154-66f4cc14d507'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f188b297-f7f1-5b16-9154-66f4cc14d507'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '2a8fa51c-b31a-5b4e-8b45-49980be4358c'::uuid, NULL, NULL, E'Many people lost their jobs in the great depression.', NULL, NULL),
  ('f18f1e8b-1137-5c6d-8a89-0739495c8a63'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f18f1e8b-1137-5c6d-8a89-0739495c8a63'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'eb8e0c3f-d1eb-588e-a9dc-4dce9dac90d8'::uuid, NULL, NULL, E'Social psychology is a new area of study.', NULL, NULL),
  ('f193bdc2-e45f-5ae6-86b4-65645683362a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f193bdc2-e45f-5ae6-86b4-65645683362a'::uuid, 1, NULL, TRUE, 0, NULL, E'Subsidies', E'Governments also frequently subsidize local industries to help them compete in the global market. Subsidies come {{1}} tax credits or direct payments. The most commonly used are farm subsidies. That allows producers to lower the price of local goods and services. This {{2}} the products cheaper {{3}} when shipped overseas. Subsidies work even better than tariffs. This method works best for countries that rely mainly on exports. {{4}} sometimes subsidies can have the opposite effect. The Agricultural Adjustment Act of 1933 allowed the government to pay farmers {{5}} to grow crops or livestock, which let their fields rest and regain nutrients. It helped the agriculture industry but raised food costs during the Depression.', NULL, NULL, NULL, E'1.in the form of, 2.makes, 3.even, 4.On the contrary, 5.not', NULL, NULL),
  ('f19d6a3e-6493-59f6-bdfc-24a4ee6f4656'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'f19d6a3e-6493-59f6-bdfc-24a4ee6f4656'::uuid, 1, NULL, TRUE, 0, NULL, E'Academic Networking', E'Getting to know fellow academics, especially more senior ones, can be very daunting. Lecturers and researchers are used to spending a lot of time in isolation working independently. The thought of going public and ‘selling yourself'' does not seem enticing. However, it is easier than you think to begin to develop your own career-enhancing networks. Your PhD supervisor and examiners or if you are already in post, your mentor, are a great place to start. They will have been chosen to guide you because they are more experienced and in most cases they will work close to your field of interest. Ask their advice for ways of building up your own network of contacts. Also it is easier to approach someone unknown to you if you can mention the name of a mutual acquaintance.\nIf you are a postgraduate who is serious about a career in academia, or a more senior scholar wanting to develop one, you will surely be attending conferences on a fairly regular basis. There is no right or wrong number of these, some scholars stick to one or two a year, others seem to attend one a month! Conferences are the main way that academics network with each other, so do not miss out on these opportunities. If you are presenting a paper it gives others a chance to see what you are working on, and the informal sections of the programme (such as food and drink breaks) encourage mingling and further discussion.', NULL, NULL, E'Although getting to know fellow academics can be very daunting, it is easier to begin to develop your own career-enhancing networks because your supervisor and examiners or your mentor will be a great place to start as they are more experienced and know more people, and conferences are the main way that academics network with each other.', NULL, 5, 75),
  ('f1a0595c-f049-595f-b6f4-a5d28a010c3b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f1a0595c-f049-595f-b6f4-a5d28a010c3b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b95413d5-1e8d-5ec0-af8a-7cf118f48a62'::uuid, NULL, E'New beaches appeared, and strange sea animals came onto them.', NULL, NULL, NULL),
