  ('f1a533ee-9f06-5206-a249-305aabd3e858'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f1a533ee-9f06-5206-a249-305aabd3e858'::uuid, 1, NULL, TRUE, 0, NULL, E'Tomato', E'The tomato is probably the most widely grown {{1}} by the home gardener because of its {{2}} value, many uses, and relative ease of {{3}} . Originating in Central and South America, the tomato was domesticated in Mexico. There are many related {{4}} species in South America. “Tomati” was the name {{5}} by Native Americans.', NULL, NULL, NULL, E'1.vegetable, 2.food, 3.culture, 4.wild, 5.used', NULL, NULL),
