  ('f1bb4c4e-bbab-5dd1-9bb4-e974d2204317'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f1bb4c4e-bbab-5dd1-9bb4-e974d2204317'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the process in which a doctor finds out the illness?', '1269d4bb-2d96-50cc-befb-3847bd0ae93b'::uuid, NULL, NULL, E'Diagnosis', NULL, NULL),
  ('f1be8ba3-6bf0-56f6-80aa-5f16c0ff9df7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f1be8ba3-6bf0-56f6-80aa-5f16c0ff9df7'::uuid, 1, NULL, TRUE, 0, NULL, E'Overfishing', NULL, 'aff1e712-7c3d-5d7c-be21-41d4b729c32d'::uuid, NULL, E'Aquaculture, the farming of fish, shrimp, shellfish and seaweeds, has been the sources of human protein for nearly four thousand years, especially in Asia. In the last decade, however, there is been unprecedented growth in aquaculture production, more than 300% since 1984, which has increased the importance of the modern food supply. It’s the world’s fastest growing food production activity. And globally, more than 25% of the odd fishing and shellfish production in 1999 was attributable to aquaculture. Yes, this industry’s contributions to human diet is actually greater than the numbers imply, whereas 1/3 of the conventional fish catch is used to make fish meal and fish oil. Virtually all farmed fish are used as human food. Today, nearly 1/3 of fish consumed by human is the product of aquaculture, and that percentage will only increase as aquaculture expands the world’s conventional fish catch, for the oceans and lakes continues to decline because of overfishing and environmental damage.', NULL, NULL, NULL),
  ('f1c2354e-f94e-51af-9cc1-1b12b898794d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f1c2354e-f94e-51af-9cc1-1b12b898794d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd9dd598a-ae7d-5d3e-b244-cf794481162c'::uuid, NULL, NULL, E'Every experiment should be repeated to validate it.', NULL, NULL),
  ('f1c77e4e-8148-5f96-a37c-417c2f9520e3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f1c77e4e-8148-5f96-a37c-417c2f9520e3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'bfc50d7c-f711-57de-afe0-9427644e746b'::uuid, NULL, NULL, E'You shall be studying economies of several developing countries.', NULL, NULL),
  ('f1c93a6a-13b3-59c8-aa83-f8ac3f3cc335'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f1c93a6a-13b3-59c8-aa83-f8ac3f3cc335'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '9a15e4b8-69d6-56dc-a10c-93f9eab56aa5'::uuid, NULL, E'Students who selected two to three courses may need an extension.', NULL, NULL, NULL),
  ('f1d4b889-20fe-577b-9cdf-bb77ed434015'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f1d4b889-20fe-577b-9cdf-bb77ed434015'::uuid, 1, NULL, TRUE, 0, NULL, E'Private School', E'Private schools in the UK are redoubling their marketing efforts to foreigners. Almost a third of the 68,000 boarding pupils at such schools {{1}} come from overseas. But now, with many UK residents {{2}} or unable to afford the fees and a cultural {{3}} away from boarding, many schools are looking abroad to survive. Overseas students now {{4}} for about 500m pounds of fee income a year for boarding schools in the UK.', NULL, NULL, NULL, E'1.already, 2.unwilling, 3.shift, 4.account', NULL, NULL),
  ('f1d9f2d2-784c-55b9-8b10-355f1b03a76c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f1d9f2d2-784c-55b9-8b10-355f1b03a76c'::uuid, 1, NULL, TRUE, 0, NULL, E'Cognitive Capabilities', E'Evaluating the cognitive capabilities of various species is a complex {{1}} . How does one measure the intelligence of a crow against that of an octopus? Biologists utilize certain methodologies that don''t require active participation from the animal. A key indicator of intelligence is the encephalization quotient (EQ), which assesses an animal''s brain size relative to its body size. This metric helps to level the playing field across species, as it {{2}} for differences in overall body size. For instance, a whale''s brain is much larger than that of a cat, but this is {{3}} to its massive body size. When using the encephalization quotient, humans {{4}} as the most intellectually advanced, followed closely by other primates, cetaceans like dolphins and whales, and certain bird species like crows and parrots. It''s also observed that {{5}} animals (such as felines and birds of prey) generally exhibit higher intelligence than herbivores. This is because hunting requires complex strategies and problem-solving skills.', NULL, NULL, NULL, E'1.endeavor, 2.accounts, 3.proportionate, 4.emerge, 5.predatory', NULL, NULL),
  ('f1e27fe1-7005-5d9b-9ddd-b35d8bb78e39'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'f1e27fe1-7005-5d9b-9ddd-b35d8bb78e39'::uuid, 1, NULL, TRUE, 0, NULL, E'Megafire', NULL, NULL, NULL, NULL, E'2, 4, 3, 1', NULL, NULL),
  ('f1ebc42a-7a41-54bd-ac35-aa296f01b8df'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f1ebc42a-7a41-54bd-ac35-aa296f01b8df'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Jack is having a presentation on Wednesday. Today is Tuesday. When will Jack have his speech, today, tomorrow or next week?', '1166dac8-e683-54c4-8cfc-b14be60ac5ac'::uuid, NULL, NULL, E'Tomorrow', NULL, NULL),
  ('f1ec6887-7f53-5b65-b357-fd3e867ad855'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f1ec6887-7f53-5b65-b357-fd3e867ad855'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '855b5b6b-9f3e-5ba3-9ba5-21ebae29fa6b'::uuid, NULL, NULL, E'All students are allowed to take the notes from the library.', NULL, NULL),
  ('f1f4b8ae-62ce-59e8-9310-29425bbc2d5c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f1f4b8ae-62ce-59e8-9310-29425bbc2d5c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '30c5a766-1a3a-5579-9fd1-c2a332bceccb'::uuid, NULL, NULL, E'You are advised to submit all the dissertations.', NULL, NULL),
  ('f1faff0e-f4de-5f1e-930c-6442fad1d3f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f1faff0e-f4de-5f1e-930c-6442fad1d3f0'::uuid, 1, NULL, TRUE, 0, NULL, E'World Heating Up', E'Comforting thoughts, perhaps. Unfortunately, however, the Earth has some discomforting news. From Alaska to the snowy peaks of the Andes the world is heating up right now, and fast. Globally, the {{1}} is up 1°F over the past century, but some of the coldest, most remote spots have warmed much more. The results aren''t pretty. Ice is {{2}} , rivers are running dry, and coasts are {{3}} , threatening communities.', NULL, NULL, NULL, E'1.temperature, 2.melting, 3.eroding', NULL, NULL),
  ('f1fdb662-3a57-527c-81c7-d465fc44ab80'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f1fdb662-3a57-527c-81c7-d465fc44ab80'::uuid, 1, NULL, TRUE, 0, NULL, E'Cinemas', E'The cinema did not {{1}} as a form of mass consumption until its technology {{2}} from the initial “peepshow” format to the point where images were {{3}} on a screen in a darkened theater. In the peepshow format, a film was viewed {{4}} a small opening in a machine that was created for that purpose.', NULL, NULL, NULL, E'1.emerge, 2.evolved, 3.projected, 4.through', NULL, NULL),
  ('f200060d-6066-5f1c-9cd2-45569a5429b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f200060d-6066-5f1c-9cd2-45569a5429b8'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '37f7bb2f-3f75-5958-a46c-982d78e04a6d'::uuid, NULL, NULL, E'We were asked to estimate the costs for the scheme.', NULL, NULL),
  ('f2079cc2-8ee0-540b-84eb-742f45cd31f5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f2079cc2-8ee0-540b-84eb-742f45cd31f5'::uuid, 1, NULL, TRUE, 0, NULL, E'Shoestring Budget', E'All the works of art shown in this exhibition were purchased on a shoestring budget. The criteria that the curators had to follow were that works must be acquired cheaply, appeal to a broad range of tastes, and fit with unusual environments. Thus, many of our better known modern artists are not represented.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f2187e48-644b-5166-a99e-bd62ecb05c58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'HIGHLIGHT_CORRECT_SUMMARY', E'HIGHLIGHT_CORRECT_SUMMARY', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f2187e48-644b-5166-a99e-bd62ecb05c58'::uuid, 1, NULL, TRUE, 0, NULL, E'Palliative Care', E'All the evidence that is related to palliative care these days demonstrates with absolute certainty people live better and live longer. There was a seminal article out of the New England Journal of Medicine in 2010. A study done at Harvard by friends of mine, colleagues. End-stage lung cancer: one group with palliative care, a similar group without. The group with palliative care reported less pain, less depression. They needed fewer hospitalizations. And, ladies and gentlemen, they lived three to six months longer. If palliative care were a cancer drug, every cancer doctor on the planet would write a prescription for it. Why don’t they? This is a space that we will all come to at some point. But this conversation today is not about dying, it is about living. Living based on our values, what we find sacred and how we want to write the chapters of our lives, whether it’s the last or the last five.\n\nClick on the paragraph that best relates to the recording.', 'b4ed3201-0b0d-5f8f-9e14-57b296d05615'::uuid, NULL, NULL, E'Evidence has shown that palliative care can help patients experience less pain and depression. They can also live longer up to six months with palliative care.', NULL, NULL),
  ('f2194f45-54df-5e40-9428-76ff552c90d9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f2194f45-54df-5e40-9428-76ff552c90d9'::uuid, 1, NULL, TRUE, 0, NULL, E'Surface Water', E'Chemicals used to control weeds in crops such as corn and soybeans may sometimes run off farmland and enter surface water bodies such as lakes and streams. If a surface water body that is used as a {{1}} water supply receives excess amounts of these herbicides, then the municipal water treatment plant must {{2}} them out in order for the water to be safe to drink. This added filtration process can be expensive. Farmers can help control excess herbicides in runoff by choosing chemicals that bind with {{3}} more readily, are less toxic, or degrade more quickly. Additionally, selecting the best tillage practice can help minimize herbicide {{4}} .', NULL, NULL, NULL, E'1.drinking, 2.filter, 3.soil, 4.pollution', NULL, NULL),
  ('f219e9cd-a7ff-510b-96fc-00cc2cd24130'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f219e9cd-a7ff-510b-96fc-00cc2cd24130'::uuid, 1, NULL, TRUE, 0, NULL, E'Vaccine Drives', E'A year ago, vaccine drives against COVID-19 were just beginning. Now, more than 4.4 billion people have had one or more {{1}} — about 56% of the world population. The vaccination of so many in such a short {{2}} of time, so soon after the {{3}} rapid development of the vaccines, has saved huge numbers of lives and is a {{4}} for science and research.', NULL, NULL, NULL, E'1.dose, 2.space, 3.unparalleled, 4.triumph', NULL, NULL),
  ('f21a95c0-1974-5edf-b2e0-6b93b49dd051'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f21a95c0-1974-5edf-b2e0-6b93b49dd051'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3f75548a-bb06-579a-b692-0e6f15063b63'::uuid, NULL, NULL, E'The universities provide excellent leisure facilities for students and staff.', NULL, NULL),
  ('f21fab6c-9cd2-549f-8b9c-35a3607b6a73'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f21fab6c-9cd2-549f-8b9c-35a3607b6a73'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '13fd2195-42d3-5262-8f4f-84be0e01c84d'::uuid, NULL, NULL, E'The government will continue to offer financial aids to students.', NULL, NULL),
  ('f220c6b5-a95f-5a56-bd50-b55e7181d8c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f220c6b5-a95f-5a56-bd50-b55e7181d8c8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Where would you most likely go to buy some flour, a bakery, a florist or a supermarket?', '5dd8b248-e8c0-5adf-bc95-3353f4629b9e'::uuid, NULL, NULL, E'Supermarket', NULL, NULL),
  ('f2286709-b0b1-5be1-8d13-4756685c2d05'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f2286709-b0b1-5be1-8d13-4756685c2d05'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '389e369b-a3a1-543d-877d-e03c089a562c'::uuid, NULL, NULL, E'A laptop computer has been found in the biology lab.', NULL, NULL),
  ('f22c0ad1-a65d-51d9-86dd-93e03ab6f645'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f22c0ad1-a65d-51d9-86dd-93e03ab6f645'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'dc3612e0-6ecb-5b2a-a991-2ee154ec99f5'::uuid, NULL, NULL, E'Most of these characteristics were components of the previous system.', NULL, NULL),
  ('f2329b7a-e591-5fba-a7b6-b4615f690555'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f2329b7a-e591-5fba-a7b6-b4615f690555'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of ground military forces?', 'cc4b23a6-aa66-5208-b573-0758cb5b1a0c'::uuid, NULL, NULL, E'Army', NULL, NULL),
  ('f23a61c1-c454-53ba-b433-b362b21d23be'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f23a61c1-c454-53ba-b433-b362b21d23be'::uuid, 1, NULL, TRUE, 0, NULL, E'Stock Market', NULL, '433b3a1b-096e-54e3-85d3-2f6f8997ebd5'::uuid, NULL, E'So how do companies and investors use the market today? Let’s imagine a new coffee company that decides to launch on the market. First, the company will advertise itself to big investors. If they think the company is a good idea, they get the first crack at investing, and then sponsor the company’s initial public offering, or IPO. This launches the company onto the official public market, where any company or individual who believes the business could be profitable might buy a stock. Buying stocks makes those investors partial owners in the business. Their investment helps the company to grow and as it becomes more successful, more buyers may see potential and start buying stocks. As demand for those stocks increases, so does their price, increasing the cost for prospective buyers, and raising the value of the company’s stocks people already own. For the company, this increased interest helps fund new initiatives, and also boosts its overall market value by showing how many people are willing to invest in their idea. However, if for some reason the company starts to seem less profitable, the reverse can also happen. If investors think their stock value is going to decline, they’ll sell their stocks with the hopes of making a profit before the company loses more value. As stocks are sold and demand for the stock goes down, the stock price falls, and with it, the company’s market value. This can leave investors with big losses–unless the company starts to look profitable again.', NULL, NULL, NULL),
  ('f23c1526-5a76-54ff-b26c-fc710c3b3eb5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f23c1526-5a76-54ff-b26c-fc710c3b3eb5'::uuid, 1, NULL, TRUE, 0, NULL, E'Culprit Fungi', E'As climate change brings more wildfires to the western United States, a rare fungal infection, valley fever, has also been on the rise. It causes coughs, fevers and chest pain and can be deadly. The culprit fungi thrive in soils in California and the desert Southwest. Wildfires appear to stir up and send the soil-loving fungi into the air, where they can enter people’s lungs.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f23e1063-6aa3-5126-b657-3c2bb43e3696'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f23e1063-6aa3-5126-b657-3c2bb43e3696'::uuid, 1, NULL, TRUE, 0, NULL, E'Marshmallow Test', E'By now a lot has been said about the marshmallow test. You guys probably know about this where children are asked you can eat this one marshmallow now or if you wait until I come back you can get two marshmallows. People talk about this in terms of the resolution that little kids have and how good they are at resisting temptation and stuff but there’s something that’s often overlooked here which is that one of the most common strategies that kids use was simply covering their eyes. Just clapping their hands over their eyes so they’re not looking at the marshmallow. And it turns out that’s a very effective strategy. And so when we think about minimizing temptations whatever your temptations are in life just think about the ways that you can actually contractually minimize that temptation so it’s not there, not a fake thing or anything. Oh yeah, if it’s in the back of the cabinet I won’t do it but like actually get rid of the...\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', 'fce7efa2-ea5a-5698-a7bd-51c9bd1c8fb6'::uuid, NULL, NULL, E'temptation', NULL, NULL),
  ('f23ec72b-d5b9-5e94-845b-cdbfb45cf7e7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f23ec72b-d5b9-5e94-845b-cdbfb45cf7e7'::uuid, 1, NULL, TRUE, 0, NULL, E'Political Science', E'I have a problem with my political science class. Literally. I know nothing about it and regret taking it. I should have dropped the class. Calm down. James students take classes to learn. I know. But I am so clueless. I am just not so into the politics constitution and laws and again the words are so confusing to me. Jane, let me tell you something based on my experience. You just need to try. You know the words may sound difficult, but they are not at all that difficult. Once you get familiar with the vocabulary basic laws and events political science is a very interesting and easy subject. On top of that. You have me to help you. Do you really think so yes, i''m sure everything''s up to you. If you think positively and put effort into it, everything will become easy.\n\nWhat does the man suggest that the woman do to do well in political science?', 'a368b495-2e60-5505-beb4-590a2ed52047'::uuid, NULL, NULL, E'Concentrate on vocabulary, laws, and events', NULL, NULL),
  ('f2423231-a152-5f0d-9120-45471d094933'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f2423231-a152-5f0d-9120-45471d094933'::uuid, 1, NULL, TRUE, 0, NULL, E'Concept of Culture', E'Many people today think of culture in the way that it was thought of in Europe during the 18th and early 19th centuries. This {{3}} of culture reflected inequalities within European societies and their colonies around the world. This understanding of culture equates culture with civilization and contrasts both with nature or non-civilization. According to this understanding of culture, some countries are more civilized than others, and some people are more cultured than others. Anything that doesn’t fit into this category is labeled as chaos or anarchy. From this perspective, culture is closely tied to cultivation, which is the progressive refinement of human {{1}} .\nIn practice, culture referred to elite goods and activities such as haute cuisine, high fashion or haute couture, museum-caliber art and classical music. The word cultured referred to people who knew about and took part in these activities. For example, someone who used culture in this sense might {{2}} that classical music is more refined than music by working-class people, such as jazz or the indigenous music traditions of aboriginal peoples.', NULL, NULL, NULL, E'1.concept, 2.behavior, 3.argue', NULL, NULL),
  ('f243f15a-dbbb-536c-9106-213a21032edc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f243f15a-dbbb-536c-9106-213a21032edc'::uuid, 1, NULL, TRUE, 0, NULL, E'Divorce in Australia', E'In 2005, 109,000 new marriages were registered in Australia. This was equivalent to 5.4 marriages for every 1,000 people in the population. This rate has been in an overall {{1}} since 1986 when there were 7.2 marriages per 1,000 people. Over the same period, the {{2}} divorce rate has remained relatively unchanged with 2.6 divorces for every 1,000 people in 2005 and 2.5 divorces per 1,000 people in 1986. The {{3}} annual number of divorces occurred in 2001 when there were 55,300 divorces recorded. This peak has been followed by recent declines, with 52,400 divorces in 2005.\nAs well as marrying less, Australians are {{4}} to marry later than in the past. In 1986, the median age at first marriage for men was 25.6 years, increasing to 30.0 years in 2005. For women, the median age at first marriage increased from 23.5 years in 1986 to 28.0 years in 2005.\nPeople are also divorcing at older ages. In 2005, the median age of divorcing men was 43.5 years, compared with 37.5 years in 1986, while for women the median age in 2005 was 40.8 compared with 34.7 years in 1986. The decline in marriage rates and increase in divorce rates has led to a decrease in the {{5}}\nof the population that is formally married. In 1986, 60% of the population aged 15 years and over were married; by 2001 this proportion had decreased to 55%. {{6}} , the proportion of the population aged 15 years and over who were never married increased from 29% in 1986 to 32% in 2001.', NULL, NULL, NULL, E'1.decrease, 2.crude, 3.greatest, 4.tending, 5.level, 6.Conversely', NULL, NULL),
  ('f24b3e75-6048-5751-9689-98e19c410b46'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f24b3e75-6048-5751-9689-98e19c410b46'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'e6ab257a-1a91-5ba4-b007-713051bf3058'::uuid, NULL, E'You will need a great deal of money to purchase the valuable painting.', NULL, NULL, NULL),
  ('f25f82bb-6ed9-5ee6-a0c5-d4969d9f2086'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'f25f82bb-6ed9-5ee6-a0c5-d4969d9f2086'::uuid, 1, NULL, TRUE, 0, NULL, E'Banana', NULL, NULL, NULL, NULL, E'4, 2, 1, 3', NULL, NULL),
  ('f26211f2-6675-5e82-a675-c12480938133'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_MULTIPLE', E'MC_LISTENING_MULTIPLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f26211f2-6675-5e82-a675-c12480938133'::uuid, 1, NULL, TRUE, 0, NULL, E'Heyday', E'The heyday of the English landscape garden was the 18th century, and it stood for many things: the appreciation of natural beauty, of course, but also the idea of a civilized life, good taste, one''s personal philosophy, and one''s social status. Gardens also - though it is hard for us to credit - became expressions of their owners'' political affiliations. Until the picturesque style emerged as part and parcel of the Romantic Movement, gardens had been strictly formal, laid out with mathematical precision following the Italian and French examples. There then came a backlash against this rigid formality, led by, among others, the poet Alexander Pope. Pope and his allies argued for a more natural nature.\nLord Burlington was a major figure in the landscape garden movement, and he was famously influenced by his love of the Italian architect, Andrea Palladia, along with the picturesque or romanticized landscapes of Italian classical painting. With these in mind, he scattered his gardens and parks with classical Greek and Roman temples and statues. In other words, he wanted to make the garden look like those paintings.\n\nWhich of the following are mentioned as influences on the English landscape garden?', '3cadb143-7bfb-5e80-9a77-9db905d5aa03'::uuid, NULL, NULL, E'The Romantic Movement\nItalian classical painting', NULL, NULL),
  ('f2630739-1ce1-554c-9c56-2d0605b8ede4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f2630739-1ce1-554c-9c56-2d0605b8ede4'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '67b7c415-ac8c-5282-bdc1-17bc993077c5'::uuid, NULL, E'Forthcoming events are listed on the page of the local newspaper.', NULL, NULL, NULL),
  ('f26b2f88-915a-5cb0-b018-49792431b05c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f26b2f88-915a-5cb0-b018-49792431b05c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '710910f3-e7bb-5a62-8cb5-a1a410dc4916'::uuid, NULL, E'I wrote to them last month and I''m still waiting for a reply.', NULL, NULL, NULL),
  ('f26c5930-f85f-55ad-87ad-fd583eda0da2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f26c5930-f85f-55ad-87ad-fd583eda0da2'::uuid, 1, NULL, TRUE, 0, NULL, E'Role of Surrounding', E'For as long as society has existed, we’ve understood the role of surrounding influences on our decision-making. With idioms like “It takes a village to raise a child” and “You are the product of your environment,” we understand that to a great extent our upbringing, our parents and the society we grew up in influence our decision making process.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f2771c66-a5f6-5f8e-9dac-4ca6e4b6392d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f2771c66-a5f6-5f8e-9dac-4ca6e4b6392d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '66c5074b-ef72-5c5c-8894-69a48bbec749'::uuid, NULL, NULL, E'Active people usually live longer and don''t get sick.', NULL, NULL),
  ('f27b7f7c-1b6c-563b-b690-300ad0dd3c1f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f27b7f7c-1b6c-563b-b690-300ad0dd3c1f'::uuid, 1, NULL, TRUE, 0, NULL, E'An Act', E'The Nature Conservation Amendment Act of 1996 enables the Minister of Environment and Tourism to register a conservancy if it has a {{2}} committee, a legal constitution, which provides for the sustainable {{3}} and utilization of game in the conservancy, the ability to {{4}} the funds, an approved method for the {{1}} distribution of benefits to members of the community and defined boundaries.', NULL, NULL, NULL, E'1.representative, 2.management, 3.manage, 4.equitable', NULL, NULL),
  ('f27c0c3f-e396-5f01-8556-6f006d335916'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f27c0c3f-e396-5f01-8556-6f006d335916'::uuid, 1, NULL, TRUE, 0, NULL, E'Beauty', E'Beauty is subjective, and as such it of course cannot be defined in absolute terms. But we all know or feel when something is beautiful to us personally. And in such instances, methods of physics and network science can be used to quantify and help us better understand what it is that evokes that pleasant feeling.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f27cba21-5fab-5b7b-8b5a-2d651412a201'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f27cba21-5fab-5b7b-8b5a-2d651412a201'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8e147752-10fc-57e0-aaab-d05e6b0a5236'::uuid, NULL, NULL, E'This advanced course requires a basic knowledge of economic theory.', NULL, NULL),
  ('f27d2794-aa37-504a-9a61-80e7fdb5504b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f27d2794-aa37-504a-9a61-80e7fdb5504b'::uuid, 1, NULL, TRUE, 0, NULL, E'Underwater Treadmill', NULL, 'f2899fff-1922-55d6-a2c0-1dedd2d0df66'::uuid, NULL, E'Located at the NASA Research Center in Iowa is a 5,000-gallon vat of water, and inside the tank is an underwater treadmill designed by Dava Newman, an aerospace engineer. For four years Newman observed scuba divers as they simulated walking on the Moon and on Mars on her underwater moving belt. She wanted to discover how the gravity of the Moon and of Mars would affect human movement. To do this, Newman attached weights to the divers and then lowered them into the tank and onto the treadmill. These weights were carefully adjusted so that the divers could experience underwater the gravity of the Moon and of Mars as they walked on the treadmill. Newman concluded that walking on Mars will probably be easier than walking on the Moon. The Moon has less gravity than Mars does, so at lunar gravity, the divers struggled to keep their balance and walked awkwardly. But at Martian gravity, the divers had greater traction and stability and could easily adjust to a pace of 1.5 miles per hour. As Newman gradually increased the speed of the treadmill, the divers took longer, graceful strides until they comfortably settled into an even quicker pace. Newman also noted that at Martian gravity, the divers needed less oxygen. The data Newman collected will help in the future design of Martian space suits. Compared to lunar space suits, Martian space suits will require smaller air tanks; and, to allow for freer movement, the elbow and knee areas of the space suits will also be altered.', NULL, NULL, NULL),
  ('f2820fa6-2e68-55e4-a53d-f3dd542698e8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'f2820fa6-2e68-55e4-a53d-f3dd542698e8'::uuid, 1, NULL, TRUE, 0, NULL, E'Football Match', NULL, NULL, NULL, NULL, E'3, 5, 1, 4, 2', NULL, NULL),
