  ('f2a71ad2-5bbd-5a9b-a3ee-2cb54c340390'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f2a71ad2-5bbd-5a9b-a3ee-2cb54c340390'::uuid, 1, NULL, TRUE, 0, NULL, E'Charles Darwin', E'Charles Darwin knew intuitively that tropical forests were places of {{1}} intricacy and energy. He and his cohort of scientific naturalists were {{2}} by the beauty of the Neotropics, where they collected tens of thousands of {{3}} new to science. But they couldn''t have guessed at the complete contents of the rainforest, and they had no idea of its {{4}} to humankind.', NULL, NULL, NULL, E'1.tremendous, 2.awed, 3.species, 4.value', NULL, NULL),
