  ('f2bbe6b7-d1bc-550b-9cc1-6726ea5ce379'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f2bbe6b7-d1bc-550b-9cc1-6726ea5ce379'::uuid, 1, NULL, TRUE, 0, NULL, E'Teenage Daughter', E'Your teenage daughter gets top marks in school, captains the debate team, and volunteers at a shelter for homeless people. But while driving the family car, she text-messages her best friend and rear-ends another vehicle.\nHow can teens be so clever, accomplished, and responsible-and reckless {{1}} ? Easily, according to two physicians at Children''s Hospital Boston and Harvard Medical School (HMS) who have been {{2}} the {{3}} structure and chemistry of the {{4}} brain. "The teenage brain is not just an adult brain with fewer miles on it," says Frances E. Jensen, a professor of neurology. "It''s a paradoxical time of {{5}} . These are people with very {{6}} brains, but they''re not quite sure what to do with them."\nResearch during the past 10 years, powered by technology such as functional magnetic resonance imaging, has revealed that young brains have {{7}} fast-growing synapses and sections that remain unconnected.', NULL, NULL, NULL, E'1.at the same time, 2.exploring, 3.unique, 4.adolescent, 5.development, 6.sharp, 7.both', NULL, NULL),
  ('f2cb4742-578f-5984-a565-2e0969714f5d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f2cb4742-578f-5984-a565-2e0969714f5d'::uuid, 1, NULL, TRUE, 0, NULL, E'Gender Equality', E'With the popularity of the gender equality campaign and the cultural change, the {{1}} roles of men as the {{2}} , and of women in which they stay at home, are {{3}} today.', NULL, NULL, NULL, E'1.traditional, 2.earner, 3.challenged', NULL, NULL),
