  ('f2f91f99-b841-57b8-8357-2c0f1d3f8425'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f2f91f99-b841-57b8-8357-2c0f1d3f8425'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'a8c8cda6-1f60-5793-9497-f3860f93b972'::uuid, NULL, E'We offer many express delivery options for a small additional charge.', NULL, NULL, NULL),
