  ('f33e9d70-ed21-5a4c-8317-91e825706190'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f33e9d70-ed21-5a4c-8317-91e825706190'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4e4cb209-8b2a-597a-a95a-ac5df6cfa07c'::uuid, NULL, E'The history department is part of the College of Arts and Sciences.', NULL, NULL, NULL),
  ('f33f5ad9-2a0d-5e0f-a575-fb522d747d65'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f33f5ad9-2a0d-5e0f-a575-fb522d747d65'::uuid, 1, NULL, TRUE, 0, NULL, E'Teaching of Languages', E'The teaching of languages could be revolutionised following ground-breaking research by Victoria University, New Zealand, PhD graduate Paul Sulzberger. Dr Sulzberger has found that the best way to learn a language is through frequent exposure to its sound patterns--even if you haven''t a {{1}} what it all means. "However crazy it might sound, just listening to the language, {{2}} you don''t understand it, is critical. A lot of language teachers may not accept that," he says. "Our ability to learn new words is directly related to how often we have been exposed to the particular combinations of the sounds which make {{3}} the words. If you want to learn Spanish, for example, frequently listening to a Spanish language radio station on the internet will dramatically {{4}} your ability to pick up the language and learn new words." Dr Sulzberger''s research challenges existing language learning theory. His main hypothesis is that simply listening to a new language sets up the structures in the brain {{5}} to learn the words.', NULL, NULL, NULL, E'1.clue, 2.even though, 3.up, 4.boost, 5.required', NULL, NULL),
  ('f34c3c10-c6a0-539d-b6f8-be1afcab8668'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f34c3c10-c6a0-539d-b6f8-be1afcab8668'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '11369b8e-d5fb-5e1a-b998-8f6fe77afbf2'::uuid, NULL, E'Are you supposed to complete the assignment without any help from others?', NULL, NULL, NULL),
