  ('f3678209-4de2-56f7-a8a8-f179ed9ca95d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f3678209-4de2-56f7-a8a8-f179ed9ca95d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '469e81f6-4db9-50e6-96af-91e9b769025f'::uuid, NULL, NULL, E'I truly believe it''s among the best actions I''ve ever taken.', NULL, NULL),
  ('f36c08b4-5f0d-5856-8283-145fc78f786e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f36c08b4-5f0d-5856-8283-145fc78f786e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e6331905-e1ca-51f6-bc7b-3e9a293413f4'::uuid, NULL, NULL, E'The history of Asia is thoroughly studied in these regions.', NULL, NULL),
  ('f3721e8a-bb01-52b3-af07-42427023c26d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'f3721e8a-bb01-52b3-af07-42427023c26d'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-R', E'Mars Global Surveyor is the oldest of five NASA robotic devices, which is designed to find out signs that Mars once had water; and it had been taking detailed pictures of the red planet for a decade. Unfortunately, it stopped working on November 2 after it developed a motor problem. After two days of silence, ground control teams received a signal that the device had put itself into an emergency standby mode. There was no information about what had gone wrong. Since then, the mission team at NASA''s laboratory in California has tried to contact the device. This week, NASA engineers are preparing for what may be their last chance to recover the spacecraft. NASA plans to use a newly arrived device to take a picture of the Surveyor to see how the failed craft is oriented to the sun for power and to Earth for communications. It is reported that the picture will be taken on Friday when the satellites are about 93 miles apart. The new high-powered camera should be able to image details of the Surveyor as small as about 10 centimeters. There is a good chance of recovering it.\n\nThe main task of Mars Global Surveyor is', NULL, NULL, NULL, E'to find out if there was water on Mars.', NULL, NULL),
  ('f374ebf8-ea84-5150-be6f-c22d5f9de596'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'f374ebf8-ea84-5150-be6f-c22d5f9de596'::uuid, 1, NULL, TRUE, 0, NULL, E'Bank Overdraft', E'Banks provide short-term finance to companies in the form of an overdraft on a current account. The advantage of an overdraft is its flexibility. When the cash needs of the company increase with seasonal factors, the company can continue to write cheques and watch the overdraft increase. When the goods and services are sold and cash begins to flow in, the company should be able to watch the overdraft decrease again. The most obvious example of a business which operates in this pattern is farming. The farmer uses the overdraft to finance the acquisition of seed for arable farming, or feed through the winter for stock farming and to cover the period when the crops or animals are growing and maturing. The overdraft is reduced when the crops or the animals are sold.\nThe main disadvantage of an overdraft is that it is repayable on demand. The farmer whose crop fails because of bad weather knows the problem of being unable to repay the overdraft. Having overdraft financing increases the worries of those who manage the company. The other disadvantage is that the interest payable on overdrafts is variable. When interest rates increase, the cost of the overdraft increases. Furthermore, for small companies there are often complaints that the rate of interest charged is high compared with that available to larger companies. The banks answer that the rates charged reflect relative risk and it is their experience that small companies are more risky.', NULL, NULL, E'Banks provide short-term finance to companies in the form of an overdraft on a current account, whose advantage is its flexibility, but the main disadvantage of an overdraft is that it is repayable on demand, and the interest payable on overdrafts is variable, while for small companies, there are often complaints that the rate of interest charged is high compared with that available to larger companies.', NULL, 5, 75),
  ('f375f5d4-d4e4-500a-8acc-54e910c28e62'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f375f5d4-d4e4-500a-8acc-54e910c28e62'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f2879f8a-fb69-5e77-9647-91ccdc004eb7'::uuid, NULL, NULL, E'She used to be the editor of the student newspaper.', NULL, NULL),
  ('f3769505-c7b1-5058-b12f-1568cb6ca744'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f3769505-c7b1-5058-b12f-1568cb6ca744'::uuid, 1, NULL, TRUE, 0, NULL, E'Rhetorical Context', E'In college, reading is active rather than passive. Instead of {{1}} receiving information and ideas through reading, college students must act upon the information they are reading. Furthermore, college students must consider the {{2}} context in which the material they are reading was {{3}} as well as the rhetorical context in which they will read and respond.', NULL, NULL, NULL, E'1.merely, 2.rhetorical, 3.composed', NULL, NULL),
  ('f376ae6b-12a8-5427-8e86-4410c58767c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f376ae6b-12a8-5427-8e86-4410c58767c0'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '03542a5a-4747-5afc-9366-bcd392b2592a'::uuid, NULL, E'Most teenagers start taking drugs because of boredom.', NULL, NULL, NULL),
  ('f377f1cd-3bf4-5faa-9663-12672689accf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f377f1cd-3bf4-5faa-9663-12672689accf'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How many hemispheres does the equator divide earth into?', '6397356f-f242-5fea-9ea6-21ba325acf64'::uuid, NULL, NULL, E'Two', NULL, NULL),
  ('f37ae6e6-f4bb-5494-9940-dac85503f7b5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f37ae6e6-f4bb-5494-9940-dac85503f7b5'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5a3f76e2-4671-579a-8178-06f5c7f2ec1d'::uuid, NULL, NULL, E'Numerous studies confirm the Earth''s temperatures are steadily increasing.', NULL, NULL),
  ('f37dae90-8f32-551c-ae69-8a19feeaded6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f37dae90-8f32-551c-ae69-8a19feeaded6'::uuid, 1, NULL, TRUE, 0, NULL, E'Low Literacy', E'In order to {{1}} the widespread problem of low literacy, educators and policymakers must first understand why so many students struggle to read. One reason is undiagnosed reading disabilities such as dyslexia or other brain-based learning difficulties, which are more effectively addressed when identified in children as early as kindergarten and ideally before the second grade. Environmental factors such as low {{2}} to literature or language barriers can also limit reading success. Many experts also argue that a major {{3}} factor is the lack of training teachers receive in identifying children who are at risk of reading failure and in building oral language and linguistic skills. Additionally, teachers may not receive explicit instruction on how to teach reading skills, and existing reading curricula often do not {{4}} with the current science on how students learn. Studies suggest that {{5}} the science of reading practices studied by psychologists, linguists, and neurobiologists into the classroom will dramatically reduce the number of children who are on track to become functionally illiterate adults.', NULL, NULL, NULL, E'1.address, 2.exposure, 3.contributing, 4.align, 5.incorporating', NULL, NULL),
  ('f381d067-5541-59e2-9614-a83384a915af'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'f381d067-5541-59e2-9614-a83384a915af'::uuid, 1, NULL, TRUE, 0, NULL, E'Historical Context', NULL, NULL, NULL, NULL, E'4, 2, 5, 3, 1', NULL, NULL),
