  ('f3a9b259-8be4-56af-bf1b-dc38968c62d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f3a9b259-8be4-56af-bf1b-dc38968c62d3'::uuid, 1, NULL, TRUE, 0, NULL, E'Hurricane Harvey', E'The human toll of Hurricane Harvey is staggering, with 68 direct deaths and 35 indirect deaths attributed to the storm. The loss of life is a sobering reminder of the destructive power of such natural disasters. But beyond the lives lost, the impact on those who survived the storm cannot be overstated.', NULL, NULL, NULL, NULL, NULL, NULL),
