  ('f3af8c89-60d5-5c8c-ad98-fc25cfdcf8c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f3af8c89-60d5-5c8c-ad98-fc25cfdcf8c5'::uuid, 1, NULL, TRUE, 0, NULL, E'Civil War', E'A new study comprehensively reveals how civil wars impact wildlife in countries affected by conflict. Researchers found that the main impacts of civil wars on native mammals are often indirect, ultimately arising from institutional and socio-economic changes, rather than from direct military tactics.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f3b34c8a-c216-5029-8817-2bd2e33de32e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f3b34c8a-c216-5029-8817-2bd2e33de32e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '02a47dd8-2d7b-59e7-bac2-8a4f0e2eaf87'::uuid, NULL, NULL, E'The teacher tested the children on their homework.', NULL, NULL),
