  ('f3bf0279-1f44-5c74-8f6c-150dfbe515e7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f3bf0279-1f44-5c74-8f6c-150dfbe515e7'::uuid, 1, NULL, TRUE, 0, NULL, E'Jazz', E'Early jazz musicians were active in many cities and towns throughout the southern United States. It was new Orleans with its long tradition of african american music that was the home of many fathers of jazz. After world war one, the musicians of new Orleans joined the general northward migration of African Americans. The first great national center of jazz was chicago. From there, the music entered the mainstream and even gave its name to the decade of the nineteen twenties. Jazz blending African American folk roots with elements of popular music and European classical traditions has been called America....\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '652cbd4b-b435-580d-9572-4b59b2ce9951'::uuid, NULL, NULL, E'classical music', NULL, NULL),
  ('f3c079c2-3431-535c-9ba6-dc8fd3bcdff2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f3c079c2-3431-535c-9ba6-dc8fd3bcdff2'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the term used for the principal male character opposite a hero in a movie or a story?', '0b519113-e00f-5153-92a3-a9f1c15dd0b0'::uuid, NULL, NULL, E'Villain / Antagonist / devil / monster', NULL, NULL),
  ('f3c3892b-1032-5e4b-9911-5d1f3a3397c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f3c3892b-1032-5e4b-9911-5d1f3a3397c0'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5c95fb15-b5ed-51ec-8aec-a994913a6fc5'::uuid, NULL, NULL, E'These buildings are part of our national heritage and deserve protection.', NULL, NULL),
  ('f3c4a891-352c-5ad7-8825-211e516dda10'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f3c4a891-352c-5ad7-8825-211e516dda10'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the policy of extending a country''s power through diplomacy or military force?', '91f65ea1-d65b-5088-8694-f9ec2b4f002e'::uuid, NULL, NULL, E'Imperialism', NULL, NULL),
  ('f3cb1644-c325-561f-a832-0edc15a8450a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f3cb1644-c325-561f-a832-0edc15a8450a'::uuid, 1, NULL, TRUE, 0, NULL, E'Crime Prevention', E'Crime prevention has a long history in Australia, and in other parts of the world. In all societies, people have tried to {{4}} themselves and those close to them from assaults and other abuses. Every time someone locks the door to their house or their car, they practise a {{3}} of prevention. Most parents want their children to learn to be law abiding and not spend extended periods of their lives in prison. In this country, at least, most succeed. Only a small minority of young people become {{1}} offenders. In a functioning society, crime prevention is part of everyday life. While prevention can be all- {{5}} at the grassroots, it is oddly neglected in mass media and political discourses .When politicians, talkback radio hosts and newspaper editorialists pontificate about crime and {{2}} remedies, it is comparatively rare for them to mention prevention. Overwhelmingly, emphasis is on policing, sentencing and other ''law and order'' responses.', NULL, NULL, NULL, E'1.protect, 2.form, 3.recidivist, 4.pervasive, 5.possible', NULL, NULL),
  ('f3ce201a-c0ef-5547-920c-c0a2c35e6e1e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f3ce201a-c0ef-5547-920c-c0a2c35e6e1e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What document does a student get when graduating from the university?', '432a6c2b-724e-5b00-8a5d-ce4e692de30d'::uuid, NULL, NULL, E'Graduation certificate', NULL, NULL),
