  ('f46b1e75-f928-5321-be49-ccbddc6dfcba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f46b1e75-f928-5321-be49-ccbddc6dfcba'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How often does a biennial convention take place?', '438b7781-899e-558a-942d-bbd9b371c445'::uuid, NULL, NULL, E'Every two years', NULL, NULL),
  ('f470884f-7bdc-5208-9bb1-123aa5dd95f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f470884f-7bdc-5208-9bb1-123aa5dd95f0'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '3972e198-d273-53fb-8d30-783f2df2158f'::uuid, NULL, NULL, E'The restaurants are down the hall and to the right.', NULL, NULL),
  ('f4716590-08ed-552d-a267-353f688e6447'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f4716590-08ed-552d-a267-353f688e6447'::uuid, 1, NULL, TRUE, 0, NULL, E'Iphone', E'The iPhone is a line of touchscreen-based smartphones designed and marketed by Apple Inc. that use Apple''s iOS mobile operating system. The first-generation iPhone was {{1}} by Apple co-founder Steve Jobs on January 9, 2007. Since then Apple has periodically released new iPhone models and iOS updates. of November 1, 2018, more than 2.2 billion iPhones had been sold.\nThe iPhone''s user interface is built around a multi-touch screen with a {{2}} keyboard. The iPhone connects to cellular networks or Wi-Fi. An iPhone can make calls, browse the web, take pictures, play music and send and receive emails and text messages. Since the iPhone''s launch further features have been added, including larger screen sizes, shooting video, waterproofing and the ability to install third-party mobile apps through an app store, {{3}} accessibility support. Up to 2017, iPhones used a layout with a single button on the front panel that returns the user to the home screen. Since 2017, more expensive iPhone models have switched to a nearly bezel-less front screen design with app switching activated by gesture {{4}} .', NULL, NULL, NULL, E'1.announced, 2.virtual, 3.as well as, 4.recognition', NULL, NULL),
  ('f47a95f6-c5ce-5786-9220-6c4be8a9d117'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f47a95f6-c5ce-5786-9220-6c4be8a9d117'::uuid, 1, NULL, TRUE, 0, NULL, E'Mutual Politics', E'In order to achieve the free flow of goods and services, with work and capital between the member countries, they needed to establish mutual politics in areas as diverse as agriculture, transport, and when they were concerned with a far wider range of issues.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f47b6dd8-9520-54ad-8614-d15faf036bef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f47b6dd8-9520-54ad-8614-d15faf036bef'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the capital of Spain?', 'a9e58202-eeda-514d-8c70-f6450a560fe1'::uuid, NULL, NULL, E'Madrid', NULL, NULL),
  ('f47be59b-409e-565f-a86d-85812611d4a0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f47be59b-409e-565f-a86d-85812611d4a0'::uuid, 1, NULL, TRUE, 0, NULL, E'UN', E'Founded after World War II by 51 "peace-loving states" combined to oppose future aggression, the United Nations now counts 192 member nations, {{1}} its newest members, Nauru, Kiribati, and Tonga in 1999, Tuvalu and Yugoslavia in 2000, Switzerland and East Timor in 2002, and Montenegro in 2006. United Nations Day has been {{2}} on October 24 since 1948 and celebrates the objectives and accomplishments of the organization, which was established on October 24, 1945. The UN {{3}} in peacekeeping and humanitarian missions across the globe. Though some say its {{4}} has declined in recent decades, the United Nations still plays a tremendous role in world politics. In 2001 the United Nations and Kofi Annan, then Secretary-General of the UN, won the Nobel Peace Prize "for their work for a better organized and more peaceful world." Since 1948 there have been 63 UN peacekeeping operations, 16 are currently underway. Thus far, close to 130 nations have contributed personnel at various times; 119 are currently providing peacekeepers. As of August 31, 2008, there were 16 peacekeeping operations underway with a total of 88,230 personnel. The small island nation of Fiji has taken part in virtually every UN peacekeeping operation, as has Canada.', NULL, NULL, NULL, E'1.including, 2.observed, 3.engages, 4.influence', NULL, NULL),
  ('f47f0da5-d58a-5cd8-a28f-3f5a6b56cd81'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f47f0da5-d58a-5cd8-a28f-3f5a6b56cd81'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '11f6ed0e-309c-52b9-b84b-6f753ccf1533'::uuid, NULL, E'I''ve got a tutorial in an hour and I haven''t had any time to prepare for it.', NULL, NULL, NULL),
  ('f484ec17-72c6-5351-8a5e-27faacd3d006'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f484ec17-72c6-5351-8a5e-27faacd3d006'::uuid, 1, NULL, TRUE, 0, NULL, E'Suburbs', E'What makes a suburb a suburb? Simply, a suburb is a community {{1}} a city. But when you picture a suburb in your mind, your image may vary widely depending on which nation you call home. In the United States, most consider the suburbs home to upper—and middle—class people with private homes. In other countries, like France, the suburbs––or “banlieues”–– are {{2}} with housing projects and impoverished communities. In fact, the banlieues of Paris are {{3}} for their ethnic violence and crime, with higher unemployment and more residents living in poverty than in the city center. Further, the banlieues have a much higher {{4}} population, which in Paris is made up mostly by Arabic and African immigrants. This contradicts the clichéd U.S. image of a typical white-picket-fence suburb.', NULL, NULL, NULL, E'1.surrounding, 2.synonymous, 3.notorious, 4.immigrant', NULL, NULL),
  ('f4860c57-8dc0-5103-866b-0c16b76f81cd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f4860c57-8dc0-5103-866b-0c16b76f81cd'::uuid, 1, NULL, TRUE, 0, NULL, E'Dark Energy', E'Arguably the greatest mystery facing humanity today is the prospect that 75% of the universe is made up of a {{1}} known as “dark energy”, about which we have almost no knowledge at all. Since a further 21% of the universe is made from invisible “dark matter” that can only be {{2}} through its gravitational effects, the ordinary matter and energy making up the Earth, planets and stars is apparently only a tiny part of what exists. These {{3}} require a shift in our perception as great as that made after Copernicus’s {{4}} that the Earth moves around the Sun.', NULL, NULL, NULL, E'1.substance, 2.detected, 3.discoveries, 4.revelation', NULL, NULL),
  ('f49867c6-cf40-5afb-83f9-072b191ba49f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f49867c6-cf40-5afb-83f9-072b191ba49f'::uuid, 1, NULL, TRUE, 0, NULL, E'Britain''s Past', E'The transitions which occurred in Britain around 100 BC, and after 43 AD (when the Roman Army {{1}} Britain) represent the key points of socio-economic trend in Britain''s past. During the first century BC, the traditional communal form of life {{2}} rapidly to a world where certain individuals became more important. During the first century AD, Britain {{3}} fully a part of the Roman Empire.', NULL, NULL, NULL, E'1.invaded, 2.shifted, 3.became', NULL, NULL),
  ('f49d1b73-ffab-5aa3-b7b3-283089f86f2f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f49d1b73-ffab-5aa3-b7b3-283089f86f2f'::uuid, 1, NULL, TRUE, 0, NULL, E'Math Anxiety', E'People might think that they’re anxious about math because they’re bad at it, but it’s often the other way around. They’re doing poorly in math because they’re anxious about it. Some psychologists think that’s because math anxiety decreases a cognitive resource called working memory. That’s the short-term memory system that helps you organize the information you need to complete a task.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f4a5270c-ff92-5a2c-b05a-4c73994168da'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f4a5270c-ff92-5a2c-b05a-4c73994168da'::uuid, 1, NULL, TRUE, 0, NULL, E'Bacteria', E'The number one biggest difference between the bacteria in your body and the cells making up your body are these tiny cellular components called organelles. You''ve actually learned a lot about organelles in other lessons without knowing it. Organelles are simply membrane-bound compartments within a cell, such as the nucleus, mitochondria, chloroplasts, golgi, and endoplasmic reticulum.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f4ac48ef-a3f6-50fa-acbd-5480995bc8b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f4ac48ef-a3f6-50fa-acbd-5480995bc8b8'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '800036aa-1360-5b76-b37c-c3853765d979'::uuid, NULL, NULL, E'You must wear safety goggles to protect your eyes.', NULL, NULL),
  ('f4aee2d7-ca82-5e9e-af01-f7acd1aa8510'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f4aee2d7-ca82-5e9e-af01-f7acd1aa8510'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '76c65216-c3bb-59d9-8880-33e7d8d0b2f0'::uuid, NULL, NULL, E'It''s just a feeling of having tried something new and succeeded.', NULL, NULL),
