  ('f4c1fb08-6027-5a03-a057-3e8f8f24fe2e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f4c1fb08-6027-5a03-a057-3e8f8f24fe2e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6e20077f-4e70-5f48-ab60-ee2f6133dd04'::uuid, NULL, NULL, E'You can find the necessary books stored in the library.', NULL, NULL),
  ('f4c35fe8-ca93-52ff-8084-9ed40500fc3f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'f4c35fe8-ca93-52ff-8084-9ed40500fc3f'::uuid, 1, NULL, TRUE, 0, NULL, E'Banana Production', NULL, NULL, NULL, NULL, E'1, 4, 3, 2', NULL, NULL),
  ('f4c547dc-920c-5211-b8ef-8c5909a784e5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f4c547dc-920c-5211-b8ef-8c5909a784e5'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '023bd1d3-da31-5350-8ebc-94c832612890'::uuid, NULL, E'Today we have a guest speaker who is visiting from Canada.', NULL, NULL, NULL),
  ('f4c7a5b7-6bc1-5c89-b02b-d816df401613'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f4c7a5b7-6bc1-5c89-b02b-d816df401613'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c865b07a-5673-5c17-91b1-0768f18ff329'::uuid, NULL, E'The seminar on writing skills has been cancelled.', NULL, NULL, NULL),
  ('f4cb45a0-f236-5e41-bfc8-10a6a5fe04d2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f4cb45a0-f236-5e41-bfc8-10a6a5fe04d2'::uuid, 1, NULL, TRUE, 0, NULL, E'Brain Efficiency', E'Efficiency is not your friend when it comes to cognitive growth. In order to keep our brains making new connections and keep them active, you need to keep moving on to another challenging activity as soon as you reach the point of mastery in the one you were engaging in.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f4dd3ea8-7afa-55b1-b774-c4ebfb4fb9e3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'f4dd3ea8-7afa-55b1-b774-c4ebfb4fb9e3'::uuid, 1, NULL, TRUE, 0, NULL, E'The Replacement of Human(人类被替代)', NULL, NULL, NULL, NULL, E'4, 1, 3, 2', NULL, NULL),
  ('f4df7b29-92bc-562c-900d-56c979167d17'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'f4df7b29-92bc-562c-900d-56c979167d17'::uuid, 1, NULL, TRUE, 0, NULL, E'Hyper Competition', E'Some people claim that competition improves the quality of our private and professional lives. Others believe that being hyper-competitive is bad for individuals and society in general. What is your opinion?', NULL, NULL, E'Competition is a pervasive aspect of our lives that can be seen in various domains, including education, work, and sports. Some people believe that competition improves the quality of our private and professional lives, while others argue that hyper competition can have negative effects on society. In my opinion, competition can have a positive impact on our lives by driving innovation, motivating individuals to improve themselves, and leading to better products and services for consumers.\nFirstly, competition drives innovation and progress. When individuals or organizations compete with one another, they are incentivized to come up with new and creative ideas to gain an advantage. This can lead to the development of new technologies, products, and services that improve our lives. For example, the intense competition between technology companies has led to the development of smartphones, social media platforms, and other technologies.\nSecondly, competition motivates individuals to work harder and improve themselves. When individuals compete with one another, they are pushed to perform at their best and to continually improve their skills and knowledge. This can lead to personal growth and development, as well as improved performance in academic or professional settings. For example, students who compete for top grades in school may be more motivated to study and learn than those who do not face such competition.\nIn conclusion, I believe that competition can have a positive impact on our private and professional lives by driving innovation, motivating individuals to improve themselves, and leading to better products and services for consumers.', NULL, 200, 300),
  ('f4e2bf1e-9c11-5dec-891e-ad76681786ae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f4e2bf1e-9c11-5dec-891e-ad76681786ae'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '27a8d577-45c8-5951-8a87-41adf7e32559'::uuid, NULL, E'Basically, marketing is about making people want to buy.', NULL, NULL, NULL),
  ('f4ec28bf-fee8-5047-a80a-4f1660622b79'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'f4ec28bf-fee8-5047-a80a-4f1660622b79'::uuid, 1, NULL, TRUE, 0, NULL, E'High Speed Rail', E'To what extent do you think that countries should invest in high-speed rail systems?', NULL, NULL, E'The question of the extent to which countries should invest in high-speed rail systems is a pivotal consideration in contemporary transportation planning. High-speed rail presents a myriad of advantages, including time-saving benefits, sustainability, and economic prosperity.\nHigh-speed rail systems play a pivotal role in reducing travel time and enhancing efficiency. Operating at remarkable speeds, these systems facilitate swift and seamless travel experiences for passengers, significantly cutting down on journey durations. This efficiency not only elevates the overall transportation landscape but also fosters productivity and competitiveness on a global scale.\nMoreover, high-speed rail systems offer a sustainable mode of transportation that aids in curbing carbon emissions and addressing environmental challenges. Nations can play a proactive role in addressing climate change and cultivating a greener society by championing eco-conscious travel options, thereby contributing to environmental preservation and sustainability efforts. Additionally, the improved connectivity enabled by high-speed rail networks drives economic growth by bolstering accessibility to key business centers, tourist attractions, and employment prospects.\nIn conclusion, the case for investing in high-speed rail systems transcends mere infrastructure enhancement. These systems not only alleviate congestion but also champion sustainability and propel economic advancement. Hence, countries should prioritize investments in high-speed rail to forge a future characterized by enhanced efficiency, environmental stewardship, and robust economic development for their populace.', NULL, 200, 300),
  ('f4eda921-be67-54c7-8c46-9c3e130c4b2d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'f4eda921-be67-54c7-8c46-9c3e130c4b2d'::uuid, 1, NULL, TRUE, 0, NULL, E'Success Key', E'Everyone wants success, but what is the key to success, the ability or the opportunity?', NULL, NULL, NULL, NULL, 200, 300),
  ('f4f19c3d-a4b3-58bf-938a-515f8ece0b35'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f4f19c3d-a4b3-58bf-938a-515f8ece0b35'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'When a person''s Blood Alcohol Content is higher than the standard range, what activity are they not allowed to do?', '56e93005-46e2-598e-aa45-03f2d9e0e590'::uuid, NULL, NULL, E'Driving', NULL, NULL),
  ('f4f400b5-111d-5edb-8f4e-27bc8deeb5fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f4f400b5-111d-5edb-8f4e-27bc8deeb5fe'::uuid, 1, NULL, TRUE, 0, NULL, E'Plato', E'Since Plato, philosophers have described the decision-making process as either rational or emotional: we carefully deliberate or we ''blink'' and go with our gut. But as scientists break open the mind''s black box with the latest tools of neuroscience, they''re discovering that this is not how the mind works. Our best decisions are a finely tuned blend of both feeling and reason, and the precise mix depends on the situation.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f4f759b3-4773-5479-a008-188e65df9dbd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f4f759b3-4773-5479-a008-188e65df9dbd'::uuid, 1, NULL, TRUE, 0, NULL, E'Dendrochronology', E'A bonus of dendrochronology is that the width and the substructure of each ring {{1}} the amount of rain and the {{2}} at which the rain fell during that particular year. Thus, tree ring studies also allow one to reconstruct {{3}} climate; for example, a {{4}} of wide rings means a wet period, and a series of narrow rings means a {{5}} .', NULL, NULL, NULL, E'1.reflect, 2.season, 3.past, 4.series, 5.drought', NULL, NULL),
  ('f50da739-14b6-5bfe-85da-c453c308f872'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'f50da739-14b6-5bfe-85da-c453c308f872'::uuid, 1, NULL, TRUE, 0, NULL, E'Life Experience', E'Some people argue that experience is the best teacher, saying life experiences teach people more effectively than books or formal education can. How far do you agree with this statement? Give your reason or provide your personal experience.', NULL, NULL, E'The debate over whether experience is the best teacher or books and formal education are more effective has been ongoing for decades. While both sides have valid arguments, I firmly believe that experience is the best teacher. In this essay, I will present a positive standpoint, outlining the reasons why experience is a more effective teacher than books or formal education.\nThe first reason why experience is the best teacher is that it provides practical knowledge that cannot be found in books or formal education. Experience allows individuals to learn by doing and to gain practical skills that can be applied in real-life situations. For example, a person who has never driven a car before can read books on driving or take driving lessons, but it is only through the experience of actually driving that they can develop the necessary skills to become a proficient driver.\nAnother reason why experience is a more effective teacher than books or formal education is that it can have a greater impact on an individual''s personal growth and development. Experiencing something firsthand can be a transformative experience that can shape an individual''s values, beliefs, and worldview. For instance, traveling to a foreign country and immersing oneself in a new culture can broaden one''s perspective and deepen one''s understanding of the world.\nIn conclusion, I firmly believe that experience is the best teacher. It provides practical knowledge that cannot be found in books or formal education, and it can have a greater impact on an individual''s personal growth and development. While books and formal education have their place in learning, they cannot replace the value of firsthand experience. Therefore, individuals should seek out opportunities to gain experience and learn from their experiences to become more knowledgeable, well-rounded individuals.', NULL, 200, 300),
  ('f527f43c-da61-5b4e-9f36-fff3e887ef79'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f527f43c-da61-5b4e-9f36-fff3e887ef79'::uuid, 1, NULL, TRUE, 0, NULL, E'Lifestyle', E'Tea played a pivotal role in {{1}} societies from nomadic hunter-gatherer lifestyles to more settled agricultural communities. With a history {{2}} over 5,000 years, tea''s origins can be {{3}} back to China, where it was first discovered. From this epicenter, it {{4}} borders on ancient caravans, making its way into India, Japan, and the Middle East.', NULL, NULL, NULL, E'1.transitioning, 2.spanning, 3.traced, 4.crossed', NULL, NULL),
  ('f52827df-5d84-5e21-8239-4b7f81beb60a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f52827df-5d84-5e21-8239-4b7f81beb60a'::uuid, 1, NULL, TRUE, 0, NULL, E'Bergson''s Theory', E'The starting point of Bergson''s theory is the experience of time and motion. Time is the reality we experience most directly, but this doesn''t mean that we can capture this experience mentally. The past is gone and the future is yet to come. The only reality is the present, which is real through our experience.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f52bb8a4-9a52-5d94-9933-146f0ee89a6a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f52bb8a4-9a52-5d94-9933-146f0ee89a6a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call a person sitting beside you?', '91d90edd-d452-5491-af22-6f31fdc23bcd'::uuid, NULL, NULL, E'Seatmate / neighbor', NULL, NULL),
  ('f5328436-41ea-5de5-8ca8-7bf9cebf6625'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f5328436-41ea-5de5-8ca8-7bf9cebf6625'::uuid, 1, NULL, TRUE, 0, NULL, E'Extreme Heat', E'Extreme heat brings serious health risks, {{1}} for people who are elderly or have pre-existing conditions. Because of climate change, heatwaves are getting more frequent, more {{2}} and are lasting longer than ever before with deadly {{3}} . During heatwaves, there is a higher {{4}} of death from cardiovascular and respiratory diseases.', NULL, NULL, NULL, E'1.especially, 2.intense, 3.consequences, 4.incidence', NULL, NULL),
  ('f539186e-a749-5e74-ac79-5fddfd757b25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'f539186e-a749-5e74-ac79-5fddfd757b25'::uuid, 1, NULL, TRUE, 0, NULL, E'MCS-R', E'One explanation for the tendency of animals to be more vigilant in smaller groups than in larger ones assumes that the vigilant behavior—looking up, for example—is aimed at predators. If individuals on the edge of a group are more vigilant because they are at greater risk of being captured, then individuals on average would have to be more vigilant in smaller groups, because the animals on the periphery of a group form a greater proportion of the whole group as the size of the group diminishes. However, a different explanation is necessary in cases where the vigilant behavior is not directed at predators. J. Krebs has discovered that great blue herons look up more often when in smaller flocks than when in larger ones, solely as a consequence of poor feeding conditions. Krebs hypothesizes that the herons in smaller flocks are watching for herons that they might follow to better feeding pools, which usually attract larger numbers of the birds.\n\nIt can be inferred from the passage that in species in which vigilant behavior is directed at predators, the tendency of the animals to be more vigilant in smaller groups than in larger ones would most likely be minimized if which of the following were true?', NULL, NULL, NULL, E'The risk of capture for individuals in a group was the same, whether they were located in the interior of the group or on its periphery.', NULL, NULL),
  ('f543b8de-e247-514e-a04c-02edcb78a92f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f543b8de-e247-514e-a04c-02edcb78a92f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '79189e11-118b-5811-b8f9-91b10d788b4b'::uuid, NULL, NULL, E'A qualified teacher can also serve as a mentor when needed.', NULL, NULL),
  ('f54620f3-359c-5eba-9494-87e165727b4f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f54620f3-359c-5eba-9494-87e165727b4f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the hottest area of Earth which is around the equator?', '96d81beb-a407-5c0b-9f4a-51b3e34f4aa3'::uuid, NULL, NULL, E'Tropic', NULL, NULL),
  ('f5464c9e-a7c2-5a34-a8bf-ef131deb529a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f5464c9e-a7c2-5a34-a8bf-ef131deb529a'::uuid, 1, NULL, TRUE, 0, NULL, E'Earthquakes', NULL, '9d425ec9-b823-51b7-9cff-562d731428b6'::uuid, NULL, E'Now, you''ve been reading articles about the tremendous damage done to life and property by earthquakes. That''s why seismologists have been working so hard to develop methods of earthquake prediction. We can now predict earthquakes fairly well, but the predictions only locate potential areas of danger. They don''t predict the specific time and location at which an earthquake is likely to occur. Today I want to introduce to you three prediction models that have been developed. The first prediction model looks along earthquake faults, those cracks in the Earth''s crust, to find what are known as seismic gaps. Seismic gaps are places where the fault has shown little or no seismic activity for a long time. This theory postulates that such places are due for a major shock. The second model relies on phenomena, like ground tilt. Using long cylindrical tubes containing water, observers noted that ground tilt tended to occur before major earthquakes. That led them to correctly predict the big Haicheng quake of 1975, the first successful earthquake prediction scientists have ever made. A million people were evacuated from that Chinese city before the earthquake struck. Unfortunately, this method hasn''t worked consistently, so we can''t say it''s been perfected. The third model is based on the theory that major earthquakes closely follow a series of minor ones. Starting with the measurements and timing of the smaller quakes, a complex formula calculates the "times of increased probability" of a much larger quake. Right now, this method, like the first method, cannot predict specific times and places, but that may change as it is further developed. For the moment, none of these models can predict with reasonable levels of confidence.', NULL, NULL, NULL),
  ('f54f30a6-9cab-51f7-92b7-1b30178de103'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f54f30a6-9cab-51f7-92b7-1b30178de103'::uuid, 1, NULL, TRUE, 0, NULL, E'Yoga', E'But like other low-impact exercises, yoga reliably improves fitness and flexibility in healthy populations. The practice has also been shown to be a potentially powerful therapeutic tool. In studies involving patients with a variety of skeletal disorders, yoga was more helpful at reducing pain and improving mobility than other forms of low-impact exercise.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f5508c4b-15fc-52bb-9a5e-fe2e9e87ea43'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f5508c4b-15fc-52bb-9a5e-fe2e9e87ea43'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e5f21ff3-84e0-553d-bdba-d7b16f0dfb99'::uuid, NULL, NULL, E'Students should engage in academic research and other cultural activities.', NULL, NULL),
  ('f5540b57-587e-58f8-ac32-faf0d8539786'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f5540b57-587e-58f8-ac32-faf0d8539786'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '97d80c82-aaca-54ec-aac4-6152c6719e41'::uuid, NULL, E'This short summary will take us to a time long ago.', NULL, NULL, NULL),
  ('f557279f-24f7-5f1d-bf22-75923a3b2aee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f557279f-24f7-5f1d-bf22-75923a3b2aee'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'f5218ab9-5bf8-5648-9ed2-9bf982114de2'::uuid, NULL, NULL, E'The purpose of the program is primarily educational.', NULL, NULL),
  ('f55995ac-67fa-5cba-a6f3-7b41dbea3370'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f55995ac-67fa-5cba-a6f3-7b41dbea3370'::uuid, 1, NULL, TRUE, 0, NULL, E'Seasonal Influenza', E'Seasonal influenza is an acute respiratory infection caused by influenza viruses which {{1}} in all parts of the world. It represents a year-round disease {{2}} .It causes illnesses that range in severity and sometimes lead to hospitalization and death. Most people recover from fever and other symptoms within a week without requiring medical attention. However, influenza can also cause {{3}} illness or death.', NULL, NULL, NULL, E'1.circulate, 2.burden, 3.severe', NULL, NULL),
  ('f55ec02e-7620-5d55-bc53-225c997d764c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f55ec02e-7620-5d55-bc53-225c997d764c'::uuid, 1, NULL, TRUE, 0, NULL, E'Reserve Requirements', E'Reserve requirements are the proportions of the deposits that banks must keep on hand and are not allowed to lend out. For example, if the reserve requirement is 10% and you deposit one hundred dollars in a bank, the bank can lend ninety dollars of that one hundred dollars to someone else. But it is not allowed to lend the remaining ten dollars.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f56273c1-dcca-5cc8-82a8-b15e126996ce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'f56273c1-dcca-5cc8-82a8-b15e126996ce'::uuid, 1, NULL, TRUE, 0, NULL, E'Indigenous Communities', E'Climate change is one of the most pressing global challenges of our time, and its effects are felt disproportionately by indigenous communities around the world. These communities, often deeply connected to their environment and traditions, are facing unprecedented challenges due to shifting weather patterns and environmental disruptions.\nHistorically, indigenous peoples have lived in harmony with nature, utilizing their knowledge of the land and its resources to sustain their way of life. However, the rapid pace of climate change has disrupted these delicate balances. Rising temperatures, altered rainfall patterns, and more frequent extreme weather events are causing food shortages, water scarcity, and damage to traditional dwellings.\nResearch indicates that these environmental changes are not only threatening the physical well-being of indigenous peoples but also eroding their cultural heritage. Traditional knowledge, passed down through generations, is at risk of being lost as younger generations are forced to adapt to a changing world.\nIndigenous communities are actively participating in climate-related events and initiatives, raising awareness about the unique challenges they face and advocating for sustainable solutions. Their deep understanding of the environment and innovative approaches to adaptation can offer valuable insights for the broader global community in addressing climate change.\nIn conclusion, climate change poses a profound threat to indigenous communities, impacting their way of life, culture, and heritage. Acknowledging their resilience and involving them in climate mitigation and adaptation efforts is not only an ethical imperative but also an opportunity to learn from their wisdom in facing this global crisis.', NULL, NULL, E'Climate change is disproportionately affecting indigenous communities, endangering their traditional way of life, cultural heritage, and the invaluable knowledge they hold about sustainable living, while also highlighting the urgent need to engage them in climate mitigation and adaptation efforts to address this global crisis more effectively.', NULL, 5, 75),
  ('f567519c-2136-5734-910b-c1fbe9066187'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f567519c-2136-5734-910b-c1fbe9066187'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5feabc66-2390-548d-99fa-d39cb86fb12b'::uuid, NULL, NULL, E'The new technician dropped the microscope in the biology lab.', NULL, NULL),
