  ('f64e7267-8774-5df8-9bcb-6655207974cd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f64e7267-8774-5df8-9bcb-6655207974cd'::uuid, 1, NULL, TRUE, 0, NULL, E'Atlantic Coast', E'The Atlantic coast of the peninsula can be thought of as the cold side, and the sea on this coast tends to be clear and cold, with a variety of seaweeds growing along the rocky shoreline. On a hot day, however, this cold water can be very refreshing and is said to be less hospitable to sharks, which prefer warmer waters.', NULL, NULL, NULL, NULL, NULL, NULL),
