  ('f655ae99-3bf5-599d-a973-c04f23f943af'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f655ae99-3bf5-599d-a973-c04f23f943af'::uuid, 1, NULL, TRUE, 0, NULL, E'Travel', E'Traveling is an exciting way to explore new places and cultures. It broadens our horizons and fosters understanding between people from different backgrounds. From exotic foods to stunning landscapes, every trip creates lasting memories. It''s an adventure that enriches our lives and teaches us valuable lessons about ourselves and the world around us.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f65dbc8b-0e25-55bc-b298-39f6920f8e07'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f65dbc8b-0e25-55bc-b298-39f6920f8e07'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8f0cb6d9-797c-5acd-ba21-3cb2acfc0754'::uuid, NULL, E'His objection to including scientific evidence has brought a lot of criticisms to him.', NULL, NULL, NULL),
