  ('f725b33b-dbef-55ea-9ec4-1436b1099c86'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f725b33b-dbef-55ea-9ec4-1436b1099c86'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f6994d97-1fc6-5902-8786-ff7cdea71b04'::uuid, NULL, E'By changing the body positions, we can actually express our thoughts and feelings.', NULL, NULL, NULL),
  ('f72677b5-7689-510f-b88f-50d1612d7cc7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f72677b5-7689-510f-b88f-50d1612d7cc7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8fb35b71-d1e0-50a3-8324-f94a51a6f6d0'::uuid, NULL, NULL, E'Faculty members are consistently accessible and approachable for guidance and counsel.', NULL, NULL),
  ('f726bd44-f1b7-5d20-aa4c-2af4d8b02e98'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f726bd44-f1b7-5d20-aa4c-2af4d8b02e98'::uuid, 1, NULL, TRUE, 0, NULL, E'Steven Pinker', E'Steven Pinker, a cognitive psychologist best known for his book "The Language Instinct", has called music "auditory cheesecake, an exquisite confection crafted to tickle the sensitive spots of at least six of our mental faculties." If it {{1}} from our species, he said, "the rest of our lifestyle would be {{2}} unchanged." Others have argued that, on the {{3}} , music, along with art and literature, is part of what makes people human; its absence would have a brutalising effect. Philip Ball, a British science writer and an {{4}} music enthusiast, comes down somewhere in the middle. He says that music is {{5}} in our auditory, cognitive and motor functions. We have a music {{6}} as much as a language instinct, and could not rid ourselves of it if we tried.', NULL, NULL, NULL, E'1.vanished, 2.virtually, 3.contrary, 4.avid, 5.ingrained, 6.instinct', NULL, NULL),
  ('f7278c7b-bc80-5eaf-9087-e3ac57dfecd2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f7278c7b-bc80-5eaf-9087-e3ac57dfecd2'::uuid, 1, NULL, TRUE, 0, NULL, E'Social Media', E'Social media''s impact on the youth has been a topic of considerable debate. Platforms like Instagram, Twitter, and Facebook offer spaces for social interaction, self-expression, and information sharing. {{1}} , they also pose risks such as cyberbullying, exposure to {{2}} content, and the impact on mental health. Studies have shown that excessive use of social media can lead to feelings of anxiety, depression, and loneliness in young people. The pressure to maintain a certain image online and the constant comparison with others can exacerbate these feelings. On the positive side, social media can also {{3}} support networks, educational content, and opportunities for civic engagement among youth. The challenge lies in achieving a balance, {{4}} safe and responsible use of these platforms.', NULL, NULL, NULL, E'1.However, 2.inappropriate, 3.provide, 4.promoting', NULL, NULL),
  ('f72f6aa1-f9c5-56ba-86bf-fe3e59ec8800'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f72f6aa1-f9c5-56ba-86bf-fe3e59ec8800'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How many continents are there on Earth?', '0bd8a63f-9f0c-5336-89bc-3a18fc12c5ff'::uuid, NULL, NULL, E'Seven', NULL, NULL),
