  ('f778f590-79be-5c53-8555-5810b367916d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f778f590-79be-5c53-8555-5810b367916d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What''s the last paragraph of an essay?', 'dc839289-956a-5474-8cd1-de001a1e94dd'::uuid, NULL, NULL, E'Conclusion', NULL, NULL),
  ('f77afef7-31ef-59a0-8b91-6cfa5e1a4d35'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f77afef7-31ef-59a0-8b91-6cfa5e1a4d35'::uuid, 1, NULL, TRUE, 0, NULL, E'Urban Forests', E'A community''s urban forest is an extension of its pride and community spirit. Trees enhance community economic stability by attracting businesses and tourists as people tend to linger and shop longer along tree-lined streets. Apartments and offices in wooded areas rent more quickly and businesses leasing office spaces in developments with trees reported higher productivity and fewer absences.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f781cb72-8470-5e0c-95f7-67512fe275fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f781cb72-8470-5e0c-95f7-67512fe275fb'::uuid, 1, NULL, TRUE, 0, NULL, E'Asteroids', E'A new study has revealed the presence of water molecules on the surface of two asteroids in the main belt between Mars and Jupiter. This discovery challenges the previous {{1}} that these asteroids were completely dry and could explain the origin and distribution of water in our solar system. The study, published in The Planetary Science Journal, used data from the SOFIA airborne telescope, {{2}} detected water signatures on Iris and Massalia, two silicate-rich asteroids. The amount of water was {{3}} to that found on the lunar surface by the same telescope in 2020. The finding of water on these asteroids suggests that they formed far enough from the sun to avoid losing their water due to heat. It also supports the theory that asteroids may have {{4}} water and other elements to early Earth through impacts. The researchers plan to use the James Webb Space Telescope to look for water on more asteroids and understand their composition and history.', NULL, NULL, NULL, E'1.assumption, 2.which, 3.comparable, 4.delivered', NULL, NULL),
  ('f78ab5a0-7f84-57c2-a710-132de9087b68'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f78ab5a0-7f84-57c2-a710-132de9087b68'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the process of breaking down plastic and glass and using it again?', '50ebd179-0e99-5039-81ee-3d666907837a'::uuid, NULL, NULL, E'Recycling', NULL, NULL),
  ('f78fef85-fa28-5c2a-9ec9-b1fcbbb533c9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f78fef85-fa28-5c2a-9ec9-b1fcbbb533c9'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the technology that uses radio waves for detecting the position, velocity, and identifying characteristics of objects?', '88ba34b5-327f-591d-b79a-35c46a7bcdc2'::uuid, NULL, NULL, E'Radar', NULL, NULL),
