  ('f805e793-a1f6-5414-ae8f-8fe7623f9352'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f805e793-a1f6-5414-ae8f-8fe7623f9352'::uuid, 1, NULL, TRUE, 0, NULL, E'Cat''s Paws', E'In the photo, the wild cat''s huge paws are clamped onto the side of the white safari Jeep in which Chappell was a passenger. Almost as tall as the Jeep on her hind legs, she appears to be forcing her muzzle into the back window.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f811e859-ccd7-5a11-bda2-3d7b2de7e2d9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f811e859-ccd7-5a11-bda2-3d7b2de7e2d9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4c7a8667-8671-5c8c-bf74-a5f57d1113e5'::uuid, NULL, NULL, E'It is difficult for him to adjust to student life.', NULL, NULL),
  ('f8147a0f-52ff-5419-9256-d388be35f269'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f8147a0f-52ff-5419-9256-d388be35f269'::uuid, 1, NULL, TRUE, 0, NULL, E'Immunology', E'Immunology, a dynamic field focused on the immune system, plays a pivotal role in vaccine development. Researchers delve into understanding {{1}} the immune system recognizes and responds to pathogens, paving the way for designing effective vaccines. Modern vaccine development {{2}} technologies like mRNA and viral vector platforms, offering rapid and adaptable approaches. Immunologists study the immune response to infectious agents, identifying potential vaccine targets and {{3}} formulations for enhanced efficacy. The ongoing challenge involves addressing emerging infectious diseases and developing vaccines that provide long-lasting immunity. Immunotherapy, a branch of immunology, extends beyond infectious diseases to harness the immune system in treating {{4}} like cancer. The synergy of immunology and vaccine development continues to drive advances in preventive medicine and therapeutic interventions.', NULL, NULL, NULL, E'1.how, 2.incorporates, 3.optimizing, 4.conditions', NULL, NULL),
  ('f81700d4-c258-5acb-8819-51b8b68c6199'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f81700d4-c258-5acb-8819-51b8b68c6199'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the device used to generate electricity?', 'b0b59045-b504-5ccc-892e-2eefcbf3859e'::uuid, NULL, NULL, E'Generator', NULL, NULL),
  ('f817db5f-0bf0-51d1-afb6-c307f6089713'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f817db5f-0bf0-51d1-afb6-c307f6089713'::uuid, 1, NULL, TRUE, 0, NULL, E'Star Brilliance', E'One of the clearest demonstrations that the magnificent brilliance of a star {{1}} from a modest aggregation of gas and dust was provided by detailed observations of young stellar objects in regions like the Orion Nebula. These nascent stars, resembling dimly lit spheres, often measure only a few million kilometers in diameter. Over time, the intense pressure and heat at their cores {{2}} nuclear fusion, causing them to shine brightly. As these stars mature, they eject material, creating luminous jets and stellar winds. Stars develop into full maturity only when the conditions at their cores become hot enough for hydrogen fusion to commence. As a star''s life {{3}} , it may enter various phases, often culminating in the formation of a red giant or a supernova. In the case of massive stars, the supernova explosion is a spectacular event, {{4}} off material into space. This material, rich in heavier elements formed during the star''s life, then contributes to the creation of new stars and planets, continuing the cycle of stellar evolution.', NULL, NULL, NULL, E'1.originates, 2.initiate, 3.progresses, 4.casting', NULL, NULL),
  ('f8196f9f-5b2c-5e27-b73f-afa249f80197'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f8196f9f-5b2c-5e27-b73f-afa249f80197'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a scientist who studies planets and stars?', 'a0cfc944-2017-585e-a9f6-70c087ae6f66'::uuid, NULL, NULL, E'Astronomer', NULL, NULL),
  ('f81f6a24-ef31-5f1f-873f-0bbdb9f2968c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SELECT_MISSING_WORD', E'SELECT_MISSING_WORD', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f81f6a24-ef31-5f1f-873f-0bbdb9f2968c'::uuid, 1, NULL, TRUE, 0, NULL, E'Flowers', E'Earlier this year, I was driving through the countryside with a girl of six, and she pointed out some flowers by the wayside. I asked her what she thought flowers were for. She gave a very thoughtful answer. "Two things," she said, "to make the world pretty and to help the bees make honey for us." I thought that this was a very nice answer and I was very sorry to have to tell her that this wasn''t ...\n\nAt the end of the recording the lost word or group of words has been replaced by a beep. Select the correct option to complete the recording.', '65171fd6-5a69-507d-9803-4adb3d60d431'::uuid, NULL, NULL, E'true', NULL, NULL),
  ('f81f9aeb-57d0-500d-8937-fa9c41d3ba56'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f81f9aeb-57d0-500d-8937-fa9c41d3ba56'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'ebf5793f-d710-508c-a068-279e4f78dfe6'::uuid, NULL, NULL, E'Previously, she served as the chief editor for the student-led newspaper.', NULL, NULL),
  ('f8297417-51a5-5658-bdd6-4890dcaaf42f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f8297417-51a5-5658-bdd6-4890dcaaf42f'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '8f32d10d-bbfd-5287-8234-c7bff5723484'::uuid, NULL, NULL, E'Please move us to the meeting room for the next hour.', NULL, NULL),
  ('f82bf5c0-668d-532f-861e-a6ddfdd65da1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f82bf5c0-668d-532f-861e-a6ddfdd65da1'::uuid, 1, NULL, TRUE, 0, NULL, E'Plague', E'Plague is an infectious disease and is {{1}} between animals via their fleas. Humans can also be contaminated by the bite of infected fleas, through direct {{2}} with infected materials, or by inhalation. Although plague has been responsible for widespread pandemics throughout history, today it can be easily treated with antibiotics and the use of standard {{3}} measures.', NULL, NULL, NULL, E'1.transmitted, 2.contact, 3.preventative', NULL, NULL),
  ('f82d9da3-9809-5cff-ac90-0c24cd0a8de3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f82d9da3-9809-5cff-ac90-0c24cd0a8de3'::uuid, 1, NULL, TRUE, 0, NULL, E'Kangaroo', NULL, '0f150876-7b47-5a36-b13d-9a0c28667c0c'::uuid, NULL, E'Many people know that the kangaroo is a marsupial from the family macropodidae. There are about 69 species of kangaroos in the world. They live in Australia, New Guinea and the nearby islands. Also everyone knows that kangaroo females have a special pouch where they carry their cubs. But not everyone knows that a kangaroo has a very short of pregnancy term. A baby is born about a month after conception. However, this is not a grown animal ready for life in the outside world. The size of a new-born kangaroo is only a couple of centimeters. And it weighs about a gram. In this embryonic state, the cub makes its way into the pouch, and a tiny kangaroo does not yet have hind legs, so he has to use the front ones. Moreover, the mother does not help him. She only licks the path to the pouch, for the cub immediately starts sucking on the nipple. Well, he doesn’t actually suck it, because he is not yet able to. He is too small. Milk is secreted into his mouth with the help of a special muscle. Another particular thing about the kangaroo is that it has four nipples in his pouch. And each of them secretes a different kind of milk. So, kangaroos have four times of milk depending on the age of the cub. Sometimes a female has two cubs of different ages at once, and both are still in the pouch. In this case, two kinds of milks are secreted. In about 190 days, the cub becomes large and strong enough to climb out of the pouch. At first, he only sticks his head out. And this can continue for several weeks, until the cub feels safe enough to get out. He then starts spending more and more time in the outside world. And eventually- In about 235 days, he lives in the pouch for the last time.', NULL, NULL, NULL),
  ('f82dd953-9243-590d-85c0-2667c344f8b4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f82dd953-9243-590d-85c0-2667c344f8b4'::uuid, 1, NULL, TRUE, 0, NULL, E'Vietnam''s Coffee', NULL, '5efa08ea-50fe-5610-8f66-8a29b3dd550e'::uuid, NULL, E'With the help of the wealthy countries such as US, Vietnam became second largest coffee producer and exporter. This impact other coffee producers like Colombia. The lecture is about the changes that have taken place in coffee production. Coffee production increased from 6 billion to 30 billion. The huge demand of Europe and America has made Vietnam the second biggest producer which has greatly affected Columbia''s production. The output of Central America is witnessing dramatic decrease. People''s drinking habit also undergoing changes. Coffee was introduced to Vietnam in 1857 by the French and slowly grew as producer of coffee in Asia. The height of coffee production occurred in the early 20th century as small-scale production shifted towards plantations. By 2000, coffee production had grown to 900,000 tons per year. Price decreases, however, led annual production to drop to around 600,000 tons/year in 2003.[3] In 2009, Reuters report Vietnamese coffee exports at "an estimated 1.13 million tones" for the previous year stating that coffee was second only to rice in value of agro-products exported from Vietnam. The country''s 2013/2014 coffee crop is expected to be a bumper harvest of around million to 29.5 million 60-kg bags. Such a large production will add to a global oversupply beans and will pressure coffee prices which have lost about 10 percent since October 20. The country''s coffee industry has taken a hit; of the 127 local coffee export firms that operated in 2012, 56 have ceased trading or shifted to other businesses after having taken out loans they can''t repay. A few firms, such as Vietnam''s top coffee exporter the Intimex Group, will benefit from the 2013 harvest. Intimex accounts for a quarter of the country''s coffee exports and made $1.2 billion in revenue in 2012.', NULL, NULL, NULL),
  ('f83720c5-568c-5a6e-becb-b11240a02774'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'f83720c5-568c-5a6e-becb-b11240a02774'::uuid, 1, NULL, TRUE, 0, NULL, E'Beautiful Buildings', E'It is important to preserve the beautiful buildings of the past, even if it will be expensive to do so. To what extent do you agree or disagree with it.', NULL, NULL, NULL, NULL, 200, 300),
  ('f837f273-e5fe-5026-aaac-80f3eec24cfb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f837f273-e5fe-5026-aaac-80f3eec24cfb'::uuid, 1, NULL, TRUE, 0, NULL, E'Environmental Cost', E'The environmental cost of our fleeting love affair with fast fashion is staggering. A single cotton T-shirt, for example, requires over 700 gallons of water to produce, while a pair of jeans can {{1}} 20 pounds of carbon emissions. And these garments are often {{2}} after just a few wears, filling landfills with mountains of textile waste. We often buy clothes to express our identity and feel like we belong to a certain group. {{3}} , in a world saturated with fast fashion, this symbolic meaning fades quickly. Historically, people had a deeper connection with their clothing. Garments were often handmade or {{4}} down through generations, imbuing them with a unique history and emotional value. Today''s mass production, on the other hand, encourages us to view clothing as disposable commodities.', NULL, NULL, NULL, E'1.generate, 2.discarded, 3.However, 4.passed', NULL, NULL),
  ('f838dfad-5464-52e0-8ccd-02c2fbbb1573'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f838dfad-5464-52e0-8ccd-02c2fbbb1573'::uuid, 1, NULL, TRUE, 0, NULL, E'Appeal of Cuteness', E'The appeal of cuteness in infants is more than just surface-level {{1}} ; it''s an evolutionary strategy designed to ensure caregiving and survival. This reaction to the features of young offspring plays a critical role in human behavior, triggering {{2}} and protective instincts. The science {{3}} this response reveals the intricate ways in which nature ensures the continuation of species through the power of cuteness, an effective {{4}} for eliciting care and attention from adults.', NULL, NULL, NULL, E'1.charm, 2.nurturing, 3.behind, 4.mechanism', NULL, NULL),
  ('f83ca78b-4d27-52f1-afa6-6f57c87cc91a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f83ca78b-4d27-52f1-afa6-6f57c87cc91a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a substance that speeds up a chemical reaction without being consumed in the process?', '76cce14a-262b-56c7-b95e-91e95c1a3345'::uuid, NULL, NULL, E'Catalyst', NULL, NULL),
  ('f84354ab-e8db-5dfe-a242-b45d6404972f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f84354ab-e8db-5dfe-a242-b45d6404972f'::uuid, 1, NULL, TRUE, 0, NULL, E'European Wildcats', E'European wildcats, thought to be extinct 50 or so years ago in the Jura mountains, have since recolonized part of their former territory. This resurgence in an area occupied by domestic cats has gone hand-in-hand with genetic crosses between the two species. A team of biologists modeled the interactions between the two species to predict that hybridization will entail the irreversible genetic replacement of wildcats.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f8445d5a-be57-57fb-9acb-1cbf4e9e7a0b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f8445d5a-be57-57fb-9acb-1cbf4e9e7a0b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'When you want to do some baking, where would you go to buy some flour, a florist or a grocery?', '82187542-0daa-533b-9c58-4abffe114d0e'::uuid, NULL, NULL, E'Grocery', NULL, NULL),
  ('f8462a75-b8c0-5a19-b3a9-853da21c68fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f8462a75-b8c0-5a19-b3a9-853da21c68fe'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'dd05256b-14df-5821-bd98-8fd72201fd0e'::uuid, NULL, E'Robots are able to communicate with humans around them.', NULL, NULL, NULL),
  ('f84fb3d3-b57d-5508-9b57-90e33d030766'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f84fb3d3-b57d-5508-9b57-90e33d030766'::uuid, 1, NULL, TRUE, 0, NULL, E'Religiosity', E'A well-established finding in psychology is that religiosity and intelligence are negatively correlated. This means that, on {{1}} , people who are more religious tend to score lower on intelligence tests, and vice versa. However, this does not mean that being religious makes you less intelligent, or that being intelligent makes you less religious. Correlation does not {{2}} causation, and there are many factors that could influence this relationship. One possible explanation is that people who rely more on {{3}} than on analytical thinking might be more likely to hold religious beliefs. However, this does not mean that religious people are irrational or that non-religious people are rational. There are many types and dimensions of religiosity, and some of them might have positive effects on cognitive and mental health. For instance, one form of religiosity that has been shown to {{4}} against cognitive decline in older adults is church attendance. Going to church regularly might provide social and communal support, as well as cognitive {{5}} ,that could enhance brain function and prevent dementia.', NULL, NULL, NULL, E'1.average, 2.imply, 3.intuition, 4.protect, 5.stimulation', NULL, NULL),
  ('f856e2c5-45ce-5eb7-ab98-6719ea70314d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'f856e2c5-45ce-5eb7-ab98-6719ea70314d'::uuid, 1, NULL, TRUE, 0, NULL, E'Automat', NULL, NULL, NULL, NULL, E'2, 3, 4, 1', NULL, NULL),
