  ('f867211a-79d0-5def-a35b-4b83bdf41765'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f867211a-79d0-5def-a35b-4b83bdf41765'::uuid, 1, NULL, TRUE, 0, NULL, E'A Country', E'A country refers to a certain population with its own {{1}} , traditions, and common cultural background. Most crucially of all, a nation needs to be {{2}} by other members of the United Nations in order to be considered a country. Otherwise, anyone with an island could {{3}} themselves the sovereign leader of their own fabricated country.', NULL, NULL, NULL, E'1.identity, 2.recognized, 3.proclaim', NULL, NULL),
  ('f8681ae1-87d5-5035-98e5-0c5509b0e4e8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f8681ae1-87d5-5035-98e5-0c5509b0e4e8'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1bfab451-f853-5795-91e1-72f6bdb20fbd'::uuid, NULL, NULL, E'Job problems have made more people unable to find work.', NULL, NULL),
  ('f86a22ba-0a91-592f-89e2-3687b5bfd8f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f86a22ba-0a91-592f-89e2-3687b5bfd8f8'::uuid, 1, NULL, TRUE, 0, NULL, E'Lava', E'Lava is an incredibly hot {{1}} that forms when magma from the Earth‘s depths rises to the surface and {{2}} through a volcano. It is so hot that it can melt and {{3}} solid rock, creating the awe-inspiring volcanic landscapes we see on Earth.', NULL, NULL, NULL, E'1.substance, 2.erupts, 3.fuse', NULL, NULL),
  ('f86d204b-c672-5aa7-910a-96abea8ab681'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f86d204b-c672-5aa7-910a-96abea8ab681'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'e79e7e65-9880-5c6b-9e39-784afa5a82ce'::uuid, NULL, NULL, E'In the winter it gets harsh, but it won''t be an issue since there is a heater.', NULL, NULL),
  ('f88011ec-dec7-50a6-99eb-b9f6796bdcd3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f88011ec-dec7-50a6-99eb-b9f6796bdcd3'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the process of an organism gradually changing over generations called?', '8c6cdc60-5f11-5805-b417-a1fcd7fb2718'::uuid, NULL, NULL, E'Evolution', NULL, NULL),
  ('f88157cb-3782-5a06-8ccc-c1f8d854241a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f88157cb-3782-5a06-8ccc-c1f8d854241a'::uuid, 1, NULL, TRUE, 0, NULL, E'Microbes', NULL, 'cb7d7b05-9b8a-5f1b-b2d1-79ccbc423ce9'::uuid, NULL, E'So we had the idea, can we take some of these NASA-type ideas and apply them to our carbon problem here on Earth? Could we cultivate these NASA-type microbes in order to make valuable products here on Earth? And we started a company to do it. And in that company, we discovered that these hydrogenotrophs — which I’ll actually call nature’s supercharged carbon recyclers — we found that they are a powerful class of microbes that had been largely overlooked and understudied, and that they could make some really valuable products. So we began cultivating these products, these microbes, in our lab. We found that we can make essential amino acids from carbon dioxide using these microbes. And we even made a protein-rich meal that has an amino acid profile similar to what you might find in some animal proteins. We began cultivating them even further, and we found that we can make oil. Oils are used to manufacture many products. We made an oil that was similar to a citrus oil, which can be used for flavoring and for fragrances, but it also can be used as a biodegradable cleaner or even as a jet fuel. And we made an oil that’s similar to palm oil. Palm oil is used to manufacture a wide range of consumer and industrial goods.', NULL, NULL, NULL),
