  ('f8f412aa-e9d7-5fdb-b56c-2d7f3feefb83'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f8f412aa-e9d7-5fdb-b56c-2d7f3feefb83'::uuid, 1, NULL, TRUE, 0, NULL, E'Scandinavian Countries', E'The Scandinavian countries — Sweden, Norway, Denmark, and Finland — share a bond that goes beyond geographical proximity. These nations, with their Viking heritage, are known for their strong social welfare systems, commitment to equality, and high {{1}} of life. Despite their individual identities, they often present a united {{2}} on the global stage, particularly in areas like environmental conservation and human rights. With languages that are {{3}} intelligible to varying degrees and a shared history of collaboration and competition, the Scandinavian countries embody a unique {{4}} of rivalry and brotherhood. This camaraderie is evident in initiatives like the Nordic Council, which fosters cooperation in areas ranging from culture to legislation. Moreover, these countries face similar challenges, such as {{5}} their welfare models in the face of globalization and addressing the complexities of immigration in societies known for their homogeneity.', NULL, NULL, NULL, E'1.quality, 2.front, 3.mutually, 4.blend, 5.maintaining', NULL, NULL),
  ('f8f544a2-5a83-5704-a9b0-2f3a8746e0b3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'f8f544a2-5a83-5704-a9b0-2f3a8746e0b3'::uuid, 1, NULL, TRUE, 0, NULL, E'Whale', NULL, NULL, NULL, NULL, E'3, 1, 2, 4', NULL, NULL),
