  ('f8fe55f7-2ac2-53ad-94af-fb1e4cbd90a9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f8fe55f7-2ac2-53ad-94af-fb1e4cbd90a9'::uuid, 1, NULL, TRUE, 0, NULL, E'Labor Migration', E'Most countries are affected by labor migration. In many rural places, the traditional extended family has been undermined by the need for family members to migrate to towns as an economic necessity. Migration, therefore, presents a major challenge everywhere to social and economic policy.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f9009264-2667-557a-b6d6-2c9d3384ed0f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9009264-2667-557a-b6d6-2c9d3384ed0f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the largest country in South America?', '606b8733-7f82-5fcb-a8d8-4027e12674dd'::uuid, NULL, NULL, E'Brazil', NULL, NULL),
  ('f902a10b-4029-5c60-b744-3eff2f55160f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f902a10b-4029-5c60-b744-3eff2f55160f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2d8963d4-cdb4-51d6-9c3c-9cac04b4d9ef'::uuid, NULL, E'As a parent you need to choose the school that best suits your child.', NULL, NULL, NULL),
  ('f902e8a0-68af-5f76-bd88-ae2deaafcfa7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f902e8a0-68af-5f76-bd88-ae2deaafcfa7'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '557b244c-5528-5c3f-aeb3-a57fef907be5'::uuid, NULL, E'If she doesn''t speak the language, she''s not going to sit around and wait for a translator.', NULL, NULL, NULL),
  ('f9054ae6-ff57-5cc8-bbee-d2b98c11e97b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9054ae6-ff57-5cc8-bbee-d2b98c11e97b'::uuid, 1, NULL, TRUE, 0, NULL, E'How to Make Friends', NULL, '634d26f1-fc1c-5be5-a664-c645e5342c08'::uuid, NULL, E'People make friends with other people when they spend casual time together. This is how our ancestors formed their relationships, because humans lived in small, close knit communities in which options for making friends were limited, so we just formed good relationships with the people who were around us. This is why it is so easy to form new friendships in school and university. Society locks you and your peers in a building for several years. You share similar activities but more importantly: similar schedules. Overlapping and fluctuating social circles form, naturally giving you regular face time and shared experiences with many different people. Time to find others with similar world views or senses of humor. Proximity can be more important than similar interests. One study found that in student dormitories, the distance between rooms was the strongest friendship predictor – living closer together meant a higher chance of becoming friends. Another study showed that being physically present in a class a lot, without saying a word, makes others more sympathetic to you. So the most important principle of making friends is to regularly spend time with people in the real world. This alone can make it happen automatically and trumps all other advice.', NULL, NULL, NULL),
  ('f9094f2b-50ad-5eaa-80a5-c13ef5cbef06'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f9094f2b-50ad-5eaa-80a5-c13ef5cbef06'::uuid, 1, NULL, TRUE, 0, NULL, E'Plants and Animals', E'From the earliest civilisations, plants and animals have been portrayed as a means of understanding and recording the potential uses, such as their economic and healing properties. From the first illustrated {{1}} of medicinal plants, De Materia Medica by Dioscorides, in the first century through to the late fourteenth century the illustration of plants and animals changed very little. Woodcuts in instructional manuals and herbals were often repeatedly copied over the centuries, resulting in a loss of definition and accuracy so that they became little more than stylized decoration. With the growing {{2}} of copperplate engravings, the traditional use of woodcuts declined and the representation of plants and animals became more accurate. Then, with the {{3}} of artists such as Albrecht Durer and Leonardo Da Vinci, naturalists such as Otto Brunfels, Leonhard Fuchs in botany and Conrad Gesner and Ulisse Aldrovandi in zoology, nature began to be depicted in a more realistic style. Individual living plants or animals {{4}} directly and their likeness was rendered onto paper or vellum.', NULL, NULL, NULL, E'1.catalogue, 2.popularity, 3.emergence, 4.were observed', NULL, NULL),
  ('f91180ab-9001-5eba-a970-048630c39c92'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f91180ab-9001-5eba-a970-048630c39c92'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '4d56293b-dbd4-5b09-aea9-a998a9be4051'::uuid, NULL, NULL, E'His theories have never really been put to the test.', NULL, NULL),
  ('f911d918-a656-5720-8631-1ab92a21a83b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f911d918-a656-5720-8631-1ab92a21a83b'::uuid, 1, NULL, TRUE, 0, NULL, E'Voting rights', E'While voting would seem fundamental in a democracy, voting rights in the U.S. have long been {{1}} . The Constitution makes no stipulations {{2}} who can vote. Instead, it is left to the states to decide, and they have often tried — with {{3}} degrees of success — to limit voting.', NULL, NULL, NULL, E'1.contentious, 2.concerning, 3.varying', NULL, NULL),
  ('f91abb9d-bded-55cd-a574-fd191a593fb6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f91abb9d-bded-55cd-a574-fd191a593fb6'::uuid, 1, NULL, TRUE, 0, NULL, E'PPG', E'Constant monitoring of blood pressure is important for many patients, especially those with a family history of hypertension. In recent years, cuffless blood pressure has become a more popular method to {{1}} cardiovascular health and many of them {{2}} the optical technique, photoplethysmography (PPG). The PPG technique can be found in many {{3}} health monitoring devices because it is inexpensive and {{4}} to users.', NULL, NULL, NULL, E'1.monitor, 2.utilize, 3.commercial, 4.practical', NULL, NULL),
  ('f921da0a-8a8a-5092-a9b1-4b802935df53'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f921da0a-8a8a-5092-a9b1-4b802935df53'::uuid, 1, NULL, TRUE, 0, NULL, E'Legal System', E'This course provides an introduction to the history and development of the British legal system. Its aim is to describe the evolution of the Common Law of England, the legal system of England and to introduce you to the study of constitutions as law, and to the legal aspects of constitutional systems of Government.', NULL, NULL, NULL, NULL, NULL, NULL),
