  ('f94074d7-a7f8-5f35-b46b-e2ccd642a87c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f94074d7-a7f8-5f35-b46b-e2ccd642a87c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do we refer to a person who studies and practices law?', '6d97cb77-358a-513f-b0b3-b54a83e894bf'::uuid, NULL, NULL, E'Lawyer', NULL, NULL),
  ('f941d196-633e-5ef1-8367-ed8f591f05a5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', 'f941d196-633e-5ef1-8367-ed8f591f05a5'::uuid, 1, NULL, TRUE, 0, NULL, E'MCM-R', E'Fuller had scientific leanings and constantly experimented with electrical lighting (which was then in its infancy), colored gels, slide projections, and other aspects of stage technology. She invented and patented special arrangements of mirrors and concocted chemical dyes for her draperies. Her interest in color and light paralleled the research of several artists of the period, notably the painter Seurat, famed for his Pointillist technique of creating a sense of shapes and light on canvas by applying extremely small dots of color rather than by painting lines. One of Fuller''s major inventions was under lighting, in which she stood on a pane of frosted glass illuminated from underneath. This was particularly effective in her Fire Dance (1895), performed to the music of Richard Wagner''s "Ride of the Valkyries." The dance caught the eye of artist Henri de Toulouse-Lautrec, who depicted it in a lithograph.\n\nAccording to the paragraph, Fuller''s Fire Dance was notable in part for its', NULL, NULL, NULL, E'performance with music of Richard Wagner\ntechnique of lighting the dancer from beneath', NULL, NULL),
  ('f9446a69-4a3e-5a59-b55c-113ca8b49a12'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f9446a69-4a3e-5a59-b55c-113ca8b49a12'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5baf650d-578e-504d-b229-c933d90a05e0'::uuid, NULL, NULL, E'The project is challenging and requires a lot of dedication.', NULL, NULL),
  ('f94993ca-eed9-5ccf-b030-1d7199c43cbb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f94993ca-eed9-5ccf-b030-1d7199c43cbb'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'bb00223c-fbee-5f46-a884-9b59ab813078'::uuid, NULL, E'The nursing assistant was in charge of getting the tool for the doctor.', NULL, NULL, NULL),
  ('f949ef55-5b48-5b7e-8384-0c1f0a9e60a7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f949ef55-5b48-5b7e-8384-0c1f0a9e60a7'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'd01c99db-2ee3-5029-a200-667305109b2c'::uuid, NULL, E'This is a chance to take a risk, try something new and something that you like.', NULL, NULL, NULL),
  ('f94cae66-6371-5b46-a4db-b9566fcb2ff2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f94cae66-6371-5b46-a4db-b9566fcb2ff2'::uuid, 1, NULL, TRUE, 0, NULL, E'Schooling and Education', NULL, '7a0cfba2-8b31-5b41-a361-33766a610a42'::uuid, NULL, E'It is commonly believed in United States that school is where people go to get an education. Nevertheless, it has been said that today children interrupt their education to go to school. The distinction between schooling and education implied by this remark is important. Education is much more open-ended and all-inclusive than schooling. Education knows no bounds. It can take place anywhere, whether in the shower or in the job, whether in a kitchen or on a tractor. It includes both the formal learning that takes place in schools and the whole universe of informal learning. The agents of education can range from a revered grandparent to the people debating politics on the radio, from a child to a distinguished scientist. Whereas schooling has a certain predictability, education quite often produces surprises. A chance conversation with a stranger may lead a person to discover how little is known of other religions. People are engaged in education from infancy on. Education, then, is a very broad, inclusive term. It is a lifelong process, a process that starts long before the start of school, and one that should be an integral part of one''s entire life.\nSchooling, on the other hand, is a specific, formalized process, whose general pattern varies little from one setting to the next. Throughout a country, children arrive at school at approximately the same time, take assigned seats, are taught by an adult, use similar textbooks, do homework, take exams, and so on. The slices of reality that are to be learned, whether they are the alphabet or an understanding of the working of government, have usually been limited by the boundaries of the subject being taught. For example, high school students know that there not likely to find out in their classes the truth about political problems in their communities or what the newest filmmakers are experimenting with. There are definite conditions surrounding the formalized process of schooling.', NULL, NULL, NULL),
  ('f94cc2c7-63d7-5b1f-9eec-f8a2f1bae10a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'f94cc2c7-63d7-5b1f-9eec-f8a2f1bae10a'::uuid, 1, NULL, TRUE, 0, NULL, E'Ecology and Climatology', E'Ecology is the study of interactions of organisms among themselves and with their environment. It seeks to understand patterns in nature (e.g., the spatial and temporal distribution of organisms) and the processes governing those patterns. Climatology is the study of the physical state of the atmosphere – its instantaneous state or weather, its seasonal-to-interannual variability, its long-term average condition or climate, and how climate changes over time. These two fields of scientific study are distinctly different. Ecology is a discipline within the biological sciences and has as its core the principle of natural selection. Climatology is a discipline within the geophysical sciences based on applied physics and fluid dynamics. Both, however, share a common history.\nThe origin of these sciences is attributed to Aristotle and Theophrastus and their books Meteorological and Enquiry into Plants, respectively, but their modern beginnings trace back to natural history and plant geography. Seventeenth, eighteenth, and nineteenth century naturalists and geographers saw changes in vegetation as they explored new regions and laid the foundation for the development of ecology and climatology as they sought explanations for these geographic patterns. Alexander von Humboldt, in the early 1800s, observed that widely separated regions have structurally and functionally similar vegetation if their climates are similar. Alphonse de Candolle hypothesized that latitudinal zones of tropical, temperate, and arctic vegetation are caused by temperature and in 1874 proposed formal vegetation zones with associated temperature limits.', NULL, NULL, E'Ecology is the study of interactions of organisms among themselves and with their environment, while climatology is the study of the physical state of the atmosphere, so these two fields of scientific study are distinctly different, yet their modern beginnings trace back to natural history and plant geography, and widely separated regions have structurally and functionally similar vegetation if their climates are similar.', NULL, 5, 75),
  ('f94d6806-6917-5266-8b7b-ce450a9fce90'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'f94d6806-6917-5266-8b7b-ce450a9fce90'::uuid, 1, NULL, TRUE, 0, NULL, E'Foodborne Risk', E'Concerns over foodborne risk from birds may not be as severe as once thought by produce farmers, according to research from the University of California, Davis. Only one foodborne disease outbreak in produce has been conclusively traced to birds: a Campylobacter outbreak in peas from Alaska. Birds like starlings that flock in large numbers and forage on the ground near cattle are more likely to spread pathogenic bacteria to crops like lettuce, spinach and broccoli, according to the study of food safety risk and bird pathogens. In contrast, insect-eating species were less likely to carry pathogens. So not all bird species are equally risky.\n\nAccording to the passage, foodborne risk from birds ___.', NULL, NULL, NULL, E'is not as acute as once thought by farmers.', NULL, NULL),
  ('f95169c0-0e0b-5204-b9a5-ececf3da0ff2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f95169c0-0e0b-5204-b9a5-ececf3da0ff2'::uuid, 1, NULL, TRUE, 0, NULL, E'Wine and Ale', E'By the Bronze Age drinking {{1}} were being made of sheet metal, primarily bronze or gold.\nHowever, the peak of feasting – and in particular, of the “political” type of feast came in the late Hallstatt period (about 600 – 450 BC), soon after the foundation of the Greek {{2}} of Massalia (Marseille) at the mouth of the Rhine. From that date on, the blood of the grape began to make its way north and east along major river systems together with imported metal and ceramic drinking vessels from the Greek world. {{3}} was thus added to the list of mood- altering beverages – such as mead and ale available to establish social networks in Iron Age Europe. Attic pottery fragments found at hillforts such as Heuneburg in Germany and {{4}} goods such as the monumental 5th century Greek bronze krater found at Vix in Burgundy supply archaeological evidence of this interaction. Organic {{5}} such as leather or wooden wine barrels may also have travelled north into Europe but have not survived. It is unknown what goods were {{6}} in return, but they may have included salted meat, hides, timber, amber and slaves.', NULL, NULL, NULL, E'1.vessels, 2.colony, 3.Wine, 4.luxury, 5.containers, 6.traded', NULL, NULL),
  ('f95f2def-b005-5d97-aef0-0b31b40a888a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f95f2def-b005-5d97-aef0-0b31b40a888a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What type of government is ruled by representatives of the citizen body?', '651a338f-ca28-5f10-a887-decee3a9623c'::uuid, NULL, NULL, E'Republic', NULL, NULL),
  ('f96335e1-6466-5c6a-8454-3e5b1e6df44e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f96335e1-6466-5c6a-8454-3e5b1e6df44e'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which country is the statue of Liberty in?', '68e65939-024c-5120-8cfc-588bc793f539'::uuid, NULL, NULL, E'America / the US', NULL, NULL),
  ('f964eca5-579a-53d5-808a-9ec45c85d428'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f964eca5-579a-53d5-808a-9ec45c85d428'::uuid, 1, NULL, TRUE, 0, NULL, E'Occupational Therapy', E'Occupational therapy helps people of all ages who have physical, sensory or cognitive problems. It can help them regain independence in all areas of their lives. Occupational therapists help with barriers that affect a person''s emotional, social and physical needs. They also help kids to improve their school performance, and aid their daily activities. It also boosts their self-esteem and sense of accomplishment.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f9656562-a23e-5be7-a860-6bd2ad7a89cb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9656562-a23e-5be7-a860-6bd2ad7a89cb'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call the hard objects in your mouth for eating food?', 'aa4af266-8a25-5518-9059-e31a295fd9ec'::uuid, NULL, NULL, E'Teeth', NULL, NULL),
  ('f96bbf32-5d87-553e-913f-da50e72ad7ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f96bbf32-5d87-553e-913f-da50e72ad7ca'::uuid, 1, NULL, TRUE, 0, NULL, E'Passion', E'Do something you are very passionate about and do not try to chase what is considered the hot passion of the day. People say you have to have a lot of passion for what you’re doing, and it’s totally true. You have to do it over a sustained period of time. So, if you don’t love it, you’re going to give up.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f975f737-2d20-5851-b9c0-edeba6692d1d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f975f737-2d20-5851-b9c0-edeba6692d1d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'ab059f96-6dd7-5cc7-bc31-8953ea315aa2'::uuid, NULL, E'Glass is not a true solid because it does not have a crystal structure.', NULL, NULL, NULL),
  ('f97733c8-52ca-592f-934a-87449d09cc10'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'f97733c8-52ca-592f-934a-87449d09cc10'::uuid, 1, NULL, TRUE, 0, NULL, E'Profit', E'Businesses should do anything they can to make a profit. Do you agree with that?', NULL, NULL, E'In today''s society, businesses are often seen as entities that exist solely to make a profit. While profit is important for the success of a business, I do not agree that businesses should do anything they can to make a profit. In this essay, I will discuss the negative consequences of prioritizing profit over other values.\nOne major negative consequence of prioritizing profit over other values is the potential for unethical or illegal behavior. When businesses focus solely on making a profit, they may be willing to cut corners or engage in unethical practices to achieve their goals. This can have serious consequences for both business and society as a whole. For example, a business that prioritizes profit over safety may put its employees or customers at risk.\nAnother negative consequence of prioritizing profit over other values is the neglect of long-term planning. When businesses focus solely on short-term gains, they may neglect investments in research and development, employee training, or environmental sustainability. This can lead to negative consequences in the long-term, such as decreased competitiveness, employee turnover, or harm to the environment.\nIn conclusion, while profit is important for the success of a business, it should not be the sole focus. Prioritizing profit over other values such as ethics, employee well-being, or long-term planning can have serious negative consequences for both business and society as a whole. Businesses should strive to find a balance between making a profit and adhering to ethical and sustainable practices.', NULL, 200, 300),
  ('f978971d-7bf1-52f8-ae21-826c253763b4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'f978971d-7bf1-52f8-ae21-826c253763b4'::uuid, 1, NULL, TRUE, 0, NULL, E'Sandra Lousada', E'London''s National Portrait Gallery is currently celebrating the fifty-year {{1}} of photographer Sandra Lousada. The twenty one portraits on display depict key {{2}} in literature, film and fashion from the early 1960s. Subsequent to the acquisition of forty portraits by Lousada, the display at The National Portrait Gallery highlights shots taken between 1960 and 1964, many of which feature in Lousada''s book Public Faces Private Places (2008). Formal commissioned portraits are shown alongside behind-the-scenes photographs taken on film {{3}} and unguarded portraits of sitters captured at home.', NULL, NULL, NULL, E'1.career, 2.figures, 3.sets', NULL, NULL),
  ('f97a1628-7b93-519a-8aa4-37cdfa85e843'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f97a1628-7b93-519a-8aa4-37cdfa85e843'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '873c2c1d-6a04-55d3-a1b4-18fc74b332cd'::uuid, NULL, NULL, E'Working hard is not necessarily the norm in this university.', NULL, NULL),
  ('f97e77d4-7b30-5121-87d6-297df6e4b957'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f97e77d4-7b30-5121-87d6-297df6e4b957'::uuid, 1, NULL, TRUE, 0, NULL, E'Delay Discounting', E'Behavioral outcomes are devalued as a function of the delay until they are experienced. This process, known as delay discounting, is reliably associated with cigarette smoking and other tobacco use. Delay discounting is a potential therapeutic target in tobacco cessation. Thus, understanding how delay discounting influences inter-temporal choice is critical and may lead to efficacious interventions for tobacco use.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f9821f49-04ac-5d19-9263-05f10f0a0a2d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9821f49-04ac-5d19-9263-05f10f0a0a2d'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the device that cooks food using steam?', 'a14a29b9-3937-51fd-b3f4-8163b6e4c422'::uuid, NULL, NULL, E'Steamer', NULL, NULL),
