  ('f9851d20-53f3-5fd0-ab34-f72941a6b690'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f9851d20-53f3-5fd0-ab34-f72941a6b690'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'aa783c69-f462-53c6-a2e5-b742d5342b58'::uuid, NULL, NULL, E'The disease occurs most frequently in rural areas.', NULL, NULL),
  ('f9864268-691f-58f6-bc1b-0a9a9a459478'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f9864268-691f-58f6-bc1b-0a9a9a459478'::uuid, 1, NULL, TRUE, 0, NULL, E'Conservancy', E'To qualify as a conservancy, a committee must define the conservancy''s boundary, elect a {{1}} conservancy committee, negotiate a legal constitution, prove the committee''s ability to {{2}} funds, and produce an acceptable plan for {{3}} distribution of wildlife-related benefits. Once approved, registered conservancies acquire the {{4}} to a sustainable wildlife {{5}} , set by the ministry.', NULL, NULL, NULL, E'1.representative, 2.manage, 3.equitable, 4.rights, 5.quota', NULL, NULL),
  ('f9879245-9383-5bb5-8b43-900a4fb4cfd4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9879245-9383-5bb5-8b43-900a4fb4cfd4'::uuid, 1, NULL, TRUE, 0, NULL, E'Karl Marx', E'It has been 200 years since the birth of Karl Marx, but the German philosopher''s relevance has never been greater. The publication of Marx and Friedrich Engels'' The Communist Manifesto in 1848 was not greeted with great fanfare — a reception unbecoming what is now considered the most influential political pamphlet of all time.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f98b3256-c695-57b1-880e-4967a737cd28'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f98b3256-c695-57b1-880e-4967a737cd28'::uuid, 1, NULL, TRUE, 0, NULL, E'Language Acquisition', E'Thus language acquisition might be like other biological functions. The linguistic clumsiness of tourists and students might be the price we pay for the linguistic genius we displayed as babies, just as the decrepitude of age is the price we pay for the vigor of youth.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f98df074-5608-5981-8d7b-18477bd4b340'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f98df074-5608-5981-8d7b-18477bd4b340'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What’s the antonym of white?', '329d7886-fc63-5228-9bd5-cadc32a22b59'::uuid, NULL, NULL, E'Black', NULL, NULL),
