  ('f9a0f0f0-b840-5508-9381-ef904ba3e067'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f9a0f0f0-b840-5508-9381-ef904ba3e067'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'bd89a0d2-5212-59de-b635-e06ee39bc606'::uuid, NULL, NULL, E'More and more women are now engaging in education career.', NULL, NULL),
  ('f9a39e02-a96f-5c2d-ad44-5f1e3369222a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9a39e02-a96f-5c2d-ad44-5f1e3369222a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a fracture or discontinuity in a volume of rock, across which there has been significant displacement?', 'cab65fda-9e94-53c6-8734-cb28230d29d5'::uuid, NULL, NULL, E'Fault', NULL, NULL),
  ('f9a6a217-566d-5e8f-a591-cf891d5c2917'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9a6a217-566d-5e8f-a591-cf891d5c2917'::uuid, 1, NULL, TRUE, 0, NULL, E'Initial Thud', E'The initial thud comes from when those dorsal bursae collide. And the reverberation results from the vibrations that linger when the tissues pull apart. But Thode the younger says the bursae have to be somewhat sticky for the clapping together and snapping apart to produce a noise with the correct loudness and pitch. That stickiness comes courtesy of the mucus.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f9acc107-c929-5f81-bb72-169032703014'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f9acc107-c929-5f81-bb72-169032703014'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '1f7f1b1d-b006-5bf9-85cf-ac82f2e3f99f'::uuid, NULL, NULL, E'He translated the speech from Spanish into Indian.', NULL, NULL),
  ('f9b24cef-89ec-55fe-98f0-2e33d84fb22a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9b24cef-89ec-55fe-98f0-2e33d84fb22a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'fadbb6a2-0895-56a9-a6d9-260ff6d72a87'::uuid, NULL, E'We will study the following two pictures in the next lecture.', NULL, NULL, NULL);
