  ('f9b5a0f5-c0c2-5f7e-bcbb-19e3c06e0862'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9b5a0f5-c0c2-5f7e-bcbb-19e3c06e0862'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do people with claustrophobia fear?', '360b9a60-2ee6-5c63-8af5-2ea3082e980b'::uuid, NULL, NULL, E'Confined space', NULL, NULL),
  ('f9b74601-c759-55d3-9a9a-849f74f2388d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9b74601-c759-55d3-9a9a-849f74f2388d'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '44c7e2c2-3a67-50cd-9588-256c7f36da5f'::uuid, NULL, E'We''ve confirmed the dates and have organized some additional optional activities.', NULL, NULL, NULL),
  ('f9bd146b-feb3-5f60-8a47-65de0dd7db7a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'f9bd146b-feb3-5f60-8a47-65de0dd7db7a'::uuid, 1, NULL, TRUE, 0, NULL, E'Cellphones and Travel', E'The desire to share our experiences has led to an increase in technology becoming a primary reason for travel, with research finding that two-fifths of millennials are actually choosing their travel destination based on how ''Instagrammable'' it is.\nAn added incentive for people who use technology on holiday are the new laws which came into play on 15th June which mean roaming charges across Europe are abolished, so phone users no longer need worry about costs involved in making calls or using the internet when abroad – making it easier than ever to keep in touch and share content with those at home.\nWhether it''s to research must-see things in the area, compare hotel prices, or simply use digital maps to help us get around, it''s undeniable that technology plays an increasing role in our travels. As a result it’s enhancing the travel experience by making it simpler to plan visits and stay safe. And it''s not just for gap year students wanting to visit the location which will get them the most ‘likes’, technology can be used to significantly enhance the traveling experience for all types of wanderer, from solo travelers to retirees.\nWith GPS it''s never been easier to explore hidden locations, while staying confident that you''re safe off the beaten track. AroundMe is an app that identifies the user’s position and shows recommendations, reviews and attractions, along with distances from where they are, offering up a whole new side of a destination that otherwise may go unknown. Sites like TripAdvisor are regularly being turned to for recommendations as opposed to travel guides, with research showing that millennials in particular trust user-generated content 50 per cent more than other media. Having access to regularly updated travel reviews opens up a wealth of options, meaning travelers can be more spontaneous when choosing destinations as they will be able to access recommendations as they go. Holiday-goers don''t have to worry about meticulously planning a trip and can concentrate on enjoying the experience.', NULL, NULL, NULL, NULL, 5, 75),
  ('f9bde617-589e-5e69-b4ff-734cd16a5ca7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9bde617-589e-5e69-b4ff-734cd16a5ca7'::uuid, 1, NULL, TRUE, 0, NULL, E'Rat’s Eye', E'It’s unclear why the animals look forever young, but it may be because their native lakes never dried up, at least not before Spanish colonizers started draining lakes near present-day Mexico City to control flooding in the 1600s. Other amphibians that live in areas with transient streams or lakes mature from water-living young into adults capable of thriving on land or in water.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f9c166aa-c0ce-5f17-b4d7-5ccbb4d913b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9c166aa-c0ce-5f17-b4d7-5ccbb4d913b8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the path by which satellites revolve around the earth?', 'c6fb4871-1cfc-52dd-bf78-699b810f7aea'::uuid, NULL, NULL, E'Orbit', NULL, NULL),
  ('f9c4aa7f-6bea-5698-9abb-558bf956a2a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9c4aa7f-6bea-5698-9abb-558bf956a2a6'::uuid, 1, NULL, TRUE, 0, NULL, E'World Heritage Sites', E'World Heritage Sites are places of outstanding cultural or natural significance that are recognized by UNESCO. They represent the shared heritage of humanity and serve as reminders of our cultural and natural diversity. By protecting these sites, we can ensure that they remain accessible to future generations.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f9c5beec-fc63-52c2-9fc6-5aed5a69945f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9c5beec-fc63-52c2-9fc6-5aed5a69945f'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '837389e3-2527-5b41-8441-88d25e8eebcf'::uuid, NULL, E'The students usually complete their projects in November.', NULL, NULL, NULL),
  ('f9c7208d-f4a8-51f9-9dce-e024092b2cc8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9c7208d-f4a8-51f9-9dce-e024092b2cc8'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the condition of being unable to sleep?', 'af86bd54-4f0d-51ef-b95a-fc15e8c931ce'::uuid, NULL, NULL, E'Insomnia / sleeplessness', NULL, NULL),
  ('f9c9e423-1c4d-5120-8307-44dd328be731'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9c9e423-1c4d-5120-8307-44dd328be731'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6212d887-2d58-52be-82fe-6b505bdd264a'::uuid, NULL, E'The police car was parked in the furthest corner of the courtyard.', NULL, NULL, NULL),
  ('f9cce2e6-547b-5283-bc7d-f61dd3c28809'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'f9cce2e6-547b-5283-bc7d-f61dd3c28809'::uuid, 1, NULL, TRUE, 0, NULL, E'Stay or Move', E'The old generation prefer to spend their entire lives in only one place, but nowadays young people would like to move many times to find a suitable place. Which one would you prefer?', NULL, NULL, NULL, NULL, 200, 300),
