  ('f9d3e39e-db55-580c-bce7-5af61545eafd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9d3e39e-db55-580c-bce7-5af61545eafd'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a diagram in which an object would appear to viewers if it were cut from top to bottom?', '5129efa1-f1b9-5cf0-bcc8-110c4cccca31'::uuid, NULL, NULL, E'Section', NULL, NULL),
  ('f9d5d2ac-452d-5fda-96dd-2d20b5674d81'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9d5d2ac-452d-5fda-96dd-2d20b5674d81'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call a list in a book which outlines the structure of the book?', 'f90732b1-d574-50b5-a366-626b6d3ccae2'::uuid, NULL, NULL, E'Table of contents', NULL, NULL),
  ('f9d80c11-eb81-5506-9a70-33f7e9798b49'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9d80c11-eb81-5506-9a70-33f7e9798b49'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the field of study that studies the human mind and behavior?', '43eb4aab-70f8-5b52-be01-379779bd5e70'::uuid, NULL, NULL, E'Psychology', NULL, NULL),
  ('f9e3b0e9-e273-5af8-ab35-bcd00028eb1e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'f9e3b0e9-e273-5af8-ab35-bcd00028eb1e'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '6456493b-8096-5ebe-9776-f3f9755d02a2'::uuid, NULL, NULL, E'Traffic is the main cause of air pollution in many cities.', NULL, NULL),
  ('f9e42b84-a579-5077-acb1-3023e1988abd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9e42b84-a579-5077-acb1-3023e1988abd'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How many sides are there in a bilateral agreement?', 'dac9bf5c-cf36-50b4-a7f3-4d8eb4dc2dd0'::uuid, NULL, NULL, E'Two', NULL, NULL),
  ('f9e8ebf3-5308-52aa-bf78-68ca199fe9f4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9e8ebf3-5308-52aa-bf78-68ca199fe9f4'::uuid, 1, NULL, TRUE, 0, NULL, E'Glaciers and Volcano', E'The fine details of how glaciers are linked to volcanic eruptions are unknown. But volcanologists theorize pressure is key. The idea is the weight of large ice sheets compresses the crust and mantle below. That closes up channels within the rock through which magma travels up. It leaves less room for surface water to make its way down into the rocks, where it can increase the pressure within magma chambers.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f9e9574d-d827-5dd0-805d-1fb078873438'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9e9574d-d827-5dd0-805d-1fb078873438'::uuid, 1, NULL, TRUE, 0, NULL, E'Desalination', E'Desalination is the answer to long-term water security, but it’s also expensive and energy-intensive. The good news is that scientists are developing some viable solutions. The first desalination plant in Europe was built in Spain nearly a half-century ago. Since then, facilities have sprung up in water-stressed regions throughout Europe.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('f9ec36d6-3038-5a70-b7b7-5595967a7460'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9ec36d6-3038-5a70-b7b7-5595967a7460'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '4a122782-21f2-59e4-9d39-c2446913eebc'::uuid, NULL, E'The new model combines a telephone and a fax machine.', NULL, NULL, NULL),
  ('f9f1b2c5-f24e-5c34-90af-d4644b59f70b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9f1b2c5-f24e-5c34-90af-d4644b59f70b'::uuid, 1, NULL, TRUE, 0, NULL, E'Biological Thinking', NULL, 'cd4967ff-e3a5-5e7a-847b-5ba841ed540a'::uuid, NULL, E'Now typically, when we think about business, we use what I call “mechanical thinking.” We set goals, we analyze problems, we construct and we adhere to plans, and more than anything else, we stress efficiency and short-term performance. Now, don’t get me wrong — this is a splendidly practical and effective way of addressing relatively simple challenges in relatively stable environments. It’s the way that Bob — and probably many of us, myself included — process most business problems we’re faced with every day. In fact, it was a pretty good mental model for business — overall — until about the mid-1980s, when the conjunction of globalization and a revolution in technology and telecommunications made business far more dynamic and unpredictable. But what about those more dynamic and unpredictable situations that we now increasingly face? I think in addition to the mechanical thinking, we now need to master the art of biological thinking, as embodied by our six principles. In other words, we need to think more modestly and subtly about when and how we can shape, rather than control, unpredictable and complex situations.', NULL, NULL, NULL),
  ('f9f54936-36ec-55b4-953d-66f79eb2f399'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'f9f54936-36ec-55b4-953d-66f79eb2f399'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c81681d4-8555-5a26-95d3-8239e04b905c'::uuid, NULL, E'The website has probably the most attractive designs and layouts.', NULL, NULL, NULL),
  ('f9f83736-3432-5c8d-977f-37a4f6ba1d0d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'f9f83736-3432-5c8d-977f-37a4f6ba1d0d'::uuid, 1, NULL, TRUE, 0, NULL, E'AI Symphony', E'A symphony composed entirely by artificial intelligence has {{1}} to a mixed reception. The piece, a collaboration between AI developers and music theorists, challenges traditional {{2}} of creativity. While some hail it as a {{3}} of modern technology, others question the emotional depth of music {{4}} by algorithms. The {{5}} continues as AI begins to blur the lines in artistic domains.', NULL, NULL, NULL, E'1.premiered, 2.notions, 3.masterpiece, 4.created, 5.debate', NULL, NULL),
  ('fa01ac10-49d9-5348-8ead-af177e52dde2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'fa01ac10-49d9-5348-8ead-af177e52dde2'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '665793a0-c62f-52cb-bea6-478c082c7f4b'::uuid, NULL, E'He ordered some new books from America on a website.', NULL, NULL, NULL),
  ('fa08cfe7-ebcf-57a1-aa80-9761d0f04c32'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'fa08cfe7-ebcf-57a1-aa80-9761d0f04c32'::uuid, 1, NULL, TRUE, 0, NULL, E'Art', E'Art is everywhere, but many people feel like they don''t understand it. They may wonder what the artist is trying to say, or how to {{1}} to a painting or a sculpture. However, art is not something that requires a special knowledge or a degree to appreciate. It is {{2}} communication that can spark our imagination, emotions, and memories. One way to approach art is to see it as an interactive adventure, {{3}} a passive observation. Instead of just glancing at a work for a few seconds, try to spend some time with it and {{4}} the details, colors, shapes, and textures. Ask yourself what the work makes you think of, feel, or remember. You may find connections to your own life, culture, or history.', NULL, NULL, NULL, E'1.relate, 2.a form of, 3.rather than, 4.notice', NULL, NULL),
  ('fa0b16c7-87cb-5679-aa76-794fee73b1ac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'fa0b16c7-87cb-5679-aa76-794fee73b1ac'::uuid, 1, NULL, TRUE, 0, NULL, E'Overburden', E'Nowadays, more and more people believed that overburden can help complete higher quality in achievements. For example, professional teachers, coaches believe that this applies to students and athletes, on the individual and national level. What is your point of view? Give examples to support it.', NULL, NULL, NULL, NULL, 200, 300),
  ('fa13d3cf-da04-587a-8155-5ac3f816d0f1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'fa13d3cf-da04-587a-8155-5ac3f816d0f1'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '0fcf345e-96d7-54b6-bfa1-0f9015e11357'::uuid, NULL, NULL, E'The team has been successful in achieving challenging objectives.', NULL, NULL),
