  ('fa4d2f47-ca47-5d29-a3d3-5ef4345f22a4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'fa4d2f47-ca47-5d29-a3d3-5ef4345f22a4'::uuid, 1, NULL, TRUE, 0, NULL, E'New Year’s Resolutions', E'Every year, millions of people make New Year’s resolutions to improve their lives, such as losing weight, quitting smoking, or saving money. However, many of these resolutions are too vague, unrealistic, or overwhelming, and {{1}} up being abandoned within weeks or months. How can we avoid this cycle of {{2}} and failure? One possible solution is to embrace the concept of kaizen, a Japanese term meaning “change for the better” or “continuous improvement”. Kaizen is a philosophy that focuses on making small, incremental changes that are easier to {{3}} and sustain, rather than trying to achieve big, radical transformations. Kaizen can be applied to any aspect of life, from personal habits to professional skills, by following a simple process: identify a problem, set a specific and measurable goal, take {{4}} , monitor progress, and adjust as needed. Kaizen encourages us to celebrate every small success and learn from every setback, rather than giving up or feeling guilty. By applying kaizen to our New Year’s resolutions, we can make positive changes {{5}} .', NULL, NULL, NULL, E'1.end, 2.frustration, 3.implement, 4.action, 5.that last', NULL, NULL),
  ('fa4eadc7-69ba-56d2-bbfb-17da9db5071c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'fa4eadc7-69ba-56d2-bbfb-17da9db5071c'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '90fc927e-9682-5d32-acbc-a9e8cfe50ab8'::uuid, NULL, NULL, E'My article has been accepted for publication in the next month.', NULL, NULL),
