  ('fa59ae25-b5d9-5541-8bfd-c060ca3c8509'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_ESSAY', E'WRITE_ESSAY', E'WRITING', E'SHARED', NULL, E'APPROVED', 'fa59ae25-b5d9-5541-8bfd-c060ca3c8509'::uuid, 1, NULL, TRUE, 0, NULL, E'Communication Type', E'Face-to-face communication is more efficient than other types of communication, such as letter, or phone calls. Do you agree or disagree with it?', NULL, NULL, NULL, NULL, 200, 300),
