  ('fa6f84a9-89e6-586e-80e0-8ce1ee8c0962'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'fa6f84a9-89e6-586e-80e0-8ce1ee8c0962'::uuid, 1, NULL, TRUE, 0, NULL, E'Gig Economy', E'The rise of the gig economy, characterized by short-term contracts and freelance work as opposed to permanent jobs, has fundamentally altered the landscape of labor and employment. This new economy has {{1}} worker identity, moving away from traditional roles and fostering a culture of entrepreneurial self-reliance. Individuals now often {{2}} multiple gigs, blending their professional and personal lives in unprecedented ways. This shift reflects broader societal changes, valuing adaptability and innovation over stability and {{3}} . However, the gig economy raises critical questions about workers'' rights, social protection, and the long-term sustainability of this model. The absence of traditional employment {{4}} such as health insurance, retirement plans, and stable income streams has sparked debates among policymakers, labor unions, and gig workers themselves. As the gig economy continues to evolve, it challenges conventional norms of work, {{5}} us to reconsider the social contract between employers and employees and the very nature of work in the 21st century.', NULL, NULL, NULL, E'1.redefined, 2.juggle, 3.routine, 4.safeguards, 5.pushing', NULL, NULL),
  ('fa74653a-dfc9-5cc5-a54c-6e2048e0a70b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'fa74653a-dfc9-5cc5-a54c-6e2048e0a70b'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'f6590f74-40ef-5c02-aa24-90bf78f4d18d'::uuid, NULL, E'Key aspects of this investigative paradigm may prove useful in other spheres.', NULL, NULL, NULL),
