  ('fa7ed9a1-70d3-544c-8c82-f2607cac0fb2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'fa7ed9a1-70d3-544c-8c82-f2607cac0fb2'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6b7f186f-07cf-5778-8536-a08357298e53'::uuid, NULL, E'Infringement of this regulation would automatically rule you out of the membership.', NULL, NULL, NULL),
