  ('fa84cc12-e4b4-583f-99a0-f77c2fc49d8e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'fa84cc12-e4b4-583f-99a0-f77c2fc49d8e'::uuid, 1, NULL, TRUE, 0, NULL, E'Transparent Wood', E'A team of researchers claim to have created a biodegradable and {{1}} alternative to both glass and plastic in the form of “transparent wood,” a futuristic new material that could greatly reduce the ecological impact of more environmentally-unfriendly building materials. The material, which was invented by German scientist Siegfried Fink in 1992, has seen several changes and improvements over the intervening years. It’s made by first removing a naturally occurring polymer called lignin from wood and {{2}} it with specially-designed, transparent plastic materials. Plastics are used as a substitute for glass which is (naturally) fragile,” Dhar said. “However, transparent wood is an even better alternative from an ecological {{3}} as observed in our life-cycle analysis. In recent times transparent wood has been used in construction, energy storage, flexible electronics and packaging applications. But it won’t be replacing glass and plastic in their entirety anytime soon because scientists have yet to figure out how to {{4}} up production of the material in an economical way.', NULL, NULL, NULL, E'1.renewable, 2.replacing, 3.perspective, 4.scale', NULL, NULL),
  ('fa93f6d6-8902-5e00-a321-ef17cfffd8bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'fa93f6d6-8902-5e00-a321-ef17cfffd8bd'::uuid, 1, NULL, TRUE, 0, NULL, E'Literature', E'Literature allows us to move beyond the inevitable boundaries of our own lives and culture because it introduces us to people different from ourselves, places remote from our neighborhoods, and times other than our own. Reading makes us more aware of life''s possibilities as well as its subtleties and ambiguities.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('faa539b5-0160-5254-8673-827e1aa83afb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'faa539b5-0160-5254-8673-827e1aa83afb'::uuid, 1, NULL, TRUE, 0, NULL, E'Attendance', E'To some extent, attendance at cultural venues and events is influenced by a person''s age and the composition of the household in which they live. For example, those people in households with dependent children were more likely to visit zoological parks and aquariums than people living in single person households.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('faaaec8b-63eb-5bdc-b11e-9e87b8c0a194'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'faaaec8b-63eb-5bdc-b11e-9e87b8c0a194'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'If a flight is not international, then what is it called?', 'f936d1d8-4c7e-5755-8c2d-d7e97586f0ac'::uuid, NULL, NULL, E'Domestic', NULL, NULL),
  ('faad2abe-1e4e-5d98-b2ed-7a43156f11d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'faad2abe-1e4e-5d98-b2ed-7a43156f11d8'::uuid, 1, NULL, TRUE, 0, NULL, E'The Border', E'The border itself between Mexico and United States is fraught with a mix of urban and desert terrain and spans over 1,900 miles. Both the uninhabited areas of the border and urban areas are where the most drug trafficking and illegal crossings take place. Crime is prevalent in urban cities like El Paso, Texas and San Diego, California.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('fab606c9-47c9-5752-9290-cc1c5440433c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'fab606c9-47c9-5752-9290-cc1c5440433c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '8a93ac6f-6c66-51a7-a487-841c1496f7c0'::uuid, NULL, E'We offer a variety of courses catering to our students'' diverse needs.', NULL, NULL, NULL),
  ('fab78b97-3a86-5494-aeb9-830c11f5a041'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'fab78b97-3a86-5494-aeb9-830c11f5a041'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '635c64b3-1dfe-5e56-9962-a6a2da0a5a6d'::uuid, NULL, NULL, E'Students can find news about climate change.', NULL, NULL),
  ('fabef9b4-bc05-5455-ad7e-21aa3bc68ccc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'fabef9b4-bc05-5455-ad7e-21aa3bc68ccc'::uuid, 1, NULL, TRUE, 0, NULL, E'Roman', E'The Roman state was tested almost to destruction by the defeat at Cannae by the Carthaginians led by Hannibal – and according to the historian Polybius, it was only what he called the “peculiar virtues” of the Roman constitution that allowed it to survive this crisis.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('fac2d353-9644-5da0-bc50-891de072591f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'fac2d353-9644-5da0-bc50-891de072591f'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a person who owns shares in a company or business?', 'c3743ffa-1f24-5043-a57a-5a46349d1619'::uuid, NULL, NULL, E'Shareholder / stockholder', NULL, NULL),
