  ('fb71793e-4043-5959-b1f6-2a5e120a2dd6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'fb71793e-4043-5959-b1f6-2a5e120a2dd6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '2659db12-1ccf-5047-8aa4-8bb5bbee9b8d'::uuid, NULL, E'The office opens on Monday and Thursday following the freshman seminar.', NULL, NULL, NULL),
  ('fb7358bf-b6b3-559e-ba11-a7d09b1eadcf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'fb7358bf-b6b3-559e-ba11-a7d09b1eadcf'::uuid, 1, NULL, TRUE, 0, NULL, E'Trigger Points', E'All approaches aim to increase blood flow to areas of tension and to release painful knots {{1}} muscle known as "trigger points". "Trigger points are tense areas of muscle that are almost constantly contracting," says Kippen. "The contraction causes pain, which in turn causes contraction, so you have a vicious circle. This is what deep tissue massage aims to break. "The way to do this, as I found out under Ogedengbe''s elbow, is to apply pressure {{2}} the point, stopping the blood flow, and then to release, which causes the brain to flood the affected area {{3}} blood, encouraging the muscle to relax. At the same time, says Kippen, you can fool the tensed muscle {{4}} relaxing {{5}} applying pressure to a complementary one nearby. "If you cause any muscle to contract, its opposite will expand. So you try to trick the body into relaxing the muscle that is in spasm."', NULL, NULL, NULL, E'1.of, 2.to, 3.with, 4.into, 5.by', NULL, NULL),
