  ('fcebb48b-86b1-557d-afad-da70791ad163'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'fcebb48b-86b1-557d-afad-da70791ad163'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which of these would probably be found in most homes around the world -a computer, a bed or a television?', 'b7cb0e42-a322-520f-9e9f-657c3cac05c0'::uuid, NULL, NULL, E'Bed', NULL, NULL),
