  ('fcfe7939-29eb-5394-933f-d6a437914abe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'fcfe7939-29eb-5394-933f-d6a437914abe'::uuid, 1, NULL, TRUE, 0, NULL, E'Water', E'Approximately 75% of the Earth’s surface is {{1}} by liquid water and ice. Water is {{2}} moving between the atmosphere, land, and ocean, shaping our planet’s climate and ecosystems. Human population growth has increased the {{3}} and use of water, which in turn reduced freshwater {{4}} in many regions, both for human consumption and for ecosystems.', NULL, NULL, NULL, E'1.covered, 2.constantly, 3.extraction, 4.availability', NULL, NULL),
