  ('fd05a4b6-d225-53fa-8a74-95db51f5d82b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'fd05a4b6-d225-53fa-8a74-95db51f5d82b'::uuid, 1, NULL, TRUE, 0, NULL, E'Healthcare', E'In the fast-changing world of modern healthcare, the job of a doctor is more like the job of chief executive. The people who run hospitals and physicians'' practices don''t just need to know {{1}} . They must also be able to balance budgets, motivate a large and diverse {{2}} and make difficult marketing and legal {{3}} .', NULL, NULL, NULL, E'1.medicine, 2.staff, 3.decisions', NULL, NULL),
  ('fd078d35-17d7-5728-b206-f8af0de9ec9d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'fd078d35-17d7-5728-b206-f8af0de9ec9d'::uuid, 1, NULL, TRUE, 0, NULL, E'Sibling Bullying', E'Sibling bullying associated with poor mental health outcomes years later. Scientists found sibling bullying in early adolescence, irrespective of whether the individual was a victim, perpetrator, or both, has a long-term effect on both positive and negative mental health in late adolescence.', NULL, NULL, NULL, NULL, NULL, NULL),
