  ('fd25f90e-232c-5d9e-aa3c-fe542d10536c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'fd25f90e-232c-5d9e-aa3c-fe542d10536c'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the other form of water other than gas and solid?', '1a8ec4d6-73f4-50ae-877b-dec556b496c7'::uuid, NULL, NULL, E'Liquid / fluid', NULL, NULL),
  ('fd2efbc3-15ff-552c-8733-d7e7d1469ffd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_MULTIPLE', E'MC_READING_MULTIPLE', E'READING', E'SHARED', NULL, E'APPROVED', 'fd2efbc3-15ff-552c-8733-d7e7d1469ffd'::uuid, 1, NULL, TRUE, 0, NULL, E'Ancient DNA', E'Analysis of ancient DNA from one of the best-preserved Neolithic tombs in Britain has revealed that most of the people buried there were from five continuous generations of a single extended family.\nBy analyzing DNA extracted from the bones and teeth of 35 individuals entombed at Hazleton North long cairn in the Cotswolds-Severn region, the research team was able to detect that 27 of them were close biological relatives. The group lived approximately 5700 years ago -- around 3700-3600 BC -- around 100 years after farming had been introduced to Britain.\nPublished in Nature, it is the first study to reveal in such detail how prehistoric families were structured, and the international team of archaeologists and geneticists say that the results provide new insights into kinship and burial practices in Neolithic times.\n\nWhat has been revealed by analysis of ancient DNA from one of Britain''s best-preserved Neolithic tombs?', NULL, NULL, NULL, E'More than half of them were close relatives.\nIt reveals the details of the organization of the prehistoric family.', NULL, NULL),
  ('fd3139b9-b677-578f-ab72-6257257708d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'fd3139b9-b677-578f-ab72-6257257708d3'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'addafa09-cce6-50c1-b4e4-fa5862e76caa'::uuid, NULL, NULL, E'The department will continue to offer three new scholarships next year.', NULL, NULL),
  ('fd316d89-ec46-5788-b512-48d049450303'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'fd316d89-ec46-5788-b512-48d049450303'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'eec769a7-8046-5c37-97a3-3cbbcfe0efd6'::uuid, NULL, E'The student service center is located on the main campus behind the library.', NULL, NULL, NULL),
