  ('fd364b46-030f-5de2-ae04-9ed846181ce1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'fd364b46-030f-5de2-ae04-9ed846181ce1'::uuid, 1, NULL, TRUE, 0, NULL, E'Urban Diet', E'As the United States began to grow in the nineteenth century and especially when people started {{1}} into cities, food and daily diet became more than a {{2}} to simple survival. For those leaving farms by the end of the century and entering into America''s manufacturing workforce, exercise and eating patterns changed to meet the {{3}} of factory work, coal mines, and other venues through which people began to earn their {{4}} .', NULL, NULL, NULL, E'1.crowding, 2.means, 3.rigors, 4.living', NULL, NULL),
  ('fd39f3ed-f19e-5ca3-9e4a-547ab93f8510'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'fd39f3ed-f19e-5ca3-9e4a-547ab93f8510'::uuid, 1, NULL, TRUE, 0, NULL, E'Ethnobotanical Study', E'A landmark ethnobotanical study recently uncovered the use of a previously unknown medicinal plant among {{1}} tribes in the Amazon. Researchers, collaborating with the tribes, are now {{2}} into the plant''s potential, respecting the traditional knowledge while {{3}} its application in modern medicine. The plant, which the tribes call "yakumama", has shown {{4}} anti-inflammatory and anti-microbial properties in preliminary tests.', NULL, NULL, NULL, E'1.indigenous, 2.delving, 3.exploring, 4.promising', NULL, NULL),
  ('fd3a040d-5ce3-52d9-9492-234a3a658aae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'fd3a040d-5ce3-52d9-9492-234a3a658aae'::uuid, 1, NULL, TRUE, 0, NULL, E'Leader Waves', E'The next wave of leaders in industrial manufacturing will build an ecosystem that capitalizes on the promise of analytics and connectivity to maximize efficiency for themselves and their customers. They will map out their strategies and prioritize measures that will bring the most value to their business, starting now with pilot projects, and building greater strengths in data analytics with cross-functional teams of experts.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('fd3ca19a-26d1-57ad-8429-4f9043764562'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'fd3ca19a-26d1-57ad-8429-4f9043764562'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'dcef5811-f93b-557e-a7be-52fad0d1dccf'::uuid, NULL, NULL, E'The designers have plans to finalize the project by today.', NULL, NULL),
  ('fd3dd1ab-ebbc-5c77-8553-928adc94172a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_ORDER_PARAGRAPHS', E'RE_ORDER_PARAGRAPHS', E'READING', E'SHARED', NULL, E'APPROVED', 'fd3dd1ab-ebbc-5c77-8553-928adc94172a'::uuid, 1, NULL, TRUE, 0, NULL, E'Chalk River(粉笔河)', NULL, NULL, NULL, NULL, E'4, 1, 2, 3', NULL, NULL),
  ('fd41f733-560a-53fe-a0e1-967e3c2c9ea9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'fd41f733-560a-53fe-a0e1-967e3c2c9ea9'::uuid, 1, NULL, TRUE, 0, NULL, E'Rowley', E'Rightly is they called pigs, said Rowley, a farm laborer looking at the wallowing animals before passing on to the cow sheds, in Aldous Huxley''s novel Chrome Yellow. Those who heard his words commented on his wisdom.This raises all sorts of questions about language and how we perceive the world, questions that range from the philosophical to the politically correct (PC) use of language and the question of causing offense — for example, calling someone a pig.Those who believed in being PC tried to adjust language to take into account people''s sensitivities in the areas of race, sexuality and disability, and a theologian has recently written that we should do the same for the animal kingdom. To call them wild or beasts is, he says, derogatory and offensive. I''m all in favor of animal welfare, but, in arguing his case, he says that language is the means by which we understand and conceptualize the world around us.But is it? Isn''t it the other way round? To put it another, very simple, way: do you believe that the language you use has made you think of the world in a certain way, or that you have an idea of the world as it is and your place in it, and you use language to understand and describe it?Is Rowley''s wisdom based on his many years working with farm animals, and what he has seen is justpigs being pigs and there''s nothing more to be said? Or has he decided that the name pig suits thesecreatures because they behave piggishly? If we cleaned them up, taught them table manners and madethem wear a tie, would we have to call them something else?\n\nWhat is the main reason for the writer mentioning Rowley?', NULL, NULL, NULL, E'To illustrate his view about the use of language.', NULL, NULL),
  ('fd42d7f0-40ea-585d-b2b2-ddce14fa2889'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'fd42d7f0-40ea-585d-b2b2-ddce14fa2889'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'd18d0fd3-09ff-5431-9ff6-4548b2d9284c'::uuid, NULL, NULL, E'People in this country enjoy a high standard of living.', NULL, NULL),
