  ('fdc8e0e4-db8c-555b-8d5b-2a4d2a8af1bc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'fdc8e0e4-db8c-555b-8d5b-2a4d2a8af1bc'::uuid, 1, NULL, TRUE, 0, NULL, E'Education', E'Education is generally considered to be a key factor in improving outcomes for Indigenous Australians, with many studies showing that improved {{1}} and socioeconomic status are directly {{2}} to educational participation and achievement. There is a range of issues {{3}} participation in education for Indigenous Australians, including {{4}} to educational institutions, financial constraints, and community {{5}} .', NULL, NULL, NULL, E'1.health, 2.linked, 3.affecting, 4.access, 5.expectations', NULL, NULL),
