  ('fddb83a0-e24a-57cf-88bc-ea62b080fad9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'fddb83a0-e24a-57cf-88bc-ea62b080fad9'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Would it be better to go jogging at noon or in the early morning if you want to avoid the hottest part of the day?', '4b3f58a6-8a54-52a1-9b64-a6bfe552838f'::uuid, NULL, NULL, E'In the early morning', NULL, NULL),
