  ('ff382cc5-00a2-5f68-9d90-fe4b0150190e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ff382cc5-00a2-5f68-9d90-fe4b0150190e'::uuid, 1, NULL, TRUE, 0, NULL, E'Roman Engineering', E'Roman engineering {{1}} its zenith with their aqueducts, roads, and monumental structures. The empire''s fall in the 5th century AD is often {{2}} to the overstretching of its resources. Architectural wonders needed constant upkeep, a task that became harder as Rome faced political instability and economic pressures. Archeological findings suggest a significant decrease in construction projects {{3}} with the period of decline, reflecting the empire''s {{4}} ability to sustain its infrastructure.', NULL, NULL, NULL, E'1.reached, 2.attributed, 3.coincided, 4.waning', NULL, NULL),
  ('ff3a5e0f-848c-54ce-a94f-0d90ea779748'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ff3a5e0f-848c-54ce-a94f-0d90ea779748'::uuid, 1, NULL, TRUE, 0, NULL, E'Earth''s Land', E'Earth''s continental crust may have emerged 500 million years earlier than scientists had previously estimated. Pinning down when our planet’s land emerged could help us understand the conditions in which {{1}} life began. Today, new oceanic crust rises at mid-ocean ridges where tectonic plates drift apart. Continental crust is usually much older, formed from volcanism where plates crash into each other, {{2}} a thicker, less-dense layer above sea level. Weathering of continental crust adds {{3}} to the ocean, a process that may have played a role in supporting primordial life. The big question is: when did continental crusts start forming? To try to answer that, Desiree Roerdink at the University of Bergen in Norway and her colleagues analyzed 30 ancient rock samples from six sites in Australia, South Africa and India. These contained barite, which can form in hydrothermal vents – fissures in the ocean floor {{4}} warm, mineral-rich waters react with seawater.', NULL, NULL, NULL, E'1.primitive, 2.thrusting, 3.nutrients, 4.where', NULL, NULL),
  ('ff4351b9-9b06-5928-97da-9c9cb4483605'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ff4351b9-9b06-5928-97da-9c9cb4483605'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the natural color of the skin on a person’s face?', '937adcf9-a3b6-5423-97c2-d1e71df5ac4a'::uuid, NULL, NULL, E'Complexion', NULL, NULL),
  ('ff4a9b00-1b2c-5f46-9ad4-2396e4f83565'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ff4a9b00-1b2c-5f46-9ad4-2396e4f83565'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the science that are concerned about the study of earth materials and nutrients, geology or geography?', '6005e972-5c96-5725-916d-003eea864dc2'::uuid, NULL, NULL, E'Geology', NULL, NULL),
  ('ff4faceb-46c0-5382-88e4-67a90b343283'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ff4faceb-46c0-5382-88e4-67a90b343283'::uuid, 1, NULL, TRUE, 0, NULL, E'Landmark', E'In a landmark report published on Monday, the international financial institution called on states to reduce global emissions and bridge the development gap to avoid the effects of slow-onset climate change such as water scarcity, decreasing crop productivity, and rising sea levels.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ff531609-d909-59d9-b286-b4890798300b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ff531609-d909-59d9-b286-b4890798300b'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do you call the very long essay that students have to write for a doctoral degree?', '4ec3b587-4011-54a8-b283-5fc4af388792'::uuid, NULL, NULL, E'Thesis / dissertation / discourse / paper', NULL, NULL),
  ('ff57b441-cf9f-54a5-b820-038091dd6b6a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ff57b441-cf9f-54a5-b820-038091dd6b6a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '0e75c763-721a-512a-bc1e-24aa57aa9053'::uuid, NULL, E'Ads often use funny stories, exciting scenes, or catchy words to get noticed.', NULL, NULL, NULL),
  ('ff5cb410-0d6b-5577-8dbe-759339898331'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ff5cb410-0d6b-5577-8dbe-759339898331'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What electronic device wakes you up in the morning?', '6515c581-7ef8-5810-bf85-53af31ee85ff'::uuid, NULL, NULL, E'alarm clock', NULL, NULL),
  ('ff607989-00e2-5ab0-911a-b2412c434267'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_LISTENING_SINGLE', E'MC_LISTENING_SINGLE', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ff607989-00e2-5ab0-911a-b2412c434267'::uuid, 1, NULL, TRUE, 0, NULL, E'Baby skills', E'Y: Today, on a Moment of Science, it''s time for another round of Baby Skills, that fun and wacky guessing game that shows your baby is up to more than crying and napping. And today''s question is: What can six-month-olds do better than nine- month-olds? Don, care to take a stab at it?\nD: Well! I don''t really know, Yael. I thought nine-month-olds would be better at just about everything.\nY: Sorry, Don. It turns out that six-month-olds are better than nine-month-olds at recognizing certain faces. In a recent study, scientists observed that six-month-olds are equally good at distinguishing between non-human faces, as they are at distinguishing between human faces.\n\nAccording to the woman, what can we know about six-month-old babies?', '3a882994-7e5f-5377-8670-bf248b3d8d9f'::uuid, NULL, NULL, E'They can both distinguish non-human faces and human faces.', NULL, NULL),
  ('ff677998-7dcb-5e6d-abdd-eb6638ba04bc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ff677998-7dcb-5e6d-abdd-eb6638ba04bc'::uuid, 1, NULL, TRUE, 0, NULL, E'Great Engineers', E'Great engineers have a passion to improve life; a burning conviction that they can make life better for everyone. Engineers need to have a talent for invention and innovation, but what {{1}} them is the conviction that they can find a better way to do things; a cheaper and more efficient solution to the problems of human existence on this planet of {{2}} resources that we call Earth.\nMany of us {{3}} a lot of time complaining about the difficulties and problems of life. It is easy to find fault with things that make daily life arduous. For an engineer, these difficulties can be opportunities. How can this be made to work better? How can that process be made more efficient? How can {{4}} be made more cheaply, more accurately and more fit-for-purpose? Great engineers are convinced that everything can be {{5}} . Instead of complaining, they think of ways to make things better.', NULL, NULL, NULL, E'1.drives, 2.limited, 3.spend, 4.components, 5.improved', NULL, NULL),
  ('ff67bb56-f0b1-5bab-adbb-d09d941ca48a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ff67bb56-f0b1-5bab-adbb-d09d941ca48a'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'c159c0c4-da67-5505-90bc-f0f335bac626'::uuid, NULL, E'As the project progresses, a written document will become very useful.', NULL, NULL, NULL),
  ('ff69e9da-5917-5d02-a6cb-2d8b2fdbf4ef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ff69e9da-5917-5d02-a6cb-2d8b2fdbf4ef'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '76a31018-940e-580f-ba62-36f7b295d6b3'::uuid, NULL, E'Online courses have made distance learning more accessible than ever.', NULL, NULL, NULL),
  ('ff742b47-d798-55cb-aed2-e62a6de76619'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ff742b47-d798-55cb-aed2-e62a6de76619'::uuid, 1, NULL, TRUE, 0, NULL, E'Bentham', E'By the 1820s Bentham had become a well-known {{1}} , both in Britain and in other parts of the world. His ideas were to influence the reforms of public administration made during the nineteenth century, and his writings are still at the centre of academic debate, especially regarding social policy, legal positivism, and welfare economics.\nBentham died on 6 June 1832, a day before the first Reform Act was given Royal Assent. As per the directions in his will, Bentham''s body was dissected by his friend, the surgeon Thomas Southwood Smith, and his skeleton was {{2}} as the Auto-Icon. Research into Bentham''s thought and life continues today at UCL''s Bentham Project, set up in the early 1960s with the aim {{3}} producing the first scholarly edition of his works and correspondence. This edition is projected to run to some eighty volumes.\nMembers of the public are invited to assist in this massive editorial task by helping to {{4}} Bentham''s manuscripts via Transcribe Bentham.', NULL, NULL, NULL, E'1.figure, 2.preserved, 3.of, 4.transcribe', NULL, NULL),
  ('ff783dbf-6372-536d-b897-d0c5aaaef59a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ff783dbf-6372-536d-b897-d0c5aaaef59a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What is the name of the electronic device that displays television programs, movies, and games?', 'afaff5ff-63fa-53b1-885b-4cb57efab81e'::uuid, NULL, NULL, E'Television / TV', NULL, NULL),
  ('ff7921df-933a-5eb7-a581-945f5c056c25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ff7921df-933a-5eb7-a581-945f5c056c25'::uuid, 1, NULL, TRUE, 0, NULL, E'Mutation', E'Think of your community''s traffic. When the traffic lights are functioning, drivers (usually) behave. Break a light, and everything comes to a standstill. Within our bodies, we could liken that broken traffic light to a DNA mutation — one that has the potential to mess up our body''s everyday operations. So where lightning might knock out a traffic light, what causes mutations in DNA?', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ff7d22bc-aa6b-5eae-ae4e-56dd74a1518a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ff7d22bc-aa6b-5eae-ae4e-56dd74a1518a'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'How do you call the doctor who treats sick animals?', '54d0ad5c-19ec-5f90-906d-f163199a35ae'::uuid, NULL, NULL, E'Vet / Veterinarian', NULL, NULL),
  ('ff7e988b-e681-510d-b1b1-a43550eadc98'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ff7e988b-e681-510d-b1b1-a43550eadc98'::uuid, 1, NULL, TRUE, 0, NULL, E'Onion', E'Varieties of onion differ in size, strength and colour. The yellow onion is the most commonly known variety, which has pale golden skin, greenish-white flesh and a strong taste. Red onions are an attractive, milder alternative to the yellow onion with their shiny purple skin. Spring onions are immature onions pulled before the bulb is fully formed, and can be recognised by their long green leaves.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ff82a10c-812f-5625-946d-f890ee892100'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'MC_READING_SINGLE', E'MC_READING_SINGLE', E'READING', E'SHARED', NULL, E'APPROVED', 'ff82a10c-812f-5625-946d-f890ee892100'::uuid, 1, NULL, TRUE, 0, NULL, E'DIT', E'Slow eating and thorough chewing help prevent obesity and weight gain — a view popularized a century back and now tested as truth. Typically, the chewing process reportedly enhances the energy expenditure associated with the metabolism of food and increases intestinal motility — all summing up to an increased heat generation in the body after food intake, known as diet-induced thermogenesis (DIT). DIT, also known as the thermic effect of food consumption, increases energy expenditure above the basal fasting level -- a factor known to prevent weight gain. So when the DIT increases in the process of slow eating and thorough chewing, it is beneficial to weight loss.\n\nWhich of the following statements is true?', NULL, NULL, NULL, E'DIT has negative correlation with weight gain.', NULL, NULL),
  ('ff833190-4fae-5d2d-9c0a-2eeea47ece1d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ff833190-4fae-5d2d-9c0a-2eeea47ece1d'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '7f3cecf3-be29-55d7-b296-3e4c628b9abc'::uuid, NULL, NULL, E'The slide shows that there has been a minimal growth.', NULL, NULL),
  ('ff86d89b-cd42-5901-8e40-611913db1eb9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'RE_TELL_LECTURE', E'RE_TELL_LECTURE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ff86d89b-cd42-5901-8e40-611913db1eb9'::uuid, 1, NULL, TRUE, 0, NULL, E'Flying Time', NULL, 'be264401-2bf6-52bc-aa97-0d41cbccfedc'::uuid, NULL, E'Essentially when the brain sees something that’s novel, it has to burn more energy to represent it because it wasn’t expecting that. This feeling that things are going in slow motion is a trick of memory. In other words, when you’re in an emergency situation a part of the brain called the amygdala comes online, this is your emergency control centre, it lays down memories on what amounts to a secondary memory track, these are very dense memories. And you’re noticing everything around you and writing it all down. So when the brain reads that back out, there’s such a density of memory there that the brain’s only conclusion is that must have taken a long time. And I think this offers an explanation for why people think that time seems to speed up as they grow older. And it’s because when you’re a child, everything’s new to you. You’re figuring out the rules of the world, you’re writing down a lot of memory, and so when you look back at the end of a year, you have a lot of memory of what you’ve learnt. But when you’re much older and you look back at the end of the year, you’re probably doing approximately the same stuff you’ve been doing for the X number of previous years. And so it seems like the year just went by in a flash.', NULL, NULL, NULL),
  ('ff888c77-60c1-5b06-beb8-7b2c6e576ccb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ff888c77-60c1-5b06-beb8-7b2c6e576ccb'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '94787e88-c962-5358-886a-df30a077bcb8'::uuid, NULL, NULL, E'Convincing evidence to support this theory is hard to obtain.', NULL, NULL),
  ('ff91acea-f442-5c2a-ab91-2dd5a1922931'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ff91acea-f442-5c2a-ab91-2dd5a1922931'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '83ffd6db-8a18-5a85-b69b-ee3de8978c8e'::uuid, NULL, NULL, E'Art represents the expression of creativity and ideas in tangible forms.', NULL, NULL),
  ('ff92f92a-cc48-5c86-a776-7e4d73e882b4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ff92f92a-cc48-5c86-a776-7e4d73e882b4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '20e7a65f-8c8f-524d-85b6-9721246c0fa8'::uuid, NULL, NULL, E'Today, we use complex ways to learn how the brain works.', NULL, NULL),
  ('ff957c11-8594-5c94-9c0d-56d901a479e6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ff957c11-8594-5c94-9c0d-56d901a479e6'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '5e3c4880-071e-5a36-bbc8-467e0619466c'::uuid, NULL, E'You will need two academic references to support your application.', NULL, NULL, NULL),
  ('ff99c6b1-f7d0-5092-8519-f0b17a6a40aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', 'ff99c6b1-f7d0-5092-8519-f0b17a6a40aa'::uuid, 1, NULL, TRUE, 0, NULL, E'Clear Plan', E'To invest, you need to {{1}} a clear plan, do your own research, {{2}} a margin of safety by always thinking about the {{3}} and, ultimately, be patient. By all means include some speculative picks if you {{4}} , but ensure they are only a small part of your portfolio. Looking for an oil explorer whose shares double, treble and double again is exciting but such firms are very {{5}} . There are a lot more which have a consistent record of paying out the dividends which really make the markets work for you, once they are reinvested.', NULL, NULL, NULL, E'1.draw up, 2.build in, 3.valuation, 4.wish, 5.rare', NULL, NULL),
  ('ff9fea57-3a18-510a-a001-6163ec20bbf8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ff9fea57-3a18-510a-a001-6163ec20bbf8'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '5bbda0cf-0c3a-547d-a9e8-53c2c72bfbd2'::uuid, NULL, NULL, E'The shipwreck of this year ruined some artifacts which were interested by historians.', NULL, NULL),
  ('ffa0eb3b-8633-58f3-bf37-d1c96ff8ced8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ffa0eb3b-8633-58f3-bf37-d1c96ff8ced8'::uuid, 1, NULL, TRUE, 0, NULL, E'Margaret Simons', E'Margaret Simons explains the changes taking place in the Australian media. She analyses audiences, our major media organisations, the role of government and the implications of all of these for our society and our democracy. Her examination leads her to the conclusion that the challenges facing the content providers in the modern world are part of a broader striving.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ffa8eb07-fb5f-5c44-a6eb-1fe1b6684b4e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ffa8eb07-fb5f-5c44-a6eb-1fe1b6684b4e'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6b4cd438-741e-5aa2-b58d-6c1a1ff22fb2'::uuid, NULL, E'The context is basically the background of framework surrounding the act of communication.', NULL, NULL, NULL),
  ('ffaca467-da81-5cb4-92a1-b76e1d430f09'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'ffaca467-da81-5cb4-92a1-b76e1d430f09'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '98ecc9f4-4771-534c-a427-69a35534896b'::uuid, NULL, NULL, E'It is very common for college students to live on campus.', NULL, NULL),
  ('ffae6745-9a2d-5e93-b5f9-eb4800fbea36'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ffae6745-9a2d-5e93-b5f9-eb4800fbea36'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'In sport, what do we call the cloths that we wear and end above the knee?', 'd6e9ba16-2c2d-5d47-9346-f627c5e0991c'::uuid, NULL, NULL, E'Shorts', NULL, NULL),
  ('ffb27ad4-a708-5be3-86ef-6a6d10eb246a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ffb27ad4-a708-5be3-86ef-6a6d10eb246a'::uuid, 1, NULL, TRUE, 0, NULL, E'Furniture', E'There are perhaps three ways of looking at furniture: some people see it as purely functional and useful, and don''t bother themselves with aesthetics; others see it as essential to civilized living and concern themselves with design and how the furniture will look in a room - in other words, function combined with aesthetics; and yet others see furniture as a form of art.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ffbacf4b-af3c-515d-b818-dd0a7c130d37'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ffbacf4b-af3c-515d-b818-dd0a7c130d37'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call a group of 12 people or things?', 'ce6e5a8b-a5d1-5998-b516-88f79af49a08'::uuid, NULL, NULL, E'A dozen', NULL, NULL),
  ('ffbd40f6-a5ca-57c1-9c44-ffb936ffd987'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'SUMMARIZE_WRITTEN_TEXT', E'SUMMARIZE_WRITTEN_TEXT', E'WRITING', E'SHARED', NULL, E'APPROVED', 'ffbd40f6-a5ca-57c1-9c44-ffb936ffd987'::uuid, 1, NULL, TRUE, 0, NULL, E'MFA', E'A new cyber security report suggests that India has the highest growth rate when it comes to Multi-Factor authentication (MFA) adoption and usage. According to the Thales Access Management Index 2022 conducted by the research firm 451 research, India recorded a 19 percent point rise, bringing MFA usage to 66 per cent compared to the global average of 56 per cent.\nIt is followed by Singapore with a 17 per cent point increase and the UAE with a ten per cent point increase. In case you are unaware, Multi-Factor Authentication often referred to as MFA is a layered security system that requires users to use a combination of two or more credentials to log in using methods such as a PIN, password or OTP.\nAs it turns out, MFA is also getting popular among internal and non-IT staff with the adoption rate increasing to 40 per cent compared to 34 per cent last year.\nThe report goes on to say that while companies are still concerned about the security risks involved with remote work when it comes to secure access to data, applications and systems, more than 84 percent of professionals working in the IT sector said they had some confidence in their company’s security system, compared to just 56 per cent last year.\nIf we compare the global MFA usage, remote workers account for more than 68 per cent followed by 52 percent privileged users.', NULL, NULL, NULL, NULL, 5, 75),
  ('ffc9a8db-111e-5947-ab04-b365f0edc285'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ffc9a8db-111e-5947-ab04-b365f0edc285'::uuid, 1, NULL, TRUE, 0, NULL, E'Evolutionary Changes', E'A groundbreaking study on recent evolutionary changes in natural populations has been conducted by a team of international researchers. The study utilized a vast genomic dataset, one of the largest ever assembled for animals in their natural habitat, which included almost 4,000 Darwin''s finches.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('ffcb3f85-672a-5713-bbb4-e2ff491c3d26'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ffcb3f85-672a-5713-bbb4-e2ff491c3d26'::uuid, 1, NULL, TRUE, 0, NULL, E'Bentham', E'By the 1820s Bentham had become a well-known figure, both in Britain and in other parts of the world. His ideas were to influence the reforms of public administration {{1}} during the nineteenth century, and his writings are still at the centre of academic debate, especially {{2}} social policy, legal positivism, and welfare economics.\nBentham died on 6 June 1832, a day before the first Reform Act was given Royal Assent. As per the {{3}} in his will, Bentham''s body was dissected by his friend, the surgeon Thomas Southwood Smith, and his skeleton preserved as the Auto-Icon. Research into Bentham''s thought and life continues today at UCL''s Bentham Project, set up in the early 1960s with the aim {{4}} producing the first scholarly edition of his works and correspondence. This edition is projected to run to {{5}} eighty volumes.\nMembers of the public are invited to assist in this massive editorial task by helping to transcribe Bentham''s manuscripts via Transcribe Bentham.', NULL, NULL, NULL, E'1.made, 2.as regards, 3.directions, 4.of, 5.some', NULL, NULL),
  ('ffce6270-b8c1-5396-af08-2445e5218835'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ffce6270-b8c1-5396-af08-2445e5218835'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'What do we call the head of a court?', '18ed4622-c226-5516-80f6-40c3f35bf50d'::uuid, NULL, NULL, E'Judge', NULL, NULL),
  ('ffd815ce-79e1-53a2-a460-a913ee1918d9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ANSWER_SHORT_QUESTION', E'ANSWER_SHORT_QUESTION', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ffd815ce-79e1-53a2-a460-a913ee1918d9'::uuid, 1, NULL, TRUE, 0, NULL, E'ASQ', E'Which is better, high employment or low employment?', '38e9e039-0f92-5db5-99c0-a5748a745ea2'::uuid, NULL, NULL, E'High employment', NULL, NULL),
  ('ffe2ba35-b706-5151-b62a-1698ccc1f43c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'ffe2ba35-b706-5151-b62a-1698ccc1f43c'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, '6abfa4f7-db40-5cd2-ab12-5a0a680d8670'::uuid, NULL, E'Students have the option to live in college residences or apartments.', NULL, NULL, NULL),
  ('ffe7bb73-51c0-5adf-b263-89bcc0eb761f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', 'ffe7bb73-51c0-5adf-b263-89bcc0eb761f'::uuid, 1, NULL, TRUE, 0, NULL, E'Satellites', E'Satellites have been {{1}} Earth since the late 1950s when Sputnik 1 was launched. It soon became obvious that having telecommunication stations in low-Earth orbit would make long-distance communications much easier and so countries began launching their own satellites in the 1960s. Eventually, companies got involved, including the Iridium Communications corporation. Its founders came up with the idea of a {{2}} of stations in orbit in the 1990s. After the company struggled to find customers and eventually went bankrupt, the constellation is still in operation today and its current owners are planning a new "generation" of satellites to {{3}} the aging fleet. Some of the new satellites, called "Iridium NEXT", have already been launched aboard SpaceX rockets and more will be sent to space to orbits that will likely not produce as many flares as the older generation has.', NULL, NULL, NULL, E'1.orbiting, 2.constellation, 3.replace', NULL, NULL),
  ('fff116b3-3fc6-5d60-a0d4-d0fdfac17e53'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'fff116b3-3fc6-5d60-a0d4-d0fdfac17e53'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'a5f18735-228a-5e08-8c14-dd4090270dab'::uuid, NULL, NULL, E'A transport plane is carrying food and medical supplies for people.', NULL, NULL),
  ('fff6ca5e-191a-5016-9eeb-6535a40469a9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', 'fff6ca5e-191a-5016-9eeb-6535a40469a9'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '676a81e5-ed59-5482-9b76-c0b80afb2bc7'::uuid, NULL, NULL, E'If you''re short on money, you might get help for school.', NULL, NULL),
  ('fffc8f2b-414f-5db7-b984-9a97000ff7f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'REPEAT_SENTENCE', E'REPEAT_SENTENCE', E'SPEAKING', E'SHARED', NULL, E'APPROVED', 'fffc8f2b-414f-5db7-b984-9a97000ff7f9'::uuid, 1, NULL, TRUE, 0, NULL, E'RS', NULL, 'b64e6732-b58b-5519-b64c-0bf823676750'::uuid, NULL, E'The facts you have garnered with such infinite trouble invariably fail you at a pinch.', NULL, NULL, NULL);
