  ('395bcffc-e9be-5d66-ac1e-89801b5075b4'::uuid, '01644ff0-e3f7-5224-956f-104db11909a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But have you ever wondered just why the Mona Lisa is so famous?', FALSE, 1, NULL, NULL),
  ('8f8ef122-c068-580f-bc96-eb8d75bb66d5'::uuid, '01644ff0-e3f7-5224-956f-104db11909a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Mona Lisa is perhaps the most recognizable piece of art in the world', FALSE, 2, NULL, NULL),
  ('adf17c20-1455-5901-a663-0c8465a64a4d'::uuid, '01644ff0-e3f7-5224-956f-104db11909a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Together they create a fascinating story that has survived through the ages.', FALSE, 3, NULL, NULL),
  ('440f0793-9c31-522a-8969-f4e1ff7d9d20'::uuid, '01685f9e-c116-5068-8ebf-7a958d4ec383'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But it is difficult to describe music in words, and even more difficult to specify a tune.', FALSE, 0, NULL, NULL),
