  ('448cb26b-a21e-5a06-9ef0-14c84639d4b7'::uuid, '0877d06c-2462-5e28-ba93-44d5b78bac85'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It posits that the laws of physics are the same for all non-accelerating observers.', FALSE, 0, NULL, NULL),
  ('52ffdf3b-f51a-5285-8b2e-980dd68dce90'::uuid, '0877d06c-2462-5e28-ba93-44d5b78bac85'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Furthermore, it asserts that the speed of light within a vacuum is the same, no matter the speed at which an observer travels.', FALSE, 1, NULL, NULL),
  ('19499ba5-e1bc-51ac-acc9-4b0fdf20c1a1'::uuid, '0877d06c-2462-5e28-ba93-44d5b78bac85'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As a result, this theory has led to new ways of thinking about the universe, fundamentally altering our understanding of physics.', FALSE, 2, NULL, NULL),
  ('a8d3ab90-4f15-5d05-bc8c-1a6fc87c0ac3'::uuid, '0877d06c-2462-5e28-ba93-44d5b78bac85'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The theory of relativity, proposed by Albert Einstein, has revolutionized the way we understand time and space.', FALSE, 3, NULL, NULL),
  ('68462760-b0c2-5f71-b5c7-32fd9df3cabe'::uuid, '08851ac7-61f6-59a4-956e-aff475f00507'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This should draw the public attention, and people should put more concerns on teenagers.', FALSE, 0, NULL, NULL),
  ('a4a7af36-4b52-57cf-98c4-bf578f88f0d8'::uuid, '08851ac7-61f6-59a4-956e-aff475f00507'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Especially, this happens very often among teenage drivers.', FALSE, 1, NULL, NULL),
  ('1508c1a0-148f-5d7c-8945-5c50c6b85cd7'::uuid, '08851ac7-61f6-59a4-956e-aff475f00507'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As a new method, it is advised to have more qualifications for teenagers to get licenses.', FALSE, 2, NULL, NULL),
  ('9c8e0df3-669e-578f-a3e7-0ec7f7792cc1'::uuid, '08851ac7-61f6-59a4-956e-aff475f00507'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'According to the research, more car accidents occur in the morning.', FALSE, 3, NULL, NULL),
