  ('cd39203b-2dcc-553b-91dc-cb95b13892aa'::uuid, '08db5412-532f-56ca-9283-e42271394c62'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'riddle', FALSE, 14, 3, NULL),
  ('d2fa77f8-0ccf-51aa-b8eb-37a67e0dbf61'::uuid, '08db5412-532f-56ca-9283-e42271394c62'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'piddle', FALSE, 15, 3, NULL),
  ('5774e405-e1c8-5f71-bdec-3a9333d41af1'::uuid, '08e3cfab-ae69-5317-bc40-5c67a65e2b5a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In the 1960s and 1970s, corporations were in a state of denial regarding their impact on the environment.', FALSE, 0, NULL, NULL),
  ('53d12dd0-28f3-575a-b023-ac32561472f5'::uuid, '08e3cfab-ae69-5317-bc40-5c67a65e2b5a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Today many companies have accepted their responsibility to do no harm to the environment.', FALSE, 1, NULL, NULL),
  ('08f4a12d-4c06-5860-baa6-e525348db054'::uuid, '08e3cfab-ae69-5317-bc40-5c67a65e2b5a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The environmental revolution has been almost three decades in the making, and it has changed forever how companies do business.', FALSE, 2, NULL, NULL),
  ('62175b30-5c13-58a3-af2d-50ca76c2140f'::uuid, '08e3cfab-ae69-5317-bc40-5c67a65e2b5a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Then a series of highly visible ecological problems created a groundswell of support for strict government regulation.', FALSE, 3, NULL, NULL),
  ('85f51e0f-e229-583a-af97-f420a82497f2'::uuid, '08e3cfab-ae69-5317-bc40-5c67a65e2b5a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In the United States, Lake Erie was dead. In Europe, the Rhine was on fire. In Japan, people were dying of mercury poisoning.', FALSE, 4, NULL, NULL),
  ('8827197b-5d48-5d31-a455-d315a3fcfcc4'::uuid, '08f797ff-ebb1-50aa-ae98-518f232da6bb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They leverage public-space assets to create value for the surrounding area, supporting livelihoods and promoting local businesses.', FALSE, 0, NULL, NULL),
  ('684d2bab-3592-522c-a4aa-8458245ebeaa'::uuid, '08f797ff-ebb1-50aa-ae98-518f232da6bb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The resulting degradation of public spaces into congested, vehicle-dominated, and polluted places often becomes a liability, exacerbating various city problems.', FALSE, 1, NULL, NULL),
  ('155c0192-ec3d-5437-8b00-785fa658ed17'::uuid, '08f797ff-ebb1-50aa-ae98-518f232da6bb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Globally, about one-third of a city’s land area is covered by public spaces.', FALSE, 2, NULL, NULL),
  ('5fc31b07-8c3f-590d-a432-c418aba96870'::uuid, '08f797ff-ebb1-50aa-ae98-518f232da6bb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Despite this significance, the potential of public-space assets to transform cities and improve urban life is often overlooked.', FALSE, 3, NULL, NULL),
  ('fdfe65e9-0073-59ac-9256-a8942d9b5ccf'::uuid, '08f797ff-ebb1-50aa-ae98-518f232da6bb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In contrast, the cities that invest in the creation of connected, inclusive public spaces and places buck this trend and fare much better.', FALSE, 4, NULL, NULL),
  ('54abfc39-1bb0-51c7-83e7-50ec2e8d3021'::uuid, '091ac85d-3dae-5a2e-9b49-4fc251459af2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'medal', FALSE, 0, 0, NULL),
