  ('881bd8dc-0e4c-5b38-97f8-7ceea7788156'::uuid, '09f47f2c-5680-50ba-98c4-ec387f33b1ed'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'wander', FALSE, 15, 3, NULL),
  ('08235799-bcb7-535a-b274-5435d2997aab'::uuid, '09fdfeeb-021f-54a1-862a-7ce27420c3d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'So companies investing well grow, enriching themselves and shareholders alike, and ensure competitiveness; companies investing poorly shrink, resulting, perhaps, in the placement of management.', FALSE, 0, NULL, NULL),
  ('f822a89b-187e-5a78-968a-46fd7ed3ceaf'::uuid, '09fdfeeb-021f-54a1-862a-7ce27420c3d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They assume that they’re using their shareholders'' resources efficiently if the company’s performance - especially ROE and earning per share - is good and if the shareholders don’t rebel.', FALSE, 1, NULL, NULL),
  ('736f8947-d377-5057-a3d8-f101e365e8d2'::uuid, '09fdfeeb-021f-54a1-862a-7ce27420c3d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They assume that the stock market automatically penalizes any corporation that  invests its resources poorly.', FALSE, 2, NULL, NULL),
  ('e06d0236-0a8a-5aad-bfbf-2defab389a9c'::uuid, '09fdfeeb-021f-54a1-862a-7ce27420c3d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In short, stock market performance and the company’s financial performance are inexorably linked.', FALSE, 3, NULL, NULL),
  ('31909a44-bcc9-5e0a-a0c8-0266d0301524'::uuid, '09fdfeeb-021f-54a1-862a-7ce27420c3d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The top executives of the large, mature, publicly held companies hold the conventional view when they stop to think of the equity owners'' welfare.', FALSE, 4, NULL, NULL),
  ('473c5cc0-cde3-54e2-ac25-967a166d8923'::uuid, '0a0ba169-0670-5f5d-8a3c-f7e6fb2a4255'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The extension to non-Internet channels differentiates digital marketing from online advertising.', FALSE, 0, NULL, NULL),
  ('cc49a1ed-a904-58d6-a743-e9318a378304'::uuid, '0a0ba169-0670-5f5d-8a3c-f7e6fb2a4255'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Digital marketing extends to non-Internet channels that provide digital media, such as television and mobile phones.', FALSE, 1, NULL, NULL),
  ('f3a5d6f1-d246-5c66-a109-366d87c81d0a'::uuid, '0a0ba169-0670-5f5d-8a3c-f7e6fb2a4255'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Digital marketing is the component of marketing that uses the internet and online-based digital technologies to promote products and services.', FALSE, 2, NULL, NULL),
  ('9b7afb7a-5222-5253-8c27-df6b248649b4'::uuid, '0a0ba169-0670-5f5d-8a3c-f7e6fb2a4255'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Its development during the 1990s and 2000s changed the way brands and businesses use technology for marketing.', FALSE, 3, NULL, NULL),
