  ('3cf6ed96-12cc-50d6-b8bf-75ea12990a24'::uuid, '0ebbe7c7-5e39-5c8a-a969-c5cbc5cf9cbe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'He just bought more books than he is able to read.', FALSE, 1, NULL, NULL),
  ('802556f1-6982-570f-9cb7-438facf23068'::uuid, '0ebbe7c7-5e39-5c8a-a969-c5cbc5cf9cbe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The books that he needs are a strain on his finances.', TRUE, 2, NULL, NULL),
  ('2691e4b4-2a3c-59da-a54c-d7730101e1ad'::uuid, '0ebbe7c7-5e39-5c8a-a969-c5cbc5cf9cbe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The third edition of the chemistry book is not available.', FALSE, 3, NULL, NULL),
  ('045427c0-0283-5461-9116-4f5811ac6af6'::uuid, '0ed3fc06-9ccb-5969-b10d-f1c213979e1f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Participants were assigned to either a high-fiber diet or a standard diet.', FALSE, 0, NULL, NULL),
  ('0ec56572-9c12-518d-af88-d1e07e07a28e'::uuid, '0ed3fc06-9ccb-5969-b10d-f1c213979e1f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These results suggested that a high-fiber diet is more effective in managing diabetes than a standard diet.', FALSE, 1, NULL, NULL),
  ('1da624d9-9418-551f-89b4-86d5f057ee1b'::uuid, '0ed3fc06-9ccb-5969-b10d-f1c213979e1f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The high-fiber diet group showed a more significant reduction in blood sugar levels than the standard diet group.', FALSE, 2, NULL, NULL),
  ('8e39b229-08eb-5237-a254-ea8793feefa9'::uuid, '0ed3fc06-9ccb-5969-b10d-f1c213979e1f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Moreover, they also exhibited improved cholesterol levels.', FALSE, 3, NULL, NULL),
  ('f4aa9d52-af49-5651-ac0c-dbf8c46950a0'::uuid, '0ed3fc06-9ccb-5969-b10d-f1c213979e1f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In an effort to understand the role of diet in managing diabetes, researchers conducted a controlled experiment.', FALSE, 4, NULL, NULL),
  ('8a580a36-18e2-5e3c-9d8b-80ad85735253'::uuid, '0f153fd8-5b3e-5bc8-990b-8238bd18b938'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Great Barrier Reef, located off the coast of Australia, is the world''s largest coral reef system.', FALSE, 0, NULL, NULL),
  ('a0b2e210-6161-5e97-83f8-f2e380448c57'::uuid, '0f153fd8-5b3e-5bc8-990b-8238bd18b938'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, it faces significant threats from climate change, pollution, and overfishing.', FALSE, 1, NULL, NULL),
  ('013a45b1-bb4c-5708-a1b7-e5a246d83e77'::uuid, '0f153fd8-5b3e-5bc8-990b-8238bd18b938'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Thus, conservation efforts are crucial to preserve this unique and vital ecosystem for future generations.', FALSE, 2, NULL, NULL),
  ('776ae48b-d3af-5fc9-ac4c-e488077dae65'::uuid, '0f153fd8-5b3e-5bc8-990b-8238bd18b938'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The reef is known for its diverse marine life, including various species of fish, corals, and mollusks.', FALSE, 3, NULL, NULL),
  ('5a90735a-2e27-5895-8747-75dc05d1e937'::uuid, '0f3f1b66-ac4c-5e87-a688-cb35fe53fea1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Good interior design can enhance the comfort and usability of a building.', FALSE, 0, NULL, NULL),
  ('b4603ad0-f175-5ff9-90bd-c0da35693bdd'::uuid, '0f3f1b66-ac4c-5e87-a688-cb35fe53fea1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It involves the strategic use of space, color, and materials.', FALSE, 1, NULL, NULL),
  ('b48eae05-1a87-5f8a-adf4-74652a12b42c'::uuid, '0f3f1b66-ac4c-5e87-a688-cb35fe53fea1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, trends in interior design can change rapidly, making some designs appear outdated after a few years.', FALSE, 2, NULL, NULL),
  ('f39171e2-c23f-5411-911a-df904c52f727'::uuid, '0f3f1b66-ac4c-5e87-a688-cb35fe53fea1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Interior design plays a significant role in the functionality and aesthetics of architectural spaces.', FALSE, 3, NULL, NULL),
  ('47477511-3913-5771-a466-1710e95c45f0'::uuid, '0f6a38e7-3036-570a-9bfd-0aa3ed76d3dc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Telemedicine has revolutionized healthcare delivery, especially during the COVID-19 pandemic.', FALSE, 0, NULL, NULL),
  ('786b6548-59d3-5303-af09-b53f09e2659e'::uuid, '0f6a38e7-3036-570a-9bfd-0aa3ed76d3dc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'While telemedicine improves access to healthcare, it also depends heavily on reliable internet connectivity.', FALSE, 1, NULL, NULL),
  ('16ea6840-47ba-5828-9ac5-eb6260395936'::uuid, '0f6a38e7-3036-570a-9bfd-0aa3ed76d3dc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It enables remote consultations, reducing the need for physical hospital visits.', FALSE, 2, NULL, NULL),
  ('c7d48c15-d452-5895-a610-be84420ae4fe'::uuid, '0f6a38e7-3036-570a-9bfd-0aa3ed76d3dc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As a result, expanding high-speed internet access is crucial for the broader adoption of telemedicine.', FALSE, 3, NULL, NULL),
  ('12afd353-66ea-560d-bec7-52dad5229d1d'::uuid, '0f9b0321-fe12-5d64-a909-6a87fe2dff79'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'He proposes that instead of arguing for sacrifice, environmentalists should show where the rewards might lie: that understanding what the science is saying and planning accordingly is the smart thing to do, which will protect your interests more effectively than flinging abuse at scientists.', FALSE, 0, NULL, NULL),
  ('cdd3d921-5827-5560-a86e-d72e2b08a9dc'::uuid, '0f9b0321-fe12-5d64-a909-6a87fe2dff79'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Of the narratives that might penetrate these circles, we are more likely to listen to those that offer us some reward.', FALSE, 1, NULL, NULL),
  ('ccc36338-dc7f-5dcc-97ae-c95ae146c865'::uuid, '0f9b0321-fe12-5d64-a909-6a87fe2dff79'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'We should emphasize the old-fashioned virtues of uniting in the face of a crisis, of resourcefulness and community action.', FALSE, 2, NULL, NULL),
  ('653a8a58-cff4-5b4c-acf8-4bbaaeb2c9d9'::uuid, '0f9b0321-fe12-5d64-a909-6a87fe2dff79'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Our view is formed by the views of people with whom we mix.', FALSE, 3, NULL, NULL),
  ('cf2fde68-2c25-5885-929f-47752e6630ce'::uuid, '0f9b0321-fe12-5d64-a909-6a87fe2dff79'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In his fascinating book Carbon Detox, George Marshall argues that people are not persuaded by information.', FALSE, 4, NULL, NULL),
