  ('b66df0e1-2dd6-5841-b060-91e9bc4f9b4b'::uuid, '0fce8ebc-9fc1-5a12-b1b6-4698af274514'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Grapes are nutrition powerhouses.', FALSE, 0, NULL, NULL),
  ('c22d08d0-329e-5fc5-a093-889bbaa13092'::uuid, '0fce8ebc-9fc1-5a12-b1b6-4698af274514'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Grapes are also rich in antioxidants, which help protect the body’s cells against oxidative stress, a mechanism linked to cancer, heart disease, and Alzheimer’s disease.', FALSE, 1, NULL, NULL),
  ('2a37a9c7-6545-5792-a38e-e76c28e4da10'::uuid, '0fce8ebc-9fc1-5a12-b1b6-4698af274514'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In particular, darker grapes, such as purple varieties, are especially high in antioxidants.', FALSE, 2, NULL, NULL),
  ('fd6b8a23-c6c8-524e-9e7b-79e43d3a605a'::uuid, '0fce8ebc-9fc1-5a12-b1b6-4698af274514'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They are packed with vitamin C, a powerful antioxidant that plays key roles in immune system health, connective tissue development, and wound healing.', FALSE, 3, NULL, NULL),
  ('1f42c457-2651-539c-a907-8c176cd38aeb'::uuid, '0fcf3aac-b8c2-5c89-ac50-4fc0b2e92aa9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But as he recalls, the bomb landed in the leaves of the banana tree, which he believes prevented it from igniting — shielding him from death.', FALSE, 0, NULL, NULL),
  ('90ce3388-327d-5219-af8b-cf5be0eb049b'::uuid, '0fcf3aac-b8c2-5c89-ac50-4fc0b2e92aa9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'He’d been shot and a bomb fell directly overhead.', FALSE, 1, NULL, NULL),
  ('c8ee08a2-b1e6-5e89-9150-271b4cf402e1'::uuid, '0fcf3aac-b8c2-5c89-ac50-4fc0b2e92aa9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As a 14-year-old resistance fighter during the civil war in 1970s El Salvador, he hid beneath the tree’s lush, green fronds when the military attacked his encampment.', FALSE, 2, NULL, NULL),
  ('d9ce6b35-e1d0-5b97-a578-bdf9f188b4da'::uuid, '0fcf3aac-b8c2-5c89-ac50-4fc0b2e92aa9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Victor Manuel Hernandez believes he wouldn’t be alive today if it weren’t for a banana tree.', FALSE, 3, NULL, NULL),
