  ('88deb162-15d5-5bc7-9937-6f39272d4b9d'::uuid, '1039357a-507f-519e-8aa1-bb1f720eafdb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It was in Montgomery that Rosa Parks, an African American woman, refused to vacate her seat in the middle of the bus so that a white man could sit in her place.', FALSE, 0, NULL, NULL),
  ('10e95866-54cb-511c-8084-53d75fea08f3'::uuid, '1039357a-507f-519e-8aa1-bb1f720eafdb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'She was arrested for her civil disobedience.', FALSE, 1, NULL, NULL),
