  ('c44c07e6-b809-5f82-a26e-6a9a6733644a'::uuid, '107efc31-47d9-5fcc-8217-c73746ae32e8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There are many reasons to do an internship nowadays, but you may be wondering what the best way to find one is.', FALSE, 1, NULL, NULL),
  ('7e863207-d533-553a-8d6d-4243558d34ef'::uuid, '107efc31-47d9-5fcc-8217-c73746ae32e8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'An internship is a time-limited introductory position within a company that provides young people the opportunity to gain an insight into the job market and the career path they are interested in.', FALSE, 2, NULL, NULL),
  ('545691c4-9d73-59af-9904-ccf0cbd0d188'::uuid, '107efc31-47d9-5fcc-8217-c73746ae32e8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'While this is certainly laughable and a red flag for the company itself, getting some work experience is never a bad idea.', FALSE, 3, NULL, NULL),
