  ('c411c07e-b3d3-55bc-8a57-745270e597be'::uuid, '1081cc40-2277-5064-810e-5133835cdd20'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The fire, lasting four days, most likely started with broken gas lines (and, in some cases, was helped along by people hoping to collect insurance for their property—they were covered  for fire, but not earthquake, damage).', FALSE, 1, NULL, NULL),
  ('824f167b-bbc9-587f-88fe-d71851300a1d'::uuid, '1081cc40-2277-5064-810e-5133835cdd20'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'At 5:12 a.m. on April 18, 1906, the people of San Francisco were awakened by an earthquake that would devastate the city.', FALSE, 2, NULL, NULL),
  ('52045a7d-ff5e-5b7b-aa85-96850373f076'::uuid, '1081cc40-2277-5064-810e-5133835cdd20'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The main temblor, having a 7.7-7.9 magnitude, lasted about one minute and was the result of the rupturing of the northernmost 296 miles of the 800-mile San Andreas fault.', FALSE, 3, NULL, NULL),
