  ('a8125a8c-d21e-5692-b01c-6ef12b14196d'::uuid, '131f23c9-816a-5bc2-90e8-afd1d3721a25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In 2001 the government, egged on by WWF, a green group, tried to regulate logging in the relatively small part of the Peruvian Amazon where this is allowed.', FALSE, 0, NULL, NULL),
  ('1a486bf1-35c4-5ed5-aee9-461ed857773d'::uuid, '131f23c9-816a-5bc2-90e8-afd1d3721a25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'That pocket denotes a tiny patch of legally loggable land sandwiched between four natural reserves, all rich in mahogany and accessible from the town.', FALSE, 1, NULL, NULL),
  ('5936cbf3-410e-52c9-8be1-55690071a2cf'::uuid, '131f23c9-816a-5bc2-90e8-afd1d3721a25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Instead, it auctioned 40-year concessions to areas ruled off on a map, with the right to log 4% of the area each year. The aim was to encourage strict management plans and sustainable extraction.', FALSE, 2, NULL, NULL),
  ('d8d2c638-18de-5c12-90b3-ddcafdf8d17f'::uuid, '131f23c9-816a-5bc2-90e8-afd1d3721a25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Sephua, a ramshackle town on the edge of Peru''s Amazon jungle, nestles in a pocket on the map where a river of the same name flows into the Urubamba.', FALSE, 3, NULL, NULL),
  ('a93c1d83-7795-503b-a575-ce5750b2bcfa'::uuid, '131f23c9-816a-5bc2-90e8-afd1d3721a25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It abolished the previous system of annual contracts.', FALSE, 4, NULL, NULL),
