  ('0b740b4d-0d25-53a9-923c-2dda8b3264c4'::uuid, '1411f9b5-9d68-5b80-b4e8-72d9bcaf24eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It can be helpful to quote or broadly summarize these sources.', FALSE, 0, NULL, NULL),
  ('7d79dcd5-99b8-5222-9609-0ae139fd8b50'::uuid, '1411f9b5-9d68-5b80-b4e8-72d9bcaf24eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'When writing an essay, you often rely on information from outside sources.', FALSE, 1, NULL, NULL),
  ('9a2b798e-ad51-54a5-85bf-bec9e5fff385'::uuid, '1411f9b5-9d68-5b80-b4e8-72d9bcaf24eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'You can use paraphrasing to support your ideas without relying on someone else''s explanation.', FALSE, 2, NULL, NULL),
  ('9c465ad2-43d2-5663-8458-6fb480934e58'::uuid, '1411f9b5-9d68-5b80-b4e8-72d9bcaf24eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But sometimes you need to explain a specific point from a source to demonstrate its meaning and connection to your own ideas.', FALSE, 3, NULL, NULL),
  ('9d0f542f-cc2c-5d1b-9f0c-9722a9782427'::uuid, '1411f9b5-9d68-5b80-b4e8-72d9bcaf24eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For this, you need to paraphrase, which is important for providing evidence in your own words.', FALSE, 4, NULL, NULL),
