  ('afc62101-c687-5d72-b5e3-8851f22006f4'::uuid, '142ed3d6-351b-5611-a089-c08c5837591c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'thoughtful', FALSE, 19, 4, NULL),
  ('16002202-571e-5e2f-85f1-3442eee88105'::uuid, '142fcbba-3030-5e04-8ec4-5026c134d586'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'James Harrington, the philosopher, is a good example. When his sisters applied for habeas corpus, he was taken from the Tower of London to a barren island where habeas corpus could not be imposed.', FALSE, 0, NULL, NULL),
  ('15eb4848-ffa9-5b46-8691-ce3538c9da36'::uuid, '142fcbba-3030-5e04-8ec4-5026c134d586'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In 1679, what became known as the first Exclusionist Parliament passed at least one useful piece of legislation: on the day parliament was suspended, the King gave his assent to a Habeas Corpus Act.', FALSE, 1, NULL, NULL),
  ('237873bc-bde1-5fb8-a825-ae8a1179a60e'::uuid, '142fcbba-3030-5e04-8ec4-5026c134d586'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The new act put a stop to such abuses and deprived the executive of powers it might have used to support oppressive and arbitrary government.', FALSE, 2, NULL, NULL),
  ('24388ce3-3d94-5fc7-bc2f-6ddcb92c5ba2'::uuid, '142fcbba-3030-5e04-8ec4-5026c134d586'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Habeas corpus, a law by which a prisoner could demand to be brought before the courts and have his case heard, was a well-established right in England, but the authorities had found a number of ways of getting round its use where political prisoners were concerned.', FALSE, 3, NULL, NULL),
  ('a10bb234-36dd-5ee4-a5d4-ebdd9b01e582'::uuid, '142fda0f-d57b-582d-9b5e-e4d95c4e153d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In the last few years, we started to connect everyday objects using machine-to-machine (M2M) technologies, to create the Internet of Things.', FALSE, 0, NULL, NULL),
  ('95b0b5b4-b293-5b4e-baab-ff5b013810ec'::uuid, '142fda0f-d57b-582d-9b5e-e4d95c4e153d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'What are the possibilities it offers, and the threats it poses?', FALSE, 1, NULL, NULL),
  ('e0ac57ce-8a52-58e4-822a-1a7560b49e07'::uuid, '142fda0f-d57b-582d-9b5e-e4d95c4e153d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Decades ago, we connected computers and got today''s powerful Internet.', FALSE, 2, NULL, NULL),
  ('49b901b1-60f8-5b76-a94e-93a7e5297579'::uuid, '142fda0f-d57b-582d-9b5e-e4d95c4e153d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But what does this really mean to you, your company and your country?', FALSE, 3, NULL, NULL),
  ('ee161c04-a532-552c-a002-964298b4183b'::uuid, '14479fff-89ea-550a-a2ac-ac4865e31c46'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The soil that sits right under our feet could be at the front lines of climate change, as it has a huge potential to act as a carbon sink.', FALSE, 0, NULL, NULL),
  ('72a986d1-c788-5594-b7cd-7c0b7b18f1d4'::uuid, '14479fff-89ea-550a-a2ac-ac4865e31c46'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A carbon sink is a reservoir capable of accumulating and storing carbon for an indefinite period.', FALSE, 1, NULL, NULL),
  ('30056ca2-bd52-59d0-8aab-f320de6ede5c'::uuid, '14479fff-89ea-550a-a2ac-ac4865e31c46'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Soil has the potential to remove an estimated 1.09 gigatonnes of CO2 per year.', FALSE, 2, NULL, NULL),
  ('e1d64f9e-e232-5e0c-a407-0eadbad38e33'::uuid, '14479fff-89ea-550a-a2ac-ac4865e31c46'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In doing so, it lowers the concentration of carbon dioxide (CO2) from the atmosphere.', FALSE, 3, NULL, NULL),
  ('958a4db5-5a21-5e4b-8547-930213ded1b7'::uuid, '1491d857-25c2-57af-83e4-d2b9899659d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'instruments', FALSE, 0, 0, NULL),
