  ('476ab434-c06e-5bef-b150-7a5a1ae4972f'::uuid, '14974993-7f10-58b1-b753-ac463136fd78'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Of the total supply of water on the Earth, only about 3 percent of it is fresh, and most of that is stored as ice and snow at the poles, or is so deep under the surface of the Earth that we cannot get to it.', FALSE, 0, NULL, NULL),
  ('321db915-fa1f-5af7-a6e8-903538beb32f'::uuid, '14974993-7f10-58b1-b753-ac463136fd78'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Without water, people, animals and plants cannot live.', FALSE, 1, NULL, NULL),
  ('a7a2123e-d6ba-5b0b-ae88-fc66333a3d65'::uuid, '14974993-7f10-58b1-b753-ac463136fd78'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Everybody needs fresh water.', FALSE, 2, NULL, NULL),
  ('997285d3-1f4e-5b5a-963d-b6bacaae06a8'::uuid, '14974993-7f10-58b1-b753-ac463136fd78'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Although a few plants and animals can make do with saltwater, all humans need a constant supply of fresh water if they are to stay fit and healthy.', FALSE, 3, NULL, NULL),
