  ('31f0acec-9eff-5ad8-ae6e-47fa802ce794'::uuid, '14deb912-6eb5-5356-b72d-33acc089ea17'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Men and women started to worship gods as soon as they became recognizably human; they created religions at the same time as they created works of art.', FALSE, 0, NULL, NULL),
  ('47368776-922f-5ed6-b8a2-2adfc5bee2cd'::uuid, '14deb912-6eb5-5356-b72d-33acc089ea17'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These early faiths expressed the wonder and mystery that seems always to have been an essential component of the human experience of this beautiful world.', FALSE, 1, NULL, NULL),
  ('faea1f04-2803-5547-9d8b-bbe2ac67d6aa'::uuid, '14deb912-6eb5-5356-b72d-33acc089ea17'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This was not simply because they wanted to propitiate powerful forces.', FALSE, 2, NULL, NULL),
  ('912ae1d1-98df-54fe-93e3-4d3ee963fdd0'::uuid, '14deb912-6eb5-5356-b72d-33acc089ea17'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'My study of the history of religion has revealed that human beings are spiritual animals. Indeed, there is a case for arguing that Homo sapiens is also Homo religious.', FALSE, 3, NULL, NULL),
  ('f46dc1a7-a76b-5810-bcdc-12b935f742ac'::uuid, '14decee3-9d06-57d4-965c-2c269efa60eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This event was pivotal in ending the Cold War and reunifying Germany.', FALSE, 0, NULL, NULL),
  ('d8772dd4-f603-5a00-8dd3-8d37cfa37889'::uuid, '14decee3-9d06-57d4-965c-2c269efa60eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In 1989, a series of political changes and public protests led to the fall of the wall.', FALSE, 1, NULL, NULL),
  ('3d432eb4-c467-559a-ab26-48ef075d9f20'::uuid, '14decee3-9d06-57d4-965c-2c269efa60eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For decades, it was a physical representation of the ''Iron Curtain'' that separated communist and capitalist Europe.', FALSE, 2, NULL, NULL),
  ('a5b191a2-aea7-5cca-970d-417e7fc6f231'::uuid, '14decee3-9d06-57d4-965c-2c269efa60eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Even today, the fall of the Berlin Wall remains a symbol of liberation and the triumph of democratic ideals.', FALSE, 3, NULL, NULL),
  ('60954077-81d7-50c2-a311-e26482b4bc8e'::uuid, '14decee3-9d06-57d4-965c-2c269efa60eb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Berlin Wall, constructed in 1961, symbolized the division between East and West Germany.', FALSE, 4, NULL, NULL),
