  ('0842cd08-6792-5105-82df-6e1d377f6537'::uuid, '15623765-cd8b-52e0-84aa-c0c4feb4f1b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'If these trends continue, the double whammy of population growth and richer diets will require us to roughly double the amount of crops we grow by 2050.', FALSE, 1, NULL, NULL),
  ('423313ea-23af-580a-98ed-8bb9bb70d4a8'::uuid, '15623765-cd8b-52e0-84aa-c0c4feb4f1b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The spread of prosperity across the world, especially in China and India, is driving an increased demand for meat, eggs, and dairy, boosting pressure to grow more corn and soybeans to feed more cattle, pigs, and chickens.', FALSE, 2, NULL, NULL),
  ('00336174-dfd3-57c5-b46d-4927a321ab39'::uuid, '15623765-cd8b-52e0-84aa-c0c4feb4f1b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'We'' ll likely have two billion more mouths to feed by mid-century --more than nine billion people.', FALSE, 3, NULL, NULL),
  ('e8054f94-a3c4-515c-90c4-7427abeb52e9'::uuid, '156becb9-5cd2-53f8-85cf-37b5d6f228b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'stage', FALSE, 0, NULL, NULL);
