  ('6f1d1b1a-c06d-5121-ba56-2f64229c38fe'::uuid, '15753063-f9f8-5a74-bb50-61b1676c4686'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It was a significant moment in American history, as it signaled the defeat of the Confederate Army and the collapse of the Southern rebellion.', FALSE, 0, NULL, NULL),
  ('c643b715-9296-5156-b5dc-ed9e2a390e72'::uuid, '15753063-f9f8-5a74-bb50-61b1676c4686'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'On April 9, 1865, Confederate General Robert E. Lee surrendered to Union General Ulysses S. Grant at Appomattox Court House.', FALSE, 1, NULL, NULL),
  ('29496a2c-6364-5e4f-8263-5d4d3d886447'::uuid, '15753063-f9f8-5a74-bb50-61b1676c4686'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This historic event marked the end of the American Civil War and the beginning of the process of reunification.', FALSE, 2, NULL, NULL),
  ('364882c8-983e-52cd-b9af-3cee9efe9149'::uuid, '15753063-f9f8-5a74-bb50-61b1676c4686'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The surrender at Appomattox Court House is often seen as a symbol of the nation''s healing and reconciliation.', FALSE, 3, NULL, NULL),
