  ('289dc812-1486-5d58-a055-f47fa8c534d8'::uuid, '16e43b79-8f62-5524-a1a0-612ab2b4ccad'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'impedes', TRUE, 18, 4, NULL),
  ('0d5e0b1f-4fe6-53ba-8654-6df777bd1247'::uuid, '16e43b79-8f62-5524-a1a0-612ab2b4ccad'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'deceases', FALSE, 19, 4, NULL),
  ('a7242528-c746-5be3-aec3-f7efc1662c93'::uuid, '16e71e50-7c74-5cfb-afaa-01f3f195f7d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But this week, the journal Science published some remarkable maps that help fill that gap.', FALSE, 0, NULL, NULL),
  ('8bbb4fe3-28ef-5981-8359-a40ab4c84dff'::uuid, '16e71e50-7c74-5cfb-afaa-01f3f195f7d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The fishing industry has long been hard to monitor. Its global footprint is difficult even to visualize.', FALSE, 1, NULL, NULL),
  ('69555af6-f991-5995-baf9-4d79676b8de2'::uuid, '16e71e50-7c74-5cfb-afaa-01f3f195f7d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Much fishing takes place unobserved, far from land, and once the boats move on, they leave behind few visible traces of their activity.', FALSE, 2, NULL, NULL),
  ('b0e0187e-4a9f-5329-8ae7-aac4f6f8419f'::uuid, '16e71e50-7c74-5cfb-afaa-01f3f195f7d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'John Amos, president of an organization called SkyTruth, which helped produce them, issued a statement calling the maps "a stunning illustration of the vast scope of exploitation of the ocean".', FALSE, 3, NULL, NULL),
  ('ac90e95c-359a-533d-9507-4b78b7071203'::uuid, '16e7f686-4199-5eeb-8562-c4310e3dc099'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There is no reason to believe that this pace will slacken.', FALSE, 0, NULL, NULL),
  ('4261c026-0518-5834-87bc-eb524d52f5f0'::uuid, '16e7f686-4199-5eeb-8562-c4310e3dc099'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The world population goes up by two percent a year, city population goes up by four percent a year, but in big cities the rate may be as much as five and six percent a year.', FALSE, 1, NULL, NULL),
  ('336cbb7c-78c1-53ab-ad54-2b1b9d46274c'::uuid, '16e7f686-4199-5eeb-8562-c4310e3dc099'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To give only one example of almost visible acceleration, Athens today grows by three dwellings and 100 square metres of road every hour.', FALSE, 2, NULL, NULL),
  ('f5c509ce-9166-558a-857c-1de956c3f290'::uuid, '16e7f686-4199-5eeb-8562-c4310e3dc099'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'After millennia of growth so slow that each generation hardly notice it, the cities are suddenly racing off in every direction.', FALSE, 3, NULL, NULL),
  ('6cfa583c-6169-5044-855b-7df4e330f28a'::uuid, '16fe47d6-b223-55dc-b43a-d6e15b85a143'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'aim', TRUE, 0, NULL, 0),
  ('24bb1f12-edc3-5d4a-9704-9b8c7663e3be'::uuid, '16fe47d6-b223-55dc-b43a-d6e15b85a143'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'delivers', FALSE, 1, NULL, NULL),
