  ('90a0160f-0299-5e70-8b82-e3f7cfaf66d5'::uuid, '19dc671b-6be0-5268-91d9-dca05f919503'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Throughout the centuries in Western culture from the 11th century on through the end of the 17th century, the definition of art was anything done with skill as the result of knowledge and practice.', FALSE, 1, NULL, NULL),
