  ('dafe74ed-0353-5ac9-bfaa-f06ebb51246b'::uuid, '19dc671b-6be0-5268-91d9-dca05f919503'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'During the Romantic period of the 18th century, as a reaction to the Enlightenment and its emphasis on science, empirical evidence, and rational thought, art began to be described as not just being something done with skill.', FALSE, 3, NULL, NULL),
