  ('581d6333-3078-51b0-8e22-08a992e78bbc'::uuid, '1ca2c404-311c-59c0-955a-7f63940d0b77'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Several criteria are used to classify the different types of skin.', FALSE, 1, NULL, NULL),
