  ('f9943514-d3d3-50cb-bf0c-790c6d0841bf'::uuid, '1ca2c404-311c-59c0-955a-7f63940d0b77'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Based on his method, there are five types of healthy skin: normal, dry, oily, combination (both oily and dry skin) and sensitive.', FALSE, 3, NULL, NULL),
