  ('190cefa8-8748-554d-a458-55345a7772d7'::uuid, '1dcefc87-c46b-5d5f-8e1d-3292777bdba8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This situation was forced upon earth dwellers of that time because of their extraordinary way of life.', FALSE, 0, NULL, NULL),
  ('e3f341b7-4b3d-5626-8446-3c0b64cacd47'::uuid, '1dcefc87-c46b-5d5f-8e1d-3292777bdba8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Men and women moved about in cars, buses and trains from a very early age. There were lifts and escalators in all large buildings to prevent people from walking.', FALSE, 1, NULL, NULL),
  ('0e8793e0-b717-5dfb-b8a2-f02ff2ed7878'::uuid, '1dcefc87-c46b-5d5f-8e1d-3292777bdba8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'When the time comes for anthropologists to turn their attention to the twentieth century, they will surely choose the label ''Legless Man''.', FALSE, 2, NULL, NULL),
  ('99f8ff40-f4d8-5904-9de9-bc11b12375ff'::uuid, '1dcefc87-c46b-5d5f-8e1d-3292777bdba8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The past ages of man have all been carefully labeled by anthropologists. Descriptions like ''Paleolithic Man'', ''Neolithic Man'', etc., neatly sum up whole periods.', FALSE, 3, NULL, NULL),
  ('90c0d2ef-c6c6-51a8-b16f-06db5920f2eb'::uuid, '1dcefc87-c46b-5d5f-8e1d-3292777bdba8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Histories of the time will go something like this: ''in the twentieth century, people forgot how to use their legs.', FALSE, 4, NULL, NULL),
