  ('a1b56aee-d28e-59d6-9238-63f95a66f707'::uuid, '1e58d833-ffb8-5e90-9fdc-f937324b7a2d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It debates whether human actions are self-determined or predetermined by external factors like biology, society, or divine intervention.', FALSE, 0, NULL, NULL),
  ('8aa8aa16-d18e-51f0-a786-cd4e28a02db5'::uuid, '1e58d833-ffb8-5e90-9fdc-f937324b7a2d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Philosophers like Immanuel Kant have argued in favor of free will, asserting its necessity for moral responsibility.', FALSE, 1, NULL, NULL),
  ('6c6371ba-823c-566a-8527-48e1b3c5cdf2'::uuid, '1e58d833-ffb8-5e90-9fdc-f937324b7a2d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Free will is a fundamental philosophical question concerning human autonomy and responsibility.', FALSE, 2, NULL, NULL),
  ('730a944f-fdba-50e8-ada2-7360cb98a7d1'::uuid, '1e58d833-ffb8-5e90-9fdc-f937324b7a2d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Conversely, determinists believe that all events, including human actions, are determined by preceding causes.', FALSE, 3, NULL, NULL),
