  ('612fa2e5-6ebe-558c-b14d-7637d58f2085'::uuid, '1ea89b31-b2e4-596e-8afe-b80ecdfcb186'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The children in that neighborhood were her primary source of language input.', FALSE, 1, NULL, NULL),
  ('55053d55-9e0b-5672-b763-35a34bfbf55d'::uuid, '1ea89b31-b2e4-596e-8afe-b80ecdfcb186'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Her family came to the United States for a period of two years while her father was a visiting scholar at Harvard, and they took residence in North Cambridge, a working-class neighborhood.', FALSE, 2, NULL, NULL),
  ('dfd6fb2f-ba0f-577f-9dc2-d6c81aaa2575'::uuid, '1ea89b31-b2e4-596e-8afe-b80ecdfcb186'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This paper summarizes some of the major data gathered in a longitudinal, naturalistic study of a Japanese girl learning English as a second language.', FALSE, 3, NULL, NULL),
  ('719f70fd-d3d8-510f-aa55-dccd1816ec40'::uuid, '1ea89b31-b2e4-596e-8afe-b80ecdfcb186'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Uguisu also attended public kindergarten of two hours every day, and later elementary school, but with no tutoring in English syntax. Most of her neighborhood friends were in her same class at school.', FALSE, 4, NULL, NULL),
  ('c0710bac-2d68-5ea0-91ba-48e38c28dbf6'::uuid, '1eac3d10-aec8-5f27-a327-e814d10cf667'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'predicts', FALSE, 0, 0, NULL),
