  ('7957c9af-51b8-5220-bf4e-d74ce7a29d61'::uuid, '1f70774c-a7bf-5ec9-b170-146f7ec77686'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'People who regularly ate tofu were 10 percent less likely to die from a common cause than those who avoided soy products.', TRUE, 2, NULL, NULL),
