  ('e8b791ce-ca83-5247-aa33-3302302be2e2'::uuid, '21803e78-280a-50ad-83a3-70cb0b00a67c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Over 600 million children and adolescents worldwide are unable to attain minimum proficiency levels in reading and mathematics, even though two thirds of them are in school.', FALSE, 0, NULL, NULL),
