  ('ceee6288-7529-52e0-95db-e1cce89d8bab'::uuid, '21db2314-41df-5f4b-a1a8-2c74e9085bcf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Hip Hop emerged as a reaction to the gang culture and violence of the South Bronx in the 1970s, and daily experiences of poverty, racism, exclusion, crime, violence, and neglect.', FALSE, 0, NULL, NULL),
  ('264a08a6-32b0-5c4d-ae79-28948bf4bbae'::uuid, '21db2314-41df-5f4b-a1a8-2c74e9085bcf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Without these, Hip Hop culture would never have been, and it is because these values remain at its core that Hip Hop is such a powerful agent of positive social change around the world.', FALSE, 1, NULL, NULL),
  ('e4f86b1f-009d-5734-b3e5-085cd3ca1d13'::uuid, '21db2314-41df-5f4b-a1a8-2c74e9085bcf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It necessarily embodies and values resilience, understanding, community and social justice.', FALSE, 2, NULL, NULL),
  ('643d9abf-c726-5547-9ce8-f51cad24c3a8'::uuid, '21db2314-41df-5f4b-a1a8-2c74e9085bcf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Yet, the hip hop project is not yet free from these difficult circumstances.', FALSE, 3, NULL, NULL),
