  ('86b3a12a-279b-5315-a7be-ff82e4a41221'::uuid, '22fb53ef-bb7e-5702-8505-633b88069aaa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Fruit and vegetable intake is important for the prevention of future chronic disease. So it''s important to know whether intakes of teens are approaching national objectives for fruit and vegetable consumption.', FALSE, 1, NULL, NULL),
  ('91a03aab-7d35-5b26-afde-cef3ffb8fbf2'::uuid, '22fb53ef-bb7e-5702-8505-633b88069aaa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Teens in middle adolescence are eating fewer fruits and vegetables than in 1999. Larson and colleagues found.', FALSE, 2, NULL, NULL),
  ('b206de96-3dc9-526e-ba6f-9fb412347171'::uuid, '22fb53ef-bb7e-5702-8505-633b88069aaa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This is giving us the message that we need new and enhanced efforts to increase fruit and vegetable intake that we haven''t been doing in the past.', FALSE, 3, NULL, NULL),
