  ('58634261-dc28-55ee-adc2-7f148a2ac5b1'::uuid, '23de3ac4-6b86-5d58-8f98-a5a688956943'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The choice between urban and rural living is a personal one and depends on individual preferences and priorities.', FALSE, 0, NULL, NULL),
  ('2777ff34-f344-5dcf-b229-d8a207508404'::uuid, '23de3ac4-6b86-5d58-8f98-a5a688956943'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Some people prefer to live in the hustle and bustle of a city, while others seek the tranquility of rural life.', FALSE, 1, NULL, NULL),
  ('e25d2f83-4d14-52bf-a750-57747388272d'::uuid, '23de3ac4-6b86-5d58-8f98-a5a688956943'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'On the other hand, rural areas provide a slower pace of life, cleaner air, and a stronger sense of community, but they may lack modern amenities.', FALSE, 2, NULL, NULL),
  ('96e05d28-6e8c-5517-8f16-983ea44b1004'::uuid, '23de3ac4-6b86-5d58-8f98-a5a688956943'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Urban areas offer convenience, job opportunities, and cultural amenities, but they can also be crowded and stressful.', FALSE, 3, NULL, NULL),
