  ('9f7a1946-30af-582c-80e3-a4efbec8dbee'::uuid, '26761830-5132-559b-8415-2b622f37cc56'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Researchers found that proteins can regulate plant growth by coordinating various biological responses.', FALSE, 0, NULL, NULL),
  ('4a0a8f3d-8d8a-55ec-bf00-4595ca6a3542'::uuid, '26761830-5132-559b-8415-2b622f37cc56'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Understanding this process helps researchers find that some grains can live in drought conditions that would typically be fatal.', FALSE, 1, NULL, NULL),
  ('adc7fd56-da7d-5232-805e-6ea014f33640'::uuid, '26761830-5132-559b-8415-2b622f37cc56'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They discovered that these specific proteins trigger mechanisms that allow plants to conserve water during environmental stress.', FALSE, 2, NULL, NULL),
  ('e59c9f6b-4f31-5d72-904c-8ad1fab1d849'::uuid, '26761830-5132-559b-8415-2b622f37cc56'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In the future, this can be applied to crops so they can adapt to drought, potentially resolving the global food crisis or issues of human hunger.', FALSE, 3, NULL, NULL),
  ('9fc0372a-5564-535b-9320-defbc8c2087c'::uuid, '2679a78f-e2cd-5364-8660-31bd0076c37e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'rise', FALSE, 0, NULL, NULL),
