  ('1117e85a-2258-5ac9-89e4-ac7fb592730c'::uuid, '26b45ffa-2c87-5ca6-a9a4-419f9b956ea9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To understand the effects of air pollution on respiratory health, an experiment was conducted in two different environments: a polluted urban area and a clean rural area.', FALSE, 0, NULL, NULL),
  ('bc37b586-27dc-57af-a149-7dee22c532d4'::uuid, '26b45ffa-2c87-5ca6-a9a4-419f9b956ea9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'At the outset, there were no significant differences in respiratory function between participants in both areas.', FALSE, 1, NULL, NULL),
  ('76de833a-7689-54da-b880-18dd6cd1ee77'::uuid, '26b45ffa-2c87-5ca6-a9a4-419f9b956ea9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Participants'' respiratory health was monitored over several months.', FALSE, 2, NULL, NULL),
  ('4259fc86-0a08-5142-b2cb-e24069565900'::uuid, '26b45ffa-2c87-5ca6-a9a4-419f9b956ea9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, over time, those in the urban area showed a decline in respiratory health, while those in the rural area remained stable.', FALSE, 3, NULL, NULL),
