  ('dbee6617-b130-5c86-bb86-bf8930c077cb'::uuid, '270546c9-805b-5ee0-bb60-0fa224ca6fc7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They treat a wide range of conditions and refer patients to specialists when necessary.', FALSE, 1, NULL, NULL),
  ('06b7893b-1724-5a67-b2e0-cc01122aacbd'::uuid, '270546c9-805b-5ee0-bb60-0fa224ca6fc7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Additionally, they play a key role in preventative care and health education.', FALSE, 2, NULL, NULL),
  ('adc335f4-d07b-507a-bc36-778a9ebdd4b9'::uuid, '270546c9-805b-5ee0-bb60-0fa224ca6fc7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, their broad scope of practice means they must constantly update their knowledge across a wide range of medical fields.', FALSE, 3, NULL, NULL),
  ('368c6b4d-b5db-5d78-965b-ee29301fc371'::uuid, '270e96c2-c6c9-5825-95e0-01f54f861ad4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Thus, the Declaration of Independence remains a powerful testament to the ideals of democracy and self-governance.', FALSE, 0, NULL, NULL),
  ('d15fe36d-9183-57b7-8313-442819f50fbb'::uuid, '270e96c2-c6c9-5825-95e0-01f54f861ad4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Drafted by Thomas Jefferson, it declared the thirteen American colonies free from British rule.', FALSE, 1, NULL, NULL),
  ('3c061681-e494-5fd5-a8ac-d14ac26a6988'::uuid, '270e96c2-c6c9-5825-95e0-01f54f861ad4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Consequently, this document not only symbolized the pursuit of liberty but also ignited revolutionary fervor globally.', FALSE, 2, NULL, NULL),
  ('0e9213e6-dca6-5db6-853f-f1221bdb6c9b'::uuid, '270e96c2-c6c9-5825-95e0-01f54f861ad4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In 1776, the American Declaration of Independence was adopted, marking the United States'' birth as a sovereign nation.', FALSE, 3, NULL, NULL),
