  ('6150ba62-4960-5936-8bbe-4a5abbc1dbca'::uuid, '277a84ae-69e9-5bbe-ad0b-6d86f6638b5c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Harappan Civilization, part of the Indus Valley Civilization, was one of the world''s earliest urban cultures.', FALSE, 0, NULL, NULL),
  ('9396325a-4bef-5b40-9a50-e5456ecc5225'::uuid, '277a84ae-69e9-5bbe-ad0b-6d86f6638b5c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Despite its sophistication, it mysteriously declined around 1900 BCE.', FALSE, 1, NULL, NULL),
  ('8718634f-df6e-5bd9-9caa-89d663c128c1'::uuid, '277a84ae-69e9-5bbe-ad0b-6d86f6638b5c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Yet, there is no consensus on what led to its decline.', FALSE, 2, NULL, NULL),
