  ('504fbcd2-e4c3-5473-b48d-debd76ee5cc4'::uuid, '27fb6a22-c44c-5dce-8356-2da8b00516f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The aim of this article is to discuss the consequences of DRM for consumers, firms and society.', FALSE, 0, NULL, NULL),
  ('7fc84a91-86e5-53cf-8668-9cfec34a284f'::uuid, '27fb6a22-c44c-5dce-8356-2da8b00516f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The article concludes with some public policy recommendations.', FALSE, 1, NULL, NULL),
  ('57674619-e40e-5579-b616-12f1d6f98bb9'::uuid, '27fb6a22-c44c-5dce-8356-2da8b00516f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In contrast, consumers are shown to be likely to see few benefits in DRM.', FALSE, 2, NULL, NULL),
  ('c5c334ed-fda8-525c-8616-42b21bbf7b45'::uuid, '27fb6a22-c44c-5dce-8356-2da8b00516f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Due to its ability to solve all main problems associated with digital goods, Digital Rights Management is the favorite option used by companies to tackle piracy.', FALSE, 3, NULL, NULL),
  ('9d37bbc1-7ef3-5c15-bde6-f435015f5ab0'::uuid, '27fb6a22-c44c-5dce-8356-2da8b00516f9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The rationales of DRM are discussed and the expected benefits for firms are presented.', FALSE, 4, NULL, NULL),
  ('423410b0-0416-55dc-8dc6-a09ca0c89aee'::uuid, '27fd3ee1-f76d-5e1b-b689-65cebc2b7d8d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Nanoplastics are even smaller (some are 500 times smaller than a human hair).', FALSE, 0, NULL, NULL),
  ('40e39477-7045-5fdf-b4e2-756571c1a306'::uuid, '27fd3ee1-f76d-5e1b-b689-65cebc2b7d8d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Plastic specks smaller than five millimetres are called microplastics.', FALSE, 1, NULL, NULL),
  ('18489644-4b8b-58be-818e-c363b0ac904b'::uuid, '27fd3ee1-f76d-5e1b-b689-65cebc2b7d8d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'When the plastic litter in our waterways and on the ground gets weathered and degrades, it eventually breaks down into millions of smaller and smaller pieces.', FALSE, 2, NULL, NULL),
  ('b66fcb36-8cf9-5336-9232-4f474447e9cb'::uuid, '27fd3ee1-f76d-5e1b-b689-65cebc2b7d8d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Plastic bottles, bags and containers float in the sea and clog landfill sites.', FALSE, 3, NULL, NULL),
  ('8dbf4297-8ad3-5f73-bf0c-b9de5a75f6cd'::uuid, '27fd3ee1-f76d-5e1b-b689-65cebc2b7d8d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'While exposure to air pollutants have been associated with health impacts, including higher risk of respiratory infections, heart disease and lung cancer, science still lacks evidence about how microplastics and nanoplastics are affecting the human body.', FALSE, 4, NULL, NULL),
  ('d0620ac8-65c0-5c8f-9704-db131a6ada6d'::uuid, '2803e721-8258-54d6-ad45-88a13294f9f1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In the past, communication was limited to written letters and face-to-face conversations.', FALSE, 0, NULL, NULL),
  ('5450b167-79ac-5a13-9d6f-c747339b22bc'::uuid, '2803e721-8258-54d6-ad45-88a13294f9f1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This has transformed the way we communicate and interact with others.', FALSE, 1, NULL, NULL),
  ('cfebd1bf-77a7-5c5c-954c-9e03ccbcba39'::uuid, '2803e721-8258-54d6-ad45-88a13294f9f1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Nowadays, we can send messages, make video calls, and share information with just a few clicks.', FALSE, 2, NULL, NULL),
  ('cf65fa0b-2c7d-52f8-aca6-49e5e7ebf20a'::uuid, '2803e721-8258-54d6-ad45-88a13294f9f1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Advances in technology have made it possible to connect with people around the world instantly.', FALSE, 3, NULL, NULL),
  ('55806f73-27e4-5dd2-b4ac-cdd34c07eee9'::uuid, '2806940e-47c7-54e7-96e3-68855f918a6b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They found that bees can see the blue halo, and use it as a signal to locate flowers more efficiently.', FALSE, 0, NULL, NULL),
  ('0c806d40-f6c7-58b9-9095-1e9f545fb6c1'::uuid, '2806940e-47c7-54e7-96e3-68855f918a6b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These nanostructures scatter light particles in the blue to ultraviolet colour spectrum, generating a subtle effect that scientists have christened the ''blue halo''.', FALSE, 1, NULL, NULL),
  ('df209d00-c8e1-5913-bac2-e81088237dcc'::uuid, '2806940e-47c7-54e7-96e3-68855f918a6b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'By manufacturing artificial surfaces that replicated ''blue halos'', scientists were able to test the effect on pollinators, in this case foraging bumblebees.', FALSE, 2, NULL, NULL),
  ('071d9575-2d5e-59ce-aecd-daba648e4593'::uuid, '2806940e-47c7-54e7-96e3-68855f918a6b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Latest research has found that several common flower species have nanoscale ridges on the surface of their petals that meddle with light when viewed from certain angles.', FALSE, 3, NULL, NULL),
