  ('6150f149-0a6e-56f0-be33-24f08d2096ac'::uuid, '28561e1b-15f8-5e24-9f50-bd351ca8e9b5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'further', TRUE, 15, 3, NULL),
  ('6c9b92e2-08c2-54e8-bc67-7809ebbe29fd'::uuid, '2857d864-3def-5106-9d3c-2abff2d14012'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Now, researchers have identified an ordinary dietary element that may increase the chances of a breast cancer becoming drug-resistant.', FALSE, 0, NULL, NULL),
  ('717201b7-222c-538e-b943-949f5e6ddba8'::uuid, '2857d864-3def-5106-9d3c-2abff2d14012'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The work also raises the possibility that a drug could be developed to mirror the effects of that dietary restriction, by blocking cells'' ability to take in leucine from the surrounding environment.', FALSE, 1, NULL, NULL),
  ('385d75e1-4ed1-5afa-bec2-a59154607930'::uuid, '2857d864-3def-5106-9d3c-2abff2d14012'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Drug resistance is the leading cause of death in women with estrogen-receptor-positive breast cancer, the most common form of the disease.', FALSE, 2, NULL, NULL),
  ('105358f1-06ca-5677-b328-c898df01ebca'::uuid, '2857d864-3def-5106-9d3c-2abff2d14012'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The connection of the amino acid leucine to drug resistance raises hopes that a relatively simple intervention, like a shift to a low-leucine diet, can reduce the incidence of drug resistance, which is responsible for a large portion of the roughly 40,000 breast cancer deaths every year.', FALSE, 3, NULL, NULL),
  ('e7b6cdda-3f00-5b6d-acb0-22960668999a'::uuid, '286b26e4-4bee-5a05-9dbb-b27db6a4a7fc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'While this invention promised companies a lot of benefits, there were many difficulties at first.', FALSE, 0, NULL, NULL),
  ('f7c710de-c182-55bb-bfbf-3390a1415bb6'::uuid, '286b26e4-4bee-5a05-9dbb-b27db6a4a7fc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This situation caused delays and created opportunities for damage that were only reduced when the shipping container was invented.', FALSE, 1, NULL, NULL),
  ('2acb5ee2-6b7e-59d7-bb0e-0c848eaed25d'::uuid, '286b26e4-4bee-5a05-9dbb-b27db6a4a7fc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It was also necessary to build new roads and rail lines, requiring companies to invest millions.', FALSE, 2, NULL, NULL),
  ('7f4d8b47-d14c-5d60-a91e-a6339d6c4690'::uuid, '286b26e4-4bee-5a05-9dbb-b27db6a4a7fc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'60 years ago, when businesses did not think of the distribution of goods as a single process, someone had to physically transfer every box each time goods were moved from one transport to another.', FALSE, 3, NULL, NULL),
  ('50dba451-0ffa-5c88-aa7a-bfc7e8172a63'::uuid, '286b26e4-4bee-5a05-9dbb-b27db6a4a7fc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The shipping system required many changes and other technical innovations before the containers could be used.', FALSE, 4, NULL, NULL),
