  ('713a4222-0016-5b5d-aef1-65f0db8a3464'::uuid, '29333ab0-b499-5710-bfb8-d1562a88b219'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'meeting', FALSE, 23, 5, NULL),
  ('e9fe4bbf-bb6d-5711-bd1f-7b1492e02729'::uuid, '2942316c-3179-56fe-84e4-1b1ab215c689'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Mapping the Himalayas and Everest wasn''t easy. Foreigners were not welcome, so Himalayan traders were recruited to infiltrate the area and gather enough information to allow accurate maps to be made.', FALSE, 0, NULL, NULL),
  ('189d8aca-f57e-5823-992d-6e217dd26a82'::uuid, '2942316c-3179-56fe-84e4-1b1ab215c689'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'About 200 million years ago, the Indian subcontinent broke away from a vast southern super-continent called Gondwanaland. It drifted northeast across the sea and collided with the Asian landmass. These two huge landmasses buckled, rather like cars in a head-on collision, and rose up to form the world''s tallest mountain.', FALSE, 1, NULL, NULL),
  ('52feded9-f7cf-56a4-969f-bfaf66d50e12'::uuid, '2942316c-3179-56fe-84e4-1b1ab215c689'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Fossilized fish remains have been found high up on the slopes of Everest proving that the world''s highest mountain once lay at the bottom of the sea. How did this happen?', FALSE, 2, NULL, NULL),
  ('74221ecd-f40a-5b49-968d-4c5b329f9c67'::uuid, '2942316c-3179-56fe-84e4-1b1ab215c689'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'One of the Tibetan names for this mountain translates as "Mountain So High That No Bird Can Fly Over It". It was first measured in 1852 and was called Peak XV until 1865, when it was named after the British Surveyor of India, Sir George Everest.', FALSE, 3, NULL, NULL),
  ('eff1e451-8cde-5751-9f05-0c80e72ff0ef'::uuid, '29432e1b-e736-562c-a953-45e07b19c6b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'resolve', FALSE, 0, NULL, NULL),
  ('99314774-7731-5812-9aa8-9d3f52c6f686'::uuid, '29432e1b-e736-562c-a953-45e07b19c6b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'set', TRUE, 1, NULL, 3),
