  ('efeb89b6-3834-5ca8-8fcf-bd79454bc4d5'::uuid, '29477b9c-36af-572e-aaac-55cad30239a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To test this, a group of plants was placed in an environment with extended daylight hours.', FALSE, 0, NULL, NULL),
  ('92c97d3f-89a1-5879-a9ee-55af48714ae3'::uuid, '29477b9c-36af-572e-aaac-55cad30239a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Over several weeks, the first group showed significantly faster growth than the control group.', FALSE, 1, NULL, NULL),
  ('a0356080-068c-5587-b51b-0b43a24587ae'::uuid, '29477b9c-36af-572e-aaac-55cad30239a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Another group of plants was kept under normal light conditions as a control group.', FALSE, 2, NULL, NULL),
  ('481a41d0-af06-501d-9a80-ece62b69790c'::uuid, '29477b9c-36af-572e-aaac-55cad30239a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A scientific experiment began with the hypothesis that increased sunlight exposure would enhance plant growth.', FALSE, 3, NULL, NULL),
  ('d6bca052-f388-5b1a-8a6e-f122776e0605'::uuid, '29477b9c-36af-572e-aaac-55cad30239a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This outcome suggested a strong causal relationship between sunlight exposure and plant growth.', FALSE, 4, NULL, NULL),
  ('588c3d96-b0ba-5ed4-8cc9-0246b1f4cd36'::uuid, '2959c444-0265-5d36-a1cb-f5f37aa3236e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'assuming', FALSE, 0, NULL, NULL),
