  ('7b8fe2d7-f116-5087-9301-c7cd503aa4fe'::uuid, '2a40c5bd-a5b0-5205-9550-31e46081cd2c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'allocated', FALSE, 15, 3, NULL),
  ('8b283bf9-a87c-5498-a11a-5b99f9e7225f'::uuid, '2a4af170-3743-5d93-9904-18fc1f4b19dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Previously, most Americans were uninsured because health insurance was a relatively new concept. Then more and more people started to realize the importance of quality health insurance. Insurance companies, therefore, offered more products that matched their customers.', FALSE, 0, NULL, NULL),
  ('a5a06f6e-d0b2-584d-953a-eccee1f10f02'::uuid, '2a4af170-3743-5d93-9904-18fc1f4b19dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'20% of Americans were either uninsured or faced the prospect of buying insurance in the unstable insurance market. Because they could not prove their financial capability, no insurance companies would provide good insurance for them.', FALSE, 1, NULL, NULL),
  ('56066d19-03ff-558f-bd8c-1dac0464d00d'::uuid, '2a4af170-3743-5d93-9904-18fc1f4b19dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Health insurance in America is not fair for everyone. Its aim should be protecting people against financial risk, instead of protecting their insurance company against the sick. If things go on the wrong track, people in this market would be very close to bankruptcy.', TRUE, 2, NULL, NULL),
  ('a0cc4a8f-8bb8-59a1-bb66-ff7706bcdb48'::uuid, '2a4af170-3743-5d93-9904-18fc1f4b19dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The insurance market is one where it was totally legal for insurers to discriminate against the sick for any reason. Insurers only provide basic insurance for Americans, but if people get a wrong gene or get caught in a bad traffic accident, they will no longer provide the service anymore.', FALSE, 3, NULL, NULL),
  ('d20e6584-6c6a-5c9e-b5ea-714b22ce9ef4'::uuid, '2a694ba5-8251-5e54-91a7-70387515aca9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'discovered', TRUE, 0, NULL, 0),
