  ('5af3d2b5-3eaa-5959-85d8-96474321f70b'::uuid, '2a6ec219-7499-57ac-b541-9e9450b6dc4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Despite these changes, the essence of street food - providing affordable, tasty, and accessible meals - remains constant.', FALSE, 0, NULL, NULL),
  ('88ce6541-faa3-5b1d-9e92-6c5ea2b0a165'::uuid, '2a6ec219-7499-57ac-b541-9e9450b6dc4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The future of street food looks promising, with trends leaning towards sustainability and health.', FALSE, 1, NULL, NULL),
  ('e1d828c7-f56e-5136-9034-b36858432574'::uuid, '2a6ec219-7499-57ac-b541-9e9450b6dc4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Additionally, technology also is playing a role in how street food is marketed and sold.', FALSE, 2, NULL, NULL),
  ('02a24f2d-da5a-5d4f-97f7-f27d592d9191'::uuid, '2a6ec219-7499-57ac-b541-9e9450b6dc4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In response to this, as consumers become more environmentally and health-conscious, vendors are adapting their offerings.', FALSE, 3, NULL, NULL),
  ('476b91ab-f37f-541f-be4b-92fd5b4df75e'::uuid, '2a733c25-8e64-52ec-ac8a-32f9b490e99e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This debate highlights the complex interplay between language, cognition, and culture.', FALSE, 0, NULL, NULL),
  ('0840fab7-e04e-5b40-aaf7-4d05704261dd'::uuid, '2a733c25-8e64-52ec-ac8a-32f9b490e99e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The relationship between language and thought is a topic of considerable debate in linguistics and psychology.', FALSE, 1, NULL, NULL),
  ('59659346-4a9f-5e81-b004-6e08be2d7392'::uuid, '2a733c25-8e64-52ec-ac8a-32f9b490e99e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Others contend that our thoughts are independent of language, with language merely expressing pre-existing ideas.', FALSE, 2, NULL, NULL),
  ('7eed58f8-1b12-55df-86bc-9e3e598d544e'::uuid, '2a733c25-8e64-52ec-ac8a-32f9b490e99e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Some argue that language shapes thought, influencing how we perceive and interact with the world.', FALSE, 3, NULL, NULL),
  ('f90b9304-a6e0-56a7-9cb6-2a7ef5c7bd3b'::uuid, '2a992cd4-e87b-58cd-bfc2-1dbe1ca71381'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'more', TRUE, 0, NULL, 0),
