  ('00cf5ded-7a79-573d-aeab-62b836e2fbe2'::uuid, '2c63c524-ab4a-5b32-8ba1-ec3c1cd70c76'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In a statement issued yesterday, Prof Ebdon dismissed the argument from the country''s most selective universities, which claim that young people from poorer backgrounds generally secure worse grades.', FALSE, 0, NULL, NULL),
  ('942e4f11-d2fd-51a1-8fdb-8d2c54a11b11'::uuid, '2c63c524-ab4a-5b32-8ba1-ec3c1cd70c76'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Professor Les Ebdon, director of Fair Access to Higher Education, has said universities can no longer make excuses about the number of poorer students they take on.', FALSE, 1, NULL, NULL),
  ('701fffc9-a5c0-5b13-a2c1-68afb55893cf'::uuid, '2c63c524-ab4a-5b32-8ba1-ec3c1cd70c76'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Such defenses from the country''s most elite universities "do not hold water", Prof Ebdon said, as he urged the institutions to do more to widen their intakes.', FALSE, 2, NULL, NULL),
  ('c0bddfa1-f0a1-5fcd-8145-c649c2a4d5a6'::uuid, '2c63c524-ab4a-5b32-8ba1-ec3c1cd70c76'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'England''s most selective universities must do more to attract teenagers from disadvantaged backgrounds if they want to charge higher tuition fees, the country''s fair access watchdog has warned.', FALSE, 3, NULL, NULL),
