  ('f8335a04-e2d7-5edb-a507-a39924ca9f7e'::uuid, '2c9c777b-5732-5d15-b041-34aee31b0f0c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'tone', TRUE, 18, 4, NULL),
  ('1f5dbf13-540b-5003-9737-16eb71fc57dd'::uuid, '2c9c777b-5732-5d15-b041-34aee31b0f0c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'note', FALSE, 19, 4, NULL),
  ('b1e3bf94-74a2-59f5-83e6-48fc4141ed82'::uuid, '2cad7cde-d08b-5394-b2e9-a730eb17baa5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There are fewer Great White sharks in Australian waters than was once believed. This is because tagging has shown that sharks travel considerable distances, and a shark recorded east of Bass Strait one week is often recorded west of Bass Strait the next. However, sharks always return to their place of origin to breed.', FALSE, 0, NULL, NULL),
  ('09fbc83c-c08a-5d08-b3da-9ef850dbf369'::uuid, '2cad7cde-d08b-5394-b2e9-a730eb17baa5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A recent research study has shown that Australian Great White shark populations have remained surprisingly distinct as, despite traveling long distances. these sharks do not breed away from their original areas. This means that local shark habitats may have a greater effect on sharks than has been believed up to now.', TRUE, 1, NULL, NULL),
  ('2b86f8a7-4ece-5a6b-b588-7d9ee21c52dd'::uuid, '2cad7cde-d08b-5394-b2e9-a730eb17baa5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There is a greater variety in the Great White shark populations in Australian waters than was previously thought to be the case. This means that some types of shark are actually more endangered than was believed. Scientists are therefore developing conservation programs which will help to protect these threatened species.', FALSE, 2, NULL, NULL),
  ('89500c8b-c073-5469-80b9-1cfa3921d1ef'::uuid, '2cad7cde-d08b-5394-b2e9-a730eb17baa5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'An investigation of Great White sharks in Australian waters has come up with some unexpected conclusions. as it found that the genetic make-up of sharks in one area was quite distinct from those found elsewhere. This made scientists realize that sharks do not swim as far away from their home areas as used to be thought.', FALSE, 3, NULL, NULL),
  ('133c7117-6e15-5c27-ad66-7aa08fc288f7'::uuid, '2cb0315f-46fd-59f0-b97e-2c3ebef1c7f2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'provide more jobs for foreign workers.', FALSE, 0, NULL, NULL),
  ('3dc997a2-4bd7-56d5-8516-5b4e35bb2ded'::uuid, '2cb0315f-46fd-59f0-b97e-2c3ebef1c7f2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'slow down the rate of its development.', TRUE, 1, NULL, NULL),
  ('8bf95bb7-23da-5dbc-8141-01b3880917b9'::uuid, '2cb0315f-46fd-59f0-b97e-2c3ebef1c7f2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'sell the oil it is producing abroad.', FALSE, 2, NULL, NULL),
  ('181f3ab9-403f-596d-9e82-28a0b7563d34'::uuid, '2cb0315f-46fd-59f0-b97e-2c3ebef1c7f2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'develop more quickly than at present.', FALSE, 3, NULL, NULL),
  ('ceea6eaa-ce7e-53b5-b85b-99642aa50469'::uuid, '2ce610c9-f1f6-5eeb-871b-66cfb475f384'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The age of a tree can be determined by counting its growth rings.', FALSE, 0, NULL, NULL),
  ('338b1c17-605a-5d19-a7e1-b25ccf38a8a0'::uuid, '2ce610c9-f1f6-5eeb-871b-66cfb475f384'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Each ring represents one year of growth, typically forming during specific seasons.', FALSE, 1, NULL, NULL),
  ('2a5f93eb-bcea-5f04-a06e-cee73ba7b4bb'::uuid, '2ce610c9-f1f6-5eeb-871b-66cfb475f384'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, this method is not always accurate for tropical trees, which may not have clear growth rings.', FALSE, 2, NULL, NULL),
  ('599c6bbf-9eae-5e79-9cc8-31e83deadb72'::uuid, '2ce610c9-f1f6-5eeb-871b-66cfb475f384'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Consequently, the number and size of these rings can indicate not only the age but also the environmental conditions during each year of the tree''s life.', FALSE, 3, NULL, NULL),
  ('d3ec1551-3334-5860-8c11-5c64dea184a8'::uuid, '2ce63730-2557-506d-ad9d-0ad8785c1746'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'marks', FALSE, 0, 0, NULL),
