  ('f4a003ac-bb1f-5a13-82db-03efd7c8e26b'::uuid, '2ebdd00d-c2fd-59a1-ae27-1efdd4c3c280'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There are both advantages and disadvantages of social media in the workplace. On one side, a company’s brand can become stronger. On the other side, there is a chance that the company’s brand will become weaker if an employee says something negative about the company.', FALSE, 0, NULL, NULL),
  ('f269570f-c0c5-5750-934b-ef5d1ca6c254'::uuid, '2ebdd00d-c2fd-59a1-ae27-1efdd4c3c280'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Because social media can stop employees working, some employers prevent them from using social media. However, these employers do not enjoy the benefits that social media can bring, such as an increase in customer demand for their product or a stronger brand.', FALSE, 1, NULL, NULL),
  ('8a39fbf7-95aa-5455-b8a2-e6f1b4656fb8'::uuid, '2ebdd00d-c2fd-59a1-ae27-1efdd4c3c280'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Social media can help employers to develop their businesses and find new staff. However, it is a problem when an employee criticises the company online or spends too much time using social media. To stop employees spending time on social media, employers must develop and challenge their staff.', TRUE, 2, NULL, NULL),
  ('7623a7b8-d7bd-5d63-8c77-edb8972eba5d'::uuid, '2ebdd00d-c2fd-59a1-ae27-1efdd4c3c280'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Employers only see the negative side of social media because they have too many problems with employees being rude or spending too much time using social media instead of working. Because this situation is challenging, it is easier for companies to stop the use of social media.', FALSE, 3, NULL, NULL),
  ('2aa56425-a1bb-5ca3-9599-469938db15ae'::uuid, '2ebe7fad-d281-5efa-a903-2d31b0ba8ca2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'provide', FALSE, 0, NULL, NULL),
