  ('1fc5c6e7-cc50-5c8a-9898-4228a9ba0823'::uuid, '2f812d04-d2bd-5a19-9153-9f5a4c345e14'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'priority', FALSE, 19, 4, NULL),
  ('0906117a-4399-5546-8d61-828b6e84c363'::uuid, '2f88715b-94c0-561a-9ea3-45b1b4da947c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This skill also allows you to start new projects that benefit the organization or your team.', FALSE, 0, NULL, NULL),
  ('6fc851d2-895a-50bd-adf5-14ee70fe4da3'::uuid, '2f88715b-94c0-561a-9ea3-45b1b4da947c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Self-sufficiency is the ability an individual has to work on their own and create solutions to challenges they encounter without asking others for help immediately.', FALSE, 1, NULL, NULL),
  ('366d5d54-25bb-5690-887c-3b5172118e72'::uuid, '2f88715b-94c0-561a-9ea3-45b1b4da947c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'You can use self-sufficiency in your role as a team leader because it can help you take responsibility for your actions if you make a mistake and it requires you to create a solution for it.', FALSE, 2, NULL, NULL),
  ('bf4faf06-9ed9-5009-aa15-29ef614d9f10'::uuid, '2f88715b-94c0-561a-9ea3-45b1b4da947c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This includes knowing when to ask for help when individuals can''t find a solution on their own.', FALSE, 3, NULL, NULL),
  ('88684329-02ff-5609-bf7d-3bb8f536d825'::uuid, '2f98e8c9-6e82-5adf-b8af-246a10dfbd3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'One Sunday Miss Brill puts on her fur and goes to the Public Gardens as usual.', FALSE, 0, NULL, NULL),
  ('89f02425-7c76-5ccd-91d4-0604a0b36a74'::uuid, '2f98e8c9-6e82-5adf-b8af-246a10dfbd3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Miss Brill is sad and depressed as she returns home.', FALSE, 1, NULL, NULL),
  ('dbbf5c04-639a-5696-836d-6dcfdc3abffe'::uuid, '2f98e8c9-6e82-5adf-b8af-246a10dfbd3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'That evening ends with her sudden realization that she is old and lonely, a realization brought to her by a conversation she overhears a comment on her unwelcome presence in their vicinity.', FALSE, 2, NULL, NULL),
  ('36258a34-2c53-59e6-890a-b72128d833f7'::uuid, '2f98e8c9-6e82-5adf-b8af-246a10dfbd3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Miss Brill is a regular visitor on Sundays to the Jardins Publiques (the Public Gardens) of a small French suburb.', FALSE, 3, NULL, NULL),
  ('2fa8fbd9-3c25-5cce-9995-d4bb4e708a61'::uuid, '2f98e8c9-6e82-5adf-b8af-246a10dfbd3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'She listens to the band playing, and enjoys contemplating the world as a great stage upon which actors perform.', FALSE, 4, NULL, NULL),
  ('e26d7f95-2ce0-50db-bcfa-e6e96f164b22'::uuid, '2fa837ba-8fe0-5d3e-a1bf-9c74de474a65'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These differences increasingly have spurred governments to adopt well-intentioned policies to improve the livelihoods of those in “places left behind.”', FALSE, 0, NULL, NULL),
  ('8f173f56-e77e-571d-9667-67c9c26ddd8a'::uuid, '2fa837ba-8fe0-5d3e-a1bf-9c74de474a65'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Such gaps largely reflect differences in productivity — the central driver of living standards across the world.', FALSE, 1, NULL, NULL),
  ('6ab47fb9-2454-5c57-91c2-4e9801fd95cc'::uuid, '2fa837ba-8fe0-5d3e-a1bf-9c74de474a65'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Yet the results often fall short of expectations, leaving billions of people farther behind while eroding public confidence in government initiatives.', FALSE, 2, NULL, NULL),
  ('dd1e9276-b873-502c-a941-9df6188590c7'::uuid, '2fa837ba-8fe0-5d3e-a1bf-9c74de474a65'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Living standards of people within developing economies vary greatly — to a much greater degree than in high-income economies.', FALSE, 3, NULL, NULL),
  ('730eda5c-ada8-5b41-8566-6571aefa2b17'::uuid, '2fa9a0dd-566a-5584-a260-78a95509890c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Excise taxes are levied on all products, while tariffs apply to government-made goods.', FALSE, 0, NULL, NULL),
  ('202e580e-9682-5723-b646-5abbeba6f892'::uuid, '2fa9a0dd-566a-5584-a260-78a95509890c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Excise taxes are levied on specifically identified commodities, while tariffs apply to all goods.', FALSE, 1, NULL, NULL),
  ('77415d16-9fba-54bd-b5e3-307344f6d4f6'::uuid, '2fa9a0dd-566a-5584-a260-78a95509890c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Excise taxes are levied on goods produced and consumed in one country, while tariffs apply to imports.', TRUE, 2, NULL, NULL),
  ('b4356e9a-016d-5c19-913e-4f6054200116'::uuid, '2fa9a0dd-566a-5584-a260-78a95509890c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Excise taxes are levied on goods to which sales tax does not apply, while tariffs only apply to goods With sales tax imposed.', FALSE, 3, NULL, NULL),
