  ('d1223ee7-05a0-5602-adc3-7214bbda447b'::uuid, '308ecaac-d40e-5391-80dc-8c2836171591'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Others study best in crowded, noisy rooms because the noise actually helps them concentrate.', FALSE, 0, NULL, NULL),
  ('535fc7e5-d81d-5a89-9e73-f89a34aa7367'::uuid, '308ecaac-d40e-5391-80dc-8c2836171591'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, one general rule for all students is that the television seems to be more of a distraction than music or other background noise, so leave the TV off when you are reading or studying. Also, don''t let yourself distracted by computer games, email, or internet surfing.', FALSE, 1, NULL, NULL),
  ('d951e5cc-ace7-52c5-ae4d-acf0e43f3526'::uuid, '308ecaac-d40e-5391-80dc-8c2836171591'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The point is, you should know the level of noise that is optimal for your own studying.', FALSE, 2, NULL, NULL),
  ('d7947fcf-0726-57d2-ba7c-6e14ec8da830'::uuid, '308ecaac-d40e-5391-80dc-8c2836171591'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Some students say that they need complete quiet to read and study.', FALSE, 3, NULL, NULL),
