  ('3ab817b1-c853-5b96-b27a-77519e76c3b3'::uuid, '30ca7c73-0930-50e7-a7d4-f1a78420fd67'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Furthermore, artists can now produce and share their music independently, without the need for traditional record labels.', FALSE, 1, NULL, NULL),
  ('e62d20ab-fa99-5621-9140-43c93e8e6121'::uuid, '30ca7c73-0930-50e7-a7d4-f1a78420fd67'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, this has also led to challenges in monetizing music due to the prevalence of online streaming and piracy.', FALSE, 2, NULL, NULL),
  ('103aba3c-030d-5469-a972-a2e4b2a780e8'::uuid, '30ca7c73-0930-50e7-a7d4-f1a78420fd67'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The digital era has revolutionized the way we create, distribute, and consume music.', FALSE, 3, NULL, NULL),
