  ('35a8f50e-d8df-5b13-abac-bd4c21634286'::uuid, '310bfcfd-6277-51af-8471-dfd315aacf1d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As a result, the environment is under increasing pressure from human activities such as deforestation, pollution, and climate change.', FALSE, 1, NULL, NULL),
