  ('4654bb74-d6e1-5e66-9dc3-d79a7398f8b0'::uuid, '31a0dc69-8939-5153-a42a-1826d971508c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In 1789, Englishman, William Jessup designed the first wagons with flanged wheels.', FALSE, 0, NULL, NULL),
  ('7cfe2cdc-cb3d-51a5-9793-2c70b1650455'::uuid, '31a0dc69-8939-5153-a42a-1826d971508c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These primitive railed roads consisted of wooden rails over which horse-drawn wagons or carts moved with greater ease than over dirt roads. Wagonways were the beginnings of modern railroads.', FALSE, 1, NULL, NULL),
  ('5825d117-5d02-51e6-8f2f-c9552a166cb3'::uuid, '31a0dc69-8939-5153-a42a-1826d971508c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Roads of rails called Wagonways were being used in Germany as early as 1550.', FALSE, 2, NULL, NULL),
  ('05b6a381-fcbb-58f9-90ad-0bef538a09b6'::uuid, '31a0dc69-8939-5153-a42a-1826d971508c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'By 1776, iron had replaced the wood in the rails and wheels on the carts.', FALSE, 3, NULL, NULL),
  ('4cff75bd-5f68-5997-b6b6-3e7972576478'::uuid, '31a0dc69-8939-5153-a42a-1826d971508c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The flange was a groove that allowed the wheels to better grip the rail, this was an important design that carried over to later locomotives.', FALSE, 4, NULL, NULL),
  ('a9ac923e-fc7b-59c9-b6d6-8cfb5517d436'::uuid, '31b74560-870b-514e-b780-e12383576817'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Chameleons are famous for their ability to change color, a form of mimicry.', FALSE, 0, NULL, NULL),
  ('1c82da39-94e1-5418-ac61-fc85a7b2a0b7'::uuid, '31b74560-870b-514e-b780-e12383576817'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Without intervention, the loss of habitat could lead to a decline in chameleon populations, thereby disrupting the ecological balance in their environments.', FALSE, 1, NULL, NULL),
  ('39be5188-8e9a-5af3-8241-822025901652'::uuid, '31b74560-870b-514e-b780-e12383576817'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This color change serves various functions, from camouflage to communication.', FALSE, 2, NULL, NULL),
  ('49179635-4910-5403-884b-e2d31de5748d'::uuid, '31b74560-870b-514e-b780-e12383576817'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Contrary to popular belief, their color change is not only for blending with the environment but also reflects their mood and health.', FALSE, 3, NULL, NULL),
  ('7e9f95dc-75c9-51d8-9a93-0a96662b8468'::uuid, '31b74560-870b-514e-b780-e12383576817'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, habitat loss is a major threat to chameleons.', FALSE, 4, NULL, NULL),
