  ('712e518f-0640-5bb7-8703-6b5a9001c488'::uuid, '31ea4500-d6d4-52cd-b78a-7948d3900732'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Playwrights come to their craft with different aesthetic sensibilities.', FALSE, 1, NULL, NULL),
