  ('70be6c61-9070-5cfc-86b2-0a574ecffc03'::uuid, '334bfdd8-54af-53f7-97e8-2fd8eb97a6f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Unless they are licensed or authorised to do so under the Poisons and Therapeutic Goods Regulation 1001, no one may supply these Schedule 1 substances.', FALSE, 0, NULL, NULL),
  ('9d77b7be-7fbc-5f5e-b681-5dee3986531b'::uuid, '334bfdd8-54af-53f7-97e8-2fd8eb97a6f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A person or company located in New South Wales may not supply by wholesales any substance which is for their therapeutic use and included in Schedule 2 of the Poisons List.', FALSE, 1, NULL, NULL),
  ('b7f8bd10-35d6-5a38-8026-faa1936eb825'::uuid, '334bfdd8-54af-53f7-97e8-2fd8eb97a6f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Additionally, wholesales have an obligation to ensure that the persons or companies they supply are licensed or authorized, to obtain, use, supply or possess the substance.', FALSE, 2, NULL, NULL),
  ('c445a1d5-6062-5e29-a166-7449f8403b3d'::uuid, '334bfdd8-54af-53f7-97e8-2fd8eb97a6f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Any breach of these regulations will result in immediate termination employment.', FALSE, 3, NULL, NULL),
  ('d4b18a50-3b1b-542b-bd59-477664ce6472'::uuid, '3367bdca-bfdb-5f23-b5db-90b95780a793'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The so-called ‘one chip’ challenge, in which students film themselves for TikTok eating a Paqui chip, marketed as the ‘world’s spiciest’, has sent students across the country to the school nurse’s office, and even to the hospital.', FALSE, 0, NULL, NULL),
  ('18da7311-6e2c-5b51-9327-ee27228224ea'::uuid, '3367bdca-bfdb-5f23-b5db-90b95780a793'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It’s just the latest in a string of viral challenges on the video platform, among the most popular apps for teenagers.', FALSE, 1, NULL, NULL),
  ('bdaed8b1-921f-58a5-839e-18cdbb5e3f06'::uuid, '3367bdca-bfdb-5f23-b5db-90b95780a793'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Others are more daredevil-oriented, such as holding your breath until you pass out.', FALSE, 2, NULL, NULL),
  ('5913286c-8fda-53b0-b48a-59baa0b45ca7'::uuid, '3367bdca-bfdb-5f23-b5db-90b95780a793'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Some challenges require kids to consume something gross and potentially dangerous, such as an entire spoonful of cinnamon, which can cause vomiting or nosebleeds.', FALSE, 3, NULL, NULL),
