  ('4c15f694-9adc-50f7-ad86-46f516ef1c4d'::uuid, '35b0af0b-70a2-5c48-a684-74234dd0d671'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'All New York areas are the same now.', FALSE, 4, NULL, NULL),
  ('20989595-03f7-5833-a0b3-8d88b37e8af6'::uuid, '35b870df-b1a0-52cb-87bd-1c14f7b4feac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A literary movement or epoch is a body of literary works (plays, novels, novellas, serialised stories, poems) composed during a set time period, or era.', FALSE, 0, NULL, NULL),
  ('9fb74133-83ef-53c7-ba5e-c5557937c0d5'::uuid, '35b870df-b1a0-52cb-87bd-1c14f7b4feac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This body of literary works is grouped together based on certain features, such as philosophy, aesthetic, school of thought, or its social, political and cultural influences.', FALSE, 1, NULL, NULL),
  ('cd162d91-4e14-5a21-8833-d0a6cc1094e6'::uuid, '35b870df-b1a0-52cb-87bd-1c14f7b4feac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But one way to get an overview is to break it down into literary movements.', FALSE, 2, NULL, NULL),
