  ('06c1be82-73aa-5943-a93c-81a3e04fbd84'::uuid, '36e264ab-1873-5979-ac32-931791b4f4cc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'removed', TRUE, 14, 3, NULL),
  ('671b9f79-04fc-54c6-be3e-c4a56c592c9a'::uuid, '36e264ab-1873-5979-ac32-931791b4f4cc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'reformed', FALSE, 15, 3, NULL),
  ('03dd93ca-7cf8-5258-9484-3fb4e656c908'::uuid, '36ecc40a-fdf2-57c1-8696-76ce76e3fee1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The ancient Romans, for example, laid out their streets mathematically many years previously, and this also produced a grid pattern.', FALSE, 0, NULL, NULL),
  ('ac4154c3-b7f3-5c01-8567-3e1dd2aa2dc7'::uuid, '36ecc40a-fdf2-57c1-8696-76ce76e3fee1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'If you look at how a US city is laid out on a map, you usually find a grid pattern of streets going from north to south and east to west, and they cross at a very precise 90 degree angle.', FALSE, 1, NULL, NULL),
  ('9d5e6cb2-83ca-59e9-91e1-0ca7d7ee296c'::uuid, '36ecc40a-fdf2-57c1-8696-76ce76e3fee1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This is not simply a case of an older, irregular pattern giving way to a later American invention, however.', FALSE, 2, NULL, NULL),
  ('ea115756-91a8-51c7-8f2e-c2ae9ae7608b'::uuid, '36ecc40a-fdf2-57c1-8696-76ce76e3fee1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In cities elsewhere, such as those in many European countries, streets follow a meandering pattern, following the rivers and natural landmarks.', FALSE, 3, NULL, NULL),
  ('625149f7-8fa0-550a-88dd-c7a2c194cb5e'::uuid, '36fa0341-12f0-557c-90f1-cf6e344318d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, the floor of the Atlantic is becoming fairly well known as a result of special surveys since 1920.', FALSE, 0, NULL, NULL),
  ('45524118-c4c1-5059-8ed5-a79135c8a133'::uuid, '36fa0341-12f0-557c-90f1-cf6e344318d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The topography of the ocean floors is none too well known, since in great areas the available soundings are hundreds or even thousands of miles apart.', FALSE, 1, NULL, NULL),
  ('01a42806-bfb3-56cd-b0f5-6b264f3c91be'::uuid, '36fa0341-12f0-557c-90f1-cf6e344318d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A broad, well-defined ridge-the Mid-Atlantic ridge-runs north and south between Africa and the two Americas.', FALSE, 2, NULL, NULL),
  ('06ad2a3f-f155-5c16-a8e2-153281694125'::uuid, '36fa0341-12f0-557c-90f1-cf6e344318d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Numerous other major irregularities diversify the Atlantic floor.', FALSE, 3, NULL, NULL),
  ('98f1d343-d2dd-5b12-8ac6-b8f6a33d914e'::uuid, '36fa0341-12f0-557c-90f1-cf6e344318d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Closely spaced soundings show that many parts of the oceanic floors are rugged as mountainous regions of the continents.', FALSE, 4, NULL, NULL),
  ('166c41f8-e135-5638-8314-94ed97d43aa3'::uuid, '37222822-aa18-5216-b3ec-6b30aa3a9df2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'the Chinese', FALSE, 0, NULL, NULL),
  ('c65590f0-08ae-5d75-a0dd-5396e3347735'::uuid, '37222822-aa18-5216-b3ec-6b30aa3a9df2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'the Greeks', FALSE, 1, NULL, NULL),
  ('94bca9cf-ca39-5945-bd1a-e30e7da69929'::uuid, '37222822-aa18-5216-b3ec-6b30aa3a9df2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'the Spanish', TRUE, 2, NULL, NULL),
