  ('d360216b-6c50-51ca-9fc8-4f3ab5cd3c33'::uuid, '372bf7c5-3292-5459-9f2c-8320d7f59b29'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'negativity', FALSE, 0, NULL, NULL),
  ('d4a982b4-b53c-58b9-bdb8-ad41da245069'::uuid, '372bf7c5-3292-5459-9f2c-8320d7f59b29'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'good', TRUE, 1, NULL, NULL),
  ('efaad244-37c2-52af-ac0d-cf22061b760c'::uuid, '372bf7c5-3292-5459-9f2c-8320d7f59b29'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'positivity', FALSE, 2, NULL, NULL),
  ('12f9a998-a0fa-5cd1-b74f-176f9baf4a3b'::uuid, '372bf7c5-3292-5459-9f2c-8320d7f59b29'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'purity', FALSE, 3, NULL, NULL),
  ('34c075da-fa48-56ce-b2fa-7e7804eb7235'::uuid, '3740ef19-ab2e-53cc-a6e8-059ba2f28231'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Compassion is one of these.', FALSE, 0, NULL, NULL),
  ('734c7e74-f2ab-572e-abed-8571c661c00b'::uuid, '3740ef19-ab2e-53cc-a6e8-059ba2f28231'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Although truth and justice may be the most powerful impulses to show moral courage, there are others.', FALSE, 1, NULL, NULL),
  ('6e69d441-8410-5428-a0d6-9280d904c498'::uuid, '3740ef19-ab2e-53cc-a6e8-059ba2f28231'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Tentatively it can be suggested that this is the main influence upon those who urge the abolition of capital punishment.', FALSE, 2, NULL, NULL);
INSERT INTO _pte_local_seed_options (public_id, question_public_id, created_at, updated_at, deleted, text, correct, order_index, blank_index, correct_gap_index) VALUES
  ('15cbccdd-b8df-50f9-aadc-29b37c951706'::uuid, '3740ef19-ab2e-53cc-a6e8-059ba2f28231'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It is recognition of compassion''s part that leads the upholders of capital punishment to accuse the abolitionists of sentimentality in being more sorry for the murderer than for his victim.', FALSE, 3, NULL, NULL),
  ('3a3ffb1e-8721-5ce1-a68d-d7e597a65eb1'::uuid, '376a61f9-6abd-5fb1-a7a8-9ed40cab3dfd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'First, there is the sensation of eating the food, which includes what it tastes like, what it smells like, and how it feels in your mouth.', FALSE, 0, NULL, NULL),
  ('2b1869b6-558e-52ef-bd6e-2487a215c2c9'::uuid, '376a61f9-6abd-5fb1-a7a8-9ed40cab3dfd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Steven Witherly is a food scientist who has been studying what makes certain foods more addictive than others.', FALSE, 1, NULL, NULL),
  ('043c649b-8847-555c-9be9-db43e82f5e01'::uuid, '376a61f9-6abd-5fb1-a7a8-9ed40cab3dfd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The second factor is the actual macronutrient makeup of the food.', FALSE, 2, NULL, NULL),
  ('e79bfd7e-2fcb-5eb9-8e3c-250f59706623'::uuid, '376a61f9-6abd-5fb1-a7a8-9ed40cab3dfd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'According to Witherly, when you eat tasty food, there are two factors that make the experience pleasurable.', FALSE, 3, NULL, NULL),
  ('6f318c3c-9ffb-5804-a3bd-1e66f7f3cde2'::uuid, '37807d02-bb0e-5202-90bc-9c4952ebea66'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'running', FALSE, 0, NULL, NULL),
