  ('6ddea3c2-eefd-5bd9-b9ec-f7354df9a71e'::uuid, '3823ac0c-bc95-5bdf-8e7b-6b8258728809'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'foster', TRUE, 6, NULL, 1),
  ('02286670-2105-59c1-b035-6883bac94bf2'::uuid, '3827d7f9-b410-5816-974d-cf7d02804788'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In many ways, it’s similar to an autobiography.', FALSE, 0, NULL, NULL),
  ('f6e0f00f-a28c-505f-b0c5-82c9e45ac294'::uuid, '3827d7f9-b410-5816-974d-cf7d02804788'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, there is a key difference that define memoirs as a subgenre.', FALSE, 1, NULL, NULL),
  ('87d4b9fd-91e7-57c1-92ef-e5197be81c8d'::uuid, '3827d7f9-b410-5816-974d-cf7d02804788'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A memoir typically narrows its focus to a short but significant period of the author’s life, whereas an autobiography typically spans the entire life of the author.', FALSE, 2, NULL, NULL),
  ('adfea58b-91fe-5d9e-ba9a-08994fa56c68'::uuid, '3827d7f9-b410-5816-974d-cf7d02804788'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A memoir is a narrative about a significant part of the author’s life written from their own perspective or their personal memories of an event.', FALSE, 3, NULL, NULL),
  ('b4c553b9-1d9d-54c5-8302-7b4355a516c6'::uuid, '384bdfeb-c898-5b70-97fb-e46a1fbef73c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This invention changed everything from travel to shipping.', FALSE, 0, NULL, NULL),
  ('c9ce58aa-8741-5aff-99b1-c576a535982c'::uuid, '384bdfeb-c898-5b70-97fb-e46a1fbef73c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In 1903 the Wrights demonstrated that an airplane could sustain flight under the control of a pilot, a feat that had never before been accomplished.', FALSE, 1, NULL, NULL),
  ('c64ad5b2-7b9d-5ab8-a81b-08fb037b1000'::uuid, '384bdfeb-c898-5b70-97fb-e46a1fbef73c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Without the Wright flyer, we wouldn’t have destination weddings or last-minute shipping for Christmas.', FALSE, 2, NULL, NULL),
  ('52234b85-242a-52ed-9315-114f5a22f8c6'::uuid, '384bdfeb-c898-5b70-97fb-e46a1fbef73c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A list of the greatest inventions would simply be incomplete without mention of the Wright brothers’ historic flight.', FALSE, 3, NULL, NULL),
  ('3a38bf1f-a551-5269-907c-2bfbe69d8a25'::uuid, '386a9172-3b7e-5e52-9f71-af899fd33f53'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Experts especially journalists, inevitably find it difficult to be objective because of their culture background.', FALSE, 0, NULL, NULL),
  ('077905ba-1391-5bc8-9d44-a76d8ad4f013'::uuid, '386a9172-3b7e-5e52-9f71-af899fd33f53'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Some aspects are not included in the reporting.', FALSE, 1, NULL, NULL),
  ('4750c76a-81a1-5f46-9c9a-fe0889d4f183'::uuid, '386a9172-3b7e-5e52-9f71-af899fd33f53'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, including every aspect of an issue is as easy as calling for every candidate to participate in presidential debate.', FALSE, 2, NULL, NULL),
  ('beb220f4-009f-5dbc-89ca-7881846a6800'::uuid, '386a9172-3b7e-5e52-9f71-af899fd33f53'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Journalists tried their best not to be biased.', FALSE, 3, NULL, NULL),
  ('00de0abf-4b44-5c29-8754-df6187589fda'::uuid, '388c5919-f30f-5a81-8465-5260b7653f12'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Customer feedback is invaluable for refining sales strategies.', FALSE, 0, NULL, NULL),
  ('cb1c5306-87f9-5ccf-a415-84e1d415d468'::uuid, '388c5919-f30f-5a81-8465-5260b7653f12'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'On the other hand, negative feedback, if not managed properly, can harm a company''s reputation and customer trust.', FALSE, 1, NULL, NULL),
  ('13603e62-bd72-5169-af8a-de8cf6e3672e'::uuid, '388c5919-f30f-5a81-8465-5260b7653f12'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'On the one hand, actively seeking and acting upon customer feedback can lead to enhanced product offerings and services.', FALSE, 2, NULL, NULL),
  ('fe013f64-f339-5d86-bff5-ba9a8088b9fd'::uuid, '388c5919-f30f-5a81-8465-5260b7653f12'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It offers insights into customer satisfaction and areas needing improvement.', FALSE, 3, NULL, NULL),
  ('706c0cd2-510c-5f99-a5c9-f75076b940ce'::uuid, '38937344-3e1b-58fd-bc7f-13cfa85fd717'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They force people to stay at home for a long time.', FALSE, 0, NULL, NULL),
  ('5ac8f445-7b69-553b-97ee-659efae5edd0'::uuid, '38937344-3e1b-58fd-bc7f-13cfa85fd717'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'People tend to become less sociable.', TRUE, 1, NULL, NULL),
  ('c055a6b0-dbdf-5ca8-9cbc-441823b06485'::uuid, '38937344-3e1b-58fd-bc7f-13cfa85fd717'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They both make people feel less lonely and less awkward.', FALSE, 2, NULL, NULL),
  ('46cbb9e0-7fad-5cc3-8f16-6a7fad89105e'::uuid, '38937344-3e1b-58fd-bc7f-13cfa85fd717'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Both of them are expensive and compulsory.', FALSE, 3, NULL, NULL),
  ('d4e27f57-b9c0-5413-b91c-7e2254c0a98f'::uuid, '38a8fad5-7667-52db-9e62-bba209907c50'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Additionally, Gothic cathedrals often feature intricate stained glass.', FALSE, 0, NULL, NULL),
  ('5edf7215-6479-5e01-a08d-3c666554a060'::uuid, '38a8fad5-7667-52db-9e62-bba209907c50'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Characterized by pointed arches, ribbed vaults, and flying buttresses, it allows for taller structures and larger windows.', FALSE, 1, NULL, NULL),
  ('0eb043a6-a4d8-5ca7-a2dc-0b97405a6ff1'::uuid, '38a8fad5-7667-52db-9e62-bba209907c50'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Gothic architecture, originating in the 12th century, is renowned for its verticality and lightness.', FALSE, 2, NULL, NULL),
  ('5bd35bc1-cc81-5898-9072-a9673089482c'::uuid, '38a8fad5-7667-52db-9e62-bba209907c50'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, the complexity of this style makes it resource-intensive to construct and maintain.', FALSE, 3, NULL, NULL),
  ('450c94b4-fcf4-5f8d-b6f3-ce7cdf26665b'::uuid, '38c61342-712b-5bcd-827a-55fec2b67ecf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The American mink has been present in Iceland since the 1930''s and despite heavy hunting since 1939 the species has become well established.', FALSE, 0, NULL, NULL),
  ('01a14d11-f903-59f9-901a-91fea99c6e6a'::uuid, '38c61342-712b-5bcd-827a-55fec2b67ecf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Direct competition between these species appears to be minimal although the arctic fox will sometimes chase mink and disturb them while foraging.', FALSE, 1, NULL, NULL),
  ('73d7138e-0d30-5ac3-9e7b-96da4ed93cf2'::uuid, '38c61342-712b-5bcd-827a-55fec2b67ecf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Iceland is therefore an ideal place to study undisturbed feeding behaviour and ecology of mink.', FALSE, 2, NULL, NULL),
  ('65608848-4927-57e9-ae66-b8006c79327b'::uuid, '38c61342-712b-5bcd-827a-55fec2b67ecf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The ecosystem in Iceland is simpler than in other areas where mink are found; the only other mammalian predator is the arctic fox.', FALSE, 3, NULL, NULL),
  ('6e335e2b-bf46-5b47-904f-e8855a7a1387'::uuid, '38cf15c2-ff1b-5000-b73d-7442b1cf200d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'When you really smile, the muscles around your eyes move 10 percent less than a fake one.', FALSE, 0, NULL, NULL),
  ('33ce6d81-c634-5b0a-b35a-8da53cf8b1b3'::uuid, '38cf15c2-ff1b-5000-b73d-7442b1cf200d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Software can recognize people''s facial expressions to determine whether people pretend to smile.', TRUE, 1, NULL, NULL),
  ('9d1e2695-8d0d-537a-8530-653e2d5ba792'::uuid, '38cf15c2-ff1b-5000-b73d-7442b1cf200d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The program can track and identify specific details around the eyes, cheeks and mouth.', TRUE, 2, NULL, NULL),
  ('dee22a0f-44ea-56fb-aadf-fd41aa49b06f'::uuid, '38cf15c2-ff1b-5000-b73d-7442b1cf200d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It''s hard for the naked eye to tell whether people really laugh or pretend to laugh.', FALSE, 3, NULL, NULL),
  ('91f54c92-ebbb-568d-8adb-19450c9c2325'::uuid, '38cf15c2-ff1b-5000-b73d-7442b1cf200d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Sometimes people smile because they are polite rather than happy.', FALSE, 4, NULL, NULL),
