  ('c1387050-7e5a-5d5b-8006-2d9d2679840e'::uuid, '3a3206f9-aa85-504c-9d65-d5395b539afe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The most famous river that flows north is also the longest river in the world: the Nile, which passes through 11 different countries in northeastern Africa.', FALSE, 1, NULL, NULL),
  ('74d95c46-0fbc-5526-bfc8-9edbbef52cc3'::uuid, '3a3206f9-aa85-504c-9d65-d5395b539afe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Then these two tributaries meet in Sudan, near the capital city of Khartoum, and then flow north through Egypt to the Mediterranean Sea.', FALSE, 2, NULL, NULL),
  ('c5eb8c33-6c07-5445-8ff5-dd90d04a2943'::uuid, '3a3206f9-aa85-504c-9d65-d5395b539afe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Its principal tributaries are the White Nile and the Blue Nile.', FALSE, 3, NULL, NULL),
  ('16b565f1-0c80-566e-ad01-d71abdce94bf'::uuid, '3a38c0ca-0def-53ea-bea6-fa62501f2562'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Marek and colleagues'' new paper, published Wednesday by the journal Zookeys, offers the first scientific description of Illacme plenipes, including insights into its strange anatomy.', FALSE, 0, NULL, NULL),
  ('ffed06a1-e39c-5980-8248-c7ab196f39c9'::uuid, '3a38c0ca-0def-53ea-bea6-fa62501f2562'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The leggiest creature on Earth lives in California: it''s a three-centimeter-long (1.2 inch) millipede with 750 legs.', FALSE, 1, NULL, NULL),
  ('82d379a6-e8c5-591e-875a-3d8bf1050296'::uuid, '3a38c0ca-0def-53ea-bea6-fa62501f2562'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For one thing, females have to up to 750 legs and males have more than 550.', FALSE, 2, NULL, NULL),
  ('5d8c274d-ae7d-5d89-8df2-52570e4e8891'::uuid, '3a38c0ca-0def-53ea-bea6-fa62501f2562'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Then University of Arizona entomologist Paul Marek spied one near Silicon Valley.', FALSE, 3, NULL, NULL),
  ('f271d45f-d63e-5fa8-a66b-9ecc3f330d81'::uuid, '3a38c0ca-0def-53ea-bea6-fa62501f2562'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'First seen by government scientists in 1928, Illacme plenipes, ''the acme of plentiful legs'', keeps such a low profile that for the rest of the 20th century the species was thought to be extinct.', FALSE, 4, NULL, NULL),
