  ('00738735-b63f-548e-bdc1-d0b287f8797d'::uuid, '3a947969-7203-5c1d-b114-8c7d68aa84b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Most wear a common uniform: white shirt, white pants, red neck scarf, and red belt or waist scarf.', FALSE, 0, NULL, NULL),
  ('21efb15a-6900-5583-b694-aa179664826c'::uuid, '3a947969-7203-5c1d-b114-8c7d68aa84b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Every morning in Pamplona at 8 a.m. during the Festival of San Fermín, six bulls and at least six steers are released into the streets and corralled into the city’s bull ring.', FALSE, 1, NULL, NULL),
  ('0a16eef0-6a1f-51a3-9d26-e08a288f46b2'::uuid, '3a947969-7203-5c1d-b114-8c7d68aa84b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The white of the uniforms is thought to reference the aprons of the medieval butchers, and the red is worn in honor of San Fermín.', FALSE, 2, NULL, NULL),
  ('74eee6db-a3aa-5c15-84f9-096863a9a61a'::uuid, '3a947969-7203-5c1d-b114-8c7d68aa84b2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This running of the bulls, called the encierro, takes less than five minutes.', FALSE, 3, NULL, NULL),
  ('6eb5a83c-ca9b-5c15-9072-3d00953274bf'::uuid, '3a9522e6-ce71-5bb8-b00a-8200fa883edb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Pancake ice is formed under deep sea, which only requires extremely cold temperature itself. The aim of the research is mere scientific experiments, and does not have serve practical purposes.', FALSE, 0, NULL, NULL),
  ('5391ef48-7ddc-5ae4-a4f4-223f0c956cef'::uuid, '3a9522e6-ce71-5bb8-b00a-8200fa883edb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Pancake ice exists in a warm river, which requires warm water, rain or snow. The aim of the research is to forecast weather in those river regions.', FALSE, 1, NULL, NULL),
  ('c9b2025d-f1de-5ee3-a693-d93813b86899'::uuid, '3a9522e6-ce71-5bb8-b00a-8200fa883edb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Pancake ice is formed by extremely cold temperature and waves, which needs a wide collection of frequency. The aim of the research is to give the meteorological modelers a better understanding of this phenomenon through a special lab.', TRUE, 2, NULL, NULL),
  ('73f26908-6fad-57d0-b660-045ee0bde7fa'::uuid, '3a9522e6-ce71-5bb8-b00a-8200fa883edb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Pancake ice forms in shallow ponds with mild temps and still water. The research aims to study its beauty, not for any scientific or practical use.', FALSE, 3, NULL, NULL),
