  ('bffb3b3f-6dc4-5343-92fb-6bb67809b985'::uuid, '3b9a4ce8-f21c-5748-a443-7ab0706bd5bf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'When writing, you need to provide evidence to back up your ideas.', FALSE, 1, NULL, NULL),
  ('c409840b-a909-5799-ba96-25bcd03f7616'::uuid, '3b9a4ce8-f21c-5748-a443-7ab0706bd5bf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But sometimes, you need to use the source''s exact words.', FALSE, 2, NULL, NULL),
  ('4bc6ac55-9cc4-5c61-9d0d-15dc21987ab6'::uuid, '3b9a4ce8-f21c-5748-a443-7ab0706bd5bf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Direct quotes are important for giving evidence and meaning to your ideas.', FALSE, 3, NULL, NULL),
