  ('112f00cc-7fa8-5e82-a8eb-062c3714eb81'::uuid, '3baf99b0-aaba-5f89-bb0e-9c1a479dc6d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'One of the recommendations was to send him to his relatives who were willing to take care until he was 18. This resulted in a positive outcome in academic achievement.', FALSE, 0, NULL, NULL),
  ('ec984271-6e6a-5c62-92fb-8bd0d878c128'::uuid, '3baf99b0-aaba-5f89-bb0e-9c1a479dc6d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'He went to two schools while he was in foster care and one was Barr Beacon School, formerly Barr Beacon Language College, is a mixed comprehensive for foster children.', FALSE, 1, NULL, NULL),
  ('ceb897b4-bbe4-5169-8678-960370ff78bb'::uuid, '3baf99b0-aaba-5f89-bb0e-9c1a479dc6d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'According to the Australian Institute of Family Studies in 2014 a 11-year-old boy was unable to live with his family, due to child abuse.', FALSE, 2, NULL, NULL),
  ('b417ce27-8438-5a59-b4a5-d2bf71558eaf'::uuid, '3baf99b0-aaba-5f89-bb0e-9c1a479dc6d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Children like him involved with child protective services were shown to have consistently low average math and reading standardized test scores.', FALSE, 3, NULL, NULL),
  ('65f7e6ea-c001-53bd-8d8e-9ea30da130ec'::uuid, '3baf99b0-aaba-5f89-bb0e-9c1a479dc6d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But upbringing in the foster care system means he has no-one to help him. It''s not his fault, yet he is being penalized for something he can''t change.', FALSE, 4, NULL, NULL),
