  ('8aae63cf-ec84-526b-83cb-5269231e837b'::uuid, '3c27461c-cefd-5249-9f3b-db57c872cc89'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A new project will look at the problems of housing in London. Because housing is too expensive in the city, people have had to move into garages. Researchers hope their new project will solve this problem by getting people into better homes and also back in work.', FALSE, 0, NULL, NULL),
  ('36155084-41c5-5448-813a-45b30cd2bc4d'::uuid, '3c27461c-cefd-5249-9f3b-db57c872cc89'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A new project intends to use garages to provide housing for the homeless in London. Although small, there will be areas outside the home to prepare food and clean clothes. The houses will provide both accommodation and training for the people living there.', TRUE, 1, NULL, NULL),
  ('14894283-3eb2-508d-9969-b44af24886bf'::uuid, '3c27461c-cefd-5249-9f3b-db57c872cc89'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A recent project will aim to give homeless people education and training in building houses and garages for key workers in the most expensive neighbourhoods of London. The houses will help people get to work more quickly because of their central location.', FALSE, 2, NULL, NULL),
  ('a30f48f1-d73f-5807-9a27-0261e156b3d1'::uuid, '3c27461c-cefd-5249-9f3b-db57c872cc89'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A recent project will aim to put homeless people into their own homes. They will each have their own bedroom, shower room, kitchen and garage and will need to build the homes themselves. Having your own space is generally better than sharing a larger home with others.', FALSE, 3, NULL, NULL),
  ('a0de678f-0583-5dba-a999-73957679699a'::uuid, '3c4411d3-70bb-5327-a668-6ab03734f656'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'universe', TRUE, 0, 0, NULL),
