  ('7b33ecf1-5d0c-585f-91a1-2df37ca6f3a8'::uuid, '3caa14a4-b44e-5072-b3c7-9d7a1b6c118d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The mayors of towns and the local governments are responsible for passing zoning laws. They regulate how people use the land in certain parts of the open land.', FALSE, 0, NULL, NULL),
