  ('23f9f441-c400-55a6-b693-cc500835e576'::uuid, '3d78aba3-3555-575f-9594-18d10794ef10'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The extremophiles that microbiologist Rick Cavicchioli and his team study love life extremely cold.', FALSE, 1, NULL, NULL),
