  ('6da35898-fac9-5837-aa5d-7a5337d6a979'::uuid, '3d82aff0-8729-55ff-93db-1cb1ad4c5197'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Long ago, long before Belgium had a railway, people''s mobility depended on the power of their own two feet.', FALSE, 0, NULL, NULL),
  ('9fd484e2-7f55-536f-9659-42f4e7fb4a98'::uuid, '3d82aff0-8729-55ff-93db-1cb1ad4c5197'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Those who were wealthy could afford a horse and carriage or travelled by stagecoach.', FALSE, 1, NULL, NULL),
