  ('aa81ec48-c85c-52ee-af17-577546ecfa8c'::uuid, '3dc97480-37e4-54c4-bc18-fd1114ca3408'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'belonging to', FALSE, 19, 4, NULL),
  ('55ff9482-b55f-5057-b90a-02d3a441c20c'::uuid, '3dcf4928-b90d-5dac-a80a-e7e5eba513e3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Organic compounds include all living organisms, boil at lower temperatures, and bond easily with other elements. As for inorganic compounds, they are more common than organic compounds.', FALSE, 0, NULL, NULL),
  ('9f6c47ae-fab4-588c-a79e-2d98a4b8fbcf'::uuid, '3dcf4928-b90d-5dac-a80a-e7e5eba513e3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Because carbon bonds easily with other elements, there are more carbon compounds than non-carbon compounds. There are more than ten million carbon compounds, which is ten times the number of inorganic compounds.', FALSE, 1, NULL, NULL),
  ('99eeef27-bddd-5c73-8e94-6bef831d8433'::uuid, '3dcf4928-b90d-5dac-a80a-e7e5eba513e3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A compound is made when two or more elements unite and there are two main branches of chemical compounds: organic and inorganic compounds. There are five differences between organic and inorganic compounds.', TRUE, 2, NULL, NULL),
  ('d495399b-5807-53e6-909e-15033f415005'::uuid, '3dd7b911-419e-5fcb-9af9-578df13a4d25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'time', TRUE, 0, NULL, 2),
