  ('1619ce1f-4a97-537c-8717-be323481ead6'::uuid, '3dfdcd90-2781-5382-b1d5-5b734089e97e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Its name comes from being a centre of activity.', FALSE, 0, NULL, NULL),
  ('88da0646-f619-524a-bcfc-a41eb93d4b14'::uuid, '3dfdcd90-2781-5382-b1d5-5b734089e97e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Its architect saw the project through to completion.', FALSE, 1, NULL, NULL),
  ('1123e3f8-e519-5f0a-bd9f-79c3e9f30c99'::uuid, '3dfdcd90-2781-5382-b1d5-5b734089e97e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It used to be a symbol of national pride for N ew Zealand.', FALSE, 2, NULL, NULL),
  ('7736c7c2-5930-5bc0-9e08-50bccb3e7559'::uuid, '3dfdcd90-2781-5382-b1d5-5b734089e97e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It has come back into favour in recent years.', TRUE, 3, NULL, NULL),
  ('e85b1baa-285f-5be5-884a-ebfcc980011f'::uuid, '3dff0762-0445-57b9-8e52-4e1b351f0eb4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Japanese companies emphasize the importance of the success of a team as a whole, so many employees in Japan work overtime. This, however, decreases their productivity, and even results in many deaths caused by overwork each year.', TRUE, 0, NULL, NULL),
  ('5229317e-ac22-55e9-b6e5-327d5c9099e4'::uuid, '3dff0762-0445-57b9-8e52-4e1b351f0eb4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'63% of Japanese feel guilty to take a paid vacation, so they often choose not to take the vacation, and instead work overtime. An employee in the firm Dentsu unfortunately died when overworking, before the company’s CEO resigned because of guilt about her death.', FALSE, 1, NULL, NULL),
  ('5cd5ffa8-2901-53dd-a931-e36a19538fc0'::uuid, '3dff0762-0445-57b9-8e52-4e1b351f0eb4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The advertising firm Dentsu has been reported to force its employees to work overtime without any pay, which resulted in the death of one of its staff. The company’s CEO then came up with new policies to turn off the lights in the office at 10pm every night.', FALSE, 2, NULL, NULL),
  ('65b269d8-a346-5eef-bb0d-5c4aec0c1279'::uuid, '3dff0762-0445-57b9-8e52-4e1b351f0eb4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Although long hours don’t necessarily mean high productivity, Japanese companies still encourage their employees to work overtime. Thus, people often get a higher pay in Japan, and governments provide great welfare to make sure they can work in a healthy condition.', FALSE, 3, NULL, NULL),
  ('5a8737cf-7193-5aca-a3a4-cb53768c045e'::uuid, '3e021d2c-8b24-5967-ab4e-0ce27f6500a5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'shipment', TRUE, 0, NULL, 1),
  ('d03241b1-d959-55dc-ae99-ae644e77ab1e'::uuid, '3e021d2c-8b24-5967-ab4e-0ce27f6500a5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'calendars', TRUE, 1, NULL, 2);
