  ('06b491ca-0eb9-50bc-a1e2-4411df7102c1'::uuid, '3e0ff8d9-37f2-5e7f-a85b-9d75063871c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Space factor is related to the space around each bead, and the greater disorder indicates a higher possibility of avalanche.', TRUE, 0, NULL, NULL),
  ('9aef37c7-6dc6-5730-abc6-d1b83b97c09b'::uuid, '3e0ff8d9-37f2-5e7f-a85b-9d75063871c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The greater the disorder around a bead, the less likely an avalanche was.', FALSE, 1, NULL, NULL),
  ('d85e9dd8-d895-5749-84a1-41babf83ad6c'::uuid, '3e0ff8d9-37f2-5e7f-a85b-9d75063871c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Internal disorder analysis will lead to a more successful model.', TRUE, 2, NULL, NULL),
  ('66b0caf0-34ac-527d-8fe7-cb3f4c3c4fd4'::uuid, '3e0ff8d9-37f2-5e7f-a85b-9d75063871c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They could 100% accurately predict an extra-large avalanche based on the change in space factor of a bead.', FALSE, 3, NULL, NULL),
  ('0e3571ba-4a16-5cf8-8678-54fdf81ac3c0'::uuid, '3e0ff8d9-37f2-5e7f-a85b-9d75063871c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Forecasting earthquakes is easier than predicting avalanche.', FALSE, 4, NULL, NULL),
  ('11d1e4f9-eb34-5d9c-a280-70ce48ee6582'::uuid, '3e136d59-bb39-5b7a-8ed9-6d465b842500'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, excessive consumption of red meat has been linked to various health issues, such as heart disease and certain cancers.', FALSE, 0, NULL, NULL),
