  ('ca0c5114-3045-5df6-8300-3cfc1b696203'::uuid, '3e366a97-6b95-5e55-933f-6dd1003d26db'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Because people don''t know enough about circulating water.', FALSE, 1, NULL, NULL),
