  ('9687368b-f5ef-5fc0-9770-d931431769dd'::uuid, '3eb45f28-e6b3-50e9-b83b-1faaa3e4622a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The practice involves focusing on the present moment, acknowledging thoughts and feelings without judgment, and cultivating a sense of calm and awareness.', FALSE, 0, NULL, NULL),
  ('37e6d29f-3a39-59ef-a989-18197c84e23e'::uuid, '3eb45f28-e6b3-50e9-b83b-1faaa3e4622a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Many people find that incorporating mindfulness into their daily routines helps reduce stress and anxiety.', FALSE, 1, NULL, NULL),
  ('063ded78-8851-5963-a929-193cc88c6292'::uuid, '3eb45f28-e6b3-50e9-b83b-1faaa3e4622a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Mindfulness meditation has its roots in ancient Buddhist traditions and has gained popularity in Western cultures as a way to improve well-being.', FALSE, 2, NULL, NULL),
  ('0ee24dbd-287d-588a-8de1-d562a02360f4'::uuid, '3eb45f28-e6b3-50e9-b83b-1faaa3e4622a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In recent years, research has shown that mindfulness meditation can have a positive impact on mental health.', FALSE, 3, NULL, NULL),
  ('b191dd03-9921-5c28-ae5c-c371c2326394'::uuid, '3ed0e0c9-a1ea-598d-b8c7-eb5853139ff1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But LiDARs, aka light detection and ranging systems, do the important work of sensing and helping cars avoid obstacles, whether that''s a fallen tree, a drunk driver, or a child running out into the road.', FALSE, 0, NULL, NULL),
