  ('f540a4bb-6bae-524a-99a9-1e9b9348414a'::uuid, '3ed0e0c9-a1ea-598d-b8c7-eb5853139ff1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Cameras help autonomous vehicles read street signs and the color of traffic lights.', FALSE, 2, NULL, NULL),
