  ('c2e46401-3a3d-5792-8ffa-a985ee2add6d'::uuid, '3f66e0c0-7c6b-569f-b6fe-ef3044f5b276'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In Chinese culture, calligraphy is considered one of the highest forms of art.', FALSE, 1, NULL, NULL),
