  ('c0e9cbc8-0992-5c11-b8a9-5ae963731c94'::uuid, '3f85b87e-8a5e-5413-ad30-a9071371135e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Early in 1938, Mario de Andrade, the municipal secretary of culture here, dispatched a four- member Folklore Research Mission to the northeastern hinterlands of Brazil on a similar mission.', FALSE, 1, NULL, NULL),
  ('faf3733f-1a34-5c0f-b090-ea603de6f93b'::uuid, '3f85b87e-8a5e-5413-ad30-a9071371135e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They recorded whoever and whatever seemed to be interesting: piano carriers, cowboys, beggars, voodoo priests, quarry workers, fishermen, dance troupes and even children at play.', FALSE, 2, NULL, NULL),
  ('329b342f-5347-5416-84f5-e9fa5c851543'::uuid, '3f85b87e-8a5e-5413-ad30-a9071371135e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But the Brazilian mission’s collection ended up languishing in vaults here.', FALSE, 3, NULL, NULL),
