  ('2791ffab-dae3-5fc1-81db-ad4d002d4e26'::uuid, '403e447f-1074-5a54-913f-e12326d50980'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Good first paragraphs include an eye-catching hook to start things off, an overview of the topic, and a statement of your main point.', FALSE, 0, NULL, NULL),
  ('5602991e-a4aa-56b7-9542-dcf457bc8957'::uuid, '403e447f-1074-5a54-913f-e12326d50980'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'You can do this with a great first paragraph, also known as the introductory paragraph.', FALSE, 1, NULL, NULL),
  ('39de2b56-6781-5513-ac2c-ede2cba09f1e'::uuid, '403e447f-1074-5a54-913f-e12326d50980'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It sets up the argument and prepares the reader for what you will be writing about.', FALSE, 2, NULL, NULL),
