  ('e0bee886-8e4b-508e-9768-a374c58b1683'::uuid, '41048cc6-423b-5080-a7f8-09b8f0db18fc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'reckoned on', FALSE, 15, 3, NULL),
  ('477bf3a4-3b6e-5e85-a77e-490eb2451f9f'::uuid, '4105af62-e050-5cd2-b660-92cda4d13343'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Their society was ruled by pharaohs, considered both kings and gods.', FALSE, 0, NULL, NULL),
  ('86912a92-ae1c-54c6-96f5-92a59b6e7372'::uuid, '4105af62-e050-5cd2-b660-92cda4d13343'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It is renowned for its monumental architecture, including pyramids, temples, and tombs.', FALSE, 1, NULL, NULL),
  ('a71251e8-c684-5ccb-826a-c0bb6bd76000'::uuid, '4105af62-e050-5cd2-b660-92cda4d13343'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Egyptians made significant advances in writing, medicine, and mathematics.', FALSE, 2, NULL, NULL),
  ('839fa3b8-cccf-5292-9c5d-279cbec2d28b'::uuid, '4105af62-e050-5cd2-b660-92cda4d13343'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Ancient Egypt, one of the world''s earliest civilizations, flourished along the Nile River for thousands of years.', FALSE, 3, NULL, NULL),
  ('9a78def3-d9f5-5745-9cbe-9fc00752f8b4'::uuid, '4115b153-cf6a-5e73-9640-9d5f5a6e1422'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In some countries where racial prejudice is acute, violence has so come to be taken for granted as a means of solving differences, that it is not even questioned.', FALSE, 0, NULL, NULL),
  ('de9ef778-ec0b-5a74-ad2e-30041f7e8697'::uuid, '4115b153-cf6a-5e73-9640-9d5f5a6e1422'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There are countries where the white man imposes his rule by brute force; there are countries where the black man protests by setting fire to cities and by looting and pillaging.', FALSE, 1, NULL, NULL),
  ('3153b995-6896-5bb0-b3c4-ea4c212a2ed1'::uuid, '4115b153-cf6a-5e73-9640-9d5f5a6e1422'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'We may wear collars and ties instead of war-paint, but our instincts remain basically unchanged.', FALSE, 2, NULL, NULL),
  ('84a3d0ae-e8cd-594d-918d-d7a4f8163a59'::uuid, '4115b153-cf6a-5e73-9640-9d5f5a6e1422'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Important people on both sides, who would in other respects appear to be reasonable men, get up and calmly argue in favor of violence – as if it were a legitimate solution, like any other.', FALSE, 3, NULL, NULL),
  ('377e432f-c14a-5d95-a2b7-82d4a3eb4add'::uuid, '4115b153-cf6a-5e73-9640-9d5f5a6e1422'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'What is really frightening, what really fills you with despair, is the realization that when it comes to the crunch, we have made no actual progress at all.', FALSE, 4, NULL, NULL),
  ('c64692d4-4155-5db0-9fc8-8240368c0a26'::uuid, '414ee598-23df-51ea-bb65-5cc84e8bafaf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For any conical mountain on the Earth, its height is limited by various factors. The factors include the Earth’s mantle, collision of tectonic plates and erosion, so the tallest mountains are not likely to grow much higher.', TRUE, 0, NULL, NULL),
  ('6ca45d74-e384-5512-9e23-bd742ec8b84d'::uuid, '414ee598-23df-51ea-bb65-5cc84e8bafaf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Geologists are trying to build up a mountain that stretches between New York and Chicago, which will soar over 45km. This has been warned by experts that the support of such mountain may be damaged by winds and glaciers.', FALSE, 1, NULL, NULL),
  ('d52d0323-7105-55e4-bdb6-a85522894ca5'::uuid, '414ee598-23df-51ea-bb65-5cc84e8bafaf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Earth''s crust is made up of continental plates that float in the rock of its mantle. This can result in earthquakes, which may force the highest mountains to collapse, according to a research.', FALSE, 2, NULL, NULL),
  ('8acddc92-99f2-5e16-94ed-5fbb0f92fb10'::uuid, '414ee598-23df-51ea-bb65-5cc84e8bafaf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Mount Everest may grow in the future, because it won’t sink lower into the Earth''s hot interior like other mountains do. Another reason is that it hasn’t reached the height limit of 15km yet.', FALSE, 3, NULL, NULL),
  ('80a51c8d-9306-5c36-8d13-f668329b079a'::uuid, '415659aa-bae5-5815-bb21-84953c20a62a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'other', FALSE, 0, 0, NULL),
