  ('99159c5a-9945-5e94-86a1-94ebdc653a89'::uuid, '41806bfe-c579-590d-90d1-6de840fd3212'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Other injury-related killers include drowning, falls, burns and poisoning.', FALSE, 0, NULL, NULL),
  ('07bf2417-004f-516b-a6db-6f75562dcce4'::uuid, '41806bfe-c579-590d-90d1-6de840fd3212'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For example, in Spain, setting the default speed limit for cities at 30 kilometers per hour, is improving road safety.', FALSE, 1, NULL, NULL),
  ('75b8a980-0b79-5ca9-9285-147e4eebb778'::uuid, '41806bfe-c579-590d-90d1-6de840fd3212'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In a recent report, WHO reveals that road traffic injuries, homicide and suicide, are three of the top five causes of death among people aged five to 29.', FALSE, 2, NULL, NULL),
  ('0f211816-8199-5691-a456-661bfb355368'::uuid, '41806bfe-c579-590d-90d1-6de840fd3212'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But these can be mitigated with many available effective and low-cost interventions.', FALSE, 3, NULL, NULL),
  ('94d49b04-14a2-5506-8bdc-2d971a34a938'::uuid, '41806bfe-c579-590d-90d1-6de840fd3212'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In Viet Nam, providing more swimming training to communities is helping to cut down rates of death by drowning.', FALSE, 4, NULL, NULL),
