  ('9915cb09-1271-51a0-a9f8-c01cf03d4a01'::uuid, '442477a3-ef6f-58bd-81c6-02366678d7c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'imaginary', FALSE, 14, 3, NULL),
  ('f64710e4-b1b6-5065-a543-2461af0784a0'::uuid, '442477a3-ef6f-58bd-81c6-02366678d7c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'close', TRUE, 15, 3, NULL),
  ('716974f2-63f8-5eaa-8b6a-1eb0c931dca6'::uuid, '442be24c-265c-59e8-b2a0-d1820f3a403a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Conferences have played a key role in guiding the work of the United Nations since its very inception.', FALSE, 0, NULL, NULL),
  ('16cee9f0-a26f-5bf8-8e04-f6ad8bc3c145'::uuid, '442be24c-265c-59e8-b2a0-d1820f3a403a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These events have put long-term, difficult problems like poverty and environmental degradation at the top of the global agenda.', FALSE, 1, NULL, NULL),
  ('366f8edc-5bc8-5ed5-984e-4bb37d2a3c4e'::uuid, '442be24c-265c-59e8-b2a0-d1820f3a403a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These problems otherwise would not have the political urgency to grab front-page headlines and command the attention of world leaders.', FALSE, 2, NULL, NULL),
  ('b02b659b-9dac-5f6a-8470-376e0dd6c4ac'::uuid, '442be24c-265c-59e8-b2a0-d1820f3a403a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The recent high-profile conferences on development issues, which have continued a series that began in the 1970s, have broken new ground in many areas: by involving Presidents, Prime Ministers and other heads of state - as pioneered at the 1990 World Summit for Children.', FALSE, 3, NULL, NULL),
  ('39adc552-8015-5c6d-a0e3-7504b674f86d'::uuid, '442be24c-265c-59e8-b2a0-d1820f3a403a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In fact, the world body was born when delegates from 50 nations met in San Francisco in April 1945 for the United Nations Conference on International Organization.', FALSE, 4, NULL, NULL),
  ('6fa0e77b-98bc-5cc6-935d-b7e14f0cfb2a'::uuid, '44303a96-ce78-5c4d-841b-4f278c142eaa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Historians must make decisions about what to include and exclude, how to organize the material, and what to say about it.', FALSE, 0, NULL, NULL),
  ('3308a527-b91c-53d2-8954-54c8930a72e2'::uuid, '44303a96-ce78-5c4d-841b-4f278c142eaa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In doing so, they create narratives that explain the past in ways that make sense in the present. Inevitably, as the present changes, these narratives are updated, rewritten, or discarded altogether and replaced with new ones.', FALSE, 1, NULL, NULL),
  ('1c5e3a7c-1d27-5059-98ba-c34b972a6f1a'::uuid, '44303a96-ce78-5c4d-841b-4f278c142eaa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Ideas about history have changed over time. It might seem that writing history should be straightforward — it’s all based on facts, isn’t it?', FALSE, 2, NULL, NULL),
  ('8c51e9cf-4886-5ba3-a071-a8f193701e1a'::uuid, '44303a96-ce78-5c4d-841b-4f278c142eaa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In theory, yes, but the evidence surviving from the past is vast, fragmentary, and messy.', FALSE, 3, NULL, NULL),
  ('4824adb0-122a-5de6-b66b-0d814e58ff1b'::uuid, '443f9a9f-c12a-53bd-a198-3ae892614e18'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They climbed the mountain in 1953 and hold the record together.', FALSE, 0, NULL, NULL),
  ('b554beed-ffac-55c2-b909-c1e680bb04da'::uuid, '443f9a9f-c12a-53bd-a198-3ae892614e18'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'At 8,849 meters (29,032 feet), it is considered the tallest point on Earth.', FALSE, 1, NULL, NULL),
  ('1073321a-edef-5402-884b-25bf55624076'::uuid, '443f9a9f-c12a-53bd-a198-3ae892614e18'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Mount Everest is a peak in the Himalaya mountain range.', FALSE, 2, NULL, NULL),
  ('208562cc-1523-58eb-a1b7-2924c1cdf826'::uuid, '443f9a9f-c12a-53bd-a198-3ae892614e18'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The first records of Everest’s height, however, came much earlier, in 1856.', FALSE, 3, NULL, NULL),
  ('a4354ee7-f74f-5fb7-8d9e-2c1fe0580278'::uuid, '443f9a9f-c12a-53bd-a198-3ae892614e18'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The first ever recorded people to climb it were Edmund Hillary (a mountaineer from New Zealand) and his guide Tenzing Norgay.', FALSE, 4, NULL, NULL),
  ('fb3d922a-1652-519d-9bf5-a2900cbab2ff'::uuid, '44768d04-4647-5081-83a9-3eeac1c32c04'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'user', TRUE, 0, NULL, 1),
  ('40c6461c-a8b8-5d0f-b2fd-6e5119201ab6'::uuid, '44768d04-4647-5081-83a9-3eeac1c32c04'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'industrial', FALSE, 1, NULL, NULL),
