  ('0ba5779e-7594-567a-9a32-369608866203'::uuid, '44b44a9a-48ea-5617-9bdd-9e9f9b51aaaf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Previous lecture courses in medicine had included a series given by Peter Mark Roget, then a physician at Manchester Infirmary (1804-1808), but better known for his later Thesaurus.', FALSE, 0, NULL, NULL),
  ('1f08e0ae-2c88-5dbc-9f37-954fd34c4249'::uuid, '44b44a9a-48ea-5617-9bdd-9e9f9b51aaaf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Jordan, however, offered dissections as well as lectures, and medical education proved good business.', FALSE, 1, NULL, NULL),
  ('cc611af6-864f-5817-a6f3-8972a7927c6a'::uuid, '44b44a9a-48ea-5617-9bdd-9e9f9b51aaaf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In London, the private anatomy schools, which had competed with each other for decades, became incorporated with the hospitals, but in the provinces, private medical schools continued beyond 1870, using the hospitals for clinical teaching but not formally attached to them.', FALSE, 2, NULL, NULL),
  ('95691425-2466-50f6-902f-2d61adbef37d'::uuid, '44b44a9a-48ea-5617-9bdd-9e9f9b51aaaf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Formal medical education in Manchester began in 1814 when Joseph Jordan opened the first anatomy school in the English provinces.', FALSE, 3, NULL, NULL),
