  ('5771f8ca-06bc-59af-afe3-dad5af88c58a'::uuid, '45a2cf34-df96-5c03-89f9-6695e3862dec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'unwanted', TRUE, 15, 3, NULL),
  ('080efef3-c83d-581c-a65c-7d9ce549d581'::uuid, '45d85f62-ce06-5a8d-acf9-c75d84995159'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But as Charles Darwin put it: ‘False facts are highly injurious to the progress of science, for they often endure long; but false views, if supported by some evidence, do little harm.’', FALSE, 0, NULL, NULL),
  ('5ac1e5da-4b9f-56ff-8a56-bca02bcf0ecc'::uuid, '45d85f62-ce06-5a8d-acf9-c75d84995159'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Why are researchers holding back on ideas?', FALSE, 1, NULL, NULL),
  ('74c76326-dbd3-5585-800d-17193e542f3a'::uuid, '45d85f62-ce06-5a8d-acf9-c75d84995159'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Perhaps they are worried about proposing an idea that turns out to be wrong, because that might damage their chances of getting promotion or funding.', FALSE, 2, NULL, NULL),
  ('6b59fca1-0bb1-5de5-b705-f8fa68f004bb'::uuid, '45d85f62-ce06-5a8d-acf9-c75d84995159'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To wit, it’s important to get the facts right, but new ideas are useful, as long as they are based on reasonable evidence and are amenable to correction.', FALSE, 3, NULL, NULL),
  ('98d41649-3944-569c-a1b2-a43d63cc4c2c'::uuid, '45d88d01-62be-5d48-b032-5465fff2b917'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'reserve', FALSE, 0, NULL, NULL),
