  ('759afd96-501f-5d91-897c-6391634e4cb3'::uuid, '46c229a0-d4e6-5b5f-a6ba-5391ce5e0a61'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This process of separation created the layers of the Earth as we know them.', FALSE, 0, NULL, NULL),
  ('617c9c58-8a86-5f91-8a88-2064caf552a7'::uuid, '46c229a0-d4e6-5b5f-a6ba-5391ce5e0a61'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But there were violent collisions, explosions, and eruptions.', FALSE, 1, NULL, NULL),
  ('9c69fd25-5008-5c72-8555-e324434621eb'::uuid, '46c229a0-d4e6-5b5f-a6ba-5391ce5e0a61'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There were no oceans, there was no oxygen in the atmosphere, and no life.', FALSE, 2, NULL, NULL),
  ('2dfc4dfd-9ebf-5b24-91d6-6d19fe1abaf4'::uuid, '46c229a0-d4e6-5b5f-a6ba-5391ce5e0a61'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In fact, the Earth in its earliest stage was molten, which allowed elements to separate into layers within the Earth: gravity pulled denser elements toward the Earths center, while less dense materials accumulated near the surface.', FALSE, 3, NULL, NULL),
  ('646ff1b7-34a9-5445-bd25-6fb43c1cfe44'::uuid, '46c229a0-d4e6-5b5f-a6ba-5391ce5e0a61'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'When the Earth was formed 4.6 billion years ago, it would never have been called the Blue Planet.', FALSE, 4, NULL, NULL),
