  ('1875ba17-37e6-58cc-a129-88cbc06a40a9'::uuid, '46ed257f-6119-59e5-b238-93c5762c3830'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The introduction of hard disk drives and later solid-state drives offered much larger storage capacities and faster access to data.', FALSE, 0, NULL, NULL),
  ('18c6cbbe-51d9-5a02-8ee4-be90d791b00f'::uuid, '46ed257f-6119-59e5-b238-93c5762c3830'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The evolution of computer storage has dramatically changed how we use and think about data.', FALSE, 1, NULL, NULL),
  ('62a25cf5-a1df-5303-8e66-69146a21e21f'::uuid, '46ed257f-6119-59e5-b238-93c5762c3830'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As a result, these advancements have enabled the vast array of applications and services we use today, from cloud computing to multimedia streaming.', FALSE, 2, NULL, NULL),
  ('670613fa-f9aa-51d8-b8b4-64a621e91a29'::uuid, '46ed257f-6119-59e5-b238-93c5762c3830'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Early computers relied on punch cards and magnetic tape for storage, which were limited in capacity and speed.', FALSE, 3, NULL, NULL),
