  ('abfd0247-142e-5da5-aa75-7c2daca155c0'::uuid, '474db1d8-4bbf-5813-aff8-fdc05ec85f60'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Covid-19 pandemic necessitated a global shift to online learning.', FALSE, 0, NULL, NULL),
  ('c1154da1-8a27-5326-ba1e-98f2ed37b9b0'::uuid, '474db1d8-4bbf-5813-aff8-fdc05ec85f60'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'One inquiry used interviews to better understand how elementary teachers experienced remote instruction.', FALSE, 1, NULL, NULL),
  ('d6423d1f-8324-5a30-bff2-31fa1212be36'::uuid, '474db1d8-4bbf-5813-aff8-fdc05ec85f60'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The results suggest that teachers need more guidance from administration and resources to manage stress.', FALSE, 2, NULL, NULL),
  ('b51c4834-5d59-5a3e-911e-ea18881fbb4a'::uuid, '474db1d8-4bbf-5813-aff8-fdc05ec85f60'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'While researchers have examined the impact of remote learning on elementary students'' academic performance, less is known about elementary teachers'' perceptions of teaching online during the pandemic.', FALSE, 3, NULL, NULL),
