  ('210df524-15b7-53aa-a408-2fb9f12d9d00'::uuid, '47651c7e-75b6-514c-a706-b1c4e30b44c7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Therefore, current quantum computing research is heavily focused on achieving stable and practical systems.', FALSE, 0, NULL, NULL),
  ('fe71063a-d181-5eb7-90fd-746a6c0b1cc6'::uuid, '47651c7e-75b6-514c-a706-b1c4e30b44c7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It operates on quantum bits, enabling it to process vast amounts of information simultaneously.', FALSE, 1, NULL, NULL),
