  ('e3e6563d-33e1-5eb8-9d06-cb0dc20cc977'::uuid, '489b1041-fc98-579b-b380-bd58abbbce3b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Over time, fashion and people''s tastes change.', FALSE, 0, NULL, NULL),
  ('c2d9544f-f5c6-58f6-8946-561654e88a1b'::uuid, '489b1041-fc98-579b-b380-bd58abbbce3b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Such changes affect the demand for products and services.', FALSE, 1, NULL, NULL),
  ('d363ba4b-6356-5eef-8155-7e6c8705418b'::uuid, '489b1041-fc98-579b-b380-bd58abbbce3b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Changes in work patterns tend to mean that fewer families sit down in the evening for a traditionally produced family meal, often because a lack of time.', FALSE, 2, NULL, NULL),
  ('145cd23b-ca8a-5fb4-bd87-6a418f6b4008'::uuid, '489b1041-fc98-579b-b380-bd58abbbce3b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In contrast, people now tend to spend more time shopping and are therefore more likely to spend time relaxing in a coffee shop or restaurant while on a shopping trip.', FALSE, 3, NULL, NULL),
  ('49681492-434b-5f59-9264-ee23c381c125'::uuid, '489b1041-fc98-579b-b380-bd58abbbce3b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Consequently, people are now more likely to buy takeaway meals or convenience food, as opposed to ingredients for meals that take time to prepare.', FALSE, 4, NULL, NULL),
  ('c19110e1-0f57-54dd-999e-d34ed36635ee'::uuid, '48c94cff-db2e-54d9-9d23-2ba20be8c90b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'sectors', FALSE, 0, NULL, NULL),
