  ('549c9d24-aa69-5a8d-a274-d801757d15e8'::uuid, '4910065b-0790-5c9a-86c1-922bdbf3342c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'taken', FALSE, 4, NULL, NULL),
  ('3228ac68-7eb8-55fa-8f54-40caaa0d2889'::uuid, '4910065b-0790-5c9a-86c1-922bdbf3342c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'release', FALSE, 5, NULL, NULL),
  ('952e524d-17b6-5243-89e5-84aa9ecdeaf8'::uuid, '4914b49e-6b80-5bd0-b0c1-24658bf21d07'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They theorized that the 1.2 liters of green tea that is consumed by many Asians each day provides high levels of polyphenols and other antioxidants.', FALSE, 0, NULL, NULL),
  ('31c0302c-6c39-5564-b4f6-698ed215dab5'::uuid, '4914b49e-6b80-5bd0-b0c1-24658bf21d07'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They pointed to what they called an "Asian paradox," which refers to lower rates of heart disease and cancer in Asia despite high rates of cigarette smoking.', FALSE, 1, NULL, NULL),
  ('dd4222df-52b0-5bd8-8511-7b155991dbef'::uuid, '4914b49e-6b80-5bd0-b0c1-24658bf21d07'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In May 2006, researchers at Yale University School of Medicine weighed in on the issue with a review article that looked at more than 300 studies on the health benefits of green tea.', FALSE, 2, NULL, NULL),
  ('a9909f13-ea6b-509d-a097-8a028e92e798'::uuid, '4914b49e-6b80-5bd0-b0c1-24658bf21d07'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These compounds may work in several ways to improve cardiovascular health.', FALSE, 3, NULL, NULL),
  ('affcbde0-d96d-5be7-adf8-d8439bb4b837'::uuid, '4914b49e-6b80-5bd0-b0c1-24658bf21d07'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Specifically, green tea may prevent the oxidation of LDL cholesterol (the “bad” type), which, in turn, can reduce the buildup of plaque in arteries, the researchers wrote.', FALSE, 4, NULL, NULL),
  ('ed5af363-6f83-5f92-b86e-e1d8b301748c'::uuid, '49345a53-2452-528a-b44b-eb5ae9cf1b87'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'avoided', TRUE, 0, NULL, 2),
