  ('736d3d9c-d661-5855-a780-c25a8a168093'::uuid, '4935c140-667d-5ee7-9334-134809347b0a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Open days are good chances for parents to ask what they want to know.', FALSE, 0, NULL, NULL),
  ('50dfe4ec-9350-59bb-a957-10e1ebe4033f'::uuid, '4935c140-667d-5ee7-9334-134809347b0a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'One of the common ways is open days.', FALSE, 1, NULL, NULL),
  ('9c922462-5bd7-5f43-a038-f011fef4ff09'::uuid, '4935c140-667d-5ee7-9334-134809347b0a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'School has different ways to let parents know how they provide education services.', FALSE, 2, NULL, NULL),
  ('55c4e96d-f3ef-5296-91b4-ae982b96d767'::uuid, '4935c140-667d-5ee7-9334-134809347b0a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These are times when parents can know what their children will be doing at school.', FALSE, 3, NULL, NULL),
  ('6d1b54d0-3e26-581e-834c-e3285568a333'::uuid, '494fefd9-b3d5-50c3-8e33-3fe24c911c10'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Their brains are the same as adults'' but with fewer miles on it.', FALSE, 0, NULL, NULL),
  ('4bab1c28-8ee8-5f9d-a825-48c437fa366a'::uuid, '494fefd9-b3d5-50c3-8e33-3fe24c911c10'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Their brains are so small that they cannot deal with so much information.', FALSE, 1, NULL, NULL),
  ('f964568e-562b-5530-af05-942622eda5a4'::uuid, '494fefd9-b3d5-50c3-8e33-3fe24c911c10'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They do not know what to do with their very sharp brains.', TRUE, 2, NULL, NULL),
  ('8e8366ff-7d7a-590c-9dc6-67200f6c4885'::uuid, '494fefd9-b3d5-50c3-8e33-3fe24c911c10'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Controlling their actions, CPG receives a simple signal from the brain to switch between different modes.', FALSE, 3, NULL, NULL),
