  ('88a42e7d-d894-5239-81d1-aa94840ba53e'::uuid, '498927db-7529-5f77-9da9-816b562b62b5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In 2013, plans to construct a 34 billion pounds barrage across the Severn estuary were rejected after concerns were raised about its effect on local ecosystems.', FALSE, 0, NULL, NULL),
  ('e80b5ca2-72eb-5d08-9d5a-ccc5ffb24109'::uuid, '498927db-7529-5f77-9da9-816b562b62b5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'And with the second largest tidal range in the world, British marine energy could play an important role in this shift.', FALSE, 1, NULL, NULL),
  ('552a6b28-4217-501d-b9be-886b0392044c'::uuid, '498927db-7529-5f77-9da9-816b562b62b5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The government has promised to help counter this global trend by reducing UK carbon emissions by 80 percent from 1990 levels by 2050.', FALSE, 2, NULL, NULL),
  ('ca06b098-123b-5c65-a32e-5f67beaf999c'::uuid, '498927db-7529-5f77-9da9-816b562b62b5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'By 2100, human-induced climate change threatens to raise temperatures by 2-4°C and push up tide-lines by 4-6m.', FALSE, 3, NULL, NULL),
  ('92348ba7-6f80-5dcb-8c6c-e47abbe2efa6'::uuid, '498927db-7529-5f77-9da9-816b562b62b5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But harnessing the power of the tides is not without consequence.', FALSE, 4, NULL, NULL),
  ('77a6bde7-b72b-577e-9161-f23575dac5b3'::uuid, '49a27c0d-324a-5342-8dcb-d12c2b016920'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'pollution', FALSE, 0, NULL, NULL),
