  ('b3d9df12-c093-5c73-8a5c-63dd3186a3b7'::uuid, '49ac7a8f-a83a-5e7c-b985-e9ed0911c55b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'unfold', FALSE, 0, NULL, NULL),
