  ('62f06171-8518-5f69-a662-cfe7876b71cd'::uuid, '49ac7a8f-a83a-5e7c-b985-e9ed0911c55b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'estimate', TRUE, 3, NULL, 0),
  ('4d630425-5c0f-5c8f-ac22-88f9c29cdcc5'::uuid, '49ac7a8f-a83a-5e7c-b985-e9ed0911c55b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'surveys', TRUE, 4, NULL, 1),
  ('c98d8dc9-095c-550d-bcda-3edc482b143b'::uuid, '49ac7a8f-a83a-5e7c-b985-e9ed0911c55b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'funds', FALSE, 5, NULL, NULL),
  ('d5d1e89f-0fda-5290-9046-c87ce3191dd0'::uuid, '49c14c89-beba-599b-a7ed-95f95c58f177'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Another study had similar findings, reporting that consuming caffeine before a round of golf improved performance, increased subjective energy levels, and reduced feelings of fatigue.', FALSE, 0, NULL, NULL),
  ('4d196bc7-d146-5eb2-90ec-c486de8dbc2f'::uuid, '49c14c89-beba-599b-a7ed-95f95c58f177'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'One small study found that consuming caffeine increased time to exhaustion during a cycling exercise by 12% and significantly reduced subjective levels of fatigue in participants.', FALSE, 1, NULL, NULL);
INSERT INTO _pte_local_seed_options (public_id, question_public_id, created_at, updated_at, deleted, text, correct, order_index, blank_index, correct_gap_index) VALUES
  ('4bdea134-e79b-5e4c-9c29-563bdd3b97ee'::uuid, '49c14c89-beba-599b-a7ed-95f95c58f177'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This is because caffeine blocks the receptors of a neurotransmitter called adenosine, and this increases levels of other neurotransmitters in your brain that regulate your energy levels.', FALSE, 2, NULL, NULL),
  ('4f7a5d2b-a696-5a60-9c6f-cf208d92f363'::uuid, '49c14c89-beba-599b-a7ed-95f95c58f177'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Coffee contains caffeine, a central nervous system stimulant that is known for its ability to fight fatigue and increase energy levels.', FALSE, 3, NULL, NULL),
  ('c2b6ab29-2d9c-51ef-a54f-8df8c0f65c8f'::uuid, '49c31d09-c543-57a2-9471-f3c648531fec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As a result, Senegal''s marine ecosystem has started to go the same way as ours.', FALSE, 0, NULL, NULL),
  ('c0292deb-9de3-5031-91d1-dfebf45765cd'::uuid, '49c31d09-c543-57a2-9471-f3c648531fec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The other is that its governments won''t confront their fishing lobbies and decommission all the surplus boats.', FALSE, 1, NULL, NULL),
  ('b5cf8970-0777-59e3-9a65-cd8c78653216'::uuid, '49c31d09-c543-57a2-9471-f3c648531fec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'One is that, partly as a result of its failure to manage them properly, its own fisheries can no longer meet European demand.', FALSE, 2, NULL, NULL),
  ('3e7c0aff-79af-58f8-a6df-b7e13199bf5d'::uuid, '49c31d09-c543-57a2-9471-f3c648531fec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The European Union has two big fish problems.', FALSE, 3, NULL, NULL),
  ('dae83bac-b120-55b9-a1c5-1aa155d37147'::uuid, '49c31d09-c543-57a2-9471-f3c648531fec'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The EU has tried to solve both problems by sending its fishermen to West Africa. Since 1979 it has struck agreements with the government of Senegal, granting our fleets access to its waters.', FALSE, 4, NULL, NULL),
  ('1ea104bb-8f7c-5e9b-9c3b-5ad13db01332'::uuid, '49c5213f-f8e9-52cd-845f-6feefa2c7f48'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'body', TRUE, 0, NULL, 4),
  ('c6c35813-ffc9-58a4-a866-4437cd21497e'::uuid, '49c5213f-f8e9-52cd-845f-6feefa2c7f48'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'company', TRUE, 1, NULL, 1),
  ('6483b6bf-86d6-58de-b09a-f48f2b6c86c2'::uuid, '49c5213f-f8e9-52cd-845f-6feefa2c7f48'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'convergent', FALSE, 2, NULL, NULL),
