  ('c4f2adf5-8709-59f5-843e-025d71f74888'::uuid, '4af18336-358d-5177-af62-96faf103ef6b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Absolute location refers to a specific, fixed point on the Earth''s surface as expressed by a scientific coordinate system.', FALSE, 0, NULL, NULL),
  ('9a09adf4-219d-504e-ab88-9e859ee7fbc1'::uuid, '4af18336-358d-5177-af62-96faf103ef6b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It is more precise than the relative location, which describes where a place is located using other places nearby.', FALSE, 1, NULL, NULL),
  ('6c610072-a16a-5689-a557-39d925353f90'::uuid, '4af18336-358d-5177-af62-96faf103ef6b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Nowadays, finding your absolute location at any given time can be done using geolocation software, which is found in most smartphones.', FALSE, 2, NULL, NULL),
  ('c6bf5beb-baea-5ed1-af32-ca61ecfcc689'::uuid, '4af18336-358d-5177-af62-96faf103ef6b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This software uses the Global Positioning System (GPS) to deliver precise information about the location of any GPS receiver on Earth.', FALSE, 3, NULL, NULL),
  ('ecd54ff6-39ee-5d82-be61-25f50c5368eb'::uuid, '4af18336-358d-5177-af62-96faf103ef6b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In contrast, a relative location can be as general as "west of the highway".', FALSE, 4, NULL, NULL),
  ('33f813f0-9f99-5444-87cb-727413a0c36a'::uuid, '4af441b9-60db-5194-8d0f-569b308a5e4a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But ongoing innovations have significantly reduced these barriers, making renewables increasingly competitive with traditional fossil fuels.', FALSE, 0, NULL, NULL),
  ('aaf6fa02-10d5-5364-851e-0ccadc2be2e4'::uuid, '4af441b9-60db-5194-8d0f-569b308a5e4a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This shift is crucial in mitigating the impacts of climate change and ensuring a sustainable energy future.', FALSE, 1, NULL, NULL),
  ('b5fdb48e-7372-58ba-9cc8-3f9ba634e618'::uuid, '4af441b9-60db-5194-8d0f-569b308a5e4a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Initially, high costs and technological limitations slowed their adoption.', FALSE, 2, NULL, NULL),
  ('4131552b-4c9f-55bd-ab57-7bba132e4ecc'::uuid, '4af441b9-60db-5194-8d0f-569b308a5e4a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In recent years, renewable energy sources such as solar, wind, and hydroelectric power have seen remarkable growth.', FALSE, 3, NULL, NULL),
  ('44c89f14-4e72-57dd-a20b-6e7da5f8d9b3'::uuid, '4af4a9d7-2f89-5c62-8ba4-a3b7471d6df8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These include the weather, low air humidity and immersion in hot water, and it is usually temporary.', FALSE, 0, NULL, NULL),
  ('227c7b07-63f0-53b2-8177-6de4f017216f'::uuid, '4af4a9d7-2f89-5c62-8ba4-a3b7471d6df8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These people normally have a relatively sensitive skin.', FALSE, 1, NULL, NULL),
  ('435aa9c0-3f66-5b6f-8ed2-905043587f0c'::uuid, '4af4a9d7-2f89-5c62-8ba4-a3b7471d6df8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In many cases, dry skin is caused by many external factors.', FALSE, 2, NULL, NULL),
  ('76c9b00f-59a6-5bb8-878a-2d545b4d98a4'::uuid, '4af4a9d7-2f89-5c62-8ba4-a3b7471d6df8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, for some people it may occur more often and even be a lifelong condition.', FALSE, 3, NULL, NULL),
  ('5697b76c-ec0b-51d3-95f8-2aa3f04385a4'::uuid, '4b03417a-c3c0-597b-88bd-109a25cfa169'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Two main techniques have been used for training elephants, which we may call respectively the tough and the gentle.', FALSE, 0, NULL, NULL),
  ('a34fe25c-eeaf-5aa7-afa6-8784aa046e7b'::uuid, '4b03417a-c3c0-597b-88bd-109a25cfa169'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Apart from any moral considerations this is a stupid method of training, for it produces a resentful animal who at a later stage may well turn man-killer.', FALSE, 1, NULL, NULL),
  ('d1438a8e-502f-5fac-a632-068a120875dc'::uuid, '4b03417a-c3c0-597b-88bd-109a25cfa169'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The former method simply consists of setting an elephant to work and beating him until he does what is expected of him.', FALSE, 2, NULL, NULL),
  ('57c7ed3d-6fb9-59df-945a-cb023063b16a'::uuid, '4b03417a-c3c0-597b-88bd-109a25cfa169'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The gentle method requires more patience in the early stages, but produces a cheerful, good-tempered elephant who will give many years of loyal service.', FALSE, 3, NULL, NULL),
  ('b7025280-3ef7-5419-b22d-8021f135cd36'::uuid, '4b16c296-7554-578f-936c-b9b4a90f8bd7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'debate', FALSE, 0, NULL, NULL),
