  ('cb583360-f48d-5711-91a0-d7e9b35bd4aa'::uuid, '4c985af2-9380-54e7-a176-24b16b74a66b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'People with advanced addictions will continue their addictive behavior, even when they understand that doing so is harmful to themselves and others.', FALSE, 0, NULL, NULL),
  ('6b626b85-6687-5ae8-a7c0-01859300efb7'::uuid, '4c985af2-9380-54e7-a176-24b16b74a66b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A compulsion is different from an addiction.', FALSE, 1, NULL, NULL),
  ('3245258c-c697-5dda-bf81-6ca18b03ecc2'::uuid, '4c985af2-9380-54e7-a176-24b16b74a66b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The former is an overwhelming desire (or sense of physical need) to do something, while an addiction is a physical or chemical dependence on a substance or behavior.', FALSE, 2, NULL, NULL),
  ('f927d483-f869-5186-8969-d9baf9d7c5e5'::uuid, '4c985af2-9380-54e7-a176-24b16b74a66b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For instance, alcoholism, drug abuse, smoking, and gambling are perhaps the most common examples of addictions.', FALSE, 3, NULL, NULL),
  ('e4acdd85-c047-52aa-aaa2-334979bc1563'::uuid, '4ca0842e-eaae-5e12-9569-22005cb62b37'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They want an incomes policy to check inflation while federal financing helps rebuild industry behind a wall of protective tariffs.', FALSE, 0, NULL, NULL),
