  ('d5a7079a-8ddf-5592-a616-0c7e8d104cfd'::uuid, '4ca0842e-eaae-5e12-9569-22005cb62b37'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It provides a coordinated program of investment credits, research grants, education reforms, and changes designed to make American industry more competitive.', FALSE, 3, NULL, NULL),
