  ('c54894cc-f5b2-5378-9100-e9a24b0e1f25'::uuid, '4dd1e295-2688-53de-a523-1892e8f0fbb8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Wildfires appear to stir up and send the soil-loving fungi into the air, where they can enter people’s lungs.', FALSE, 0, NULL, NULL),
  ('91ecf053-e5f6-50b2-b7c4-bbb76c238b7b'::uuid, '4dd1e295-2688-53de-a523-1892e8f0fbb8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The culprit fungi thrive in soils in California and the desert Southwest. Firefighters are especially vulnerable to the disease.', FALSE, 1, NULL, NULL),
  ('1102ea02-33b7-543b-b2e3-2c794f4fba70'::uuid, '4dd1e295-2688-53de-a523-1892e8f0fbb8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As climate change brings more wildfires to the western United States, a rare fungal infection, valley fever, has also been on the rise.', FALSE, 2, NULL, NULL),
  ('427ac474-3665-54fc-ba1e-1ebbf9b5048e'::uuid, '4dd1e295-2688-53de-a523-1892e8f0fbb8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It causes coughs, fevers and chest pain and can be deadly.', FALSE, 3, NULL, NULL),
  ('f215f0c6-34f8-5fc1-9578-7bd27bb1d853'::uuid, '4dd866ca-efee-5e23-bad1-f87752a8d2c2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The first steel rails were made in 1857 by Robert Forester Mushet, who laid them at Derby station in England. Steel is a much stronger material, which steadily replaced iron for use on railway rail and allowed much longer lengths of rails to be rolled.', FALSE, 0, NULL, NULL),
  ('6df586b2-2948-580c-97d3-aeeac8f40c49'::uuid, '4dd866ca-efee-5e23-bad1-f87752a8d2c2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'An early proponent of this design was Benjamin Outram. His partner William Jessop preferred the use of "edge rails" in 1789 where the wheels were flanged and, over time, it was realised that this combination worked better.', FALSE, 1, NULL, NULL),
  ('066bf0a2-b0ab-5623-b53c-c803c2a4484f'::uuid, '4dd866ca-efee-5e23-bad1-f87752a8d2c2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These were superseded by cast iron rails that were flanged (i.e. ''L'' shaped) and with the wagon wheels flat.', FALSE, 2, NULL, NULL),
  ('862338de-21ca-5c80-960b-06c1a7bbbd93'::uuid, '4dd866ca-efee-5e23-bad1-f87752a8d2c2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, the long-term expense involved in frequent maintenance outweighed any savings.', FALSE, 3, NULL, NULL),
  ('dd632b2e-6851-5b89-a0dd-37aca14eef5a'::uuid, '4dd866ca-efee-5e23-bad1-f87752a8d2c2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These rails were too fragile to carry heavy loads, but because the initial construction cost was less, this method was sometimes used to quickly build an inexpensive rail line.', FALSE, 4, NULL, NULL),
  ('d57763a6-5563-5c07-973c-afb35024640e'::uuid, '4dd866ca-efee-5e23-bad1-f87752a8d2c2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Early rails were used on horse drawn wagon ways originally with wooden rails, but from the 1760s using strap-iron rails, which consisted of thin strips of cast iron fixed onto wooden rails.', FALSE, 5, NULL, NULL),
  ('6c11d9c1-9fa9-5ac2-90fd-eb9c859e76dd'::uuid, '4dda9e4b-1dfe-556e-942c-288e5f69fbd5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'struggle', TRUE, 0, NULL, 3),
  ('485c4202-d2c8-5e12-8340-df14d4f714c0'::uuid, '4dda9e4b-1dfe-556e-942c-288e5f69fbd5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'rigorous', TRUE, 1, NULL, 4),
  ('7d0c2140-e9c2-5056-8240-7f105e2e4803'::uuid, '4dda9e4b-1dfe-556e-942c-288e5f69fbd5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'underline', TRUE, 2, NULL, 0),
  ('57b33ff0-be90-5f86-80c0-2713b690f001'::uuid, '4dda9e4b-1dfe-556e-942c-288e5f69fbd5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'same', FALSE, 3, NULL, NULL),
  ('ec6574c1-b609-5f2c-ad92-97c8c48fc4e8'::uuid, '4dda9e4b-1dfe-556e-942c-288e5f69fbd5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'split', FALSE, 4, NULL, NULL),
  ('15d50604-bf3c-55b0-b328-a1e460d59632'::uuid, '4dda9e4b-1dfe-556e-942c-288e5f69fbd5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'refuse', FALSE, 5, NULL, NULL),
  ('af607c32-b221-586c-aee3-d858e29a0e49'::uuid, '4dda9e4b-1dfe-556e-942c-288e5f69fbd5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'associate', TRUE, 6, NULL, 2),
  ('48e31da4-0a31-558f-8e80-0e51322398f1'::uuid, '4dda9e4b-1dfe-556e-942c-288e5f69fbd5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'akin', TRUE, 7, NULL, 1),
  ('9e4a2b81-a23d-5cea-8392-2bcdf89729f6'::uuid, '4dda9e4b-1dfe-556e-942c-288e5f69fbd5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'severe', FALSE, 8, NULL, NULL),
  ('9e41d6e9-e373-5e7a-be30-69e6c3c2c141'::uuid, '4ddebe65-5c8b-5303-9c08-24d2ebb7b77c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The movement also creates gaps in tectonic plates, which reduce the pressure on the mantle beneath it, allowing it to melt and push through.', FALSE, 0, NULL, NULL),
  ('f7d2eabf-a9e5-5624-b5dc-15fb2bd4d296'::uuid, '4ddebe65-5c8b-5303-9c08-24d2ebb7b77c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The buildup and sudden release of friction from this movement can cause earthquakes.', FALSE, 1, NULL, NULL),
  ('c36b2921-48da-55f0-9907-4bf182dc10f5'::uuid, '4ddebe65-5c8b-5303-9c08-24d2ebb7b77c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This leads the tectonic plates on top to slowly jostle one another.', FALSE, 2, NULL, NULL),
  ('b0202e0a-502a-5768-9edd-77e33e4f0a18'::uuid, '4ddebe65-5c8b-5303-9c08-24d2ebb7b77c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The mantle makes up 84 percent of Earth''s volume, and though it''s solid rock, over the course of millions of years, it behaves like a liquid.', FALSE, 3, NULL, NULL),
  ('21d56a06-382f-5087-aaab-ff764b5ef714'::uuid, '4e02f486-0fd2-5f82-a837-25bbdce2e4ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ambiguity', FALSE, 0, NULL, NULL),
  ('7cbe94a7-c142-5075-ab01-89efb0233671'::uuid, '4e02f486-0fd2-5f82-a837-25bbdce2e4ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'collaborative', TRUE, 1, NULL, 2);
