  ('c15b9a60-1e51-5951-9024-5788f9bd1f40'::uuid, '4e0fe4c2-0517-5b96-8cc4-a3d1f5fc34fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They have a regular shape.', FALSE, 0, NULL, NULL),
  ('b8b72ba6-6ebc-577a-956a-62e7a0383f25'::uuid, '4e0fe4c2-0517-5b96-8cc4-a3d1f5fc34fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They are formed where glaciers meet the ocean.', TRUE, 1, NULL, NULL),
  ('9808078c-6ea3-5e89-8a2e-e97cf8dfc353'::uuid, '4e0fe4c2-0517-5b96-8cc4-a3d1f5fc34fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Most of their mass is above the sea surface.', FALSE, 2, NULL, NULL),
  ('73b0e4d4-38a4-5913-8e0a-8031348b8411'::uuid, '4e0fe4c2-0517-5b96-8cc4-a3d1f5fc34fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Waves and tides cause them to break off glaciers.', TRUE, 3, NULL, NULL),
  ('c2fa875b-bb07-5e62-8f11-01cf93d6e7e5'::uuid, '4e0fe4c2-0517-5b96-8cc4-a3d1f5fc34fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The color of the icebergs is always the same.', FALSE, 4, NULL, NULL),
