  ('0f469175-9665-5045-92e4-a59a6beded89'::uuid, '4e3ce18c-b0d4-5e01-bd9f-6391f9162b48'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Born in Omaha, Nebraska, Ed Ruscha spent most of his years growing up in Oklahoma City, Oklahoma.', FALSE, 1, NULL, NULL),
  ('5eb109f9-6f7f-5f50-b3ca-e46cae369e55'::uuid, '4e3ce18c-b0d4-5e01-bd9f-6391f9162b48'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'His mother introduced him to the appreciation of music, literature, and art.', FALSE, 2, NULL, NULL),
