  ('ebad3e1e-9069-539e-bc11-bb76cb93323e'::uuid, '4ee4f186-8281-5071-a4d5-c3c2830c195e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The lecture is mainly about various aspects of Mayan civilization. They developed exceptional works of architecture as well as writing system. However, all of these have not survived to present day due to Spanish conquerors.', TRUE, 0, NULL, NULL),
  ('f99b7ef9-119e-5112-8203-f4483c55e33d'::uuid, '4ee4f186-8281-5071-a4d5-c3c2830c195e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The lecture is mainly about the methods the Mayans used to write with. They often used paper to write on and unfortunately many figures and pottery were stolen by Spanish conquerors.', FALSE, 1, NULL, NULL),
  ('b6d63d53-ac8a-57e9-9532-3480df037ff2'::uuid, '4ee4f186-8281-5071-a4d5-c3c2830c195e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The lecture is mainly about the role of the Spanish in Mayan culture. The Spanish conquerors announce that they defeated the Mayans in battle and then destroyed many of Mayan’s written records.', FALSE, 2, NULL, NULL),
