  ('eb22604a-4924-5370-9e53-50afde07f2fc'::uuid, '4fe08392-6f37-5bfc-8151-39b3bb457427'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The right chair will impress your boss.', FALSE, 1, NULL, NULL),
  ('436ca69a-f4bd-5c5a-8378-12cabcb060cf'::uuid, '4fe08392-6f37-5bfc-8151-39b3bb457427'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The chairs color affects your level of stress.', FALSE, 2, NULL, NULL),
  ('02da216d-0bf1-58b3-b19c-56e2d16cd94a'::uuid, '4fe08392-6f37-5bfc-8151-39b3bb457427'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The right chair can help you avoid back pain.', TRUE, 3, NULL, NULL),
  ('ccff15b4-1293-55a2-990b-65fd8fd2a091'::uuid, '500be7b9-af3d-58a7-8fb9-fb291d38c62a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In the universe, just a few star systems have more than one stars.', FALSE, 0, NULL, NULL),
  ('b44769af-9de2-5fc5-a434-5dc15a3b8d34'::uuid, '500be7b9-af3d-58a7-8fb9-fb291d38c62a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The speaker thinks that seeing two Suns during a sunset is a rather scaring sight.', FALSE, 1, NULL, NULL),
  ('58b5219f-3ff8-5afe-894d-c716b549ef40'::uuid, '500be7b9-af3d-58a7-8fb9-fb291d38c62a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In fact, about 33% of the star systems have two or more stars.', TRUE, 2, NULL, NULL),
  ('816dcfee-678c-542f-a4d8-a7591a7d3ee2'::uuid, '500be7b9-af3d-58a7-8fb9-fb291d38c62a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The consequences of having two suns would be detrimental to humans on Earth.', FALSE, 3, NULL, NULL),
  ('faa653fa-7b52-55d7-931a-cad276ed4929'::uuid, '5014f8ee-c828-5afa-9f72-f3a7ad454e23'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Sodium is harmful to the human body and should be eliminated entirely, as the kidney cannot regulate it effectively.', FALSE, 0, NULL, NULL),
  ('0381ffc3-4704-5fb1-8f11-8fb70f565aa5'::uuid, '5014f8ee-c828-5afa-9f72-f3a7ad454e23'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Sodium levels never change in the body, so no regulation is needed.', FALSE, 1, NULL, NULL),
  ('3e94cb13-6129-5bb1-9b5b-61b273b5a795'::uuid, '5014f8ee-c828-5afa-9f72-f3a7ad454e23'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Sodium is stored only in the bones, and its balance is controlled by the lungs rather than the kidneys.', FALSE, 2, NULL, NULL),
  ('4de6c620-6756-5ec0-8cbe-186985a0a64e'::uuid, '5014f8ee-c828-5afa-9f72-f3a7ad454e23'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Sodium is an essential mineral, and the kidney uses filtration, reabsorption, and hormones to maintain body sodium balance.', TRUE, 3, NULL, NULL),
  ('9fa67a62-403a-5cf9-b1cd-f0c8f740e64a'::uuid, '5018a622-8d69-537c-a9c7-935f774bcb7f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'aggressive', FALSE, 0, NULL, NULL),
  ('1db8ab2c-9a59-5e37-8e71-148c6734ee1e'::uuid, '5018a622-8d69-537c-a9c7-935f774bcb7f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'endangered', FALSE, 1, NULL, NULL),
  ('64b860cc-fc12-5aee-a144-98875eedbb65'::uuid, '5018a622-8d69-537c-a9c7-935f774bcb7f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'airborne', FALSE, 2, NULL, NULL),
