  ('1a0871e4-1d81-5651-a43b-cfc1b4798640'::uuid, '5018a622-8d69-537c-a9c7-935f774bcb7f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'triggered', TRUE, 5, NULL, 0),
  ('f3e8632a-36d7-539d-b587-2b0563bf6b5c'::uuid, '5021f73b-7cf7-58e7-a6df-744e5903b383'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Without having the right amount of balance, you’re going to struggle to shift your centre of gravity into an optimal position to help you complete a problem.', FALSE, 0, NULL, NULL),
  ('4bf97a26-cfed-54f4-9f82-a33e9e696fc1'::uuid, '5021f73b-7cf7-58e7-a6df-744e5903b383'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Balance is everything when you’re climbing.', FALSE, 1, NULL, NULL),
  ('c06cb4c6-149b-5ea3-b115-0a90d3214a06'::uuid, '5021f73b-7cf7-58e7-a6df-744e5903b383'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Besides, the core strength and balance often go hand in hand.', FALSE, 2, NULL, NULL),
  ('1f20ba44-94a8-509c-8767-b17fff54b020'::uuid, '5021f73b-7cf7-58e7-a6df-744e5903b383'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Therefore, the more you climb and the more you increase your core strength, the greater improvements you’ll see in your balance.', FALSE, 3, NULL, NULL),
  ('f67d87ac-59df-57ae-b94d-987c9d6e9474'::uuid, '50380f95-d77e-5d2a-8c01-982c3c606995'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'defect', FALSE, 0, NULL, NULL),
