  ('a5a8fa1f-fc43-5ffb-832b-a8674e599d99'::uuid, '52097b14-05b2-5d92-9f1e-d3fcb0159683'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'rebelling', TRUE, 6, NULL, 0),
  ('77fe557b-f119-5a11-9630-d58d28aef13d'::uuid, '5248f95c-818e-5bab-9f2e-0b3239a93bae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Suez Crisis of 1956 was a diplomatic and military confrontation in Egypt involving Egypt, Israel, France, and the United Kingdom.', FALSE, 0, NULL, NULL),
  ('7c13f306-a579-5be5-b8df-dc7b7e47f8cc'::uuid, '5248f95c-818e-5bab-9f2e-0b3239a93bae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Consequently, it marked the decline of British and French influence in the region and the emergence of new power dynamics.', FALSE, 1, NULL, NULL),
  ('71dc1b89-08e6-5b1b-a808-cda1cac16d0e'::uuid, '5248f95c-818e-5bab-9f2e-0b3239a93bae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Although the conflict was brief, it had significant implications for the Middle East, colonialism, and international relations.', FALSE, 2, NULL, NULL),
  ('227e1707-fef6-5333-b2cd-9a89d379b54d'::uuid, '5248f95c-818e-5bab-9f2e-0b3239a93bae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The crisis began after Egypt nationalized the Suez Canal, previously controlled by British and French companies.', FALSE, 3, NULL, NULL),
  ('311c8436-491f-5583-8146-15a1cdadcfdf'::uuid, '524b8370-37c1-5dc6-bf77-3f8cf0d73cd7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Unlike Barnes'' previous books, Mother of Storms has a fairly large cast of viewpoint characters.', FALSE, 0, NULL, NULL),
  ('bbbeb707-7649-5f9e-98a9-adc43a17df37'::uuid, '524b8370-37c1-5dc6-bf77-3f8cf0d73cd7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But even the Evil American Corporate Magnate is a pretty likable guy.', FALSE, 1, NULL, NULL),
  ('31a29893-c541-518e-8d75-873cccbae0cd'::uuid, '524b8370-37c1-5dc6-bf77-3f8cf0d73cd7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They''re not all necessarily good guys, either, although with the hurricanes wreaking wholesale destruction upon the world''s coastal areas, ethical categories tend to become irrelevant.', FALSE, 2, NULL, NULL),
  ('0f76dccc-2536-50fb-9f3f-3f04b266fc9f'::uuid, '524b8370-37c1-5dc6-bf77-3f8cf0d73cd7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This usually irritates me, but I didn''t mind it here, and their interactions are well-handled and informative, although occasionally in moving those about the author''s manipulations are a bit blatant. (Especially when one character''s ex-girlfriend, who has just undergone a sudden and not entirely credible change in personality, is swept up by a Plot Device in Shining Armor and transported directly across most of Mexico and a good bit of the States to where she happens to bump into another viewpoint character.)', FALSE, 3, NULL, NULL),
  ('0989ce80-2f31-5551-a81e-6feaa1e19989'::uuid, '5271d2db-6441-5170-8352-043c723ee48d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'qualified', TRUE, 0, NULL, 0),
