  ('60f9e868-c0e6-51d0-98f2-5dd84ee15fb8'::uuid, '528f1a5b-cbec-5916-9ede-277348d0c9c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As a result, books have played a crucial role in shaping societies and intellectual progress.', FALSE, 0, NULL, NULL),
  ('710596d3-043d-5ada-89a6-55765f249a8a'::uuid, '528f1a5b-cbec-5916-9ede-277348d0c9c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Books have been a fundamental part of human culture for centuries, serving as repositories of knowledge, stories, and history.', FALSE, 1, NULL, NULL),
  ('52c980e4-7d5d-5225-aabb-9c8ed7ada32b'::uuid, '528f1a5b-cbec-5916-9ede-277348d0c9c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The invention of the printing press in the 15th century made books more accessible, leading to widespread literacy and the spread of ideas.', FALSE, 2, NULL, NULL),
  ('a7f7bddf-a8c3-5741-98fc-1d4e80b29338'::uuid, '528f1a5b-cbec-5916-9ede-277348d0c9c0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Initially, they were handwritten and available only to a select few.', FALSE, 3, NULL, NULL),
  ('0e6f5aab-0ef6-5b34-ae45-4b384240991f'::uuid, '529586ce-a199-5120-9265-b00b1be44c1a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'taking away from a word any reference to particular instances', FALSE, 0, NULL, NULL),
