  ('3f9bea54-9958-5bc4-b53c-d8b10a52c23f'::uuid, '52a0aea7-4e6b-531d-8883-0a135a3e75b7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Fusarium wilt disease will bring serious damage to cotton.', FALSE, 1, NULL, NULL),
  ('87c3c503-3e39-5647-9e64-5043e3cae151'::uuid, '52a0aea7-4e6b-531d-8883-0a135a3e75b7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Cotton price will increase with the spread of Fusarium wilt disease.', FALSE, 2, NULL, NULL),
  ('fc843693-ec46-5851-98cf-57d60d484b3e'::uuid, '52a0aea7-4e6b-531d-8883-0a135a3e75b7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Cotton price will decrease with the spread of Fusarium wilt disease.', TRUE, 3, NULL, NULL),
  ('3f5c2366-0139-53c7-8c5a-00368c499455'::uuid, '52a25f79-2852-554f-ba20-157197648d4f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The collars transmitted each animal''s position every four hours, for up to two years.', FALSE, 0, NULL, NULL),
  ('ef18dc89-0f88-52f4-8798-6283acbded43'::uuid, '52a25f79-2852-554f-ba20-157197648d4f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But in 2010 and 2011, Vanessa Hull of Michigan State University and her colleagues were given permission to attach GPS tracking collars to five pandas in the Wolong National Nature Reserve in China.', FALSE, 1, NULL, NULL),
  ('204caebf-17dc-56e1-a147-3d4cb423e511'::uuid, '52a25f79-2852-554f-ba20-157197648d4f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'We know very little about wild pandas because they are so rare and live in almost impenetrable forest.', FALSE, 2, NULL, NULL);
