  ('af060df5-ed6a-5dd1-a99f-ded14d7c7116'::uuid, '52ef75dc-2dad-5c78-9f7a-7fcd2d280159'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'People need time to make this adjustment in attitude and react badly to any attempt to rush them into an agreement.', FALSE, 0, NULL, NULL),
  ('dc85da3d-a45f-5050-b058-699bda4361d8'::uuid, '52ef75dc-2dad-5c78-9f7a-7fcd2d280159'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In general, there is a tendency to underestimate how long it takes to discuss and resolve an issue on which two people initially have different views.', FALSE, 1, NULL, NULL),
  ('3c1d495b-1219-580e-a426-0232314fd326'::uuid, '52ef75dc-2dad-5c78-9f7a-7fcd2d280159'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The reason is that achieving agreement requires people to accept the reality of views different from their own and to accept change or compromise.', FALSE, 2, NULL, NULL),
  ('e7e41fca-3af8-54c1-acc1-670702e55024'::uuid, '52ef75dc-2dad-5c78-9f7a-7fcd2d280159'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They (and probably you) have to be persuaded and helped to feel comfortable about the outcome that is eventually agreed.', FALSE, 3, NULL, NULL),
  ('6b4069ef-9824-5e3a-9488-03a8905d8c6f'::uuid, '52ef75dc-2dad-5c78-9f7a-7fcd2d280159'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It is not just a matter of putting forward a set of facts and expecting the other person immediately to accept the logic of the exposition.', FALSE, 4, NULL, NULL),
  ('c739c71a-91dd-520d-80bc-5fcf65730006'::uuid, '52fb1f41-bca7-5eba-8891-1b68ed27dc65'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They can be surprised by the results.', FALSE, 0, NULL, NULL),
  ('cea11f7b-c95c-5e26-875c-3bda78e2d9f2'::uuid, '52fb1f41-bca7-5eba-8891-1b68ed27dc65'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But a growing number of companies are setting up schemes to recruit young workers .', FALSE, 1, NULL, NULL),
  ('20a8aa8c-f37b-53b0-b5ab-85315d342105'::uuid, '52fb1f41-bca7-5eba-8891-1b68ed27dc65'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They are skeptical about young people''s skills and their readiness for work.', FALSE, 2, NULL, NULL),
  ('aa2cd835-584a-5a16-80f9-d6815e99b846'::uuid, '52fb1f41-bca7-5eba-8891-1b68ed27dc65'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Employers are often reluctant to hire young people, even though there are more than 850,000 unemployed 16 to 24-year-olds and UK businesses are struggling to fill one in five vacancies because of skills shortages.', FALSE, 3, NULL, NULL),
