  ('4f216b34-ae2f-5122-90fc-12a18f8e4aeb'::uuid, '535adedf-b4c0-5739-aa3c-a2abd39e66f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, the expansion of soy cultivation has been linked to deforestation and environmental degradation, especially in the Amazon.', FALSE, 3, NULL, NULL),
  ('f5741392-e3e0-52ea-bff2-2032a557edcb'::uuid, '5363b2ec-248b-58d2-aba7-e61abd0f3c54'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Black people are very underrepresented in clinical trials, especially cancer trials.', FALSE, 0, NULL, NULL),
  ('4ce78cb5-181f-50d8-a00d-c3f9191667b2'::uuid, '5363b2ec-248b-58d2-aba7-e61abd0f3c54'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They also have higher death rates from cancer.', FALSE, 1, NULL, NULL),
