  ('c57b8b16-7def-5da9-abbd-c61d483718a4'::uuid, '55d1e396-045c-515b-8a58-46c77cb7cb04'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Currency is a medium of exchange for goods and services.', FALSE, 0, NULL, NULL),
  ('8ffb2a3b-8776-5178-834a-c6857bf8dfad'::uuid, '55d1e396-045c-515b-8a58-46c77cb7cb04'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In the 21st century, a new form of currency has entered the vocabulary, the virtual currency.', FALSE, 1, NULL, NULL),
  ('b3733f6b-12d8-54db-b0de-7d84567c3347'::uuid, '55d1e396-045c-515b-8a58-46c77cb7cb04'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Virtual currencies such as bitcoins have no physical existence or government backing and are traded and stored in electronic form.', FALSE, 2, NULL, NULL),
  ('6c6fe810-599f-54bc-969d-3e1b80707338'::uuid, '55d1e396-045c-515b-8a58-46c77cb7cb04'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In short, it''s money, in the form of paper or coins, usually issued by a government and generally accepted at its face value as a method of payment.', FALSE, 3, NULL, NULL),
  ('3ce3828b-d6ba-5aef-b8d7-9e202dd5737f'::uuid, '55d45c9b-93f1-5acb-a1ed-67665710f5ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'via', FALSE, 0, NULL, NULL),
  ('d7f81555-3c77-5e0c-865a-2aff7f312dc1'::uuid, '55d45c9b-93f1-5acb-a1ed-67665710f5ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'towards', FALSE, 1, NULL, NULL),
