  ('9f80ade0-497e-5212-b9b7-c80bcf526e28'::uuid, '57911ecb-f3d2-55df-80d0-79e4940bfa2a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These ranged from the current UN Food and Agriculture Organization''s database to information hundreds of years old, gleaned from kitchen records and archeology.', FALSE, 2, NULL, NULL),
  ('1fe0ef51-ada4-5211-ba9f-2f3e043630cf'::uuid, '57911ecb-f3d2-55df-80d0-79e4940bfa2a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In order to establish whether diversity matters in the sea as well as on land, 11 marine biologists, along with three economists, have joined forces.', FALSE, 3, NULL, NULL),
