  ('90e124c0-2744-5b27-a06e-fd74dd30094b'::uuid, '5825f65a-8375-5946-bd4f-f7f1e3b1a488'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There is no reliable population data for the great white shark, but scientists agree that their number are decreasing precipitously.', FALSE, 1, NULL, NULL),
