  ('6f7e461e-e6f1-5760-8d88-95c3dcad2269'::uuid, '5896bede-2530-5eda-accb-885ae86da442'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'have sounded', FALSE, 3, 0, NULL),
  ('e352f547-bfc0-5733-9e03-3c0364fb718d'::uuid, '58c1543e-76a2-5e47-b8c2-42b97d3519f3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This shift in the way we approach photography raises important questions about the value of photographs in our lives and the way we document our experiences.', FALSE, 0, NULL, NULL),
  ('43f69760-1da9-5c8e-88b7-a3e6e1933f38'::uuid, '58c1543e-76a2-5e47-b8c2-42b97d3519f3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, this convenience has also led to the overconsumption of images, with many photos being taken and forgotten without ever being printed or cherished.', FALSE, 1, NULL, NULL),
  ('c8190857-0743-5114-9ad4-9827e11a9f83'::uuid, '58c1543e-76a2-5e47-b8c2-42b97d3519f3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In contrast, digital photography has made it incredibly easy for anyone to take and share photos instantly using smartphones and digital cameras.', FALSE, 2, NULL, NULL),
  ('ee607169-6adc-5300-875b-d9534b3bfb38'::uuid, '58c1543e-76a2-5e47-b8c2-42b97d3519f3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In the past, photography was a more deliberate and time-consuming process, with film cameras requiring careful composition and film development.', FALSE, 3, NULL, NULL),
  ('b6e7bac9-c036-56ac-a677-a774c3780432'::uuid, '58d6807d-5445-5e56-bcfb-10969ed5e173'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'preventative', FALSE, 0, NULL, NULL),
