  ('bfe70b7a-20b7-5cb9-a3c3-9e388f62c27b'::uuid, '5910a0e6-9f55-5e52-bf5e-9210cb6a086e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Genes tell cells what to do and when. But copying errors in those operating manuals - known as mutations - can lead to misspelled instructions that can change how cells operate.', FALSE, 0, NULL, NULL),
