  ('151180ca-bd9d-5ef7-9c75-d6163405ab29'::uuid, '592b1346-ebb1-5933-b134-ec44610f9d51'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'power', FALSE, 15, 3, NULL),
  ('323e46a0-e24e-597e-903b-c7468857b7ec'::uuid, '5931ec48-44f5-5df4-9e4c-dc19f00c9081'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Whereas play with stereotypically masculine toys, such as blocks and toy soldiers, is generally associated with the development of spatial skills and more aggressive behavior, playing with stereotypically feminine toys, such as baby dolls and stuffed animals, is associated with more nurturing behavior.', FALSE, 0, NULL, NULL),
  ('321c7e6e-96ed-5e52-b655-340f690c8b5e'::uuid, '5931ec48-44f5-5df4-9e4c-dc19f00c9081'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In general, strongly gender-typed toys are less supportive of the development of children''s physical, cognitive, and artistic skills than are gender-neutral or moderately gender-typed toys.', FALSE, 1, NULL, NULL),
  ('40ac9d4f-fd82-541d-b1a4-4f61db43d96f'::uuid, '5931ec48-44f5-5df4-9e4c-dc19f00c9081'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Therefore, playing predominantly with same-gender-typed toys limits the development of children''s action repertoires in accordance with gender stereotypes and thus contributes to the perpetuation of gender stereotypes.', FALSE, 2, NULL, NULL),
  ('5f6d835c-2432-58f7-9bbb-ae9a3134dadc'::uuid, '5931ec48-44f5-5df4-9e4c-dc19f00c9081'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Gender-typed toy play leads to the promotion of different skills in boys and girls, with girls practicing communal roles and boys practicing agentic roles.', FALSE, 3, NULL, NULL),
  ('9d46982d-28cd-53aa-b3ae-d013946c63d5'::uuid, '5931ec48-44f5-5df4-9e4c-dc19f00c9081'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This guides children''s activities in accordance with gender stereotypes and thus restricts their individual development potential.', FALSE, 4, NULL, NULL),
  ('3da3290f-ce2b-51cd-9ad2-68dc06da6450'::uuid, '5931ec48-44f5-5df4-9e4c-dc19f00c9081'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Play with sexualized dolls, such as Fashion Barbies, is even associated with a narrowing of perceived career options in girls.', FALSE, 5, NULL, NULL),
