  ('c3aa3a23-996e-5e27-8cec-60866cb609d1'::uuid, '59e14604-a104-50c1-8fd1-1ffc3c4489f1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The work also creates a constant state of cognitive load; as a result, individuals find themselves constantly worrying about work-related issues.', FALSE, 0, NULL, NULL),
