  ('7041048c-68a1-5057-b26d-88b1caa57a60'::uuid, '5a170912-1d00-58a1-8725-753e9d7894a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Perhaps they can acquire grammar like humans if they could only express it some other way.', FALSE, 0, NULL, NULL),
  ('fdb427d1-7443-52fb-b737-51251d518c3f'::uuid, '5a170912-1d00-58a1-8725-753e9d7894a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It does not follow from their lack of speech, however, that chimpanzees are incapable of language.', FALSE, 1, NULL, NULL),
  ('bf90611a-839f-514c-b421-d7084db166f9'::uuid, '5a170912-1d00-58a1-8725-753e9d7894a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Chimpanzees cannot speak because, unlike homo sapiens, their vocal cords are located higher in their throats and cannot be controlled as delicately as human vocal cords.', FALSE, 2, NULL, NULL),
  ('ee9f35bb-d331-5b84-991a-1068e8ce9cbd'::uuid, '5a170912-1d00-58a1-8725-753e9d7894a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A logical candidate for such a species is the chimpanzee, which shares 98.4% of the human genetic code.', FALSE, 3, NULL, NULL),
  ('94594401-572e-5e65-b317-348a6644d8bc'::uuid, '5a170912-1d00-58a1-8725-753e9d7894a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A simple way to disprove this hypothesis (the Innateness Hypothesis) is to demonstrate that other species have the capacity to speak but for some reason simply have not developed speech.', FALSE, 4, NULL, NULL),
  ('779d2fda-15d0-551c-af2b-1961afbf174d'::uuid, '5a1d54d9-f3ef-5cf1-8acb-e4ffbe2bd440'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'presented', FALSE, 0, 0, NULL),
