  ('73b901ff-538b-5dda-b061-31ece3e6fb55'::uuid, '5a3aa8c8-15d4-5a9c-925d-623da829f8e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Because the eye is so complex and perfect already.', FALSE, 0, NULL, NULL),
  ('09d8ece3-ab4b-5368-b838-1028eab4a18e'::uuid, '5a3aa8c8-15d4-5a9c-925d-623da829f8e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Because evidence of its ancestors is almost impossible to find.', TRUE, 1, NULL, NULL),
  ('cbe873fc-851f-5bc1-aec1-c1093409ec24'::uuid, '5a3aa8c8-15d4-5a9c-925d-623da829f8e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Because the eye cannot change without losing its usefulness.', FALSE, 2, NULL, NULL),
  ('c4de6e4e-80dc-5bb8-90fa-2df8f6bf9fdc'::uuid, '5a3aa8c8-15d4-5a9c-925d-623da829f8e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Because other species have more complex eyes.', FALSE, 3, NULL, NULL),
  ('17a6d737-fe2c-5b91-8aac-2cf8c2abeaa8'::uuid, '5a3f0323-177a-529f-83d6-06c01ca2594d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Despite his numerous contributions, many of his projects remained unfinished at his death in 1519, leaving a legacy of unfinished potential.', FALSE, 0, NULL, NULL),
  ('8d4b65a3-a7da-569d-a790-8b730f9733c0'::uuid, '5a3f0323-177a-529f-83d6-06c01ca2594d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'His early life in Florence fostered a profound interest in science, art, and invention.', FALSE, 1, NULL, NULL),
  ('0c2e3f09-e1d0-53be-be46-df61ea0bb276'::uuid, '5a3f0323-177a-529f-83d6-06c01ca2594d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'By the early 1500s, da Vinci had painted the Mona Lisa, a masterpiece that exemplifies his keen observation and innovative techniques.', FALSE, 2, NULL, NULL),
  ('1157a111-3386-5cdb-ab5e-1833d5705652'::uuid, '5a3f0323-177a-529f-83d6-06c01ca2594d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Leonardo da Vinci was born in 1452 in Vinci, Italy, becoming a pivotal figure of the Renaissance.', FALSE, 3, NULL, NULL),
  ('cb32145a-ea09-5a3e-9f12-83a2fead216b'::uuid, '5a735464-dc24-57dc-a1de-3a95ac650102'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But though the possibility of living a long and happy life is greater than ever before, every day we witness the incredible slaughter of men, women and children on the roads.', FALSE, 0, NULL, NULL),
  ('ce32c284-e035-5dfa-8924-b5d052033c9e'::uuid, '5a735464-dc24-57dc-a1de-3a95ac650102'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'From the health point of view we are living in a marvelous age. We are immunized from birth against many of the most dangerous diseases.', FALSE, 1, NULL, NULL),
  ('b0b8150b-19f0-534c-ae8c-6f0d85f4a140'::uuid, '5a735464-dc24-57dc-a1de-3a95ac650102'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A large number of once fatal illnesses can now be cured by modern drugs and surgery. It is almost certain that one day remedies will be found for the most stubborn remaining diseases.', FALSE, 2, NULL, NULL),
  ('d75cf13e-cfb6-585f-963f-a98313fd53ff'::uuid, '5a735464-dc24-57dc-a1de-3a95ac650102'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Man versus the motor-car!It is a never-ending battle which man is losing.', FALSE, 3, NULL, NULL),
  ('ceb7ed4c-ec40-5f0e-adc9-ede3adedfbdb'::uuid, '5a735464-dc24-57dc-a1de-3a95ac650102'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The expectation of life has increased enormously.', FALSE, 4, NULL, NULL),
  ('784f8daf-2d02-5109-bce3-7c819311eb37'::uuid, '5aa0cd16-6f67-53e8-b6e6-7def3f2dd380'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'revolutionize', FALSE, 0, 0, NULL),
