  ('47c703e7-4ce9-5086-b2b2-ef7ea6e58042'::uuid, '5bcfd34d-1136-5d48-a487-11a99d0aa0c3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Great Wall of China was initially built over several dynasties, starting around the 7th century BC.', FALSE, 0, NULL, NULL),
  ('611a6983-c153-585f-b109-dcb8dfd97cc3'::uuid, '5bcfd34d-1136-5d48-a487-11a99d0aa0c3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Over centuries, the wall was expanded and fortified, becoming one of the most significant symbols of China.', FALSE, 1, NULL, NULL),
  ('81f08371-233d-59d5-8b49-e6d50b01c094'::uuid, '5bcfd34d-1136-5d48-a487-11a99d0aa0c3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Its construction was aimed at protecting the Chinese states against invasions and raids from various nomadic groups.', FALSE, 2, NULL, NULL),
  ('c0ad2e8f-4cc8-5ede-822e-445be450bf02'::uuid, '5bcfd34d-1136-5d48-a487-11a99d0aa0c3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Despite its strength, the wall was not always successful in preventing invasions, showing the complexity of maintaining such a vast defense system.', FALSE, 3, NULL, NULL),
