  ('65dd6e37-63a8-58b1-9f25-9a5335655b31'::uuid, '5bf5f4f2-edcf-56fc-8f87-f1b2ec39882f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There were three reasons why the building of St Petersburg meant Russian Tsar Peter I became famous for being a cruel leader. Many workers died either on the journey or from disease and overwork in the city build itself. The Tsar did not pay his workers or provide food and because of this, many more died.', FALSE, 0, NULL, NULL),
  ('aa355ada-ec2c-51ec-804b-21f6b8dc96cc'::uuid, '5bf5f4f2-edcf-56fc-8f87-f1b2ec39882f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Russian Tsar Peter I wanted a new capital city so that he could compete with other European capitals. He built the city on a river so that it would be easier to bring workers and materials into the city to help with the building process.', FALSE, 1, NULL, NULL),
  ('b9c2b927-e076-5a0e-b5fd-e52be95c5fa3'::uuid, '5bf5f4f2-edcf-56fc-8f87-f1b2ec39882f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There were three challenges with the construction of St Petersburg: the unsuitability of the wet land in the location he chose, the difficulty of transporting builders to the remote location, and the poor conditions they were working in and the lack of raw materials for the construction process.', TRUE, 2, NULL, NULL),
  ('2178b708-e700-51b0-a3ba-173822c4f145'::uuid, '5bf5f4f2-edcf-56fc-8f87-f1b2ec39882f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'St Petersburg was the first city to be built on water and this is why the construction process was so challenging. It was such a big project requiring so many men and materials that building in other parts of Russia stopped while the city was being built.', FALSE, 3, NULL, NULL),
  ('bae8180d-2dee-5f3f-8930-5c4b5b42269a'::uuid, '5c42e8f7-12d0-5d5d-9d0e-39470f3a6246'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'decals', FALSE, 0, 0, NULL),
