  ('33922f77-d1ea-5711-9ef9-4f37b13c7573'::uuid, '5cbed9f9-8565-593c-9fe0-36410aa09782'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Consequently, this evolution has made computers accessible to the vast majority of people, changing the way we live, work, and communicate.', FALSE, 0, NULL, NULL),
