  ('b9f4ca66-b446-578e-8e88-a449fbe270b9'::uuid, '5e25dc38-cb77-536b-86e3-ae87322568d4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Hop a plane across several time zones, and you may end up with what scientists call circadian dysrhythmia, also known as jet lag.', FALSE, 0, NULL, NULL),
  ('65670f82-94fe-5358-900c-f4271af9ed90'::uuid, '5e25dc38-cb77-536b-86e3-ae87322568d4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It’s a temporary sleep disorder where your body’s internal clock isn’t in sync with the time cues in your destination.', FALSE, 1, NULL, NULL),
  ('2673d527-8317-5e46-9c07-59ae2830019d'::uuid, '5e25dc38-cb77-536b-86e3-ae87322568d4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'You can use strategically timed naps and caffeine to ease into your new time zone.', FALSE, 2, NULL, NULL),
  ('bb2c6f43-7ab8-51be-a5b2-0d1b7a20d912'::uuid, '5e25dc38-cb77-536b-86e3-ae87322568d4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But jet lag doesn’t have to wreck your trip.', FALSE, 3, NULL, NULL),
  ('ac0e285e-2996-5e2a-a8ec-a94b64418669'::uuid, '5e25dc38-cb77-536b-86e3-ae87322568d4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It’s also why you might doze off at lunch on your first day in London or be unable to get to sleep the first couple of nights of a vacation to Japan.', FALSE, 4, NULL, NULL),
