  ('23c63c0f-ff1a-58b3-98b1-7462e160b050'::uuid, '60cbf620-0742-5e2d-8183-3654502172d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Most meat eaten by Americans comes from concentrated animal feeding operations where animals have scant legal protections.', FALSE, 0, NULL, NULL),
  ('51248efd-98e8-5a6d-8c23-eb706efd3f16'::uuid, '60cbf620-0742-5e2d-8183-3654502172d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It’s unsurprising, then, that footage depicting neglect and mistreatment of animals has caused reputational damage to the food companies that were unaware of practices on the farms from which they source.', FALSE, 1, NULL, NULL),
  ('3f6910d4-a22a-5629-bb3a-796201ef3cb0'::uuid, '60cbf620-0742-5e2d-8183-3654502172d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For instance, the dairy company Fairlife faced lawsuits after undercover footage apparently showed abuse of its cows.', FALSE, 2, NULL, NULL),
  ('1302adad-6e11-55c1-a5d6-6a7c6178902e'::uuid, '60cbf620-0742-5e2d-8183-3654502172d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This barren legal landscape has led to a race to the bottom on animal welfare, resulting in animals bred to grow so fast that their vital organs can painfully lose function.', FALSE, 3, NULL, NULL),
