  ('c8a45400-c95d-58e4-ae40-a10008c6aeec'::uuid, '6122d6f1-79aa-5f92-ad00-75121431cb2f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It incorporates energy-efficient systems, renewable energy sources, and green roofs.', FALSE, 0, NULL, NULL),
  ('99da1a96-01a5-51ca-a521-ac2e0467cc1b'::uuid, '6122d6f1-79aa-5f92-ad00-75121431cb2f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These practices not only reduce the carbon footprint but also can lead to cost savings over time.', FALSE, 1, NULL, NULL),
  ('a0b94ab3-83e2-5b37-9eda-beb7d07d809a'::uuid, '6122d6f1-79aa-5f92-ad00-75121431cb2f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, the initial investment in green technologies can be higher compared to traditional construction methods.', FALSE, 2, NULL, NULL),
  ('7bf41f0c-a3fa-5c9d-bcae-2b3bead2d1bb'::uuid, '6122d6f1-79aa-5f92-ad00-75121431cb2f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Green architecture focuses on minimizing the environmental impact of buildings.', FALSE, 3, NULL, NULL),
  ('73be0cc6-e307-5a0d-aa77-eda991c30def'::uuid, '61264089-2e71-58fc-840c-9f32f298bd1e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Traditionally, farmers practiced crop rotation, whereby different crops were grown in succession on the same area of land.', FALSE, 0, NULL, NULL),
  ('c5ccba9f-ada5-5a2e-9065-ecc11745ee26'::uuid, '61264089-2e71-58fc-840c-9f32f298bd1e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, after 1945, monoculture became increasingly prevalent and now supplies not only most of our food but also a significant share of non-food crops like cotton.', FALSE, 1, NULL, NULL),
  ('e13d8729-dc24-5f61-8e1b-e83ade0ebadd'::uuid, '61264089-2e71-58fc-840c-9f32f298bd1e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Yet this may be the greatest experiment that humans have conducted without a clear blueprint.', FALSE, 2, NULL, NULL),
