  ('a9325993-0077-539e-be63-9c02286440d3'::uuid, '61b02933-4f9a-5d2d-9f65-ca87ba2eb114'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'More and more people are choosing to live in cities.', FALSE, 0, NULL, NULL),
  ('fc0debae-a951-5fca-8188-9b242e520b9e'::uuid, '61b02933-4f9a-5d2d-9f65-ca87ba2eb114'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Yet large numbers of people are unable for various reasons to move to cities — skills mismatches, reluctance to sell land at a loss, and sometimes because of explicit policy restrictions that limit people’s movement within countries.', FALSE, 1, NULL, NULL),
  ('983de292-7050-5a24-8f5f-1addb1b86644'::uuid, '61b02933-4f9a-5d2d-9f65-ca87ba2eb114'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These choices have major implications for a person’s standard of living, particularly in developing countries.', FALSE, 2, NULL, NULL),
  ('4a0ef1bf-cfd8-596a-bd5c-3d629b9e18fc'::uuid, '61b02933-4f9a-5d2d-9f65-ca87ba2eb114'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They offer better opportunities, better services, and sanctuary from conflict and the effects of climate change influences.', FALSE, 3, NULL, NULL),
