  ('36f80a9b-1344-5b22-b959-25baedad27e8'::uuid, '61da0661-4da5-5823-8749-692ff92f0cdb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Consequently, species that adapt well to their environment tend to survive and reproduce, passing on their traits to future generations.', FALSE, 0, NULL, NULL),
  ('ddcad38d-6269-5c54-a2a6-0fdaecdf1c9f'::uuid, '61da0661-4da5-5823-8749-692ff92f0cdb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These changes allow organisms to better adapt to their environment.', FALSE, 1, NULL, NULL),
  ('ca861401-8441-5443-ab6a-8235ead99e0a'::uuid, '61da0661-4da5-5823-8749-692ff92f0cdb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Darwin''s theory of evolution by natural selection provides a framework for understanding the diversity of life on Earth.', FALSE, 2, NULL, NULL),
  ('2d3c4740-2200-5e24-bfaf-cddefd919bb9'::uuid, '61da0661-4da5-5823-8749-692ff92f0cdb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It argues that species evolve over time due to changes in heritable physical or behavioral traits.', FALSE, 3, NULL, NULL),
  ('79e21ca9-894c-50c4-ba0f-9015cd146530'::uuid, '61e2a1f1-cd00-55e4-9653-ce3682fa7eb7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Despite its size and power, the Armada was defeated by the English navy and adverse weather conditions.', FALSE, 0, NULL, NULL),
