  ('43549681-60dd-5299-b55c-355a24465726'::uuid, '61e2a1f1-cd00-55e4-9653-ce3682fa7eb7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In 1588, the Spanish Armada, a massive fleet sent by King Philip II of Spain, attempted to invade England.', FALSE, 2, NULL, NULL),
