  ('c83d121c-4a2e-577a-8250-ce5c89c63867'::uuid, '6230732b-b665-55ee-b8e1-2f67bede83b3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The hardest mineral is determined by Mohs Scale of Hardness. Diamonds are close to glass in hardness, and Gypsum is known as the softest substance on Mohs.', FALSE, 0, NULL, NULL),
  ('64ccdb88-8a59-5e6f-a59c-748a449f9955'::uuid, '6230732b-b665-55ee-b8e1-2f67bede83b3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Mohs Scale of Hardness is created to rate minerals. Hardness refers to a material’s ability to scratch other objects and different materials are received different rank on this scale.', TRUE, 1, NULL, NULL),
  ('8d26b187-da31-50af-b88e-2365cdb50aa3'::uuid, '6230732b-b665-55ee-b8e1-2f67bede83b3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Friedrich Mohs was the first person to realize how hard diamonds are. The professor tells the students to look in their textbooks so that they can learn about the hardness of them.', FALSE, 2, NULL, NULL),
