  ('db9d35d3-3f4a-58aa-a20c-ae10b4266cdf'::uuid, '62a437e3-fd95-53b7-95a5-8cfead7c0328'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'festiveness', FALSE, 15, 3, NULL),
  ('72356153-85fd-5610-b636-d5734cf32040'::uuid, '62ab7cd7-16ea-5043-9a8e-08bfd8ddb0f1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Though it cannot be guaranteed that gene drives can completely eradicate malaria, they have already been proven to be effective in some parts of the world. In the future, gene drives may be the most effective solution.', TRUE, 0, NULL, NULL),
  ('e73edf73-3294-56f2-a18f-9e4e0c6210a3'::uuid, '62ab7cd7-16ea-5043-9a8e-08bfd8ddb0f1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A gene editing technology called CRISPR has been used by scientists to deal with Malaria. Its aim is to eradicate malaria, but it turned out that such technology could only control the disease within Africa.', FALSE, 1, NULL, NULL),
  ('3efe4fed-1df3-52a1-a9ba-c231685324fc'::uuid, '62ab7cd7-16ea-5043-9a8e-08bfd8ddb0f1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Malaria is only transmitted by mosquitoes, so the only method to eradicate the disease is to wipe out the whole species of malaria-carrying mosquito. Currently, only Africa has successfully eradicated malaria, but in the future the disease may disappear globally.', FALSE, 2, NULL, NULL),
  ('80e579ec-b1ef-5f2b-aa63-aa6b22ab97a3'::uuid, '62ab7cd7-16ea-5043-9a8e-08bfd8ddb0f1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Africa has the most species of mosquito in the whole world, and this is the reason that malaria occurs mainly in Africa. A team from London had invented a new technology to help the African people with the disease, and they are confident to eradicate it in the future.', FALSE, 3, NULL, NULL),
  ('6b44884a-c17a-5a69-b2ba-1d9e0c6381e8'::uuid, '62d4ae4e-7d00-5a7a-b5bc-0e1ccb661f4d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Teachers will host online sessions for students to discuss.', FALSE, 0, NULL, NULL),
  ('7b686d7f-89bf-563c-8aca-cb3e721e0df2'::uuid, '62d4ae4e-7d00-5a7a-b5bc-0e1ccb661f4d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Students will also think about the knowledge when they''re writing essays.', FALSE, 1, NULL, NULL),
  ('91a18b52-f4de-5e58-8cd5-1f1d0c93d922'::uuid, '62d4ae4e-7d00-5a7a-b5bc-0e1ccb661f4d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'By doing so, students can leave comments and go over all the information they have learned.', FALSE, 2, NULL, NULL),
  ('f823f3b5-f6e5-5329-b12b-5f8af2ffc6a1'::uuid, '62d4ae4e-7d00-5a7a-b5bc-0e1ccb661f4d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'When students are learning or taking exams, they will apply or recall the knowledge they''ve acquired.', FALSE, 3, NULL, NULL),
  ('6aa18323-0509-5a90-b6ae-6251ff980f36'::uuid, '62d791e0-c197-55df-b8bb-d52d3fb3bb6c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'demonstration', FALSE, 0, 0, NULL),
