  ('373cb3e3-6ec0-53e7-9f93-913940871b71'::uuid, '63c0b354-7f99-5ed1-b86e-7fdf4b37d638'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'More than 50 million Americans engage in the practice, collectively undertaking an unwitting experiment on a vast scale.', FALSE, 0, NULL, NULL),
  ('8c500bd2-0c98-5505-bde4-edbd6900a48f'::uuid, '63c0b354-7f99-5ed1-b86e-7fdf4b37d638'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'According to experts, feeding birds is probably the most common way in which people interact with wild animals today.', FALSE, 1, NULL, NULL),
  ('93022a00-0e52-5d4a-b496-51a6ca3eadf9'::uuid, '63c0b354-7f99-5ed1-b86e-7fdf4b37d638'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Is what we''re doing good or bad for birds?', FALSE, 2, NULL, NULL),
  ('7ac45042-1b4a-56aa-8f99-c1b789418254'::uuid, '63c0b354-7f99-5ed1-b86e-7fdf4b37d638'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Recently, researchers at the Cornell Lab of Ornithology sought to answer this question, analyzing nearly three decades'' worth of data from a winter-long survey called Project Feeder Watch.', FALSE, 3, NULL, NULL),
  ('bc71a348-84fe-5e55-a9cf-498e739a4e17'::uuid, '63c0b354-7f99-5ed1-b86e-7fdf4b37d638'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Preliminary results suggest the species visiting our feeders the most are faring exceptionally well in an age when one-third of the continent''s birds need urgent conservation.', FALSE, 4, NULL, NULL),
  ('19cc4bf3-7b2b-5af7-b97b-06ed1107ac56'::uuid, '63df80f6-64ba-545b-ab6f-53a9a4629662'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'infection', FALSE, 0, NULL, NULL),
  ('d9dd9112-9b1f-5d21-8d96-5422caf00fe6'::uuid, '63df80f6-64ba-545b-ab6f-53a9a4629662'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'cost', TRUE, 1, NULL, 2),
