  ('93c5053e-b4a4-593b-a8fe-07f11594d114'::uuid, '63df80f6-64ba-545b-ab6f-53a9a4629662'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'alternative', TRUE, 4, NULL, 0),
  ('397cad5e-cedd-5241-b3cc-816056bc440a'::uuid, '63df80f6-64ba-545b-ab6f-53a9a4629662'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'depression', TRUE, 5, NULL, 1),
  ('1a6019d6-cb28-550d-9b31-81f7c8893687'::uuid, '63df80f6-64ba-545b-ab6f-53a9a4629662'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'age', FALSE, 6, NULL, NULL),
  ('aa1ae232-8cb0-52a6-88c8-cf8e543100ec'::uuid, '63ee9798-2076-5d1c-8de4-7aa547238f4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Glass cups offer a different appeal, primarily through their transparency.', FALSE, 0, NULL, NULL),
  ('5ea8b20c-8427-5b40-ac6c-c3c1886ba6bc'::uuid, '63ee9798-2076-5d1c-8de4-7aa547238f4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They allow the drinker to see the beverage, making them popular for serving layered or colorful drinks.', FALSE, 1, NULL, NULL),
  ('c40adfee-398d-5c47-a116-830f5fb124a6'::uuid, '63ee9798-2076-5d1c-8de4-7aa547238f4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Thus, glass cups are more suitable for cold beverages or those intended to be consumed quickly.', FALSE, 2, NULL, NULL),
  ('c2fdd00b-a37f-5e73-a9ff-1c4a34ccd936'::uuid, '63ee9798-2076-5d1c-8de4-7aa547238f4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, glass is a poor insulator compared to ceramic, causing the contents to lose heat faster.', FALSE, 3, NULL, NULL),
  ('64b710f6-e40b-5849-ab9d-21147760bda4'::uuid, '63ff25fa-31cf-506d-bfaf-2b99ba52758c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Polybius believed that this progression could be halted at least temporarily by keeping the three elements held in some kind of balance, and the Romans achieved this not by abstract reasoning but by trial and error.', FALSE, 0, NULL, NULL),
  ('69989f10-b77b-5c19-8ea2-c3e6800369a6'::uuid, '63ff25fa-31cf-506d-bfaf-2b99ba52758c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The constitution was then at its healthiest, while that of the Carthaginians was already in decline because, in Polybius’ opinion it was becoming more democratic.', FALSE, 1, NULL, NULL),
  ('0f52238d-b774-5425-8b9b-9998a6764a5f'::uuid, '63ff25fa-31cf-506d-bfaf-2b99ba52758c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Roman state was tested almost to destruction by the defeat at Cannae by the Carthaginians led by Hannibal - and according to the historian Polybius it was only what he called the "peculiar virtues" of the Roman constitution that allowed it to survive this crisis.', FALSE, 2, NULL, NULL),
  ('6e5765fc-c8b2-5d5c-955c-30c5f70710eb'::uuid, '63ff25fa-31cf-506d-bfaf-2b99ba52758c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Now, Polybius, if we forget Aristotle for the moment, was to become the main authority on the three types of constitution and the cycles through which they pass, becoming more corrupt as they do so: kingship turns into tyranny, aristocracy to oligarchy, and democracy into mob rule.', FALSE, 3, NULL, NULL),
  ('c019daad-b8d6-5879-8cbd-820f3ff968c5'::uuid, '64028981-a2e0-518d-8b74-e08e7ffa7126'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'zone', FALSE, 0, NULL, NULL),
  ('c5bd8937-a9e4-5199-93df-1974e70ad46d'::uuid, '64028981-a2e0-518d-8b74-e08e7ffa7126'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'untouched', TRUE, 1, NULL, 2),
