  ('14e56f4d-389b-5675-b1ee-6c470d1ed0f8'::uuid, '640ef34a-ddf6-59d2-8ef6-1c579310d944'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Print media such as newspapers and magazines are replaced by the use of television commercials. The TV commercials are relatively cheaper, which were once worth the money that advertisers spent. This lets the advertiser get more value from its money.', FALSE, 0, NULL, NULL),
  ('2c9c4ca0-d750-5864-a4d5-d6bb33cd6f67'::uuid, '640ef34a-ddf6-59d2-8ef6-1c579310d944'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The costs involved with advertisements have been ranked. Internet advertisements can be targeted to a specific audience and are usually cheap. As for television commercials, they can cost millions of dollars.', FALSE, 1, NULL, NULL),
  ('1d3411ca-0af2-583d-909e-cde181b5cd70'::uuid, '640ef34a-ddf6-59d2-8ef6-1c579310d944'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Television will no longer be the largest marketing segment and more people are getting their news from the internet nowadays. While TV commercials can cost millions of dollars to make and air, it is possible to advertise to specific groups of people on the Internet.', TRUE, 2, NULL, NULL),
