  ('000c01f3-547a-5eec-87de-61206f098387'::uuid, '647ee61d-a267-5f3f-a60d-88a7141f3518'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It has transformed industries, from retail and entertainment to education and healthcare.', FALSE, 1, NULL, NULL),
  ('a3552d9f-3ca2-541c-af9b-3af172087ed7'::uuid, '647ee61d-a267-5f3f-a60d-88a7141f3518'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In just a few decades, the internet has become an integral part of our daily lives.', FALSE, 2, NULL, NULL),
  ('2c8dce57-5c65-597f-887c-7cbb1cf7e03f'::uuid, '647ee61d-a267-5f3f-a60d-88a7141f3518'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The internet has also opened up new opportunities for businesses to reach global markets and for individuals to connect with people from around the world.', FALSE, 3, NULL, NULL),
  ('10a1d6c1-ba84-56a0-b5f8-bb16bae95305'::uuid, '648985fc-7d69-523b-bbde-29d503c1cfee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Children are more likely to forgive those who are "in the group".', TRUE, 0, NULL, NULL),
  ('38339e2d-cf51-5c37-99fa-b90eff877bae'::uuid, '648985fc-7d69-523b-bbde-29d503c1cfee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Forgiveness can help restore their relationship and reduce future conflict.', FALSE, 1, NULL, NULL),
  ('dec30cab-75f4-51eb-9a1b-2a81d41b6c00'::uuid, '648985fc-7d69-523b-bbde-29d503c1cfee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Children are more likely to forgive the person who apologizes.', TRUE, 2, NULL, NULL),
  ('86e557c0-7b9c-5d23-a157-620d9e442d4b'::uuid, '648985fc-7d69-523b-bbde-29d503c1cfee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Children can forgive just like adults.', FALSE, 3, NULL, NULL),
  ('0d5f7143-57ba-5e70-a8d1-2c824d9c07b0'::uuid, '648985fc-7d69-523b-bbde-29d503c1cfee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The more advanced the theory of mind skills, the less likely a child is to forgive.', FALSE, 4, NULL, NULL),
  ('0b84ec12-5c90-5cb7-b2ee-2a369ddd2c97'::uuid, '64dc42af-eafe-5fd9-a006-57baf1a3400c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Mass transportation revised the social and economic fabric of the American city in three fundamental ways.', FALSE, 0, NULL, NULL),
  ('421be1d5-5164-59df-9a19-e321efb4a7a8'::uuid, '64dc42af-eafe-5fd9-a006-57baf1a3400c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The new accessibility of land around the periphery of almost every major city sparked an explosion of real estate development and fueled what we now know as urban sprawl.', FALSE, 1, NULL, NULL),
  ('41e4aa04-6882-5559-ab10-c5cce516c581'::uuid, '64dc42af-eafe-5fd9-a006-57baf1a3400c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Now those who could afford it could live far removed from the old city center and still commute there for work, shopping, and entertainment.', FALSE, 2, NULL, NULL),
  ('a67ec936-ff5e-530d-a1c3-e8441a059963'::uuid, '64dc42af-eafe-5fd9-a006-57baf1a3400c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In 1850, for example, the borders of Boston lay scarcely two miles from the old business district; by the turn of the century the radius extended ten miles.', FALSE, 3, NULL, NULL),
  ('f8832a44-028e-51b4-94d2-0458fad29692'::uuid, '64dc42af-eafe-5fd9-a006-57baf1a3400c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It catalyzed physical expansion, it sorted out people and land uses, and it accelerated the inherent instability of urban life. By opening vast areas of unoccupied land for residential expansion, the omnibuses, horse railways, commuter trains, and electric trolleys pulled settled regions outward two to four times more distant form city centers than they were in the pre-modern era.', FALSE, 4, NULL, NULL),
  ('7e05c87e-dc4c-58c7-a4a8-23895a5d6a82'::uuid, '64ee4f92-c76f-5320-b377-05c7846bfcdc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'People who are involved in education need to think about the way they teach. It is important that young people leave school with the key skills they need to succeed in the workplace but they do not have these skills today.', TRUE, 0, NULL, NULL),
  ('32562c8a-ba09-5081-b2a5-28bf29915afb'::uuid, '64ee4f92-c76f-5320-b377-05c7846bfcdc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Schools must work harder to train students to become good managers so that they can lead and influence other people. This is the most important skill that young people need if they want to get - and keep - their dream job.', FALSE, 1, NULL, NULL),
  ('830342a7-725d-5dd9-9f53-e2538a0cc4c2'::uuid, '64ee4f92-c76f-5320-b377-05c7846bfcdc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Young people need to know how to talk to people around the world. Technology has changed the way business people meet; meetings are no longer held in one building but instead an international group of people meet online.', FALSE, 2, NULL, NULL),
  ('df766322-9563-5592-a554-9006ea34d964'::uuid, '64ee4f92-c76f-5320-b377-05c7846bfcdc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Young people are being taught just seven key workplace skills and one expert believes they will find it difficult to get work in the future as a result. He therefore suggests that schools need to change the skills that they teach in the future.', FALSE, 3, NULL, NULL),
  ('215262f8-091b-5c05-b42f-6c0cdc28fc36'::uuid, '64f0e331-954d-5c70-8b46-9865c94270b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There are several kinds of improvisation.', TRUE, 0, NULL, NULL),
  ('2932536e-84f2-5735-8992-fd74e1a3c842'::uuid, '64f0e331-954d-5c70-8b46-9865c94270b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'People disagree about what improvisation is.', TRUE, 1, NULL, NULL),
  ('79b9a92c-68b8-5a28-8e64-befa5ae8774d'::uuid, '64f0e331-954d-5c70-8b46-9865c94270b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'No musicians have recorded improvisation.', FALSE, 2, NULL, NULL),
  ('15507f24-4848-506e-9468-f372da982680'::uuid, '64f0e331-954d-5c70-8b46-9865c94270b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The dictionary does not define improvisation.', FALSE, 3, NULL, NULL),
  ('4f24af43-e836-5783-989d-23bac248f1ee'::uuid, '64ff188c-4598-53fc-a687-9a34900762a4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Microorganisms resistant to drugs', TRUE, 0, NULL, NULL),
