  ('02a86a03-3c02-5f58-a66f-6354c30173d1'::uuid, '650ed526-676c-5708-8981-5f65a59a1685'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Children from disadvantaged backgrounds frequently have less access to quality schooling.', FALSE, 1, NULL, NULL),
  ('021e2259-5b84-5858-9024-430fea925b9e'::uuid, '650ed526-676c-5708-8981-5f65a59a1685'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This lack of access hampers their future opportunities and perpetuates cycles of poverty.', FALSE, 2, NULL, NULL),
