  ('d72249ff-6f97-55cf-b7ce-9af624e7844c'::uuid, '6541eaf3-f9cc-5498-a696-efa6196a8cd0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'From outside Wales, too, it is the rugby that commonly defines the nation - with the sport providing both widespread interest and one of the few positive associations of outsiders'' perceptions of Wales.', FALSE, 0, NULL, NULL),
  ('fb1fd280-6cfe-5d01-8fc3-0dc98ac9ceec'::uuid, '6541eaf3-f9cc-5498-a696-efa6196a8cd0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In many ways rugby in Wales defines what Wales is and what people in Wales share.', FALSE, 1, NULL, NULL),
  ('b3963de0-e211-5b28-88f7-011a5a84dbea'::uuid, '6541eaf3-f9cc-5498-a696-efa6196a8cd0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Rugby in Wales is a particularly strong example of this phenomenon, being perhaps the main thing that unites people in Wales.', FALSE, 2, NULL, NULL),
  ('44ba74d3-2da6-5fd3-8923-732f758e3357'::uuid, '6541eaf3-f9cc-5498-a696-efa6196a8cd0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Citizens commonly identify with their nation in the context of major sporting events: imagining the nation is easier when there is a national team playing another nation (Hobsbawm, 1990).', FALSE, 3, NULL, NULL),
  ('b64ca50c-c1e6-5b84-91bb-47ac587296ea'::uuid, '65478842-b94e-5aef-a9aa-20f6c408f32b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The telescope is intended to work with the Hubble Space telescope to explore space.', FALSE, 0, NULL, NULL),
