  ('31b59f7f-79a4-538e-8928-3a6e5a09e73d'::uuid, '65478842-b94e-5aef-a9aa-20f6c408f32b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'More than 10 billion dollars were spent to build the James Webb telescope.', FALSE, 2, NULL, NULL),
