  ('be703e8d-5956-59f1-b4a7-ea95966b7050'::uuid, '675c3e0d-c88c-5495-bb88-15bfd0537551'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The two exchanged 25,000 pages of letters between 1915 and 1946, during which time she found her voice as an artist: first, through her flower paintings, and later, through landscapes and surrealistic still lifes inspired by her mountainous, skull-studded surroundings in New Mexico.', FALSE, 1, NULL, NULL),
  ('e7a96889-89ad-50ae-a81f-0044bc27cd48'::uuid, '675c3e0d-c88c-5495-bb88-15bfd0537551'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'She did, however, leave a long trail of interviews and letters that reveal how she approached her painting practice—and the rituals, experiences, and environments that inspired her.', FALSE, 2, NULL, NULL),
