  ('16f793fc-1056-5633-bb9d-b2d595642d0d'::uuid, '67a69010-d508-55f3-be94-f89600f3b495'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Coral reefs support more marine life than any other ocean ecosystem and are, not surprisingly, a favorite pursuit for many divers.', FALSE, 1, NULL, NULL),
  ('47232ab5-aa52-5baf-ad95-2d2f62f22440'::uuid, '67a69010-d508-55f3-be94-f89600f3b495'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But as well as being physically and biologically spectacular, coral reefs also sustain the livelihoods of over half a billion people.', FALSE, 2, NULL, NULL),
  ('0568ee5d-689b-5420-b06b-5e8d0b9b78a3'::uuid, '67a69010-d508-55f3-be94-f89600f3b495'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In combination with the very real threat of climate change, which could lead to increased seawater temperatures and ocean acidification, we start to arrive at some quite frightening scenarios.', FALSE, 3, NULL, NULL),
