  ('ec515cba-5805-5c4c-8b29-40e3c953006a'::uuid, '69ceb348-475d-57c4-a13f-81d1c21cd90f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Reading also is special because, unlike language, most children have to be taught to read, write and spell.', FALSE, 0, NULL, NULL),
  ('03d827e9-d3b2-51cd-b972-0cf18138fad7'::uuid, '69ceb348-475d-57c4-a13f-81d1c21cd90f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'So though we may be predisposed to being able to read and usually have the abilities necessary to master reading, it is something that most of us only accomplish through the direct help of others.', FALSE, 1, NULL, NULL),
  ('838626c7-3a07-59b8-8b0c-65b505006a0b'::uuid, '69ceb348-475d-57c4-a13f-81d1c21cd90f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'So reading is a very special ability that we have.', FALSE, 2, NULL, NULL),
  ('f6514fdc-2853-596a-99cd-6d5c01ce76e5'::uuid, '69ceb348-475d-57c4-a13f-81d1c21cd90f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Humans appear to be the only species which is able to translate their communication into another medium, and in this case the medium provides a semi-durable record of the elements of the communication.', FALSE, 3, NULL, NULL),
