  ('4b17c535-b94a-5080-bc4f-f6b2bbf822fe'::uuid, '6a114e4b-0378-5b8a-86cd-903376f2a5da'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Ethical considerations are paramount in the medical profession.', FALSE, 1, NULL, NULL),
