  ('7caf9d9d-b731-560e-af59-4bd0802700e1'::uuid, '6a294581-c0be-56ad-8c2e-65daa81b84d2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Practically speaking, however, it is about as difficult to present all sides of an issue as it is to invite candidates from all political parties to a presidential debate.', FALSE, 1, NULL, NULL),
  ('a7cdc3ef-7157-5990-8016-15139373175c'::uuid, '6a294581-c0be-56ad-8c2e-65daa81b84d2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Some perspectives ultimately are not included.', FALSE, 2, NULL, NULL),
  ('692a8742-d694-5503-b641-698b0c663431'::uuid, '6a294581-c0be-56ad-8c2e-65daa81b84d2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Although experts like journalists are expected to be unbiased they invariably share the system biases of the disciplines and cultures in which they work.', FALSE, 3, NULL, NULL),
