  ('86ebb5fa-5f1c-545f-889d-790c6d749831'::uuid, '6ca309ee-cfe9-5dca-a223-4156ebb8ffb7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'More recent missions to Mars include the hugely successful Mars Pathfinder, which landed a small ‘rover’ called Sojourner on the surface to explore a region where there may once have been life.', FALSE, 0, NULL, NULL),
  ('68522704-b227-5ee3-bce4-70167aee53e7'::uuid, '6ca309ee-cfe9-5dca-a223-4156ebb8ffb7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The only unfortunate thing to have arisen from the mission is the naming of the rocks at the landing site (including everything from Scooby Doo to Darth Vader).', FALSE, 1, NULL, NULL),
  ('68bd657a-60ce-50c6-a960-3a11a5746c1d'::uuid, '6ca309ee-cfe9-5dca-a223-4156ebb8ffb7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Similarly the lander, which imaged several areas around the landing site (dubbed the Carl Sagan Memorial site) and took atmospheric measurements, lasted a good deal longer than expected.', FALSE, 2, NULL, NULL),
  ('50510296-daa0-5ebc-852c-81baf445db13'::uuid, '6ca309ee-cfe9-5dca-a223-4156ebb8ffb7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Sojourner has now been effectively switched off, but lasted almost twelve times its expected lifetime.', FALSE, 3, NULL, NULL),
  ('0b8b2e0d-82a7-5734-97d7-c4358117acc2'::uuid, '6cf163e7-cb5a-5239-a8a8-40ad481270b1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'By increasing development aid and working towards comprehensive debt solutions for low-income countries, high-income countries can preempt emerging threats to peace and prosperity — securing a healthier, more secure future for all.', FALSE, 0, NULL, NULL),
  ('21facc88-56a0-5775-939f-a41265f3c4e8'::uuid, '6cf163e7-cb5a-5239-a8a8-40ad481270b1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This will lead to growing inequalities between countries, threatening global stability, and prosperity.', FALSE, 1, NULL, NULL),
  ('48b0516c-ec11-5c28-9392-b9719d36f050'::uuid, '6cf163e7-cb5a-5239-a8a8-40ad481270b1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Thus, governments need to increase revenues, give greater priority to health in budgets, and improve the efficiency and equity of health spending.', FALSE, 2, NULL, NULL),
  ('2990ff8c-5c31-5dee-bb9c-05a5ccaacaf3'::uuid, '6cf163e7-cb5a-5239-a8a8-40ad481270b1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The projected decline of government spending in many low income countries will restrict their ability to strengthen pandemic preparedness and limit their progress towards universal health coverage.', FALSE, 3, NULL, NULL),
  ('c085bddb-0367-526c-9f27-15619852ae3c'::uuid, '6cfe2db5-c26a-540d-b39f-056e50fe0048'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'level', FALSE, 0, NULL, NULL),
