  ('9f14aad9-b54d-5924-9260-55082c166d1b'::uuid, '6f45ec69-e68b-5558-9fd2-0b2c55af93e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But no one would argue that mobile phones cannot help to make a phone call when we are in a crisis.', FALSE, 1, NULL, NULL),
  ('7b2b67bb-c475-5809-84da-9119e2e51dbb'::uuid, '6f45ec69-e68b-5558-9fd2-0b2c55af93e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'I think we should be wary of the reporting of science — it is often over-dramatized in order to secure an audience — but not of science itself.', FALSE, 2, NULL, NULL),
  ('5aaca3c7-3ab2-528f-b753-6eec6fdf61c6'::uuid, '6f45ec69-e68b-5558-9fd2-0b2c55af93e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Mobile phones, for example, can cause incidents if drivers insist on talking on the phone instead of looking at roads.', FALSE, 3, NULL, NULL),
