  ('56a69d93-4359-5efc-ac6e-44ea7c189ccf'::uuid, '6fe8dc01-32c5-55ae-83ba-26b25d3808ed'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, most of these workers would not consider career alternatives.', FALSE, 1, NULL, NULL),
  ('3ca0d9a0-3cd2-5d3a-9f84-bf00ab4681b9'::uuid, '6fe8dc01-32c5-55ae-83ba-26b25d3808ed'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It seems that the lack of psychological reward is the reason for their dissatisfaction.', FALSE, 2, NULL, NULL),
  ('00ebba99-4374-5b9d-97a4-258864d7d565'::uuid, '6fe8dc01-32c5-55ae-83ba-26b25d3808ed'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The fear of criticism from colleagues, friends and family is the main factor that obstructs a change in their employment situation.', FALSE, 3, NULL, NULL),
  ('587907e9-5e1d-5b2f-ab67-499cf7f39bc0'::uuid, '6fe8dc01-32c5-55ae-83ba-26b25d3808ed'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Despite the financial stability a high salary brings, research has shown that the majority of top earners are not happy in their jobs.', FALSE, 4, NULL, NULL),
