  ('10ebe427-56bc-5d3d-9327-45ef8b84f909'::uuid, '70291d0e-7d7f-53b7-b3d1-91b2f117dc3d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The students who are in the top 2% of all the freshmen are most likely to receive the scholarship.', TRUE, 0, NULL, NULL),
  ('0747377c-f685-5b27-9a59-6268c14f9353'::uuid, '70291d0e-7d7f-53b7-b3d1-91b2f117dc3d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The students whose marks are over 93% are most likely to receive the scholarship.', FALSE, 1, NULL, NULL),
  ('b7b2181b-ef82-5c0c-929d-85fed3a338dd'::uuid, '70291d0e-7d7f-53b7-b3d1-91b2f117dc3d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The scholarship awardees should get the 4.0 grade point on average in order to maintain the scholarship.', FALSE, 2, NULL, NULL),
  ('34c34f5b-93fa-59f5-b804-af7b9623569f'::uuid, '70291d0e-7d7f-53b7-b3d1-91b2f117dc3d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The scholarship does not guarantee housing.', FALSE, 3, NULL, NULL),
  ('677666d0-817e-5e53-9365-da3fc0988e79'::uuid, '70291d0e-7d7f-53b7-b3d1-91b2f117dc3d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The scholarship awardees are given a parking priority in the university residence.', TRUE, 4, NULL, NULL),
  ('7fde4c1a-4f3a-548f-a52e-ce49db802dfa'::uuid, '7036ee8b-d37f-5039-b5e5-9363928b74f7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In this system, creditworthiness, determined by past financial behavior and current financial status, influences the ability to borrow and the terms of loans.', FALSE, 0, NULL, NULL),
  ('aa8ac745-d835-5fad-b42a-11001ad3c8e0'::uuid, '7036ee8b-d37f-5039-b5e5-9363928b74f7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'While credit can stimulate economic growth, excessive borrowing can lead to financial crises.', FALSE, 1, NULL, NULL),
  ('87776359-c563-515d-9990-0279d9bc1803'::uuid, '7036ee8b-d37f-5039-b5e5-9363928b74f7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Therefore, maintaining a balanced and well-regulated credit system is crucial for economic health.', FALSE, 2, NULL, NULL),
  ('c2a38399-08d6-5704-ae98-e03ddcd5ef98'::uuid, '7036ee8b-d37f-5039-b5e5-9363928b74f7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The credit system allows individuals and businesses to borrow money, facilitating purchases and investments.', FALSE, 3, NULL, NULL),
  ('bd216896-4848-5973-b622-e74f23a10454'::uuid, '70498959-fd09-59d4-87a5-e7e0e2dea887'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Thus, today the Great Wall stands as a symbol of China''s rich history and cultural endurance.', FALSE, 0, NULL, NULL),
  ('9c9349e8-7a0a-531d-b3d3-26443ec51f40'::uuid, '70498959-fd09-59d4-87a5-e7e0e2dea887'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Its construction began in the 7th century BC and continued for centuries, involving millions of workers, which signifies the determination and strength of ancient Chinese dynasties.', FALSE, 1, NULL, NULL),
  ('09cae31c-ebf0-5503-a999-257d55020f1f'::uuid, '70498959-fd09-59d4-87a5-e7e0e2dea887'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Consequently, this monumental structure not only represents defensive strategies but also the unification of China.', FALSE, 2, NULL, NULL),
  ('d559b660-a23c-52df-9aeb-25ba467cc5bb'::uuid, '70498959-fd09-59d4-87a5-e7e0e2dea887'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Great Wall of China, originally built to protect against invasions, stretches over 13,000 miles and represents a significant historical achievement.', FALSE, 3, NULL, NULL),
  ('e354ca8b-2784-5007-810b-8f7a43c22a19'::uuid, '7056cec8-6bec-50b1-9343-da75c0fc491c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'visit', FALSE, 0, NULL, NULL),
