  ('1f73ac06-5b09-503d-9710-b4ad616289eb'::uuid, '7056cec8-6bec-50b1-9343-da75c0fc491c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'accounts', FALSE, 5, NULL, NULL),
  ('1feead28-bab2-5eb3-9d79-9a6a99a71508'::uuid, '70621731-f0b6-56ef-a0bb-7c654123b8b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Above all, Marx''s fresh perspective on nineteenth-century events encouraged his readers to think, and his writing is surprisingly relevant today.', FALSE, 0, NULL, NULL),
  ('dd1bbc44-a881-564e-bac4-fcfbe827bc50'::uuid, '70621731-f0b6-56ef-a0bb-7c654123b8b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Karl Marx is arguably the most of the most famous political philosopher of all time, but he was also one of the great foreign correspondents of the nineteenth century.', FALSE, 1, NULL, NULL),
  ('8e23fa2f-9185-5bfc-8f93-ad9c9787692d'::uuid, '70621731-f0b6-56ef-a0bb-7c654123b8b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Particularly moving pieces highlight social inequality and starvation in Britain, while others explore his groundbreaking views on the slave and opium trades — Marx believed Western powers relied on these and would stop at nothing to protect their interests.', FALSE, 2, NULL, NULL),
  ('028b34c4-6913-5a38-99b3-9b26ba9dcbad'::uuid, '70621731-f0b6-56ef-a0bb-7c654123b8b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'During his 11 years writing for the New York Tribune — their collaboration began in 1852 — Marx tackled an abundance of topics, from issues of class and the state to world affairs.', FALSE, 3, NULL, NULL),
  ('8b9fc17f-fada-596c-810f-5cf6f6aaf241'::uuid, '7079726d-b1ad-5ae3-ba39-8065d61abb6d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'invention', FALSE, 0, 0, NULL),
