  ('e922b3fe-f26a-52f1-ba66-83515156a3d7'::uuid, '721d6e13-ab5c-5762-aa89-3be07e882096'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'sized', FALSE, 18, 4, NULL),
  ('e3cbf876-0787-5d14-b93e-45742a42d19f'::uuid, '721d6e13-ab5c-5762-aa89-3be07e882096'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'enshrined', FALSE, 19, 4, NULL),
  ('3907a0f3-faed-5566-807b-ed5d5b8ef90a'::uuid, '7221face-ea33-5ebf-9d15-1c60eed5f4d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Because everyone is capable of learning to speak and understand language, it may seem to be simple.', FALSE, 0, NULL, NULL),
  ('b23be6a9-e0fb-59c0-8390-1b33e78ce6bd'::uuid, '7221face-ea33-5ebf-9d15-1c60eed5f4d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But just the opposite is true — language is one of the most complex of all human cognitive abilities.', FALSE, 1, NULL, NULL),
  ('a78f56d0-2911-514e-943e-30a7f4fc3d9e'::uuid, '7221face-ea33-5ebf-9d15-1c60eed5f4d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For one thing, the use of language is universal — all normally developing children learn to speak at least one language, and many learn more than one.', FALSE, 2, NULL, NULL),
  ('e4da73c8-b71b-5cb6-ae69-a453aba53d51'::uuid, '7221face-ea33-5ebf-9d15-1c60eed5f4d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'By contrast, not everyone becomes proficient at complex mathematical reasoning, few people learn to paint well, and many people cannot carry a tune.', FALSE, 3, NULL, NULL),
  ('a00bd5fc-f9e4-55a7-8954-1c51606a9751'::uuid, '7221face-ea33-5ebf-9d15-1c60eed5f4d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It is wrong to exaggerate the similarity between language and other cognitive skills, because language stands apart in several ways.', FALSE, 4, NULL, NULL),
  ('70ae2db0-9c86-5258-8446-cb5c5886b95a'::uuid, '722ee8df-3b81-5f18-8d6a-7494930c5d73'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'off', FALSE, 0, 0, NULL),
