  ('3129e260-ee8b-5e64-8c73-0f99a17ef269'::uuid, '723c1b0e-4755-5f22-93f1-422e0fcd6dbb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Development in the past was driven by growth and innovation. It led to new technologies and huge improvements in living standards.', FALSE, 0, NULL, NULL),
  ('8087e73e-717b-54d9-86ef-6b1f2b0f2c21'::uuid, '723c1b0e-4755-5f22-93f1-422e0fcd6dbb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Whatever happened to the idea of progress and a better future? I still believe both.', FALSE, 1, NULL, NULL),
  ('7c415a73-99a6-569f-b0fc-955f18d200ce'::uuid, '723c1b0e-4755-5f22-93f1-422e0fcd6dbb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Implicit in this definition is the idea that the old pattern of development could not be sustained. Is this true?', FALSE, 2, NULL, NULL),
  ('d96a3711-22c9-5fa9-83b4-10e2b5ae47fa'::uuid, '723c1b0e-4755-5f22-93f1-422e0fcd6dbb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Brundtland Report, our Common Future (1987) defines sustainable development as ''development which meets the needs of the present without compromising the ability of future generations to meet their own needs''.', FALSE, 3, NULL, NULL),
  ('43ac638b-9efc-5f36-9a4c-a92a16cf3327'::uuid, '723c1b0e-4755-5f22-93f1-422e0fcd6dbb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To assume that we know what the circumstances or needs of future generations will be is mistaken and inevitably leads to the debilitating sense that we are living on borrowed time.', FALSE, 4, NULL, NULL),
  ('feec83cb-ff07-51f6-988b-9970aaf1553e'::uuid, '7250c008-acf0-52e5-a296-2ac2b1c047db'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'skyrocketed', TRUE, 0, NULL, 2),
