  ('0ccd4a8d-2296-5b3a-ac10-4bcfb0dac3b3'::uuid, '7289f8d2-f9d2-5852-9b6d-2ae2081a1d5a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'consumption', FALSE, 16, 4, NULL),
  ('0a6e4e31-cde3-5f58-be88-e90b4cb1668a'::uuid, '7289f8d2-f9d2-5852-9b6d-2ae2081a1d5a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'regret', FALSE, 17, 4, NULL),
  ('af00b15b-4507-5df1-a264-c48a3bb9c563'::uuid, '7289f8d2-f9d2-5852-9b6d-2ae2081a1d5a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'skill', TRUE, 18, 4, NULL),
  ('9f779ec2-8e34-5b9d-959e-5528de1b9fc2'::uuid, '7289f8d2-f9d2-5852-9b6d-2ae2081a1d5a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'degree', FALSE, 19, 4, NULL),
  ('f8f3a784-42a9-5a2c-b1b5-decac668c919'::uuid, '72939813-f4bb-531c-88a4-4923da2adbcc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'And it is a lesson to us that no one has ever yet seen quarrel between any two ants belonging to the same community.', FALSE, 0, NULL, NULL),
  ('3ad6a63d-b785-54c2-9fae-fee3234e9c18'::uuid, '72939813-f4bb-531c-88a4-4923da2adbcc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'I have over and over again introduced ants from one of my nests into another nest of the same species; and they were invariably attacked, seized by a leg or an antenna, and dragged out.', FALSE, 1, NULL, NULL),
  ('99174293-264e-5fb0-a13d-6d6172b31031'::uuid, '72939813-f4bb-531c-88a4-4923da2adbcc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It is evident, therefore, that the ants of each community all recognize one another, which is very remarkable.', FALSE, 2, NULL, NULL),
  ('f8bc78e9-6097-5729-9e7a-34c703eb129e'::uuid, '72939813-f4bb-531c-88a4-4923da2adbcc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The communities of ants are sometimes very large, numbering even to 500 individuals.', FALSE, 3, NULL, NULL),
  ('88a6762a-2ca3-5c65-8ae7-167095a68f8e'::uuid, '72939813-f4bb-531c-88a4-4923da2adbcc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, it must be admitted that they are in hostility not only with most other insects, including ants of different species, but even with those of the same species if belonging to different communities.', FALSE, 4, NULL, NULL),
  ('ffbe8edc-cce9-57e8-91bf-4b3999cd4ab2'::uuid, '72af01e4-71b2-56b5-a270-77c2492d1fa2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'medical', TRUE, 0, NULL, 3),
  ('c7cde6ec-6879-5fa8-b075-db2f0019bbd6'::uuid, '72af01e4-71b2-56b5-a270-77c2492d1fa2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'patient', FALSE, 1, NULL, NULL),
