  ('2ed0396e-bf44-50a2-aef9-cb7740950b89'::uuid, '73ce2a8e-428a-5225-af72-f8a9a8be9974'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'especially', FALSE, 4, NULL, NULL),
  ('c00efa2e-867c-5062-847c-2558968d0075'::uuid, '73ce2a8e-428a-5225-af72-f8a9a8be9974'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'generally', TRUE, 5, NULL, 1),
  ('7981102b-8b7e-5a21-82f0-1ded27b99eea'::uuid, '73d4121b-8989-57c2-a1b4-69620f195618'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Cliches are the enemy of literature and art. They are words, phrases and images that have become stale through overuse and therefore have nothing new to say to us. They are an enemy to clear and original thinking, although they are sometimes useful in advertising to get a simple message across.', FALSE, 0, NULL, NULL),
  ('8d51a3f5-1fa2-5e81-a4f1-a9e97bd83e80'::uuid, '73d4121b-8989-57c2-a1b4-69620f195618'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'While cliches in writing reveal lazy thinking and are to be avoided at all costs, in the graphic arts they become essential, helping to get the message across quickly, clearly and with emotional force. This is especially true of advertising and propaganda where the impact must be immediate.', TRUE, 1, NULL, NULL),
  ('42594c50-f1d8-5995-9f23-2cba7b9af12e'::uuid, '73d4121b-8989-57c2-a1b4-69620f195618'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Cliches are worn out, overused and over-familiar phrases, and the etymology of the word helps to explain this. Originally, a cliche or stereotype was a printer''s term for a pre-set block of type with phrases used frequently in the newspapers. The word has since adopted a negative meaning and careful writers avoid them where they can.', FALSE, 2, NULL, NULL),
  ('6491f4b3-2d38-5f08-9e5d-24e1d410fba7'::uuid, '73d4121b-8989-57c2-a1b4-69620f195618'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Cliches, whether in language or graphic design, are entirely worthless and should be eliminated in all fields. In literature, they destroy original thinking, and in graphic arts, they only create confusion instead of conveying clear messages.', FALSE, 3, NULL, NULL),
  ('be2c9e8c-a5be-54b2-b188-96c9f73566b1'::uuid, '73ee43a7-8241-5f9d-b56e-bebdd9faf9c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'function', TRUE, 0, NULL, 1),
  ('40df4096-2f2b-5ab6-a8af-8cc43375b4c6'::uuid, '73ee43a7-8241-5f9d-b56e-bebdd9faf9c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'overview', FALSE, 1, NULL, NULL),
