  ('72766da3-c2b4-5a6f-87d2-5ef0cd40275c'::uuid, '73ef5263-8e88-510f-b484-68814e16ac2c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For the past seven years Professor Philip Hill has been part of a collaborative tuberculosis research project in Indonesia, with the University of Padjadjaran in Bandung, West Java, undertaking European-Commission-funded research into the causative links between infectious and non-communicable diseases, which in this case are tuberculosis (TB) and diabetes mellitus.', FALSE, 0, NULL, NULL),
  ('09f5b309-1f95-55da-8233-9c223706768f'::uuid, '73ef5263-8e88-510f-b484-68814e16ac2c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'University of Otago Centre of International Health co-directors Professor Philip Hill and Professor John Crump share a view that global health is a multidisciplinary activity.', FALSE, 1, NULL, NULL),
  ('d70f6c28-f5be-55f7-ab80-eb618d6e6743'::uuid, '73ef5263-8e88-510f-b484-68814e16ac2c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In their work from Tanzania to the Gambia, from Myanmar to Indonesia and beyond, they tap into a wide range of expertise from across the University, including clinicians, microbiologists and molecular microbiologists, public health experts, economists and mathematicians.', FALSE, 2, NULL, NULL),
  ('d5e6f539-2011-55a1-a182-ad33ea439dd4'::uuid, '73ef5263-8e88-510f-b484-68814e16ac2c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They have also forged relationships and collaborations with research and aid agencies around the world.', FALSE, 3, NULL, NULL),
