  ('f80b7e5e-5cae-5164-aaf9-12b570022676'::uuid, '740d8f3a-66e4-59c6-bfac-9ebe1c0eff85'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Initial observations indicated that temperature had a negligible effect on the chemical reaction.', FALSE, 0, NULL, NULL),
  ('edb02fd1-c203-5f62-bac9-917c1c677c67'::uuid, '740d8f3a-66e4-59c6-bfac-9ebe1c0eff85'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, upon further investigation, it was found that increasing the temperature slightly accelerated the reaction.', FALSE, 1, NULL, NULL),
  ('be83efc1-9783-510c-b424-4f50a26bef4a'::uuid, '740d8f3a-66e4-59c6-bfac-9ebe1c0eff85'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Consequently, it was concluded that temperature played a critical role in the reaction''s speed.', FALSE, 2, NULL, NULL),
  ('6ece7002-d970-5d69-859f-53139c532a87'::uuid, '740d8f3a-66e4-59c6-bfac-9ebe1c0eff85'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This acceleration became more pronounced at higher temperatures.', FALSE, 3, NULL, NULL),
