  ('405355e8-2a3d-5c4f-b793-9b5731f6f569'::uuid, '744b4a70-4e23-5ec5-ba0f-71c14c7da480'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Potential energy is the energy of an object''s position.', FALSE, 0, NULL, NULL),
  ('b1b03339-9414-5a32-899d-dde7e8edacf6'::uuid, '744b4a70-4e23-5ec5-ba0f-71c14c7da480'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'At the highest point, the potential energy is greatest. As the ball rises or falls it has a combination of potential and kinetic energy.', FALSE, 1, NULL, NULL),
  ('2a6c9a46-e578-5bc0-b474-3ff0f923127d'::uuid, '744b4a70-4e23-5ec5-ba0f-71c14c7da480'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Another example is throwing a ball into the air.', FALSE, 2, NULL, NULL),
  ('aaab70c1-9865-5bea-bde9-3b4d63c0acef'::uuid, '744b4a70-4e23-5ec5-ba0f-71c14c7da480'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'When she is closest to the ground, her potential energy is at its minimum.', FALSE, 3, NULL, NULL),
  ('bc6c82d1-de9f-5067-8731-4fa5559c5e20'::uuid, '744b4a70-4e23-5ec5-ba0f-71c14c7da480'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For example, when a child swinging on a swing reaches the top of the arc, she has maximum potential energy.', FALSE, 4, NULL, NULL),
  ('4b3514a0-2a33-52c8-8457-aaa5164511b1'::uuid, '747e2bcd-dbb6-5593-9c7c-c95236b36a4c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'tied', TRUE, 0, NULL, 2),
