  ('dd897358-4787-5599-a4ab-6c14ecff7ead'::uuid, '75e4a7d0-f6b3-530a-a296-01234bfe69f6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The construction of new houses came to a standstill during the war, and this, together with growing demand, led to an estimated shortage of close to a million houses when the war was over.', FALSE, 0, NULL, NULL),
  ('a18c840c-8a8a-52a7-b8db-5e87c0798cdd'::uuid, '75e4a7d0-f6b3-530a-a296-01234bfe69f6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In the absence of housing regulations, including the availability of loans to the less well-off, poor-quality housing was built by private enterprise to meet the growing demand at rents that people could afford.', FALSE, 1, NULL, NULL),
  ('f8489657-c549-5bff-ab42-345a99df0ed6'::uuid, '75e4a7d0-f6b3-530a-a296-01234bfe69f6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Before the First World War, most housing in Britain was provided on a rental basis as the cost of housing was beyond the means of the average family and mortgages were hard to come by.', FALSE, 2, NULL, NULL),
  ('c4bb5872-7fe9-5661-a378-e4f57be44ecd'::uuid, '75e4a7d0-f6b3-530a-a296-01234bfe69f6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This created a dilemma, since wartime inflation had pushed up wages and the cost of building materials with the result that private enterprise was no longer able to provide the houses needed at rents which people could afford.', FALSE, 3, NULL, NULL),
  ('d4f5f5dc-33be-5088-b96e-4b4d8cd7dd4a'::uuid, '75ea2098-5708-5aba-833b-79991f8fb0b1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'mitigating', TRUE, 0, NULL, 1),
