  ('b5ace2d4-596d-5e0d-9580-707a8a138a04'::uuid, '75efd28b-c26d-527e-899c-1e464347d9fc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, over the course of the treatment, those on the actual drug showed a more significant reduction in symptom severity.', FALSE, 1, NULL, NULL),
