  ('62e270ef-c296-5ac6-8189-8f56c04c1f48'::uuid, '7693800f-414e-5dba-91c2-342a89adb8c7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But the fact that science underlies our lives, our health, our work, our communications, our entertainment and our transport is undeniable.', FALSE, 0, NULL, NULL),
  ('66820a6d-fc5f-59ea-ba0f-930380789109'::uuid, '7693800f-414e-5dba-91c2-342a89adb8c7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Indeed, human existence in the developed world is entirely dependent on some fairly recent developments in science and technology.', FALSE, 1, NULL, NULL),
  ('db7c7e56-67aa-5e52-8b63-dad7dd60d4c0'::uuid, '7693800f-414e-5dba-91c2-342a89adb8c7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Whether this is good or bad is, of course, up for argument.', FALSE, 2, NULL, NULL),
  ('74d41953-e68e-5c3c-a886-f3f7eccbb00a'::uuid, '7693800f-414e-5dba-91c2-342a89adb8c7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It is a truism to say that in 21st century society science and technology are important.', FALSE, 3, NULL, NULL),
