  ('ec4a7329-806b-51c4-a9e4-500faac44aa0'::uuid, '76a30445-65e7-5857-881c-6538ea2e316f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They originate from sources like glaciers, springs, or rainfall and flow towards oceans, lakes, or other rivers.', FALSE, 0, NULL, NULL),
  ('eefa146f-9c6d-583b-bedb-9c0bdc765735'::uuid, '76a30445-65e7-5857-881c-6538ea2e316f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Rivers play a crucial role in shaping the geography of the land.', FALSE, 1, NULL, NULL),
  ('48bc374b-87ce-5b5b-8368-ec75c6454e41'::uuid, '76a30445-65e7-5857-881c-6538ea2e316f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As rivers flow, they erode the land and carry sediment, which can lead to the formation of valleys and deltas.', FALSE, 2, NULL, NULL),
  ('a7e5f075-80ce-57b7-b66c-0dad655229a3'::uuid, '76a30445-65e7-5857-881c-6538ea2e316f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Therefore, rivers are key in forming some of the world''s most fertile agricultural areas.', FALSE, 3, NULL, NULL),
