  ('c0b15bff-a528-5ab4-8819-efa3ab5c428d'::uuid, '77ce6444-01cf-552d-8397-9f337a91d5b4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'notion', TRUE, 7, NULL, 1),
  ('480a7878-5ed5-583f-8ac8-ca444cb48505'::uuid, '77d0d934-dca9-52f8-9329-e3712e20ad87'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To understand the past, one must think as people of the period did (e.g., medieval peasants). But due to changing sensibilities, each era has a slightly different view of the same past, regardless of facts.', TRUE, 0, NULL, NULL),
  ('9af3f240-b399-5bd3-9a7a-0d3b3ffbe805'::uuid, '77d0d934-dca9-52f8-9329-e3712e20ad87'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The text states historians need novelists'' ability to get into characters'' minds, as the world and thinking (e.g., medieval vs. 21st century) changed, explained by shifting historians'' sensibilities.', FALSE, 1, NULL, NULL),
  ('71822b3a-ec64-56df-83b0-70de935c5f49'::uuid, '77d0d934-dca9-52f8-9329-e3712e20ad87'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Historians must, like novelists, enter characters'' minds and feel as they did, with the medieval peasant example emphasizing imaginative sympathy for ordinary people of the past.', FALSE, 2, NULL, NULL),
  ('aaaccf61-0423-5919-9b52-79e42c0e27ca'::uuid, '77d0d934-dca9-52f8-9329-e3712e20ad87'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Understanding the medieval period requires no imagination, only facts. Historians of different eras agree on the Middle Ages; history needs no rewriting as facts are unchanging.', FALSE, 3, NULL, NULL),
  ('a3c72f36-fe48-5a0f-829a-621e077ccea9'::uuid, '77d4a15e-5e6d-5922-9486-f5069d777189'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For example, many medical students take a gap year after completing their A-Levels before starting medical school.', FALSE, 0, NULL, NULL),
  ('224d2121-e4aa-5f84-9f34-6da964133491'::uuid, '77d4a15e-5e6d-5922-9486-f5069d777189'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, this is not always the journey that most medical students follow.', FALSE, 1, NULL, NULL),
  ('b24f0c2b-3eff-516d-8fc4-83e6edd448e1'::uuid, '77d4a15e-5e6d-5922-9486-f5069d777189'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'You need to know that the road to becoming a doctor is not a straightforward journey you can easily progress through.', FALSE, 2, NULL, NULL),
  ('02ebf250-f2e9-528d-ba8f-875da2e235df'::uuid, '77d4a15e-5e6d-5922-9486-f5069d777189'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'You have the option to follow the undergraduate route as a school leaver: you finish your A-Levels, apply to a university offering Medicine, and then go to medical school.', FALSE, 3, NULL, NULL),
  ('3b61af90-97e4-5d4c-a883-f80970b39675'::uuid, '77d4a15e-5e6d-5922-9486-f5069d777189'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Instead, think about the journey as one that has many different stages and routes that you can follow.', FALSE, 4, NULL, NULL),
  ('a7c1e850-e651-521b-b444-badce46386f2'::uuid, '77fec839-ef35-5cde-94fc-50d922feb8c1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'fascination', FALSE, 0, 0, NULL),
