  ('041ac7fc-5f91-5614-953d-aa94698ba9ec'::uuid, '78085aed-7aa9-57d4-876d-d8e36f6713aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Northern Italy, for example, tends to add eggs in the dough to make a pasta that is elastic enough to hold heavy fillings inside.', FALSE, 0, NULL, NULL),
  ('ce63d3c3-4cd6-595a-a0cf-1fa35027b410'::uuid, '78085aed-7aa9-57d4-876d-d8e36f6713aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This is why some of the most popular stuffed pastas come from this region.', FALSE, 1, NULL, NULL),
  ('97d87762-4583-5c98-a07c-adc0aa4835a1'::uuid, '78085aed-7aa9-57d4-876d-d8e36f6713aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This simple mix of a few ingredients, however, differs greatly through the many regions of Italy, where each region produces its own type of pasta based on what it is meant to be eaten with.', FALSE, 2, NULL, NULL),
  ('c77d8bbb-66c5-5191-8e50-9f84560fda57'::uuid, '78085aed-7aa9-57d4-876d-d8e36f6713aa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Pasta roughly translates to paste in Italian, referring to the mix of flour, water, and eggs that pasta is made from.', FALSE, 3, NULL, NULL),
