  ('fb060e47-0e35-549e-990c-bfcd314f4116'::uuid, '78c6c141-8147-502f-af93-db4d945791fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The mantle is the mostly-solid bulk of Earth’s interior.', FALSE, 0, NULL, NULL),
  ('f483ccb5-2761-5338-91b8-eb552f36fc04'::uuid, '78c6c141-8147-502f-af93-db4d945791fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The rocks that make up Earth’s mantle are mostly silicates — a wide variety of compounds that share a silicon and oxygen structure.', FALSE, 1, NULL, NULL),
  ('3ebf60f0-7ebd-5aa7-9170-039965199a90'::uuid, '78c6c141-8147-502f-af93-db4d945791fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The other major type of rock found in the mantle is magnesium oxide.', FALSE, 2, NULL, NULL),
  ('5e766f0d-67d2-53bc-882b-52aae5b61a1d'::uuid, '78c6c141-8147-502f-af93-db4d945791fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Common silicates found in the mantle include olivine, garnet, and pyroxene.', FALSE, 3, NULL, NULL),
