  ('5286f2a2-a8bc-5b27-8ca4-6fcb2b8a9175'::uuid, '78c79e13-2738-536a-9dd2-430b134282d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'painstakingly', TRUE, 5, NULL, 2),
  ('ccd0ade0-f042-5a3b-8718-a866c86a09cf'::uuid, '78d5db55-7fad-550d-8c11-84bcc4c61c53'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This kind of oppression includes the systematic mistreatment, exploitation, and abuse of a group of people by another group.', FALSE, 0, NULL, NULL),
  ('c47114bc-a815-5119-9056-ba1eedb57a8c'::uuid, '78d5db55-7fad-550d-8c11-84bcc4c61c53'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Consequently, those in the controlling or dominant group benefit from the oppression of other groups through greater access to rights and resources, a better quality of life, and overall greater life chances.', FALSE, 1, NULL, NULL),
  ('43f66199-b497-5ca2-86d6-81beb1fdb76d'::uuid, '78d5db55-7fad-550d-8c11-84bcc4c61c53'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Social oppression refers to oppression that is achieved through social means.', FALSE, 2, NULL, NULL),
  ('08c81486-d100-57ad-9144-d5cf2684b3c9'::uuid, '78d5db55-7fad-550d-8c11-84bcc4c61c53'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The outcome of social oppression is that groups in society are sorted into different positions depending on their social hierarchies.', FALSE, 3, NULL, NULL),
  ('65af8235-5824-5fb1-b481-1b0dea7ea689'::uuid, '78e3ff15-b586-5625-af0a-49d989650bee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Their current height is not an indication of their age.', FALSE, 0, NULL, NULL),
  ('4a6d5b53-8d86-5b96-8976-fd6249082549'::uuid, '78e3ff15-b586-5625-af0a-49d989650bee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'At present, they are much higher than the mountains of the Caledonian range.', TRUE, 1, NULL, NULL),
  ('a2a7f96d-6686-52e8-9150-14c69a4c94dc'::uuid, '78e3ff15-b586-5625-af0a-49d989650bee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They did not exist 400 million years ago.', TRUE, 2, NULL, NULL),
  ('4e71901c-02dc-58b2-86ca-30b5eb378304'::uuid, '78e3ff15-b586-5625-af0a-49d989650bee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They are not as high as the Caledonian mountains were 400 million years ago.', FALSE, 3, NULL, NULL),
  ('c92c286c-c283-5aec-aea3-c7dd5beea897'::uuid, '78e3ff15-b586-5625-af0a-49d989650bee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The higher the mountains, the older their age.', FALSE, 4, NULL, NULL),
  ('028c9119-392d-54a7-8f0c-23cffb5bae8a'::uuid, '78e512c8-b167-5655-a022-30f7b0785bbc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It''s the most common sexually transmitted virus and infection in the U.S.', FALSE, 0, NULL, NULL),
