  ('7b5c6e67-6a8d-5610-a9ae-d047ebb987f0'::uuid, '7a421e77-9a52-5765-8ec6-731ef923dd15'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'means', TRUE, 5, NULL, 4),
