  ('0eb74ab8-65ad-55ed-abee-10d79519d56b'::uuid, '7ac20eed-9d6b-5fc9-9583-19bafa7260e6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'One Health recognizes that the health of humans, animals and ecosystems are interconnected.', FALSE, 0, NULL, NULL),
  ('cf0f40a7-2bee-51fe-b1b3-1eb2e838e29e'::uuid, '7ac20eed-9d6b-5fc9-9583-19bafa7260e6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The term “One Health” was developed in 2004 in relation to human infectious diseases such as SARS.', FALSE, 1, NULL, NULL),
  ('e6ef348a-c5ef-5d3a-b4f7-499e77d958cd'::uuid, '7ac20eed-9d6b-5fc9-9583-19bafa7260e6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It involves applying a coordinated, collaborative, multidisciplinary and cross-sectoral approach to address potential or existing risks that originate at the animal-human-ecosystems interface.', FALSE, 2, NULL, NULL),
  ('54f7babd-6ade-588d-8354-6b361bb62cf9'::uuid, '7ac20eed-9d6b-5fc9-9583-19bafa7260e6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The rationale for extending a One Health approach to complex and multifactorial diseases is the growing realization that such diseases do have many pathological changes.', FALSE, 3, NULL, NULL),
