  ('bb89af68-3229-5fdd-b4ad-3779bd89faac'::uuid, '7c3b6bb4-1147-527f-b935-08616e94735e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As one of the best literary works of Ernest Hemingway, A Farewell to Arms was published in the late 1920s.', FALSE, 0, NULL, NULL),
  ('95c0a6c5-a508-5cc1-8758-dd6feef03ab9'::uuid, '7c3b6bb4-1147-527f-b935-08616e94735e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The famous work of Ernest Hemingway-A Farewell to Arms-describes the Italian campaign after the First World War.', TRUE, 1, NULL, NULL),
  ('f0f619a8-9889-5b13-b382-94770b83903f'::uuid, '7c3b6bb4-1147-527f-b935-08616e94735e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In addition to the love story, Hemingway also mentions about how absurd war is and how he loses his love.', FALSE, 2, NULL, NULL),
  ('faaaaf97-28dd-5fed-a6de-3cbcd55ce026'::uuid, '7c3b6bb4-1147-527f-b935-08616e94735e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'People now can enjoy the work on screen, TV and stage.', FALSE, 3, NULL, NULL),
  ('2b0c7b4c-dc07-582b-b384-6d4b4c03dbfb'::uuid, '7c43f25d-6d16-5dd7-8b19-84ea5d9e76f1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This pandemic had profound social, economic, and religious effects, leading to widespread labor shortages and challenging existing hierarchies.', FALSE, 0, NULL, NULL),
  ('0da7928d-95bd-59fb-bf03-ca933eb36995'::uuid, '7c43f25d-6d16-5dd7-8b19-84ea5d9e76f1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It killed an estimated 75 to 200 million people, drastically reducing the world population.', FALSE, 1, NULL, NULL),
  ('fbdefcd3-012b-5f41-95bd-41e9b14f4eee'::uuid, '7c43f25d-6d16-5dd7-8b19-84ea5d9e76f1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Black Death, a devastating global epidemic of bubonic plague, struck Europe and Asia in the mid-14th century.', FALSE, 2, NULL, NULL);
