  ('47bebafd-cf89-5b02-8127-f6edc3564590'::uuid, '7c6b2e61-d98e-5acb-bebb-08070b4a8b01'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For some time, those in geographic circles have debated whether there are four or five oceans on Earth.', FALSE, 0, NULL, NULL),
  ('c57f9d33-c1c8-533c-b08a-670ddd277351'::uuid, '7c6b2e61-d98e-5acb-bebb-08070b4a8b01'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Now, those that side with the number five can add the fifth new ocean and call it the Southern Ocean or the Antarctic Ocean, thanks to the International Hydrographic Organization (IHO).', FALSE, 1, NULL, NULL),
  ('d56de530-9a43-51b9-b7d8-2ffd520a6290'::uuid, '7c6b2e61-d98e-5acb-bebb-08070b4a8b01'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The IHO has settled the debate through a publication that has declared, named, and demarcated the Southern Ocean.', FALSE, 2, NULL, NULL),
  ('153d86c6-2f0f-5a79-a374-7fa030148d61'::uuid, '7c6b2e61-d98e-5acb-bebb-08070b4a8b01'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Some consider the Arctic, Atlantic, Indian, and Pacific to be the world''s four oceans.', FALSE, 3, NULL, NULL),
