  ('19fc7ffb-5763-5872-a215-30a3c48a1501'::uuid, '7e0c4bd2-cf2a-57ae-aa01-cd9e21e29e62'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'On the other hand, the human shoulder is better for throwing and hunting, giving humans invaluable survival skills.', FALSE, 0, NULL, NULL),
  ('55d7dc90-cc2c-52f6-8c7c-c55feb45326e'::uuid, '7e0c4bd2-cf2a-57ae-aa01-cd9e21e29e62'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This is in contrast to the ape shoulder, which is pointed more vertically.', FALSE, 1, NULL, NULL),
  ('4f477eeb-ab00-5c29-91d2-be86cd17afe5'::uuid, '7e0c4bd2-cf2a-57ae-aa01-cd9e21e29e62'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Human shoulders have evolved in such a way that the whole joint angles out horizontally from the neck, like a coat hanger.', FALSE, 2, NULL, NULL),
