  ('d8741254-ca01-5f2f-87d9-e550269d87d9'::uuid, '7eb77584-8317-5405-a4de-25e1a56498e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'False memories are constructed by combining actual memories with the content of suggestions received from others. During the process, individuals may forget the source of the information.', FALSE, 0, NULL, NULL),
  ('b068528a-0770-5fd8-bb14-022dd7ab1861'::uuid, '7eb77584-8317-5405-a4de-25e1a56498e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Of course, because we can implant false childhood memories in some individuals in no way implies that all memories that arise after suggestion are necessarily false.', FALSE, 1, NULL, NULL),
  ('c0a28dc8-e233-5284-ae77-b2f5afbdbab9'::uuid, '7eb77584-8317-5405-a4de-25e1a56498e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This is a classic example of source confusion, in which the content and the source become dissociated.', FALSE, 2, NULL, NULL),
  ('ce940e3d-b11e-56f5-a95d-d0e6c6d164e4'::uuid, '7eb77584-8317-5405-a4de-25e1a56498e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Put another way, although experimental work on the creation of false memories may raise doubt about the validity of long-buried memories, such as repeated trauma, it in no way disproves them.', FALSE, 3, NULL, NULL),
  ('fe58d7c7-ed7a-56de-8b2d-08bd62f2e6f0'::uuid, '7ebb72fd-0279-5253-9ba7-f221a83c24c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There is a lot of research that shows that when bilinguals speak in one of their languages, the other language is still active.', FALSE, 0, NULL, NULL),
  ('a9218639-11e2-504a-aaad-2d02a3cc62f0'::uuid, '7ebb72fd-0279-5253-9ba7-f221a83c24c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'More than half of people in Europe speak more than one language.', FALSE, 1, NULL, NULL),
  ('92df8c54-2672-549c-ad2b-7aad5e442b1b'::uuid, '7ebb72fd-0279-5253-9ba7-f221a83c24c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It could also enhance metacognition: the awareness, monitoring and assessment of one’s own knowledge and mental processes.', FALSE, 2, NULL, NULL),
  ('16e82440-094f-531f-aa3e-9bfed332a815'::uuid, '7ebb72fd-0279-5253-9ba7-f221a83c24c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The ability to speak more than one language is therefore thought to influence skills and processes used by our brain to acquire knowledge and make sense of our surroundings, known as cognition.', FALSE, 3, NULL, NULL),
  ('8df5cf2f-a92a-5ca9-835f-de6911ca1154'::uuid, '7ecf73a2-179a-508b-8632-c687f285ee44'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'sense', FALSE, 0, 0, NULL),
  ('4073a5df-773d-5310-b083-b24246e594e5'::uuid, '7ecf73a2-179a-508b-8632-c687f285ee44'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'hoard', FALSE, 1, 0, NULL),
