  ('030b31b4-3106-509c-a9d9-e7fc8c57a474'::uuid, '7ee1a9c1-172e-58f2-87a7-eeb69386cd40'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'vivid', TRUE, 5, NULL, 2),
  ('de5fbad5-2c4c-5026-8511-f7031eeda75e'::uuid, '7eeefd15-9882-5f70-8bde-7d04b5e44b5c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In addition to reducing carbon dioxide, turfgrass traps an estimated 12 million tons of dust and dirt released annually into the atmosphere.', FALSE, 0, NULL, NULL),
  ('6f7b5850-da36-50cf-b922-22bfa93d4e62'::uuid, '7eeefd15-9882-5f70-8bde-7d04b5e44b5c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Turfgrass is a living organism which takes in carbon dioxide and converts it into simple sugars to use as food through the process of photosynthesis.', FALSE, 1, NULL, NULL),
  ('74a4aa03-5620-5ed4-9104-8f7a2ae24f4f'::uuid, '7eeefd15-9882-5f70-8bde-7d04b5e44b5c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'An average sized healthy lawn can capture 300 pounds of carbon per year and a golf course fairway can capture 1,500 pounds per year.', FALSE, 2, NULL, NULL),
  ('94c1ae57-3ace-5223-bb07-120d851961a2'::uuid, '7eeefd15-9882-5f70-8bde-7d04b5e44b5c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Because of this, experts state that the strategic use of turfgrass is the most sensible and economically feasible approach to countering the greenhouse effect in urban areas.', FALSE, 3, NULL, NULL),
  ('b67b4f2b-307b-5c7d-aeae-2a7c00e5824e'::uuid, '7ef30597-dbaf-58bd-979e-738dbc5d2de8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'swelled', FALSE, 0, 0, NULL),
