  ('33c3312f-2146-584f-afcb-895a568c3c55'::uuid, '7f6393bc-ff01-5e65-839c-2c1020b3d1e2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'He doesn''t believe any of it is true.', FALSE, 1, NULL, NULL),
  ('e3d107e4-15c8-5de7-8249-f5f739975807'::uuid, '7f6393bc-ff01-5e65-839c-2c1020b3d1e2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'He is angered by it.', FALSE, 2, NULL, NULL),
  ('f5dfd6b2-b264-5a85-b3ce-84d16d313869'::uuid, '7f6393bc-ff01-5e65-839c-2c1020b3d1e2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'He is skeptical of it.', TRUE, 3, NULL, NULL),
  ('99016e99-cebe-5ab6-a7b1-c54d78792903'::uuid, '7f659b7f-e122-57f8-afb0-d88eea8682e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'If they have put all their effort into the perfection of one survival trick, they do not bother so much with the general complexities of the world around them.', FALSE, 0, NULL, NULL),
  ('cc440bf3-6a13-5ae1-b27a-3a602fa5e0ea'::uuid, '7f659b7f-e122-57f8-afb0-d88eea8682e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'All animals have a strong exploratory urge, but for some it is more crucial than others.', FALSE, 1, NULL, NULL),
  ('f47981f1-7c63-537b-9452-83e76c2bc889'::uuid, '7f659b7f-e122-57f8-afb0-d88eea8682e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It depends on how specialized they have become during the course of evolution.', FALSE, 2, NULL, NULL),
  ('d10d9307-e27f-5302-9c3c-a656c2a4ec59'::uuid, '7f659b7f-e122-57f8-afb0-d88eea8682e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'So long as the ant eater had its ants and the koala bear had gum leaves, then they are satisfied and the living is easy.', FALSE, 3, NULL, NULL),
  ('1d34e7da-dbeb-5ef1-9180-990fed73e305'::uuid, '7f659b7f-e122-57f8-afb0-d88eea8682e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The non-specialists, however, the opportunities of the animal world, can never afford to relax.', FALSE, 4, NULL, NULL),
