  ('cd9f95cb-d327-513c-8b32-c9b0ef5ce3cb'::uuid, '7fde9938-dc7e-5696-a823-a196b48d1688'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Nonetheless, they closed their blog with a challenge: "We ask chief executives, governments, NGOs, foundations: Are there any takers?"', FALSE, 1, NULL, NULL),
  ('7c90bd20-fd19-592c-a841-2fa73a7b4b20'::uuid, '7fde9938-dc7e-5696-a823-a196b48d1688'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'When Vijay Govindarajan and Christian Sarkar wrote a blog entry on Harvard Business Review in August 2010 mooting the idea of a "$300- house for the poor", they were merely expressing a suggestion.', FALSE, 2, NULL, NULL),
  ('127d5601-b685-53dd-8447-74505a121114'::uuid, '7fde9938-dc7e-5696-a823-a196b48d1688'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'"Of course, the idea we present here is an experiment," wrote Prof Govindarajan, a professor of international business at the Tuck School of Business at Dartmouth and Mr Sarkar, a marketing consultant who works on environmental issues - an almost apologetic disclaimer for having such a "far-out" idea.', FALSE, 3, NULL, NULL),
  ('efd6977e-196e-57e0-b88c-156bf4825853'::uuid, '7fed7139-740d-500f-8025-c2eec12d035b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, this accessibility depends heavily on reliable internet connectivity.', FALSE, 0, NULL, NULL),
  ('ef20a716-e719-5816-8e7e-b381db15e5b1'::uuid, '7fed7139-740d-500f-8025-c2eec12d035b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Thus, while online education opens doors for many, it also highlights the digital divide.', FALSE, 1, NULL, NULL),
  ('7033fb37-31c0-5e9f-8079-9c8f4997c368'::uuid, '7fed7139-740d-500f-8025-c2eec12d035b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In regions where internet access is limited, students face significant challenges.', FALSE, 2, NULL, NULL),
  ('3efd2e47-aa4e-5f12-9fb7-8d89561353a8'::uuid, '7fed7139-740d-500f-8025-c2eec12d035b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Students from remote areas can now access quality education without geographical constraints.', FALSE, 3, NULL, NULL),
