  ('699158aa-c360-5ed0-8470-fc8fc5af822c'::uuid, '8129d3c8-6261-5a4c-be3f-9d5726c25e58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In January 1937 the Spanish Republican government commissioned Pablo Picasso to create a mural on the theme of "technology" for the Spanish Pavilion at the 1937 World''s Fair in Paris.', FALSE, 0, NULL, NULL),
  ('4964cf71-d4e2-5e2b-98b8-cc0cd2e5557b'::uuid, '8129d3c8-6261-5a4c-be3f-9d5726c25e58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'On the first of May Picasso read George Steer''s moving eyewitness account of the bombing of Guernica and started sketches for what would become the world-famous painting, known as Guernica.', FALSE, 1, NULL, NULL),
  ('2702abe4-13c5-5592-b45b-a669b9ad2b41'::uuid, '8129d3c8-6261-5a4c-be3f-9d5726c25e58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Picasso was living in Paris at the time and hadn''t been to Spain for three years.', FALSE, 2, NULL, NULL),
  ('f4723884-618d-59ae-aa33-0917e323f958'::uuid, '8129d3c8-6261-5a4c-be3f-9d5726c25e58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'He still had connections to Spain as Honorary Director-in-Exile of the Prado Museum in Madrid, however, and so agreed to the commission.', FALSE, 3, NULL, NULL),
