  ('27dc9960-a877-532c-8dd0-a2eb1d4fbf7c'::uuid, '82a35fc9-41a7-5f41-aa51-601d5230837b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Choices must similarly be made about which aspects of the past should be formally taught to the next generation in the shape of school history lessons.', FALSE, 0, NULL, NULL),
  ('6b924170-123b-5c34-a95f-0275445528ad'::uuid, '82a35fc9-41a7-5f41-aa51-601d5230837b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They cannot put in everything: choices have to be made.', FALSE, 1, NULL, NULL),
  ('241e98aa-d2be-5266-8e90-a3b900dcb72a'::uuid, '82a35fc9-41a7-5f41-aa51-601d5230837b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'What history books tell us about the past is not everything that happened, but what historians have selected.', FALSE, 2, NULL, NULL),
  ('d6bf0f51-aa5b-5a4e-9908-bfd0a87c8881'::uuid, '82a35fc9-41a7-5f41-aa51-601d5230837b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'History is selective.', FALSE, 3, NULL, NULL),
  ('ccb92f94-f9e4-5cd6-9a9a-f30e15c7620a'::uuid, '82ad1569-c681-5788-9f45-4936641eaff0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The best way to protect the Amazon is to use laws governing human rights and probably international legislation.', TRUE, 0, NULL, NULL),
  ('771a0ef1-aafa-5fe5-9d17-ae8cf903c293'::uuid, '82ad1569-c681-5788-9f45-4936641eaff0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Protecting the rainforest is a vital top priority.', FALSE, 1, NULL, NULL),
  ('9d9fc165-b985-53d7-a183-b7dba7822e46'::uuid, '82ad1569-c681-5788-9f45-4936641eaff0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Using human rights law to protect the Amazon is more likely to prove promising.', TRUE, 2, NULL, NULL),
  ('0fa69565-c0bd-5a2e-972e-e9d68eac2845'::uuid, '82ad1569-c681-5788-9f45-4936641eaff0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The increase in regional deforestation and fires has made the protection more urgent.', TRUE, 3, NULL, NULL),
  ('1e93a16b-6259-53ea-8159-8a8ddf87562e'::uuid, '82ad1569-c681-5788-9f45-4936641eaff0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Protecting the Amazon is a common challenge of international law.', FALSE, 4, NULL, NULL),
  ('0f99e332-ca22-513e-9a8d-b2c4727ff1ed'::uuid, '82f7d06c-c4b9-56db-b9d0-557597476718'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'She found that positive emotions were often felt by the actors as they played those character''s emotions.', FALSE, 0, NULL, NULL),
  ('93561cdf-261f-5567-8c94-66d90590802d'::uuid, '82f7d06c-c4b9-56db-b9d0-557597476718'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, the more negative the emotion of the character, the less likely the actor would report feeling that emotion onstage', FALSE, 1, NULL, NULL),
  ('3a3c7823-b34a-5f89-a29f-2dbe14acf173'::uuid, '82f7d06c-c4b9-56db-b9d0-557597476718'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In a wonderful set of studies and subsequent book, Elly A. Konijn looked to the question of how much actors are aware of their performance as they perform it, and how much they let the character ''take over''.', FALSE, 2, NULL, NULL),
  ('4e8124ab-25a0-526e-a89b-e94247689cba'::uuid, '82f7d06c-c4b9-56db-b9d0-557597476718'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'She asked Dutch actors to rate their own emotions and the emotions of the characters they were playing across a range of affective states (from disgust and anxiety to tenderness and pleasure).', FALSE, 3, NULL, NULL),
