  ('687659d6-e5e0-5aeb-a694-76df8bcdf48b'::uuid, '8390c19f-3e37-5ece-84b3-d372a2946056'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To gauge optimism and pessimism, the researchers set up an experiment involving 22 calves.', FALSE, 0, NULL, NULL),
  ('7faa99c6-e153-50c3-85f3-049b38c3b2d5'::uuid, '8390c19f-3e37-5ece-84b3-d372a2946056'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Before they started the experiment, they trained the calves to understand which of their choices would lead to a reward.', FALSE, 1, NULL, NULL),
  ('60747724-497b-573f-af20-9164c178856d'::uuid, '8390c19f-3e37-5ece-84b3-d372a2946056'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The calves learned quickly which side of the pen held the milk reward.', FALSE, 2, NULL, NULL),
  ('ef0c0aec-f284-5bd9-874d-4a6af404bc4e'::uuid, '8390c19f-3e37-5ece-84b3-d372a2946056'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The hole at one end contained milk from a bottle, while the hole at the opposite end contained only an empty bottle and delivered a puff of air in calves'' faces.', FALSE, 3, NULL, NULL),
  ('4df7fcac-0ab6-56b1-8516-ad9da97e5498'::uuid, '8390c19f-3e37-5ece-84b3-d372a2946056'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In the training, each calf entered a small pen and found a wall with five holes arranged in a horizontal line, two-and-a-half feet apart.', FALSE, 4, NULL, NULL),
