  ('3399345f-97b7-5fac-86a1-123c3995fc22'::uuid, '8390c349-d823-5ebc-ae3e-204fa22f0ac5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'to highlight the generally held view about the start and end of World War II.', FALSE, 1, NULL, NULL),
