  ('9d45be5d-48c1-5e3b-8206-19080a4c7961'::uuid, '83b60055-ea88-54b7-adc4-f009b8c084f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Romance can be a part of a relationship, but it’s not everything. Healthy communication, equality and trust are all very important in a relationship.', TRUE, 0, NULL, NULL),
  ('e2e4bc70-3eba-585a-877f-fce402fa85dd'::uuid, '83b60055-ea88-54b7-adc4-f009b8c084f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Romance can signify a lot of passion, but people will eventually get tired in a relationship, especially when it has lasted for a long time. So it’s important that we should always find something new, to make the relationship fresh.', FALSE, 1, NULL, NULL),
  ('1b6c7369-c5a0-5e4e-92e3-337da8dc523e'::uuid, '83b60055-ea88-54b7-adc4-f009b8c084f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Romance consists of many things, including communication, equality and trust. Without these great characteristics, romance cannot survive within a relationship.', FALSE, 2, NULL, NULL),
  ('ed5a3b3c-690e-53cc-a29c-35708f1e6539'::uuid, '83b60055-ea88-54b7-adc4-f009b8c084f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Romance mainly exists in the movies, and we don’t often see it in our daily life. This is because it can cause more chaos and instability than passion, which is not healthy for a relationship.', FALSE, 3, NULL, NULL),
  ('939b935e-7a86-5823-8318-bd38d025fc13'::uuid, '83bb458f-ce18-59ae-bf56-83c9915a9e53'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'evidence', FALSE, 0, NULL, NULL),
