  ('2640aa83-25c4-5eb5-b4d0-5ec194e8188a'::uuid, '83d3a9fc-0696-5c4b-9042-baca3d2b6fea'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'You need to give four weeks'' notice before you intend to ask for a leave.', FALSE, 0, NULL, NULL),
  ('46b3d6f6-d967-56ee-bf1c-3fd0cf746daa'::uuid, '83d3a9fc-0696-5c4b-9042-baca3d2b6fea'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Upon returning, you will be assigned to the previous position if you leave for 60 days or less than 60 days.', FALSE, 1, NULL, NULL),
  ('c669ef19-94e3-5e29-bb8b-4b33ac1fbc9e'::uuid, '83d3a9fc-0696-5c4b-9042-baca3d2b6fea'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Employees should have same wage and benefits.', FALSE, 2, NULL, NULL),
  ('ac88bc43-976a-596b-b4e1-b7b84ed940c4'::uuid, '83d3a9fc-0696-5c4b-9042-baca3d2b6fea'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'If you leave for more than 60 days, you will be put in a comparable position.', FALSE, 3, NULL, NULL),
  ('ca146ff7-de30-5d3b-be94-d44efb60192a'::uuid, '83e7f9f4-7b3a-542e-8d7a-fdda705938b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, over-reliance on technology can sometimes replace the human element of personal training and coaching, which can be more effective in addressing individual needs.', FALSE, 0, NULL, NULL),
  ('3ab67f63-42b2-501d-9ddf-e1bcbfbe4384'::uuid, '83e7f9f4-7b3a-542e-8d7a-fdda705938b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They offer much more convenience and accountability.', FALSE, 1, NULL, NULL),
  ('37260cd8-5468-52dd-b9e1-d4dcbdd10658'::uuid, '83e7f9f4-7b3a-542e-8d7a-fdda705938b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For example, fitness apps and wearable tech can track progress and provide personalized workout plans.', FALSE, 2, NULL, NULL),
  ('5c7a21a4-9527-57fa-8f7c-0fb8c1930bc0'::uuid, '83e7f9f4-7b3a-542e-8d7a-fdda705938b8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Technology has revolutionized fitness.', FALSE, 3, NULL, NULL),
