  ('28c83737-087d-500a-9ffd-8f705560fa3d'::uuid, '850aed1d-55d6-51c4-a4fa-6e369ed0d789'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Yet these fires have not halted the advance of trees and shrubs.', FALSE, 0, NULL, NULL),
  ('f7f5538f-a257-5356-9703-59e1a1cd19dd'::uuid, '850aed1d-55d6-51c4-a4fa-6e369ed0d789'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The main tool used to drive out the trees and encourage the grasses is controlled fires, set every few years.', FALSE, 1, NULL, NULL),
  ('8173dc26-48ca-5747-8bc1-be4627c589eb'::uuid, '850aed1d-55d6-51c4-a4fa-6e369ed0d789'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Now, Dirac Twidwell, a range ecologist at the University of Nebraska, says he’s figured out why.', FALSE, 2, NULL, NULL),
  ('be9457f4-e22c-579b-b06d-2da831b942d6'::uuid, '850aed1d-55d6-51c4-a4fa-6e369ed0d789'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The sea of native grassland that once carpeted the United States'' Great Plains has steadily been disappearing — replaced at a disconcerting rate by trees and shrubs.', FALSE, 3, NULL, NULL),
  ('757040c4-65a9-508c-9dc7-4429743bc411'::uuid, '850aed1d-55d6-51c4-a4fa-6e369ed0d789'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The problem is not that controlled burns are too destructive, he says. It’s that they’re not destructive enough.', FALSE, 4, NULL, NULL),
