  ('6f931905-7865-5ced-9518-1fdede628b72'::uuid, '85790ed1-9ca2-5e9e-a77d-b019dc890f08'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'One of the key components of effective communication is active listening.', FALSE, 0, NULL, NULL),
  ('805a6c6d-5c55-5aa5-9df4-ce1fbf4994c5'::uuid, '85790ed1-9ca2-5e9e-a77d-b019dc890f08'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It is a skill that requires practice and patience to develop.', FALSE, 1, NULL, NULL),
  ('e53676f4-09a2-5a47-aa01-850550fd9a10'::uuid, '85790ed1-9ca2-5e9e-a77d-b019dc890f08'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Active listening involves giving full attention to the speaker, asking clarifying questions, and providing feedback.', FALSE, 2, NULL, NULL),
  ('ac866e62-298d-5d87-aad1-fe7f36b0fd69'::uuid, '85790ed1-9ca2-5e9e-a77d-b019dc890f08'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Effective communication is essential in both personal and professional relationships.', FALSE, 3, NULL, NULL),
  ('1b4ddc9d-ad61-570d-8ae2-03d6d57bc766'::uuid, '857db2c2-c798-5e3a-8d3d-5e575241ee58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Because bed bugs are extremely difficult to eliminate, the work should be carried out by trained pest control professionals.', FALSE, 0, NULL, NULL),
  ('04385efe-0590-5697-9128-39dbe7ccbf41'::uuid, '857db2c2-c798-5e3a-8d3d-5e575241ee58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'If the landlord refuses to deal with a bed bug infestation, the tenant can seek assistance from the government.', FALSE, 1, NULL, NULL),
  ('3936c9d9-bd37-500c-ac0b-d1eca12213a8'::uuid, '857db2c2-c798-5e3a-8d3d-5e575241ee58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Alternatively, the tenant may hire a professional exterminator directly.', FALSE, 2, NULL, NULL),
  ('de8665e1-5453-5d35-9155-81acecc0d5a5'::uuid, '857db2c2-c798-5e3a-8d3d-5e575241ee58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'If the tenant hires an exterminator independently, they should choose a reputable company and make sure the treatment is performed properly.', FALSE, 3, NULL, NULL),
