  ('4caa97cd-1d34-54bc-bf94-d164aad8563f'::uuid, '85ab9479-04c2-5c17-9f5d-aa6f45b771c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The brain is our most treasured possession.', FALSE, 0, NULL, NULL),
  ('81002c6c-6d77-5531-96e8-5cb6638abf3e'::uuid, '85ab9479-04c2-5c17-9f5d-aa6f45b771c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It coordinates our movements, our words, our relationships, and the ability to pass on our genes.', FALSE, 1, NULL, NULL),
  ('b52b7225-46ea-5e99-9672-0bac487a06cf'::uuid, '85ab9479-04c2-5c17-9f5d-aa6f45b771c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This selective process occurs due to a proactive boundary known as the blood-brain barrier.', FALSE, 2, NULL, NULL),
  ('7b5a761b-8a19-560d-8d87-1289c0204c6f'::uuid, '85ab9479-04c2-5c17-9f5d-aa6f45b771c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The barrier serves a vital role, but it also poses a tremendous challenge for scientists developing drugs to treat brain-based disorders.', FALSE, 3, NULL, NULL),
  ('8d61e73c-874e-5b0d-9f01-2bdf32cf50ae'::uuid, '85ab9479-04c2-5c17-9f5d-aa6f45b771c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Our body therefore protects the organ fiercely: The central nervous system polices particles traveling through the bloodstream and invites only the safest into our cognitive chamber.', FALSE, 4, NULL, NULL),
  ('4a1020df-eb56-5b40-8c1d-c93b24dec6b1'::uuid, '85b99fba-c978-5f28-ac87-f6e49b9d6a01'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'convince', FALSE, 0, NULL, NULL),
