  ('c1896f53-e171-5d6f-862b-528dcb576f3c'::uuid, '85cd7ed4-b08e-5358-92de-124a9e42647c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This is in order to ensure that the technology only serves to enable the athletes to reach their full physical potential and not to enhance their performance.', FALSE, 0, NULL, NULL),
  ('420810f9-beed-5e3b-8490-d7a168ab803c'::uuid, '85cd7ed4-b08e-5358-92de-124a9e42647c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Whether this will change is a point of contention for the industry.', FALSE, 1, NULL, NULL),
  ('ec68759b-0204-5932-80c6-a69ed34940fb'::uuid, '85cd7ed4-b08e-5358-92de-124a9e42647c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'When it comes to competitive sport, however, this technology poses a problem as the paralympics currently prohibits prostheses that move artificially.', FALSE, 2, NULL, NULL),
