  ('72ade924-c6c2-57c6-af9c-a5c2b79d32c1'::uuid, '870a02ea-afbd-5c01-b8b8-a522a98ba3ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'During the school year, we had the benefit of being both unaccountable and omnipotent.', FALSE, 0, NULL, NULL),
  ('f6e1582e-e19b-541d-926a-88ab986d5248'::uuid, '870a02ea-afbd-5c01-b8b8-a522a98ba3ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Insulated from the consequences of such decisions, and privy to all critical information about the case, we were able to solve complex business problems with relative ease.', FALSE, 1, NULL, NULL),
  ('5023afab-051f-5865-ad77-5031dbde416d'::uuid, '870a02ea-afbd-5c01-b8b8-a522a98ba3ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The information would be more nebulous and the outcomes of our decisions would be unpredictable.', FALSE, 2, NULL, NULL),
  ('3619d3c5-a932-5917-8ff1-e1246524502b'::uuid, '870a02ea-afbd-5c01-b8b8-a522a98ba3ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'We knew that once we began our internships, this would no longer be the case.', FALSE, 3, NULL, NULL),
