  ('009bfc67-9eb4-555d-91e5-948f4153d069'::uuid, '87d3e8f8-fbe2-52ed-8dd5-bee13f5db0dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'If a depression intensifies such that its maximum sustained winds reach 39 miles per hour, the tropical cyclone becomes a tropical storm.', FALSE, 0, NULL, NULL),
  ('b33bd5ba-e6e6-5955-8771-1189b5d189df'::uuid, '87d3e8f8-fbe2-52ed-8dd5-bee13f5db0dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A tropical cyclone is a generic term used by meteorologists to describe a rotating, organized system of clouds and thunderstorms.', FALSE, 1, NULL, NULL),
