  ('1da26816-ad82-5e5f-95e8-8ed3b5c04834'::uuid, '881a544f-6887-525c-b31e-ee979c392e37'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Throughout the 20th century, the manifestation of totalitarianism was an extreme measure of harsh political occurrences.', FALSE, 0, NULL, NULL),
  ('3c95844d-2dc6-5b1e-8cd5-bd12a26cd925'::uuid, '881a544f-6887-525c-b31e-ee979c392e37'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Totalitarianism is a political and social concept that explains a form of government where the state has all control over the civilians.', FALSE, 1, NULL, NULL),
  ('89c7eed4-ddda-508d-8508-7abdcdaf00cb'::uuid, '881a544f-6887-525c-b31e-ee979c392e37'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As put by Juan Linz, a totalitarian scholar, the three main factors of a totalitarianism government are ”a monistic center of power; an ideology developed, justified and pursued by the leadership; and mass participation in political and social goals encouraged and even demanded by that same leadership.”', FALSE, 2, NULL, NULL),
  ('9c57580b-1c1e-5903-b84f-eda92d50dd4a'::uuid, '881a544f-6887-525c-b31e-ee979c392e37'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Such government assumes full power, without any limitations.', FALSE, 3, NULL, NULL),
  ('34770d0b-ce79-5a73-a33d-a0522004e83f'::uuid, '881c7a40-50ac-59ac-afe3-c0e6b5b5a56a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The truth is that rivers (like all other objects on Earth) flow downhill due to gravity.', FALSE, 0, NULL, NULL),
  ('dc4651a5-d81a-5b2a-8ac3-1c5e0a2403e2'::uuid, '881c7a40-50ac-59ac-afe3-c0e6b5b5a56a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Sometimes that path is south but it is just as likely to be north, east, west, or some other direction in between.', FALSE, 1, NULL, NULL),
  ('3fd7c947-e929-5785-b795-b25b536e48f6'::uuid, '881c7a40-50ac-59ac-afe3-c0e6b5b5a56a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A common misconception about rivers is that they all flow south.', FALSE, 2, NULL, NULL),
  ('ec4829f9-c9f8-5c2f-8008-efa41e638e80'::uuid, '881c7a40-50ac-59ac-afe3-c0e6b5b5a56a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Perhaps some people think that all rivers flow toward the equator or that rivers like to flow down toward the bottom of north-oriented maps.', FALSE, 3, NULL, NULL),
  ('de704ef6-c2a6-5eba-8970-6929ae71fe67'::uuid, '881c7a40-50ac-59ac-afe3-c0e6b5b5a56a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'No matter where a river is located, it will take the path of least resistance and flow downhill as rapidly as possible.', FALSE, 4, NULL, NULL),
  ('9e3f3b92-d173-5ffb-8412-b8b9eb673979'::uuid, '883bc248-a88b-584d-a155-828416d17034'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'was challenged', TRUE, 0, 0, NULL),
