  ('658ec71c-7ef3-5e2a-b5e5-badcc4cf312a'::uuid, '885ab890-9979-5398-95d0-1b6e55b46657'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'meets', TRUE, 5, NULL, 1),
  ('551d8c2c-f205-5e95-a558-a1c08a4fbed2'::uuid, '886464bb-f2a8-5822-8cba-4aac10b28d46'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Therefore, this event led to widespread European exploration and colonization of the Americas, profoundly changing the course of world history.', FALSE, 0, NULL, NULL),
  ('179779f9-03fe-58c4-ba73-c031eb7bca00'::uuid, '886464bb-f2a8-5822-8cba-4aac10b28d46'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In 1492, Christopher Columbus embarked on a voyage that led to the discovery of the Americas.', FALSE, 1, NULL, NULL),
  ('fef276f7-420a-505c-936b-6b2d0c8ecaca'::uuid, '886464bb-f2a8-5822-8cba-4aac10b28d46'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, he unexpectedly landed in a New World, marking a pivotal moment in history.', FALSE, 2, NULL, NULL),
  ('5dd45718-0ddc-561b-9913-08abd3e8d8ad'::uuid, '886464bb-f2a8-5822-8cba-4aac10b28d46'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Sponsored by the Spanish monarchs, he intended to find a westward sea passage to Asia.', FALSE, 3, NULL, NULL),
  ('b1930176-6a69-507f-87b9-ede5fa0ac024'::uuid, '886b3348-4253-55b0-a591-0fadb4c63bef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There are one hundred thousand million stars in our own Milky Way alone, and then there are three thousand million other Milky Ways, or Galaxies, in universe.', FALSE, 0, NULL, NULL),
  ('7d269272-b5a9-55ef-8873-5e3fccf816a5'::uuid, '886b3348-4253-55b0-a591-0fadb4c63bef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Of all the planets in our solar system we are now pretty certain the Earth is the only one on which life can survive.', FALSE, 1, NULL, NULL),
  ('302a223e-a68e-5b4c-a0c2-fc0a5636e334'::uuid, '886b3348-4253-55b0-a591-0fadb4c63bef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But other suns, stars as the astronomers call them, are bound to have planets like our own, and as the number of stars in the universe is so vast, this possibility becomes virtual certainty.', FALSE, 2, NULL, NULL),
  ('dc982598-3b11-5459-855e-1e5d1be9d584'::uuid, '886b3348-4253-55b0-a591-0fadb4c63bef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'So the number of stars that we know exist is estimated at about 300 million million million.', FALSE, 3, NULL, NULL),
  ('6a71f9c5-4e5b-5860-983c-ebc648ee7922'::uuid, '886b3348-4253-55b0-a591-0fadb4c63bef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Mars is too dry and poor in oxygen, Venus far too hot, and so is Mercury, and the outer planets have temperatures near absolute zero and hydrogen-dominated atmospheres.', FALSE, 4, NULL, NULL),
  ('855dd72b-c613-5680-bf61-b152f349d9f9'::uuid, '88933426-36ed-5e09-9338-2bdd83822e59'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Communication was slow then, making the spread of information slow as well.', FALSE, 0, NULL, NULL),
  ('6179d7c0-90ac-57d8-89c9-a4c46fd72f66'::uuid, '88933426-36ed-5e09-9338-2bdd83822e59'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'One common method for sharing messages is email.', FALSE, 1, NULL, NULL),
  ('73f81c77-8650-5a99-91b9-4548c6c980fe'::uuid, '88933426-36ed-5e09-9338-2bdd83822e59'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'With increasing advancements in communication technology, it is more and more common for communication to take place online, which allows messages and information to be shared much faster.', FALSE, 2, NULL, NULL),
  ('c1173427-140e-5283-ad3d-826a16850334'::uuid, '88933426-36ed-5e09-9338-2bdd83822e59'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Decades ago, you would have had to deliver a message to someone by physically going to where the other person was or sending a physical letter in the mail.', FALSE, 3, NULL, NULL),
  ('43dfbd73-8e80-5dcb-a032-f1964525aa33'::uuid, '88933426-36ed-5e09-9338-2bdd83822e59'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It is one of the fastest ways to share information, and this is especially true for businesses and professional communication.', FALSE, 4, NULL, NULL),
  ('70a74584-0d9f-5700-949b-76941477c492'::uuid, '88ccca42-5eae-5033-8b1b-898372640ee0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'deny', FALSE, 0, 0, NULL),
