  ('1b4f2064-6455-558c-8e11-5d4746851b69'::uuid, '8ab7ade5-2409-50ee-9c6c-d42c59b84906'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A liver detox, cleanse, or flush is a program that claims to take out toxins in your body, help you lose weight, or improve your health.', FALSE, 1, NULL, NULL),
  ('85d5b60b-1b19-508d-ba22-2f42e336b12b'::uuid, '8ab7ade5-2409-50ee-9c6c-d42c59b84906'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Studies have found that liver injuries from herbal and dietary supplements are on the rise. Black tea extract, for example, can cause damage like that from hepatitis.', FALSE, 2, NULL, NULL),
  ('a31de696-2f8e-5517-a8e2-af93d26cc994'::uuid, '8ab7ade5-2409-50ee-9c6c-d42c59b84906'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In fact, detoxes may harm your liver.', FALSE, 3, NULL, NULL),
