  ('1e3d7d22-e8c2-58fa-9705-0253bdeca28f'::uuid, '8afa5c5d-45d4-5448-a8a3-3d9dc942df3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'finished', TRUE, 19, 4, NULL),
  ('8b1f50dd-a1f3-5841-9e99-2e51fbe4b8ac'::uuid, '8b0d9711-f763-5513-96fe-acae3a2852d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Business students are finding it increasingly difficult to get employment. as the standard of law courses has declined since 2007. Employers have criticized the schools for adopting unsatisfactory teaching methods. and have urged them to ensure students get higher grades.', FALSE, 0, NULL, NULL),
  ('41724554-0d25-540f-b52b-cc90a1962a9d'::uuid, '8b0d9711-f763-5513-96fe-acae3a2852d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In order to improve the chances of their students obtaining jobs after they have finished their courses, some business schools are adjusting their grades. These adjustments are being made to all grades awarded since 2007 but instead of C benefiting the students it is, in some instances, having the opposite effect.', TRUE, 1, NULL, NULL),
  ('46723a39-f235-5faf-8a84-924313968ce4'::uuid, '8b0d9711-f763-5513-96fe-acae3a2852d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Some business schools have realized that their grading system has been inaccurate since 2007 and are currently making changes to correct the errors. Students'' grades are being revised, and employers have welcomed this move as it means that they will be able to employ better qualified students.', FALSE, 2, NULL, NULL),
  ('1576cfcb-66ce-5acd-9c0f-cb3dd9d9b6ad'::uuid, '8b0d9711-f763-5513-96fe-acae3a2852d3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Since 2007, the education of business students has been improving but this has not been reflected in the grades that they are achieving. Business schools have been under pressure from employers to ensure that the grades that students are achieving match their abilities far better than in recent years.', FALSE, 3, NULL, NULL),
  ('2896e328-2d8b-56ef-b3c3-475db858e376'::uuid, '8b0eb77f-4900-5806-b6d7-eb5dd7bf87dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'tremendous', TRUE, 0, NULL, 2),
  ('3f0b4ccd-fa2b-5c21-af9a-e744c6fdb166'::uuid, '8b0eb77f-4900-5806-b6d7-eb5dd7bf87dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'dignified', TRUE, 1, NULL, 1),
  ('6ed96dda-ca30-5819-8f0e-6628d140a1d1'::uuid, '8b0eb77f-4900-5806-b6d7-eb5dd7bf87dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'restricts', FALSE, 2, NULL, NULL),
