  ('a2784333-5a0b-5626-8071-d3f8bfbbf0da'::uuid, '8b0eb77f-4900-5806-b6d7-eb5dd7bf87dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'professional', FALSE, 5, NULL, NULL),
  ('6e6ecd47-8290-56ee-8fdd-b3880628383d'::uuid, '8b0eb77f-4900-5806-b6d7-eb5dd7bf87dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'otherwise', FALSE, 6, NULL, NULL),
  ('95ccc112-fc31-5f2a-b50a-82798d246b57'::uuid, '8b195c53-4935-52cd-b005-2268004dd00a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, any employee who wants to acquire more varied and responsible duties will not feel satisfied for long staying with the same and boring job.', FALSE, 0, NULL, NULL),
  ('2439f3eb-31f0-5bb1-b9dc-c16e6b060460'::uuid, '8b195c53-4935-52cd-b005-2268004dd00a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A number of staff who wish to turn up, do a simple job and go home is relatively happy if they believe their work is secure.', FALSE, 1, NULL, NULL),
  ('0e3b1f0b-aa9a-517c-aba6-16152d0dc6a4'::uuid, '8b195c53-4935-52cd-b005-2268004dd00a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'If this opportunity does not exist, they are most likely to be demotivated.', FALSE, 2, NULL, NULL),
  ('6d424d8d-2ce7-5ae9-a395-b6ddf9b8c319'::uuid, '8b195c53-4935-52cd-b005-2268004dd00a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'People want to keep working hard only if there are opportunities for promotion to a more challenging job.', FALSE, 3, NULL, NULL),
  ('d5ae907e-924b-56aa-be43-26558795de58'::uuid, '8b4c2d87-3a3f-5ef9-bb02-1d4fc5fdd431'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To raise the status of psychology as a serious science', FALSE, 0, NULL, NULL),
  ('4beab85b-8232-5361-bfce-0cc3fc1c5dad'::uuid, '8b4c2d87-3a3f-5ef9-bb02-1d4fc5fdd431'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To be able to make predictions about human behavior', TRUE, 1, NULL, NULL),
  ('2a1990aa-8981-5093-a438-c96579263647'::uuid, '8b4c2d87-3a3f-5ef9-bb02-1d4fc5fdd431'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To permit scientists to experiment with human subjects', FALSE, 2, NULL, NULL),
  ('22022265-6e98-5b66-9c04-8dec49c0ba71'::uuid, '8b4c2d87-3a3f-5ef9-bb02-1d4fc5fdd431'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To help students understand the art of psychology', FALSE, 3, NULL, NULL),
  ('42046ae5-4be2-593f-b06d-f1c751550d02'::uuid, '8b6904b8-47bb-584d-9866-a3efe8942d6e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Because the barons pressured him, he agreed to a series of legal reforms limiting his power.', FALSE, 0, NULL, NULL),
  ('d6013120-63ba-5166-bc09-26b6e65529d0'::uuid, '8b6904b8-47bb-584d-9866-a3efe8942d6e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In 1215, King John of England signed the Magna Carta, a document that significantly influenced the course of history.', FALSE, 1, NULL, NULL),
  ('1aa29485-33ea-54f1-802f-be7bde183495'::uuid, '8b6904b8-47bb-584d-9866-a3efe8942d6e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Consequently, this event laid the foundation for modern democracy and the rule of law.', FALSE, 2, NULL, NULL),
  ('50dbc695-32a6-50ac-a5c5-c378a8dfdec7'::uuid, '8b6904b8-47bb-584d-9866-a3efe8942d6e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Thus, the Magna Carta is often cited as a symbol of freedom against arbitrary rule, influencing legal systems around the world.', FALSE, 3, NULL, NULL),
  ('53916e65-462d-5ea8-b926-73ef0876ccd8'::uuid, '8b6e5134-49d8-5ed1-a261-f1d3c8835fb5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'disapointed', FALSE, 0, NULL, NULL),
