  ('e40ea30a-04b1-540a-b37a-9511ee68f106'::uuid, '8cd8321d-5cb2-5982-95c1-260fccc2ad96'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It can attract more future investment in the future.', FALSE, 1, NULL, NULL),
  ('dc57e369-ff96-57bd-b876-7614e58ae4d6'::uuid, '8cd8321d-5cb2-5982-95c1-260fccc2ad96'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It is the third version of the Google glass.', FALSE, 2, NULL, NULL),
  ('b1b6d953-0978-5e80-b005-08183f272fa7'::uuid, '8cd8321d-5cb2-5982-95c1-260fccc2ad96'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It is able to make a one-minute long video.', TRUE, 3, NULL, NULL),
  ('94fcd904-d52a-5cc1-9b25-87ce8df02414'::uuid, '8cf222d4-4312-5206-a399-9460210316d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'He was able to argue that the State was the only organ that was genuinely capable of responding to social needs and social interests, unlike markets.', FALSE, 0, NULL, NULL),
  ('9cc70d0f-10fb-5a3c-a1d0-9ee1343b9c11'::uuid, '8cf222d4-4312-5206-a399-9460210316d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There had already been some legislation to prevent such abuses - such as various Factory Acts to prevent the exploitation of child workers.', FALSE, 1, NULL, NULL),
  ('20a4aed5-9576-5c69-b5d5-e30d9037ba89'::uuid, '8cf222d4-4312-5206-a399-9460210316d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Markets may be good at encouraging innovation and following trends, but they were no good at ensuring social equality.', FALSE, 2, NULL, NULL),
  ('07fb3f9a-b965-508f-aa90-4fc6db20789f'::uuid, '8cf222d4-4312-5206-a399-9460210316d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These markets had become rapidly dominated by powerful enterprises who were able to act in their own interests, against the interests of both workers and consumers.', FALSE, 3, NULL, NULL),
  ('c3c21050-dd7f-5124-879d-6eb79a4b6eb2'::uuid, '8cf222d4-4312-5206-a399-9460210316d7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Mill was able to see an expanded role for the State in such legislation to protect us against powerful interests.', FALSE, 4, NULL, NULL),
  ('830a5798-0728-521c-b663-5d270e751ef7'::uuid, '8cf6c208-f77c-5b1b-8430-fb782f42f02c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'the 90 minute rule', TRUE, 0, NULL, NULL),
  ('722513c1-6a2b-54cc-8be7-d78771f9261d'::uuid, '8cf6c208-f77c-5b1b-8430-fb782f42f02c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'your normal waking state', FALSE, 1, NULL, NULL),
