  ('f9a3896a-b7ab-58b0-a360-4155e854fa47'::uuid, '8cf6c208-f77c-5b1b-8430-fb782f42f02c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'your feelings', FALSE, 3, NULL, NULL),
  ('e747fdd4-f874-5117-9f3a-8969dd0aacea'::uuid, '8d014810-e40a-5ef3-9345-e96dc97843f6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Crops are cultivated plants grown on a large scale for food and other purposes.', FALSE, 0, NULL, NULL),
  ('5ccdc489-77fb-5fba-96e9-6dfecb38be52'::uuid, '8d014810-e40a-5ef3-9345-e96dc97843f6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Additionally, many crops are used in various industries, such as cotton in textiles.', FALSE, 1, NULL, NULL),
  ('ab7984eb-5a8e-581f-a0fb-7ed6744e679f'::uuid, '8d014810-e40a-5ef3-9345-e96dc97843f6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They form the basis of the global food supply, providing essential nutrients to humans and animals.', FALSE, 2, NULL, NULL),
  ('4298115e-164f-522d-9eac-7dfaa40a57ea'::uuid, '8d014810-e40a-5ef3-9345-e96dc97843f6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, the intensive cultivation of single crop species can lead to soil depletion and increased vulnerability to pests and diseases.', FALSE, 3, NULL, NULL),
  ('b3cd5130-fb15-5637-879d-177ee873e6fc'::uuid, '8d1b63a4-1aa4-50bd-bf33-c2fddcdf8dba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Too much rest can have negative results.', FALSE, 0, NULL, NULL),
  ('610b6887-778b-5d9e-8509-376289fe35dc'::uuid, '8d1b63a4-1aa4-50bd-bf33-c2fddcdf8dba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Activity and exercise are forms of rest.', TRUE, 1, NULL, NULL),
  ('69b4530e-2ad9-5c9a-9c45-281e92838d4e'::uuid, '8d1b63a4-1aa4-50bd-bf33-c2fddcdf8dba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Managers should allow rest time for workers.', FALSE, 2, NULL, NULL),
  ('3cd95087-5608-5b97-b176-a6e3dadabdd0'::uuid, '8d1b63a4-1aa4-50bd-bf33-c2fddcdf8dba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Few people know the real meaning of rest.', FALSE, 3, NULL, NULL),
  ('08b73006-6808-5b02-a87e-cdc3f3afac48'::uuid, '8d32865e-ec2e-5cfe-90b5-ad15b3e579ff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The longer a child can resist the temptation has been correlated with higher general competency later in life.', FALSE, 0, NULL, NULL),
