  ('d6d48d79-f7d7-59fb-8c8a-b446be741ea7'::uuid, '8db53486-b159-596f-9831-6fa78b35505e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Since it touches almost every facet of our life, educated people need at least some acquaintance with its structure and operation.', FALSE, 0, NULL, NULL),
  ('f6ed679d-6b65-5d56-97ee-638ede32c134'::uuid, '8db53486-b159-596f-9831-6fa78b35505e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Science is a dominant theme in our culture.', FALSE, 1, NULL, NULL),
  ('90eaa38d-daf8-5427-a2a2-544f2e611669'::uuid, '8db53486-b159-596f-9831-6fa78b35505e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'An understanding of general characteristics of science as well as specific scientific concepts is easier to attain if one knows something about the things that excite and frustrate the scientist.', FALSE, 2, NULL, NULL),
