  ('6fcec638-7de7-5f58-996e-0aed30088145'::uuid, '8e2a748c-c43d-560b-9f34-55b9b6486c76'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'intriguing', TRUE, 19, 4, NULL),
  ('595ed882-8cd8-5c31-acde-2c3a07c438f4'::uuid, '8e4e8827-212a-52e0-8173-85b21a67e46b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But in the industrial era destroying the enemy’s productive capacity means bombing the factories which are located in the cities.', FALSE, 0, NULL, NULL),
  ('43a07568-5301-5ae8-9e0c-21ec94a427e4'::uuid, '8e4e8827-212a-52e0-8173-85b21a67e46b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'So in the agrarian era, if you need to destroy the enemy’s productive capacity, what you want to do is burn his fields, or if you’re really vicious, salt them.', FALSE, 1, NULL, NULL);
INSERT INTO _pte_local_seed_options (public_id, question_public_id, created_at, updated_at, deleted, text, correct, order_index, blank_index, correct_gap_index) VALUES
  ('a4a86ec4-329c-5a14-95f8-69ec4ed73092'::uuid, '8e4e8827-212a-52e0-8173-85b21a67e46b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The idea is to destroy the enemy’s productive capacity, and depending upon the economic foundation, that the productive capacity is different in each case.', FALSE, 2, NULL, NULL),
  ('c86e7a12-110a-5cef-b8bd-74d5a1a084b6'::uuid, '8e4e8827-212a-52e0-8173-85b21a67e46b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'How do you do battle with your enemy?', FALSE, 3, NULL, NULL),
  ('ea332d85-613e-5c81-a354-9f6832476388'::uuid, '8e4e8827-212a-52e0-8173-85b21a67e46b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'With regard to defence, the purpose of the military is to defend the nation and be prepared to do battles with its enemy.', FALSE, 4, NULL, NULL),
  ('cab60bf1-eb75-5fea-b08d-3fa3b9938994'::uuid, '8e4e8827-212a-52e0-8173-85b21a67e46b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Now in the information era, destroying the enemy’s productive capacity means destroying the information infrastructure.', FALSE, 5, NULL, NULL),
  ('7bfeb02e-02a2-51c9-b492-8e67b7823d64'::uuid, '8e676909-8e5b-53b5-9353-8d81560f6a91'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For example, if the researcher is interested in dog owners'' interactions with their dogs, they might tally the number of times the owner talks to their dog during a walk.', FALSE, 0, NULL, NULL),
  ('180155f6-ae3f-5e7b-b946-1ceea5c86634'::uuid, '8e676909-8e5b-53b5-9353-8d81560f6a91'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'While they may want to study everything about the people in the chosen setting, this may not be realistic given the complexities of human behavior.', FALSE, 1, NULL, NULL),
  ('98116468-1b13-5f81-8c6a-c09498df48dc'::uuid, '8e676909-8e5b-53b5-9353-8d81560f6a91'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As a result, the researchers must focus observations on the specific behaviors and responses they are most interested in studying.', FALSE, 2, NULL, NULL),
  ('7a362033-695f-59a4-8c1c-7f865c83afde'::uuid, '8e676909-8e5b-53b5-9353-8d81560f6a91'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Before going into the field, researchers must define the scope of their research.', FALSE, 3, NULL, NULL),
