  ('6184e3c4-ed12-5a51-a8fa-211df1f12770'::uuid, '8e8cdd13-58a0-58fd-9962-55f1ffdd8fdc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The natural structure found within leaves could improve the performance of everything from rechargeable batteries to high-performance gas sensors, according to an international team of scientists.', FALSE, 0, NULL, NULL),
  ('a308aa0e-3fb9-565a-b31d-57661e74b59c'::uuid, '8e8cdd13-58a0-58fd-9962-55f1ffdd8fdc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The material could improve the performance of rechargeable batteries, optimising the charge and discharge process and relieving stresses within the battery electrodes, which, at the moment, limit their life span.', FALSE, 1, NULL, NULL),
  ('39cd95c3-58b3-5e92-bafc-6591233c6ec0'::uuid, '8e8cdd13-58a0-58fd-9962-55f1ffdd8fdc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The researchers have designed a porous material that utilises a vascular structure, such as that found in the veins of a leaf, and could make energy transfers more efficient.', FALSE, 2, NULL, NULL),
  ('50897f21-77ac-5a21-aa77-0052039afdba'::uuid, '8e8cdd13-58a0-58fd-9962-55f1ffdd8fdc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The same material could be used for high performance gas sensing or for catalysis to break down organic pollutants in water.', FALSE, 3, NULL, NULL),
