  ('bbf26d45-3e69-581a-b38a-cb391c8b4695'::uuid, '8e9d6276-4cc2-5929-9b80-b09a34bcf422'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Instead of moving along a straight line, the jet stream flows in a wavelike fashion; the waves propagate eastward (in the Northern Hemisphere) at speeds considerably slower than the wind speed itself.', FALSE, 0, NULL, NULL),
  ('139db0cb-c91a-5983-9bfb-989815a4e250'::uuid, '8e9d6276-4cc2-5929-9b80-b09a34bcf422'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Since the progress of an airplane is aided or impeded depending on whether tail winds or head winds are encountered.', FALSE, 1, NULL, NULL),
  ('e16ff5a0-1034-58dc-ae43-f88431a42099'::uuid, '8e9d6276-4cc2-5929-9b80-b09a34bcf422'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They are caused by great temperature differences between adjacent air masses.', FALSE, 2, NULL, NULL),
  ('0eec1ba0-80b2-5c8f-8cde-60622f386417'::uuid, '8e9d6276-4cc2-5929-9b80-b09a34bcf422'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In the Northern Hemisphere the jet stream is sought by eastbound aircraft, in order to gain speed and save fuel, and avoided by westbound aircraft.', FALSE, 3, NULL, NULL),
  ('ae70ccaa-dce8-57a8-ba67-cd6f825956dd'::uuid, '8e9d6276-4cc2-5929-9b80-b09a34bcf422'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Jet stream, narrow, swift currents or tubes of air found at heights ranging from 7 to 8 mi (11.3–12.9 km) above the surface of the earth.', FALSE, 4, NULL, NULL),
  ('250c4b11-ea6a-540a-95a7-da5cef55ab7c'::uuid, '8ea2e746-b490-5d87-9da0-867d0e5887b6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'have', TRUE, 0, NULL, 2),
