  ('5f44abed-c5a1-5160-9090-6cb88396296d'::uuid, '8edcf5b3-936e-5c04-b7df-9272943d65b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They also learned a great deal about manure and other fertilizers.', FALSE, 0, NULL, NULL),
  ('b8a9b2b2-effe-5b16-b21a-39797779444c'::uuid, '8edcf5b3-936e-5c04-b7df-9272943d65b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Historians are now agreed that beginning in the 17th century and continuing throughout the 18th century, England witnessed an agricultural revolution.', FALSE, 1, NULL, NULL),
  ('4e9505ea-7775-5da7-a0de-82d8ca173351'::uuid, '8edcf5b3-936e-5c04-b7df-9272943d65b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In other words, many English farmers were treating farming as a science, and all this interest eventually resulted in greater yields.', FALSE, 2, NULL, NULL),
  ('2af38371-d639-5d4c-821d-440e48055ed9'::uuid, '8edcf5b3-936e-5c04-b7df-9272943d65b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'English (and Dutch) farmers were the most productive farmers of the century and were continually adopting new methods of farming and experimenting with new types of vegetables and grains.', FALSE, 3, NULL, NULL),
  ('ea5d274d-5739-5871-8385-46b8cd069de9'::uuid, '8eea2f28-8285-5fdf-8929-12d3efc4dffe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Ethics, a branch of philosophy, deals with questions of morality and human values.', FALSE, 0, NULL, NULL),
  ('5b044614-700c-585f-9cb7-66d19746cd80'::uuid, '8eea2f28-8285-5fdf-8929-12d3efc4dffe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In contrast, deontological ethics focus on the inherent rightness or wrongness of actions, regardless of their consequences.', FALSE, 1, NULL, NULL),
  ('c86b2a23-a4e9-52fd-a44f-6d227a971ce7'::uuid, '8eea2f28-8285-5fdf-8929-12d3efc4dffe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It explores concepts of right and wrong, justice, and virtue.', FALSE, 2, NULL, NULL),
  ('5143ac2b-ea5a-5ab4-abc0-74053d6bb5ac'::uuid, '8eea2f28-8285-5fdf-8929-12d3efc4dffe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For instance, utilitarianism emphasizes the greatest good for the greatest number.', FALSE, 3, NULL, NULL),
  ('e5927901-0262-5259-bbeb-db4bfd94994f'::uuid, '8eea2f28-8285-5fdf-8929-12d3efc4dffe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Different ethical theories propose varied criteria for moral judgments.', FALSE, 4, NULL, NULL),
