  ('127aad9d-6f85-5d0a-ad7d-b45150cf1d04'::uuid, '8f1a2130-9cb8-5f07-ac74-96b7d7f2fd44'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Human geography is one of the two major branches of geography, together with physical geography.', FALSE, 0, NULL, NULL),
  ('c21b6a71-ee6a-5491-9b8b-0998a2d601ae'::uuid, '8f1a2130-9cb8-5f07-ac74-96b7d7f2fd44'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It is the study of the many cultural aspects found throughout the world and how they relate to the spaces and places where they originate.', FALSE, 1, NULL, NULL),
  ('00bd9248-efca-5c3b-966c-5bf2e006cf99'::uuid, '8f1a2130-9cb8-5f07-ac74-96b7d7f2fd44'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'He used landscapes as the defining unit of geographic study and said that cultures develop because of the landscape and also, conversely, help to develop the landscape.', FALSE, 2, NULL, NULL),
  ('c3e82376-7119-5756-bc3d-8f4959adbc7a'::uuid, '8f1a2130-9cb8-5f07-ac74-96b7d7f2fd44'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It developed out of the University of California, Berkeley and was led by Professor Carl Sauer.', FALSE, 3, NULL, NULL),
  ('a2f8b83d-7403-57d8-a42e-0842e697a9a3'::uuid, '8f2ca1ae-3e76-56a4-8c79-e6aef61082a4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Lately, they''re ''running out of money'' at a faster clip, he said.', FALSE, 0, NULL, NULL),
  ('9c025658-dfef-59e1-aba6-acdc3082a35f'::uuid, '8f2ca1ae-3e76-56a4-8c79-e6aef61082a4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Purchases are really dropping off by the end of the month even more than last year,” Duke said. “This end-of-month [purchases] cycle is growing to be a concern.', FALSE, 1, NULL, NULL),
  ('06022e41-1a8d-52ca-bcf4-13f42680d55a'::uuid, '8f2ca1ae-3e76-56a4-8c79-e6aef61082a4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Wal-Mart''s core shoppers are running out of money much faster than a year ago due to rising gasoline prices, and the retail giant is worried, CEO Mike Duke said Wednesday.', FALSE, 2, NULL, NULL),
  ('7721d747-7bf9-54a2-b506-3913d07c7d4f'::uuid, '8f2ca1ae-3e76-56a4-8c79-e6aef61082a4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'''We''re seeing core consumers under a lot of pressure,'' Duke said at an event in New York. ''There''s no doubt that rising fuel prices are having an impact.''', FALSE, 3, NULL, NULL),
  ('ca2c2ec2-7913-5309-b0cb-1eddadb20a80'::uuid, '8f2ca1ae-3e76-56a4-8c79-e6aef61082a4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Wal-Mart shoppers, many of whom live paycheck to paycheck, typically shop in bulk at the beginning of the month when their paychecks come in.', FALSE, 4, NULL, NULL),
