  ('7370ad35-8ed7-5712-9216-4d2ce8282703'::uuid, '8ffb277f-5d24-5e39-84b9-9ef4e5e3fcf6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The value of history also depends upon the chronological presentation of events through time.', FALSE, 0, NULL, NULL),
  ('f1175694-8982-5246-b247-83a1c6944238'::uuid, '8ffb277f-5d24-5e39-84b9-9ef4e5e3fcf6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'That is not possible when historical events or topics are isolated and extracted from the web of historic time to serve some other curricular purpose.', FALSE, 1, NULL, NULL),
  ('863140bc-b710-5163-b9b1-fee0c3b8e9a0'::uuid, '8ffb277f-5d24-5e39-84b9-9ef4e5e3fcf6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It is only through a chronological survey that students can begin to understand the process of social and cultural change, which is one of the principal purposes of history.', FALSE, 2, NULL, NULL),
  ('efe5abde-5b32-5201-b173-c86b24085683'::uuid, '8ffb277f-5d24-5e39-84b9-9ef4e5e3fcf6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The people and events of the past can only be understood when viewed within the larger context in which they existed.', FALSE, 3, NULL, NULL),
  ('36c500eb-99ba-50bb-843b-be3767b7aff4'::uuid, '901acb94-bf60-5573-9e54-3d41d2c70718'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A healthier life requires various small changes to diverse aspects of our life, such as diet, exercise and so on.', TRUE, 0, NULL, NULL),
  ('1105c245-a0f9-5911-8592-50b5ccba4d83'::uuid, '901acb94-bf60-5573-9e54-3d41d2c70718'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Healthier lifestyles can bring people a great deal of benefits, including losing weight, being more active and feeling healthier.', FALSE, 1, NULL, NULL),
  ('7890fce5-8c53-5f35-b4c0-0ac37a049f22'::uuid, '901acb94-bf60-5573-9e54-3d41d2c70718'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Some delicate adjustments in a limited scope of areas are believed to help us to lead a healthier lifestyle.', FALSE, 2, NULL, NULL),
  ('2a85e85f-e98a-5881-a70b-3f723a3800f2'::uuid, '901acb94-bf60-5573-9e54-3d41d2c70718'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Apart from making small changes to our life, controlling our genes can also make us healthier.', FALSE, 3, NULL, NULL),
