  ('99ce09eb-3a6e-59d9-a441-3c5c5390ceda'::uuid, '909e0f93-7504-585d-be3f-b7eb21579055'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It is a way of mindful travelling, where you intentionally devote time to get immersed into things of importance to you rather than following a checklist of things to see and do.', FALSE, 0, NULL, NULL),
