  ('6a2989b5-1c2d-5a28-a67c-62530db7c0e2'::uuid, '90f43a40-052b-56ec-9f6e-910f4bb455f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Upon further observation, he found the goats eating what appeared to be red berries (coffee cherries).', FALSE, 1, NULL, NULL),
  ('236a5ea6-632a-556b-a505-21e6857f7979'::uuid, '90f43a40-052b-56ec-9f6e-910f4bb455f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'An old legend states that coffee was first discovered in Ethiopia in AD 850 by a herdsman named Kaldi.', FALSE, 2, NULL, NULL),
  ('90873d82-a857-5504-b260-d92754764092'::uuid, '90f43a40-052b-56ec-9f6e-910f4bb455f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Kaldi also ate the berries. After experiencing a similar feeling of elation and energy, he brought the berries to local monks.', FALSE, 3, NULL, NULL),
  ('35fabb18-1288-593c-b43a-33bf4b9d80e4'::uuid, '90f43a40-052b-56ec-9f6e-910f4bb455f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They came up with the idea of drying and boiling the cherries to make a beverage, hence the birth of coffee.', FALSE, 4, NULL, NULL),
  ('47575b63-eed4-54bf-bd43-39264812616a'::uuid, '9116fa12-398a-56be-9c3c-a6227d729da4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, if your brand name reflects a key benefit of your service, such as ''Budget Car Rental'', then you may want to consider translating it for other markets.', FALSE, 0, NULL, NULL),
  ('4aa8c5b4-7394-523d-92e7-60600c30cfe8'::uuid, '9116fa12-398a-56be-9c3c-a6227d729da4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'So a made-up word or compound word can be a good idea.', FALSE, 1, NULL, NULL),
  ('5d5b4c7c-2546-5633-948a-5df305822f10'::uuid, '9116fa12-398a-56be-9c3c-a6227d729da4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Ideally, the brand name you choose should be one that doesn''t require translation.', FALSE, 2, NULL, NULL),
  ('f2732eca-28f6-57b4-96f5-ea96b03ef8cd'::uuid, '9116fa12-398a-56be-9c3c-a6227d729da4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In other words, it''s the one that''s simple, easy to pronounce and has no particular meaning.', FALSE, 3, NULL, NULL),
