  ('b7443a68-ab6e-5e42-9d07-c25d5e31abc5'::uuid, '93257e06-ced1-574a-9804-448decc95add'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'He and colleagues were testing a hypothesis that the sounds of nature influence where animals lived and how they forage.', FALSE, 0, NULL, NULL),
  ('057acd63-b868-5e0a-ae87-a23f9a38f5ed'::uuid, '93257e06-ced1-574a-9804-448decc95add'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There’s a lot of research suggesting that human noise negatively affects animals, from communication to foraging to reproduction, and even survival,’ Gomes says.', FALSE, 1, NULL, NULL),
  ('9e10d323-1a47-53d4-9b1d-a81ce0b2bd76'::uuid, '93257e06-ced1-574a-9804-448decc95add'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For two summers in Idaho’s Pioneer Mountains, the roar of rushing white water filled the air.', FALSE, 2, NULL, NULL),
  ('1c61a00b-d59d-5830-b0fd-26a3b6ec458b'::uuid, '93257e06-ced1-574a-9804-448decc95add'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But where the loud sounds prevailed, only gentle streams flowed by.', FALSE, 3, NULL, NULL),
  ('64599d7c-1ebb-56e7-ba84-7934e63f988a'::uuid, '93257e06-ced1-574a-9804-448decc95add'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These phantom rivers were part of an experiment led by ecologist Dylan Gomes of Boise State University.', FALSE, 4, NULL, NULL),
  ('e3592620-ac36-567a-b976-42aca65cd682'::uuid, '938124cf-7947-5bc8-8ae1-702129d3c823'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'has health benefits', FALSE, 0, NULL, NULL),
