  ('fea47d6a-9720-5d96-a2ff-de643558a7da'::uuid, '93c03ea2-8cb4-5606-a66f-5f4a2555a8bb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It has been shown that regular exercise can improve mood and reduce symptoms of depression and anxiety.', FALSE, 0, NULL, NULL),
  ('ab05d7ad-26f5-5dff-8e51-b24ec461df57'::uuid, '93c03ea2-8cb4-5606-a66f-5f4a2555a8bb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Additionally, exercise is essential for maintaining physical health, including cardiovascular fitness and muscle strength.', FALSE, 1, NULL, NULL),
  ('758c9480-c54b-547c-9deb-cc11b33c94cd'::uuid, '93c03ea2-8cb4-5606-a66f-5f4a2555a8bb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In recent years, there has been growing recognition of the importance of physical activity for mental and emotional well-being.', FALSE, 2, NULL, NULL),
