  ('61ac0212-8f36-5261-86cd-3f88141da75d'::uuid, '93fa7750-588f-552e-bfb5-d886c128c15e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'When people have more options, they will have a higher expectation, and tend to feel less satisfied with results, even when they’re good results.', TRUE, 0, NULL, NULL),
  ('cae75696-39d1-57b6-9ad4-f0cfb7e104d9'::uuid, '93fa7750-588f-552e-bfb5-d886c128c15e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'People need to make many choices when buying a good pair of jeans, so making more choices can make it possible for people to do better.', FALSE, 1, NULL, NULL),
  ('f43bd1f7-fe20-5fdf-814c-b8af1a37d8d4'::uuid, '93fa7750-588f-552e-bfb5-d886c128c15e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'If people get a good thing, they will think that it is not perfect, and then they will feel disappointed in the choice that they’ve made.', FALSE, 2, NULL, NULL),
  ('f566f713-3f28-5420-a06b-aec7a2dce83d'::uuid, '93fa7750-588f-552e-bfb5-d886c128c15e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'People often feel more satisfied with more options, as adding options to their lives can increase the expectations, so they often get good results from them.', FALSE, 3, NULL, NULL),
  ('a708e405-cea5-5712-b48a-352722c33a3c'::uuid, '942fb6d8-8ac2-5f49-a940-ce6e443970a2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'preference', TRUE, 0, NULL, 1),
