  ('6bc8e0f0-3748-5c1c-9747-bd88630f2e9b'::uuid, '95973022-9bb2-5307-a83d-f10fc382942b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'gear', FALSE, 7, NULL, NULL),
  ('c4af4992-267d-569c-ac37-cafa8f4161b9'::uuid, '959c691c-0af9-5818-8e55-81328f0cafbf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Over the years, I have had the opportunities to observe and understand the thought process behind the ads that have been flooding both the print and the TV.', FALSE, 0, NULL, NULL),
  ('093449aa-ff29-57de-a251-644ed73950a2'::uuid, '959c691c-0af9-5818-8e55-81328f0cafbf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Although there is a huge shift in the quality of ads that we come across on daily basis-thanks essentially to improvement in technology, I somehow can’t help but feel that the quality of communication of the message has become diluted.', FALSE, 1, NULL, NULL),
  ('7e08daa5-ecf6-5b9a-861a-ce6ec0edc020'::uuid, '959c691c-0af9-5818-8e55-81328f0cafbf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There is an increasing attempt by most companies to be seen as cool and funky.', FALSE, 2, NULL, NULL),
  ('0b5d9179-9232-5db1-af07-098e5d01bb6d'::uuid, '959c691c-0af9-5818-8e55-81328f0cafbf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Proportionally, the numbers of ads that lack in quality have gone up exponentially as well.', FALSE, 3, NULL, NULL),
  ('83b336fa-086a-5ff6-b655-ac8e505808bc'::uuid, '959c691c-0af9-5818-8e55-81328f0cafbf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Another reason could be the burgeoning number of companies, which means an exponential increase in the number of ads that are being made.', FALSE, 4, NULL, NULL),
  ('dfce2fdc-06e7-52d3-beba-4a3d9a841500'::uuid, '95bcd5ed-7d20-551f-893a-33767b0ae515'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'place', TRUE, 0, NULL, 2),
  ('cb36fdbf-9956-5aca-896b-af4ad2121b5f'::uuid, '95bcd5ed-7d20-551f-893a-33767b0ae515'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'beliefs', FALSE, 1, NULL, NULL),
