  ('853cf654-906a-5464-8bcb-effeb09840b8'::uuid, '95bcd5ed-7d20-551f-893a-33767b0ae515'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'end', FALSE, 6, NULL, NULL),
  ('7bb6d5d7-5062-59db-8f77-f0ec193352b5'::uuid, '95bdb582-790b-5752-8333-095e6d380227'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This process not only aids in the growth of fruits and vegetables but also is vital for the plants'' reproduction.', FALSE, 0, NULL, NULL),
  ('b6b38833-79e5-5818-9045-10b03e63292c'::uuid, '95bdb582-790b-5752-8333-095e6d380227'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Bees are crucial to the ecosystem because they pollinate plants, which is a process where pollen is transferred from one flower to another.', FALSE, 1, NULL, NULL),
  ('99d07b62-0995-52fe-8e12-f67655d6674b'::uuid, '95bdb582-790b-5752-8333-095e6d380227'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Unfortunately, bee populations are declining at an alarming rate due to pesticides, habitat loss, and climate change.', FALSE, 2, NULL, NULL),
  ('28f84e5a-039e-540c-98b2-36ce0d166703'::uuid, '95bdb582-790b-5752-8333-095e6d380227'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Protecting bee populations is therefore essential, not just for natural biodiversity but also for agricultural purposes.', FALSE, 3, NULL, NULL),
  ('c1125924-ec8d-5c3e-b1b3-843611d82cbf'::uuid, '95bdb582-790b-5752-8333-095e6d380227'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Due to their role in pollination, bees are directly responsible for the production of many seeds and fruits that serve as a food source for various animals.', FALSE, 4, NULL, NULL),
  ('f30b3443-d716-52cd-a0b3-35541d781857'::uuid, '95c112a7-f540-5468-9709-ec38b07c1d9f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'attend', FALSE, 0, NULL, NULL),
