  ('b0d47b31-b86a-5520-bd47-4f78904392cb'::uuid, '96a73a38-42d6-5f63-a750-faa65feabbe9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Because of their extreme condition, there is not as much biodiversity found in deserts.', FALSE, 0, NULL, NULL),
  ('178e1195-6ec4-500f-b41d-e2208b5a247d'::uuid, '96a73a38-42d6-5f63-a750-faa65feabbe9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Deserts are dry areas where rainfall is less than 50 centimeters (20 inches) per year.', FALSE, 1, NULL, NULL),
  ('ef31178c-6577-57c5-b42e-b0118980f307'::uuid, '96a73a38-42d6-5f63-a750-faa65feabbe9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Any vegetation and wildlife living in a desert must have special adaptations for surviving in a dry environment.', FALSE, 2, NULL, NULL),
  ('95822225-31d5-517e-bd3d-a2a31d6d9fde'::uuid, '96a73a38-42d6-5f63-a750-faa65feabbe9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They can be either very cold or hot, although most of them are found in subtropical areas.', FALSE, 3, NULL, NULL),
  ('174c6996-40b5-536d-ab83-4ae2d2a4bb54'::uuid, '96b9c6b5-474f-5df5-b2b7-bde991543ace'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They rank above the first lieutenant and directly below the major.', FALSE, 0, NULL, NULL),
  ('6d30d197-969b-5884-b806-74a2224d1e8c'::uuid, '96b9c6b5-474f-5df5-b2b7-bde991543ace'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The first lieutenant is responsible for the platoons in combat and serves their executive commander, which is often the captain.', FALSE, 1, NULL, NULL),
  ('fdeecee1-9fe8-58a8-b35b-98cd0c7d88f5'::uuid, '96b9c6b5-474f-5df5-b2b7-bde991543ace'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The majors handle their primary staff officers for the brigade, maintain the task force command and manage the personnel and operational missions.', FALSE, 2, NULL, NULL),
  ('54923301-b1cc-51ae-bcec-3a15f1971d9b'::uuid, '96b9c6b5-474f-5df5-b2b7-bde991543ace'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A captain is in the 21st rank in the U.S. Army.', FALSE, 3, NULL, NULL),
