  ('6c8a4087-0db6-522d-9a3b-87234098e321'::uuid, '971091b3-72fa-510e-994b-aa1d72c7c600'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Knowing the Highway Code is not the same as driving.', FALSE, 0, NULL, NULL),
  ('b7996952-00c8-5931-91a4-69f7400659dd'::uuid, '971091b3-72fa-510e-994b-aa1d72c7c600'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In language learning, there is a distinction between competence and performance. Competence is a state of the speaker''s mind. What does he or she know?', FALSE, 1, NULL, NULL),
  ('ca1e84c2-c3bc-56e0-8d92-10a84be30fca'::uuid, '971091b3-72fa-510e-994b-aa1d72c7c600'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'An analogy can be made to the Highway Code for driving. Drivers know the Code and have indeed been tested on it to obtain a driving license.', FALSE, 2, NULL, NULL),
  ('84798f83-e65b-5e2d-958a-daae509370b5'::uuid, '971091b3-72fa-510e-994b-aa1d72c7c600'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Separate from actual performance- what he or she does while producing or comprehending language. In other words, competence is put to use through performance.', FALSE, 3, NULL, NULL),
  ('92defb76-2c81-575e-a18d-ca15100c0254'::uuid, '971091b3-72fa-510e-994b-aa1d72c7c600'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In actual driving, however, the driver has to relate the Code to a continuous flow of changing circumstances, and may even break it from time to time.', FALSE, 4, NULL, NULL),
  ('4b4dba21-6c18-57b4-9863-057dcd971a5c'::uuid, '972916d3-5985-5e58-88bb-f73f7fc6db68'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'dream', TRUE, 0, 0, NULL),
