  ('4456d7b7-a97c-5b00-818a-2c0926c0b47b'::uuid, '9761d6be-c688-5f82-ba53-c63561f4f44b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'I invited one student from their school each time, made them feel comfortable, and then gave them a puzzle.', FALSE, 0, NULL, NULL),
  ('21973379-ef87-5ab3-a61c-83161de9d1ed'::uuid, '9761d6be-c688-5f82-ba53-c63561f4f44b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'One was very easy, while another was very difficult.', FALSE, 1, NULL, NULL),
  ('c4250bb0-ce65-5a73-a8d9-54606da62907'::uuid, '9761d6be-c688-5f82-ba53-c63561f4f44b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The students tried to solve the questions with confusion and frustration.', FALSE, 2, NULL, NULL),
