  ('b803b5dc-680a-52f5-bc2f-1e54b282899b'::uuid, '9761d6be-c688-5f82-ba53-c63561f4f44b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'When I was a young scholar, I did a research study that changed my perception of how students learn.', FALSE, 4, NULL, NULL),
