  ('c1d08aa0-2b96-52e0-a38d-310b89d35599'::uuid, '976f8c56-1c1d-5fcc-9876-d5469a2a5977'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The pencil, a common tool in education and art, has a rich history.', FALSE, 0, NULL, NULL),
  ('ddf36381-0a36-5c10-8942-af666f620150'::uuid, '976f8c56-1c1d-5fcc-9876-d5469a2a5977'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Its origins date back to the 16th century when graphite was first discovered in England.', FALSE, 1, NULL, NULL),
  ('600ba7ef-86a7-5ab4-8407-d61e414195ab'::uuid, '976f8c56-1c1d-5fcc-9876-d5469a2a5977'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As the tool evolved, wood casings were introduced, leading to the modern pencil design we recognize today.', FALSE, 2, NULL, NULL),
  ('9b34e766-057a-5638-be6c-0803d17fc000'::uuid, '976f8c56-1c1d-5fcc-9876-d5469a2a5977'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Initially, graphite sticks were wrapped in string or sheepskin for stability.', FALSE, 3, NULL, NULL),
  ('bf3bbdd3-6867-5018-85c9-d2afb22774f7'::uuid, '977666f2-97c2-55ef-afe1-31a8d5fa793a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Newnes railroad was closed in 1932 after 25 years of shipping oil shale.', FALSE, 0, NULL, NULL),
  ('802eafee-622a-5030-b53c-65498ac24d77'::uuid, '977666f2-97c2-55ef-afe1-31a8d5fa793a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The rails were pulled out of the 600-meter tunnel, which had been bored through the sandstone in the Wollemi National Park, and the tunnel was left to its own devices.', FALSE, 1, NULL, NULL),
  ('a206343d-814b-521d-9e69-1fdce2a1fd9e'::uuid, '977666f2-97c2-55ef-afe1-31a8d5fa793a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The glow worm is a catch-all name for the bioluminescent larvae of various species, in this case, the Arachnocampa richardsae, a type of fungus gnat.', FALSE, 2, NULL, NULL),
  ('1bbbe3ed-b251-59df-8440-7a5b7994a335'::uuid, '977666f2-97c2-55ef-afe1-31a8d5fa793a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Found in massive numbers in caves, the fungus gnat larvae cling to the rocky walls of the abandoned tunnel and hunt with long, glowing strings of sticky mucus.', FALSE, 3, NULL, NULL),
  ('ca4c5302-1c44-5ba5-98e1-4293d51bd490'::uuid, '977666f2-97c2-55ef-afe1-31a8d5fa793a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For Newnes, that meant becoming home to thousands and thousands of glow worms.', FALSE, 4, NULL, NULL),
  ('a21b7161-2f75-5b60-bf26-9125c0973301'::uuid, '9781f680-63cc-518e-a9a4-792d47badc2c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'At the same time, the proportion of the population who were divorced increased, from 5% in 1986 to 7% in 2001, while the proportion of the population who were widowed remained at around 6%.', FALSE, 0, NULL, NULL),
  ('cd66d8d2-c5ff-5b1b-bee6-969c544afb46'::uuid, '9781f680-63cc-518e-a9a4-792d47badc2c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The decline in marriage rates and increase in divorce rates has led to a decrease in the proportion of the population that is formally married.', FALSE, 1, NULL, NULL),
  ('59c53310-315b-577e-9fd5-e3b0f21fac0f'::uuid, '9781f680-63cc-518e-a9a4-792d47badc2c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Conversely the proportion of the population aged 15 years and over who were never married increased from 29% in 1986 to 32% in 2001.', FALSE, 2, NULL, NULL),
  ('276c235b-5a26-57d9-a0ac-8b337791ffbf'::uuid, '9781f680-63cc-518e-a9a4-792d47badc2c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In 1986, 60% of the population aged 15 years and over were married; by 2001 this proportion had decreased to 55%.', FALSE, 3, NULL, NULL),
  ('77f91036-c54d-5b19-bfcc-847f8c18eecc'::uuid, '97834a3a-0685-5a70-a23a-782eac135172'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'resurrecting', FALSE, 0, 0, NULL),
