  ('09c65edb-8093-5ebd-9a50-8f9015fac708'::uuid, '989d6c1e-09cc-5937-96af-464a8b42977d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A coral the size of a carousel is the widest known in the Great Barrier Reef.', FALSE, 0, NULL, NULL),
  ('4908d58e-4105-54db-9594-29a908bd2e34'::uuid, '989d6c1e-09cc-5937-96af-464a8b42977d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Found in Northeast Australia, this reef-building measures 10.4 meters in diameter — earning it the nickname Muga dhamb.', FALSE, 1, NULL, NULL),
  ('335ac1f9-b46e-514c-94e8-541adc7bc39b'::uuid, '989d6c1e-09cc-5937-96af-464a8b42977d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It predates European colonization of Australia and has survived 99 coral bleaching events.', FALSE, 2, NULL, NULL),
  ('e365f0cb-61a7-573f-b9fa-b04165ee2b1f'::uuid, '989d6c1e-09cc-5937-96af-464a8b42977d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In addition to its record-setting width, Muga dhambi stands a little over 5 meters tall, making it the sixth tallest coral in the Great Barrier Reef.', FALSE, 3, NULL, NULL),
  ('28e15dad-8416-532e-86c2-c2a253885fe0'::uuid, '989d6c1e-09cc-5937-96af-464a8b42977d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Based on Muga dhambi’s height and estimated growth rate, scientists calculate that it is about 421 to 438 years old.', FALSE, 4, NULL, NULL),
  ('acecb129-1689-55b2-a0d7-b70ebf2c0e87'::uuid, '98a304f1-b8ac-50f3-893c-3ba6aa3b9f89'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'divided', TRUE, 0, NULL, 0),
