  ('85b7b476-3363-56c1-9e73-38ee87684e05'::uuid, '98b105a8-d828-5399-a956-e7d96dab1707'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It is also a recurrent theme in the press, from the highbrow pages of Prospect to the populism of the Daily Mail.', FALSE, 0, NULL, NULL),
  ('772edf6e-ff50-50f1-86f5-a30ce2e8d654'::uuid, '98b105a8-d828-5399-a956-e7d96dab1707'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In the early years of the twenty-first century the impact of immigrants on the welfare state has become a staple of discussion among policy makers and politicians.', FALSE, 1, NULL, NULL),
  ('308b84ff-2be4-5449-b909-717e65f290fc'::uuid, '98b105a8-d828-5399-a956-e7d96dab1707'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Inevitably, these discussions focus on present-day dilemmas.', FALSE, 2, NULL, NULL),
  ('5f9bb230-fe53-5e2a-a2e1-1f04068111b0'::uuid, '98b105a8-d828-5399-a956-e7d96dab1707'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But the issues themselves are not new and have historical roots that go much deeper than have been acknowledged.', FALSE, 3, NULL, NULL),
