  ('db0e6b90-15be-5b72-8519-09c9823e11ed'::uuid, '9910d7bb-b220-5fd7-8c33-7c8c252a5f45'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'On May 12th, 1804 these conquests received a new name: the Empire, ruled by a hereditary Bonaparte Emperor.', FALSE, 0, NULL, NULL),
  ('1978a8fc-1a45-5628-a6a3-c624f33269cd'::uuid, '9910d7bb-b220-5fd7-8c33-7c8c252a5f45'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The first emperor was Napoleon, and at times he ruled vast swathes of the European continent.', FALSE, 1, NULL, NULL),
  ('d5ac5815-8622-59ef-aff3-54491d7afc15'::uuid, '9910d7bb-b220-5fd7-8c33-7c8c252a5f45'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The borders of France and the states ruled by France grew during the wars of the French Revolution and the Napoleonic Wars.', FALSE, 2, NULL, NULL),
  ('466e8031-aa57-540b-bbb2-f4404313da49'::uuid, '9910d7bb-b220-5fd7-8c33-7c8c252a5f45'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'By 1810 it was easier to list the regions he didn’t dominate: Portugal, Sicily, Sardinian, Montenegro, and the British, Russian and Ottoman Empires.', FALSE, 3, NULL, NULL),
  ('fb2b5c57-216b-5d11-9474-90b8c44aee51'::uuid, '991cac43-afe3-56a6-9bfe-47e41020bc6e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Career planning is a comprehensive venture which encompasses defining your goals and developing a feasible plan to achieve them.', FALSE, 0, NULL, NULL),
  ('4eaf97d0-7144-586d-934d-0ac03c3ad739'::uuid, '991cac43-afe3-56a6-9bfe-47e41020bc6e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Additionally, lots of university programs are structured in a way that will equip you with the necessary skills to find multiple employment options in the future.', FALSE, 1, NULL, NULL),
  ('fb4c2693-e2bb-58e3-aedc-1359e1cd2298'::uuid, '991cac43-afe3-56a6-9bfe-47e41020bc6e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Your lecturers might mention possible career paths, and there may be obligatory internships that can guide you towards your future job.', FALSE, 2, NULL, NULL),
  ('d246be59-e726-5ec1-b201-8f2af8bec73d'::uuid, '991cac43-afe3-56a6-9bfe-47e41020bc6e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The great news about defining your career goals is that you will hear quite a few ideas and stories during your studies.', FALSE, 3, NULL, NULL),
