  ('524019a3-6ad0-5499-80bd-987a835dbe2c'::uuid, '9a1f1a83-8b7e-5f05-83d0-f499bceefea9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, the environmental impact of air travel has become a growing concern.', FALSE, 0, NULL, NULL),
  ('bb1d7a3e-0199-5fb7-a3c1-50969ae3fc4c'::uuid, '9a1f1a83-8b7e-5f05-83d0-f499bceefea9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Airline travel is a crucial aspect of the tourism industry, connecting destinations across the globe.', FALSE, 1, NULL, NULL),
  ('ef47efa5-ad95-533c-a276-c2fd7be0bbf3'::uuid, '9a1f1a83-8b7e-5f05-83d0-f499bceefea9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This is achieved because of the evolution of commercial aviation, which has made long-distance travel more accessible.', FALSE, 2, NULL, NULL),
  ('ed148733-0b7f-555f-9111-547e7ee36fda'::uuid, '9a1f1a83-8b7e-5f05-83d0-f499bceefea9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Consequently, there is increasing pressure on the airline industry to adopt more sustainable practices.', FALSE, 3, NULL, NULL),
  ('a9e85647-559f-5147-a54c-969da583ab00'::uuid, '9a6d245d-ec98-50a4-871c-16652797e156'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Integrated pest management strategies, including biological control and minimal pesticide use, are often employed.', FALSE, 0, NULL, NULL),
  ('2101b62f-ed81-5c08-b69b-d475d17d4309'::uuid, '9a6d245d-ec98-50a4-871c-16652797e156'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This is because pests and diseases can significantly reduce yield and fruit quality.', FALSE, 1, NULL, NULL),
  ('1ba7a1fb-1199-5735-8f9f-371961ec909c'::uuid, '9a6d245d-ec98-50a4-871c-16652797e156'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Pest and disease control is an ongoing challenge in fruit orchards.', FALSE, 2, NULL, NULL),
  ('676639af-4385-5920-976c-fc5fd22734d7'::uuid, '9a6d245d-ec98-50a4-871c-16652797e156'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As a result, these strategies help in maintaining a healthy orchard and ensuring high-quality fruit production.', FALSE, 3, NULL, NULL),
