  ('f81a36ab-d648-504a-9b09-2f60bb02d149'::uuid, '9c05b4a4-77ad-5aab-a754-3b43525b7839'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In this play, a long lasting dispute between the Montague and Capulet families from the city of Verona causes the death of Romeo and of Juliet.', FALSE, 1, NULL, NULL),
  ('07d807d2-61b8-5ce9-9657-d27b2dee3338'::uuid, '9c05b4a4-77ad-5aab-a754-3b43525b7839'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The first half of the play, with jokes and love poetry is more like a comedy: the two teenagers rush impetuously into love.', FALSE, 2, NULL, NULL),
  ('1e3358d5-b327-5836-9e51-cd79036dac81'::uuid, '9c05b4a4-77ad-5aab-a754-3b43525b7839'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But conflict, revenge and secret plots create an intense pressure on them and lead the lovers to finally commit suicide in despair.', FALSE, 3, NULL, NULL),
  ('9817090b-ea24-5980-80ef-6601f06a989d'::uuid, '9c07b214-2495-50b0-96b4-dff629e78b99'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In terms of ''green superpower'', it means having strong capabilities in green energy and sustainable development.', FALSE, 0, NULL, NULL),
