  ('8f9850ef-ad1c-53e1-8da3-0fc3210e2f13'::uuid, '9c25c0bd-198b-577a-aa67-d513cc3c0071'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For example, dendrochronology (literally ''tree time'') dates wooden artefacts by matching their ring patterns to known records, which, in some areas of the world, span several thousand years.', FALSE, 0, NULL, NULL),
  ('758c3f54-9f90-504f-a388-aa0b287afe6f'::uuid, '9c25c0bd-198b-577a-aa67-d513cc3c0071'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The series of strata in an archaeological dig enables an excavator to date recovered objects relatively, if not absolutely.', FALSE, 1, NULL, NULL),
  ('cd59b787-f8e0-5477-9641-3675d2ec8781'::uuid, '9c25c0bd-198b-577a-aa67-d513cc3c0071'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, when archaeologists want to know the absolute date of a site, they can often go beyond simple stratigraphy.', FALSE, 2, NULL, NULL),
  ('804ffc3e-4272-54a4-8f0d-53950295d3cd'::uuid, '9c25c0bd-198b-577a-aa67-d513cc3c0071'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Historical records, coins, and other date-bearing objects can help — if they exist. But even prehistoric sites contain records written in nature''s hand.', FALSE, 3, NULL, NULL),
  ('a6d6ab16-f1fb-5b15-954a-ee09ed924523'::uuid, '9c2fcd9f-69d9-555d-a94d-7115bf9cbf15'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'grew', TRUE, 0, NULL, 0),
  ('82e64ef9-9cb3-5d84-916e-5c0525c2cb6b'::uuid, '9c2fcd9f-69d9-555d-a94d-7115bf9cbf15'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'increase', FALSE, 1, NULL, NULL),
