  ('2da7d72f-deaf-54df-8c42-de7258d1ca32'::uuid, '9c2fcd9f-69d9-555d-a94d-7115bf9cbf15'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'vague', FALSE, 6, NULL, NULL),
  ('7ac32d21-2cef-545e-b907-eecde983153f'::uuid, '9c39161a-0b9d-52c5-8ba9-f25b1535f808'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As the semester progressed, the group study participants consistently scored higher on tests.', FALSE, 0, NULL, NULL),
  ('6e3a1864-ee2b-547d-a6f3-211bba0a8984'::uuid, '9c39161a-0b9d-52c5-8ba9-f25b1535f808'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'At first, both groups showed similar levels of performance.', FALSE, 1, NULL, NULL),
  ('4d3dbf2d-f808-57bf-8105-c312360259a3'::uuid, '9c39161a-0b9d-52c5-8ba9-f25b1535f808'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To determine the impact of group study versus solitary study on academic performance, students were assigned to study in groups or alone.', FALSE, 2, NULL, NULL),
  ('f2e0e4c1-335e-5597-8b73-f6c7b8f2c42d'::uuid, '9c39161a-0b9d-52c5-8ba9-f25b1535f808'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This trend suggested that group study was more beneficial for academic achievement in this context.', FALSE, 3, NULL, NULL),
  ('ddb4618c-1b01-5264-9e69-c1ab54f04367'::uuid, '9c3a0863-8436-5362-ba28-964467f102dc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Houses in which ordinary Egyptians lived have not been preserved, and when most people died they were buried in simple graves with few funerary goods.', FALSE, 0, NULL, NULL),
  ('1e72be07-6a63-59f4-9f3b-4c28bf67fdf7'::uuid, '9c3a0863-8436-5362-ba28-964467f102dc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Most of our traditional sources of information about the Old Kingdom are those concerned with death and the rituals surrounding death: these include pyramids, tombs and graves, but also statues, reliefs and paintings.', FALSE, 1, NULL, NULL),
  ('01b89c31-c836-55fd-9ff2-278e117b4e0b'::uuid, '9c3a0863-8436-5362-ba28-964467f102dc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Even papyri come mainly from pyramid temples.', FALSE, 2, NULL, NULL),
  ('c2de82ad-e1c3-525c-bf14-91de2b784bf7'::uuid, '9c3a0863-8436-5362-ba28-964467f102dc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But this does not mean that death was the Egyptians'' only preoccupation.', FALSE, 3, NULL, NULL),
  ('06624e23-1eb7-5f77-ae45-b478679a34e0'::uuid, '9c3a0863-8436-5362-ba28-964467f102dc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'We know infinitely more about the wealthy people of Egypt than we do about the ordinary people, as almost all the monuments were made for the rich and influential.', FALSE, 4, NULL, NULL),
  ('d82c3cbc-2676-51f5-aab4-7fcf03495703'::uuid, '9c416e7a-c378-57f4-aeb0-d9fadcc5ba57'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Penicillin''s success led to the research and creation of more antibiotics, revolutionizing the treatment of various infectious diseases.', FALSE, 0, NULL, NULL),
  ('81a8a909-9a52-5cbb-9d90-805cbf8cfac7'::uuid, '9c416e7a-c378-57f4-aeb0-d9fadcc5ba57'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The discovery of penicillin by Alexander Fleming in 1928 marked a turning point in medical history.', FALSE, 1, NULL, NULL),
  ('d9f51eed-e0bb-5589-b482-ac0013cbd512'::uuid, '9c416e7a-c378-57f4-aeb0-d9fadcc5ba57'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Consequently, the widespread use of antibiotics has significantly reduced mortality rates and changed the landscape of healthcare.', FALSE, 2, NULL, NULL),
  ('271539c3-297f-5851-bd40-abcb260bc730'::uuid, '9c416e7a-c378-57f4-aeb0-d9fadcc5ba57'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This accidental discovery occurred when Fleming noticed that a mold, Penicillium notatum, had contaminated his Petri dishes and killed the surrounding bacteria.', FALSE, 3, NULL, NULL),
  ('ac17355f-c7f9-5497-8651-fb8423383e33'::uuid, '9c416e7a-c378-57f4-aeb0-d9fadcc5ba57'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The development and mass production of penicillin during World War II saved countless lives by effectively treating bacterial infections.', FALSE, 4, NULL, NULL),
  ('faca20dd-a07b-5b2a-bfa4-9597424f8f27'::uuid, '9c7b2490-b087-5689-b958-b6ed9977cf92'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'how attractive the building is to look at', TRUE, 0, NULL, NULL),
