  ('b2420298-1898-56a5-97fd-c562753faf21'::uuid, '9ca524c7-76ed-59ce-8103-6f2979f5369c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'And if this something else is rightly chosen, if it is really attended by the illumination of another field of interest, gradually, and often quite swiftly, the old undue grip relaxes and process of recuperation and repair begins.', FALSE, 0, NULL, NULL),
  ('b6f36b70-8cc5-513c-9859-92945ee78e7c'::uuid, '9ca524c7-76ed-59ce-8103-6f2979f5369c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A gifted American psychologist has said, ''Worry is a spasm of the emotion; the mind catches hold of something and will not let it go.''', FALSE, 1, NULL, NULL),
