  ('317e1bc3-fd4c-5722-ad1a-ceb950af47e8'::uuid, '9cf9e58f-6453-5c81-aab2-68187bac3545'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But in 1912, discouraged by American magazines’ constant rejection of his work, he took his family to England, where he found more professional success.', FALSE, 0, NULL, NULL),
  ('5c81abb9-a52b-57d9-8632-f5f07d6ae5f7'::uuid, '9cf9e58f-6453-5c81-aab2-68187bac3545'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To celebrate his first publication, Frost had a book of six poems privately printed; two copies of Twilight were made—one for himself and one for his fiancée.', FALSE, 1, NULL, NULL),
