  ('181d471c-3fb6-5d23-ad65-03e3e62aebdc'::uuid, '9e8a2ccf-86c7-583c-a3f6-8715a5cf3462'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Many people face serious financial crisis when they are only 20-30 years old.', FALSE, 0, NULL, NULL),
  ('83a2eca2-aaff-54aa-8d0b-b539083238d8'::uuid, '9e8a2ccf-86c7-583c-a3f6-8715a5cf3462'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This is because they do not really pay attention to their daily spending, and has poured their spending on buying.', FALSE, 1, NULL, NULL),
  ('83323166-cb98-58f1-bba3-40cb2476e9b3'::uuid, '9e8a2ccf-86c7-583c-a3f6-8715a5cf3462'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Although they can have student loans, people should consider creating a budget to track their expenses, prioritize essential spending, and avoid unnecessary debt.', FALSE, 2, NULL, NULL),
  ('4c193e9d-4915-5f04-8ac3-420b87831a21'::uuid, '9e8a2ccf-86c7-583c-a3f6-8715a5cf3462'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This will lead to them paying piling credit card loan and monthly payments.', FALSE, 3, NULL, NULL),
  ('bb12005b-4ea3-5927-8c79-cbaa60bdcdaa'::uuid, '9e8a2ccf-86c7-583c-a3f6-8715a5cf3462'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Additionally, building an emergency fund and seeking financial advice can help manage and mitigate financial crises.', FALSE, 4, NULL, NULL),
  ('5da47f68-596a-5b50-80e4-db35d60ef031'::uuid, '9e8d7a22-6417-53f9-9f35-c7504574540a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The St. Johns River is the longest river in Florida, running up the eastern coast of the state from St. Johns Marsh to the Atlantic Ocean.', FALSE, 0, NULL, NULL),
  ('9a8725ad-d668-5202-ad50-ce075d481ad7'::uuid, '9e8d7a22-6417-53f9-9f35-c7504574540a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The earliest people to live along the river were likely the hunter-gatherers known as Paleo-Indians, who inhabited the Florida Peninsula over 10,000 years ago.', FALSE, 1, NULL, NULL),
  ('65dce6e6-d7a5-5fd7-84de-c5cdff540e87'::uuid, '9e8d7a22-6417-53f9-9f35-c7504574540a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The mission was named San Juan del Puerto (St. John of the Harbor), giving the river its name.', FALSE, 2, NULL, NULL),
  ('f1296713-4020-56fa-9cf8-91fe6af9ac00'::uuid, '9e8d7a22-6417-53f9-9f35-c7504574540a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It was Spanish missionaries who later established a mission at the mouth of the river.', FALSE, 3, NULL, NULL),
  ('e5b84014-d7ae-5519-a68f-80907e87d323'::uuid, '9ea2bcd2-e86a-54b8-a09d-46e3455120c2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'hijack', TRUE, 0, 0, NULL),
