  ('ed5257b6-007a-5ef4-af99-27843a3339f2'::uuid, '9f47d6ab-3385-59ff-bb8f-39892d254a79'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Because, in most environments, vision is much more effective.', FALSE, 0, NULL, NULL),
  ('bd653b94-541e-5825-b45b-8d48d730e6b6'::uuid, '9f47d6ab-3385-59ff-bb8f-39892d254a79'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Echolocation is adaptive only in an ecological niche where vision is impossible or badly impaired—for instance, when dwelling in caves and hunting at night, as bats do.', FALSE, 1, NULL, NULL),
  ('746dd97d-4654-5301-9602-4992d0590ab0'::uuid, '9f47d6ab-3385-59ff-bb8f-39892d254a79'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Vision and echolocation have many features in common.', FALSE, 2, NULL, NULL),
  ('023be821-71f9-5bd9-9cc0-aae601f0bdb9'::uuid, '9f47d6ab-3385-59ff-bb8f-39892d254a79'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'One narrow range of radiation — light in the case of vision, ultrasounds in the case of echolocation — provides information relevant to a wide variety of cognitive and practical goals.', FALSE, 3, NULL, NULL),
  ('85b4f786-6259-5b5d-b864-75dacb7772cb'::uuid, '9f47d6ab-3385-59ff-bb8f-39892d254a79'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Why, then, is vision so common and echolocation so rare?', FALSE, 4, NULL, NULL),
