  ('7f0c6c60-b614-5d49-868b-d66e97122c14'::uuid, '9f77b46d-eb9f-5a4f-88bd-8370e852ffe8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Between the ocean and the mountain, there''s the unfinished highway.', FALSE, 1, NULL, NULL),
