  ('9fe2cdd6-8098-5330-99f5-520211dd23ac'::uuid, '9f77b46d-eb9f-5a4f-88bd-8370e852ffe8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A glossy brochure of Cape Town film locations proclaims the cut-off highway “truly special”, with “great city views”.', FALSE, 3, NULL, NULL),
