  ('520529c0-880d-5c2c-a562-228abdd83224'::uuid, '9f97a83b-52c0-59b8-9ca3-73466f2f3b71'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Physical geography, for example, is important in understanding why a city is located in a specific area as environmental conditions play a large role in whether or not a city develops.', FALSE, 1, NULL, NULL),
  ('55ee8fd6-1919-54e8-bb63-aace999880e5'::uuid, '9f97a83b-52c0-59b8-9ca3-73466f2f3b71'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'An urban geographer''s main role is to emphasize location and space and study the spatial processes that create patterns observed in urban areas.', FALSE, 2, NULL, NULL),
  ('b17b5828-cd3a-5e16-8c46-ebaf78e3c858'::uuid, '9f97a83b-52c0-59b8-9ca3-73466f2f3b71'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In order to fully understand each of these aspects of a city, urban geography represents a combination of many other fields within geography.', FALSE, 3, NULL, NULL),
