  ('d5751b97-6337-589f-8965-0eed9cf83b05'::uuid, 'a1e26d66-87f2-542d-998c-e8fcaa1e2113'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It is hard to find a place to sit down and study.', FALSE, 1, NULL, NULL);
