  ('20275ff9-67ee-58b7-871d-9fa0994c7415'::uuid, 'a26c91ec-cc21-5b4d-a20d-a3d0778ecd3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Scientists at Queen''s University in Belfast now think that crustaceans may be more sensitive to pain than previously thought.', FALSE, 0, NULL, NULL),
  ('61682e06-a20c-5f1a-8fe0-19e5737d928b'::uuid, 'a26c91ec-cc21-5b4d-a20d-a3d0778ecd3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'And they found that crabs that experienced an electric shock when they hid under a safe, dark rock would eventually learn to avoid the hiding place.', FALSE, 1, NULL, NULL),
