  ('1e669643-8bbf-57b8-8a1c-e58e011d5e45'::uuid, 'a2f850a7-72e4-5f0b-b2bd-f345c0c84ee1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'By 1677, Louis XIV had begun to lay the foundation for a more permanent move.', FALSE, 1, NULL, NULL),
