  ('923c4e30-e257-5671-b902-f5025317a7af'::uuid, 'a3a5f241-fb34-5db0-bdaf-aa4aeec9843a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Children as young as 2 can detect when there is a shift in a family''s dynamic, according to Dr. Shannon Curry, clinical psychologist in California.', FALSE, 0, NULL, NULL),
  ('572f9420-93b4-59c0-99ec-3a43b4e60f42'::uuid, 'a3a5f241-fb34-5db0-bdaf-aa4aeec9843a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'"A child’s ability to cope with the death of a loved one depends significantly on how clearly their parent presents the news," Curry said.', FALSE, 1, NULL, NULL),
  ('84f27bcc-e1ff-57fb-a3c5-82bbb389000d'::uuid, 'a3a5f241-fb34-5db0-bdaf-aa4aeec9843a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'She continued, ‘‘Allowing your child to see the reality of your sadness can be an important teaching opportunity about emotional awareness.’’', FALSE, 2, NULL, NULL),
  ('518e2221-f02b-5849-acf2-e46d26777931'::uuid, 'a3a5f241-fb34-5db0-bdaf-aa4aeec9843a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The loss of a grandparent can be a very traumatic time for every family, but especially for kids who might not fully understand what is happening around them.', FALSE, 3, NULL, NULL),
  ('bd2ecc9b-56f7-5403-99b2-a7e60c5061d4'::uuid, 'a3b2f22f-18b5-5f5f-a43f-4e51ac6e6131'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In 1955, Disneyland had just opened in Anaheim, California, when a ten-year-old boy walked in and asked for a job.', FALSE, 0, NULL, NULL),
  ('212d0115-e9bf-5998-bf73-0e49da0db377'::uuid, 'a3b2f22f-18b5-5f5f-a43f-4e51ac6e6131'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Then he discovered that what he loved was not performing magic but performing in general.', FALSE, 1, NULL, NULL),
  ('67ab6c81-02de-58a6-a9ad-d6342f5b3622'::uuid, 'a3b2f22f-18b5-5f5f-a43f-4e51ac6e6131'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Labor laws were loose back then and the boy managed to land a position selling guidebooks for $0.50 apiece.', FALSE, 2, NULL, NULL),
  ('faba4b89-5199-52a6-b7db-d432aeb1d437'::uuid, 'a3b2f22f-18b5-5f5f-a43f-4e51ac6e6131'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'He experimented with jokes and tried out simple routines on visitors.', FALSE, 3, NULL, NULL),
