  ('05efe237-3185-5659-9ad7-bcb753aeee26'::uuid, 'a41dd29a-fbf0-5593-a0a2-c8c9fe56d241'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They are so habituated to humans that they will climb on and off weighing scales when a scientist wants to weigh an animal.', FALSE, 0, NULL, NULL),
  ('a3b86684-317b-5053-b717-02910ed5117f'::uuid, 'a41dd29a-fbf0-5593-a0a2-c8c9fe56d241'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Kalahari Desert meerkats, Suricata Suricatta, have been followed over generations.', FALSE, 1, NULL, NULL),
  ('cfdb0314-51ad-524e-b0e9-497b45d13190'::uuid, 'a41dd29a-fbf0-5593-a0a2-c8c9fe56d241'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Meerkats, a small group-living mongooses in southern Africa, have been so extensively studied and filmed that we can follow individuals through their lives like characters in an animal soap opera.', FALSE, 2, NULL, NULL),
