  ('7f61153d-72b1-58a1-be95-30db71256ee2'::uuid, 'a4d61427-f837-5337-8b3d-95c8139153c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'posture', FALSE, 7, NULL, NULL),
  ('1c63d661-e234-5ae3-ad06-2213632ee121'::uuid, 'a53bb081-3dbc-52c6-80fe-c1c6ea0bd91e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Heart and blood vessel diseases are not only preventable but also reversible. For individuals, simply changing their lifestyle and diet can make a difference. Such low-cost interventions can indeed help stop the cancer.', TRUE, 0, NULL, NULL),
  ('df44773b-bb62-5699-80dc-5e7bb9730b5f'::uuid, 'a53bb081-3dbc-52c6-80fe-c1c6ea0bd91e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Diabetes has increased 70 percent in the past ten years, which is the most concerning issue nowadays. If this trend continues, our kids will live a shorter life span than we do. What is sad is that we cannot do anything to stop it.', FALSE, 1, NULL, NULL),
  ('c77de2be-a25f-5381-8427-6b023f195045'::uuid, 'a53bb081-3dbc-52c6-80fe-c1c6ea0bd91e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Heart and blood vessel diseases endanger people’s health globally. Scientists found that the diseases can be preventable by changes in lifestyle, but they can’t be reversible. So it is very important for people to detect those diseases as soon as possible.', FALSE, 2, NULL, NULL),
  ('de07163e-50ef-5079-a4aa-5f4b54cae022'::uuid, 'a53bb081-3dbc-52c6-80fe-c1c6ea0bd91e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Many people pass away because of chronic diseases, such as heart and blood vessel disease. However, researchers have found that using the most advanced measures can prevent and reverse them. These measures tend to be costly, so only the rich can afford to get sufficient medical care.', FALSE, 3, NULL, NULL),
  ('9a282f70-f03c-5861-b303-70dbe8ccecaf'::uuid, 'a55b7bbf-f30c-58d1-b96e-9e6dba6d4bf5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'depth', TRUE, 0, NULL, 3),
