  ('dabf3a9c-34f4-5bc2-bdbe-49e5057feb5b'::uuid, 'a5849773-c447-5db7-84b9-76ffeee3b460'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There can be problems contacting organisers, difficulties in negotiating dates and times, problems finding suitable accommodation and general procrastination on the pan of people who may have conflicting priorities.', FALSE, 0, NULL, NULL),
  ('a198f786-d879-547d-84cc-3fb13d6707ef'::uuid, 'a5849773-c447-5db7-84b9-76ffeee3b460'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In addition, there may be a need to provide group members with childcare facilities, which can add to the difficulty of finding suitable accommodation, equipment and staffing.', FALSE, 1, NULL, NULL),
  ('6bacf693-6c39-5676-b829-d5c2fcb3e406'::uuid, 'a5849773-c447-5db7-84b9-76ffeee3b460'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It is easy to assume that a programme of financial literacy can be set up quite quickly but there are numerous potential pitfalls which hold back a clear start time.', FALSE, 2, NULL, NULL),
