  ('65215a6e-2381-59db-b0e7-9db00e90769c'::uuid, 'a6167138-d5d8-58f3-80ab-f5f5a530fb6f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It''s time for us all to take action and create a cleaner, greener future.', FALSE, 0, NULL, NULL),
  ('26d649fa-eb3f-56f3-898c-03365e29a1b4'::uuid, 'a6167138-d5d8-58f3-80ab-f5f5a530fb6f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A healthy and stable climate is vital to sustaining our life on earth.', FALSE, 1, NULL, NULL),
  ('71f4942e-6066-5b06-ad21-1d10b04d6437'::uuid, 'a6167138-d5d8-58f3-80ab-f5f5a530fb6f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'After all, humans rely on the natural environment to provide everything from food and water to the air we breathe.', FALSE, 2, NULL, NULL),
  ('f237140b-dbbd-5444-ae91-1695081d0cbc'::uuid, 'a6167138-d5d8-58f3-80ab-f5f5a530fb6f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But our climate is changing fast and this poses a serious threat to the future of our life on planet Earth.', FALSE, 3, NULL, NULL),
