  ('235052df-349c-54a7-8ae8-e36c1d9d2692'::uuid, 'a65613e3-7694-5b50-be21-cd47402f6073'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The ''Festival in The Desert'' is a celebration of the musical heritage of the Touareg, a fiercely independent nomadic people.', FALSE, 0, NULL, NULL),
  ('35444c6b-53bf-5441-af98-021a295e88f1'::uuid, 'a65613e3-7694-5b50-be21-cd47402f6073'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Reaching it tests endurance, with miles of impermanent sand tracks to negotiate.', FALSE, 1, NULL, NULL),
  ('2df45001-8e0d-5a12-bdd2-71bc684e1baf'::uuid, 'a65613e3-7694-5b50-be21-cd47402f6073'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It is held annually near Essakane, an oasis some 40 miles north-west of Timbuktu, the ancient city on the Niger River.', FALSE, 2, NULL, NULL),
  ('d5ce24b1-4301-5e29-9535-9a15b1d335df'::uuid, 'a65613e3-7694-5b50-be21-cd47402f6073'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The reward of navigating this rough terrain comes in the form of a three-day feast of music and dance.', FALSE, 3, NULL, NULL),
  ('09bff15b-e926-541c-bdb9-9a08aabaee32'::uuid, 'a685a80e-e9ea-52e8-8962-e40358b67f17'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'laboratory', TRUE, 0, NULL, 4),
