  ('536daaa3-5b41-54a1-8abe-01f706ac1e30'::uuid, 'a727a01b-0b6b-50c8-a63f-5863008a8ec8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Congress wanted a strong central government. At that time, Washington D.C., between Virginia and North Carolina, had been a focal point of the American Revolution. The Continental Congress had met there before the war.', FALSE, 0, NULL, NULL),
  ('0a374d7a-ffdf-56b6-9972-a1d93fe10752'::uuid, 'a727a01b-0b6b-50c8-a63f-5863008a8ec8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Philadelphia was an important early American city and was the logical choice as the new country''s capital because of a roughly central location in the U. S. However, government of Pennsylvania failed to protect the federal government.', FALSE, 1, NULL, NULL),
  ('dcb5c601-8e48-5015-96ce-14e5924fbab2'::uuid, 'a727a01b-0b6b-50c8-a63f-5863008a8ec8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There was an early problem between congress and the American army. Therefore, the continental congress never met in Philadelphia and it ruled out Philadelphia as the capital city in United States.', FALSE, 2, NULL, NULL),
  ('9dc50376-986a-5630-bb5f-4e8a9dc67f7c'::uuid, 'a727a01b-0b6b-50c8-a63f-5863008a8ec8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'How Washington D.C. became the capital of United States is an intriguing story. Since in 1783 some soldiers interrupted a meeting of Congress in Philadelphia,it decided to create a completely new and independent area as the capital city.', TRUE, 3, NULL, NULL),
  ('8646a133-de73-5550-abae-f47482b098c2'::uuid, 'a7348a72-25cf-58e9-84ed-2d4da0f8d856'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A super-Earth is a type of planet that is about twice the size of Earth and up to 10 times its mass.', FALSE, 0, NULL, NULL),
  ('cc404ab6-3a91-5f93-b01b-0e2f08bdf280'::uuid, 'a7348a72-25cf-58e9-84ed-2d4da0f8d856'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Astronomers have discovered super-Earths used to orbit about 30% of sun-like stars in our galaxy.', FALSE, 1, NULL, NULL),
  ('581dde4d-cb3a-5044-a0ed-4e36a6e8b04b'::uuid, 'a7348a72-25cf-58e9-84ed-2d4da0f8d856'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Those rings of dust may have prevented Earth from growing into a "super-Earth".', FALSE, 2, NULL, NULL),
  ('698fa7bf-335d-5555-b472-3f3f9497f7f4'::uuid, 'a7348a72-25cf-58e9-84ed-2d4da0f8d856'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Before Earth and the other planets in our solar system existed, the sun may have been surrounded by giant rings of dust similar to Saturn''s.', FALSE, 3, NULL, NULL),
  ('fbbad354-78f3-5efb-92cb-6c055fefc228'::uuid, 'a7348a72-25cf-58e9-84ed-2d4da0f8d856'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Now they are only orbiting 5% of those sun-like stars, because of a lot of planets that have invaded into the galaxy.', FALSE, 4, NULL, NULL),
  ('59562eae-e2f5-5310-ab99-463462924dc9'::uuid, 'a7616c68-eb94-5a20-b68c-36ae88934d69'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'establish', TRUE, 0, NULL, 1),
