  ('0190d5fd-cbe8-5731-a836-7c2c6b15d884'::uuid, 'a7a0ed14-5c79-5c06-9e61-8c24dd3be415'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Since this initial formulation, the term has been further developed and is now considered to encompass all the ecosystems of the Earth.', FALSE, 0, NULL, NULL),
  ('253feffa-3a4c-5af5-8849-9eb659d3d380'::uuid, 'a7a0ed14-5c79-5c06-9e61-8c24dd3be415'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In 1875, the geologist Eduard Suess used the term biosphere to describe the location where all living things dwell.', FALSE, 1, NULL, NULL),
  ('6473a89d-064f-5dfd-ac23-45b0ff28c46b'::uuid, 'a7a0ed14-5c79-5c06-9e61-8c24dd3be415'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The biosphere is thought to have developed about 3.5 billion years ago when the first living organisms began to appear.', FALSE, 2, NULL, NULL),
  ('45b5ab48-c121-5dec-a37a-4a39b36eac11'::uuid, 'a7a0ed14-5c79-5c06-9e61-8c24dd3be415'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Today, some scientists have argued that the biosphere itself is a kind of super organism.', FALSE, 3, NULL, NULL),
  ('20435140-4252-5446-ae0c-028113508f17'::uuid, 'a7a0ed14-5c79-5c06-9e61-8c24dd3be415'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It includes every living organism on the planet as well as their interactions with the earth, water, and air.', FALSE, 4, NULL, NULL),
  ('7574757b-bdf7-54de-89ac-f4531b4a1e06'::uuid, 'a7a0ed14-5c79-5c06-9e61-8c24dd3be415'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Each of the plants, animals and other organisms serve as just a piece of the whole.', FALSE, 5, NULL, NULL),
