  ('85ad4bff-a4d0-52c2-a856-c59257fb90fa'::uuid, 'a8a2e656-ca41-54b6-90ab-368183c9609a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, deforestation is a significant threat, which has led to the loss of biodiversity and ecological balance.', FALSE, 2, NULL, NULL),
  ('4cfa0f34-2638-5dd3-ad74-dada158ce61a'::uuid, 'a8a2e656-ca41-54b6-90ab-368183c9609a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They also absorb carbon dioxide, which helps mitigate climate change.', FALSE, 3, NULL, NULL),
  ('26ec2cc2-26f0-5054-91a9-fb4c91045c13'::uuid, 'a8c018ff-fce5-5459-a3c5-53bcc5e080d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Despite its chaotic and violent nature, the French Revolution played a crucial role in shaping modern nations by promoting ideas of liberty and democracy.', FALSE, 0, NULL, NULL),
  ('d3bd831f-0e87-50b8-9d30-25d4faa96cb3'::uuid, 'a8c018ff-fce5-5459-a3c5-53bcc5e080d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It arose from economic distress and political discontent with the monarchy.', FALSE, 1, NULL, NULL),
  ('7a2b3bb9-fa1c-5512-a938-0ca826f3a543'::uuid, 'a8c018ff-fce5-5459-a3c5-53bcc5e080d5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The revolution led to the overthrow of the Bourbon monarchy, the rise of Napoleon, and the establishment of the French Republic.', FALSE, 2, NULL, NULL),
