  ('30eae6ae-a9cd-55b9-9a68-084598450c87'::uuid, 'abdcd6bd-0225-5a8e-8600-c84c458035cd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, deforestation is posing a severe threat to these biodiverse environments, leading to the loss of species and contributing to global climate change.', FALSE, 2, NULL, NULL),
  ('80278639-196c-5e66-b80b-2ff86b217b29'::uuid, 'abdcd6bd-0225-5a8e-8600-c84c458035cd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These forests cover only 6% of the Earth''s surface but contain more than half of the world''s plant and animal species.', FALSE, 3, NULL, NULL),
  ('5fa1bfad-54fd-526b-8c61-4a8d1fe90555'::uuid, 'abe6fc5f-cd7b-55ec-8472-ab3b09c3d0f4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Skin lesions that are benign are noncancerous and often harmless.', FALSE, 0, NULL, NULL),
  ('99b3ccc6-d9df-5109-bf06-2f244fb20672'::uuid, 'abe6fc5f-cd7b-55ec-8472-ab3b09c3d0f4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They are common and may be the result of an injury or damage to your skin, like sunburn.', FALSE, 1, NULL, NULL),
  ('ee862b1c-dbc3-59de-a73d-24470d6945fd'::uuid, 'abe6fc5f-cd7b-55ec-8472-ab3b09c3d0f4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Skin lesions are areas of your skin that are different from the skin around them.', FALSE, 2, NULL, NULL),
  ('70d4b926-26e5-58b8-9ce2-96c14bc45e4b'::uuid, 'abe6fc5f-cd7b-55ec-8472-ab3b09c3d0f4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Most benign lesions don’t need treatment unless they’re bothering you or you don’t like how they look.', FALSE, 3, NULL, NULL),
