  ('b8779a03-d677-54c8-8a53-6baaa0934c82'::uuid, 'af41b727-f0d5-5db3-94d9-c9ef67d91686'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Research has shown that when you start fiddling around for about 20 hours, you will lose your opportunity to be an expert in language in the future, because these 20 hours in the beginning are the most important.', FALSE, 0, NULL, NULL),
  ('ed8f0b6b-c9f0-5939-8c19-7e693b90e4f5'::uuid, 'af41b727-f0d5-5db3-94d9-c9ef67d91686'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Research has shown that a person can become a master in drawing or chainsaws within only 20 hours, but you need to practise your skills intelligently.', FALSE, 1, NULL, NULL),
  ('7452394c-0de5-5cc9-ad01-e7a8f023732c'::uuid, 'af41b727-f0d5-5db3-94d9-c9ef67d91686'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Research has shown that it’s not hard to accumulate 20 hours to improve your skills, but this has to happen within a month, because skipping a couple days will make your efforts useless.', FALSE, 2, NULL, NULL),
  ('8049bf29-7600-58e6-8fb8-89d7da20ecc2'::uuid, 'af41b727-f0d5-5db3-94d9-c9ef67d91686'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Research has shown that it takes you just 20 hours to be reasonably good in a thing, provided that you have invested these 20 hours in an intelligent and effective way.', TRUE, 3, NULL, NULL),
