  ('27f26653-a3af-51aa-b493-03d0adfa4286'::uuid, 'af6379bd-e8b0-5694-b1ab-979b6dd38cb3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In other words, the electric field surrounding a charged particle exerts a force on other charged particles, causing it to move and thus do work.', FALSE, 1, NULL, NULL),
  ('0c8d5f56-6b69-584b-b11d-244853c306a9'::uuid, 'af6379bd-e8b0-5694-b1ab-979b6dd38cb3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The basic principle is that electrons in copper wire are free to move.', FALSE, 2, NULL, NULL),
  ('2f430c69-f315-5baa-a561-acc007dbe124'::uuid, 'af6379bd-e8b0-5694-b1ab-979b6dd38cb3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'He moved a loop or disc of conductive metal between the poles of a magnet.', FALSE, 3, NULL, NULL),
  ('59a4e458-4da7-5902-8cec-e88b7dd67482'::uuid, 'af6379bd-e8b0-5694-b1ab-979b6dd38cb3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The British scientist Michael Faraday discovered a means of generating electricity as early as the 1820s.', FALSE, 4, NULL, NULL),
  ('78231f7c-48d5-5d88-a038-75b45933826c'::uuid, 'af7aef70-95a9-5ca0-b641-5d9d4c8b0af4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Nearly eight out of 10 people live in poverty.', FALSE, 0, NULL, NULL),
  ('79af1575-f53c-5038-8d1f-72531276eea1'::uuid, 'af7aef70-95a9-5ca0-b641-5d9d4c8b0af4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'South Sudan is one of the world’s poorest countries, plagued with fragility, conflict, and violence.', FALSE, 1, NULL, NULL),
  ('f40fa71b-9a4e-59c5-838b-224551619b52'::uuid, 'af7aef70-95a9-5ca0-b641-5d9d4c8b0af4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These have increased food insecurity and further exacerbated malnutrition for millions of people.', FALSE, 2, NULL, NULL),
  ('a2da4ef1-dbaa-52cc-a918-7b6ec466dd56'::uuid, 'af7aef70-95a9-5ca0-b641-5d9d4c8b0af4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The country is a classic case of ‘compounding’ crisis – dealing with the devastating effects of COVID-19, desert locust invasion, and flooding.', FALSE, 3, NULL, NULL),
  ('cb9211f9-8295-508d-91e7-4e8a8e66030d'::uuid, 'af9b40af-b8cd-571e-b974-7d3ff0f8f48c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The researchers checked in periodically, asking the participants if their minds were on task or wandering.', FALSE, 0, NULL, NULL),
  ('22291cc2-a6e5-53df-9383-0ffe8f8ec118'::uuid, 'af9b40af-b8cd-571e-b974-7d3ff0f8f48c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Researchers studied groups of people from the University of Wisconsin-Madison community, ranging in age from 18 to 65.', FALSE, 1, NULL, NULL),
  ('a9704ff9-4a29-5d1c-8d2a-c82f8dc9f2e8'::uuid, 'af9b40af-b8cd-571e-b974-7d3ff0f8f48c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'When the task was over, they measured each participant''s working memory capacity by having them remember letters while doing math equations.', FALSE, 2, NULL, NULL),
  ('473c465e-a7d6-5f88-9c23-c9987445b347'::uuid, 'af9b40af-b8cd-571e-b974-7d3ff0f8f48c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The first group was asked to perform simple tasks, like pressing a button every time they took a breath or clicking in response to a letter popping up on a computer screen; these tasks were so easy that their minds were likely to wander, the researchers figured.', FALSE, 3, NULL, NULL),
  ('57b75b71-7ea6-5bc8-8fcb-ecefa38f27fd'::uuid, 'af9b9ef8-de50-56eb-8d15-c4f8dcb9d04c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'taken off', FALSE, 0, 0, NULL),
