  ('c3cc9386-9c94-5b5a-ad7f-2e9d4ff3aa9c'::uuid, 'afd72f51-0acb-50ff-8af4-3f1ef750e986'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'More importantly, the Arcelor Mittal deal demonstrates Europe''s deepening integration into the global economy.', FALSE, 1, NULL, NULL),
  ('af5b927c-d89d-5cd5-8a8a-36ce3b14a798'::uuid, 'afd72f51-0acb-50ff-8af4-3f1ef750e986'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The takeover battle raged for six months before Arcelor''s bosses finally listened to shareholders who wanted the board to accept Mittal''s third offer.', FALSE, 2, NULL, NULL),
  ('107642a3-bda5-5fff-907d-99970f53c5bd'::uuid, 'afd72f51-0acb-50ff-8af4-3f1ef750e986'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The story tells us two things about European business, both positive.', FALSE, 3, NULL, NULL),
  ('1fcbea08-f67e-5074-ae5e-8666db061822'::uuid, 'afd72f51-0acb-50ff-8af4-3f1ef750e986'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It was taken over by Mittal, a Dutch-registered company run from London by its biggest single shareholder, Lakshmi Mittal, an Indian who started his first business in Indonesia.', FALSE, 4, NULL, NULL),
  ('78ca2f9b-dd09-5d2f-a1bc-8ede7a31de9c'::uuid, 'afdd569e-bbe6-53e6-84aa-f1357ae3cd0f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There were three toys in the room: a train (boy stereotype), a doll (girl stereotype) and a fish (neutral).', FALSE, 0, NULL, NULL),
  ('e23c805f-cab3-53c3-a426-cd8d4622418a'::uuid, 'afdd569e-bbe6-53e6-84aa-f1357ae3cd0f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The research by Will and colleagues dressed 6-month-old babies in different colored outfits that did not necessarily match their gender, so the participants had no way of knowing if the baby was in fact a boy or a girl.', FALSE, 1, NULL, NULL),
  ('4444d7f2-8c5f-5e5f-88f9-4949e4516d71'::uuid, 'afdd569e-bbe6-53e6-84aa-f1357ae3cd0f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Sometimes, the infant was dressed in blue and was called Adam and sometimes it was dressed in pink and was called Beth.', FALSE, 2, NULL, NULL),
  ('f5ee2d6c-2f62-564e-b29f-d051f55d3d6d'::uuid, 'afdd569e-bbe6-53e6-84aa-f1357ae3cd0f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This study found that babies dressed in blue and thought to be boys were more likely to be given the train.', FALSE, 3, NULL, NULL),
  ('1f69aebd-2b9d-52c2-bb2c-94bf596fd090'::uuid, 'afdd569e-bbe6-53e6-84aa-f1357ae3cd0f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Babies in pink or ''girls'' were more likely to be given the doll and more people smiled at ''Beth'' then at ''Adam''.', FALSE, 4, NULL, NULL),
  ('da9a6191-1019-5f05-a1bb-907ef7c4870e'::uuid, 'afdf1614-af4d-5ef7-ba68-5b8fd4e5a6c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The subject is culture and the two kinds of it - material, which is to do with technology and science, such as genetics, and non-material, which is basically what we think about it, our beliefs and so forth. The speaker''s main point is how our beliefs and attitudes resist developments in the material culture even when they know they are beneficial.', FALSE, 0, NULL, NULL),
  ('b56936ba-0377-56bc-a833-ea76473b9c15'::uuid, 'afdf1614-af4d-5ef7-ba68-5b8fd4e5a6c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In comparing material with non-material culture - the first being the objects and technologies we create, and the second our customs, beliefs and attitudes - the speaker gives greater emphasis to the material culture. He gives the example of the development of genetic science and the benefits it has brought to mankind, despite a fair amount of opposition.', FALSE, 1, NULL, NULL),
  ('9338993b-a667-57fa-95f6-e180b5007b3c'::uuid, 'afdf1614-af4d-5ef7-ba68-5b8fd4e5a6c8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For the purposes of argument, culture is divided into material and non-material, and the speaker''s aim is to show how they both affect each other. Material developments in tools and technology can affect non- material culture, our customs and beliefs, and the other way around. Genetics is used as an example as it has changed the way we think about life, but also our beliefs have affected its rate of development.', TRUE, 2, NULL, NULL),
  ('2b4c06e5-e066-5a07-a522-3865de728701'::uuid, 'afe2ae89-3126-5b7e-b8b9-bec0cbc3b5fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'originated', TRUE, 0, 0, NULL),
  ('b6d4849e-8440-5020-9909-81b7c25b20c1'::uuid, 'afe2ae89-3126-5b7e-b8b9-bec0cbc3b5fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'laminated', FALSE, 1, 0, NULL),
