  ('1c3e0825-d379-5f6a-b731-0b6d28ef744b'::uuid, 'b069d1cc-c67c-5ff3-b570-5094cf8724af'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'source', FALSE, 19, 4, NULL),
  ('ae15888f-3765-5021-a0ff-959c64a5a769'::uuid, 'b07126cc-1542-5c52-ae22-fc8973c0f299'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This process begins in the mouth, where food is mechanically broken down by chewing and chemically by saliva.', FALSE, 0, NULL, NULL),
  ('431d33f6-6b91-54bb-b598-5445dc160529'::uuid, 'b07126cc-1542-5c52-ae22-fc8973c0f299'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It then travels to the stomach and intestines, where further digestion and nutrient absorption occur.', FALSE, 1, NULL, NULL),
  ('320f90cb-3529-57bc-a31a-fef57552fa91'::uuid, 'b07126cc-1542-5c52-ae22-fc8973c0f299'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The human digestive system is designed to break down food and absorb nutrients.', FALSE, 2, NULL, NULL),
  ('b3bfb3f2-9bc3-5c6d-9c46-f65361edb219'::uuid, 'b07126cc-1542-5c52-ae22-fc8973c0f299'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, problems like poor diet and diseases can disrupt this process, leading to health issues.', FALSE, 3, NULL, NULL),
  ('a93425ed-6321-5f31-aa75-ba05bdd23b4c'::uuid, 'b0973da2-dc4b-5685-b382-cf166a8e9d58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For example, if an airplane were to travel westward with the sun, 24 hr would elapse as it circled the globe, but it would still be the same day for those in the airplane while it would be one day later for those on the ground below them.', FALSE, 0, NULL, NULL),
  ('a23c9244-2c52-5112-95fd-a7b1febc3fe9'::uuid, 'b0973da2-dc4b-5685-b382-cf166a8e9d58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The apparent paradox is resolved by requiring that the traveler crossing the date line change his date, thus bringing the travelers into agreement when they meet.', FALSE, 1, NULL, NULL),
  ('f7455381-63f5-5a4a-bb98-7eb07fd9f0f8'::uuid, 'b0973da2-dc4b-5685-b382-cf166a8e9d58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The same problem would arise if two travelers journeyed in opposite directions to a point on the opposite side of the earth, 180° of longitude distant.', FALSE, 2, NULL, NULL),
  ('a500ff67-7563-5071-9495-4539bd88eb05'::uuid, 'b0973da2-dc4b-5685-b382-cf166a8e9d58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The date line is necessary to avoid a confusion that would otherwise result.', FALSE, 3, NULL, NULL),
  ('c888b815-4ab6-5cb3-9a92-5615544e9c7a'::uuid, 'b0973da2-dc4b-5685-b382-cf166a8e9d58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'International Date Line, imaginary line on the earth''s surface, generally following the 180° meridian of longitude  , where, by international agreement, travelers change dates.', FALSE, 4, NULL, NULL),
  ('e640d1b6-4be0-5cfc-9c8e-6ea5ead5d5e9'::uuid, 'b0b03065-c2e8-5ba8-9d1a-deea986b88fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Once you have done this, you have set the stage for successful reviewing and revising.', FALSE, 0, NULL, NULL),
  ('af614034-6d2d-586c-89d6-932ea9da68d9'::uuid, 'b0b03065-c2e8-5ba8-9d1a-deea986b88fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Get them down, and then later reorganize them in your own words.', FALSE, 1, NULL, NULL),
  ('0192211b-2d48-5d90-8e36-b4079bb493e0'::uuid, 'b0b03065-c2e8-5ba8-9d1a-deea986b88fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Your main job in taking lecture notes is to be a good listener.', FALSE, 2, NULL, NULL),
  ('f58227ff-53b8-5d0e-9ff3-e2d387c8ebbe'::uuid, 'b0b03065-c2e8-5ba8-9d1a-deea986b88fb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To be a good listener, you must learn to focus and concentrate on the main points of the lecture.', FALSE, 3, NULL, NULL),
  ('33450c3c-34f4-5cfa-94b6-0220344938e0'::uuid, 'b101cf03-d5a6-5da7-8f95-fe894ac68db1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'suggested', TRUE, 0, 0, NULL),
