  ('c117e438-1b5b-502b-8aa8-91a43e462538'::uuid, 'b128dce8-1f90-50e6-99b4-ad11a07b8648'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'portion', FALSE, 19, 4, NULL),
  ('2e728423-f31b-5874-b6e3-fa776c7a8169'::uuid, 'b144eee8-6c2a-5682-b90c-82197c132b4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Suggestions for entrepreneurs to better manage their companies.', FALSE, 0, NULL, NULL),
  ('e8359692-946a-5d83-915a-dc311ab2ec72'::uuid, 'b144eee8-6c2a-5682-b90c-82197c132b4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Reports about the dire situation of the unemployed people.', FALSE, 1, NULL, NULL),
  ('7c9fd7d9-3f67-57d2-a4ef-987616fbd3e5'::uuid, 'b144eee8-6c2a-5682-b90c-82197c132b4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Advice to job-seekers on how to get employment efficiently.', FALSE, 2, NULL, NULL),
  ('3de3455b-d7b9-547c-98ae-70ec5117c9bd'::uuid, 'b144eee8-6c2a-5682-b90c-82197c132b4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Discussion about the problems confronting the labor market.', TRUE, 3, NULL, NULL),
  ('c8493bdf-b2a2-56c5-a0a2-02e92612429a'::uuid, 'b14f9231-311a-5cd9-8c65-1ed3bb7a1e42'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Religious groups and private charities used to provide individual aid to help people in poverty meet essential demands. These organizations provide subsidies for housing, food, energy, and healthcare. However, this may lead to a dangerous consequence that these people in need mostly rely on those subsidies, instead of finding a job themselves.', FALSE, 0, NULL, NULL),
  ('28b690e2-4c7a-51e2-a56e-17c7ed5a27bf'::uuid, 'b14f9231-311a-5cd9-8c65-1ed3bb7a1e42'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Welfare programs are devised to ensure assistance goes to people who need it the most. Once they earn more than the qualification threshold, they will no longer be provided with such welfare. If people gain no net benefit from working, they’re more likely to remain in government help, which will lead to a low employment rate and a sluggish economy.', TRUE, 1, NULL, NULL),
  ('ffe82f57-c675-5d7e-be78-a36fb481a81a'::uuid, 'b14f9231-311a-5cd9-8c65-1ed3bb7a1e42'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'People work for many reasons, including societal norms and personal values. These reasons have inspired them to solve the problem of poverty. When the economy slows down, they will work harder to find a job, in case of an unemployment, and that in turn boosts the economy.', FALSE, 2, NULL, NULL),
  ('3a25c6a5-b534-55ae-9414-246db3b9e81a'::uuid, 'b14f9231-311a-5cd9-8c65-1ed3bb7a1e42'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Welfare programs are designed for people who fall below a certain income level. Only they are eligible for benefits provided by governments, who will support these people no matter whether they find a job in the future or not. Thus, tax payers will have a heavier burden to support the governments.', FALSE, 3, NULL, NULL),
  ('ba0feeb9-a442-56ff-8bd5-7864427e7227'::uuid, 'b15ce2ef-29bc-5e2a-9920-5a08c3ad392d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Drinking coffee.', FALSE, 0, NULL, NULL),
  ('4998c82c-6659-5f48-9a7b-a79d866b8ef4'::uuid, 'b15ce2ef-29bc-5e2a-9920-5a08c3ad392d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Eating supplementary drugs.', TRUE, 1, NULL, NULL),
  ('451cb81c-22be-55e6-a646-756b3a1bd490'::uuid, 'b15ce2ef-29bc-5e2a-9920-5a08c3ad392d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Doing exercise every day.', FALSE, 2, NULL, NULL),
  ('4adc7ba0-303c-54f3-97d4-8ed52d70ae01'::uuid, 'b15ce2ef-29bc-5e2a-9920-5a08c3ad392d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Eating nuts.', FALSE, 3, NULL, NULL),
  ('06604928-036e-5f9d-bcca-8a1a207eb5ab'::uuid, 'b164e3f0-974c-5ba5-b570-73823c3a8f3d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Their mission collected valuable scientific data and samples from the Moon''s surface.', FALSE, 0, NULL, NULL),
  ('2437e257-bb86-5483-8ced-2e0ae0a72596'::uuid, 'b164e3f0-974c-5ba5-b570-73823c3a8f3d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This milestone spurred further lunar missions and opened new possibilities for human space travel, forever altering humanity''s view of its place in the universe.', FALSE, 1, NULL, NULL),
  ('7f0b556c-dc60-5884-bf60-c71024baec86'::uuid, 'b164e3f0-974c-5ba5-b570-73823c3a8f3d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Following this historic event, astronauts Neil Armstrong and Buzz Aldrin explored the lunar surface, while Michael Collins orbited above in the command module.', FALSE, 2, NULL, NULL),
  ('b17bd5d5-b8a9-566d-b7d7-4c3eaf6758b2'::uuid, 'b164e3f0-974c-5ba5-b570-73823c3a8f3d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In 1969, the Apollo 11 mission successfully landed the first humans on the Moon.', FALSE, 3, NULL, NULL),
  ('60c0f328-1e41-5f9b-ba72-576cd3b1d8f4'::uuid, 'b16e290f-f473-5885-97ed-7e9f6243ecb9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'surge', TRUE, 0, NULL, 4);
