  ('23f25995-62ad-5909-b098-413fb5f0a5a5'::uuid, 'b1c2c557-cf98-5c95-a660-f570ea5349c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This flexibility is particularly beneficial for those who need to balance work or family commitments.', FALSE, 0, NULL, NULL),
  ('ae2f0578-3857-53a3-aecf-b6a6d9eefb6e'::uuid, 'b1c2c557-cf98-5c95-a660-f570ea5349c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'One of the major advantages of online education is the flexibility it offers.', FALSE, 1, NULL, NULL),
  ('38902beb-d170-560b-b0cc-494ca77c2c99'::uuid, 'b1c2c557-cf98-5c95-a660-f570ea5349c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Yet, this same flexibility can lead to procrastination and lack of structure.', FALSE, 2, NULL, NULL),
  ('a247d5ce-afd5-59a0-bf9d-8f4803993cd5'::uuid, 'b1c2c557-cf98-5c95-a660-f570ea5349c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Therefore, effective online learning requires strong self-discipline and time management skills.', FALSE, 3, NULL, NULL),
