  ('2dadeac2-c9f1-57a9-8d68-56736d73c9a5'::uuid, 'b224ac42-80c9-59e1-99e3-3b9d8c742640'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To test this theory, Andrew Oxenham and his colleagues at the University of Minnesota in Minneapolis asked a group of six students whether two four-note melodies were identical or not.', FALSE, 2, NULL, NULL),
  ('a6ffc372-ed39-5918-9112-5c956307084e'::uuid, 'b224ac42-80c9-59e1-99e3-3b9d8c742640'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Previous studies have shown that humans are unable to recognize melodies whose notes have a fundamental tone above 5 kilohertz.', FALSE, 3, NULL, NULL),
