  ('477afb89-bd17-5cae-9914-bb2ab0e8e5ab'::uuid, 'b3563962-7622-5881-8f2d-81b87845f177'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'X-rays are scattered according to the atomic structure of the crystal lattice.', TRUE, 1, NULL, NULL),
  ('f2f268e0-71b8-59b9-8961-127beab45e73'::uuid, 'b3563962-7622-5881-8f2d-81b87845f177'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The analysis of chemical compounds was only passible after the development of computer technology.', FALSE, 2, NULL, NULL),
  ('faf4a673-ba17-5ca3-bcb1-3cdfa65e268d'::uuid, 'b3563962-7622-5881-8f2d-81b87845f177'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The process can be used to determine the chemical structure of biological compounds.', TRUE, 3, NULL, NULL),
  ('8e291b85-daa1-5d4a-8f06-3cd6bf338611'::uuid, 'b3563962-7622-5881-8f2d-81b87845f177'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'X-rays will not diffract in crystalline substances.', FALSE, 4, NULL, NULL),
  ('2a4b7434-5cfb-575e-a510-fa36e296921d'::uuid, 'b3702c51-6c2c-5b5e-a87a-856eb36f34c2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Despite this, for the first decades of his life Darwin failed to distinguish himself, first dropping out of medical studies in Edinburgh because he hated the sight of blood, and subsequently entering Cambridge to study for the profession of clergyman very much as second option.', FALSE, 0, NULL, NULL),
  ('729f8133-e7eb-55c0-a903-2a29c077fff4'::uuid, 'b3702c51-6c2c-5b5e-a87a-856eb36f34c2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'His paternal grandfather was Erasmus Darwin, a famous scientist who came up with his own theory of evolution, while his maternal grandfather was Josiah Wedgwood, of pottery fame.', FALSE, 1, NULL, NULL),
  ('b9f56bf9-67e0-5a37-804b-c8560e76ef80'::uuid, 'b3702c51-6c2c-5b5e-a87a-856eb36f34c2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Charles Darwin was born on 12 February 1809 into a rich and powerful family.', FALSE, 2, NULL, NULL),
  ('11774e8d-d9cf-5ee7-bc52-ecf0eaf2c8e4'::uuid, 'b3702c51-6c2c-5b5e-a87a-856eb36f34c2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Yet Darwin was gaining great skill as an amateur naturalist and it was this that allowed him to seize the opportunity presented when he was offered an unpaid position as scientist on board the Beagle, a naval surveying ship bound for the farthest corners of the globe.', FALSE, 3, NULL, NULL),
  ('f5ebfed9-7679-5103-913a-329aadd733ec'::uuid, 'b3702c51-6c2c-5b5e-a87a-856eb36f34c2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The five-year voyage was the making of Darwin, providing him with the wealth of observations of the natural world that established him as one of the foremost scientists of his age and provided the raw material for his revolutionary theory.', FALSE, 4, NULL, NULL),
  ('9351f0d6-cc49-5886-9b57-384890c51db7'::uuid, 'b38a5b4d-6294-5c5a-ad3f-b70b0fe55a6e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ever', TRUE, 0, 0, NULL),
