  ('f9bceeb9-e24b-501d-ab50-107b68a1cff7'::uuid, 'b6557e73-ee49-56ea-8e11-e81f288ced25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But for France''s Bonpoint, making kids'' clothing is the main business.', FALSE, 1, NULL, NULL),
