  ('1134fe83-daed-5e30-8625-8f9fc325a4f0'::uuid, 'b6557e73-ee49-56ea-8e11-e81f288ced25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Since Bonpoint was founded 40 years ago by clothes store owner Marie-France and Bernard Cohen, children and babies have been at the centre of the brand''s development.', FALSE, 3, NULL, NULL),
  ('1bd5d924-6c5d-5134-9a2e-fbae8fbb4610'::uuid, 'b65d2e85-006b-55e1-9fc8-31171b4bf3bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The European Coal and Steel Community, founded in 1951, is the first step in securing a lasting peace.', FALSE, 0, NULL, NULL),
  ('0f84cbcf-223d-5087-adcf-5dc2ceee664a'::uuid, 'b65d2e85-006b-55e1-9fc8-31171b4bf3bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In 1957, the Treaty of Rome establishes the European Economic Community (EEC) and a new era of ever-closer cooperation in Europe.', FALSE, 1, NULL, NULL),
  ('3d7ba275-54b5-566e-a2b8-f2e817aa50df'::uuid, 'b65d2e85-006b-55e1-9fc8-31171b4bf3bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This period, however, also sees the emergence of a Cold War that divides the continent for more than 40 years.', FALSE, 2, NULL, NULL),
  ('b9949944-46f9-563d-a4ab-05dabaea2291'::uuid, 'b65d2e85-006b-55e1-9fc8-31171b4bf3bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'With the aim of ending the frequent and bloody conflicts that culminated in the Second World War, European politicians begin the process of building what we know today as the European Union.', FALSE, 3, NULL, NULL),
  ('f2ab4dcb-d41b-591d-aab4-94ff10d5da7d'::uuid, 'b66647c8-052a-5211-aaef-b2065bd21a3b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'engage', TRUE, 0, NULL, 0),
