  ('45f9346d-0342-51a7-b470-6c86c709fcef'::uuid, 'b678d88d-545e-54cb-97f3-362e07f7c5ff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The physical location of a restaurant in the competitive landscape of the city has long been known as a major factor in its likely success or failure.', FALSE, 0, NULL, NULL),
  ('90050972-48fd-59df-ba12-c0fa2ddf6e60'::uuid, 'b678d88d-545e-54cb-97f3-362e07f7c5ff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'All they can do is work to improve customer access to their premises.', FALSE, 1, NULL, NULL),
  ('03e42e1c-16b1-5fb8-9fc5-272256267516'::uuid, 'b678d88d-545e-54cb-97f3-362e07f7c5ff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Once restaurants are established in such environments they can do little about their location.', FALSE, 2, NULL, NULL),
