  ('63930656-9857-5e63-9c5e-f96608ebcb6f'::uuid, 'b68e804f-00e7-53a9-9ac5-0355b4edb0f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'People on the bottom face shortcomings within their own governmental systems and weaknesses in global institutions.', FALSE, 1, NULL, NULL),
