  ('bfc5256e-cae9-5068-a1cf-b8d080f904a7'::uuid, 'b68e804f-00e7-53a9-9ac5-0355b4edb0f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The COVID-19 pandemic and related shutdowns are challenging the effectiveness of civil and institutional structures around the world, resulting in interrelated crises for foreign policy, development, and economics.', FALSE, 3, NULL, NULL),
