  ('f688cd9e-cb3d-51fe-851b-03a7877db37c'::uuid, 'b74e7ef0-296b-5be6-933c-593b7b775f38'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Copernicus probably hit upon his main idea sometime between 1508 and 1514.', FALSE, 0, NULL, NULL),
  ('90fce7af-a708-5ba9-9b1e-cbbfb3ef6f3e'::uuid, 'b74e7ef0-296b-5be6-933c-593b7b775f38'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For years, however, he delayed publication of his controversial work, which contradicted all the authorities of the time.', FALSE, 1, NULL, NULL),
  ('94a596d8-7ca6-5ba9-8b3d-21d68822a0af'::uuid, 'b74e7ef0-296b-5be6-933c-593b7b775f38'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'According to legend, Copernicus received a copy as he was dying, on May 24, 1543.', FALSE, 2, NULL, NULL),
  ('b549d036-79b0-5d0e-8ba1-9b86f210321f'::uuid, 'b74e7ef0-296b-5be6-933c-593b7b775f38'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The historic book that contains the final version of his theory, De revolutionibus orbium coelestium libri vi ("Six Books Concerning the Revolutions of the Heavenly Orbs"), did not appear in print until 1543, the year of his death.', FALSE, 3, NULL, NULL),
  ('5cf20444-5b3d-5ee8-86ad-c6e3a85d68bc'::uuid, 'b75209ae-f2d9-59f0-b587-5e1a63bb05b3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A Technology for recording brainwaves in wild animals awakens a more sophisticated understanding of the function of sleep.', FALSE, 0, NULL, NULL),
  ('4a77723b-69cc-5df4-bb84-bd630d015aa6'::uuid, 'b75209ae-f2d9-59f0-b587-5e1a63bb05b3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Studies using miniature sleep recording devices known as neurologgers have already challenged several long-held beliefs about the sleeping habits of sloths and birds.', FALSE, 1, NULL, NULL),
  ('727c346b-1acc-559c-8ab5-1e558cefb2df'::uuid, 'b75209ae-f2d9-59f0-b587-5e1a63bb05b3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'And male sandpipers can go almost entirely without sleep during the three-week breeding season, helping maximize success at that time.', FALSE, 2, NULL, NULL),
  ('4a848c5d-48a5-500e-a258-ba86428988b8'::uuid, 'b75209ae-f2d9-59f0-b587-5e1a63bb05b3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Three toed sloths, for example, sleep far less than once thought.', FALSE, 3, NULL, NULL),
  ('827458ef-b650-54d9-8cbe-01d7553677db'::uuid, 'b75209ae-f2d9-59f0-b587-5e1a63bb05b3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Now John Lesku of La Trobe University in Melbourne and his colleagues are using neurologgers to investigate whether light pollution interferes with the circadian rhythms of tammar wallabies in Australia.', FALSE, 4, NULL, NULL),
  ('2735e79d-1331-5f47-80a7-aabf03440f3c'::uuid, 'b75d336e-e9e2-590a-9d85-b01aecec52d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'may', TRUE, 0, NULL, 0),
