  ('b71acecf-44a5-54fc-a02c-445d48e9b823'::uuid, 'b85ba281-a792-5123-896e-886eec9cc1e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The standard criterion for the survival of a species is its success in competing with other species and adapting to slowly changing environments.', FALSE, 1, NULL, NULL),
  ('3ddd4f99-e925-5323-b7af-dc654fcbf3da'::uuid, 'b85ba281-a792-5123-896e-886eec9cc1e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Yet an equally important criterion is the ability of a species to survive random global ecological catastrophes due to impacts.', FALSE, 2, NULL, NULL),
  ('abc089d4-9ca7-5e35-b06a-58f9d41f3b36'::uuid, 'b85ba281-a792-5123-896e-886eec9cc1e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'According to some estimates, the majority of all extinctions of species may be due to such impacts.', FALSE, 3, NULL, NULL),
  ('0eae9d06-a3c1-599e-9585-f63bd7080a9e'::uuid, 'b85ba281-a792-5123-896e-886eec9cc1e1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Such a perspective fundamentally changes our view of biological evolution.', FALSE, 4, NULL, NULL),
  ('2851f993-c2fe-5a06-8a10-22b165242d18'::uuid, 'b860a4d5-6f48-5441-982a-968a6c976557'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As a result, flying is now statistically safer than driving.', FALSE, 0, NULL, NULL),
  ('36f72611-43bd-5997-913d-3612299b2ab5'::uuid, 'b860a4d5-6f48-5441-982a-968a6c976557'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, continual improvements in aircraft design, navigation technology, and pilot training have drastically reduced accidents.', FALSE, 1, NULL, NULL),
  ('f294fbaf-e13e-5653-927d-8016e1464e3c'::uuid, 'b860a4d5-6f48-5441-982a-968a6c976557'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Air travel is one of the safest modes of transportation, thanks to rigorous safety standards and technological advancements.', FALSE, 2, NULL, NULL),
  ('eae4b32f-e74a-51e9-84a8-f7b6094cf590'::uuid, 'b860a4d5-6f48-5441-982a-968a6c976557'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Initially, air travel faced skepticism due to high-profile accidents.', FALSE, 3, NULL, NULL),
