  ('1d9d490e-bc77-5405-98de-a9beea23d370'::uuid, 'b92e6f22-0978-5192-88ac-23eb9a831e1a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'psychological', TRUE, 15, 3, NULL),
  ('cc6b5b8e-93b0-5f0f-8add-c34da0670e14'::uuid, 'b93c42bb-de5b-5894-862e-d108c4f48fac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Education is not about learning the most recent technique, but is to encourage people to synthesize the information they’ve learned and come up with their own answers. Otherwise you may be behind the curve of new information.', TRUE, 0, NULL, NULL),
  ('d886d97a-73aa-51e1-aa28-1573c247b88c'::uuid, 'b93c42bb-de5b-5894-862e-d108c4f48fac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'When students want to acquire new knowledge, they need to use the most recent technique. They also have to forget what they have already learned, in order not to let the former memories mess with new information.', FALSE, 1, NULL, NULL),
  ('7599c97b-bd0e-51ee-a619-3f19345f3943'::uuid, 'b93c42bb-de5b-5894-862e-d108c4f48fac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Many changes have occurred in technology and other aspects of American life. We need to study in order to keep up with the changes. Even when we graduate from schools, we still have to keep studying.', FALSE, 2, NULL, NULL),
  ('27a319e4-1377-5fdd-a22e-87c01ad107d1'::uuid, 'b93c42bb-de5b-5894-862e-d108c4f48fac'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'If you’re already behind the curve, you need to study harder to get more information or knowledge. Developing certain study skills can help you with that, especially when you are under 18 years old.', FALSE, 3, NULL, NULL),
  ('a3f4ce45-6fef-5410-a8f1-3194c7bb7124'::uuid, 'b93f7967-84a8-5212-bd23-9f2dd377621e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'dives', FALSE, 0, 0, NULL),
