  ('db48bce2-0b19-55ab-b319-62c0b58f6a3c'::uuid, 'b9b2177c-8621-5360-99a2-69af1eda7c9f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'resulting', FALSE, 6, NULL, NULL),
  ('54c4521e-bc8e-5fa1-8fa8-6a44f62e6b61'::uuid, 'b9b9637e-d5c9-5db3-9dfb-641b5332c712'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, this industry is also vulnerable to economic fluctuations, as seen during the COVID-19 pandemic.', FALSE, 0, NULL, NULL),
  ('ec463aab-a1bf-519e-8516-31d93ebc39d8'::uuid, 'b9b9637e-d5c9-5db3-9dfb-641b5332c712'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The pandemic''s impact underscored the need for the industry to adapt and diversify to mitigate future risks.', FALSE, 1, NULL, NULL),
  ('6d8c9d7e-7c1d-529d-a375-8111e34be8bd'::uuid, 'b9b9637e-d5c9-5db3-9dfb-641b5332c712'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It not only facilitates international trade and tourism but also creates millions of jobs worldwide.', FALSE, 2, NULL, NULL),
  ('f30701dc-6512-502c-a5ce-1a68612ef16c'::uuid, 'b9b9637e-d5c9-5db3-9dfb-641b5332c712'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The aviation industry is a significant contributor to the global economy.', FALSE, 3, NULL, NULL),
  ('2863d858-cd87-5e1b-9c91-d4520856da23'::uuid, 'b9b99448-4888-512b-a545-be2f55ba8310'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'One way researchers can limit the scope of a study is by using a specific sampling method.', FALSE, 0, NULL, NULL),
  ('3a1feb13-90d1-59f0-9214-a6f258ce1b55'::uuid, 'b9b99448-4888-512b-a545-be2f55ba8310'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For example, the researcher could decide to only observe subjects every morning for an hour.', FALSE, 1, NULL, NULL),
  ('e3797055-e888-50c3-aaf9-627a2740a6c0'::uuid, 'b9b99448-4888-512b-a545-be2f55ba8310'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These intervals could be random or specific.', FALSE, 2, NULL, NULL),
  ('763f1342-c60f-5c94-aa8f-84db7da70090'::uuid, 'b9b99448-4888-512b-a545-be2f55ba8310'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The most common sampling method is time sampling, which means the researcher will observe subjects at different intervals of time.', FALSE, 3, NULL, NULL),
  ('287eeb0d-8119-57de-85bf-b12c6f4411a3'::uuid, 'b9b99448-4888-512b-a545-be2f55ba8310'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This will enable them to gather a representative sample of data on the subjects’ behavior without having to observe everything the subject does at all times.', FALSE, 4, NULL, NULL),
  ('4dce8543-cafb-53f3-8cf1-87f059a50241'::uuid, 'b9cec247-bcd5-5db1-b150-ba7b86cee84f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The rare and valuable metals and stones found in Middle Eastern deserts have always been in high demand in surrounding areas.', FALSE, 0, NULL, NULL),
  ('906a68d0-6de5-56b3-8aa5-fe352c1b34f4'::uuid, 'b9cec247-bcd5-5db1-b150-ba7b86cee84f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Growing conditions throughout the Middle East are generally poor, forcing Middle Eastern people to depend on imported grain.', FALSE, 1, NULL, NULL),
  ('7977f94b-2622-536c-81e5-2ccf2a7438d5'::uuid, 'b9cec247-bcd5-5db1-b150-ba7b86cee84f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Many useful and decorative raw materials cannot be found naturally in the Middle East but are available from neighboring regions.', TRUE, 2, NULL, NULL);
