  ('49824cc9-1b12-5d51-8165-7cb9516e0df6'::uuid, 'bb5de8bc-d389-5f99-9bb1-ff78adbf7eff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It turns out that those horses are actually feral descendants of the first horses that humans are known to have domesticated, around 5,500 years ago.', FALSE, 0, NULL, NULL),
  ('9e4b9e96-8253-501c-8bc4-4e88d3b0cbf9'::uuid, 'bb5de8bc-d389-5f99-9bb1-ff78adbf7eff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These are startling conclusions of a new genetic study, published in the journal Science, which challenges long-held assumptions about the entwined history of horses and humanity.', FALSE, 1, NULL, NULL),
  ('d9830802-925c-5fba-9724-ab13151383e6'::uuid, 'bb5de8bc-d389-5f99-9bb1-ff78adbf7eff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A Mongolian horse that has long been hailed as the last truly wild horse species in existence isn''t really all that wild.', FALSE, 2, NULL, NULL),
  ('635a2ed4-1d9a-575d-b757-b61d2daaa074'::uuid, 'bb5de8bc-d389-5f99-9bb1-ff78adbf7eff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'That means humans must have tamed wild horses once again later on, somewhere else, but no one knows where or when.', FALSE, 3, NULL, NULL),
  ('eafd82b0-c7f1-5761-adbe-2b2385558f1e'::uuid, 'bb5de8bc-d389-5f99-9bb1-ff78adbf7eff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'What''s more, the modern horses that people ride today cannot be traced to those early steeds.', FALSE, 4, NULL, NULL),
  ('e8ee2f3b-e085-5e0a-9820-2e5a76333485'::uuid, 'bbcde047-d016-52df-81f4-cdbb1f0db99b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'whose', FALSE, 0, 0, NULL),
