  ('61516131-7a3a-55c7-9ddb-615f3139ea44'::uuid, 'bc710c5c-b098-5b03-8d52-e29a44fffb66'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'When they surveyed the same group five years later, most of the teenagers were eating fewer fruits and vegetables.', FALSE, 0, NULL, NULL),
  ('f331405c-bc45-587f-b6ac-94c67797454b'::uuid, 'bc710c5c-b098-5b03-8d52-e29a44fffb66'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Researchers surveyed more than 2,000 young people about their eating habits in 1999.', FALSE, 1, NULL, NULL),
  ('685d3236-4752-52a0-b820-23925cefadba'::uuid, 'bc710c5c-b098-5b03-8d52-e29a44fffb66'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The first occurred in early adolescence, when consumption went down by more than half a serving. The second came in late adolescence and was about the same size as the first.', FALSE, 2, NULL, NULL),
  ('c4d0efa0-f890-50de-a9d1-5e1761934218'::uuid, 'bc710c5c-b098-5b03-8d52-e29a44fffb66'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The researchers, led by Nicole I. Larson of University of Minnesota School of Public Health, found two dips in the intake of fruits and vegetables during the teenage years.', FALSE, 3, NULL, NULL),
