  ('22fcc179-167f-56cc-9b61-6e687db6f8fb'::uuid, 'bdbed5ea-3246-55a5-8468-c0078364d68c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The receiving unit of this system formed monochrome, which is black-and-white images, through the usual cathode-ray tube.', FALSE, 0, NULL, NULL),
  ('93547dd0-49c7-5413-99b6-63c9ab51cab0'::uuid, 'bdbed5ea-3246-55a5-8468-c0078364d68c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In the first color system, a motor-driven disk with segments in three primary colors—red, blue, and green—rotated behind the camera lens, filtering the light from the subject.', FALSE, 1, NULL, NULL),
  ('b64628ec-5f3a-58a7-b392-151b66acb34e'::uuid, 'bdbed5ea-3246-55a5-8468-c0078364d68c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This method is said to be field-sequential because the monochrome image is painted first in one color, then another, and finally in the third, in rapid enough succession so that the individual colors are blended by the retentive capacities of the eye, giving the viewer the impression of a full colored image.', FALSE, 2, NULL, NULL),
  ('91b989f6-113c-5de0-8f91-f28f293cbb78'::uuid, 'bdbed5ea-3246-55a5-8468-c0078364d68c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Several systems of color television have been developed.', FALSE, 3, NULL, NULL),
