  ('dc9bceb3-a30c-5820-890e-dc4d474fdb31'::uuid, 'bde71381-2199-5855-8613-9003828fc472'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Fear conditioning is an associative learning process by which we learn through repeated experiences to fear something.', FALSE, 0, NULL, NULL),
  ('15b24d37-b5c9-58b0-b953-6e23d7a6f252'::uuid, 'bde71381-2199-5855-8613-9003828fc472'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The amygdala is involved in autonomic responses associated with fear and hormonal secretions.', FALSE, 1, NULL, NULL),
