  ('b3a919eb-45cc-597b-a200-1fbb4ce89926'::uuid, 'bde71381-2199-5855-8613-9003828fc472'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For example, when we hear an unpleasant sound, the amygdala heightens our perception of the sound.', FALSE, 3, NULL, NULL),
