  ('6b3b7577-7abd-5d26-b307-caa80034867b'::uuid, 'beb756d9-2709-5a7d-9cee-8c1ff4134822'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'bringing the situation to the attention of the public', TRUE, 1, NULL, NULL),
  ('ec14f17e-947c-5c73-ba05-991cfbb5935b'::uuid, 'beb756d9-2709-5a7d-9cee-8c1ff4134822'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'making use of their own experience of poverty', FALSE, 2, NULL, NULL),
  ('cfaa293e-ed1f-5392-b4af-83364fc70477'::uuid, 'beb756d9-2709-5a7d-9cee-8c1ff4134822'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'helping the poor to gain agood education', FALSE, 3, NULL, NULL),
  ('d2697754-032d-5e23-a2e8-71d63104bb8c'::uuid, 'bee8a860-d6f5-559d-b703-1fab86c25f57'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Even today, World War I is remembered as a tragic event that ushered in a century of profound geopolitical changes.', FALSE, 0, NULL, NULL),
  ('752d368f-d6d1-5a1d-adc2-f65108bdb83b'::uuid, 'bee8a860-d6f5-559d-b703-1fab86c25f57'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Consequently, the war led to significant political changes and the redrawing of national borders.', FALSE, 1, NULL, NULL),
  ('8d3e1dd9-2f2e-5877-ae97-f5778398962d'::uuid, 'bee8a860-d6f5-559d-b703-1fab86c25f57'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The First World War, from 1914 to 1918, was a global conflict that reshaped the world''s political landscape.', FALSE, 2, NULL, NULL),
  ('a096cb4c-42bb-5703-9962-f11147896462'::uuid, 'bee8a860-d6f5-559d-b703-1fab86c25f57'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Triggered by the assassination of Archduke Franz Ferdinand, it involved most world powers.', FALSE, 3, NULL, NULL),
  ('909b9a81-5b0d-51d0-bad6-84c6276892e4'::uuid, 'beedf629-1c5c-55fb-8729-31903a672628'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Trade unions were legalized in an Act of 1871, and by the end of the century more than one and a half million workers were members. Conditions for workers slowly improved over the years, but it wasn’t until 1974 that legislation covering the health and safety of all employees was introduced.', FALSE, 0, NULL, NULL),
  ('b0a29255-9d85-5f56-8e54-97c12718f652'::uuid, 'beedf629-1c5c-55fb-8729-31903a672628'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Until the 19th century, workers were given little or no protection. Child labor was common, as were long hours worked in unsafe conditions for minimal pay.', FALSE, 1, NULL, NULL),
  ('aad854fa-5091-571b-92dd-a73bdb9fe81a'::uuid, 'beedf629-1c5c-55fb-8729-31903a672628'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In the late 18th century, groups of skilled workers began to control the hiring of apprentices, and bargained with employers for better working conditions, but, as the movement grew, these trade unions tried to find ways of creating an alliance among themselves.', FALSE, 2, NULL, NULL),
  ('8c1e7118-c72f-5e2c-a05f-360b70907d36'::uuid, 'beedf629-1c5c-55fb-8729-31903a672628'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The first meeting of the Trades Union Congress took place in Manchester, at which thirty-four delegates represented well over a hundred thousand trade union members.', FALSE, 3, NULL, NULL),
  ('4a3741f4-c595-5c60-a545-09568cc46b37'::uuid, 'bef79762-d216-5f70-a01c-3e100f5f41e2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They go to work very early, from 7:00 to 8:00.', FALSE, 0, NULL, NULL),
  ('ea381334-0817-5047-8d71-af34e09b4bc6'::uuid, 'bef79762-d216-5f70-a01c-3e100f5f41e2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Many managers find the employee''s performance column is decreasing.', FALSE, 1, NULL, NULL),
  ('310f4d2c-a78c-5888-a883-55ba79ab48c4'::uuid, 'bef79762-d216-5f70-a01c-3e100f5f41e2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Because of great demand, more and more employees are putting themselves into limit.', FALSE, 2, NULL, NULL),
  ('09f30522-4939-572c-b7b5-786a409814f2'::uuid, 'bef79762-d216-5f70-a01c-3e100f5f41e2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They (managers) should avoid this phenomenon, because this is not good for the company.', FALSE, 3, NULL, NULL),
  ('c2b35a7c-c938-569f-8aa2-b5b0bd6ec508'::uuid, 'bef79762-d216-5f70-a01c-3e100f5f41e2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'And they went home very late, some even overwork.', FALSE, 4, NULL, NULL),
