  ('86161991-cbad-5da1-8569-3c4078c355d3'::uuid, 'bf754551-5ae8-5594-8716-54f9abf5e690'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There is a growing consensus that, if serious action is to be taken to reduce greenhouse gas (GHG) emissions in Canada, a price must be applied to those emissions.', FALSE, 0, NULL, NULL),
  ('96a5ffb1-4ab3-5141-adb6-11cd33826380'::uuid, 'bf754551-5ae8-5594-8716-54f9abf5e690'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'If Canada implements a carbon price on its own, there are worries that Canadian factories will relocate to other countries to avoid the regulation.', FALSE, 1, NULL, NULL),
  ('c80ef140-9687-56df-874b-02091015fecf'::uuid, 'bf754551-5ae8-5594-8716-54f9abf5e690'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There are, however, challenges associated with the political acceptability of carbon pricing.', FALSE, 2, NULL, NULL),
  ('98e7392b-d8b8-56ee-9303-dbc1729ec138'::uuid, 'bf754551-5ae8-5594-8716-54f9abf5e690'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Even if other countries act in concert with Canada to price carbon, the effects will be uneven across sectors, and lobbying efforts by relatively more-affected sectors might threaten the political viability of the policy.', FALSE, 3, NULL, NULL),
