  ('1a616d4a-33f7-5eee-b651-073358908ea6'::uuid, 'c0e2dc50-87a7-5751-afb9-c03831fe518e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The sequence in which they migrate correlates with their body size.', FALSE, 0, NULL, NULL),
  ('edf1574a-6431-5a6a-b839-3300cbbd69a7'::uuid, 'c0e2dc50-87a7-5751-afb9-c03831fe518e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The differences in feeding preferences lead, in turn, to differences in migratory habits.', FALSE, 1, NULL, NULL),
