  ('3409913d-09d4-509b-8031-c809f8502ed0'::uuid, 'c160bfe4-ecda-58c5-ac16-829c94b913b0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'And the ancient Chinese and Egyptians are also known to have used chemical pest control.', FALSE, 0, NULL, NULL),
  ('e5c71cd8-b41f-5fc4-9c5d-0c26184e19ef'::uuid, 'c160bfe4-ecda-58c5-ac16-829c94b913b0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Chemical pest control dates back 4,500 years, when the Sumerians used sulfur compounds as insecticides.', FALSE, 1, NULL, NULL),
  ('67f8edef-b346-5b70-b151-5d2bfa8c35d0'::uuid, 'c160bfe4-ecda-58c5-ac16-829c94b913b0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Rig Veda, which is about 4,000 years old, also mentions the use of poisonous plants for pest control.', FALSE, 2, NULL, NULL),
  ('47f26cdb-1121-5088-b160-1957d7cc8de8'::uuid, 'c160bfe4-ecda-58c5-ac16-829c94b913b0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But it was only with the industrialization and mechanization of agriculture in the 18th and 19th centuries, and the introduction of the insecticides pyrethrum and derris that chemical pest control became the method of choice.', FALSE, 3, NULL, NULL),
