  ('c9a936cf-de65-55a5-83fa-fd7018f39d4e'::uuid, 'c18cb8fe-63ad-59c2-938b-5c38409594fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Humans evolved that way because changes in the climate 200,000 years ago that demanded that they travel long distances for food and water.', FALSE, 0, NULL, NULL),
  ('4bf5ecc1-9faf-5268-a5d2-7f75f6551d93'::uuid, 'c18cb8fe-63ad-59c2-938b-5c38409594fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Although there are other mammals that are hairless, humans are the only primates to have mostly naked skin.', FALSE, 1, NULL, NULL),
  ('a099dd03-9d2b-5d18-bd16-c6d95943c857'::uuid, 'c18cb8fe-63ad-59c2-938b-5c38409594fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Humans also have an abundance of sweat glands, called eccrine glands.', FALSE, 2, NULL, NULL),
  ('30f4e024-49ac-55f4-abed-b53967919760'::uuid, 'c18cb8fe-63ad-59c2-938b-5c38409594fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This enabled them to obtain the food they needed to nourish their bodies and brains, while keeping them at the right temperature and allowing them to grow.', FALSE, 3, NULL, NULL),
  ('3613f3ba-174c-5e4c-a82a-ec6add894cf2'::uuid, 'c18cb8fe-63ad-59c2-938b-5c38409594fe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To make these glands more efficient, human bodies had to lose their hair to better dissipate heat.', FALSE, 4, NULL, NULL),
