  ('65305c27-a15c-5dd9-9c67-17f31776a51d'::uuid, 'c1d3b71c-57fb-562a-983a-acb7bf8e8778'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Normally in Delhi, September is a month of almost equatorial fertility and the land seems refreshed and newly-washed.', FALSE, 0, NULL, NULL),
