  ('ff34da67-fcc3-54f3-a68f-72a311f61374'::uuid, 'c4ad8ab4-f36f-5f5b-88f3-d1fe292b2e19'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'existed', TRUE, 1, NULL, 1),
  ('28519e08-7895-5cf8-869f-6d9681c2e12e'::uuid, 'c4ad8ab4-f36f-5f5b-88f3-d1fe292b2e19'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'performed', FALSE, 2, NULL, NULL),
  ('57b2582e-d380-564e-9a19-b28e431bfbb9'::uuid, 'c4ad8ab4-f36f-5f5b-88f3-d1fe292b2e19'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'challenged', TRUE, 3, NULL, 0),
  ('bf43ebfd-3e1f-5019-9cd2-07daca942dfe'::uuid, 'c4ad8ab4-f36f-5f5b-88f3-d1fe292b2e19'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'prompted', FALSE, 4, NULL, NULL),
  ('1d6a5ce5-6be9-50ee-9c1e-647addf1494a'::uuid, 'c4ad8ab4-f36f-5f5b-88f3-d1fe292b2e19'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'distinct', TRUE, 5, NULL, 2),
  ('8f38ecfb-f418-52f1-a70e-c9726f70f741'::uuid, 'c4c4299d-d2de-5eb3-b72e-d52b8980030b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The traveler on foot, on the other hand, lives constantly in the present.', FALSE, 0, NULL, NULL),
  ('3b2a876b-96be-503a-bdb9-b07dc8dc8463'::uuid, 'c4c4299d-d2de-5eb3-b72e-d52b8980030b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'By traveling like this, you suspend all experience; the present ceases to be a reality: you might just as well be dead.', FALSE, 1, NULL, NULL),
  ('e5135cc5-eecb-5c05-a0b7-300300bd92cf'::uuid, 'c4c4299d-d2de-5eb3-b72e-d52b8980030b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For him traveling and arriving are one and the same thing: he arrives somewhere with every step he makes. He experiences the present moment with his eyes, his ears and the whole of his body.', FALSE, 2, NULL, NULL),
  ('a4d2651d-cb51-5965-8ece-36a6a9cbfc56'::uuid, 'c4c4299d-d2de-5eb3-b72e-d52b8980030b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But actual arrival, when it is achieved, is meaningless. You want to move on again.', FALSE, 3, NULL, NULL),
  ('5fca90cf-4c7d-53ec-9894-dd3a18925801'::uuid, 'c4c4299d-d2de-5eb3-b72e-d52b8980030b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'When you travel at high speeds, the present means nothing: you live mainly in the future because you spend most of your time looking forward to arriving at some other place.', FALSE, 4, NULL, NULL),
  ('52ca3bf5-8fdf-5d3b-a3ba-900ef4af12f2'::uuid, 'c4db293e-1234-5c07-8d04-92fd7d75c856'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'diluted', TRUE, 0, NULL, 3),
  ('9ab79f10-fb4b-522e-811a-1c4163fede69'::uuid, 'c4db293e-1234-5c07-8d04-92fd7d75c856'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'turn', TRUE, 1, NULL, 2),
  ('14e18ea4-a32b-5a25-8016-29cf8b01d0c3'::uuid, 'c4db293e-1234-5c07-8d04-92fd7d75c856'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'concur', FALSE, 2, NULL, NULL),
  ('6195e20c-b0cf-5112-9060-b55688397042'::uuid, 'c4db293e-1234-5c07-8d04-92fd7d75c856'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'from', FALSE, 3, NULL, NULL),
  ('42ec8f02-8786-5172-988f-3ffc74dfa0a8'::uuid, 'c4db293e-1234-5c07-8d04-92fd7d75c856'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'relish', TRUE, 4, NULL, 1),
  ('82565a2b-8539-5469-9087-2c95ce3c70d0'::uuid, 'c4db293e-1234-5c07-8d04-92fd7d75c856'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'implemented', FALSE, 5, NULL, NULL),
  ('77fcde04-db27-531e-b82e-c384900d27b9'::uuid, 'c4db293e-1234-5c07-8d04-92fd7d75c856'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'since', TRUE, 6, NULL, 0),
  ('23a36e99-e787-5561-b6a5-bae50af18a6d'::uuid, 'c4db293e-1234-5c07-8d04-92fd7d75c856'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'cease', FALSE, 7, NULL, NULL),
  ('a31f08d5-85cd-5359-9db6-c303462db638'::uuid, 'c503143b-b1e1-56a7-a0eb-91eee740b493'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This explosion is already freeing vast numbers of people from their traditional bondage to nature, and now at last we have it in our power to free mankind once and for all from the fear which is based on want.', FALSE, 0, NULL, NULL),
  ('2b5feafa-93dc-5437-baca-647f9dfce2e0'::uuid, 'c503143b-b1e1-56a7-a0eb-91eee740b493'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Now, for the first time, man can reasonably begin to think that life can be something more than a grim struggle for survival.', FALSE, 1, NULL, NULL),
  ('53253a40-de3c-5b27-a3eb-974eb744108e'::uuid, 'c503143b-b1e1-56a7-a0eb-91eee740b493'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Science and technology have come to pervade every aspect of our lives and, as a result, society is changing at a speed which is quite unprecedented.', FALSE, 2, NULL, NULL),
  ('52bd4554-c9f2-515e-9dab-faa18348f7b3'::uuid, 'c503143b-b1e1-56a7-a0eb-91eee740b493'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There is a great technological explosion around us, generated by science.', FALSE, 3, NULL, NULL),
  ('6d1a565e-44de-5a2f-ab78-82c1a1421329'::uuid, 'c529070c-a742-5363-80e2-e2a0cccdf9ce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'discard', FALSE, 0, NULL, NULL),
  ('7b255909-3ac0-5655-9257-67dd6ec1be87'::uuid, 'c529070c-a742-5363-80e2-e2a0cccdf9ce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'amount', FALSE, 1, NULL, NULL),
  ('9ee296f8-bb14-5fe6-b417-1f6681de17d3'::uuid, 'c529070c-a742-5363-80e2-e2a0cccdf9ce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'containing', FALSE, 2, NULL, NULL),
  ('e3050012-193c-5618-83b5-673463c2d63b'::uuid, 'c529070c-a742-5363-80e2-e2a0cccdf9ce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'discharging', TRUE, 3, NULL, 0),
  ('804f9946-22e8-53b5-bb44-12979b0b9221'::uuid, 'c529070c-a742-5363-80e2-e2a0cccdf9ce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'mechanisms', TRUE, 4, NULL, 1),
  ('a4120554-d82e-5661-aaa3-7d4b4de5b0bb'::uuid, 'c529070c-a742-5363-80e2-e2a0cccdf9ce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'untangle', TRUE, 5, NULL, 2),
  ('45513c10-a026-5575-ae81-833060b9c1d2'::uuid, 'c529070c-a742-5363-80e2-e2a0cccdf9ce'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'characteristic', TRUE, 6, NULL, 3),
  ('264c9f6b-a43d-5769-8971-82390f2ebaa9'::uuid, 'c53bea5b-927f-5212-9734-fba30ed08a34'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But stress management is not one-size-fits-all. That’s why it’s important to experiment and find out what works best for you.', FALSE, 0, NULL, NULL),
  ('37c34893-4328-54a1-bb8d-ef07b8c272d8'::uuid, 'c53bea5b-927f-5212-9734-fba30ed08a34'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It may seem like there’s nothing you can do about stress.', FALSE, 1, NULL, NULL),
  ('784b9214-e02a-532c-95e7-afff089af60f'::uuid, 'c53bea5b-927f-5212-9734-fba30ed08a34'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Effective stress management helps you break the hold stress has on your life, so you can be happier, healthier, and more productive.', FALSE, 2, NULL, NULL),
  ('9ac641e3-be97-5a19-9e4d-4100cbe130dc'::uuid, 'c53bea5b-927f-5212-9734-fba30ed08a34'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The bills won’t stop coming, there will never be more hours in the day, and your work and family responsibilities will always be demanding.', FALSE, 3, NULL, NULL),
  ('aac5d769-cb27-5e56-b509-f1ea06549273'::uuid, 'c53bea5b-927f-5212-9734-fba30ed08a34'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But you have a lot more control than you might think.', FALSE, 4, NULL, NULL),
  ('5426e7c4-6b23-50c7-89a3-3cb6d3f4e885'::uuid, 'c5735982-0671-5731-b2c9-486021b8ef4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'falls', FALSE, 0, 0, NULL),
  ('7cb114a0-35c3-5b47-a8db-36c706fa72cd'::uuid, 'c5735982-0671-5731-b2c9-486021b8ef4b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'depends', FALSE, 1, 0, NULL),
