  ('5f38ee56-fbeb-5c1e-8b2e-760ff40220b3'::uuid, 'c632b66d-1591-51ae-a149-2681eb7ef791'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Language originated as a means for early humans to communicate and survive.', FALSE, 0, NULL, NULL),
  ('29b0b84d-f8f6-5713-8b88-d6f198f3fec6'::uuid, 'c632b66d-1591-51ae-a149-2681eb7ef791'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, globalization is now causing a decline in language diversity, as dominant languages overshadow smaller ones.', FALSE, 1, NULL, NULL),
  ('b6fd5216-5abc-57c8-87b9-58887796e81b'::uuid, 'c632b66d-1591-51ae-a149-2681eb7ef791'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This evolution was driven by geographical, social, and cultural factors.', FALSE, 2, NULL, NULL),
  ('daf1fa7b-db3a-5daf-b609-9ab281e092fd'::uuid, 'c632b66d-1591-51ae-a149-2681eb7ef791'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As societies evolved, languages diversified, leading to the rich linguistic tapestry we see today.', FALSE, 3, NULL, NULL),
  ('eaa4d573-b9cc-533e-a63e-4251e58c8938'::uuid, 'c6399c55-a7e4-5d47-82da-eb5ccb4a5073'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For beginners, that may be a light jog or a dance class, and for more advanced exercisers, that could look like a sweat-fest in the gym.', FALSE, 0, NULL, NULL),
  ('e9ddbf36-5adb-5630-b633-29285c76e9ed'::uuid, 'c6399c55-a7e4-5d47-82da-eb5ccb4a5073'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'On the contrary, exercising should be enjoyable and include a level of effort you’re able to give at that particular time.', FALSE, 1, NULL, NULL),
  ('b1df8576-71ec-520b-9d7b-1ed338cf0bb1'::uuid, 'c6399c55-a7e4-5d47-82da-eb5ccb4a5073'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'You’ve heard it from your fitness-junkie friends, and you’ve heard it on the TV: exercise is good for you.', FALSE, 2, NULL, NULL),
