  ('447d3108-6d34-5b4d-a247-2b5d6577d537'::uuid, 'c69f28f9-c008-5b30-9ae2-8451de883b18'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'His philosophy of nonviolent resistance inspired millions.', FALSE, 0, NULL, NULL),
  ('d9761fdb-ce90-52e6-882c-b8696f6506fe'::uuid, 'c69f28f9-c008-5b30-9ae2-8451de883b18'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Mahatma Gandhi, born in 1869 in India, became the leader of the Indian independence movement against British rule.', FALSE, 1, NULL, NULL),
  ('aad95dcf-e4e4-5c6d-b52a-66208e68f363'::uuid, 'c69f28f9-c008-5b30-9ae2-8451de883b18'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Gandhi''s commitment to nonviolence and his belief in simple living made him a global symbol of peace.', FALSE, 2, NULL, NULL),
  ('23239d02-3b66-5d86-b0db-c383fb28d95b'::uuid, 'c69f28f9-c008-5b30-9ae2-8451de883b18'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'His efforts led to India''s independence in 1947, though he was assassinated shortly after.', FALSE, 3, NULL, NULL),
  ('27d134f1-77d2-584c-8be8-2a107d9e25d3'::uuid, 'c69f28f9-c008-5b30-9ae2-8451de883b18'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Even now, Gandhi''s teachings still continue to influence civil rights movements worldwide.', FALSE, 4, NULL, NULL),
