  ('f113f4e1-e194-5220-a945-31fe6316866b'::uuid, 'c6f20f07-699d-5dcd-ba57-ec2aa169b296'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'category', FALSE, 6, NULL, NULL),
  ('5342ee8b-019f-5372-b3d5-9bd0afe462cb'::uuid, 'c714a3db-37d9-5d01-a8af-ea25eb2af07b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Alzheimer’s disease mainly occurs among the old people, who often have difficulties in forming new memories or learning new information. Although there is no cure for this disease, tens of billions of dollars have been spent on its research, giving scientists and physicians hope to cure it in the near future..', FALSE, 0, NULL, NULL),
  ('f82488ba-331c-5f41-bfdc-1eb81f7f9015'::uuid, 'c714a3db-37d9-5d01-a8af-ea25eb2af07b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Scientists haven’t found any evidence that Alzheimer’s disease can directly lead to death, but they suggest that patients suffering from it should live with their family, as they may lose the ability to live independently. The progression of Alzheimer’s disease can be halted, but it damages patients’ brains anyway.', FALSE, 1, NULL, NULL),
  ('2248cd2b-d819-5fc5-bb41-b96c8a1fef55'::uuid, 'c714a3db-37d9-5d01-a8af-ea25eb2af07b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There is still no cure for Alzheimer’s disease, a form of dementia accounting for many deaths worldwide. It damages the neurons in the brain, and slowly changes people’s personality and behavior, and finally the ability to live on their own.', TRUE, 2, NULL, NULL),
  ('b9f536ee-145f-5dd6-bee7-f0b17def0afd'::uuid, 'c714a3db-37d9-5d01-a8af-ea25eb2af07b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Alzheimer’s disease can influence a person’s memories and emotional responses, by damaging the connection between the body and the brain. Around one fifth patients who suffer Alzheimer’s disease eventually die, even with the aid of major drug companies.', FALSE, 3, NULL, NULL),
  ('7fb579d9-1e84-5bcc-bc28-8637b5d7fc8d'::uuid, 'c7468892-5348-5708-bb0d-2c40abb9b114'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'intestine', FALSE, 0, 0, NULL),
