  ('05a004ad-a44b-5030-bdfb-b4e0a574231b'::uuid, 'c785ec29-0e22-5d42-afa6-3aa22a1e4875'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For example, a mechanical ankle brace can improve the metabolic efficiency of human walking, implying that walking is inefficient.', FALSE, 0, NULL, NULL),
  ('6f4dbe1f-0dee-5c53-b2d8-299078df29a3'::uuid, 'c785ec29-0e22-5d42-afa6-3aa22a1e4875'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Long-held assumptions, such as the need for energy efficiency, have already been overturned.', FALSE, 1, NULL, NULL),
  ('b6878905-407d-5f69-a9fe-2ebe77afc97e'::uuid, 'c785ec29-0e22-5d42-afa6-3aa22a1e4875'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Similarly, legged robots struggle to deploy different gaits, just as roboticists struggle to enumerate them.', FALSE, 2, NULL, NULL),
  ('fa8b301c-f495-5f0f-a06d-30749c784e90'::uuid, 'c785ec29-0e22-5d42-afa6-3aa22a1e4875'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But variation of movement is important, too: such an ankle brace holds you back if you try to skip, gallop or skitter.', FALSE, 3, NULL, NULL),
  ('319a0753-c026-52d7-abbe-a89409165a53'::uuid, 'c785ec29-0e22-5d42-afa6-3aa22a1e4875'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Researchers need to understand why different forms of locomotion evolved.', FALSE, 4, NULL, NULL),
  ('b6486058-6b60-57df-8ba5-09a0362f3713'::uuid, 'c7920a1d-e5d3-5df4-8807-3d722b20ce3d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'And they can be helpful to your study as well.', FALSE, 0, NULL, NULL),
  ('2fc56c83-3de0-5014-92aa-a0e11d4584ef'::uuid, 'c7920a1d-e5d3-5df4-8807-3d722b20ce3d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Within the country, there are more than 100 schools in the country providing course and accommodations.', FALSE, 1, NULL, NULL),
  ('3db9ceef-c4f1-5c92-a725-7e1b25c5c00f'::uuid, 'c7920a1d-e5d3-5df4-8807-3d722b20ce3d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Never choose a school without going to the place and having a look. You should go and see once you have a chance.', FALSE, 2, NULL, NULL),
  ('6edc7306-8b4f-5fbf-92ea-7d17c81a4bf0'::uuid, 'c7920a1d-e5d3-5df4-8807-3d722b20ce3d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Because you might be living there.', FALSE, 3, NULL, NULL),
  ('4d484fe4-59e3-5bb4-9b50-d22639e0a1fa'::uuid, 'c7920a1d-e5d3-5df4-8807-3d722b20ce3d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'You can see the facilities and accommodations around the school.', FALSE, 4, NULL, NULL),
  ('1172e986-2e8b-5099-bb42-acec3b8a2e19'::uuid, 'c79682ba-472e-5884-9637-c95113567fe0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The sign above the Academy entrance read: ''Let no-one ignorant of geometry enter here''.', FALSE, 0, NULL, NULL),
  ('89749df0-78dc-56df-923b-2c025eb3f0bd'::uuid, 'c79682ba-472e-5884-9637-c95113567fe0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Although usually remembered today as a philosopher, Plato was also one of ancient Greece''s most important patrons of mathematics.', FALSE, 1, NULL, NULL),
  ('6671f3ef-276f-50f2-998b-5cafbe23f963'::uuid, 'c79682ba-472e-5884-9637-c95113567fe0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In particular, he was convinced that geometry was the key to unlocking the secrets of the universe.', FALSE, 2, NULL, NULL),
  ('af2ed106-c24e-51cd-a099-78470d997b21'::uuid, 'c79682ba-472e-5884-9637-c95113567fe0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Inspired by Pythagoras, he founded his Academy in Athens in 387 BC, where he stressed mathematics as a way of understanding more about reality.', FALSE, 3, NULL, NULL),
