  ('5e1b767a-fa54-5b8a-b92d-79f8eab94024'::uuid, 'c7bb25df-7c17-5696-94ca-88c8673f3025'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Dr. Susan Solomon contributed key findings to understand what was depleting the ozone layer and how to address it.', FALSE, 0, NULL, NULL),
  ('0fe46fb0-5a76-56a6-8fcb-54b5db09daef'::uuid, 'c7bb25df-7c17-5696-94ca-88c8673f3025'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In the 1980s, scientists discovered there was a hole in the ozone over the South Pole.', FALSE, 1, NULL, NULL),
  ('b1784492-37e4-5742-b3fb-fb103c3c0a7c'::uuid, 'c7bb25df-7c17-5696-94ca-88c8673f3025'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The situation was dire. But today, we are on the path to recovery.', FALSE, 2, NULL, NULL),
  ('fc5b8c5c-49db-5510-bdb4-dd7baf01747e'::uuid, 'c7bb25df-7c17-5696-94ca-88c8673f3025'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In a video, she breaks down how we managed to fix this huge problem and shows the unbridled optimism that drove her to fix the ozone hole.', FALSE, 3, NULL, NULL),
  ('97488fe3-da68-55af-a07d-eea0e1686eea'::uuid, 'c7bb25df-7c17-5696-94ca-88c8673f3025'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Projections suggested it would collapse by 2050, increasing skin cancer rates, harming crops, and destroying the marine food chain.', FALSE, 4, NULL, NULL),
  ('fa2b017e-1190-5151-8997-327915a3fe34'::uuid, 'c7c198f7-a7e3-51d9-9552-deac3244e5fc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Native American totem poles are a significant part of indigenous cultures, especially among tribes in the Pacific Northwest, and are intricately carved wooden poles depicting various animals and ancestral figures.', FALSE, 0, NULL, NULL),
  ('a74c375a-6f22-5b00-a8f2-ec2c29cf89a5'::uuid, 'c7c198f7-a7e3-51d9-9552-deac3244e5fc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Additionally, these poles showcase the artistic skills and spiritual beliefs of Native American communities.', FALSE, 1, NULL, NULL),
  ('c943ad71-2559-5765-b50b-5714a73fdeac'::uuid, 'c7c198f7-a7e3-51d9-9552-deac3244e5fc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Thus, totem poles remain a respected and preserved aspect of cultural heritage, symbolizing identity and history.', FALSE, 2, NULL, NULL),
  ('7df2c4bf-cc53-52f4-ae88-c197169102ed'::uuid, 'c7c198f7-a7e3-51d9-9552-deac3244e5fc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Each totem pole tells a story or represents a family''s lineage and social status, created from large trees.', FALSE, 3, NULL, NULL),
