  ('ede29609-cba3-5bf6-a35e-7f24443b4f1e'::uuid, 'c7c763b7-5e07-53f3-9f72-f066d2351cd5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To overcome the pull of gravity and reach another body in space you need to achieve a certain speed.', FALSE, 0, NULL, NULL),
  ('d9e51c83-c6b3-5b15-be86-2a7e69c7c705'::uuid, 'c7c763b7-5e07-53f3-9f72-f066d2351cd5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This is roughly one third of that necessary to reach the International Space Station from Earth.', FALSE, 1, NULL, NULL),
  ('43605dde-7f27-5a2c-8c77-8a469a9950ec'::uuid, 'c7c763b7-5e07-53f3-9f72-f066d2351cd5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A journey to Mars from Earth''s surface requires a minimum total speed of nearly 30,000mph.', FALSE, 2, NULL, NULL),
