  ('40277432-671c-5b52-8cb2-69a2faf36711'::uuid, 'c7fa8b4f-f4f1-547b-bdeb-bc8b6353f5f6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'chance', TRUE, 7, NULL, 2),
  ('d284da44-4c4f-5410-96db-725bb350dc5f'::uuid, 'c8055e80-d18f-5846-84b8-f1dd70e6495f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'He will be told just to sit tight in a certain hotel or bar until someone contacts him. In this way if he is blown, coming through airport customs he cannot unwittingly lead agents to the next link in the chain.', FALSE, 0, NULL, NULL),
  ('29e5afd0-5d46-552c-9eb2-a7b6cce4cb9a'::uuid, 'c8055e80-d18f-5846-84b8-f1dd70e6495f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Although the top men in smuggling business must work together, most of a syndicate''s small fry, especially the mules, know only their immediate contacts. If caught there is little they can give away.', FALSE, 1, NULL, NULL),
  ('a385bac7-a1ab-50d9-bfc1-f7d62fdda30c'::uuid, 'c8055e80-d18f-5846-84b8-f1dd70e6495f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'All the persons at the receiving end do is to hang around the airport among the waiting crowd, and see that the mule comes through safely. If he does not, he is simply written off as a loss.', FALSE, 2, NULL, NULL),
  ('0dea845a-7b22-5a14-8e5f-e4517c414659'::uuid, 'c8055e80-d18f-5846-84b8-f1dd70e6495f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To make identification of mules easier, several syndicates have devised their own "club ties" so that a mule wearing one can immediately be picked out.', FALSE, 3, NULL, NULL),
  ('d59d625f-9442-567a-b1b2-296dbc759f09'::uuid, 'c8055e80-d18f-5846-84b8-f1dd70e6495f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A mule probably will not even know the name of the person who gives him his instructions, nor how to get in touch with him. Usually he even does not know the person to whom he has to make delivery.', FALSE, 4, NULL, NULL),
  ('02ae69ea-ddee-5a66-aa5d-dc7bd1f9026d'::uuid, 'c808372f-ec5b-557c-a9f5-618f2e5a2a64'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'community', FALSE, 0, NULL, NULL),
