  ('11d48234-279a-58bd-8892-a7ffddb912b9'::uuid, 'c896babd-81eb-5400-817e-bef893e982db'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Based on the track record of the past two years, I predict that such discoveries will happen in 2022, yielding drugs that are promising enough to merit a clinical trial.', FALSE, 0, NULL, NULL),
  ('739cddc0-f73f-5a57-9f4e-62868638e9e3'::uuid, 'c896babd-81eb-5400-817e-bef893e982db'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For years, there''s been a ton of hype about AI''s potential to transform drug discovery.', FALSE, 1, NULL, NULL),
  ('2e82ab9c-7300-5de9-b3f6-bbc1f422305d'::uuid, 'c896babd-81eb-5400-817e-bef893e982db'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In 2021, Exscientia followed that up with another drug for patients with tumors.', FALSE, 2, NULL, NULL),
  ('b5ea20e4-fbb2-5b4a-8a85-c8662963ece6'::uuid, 'c896babd-81eb-5400-817e-bef893e982db'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In 2020, a British startup called Exscientia said its new pill for OCD would be the first AI-designed drug to be tested on humans.', FALSE, 3, NULL, NULL),
  ('afab8c57-c71b-52aa-9c7a-6f062823a7a8'::uuid, 'c896bc33-879b-5254-ac47-f82092bb059d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In 1991 the United States Congress asked NASA to investigate the hazard posed today by large impacts on Earth.', FALSE, 0, NULL, NULL),
  ('eada0dd6-47d9-59e9-88a0-e1468b061561'::uuid, 'c896bc33-879b-5254-ac47-f82092bb059d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Earth is a target in a cosmic shooting gallery, subject to random violent events that were unsuspected a few decades ago.', FALSE, 1, NULL, NULL),
  ('09296939-0ecc-5e0f-8c05-6fa10398a9d9'::uuid, 'c896bc33-879b-5254-ac47-f82092bb059d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Although there is always some risk that a large impact could occur, careful study shows that this risk is quite small.', FALSE, 2, NULL, NULL),
