  ('28d494d3-a15d-524a-a910-52e84be3f6c2'::uuid, 'ca017c59-8605-59ff-885b-e5d8f2d561d1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For as long as I can remember, there has been a map in the ticket hall of Piccadilly Circus tube station supposedly showing night and day across the time zones of the world.', FALSE, 0, NULL, NULL),
  ('0b138022-2049-5eef-805e-5c1f2efbcf3b'::uuid, 'ca017c59-8605-59ff-885b-e5d8f2d561d1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But this map has always fascinated me, and still does, even though it now seems very primitive.', FALSE, 1, NULL, NULL),
  ('aeced1ab-bcbe-58a7-8940-ae3f07803915'::uuid, 'ca017c59-8605-59ff-885b-e5d8f2d561d1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This is somewhat surprising given the London Underground''s historic difficulty in grasping the concept of punctuality.', FALSE, 2, NULL, NULL),
