  ('0fb68a67-d246-5fb5-bbcc-0ffe702e9009'::uuid, 'ca2ded19-8b0a-51cd-aab5-e8057224debe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The man who maneuvers carelessly into his five shillings worth of space at one of Europe''s myriad permanent sites may find himself bumping a Bentley.', FALSE, 0, NULL, NULL),
  ('efe8818b-797a-5fa1-8f83-01edfd9b21f7'::uuid, 'ca2ded19-8b0a-51cd-aab5-e8057224debe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'More likely, Ford Consul will be hub to hub with Renault or Mecedes, but rarely with bicycles made for two.', FALSE, 1, NULL, NULL),
  ('f14e60e9-b3f9-5b5a-9277-1ee84851282d'::uuid, 'ca2ded19-8b0a-51cd-aab5-e8057224debe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'That the equipment of modern camping becomes yearly more sophisticated is an entertaining paradox for the cynic, a brighter promise for the hopeful traveler who has sworn to get away from it all.', FALSE, 2, NULL, NULL),
  ('8c3f9583-8a30-5373-9d9f-a989fdc81078'::uuid, 'ca2ded19-8b0a-51cd-aab5-e8057224debe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Economy is one powerful motive for camping, since after the initial outlay upon equipment, or through hiring it, the total expense can be far less than the cost of hotels.', FALSE, 3, NULL, NULL),
