  ('c5ee57f4-1798-5f3e-b4b9-9735fdffc18a'::uuid, 'ca41cdbe-ff00-5413-aa2b-267d3e199a01'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It is a system to help young people work in a profitable company.', FALSE, 1, NULL, NULL),
  ('795d4c28-1474-5f68-9388-1d46e9a0ab82'::uuid, 'ca41cdbe-ff00-5413-aa2b-267d3e199a01'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It is part of the welfare system to help long-term unemployed people.', TRUE, 2, NULL, NULL),
  ('2f07cc05-baf0-5c48-87b6-a4e181d99aaf'::uuid, 'ca41cdbe-ff00-5413-aa2b-267d3e199a01'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It refers to the social assistance system to help farmers find a decent job.', FALSE, 3, NULL, NULL),
  ('60de1ce0-7906-5b31-8f49-6fa28282892a'::uuid, 'ca45870a-a66b-509b-b534-b91b36671648'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'That''s because a group of tiny, colorful birds has been singing the exact same tunes for more than 500,000 years.', FALSE, 0, NULL, NULL),
  ('63076890-f07b-56c2-bd5f-a19775ee0e29'::uuid, 'ca45870a-a66b-509b-b534-b91b36671648'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These colorful, tiny, nectar-feeding birds are called sunbirds.', FALSE, 1, NULL, NULL),
  ('e7665961-5f8f-5a3d-a9fb-5999fcd9b9d4'::uuid, 'ca45870a-a66b-509b-b534-b91b36671648'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The most famous eastern double-collared sunbirds, also known as the "sky island sunbirds," live at the peaks of tall mountains in East Africa from Mozambique to Kenya.', FALSE, 2, NULL, NULL),
  ('545ebce3-b5e5-5855-8282-63b32d320830'::uuid, 'ca45870a-a66b-509b-b534-b91b36671648'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A million years ago, the soundtrack of the "sky island" mountains of East Africa may have been very similar to what it is today.', FALSE, 3, NULL, NULL),
  ('656ea423-07ec-52fe-84d7-5d2018872e90'::uuid, 'ca45870a-a66b-509b-b534-b91b36671648'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They resemble hummingbirds and are common throughout Africa and Asia.', FALSE, 4, NULL, NULL),
  ('8ecf613c-15fb-5ed6-9aa9-b691e71c55ba'::uuid, 'ca5b0bc3-b5bf-5886-bd67-719d7f00631a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They collected the results from 116 scientific studies, 22 of which looked at structural changes in the brain and 100 of which looked at changes in brain functionality and or behavior.', FALSE, 0, NULL, NULL),
  ('03381282-e38b-5c7f-b1f5-36aa76b75cd6'::uuid, 'ca5b0bc3-b5bf-5886-bd67-719d7f00631a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Palaus and his colleagues wanted to see if any trends had emerged from the research to date concerning how video games affect the structure and activity of our brains.', FALSE, 1, NULL, NULL),
  ('58632560-a70c-5472-9f54-629c50a7f1ee'::uuid, 'ca5b0bc3-b5bf-5886-bd67-719d7f00631a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For example, playing video games affects our attention, and some studies found that gamers show improvements in several types of attention, such as sustained attention or selective attention.', FALSE, 2, NULL, NULL),
  ('554c93b6-ef25-5ab1-b398-f86f98e3c40f'::uuid, 'ca5b0bc3-b5bf-5886-bd67-719d7f00631a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The studies show that playing video games can change how our brains perform, and even their structure.', FALSE, 3, NULL, NULL),
  ('2bfaea25-7c5e-5ba6-8497-8537dcec2b1b'::uuid, 'ca8afe53-6335-59b4-b40a-1eb19e35bdbf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The first founders of Granta were Cambridge University students in 1899.', FALSE, 0, NULL, NULL),
  ('b9522287-30a5-5079-b126-8db60ac217b6'::uuid, 'ca8afe53-6335-59b4-b40a-1eb19e35bdbf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Until now, Granta has published 27 Nobel Prize winners.', FALSE, 1, NULL, NULL),
  ('a7431b14-52a5-56fb-a78a-84c8b375fcde'::uuid, 'ca8afe53-6335-59b4-b40a-1eb19e35bdbf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Granta is a literary magazine based in the United Kingdom.', FALSE, 2, NULL, NULL),
  ('46c770a0-fddd-5999-9f8c-c3a16a26952e'::uuid, 'ca8afe53-6335-59b4-b40a-1eb19e35bdbf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In addition, Granta has published authors who have won literary prizes including the Booker Prize, the Whitbread Prize, the Forward Prize, the T.S. Eliot Prize, and the Pushcart Prize.', FALSE, 3, NULL, NULL),
