  ('e30689d4-efb5-5d50-8cd9-0733218c1e20'::uuid, 'cb06453d-ce64-536e-83f7-9168419acae8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'dissonant', FALSE, 23, 5, NULL),
  ('aae8fa40-e8f7-5eac-b2e4-0e9ad30f8bc2'::uuid, 'cb0bc038-9320-5045-a4cc-12f080e15b12'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In Montana as elsewhere, companies that have acquired older mines respond to demands to pay for cleanup in either of two ways.', FALSE, 0, NULL, NULL),
  ('78834c45-dbe2-562e-a917-7c689f3b1d1b'::uuid, 'cb0bc038-9320-5045-a4cc-12f080e15b12'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'If the company is so large that it cannot claim that it would be bankrupted by cleanup costs (as in the case of ARCO that I shall discuss below), the company instead denies its responsibility or else seeks to minimize the costs.', FALSE, 1, NULL, NULL),
  ('7d69b639-bb43-5783-bdbd-35aaf65ba891'::uuid, 'cb0bc038-9320-5045-a4cc-12f080e15b12'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Especially if the company is small, its owners may declare the company bankrupt, in some cases conceal its assets, and transfer their business efforts to other companies or to new companies that do not bear responsibility for cleanup at the old mine.', FALSE, 2, NULL, NULL),
  ('fae0ae30-8c27-5954-b7c6-23c21f80a296'::uuid, 'cb0bc038-9320-5045-a4cc-12f080e15b12'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In either case, either the mine site and areas downstream of it remain toxic, thereby endangering people, or else the U.S. federal government and the Montana state government (hence ultimately all taxpayers) pay for the cleanup through the federal Superfund and a corresponding Montana state fund.', FALSE, 3, NULL, NULL),
  ('28244905-cccc-58ff-bb5a-3aeacb840c90'::uuid, 'cb26567e-b17c-5ed2-9a49-a53aae28d8c1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'is driven by', TRUE, 0, 0, NULL),
