  ('5788c8c5-05ed-5c13-bfd8-e617c1f6df2e'::uuid, 'cbe360e6-6ad6-5c91-bb60-b6b397ed42ff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Most Americans talk about electric vehicles solely as modes of transport — which is understandable, given they have motors and wheels and get us around.', FALSE, 0, NULL, NULL),
  ('019a1bf2-49dc-5348-8cb0-631943cc78d4'::uuid, 'cbe360e6-6ad6-5c91-bb60-b6b397ed42ff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Done right, integrating electric vehicles into American society could help prevent power blackouts, and make solar and wind energy more reliable sources of power for more people.', FALSE, 1, NULL, NULL),
  ('bd77654c-6c62-513f-b01e-301674386f23'::uuid, 'cbe360e6-6ad6-5c91-bb60-b6b397ed42ff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The first step is to stop thinking about electric vehicles as cars that happen to be powered by batteries, and instead see them as batteries that happen to be inside cars.', FALSE, 2, NULL, NULL),
  ('95606e08-ad68-51b6-af5e-04d28b4f30d7'::uuid, 'cbe360e6-6ad6-5c91-bb60-b6b397ed42ff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But they are so much more than cars: they‘re batteries, and batteries have uses far beyond transport.', FALSE, 3, NULL, NULL),
  ('5882d5f8-f77d-5c9a-a367-12618fac737f'::uuid, 'cbfa11aa-1581-51eb-96f7-992bd5bb38ca'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'therefore', FALSE, 0, 0, NULL),
