  ('23a51dfa-290a-5abd-a92f-bfe9df596e9d'::uuid, 'cc0b9686-6fa4-5629-bf24-0cc3701e3f62'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'whether', FALSE, 15, 3, NULL),
  ('4a7920ae-faa6-5245-95ee-df38b835e5aa'::uuid, 'cc1894e2-ecda-5a52-85a1-2435493c82bc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But what Darwin rightly recognized is that - panda fans avert your eyes - worm conservation is much more important once we factor in their provision of what we now call "ecosystem services", which are crucial to human survival.', FALSE, 0, NULL, NULL),
  ('6feb05e4-d7b0-509d-8dde-21b572248c21'::uuid, 'cc1894e2-ecda-5a52-85a1-2435493c82bc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Not all wildlife is created equal in our eyes.', FALSE, 1, NULL, NULL),
  ('095bb7c5-dd42-5f2a-b72c-eea1f1b21e88'::uuid, 'cc1894e2-ecda-5a52-85a1-2435493c82bc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Take the earthworm, which doesn''t have the widespread appeal of larger, more charismatic animals such as gorillas, tigers or pandas.', FALSE, 2, NULL, NULL),
  ('4524439f-1133-5d52-81ed-53bb5de1acbf'::uuid, 'cc1894e2-ecda-5a52-85a1-2435493c82bc'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Worms are never going to get a strong "cute response", and they won''t ever be the face of a conservation campaign.', FALSE, 3, NULL, NULL),
  ('58730f86-1a69-5f01-9aa8-0003b87115ae'::uuid, 'cc21183d-78e8-541c-bbbf-d814e65d7a93'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Additionally, how the Nabataeans carved such elaborate structures directly into the rock is not entirely understood.', FALSE, 0, NULL, NULL),
  ('49772793-ffc3-5249-adf8-3cc1c42ab143'::uuid, 'cc21183d-78e8-541c-bbbf-d814e65d7a93'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Its intricate water conduit system is an engineering marvel.', FALSE, 1, NULL, NULL),
  ('dc437094-b975-59c2-9c6b-c85168e84fdc'::uuid, 'cc21183d-78e8-541c-bbbf-d814e65d7a93'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The purpose of this system remains shrouded in mystery.', FALSE, 2, NULL, NULL),
  ('f73f8a75-5060-5f7d-82f0-84408969bb9b'::uuid, 'cc21183d-78e8-541c-bbbf-d814e65d7a93'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The ancient city of Petra, carved into the rose-red cliffs of Jordan, was the capital of the Nabataean Kingdom.', FALSE, 3, NULL, NULL),
