  ('37dcf80d-51b5-519d-9ec7-a4247dfb9436'::uuid, 'ccf031c1-7419-5c94-9ec7-ca7ac9c59153'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Rosetta Stone was found in an ancient Egyptian temple and there was Latin written on it. Scholars took many years to decipher it and Thomas Young made the first important discovery about it.', FALSE, 0, NULL, NULL),
  ('c97c0577-fe93-56b9-a36d-25eaaeb2e43e'::uuid, 'ccf031c1-7419-5c94-9ec7-ca7ac9c59153'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Some French soldiers found the Rosetta Stone in 1799 and it contained information in three languages. Thomas Young discovered about eighty words in each text that were similar and then Jean-Francois Champollion wrote a grammar and a dictionary of hieroglyphics.', TRUE, 1, NULL, NULL),
  ('925f6e7e-9853-5846-841b-c3a4ab9d9ebe'::uuid, 'ccf031c1-7419-5c94-9ec7-ca7ac9c59153'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The text on the Rosetta Stone became the key to understanding ancient Egyptian hieroglyphics. On it there are eighty words in the Demotic and hieroglyphic texts that were similar to words in ancient Greek. However, scholars were still unable to figure out the alphabet for hieroglyphics.', FALSE, 2, NULL, NULL),
  ('988deb78-14d1-592a-8c42-6e980a842d85'::uuid, 'ccfe9371-99b1-59de-928c-43f5b2951ce0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'subjective', FALSE, 0, 0, NULL),
