  ('d35d6b5c-619a-539f-afdd-3c78f37ef873'::uuid, 'ce5960b5-8465-5457-8192-fab42aec77b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The first Modern Olympics were held two years later in Athens, where 245 athletes from 14 nations competed in the ancient Panathenaic stadium to large and ardent crowds.', FALSE, 0, NULL, NULL),
  ('b4d6bf16-ba12-5866-a664-c161eb64af64'::uuid, 'ce5960b5-8465-5457-8192-fab42aec77b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Americans captured nine out of 12 track and field events, but Greece won most medals with 47.', FALSE, 1, NULL, NULL),
