  ('429a6509-8478-5b3a-b6e0-c9b0e9020fa2'::uuid, 'ce5960b5-8465-5457-8192-fab42aec77b9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The original Olympic Games were celebrated by the Greeks as a religious festival from 776 B.C. until A.D. 393 when Roman emperor Theodosius I banned all pagan festivals (the Olympics celebrated the Greek god Zeus).', FALSE, 4, NULL, NULL),
