  ('51fb4aa3-e6b2-5faa-9e3a-fd97e96e9718'::uuid, 'cf47ee97-a06a-510c-b7b6-6d6c0ccd2bb0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The place that mosquitoes live is dark and mysterious and it also protects them from their predators. However, DDT, an effective way to eliminate mosquitoes, was now banned in many countries.', FALSE, 1, NULL, NULL),
  ('7bd6c8d1-7099-57fe-bfee-d88eeb448e52'::uuid, 'cf47ee97-a06a-510c-b7b6-6d6c0ccd2bb0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The best way to exterminate mosquitoes in high insects environment is the kill their eggs first. They lay their eggs in stagnant water, like in swamps. So draining these areas can control them.', FALSE, 2, NULL, NULL),
  ('8a0677c3-e6ce-5ea1-b02a-b5d19ad36d86'::uuid, 'cf47ee97-a06a-510c-b7b6-6d6c0ccd2bb0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Mosquitoes suck blood from various animals by a long feeder in its mouth to provide them with nourishment. So to control them, DDT, an insect killer, must be used many times to be successful.', FALSE, 3, NULL, NULL),
  ('9ff8b635-aab4-529d-b17e-a307fbedd12e'::uuid, 'cf53930c-acb1-5737-b61e-53fe0560f337'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Its genome evolved from multiple species.', FALSE, 0, NULL, NULL),
