  ('40d3daa9-ddaa-546a-a377-ad51b1d16fce'::uuid, 'cf5f7129-0732-5f1f-af51-58b46780c527'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This innovative technology allows us to capture and store solar energy efficiently, making it available even on cloudy days or during the night.', FALSE, 0, NULL, NULL),
