  ('75e9e1d2-3aae-5739-83d0-2092ed7ee56c'::uuid, 'd071fee3-e829-5e6e-b18f-fad9dbd1fe5f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'When writers are writing long texts, such as long academic essays or dense blog posts, using headings helps them outline how they will organize their argument.', FALSE, 1, NULL, NULL),
