  ('9fb4b30c-e686-5be5-98e0-aa7f28508530'::uuid, 'd0af9482-6c4c-5648-ade4-7e53b4be441e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Even in one province, there can be multiple languages spoken. For example, in Fujian province, you can hear Min, Fuzhounese, and Mandarin being spoken, each being very distinct from the other.', FALSE, 0, NULL, NULL),
  ('027794b0-f223-5dd0-bfe5-625523df379d'::uuid, 'd0af9482-6c4c-5648-ade4-7e53b4be441e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Thus, Mandarin is commonly referred to as ‘Chinese’.', FALSE, 1, NULL, NULL),
  ('c8a3254d-79c6-5473-926d-6d3aa4bc94a6'::uuid, 'd0af9482-6c4c-5648-ade4-7e53b4be441e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Mandarin is the most common language in the world as it is the official language of Mainland China, Taiwan, and one of the official languages of Singapore.', FALSE, 2, NULL, NULL),
  ('5d834eee-b4c7-562a-ab4c-7ee85e883036'::uuid, 'd0af9482-6c4c-5648-ade4-7e53b4be441e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Depending on the region, Chinese people also speak Wu, Hunanese, Jiangxinese, Hakka, Min, and many other languages.', FALSE, 3, NULL, NULL),
  ('e6026a81-02c0-5653-8ba8-92d72b126f6e'::uuid, 'd0af9482-6c4c-5648-ade4-7e53b4be441e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But in fact, it is just one of many Chinese languages.', FALSE, 4, NULL, NULL),
  ('5b879f2b-96e0-5bca-aa10-a08b3cde3005'::uuid, 'd0d7fa05-46dc-57c6-a21b-d880afd8a21e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'One such example is a solar panel which could charge an LED lamp to create hours of light each day.', FALSE, 0, NULL, NULL),
