  ('901b60c2-7971-56ac-9284-576adeb3e6b3'::uuid, 'd16ba184-9c91-5599-b70f-eac091606ce4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Young children don''t possess these qualities and are easily angered, cry frequently and are incapable of understanding the external difficulties facing the community, such as shortages of food.', FALSE, 0, NULL, NULL),
  ('35eaa301-0c2a-506a-848e-d02f6d820c62'::uuid, 'd16ba184-9c91-5599-b70f-eac091606ce4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Jean Briggs has worked with the Inuit of the Canadian Arctic and has described how, within these communities, growing up is largely seen as a process of acquiring thought, reason and understanding (known in Inuit as ihuma).', FALSE, 1, NULL, NULL),
  ('b0a7b480-4eb3-5a5d-a86f-d2a63907fade'::uuid, 'd16ba184-9c91-5599-b70f-eac091606ce4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It’s only when they are older and begin to acquire thought that parents attempt to teach them or discipline them.', FALSE, 2, NULL, NULL),
  ('42ec11f0-daf5-5f42-88c1-118987d456b8'::uuid, 'd16ba184-9c91-5599-b70f-eac091606ce4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Because they can’t be reasoned with, and don’t understand, parents treat them with a great deal of tolerance and leniency.', FALSE, 3, NULL, NULL),
