  ('668c44a7-8ae9-5e83-81cb-d491e487aa1c'::uuid, 'd178a15f-0c84-5b2f-bd32-4854da6b49a4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, its effectiveness can vary depending on the individual''s responsiveness to music.', FALSE, 0, NULL, NULL),
  ('d7ea46f3-155b-5556-a3f5-fa190fef2cc6'::uuid, 'd178a15f-0c84-5b2f-bd32-4854da6b49a4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It can be particularly effective in improving mental health and enhancing quality of life.', FALSE, 1, NULL, NULL),
  ('095c53f6-1690-553a-9494-ffe82a68c21c'::uuid, 'd178a15f-0c84-5b2f-bd32-4854da6b49a4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Music therapy is an established health profession that uses music to address physical, emotional, cognitive, and social needs.', FALSE, 2, NULL, NULL),
  ('9d4c1ae4-22a1-570a-b948-60c464af6552'::uuid, 'd178a15f-0c84-5b2f-bd32-4854da6b49a4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Moreover, music therapy is adaptable to individuals of all ages and various conditions.', FALSE, 3, NULL, NULL),
  ('5684e451-18de-5385-a758-048cbbd49d24'::uuid, 'd182f7fd-2664-59f9-8591-f19c549bbffa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A series of thin nerves run along the shell and detect pressure changes associated with touch.', FALSE, 0, NULL, NULL),
  ('8fc4ffed-0f28-5850-9c3c-5affaab9e19b'::uuid, 'd182f7fd-2664-59f9-8591-f19c549bbffa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In addition, researchers and scuba divers have observed sea turtles respond to the stimulation of being touched on the skin of their head and their flippers.', FALSE, 1, NULL, NULL),
  ('f7551f32-bc8b-5cf0-b519-db8a47665cdc'::uuid, 'd182f7fd-2664-59f9-8591-f19c549bbffa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The nerves do not contain pain receptors so scientists do not think sea turtles feel pain when touched on the shell, but these thin nerves could transmit information to other parts of the sea turtle’s body.', FALSE, 2, NULL, NULL),
  ('e41ecaf6-710b-5375-9491-30a526119dc1'::uuid, 'd182f7fd-2664-59f9-8591-f19c549bbffa'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The bony shell of a sea turtle can actually sense when something touches it.', FALSE, 3, NULL, NULL),
  ('92f46bb1-33ce-51b6-bf7d-e9c489ee0add'::uuid, 'd18ad3c9-87cf-55fc-afff-ed1cb78fc61e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'bravery', TRUE, 0, 0, NULL),
