  ('7d6ca554-e7d0-5454-93ff-dbd2d914fc37'::uuid, 'd1a511c9-8909-5cee-838d-26a44abd3d9d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Photogrammetry involves taking hundreds of photos of an object at slightly different angles and ‘stitching’ them together to create an interactive digital 3D model.', FALSE, 0, NULL, NULL),
  ('33a1b045-5c4f-51fa-bee8-115fabb5a7db'::uuid, 'd1a511c9-8909-5cee-838d-26a44abd3d9d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These artifacts are rarely handled as they are so fragile.', FALSE, 1, NULL, NULL),
  ('04fe3741-e57c-510a-8fab-62f758167aec'::uuid, 'd1a511c9-8909-5cee-838d-26a44abd3d9d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The process is already being used by the University of Aberdeen’s anatomy department to create digital models of organs and other body parts to aid teaching and learning for young doctors.', FALSE, 2, NULL, NULL),
  ('86f661b6-352b-580a-b21c-9d0835b268ee'::uuid, 'd1a511c9-8909-5cee-838d-26a44abd3d9d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Photogrammetry lets the public and students get to see them close-up and in very high detail.', FALSE, 3, NULL, NULL),
  ('d626ea7b-edaf-5a2f-a9b6-0b3bd7944534'::uuid, 'd1a511c9-8909-5cee-838d-26a44abd3d9d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Now the same technology is being used to create virtual replicas of artifacts within the University’s museum’s collections, including an ancient Egyptian mummified cat, prehistoric skulls and ancient Greek pottery.', FALSE, 4, NULL, NULL),
