  ('1b99eb18-3c1e-5ed2-be58-a9ba776b36ba'::uuid, 'd2746336-27ec-599d-8a42-19a502963b0d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Crusades were a series of religious wars sanctioned by the Latin Church in the medieval period, primarily against Muslim territories in the Eastern Mediterranean.', FALSE, 1, NULL, NULL),
  ('2c5f99b9-d6de-5161-9d65-1d2344195799'::uuid, 'd2746336-27ec-599d-8a42-19a502963b0d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Initiated in 1095, they aimed to recapture the Holy Land from Muslim control.', FALSE, 2, NULL, NULL),
  ('873fc39e-6736-5f52-a32f-584454e40007'::uuid, 'd2746336-27ec-599d-8a42-19a502963b0d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, the Crusades still played a significant role in shaping the religious and cultural landscape of the medieval world.', FALSE, 3, NULL, NULL),
  ('61701efb-9e2a-5da8-9d49-46d512610f5c'::uuid, 'd2748e05-ad78-5d85-81f4-ef09ee0c96a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There are insufficient sources of fresh water for human consumption.', FALSE, 0, NULL, NULL),
  ('f552fc3d-6f7a-5a4a-9d84-25fed4451164'::uuid, 'd2748e05-ad78-5d85-81f4-ef09ee0c96a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Industrial pollution can affect both underground and river water.', TRUE, 1, NULL, NULL),
  ('a46eeee6-eb61-5d5c-ae1c-f4bc763ea05e'::uuid, 'd2748e05-ad78-5d85-81f4-ef09ee0c96a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There are numerous means by which water can become impure.', TRUE, 2, NULL, NULL),
  ('f8c5b1a0-8d60-5ebe-ac32-9ac05a490e42'::uuid, 'd2748e05-ad78-5d85-81f4-ef09ee0c96a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Rain is a safer source of water for human consumption than aquifers.', FALSE, 3, NULL, NULL),
  ('629dd9da-9803-5143-909a-9140afe012c5'::uuid, 'd2748e05-ad78-5d85-81f4-ef09ee0c96a6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Water in reservoirs is chemically treated to remove harmful bacteria.', FALSE, 4, NULL, NULL),
