  ('ece059ce-ef16-5468-a46d-40b956a29dbf'::uuid, 'd3f4c413-34da-5c5c-969c-e27eeb1d9195'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To be more specific, the size of the human brain relative to the total weight of the average human is 1-to-50.', FALSE, 1, NULL, NULL),
