  ('2f7aa39f-2030-59ab-a54b-376d033bbc72'::uuid, 'd598e2c3-39ff-536b-aa9b-c423dce47be9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There is a scientific basis for dogs to turn to humans for help.', TRUE, 0, NULL, NULL),
  ('f2a4b541-3803-5731-925c-3f1553122bcb'::uuid, 'd598e2c3-39ff-536b-aa9b-c423dce47be9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Dogs seek help from humans when they encounter problems, and so do wolves.', FALSE, 1, NULL, NULL),
  ('4eb382f0-c171-5ccf-86c9-344e327b31bd'::uuid, 'd598e2c3-39ff-536b-aa9b-c423dce47be9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Babies seek help when they are in trouble.', TRUE, 2, NULL, NULL),
  ('dfa50d6d-19a0-5e91-80db-bb387917f3d9'::uuid, 'd598e2c3-39ff-536b-aa9b-c423dce47be9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Dogs also seek help from other dogs when they feel depressed.', FALSE, 3, NULL, NULL),
  ('83804193-481a-58fc-ae52-cb6b832d8951'::uuid, 'd598e2c3-39ff-536b-aa9b-c423dce47be9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Wolves raised by humans will seek help, while wild wolves will not.', FALSE, 4, NULL, NULL),
