  ('7c701d0a-478a-5efe-b978-0ab48489246b'::uuid, 'd59ea72b-eceb-5b95-9351-a819f8344b30'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The largest bear in the world and the Arctic''s top predator, polar bears are a powerful symbol of the strength and endurance of the Arctic.', FALSE, 0, NULL, NULL),
  ('046f539b-6a59-5957-bb0c-96c774609058'::uuid, 'd59ea72b-eceb-5b95-9351-a819f8344b30'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It''s an apt name for this majestic species, which spends much of its life on the ocean, predominantly on the sea ice.', FALSE, 1, NULL, NULL),
  ('ad717dc9-bb4e-5f80-84e3-e9b320f4e7a7'::uuid, 'd59ea72b-eceb-5b95-9351-a819f8344b30'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But because of the ongoing loss of their sea ice habitat resulting from climate change, polar bears were listed as a threatened species in May 2008.', FALSE, 2, NULL, NULL),
  ('42edd6ef-3ee7-520e-8f41-c3e0edabfb39'::uuid, 'd59ea72b-eceb-5b95-9351-a819f8344b30'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Its Latin name, Ursus maritimus, means "sea bear."', FALSE, 3, NULL, NULL),
