  ('9ee51153-fa68-530e-a992-889ca5fca518'::uuid, 'd63612f3-dbb5-5ce8-9ff6-16a353fbcad0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Students are confused about the effects of the Earth magnetic field. When solar winds reach the Earth’s magnetic field, the electrons in oxygen atoms give off energy. Thus, auroras are the result of solar winds hitting the magnetic field.', FALSE, 0, NULL, NULL),
  ('0ad04b2a-488d-5285-84f9-bd8ef85e4dd5'::uuid, 'd63612f3-dbb5-5ce8-9ff6-16a353fbcad0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Auroras appear as colorful streams of light in the sky in high northern and southern latitudes. They are caused by three things: nitrogen atoms getting excited, solar winds in the Earth''s magnetic field, and electrons in oxygen atoms giving off energy.', TRUE, 1, NULL, NULL),
  ('94155403-a038-503a-b51d-5a0bff86c5e9'::uuid, 'd63612f3-dbb5-5ce8-9ff6-16a353fbcad0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The aurora australis are seen in the Northern Hemisphere in March and November. When nitrogen atoms in the atmosphere get excited, the magnificent green lights appear in the sky.', FALSE, 2, NULL, NULL),
