  ('cdfaab2d-dbc9-5f56-900a-87690b736016'::uuid, 'da19bcd2-1a31-5d55-8096-90fd7a55e503'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'evidence', TRUE, 23, 5, NULL),
