  ('a32ba1ca-0724-5ea9-b062-660f1dae9683'::uuid, 'db99a5dd-b35c-5c53-9a30-95551f56efdf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There you will see how women are consistently portrayed as weak and in need of male protection.', FALSE, 0, NULL, NULL),
  ('2a53713e-d10e-53bb-933d-3ed29430962e'::uuid, 'db99a5dd-b35c-5c53-9a30-95551f56efdf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This acceptance that men were the superior gender had not developed by chance.', FALSE, 1, NULL, NULL),
  ('2130948e-8fcb-5a6b-a582-47001563dd9e'::uuid, 'db99a5dd-b35c-5c53-9a30-95551f56efdf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It had been the view that had been socialized into them from the moment of their birth.', FALSE, 2, NULL, NULL),
  ('71cb11d8-c4b2-5aac-9abc-80561c377c53'::uuid, 'db99a5dd-b35c-5c53-9a30-95551f56efdf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This will become clear if you look at any girls’ magazine or popular film of the period.', FALSE, 3, NULL, NULL),
  ('0caf32d2-0b40-5df2-9e2a-5c9f9eb9fbe7'::uuid, 'db99a5dd-b35c-5c53-9a30-95551f56efdf'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In the 1960s, the greatest obstacle for those who wanted to organize women was said to be women’s conviction that they were actually inferior to men.', FALSE, 4, NULL, NULL),
  ('d5ac7d31-180d-5575-9f7e-6708bce521f0'::uuid, 'dba2df9b-2e75-568e-9245-efac2a257b7c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'We have spent the most time on the phylogenetic tree with them.', FALSE, 0, NULL, NULL),
  ('b3b0d40a-c91c-5a3b-a8a9-97c912216449'::uuid, 'dba2df9b-2e75-568e-9245-efac2a257b7c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The two other living primate species in terms of genetics and morphology are like us the most: the chimpanzee and bonobo.', FALSE, 1, NULL, NULL),
  ('ac00494e-76b8-58c4-8959-0fff8d4add71'::uuid, 'dba2df9b-2e75-568e-9245-efac2a257b7c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Humans have much in common with other mammals on Earth in terms of physiology.', FALSE, 2, NULL, NULL),
