  ('1d7abbbb-321a-5d29-bd9d-c75d573d47ad'::uuid, 'dc41e347-282c-5564-9760-8b626020c044'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, human activities have been causing a significant loss of biodiversity.', FALSE, 0, NULL, NULL),
  ('56bd1523-655e-537f-a6b1-e92043e1320b'::uuid, 'dc41e347-282c-5564-9760-8b626020c044'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Thus, protecting biodiversity is crucial for maintaining ecological balance and the sustainability of life on Earth.', FALSE, 1, NULL, NULL),
  ('c6da79ec-8c63-5e0d-b617-9ac1d81f9a5a'::uuid, 'dc41e347-282c-5564-9760-8b626020c044'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This diversity contributes to the functionality of ecosystems, providing essential services like pollination and nutrient cycling.', FALSE, 2, NULL, NULL),
