  ('aed1a65e-5b21-5eb0-a9a4-ba3849b0093c'::uuid, 'dd170466-9ba3-58f7-a74e-4c515de8761c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'prevalent', TRUE, 7, NULL, 1),
  ('f346589d-4681-5e90-b11c-fb8cdf131283'::uuid, 'dd2d8c54-1732-5f8e-8aa6-81933b034f5b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Laws, he said, are not direct generalizations of experience; they aren’t mere summaries of the points on the graph.', FALSE, 0, NULL, NULL),
  ('61d26c9b-f979-5f72-92a8-3f8ae06c991b'::uuid, 'dd2d8c54-1732-5f8e-8aa6-81933b034f5b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Thus a scientific theory is not directly falsifiable by the data of experience; instead, the falsification process is more indirect.', FALSE, 1, NULL, NULL),
  ('7bb5755f-ffa9-576d-8848-5c8a7327145a'::uuid, 'dd2d8c54-1732-5f8e-8aa6-81933b034f5b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Poincaré had an especially interesting view of scientific induction.', FALSE, 2, NULL, NULL),
  ('5c2214f9-8fc0-5d82-aa31-d27b2375d76c'::uuid, 'dd2d8c54-1732-5f8e-8aa6-81933b034f5b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Rather, the scientist declares the law to be some interpolated curve that is more or less smooth and so will miss some of those points.', FALSE, 3, NULL, NULL),
  ('72eab94c-cb29-5ebc-907f-b31e8e220176'::uuid, 'dd2f8add-b219-5c61-927b-35adf6f2a9f2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Reports of ‘demon cats’, both real and supernatural, were bizarrely commonplace during the 19th century.', FALSE, 0, NULL, NULL),
  ('70938bd8-3c3d-5a33-b5eb-e3d623011920'::uuid, 'dd2f8add-b219-5c61-927b-35adf6f2a9f2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In Japan, for example, ‘bakneko’ legends depicted revenge-hungry cats that behaved like humans.', FALSE, 1, NULL, NULL),
  ('d059b7d8-5be4-5f76-a790-e6ae5d475e84'::uuid, 'dd2f8add-b219-5c61-927b-35adf6f2a9f2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Scholars used to attribute the ubiquity of these tales to cats’ bodies and behavior, from their otherworldly sounds to their nocturnal habits and glowing eyes.', FALSE, 2, NULL, NULL),
  ('6fae447a-40f0-5784-b5a3-14e013c1517e'::uuid, 'dd2f8add-b219-5c61-927b-35adf6f2a9f2'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In fact, cat-related mythology dates back centuries around the world.', FALSE, 3, NULL, NULL),
  ('fefaeb3c-1300-52d1-b22e-919e3f0e133f'::uuid, 'dd32bbf9-5f23-5a9c-87b7-e9cc92c19fef'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'admit', FALSE, 0, NULL, NULL),
