  ('4f6fc33a-46cb-50c2-a1eb-f9bef45c9f6d'::uuid, 'df49c72b-84bf-59de-a022-c74f49f23c2d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'New Jay felt disrespected when his student Ann was late for his class. Despite the fact that Ann had already explained why she was late, New Jay was still angry and told her not to come to his class at all if she was late again.', FALSE, 0, NULL, NULL),
  ('22b21484-c79d-52e5-b939-025d5ad26c50'::uuid, 'df49c72b-84bf-59de-a022-c74f49f23c2d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Ann’s teacher New Jay followed nonviolent communication, which started with observation. He then told Ann about his feelings and brought up his clear requests, so both of their needs were finally met in a peaceful way.', TRUE, 1, NULL, NULL),
  ('f514b22e-23bd-578e-8c1a-66b1f11087b5'::uuid, 'df49c72b-84bf-59de-a022-c74f49f23c2d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'New Jay was a specialist in nonviolent communication, and he used to teach his student Ann how to communicate with others in a respectful method. Ann was often late to his class, so New Jay became disappointed and stopped teaching her.', FALSE, 2, NULL, NULL),
  ('00df6329-4d6e-5998-9f1e-a5c7aead0066'::uuid, 'df49c72b-84bf-59de-a022-c74f49f23c2d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Ann was told by her teacher New Jay that she was allowed to be late for one minute to his class. This is the result of their nonviolent communication, during which both sides had clearly mentioned their requests.', FALSE, 3, NULL, NULL),
  ('60b0cf2d-7c41-50f7-af39-188be0a0701a'::uuid, 'df751a3d-f204-5db0-b121-792c73126f37'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'reluctant', FALSE, 0, NULL, NULL),
