  ('a001298f-ed55-5072-a097-bc24f366749e'::uuid, 'e11ab8fa-7422-544a-abd6-50638d3a88ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Around the world, wind in valleys generally travels up the valley, and up the sides of mountains, during the day.', FALSE, 0, NULL, NULL),
  ('5a6ab200-4f34-5e8b-8064-2146c89611f3'::uuid, 'e11ab8fa-7422-544a-abd6-50638d3a88ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This is often driven by differences in pressure caused by the slopes of the mountains and the shape of the valleys.', FALSE, 1, NULL, NULL),
  ('8f16c93e-288d-5f31-8364-6e8953ca4686'::uuid, 'e11ab8fa-7422-544a-abd6-50638d3a88ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Around 1 billion people depend on water resources originating from the Hindu-Kush Karakoram Himalayan region, attributable to both rainfall and melting of snow and ice.', FALSE, 2, NULL, NULL),
  ('74c9236c-9106-5310-9d1d-75202822b811'::uuid, 'e11ab8fa-7422-544a-abd6-50638d3a88ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The wind in the valleys in the region plays an important role in transporting clouds and moisture and redistributing snow in the valleys, and so understanding what drives this wind is crucial.', FALSE, 3, NULL, NULL),
