  ('9c412402-e75d-5644-8eac-3e19997d529f'::uuid, 'e155aec0-c9a4-50db-9b2f-749f48236389'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This aspect of culture includes a wide variety of things, from buildings, technological gadgets, and clothing, to film, music, literature, and art, among others.', FALSE, 0, NULL, NULL),
  ('3f628936-827e-5b73-bc1b-34f7ddb0c278'::uuid, 'e155aec0-c9a4-50db-9b2f-749f48236389'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'On the other hand, material culture is composed of the things that humans make and use.', FALSE, 1, NULL, NULL),
  ('eb0e0fbc-b714-55bb-a51d-049669dc32c4'::uuid, 'e155aec0-c9a4-50db-9b2f-749f48236389'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Culture is composed of both non-material and material things.', FALSE, 2, NULL, NULL),
  ('b43bf160-e6d1-5aaa-88d6-ddbb51e657e9'::uuid, 'e155aec0-c9a4-50db-9b2f-749f48236389'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In brief, sociologists define the non-material aspects of culture as the values and beliefs, language, communication, and practices that are shared in common by a group of people.', FALSE, 3, NULL, NULL),
  ('ef3027b1-cad0-581b-9a9f-93534606d1dc'::uuid, 'e155aec0-c9a4-50db-9b2f-749f48236389'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Expanding on these categories, culture is made up of our knowledge, common sense, assumptions, and expectations.', FALSE, 4, NULL, NULL),
  ('e6428966-45b2-5468-916f-8e3e96864ef8'::uuid, 'e15998c3-d52e-5df6-9031-3361ee5735a1'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'articles', FALSE, 0, 0, NULL),
