  ('e061540f-eb16-5f15-aba3-951f448d3b33'::uuid, 'e290a660-2d2f-54f2-8d13-3c12a36b0bdb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'workers', FALSE, 5, NULL, NULL),
  ('f0b65617-4ec4-5821-aafc-f262777b7f2b'::uuid, 'e297b055-0098-596a-9541-e5a7b0640534'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Beyond these three categories, many theories of and approaches toward human learning potential have been established.', FALSE, 0, NULL, NULL),
  ('f73f5d11-b063-5df4-bf51-18d4d30a5dea'::uuid, 'e297b055-0098-596a-9541-e5a7b0640534'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Among them is the theory of multiple intelligences developed by Howard Gardner, Ph.D., John H. and Elisabeth A. Hobbs Research Professor of Cognition and Education at the Harvard Graduate School of Education at Harvard University.', FALSE, 1, NULL, NULL),
  ('051b1031-7df4-53cc-9d44-88858b631d90'::uuid, 'e297b055-0098-596a-9541-e5a7b0640534'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Today there are nine intelligences, and the possibility of others may eventually expand the list.', FALSE, 2, NULL, NULL),
  ('84591bec-feb3-5ff5-9596-dcddb66e4183'::uuid, 'e297b055-0098-596a-9541-e5a7b0640534'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Gardner''s early work in psychology and later in human cognition and human potential led to his development of the initial six intelligences.', FALSE, 3, NULL, NULL),
  ('a649a51c-9f0e-5b15-b0ae-2ea40d7b3ca8'::uuid, 'e297b055-0098-596a-9541-e5a7b0640534'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Many of us are familiar with three broad categories in which people learn: visual learning, auditory learning, and kinesthetic learning.', FALSE, 4, NULL, NULL),
  ('1b5f862d-6c4b-539e-bff5-d9fbf1f50add'::uuid, 'e2a06bd2-2918-5358-8a5e-19e16438455e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'From this he concluded that there was nothing that could be identified genetically as East African.', FALSE, 0, NULL, NULL),
  ('0cca0044-3a29-5af4-bfd2-de894b0c4b5f'::uuid, 'e2a06bd2-2918-5358-8a5e-19e16438455e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Dr Pitsiladis has spent years trying to identify why Ethiopian runners from the mountain region are so successful.', FALSE, 1, NULL, NULL),
  ('0bcd3848-eff6-5699-a3e2-fec042553f87'::uuid, 'e2a06bd2-2918-5358-8a5e-19e16438455e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'He tested those children and found that their bodies processed oxygen more efficiently than many adult elite athletes in Britain.', FALSE, 2, NULL, NULL),
  ('8ccbcf57-e405-5ef2-b2cf-733347fb2309'::uuid, 'e2a06bd2-2918-5358-8a5e-19e16438455e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'He began by taking DNA samples but found that they all had a very different genetic make-up.', FALSE, 3, NULL, NULL),
  ('64093db5-ec50-50d1-851c-d569d26d521b'::uuid, 'e2a06bd2-2918-5358-8a5e-19e16438455e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'So he then looked at the East African way of life and found that as Children, 68 percent of all top Ethiopian or Kenyan runners ran, rather than walked, to school and back home, from the age of five onwards.', FALSE, 4, NULL, NULL),
  ('e35cf25a-cc21-56ac-8006-bc801ce843f4'::uuid, 'e2a27b49-893a-5366-8e85-9bd5e7b3e602'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'repository', FALSE, 0, 0, NULL),
