  ('ccbe50db-06f5-5be5-a6a4-bd0da07b9d1e'::uuid, 'e39509c1-61c9-51a5-9b0f-0220a62dd2e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'If you want to withdraw money, you can go to the ATM.', FALSE, 2, NULL, NULL),
  ('77128b25-0c30-5be6-aa03-90cad270fadd'::uuid, 'e39509c1-61c9-51a5-9b0f-0220a62dd2e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'ID is required to open a bank account.', FALSE, 3, NULL, NULL),
  ('b7045932-1240-50d0-b514-de08ef79cea3'::uuid, 'e39509c1-61c9-51a5-9b0f-0220a62dd2e9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Withdrawing money means to remove money from a bank account.', FALSE, 4, NULL, NULL),
  ('1cf5ac38-65cc-5139-b3f6-c31c448119c1'::uuid, 'e3ac3bc7-5cef-5df8-a4af-bb809229bf43'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This radiation heats the surface of the land and ocean, and these surfaces then reradiate infrared radiation back into space.', FALSE, 0, NULL, NULL),
  ('48237434-cfff-5900-8d94-c487e88987de'::uuid, 'e3ac3bc7-5cef-5df8-a4af-bb809229bf43'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A greenhouse gas is one that absorbs infrared radiation and then reradiates some of this radiation back to Earth.', FALSE, 1, NULL, NULL),
  ('3f68d5e5-6e65-5b18-9137-be694aa59c17'::uuid, 'e3ac3bc7-5cef-5df8-a4af-bb809229bf43'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'If any difference in this process, it may have impacts on climate change.', FALSE, 2, NULL, NULL),
  ('86dbd354-6ce6-5a88-b3a6-6da8056ee76d'::uuid, 'e3ac3bc7-5cef-5df8-a4af-bb809229bf43'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'About 70 percent of the Sun''s energy passes through the atmosphere and strikes Earth''s surface.', FALSE, 3, NULL, NULL),
  ('767e356b-a5f6-5d3e-ad4f-ea59212f57d9'::uuid, 'e3ac3bc7-5cef-5df8-a4af-bb809229bf43'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, not all of the infrared radiation makes it into space; some is absorbed by gases in the atmosphere and is reradiated back to Earth''s surface.', FALSE, 4, NULL, NULL),
  ('7fc3962e-1e1f-5b7a-b886-273285c57cf2'::uuid, 'e3bfd5f6-0088-5e37-abd6-da54f3a20546'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'retired', FALSE, 0, 0, NULL),
