  ('d6c56d28-56c5-54c3-b5ac-9ad4591d202c'::uuid, 'e3f6a557-8d15-5d47-8fda-dcaa8e1d794b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'He erected fort San Marcos in six days in defense against a Native American attack such as the one that forced the abandonment of the town a year earlier.', FALSE, 1, NULL, NULL),
  ('80b4c3d0-5b0b-5457-a737-3be7a99e350f'::uuid, 'e3f6a557-8d15-5d47-8fda-dcaa8e1d794b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The town had flourished, nearing 400 residents, since its establishment more than a decade earlier in 1566 by Pedro Menendez de Aviles who had founded La Florida and St. Augustine the year before.', FALSE, 2, NULL, NULL),
