  ('b900c123-0b09-5672-b84a-c49f81b76659'::uuid, 'e435b90d-4031-57bd-b2db-ec7ee8fd4eb9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The wildebeest', FALSE, 4, NULL, NULL),
  ('94fb7494-1826-5a27-9b16-19ed529ec48f'::uuid, 'e449d0e8-b266-5d67-92ba-9a52600f53ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'We have facilitated more than $203 million in investment, and worked with 250 innovative businesses whose goods and services produce clear, measurable environmental benefits, such as clean energy, efficient water use, and sustainable agriculture.', FALSE, 0, NULL, NULL),
  ('95b6efed-981e-59a7-a536-d9cb0896ad04'::uuid, 'e449d0e8-b266-5d67-92ba-9a52600f53ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Often they also address the challenges experienced by the world''s poor.', FALSE, 1, NULL, NULL),
  ('ad2b8f97-9780-5b10-b375-ea555dfb4ec7'::uuid, 'e449d0e8-b266-5d67-92ba-9a52600f53ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For example, one of the companies we work with in China, called Ecostar, refurbishes copy machines from the United States and re-sells or leases them for 20 percent less than a branded photocopier.', FALSE, 2, NULL, NULL),
  ('0bdd914f-71c3-5751-9bb8-6a94b69c0f18'::uuid, 'e449d0e8-b266-5d67-92ba-9a52600f53ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'New Ventures is a program that helps entrepreneurs in some of the world''s most dynamic, emerging economies - Brazil, China, Colombia, India, Indonesia and Mexico.', FALSE, 3, NULL, NULL),
  ('ff366c97-5acc-5963-b078-ee2c1431ff5c'::uuid, 'e45856fc-9dde-5628-85be-15e3efaf6dc4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In 1992 a retired engineer in San Diego contracted a rare brain disease that wiped out his memory.', FALSE, 0, NULL, NULL),
  ('9cedf78c-c101-52e8-9f72-7bd3e7e7b02a'::uuid, 'e45856fc-9dde-5628-85be-15e3efaf6dc4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Yet whenever he was hungry he got up and propelled himself straight to the kitchen to get something to eat.', FALSE, 1, NULL, NULL),
  ('2a38873d-8576-504a-8a5a-6ff2b60dbc05'::uuid, 'e45856fc-9dde-5628-85be-15e3efaf6dc4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Studies of this man led scientists to a breakthrough: the part of our brains where habits are stored has nothing to do with memory or reason.', FALSE, 2, NULL, NULL),
  ('d9ab58ef-06dc-507f-98a5-83cb26b6a81d'::uuid, 'e45856fc-9dde-5628-85be-15e3efaf6dc4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Every day he was asked where the kitchen was in his house, and every day he didn’t have the foggiest idea.', FALSE, 3, NULL, NULL),
  ('b44ce081-60bc-59c6-a71f-bee9bc8f18aa'::uuid, 'e45856fc-9dde-5628-85be-15e3efaf6dc4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It offered proof of what the US psychologist William James noticed more than a century ago that humans ''are mere walking bundles of habits'' .', FALSE, 4, NULL, NULL),
  ('481534c7-e568-5a83-aa74-446a7159d4ea'::uuid, 'e46740c3-145b-52f4-b4a7-515ac643c42c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'embedding', FALSE, 0, 0, NULL),
