  ('ff1d3962-b6c2-5232-b95a-d9d2c116212f'::uuid, 'e7396aac-3340-5df3-9680-6f607a2eef73'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Reviewing a historical study of the status of women in Mexico City during the nineteenth century', TRUE, 0, NULL, NULL),
  ('1c090508-afb1-5bad-a5eb-037bd44f5a75'::uuid, 'e7396aac-3340-5df3-9680-6f607a2eef73'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Analyzing the effects of economic instability on the status of women in Mexico during the nineteenth century', FALSE, 1, NULL, NULL),
  ('951f437c-1e6f-5442-8b49-8d2f7dd65096'::uuid, 'e7396aac-3340-5df3-9680-6f607a2eef73'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Advancing a thesis explaining why women''s status in Mexico City improved during the nineteenth century', FALSE, 2, NULL, NULL),
  ('2d76cfda-8c8e-53c6-a601-01e116e90505'::uuid, 'e7396aac-3340-5df3-9680-6f607a2eef73'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Rejecting the thesis that the status of women in Mexico City during the nineteenth century actually improved', FALSE, 3, NULL, NULL),
  ('b7b197d4-ba5e-50a2-92a2-c20c1145e4ae'::uuid, 'e742cbb6-40a8-5c2b-b736-a747cf69e8c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Research into family history by ordinary people only started to become far more widespread in the early nineteenth century. Prior to that time, it was chiefly rich. important and powerful families who had an interest and involvement in this type of activity.', FALSE, 0, NULL, NULL),
  ('224af180-3641-5b7e-be85-915e19518523'::uuid, 'e742cbb6-40a8-5c2b-b736-a747cf69e8c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The study of family history began hundreds of years ago in North Africa in order to establish such things as ownership of property. It rapidly became a common practice in many cultures because inheritance played such an important role in society and government.', FALSE, 1, NULL, NULL),
  ('c09847a9-e0d0-5b46-a452-82f5288643e6'::uuid, 'e742cbb6-40a8-5c2b-b736-a747cf69e8c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Originally. tracing family history was only used in order to establish the origins of prosperous and powerful families. However. by the middle of the twentieth century. ordinary people were also starting to show an interest in researching their family background too.', TRUE, 2, NULL, NULL),
  ('1656c6f6-1f94-557a-bd28-e9ac134e13cf'::uuid, 'e742cbb6-40a8-5c2b-b736-a747cf69e8c5'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'All social classes of the general population have always been interested in recording their family history. but genealogy became really popular in the early nineteenth century due to the publication of a book concerned with methodology of determining family history.', FALSE, 3, NULL, NULL),
  ('4e6f248d-f529-56a6-913b-0d65b56ee0f9'::uuid, 'e75b5427-8fdc-596e-9cf3-09d33c50d5a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'to make patients happier', TRUE, 0, NULL, NULL),
  ('2d3bc070-e268-5df1-ae89-0dd920506b1d'::uuid, 'e75b5427-8fdc-596e-9cf3-09d33c50d5a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'is less expensive', FALSE, 1, NULL, NULL),
