  ('568e94ec-2bc5-557d-b441-22861d1bae9f'::uuid, 'e75b5427-8fdc-596e-9cf3-09d33c50d5a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'to make a cure', FALSE, 4, NULL, NULL),
  ('ac3bcdf0-1700-5359-b849-732ccb17d1da'::uuid, 'e75d9724-9564-5092-bebf-f989f62cb22e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Philosophers like Socrates, Plato, and Aristotle explored topics such as ethics, metaphysics, and politics.', FALSE, 0, NULL, NULL),
  ('48c937e7-91c8-5c36-ac99-19aff0b44bca'::uuid, 'e75d9724-9564-5092-bebf-f989f62cb22e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It began in the 6th century BC and continued through the Hellenistic period.', FALSE, 1, NULL, NULL),
  ('a92d73bf-e856-5f66-bac3-d59fe6b79388'::uuid, 'e75d9724-9564-5092-bebf-f989f62cb22e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Ancient Greek philosophy had a profound impact on Western thought and culture.', FALSE, 2, NULL, NULL),
  ('c00ca359-f228-5a49-9e9f-231d5aaa127f'::uuid, 'e75d9724-9564-5092-bebf-f989f62cb22e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The legacy of ancient Greek philosophy is still evident in modern educational systems and philosophical discourse.', FALSE, 3, NULL, NULL),
  ('80f51ea3-a6bc-5768-aab8-ba7239b73a59'::uuid, 'e777285c-c78c-5403-b83b-260232d0a59f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Additionally, their works reflected the humanist ideals of the time and marked a significant shift in artistic techniques and themes.', FALSE, 0, NULL, NULL),
  ('d2fe05b7-9743-5c9e-873c-3d737c7b72cf'::uuid, 'e777285c-c78c-5403-b83b-260232d0a59f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Renaissance period, a rebirth of art and culture in Europe between the 14th and 17th centuries, witnessed revolutionary changes.', FALSE, 1, NULL, NULL),
  ('ec6058f5-6f67-528c-9da7-92142ce57c9a'::uuid, 'e777285c-c78c-5403-b83b-260232d0a59f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Artists like Leonardo da Vinci, Michelangelo, and Raphael transformed the field of art with innovations in perspective, composition, and human anatomy.', FALSE, 2, NULL, NULL),
  ('d6550270-d059-5c42-9ce9-10849927d048'::uuid, 'e777285c-c78c-5403-b83b-260232d0a59f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Consequently, Renaissance art remains a vital cultural heritage, captivating audiences with its beauty and historical significance.', FALSE, 3, NULL, NULL),
  ('185f82f7-ebf7-5c5b-87a8-a8a7aeba9919'::uuid, 'e7b33be4-6514-5002-b046-b1ec2c238246'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'overcome', TRUE, 0, 0, NULL),
