  ('a2afabe1-d1cf-5281-aaf9-22cc18bb2f43'::uuid, 'ec7bba52-4ed1-54ba-b4a5-7f784e29e487'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Part of the decline is almost certainly due to climate change, but other factors include increased commercial fishing and disease.', FALSE, 1, NULL, NULL),
