  ('e8f94a4e-c6da-5ce9-bfea-1958c60870e1'::uuid, 'ec8d1151-3c28-549b-9d4d-102e31140bf0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It''s often said that ants can predict impending rain and respond by changing their behavior.', FALSE, 0, NULL, NULL),
  ('ee184b78-3b97-5aaa-afb7-94138a78aabb'::uuid, 'ec8d1151-3c28-549b-9d4d-102e31140bf0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'But is there any scientific evidence to support this piece of folk wisdom?', FALSE, 1, NULL, NULL),
  ('3274211e-19a2-56ab-8c55-184f08ee732a'::uuid, 'ec8d1151-3c28-549b-9d4d-102e31140bf0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Some people say that if you see ants building their mounds higher, or building them from different materials, this might signal the coming of rain.', FALSE, 2, NULL, NULL),
  ('62f69ad4-4cdf-58aa-be7b-e50ba37bf3fe'::uuid, 'ec8d1151-3c28-549b-9d4d-102e31140bf0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The short answer is "no", although it is a difficult question to answer partly because of the sheer diversity of ants - there are 13,000 named species on the planet!', FALSE, 3, NULL, NULL),
  ('8fb04fd4-4a0f-5be3-bb1c-4dbf97934b69'::uuid, 'eca5203e-df02-5466-aae6-a1ee7a0f3f3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Many bird species exhibit migration, a seasonal movement to new regions.', FALSE, 0, NULL, NULL),
  ('a4656ec6-8269-5a43-b8c8-ffc9f60d09ab'::uuid, 'eca5203e-df02-5466-aae6-a1ee7a0f3f3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, these migratory patterns can be disrupted by climate change and habitat destruction.', FALSE, 1, NULL, NULL),
  ('60a4d488-42c0-5259-974b-6308257066fb'::uuid, 'eca5203e-df02-5466-aae6-a1ee7a0f3f3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This behavior often results from changes in food availability and climatic conditions.', FALSE, 2, NULL, NULL),
  ('88f7d05d-0a05-5396-a97e-46eab796fc07'::uuid, 'eca5203e-df02-5466-aae6-a1ee7a0f3f3c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For example, birds fly south to warmer areas during winter when food becomes scarce in colder regions.', FALSE, 3, NULL, NULL),
  ('d9dae648-a220-51e7-83a1-7615e0e142ac'::uuid, 'eca8f2ba-63e2-55fb-ae79-b0e736a55536'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'integrity', FALSE, 0, 0, NULL),
