  ('8a7219a5-141a-56b5-bb9a-dc4e6a549314'::uuid, 'ecccf47f-a8f8-5246-98ea-6384729dcd1b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'High noise levels in the workplace, particularly in industrial settings, can impair communication and concentration.', FALSE, 0, NULL, NULL),
  ('dca6e76a-ab95-572a-af5f-44de9bddee6d'::uuid, 'ecccf47f-a8f8-5246-98ea-6384729dcd1b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This often leads to reduced productivity and an increased risk of accidents.', FALSE, 1, NULL, NULL),
  ('97663567-11f6-5594-b0d0-404cb393e1f9'::uuid, 'ecccf47f-a8f8-5246-98ea-6384729dcd1b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Therefore, implementing noise control measures, such as soundproofing and providing personal protective equipment like earplugs, is essential for worker safety and well-being.', FALSE, 2, NULL, NULL),
  ('977ebd1b-e4d2-57cc-a3aa-d1bc2a7ad259'::uuid, 'ecccf47f-a8f8-5246-98ea-6384729dcd1b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Besides, long-term exposure can cause permanent hearing loss and psychological stress.', FALSE, 3, NULL, NULL),
