  ('f82431ef-47d8-581b-be1d-ddb2e43a1547'::uuid, 'ece1d1b9-4811-55de-ba35-0b0b4484ec91'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The political patterns in America.', FALSE, 0, NULL, NULL),
  ('c9d7daf1-06dd-5382-ae83-cb827cf5fb23'::uuid, 'ece1d1b9-4811-55de-ba35-0b0b4484ec91'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The change of politics given by televisions.', TRUE, 1, NULL, NULL),
  ('a208991d-b8c3-5541-8f67-3352c5cfbf81'::uuid, 'ece1d1b9-4811-55de-ba35-0b0b4484ec91'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The change of audience in speeches.', FALSE, 2, NULL, NULL),
  ('6c0146c6-1bc0-5724-ae05-c16d4b1eb31a'::uuid, 'ece1d1b9-4811-55de-ba35-0b0b4484ec91'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The advantages of televisions.', FALSE, 3, NULL, NULL),
  ('4f0fee35-ee89-510d-9e03-c449d5573365'::uuid, 'ece346a7-89fd-5bd0-a50f-c320315bff8e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'When making a friend, we should not trust a person from the very beginning. It takes weeks or even months when we get to know a stranger. If we share the same interest, this process may take less time.', FALSE, 0, NULL, NULL),
  ('711203cd-6491-578a-bf04-668daffd7e7b'::uuid, 'ece346a7-89fd-5bd0-a50f-c320315bff8e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To build a friendship, an effective way is to join like-minded groups, who share the same interest. Also, you should trust your instincts and make friends with people who make you feel comfortable from the beginning..', TRUE, 1, NULL, NULL),
  ('36ad1931-33f4-5527-b68e-202e898cbb11'::uuid, 'ece346a7-89fd-5bd0-a50f-c320315bff8e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'When meeting with someone in a like-minded group, you should never trust what people show you about themselves initially. Also, you need to feel comfortable when communicating with people who may potentially become your friends.', FALSE, 2, NULL, NULL),
  ('7ecbdb54-a659-55ef-80e4-6b9bb84a6811'::uuid, 'ece346a7-89fd-5bd0-a50f-c320315bff8e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'People tend to disguise who they really are initially and avoid trusting strangers, even in like-minded groups. Therefore, we should invest more time in understanding others before deciding to develop a friendship with them.', FALSE, 3, NULL, NULL),
