  ('cc92b1f8-4851-5f2d-a7df-53835f2a8029'::uuid, 'ed23048e-2b0c-51cf-a63f-9ea2daefeceb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Food alone is a logistical headache.', FALSE, 0, NULL, NULL),
  ('6c3c3afe-2c91-560c-b999-08f149b8e0dc'::uuid, 'ed23048e-2b0c-51cf-a63f-9ea2daefeceb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Giant pandas are not biologically herbivores, but for some reason they developed a taste for bamboo about 6,000 years ago and stopped eating a varied diet, including meat.', FALSE, 1, NULL, NULL),
  ('8773b612-c1a8-5a9d-82f7-2485aa7b731d'::uuid, 'ed23048e-2b0c-51cf-a63f-9ea2daefeceb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Pandas are the most expensive animal to keep in a zoo, costing about five times as much as an elephant.', FALSE, 2, NULL, NULL),
  ('e288fa55-23f9-5b51-aa3c-82d283e7c838'::uuid, 'ed23048e-2b0c-51cf-a63f-9ea2daefeceb'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Bamboo, however, is low in nutrients and difficult to digest, which means pandas have to eat a lot and then rest.', FALSE, 3, NULL, NULL),
  ('0b4658bb-945b-5825-bbf1-a9a749e2d424'::uuid, 'ed29ec3b-36d9-57af-9328-70201aff99ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Renewable energy technologies are essential in combating climate change.', FALSE, 0, NULL, NULL),
  ('33a5f0ee-6757-554a-a317-513d531fa3fe'::uuid, 'ed29ec3b-36d9-57af-9328-70201aff99ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To be more specific, solar panels and wind turbines convert natural resources into clean energy, reducing reliance on fossil fuels.', FALSE, 1, NULL, NULL),
  ('1029c2e1-15f6-5ad3-93a6-24a0aaa723ca'::uuid, 'ed29ec3b-36d9-57af-9328-70201aff99ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Despite their benefits, these technologies face challenges in storage and consistent energy supply.', FALSE, 2, NULL, NULL),
  ('dbb271ab-2c09-51ba-9fd1-b69bd22fd944'::uuid, 'ed29ec3b-36d9-57af-9328-70201aff99ee'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Thus, ongoing research is focused on improving energy storage solutions and efficiency.', FALSE, 3, NULL, NULL),
  ('217ab79c-f8c8-5dfc-957c-820bfdc742b4'::uuid, 'ed2dc20a-db82-5ac4-bdb1-1783abc4ca60'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Today, GPS technology is integrated into smartphones, cars, and even wearable devices, making it a part of our daily lives.', FALSE, 0, NULL, NULL),
  ('cdb70b24-068d-5adf-83db-e5eaa25940a6'::uuid, 'ed2dc20a-db82-5ac4-bdb1-1783abc4ca60'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In the past, people relied on physical maps and written directions to find their way, but technology has changed all that.', FALSE, 1, NULL, NULL),
  ('f406c67d-3552-5851-89f5-ce352f529bae'::uuid, 'ed2dc20a-db82-5ac4-bdb1-1783abc4ca60'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'GPS stands for Global Positioning System, and it allows users to determine their exact location anywhere on Earth.', FALSE, 2, NULL, NULL),
  ('60baa26e-ddb6-5815-8a3e-e9791f675f9f'::uuid, 'ed2dc20a-db82-5ac4-bdb1-1783abc4ca60'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'GPS technology works by triangulating signals from multiple satellites to pinpoint a user''s location with remarkable accuracy.', FALSE, 3, NULL, NULL),
  ('ee187770-e49c-5df6-b3e3-5d2e46fa5fd4'::uuid, 'ed2dc4f6-fc54-51c9-8f83-9617d629527f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'talked', FALSE, 0, 0, NULL),
