  ('4aef67e1-3712-5954-af38-cae7fbc6bfc1'::uuid, 'ed51655c-c3c0-5184-a490-b69ed5e165c4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'present', FALSE, 15, 3, NULL),
  ('e261c02e-a997-5780-833e-42f5702e973b'::uuid, 'ed570e72-6f99-51b6-99eb-67f8e920ce7e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The speaker is a trained marine biologist who became an anthropologist after hearing about an ancient people who lived on beaches and got their food from the sea. Because he was a keen fisherman, he identified with these people and began to study anthropology. They lived in a very simple way, catching fish with their hands and gathering shells, such as oysters.', FALSE, 0, NULL, NULL),
  ('628cffcf-dd03-54a4-a003-a301bb89fb45'::uuid, 'ed570e72-6f99-51b6-99eb-67f8e920ce7e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The speaker is a marine biologist who became interested in the Strandlopers, an ancient people who lived on the coastline, because of their and his connection to the sea. Their way of life intrigued him - as a child he had spent a lot of time by the sea, exploring and collecting things - so he began to study them, and discovered some interesting information about their way of life, how they hunted, what tools they used, and so on.', TRUE, 1, NULL, NULL),
  ('debe3cec-7ad2-52e1-b64e-8d2f4f2b20cd'::uuid, 'ed570e72-6f99-51b6-99eb-67f8e920ce7e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The speaker is a marine biologist who became an archaeologist when he heard about a mythical people called the Strandlopers, or beach-walkers. He was interested in them because as a child he had lived by the sea and so he identified with them. His aim was to prove they were not a myth and set about finding evidence to prove they really existed, and in this he was successful.', FALSE, 2, NULL, NULL),
  ('85b8ff73-c8c4-5b6c-87e8-d9d7922edae8'::uuid, 'ed57dc67-e1e8-55c0-9acd-dbc9bc85e63e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Oxford likes to be different from other places.', FALSE, 0, NULL, NULL),
  ('1afdcdf8-c22b-5877-8b29-f4b5c7675993'::uuid, 'ed57dc67-e1e8-55c0-9acd-dbc9bc85e63e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It was initially a protest against the coming of the railway.', FALSE, 1, NULL, NULL),
  ('71641079-e70a-5060-a7d8-88dba8ba90a9'::uuid, 'ed57dc67-e1e8-55c0-9acd-dbc9bc85e63e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Cathedral staff were reluctant to act too quickly.', TRUE, 2, NULL, NULL),
  ('cccb61be-af70-5060-be16-80e0075453c3'::uuid, 'ed57dc67-e1e8-55c0-9acd-dbc9bc85e63e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It was very difficult to alter the time on the clock.', FALSE, 3, NULL, NULL),
