  ('f688b04d-48e5-55ec-871b-e41a2efefc66'::uuid, 'edf5bb4d-c3c6-5c85-ba01-7eec45a826fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The approach doesn''t always require researchers to observe people in such exotic environments, however.', FALSE, 0, NULL, NULL),
  ('f72a822e-77f8-5a74-ba63-942ff2cb60d7'::uuid, 'edf5bb4d-c3c6-5c85-ba01-7eec45a826fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For example, cultural anthropologist Margaret Mead used naturalistic observation to study the daily lives of different groups in the South Pacific.', FALSE, 1, NULL, NULL),
  ('d4730903-6414-5b82-a70f-8efb1281e83d'::uuid, 'edf5bb4d-c3c6-5c85-ba01-7eec45a826fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It can be conducted in any kind of social or organizational setting, including offices, schools, or just about any other place where people can be observed.', FALSE, 2, NULL, NULL),
  ('20cf0e7e-bedb-5579-bfe1-8e28236abe1c'::uuid, 'edf5bb4d-c3c6-5c85-ba01-7eec45a826fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Naturalistic observation involves observing subjects of interest in their normal, everyday setting.', FALSE, 3, NULL, NULL),
  ('97330be1-6869-5881-849a-d17ac6c49513'::uuid, 'edf5bb4d-c3c6-5c85-ba01-7eec45a826fd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It’s sometimes referred to as field work because it requires researchers to go out into the field (the natural setting) to collect data on their participants.', FALSE, 4, NULL, NULL),
  ('a8dd3056-e686-5262-951e-968d9d13ffa4'::uuid, 'edffb8cb-f64f-5ebc-a542-5668f7f1a841'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The regent honeyeater has gone extinct.', FALSE, 0, NULL, NULL),
