  ('26bf0b9e-bef1-5845-86fc-1a2de79a422f'::uuid, 'edffb8cb-f64f-5ebc-a542-5668f7f1a841'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It used to be one of the most common species.', TRUE, 2, NULL, NULL),
