  ('094210a4-793b-53e1-857f-f96aceed9f22'::uuid, 'ef3f8910-23d9-595b-a45b-366c0d32beb6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There is a difference between Gandhiji''s concept of secularism and that of Nehru''s.', FALSE, 1, NULL, NULL),
  ('db6862c4-4cee-5a80-8739-41c3cf6971cc'::uuid, 'ef3f8910-23d9-595b-a45b-366c0d32beb6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In Gandhiji''s view, secularism stands for equal respect for all religions.', FALSE, 2, NULL, NULL),
  ('893a8ab1-ca2e-5b56-b187-ecffb1eb5870'::uuid, 'ef3f8910-23d9-595b-a45b-366c0d32beb6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Nehru''s idea of secularism was equally indifferent to all religions and bothering about none of them.', FALSE, 3, NULL, NULL),
  ('ff910246-3a31-5dfd-9c1f-88f051330593'::uuid, 'ef3f8910-23d9-595b-a45b-366c0d32beb6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Such secularism which means the rejection of all religions is contrary to our culture and tradition.', FALSE, 4, NULL, NULL),
  ('c04cfab2-65b7-59fb-8da6-bf80554d064b'::uuid, 'ef637265-8fbd-5201-9f19-cb833307e195'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For that reason, microbiologists in Turkey have surveyed the array of species that inhabit the Acigol, Salda and Yarisli lakes.', FALSE, 0, NULL, NULL),
  ('90a465ce-98d2-5787-937c-90aee27e01fc'::uuid, 'ef637265-8fbd-5201-9f19-cb833307e195'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'That''s where you''ll find lakes so salty that the only bugs able to live there are species that could probably survive on Mars as well.', FALSE, 1, NULL, NULL),
  ('1ba9954e-5b97-5892-9330-9a8eac9e1f64'::uuid, 'ef637265-8fbd-5201-9f19-cb833307e195'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They''re hopeful that studying some of them will yield useful insights into the kinds of biology that could help microbes exist on Mars or other potentially habitable planets and moons.', FALSE, 2, NULL, NULL),
