  ('47b767cb-1404-5343-9581-016435e4c8a8'::uuid, 'efb6415e-c349-5f5a-a041-c150334e9abe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Mobius weight energy function models DNA purely as a bending rod and does not account for torsional topology or sequence variability.', FALSE, 2, NULL, NULL),
  ('94b68cc9-c763-5d7b-8fd4-72af653896a9'::uuid, 'efb6415e-c349-5f5a-a041-c150334e9abe'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The Mobius weight function focuses exclusively on electronic base-pair interactions, ignoring large-scale mechanical properties.', FALSE, 3, NULL, NULL),
