  ('1785f5d9-8d79-573e-b32c-a2d3dafbe792'::uuid, 'f112c40f-393a-5dc2-9ac0-75dbbc3bcde8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Swiss engineer George de Mestral once returned from a hike with his dog and found many burrs clinging tightly to his trousers and the dog''s fur.', FALSE, 0, NULL, NULL),
  ('12ea102c-47c9-5e96-9920-05a4e6c470a4'::uuid, 'f112c40f-393a-5dc2-9ac0-75dbbc3bcde8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The discovery revealed the burrs were covered with tiny hooks that could latch onto fabric loops and fur firmly.', FALSE, 1, NULL, NULL),
  ('43096029-2686-5bd2-8f58-90e9860e2006'::uuid, 'f112c40f-393a-5dc2-9ac0-75dbbc3bcde8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Curious about this attachment, he took some burrs home and examined them with a magnifying glass first, then a microscope.', FALSE, 2, NULL, NULL),
  ('2894f7e5-d974-54cf-9e04-3fbee4c24ed8'::uuid, 'f112c40f-393a-5dc2-9ac0-75dbbc3bcde8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This mechanism inspired him to create Velcro, a fastener with hooks on one side and soft loops on the other, named by combining French ''velours'' and ''crochet''.', FALSE, 3, NULL, NULL),
  ('4ab9b4db-bcf0-5e54-b075-d2cf16454f7a'::uuid, 'f1182057-90e6-5124-bf8e-4de1c02117bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Only by mitigating human disturbances and preserving the ecosystems where owls thrive can we ensure the continued survival of these remarkable nocturnal hunters.', FALSE, 0, NULL, NULL),
  ('5903f660-4d43-5064-91ba-1aeba0f19c11'::uuid, 'f1182057-90e6-5124-bf8e-4de1c02117bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Their silent flight is due to specialized feather structures, allowing them to approach prey unnoticed.', FALSE, 1, NULL, NULL),
  ('89aae4e5-def4-5ba2-9c2a-cbdc757df162'::uuid, 'f1182057-90e6-5124-bf8e-4de1c02117bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Owls are well-adapted for nocturnal life.', FALSE, 2, NULL, NULL),
  ('1ad0cb38-5141-58bc-b3e9-8d87bfdc7fdb'::uuid, 'f1182057-90e6-5124-bf8e-4de1c02117bd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'While these adaptations are advantageous for night hunting, habitat loss and human disturbances are challenging their survival.', FALSE, 3, NULL, NULL),
