  ('643fe600-a733-5dc2-be6a-f768fa2461bf'::uuid, 'f1e27fe1-7005-5d9b-9ddd-b35d8bb78e39'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Today, wildfire experts call the burning of Yellowstone, located in the western United States, something else: a “megafire.”', FALSE, 0, NULL, NULL),
  ('d36f1b03-fc0e-5372-851b-c3b21a8985c3'::uuid, 'f1e27fe1-7005-5d9b-9ddd-b35d8bb78e39'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Other wildfire experts expand the definition of a megafire beyond “acres burned” to mean wildfires that have an unusually large impact on people and the environment.', FALSE, 1, NULL, NULL),
  ('baec3d7f-fd25-531b-afbe-ad9c448786a8'::uuid, 'f1e27fe1-7005-5d9b-9ddd-b35d8bb78e39'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The U.S. Interagency Fire Center defines a megafire by its size: It is a wildfire that burns more than 40,500 hectares (100,000 acres) of land.', FALSE, 2, NULL, NULL),
  ('bdd96944-9da0-5b25-949b-7c40def765ea'::uuid, 'f1e27fe1-7005-5d9b-9ddd-b35d8bb78e39'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In August 1988, high winds changed small, smoldering wildfires in Yellowstone National Park into raging firestorms — an event that came to be known as “Black Saturday.”', FALSE, 3, NULL, NULL),
  ('da94b38f-a7dc-5cc4-9145-bea60e1ba31c'::uuid, 'f1faff0e-f4de-5f1e-930c-6442fad1d3f0'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'vanishing', FALSE, 0, NULL, NULL),
