  ('36125375-4bb7-5a08-8572-2de898488e91'::uuid, 'f1fdb662-3a57-527c-81c7-d465fc44ab80'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'beyond', FALSE, 6, NULL, NULL),
  ('cf9f5a68-187d-5b7a-a628-c69b7e72a9ba'::uuid, 'f2187e48-644b-5166-a99e-bd62ecb05c58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Research has shown that palliative care should be seen as a cancer drug, because it can help patients live at least one year longer. Currently there is no prescription for it written by doctors.', FALSE, 0, NULL, NULL),
  ('c460b5a7-32d9-5354-9c80-b551b5e727cf'::uuid, 'f2187e48-644b-5166-a99e-bd62ecb05c58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Evidence has shown that palliative care can help patients experience less pain and depression. They can also live longer up to six months with palliative care.', TRUE, 1, NULL, NULL),
  ('06e64aa3-e39e-5804-9b93-20e17f798126'::uuid, 'f2187e48-644b-5166-a99e-bd62ecb05c58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It has been proved that palliative care can directly help patients to live their life based on their values and faith, and help them to write the chapters of their lives.', FALSE, 2, NULL, NULL),
  ('3781a527-df1c-56b2-8578-de197dbca339'::uuid, 'f2187e48-644b-5166-a99e-bd62ecb05c58'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Their is no direct proof that palliative care is able to extend patients’ life. However, if patients have their own values and find what are sacred, they can live a longer life with up to five more years.', FALSE, 3, NULL, NULL),
  ('ed055f85-ace6-5aa4-a82c-775aa734b0a6'::uuid, 'f2194f45-54df-5e40-9428-76ff552c90d9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'damages', FALSE, 0, NULL, NULL),
