  ('203ff71e-ed31-53e7-8c62-f78df769c905'::uuid, 'f27b7f7c-1b6c-563b-b690-300ad0dd3c1f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'equitable', TRUE, 15, 3, NULL),
  ('77f47776-5b2c-5b72-b8a8-7a97738e465a'::uuid, 'f2820fa6-2e68-55e4-a53d-f3dd542698e8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Only four years later did football become an official competition at the Games. At this stage it was, of course, for amateurs only.', FALSE, 0, NULL, NULL),
  ('8c8044c4-b678-5c04-9fa5-a8597d5d141e'::uuid, 'f2820fa6-2e68-55e4-a53d-f3dd542698e8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Ironically, the first tournament was won by an amateur team from the north- cast of England, who had been especially invited after the British Football Association refused to be associated with the competition.', FALSE, 1, NULL, NULL),
  ('a956823c-94bb-5cd9-b7b9-03ae58770be2'::uuid, 'f2820fa6-2e68-55e4-a53d-f3dd542698e8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The first international football match was played in 1872 between England and Scotland, when football was rarely played anywhere outside Great Britain.', FALSE, 2, NULL, NULL),
  ('aee22171-2c02-5e53-830a-d33889dd44cf'::uuid, 'f2820fa6-2e68-55e4-a53d-f3dd542698e8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As an alternative, Sir Thomas Lipton decided to organize an event for professionals. Often described as The First World Cup, it took place in Turin in 1909 and featured the most prestigious professional clubs from Italy, Germany and Switzerland.', FALSE, 3, NULL, NULL),
  ('bd22a899-980b-5072-b23f-6de51968a35b'::uuid, 'f2820fa6-2e68-55e4-a53d-f3dd542698e8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, as football increased in popularity, it was admitted to the Olympics TM in 1900 and 1904, but only as a sideshow and not in the competition for medals.', FALSE, 4, NULL, NULL),
  ('bfabbfde-b007-5152-9284-3770e60dd0d2'::uuid, 'f2923dec-a490-5352-a715-09903106c89b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'untreated', TRUE, 0, NULL, 3),
