  ('103ea80e-baac-5234-8265-36bbb2b5bf4c'::uuid, 'f2981cdb-0c92-59de-83e4-29ce732639ae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'layout', FALSE, 16, 4, NULL),
  ('a484cdd0-24cd-5786-8470-3ca30b69df21'::uuid, 'f2981cdb-0c92-59de-83e4-29ce732639ae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'brick', FALSE, 17, 4, NULL),
  ('b30af315-09b9-564f-843f-415a60927eca'::uuid, 'f2981cdb-0c92-59de-83e4-29ce732639ae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'formality', FALSE, 18, 4, NULL),
  ('75ae387a-239c-58d4-83f8-3064a3960c10'::uuid, 'f2981cdb-0c92-59de-83e4-29ce732639ae'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'stage', TRUE, 19, 4, NULL),
  ('9c9eb645-fb23-5ac2-b1c6-ab0a068bf9de'::uuid, 'f2a0cc43-a2ea-5f75-ae56-1a3c840c5611'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'If any member of the family dares to open his mouth during a programme, he is quickly silenced.', FALSE, 0, NULL, NULL),
  ('2f04eac4-59ca-5caf-bee9-ce8f72ef01ca'::uuid, 'f2a0cc43-a2ea-5f75-ae56-1a3c840c5611'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Television hasn''t been with us all that long, but we are already beginning to forget what the world was like without it. Before we admitted the one-eyed monster into our homes, we never found it difficult to occupy our spare time. We used to enjoy civilized pleasures. For instance, we used to have hobbies, we used to entertain our friends and be entertained by them, we used to go outside for our amusements to theatres, cinemas, restaurants and sporting events.', FALSE, 1, NULL, NULL),
  ('ca8feba8-2321-50db-bd62-f0975831a403'::uuid, 'f2a0cc43-a2ea-5f75-ae56-1a3c840c5611'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'We have even given up sitting at table and having a leisurely evening meal, exchanging the news of the day. A sandwich and a glass of beer will do- anything, providing it don''t interfere with the programme. The monster demands and obtains absolute silence and attention.', FALSE, 2, NULL, NULL),
  ('d8d7d185-31e0-5196-a0c0-0f3a6a0a19b9'::uuid, 'f2a0cc43-a2ea-5f75-ae56-1a3c840c5611'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Whole generations are growing up addicted to the telly. Food is left uneaten, homework undone and sleep is lost.', FALSE, 3, NULL, NULL);
INSERT INTO _pte_local_seed_options (public_id, question_public_id, created_at, updated_at, deleted, text, correct, order_index, blank_index, correct_gap_index) VALUES
  ('57c16fbb-76e2-598b-9a6b-05ad00982f64'::uuid, 'f2a0cc43-a2ea-5f75-ae56-1a3c840c5611'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'We even used to read books and listen to music and broadcast talks occasionally. All that belongs to the past. Now all our free time is regulated by the goggle box. We rush home or gulp down our meals to be in time for this or that programme.', FALSE, 4, NULL, NULL),
  ('8760e695-155b-5a6c-8375-635f55414be3'::uuid, 'f2a71ad2-5bbd-5a9b-a3ee-2cb54c340390'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'tremendous', TRUE, 0, NULL, 0),
