  ('973e9f61-7177-589a-8b70-b9b3ecc037ab'::uuid, 'f3099c4a-7c70-5fa1-b4f0-295e2739d40e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As a result, the rapid growth in demand for oil fruit has led to the significant loss of native rainforests in Asia.', FALSE, 0, NULL, NULL),
  ('c32dde19-2074-50ce-a7ef-f2aa80fb1431'::uuid, 'f3099c4a-7c70-5fa1-b4f0-295e2739d40e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'With the global increase in demand for vegetable oils, other continents like Asia began to cultivate this fruit on a massive scale.', FALSE, 1, NULL, NULL),
  ('c57c20ca-de06-5408-abd1-98484ff4314a'::uuid, 'f3099c4a-7c70-5fa1-b4f0-295e2739d40e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Originally, oil palm trees were native to West Africa, but today approximately 80% of the world''s production is concentrated in Southeast Asia.', FALSE, 2, NULL, NULL),
  ('dd309826-c0d4-5d12-b980-6f616f35cfd3'::uuid, 'f3099c4a-7c70-5fa1-b4f0-295e2739d40e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The oil is extracted from the fruit of the oil palm tree, which is typically the size of a large golf ball.', FALSE, 3, NULL, NULL),
