  ('5a1026c7-6e8c-5d5c-a4fc-20426bf3d084'::uuid, 'f32db380-78b8-57bd-83ff-5fbf97690f06'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A team of scientists has discovered two Earth-like planets in the habitable orbit of a Sun-like star.', FALSE, 0, NULL, NULL),
  ('70f16530-3fab-5cbd-9126-d53b50b62654'::uuid, 'f32db380-78b8-57bd-83ff-5fbf97690f06'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Using observations gathered by NASA''s Kepler Mission, the team found five planets orbiting a Sun-like star called Kepler-62.', FALSE, 1, NULL, NULL),
  ('1da48d50-8e7f-5e99-93fd-b7907ddee0da'::uuid, 'f32db380-78b8-57bd-83ff-5fbf97690f06'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Four of these planets are so-called super-Earths, larger than our own planet, but smaller than even the smallest ice giant planet in our Solar System.', FALSE, 2, NULL, NULL),
  ('83df9b20-9420-5ad1-91f8-0fea9f3e0685'::uuid, 'f32db380-78b8-57bd-83ff-5fbf97690f06'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'These new super-Earths have radii of 1.3, 1.4, 1.6, and 1.9 times that of Earth. In addition, one of the five was a roughly Mars-sized planet, half the size of Earth.', FALSE, 3, NULL, NULL),
  ('ffc332b0-e843-56c1-82a2-203ea8e54ace'::uuid, 'f33f5ad9-2a0d-5e0f-a575-fb522d747d65'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'dew', FALSE, 0, 0, NULL),
