  ('25f8daca-75a7-53cb-9d36-dfe3b391cb96'::uuid, 'f4b78221-7220-52c3-b326-72c5359d252f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, these tools often struggle with capturing cultural nuances and the idiomatic expressions.', FALSE, 1, NULL, NULL),
  ('0a5ec8c4-39c1-5576-9a35-7be3779c4079'::uuid, 'f4b78221-7220-52c3-b326-72c5359d252f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As a result, human translators remain vital for accurate and culturally sensitive translations.', FALSE, 2, NULL, NULL),
  ('2992745b-803f-538b-a6da-7756d3b6aa4c'::uuid, 'f4b78221-7220-52c3-b326-72c5359d252f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Advances in translation technology have largely bridged communication gaps between different languages.', FALSE, 3, NULL, NULL),
  ('7b6362f1-9e5f-5d95-b3b2-14fd7fcd6e9b'::uuid, 'f4c35fe8-ca93-52ff-8084-9ed40500fc3f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Nowadays, the environmental impact of banana production is a growing concern.', FALSE, 0, NULL, NULL),
  ('f0d1a6ed-1a52-5f1d-aa8a-376493e6c7ee'::uuid, 'f4c35fe8-ca93-52ff-8084-9ed40500fc3f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In response, there is an increasing shift towards organic banana farming practices.', FALSE, 1, NULL, NULL),
  ('e36dd624-f924-55e2-a38d-748660cca77c'::uuid, 'f4c35fe8-ca93-52ff-8084-9ed40500fc3f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Additionally, intensive banana farming often involves heavy use of pesticides and fertilizers, contributing to soil and water pollution.', FALSE, 2, NULL, NULL),
  ('7d303f9a-2268-5891-94ed-1a2eecaa8d51'::uuid, 'f4c35fe8-ca93-52ff-8084-9ed40500fc3f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As bananas require a lot of water to grow, this can lead to water scarcity in some regions.', FALSE, 3, NULL, NULL),
  ('13e29df3-6c0b-57f0-9e8b-22bc9f3d1732'::uuid, 'f4dd3ea8-7afa-55b1-b774-c4ebfb4fb9e3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Some examples cited for a possible treatment using these cells are diabetes, motor neuron disease and Parkinson’s disease.', FALSE, 0, NULL, NULL),
  ('a28d51d2-8980-5dd7-b04e-2c43e23d6a19'::uuid, 'f4dd3ea8-7afa-55b1-b774-c4ebfb4fb9e3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Embryonic stem cells are valued by scientists because the cells’ descendant can turn into any other sort of body cells.', FALSE, 1, NULL, NULL),
