  ('edf6c264-203a-5e56-bdc9-bcac3e029625'::uuid, 'f539186e-a749-5e74-ac79-5fddfd757b25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The vigilance of animals on the periphery of a group always exceeded that of animals located in its interior, even when predators were not in the area.', FALSE, 0, NULL, NULL),
  ('e6ff198b-a59a-5303-8a41-f19025743c29'::uuid, 'f539186e-a749-5e74-ac79-5fddfd757b25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The risk of capture for individuals in a group was the same, whether they were located in the interior of the group or on its periphery.', TRUE, 1, NULL, NULL),
  ('693ae8c4-9071-5a27-bd30-94be6fc5542e'::uuid, 'f539186e-a749-5e74-ac79-5fddfd757b25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Animals on the periphery of a group tended to be less capable of defending themselves from attack by predators than animals located in the interior of the group.', FALSE, 2, NULL, NULL),
  ('7a037fb2-f56e-5e91-bb79-11ac1a099565'::uuid, 'f539186e-a749-5e74-ac79-5fddfd757b25'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Animals on the periphery of a group tended to bear marks that were more distinctive to predators than animals located in the interior of the group.', FALSE, 3, NULL, NULL),
