  ('585daf59-649b-5fcc-8e3d-d6c9cc4e72de'::uuid, 'f62b5a4c-eb60-5b6e-99c0-40326c2679ba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In the 1920s, Carl Sauer became influential in urban geography as he motivated geographers to study a city''s population and economic aspects with regard to its physical location.', FALSE, 0, NULL, NULL),
  ('e1849f79-28ec-5cf6-a803-90bbf17d30b9'::uuid, 'f62b5a4c-eb60-5b6e-99c0-40326c2679ba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Throughout the 1950s and 1970s, geography itself became focused on spatial analysis, quantitative measurements and the use of the scientific method.', FALSE, 1, NULL, NULL),
  ('25c64471-91e8-54cb-851f-bb27cb7aa1f7'::uuid, 'f62b5a4c-eb60-5b6e-99c0-40326c2679ba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'At the same time, urban geographers began using quantitative information like census data to compare different urban areas.', FALSE, 2, NULL, NULL),
  ('8af19dbe-fe14-5512-b066-64949ed3f7c9'::uuid, 'f62b5a4c-eb60-5b6e-99c0-40326c2679ba'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Using this data allowed them to do comparative studies of different cities and develop computer-based analysis out of those studies.', FALSE, 3, NULL, NULL),
