  ('b6284cee-f286-5bb3-92e2-a3b9a6124bc7'::uuid, 'f67e6533-e20d-5943-8756-27fd5823893b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'For this reason, the primary meaning of art was, for centuries, defined as the representation or replication of something that is beautiful or meaningful.', FALSE, 0, NULL, NULL),
