  ('d434d2f5-720d-579c-a0be-9deb55f11adf'::uuid, 'f6c7c197-fc60-58bd-8583-91a62ab5595f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Somewhere in your house is a box or drawer full of videotapes: aging home movies full of birthdays, holiday gatherings, and other special family moments.', FALSE, 0, NULL, NULL),
  ('e0c47469-6f0e-5cd9-a49f-17aa1e3e7ad7'::uuid, 'f6c7c197-fc60-58bd-8583-91a62ab5595f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'You haven''t watched the movies in years but, unfortunately, the years are still taking their toll.', FALSE, 1, NULL, NULL),
  ('05ddb272-8d4b-533c-a5bd-f40cf25ba36a'::uuid, 'f6c7c197-fc60-58bd-8583-91a62ab5595f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Heat, humidity and improper storage cause videotapes to deteriorate, decaying the magnetic particles that represent your precious family memories.', FALSE, 2, NULL, NULL),
  ('01d41c18-d1ba-5c2d-a91f-b3ecf2e2f499'::uuid, 'f6c7c197-fc60-58bd-8583-91a62ab5595f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'By converting those old tapes to digital form, you can effectively stop the deterioration in its tracks.', FALSE, 3, NULL, NULL),
  ('47c79826-619f-51dc-9ffd-a7be6941acce'::uuid, 'f6c7c197-fc60-58bd-8583-91a62ab5595f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It also allows you to use your computer to edit out the boring moments and add music or narration.', FALSE, 4, NULL, NULL),
