  ('ab56cb55-379e-5884-bf24-a57476c987b7'::uuid, 'f6f96a0e-e15a-59c0-9a4d-3106fd03a5db'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Many think the best way to make foreigners understand is to be chatty and informal.', FALSE, 1, NULL, NULL),
