  ('7e66bcad-3099-525d-80d2-13e847648660'::uuid, 'f856e2c5-45ce-5eb7-ab98-6719ea70314d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Named Quisisana, this high-tech eatery established itself in other northern European cities.', FALSE, 1, NULL, NULL),
  ('c1f7affc-5a49-52d0-9718-8141eee9f0a1'::uuid, 'f856e2c5-45ce-5eb7-ab98-6719ea70314d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Quisisana soon licensed its technology to Joseph Horn, who opened the first American automat in Philadelphia in 1902.', FALSE, 2, NULL, NULL),
  ('a0a68ea8-7cde-5835-bcd8-49bd3ba94a6f'::uuid, 'f856e2c5-45ce-5eb7-ab98-6719ea70314d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The automat is often considered to be an exclusively American phenomenon.', FALSE, 3, NULL, NULL),
  ('cd5fcd5d-58b1-5f81-b326-7977fc137956'::uuid, 'f8608d7b-6c19-5357-8e32-8a8d47d373db'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, their influence can be controversial, as they are sometimes accused of being out of touch with the average person''s reality.', FALSE, 0, NULL, NULL),
  ('a037890c-dd9f-51b4-959f-7cceac61e465'::uuid, 'f8608d7b-6c19-5357-8e32-8a8d47d373db'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Celebrities often influence public opinion through their actions and statements.', FALSE, 1, NULL, NULL),
  ('4d848a85-a4eb-515f-a95d-8c2648aae418'::uuid, 'f8608d7b-6c19-5357-8e32-8a8d47d373db'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They have a wide platform, thanks to their fame and social media presence.', FALSE, 2, NULL, NULL),
