  ('a30fa799-ae51-596b-910a-13d70cdbf8cd'::uuid, 'fa7ba530-e632-5bbf-9c06-0a99bf085b27'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Scientists have known for over a decade that the West Antarctic Ice Sheet has been losing mass and contributing to sea level rise.', FALSE, 0, NULL, NULL),
  ('087737d7-bfa6-5188-a8ab-08a8ecd77ad7'::uuid, 'fa7ba530-e632-5bbf-9c06-0a99bf085b27'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'A study led by a group of NASA scientists, that was published in 2015, suggested that this part of Antarctica was gaining so much mass that it compensated for the losses in the west.', FALSE, 1, NULL, NULL),
  ('7ade6f50-0577-555c-9516-f9969a226baa'::uuid, 'fa7ba530-e632-5bbf-9c06-0a99bf085b27'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Its eastern neighbor is, however, ten times larger and has the potential to raise the global sea level by some 50 meters.', FALSE, 2, NULL, NULL),
  ('ac8b4193-6118-5852-851d-2d875f79538f'::uuid, 'fa7ba530-e632-5bbf-9c06-0a99bf085b27'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Despite its huge size and importance, conflicting results have been published on the recent behavior of the East Antarctic Ice Sheet.', FALSE, 3, NULL, NULL),
  ('665729da-fe4e-583b-9887-2a35193e373f'::uuid, 'fa8100a0-a5e8-5369-9f17-e624a5a7757f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They drew on the theories of Charles Darwin, attempting to apply his concept of evolution to human culture.', FALSE, 0, NULL, NULL),
  ('d9be5cd9-26e3-5966-9239-20ecbe85f75d'::uuid, 'fa8100a0-a5e8-5369-9f17-e624a5a7757f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This was because they based their ideas on data collected by others and did not personally engage first-hand with the groups they claimed to study.', FALSE, 1, NULL, NULL),
  ('99b775ff-c841-5b90-9576-877cd998aed1'::uuid, 'fa8100a0-a5e8-5369-9f17-e624a5a7757f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Cultural anthropology’s roots date back to the 1800s, when early scholars like Lewis Henry Morgan and Edward Tylor became interested in the comparative study of cultural systems.', FALSE, 2, NULL, NULL),
  ('aaed5383-4c25-5773-aa56-5ee9f9d88c3a'::uuid, 'fa8100a0-a5e8-5369-9f17-e624a5a7757f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They were later dismissed as so-called ‘armchair anthropologists’.', FALSE, 3, NULL, NULL),
