  ('9ee3873f-3af5-59f3-9dc3-647c5340cbdf'::uuid, 'feac4317-9736-59c9-bb20-7664121c4c68'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The way we work has undergone a significant shift in recent years.', FALSE, 0, NULL, NULL),
  ('5f175b64-057d-510c-9fb0-07c8f7c455cf'::uuid, 'feac4317-9736-59c9-bb20-7664121c4c68'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Technology has played a key role in enabling this change, with advancements in communication tools and collaboration platforms.', FALSE, 1, NULL, NULL),
  ('41d8bc29-f7ed-53ed-8fe3-0329586440f1'::uuid, 'feac4317-9736-59c9-bb20-7664121c4c68'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This transformation has led to an increase in the demand for remote work and flexible work arrangements.', FALSE, 2, NULL, NULL),
  ('bb028988-6271-51ed-a638-5b4417e7e1c0'::uuid, 'feac4317-9736-59c9-bb20-7664121c4c68'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As a result, many companies are now offering their employees the option to work from home or choose flexible hours.', FALSE, 3, NULL, NULL),
  ('2ffca5cb-0397-5212-a5e6-95f8d262d453'::uuid, 'feb5b32c-6048-5e87-ac9d-e7f82269532f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'She doesn’t have many friends in the city.', FALSE, 0, NULL, NULL),
  ('9b3078ff-cbab-544e-8f1f-bbfda8f154e2'::uuid, 'feb5b32c-6048-5e87-ac9d-e7f82269532f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Her friends there are so rich that she cannot pay the bill.', FALSE, 1, NULL, NULL),
  ('ba5ffe26-488e-5098-8edb-eacd55d714c3'::uuid, 'feb5b32c-6048-5e87-ac9d-e7f82269532f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'People there always avoid talking about the issue.', TRUE, 2, NULL, NULL),
  ('ff151930-b019-5f2b-8d69-6510c259656c'::uuid, 'feb5b32c-6048-5e87-ac9d-e7f82269532f'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'City life there are so hectic, leaving her no time to consider the problem.', FALSE, 3, NULL, NULL),
