  ('bc9a48f3-378a-57dc-8301-7937ea6955c9'::uuid, 'fef1a6af-5271-5340-a91e-10e2abde1248'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'As a result, many people find it difficult to strike a healthy balance between work and personal life.', FALSE, 0, NULL, NULL),
